export const BHAVAPRAKASHA_DATA = [{"sthana":"Пурвакханда","number":1,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть I, пракарана 1"},{"type":"verse","number":"1","sanskrit":"श्रीमद्भावमिश्रप्रणीतः भाव प्रकाशः पूर्व खण्डम् गजमुखममरप्रवरं सिद्धिकरं विघ्नहर्तारम् गुरुमवगमनयनप्रदमिष्टकरीमिष्टदेवतां वन्दे","text":"śrīmadbhāvamiśrapraṇītaḥ bhāva prakāśaḥ pūrva khaṇḍam gajamukhamamarapravaraṃ siddhikaraṃ vighnahartāram gurumavagamanayanapradamiṣṭakarīmiṣṭadevatāṃ vande"},{"type":"verse","number":"2","sanskrit":"आयुर्वेदागमनं क्रमेण येनाभवद्भूमौ प्रथमं लिखामि तमहं नानातन्त्राणि संदृश्य","text":"āyurvedāgamanaṃ krameṇa yenābhavadbhūmau prathamaṃ likhāmi tamahaṃ nānātantrāṇi saṃdṛśya"},{"type":"verse","number":"3","sanskrit":"आयुर्हिताहितं व्याधेर्निदानं शमनं तथा विद्यते यत्र विद्वद्भिः स आयुर्वेद उच्यते","text":"āyurhitāhitaṃ vyādhernidānaṃ śamanaṃ tathā vidyate yatra vidvadbhiḥ sa āyurveda ucyate"},{"type":"verse","number":"4","sanskrit":"अनेन पुरुषो यस्मादायुर्विन्दति वेत्ति च तस्मान्मुनिवरैरेष आयुर्वेद इति स्मृतः","text":"anena puruṣo yasmādāyurvindati vetti ca tasmānmunivaraireṣa āyurveda iti smṛtaḥ"},{"type":"verse","number":"5","sanskrit":"विधाताऽथर्वसर्वस्वमायुर्वेदं प्रकाशयन् स्वनाम्ना संहितां चक्रे लक्षश्लोकमयीमृजुम्","text":"vidhātā'tharvasarvasvamāyurvedaṃ prakāśayan svanāmnā saṃhitāṃ cakre lakṣaślokamayīmṛjum"},{"type":"verse","number":"6","sanskrit":"ततः प्रजापतिं दक्षं दक्षं सकलकर्मसु विधिर्धीनीरधिः साङ्गमायुर्वेदमुपादिशत्","text":"tataḥ prajāpatiṃ dakṣaṃ dakṣaṃ sakalakarmasu vidhirdhīnīradhiḥ sāṅgamāyurvedamupādiśat"},{"type":"verse","number":"7","sanskrit":"अथ दक्षः क्रियादक्षः स्वर्वैद्यौ वेदमायुषः वेदयामास विद्वांसौ सूर्यांशौ सुरसत्तमौ","text":"atha dakṣaḥ kriyādakṣaḥ svarvaidyau vedamāyuṣaḥ vedayāmāsa vidvāṃsau sūryāṃśau surasattamau"},{"type":"verse","number":"8","sanskrit":"दक्षादधीत्य दस्रौ वितनुतः संहितां स्वीयाम् सकलचिकित्सकलोकप्रतिपत्तिविवृद्धये धन्याम्","text":"dakṣādadhītya dasrau vitanutaḥ saṃhitāṃ svīyām sakalacikitsakalokapratipattivivṛddhaye dhanyām"},{"type":"verse","number":"9","sanskrit":"स्वयम्भुवः शिरश्छिन्नं भैरवेण रुषाऽथ तत् अश्विभ्यां संहितं तस्मात्तौ जातौ यज्ञभागिनौ","text":"svayambhuvaḥ śiraśchinnaṃ bhairaveṇa ruṣā'tha tat aśvibhyāṃ saṃhitaṃ tasmāttau jātau yajñabhāginau"},{"type":"verse","number":"10","sanskrit":"देवासुररणे देवा दैत्यैर्ये सक्षताः कृताः अक्षतास्ते कृताः सद्यो दस्राभ्यामद्भुतं महत्","text":"devāsuraraṇe devā daityairye sakṣatāḥ kṛtāḥ akṣatāste kṛtāḥ sadyo dasrābhyāmadbhutaṃ mahat"},{"type":"verse","number":"11","sanskrit":"वज्रिणोऽभूद् भुजस्तम्भः स दस्राभ्यां चिकित्सितः सोमान्निपतितश्चन्द्र स्ताभ्यामेव सुखी कृतः","text":"vajriṇo'bhūd bhujastambhaḥ sa dasrābhyāṃ cikitsitaḥ somānnipatitaścandra stābhyāmeva sukhī kṛtaḥ"},{"type":"verse","number":"12","sanskrit":"विशीर्णा दशनाः पूष्णो नेत्रे नष्टे भगस्य च शशिनो राजयक्ष्माऽभूदश्विभ्यां ते चिकित्सिताः","text":"viśīrṇā daśanāḥ pūṣṇo netre naṣṭe bhagasya ca śaśino rājayakṣmā'bhūdaśvibhyāṃ te cikitsitāḥ"},{"type":"verse","number":"13","sanskrit":"भार्गवश्च्यवनः कामी वृद्धः सन् विकृतिं गतः वीर्यवर्णस्वरोपेतः कृतोऽश्विभ्यां पुनर्युवा","text":"bhārgavaścyavanaḥ kāmī vṛddhaḥ san vikṛtiṃ gataḥ vīryavarṇasvaropetaḥ kṛto'śvibhyāṃ punaryuvā"},{"type":"verse","number":"14","sanskrit":"एतैश्चान्यैश्च बहुभिः कर्मभिर्भिषजां वरौ बभूवतुर्भृशं पूज्याविन्द्रा दीनां दिवौकसाम्","text":"etaiścānyaiśca bahubhiḥ karmabhirbhiṣajāṃ varau babhūvaturbhṛśaṃ pūjyāvindrā dīnāṃ divaukasām"},{"type":"verse","number":"15","sanskrit":"संदृश्य दस्रयोरिन्द्रः कर्माण्येतानि यत्नवान् आयुर्वेदं निरुद्वेगं तौ ययाचे शचीपतिः","text":"saṃdṛśya dasrayorindraḥ karmāṇyetāni yatnavān āyurvedaṃ nirudvegaṃ tau yayāce śacīpatiḥ"},{"type":"verse","number":"16","sanskrit":"नासत्यौ सत्यसन्धेन शक्रेण किल याचितौ आयुर्वेदं यथाऽधीतं ददतुः शतमन्यवे","text":"nāsatyau satyasandhena śakreṇa kila yācitau āyurvedaṃ yathā'dhītaṃ dadatuḥ śatamanyave"},{"type":"verse","number":"17","sanskrit":"नासत्याभ्यामधीत्यैव आयुर्वेदं शतक्रतुः अध्यापयामास बहूनात्रेयप्रमुखान्मुनीन्","text":"nāsatyābhyāmadhītyaiva āyurvedaṃ śatakratuḥ adhyāpayāmāsa bahūnātreyapramukhānmunīn"},{"type":"verse","number":"18","sanskrit":"एकदा जगदालोक्य गदाकुलमितस्ततः चिन्तयामास भगवानात्रेयो मुनिपुङ्गवः","text":"ekadā jagadālokya gadākulamitastataḥ cintayāmāsa bhagavānātreyo munipuṅgavaḥ"},{"type":"verse","number":"19","sanskrit":"किं करोमि क्व गच्छामि कथं लोका निरामयाः भवन्ति सामयानेतान्न शक्नोमि निरीक्षितुम्","text":"kiṃ karomi kva gacchāmi kathaṃ lokā nirāmayāḥ bhavanti sāmayānetānna śaknomi nirīkṣitum"},{"type":"verse","number":"20","sanskrit":"दयालुरहमत्यर्थं स्वभावो दुरतिक्रमः एतेषां दुःखतो दुःखं ममापि हृदयेऽधिकम्","text":"dayālurahamatyarthaṃ svabhāvo duratikramaḥ eteṣāṃ duḥkhato duḥkhaṃ mamāpi hṛdaye'dhikam"},{"type":"verse","number":"21","sanskrit":"आयुर्वेदं पठिष्यामि नैरुज्याय शरीरिणाम् इति निश्चित्य गतवानात्रेयस्त्रिदशालयम्","text":"āyurvedaṃ paṭhiṣyāmi nairujyāya śarīriṇām iti niścitya gatavānātreyastridaśālayam"},{"type":"verse","number":"22","sanskrit":"तत्र मन्दिरमिन्द्र स्य गत्वा शक्रं ददर्श सः सिंहासनसमासीनं स्तूयमानं सुरर्षिभिः","text":"tatra mandiramindra sya gatvā śakraṃ dadarśa saḥ siṃhāsanasamāsīnaṃ stūyamānaṃ surarṣibhiḥ"},{"type":"verse","number":"23","sanskrit":"भासयन्तं दिशो भासा भास्करप्रतिमं त्विषा आयुर्वेदमहाचार्यं शिरोधार्यं दिवौकसाम्","text":"bhāsayantaṃ diśo bhāsā bhāskarapratimaṃ tviṣā āyurvedamahācāryaṃ śirodhāryaṃ divaukasām"},{"type":"verse","number":"24","sanskrit":"शक्रस्तु तं निरीक्ष्यैवं त्यक्तसिंहासनः स्थितः तमग्रे पूजयामास भृशं भूरितपःकृशम्","text":"śakrastu taṃ nirīkṣyaivaṃ tyaktasiṃhāsanaḥ sthitaḥ tamagre pūjayāmāsa bhṛśaṃ bhūritapaḥkṛśam"},{"type":"verse","number":"25","sanskrit":"कुशलं परिपप्रच्छ तथागमनकारणम् स मुनिर्वक्तुमारेभे निजागमनकारणम्","text":"kuśalaṃ paripapraccha tathāgamanakāraṇam sa munirvaktumārebhe nijāgamanakāraṇam"},{"type":"verse","number":"26","sanskrit":"देवराज न जानासि दिव एव यतो भवान् विधात्रा विहितो यत्नात्त्रिलोकीलोकपालकः","text":"devarāja na jānāsi diva eva yato bhavān vidhātrā vihito yatnāttrilokīlokapālakaḥ"},{"type":"verse","number":"27","sanskrit":"व्याधिभिर्व्यथिता लोकाः शोकाकुलितचेतसः भूतले सन्ति सन्तापं तेषां हन्तुं कृपां कुरु","text":"vyādhibhirvyathitā lokāḥ śokākulitacetasaḥ bhūtale santi santāpaṃ teṣāṃ hantuṃ kṛpāṃ kuru"},{"type":"verse","number":"28","sanskrit":"आयुर्वेदोपदेशं मे कुरु कारुण्यतो नृणाम् तथेत्युक्त्वा सहस्राक्षोऽध्यापयामास तं मुनिम्","text":"āyurvedopadeśaṃ me kuru kāruṇyato nṛṇām tathetyuktvā sahasrākṣo'dhyāpayāmāsa taṃ munim"},{"type":"verse","number":"29","sanskrit":"मुनीन्द्र इन्द्र तः साङ्गमायुर्वेदमधीत्य सः अभिनन्द्य तमाशीर्भिराजगाम पुनर्महीम्","text":"munīndra indra taḥ sāṅgamāyurvedamadhītya saḥ abhinandya tamāśīrbhirājagāma punarmahīm"},{"type":"verse","number":"30","sanskrit":"अथात्रेयो मुनिश्रेष्ठो भगवान्करुणाकरः स्वनाम्ना संहितां चक्रे नरवर्गानुकम्पया","text":"athātreyo muniśreṣṭho bhagavānkaruṇākaraḥ svanāmnā saṃhitāṃ cakre naravargānukampayā"},{"type":"verse","number":"31","sanskrit":"ततोऽग्निवेशं भेडञ्च जातूकर्णं पराशरम् क्षीरपाणिञ्च हारीतमायुर्वेदमपाठयत्","text":"tato'gniveśaṃ bheḍañca jātūkarṇaṃ parāśaram kṣīrapāṇiñca hārītamāyurvedamapāṭhayat"},{"type":"verse","number":"32","sanskrit":"तन्त्रस्य कर्त्ता प्रथममग्निवेशोऽभवत्पुरा ततो भेडादयश्चक्रुः स्वं स्वं तन्त्रं कृतानि च","text":"tantrasya karttā prathamamagniveśo'bhavatpurā tato bheḍādayaścakruḥ svaṃ svaṃ tantraṃ kṛtāni ca"},{"type":"verse","number":"33","sanskrit":"श्रावयामासुरात्रेयं मुनिवृन्देन वन्दितम् श्रुत्वा च तानि तन्त्राणि हृष्टोऽभूदत्रिनन्दनः","text":"śrāvayāmāsurātreyaṃ munivṛndena vanditam śrutvā ca tāni tantrāṇi hṛṣṭo'bhūdatrinandanaḥ"},{"type":"verse","number":"34","sanskrit":"यथावत्सूत्रितं दृष्ट्वा प्रहृष्टा मुनयोऽभवन् दिवि देवर्षयो देवाः श्रुत्वा साध्विति चाब्रुवन्","text":"yathāvatsūtritaṃ dṛṣṭvā prahṛṣṭā munayo'bhavan divi devarṣayo devāḥ śrutvā sādhviti cābruvan"},{"type":"verse","number":"35","sanskrit":"एकदा हिमवत्पार्श्वे दैवादागत्य सङ्गताः मुनयो बहवस्तेषां नामभिः कथयाम्यहम्","text":"ekadā himavatpārśve daivādāgatya saṅgatāḥ munayo bahavasteṣāṃ nāmabhiḥ kathayāmyaham"},{"type":"verse","number":"36","sanskrit":"भरद्वाजो मुनिवरः प्रथमं समुपागतः ततोऽङ्गिरास्ततो गर्गो मरीचिर्भृगुभार्गवौ","text":"bharadvājo munivaraḥ prathamaṃ samupāgataḥ tato'ṅgirāstato gargo marīcirbhṛgubhārgavau"},{"type":"verse","number":"37","sanskrit":"पुलस्त्योऽगस्तिरसितो वसिष्ठः सपराशरः हारीतो गौतमः सांख्यो मैत्रेयश्च्यवनोऽपि च","text":"pulastyo'gastirasito vasiṣṭhaḥ saparāśaraḥ hārīto gautamaḥ sāṃkhyo maitreyaścyavano'pi ca"},{"type":"verse","number":"38","sanskrit":"जमदग्निश्च गार्ग्यश्च कश्यपः काश्यपोऽपि च नारदो वामदेवश्च मार्कण्डेयः कपिञ्जलः","text":"jamadagniśca gārgyaśca kaśyapaḥ kāśyapo'pi ca nārado vāmadevaśca mārkaṇḍeyaḥ kapiñjalaḥ"},{"type":"verse","number":"39","sanskrit":"शाण्डिल्यः सहकौण्डिन्यः शाकुनेयश्चशौनकः आश्वलायनसांकृत्यौ विश्वामित्रः परीक्षकः","text":"śāṇḍilyaḥ sahakauṇḍinyaḥ śākuneyaścaśaunakaḥ āśvalāyanasāṃkṛtyau viśvāmitraḥ parīkṣakaḥ"},{"type":"verse","number":"40","sanskrit":"देवलो गालवो धौम्यः काप्यकात्यायनावुभौ काङ्कायनो वैजपेयः कुशिको बादरायणः","text":"devalo gālavo dhaumyaḥ kāpyakātyāyanāvubhau kāṅkāyano vaijapeyaḥ kuśiko bādarāyaṇaḥ"},{"type":"verse","number":"41","sanskrit":"हिरण्याक्षश्च लौगाक्षिः शरलोमा च गोभिलः वैखानसा वालखिल्यास्तथैवान्ये महर्षयः","text":"hiraṇyākṣaśca laugākṣiḥ śaralomā ca gobhilaḥ vaikhānasā vālakhilyāstathaivānye maharṣayaḥ"},{"type":"verse","number":"42","sanskrit":"ब्रह्मज्ञानस्य निधयो यमस्य नियमस्य च तपसस्तेजसा दीप्ता हूयमाना इवाग्नयः","text":"brahmajñānasya nidhayo yamasya niyamasya ca tapasastejasā dīptā hūyamānā ivāgnayaḥ"},{"type":"verse","number":"43","sanskrit":"सुखोपविष्टास्ते तत्र सर्वे चक्रुः कथामिमाम् धर्मार्थकाममोक्षाणां मूलमुक्तं कलेवरम् तच्च सर्वार्थसंसिद्ध्यै भवेद्यदि निरामयम्","text":"sukhopaviṣṭāste tatra sarve cakruḥ kathāmimām dharmārthakāmamokṣāṇāṃ mūlamuktaṃ kalevaram tacca sarvārthasaṃsiddhyai bhavedyadi nirāmayam"},{"type":"verse","number":"44","sanskrit":"तपः स्वाध्यायधर्माणां ब्रह्मचर्यव्रतायुषाम् हर्त्तारः प्रसृता रोगा यत्र तत्र च सर्वशः","text":"tapaḥ svādhyāyadharmāṇāṃ brahmacaryavratāyuṣām harttāraḥ prasṛtā rogā yatra tatra ca sarvaśaḥ"},{"type":"verse","number":"45","sanskrit":"रोगाः कार्श्यकरा बलक्षयकरा देहस्य चेष्टाहरा दृष्टा इन्द्रि यशक्तिसङ्क्षयकराः सर्वाङ्गपीडाकराः धर्मार्थाखिलकाममुक्तिषु महाविघ्नस्वरूपा बलात् प्राणानाशु हरन्ति सन्ति यदि ते क्षेमं कुतः प्राणिनाम्","text":"rogāḥ kārśyakarā balakṣayakarā dehasya ceṣṭāharā dṛṣṭā indri yaśaktisaṅkṣayakarāḥ sarvāṅgapīḍākarāḥ dharmārthākhilakāmamuktiṣu mahāvighnasvarūpā balāt prāṇānāśu haranti santi yadi te kṣemaṃ kutaḥ prāṇinām"},{"type":"verse","number":"46","sanskrit":"तत्तेषां प्रशमाय कश्चन विधिश्चिन्त्यो भवद्भिर्बुधै र्योग्यैरित्यभिधाय संसदि भरद्वाजं मुनिं तेऽब्रुवन् त्वं योग्यो भगवन् सहस्रनयनं याचस्व लब्धं क्रमा दायुर्वेदमधीत्य यं गदभयान्मुक्ता भवामो वयम्","text":"tatteṣāṃ praśamāya kaścana vidhiścintyo bhavadbhirbudhai ryogyairityabhidhāya saṃsadi bharadvājaṃ muniṃ te'bruvan tvaṃ yogyo bhagavan sahasranayanaṃ yācasva labdhaṃ kramā dāyurvedamadhītya yaṃ gadabhayānmuktā bhavāmo vayam"},{"type":"verse","number":"47","sanskrit":"इत्थं स मुनिभिर्योग्यैः प्रार्थितो विनयान्वितैः भरद्वाजो मुनिश्रेष्ठो जगाम त्रिदशालयम्","text":"itthaṃ sa munibhiryogyaiḥ prārthito vinayānvitaiḥ bharadvājo muniśreṣṭho jagāma tridaśālayam"},{"type":"verse","number":"48","sanskrit":"तत्रेन्द्र भवनं गत्वा सुरर्षिगणमध्यगम् दृष्टवान् वृत्रहन्तारं दीप्यमानमिवानलम्","text":"tatrendra bhavanaṃ gatvā surarṣigaṇamadhyagam dṛṣṭavān vṛtrahantāraṃ dīpyamānamivānalam"},{"type":"verse","number":"49","sanskrit":"दृष्ट्वैव स मुनिं प्राह भगवान् मघवा मुदा धर्मज्ञ स्वागतं तेऽथ मुनिं तं समपूजयत्","text":"dṛṣṭvaiva sa muniṃ prāha bhagavān maghavā mudā dharmajña svāgataṃ te'tha muniṃ taṃ samapūjayat"},{"type":"verse","number":"50","sanskrit":"सोऽभिगम्य जयाशीर्भिरभिनन्द्य सुरेश्वरम् ऋषीणां वचनं सम्यक् श्रावयामास तत्त्वतः","text":"so'bhigamya jayāśīrbhirabhinandya sureśvaram ṛṣīṇāṃ vacanaṃ samyak śrāvayāmāsa tattvataḥ"},{"type":"verse","number":"51","sanskrit":"व्याधयो हि समुत्पन्नाः सर्वप्राणिभयङ्कराः तेषां प्रशमनोपायं यथावद्वक्तुमर्हसि","text":"vyādhayo hi samutpannāḥ sarvaprāṇibhayaṅkarāḥ teṣāṃ praśamanopāyaṃ yathāvadvaktumarhasi"},{"type":"verse","number":"52","sanskrit":"अपाठयन्मुनिं साङ्गमायुर्वेदं शतक्रतुः जीवेद्वर्षसहस्राणि देही नीरुङ् निशम्य यम्","text":"apāṭhayanmuniṃ sāṅgamāyurvedaṃ śatakratuḥ jīvedvarṣasahasrāṇi dehī nīruṅ niśamya yam"},{"type":"verse","number":"53","sanskrit":"सोऽनन्तपारं त्रिस्कन्धमायुर्वेदं महामुनिः यथावदचिरात्सर्वं बुबुधे तन्मना मुनिः","text":"so'nantapāraṃ triskandhamāyurvedaṃ mahāmuniḥ yathāvadacirātsarvaṃ bubudhe tanmanā muniḥ"},{"type":"verse","number":"54","sanskrit":"तेनायुः सुचिरं लेभे भरद्वाजो निरामयम् अन्यानपि मुनींश्चक्रे नीरुजः सुचिरायुषः","text":"tenāyuḥ suciraṃ lebhe bharadvājo nirāmayam anyānapi munīṃścakre nīrujaḥ sucirāyuṣaḥ"},{"type":"verse","number":"55","sanskrit":"तत्तन्त्रजनितज्ञानचक्षुषा ऋषयोऽखिलाः गुणान्द्र व्याणि कर्माणि दृष्ट्वा तद्विधिमाश्रिताः","text":"tattantrajanitajñānacakṣuṣā ṛṣayo'khilāḥ guṇāndra vyāṇi karmāṇi dṛṣṭvā tadvidhimāśritāḥ"},{"type":"verse","number":"56","sanskrit":"आरोग्यं लेभिरे दीर्घमायुश्च सुखसंयुतम् आयुर्वेदोक्तविधिनाऽन्येऽपि स्युर्मुनयो यथा","text":"ārogyaṃ lebhire dīrghamāyuśca sukhasaṃyutam āyurvedoktavidhinā'nye'pi syurmunayo yathā"},{"type":"verse","number":"57","sanskrit":"यदा मत्स्यावतारेण हरिणा वेद उद्धृतः तदा शेषश्च तत्रैव वेदं साङ्गमवाप्तवान्","text":"yadā matsyāvatāreṇa hariṇā veda uddhṛtaḥ tadā śeṣaśca tatraiva vedaṃ sāṅgamavāptavān"},{"type":"verse","number":"58","sanskrit":"अथर्वान्तर्गतं सम्यगायुर्वेदं च लब्धवान् एकदा स महीवृत्तं द्र ष्टुं चर इवागतः","text":"atharvāntargataṃ samyagāyurvedaṃ ca labdhavān ekadā sa mahīvṛttaṃ dra ṣṭuṃ cara ivāgataḥ"},{"type":"verse","number":"59","sanskrit":"तत्रलोकान् गदैर्ग्रस्तान् व्यथया परिपीडितान् स्थलेषु बहुषु व्यग्रान् म्रियमाणांश्च दृष्टवान्","text":"tatralokān gadairgrastān vyathayā paripīḍitān sthaleṣu bahuṣu vyagrān mriyamāṇāṃśca dṛṣṭavān"},{"type":"verse","number":"60","sanskrit":"तान्दृष्ट्वातिदयायुक्तस्तेषां दुःखेन दुःखितः अनन्तश्चिन्तयामास रोगोपशमकारणम्","text":"tāndṛṣṭvātidayāyuktasteṣāṃ duḥkhena duḥkhitaḥ anantaścintayāmāsa rogopaśamakāraṇam"},{"type":"verse","number":"61","sanskrit":"सञ्चिन्त्य स स्वयं तत्र मुनेः पुत्रो बभूव ह प्रसिद्धस्य विशुद्धस्य वेदवेदाङ्गवेदिनः","text":"sañcintya sa svayaṃ tatra muneḥ putro babhūva ha prasiddhasya viśuddhasya vedavedāṅgavedinaḥ"},{"type":"verse","number":"62","sanskrit":"यतश्चर इवायातो न ज्ञातः केनचिद्यतः तस्माच्चरकनाम्नासौ ख्यातश्च क्षितिमण्डले","text":"yataścara ivāyāto na jñātaḥ kenacidyataḥ tasmāccarakanāmnāsau khyātaśca kṣitimaṇḍale"},{"type":"verse","number":"63","sanskrit":"स भाति चरकाचार्यो देवाचार्यो यथा दिवि सहस्रवदनस्यांशो येन ध्वंसो रुजां कृतः","text":"sa bhāti carakācāryo devācāryo yathā divi sahasravadanasyāṃśo yena dhvaṃso rujāṃ kṛtaḥ"},{"type":"verse","number":"64","sanskrit":"आत्रेयस्य मुनेः शिष्या अग्निवेशादयोऽभवन् मुनयो बहवस्तैश्च कृतं तन्त्रं स्वकं स्वकम्","text":"ātreyasya muneḥ śiṣyā agniveśādayo'bhavan munayo bahavastaiśca kṛtaṃ tantraṃ svakaṃ svakam"},{"type":"verse","number":"65","sanskrit":"तेषां तन्त्राणि संस्कृत्य समाहृत्य विपश्चिता चरकेणात्मनो नाम्ना ग्रन्थोऽय चरकः कृतः","text":"teṣāṃ tantrāṇi saṃskṛtya samāhṛtya vipaścitā carakeṇātmano nāmnā grantho'ya carakaḥ kṛtaḥ"},{"type":"verse","number":"66","sanskrit":"एकदा देवराजस्य दृष्टिर्निपतिता भुवि तत्र तेन नरा दृष्टा व्याधिभिर्भृशपीडिताः","text":"ekadā devarājasya dṛṣṭirnipatitā bhuvi tatra tena narā dṛṣṭā vyādhibhirbhṛśapīḍitāḥ"},{"type":"verse","number":"67","sanskrit":"तान्दृष्ट्वा हृदयं तस्य दयया परिपीडितम् दयार्द्र हृदयः शक्रो धन्वन्तरिमुवाच ह","text":"tāndṛṣṭvā hṛdayaṃ tasya dayayā paripīḍitam dayārdra hṛdayaḥ śakro dhanvantarimuvāca ha"},{"type":"verse","number":"68","sanskrit":"धन्वन्तरे सुरश्रेष्ठ भगवन् किञ्चिदुच्यते योग्यो भवसि भूतानामुपकारपरो भव","text":"dhanvantare suraśreṣṭha bhagavan kiñciducyate yogyo bhavasi bhūtānāmupakāraparo bhava"},{"type":"verse","number":"69","sanskrit":"उपकाराय लोकानां केन किं न कृतं पुरा त्रैलोक्याधिपतिर्विष्णुरभून्मत्स्यादिरूपवान्","text":"upakārāya lokānāṃ kena kiṃ na kṛtaṃ purā trailokyādhipatirviṣṇurabhūnmatsyādirūpavān"},{"type":"verse","number":"70","sanskrit":"तस्मात्त्वं पृथिवीं याहि काशीमध्ये नृपो भव प्रतीकाराय रोगाणामायुर्वेदं प्रकाशय","text":"tasmāttvaṃ pṛthivīṃ yāhi kāśīmadhye nṛpo bhava pratīkārāya rogāṇāmāyurvedaṃ prakāśaya"},{"type":"verse","number":"71","sanskrit":"इत्युक्त्वा सुरशार्दूलः सर्वभूतहितेप्सया समस्तमायुषो वेदं धन्वन्तरिमुपादिशत्","text":"ityuktvā suraśārdūlaḥ sarvabhūtahitepsayā samastamāyuṣo vedaṃ dhanvantarimupādiśat"},{"type":"verse","number":"72","sanskrit":"अधीत्य चायुषो वेदमिन्द्रा द्धन्वन्तरिः पुरा आगत्य पृथिवीं काश्यां जातो बाहुजवेश्मनि","text":"adhītya cāyuṣo vedamindrā ddhanvantariḥ purā āgatya pṛthivīṃ kāśyāṃ jāto bāhujaveśmani"},{"type":"verse","number":"73","sanskrit":"नाम्ना तु सोऽभवत्ख्यातो दिवोदास इति क्षितौ बाल एव विरक्तोऽभूच्चचार सुमहत्तपः","text":"nāmnā tu so'bhavatkhyāto divodāsa iti kṣitau bāla eva virakto'bhūccacāra sumahattapaḥ"},{"type":"verse","number":"74","sanskrit":"यत्नेन महता ब्रह्मा तं काश्यामकरोन्नृपम् ततो धन्वन्तरिर्लोकैः काशीराजोऽभिधीयते","text":"yatnena mahatā brahmā taṃ kāśyāmakaronnṛpam tato dhanvantarirlokaiḥ kāśīrājo'bhidhīyate"},{"type":"verse","number":"75","sanskrit":"हिताय देहिनां स्वीया संहिता विहिताऽमुना अथ विद्यार्थिनो लोकान्संहितां तामपाठयत्","text":"hitāya dehināṃ svīyā saṃhitā vihitā'munā atha vidyārthino lokānsaṃhitāṃ tāmapāṭhayat"},{"type":"verse","number":"76","sanskrit":"अथ ज्ञानदृशा विश्वामित्रप्रभृतयोऽविदन् अयं धन्वन्तरिः काश्यां काशिराजोऽयमुच्यते","text":"atha jñānadṛśā viśvāmitraprabhṛtayo'vidan ayaṃ dhanvantariḥ kāśyāṃ kāśirājo'yamucyate"},{"type":"verse","number":"77","sanskrit":"विश्वामित्रो मुनिस्तेषु पुत्रं सुश्रुतमुक्तवान् वत्स वाराणसीं गच्छ त्वं विश्वेश्वरवल्लभाम्","text":"viśvāmitro munisteṣu putraṃ suśrutamuktavān vatsa vārāṇasīṃ gaccha tvaṃ viśveśvaravallabhām"},{"type":"verse","number":"78","sanskrit":"तत्र नाम्ना दिवोदासः काशिराजोऽस्ति बाहुजः स हि धन्वन्तरिः साक्षादायुर्वेदविदां वरः","text":"tatra nāmnā divodāsaḥ kāśirājo'sti bāhujaḥ sa hi dhanvantariḥ sākṣādāyurvedavidāṃ varaḥ"},{"type":"verse","number":"79","sanskrit":"आयुर्वेदं पठस्व त्वं लोकोपकृतिहेतवे सर्वप्राणिदया तीर्थमुपकारो महामखः","text":"āyurvedaṃ paṭhasva tvaṃ lokopakṛtihetave sarvaprāṇidayā tīrthamupakāro mahāmakhaḥ"},{"type":"verse","number":"80","sanskrit":"पितुर्वचनमाकर्ण्य सुश्रुतः काशिकां गतः तेन सार्द्धं समध्येतुं मुनिसूनुशतं ययौ","text":"piturvacanamākarṇya suśrutaḥ kāśikāṃ gataḥ tena sārddhaṃ samadhyetuṃ munisūnuśataṃ yayau"},{"type":"verse","number":"81","sanskrit":"अथ धन्वन्तरिं सर्वे वानप्रस्थाश्रमे स्थितम् भगवन्तं सुरश्रेष्ठं मुनिभिर्बहुभिः स्तुतम्","text":"atha dhanvantariṃ sarve vānaprasthāśrame sthitam bhagavantaṃ suraśreṣṭhaṃ munibhirbahubhiḥ stutam"},{"type":"verse","number":"82","sanskrit":"काशिराजं दिवोदासं तेऽपश्यन्विनयान्विताः स्वागतं च तदा चाह दिवोदासो यशोधनः","text":"kāśirājaṃ divodāsaṃ te'paśyanvinayānvitāḥ svāgataṃ ca tadā cāha divodāso yaśodhanaḥ"},{"type":"verse","number":"83","sanskrit":"कुशलं परिपप्रच्छ तथागमनकारणम् ततस्ते सुश्रुतद्वारा कथयामासुरुत्तरम्","text":"kuśalaṃ paripapraccha tathāgamanakāraṇam tataste suśrutadvārā kathayāmāsuruttaram"},{"type":"verse","number":"84","sanskrit":"भगवन्मानवान्दृष्ट्वा व्याधिभिः परिपीडितान् क्रन्दतो म्रियमाणांश्च जातास्माकं हृदि व्यथा","text":"bhagavanmānavāndṛṣṭvā vyādhibhiḥ paripīḍitān krandato mriyamāṇāṃśca jātāsmākaṃ hṛdi vyathā"},{"type":"verse","number":"85","sanskrit":"आमयानां शमोपायं विज्ञातुं वयमागताः आयुर्वेदं भवानस्मानध्यापयतु यत्नतः","text":"āmayānāṃ śamopāyaṃ vijñātuṃ vayamāgatāḥ āyurvedaṃ bhavānasmānadhyāpayatu yatnataḥ"},{"type":"verse","number":"86","sanskrit":"अङ्गीकृत्य वचस्तेषां नृपतिस्तानुपादिशत् व्याख्यातं तेन ते यत्नाज्जगृहुर्मुनयो मुदा","text":"aṅgīkṛtya vacasteṣāṃ nṛpatistānupādiśat vyākhyātaṃ tena te yatnājjagṛhurmunayo mudā"},{"type":"verse","number":"87","sanskrit":"काशिराजं जयाशीर्भिरभिनन्द्य मुदान्विताः सुश्रुताद्याः सुसिद्धार्था जग्मुर्गेहं स्वकं स्वकम्","text":"kāśirājaṃ jayāśīrbhirabhinandya mudānvitāḥ suśrutādyāḥ susiddhārthā jagmurgehaṃ svakaṃ svakam"},{"type":"verse","number":"88","sanskrit":"प्रथमं सुश्रुतस्तेषु स्वतन्त्रं कृतवान्स्फुटम् सुश्रुतस्य सखायोऽपि पृथक्तन्त्राणि तेनिरे","text":"prathamaṃ suśrutasteṣu svatantraṃ kṛtavānsphuṭam suśrutasya sakhāyo'pi pṛthaktantrāṇi tenire"},{"type":"verse","number":"89","sanskrit":"सुश्रुतेन कृतं तन्त्रं सुश्रुतं बहुभिर्यतः तस्मात्तत्सुश्रुतं नाम्ना विख्यातं क्षितिमण्डले","text":"suśrutena kṛtaṃ tantraṃ suśrutaṃ bahubhiryataḥ tasmāttatsuśrutaṃ nāmnā vikhyātaṃ kṣitimaṇḍale"},{"type":"verse","number":"90","sanskrit":"इति भावप्रकाशे पूर्वखण्डे आयुर्वेदप्रवक्तृप्रादुर्भावप्रकरणं समाप्तम्","text":"iti bhāvaprakāśe pūrvakhaṇḍe āyurvedapravaktṛprādurbhāvaprakaraṇaṃ samāptam"}]},{"sthana":"Пурвакханда","number":2,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть I, пракарана 2"},{"type":"verse","number":"1","sanskrit":"आयुर्वेदाब्धिमध्यादतिमतिमुनयो योगरत्नानि यत्नाल्लब्ध्वा स्वे स्वे निबन्धे दधुरखिलजनव्याधिविध्वंसनाय तत्तद्ग्रन्थाद् गृहीतैः सुवचनमणिभिर्भावमिश्रैश्चिकित्साशास्त्रे जाड्यान्धकारं प्रशमयितुमिमं संविधत्ते प्रकाशम्","text":"āyurvedābdhimadhyādatimatimunayo yogaratnāni yatnāllabdhvā sve sve nibandhe dadhurakhilajanavyādhividhvaṃsanāya tattadgranthād gṛhītaiḥ suvacanamaṇibhirbhāvamiśraiścikitsāśāstre jāḍyāndhakāraṃ praśamayitumimaṃ saṃvidhatte prakāśam"},{"type":"verse","number":"2","sanskrit":"श्रीपतिपदप्रसादादाशीर्भिर्भूमिदेवानाम् भावप्रकाशनाम्ना ग्रन्थोऽयं पठ्यतां सर्वैः","text":"śrīpatipadaprasādādāśīrbhirbhūmidevānām bhāvaprakāśanāmnā grantho'yaṃ paṭhyatāṃ sarvaiḥ"},{"type":"verse","number":"3","sanskrit":"आत्मा ज्योतिश्चिदानन्दरूपो नित्यश्च निःस्पृहः निर्गुणः प्रकृतेर्योगात्सगुणः कुरुते जगत्","text":"ātmā jyotiścidānandarūpo nityaśca niḥspṛhaḥ nirguṇaḥ prakṛteryogātsaguṇaḥ kurute jagat"},{"type":"verse","number":"4","sanskrit":"सत्त्वं रजस्तमश्चेति गुणास्ते प्रकृतेः समाः सा जडापि जगत्कर्त्री परमात्मचिदव्ययात्","text":"sattvaṃ rajastamaśceti guṇāste prakṛteḥ samāḥ sā jaḍāpi jagatkartrī paramātmacidavyayāt"},{"type":"verse","number":"5","sanskrit":"प्रधानं प्रकृतिः शक्तिर्नित्या चाविकृतिस्तथा एतानि तस्या नामानि पुरुषं या समाश्रिता","text":"pradhānaṃ prakṛtiḥ śaktirnityā cāvikṛtistathā etāni tasyā nāmāni puruṣaṃ yā samāśritā"},{"type":"verse","number":"6","sanskrit":"सत्त्वं रजस्तमस्त्रीणि विज्ञेयाः प्रकृतेर्गुणाः तैश्च युक्तस्य चित्तस्य कथयाम्यखिलान् गुणान्","text":"sattvaṃ rajastamastrīṇi vijñeyāḥ prakṛterguṇāḥ taiśca yuktasya cittasya kathayāmyakhilān guṇān"},{"type":"verse","number":"7","sanskrit":"आस्तिक्यं प्रविभज्य भोजनमनुत्तापश्च तथ्यं वचो मेधाबुद्धिधृतिक्षमाश्च करुणा ज्ञानं च निर्दम्भता कर्मानिन्दितमस्पृहं च विनयो धर्मः सदैवादरा देते सत्त्वगुणान्वितस्य मनसो गीता गुणा ज्ञानिभिः","text":"āstikyaṃ pravibhajya bhojanamanuttāpaśca tathyaṃ vaco medhābuddhidhṛtikṣamāśca karuṇā jñānaṃ ca nirdambhatā karmāninditamaspṛhaṃ ca vinayo dharmaḥ sadaivādarā dete sattvaguṇānvitasya manaso gītā guṇā jñānibhiḥ"},{"type":"verse","number":"8","sanskrit":"क्रोधस्ताडनशीलता च बहुलं दुःखं सुखेच्छाऽधिका दम्भः कामुकताप्यलीकवचनं चाधीरताहङ्कृतिः ऐश्वर्यादभिमानितातिशयितानन्दोऽधिकश्चाटनं प्रख्याता हि रजोगुणेन सहितस्यैते गुणाश्चेतसः","text":"krodhastāḍanaśīlatā ca bahulaṃ duḥkhaṃ sukhecchā'dhikā dambhaḥ kāmukatāpyalīkavacanaṃ cādhīratāhaṅkṛtiḥ aiśvaryādabhimānitātiśayitānando'dhikaścāṭanaṃ prakhyātā hi rajoguṇena sahitasyaite guṇāścetasaḥ"},{"type":"verse","number":"9","sanskrit":"नास्तिक्यं सुविषण्णतातिशयितालस्यं च दुष्टा मतिः प्रीतिर्निन्दितकर्मशर्मणि सदा निद्रा लुताहर्निशम् अज्ञानं किल सर्वतोऽपि सततं क्रोधान्धता मूढता प्रख्याता हि तमोगुणेन सहितस्यैते गुणाश्चेतसः","text":"nāstikyaṃ suviṣaṇṇatātiśayitālasyaṃ ca duṣṭā matiḥ prītirninditakarmaśarmaṇi sadā nidrā lutāharniśam ajñānaṃ kila sarvato'pi satataṃ krodhāndhatā mūḍhatā prakhyātā hi tamoguṇena sahitasyaite guṇāścetasaḥ"},{"type":"verse","number":"10","sanskrit":"तत्र प्रभूतसत्त्वस्तु सात्त्विकः पुरुषः स्मृतः राजसस्तामसश्चैव त्रिविधस्तेन मानवः","text":"tatra prabhūtasattvastu sāttvikaḥ puruṣaḥ smṛtaḥ rājasastāmasaścaiva trividhastena mānavaḥ"},{"type":"verse","number":"11","sanskrit":"ततोऽभवन्महत्तत्त्वं बुद्धितत्त्वापराभिधम् त्रिगुणं सत्त्वबहुलं निर्मलं स्फटिकोपमम् चिच्छायाप्राप्तचैतन्यं तदिच्छामयमीरितम्","text":"tato'bhavanmahattattvaṃ buddhitattvāparābhidham triguṇaṃ sattvabahulaṃ nirmalaṃ sphaṭikopamam cicchāyāprāptacaitanyaṃ tadicchāmayamīritam"},{"type":"verse","number":"12","sanskrit":"महतस्त्रिगुणाज्जातोऽहङ्कारस्त्रिगुणान्वितः सात्त्विको राजसश्चापि तामसश्चेति स त्रिधा","text":"mahatastriguṇājjāto'haṅkārastriguṇānvitaḥ sāttviko rājasaścāpi tāmasaśceti sa tridhā"},{"type":"verse","number":"13","sanskrit":"जातानि सात्त्विकात्तस्मादिन्द्रि याणि सराजसात् तानि श्रोत्रं त्वचो नेत्रं रसना नासिका तथा","text":"jātāni sāttvikāttasmādindri yāṇi sarājasāt tāni śrotraṃ tvaco netraṃ rasanā nāsikā tathā"},{"type":"verse","number":"14","sanskrit":"वाग्घस्तचरणोपस्थगुदान्येकादशं मनः पञ्च बुद्धीन्द्रि याण्याहुः प्राक्तनानीतराणि च","text":"vāgghastacaraṇopasthagudānyekādaśaṃ manaḥ pañca buddhīndri yāṇyāhuḥ prāktanānītarāṇi ca"},{"type":"verse","number":"15","sanskrit":"कर्मेन्द्रि याणि पञ्चैव कथयन्ति विपश्चितः","text":"karmendri yāṇi pañcaiva kathayanti vipaścitaḥ"},{"type":"verse","number":"16","sanskrit":"मनो बुद्धीन्द्रि यं विज्ञैः कर्मेन्द्रि यमपि स्मृतम् मनोऽधिष्ठितमेवेदमिन्द्रि यं यत्प्रवर्त्तते","text":"mano buddhīndri yaṃ vijñaiḥ karmendri yamapi smṛtam mano'dhiṣṭhitamevedamindri yaṃ yatpravarttate"},{"type":"verse","number":"17","sanskrit":"शब्दः स्पर्शश्च रूपश्च रसो गन्धो ह्यनुक्रमात् बुद्धीन्द्रि याणां विषयाः समाख्याता महर्षिभिः","text":"śabdaḥ sparśaśca rūpaśca raso gandho hyanukramāt buddhīndri yāṇāṃ viṣayāḥ samākhyātā maharṣibhiḥ"},{"type":"verse","number":"18","sanskrit":"वाच्यं ग्राह्यञ्च गन्तव्यमानन्दं त्याज्यमेव च कर्मेन्द्रि याणां विषया ज्ञातव्य विषयो हृदः","text":"vācyaṃ grāhyañca gantavyamānandaṃ tyājyameva ca karmendri yāṇāṃ viṣayā jñātavya viṣayo hṛdaḥ"},{"type":"verse","number":"19","sanskrit":"तामसादप्यहङ्कारस्तन्मात्राणि सराजसात् पञ्चाल्पसत्त्वसम्बन्धात्तल्लिङ्गानि भवन्ति हि","text":"tāmasādapyahaṅkārastanmātrāṇi sarājasāt pañcālpasattvasambandhāttalliṅgāni bhavanti hi"},{"type":"verse","number":"20","sanskrit":"शब्दतन्मात्रकं स्पर्शतन्मात्रं रूपमात्रकम् रसतन्मात्रकं गन्धतन्मात्रमिति तानि तु","text":"śabdatanmātrakaṃ sparśatanmātraṃ rūpamātrakam rasatanmātrakaṃ gandhatanmātramiti tāni tu"},{"type":"verse","number":"21","sanskrit":"तन्मात्रेभ्यो वियद्वायुर्वह्निर्वारि वसुन्धरा एतानि पञ्च जायन्ते महाभूतानि तत्क्रमात्","text":"tanmātrebhyo viyadvāyurvahnirvāri vasundharā etāni pañca jāyante mahābhūtāni tatkramāt"},{"type":"verse","number":"22","sanskrit":"शब्दः श्रोत्रेन्द्रि यं वापि च्छिद्रा णि च विविक्तता वियतः कथिता एते गुणागुणविचारिभिः","text":"śabdaḥ śrotrendri yaṃ vāpi cchidrā ṇi ca viviktatā viyataḥ kathitā ete guṇāguṇavicāribhiḥ"},{"type":"verse","number":"23","sanskrit":"स्पर्शस्त्वगिन्द्रि यञ्चापि लघुता स्पन्दनं तनोः चेष्टा सर्वशरीरस्य वायोरेते गुणाः स्मृताः","text":"sparśastvagindri yañcāpi laghutā spandanaṃ tanoḥ ceṣṭā sarvaśarīrasya vāyorete guṇāḥ smṛtāḥ"},{"type":"verse","number":"24","sanskrit":"रूपं नेत्रेन्द्रि यं पाकः सन्तापस्तीक्ष्णता तथा वर्णो भ्राजिष्णुताऽमर्षः शौर्यं वह्नेर्गुणा अमी","text":"rūpaṃ netrendri yaṃ pākaḥ santāpastīkṣṇatā tathā varṇo bhrājiṣṇutā'marṣaḥ śauryaṃ vahnerguṇā amī"},{"type":"verse","number":"25","sanskrit":"रसो रसेन्द्रि यं शैत्यं स्नेहश्च गुरुता तथा सर्वद्र वसमूहश्च शुक्रं वारिगुणाः स्मृताः","text":"raso rasendri yaṃ śaityaṃ snehaśca gurutā tathā sarvadra vasamūhaśca śukraṃ vāriguṇāḥ smṛtāḥ"},{"type":"verse","number":"26","sanskrit":"गन्धो घ्राणेन्द्रि यं चापि काठिन्यं गौरवं तथा वसुन्धरागुणा एते गदिता गुणवेदिभिः","text":"gandho ghrāṇendri yaṃ cāpi kāṭhinyaṃ gauravaṃ tathā vasundharāguṇā ete gaditā guṇavedibhiḥ"},{"type":"verse","number":"27","sanskrit":"शब्दः स्पर्शश्च रूपञ्च रसो गन्धश्च तत्क्रमात् तन्मात्राणां विशेषाः स्युः स्थूलभावमुपागताः","text":"śabdaḥ sparśaśca rūpañca raso gandhaśca tatkramāt tanmātrāṇāṃ viśeṣāḥ syuḥ sthūlabhāvamupāgatāḥ"},{"type":"verse","number":"28","sanskrit":"प्रकृतेः कारणायोगान्मता प्रकृतिरेव सा महत्तत्त्वादयः सप्त शक्तेर्विकृतयः स्मृताः","text":"prakṛteḥ kāraṇāyogānmatā prakṛtireva sā mahattattvādayaḥ sapta śaktervikṛtayaḥ smṛtāḥ"},{"type":"verse","number":"29","sanskrit":"इन्द्रि याणां च भूतानां कारणत्वान्महर्षिभिः महत्तत्त्वादयः सप्त प्रोक्ताः प्रकृतयोऽपि च","text":"indri yāṇāṃ ca bhūtānāṃ kāraṇatvānmaharṣibhiḥ mahattattvādayaḥ sapta proktāḥ prakṛtayo'pi ca"},{"type":"verse","number":"30","sanskrit":"दशेन्द्रि याणि चित्तञ्च महाभूतानि पञ्च च एतानि सृष्टिं जानद्भिर्विकाराः षोडश स्मृताः","text":"daśendri yāṇi cittañca mahābhūtāni pañca ca etāni sṛṣṭiṃ jānadbhirvikārāḥ ṣoḍaśa smṛtāḥ"},{"type":"verse","number":"31","sanskrit":"एवं चतुर्विंशतिभिस्तत्त्वैः सिद्धे वपुर्गृहे जीवात्मनियतेर्निघ्नो वसति स्वान्तदूतवान्","text":"evaṃ caturviṃśatibhistattvaiḥ siddhe vapurgṛhe jīvātmaniyaternighno vasati svāntadūtavān"},{"type":"verse","number":"32","sanskrit":"स देही कथ्यते पापपुण्यदुःखसुखादिभिः व्याप्तो बद्धश्च मनसा कृत्रिमैः कर्मबन्धनैः","text":"sa dehī kathyate pāpapuṇyaduḥkhasukhādibhiḥ vyāpto baddhaśca manasā kṛtrimaiḥ karmabandhanaiḥ"},{"type":"verse","number":"33","sanskrit":"इच्छाद्वेषसुखासुखानि विषयज्ञानं प्रयत्नो मनः सङ्कल्पश्च विचारणा स्मृतिरथो बुद्धिः कलाविज्ञता प्राणस्योपरियापनं गुदवशाद्वायोरधः प्रेरणं नेत्रोन्मेषनिमेषकृत्यकरणोत्साहाश्च जीवे गुणाः","text":"icchādveṣasukhāsukhāni viṣayajñānaṃ prayatno manaḥ saṅkalpaśca vicāraṇā smṛtiratho buddhiḥ kalāvijñatā prāṇasyopariyāpanaṃ gudavaśādvāyoradhaḥ preraṇaṃ netronmeṣanimeṣakṛtyakaraṇotsāhāśca jīve guṇāḥ"},{"type":"verse","number":"34","sanskrit":"इति श्री मिश्रलटकनतनय श्रीमन्मिश्रभावविरचिते भावप्रकाशे सृष्टिप्रकरणं समाप्तम् २","text":"iti śrī miśralaṭakanatanaya śrīmanmiśrabhāvaviracite bhāvaprakāśe sṛṣṭiprakaraṇaṃ samāptam 2"}]},{"sthana":"Пурвакханда","number":3,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть I, пракарана 3"},{"type":"verse","number":"1","sanskrit":"द्वादशाद्वत्सरादूर्ध्वमापञ्चाशत्समाः स्त्रियः मासि मासि भगद्वारा प्रकृत्यैवार्तवं स्रवेत्","text":"dvādaśādvatsarādūrdhvamāpañcāśatsamāḥ striyaḥ māsi māsi bhagadvārā prakṛtyaivārtavaṃ sravet"},{"type":"verse","number":"2","sanskrit":"आर्तवस्रावदिवसादृतुः षोडश रात्रयः गर्भग्रहणयोग्यस्तु स एव समयः स्मृतः","text":"ārtavasrāvadivasādṛtuḥ ṣoḍaśa rātrayaḥ garbhagrahaṇayogyastu sa eva samayaḥ smṛtaḥ"},{"type":"verse","number":"3","sanskrit":"आर्तवस्रावदिवसादहिंसा ब्रह्मचारिणी शयीत दर्भशय्यायां पश्येदपि पतिं न च","text":"ārtavasrāvadivasādahiṃsā brahmacāriṇī śayīta darbhaśayyāyāṃ paśyedapi patiṃ na ca"},{"type":"verse","number":"4","sanskrit":"करे शरावे पर्णे वा हविष्यं त्र्यहमाहरेत् अश्रुपातं नखच्छेदमभ्यङ्गमनुलेपनम्","text":"kare śarāve parṇe vā haviṣyaṃ tryahamāharet aśrupātaṃ nakhacchedamabhyaṅgamanulepanam"},{"type":"verse","number":"5","sanskrit":"नेत्रयोरञ्जनं स्नानं दिवास्वापं प्रधावनम् अत्युच्चशब्दश्रवणं हसनं बहुभाषणम् आयासं भूमिखननं प्रवातञ्च विवर्जयेत्","text":"netrayorañjanaṃ snānaṃ divāsvāpaṃ pradhāvanam atyuccaśabdaśravaṇaṃ hasanaṃ bahubhāṣaṇam āyāsaṃ bhūmikhananaṃ pravātañca vivarjayet"},{"type":"verse","number":"6","sanskrit":"अज्ञानाद्वा प्रमादाद्वा लोभाद्वा दैवतश्च वा","text":"ajñānādvā pramādādvā lobhādvā daivataśca vā"},{"type":"verse","number":"7","sanskrit":"सा चेत्कुर्यान्निषिद्धानि गर्भो दोषांस्तदाऽप्नुयात् एतस्या रोदनाद्गर्भो भवेद्विकृतलोचनः","text":"sā cetkuryānniṣiddhāni garbho doṣāṃstadā'pnuyāt etasyā rodanādgarbho bhavedvikṛtalocanaḥ"},{"type":"verse","number":"8","sanskrit":"नखच्छेदेन कुनखी कुष्ठी त्वभ्यङ्गतो भवेत् अनुलेपात्तथा स्नानाद् दुःखशीलोऽञ्जनाददृक्","text":"nakhacchedena kunakhī kuṣṭhī tvabhyaṅgato bhavet anulepāttathā snānād duḥkhaśīlo'ñjanādadṛk"},{"type":"verse","number":"9","sanskrit":"स्वापशीलो दिवास्वापाच्चञ्चलः स्यात्प्रधावनात् अत्युच्चशब्दश्रवणाद्बधिरः खलु जायते","text":"svāpaśīlo divāsvāpāccañcalaḥ syātpradhāvanāt atyuccaśabdaśravaṇādbadhiraḥ khalu jāyate"},{"type":"verse","number":"10","sanskrit":"तालुदन्तौष्ठजिह्वासु श्यावो हसनतो भवेत् प्रलापी भूरिकथनादुन्मत्तस्तु परिश्रमात् स्खलते भूमिखननादुन्मत्तो वातसेवनात्","text":"tāludantauṣṭhajihvāsu śyāvo hasanato bhavet pralāpī bhūrikathanādunmattastu pariśramāt skhalate bhūmikhananādunmatto vātasevanāt"},{"type":"verse","number":"11","sanskrit":"पूर्वं पश्येदृतुस्नाता यादृशं नरमङ्गना तादृशं जनयेत्पुत्रं ततः पश्येत्पतिं प्रियम्","text":"pūrvaṃ paśyedṛtusnātā yādṛśaṃ naramaṅganā tādṛśaṃ janayetputraṃ tataḥ paśyetpatiṃ priyam"},{"type":"verse","number":"12","sanskrit":"प्रवहत्सलिले क्षिप्तं द्र व्यं गच्छत्यधो यथा तथा वहति रक्ते तु क्षिप्तं वीर्यमधो व्रजेत्","text":"pravahatsalile kṣiptaṃ dra vyaṃ gacchatyadho yathā tathā vahati rakte tu kṣiptaṃ vīryamadho vrajet"},{"type":"verse","number":"13","sanskrit":"आयुः क्षयभयाद्भर्त्ता प्रथमे दिवसे स्त्रियम् द्वितीयेऽपि दिने रत्यै त्यजेदृतुमतीं तथा","text":"āyuḥ kṣayabhayādbharttā prathame divase striyam dvitīye'pi dine ratyai tyajedṛtumatīṃ tathā"},{"type":"verse","number":"14","sanskrit":"तत्र यश्चाहितो गर्भो जायमानो न जीवति आहितो यस्तृतीयेऽह्नि स्वल्पायुर्विकलाङ्गकः","text":"tatra yaścāhito garbho jāyamāno na jīvati āhito yastṛtīye'hni svalpāyurvikalāṅgakaḥ"},{"type":"verse","number":"15","sanskrit":"अतश्चतुर्थी षष्ठी स्यादष्टमी दशमी तथा द्वादशी वापि या रात्रिस्तस्यां तां विधिना भजेत्","text":"ataścaturthī ṣaṣṭhī syādaṣṭamī daśamī tathā dvādaśī vāpi yā rātristasyāṃ tāṃ vidhinā bhajet"},{"type":"verse","number":"16","sanskrit":"अत्रोत्तरोत्तरं विद्यादायुरारोग्यमेव च प्रजासौभाग्यमैश्वर्यं बलञ्चाभिगमात् फलम्","text":"atrottarottaraṃ vidyādāyurārogyameva ca prajāsaubhāgyamaiśvaryaṃ balañcābhigamāt phalam"},{"type":"verse","number":"17","sanskrit":"मनोभवागारमुखेऽबलानां तिस्रो भवन्ति प्रमदाजनानाम् समीरणा चन्द्र मसी च गौरी विशेषमासामुपवर्णयामि","text":"manobhavāgāramukhe'balānāṃ tisro bhavanti pramadājanānām samīraṇā candra masī ca gaurī viśeṣamāsāmupavarṇayāmi"},{"type":"verse","number":"18","sanskrit":"प्रधानभूता मदनातपत्रे समीरणा नाम विशेषनाडी तस्या मुखे यत् पतितं तु वीर्यं तन्निष्फलं स्यादिति चन्द्र मौलिः","text":"pradhānabhūtā madanātapatre samīraṇā nāma viśeṣanāḍī tasyā mukhe yat patitaṃ tu vīryaṃ tanniṣphalaṃ syāditi candra mauliḥ"},{"type":"verse","number":"19","sanskrit":"या चापरा चान्द्र मसी च नाडी कन्दर्पगेहे भवति प्रधाना सा सुन्दरी योषितमेव सूते साध्या भवेदल्परतोत्सवेषु","text":"yā cāparā cāndra masī ca nāḍī kandarpagehe bhavati pradhānā sā sundarī yoṣitameva sūte sādhyā bhavedalparatotsaveṣu"},{"type":"verse","number":"20","sanskrit":"गौरीति नाडी यदुपस्थगर्भे प्रधानभूता भवति स्वभावात् पुत्रं प्रसूते बहुधाङ्गना सा कष्टोपभोग्या सुरतोपविष्टा","text":"gaurīti nāḍī yadupasthagarbhe pradhānabhūtā bhavati svabhāvāt putraṃ prasūte bahudhāṅganā sā kaṣṭopabhogyā suratopaviṣṭā"},{"type":"verse","number":"21","sanskrit":"युग्मासु पुत्रा जायन्ते स्त्रियोऽयुग्मासु रात्रिषु","text":"yugmāsu putrā jāyante striyo'yugmāsu rātriṣu"},{"type":"verse","number":"22","sanskrit":"स्नातश्चन्दनलिप्ताङ्गः सुगन्धसुमनोर्चितः भुक्तवृष्यः सुवसनः सुवेशः समलङ्कृतः","text":"snātaścandanaliptāṅgaḥ sugandhasumanorcitaḥ bhuktavṛṣyaḥ suvasanaḥ suveśaḥ samalaṅkṛtaḥ"},{"type":"verse","number":"23","sanskrit":"ताम्बूलवदनस्तस्यामनुरक्तोऽधिकस्मरः पुत्रार्थी पुरुषो नारीमुपेयाच्छयने शुभे","text":"tāmbūlavadanastasyāmanurakto'dhikasmaraḥ putrārthī puruṣo nārīmupeyācchayane śubhe"},{"type":"verse","number":"24","sanskrit":"अत्याशितोऽधृतिः क्षुद्वान् सव्यथाङ्गः पिपासितः बालो वृद्धोऽन्यवेगार्त्तस्त्यजेद्रो गी च मैथुनम्","text":"atyāśito'dhṛtiḥ kṣudvān savyathāṅgaḥ pipāsitaḥ bālo vṛddho'nyavegārttastyajedro gī ca maithunam"},{"type":"verse","number":"25","sanskrit":"पुरुषस्य गुणैर्युक्ता विहिता न्यूनभोजना नारी ऋतुमती पुंसा सङ्गच्छेत्तु सुतार्थिनी","text":"puruṣasya guṇairyuktā vihitā nyūnabhojanā nārī ṛtumatī puṃsā saṅgacchettu sutārthinī"},{"type":"verse","number":"26","sanskrit":"रजस्वला व्याधिमती विशेषाद्योनिरोगिणी वयोऽधिका च निष्कामा मलिना गर्भिणी तथा एतासां सङ्गमात्पुंसां वैगुण्यानि भवन्ति हि","text":"rajasvalā vyādhimatī viśeṣādyonirogiṇī vayo'dhikā ca niṣkāmā malinā garbhiṇī tathā etāsāṃ saṅgamātpuṃsāṃ vaiguṇyāni bhavanti hi"},{"type":"verse","number":"27","sanskrit":"कामान्मिथुनसंयोगे शुद्धशोणितशुक्रजः गर्भः सञ्जायते नार्याः स जातो बाल उच्यते","text":"kāmānmithunasaṃyoge śuddhaśoṇitaśukrajaḥ garbhaḥ sañjāyate nāryāḥ sa jāto bāla ucyate"},{"type":"verse","number":"28","sanskrit":"दम्पत्योः कुष्ठबाहुल्याद्दुष्टशोणितशुक्रयोः यदपत्यं तयोर्जातं ज्ञेयं तदपि कुष्ठितमिति","text":"dampatyoḥ kuṣṭhabāhulyādduṣṭaśoṇitaśukrayoḥ yadapatyaṃ tayorjātaṃ jñeyaṃ tadapi kuṣṭhitamiti"},{"type":"verse","number":"29","sanskrit":"ऋतौ स्त्रीपुंसयोर्योगे मकरध्वजवेगतः मेढ्रयोन्यभिसङ्घर्षाच्छरीरोष्मानिलाहतः","text":"ṛtau strīpuṃsayoryoge makaradhvajavegataḥ meḍhrayonyabhisaṅgharṣāccharīroṣmānilāhataḥ"},{"type":"verse","number":"30","sanskrit":"पुंसः सर्वशरीरस्थं रेतो द्रा वयतेऽथ तत् वायुर्मेहनमार्गेण पातयत्यङ्गनाभगे","text":"puṃsaḥ sarvaśarīrasthaṃ reto drā vayate'tha tat vāyurmehanamārgeṇa pātayatyaṅganābhage"},{"type":"verse","number":"31","sanskrit":"तत् संस्रुत्य व्यात्तमुखं याति गर्भाशयं प्रति तत्र शुक्रवदायातेनार्त्तवेन युतं भवेत्","text":"tat saṃsrutya vyāttamukhaṃ yāti garbhāśayaṃ prati tatra śukravadāyātenārttavena yutaṃ bhavet"},{"type":"verse","number":"32","sanskrit":"शङ्खनाभ्याकृतिर्योनिस्त्र्यावर्त्ता सा च कीर्तिता तस्यास्तृतीये त्वावर्त्ते गर्भशय्या प्रतिष्ठिता","text":"śaṅkhanābhyākṛtiryonistryāvarttā sā ca kīrtitā tasyāstṛtīye tvāvartte garbhaśayyā pratiṣṭhitā"},{"type":"verse","number":"33","sanskrit":"यथा रोहितमत्स्यस्य मुखं भवति रूपतः तत्संस्थानां तथा रूपां गर्भशय्यां विदुर्बुधाः","text":"yathā rohitamatsyasya mukhaṃ bhavati rūpataḥ tatsaṃsthānāṃ tathā rūpāṃ garbhaśayyāṃ vidurbudhāḥ"},{"type":"verse","number":"34","sanskrit":"शुक्रार्त्तवसमाश्लेषो यदैव खलु जायते जीवस्तदैव विशति युक्तः शुक्रार्त्तवान्तरः","text":"śukrārttavasamāśleṣo yadaiva khalu jāyate jīvastadaiva viśati yuktaḥ śukrārttavāntaraḥ"},{"type":"verse","number":"35","sanskrit":"सूर्यांशोः सूर्यमणित उभयस्माद्युताद्यथा वह्निः सञ्जायते जीवस्तथा शुक्रार्तवाद्युतात्","text":"sūryāṃśoḥ sūryamaṇita ubhayasmādyutādyathā vahniḥ sañjāyate jīvastathā śukrārtavādyutāt"},{"type":"verse","number":"36","sanskrit":"आत्मानादिरनन्तश्चाव्यक्तो वक्तुं न शक्यते चिदानन्दैकरूपोऽयं मनसापि न गम्यते","text":"ātmānādiranantaścāvyakto vaktuṃ na śakyate cidānandaikarūpo'yaṃ manasāpi na gamyate"},{"type":"verse","number":"37","sanskrit":"एवम्भूतोऽपि जगतो भाविनी बलवत्तया अविद्यास्वीकृते कर्मवशो गर्भे विशत्यसौ","text":"evambhūto'pi jagato bhāvinī balavattayā avidyāsvīkṛte karmavaśo garbhe viśatyasau"},{"type":"verse","number":"38","sanskrit":"स एव वेत्ता रसनो द्र ष्टा घ्राता स्पृशत्यसौ श्रोता वक्ता च कर्त्ता च गन्ता रन्तोत्सृजत्यपि","text":"sa eva vettā rasano dra ṣṭā ghrātā spṛśatyasau śrotā vaktā ca karttā ca gantā rantotsṛjatyapi"},{"type":"verse","number":"39","sanskrit":"दिने व्यतीते नियतं संकुचत्यम्बुजं यथा ऋतौ व्यतीते नार्यास्तु योनिः संव्रियते तथा","text":"dine vyatīte niyataṃ saṃkucatyambujaṃ yathā ṛtau vyatīte nāryāstu yoniḥ saṃvriyate tathā"},{"type":"verse","number":"40","sanskrit":"बीजेऽन्तर्वायुना भिन्ने द्वौ जीवौ कुक्षिमागतौ यमावित्यभिधीयेते धर्मेतरपुरःसरौ","text":"bīje'ntarvāyunā bhinne dvau jīvau kukṣimāgatau yamāvityabhidhīyete dharmetarapuraḥsarau"},{"type":"verse","number":"41","sanskrit":"आधिक्ये रेतसः पुत्रः कन्या स्यादार्त्तवेऽधिके नपुंसकं तयोः साम्ये यथेच्छा पारमेश्वरी","text":"ādhikye retasaḥ putraḥ kanyā syādārttave'dhike napuṃsakaṃ tayoḥ sāmye yathecchā pārameśvarī"},{"type":"verse","number":"42","sanskrit":"एवं तामभिसङ्गम्य पुनर्मासाद्भजेदसौ ४१ शुक्रशोणितयोर्योनेरस्रावोऽथ श्रमोद्भवः सक्थिसादः पिपासा च ग्लानिः स्फूर्त्तिर्भगे भवेत्","text":"evaṃ tāmabhisaṅgamya punarmāsādbhajedasau 41 śukraśoṇitayoryonerasrāvo'tha śramodbhavaḥ sakthisādaḥ pipāsā ca glāniḥ sphūrttirbhage bhavet"},{"type":"verse","number":"43","sanskrit":"स्तनयोर्मुखकार्ष्ण्यं स्याद्रो मराज्युद्गमस्तथा अक्षिपक्ष्माणि चाप्यस्याः संमील्यन्ते विशेषतः","text":"stanayormukhakārṣṇyaṃ syādro marājyudgamastathā akṣipakṣmāṇi cāpyasyāḥ saṃmīlyante viśeṣataḥ"},{"type":"verse","number":"44","sanskrit":"छर्दयेत्पथ्यभुक्चापि गन्धादुद्विजते शुभात् प्रसेकः सदनं चैव गर्भिण्या लिङ्गमुच्यते","text":"chardayetpathyabhukcāpi gandhādudvijate śubhāt prasekaḥ sadanaṃ caiva garbhiṇyā liṅgamucyate"},{"type":"verse","number":"45","sanskrit":"पुत्रगर्भयुतायास्तु नार्या मासि द्वितीयके गर्भो गर्भाशये लक्ष्यः पिण्डाकारोऽपरं शृणु","text":"putragarbhayutāyāstu nāryā māsi dvitīyake garbho garbhāśaye lakṣyaḥ piṇḍākāro'paraṃ śṛṇu"},{"type":"verse","number":"46","sanskrit":"दक्षिणाक्षिमहत्वं स्यात् प्राक्क्षीरं दक्षिणे स्तने दक्षिणोरुः सुपुष्टः स्यात्प्रसन्नमुखवर्णता","text":"dakṣiṇākṣimahatvaṃ syāt prākkṣīraṃ dakṣiṇe stane dakṣiṇoruḥ supuṣṭaḥ syātprasannamukhavarṇatā"},{"type":"verse","number":"47","sanskrit":"पुन्नामधेयद्र व्येषु स्वप्नेष्वपि मनोरथः आम्रादिफलमाप्नोति स्वप्नेषु कमलादि च","text":"punnāmadheyadra vyeṣu svapneṣvapi manorathaḥ āmrādiphalamāpnoti svapneṣu kamalādi ca"},{"type":"verse","number":"48","sanskrit":"कन्या गर्भवती गर्भे पेशी मासि द्वितीयके पुत्रगर्भस्य लिङ्गानि विपरीतानि चेक्षते","text":"kanyā garbhavatī garbhe peśī māsi dvitīyake putragarbhasya liṅgāni viparītāni cekṣate"},{"type":"verse","number":"49","sanskrit":"नपुंसकं यदा गर्भे भवेद् गर्भोऽबुदाकृतिः उन्नते भवतः पार्श्वे पुरस्तादुदरं महत्","text":"napuṃsakaṃ yadā garbhe bhaved garbho'budākṛtiḥ unnate bhavataḥ pārśve purastādudaraṃ mahat"},{"type":"verse","number":"50","sanskrit":"आसेक्यश्च सुगन्धी च कुम्भीकश्चेष्यर्यकस्तथा अमी सशुक्रा बोद्धव्या अशुक्रः षण्ढसंज्ञकः","text":"āsekyaśca sugandhī ca kumbhīkaśceṣyaryakastathā amī saśukrā boddhavyā aśukraḥ ṣaṇḍhasaṃjñakaḥ"},{"type":"verse","number":"51","sanskrit":"पित्रोस्तु स्वल्पवीर्यत्वादासेक्यः पुरुषो भवेत् स शुक्रं प्राश्य लभते ध्वजोन्नतिमसंशयम्","text":"pitrostu svalpavīryatvādāsekyaḥ puruṣo bhavet sa śukraṃ prāśya labhate dhvajonnatimasaṃśayam"},{"type":"verse","number":"52","sanskrit":"यः पूतियोनौ जायेत स हि सौगन्धिको भवेत् स योनिशेफसोर्गन्धमाघ्राय लभते बलम्","text":"yaḥ pūtiyonau jāyeta sa hi saugandhiko bhavet sa yoniśephasorgandhamāghrāya labhate balam"},{"type":"verse","number":"53","sanskrit":"स्वे गुदेऽब्रह्मचर्याद्यः स्त्रीषु पुंवत् प्रवर्त्तते स कुम्भीक इति ज्ञेयो गुदयोनिस्तु स स्मृतः","text":"sve gude'brahmacaryādyaḥ strīṣu puṃvat pravarttate sa kumbhīka iti jñeyo gudayonistu sa smṛtaḥ"},{"type":"verse","number":"54","sanskrit":"दृष्ट्वा व्यवायमन्येषां व्यावाये यः प्रवर्त्तते ईर्ष्यकः स तु विज्ञेयो दृष्टियोनिस्तु स स्मृतः","text":"dṛṣṭvā vyavāyamanyeṣāṃ vyāvāye yaḥ pravarttate īrṣyakaḥ sa tu vijñeyo dṛṣṭiyonistu sa smṛtaḥ"},{"type":"verse","number":"55","sanskrit":"यो भार्यायामृतौ मोहादङ्गनेव प्रवर्त्तते तत्र स्त्रीचेष्टिताकारो जायते षण्ढसंज्ञकः","text":"yo bhāryāyāmṛtau mohādaṅganeva pravarttate tatra strīceṣṭitākāro jāyate ṣaṇḍhasaṃjñakaḥ"},{"type":"verse","number":"56","sanskrit":"ऋतौ ॠतौ पुरुषवत् प्रवर्त्तेताङ्गना यदि तत्र कन्या यदि भवेत् सा भवेन्नरचेष्टिता","text":"ṛtau ṝtau puruṣavat pravarttetāṅganā yadi tatra kanyā yadi bhavet sā bhavennaraceṣṭitā"},{"type":"verse","number":"57","sanskrit":"यदा नार्यावुपेयातां वृषस्यन्त्यौ कथञ्चन मुञ्चन्त्यौ शुक्रमन्योन्यमनस्थिस्तत्र जायते","text":"yadā nāryāvupeyātāṃ vṛṣasyantyau kathañcana muñcantyau śukramanyonyamanasthistatra jāyate"},{"type":"verse","number":"58","sanskrit":"ऋतुस्नाता तु या नारी स्वप्ने मैथुनमाचरेत् आर्त्तवं वायुरादाय कुक्षौ गर्भं करोति हि","text":"ṛtusnātā tu yā nārī svapne maithunamācaret ārttavaṃ vāyurādāya kukṣau garbhaṃ karoti hi"},{"type":"verse","number":"59","sanskrit":"मासि मासिप्रवर्द्धेत स गर्भो गर्भलक्षणः कललं जायते तस्य वर्जितं पैतृकैर्गुणैः","text":"māsi māsipravarddheta sa garbho garbhalakṣaṇaḥ kalalaṃ jāyate tasya varjitaṃ paitṛkairguṇaiḥ"},{"type":"verse","number":"60","sanskrit":"सर्पवृश्चिककूष्माण्डाकृतयो विकृताश्च ये गर्भास्ते योषितस्ताश्च ज्ञेयाः पापकृतो भृशम्","text":"sarpavṛścikakūṣmāṇḍākṛtayo vikṛtāśca ye garbhāste yoṣitastāśca jñeyāḥ pāpakṛto bhṛśam"},{"type":"verse","number":"61","sanskrit":"गर्भो वातप्रकोपेण दोहदे चापमानिते भवेत् कुब्जः कुणिः पङ्गुर्मूको मिन्मिन एव च","text":"garbho vātaprakopeṇa dohade cāpamānite bhavet kubjaḥ kuṇiḥ paṅgurmūko minmina eva ca"},{"type":"verse","number":"62","sanskrit":"आहाराचारचेष्टाभिर्यादृशीभिः समन्वितौ स्त्रीपुंसौ समुपेयातां तयोः पुत्रोऽपि तादृशः","text":"āhārācāraceṣṭābhiryādṛśībhiḥ samanvitau strīpuṃsau samupeyātāṃ tayoḥ putro'pi tādṛśaḥ"},{"type":"verse","number":"63","sanskrit":"गर्भाशयगतं शुक्रमार्त्तवं जीवसंज्ञकः प्रकृतिः सविकारा च तत्सर्वं गर्भसंज्ञकम्","text":"garbhāśayagataṃ śukramārttavaṃ jīvasaṃjñakaḥ prakṛtiḥ savikārā ca tatsarvaṃ garbhasaṃjñakam"},{"type":"verse","number":"64","sanskrit":"कालेन वर्द्धितो गर्भो यद्यङ्गोपाङ्गसंयुतः भवेत्तदा स मुनिभिः शरीरीति निगद्यते","text":"kālena varddhito garbho yadyaṅgopāṅgasaṃyutaḥ bhavettadā sa munibhiḥ śarīrīti nigadyate"},{"type":"verse","number":"65","sanskrit":"तस्य त्वङ्गान्युपाङ्गानि ज्ञात्वा सुश्रुतशास्त्रतः मस्तकादभिधीयन्ते शिष्याः शृणुत यत्नतः","text":"tasya tvaṅgānyupāṅgāni jñātvā suśrutaśāstrataḥ mastakādabhidhīyante śiṣyāḥ śṛṇuta yatnataḥ"},{"type":"verse","number":"66","sanskrit":"आद्यमङ्गं शिरः प्रोक्तं तदुपाङ्गानि कुन्तलाः तस्यान्तर्मस्तुलुङ्गं च ललाटं भ्रूयुगन्तथा","text":"ādyamaṅgaṃ śiraḥ proktaṃ tadupāṅgāni kuntalāḥ tasyāntarmastuluṅgaṃ ca lalāṭaṃ bhrūyugantathā"},{"type":"verse","number":"67","sanskrit":"नेत्रद्वयं तयोरन्तर्वर्त्तेते द्वे कनीनिके दृष्टिद्वयं कृष्णगोलौ श्वेतभागौ च वर्त्मनी","text":"netradvayaṃ tayorantarvarttete dve kanīnike dṛṣṭidvayaṃ kṛṣṇagolau śvetabhāgau ca vartmanī"},{"type":"verse","number":"68","sanskrit":"पक्ष्माण्यपाङ्गौ शङ्खौ च कर्णौ तच्छष्कुलीद्वयम् पालिद्वयं कपोलौ च नासिका च प्रकीर्त्तिता","text":"pakṣmāṇyapāṅgau śaṅkhau ca karṇau tacchaṣkulīdvayam pālidvayaṃ kapolau ca nāsikā ca prakīrttitā"},{"type":"verse","number":"69","sanskrit":"ओष्ठाधरौ च सृक्किण्यौ मुख तालु हनुद्वयम् दन्ताश्च दन्तवेष्टश्च रसना चिबुकङ्गलः","text":"oṣṭhādharau ca sṛkkiṇyau mukha tālu hanudvayam dantāśca dantaveṣṭaśca rasanā cibukaṅgalaḥ"},{"type":"verse","number":"70","sanskrit":"द्वितीयमङ्गं ग्रीवा तु यया मूर्द्धा विधार्यते तृतीयं बाहुयुगलं तदुपाङ्गान्यथ ब्रुवे","text":"dvitīyamaṅgaṃ grīvā tu yayā mūrddhā vidhāryate tṛtīyaṃ bāhuyugalaṃ tadupāṅgānyatha bruve"},{"type":"verse","number":"71","sanskrit":"तत्रोपरि मतौ स्कन्धौ प्रगण्डौ भवतस्त्वधः कफोणियुग्मं तदधं प्रकोष्ठयुगलन्तथा","text":"tatropari matau skandhau pragaṇḍau bhavatastvadhaḥ kaphoṇiyugmaṃ tadadhaṃ prakoṣṭhayugalantathā"},{"type":"verse","number":"72","sanskrit":"मणिबन्धौ तले हस्तौ तयोश्चाङ्गुलयो दश नखाश्च दश ते स्थाप्या दशच्छेद्याःप्रकीर्त्तिताः","text":"maṇibandhau tale hastau tayoścāṅgulayo daśa nakhāśca daśa te sthāpyā daśacchedyāḥprakīrttitāḥ"},{"type":"verse","number":"73","sanskrit":"चतुर्थमङ्गं वक्षस्तु तदुपाङ्गान्यथ ब्रुवे स्तनौ पुंसस्तथा नार्या विशेष उभयोरयम्","text":"caturthamaṅgaṃ vakṣastu tadupāṅgānyatha bruve stanau puṃsastathā nāryā viśeṣa ubhayorayam"},{"type":"verse","number":"74","sanskrit":"यौवनागमने नार्याः पीवरौ भवतः स्तनौ गर्भवत्या प्रसूतायास्तावेव क्षीरपूरितौ","text":"yauvanāgamane nāryāḥ pīvarau bhavataḥ stanau garbhavatyā prasūtāyāstāveva kṣīrapūritau"},{"type":"verse","number":"75","sanskrit":"हृदयं पुण्डरीकेण सदृशं स्यादधोमुखम् जाग्रतस्तद्विकसति स्वपतस्तु निमीलति","text":"hṛdayaṃ puṇḍarīkeṇa sadṛśaṃ syādadhomukham jāgratastadvikasati svapatastu nimīlati"},{"type":"verse","number":"76","sanskrit":"आशयस्तत्तु जीवस्य चेतनास्थानमुत्तमम् अतस्तस्मिंस्तमोव्याप्ते प्राणिनः प्रस्वपन्ति हि","text":"āśayastattu jīvasya cetanāsthānamuttamam atastasmiṃstamovyāpte prāṇinaḥ prasvapanti hi"},{"type":"verse","number":"77","sanskrit":"कक्षयोर्वक्षसः सन्धी जत्रुणी समुदाहृते कक्षे उभे समाख्याते तयोः स्यातां च वङ्क्षणौ","text":"kakṣayorvakṣasaḥ sandhī jatruṇī samudāhṛte kakṣe ubhe samākhyāte tayoḥ syātāṃ ca vaṅkṣaṇau"},{"type":"verse","number":"78","sanskrit":"उदरं पञ्चमञ्चाङ्गं षष्ठं पार्श्वद्वयं मतम् सपृष्ठवंशं पृष्ठं तु समस्तं सप्तमं स्मृतम्","text":"udaraṃ pañcamañcāṅgaṃ ṣaṣṭhaṃ pārśvadvayaṃ matam sapṛṣṭhavaṃśaṃ pṛṣṭhaṃ tu samastaṃ saptamaṃ smṛtam"},{"type":"verse","number":"79","sanskrit":"उपाङ्गानि च कथ्यन्ते तानि जानीहि यत्नतः शोणिताज्जायते प्लीहा वामतो हृदयादधः","text":"upāṅgāni ca kathyante tāni jānīhi yatnataḥ śoṇitājjāyate plīhā vāmato hṛdayādadhaḥ"},{"type":"verse","number":"80","sanskrit":"रक्तवाहिशिराणां स मूलं ख्यातो महर्षिभिः हृदयाद्वामतोऽधश्च फुप्फुसो रक्तफेनजः","text":"raktavāhiśirāṇāṃ sa mūlaṃ khyāto maharṣibhiḥ hṛdayādvāmato'dhaśca phupphuso raktaphenajaḥ"},{"type":"verse","number":"81","sanskrit":"अधो दक्षिणतश्चापि हृदयाद्यकृतः स्थितिः तत्तु रञ्जकपित्तस्य स्थानं शोणितजं मतम्","text":"adho dakṣiṇataścāpi hṛdayādyakṛtaḥ sthitiḥ tattu rañjakapittasya sthānaṃ śoṇitajaṃ matam"},{"type":"verse","number":"82","sanskrit":"अधस्तु दक्षिणे भागे हृदयात् क्लोम तिष्ठति जलवाहिशिरामूलं तृष्णाऽच्छादनकृन्मतम्","text":"adhastu dakṣiṇe bhāge hṛdayāt kloma tiṣṭhati jalavāhiśirāmūlaṃ tṛṣṇā'cchādanakṛnmatam"},{"type":"verse","number":"83","sanskrit":"मेदः शोणितयोः साराद्वृक्कयोर्युगलं भवेत् तौ तु पुष्टिकरौ प्रोक्तौ जठरस्थस्य मेदसः","text":"medaḥ śoṇitayoḥ sārādvṛkkayoryugalaṃ bhavet tau tu puṣṭikarau proktau jaṭharasthasya medasaḥ"},{"type":"verse","number":"84","sanskrit":"अर्द्धव्यामेन हीनानि योषितोऽन्त्राणि निर्दिशेत् उक्ता सार्द्धास्त्रयो व्यामापुंसामन्त्राणि सूरिभिः","text":"arddhavyāmena hīnāni yoṣito'ntrāṇi nirdiśet uktā sārddhāstrayo vyāmāpuṃsāmantrāṇi sūribhiḥ"},{"type":"verse","number":"85","sanskrit":"उन्दुकश्च कटी चापि त्रिकं वस्तिश्च वङ्क्षणौ कण्डराणां प्ररोहःस्यान्मेढ्रोऽध्वा वीर्यमूत्रयोः","text":"undukaśca kaṭī cāpi trikaṃ vastiśca vaṅkṣaṇau kaṇḍarāṇāṃ prarohaḥsyānmeḍhro'dhvā vīryamūtrayoḥ"},{"type":"verse","number":"86","sanskrit":"स एव गर्भस्याधानं कुर्याद्गर्भाशये स्त्रियाः शङ्खनाभ्याकृतिर्योनिस्त्र्यावर्त्ता सा च कीर्त्तिता","text":"sa eva garbhasyādhānaṃ kuryādgarbhāśaye striyāḥ śaṅkhanābhyākṛtiryonistryāvarttā sā ca kīrttitā"},{"type":"verse","number":"87","sanskrit":"तस्यास्तृतीये त्वावर्त्ते गर्भशय्या प्रतिष्ठिता वृषणौ भवतः सारात्कफासृङ्मांसमेदसाम्","text":"tasyāstṛtīye tvāvartte garbhaśayyā pratiṣṭhitā vṛṣaṇau bhavataḥ sārātkaphāsṛṅmāṃsamedasām"},{"type":"verse","number":"88","sanskrit":"वीर्यवाहिशिराधारौ तौ मतौ पौरुषावहौ गुदस्य मानं सर्वस्य सार्द्धं स्याच्चतुरङ्गुलम्","text":"vīryavāhiśirādhārau tau matau pauruṣāvahau gudasya mānaṃ sarvasya sārddhaṃ syāccaturaṅgulam"},{"type":"verse","number":"89","sanskrit":"तत्र स्युर्वलयस्तिस्रः शङ्खावर्तनिभास्तु ताः प्रवाहिणी भवेत्पूर्वा सार्द्धाङ्गुलमिता मता","text":"tatra syurvalayastisraḥ śaṅkhāvartanibhāstu tāḥ pravāhiṇī bhavetpūrvā sārddhāṅgulamitā matā"},{"type":"verse","number":"90","sanskrit":"उत्सर्जनी तु तदधः सा सार्द्धाङ्गुलसम्मिता तस्याधः संवरणी स्यादेकाङ्गुलसमा मता","text":"utsarjanī tu tadadhaḥ sā sārddhāṅgulasammitā tasyādhaḥ saṃvaraṇī syādekāṅgulasamā matā"},{"type":"verse","number":"91","sanskrit":"अर्द्धाङ्गुलप्रमाणं तु बुधैर्गुदमुखं मतम् मलोत्सर्गस्य मार्गोऽय पायुर्देहे विनिर्मितः","text":"arddhāṅgulapramāṇaṃ tu budhairgudamukhaṃ matam malotsargasya mārgo'ya pāyurdehe vinirmitaḥ"},{"type":"verse","number":"92","sanskrit":"पुंसः प्रोथौ स्मृतौ यौ तु तौ नितम्बौ च योषितः तयोः कुकुन्दरे स्यातां सक्थिनोत्वङ्गमष्टमम्","text":"puṃsaḥ prothau smṛtau yau tu tau nitambau ca yoṣitaḥ tayoḥ kukundare syātāṃ sakthinotvaṅgamaṣṭamam"},{"type":"verse","number":"93","sanskrit":"तदुपाङ्गानि च ब्रूमो जानुनी पिण्डकाद्वयम् जंघे द्वे घुटिके पार्ष्णी तले च प्रपदे तथा","text":"tadupāṅgāni ca brūmo jānunī piṇḍakādvayam jaṃghe dve ghuṭike pārṣṇī tale ca prapade tathā"},{"type":"verse","number":"94","sanskrit":"पादावङ्गुलयस्तत्र दश तासां नखा दश अथ दोषाः प्रवक्ष्यन्ते धातवस्तदनन्तरम्","text":"pādāvaṅgulayastatra daśa tāsāṃ nakhā daśa atha doṣāḥ pravakṣyante dhātavastadanantaram"},{"type":"verse","number":"95","sanskrit":"आहारादेर्गतिस्तस्य परिणामश्च वक्ष्यते आर्त्तवं चाथ धातूनां मलास्तदुपधातवः","text":"āhārādergatistasya pariṇāmaśca vakṣyate ārttavaṃ cātha dhātūnāṃ malāstadupadhātavaḥ"},{"type":"verse","number":"96","sanskrit":"आशयाश्च कलाश्चापि मर्माण्यथ च सन्धयः शिराश्च स्नायवश्चापि धमन्यः कण्डरास्तथा","text":"āśayāśca kalāścāpi marmāṇyatha ca sandhayaḥ śirāśca snāyavaścāpi dhamanyaḥ kaṇḍarāstathā"},{"type":"verse","number":"97","sanskrit":"रन्ध्राणि भूरि स्रोतांसि जालैः कूर्च्चाश्च रज्जवः सेवन्यश्चाथ सङ्घाताः सीमान्ताश्च तथा त्वचः","text":"randhrāṇi bhūri srotāṃsi jālaiḥ kūrccāśca rajjavaḥ sevanyaścātha saṅghātāḥ sīmāntāśca tathā tvacaḥ"},{"type":"verse","number":"98","sanskrit":"लोमानि लोमकूपाश्च देह एतन्मयो मतः वायुः पित्तं कफश्चेति त्रयो दोषाः समासतः","text":"lomāni lomakūpāśca deha etanmayo mataḥ vāyuḥ pittaṃ kaphaśceti trayo doṣāḥ samāsataḥ"},{"type":"verse","number":"99","sanskrit":"विकृताविकृता देहं घ्नन्ति ते वर्द्धयन्ति च ते व्यापिनोऽपि हृन्नाभ्योरधो मध्योर्ध्वसंश्रयाः वयोऽहोरात्रिभुक्तानामन्तमध्यादिगाः क्रमात्","text":"vikṛtāvikṛtā dehaṃ ghnanti te varddhayanti ca te vyāpino'pi hṛnnābhyoradho madhyordhvasaṃśrayāḥ vayo'horātribhuktānāmantamadhyādigāḥ kramāt"},{"type":"verse","number":"100","sanskrit":"धातवश्च मलाश्चापि दुष्यन्त्येभिर्यतस्ततः वातपित्तकफा एते त्रयो दोषा इति स्मृताः","text":"dhātavaśca malāścāpi duṣyantyebhiryatastataḥ vātapittakaphā ete trayo doṣā iti smṛtāḥ"},{"type":"verse","number":"101","sanskrit":"ते धातवोऽपि विद्वद्भिर्गदिता देहधारणात्","text":"te dhātavo'pi vidvadbhirgaditā dehadhāraṇāt"},{"type":"verse","number":"102","sanskrit":"दोषधातुमलादीनां नेता शीघ्रः समीरणः रजोगुणमयः सूक्ष्मो रूक्षः शीतो लघुश्चलः","text":"doṣadhātumalādīnāṃ netā śīghraḥ samīraṇaḥ rajoguṇamayaḥ sūkṣmo rūkṣaḥ śīto laghuścalaḥ"},{"type":"verse","number":"103","sanskrit":"उत्साहोच्छ्वासनिःश्वासचेष्टावेगप्रवर्त्तनैः","text":"utsāhocchvāsaniḥśvāsaceṣṭāvegapravarttanaiḥ"},{"type":"verse","number":"104","sanskrit":"सम्यग् गत्या च धातूनामन्द्रि याणाञ्च पाटवैः अनुगृह्णात्यविकृतो हृदयेन्द्रि यचित्तधृक्","text":"samyag gatyā ca dhātūnāmandri yāṇāñca pāṭavaiḥ anugṛhṇātyavikṛto hṛdayendri yacittadhṛk"},{"type":"verse","number":"105","sanskrit":"रजोगुणमयः सूक्ष्मः शीतो रूक्षो लघुश्चलः खरो मृदुर्योगवाही संयोगादुभयार्थकृत्","text":"rajoguṇamayaḥ sūkṣmaḥ śīto rūkṣo laghuścalaḥ kharo mṛduryogavāhī saṃyogādubhayārthakṛt"},{"type":"verse","number":"106","sanskrit":"दाहकृत् तेजसा युक्तः शीतकृत्सोमसंश्रयात् विभागकरणाद्वायुः प्रधानं दोषसंग्रहे","text":"dāhakṛt tejasā yuktaḥ śītakṛtsomasaṃśrayāt vibhāgakaraṇādvāyuḥ pradhānaṃ doṣasaṃgrahe"},{"type":"verse","number":"107","sanskrit":"पक्वाशयकटीसक्थिश्रोत्रास्थिस्पर्शनेन्द्रि यम् स्थानं वातस्य तत्रापि पक्वाधानं विशेषतः","text":"pakvāśayakaṭīsakthiśrotrāsthisparśanendri yam sthānaṃ vātasya tatrāpi pakvādhānaṃ viśeṣataḥ"},{"type":"verse","number":"108","sanskrit":"उदानस्तदनुप्राणः समानोऽपान एव च व्यानश्चैतानि नामानि वायोः स्थानप्रभेदतः","text":"udānastadanuprāṇaḥ samāno'pāna eva ca vyānaścaitāni nāmāni vāyoḥ sthānaprabhedataḥ"},{"type":"verse","number":"109","sanskrit":"कण्ठे हृदि तथाऽधस्तात्कोष्ठवह्नेर्मलाशये सकलेऽपि शरीरेऽसौ क्रमेण पवनो वसेत्","text":"kaṇṭhe hṛdi tathā'dhastātkoṣṭhavahnermalāśaye sakale'pi śarīre'sau krameṇa pavano vaset"},{"type":"verse","number":"110","sanskrit":"उदानो नाम यस्तूर्ध्वमुपैति पवनोत्तमः तेन भाषितगीतादिप्रवृत्तिः कुपितस्तु सः","text":"udāno nāma yastūrdhvamupaiti pavanottamaḥ tena bhāṣitagītādipravṛttiḥ kupitastu saḥ"},{"type":"verse","number":"111","sanskrit":"ऊर्ध्वजत्रुगतान् रोगान्विदधाति विशेषतः यो वायुः प्राणनामाऽसौ मुखं गच्छति देहधृक्","text":"ūrdhvajatrugatān rogānvidadhāti viśeṣataḥ yo vāyuḥ prāṇanāmā'sau mukhaṃ gacchati dehadhṛk"},{"type":"verse","number":"112","sanskrit":"सोऽन्न प्रवेशयत्यन्तः प्राणांश्चाप्यवलम्बते प्रायशः कुरुते दुष्टो हिक्काश्वासादिकान् गदान्","text":"so'nna praveśayatyantaḥ prāṇāṃścāpyavalambate prāyaśaḥ kurute duṣṭo hikkāśvāsādikān gadān"},{"type":"verse","number":"113","sanskrit":"आमपक्वाशयचरः समानो वह्निसङ्गतः सोऽन्न पचति तज्जांश्च विशेषान्विविनक्ति हि","text":"āmapakvāśayacaraḥ samāno vahnisaṅgataḥ so'nna pacati tajjāṃśca viśeṣānvivinakti hi"},{"type":"verse","number":"114","sanskrit":"स दुष्टो वह्निमान्द्यातिसारगुल्मान् करोति हि पक्वाशयालयोऽपानः काले कर्षति चाप्ययम्","text":"sa duṣṭo vahnimāndyātisāragulmān karoti hi pakvāśayālayo'pānaḥ kāle karṣati cāpyayam"},{"type":"verse","number":"115","sanskrit":"समीरणः शकृन्मूत्रशुक्रगर्भार्त्तवान्यधः क्रुद्धस्तु कुरुते रोगान् घोरान्वस्तिगुदाश्रयान्","text":"samīraṇaḥ śakṛnmūtraśukragarbhārttavānyadhaḥ kruddhastu kurute rogān ghorānvastigudāśrayān"},{"type":"verse","number":"116","sanskrit":"शुक्रदोषप्रमेहांश्च व्यानापानप्रकोपजान् कृत्स्नदेहचरो व्यानो रससंवाहनोद्यतः","text":"śukradoṣapramehāṃśca vyānāpānaprakopajān kṛtsnadehacaro vyāno rasasaṃvāhanodyataḥ"},{"type":"verse","number":"117","sanskrit":"स्वेदाऽसृक्स्रावणश्चापि पञ्चधा चेष्टयत्यपि प्रस्पन्दनञ्चोद्वहनं पूरणञ्च विरेचनम्","text":"svedā'sṛksrāvaṇaścāpi pañcadhā ceṣṭayatyapi praspandanañcodvahanaṃ pūraṇañca virecanam"},{"type":"verse","number":"118","sanskrit":"धारणञ्चेति पञ्चैताश्चेष्टाः प्रोक्ताः नभस्वतः गत्यपक्षेपणोत्क्षेपनिमेषोन्मेषणादिकाः प्रायः सर्वाः क्रियास्तस्मिन् प्रतिबद्धाः शरीरिणाम्","text":"dhāraṇañceti pañcaitāśceṣṭāḥ proktāḥ nabhasvataḥ gatyapakṣepaṇotkṣepanimeṣonmeṣaṇādikāḥ prāyaḥ sarvāḥ kriyāstasmin pratibaddhāḥ śarīriṇām"},{"type":"verse","number":"119","sanskrit":"क्रुद्धः सः कुरुते रोगान् प्रायशः सर्वदेहगान् युगपत् कुपिता एते देहं भिन्द्युरसंशयम्","text":"kruddhaḥ saḥ kurute rogān prāyaśaḥ sarvadehagān yugapat kupitā ete dehaṃ bhindyurasaṃśayam"},{"type":"verse","number":"120","sanskrit":"पित्तमुष्णं द्र वं पीतं नीलं सत्त्वगुणोत्तरम् सरं कटु लघु स्निग्धं तीक्ष्णमम्लन्तु पाकतः","text":"pittamuṣṇaṃ dra vaṃ pītaṃ nīlaṃ sattvaguṇottaram saraṃ kaṭu laghu snigdhaṃ tīkṣṇamamlantu pākataḥ"},{"type":"verse","number":"121","sanskrit":"पाचकं रञ्जकञ्चापि साधकालोचके तथा भ्राजकञ्चेति पित्तस्य नामानि स्थानभेदतः","text":"pācakaṃ rañjakañcāpi sādhakālocake tathā bhrājakañceti pittasya nāmāni sthānabhedataḥ"},{"type":"verse","number":"122","sanskrit":"अग्न्याशये यकृत्प्लीह्नोर्हृदये लोचनद्वये त्वचि सर्वशरीरेषु पित्तं निवसति क्रमात्","text":"agnyāśaye yakṛtplīhnorhṛdaye locanadvaye tvaci sarvaśarīreṣu pittaṃ nivasati kramāt"},{"type":"verse","number":"123","sanskrit":"पाचकं पचते भुक्तं शेषाग्निबलवर्द्धनम् रसमूत्रपुरीषाणि विरेचयति नित्यशः","text":"pācakaṃ pacate bhuktaṃ śeṣāgnibalavarddhanam rasamūtrapurīṣāṇi virecayati nityaśaḥ"},{"type":"verse","number":"124","sanskrit":"इत्यलमप्रकृतिचिन्तनेन पुनः प्रकृतमनुसरति रञ्जकं नाम यत्पित्तं तद्र सं शोणितं नयेत् यत्तु साधकसंज्ञं तत्कुर्याद्बुद्धिं धृतिं स्मृतम्","text":"ityalamaprakṛticintanena punaḥ prakṛtamanusarati rañjakaṃ nāma yatpittaṃ tadra saṃ śoṇitaṃ nayet yattu sādhakasaṃjñaṃ tatkuryādbuddhiṃ dhṛtiṃ smṛtam"},{"type":"verse","number":"125","sanskrit":"यदालोचकसंज्ञं तद्रू पग्रहणकारणम् भ्राजकं कान्तिकारि स्याल्लेपाभ्यङ्गादिपाचकम्","text":"yadālocakasaṃjñaṃ tadrū pagrahaṇakāraṇam bhrājakaṃ kāntikāri syāllepābhyaṅgādipācakam"},{"type":"verse","number":"126","sanskrit":"श्लेष्माश्वेतो गुरुः स्निग्धः पिच्छिलः शीतलस्तथा तमोगुणाधिकः स्वादुर्विदग्धो लवणो भवेत्","text":"śleṣmāśveto guruḥ snigdhaḥ picchilaḥ śītalastathā tamoguṇādhikaḥ svādurvidagdho lavaṇo bhavet"},{"type":"verse","number":"127","sanskrit":"कफस्यैतानि नामानि क्लेदनश्चावलम्बनः रसनः स्नेहनश्चापि श्लेषणः स्थानभेदतः","text":"kaphasyaitāni nāmāni kledanaścāvalambanaḥ rasanaḥ snehanaścāpi śleṣaṇaḥ sthānabhedataḥ"},{"type":"verse","number":"128","sanskrit":"आमाशयेऽथ हृदये कण्ठे शिरसि सन्धिषु स्थानेष्वेषु मनुष्याणां श्लेष्मा तिष्ठत्यनुक्रमात्","text":"āmāśaye'tha hṛdaye kaṇṭhe śirasi sandhiṣu sthāneṣveṣu manuṣyāṇāṃ śleṣmā tiṣṭhatyanukramāt"},{"type":"verse","number":"129","sanskrit":"क्लेदनः क्लेदयत्यन्नमात्मशक्त्याऽपराण्यपि अनुगृह्णाति च श्लेष्मस्थानान्युदककर्मणा","text":"kledanaḥ kledayatyannamātmaśaktyā'parāṇyapi anugṛhṇāti ca śleṣmasthānānyudakakarmaṇā"},{"type":"verse","number":"130","sanskrit":"रसयुक्तात्मवीर्येण हृदयस्यावलम्बनम् त्रिकसन्धारणं चापि विदधात्यवलम्बनः","text":"rasayuktātmavīryeṇa hṛdayasyāvalambanam trikasandhāraṇaṃ cāpi vidadhātyavalambanaḥ"},{"type":"verse","number":"131","sanskrit":"उभावपि ततः सौम्यौ तिष्ठतश्चान्तिके यतः यतो रसान्विजानीतो रसनारसनौ समौ","text":"ubhāvapi tataḥ saumyau tiṣṭhataścāntike yataḥ yato rasānvijānīto rasanārasanau samau"},{"type":"verse","number":"132","sanskrit":"स्नेहनः स्नेहदानेन समस्तेन्द्रि यतर्पणः श्लेषणः सर्वसन्धीनां संश्लेषं विदधात्यसौ","text":"snehanaḥ snehadānena samastendri yatarpaṇaḥ śleṣaṇaḥ sarvasandhīnāṃ saṃśleṣaṃ vidadhātyasau"},{"type":"verse","number":"133","sanskrit":"एते सप्त स्वयं स्थित्वा देहं दधति यन्नृणाम् रसासृङ्मांसमेदोऽस्थिमज्जशुक्राणि धातवः","text":"ete sapta svayaṃ sthitvā dehaṃ dadhati yannṛṇām rasāsṛṅmāṃsamedo'sthimajjaśukrāṇi dhātavaḥ"},{"type":"verse","number":"134","sanskrit":"प्रीणनं जीवनं लेपः स्नेहो धारणपूरणे गर्भोत्पादश्च कर्माणि धातूनां कथितानि हि","text":"prīṇanaṃ jīvanaṃ lepaḥ sneho dhāraṇapūraṇe garbhotpādaśca karmāṇi dhātūnāṃ kathitāni hi"},{"type":"verse","number":"135","sanskrit":"गत्यर्थो रस धातुर्यस्ततोऽभवदयं रसः सद्र वं सकलं देहे रसतीति रसः स्मृतः १३४ सम्यक्पक्वस्य भुक्तस्य सारो निगदितो रसः स तु द्र वः सितः शीतः स्वादुः स्निग्धश्चलो भवेत्","text":"gatyartho rasa dhāturyastato'bhavadayaṃ rasaḥ sadra vaṃ sakalaṃ dehe rasatīti rasaḥ smṛtaḥ 134 samyakpakvasya bhuktasya sāro nigadito rasaḥ sa tu dra vaḥ sitaḥ śītaḥ svāduḥ snigdhaścalo bhavet"},{"type":"verse","number":"136","sanskrit":"सर्वदेहचरस्यापि रसस्य हृदयं स्थलम् समानमरुता पूर्वं यदयं हृदये धृतः","text":"sarvadehacarasyāpi rasasya hṛdayaṃ sthalam samānamarutā pūrvaṃ yadayaṃ hṛdaye dhṛtaḥ"},{"type":"verse","number":"137","sanskrit":"आरुह्य धमनीर्गत्वा धातून् सर्वानयं रसः पुष्णाति तदनु स्वीयैर्व्याप्नोति च तनुं गुणैः","text":"āruhya dhamanīrgatvā dhātūn sarvānayaṃ rasaḥ puṣṇāti tadanu svīyairvyāpnoti ca tanuṃ guṇaiḥ"},{"type":"verse","number":"138","sanskrit":"मन्दवह्निविदग्धस्तु कटुर्वाऽम्लो भवेद्र सः स कुर्याद्बहुलान् रोगान् विषकृत्यं करोत्यपि","text":"mandavahnividagdhastu kaṭurvā'mlo bhavedra saḥ sa kuryādbahulān rogān viṣakṛtyaṃ karotyapi"},{"type":"verse","number":"139","sanskrit":"यदा रसो यकृद्याति तत्र रञ्जकपितत्तः रागंपाकं च सम्प्राप्य स भवेद्र क्तसंज्ञकः","text":"yadā raso yakṛdyāti tatra rañjakapitattaḥ rāgaṃpākaṃ ca samprāpya sa bhavedra ktasaṃjñakaḥ"},{"type":"verse","number":"140","sanskrit":"रक्तं सर्वशरीरस्थं जीवस्याधारमुत्तमम् स्निग्धं गुरु चलं स्वादु विदग्धं पित्तवद्भवेत्","text":"raktaṃ sarvaśarīrasthaṃ jīvasyādhāramuttamam snigdhaṃ guru calaṃ svādu vidagdhaṃ pittavadbhavet"},{"type":"verse","number":"141","sanskrit":"यकृत् प्लीहा च रक्तस्य मुख्यस्थानन्तयोः स्थितम् अन्यत्र संस्थितवतां रक्तानां पोषकं भवेत्","text":"yakṛt plīhā ca raktasya mukhyasthānantayoḥ sthitam anyatra saṃsthitavatāṃ raktānāṃ poṣakaṃ bhavet"},{"type":"verse","number":"142","sanskrit":"शोणितं स्वाग्निना पक्वं वायुना च घनीकृतम् तदेव मांसं जानीयात्तस्य भेदानपि ब्रुवे","text":"śoṇitaṃ svāgninā pakvaṃ vāyunā ca ghanīkṛtam tadeva māṃsaṃ jānīyāttasya bhedānapi bruve"},{"type":"verse","number":"143","sanskrit":"यथाऽथमूष्मणा युक्तो वायुः स्रोतांसिदारयेत् अनुप्रविश्य पिशितं पेशीर्विभजते तथा","text":"yathā'thamūṣmaṇā yukto vāyuḥ srotāṃsidārayet anupraviśya piśitaṃ peśīrvibhajate tathā"},{"type":"verse","number":"144","sanskrit":"मांसपेश्यः समाख्याता नृणां पञ्च शतानि हि","text":"māṃsapeśyaḥ samākhyātā nṛṇāṃ pañca śatāni hi"},{"type":"verse","number":"145","sanskrit":"तासां शतानि चत्वारि शाखासु कथितान्यथ कोष्ठे षडुत्तरा षष्टिः कथिता मुनिपुङ्गवैः ग्रीवाया ऊर्ध्वगास्तास्तु चतुस्त्रिंशत् प्रकीर्त्तिताः","text":"tāsāṃ śatāni catvāri śākhāsu kathitānyatha koṣṭhe ṣaḍuttarā ṣaṣṭiḥ kathitā munipuṅgavaiḥ grīvāyā ūrdhvagāstāstu catustriṃśat prakīrttitāḥ"},{"type":"verse","number":"146","sanskrit":"स्त्रीणामपि भवन्त्येताः किन्तु विंशतिरुत्तराः गर्भाशये गर्भमार्गे योनौ च स्तनयोरपि","text":"strīṇāmapi bhavantyetāḥ kintu viṃśatiruttarāḥ garbhāśaye garbhamārge yonau ca stanayorapi"},{"type":"verse","number":"147","sanskrit":"पुंसां पेश्यः पुरस्ताद्याः प्रोक्ता मेहनमुष्कजाः स्त्रीणामावृत्य तिष्ठन्ति फलमन्तर्गतं हि ताः","text":"puṃsāṃ peśyaḥ purastādyāḥ proktā mehanamuṣkajāḥ strīṇāmāvṛtya tiṣṭhanti phalamantargataṃ hi tāḥ"},{"type":"verse","number":"148","sanskrit":"शिरास्नाय्वस्थिपर्वाणि सन्धयश्च शरीरिणाम् पेशीभिःसंवृतान्येव बलवन्ति भवन्ति हि","text":"śirāsnāyvasthiparvāṇi sandhayaśca śarīriṇām peśībhiḥsaṃvṛtānyeva balavanti bhavanti hi"},{"type":"verse","number":"149","sanskrit":"यन्मांसं स्वाग्निना पक्वं तन्मेद इति कथ्यते तदतीव गुरु स्निग्धं बलकार्यतिबृंहणम्","text":"yanmāṃsaṃ svāgninā pakvaṃ tanmeda iti kathyate tadatīva guru snigdhaṃ balakāryatibṛṃhaṇam"},{"type":"verse","number":"150","sanskrit":"मेदो हि सर्वभूतानामुदरेष्वस्थि संस्थितम् अत एवोदरे वृद्धिः प्रायो मेदस्विनो भवेत्","text":"medo hi sarvabhūtānāmudareṣvasthi saṃsthitam ata evodare vṛddhiḥ prāyo medasvino bhavet"},{"type":"verse","number":"151","sanskrit":"मेदो यत् स्वाग्निना पक्वं वायुना चातिशोषितम्","text":"medo yat svāgninā pakvaṃ vāyunā cātiśoṣitam"},{"type":"verse","number":"152","sanskrit":"तदस्थिसंज्ञां लभते स सारः सर्वविग्रहे अभ्यन्तरगतैः सारैर्यथा तिष्ठन्ति भूरुहाः","text":"tadasthisaṃjñāṃ labhate sa sāraḥ sarvavigrahe abhyantaragataiḥ sārairyathā tiṣṭhanti bhūruhāḥ"},{"type":"verse","number":"153","sanskrit":"अस्थिसारैस्तथा देहा ध्रियन्ते देहिनो ध्रुवम् तस्माच्चिरविनष्टेषु त्वङ्मांसेषु शरीरिणाम् अस्थीनि न विनश्यन्ति सारा एतानि सर्वथा","text":"asthisāraistathā dehā dhriyante dehino dhruvam tasmācciravinaṣṭeṣu tvaṅmāṃseṣu śarīriṇām asthīni na vinaśyanti sārā etāni sarvathā"},{"type":"verse","number":"154","sanskrit":"शल्यतन्त्रेऽस्थिखण्डानांशतत्रयमुदाहृतम्","text":"śalyatantre'sthikhaṇḍānāṃśatatrayamudāhṛtam"},{"type":"verse","number":"155","sanskrit":"तान्येवात्र निगद्यन्ते तेषां स्थानानि यानि च सविंशतिशतं त्वस्थ्नां शाखासु कथितं बुधैः","text":"tānyevātra nigadyante teṣāṃ sthānāni yāni ca saviṃśatiśataṃ tvasthnāṃ śākhāsu kathitaṃ budhaiḥ"},{"type":"verse","number":"156","sanskrit":"पार्श्वयोः श्रोणिफलके वक्षःपृष्ठोदरेषु च जानीयाद्भिषगेतेषु शतं सप्तदशोत्तरम् ग्रीवायामूर्ध्वगां विद्यादस्थ्नां षष्टिंत्रिसंयुताम्","text":"pārśvayoḥ śroṇiphalake vakṣaḥpṛṣṭhodareṣu ca jānīyādbhiṣageteṣu śataṃ saptadaśottaram grīvāyāmūrdhvagāṃ vidyādasthnāṃ ṣaṣṭiṃtrisaṃyutām"},{"type":"verse","number":"157","sanskrit":"एतान्यस्थीनि पञ्चविधानि भवन्ति तानि यथा तरुणानि कपालानि रुचकानि भवन्ति हि वलयानीति तानि स्युर्नलकानि च कानि चित्","text":"etānyasthīni pañcavidhāni bhavanti tāni yathā taruṇāni kapālāni rucakāni bhavanti hi valayānīti tāni syurnalakāni ca kāni cit"},{"type":"verse","number":"158","sanskrit":"अक्षिकोश श्रुतिघ्राणग्रीवासु तरुणानि च","text":"akṣikośa śrutighrāṇagrīvāsu taruṇāni ca"},{"type":"verse","number":"159","sanskrit":"शिरः शङ्खकपोलेषु ताल्वं सप्रोथजानुषु कपालानि भवन्त्येषु दन्तेषु रुचकानि च","text":"śiraḥ śaṅkhakapoleṣu tālvaṃ saprothajānuṣu kapālāni bhavantyeṣu danteṣu rucakāni ca"},{"type":"verse","number":"160","sanskrit":"पार्ष्ण्योः पार्श्वयुगे पृष्ठे वक्षोजठरपायुषु पादयोर्वलयानि स्युर्नलकानि ब्रुवेऽधुना","text":"pārṣṇyoḥ pārśvayuge pṛṣṭhe vakṣojaṭharapāyuṣu pādayorvalayāni syurnalakāni bruve'dhunā"},{"type":"verse","number":"161","sanskrit":"हस्ते पादाङ्गुलितले कूर्च्चे च मणिबन्धके बाहूजङ्घाद्वये चापि जानीयान्नलकानि तु","text":"haste pādāṅgulitale kūrcce ca maṇibandhake bāhūjaṅghādvaye cāpi jānīyānnalakāni tu"},{"type":"verse","number":"162","sanskrit":"मांसान्यन्त्राणि बद्धानि शिराभिः स्नायुभिस्तथा अस्थीन्यालम्बनं कृत्वा न दीर्यन्ते पतन्ति च","text":"māṃsānyantrāṇi baddhāni śirābhiḥ snāyubhistathā asthīnyālambanaṃ kṛtvā na dīryante patanti ca"},{"type":"verse","number":"163","sanskrit":"अस्थि यत् स्वाग्निना पक्वं तस्य सारो भवेद्घनः यः स्वेदवत् पृथग्भूतः स मज्जेत्यभिधीयते","text":"asthi yat svāgninā pakvaṃ tasya sāro bhavedghanaḥ yaḥ svedavat pṛthagbhūtaḥ sa majjetyabhidhīyate"},{"type":"verse","number":"164","sanskrit":"स्थूलास्थिषु विशेषेण मज्जा त्वभ्यन्तरे स्थितः","text":"sthūlāsthiṣu viśeṣeṇa majjā tvabhyantare sthitaḥ"},{"type":"verse","number":"165","sanskrit":"रसाद्र क्तं ततो मांसं मांसान्मेदः प्रजायते मेदसोऽस्थि ततो मज्जा मज्ज्ञः शुक्रस्य सम्भवः","text":"rasādra ktaṃ tato māṃsaṃ māṃsānmedaḥ prajāyate medaso'sthi tato majjā majjñaḥ śukrasya sambhavaḥ"},{"type":"verse","number":"166","sanskrit":"यात्यामाशयमाहारः पूर्वं प्राणानिलेरितः माधुर्यं फेनभावं च षड्रसोऽपि लभेत सः","text":"yātyāmāśayamāhāraḥ pūrvaṃ prāṇānileritaḥ mādhuryaṃ phenabhāvaṃ ca ṣaḍraso'pi labheta saḥ"},{"type":"verse","number":"167","sanskrit":"षष्ठी पित्तधरा नाम या कला परिकीर्त्तिता आमपक्वाशयान्तःस्था ग्रहणी साऽभिधीयते","text":"ṣaṣṭhī pittadharā nāma yā kalā parikīrttitā āmapakvāśayāntaḥsthā grahaṇī sā'bhidhīyate"},{"type":"verse","number":"168","sanskrit":"तत्रग्रहण्यामामाशयपक्वाशयमध्यवर्त्तिपाचकाख्यपित्ताधिष्ठानेनाग्निनाऽहारः पच्यते स कटुश्च भवतीत्याहग्रहण्यां पच्यते कोष्ठे वह्निना जायते कटुः इति","text":"tatragrahaṇyāmāmāśayapakvāśayamadhyavarttipācakākhyapittādhiṣṭhānenāgninā'hāraḥ pacyate sa kaṭuśca bhavatītyāhagrahaṇyāṃ pacyate koṣṭhe vahninā jāyate kaṭuḥ iti"},{"type":"verse","number":"169","sanskrit":"भौमाप्याग्नेयवायव्याः पञ्चोष्माणः सनाभसाः पञ्चाहारगुणान् स्वान् स्वान्पार्थिवादीन् पचन्त्यनु","text":"bhaumāpyāgneyavāyavyāḥ pañcoṣmāṇaḥ sanābhasāḥ pañcāhāraguṇān svān svānpārthivādīn pacantyanu"},{"type":"verse","number":"170","sanskrit":"पञ्च भूतात्मके देहे आहारः पाञ्चभौतिकः विपक्वः पञ्चधा सम्यग्गुणान्स्वानभिवर्द्धयेत् इति","text":"pañca bhūtātmake dehe āhāraḥ pāñcabhautikaḥ vipakvaḥ pañcadhā samyagguṇānsvānabhivarddhayet iti"},{"type":"verse","number":"171","sanskrit":"मिष्टः पटुश्च मधुरमम्लोऽम्ल पच्यते रसः कटुतिक्तकषायाणां विपाको जायते कटुः इति","text":"miṣṭaḥ paṭuśca madhuramamlo'mla pacyate rasaḥ kaṭutiktakaṣāyāṇāṃ vipāko jāyate kaṭuḥ iti"},{"type":"verse","number":"172","sanskrit":"आहारस्य रसः सारः सार हीनो मलद्र वः शिराभिस्तज्जलं नीतं वस्तिं मूत्रत्वमाप्नुयात्","text":"āhārasya rasaḥ sāraḥ sāra hīno maladra vaḥ śirābhistajjalaṃ nītaṃ vastiṃ mūtratvamāpnuyāt"},{"type":"verse","number":"173","sanskrit":"शेषं किट्टञ्च यत्तस्य तत्पुरीषं निगद्यते समानवायुना नीतन्तत्तिष्ठति मलाशये","text":"śeṣaṃ kiṭṭañca yattasya tatpurīṣaṃ nigadyate samānavāyunā nītantattiṣṭhati malāśaye"},{"type":"verse","number":"174","sanskrit":"मूत्रञ्चोपस्थमार्गेण पुरीषं गुदमार्गतः अपानवायुना क्षिप्तं बहिर्याति शररीतः","text":"mūtrañcopasthamārgeṇa purīṣaṃ gudamārgataḥ apānavāyunā kṣiptaṃ bahiryāti śararītaḥ"},{"type":"verse","number":"175","sanskrit":"रसस्तु हृदयं याति समानमरुतेरितः स तु व्यानेन विक्षिप्तः सर्वान् धातून् विवर्द्धयेत्","text":"rasastu hṛdayaṃ yāti samānamaruteritaḥ sa tu vyānena vikṣiptaḥ sarvān dhātūn vivarddhayet"},{"type":"verse","number":"176","sanskrit":"केदारेषु यथा कुल्याः पुष्णन्ति विविधौषधीः तथा कलेवरे धातून् सर्वान् वर्द्धयते रसः","text":"kedāreṣu yathā kulyāḥ puṣṇanti vividhauṣadhīḥ tathā kalevare dhātūn sarvān varddhayate rasaḥ"},{"type":"verse","number":"177","sanskrit":"स्थूलः सूक्ष्मस्तन्मलश्च तत्र तत्र त्रिधा रसः स्वं स्थूलॐऽश परं सूक्ष्मस्तन्मलो याति तन्मलम्","text":"sthūlaḥ sūkṣmastanmalaśca tatra tatra tridhā rasaḥ svaṃ sthūlaoṃ'śa paraṃ sūkṣmastanmalo yāti tanmalam"},{"type":"verse","number":"178","sanskrit":"धातौ रसादौ मज्जान्ते प्रत्येकं क्रमतो रसः अहोरात्रात्स्वयं पञ्च सार्द्धदण्डं च तिष्ठति","text":"dhātau rasādau majjānte pratyekaṃ kramato rasaḥ ahorātrātsvayaṃ pañca sārddhadaṇḍaṃ ca tiṣṭhati"},{"type":"verse","number":"179","sanskrit":"स्वाग्निभिः पच्यमानेषु मज्जान्तेषु रसादिषु षट्सु धातुषु जायन्ते मलानि मुनयो जगुः","text":"svāgnibhiḥ pacyamāneṣu majjānteṣu rasādiṣu ṣaṭsu dhātuṣu jāyante malāni munayo jaguḥ"},{"type":"verse","number":"180","sanskrit":"यथा सहस्रधा ध्माते न मलं किल काञ्चने तथा रसे मुहुः पक्वे न मलं शुक्रताङ्गते","text":"yathā sahasradhā dhmāte na malaṃ kila kāñcane tathā rase muhuḥ pakve na malaṃ śukratāṅgate"},{"type":"verse","number":"181","sanskrit":"ओजः सर्वशरीरस्थं स्निग्धं शीतं स्थिरं सितम् सोमात्मकं शरीरस्य बलपुष्टिकरं मतम्","text":"ojaḥ sarvaśarīrasthaṃ snigdhaṃ śītaṃ sthiraṃ sitam somātmakaṃ śarīrasya balapuṣṭikaraṃ matam"},{"type":"verse","number":"182","sanskrit":"गुरु शीतं मृदु स्निग्धं सान्द्रं स्वादु स्थिरं तथा प्रसन्नं पिच्छिलं सूक्ष्ममोजो दशगुणं स्मृतम्","text":"guru śītaṃ mṛdu snigdhaṃ sāndraṃ svādu sthiraṃ tathā prasannaṃ picchilaṃ sūkṣmamojo daśaguṇaṃ smṛtam"},{"type":"verse","number":"183","sanskrit":"अष्टविन्दुप्रमाणं तदीषद्र क्तं सपीतकम् अग्नीषोमात्मकत्वेन द्विरूपं वर्णितन्तु तत्","text":"aṣṭavindupramāṇaṃ tadīṣadra ktaṃ sapītakam agnīṣomātmakatvena dvirūpaṃ varṇitantu tat"},{"type":"verse","number":"184","sanskrit":"ओजश्च तेजो धातूनां शुक्रान्तानां परं स्मृतम् हृदयस्थमपि व्यापि देहस्थितिनिबन्धनम्","text":"ojaśca tejo dhātūnāṃ śukrāntānāṃ paraṃ smṛtam hṛdayasthamapi vyāpi dehasthitinibandhanam"},{"type":"verse","number":"185","sanskrit":"यस्य प्रवृद्धौ देहस्य तुष्टिपुष्टिबलोदयाः यन्नाशे नियतो नाशो यस्मिंस्तिष्ठति जीवनम्","text":"yasya pravṛddhau dehasya tuṣṭipuṣṭibalodayāḥ yannāśe niyato nāśo yasmiṃstiṣṭhati jīvanam"},{"type":"verse","number":"186","sanskrit":"निष्पद्यन्ते यतो भावा विविधा देहसंश्रयाः उत्साहप्रतिभाधैर्यलावण्यसुकुमारताः","text":"niṣpadyante yato bhāvā vividhā dehasaṃśrayāḥ utsāhapratibhādhairyalāvaṇyasukumāratāḥ"},{"type":"verse","number":"187","sanskrit":"ततः स्थूलो भागो रसो मासेन पुंसां शुक्रं स्त्रीणान्त्वार्त्तवं शुक्रञ्च भवति उक्तञ्च सुश्रुते एवं मासेन रसः शुक्रो भवति स्त्रीणामार्त्तवञ्चेति चकारात् स्त्रीणामपि शुक्रं भवति अत एवोक्तं सुश्रुते योषितोऽपि स्रवत्येव शुक्रं पुंसः समागमे तत्र गर्भस्य किञ्चित्तुन करोतीति न चिन्त्यते","text":"tataḥ sthūlo bhāgo raso māsena puṃsāṃ śukraṃ strīṇāntvārttavaṃ śukrañca bhavati uktañca suśrute evaṃ māsena rasaḥ śukro bhavati strīṇāmārttavañceti cakārāt strīṇāmapi śukraṃ bhavati ata evoktaṃ suśrute yoṣito'pi sravatyeva śukraṃ puṃsaḥ samāgame tatra garbhasya kiñcittuna karotīti na cintyate"},{"type":"verse","number":"188","sanskrit":"स्त्रीणां गर्भोपयोगि स्यादार्त्तवं सर्वसम्मतम् तासामपि बलं वर्णं शुक्रं पुष्टिं करोति हि","text":"strīṇāṃ garbhopayogi syādārttavaṃ sarvasammatam tāsāmapi balaṃ varṇaṃ śukraṃ puṣṭiṃ karoti hi"},{"type":"verse","number":"189","sanskrit":"रसाद्र क्तं ततो मांसं मांसान्मेदः प्रजायते मेदसोऽस्थि ततो मज्जा मज्ज्ञः शुक्रस्य सम्भवः","text":"rasādra ktaṃ tato māṃsaṃ māṃsānmedaḥ prajāyate medaso'sthi tato majjā majjñaḥ śukrasya sambhavaḥ"},{"type":"verse","number":"190","sanskrit":"रसः शरीरे शब्दार्च्चिर्जलसन्तानवत् त्रिधा सञ्चरत्यनुरूपोऽय नित्यमेव हि देहिनाम्","text":"rasaḥ śarīre śabdārccirjalasantānavat tridhā sañcaratyanurūpo'ya nityameva hi dehinām"},{"type":"verse","number":"191","sanskrit":"वाजीकरिण्य ओषध्यः स्वप्रभावगुणोच्छ्रयात् विरेचयन्ति ताः शुक्रं विरेकिद्र व्यवन्नृणाम्","text":"vājīkariṇya oṣadhyaḥ svaprabhāvaguṇocchrayāt virecayanti tāḥ śukraṃ virekidra vyavannṛṇām"},{"type":"verse","number":"192","sanskrit":"दुग्धं माषाश्च भल्लात फलमज्जामलानि च जनकानि निगद्यन्ते रेचनानि च रेतसः","text":"dugdhaṃ māṣāśca bhallāta phalamajjāmalāni ca janakāni nigadyante recanāni ca retasaḥ"},{"type":"verse","number":"193","sanskrit":"बालानां शुक्रमस्त्येव किन्तु सौक्ष्म्यान्न दृश्यते पुष्पाणां मुकुले गन्धो यथा सन्नपि नाप्यते","text":"bālānāṃ śukramastyeva kintu saukṣmyānna dṛśyate puṣpāṇāṃ mukule gandho yathā sannapi nāpyate"},{"type":"verse","number":"194","sanskrit":"तेषां तदेव तारुण्ये पुष्टत्वाद्व्यक्तिमेति हि कुसुमानां प्रफुल्लानां गन्धः प्रादुर्भवेद्यथा","text":"teṣāṃ tadeva tāruṇye puṣṭatvādvyaktimeti hi kusumānāṃ praphullānāṃ gandhaḥ prādurbhavedyathā"},{"type":"verse","number":"195","sanskrit":"रोमराज्यादयः पुंसां नारीणामपि यौवने जायतेऽत्र च यो भेदो ज्ञेयो व्याख्यानतः स च","text":"romarājyādayaḥ puṃsāṃ nārīṇāmapi yauvane jāyate'tra ca yo bhedo jñeyo vyākhyānataḥ sa ca"},{"type":"verse","number":"196","sanskrit":"वार्द्धके वर्द्धमानेन वायुना रसशोषणात् न तथा धातुवृद्धिः स्यात्ततस्तत्रानिलं जयेत्","text":"vārddhake varddhamānena vāyunā rasaśoṣaṇāt na tathā dhātuvṛddhiḥ syāttatastatrānilaṃ jayet"},{"type":"verse","number":"197","sanskrit":"शुक्रं सौम्यं सितं स्निग्धं बलपुष्टिकरं स्मृतम् गर्भबीजं वपुःसारो जीवस्याश्रय उत्तमः","text":"śukraṃ saumyaṃ sitaṃ snigdhaṃ balapuṣṭikaraṃ smṛtam garbhabījaṃ vapuḥsāro jīvasyāśraya uttamaḥ"},{"type":"verse","number":"198","sanskrit":"जीवो वसति सर्वस्मिन्देहे तत्र विशेषतः वीर्ये रक्ते मले यस्मिन् क्षीणे याति क्षयं क्षणात्","text":"jīvo vasati sarvasmindehe tatra viśeṣataḥ vīrye rakte male yasmin kṣīṇe yāti kṣayaṃ kṣaṇāt"},{"type":"verse","number":"199","sanskrit":"स्फटिकाभं द्र वं स्निग्धं मधुरं मधुगन्धि च शुक्रमिच्छन्ति केचित्तु तैलक्षौद्र निभञ्च तत्","text":"sphaṭikābhaṃ dra vaṃ snigdhaṃ madhuraṃ madhugandhi ca śukramicchanti kecittu tailakṣaudra nibhañca tat"},{"type":"verse","number":"200","sanskrit":"यथा पयसि सर्पिस्तु गूढश्चेक्षौ रसो यथा एवं हि सकले काये शुक्रं तिष्ठति देहिनाम्","text":"yathā payasi sarpistu gūḍhaścekṣau raso yathā evaṃ hi sakale kāye śukraṃ tiṣṭhati dehinām"},{"type":"verse","number":"201","sanskrit":"द्व्यङ्गुले दक्षिणे पार्श्वे वस्तिद्वारस्य चाप्यधः मूत्रस्रोतःपथाच्छुक्रं पुरुषस्य प्रवर्त्तते","text":"dvyaṅgule dakṣiṇe pārśve vastidvārasya cāpyadhaḥ mūtrasrotaḥpathācchukraṃ puruṣasya pravarttate"},{"type":"verse","number":"202","sanskrit":"कृत्स्नदेहस्थितं शुक्रं प्रसन्नमनसस्तथा स्त्रीषु व्यायच्छतश्चापि हर्षात्तत् सम्प्रवर्त्तते","text":"kṛtsnadehasthitaṃ śukraṃ prasannamanasastathā strīṣu vyāyacchataścāpi harṣāttat sampravarttate"},{"type":"verse","number":"203","sanskrit":"शुक्रं कामेन कामिन्या दर्शनात् स्पर्शनादपि शब्दसंश्रवणाद् ध्यानात् संयोगाच्च प्रवर्त्तते","text":"śukraṃ kāmena kāminyā darśanāt sparśanādapi śabdasaṃśravaṇād dhyānāt saṃyogācca pravarttate"},{"type":"verse","number":"204","sanskrit":"रसादेव रजः स्त्रीणां मासि मासि त्र्यहं स्रवेत् तद्वर्षाद् द्वादशादूर्ध्वं याति पञ्चाशतः क्षयम्","text":"rasādeva rajaḥ strīṇāṃ māsi māsi tryahaṃ sravet tadvarṣād dvādaśādūrdhvaṃ yāti pañcāśataḥ kṣayam"},{"type":"verse","number":"205","sanskrit":"मासेनोपचितं काले धमनीभ्यस्तदार्त्तवम् ईषद्विवर्णं कृष्णञ्च वायुर्योनिमुखं नयेत्","text":"māsenopacitaṃ kāle dhamanībhyastadārttavam īṣadvivarṇaṃ kṛṣṇañca vāyuryonimukhaṃ nayet"},{"type":"verse","number":"206","sanskrit":"शशासृक्प्रतिमं यच्च यद्वा लाक्षारसोपमम् तदार्त्तवं प्रशंसन्ति यद्वासो न विरञ्जयेत्","text":"śaśāsṛkpratimaṃ yacca yadvā lākṣārasopamam tadārttavaṃ praśaṃsanti yadvāso na virañjayet"},{"type":"verse","number":"207","sanskrit":"अतिरिक्ता गुणा रक्ते बह्नेर्मांसे तु पार्थिवाः मेदस्यपां भुवश्चास्थ्नि पृथिव्यनिलतेजसाम्","text":"atiriktā guṇā rakte bahnermāṃse tu pārthivāḥ medasyapāṃ bhuvaścāsthni pṛthivyanilatejasām"},{"type":"verse","number":"208","sanskrit":"मज्ज्ञि शुक्रे च सोमस्य मूत्रे च शिखिनोगुणाः भुवस्तथाऽत्तवे त्वग्ने रसे क्षीरे तथाऽम्भसः","text":"majjñi śukre ca somasya mūtre ca śikhinoguṇāḥ bhuvastathā'ttave tvagne rase kṣīre tathā'mbhasaḥ"},{"type":"verse","number":"209","sanskrit":"कफः पित्तं मलः खेषु प्रस्वेदो नखलोम च नेत्रविट्त्वक्षु च स्नेहो धातूनां क्रमशो मलाः","text":"kaphaḥ pittaṃ malaḥ kheṣu prasvedo nakhaloma ca netraviṭtvakṣu ca sneho dhātūnāṃ kramaśo malāḥ"},{"type":"verse","number":"210","sanskrit":"वनितानां प्रसूतानां धमनीभ्यां स्तनौ गतात् रसादेव हि जायेत स्तन्यं स्तनयुगाशयम्","text":"vanitānāṃ prasūtānāṃ dhamanībhyāṃ stanau gatāt rasādeva hi jāyeta stanyaṃ stanayugāśayam"},{"type":"verse","number":"211","sanskrit":"शुद्धमांसस्य यः स्नेहः सा वसा परिकीर्त्तिता मेदसस्ताप्यमानस्य स्नेहो वा कथिता वसा","text":"śuddhamāṃsasya yaḥ snehaḥ sā vasā parikīrttitā medasastāpyamānasya sneho vā kathitā vasā"},{"type":"verse","number":"212","sanskrit":"स्तन्यं रजो वसा स्वेदो दन्ताः केशास्तथैव च ओजश्च सप्तधातूनां क्रमात् सप्तोपधातवः","text":"stanyaṃ rajo vasā svedo dantāḥ keśāstathaiva ca ojaśca saptadhātūnāṃ kramāt saptopadhātavaḥ"},{"type":"verse","number":"213","sanskrit":"उरोरक्ताशयस्तस्मादधः श्लेष्माशयः स्मृतः आमाशयस्तु तदधस्तल्लिङ्गं चरकोऽवदत्","text":"uroraktāśayastasmādadhaḥ śleṣmāśayaḥ smṛtaḥ āmāśayastu tadadhastalliṅgaṃ carako'vadat"},{"type":"verse","number":"214","sanskrit":"आमाशयादधः पक्वाशयादूर्ध्वन्तु या कला ग्रहणी नामिका सैव कथितः पाचकाशयः","text":"āmāśayādadhaḥ pakvāśayādūrdhvantu yā kalā grahaṇī nāmikā saiva kathitaḥ pācakāśayaḥ"},{"type":"verse","number":"215","sanskrit":"ऊर्ध्वमग्न्याशयो नाभेर्मध्यभागे व्यवस्थितः तस्योपरि तिलं ज्ञेयं तदधः पवनाशयः","text":"ūrdhvamagnyāśayo nābhermadhyabhāge vyavasthitaḥ tasyopari tilaṃ jñeyaṃ tadadhaḥ pavanāśayaḥ"},{"type":"verse","number":"216","sanskrit":"पक्वाशयस्तुतदधः स एव तु मलाशयः तदधः कथितो वस्तिः स हि मूत्राशयो मतः","text":"pakvāśayastutadadhaḥ sa eva tu malāśayaḥ tadadhaḥ kathito vastiḥ sa hi mūtrāśayo mataḥ"},{"type":"verse","number":"217","sanskrit":"कफाऽमपित्तवातानामाशया मलमूत्रयोः पुरुषेभ्योऽधिकाश्चान्ये नारीणामाशयास्त्रयः","text":"kaphā'mapittavātānāmāśayā malamūtrayoḥ puruṣebhyo'dhikāścānye nārīṇāmāśayāstrayaḥ"},{"type":"verse","number":"218","sanskrit":"धरा गर्भाशयः प्रोक्तः पित्तपक्वाशयान्तरे स्तनौ प्रवृद्धौ तावेव बुधैः स्तन्याशयौ मतौ","text":"dharā garbhāśayaḥ proktaḥ pittapakvāśayāntare stanau pravṛddhau tāveva budhaiḥ stanyāśayau matau"},{"type":"verse","number":"219","sanskrit":"स्नायुभिश्च प्रतिच्छन्नान् सन्ततांश्च जरायुणा श्लेष्मणा वेष्टितांश्चापि कलाभागांस्तु तान्विदुः","text":"snāyubhiśca praticchannān santatāṃśca jarāyuṇā śleṣmaṇā veṣṭitāṃścāpi kalābhāgāṃstu tānviduḥ"},{"type":"verse","number":"220","sanskrit":"धात्वाशयान्तरे धातोर्यः क्लेदस्त्वधितिष्ठति देहोष्मणाऽभिपक्वश्च सा कलेत्यभिधीयते","text":"dhātvāśayāntare dhātoryaḥ kledastvadhitiṣṭhati dehoṣmaṇā'bhipakvaśca sā kaletyabhidhīyate"},{"type":"verse","number":"221","sanskrit":"आद्या मांसधरा प्रोक्ता द्वितीया रक्तधारिणी मेदोधरा तृतीया तु चतुर्थी श्लेष्मधारिणी","text":"ādyā māṃsadharā proktā dvitīyā raktadhāriṇī medodharā tṛtīyā tu caturthī śleṣmadhāriṇī"},{"type":"verse","number":"222","sanskrit":"पञ्चमी तु मलं धत्ते षष्ठी पित्तधरा मता रेतोधरा सप्तमी स्यादिति सप्त कलाः स्मृताः","text":"pañcamī tu malaṃ dhatte ṣaṣṭhī pittadharā matā retodharā saptamī syāditi sapta kalāḥ smṛtāḥ"},{"type":"verse","number":"223","sanskrit":"सन्निपातः शिरास्नायुसन्धिमांसास्थिसम्भवः मर्माणि तेषु तिष्ठन्ति प्राणाः खलु विशेषतः","text":"sannipātaḥ śirāsnāyusandhimāṃsāsthisambhavaḥ marmāṇi teṣu tiṣṭhanti prāṇāḥ khalu viśeṣataḥ"},{"type":"verse","number":"224","sanskrit":"सप्तोत्तरशतं सन्ति देहे मर्माणि देहिनाम् तान्येकादश मांसे स्युरष्टावस्थिषु सन्ति हि","text":"saptottaraśataṃ santi dehe marmāṇi dehinām tānyekādaśa māṃse syuraṣṭāvasthiṣu santi hi"},{"type":"verse","number":"225","sanskrit":"सन्धीनां विंशतिस्तानि स्नायूनां सप्तविंशतिः चत्वारिंशतत्तथैकञ्च शिरामर्माणि तत्र तु","text":"sandhīnāṃ viṃśatistāni snāyūnāṃ saptaviṃśatiḥ catvāriṃśatattathaikañca śirāmarmāṇi tatra tu"},{"type":"verse","number":"226","sanskrit":"द्वाविंशतिः सक्थियुगे तावत्येव भुजद्वये द्वादशोरसि कुक्षौ च पृष्ठदेशे चतुर्दश","text":"dvāviṃśatiḥ sakthiyuge tāvatyeva bhujadvaye dvādaśorasi kukṣau ca pṛṣṭhadeśe caturdaśa"},{"type":"verse","number":"227","sanskrit":"ग्रीवायामूर्ध्वभागे तु सप्तत्रिंशन्मतानि हि मर्माणि तानि सन्तीह पञ्चधा च भवन्ति हि","text":"grīvāyāmūrdhvabhāge tu saptatriṃśanmatāni hi marmāṇi tāni santīha pañcadhā ca bhavanti hi"},{"type":"verse","number":"228","sanskrit":"सद्यः प्राणहराणि स्युर्मर्माण्येकोनविंशतिः मर्मदेशास्त्रयस्त्रिंशत् स्युः कालान्तरमारकाः","text":"sadyaḥ prāṇaharāṇi syurmarmāṇyekonaviṃśatiḥ marmadeśāstrayastriṃśat syuḥ kālāntaramārakāḥ"},{"type":"verse","number":"229","sanskrit":"चत्वारिंशच्च चत्वारि वैकल्यं जनयन्ति हि मर्माष्टकं रुजाकारि विशल्यघ्नं त्रिकं मतम्","text":"catvāriṃśacca catvāri vaikalyaṃ janayanti hi marmāṣṭakaṃ rujākāri viśalyaghnaṃ trikaṃ matam"},{"type":"verse","number":"230","sanskrit":"शृङ्गाटकान्यधिपतिः शङ्खौ कण्ठशिरा गुदम् हृदयं वस्तिनाभी च सद्यो घ्नन्ति हतानि चेत्","text":"śṛṅgāṭakānyadhipatiḥ śaṅkhau kaṇṭhaśirā gudam hṛdayaṃ vastinābhī ca sadyo ghnanti hatāni cet"},{"type":"verse","number":"231","sanskrit":"वक्षोमर्माणि सीमन्ततलक्षिप्रेन्द्र वस्तयः वृहत्यौ पार्श्वयोः सन्धी कटीकतरुणे च ये नितम्बाविति चैतानि कालान्तरहराणि तु","text":"vakṣomarmāṇi sīmantatalakṣiprendra vastayaḥ vṛhatyau pārśvayoḥ sandhī kaṭīkataruṇe ca ye nitambāviti caitāni kālāntaraharāṇi tu"},{"type":"verse","number":"232","sanskrit":"लोहिताक्षाणिजानूर्वी कूर्चा विटपकूर्पराः कुकुन्दरे कक्षधरे विधुरे सकृकाटिके","text":"lohitākṣāṇijānūrvī kūrcā viṭapakūrparāḥ kukundare kakṣadhare vidhure sakṛkāṭike"},{"type":"verse","number":"233","sanskrit":"अंसांसफलकापाङ्गा नीले मन्ये फणे तथा वैकल्यकरणान्याहुरावर्त्तौ द्वौ तथैव च","text":"aṃsāṃsaphalakāpāṅgā nīle manye phaṇe tathā vaikalyakaraṇānyāhurāvarttau dvau tathaiva ca"},{"type":"verse","number":"234","sanskrit":"गुल्फौ द्वौ मणिबन्धौ द्वौ तथा कूर्चशिरांसि च रुजाकराणि जानीयादष्टावेतानि बुद्धिमान्","text":"gulphau dvau maṇibandhau dvau tathā kūrcaśirāṃsi ca rujākarāṇi jānīyādaṣṭāvetāni buddhimān"},{"type":"verse","number":"235","sanskrit":"उत्क्षेपौ स्थपनी चैव विशल्यघ्नं त्रिकम्मतम्","text":"utkṣepau sthapanī caiva viśalyaghnaṃ trikammatam"},{"type":"verse","number":"236","sanskrit":"सप्तरात्रान्तरे हन्युः सद्यः प्राणहराणि हि कालान्तरप्राणहरं पक्षे मासे च मारकम्","text":"saptarātrāntare hanyuḥ sadyaḥ prāṇaharāṇi hi kālāntaraprāṇaharaṃ pakṣe māse ca mārakam"},{"type":"verse","number":"237","sanskrit":"सद्यः प्राणहरञ्चान्ते विद्धं कालेन मारयेत् कालान्तरप्राणहरमन्ते विद्धन्तु दुःखदम्","text":"sadyaḥ prāṇaharañcānte viddhaṃ kālena mārayet kālāntaraprāṇaharamante viddhantu duḥkhadam"},{"type":"verse","number":"238","sanskrit":"मर्माण्यधिष्ठाय हि ये विकारा मूर्च्छन्ति काये विविधा नराणाम् प्रायेण ते कृच्छ्रतमा भवन्ति वैद्येन यत्नैरपि साध्यमानाः","text":"marmāṇyadhiṣṭhāya hi ye vikārā mūrcchanti kāye vividhā narāṇām prāyeṇa te kṛcchratamā bhavanti vaidyena yatnairapi sādhyamānāḥ"},{"type":"verse","number":"239","sanskrit":"अथ सन्धयः ते द्विविधाश्चेष्टावन्तः स्थिराश्च शाखासु हन्वोः कट्याञ्च चेष्टावन्तो भवन्ति हि शेषास्तु सन्धयः सर्वे स्थिरास्तज्ज्ञैरुदाहृताः","text":"atha sandhayaḥ te dvividhāśceṣṭāvantaḥ sthirāśca śākhāsu hanvoḥ kaṭyāñca ceṣṭāvanto bhavanti hi śeṣāstu sandhayaḥ sarve sthirāstajjñairudāhṛtāḥ"},{"type":"verse","number":"240","sanskrit":"कथिता देहिनां देहे सन्धयो द्वे शते दश शाखासु तेऽष्टषष्टिश्च कोष्ठे त्वेकोनषष्टिका","text":"kathitā dehināṃ dehe sandhayo dve śate daśa śākhāsu te'ṣṭaṣaṣṭiśca koṣṭhe tvekonaṣaṣṭikā"},{"type":"verse","number":"241","sanskrit":"ग्रीवाया ऊर्ध्वदेशे तु त्र्यशीतिस्ते प्रकीर्त्तिताः प्रथमं परिगण्यन्ते तेषु शाखागता इह","text":"grīvāyā ūrdhvadeśe tu tryaśītiste prakīrttitāḥ prathamaṃ parigaṇyante teṣu śākhāgatā iha"},{"type":"verse","number":"242","sanskrit":"कोरोदूखलसामुद्गाः प्रतरस्तूणसेवनी काकतुण्डं मण्डलञ्च शङ्खावर्त्तोऽष्टसन्धयः","text":"korodūkhalasāmudgāḥ pratarastūṇasevanī kākatuṇḍaṃ maṇḍalañca śaṅkhāvartto'ṣṭasandhayaḥ"},{"type":"verse","number":"243","sanskrit":"अस्थ्नां तु सन्धयो ह्येते केवलाः समुदाहृताः पेशीस्नायु शिराणान्तु सन्धिसंख्या न विद्यते","text":"asthnāṃ tu sandhayo hyete kevalāḥ samudāhṛtāḥ peśīsnāyu śirāṇāntu sandhisaṃkhyā na vidyate"},{"type":"verse","number":"244","sanskrit":"सन्धिबन्धनकारिण्यो दोषधातुवहाः शिराः नाभ्यां सर्वा निबद्धास्ताः प्रतन्वन्ति समन्ततः","text":"sandhibandhanakāriṇyo doṣadhātuvahāḥ śirāḥ nābhyāṃ sarvā nibaddhāstāḥ pratanvanti samantataḥ"},{"type":"verse","number":"245","sanskrit":"शरीरं सकलञ्चैतच्छिराभिः पोष्यते सदा प्रणालीभिरिवारामाः कुल्याभिः क्षेत्रधान्यवत्","text":"śarīraṃ sakalañcaitacchirābhiḥ poṣyate sadā praṇālībhirivārāmāḥ kulyābhiḥ kṣetradhānyavat"},{"type":"verse","number":"246","sanskrit":"प्रसारणाकुञ्चनादिक्रियाभिः सततं तनौ शिरा एवोपकुर्वन्ति ताः स्युः सप्तशतानि तु","text":"prasāraṇākuñcanādikriyābhiḥ satataṃ tanau śirā evopakurvanti tāḥ syuḥ saptaśatāni tu"},{"type":"verse","number":"247","sanskrit":"यथा द्रुमदले साक्षाद् दृश्यन्ते प्रतताः शिराः तथैव दैहिनो देहे वर्त्तन्ते सकले शिराः","text":"yathā drumadale sākṣād dṛśyante pratatāḥ śirāḥ tathaiva daihino dehe varttante sakale śirāḥ"},{"type":"verse","number":"248","sanskrit":"नाभिस्थाः प्राणिनां प्राणाः प्राणान्नाभिरुपाश्रिता शिराभिरावृता नाभिश्चक्रनाभिरिवारकैः","text":"nābhisthāḥ prāṇināṃ prāṇāḥ prāṇānnābhirupāśritā śirābhirāvṛtā nābhiścakranābhirivārakaiḥ"},{"type":"verse","number":"249","sanskrit":"क्रियाणामप्रतीघातममोहं बुद्धिकर्मणाम् करोत्यन्यान् गुणांश्चापि स्वाः शिराः पवनश्चरन्","text":"kriyāṇāmapratīghātamamohaṃ buddhikarmaṇām karotyanyān guṇāṃścāpi svāḥ śirāḥ pavanaścaran"},{"type":"verse","number":"250","sanskrit":"यदा तु कुपितो वायुः स्वाः शिराः प्रतिपद्यते तदाऽस्य विविधा रोगा जायन्ते वातसम्भवाः","text":"yadā tu kupito vāyuḥ svāḥ śirāḥ pratipadyate tadā'sya vividhā rogā jāyante vātasambhavāḥ"},{"type":"verse","number":"251","sanskrit":"भ्राजिष्णुतामन्नरुचिमग्निदीप्तिमरोगताम् करोत्यन्यान् गुणांश्चापि पित्तमात्मशिराश्चरद्","text":"bhrājiṣṇutāmannarucimagnidīptimarogatām karotyanyān guṇāṃścāpi pittamātmaśirāścarad"},{"type":"verse","number":"252","sanskrit":"यदा तु कुपितं पित्तं सेवते स्ववहाः शिराः तदाऽस्यविविधा रोगा जायन्ते पित्तसम्भवाः","text":"yadā tu kupitaṃ pittaṃ sevate svavahāḥ śirāḥ tadā'syavividhā rogā jāyante pittasambhavāḥ"},{"type":"verse","number":"253","sanskrit":"स्नेहमङ्गेषु सन्धीनां स्थैर्यं बलमरोगाताम् करोत्यन्यान् गुणांश्चापि वलासःस्वाःशिराश्चरन्","text":"snehamaṅgeṣu sandhīnāṃ sthairyaṃ balamarogātām karotyanyān guṇāṃścāpi valāsaḥsvāḥśirāścaran"},{"type":"verse","number":"254","sanskrit":"यदा तु कुपितः श्लेष्मा स्वाः शिराः प्रतिपद्यते तदाऽस्य विविधा रोगा जायन्ते श्लेष्मसम्भवाः","text":"yadā tu kupitaḥ śleṣmā svāḥ śirāḥ pratipadyate tadā'sya vividhā rogā jāyante śleṣmasambhavāḥ"},{"type":"verse","number":"255","sanskrit":"धातूनां पूरणं वर्णस्पर्शज्ञानमसंशयम् स्वशिरासु चरद्र क्तं कुर्याच्चान्यान् गुणानपि","text":"dhātūnāṃ pūraṇaṃ varṇasparśajñānamasaṃśayam svaśirāsu caradra ktaṃ kuryāccānyān guṇānapi"},{"type":"verse","number":"256","sanskrit":"यदा तु कुपितं रक्तं सेवते स्ववहाः शिराः तदाऽस्य विविधा रोगा जायन्ते रक्तसम्भवाः","text":"yadā tu kupitaṃ raktaṃ sevate svavahāḥ śirāḥ tadā'sya vividhā rogā jāyante raktasambhavāḥ"},{"type":"verse","number":"257","sanskrit":"तत्रारुणा वातवहाः पूर्यन्ते वायुना शिराः पित्तादुष्णाश्च नीलाश्च शीता गौर्यः स्थिराः कफात् असृग्धरास्तु ता रक्ताः स्युश्च नात्युष्णशीतलाः","text":"tatrāruṇā vātavahāḥ pūryante vāyunā śirāḥ pittāduṣṇāśca nīlāśca śītā gauryaḥ sthirāḥ kaphāt asṛgdharāstu tā raktāḥ syuśca nātyuṣṇaśītalāḥ"},{"type":"verse","number":"258","sanskrit":"मेदसः स्नेहमादाय शिरा स्नायुत्वमाप्नुयात् शिराणां हि मृदुः पाकः स्नायूनान्तु ततः खरः","text":"medasaḥ snehamādāya śirā snāyutvamāpnuyāt śirāṇāṃ hi mṛduḥ pākaḥ snāyūnāntu tataḥ kharaḥ"},{"type":"verse","number":"259","sanskrit":"स्नायवो बन्धनानिस्युर्देहमांसास्थिमेदसाम् सन्धीनामपि यत्तास्तु शिराभ्यः सुदृढाः स्मृताः","text":"snāyavo bandhanānisyurdehamāṃsāsthimedasām sandhīnāmapi yattāstu śirābhyaḥ sudṛḍhāḥ smṛtāḥ"},{"type":"verse","number":"260","sanskrit":"नौर्यथा फलकास्तीर्णा बन्धनैर्बहुभिर्युता नियुक्ताऽगाधसलिले भवेद्भारसहा भृशम्","text":"nauryathā phalakāstīrṇā bandhanairbahubhiryutā niyuktā'gādhasalile bhavedbhārasahā bhṛśam"},{"type":"verse","number":"261","sanskrit":"एवमेव शरीरेस्मिन्यावन्तः सन्धयः स्मृताः स्नायुभिर्बहुभिर्बद्धास्तेन भारसहा नराः","text":"evameva śarīresminyāvantaḥ sandhayaḥ smṛtāḥ snāyubhirbahubhirbaddhāstena bhārasahā narāḥ"},{"type":"verse","number":"262","sanskrit":"शतानि नव जायन्ते शरीरे स्नायवो नृणाम् तासां विवरणं ब्रूमः शिष्याः शृणुत यत्नतः","text":"śatāni nava jāyante śarīre snāyavo nṛṇām tāsāṃ vivaraṇaṃ brūmaḥ śiṣyāḥ śṛṇuta yatnataḥ"},{"type":"verse","number":"263","sanskrit":"शाखासु षट्शतानि स्युः कोष्ठे त्रिंशच्छतद्वयम् ग्रीवाया ऊर्ध्वदेशे तु स्नायूनां सप्ततिः समृता","text":"śākhāsu ṣaṭśatāni syuḥ koṣṭhe triṃśacchatadvayam grīvāyā ūrdhvadeśe tu snāyūnāṃ saptatiḥ samṛtā"},{"type":"verse","number":"264","sanskrit":"धमन्यो नाभितो जाताश्चतुर्विंशतिसंख्यया दशोर्ध्वगा दशाधोगाः शेषास्तिर्यग्गताः स्मृता","text":"dhamanyo nābhito jātāścaturviṃśatisaṃkhyayā daśordhvagā daśādhogāḥ śeṣāstiryaggatāḥ smṛtā"},{"type":"verse","number":"265","sanskrit":"यथा स्वभावतः खानि मृणालेषु विसेषु च धमनीनां तथा खानि रसो यैरभितश्चरेत्","text":"yathā svabhāvataḥ khāni mṛṇāleṣu viseṣu ca dhamanīnāṃ tathā khāni raso yairabhitaścaret"},{"type":"verse","number":"266","sanskrit":"पञ्चाभिभूतास्त्वथ पञ्चकृत्वः पञ्चेन्द्रि यं पञ्चसु भाबयन्ति पञ्चेन्द्रि यं पञ्चसु भावयित्वा पञ्चत्वमायान्ति विनाशकाले","text":"pañcābhibhūtāstvatha pañcakṛtvaḥ pañcendri yaṃ pañcasu bhābayanti pañcendri yaṃ pañcasu bhāvayitvā pañcatvamāyānti vināśakāle"},{"type":"verse","number":"267","sanskrit":"महत्यः स्नायवः प्रोक्ताः कण्डरास्तास्तु षोडश प्रसारणाकुञ्चनयोर्दृष्टं तासां प्रयोजनम्","text":"mahatyaḥ snāyavaḥ proktāḥ kaṇḍarāstāstu ṣoḍaśa prasāraṇākuñcanayordṛṣṭaṃ tāsāṃ prayojanam"},{"type":"verse","number":"268","sanskrit":"चतस्रो हस्तयोस्तासां तावत्यः पादयोः स्मृताः ग्रीवायामपि तावत्यस्तावत्यः पृष्ठसङ्गताः","text":"catasro hastayostāsāṃ tāvatyaḥ pādayoḥ smṛtāḥ grīvāyāmapi tāvatyastāvatyaḥ pṛṣṭhasaṅgatāḥ"},{"type":"verse","number":"269","sanskrit":"नेत्रश्रवणनासानां द्वे द्वे रन्ध्रे प्रकीर्त्तिते मुखमेहनपायूनामेकैकं रन्ध्रमुच्यते","text":"netraśravaṇanāsānāṃ dve dve randhre prakīrttite mukhamehanapāyūnāmekaikaṃ randhramucyate"},{"type":"verse","number":"270","sanskrit":"दशमं मस्तके प्रोक्तं रन्ध्राणीति नृणां विदुः स्त्रीणामन्यानि च त्रीणि स्तनयोर्गर्भवर्त्मनि","text":"daśamaṃ mastake proktaṃ randhrāṇīti nṛṇāṃ viduḥ strīṇāmanyāni ca trīṇi stanayorgarbhavartmani"},{"type":"verse","number":"271","sanskrit":"मनः प्राणान्नपानीयदोषधातूपधातवः धातूनां च मला मूत्रं मलमित्यादयस्तनौ","text":"manaḥ prāṇānnapānīyadoṣadhātūpadhātavaḥ dhātūnāṃ ca malā mūtraṃ malamityādayastanau"},{"type":"verse","number":"272","sanskrit":"सञ्चरन्ति हि यैर्मागैस्तानि स्रोतांसि सञ्जगुः बहूनि तानि संख्याय शक्यन्ते नैव भाषितुम्","text":"sañcaranti hi yairmāgaistāni srotāṃsi sañjaguḥ bahūni tāni saṃkhyāya śakyante naiva bhāṣitum"},{"type":"verse","number":"273","sanskrit":"जालानि तु शिरास्नायुमांसास्थ्नामुद्भवन्ति हि तानि चत्वारि चत्वारि सर्वाण्येव च षोडश","text":"jālāni tu śirāsnāyumāṃsāsthnāmudbhavanti hi tāni catvāri catvāri sarvāṇyeva ca ṣoḍaśa"},{"type":"verse","number":"274","sanskrit":"कूर्चा स्युर्हस्तयोर्द्वौ तु तावन्तौ पादयोरपि ग्रीवायामेक एकस्तु मेढ्रे सर्वेऽपि षट् स्मृताः","text":"kūrcā syurhastayordvau tu tāvantau pādayorapi grīvāyāmeka ekastu meḍhre sarve'pi ṣaṭ smṛtāḥ"},{"type":"verse","number":"275","sanskrit":"पृष्ठवंशस्योभयत्र महत्यो मांसरज्जवः चतस्रो मांसपेशीनां बन्धनं तत्प्रयोजनम्","text":"pṛṣṭhavaṃśasyobhayatra mahatyo māṃsarajjavaḥ catasro māṃsapeśīnāṃ bandhanaṃ tatprayojanam"},{"type":"verse","number":"276","sanskrit":"सेवन्यः सप्त तासां तु भवेयुः पञ्च मस्तके एका शेफसि जिह्वायामेका विध्येन्न ताः क्वचित्","text":"sevanyaḥ sapta tāsāṃ tu bhaveyuḥ pañca mastake ekā śephasi jihvāyāmekā vidhyenna tāḥ kvacit"},{"type":"verse","number":"277","sanskrit":"चतुर्दशास्थ्नां सङ्घातास्तेषां त्रयो गुल्फजानुवंक्षणेषु एतेनेतरसक्थिबाहू च व्याख्यातौ त्रिकशिरसोरेकैकम्","text":"caturdaśāsthnāṃ saṅghātāsteṣāṃ trayo gulphajānuvaṃkṣaṇeṣu etenetarasakthibāhū ca vyākhyātau trikaśirasorekaikam"},{"type":"verse","number":"278","sanskrit":"चतुर्दशैव सीमन्ताः कथिता मुनिपुङ्गवैः सङ्घाताः सीविता यैस्तु सीमन्तास्ते प्रकीर्त्तिताः","text":"caturdaśaiva sīmantāḥ kathitā munipuṅgavaiḥ saṅghātāḥ sīvitā yaistu sīmantāste prakīrttitāḥ"},{"type":"verse","number":"279","sanskrit":"क्षीरस्य पच्यमानस्य यथा सन्तानिका भवेत् पच्यमानस्य शुक्रस्य रजसश्च तथा त्वचः पूर्वावभासिनी तासां सिध्मस्थानं च सा स्मृता","text":"kṣīrasya pacyamānasya yathā santānikā bhavet pacyamānasya śukrasya rajasaśca tathā tvacaḥ pūrvāvabhāsinī tāsāṃ sidhmasthānaṃ ca sā smṛtā"},{"type":"verse","number":"280","sanskrit":"द्वितीया लोहिता ज्ञेया तिलकालकजन्मभूः","text":"dvitīyā lohitā jñeyā tilakālakajanmabhūḥ"},{"type":"verse","number":"281","sanskrit":"तृतीया तु भवेच्छ्वेता स्थानं चर्मदलस्य सा","text":"tṛtīyā tu bhavecchvetā sthānaṃ carmadalasya sā"},{"type":"verse","number":"282","sanskrit":"ताम्रा चतुर्थी विज्ञेया किलासश्वित्रभूमिका","text":"tāmrā caturthī vijñeyā kilāsaśvitrabhūmikā"},{"type":"verse","number":"283","sanskrit":"पिञ्चमी वेदिनी नाम्ना पञ्चभागप्रमाणिका विसर्पकुष्ठाधिष्ठाना ज्ञेया षष्ठी तु रोहिणी विख्याता रोहिणी षष्ठी ग्रन्थिगण्डापचीस्थितिः","text":"piñcamī vedinī nāmnā pañcabhāgapramāṇikā visarpakuṣṭhādhiṣṭhānā jñeyā ṣaṣṭhī tu rohiṇī vikhyātā rohiṇī ṣaṣṭhī granthigaṇḍāpacīsthitiḥ"},{"type":"verse","number":"284","sanskrit":"स्थूला त्वक्सप्तमी ख्याता विद्र ध्यादेः स्थितिश्च सा","text":"sthūlā tvaksaptamī khyātā vidra dhyādeḥ sthitiśca sā"},{"type":"verse","number":"285","sanskrit":"अस्थ्नो मलानि लोमानि चासंख्यानि भवन्ति हि सन्ति यावन्ति लोमानि तावन्तो लोमकूपकाः","text":"asthno malāni lomāni cāsaṃkhyāni bhavanti hi santi yāvanti lomāni tāvanto lomakūpakāḥ"},{"type":"verse","number":"286","sanskrit":"अङ्गप्रत्यङ्गनिर्वृत्तिः स्वभावादेव जायते सन्निवेशश्च गात्राणां नात्रास्ते कारणान्तरम्","text":"aṅgapratyaṅganirvṛttiḥ svabhāvādeva jāyate sanniveśaśca gātrāṇāṃ nātrāste kāraṇāntaram"},{"type":"verse","number":"287","sanskrit":"अङ्गप्रत्यङ्गनिर्वृत्तौ ये भवन्यगुणा गुणाः ते ते गर्भस्य विज्ञेया धर्माधर्मनिमित्तजाः","text":"aṅgapratyaṅganirvṛttau ye bhavanyaguṇā guṇāḥ te te garbhasya vijñeyā dharmādharmanimittajāḥ"},{"type":"verse","number":"288","sanskrit":"दन्तानां पतनं जन्म पुनः पाते त्वसम्भवः तलेष्वनुद्भवो लोम्नामेतत्सर्वं स्वभावतः","text":"dantānāṃ patanaṃ janma punaḥ pāte tvasambhavaḥ taleṣvanudbhavo lomnāmetatsarvaṃ svabhāvataḥ"},{"type":"verse","number":"289","sanskrit":"गर्भाशये निपतितं यादृक्शुक्रं तथाऽतवम् तादृगेव द्र वीभूतं प्रथमे मासि तिष्ठति","text":"garbhāśaye nipatitaṃ yādṛkśukraṃ tathā'tavam tādṛgeva dra vībhūtaṃ prathame māsi tiṣṭhati"},{"type":"verse","number":"290","sanskrit":"मरुत्पित्तकफैस्तत्स्थैः पच्यमानो द्वितीयके कललस्थमहाभूतसमुदायो घनीभवेत्","text":"marutpittakaphaistatsthaiḥ pacyamāno dvitīyake kalalasthamahābhūtasamudāyo ghanībhavet"},{"type":"verse","number":"291","sanskrit":"तृतीये मासि शिरसो हस्तयोः पादयोस्तथा पिण्डकाः पञ्च सिध्यन्ति सूक्ष्माङ्गावयवास्तनोः","text":"tṛtīye māsi śiraso hastayoḥ pādayostathā piṇḍakāḥ pañca sidhyanti sūkṣmāṅgāvayavāstanoḥ"},{"type":"verse","number":"292","sanskrit":"सर्वाण्यङ्गान्युपाङ्गानि चतुर्थे स्युः स्फुटानि हि हृदयव्यक्तभावेन व्यज्यते चेतनाऽपि च","text":"sarvāṇyaṅgānyupāṅgāni caturthe syuḥ sphuṭāni hi hṛdayavyaktabhāvena vyajyate cetanā'pi ca"},{"type":"verse","number":"293","sanskrit":"तस्माच्चतुर्थे गर्भस्तु नाना वस्तूनि वाञ्छति ततो द्विहृदया यत्स्यान्नारी दौहृदिनी मता","text":"tasmāccaturthe garbhastu nānā vastūni vāñchati tato dvihṛdayā yatsyānnārī dauhṛdinī matā"},{"type":"verse","number":"294","sanskrit":"दौहृदावज्ञया कुब्जं कुणिं षण्ढं च वामनम् विकृताक्षमनक्षं वा पुत्रं नारी प्रसूयते","text":"dauhṛdāvajñayā kubjaṃ kuṇiṃ ṣaṇḍhaṃ ca vāmanam vikṛtākṣamanakṣaṃ vā putraṃ nārī prasūyate"},{"type":"verse","number":"295","sanskrit":"यतः स्त्री दौहृदं प्राप्य वीर्यवन्तं चिरायुषम् पुत्रं प्रसूयते तस्मात्तस्यै वाच्छितमर्पयेत्","text":"yataḥ strī dauhṛdaṃ prāpya vīryavantaṃ cirāyuṣam putraṃ prasūyate tasmāttasyai vācchitamarpayet"},{"type":"verse","number":"296","sanskrit":"इन्द्रि यार्थांस्तु यान्यान्सा भोक्तुमिच्छति गर्भिणी गर्भबाधाभयात्तांस्तान्भिषगाहृत्य दापयेत्","text":"indri yārthāṃstu yānyānsā bhoktumicchati garbhiṇī garbhabādhābhayāttāṃstānbhiṣagāhṛtya dāpayet"},{"type":"verse","number":"297","sanskrit":"सा प्राप्तदौहृदा पुत्रं जनयेत्तु गुणान्वितम् अलब्धदौहृदा गर्भे लभेतात्मनि वा भयम्","text":"sā prāptadauhṛdā putraṃ janayettu guṇānvitam alabdhadauhṛdā garbhe labhetātmani vā bhayam"},{"type":"verse","number":"298","sanskrit":"येषु येष्विन्द्रि यार्थेषु दौहृदे साऽवमानिता प्रसूयते सुतं सार्तिं तस्मिंस्तस्मिंस्तदिन्द्रि ये","text":"yeṣu yeṣvindri yārtheṣu dauhṛde sā'vamānitā prasūyate sutaṃ sārtiṃ tasmiṃstasmiṃstadindri ye"},{"type":"verse","number":"299","sanskrit":"राजसन्दर्शने यस्या दौहृदंजायते स्त्रियाः अर्थवन्तं महाभागं कुमारं सा प्रसूयते","text":"rājasandarśane yasyā dauhṛdaṃjāyate striyāḥ arthavantaṃ mahābhāgaṃ kumāraṃ sā prasūyate"},{"type":"verse","number":"300","sanskrit":"दुकूलपट्टकौशेयभूषणादिषु दौहृदात् अलङ्कारैषिणं पुत्रं ललितं सा प्रसूयते","text":"dukūlapaṭṭakauśeyabhūṣaṇādiṣu dauhṛdāt alaṅkāraiṣiṇaṃ putraṃ lalitaṃ sā prasūyate"},{"type":"verse","number":"301","sanskrit":"आश्रमे संयतात्मानं धर्मशीलं प्रसूयते देवताप्रतिमायां तु प्रसूते पार्षदोपमम्","text":"āśrame saṃyatātmānaṃ dharmaśīlaṃ prasūyate devatāpratimāyāṃ tu prasūte pārṣadopamam"},{"type":"verse","number":"302","sanskrit":"दर्शने व्यालजातीनां हिंसाशीलं प्रसूयते रक्ताक्षं लोमशं शूरं महिषामिषदौहृदात्","text":"darśane vyālajātīnāṃ hiṃsāśīlaṃ prasūyate raktākṣaṃ lomaśaṃ śūraṃ mahiṣāmiṣadauhṛdāt"},{"type":"verse","number":"303","sanskrit":"वाराहमांसे स्वप्नालुं शूरं सञ्जनयेत्सुतम् मृगमांसे तु जङ्घालं विक्रान्तं वनचारिणम्","text":"vārāhamāṃse svapnāluṃ śūraṃ sañjanayetsutam mṛgamāṃse tu jaṅghālaṃ vikrāntaṃ vanacāriṇam"},{"type":"verse","number":"304","sanskrit":"अतोऽनुक्तेषु या नारी दौहृदं विदधाति हि शरीराचारशीलैः सा समानं जनयिष्यति","text":"ato'nukteṣu yā nārī dauhṛdaṃ vidadhāti hi śarīrācāraśīlaiḥ sā samānaṃ janayiṣyati"},{"type":"verse","number":"305","sanskrit":"पञ्चमे मानसं षष्ठे बुद्धिश्चातिप्रबुद्ध्य्ते सर्वाण्यङ्गान्युपाङ्गानि भृशं व्यक्तानि सप्तमे","text":"pañcame mānasaṃ ṣaṣṭhe buddhiścātiprabuddhyte sarvāṇyaṅgānyupāṅgāni bhṛśaṃ vyaktāni saptame"},{"type":"verse","number":"306","sanskrit":"ओजोऽष्टमे सञ्चरति माता पुत्रौ मुहुः क्रमात् तेन तौम्लानमुदितौ स्यातां जातो न जीवति","text":"ojo'ṣṭame sañcarati mātā putrau muhuḥ kramāt tena taumlānamuditau syātāṃ jāto na jīvati"},{"type":"verse","number":"307","sanskrit":"न जीवत्यष्टमे जातस्तत्रौजो न स्थिरं यतः तथा नेरृत्यभागत्वाद्दापयेत्तद्वलि ततः","text":"na jīvatyaṣṭame jātastatraujo na sthiraṃ yataḥ tathā nerṛtyabhāgatvāddāpayettadvali tataḥ"},{"type":"verse","number":"308","sanskrit":"नवमे दशमे मासि नारी बालं प्रसूयते एकादशे द्वादशे वा ततोऽन्यत्र विकारतः","text":"navame daśame māsi nārī bālaṃ prasūyate ekādaśe dvādaśe vā tato'nyatra vikārataḥ"},{"type":"verse","number":"309","sanskrit":"शिरो भवति चाङ्गस्य पूर्वमित्याह शौनकः शिरस्येवोपजायन्ते प्रधानानीन्द्रि याणि यत्","text":"śiro bhavati cāṅgasya pūrvamityāha śaunakaḥ śirasyevopajāyante pradhānānīndri yāṇi yat"},{"type":"verse","number":"310","sanskrit":"हृदयं जायते पूर्वं कृतवीर्योऽवदन्मुनिः बुद्धेश्च मनसश्चापि यतस्तत्स्थानमीरितम्","text":"hṛdayaṃ jāyate pūrvaṃ kṛtavīryo'vadanmuniḥ buddheśca manasaścāpi yatastatsthānamīritam"},{"type":"verse","number":"311","sanskrit":"पाराशर्य इति प्राह पूर्वं नाभिसमुद्भवः प्राणो यत्र स्थितो देहं वर्द्धयत्यूष्मसंयुतः","text":"pārāśarya iti prāha pūrvaṃ nābhisamudbhavaḥ prāṇo yatra sthito dehaṃ varddhayatyūṣmasaṃyutaḥ"},{"type":"verse","number":"312","sanskrit":"पाणिपादं भवेत्पूर्वं मार्कण्डेयमुनेर्मतम् देहिनः सकलाश्चेष्टाः पाणिपादाश्रया यतः","text":"pāṇipādaṃ bhavetpūrvaṃ mārkaṇḍeyamunermatam dehinaḥ sakalāśceṣṭāḥ pāṇipādāśrayā yataḥ"},{"type":"verse","number":"313","sanskrit":"प्रथमं जायते कोष्ठं ततः सर्वांगसम्भवः एतत्तुं कथयामास गौतमो मुनिपुंगवः","text":"prathamaṃ jāyate koṣṭhaṃ tataḥ sarvāṃgasambhavaḥ etattuṃ kathayāmāsa gautamo munipuṃgavaḥ"},{"type":"verse","number":"314","sanskrit":"सर्वाण्यङ्गान्युपाङ्गानि युगपत्सम्भवन्ति हि सूक्ष्मत्वान्नोपलभ्यन्ते मतं धन्वन्तरेरिदम्","text":"sarvāṇyaṅgānyupāṅgāni yugapatsambhavanti hi sūkṣmatvānnopalabhyante mataṃ dhanvantareridam"},{"type":"verse","number":"315","sanskrit":"आम्रस्याणुफले भवन्ति युगपन्मांसास्थिमज्जादयो लक्ष्यन्ते न पृथक्पृथक्तनुतया पुष्टास्त एव स्फुटाः एवं गर्भसमुद्भवे त्ववयवाः सर्वे भवन्त्येकदा लक्ष्याः सूक्ष्मतया न ते प्रकटतामायान्ति वृद्धिं गताः","text":"āmrasyāṇuphale bhavanti yugapanmāṃsāsthimajjādayo lakṣyante na pṛthakpṛthaktanutayā puṣṭāsta eva sphuṭāḥ evaṃ garbhasamudbhave tvavayavāḥ sarve bhavantyekadā lakṣyāḥ sūkṣmatayā na te prakaṭatāmāyānti vṛddhiṃ gatāḥ"},{"type":"verse","number":"316","sanskrit":"अथ शरीरे पितृजमातृजरसजात्मजा भागा उच्यन्ते तत्र केशाःश्मश्रु च लोमानि नखा दन्ताः शिरास्तथा धमन्यः स्नायवः शुक्रमेतानि पितृजानि हि","text":"atha śarīre pitṛjamātṛjarasajātmajā bhāgā ucyante tatra keśāḥśmaśru ca lomāni nakhā dantāḥ śirāstathā dhamanyaḥ snāyavaḥ śukrametāni pitṛjāni hi"},{"type":"verse","number":"317","sanskrit":"मांसासृङ्मज्जमेदांसि यकृत्प्लीहान्त्रनाभयः हृदयं च गुदं चापि भवन्त्येतानि मातृतः","text":"māṃsāsṛṅmajjamedāṃsi yakṛtplīhāntranābhayaḥ hṛdayaṃ ca gudaṃ cāpi bhavantyetāni mātṛtaḥ"},{"type":"verse","number":"318","sanskrit":"शरीरोपचयो वर्णो बलं देहस्थितिस्तथा रसादेतानि जायन्ते भिषजो मुनयो जगुः","text":"śarīropacayo varṇo balaṃ dehasthitistathā rasādetāni jāyante bhiṣajo munayo jaguḥ"},{"type":"verse","number":"319","sanskrit":"ज्ञानं विज्ञानमायुश्च सुखदुःखादिकं तथा इन्द्रि याणि च सर्वाणि भवन्त्येतानि चात्मनः","text":"jñānaṃ vijñānamāyuśca sukhaduḥkhādikaṃ tathā indri yāṇi ca sarvāṇi bhavantyetāni cātmanaḥ"},{"type":"verse","number":"320","sanskrit":"अग्नीषोमौ मही वायुर्नभः सत्त्वं रजस्तमः पञ्चेन्द्रि याणि भूतात्मा गर्भं सञ्जीवयन्ति हि","text":"agnīṣomau mahī vāyurnabhaḥ sattvaṃ rajastamaḥ pañcendri yāṇi bhūtātmā garbhaṃ sañjīvayanti hi"},{"type":"verse","number":"321","sanskrit":"गर्भस्य नाभिनाड्या तु नाडी रसवहा स्त्रियाः संलग्ना तेन गर्भस्य वृद्धिर्भवति नित्यशः","text":"garbhasya nābhināḍyā tu nāḍī rasavahā striyāḥ saṃlagnā tena garbhasya vṛddhirbhavati nityaśaḥ"},{"type":"verse","number":"322","sanskrit":"निःश्वासोच्छ्वाससंक्षोभस्वप्नांशान्सोऽधिगच्छति मातुर्निःश्वसितोच्छ्वाससंक्षोभस्वप्नसंभवान्","text":"niḥśvāsocchvāsasaṃkṣobhasvapnāṃśānso'dhigacchati māturniḥśvasitocchvāsasaṃkṣobhasvapnasaṃbhavān"},{"type":"verse","number":"323","sanskrit":"गर्भस्य नाभिमध्ये तु ज्योतिःस्थानं ध्रुवं स्मृतम् तदाधमति वातश्च देहस्तेनास्य वर्धते","text":"garbhasya nābhimadhye tu jyotiḥsthānaṃ dhruvaṃ smṛtam tadādhamati vātaśca dehastenāsya vardhate"},{"type":"verse","number":"324","sanskrit":"ऊष्मणा सहिताश्चापि दारयत्यस्य मारुतः ऊर्ध्वं तिर्यगधस्ताच्च स्रोतांसि तु यथा तथा","text":"ūṣmaṇā sahitāścāpi dārayatyasya mārutaḥ ūrdhvaṃ tiryagadhastācca srotāṃsi tu yathā tathā"},{"type":"verse","number":"325","sanskrit":"दृष्टिश्च रामकूपाश्च न वर्धन्ते कदा च न ध्रुवाण्येतानि मर्त्यानामिति धन्वन्तरेर्मतम्","text":"dṛṣṭiśca rāmakūpāśca na vardhante kadā ca na dhruvāṇyetāni martyānāmiti dhanvantarermatam"},{"type":"verse","number":"326","sanskrit":"शरीरे क्षीयमाणेऽपि वर्धेते द्वाविमौ सदा स्वभावं प्रकृतिं कृत्वा नखकेशाविति स्थितिः","text":"śarīre kṣīyamāṇe'pi vardhete dvāvimau sadā svabhāvaṃ prakṛtiṃ kṛtvā nakhakeśāviti sthitiḥ"},{"type":"verse","number":"327","sanskrit":"चेतनानामधिष्ठानं मनो देहश्च सेन्द्रि यः केशलोमनखाग्रान्नमलद्र वगुणैर्विना","text":"cetanānāmadhiṣṭhānaṃ mano dehaśca sendri yaḥ keśalomanakhāgrānnamaladra vaguṇairvinā"},{"type":"verse","number":"328","sanskrit":"वाताल्पत्वादयोगाच्च वायोः पक्वाशयस्य च वातमूत्रपुरीषाणि गर्भस्थो न विमुञ्चति","text":"vātālpatvādayogācca vāyoḥ pakvāśayasya ca vātamūtrapurīṣāṇi garbhastho na vimuñcati"},{"type":"verse","number":"329","sanskrit":"जरायुणा मुखे छन्ने कण्ठे च कफवेष्टिते वायोर्मार्गनिरोधाच्च न गर्भस्थः प्ररोदिति","text":"jarāyuṇā mukhe channe kaṇṭhe ca kaphaveṣṭite vāyormārganirodhācca na garbhasthaḥ praroditi"},{"type":"verse","number":"330","sanskrit":"गर्भिणी प्रथमादह्नः प्रहृष्टा भूषिता शुचिः भवेच्छुक्लाम्बरधरा गुरुविप्रार्चने रता","text":"garbhiṇī prathamādahnaḥ prahṛṣṭā bhūṣitā śuciḥ bhavecchuklāmbaradharā guruviprārcane ratā"},{"type":"verse","number":"331","sanskrit":"भोज्यं तु मधुरप्रायं स्निग्धं हृद्यं द्र वं लघु सस्कृतं दीपनीयं तु नित्यमेवोपयोजयेत्","text":"bhojyaṃ tu madhuraprāyaṃ snigdhaṃ hṛdyaṃ dra vaṃ laghu saskṛtaṃ dīpanīyaṃ tu nityamevopayojayet"},{"type":"verse","number":"332","sanskrit":"गर्भिणी न तु कुर्वीत व्यायाममपतर्पणम् व्यवायं च न सेवेत न कुर्यादतितर्पणम्","text":"garbhiṇī na tu kurvīta vyāyāmamapatarpaṇam vyavāyaṃ ca na seveta na kuryādatitarpaṇam"},{"type":"verse","number":"333","sanskrit":"रात्रौ जागरणं शोकं यानस्यारोहणं तथा रक्तमोक्षं वेगरोधं न कुर्यादुत्कटासनम्","text":"rātrau jāgaraṇaṃ śokaṃ yānasyārohaṇaṃ tathā raktamokṣaṃ vegarodhaṃ na kuryādutkaṭāsanam"},{"type":"verse","number":"334","sanskrit":"दोषाभिघातैर्गर्भिण्या यो यो भागः प्रपीड्यते स स भागः शिशोस्तस्य गर्भस्थस्य प्रपीड्यते","text":"doṣābhighātairgarbhiṇyā yo yo bhāgaḥ prapīḍyate sa sa bhāgaḥ śiśostasya garbhasthasya prapīḍyate"},{"type":"verse","number":"335","sanskrit":"मलिनां विकृताकारां हीनाङ्गीं न स्पृशेत्स्त्रियम् न जिघ्रेदपि दुर्गन्धं न पश्येन्नयनाप्रियम्","text":"malināṃ vikṛtākārāṃ hīnāṅgīṃ na spṛśetstriyam na jighredapi durgandhaṃ na paśyennayanāpriyam"},{"type":"verse","number":"336","sanskrit":"वचांसि नापि शृणुयात्कर्णयोरप्रियाणि च नान्नं पर्युषितं शुष्कं भुञ्जीत क्वथितं न च","text":"vacāṃsi nāpi śṛṇuyātkarṇayorapriyāṇi ca nānnaṃ paryuṣitaṃ śuṣkaṃ bhuñjīta kvathitaṃ na ca"},{"type":"verse","number":"337","sanskrit":"चैत्यश्मशानवृक्षांश्च भावांश्चाप्ययशस्करान् बहिर्निष्क्रमणं क्रोधं शून्यागारं च वर्जयेत्","text":"caityaśmaśānavṛkṣāṃśca bhāvāṃścāpyayaśaskarān bahirniṣkramaṇaṃ krodhaṃ śūnyāgāraṃ ca varjayet"},{"type":"verse","number":"338","sanskrit":"नोच्चैर्ब्रूयान्न तत्कुर्याद्येन गर्भो विनश्यति तैलाभ्यङ्गोद्वर्तनं च नात्यर्थं कारयेदपि","text":"noccairbrūyānna tatkuryādyena garbho vinaśyati tailābhyaṅgodvartanaṃ ca nātyarthaṃ kārayedapi"},{"type":"verse","number":"339","sanskrit":"नामृद्वास्तरणं कुर्यान्नात्युच्चं शयनासनम् एतांस्तु नियमान्सर्वान्यत्नात्कुर्वीत गर्भिणी","text":"nāmṛdvāstaraṇaṃ kuryānnātyuccaṃ śayanāsanam etāṃstu niyamānsarvānyatnātkurvīta garbhiṇī"},{"type":"verse","number":"340","sanskrit":"नवमे दशमे मासि नारी गर्भं प्रसूयते एकादशे द्वादशे वा ततोऽन्यत्र विकारतः","text":"navame daśame māsi nārī garbhaṃ prasūyate ekādaśe dvādaśe vā tato'nyatra vikārataḥ"},{"type":"verse","number":"341","sanskrit":"अष्टहस्तायतं चारु चतुर्हस्तविशालकम् प्राचीद्वारमुदग्द्वारं विदध्यात्सूतिकागृहम्","text":"aṣṭahastāyataṃ cāru caturhastaviśālakam prācīdvāramudagdvāraṃ vidadhyātsūtikāgṛham"},{"type":"verse","number":"342","sanskrit":"जाते हि शिथिले कुक्षौ मुक्ते हृदयबन्धने सशूले जघने नारी विज्ञेया प्रसवोत्सुका","text":"jāte hi śithile kukṣau mukte hṛdayabandhane saśūle jaghane nārī vijñeyā prasavotsukā"},{"type":"verse","number":"343","sanskrit":"आसन्नप्रसवायास्तु कटीपृष्ठं तु सव्यथम् भवेन्मुहुः प्रवृत्तिश्च मूत्रस्य च मलस्य च","text":"āsannaprasavāyāstu kaṭīpṛṣṭhaṃ tu savyatham bhavenmuhuḥ pravṛttiśca mūtrasya ca malasya ca"},{"type":"verse","number":"344","sanskrit":"तैलेनाभ्यक्तगात्रान्तां संस्नातामुष्णवारिणा यवागूं पाययेत्कोष्णां मात्रया घृतसंयुताम्","text":"tailenābhyaktagātrāntāṃ saṃsnātāmuṣṇavāriṇā yavāgūṃ pāyayetkoṣṇāṃ mātrayā ghṛtasaṃyutām"},{"type":"verse","number":"345","sanskrit":"कृतोपधाने मृदुनि विस्तीर्णे शयने शनैः अभुग्नसक्थी चोत्ताना नारी तिष्ठेद्व्यथाऽन्विता","text":"kṛtopadhāne mṛduni vistīrṇe śayane śanaiḥ abhugnasakthī cottānā nārī tiṣṭhedvyathā'nvitā"},{"type":"verse","number":"346","sanskrit":"चतस्रोऽशकनीयाश्च स्रावणे कुशला हिताः वृद्धाः परिचरेयुस्ताः सम्यक्छिन्ननखाः स्त्रियः","text":"catasro'śakanīyāśca srāvaṇe kuśalā hitāḥ vṛddhāḥ paricareyustāḥ samyakchinnanakhāḥ striyaḥ"},{"type":"verse","number":"347","sanskrit":"अपत्यमार्गं तैलेन समभ्यज्य समन्ततः एका तु तासु सुभगे प्रवाहस्वेति तां वदेत्","text":"apatyamārgaṃ tailena samabhyajya samantataḥ ekā tu tāsu subhage pravāhasveti tāṃ vadet"},{"type":"verse","number":"348","sanskrit":"अव्यथा मा प्रवाहिष्ठाः प्रावहेथा व्यथा यदि प्रवाहेथाः शनैः पूर्वंप्रगाढं च ततः परम्","text":"avyathā mā pravāhiṣṭhāḥ prāvahethā vyathā yadi pravāhethāḥ śanaiḥ pūrvaṃpragāḍhaṃ ca tataḥ param"},{"type":"verse","number":"349","sanskrit":"ततो गाढतमं गर्भे योनिद्वारमुपागते अपरासहितो गर्भो यावत्पतति भूतले","text":"tato gāḍhatamaṃ garbhe yonidvāramupāgate aparāsahito garbho yāvatpatati bhūtale"},{"type":"verse","number":"350","sanskrit":"मूकं वा बधिरं कुब्जं श्वासकासक्षयान्वितम् सूते स्रस्ततनुं बालमकाले तु प्रवाहणात्","text":"mūkaṃ vā badhiraṃ kubjaṃ śvāsakāsakṣayānvitam sūte srastatanuṃ bālamakāle tu pravāhaṇāt"},{"type":"verse","number":"351","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमन्मिश्रभाव विरचिते भावप्रकाशे गर्भप्रकरणं तृतीयम् ३","text":"iti śrīmiśralaṭakana tanaya śrīmanmiśrabhāva viracite bhāvaprakāśe garbhaprakaraṇaṃ tṛtīyam 3"}]},{"sthana":"Пурвакханда","number":4,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть I, пракарана 4"},{"type":"verse","number":"1","sanskrit":"अथ बाले समुत्पन्ने विदधीत विधिं तथा यथैव कुलवृद्धस्त्रीव्यवहारपरम्परा","text":"atha bāle samutpanne vidadhīta vidhiṃ tathā yathaiva kulavṛddhastrīvyavahāraparamparā"},{"type":"verse","number":"2","sanskrit":"प्रसूता हितमाहारं विहारं च समाचरेत् व्यायामं मैथुनं क्रोधं शीतसेवां विवर्जयेत्","text":"prasūtā hitamāhāraṃ vihāraṃ ca samācaret vyāyāmaṃ maithunaṃ krodhaṃ śītasevāṃ vivarjayet"},{"type":"verse","number":"3","sanskrit":"मिथ्याचारात्सूतिकाया यो व्याधिरुपजायते स कृच्छ्रसाध्योऽसाध्यो वा भवेत्तत्पथ्यमाचरेत्","text":"mithyācārātsūtikāyā yo vyādhirupajāyate sa kṛcchrasādhyo'sādhyo vā bhavettatpathyamācaret"},{"type":"verse","number":"4","sanskrit":"सर्वतः परिशुद्धा स्यात्स्निग्धपथ्याऽल्पभोजना स्वेदाभ्यङ्गपरा नित्यं भवेन्मासमतन्द्रि ता","text":"sarvataḥ pariśuddhā syātsnigdhapathyā'lpabhojanā svedābhyaṅgaparā nityaṃ bhavenmāsamatandri tā"},{"type":"verse","number":"5","sanskrit":"प्रसूता सार्धमासान्ते दृष्टे वा पुनरार्त्तवे सूतिकानामहीना स्यादिति धन्वन्तरेर्मतम्","text":"prasūtā sārdhamāsānte dṛṣṭe vā punarārttave sūtikānāmahīnā syāditi dhanvantarermatam"},{"type":"verse","number":"6","sanskrit":"व्युपद्र वां विशुद्धां च विज्ञाय वरवर्णिनीम् ऊर्ध्वं चतुर्भ्यो मासेभ्यो नियमं परिहारयेत्","text":"vyupadra vāṃ viśuddhāṃ ca vijñāya varavarṇinīm ūrdhvaṃ caturbhyo māsebhyo niyamaṃ parihārayet"},{"type":"verse","number":"7","sanskrit":"रसप्रसादो मधुरः पक्वाहारनिमित्तजः कृत्स्नाद्देहात्स्तनौ प्राप्तः स्तन्यमित्यभिधीयते","text":"rasaprasādo madhuraḥ pakvāhāranimittajaḥ kṛtsnāddehātstanau prāptaḥ stanyamityabhidhīyate"},{"type":"verse","number":"8","sanskrit":"स्तन्यं त्रिरात्रात्स्त्रीणां वा चतूरात्रादनन्तरम् प्रवर्त्तयन्ति विवृता धमन्यो हृदये स्थिताः","text":"stanyaṃ trirātrātstrīṇāṃ vā catūrātrādanantaram pravarttayanti vivṛtā dhamanyo hṛdaye sthitāḥ"},{"type":"verse","number":"9","sanskrit":"पयः पुत्रस्य संस्पर्शाद्दर्शनात्स्मरणादपि ग्रहणादप्युरोजस्य शुक्रवत्सम्प्रवर्त्तते स्नेहो निरन्तरस्तस्य प्रवाहे हेतुरुच्यते","text":"payaḥ putrasya saṃsparśāddarśanātsmaraṇādapi grahaṇādapyurojasya śukravatsampravarttate sneho nirantarastasya pravāhe heturucyate"},{"type":"verse","number":"10","sanskrit":"अवात्सल्याद्भयाच्छोकात्क्रोधादत्यपतर्पणात् स्त्रीणां स्तन्यं भवेत्स्वल्पं गर्भान्तरविधारणात्","text":"avātsalyādbhayācchokātkrodhādatyapatarpaṇāt strīṇāṃ stanyaṃ bhavetsvalpaṃ garbhāntaravidhāraṇāt"},{"type":"verse","number":"11","sanskrit":"शालिषष्टिकगोधूमान्मांसक्षुद्र झषानपि कालशाकमलाबूं च नारिकेलं कसेरुकम्","text":"śāliṣaṣṭikagodhūmānmāṃsakṣudra jhaṣānapi kālaśākamalābūṃ ca nārikelaṃ kaserukam"},{"type":"verse","number":"12","sanskrit":"शृङ्गाटकं वरीं चापि विदारीकन्दमेव च लशुनं दुग्धवृद्धयै स्त्री सेवेत सुमना भवेत्","text":"śṛṅgāṭakaṃ varīṃ cāpi vidārīkandameva ca laśunaṃ dugdhavṛddhayai strī seveta sumanā bhavet"},{"type":"verse","number":"13","sanskrit":"कलमस्य तण्डुलानां कल्कं या क्षीरपेषितं पिबति सा भवति भृशं तरुणी क्षीरभरेणैव तुङ्गकुचयुगला","text":"kalamasya taṇḍulānāṃ kalkaṃ yā kṣīrapeṣitaṃ pibati sā bhavati bhṛśaṃ taruṇī kṣīrabhareṇaiva tuṅgakucayugalā"},{"type":"verse","number":"14","sanskrit":"कलमः कलिविख्यातो जायते स बृहद्ध्रदे काश्मीरदेश एवोक्तो महातण्डुलसंज्ञकः","text":"kalamaḥ kalivikhyāto jāyate sa bṛhaddhrade kāśmīradeśa evokto mahātaṇḍulasaṃjñakaḥ"},{"type":"verse","number":"15","sanskrit":"विदारिकन्दस्य रसं पिबेत्स्तन्यस्य वृद्धये तच्चूर्णं तस्य वृर्द्ध्य्थं पिबेद्वा क्षीरसंयुतम्","text":"vidārikandasya rasaṃ pibetstanyasya vṛddhaye taccūrṇaṃ tasya vṛrddhythaṃ pibedvā kṣīrasaṃyutam"},{"type":"verse","number":"16","sanskrit":"धात्र्या गुरुभिराहारैर्विहारैर्दोषलैस्तथा देहे दोषाः प्रकुप्यन्ति ततः स्तन्यं प्रदुष्यति","text":"dhātryā gurubhirāhārairvihārairdoṣalaistathā dehe doṣāḥ prakupyanti tataḥ stanyaṃ praduṣyati"},{"type":"verse","number":"17","sanskrit":"मिथ्याऽहारविहारिण्या दुष्टा वातादयः स्त्रियाः दूषयन्ति पयस्तेन शरीरं व्याधयः शिशोः","text":"mithyā'hāravihāriṇyā duṣṭā vātādayaḥ striyāḥ dūṣayanti payastena śarīraṃ vyādhayaḥ śiśoḥ"},{"type":"verse","number":"18","sanskrit":"कषायं सलिलप्लावि स्तन्यं मारुतदूषितम् पित्तादम्लं च कटुकं राज्योऽम्भसि तु पीतिकाः","text":"kaṣāyaṃ salilaplāvi stanyaṃ mārutadūṣitam pittādamlaṃ ca kaṭukaṃ rājyo'mbhasi tu pītikāḥ"},{"type":"verse","number":"19","sanskrit":"कफदुष्टं तु यत्तोये निमज्जति च पिच्छिलम् द्वन्द्वजं तु द्विलिङ्गं स्यात्त्रिलिङ्गं सान्निपातिकम्","text":"kaphaduṣṭaṃ tu yattoye nimajjati ca picchilam dvandvajaṃ tu dviliṅgaṃ syāttriliṅgaṃ sānnipātikam"},{"type":"verse","number":"20","sanskrit":"धात्री क्षीरविशुर्द्ध्य्थं मुद्गयूषरसाशिनी भार्ङ्गीदारुवचाः पिष्ट्वा पिबेत्साऽतिविषास्तथा","text":"dhātrī kṣīraviśurddhythaṃ mudgayūṣarasāśinī bhārṅgīdāruvacāḥ piṣṭvā pibetsā'tiviṣāstathā"},{"type":"verse","number":"21","sanskrit":"पाठामूर्वाऽब्दभूनिम्बदारुशुण्ठीकलिङ्गकैः सारिवामत्स्यपित्ताऽख्यै क्वाथः स्तन्यविशोधनः","text":"pāṭhāmūrvā'bdabhūnimbadāruśuṇṭhīkaliṅgakaiḥ sārivāmatsyapittā'khyai kvāthaḥ stanyaviśodhanaḥ"},{"type":"verse","number":"22","sanskrit":"पटोलनिम्बासनदारुपाठा मूर्वां गुडूचीं कटुरोहिणीं च सनागरां च क्वथितां च तोये धात्री पिबेत्स्तन्यविशुद्धिहेतोः","text":"paṭolanimbāsanadārupāṭhā mūrvāṃ guḍūcīṃ kaṭurohiṇīṃ ca sanāgarāṃ ca kvathitāṃ ca toye dhātrī pibetstanyaviśuddhihetoḥ"},{"type":"verse","number":"23","sanskrit":"नीरे स्यन्यं यदेकि स्वादविवर्णमतन्तुमत् पाण्डुरं तनु शीतं च तद्दुग्धं शुंद्धमादिशेत्","text":"nīre syanyaṃ yadeki svādavivarṇamatantumat pāṇḍuraṃ tanu śītaṃ ca taddugdhaṃ śuṃddhamādiśet"},{"type":"verse","number":"24","sanskrit":"पीताय यदि बालस्य विदध्यादुपमातरम् सुविचार्य गुणान्दोषान्कुर्याद्धात्रीं तदेदृशीम्","text":"pītāya yadi bālasya vidadhyādupamātaram suvicārya guṇāndoṣānkuryāddhātrīṃ tadedṛśīm"},{"type":"verse","number":"25","sanskrit":"सवर्णां मध्यवयसां सच्छीलां मुदितां सदा शुद्धदुग्धां बहुक्षीरां सवत्सामतिवत्सलाम्","text":"savarṇāṃ madhyavayasāṃ sacchīlāṃ muditāṃ sadā śuddhadugdhāṃ bahukṣīrāṃ savatsāmativatsalām"},{"type":"verse","number":"26","sanskrit":"स्वाधीनामल्पसन्तुष्टां कुलीनां सज्जनात्मजाम् कैतवेन परित्यक्तां निजपुत्रशदृशं शिशौ","text":"svādhīnāmalpasantuṣṭāṃ kulīnāṃ sajjanātmajām kaitavena parityaktāṃ nijaputraśadṛśaṃ śiśau"},{"type":"verse","number":"27","sanskrit":"शोकाकुलाक्षु धार्ता च श्रान्ता व्याधिमती सदा अत्युच्चा नितरां नीचा स्थूलातीव भृशं कृशा","text":"śokākulākṣu dhārtā ca śrāntā vyādhimatī sadā atyuccā nitarāṃ nīcā sthūlātīva bhṛśaṃ kṛśā"},{"type":"verse","number":"28","sanskrit":"गर्भिणी ज्वरिणी चापि लम्बोन्नतपयोधरा अजीर्णभोजिनी चापि तथा पथ्यविवर्जिता","text":"garbhiṇī jvariṇī cāpi lambonnatapayodharā ajīrṇabhojinī cāpi tathā pathyavivarjitā"},{"type":"verse","number":"29","sanskrit":"आसक्ता क्षुद्र कार्येषु दुःखार्ता चञ्चलाऽपि च एतासां स्तन्यपानेन शिशुर्भवति सामयः","text":"āsaktā kṣudra kāryeṣu duḥkhārtā cañcalā'pi ca etāsāṃ stanyapānena śiśurbhavati sāmayaḥ"},{"type":"verse","number":"30","sanskrit":"तत्र माता प्रशस्ताङ्गी चारुवस्त्रा पुरोमुखी उपविश्यासने सम्यग्दक्षिणं स्तनमम्बुना","text":"tatra mātā praśastāṅgī cāruvastrā puromukhī upaviśyāsane samyagdakṣiṇaṃ stanamambunā"},{"type":"verse","number":"31","sanskrit":"प्रक्षाल्येषत्परिस्राव्य मन्त्राभ्यामभिमन्त्रितम् उदङ्मुखं शिशुं क्रोडे शनैः सन्धाय पाययेत्","text":"prakṣālyeṣatparisrāvya mantrābhyāmabhimantritam udaṅmukhaṃ śiśuṃ kroḍe śanaiḥ sandhāya pāyayet"},{"type":"verse","number":"32","sanskrit":"अस्रावितं स्तनं बालः पिबन्स्तन्येन भूयसा पूर्णस्रोता वमीकासश्वासैर्भवति पीडितः","text":"asrāvitaṃ stanaṃ bālaḥ pibanstanyena bhūyasā pūrṇasrotā vamīkāsaśvāsairbhavati pīḍitaḥ"},{"type":"verse","number":"33","sanskrit":"क्षीरनीरनिधिस्तेऽस्तु स्तनयोः क्षीरपूरकः सदैव सुभगो बालो भवत्वेष महाबलः","text":"kṣīranīranidhiste'stu stanayoḥ kṣīrapūrakaḥ sadaiva subhago bālo bhavatveṣa mahābalaḥ"},{"type":"verse","number":"34","sanskrit":"पयोऽमृतसमं पीत्वा कुमारस्ते शुभानने दीर्घमायुरवाप्नोतु देवाः प्राप्यामृतं यथा","text":"payo'mṛtasamaṃ pītvā kumāraste śubhānane dīrghamāyuravāpnotu devāḥ prāpyāmṛtaṃ yathā"},{"type":"verse","number":"35","sanskrit":"क्षीरसात्म्यतया क्षीरमाजं गव्यमथापि वा दद्यादास्तन्यपर्याप्तेर्बालेभ्यो वीक्ष्य मात्रया","text":"kṣīrasātmyatayā kṣīramājaṃ gavyamathāpi vā dadyādāstanyaparyāpterbālebhyo vīkṣya mātrayā"},{"type":"verse","number":"36","sanskrit":"यथोक्तविधिना बालं मासि षष्ठेऽष्टमेऽपि च अन्नं सम्प्राशयेत्किञ्चित्ततस्तद्वर्धयेत्क्रमात्","text":"yathoktavidhinā bālaṃ māsi ṣaṣṭhe'ṣṭame'pi ca annaṃ samprāśayetkiñcittatastadvardhayetkramāt"},{"type":"verse","number":"37","sanskrit":"बालमङ्के सुखं दध्यान्न चैनं तर्जयेत्क्वचित् सहसा बोधये न्नैव नायोग्यमुपवेशयेत्","text":"bālamaṅke sukhaṃ dadhyānna cainaṃ tarjayetkvacit sahasā bodhaye nnaiva nāyogyamupaveśayet"},{"type":"verse","number":"38","sanskrit":"नाकृष्य स्थापयेत्क्रोडे न क्षिप्रं शयने क्षिपेत् रोदयेन्न क्वचित्कार्ये विधिमावश्यकं विना","text":"nākṛṣya sthāpayetkroḍe na kṣipraṃ śayane kṣipet rodayenna kvacitkārye vidhimāvaśyakaṃ vinā"},{"type":"verse","number":"39","sanskrit":"तच्चित्तमनुवर्त्तेत तं सदैवानुमोदयेत् वारतपतडिद्वृष्टिधूमानलजलादितः निम्नोच्चस्थानतश्चापि रक्षेद्बालं प्रयत्नतः","text":"taccittamanuvartteta taṃ sadaivānumodayet vāratapataḍidvṛṣṭidhūmānalajalāditaḥ nimnoccasthānataścāpi rakṣedbālaṃ prayatnataḥ"},{"type":"verse","number":"40","sanskrit":"अभ्यङ्गोद्वर्त्तन स्नानं नेत्रयोरञ्जनं तथा वसनं मृदु यत्तच्च तथा मृद्वनुलेपनम् जन्मप्रभृति पथ्यानि बालस्यैतानि सर्वथा","text":"abhyaṅgodvarttana snānaṃ netrayorañjanaṃ tathā vasanaṃ mṛdu yattacca tathā mṛdvanulepanam janmaprabhṛti pathyāni bālasyaitāni sarvathā"},{"type":"verse","number":"41","sanskrit":"कवलः पञ्चमाद्वर्षादष्टमान्नस्यकर्म च विरेकः षोडशाद्वर्षाद्विंशतेश्चैव मैथुनम्","text":"kavalaḥ pañcamādvarṣādaṣṭamānnasyakarma ca virekaḥ ṣoḍaśādvarṣādviṃśateścaiva maithunam"},{"type":"verse","number":"42","sanskrit":"वयस्तु त्रिविधं बाल्यं मध्यमं वार्धकं तथा ऊनषोडशवर्षस्तु नरो बालो निगद्यते","text":"vayastu trividhaṃ bālyaṃ madhyamaṃ vārdhakaṃ tathā ūnaṣoḍaśavarṣastu naro bālo nigadyate"},{"type":"verse","number":"43","sanskrit":"त्रिविधः सोऽपि दुग्धाशी दुग्धान्नाशी तथाऽन्नभुक् दुग्धाशी वर्षपर्यन्तं दुग्धान्नाशी शरद्द्वयम्","text":"trividhaḥ so'pi dugdhāśī dugdhānnāśī tathā'nnabhuk dugdhāśī varṣaparyantaṃ dugdhānnāśī śaraddvayam"},{"type":"verse","number":"44","sanskrit":"तदुत्तरं स्यादन्नाशी एवं बालस्त्रिधा मतः मध्ये षोडशसप्तत्योर्मध्यमः कथितो बुधैः","text":"taduttaraṃ syādannāśī evaṃ bālastridhā mataḥ madhye ṣoḍaśasaptatyormadhyamaḥ kathito budhaiḥ"},{"type":"verse","number":"45","sanskrit":"चतुर्धा मध्यमं वृद्धियुवपूर्णक्षयान्वितम् भवेदाविंशतेर्वृद्धिर्युवा त्वान्त्रिंशतो मतः","text":"caturdhā madhyamaṃ vṛddhiyuvapūrṇakṣayānvitam bhavedāviṃśatervṛddhiryuvā tvāntriṃśato mataḥ"},{"type":"verse","number":"46","sanskrit":"चत्वारिंशत्समा यावत्तिष्ठेद्वीर्यादिपूरितः ततः क्रमेण क्षीणः स्याद्यावद्भवति सप्ततिः","text":"catvāriṃśatsamā yāvattiṣṭhedvīryādipūritaḥ tataḥ krameṇa kṣīṇaḥ syādyāvadbhavati saptatiḥ"},{"type":"verse","number":"47","sanskrit":"ततस्तु सप्ततेरूर्ध्वं क्षीणधातुरसादिकः क्षीयमाणेन्द्रि यबलः क्षीणरेता दिने दिने","text":"tatastu saptaterūrdhvaṃ kṣīṇadhāturasādikaḥ kṣīyamāṇendri yabalaḥ kṣīṇaretā dine dine"},{"type":"verse","number":"48","sanskrit":"बलीपलितखालित्ययुक्तः कर्मसु चाक्षमः कासश्वासादिभिः क्लिष्टो वृद्धो भवति मानवः","text":"balīpalitakhālityayuktaḥ karmasu cākṣamaḥ kāsaśvāsādibhiḥ kliṣṭo vṛddho bhavati mānavaḥ"},{"type":"verse","number":"49","sanskrit":"बाल्ये विवर्धते श्लेष्मा पित्तं स्यान्मध्यमेऽधिकम् वार्धके वर्द्धते वायुर्विचार्यैतदुपक्रमेत्","text":"bālye vivardhate śleṣmā pittaṃ syānmadhyame'dhikam vārdhake varddhate vāyurvicāryaitadupakramet"},{"type":"verse","number":"50","sanskrit":"बाल्यं वृद्धिश्छविर्मेधा त्वग्दृष्टिः शुक्रविक्रमौ बुद्धिः कर्मेन्द्रि यं चेतो जीवितं दशतो ह्रसेत्","text":"bālyaṃ vṛddhiśchavirmedhā tvagdṛṣṭiḥ śukravikramau buddhiḥ karmendri yaṃ ceto jīvitaṃ daśato hraset"},{"type":"verse","number":"51","sanskrit":"सप्त प्रकृतयो नॄणां वातात्पित्तात्कफात्तथा संसर्गात्सन्निपाताच्च भवन्ति भिषजां मते","text":"sapta prakṛtayo nṝṇāṃ vātātpittātkaphāttathā saṃsargātsannipātācca bhavanti bhiṣajāṃ mate"},{"type":"verse","number":"52","sanskrit":"शुक्रशोणितसंयोगे यो दोषस्तूत्कटो भवेत् प्रकृतिर्जायते तेन तस्या लक्षणमुच्यते","text":"śukraśoṇitasaṃyoge yo doṣastūtkaṭo bhavet prakṛtirjāyate tena tasyā lakṣaṇamucyate"},{"type":"verse","number":"53","sanskrit":"शुक्रासृग्गर्भिणीभोज्यचेष्टागर्भाशयार्त्तिषु यः स्याद्दोषोऽधिकस्तेन प्रकृतिः सप्तधोदिता","text":"śukrāsṛggarbhiṇībhojyaceṣṭāgarbhāśayārttiṣu yaḥ syāddoṣo'dhikastena prakṛtiḥ saptadhoditā"},{"type":"verse","number":"54","sanskrit":"जागरूकोऽल्पकेशश्च स्फुटितांघ्रिकरः कृशः शीघ्रगो बहुवाग्रूक्षः स्वप्ने वियति गच्छति एवंविधः स विज्ञेयो वातप्रकृतिको नरः","text":"jāgarūko'lpakeśaśca sphuṭitāṃghrikaraḥ kṛśaḥ śīghrago bahuvāgrūkṣaḥ svapne viyati gacchati evaṃvidhaḥ sa vijñeyo vātaprakṛtiko naraḥ"},{"type":"verse","number":"55","sanskrit":"पित्तप्रकृतिको लोको यादृशोऽथ निगद्यते अकालपलितो गौरः क्रोधी स्वेदी च बुद्धिमान्","text":"pittaprakṛtiko loko yādṛśo'tha nigadyate akālapalito gauraḥ krodhī svedī ca buddhimān"},{"type":"verse","number":"56","sanskrit":"बहुभुक्ताम्रनेत्रश्च स्वप्ने ज्योतींषि पश्यति एवंविधो भवेद्यस्तु पित्तप्रकृतिको नरः","text":"bahubhuktāmranetraśca svapne jyotīṃṣi paśyati evaṃvidho bhavedyastu pittaprakṛtiko naraḥ"},{"type":"verse","number":"57","sanskrit":"श्यामकेशः क्षमी स्थूलो बहुवीर्यो महाबलः स्वप्ने जलाशयालोकी श्लेष्मप्रकृतिको नरः","text":"śyāmakeśaḥ kṣamī sthūlo bahuvīryo mahābalaḥ svapne jalāśayālokī śleṣmaprakṛtiko naraḥ"},{"type":"verse","number":"58","sanskrit":"दृश्यते प्रकृतौ यत्र रूपं दोषद्वयस्य तु द्विसंसर्गेण जानीयात्सर्वलिङ्गैस्त्रिदोषजम्","text":"dṛśyate prakṛtau yatra rūpaṃ doṣadvayasya tu dvisaṃsargeṇa jānīyātsarvaliṅgaistridoṣajam"},{"type":"verse","number":"59","sanskrit":"विभुत्वादाशुकारित्वाद्वलित्वादन्यकोपनात् स्वातन्त्र्याद्बहुरोगत्वाद्दोषाणां प्रबलोऽनिलः","text":"vibhutvādāśukāritvādvalitvādanyakopanāt svātantryādbahurogatvāddoṣāṇāṃ prabalo'nilaḥ"},{"type":"verse","number":"60","sanskrit":"प्रायोऽत एव पवनाध्युषिता मनुष्या दोषात्मकाः स्फुटितधूसरकेशगात्राः शीतद्विषश्चलधृतिस्मृतिबुद्धिचेष्टासौहार्ददृष्टिगतयोऽतिबहुप्रलापाः","text":"prāyo'ta eva pavanādhyuṣitā manuṣyā doṣātmakāḥ sphuṭitadhūsarakeśagātrāḥ śītadviṣaścaladhṛtismṛtibuddhiceṣṭāsauhārdadṛṣṭigatayo'tibahupralāpāḥ"},{"type":"verse","number":"61","sanskrit":"अल्पपित्तबलजीवितनिद्राः सन्नसक्तचलजर्जरवाचः नास्तिका बहुभुजः सविलासा गीतहास्यमृगयाकलिलोलाः","text":"alpapittabalajīvitanidrāḥ sannasaktacalajarjaravācaḥ nāstikā bahubhujaḥ savilāsā gītahāsyamṛgayākalilolāḥ"},{"type":"verse","number":"62","sanskrit":"मधुराम्लपटूष्णसात्म्यकांक्षाः कृशदीर्घाकृतयः सशब्दयाताः न दृढा न जितेन्द्रि या न चार्या न च कान्तादयिता बहुप्रजा वा","text":"madhurāmlapaṭūṣṇasātmyakāṃkṣāḥ kṛśadīrghākṛtayaḥ saśabdayātāḥ na dṛḍhā na jitendri yā na cāryā na ca kāntādayitā bahuprajā vā"},{"type":"verse","number":"63","sanskrit":"नेत्राणि चैषां खरधूसराणि वृत्तान्यचारूणि मृतोपमानि उन्मीलितानीव भवन्ति सुप्ते शैलद्रुमांस्ते गगनं च यान्ति","text":"netrāṇi caiṣāṃ kharadhūsarāṇi vṛttānyacārūṇi mṛtopamāni unmīlitānīva bhavanti supte śailadrumāṃste gaganaṃ ca yānti"},{"type":"verse","number":"64","sanskrit":"अधन्या मत्सराध्माताः स्तेना प्रोद्बद्धपिण्डिकाः श्वशृगालोष्ट्रगृध्राखुकाकानूकाश्च वातिकाः","text":"adhanyā matsarādhmātāḥ stenā prodbaddhapiṇḍikāḥ śvaśṛgāloṣṭragṛdhrākhukākānūkāśca vātikāḥ"},{"type":"verse","number":"65","sanskrit":"पित्तं वह्निर्वह्निजं वा यदस्मात्पित्तोद्रि क्तस्तीक्ष्णतृष्णाबुभुक्षः गौरोष्णाङ्गस्ताम्रहस्ताङ्घ्रिवक्त्रः शूरो मानी पिङ्गकेशोऽल्परोमा","text":"pittaṃ vahnirvahnijaṃ vā yadasmātpittodri ktastīkṣṇatṛṣṇābubhukṣaḥ gauroṣṇāṅgastāmrahastāṅghrivaktraḥ śūro mānī piṅgakeśo'lparomā"},{"type":"verse","number":"66","sanskrit":"दयितमाल्यविलेपनमण्डनः सुचरितः शुचिराश्रितवत्सलः विभवसाहसबुद्धिबलान्वितो भवति भीषु गतिर्द्विषतामपि","text":"dayitamālyavilepanamaṇḍanaḥ sucaritaḥ śucirāśritavatsalaḥ vibhavasāhasabuddhibalānvito bhavati bhīṣu gatirdviṣatāmapi"},{"type":"verse","number":"67","sanskrit":"मेधावी प्रशिथिलसन्धिबन्धमांसो नारीणामनभिमतोऽल्पशुक्रकामः आवासः पलिततरंगनीलिकानां भुक्तान्नं मधुरकषायतिक्तशीतम्","text":"medhāvī praśithilasandhibandhamāṃso nārīṇāmanabhimato'lpaśukrakāmaḥ āvāsaḥ palitataraṃganīlikānāṃ bhuktānnaṃ madhurakaṣāyatiktaśītam"},{"type":"verse","number":"68","sanskrit":"धर्मद्वेषी स्वेदनः पूतिगन्धिर्भूर्युच्चारक्रोधपानाशनेर्ष्यः सुप्तं पश्येत्कर्णिकारान् पलाशान् दिग्दाहोल्काविद्युदर्कानलांश्च","text":"dharmadveṣī svedanaḥ pūtigandhirbhūryuccārakrodhapānāśanerṣyaḥ suptaṃ paśyetkarṇikārān palāśān digdāholkāvidyudarkānalāṃśca"},{"type":"verse","number":"69","sanskrit":"तनूनि पिङ्गानि चलानि चैषां तन्वल्पपक्ष्माणि हिमप्रियाणि क्रोधेन मद्येन रवेश्च भासा रागं व्रजन्त्याशु विलोचनानि","text":"tanūni piṅgāni calāni caiṣāṃ tanvalpapakṣmāṇi himapriyāṇi krodhena madyena raveśca bhāsā rāgaṃ vrajantyāśu vilocanāni"},{"type":"verse","number":"70","sanskrit":"मध्यायुषो मध्यबलाः पण्डिताः क्लेशभीरवः व्याघ्रर्क्षकपिमार्जारवृकानूकाश्च पैत्तिकाः","text":"madhyāyuṣo madhyabalāḥ paṇḍitāḥ kleśabhīravaḥ vyāghrarkṣakapimārjāravṛkānūkāśca paittikāḥ"},{"type":"verse","number":"71","sanskrit":"श्लेष्मा सोमं श्लेष्मलस्तेन सौम्यो गूढस्निग्धश्लिष्टसन्ध्यस्थिमांसः क्षुत्तृड्दुःखक्लेशधर्मैरतप्तो बुद्ध्या युक्तः सात्त्विकः सत्यसन्धः","text":"śleṣmā somaṃ śleṣmalastena saumyo gūḍhasnigdhaśliṣṭasandhyasthimāṃsaḥ kṣuttṛḍduḥkhakleśadharmairatapto buddhyā yuktaḥ sāttvikaḥ satyasandhaḥ"},{"type":"verse","number":"72","sanskrit":"प्रियंगुदूर्वाशरकाण्डदर्भगोरोचनापद्मसुवर्णवर्णः प्रलम्बबाहुः पृथुपीनवक्षा महाललाटो घननीलकेशः","text":"priyaṃgudūrvāśarakāṇḍadarbhagorocanāpadmasuvarṇavarṇaḥ pralambabāhuḥ pṛthupīnavakṣā mahālalāṭo ghananīlakeśaḥ"},{"type":"verse","number":"73","sanskrit":"मृद्वङ्गः समसुविभक्तचारुदेहो बह्वोजोरतिरसशुक्रपुत्रभृत्यः धर्मात्मा वदति न निष्ठुरं च जातु प्रच्छन्नं वहति दृढं चिरं च वैरम्","text":"mṛdvaṅgaḥ samasuvibhaktacārudeho bahvojoratirasaśukraputrabhṛtyaḥ dharmātmā vadati na niṣṭhuraṃ ca jātu pracchannaṃ vahati dṛḍhaṃ ciraṃ ca vairam"},{"type":"verse","number":"74","sanskrit":"समदद्विरदेन्द्र तुल्ययातो जलदाम्भोधिमृदङ्गसिंहघोषः स्मृतिमानभियोगवान्विनीतो न च बाल्येऽप्यतिरोदनो न लोलः","text":"samadadviradendra tulyayāto jaladāmbhodhimṛdaṅgasiṃhaghoṣaḥ smṛtimānabhiyogavānvinīto na ca bālye'pyatirodano na lolaḥ"},{"type":"verse","number":"75","sanskrit":"तिक्तं कषायं कटुकोष्णरूक्षमल्पं स भुंक्ते बलवांस्तथाऽपि रक्तान्तसुस्निग्धविशालदीर्घसुव्यक्तशुक्लासितपक्ष्मलाक्षः","text":"tiktaṃ kaṣāyaṃ kaṭukoṣṇarūkṣamalpaṃ sa bhuṃkte balavāṃstathā'pi raktāntasusnigdhaviśāladīrghasuvyaktaśuklāsitapakṣmalākṣaḥ"},{"type":"verse","number":"76","sanskrit":"अल्पव्याहारक्रोधपानाशनेर्ष्यः प्राज्यायुर्वित्तो दीर्घदर्शी वदान्यः श्राद्धो गम्भीरः स्थूललक्ष्यः क्षमावानार्योनिद्रा लुर्दीर्घसूत्रः कृतज्ञः","text":"alpavyāhārakrodhapānāśanerṣyaḥ prājyāyurvitto dīrghadarśī vadānyaḥ śrāddho gambhīraḥ sthūlalakṣyaḥ kṣamāvānāryonidrā lurdīrghasūtraḥ kṛtajñaḥ"},{"type":"verse","number":"77","sanskrit":"ऋजुर्विपश्चित्सुभगः सलज्जो भक्तो गुरूणां स्थिरसौहृदश्च स्वप्ने सपद्मान्सविहङ्गमालांस्तोयाशयान्पश्यति तोयदांश्च","text":"ṛjurvipaścitsubhagaḥ salajjo bhakto gurūṇāṃ sthirasauhṛdaśca svapne sapadmānsavihaṅgamālāṃstoyāśayānpaśyati toyadāṃśca"},{"type":"verse","number":"78","sanskrit":"ब्रह्मरुद्रे न्द्र वरुणतार्क्ष्यहंसगजाधिपैः श्लेष्मप्रकृतयस्तुल्यास्तथा सिंहाश्वगोवृषैः","text":"brahmarudre ndra varuṇatārkṣyahaṃsagajādhipaiḥ śleṣmaprakṛtayastulyāstathā siṃhāśvagovṛṣaiḥ"},{"type":"verse","number":"79","sanskrit":"विषजातो यथा कीटो न विषेण प्रबाध्यते तद्वत्प्रकृतयो मर्त्यं शक्नुवन्ति न बाधितुम्","text":"viṣajāto yathā kīṭo na viṣeṇa prabādhyate tadvatprakṛtayo martyaṃ śaknuvanti na bādhitum"},{"type":"verse","number":"80","sanskrit":"प्रकोपो वाऽन्यभावो वा शमो वा नोपजायते प्रकृतीनां स्वभावेन जायते तु गतायुषः","text":"prakopo vā'nyabhāvo vā śamo vā nopajāyate prakṛtīnāṃ svabhāvena jāyate tu gatāyuṣaḥ"},{"type":"verse","number":"81","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमन्मिश्रभाव विरचिते भावप्रकाशे बालप्रकरणं चतुर्थम् ४ अथ पञ्चमं दिनचर्यादिप्रकरणम् ५ भूमिदेशस्त्रिधाऽनूपो जांगलो मिश्रलक्षणः","text":"iti śrīmiśralaṭakana tanaya śrīmanmiśrabhāva viracite bhāvaprakāśe bālaprakaraṇaṃ caturtham 4 atha pañcamaṃ dinacaryādiprakaraṇam 5 bhūmideśastridhā'nūpo jāṃgalo miśralakṣaṇaḥ"},{"type":"verse","number":"82","sanskrit":"नदीपल्वलशैलाढ्यः फुल्लोत्पलकुलैर्युतः हंससारसकारंडचक्रवाकादिसेवितः","text":"nadīpalvalaśailāḍhyaḥ phullotpalakulairyutaḥ haṃsasārasakāraṃḍacakravākādisevitaḥ"},{"type":"verse","number":"83","sanskrit":"शशवाराहमहिषरुरुरोहिकुलाकुलः प्रभूतद्रुमपुष्पाढ्यो नीलशस्यफलान्वितः","text":"śaśavārāhamahiṣarururohikulākulaḥ prabhūtadrumapuṣpāḍhyo nīlaśasyaphalānvitaḥ"},{"type":"verse","number":"84","sanskrit":"अनेकशालिकेदारकदलीक्षुविभूषितः अनूपदेशो ज्ञातव्यो वातश्लेष्मामयार्त्तिमान्","text":"anekaśālikedārakadalīkṣuvibhūṣitaḥ anūpadeśo jñātavyo vātaśleṣmāmayārttimān"},{"type":"verse","number":"85","sanskrit":"आकाशसम उच्चश्च स्वल्पपानीयपादपः शमीकरीरबिल्वार्कपीलुकर्कंधुसङ्कुलः","text":"ākāśasama uccaśca svalpapānīyapādapaḥ śamīkarīrabilvārkapīlukarkaṃdhusaṅkulaḥ"},{"type":"verse","number":"86","sanskrit":"हरिणैणर्क्षपृषतगोकर्णखरसङ्कुलः सुस्वादुफलवान्देशो वातलो जाङ्गलः स्मृतः","text":"hariṇaiṇarkṣapṛṣatagokarṇakharasaṅkulaḥ susvāduphalavāndeśo vātalo jāṅgalaḥ smṛtaḥ"},{"type":"verse","number":"87","sanskrit":"बहूदकनगोऽनूपः कफमारुतरोगवान् जाङ्गलोऽल्पाम्बुशाखी च पित्तासृङ्मारुतोत्तरः","text":"bahūdakanago'nūpaḥ kaphamārutarogavān jāṅgalo'lpāmbuśākhī ca pittāsṛṅmārutottaraḥ"},{"type":"verse","number":"88","sanskrit":"संसृष्टलक्षणो यस्तु देशः साधारणो मतः समाः सधारणे यस्माच्छीतवर्षोष्णमारुताः समता तेन दोषाणां तस्मात्साधारणो वरः","text":"saṃsṛṣṭalakṣaṇo yastu deśaḥ sādhāraṇo mataḥ samāḥ sadhāraṇe yasmācchītavarṣoṣṇamārutāḥ samatā tena doṣāṇāṃ tasmātsādhāraṇo varaḥ"},{"type":"verse","number":"89","sanskrit":"उचिते वर्तमानस्य नास्ति दुर्देशजं भयम् आहारस्वप्नचेष्टाऽदौ तद्देशस्य कृते सति","text":"ucite vartamānasya nāsti durdeśajaṃ bhayam āhārasvapnaceṣṭā'dau taddeśasya kṛte sati"},{"type":"verse","number":"90","sanskrit":"यस्य देशस्य यो जन्तुस्तज्जं तस्यौषधं हितम् देशादन्यत्र वसतस्तत्तुल्यगुणमौषधम्","text":"yasya deśasya yo jantustajjaṃ tasyauṣadhaṃ hitam deśādanyatra vasatastattulyaguṇamauṣadham"},{"type":"verse","number":"91","sanskrit":"स्वे देशेनिचिता दोषा अन्यस्मिन्कोपमागताः बलवन्तस्तथा न स्युर्जलजाः स्थलजास्तथा","text":"sve deśenicitā doṣā anyasminkopamāgatāḥ balavantastathā na syurjalajāḥ sthalajāstathā"},{"type":"verse","number":"92","sanskrit":"मानवो येन विधिना स्वस्थस्तिष्ठति सर्वदा तमेव कारयेद्वैद्यो यतः स्वास्थ्यं सदेप्सितम्","text":"mānavo yena vidhinā svasthastiṣṭhati sarvadā tameva kārayedvaidyo yataḥ svāsthyaṃ sadepsitam"},{"type":"verse","number":"93","sanskrit":"दिनचर्यां निशाचर्यामृतुचर्यां यथोदिताम् आचरन्पुरुषः स्वस्थः सदा तिष्ठति नान्यथा","text":"dinacaryāṃ niśācaryāmṛtucaryāṃ yathoditām ācaranpuruṣaḥ svasthaḥ sadā tiṣṭhati nānyathā"},{"type":"verse","number":"94","sanskrit":"समदोषः समाग्निश्च समधातुमलक्रियः प्रसन्नात्मेन्द्रि यमनाः स्वस्थ इत्यभिधीयते","text":"samadoṣaḥ samāgniśca samadhātumalakriyaḥ prasannātmendri yamanāḥ svastha ityabhidhīyate"},{"type":"verse","number":"95","sanskrit":"ब्राह्मे मुहूर्ते बुध्येत स्वस्थो रक्षाऽथमायुषः तत्र सर्वाघशान्त्यर्थं स्मरेद्धि मधुसूदनम्","text":"brāhme muhūrte budhyeta svastho rakṣā'thamāyuṣaḥ tatra sarvāghaśāntyarthaṃ smareddhi madhusūdanam"},{"type":"verse","number":"96","sanskrit":"दध्याज्यादर्शसिद्धार्थं बिल्वगोरोचनस्रजाम् दर्शनं स्पर्शनं कार्यं प्रबुद्धेन शुभावहम्","text":"dadhyājyādarśasiddhārthaṃ bilvagorocanasrajām darśanaṃ sparśanaṃ kāryaṃ prabuddhena śubhāvaham"},{"type":"verse","number":"97","sanskrit":"स्वमाननं घृते पश्येद् यदीच्छेच्चिरजीवितम् आयुष्यमुषसि प्रोक्तं मलादीनां विसर्जनम् तदन्त्रकूजनाध्मानोदरगौरववारणम्","text":"svamānanaṃ ghṛte paśyed yadīccheccirajīvitam āyuṣyamuṣasi proktaṃ malādīnāṃ visarjanam tadantrakūjanādhmānodaragauravavāraṇam"},{"type":"verse","number":"98","sanskrit":"आटोपशूलौ परिकर्त्तिका च सङ्गः पुरीषस्य तथोर्ध्ववातः पुरीषमास्यादथवा निरेति पुरीषवेगेऽभिहते नरस्य","text":"āṭopaśūlau parikarttikā ca saṅgaḥ purīṣasya tathordhvavātaḥ purīṣamāsyādathavā nireti purīṣavege'bhihate narasya"},{"type":"verse","number":"99","sanskrit":"वातमूत्रपुरीषाणां सङ्गो ध्मानं क्लमो रुजा जठरे वातजाश्चान्येरोगाः स्युर्वातनिग्रहात्","text":"vātamūtrapurīṣāṇāṃ saṅgo dhmānaṃ klamo rujā jaṭhare vātajāścānyerogāḥ syurvātanigrahāt"},{"type":"verse","number":"100","sanskrit":"बस्तिमेहनयोः शूलं मूत्रकृच्छ्रं शिरोरुजा विनामो वङ्क्षणानाहः स्यालिङ्गं मूत्रनिग्रहे","text":"bastimehanayoḥ śūlaṃ mūtrakṛcchraṃ śirorujā vināmo vaṅkṣaṇānāhaḥ syāliṅgaṃ mūtranigrahe"},{"type":"verse","number":"101","sanskrit":"न वेगितोऽन्यकार्यः स्यान्न वेगानीरयेद्बलात् कामशोकभयक्रोधान्मनोवेगान्विधारयेत्","text":"na vegito'nyakāryaḥ syānna vegānīrayedbalāt kāmaśokabhayakrodhānmanovegānvidhārayet"},{"type":"verse","number":"102","sanskrit":"गुदादिमलमार्गाणां शौचं कान्तिबलप्रदम् पवित्रकरमाख्यातमलक्ष्मीकलिपापहृत्","text":"gudādimalamārgāṇāṃ śaucaṃ kāntibalapradam pavitrakaramākhyātamalakṣmīkalipāpahṛt"},{"type":"verse","number":"103","sanskrit":"प्रक्षालनं मतं पाण्योः पादयोः शुद्धिकारणम् मलश्रमहरं वृष्यं चक्षुष्यं राजसापहम्","text":"prakṣālanaṃ mataṃ pāṇyoḥ pādayoḥ śuddhikāraṇam malaśramaharaṃ vṛṣyaṃ cakṣuṣyaṃ rājasāpaham"},{"type":"verse","number":"104","sanskrit":"भक्षयेद्दन्तपवनं द्वादशाङ्गुलमायतम् कनिष्ठिकाऽग्रवत्स्थूलमृज्वग्रन्थिं तथाऽव्रणम्","text":"bhakṣayeddantapavanaṃ dvādaśāṅgulamāyatam kaniṣṭhikā'gravatsthūlamṛjvagranthiṃ tathā'vraṇam"},{"type":"verse","number":"105","sanskrit":"एकैकं घर्षयेद्दन्तं मृदुना कूर्चकेन तु दन्तशोधनचूर्णेन दन्तमांसान्यबाधयन्","text":"ekaikaṃ gharṣayeddantaṃ mṛdunā kūrcakena tu dantaśodhanacūrṇena dantamāṃsānyabādhayan"},{"type":"verse","number":"106","sanskrit":"क्षौद्र त्रिकटुकाक्तेन तैलसिन्धुभवेन वा चूर्णेन तेजोवत्याश्च दन्तान्नित्यं विशोधयेत्","text":"kṣaudra trikaṭukāktena tailasindhubhavena vā cūrṇena tejovatyāśca dantānnityaṃ viśodhayet"},{"type":"verse","number":"107","sanskrit":"मधुको मधुरे श्रेष्ठः करञ्जः कटुके तथा निम्बः स्यात्तिक्तके श्रेष्ठः कषाये खदिरस्तथा","text":"madhuko madhure śreṣṭhaḥ karañjaḥ kaṭuke tathā nimbaḥ syāttiktake śreṣṭhaḥ kaṣāye khadirastathā"},{"type":"verse","number":"108","sanskrit":"समयं तु समालोक्य दोषं च प्रकृतिं तथा यथोचितै रसैर्वीर्यैर्युक्तं द्र व्यं प्रयोजयेत्","text":"samayaṃ tu samālokya doṣaṃ ca prakṛtiṃ tathā yathocitai rasairvīryairyuktaṃ dra vyaṃ prayojayet"},{"type":"verse","number":"109","sanskrit":"तेनास्य मुखवैरस्यदन्तजिह्वाऽस्यजा गदाः रुचिवैशद्यलघुता न भवन्ति भवन्ति च","text":"tenāsya mukhavairasyadantajihvā'syajā gadāḥ rucivaiśadyalaghutā na bhavanti bhavanti ca"},{"type":"verse","number":"110","sanskrit":"अर्के वीर्यं वटे दीप्तिः करञ्जे विजयो भवेत् प्लक्षे चैवार्थसम्पत्तिर्वैदर्यां मधुरोध्वनिः","text":"arke vīryaṃ vaṭe dīptiḥ karañje vijayo bhavet plakṣe caivārthasampattirvaidaryāṃ madhurodhvaniḥ"},{"type":"verse","number":"111","sanskrit":"खदिरे मुखसौगन्ध्यं बिल्वे तु विपुलं धनम् उदुम्बरे तु वाक्सिद्धिराम्रे त्वारोग्यमेव च","text":"khadire mukhasaugandhyaṃ bilve tu vipulaṃ dhanam udumbare tu vāksiddhirāmre tvārogyameva ca"},{"type":"verse","number":"112","sanskrit":"कदम्बे तु धृतिर्मेधा चम्पके च दृढा मतिः शिरीषे कीर्त्तिसौभाग्यमायुरारोग्यमेव च","text":"kadambe tu dhṛtirmedhā campake ca dṛḍhā matiḥ śirīṣe kīrttisaubhāgyamāyurārogyameva ca"},{"type":"verse","number":"113","sanskrit":"अपामार्गे धृतिर्मेधा प्रज्ञाशक्तिस्तथाऽसने दाडिम्यां सुन्दराकारः ककुभे कुटजे तथा","text":"apāmārge dhṛtirmedhā prajñāśaktistathā'sane dāḍimyāṃ sundarākāraḥ kakubhe kuṭaje tathā"},{"type":"verse","number":"114","sanskrit":"जातीतगरमन्दारैर्दुःस्वप्नं च विनश्यति","text":"jātītagaramandārairduḥsvapnaṃ ca vinaśyati"},{"type":"verse","number":"115","sanskrit":"गुर्वाकस्तालहिन्तालौ केतकश्च बृहत्तृणः खर्जूरं नारिकेलं च सप्तैते तृणराजकाः","text":"gurvākastālahintālau ketakaśca bṛhattṛṇaḥ kharjūraṃ nārikelaṃ ca saptaite tṛṇarājakāḥ"},{"type":"verse","number":"116","sanskrit":"तृणराजसमुत्पन्नं यः कुर्याद्दन्तधावनम् नरश्चाण्डालयोनिः स्याद्यावद्गङ्गां न पश्यति","text":"tṛṇarājasamutpannaṃ yaḥ kuryāddantadhāvanam naraścāṇḍālayoniḥ syādyāvadgaṅgāṃ na paśyati"},{"type":"verse","number":"117","sanskrit":"न खादेद्गलताल्वोष्ठजिह्वादन्तगदेषु तत् मुखस्य पाके शोथे च श्वासकासवमीषु च","text":"na khādedgalatālvoṣṭhajihvādantagadeṣu tat mukhasya pāke śothe ca śvāsakāsavamīṣu ca"},{"type":"verse","number":"118","sanskrit":"दुर्बलोऽजीर्णभुक्तश्च हिक्कामूर्च्छामदान्वितः शिरोरुजार्तस्तृषितः श्रान्तः पानक्लमान्वितः","text":"durbalo'jīrṇabhuktaśca hikkāmūrcchāmadānvitaḥ śirorujārtastṛṣitaḥ śrāntaḥ pānaklamānvitaḥ"},{"type":"verse","number":"119","sanskrit":"अर्दितः कर्णशूली च नेत्ररोगी नवज्वरी वर्जयेद्दन्तकाष्ठं तु हृदामययुतोऽपि च","text":"arditaḥ karṇaśūlī ca netrarogī navajvarī varjayeddantakāṣṭhaṃ tu hṛdāmayayuto'pi ca"},{"type":"verse","number":"120","sanskrit":"जिह्वानिर्लेखनं हैमं राजतं ताम्रजं तथा पाटितं मृदु तत्काष्ठं मृदुपत्रमयं तथा","text":"jihvānirlekhanaṃ haimaṃ rājataṃ tāmrajaṃ tathā pāṭitaṃ mṛdu tatkāṣṭhaṃ mṛdupatramayaṃ tathā"},{"type":"verse","number":"121","sanskrit":"दशाङ्गुलं मृदु स्निग्धं तेन जिह्वां लिखेत्सुखम् तज्जिह्वामलवैरस्यदुर्गन्धजडताहरम्","text":"daśāṅgulaṃ mṛdu snigdhaṃ tena jihvāṃ likhetsukham tajjihvāmalavairasyadurgandhajaḍatāharam"},{"type":"verse","number":"122","sanskrit":"गण्डूषमपि कुर्वीत शीतेन पयसा मुहुः कफतृष्णामलहरं मुखान्तःशुद्धिकारकम्","text":"gaṇḍūṣamapi kurvīta śītena payasā muhuḥ kaphatṛṣṇāmalaharaṃ mukhāntaḥśuddhikārakam"},{"type":"verse","number":"123","sanskrit":"सुखोष्णोदकगण्डूषः कफारुचिमलापहः दन्तजाड्यहरश्चापि मुखलाघवकारकः","text":"sukhoṣṇodakagaṇḍūṣaḥ kaphārucimalāpahaḥ dantajāḍyaharaścāpi mukhalāghavakārakaḥ"},{"type":"verse","number":"124","sanskrit":"विषमूर्च्छामदार्त्तानां शोषिणां रक्तपित्तिनाम् कुपिताक्षिमलक्षीणरूक्षाणां स न शस्यते","text":"viṣamūrcchāmadārttānāṃ śoṣiṇāṃ raktapittinām kupitākṣimalakṣīṇarūkṣāṇāṃ sa na śasyate"},{"type":"verse","number":"125","sanskrit":"मुखप्रक्षालनं शीतपयसा रक्तपित्तजित् मुखस्य पिडिकाशोषनीलिकाव्यङ्गनाशनम्","text":"mukhaprakṣālanaṃ śītapayasā raktapittajit mukhasya piḍikāśoṣanīlikāvyaṅganāśanam"},{"type":"verse","number":"126","sanskrit":"कुर्याद्वाऽपि कदुष्णेन पयसाऽस्यविशोधनम् कफवातहरं स्निग्धं मुखशोषविनाशनम्","text":"kuryādvā'pi kaduṣṇena payasā'syaviśodhanam kaphavātaharaṃ snigdhaṃ mukhaśoṣavināśanam"},{"type":"verse","number":"127","sanskrit":"कटुतैलादि नस्यार्थे नित्याभ्यासेन योजयेत् प्रातः श्लेष्मणि मध्याह्ने पित्ते सायं समीरणे","text":"kaṭutailādi nasyārthe nityābhyāsena yojayet prātaḥ śleṣmaṇi madhyāhne pitte sāyaṃ samīraṇe"},{"type":"verse","number":"128","sanskrit":"सुगन्धवदनाः स्निग्धनिःस्वना विमलेन्द्रि याः निर्बलीपलितव्यङ्गा भवेयुर्नस्यशीलिनः","text":"sugandhavadanāḥ snigdhaniḥsvanā vimalendri yāḥ nirbalīpalitavyaṅgā bhaveyurnasyaśīlinaḥ"},{"type":"verse","number":"129","sanskrit":"सौवीरमञ्जनं नित्यं हितमक्ष्णोस्ततो भजेत् लोचने भवतस्तेन मनोज्ञे सूक्ष्मदर्शने","text":"sauvīramañjanaṃ nityaṃ hitamakṣṇostato bhajet locane bhavatastena manojñe sūkṣmadarśane"},{"type":"verse","number":"130","sanskrit":"स्रोतोऽञ्जनं मतं श्रेष्ठं विशुद्धं सिन्धुसम्भवम् दृष्टेः कण्डूमलहरं दाहक्लेदरुजापहम्","text":"sroto'ñjanaṃ mataṃ śreṣṭhaṃ viśuddhaṃ sindhusambhavam dṛṣṭeḥ kaṇḍūmalaharaṃ dāhakledarujāpaham"},{"type":"verse","number":"131","sanskrit":"अक्ष्णो रूपावहं चैव सहते मारुतातपौ नेत्रे रोगा न जायन्ते तस्मादञ्जनमाचरेत्","text":"akṣṇo rūpāvahaṃ caiva sahate mārutātapau netre rogā na jāyante tasmādañjanamācaret"},{"type":"verse","number":"132","sanskrit":"रात्रौ जागरितः श्रान्तश्छर्दितो भुक्तवांस्तथा ज्वरातुरः शिरः स्नातो नाक्ष्णोरञ्जनमाचरेत्","text":"rātrau jāgaritaḥ śrāntaśchardito bhuktavāṃstathā jvarāturaḥ śiraḥ snāto nākṣṇorañjanamācaret"},{"type":"verse","number":"133","sanskrit":"पञ्चरात्रान्नखश्मश्रुकेशरोमाणि कर्त्तयेत् केशश्मश्रुनखादीनां कर्त्तनं सम्प्रसाधनम् पौष्टिकं धन्यमायुष्यं शौचकान्तिकरं परम्","text":"pañcarātrānnakhaśmaśrukeśaromāṇi karttayet keśaśmaśrunakhādīnāṃ karttanaṃ samprasādhanam pauṣṭikaṃ dhanyamāyuṣyaṃ śaucakāntikaraṃ param"},{"type":"verse","number":"134","sanskrit":"उत्पाटयेत्तु लोमानि नासाया न कदाचन तदुत्पाटनतो दृष्टेर्दौर्बल्यं त्वरया भवेत्","text":"utpāṭayettu lomāni nāsāyā na kadācana tadutpāṭanato dṛṣṭerdaurbalyaṃ tvarayā bhavet"},{"type":"verse","number":"135","sanskrit":"केशपाशे प्रकुर्वीत प्रसाधन्या प्रसाधनम् केशप्रसाधनं केश्यं रजोजन्तुमलापहम्","text":"keśapāśe prakurvīta prasādhanyā prasādhanam keśaprasādhanaṃ keśyaṃ rajojantumalāpaham"},{"type":"verse","number":"136","sanskrit":"आदर्शालोकनं प्रोक्तं मङ्गल्यं कान्तिकारम् पौष्टिकं बल्यमायुष्यं पापालक्ष्मीविनाशनम्","text":"ādarśālokanaṃ proktaṃ maṅgalyaṃ kāntikāram pauṣṭikaṃ balyamāyuṣyaṃ pāpālakṣmīvināśanam"},{"type":"verse","number":"137","sanskrit":"लाघवं कर्मसमर्थ्यं विभक्तघनगात्रता दोषक्षयोऽग्निवृद्धिश्च व्यायामादुपजायते","text":"lāghavaṃ karmasamarthyaṃ vibhaktaghanagātratā doṣakṣayo'gnivṛddhiśca vyāyāmādupajāyate"},{"type":"verse","number":"138","sanskrit":"व्यायामदृढगात्रस्य व्याधिर्नास्ति कदाचन विरुद्धं वा विदग्धं वा भुक्तं शीघ्रं विपच्यते","text":"vyāyāmadṛḍhagātrasya vyādhirnāsti kadācana viruddhaṃ vā vidagdhaṃ vā bhuktaṃ śīghraṃ vipacyate"},{"type":"verse","number":"139","sanskrit":"भवन्ति शीघ्रं नैतस्य देहे शिथिलतादयः न चैवं सहसाऽक्रम्य जरा समधिरोहति","text":"bhavanti śīghraṃ naitasya dehe śithilatādayaḥ na caivaṃ sahasā'kramya jarā samadhirohati"},{"type":"verse","number":"140","sanskrit":"न चास्ति सदृशं तेन किञ्चित्स्थौल्यापकर्षकम् स सदा गुणमाधत्ते बलिनां स्निग्धभोजिनाम्","text":"na cāsti sadṛśaṃ tena kiñcitsthaulyāpakarṣakam sa sadā guṇamādhatte balināṃ snigdhabhojinām"},{"type":"verse","number":"141","sanskrit":"वसन्ते शीतसमये सुतरां स हितो मतः अन्यदाऽपि च कर्त्तव्यो बलार्धेन यथा बलम्","text":"vasante śītasamaye sutarāṃ sa hito mataḥ anyadā'pi ca karttavyo balārdhena yathā balam"},{"type":"verse","number":"142","sanskrit":"हृदयस्थो यदा वायुर्वक्त्रं शीघ्रं प्रपद्यते मुखं च शोषं लभते तद्बलार्धस्य लक्षणम्","text":"hṛdayastho yadā vāyurvaktraṃ śīghraṃ prapadyate mukhaṃ ca śoṣaṃ labhate tadbalārdhasya lakṣaṇam"},{"type":"verse","number":"143","sanskrit":"किं वा ललाटे नासायां गात्रसन्धिषु कक्षयोः यदा सञ्जायते स्वेदो बलार्धं तु तदादिशेत्","text":"kiṃ vā lalāṭe nāsāyāṃ gātrasandhiṣu kakṣayoḥ yadā sañjāyate svedo balārdhaṃ tu tadādiśet"},{"type":"verse","number":"144","sanskrit":"भुक्तवान्कृतसम्भोगः कासी श्वासी कृशः क्षयी रक्तपित्ती क्षती शोषी न तं कुर्यात्कदाचन","text":"bhuktavānkṛtasambhogaḥ kāsī śvāsī kṛśaḥ kṣayī raktapittī kṣatī śoṣī na taṃ kuryātkadācana"},{"type":"verse","number":"145","sanskrit":"अतिव्यायामतः कासो ज्वरश्छर्दिं श्रमः क्लमः तृष्णा क्षयः प्रतमको रक्तपित्तं च जायते","text":"ativyāyāmataḥ kāso jvaraśchardiṃ śramaḥ klamaḥ tṛṣṇā kṣayaḥ pratamako raktapittaṃ ca jāyate"},{"type":"verse","number":"146","sanskrit":"अभ्यङ्गं कारयेन्नित्यं सर्वेष्वङ्गेषु पुष्टिदम् शिरः श्रवणपादेषु तं विशेषेण शीलयेत्","text":"abhyaṅgaṃ kārayennityaṃ sarveṣvaṅgeṣu puṣṭidam śiraḥ śravaṇapādeṣu taṃ viśeṣeṇa śīlayet"},{"type":"verse","number":"147","sanskrit":"सार्षपं गन्धतैलं च यत्तैलं पुष्पवासितम् अन्यद्र व्ययुतं तैलं न दुष्यति कदाचन","text":"sārṣapaṃ gandhatailaṃ ca yattailaṃ puṣpavāsitam anyadra vyayutaṃ tailaṃ na duṣyati kadācana"},{"type":"verse","number":"148","sanskrit":"अभ्यङ्गो वातकफहृच्छ्रमशान्तिबलं सुखम् निद्रा वर्णमृदुत्वायुष्कुरुते देहपुष्टिकृत्","text":"abhyaṅgo vātakaphahṛcchramaśāntibalaṃ sukham nidrā varṇamṛdutvāyuṣkurute dehapuṣṭikṛt"},{"type":"verse","number":"149","sanskrit":"अभ्यङ्गः शीलितो मूर्ध्नि सकलेन्द्रि यतर्पकः दृष्टितुष्टिकरो हन्ति शिरोभूमिगतान्गदान्","text":"abhyaṅgaḥ śīlito mūrdhni sakalendri yatarpakaḥ dṛṣṭituṣṭikaro hanti śirobhūmigatāngadān"},{"type":"verse","number":"150","sanskrit":"केशानां बहुतां दार्ढ्यं मृदुतां दीर्घतां तथा कृष्णतां कुरुते कुर्याच्छिरसःपूर्णतामपि","text":"keśānāṃ bahutāṃ dārḍhyaṃ mṛdutāṃ dīrghatāṃ tathā kṛṣṇatāṃ kurute kuryācchirasaḥpūrṇatāmapi"},{"type":"verse","number":"151","sanskrit":"न कर्णरोगा न मलं न च मन्याहनुग्रहः नोच्चैः श्रुतिर्न बाधिर्यं स्यान्नित्यं कर्णपूरणात्","text":"na karṇarogā na malaṃ na ca manyāhanugrahaḥ noccaiḥ śrutirna bādhiryaṃ syānnityaṃ karṇapūraṇāt"},{"type":"verse","number":"152","sanskrit":"रसाद्यैः पूरणं कर्णे भोजनात्प्राक्प्रशस्यते तैलाद्यैः पूरणं कर्णे भास्करेऽस्तमुपागते","text":"rasādyaiḥ pūraṇaṃ karṇe bhojanātprākpraśasyate tailādyaiḥ pūraṇaṃ karṇe bhāskare'stamupāgate"},{"type":"verse","number":"153","sanskrit":"पादाभ्यङ्गश्च तत्स्थैर्यनिद्रा दृष्टिप्रसादकृत् पादसुप्तिश्रमस्तम्भसङ्कोचस्फुटनप्रणुत्","text":"pādābhyaṅgaśca tatsthairyanidrā dṛṣṭiprasādakṛt pādasuptiśramastambhasaṅkocasphuṭanapraṇut"},{"type":"verse","number":"154","sanskrit":"व्यायामक्षुण्णवपुषं पद्भ्यां सम्मर्दितं तथा व्याधयो नोपसर्पन्ति वैनतेयमिवोरगाः","text":"vyāyāmakṣuṇṇavapuṣaṃ padbhyāṃ sammarditaṃ tathā vyādhayo nopasarpanti vainateyamivoragāḥ"},{"type":"verse","number":"155","sanskrit":"लोमकूपशिराजालधमनीभिः कलेवरे तर्पयेद्बलमाधत्ते स्नेहयुक्तेऽवगाहने","text":"lomakūpaśirājāladhamanībhiḥ kalevare tarpayedbalamādhatte snehayukte'vagāhane"},{"type":"verse","number":"156","sanskrit":"अद्भिः संसिक्तमूलानां तरूणां पल्लवादयः वर्द्धन्ते हि तथा नॄणां स्नेहसंसिक्तधातवः","text":"adbhiḥ saṃsiktamūlānāṃ tarūṇāṃ pallavādayaḥ varddhante hi tathā nṝṇāṃ snehasaṃsiktadhātavaḥ"},{"type":"verse","number":"157","sanskrit":"नवज्वरी अजीर्णी च नाभ्यक्तव्यः कथञ्चन तथा विरिक्तो वान्तश्च निरूढो यश्च मानवः","text":"navajvarī ajīrṇī ca nābhyaktavyaḥ kathañcana tathā virikto vāntaśca nirūḍho yaśca mānavaḥ"},{"type":"verse","number":"158","sanskrit":"पूर्वयोः कृच्छ्रता व्याधेरसाध्यत्वमथापि वा शेषाणां च त्विह प्रोक्ता वह्निसादादयो गदाः","text":"pūrvayoḥ kṛcchratā vyādherasādhyatvamathāpi vā śeṣāṇāṃ ca tviha proktā vahnisādādayo gadāḥ"},{"type":"verse","number":"159","sanskrit":"उद्वर्त्तनं कफहरं मेदोघ्नं शुक्रदं परम् बल्यं शोणितकृच्चापि त्वक्प्रसादमृदुत्वकृत्","text":"udvarttanaṃ kaphaharaṃ medoghnaṃ śukradaṃ param balyaṃ śoṇitakṛccāpi tvakprasādamṛdutvakṛt"},{"type":"verse","number":"160","sanskrit":"मुखलेपादृढं चक्षुः पीनो गण्डस्तथाऽननम् कान्तमव्यङ्गपिडकं भवेत्कमलसन्निभम्","text":"mukhalepādṛḍhaṃ cakṣuḥ pīno gaṇḍastathā'nanam kāntamavyaṅgapiḍakaṃ bhavetkamalasannibham"},{"type":"verse","number":"161","sanskrit":"दीपनंवृष्यमायुष्यं स्नानमोजोबलप्रदम् कण्डूमलश्रमस्वेदतन्द्रा तृड्दाहपाप्मनुत्","text":"dīpanaṃvṛṣyamāyuṣyaṃ snānamojobalapradam kaṇḍūmalaśramasvedatandrā tṛḍdāhapāpmanut"},{"type":"verse","number":"162","sanskrit":"बाह्यैश्च सेकैः शीताद्यैरूष्माऽन्तर्याति पीडितः नरस्य स्नानमात्रस्य दीप्यते तेन पावकः","text":"bāhyaiśca sekaiḥ śītādyairūṣmā'ntaryāti pīḍitaḥ narasya snānamātrasya dīpyate tena pāvakaḥ"},{"type":"verse","number":"163","sanskrit":"शीतेन पयसा स्नानं रक्तपित्तप्रशान्तिकृत् तदेवोष्णेन तोयेन बल्यं वातकफापहम्","text":"śītena payasā snānaṃ raktapittapraśāntikṛt tadevoṣṇena toyena balyaṃ vātakaphāpaham"},{"type":"verse","number":"164","sanskrit":"शिरः स्नानमचक्षुष्यमत्युष्णेनाग्बुना सदा वातश्लेष्मप्रकोपे तु हितं तच्च प्रकीर्त्तितम्","text":"śiraḥ snānamacakṣuṣyamatyuṣṇenāgbunā sadā vātaśleṣmaprakope tu hitaṃ tacca prakīrttitam"},{"type":"verse","number":"165","sanskrit":"अशीतेनाम्भसा स्नानं पयःपानं नवाःस्त्रियः एतद्वो मानवाः पथ्यं स्निग्धमल्पं च भोजनम्","text":"aśītenāmbhasā snānaṃ payaḥpānaṃ navāḥstriyaḥ etadvo mānavāḥ pathyaṃ snigdhamalpaṃ ca bhojanam"},{"type":"verse","number":"166","sanskrit":"यः सदाऽमलकैः स्नानं करोति स विनिश्चितम् बलीपलितनिर्मुक्तो जीवेद्वर्षशतं नरः","text":"yaḥ sadā'malakaiḥ snānaṃ karoti sa viniścitam balīpalitanirmukto jīvedvarṣaśataṃ naraḥ"},{"type":"verse","number":"167","sanskrit":"स्नानं ज्वरेऽतिसारे च नेत्रकर्णानिलार्तिषु आध्मानपीनसाजीर्णभुक्तवत्सु च गर्हितम्","text":"snānaṃ jvare'tisāre ca netrakarṇānilārtiṣu ādhmānapīnasājīrṇabhuktavatsu ca garhitam"},{"type":"verse","number":"168","sanskrit":"स्नानस्यानन्तरं सम्यग्वस्त्रेणाङ्गस्य मार्जनम् कान्तिप्रदं शरीरस्य कण्डूत्वग्दोषनाशनम्","text":"snānasyānantaraṃ samyagvastreṇāṅgasya mārjanam kāntipradaṃ śarīrasya kaṇḍūtvagdoṣanāśanam"},{"type":"verse","number":"169","sanskrit":"कौशेयौर्णिकवस्त्रं च रक्तवस्त्रं तथैव च वातश्लेष्महरं तत्तु शीतकाले विधारयेत्","text":"kauśeyaurṇikavastraṃ ca raktavastraṃ tathaiva ca vātaśleṣmaharaṃ tattu śītakāle vidhārayet"},{"type":"verse","number":"170","sanskrit":"मेध्यं सुशीतं पित्तघ्नं कषायं वस्त्रमुच्यते तद्धारयेदुष्णकाले तत्रापि लघु शस्यते","text":"medhyaṃ suśītaṃ pittaghnaṃ kaṣāyaṃ vastramucyate taddhārayeduṣṇakāle tatrāpi laghu śasyate"},{"type":"verse","number":"171","sanskrit":"शुक्लं तु शुभदं वस्त्रं शीतातपनिवारणम् न चोष्णं न च वा शीतं तत्तुवर्षासु धारयेत्","text":"śuklaṃ tu śubhadaṃ vastraṃ śītātapanivāraṇam na coṣṇaṃ na ca vā śītaṃ tattuvarṣāsu dhārayet"},{"type":"verse","number":"172","sanskrit":"यशस्यं काम्यमायुष्यं श्रीमदानन्दवर्धनम् त्वच्यं वशीकरं रुच्यं नवनिर्मलमम्बरम्","text":"yaśasyaṃ kāmyamāyuṣyaṃ śrīmadānandavardhanam tvacyaṃ vaśīkaraṃ rucyaṃ navanirmalamambaram"},{"type":"verse","number":"173","sanskrit":"कदाऽपि न जनैः सद्भिर्धार्यं मलिनमम्बरम् तत्तु कण्डूकृमिकरं ग्लान्यलक्ष्मीकरं परम्","text":"kadā'pi na janaiḥ sadbhirdhāryaṃ malinamambaram tattu kaṇḍūkṛmikaraṃ glānyalakṣmīkaraṃ param"},{"type":"verse","number":"174","sanskrit":"कुङ्कुमं चन्दनं चापि कृष्णागुरु च मिश्रितम् उष्णं वातकफध्वंसि शीतकाले तदिष्यते","text":"kuṅkumaṃ candanaṃ cāpi kṛṣṇāguru ca miśritam uṣṇaṃ vātakaphadhvaṃsi śītakāle tadiṣyate"},{"type":"verse","number":"175","sanskrit":"चन्दनं घनसारेण बालकेन च मिश्रितम् सुगन्धि परमं शीतमुष्णकाले प्रशस्यते","text":"candanaṃ ghanasāreṇa bālakena ca miśritam sugandhi paramaṃ śītamuṣṇakāle praśasyate"},{"type":"verse","number":"176","sanskrit":"चन्दनं घुसृणोपेतं मृगनाभिसमायुतम् न चोष्णं न च वा शीतं वर्षाकाले तदिष्यते","text":"candanaṃ ghusṛṇopetaṃ mṛganābhisamāyutam na coṣṇaṃ na ca vā śītaṃ varṣākāle tadiṣyate"},{"type":"verse","number":"177","sanskrit":"अनुलेपस्तृषामूर्च्छादुर्गन्धस्वेददाहजित् सौभाग्यतेजस्त्वग्वर्णप्रीत्यौजोबलवर्धनः स स्नानानर्हलोकानाममुलेपोऽपि नो हितः","text":"anulepastṛṣāmūrcchādurgandhasvedadāhajit saubhāgyatejastvagvarṇaprītyaujobalavardhanaḥ sa snānānarhalokānāmamulepo'pi no hitaḥ"},{"type":"verse","number":"178","sanskrit":"सुगन्धिपुष्पपत्राणां धारणं कान्तिकारकम् पापरक्षोग्रहहरं कामदं श्रीविवर्द्धनम्","text":"sugandhipuṣpapatrāṇāṃ dhāraṇaṃ kāntikārakam pāparakṣograhaharaṃ kāmadaṃ śrīvivarddhanam"},{"type":"verse","number":"179","sanskrit":"भूषणैर्भूषयेदङ्गं यथायोग्यं विधानतः शुचिसौभाग्यसन्तोषदायकं काञ्चनं स्मृतम्","text":"bhūṣaṇairbhūṣayedaṅgaṃ yathāyogyaṃ vidhānataḥ śucisaubhāgyasantoṣadāyakaṃ kāñcanaṃ smṛtam"},{"type":"verse","number":"180","sanskrit":"ग्रहदृष्टिहरं पुष्टिकरं दुःस्वप्ननाशनम् पापदौर्भाग्यशमनं रत्नाभरणधारणम्","text":"grahadṛṣṭiharaṃ puṣṭikaraṃ duḥsvapnanāśanam pāpadaurbhāgyaśamanaṃ ratnābharaṇadhāraṇam"},{"type":"verse","number":"181","sanskrit":"माणिक्यं तरणेः सुजातममलं मुक्ताफलं शीतगो र्माहेयस्य च विद्रुमो निगदितः सौम्यस्य गारुत्मतम् देवेज्यस्य च पुष्परागमसुराचार्यस्य वज्रं शने र्नीलं निर्मलमन्ययोश्च गदिते गोमेदवैदूर्यके","text":"māṇikyaṃ taraṇeḥ sujātamamalaṃ muktāphalaṃ śītago rmāheyasya ca vidrumo nigaditaḥ saumyasya gārutmatam devejyasya ca puṣparāgamasurācāryasya vajraṃ śane rnīlaṃ nirmalamanyayośca gadite gomedavaidūryake"},{"type":"verse","number":"182","sanskrit":"वासःशृङ्गाररत्नानां धारणं प्रीतिबर्धकम् रक्षोघ्नमर्थ्यमोजस्यं सौभाग्यकरमुत्तमम्","text":"vāsaḥśṛṅgāraratnānāṃ dhāraṇaṃ prītibardhakam rakṣoghnamarthyamojasyaṃ saubhāgyakaramuttamam"},{"type":"verse","number":"183","sanskrit":"सततं सिद्धमन्त्रस्य महौषध्यास्तथैव च रोचनासर्षपादीनां मङ्गल्यानां च धारणम्","text":"satataṃ siddhamantrasya mahauṣadhyāstathaiva ca rocanāsarṣapādīnāṃ maṅgalyānāṃ ca dhāraṇam"},{"type":"verse","number":"184","sanskrit":"आयुर्लक्ष्मीकरं रक्षोहरं मङ्गलदं शुभम् हिंस्नादिभयविध्वंसि वशीकरणकारणम्","text":"āyurlakṣmīkaraṃ rakṣoharaṃ maṅgaladaṃ śubham hiṃsnādibhayavidhvaṃsi vaśīkaraṇakāraṇam"},{"type":"verse","number":"185","sanskrit":"ततो भोजनवेलायां कुर्यान्मङ्गल्यदर्शनम् तस्य प्रदर्शनं नित्यमायुर्धर्मविवर्धनम्","text":"tato bhojanavelāyāṃ kuryānmaṅgalyadarśanam tasya pradarśanaṃ nityamāyurdharmavivardhanam"},{"type":"verse","number":"186","sanskrit":"लोकेऽस्मिन्मङ्गलान्यष्टौ ब्राह्मणो गौर्हुताशनः पुष्पस्रक्सर्पिरादित्य आपो राजा तथाऽष्टमः","text":"loke'sminmaṅgalānyaṣṭau brāhmaṇo gaurhutāśanaḥ puṣpasraksarpirāditya āpo rājā tathā'ṣṭamaḥ"},{"type":"verse","number":"187","sanskrit":"पादुकाधारणं कुर्यात्पूर्वं भोजनतः परम् पादरोगहरं वृष्यं चक्षुष्यं चायुषो हितम्","text":"pādukādhāraṇaṃ kuryātpūrvaṃ bhojanataḥ param pādarogaharaṃ vṛṣyaṃ cakṣuṣyaṃ cāyuṣo hitam"},{"type":"verse","number":"188","sanskrit":"शरीरे जायते नित्यं वाञ्छा नॄणां चतुर्विधः बुभुक्षा च पिपासा च सुषुप्सा च रतिस्पृहा","text":"śarīre jāyate nityaṃ vāñchā nṝṇāṃ caturvidhaḥ bubhukṣā ca pipāsā ca suṣupsā ca ratispṛhā"},{"type":"verse","number":"189","sanskrit":"भोजनेच्छाविघातात्स्यादङ्गमर्दोऽरुचिः श्रमः तन्द्रा लोचनदौर्बल्य धातुदाहो बलक्षयः","text":"bhojanecchāvighātātsyādaṅgamardo'ruciḥ śramaḥ tandrā locanadaurbalya dhātudāho balakṣayaḥ"},{"type":"verse","number":"190","sanskrit":"विघातेन पिपासायाः शोषः कण्ठास्ययोर्भवेत् श्रवणस्यावरोधश्च रक्तशोषो हृदि व्यथा","text":"vighātena pipāsāyāḥ śoṣaḥ kaṇṭhāsyayorbhavet śravaṇasyāvarodhaśca raktaśoṣo hṛdi vyathā"},{"type":"verse","number":"191","sanskrit":"निद्रा विघाततो जृम्भा शिरोलोचनगौरवम् अङ्गमर्दस्तथा तन्द्रा स्यादन्नापाक एव च","text":"nidrā vighātato jṛmbhā śirolocanagauravam aṅgamardastathā tandrā syādannāpāka eva ca"},{"type":"verse","number":"192","sanskrit":"बुभुक्षितो न योऽश्नाति तस्याहारेन्धनक्षयात् मन्दीभवति कायाग्निर्यथा चाग्निर्निरिन्धनः","text":"bubhukṣito na yo'śnāti tasyāhārendhanakṣayāt mandībhavati kāyāgniryathā cāgnirnirindhanaḥ"},{"type":"verse","number":"193","sanskrit":"आहारं पचति शिखी दोषानाहारवर्जितः पचेद् दोषक्षये धातून्प्राणान्धातुक्षयेऽपि च","text":"āhāraṃ pacati śikhī doṣānāhāravarjitaḥ paced doṣakṣaye dhātūnprāṇāndhātukṣaye'pi ca"},{"type":"verse","number":"194","sanskrit":"आहारः प्रीणनः सद्यो बलकृद् देहधारणः स्मृत्यायुःशक्तिवर्णौजःसत्त्वशोभाविवर्धनः","text":"āhāraḥ prīṇanaḥ sadyo balakṛd dehadhāraṇaḥ smṛtyāyuḥśaktivarṇaujaḥsattvaśobhāvivardhanaḥ"},{"type":"verse","number":"195","sanskrit":"यथोक्तगुणसम्पन्नं नरः सेवेत भोजनम् विचार्य दोषकालादीन्कालयोरुभयोरपि","text":"yathoktaguṇasampannaṃ naraḥ seveta bhojanam vicārya doṣakālādīnkālayorubhayorapi"},{"type":"verse","number":"196","sanskrit":"सायं प्रातर्मनुष्याणामशनं श्रुतिबोधितम् नान्तरा भोजनं कुर्यादग्निहोत्रसमो विधिः","text":"sāyaṃ prātarmanuṣyāṇāmaśanaṃ śrutibodhitam nāntarā bhojanaṃ kuryādagnihotrasamo vidhiḥ"},{"type":"verse","number":"197","sanskrit":"याममध्ये न भोक्तव्यं यामयुग्मं न लङ्घयेत् याममध्ये रसोत्पत्तिर्यामयुग्माद्बलक्षयः","text":"yāmamadhye na bhoktavyaṃ yāmayugmaṃ na laṅghayet yāmamadhye rasotpattiryāmayugmādbalakṣayaḥ"},{"type":"verse","number":"198","sanskrit":"क्षुत्सम्भवति पक्वेषु रसदोषमलेषु च काले वा यदि वाऽकाले सोऽन्नकाल उदाहृतः","text":"kṣutsambhavati pakveṣu rasadoṣamaleṣu ca kāle vā yadi vā'kāle so'nnakāla udāhṛtaḥ"},{"type":"verse","number":"199","sanskrit":"उद्गारशुद्धिरुत्साहो वेगोत्सर्गो यथोचितः लघुता क्षुत्पिपासा च जीर्णाहारस्य लक्षणम्","text":"udgāraśuddhirutsāho vegotsargo yathocitaḥ laghutā kṣutpipāsā ca jīrṇāhārasya lakṣaṇam"},{"type":"verse","number":"200","sanskrit":"आहारं तु रहः कुर्यान्निर्हारमपि सर्वदा उभाभ्यां लक्ष्म्युपेतः स्यात्प्रकाशे हीयते श्रिया","text":"āhāraṃ tu rahaḥ kuryānnirhāramapi sarvadā ubhābhyāṃ lakṣmyupetaḥ syātprakāśe hīyate śriyā"},{"type":"verse","number":"201","sanskrit":"आहारनिर्हारविहारयोगाः सदैव सद्भिर्विजने विधेयाः","text":"āhāranirhāravihārayogāḥ sadaiva sadbhirvijane vidheyāḥ"},{"type":"verse","number":"202","sanskrit":"पितृमातृसुहृद्वैद्यपाककृद्धंसबर्हिणाम् सारसस्य चकोरस्य भोजने दृष्टिरुत्तमा","text":"pitṛmātṛsuhṛdvaidyapākakṛddhaṃsabarhiṇām sārasasya cakorasya bhojane dṛṣṭiruttamā"},{"type":"verse","number":"203","sanskrit":"दीनहीनक्षुधाऽत्तानां पापपाषण्डरोगिणाम् कुक्कुटादेः शुनो दृष्टिर्भोजने नैव शोभना","text":"dīnahīnakṣudhā'ttānāṃ pāpapāṣaṇḍarogiṇām kukkuṭādeḥ śuno dṛṣṭirbhojane naiva śobhanā"},{"type":"verse","number":"204","sanskrit":"दोषहृद् दृष्टिदं पथ्यं हैमं भोजनभाजनम् रौप्यं भवति चक्षुष्यं पित्तहृत्कफवातकृत्","text":"doṣahṛd dṛṣṭidaṃ pathyaṃ haimaṃ bhojanabhājanam raupyaṃ bhavati cakṣuṣyaṃ pittahṛtkaphavātakṛt"},{"type":"verse","number":"205","sanskrit":"कांस्यं बुद्धिप्रदं रुच्यं रक्तपित्तप्रसादनम् पैत्तलं वातकृद्रू क्षमुष्णं कृमिकफप्रणुत्","text":"kāṃsyaṃ buddhipradaṃ rucyaṃ raktapittaprasādanam paittalaṃ vātakṛdrū kṣamuṣṇaṃ kṛmikaphapraṇut"},{"type":"verse","number":"206","sanskrit":"आयसे काचपात्रे च भोजनं सिद्धिकारकम् शोथपाण्डुहरं बल्यं कामलाऽपहमुत्तमम्","text":"āyase kācapātre ca bhojanaṃ siddhikārakam śothapāṇḍuharaṃ balyaṃ kāmalā'pahamuttamam"},{"type":"verse","number":"207","sanskrit":"शैलेये मृण्मये पात्रे भोजनं श्रीनिवारणम् दारूद्भवे विशेषेण रुचिदं श्लेष्मकारि च पात्रं पत्रमयं रुच्यं दीपनं विषपापनुत्","text":"śaileye mṛṇmaye pātre bhojanaṃ śrīnivāraṇam dārūdbhave viśeṣeṇa rucidaṃ śleṣmakāri ca pātraṃ patramayaṃ rucyaṃ dīpanaṃ viṣapāpanut"},{"type":"verse","number":"208","sanskrit":"जलपात्रं तु ताम्रस्य तदभावे मृदो हितम्","text":"jalapātraṃ tu tāmrasya tadabhāve mṛdo hitam"},{"type":"verse","number":"209","sanskrit":"पवित्रं शीतलं पात्रं रचितं स्फटिकेन यत् काचेन रचितं तद्वत्तथा वैदूर्यसम्भवम्","text":"pavitraṃ śītalaṃ pātraṃ racitaṃ sphaṭikena yat kācena racitaṃ tadvattathā vaidūryasambhavam"},{"type":"verse","number":"210","sanskrit":"भोजनाग्रे सदा पथ्यं लवणार्द्र कभक्षणम् अग्निसन्दीपनं रुच्यं जिह्वाकण्ठविशोधनम्","text":"bhojanāgre sadā pathyaṃ lavaṇārdra kabhakṣaṇam agnisandīpanaṃ rucyaṃ jihvākaṇṭhaviśodhanam"},{"type":"verse","number":"211","sanskrit":"अन्नं ब्रह्मा रसो विष्णुर्भोक्ता देवो महेश्वरः इति सञ्चिन्त्य भुञ्जानं दृष्टिदोषो न बाधते","text":"annaṃ brahmā raso viṣṇurbhoktā devo maheśvaraḥ iti sañcintya bhuñjānaṃ dṛṣṭidoṣo na bādhate"},{"type":"verse","number":"212","sanskrit":"अञ्जनागर्भसम्भूतं कुमारं ब्रह्मचारिणम् दृष्टिदोषविनाशाय हनुमन्तं स्मराम्यहम्","text":"añjanāgarbhasambhūtaṃ kumāraṃ brahmacāriṇam dṛṣṭidoṣavināśāya hanumantaṃ smarāmyaham"},{"type":"verse","number":"213","sanskrit":"अश्नीयात्तन्मना भूत्वा पूर्वं तु मधुरं रसम् मध्येऽम्ललवणौ पश्चात्कटुतिक्तकषायकान्","text":"aśnīyāttanmanā bhūtvā pūrvaṃ tu madhuraṃ rasam madhye'mlalavaṇau paścātkaṭutiktakaṣāyakān"},{"type":"verse","number":"214","sanskrit":"फलान्यादौ समश्नीयाद्दाडिमादीनि बुद्धिमान् विना मोचफलं तद्वद्वर्जनीया च कर्कटी","text":"phalānyādau samaśnīyāddāḍimādīni buddhimān vinā mocaphalaṃ tadvadvarjanīyā ca karkaṭī"},{"type":"verse","number":"215","sanskrit":"मृणालबिसशालूककन्देक्षुप्रभृतीनपि पूर्वमेव हि भोज्यानि न तु भुक्त्वा कदाचन","text":"mṛṇālabisaśālūkakandekṣuprabhṛtīnapi pūrvameva hi bhojyāni na tu bhuktvā kadācana"},{"type":"verse","number":"216","sanskrit":"गुरु पिष्टमयं द्र व्यं तण्डुलान्पृथुकानपि न जातु भुक्तवान्खादेन्मात्रां खादेद्बुभुक्षितः","text":"guru piṣṭamayaṃ dra vyaṃ taṇḍulānpṛthukānapi na jātu bhuktavānkhādenmātrāṃ khādedbubhukṣitaḥ"},{"type":"verse","number":"217","sanskrit":"घृतपूर्वं समश्नीयात्कठिनं प्राक् ततो मृदु अन्ते पुनर्द्र वाशी तु बलाद्रो गेण मुञ्चति","text":"ghṛtapūrvaṃ samaśnīyātkaṭhinaṃ prāk tato mṛdu ante punardra vāśī tu balādro geṇa muñcati"},{"type":"verse","number":"218","sanskrit":"यद्यत्स्वादुतरं तत्तद्विदध्यादुत्तरोत्तरम् भुक्त्वा यत्प्रार्थ्यते भूयस्तदुक्तं स्वादु भोजनम्","text":"yadyatsvādutaraṃ tattadvidadhyāduttarottaram bhuktvā yatprārthyate bhūyastaduktaṃ svādu bhojanam"},{"type":"verse","number":"219","sanskrit":"सौमनस्यं बलं पुष्टिमुत्साहं वृद्धिमायुषः स्वादु सञ्जनयत्यन्नमस्वादु च विपर्ययम्","text":"saumanasyaṃ balaṃ puṣṭimutsāhaṃ vṛddhimāyuṣaḥ svādu sañjanayatyannamasvādu ca viparyayam"},{"type":"verse","number":"220","sanskrit":"अत्युष्णान्नं बलं हन्ति शीतं शुष्कं च दुर्जरम् अतिक्लिन्नं ग्लानिकरं युक्तियुक्तं हि भोजनम्","text":"atyuṣṇānnaṃ balaṃ hanti śītaṃ śuṣkaṃ ca durjaram atiklinnaṃ glānikaraṃ yuktiyuktaṃ hi bhojanam"},{"type":"verse","number":"221","sanskrit":"अतिद्रुताशिताहारे गुणान्दोषान्न विन्दति भोज्यं शीतमहृद्यं च स्याद्विलम्बितमश्नतः","text":"atidrutāśitāhāre guṇāndoṣānna vindati bhojyaṃ śītamahṛdyaṃ ca syādvilambitamaśnataḥ"},{"type":"verse","number":"222","sanskrit":"मन्दानलो नरो द्र व्यं मात्रागुरु विवर्जयेत् स्वभावतश्च गुरु यत्तथा संस्कारतो गुरु","text":"mandānalo naro dra vyaṃ mātrāguru vivarjayet svabhāvataśca guru yattathā saṃskārato guru"},{"type":"verse","number":"223","sanskrit":"मात्रागुरुस्तु मुद्गादिर्माषादिः प्रकृतेर्गुरुः संस्कारगुरु पिष्टान्नं प्रोक्तमित्युपलक्षणम्","text":"mātrāgurustu mudgādirmāṣādiḥ prakṛterguruḥ saṃskāraguru piṣṭānnaṃ proktamityupalakṣaṇam"},{"type":"verse","number":"224","sanskrit":"आहारं षड्विधं चूष्यं पेयं लेह्यं तथैव च भोज्यं भक्ष्यं तथा चर्व्यं गुरु विद्याद्यथोत्तरम्","text":"āhāraṃ ṣaḍvidhaṃ cūṣyaṃ peyaṃ lehyaṃ tathaiva ca bhojyaṃ bhakṣyaṃ tathā carvyaṃ guru vidyādyathottaram"},{"type":"verse","number":"225","sanskrit":"गुरूणामर्धसौहित्यं लघूनां तृप्तिरिष्यते द्र वो द्र वोत्तरश्चापि न मात्रागुरुरिष्यते","text":"gurūṇāmardhasauhityaṃ laghūnāṃ tṛptiriṣyate dra vo dra vottaraścāpi na mātrāgururiṣyate"},{"type":"verse","number":"226","sanskrit":"विशुष्कमन्नमभ्यस्तं न पाकं साधु गच्छति","text":"viśuṣkamannamabhyastaṃ na pākaṃ sādhu gacchati"},{"type":"verse","number":"227","sanskrit":"शुष्कं निरुद्धं विष्टम्भि वह्निव्यापादकृद्भवेत्","text":"śuṣkaṃ niruddhaṃ viṣṭambhi vahnivyāpādakṛdbhavet"},{"type":"verse","number":"228","sanskrit":"न भुक्त्वा न रदैश्छित्त्वा न निशायां न वा बहून् न जलान्तरितानद्भिः सक्तूनद्यान्न केवलान्","text":"na bhuktvā na radaiśchittvā na niśāyāṃ na vā bahūn na jalāntaritānadbhiḥ saktūnadyānna kevalān"},{"type":"verse","number":"229","sanskrit":"पुनर्दानं पृथक्पानं सामिषं पयसा निशि सदन्तच्छेदमुष्णं च सप्त सक्तुषु वर्जयेत्","text":"punardānaṃ pṛthakpānaṃ sāmiṣaṃ payasā niśi sadantacchedamuṣṇaṃ ca sapta saktuṣu varjayet"},{"type":"verse","number":"230","sanskrit":"सक्तूनामाशु जीर्येत मृदुत्वादवलेहिका","text":"saktūnāmāśu jīryeta mṛdutvādavalehikā"},{"type":"verse","number":"231","sanskrit":"यथाकालेऽतिमात्रं यत् तद्भवेद्विषमाशनम् बहुस्तोकमकाले वा ज्ञेयं तद्विषमाशनम्","text":"yathākāle'timātraṃ yat tadbhavedviṣamāśanam bahustokamakāle vā jñeyaṃ tadviṣamāśanam"},{"type":"verse","number":"232","sanskrit":"आलस्यगौरवाटोपसादांश्च कुरुतेऽधिकम् हीनमात्रं तनोःकार्श्यं करोति च बलक्षयम्","text":"ālasyagauravāṭopasādāṃśca kurute'dhikam hīnamātraṃ tanoḥkārśyaṃ karoti ca balakṣayam"},{"type":"verse","number":"233","sanskrit":"अप्राप्तकाले भुञ्जानो ह्यसमर्थतनुर्नरः तांस्तान् व्याधीनवाप्नोति मरणं चाधिगच्छति","text":"aprāptakāle bhuñjāno hyasamarthatanurnaraḥ tāṃstān vyādhīnavāpnoti maraṇaṃ cādhigacchati"},{"type":"verse","number":"234","sanskrit":"कालेतीतेश्नतो जन्तोर्वायुनोपहतेऽनले कृच्छ्राद्विपच्यते भुक्तं न स्याद्भोक्तुं पुनः स्पृहा","text":"kāletīteśnato jantorvāyunopahate'nale kṛcchrādvipacyate bhuktaṃ na syādbhoktuṃ punaḥ spṛhā"},{"type":"verse","number":"235","sanskrit":"कुक्षेर्भागद्वयं भोज्यैस्तृतीये वारि पूरयेत् वायोः सञ्चारणार्थाय चतुर्थमवशेषयेत्","text":"kukṣerbhāgadvayaṃ bhojyaistṛtīye vāri pūrayet vāyoḥ sañcāraṇārthāya caturthamavaśeṣayet"},{"type":"verse","number":"236","sanskrit":"रसेनान्नस्य रसना प्रथमेनोपतर्पिता न तथा स्वादमाप्नोति ततः शोध्याम्बुनान्तरा","text":"rasenānnasya rasanā prathamenopatarpitā na tathā svādamāpnoti tataḥ śodhyāmbunāntarā"},{"type":"verse","number":"237","sanskrit":"अत्यम्बुपानान्न विपच्यतेऽन्नमनम्बुपानाच्च स एव दोषः तस्मान्नरो वह्निविवर्धनाय मुहुर्मुहुर्वारि पिबेदभूरि","text":"atyambupānānna vipacyate'nnamanambupānācca sa eva doṣaḥ tasmānnaro vahnivivardhanāya muhurmuhurvāri pibedabhūri"},{"type":"verse","number":"238","sanskrit":"भुक्तस्यादौ जलं पीतं कार्श्यमन्दाग्निदोषकृत् मध्येऽग्निदीपनं श्रेष्ठमन्ते स्थौल्यकफप्रदम्","text":"bhuktasyādau jalaṃ pītaṃ kārśyamandāgnidoṣakṛt madhye'gnidīpanaṃ śreṣṭhamante sthaulyakaphapradam"},{"type":"verse","number":"239","sanskrit":"समस्थूलकृशा भुक्तमध्यान्तप्रथमाम्बुपाः","text":"samasthūlakṛśā bhuktamadhyāntaprathamāmbupāḥ"},{"type":"verse","number":"240","sanskrit":"तृषितस्तु न चाश्नीयात्क्षुधितो न पिबेज्जलम् तृषितस्तु भवेद्गुल्मी क्षुधितस्तु जलोदरी","text":"tṛṣitastu na cāśnīyātkṣudhito na pibejjalam tṛṣitastu bhavedgulmī kṣudhitastu jalodarī"},{"type":"verse","number":"241","sanskrit":"अश्नीयात्तन्मना भूत्वा पूर्वं तु मधुरं रसम् मध्येऽम्ललवणौ पश्चात्कटुतिक्तकषायकान्","text":"aśnīyāttanmanā bhūtvā pūrvaṃ tu madhuraṃ rasam madhye'mlalavaṇau paścātkaṭutiktakaṣāyakān"},{"type":"verse","number":"242","sanskrit":"दुग्धं स्वादुरसं स्निग्धमोजस्यं धातुवर्धनम् वातपित्तहरं वृष्यं श्लेष्मलं गुरु शीतलम्","text":"dugdhaṃ svādurasaṃ snigdhamojasyaṃ dhātuvardhanam vātapittaharaṃ vṛṣyaṃ śleṣmalaṃ guru śītalam"},{"type":"verse","number":"243","sanskrit":"विदाहीन्यन्नपानानि यानि भुंङ्क्ते हि मानवः तद्विदाहप्रशान्त्यर्थं भोजनान्ते पयः पिबेत्","text":"vidāhīnyannapānāni yāni bhuṃṅkte hi mānavaḥ tadvidāhapraśāntyarthaṃ bhojanānte payaḥ pibet"},{"type":"verse","number":"244","sanskrit":"कुर्यात्क्षीरान्तमाहारं न दध्यन्तं कदाचन लवणाम्लकटूष्णानि विदाहीन्यत्ति यानि तु तद्दोषं हर्तुमाहारं मधुरेण समापयेत्","text":"kuryātkṣīrāntamāhāraṃ na dadhyantaṃ kadācana lavaṇāmlakaṭūṣṇāni vidāhīnyatti yāni tu taddoṣaṃ hartumāhāraṃ madhureṇa samāpayet"},{"type":"verse","number":"245","sanskrit":"बलवच्छत्रुविनाशनेन शत्रुहन्तुः क्षीणता च दृश्यते तथा च नाशनात्प्रत्यनीकस्य स्वयं च क्षीयते यथा वह्निसन्तप्तलोहस्य तप्ततां नाशयेज्जलम्","text":"balavacchatruvināśanena śatruhantuḥ kṣīṇatā ca dṛśyate tathā ca nāśanātpratyanīkasya svayaṃ ca kṣīyate yathā vahnisantaptalohasya taptatāṃ nāśayejjalam"},{"type":"verse","number":"246","sanskrit":"ननु भोजनावसानसमये प्रयुक्ताः कटुतिक्तकषायरसाः कफं शमयिष्यन्ति वातस्य वृद्धिं विधास्यन्तीति चेतै तन्न कट्वादीनां क्षीणशक्तित्वात् तथा च यदेकं नाशयेद्दोषं तदन्यं वर्धयेत्कुतः नाशने ह्येकदोषस्य यतस्तत्क्षीणशक्तिकम्","text":"nanu bhojanāvasānasamaye prayuktāḥ kaṭutiktakaṣāyarasāḥ kaphaṃ śamayiṣyanti vātasya vṛddhiṃ vidhāsyantīti cetai tanna kaṭvādīnāṃ kṣīṇaśaktitvāt tathā ca yadekaṃ nāśayeddoṣaṃ tadanyaṃ vardhayetkutaḥ nāśane hyekadoṣasya yatastatkṣīṇaśaktikam"},{"type":"verse","number":"247","sanskrit":"जग्धाः सर्वेऽपि गच्छन्ति बलिनो वश्यतां रसाः यथा प्रकुपिता दोषा वशं यान्ति बलीयसः","text":"jagdhāḥ sarve'pi gacchanti balino vaśyatāṃ rasāḥ yathā prakupitā doṣā vaśaṃ yānti balīyasaḥ"},{"type":"verse","number":"248","sanskrit":"एवं भुक्त्वा समाचामेद्रू क्षग्रहणपूर्वकम् भोजने दन्तलग्नानि निर्हृत्याचमनं चरेत्","text":"evaṃ bhuktvā samācāmedrū kṣagrahaṇapūrvakam bhojane dantalagnāni nirhṛtyācamanaṃ caret"},{"type":"verse","number":"249","sanskrit":"दन्तान्तरगतं चान्नं शोधनेनाहरेच्छनैः कुर्यादनिर्हृतं तद्धि मुखस्यानिष्टगन्धताम्","text":"dantāntaragataṃ cānnaṃ śodhanenāharecchanaiḥ kuryādanirhṛtaṃ taddhi mukhasyāniṣṭagandhatām"},{"type":"verse","number":"250","sanskrit":"दन्तलग्नमनिर्हार्यं लेपं मन्येत दन्तवत् न तत्र बहुशः कुर्याद्यत्नं निर्हरणं प्रति","text":"dantalagnamanirhāryaṃ lepaṃ manyeta dantavat na tatra bahuśaḥ kuryādyatnaṃ nirharaṇaṃ prati"},{"type":"verse","number":"251","sanskrit":"आचम्य जलयुक्ताभ्यां पाणिभ्यां चक्षुषी स्पृशेत् भुक्त्वा पाणितलं घृष्ट्वा चक्षुषोर्यदि दीयते अचिरेणैव तद्वारि तिमिराणि व्यपोहति","text":"ācamya jalayuktābhyāṃ pāṇibhyāṃ cakṣuṣī spṛśet bhuktvā pāṇitalaṃ ghṛṣṭvā cakṣuṣoryadi dīyate acireṇaiva tadvāri timirāṇi vyapohati"},{"type":"verse","number":"252","sanskrit":"भुक्त्वा च संस्मरेन्नित्यमगस्त्यादीन्सुखावहान्","text":"bhuktvā ca saṃsmarennityamagastyādīnsukhāvahān"},{"type":"verse","number":"253","sanskrit":"विष्णुरात्मा तथैवान्नं परिणामश्च वै यथा सत्येन तेन मद्भुक्तं जीर्यत्वन्नमिदं तथा","text":"viṣṇurātmā tathaivānnaṃ pariṇāmaśca vai yathā satyena tena madbhuktaṃ jīryatvannamidaṃ tathā"},{"type":"verse","number":"254","sanskrit":"अगस्तिरग्निर्वडवानलश्च भुक्तं ममान्नं जरयन्त्वशेषम् सुखं च मे तत्परिणामसम्भवं यच्छन्त्वरोगं मम चास्तु देहम्","text":"agastiragnirvaḍavānalaśca bhuktaṃ mamānnaṃ jarayantvaśeṣam sukhaṃ ca me tatpariṇāmasambhavaṃ yacchantvarogaṃ mama cāstu deham"},{"type":"verse","number":"255","sanskrit":"अङ्गारकमगस्तिं च पावकं सूर्यमश्विनौ पञ्चैतान्संस्मरेन्नित्यं भुक्तं तस्याशु जीर्यति","text":"aṅgārakamagastiṃ ca pāvakaṃ sūryamaśvinau pañcaitānsaṃsmarennityaṃ bhuktaṃ tasyāśu jīryati"},{"type":"verse","number":"256","sanskrit":"इत्युच्चार्य स्वहस्तेन परिमार्ज्य तथोदरम् अनायासप्रदायीनि कुर्यात्कर्माण्यतन्द्रि तः","text":"ityuccārya svahastena parimārjya tathodaram anāyāsapradāyīni kuryātkarmāṇyatandri taḥ"},{"type":"verse","number":"257","sanskrit":"जीर्णेऽन्ने वर्धते वायुर्विदग्धे पित्तमेधते भुक्तमात्रे कफश्चापि क्रमोऽय भोजनोपरि","text":"jīrṇe'nne vardhate vāyurvidagdhe pittamedhate bhuktamātre kaphaścāpi kramo'ya bhojanopari"},{"type":"verse","number":"258","sanskrit":"धूमेनापोह्य हृद्यैर्वा कषायकटुतिक्तकैः पूगैः कर्पूरकस्तूरीलवंगसुमनः फलैः","text":"dhūmenāpohya hṛdyairvā kaṣāyakaṭutiktakaiḥ pūgaiḥ karpūrakastūrīlavaṃgasumanaḥ phalaiḥ"},{"type":"verse","number":"259","sanskrit":"फलैः कटुकषायैर्वा मुखवैशद्यकारिभिः ताम्बूलपत्रसहितैः सुगन्धैर्वा विचक्षणः","text":"phalaiḥ kaṭukaṣāyairvā mukhavaiśadyakāribhiḥ tāmbūlapatrasahitaiḥ sugandhairvā vicakṣaṇaḥ"},{"type":"verse","number":"260","sanskrit":"रतौ सुप्तोत्थिते स्नाते भुक्तेवान्ते च संगरे सभायां विदुषां राज्ञां कुर्यात्ताम्बूलचर्वणम्","text":"ratau suptotthite snāte bhuktevānte ca saṃgare sabhāyāṃ viduṣāṃ rājñāṃ kuryāttāmbūlacarvaṇam"},{"type":"verse","number":"261","sanskrit":"ताम्बूलमुक्तं तीक्ष्णोष्णं रोचनं तुवरं सरम् तिक्तं क्षारोषणं कामरक्तपित्तकरं लघु","text":"tāmbūlamuktaṃ tīkṣṇoṣṇaṃ rocanaṃ tuvaraṃ saram tiktaṃ kṣāroṣaṇaṃ kāmaraktapittakaraṃ laghu"},{"type":"verse","number":"262","sanskrit":"वश्यं श्लेष्मास्यदौर्गन्ध्यमलवातश्रमापहम् मुखवैशद्यसौगन्ध्यकान्तिसौष्ठवकारकम्","text":"vaśyaṃ śleṣmāsyadaurgandhyamalavātaśramāpaham mukhavaiśadyasaugandhyakāntisauṣṭhavakārakam"},{"type":"verse","number":"263","sanskrit":"हनुदन्तमलध्वंसि जिह्वेन्द्रि यविशोधनम् मुखप्रसेकशमनं गलामयविनाशनम्","text":"hanudantamaladhvaṃsi jihvendri yaviśodhanam mukhaprasekaśamanaṃ galāmayavināśanam"},{"type":"verse","number":"264","sanskrit":"नवं तदेव मधुरं कषायानुरसं गुरु बलासजननंप्रायः पत्रशाकगुणं स्मृतम्","text":"navaṃ tadeva madhuraṃ kaṣāyānurasaṃ guru balāsajananaṃprāyaḥ patraśākaguṇaṃ smṛtam"},{"type":"verse","number":"265","sanskrit":"वङ्गदेशोद्भवं पर्णं परं कटुरसं सरम् पाचनं पित्तजनकमुष्णं कफहरं स्मृतम्","text":"vaṅgadeśodbhavaṃ parṇaṃ paraṃ kaṭurasaṃ saram pācanaṃ pittajanakamuṣṇaṃ kaphaharaṃ smṛtam"},{"type":"verse","number":"266","sanskrit":"पर्णं पुराणमकटु क्षुल्लकं तनु पाण्डुरम् विशेषाद्गुणवद्वेद्यमन्वद्धीनगुणं स्मृतम्","text":"parṇaṃ purāṇamakaṭu kṣullakaṃ tanu pāṇḍuram viśeṣādguṇavadvedyamanvaddhīnaguṇaṃ smṛtam"},{"type":"verse","number":"267","sanskrit":"पूगं गुरु हिमं रूक्षं कषायं कफपित्तनुत् मोहनं दीपनं रुच्यमास्यवैरस्यनाशनम्","text":"pūgaṃ guru himaṃ rūkṣaṃ kaṣāyaṃ kaphapittanut mohanaṃ dīpanaṃ rucyamāsyavairasyanāśanam"},{"type":"verse","number":"268","sanskrit":"पूगं स्यात् दृढमध्यं यत्स्विन्नं वाऽपि त्रिदोषनुत् सरसङ्गुर्वभिष्यन्दि तद् भृशं वह्निनाशनम्","text":"pūgaṃ syāt dṛḍhamadhyaṃ yatsvinnaṃ vā'pi tridoṣanut sarasaṅgurvabhiṣyandi tad bhṛśaṃ vahnināśanam"},{"type":"verse","number":"269","sanskrit":"खदिरं कफपित्तघ्नश्चूर्णं वातबलासनुत् संयोगतस्त्रिदोषघ्नं सौमनस्यं करोति च","text":"khadiraṃ kaphapittaghnaścūrṇaṃ vātabalāsanut saṃyogatastridoṣaghnaṃ saumanasyaṃ karoti ca"},{"type":"verse","number":"270","sanskrit":"मुखवैशद्यसौगन्ध्यकान्तिसौष्ठवकारकम् प्रभाते पूगमधिकं मध्याह्ने खदिरं तथा निशासु चूर्णमधिकं ताम्बूलं भक्षयेत्सदा","text":"mukhavaiśadyasaugandhyakāntisauṣṭhavakārakam prabhāte pūgamadhikaṃ madhyāhne khadiraṃ tathā niśāsu cūrṇamadhikaṃ tāmbūlaṃ bhakṣayetsadā"},{"type":"verse","number":"271","sanskrit":"आयुरग्रे यशो मूले लक्ष्मीर्मध्ये व्यवस्थिता तस्मादग्रं तथा मूलं मध्यं पर्णस्य वर्जयेत्","text":"āyuragre yaśo mūle lakṣmīrmadhye vyavasthitā tasmādagraṃ tathā mūlaṃ madhyaṃ parṇasya varjayet"},{"type":"verse","number":"272","sanskrit":"पर्णमूले भवेद्व्याधिः पर्णाग्रे पापसम्भवः पर्णमध्यं हरत्यायुः शिरा बुद्धि विनाशिनी","text":"parṇamūle bhavedvyādhiḥ parṇāgre pāpasambhavaḥ parṇamadhyaṃ haratyāyuḥ śirā buddhi vināśinī"},{"type":"verse","number":"273","sanskrit":"आद्यं विषोपमं पीतं द्वितीयं भेदि दुर्जरम् तृतीयादनुपातव्यं सुधातुल्यं रसायनम्","text":"ādyaṃ viṣopamaṃ pītaṃ dvitīyaṃ bhedi durjaram tṛtīyādanupātavyaṃ sudhātulyaṃ rasāyanam"},{"type":"verse","number":"274","sanskrit":"ताम्बूलं नातिसेवेत न विरिक्तो बुभुक्षितः","text":"tāmbūlaṃ nātiseveta na virikto bubhukṣitaḥ"},{"type":"verse","number":"275","sanskrit":"देहदृक्केशदन्ताग्निश्रोत्रवर्णबलक्षयः शोषः पित्तानिलास्रं स्यादतिताम्बूलचर्वणात्","text":"dehadṛkkeśadantāgniśrotravarṇabalakṣayaḥ śoṣaḥ pittānilāsraṃ syādatitāmbūlacarvaṇāt"},{"type":"verse","number":"276","sanskrit":"ताम्बूलं न हितं दन्तदुर्बलेक्षणरोगिणाम् विषमूर्च्छामदार्त्तानां क्षयिणां रक्तपित्तिनाम्","text":"tāmbūlaṃ na hitaṃ dantadurbalekṣaṇarogiṇām viṣamūrcchāmadārttānāṃ kṣayiṇāṃ raktapittinām"},{"type":"verse","number":"277","sanskrit":"भुक्त्वा शतपदं गच्छेच्छनैस्तेन तु जायते अन्नसंघातशैथिल्यं ग्रीवाजानुकटीषु च","text":"bhuktvā śatapadaṃ gacchecchanaistena tu jāyate annasaṃghātaśaithilyaṃ grīvājānukaṭīṣu ca"},{"type":"verse","number":"278","sanskrit":"भुक्त्वोपविशतस्तन्द्रा शयानस्य तु पुष्टता आयुश्च्रंकममाणस्य मृत्युर्धावति धावतः","text":"bhuktvopaviśatastandrā śayānasya tu puṣṭatā āyuścraṃkamamāṇasya mṛtyurdhāvati dhāvataḥ"},{"type":"verse","number":"279","sanskrit":"श्वासानष्टौ समुत्तानस्तान् द्विःपार्श्वे तु दक्षिणे ततस्तद्द्विगुणान्वामे पश्चात्स्वप्याद्यथासुखम्","text":"śvāsānaṣṭau samuttānastān dviḥpārśve tu dakṣiṇe tatastaddviguṇānvāme paścātsvapyādyathāsukham"},{"type":"verse","number":"280","sanskrit":"वामदिशायामनलो नाभेरूर्ध्वेऽस्ति जन्तूनाम् तस्मात्तु वामपार्श्वे शयीत भुक्तप्रपाकार्थम्","text":"vāmadiśāyāmanalo nābherūrdhve'sti jantūnām tasmāttu vāmapārśve śayīta bhuktaprapākārtham"},{"type":"verse","number":"281","sanskrit":"त्रिदोषशमनी षट्वा तूली वातकफापहा भूशय्या वृंहणी वृष्या काष्ठपट्टी तु वातला","text":"tridoṣaśamanī ṣaṭvā tūlī vātakaphāpahā bhūśayyā vṛṃhaṇī vṛṣyā kāṣṭhapaṭṭī tu vātalā"},{"type":"verse","number":"282","sanskrit":"भूशय्या वातलाऽतीवरूक्षा पित्तास्रनाशिनी सुशय्याशयनं हृद्यं पुष्टिनिद्रा धृतिप्रदम् श्रमानिलहरं वृष्यं विपरीतमतोऽन्यथा","text":"bhūśayyā vātalā'tīvarūkṣā pittāsranāśinī suśayyāśayanaṃ hṛdyaṃ puṣṭinidrā dhṛtipradam śramānilaharaṃ vṛṣyaṃ viparītamato'nyathā"},{"type":"verse","number":"283","sanskrit":"संवाहनं मांसरक्तत्वक्प्रसादकरं परम् प्रीतिनिद्रा करं वृष्यं कफवातश्रमापहम्","text":"saṃvāhanaṃ māṃsaraktatvakprasādakaraṃ param prītinidrā karaṃ vṛṣyaṃ kaphavātaśramāpaham"},{"type":"verse","number":"284","sanskrit":"प्रवातं रौक्ष्यवैवर्ण्यस्तम्भकृद्दाहपित्तनुत् स्वेदमूर्च्छापिपासाघ्नमप्रवातमतोऽन्यथा","text":"pravātaṃ raukṣyavaivarṇyastambhakṛddāhapittanut svedamūrcchāpipāsāghnamapravātamato'nyathā"},{"type":"verse","number":"285","sanskrit":"सुखं प्रवातं सेवेत ग्रीष्मे शरदि चान्तरा निर्वातमायुषे सेव्यमारोग्याय च सर्वदा","text":"sukhaṃ pravātaṃ seveta grīṣme śaradi cāntarā nirvātamāyuṣe sevyamārogyāya ca sarvadā"},{"type":"verse","number":"286","sanskrit":"पूर्वाऽनिलो गुरुः सोष्णः स्निग्धः पित्तास्नदूषकः विदाही वातलः श्रान्तिकफशोषवतां हितः","text":"pūrvā'nilo guruḥ soṣṇaḥ snigdhaḥ pittāsnadūṣakaḥ vidāhī vātalaḥ śrāntikaphaśoṣavatāṃ hitaḥ"},{"type":"verse","number":"287","sanskrit":"स्वादुः पटुरभिष्यन्दी त्वग्दोषार्शोविषकृमीन् सन्निपातं ज्वरं श्वासमामवातं च कोपयेत्","text":"svāduḥ paṭurabhiṣyandī tvagdoṣārśoviṣakṛmīn sannipātaṃ jvaraṃ śvāsamāmavātaṃ ca kopayet"},{"type":"verse","number":"288","sanskrit":"दक्षिणः पवनः स्वादुः पित्तरक्तहरो लघुः वीर्येण शीतलो बल्यश्चक्षुष्यो न तु वातलः","text":"dakṣiṇaḥ pavanaḥ svāduḥ pittaraktaharo laghuḥ vīryeṇa śītalo balyaścakṣuṣyo na tu vātalaḥ"},{"type":"verse","number":"289","sanskrit":"पश्चिमः पवनस्तीक्ष्णः शोषणो बलहृल्लघुः मेदः पित्तकफध्वंसी प्रभञ्जनविवर्धनः","text":"paścimaḥ pavanastīkṣṇaḥ śoṣaṇo balahṛllaghuḥ medaḥ pittakaphadhvaṃsī prabhañjanavivardhanaḥ"},{"type":"verse","number":"290","sanskrit":"उत्तरो मारुतः शीतः स्निग्धो दोषप्रकोपकृत् क्लेदनः प्रकृतिस्थानां बलदो मधुरो मृदुः","text":"uttaro mārutaḥ śītaḥ snigdho doṣaprakopakṛt kledanaḥ prakṛtisthānāṃ balado madhuro mṛduḥ"},{"type":"verse","number":"291","sanskrit":"आग्नेयो दाहकृद्रू क्षो नैरृतो न विदाहकृत् वायव्यस्तु भवेत्तिक्त एशानः कटुकः स्मृतः","text":"āgneyo dāhakṛdrū kṣo nairṛto na vidāhakṛt vāyavyastu bhavettikta eśānaḥ kaṭukaḥ smṛtaḥ"},{"type":"verse","number":"292","sanskrit":"विष्वग्वायुरनायुष्यः प्राणिनां बहुरोगकृत् अतस्तं नैव सेवेत सेवितः स्यान्न शर्मणे","text":"viṣvagvāyuranāyuṣyaḥ prāṇināṃ bahurogakṛt atastaṃ naiva seveta sevitaḥ syānna śarmaṇe"},{"type":"verse","number":"293","sanskrit":"व्यजनस्यानिलो दाहस्वेदमूर्च्छाश्रमापहः तालवृन्तभवो वातस्त्रिदोषशमको मतः","text":"vyajanasyānilo dāhasvedamūrcchāśramāpahaḥ tālavṛntabhavo vātastridoṣaśamako mataḥ"},{"type":"verse","number":"294","sanskrit":"वंशब्यजनजस्तूष्णो रक्तपित्तप्रकोपणः चामरो वस्त्रसम्भूतो मायूरो वेत्रजस्तथा","text":"vaṃśabyajanajastūṣṇo raktapittaprakopaṇaḥ cāmaro vastrasambhūto māyūro vetrajastathā"},{"type":"verse","number":"295","sanskrit":"पूते दोषजिता वाताः स्निग्धाः हृद्याः सुपूजिताः","text":"pūte doṣajitā vātāḥ snigdhāḥ hṛdyāḥ supūjitāḥ"},{"type":"verse","number":"296","sanskrit":"दिवा स्वापं न कुर्वीत यतोसौ स्यात्कफावहः ग्रीष्मवर्ज्येषु कालेषु दिवास्वप्नो निषिध्यते","text":"divā svāpaṃ na kurvīta yatosau syātkaphāvahaḥ grīṣmavarjyeṣu kāleṣu divāsvapno niṣidhyate"},{"type":"verse","number":"297","sanskrit":"उचितो हि दिवास्वप्नो नित्यं येषां शरीरिणाम् वातादयः प्रकुप्यन्ति तेषामस्वपतां दिवा","text":"ucito hi divāsvapno nityaṃ yeṣāṃ śarīriṇām vātādayaḥ prakupyanti teṣāmasvapatāṃ divā"},{"type":"verse","number":"298","sanskrit":"व्यायामप्रमदाऽध्ववाहनरतान् क्लान्तानतीसारिणः शूलश्वासवतस्तृषापरिगतान् हिक्कामरुत्पीडितान् क्षीणान् क्षीणकफाञ्छिशून्मदहतान्वृद्धान् रसाजीर्णिनो रात्रौ जागरितान्नरान्निरशनान्कामं दिवा स्वापयेत्","text":"vyāyāmapramadā'dhvavāhanaratān klāntānatīsāriṇaḥ śūlaśvāsavatastṛṣāparigatān hikkāmarutpīḍitān kṣīṇān kṣīṇakaphāñchiśūnmadahatānvṛddhān rasājīrṇino rātrau jāgaritānnarānniraśanānkāmaṃ divā svāpayet"},{"type":"verse","number":"299","sanskrit":"दिवा वा यदि वा रात्रौ निद्रा सात्मीकृता तु यैः न तेषां स्वपतां दोषो जाग्रतां चोपजायते","text":"divā vā yadi vā rātrau nidrā sātmīkṛtā tu yaiḥ na teṣāṃ svapatāṃ doṣo jāgratāṃ copajāyate"},{"type":"verse","number":"300","sanskrit":"भोजनानन्तरं निद्रा वातं हरति पित्तहृत् कफं करोति वपुषः पुष्टिं सौख्यं तनोति हि","text":"bhojanānantaraṃ nidrā vātaṃ harati pittahṛt kaphaṃ karoti vapuṣaḥ puṣṭiṃ saukhyaṃ tanoti hi"},{"type":"verse","number":"301","sanskrit":"शयनं पित्तनाशाय वातनाशाय मर्दनम् वमनं कफनाशाय ज्वरनाशाय लङ्घनम्","text":"śayanaṃ pittanāśāya vātanāśāya mardanam vamanaṃ kaphanāśāya jvaranāśāya laṅghanam"},{"type":"verse","number":"302","sanskrit":"आसीनं घूर्णितं यत्तु नाभिष्यन्दि न रूक्षणम्","text":"āsīnaṃ ghūrṇitaṃ yattu nābhiṣyandi na rūkṣaṇam"},{"type":"verse","number":"303","sanskrit":"शब्दान् स्पर्शांश्च रूपाणि रसान्गन्धान्मनःप्रियान् भुक्तवानपि सेवेत तेनान्नं साधु तिष्ठति","text":"śabdān sparśāṃśca rūpāṇi rasāngandhānmanaḥpriyān bhuktavānapi seveta tenānnaṃ sādhu tiṣṭhati"},{"type":"verse","number":"304","sanskrit":"शब्दः स्पर्शस्तथा रूपं रसो गन्धो जुगुप्सितः भुक्तमप्रयतं चान्नमतिहास्यं च वामयेत्","text":"śabdaḥ sparśastathā rūpaṃ raso gandho jugupsitaḥ bhuktamaprayataṃ cānnamatihāsyaṃ ca vāmayet"},{"type":"verse","number":"305","sanskrit":"शयनं चाशनं चाति न भजेन्न द्र वाधिकम् नाग्न्यातपौ न प्लवनं न यानं नापि वाहनम्","text":"śayanaṃ cāśanaṃ cāti na bhajenna dra vādhikam nāgnyātapau na plavanaṃ na yānaṃ nāpi vāhanam"},{"type":"verse","number":"306","sanskrit":"व्यायामं च व्यवायं च धावनं यानमेव च युंद्धं गीतं च पाठं च मुहूर्त्तं भुक्तवांस्त्यजेत्","text":"vyāyāmaṃ ca vyavāyaṃ ca dhāvanaṃ yānameva ca yuṃddhaṃ gītaṃ ca pāṭhaṃ ca muhūrttaṃ bhuktavāṃstyajet"},{"type":"verse","number":"307","sanskrit":"अत्यम्बुपानाद्विषमाशनाच्च सन्धारणात् स्वप्नविपर्ययाच्च कालेऽपि सात्म्यं लघु चापि भुक्तमन्नं न पाकं भजते नरस्य","text":"atyambupānādviṣamāśanācca sandhāraṇāt svapnaviparyayācca kāle'pi sātmyaṃ laghu cāpi bhuktamannaṃ na pākaṃ bhajate narasya"},{"type":"verse","number":"308","sanskrit":"ईर्ष्याभय क्रोधसमन्वितेन लुब्धेन रुग्दैन्यनिपीडितेन विद्वेषयुक्तेन च सेव्यमानमन्नं न सम्यक्परिपाकमेति","text":"īrṣyābhaya krodhasamanvitena lubdhena rugdainyanipīḍitena vidveṣayuktena ca sevyamānamannaṃ na samyakparipākameti"},{"type":"verse","number":"309","sanskrit":"अजीर्णे भुज्यते यत्तु तदध्यशनमुच्यते","text":"ajīrṇe bhujyate yattu tadadhyaśanamucyate"},{"type":"verse","number":"310","sanskrit":"प्राग्भुक्ते चानले मन्दे द्विरह्नि न समाहरेत्","text":"prāgbhukte cānale mande dvirahni na samāharet"},{"type":"verse","number":"311","sanskrit":"पूर्व भुक्ते विदग्धेऽन्ने भुञ्जानो हन्ति पावकम्","text":"pūrva bhukte vidagdhe'nne bhuñjāno hanti pāvakam"},{"type":"verse","number":"312","sanskrit":"सायमाशे त्वजीर्णे तु प्रातर्भुक्तं विषोपमम्","text":"sāyamāśe tvajīrṇe tu prātarbhuktaṃ viṣopamam"},{"type":"verse","number":"313","sanskrit":"भवेद्यदि प्रातरजीर्णशङ्का तदाऽभयां नागरसैन्धवाभ्याम् विचूर्णितां शीतजलेन भुक्त्वा भुञ्जीत चान्नं मितमन्नकाले","text":"bhavedyadi prātarajīrṇaśaṅkā tadā'bhayāṃ nāgarasaindhavābhyām vicūrṇitāṃ śītajalena bhuktvā bhuñjīta cānnaṃ mitamannakāle"},{"type":"verse","number":"314","sanskrit":"आयुःक्षयभयाद्विद्वान्नाह्नि सेवेत कामिनीम् अवशो यदि सेवेत तदा ग्रीष्मवसन्तयोः","text":"āyuḥkṣayabhayādvidvānnāhni seveta kāminīm avaśo yadi seveta tadā grīṣmavasantayoḥ"},{"type":"verse","number":"315","sanskrit":"आस्या वर्णकफस्थौल्यसौकुमार्यसुखप्रदा अध्वा वर्णकफस्थौल्यसौकुमार्यविनाशनः","text":"āsyā varṇakaphasthaulyasaukumāryasukhapradā adhvā varṇakaphasthaulyasaukumāryavināśanaḥ"},{"type":"verse","number":"316","sanskrit":"यत्तु चंक्रमणं नातिदेहपीडाकरं भवेत् तदायुर्बलमेधाऽग्निप्रदमिन्द्रि यबोधनम्","text":"yattu caṃkramaṇaṃ nātidehapīḍākaraṃ bhavet tadāyurbalamedhā'gnipradamindri yabodhanam"},{"type":"verse","number":"317","sanskrit":"उष्णीषं कान्तिकृत्केश्यं रजोवातकफापहम् लघु यच्छस्यते तस्माद् गुरु पित्ताक्षिरोगकृत्","text":"uṣṇīṣaṃ kāntikṛtkeśyaṃ rajovātakaphāpaham laghu yacchasyate tasmād guru pittākṣirogakṛt"},{"type":"verse","number":"318","sanskrit":"उपानद्धारणं नेत्र्यमायुष्यं पादरोगहृत् सुखप्रचारमोजस्यं वृष्यं च परिकीर्तितम्","text":"upānaddhāraṇaṃ netryamāyuṣyaṃ pādarogahṛt sukhapracāramojasyaṃ vṛṣyaṃ ca parikīrtitam"},{"type":"verse","number":"319","sanskrit":"पादाभ्यामनुपानद्भ्यां सदा चंक्रमणं नृणाम् अनारोग्यमनायुष्यमिन्द्रि यघ्नमदृष्टिदम्","text":"pādābhyāmanupānadbhyāṃ sadā caṃkramaṇaṃ nṛṇām anārogyamanāyuṣyamindri yaghnamadṛṣṭidam"},{"type":"verse","number":"320","sanskrit":"छत्रस्य धारणं वर्षातपवातरजोऽपहम् हिमघ्नं हितमक्ष्णोश्च मङ्गल्यमपि कीर्त्तितम्","text":"chatrasya dhāraṇaṃ varṣātapavātarajo'paham himaghnaṃ hitamakṣṇośca maṅgalyamapi kīrttitam"},{"type":"verse","number":"321","sanskrit":"सत्त्वोत्साहवलस्थैर्यधैर्यतेजोविवर्धनम् अवष्टम्भकरं चापि भयघ्नं दण्डधारणम्","text":"sattvotsāhavalasthairyadhairyatejovivardhanam avaṣṭambhakaraṃ cāpi bhayaghnaṃ daṇḍadhāraṇam"},{"type":"verse","number":"322","sanskrit":"ऊर्ध्वाच्छादनसंयुक्ता शिबिका सर्ववल्लभा तस्यामारोहणं नॄणां त्रिदोषशमकं मतम्","text":"ūrdhvācchādanasaṃyuktā śibikā sarvavallabhā tasyāmārohaṇaṃ nṝṇāṃ tridoṣaśamakaṃ matam"},{"type":"verse","number":"323","sanskrit":"वातश्लेष्मगदार्त्तानामहिता भ्रमकृत्तरिः पित्तानिलकरो हस्ती लक्ष्म्यायुःपुष्टिवर्द्धनः","text":"vātaśleṣmagadārttānāmahitā bhramakṛttariḥ pittānilakaro hastī lakṣmyāyuḥpuṣṭivarddhanaḥ"},{"type":"verse","number":"324","sanskrit":"घोटकारोहणं वातपित्ताग्निश्रमकृन्मतम् मेदोवर्णकफघ्नं च हितं तद्वलिनां परम्","text":"ghoṭakārohaṇaṃ vātapittāgniśramakṛnmatam medovarṇakaphaghnaṃ ca hitaṃ tadvalināṃ param"},{"type":"verse","number":"325","sanskrit":"आतपः स्वेदमूर्च्छाऽस्रपित्ततृष्णाक्लमश्रमान् दाहं विवर्णतां कुर्यादेतांश्छाया व्यपोहति","text":"ātapaḥ svedamūrcchā'srapittatṛṣṇāklamaśramān dāhaṃ vivarṇatāṃ kuryādetāṃśchāyā vyapohati"},{"type":"verse","number":"326","sanskrit":"वृष्टिर्वृष्या हिमा बल्या निद्रा ऽलस्यविधायिनी भयावहा मोहकरी कुहेलि कफवातला","text":"vṛṣṭirvṛṣyā himā balyā nidrā 'lasyavidhāyinī bhayāvahā mohakarī kuheli kaphavātalā"},{"type":"verse","number":"327","sanskrit":"अग्निर्वातकफस्तम्भशीतवेपथुनाशनः आमाभिष्यन्दशमनो रक्तपित्तप्रकोपणः","text":"agnirvātakaphastambhaśītavepathunāśanaḥ āmābhiṣyandaśamano raktapittaprakopaṇaḥ"},{"type":"verse","number":"328","sanskrit":"सद्यः श्लेष्मकरो धूमो नेत्रयोरहितो भृशम् शिरोगौरवकृच्चापि वातपित्तं च कोपयेत्","text":"sadyaḥ śleṣmakaro dhūmo netrayorahito bhṛśam śirogauravakṛccāpi vātapittaṃ ca kopayet"},{"type":"verse","number":"329","sanskrit":"मैत्री सद्भिः समं कुर्यात्स्नेहं सत्सु तु सर्वथा संसर्गं साधुभिः कुर्यादसत्सङ्गं परित्यजेत्","text":"maitrī sadbhiḥ samaṃ kuryātsnehaṃ satsu tu sarvathā saṃsargaṃ sādhubhiḥ kuryādasatsaṅgaṃ parityajet"},{"type":"verse","number":"330","sanskrit":"सेवेत देवभूदेववृद्धवैद्यनृपातिथीन् विमुखान्नार्थिनः कुर्यान्नावमन्येत कानपि","text":"seveta devabhūdevavṛddhavaidyanṛpātithīn vimukhānnārthinaḥ kuryānnāvamanyeta kānapi"},{"type":"verse","number":"331","sanskrit":"गुरूणां सन्निधौ तिष्ठेत्सदैव विनयान्वितः पादप्रसारणादीनि तत्र नैव समाचरेत्","text":"gurūṇāṃ sannidhau tiṣṭhetsadaiva vinayānvitaḥ pādaprasāraṇādīni tatra naiva samācaret"},{"type":"verse","number":"332","sanskrit":"अपकारपरेऽपि स्यादुपकारपरः पुमान् आत्मवत्सकलान्पश्येद्वैरिणो दूरतो वसेत्","text":"apakārapare'pi syādupakāraparaḥ pumān ātmavatsakalānpaśyedvairiṇo dūrato vaset"},{"type":"verse","number":"333","sanskrit":"न कञ्चिदात्मनः शत्रुं नात्मानं कस्यचिद्रि पुम् प्रकाशयेन्नापमानं न च निःस्नेहतां प्रभोः","text":"na kañcidātmanaḥ śatruṃ nātmānaṃ kasyacidri pum prakāśayennāpamānaṃ na ca niḥsnehatāṃ prabhoḥ"},{"type":"verse","number":"334","sanskrit":"नात्मानमुदके पश्येन्न नग्नः प्रविशेज्जलम् तथा नाज्ञातगाम्भीर्यं न हिंस्रप्राणिसेवितम्","text":"nātmānamudake paśyenna nagnaḥ praviśejjalam tathā nājñātagāmbhīryaṃ na hiṃsraprāṇisevitam"},{"type":"verse","number":"335","sanskrit":"काले हितं मितं सत्यं संवादि मधुरं वदेत् भुञ्जीत मधुरप्रायं स्निग्धं काले हितं मितम्","text":"kāle hitaṃ mitaṃ satyaṃ saṃvādi madhuraṃ vadet bhuñjīta madhuraprāyaṃ snigdhaṃ kāle hitaṃ mitam"},{"type":"verse","number":"336","sanskrit":"न रात्रौ दधि भुञ्जीत न च निर्लवणं तथा नामुद्गसूपं नाक्षौद्रं न चाप्यघृतशर्करम्","text":"na rātrau dadhi bhuñjīta na ca nirlavaṇaṃ tathā nāmudgasūpaṃ nākṣaudraṃ na cāpyaghṛtaśarkaram"},{"type":"verse","number":"337","sanskrit":"जनस्याशयमालक्ष्य यो यथा परितुष्यति तं तथैवानुवर्तेत पराराधनपण्डितः","text":"janasyāśayamālakṣya yo yathā parituṣyati taṃ tathaivānuvarteta parārādhanapaṇḍitaḥ"},{"type":"verse","number":"338","sanskrit":"नैकः सुखी न सर्वत्र विश्वस्तो न च शङ्कितः नोद्यमेविरमेत्क्वापि हेतावीर्ष्येत्फले न तु","text":"naikaḥ sukhī na sarvatra viśvasto na ca śaṅkitaḥ nodyamevirametkvāpi hetāvīrṣyetphale na tu"},{"type":"verse","number":"339","sanskrit":"वेगान्न धारयेज्जातु मनोवेगान्विधारयेत् न पीडयेदिन्द्रि याणि न चैतान्यतिलालयेत्","text":"vegānna dhārayejjātu manovegānvidhārayet na pīḍayedindri yāṇi na caitānyatilālayet"},{"type":"verse","number":"340","sanskrit":"वर्षाऽतपादिषु च्छत्री दण्डी रात्रौ भयेषु च सोपानत्कस्तनुं रक्षेद्विचरेद्युगमात्रदृक्","text":"varṣā'tapādiṣu cchatrī daṇḍī rātrau bhayeṣu ca sopānatkastanuṃ rakṣedvicaredyugamātradṛk"},{"type":"verse","number":"341","sanskrit":"नदीं तरेन्न बाहुभ्यां नाग्निस्कन्धमभिव्रजेत् सन्दिग्धनावं वृक्षं च नारोहेद्दुष्टयानकम्","text":"nadīṃ tarenna bāhubhyāṃ nāgniskandhamabhivrajet sandigdhanāvaṃ vṛkṣaṃ ca nārohedduṣṭayānakam"},{"type":"verse","number":"342","sanskrit":"नासंवृतमुखः कुर्यात्सभायां च विचक्षणः कासं हासं तथोद्गारं जृम्भणं क्षवथुं तथा","text":"nāsaṃvṛtamukhaḥ kuryātsabhāyāṃ ca vicakṣaṇaḥ kāsaṃ hāsaṃ tathodgāraṃ jṛmbhaṇaṃ kṣavathuṃ tathā"},{"type":"verse","number":"343","sanskrit":"नासिकां न विकुष्णीयान्नासीतोत्कटकः क्वचित् नोर्ध्वजानुश्चिरं तिष्ठेन्न नखेन लिखेद्भुवम्","text":"nāsikāṃ na vikuṣṇīyānnāsītotkaṭakaḥ kvacit nordhvajānuściraṃ tiṣṭhenna nakhena likhedbhuvam"},{"type":"verse","number":"344","sanskrit":"सम्मार्जनीरजो नैव देहे दद्यात्कदाचन न नखेन तृणं छिन्द्यान्नोच्छिष्टो ब्राह्मणं स्पृशेत्","text":"sammārjanīrajo naiva dehe dadyātkadācana na nakhena tṛṇaṃ chindyānnocchiṣṭo brāhmaṇaṃ spṛśet"},{"type":"verse","number":"345","sanskrit":"नोपरक्तं न चोद्यन्तं नास्तं यातं दिवाकरम् सर्वथा न समीक्षेत न जले प्रतिबिम्बितम्","text":"noparaktaṃ na codyantaṃ nāstaṃ yātaṃ divākaram sarvathā na samīkṣeta na jale pratibimbitam"},{"type":"verse","number":"346","sanskrit":"नेक्षेत सततं सूक्ष्मं दीप्तामेध्याप्रियाणि च पौरन्दरं धनुर्नैव दर्शयेत्कमपि क्वचित्","text":"nekṣeta satataṃ sūkṣmaṃ dīptāmedhyāpriyāṇi ca paurandaraṃ dhanurnaiva darśayetkamapi kvacit"},{"type":"verse","number":"347","sanskrit":"नेच्छेद्बलवता युद्धं न भारं शिरसा वहेत् गात्रं न वादयेत्केशान्हस्तेन धुनुयान्न च","text":"necchedbalavatā yuddhaṃ na bhāraṃ śirasā vahet gātraṃ na vādayetkeśānhastena dhunuyānna ca"},{"type":"verse","number":"348","sanskrit":"न गच्छेत्पूज्ययोर्मध्ये दम्पत्योरन्तरेण च रिपोरन्नं न भुञ्जीत गणिकाऽन्नमपि क्वचित्","text":"na gacchetpūjyayormadhye dampatyorantareṇa ca riporannaṃ na bhuñjīta gaṇikā'nnamapi kvacit"},{"type":"verse","number":"349","sanskrit":"प्रतिभूर्न भवेत्क्वापि न च साक्षी वृथा भवेत्","text":"pratibhūrna bhavetkvāpi na ca sākṣī vṛthā bhavet"},{"type":"verse","number":"350","sanskrit":"स्थागं न धारयेज्जातु द्यूतं दूरात्परित्यजेत्","text":"sthāgaṃ na dhārayejjātu dyūtaṃ dūrātparityajet"},{"type":"verse","number":"351","sanskrit":"विश्वासं नाचरेत्स्त्रीणां ताः स्वतंत्रा न चारयेत् रक्षणीयाः सदा यत्नाद्यौवने तु विशेषतः","text":"viśvāsaṃ nācaretstrīṇāṃ tāḥ svataṃtrā na cārayet rakṣaṇīyāḥ sadā yatnādyauvane tu viśeṣataḥ"},{"type":"verse","number":"352","sanskrit":"न भिन्ने शयने स्वप्यान्नानेकविवरेऽपि च नैको देवालये नैव रात्रौ तरुतलेऽपि च","text":"na bhinne śayane svapyānnānekavivare'pi ca naiko devālaye naiva rātrau tarutale'pi ca"},{"type":"verse","number":"353","sanskrit":"एवं दिनानि गमयेत्सदाचारपरः सदा ततो रात्रिप्रयुक्तानि कुर्यात्कर्माणि मानवः","text":"evaṃ dināni gamayetsadācāraparaḥ sadā tato rātriprayuktāni kuryātkarmāṇi mānavaḥ"},{"type":"verse","number":"354","sanskrit":"इत्याचारं समासेन भाषितं यः समाचरेत् स विंदत्यायुरारोग्यं प्रीतिं धर्मं धनं यशः","text":"ityācāraṃ samāsena bhāṣitaṃ yaḥ samācaret sa viṃdatyāyurārogyaṃ prītiṃ dharmaṃ dhanaṃ yaśaḥ"},{"type":"verse","number":"355","sanskrit":"एतानि पञ्च कर्माणि सन्ध्यायां वर्जयेद् बुधः आहारं मैथुनं निद्रां संपाठं गतिमध्वनि","text":"etāni pañca karmāṇi sandhyāyāṃ varjayed budhaḥ āhāraṃ maithunaṃ nidrāṃ saṃpāṭhaṃ gatimadhvani"},{"type":"verse","number":"356","sanskrit":"भोजनाज्जायते व्याधिर्मैथुनाद्गर्भवैकृतिः निद्र या निःस्वता पाठादायुर्हानिर्गतेर्भयम्","text":"bhojanājjāyate vyādhirmaithunādgarbhavaikṛtiḥ nidra yā niḥsvatā pāṭhādāyurhānirgaterbhayam"},{"type":"verse","number":"357","sanskrit":"ज्योत्स्ना शीता स्मरानन्दप्रदा तृट्पित्तदाहहृत् ततो हीनगुणः कुर्यादवश्यायोऽनिलं कफम्","text":"jyotsnā śītā smarānandapradā tṛṭpittadāhahṛt tato hīnaguṇaḥ kuryādavaśyāyo'nilaṃ kapham"},{"type":"verse","number":"358","sanskrit":"तमो भयावहं मोहदिङ्मोहजनकं भवेत् पित्तहृत्कफहृत्कामवर्धनं क्लमकृच्च तत्","text":"tamo bhayāvahaṃ mohadiṅmohajanakaṃ bhavet pittahṛtkaphahṛtkāmavardhanaṃ klamakṛcca tat"},{"type":"verse","number":"359","sanskrit":"रात्रौ च भोजनं कुर्यात्प्रथमप्रहरान्तरे किञ्चिदूनं समश्नीयाद् दुर्जरं तत्र वर्जयेत्","text":"rātrau ca bhojanaṃ kuryātprathamapraharāntare kiñcidūnaṃ samaśnīyād durjaraṃ tatra varjayet"},{"type":"verse","number":"360","sanskrit":"शरीरे जायते नित्यं देहिनः सुरतस्पृहा अव्यवायान्मेहमेदोवृद्धिः शिथिलता तनोः","text":"śarīre jāyate nityaṃ dehinaḥ surataspṛhā avyavāyānmehamedovṛddhiḥ śithilatā tanoḥ"},{"type":"verse","number":"361","sanskrit":"बालेति गीयते नारी यावद्वर्षाणि षोडश ततस्तु तरुणी ज्ञेया द्वात्रिंशद्वत्सरावधि","text":"bāleti gīyate nārī yāvadvarṣāṇi ṣoḍaśa tatastu taruṇī jñeyā dvātriṃśadvatsarāvadhi"},{"type":"verse","number":"362","sanskrit":"तदूर्ध्वमधिरुढा स्यात्पञ्चाशद्वत्सरावधि वृद्धा तत्परतो ज्ञेया सुरतोत्सववर्जिता","text":"tadūrdhvamadhiruḍhā syātpañcāśadvatsarāvadhi vṛddhā tatparato jñeyā suratotsavavarjitā"},{"type":"verse","number":"363","sanskrit":"निदाघशरदोर्वाला हिता विषयिणां मता तरुणी शीतसमये प्रौढा वर्षावसन्तयोः","text":"nidāghaśaradorvālā hitā viṣayiṇāṃ matā taruṇī śītasamaye prauḍhā varṣāvasantayoḥ"},{"type":"verse","number":"364","sanskrit":"नित्यं बाला सेव्यमाना नित्यं वर्धयते वलम् तरुणी ह्रासयेच्छक्तिं प्रौढोद्भावयते जराम्","text":"nityaṃ bālā sevyamānā nityaṃ vardhayate valam taruṇī hrāsayecchaktiṃ prauḍhodbhāvayate jarām"},{"type":"verse","number":"365","sanskrit":"सद्यो मांसं नवं चान्नं वाला स्त्री क्षीरभोजनम् घृतमुष्णोदके स्नानं सद्यः प्राणकराणिषट्","text":"sadyo māṃsaṃ navaṃ cānnaṃ vālā strī kṣīrabhojanam ghṛtamuṣṇodake snānaṃ sadyaḥ prāṇakarāṇiṣaṭ"},{"type":"verse","number":"366","sanskrit":"पूतिमांसं स्त्रियो वृद्धा बालाऽकस्तरुणं दधि प्रभाते मैथुनं निद्रा सद्यः प्राणहराणि षट्","text":"pūtimāṃsaṃ striyo vṛddhā bālā'kastaruṇaṃ dadhi prabhāte maithunaṃ nidrā sadyaḥ prāṇaharāṇi ṣaṭ"},{"type":"verse","number":"367","sanskrit":"वृद्धोऽपि तरुणीं गत्वा तरुणत्वमवाप्नुयात् वयोधिकां स्त्रियं गत्वा तरुणः स्थविरायते","text":"vṛddho'pi taruṇīṃ gatvā taruṇatvamavāpnuyāt vayodhikāṃ striyaṃ gatvā taruṇaḥ sthavirāyate"},{"type":"verse","number":"368","sanskrit":"आयुष्मन्तो मन्दजरा वपुर्वर्णबलान्विताः स्थिरोपचितमांसाश्च भवन्ति स्त्रीषु संयताः","text":"āyuṣmanto mandajarā vapurvarṇabalānvitāḥ sthiropacitamāṃsāśca bhavanti strīṣu saṃyatāḥ"},{"type":"verse","number":"369","sanskrit":"सेवेत कामतः कामं बलाद्वाजीकृतो हिमे प्रकामं तु निषेवेत मैथुनं शिशिरागमे","text":"seveta kāmataḥ kāmaṃ balādvājīkṛto hime prakāmaṃ tu niṣeveta maithunaṃ śiśirāgame"},{"type":"verse","number":"370","sanskrit":"त्र्यहाद्वसन्तशरदोः पक्षाद् वृष्टिनिदाघयोः","text":"tryahādvasantaśaradoḥ pakṣād vṛṣṭinidāghayoḥ"},{"type":"verse","number":"371","sanskrit":"त्रिभिस्त्रिभिरहोभिर्हि समेयात्प्रमदां नरः सर्वेष्वृतुषु घर्मे तु पक्षात्पक्षाद् व्रजेद् बुधः","text":"tribhistribhirahobhirhi sameyātpramadāṃ naraḥ sarveṣvṛtuṣu gharme tu pakṣātpakṣād vrajed budhaḥ"},{"type":"verse","number":"372","sanskrit":"शीते रात्रौ दिवा ग्रीष्मे वसन्ते तु दिवा निशि वर्षासु वारिदध्वाने शरत्सु सरसः स्मरः","text":"śīte rātrau divā grīṣme vasante tu divā niśi varṣāsu vāridadhvāne śaratsu sarasaḥ smaraḥ"},{"type":"verse","number":"373","sanskrit":"उपेयात्पुरुषो नारीं संध्ययोर्न च पर्वसु गोसर्गे चार्द्धरात्रे च तथा मध्यदिनेऽपि च","text":"upeyātpuruṣo nārīṃ saṃdhyayorna ca parvasu gosarge cārddharātre ca tathā madhyadine'pi ca"},{"type":"verse","number":"374","sanskrit":"विहारं भार्यया कुर्याद् देशेऽतिशयसंवृते रम्ये श्राव्याङ्गनागाने सुगन्धे सुखमारुते","text":"vihāraṃ bhāryayā kuryād deśe'tiśayasaṃvṛte ramye śrāvyāṅganāgāne sugandhe sukhamārute"},{"type":"verse","number":"375","sanskrit":"देशे गुरुजनासन्ने विवृतेऽतित्रपाकरे श्रूयमाणे व्यथाहेतुवचने न रमेत ना","text":"deśe gurujanāsanne vivṛte'titrapākare śrūyamāṇe vyathāhetuvacane na rameta nā"},{"type":"verse","number":"376","sanskrit":"स्नातचन्दनलिप्ताङ्गः सुगन्धः सुमनोऽन्वितः भुक्तवृष्यः सुवसनः सुवेषः समलंकृतः","text":"snātacandanaliptāṅgaḥ sugandhaḥ sumano'nvitaḥ bhuktavṛṣyaḥ suvasanaḥ suveṣaḥ samalaṃkṛtaḥ"},{"type":"verse","number":"377","sanskrit":"ताम्बूलवदनः पत्न्यामनुरक्तोऽधिकस्मरः पुत्रार्थी पुरुषो नारीमुपेयाच्छयने शुभे","text":"tāmbūlavadanaḥ patnyāmanurakto'dhikasmaraḥ putrārthī puruṣo nārīmupeyācchayane śubhe"},{"type":"verse","number":"378","sanskrit":"अत्याशितोऽधृतिः क्षुद्वान्सव्यथाङ्गः पिपासितः बालो वृद्धोऽन्यवेगार्त्तस्त्यजेद्रो गी च मैथुनम्","text":"atyāśito'dhṛtiḥ kṣudvānsavyathāṅgaḥ pipāsitaḥ bālo vṛddho'nyavegārttastyajedro gī ca maithunam"},{"type":"verse","number":"379","sanskrit":"भार्यां रूपगुणोपेतां तुल्यशीलां कुलोद्भवाम् अतिकामोऽभिकामां तु हृष्टो हृष्टामलंकृताम् सेवेत प्रमदां युक्त्या वाजीकरणवृंहितः","text":"bhāryāṃ rūpaguṇopetāṃ tulyaśīlāṃ kulodbhavām atikāmo'bhikāmāṃ tu hṛṣṭo hṛṣṭāmalaṃkṛtām seveta pramadāṃ yuktyā vājīkaraṇavṛṃhitaḥ"},{"type":"verse","number":"380","sanskrit":"रजस्वलामकामां च मलिनामप्रियां तथा","text":"rajasvalāmakāmāṃ ca malināmapriyāṃ tathā"},{"type":"verse","number":"381","sanskrit":"वर्णबृद्धां वयोवृद्धां तथा व्याधिप्रपीडिताम् हीनाङ्गीं गर्भिणीं द्वेष्यां योनिरोगसमन्विताम्","text":"varṇabṛddhāṃ vayovṛddhāṃ tathā vyādhiprapīḍitām hīnāṅgīṃ garbhiṇīṃ dveṣyāṃ yonirogasamanvitām"},{"type":"verse","number":"382","sanskrit":"सगोत्रां गुरुपत्नीं च तथा प्रव्रजितामपि नाधिगच्छेत् पुमान्नारीं भूरिवैगुण्यशङ्कया","text":"sagotrāṃ gurupatnīṃ ca tathā pravrajitāmapi nādhigacchet pumānnārīṃ bhūrivaiguṇyaśaṅkayā"},{"type":"verse","number":"383","sanskrit":"रजस्वलां गतवतो नरस्यासंयतात्मनः दृष्ट्यायुस्तेजसां हानिरधर्मश्च ततो भवेत्","text":"rajasvalāṃ gatavato narasyāsaṃyatātmanaḥ dṛṣṭyāyustejasāṃ hāniradharmaśca tato bhavet"},{"type":"verse","number":"384","sanskrit":"लिगिनीं गुरुपत्नीं च सगोत्रामथ पर्वसु वृद्धां च सन्ध्ययोश्चापि गच्छतो जीवनक्षयः","text":"liginīṃ gurupatnīṃ ca sagotrāmatha parvasu vṛddhāṃ ca sandhyayoścāpi gacchato jīvanakṣayaḥ"},{"type":"verse","number":"385","sanskrit":"गर्भिण्यां गर्भपीडा स्याद्व्याधितायां बलक्षयः","text":"garbhiṇyāṃ garbhapīḍā syādvyādhitāyāṃ balakṣayaḥ"},{"type":"verse","number":"386","sanskrit":"हीनाङ्गीं मलिनां द्वेष्यां क्षामां वन्ध्यामसंवृते देशेऽभिगच्छतो रेतः क्षीणं म्लानं मनो भवेत्","text":"hīnāṅgīṃ malināṃ dveṣyāṃ kṣāmāṃ vandhyāmasaṃvṛte deśe'bhigacchato retaḥ kṣīṇaṃ mlānaṃ mano bhavet"},{"type":"verse","number":"387","sanskrit":"क्षुधितः क्षुब्धचित्तश्च मध्याह्ने तृषितोऽबलः स्थितस्य हानिं शुक्रस्य वायोः कोपं च विन्दति","text":"kṣudhitaḥ kṣubdhacittaśca madhyāhne tṛṣito'balaḥ sthitasya hāniṃ śukrasya vāyoḥ kopaṃ ca vindati"},{"type":"verse","number":"388","sanskrit":"व्याधितस्य रुजा प्लीहा मूर्च्छा मृत्युश्च जायते प्रत्यूषे चार्धरात्रे च वातपित्ते प्रक्प्यतः","text":"vyādhitasya rujā plīhā mūrcchā mṛtyuśca jāyate pratyūṣe cārdharātre ca vātapitte prakpyataḥ"},{"type":"verse","number":"389","sanskrit":"तिर्यग्योनावयोनौ वा दुष्टयोनौ तथैव च उपदंशस्तथा वायोः कोपः शुक्रसुखक्षयः","text":"tiryagyonāvayonau vā duṣṭayonau tathaiva ca upadaṃśastathā vāyoḥ kopaḥ śukrasukhakṣayaḥ"},{"type":"verse","number":"390","sanskrit":"उच्चारिते मूत्रिते च रेतसश्च विधारणे उत्ताने च भवेच्छीघ्रं शुक्राश्मर्यास्तु सम्भवः","text":"uccārite mūtrite ca retasaśca vidhāraṇe uttāne ca bhavecchīghraṃ śukrāśmaryāstu sambhavaḥ"},{"type":"verse","number":"391","sanskrit":"सर्वमेतत्त्यजेत्तस्माद्यतो लोकद्वयाहितम् शुक्रं तूपस्थितं मोहान्न सन्धार्यं कदा चन","text":"sarvametattyajettasmādyato lokadvayāhitam śukraṃ tūpasthitaṃ mohānna sandhāryaṃ kadā cana"},{"type":"verse","number":"392","sanskrit":"स्नानं सशर्करं क्षीरं भक्ष्यमैक्षवसंस्कृतम् वातो मांसरसः स्वप्नः सुरतान्ते हिता अमी","text":"snānaṃ saśarkaraṃ kṣīraṃ bhakṣyamaikṣavasaṃskṛtam vāto māṃsarasaḥ svapnaḥ suratānte hitā amī"},{"type":"verse","number":"393","sanskrit":"शूलकासज्वरश्वासकार्श्यपाण्ड्वामयक्षयाः अतिव्यवायाज्जायन्ते रोगाश्चाक्षेपकादयः","text":"śūlakāsajvaraśvāsakārśyapāṇḍvāmayakṣayāḥ ativyavāyājjāyante rogāścākṣepakādayaḥ"},{"type":"verse","number":"394","sanskrit":"रोत्रौ जागरणं रूक्षं कफदोषविषार्तिजित् निद्रा तु सेविताकाले धातुसाम्यमतन्द्रि ताम्","text":"rotrau jāgaraṇaṃ rūkṣaṃ kaphadoṣaviṣārtijit nidrā tu sevitākāle dhātusāmyamatandri tām"},{"type":"verse","number":"395","sanskrit":"पुष्टिं वर्णं बलोत्साहं वह्निदीप्तिं करोति हि","text":"puṣṭiṃ varṇaṃ balotsāhaṃ vahnidīptiṃ karoti hi"},{"type":"verse","number":"396","sanskrit":"यो लेढि शयनसमये मधुमिश्रं बीजपूरदलचूर्णम् स तु लज्जाकरवातप्रसरनिरोधात्सुखं स्वपिति","text":"yo leḍhi śayanasamaye madhumiśraṃ bījapūradalacūrṇam sa tu lajjākaravātaprasaranirodhātsukhaṃ svapiti"},{"type":"verse","number":"397","sanskrit":"सवितुः समुदयकाले प्रसृतीः सलिलस्य यः पिबेदष्टौ रोगजरापरिमुक्तो जीवेद्वत्सरशतं साग्रम्","text":"savituḥ samudayakāle prasṛtīḥ salilasya yaḥ pibedaṣṭau rogajarāparimukto jīvedvatsaraśataṃ sāgram"},{"type":"verse","number":"398","sanskrit":"अर्शःशोथग्रहण्यो ज्वरजठरजराकुष्ठमेदोविकाराः मूत्राघातास्रपित्तश्रवणगलशिरःश्रोणिशूलाक्षिरोगाः ये चान्ये वातपित्तक्षतजकफकृता व्याधयः सन्ति जन्तो स्तांस्तानभ्यासयोगादपहरति पयः पीतमन्ते निशायाः","text":"arśaḥśothagrahaṇyo jvarajaṭharajarākuṣṭhamedovikārāḥ mūtrāghātāsrapittaśravaṇagalaśiraḥśroṇiśūlākṣirogāḥ ye cānye vātapittakṣatajakaphakṛtā vyādhayaḥ santi janto stāṃstānabhyāsayogādapaharati payaḥ pītamante niśāyāḥ"},{"type":"verse","number":"399","sanskrit":"विगतघननिशीथे प्रातरुत्थाय नित्यं पिबति खलु नरो यो घ्राणरन्ध्रेण वारि स भवति मतिपूर्णश्चक्षुषा तार्क्ष्यतुल्यो वलिपलितविहीनः सर्वरोगैर्विमुक्तः","text":"vigataghananiśīthe prātarutthāya nityaṃ pibati khalu naro yo ghrāṇarandhreṇa vāri sa bhavati matipūrṇaścakṣuṣā tārkṣyatulyo valipalitavihīnaḥ sarvarogairvimuktaḥ"},{"type":"verse","number":"400","sanskrit":"पातव्यं नासया नीरं प्रसृतित्रयमात्रया","text":"pātavyaṃ nāsayā nīraṃ prasṛtitrayamātrayā"},{"type":"verse","number":"401","sanskrit":"व्यङ्गवलीपलितघ्नंपीनसवैस्वर्यकासशोथहरम् रजनीक्षयेऽम्बुनस्यं रसायनं दृष्टिसञ्जननम्","text":"vyaṅgavalīpalitaghnaṃpīnasavaisvaryakāsaśothaharam rajanīkṣaye'mbunasyaṃ rasāyanaṃ dṛṣṭisañjananam"},{"type":"verse","number":"402","sanskrit":"स्नेहे पीते क्षते शुद्धावाध्माने स्तिमितोदरे हिक्कायां कफवातोत्थे व्याधौ तद्वारि वारयेत्","text":"snehe pīte kṣate śuddhāvādhmāne stimitodare hikkāyāṃ kaphavātotthe vyādhau tadvāri vārayet"},{"type":"verse","number":"403","sanskrit":"क्षयकोपशमा यस्मिन्दोषाणां सम्भवन्ति हि ऋतुषट्कं तदाख्यातं रवेः राशिषु संक्रमात्","text":"kṣayakopaśamā yasmindoṣāṇāṃ sambhavanti hi ṛtuṣaṭkaṃ tadākhyātaṃ raveḥ rāśiṣu saṃkramāt"},{"type":"verse","number":"404","sanskrit":"ग्रीष्मो मेषबृषौ प्रोक्तः प्रावृण्मिथुनकर्कटौ सिंहकन्ये स्मृता वर्षा तुलावृश्चिकयोः शरत्","text":"grīṣmo meṣabṛṣau proktaḥ prāvṛṇmithunakarkaṭau siṃhakanye smṛtā varṣā tulāvṛścikayoḥ śarat"},{"type":"verse","number":"405","sanskrit":"धनुर्ग्राहौ च हेमन्तो वसन्तः कुम्भमीनयोः","text":"dhanurgrāhau ca hemanto vasantaḥ kumbhamīnayoḥ"},{"type":"verse","number":"406","sanskrit":"शिशिरः पुष्पसमयो ग्रीष्मो वर्षा शरद्धिमाः माघादिमासयुग्मं स्युरृतवः षट् क्रमादमी","text":"śiśiraḥ puṣpasamayo grīṣmo varṣā śaraddhimāḥ māghādimāsayugmaṃ syurṛtavaḥ ṣaṭ kramādamī"},{"type":"verse","number":"407","sanskrit":"गङ्गाया दक्षिणे देशे वृष्टेर्बहुलभावतः उभौ मुनिभिराख्यातौ प्रावृड्वर्षाभिधावृतू","text":"gaṅgāyā dakṣiṇe deśe vṛṣṭerbahulabhāvataḥ ubhau munibhirākhyātau prāvṛḍvarṣābhidhāvṛtū"},{"type":"verse","number":"408","sanskrit":"तिस्याएवोत्तरेदेशे हिमप्रचुरभावतः एतावुभौ समाख्यातौ हेमन्तशिशिरावृतू","text":"tisyāevottaredeśe himapracurabhāvataḥ etāvubhau samākhyātau hemantaśiśirāvṛtū"},{"type":"verse","number":"409","sanskrit":"उत्तरायणमाद्यैस्तैः परैः स्याद्दक्षिणायनम् आद्यमुष्णं बलहरं ततोऽन्यद्बलदं हिमम्","text":"uttarāyaṇamādyaistaiḥ paraiḥ syāddakṣiṇāyanam ādyamuṣṇaṃ balaharaṃ tato'nyadbaladaṃ himam"},{"type":"verse","number":"410","sanskrit":"हेमन्तं शीतलः स्निग्धः स्वादुर्जठरवह्निकृत् शिशिरः शीतलोऽतीव रूक्षो वाताग्निवर्धनः","text":"hemantaṃ śītalaḥ snigdhaḥ svādurjaṭharavahnikṛt śiśiraḥ śītalo'tīva rūkṣo vātāgnivardhanaḥ"},{"type":"verse","number":"411","sanskrit":"वसन्तो मधुरः स्निग्धः श्लेष्मवृद्धिकरश्च सः ग्रीष्मो रूक्षोऽतिकटुकः पित्तकृत्कफनाशनः","text":"vasanto madhuraḥ snigdhaḥ śleṣmavṛddhikaraśca saḥ grīṣmo rūkṣo'tikaṭukaḥ pittakṛtkaphanāśanaḥ"},{"type":"verse","number":"412","sanskrit":"वर्षाः शीता विदाहिन्यो वह्निमान्द्यानिलप्रदाः शरदुष्णा पित्तकर्त्री नृणां मध्यबलावहा","text":"varṣāḥ śītā vidāhinyo vahnimāndyānilapradāḥ śaraduṣṇā pittakartrī nṛṇāṃ madhyabalāvahā"},{"type":"verse","number":"413","sanskrit":"चयप्रकोपोपशमा वायोर्ग्रीष्मादिषु त्रिषु वर्षाऽदिषु च पित्तस्य श्लेष्मणः शिशिरादिषु","text":"cayaprakopopaśamā vāyorgrīṣmādiṣu triṣu varṣā'diṣu ca pittasya śleṣmaṇaḥ śiśirādiṣu"},{"type":"verse","number":"414","sanskrit":"चीयते लघुरूक्षाभिरोषधीभिः समीरणः तद्विधस्तद्विधे देहे कालस्यौष्ण्यान्न कुप्यति","text":"cīyate laghurūkṣābhiroṣadhībhiḥ samīraṇaḥ tadvidhastadvidhe dehe kālasyauṣṇyānna kupyati"},{"type":"verse","number":"415","sanskrit":"अद्भिरम्लविपाकाभिरोषधीभिश्च तादृशम् पित्तं याति चयं कोपं न तु कालस्य शैत्यतः","text":"adbhiramlavipākābhiroṣadhībhiśca tādṛśam pittaṃ yāti cayaṃ kopaṃ na tu kālasya śaityataḥ"},{"type":"verse","number":"416","sanskrit":"चीयते स्निग्धशीताभिरुदकौषधिभिः कफः तुल्ये च काले देहे च स्कन्नत्वान्न प्रकुप्यति","text":"cīyate snigdhaśītābhirudakauṣadhibhiḥ kaphaḥ tulye ca kāle dehe ca skannatvānna prakupyati"},{"type":"verse","number":"417","sanskrit":"हिमे याति शमं पित्तं वायुः श्लेष्मा च चीयते स वायुः शिशिरे कोपं यात्येवोपचितः कफः","text":"hime yāti śamaṃ pittaṃ vāyuḥ śleṣmā ca cīyate sa vāyuḥ śiśire kopaṃ yātyevopacitaḥ kaphaḥ"},{"type":"verse","number":"418","sanskrit":"हेमन्ते सञ्चितः श्लेष्मा शिशिरे त्वतिचीयते शीतस्निग्धगुरुद्र व्यैः शैत्यस्कन्नो न कुप्यति","text":"hemante sañcitaḥ śleṣmā śiśire tvaticīyate śītasnigdhagurudra vyaiḥ śaityaskanno na kupyati"},{"type":"verse","number":"419","sanskrit":"इति कालस्वभावोऽयमाहारादिवशात्पुनः चयादीन् यान्ति सद्योऽपि दोषाः काले विशेषतः","text":"iti kālasvabhāvo'yamāhārādivaśātpunaḥ cayādīn yānti sadyo'pi doṣāḥ kāle viśeṣataḥ"},{"type":"verse","number":"420","sanskrit":"चयकोपमशमान्दोषा विहाराहारसेवनैः समानैर्यान्त्यकालेऽपि विपरीतैर्विपर्ययम्","text":"cayakopamaśamāndoṣā vihārāhārasevanaiḥ samānairyāntyakāle'pi viparītairviparyayam"},{"type":"verse","number":"421","sanskrit":"स्वस्थानस्थस्य दोषस्य वृद्धिः स्यात्स्तब्धकोषता पीतावभासता वह्निमन्दता चाङ्गगौरवम्","text":"svasthānasthasya doṣasya vṛddhiḥ syātstabdhakoṣatā pītāvabhāsatā vahnimandatā cāṅgagauravam"},{"type":"verse","number":"422","sanskrit":"आलस्यं चयहेतौ तु द्वेषश्च चयलक्षणम् सञ्चये ऽपहृता दोषा लभन्ते नोत्तरां गतिम्","text":"ālasyaṃ cayahetau tu dveṣaśca cayalakṣaṇam sañcaye 'pahṛtā doṣā labhante nottarāṃ gatim"},{"type":"verse","number":"423","sanskrit":"ते तूत्तरासु गतिषु भवन्ति बलवत्तराः","text":"te tūttarāsu gatiṣu bhavanti balavattarāḥ"},{"type":"verse","number":"424","sanskrit":"वर्षासुप्रबलो वायुस्तस्मान्मिष्टादयस्त्रयः रसाः सेव्या विशेषेण पवनस्योपशान्तये","text":"varṣāsuprabalo vāyustasmānmiṣṭādayastrayaḥ rasāḥ sevyā viśeṣeṇa pavanasyopaśāntaye"},{"type":"verse","number":"425","sanskrit":"भवेद्वर्षासु वपुषः क्लिन्नत्वं यद्विशेषतः तत्क्लेदशान्तये सेव्या अपि कट्वादयस्त्रयः","text":"bhavedvarṣāsu vapuṣaḥ klinnatvaṃ yadviśeṣataḥ tatkledaśāntaye sevyā api kaṭvādayastrayaḥ"},{"type":"verse","number":"426","sanskrit":"स्वेदनं मर्दनं सेव्यं दध्युष्णंजाङ्गलामिषम् शालयो यवगोधूमा जलं कौपं जलं च्युतम्","text":"svedanaṃ mardanaṃ sevyaṃ dadhyuṣṇaṃjāṅgalāmiṣam śālayo yavagodhūmā jalaṃ kaupaṃ jalaṃ cyutam"},{"type":"verse","number":"427","sanskrit":"न भजेत्पूर्वपवनं वृष्टिं घर्मं हिमं श्रमम् नदीतीरं दिवास्वप्नं रूक्षं नित्यं च मैथुनम्","text":"na bhajetpūrvapavanaṃ vṛṣṭiṃ gharmaṃ himaṃ śramam nadītīraṃ divāsvapnaṃ rūkṣaṃ nityaṃ ca maithunam"},{"type":"verse","number":"428","sanskrit":"सर्पिः स्वादुकषायतिक्तकरसा यच्छीतलं यल्लघु क्षीरं स्वच्छसितैक्षवः पटुरसः स्वल्पं पलं जाङ्गलम् गोधूमा यवमुद्गशालिसहिता नादेयमंशूदकं चन्द्र श्चन्दनमिन्दुरादिरजनी माल्यं पटो निर्मलः","text":"sarpiḥ svādukaṣāyatiktakarasā yacchītalaṃ yallaghu kṣīraṃ svacchasitaikṣavaḥ paṭurasaḥ svalpaṃ palaṃ jāṅgalam godhūmā yavamudgaśālisahitā nādeyamaṃśūdakaṃ candra ścandanamindurādirajanī mālyaṃ paṭo nirmalaḥ"},{"type":"verse","number":"429","sanskrit":"दिविसेऽककरैर्जुष्टं निशि शीतकरांशुभिः ज्ञेयमंशूदकं नाम स्निग्धं दोषत्रयापहम् विश्रामः सुहृदां गणेषु मधुरा वाचः सरः क्रीडनं पित्तानां च विरेचनं बलवतो युक्तं शिरामोक्षणम् एतांयत्र घनावसानसमयेपथ्यानि मुञ्चेद्दधिव्यायामाम्लकटूष्णतीक्ष्ण दिवसस्वप्नं हिमञ्चातपम्","text":"divise'kakarairjuṣṭaṃ niśi śītakarāṃśubhiḥ jñeyamaṃśūdakaṃ nāma snigdhaṃ doṣatrayāpaham viśrāmaḥ suhṛdāṃ gaṇeṣu madhurā vācaḥ saraḥ krīḍanaṃ pittānāṃ ca virecanaṃ balavato yuktaṃ śirāmokṣaṇam etāṃyatra ghanāvasānasamayepathyāni muñceddadhivyāyāmāmlakaṭūṣṇatīkṣṇa divasasvapnaṃ himañcātapam"},{"type":"verse","number":"430","sanskrit":"इक्षवः शालयो मुद्गाः सरोऽम्भ क्वथितं पयः शरद्येतानि पथ्यानि प्रदोषे चेन्दुरश्मयः","text":"ikṣavaḥ śālayo mudgāḥ saro'mbha kvathitaṃ payaḥ śaradyetāni pathyāni pradoṣe cenduraśmayaḥ"},{"type":"verse","number":"431","sanskrit":"प्रातर्भोजनमम्लमिष्टलवणानभ्यङ्गघर्मश्रमान् गोधूमैक्षवशालिमाषपिशितं पिष्टं नवान्नं तिलान् कस्तूरीं वरकुङ्कुमागुरुयुतामुष्णाम्बुशौचं तथौ स्निग्धं स्त्रीषु सुखं गुरूष्णवसनं सेवेत हेमन्तके","text":"prātarbhojanamamlamiṣṭalavaṇānabhyaṅgagharmaśramān godhūmaikṣavaśālimāṣapiśitaṃ piṣṭaṃ navānnaṃ tilān kastūrīṃ varakuṅkumāguruyutāmuṣṇāmbuśaucaṃ tathau snigdhaṃ strīṣu sukhaṃ gurūṣṇavasanaṃ seveta hemantake"},{"type":"verse","number":"432","sanskrit":"शिशिरे शीतमधिकं रौक्ष्यं चादानकालजम् विशेषतस्ततस्तत्र हेमन्तस्य मतो विधिः","text":"śiśire śītamadhikaṃ raukṣyaṃ cādānakālajam viśeṣatastatastatra hemantasya mato vidhiḥ"},{"type":"verse","number":"433","sanskrit":"वान्तिं नस्यमथाभयां च मधुना व्यायाममुद्वर्त्तनं संसेवेत मधौ कफघ्नकवलं शूल्यं पलं जाङ्गलम् गोधूमान्बहुशालिभेदसहितान्मुद्गान्यवान्षष्टिकां ल्लेपञ्चन्दनकुङ्कुमागुरुकृतं रूक्षं कटूष्णं लघु","text":"vāntiṃ nasyamathābhayāṃ ca madhunā vyāyāmamudvarttanaṃ saṃseveta madhau kaphaghnakavalaṃ śūlyaṃ palaṃ jāṅgalam godhūmānbahuśālibhedasahitānmudgānyavānṣaṣṭikāṃ llepañcandanakuṅkumāgurukṛtaṃ rūkṣaṃ kaṭūṣṇaṃ laghu"},{"type":"verse","number":"434","sanskrit":"मिष्टमम्लं दधिस्निग्धं दिवास्वप्नं च दुर्जरम् अवश्यायमपि प्राज्ञो वसन्ते परिवर्जयेत्","text":"miṣṭamamlaṃ dadhisnigdhaṃ divāsvapnaṃ ca durjaram avaśyāyamapi prājño vasante parivarjayet"},{"type":"verse","number":"435","sanskrit":"स्वादुस्निग्धहिमं लघु द्र वमयं द्र व्यं रसालां सितां सक्तुंक्षीरमजाङ्गलानि सितया शालि रसं मांसजम् शीतांशुं शयनं दिवा मलयजं शीतं पयः पानकं सेवेतोष्णदिने त्यजेत्तु कटुकक्षाराम्लघर्मश्रमान्","text":"svādusnigdhahimaṃ laghu dra vamayaṃ dra vyaṃ rasālāṃ sitāṃ saktuṃkṣīramajāṅgalāni sitayā śāli rasaṃ māṃsajam śītāṃśuṃ śayanaṃ divā malayajaṃ śītaṃ payaḥ pānakaṃ sevetoṣṇadine tyajettu kaṭukakṣārāmlagharmaśramān"},{"type":"verse","number":"436","sanskrit":"ॠतुष्वेषु य एतैस्तु विधिभिर्वर्त्तते नरः दोषानृतुकृतान्नैव लभते स कदाचन","text":"ṝtuṣveṣu ya etaistu vidhibhirvarttate naraḥ doṣānṛtukṛtānnaiva labhate sa kadācana"},{"type":"verse","number":"437","sanskrit":"इति श्रीलटकन तनय श्रीमन्मिश्रभाव विरचिते भावप्रकाशे","text":"iti śrīlaṭakana tanaya śrīmanmiśrabhāva viracite bhāvaprakāśe"}]},{"sthana":"Пурвакханда","number":5,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть I, пракарана 5"},{"type":"verse","number":"1","sanskrit":"रोगस्तु दोषवैषम्यं दोषसाम्यमरोगता रोगा दुःखस्य दातारो ज्वरप्रभृतयो हि ते","text":"rogastu doṣavaiṣamyaṃ doṣasāmyamarogatā rogā duḥkhasya dātāro jvaraprabhṛtayo hi te"},{"type":"verse","number":"2","sanskrit":"ते च स्वाभाविकाः केचित्केचिदागन्तवः स्मृताः मानसाः केचिदाख्याताः कथिताः केऽपि कायिकाः","text":"te ca svābhāvikāḥ kecitkecidāgantavaḥ smṛtāḥ mānasāḥ kecidākhyātāḥ kathitāḥ ke'pi kāyikāḥ"},{"type":"verse","number":"3","sanskrit":"कर्मजाः कथिताः केचिद्दोषजाः सन्ति चापरे कर्मदोषोद्भवाश्चान्ये व्याधयस्त्रिविधाः स्मृताः","text":"karmajāḥ kathitāḥ keciddoṣajāḥ santi cāpare karmadoṣodbhavāścānye vyādhayastrividhāḥ smṛtāḥ"},{"type":"verse","number":"4","sanskrit":"कर्मक्षयात्कर्मकृता दोषजाः स्वस्वभेषजैः कर्मदोषोद्भवा यान्ति कर्मदोषक्षयात् क्षयम्","text":"karmakṣayātkarmakṛtā doṣajāḥ svasvabheṣajaiḥ karmadoṣodbhavā yānti karmadoṣakṣayāt kṣayam"},{"type":"verse","number":"5","sanskrit":"साध्या याप्या असाध्याश्च व्याधयस्त्रिविधाः स्मृताः सुखसाध्यः कष्टसाध्यो द्विविधः साध्य उच्यते","text":"sādhyā yāpyā asādhyāśca vyādhayastrividhāḥ smṛtāḥ sukhasādhyaḥ kaṣṭasādhyo dvividhaḥ sādhya ucyate"},{"type":"verse","number":"6","sanskrit":"यापनीयं तु तं विद्यात्क्रिया धारयते हि यम् क्रियायां तु निवृत्तायां सद्यो यश्च विनश्यति","text":"yāpanīyaṃ tu taṃ vidyātkriyā dhārayate hi yam kriyāyāṃ tu nivṛttāyāṃ sadyo yaśca vinaśyati"},{"type":"verse","number":"7","sanskrit":"प्राप्ता क्रिया धारयति सुखिनं याप्यमातुरम् प्रपतिष्यदिवागारं स्तम्भो यत्नेन योजितः","text":"prāptā kriyā dhārayati sukhinaṃ yāpyamāturam prapatiṣyadivāgāraṃ stambho yatnena yojitaḥ"},{"type":"verse","number":"8","sanskrit":"साध्या याप्यत्वमायान्ति याप्याश्चासाध्यतां तथा घ्नन्ति प्राणानसाध्यास्तु नराणामक्रियावताम्","text":"sādhyā yāpyatvamāyānti yāpyāścāsādhyatāṃ tathā ghnanti prāṇānasādhyāstu narāṇāmakriyāvatām"},{"type":"verse","number":"9","sanskrit":"रोगारम्भकदोषस्य प्रकोपादुपजायते योऽन्यो विकारः स बुधैरुपद्र व इहोदितः","text":"rogārambhakadoṣasya prakopādupajāyate yo'nyo vikāraḥ sa budhairupadra va ihoditaḥ"},{"type":"verse","number":"10","sanskrit":"रोगिणो मरणं यस्मादवश्यम्भावि लक्ष्यते तल्लक्षणमरिष्टं स्याद्रि ष्टं चापि तदुच्यते","text":"rogiṇo maraṇaṃ yasmādavaśyambhāvi lakṣyate tallakṣaṇamariṣṭaṃ syādri ṣṭaṃ cāpi taducyate"},{"type":"verse","number":"11","sanskrit":"या क्रिया व्याधिहरणी सा चिकित्सा निगद्यते दोषधातुमलानां या साम्यकृत्सैव रोगृहृत्","text":"yā kriyā vyādhiharaṇī sā cikitsā nigadyate doṣadhātumalānāṃ yā sāmyakṛtsaiva rogṛhṛt"},{"type":"verse","number":"12","sanskrit":"याभिः क्रियाभिर्जायन्ते शरीरे धातवः समाः सा चिकित्सा विकाराणां कर्म तद्भिषजां मतम्","text":"yābhiḥ kriyābhirjāyante śarīre dhātavaḥ samāḥ sā cikitsā vikārāṇāṃ karma tadbhiṣajāṃ matam"},{"type":"verse","number":"13","sanskrit":"या ह्युदीर्णं शमयति नान्यं व्याधिं करोति च सा क्रिया न तु या व्याधिं हरत्यन्यमुदीरयेत्","text":"yā hyudīrṇaṃ śamayati nānyaṃ vyādhiṃ karoti ca sā kriyā na tu yā vyādhiṃ haratyanyamudīrayet"},{"type":"verse","number":"14","sanskrit":"जातमात्रश्चिकित्स्यः स्यान्नोपेक्ष्योऽल्पतया गदः वह्निशत्रुविषैस्तुल्यः स्वल्पोऽपि विकरोत्यसौ","text":"jātamātraścikitsyaḥ syānnopekṣyo'lpatayā gadaḥ vahniśatruviṣaistulyaḥ svalpo'pi vikarotyasau"},{"type":"verse","number":"15","sanskrit":"रोगमादौ परीक्षेत ततोऽनन्तरमौषधम् ततः कर्म भिषक् पश्चाज्ज्ञानपूर्वं समाचरेत्","text":"rogamādau parīkṣeta tato'nantaramauṣadham tataḥ karma bhiṣak paścājjñānapūrvaṃ samācaret"},{"type":"verse","number":"16","sanskrit":"यस्तु रोगमविज्ञाय कर्माण्यारभते भिषक् अप्यौषधविधानज्ञस्तस्य सिद्धिर्यदृच्छया","text":"yastu rogamavijñāya karmāṇyārabhate bhiṣak apyauṣadhavidhānajñastasya siddhiryadṛcchayā"},{"type":"verse","number":"17","sanskrit":"भेषजं केवलं कर्तुं यो जानाति न चामयम् वैद्यकर्म स चेत्कुर्याद्वधमर्हति राजतः","text":"bheṣajaṃ kevalaṃ kartuṃ yo jānāti na cāmayam vaidyakarma sa cetkuryādvadhamarhati rājataḥ"},{"type":"verse","number":"18","sanskrit":"यस्तु केवलरोगज्ञो भेषजेष्वविचक्षणः तं वैद्यं प्राप्य रोगी स्याद्यथा नौर्नाविकं विना","text":"yastu kevalarogajño bheṣajeṣvavicakṣaṇaḥ taṃ vaidyaṃ prāpya rogī syādyathā naurnāvikaṃ vinā"},{"type":"verse","number":"19","sanskrit":"यस्तु केवलशास्त्रज्ञः क्रियास्वकुशलो भिषक् स मुह्यत्यातुरं प्राप्य तथा भीरुरिवाहवम्","text":"yastu kevalaśāstrajñaḥ kriyāsvakuśalo bhiṣak sa muhyatyāturaṃ prāpya tathā bhīrurivāhavam"},{"type":"verse","number":"20","sanskrit":"यस्तु रोगविशेषज्ञः सर्वभैषज्यकोविदः देश कालविभागज्ञस्तस्य सिद्धिर्न संशयः","text":"yastu rogaviśeṣajñaḥ sarvabhaiṣajyakovidaḥ deśa kālavibhāgajñastasya siddhirna saṃśayaḥ"},{"type":"verse","number":"21","sanskrit":"आदावन्ते रुजां ज्ञाने प्रयतेत चिकित्सकः भेषजानां विधानेन ततः कुर्याच्चिकित्सतम्","text":"ādāvante rujāṃ jñāne prayateta cikitsakaḥ bheṣajānāṃ vidhānena tataḥ kuryāccikitsatam"},{"type":"verse","number":"22","sanskrit":"विकारनामाकुशलो न जिह्रीयात्कदाचन न हि सर्वविकाराणां नामतोऽस्ति ध्रुवा स्थितिः","text":"vikāranāmākuśalo na jihrīyātkadācana na hi sarvavikārāṇāṃ nāmato'sti dhruvā sthitiḥ"},{"type":"verse","number":"23","sanskrit":"नास्ति रोगो विना दोषैर्यस्मात्तस्माच्चिकित्सकः अनुक्तमपि दोषाणां लिङ्गैर्व्याधिमुपाचरेत्","text":"nāsti rogo vinā doṣairyasmāttasmāccikitsakaḥ anuktamapi doṣāṇāṃ liṅgairvyādhimupācaret"},{"type":"verse","number":"24","sanskrit":"ये न कुर्वन्त्यसाध्यानां चिकित्सां ते भिषग्वराः अतो वैद्यैः श्रमः कार्यः साध्यासाध्यपरीक्षणे","text":"ye na kurvantyasādhyānāṃ cikitsāṃ te bhiṣagvarāḥ ato vaidyaiḥ śramaḥ kāryaḥ sādhyāsādhyaparīkṣaṇe"},{"type":"verse","number":"25","sanskrit":"शीते शीतप्रतीकारमुष्णे तूष्णनिवारणम् कृत्वा कुर्यात्क्रियां प्राप्तां क्रियाकालं न हापयेत्","text":"śīte śītapratīkāramuṣṇe tūṣṇanivāraṇam kṛtvā kuryātkriyāṃ prāptāṃ kriyākālaṃ na hāpayet"},{"type":"verse","number":"26","sanskrit":"अप्राप्ते वा क्रियाकाले प्राप्ते वा न क्रिया कृता क्रियाहीनाऽतिरिक्ता च साध्येष्वपि न सिध्यति","text":"aprāpte vā kriyākāle prāpte vā na kriyā kṛtā kriyāhīnā'tiriktā ca sādhyeṣvapi na sidhyati"},{"type":"verse","number":"27","sanskrit":"विकारेऽल्पे महत्कर्म क्रिया लघ्वी गरीयसि द्वयमेतदकौशल्यं कौशल्यं युक्तकर्मता","text":"vikāre'lpe mahatkarma kriyā laghvī garīyasi dvayametadakauśalyaṃ kauśalyaṃ yuktakarmatā"},{"type":"verse","number":"28","sanskrit":"क्रियायास्तु गुणालाभे क्रियामन्यां प्रयोजयेत् पूर्वस्यां शान्तवेगायां न क्रियासङ्करो हितः","text":"kriyāyāstu guṇālābhe kriyāmanyāṃ prayojayet pūrvasyāṃ śāntavegāyāṃ na kriyāsaṅkaro hitaḥ"},{"type":"verse","number":"29","sanskrit":"क्रियाभिस्तुल्यरूपाभिर्न क्रियासङ्करो हितः ताभिस्तु भिन्नरूपाभिः साङ्कर्यं नैव दुष्यति","text":"kriyābhistulyarūpābhirna kriyāsaṅkaro hitaḥ tābhistu bhinnarūpābhiḥ sāṅkaryaṃ naiva duṣyati"},{"type":"verse","number":"30","sanskrit":"न चैकान्तेन निर्दिष्टे शास्त्रे निविशते बुधः स्वयमप्यत्र भिषजा तर्कणीयं चिकित्सता","text":"na caikāntena nirdiṣṭe śāstre niviśate budhaḥ svayamapyatra bhiṣajā tarkaṇīyaṃ cikitsatā"},{"type":"verse","number":"31","sanskrit":"उत्पद्यते च साऽवस्था दोषकालबलं प्रति यस्यां कार्यमकार्यं स्यात्कर्म कार्यं विवर्जितम्","text":"utpadyate ca sā'vasthā doṣakālabalaṃ prati yasyāṃ kāryamakāryaṃ syātkarma kāryaṃ vivarjitam"},{"type":"verse","number":"32","sanskrit":"क्वचिदर्थः क्वचिन्मैत्री क्वचिद्धर्मः क्वचिद्यशः कर्माभ्यासः क्वचिच्चेति चिकित्सा नास्ति निष्फला","text":"kvacidarthaḥ kvacinmaitrī kvaciddharmaḥ kvacidyaśaḥ karmābhyāsaḥ kvacicceti cikitsā nāsti niṣphalā"},{"type":"verse","number":"33","sanskrit":"आयुर्वेदोदितां युक्तिं कुर्वाणाश्च हिताय ये पुण्यायुर्वृद्धिसंयुक्ता नीरोगाश्च भवन्ति ते","text":"āyurvedoditāṃ yuktiṃ kurvāṇāśca hitāya ye puṇyāyurvṛddhisaṃyuktā nīrogāśca bhavanti te"},{"type":"verse","number":"34","sanskrit":"नैव कुर्वीत लोभेन चिकित्सापुण्यविक्रयम् ईश्वराणां वसुमतां लिप्सेतार्थं तु वृत्तये","text":"naiva kurvīta lobhena cikitsāpuṇyavikrayam īśvarāṇāṃ vasumatāṃ lipsetārthaṃ tu vṛttaye"},{"type":"verse","number":"35","sanskrit":"चिकित्सितं शरीरं यो न निष्क्रीणाति दुर्मतिः स यत्करोति सुकृतं सर्वं तद्भिषगश्नुते","text":"cikitsitaṃ śarīraṃ yo na niṣkrīṇāti durmatiḥ sa yatkaroti sukṛtaṃ sarvaṃ tadbhiṣagaśnute"},{"type":"verse","number":"36","sanskrit":"न देशो मनुजैर्हीनो न मनुष्या निरामयाः ततः सर्वत्र वैद्यानां सुसिद्धा एव वृत्तयः","text":"na deśo manujairhīno na manuṣyā nirāmayāḥ tataḥ sarvatra vaidyānāṃ susiddhā eva vṛttayaḥ"},{"type":"verse","number":"37","sanskrit":"रोगी दूतो भिषग्दीर्घमायुर्द्र व्यं सुसेवकः सदौषधं चिकित्साया इत्यङ्गानि बुधा जगुः","text":"rogī dūto bhiṣagdīrghamāyurdra vyaṃ susevakaḥ sadauṣadhaṃ cikitsāyā ityaṅgāni budhā jaguḥ"},{"type":"verse","number":"38","sanskrit":"रोगो यस्यास्तिरोगी स सचिकित्स्यस्तु यादृशः यादृशश्चाचिकित्स्योऽपि वक्ष्यमाणो निशम्यताम्","text":"rogo yasyāstirogī sa sacikitsyastu yādṛśaḥ yādṛśaścācikitsyo'pi vakṣyamāṇo niśamyatām"},{"type":"verse","number":"39","sanskrit":"निजप्रकृतिवर्णाभ्यां युक्तः सत्त्वेन चक्षुषा चिकित्स्यो भिषजां रोगी वैद्यभक्तो जितेन्द्रि यः","text":"nijaprakṛtivarṇābhyāṃ yuktaḥ sattvena cakṣuṣā cikitsyo bhiṣajāṃ rogī vaidyabhakto jitendri yaḥ"},{"type":"verse","number":"40","sanskrit":"आयुष्मान्सत्त्ववान्साध्यो द्र व्यवान्मित्रवानपि चिकित्स्यो भिषजां रोगी वैद्यवाक्यकृदास्तिकः","text":"āyuṣmānsattvavānsādhyo dra vyavānmitravānapi cikitsyo bhiṣajāṃ rogī vaidyavākyakṛdāstikaḥ"},{"type":"verse","number":"41","sanskrit":"चण्डः साहसिको भीरुः कृतघ्नो व्यग्र एव च शोकाकुलो मुमूर्षुश्च विहीनः करणैश्चः यः","text":"caṇḍaḥ sāhasiko bhīruḥ kṛtaghno vyagra eva ca śokākulo mumūrṣuśca vihīnaḥ karaṇaiścaḥ yaḥ"},{"type":"verse","number":"42","sanskrit":"वैरी वैद्यविदग्धश्च श्रद्धाहीनश्च शङ्कितः भिषजामविधेयः स्युर्नोपक्रम्या भिषग्विधाः","text":"vairī vaidyavidagdhaśca śraddhāhīnaśca śaṅkitaḥ bhiṣajāmavidheyaḥ syurnopakramyā bhiṣagvidhāḥ"},{"type":"verse","number":"43","sanskrit":"एतानुपाचरन् वैद्यो वहून् दोषानवाप्नुयात्","text":"etānupācaran vaidyo vahūn doṣānavāpnuyāt"},{"type":"verse","number":"44","sanskrit":"यश्चिकित्सकमानेतुं याति दूतः स कथ्यते स च यादृक् समुचितस्तादृगत्र निगद्यते","text":"yaścikitsakamānetuṃ yāti dūtaḥ sa kathyate sa ca yādṛk samucitastādṛgatra nigadyate"},{"type":"verse","number":"45","sanskrit":"दूताः सुजातयोऽव्यङ्गाः पटवो निर्मलाम्बराः सुखिनोऽश्ववृषारूढाः शुभ्रपुष्पफलैर्युताः","text":"dūtāḥ sujātayo'vyaṅgāḥ paṭavo nirmalāmbarāḥ sukhino'śvavṛṣārūḍhāḥ śubhrapuṣpaphalairyutāḥ"},{"type":"verse","number":"46","sanskrit":"सजातयः सुचेष्टाश्च सजीवदिशि सङ्गताः भिषजं समये प्राप्ता रोगिणः सुखहेतवे","text":"sajātayaḥ suceṣṭāśca sajīvadiśi saṅgatāḥ bhiṣajaṃ samaye prāptā rogiṇaḥ sukhahetave"},{"type":"verse","number":"47","sanskrit":"वैद्याह्वानाय दूतस्य गच्छतो रोगिणः कृते न शुभं सौम्यशकुनं प्रदीप्तं तु सुखावहम्","text":"vaidyāhvānāya dūtasya gacchato rogiṇaḥ kṛte na śubhaṃ saumyaśakunaṃ pradīptaṃ tu sukhāvaham"},{"type":"verse","number":"48","sanskrit":"तथाहि रिक्तहस्तो न पश्येत्तुराजानं भिषजं गुरुम् दैवज्ञं देवतां मित्रं फलेन फलमादिशेत्","text":"tathāhi riktahasto na paśyetturājānaṃ bhiṣajaṃ gurum daivajñaṃ devatāṃ mitraṃ phalena phalamādiśet"},{"type":"verse","number":"49","sanskrit":"चिकित्सां कुरुते यस्तु स चिकित्सक उच्यते स च यादृक्समीचीनस्तादृशोऽपि निगद्यते","text":"cikitsāṃ kurute yastu sa cikitsaka ucyate sa ca yādṛksamīcīnastādṛśo'pi nigadyate"},{"type":"verse","number":"50","sanskrit":"तत्त्वाधिगतशास्त्रार्थो दृष्टकर्मा स्वयंकृती लघुहस्तः शुचिः शूरः सज्जोपस्करभेषजः","text":"tattvādhigataśāstrārtho dṛṣṭakarmā svayaṃkṛtī laghuhastaḥ śuciḥ śūraḥ sajjopaskarabheṣajaḥ"},{"type":"verse","number":"51","sanskrit":"प्रत्युत्पन्नमतिर्धीमान् व्यवसाथी प्रियंवदः सत्यधर्मपरो यश्च वैद्य ईदृक् प्रशस्यते","text":"pratyutpannamatirdhīmān vyavasāthī priyaṃvadaḥ satyadharmaparo yaśca vaidya īdṛk praśasyate"},{"type":"verse","number":"52","sanskrit":"कुचैलः कर्कशः स्तब्धो ग्रामीणः स्वयमागतः पञ्च वैद्या न पूज्यन्ते धन्वन्तरिसमा यदि","text":"kucailaḥ karkaśaḥ stabdho grāmīṇaḥ svayamāgataḥ pañca vaidyā na pūjyante dhanvantarisamā yadi"},{"type":"verse","number":"53","sanskrit":"व्याधेस्तत्त्वपरिज्ञानं वेदनायाश्च निग्रहः एतद्वैद्यस्य वैद्यत्वं न वैद्यः प्रभुरायुषः","text":"vyādhestattvaparijñānaṃ vedanāyāśca nigrahaḥ etadvaidyasya vaidyatvaṃ na vaidyaḥ prabhurāyuṣaḥ"},{"type":"verse","number":"54","sanskrit":"भिषगादौ परीक्षेत रुग्णस्यायुः प्रयत्नतः तत आयुषि विस्तीर्णे चिकित्सा सफला भवेत्","text":"bhiṣagādau parīkṣeta rugṇasyāyuḥ prayatnataḥ tata āyuṣi vistīrṇe cikitsā saphalā bhavet"},{"type":"verse","number":"55","sanskrit":"सौम्या दृष्टिर्भवेद्यस्य श्रोत्रं वक्त्रं तथैव च स्वादु गन्धं विजानाति स साध्यो नात्र संशयः","text":"saumyā dṛṣṭirbhavedyasya śrotraṃ vaktraṃ tathaiva ca svādu gandhaṃ vijānāti sa sādhyo nātra saṃśayaḥ"},{"type":"verse","number":"56","sanskrit":"पाणिपादौ च यस्योष्णौ दाहः स्वल्पतरो भवेत् जिह्वातु कोमला यस्य स रोगी न विनश्यति","text":"pāṇipādau ca yasyoṣṇau dāhaḥ svalpataro bhavet jihvātu komalā yasya sa rogī na vinaśyati"},{"type":"verse","number":"57","sanskrit":"स्वेदहीनो ज्वरो यस्य श्वासो नासिकया चरेत् कण्ठश्च कफहीनः स्यात्स रोगी जीवति ध्रुवम्","text":"svedahīno jvaro yasya śvāso nāsikayā caret kaṇṭhaśca kaphahīnaḥ syātsa rogī jīvati dhruvam"},{"type":"verse","number":"58","sanskrit":"यस्य निद्रा सुखेन स्याच्छरीरं द्युतिमद्भवेत् इन्द्रि याणि प्रसन्नानि स रोगी नैव नश्यति","text":"yasya nidrā sukhena syāccharīraṃ dyutimadbhavet indri yāṇi prasannāni sa rogī naiva naśyati"},{"type":"verse","number":"59","sanskrit":"शरीरशीलयोर्यस्य प्रकृतेर्विकृतिर्भवेत् तदरिष्टं समासेन व्यासतश्च निबोध मे","text":"śarīraśīlayoryasya prakṛtervikṛtirbhavet tadariṣṭaṃ samāsena vyāsataśca nibodha me"},{"type":"verse","number":"60","sanskrit":"शृणोति विविधाञ्छब्दान्विपरीताञ्छृणोति च यो न शृणोति चाकस्मात्तं वदन्ति गतायुषम्","text":"śṛṇoti vividhāñchabdānviparītāñchṛṇoti ca yo na śṛṇoti cākasmāttaṃ vadanti gatāyuṣam"},{"type":"verse","number":"61","sanskrit":"यस्तूष्णमिव गृह्णाति शीतमुष्णं च शीतवत् उष्णगात्रोऽतिमात्रं यो भृशं शीतेन कम्पते","text":"yastūṣṇamiva gṛhṇāti śītamuṣṇaṃ ca śītavat uṣṇagātro'timātraṃ yo bhṛśaṃ śītena kampate"},{"type":"verse","number":"62","sanskrit":"प्रहारं नैव जानाति योऽङ्गच्छेदमथापि वा पांशुनेवावकीर्णानि यश्च गात्राणि मन्यते","text":"prahāraṃ naiva jānāti yo'ṅgacchedamathāpi vā pāṃśunevāvakīrṇāni yaśca gātrāṇi manyate"},{"type":"verse","number":"63","sanskrit":"वर्णान्यता वा राज्यो वा यस्य गात्रे भवन्ति हि स्नातानुलिप्तं यं चापि भजन्ते नीलमाक्षिकाः","text":"varṇānyatā vā rājyo vā yasya gātre bhavanti hi snātānuliptaṃ yaṃ cāpi bhajante nīlamākṣikāḥ"},{"type":"verse","number":"64","sanskrit":"विपरीतेन गृह्णाति रसान्यश्चोपयोजितान् यो वा रसान्न संवेत्ति तं गतासुं प्रचक्षते","text":"viparītena gṛhṇāti rasānyaścopayojitān yo vā rasānna saṃvetti taṃ gatāsuṃ pracakṣate"},{"type":"verse","number":"65","sanskrit":"सुगन्धं वेत्ति दुर्गन्धं दुर्गन्धं च सुगन्धवत् गृह्णाति योऽन्यथा गन्धं शान्ते दीपे निरामयः","text":"sugandhaṃ vetti durgandhaṃ durgandhaṃ ca sugandhavat gṛhṇāti yo'nyathā gandhaṃ śānte dīpe nirāmayaḥ"},{"type":"verse","number":"66","sanskrit":"रात्रौ सूर्यं ज्वलन्तं वा दिवा वा चन्द्र वर्चसम् दिवा ज्योतींषि यश्चापि ज्वलितानीव पश्यति","text":"rātrau sūryaṃ jvalantaṃ vā divā vā candra varcasam divā jyotīṃṣi yaścāpi jvalitānīva paśyati"},{"type":"verse","number":"67","sanskrit":"विद्युत्वतोऽसितान्मेघान् गगने निर्घने घनान् विमानयानप्रासादैर्यश्च सङ्कुलमम्बरम्","text":"vidyutvato'sitānmeghān gagane nirghane ghanān vimānayānaprāsādairyaśca saṅkulamambaram"},{"type":"verse","number":"68","sanskrit":"यश्चानिलं मूर्त्तिमन्तमन्तरिक्षेऽवलोकते धूमनीहारवासोभिरावृतामिव मेदिनीम्","text":"yaścānilaṃ mūrttimantamantarikṣe'valokate dhūmanīhāravāsobhirāvṛtāmiva medinīm"},{"type":"verse","number":"69","sanskrit":"प्रदीप्तमिव यो लोकं यो वाप्लुतमिवाम्भसा भूमिमष्टापदाकारां लेखाभिर्यश्च पश्यति","text":"pradīptamiva yo lokaṃ yo vāplutamivāmbhasā bhūmimaṣṭāpadākārāṃ lekhābhiryaśca paśyati"},{"type":"verse","number":"70","sanskrit":"यो न पश्यति ॠक्षाणि यश्च देवीमरुन्धतीम् ध्रुवमाकाशगङ्गां च तं वदन्ति गतायुषम्","text":"yo na paśyati ṝkṣāṇi yaśca devīmarundhatīm dhruvamākāśagaṅgāṃ ca taṃ vadanti gatāyuṣam"},{"type":"verse","number":"71","sanskrit":"आदर्शेऽम्बुनि घर्मे वा छायां यश्च न पश्यति पश्यत्येकाङ्गहीनां वा विकृतां वाऽन्यसत्वजाम्","text":"ādarśe'mbuni gharme vā chāyāṃ yaśca na paśyati paśyatyekāṅgahīnāṃ vā vikṛtāṃ vā'nyasatvajām"},{"type":"verse","number":"72","sanskrit":"श्वकाककङ्कगृध्राणां प्रेतानां यक्षरक्षसाम् आतुरो लभते मृत्युं स्वस्थो व्याधिमवाप्नुयात्","text":"śvakākakaṅkagṛdhrāṇāṃ pretānāṃ yakṣarakṣasām āturo labhate mṛtyuṃ svastho vyādhimavāpnuyāt"},{"type":"verse","number":"73","sanskrit":"ह्रीश्रियौ नश्यतो यस्य तेज ओजः स्मृतिः प्रभा अकस्माच्च भजन्ते यं स गतासुरसंशयम्","text":"hrīśriyau naśyato yasya teja ojaḥ smṛtiḥ prabhā akasmācca bhajante yaṃ sa gatāsurasaṃśayam"},{"type":"verse","number":"74","sanskrit":"यस्याधरौष्ठः पतितः क्षिप्तश्चोर्ध्वं तथोत्तरः उभौ वा जाम्बवाभासौ दुर्लभं तस्य जीवितम्","text":"yasyādharauṣṭhaḥ patitaḥ kṣiptaścordhvaṃ tathottaraḥ ubhau vā jāmbavābhāsau durlabhaṃ tasya jīvitam"},{"type":"verse","number":"75","sanskrit":"आरक्ता दशना यस्य श्यावा वा स्युः पतन्ति वा खञ्जनप्रतिभा वापि तं गतायुषमादिशेत्","text":"āraktā daśanā yasya śyāvā vā syuḥ patanti vā khañjanapratibhā vāpi taṃ gatāyuṣamādiśet"},{"type":"verse","number":"76","sanskrit":"कृष्णा तथाऽनुलिप्ता च जिह्वा शून्या च यस्य वै कर्कशा वा भवेद्यस्य सोऽचिराद्विजहात्यसून्","text":"kṛṣṇā tathā'nuliptā ca jihvā śūnyā ca yasya vai karkaśā vā bhavedyasya so'cirādvijahātyasūn"},{"type":"verse","number":"77","sanskrit":"कुटिला स्फुटिता वाऽपि शुष्का वा यस्य नासिका अवस्फूर्जति भग्ना वा स न जीवति मानवः","text":"kuṭilā sphuṭitā vā'pi śuṣkā vā yasya nāsikā avasphūrjati bhagnā vā sa na jīvati mānavaḥ"},{"type":"verse","number":"78","sanskrit":"संक्षिप्ते विषमे स्तब्धे रूक्षे सास्रे च लोचने स्यातां परिश्रुते यस्य स गतायुर्नरो ध्रुवम्","text":"saṃkṣipte viṣame stabdhe rūkṣe sāsre ca locane syātāṃ pariśrute yasya sa gatāyurnaro dhruvam"},{"type":"verse","number":"79","sanskrit":"केशा सीमन्तिनो यस्य संक्षिप्ते विनते भ्रुवौ लुठन्ति चाक्षिपक्ष्माणि सोऽचिराद्याति मृत्यवे","text":"keśā sīmantino yasya saṃkṣipte vinate bhruvau luṭhanti cākṣipakṣmāṇi so'cirādyāti mṛtyave"},{"type":"verse","number":"80","sanskrit":"नाहरत्यन्नमास्यस्थं न धारयति यः शिरः एकाग्रदृष्टिर्मूढात्मा सद्यः प्राणान्विमुञ्चति","text":"nāharatyannamāsyasthaṃ na dhārayati yaḥ śiraḥ ekāgradṛṣṭirmūḍhātmā sadyaḥ prāṇānvimuñcati"},{"type":"verse","number":"81","sanskrit":"उत्थाप्यमानो बहुशः संमोहं योऽधिगच्छति बलवान्दुर्बलो वापि तं पक्वं भिषगादिशेत्","text":"utthāpyamāno bahuśaḥ saṃmohaṃ yo'dhigacchati balavāndurbalo vāpi taṃ pakvaṃ bhiṣagādiśet"},{"type":"verse","number":"82","sanskrit":"निद्रा निरन्तरं यस्य यो जागर्त्ति च सर्वदा मुह्येद्वा वक्तुकामश्च प्रत्याख्येयः स जानता","text":"nidrā nirantaraṃ yasya yo jāgartti ca sarvadā muhyedvā vaktukāmaśca pratyākhyeyaḥ sa jānatā"},{"type":"verse","number":"83","sanskrit":"उत्तरौष्ठं च यो लिह्यादुत्करांश्च करोतिः यः प्रेतैर्वा भाषते सायं प्रेतरूपं तमादिशेत्","text":"uttarauṣṭhaṃ ca yo lihyādutkarāṃśca karotiḥ yaḥ pretairvā bhāṣate sāyaṃ pretarūpaṃ tamādiśet"},{"type":"verse","number":"84","sanskrit":"खेभ्यश्च रोमकूपेभ्यो यस्य रक्तं प्रवर्तते पुरुषस्याविषार्तस्य स सद्यो जीवितं त्यजेत्","text":"khebhyaśca romakūpebhyo yasya raktaṃ pravartate puruṣasyāviṣārtasya sa sadyo jīvitaṃ tyajet"},{"type":"verse","number":"85","sanskrit":"सम्यक् चिकित्स्यमानस्य विकारो योऽभिवर्धते प्रक्षीणबलमांसस्य लक्षणं तद्गतायुषः","text":"samyak cikitsyamānasya vikāro yo'bhivardhate prakṣīṇabalamāṃsasya lakṣaṇaṃ tadgatāyuṣaḥ"},{"type":"verse","number":"86","sanskrit":"भूताः प्रेताः पिशाचाश्च रक्षांसि विविधानि च मरणाभिमुखं जन्तुमुपसृत्य च नित्यशः","text":"bhūtāḥ pretāḥ piśācāśca rakṣāṃsi vividhāni ca maraṇābhimukhaṃ jantumupasṛtya ca nityaśaḥ"},{"type":"verse","number":"87","sanskrit":"तानि भेषजवीर्याणि प्रतिघ्नन्ति जिघांसया तस्मान्मोघाः क्रियाः सर्वा भवन्त्येव गतायुषः","text":"tāni bheṣajavīryāṇi pratighnanti jighāṃsayā tasmānmoghāḥ kriyāḥ sarvā bhavantyeva gatāyuṣaḥ"},{"type":"verse","number":"88","sanskrit":"सर्वे द्र व्यमपेक्षन्ते रोगिप्रभृतयो यतः विना वित्तं न भैषज्यं चिकित्साऽङ्ग ततो धनम्","text":"sarve dra vyamapekṣante rogiprabhṛtayo yataḥ vinā vittaṃ na bhaiṣajyaṃ cikitsā'ṅga tato dhanam"},{"type":"verse","number":"89","sanskrit":"स्निग्धोऽजुगुप्सुर्बलवान्युक्तो व्याधितरक्षणे वैद्यवाक्यकृदश्रान्तो युज्यते परिचारकः","text":"snigdho'jugupsurbalavānyukto vyādhitarakṣaṇe vaidyavākyakṛdaśrānto yujyate paricārakaḥ"},{"type":"verse","number":"90","sanskrit":"वैद्यो व्याधिं हरेद्येन तद्द्र व्यं प्रोक्तमौषधम् तद्यादृशमवश्यं स्याद्रो गघ्नं तादृशं ब्रुवे","text":"vaidyo vyādhiṃ haredyena taddra vyaṃ proktamauṣadham tadyādṛśamavaśyaṃ syādro gaghnaṃ tādṛśaṃ bruve"},{"type":"verse","number":"91","sanskrit":"प्रशस्तदेशे सञ्जातं प्रशस्तेऽहनि चोद्धृतम् अल्पमात्रं बहुगुणं गन्धवर्णरसान्वितम्","text":"praśastadeśe sañjātaṃ praśaste'hani coddhṛtam alpamātraṃ bahuguṇaṃ gandhavarṇarasānvitam"},{"type":"verse","number":"92","sanskrit":"दोषघ्नमग्लानिकरमधिकं न विकारि यत् समीक्ष्य काले दत्तं च भेषजं स्याद् गुणावहम्","text":"doṣaghnamaglānikaramadhikaṃ na vikāri yat samīkṣya kāle dattaṃ ca bheṣajaṃ syād guṇāvaham"},{"type":"verse","number":"93","sanskrit":"आग्नेया विन्ध्यशैलाद्या सौम्यो हिमगिरिः स्मृतः अतस्तदौषधानि स्युरनुरूपाणि हेतुभिः","text":"āgneyā vindhyaśailādyā saumyo himagiriḥ smṛtaḥ atastadauṣadhāni syuranurūpāṇi hetubhiḥ"},{"type":"verse","number":"94","sanskrit":"अन्येष्वपि प्ररोहन्ति वनेषूपवनेषु च गृह्णीयात्तानि सुमनाः शुचिः प्रातः सुवासरे","text":"anyeṣvapi prarohanti vaneṣūpavaneṣu ca gṛhṇīyāttāni sumanāḥ śuciḥ prātaḥ suvāsare"},{"type":"verse","number":"95","sanskrit":"आदित्यसम्मुखो मौनी नमस्कृत्य शिवं हृदि साधारणधराद्र व्यं गृह्णीयादुत्तराश्रितम्","text":"ādityasammukho maunī namaskṛtya śivaṃ hṛdi sādhāraṇadharādra vyaṃ gṛhṇīyāduttarāśritam"},{"type":"verse","number":"96","sanskrit":"वल्मीककुत्सितानूपश्मशानोषरमार्गजाः जन्तुवह्निहिमव्याप्ता नौषध्यः कार्यसाधिकाः","text":"valmīkakutsitānūpaśmaśānoṣaramārgajāḥ jantuvahnihimavyāptā nauṣadhyaḥ kāryasādhikāḥ"},{"type":"verse","number":"97","sanskrit":"शरद्यखिलकार्यार्थं ग्राह्यंसरसमौषधम् विरेकवमनार्थं तु वसन्तान्ते समाहरेत्","text":"śaradyakhilakāryārthaṃ grāhyaṃsarasamauṣadham virekavamanārthaṃ tu vasantānte samāharet"},{"type":"verse","number":"98","sanskrit":"अतिस्थूलजटा याः स्युस्तासां ग्राह्यास्त्वचो ध्रुवम् गृह्णीयात्सूक्ष्ममूलानि सकलान्यपि बुद्धिमान्","text":"atisthūlajaṭā yāḥ syustāsāṃ grāhyāstvaco dhruvam gṛhṇīyātsūkṣmamūlāni sakalānyapi buddhimān"},{"type":"verse","number":"99","sanskrit":"महान्ति येषां मूलानि काष्ठगर्भाणि सर्वतः तेषां तु वल्कलं ग्राह्यं ह्रस्वमूलानि सर्वशः","text":"mahānti yeṣāṃ mūlāni kāṣṭhagarbhāṇi sarvataḥ teṣāṃ tu valkalaṃ grāhyaṃ hrasvamūlāni sarvaśaḥ"},{"type":"verse","number":"100","sanskrit":"न्यग्रोधादेस्त्वचो ग्राह्या सारःस्याद्वीजकादितः तालीसादेश्च पत्राणि फलं स्यात् त्रिफलादितः","text":"nyagrodhādestvaco grāhyā sāraḥsyādvījakāditaḥ tālīsādeśca patrāṇi phalaṃ syāt triphalāditaḥ"},{"type":"verse","number":"101","sanskrit":"क्वचिन्मूलं क्वचित्कन्दः क्वचित्पत्रं क्वचित्फलम् क्वचित्पुष्पं क्वचित्सर्वं क्वचित्सारः क्वचित्त्वचः","text":"kvacinmūlaṃ kvacitkandaḥ kvacitpatraṃ kvacitphalam kvacitpuṣpaṃ kvacitsarvaṃ kvacitsāraḥ kvacittvacaḥ"},{"type":"verse","number":"102","sanskrit":"चित्रकं सूरणं निम्बो वासा च त्रिफला क्रमात् धातकी कण्टकारी च खदिरः क्षीरपादपः","text":"citrakaṃ sūraṇaṃ nimbo vāsā ca triphalā kramāt dhātakī kaṇṭakārī ca khadiraḥ kṣīrapādapaḥ"},{"type":"verse","number":"103","sanskrit":"क्वचिन्निम्बस्य गृह्णीयात्पत्राभावे त्वचामपि बालं फलं तु बिल्वस्य पक्वमारग्वधस्य च","text":"kvacinnimbasya gṛhṇīyātpatrābhāve tvacāmapi bālaṃ phalaṃ tu bilvasya pakvamāragvadhasya ca"},{"type":"verse","number":"104","sanskrit":"अङ्गेऽनुक्ते जटा ग्राह्या भागेऽनुक्तेऽखिलं समम् पात्रेऽनुक्ते मृदः पात्रं कालेऽनुक्ते त्वहर्मुखम्","text":"aṅge'nukte jaṭā grāhyā bhāge'nukte'khilaṃ samam pātre'nukte mṛdaḥ pātraṃ kāle'nukte tvaharmukham"},{"type":"verse","number":"105","sanskrit":"नवान्येव हि योज्यानि द्र व्याण्यखिलकर्मसु विना विडङ्गकृष्णाभ्यां गुडधान्याज्यमाक्षिकैः","text":"navānyeva hi yojyāni dra vyāṇyakhilakarmasu vinā viḍaṅgakṛṣṇābhyāṃ guḍadhānyājyamākṣikaiḥ"},{"type":"verse","number":"106","sanskrit":"पुराणन्तु प्रशस्तं स्यात्ताम्बूलं काञ्जिकं तथा शुष्कं नवीनद्र व्यं तु योज्यं सकलकर्मसु","text":"purāṇantu praśastaṃ syāttāmbūlaṃ kāñjikaṃ tathā śuṣkaṃ navīnadra vyaṃ tu yojyaṃ sakalakarmasu"},{"type":"verse","number":"107","sanskrit":"आर्द्रान्तु द्विगुणं युञ्ज्यादेष सर्वत्र निश्चयः गुडूची कुटजो वासा कूष्माण्डश्च शतावरी","text":"ārdrāntu dviguṇaṃ yuñjyādeṣa sarvatra niścayaḥ guḍūcī kuṭajo vāsā kūṣmāṇḍaśca śatāvarī"},{"type":"verse","number":"108","sanskrit":"अश्वगन्धा सहचरः शतपुष्पा प्रसारिणी प्रयोक्तव्याः सदैवार्द्राद्विगुणं नैव कारयेत्","text":"aśvagandhā sahacaraḥ śatapuṣpā prasāriṇī prayoktavyāḥ sadaivārdrādviguṇaṃ naiva kārayet"},{"type":"verse","number":"109","sanskrit":"वासानिम्बपटोलकेतकबलाकूष्माण्डकेन्दीवरी वर्षाभूकुटजाश्च कन्दसहिता सा पूतिगन्धाऽमृता एन्द्री नागबला कुरुण्टकपुरच्छत्राऽमृताः सर्वदा सार्द्रा एव तु न क्वचिद् द्विगुणिताः कार्येषु योज्या बुधैः","text":"vāsānimbapaṭolaketakabalākūṣmāṇḍakendīvarī varṣābhūkuṭajāśca kandasahitā sā pūtigandhā'mṛtā endrī nāgabalā kuruṇṭakapuracchatrā'mṛtāḥ sarvadā sārdrā eva tu na kvacid dviguṇitāḥ kāryeṣu yojyā budhaiḥ"},{"type":"verse","number":"110","sanskrit":"घृतं तैलं च पानीयं कषायं व्यञ्जनादिकम् पक्त्वा शीतीकृतं चोष्णं तत्सर्वं स्याद्विषोपमम्","text":"ghṛtaṃ tailaṃ ca pānīyaṃ kaṣāyaṃ vyañjanādikam paktvā śītīkṛtaṃ coṣṇaṃ tatsarvaṃ syādviṣopamam"},{"type":"verse","number":"111","sanskrit":"सूक्ष्मास्थिमांसला पथ्या सर्वकर्मणि पूजिता क्षिप्ताऽम्भसि निमज्जेद्याः भल्लातक्यस्तथोत्तमाः","text":"sūkṣmāsthimāṃsalā pathyā sarvakarmaṇi pūjitā kṣiptā'mbhasi nimajjedyāḥ bhallātakyastathottamāḥ"},{"type":"verse","number":"112","sanskrit":"वराहमूर्द्धवत्कन्दो वाराहीकन्दसंज्ञकः सौवर्चलं तु काचाभं सैन्धवं स्फटिकप्रभम्","text":"varāhamūrddhavatkando vārāhīkandasaṃjñakaḥ sauvarcalaṃ tu kācābhaṃ saindhavaṃ sphaṭikaprabham"},{"type":"verse","number":"113","sanskrit":"सुवर्णच्छविकं ज्ञेयं स्वर्णमाक्षिकमुत्तमम् ओड्रपुष्पप्रतीकाशा मनोह्वा चोत्तमा मता","text":"suvarṇacchavikaṃ jñeyaṃ svarṇamākṣikamuttamam oḍrapuṣpapratīkāśā manohvā cottamā matā"},{"type":"verse","number":"114","sanskrit":"श्रेष्ठं शिलाजतु ज्ञेयं प्रक्षिप्तं न विशीर्यते तोयपूर्णे कांस्यपात्रे प्रतानेन विवर्धते","text":"śreṣṭhaṃ śilājatu jñeyaṃ prakṣiptaṃ na viśīryate toyapūrṇe kāṃsyapātre pratānena vivardhate"},{"type":"verse","number":"115","sanskrit":"कर्पूरस्तुवरः स्निग्धः एला सूक्ष्फला वरा श्वेतचन्दनमत्यन्तं सुगन्धि गुरुपूजितम्","text":"karpūrastuvaraḥ snigdhaḥ elā sūkṣphalā varā śvetacandanamatyantaṃ sugandhi gurupūjitam"},{"type":"verse","number":"116","sanskrit":"रक्तचन्दनमत्यन्तं लोहितं प्रवरं मतम् काकतुण्डनिभः स्निग्धो गुरुः श्रेष्ठो गुरुर्मतः","text":"raktacandanamatyantaṃ lohitaṃ pravaraṃ matam kākatuṇḍanibhaḥ snigdho guruḥ śreṣṭho gururmataḥ"},{"type":"verse","number":"117","sanskrit":"सुगन्धि लघु रूक्षं च सुरदारु वरं मतम् सरलं स्निग्धमत्यर्थं सुगन्धि च गुणावहम्","text":"sugandhi laghu rūkṣaṃ ca suradāru varaṃ matam saralaṃ snigdhamatyarthaṃ sugandhi ca guṇāvaham"},{"type":"verse","number":"118","sanskrit":"अतिपीता प्रशस्ता तु ज्ञेया दारुनिशा बुधैः जातीफलं गुरु स्निग्धं समं शुभ्रान्तरं वरम्","text":"atipītā praśastā tu jñeyā dāruniśā budhaiḥ jātīphalaṃ guru snigdhaṃ samaṃ śubhrāntaraṃ varam"},{"type":"verse","number":"119","sanskrit":"मृद्वीका सोत्तमा ज्ञेया या स्याद्गोस्तनसन्निभा करमर्दफलाकारा मध्यमा सा प्रकीर्त्तिता","text":"mṛdvīkā sottamā jñeyā yā syādgostanasannibhā karamardaphalākārā madhyamā sā prakīrttitā"},{"type":"verse","number":"120","sanskrit":"खण्डं तु विमलं श्रेष्ठं चन्द्र कान्तसमप्रभम् गव्याज्यसदृशं रुच्यं गन्धं मधु वरं मतम्","text":"khaṇḍaṃ tu vimalaṃ śreṣṭhaṃ candra kāntasamaprabham gavyājyasadṛśaṃ rucyaṃ gandhaṃ madhu varaṃ matam"},{"type":"verse","number":"121","sanskrit":"शालीनां लोहितः शालि षष्टिकेषु च षष्टिकः शूकधान्येष्वपि यवो गोधूमः प्रवरो मतः","text":"śālīnāṃ lohitaḥ śāli ṣaṣṭikeṣu ca ṣaṣṭikaḥ śūkadhānyeṣvapi yavo godhūmaḥ pravaro mataḥ"},{"type":"verse","number":"122","sanskrit":"शिम्बीधान्ये वरो मुद्गो मसूरश्चाढकी तथा रसेषु मधुरः श्रेष्ठो लवणेषु च सैन्धवः","text":"śimbīdhānye varo mudgo masūraścāḍhakī tathā raseṣu madhuraḥ śreṣṭho lavaṇeṣu ca saindhavaḥ"},{"type":"verse","number":"123","sanskrit":"दाडिमामलकं द्रा क्षा खर्जूरं च परूषकम् राजादनं मातुलुंगं फलवर्गेषु शस्यते","text":"dāḍimāmalakaṃ drā kṣā kharjūraṃ ca parūṣakam rājādanaṃ mātuluṃgaṃ phalavargeṣu śasyate"},{"type":"verse","number":"124","sanskrit":"पत्रशाकेषु वास्तूकं जीवन्ती पोतिका वरा पटोलं फलशाकेषु कन्दशाकेषु सूरणम्","text":"patraśākeṣu vāstūkaṃ jīvantī potikā varā paṭolaṃ phalaśākeṣu kandaśākeṣu sūraṇam"},{"type":"verse","number":"125","sanskrit":"एणः कुरङ्गो हरिणो जाङ्गलेषु प्रशस्यते पक्षिणां तित्तिरिर्लावो वरो मत्स्येषु रोहितः","text":"eṇaḥ kuraṅgo hariṇo jāṅgaleṣu praśasyate pakṣiṇāṃ tittirirlāvo varo matsyeṣu rohitaḥ"},{"type":"verse","number":"126","sanskrit":"हरिणस्ताम्रवर्णः स्यादेणः कृष्णतया मतः कुरङ्गस्ताम्र उद्दिष्टो हरिणाकृतिको महान्","text":"hariṇastāmravarṇaḥ syādeṇaḥ kṛṣṇatayā mataḥ kuraṅgastāmra uddiṣṭo hariṇākṛtiko mahān"},{"type":"verse","number":"127","sanskrit":"जलेषु दिव्यं दुग्धेषु गव्यमाज्येषु गोभवम् तैलेषु तिलजं तैलमैक्षवेषु सिता हिता","text":"jaleṣu divyaṃ dugdheṣu gavyamājyeṣu gobhavam taileṣu tilajaṃ tailamaikṣaveṣu sitā hitā"},{"type":"verse","number":"128","sanskrit":"शिम्वीषु माषान्ग्रीष्मर्तौ लवणेष्वौषरं त्यजेत् फलेषु लकुचं शाके सार्षपं न हितं मतम्","text":"śimvīṣu māṣāngrīṣmartau lavaṇeṣvauṣaraṃ tyajet phaleṣu lakucaṃ śāke sārṣapaṃ na hitaṃ matam"},{"type":"verse","number":"129","sanskrit":"गोमांसं ग्राम्यमांसेषु न हितं महिषीवसा मेषीपयः कुसुम्भस्य तैलं त्याज्यं च फाणितम्","text":"gomāṃsaṃ grāmyamāṃseṣu na hitaṃ mahiṣīvasā meṣīpayaḥ kusumbhasya tailaṃ tyājyaṃ ca phāṇitam"},{"type":"verse","number":"130","sanskrit":"मत्स्यमानूपमांसं च दुग्धयुक्तं विवर्जयेत् कपोतं सर्षपस्नेहभर्जितं परिवर्जयेत्","text":"matsyamānūpamāṃsaṃ ca dugdhayuktaṃ vivarjayet kapotaṃ sarṣapasnehabharjitaṃ parivarjayet"},{"type":"verse","number":"131","sanskrit":"मत्स्यानिक्षोर्विकारेण तथा क्षौद्रे ण वर्जयेत् सक्तून्मांसपयोयुक्तानुष्णैर्दधि विवर्जयेत्","text":"matsyānikṣorvikāreṇa tathā kṣaudre ṇa varjayet saktūnmāṃsapayoyuktānuṣṇairdadhi vivarjayet"},{"type":"verse","number":"132","sanskrit":"उष्णैर्नभोऽम्बुना क्षौद्रं पायसं कृसरान्वितम् रम्भाफलं त्यजेत्तक्रदधिबिल्वफलान्वितम्","text":"uṣṇairnabho'mbunā kṣaudraṃ pāyasaṃ kṛsarānvitam rambhāphalaṃ tyajettakradadhibilvaphalānvitam"},{"type":"verse","number":"133","sanskrit":"दशाहमुषितं सर्पिः कांस्ये मधुघृतं समम् कृतान्नं च कषायं च पुनरुष्णीकृतं त्यजेत्","text":"daśāhamuṣitaṃ sarpiḥ kāṃsye madhughṛtaṃ samam kṛtānnaṃ ca kaṣāyaṃ ca punaruṣṇīkṛtaṃ tyajet"},{"type":"verse","number":"134","sanskrit":"एकत्र बहुमांसानि विरुध्यन्ते परस्परम् मधु सर्पिर्वसा तैलं पानीयं वा पयस्तथा","text":"ekatra bahumāṃsāni virudhyante parasparam madhu sarpirvasā tailaṃ pānīyaṃ vā payastathā"},{"type":"verse","number":"135","sanskrit":"लवणं सैन्धवं प्रोक्तंचन्दनं रक्तचन्दनम् चूर्णलेहासवस्नेहाः साध्या धवलचन्दनैः कषायलेपयोः प्रायो युज्यते रक्तचन्दनम्","text":"lavaṇaṃ saindhavaṃ proktaṃcandanaṃ raktacandanam cūrṇalehāsavasnehāḥ sādhyā dhavalacandanaiḥ kaṣāyalepayoḥ prāyo yujyate raktacandanam"},{"type":"verse","number":"136","sanskrit":"अन्तः सम्मार्जने ज्ञेया ह्यजमोदा यवानिका बहिः सम्मार्जने सैव विज्ञातव्याऽजमोदिका","text":"antaḥ sammārjane jñeyā hyajamodā yavānikā bahiḥ sammārjane saiva vijñātavyā'jamodikā"},{"type":"verse","number":"137","sanskrit":"पयः सर्पिः प्रयोगेषु गव्यमेव हि गृह्यते शकृद्र सो गोमयको मूत्रं गोमूत्रमुच्यते","text":"payaḥ sarpiḥ prayogeṣu gavyameva hi gṛhyate śakṛdra so gomayako mūtraṃ gomūtramucyate"},{"type":"verse","number":"138","sanskrit":"चित्रकाभावतोदन्ती क्षारः शिखरिजोऽथवा अभावे धन्वयासस्य प्रेक्षेप्यातु दुरालभा","text":"citrakābhāvatodantī kṣāraḥ śikharijo'thavā abhāve dhanvayāsasya prekṣepyātu durālabhā"},{"type":"verse","number":"139","sanskrit":"तगरस्याप्यभावे तु कुष्ठं दद्याद्भिषग्वरः मूर्वाऽभावे त्वचो ग्राह्या जिङ्गिनीप्रभवा बुधैः","text":"tagarasyāpyabhāve tu kuṣṭhaṃ dadyādbhiṣagvaraḥ mūrvā'bhāve tvaco grāhyā jiṅginīprabhavā budhaiḥ"},{"type":"verse","number":"140","sanskrit":"अहिंस्रया अभावे तु मानकन्दः प्रकीर्त्तितः लक्ष्मणाया अभावे तु नीलकण्ठशिखा मता","text":"ahiṃsrayā abhāve tu mānakandaḥ prakīrttitaḥ lakṣmaṇāyā abhāve tu nīlakaṇṭhaśikhā matā"},{"type":"verse","number":"141","sanskrit":"वकुलाभावतो देयं कह्लारोत्पलपङ्कजम् नीलोत्पलस्याभावे तु कुमुदं देयमिष्यते","text":"vakulābhāvato deyaṃ kahlārotpalapaṅkajam nīlotpalasyābhāve tu kumudaṃ deyamiṣyate"},{"type":"verse","number":"142","sanskrit":"जातीपुष्पं न यत्रास्ति लवंगं तत्र दीयते अर्कपर्णादिपयसो ह्यभावे तद्र सो मतः","text":"jātīpuṣpaṃ na yatrāsti lavaṃgaṃ tatra dīyate arkaparṇādipayaso hyabhāve tadra so mataḥ"},{"type":"verse","number":"143","sanskrit":"पौष्करा भावतः कुष्ठं तथा लाङ्गल्यभावतः स्थौणेयकस्याभावे तु मिषग्भिर्दीयते गदः","text":"pauṣkarā bhāvataḥ kuṣṭhaṃ tathā lāṅgalyabhāvataḥ sthauṇeyakasyābhāve tu miṣagbhirdīyate gadaḥ"},{"type":"verse","number":"144","sanskrit":"चविकागजपिप्पल्यौ पिप्लीमूलवत्स्मृतौ","text":"cavikāgajapippalyau piplīmūlavatsmṛtau"},{"type":"verse","number":"145","sanskrit":"अभावे सोमराज्यास्तु प्रपुन्नाडफलं मतम् यदि न स्याद्दारुनिशा तदा देया निशा बुधैः","text":"abhāve somarājyāstu prapunnāḍaphalaṃ matam yadi na syāddāruniśā tadā deyā niśā budhaiḥ"},{"type":"verse","number":"146","sanskrit":"रसाञ्जनस्याभावे तु दार्वीक्वाथः प्रयुज्यते सौराष्ट्र्यभावतो देया स्फटिका तद्गुणा जनैः","text":"rasāñjanasyābhāve tu dārvīkvāthaḥ prayujyate saurāṣṭryabhāvato deyā sphaṭikā tadguṇā janaiḥ"},{"type":"verse","number":"147","sanskrit":"तालीसपत्रकाभावे स्वर्णताली प्रशस्यते भार्ङ्ग्यभावे तु तालीसं कण्टकारीजटाऽथवा","text":"tālīsapatrakābhāve svarṇatālī praśasyate bhārṅgyabhāve tu tālīsaṃ kaṇṭakārījaṭā'thavā"},{"type":"verse","number":"148","sanskrit":"रुचकाभावतो दद्याल्लवणं पांशुपूर्वकम् अभावे मधुयष्ट्यास्तु धातकीं च प्रयोजयेत्","text":"rucakābhāvato dadyāllavaṇaṃ pāṃśupūrvakam abhāve madhuyaṣṭyāstu dhātakīṃ ca prayojayet"},{"type":"verse","number":"149","sanskrit":"अम्लवेतसकाभावे चुक्रं दातव्यमिष्यते द्रा क्षा यदि न लभ्येत प्रदेयं काश्मरीफलम्","text":"amlavetasakābhāve cukraṃ dātavyamiṣyate drā kṣā yadi na labhyeta pradeyaṃ kāśmarīphalam"},{"type":"verse","number":"150","sanskrit":"तयोरभावे कुसुमं मधूकस्य मतं बुधैः लवङ्गकुसुमं देयं नखस्याभावतः पुनः","text":"tayorabhāve kusumaṃ madhūkasya mataṃ budhaiḥ lavaṅgakusumaṃ deyaṃ nakhasyābhāvataḥ punaḥ"},{"type":"verse","number":"151","sanskrit":"कस्तूर्यभावे कङ्कोलं क्षेपणीयं विदुर्बुधाः कङ्कोलस्याप्यभावे तु जातीपुष्पं प्रदीयते","text":"kastūryabhāve kaṅkolaṃ kṣepaṇīyaṃ vidurbudhāḥ kaṅkolasyāpyabhāve tu jātīpuṣpaṃ pradīyate"},{"type":"verse","number":"152","sanskrit":"सुगन्धिमुस्तकं देयं कर्पूराभावतो बुधैः कर्पूराभावतो देयं ग्रन्थिपर्णं विशेषतः","text":"sugandhimustakaṃ deyaṃ karpūrābhāvato budhaiḥ karpūrābhāvato deyaṃ granthiparṇaṃ viśeṣataḥ"},{"type":"verse","number":"153","sanskrit":"कुङ्कुमाभावतो दद्यात्कुसुम्भकुसुमं नवम् श्रीखण्डचन्दनाभावे कर्पूरं देयमिष्यते","text":"kuṅkumābhāvato dadyātkusumbhakusumaṃ navam śrīkhaṇḍacandanābhāve karpūraṃ deyamiṣyate"},{"type":"verse","number":"154","sanskrit":"अभावे त्वेतयोर्वैद्यः प्रक्षिपेद्र क्तचन्दनम् रक्तचन्दनकाभावे नवोशीरं विदुर्बुधाः","text":"abhāve tvetayorvaidyaḥ prakṣipedra ktacandanam raktacandanakābhāve navośīraṃ vidurbudhāḥ"},{"type":"verse","number":"155","sanskrit":"मुस्ता चातिविषाभावे शिवाऽभावे शिवा मता अभावे नागपुष्पस्य पद्मकेशरमिष्यते","text":"mustā cātiviṣābhāve śivā'bhāve śivā matā abhāve nāgapuṣpasya padmakeśaramiṣyate"},{"type":"verse","number":"156","sanskrit":"मेदाजीवककाकोलीऋद्धिद्वन्द्वेऽपि वाऽसति दरीविदार्यश्वगन्धावाराहीश्च क्रमात् क्षिपेत्","text":"medājīvakakākolīṛddhidvandve'pi vā'sati darīvidāryaśvagandhāvārāhīśca kramāt kṣipet"},{"type":"verse","number":"157","sanskrit":"वाराह्याश्च तथाऽभावे चर्मकारालुको मतः वाराहीकन्दसंज्ञस्तु पश्चिमे गृष्टिसंज्ञकः","text":"vārāhyāśca tathā'bhāve carmakārāluko mataḥ vārāhīkandasaṃjñastu paścime gṛṣṭisaṃjñakaḥ"},{"type":"verse","number":"158","sanskrit":"वारीहीकन्द एवान्यश्चर्मकारालुको मतः अनूपसम्भवे देशे वराह इव लोमवान्","text":"vārīhīkanda evānyaścarmakārāluko mataḥ anūpasambhave deśe varāha iva lomavān"},{"type":"verse","number":"159","sanskrit":"भल्लातकासहत्वे तु रक्तचन्दनमिष्यते भल्लाताभावतश्चित्रं नलश्चेक्षोरभावतः","text":"bhallātakāsahatve tu raktacandanamiṣyate bhallātābhāvataścitraṃ nalaścekṣorabhāvataḥ"},{"type":"verse","number":"160","sanskrit":"सुवर्णाभावतः स्वर्णमाक्षिकं प्रक्षिपेद् बुधः श्वेतं तु माक्षिकं ज्ञेयं बुधै रजतवद् ध्रुवम्","text":"suvarṇābhāvataḥ svarṇamākṣikaṃ prakṣiped budhaḥ śvetaṃ tu mākṣikaṃ jñeyaṃ budhai rajatavad dhruvam"},{"type":"verse","number":"161","sanskrit":"माक्षिकस्याप्यभावे तु प्रदद्यात्स्वर्णगैरिकम् सुवर्णमथ वा रौप्यं मृतं यत्र न लभ्यते","text":"mākṣikasyāpyabhāve tu pradadyātsvarṇagairikam suvarṇamatha vā raupyaṃ mṛtaṃ yatra na labhyate"},{"type":"verse","number":"162","sanskrit":"तत्र कान्तेन कर्माणि भिषक्कुर्याद्विचक्षणः कान्ताभावे तीक्ष्णलोहं योजयेद्वैद्यसत्तमः","text":"tatra kāntena karmāṇi bhiṣakkuryādvicakṣaṇaḥ kāntābhāve tīkṣṇalohaṃ yojayedvaidyasattamaḥ"},{"type":"verse","number":"163","sanskrit":"अभावे मौक्तिकस्यापि मुक्ताशुक्तिं प्रयोजयेत् मधु यत्र न लभ्येत तत्र जीर्णगुडो मतः","text":"abhāve mauktikasyāpi muktāśuktiṃ prayojayet madhu yatra na labhyeta tatra jīrṇaguḍo mataḥ"},{"type":"verse","number":"164","sanskrit":"मत्स्यण्ड्यभावतो दद्युर्भिषजः सितशर्कराम् असम्भवे सितायास्तु बुधैः खण्डं प्रयुज्यते","text":"matsyaṇḍyabhāvato dadyurbhiṣajaḥ sitaśarkarām asambhave sitāyāstu budhaiḥ khaṇḍaṃ prayujyate"},{"type":"verse","number":"165","sanskrit":"क्षीराभावे रसो मौद्गो मासूरो वा प्रदीयते अत्र प्रोक्तानि वस्तूनि यानि तेषु च तेषु च","text":"kṣīrābhāve raso maudgo māsūro vā pradīyate atra proktāni vastūni yāni teṣu ca teṣu ca"},{"type":"verse","number":"166","sanskrit":"योज्यमेकतराभावे परं वैद्येन जानता रसवीर्यविपाकाद्यैः समं द्र व्यं विचिन्त्य च","text":"yojyamekatarābhāve paraṃ vaidyena jānatā rasavīryavipākādyaiḥ samaṃ dra vyaṃ vicintya ca"},{"type":"verse","number":"167","sanskrit":"युञ्ज्यात्तद्विधमन्यच्च द्र व्याणां तु रसादिवित् योगे यदप्रधानं स्यात्तस्य प्रतिनिधिर्मतः","text":"yuñjyāttadvidhamanyacca dra vyāṇāṃ tu rasādivit yoge yadapradhānaṃ syāttasya pratinidhirmataḥ"},{"type":"verse","number":"168","sanskrit":"यत्तु प्रधानं तस्यापि सदृशं नैव गृह्यते व्याधेरयुक्तं यद्द्र व्यं गणोक्तमपि तत्त्यजेत् अनुक्तमपि युक्तं यद्योजयेत्तद्र सादिवित्","text":"yattu pradhānaṃ tasyāpi sadṛśaṃ naiva gṛhyate vyādherayuktaṃ yaddra vyaṃ gaṇoktamapi tattyajet anuktamapi yuktaṃ yadyojayettadra sādivit"},{"type":"verse","number":"169","sanskrit":"द्र व्ये रसो गुणो वीर्यं विपाकः शक्तिरेव च पदार्थाः पञ्च तिष्ठन्ति स्वं स्वं कुर्वन्ति कर्म च","text":"dra vye raso guṇo vīryaṃ vipākaḥ śaktireva ca padārthāḥ pañca tiṣṭhanti svaṃ svaṃ kurvanti karma ca"},{"type":"verse","number":"170","sanskrit":"रसाः स्वाद्वम्ललवणतिक्तोषणकषायकाः षड् द्र व्यमाश्रितास्ते च यथापूर्वं बलावहाः","text":"rasāḥ svādvamlalavaṇatiktoṣaṇakaṣāyakāḥ ṣaḍ dra vyamāśritāste ca yathāpūrvaṃ balāvahāḥ"},{"type":"verse","number":"171","sanskrit":"तत्राद्या मारुतं घ्नन्ति त्रयस्तिक्तादयः कफम् कषायतिक्तमधुराः पित्तमन्ये तु कुर्वते","text":"tatrādyā mārutaṃ ghnanti trayastiktādayaḥ kapham kaṣāyatiktamadhurāḥ pittamanye tu kurvate"},{"type":"verse","number":"172","sanskrit":"ये रसा वातशमना भवन्ति यदि तेषु वै रौक्ष्यलाघवशैत्यानि न ते हन्युः समीरणम्","text":"ye rasā vātaśamanā bhavanti yadi teṣu vai raukṣyalāghavaśaityāni na te hanyuḥ samīraṇam"},{"type":"verse","number":"173","sanskrit":"ये रसा पित्तशमना भवन्ति यदि तेषु वै तीक्ष्णोष्णलघुताश्चैव नैते तत्कर्मकारिणः","text":"ye rasā pittaśamanā bhavanti yadi teṣu vai tīkṣṇoṣṇalaghutāścaiva naite tatkarmakāriṇaḥ"},{"type":"verse","number":"174","sanskrit":"ये रसाः श्लेष्मशमना भवन्ति यदि तेषु वै स्नेहगौरवशैत्यानि न ते हन्युः कफं तदा","text":"ye rasāḥ śleṣmaśamanā bhavanti yadi teṣu vai snehagauravaśaityāni na te hanyuḥ kaphaṃ tadā"},{"type":"verse","number":"175","sanskrit":"मधुरो हि रसः शीतो धातुस्तन्यबलप्रदः चक्षुष्यो वातपित्तघ्नः कुर्यात्स्थौल्यमलकृमीन्","text":"madhuro hi rasaḥ śīto dhātustanyabalapradaḥ cakṣuṣyo vātapittaghnaḥ kuryātsthaulyamalakṛmīn"},{"type":"verse","number":"176","sanskrit":"विषघ्नः पिच्छिलश्चापि स्निग्धः प्रीत्यायुषोर्हितः बालबृद्धक्षतक्षीणवर्णकेशेन्द्रि यौजसाम्","text":"viṣaghnaḥ picchilaścāpi snigdhaḥ prītyāyuṣorhitaḥ bālabṛddhakṣatakṣīṇavarṇakeśendri yaujasām"},{"type":"verse","number":"177","sanskrit":"प्रशस्तो बृंहणः कण्ठ्यो गुरुः सन्धानकृन्मतः","text":"praśasto bṛṃhaṇaḥ kaṇṭhyo guruḥ sandhānakṛnmataḥ"},{"type":"verse","number":"178","sanskrit":"सोऽतियुक्तो ज्वरश्वासगलगण्डार्बुदकृमीन् स्थौल्याग्निमान्द्यमेहांश्च कुर्यान्मेदःकफामयान्","text":"so'tiyukto jvaraśvāsagalagaṇḍārbudakṛmīn sthaulyāgnimāndyamehāṃśca kuryānmedaḥkaphāmayān"},{"type":"verse","number":"179","sanskrit":"रसोऽम्ल पाचनो रुच्यः पित्तश्लेष्मास्रदो लघुः लेखितोष्णो बहिः शीतः क्लेदनः पवनापहः","text":"raso'mla pācano rucyaḥ pittaśleṣmāsrado laghuḥ lekhitoṣṇo bahiḥ śītaḥ kledanaḥ pavanāpahaḥ"},{"type":"verse","number":"180","sanskrit":"स्निग्धस्तीक्ष्णः सरः शुक्रविबन्धानाहदृष्टिहा हर्षणो रोमदन्तानामक्षिभ्रूविनिकोचनः","text":"snigdhastīkṣṇaḥ saraḥ śukravibandhānāhadṛṣṭihā harṣaṇo romadantānāmakṣibhrūvinikocanaḥ"},{"type":"verse","number":"181","sanskrit":"सोऽतियुक्तो भ्रमं कुर्यात्तृड्दाहतिमिरज्वरान् कण्डूपाण्डुत्ववीसर्पशोथविस्फोटकुष्ठकृत्","text":"so'tiyukto bhramaṃ kuryāttṛḍdāhatimirajvarān kaṇḍūpāṇḍutvavīsarpaśothavisphoṭakuṣṭhakṛt"},{"type":"verse","number":"182","sanskrit":"लवणः शोधनो रुच्यः पाचनः कफपित्तदः पुंस्त्ववातहरः कायशैथिल्यमृदुताकरः बलघ्न आस्यजलदः कपोलगलदाहकृत्","text":"lavaṇaḥ śodhano rucyaḥ pācanaḥ kaphapittadaḥ puṃstvavātaharaḥ kāyaśaithilyamṛdutākaraḥ balaghna āsyajaladaḥ kapolagaladāhakṛt"},{"type":"verse","number":"183","sanskrit":"सोऽति युक्तो ऽक्षिपाकास्रपित्त कोठक्षतादिकृत् वलीपलितखालित्यकुष्ठवीसर्पतृट्प्रदः","text":"so'ti yukto 'kṣipākāsrapitta koṭhakṣatādikṛt valīpalitakhālityakuṣṭhavīsarpatṛṭpradaḥ"},{"type":"verse","number":"184","sanskrit":"कटुरुष्णश्च तीक्ष्णश्च विशदो वातपित्तकृत् श्लेष्महृल्लघुराग्नेयः कृमिकण्डूविषापहः","text":"kaṭuruṣṇaśca tīkṣṇaśca viśado vātapittakṛt śleṣmahṛllaghurāgneyaḥ kṛmikaṇḍūviṣāpahaḥ"},{"type":"verse","number":"185","sanskrit":"शुक्रस्तन्यहरश्चापि मेदःस्थौल्यापकर्षणः अश्रुदो नासिकाऽस्याक्षिजिह्वाऽग्रोद्वेजको मतः","text":"śukrastanyaharaścāpi medaḥsthaulyāpakarṣaṇaḥ aśrudo nāsikā'syākṣijihvā'grodvejako mataḥ"},{"type":"verse","number":"186","sanskrit":"दीपनः पाचनो रुच्यो नासिकाशोषणो भृशम् क्लेदमेदोवसामज्जशकृन्मूत्रोपशोषणः","text":"dīpanaḥ pācano rucyo nāsikāśoṣaṇo bhṛśam kledamedovasāmajjaśakṛnmūtropaśoṣaṇaḥ"},{"type":"verse","number":"187","sanskrit":"स्रोतः प्रकाशको रूक्षः मेध्यो वर्चोविबन्धकृत्","text":"srotaḥ prakāśako rūkṣaḥ medhyo varcovibandhakṛt"},{"type":"verse","number":"188","sanskrit":"सोऽतियुक्तो भ्रान्तिदाहमुखताल्वोष्ठशोषकृत् कण्ठादिपीडामूर्च्छाऽन्तर्दाहदो बलकान्तिहृत्","text":"so'tiyukto bhrāntidāhamukhatālvoṣṭhaśoṣakṛt kaṇṭhādipīḍāmūrcchā'ntardāhado balakāntihṛt"},{"type":"verse","number":"189","sanskrit":"तिक्तः शीतस्तृषामूर्च्छाज्वरपित्तकफाञ्जयेत् कृमिकुष्ठविषोत्क्लेददाहरक्तगदापहः","text":"tiktaḥ śītastṛṣāmūrcchājvarapittakaphāñjayet kṛmikuṣṭhaviṣotkledadāharaktagadāpahaḥ"},{"type":"verse","number":"190","sanskrit":"रुच्यः स्वयमरोचिष्णुः कण्ठस्तन्यविशोधनः वातलोऽग्निकरो नासाशोषणो रूक्षणो लघुः","text":"rucyaḥ svayamarociṣṇuḥ kaṇṭhastanyaviśodhanaḥ vātalo'gnikaro nāsāśoṣaṇo rūkṣaṇo laghuḥ"},{"type":"verse","number":"191","sanskrit":"सोऽतियुक्तः शिरःशूलमन्यास्तम्भश्रमार्त्तिकृत् कम्पमूर्च्छातृषाकारी बलशुक्रक्षयप्रदः","text":"so'tiyuktaḥ śiraḥśūlamanyāstambhaśramārttikṛt kampamūrcchātṛṣākārī balaśukrakṣayapradaḥ"},{"type":"verse","number":"192","sanskrit":"कषायो रोपणो ग्राही स्तम्भनः शोधनस्तथा लेखनः पीडनः सौम्यः शोषणो वातकोपनः","text":"kaṣāyo ropaṇo grāhī stambhanaḥ śodhanastathā lekhanaḥ pīḍanaḥ saumyaḥ śoṣaṇo vātakopanaḥ"},{"type":"verse","number":"193","sanskrit":"कफशोणितपित्तघ्नो रूक्षः शीतो लघुर्मतः त्वक्प्रसाधन आमस्य स्तम्भनो विशदो मतः जिह्वायां जाड्यकृत्कण्ठस्रोतसां च विबन्धकृत्","text":"kaphaśoṇitapittaghno rūkṣaḥ śīto laghurmataḥ tvakprasādhana āmasya stambhano viśado mataḥ jihvāyāṃ jāḍyakṛtkaṇṭhasrotasāṃ ca vibandhakṛt"},{"type":"verse","number":"194","sanskrit":"सोऽतियुक्तो ग्रहाध्मानहृत्पीडाक्षेपणादिकृत्","text":"so'tiyukto grahādhmānahṛtpīḍākṣepaṇādikṛt"},{"type":"verse","number":"195","sanskrit":"मधुरं श्लेष्मलंप्रायो जीर्णशालियवादृते मुद्गाद्गोधूमतः क्षौद्रा त्सिताया जाङ्गलामिषात्","text":"madhuraṃ śleṣmalaṃprāyo jīrṇaśāliyavādṛte mudgādgodhūmataḥ kṣaudrā tsitāyā jāṅgalāmiṣāt"},{"type":"verse","number":"196","sanskrit":"अम्लं पित्तकरं प्रायो विना धात्रीं च दाडिमीम् लवणं प्रायशो द्वेषि नेत्रयोः सैन्धवं विना","text":"amlaṃ pittakaraṃ prāyo vinā dhātrīṃ ca dāḍimīm lavaṇaṃ prāyaśo dveṣi netrayoḥ saindhavaṃ vinā"},{"type":"verse","number":"197","sanskrit":"प्रायः कटु तथा तिक्तमवृष्यं वातकोपनम् शुण्ठी कृष्णारसोनानि पटोलममृतां विना","text":"prāyaḥ kaṭu tathā tiktamavṛṣyaṃ vātakopanam śuṇṭhī kṛṣṇārasonāni paṭolamamṛtāṃ vinā"},{"type":"verse","number":"198","sanskrit":"पिप्पलीनागरं वृष्यं कटु चावृष्यमुच्यते प्रायशः स्तम्भनं प्रोक्तं कषायमभयां विना","text":"pippalīnāgaraṃ vṛṣyaṃ kaṭu cāvṛṣyamucyate prāyaśaḥ stambhanaṃ proktaṃ kaṣāyamabhayāṃ vinā"},{"type":"verse","number":"199","sanskrit":"सामान्येनात्र निर्दिष्टा गुणाः षड्रससम्भवाः रसानां योगतस्तु स्यादन्य एव गुणोदयः","text":"sāmānyenātra nirdiṣṭā guṇāḥ ṣaḍrasasambhavāḥ rasānāṃ yogatastu syādanya eva guṇodayaḥ"},{"type":"verse","number":"200","sanskrit":"संयोगाद्विषतां याति सममाज्येन माक्षिंकम् अमृतत्वं विषं याति सर्पदष्टस्य वै यथा","text":"saṃyogādviṣatāṃ yāti samamājyena mākṣiṃkam amṛtatvaṃ viṣaṃ yāti sarpadaṣṭasya vai yathā"},{"type":"verse","number":"201","sanskrit":"लघुर्गुरुस्तथा स्निग्धो रूक्षस्तीक्ष्ण इति क्रमात् नभोभूवारिवातानां वह्नेरेते गुणाःस्मृताः","text":"laghurgurustathā snigdho rūkṣastīkṣṇa iti kramāt nabhobhūvārivātānāṃ vahnerete guṇāḥsmṛtāḥ"},{"type":"verse","number":"202","sanskrit":"लघु पथ्यं परं प्रोक्तं कफघ्नं शीघ्रपाकि च","text":"laghu pathyaṃ paraṃ proktaṃ kaphaghnaṃ śīghrapāki ca"},{"type":"verse","number":"203","sanskrit":"गरु वातहरं पुष्टिश्लेष्मकृच्चिरपाकि च स्निग्धं वातहरं श्लेष्मकारि वृष्यं बलावहम् रूक्षं समीरणकरं परं कफहरं मतम्","text":"garu vātaharaṃ puṣṭiśleṣmakṛccirapāki ca snigdhaṃ vātaharaṃ śleṣmakāri vṛṣyaṃ balāvaham rūkṣaṃ samīraṇakaraṃ paraṃ kaphaharaṃ matam"},{"type":"verse","number":"204","sanskrit":"तीक्ष्णं पित्तकरं प्रायो लेखनं कफवातहृत् सुश्रुते तु गुणा एते विंशतिस्तान्ब्रुवे शृणु","text":"tīkṣṇaṃ pittakaraṃ prāyo lekhanaṃ kaphavātahṛt suśrute tu guṇā ete viṃśatistānbruve śṛṇu"},{"type":"verse","number":"205","sanskrit":"गुरुर्लघुः स्निग्धरूक्षौ तीक्ष्णः श्लक्ष्णः स्थिरः सरः पिच्छिलो विशदः शीत उष्णश्च मृदुकर्कशौ स्थूलः सूक्ष्मो द्र वः शुष्क आशुर्मन्दः स्मृता गुणाः","text":"gururlaghuḥ snigdharūkṣau tīkṣṇaḥ ślakṣṇaḥ sthiraḥ saraḥ picchilo viśadaḥ śīta uṣṇaśca mṛdukarkaśau sthūlaḥ sūkṣmo dra vaḥ śuṣka āśurmandaḥ smṛtā guṇāḥ"},{"type":"verse","number":"206","sanskrit":"श्लक्ष्णः स्नेहं विनाऽपि स्यात्कठिनोऽपि हि चिक्कणः","text":"ślakṣṇaḥ snehaṃ vinā'pi syātkaṭhino'pi hi cikkaṇaḥ"},{"type":"verse","number":"207","sanskrit":"स्थिरो वातमलस्तम्भी सरस्तेषां प्रवर्तकः पिच्छिलस्तन्तुलो बल्यः सन्धानः श्लेष्मलो गुरुः","text":"sthiro vātamalastambhī sarasteṣāṃ pravartakaḥ picchilastantulo balyaḥ sandhānaḥ śleṣmalo guruḥ"},{"type":"verse","number":"208","sanskrit":"क्लेदच्छेदकरः ख्यातो विशदो व्रणरोपणः शीतस्तु ह्लादनःस्तम्भी मूर्च्छातृटस्वेददाहनुत् उष्णो भवति शीतस्य विपरीतश्च पाचनः","text":"kledacchedakaraḥ khyāto viśado vraṇaropaṇaḥ śītastu hlādanaḥstambhī mūrcchātṛṭasvedadāhanut uṣṇo bhavati śītasya viparītaśca pācanaḥ"},{"type":"verse","number":"209","sanskrit":"स्थूलः स्थौल्यकरो देहे स्रोतसामवरोधकृत्","text":"sthūlaḥ sthaulyakaro dehe srotasāmavarodhakṛt"},{"type":"verse","number":"210","sanskrit":"देहस्य सूक्ष्मच्छिद्रे षु विशेद्यत्सूक्ष्ममुच्यते द्र वः क्लेदकरो व्यापी शुष्कस्तद्विपरीतकः","text":"dehasya sūkṣmacchidre ṣu viśedyatsūkṣmamucyate dra vaḥ kledakaro vyāpī śuṣkastadviparītakaḥ"},{"type":"verse","number":"211","sanskrit":"आशुराशुकरो देहे धावत्यम्भसि तैलवत् मन्दः सकलकार्येषु शिथिलोऽल्पोऽपि कथ्यते","text":"āśurāśukaro dehe dhāvatyambhasi tailavat mandaḥ sakalakāryeṣu śithilo'lpo'pi kathyate"},{"type":"verse","number":"212","sanskrit":"पचेन्नामं वह्निकृद्यद्दीपनं तद्यथा मिसिः","text":"pacennāmaṃ vahnikṛdyaddīpanaṃ tadyathā misiḥ"},{"type":"verse","number":"213","sanskrit":"पचत्यामं न वह्निं च कुर्याद्यत्तद्धि पाचनम् नागकेशरवद्विद्याच्चित्रोदीपनपाचनः","text":"pacatyāmaṃ na vahniṃ ca kuryādyattaddhi pācanam nāgakeśaravadvidyāccitrodīpanapācanaḥ"},{"type":"verse","number":"214","sanskrit":"नशोधयति यद्दोषान्समान्नोदीरयत्यपि समीकरोति विषमाञ्छमनं तद्यथाऽमृता","text":"naśodhayati yaddoṣānsamānnodīrayatyapi samīkaroti viṣamāñchamanaṃ tadyathā'mṛtā"},{"type":"verse","number":"215","sanskrit":"कृत्वा पाकं मलानां च भित्वा बन्धमधो नयेत् तच्चानुलोमनं ज्ञेयं यथा प्रोक्ता हरीतकी","text":"kṛtvā pākaṃ malānāṃ ca bhitvā bandhamadho nayet taccānulomanaṃ jñeyaṃ yathā proktā harītakī"},{"type":"verse","number":"216","sanskrit":"पक्तव्यं यदपक्त्वैव श्लिष्टं कोष्ठे मलादिकम् नयत्यधः स्रंसनं तद्यथा स्यात्कृतमालकम्","text":"paktavyaṃ yadapaktvaiva śliṣṭaṃ koṣṭhe malādikam nayatyadhaḥ sraṃsanaṃ tadyathā syātkṛtamālakam"},{"type":"verse","number":"217","sanskrit":"मलादिकमबद्धं यद्बद्धं वा पिण्डितं मलैः भित्वाऽध पातयति यद्भेदनं कटुकी यथा","text":"malādikamabaddhaṃ yadbaddhaṃ vā piṇḍitaṃ malaiḥ bhitvā'dha pātayati yadbhedanaṃ kaṭukī yathā"},{"type":"verse","number":"218","sanskrit":"विपक्वं यदपक्वं वा मलादि द्र वतां नयेत् रेचयत्यपि तज्ज्ञेयं रेचनं त्रिवृता यथा","text":"vipakvaṃ yadapakvaṃ vā malādi dra vatāṃ nayet recayatyapi tajjñeyaṃ recanaṃ trivṛtā yathā"},{"type":"verse","number":"219","sanskrit":"अपक्वं पित्तश्लेष्मान्नं बलादूर्ध्वं नयेत्तु यत् वमनं तद्धि विज्ञेयं मदनस्य फलं यथा","text":"apakvaṃ pittaśleṣmānnaṃ balādūrdhvaṃ nayettu yat vamanaṃ taddhi vijñeyaṃ madanasya phalaṃ yathā"},{"type":"verse","number":"220","sanskrit":"स्थानाद्वहिर्नयेदूर्ध्वमधो वा मलसञ्चयम् देहसंशोधनं तत्स्याद् देवदालीफलं यथा","text":"sthānādvahirnayedūrdhvamadho vā malasañcayam dehasaṃśodhanaṃ tatsyād devadālīphalaṃ yathā"},{"type":"verse","number":"221","sanskrit":"दीपनं पाचनं यत्स्यादुष्णत्वाद्द्र वशोषकम् ग्राहि तच्च यथा शुण्ठी जीरकं गजपिप्पली","text":"dīpanaṃ pācanaṃ yatsyāduṣṇatvāddra vaśoṣakam grāhi tacca yathā śuṇṭhī jīrakaṃ gajapippalī"},{"type":"verse","number":"222","sanskrit":"रौक्ष्याच्छैत्यात्कषायत्वाल्लघुपाकाच्च यद्भवेत् वातकृत्स्तम्भनं तत्स्याद्यथा वत्सकटुण्टुकौ","text":"raukṣyācchaityātkaṣāyatvāllaghupākācca yadbhavet vātakṛtstambhanaṃ tatsyādyathā vatsakaṭuṇṭukau"},{"type":"verse","number":"223","sanskrit":"श्लिष्टान्कफादिकान्दोषानुन्मूलयति यद्वलात् छेदनं तद्यथा क्षारा मरिचानि शिलाजतु","text":"śliṣṭānkaphādikāndoṣānunmūlayati yadvalāt chedanaṃ tadyathā kṣārā maricāni śilājatu"},{"type":"verse","number":"224","sanskrit":"धातून्मलान् वा देहस्य विशोध्योल्लेखयेच्च यत् लेखनं तद्यथा क्षौद्रं नीरमुष्णं वचा यवाः","text":"dhātūnmalān vā dehasya viśodhyollekhayecca yat lekhanaṃ tadyathā kṣaudraṃ nīramuṣṇaṃ vacā yavāḥ"},{"type":"verse","number":"225","sanskrit":"यस्माद् द्र व्याद्भवेत्स्त्रीषु हर्षो वाजीकरं हि तत् यथाऽश्वगन्धामुसली शर्करा च शतावरी","text":"yasmād dra vyādbhavetstrīṣu harṣo vājīkaraṃ hi tat yathā'śvagandhāmusalī śarkarā ca śatāvarī"},{"type":"verse","number":"226","sanskrit":"यस्माच्छुक्रस्य वृद्धिः स्याच्छुक्रलं हि तदुच्यते यथा नागबलाऽद्या स्युर्बीजं च कपिकच्छुजम्","text":"yasmācchukrasya vṛddhiḥ syācchukralaṃ hi taducyate yathā nāgabalā'dyā syurbījaṃ ca kapikacchujam"},{"type":"verse","number":"227","sanskrit":"दुग्धं माषाश्च भल्लातफलमज्जामलानि च एतानि जनकानि स्यू रेचकानि च रेतसः","text":"dugdhaṃ māṣāśca bhallātaphalamajjāmalāni ca etāni janakāni syū recakāni ca retasaḥ"},{"type":"verse","number":"228","sanskrit":"प्रवर्तिनी स्त्री शुक्रस्य रेचनं बृहतीफलम् जातीफलं स्तम्भकं स्यात्कालिङ्गं क्षयकारि च","text":"pravartinī strī śukrasya recanaṃ bṛhatīphalam jātīphalaṃ stambhakaṃ syātkāliṅgaṃ kṣayakāri ca"},{"type":"verse","number":"229","sanskrit":"रसायनन्तु तज्ज्ञेयं यज्जराव्याधिनाशनम् यथा हरीतकी दन्ती गुग्गुलुश्च शिलाजतु","text":"rasāyanantu tajjñeyaṃ yajjarāvyādhināśanam yathā harītakī dantī gugguluśca śilājatu"},{"type":"verse","number":"230","sanskrit":"पूर्वं व्याप्याखिलं कायं ततः पाकञ्च गच्छति व्यवायि तद् यथा भङ्गा फेनञ्चाहि समुद्भवम्","text":"pūrvaṃ vyāpyākhilaṃ kāyaṃ tataḥ pākañca gacchati vyavāyi tad yathā bhaṅgā phenañcāhi samudbhavam"},{"type":"verse","number":"231","sanskrit":"सन्धिबन्धांस्तु शिथिलान्यत्करोति विकाशि तत् विशोष्यौजश्च धातुभ्यो यथा क्रमुककोद्र वौ","text":"sandhibandhāṃstu śithilānyatkaroti vikāśi tat viśoṣyaujaśca dhātubhyo yathā kramukakodra vau"},{"type":"verse","number":"232","sanskrit":"बुद्धिं लुम्पति यद् द्र व्यं मदकारि तदुच्यते तमोगुणप्रधानञ्च यथा मद्यं सुराऽदिकम्","text":"buddhiṃ lumpati yad dra vyaṃ madakāri taducyate tamoguṇapradhānañca yathā madyaṃ surā'dikam"},{"type":"verse","number":"233","sanskrit":"व्यवायि च विकाशि स्याच्छ्लेष्मच्छेदि मदावहम् आग्नेयं जीवितहरं योगवाहि स्मृतं विषम्","text":"vyavāyi ca vikāśi syācchleṣmacchedi madāvaham āgneyaṃ jīvitaharaṃ yogavāhi smṛtaṃ viṣam"},{"type":"verse","number":"234","sanskrit":"निजवीर्य्येण यद् द्र व्यं स्रोतोभ्यो दोषसञ्चयम् निरस्यति प्रमाथि स्यात्तद्यथा मरिचं वचा","text":"nijavīryyeṇa yad dra vyaṃ srotobhyo doṣasañcayam nirasyati pramāthi syāttadyathā maricaṃ vacā"},{"type":"verse","number":"235","sanskrit":"पैच्छिल्याद्गौरवाद् द्र व्यं रुद्ध्वा रसवहाः शिराः धत्ते यद्गौरवं तत्स्यादभिष्यन्दि यथा दधि","text":"paicchilyādgauravād dra vyaṃ ruddhvā rasavahāḥ śirāḥ dhatte yadgauravaṃ tatsyādabhiṣyandi yathā dadhi"},{"type":"verse","number":"236","sanskrit":"विदाहि द्र व्यमुद्गारमम्लं कुर्यात्तथा तृषाम् हृदि दाहं च जनयेत्पाकं गच्छति तच्चिरात्","text":"vidāhi dra vyamudgāramamlaṃ kuryāttathā tṛṣām hṛdi dāhaṃ ca janayetpākaṃ gacchati taccirāt"},{"type":"verse","number":"237","sanskrit":"गृह्णाति योगवाहि द्र व्यं संसर्गिवस्तुगुणान् पच्यमानं यथैतन्मधुजलतैलाज्यसूतलोहादिः","text":"gṛhṇāti yogavāhi dra vyaṃ saṃsargivastuguṇān pacyamānaṃ yathaitanmadhujalatailājyasūtalohādiḥ"},{"type":"verse","number":"238","sanskrit":"उष्णशीतगुणोत्कर्षाद् बुधैवीर्यं द्विधा स्मृतम् यत्सर्वमग्निषोमीयं दृश्यते भुवनत्रयम्","text":"uṣṇaśītaguṇotkarṣād budhaivīryaṃ dvidhā smṛtam yatsarvamagniṣomīyaṃ dṛśyate bhuvanatrayam"},{"type":"verse","number":"239","sanskrit":"उष्णं वातकफौ हन्यात् पित्तं तु तनुते जराम् शीतं वातकफातङ्कान्कुरुते पित्तहृत्परम्","text":"uṣṇaṃ vātakaphau hanyāt pittaṃ tu tanute jarām śītaṃ vātakaphātaṅkānkurute pittahṛtparam"},{"type":"verse","number":"240","sanskrit":"तत्रोष्णं भ्रमतृड्ग्लानिस्वेददाहाशुपाकताम् शमञ्च वातकफयो करोति शिशिरं पुनः ह्लादनं जीवनं स्तम्भं प्रसादं रक्तपित्तयोः","text":"tatroṣṇaṃ bhramatṛḍglānisvedadāhāśupākatām śamañca vātakaphayo karoti śiśiraṃ punaḥ hlādanaṃ jīvanaṃ stambhaṃ prasādaṃ raktapittayoḥ"},{"type":"verse","number":"241","sanskrit":"जाठरेणाग्निना योगाद्यदुदेति रसान्तरम् रसानां परिणामान्ते स विपाक इति स्मृतः","text":"jāṭhareṇāgninā yogādyadudeti rasāntaram rasānāṃ pariṇāmānte sa vipāka iti smṛtaḥ"},{"type":"verse","number":"242","sanskrit":"मिष्टः पटुश्च मधुरमम्लोऽम्ल पच्यते रसः कटुतिक्तकषायाणां पाकः स्यात्प्रायशः कटुः","text":"miṣṭaḥ paṭuśca madhuramamlo'mla pacyate rasaḥ kaṭutiktakaṣāyāṇāṃ pākaḥ syātprāyaśaḥ kaṭuḥ"},{"type":"verse","number":"243","sanskrit":"श्लेष्मकृन्मधुरः पाको वातपित्तहरो मतः अम्लस्तु कुरुते पित्तं वातश्लेष्मगदापहः","text":"śleṣmakṛnmadhuraḥ pāko vātapittaharo mataḥ amlastu kurute pittaṃ vātaśleṣmagadāpahaḥ"},{"type":"verse","number":"244","sanskrit":"कटुः करोति पवनं कफं पित्तञ्च नाशयेत् विशेष एवं रसतो विपाकानां निदर्शितः","text":"kaṭuḥ karoti pavanaṃ kaphaṃ pittañca nāśayet viśeṣa evaṃ rasato vipākānāṃ nidarśitaḥ"},{"type":"verse","number":"245","sanskrit":"रसादिसाम्ये यत्कर्म विशिष्टं तत्प्रभावजम् दन्ती रसाद्यैस्तुल्यापि चित्रकस्य विरेचनी","text":"rasādisāmye yatkarma viśiṣṭaṃ tatprabhāvajam dantī rasādyaistulyāpi citrakasya virecanī"},{"type":"verse","number":"246","sanskrit":"मधूकस्य च मृद्वीका घृतं क्षीरस्य दीपनम् प्रभावस्तु यथा धात्री लकुचस्य रसादिभिः","text":"madhūkasya ca mṛdvīkā ghṛtaṃ kṣīrasya dīpanam prabhāvastu yathā dhātrī lakucasya rasādibhiḥ"},{"type":"verse","number":"247","sanskrit":"समाऽपि कुरुते दोषत्रितयस्य विनाशनम्","text":"samā'pi kurute doṣatritayasya vināśanam"},{"type":"verse","number":"248","sanskrit":"क्वचित्तुकेवलं द्र व्यं कर्म कुर्यात्प्रभावतः ज्वरं हन्ति शिरोबद्धा सहदेवीजटा यथा","text":"kvacittukevalaṃ dra vyaṃ karma kuryātprabhāvataḥ jvaraṃ hanti śirobaddhā sahadevījaṭā yathā"},{"type":"verse","number":"249","sanskrit":"विरुद्धगुणसंयोगे भूयसाऽल्प हि जीयते रसं विपाकस्तौ वीर्यं प्रभावस्तान्व्यपोहति","text":"viruddhaguṇasaṃyoge bhūyasā'lpa hi jīyate rasaṃ vipākastau vīryaṃ prabhāvastānvyapohati"},{"type":"verse","number":"250","sanskrit":"इति मिश्रप्रकरणे मिश्रवर्गः प्रथमः समाप्तः","text":"iti miśraprakaraṇe miśravargaḥ prathamaḥ samāptaḥ"},{"type":"verse","number":"251","sanskrit":"भावप्रकाशपूर्वखण्डं","text":"bhāvaprakāśapūrvakhaṇḍaṃ"}]},{"sthana":"Пурвакханда","number":6,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 1"},{"type":"verse","number":"1","sanskrit":"न मानेन विना युक्तिर्द्र व्याणां जायते क्वचित् अतः प्रयोगकार्यार्थं मानमत्रोच्यते मया","text":"na mānena vinā yuktirdra vyāṇāṃ jāyate kvacit ataḥ prayogakāryārthaṃ mānamatrocyate mayā"},{"type":"verse","number":"2","sanskrit":"चरकस्य मतं वैद्यैराद्यैर्यस्मान्मतं ततः विहाय सर्वमानानि मागधं मानमुच्यते","text":"carakasya mataṃ vaidyairādyairyasmānmataṃ tataḥ vihāya sarvamānāni māgadhaṃ mānamucyate"},{"type":"verse","number":"3","sanskrit":"त्रसरेणुर्बुधैः प्रोक्तस्त्रिशता परमाणुभिः त्रसरेणुस्तु पर्यायनाम्ना वंशी निगद्यते","text":"trasareṇurbudhaiḥ proktastriśatā paramāṇubhiḥ trasareṇustu paryāyanāmnā vaṃśī nigadyate"},{"type":"verse","number":"4","sanskrit":"जालान्तरगतैः सूर्यकरैर्वंशी विलोक्यते षड्वंशीभिर्मरीचिः स्यात्ताभिः षड्भिश्च राजिका","text":"jālāntaragataiḥ sūryakarairvaṃśī vilokyate ṣaḍvaṃśībhirmarīciḥ syāttābhiḥ ṣaḍbhiśca rājikā"},{"type":"verse","number":"5","sanskrit":"तिसृभी राजिकाभिश्च्न सर्षपः प्रोच्यते बुधैः यवोऽष्टसर्षपैः प्रोक्तो गुञ्जा स्यात्तच्चतुष्टयम्","text":"tisṛbhī rājikābhiścna sarṣapaḥ procyate budhaiḥ yavo'ṣṭasarṣapaiḥ prokto guñjā syāttaccatuṣṭayam"},{"type":"verse","number":"6","sanskrit":"षड्भिस्तु रक्तिकाभिः स्यान्माषको हेमधानकौ माषैश्चतुर्भिः शाणः स्याद्धरणः स निगद्यते","text":"ṣaḍbhistu raktikābhiḥ syānmāṣako hemadhānakau māṣaiścaturbhiḥ śāṇaḥ syāddharaṇaḥ sa nigadyate"},{"type":"verse","number":"7","sanskrit":"टङ्कः स एव कथितस्तद्द्वयं कोल उच्यते क्षुद्र को वटकश्चैव द्र ङ्क्षणः स निगद्यते","text":"ṭaṅkaḥ sa eva kathitastaddvayaṃ kola ucyate kṣudra ko vaṭakaścaiva dra ṅkṣaṇaḥ sa nigadyate"},{"type":"verse","number":"8","sanskrit":"कोलद्वयन्तुं कर्षः स्यात्स प्रोक्तः पाणिमानिका अक्षः पिचुः पाणितलं किञ्चित्पाणिश्च तिन्दुकम्","text":"koladvayantuṃ karṣaḥ syātsa proktaḥ pāṇimānikā akṣaḥ picuḥ pāṇitalaṃ kiñcitpāṇiśca tindukam"},{"type":"verse","number":"9","sanskrit":"विडालपदकं चैव तथा षोडशिका मता करमध्यो हंसपदं सुवर्णं कवलग्रहः","text":"viḍālapadakaṃ caiva tathā ṣoḍaśikā matā karamadhyo haṃsapadaṃ suvarṇaṃ kavalagrahaḥ"},{"type":"verse","number":"10","sanskrit":"उदुम्बरञ्च पर्यायैः कर्षमेव निगद्यते स्यात्कर्षाभ्यामर्द्धपलं शुक्तिरष्टमिका तथा","text":"udumbarañca paryāyaiḥ karṣameva nigadyate syātkarṣābhyāmarddhapalaṃ śuktiraṣṭamikā tathā"},{"type":"verse","number":"11","sanskrit":"शुक्तिभ्याञ्च पलं ज्ञेयं मुष्टिराम्रं चतुर्थिका प्रकुञ्चः षोडशी बिल्वं पलमेवात्र कीत्तर्यते","text":"śuktibhyāñca palaṃ jñeyaṃ muṣṭirāmraṃ caturthikā prakuñcaḥ ṣoḍaśī bilvaṃ palamevātra kīttaryate"},{"type":"verse","number":"12","sanskrit":"पलाभ्यां प्रसृतिर्ज्ञेया प्रसृतञ्च निगद्यते प्रसृतिभ्यामञ्जलि स्यात्कुडवोऽद्धशरावकः","text":"palābhyāṃ prasṛtirjñeyā prasṛtañca nigadyate prasṛtibhyāmañjali syātkuḍavo'ddhaśarāvakaḥ"},{"type":"verse","number":"13","sanskrit":"अष्टमानञ्च स ज्ञेयः कुडवाभ्याञ्च मानिका शरावोऽष्टपलं तद्वज्ज्ञेयमत्र विचक्षणैः","text":"aṣṭamānañca sa jñeyaḥ kuḍavābhyāñca mānikā śarāvo'ṣṭapalaṃ tadvajjñeyamatra vicakṣaṇaiḥ"},{"type":"verse","number":"14","sanskrit":"शरावाभ्यां भवेत्प्रस्थश्चतुः प्रस्थस्तथाऽढकः भाजनं कांस्यपात्रं च चतुःषष्टिपलश्च सः","text":"śarāvābhyāṃ bhavetprasthaścatuḥ prasthastathā'ḍhakaḥ bhājanaṃ kāṃsyapātraṃ ca catuḥṣaṣṭipalaśca saḥ"},{"type":"verse","number":"15","sanskrit":"चतुर्भिराढकैद्रो र्णः! कलशो नल्वणोऽमणः उन्मानञ्चघटो राशिद्रो र्ण!पर्यायसंज्ञितः","text":"caturbhirāḍhakaidro rṇaḥ! kalaśo nalvaṇo'maṇaḥ unmānañcaghaṭo rāśidro rṇa!paryāyasaṃjñitaḥ"},{"type":"verse","number":"16","sanskrit":"द्रो णाभ्यां शूर्पकुम्भौ च चतुःषष्टिशरावकः शूर्पाभ्याञ्च भवेद् द्रो णी वाहो गोणी च सा स्मृता","text":"dro ṇābhyāṃ śūrpakumbhau ca catuḥṣaṣṭiśarāvakaḥ śūrpābhyāñca bhaved dro ṇī vāho goṇī ca sā smṛtā"},{"type":"verse","number":"17","sanskrit":"द्रो णीचतुष्टयं खारी कथिता सूक्ष्मबुद्धिभिः चतुःसहस्रपलिका षण्णवत्यधिका च सा","text":"dro ṇīcatuṣṭayaṃ khārī kathitā sūkṣmabuddhibhiḥ catuḥsahasrapalikā ṣaṇṇavatyadhikā ca sā"},{"type":"verse","number":"18","sanskrit":"पलानां द्विसहस्रञ्च भार एकः प्रकीर्त्तितः तुलापलशतं ज्ञेयं सर्वत्रैवैष निश्चयः","text":"palānāṃ dvisahasrañca bhāra ekaḥ prakīrttitaḥ tulāpalaśataṃ jñeyaṃ sarvatraivaiṣa niścayaḥ"},{"type":"verse","number":"19","sanskrit":"माषटङ्काक्षबिल्वानि कुडवप्रस्थमाढकम् राशिर्गोणी खारिकेति यथोत्तरचतुर्गुणम्","text":"māṣaṭaṅkākṣabilvāni kuḍavaprasthamāḍhakam rāśirgoṇī khāriketi yathottaracaturguṇam"},{"type":"verse","number":"20","sanskrit":"गुञ्जाऽदिमानमारभ्य यावत्स्यात्कुडवस्थितिः द्र वार्द्र शुष्कद्र व्याणां तावन्मानं समं मतम्","text":"guñjā'dimānamārabhya yāvatsyātkuḍavasthitiḥ dra vārdra śuṣkadra vyāṇāṃ tāvanmānaṃ samaṃ matam"},{"type":"verse","number":"21","sanskrit":"प्रस्थादिमानमारभ्य द्विगुणं तद् द्र वार्द्र योः मानं तथा तुलायास्तु द्विगुणं न क्वचित्स्मृतम्","text":"prasthādimānamārabhya dviguṇaṃ tad dra vārdra yoḥ mānaṃ tathā tulāyāstu dviguṇaṃ na kvacitsmṛtam"},{"type":"verse","number":"22","sanskrit":"मृद्वृक्षवेणुलोहादेर्भाण्डं यच्चतुरङ्गुलम् विस्तीर्णञ्च तथोच्चञ्च तन्मानं कुडवं वदेत्","text":"mṛdvṛkṣaveṇulohāderbhāṇḍaṃ yaccaturaṅgulam vistīrṇañca tathoccañca tanmānaṃ kuḍavaṃ vadet"},{"type":"verse","number":"23","sanskrit":"इति मागधमानं समाप्तम् यतो मन्दाग्नयो ह्रस्वा हीनसत्त्वा नराः कलौ अतस्तु मात्रा तद्योग्या प्रोच्यते सुज्ञसंमता","text":"iti māgadhamānaṃ samāptam yato mandāgnayo hrasvā hīnasattvā narāḥ kalau atastu mātrā tadyogyā procyate sujñasaṃmatā"},{"type":"verse","number":"24","sanskrit":"यवो द्वादशभिर्गौरसर्षपैः प्रोच्यते बुधैः यवद्वयेन गुञ्जा स्यात्त्रिगुञ्जो वल्ल उच्यते","text":"yavo dvādaśabhirgaurasarṣapaiḥ procyate budhaiḥ yavadvayena guñjā syāttriguñjo valla ucyate"},{"type":"verse","number":"25","sanskrit":"माषो गुञ्जाभिरष्टाभिः सप्तभिर्वा भवेत्क्वचित् चतुर्भिर्माषकैः शाणः स निष्कष्टङ्क एव च","text":"māṣo guñjābhiraṣṭābhiḥ saptabhirvā bhavetkvacit caturbhirmāṣakaiḥ śāṇaḥ sa niṣkaṣṭaṅka eva ca"},{"type":"verse","number":"26","sanskrit":"गद्याणो माषकैः षड्भिः कर्षः स्याद्दशमाषकैः चतुष्कर्षैः पलं प्रोक्तं दशशाणमितं बुधैः","text":"gadyāṇo māṣakaiḥ ṣaḍbhiḥ karṣaḥ syāddaśamāṣakaiḥ catuṣkarṣaiḥ palaṃ proktaṃ daśaśāṇamitaṃ budhaiḥ"},{"type":"verse","number":"27","sanskrit":"चतुष्पलैश्च कुडवः प्रस्थाद्याः पूर्ववन्मताः स्थितिर्नास्त्येव मात्रायाः कालमग्निं वयो बलम्","text":"catuṣpalaiśca kuḍavaḥ prasthādyāḥ pūrvavanmatāḥ sthitirnāstyeva mātrāyāḥ kālamagniṃ vayo balam"},{"type":"verse","number":"28","sanskrit":"प्रकृतिं दोषदेशौ च दृष्ट्वा मात्रां प्रकल्पयेत् नाल्पं हन्त्यौषधं व्याधिं यथाऽम्भोऽल्प महानलः अतिमात्रं च दोषाय यथा शस्ये बहूदकम्","text":"prakṛtiṃ doṣadeśau ca dṛṣṭvā mātrāṃ prakalpayet nālpaṃ hantyauṣadhaṃ vyādhiṃ yathā'mbho'lpa mahānalaḥ atimātraṃ ca doṣāya yathā śasye bahūdakam"},{"type":"verse","number":"29","sanskrit":"इति कालिङ्गमानं समाप्तम् इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे परिभाषादिप्रकरणे प्रथमं मानपरिभाषाख्यं प्रकरणं समाप्तम्","text":"iti kāliṅgamānaṃ samāptam iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe paribhāṣādiprakaraṇe prathamaṃ mānaparibhāṣākhyaṃ prakaraṇaṃ samāptam"}]},{"sthana":"Пурвакханда","number":7,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 2"},{"type":"verse","number":"1","sanskrit":"स्वरसश्च तथा कल्कः क्वाथश्च हिमफाण्टकौ ज्ञेयाः कषायाः पञ्चैते लघवः स्युर्यथोत्तरम्","text":"svarasaśca tathā kalkaḥ kvāthaśca himaphāṇṭakau jñeyāḥ kaṣāyāḥ pañcaite laghavaḥ syuryathottaram"},{"type":"verse","number":"2","sanskrit":"अहतात्तत्क्षणाकृष्टाद् द्र व्यात्क्षुण्णात्समुद्भवेत् वस्त्रनिष्पीडितो यश्च स्वरसो रस उच्यते","text":"ahatāttatkṣaṇākṛṣṭād dra vyātkṣuṇṇātsamudbhavet vastraniṣpīḍito yaśca svaraso rasa ucyate"},{"type":"verse","number":"3","sanskrit":"कुडवं चूर्णितं द्र व्यं क्षिप्तञ्च द्विगुणे जले अहोरात्रं स्थितं तस्माद्भवेद्वा रस उत्तमः","text":"kuḍavaṃ cūrṇitaṃ dra vyaṃ kṣiptañca dviguṇe jale ahorātraṃ sthitaṃ tasmādbhavedvā rasa uttamaḥ"},{"type":"verse","number":"4","sanskrit":"आदाय शुष्कद्र व्यं वा स्वरसानामसंभवे जलेऽष्टगुणिते साध्यं पादशिष्टं च गृह्यते","text":"ādāya śuṣkadra vyaṃ vā svarasānāmasaṃbhave jale'ṣṭaguṇite sādhyaṃ pādaśiṣṭaṃ ca gṛhyate"},{"type":"verse","number":"5","sanskrit":"स्वरस्य गुरुत्वाच्च पलमर्द्धं प्रयोजयेत् निशोषितं चाग्निसिद्धं पलमात्रं रसं पिबेत्","text":"svarasya gurutvācca palamarddhaṃ prayojayet niśoṣitaṃ cāgnisiddhaṃ palamātraṃ rasaṃ pibet"},{"type":"verse","number":"6","sanskrit":"सितामधुगुडक्षाराञ्जीरकं लवणं तथा घृतं तैलञ्च चूर्णादीन् कोलमात्रान् रसे क्षिपेत्","text":"sitāmadhuguḍakṣārāñjīrakaṃ lavaṇaṃ tathā ghṛtaṃ tailañca cūrṇādīn kolamātrān rase kṣipet"},{"type":"verse","number":"7","sanskrit":"कण्डितं तण्डुलपलं जलेऽष्टगुणिते क्षिपेत् भावयित्वा जलं ग्राह्यं देयं सर्वत्र कर्मसु","text":"kaṇḍitaṃ taṇḍulapalaṃ jale'ṣṭaguṇite kṣipet bhāvayitvā jalaṃ grāhyaṃ deyaṃ sarvatra karmasu"},{"type":"verse","number":"8","sanskrit":"क्षुण्णं द्र व्यपलं सम्यक् षड्भिर्नीरपलैः प्लुतम् निशोषितं हिमः स स्यात्तथा शीतकषायकः तस्य मानं मतं पाने पलद्वयमितं बुधैः","text":"kṣuṇṇaṃ dra vyapalaṃ samyak ṣaḍbhirnīrapalaiḥ plutam niśoṣitaṃ himaḥ sa syāttathā śītakaṣāyakaḥ tasya mānaṃ mataṃ pāne paladvayamitaṃ budhaiḥ"},{"type":"verse","number":"9","sanskrit":"जले चतुष्पले शीते क्षुण्णं द्र व्यपलं क्षिपेत् मृत्पात्रे मन्थयेत् सम्यक् तस्माच्च द्विपलं पिबेत्","text":"jale catuṣpale śīte kṣuṇṇaṃ dra vyapalaṃ kṣipet mṛtpātre manthayet samyak tasmācca dvipalaṃ pibet"},{"type":"verse","number":"10","sanskrit":"क्षुण्णे द्र व्यपले सम्यग्जलमुष्णं विनिक्षिपेत् मृत्पात्रे कुडवोन्मानं ततस्तु स्रावयेत्पटात्","text":"kṣuṇṇe dra vyapale samyagjalamuṣṇaṃ vinikṣipet mṛtpātre kuḍavonmānaṃ tatastu srāvayetpaṭāt"},{"type":"verse","number":"11","sanskrit":"स स्याच्चूर्णद्र वः फाण्टस्तन्मानं द्विपलोन्मितम् क्षौद्रं सितागुडादींस्तु कर्षमात्रान्विनिक्षिपेत्","text":"sa syāccūrṇadra vaḥ phāṇṭastanmānaṃ dvipalonmitam kṣaudraṃ sitāguḍādīṃstu karṣamātrānvinikṣipet"},{"type":"verse","number":"12","sanskrit":"द्र व्यमाद्र रं! शिलापिष्टं शुष्कं वा सजलं भवेत् तदेव कल्को विज्ञेयस्तन्मानं कर्षसम्मितम्","text":"dra vyamādra raṃ! śilāpiṣṭaṃ śuṣkaṃ vā sajalaṃ bhavet tadeva kalko vijñeyastanmānaṃ karṣasammitam"},{"type":"verse","number":"13","sanskrit":"कल्के मधुघृतं तैलं देयं द्बिगुणमात्रया सितां गुडं समं दद्याद् द्र वो देयश्चतुर्गुणः","text":"kalke madhughṛtaṃ tailaṃ deyaṃ dbiguṇamātrayā sitāṃ guḍaṃ samaṃ dadyād dra vo deyaścaturguṇaḥ"},{"type":"verse","number":"14","sanskrit":"अत्यन्तशुष्कं यद् द्र व्यं सुपिष्टं वस्त्रगालितम् तत्स्याच्चूर्णं रजः क्षोदस्तन्मात्रा कर्षसम्मिता","text":"atyantaśuṣkaṃ yad dra vyaṃ supiṣṭaṃ vastragālitam tatsyāccūrṇaṃ rajaḥ kṣodastanmātrā karṣasammitā"},{"type":"verse","number":"15","sanskrit":"चूर्णे गुडः समो देयः शर्करा द्विगुणा मता चूर्णेषु भर्जितं हिङ्गु देयं नोत्क्लेदकृद्भवेत्","text":"cūrṇe guḍaḥ samo deyaḥ śarkarā dviguṇā matā cūrṇeṣu bharjitaṃ hiṅgu deyaṃ notkledakṛdbhavet"},{"type":"verse","number":"16","sanskrit":"लिहेच्चूर्णं द्र वैः सर्वैर्घृताद्यैर्द्विगुणोन्मितैः पिबेच्चतुर्गुणैरेवं चूर्णमालोडितं द्र वैः","text":"liheccūrṇaṃ dra vaiḥ sarvairghṛtādyairdviguṇonmitaiḥ pibeccaturguṇairevaṃ cūrṇamāloḍitaṃ dra vaiḥ"},{"type":"verse","number":"17","sanskrit":"चूर्णावलेहगुटिकाकल्कानामनुपानकम् पित्तवातकफातङ्के त्रिद्व्येकपलमाहरेत्","text":"cūrṇāvalehaguṭikākalkānāmanupānakam pittavātakaphātaṅke tridvyekapalamāharet"},{"type":"verse","number":"18","sanskrit":"यथा तैलं जले क्षिप्तं क्षणेनैव विसर्पति अनुपानबलादङ्गे तथा सर्पति भेषजम्","text":"yathā tailaṃ jale kṣiptaṃ kṣaṇenaiva visarpati anupānabalādaṅge tathā sarpati bheṣajam"},{"type":"verse","number":"19","sanskrit":"द्र वेण यावता सम्यक् चूर्णं सर्वं प्लुतं भवेत् भावनायाः प्रमाणं तु चूर्णे प्रोक्तं भिषग्वरैः","text":"dra veṇa yāvatā samyak cūrṇaṃ sarvaṃ plutaṃ bhavet bhāvanāyāḥ pramāṇaṃ tu cūrṇe proktaṃ bhiṣagvaraiḥ"},{"type":"verse","number":"20","sanskrit":"पुटपाकस्य कल्कस्य स्वरसो गृह्यते यतः अतस्तु पुटपाकानां युक्तिरत्रोच्यते मया","text":"puṭapākasya kalkasya svaraso gṛhyate yataḥ atastu puṭapākānāṃ yuktiratrocyate mayā"},{"type":"verse","number":"21","sanskrit":"पुटपाकस्य पाकोऽय लेपस्याङ्गारवर्णता लेपश्च द्व्यङ्गुलं स्थूलं कुर्याद् द्व्यङ्गुलमात्रकम्","text":"puṭapākasya pāko'ya lepasyāṅgāravarṇatā lepaśca dvyaṅgulaṃ sthūlaṃ kuryād dvyaṅgulamātrakam"},{"type":"verse","number":"22","sanskrit":"काश्मरीवटजम्ब्वादिपत्रैर्वेष्टनमुत्तमम्","text":"kāśmarīvaṭajambvādipatrairveṣṭanamuttamam"},{"type":"verse","number":"23","sanskrit":"पलमात्रो रसो ग्राह्यः कर्षमानं मधु क्षिपेत् कल्कचूर्णद्र वाद्यास्तु देयाः कोलमिता बुधैः","text":"palamātro raso grāhyaḥ karṣamānaṃ madhu kṣipet kalkacūrṇadra vādyāstu deyāḥ kolamitā budhaiḥ"},{"type":"verse","number":"24","sanskrit":"अष्टमेनांशशेषेण चतुर्थेनार्द्धकेन वा अथवा क्वथनेनैव सिद्धमुष्णोदकं भवेत्","text":"aṣṭamenāṃśaśeṣeṇa caturthenārddhakena vā athavā kvathanenaiva siddhamuṣṇodakaṃ bhavet"},{"type":"verse","number":"25","sanskrit":"श्लेष्मामवातमेदोघ्नं वस्तिशोधनदीपनम् कासश्वासज्वरान् हन्ति पीतमुष्णोदकं निशि","text":"śleṣmāmavātamedoghnaṃ vastiśodhanadīpanam kāsaśvāsajvarān hanti pītamuṣṇodakaṃ niśi"},{"type":"verse","number":"26","sanskrit":"क्षीरमष्टगुणं द्र व्यात्क्षीरान्नीरं चतुर्गुणम् क्षीरावशेषं तत्पीतं शूलमामोद्भवं जयेत्","text":"kṣīramaṣṭaguṇaṃ dra vyātkṣīrānnīraṃ caturguṇam kṣīrāvaśeṣaṃ tatpītaṃ śūlamāmodbhavaṃ jayet"},{"type":"verse","number":"27","sanskrit":"पानीयं षोडशगुणं क्षुण्णे द्र व्यपले क्षिपेत् मृत्पात्रे क्वाथयेद् ग्राह्यमष्टमांशावशेषितम्","text":"pānīyaṃ ṣoḍaśaguṇaṃ kṣuṇṇe dra vyapale kṣipet mṛtpātre kvāthayed grāhyamaṣṭamāṃśāvaśeṣitam"},{"type":"verse","number":"28","sanskrit":"कर्षादौ तु पलं यावद् दद्यात्षोडशिकं जलम् ततस्तु कुडवं यावत्तोयमष्टगुणं भवेत् चतुर्गुणमतश्चोर्ध्वं यावत् प्रस्थादिकं जलम्","text":"karṣādau tu palaṃ yāvad dadyātṣoḍaśikaṃ jalam tatastu kuḍavaṃ yāvattoyamaṣṭaguṇaṃ bhavet caturguṇamataścordhvaṃ yāvat prasthādikaṃ jalam"},{"type":"verse","number":"29","sanskrit":"तज्जलं पाययेद्धीमान्कोष्णं मृद्वग्निसाधितम् शृतः क्वाथः कषायश्च निर्यूहः स निगद्यते","text":"tajjalaṃ pāyayeddhīmānkoṣṇaṃ mṛdvagnisādhitam śṛtaḥ kvāthaḥ kaṣāyaśca niryūhaḥ sa nigadyate"},{"type":"verse","number":"30","sanskrit":"मात्रोत्तमा पलेन स्यात्त्रिभिरक्षैस्तु मध्यमा जघन्या च पलार्द्धेन स्नेहक्वाथौषधेषु च","text":"mātrottamā palena syāttribhirakṣaistu madhyamā jaghanyā ca palārddhena snehakvāthauṣadheṣu ca"},{"type":"verse","number":"31","sanskrit":"क्वाथ्यद्र व्यपले वारि द्विरष्टगुणमिष्यते चतुर्भागावशिष्टन्तु पेयं जलचतुष्टयम्","text":"kvāthyadra vyapale vāri dviraṣṭaguṇamiṣyate caturbhāgāvaśiṣṭantu peyaṃ jalacatuṣṭayam"},{"type":"verse","number":"32","sanskrit":"दीप्तानलं महाकायं पाययेदञ्जलि जलम् अन्ये त्वर्द्धं परित्यज्य प्रसृतिं तु चिकित्सकाः","text":"dīptānalaṃ mahākāyaṃ pāyayedañjali jalam anye tvarddhaṃ parityajya prasṛtiṃ tu cikitsakāḥ"},{"type":"verse","number":"33","sanskrit":"क्वाथत्यागमनिच्छन्तस्त्वष्टभागावशेषितम् पारम्पर्योपदेशेन वृद्धवैद्याः पलद्वयम्","text":"kvāthatyāgamanicchantastvaṣṭabhāgāvaśeṣitam pāramparyopadeśena vṛddhavaidyāḥ paladvayam"},{"type":"verse","number":"34","sanskrit":"क्वाथे क्षिपेत्सितामंशैश्चतुर्थाष्टमषोडशैः वातपित्तकफातङ्के विपरीतं लघु स्मृतम्","text":"kvāthe kṣipetsitāmaṃśaiścaturthāṣṭamaṣoḍaśaiḥ vātapittakaphātaṅke viparītaṃ laghu smṛtam"},{"type":"verse","number":"35","sanskrit":"जीरकं गुग्गुलं क्षारं लवणं च शिलाजतु हिङ्गु त्रिकटुकञ्चैव क्वाथे शाणोन्मितं क्षिपेत्","text":"jīrakaṃ guggulaṃ kṣāraṃ lavaṇaṃ ca śilājatu hiṅgu trikaṭukañcaiva kvāthe śāṇonmitaṃ kṣipet"},{"type":"verse","number":"36","sanskrit":"क्षीरं घृतं गुडं तैलं मूत्रं चान्यद् द्र वं तथा कल्कं चूर्णादिकं क्वाथे निक्षिपेत् कर्षसम्मितम्","text":"kṣīraṃ ghṛtaṃ guḍaṃ tailaṃ mūtraṃ cānyad dra vaṃ tathā kalkaṃ cūrṇādikaṃ kvāthe nikṣipet karṣasammitam"},{"type":"verse","number":"37","sanskrit":"तत्रोपविश्य विश्रान्तः प्रसन्नवदनेक्षणः औषधं हेमरजतमृद्भाजनपरिस्थितम्","text":"tatropaviśya viśrāntaḥ prasannavadanekṣaṇaḥ auṣadhaṃ hemarajatamṛdbhājanaparisthitam"},{"type":"verse","number":"38","sanskrit":"पिबेत् प्रसन्नहृदयः पीत्वा पात्रमधोमुखम् विधायाचम्य सलिलं ताम्बूलाद्युपयोजयेत्","text":"pibet prasannahṛdayaḥ pītvā pātramadhomukham vidhāyācamya salilaṃ tāmbūlādyupayojayet"},{"type":"verse","number":"39","sanskrit":"क्वाथादेर्यत्पुनः पाकाद् घनत्वं सा रसक्रिया सोऽवलेहश्च लेहश्च तन्मात्रा स्यात्पलोन्मिता","text":"kvāthāderyatpunaḥ pākād ghanatvaṃ sā rasakriyā so'valehaśca lehaśca tanmātrā syātpalonmitā"},{"type":"verse","number":"40","sanskrit":"सिता चतुर्गुणा कार्या चूर्णाच्च द्विगुणो गुडः द्र वं चतुर्गुणं दद्यादिति सर्वत्र निश्चयः","text":"sitā caturguṇā kāryā cūrṇācca dviguṇo guḍaḥ dra vaṃ caturguṇaṃ dadyāditi sarvatra niścayaḥ"},{"type":"verse","number":"41","sanskrit":"सुपक्वे तन्तुमत्त्वं स्यादवलेहेऽप्सु मज्जनम् स्थिरत्वं पीडिते मुद्रा गन्धवर्णरसोद्भवः","text":"supakve tantumattvaṃ syādavalehe'psu majjanam sthiratvaṃ pīḍite mudrā gandhavarṇarasodbhavaḥ"},{"type":"verse","number":"42","sanskrit":"दुग्धमिक्षुरसं यूषं पञ्चमूलकषायकम् वासाक्वाथं यथायोग्यमनुपानं प्रशस्यते","text":"dugdhamikṣurasaṃ yūṣaṃ pañcamūlakaṣāyakam vāsākvāthaṃ yathāyogyamanupānaṃ praśasyate"},{"type":"verse","number":"43","sanskrit":"वटका अथ कथ्यन्ते तन्नाम गुटिका वटी मोदको वटिका पिण्डी गुडो वर्त्तिस्तथोच्यते","text":"vaṭakā atha kathyante tannāma guṭikā vaṭī modako vaṭikā piṇḍī guḍo varttistathocyate"},{"type":"verse","number":"44","sanskrit":"लेहवत्साध्यते वह्नौ गुडो वा शर्कराऽथवा गुग्गुल्लुर्वा क्षिपेत्तत्र चूर्णं तन्निर्मिता वटी","text":"lehavatsādhyate vahnau guḍo vā śarkarā'thavā guggullurvā kṣipettatra cūrṇaṃ tannirmitā vaṭī"},{"type":"verse","number":"45","sanskrit":"कुर्यादवह्निसिद्धेन क्वचिद् गुग्गुलुना वटीम् द्र वेण मधुना वाऽपि गुटिकां कारयेद् बुधः","text":"kuryādavahnisiddhena kvacid guggulunā vaṭīm dra veṇa madhunā vā'pi guṭikāṃ kārayed budhaḥ"},{"type":"verse","number":"46","sanskrit":"सिता चतुर्गुणा देया वटीषु द्विगुणो गुडः चूर्णे चूर्णसमः कार्यो गुग्गुलुर्मधु तत्समम्","text":"sitā caturguṇā deyā vaṭīṣu dviguṇo guḍaḥ cūrṇe cūrṇasamaḥ kāryo guggulurmadhu tatsamam"},{"type":"verse","number":"47","sanskrit":"द्र वं तु द्विगुणं देयं मोदकेषु भिषग्वरैः","text":"dra vaṃ tu dviguṇaṃ deyaṃ modakeṣu bhiṣagvaraiḥ"},{"type":"verse","number":"48","sanskrit":"कर्षप्रमाणं तन्मात्रा बलं दृष्ट्वा प्रयुज्यते","text":"karṣapramāṇaṃ tanmātrā balaṃ dṛṣṭvā prayujyate"},{"type":"verse","number":"49","sanskrit":"कल्काच्चतुर्गुणीकृत्य घृतं वा तैलमेव च चतुर्गुणद्र वे साध्यं तस्य मात्रा पलोन्मिता","text":"kalkāccaturguṇīkṛtya ghṛtaṃ vā tailameva ca caturguṇadra ve sādhyaṃ tasya mātrā palonmitā"},{"type":"verse","number":"50","sanskrit":"निक्षिप्य क्वाथयेत्तोयं क्वाथ्यद्र व्याच्चतुर्गुणम् पादशिष्टं गृहीत्वा तु स्नेहं तेनैव साधयेत्","text":"nikṣipya kvāthayettoyaṃ kvāthyadra vyāccaturguṇam pādaśiṣṭaṃ gṛhītvā tu snehaṃ tenaiva sādhayet"},{"type":"verse","number":"51","sanskrit":"चतुर्गुणं मृदुद्र व्ये कठिनेऽष्टगुणं जलम् मृद्वादिक्वाथ्यसंघाते दद्यादष्टगुणं पयः अत्यन्त कठिने द्र व्ये नीरं षोडशिकं मतम्","text":"caturguṇaṃ mṛdudra vye kaṭhine'ṣṭaguṇaṃ jalam mṛdvādikvāthyasaṃghāte dadyādaṣṭaguṇaṃ payaḥ atyanta kaṭhine dra vye nīraṃ ṣoḍaśikaṃ matam"},{"type":"verse","number":"52","sanskrit":"प्रस्थादितः क्षिपेन्नीरं खारीं यावच्चतुर्गुणम्","text":"prasthāditaḥ kṣipennīraṃ khārīṃ yāvaccaturguṇam"},{"type":"verse","number":"53","sanskrit":"अम्बुक्वाथरसैर्यत्र पृथक् स्नेहस्य साधनम् कल्कस्यांशं तत्र दद्याच्चतुर्थ षष्ठमष्टमम्","text":"ambukvātharasairyatra pṛthak snehasya sādhanam kalkasyāṃśaṃ tatra dadyāccaturtha ṣaṣṭhamaṣṭamam"},{"type":"verse","number":"54","sanskrit":"दुग्धेदध्नि रसे तक्रे कल्को देयोऽष्टमांशकः कल्काच्च सम्यक् पाकार्थं तोयमत्र चतुर्गुणम्","text":"dugdhedadhni rase takre kalko deyo'ṣṭamāṃśakaḥ kalkācca samyak pākārthaṃ toyamatra caturguṇam"},{"type":"verse","number":"55","sanskrit":"द्र वाणि यत्र स्नेहेषु पञ्चादीनि भवन्ति हि तत्र स्नेहसमान्याहुर्यथापूर्वं चतुर्गुणम्","text":"dra vāṇi yatra sneheṣu pañcādīni bhavanti hi tatra snehasamānyāhuryathāpūrvaṃ caturguṇam"},{"type":"verse","number":"56","sanskrit":"द्र व्येण केवलेनैव स्नेहपाको भवेद् यदि तत्राम्बुपिष्टः कल्कः स्याज्जलं चात्र चतुर्गुणम्","text":"dra vyeṇa kevalenaiva snehapāko bhaved yadi tatrāmbupiṣṭaḥ kalkaḥ syājjalaṃ cātra caturguṇam"},{"type":"verse","number":"57","sanskrit":"क्वाथेन केवलेनैव पाको यत्रोदितः क्वचित् क्वाथ्यद्र व्यस्य कल्कोऽपि तत्र स्नेहे प्रयुज्यते","text":"kvāthena kevalenaiva pāko yatroditaḥ kvacit kvāthyadra vyasya kalko'pi tatra snehe prayujyate"},{"type":"verse","number":"58","sanskrit":"कल्कहीनस्तु यः स्नेहः स साध्यः केवले द्र वे","text":"kalkahīnastu yaḥ snehaḥ sa sādhyaḥ kevale dra ve"},{"type":"verse","number":"59","sanskrit":"पुष्पकल्कस्तु यः स्नेहस्तत्र तोयं चतुर्गुणम् स्नेहात् स्नेहाष्टमांशश्च पुष्पकल्कः प्रयुज्यते","text":"puṣpakalkastu yaḥ snehastatra toyaṃ caturguṇam snehāt snehāṣṭamāṃśaśca puṣpakalkaḥ prayujyate"},{"type":"verse","number":"60","sanskrit":"वर्त्तिवत्स्नेहकल्कः स्याद् यदाऽङ्गुल्या विवर्त्तितः शब्दहीनोऽग्निनिक्षिप्तःस्नेहः सिद्धो भवेत्तदा","text":"varttivatsnehakalkaḥ syād yadā'ṅgulyā vivarttitaḥ śabdahīno'gninikṣiptaḥsnehaḥ siddho bhavettadā"},{"type":"verse","number":"61","sanskrit":"यदा फेनोद्गमस्तैले फेनशान्तिश्च सर्पिषि वर्णगन्धरसोत्पत्तिः स्नेहः सिद्धो भवेत्तदा","text":"yadā phenodgamastaile phenaśāntiśca sarpiṣi varṇagandharasotpattiḥ snehaḥ siddho bhavettadā"},{"type":"verse","number":"62","sanskrit":"स्नेहपाकस्त्रिधा प्रोक्तो मृदुर्मध्यः खरस्तथा ईषत्सरसकल्कस्तु स्नेहपाको मृदुर्भवेत्","text":"snehapākastridhā prokto mṛdurmadhyaḥ kharastathā īṣatsarasakalkastu snehapāko mṛdurbhavet"},{"type":"verse","number":"63","sanskrit":"मध्यपाकस्य सिद्धिश्च कल्के नीरसकोमले ईषत्कठिनकल्कश्च स्नेहपाको भवेत्खरः","text":"madhyapākasya siddhiśca kalke nīrasakomale īṣatkaṭhinakalkaśca snehapāko bhavetkharaḥ"},{"type":"verse","number":"64","sanskrit":"तदूर्ध्वं दग्धपाकः स्याद्दाहकृन्निष्प्रयोजनः आमपाकश्च निर्वीर्यो वह्निमान्द्यकरो गुरुः","text":"tadūrdhvaṃ dagdhapākaḥ syāddāhakṛnniṣprayojanaḥ āmapākaśca nirvīryo vahnimāndyakaro guruḥ"},{"type":"verse","number":"65","sanskrit":"नस्यार्थं स्यान्मृदुः पाको मध्यमः सर्वकर्मसु अभ्यङ्गार्थः खरः प्रोक्तो युञ्ज्यादेवं यथोचितम्","text":"nasyārthaṃ syānmṛduḥ pāko madhyamaḥ sarvakarmasu abhyaṅgārthaḥ kharaḥ prokto yuñjyādevaṃ yathocitam"},{"type":"verse","number":"66","sanskrit":"घृततैलगुडादींश्च साधयेन्नैकवासरे प्रकुर्वुन्त्युषितास्त्वेते विशेषाद् गुणसञ्चयम्","text":"ghṛtatailaguḍādīṃśca sādhayennaikavāsare prakurvuntyuṣitāstvete viśeṣād guṇasañcayam"},{"type":"verse","number":"67","sanskrit":"द्र वेषु चिरकालस्थं द्र व्यं यत्सन्धितं भवेत् आसवारिष्टभेदैस्तु प्रोच्यते भेषजोचितम्","text":"dra veṣu cirakālasthaṃ dra vyaṃ yatsandhitaṃ bhavet āsavāriṣṭabhedaistu procyate bheṣajocitam"},{"type":"verse","number":"68","sanskrit":"यदपक्वौषधाम्बुभ्यां सिद्धं मद्यं स आसवः अरिष्टः क्वाथसाध्यः स्यात्तयोर्मानं पलोन्मितम्","text":"yadapakvauṣadhāmbubhyāṃ siddhaṃ madyaṃ sa āsavaḥ ariṣṭaḥ kvāthasādhyaḥ syāttayormānaṃ palonmitam"},{"type":"verse","number":"69","sanskrit":"अनुक्तमानारिष्टेषु द्र वाद् द्रो णं गुडात्तुलाम् क्षौद्रं क्षिपेद् गुडादर्द्धं प्रक्षेपं दशमांशिकम्","text":"anuktamānāriṣṭeṣu dra vād dro ṇaṃ guḍāttulām kṣaudraṃ kṣiped guḍādarddhaṃ prakṣepaṃ daśamāṃśikam"},{"type":"verse","number":"70","sanskrit":"ज्ञेयः शीतरसः सीघुरपक्वमधुरद्र वैः सिद्धः पक्वरसः सीधुः सम्पक्वमधुरद्र वैः","text":"jñeyaḥ śītarasaḥ sīghurapakvamadhuradra vaiḥ siddhaḥ pakvarasaḥ sīdhuḥ sampakvamadhuradra vaiḥ"},{"type":"verse","number":"71","sanskrit":"परिपक्वान्नसन्धानात्समुत्पन्नां सुरां जगुः सुरामण्डः प्रसन्ना स्यात्ततः कादम्वरी घना","text":"paripakvānnasandhānātsamutpannāṃ surāṃ jaguḥ surāmaṇḍaḥ prasannā syāttataḥ kādamvarī ghanā"},{"type":"verse","number":"72","sanskrit":"तदधो जगलो ज्ञेयो मेदको जगलाद्घनः वक्कसो हृतसारः स्यात्सुराबीजं तु किण्वकम्","text":"tadadho jagalo jñeyo medako jagalādghanaḥ vakkaso hṛtasāraḥ syātsurābījaṃ tu kiṇvakam"},{"type":"verse","number":"73","sanskrit":"यत्तालखर्जूररसैः सन्धिता सा हि वारुणी","text":"yattālakharjūrarasaiḥ sandhitā sā hi vāruṇī"},{"type":"verse","number":"74","sanskrit":"कन्दमूलफलादीनि सस्नेहलवणानि च यत्र द्र वेऽभिषूयन्ते तच्छुक्तमभिधीयते","text":"kandamūlaphalādīni sasnehalavaṇāni ca yatra dra ve'bhiṣūyante tacchuktamabhidhīyate"},{"type":"verse","number":"75","sanskrit":"विनष्टमम्लतां यातं मद्यं वा मधुरद्र वः विनष्टः सन्धितो यस्तु तच्चुक्रमभिधीयते","text":"vinaṣṭamamlatāṃ yātaṃ madyaṃ vā madhuradra vaḥ vinaṣṭaḥ sandhito yastu taccukramabhidhīyate"},{"type":"verse","number":"76","sanskrit":"गुडाम्बुना सतैलेन कन्दशाकफलैस्तथा संधितं चाम्लतां यातं गुडचुक्रं प्रचक्ष्यते एवमेव हि शुक्तं स्यान्मृद्वीकासम्भवं तथा","text":"guḍāmbunā satailena kandaśākaphalaistathā saṃdhitaṃ cāmlatāṃ yātaṃ guḍacukraṃ pracakṣyate evameva hi śuktaṃ syānmṛdvīkāsambhavaṃ tathā"},{"type":"verse","number":"77","sanskrit":"तुषाम्बु सन्धितं ज्ञेयमामैर्विदलितैर्यवः यवैस्तु निस्तुषैः पक्वैः सौवीरं साधितं भवेत्","text":"tuṣāmbu sandhitaṃ jñeyamāmairvidalitairyavaḥ yavaistu nistuṣaiḥ pakvaiḥ sauvīraṃ sādhitaṃ bhavet"},{"type":"verse","number":"78","sanskrit":"आरनालन्तु गोधूमैरामैः स्यान्निस्तुस्तुषीकृतैः पक्वैर्वा संहितं तत्तु सौवीरसदृशं गुणैः","text":"āranālantu godhūmairāmaiḥ syānnistustuṣīkṛtaiḥ pakvairvā saṃhitaṃ tattu sauvīrasadṛśaṃ guṇaiḥ"},{"type":"verse","number":"79","sanskrit":"कुल्माषधान्यमण्डादिसहितं काञ्जिकं विदुः शिण्डाकी संहिता ज्ञेया मूलकैः सर्षपादिभिः","text":"kulmāṣadhānyamaṇḍādisahitaṃ kāñjikaṃ viduḥ śiṇḍākī saṃhitā jñeyā mūlakaiḥ sarṣapādibhiḥ"},{"type":"verse","number":"80","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे परिभाषादिप्रकरणे द्वितीयं भेषजविधानप्रकरणं समाप्तम् २","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe paribhāṣādiprakaraṇe dvitīyaṃ bheṣajavidhānaprakaraṇaṃ samāptam 2"}]},{"sthana":"Пурвакханда","number":8,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 3"},{"type":"verse","number":"1","sanskrit":"दाहे रक्तं सितं छेदे निकषे कुङ्कुमप्रभम् तारशुल्बोज्झितं स्निग्धं कोमलं गुरु हेम सत्","text":"dāhe raktaṃ sitaṃ chede nikaṣe kuṅkumaprabham tāraśulbojjhitaṃ snigdhaṃ komalaṃ guru hema sat"},{"type":"verse","number":"2","sanskrit":"तच्छेदे कठिनं रूक्षं विवर्णं समलं दलम् दाहे छेदे सितं श्वेतं कषे स्फुटं लघु त्यजेत्","text":"tacchede kaṭhinaṃ rūkṣaṃ vivarṇaṃ samalaṃ dalam dāhe chede sitaṃ śvetaṃ kaṣe sphuṭaṃ laghu tyajet"},{"type":"verse","number":"3","sanskrit":"पत्तलीकृतपत्राणि हेम्नो वह्नौ प्रतापयेत् निषिञ्चेत्तप्ततप्तानि तैले तक्रे च काञ्जिके","text":"pattalīkṛtapatrāṇi hemno vahnau pratāpayet niṣiñcettaptataptāni taile takre ca kāñjike"},{"type":"verse","number":"4","sanskrit":"गोमूत्रे च कुलत्थानां कषाये तु त्रिधा त्रिधा एवं हेम्नः परेषाञ्च धातूनां शोधनं भवेत्","text":"gomūtre ca kulatthānāṃ kaṣāye tu tridhā tridhā evaṃ hemnaḥ pareṣāñca dhātūnāṃ śodhanaṃ bhavet"},{"type":"verse","number":"5","sanskrit":"बलं सवीर्य्यं हरते नराणां रोगव्रजं पोषयतीह काये असौख्यकार्येव सदा सुवर्णमशुद्धमेतन्मरणञ्च कुर्यात्","text":"balaṃ savīryyaṃ harate narāṇāṃ rogavrajaṃ poṣayatīha kāye asaukhyakāryeva sadā suvarṇamaśuddhametanmaraṇañca kuryāt"},{"type":"verse","number":"6","sanskrit":"स्वर्णस्य द्विगुणं सूतमम्लेन सह मर्दयेत् तद्गोलकसमं गन्धं निदध्यादधरोत्तरम्","text":"svarṇasya dviguṇaṃ sūtamamlena saha mardayet tadgolakasamaṃ gandhaṃ nidadhyādadharottaram"},{"type":"verse","number":"7","sanskrit":"गोलकञ्च ततो रुद्ध्वा शरावदृढसम्पुटे त्रिंशद्वनोपलैर्दद्यात्पुटान्येवं चतुर्दश निरुत्थं जायते भस्म गन्धो देयः पुनः पुनः","text":"golakañca tato ruddhvā śarāvadṛḍhasampuṭe triṃśadvanopalairdadyātpuṭānyevaṃ caturdaśa nirutthaṃ jāyate bhasma gandho deyaḥ punaḥ punaḥ"},{"type":"verse","number":"8","sanskrit":"काञ्चने गलिते नागं षोडशांशेन निक्षिपेत् चूर्णयित्वा तथाम्लेन घृष्ट्वा कृत्वा तु गोलकम्","text":"kāñcane galite nāgaṃ ṣoḍaśāṃśena nikṣipet cūrṇayitvā tathāmlena ghṛṣṭvā kṛtvā tu golakam"},{"type":"verse","number":"9","sanskrit":"गोलकेन समं गन्धं दत्त्वा चैवाधरोत्तरम्","text":"golakena samaṃ gandhaṃ dattvā caivādharottaram"},{"type":"verse","number":"10","sanskrit":"शरावसम्पुटे धृत्वा पुटेत् त्रिंशद्वनोपलैः एवं सप्तपुटैर्हेम निरुत्थं भस्म जायते","text":"śarāvasampuṭe dhṛtvā puṭet triṃśadvanopalaiḥ evaṃ saptapuṭairhema nirutthaṃ bhasma jāyate"},{"type":"verse","number":"11","sanskrit":"काञ्चनाररसैर्घृष्ट्वा समसूतकगन्धयोः कज्जलद्यं हेमपत्राणि लेपयेत्समया तथा","text":"kāñcanārarasairghṛṣṭvā samasūtakagandhayoḥ kajjaladyaṃ hemapatrāṇi lepayetsamayā tathā"},{"type":"verse","number":"12","sanskrit":"काञ्चनारत्वचः कल्कैर्मूषायुग्मं प्रकल्पयेत् धृत्वा तत्संपुटे गोलं मृण्मूषासम्पुटे च तत्","text":"kāñcanāratvacaḥ kalkairmūṣāyugmaṃ prakalpayet dhṛtvā tatsaṃpuṭe golaṃ mṛṇmūṣāsampuṭe ca tat"},{"type":"verse","number":"13","sanskrit":"निधाय सन्धिरोधं च कृत्वा संशोष्य गोलकम् वह्निं खरतरं कुर्यादेवं दत्त्वा पुटत्रयम्","text":"nidhāya sandhirodhaṃ ca kṛtvā saṃśoṣya golakam vahniṃ kharataraṃ kuryādevaṃ dattvā puṭatrayam"},{"type":"verse","number":"14","sanskrit":"निरुत्थं जायते भस्म सर्वकर्मसु योजयेत् काञ्चनारप्रकारेण लाङ्गली हन्ति काञ्चनम्","text":"nirutthaṃ jāyate bhasma sarvakarmasu yojayet kāñcanāraprakāreṇa lāṅgalī hanti kāñcanam"},{"type":"verse","number":"15","sanskrit":"ज्वालामुखी तथा हन्याद् यथा हन्ति मनःशिला","text":"jvālāmukhī tathā hanyād yathā hanti manaḥśilā"},{"type":"verse","number":"16","sanskrit":"शिलासिन्दूरयोश्चूर्णं समयोरर्कदुग्धकैः सप्तधा भावनां दद्याच्छोषयेच्च पुनः पुनः","text":"śilāsindūrayoścūrṇaṃ samayorarkadugdhakaiḥ saptadhā bhāvanāṃ dadyācchoṣayecca punaḥ punaḥ"},{"type":"verse","number":"17","sanskrit":"ततस्तु गलिते हेम्नि कल्कोऽय दीयते समः पुनर्धमेदतितरां यथा कल्को विलीयते एवं वेलात्रयं दद्यात्कल्कं हेममृतिर्भवेत्","text":"tatastu galite hemni kalko'ya dīyate samaḥ punardhamedatitarāṃ yathā kalko vilīyate evaṃ velātrayaṃ dadyātkalkaṃ hemamṛtirbhavet"},{"type":"verse","number":"18","sanskrit":"सुवर्णं शीतलं वृष्यं बल्यं गुरु रसायनम् स्वादु तिक्तं च तुवरं पाके च स्वादु पिच्छिलम्","text":"suvarṇaṃ śītalaṃ vṛṣyaṃ balyaṃ guru rasāyanam svādu tiktaṃ ca tuvaraṃ pāke ca svādu picchilam"},{"type":"verse","number":"19","sanskrit":"पवित्रं बृंहणं नेत्र्! यं मेधास्मृतिमतिप्रदम् हृद्यामायुष्करं कान्तिवाग्विशुद्धिस्थिरत्वकृत् विषद्वयक्षयोन्मादत्रिदोषज्वरशोषजित्","text":"pavitraṃ bṛṃhaṇaṃ netr! yaṃ medhāsmṛtimatipradam hṛdyāmāyuṣkaraṃ kāntivāgviśuddhisthiratvakṛt viṣadvayakṣayonmādatridoṣajvaraśoṣajit"},{"type":"verse","number":"20","sanskrit":"असम्यङ्मारितं स्वर्णं बलं वीर्यं च नाशयेत् करोति रोगान् मृत्युं च तद्धन्याद् यत्नतस्ततः","text":"asamyaṅmāritaṃ svarṇaṃ balaṃ vīryaṃ ca nāśayet karoti rogān mṛtyuṃ ca taddhanyād yatnatastataḥ"},{"type":"verse","number":"21","sanskrit":"लोहादेरनपुनर्भावस्तद्गुणत्वं गुणाढ्यता सलिले तरणं चापि तत्सिद्धिः पुटनाद्भवेत्","text":"lohāderanapunarbhāvastadguṇatvaṃ guṇāḍhyatā salile taraṇaṃ cāpi tatsiddhiḥ puṭanādbhavet"},{"type":"verse","number":"22","sanskrit":"गम्भीरे विस्तृते कुण्डे द्विहस्ते चतुरस्रके वनोपलसहस्रेण पूरिते पुटनौषधम्","text":"gambhīre vistṛte kuṇḍe dvihaste caturasrake vanopalasahasreṇa pūrite puṭanauṣadham"},{"type":"verse","number":"23","sanskrit":"कोष्ठे रुद्धं प्रयत्नेन गोविष्ठोपरि धारयेत् वनोपलसहस्रार्द्धं कोष्ठिकोपरि निक्षिपेत्","text":"koṣṭhe ruddhaṃ prayatnena goviṣṭhopari dhārayet vanopalasahasrārddhaṃ koṣṭhikopari nikṣipet"},{"type":"verse","number":"24","sanskrit":"वह्निं विनिक्षिपेत्तत्र महापुटमिति स्मृतम्","text":"vahniṃ vinikṣipettatra mahāpuṭamiti smṛtam"},{"type":"verse","number":"25","sanskrit":"सपादहस्तमानेन कुण्डे निम्ने तथाऽयते वनोपलसहस्रेण पूर्णे मध्ये विधारयेत्","text":"sapādahastamānena kuṇḍe nimne tathā'yate vanopalasahasreṇa pūrṇe madhye vidhārayet"},{"type":"verse","number":"26","sanskrit":"पुटनद्र व्यसंयुक्तां कोष्टिकां मुद्रि तां मुखे अधोऽधानि करण्डानि अर्धान्युपरि निक्षिपेत् एतद्गजपुटं प्रोक्तं ख्यातं सर्वपुटोत्तमम्","text":"puṭanadra vyasaṃyuktāṃ koṣṭikāṃ mudri tāṃ mukhe adho'dhāni karaṇḍāni ardhānyupari nikṣipet etadgajapuṭaṃ proktaṃ khyātaṃ sarvapuṭottamam"},{"type":"verse","number":"27","sanskrit":"अरत्निमात्रके कुण्डे पुटं वाराहमुच्यते वितस्तिमात्रके खाते कथितं कौक्कुटं पुटम्","text":"aratnimātrake kuṇḍe puṭaṃ vārāhamucyate vitastimātrake khāte kathitaṃ kaukkuṭaṃ puṭam"},{"type":"verse","number":"28","sanskrit":"षोडशाङ्गुलके खाते कस्यचित्कौक्कुटं पुटम्","text":"ṣoḍaśāṅgulake khāte kasyacitkaukkuṭaṃ puṭam"},{"type":"verse","number":"29","sanskrit":"यत्पुटं दीयते खाते ह्यष्टसंख्यैर्वनोपलैः कपोतपुटमेतत्तु कथितं पुटपण्डितैः","text":"yatpuṭaṃ dīyate khāte hyaṣṭasaṃkhyairvanopalaiḥ kapotapuṭametattu kathitaṃ puṭapaṇḍitaiḥ"},{"type":"verse","number":"30","sanskrit":"गोष्ठान्तर्गोखुरक्षुण्णं शुष्कं चूर्णितगोमयम् गोबरं तत्समाख्यातं वरिष्ठं रससाधने","text":"goṣṭhāntargokhurakṣuṇṇaṃ śuṣkaṃ cūrṇitagomayam gobaraṃ tatsamākhyātaṃ variṣṭhaṃ rasasādhane"},{"type":"verse","number":"31","sanskrit":"बृहद्भाण्डस्थितैर्यत्र गौबरैर्दीयते पुटम् तद् गोबरपुटं प्रोक्तं भिषग्भिः सूतभस्मनि","text":"bṛhadbhāṇḍasthitairyatra gaubarairdīyate puṭam tad gobarapuṭaṃ proktaṃ bhiṣagbhiḥ sūtabhasmani"},{"type":"verse","number":"32","sanskrit":"बृहद्भाण्डे तुषैः पूर्णे मध्ये मूषां विधारयेत् क्षिप्त्वाऽग्नि मुद्र येद्भाण्डं तद्भाण्डपुटमुच्यते","text":"bṛhadbhāṇḍe tuṣaiḥ pūrṇe madhye mūṣāṃ vidhārayet kṣiptvā'gni mudra yedbhāṇḍaṃ tadbhāṇḍapuṭamucyate"},{"type":"verse","number":"33","sanskrit":"भाण्डे वितस्तिगम्भीरे मध्ये निहितकूपिके कूपिकाकण्ठपर्यन्तं वालुकाभिश्च पूरिते","text":"bhāṇḍe vitastigambhīre madhye nihitakūpike kūpikākaṇṭhaparyantaṃ vālukābhiśca pūrite"},{"type":"verse","number":"34","sanskrit":"भेषजं कूपिकासंस्थं वह्निना यत्र पच्यते बालुकायन्त्रमेतद्धि यन्त्रं तत्र बुधैः स्मृतम्","text":"bheṣajaṃ kūpikāsaṃsthaṃ vahninā yatra pacyate bālukāyantrametaddhi yantraṃ tatra budhaiḥ smṛtam"},{"type":"verse","number":"35","sanskrit":"निबद्धमौषधं सूतं भूर्जे तत्त्रिगुणे वरे रसपोटलिकां काष्ठे दृढं बद्ध्वा गुणेन हि","text":"nibaddhamauṣadhaṃ sūtaṃ bhūrje tattriguṇe vare rasapoṭalikāṃ kāṣṭhe dṛḍhaṃ baddhvā guṇena hi"},{"type":"verse","number":"36","sanskrit":"सन्धानपूर्णकुम्भान्तःस्वावलम्बनसन्धितम् अधस्ताज्ज्वालयेदग्निं तत्तदुक्तक्रमेण हि दोलायन्त्रमिदं प्रोक्तं स्वेदनाख्यं तदेव हि","text":"sandhānapūrṇakumbhāntaḥsvāvalambanasandhitam adhastājjvālayedagniṃ tattaduktakrameṇa hi dolāyantramidaṃ proktaṃ svedanākhyaṃ tadeva hi"},{"type":"verse","number":"37","sanskrit":"साम्बुस्थालीमुखे बद्धे वस्त्रे स्वेद्यं निधाय च पिधाय पच्यते तत्र तद् यन्त्रं स्वेदनं स्मृतम्","text":"sāmbusthālīmukhe baddhe vastre svedyaṃ nidhāya ca pidhāya pacyate tatra tad yantraṃ svedanaṃ smṛtam"},{"type":"verse","number":"38","sanskrit":"अधःस्थाल्यां रसं क्षिप्त्वा विदध्यात्तन्मुखोपरि स्थालीमूर्ध्वमुखीं सम्यङ्निरुध्य मृदुमृत्स्नया","text":"adhaḥsthālyāṃ rasaṃ kṣiptvā vidadhyāttanmukhopari sthālīmūrdhvamukhīṃ samyaṅnirudhya mṛdumṛtsnayā"},{"type":"verse","number":"39","sanskrit":"ऊर्ध्वस्थाल्यां जलं क्षिप्त्वा चुल्ल्यामारोप्य यत्नतः अधस्ताज्ज्वालयेदग्निं यावत्प्रहरपञ्चकम्","text":"ūrdhvasthālyāṃ jalaṃ kṣiptvā cullyāmāropya yatnataḥ adhastājjvālayedagniṃ yāvatpraharapañcakam"},{"type":"verse","number":"40","sanskrit":"स्वाङ्गशीतं ततो यन्त्राद् गृह्णीयाद्र समुत्तमम् विद्याधराभिधं यन्त्रमेतत्तज्ज्ञैरुदाहृतम्","text":"svāṅgaśītaṃ tato yantrād gṛhṇīyādra samuttamam vidyādharābhidhaṃ yantrametattajjñairudāhṛtam"},{"type":"verse","number":"41","sanskrit":"बालुकाभिः समस्ताङ्गं गर्त्ते मूषां रसान्विताम् दीप्तोपलैः संवृणुयाद् यन्त्रं भूधरनामकम्","text":"bālukābhiḥ samastāṅgaṃ gartte mūṣāṃ rasānvitām dīptopalaiḥ saṃvṛṇuyād yantraṃ bhūdharanāmakam"},{"type":"verse","number":"42","sanskrit":"यन्त्रं डमरुसंज्ञं स्यात्तत्स्थाल्या मुद्रि ते मुखे","text":"yantraṃ ḍamarusaṃjñaṃ syāttatsthālyā mudri te mukhe"},{"type":"verse","number":"43","sanskrit":"गुरु स्निग्धं मृदु श्वेतं दाहे छेदे घनक्षमम् वर्णाढ्यं चन्द्र वत् स्वच्छं तारं नवगुणं शुभम्","text":"guru snigdhaṃ mṛdu śvetaṃ dāhe chede ghanakṣamam varṇāḍhyaṃ candra vat svacchaṃ tāraṃ navaguṇaṃ śubham"},{"type":"verse","number":"44","sanskrit":"कठिनं कृत्रिमं रूक्षं रक्तं पीतदलं लघु दाहच्छेदघनैर्नष्टं रूप्यं दुष्टं प्रकीर्त्तितम्","text":"kaṭhinaṃ kṛtrimaṃ rūkṣaṃ raktaṃ pītadalaṃ laghu dāhacchedaghanairnaṣṭaṃ rūpyaṃ duṣṭaṃ prakīrttitam"},{"type":"verse","number":"45","sanskrit":"पत्तलीकृतपत्राणि तारस्याग्नौ प्रतापयेत् निषिञ्चेत्तप्ततप्तानि तैले तक्रे च काञ्जिके","text":"pattalīkṛtapatrāṇi tārasyāgnau pratāpayet niṣiñcettaptataptāni taile takre ca kāñjike"},{"type":"verse","number":"46","sanskrit":"गोमूत्रे च कुलत्थानां कषाये च त्रिधा त्रिधा एवं रजतपत्राणां विशुद्धिः संप्रजायते","text":"gomūtre ca kulatthānāṃ kaṣāye ca tridhā tridhā evaṃ rajatapatrāṇāṃ viśuddhiḥ saṃprajāyate"},{"type":"verse","number":"47","sanskrit":"रूप्यं त्वशुद्धं प्रकरोति तापं विबन्धकं वीर्यबलक्षयं च देहस्य पुष्टिं हरते तनोति रोगांस्ततः शोधनमस्य कुर्यात्","text":"rūpyaṃ tvaśuddhaṃ prakaroti tāpaṃ vibandhakaṃ vīryabalakṣayaṃ ca dehasya puṣṭiṃ harate tanoti rogāṃstataḥ śodhanamasya kuryāt"},{"type":"verse","number":"48","sanskrit":"भागैकं तालकं मर्द्यं याममम्लेन केनचित् तेन भागत्रयं तारपत्त्राणि परिलेपयेत्","text":"bhāgaikaṃ tālakaṃ mardyaṃ yāmamamlena kenacit tena bhāgatrayaṃ tārapattrāṇi parilepayet"},{"type":"verse","number":"49","sanskrit":"धृत्वा मूषापुटे रुद्ध्वा पुटेत्त्रिंशद्वनोपलैः समुद्धृत्य पुनस्तालं दत्त्वा रुद्ध्वा पुटे पचेत् एवं चतुर्दशपुटैस्तारं भस्म प्रजायते","text":"dhṛtvā mūṣāpuṭe ruddhvā puṭettriṃśadvanopalaiḥ samuddhṛtya punastālaṃ dattvā ruddhvā puṭe pacet evaṃ caturdaśapuṭaistāraṃ bhasma prajāyate"},{"type":"verse","number":"50","sanskrit":"स्नुहीक्षीरेण सम्पिष्टं माक्षिकं तेन लेपयेत्","text":"snuhīkṣīreṇa sampiṣṭaṃ mākṣikaṃ tena lepayet"},{"type":"verse","number":"51","sanskrit":"तालकस्य प्रकारेण तारपत्राणि बुद्धिमान् पुटेच्चतुर्दशपुटैस्तारं भस्म प्रजायते","text":"tālakasya prakāreṇa tārapatrāṇi buddhimān puṭeccaturdaśapuṭaistāraṃ bhasma prajāyate"},{"type":"verse","number":"52","sanskrit":"रौप्यं शीतं कषायं च स्वादुपाकरसं सरम् वयसः स्थापनं स्निग्धं लेखनं वातपित्तजित् प्रमेहादिकरोगांश्च नाशयत्यचिराद्र् ध्रुवम्","text":"raupyaṃ śītaṃ kaṣāyaṃ ca svādupākarasaṃ saram vayasaḥ sthāpanaṃ snigdhaṃ lekhanaṃ vātapittajit pramehādikarogāṃśca nāśayatyacirādr dhruvam"},{"type":"verse","number":"53","sanskrit":"जपाकुसुमसङ्काशं स्निग्धं गुरु घनक्षमम् लोहनागोज्झितं ताम्रं मारणाय प्रशस्यते","text":"japākusumasaṅkāśaṃ snigdhaṃ guru ghanakṣamam lohanāgojjhitaṃ tāmraṃ māraṇāya praśasyate"},{"type":"verse","number":"54","sanskrit":"कृष्णं रूक्षमतिस्वच्छं श्वेतं चापि घनासहम् लोहनागयुतं चेति शुल्वं दुष्टं प्रकीर्त्तितम्","text":"kṛṣṇaṃ rūkṣamatisvacchaṃ śvetaṃ cāpi ghanāsaham lohanāgayutaṃ ceti śulvaṃ duṣṭaṃ prakīrttitam"},{"type":"verse","number":"55","sanskrit":"पत्तलीकृतपत्राणि ताम्रस्याग्नौ प्रतापयेत् निषिञ्चेत्तप्ततप्तानि तैले तक्रे च काञ्जिके","text":"pattalīkṛtapatrāṇi tāmrasyāgnau pratāpayet niṣiñcettaptataptāni taile takre ca kāñjike"},{"type":"verse","number":"56","sanskrit":"गोमूत्रे च कुलत्थानां कषाये च त्रिधा त्रिधा एवं ताम्रस्य पत्राणां विशुद्धिः संप्रजायते","text":"gomūtre ca kulatthānāṃ kaṣāye ca tridhā tridhā evaṃ tāmrasya patrāṇāṃ viśuddhiḥ saṃprajāyate"},{"type":"verse","number":"57","sanskrit":"एको दोषो विषे ताम्रे त्वशुद्धेऽष्टौ भ्रमो वमिः विरेकस्वेद उत्क्लेदो मूर्च्छा दाहोऽरुचिस्तथा","text":"eko doṣo viṣe tāmre tvaśuddhe'ṣṭau bhramo vamiḥ virekasveda utkledo mūrcchā dāho'rucistathā"},{"type":"verse","number":"58","sanskrit":"न विषं विषमित्याहुस्ताम्रन्तु विषमुच्यते एको दोषो विषे ताम्रे त्वष्टौ दोषाः प्रकीर्त्तिताः","text":"na viṣaṃ viṣamityāhustāmrantu viṣamucyate eko doṣo viṣe tāmre tvaṣṭau doṣāḥ prakīrttitāḥ"},{"type":"verse","number":"59","sanskrit":"सूक्ष्माणि ताम्रपत्राणि कृत्वा संस्वेदयेद् बुधः वासरत्रयमम्लेन ततः खल्वे विनिक्षिपेत्","text":"sūkṣmāṇi tāmrapatrāṇi kṛtvā saṃsvedayed budhaḥ vāsaratrayamamlena tataḥ khalve vinikṣipet"},{"type":"verse","number":"60","sanskrit":"पादांशं सूतकं दत्त्वा याममम्लेन मर्दयेत् ततः उद्धृत्य पत्राणि लेपयेद् द्विगुणेन च","text":"pādāṃśaṃ sūtakaṃ dattvā yāmamamlena mardayet tataḥ uddhṛtya patrāṇi lepayed dviguṇena ca"},{"type":"verse","number":"61","sanskrit":"गन्धकेनाम्लघृष्टेन तस्य कुर्याच्च गोलकम् ततः पिष्ट्वा च मीनाक्षीं चाङ्गेरीं वा पुनर्नवाम्","text":"gandhakenāmlaghṛṣṭena tasya kuryācca golakam tataḥ piṣṭvā ca mīnākṣīṃ cāṅgerīṃ vā punarnavām"},{"type":"verse","number":"62","sanskrit":"तत्कल्केन बहिर्गोलं लेपयेद्द्व्यङ्गुलोन्मितम् धृत्वा तद् गोलकं भाण्डे शरावेण च रोधयेत्","text":"tatkalkena bahirgolaṃ lepayeddvyaṅgulonmitam dhṛtvā tad golakaṃ bhāṇḍe śarāveṇa ca rodhayet"},{"type":"verse","number":"63","sanskrit":"बालुकाभिः प्रपूर्याथ विभूतिलवणाम्बुभिः दत्वा भाण्डमुखे मुद्रां ततश्चुल्ल्यां विपाचयेत्","text":"bālukābhiḥ prapūryātha vibhūtilavaṇāmbubhiḥ datvā bhāṇḍamukhe mudrāṃ tataścullyāṃ vipācayet"},{"type":"verse","number":"64","sanskrit":"क्रमवृद्ध्याऽग्निना सम्यग्यावद्यामचतुष्टयम् स्वाङ्गशीतं समुद्धृत्य मर्दयेच्छूरणद्र वैः","text":"kramavṛddhyā'gninā samyagyāvadyāmacatuṣṭayam svāṅgaśītaṃ samuddhṛtya mardayecchūraṇadra vaiḥ"},{"type":"verse","number":"65","sanskrit":"यामैकं गोलकं तच्च विक्षिपेच्छूरणोदरे मृदा लेपस्तु कर्त्तव्यः सर्वतोऽङ्गुष्ठमात्रकः","text":"yāmaikaṃ golakaṃ tacca vikṣipecchūraṇodare mṛdā lepastu karttavyaḥ sarvato'ṅguṣṭhamātrakaḥ"},{"type":"verse","number":"66","sanskrit":"पाच्यं गजपुटे क्षिप्तं मृतं भवति निश्चितम्","text":"pācyaṃ gajapuṭe kṣiptaṃ mṛtaṃ bhavati niścitam"},{"type":"verse","number":"67","sanskrit":"वमनं च विरेकं च भ्रमं क्लममथारुचिम् विदाहं स्वेदमुत्क्लेदं न करोति कदाचन","text":"vamanaṃ ca virekaṃ ca bhramaṃ klamamathārucim vidāhaṃ svedamutkledaṃ na karoti kadācana"},{"type":"verse","number":"68","sanskrit":"ताम्रं कषायं मधुरं सतिक्तमम्लञ्च पाके कटु सारकं च पित्तापहं श्लेष्महरं च शीतं तद्रो पणं स्याल्लघु लेखनं च","text":"tāmraṃ kaṣāyaṃ madhuraṃ satiktamamlañca pāke kaṭu sārakaṃ ca pittāpahaṃ śleṣmaharaṃ ca śītaṃ tadro paṇaṃ syāllaghu lekhanaṃ ca"},{"type":"verse","number":"69","sanskrit":"पाण्डूदरार्शोज्वरकुष्ठकासश्वासक्षयान्पीनसमम्लपित्तम् शोथं कृमीञ्शूलमपाकरोति प्राहुर्बुधा बृंहणमल्पमेतत्","text":"pāṇḍūdarārśojvarakuṣṭhakāsaśvāsakṣayānpīnasamamlapittam śothaṃ kṛmīñśūlamapākaroti prāhurbudhā bṛṃhaṇamalpametat"},{"type":"verse","number":"70","sanskrit":"एको दोषो विषे ताम्रे त्वसम्यङ्मारिते पुनः दाहः स्वेदोऽरुचिर्मूर्च्छोत्क्लेदो रेको वमिर्भ्रमः","text":"eko doṣo viṣe tāmre tvasamyaṅmārite punaḥ dāhaḥ svedo'rucirmūrcchotkledo reko vamirbhramaḥ"},{"type":"verse","number":"71","sanskrit":"वङ्गं च गिरिजं तच्च खुरकं मिश्रकं द्विधा तयोस्तु खुरकं श्रेष्ठं मिश्रकं त्वहितं मतम्","text":"vaṅgaṃ ca girijaṃ tacca khurakaṃ miśrakaṃ dvidhā tayostu khurakaṃ śreṣṭhaṃ miśrakaṃ tvahitaṃ matam"},{"type":"verse","number":"72","sanskrit":"वङ्गं विधत्ते खलु शुद्धिहीनमाक्षेपकम्पौ च किलासगुल्मौ कुष्ठानि शूलं किल वातशोथं पाण्डुं प्रमेहञ्च भगन्दरञ्च","text":"vaṅgaṃ vidhatte khalu śuddhihīnamākṣepakampau ca kilāsagulmau kuṣṭhāni śūlaṃ kila vātaśothaṃ pāṇḍuṃ pramehañca bhagandarañca"},{"type":"verse","number":"73","sanskrit":"विषोपमं रक्तविकारवृन्दं क्षयञ्च कृच्छ्राणि कफज्चरञ्च मेहाश्मरीविद्र धिमुष्करोगान् नागोऽपि कुर्यात्कथितान्विकारान्","text":"viṣopamaṃ raktavikāravṛndaṃ kṣayañca kṛcchrāṇi kaphajcarañca mehāśmarīvidra dhimuṣkarogān nāgo'pi kuryātkathitānvikārān"},{"type":"verse","number":"74","sanskrit":"वङ्गनागौ प्रतप्तौ च गलितौ तौ निषेचयेत् त्रिधा त्रिधा विशुद्धिः स्याद्र विदुग्धेऽपि च त्रिधा","text":"vaṅganāgau prataptau ca galitau tau niṣecayet tridhā tridhā viśuddhiḥ syādra vidugdhe'pi ca tridhā"},{"type":"verse","number":"75","sanskrit":"मृत्पात्रे द्रा विते वङ्गे चिञ्चाऽश्वत्थत्वचो रजः पिष्ट्वा वङ्गचतुर्थांशमथोदर्व्या प्रचालयेत्","text":"mṛtpātre drā vite vaṅge ciñcā'śvatthatvaco rajaḥ piṣṭvā vaṅgacaturthāṃśamathodarvyā pracālayet"},{"type":"verse","number":"76","sanskrit":"ततो द्वियाममात्रेण वङ्गं भस्म प्रजायते अथ भस्मसमं तालं क्षिप्त्वाऽम्लेन विमर्दयेत्","text":"tato dviyāmamātreṇa vaṅgaṃ bhasma prajāyate atha bhasmasamaṃ tālaṃ kṣiptvā'mlena vimardayet"},{"type":"verse","number":"77","sanskrit":"ततो गजपुटे पक्त्वा पुनरम्लेन मर्दयेत् तालेन दशमांशेन याममेकं ततः पुटेत् एवं दशपुटैः पक्वं वङ्गं भवति मारितम्","text":"tato gajapuṭe paktvā punaramlena mardayet tālena daśamāṃśena yāmamekaṃ tataḥ puṭet evaṃ daśapuṭaiḥ pakvaṃ vaṅgaṃ bhavati māritam"},{"type":"verse","number":"78","sanskrit":"वङ्गं लघु सरं रूक्षं कुष्ठं मेहकफकृमीन् निहन्ति पाण्डुं सश्वासं नेत्र्! यमीषत्तु पित्तलम्","text":"vaṅgaṃ laghu saraṃ rūkṣaṃ kuṣṭhaṃ mehakaphakṛmīn nihanti pāṇḍuṃ saśvāsaṃ netr! yamīṣattu pittalam"},{"type":"verse","number":"79","sanskrit":"सिंहो गजौघं तु यथा निहन्ति तथैव वङ्गोऽखिलमेहवर्गम् देहस्य सौख्यं प्रबलेन्द्रि यत्वं नरस्य पुष्टिं विदधाति नूनम्","text":"siṃho gajaughaṃ tu yathā nihanti tathaiva vaṅgo'khilamehavargam dehasya saukhyaṃ prabalendri yatvaṃ narasya puṣṭiṃ vidadhāti nūnam"},{"type":"verse","number":"80","sanskrit":"यशदं गिरिजं तस्य दोषाः शोधनमारणे वङ्गस्येव हि बोद्धव्या गुणांस्तु गणयाम्यथ","text":"yaśadaṃ girijaṃ tasya doṣāḥ śodhanamāraṇe vaṅgasyeva hi boddhavyā guṇāṃstu gaṇayāmyatha"},{"type":"verse","number":"81","sanskrit":"यशदं च सरं तिक्तं शीतलं कफपित्तहृत् चक्षुष्यं परमं मेहान् पाण्डुं श्वासञ्च नाशयेत्","text":"yaśadaṃ ca saraṃ tiktaṃ śītalaṃ kaphapittahṛt cakṣuṣyaṃ paramaṃ mehān pāṇḍuṃ śvāsañca nāśayet"},{"type":"verse","number":"82","sanskrit":"तस्य साहजिका दोषा वङ्गस्येव निदर्शिताः शोधनञ्चापि तस्येव भिषग्भिर्गदितं पुरा","text":"tasya sāhajikā doṣā vaṅgasyeva nidarśitāḥ śodhanañcāpi tasyeva bhiṣagbhirgaditaṃ purā"},{"type":"verse","number":"83","sanskrit":"ताम्बूलरससम्पिष्टं शिलालेपात् पुनः पुनः द्वात्रिंशद्भिः पुटैर्नागो निरुत्थं भस्म जायते","text":"tāmbūlarasasampiṣṭaṃ śilālepāt punaḥ punaḥ dvātriṃśadbhiḥ puṭairnāgo nirutthaṃ bhasma jāyate"},{"type":"verse","number":"84","sanskrit":"अश्वत्थचिञ्चात्वक्चूर्णं चतुर्थांशेन निक्षिपेत् मृत्पात्रे विद्रुतो नागो लोहदर्व्या प्रचालितः","text":"aśvatthaciñcātvakcūrṇaṃ caturthāṃśena nikṣipet mṛtpātre vidruto nāgo lohadarvyā pracālitaḥ"},{"type":"verse","number":"85","sanskrit":"यामैकेन भवेद्भस्म तत्तुल्या स्यान्मनःशिला काञ्जिकेन द्वयं पिष्ट्वा पचेद्गजपुटेन च","text":"yāmaikena bhavedbhasma tattulyā syānmanaḥśilā kāñjikena dvayaṃ piṣṭvā pacedgajapuṭena ca"},{"type":"verse","number":"86","sanskrit":"स्वाङ्गशीतं पुनः पिष्ट्वा शिलया काञ्जिकेन च पुनः पचेच्छरावाभ्यामेवं षष्टिपुटैर्मृतिः","text":"svāṅgaśītaṃ punaḥ piṣṭvā śilayā kāñjikena ca punaḥ paceccharāvābhyāmevaṃ ṣaṣṭipuṭairmṛtiḥ"},{"type":"verse","number":"87","sanskrit":"सीसं वङ्गगुणं ज्ञेयं विशेषान्मेहनाशनम्","text":"sīsaṃ vaṅgaguṇaṃ jñeyaṃ viśeṣānmehanāśanam"},{"type":"verse","number":"88","sanskrit":"नागस्तु नागशततुल्यबलं ददाति व्याधिं च नाशयति जीवनमातनोति वह्निं प्रदीपयति कामबलं करोति मृत्युञ्च नाशयति सन्ततसेवितः सः","text":"nāgastu nāgaśatatulyabalaṃ dadāti vyādhiṃ ca nāśayati jīvanamātanoti vahniṃ pradīpayati kāmabalaṃ karoti mṛtyuñca nāśayati santatasevitaḥ saḥ"},{"type":"verse","number":"89","sanskrit":"खञ्जत्वकुष्ठामयमृत्युकारी हृद्रो गशूलौ कुरुतेऽश्मरीञ्च नानारुजानां च तथा प्रकोपं कुर्याच्च हृल्लासमशुद्धलौहम्","text":"khañjatvakuṣṭhāmayamṛtyukārī hṛdro gaśūlau kurute'śmarīñca nānārujānāṃ ca tathā prakopaṃ kuryācca hṛllāsamaśuddhalauham"},{"type":"verse","number":"90","sanskrit":"पत्तलीकृतपत्राणि लौहस्याग्नौ प्रतापयेत् निषिञ्चेत्तप्ततप्तानि तैले तक्रे च काञ्जिके","text":"pattalīkṛtapatrāṇi lauhasyāgnau pratāpayet niṣiñcettaptataptāni taile takre ca kāñjike"},{"type":"verse","number":"91","sanskrit":"गोमूत्रे च कुलत्थानां कषाये च त्रिधा त्रिधा एवं लौहस्य पत्राणां विशुद्धिः संप्रजायते","text":"gomūtre ca kulatthānāṃ kaṣāye ca tridhā tridhā evaṃ lauhasya patrāṇāṃ viśuddhiḥ saṃprajāyate"},{"type":"verse","number":"92","sanskrit":"शुद्धं लौहभवं चूर्णं पातालगरुडीरसैः मर्दयित्वा पुटेद्वह्नौ दद्यादेवं पुटत्रयम्","text":"śuddhaṃ lauhabhavaṃ cūrṇaṃ pātālagaruḍīrasaiḥ mardayitvā puṭedvahnau dadyādevaṃ puṭatrayam"},{"type":"verse","number":"93","sanskrit":"पुटत्रयं कुमार्याश्च कुठारच्छिन्निकिरसैः पुटषट्कं ततो दद्यादेवं तीक्ष्णमृतिर्भवेत्","text":"puṭatrayaṃ kumāryāśca kuṭhāracchinnikirasaiḥ puṭaṣaṭkaṃ tato dadyādevaṃ tīkṣṇamṛtirbhavet"},{"type":"verse","number":"94","sanskrit":"क्षिपेच्च द्वादशांशेन दरदं तीक्ष्णचूर्णतः मर्दयेत्कन्यकाद्रा वैर्यामयुग्मं ततः पुटेत् एवं सप्तपुटैर्मृत्युं लौहचूर्णमवाप्नुयात्","text":"kṣipecca dvādaśāṃśena daradaṃ tīkṣṇacūrṇataḥ mardayetkanyakādrā vairyāmayugmaṃ tataḥ puṭet evaṃ saptapuṭairmṛtyuṃ lauhacūrṇamavāpnuyāt"},{"type":"verse","number":"95","sanskrit":"सत्योऽनुभूतो योगेन्द्रै ः! क्रमोऽन्यो लौहमारणे कथ्यते रामराजेन कौतूहलधियाऽधुना","text":"satyo'nubhūto yogendrai ḥ! kramo'nyo lauhamāraṇe kathyate rāmarājena kautūhaladhiyā'dhunā"},{"type":"verse","number":"96","sanskrit":"सूतकाद् द्विगुणं गन्धं दत्त्वा कुर्याच्च कज्जलीम् द्वयोः समं लौहचूर्णं मर्दयेत्कन्यकाद्र वैः","text":"sūtakād dviguṇaṃ gandhaṃ dattvā kuryācca kajjalīm dvayoḥ samaṃ lauhacūrṇaṃ mardayetkanyakādra vaiḥ"},{"type":"verse","number":"97","sanskrit":"यामयुग्मं ततः पिण्डं कृत्वा ताम्रस्य पात्रके घर्मे धृत्वा रुबूकस्य पत्रैराच्छादयेद्बुधः","text":"yāmayugmaṃ tataḥ piṇḍaṃ kṛtvā tāmrasya pātrake gharme dhṛtvā rubūkasya patrairācchādayedbudhaḥ"},{"type":"verse","number":"98","sanskrit":"यामत्रयाद्भवेदुष्णं धान्यराशौ न्यसेत्ततः दत्त्वोपरि शरावं तु त्रिदिनान्ते समुद्धरेत्","text":"yāmatrayādbhaveduṣṇaṃ dhānyarāśau nyasettataḥ dattvopari śarāvaṃ tu tridinānte samuddharet"},{"type":"verse","number":"99","sanskrit":"पिष्ट्वा च गालयेद्वस्त्रादेवं वारितरं भवेत् दाडिमस्य दलं पिष्ट्वा तच्चतुर्गुणवारिणा","text":"piṣṭvā ca gālayedvastrādevaṃ vāritaraṃ bhavet dāḍimasya dalaṃ piṣṭvā taccaturguṇavāriṇā"},{"type":"verse","number":"100","sanskrit":"तद्र सेनायसं चूर्णं सन्नीय प्लावयेदिति आतपे शोषयेत्तच्च पुटेदेवं पुनः पुनः","text":"tadra senāyasaṃ cūrṇaṃ sannīya plāvayediti ātape śoṣayettacca puṭedevaṃ punaḥ punaḥ"},{"type":"verse","number":"101","sanskrit":"एकविंशतिवारैस्तन्म्रियते नात्र संशयः एवं सर्वाणि लौहानि स्वर्णादीन्यपि मारयेत्","text":"ekaviṃśativāraistanmriyate nātra saṃśayaḥ evaṃ sarvāṇi lauhāni svarṇādīnyapi mārayet"},{"type":"verse","number":"102","sanskrit":"लौहं तिक्तं सरं शीतं कषायं मधुरं गुरु रूक्षं वयस्यं चक्षुष्यं लेखनं वातलं जयेत्","text":"lauhaṃ tiktaṃ saraṃ śītaṃ kaṣāyaṃ madhuraṃ guru rūkṣaṃ vayasyaṃ cakṣuṣyaṃ lekhanaṃ vātalaṃ jayet"},{"type":"verse","number":"103","sanskrit":"कफं पित्तं गरं शूलं शोफार्शः प्लीहपाण्डुताः मेदोमेहकृमीन् कुष्ठं तत्किट्टं तद्वदेव हि","text":"kaphaṃ pittaṃ garaṃ śūlaṃ śophārśaḥ plīhapāṇḍutāḥ medomehakṛmīn kuṣṭhaṃ tatkiṭṭaṃ tadvadeva hi"},{"type":"verse","number":"104","sanskrit":"गुञ्जामेकां समारभ्य यावत्स्युर्नवरक्तिकाः तावल्लौहं समश्नीयाद्यथादोषानलं नरः","text":"guñjāmekāṃ samārabhya yāvatsyurnavaraktikāḥ tāvallauhaṃ samaśnīyādyathādoṣānalaṃ naraḥ"},{"type":"verse","number":"105","sanskrit":"कूष्माण्डं तिलतैलं च माषान्नं राजिकां तथा मद्यमम्लरसञ्चैव वर्जयेल्लौहसेवकः","text":"kūṣmāṇḍaṃ tilatailaṃ ca māṣānnaṃ rājikāṃ tathā madyamamlarasañcaiva varjayellauhasevakaḥ"},{"type":"verse","number":"106","sanskrit":"शिलागन्धार्कदुग्धाक्ताः स्वर्णाद्याः सर्वधातवः म्रियन्ते द्वादशपुटैः सत्यं गुरुवचो यथा","text":"śilāgandhārkadugdhāktāḥ svarṇādyāḥ sarvadhātavaḥ mriyante dvādaśapuṭaiḥ satyaṃ guruvaco yathā"},{"type":"verse","number":"107","sanskrit":"मन्दानलत्वं बलहानिमुग्रां बिष्टम्भितां नेत्रगदान् सकुष्ठान् मालां तथैव व्रणपूर्विकाञ्च कुर्यादशुद्धं खलु माक्षिकञ्च","text":"mandānalatvaṃ balahānimugrāṃ biṣṭambhitāṃ netragadān sakuṣṭhān mālāṃ tathaiva vraṇapūrvikāñca kuryādaśuddhaṃ khalu mākṣikañca"},{"type":"verse","number":"108","sanskrit":"माक्षिकस्य त्रयो भागा भागैकं सैन्धवस्य च मातुलुङ्गद्र वैर्वाऽथ जम्बीरस्य द्र वैः पचेत्","text":"mākṣikasya trayo bhāgā bhāgaikaṃ saindhavasya ca mātuluṅgadra vairvā'tha jambīrasya dra vaiḥ pacet"},{"type":"verse","number":"109","sanskrit":"चालयेल्लौहजे पात्रे यावत्पात्रं सुलोहितम् भवेत्ततस्तु संशुद्धिं स्वर्णमाक्षिकमृच्छति","text":"cālayellauhaje pātre yāvatpātraṃ sulohitam bhavettatastu saṃśuddhiṃ svarṇamākṣikamṛcchati"},{"type":"verse","number":"110","sanskrit":"कुलत्थस्य कषायेण घृष्ट्वा तैलेन वा पुटेत् तक्रेण वाऽजमूत्रेण म्रियते स्वर्णमाक्षिकम्","text":"kulatthasya kaṣāyeṇa ghṛṣṭvā tailena vā puṭet takreṇa vā'jamūtreṇa mriyate svarṇamākṣikam"},{"type":"verse","number":"111","sanskrit":"स्वर्णमाक्षिकवद्दोषा विज्ञेयास्तारमाक्षिके अतस्तद्दोषशान्त्यर्थं शोधनं तस्य कथ्यते","text":"svarṇamākṣikavaddoṣā vijñeyāstāramākṣike atastaddoṣaśāntyarthaṃ śodhanaṃ tasya kathyate"},{"type":"verse","number":"112","sanskrit":"कर्कोटीमेषशृङ्ग्युत्थैर्द्र वैर्जम्बीरजैर्दिनम् भावयेदातपे तीव्रे विमला शुद्ध्य्ति ध्रुवम्","text":"karkoṭīmeṣaśṛṅgyutthairdra vairjambīrajairdinam bhāvayedātape tīvre vimalā śuddhyti dhruvam"},{"type":"verse","number":"113","sanskrit":"कुलत्थस्य कषायेण घृष्ट्वा तैलेन वा पुटेत् मरणं वाऽजमूत्रेण तारमाक्षिकमृच्छति","text":"kulatthasya kaṣāyeṇa ghṛṣṭvā tailena vā puṭet maraṇaṃ vā'jamūtreṇa tāramākṣikamṛcchati"},{"type":"verse","number":"114","sanskrit":"न केवलं स्वर्णरूप्यगुणास्तापीजयोर्मताः द्र व्यान्तरस्य संसर्गात्सन्त्यन्येऽपि गुणास्तयोः","text":"na kevalaṃ svarṇarūpyaguṇāstāpījayormatāḥ dra vyāntarasya saṃsargātsantyanye'pi guṇāstayoḥ"},{"type":"verse","number":"115","sanskrit":"माक्षिकं मधुरं तिक्तं स्वर्यं वृष्यं रसायनम्","text":"mākṣikaṃ madhuraṃ tiktaṃ svaryaṃ vṛṣyaṃ rasāyanam"},{"type":"verse","number":"116","sanskrit":"चक्षुष्यं वस्तिरुक्कुष्ठपाण्डुमेहविषोदरम् अर्शः शोफं क्षयं कण्डूं त्रिदोषञ्च नियच्छति","text":"cakṣuṣyaṃ vastirukkuṣṭhapāṇḍumehaviṣodaram arśaḥ śophaṃ kṣayaṃ kaṇḍūṃ tridoṣañca niyacchati"},{"type":"verse","number":"117","sanskrit":"विष्ठया मर्दयेत्तुत्थं मार्जारककपोतयोः दशांशं टङ्कणं दत्त्वा पचेल्लघुपुटे ततः पुटं दध्ना पुटं क्षौद्रै र्देयं तुत्थविशुद्धये","text":"viṣṭhayā mardayettutthaṃ mārjārakakapotayoḥ daśāṃśaṃ ṭaṅkaṇaṃ dattvā pacellaghupuṭe tataḥ puṭaṃ dadhnā puṭaṃ kṣaudrai rdeyaṃ tutthaviśuddhaye"},{"type":"verse","number":"118","sanskrit":"तुत्थकं कटुकं क्षारं कषायं वामकं लघु","text":"tutthakaṃ kaṭukaṃ kṣāraṃ kaṣāyaṃ vāmakaṃ laghu"},{"type":"verse","number":"119","sanskrit":"लेखनं भेदनं शीतं चक्षुष्यं कफपित्तहृत् विषाश्मकुष्ठकण्डूघ्नं तद्गुणं खर्परं मतम्","text":"lekhanaṃ bhedanaṃ śītaṃ cakṣuṣyaṃ kaphapittahṛt viṣāśmakuṣṭhakaṇḍūghnaṃ tadguṇaṃ kharparaṃ matam"},{"type":"verse","number":"120","sanskrit":"पत्तलीकृतपत्राणि कांस्यस्याग्नौ प्रतापयेत् निषिञ्चेत्तप्ततप्तानि तैले तक्रे च काञ्जिके","text":"pattalīkṛtapatrāṇi kāṃsyasyāgnau pratāpayet niṣiñcettaptataptāni taile takre ca kāñjike"},{"type":"verse","number":"121","sanskrit":"गोमूत्रे च कुलत्थानां कषायेऽत्र त्रिधा त्रिधा एवं कांस्यस्य रीतेश्च विशुद्धिः सम्प्रजायते","text":"gomūtre ca kulatthānāṃ kaṣāye'tra tridhā tridhā evaṃ kāṃsyasya rīteśca viśuddhiḥ samprajāyate"},{"type":"verse","number":"122","sanskrit":"अर्कक्षीरेण सम्पिष्टो गन्धकस्तेन लेपयेत् समेन कांस्यपत्राणि शुद्धान्यम्लद्र वैर्मुहुः","text":"arkakṣīreṇa sampiṣṭo gandhakastena lepayet samena kāṃsyapatrāṇi śuddhānyamladra vairmuhuḥ"},{"type":"verse","number":"123","sanskrit":"ततो मूषापुटे धृत्वा पचेद्गजपुटेन च एवं पुटद्वयात् कांस्यं रीतिश्च म्रियते ध्रुवम्","text":"tato mūṣāpuṭe dhṛtvā pacedgajapuṭena ca evaṃ puṭadvayāt kāṃsyaṃ rītiśca mriyate dhruvam"},{"type":"verse","number":"124","sanskrit":"कांस्यं कषायं तीक्ष्णोष्णं लेखनं विशदं सरम् गुरु नेत्रहितं रूक्षं कफपित्तहरं परम्","text":"kāṃsyaṃ kaṣāyaṃ tīkṣṇoṣṇaṃ lekhanaṃ viśadaṃ saram guru netrahitaṃ rūkṣaṃ kaphapittaharaṃ param"},{"type":"verse","number":"125","sanskrit":"रीतिका तु भवेद्रू क्षा सतिक्ता लवणा रसे शोधनी पाण्डुरोगघ्नी कृमिहृन्नातिलेखनी","text":"rītikā tu bhavedrū kṣā satiktā lavaṇā rase śodhanī pāṇḍurogaghnī kṛmihṛnnātilekhanī"},{"type":"verse","number":"126","sanskrit":"दुग्धाम्लयोगतस्तस्य विशुद्धिर्गदिता बुधैः","text":"dugdhāmlayogatastasya viśuddhirgaditā budhaiḥ"},{"type":"verse","number":"127","sanskrit":"सिन्दूर उष्णो वीसर्पकुष्ठकण्डूविषापहः भग्नसन्धानजननो व्रणशोधनरोपणः","text":"sindūra uṣṇo vīsarpakuṣṭhakaṇḍūviṣāpahaḥ bhagnasandhānajanano vraṇaśodhanaropaṇaḥ"},{"type":"verse","number":"128","sanskrit":"गोमूत्रगन्धवत्कृष्णं स्रिग्धं मृदु तथा गुरु तिक्तं कषायं शीतञ्च सर्वश्रेष्ठं तदायसम्","text":"gomūtragandhavatkṛṣṇaṃ srigdhaṃ mṛdu tathā guru tiktaṃ kaṣāyaṃ śītañca sarvaśreṣṭhaṃ tadāyasam"},{"type":"verse","number":"129","sanskrit":"विन्ध्यादौ बहुलं तत्तु यत्र लौहं यतोऽधिकम् तच्छोधनमृते व्यर्थमनेकमलमेलनात्","text":"vindhyādau bahulaṃ tattu yatra lauhaṃ yato'dhikam tacchodhanamṛte vyarthamanekamalamelanāt"},{"type":"verse","number":"130","sanskrit":"शिलाजतु समानीय सूक्ष्मं खण्डं विधाय च निक्षिप्यात्युष्णपानीये यामैकं स्थापयेत्सुधीः","text":"śilājatu samānīya sūkṣmaṃ khaṇḍaṃ vidhāya ca nikṣipyātyuṣṇapānīye yāmaikaṃ sthāpayetsudhīḥ"},{"type":"verse","number":"131","sanskrit":"मर्दयित्वा ततो नीरं गृह्णीयाद्वस्त्रगालितम् स्थापयित्वा च मृत्पात्रे धारयेदातपे बुधः","text":"mardayitvā tato nīraṃ gṛhṇīyādvastragālitam sthāpayitvā ca mṛtpātre dhārayedātape budhaḥ"},{"type":"verse","number":"132","sanskrit":"उपरिस्थं घनं यत्स्यात्तत्क्षिपेदन्यपात्रके एवं पुनः पुनर्नीतं द्विमासाभ्यां शिलाजतु","text":"uparisthaṃ ghanaṃ yatsyāttatkṣipedanyapātrake evaṃ punaḥ punarnītaṃ dvimāsābhyāṃ śilājatu"},{"type":"verse","number":"133","sanskrit":"भवेत्कार्यक्षमं वह्नौ क्षिप्तं लिङ्गोपमं भवेत् निर्धूमञ्च ततः शुद्धं सर्वकर्मसु योजयेत्","text":"bhavetkāryakṣamaṃ vahnau kṣiptaṃ liṅgopamaṃ bhavet nirdhūmañca tataḥ śuddhaṃ sarvakarmasu yojayet"},{"type":"verse","number":"134","sanskrit":"व्याधिव्याधितसात्म्यं समनुसरन् भावयेदयःपात्रे प्राक् केवलजलधौतं शुष्कं क्वाथैस्ततो भाव्यम्","text":"vyādhivyādhitasātmyaṃ samanusaran bhāvayedayaḥpātre prāk kevalajaladhautaṃ śuṣkaṃ kvāthaistato bhāvyam"},{"type":"verse","number":"135","sanskrit":"तुल्यं गिरिजेन जले वसुगुणिते भावनौषधं क्वाथ्यम् तत्क्वाथे पादांशे पूतोष्णे प्रक्षिपेद्गिरिजम्","text":"tulyaṃ girijena jale vasuguṇite bhāvanauṣadhaṃ kvāthyam tatkvāthe pādāṃśe pūtoṣṇe prakṣipedgirijam"},{"type":"verse","number":"136","sanskrit":"तत्समरसतां यातं संशुष्कं प्रक्षिपेद्र से भूयः स्वैः स्व्रेवं क्वाथैर्भाव्यं वारान् भवेत् सप्त","text":"tatsamarasatāṃ yātaṃ saṃśuṣkaṃ prakṣipedra se bhūyaḥ svaiḥ svrevaṃ kvāthairbhāvyaṃ vārān bhavet sapta"},{"type":"verse","number":"137","sanskrit":"अथ स्निग्धस्य शुद्धस्य वृतं तिक्तकसाधितम् त्र्! यहं युञ्जीत गिरिजमेकैकेन तथा त्र्! यहम्","text":"atha snigdhasya śuddhasya vṛtaṃ tiktakasādhitam tr! yahaṃ yuñjīta girijamekaikena tathā tr! yaham"},{"type":"verse","number":"138","sanskrit":"फलत्रयस्य यूषेण पटोल्या मधुकस्य च शिलाजमेवं देहस्य भवत्यत्युपकारकम्","text":"phalatrayasya yūṣeṇa paṭolyā madhukasya ca śilājamevaṃ dehasya bhavatyatyupakārakam"},{"type":"verse","number":"139","sanskrit":"लोहस्थितं निम्बगुडूचिसर्पिर्यवैर्यथावत्परिभावयेत्तत् सन्तानिकाकीटपतङ्गदंशदुष्टौषधीदोषनिवारणाय","text":"lohasthitaṃ nimbaguḍūcisarpiryavairyathāvatparibhāvayettat santānikākīṭapataṅgadaṃśaduṣṭauṣadhīdoṣanivāraṇāya"},{"type":"verse","number":"140","sanskrit":"उष्णे च काले रवितापयुक्ते व्यभ्रे निवाते समभूमिभागे चत्वारि पात्राण्यसितायसानि न्यस्यातपे तत्र कृतावधानः","text":"uṣṇe ca kāle ravitāpayukte vyabhre nivāte samabhūmibhāge catvāri pātrāṇyasitāyasāni nyasyātape tatra kṛtāvadhānaḥ"},{"type":"verse","number":"141","sanskrit":"शिलाजतु श्रेष्ठमवाप्य पात्रे प्रक्षिप्य तस्माद् द्विगुणञ्च तोयम् उष्णं तदूर्ध्वं क्वथितञ्च दत्त्वा विशोधयेत्तन्मृदितं यथावत्","text":"śilājatu śreṣṭhamavāpya pātre prakṣipya tasmād dviguṇañca toyam uṣṇaṃ tadūrdhvaṃ kvathitañca dattvā viśodhayettanmṛditaṃ yathāvat"},{"type":"verse","number":"142","sanskrit":"ततस्तु यत्कृष्णमुपैति चोर्ध्वं सन्तानिकावद्र विरश्मितप्तम् पात्रे तदन्यत्र ततो निदध्यात्तत्रापरं कोष्णजलं क्षिपेच्च","text":"tatastu yatkṛṣṇamupaiti cordhvaṃ santānikāvadra viraśmitaptam pātre tadanyatra tato nidadhyāttatrāparaṃ koṣṇajalaṃ kṣipecca"},{"type":"verse","number":"143","sanskrit":"पुनश्च तस्मादपरत्र पात्रे पश्चाच्च पात्रादपरत्र भूयः यदा विशुद्धं जलमेवमूर्ध्वं कृष्णं समस्तं मलमेत्यधस्तात् तदा त्यजेत्तत्सलिलं मलञ्च शिलाजतु स्याज्जलशुद्धमेवम्","text":"punaśca tasmādaparatra pātre paścācca pātrādaparatra bhūyaḥ yadā viśuddhaṃ jalamevamūrdhvaṃ kṛṣṇaṃ samastaṃ malametyadhastāt tadā tyajettatsalilaṃ malañca śilājatu syājjalaśuddhamevam"},{"type":"verse","number":"144","sanskrit":"शिलाजतु स्मृतं तिक्तं कटूष्णं कटुपाकि च रसायनं योगवाहि श्लेष्ममेहाश्मशर्कराः","text":"śilājatu smṛtaṃ tiktaṃ kaṭūṣṇaṃ kaṭupāki ca rasāyanaṃ yogavāhi śleṣmamehāśmaśarkarāḥ"},{"type":"verse","number":"145","sanskrit":"मूत्रकृच्छ्रं क्षयं श्वासं शोथमर्शांसि पाण्डुताम् वातरक्तं तथा कुष्ठमपस्मारोदरं हरेत्","text":"mūtrakṛcchraṃ kṣayaṃ śvāsaṃ śothamarśāṃsi pāṇḍutām vātaraktaṃ tathā kuṣṭhamapasmārodaraṃ haret"},{"type":"verse","number":"146","sanskrit":"नानाधान्यैर्यथाप्राप्तैस्तुषवर्जैर्जलान्वितैः मृद्भाण्डं पूरितं रक्षेद्यावदम्लत्वमाप्नुयात्","text":"nānādhānyairyathāprāptaistuṣavarjairjalānvitaiḥ mṛdbhāṇḍaṃ pūritaṃ rakṣedyāvadamlatvamāpnuyāt"},{"type":"verse","number":"147","sanskrit":"तन्मध्ये भृङ्गराड् मुण्डी विष्णुक्रान्ता पुनर्नवा मीनाक्षी चैव सर्पाक्षी सहदेवी शतावरी","text":"tanmadhye bhṛṅgarāḍ muṇḍī viṣṇukrāntā punarnavā mīnākṣī caiva sarpākṣī sahadevī śatāvarī"},{"type":"verse","number":"148","sanskrit":"त्रिफला गिरिकर्णी च हंसपादी च चित्रकम् समूलं कुट्टयित्वा तु यथालाभं विनिक्षिपेत्","text":"triphalā girikarṇī ca haṃsapādī ca citrakam samūlaṃ kuṭṭayitvā tu yathālābhaṃ vinikṣipet"},{"type":"verse","number":"149","sanskrit":"पूर्वाम्लभाण्डमध्ये तु धान्याम्लकमिदं स्मृतम् स्वेदनादिषु सर्वत्र रसराजस्य योजयेत् अत्यम्लमारनालं वा तदभावे प्रयोजयेत्","text":"pūrvāmlabhāṇḍamadhye tu dhānyāmlakamidaṃ smṛtam svedanādiṣu sarvatra rasarājasya yojayet atyamlamāranālaṃ vā tadabhāve prayojayet"},{"type":"verse","number":"150","sanskrit":"त्र्! यूषणं लवणं राजी रजनी त्रिफलाऽद्र कम् महाबला नागबला मेघनादः पुनर्नवा","text":"tr! yūṣaṇaṃ lavaṇaṃ rājī rajanī triphalā'dra kam mahābalā nāgabalā meghanādaḥ punarnavā"},{"type":"verse","number":"151","sanskrit":"मेषशृङ्गी चित्रकञ्च नवसारं समं समम् एतत्समस्तं व्यस्तं वा पूर्वाम्लेनैव पेषयेत्","text":"meṣaśṛṅgī citrakañca navasāraṃ samaṃ samam etatsamastaṃ vyastaṃ vā pūrvāmlenaiva peṣayet"},{"type":"verse","number":"152","sanskrit":"प्रलिम्पेत्तेन कल्केन वस्त्रमङ्गुलमात्रकम्","text":"pralimpettena kalkena vastramaṅgulamātrakam"},{"type":"verse","number":"153","sanskrit":"तन्मध्ये निक्षिपेत्सूतं बद्ध्वा तत्त्रिदिनं पचेत् दोलायन्त्रेऽम्लसंयुक्ते जायते स्वेदितो रसः","text":"tanmadhye nikṣipetsūtaṃ baddhvā tattridinaṃ pacet dolāyantre'mlasaṃyukte jāyate svedito rasaḥ"},{"type":"verse","number":"154","sanskrit":"मूलकानलसिन्धूत्थत्र्! यूषणार्द्र कराजिकाः रसस्य षोडशांशेन द्र व्यं युञ्ज्यात् पृथक्पृथक्","text":"mūlakānalasindhūtthatr! yūṣaṇārdra karājikāḥ rasasya ṣoḍaśāṃśena dra vyaṃ yuñjyāt pṛthakpṛthak"},{"type":"verse","number":"155","sanskrit":"द्र व्येष्वनुक्तमानेषु मतं मानमितं बुधैः पट्टावृतेषु चैतेषु सूतं प्रक्षिप्य काञ्जिके","text":"dra vyeṣvanuktamāneṣu mataṃ mānamitaṃ budhaiḥ paṭṭāvṛteṣu caiteṣu sūtaṃ prakṣipya kāñjike"},{"type":"verse","number":"156","sanskrit":"स्वेदयेद्दिनमेकञ्च दोलायन्त्रेण बुद्धिमान् स्वेदात्तीव्रो भवेत्सूतो मर्दनाच्च सुनिर्मलः","text":"svedayeddinamekañca dolāyantreṇa buddhimān svedāttīvro bhavetsūto mardanācca sunirmalaḥ"},{"type":"verse","number":"157","sanskrit":"इष्टिकाचूर्णचूर्णाभ्यामादौ मर्द्यो रसस्ततः दध्ना गुडेन सिन्धूत्थराजिकागृहधूमकैः","text":"iṣṭikācūrṇacūrṇābhyāmādau mardyo rasastataḥ dadhnā guḍena sindhūttharājikāgṛhadhūmakaiḥ"},{"type":"verse","number":"158","sanskrit":"कुमारिकाचित्रकरक्तसर्षपैः कृतैः कषायैर्बृहतीविमिश्रितैः फलत्रिकेणापि विमर्दितो रसो दिनत्रयं सर्वमलैर्विमुच्यते","text":"kumārikācitrakaraktasarṣapaiḥ kṛtaiḥ kaṣāyairbṛhatīvimiśritaiḥ phalatrikeṇāpi vimardito raso dinatrayaṃ sarvamalairvimucyate"},{"type":"verse","number":"159","sanskrit":"त्र्! यूषणत्रिफलावन्ध्याकन्दैः क्षुद्रा द्वयान्वितैः चित्रकोर्णानिशाक्षारकन्याऽककनकद्र वैः","text":"tr! yūṣaṇatriphalāvandhyākandaiḥ kṣudrā dvayānvitaiḥ citrakorṇāniśākṣārakanyā'kakanakadra vaiḥ"},{"type":"verse","number":"160","sanskrit":"सूतं कृतेन यूषेण वारान्सप्त विमर्दयेत् इत्थं संमूर्च्छितः सूतस्त्यजेत्सप्तापि कञ्चुकान्","text":"sūtaṃ kṛtena yūṣeṇa vārānsapta vimardayet itthaṃ saṃmūrcchitaḥ sūtastyajetsaptāpi kañcukān"},{"type":"verse","number":"161","sanskrit":"मयूरग्रीवताप्याभ्यां नष्टपिष्टीकृतस्य च यन्त्रे विद्याधरे कुर्याद्र सेन्द्र स्योर्ध्वपातनम्","text":"mayūragrīvatāpyābhyāṃ naṣṭapiṣṭīkṛtasya ca yantre vidyādhare kuryādra sendra syordhvapātanam"},{"type":"verse","number":"162","sanskrit":"त्रिफलाशिग्रुशिखिभिर्लंवणासुरिसंयुतैः नष्टपिष्टं रसं कृत्वा लेपयेदूर्ध्वभाजनम्","text":"triphalāśigruśikhibhirlaṃvaṇāsurisaṃyutaiḥ naṣṭapiṣṭaṃ rasaṃ kṛtvā lepayedūrdhvabhājanam"},{"type":"verse","number":"163","sanskrit":"ततो दीप्तैरधः पातमुपलैस्तस्य कारयेत् यन्त्रे भूधरसंज्ञे तु ततः सूतो विशुद्ध्य्ति","text":"tato dīptairadhaḥ pātamupalaistasya kārayet yantre bhūdharasaṃjñe tu tataḥ sūto viśuddhyti"},{"type":"verse","number":"164","sanskrit":"स्वेदनादिक्रियाभिस्तु शोधितोऽसौ यदा भवेत् तदा कार्याणि कुरुते प्रयोज्यः सर्वकर्मसु","text":"svedanādikriyābhistu śodhito'sau yadā bhavet tadā kāryāṇi kurute prayojyaḥ sarvakarmasu"},{"type":"verse","number":"165","sanskrit":"गृहकन्या हरति मलं त्रिफलाऽग्नि चित्रको विषं हन्ति तस्मादेभिर्मिश्रैर्वारान् संमूर्च्छयेत्सप्त","text":"gṛhakanyā harati malaṃ triphalā'gni citrako viṣaṃ hanti tasmādebhirmiśrairvārān saṃmūrcchayetsapta"},{"type":"verse","number":"166","sanskrit":"कुमारिकाचित्रकरक्तसर्षपैः कृतैः कषायैर्वृहतीविमिश्रितैः फलत्रिकेणापि विमर्दितो रसो दिनत्रयं सर्वमलैर्विमुच्यते","text":"kumārikācitrakaraktasarṣapaiḥ kṛtaiḥ kaṣāyairvṛhatīvimiśritaiḥ phalatrikeṇāpi vimardito raso dinatrayaṃ sarvamalairvimucyate"},{"type":"verse","number":"167","sanskrit":"कुमार्या च निशाचूर्णैर्दिनं सूतं विमर्दयेत् एवं कदर्थितः सूतः षण्ढो भवति निश्चितम्","text":"kumāryā ca niśācūrṇairdinaṃ sūtaṃ vimardayet evaṃ kadarthitaḥ sūtaḥ ṣaṇḍho bhavati niścitam"},{"type":"verse","number":"168","sanskrit":"बह्वौषधिकषायेण स्वेदितः स बली भवेत् सर्पाक्षीचिञ्चिकावन्ध्याभृङ्गाब्दैः स्वेदितो बली ततः स पावकद्रा वैः स्विन्नः स्यादतिदीप्तिमान्","text":"bahvauṣadhikaṣāyeṇa sveditaḥ sa balī bhavet sarpākṣīciñcikāvandhyābhṛṅgābdaiḥ svedito balī tataḥ sa pāvakadrā vaiḥ svinnaḥ syādatidīptimān"},{"type":"verse","number":"169","sanskrit":"धूमसारं रसं तोरीं गन्धकं नवसादरम् यामैकं मर्दयेदम्लैर्भागं कृत्वा समं समम्","text":"dhūmasāraṃ rasaṃ torīṃ gandhakaṃ navasādaram yāmaikaṃ mardayedamlairbhāgaṃ kṛtvā samaṃ samam"},{"type":"verse","number":"170","sanskrit":"काचकूप्यां विनिक्षिप्य ताञ्च मृद्वस्त्रमुद्र या विलिप्य परितो वक्त्रे मुद्रा ं! दत्त्वा विशोषयेत्","text":"kācakūpyāṃ vinikṣipya tāñca mṛdvastramudra yā vilipya parito vaktre mudrā ṃ! dattvā viśoṣayet"},{"type":"verse","number":"171","sanskrit":"अधः सच्छिद्र पिठरीमध्ये कूपीं निवेशयेत् पिठरीं बालुकापूरैर्भृत्वा चाकूपिकागलम्","text":"adhaḥ sacchidra piṭharīmadhye kūpīṃ niveśayet piṭharīṃ bālukāpūrairbhṛtvā cākūpikāgalam"},{"type":"verse","number":"172","sanskrit":"निवेश्य चुल्ल्यां तदधो बह्निं कुर्याच्छनैः शनैः तस्मादत्यधिकं किञ्चित्पावकं ज्वालयेत्क्रमात्","text":"niveśya cullyāṃ tadadho bahniṃ kuryācchanaiḥ śanaiḥ tasmādatyadhikaṃ kiñcitpāvakaṃ jvālayetkramāt"},{"type":"verse","number":"173","sanskrit":"एवं द्वादशभिर्यामैम्रियते रस उत्तमः स्फोटयेत्स्वाङ्गशीतं तमूर्ध्वगं गन्धकं त्यजेत्","text":"evaṃ dvādaśabhiryāmaimriyate rasa uttamaḥ sphoṭayetsvāṅgaśītaṃ tamūrdhvagaṃ gandhakaṃ tyajet"},{"type":"verse","number":"174","sanskrit":"अधःस्थञ्च मृतं सूतं गृह्णीयात्तं तु मात्रया यथोचितानुपानेन सर्वकर्मसु योजयेत्","text":"adhaḥsthañca mṛtaṃ sūtaṃ gṛhṇīyāttaṃ tu mātrayā yathocitānupānena sarvakarmasu yojayet"},{"type":"verse","number":"175","sanskrit":"अपामार्गस्य बीजानां मूषायुग्मं प्रकल्पयेत् तत्सम्पुटे क्षिपेत्सूतं मलयूदुग्धमिश्रितम्","text":"apāmārgasya bījānāṃ mūṣāyugmaṃ prakalpayet tatsampuṭe kṣipetsūtaṃ malayūdugdhamiśritam"},{"type":"verse","number":"176","sanskrit":"द्रो णपुष्पीप्रसूनानि विडङ्गमरिमेदकः एतच्चूर्णमधश्चोर्ध्वं दत्त्वा मुद्रा प्रदीयते","text":"dro ṇapuṣpīprasūnāni viḍaṅgamarimedakaḥ etaccūrṇamadhaścordhvaṃ dattvā mudrā pradīyate"},{"type":"verse","number":"177","sanskrit":"तद्गोलं स्थापयेत्सम्यङ् मृन्मूषासम्पुटे पचेत्","text":"tadgolaṃ sthāpayetsamyaṅ mṛnmūṣāsampuṭe pacet"},{"type":"verse","number":"178","sanskrit":"एवमेकपुटेनैव सूतकं भस्म जायते तत्प्रयोज्यं यथास्थाने यथामात्रं यथाविधि","text":"evamekapuṭenaiva sūtakaṃ bhasma jāyate tatprayojyaṃ yathāsthāne yathāmātraṃ yathāvidhi"},{"type":"verse","number":"179","sanskrit":"काकोदुम्बरिकादुग्धैः रसं किञ्चिद्विमर्दयेत् तद्दुग्धघृष्टहिङ्गोश्च मूषायुग्मं प्रकल्पयेत्","text":"kākodumbarikādugdhaiḥ rasaṃ kiñcidvimardayet taddugdhaghṛṣṭahiṅgośca mūṣāyugmaṃ prakalpayet"},{"type":"verse","number":"180","sanskrit":"क्षिप्त्वा तत्संपुटे सूतं तत्र मुद्रा ं! प्रदापयेत् धृत्वा तद् गोलकं प्राज्ञो मृन्मूषासम्पुटेऽधिके पचेद् गजपुटेनैव सूतकं याति भस्मताम्","text":"kṣiptvā tatsaṃpuṭe sūtaṃ tatra mudrā ṃ! pradāpayet dhṛtvā tad golakaṃ prājño mṛnmūṣāsampuṭe'dhike paced gajapuṭenaiva sūtakaṃ yāti bhasmatām"},{"type":"verse","number":"181","sanskrit":"नागवल्लीरसैर्घृष्टः कर्कोटीकन्दगर्भितः मृन्मूषासम्पुटे पक्वं सूतो यात्येव भस्मताम्","text":"nāgavallīrasairghṛṣṭaḥ karkoṭīkandagarbhitaḥ mṛnmūṣāsampuṭe pakvaṃ sūto yātyeva bhasmatām"},{"type":"verse","number":"182","sanskrit":"तत्र पारदस्य संक्षिप्तं शोधनं कर्त्तव्यम् शुद्धसूतसमं कुर्यात्प्रत्येकं गैरिकं सुधीः इष्टिकां खटिकां तद्वत्स्फटिकां सिन्धुजन्म च","text":"tatra pāradasya saṃkṣiptaṃ śodhanaṃ karttavyam śuddhasūtasamaṃ kuryātpratyekaṃ gairikaṃ sudhīḥ iṣṭikāṃ khaṭikāṃ tadvatsphaṭikāṃ sindhujanma ca"},{"type":"verse","number":"183","sanskrit":"वल्मीकं क्षारलवणं भाण्डरञ्जकमृत्तिकाम् सर्वाण्येतानि संचूर्ण्य वाससा चापि शोधयेत्","text":"valmīkaṃ kṣāralavaṇaṃ bhāṇḍarañjakamṛttikām sarvāṇyetāni saṃcūrṇya vāsasā cāpi śodhayet"},{"type":"verse","number":"184","sanskrit":"एभिश्चूर्णैर्युतं सूतं यावद्यामं विमर्दयेत् तच्चूर्णसहितं सूतं स्थालीमध्ये परिक्षिपेत्","text":"ebhiścūrṇairyutaṃ sūtaṃ yāvadyāmaṃ vimardayet taccūrṇasahitaṃ sūtaṃ sthālīmadhye parikṣipet"},{"type":"verse","number":"185","sanskrit":"तस्याः स्थाल्या मुखे स्थालीमपरां धारयेत्समाम् सवस्त्रकुट्टितमृदा मुद्र येदनयोर्मुखम्","text":"tasyāḥ sthālyā mukhe sthālīmaparāṃ dhārayetsamām savastrakuṭṭitamṛdā mudra yedanayormukham"},{"type":"verse","number":"186","sanskrit":"संशोष्य मुद्र येद्भूयो भूयः संशोष्य मुद्र येत् सम्यग्विशोष्य मुद्रा ं! तां स्थालद्यं चुल्ल्यां विधारयेत्","text":"saṃśoṣya mudra yedbhūyo bhūyaḥ saṃśoṣya mudra yet samyagviśoṣya mudrā ṃ! tāṃ sthāladyaṃ cullyāṃ vidhārayet"},{"type":"verse","number":"187","sanskrit":"अग्निं निरन्तरं दद्याद्यावद्दिनचतुष्टयम् अङ्गारोपरि तद्यन्त्रं रक्षेद्यत्नादहर्निशम्","text":"agniṃ nirantaraṃ dadyādyāvaddinacatuṣṭayam aṅgāropari tadyantraṃ rakṣedyatnādaharniśam"},{"type":"verse","number":"188","sanskrit":"शनैरुद्घाटयेद्यन्त्रमूर्ध्वस्थालीगतं रसम् कर्पूरवत्सुविमलं गृह्णीयाद् गुणवत्तरम्","text":"śanairudghāṭayedyantramūrdhvasthālīgataṃ rasam karpūravatsuvimalaṃ gṛhṇīyād guṇavattaram"},{"type":"verse","number":"189","sanskrit":"तद्देवकुसुमचन्दनकस्तूरीकुङ्कुमैर्युक्तम् खादन् हरति फिरङ्गं व्याधिं सोपद्र वं सपदि","text":"taddevakusumacandanakastūrīkuṅkumairyuktam khādan harati phiraṅgaṃ vyādhiṃ sopadra vaṃ sapadi"},{"type":"verse","number":"190","sanskrit":"विन्दति वह्नेर्दीप्तिं पुष्टिं वीर्यं बलं विपुलम् रमयति रमणीशतकं रसकर्पूरस्य सेवकः सततम्","text":"vindati vahnerdīptiṃ puṣṭiṃ vīryaṃ balaṃ vipulam ramayati ramaṇīśatakaṃ rasakarpūrasya sevakaḥ satatam"},{"type":"verse","number":"191","sanskrit":"शुद्धसूतस्य गृह्णीयाद्भिषग्भागचतुष्टयम् शुद्धगन्धस्य भागैकं तावत्कृत्रिमगन्धकम्","text":"śuddhasūtasya gṛhṇīyādbhiṣagbhāgacatuṣṭayam śuddhagandhasya bhāgaikaṃ tāvatkṛtrimagandhakam"},{"type":"verse","number":"192","sanskrit":"अथवा पारदस्यार्द्धं शुद्धगन्धकमेव हि तयोः कज्जलिकां कुर्याद्दिनमेकं विमर्दयेत्","text":"athavā pāradasyārddhaṃ śuddhagandhakameva hi tayoḥ kajjalikāṃ kuryāddinamekaṃ vimardayet"},{"type":"verse","number":"193","sanskrit":"मृत्तिका वाससा सार्द्धं कुट्टयेदतियत्नतः तथा वारत्रयं सम्यक्काचकूपीं प्रलेपयेत्","text":"mṛttikā vāsasā sārddhaṃ kuṭṭayedatiyatnataḥ tathā vāratrayaṃ samyakkācakūpīṃ pralepayet"},{"type":"verse","number":"194","sanskrit":"मृत्तिकां शोषयित्वा तु कूप्यां कज्जलिकां क्षिपेत् तां कूपीं बालुकायन्त्रे स्थापयित्वा रसं पचेत्","text":"mṛttikāṃ śoṣayitvā tu kūpyāṃ kajjalikāṃ kṣipet tāṃ kūpīṃ bālukāyantre sthāpayitvā rasaṃ pacet"},{"type":"verse","number":"195","sanskrit":"अग्निं निरन्तरं दद्याद्यावद्दिनचुतष्टयम् गृह्णीयादूर्ध्वसंलग्नं सिन्दूरसदृशं रसम्","text":"agniṃ nirantaraṃ dadyādyāvaddinacutaṣṭayam gṛhṇīyādūrdhvasaṃlagnaṃ sindūrasadṛśaṃ rasam"},{"type":"verse","number":"196","sanskrit":"इति सिन्दूररसः पारदः कृमिकुष्ठघ्नो जयदो दृष्टिकृत्सरः मृत्युहृच्च महावीर्यो योगवाही ज्वरापहः","text":"iti sindūrarasaḥ pāradaḥ kṛmikuṣṭhaghno jayado dṛṣṭikṛtsaraḥ mṛtyuhṛcca mahāvīryo yogavāhī jvarāpahaḥ"},{"type":"verse","number":"197","sanskrit":"स्मृत्योजोरूपदो वृष्यो वृद्धिकृद्धातुवर्द्धनः षण्ढत्वनाशनः शूरः खेचरः सिद्धिदःपरः","text":"smṛtyojorūpado vṛṣyo vṛddhikṛddhātuvarddhanaḥ ṣaṇḍhatvanāśanaḥ śūraḥ khecaraḥ siddhidaḥparaḥ"},{"type":"verse","number":"198","sanskrit":"पारदः सकलरोगहा स्मृतः षड्रसो निखिलयोगवाहकः पञ्चभूतमय एष कीर्त्तितस्तेन तद्गुणगणैर्विराजते","text":"pāradaḥ sakalarogahā smṛtaḥ ṣaḍraso nikhilayogavāhakaḥ pañcabhūtamaya eṣa kīrttitastena tadguṇagaṇairvirājate"},{"type":"verse","number":"199","sanskrit":"यस्य रोगस्य यो योगस्तेनैव सह योजितः रसेन्द्रो हन्ति तं रोगं नरकुञ्जरवाजिनाम्","text":"yasya rogasya yo yogastenaiva saha yojitaḥ rasendro hanti taṃ rogaṃ narakuñjaravājinām"},{"type":"verse","number":"200","sanskrit":"मेषीक्षीरेण दरदमम्लवर्गैश्च भावितम् सप्तवारान्प्रयत्नेन शुद्धिमायाति निश्चितम्","text":"meṣīkṣīreṇa daradamamlavargaiśca bhāvitam saptavārānprayatnena śuddhimāyāti niścitam"},{"type":"verse","number":"201","sanskrit":"तिक्तं कषायं कटु हिङ्गुलं स्यान्नेत्रामयघ्नं कफपित्तहारि हृल्लासकण्डूज्वरकामलाश्च प्लीहामवातौ च गरं निहन्ति","text":"tiktaṃ kaṣāyaṃ kaṭu hiṅgulaṃ syānnetrāmayaghnaṃ kaphapittahāri hṛllāsakaṇḍūjvarakāmalāśca plīhāmavātau ca garaṃ nihanti"},{"type":"verse","number":"202","sanskrit":"निम्बूरसैर्निम्बपत्ररसैर्वा याममात्रकम् घृष्ट्वा दरदमूर्ध्वन्तु पातयेत्सूतयुक्तिवत्","text":"nimbūrasairnimbapatrarasairvā yāmamātrakam ghṛṣṭvā daradamūrdhvantu pātayetsūtayuktivat"},{"type":"verse","number":"203","sanskrit":"तत्रोर्ध्वपिठरीलग्नं गृह्णीयाद्र समुत्तमम् शुद्धमेव हि तं सूतं सर्वकर्मसु योजयेत्","text":"tatrordhvapiṭharīlagnaṃ gṛhṇīyādra samuttamam śuddhameva hi taṃ sūtaṃ sarvakarmasu yojayet"},{"type":"verse","number":"204","sanskrit":"अशुद्धो गन्धकः कुर्यात्कुष्ठं पित्तरुजां भ्रमम् हन्ति वीर्य्यं बलं रूपं तस्माच्छुद्धः प्रयुज्यते","text":"aśuddho gandhakaḥ kuryātkuṣṭhaṃ pittarujāṃ bhramam hanti vīryyaṃ balaṃ rūpaṃ tasmācchuddhaḥ prayujyate"},{"type":"verse","number":"205","sanskrit":"लौहपात्रे विनिक्षिप्य घृतमग्नौ प्रतापयेत् तप्ते घृते तत्समानं क्षिपेद् गन्धकजं रजः","text":"lauhapātre vinikṣipya ghṛtamagnau pratāpayet tapte ghṛte tatsamānaṃ kṣiped gandhakajaṃ rajaḥ"},{"type":"verse","number":"206","sanskrit":"विद्रुतं गन्धकं दृष्ट्वा तनुवस्त्रे विनिक्षिपेत् यथा वस्त्राद्विनिःस्रुत्य दुग्धमध्येऽखिलं पतेत् एवं स गन्धकः शुद्धः सर्वकर्मोचितो भवेत्","text":"vidrutaṃ gandhakaṃ dṛṣṭvā tanuvastre vinikṣipet yathā vastrādviniḥsrutya dugdhamadhye'khilaṃ patet evaṃ sa gandhakaḥ śuddhaḥ sarvakarmocito bhavet"},{"type":"verse","number":"207","sanskrit":"गन्धकः कटुकस्तिक्तो वीर्य्योष्णस्तुवरः सरः","text":"gandhakaḥ kaṭukastikto vīryyoṣṇastuvaraḥ saraḥ"},{"type":"verse","number":"208","sanskrit":"पित्तलः कटुकः पाके कण्डूवीसर्पजन्तुजित् हन्ति कुष्ठक्षयप्लीहकफवातान् रसायनः","text":"pittalaḥ kaṭukaḥ pāke kaṇḍūvīsarpajantujit hanti kuṣṭhakṣayaplīhakaphavātān rasāyanaḥ"},{"type":"verse","number":"209","sanskrit":"पीडां विधत्ते विविधां नराणां कुष्ठं क्षयं पाण्डुगदञ्च कुर्य्यात् हृत्पार्श्वपीडां च करोत्यसह्यामशुद्धमभ्रं गुरु वह्निहृत्स्यात्","text":"pīḍāṃ vidhatte vividhāṃ narāṇāṃ kuṣṭhaṃ kṣayaṃ pāṇḍugadañca kuryyāt hṛtpārśvapīḍāṃ ca karotyasahyāmaśuddhamabhraṃ guru vahnihṛtsyāt"},{"type":"verse","number":"210","sanskrit":"कृष्णाभ्रकं धमेद्वह्नौ ततः क्षीरे विनिक्षिपेत् भिन्नपत्रं तु तत्कृत्वा तण्डुलीयाम्लयोर्द्र वैः भावयेदष्टयामं तदेवमभ्रं विशुद्ध्यति","text":"kṛṣṇābhrakaṃ dhamedvahnau tataḥ kṣīre vinikṣipet bhinnapatraṃ tu tatkṛtvā taṇḍulīyāmlayordra vaiḥ bhāvayedaṣṭayāmaṃ tadevamabhraṃ viśuddhyati"},{"type":"verse","number":"211","sanskrit":"कृत्वा धान्याभ्रकं तथा शोषयित्वाऽथ मर्दयेत् अर्कक्षीरैर्दिनं खल्वे चक्राकारं च कारयेत्","text":"kṛtvā dhānyābhrakaṃ tathā śoṣayitvā'tha mardayet arkakṣīrairdinaṃ khalve cakrākāraṃ ca kārayet"},{"type":"verse","number":"212","sanskrit":"वेष्टयेदर्कपत्रैश्च सम्यग्गजपुटे पचेत् पुनर्मर्द्यं पुनः पाच्यं सप्तवारान् पुनः पुनः","text":"veṣṭayedarkapatraiśca samyaggajapuṭe pacet punarmardyaṃ punaḥ pācyaṃ saptavārān punaḥ punaḥ"},{"type":"verse","number":"213","sanskrit":"ततो वटजटाक्वाथैस्तद्वद्देयं पुटत्रयम् म्रियते नात्र सन्देहः प्रयोज्यं सर्वकर्मसु","text":"tato vaṭajaṭākvāthaistadvaddeyaṃ puṭatrayam mriyate nātra sandehaḥ prayojyaṃ sarvakarmasu"},{"type":"verse","number":"214","sanskrit":"तुल्यं घृतं मृताभ्रेण लोहपात्रे विपाचयेत् घृते जीर्णे तदभ्रन्तु सर्वयोगेषु योजयेत्","text":"tulyaṃ ghṛtaṃ mṛtābhreṇa lohapātre vipācayet ghṛte jīrṇe tadabhrantu sarvayogeṣu yojayet"},{"type":"verse","number":"215","sanskrit":"पादांशशालिसंयुक्तमभ्रं बद्ध्वाऽथ कम्बले त्रिरात्रं स्थापयेन्नीरे तत्क्लिन्नं मर्दयेत्करैः","text":"pādāṃśaśālisaṃyuktamabhraṃ baddhvā'tha kambale trirātraṃ sthāpayennīre tatklinnaṃ mardayetkaraiḥ"},{"type":"verse","number":"216","sanskrit":"कम्बलाद्गलितं सूक्ष्मं बालुकारहितञ्च यत् तद् धान्याभ्रमिति प्रोक्तमभ्रमारणसिद्धये","text":"kambalādgalitaṃ sūkṣmaṃ bālukārahitañca yat tad dhānyābhramiti proktamabhramāraṇasiddhaye"},{"type":"verse","number":"217","sanskrit":"अभ्रं कषायं मधुरं सुशीतमायुष्करं धातुविवर्द्धनञ्च हन्यात् त्रिदोषं व्रणमेहकुष्ठं प्लीहोदरं ग्रन्थिविषकृमींश्च","text":"abhraṃ kaṣāyaṃ madhuraṃ suśītamāyuṣkaraṃ dhātuvivarddhanañca hanyāt tridoṣaṃ vraṇamehakuṣṭhaṃ plīhodaraṃ granthiviṣakṛmīṃśca"},{"type":"verse","number":"218","sanskrit":"रोगान् हन्ति द्र ढयति वपुर्वीर्यवृद्धिं विधत्ते तारुण्याढ्यं रमयति शतं योषितां नित्यमेव दीर्घायुष्काञ्जनयति सुतान् सिंहतुल्यप्रभावान् मृत्योर्भीतिं हरति सुतरां सेव्यमानं मृताभ्रम्","text":"rogān hanti dra ḍhayati vapurvīryavṛddhiṃ vidhatte tāruṇyāḍhyaṃ ramayati śataṃ yoṣitāṃ nityameva dīrghāyuṣkāñjanayati sutān siṃhatulyaprabhāvān mṛtyorbhītiṃ harati sutarāṃ sevyamānaṃ mṛtābhram"},{"type":"verse","number":"219","sanskrit":"अशुद्धं तालमायुर्हृत्कफमारुतमेहकृत् तापस्फोटाङ्गसङ्कोचं कुरुते तेन शोधयेत्","text":"aśuddhaṃ tālamāyurhṛtkaphamārutamehakṛt tāpasphoṭāṅgasaṅkocaṃ kurute tena śodhayet"},{"type":"verse","number":"220","sanskrit":"तालकं कणशः कृत्वा तच्चूर्णं काञ्जिके पचेत् दोलायन्त्रेण यामैकं ततः कूष्माण्डजद्र वैः","text":"tālakaṃ kaṇaśaḥ kṛtvā taccūrṇaṃ kāñjike pacet dolāyantreṇa yāmaikaṃ tataḥ kūṣmāṇḍajadra vaiḥ"},{"type":"verse","number":"221","sanskrit":"तिलतैले पचेद्यामं यामञ्च त्रिफलाजले एवं यन्त्रे चतुर्यामं पक्वं शुद्ध्य्ति तालकम्","text":"tilataile pacedyāmaṃ yāmañca triphalājale evaṃ yantre caturyāmaṃ pakvaṃ śuddhyti tālakam"},{"type":"verse","number":"222","sanskrit":"सदलं तालकं शुद्धं पौनर्नवरसेन तु खल्वे विमर्दयेदेकं दिनं पश्चाद्विशोधयेत्","text":"sadalaṃ tālakaṃ śuddhaṃ paunarnavarasena tu khalve vimardayedekaṃ dinaṃ paścādviśodhayet"},{"type":"verse","number":"223","sanskrit":"ततः पुनर्नवाक्षारैः स्थाल्यामर्द्धं प्रपूरयेत् तत्र तद्गोलकं कृत्वा पुनस्तेनैव पूरयेत्","text":"tataḥ punarnavākṣāraiḥ sthālyāmarddhaṃ prapūrayet tatra tadgolakaṃ kṛtvā punastenaiva pūrayet"},{"type":"verse","number":"224","sanskrit":"आकण्ठं पिठरं तस्य पिधानं धारयेन्मुखे स्थालद्यं चुल्ल्यां समारोप्य क्रमाद्वह्निं विवर्धयेत्","text":"ākaṇṭhaṃ piṭharaṃ tasya pidhānaṃ dhārayenmukhe sthāladyaṃ cullyāṃ samāropya kramādvahniṃ vivardhayet"},{"type":"verse","number":"225","sanskrit":"दिनान्यन्तरशून्यानि पञ्च वह्निं प्रदापयेत्","text":"dinānyantaraśūnyāni pañca vahniṃ pradāpayet"},{"type":"verse","number":"226","sanskrit":"एवं तन्म्रियते तालं मात्रा तस्यैकरक्तिका अनुपानान्यनेकानि यथायोग्यं प्रयोजयेत्","text":"evaṃ tanmriyate tālaṃ mātrā tasyaikaraktikā anupānānyanekāni yathāyogyaṃ prayojayet"},{"type":"verse","number":"227","sanskrit":"हरितालं कटु स्निग्धं कषायोष्णं हरेद्विषम् कण्डूकुष्ठास्यरोगास्रकफपित्तकचव्रणान्","text":"haritālaṃ kaṭu snigdhaṃ kaṣāyoṣṇaṃ haredviṣam kaṇḍūkuṣṭhāsyarogāsrakaphapittakacavraṇān"},{"type":"verse","number":"228","sanskrit":"तालकं हरते रोगान्कुष्ठमृत्युज्वरापहम् शोधितं कुरुते कान्तिं वीर्यवृद्धिं तथाऽयुषम्","text":"tālakaṃ harate rogānkuṣṭhamṛtyujvarāpaham śodhitaṃ kurute kāntiṃ vīryavṛddhiṃ tathā'yuṣam"},{"type":"verse","number":"229","sanskrit":"तालकस्यैव भेदोऽस्ति मनोगुप्तैतदन्तरम् तालकं त्वतिपीतं स्याद्भवेद्र क्ता मनः शिला","text":"tālakasyaiva bhedo'sti manoguptaitadantaram tālakaṃ tvatipītaṃ syādbhavedra ktā manaḥ śilā"},{"type":"verse","number":"230","sanskrit":"मनःशिला मन्दवलं करोति जन्तुं ध्रुवं शोधनमन्तरेण मलस्य बन्धं किल मूत्ररोधं सशर्करं कृच्छ्रगदञ्च कुर्य्यात्","text":"manaḥśilā mandavalaṃ karoti jantuṃ dhruvaṃ śodhanamantareṇa malasya bandhaṃ kila mūtrarodhaṃ saśarkaraṃ kṛcchragadañca kuryyāt"},{"type":"verse","number":"231","sanskrit":"पचेत्त्र्यहमजामूत्रे दोलायन्त्रे मनःशिलाम् भावयेत्सप्तधा पित्तैरजायाः सा विशुद्ध्यति","text":"pacettryahamajāmūtre dolāyantre manaḥśilām bhāvayetsaptadhā pittairajāyāḥ sā viśuddhyati"},{"type":"verse","number":"232","sanskrit":"गुर्वी मनः शिला वर्ण्या सरोष्णा लेखनी कटुः तिक्ता स्निग्धा विषश्वासकासभूतकफास्रनुत्","text":"gurvī manaḥ śilā varṇyā saroṣṇā lekhanī kaṭuḥ tiktā snigdhā viṣaśvāsakāsabhūtakaphāsranut"},{"type":"verse","number":"233","sanskrit":"नरमूत्रे च गोमूत्रे सप्ताहं रसकं पचेत् दोलायन्त्रेण शुद्धः स्यात्ततः कार्येषु योजयेत्","text":"naramūtre ca gomūtre saptāhaṃ rasakaṃ pacet dolāyantreṇa śuddhaḥ syāttataḥ kāryeṣu yojayet"},{"type":"verse","number":"234","sanskrit":"खर्परं कटुकं क्षारं कषायं वामकं लघु लेखनं भेदनं शीतं चक्षुष्यं कफपित्तहृत् विषाश्मकुष्ठकण्डूनां नाशनं परमं मतम्","text":"kharparaṃ kaṭukaṃ kṣāraṃ kaṣāyaṃ vāmakaṃ laghu lekhanaṃ bhedanaṃ śītaṃ cakṣuṣyaṃ kaphapittahṛt viṣāśmakuṣṭhakaṇḍūnāṃ nāśanaṃ paramaṃ matam"},{"type":"verse","number":"235","sanskrit":"सूर्यावर्त्तो वज्रकन्दः कदली देवदालिका शिग्रुः कोशातकी वन्ध्या काकमाची च बालकम्","text":"sūryāvartto vajrakandaḥ kadalī devadālikā śigruḥ kośātakī vandhyā kākamācī ca bālakam"},{"type":"verse","number":"236","sanskrit":"एषामेकरसेनैव त्रिक्षारैर्लवणैः सह भावयेदम्लवर्गैश्च दिनमेकं प्रयत्नतः","text":"eṣāmekarasenaiva trikṣārairlavaṇaiḥ saha bhāvayedamlavargaiśca dinamekaṃ prayatnataḥ"},{"type":"verse","number":"237","sanskrit":"ततः पचेच्च तद्द्रा वैर्दोलायन्त्रे दिनं सुधीः एवं शुद्ध्य्न्ति ते सर्वे प्रोक्ता उपरसा हि ये","text":"tataḥ pacecca taddrā vairdolāyantre dinaṃ sudhīḥ evaṃ śuddhynti te sarve proktā uparasā hi ye"},{"type":"verse","number":"238","sanskrit":"कङ्कुष्ठं गैरिकं शङ्खः कासीसं टङ्कणं तथा नीलाञ्जनं शुक्तिभेदाः क्षुल्लकाः सवराटकाः","text":"kaṅkuṣṭhaṃ gairikaṃ śaṅkhaḥ kāsīsaṃ ṭaṅkaṇaṃ tathā nīlāñjanaṃ śuktibhedāḥ kṣullakāḥ savarāṭakāḥ"},{"type":"verse","number":"239","sanskrit":"जम्बीरवारिणा स्विन्नाः क्षालिताः कोष्णवारिणा शुद्धिमायान्त्यमी योज्या भिषग्भिर्योगसिद्धये","text":"jambīravāriṇā svinnāḥ kṣālitāḥ koṣṇavāriṇā śuddhimāyāntyamī yojyā bhiṣagbhiryogasiddhaye"},{"type":"verse","number":"240","sanskrit":"अशुद्धं कुरुते वज्रं कुष्ठं पार्श्वव्यथां तथा पाण्डुत्वं पङ्गुलत्वञ्च तस्मात्संशोध्य मारयेत्","text":"aśuddhaṃ kurute vajraṃ kuṣṭhaṃ pārśvavyathāṃ tathā pāṇḍutvaṃ paṅgulatvañca tasmātsaṃśodhya mārayet"},{"type":"verse","number":"241","sanskrit":"कुलत्थकोद्र वक्वाथे दोलायन्त्रे विपाचयेत् व्याघ्रीकन्दगतं वज्रं त्रिदिनात्तद्विशुद्ध्य्ति","text":"kulatthakodra vakvāthe dolāyantre vipācayet vyāghrīkandagataṃ vajraṃ tridināttadviśuddhyti"},{"type":"verse","number":"242","sanskrit":"गृहीत्वाऽह्नि शुभे वज्रंव्याघ्रीकन्दोदरे क्षिपेत् महिषीविष्ठया लिप्त्वा कारीषाग्नौ विपाचयेत्","text":"gṛhītvā'hni śubhe vajraṃvyāghrīkandodare kṣipet mahiṣīviṣṭhayā liptvā kārīṣāgnau vipācayet"},{"type":"verse","number":"243","sanskrit":"त्रियामायां चतुर्यामं यामिन्यन्तेऽश्वमूत्रके सेचयेत्पाचयेदेवं सप्तरात्रेण शुद्ध्य्ति","text":"triyāmāyāṃ caturyāmaṃ yāminyante'śvamūtrake secayetpācayedevaṃ saptarātreṇa śuddhyti"},{"type":"verse","number":"244","sanskrit":"हिंगुसैन्धवसंयुक्ते क्षिपेत्क्वाथे कुलत्थजे तप्तं तप्तं पुनर्वज्रं भवेद्भस्म त्रिसप्तधा","text":"hiṃgusaindhavasaṃyukte kṣipetkvāthe kulatthaje taptaṃ taptaṃ punarvajraṃ bhavedbhasma trisaptadhā"},{"type":"verse","number":"245","sanskrit":"मेषशृङ्गभुजङ्गास्थिकूर्मपृष्ठाम्लवेतसान्","text":"meṣaśṛṅgabhujaṅgāsthikūrmapṛṣṭhāmlavetasān"},{"type":"verse","number":"246","sanskrit":"शशदन्तं समं पिष्ट्वा वज्रीक्षीरेण गोलकम् कृत्वा तन्मध्यगं वज्रं म्रियते ध्मातमेव हि","text":"śaśadantaṃ samaṃ piṣṭvā vajrīkṣīreṇa golakam kṛtvā tanmadhyagaṃ vajraṃ mriyate dhmātameva hi"},{"type":"verse","number":"247","sanskrit":"आयुः पुष्टिं बलं वीर्यं वर्णं सौख्यं करोति च सेवितं सर्वरोगघ्नं मृतं वज्रं न संशयः","text":"āyuḥ puṣṭiṃ balaṃ vīryaṃ varṇaṃ saukhyaṃ karoti ca sevitaṃ sarvarogaghnaṃ mṛtaṃ vajraṃ na saṃśayaḥ"},{"type":"verse","number":"248","sanskrit":"वज्रवत्सर्वरत्नानि शोधयेन्मारयेत्तथा शुद्धानां मारितानाञ्च तेषां शृणु गुणानपि","text":"vajravatsarvaratnāni śodhayenmārayettathā śuddhānāṃ māritānāñca teṣāṃ śṛṇu guṇānapi"},{"type":"verse","number":"249","sanskrit":"मणयो वीर्यतः शीता मधुरास्तुवरा रसात् चक्षुष्या लेखनाश्चापि सारका विषहारकाः धारणात्ते तु मङ्गल्या ग्रहदृष्टिहरा अपि","text":"maṇayo vīryataḥ śītā madhurāstuvarā rasāt cakṣuṣyā lekhanāścāpi sārakā viṣahārakāḥ dhāraṇātte tu maṅgalyā grahadṛṣṭiharā api"},{"type":"verse","number":"250","sanskrit":"सिन्धुवारसदृक्पत्रो वत्सनाभ्याकृतिस्तथा यत्पार्श्वे न तरोर्वृद्धिर्वत्सनाभः स भाषितः","text":"sindhuvārasadṛkpatro vatsanābhyākṛtistathā yatpārśve na tarorvṛddhirvatsanābhaḥ sa bhāṣitaḥ"},{"type":"verse","number":"251","sanskrit":"गोमूत्रे त्रिदिनं स्थाप्यं विषं तेन विशुद्ध्य्ति रक्तसर्षपतैलाक्ते तथा धार्यञ्च वाससि","text":"gomūtre tridinaṃ sthāpyaṃ viṣaṃ tena viśuddhyti raktasarṣapatailākte tathā dhāryañca vāsasi"},{"type":"verse","number":"252","sanskrit":"ये गुणा गरले प्रोक्तास्ते स्युर्हीना विशोधनात् तस्माद्विषं प्रयोगे तु शोधयित्वा प्रयोजयेत्","text":"ye guṇā garale proktāste syurhīnā viśodhanāt tasmādviṣaṃ prayoge tu śodhayitvā prayojayet"},{"type":"verse","number":"253","sanskrit":"विषं प्राणहरं प्रोक्तं व्यवायि च विकाशि च आग्नेयं वातकफहृद्योगवाहि मदावहम्","text":"viṣaṃ prāṇaharaṃ proktaṃ vyavāyi ca vikāśi ca āgneyaṃ vātakaphahṛdyogavāhi madāvaham"},{"type":"verse","number":"254","sanskrit":"तदेव युक्तियुक्तन्तु प्राणदायि रसायनम् योगवाहि परं वातश्लेष्मजित्सन्निपातहृत्","text":"tadeva yuktiyuktantu prāṇadāyi rasāyanam yogavāhi paraṃ vātaśleṣmajitsannipātahṛt"},{"type":"verse","number":"255","sanskrit":"अर्कक्षीरं स्नुहीक्षीरं लाङ्गली करवीरकः गुञ्जाऽहिफेनो धत्तूरः सप्तोपविषजातयः","text":"arkakṣīraṃ snuhīkṣīraṃ lāṅgalī karavīrakaḥ guñjā'hipheno dhattūraḥ saptopaviṣajātayaḥ"},{"type":"verse","number":"256","sanskrit":"गुणहीनं भवेद्वर्षादूर्ध्वं तद्रू पमौषधम् मासद्वयात्तथा चूर्णं लभते हीनवीर्यताम्","text":"guṇahīnaṃ bhavedvarṣādūrdhvaṃ tadrū pamauṣadham māsadvayāttathā cūrṇaṃ labhate hīnavīryatām"},{"type":"verse","number":"257","sanskrit":"हीनत्वं गुटिकालेहौ लभेते वत्सरं यदि हीनाः स्युर्घृततैलाद्याश्चतुर्मासाधिकास्तथा","text":"hīnatvaṃ guṭikālehau labhete vatsaraṃ yadi hīnāḥ syurghṛtatailādyāścaturmāsādhikāstathā"},{"type":"verse","number":"258","sanskrit":"घृतमब्दात्परं पक्वं हीनवीर्यत्वमाप्नुयात् तैलं पक्वमपक्वञ्च चिरस्थायि गुणाधिकम्","text":"ghṛtamabdātparaṃ pakvaṃ hīnavīryatvamāpnuyāt tailaṃ pakvamapakvañca cirasthāyi guṇādhikam"},{"type":"verse","number":"259","sanskrit":"ओषध्यो लघुपाकाः स्युर्निर्वीर्या वत्सरात्परम् पुराणाः स्युर्गुणैर्युक्ता आसवा धातवो रसाः","text":"oṣadhyo laghupākāḥ syurnirvīryā vatsarātparam purāṇāḥ syurguṇairyuktā āsavā dhātavo rasāḥ"},{"type":"verse","number":"260","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे परिभाषादिप्रकरणे तृतीयं धात्वादिशोधनमारणविधिप्रकरणं समाप्तम् ३","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe paribhāṣādiprakaraṇe tṛtīyaṃ dhātvādiśodhanamāraṇavidhiprakaraṇaṃ samāptam 3"}]},{"sthana":"Пурвакханда","number":9,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 4"},{"type":"verse","number":"1","sanskrit":"स्नेहश्चतुर्विधः प्रोक्तो घृतं तैलं वसा तथा मज्जा च तं पिवेन्मर्त्यः किञ्चिदभ्युदिते रवौ","text":"snehaścaturvidhaḥ prokto ghṛtaṃ tailaṃ vasā tathā majjā ca taṃ pivenmartyaḥ kiñcidabhyudite ravau"},{"type":"verse","number":"2","sanskrit":"स्थावरो जङ्गमश्चैव द्वियोनिः स्नेह उच्यते तिलतैलं स्थावरेषु जङ्गमेषु घृतं वरम् द्वाभ्यां त्रिभिश्चतुर्भिर्वा यमकस्रिवृतो महान्","text":"sthāvaro jaṅgamaścaiva dviyoniḥ sneha ucyate tilatailaṃ sthāvareṣu jaṅgameṣu ghṛtaṃ varam dvābhyāṃ tribhiścaturbhirvā yamakasrivṛto mahān"},{"type":"verse","number":"3","sanskrit":"पिबेत् त्र्! यहं चतुरहं पञ्चाहं षडहानि वा","text":"pibet tr! yahaṃ caturahaṃ pañcāhaṃ ṣaḍahāni vā"},{"type":"verse","number":"4","sanskrit":"दोषकालवयोवह्निबलान्यालोक्य योजयेत् हीनाञ्चमध्यमां ज्येष्ठां मात्रां स्नेहस्य बुद्धिमान्","text":"doṣakālavayovahnibalānyālokya yojayet hīnāñcamadhyamāṃ jyeṣṭhāṃ mātrāṃ snehasya buddhimān"},{"type":"verse","number":"5","sanskrit":"अमात्रया तथाऽकाले मिथ्याऽहारविहारतः स्नेहः करोति शोथार्शस्तन्द्रा निद्रा विसंज्ञताः","text":"amātrayā tathā'kāle mithyā'hāravihārataḥ snehaḥ karoti śothārśastandrā nidrā visaṃjñatāḥ"},{"type":"verse","number":"6","sanskrit":"देया दीप्ताग्नये मात्रा स्नेहस्यैकपलोन्मिता मध्यमाय त्रिकर्षा स्याज्जघन्याय द्विकार्षिकी","text":"deyā dīptāgnaye mātrā snehasyaikapalonmitā madhyamāya trikarṣā syājjaghanyāya dvikārṣikī"},{"type":"verse","number":"7","sanskrit":"अथवा स्नेहमात्राः स्युस्तिस्रोऽन्या सर्वसम्मताः अहोरात्रेण महती जीर्यत्यह्नि तु मध्यमा जीर्यत्यल्पा दिनार्द्धेन सा विज्ञेया सुखावहा","text":"athavā snehamātrāḥ syustisro'nyā sarvasammatāḥ ahorātreṇa mahatī jīryatyahni tu madhyamā jīryatyalpā dinārddhena sā vijñeyā sukhāvahā"},{"type":"verse","number":"8","sanskrit":"अल्पा स्याद्दीपनी वृष्या स्वल्पदोषे प्रपूजिता","text":"alpā syāddīpanī vṛṣyā svalpadoṣe prapūjitā"},{"type":"verse","number":"9","sanskrit":"मध्यमा स्नेहनी ज्ञेया वृंहणी भ्रमहारिणी ज्येष्ठा कुष्ठविषोन्मादग्रहापस्मारनाशिनी","text":"madhyamā snehanī jñeyā vṛṃhaṇī bhramahāriṇī jyeṣṭhā kuṣṭhaviṣonmādagrahāpasmāranāśinī"},{"type":"verse","number":"10","sanskrit":"या मात्रा प्रथमे यामे गते जीर्यति वासरे सा मात्रा दीपयत्यग्निमल्पदोषे च पूजिता","text":"yā mātrā prathame yāme gate jīryati vāsare sā mātrā dīpayatyagnimalpadoṣe ca pūjitā"},{"type":"verse","number":"11","sanskrit":"या मात्रा वासरस्यार्द्धे व्यतीते परिजीर्यति सा वृष्या बृंहणी च स्यान्मध्यदोषे प्रपूजिता","text":"yā mātrā vāsarasyārddhe vyatīte parijīryati sā vṛṣyā bṛṃhaṇī ca syānmadhyadoṣe prapūjitā"},{"type":"verse","number":"12","sanskrit":"या मात्रा चरमे यामे स्थितेऽह्न परिजीर्यति सा मात्रा स्नेहनी ज्ञेया बहुदोषेषु पूजिता","text":"yā mātrā carame yāme sthite'hna parijīryati sā mātrā snehanī jñeyā bahudoṣeṣu pūjitā"},{"type":"verse","number":"13","sanskrit":"केवलं पैत्तिके सर्पिर्वातिके लवणान्वितम् देयं वहुकफे वह्निव्योषक्षारसमन्वितम्","text":"kevalaṃ paittike sarpirvātike lavaṇānvitam deyaṃ vahukaphe vahnivyoṣakṣārasamanvitam"},{"type":"verse","number":"14","sanskrit":"रूक्षक्षतविषार्त्तानां वातपित्तविकारिणाम् हीनमेधास्मृतीनां च सर्पिष्पानं प्रशस्यते","text":"rūkṣakṣataviṣārttānāṃ vātapittavikāriṇām hīnamedhāsmṛtīnāṃ ca sarpiṣpānaṃ praśasyate"},{"type":"verse","number":"15","sanskrit":"कृमिकोष्ठानिलाविष्टाः प्रवृद्धकफमेदसः पिबेयुस्तैलसात्म्याश्च तैलं दार्ढ्यार्थिनस्तु ये","text":"kṛmikoṣṭhānilāviṣṭāḥ pravṛddhakaphamedasaḥ pibeyustailasātmyāśca tailaṃ dārḍhyārthinastu ye"},{"type":"verse","number":"16","sanskrit":"व्यायामकर्षिताः शुष्करेतोरक्ता महारुजः महाग्निमारुतप्राणा वसायोग्या नराः स्मृताः","text":"vyāyāmakarṣitāḥ śuṣkaretoraktā mahārujaḥ mahāgnimārutaprāṇā vasāyogyā narāḥ smṛtāḥ"},{"type":"verse","number":"17","sanskrit":"क्रूराशयाः क्लेशसहा वातार्त्ता दीप्तवह्नयः मज्जानञ्च पिबेयुस्ते सर्पिर्वा सर्वतो हितम्","text":"krūrāśayāḥ kleśasahā vātārttā dīptavahnayaḥ majjānañca pibeyuste sarpirvā sarvato hitam"},{"type":"verse","number":"18","sanskrit":"शीतकाले दिवा स्नेहमुष्णकाले पिबेन्निशि वातपित्ताधिके रात्रौ वातश्लेष्माधिके दिवा","text":"śītakāle divā snehamuṣṇakāle pibenniśi vātapittādhike rātrau vātaśleṣmādhike divā"},{"type":"verse","number":"19","sanskrit":"नस्याभ्यज्जनगण्डूषमूर्ध्वकर्णाक्षितर्पणे तैलं घृतं वा युञ्जीत दृष्ट्वा दोषबलाबलम्","text":"nasyābhyajjanagaṇḍūṣamūrdhvakarṇākṣitarpaṇe tailaṃ ghṛtaṃ vā yuñjīta dṛṣṭvā doṣabalābalam"},{"type":"verse","number":"20","sanskrit":"घृते कोष्णं जलं पेयं तैले यूषः प्रशस्यते वसामज्ज्ञोः पिबेन्मण्डमनुपानं सुखावहम्","text":"ghṛte koṣṇaṃ jalaṃ peyaṃ taile yūṣaḥ praśasyate vasāmajjñoḥ pibenmaṇḍamanupānaṃ sukhāvaham"},{"type":"verse","number":"21","sanskrit":"स्नेहद्विषः शिशून्वृद्धान्सुकुमारान्कृशानपि तृष्णालुकानुष्णकाले सह भक्तेन पाययेत्","text":"snehadviṣaḥ śiśūnvṛddhānsukumārānkṛśānapi tṛṣṇālukānuṣṇakāle saha bhaktena pāyayet"},{"type":"verse","number":"22","sanskrit":"सर्पिष्मती बहुतिला यवागूः स्वल्पतण्डुला सुखोष्णा सेव्यमाना तु सद्यः स्नेहनकारिणी","text":"sarpiṣmatī bahutilā yavāgūḥ svalpataṇḍulā sukhoṣṇā sevyamānā tu sadyaḥ snehanakāriṇī"},{"type":"verse","number":"23","sanskrit":"शर्कराचूर्णसंयुक्ते दोहनस्थे घृते तु गाम् दुग्ध्वा क्षीरं पिबेद्रू क्षः सद्यः स्नेहनमुत्तमम्","text":"śarkarācūrṇasaṃyukte dohanasthe ghṛte tu gām dugdhvā kṣīraṃ pibedrū kṣaḥ sadyaḥ snehanamuttamam"},{"type":"verse","number":"24","sanskrit":"मिथ्याऽचाराद् बहुत्वाच्च यस्य स्नेहो न जीर्यति विष्टभ्य वाऽपि जीर्येत वारिणोष्णेन वामयेत्","text":"mithyā'cārād bahutvācca yasya sneho na jīryati viṣṭabhya vā'pi jīryeta vāriṇoṣṇena vāmayet"},{"type":"verse","number":"25","sanskrit":"स्नेहस्याजीर्णशङ्कायां पिबेदुष्णोदकं नरः तेनोद्गारो भवेच्छुद्धो भक्तं प्रति रुचिस्तथा","text":"snehasyājīrṇaśaṅkāyāṃ pibeduṣṇodakaṃ naraḥ tenodgāro bhavecchuddho bhaktaṃ prati rucistathā"},{"type":"verse","number":"26","sanskrit":"स्नेहेन पैत्तिकस्याग्निर्यदा तीक्ष्णतरीकृतः तदाऽस्योदीरयेत् तृष्णां विषमां तस्य पाययेत् शीतलं पायसं तेन तृष्णा तस्य प्रशाम्यति","text":"snehena paittikasyāgniryadā tīkṣṇatarīkṛtaḥ tadā'syodīrayet tṛṣṇāṃ viṣamāṃ tasya pāyayet śītalaṃ pāyasaṃ tena tṛṣṇā tasya praśāmyati"},{"type":"verse","number":"27","sanskrit":"अजीर्णी वर्जयेत्स्नेहमुदरी तरुणज्वरी दुर्बलोऽरोचकी स्थूलो मूर्च्छालो मेहपीडितः","text":"ajīrṇī varjayetsnehamudarī taruṇajvarī durbalo'rocakī sthūlo mūrcchālo mehapīḍitaḥ"},{"type":"verse","number":"28","sanskrit":"दत्तवस्तिविरिक्तश्च वान्तस्तृष्णाश्रमान्वितः अकालप्रसवा नारी दुर्दिने च विवर्जयेत्","text":"dattavastiviriktaśca vāntastṛṣṇāśramānvitaḥ akālaprasavā nārī durdine ca vivarjayet"},{"type":"verse","number":"29","sanskrit":"स्वेद्यसंशोध्यमद्यस्त्रीव्यायामासक्तचित्तकाः","text":"svedyasaṃśodhyamadyastrīvyāyāmāsaktacittakāḥ"},{"type":"verse","number":"30","sanskrit":"वृद्धबालकृशा रूक्षाः क्षीणास्राः क्षीणरेतसः वातार्त्तास्तिमिरार्त्ता ये तेषां स्नेहनमुत्तमम्","text":"vṛddhabālakṛśā rūkṣāḥ kṣīṇāsrāḥ kṣīṇaretasaḥ vātārttāstimirārttā ye teṣāṃ snehanamuttamam"},{"type":"verse","number":"31","sanskrit":"वातानुलोम्यं दीप्ताग्निर्वर्चः स्निग्धमसंहतम् मृदुस्निग्धाङ्गताऽग्लानिः स्नेहद्वेषोऽथ लाघवम् विमलेन्द्रि यता सम्यक् स्निग्धे रूक्षे विपर्ययः","text":"vātānulomyaṃ dīptāgnirvarcaḥ snigdhamasaṃhatam mṛdusnigdhāṅgatā'glāniḥ snehadveṣo'tha lāghavam vimalendri yatā samyak snigdhe rūkṣe viparyayaḥ"},{"type":"verse","number":"32","sanskrit":"भक्तद्वेषो मुखस्रावो गुदे दाहः प्रवाहिका तन्द्रा ऽतीसारपाण्डुत्वं भृशं स्निग्धस्य लक्षणम्","text":"bhaktadveṣo mukhasrāvo gude dāhaḥ pravāhikā tandrā 'tīsārapāṇḍutvaṃ bhṛśaṃ snigdhasya lakṣaṇam"},{"type":"verse","number":"33","sanskrit":"रूक्षस्य स्नेहनं स्नेहैरतिस्निग्धस्य रूक्षणम् श्यामाकचणकाद्यैश्च तक्रपिण्याकसक्तुभिः","text":"rūkṣasya snehanaṃ snehairatisnigdhasya rūkṣaṇam śyāmākacaṇakādyaiśca takrapiṇyākasaktubhiḥ"},{"type":"verse","number":"34","sanskrit":"दीप्ताग्निः शुद्धकोष्ठश्च पुष्टधातुर्दृढेन्द्रि यः निर्जरो बलवर्णाढ्यः स्नेहसेवी भवेन्नरः","text":"dīptāgniḥ śuddhakoṣṭhaśca puṣṭadhāturdṛḍhendri yaḥ nirjaro balavarṇāḍhyaḥ snehasevī bhavennaraḥ"},{"type":"verse","number":"35","sanskrit":"स्नेहे व्यायामसंशीतवेगाघातप्रजागरान् दिवास्वप्नमभिष्यन्दि रूक्षान्नञ्च विवर्जयेत्","text":"snehe vyāyāmasaṃśītavegāghātaprajāgarān divāsvapnamabhiṣyandi rūkṣānnañca vivarjayet"},{"type":"verse","number":"36","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे परिभाषादिप्रकरणे चतुर्थं स्नेहपानविधिप्रकरणं समाप्तम् ४","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe paribhāṣādiprakaraṇe caturthaṃ snehapānavidhiprakaraṇaṃ samāptam 4"}]},{"sthana":"Пурвакханда","number":10,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 5"},{"type":"verse","number":"1","sanskrit":"प्रथमं वमनं पश्चाद्विरेकश्चानुवासनम् एतानि पञ्चकर्माणि निरूहो नावनं तथा","text":"prathamaṃ vamanaṃ paścādvirekaścānuvāsanam etāni pañcakarmāṇi nirūho nāvanaṃ tathā"},{"type":"verse","number":"2","sanskrit":"शरत्काले वसन्ते च प्रावृट्काले च देहिनाम् वमनं रेचनं चैव कारयेत्कुशलो भिषक्","text":"śaratkāle vasante ca prāvṛṭkāle ca dehinām vamanaṃ recanaṃ caiva kārayetkuśalo bhiṣak"},{"type":"verse","number":"3","sanskrit":"बलवन्तं कफव्याप्तं हृल्लासादिनिपीडितम् तथा वमनसात्म्यञ्च धीरचित्तञ्च वामयेत्","text":"balavantaṃ kaphavyāptaṃ hṛllāsādinipīḍitam tathā vamanasātmyañca dhīracittañca vāmayet"},{"type":"verse","number":"4","sanskrit":"विषदोषे स्तन्यरोगे मन्देऽग्नौ श्लीपदेऽबुदे हृद्रो गे कुष्ठवीसर्पमेहाजीर्णभ्रमेषु च","text":"viṣadoṣe stanyaroge mande'gnau ślīpade'bude hṛdro ge kuṣṭhavīsarpamehājīrṇabhrameṣu ca"},{"type":"verse","number":"5","sanskrit":"विदारिकाऽपचीकासश्वासपीनसवृद्धिषु अपस्मारे ज्वरोन्मादे तथा रक्तातिसारिषु","text":"vidārikā'pacīkāsaśvāsapīnasavṛddhiṣu apasmāre jvaronmāde tathā raktātisāriṣu"},{"type":"verse","number":"6","sanskrit":"नासाताल्वोष्ठपाकेषु कर्णस्रावेऽधिजिह्वके गलशुण्ड्यामतीसारे पित्तश्लेष्मगदे तथा मेदोगदेऽरुचौ चैव वमनं कारयेद्भिषक्","text":"nāsātālvoṣṭhapākeṣu karṇasrāve'dhijihvake galaśuṇḍyāmatīsāre pittaśleṣmagade tathā medogade'rucau caiva vamanaṃ kārayedbhiṣak"},{"type":"verse","number":"7","sanskrit":"न वामनीयस्तिमिरी न गुल्मी नोदरी कृशः नातिवृद्धो गर्भिणी च न स्थूलो न क्षतातुरः","text":"na vāmanīyastimirī na gulmī nodarī kṛśaḥ nātivṛddho garbhiṇī ca na sthūlo na kṣatāturaḥ"},{"type":"verse","number":"8","sanskrit":"मदार्त्तो बालको रूक्षः क्षुधितश्च निरूहितः उदावत्तर्यूर्ध्वरक्ती च दुश्छर्द्यः केवलानिली","text":"madārtto bālako rūkṣaḥ kṣudhitaśca nirūhitaḥ udāvattaryūrdhvaraktī ca duśchardyaḥ kevalānilī"},{"type":"verse","number":"9","sanskrit":"पाण्डुरोगी कृमिव्याप्तः पवनात्स्वरघातवान्","text":"pāṇḍurogī kṛmivyāptaḥ pavanātsvaraghātavān"},{"type":"verse","number":"10","sanskrit":"एतेऽप्यजीर्णव्यथिता वाम्या ये विषपीडिताः कफव्याप्ताश्च ते वाम्या मधुकक्वाथपानतः","text":"ete'pyajīrṇavyathitā vāmyā ye viṣapīḍitāḥ kaphavyāptāśca te vāmyā madhukakvāthapānataḥ"},{"type":"verse","number":"11","sanskrit":"सुकुमारं कृशं बालं वृद्धं भीरुञ्च वामयेत् पाययित्वा यवागूं वा क्षीरतक्रदधीनि च","text":"sukumāraṃ kṛśaṃ bālaṃ vṛddhaṃ bhīruñca vāmayet pāyayitvā yavāgūṃ vā kṣīratakradadhīni ca"},{"type":"verse","number":"12","sanskrit":"असात्म्यैः श्लेष्मलैर्भोज्यैर्दोषानुत्क्लेश्य देहिनाम् स्निग्धस्विन्नाय वमनं दत्तं सम्यक्प्रवर्त्तते","text":"asātmyaiḥ śleṣmalairbhojyairdoṣānutkleśya dehinām snigdhasvinnāya vamanaṃ dattaṃ samyakpravarttate"},{"type":"verse","number":"13","sanskrit":"वमनेषु च सर्वेषु सैन्धवं मधु वा हितम् वीभत्सं वमनं दद्याद्विपरीतं विरेचनम्","text":"vamaneṣu ca sarveṣu saindhavaṃ madhu vā hitam vībhatsaṃ vamanaṃ dadyādviparītaṃ virecanam"},{"type":"verse","number":"14","sanskrit":"क्वाथद्र व्यस्य कुडवं श्रपयित्वा जलाढके अर्द्धभागावशिष्टञ्च वमनेष्ववचारयेत्","text":"kvāthadra vyasya kuḍavaṃ śrapayitvā jalāḍhake arddhabhāgāvaśiṣṭañca vamaneṣvavacārayet"},{"type":"verse","number":"15","sanskrit":"क्वाथपाने नवप्रस्था ज्येष्ठा मात्रा प्रकीर्त्तिता मध्यमा षण्मिता प्रोक्ता त्रिप्रस्था च कनीयसी","text":"kvāthapāne navaprasthā jyeṣṭhā mātrā prakīrttitā madhyamā ṣaṇmitā proktā triprasthā ca kanīyasī"},{"type":"verse","number":"16","sanskrit":"वमने च विरेके च तथा शोणितमोक्षणे अर्द्धत्रयोदशपलं प्रस्थमाहुर्मनीषिणः","text":"vamane ca vireke ca tathā śoṇitamokṣaṇe arddhatrayodaśapalaṃ prasthamāhurmanīṣiṇaḥ"},{"type":"verse","number":"17","sanskrit":"कल्कचूर्णावलेहानां त्रिपलं मात्रयोत्तमम् मध्यमं द्विपलं विद्यात्कनीयस्तु पलं भवेत्","text":"kalkacūrṇāvalehānāṃ tripalaṃ mātrayottamam madhyamaṃ dvipalaṃ vidyātkanīyastu palaṃ bhavet"},{"type":"verse","number":"18","sanskrit":"वमने चाष्टवेगाःस्युः पित्तान्ता उत्तमास्तु ते षड् वेगा मध्यमा वेगाश्चत्वारस्त्वपरे मताः","text":"vamane cāṣṭavegāḥsyuḥ pittāntā uttamāstu te ṣaḍ vegā madhyamā vegāścatvārastvapare matāḥ"},{"type":"verse","number":"19","sanskrit":"कफं कटुकतीक्ष्णोष्णैः पित्तं स्वादुहिमैर्जयेत् सुस्वादुलवणाम्लोष्णैः संसृष्टं वायुना कफम्","text":"kaphaṃ kaṭukatīkṣṇoṣṇaiḥ pittaṃ svāduhimairjayet susvādulavaṇāmloṣṇaiḥ saṃsṛṣṭaṃ vāyunā kapham"},{"type":"verse","number":"20","sanskrit":"कृष्णां राठफलं सिन्धुं कफे कोष्णजलैः पिबेत् पटोलवासानिम्बांश्च पित्ते शीतजलैः पिबेत्","text":"kṛṣṇāṃ rāṭhaphalaṃ sindhuṃ kaphe koṣṇajalaiḥ pibet paṭolavāsānimbāṃśca pitte śītajalaiḥ pibet"},{"type":"verse","number":"21","sanskrit":"सश्लेष्मवातपीडायां सक्षीरं मदनं पिबेत् अजीर्णे कोष्णपानीयं सिन्धुं पीत्वा वमेत्सुधीः","text":"saśleṣmavātapīḍāyāṃ sakṣīraṃ madanaṃ pibet ajīrṇe koṣṇapānīyaṃ sindhuṃ pītvā vametsudhīḥ"},{"type":"verse","number":"22","sanskrit":"वमनं पाययित्वा तु जानुमात्रासने स्थितम् कण्ठमेरण्डनालेन स्पृशन्तं वामयेद्भिषक्","text":"vamanaṃ pāyayitvā tu jānumātrāsane sthitam kaṇṭhameraṇḍanālena spṛśantaṃ vāmayedbhiṣak"},{"type":"verse","number":"23","sanskrit":"प्रसेको हृद्ग्रहः कोठः कण्डूर्दुश्छर्दिते भवेत् अतिवान्ते भवेत्तृष्णा हिक्कोद्गारो विसंज्ञिता","text":"praseko hṛdgrahaḥ koṭhaḥ kaṇḍūrduśchardite bhavet ativānte bhavettṛṣṇā hikkodgāro visaṃjñitā"},{"type":"verse","number":"24","sanskrit":"जिह्वानिःसरणं चाक्ष्णोर्व्यावृत्तिर्हनुसंहतिः रक्तच्छर्दिः ष्ठीवनञ्च कण्ठपीडा च जायते","text":"jihvāniḥsaraṇaṃ cākṣṇorvyāvṛttirhanusaṃhatiḥ raktacchardiḥ ṣṭhīvanañca kaṇṭhapīḍā ca jāyate"},{"type":"verse","number":"25","sanskrit":"वमनस्यातियोगे तु मृदु कुर्याद्विरेचनम् वमनेन प्रविष्टायां जिह्वायां कवलग्रहाः स्निग्धाम्ललवणैर्युक्तैर्घृतक्षीररसैर्हिताः","text":"vamanasyātiyoge tu mṛdu kuryādvirecanam vamanena praviṣṭāyāṃ jihvāyāṃ kavalagrahāḥ snigdhāmlalavaṇairyuktairghṛtakṣīrarasairhitāḥ"},{"type":"verse","number":"26","sanskrit":"फलान्यम्लानि खादेयुस्तस्य चान्येऽग्रतो नराः निःसृतान्तु तिलद्रा क्षाकल्कलिप्तां प्रवेशयेत्","text":"phalānyamlāni khādeyustasya cānye'grato narāḥ niḥsṛtāntu tiladrā kṣākalkaliptāṃ praveśayet"},{"type":"verse","number":"27","sanskrit":"व्यावृत्तेऽक्ष्णि घृताभ्यक्तेपीडनञ्च शनेः शनैः हनुमोक्षे स्मृतः स्वेदो नस्यञ्च श्लेष्मवातहृत्","text":"vyāvṛtte'kṣṇi ghṛtābhyaktepīḍanañca śaneḥ śanaiḥ hanumokṣe smṛtaḥ svedo nasyañca śleṣmavātahṛt"},{"type":"verse","number":"28","sanskrit":"रक्तपित्तविधानेन रक्तष्ठीवमुपाचरेत् धात्रीरसाञ्जनोशीरलाजाचन्दनवारिभिः","text":"raktapittavidhānena raktaṣṭhīvamupācaret dhātrīrasāñjanośīralājācandanavāribhiḥ"},{"type":"verse","number":"29","sanskrit":"मन्थंकृत्वा पाययेच्च सघृतं क्षौरद्र शर्करम् शाम्यन्त्यनेन तृष्णाऽद्या रोगाश्छर्दिसमुद्भवाः","text":"manthaṃkṛtvā pāyayecca saghṛtaṃ kṣauradra śarkaram śāmyantyanena tṛṣṇā'dyā rogāśchardisamudbhavāḥ"},{"type":"verse","number":"30","sanskrit":"हृत्कण्ठशिरसां शुद्धिर्दीप्ताग्नित्वञ्च लाघवम् कफपित्तविनाशश्च सम्यग्वान्तस्य लक्षणम्","text":"hṛtkaṇṭhaśirasāṃ śuddhirdīptāgnitvañca lāghavam kaphapittavināśaśca samyagvāntasya lakṣaṇam"},{"type":"verse","number":"31","sanskrit":"ततोऽपराह्णे दीप्ताग्निं मुद्गषष्टिकशालिभिः हृद्यैश्च जाङ्गलरसैः कृत्वा यूषञ्च भोजयेत्","text":"tato'parāhṇe dīptāgniṃ mudgaṣaṣṭikaśālibhiḥ hṛdyaiśca jāṅgalarasaiḥ kṛtvā yūṣañca bhojayet"},{"type":"verse","number":"32","sanskrit":"तन्द्रा निद्रा ऽस्यदौर्गन्ध्यं कण्डूश्च ग्रहणी विषम् सुवान्तस्य न पीडायै भवन्त्येते कदाचन","text":"tandrā nidrā 'syadaurgandhyaṃ kaṇḍūśca grahaṇī viṣam suvāntasya na pīḍāyai bhavantyete kadācana"},{"type":"verse","number":"33","sanskrit":"अजीर्णं शीतपानीयं व्यायामं मैथुनं तथा स्नेहाभ्यङ्गञ्च रोषञ्च दिनमेकं सुधीस्त्यजेत्","text":"ajīrṇaṃ śītapānīyaṃ vyāyāmaṃ maithunaṃ tathā snehābhyaṅgañca roṣañca dinamekaṃ sudhīstyajet"},{"type":"verse","number":"34","sanskrit":"स्निग्धस्विन्नाय वान्ताय दद्यात्सम्यग्विरेचनम् अवान्तस्य त्वधःस्रस्तो ग्रहणीं छादयेत्कफः","text":"snigdhasvinnāya vāntāya dadyātsamyagvirecanam avāntasya tvadhaḥsrasto grahaṇīṃ chādayetkaphaḥ"},{"type":"verse","number":"35","sanskrit":"मन्दाग्निं गौरवं कुर्याज्जनयेद्वा प्रवाहिकाम् अथवा पाचनैरामं वलासं परिपाचयेत्","text":"mandāgniṃ gauravaṃ kuryājjanayedvā pravāhikām athavā pācanairāmaṃ valāsaṃ paripācayet"},{"type":"verse","number":"36","sanskrit":"ऋतौ वसन्ते शरदि देहशुद्धौ विरेचयेत् अन्यदाऽत्ययिके कार्ये शोधनं शीलयेद् बुधः","text":"ṛtau vasante śaradi dehaśuddhau virecayet anyadā'tyayike kārye śodhanaṃ śīlayed budhaḥ"},{"type":"verse","number":"37","sanskrit":"पित्ते विरेचनं युञ्ज्यादामोद्भूते गदे तथा उदरे च तथाऽध्माने कोष्ठशुद्धौ विशेषतः","text":"pitte virecanaṃ yuñjyādāmodbhūte gade tathā udare ca tathā'dhmāne koṣṭhaśuddhau viśeṣataḥ"},{"type":"verse","number":"38","sanskrit":"दोषाः कादाचित्कुप्यन्ति जिता लङ्घनपाचनैः शोधनैः शोधिता ये तु न तेषां पुनरुद्भवः","text":"doṣāḥ kādācitkupyanti jitā laṅghanapācanaiḥ śodhanaiḥ śodhitā ye tu na teṣāṃ punarudbhavaḥ"},{"type":"verse","number":"39","sanskrit":"बालो वृद्धो भृशं स्निग्धः क्षतक्षीणो भयान्वितः श्रान्तस्तृषाऽत्त स्थूलश्च गर्भिणी च नवज्वरी","text":"bālo vṛddho bhṛśaṃ snigdhaḥ kṣatakṣīṇo bhayānvitaḥ śrāntastṛṣā'tta sthūlaśca garbhiṇī ca navajvarī"},{"type":"verse","number":"40","sanskrit":"नवप्रसूता नारी च मन्दाग्निश्च मदात्ययी शल्यार्दितश्च रूक्षश्च न विरेच्या विजानता","text":"navaprasūtā nārī ca mandāgniśca madātyayī śalyārditaśca rūkṣaśca na virecyā vijānatā"},{"type":"verse","number":"41","sanskrit":"जीर्णज्वरी गरव्याप्तो वातरोगी भगन्दरी अर्शः पाण्डूदरग्रन्थिहृद्रो गारुचिपीडिताः","text":"jīrṇajvarī garavyāpto vātarogī bhagandarī arśaḥ pāṇḍūdaragranthihṛdro gārucipīḍitāḥ"},{"type":"verse","number":"42","sanskrit":"योनिरोगप्रमेहार्त्ता गुल्मप्लीहव्रणार्दिताः विद्र धिच्छर्दिविस्फोटविसूचीकुष्ठसंयुताः","text":"yonirogapramehārttā gulmaplīhavraṇārditāḥ vidra dhicchardivisphoṭavisūcīkuṣṭhasaṃyutāḥ"},{"type":"verse","number":"43","sanskrit":"कर्णनासाशिरोवक्त्रगुदमेढ्रामयान्विताः प्लीहशोथाक्षिरोगार्त्ताः कृमिक्षारानिलार्दिताः","text":"karṇanāsāśirovaktragudameḍhrāmayānvitāḥ plīhaśothākṣirogārttāḥ kṛmikṣārānilārditāḥ"},{"type":"verse","number":"44","sanskrit":"शूलिनो मूत्रघातार्त्ता विरेकार्हा नरा मताः","text":"śūlino mūtraghātārttā virekārhā narā matāḥ"},{"type":"verse","number":"45","sanskrit":"बहुपित्तो मृदुः कोष्ठो बहुश्लेष्मा च मध्यमः बहुवातःक्रूरकोष्ठो दुर्विरेच्यः स कथ्यते","text":"bahupitto mṛduḥ koṣṭho bahuśleṣmā ca madhyamaḥ bahuvātaḥkrūrakoṣṭho durvirecyaḥ sa kathyate"},{"type":"verse","number":"46","sanskrit":"मृद्वी मात्रा मृदौ कोष्ठे मध्यकोष्ठे च मध्यमा क्रूरे तीक्ष्णा मता द्र व्यैर्मृदुमध्यमतीक्ष्णकैः","text":"mṛdvī mātrā mṛdau koṣṭhe madhyakoṣṭhe ca madhyamā krūre tīkṣṇā matā dra vyairmṛdumadhyamatīkṣṇakaiḥ"},{"type":"verse","number":"47","sanskrit":"मृदुद्रा र्क्षा!पयश्चञ्चुतैलैरपि विरिच्यते मध्यमस्त्रिवृतातिक्ताराजवृक्षैर्विरिच्यते क्रूरः स्नुक्पयसा हेमक्षीरीदन्तीफलादिभिः","text":"mṛdudrā rkṣā!payaścañcutailairapi viricyate madhyamastrivṛtātiktārājavṛkṣairviricyate krūraḥ snukpayasā hemakṣīrīdantīphalādibhiḥ"},{"type":"verse","number":"48","sanskrit":"मात्रोत्तमा विरेकस्य त्रिंशद्वेगैः कफान्तिका वेगैर्विंशतिभिर्मध्या हीनोक्ता दशवेगिका","text":"mātrottamā virekasya triṃśadvegaiḥ kaphāntikā vegairviṃśatibhirmadhyā hīnoktā daśavegikā"},{"type":"verse","number":"49","sanskrit":"द्विपलं श्रेष्ठमाख्यातं मध्यमं च पलं भवेत् पलार्द्धं च कषायाणां कनीयस्तु विरेचनम्","text":"dvipalaṃ śreṣṭhamākhyātaṃ madhyamaṃ ca palaṃ bhavet palārddhaṃ ca kaṣāyāṇāṃ kanīyastu virecanam"},{"type":"verse","number":"50","sanskrit":"कल्कमोदकचूर्णानां कर्षो मध्वाज्यलेहतः कर्षद्वयं पलं वाऽपि वयोरोगाद्यपेक्षया","text":"kalkamodakacūrṇānāṃ karṣo madhvājyalehataḥ karṣadvayaṃ palaṃ vā'pi vayorogādyapekṣayā"},{"type":"verse","number":"51","sanskrit":"पित्तोत्तरे त्रिवृच्चूर्णं द्रा क्षाक्वाथादिभिः पिबेत् त्रिफलाक्वाथगोमूत्रैः पिबेद् व्योषं कफार्दितः","text":"pittottare trivṛccūrṇaṃ drā kṣākvāthādibhiḥ pibet triphalākvāthagomūtraiḥ pibed vyoṣaṃ kaphārditaḥ"},{"type":"verse","number":"52","sanskrit":"त्रिवृत्सैन्धवशुण्ठीनां चूर्णमम्लैः पिबन्नेरः वातार्दितो विरेकाय जाङ्गलानां रसेन वा","text":"trivṛtsaindhavaśuṇṭhīnāṃ cūrṇamamlaiḥ pibanneraḥ vātārdito virekāya jāṅgalānāṃ rasena vā"},{"type":"verse","number":"53","sanskrit":"एरण्डतैलं त्रिफलाक्वाथेन द्विगुणेन वा युक्तं पीतं पयोभिर्वा न चिरेण विरिच्यते","text":"eraṇḍatailaṃ triphalākvāthena dviguṇena vā yuktaṃ pītaṃ payobhirvā na cireṇa viricyate"},{"type":"verse","number":"54","sanskrit":"त्रिवृता कौटजं बीजं पिप्पली विश्वभेषजम् समृद्वीकारसं क्षौद्रं वर्षाकाले विरेचनम्","text":"trivṛtā kauṭajaṃ bījaṃ pippalī viśvabheṣajam samṛdvīkārasaṃ kṣaudraṃ varṣākāle virecanam"},{"type":"verse","number":"55","sanskrit":"त्रिवृद्दुरालभामुस्तशर्करोदीच्यचन्दनम् द्रा क्षाऽम्बुना सयष्ट्याह्वं शीतलञ्च घनात्यये","text":"trivṛddurālabhāmustaśarkarodīcyacandanam drā kṣā'mbunā sayaṣṭyāhvaṃ śītalañca ghanātyaye"},{"type":"verse","number":"56","sanskrit":"त्रिवृता चित्रकं पाठामजाजीं सरलं वचाम् हेमक्षीरीं हेमन्ते तु चूर्णमुष्णाम्बुना पिबेत्","text":"trivṛtā citrakaṃ pāṭhāmajājīṃ saralaṃ vacām hemakṣīrīṃ hemante tu cūrṇamuṣṇāmbunā pibet"},{"type":"verse","number":"57","sanskrit":"पिप्पलद्यं नागरं सिन्धुं श्यामां त्रिवृतया सह लिह्यात्क्षौद्रे ण शिशिरे वसन्ते च विरेचनम्","text":"pippaladyaṃ nāgaraṃ sindhuṃ śyāmāṃ trivṛtayā saha lihyātkṣaudre ṇa śiśire vasante ca virecanam"},{"type":"verse","number":"58","sanskrit":"त्रिवृता शर्करा तुल्या ग्रीष्मकाले विरेचनम्","text":"trivṛtā śarkarā tulyā grīṣmakāle virecanam"},{"type":"verse","number":"59","sanskrit":"अथाभयादिमोदकः अभया मरिचं शुण्ठीविडङ्गामलकानि च पिप्पली पिप्पलीमूलं त्वक्पत्रं मुस्तमेव च","text":"athābhayādimodakaḥ abhayā maricaṃ śuṇṭhīviḍaṅgāmalakāni ca pippalī pippalīmūlaṃ tvakpatraṃ mustameva ca"},{"type":"verse","number":"60","sanskrit":"एतानि समभागानि दन्ती तु त्रिगुणा भवेत् त्रिवृताऽष्टगुणा ज्ञेया षड्गुणा चात्र शर्करा","text":"etāni samabhāgāni dantī tu triguṇā bhavet trivṛtā'ṣṭaguṇā jñeyā ṣaḍguṇā cātra śarkarā"},{"type":"verse","number":"61","sanskrit":"मधुना मोदकान्कृत्वा कर्षमात्रान्प्रमाणतः एकैकं भक्षयेत् प्रातः शीतञ्चानु पिबेज्जलम्","text":"madhunā modakānkṛtvā karṣamātrānpramāṇataḥ ekaikaṃ bhakṣayet prātaḥ śītañcānu pibejjalam"},{"type":"verse","number":"62","sanskrit":"तावद्विरिच्यते जन्तुर्यावदुष्णं न सेवते पानाहारविहारेषु भवेन्निर्यन्त्रणः सदा","text":"tāvadviricyate janturyāvaduṣṇaṃ na sevate pānāhāravihāreṣu bhavenniryantraṇaḥ sadā"},{"type":"verse","number":"63","sanskrit":"विषमज्वरमन्दाग्निपाण्डुकासभगन्दरान् दुर्नामकुष्ठगुल्मार्शोगलगण्डोदरभ्रमान्","text":"viṣamajvaramandāgnipāṇḍukāsabhagandarān durnāmakuṣṭhagulmārśogalagaṇḍodarabhramān"},{"type":"verse","number":"64","sanskrit":"विदाहप्लीहमेहांश्च यक्ष्माणं नयनामयान् वातरोगांस्तथाऽध्मानं मूत्रकच्छ्रादि चाश्मरीम्","text":"vidāhaplīhamehāṃśca yakṣmāṇaṃ nayanāmayān vātarogāṃstathā'dhmānaṃ mūtrakacchrādi cāśmarīm"},{"type":"verse","number":"65","sanskrit":"पृष्ठपार्श्वोरुजघनजङ्घोदररुजं जयेत् स्नेहाभ्यङ्गञ्च रोषञ्च दिनमेकं सुधीस्त्यजेत्","text":"pṛṣṭhapārśvorujaghanajaṅghodararujaṃ jayet snehābhyaṅgañca roṣañca dinamekaṃ sudhīstyajet"},{"type":"verse","number":"66","sanskrit":"सततं शीलनादेव पलितानि प्रणाशयेत् अभयामोदका ह्येते रसायनवराः स्मृताः","text":"satataṃ śīlanādeva palitāni praṇāśayet abhayāmodakā hyete rasāyanavarāḥ smṛtāḥ"},{"type":"verse","number":"67","sanskrit":"पीत्वा विरेचनं शीतजलैः संसिच्य चक्षुषी सुगन्धि किच्चिदाघ्राय ताम्बूलं शीलयेद् बुधः","text":"pītvā virecanaṃ śītajalaiḥ saṃsicya cakṣuṣī sugandhi kiccidāghrāya tāmbūlaṃ śīlayed budhaḥ"},{"type":"verse","number":"68","sanskrit":"निर्वातस्थो न वेगांश्च धारयेन्न शयीत च शीताम्बु न स्पृशेत्क्वापि कोष्णनीरं पिबेन्मुहुः","text":"nirvātastho na vegāṃśca dhārayenna śayīta ca śītāmbu na spṛśetkvāpi koṣṇanīraṃ pibenmuhuḥ"},{"type":"verse","number":"69","sanskrit":"वलासौषधपित्तानि वायुर्वान्ते यथा व्रजेत् रेकात्तथा मलं पित्तं भेषजञ्च कफो व्रजेत्","text":"valāsauṣadhapittāni vāyurvānte yathā vrajet rekāttathā malaṃ pittaṃ bheṣajañca kapho vrajet"},{"type":"verse","number":"70","sanskrit":"दुर्विरिक्तस्य नाभेस्तु स्तब्धता कुक्षिशूलरुक् पुरीषवातसङ्गश्च कण्डूमण्डलगौरवम्","text":"durviriktasya nābhestu stabdhatā kukṣiśūlaruk purīṣavātasaṅgaśca kaṇḍūmaṇḍalagauravam"},{"type":"verse","number":"71","sanskrit":"विदाहोऽरुचिराध्मानं भ्रमश्छर्दिश्च जायते तं पुनः पाचनैः स्नेहैः पक्त्वा स्निग्धं तु रेचयेत् तेनास्योपद्र वा यान्ति दीप्ताग्निर्लघुता भवेत्","text":"vidāho'rucirādhmānaṃ bhramaśchardiśca jāyate taṃ punaḥ pācanaiḥ snehaiḥ paktvā snigdhaṃ tu recayet tenāsyopadra vā yānti dīptāgnirlaghutā bhavet"},{"type":"verse","number":"72","sanskrit":"विरेकस्यातियोगेन मूर्च्छा भ्रंशो गुदस्य च शूलं कफातियोगः स्यान्मांसधावनसन्निभम्","text":"virekasyātiyogena mūrcchā bhraṃśo gudasya ca śūlaṃ kaphātiyogaḥ syānmāṃsadhāvanasannibham"},{"type":"verse","number":"73","sanskrit":"मेदोनिभं जलाभासं रक्तश्चापि विरिच्यते तस्य शीताम्बुभिः सिक्त्वा शरीरं तण्डुलाम्बुभिः","text":"medonibhaṃ jalābhāsaṃ raktaścāpi viricyate tasya śītāmbubhiḥ siktvā śarīraṃ taṇḍulāmbubhiḥ"},{"type":"verse","number":"74","sanskrit":"मधुमिश्रैस्तथा शीतैः कारयेद्वमनं मृदु सहकारत्वचः कल्को दध्ना सौवीरकेण वा","text":"madhumiśraistathā śītaiḥ kārayedvamanaṃ mṛdu sahakāratvacaḥ kalko dadhnā sauvīrakeṇa vā"},{"type":"verse","number":"75","sanskrit":"पिष्ट्वा नाभिप्रलेपेन हन्त्यतीसारमुल्वणम् सौवीरं तु यवैरामैः पक्वैर्वा निस्तुषीकृतैः","text":"piṣṭvā nābhipralepena hantyatīsāramulvaṇam sauvīraṃ tu yavairāmaiḥ pakvairvā nistuṣīkṛtaiḥ"},{"type":"verse","number":"76","sanskrit":"अजाक्षीरं रसञ्चापि वैष्किरं हारिणं तथा शालिभिः षष्टिकैस्तुल्यैर्मसूरैर्वापि भोजयेत्","text":"ajākṣīraṃ rasañcāpi vaiṣkiraṃ hāriṇaṃ tathā śālibhiḥ ṣaṣṭikaistulyairmasūrairvāpi bhojayet"},{"type":"verse","number":"77","sanskrit":"शीतैः संग्राहिभिर्द्र व्यैः कुर्यात्संग्रहणं भिषक् लाघवे मनसस्तुष्टावनुलोमं गतेऽनिले","text":"śītaiḥ saṃgrāhibhirdra vyaiḥ kuryātsaṃgrahaṇaṃ bhiṣak lāghave manasastuṣṭāvanulomaṃ gate'nile"},{"type":"verse","number":"78","sanskrit":"सुविरिक्तं नरं ज्ञात्वा पाचनं पाययेन्निशि इन्द्रि याणां बलं बुद्धे प्रसादो वह्निदीप्तता","text":"suviriktaṃ naraṃ jñātvā pācanaṃ pāyayenniśi indri yāṇāṃ balaṃ buddhe prasādo vahnidīptatā"},{"type":"verse","number":"79","sanskrit":"धातुस्थैर्यं वयःस्थैर्यं भवेद्रे चनसेवनात् प्रवातसेवां शीताम्बुस्नेहाभ्यङ्गमजीर्णताम्","text":"dhātusthairyaṃ vayaḥsthairyaṃ bhavedre canasevanāt pravātasevāṃ śītāmbusnehābhyaṅgamajīrṇatām"},{"type":"verse","number":"80","sanskrit":"व्यायामं मैथुनञ्चैव न सेवेत विरेचितः शालिषष्टिकमुद्गाद्यैर्यवागूं भोजयेत्कृताम्","text":"vyāyāmaṃ maithunañcaiva na seveta virecitaḥ śāliṣaṣṭikamudgādyairyavāgūṃ bhojayetkṛtām"},{"type":"verse","number":"81","sanskrit":"जङ्घालविष्किराणां वा रसैः शाल्योदनं हितम्","text":"jaṅghālaviṣkirāṇāṃ vā rasaiḥ śālyodanaṃ hitam"},{"type":"verse","number":"82","sanskrit":"वस्तिर्द्विधाऽनुवासाख्यो निरूहश्च ततः परम् यः स्नेहो दीयते स स्यादनुवासन नामकः","text":"vastirdvidhā'nuvāsākhyo nirūhaśca tataḥ param yaḥ sneho dīyate sa syādanuvāsana nāmakaḥ"},{"type":"verse","number":"83","sanskrit":"कषायक्षीरतैलैर्यो निरूहः स निगद्यते वस्तिभिर्दीयते यस्मात्तस्माद्वस्तिरिति स्मृतः","text":"kaṣāyakṣīratailairyo nirūhaḥ sa nigadyate vastibhirdīyate yasmāttasmādvastiriti smṛtaḥ"},{"type":"verse","number":"84","sanskrit":"तत्रानुवासनाख्यो हि वस्तिर्यः सोऽत्र कथ्यते अनुवासनभेदश्च मात्रावस्तिरुदीरितः","text":"tatrānuvāsanākhyo hi vastiryaḥ so'tra kathyate anuvāsanabhedaśca mātrāvastirudīritaḥ"},{"type":"verse","number":"85","sanskrit":"पलद्वयं तस्य मात्रा तस्मादर्द्धाऽपि वा भवेत् अनुवास्यस्तु रूक्षः स्यात्तीक्ष्णाग्निः केवलानिली","text":"paladvayaṃ tasya mātrā tasmādarddhā'pi vā bhavet anuvāsyastu rūkṣaḥ syāttīkṣṇāgniḥ kevalānilī"},{"type":"verse","number":"86","sanskrit":"नानुवास्यस्तु कुष्ठी स्यान्मेही स्थूलस्तथोदरी नास्थाप्या नानुवास्याश्च जीर्णोन्मादतृडर्दिताः शोथमूर्च्छाऽरुचिभयश्वासकासक्षयातुराः","text":"nānuvāsyastu kuṣṭhī syānmehī sthūlastathodarī nāsthāpyā nānuvāsyāśca jīrṇonmādatṛḍarditāḥ śothamūrcchā'rucibhayaśvāsakāsakṣayāturāḥ"},{"type":"verse","number":"87","sanskrit":"नेत्रं कार्यं सुवर्णादिधातुभिर्वृक्षवेणुभिः नलैर्दन्तैर्विषाणाग्रैर्मणिभिर्वा विधीयते","text":"netraṃ kāryaṃ suvarṇādidhātubhirvṛkṣaveṇubhiḥ nalairdantairviṣāṇāgrairmaṇibhirvā vidhīyate"},{"type":"verse","number":"88","sanskrit":"एकवर्षात्तु षड्वर्षाद्यावन्मानं षडङ्गुलम् ततो द्वादशकं यावन्मानं स्यादष्टसम्मितम्","text":"ekavarṣāttu ṣaḍvarṣādyāvanmānaṃ ṣaḍaṅgulam tato dvādaśakaṃ yāvanmānaṃ syādaṣṭasammitam"},{"type":"verse","number":"89","sanskrit":"ततः परं द्वादशभिरङ्गुलैर्नेत्रदीर्घता मुद्गच्छिद्रं कलायाभं छिद्रं कोलास्थिसन्निमम्","text":"tataḥ paraṃ dvādaśabhiraṅgulairnetradīrghatā mudgacchidraṃ kalāyābhaṃ chidraṃ kolāsthisannimam"},{"type":"verse","number":"90","sanskrit":"यथा संख्यं भवेन्नेत्रं श्लक्ष्णं गोपुच्छसन्निभम् गोपुच्छसन्निमं मूले स्थूलं तस्मात् क्रमात् कृशम्","text":"yathā saṃkhyaṃ bhavennetraṃ ślakṣṇaṃ gopucchasannibham gopucchasannimaṃ mūle sthūlaṃ tasmāt kramāt kṛśam"},{"type":"verse","number":"91","sanskrit":"आतुराङ्गुष्ठमानेन मूले स्थूलं निधीयते कनिष्ठिकापरीणाहमग्रे च गुटिकामुखम्","text":"āturāṅguṣṭhamānena mūle sthūlaṃ nidhīyate kaniṣṭhikāparīṇāhamagre ca guṭikāmukham"},{"type":"verse","number":"92","sanskrit":"तन्मूले कर्णिके द्वे च कार्ये भागाच्चतुर्थकात्","text":"tanmūle karṇike dve ca kārye bhāgāccaturthakāt"},{"type":"verse","number":"93","sanskrit":"योजयेत्तत्र वस्तिञ्च बन्धद्वयविधानतः मृगाजशूकरगवां महिषस्यापि वा भवेत्","text":"yojayettatra vastiñca bandhadvayavidhānataḥ mṛgājaśūkaragavāṃ mahiṣasyāpi vā bhavet"},{"type":"verse","number":"94","sanskrit":"मूत्रकोषस्य वस्तिस्तु तदलाभे तु चर्मणः कषायरक्तः स मृदुर्वस्तिः स्निग्धो दृढो हितः","text":"mūtrakoṣasya vastistu tadalābhe tu carmaṇaḥ kaṣāyaraktaḥ sa mṛdurvastiḥ snigdho dṛḍho hitaḥ"},{"type":"verse","number":"95","sanskrit":"व्रणवस्तेस्तु नेत्रं स्याच्छ्लक्ष्णमष्टाङ्गुलोन्मितम् मुद्गच्छिद्रं गृध्रपक्षनलिकापरिणाहि च","text":"vraṇavastestu netraṃ syācchlakṣṇamaṣṭāṅgulonmitam mudgacchidraṃ gṛdhrapakṣanalikāpariṇāhi ca"},{"type":"verse","number":"96","sanskrit":"शरीरोपचयं वर्णं बलमारोग्यमायुषः कुरुते परिवृद्धिञ्च वस्तिः सम्यगुपासितः","text":"śarīropacayaṃ varṇaṃ balamārogyamāyuṣaḥ kurute parivṛddhiñca vastiḥ samyagupāsitaḥ"},{"type":"verse","number":"97","sanskrit":"दिवा शीते वसन्ते च स्नेहवस्तिः प्रदीयते ग्रीष्मवर्षाशरत्काले रात्रौ स्यादनुवासनम्","text":"divā śīte vasante ca snehavastiḥ pradīyate grīṣmavarṣāśaratkāle rātrau syādanuvāsanam"},{"type":"verse","number":"98","sanskrit":"न चातिस्निग्धमशनं भोजयित्वाऽनुवासयेत् मदं मूर्च्छां च जनयेद् द्विधा स्नेहः प्रयोजितः","text":"na cātisnigdhamaśanaṃ bhojayitvā'nuvāsayet madaṃ mūrcchāṃ ca janayed dvidhā snehaḥ prayojitaḥ"},{"type":"verse","number":"99","sanskrit":"रूक्षभुक्तवतोऽत्यन्तं बलं वर्णञ्च हापयेत् युक्तस्नेहमतो जन्तुं भोजयित्वाऽनुवासयेत्","text":"rūkṣabhuktavato'tyantaṃ balaṃ varṇañca hāpayet yuktasnehamato jantuṃ bhojayitvā'nuvāsayet"},{"type":"verse","number":"100","sanskrit":"हीनमात्रावुभौ वस्ती नातिकार्यकरौ स्मृतौ अतिमात्रौ तथाऽनाहक्लमातीसारकारकौ","text":"hīnamātrāvubhau vastī nātikāryakarau smṛtau atimātrau tathā'nāhaklamātīsārakārakau"},{"type":"verse","number":"101","sanskrit":"उत्तमास्यात्पलैः षड्भिर्मध्यमा स्यात्पलैस्त्रिभिः पलाध्यर्द्धेन हीनास्यादुक्ताः मात्राऽनुवासने","text":"uttamāsyātpalaiḥ ṣaḍbhirmadhyamā syātpalaistribhiḥ palādhyarddhena hīnāsyāduktāḥ mātrā'nuvāsane"},{"type":"verse","number":"102","sanskrit":"शताह्वासैन्धवाभ्याञ्च देयं स्नेहे च चूर्णकम् तन्मात्रोत्तममध्यान्त्या षट्चतुर्द्वयमाषकैः","text":"śatāhvāsaindhavābhyāñca deyaṃ snehe ca cūrṇakam tanmātrottamamadhyāntyā ṣaṭcaturdvayamāṣakaiḥ"},{"type":"verse","number":"103","sanskrit":"विरेचनात्सप्तरात्रे गते जातबलाय च भुक्तान्नायानुवास्याय वस्तिर्देयोऽनुवासनः","text":"virecanātsaptarātre gate jātabalāya ca bhuktānnāyānuvāsyāya vastirdeyo'nuvāsanaḥ"},{"type":"verse","number":"104","sanskrit":"तथाऽनुवास्यं स्वभ्यक्तमुष्णाम्बुस्वेदितं शनैः भोजयित्चा यथाशास्त्रं कृतचङ्क्रमणं ततः उत्सृष्टानिलविण्मूत्रं योजयेत्स्नेहबस्तिना","text":"tathā'nuvāsyaṃ svabhyaktamuṣṇāmbusveditaṃ śanaiḥ bhojayitcā yathāśāstraṃ kṛtacaṅkramaṇaṃ tataḥ utsṛṣṭānilaviṇmūtraṃ yojayetsnehabastinā"},{"type":"verse","number":"105","sanskrit":"सुप्तस्य वामपार्श्वेन वामजङ्घाप्रसारिणः कुञ्चितापरजङ्घस्य नेत्रं स्निग्धे गुदे न्यसेत्","text":"suptasya vāmapārśvena vāmajaṅghāprasāriṇaḥ kuñcitāparajaṅghasya netraṃ snigdhe gude nyaset"},{"type":"verse","number":"106","sanskrit":"बद्धं वस्तिमुखं सूत्रैर्वामहस्तेन धारयेत् पीडयेद्दक्षिणेनैव मध्यवेगेन धीरधीः","text":"baddhaṃ vastimukhaṃ sūtrairvāmahastena dhārayet pīḍayeddakṣiṇenaiva madhyavegena dhīradhīḥ"},{"type":"verse","number":"107","sanskrit":"जृम्भाकासक्षवादींश्च वस्तिकाले न कारयेत् त्रिंशन्मात्रामितः कालः प्रोक्तो वस्तेस्तु पीडने","text":"jṛmbhākāsakṣavādīṃśca vastikāle na kārayet triṃśanmātrāmitaḥ kālaḥ prokto vastestu pīḍane"},{"type":"verse","number":"108","sanskrit":"ततः प्रणिहिते स्नेहे उत्तानो वाक्शतं भवेत् प्रसारितः सर्वगात्रैर्यथावीर्यं प्रसर्पति","text":"tataḥ praṇihite snehe uttāno vākśataṃ bhavet prasāritaḥ sarvagātrairyathāvīryaṃ prasarpati"},{"type":"verse","number":"109","sanskrit":"स्वजानुनः करावर्त्तं कुर्याच्छोटिकया पुनः एषा मात्रा भवेदेका सर्वत्रैवैष निश्चयः","text":"svajānunaḥ karāvarttaṃ kuryācchoṭikayā punaḥ eṣā mātrā bhavedekā sarvatraivaiṣa niścayaḥ"},{"type":"verse","number":"110","sanskrit":"निमेषोन्मेषणं पुंसामङ्गुल्या छोटिकाऽथ वा गुर्वक्षरोच्चारणं वा स्यान्मात्रेयं स्मृता बुधैः","text":"nimeṣonmeṣaṇaṃ puṃsāmaṅgulyā choṭikā'tha vā gurvakṣaroccāraṇaṃ vā syānmātreyaṃ smṛtā budhaiḥ"},{"type":"verse","number":"111","sanskrit":"ताडयेत्तलयोरेनं त्रींस्त्रीन्वाराञ्छनैः शनैः स्फिजोश्चैव तथा श्रोणीं शय्याञ्चैवोत्क्षिपेत्ततः","text":"tāḍayettalayorenaṃ trīṃstrīnvārāñchanaiḥ śanaiḥ sphijoścaiva tathā śroṇīṃ śayyāñcaivotkṣipettataḥ"},{"type":"verse","number":"112","sanskrit":"स्फिजोश्चैनं स्वपाणिभ्यां पूर्ववत्ताडयेद् बुधः","text":"sphijoścainaṃ svapāṇibhyāṃ pūrvavattāḍayed budhaḥ"},{"type":"verse","number":"113","sanskrit":"शय्याञ्च पादतस्तस्य त्रीन्वारानुत्क्षिपेत्ततः जाते विधाने तु ततः कुर्यान्निद्रा ं! यथासुखम्","text":"śayyāñca pādatastasya trīnvārānutkṣipettataḥ jāte vidhāne tu tataḥ kuryānnidrā ṃ! yathāsukham"},{"type":"verse","number":"114","sanskrit":"सानिलः सपुरीषश्च स्नेहः प्रत्येति यस्य तु उपद्र वं विना शीघ्रं स सम्यगनुवासितः","text":"sānilaḥ sapurīṣaśca snehaḥ pratyeti yasya tu upadra vaṃ vinā śīghraṃ sa samyaganuvāsitaḥ"},{"type":"verse","number":"115","sanskrit":"जीर्णान्नमथ सायाह्ने स्नेहे प्रत्यागते पुनः लघ्वन्नं भोजयेत्कामं दीप्ताग्निस्तु नरो यदि","text":"jīrṇānnamatha sāyāhne snehe pratyāgate punaḥ laghvannaṃ bhojayetkāmaṃ dīptāgnistu naro yadi"},{"type":"verse","number":"116","sanskrit":"अनुवासिताय दातव्यमितरेऽह्नि सुखोदकम् धान्यशुण्ठीकषायं वा स्नेहव्यापत्तिनाशनम्","text":"anuvāsitāya dātavyamitare'hni sukhodakam dhānyaśuṇṭhīkaṣāyaṃ vā snehavyāpattināśanam"},{"type":"verse","number":"117","sanskrit":"अनेनविधिना षड्वा सप्त चाष्टौ नवापि वा विधेया वस्तयस्तेषामन्ते चैव निरूहणम्","text":"anenavidhinā ṣaḍvā sapta cāṣṭau navāpi vā vidheyā vastayasteṣāmante caiva nirūhaṇam"},{"type":"verse","number":"118","sanskrit":"दत्तस्तु प्रथमो वस्तिः स्नेहयेद्वस्तिवङ्क्षणौ सम्यग्दत्तो द्वितीयस्तु मूर्द्धस्थमनिलं जयेत्","text":"dattastu prathamo vastiḥ snehayedvastivaṅkṣaṇau samyagdatto dvitīyastu mūrddhasthamanilaṃ jayet"},{"type":"verse","number":"119","sanskrit":"बलं वर्णश्च जनयेत्तृतीयस्तु प्रयोजितः चतुर्थपञ्चमौ दत्तौ स्नेहयेतां रसासृजी","text":"balaṃ varṇaśca janayettṛtīyastu prayojitaḥ caturthapañcamau dattau snehayetāṃ rasāsṛjī"},{"type":"verse","number":"120","sanskrit":"षष्ठो मांसं स्नेहयति सप्तमो मेद एव च अष्टमो नवमश्चापि मज्जानञ्च यथाक्रमम्","text":"ṣaṣṭho māṃsaṃ snehayati saptamo meda eva ca aṣṭamo navamaścāpi majjānañca yathākramam"},{"type":"verse","number":"121","sanskrit":"एवं शुक्रगतान्दोषान्द्विगुणः साधु साधयेत्","text":"evaṃ śukragatāndoṣāndviguṇaḥ sādhu sādhayet"},{"type":"verse","number":"122","sanskrit":"अष्टादशाष्टादशकाद्दिनाद्यो ना निषेवते स कुञ्जरबलोऽश्वस्य जवतुल्योऽमरप्रभः","text":"aṣṭādaśāṣṭādaśakāddinādyo nā niṣevate sa kuñjarabalo'śvasya javatulyo'maraprabhaḥ"},{"type":"verse","number":"123","sanskrit":"रूक्षाय बहुवाताय स्नेहवस्तिं दिने दिने दद्याद्वैद्यस्तथाऽन्येषामग्न्याबाधभयात् त्र्! यहात् स्नेहोऽल्पमात्रो रूक्षाणां दीर्घकालमनत्ययः","text":"rūkṣāya bahuvātāya snehavastiṃ dine dine dadyādvaidyastathā'nyeṣāmagnyābādhabhayāt tr! yahāt sneho'lpamātro rūkṣāṇāṃ dīrghakālamanatyayaḥ"},{"type":"verse","number":"124","sanskrit":"तथा निरूहः स्निग्धानामल्पमात्रः प्रशस्यते अथ वा यस्य तत्कालं स्नेहो निर्याति केवलः तस्याप्यल्पतरो देयो न हि स्निग्धेऽवतिष्ठते","text":"tathā nirūhaḥ snigdhānāmalpamātraḥ praśasyate atha vā yasya tatkālaṃ sneho niryāti kevalaḥ tasyāpyalpataro deyo na hi snigdhe'vatiṣṭhate"},{"type":"verse","number":"125","sanskrit":"अशुद्धस्य मलोन्मिश्रः स्नेहो नैति यदा पुनः तदाऽङ्गसदनध्माने शूलं श्वासश्च जायते","text":"aśuddhasya malonmiśraḥ sneho naiti yadā punaḥ tadā'ṅgasadanadhmāne śūlaṃ śvāsaśca jāyate"},{"type":"verse","number":"126","sanskrit":"पक्वाशये गुरुत्वञ्च तत्र दद्यान्निरूहणम् तीक्ष्णं तीक्ष्णोषधैर्युक्तं फलवर्त्तिमथापि वा","text":"pakvāśaye gurutvañca tatra dadyānnirūhaṇam tīkṣṇaṃ tīkṣṇoṣadhairyuktaṃ phalavarttimathāpi vā"},{"type":"verse","number":"127","sanskrit":"यथाऽनुलोमनो वायुर्मलः स्नेहश्च जायते तथा विरेचनं दद्यात्तीक्ष्णं नस्यञ्च शस्यते","text":"yathā'nulomano vāyurmalaḥ snehaśca jāyate tathā virecanaṃ dadyāttīkṣṇaṃ nasyañca śasyate"},{"type":"verse","number":"128","sanskrit":"यस्य नोपद्र वं कुर्यात्स्नेहवस्तिरनिःसृतः सर्वोऽल्पो व्यावृतो रौक्ष्यादुपेक्ष्यः स विजानता","text":"yasya nopadra vaṃ kuryātsnehavastiraniḥsṛtaḥ sarvo'lpo vyāvṛto raukṣyādupekṣyaḥ sa vijānatā"},{"type":"verse","number":"129","sanskrit":"अनायातं त्वहोरात्रे स्नेहं संशोधनैर्हरेत् स्नेहबस्तावनायाते नान्यः स्नेहो विधीयते","text":"anāyātaṃ tvahorātre snehaṃ saṃśodhanairharet snehabastāvanāyāte nānyaḥ sneho vidhīyate"},{"type":"verse","number":"130","sanskrit":"गुडूच्येरण्डपूतीकभार्ङ्गींवृषकरौहिषम् शतावरीसहचरौ काकनासां पलोन्मिताम्","text":"guḍūcyeraṇḍapūtīkabhārṅgīṃvṛṣakarauhiṣam śatāvarīsahacarau kākanāsāṃ palonmitām"},{"type":"verse","number":"131","sanskrit":"यवमाषातसीकोलकुलत्थान्प्रसृतोन्मितान् चतुद्रो र्णे!ऽम्भसः पक्त्वा द्रो णशेषेण तेन च","text":"yavamāṣātasīkolakulatthānprasṛtonmitān catudro rṇe!'mbhasaḥ paktvā dro ṇaśeṣeṇa tena ca"},{"type":"verse","number":"132","sanskrit":"पचेत्तैलाढकं सर्वैर्जीवनीयैः पलोन्मितैः अनुवासनमेतद्धि सर्ववातविकारनुत्","text":"pacettailāḍhakaṃ sarvairjīvanīyaiḥ palonmitaiḥ anuvāsanametaddhi sarvavātavikāranut"},{"type":"verse","number":"133","sanskrit":"षटसप्ततिव्यापदस्तु जायन्ते बस्तिकर्मणः दूषितात् समुदायेन ताश्चिकित्स्यास्तु सुश्रुतात्","text":"ṣaṭasaptativyāpadastu jāyante bastikarmaṇaḥ dūṣitāt samudāyena tāścikitsyāstu suśrutāt"},{"type":"verse","number":"134","sanskrit":"पानाहारविहाराश्च परिहाराश्च कृत्स्नशः स्नेहपानसमाः कार्य्या नात्र कार्या विचारणा","text":"pānāhāravihārāśca parihārāśca kṛtsnaśaḥ snehapānasamāḥ kāryyā nātra kāryā vicāraṇā"},{"type":"verse","number":"135","sanskrit":"निरूहवस्तिर्बहुधा भिद्यते कारणान्तरः तैरेव तस्य नामानि कृतानि मुनिपुङ्गवैः","text":"nirūhavastirbahudhā bhidyate kāraṇāntaraḥ taireva tasya nāmāni kṛtāni munipuṅgavaiḥ"},{"type":"verse","number":"136","sanskrit":"निरूहस्यापरं नाम प्रोक्तमास्थापनं बुधैः स्वस्थाने स्थापनाद्दोषधातूनां स्थापनं मतम्","text":"nirūhasyāparaṃ nāma proktamāsthāpanaṃ budhaiḥ svasthāne sthāpanāddoṣadhātūnāṃ sthāpanaṃ matam"},{"type":"verse","number":"137","sanskrit":"निरूहस्य प्रमाणं तु प्रस्थं पादोत्तरं परम् मध्यमं प्रस्थमुद्दिष्टं हीनञ्च कुडवास्त्रयः","text":"nirūhasya pramāṇaṃ tu prasthaṃ pādottaraṃ param madhyamaṃ prasthamuddiṣṭaṃ hīnañca kuḍavāstrayaḥ"},{"type":"verse","number":"138","sanskrit":"अतिस्निग्धोऽक्लिष्टदोषः क्षतोरस्कः कृशस्तथा आध्मानच्छर्दिहिक्काऽशकासश्वासप्रपीडितः","text":"atisnigdho'kliṣṭadoṣaḥ kṣatoraskaḥ kṛśastathā ādhmānacchardihikkā'śakāsaśvāsaprapīḍitaḥ"},{"type":"verse","number":"139","sanskrit":"गुदशोफातिसारार्त्तो विसूचीकुष्ठसंयुतः गर्भिणी मधुमेही च नास्थाप्यश्च जलोदरी","text":"gudaśophātisārārtto visūcīkuṣṭhasaṃyutaḥ garbhiṇī madhumehī ca nāsthāpyaśca jalodarī"},{"type":"verse","number":"140","sanskrit":"वातव्याधावुदावर्ते वातासृग्विषमज्वरे मूर्च्छातृष्णोदरानाहमूत्रकृच्छ्राश्मरीषु च","text":"vātavyādhāvudāvarte vātāsṛgviṣamajvare mūrcchātṛṣṇodarānāhamūtrakṛcchrāśmarīṣu ca"},{"type":"verse","number":"141","sanskrit":"वृद्ध्य्सृग्दरमन्दाग्निप्रमेहेषु निरूह्रणम् शूलेऽम्लपित्ते हृद्रो गे योजयेद्विधिवद् बुधः","text":"vṛddhysṛgdaramandāgniprameheṣu nirūhraṇam śūle'mlapitte hṛdro ge yojayedvidhivad budhaḥ"},{"type":"verse","number":"142","sanskrit":"उत्सृष्टानिलविण्मूत्रं स्निग्धं स्विन्नमभोजितम् मध्याह्ने गृहमध्ये च यथायोग्यं निरूहयेत्","text":"utsṛṣṭānilaviṇmūtraṃ snigdhaṃ svinnamabhojitam madhyāhne gṛhamadhye ca yathāyogyaṃ nirūhayet"},{"type":"verse","number":"143","sanskrit":"स्नेहवस्तिविधानेन बुधः कुर्यान्निरूहणम्","text":"snehavastividhānena budhaḥ kuryānnirūhaṇam"},{"type":"verse","number":"144","sanskrit":"जाते निरूहे च ततो भवेदुत्कटकासनः तिष्ठेन्महूर्त्तमात्रन्तु निरूहागमनेच्छया","text":"jāte nirūhe ca tato bhavedutkaṭakāsanaḥ tiṣṭhenmahūrttamātrantu nirūhāgamanecchayā"},{"type":"verse","number":"145","sanskrit":"अनायातं मुहूर्त्तं तु निरूहं शोधनैर्हरेत् निरूहैरेव मतिमान्क्षारसूत्राम्लसैन्धवैः","text":"anāyātaṃ muhūrttaṃ tu nirūhaṃ śodhanairharet nirūhaireva matimānkṣārasūtrāmlasaindhavaiḥ"},{"type":"verse","number":"146","sanskrit":"यस्य क्रमेण गच्छन्ति विट्पित्तकफवायवः लाघवं चोपजायेत सुनिरूहं तमादिशेत्","text":"yasya krameṇa gacchanti viṭpittakaphavāyavaḥ lāghavaṃ copajāyeta sunirūhaṃ tamādiśet"},{"type":"verse","number":"147","sanskrit":"यस्य स्याद्वस्तिरत्यल्पवेगो हीनमलानिलः मूर्च्छाऽत्तिजाड्यारुचिमान्दुर्निरूहं तमादिशेत्","text":"yasya syādvastiratyalpavego hīnamalānilaḥ mūrcchā'ttijāḍyārucimāndurnirūhaṃ tamādiśet"},{"type":"verse","number":"148","sanskrit":"विविक्तता मनस्तुष्टिः स्निग्धता व्याधिनिग्रहः आस्थापनस्नेहवस्त्योः सम्यग्दाने तु लक्षणम्","text":"viviktatā manastuṣṭiḥ snigdhatā vyādhinigrahaḥ āsthāpanasnehavastyoḥ samyagdāne tu lakṣaṇam"},{"type":"verse","number":"149","sanskrit":"अनेन विधिना युञ्ज्यान्निरूहं वस्तिदानवित् द्वितीयं वा तृतीयं वा चतुर्थं वा यथोचितम्","text":"anena vidhinā yuñjyānnirūhaṃ vastidānavit dvitīyaṃ vā tṛtīyaṃ vā caturthaṃ vā yathocitam"},{"type":"verse","number":"150","sanskrit":"सस्नेह एकः पवने पित्ते द्वौ पयसा सह कषायकटुमूत्राद्याः कफेऽत्युष्णास्त्रयो हिताः","text":"sasneha ekaḥ pavane pitte dvau payasā saha kaṣāyakaṭumūtrādyāḥ kaphe'tyuṣṇāstrayo hitāḥ"},{"type":"verse","number":"151","sanskrit":"पित्तश्लेष्मानिलाविष्टं क्षीरयूषरसैः क्रमात् निरूढं भोजयित्वा च ततस्तमनुवासयेत्","text":"pittaśleṣmānilāviṣṭaṃ kṣīrayūṣarasaiḥ kramāt nirūḍhaṃ bhojayitvā ca tatastamanuvāsayet"},{"type":"verse","number":"152","sanskrit":"सुकुमारस्य वृद्धस्य बालस्य च मृदुर्हितः वस्तिस्तीक्ष्णः प्रयुक्तस्तु तेषां हन्याद्बलायुषी","text":"sukumārasya vṛddhasya bālasya ca mṛdurhitaḥ vastistīkṣṇaḥ prayuktastu teṣāṃ hanyādbalāyuṣī"},{"type":"verse","number":"153","sanskrit":"दद्यादुत्क्लेशनं पूर्वं मध्ये दोषहरं ततः पश्चात्संशमनीयञ्च दद्याद्वस्तिं विचक्षणः","text":"dadyādutkleśanaṃ pūrvaṃ madhye doṣaharaṃ tataḥ paścātsaṃśamanīyañca dadyādvastiṃ vicakṣaṇaḥ"},{"type":"verse","number":"154","sanskrit":"एरण्डबीजं मधुकं पिप्पली सैन्धवं वचा हपुषाफलकल्कश्च वस्तिरुत्क्लेशनः स्मृतः","text":"eraṇḍabījaṃ madhukaṃ pippalī saindhavaṃ vacā hapuṣāphalakalkaśca vastirutkleśanaḥ smṛtaḥ"},{"type":"verse","number":"155","sanskrit":"शताह्वा मधुकं बिल्वं कौटजं फलमेव च सकाञ्जिकः सगोमूत्रो वस्तिर्दोषहरः स्मृतः","text":"śatāhvā madhukaṃ bilvaṃ kauṭajaṃ phalameva ca sakāñjikaḥ sagomūtro vastirdoṣaharaḥ smṛtaḥ"},{"type":"verse","number":"156","sanskrit":"प्रियङ्गुर्मधुकं मुस्ता तथैव च रसाञ्जनम् सक्षीरः शस्यते वस्तिर्दोषाणां शमनः स्मृतः","text":"priyaṅgurmadhukaṃ mustā tathaiva ca rasāñjanam sakṣīraḥ śasyate vastirdoṣāṇāṃ śamanaḥ smṛtaḥ"},{"type":"verse","number":"157","sanskrit":"त्रिफलाक्वाथगोमूत्रक्षौद्र क्षारसमायुतः ऊषकादिप्रतीवापैर्वस्तयोलेखनाः स्मृताः","text":"triphalākvāthagomūtrakṣaudra kṣārasamāyutaḥ ūṣakādipratīvāpairvastayolekhanāḥ smṛtāḥ"},{"type":"verse","number":"158","sanskrit":"बृंहणद्र व्यनिक्वाथैः कल्कैर्मधुरकैर्युताः सर्पिर्मांसरसोपेता वस्तयो बृंहणाः स्मृताः","text":"bṛṃhaṇadra vyanikvāthaiḥ kalkairmadhurakairyutāḥ sarpirmāṃsarasopetā vastayo bṛṃhaṇāḥ smṛtāḥ"},{"type":"verse","number":"159","sanskrit":"बदर्यैरावतीशेलुशाल्मलीपुष्पजाङ्कुराः क्षीरसिद्धाःक्षौद्र युक्ता नाम्ना पिच्छलसंज्ञिताः","text":"badaryairāvatīśeluśālmalīpuṣpajāṅkurāḥ kṣīrasiddhāḥkṣaudra yuktā nāmnā picchalasaṃjñitāḥ"},{"type":"verse","number":"160","sanskrit":"अजोरभ्रैणरुधिरैर्युक्ता देया विचक्षणैः मात्रा पिच्छिलवस्तीनां पलैर्द्वादशभिर्मता","text":"ajorabhraiṇarudhirairyuktā deyā vicakṣaṇaiḥ mātrā picchilavastīnāṃ palairdvādaśabhirmatā"},{"type":"verse","number":"161","sanskrit":"दत्त्वादौ सैन्धवस्याक्षं मधुनः प्रसृतिद्वयम् विनिर्मथ्य ततो दद्यात्स्नेहस्य प्रसृतित्रयम्","text":"dattvādau saindhavasyākṣaṃ madhunaḥ prasṛtidvayam vinirmathya tato dadyātsnehasya prasṛtitrayam"},{"type":"verse","number":"162","sanskrit":"एकीभूते ततः स्नेहे कल्कस्य प्रसृतिं क्षिपेत् सम्मूर्च्छिते कषायन्तु चतुः प्रसृतिसम्मितम्","text":"ekībhūte tataḥ snehe kalkasya prasṛtiṃ kṣipet sammūrcchite kaṣāyantu catuḥ prasṛtisammitam"},{"type":"verse","number":"163","sanskrit":"गृह्णीयाच्च तदा वाऽल्पमन्ते द्विप्रसृतोन्मितम् क्षिप्त्वा विमथ्य दद्याच्च निरूहं कुशलो भिषक्","text":"gṛhṇīyācca tadā vā'lpamante dviprasṛtonmitam kṣiptvā vimathya dadyācca nirūhaṃ kuśalo bhiṣak"},{"type":"verse","number":"164","sanskrit":"एवं प्रकल्पितो वस्तिर्द्वादशप्रसृतिर्भवेत् वाते चतुष्पलं क्षौद्रं दद्यात् स्नेहस्य षट्पलम्","text":"evaṃ prakalpito vastirdvādaśaprasṛtirbhavet vāte catuṣpalaṃ kṣaudraṃ dadyāt snehasya ṣaṭpalam"},{"type":"verse","number":"165","sanskrit":"पित्ते चतुष्पलं क्षौद्रं स्नेहं दद्यात्पलत्रयम् कफे तु षट्पलं क्षौद्रं क्षिपेत् स्नेहं चतुष्पलम्","text":"pitte catuṣpalaṃ kṣaudraṃ snehaṃ dadyātpalatrayam kaphe tu ṣaṭpalaṃ kṣaudraṃ kṣipet snehaṃ catuṣpalam"},{"type":"verse","number":"166","sanskrit":"एरण्डक्वाथतुल्यांशं मधुतैलं पलाष्टकम् शतपुष्पापलार्द्धेन सैन्धवार्द्धेन संयुतम् मधुतैलकसंज्ञोऽय वस्तिर्दारुविलोडितः","text":"eraṇḍakvāthatulyāṃśaṃ madhutailaṃ palāṣṭakam śatapuṣpāpalārddhena saindhavārddhena saṃyutam madhutailakasaṃjño'ya vastirdāruviloḍitaḥ"},{"type":"verse","number":"167","sanskrit":"मेदोगुल्मकृमिप्लीहमलोदावर्तनाशनः बलवर्णकरश्चैव वृष्यो दीपनबृंहणः","text":"medogulmakṛmiplīhamalodāvartanāśanaḥ balavarṇakaraścaiva vṛṣyo dīpanabṛṃhaṇaḥ"},{"type":"verse","number":"168","sanskrit":"क्षौद्रा ज्यक्षीरतैलानां प्रसृतं प्रसृतं भवेत् हपुषासैन्धवाक्षांशो वस्तिः स्याद्यापनः परः","text":"kṣaudrā jyakṣīratailānāṃ prasṛtaṃ prasṛtaṃ bhavet hapuṣāsaindhavākṣāṃśo vastiḥ syādyāpanaḥ paraḥ"},{"type":"verse","number":"169","sanskrit":"एरण्डमूलनिक्वाथो मधुतैलं ससैन्धवम् एष युक्तरथो वस्तिः सवचापिप्पलीफलः","text":"eraṇḍamūlanikvātho madhutailaṃ sasaindhavam eṣa yuktaratho vastiḥ savacāpippalīphalaḥ"},{"type":"verse","number":"170","sanskrit":"पञ्चमूलस्य निक्वाथैस्तैलं मागधिका मधु ससैन्धवः सयष्ट्याह्वः सिद्धवस्तिरिति स्मृतः","text":"pañcamūlasya nikvāthaistailaṃ māgadhikā madhu sasaindhavaḥ sayaṣṭyāhvaḥ siddhavastiriti smṛtaḥ"},{"type":"verse","number":"171","sanskrit":"स्नानमुष्णोदकैः कुर्याद्दिवास्वप्नमजीर्णताम् वर्जयेदपरं सर्वमाचरेत्स्नेहवस्तिवत्","text":"snānamuṣṇodakaiḥ kuryāddivāsvapnamajīrṇatām varjayedaparaṃ sarvamācaretsnehavastivat"},{"type":"verse","number":"172","sanskrit":"अतः परं प्रवक्ष्यामि वस्तिमुत्तरसंज्ञितम् निरूहादुत्तरो यस्मात्तस्मादुत्तरसंज्ञकः","text":"ataḥ paraṃ pravakṣyāmi vastimuttarasaṃjñitam nirūhāduttaro yasmāttasmāduttarasaṃjñakaḥ"},{"type":"verse","number":"173","sanskrit":"द्वादशाङ्गुलकं नेत्रं मध्ये च कृतकर्णिकम् मालतीपुष्पवृन्ताभं छिद्रं सर्षपनिर्गमम्","text":"dvādaśāṅgulakaṃ netraṃ madhye ca kṛtakarṇikam mālatīpuṣpavṛntābhaṃ chidraṃ sarṣapanirgamam"},{"type":"verse","number":"174","sanskrit":"पञ्चविंशतिवर्षाणामधोमात्रा द्विकार्षिकी तदूर्ध्वं पलमात्रा च स्नेहस्योक्ता भिषग्वरैः","text":"pañcaviṃśativarṣāṇāmadhomātrā dvikārṣikī tadūrdhvaṃ palamātrā ca snehasyoktā bhiṣagvaraiḥ"},{"type":"verse","number":"175","sanskrit":"अथास्थापनशुद्धस्य तृप्तस्य स्नानभोजनैः स्थितस्य जानुमात्रे च पिष्टे स्निग्धे शलाकया","text":"athāsthāpanaśuddhasya tṛptasya snānabhojanaiḥ sthitasya jānumātre ca piṣṭe snigdhe śalākayā"},{"type":"verse","number":"176","sanskrit":"स्निग्धया मेढ्रमार्गे तु तत्रो नेत्रं नियोजयेत् शनैः शनैर्घृताभ्यक्तं मेढ्ररन्ध्राङ्गुलानि षट्","text":"snigdhayā meḍhramārge tu tatro netraṃ niyojayet śanaiḥ śanairghṛtābhyaktaṃ meḍhrarandhrāṅgulāni ṣaṭ"},{"type":"verse","number":"177","sanskrit":"ततोऽवपीडयेद्बस्तिं शनैर्नेत्रं विनिर्हरेत् ततः प्रत्यागते स्नेहे स्नेहवस्तिंक्रमो हितः","text":"tato'vapīḍayedbastiṃ śanairnetraṃ vinirharet tataḥ pratyāgate snehe snehavastiṃkramo hitaḥ"},{"type":"verse","number":"178","sanskrit":"स्त्रीणां कनिष्ठिकास्थूलं नेत्रं कुर्याद् दशाङ्गुलम् मुद्गप्रवेशयोग्यञ्च योन्यन्तश्चतुरङ्गुलम्","text":"strīṇāṃ kaniṣṭhikāsthūlaṃ netraṃ kuryād daśāṅgulam mudgapraveśayogyañca yonyantaścaturaṅgulam"},{"type":"verse","number":"179","sanskrit":"द्व्यङ्गुलं मूत्रमार्गे च सूक्ष्मं नेत्रं नियोजयेत् मूत्रकृच्छ्रविकारेषु बालानां त्वेकमङ्गुलम्","text":"dvyaṅgulaṃ mūtramārge ca sūkṣmaṃ netraṃ niyojayet mūtrakṛcchravikāreṣu bālānāṃ tvekamaṅgulam"},{"type":"verse","number":"180","sanskrit":"शनैर्निष्कम्पमाधेयं सूक्ष्मं नेत्रं विचक्षणैः मालतीपुष्पवृन्ताभं नेत्रमित्युदितं पुनः","text":"śanairniṣkampamādheyaṃ sūkṣmaṃ netraṃ vicakṣaṇaiḥ mālatīpuṣpavṛntābhaṃ netramityuditaṃ punaḥ"},{"type":"verse","number":"181","sanskrit":"योनिमार्गेषु नारीणां स्नेहमात्रा द्विपालिकी मूत्रमार्गे पलोन्माना बालानां च द्विकार्षिकी","text":"yonimārgeṣu nārīṇāṃ snehamātrā dvipālikī mūtramārge palonmānā bālānāṃ ca dvikārṣikī"},{"type":"verse","number":"182","sanskrit":"उत्तानायै स्त्रियै दद्यादूर्ध्वजान्वै विचक्षणः अप्रत्यागच्छति भिषग् वस्तावुत्तरसंज्ञिते","text":"uttānāyai striyai dadyādūrdhvajānvai vicakṣaṇaḥ apratyāgacchati bhiṣag vastāvuttarasaṃjñite"},{"type":"verse","number":"183","sanskrit":"भूयो वस्तिं विदध्याच्च संयुक्तं शोधनैर्गुणैः फलवर्त्तिं विदध्याद् वा योनिमार्गे दृढां भिषक्","text":"bhūyo vastiṃ vidadhyācca saṃyuktaṃ śodhanairguṇaiḥ phalavarttiṃ vidadhyād vā yonimārge dṛḍhāṃ bhiṣak"},{"type":"verse","number":"184","sanskrit":"सूत्रैर्विनिर्मितां स्निग्धां शोधनद्र व्यसंयुताम्","text":"sūtrairvinirmitāṃ snigdhāṃ śodhanadra vyasaṃyutām"},{"type":"verse","number":"185","sanskrit":"दह्यमाने तथा वस्तौ दद्याद्वस्तिं विशारदः क्षीरिवृक्षकषायेण पयसा शीतलेन वा","text":"dahyamāne tathā vastau dadyādvastiṃ viśāradaḥ kṣīrivṛkṣakaṣāyeṇa payasā śītalena vā"},{"type":"verse","number":"186","sanskrit":"वस्तिः शुक्ररुजः पुंसां स्त्रीणामार्त्तवजा रुजः हन्यादुत्तरवस्तिस्तु नोचितो मेहिने क्वचित्","text":"vastiḥ śukrarujaḥ puṃsāṃ strīṇāmārttavajā rujaḥ hanyāduttaravastistu nocito mehine kvacit"},{"type":"verse","number":"187","sanskrit":"सम्यग्दत्तस्य लिङ्गानि व्यापदः क्रम एव च वस्तेरुत्तरसंज्ञस्य समानाः स्नेहवस्तिना","text":"samyagdattasya liṅgāni vyāpadaḥ krama eva ca vasteruttarasaṃjñasya samānāḥ snehavastinā"},{"type":"verse","number":"188","sanskrit":"घृताभ्यक्ते गुदे क्षिप्ता श्लक्ष्णा स्वाङ्गुष्ठसन्निभा मलप्रवर्त्तिनी वर्त्तिः फलवर्त्तिश्च सा स्मृता","text":"ghṛtābhyakte gude kṣiptā ślakṣṇā svāṅguṣṭhasannibhā malapravarttinī varttiḥ phalavarttiśca sā smṛtā"},{"type":"verse","number":"189","sanskrit":"नस्यं तत्कथ्यते धीरैर्नासाग्राह्यं यदौषधम् नावनं नस्यकर्मेति तस्य नामद्वयं मतम्","text":"nasyaṃ tatkathyate dhīrairnāsāgrāhyaṃ yadauṣadham nāvanaṃ nasyakarmeti tasya nāmadvayaṃ matam"},{"type":"verse","number":"190","sanskrit":"नस्यभेदो द्विधा प्रोक्तो रेचनं स्नेहनं तथा रेचनं कर्षणं प्रोक्तं स्नेहनं वृंहणं मतम्","text":"nasyabhedo dvidhā prokto recanaṃ snehanaṃ tathā recanaṃ karṣaṇaṃ proktaṃ snehanaṃ vṛṃhaṇaṃ matam"},{"type":"verse","number":"191","sanskrit":"कफपित्तानिलध्वंसि पूर्वमध्यापराह्णके दिनस्य गृह्यते नस्यं रात्रावप्युत्कटे गदे","text":"kaphapittāniladhvaṃsi pūrvamadhyāparāhṇake dinasya gṛhyate nasyaṃ rātrāvapyutkaṭe gade"},{"type":"verse","number":"192","sanskrit":"नस्यं त्यजेद्भोजनान्ते दुर्दिने चापतर्पितः तथा नवप्रतिश्यायी गर्भिणी गरदूषितः अजीर्णी दत्तवस्तिश्च पीतस्नेहोदकासवः","text":"nasyaṃ tyajedbhojanānte durdine cāpatarpitaḥ tathā navapratiśyāyī garbhiṇī garadūṣitaḥ ajīrṇī dattavastiśca pītasnehodakāsavaḥ"},{"type":"verse","number":"193","sanskrit":"क्रुद्धः शोकाभिभूतश्च तृषार्त्तो वृद्धबालकौ वेगावरोधी श्रान्तश्च स्नातुकामश्च वर्जयेत्","text":"kruddhaḥ śokābhibhūtaśca tṛṣārtto vṛddhabālakau vegāvarodhī śrāntaśca snātukāmaśca varjayet"},{"type":"verse","number":"194","sanskrit":"अष्टवर्षस्य बालस्य नस्यकर्म समाचरेत् अशीतिवर्षादूर्ध्वञ्च नावनं नैव दीयते","text":"aṣṭavarṣasya bālasya nasyakarma samācaret aśītivarṣādūrdhvañca nāvanaṃ naiva dīyate"},{"type":"verse","number":"195","sanskrit":"अथ वैरेचनं नस्यं ग्राह्यं तैलैः सुतीक्ष्णकैः तीक्ष्णैः भेषजसिद्धैर्वा स्नेहैः क्वाथै रसैस्तथा","text":"atha vairecanaṃ nasyaṃ grāhyaṃ tailaiḥ sutīkṣṇakaiḥ tīkṣṇaiḥ bheṣajasiddhairvā snehaiḥ kvāthai rasaistathā"},{"type":"verse","number":"196","sanskrit":"नासिकारन्ध्रयोरष्टौ षट् चत्वारश्च बिन्दवः प्रत्येकं रेचनं योग्यं मुख्यमध्याल्पमात्रया","text":"nāsikārandhrayoraṣṭau ṣaṭ catvāraśca bindavaḥ pratyekaṃ recanaṃ yogyaṃ mukhyamadhyālpamātrayā"},{"type":"verse","number":"197","sanskrit":"नस्यकर्मणि दातव्यं शाणैकं तीक्ष्णमौषधम् हिङ्गु स्याद्यवमात्रन्तु माषैकं सैन्धवं मतम्","text":"nasyakarmaṇi dātavyaṃ śāṇaikaṃ tīkṣṇamauṣadham hiṅgu syādyavamātrantu māṣaikaṃ saindhavaṃ matam"},{"type":"verse","number":"198","sanskrit":"क्षीरं चैवाष्टशाणं स्यात्पानीयञ्च त्रिकार्षिकम् कार्षिकं मधुरद्र व्यं नस्यकर्मणि योजयेत्","text":"kṣīraṃ caivāṣṭaśāṇaṃ syātpānīyañca trikārṣikam kārṣikaṃ madhuradra vyaṃ nasyakarmaṇi yojayet"},{"type":"verse","number":"199","sanskrit":"अवपीडः प्रधमनं द्वौ भेदावपरौ स्मृतौ शिरोविरेचनस्याथ तौ तु देयौ यथायथम्","text":"avapīḍaḥ pradhamanaṃ dvau bhedāvaparau smṛtau śirovirecanasyātha tau tu deyau yathāyatham"},{"type":"verse","number":"200","sanskrit":"कल्कीकृतादौषधाद्यः पीडितो निःसृतो रसः सोऽवपीडः समुद्दिष्टस्तीक्ष्णद्र व्यसमुद्भवः","text":"kalkīkṛtādauṣadhādyaḥ pīḍito niḥsṛto rasaḥ so'vapīḍaḥ samuddiṣṭastīkṣṇadra vyasamudbhavaḥ"},{"type":"verse","number":"201","sanskrit":"षडङ्गुला द्विवक्त्रा या नाडी चूर्णं तथा धमेत् तीक्ष्णं कोलमितं वक्त्रवातैः प्रधमनं हितम्","text":"ṣaḍaṅgulā dvivaktrā yā nāḍī cūrṇaṃ tathā dhamet tīkṣṇaṃ kolamitaṃ vaktravātaiḥ pradhamanaṃ hitam"},{"type":"verse","number":"202","sanskrit":"ऊर्ध्वजत्रुगते रोगे कफजे स्वरसंक्षये अरोचके प्रतिश्याये शिरःशूले च पीनसे","text":"ūrdhvajatrugate roge kaphaje svarasaṃkṣaye arocake pratiśyāye śiraḥśūle ca pīnase"},{"type":"verse","number":"203","sanskrit":"शोफापस्मारकुष्ठेषु नस्यं वैरेचनं हितम् भीरुस्त्रीकृशबालानां नस्यं स्नेहेन शस्यते","text":"śophāpasmārakuṣṭheṣu nasyaṃ vairecanaṃ hitam bhīrustrīkṛśabālānāṃ nasyaṃ snehena śasyate"},{"type":"verse","number":"204","sanskrit":"गलरोगे सन्निपाते निद्रा यां विषमज्वरे मनोविकारे कृमिषु पूज्यते चावपीडनम्","text":"galaroge sannipāte nidrā yāṃ viṣamajvare manovikāre kṛmiṣu pūjyate cāvapīḍanam"},{"type":"verse","number":"205","sanskrit":"अत्यन्तोत्कटदोषेषु विसंज्ञेषु च दीयते चूर्णं प्रधमनं धीरैस्तद्धि तीक्ष्णतरं यतः","text":"atyantotkaṭadoṣeṣu visaṃjñeṣu ca dīyate cūrṇaṃ pradhamanaṃ dhīraistaddhi tīkṣṇataraṃ yataḥ"},{"type":"verse","number":"206","sanskrit":"नस्यं स्याद् गुडशुण्ठीभ्यां पिप्पलीसैन्धवेन वा जलपिष्टेन कर्णाक्षिनासामूर्द्धभवा गदाः","text":"nasyaṃ syād guḍaśuṇṭhībhyāṃ pippalīsaindhavena vā jalapiṣṭena karṇākṣināsāmūrddhabhavā gadāḥ"},{"type":"verse","number":"207","sanskrit":"मन्याहनुगलोद्भूता नश्यन्ति भुजपृष्ठजाः मधूकसारकृष्णाभ्यां वचामरिचसैन्धवैः","text":"manyāhanugalodbhūtā naśyanti bhujapṛṣṭhajāḥ madhūkasārakṛṣṇābhyāṃ vacāmaricasaindhavaiḥ"},{"type":"verse","number":"208","sanskrit":"नस्यं कोष्णाम्भसा पिष्टं दद्यात्संज्ञाप्रबोधनम् अपस्मारे तथोन्मादे सन्निपातेऽपतन्त्रके","text":"nasyaṃ koṣṇāmbhasā piṣṭaṃ dadyātsaṃjñāprabodhanam apasmāre tathonmāde sannipāte'patantrake"},{"type":"verse","number":"209","sanskrit":"सैन्धवं श्वेतमरिचं सर्षपाः कुष्ठमेव च बस्तमूत्रेण संपिष्टं नस्यं तन्द्रा निवारणम्","text":"saindhavaṃ śvetamaricaṃ sarṣapāḥ kuṣṭhameva ca bastamūtreṇa saṃpiṣṭaṃ nasyaṃ tandrā nivāraṇam"},{"type":"verse","number":"210","sanskrit":"रोहितस्य च पित्तेन भावितं मरिचं वचा कट्फलं चेति तच्चूर्णं देयं प्रधमनं वुधैः","text":"rohitasya ca pittena bhāvitaṃ maricaṃ vacā kaṭphalaṃ ceti taccūrṇaṃ deyaṃ pradhamanaṃ vudhaiḥ"},{"type":"verse","number":"211","sanskrit":"अथ बृंहणनस्यस्य कल्पना कथ्यतेऽधुना मर्शश्च प्रतिमर्शश्च द्वौ भेदौ स्नेहने मतौ","text":"atha bṛṃhaṇanasyasya kalpanā kathyate'dhunā marśaśca pratimarśaśca dvau bhedau snehane matau"},{"type":"verse","number":"212","sanskrit":"मर्शस्य तर्पणी मात्रा मुख्या शाणैः स्मृताऽष्टभिः मध्यमा तु चतुःशाणैर्हीना शाणमिता मता","text":"marśasya tarpaṇī mātrā mukhyā śāṇaiḥ smṛtā'ṣṭabhiḥ madhyamā tu catuḥśāṇairhīnā śāṇamitā matā"},{"type":"verse","number":"213","sanskrit":"एकैकस्मिंस्तु मात्रेयं देया नासापुटे बुधैः","text":"ekaikasmiṃstu mātreyaṃ deyā nāsāpuṭe budhaiḥ"},{"type":"verse","number":"214","sanskrit":"मर्शस्य द्वित्रिवेलं वा वीक्ष्य दोषबलाबलम् एकान्तरं द्वयन्तरं वा नस्यं दद्याद्विचक्षणः","text":"marśasya dvitrivelaṃ vā vīkṣya doṣabalābalam ekāntaraṃ dvayantaraṃ vā nasyaṃ dadyādvicakṣaṇaḥ"},{"type":"verse","number":"215","sanskrit":"त्र्! यहं पञ्चाहमथवा सप्ताहं वा सुयन्त्रितः","text":"tr! yahaṃ pañcāhamathavā saptāhaṃ vā suyantritaḥ"},{"type":"verse","number":"216","sanskrit":"मर्शे शिरोविरेके च व्यापदो विविधाः स्मृताः दोषोत्क्लेशात्क्षयाच्चैव विज्ञेयास्ता यथाक्रमम् दोषोत्क्लेशनिमित्तासु युञ्ज्याद्वमनशोधनम्","text":"marśe śirovireke ca vyāpado vividhāḥ smṛtāḥ doṣotkleśātkṣayāccaiva vijñeyāstā yathākramam doṣotkleśanimittāsu yuñjyādvamanaśodhanam"},{"type":"verse","number":"217","sanskrit":"अथ क्षयनिमित्तासु यथास्वं बृंहणं हितम् शिरोनासाऽक्षिरोगेषु सूर्यावर्त्तार्द्धभेदके","text":"atha kṣayanimittāsu yathāsvaṃ bṛṃhaṇaṃ hitam śironāsā'kṣirogeṣu sūryāvarttārddhabhedake"},{"type":"verse","number":"218","sanskrit":"दन्तरोगे बले हीने मन्याबाह्वंसजे गदे मुखशोषे कर्णनादे वातपित्तगदे तथा","text":"dantaroge bale hīne manyābāhvaṃsaje gade mukhaśoṣe karṇanāde vātapittagade tathā"},{"type":"verse","number":"219","sanskrit":"अकालपलिते चैव केशश्मश्रुप्रपातने पूज्यते बृंहणं नस्यं स्नेहैर्वा मधुरद्र वैः","text":"akālapalite caiva keśaśmaśruprapātane pūjyate bṛṃhaṇaṃ nasyaṃ snehairvā madhuradra vaiḥ"},{"type":"verse","number":"220","sanskrit":"सशर्करं पयःपिष्टं भृष्टमाज्येन कुङ्कुमम् नस्यप्रयोगतो हन्याद्वातरक्तभवा रुजः भ्रूशङ्खाक्षिशिरःकर्णसूर्यावर्त्तार्द्धभेदकान्","text":"saśarkaraṃ payaḥpiṣṭaṃ bhṛṣṭamājyena kuṅkumam nasyaprayogato hanyādvātaraktabhavā rujaḥ bhrūśaṅkhākṣiśiraḥkarṇasūryāvarttārddhabhedakān"},{"type":"verse","number":"221","sanskrit":"नस्यं स्यादणुतैलेन तथा नारायणेन वा माषादिना वा सर्पिर्भिस्तत्तद्भेषजसाधितैः","text":"nasyaṃ syādaṇutailena tathā nārāyaṇena vā māṣādinā vā sarpirbhistattadbheṣajasādhitaiḥ"},{"type":"verse","number":"222","sanskrit":"तैलं कफे स्याद्वाते च केवले पवने वसाम् दद्यान्नस्यं सदा पित्ते सर्पिर्मज्जानमेव च","text":"tailaṃ kaphe syādvāte ca kevale pavane vasām dadyānnasyaṃ sadā pitte sarpirmajjānameva ca"},{"type":"verse","number":"223","sanskrit":"माषात्मगुप्तारास्नाभिर्बलारुबुकरौहिषैः कृतोऽश्वगन्धया क्वाथो हिङ्गुसैन्धवसंयुतः","text":"māṣātmaguptārāsnābhirbalārubukarauhiṣaiḥ kṛto'śvagandhayā kvātho hiṅgusaindhavasaṃyutaḥ"},{"type":"verse","number":"224","sanskrit":"कोष्णो नस्यप्रयोगेण पक्षाघातं सकम्पनम् जयेदर्दितवातञ्च मन्यास्तम्भावबाहुकौ","text":"koṣṇo nasyaprayogeṇa pakṣāghātaṃ sakampanam jayedarditavātañca manyāstambhāvabāhukau"},{"type":"verse","number":"225","sanskrit":"प्रतिमर्शस्य मात्रा तु द्वित्रिविन्दुमिता मता प्रत्येकशो नासिकया स्नेहनेति विनिश्चितम्","text":"pratimarśasya mātrā tu dvitrivindumitā matā pratyekaśo nāsikayā snehaneti viniścitam"},{"type":"verse","number":"226","sanskrit":"स्नेहे ग्रन्थिद्वयं यावन्निमग्ना चोद्धृता ततः तर्जनी यं स्रवेद्बिन्दुं सा मात्रा बिन्दुसंज्ञिता","text":"snehe granthidvayaṃ yāvannimagnā coddhṛtā tataḥ tarjanī yaṃ sravedbinduṃ sā mātrā bindusaṃjñitā"},{"type":"verse","number":"227","sanskrit":"एवंविधैर्बिन्दुसंज्ञैरष्टाभिः शाण उच्यते स देयो मर्शनस्येषु प्रतिमर्शो द्विबिन्दुकः","text":"evaṃvidhairbindusaṃjñairaṣṭābhiḥ śāṇa ucyate sa deyo marśanasyeṣu pratimarśo dvibindukaḥ"},{"type":"verse","number":"228","sanskrit":"समयाः प्रतिमर्शस्य बुधैः प्रोक्ताश्चतुर्दश प्रभाते दन्तकाष्ठान्ते गृहान्निर्गमने तथा","text":"samayāḥ pratimarśasya budhaiḥ proktāścaturdaśa prabhāte dantakāṣṭhānte gṛhānnirgamane tathā"},{"type":"verse","number":"229","sanskrit":"व्यायामाध्वव्यवायान्ते विण्मूत्रान्तेऽञ्जने कृते कवलान्ते भोजनान्ते दिवास्वप्नोस्त्थिते तथा","text":"vyāyāmādhvavyavāyānte viṇmūtrānte'ñjane kṛte kavalānte bhojanānte divāsvapnostthite tathā"},{"type":"verse","number":"230","sanskrit":"वमनान्ते तथा सायं प्रतिमर्शः प्रयुज्यते","text":"vamanānte tathā sāyaṃ pratimarśaḥ prayujyate"},{"type":"verse","number":"231","sanskrit":"रीषदुच्छिक्कनात्स्नेहो यथा वक्त्रं प्रपद्यते नस्ये निषिक्तं तं विद्यात्प्रतिमर्शप्रमाणतः","text":"rīṣaducchikkanātsneho yathā vaktraṃ prapadyate nasye niṣiktaṃ taṃ vidyātpratimarśapramāṇataḥ"},{"type":"verse","number":"232","sanskrit":"उच्छिष्टं न पिबेन्नैव निष्ठीवेन्मुखमागतम्","text":"ucchiṣṭaṃ na pibennaiva niṣṭhīvenmukhamāgatam"},{"type":"verse","number":"233","sanskrit":"क्षीणे तृष्णाऽस्यशोषार्त्ते बाले वृद्धे च पूज्यते प्रतिमर्शान्न जायन्ते रोगाश्चैवोर्ध्वजत्रुजाः बलीपलितनाशश्च बलमिन्द्रि यजं भवेत्","text":"kṣīṇe tṛṣṇā'syaśoṣārtte bāle vṛddhe ca pūjyate pratimarśānna jāyante rogāścaivordhvajatrujāḥ balīpalitanāśaśca balamindri yajaṃ bhavet"},{"type":"verse","number":"234","sanskrit":"बिभीतनिम्बौ गाम्भारी शिवा शेलुश्च काकिनी एकैकतैलनस्येन पलितं नश्यति ध्रुवम्","text":"bibhītanimbau gāmbhārī śivā śeluśca kākinī ekaikatailanasyena palitaṃ naśyati dhruvam"},{"type":"verse","number":"235","sanskrit":"अथ नस्यविधिं वक्ष्ये नस्यग्रहणहेतवे देशेवातरजोमुक्ते कृतदन्तनिघर्षणम्","text":"atha nasyavidhiṃ vakṣye nasyagrahaṇahetave deśevātarajomukte kṛtadantanigharṣaṇam"},{"type":"verse","number":"236","sanskrit":"विशुद्धं धूमपानेन स्विन्नभालगलं तथा उत्तानशायिनं किञ्चित्प्रलम्बशिरसं नरम्","text":"viśuddhaṃ dhūmapānena svinnabhālagalaṃ tathā uttānaśāyinaṃ kiñcitpralambaśirasaṃ naram"},{"type":"verse","number":"237","sanskrit":"आस्तीर्णहस्तपादञ्च वस्त्राच्छादितलोचनम् समुन्नामितनासाऽग्र वैद्यो नस्येन योजयेत्","text":"āstīrṇahastapādañca vastrācchāditalocanam samunnāmitanāsā'gra vaidyo nasyena yojayet"},{"type":"verse","number":"238","sanskrit":"कोष्णेनाच्छिन्नधारेण हेमतारादिशुक्तिभिः शुक्त्या वा यन्त्रयुक्त्या वा प्लोतैर्वा नस्यमाचरेत्","text":"koṣṇenācchinnadhāreṇa hematārādiśuktibhiḥ śuktyā vā yantrayuktyā vā plotairvā nasyamācaret"},{"type":"verse","number":"239","sanskrit":"नस्येष्वासिच्यमानेषु सिरो नैव प्रकम्पयेत् न कुप्येन्न प्रभाषेत नोच्छिक्केन्न हसेत्तथा","text":"nasyeṣvāsicyamāneṣu siro naiva prakampayet na kupyenna prabhāṣeta nocchikkenna hasettathā"},{"type":"verse","number":"240","sanskrit":"एतैर्हि विहितः स्नेहो नैवान्तं सम्प्रपद्यते ततः कासप्रतिश्यायशिरोऽक्षिगदसम्भवः","text":"etairhi vihitaḥ sneho naivāntaṃ samprapadyate tataḥ kāsapratiśyāyaśiro'kṣigadasambhavaḥ"},{"type":"verse","number":"241","sanskrit":"शृङ्गाटकमभिव्याप्य स्थापयेन्न गिलेद् द्र वम् पञ्च सप्त दशैव स्युर्मात्राः स्नेहस्य धारणे","text":"śṛṅgāṭakamabhivyāpya sthāpayenna giled dra vam pañca sapta daśaiva syurmātrāḥ snehasya dhāraṇe"},{"type":"verse","number":"242","sanskrit":"उपविश्याथ निष्ठीवेन्नासावक्त्रागतं द्र वम् वामदक्षिणपार्श्वाभ्यां निष्ठीवेत्संमुखं न हि","text":"upaviśyātha niṣṭhīvennāsāvaktrāgataṃ dra vam vāmadakṣiṇapārśvābhyāṃ niṣṭhīvetsaṃmukhaṃ na hi"},{"type":"verse","number":"243","sanskrit":"नीते नस्ये मनस्तापं रजःक्रोधञ्च सन्त्यजेत् शयीत निद्रा ं! त्यक्त्वा च प्रोत्तानो वाक्छतं नरः","text":"nīte nasye manastāpaṃ rajaḥkrodhañca santyajet śayīta nidrā ṃ! tyaktvā ca prottāno vākchataṃ naraḥ"},{"type":"verse","number":"244","sanskrit":"तथा शिरोविरेकान्ते धूमो वा कवलो हितः नस्ये त्रीण्युपदिष्टानि लक्षणानि प्रयोगतः","text":"tathā śirovirekānte dhūmo vā kavalo hitaḥ nasye trīṇyupadiṣṭāni lakṣaṇāni prayogataḥ"},{"type":"verse","number":"245","sanskrit":"शुद्धहीनातियोगा हि विज्ञेयाः शास्त्रचिन्तकैः लाघवं मलसंशुद्धिः स्रोतसां व्याधिसंक्षयः चित्तेन्द्रि यप्रसादश्च शिरसः शुद्धिलक्षणम्","text":"śuddhahīnātiyogā hi vijñeyāḥ śāstracintakaiḥ lāghavaṃ malasaṃśuddhiḥ srotasāṃ vyādhisaṃkṣayaḥ cittendri yaprasādaśca śirasaḥ śuddhilakṣaṇam"},{"type":"verse","number":"246","sanskrit":"कण्डूःप्रदेहो गुरुता स्रोतसां कफसंस्रवः मूर्ध्नि हीनाविशुद्धेस्तु लक्षणं परिकीर्त्तितम्","text":"kaṇḍūḥpradeho gurutā srotasāṃ kaphasaṃsravaḥ mūrdhni hīnāviśuddhestu lakṣaṇaṃ parikīrttitam"},{"type":"verse","number":"247","sanskrit":"मस्तुलुङ्गागमो वातवृद्धिरिन्द्रि यविभ्रमः शून्यता शिरसश्चापि मूर्ध्नि गाढं विरेचिते","text":"mastuluṅgāgamo vātavṛddhirindri yavibhramaḥ śūnyatā śirasaścāpi mūrdhni gāḍhaṃ virecite"},{"type":"verse","number":"248","sanskrit":"हीनातिशुद्धे शिरसि कफवातघ्नमाचरेत् तत्र हीनेन नस्येन शुद्धे वातघ्नमाचरेत्","text":"hīnātiśuddhe śirasi kaphavātaghnamācaret tatra hīnena nasyena śuddhe vātaghnamācaret"},{"type":"verse","number":"249","sanskrit":"सम्यग्विशुद्धे शिरसि सर्पिर्नस्येन दीयते कफप्रसेकः शिरसो गुरुतेन्द्रि यविभ्रमः","text":"samyagviśuddhe śirasi sarpirnasyena dīyate kaphaprasekaḥ śiraso gurutendri yavibhramaḥ"},{"type":"verse","number":"250","sanskrit":"लक्षणं तदतिस्निग्धे तत्र रूक्षं प्रदापयेत् भोजयेच्चानभिष्यन्दि नस्ये वातिकमादिशेत्","text":"lakṣaṇaṃ tadatisnigdhe tatra rūkṣaṃ pradāpayet bhojayeccānabhiṣyandi nasye vātikamādiśet"},{"type":"verse","number":"251","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे परिभाषाऽदिप्रकरणे पञ्चमं पञ्चकर्मविधिप्रकरणं समाप्तम् ५","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe paribhāṣā'diprakaraṇe pañcamaṃ pañcakarmavidhiprakaraṇaṃ samāptam 5"}]},{"sthana":"Пурвакханда","number":11,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 6"},{"type":"verse","number":"1","sanskrit":"धूमस्तु षड्विधः प्रोक्तः शमनो बृंहणस्तथा रेचनः कासहा चैव वामनो व्रणधूपनः","text":"dhūmastu ṣaḍvidhaḥ proktaḥ śamano bṛṃhaṇastathā recanaḥ kāsahā caiva vāmano vraṇadhūpanaḥ"},{"type":"verse","number":"2","sanskrit":"शमनस्य तु पर्यायौ मध्यः प्रायोगिकस्तथा बृंहणस्य च पर्यायौ स्नेहनो मृदुरेव च","text":"śamanasya tu paryāyau madhyaḥ prāyogikastathā bṛṃhaṇasya ca paryāyau snehano mṛdureva ca"},{"type":"verse","number":"3","sanskrit":"रेचनस्यापि पर्यायौ शोधनस्तीक्ष्ण एव च अधूमार्हाश्च खल्वेते श्रान्तो भीतश्च दुःखितः","text":"recanasyāpi paryāyau śodhanastīkṣṇa eva ca adhūmārhāśca khalvete śrānto bhītaśca duḥkhitaḥ"},{"type":"verse","number":"4","sanskrit":"दत्तवस्तिर्विरिक्तश्च रात्रौ जागरितस्तथा पिपासितश्च दाहार्त्तस्तालुशोषी तथोदरी","text":"dattavastirviriktaśca rātrau jāgaritastathā pipāsitaśca dāhārttastāluśoṣī tathodarī"},{"type":"verse","number":"5","sanskrit":"शिरोऽभितापी तिमिरी छर्द्याध्मानप्रपीडितः क्षतोरस्कः प्रमेहार्त्तः पाण्डुरोगी च गर्भिणी","text":"śiro'bhitāpī timirī chardyādhmānaprapīḍitaḥ kṣatoraskaḥ pramehārttaḥ pāṇḍurogī ca garbhiṇī"},{"type":"verse","number":"6","sanskrit":"रूक्षः क्षीणोऽभ्यवहृतक्षीरक्षौद्र घृतासवः भुक्तान्नदधिमत्स्यश्च बालो वृद्धः कृशस्तथा","text":"rūkṣaḥ kṣīṇo'bhyavahṛtakṣīrakṣaudra ghṛtāsavaḥ bhuktānnadadhimatsyaśca bālo vṛddhaḥ kṛśastathā"},{"type":"verse","number":"7","sanskrit":"अकाले चातिपीतश्च धूमः कुर्यादुपद्र वान् तत्रेष्टं सर्पिषः पानं नावनाञ्जनतर्पणम्","text":"akāle cātipītaśca dhūmaḥ kuryādupadra vān tatreṣṭaṃ sarpiṣaḥ pānaṃ nāvanāñjanatarpaṇam"},{"type":"verse","number":"8","sanskrit":"सर्पिरिक्षुरसं द्रा क्षां पयो वा शर्कराऽम्बु वा मधुराम्लौ रसौ वाऽपि वमनाय प्रदापयेत्","text":"sarpirikṣurasaṃ drā kṣāṃ payo vā śarkarā'mbu vā madhurāmlau rasau vā'pi vamanāya pradāpayet"},{"type":"verse","number":"9","sanskrit":"धूमस्तु द्वादशाद्वर्षाद् गृह्यतेऽशीतिकान्न च कासश्वासप्रतिश्यायान् मन्याहनुशिरोरुजः","text":"dhūmastu dvādaśādvarṣād gṛhyate'śītikānna ca kāsaśvāsapratiśyāyān manyāhanuśirorujaḥ"},{"type":"verse","number":"10","sanskrit":"वातश्लेष्मविकारांश्च हन्याद्धूमः सुयोजितः धूमोपयोगात्पुरुषः प्रसन्नेन्द्रि यवाङ्मनाः दृढकेशद्विजश्मश्रुः सुगन्धिवदनो भवेत्","text":"vātaśleṣmavikārāṃśca hanyāddhūmaḥ suyojitaḥ dhūmopayogātpuruṣaḥ prasannendri yavāṅmanāḥ dṛḍhakeśadvijaśmaśruḥ sugandhivadano bhavet"},{"type":"verse","number":"11","sanskrit":"धूमनाडी भवेत्तत्र त्रिखण्डा च त्रिपर्विका कनिष्ठिकापरीणाहा राजमाषागमान्तरा","text":"dhūmanāḍī bhavettatra trikhaṇḍā ca triparvikā kaniṣṭhikāparīṇāhā rājamāṣāgamāntarā"},{"type":"verse","number":"12","sanskrit":"धूमपानी भवेद्दीर्घा शमने रोगिणोऽङ्गुलैः चत्वारिंशन्मितैस्तद्वद् द्वात्रिंशद्भिर्मृदौ मता","text":"dhūmapānī bhaveddīrghā śamane rogiṇo'ṅgulaiḥ catvāriṃśanmitaistadvad dvātriṃśadbhirmṛdau matā"},{"type":"verse","number":"13","sanskrit":"तीक्ष्णे चतुर्विंशतिभिः कासघ्ने षोडशोन्मित्!","text":"tīkṣṇe caturviṃśatibhiḥ kāsaghne ṣoḍaśonmit!"},{"type":"verse","number":"14","sanskrit":"दशाङ्गुलैर्वामनीये तथा स्याद् व्रणनाडिका कलायमण्डलस्थूला कुलत्थागमरन्ध्रिका","text":"daśāṅgulairvāmanīye tathā syād vraṇanāḍikā kalāyamaṇḍalasthūlā kulatthāgamarandhrikā"},{"type":"verse","number":"15","sanskrit":"अथेषिकां प्रलिम्पेच्च सुश्लक्ष्णां द्वादशाङ्गुलाम् धूमद्र व्यस्य कल्केन लेपश्चाष्टाङ्गुलः स्मृतः","text":"atheṣikāṃ pralimpecca suślakṣṇāṃ dvādaśāṅgulām dhūmadra vyasya kalkena lepaścāṣṭāṅgulaḥ smṛtaḥ"},{"type":"verse","number":"16","sanskrit":"कल्कं कर्षमितं लिप्त्वा छायाशुष्कञ्च कारयेत् ईषिकामपनीयाथ स्नेहाक्तां वर्त्तिमादरात्","text":"kalkaṃ karṣamitaṃ liptvā chāyāśuṣkañca kārayet īṣikāmapanīyātha snehāktāṃ varttimādarāt"},{"type":"verse","number":"17","sanskrit":"अङ्गारैर्दीपितां कृत्वा धृत्वा नेत्रस्य रन्ध्रके वदनेन पिबेद् धूमं वदनेनैव संत्यजेत्","text":"aṅgārairdīpitāṃ kṛtvā dhṛtvā netrasya randhrake vadanena pibed dhūmaṃ vadanenaiva saṃtyajet"},{"type":"verse","number":"18","sanskrit":"नासिकाभ्यां ततः पीत्वा मुखेनैव वमेत्सुधीः शरावसम्पुटे क्षिप्त्वा कल्कमङ्गारदीपितम् छिद्रे नेत्रं निवेश्याथ व्रणं तेनैव धूपयेत्","text":"nāsikābhyāṃ tataḥ pītvā mukhenaiva vametsudhīḥ śarāvasampuṭe kṣiptvā kalkamaṅgāradīpitam chidre netraṃ niveśyātha vraṇaṃ tenaiva dhūpayet"},{"type":"verse","number":"19","sanskrit":"एलादिकल्कं शमने स्निग्धं सर्जरसं मृदौ","text":"elādikalkaṃ śamane snigdhaṃ sarjarasaṃ mṛdau"},{"type":"verse","number":"20","sanskrit":"रेचने तीक्ष्णकल्कञ्च श्वासघ्ने क्षुद्र कोषणम् वामने स्नायुचर्माढ्यं दद्याद्धूमस्य पानकम्","text":"recane tīkṣṇakalkañca śvāsaghne kṣudra koṣaṇam vāmane snāyucarmāḍhyaṃ dadyāddhūmasya pānakam"},{"type":"verse","number":"21","sanskrit":"व्रणे निम्बवचाद्यश्च धूपनं संप्रशस्यते अन्येऽपि धूमा गेहेषु कर्त्तव्या रोगशान्तये","text":"vraṇe nimbavacādyaśca dhūpanaṃ saṃpraśasyate anye'pi dhūmā geheṣu karttavyā rogaśāntaye"},{"type":"verse","number":"22","sanskrit":"मयूरपिच्छं निम्बस्य पत्राणि बृहतीफलम् मरिचं हिङ्गु मांसी च बीजं कार्पाससम्भवम्","text":"mayūrapicchaṃ nimbasya patrāṇi bṛhatīphalam maricaṃ hiṅgu māṃsī ca bījaṃ kārpāsasambhavam"},{"type":"verse","number":"23","sanskrit":"छागरोमाहिनिर्मोको विष्ठा वैडालिकी तथा गजदन्तश्च तच्चूर्णं किञ्चिद्घृतविमिश्रितम्","text":"chāgaromāhinirmoko viṣṭhā vaiḍālikī tathā gajadantaśca taccūrṇaṃ kiñcidghṛtavimiśritam"},{"type":"verse","number":"24","sanskrit":"गेहेषु धूपनं दत्तं सर्वान् बालग्रहान् हरेत् पिशाचान् राक्षसान् हत्वा सर्वज्वरहरं भवेत्","text":"geheṣu dhūpanaṃ dattaṃ sarvān bālagrahān haret piśācān rākṣasān hatvā sarvajvaraharaṃ bhavet"},{"type":"verse","number":"25","sanskrit":"मनस्तापं रजःक्रोधौ धूमपाने निवारयेत् नेत्राणि धातुजान्याहुर्नलवंशादिजान्यपि","text":"manastāpaṃ rajaḥkrodhau dhūmapāne nivārayet netrāṇi dhātujānyāhurnalavaṃśādijānyapi"},{"type":"verse","number":"26","sanskrit":"स्नेहक्षीरकषायादिद्र वैः सम्पूर्णमाननम् आपूर्य स्थीयते तावद्विधिर्गण्डूषधारणे","text":"snehakṣīrakaṣāyādidra vaiḥ sampūrṇamānanam āpūrya sthīyate tāvadvidhirgaṇḍūṣadhāraṇe"},{"type":"verse","number":"27","sanskrit":"कफपूर्णास्यता यावच्छेदो दोषस्य वा भवेत् नेत्रघ्राणस्रुतिर्यावत्तावद्गण्डूषधारणम्","text":"kaphapūrṇāsyatā yāvacchedo doṣasya vā bhavet netraghrāṇasrutiryāvattāvadgaṇḍūṣadhāraṇam"},{"type":"verse","number":"28","sanskrit":"गण्डूषान् सुस्थितः कुर्य्यात्स्विन्नभालगलादिकः मनुष्यस्त्रींस्तथा पञ्च सप्त वाऽदोषनाशनात्","text":"gaṇḍūṣān susthitaḥ kuryyātsvinnabhālagalādikaḥ manuṣyastrīṃstathā pañca sapta vā'doṣanāśanāt"},{"type":"verse","number":"29","sanskrit":"चतुर्विधः स्याद् गण्डूषः स्नेहनः शमनस्तथा शोधनो रोपणश्चैव कवलश्चापि तादृशः","text":"caturvidhaḥ syād gaṇḍūṣaḥ snehanaḥ śamanastathā śodhano ropaṇaścaiva kavalaścāpi tādṛśaḥ"},{"type":"verse","number":"30","sanskrit":"स्निग्धोष्णैः स्नैहिको वाते स्वादुशीतैः प्रसादनः पित्ते कट्वम्ललवणैरुष्णैः संशोधनः कफे कषायतिक्तमधुरैः कटूष्णो रोपणो व्रणे","text":"snigdhoṣṇaiḥ snaihiko vāte svāduśītaiḥ prasādanaḥ pitte kaṭvamlalavaṇairuṣṇaiḥ saṃśodhanaḥ kaphe kaṣāyatiktamadhuraiḥ kaṭūṣṇo ropaṇo vraṇe"},{"type":"verse","number":"31","sanskrit":"दद्याद् द्र व्येषु चूर्णञ्च गण्डूषे कोलमात्रकम् कर्षप्रमाणः कल्कश्च कवले दीयते बुधैः","text":"dadyād dra vyeṣu cūrṇañca gaṇḍūṣe kolamātrakam karṣapramāṇaḥ kalkaśca kavale dīyate budhaiḥ"},{"type":"verse","number":"32","sanskrit":"धार्यन्ते पञ्चमाद्वर्षाद्गण्डूषाः कवलादयः","text":"dhāryante pañcamādvarṣādgaṇḍūṣāḥ kavalādayaḥ"},{"type":"verse","number":"33","sanskrit":"व्याधेरपचयस्तुष्टिर्वैशद्यं वक्त्रलाघवम् इन्द्रि याणां प्रसादश्च गण्डूषे विधृते भवेत्","text":"vyādherapacayastuṣṭirvaiśadyaṃ vaktralāghavam indri yāṇāṃ prasādaśca gaṇḍūṣe vidhṛte bhavet"},{"type":"verse","number":"34","sanskrit":"हरेदास्यस्य वैरस्यं शोषं पाकं व्रणं तृषाम् दन्तचालञ्च गण्डूषो वैशद्यं तु करोति हि","text":"haredāsyasya vairasyaṃ śoṣaṃ pākaṃ vraṇaṃ tṛṣām dantacālañca gaṇḍūṣo vaiśadyaṃ tu karoti hi"},{"type":"verse","number":"35","sanskrit":"वातपित्तकफघ्नस्य द्र व्यस्य कवलं मुखे अर्द्धं निक्षिप्य संचर्व्य निष्ठीवेत्कवले विधिः","text":"vātapittakaphaghnasya dra vyasya kavalaṃ mukhe arddhaṃ nikṣipya saṃcarvya niṣṭhīvetkavale vidhiḥ"},{"type":"verse","number":"36","sanskrit":"कवलः कुरुते काङ्क्षां भक्ष्येषु हरते कफम् तृष्णां शोषञ्च वैरस्यं दन्तचालञ्च नाशयेत्","text":"kavalaḥ kurute kāṅkṣāṃ bhakṣyeṣu harate kapham tṛṣṇāṃ śoṣañca vairasyaṃ dantacālañca nāśayet"},{"type":"verse","number":"37","sanskrit":"दन्त जिह्वामुखानां यच्चूर्णकल्कावलेहकैः शनैर्घर्षणमङ्गुल्या तदुक्तं प्रतिसारणम्","text":"danta jihvāmukhānāṃ yaccūrṇakalkāvalehakaiḥ śanairgharṣaṇamaṅgulyā taduktaṃ pratisāraṇam"},{"type":"verse","number":"38","sanskrit":"वैरस्यं मुखदौर्गन्ध्यं मुखशोषं तथा तृषाम् अरुचिं दन्तपीडाञ्च निहन्ति प्रतिसारणम्","text":"vairasyaṃ mukhadaurgandhyaṃ mukhaśoṣaṃ tathā tṛṣām aruciṃ dantapīḍāñca nihanti pratisāraṇam"},{"type":"verse","number":"39","sanskrit":"हीने जाड्यकफोत्क्लेशावरसज्ञानमेव च अतियोगान्मुखे पाकः शोषस्तृष्णावमिः क्लमः","text":"hīne jāḍyakaphotkleśāvarasajñānameva ca atiyogānmukhe pākaḥ śoṣastṛṣṇāvamiḥ klamaḥ"},{"type":"verse","number":"40","sanskrit":"स्वेदश्चतुर्विधः प्रोक्तस्तापोष्मस्वेदसंज्ञितः उपनाहो द्र वः स्वेदः सर्वे वातार्त्तिहारिणः","text":"svedaścaturvidhaḥ proktastāpoṣmasvedasaṃjñitaḥ upanāho dra vaḥ svedaḥ sarve vātārttihāriṇaḥ"},{"type":"verse","number":"41","sanskrit":"स्वेदौ तापोष्मजौ प्रायः श्लेष्मघ्नौ समुदीरितौ उपनाहस्तु वातघ्नः पित्तसङ्गे द्र वो हितः","text":"svedau tāpoṣmajau prāyaḥ śleṣmaghnau samudīritau upanāhastu vātaghnaḥ pittasaṅge dra vo hitaḥ"},{"type":"verse","number":"42","sanskrit":"महाबले महाव्याधौ शीते स्वेदो महान् स्मृतः दुर्बले दुर्बलः स्वेदो मध्यमे मध्यमो मतः बलासे रूक्षणः स्वेदो रूक्षस्निग्धः कफानिले","text":"mahābale mahāvyādhau śīte svedo mahān smṛtaḥ durbale durbalaḥ svedo madhyame madhyamo mataḥ balāse rūkṣaṇaḥ svedo rūkṣasnigdhaḥ kaphānile"},{"type":"verse","number":"43","sanskrit":"कफमेदोवृते वाते कोष्णं गेहं रवेः करान् नियुद्धं मार्गगमनं गुरु प्रावरणं ध्रुवम्","text":"kaphamedovṛte vāte koṣṇaṃ gehaṃ raveḥ karān niyuddhaṃ mārgagamanaṃ guru prāvaraṇaṃ dhruvam"},{"type":"verse","number":"44","sanskrit":"चिन्ताव्यायामभारांश्च सेवेतामयमुक्तये येषां नस्यं प्रदातव्यं वस्तिश्श्चापि हि देहिनाम्","text":"cintāvyāyāmabhārāṃśca sevetāmayamuktaye yeṣāṃ nasyaṃ pradātavyaṃ vastiśścāpi hi dehinām"},{"type":"verse","number":"45","sanskrit":"शोधनीयाश्च ये केचित् पूर्वं स्वेद्याश्च ते मताः स्वेद्या ऊर्ध्वं त्रयोऽपीह भगन्दर्यर्शसस्तथा","text":"śodhanīyāśca ye kecit pūrvaṃ svedyāśca te matāḥ svedyā ūrdhvaṃ trayo'pīha bhagandaryarśasastathā"},{"type":"verse","number":"46","sanskrit":"अश्मर्या चातुरो जन्तुः शययेच्छस्त्रकर्मणः","text":"aśmaryā cāturo jantuḥ śayayecchastrakarmaṇaḥ"},{"type":"verse","number":"47","sanskrit":"पश्चात्स्वेद्या हृते शल्ये मूढगर्भगदे तथा काले प्रजाताऽकाले वा पश्चात्स्वेद्या नितम्बिनी","text":"paścātsvedyā hṛte śalye mūḍhagarbhagade tathā kāle prajātā'kāle vā paścātsvedyā nitambinī"},{"type":"verse","number":"48","sanskrit":"सर्वान्स्वेदान्निवाते च जीर्णेऽन्ने वाऽवचारयेत् स्वेदाद्धातुस्थिता दोषाः स्नेहक्लिन्नस्य देहिनः","text":"sarvānsvedānnivāte ca jīrṇe'nne vā'vacārayet svedāddhātusthitā doṣāḥ snehaklinnasya dehinaḥ"},{"type":"verse","number":"49","sanskrit":"द्र वत्वं प्राप्य कोष्ठान्तर्गत्वा यान्ति विरेकताम् स्नेहाभ्यक्तशरीरस्य शीतैराच्छाद्य चक्षुषी स्वेद्यमानशरीरस्य हृदयं शीतलः स्पृशेत्","text":"dra vatvaṃ prāpya koṣṭhāntargatvā yānti virekatām snehābhyaktaśarīrasya śītairācchādya cakṣuṣī svedyamānaśarīrasya hṛdayaṃ śītalaḥ spṛśet"},{"type":"verse","number":"50","sanskrit":"अजीर्णी दुर्बली मेही क्षतक्षीणः पिपासितः","text":"ajīrṇī durbalī mehī kṣatakṣīṇaḥ pipāsitaḥ"},{"type":"verse","number":"51","sanskrit":"अतिसारी रक्तपित्ती पाण्डुरोगी तथोदरी मेदस्वी गर्भिणी चैव न हि स्वेद्या विजानता","text":"atisārī raktapittī pāṇḍurogī tathodarī medasvī garbhiṇī caiva na hi svedyā vijānatā"},{"type":"verse","number":"52","sanskrit":"स्वेदादेषां याति देहो विनाशं नो साध्यत्वं यान्ति तेषां विकाराः","text":"svedādeṣāṃ yāti deho vināśaṃ no sādhyatvaṃ yānti teṣāṃ vikārāḥ"},{"type":"verse","number":"53","sanskrit":"एतानपि मृदुस्वेदैः स्वेदसाध्यानुपाचरेत् मृदुस्वेदं प्रयुञ्जीत तथा हृन्मुष्कदृष्टिषु","text":"etānapi mṛdusvedaiḥ svedasādhyānupācaret mṛdusvedaṃ prayuñjīta tathā hṛnmuṣkadṛṣṭiṣu"},{"type":"verse","number":"54","sanskrit":"अतिस्वेदात्सन्धिपीठा दाहस्तृष्णा क्लमो भ्रमः पित्तासृक्पिडिकाकोपस्तत्र शीतैरुपाचरेत्","text":"atisvedātsandhipīṭhā dāhastṛṣṇā klamo bhramaḥ pittāsṛkpiḍikākopastatra śītairupācaret"},{"type":"verse","number":"55","sanskrit":"तेषु तापाभिधः स्वेदो बालुकावस्त्रपाणिभिः कपालकन्दुकाङ्गारैर्यथायोग्यं हि जायते","text":"teṣu tāpābhidhaḥ svedo bālukāvastrapāṇibhiḥ kapālakandukāṅgārairyathāyogyaṃ hi jāyate"},{"type":"verse","number":"56","sanskrit":"प्रतप्तैरम्लसिक्तैश्च कायेऽलक्तकवेष्टिते ऊष्मस्वेदः प्रयोक्तव्यो लोहपिण्डेष्टकादिभिः अथवा वातनिर्णाशिद्र व्यक्वाथरसादिभिः","text":"prataptairamlasiktaiśca kāye'laktakaveṣṭite ūṣmasvedaḥ prayoktavyo lohapiṇḍeṣṭakādibhiḥ athavā vātanirṇāśidra vyakvātharasādibhiḥ"},{"type":"verse","number":"57","sanskrit":"उष्णैर्घटं पूरयित्वा पार्श्वे छिद्रं विधाय च विमुद्र य्स्यां त्रिखण्डां च धातुजां काष्ठजामुत","text":"uṣṇairghaṭaṃ pūrayitvā pārśve chidraṃ vidhāya ca vimudra ysyāṃ trikhaṇḍāṃ ca dhātujāṃ kāṣṭhajāmuta"},{"type":"verse","number":"58","sanskrit":"षडङ्गुलास्यां गोपुच्छां नाडीं युञ्ज्याद् द्विहस्तकाम् सुखोपविष्टं स्वभ्यक्तं गुरुप्रावरणावृतम् हस्तिशुण्डिकया नाड्या स्वेदयेद्वातरोगिणम्","text":"ṣaḍaṅgulāsyāṃ gopucchāṃ nāḍīṃ yuñjyād dvihastakām sukhopaviṣṭaṃ svabhyaktaṃ guruprāvaraṇāvṛtam hastiśuṇḍikayā nāḍyā svedayedvātarogiṇam"},{"type":"verse","number":"59","sanskrit":"पुरुषायाममात्रां वा भूमिं सम्मार्ज्य खादिरैः काष्ठैर्दग्ध्वा तथाऽभ्युक्ष्य क्षीरधान्याम्लवारिभिः","text":"puruṣāyāmamātrāṃ vā bhūmiṃ sammārjya khādiraiḥ kāṣṭhairdagdhvā tathā'bhyukṣya kṣīradhānyāmlavāribhiḥ"},{"type":"verse","number":"60","sanskrit":"वातघ्नपत्रैराच्छाद्य शयानं स्वेदयेन्नरम् एवं माषादिभिः स्विन्नैः शयानं स्वेदमाचरेत्","text":"vātaghnapatrairācchādya śayānaṃ svedayennaram evaṃ māṣādibhiḥ svinnaiḥ śayānaṃ svedamācaret"},{"type":"verse","number":"61","sanskrit":"अथोपनाहस्वेदञ्च कुर्याद्वातहरौषधैः प्रदिह्य देहं वातार्त्तं क्षीरमांसरसादिभिः","text":"athopanāhasvedañca kuryādvātaharauṣadhaiḥ pradihya dehaṃ vātārttaṃ kṣīramāṃsarasādibhiḥ"},{"type":"verse","number":"62","sanskrit":"अम्लपिष्टैः सलवणैः सुखोष्णैः स्नेहसंयुतैः अथ ग्राम्यानूपमांसैर्जीवनीयगणेन च","text":"amlapiṣṭaiḥ salavaṇaiḥ sukhoṣṇaiḥ snehasaṃyutaiḥ atha grāmyānūpamāṃsairjīvanīyagaṇena ca"},{"type":"verse","number":"63","sanskrit":"दधिसौवीरकक्षीरैर्वीरतर्वादिना तथा कुलत्थमाषगोधूमैरतसीतिलसर्षपैः","text":"dadhisauvīrakakṣīrairvīratarvādinā tathā kulatthamāṣagodhūmairatasītilasarṣapaiḥ"},{"type":"verse","number":"64","sanskrit":"शतपुष्पादेवदारुशेफालीस्थूलजीरकैः एरण्डमूलजीरैश्च रास्नामूलकशिग्रुभिः","text":"śatapuṣpādevadāruśephālīsthūlajīrakaiḥ eraṇḍamūlajīraiśca rāsnāmūlakaśigrubhiḥ"},{"type":"verse","number":"65","sanskrit":"मिसिकृष्णाकुठेरैश्च लवणैरम्लसंयुतैः प्रसारण्यश्वगन्धाभ्यां बलाभिर्दशमूलकैः","text":"misikṛṣṇākuṭheraiśca lavaṇairamlasaṃyutaiḥ prasāraṇyaśvagandhābhyāṃ balābhirdaśamūlakaiḥ"},{"type":"verse","number":"66","sanskrit":"गुडूच्या वानरीवीजैर्यथालाभसमाहृतैः क्षुण्णैः स्विन्नैश्च वस्त्रेण बद्धैः संस्वेदयेन्नरम्","text":"guḍūcyā vānarīvījairyathālābhasamāhṛtaiḥ kṣuṇṇaiḥ svinnaiśca vastreṇa baddhaiḥ saṃsvedayennaram"},{"type":"verse","number":"67","sanskrit":"महाशाल्वणसंज्ञोऽय योगः सर्वानिलार्त्तिहृत्","text":"mahāśālvaṇasaṃjño'ya yogaḥ sarvānilārttihṛt"},{"type":"verse","number":"68","sanskrit":"अथवाऽम्लेन सम्पिष्टैः कोष्णैःसूक्ष्मपटस्थितैः भेषजैः स्वेदयेत् किं वा स्विन्नैः कोष्णैः पटस्थितैः","text":"athavā'mlena sampiṣṭaiḥ koṣṇaiḥsūkṣmapaṭasthitaiḥ bheṣajaiḥ svedayet kiṃ vā svinnaiḥ koṣṇaiḥ paṭasthitaiḥ"},{"type":"verse","number":"69","sanskrit":"द्र वस्वेदस्तु वातघ्नद्र व्यक्वाथेन पूरिते कटाहे कोष्ठके वाऽपि सूपविष्टोऽवगाहयेत्","text":"dra vasvedastu vātaghnadra vyakvāthena pūrite kaṭāhe koṣṭhake vā'pi sūpaviṣṭo'vagāhayet"},{"type":"verse","number":"70","sanskrit":"सौवर्णं राजतं वापि ताम्रं लौहञ्च दारुजम् कोष्ठकं तत्र कुर्वीतोच्छ्राये षड्विंशदङ्गुलम् आयामे वा तदेव स्याच्चतुष्कोणन्तु चिक्कणम्","text":"sauvarṇaṃ rājataṃ vāpi tāmraṃ lauhañca dārujam koṣṭhakaṃ tatra kurvītocchrāye ṣaḍviṃśadaṅgulam āyāme vā tadeva syāccatuṣkoṇantu cikkaṇam"},{"type":"verse","number":"71","sanskrit":"नाभेः षडङ्गुलं यावन्मग्नं क्वाथस्य धारया कोष्णया स्कन्धयोः सिक्तस्तिष्ठेत्स्निग्धतनुर्नरः","text":"nābheḥ ṣaḍaṅgulaṃ yāvanmagnaṃ kvāthasya dhārayā koṣṇayā skandhayoḥ siktastiṣṭhetsnigdhatanurnaraḥ"},{"type":"verse","number":"72","sanskrit":"मुहूर्त्तैकं समारभ्य यावत्स्यात्तच्चतुष्टयम् तावत्तदवगाहेत यावदारोग्यनिश्चयः","text":"muhūrttaikaṃ samārabhya yāvatsyāttaccatuṣṭayam tāvattadavagāheta yāvadārogyaniścayaḥ"},{"type":"verse","number":"73","sanskrit":"एवं तैलेन दुग्धेन सर्पिषा स्वेदयेन्नरम् एकान्तरो द्व्यन्तरो वा युक्तः स्नेहोऽवगाहने","text":"evaṃ tailena dugdhena sarpiṣā svedayennaram ekāntaro dvyantaro vā yuktaḥ sneho'vagāhane"},{"type":"verse","number":"74","sanskrit":"सिरामुखैर्लोमकूपैर्धमनीभिश्च तर्पयेत् शरीरे बलमाधत्ते युक्तः स्नेहोऽवगाहने","text":"sirāmukhairlomakūpairdhamanībhiśca tarpayet śarīre balamādhatte yuktaḥ sneho'vagāhane"},{"type":"verse","number":"75","sanskrit":"जलसिक्तस्य वर्द्धन्ते यथा मूलेऽङकुरादयः तथैव धातुवृद्धिर्हि स्नेहसिक्तस्य जायते","text":"jalasiktasya varddhante yathā mūle'ṅakurādayaḥ tathaiva dhātuvṛddhirhi snehasiktasya jāyate"},{"type":"verse","number":"76","sanskrit":"नातः परतरः कश्चिदुपायो वातनाशनः शीतशूलव्युपरमे स्तम्भगौरवनिग्रहे","text":"nātaḥ parataraḥ kaścidupāyo vātanāśanaḥ śītaśūlavyuparame stambhagauravanigrahe"},{"type":"verse","number":"77","sanskrit":"दीप्तैऽग्नौ मार्दवे जाते स्वेदनाद्विरतिर्मता","text":"dīptai'gnau mārdave jāte svedanādviratirmatā"},{"type":"verse","number":"78","sanskrit":"अभ्यङ्गः परिषेकश्च पिचुर्वस्तिरिति क्रमात् मूर्द्धतैलं चतुर्द्धा स्याद्बलवत्तद्यथोत्तरम्","text":"abhyaṅgaḥ pariṣekaśca picurvastiriti kramāt mūrddhatailaṃ caturddhā syādbalavattadyathottaram"},{"type":"verse","number":"79","sanskrit":"त्रयोऽभ्यङ्गादयः पूर्वे प्रसिद्धाः सर्वतः स्मृताः शिरोवस्तिविधिश्चात्र प्रोच्यते सुज्ञसम्मतः","text":"trayo'bhyaṅgādayaḥ pūrve prasiddhāḥ sarvataḥ smṛtāḥ śirovastividhiścātra procyate sujñasammataḥ"},{"type":"verse","number":"80","sanskrit":"शिरोवस्तिश्चर्मणः स्याद् द्विमुखो द्वादशाङ्गुलः शिरःप्रमाणस्तं बद्ध्वा मस्तके माषपिष्टकैः","text":"śirovastiścarmaṇaḥ syād dvimukho dvādaśāṅgulaḥ śiraḥpramāṇastaṃ baddhvā mastake māṣapiṣṭakaiḥ"},{"type":"verse","number":"81","sanskrit":"सन्धिरोधं विधायाशु स्नेहैः कोष्णैः प्रपूरयेत् तावद्धार्यस्तु यावत्स्यान्नासाकर्णमुखस्रुतिः","text":"sandhirodhaṃ vidhāyāśu snehaiḥ koṣṇaiḥ prapūrayet tāvaddhāryastu yāvatsyānnāsākarṇamukhasrutiḥ"},{"type":"verse","number":"82","sanskrit":"वेदनोपशमो वाऽपि मात्राणां वा सहस्रकम् स्वजानुनः करावर्त्तं कुर्याच्छोटिकया युतम्","text":"vedanopaśamo vā'pi mātrāṇāṃ vā sahasrakam svajānunaḥ karāvarttaṃ kuryācchoṭikayā yutam"},{"type":"verse","number":"83","sanskrit":"एषा मात्रा भवेदेका सर्वत्रैवैष निश्चयः विना भोजनमेवात्र शिरोवस्तिः प्रशस्यते","text":"eṣā mātrā bhavedekā sarvatraivaiṣa niścayaḥ vinā bhojanamevātra śirovastiḥ praśasyate"},{"type":"verse","number":"84","sanskrit":"प्रयोज्यस्तु शिरोवस्तिः पञ्च सप्त दिनानि वा विमोच्य शिरसो बस्तिं गृह्णीयाच्च समन्ततः","text":"prayojyastu śirovastiḥ pañca sapta dināni vā vimocya śiraso bastiṃ gṛhṇīyācca samantataḥ"},{"type":"verse","number":"85","sanskrit":"ऊर्ध्वकायं ततः कोष्णे नीरे स्नानं समाचरेत् अनेन दुर्जया रोगा वातजा यान्ति संक्षयम् शिरःकम्पादयस्तेन सर्वकालेषु युज्यते","text":"ūrdhvakāyaṃ tataḥ koṣṇe nīre snānaṃ samācaret anena durjayā rogā vātajā yānti saṃkṣayam śiraḥkampādayastena sarvakāleṣu yujyate"},{"type":"verse","number":"86","sanskrit":"स्वेदयेत्कर्णदेशन्तु किञ्चिन्नुः पार्श्वशायिनः मूत्रैः स्नेहै रसैरुष्णैः श्रोत्ररन्ध्रं प्रपूरयेत्","text":"svedayetkarṇadeśantu kiñcinnuḥ pārśvaśāyinaḥ mūtraiḥ snehai rasairuṣṇaiḥ śrotrarandhraṃ prapūrayet"},{"type":"verse","number":"87","sanskrit":"कर्णञ्च पूरितं रक्षेच्छतं पञ्च शतानि वा सहस्रं वापि मात्राणां श्रोत्रकण्ठशिरोगदे","text":"karṇañca pūritaṃ rakṣecchataṃ pañca śatāni vā sahasraṃ vāpi mātrāṇāṃ śrotrakaṇṭhaśirogade"},{"type":"verse","number":"88","sanskrit":"मूत्राद्यैः पूरणं कर्णे भोजनात्प्राक्प्रशस्यते तैलाद्यैः पूरणं कर्णे भास्करेऽस्तमुपागते","text":"mūtrādyaiḥ pūraṇaṃ karṇe bhojanātprākpraśasyate tailādyaiḥ pūraṇaṃ karṇe bhāskare'stamupāgate"},{"type":"verse","number":"89","sanskrit":"कर्णे शूलाकुले कोष्णं बस्तमूत्रं ससैन्धवम् निक्षिपेत्तेन शाम्यन्ति शूलपाकादिजा रुजः","text":"karṇe śūlākule koṣṇaṃ bastamūtraṃ sasaindhavam nikṣipettena śāmyanti śūlapākādijā rujaḥ"},{"type":"verse","number":"90","sanskrit":"शृङ्गवेरञ्च मधुकं सैन्धवं तैलमेव च कदुष्णं कर्णयोर्देयमेतत्स्याद्वेदनाऽपहम्","text":"śṛṅgaverañca madhukaṃ saindhavaṃ tailameva ca kaduṣṇaṃ karṇayordeyametatsyādvedanā'paham"},{"type":"verse","number":"91","sanskrit":"पीतार्कपत्रमाज्येन लिप्तं वह्नौ प्रतापयेत् तद्र सः श्रवणे क्षिप्तः कर्णशूलहरः परः","text":"pītārkapatramājyena liptaṃ vahnau pratāpayet tadra saḥ śravaṇe kṣiptaḥ karṇaśūlaharaḥ paraḥ"},{"type":"verse","number":"92","sanskrit":"आलेपस्य तु नामानि लेपो लेपनलिप्तकौ दोषघ्नो विषहा वर्ण्यः स च लेपस्त्रिधा मतः","text":"ālepasya tu nāmāni lepo lepanaliptakau doṣaghno viṣahā varṇyaḥ sa ca lepastridhā mataḥ"},{"type":"verse","number":"93","sanskrit":"त्रिप्रमाणश्चतुर्भागत्रिभागार्द्धाङ्गुलोन्नतः आद्रो र्! व्याधिहरः स स्याच्छुष्को दूषयति च्छविम्","text":"tripramāṇaścaturbhāgatribhāgārddhāṅgulonnataḥ ādro r! vyādhiharaḥ sa syācchuṣko dūṣayati cchavim"},{"type":"verse","number":"94","sanskrit":"दोषघ्नो लेपो यथा शोथघ्नीदारुसिद्धार्थशुण्ठीशोभाञ्जनत्वचाम् आरनालेप पिष्टानां प्रलेपः सर्वशोथहा","text":"doṣaghno lepo yathā śothaghnīdārusiddhārthaśuṇṭhīśobhāñjanatvacām āranālepa piṣṭānāṃ pralepaḥ sarvaśothahā"},{"type":"verse","number":"95","sanskrit":"शिरीषं मधुयष्टी च तगरं रक्तचन्दनम् एला मांसी निशायुग्मं कुष्ठं बालकमेव च","text":"śirīṣaṃ madhuyaṣṭī ca tagaraṃ raktacandanam elā māṃsī niśāyugmaṃ kuṣṭhaṃ bālakameva ca"},{"type":"verse","number":"96","sanskrit":"इति सञ्चूर्ण्य लेपोऽय पञ्चमांशघृतप्लुतः जलेन क्रियते सुज्ञैर्दशाङ्ग इति संज्ञितः","text":"iti sañcūrṇya lepo'ya pañcamāṃśaghṛtaplutaḥ jalena kriyate sujñairdaśāṅga iti saṃjñitaḥ"},{"type":"verse","number":"97","sanskrit":"वीसर्पश्च विषस्फोटाञ्छोथदुष्टव्रणाञ्जयेत्","text":"vīsarpaśca viṣasphoṭāñchothaduṣṭavraṇāñjayet"},{"type":"verse","number":"98","sanskrit":"विषहा लेपो यथा अजादुग्धतिलैर्लेपो नवनीतेन संयुतः शोथमारुष्करं हन्ति लेपो वा कृष्णमार्त्तिकः","text":"viṣahā lepo yathā ajādugdhatilairlepo navanītena saṃyutaḥ śothamāruṣkaraṃ hanti lepo vā kṛṣṇamārttikaḥ"},{"type":"verse","number":"99","sanskrit":"अपरः कृमिविषापहलेपो यथा लाङ्गल्यतिविषाऽलाबूशालिनीबीजमूलकैः लेपो धान्याम्बुसम्पिष्टः कीटविस्फोटनाशनः","text":"aparaḥ kṛmiviṣāpahalepo yathā lāṅgalyativiṣā'lābūśālinībījamūlakaiḥ lepo dhānyāmbusampiṣṭaḥ kīṭavisphoṭanāśanaḥ"},{"type":"verse","number":"100","sanskrit":"मुखकान्तिदो लेपो यथा रक्तचन्दन मञ्जिष्ठा लोध्र कुष्ठ प्रियङ्गवः वटाङ्कुरा मसूराश्च व्यङ्गघ्ना मुखकान्तिदाः","text":"mukhakāntido lepo yathā raktacandana mañjiṣṭhā lodhra kuṣṭha priyaṅgavaḥ vaṭāṅkurā masūrāśca vyaṅgaghnā mukhakāntidāḥ"},{"type":"verse","number":"101","sanskrit":"अथ लेपविधिश्चैव प्रोच्यते सुज्ञसम्मतः आलेपश्च प्रदेहश्च द्वौ भेदौ तस्य भाषितौ","text":"atha lepavidhiścaiva procyate sujñasammataḥ ālepaśca pradehaśca dvau bhedau tasya bhāṣitau"},{"type":"verse","number":"102","sanskrit":"चर्माद्र रं! माहिषं यद्वत्प्रोन्नतं सा मितिस्तयोः शीतस्तनुविशोषी च प्रलेपः पित्तहृन्मतः","text":"carmādra raṃ! māhiṣaṃ yadvatpronnataṃ sā mitistayoḥ śītastanuviśoṣī ca pralepaḥ pittahṛnmataḥ"},{"type":"verse","number":"103","sanskrit":"आद्रो र्! घनस्तथोष्णः स्यात्प्रदेहः श्लेष्मवातहा न रात्रौ लेपनं कुर्याच्छुष्यमाणं न धारयेत् शुष्यमाणमुपेक्षेत प्रदेहं पीडनं प्रति","text":"ādro r! ghanastathoṣṇaḥ syātpradehaḥ śleṣmavātahā na rātrau lepanaṃ kuryācchuṣyamāṇaṃ na dhārayet śuṣyamāṇamupekṣeta pradehaṃ pīḍanaṃ prati"},{"type":"verse","number":"104","sanskrit":"तमसा पिहितो ह्यूष्मा लोमकूपमुखे स्थितः विना लेपेन निर्याति रात्रौ नालेपयेदतः","text":"tamasā pihito hyūṣmā lomakūpamukhe sthitaḥ vinā lepena niryāti rātrau nālepayedataḥ"},{"type":"verse","number":"105","sanskrit":"रात्रावपि प्रलेपादिर्व्रणे देयो विचक्षणैः अपाकिन्यतिगम्भीरे रक्तश्लेष्मसमुद्भवे","text":"rātrāvapi pralepādirvraṇe deyo vicakṣaṇaiḥ apākinyatigambhīre raktaśleṣmasamudbhave"},{"type":"verse","number":"106","sanskrit":"प्रलेपो यथा मधुकं चन्दनं मूर्वा नलमूलञ्च पर्पटम् उशीरं बालकं पद्मं प्रलेपः पित्तशोथहृत्","text":"pralepo yathā madhukaṃ candanaṃ mūrvā nalamūlañca parpaṭam uśīraṃ bālakaṃ padmaṃ pralepaḥ pittaśothahṛt"},{"type":"verse","number":"107","sanskrit":"प्रदेहो यथा बीजपूरजटा हिंस्रा देवदारु महौषधम् रास्नाऽरणिः प्रदेहोऽय वातशोथविनाशनः","text":"pradeho yathā bījapūrajaṭā hiṃsrā devadāru mahauṣadham rāsnā'raṇiḥ pradeho'ya vātaśothavināśanaḥ"},{"type":"verse","number":"108","sanskrit":"कृष्णापुराणपिण्याकशिग्रुत्वक्सिकताशिवाः गोमूत्रपिष्टः कोष्णोऽय प्रदेहः श्लेष्मशोथहा","text":"kṛṣṇāpurāṇapiṇyākaśigrutvaksikatāśivāḥ gomūtrapiṣṭaḥ koṣṇo'ya pradehaḥ śleṣmaśothahā"},{"type":"verse","number":"109","sanskrit":"शोणितं स्रावयेज्जन्तोरामयं प्रसमीक्ष्य च प्रस्थं प्रस्थार्द्धमथ वा प्रस्थार्द्धार्द्धमथापि वा","text":"śoṇitaṃ srāvayejjantorāmayaṃ prasamīkṣya ca prasthaṃ prasthārddhamatha vā prasthārddhārddhamathāpi vā"},{"type":"verse","number":"110","sanskrit":"शरत्काले स्वभावेन शोणितं स्रावयेन्नरः त्वग्दोषग्रन्थिशोथाद्या नश्यन्ति रुधिरोद्भवाः","text":"śaratkāle svabhāvena śoṇitaṃ srāvayennaraḥ tvagdoṣagranthiśothādyā naśyanti rudhirodbhavāḥ"},{"type":"verse","number":"111","sanskrit":"व्यभ्रे वर्षासु विध्येत शीते ग्रीष्मे शरद्यपि मध्याह्ने शीतकाले च रुधिरं स्रावयेद् बुधः","text":"vyabhre varṣāsu vidhyeta śīte grīṣme śaradyapi madhyāhne śītakāle ca rudhiraṃ srāvayed budhaḥ"},{"type":"verse","number":"112","sanskrit":"अनुष्णाशीतं मधुरं स्निग्धं रक्तञ्चवर्णतः शोणितं गुरु विस्रं स्याद् विदाहश्चास्य पित्तवत्","text":"anuṣṇāśītaṃ madhuraṃ snigdhaṃ raktañcavarṇataḥ śoṇitaṃ guru visraṃ syād vidāhaścāsya pittavat"},{"type":"verse","number":"113","sanskrit":"विस्रता द्र वता रागश्चलनं विलयस्तथा भूम्यादिपञ्चभूतानामेते रक्ते गुणाः स्मृताः","text":"visratā dra vatā rāgaścalanaṃ vilayastathā bhūmyādipañcabhūtānāmete rakte guṇāḥ smṛtāḥ"},{"type":"verse","number":"114","sanskrit":"रक्ते दुष्टे भवेच्छोथो रक्तमण्डलमेव च व्यथा दाहश्च पाकश्च कण्डूश्च पिडकोद्गमः","text":"rakte duṣṭe bhavecchotho raktamaṇḍalameva ca vyathā dāhaśca pākaśca kaṇḍūśca piḍakodgamaḥ"},{"type":"verse","number":"115","sanskrit":"वृद्धे रक्ताङ्गनेत्रत्वं सिराणां पूर्णता तथा गात्राणां गौरवं निद्रा मोहो दाहश्च जायते","text":"vṛddhe raktāṅganetratvaṃ sirāṇāṃ pūrṇatā tathā gātrāṇāṃ gauravaṃ nidrā moho dāhaśca jāyate"},{"type":"verse","number":"116","sanskrit":"क्षीणेऽस्रे मधुराकाङ्क्षा मूर्च्छा च त्वचि रूक्षता शैथिल्यं च सिराणां स्याद्वातादुन्मार्गगामिता","text":"kṣīṇe'sre madhurākāṅkṣā mūrcchā ca tvaci rūkṣatā śaithilyaṃ ca sirāṇāṃ syādvātādunmārgagāmitā"},{"type":"verse","number":"117","sanskrit":"अरुणं फेनिलं रूक्षं परुषं तनु शीघ्रगम् आस्कन्दि सूचीनिस्तोदि रक्तं स्याद्वातदूषितम्","text":"aruṇaṃ phenilaṃ rūkṣaṃ paruṣaṃ tanu śīghragam āskandi sūcīnistodi raktaṃ syādvātadūṣitam"},{"type":"verse","number":"118","sanskrit":"पित्तेन पीतं हरितं नीलं श्यावं च विस्रकम् अस्वादूष्णं मक्षिकाणां पिपीलीनामनिष्टकम्","text":"pittena pītaṃ haritaṃ nīlaṃ śyāvaṃ ca visrakam asvādūṣṇaṃ makṣikāṇāṃ pipīlīnāmaniṣṭakam"},{"type":"verse","number":"119","sanskrit":"शीतलं बहुलं स्निग्धं गैरिकोदकसन्निभम् मांसपेशीप्रभं स्कन्दि मन्दगं कफदूषितम्","text":"śītalaṃ bahulaṃ snigdhaṃ gairikodakasannibham māṃsapeśīprabhaṃ skandi mandagaṃ kaphadūṣitam"},{"type":"verse","number":"120","sanskrit":"द्विदोषदुष्टं संसृष्टं त्रिदुष्टं पूतिगन्धकम् सर्वलक्षणसंयुक्तं काञ्जिकाभं च जायते","text":"dvidoṣaduṣṭaṃ saṃsṛṣṭaṃ triduṣṭaṃ pūtigandhakam sarvalakṣaṇasaṃyuktaṃ kāñjikābhaṃ ca jāyate"},{"type":"verse","number":"121","sanskrit":"विषदुष्टं भवेच्छ्यावं नासिकोन्मार्गगं तथा विस्रं काञ्जिकसंकाशं सर्वकुष्ठकरं तथा","text":"viṣaduṣṭaṃ bhavecchyāvaṃ nāsikonmārgagaṃ tathā visraṃ kāñjikasaṃkāśaṃ sarvakuṣṭhakaraṃ tathā"},{"type":"verse","number":"122","sanskrit":"इन्द्र गोपप्रभं ज्ञेयं प्रकृतिस्थमसंहतम्","text":"indra gopaprabhaṃ jñeyaṃ prakṛtisthamasaṃhatam"},{"type":"verse","number":"123","sanskrit":"शोथे दाहेऽङ्गपाके च रक्तवर्णेऽसृजः स्रुतौ वातरक्ते तथा कुष्ठे सपीडे दुर्जयेऽनिले पाण्डुरोगे श्लीपदे च विषदुष्टेच शोणिते","text":"śothe dāhe'ṅgapāke ca raktavarṇe'sṛjaḥ srutau vātarakte tathā kuṣṭhe sapīḍe durjaye'nile pāṇḍuroge ślīpade ca viṣaduṣṭeca śoṇite"},{"type":"verse","number":"124","sanskrit":"ग्रन्थ्यर्बुदापचीक्षुद्र रोगाधिमन्थकाभिधे विदारीस्तनरोगेषु गात्राणां सादगौरवे","text":"granthyarbudāpacīkṣudra rogādhimanthakābhidhe vidārīstanarogeṣu gātrāṇāṃ sādagaurave"},{"type":"verse","number":"125","sanskrit":"रक्ताभिष्यन्दतन्द्रा यां पूतिघ्राणास्यदाहके यकृत्प्लीहविसर्पेषु विद्र धौ पिडकोद्गमे","text":"raktābhiṣyandatandrā yāṃ pūtighrāṇāsyadāhake yakṛtplīhavisarpeṣu vidra dhau piḍakodgame"},{"type":"verse","number":"126","sanskrit":"कर्णौष्ठघ्राणवक्त्राणां पाके दाहे शिरोरुजि उपदंशे रक्तपित्ते रक्तस्रावः प्रशस्यते","text":"karṇauṣṭhaghrāṇavaktrāṇāṃ pāke dāhe śiroruji upadaṃśe raktapitte raktasrāvaḥ praśasyate"},{"type":"verse","number":"127","sanskrit":"एषु रोगेषु शृङ्गैर्वा जलौकाऽलाबुकैरपि अथवापि सिरामोक्षैः कारयेद्र क्तपातनम्","text":"eṣu rogeṣu śṛṅgairvā jalaukā'lābukairapi athavāpi sirāmokṣaiḥ kārayedra ktapātanam"},{"type":"verse","number":"128","sanskrit":"न कुर्वीत सिरामोक्षं कृशस्यातिव्यवायिनः क्लीबस्य भीरोर्गर्भिण्याः सूतायाः पाण्डुरोगिणः","text":"na kurvīta sirāmokṣaṃ kṛśasyātivyavāyinaḥ klībasya bhīrorgarbhiṇyāḥ sūtāyāḥ pāṇḍurogiṇaḥ"},{"type":"verse","number":"129","sanskrit":"पञ्चकर्मविशुद्धस्य पीतस्नेहस्य चार्शसाम् सर्वाङ्गशोथयुक्तानामुदरिश्वासकासिनाम्","text":"pañcakarmaviśuddhasya pītasnehasya cārśasām sarvāṅgaśothayuktānāmudariśvāsakāsinām"},{"type":"verse","number":"130","sanskrit":"छर्द्यतीसारजुष्टानामतिस्विन्नतनोरपि ऊनषोडशवर्षस्य गतसप्ततिकस्य च","text":"chardyatīsārajuṣṭānāmatisvinnatanorapi ūnaṣoḍaśavarṣasya gatasaptatikasya ca"},{"type":"verse","number":"131","sanskrit":"आघातात्स्रुतरक्तस्य सिरामोक्षो न शस्यते","text":"āghātātsrutaraktasya sirāmokṣo na śasyate"},{"type":"verse","number":"132","sanskrit":"एषां चात्ययिके रोगे जलौकाभिर्विनिर्हरेत् तथा च विषजुष्टानां सिरामोक्षो न शस्यते","text":"eṣāṃ cātyayike roge jalaukābhirvinirharet tathā ca viṣajuṣṭānāṃ sirāmokṣo na śasyate"},{"type":"verse","number":"133","sanskrit":"गोशृङ्गेण जलौकाभिरलाबूभिरपि त्रिधा वातपित्तकफैर्दुष्टं शोणितं स्रावयेद् बुधः","text":"gośṛṅgeṇa jalaukābhiralābūbhirapi tridhā vātapittakaphairduṣṭaṃ śoṇitaṃ srāvayed budhaḥ"},{"type":"verse","number":"134","sanskrit":"द्विदोषाभ्यान्तु दुष्टं यत्त्रिदोषैरपिदूषितम् शोणितं स्रावयेद्युक्त्यासिरामोक्षैः पदैस्तथा","text":"dvidoṣābhyāntu duṣṭaṃ yattridoṣairapidūṣitam śoṇitaṃ srāvayedyuktyāsirāmokṣaiḥ padaistathā"},{"type":"verse","number":"135","sanskrit":"गृह्णाति शोणितं शृङ्गं दशाङ्गुलमितं बलात् जलौकाहस्तमात्रं तु तुम्बी तु द्वादशाङ्गुलम्","text":"gṛhṇāti śoṇitaṃ śṛṅgaṃ daśāṅgulamitaṃ balāt jalaukāhastamātraṃ tu tumbī tu dvādaśāṅgulam"},{"type":"verse","number":"136","sanskrit":"पदमङ्गुलमात्रस्य सिरा सर्वाङ्गशोधिनी शीते निरन्ने मूर्छार्त्तिनिद्रा भीतिमदश्रमैः","text":"padamaṅgulamātrasya sirā sarvāṅgaśodhinī śīte niranne mūrchārttinidrā bhītimadaśramaiḥ"},{"type":"verse","number":"137","sanskrit":"युक्तानां न स्रवेद्र क्तं तथा विण्मूत्रसङ्गिनाम् शोणिते चाप्रवृत्ते तु कुष्ठत्रिकटुसैन्धवैः","text":"yuktānāṃ na sravedra ktaṃ tathā viṇmūtrasaṅginām śoṇite cāpravṛtte tu kuṣṭhatrikaṭusaindhavaiḥ"},{"type":"verse","number":"138","sanskrit":"मर्दयेद् व्रणवक्त्रञ्च तेन रक्तं प्रवर्त्तते तस्मान्न शीते नात्युष्णे नास्विन्ने नातितापिते","text":"mardayed vraṇavaktrañca tena raktaṃ pravarttate tasmānna śīte nātyuṣṇe nāsvinne nātitāpite"},{"type":"verse","number":"139","sanskrit":"पीत्वा यथागूं तृप्तस्य स्रावयेच्छोणितं बुधः अतिस्विन्नस्योष्णकाले तथैवातिसिराव्यधात्","text":"pītvā yathāgūṃ tṛptasya srāvayecchoṇitaṃ budhaḥ atisvinnasyoṣṇakāle tathaivātisirāvyadhāt"},{"type":"verse","number":"140","sanskrit":"अतिप्रवर्त्तते रक्तं तत्र कुर्यात्प्रतिक्रियाम् अतिप्रवृत्ते रक्ते तु लोध्रसर्जरसाञ्जनैः","text":"atipravarttate raktaṃ tatra kuryātpratikriyām atipravṛtte rakte tu lodhrasarjarasāñjanaiḥ"},{"type":"verse","number":"141","sanskrit":"यवगोधूमचूर्णैश्च धवधन्वनगैरिकैः सर्पनिर्मोकचूर्णैर्वा भस्मना क्षौमवस्त्रयोः","text":"yavagodhūmacūrṇaiśca dhavadhanvanagairikaiḥ sarpanirmokacūrṇairvā bhasmanā kṣaumavastrayoḥ"},{"type":"verse","number":"142","sanskrit":"मुखं व्रणस्य बद्ध्वा च शीतैश्चोपचरेद् व्रणम् विध्येदूर्ध्वसिरां तावद्दहेत्क्षारेण वह्निना","text":"mukhaṃ vraṇasya baddhvā ca śītaiścopacared vraṇam vidhyedūrdhvasirāṃ tāvaddahetkṣāreṇa vahninā"},{"type":"verse","number":"143","sanskrit":"व्रणं कषायः सन्धत्ते रक्तं स्कन्दयते हिमम् व्रणास्यं पाचयेत्क्षारो दाहः सङ्कोचयेत्सिराः","text":"vraṇaṃ kaṣāyaḥ sandhatte raktaṃ skandayate himam vraṇāsyaṃ pācayetkṣāro dāhaḥ saṅkocayetsirāḥ"},{"type":"verse","number":"144","sanskrit":"रक्ते दुष्टेऽवशिष्टेऽपि व्याधिर्नैव प्रकुप्यति अतो रक्षेत्सावशेषं रक्ते नातिस्रुतिर्हिता","text":"rakte duṣṭe'vaśiṣṭe'pi vyādhirnaiva prakupyati ato rakṣetsāvaśeṣaṃ rakte nātisrutirhitā"},{"type":"verse","number":"145","sanskrit":"आन्ध्यमाक्षेपकं तृष्णां तिमिरं शिरसो रुजः पक्षाघातं श्वासकासौ हिक्कादाहौ च पाण्डुताम् कुरुतेऽतिस्रुतं रक्तं मरणं वा करोति च","text":"āndhyamākṣepakaṃ tṛṣṇāṃ timiraṃ śiraso rujaḥ pakṣāghātaṃ śvāsakāsau hikkādāhau ca pāṇḍutām kurute'tisrutaṃ raktaṃ maraṇaṃ vā karoti ca"},{"type":"verse","number":"146","sanskrit":"देहस्योत्पत्तिरसृजा देहस्तेनैव धार्यते रक्तं जीवस्य चाधारस्तस्माद्र क्षेदसृग्बुधः","text":"dehasyotpattirasṛjā dehastenaiva dhāryate raktaṃ jīvasya cādhārastasmādra kṣedasṛgbudhaḥ"},{"type":"verse","number":"147","sanskrit":"शीतोपचारैः कुपिते स्रुतरक्तस्य मारुते कोष्णेन सर्पिषा शोथं सव्यथं परिषेचयेत्","text":"śītopacāraiḥ kupite srutaraktasya mārute koṣṇena sarpiṣā śothaṃ savyathaṃ pariṣecayet"},{"type":"verse","number":"148","sanskrit":"क्षीणस्यैणशशोरभ्रहरिणच्छागमांसजः रसः समुचितः पाने क्षीरः षष्टिकया हितम्","text":"kṣīṇasyaiṇaśaśorabhrahariṇacchāgamāṃsajaḥ rasaḥ samucitaḥ pāne kṣīraḥ ṣaṣṭikayā hitam"},{"type":"verse","number":"149","sanskrit":"पीडाशान्तिर्लघुत्वं च व्याध्युपद्र वसंक्षयः मनःस्वास्थ्यं भवेच्चिह्नं सम्यङ्निःसारितेऽसृजि","text":"pīḍāśāntirlaghutvaṃ ca vyādhyupadra vasaṃkṣayaḥ manaḥsvāsthyaṃ bhaveccihnaṃ samyaṅniḥsārite'sṛji"},{"type":"verse","number":"150","sanskrit":"व्यायाममैथुनक्रोधशीतस्नानप्रवातकान् एकाशनं दिवानिद्रा क्षाराम्लकटुभोजनम्","text":"vyāyāmamaithunakrodhaśītasnānapravātakān ekāśanaṃ divānidrā kṣārāmlakaṭubhojanam"},{"type":"verse","number":"151","sanskrit":"शोकं वादमजीर्णञ्च त्यजेदाबलदर्शनात्","text":"śokaṃ vādamajīrṇañca tyajedābaladarśanāt"},{"type":"verse","number":"152","sanskrit":"सेक आश्च्योतनं पिण्डी विडालस्तर्पणं तथा पुटपाकोऽञ्जनं चैभिः कल्पैर्नेत्रमुपाचरेत्","text":"seka āścyotanaṃ piṇḍī viḍālastarpaṇaṃ tathā puṭapāko'ñjanaṃ caibhiḥ kalpairnetramupācaret"},{"type":"verse","number":"153","sanskrit":"सेकस्तु सूक्ष्मधाराभिः सर्वस्मिन्नयने हितः मीलिताक्षस्य मर्त्यस्य प्रदेयश्चतुरङ्गुलः","text":"sekastu sūkṣmadhārābhiḥ sarvasminnayane hitaḥ mīlitākṣasya martyasya pradeyaścaturaṅgulaḥ"},{"type":"verse","number":"154","sanskrit":"स सस्नेहो भवेद्वाते पित्ते रक्ते च रोपणः लेखनस्तु कफे कार्यस्तस्य मात्राऽभिधीयते","text":"sa sasneho bhavedvāte pitte rakte ca ropaṇaḥ lekhanastu kaphe kāryastasya mātrā'bhidhīyate"},{"type":"verse","number":"155","sanskrit":"षड्भिर्वाचां शतैः स्नेहे चतुभिश्चैव रोपणे तैस्त्रिभिर्लेखने कार्यः सेको नेत्रप्रसादने","text":"ṣaḍbhirvācāṃ śataiḥ snehe catubhiścaiva ropaṇe taistribhirlekhane kāryaḥ seko netraprasādane"},{"type":"verse","number":"156","sanskrit":"निमेषोन्मेषणं पुंसामङ्गुल्या च्छोटिकाऽथ वा गुर्वक्षरोच्चारणं वा वाङ्मात्रेयं स्मृता बुधैः","text":"nimeṣonmeṣaṇaṃ puṃsāmaṅgulyā cchoṭikā'tha vā gurvakṣaroccāraṇaṃ vā vāṅmātreyaṃ smṛtā budhaiḥ"},{"type":"verse","number":"157","sanskrit":"सेकस्तु दिवसे कार्यो रात्रौ चात्यन्तिके गदे एरण्डस्य दलैः पिष्टैः पक्वमाजं पयो हितम् सुखोष्णं नेत्रयोः सिक्तं वाताभिष्यन्दनाशनम्","text":"sekastu divase kāryo rātrau cātyantike gade eraṇḍasya dalaiḥ piṣṭaiḥ pakvamājaṃ payo hitam sukhoṣṇaṃ netrayoḥ siktaṃ vātābhiṣyandanāśanam"},{"type":"verse","number":"158","sanskrit":"क्वाथक्षौद्रा सवस्नेहबिन्दूनां यत्तु पातनम् द्व्यङ्गुलोन्मीलिते नेत्रे प्रोक्तमाश्च्योतनं हितम्","text":"kvāthakṣaudrā savasnehabindūnāṃ yattu pātanam dvyaṅgulonmīlite netre proktamāścyotanaṃ hitam"},{"type":"verse","number":"159","sanskrit":"बिन्दवोऽष्टौ लेखनेषु रोपणे दश बिन्दवः स्नेहने द्वादश प्रोक्तास्ते शीते कोष्णरूपिणः","text":"bindavo'ṣṭau lekhaneṣu ropaṇe daśa bindavaḥ snehane dvādaśa proktāste śīte koṣṇarūpiṇaḥ"},{"type":"verse","number":"160","sanskrit":"उष्णे तु शीतरूपाः स्युः सर्वत्रैवैष निश्चयः वाते तिक्तं तथा स्निग्धं पित्ते मधुरशीतलम्","text":"uṣṇe tu śītarūpāḥ syuḥ sarvatraivaiṣa niścayaḥ vāte tiktaṃ tathā snigdhaṃ pitte madhuraśītalam"},{"type":"verse","number":"161","sanskrit":"कफे तिक्तोष्णरूक्षं च क्रमादाश्च्योतनं हितम् आश्च्योतनानां सर्वेषां मात्रा स्याद्वाक्छतोन्मिता","text":"kaphe tiktoṣṇarūkṣaṃ ca kramādāścyotanaṃ hitam āścyotanānāṃ sarveṣāṃ mātrā syādvākchatonmitā"},{"type":"verse","number":"162","sanskrit":"ततः परं लोचनाभ्यां भेषजानामयोगतः आश्च्योतनं न कर्त्तव्यं निशायां केनचित्क्वचित्","text":"tataḥ paraṃ locanābhyāṃ bheṣajānāmayogataḥ āścyotanaṃ na karttavyaṃ niśāyāṃ kenacitkvacit"},{"type":"verse","number":"163","sanskrit":"बिल्वादिपञ्चमूलेन बृहत्येरण्डशिग्रुमिः क्वाथ आश्च्योतने कोष्णो वाताभिष्यन्दनाशनः","text":"bilvādipañcamūlena bṛhatyeraṇḍaśigrumiḥ kvātha āścyotane koṣṇo vātābhiṣyandanāśanaḥ"},{"type":"verse","number":"164","sanskrit":"युक्तभेषजकल्कस्य पिण्डी कवलमात्रया वस्त्रखण्डेन सम्बद्ध्या नेत्रेऽभिष्यिन्दनाशिनी","text":"yuktabheṣajakalkasya piṇḍī kavalamātrayā vastrakhaṇḍena sambaddhyā netre'bhiṣyindanāśinī"},{"type":"verse","number":"165","sanskrit":"स्निग्धोष्णा पिण्डिका वाते पित्ते सा शीतला मता रूक्षोष्णा श्लेष्मणि प्रोक्ता विधिरुक्तो बुधैरयम्","text":"snigdhoṣṇā piṇḍikā vāte pitte sā śītalā matā rūkṣoṣṇā śleṣmaṇi proktā vidhirukto budhairayam"},{"type":"verse","number":"166","sanskrit":"एरण्डपत्रमूलत्वङ्निर्मिता वातनाशिनी धात्रीविरचिता पित्ते शिग्रुपत्रकृता कफे","text":"eraṇḍapatramūlatvaṅnirmitā vātanāśinī dhātrīviracitā pitte śigrupatrakṛtā kaphe"},{"type":"verse","number":"167","sanskrit":"विडालको बहिर्लेपो नेत्रपक्ष्मविवर्जितः तस्य मात्रा परिज्ञेया मुखालेपविधानवत्","text":"viḍālako bahirlepo netrapakṣmavivarjitaḥ tasya mātrā parijñeyā mukhālepavidhānavat"},{"type":"verse","number":"168","sanskrit":"यष्टीगैरिकसिन्धूत्थदार्वीतार्क्ष्यैः समांशकेः जलपिष्टैर्बहिर्लेपः सर्वनेत्रामयापहः","text":"yaṣṭīgairikasindhūtthadārvītārkṣyaiḥ samāṃśakeḥ jalapiṣṭairbahirlepaḥ sarvanetrāmayāpahaḥ"},{"type":"verse","number":"169","sanskrit":"वातातपरजोहीने वेश्मन्युत्तानशायिनः अभितो माषचूर्णेन क्लिन्नेन परिपिण्डितौ","text":"vātātaparajohīne veśmanyuttānaśāyinaḥ abhito māṣacūrṇena klinnena paripiṇḍitau"},{"type":"verse","number":"170","sanskrit":"समौ दृढावसम्बाधौ कर्त्तव्यौ नेत्रकोशयोः पूरयेद् घृतमण्डेन विलीनेन सुखोदकैः","text":"samau dṛḍhāvasambādhau karttavyau netrakośayoḥ pūrayed ghṛtamaṇḍena vilīnena sukhodakaiḥ"},{"type":"verse","number":"171","sanskrit":"सर्पिषा शतधौतेन क्षीरजेन घृतेन वा निमग्नान्यक्षिपक्ष्माणि यावत्स्युस्तावदेव हि","text":"sarpiṣā śatadhautena kṣīrajena ghṛtena vā nimagnānyakṣipakṣmāṇi yāvatsyustāvadeva hi"},{"type":"verse","number":"172","sanskrit":"पूरयेन्मीलिते नेत्रे तत उन्मीलयेच्छनैः भिषग्भिरेष विख्यातस्तर्पणस्योदितो विधिः","text":"pūrayenmīlite netre tata unmīlayecchanaiḥ bhiṣagbhireṣa vikhyātastarpaṇasyodito vidhiḥ"},{"type":"verse","number":"173","sanskrit":"यद्रू क्षञ्च परिष्यन्दि नेत्रं कुटिलमाविलम् शीर्णपक्ष्मसिरोत्पातकृच्छ्रोन्मीलनसंयुतम्","text":"yadrū kṣañca pariṣyandi netraṃ kuṭilamāvilam śīrṇapakṣmasirotpātakṛcchronmīlanasaṃyutam"},{"type":"verse","number":"174","sanskrit":"तिमिरार्जुनशुक्लाद्यैरभिष्यन्दाधिमन्थकैः शुष्काक्षिपाकशोथाभ्यां युतं वातविपर्ययैः तन्नेत्रं तर्पयेत्सम्यङ् नेत्ररोगविशारदः","text":"timirārjunaśuklādyairabhiṣyandādhimanthakaiḥ śuṣkākṣipākaśothābhyāṃ yutaṃ vātaviparyayaiḥ tannetraṃ tarpayetsamyaṅ netrarogaviśāradaḥ"},{"type":"verse","number":"175","sanskrit":"तर्पणं धारयेद्वर्त्मरोगे वाचां शतं बुधः स्वस्थे कफे सन्धिरोगे वाचां पञ्च शतानि च","text":"tarpaṇaṃ dhārayedvartmaroge vācāṃ śataṃ budhaḥ svasthe kaphe sandhiroge vācāṃ pañca śatāni ca"},{"type":"verse","number":"176","sanskrit":"षट्शतानि कफे कृष्णरोगे सप्त शतानि हि दृष्टिरोगे शतान्यष्टावधिमन्थे सहस्रकम्","text":"ṣaṭśatāni kaphe kṛṣṇaroge sapta śatāni hi dṛṣṭiroge śatānyaṣṭāvadhimanthe sahasrakam"},{"type":"verse","number":"177","sanskrit":"सहस्रं वातरोगेषु धार्यमेव हि तर्पणम्","text":"sahasraṃ vātarogeṣu dhāryameva hi tarpaṇam"},{"type":"verse","number":"178","sanskrit":"पूर्णे चापाङ्गमार्गेण स्रावयित्वाऽक्षि शोधयेत् स्विन्नेन यवपिष्टेन स्नेहवीर्येरितं ततः","text":"pūrṇe cāpāṅgamārgeṇa srāvayitvā'kṣi śodhayet svinnena yavapiṣṭena snehavīryeritaṃ tataḥ"},{"type":"verse","number":"179","sanskrit":"यथास्वं धूमपानेन कफमस्य विरेचयेत् एकाहं वा त्र्! यहं वापि पञ्चाहं तर्पणं चरेत्","text":"yathāsvaṃ dhūmapānena kaphamasya virecayet ekāhaṃ vā tr! yahaṃ vāpi pañcāhaṃ tarpaṇaṃ caret"},{"type":"verse","number":"180","sanskrit":"तर्पणे तृप्तिलिङ्गानि नेत्रस्यैतानि लक्षयेत् सुखस्वप्नावबोधत्वं वैशद्यं नेत्रपाटवम् निर्वृतिर्व्याधिशान्तिश्च क्रियालाघवमेव च","text":"tarpaṇe tṛptiliṅgāni netrasyaitāni lakṣayet sukhasvapnāvabodhatvaṃ vaiśadyaṃ netrapāṭavam nirvṛtirvyādhiśāntiśca kriyālāghavameva ca"},{"type":"verse","number":"181","sanskrit":"गुर्वाविलमतिस्निग्धमश्रुकण्डूपदेहवत् घर्षतोदयुतं नेत्रमतितर्पितमादिशेत्","text":"gurvāvilamatisnigdhamaśrukaṇḍūpadehavat gharṣatodayutaṃ netramatitarpitamādiśet"},{"type":"verse","number":"182","sanskrit":"सास्रावशोफरोगाढ्यमुपदेहसमाकुलम् रूक्षमस्रावमरुणं नेत्रं स्याद्धीनतर्पितम्","text":"sāsrāvaśopharogāḍhyamupadehasamākulam rūkṣamasrāvamaruṇaṃ netraṃ syāddhīnatarpitam"},{"type":"verse","number":"183","sanskrit":"अनयोर्दोषबाहुल्यात्प्रयतेत चिकित्सिते रूक्षस्निग्धोपचाराभ्यामनयोः स्यात्प्रतिक्रिया","text":"anayordoṣabāhulyātprayateta cikitsite rūkṣasnigdhopacārābhyāmanayoḥ syātpratikriyā"},{"type":"verse","number":"184","sanskrit":"दुर्दिनात्युष्णशीतेषु चिन्तायां संभ्रमेषु च अशान्तोपद्र वे चाक्ष्णि तर्पणं न प्रशस्यते","text":"durdinātyuṣṇaśīteṣu cintāyāṃ saṃbhrameṣu ca aśāntopadra ve cākṣṇi tarpaṇaṃ na praśasyate"},{"type":"verse","number":"185","sanskrit":"द्वे बिल्वे स्निग्धमांसस्य परद्र व्यपलं मतम् द्र वस्य कुडवोन्मानं सर्वमेकत्र पेषयेत्","text":"dve bilve snigdhamāṃsasya paradra vyapalaṃ matam dra vasya kuḍavonmānaṃ sarvamekatra peṣayet"},{"type":"verse","number":"186","sanskrit":"तदेकत्र समालोड्य पत्रैः सुपरिवेष्टितम् पुटपाकविधानेन तत्पक्त्वा तद्र सं बुधः","text":"tadekatra samāloḍya patraiḥ supariveṣṭitam puṭapākavidhānena tatpaktvā tadra saṃ budhaḥ"},{"type":"verse","number":"187","sanskrit":"तर्पणोक्तेन विधिना यथावदवधारयेत् दृष्टिमध्ये निषेच्यः स्यान्नित्यमुत्तानशायिनः","text":"tarpaṇoktena vidhinā yathāvadavadhārayet dṛṣṭimadhye niṣecyaḥ syānnityamuttānaśāyinaḥ"},{"type":"verse","number":"188","sanskrit":"स्नेहनो लेखनश्चैव रोपणश्चेति स त्रिधा हितः स्निग्धोऽतिरूक्षस्य स्निग्धस्य स तु लेखनः","text":"snehano lekhanaścaiva ropaṇaśceti sa tridhā hitaḥ snigdho'tirūkṣasya snigdhasya sa tu lekhanaḥ"},{"type":"verse","number":"189","sanskrit":"दृष्टेर्बलार्थमितरः पित्तासृग्व्रणवातनुत्","text":"dṛṣṭerbalārthamitaraḥ pittāsṛgvraṇavātanut"},{"type":"verse","number":"190","sanskrit":"स्नेहमांसवसामज्जमेदःस्वाद्वौषधैः कृतः स्नेहनः पुटपाकः स्याद्धार्यो द्वे वाक्छते तु सः","text":"snehamāṃsavasāmajjamedaḥsvādvauṣadhaiḥ kṛtaḥ snehanaḥ puṭapākaḥ syāddhāryo dve vākchate tu saḥ"},{"type":"verse","number":"191","sanskrit":"जाङ्गलानां यकृन्मांसैर्लैखनद्र व्यसंयुतैः कृष्णलोहरजस्ताम्रशङ्खविद्रुमसिन्धुजैः","text":"jāṅgalānāṃ yakṛnmāṃsairlaikhanadra vyasaṃyutaiḥ kṛṣṇaloharajastāmraśaṅkhavidrumasindhujaiḥ"},{"type":"verse","number":"192","sanskrit":"समुद्र फेनकासीसस्रोतोऽजदधिमस्तुभिः लेखनो वाक्छतं तस्य परं धारणमिष्यते","text":"samudra phenakāsīsasroto'jadadhimastubhiḥ lekhano vākchataṃ tasya paraṃ dhāraṇamiṣyate"},{"type":"verse","number":"193","sanskrit":"स्तन्य जाङ्गलमध्वाज्यतिक्तद्र व्यविपाचितः लेखनात्त्रिगुणो धार्यः पुटपाकस्तु रोपणः","text":"stanya jāṅgalamadhvājyatiktadra vyavipācitaḥ lekhanāttriguṇo dhāryaḥ puṭapākastu ropaṇaḥ"},{"type":"verse","number":"194","sanskrit":"निम्बामृतावृषपटोलनिदिग्धिकाभिः स्यात्पञ्चतिक्तक इति प्रथितो गणोऽयम्","text":"nimbāmṛtāvṛṣapaṭolanidigdhikābhiḥ syātpañcatiktaka iti prathito gaṇo'yam"},{"type":"verse","number":"195","sanskrit":"आचरेत्तर्पणोक्तां तु क्रियां व्यापत्तिदर्शने","text":"ācarettarpaṇoktāṃ tu kriyāṃ vyāpattidarśane"},{"type":"verse","number":"196","sanskrit":"तेजांस्यनिलमाकाशमादर्शं भास्वराणि च नेक्षेत तर्पिते नेत्रे यश्च वा पुटपाकवान्","text":"tejāṃsyanilamākāśamādarśaṃ bhāsvarāṇi ca nekṣeta tarpite netre yaśca vā puṭapākavān"},{"type":"verse","number":"197","sanskrit":"अथ सम्पक्वदोषस्य प्राप्तमञ्जनमाचरेत् अञ्जनं क्रियते येन तद् द्र व्यं चाञ्जनं मतम्","text":"atha sampakvadoṣasya prāptamañjanamācaret añjanaṃ kriyate yena tad dra vyaṃ cāñjanaṃ matam"},{"type":"verse","number":"198","sanskrit":"तत्प्रत्येकं त्रिधा प्रोक्तं लेखनं रोपणं तथा स्नेहनं चेति लिङ्गानि तेषां विस्तरतः शृणु","text":"tatpratyekaṃ tridhā proktaṃ lekhanaṃ ropaṇaṃ tathā snehanaṃ ceti liṅgāni teṣāṃ vistarataḥ śṛṇu"},{"type":"verse","number":"199","sanskrit":"लेखनं क्षारतीक्ष्णाम्लरसैरञ्जनमुच्यते नेत्रवर्त्मसिराजालश्रोत्रशृङ्गाटकस्थितम्","text":"lekhanaṃ kṣāratīkṣṇāmlarasairañjanamucyate netravartmasirājālaśrotraśṛṅgāṭakasthitam"},{"type":"verse","number":"200","sanskrit":"मुखनासाऽक्षिभिर्दोषमुत्क्लिश्य स्रावयेच्च तत् कषायं तिक्तकं चापि सस्नेहं रोपणं मतम्","text":"mukhanāsā'kṣibhirdoṣamutkliśya srāvayecca tat kaṣāyaṃ tiktakaṃ cāpi sasnehaṃ ropaṇaṃ matam"},{"type":"verse","number":"201","sanskrit":"स्नेहस्य शैत्याद्वर्ण्यं स्याद् दृष्टेश्च बलवर्द्धनम् मधुरं स्नेहमण्डं तदञ्जनं स्यात्प्रसादनम्","text":"snehasya śaityādvarṇyaṃ syād dṛṣṭeśca balavarddhanam madhuraṃ snehamaṇḍaṃ tadañjanaṃ syātprasādanam"},{"type":"verse","number":"202","sanskrit":"दृष्टिदोषप्रसादार्थं स्नेहनार्थञ्च तद्धितम् हरेणुमात्रावर्त्तिस्तु लेखनी स्यात्प्रमाणतः","text":"dṛṣṭidoṣaprasādārthaṃ snehanārthañca taddhitam hareṇumātrāvarttistu lekhanī syātpramāṇataḥ"},{"type":"verse","number":"203","sanskrit":"सार्द्धहरेणुकमिता रोपणी वर्त्तिरिष्यते क्रियते स्नेहनी वर्त्तिर्द्विहरेणुकमात्रया","text":"sārddhahareṇukamitā ropaṇī varttiriṣyate kriyate snehanī varttirdvihareṇukamātrayā"},{"type":"verse","number":"204","sanskrit":"रसाञ्जनस्य मात्रा तु पिष्टवर्तिमिता मता चूर्णं तु लेखनं वैद्यैर्द्विशलाकं प्रदीयते रोपणं त्रिशलाकं स्याच्चतस्रः स्नेहनाञ्जने","text":"rasāñjanasya mātrā tu piṣṭavartimitā matā cūrṇaṃ tu lekhanaṃ vaidyairdviśalākaṃ pradīyate ropaṇaṃ triśalākaṃ syāccatasraḥ snehanāñjane"},{"type":"verse","number":"205","sanskrit":"मुखयोर्मुकुलाकारा कलायपरिमण्डला अष्टाङ्गुला शलाका स्यादश्मजा धातुजाऽथ वा","text":"mukhayormukulākārā kalāyaparimaṇḍalā aṣṭāṅgulā śalākā syādaśmajā dhātujā'tha vā"},{"type":"verse","number":"206","sanskrit":"ताम्रलोहाश्मसञ्जाता शलाका लेखने मता सुवर्णरजतोद्भूता स्नेहने समुदाहृता","text":"tāmralohāśmasañjātā śalākā lekhane matā suvarṇarajatodbhūtā snehane samudāhṛtā"},{"type":"verse","number":"207","sanskrit":"अङ्गुली च मृदुत्वेन रोपणे सम्प्रयुज्यते कृष्णभागावधिं लिम्पेदपाङ्गं यावदञ्जनम्","text":"aṅgulī ca mṛdutvena ropaṇe samprayujyate kṛṣṇabhāgāvadhiṃ limpedapāṅgaṃ yāvadañjanam"},{"type":"verse","number":"208","sanskrit":"हेमन्ते शिशिरे चैव मध्याह्नेऽञ्जनमिष्यते पूर्वाह्णेवाऽपराह्णे वा ग्रीष्मे शरदि चेष्यते","text":"hemante śiśire caiva madhyāhne'ñjanamiṣyate pūrvāhṇevā'parāhṇe vā grīṣme śaradi ceṣyate"},{"type":"verse","number":"209","sanskrit":"वर्षास्वनभ्रे नात्युष्णे वसन्ते तु सदैव हि अथ वा सर्वदा प्रातः सायं वाऽञ्जनमाचरेत्","text":"varṣāsvanabhre nātyuṣṇe vasante tu sadaiva hi atha vā sarvadā prātaḥ sāyaṃ vā'ñjanamācaret"},{"type":"verse","number":"210","sanskrit":"नातिशीतोष्णवाताभ्रवेलायां तत्प्रयुज्यते श्रान्तेऽथ रुदिते भीते पीतमद्ये नवज्वरे","text":"nātiśītoṣṇavātābhravelāyāṃ tatprayujyate śrānte'tha rudite bhīte pītamadye navajvare"},{"type":"verse","number":"211","sanskrit":"अजीर्णे वेगघाते च नाञ्जनं सम्प्रयुज्यते रागोपदेहौ तिमिरं शूलं संरम्भमेव च","text":"ajīrṇe vegaghāte ca nāñjanaṃ samprayujyate rāgopadehau timiraṃ śūlaṃ saṃrambhameva ca"},{"type":"verse","number":"212","sanskrit":"निद्रा क्षयञ्च कुरुते निषिद्धे युक्तमञ्जनम्","text":"nidrā kṣayañca kurute niṣiddhe yuktamañjanam"},{"type":"verse","number":"213","sanskrit":"शङ्खनाभिर्बिभीतस्य मज्जा पथ्या मनः शिला पिप्पली मरिचं कुष्ठं वचा चेति समांशकम्","text":"śaṅkhanābhirbibhītasya majjā pathyā manaḥ śilā pippalī maricaṃ kuṣṭhaṃ vacā ceti samāṃśakam"},{"type":"verse","number":"214","sanskrit":"छागक्षीरेण सम्पिष्य वर्त्तिं कुर्याद्यवोन्मिताम् हरेणुमात्रां सम्पिष्य जलैः कुर्याद्यथाऽञ्जनम्","text":"chāgakṣīreṇa sampiṣya varttiṃ kuryādyavonmitām hareṇumātrāṃ sampiṣya jalaiḥ kuryādyathā'ñjanam"},{"type":"verse","number":"215","sanskrit":"तिमिरं मांसवृद्धिञ्च काचं पटलमर्बुदम् रात्र्! यन्धं वार्षिकं पुष्पं वर्त्तिश्चन्द्रो दया हरेत्","text":"timiraṃ māṃsavṛddhiñca kācaṃ paṭalamarbudam rātr! yandhaṃ vārṣikaṃ puṣpaṃ varttiścandro dayā haret"},{"type":"verse","number":"216","sanskrit":"इति चन्द्रो दया वर्त्तिर्लेखनी अशीतिस्तिलपुष्पाणि षष्टिः पिप्पलितण्डुलाः जातीपुष्पाणि पञ्चाशन्मरिचानि तु षोडश","text":"iti candro dayā varttirlekhanī aśītistilapuṣpāṇi ṣaṣṭiḥ pippalitaṇḍulāḥ jātīpuṣpāṇi pañcāśanmaricāni tu ṣoḍaśa"},{"type":"verse","number":"217","sanskrit":"सूक्ष्मं पिष्ट्वाऽम्बुना वर्त्तिः कृता कुसुमिकाऽभिधा तिमिरार्जुनशुक्लानां नाशिनी मांसवृद्धिनुत् एतस्या अञ्जने प्रोक्ता मात्रा सार्धहरेणुका","text":"sūkṣmaṃ piṣṭvā'mbunā varttiḥ kṛtā kusumikā'bhidhā timirārjunaśuklānāṃ nāśinī māṃsavṛddhinut etasyā añjane proktā mātrā sārdhahareṇukā"},{"type":"verse","number":"218","sanskrit":"धात्र्! यक्षपथ्याबीजानि एकद्वित्रिगुणानि च पिष्ट्वा वर्त्तिं जलैः कुर्यादञ्जनं द्विहरेणुकम्","text":"dhātr! yakṣapathyābījāni ekadvitriguṇāni ca piṣṭvā varttiṃ jalaiḥ kuryādañjanaṃ dvihareṇukam"},{"type":"verse","number":"219","sanskrit":"नेत्रस्रावं हरत्याशु वातरक्तरुजं तथा","text":"netrasrāvaṃ haratyāśu vātaraktarujaṃ tathā"},{"type":"verse","number":"220","sanskrit":"तुत्थमाक्षिकसिन्ध्त्थाः सिताशङ्खमनःशिलाः गैरिकं सिन्धुफेनञ्च मरिचं चेति चूर्णयेत्","text":"tutthamākṣikasindhtthāḥ sitāśaṅkhamanaḥśilāḥ gairikaṃ sindhuphenañca maricaṃ ceti cūrṇayet"},{"type":"verse","number":"221","sanskrit":"संयोज्य मधुना कुर्यादञ्जनार्थं रसक्रियाम् वर्त्मरोगार्मतिमिरकाचशुक्लहरीं पराम्","text":"saṃyojya madhunā kuryādañjanārthaṃ rasakriyām vartmarogārmatimirakācaśuklaharīṃ parām"},{"type":"verse","number":"222","sanskrit":"रसाञ्जनं सर्जरसो जातिपुष्पं मनः शिला समुद्र फेनो लवणं गैरिकं मरिचं तथा","text":"rasāñjanaṃ sarjaraso jātipuṣpaṃ manaḥ śilā samudra pheno lavaṇaṃ gairikaṃ maricaṃ tathā"},{"type":"verse","number":"223","sanskrit":"एतत्समांशं मधुना पिष्टं प्रक्लिन्नवर्त्मने अञ्जनं क्लेदकण्डूघ्नं पक्ष्मणाञ्च प्ररोहणम्","text":"etatsamāṃśaṃ madhunā piṣṭaṃ praklinnavartmane añjanaṃ kledakaṇḍūghnaṃ pakṣmaṇāñca prarohaṇam"},{"type":"verse","number":"224","sanskrit":"कतकस्य फलं घृष्ट्वा मधुना नेत्रमञ्जयेत् ईषत्कर्पूरसहितं स्मृतं नेत्रप्रसादनम्","text":"katakasya phalaṃ ghṛṣṭvā madhunā netramañjayet īṣatkarpūrasahitaṃ smṛtaṃ netraprasādanam"},{"type":"verse","number":"225","sanskrit":"दक्षाण्डत्वक्छिलाकाचशङ्खचन्दनसैन्धबैः अञ्जनं हरते नित्यं सर्वानक्षिगदान्बलात्","text":"dakṣāṇḍatvakchilākācaśaṅkhacandanasaindhabaiḥ añjanaṃ harate nityaṃ sarvānakṣigadānbalāt"},{"type":"verse","number":"226","sanskrit":"शिलायां रसकं पिष्ट्वा सम्यगाप्लाव्य वारिणा गृह्णीयात्तज्जलं सर्वं त्यजेच्चूर्णमधोगतम्","text":"śilāyāṃ rasakaṃ piṣṭvā samyagāplāvya vāriṇā gṛhṇīyāttajjalaṃ sarvaṃ tyajeccūrṇamadhogatam"},{"type":"verse","number":"227","sanskrit":"शुष्कं तच्च जलं सर्वं पर्पटीसन्निभं भवेत् विचूर्ण्य भावयेत्सम्यक्त्रिवेलं त्रिफलारसैः","text":"śuṣkaṃ tacca jalaṃ sarvaṃ parpaṭīsannibhaṃ bhavet vicūrṇya bhāvayetsamyaktrivelaṃ triphalārasaiḥ"},{"type":"verse","number":"228","sanskrit":"कर्पूरस्य रजस्तत्र दशमांशेन निक्षिपेत् अञ्जयेन्नयनं तेन सर्वदोषप्रशान्तये समस्तनेत्ररोगघ्नं चूर्णमेतन्न संशयः","text":"karpūrasya rajastatra daśamāṃśena nikṣipet añjayennayanaṃ tena sarvadoṣapraśāntaye samastanetrarogaghnaṃ cūrṇametanna saṃśayaḥ"},{"type":"verse","number":"229","sanskrit":"अग्नितप्तं हि सौवीरं निषिञ्चेत्त्रिफलारसैः सप्तवेलं तथा स्तन्यैः स्त्रीणां सिक्तं विच्!र्णितम्","text":"agnitaptaṃ hi sauvīraṃ niṣiñcettriphalārasaiḥ saptavelaṃ tathā stanyaiḥ strīṇāṃ siktaṃ vic!rṇitam"},{"type":"verse","number":"230","sanskrit":"अञ्जयेत्तेन नयने प्रत्यहं चक्षुषोर्हितम् सर्वानक्षिविकारांस्तु हन्यादेतन्न संशयः","text":"añjayettena nayane pratyahaṃ cakṣuṣorhitam sarvānakṣivikārāṃstu hanyādetanna saṃśayaḥ"},{"type":"verse","number":"231","sanskrit":"गतदोषमपेताश्रु प्रपश्यत्सम्यगम्भसि प्रक्षाल्याक्षि यथादोषं कार्यं प्रत्यञ्जनं ततः","text":"gatadoṣamapetāśru prapaśyatsamyagambhasi prakṣālyākṣi yathādoṣaṃ kāryaṃ pratyañjanaṃ tataḥ"},{"type":"verse","number":"232","sanskrit":"न वा निर्वातदोषेऽक्षिधावनं सम्प्रयोजयेत् प्रत्यञ्जनं तत्रदद्याच्चूर्णं तीक्ष्णप्रसादनम्","text":"na vā nirvātadoṣe'kṣidhāvanaṃ samprayojayet pratyañjanaṃ tatradadyāccūrṇaṃ tīkṣṇaprasādanam"},{"type":"verse","number":"233","sanskrit":"शुद्धे नागे द्रुते तुत्थं शुद्धं सूतं विनिक्षिपेत् कृष्णाञ्जनं तयोस्तुल्यं सर्वमेकत्र चूर्णयेत्","text":"śuddhe nāge drute tutthaṃ śuddhaṃ sūtaṃ vinikṣipet kṛṣṇāñjanaṃ tayostulyaṃ sarvamekatra cūrṇayet"},{"type":"verse","number":"234","sanskrit":"दशमांशेन कर्पूरं तस्मिश्चूर्णे विनिक्षिपेत् एतत्प्रत्यञ्जनं नेत्रगदजिन्नयनामृतम्","text":"daśamāṃśena karpūraṃ tasmiścūrṇe vinikṣipet etatpratyañjanaṃ netragadajinnayanāmṛtam"},{"type":"verse","number":"235","sanskrit":"त्रिफलाभृङ्गशुण्ठीनां रसैस्तद्वच्च सर्पिषा गोमूत्रमध्वजाक्षीरैः सिक्तो नागः प्रतापितः","text":"triphalābhṛṅgaśuṇṭhīnāṃ rasaistadvacca sarpiṣā gomūtramadhvajākṣīraiḥ sikto nāgaḥ pratāpitaḥ"},{"type":"verse","number":"236","sanskrit":"तच्छलाका हरत्येव सर्वान्नेत्रभवान्गदान्","text":"tacchalākā haratyeva sarvānnetrabhavāngadān"},{"type":"verse","number":"237","sanskrit":"इति भेषजानां विधानानि भैषज्यमभ्यवहरेत्प्रभाते प्रायशो बुधः कषायांस्तु विशेषेण तत्र भेदस्तु दर्शितः","text":"iti bheṣajānāṃ vidhānāni bhaiṣajyamabhyavaharetprabhāte prāyaśo budhaḥ kaṣāyāṃstu viśeṣeṇa tatra bhedastu darśitaḥ"},{"type":"verse","number":"238","sanskrit":"ज्ञेयः पञ्चविधः कालो भैषज्यग्रहणे नृणाम् किञ्चित्सूर्योदये जाते तथा दिवसभोजने सायन्तने भोजने च मुहुश्चापि तथा निशि","text":"jñeyaḥ pañcavidhaḥ kālo bhaiṣajyagrahaṇe nṛṇām kiñcitsūryodaye jāte tathā divasabhojane sāyantane bhojane ca muhuścāpi tathā niśi"},{"type":"verse","number":"239","sanskrit":"प्रायः पित्तकफोद्रे के विरेकवमनार्थयोः लेखनार्थे च भैषज्यं प्रभातेऽनन्नमाहरेत्","text":"prāyaḥ pittakaphodre ke virekavamanārthayoḥ lekhanārthe ca bhaiṣajyaṃ prabhāte'nannamāharet"},{"type":"verse","number":"240","sanskrit":"भैषज्यं विगुणेऽपाने भोजनाग्रे प्रशस्यते अरुचौ चित्रभोज्यैश्च मिश्रं रुचिरमाहरेत्","text":"bhaiṣajyaṃ viguṇe'pāne bhojanāgre praśasyate arucau citrabhojyaiśca miśraṃ ruciramāharet"},{"type":"verse","number":"241","sanskrit":"समानवाते विगुणे मन्देऽग्नावतिदीपनम् दद्याद्भोजनमध्ये च भैषज्यं कुशलो भिषक्","text":"samānavāte viguṇe mande'gnāvatidīpanam dadyādbhojanamadhye ca bhaiṣajyaṃ kuśalo bhiṣak"},{"type":"verse","number":"242","sanskrit":"व्यानकोपेतु भैषज्यं भोजनान्ते समाहरेत् हिक्काऽक्षेपककम्पेषु पूर्वमन्ते च भोजनात्","text":"vyānakopetu bhaiṣajyaṃ bhojanānte samāharet hikkā'kṣepakakampeṣu pūrvamante ca bhojanāt"},{"type":"verse","number":"243","sanskrit":"उदाने कुपिते वाते स्वरभङ्गादिकारिणि ग्रासग्रासान्तरे देयं भैषज्यं सान्ध्यभोजने","text":"udāne kupite vāte svarabhaṅgādikāriṇi grāsagrāsāntare deyaṃ bhaiṣajyaṃ sāndhyabhojane"},{"type":"verse","number":"244","sanskrit":"प्राणे प्रदुष्टे सान्ध्यस्य भुक्तस्यान्ते प्रदीयते औषधं प्रायशो धीरैः कालोऽय स्यात्तृतीयकः","text":"prāṇe praduṣṭe sāndhyasya bhuktasyānte pradīyate auṣadhaṃ prāyaśo dhīraiḥ kālo'ya syāttṛtīyakaḥ"},{"type":"verse","number":"245","sanskrit":"मुहुर्मुहुश्च तृट्छर्दिहिक्काश्वासगरेषु च सायञ्च भेषजं दद्यादिति कालश्चतुर्थकः","text":"muhurmuhuśca tṛṭchardihikkāśvāsagareṣu ca sāyañca bheṣajaṃ dadyāditi kālaścaturthakaḥ"},{"type":"verse","number":"246","sanskrit":"ऊर्ध्वजत्रुविकारेषु लेखने बृंहणे तथा पाचने शमने देयमनन्नं भेषजं निशि","text":"ūrdhvajatruvikāreṣu lekhane bṛṃhaṇe tathā pācane śamane deyamanannaṃ bheṣajaṃ niśi"},{"type":"verse","number":"247","sanskrit":"वीर्याधिकं भवति भेषजमन्नहीनं हन्यात्तदामयमसंशयमाशु चैव तद्बालवृद्धयुवतीमृदुभिश्च पीतं ग्लानिं परां नयति चाशु बलक्षयञ्च","text":"vīryādhikaṃ bhavati bheṣajamannahīnaṃ hanyāttadāmayamasaṃśayamāśu caiva tadbālavṛddhayuvatīmṛdubhiśca pītaṃ glāniṃ parāṃ nayati cāśu balakṣayañca"},{"type":"verse","number":"248","sanskrit":"शीघ्रं विपाकमुपयाति बलं न हिंस्यादन्नावृतं न च मुहुर्वदनान्निरेति एतद्धितं स्थविरवालकृशाङ्गनाभ्यः प्राग्भोजनाद्यदशितं किल तच्च तद्वत्","text":"śīghraṃ vipākamupayāti balaṃ na hiṃsyādannāvṛtaṃ na ca muhurvadanānnireti etaddhitaṃ sthaviravālakṛśāṅganābhyaḥ prāgbhojanādyadaśitaṃ kila tacca tadvat"},{"type":"verse","number":"249","sanskrit":"औषधशेषे भुक्तं भोजनशेषे यदौषधं पीतम् न करोति गदोपशमम्प्रकोपयत्यन्यरोगांश्च","text":"auṣadhaśeṣe bhuktaṃ bhojanaśeṣe yadauṣadhaṃ pītam na karoti gadopaśamamprakopayatyanyarogāṃśca"},{"type":"verse","number":"250","sanskrit":"अनुलोमोऽनिलः स्वास्थ्यं क्षुत्तृष्णासुमनस्कताः लघुत्वमिन्द्रि योद्गारशुद्धिर्जीर्णौषधाकृतिः","text":"anulomo'nilaḥ svāsthyaṃ kṣuttṛṣṇāsumanaskatāḥ laghutvamindri yodgāraśuddhirjīrṇauṣadhākṛtiḥ"},{"type":"verse","number":"251","sanskrit":"क्लमो दाहोऽङ्गसदनं भ्रममूर्च्छाशिरोरुजाः अरतिर्बलहानिश्च सावशेषौषधाकृतिः","text":"klamo dāho'ṅgasadanaṃ bhramamūrcchāśirorujāḥ aratirbalahāniśca sāvaśeṣauṣadhākṛtiḥ"},{"type":"verse","number":"252","sanskrit":"देवान्गुरूंस्तथा विप्रान्पूजयित्वा प्रणम्य च आशिषश्च समादाय श्रद्धया भैषजं भजेत्","text":"devāngurūṃstathā viprānpūjayitvā praṇamya ca āśiṣaśca samādāya śraddhayā bhaiṣajaṃ bhajet"},{"type":"verse","number":"253","sanskrit":"रसायनमिवर्षीणां देवानाममृतं यथा सुधेवोत्तमनागानां भैषज्यमिदमस्तु ते","text":"rasāyanamivarṣīṇāṃ devānāmamṛtaṃ yathā sudhevottamanāgānāṃ bhaiṣajyamidamastu te"},{"type":"verse","number":"254","sanskrit":"ब्रह्मदक्षाश्विरुद्रे न्द्र भूचन्द्रा र्कानिलानलाः देवाश्च सौषधिग्रामा भूमिदेवाश्च पान्तु वः","text":"brahmadakṣāśvirudre ndra bhūcandrā rkānilānalāḥ devāśca sauṣadhigrāmā bhūmidevāśca pāntu vaḥ"},{"type":"verse","number":"255","sanskrit":"औषधं हेमरजतमृद्भाजनपरिस्थितम् पिबेदाप्तजनस्याग्रे प्रसन्नवदनेक्षणः","text":"auṣadhaṃ hemarajatamṛdbhājanaparisthitam pibedāptajanasyāgre prasannavadanekṣaṇaḥ"},{"type":"verse","number":"256","sanskrit":"प्रशान्तस्तूपविश्याथ पीत्वा पात्रमधोमुखम् निक्षिप्याचम्य सलिलं ताम्बूलाद्युपयोजयेत्","text":"praśāntastūpaviśyātha pītvā pātramadhomukham nikṣipyācamya salilaṃ tāmbūlādyupayojayet"},{"type":"verse","number":"257","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमन्मिश्रभाव विरचिते भावप्रकाशे परिभाषादिप्रकरणे षष्ठं धूमपानादिविधिप्रकरणं समाप्तम्","text":"iti śrīmiśralaṭakana tanaya śrīmanmiśrabhāva viracite bhāvaprakāśe paribhāṣādiprakaraṇe ṣaṣṭhaṃ dhūmapānādividhiprakaraṇaṃ samāptam"}]},{"sthana":"Пурвакханда","number":12,"lang":"sa","content":[{"type":"heading","heading":"Пурвакханда — Часть II, пракарана 7"},{"type":"verse","number":"1","sanskrit":"दर्शनस्पर्शनप्रश्नैस्तं परीक्षेत रोगिणम् आयुरादि दृशा स्पर्शाच्छीतादि प्रश्नतः परम्","text":"darśanasparśanapraśnaistaṃ parīkṣeta rogiṇam āyurādi dṛśā sparśācchītādi praśnataḥ param"},{"type":"verse","number":"2","sanskrit":"मिथ्यादृष्टा विकारा हि दुराख्यातास्तथैव च तथा दुष्परिदृष्टाश्च मोहयेयुश्चिकित्सकान्","text":"mithyādṛṣṭā vikārā hi durākhyātāstathaiva ca tathā duṣparidṛṣṭāśca mohayeyuścikitsakān"},{"type":"verse","number":"3","sanskrit":"तत्र दर्शनं नेत्रजिह्वामूत्रादीनां कर्त्तव्यम् नेत्रं स्यात्पवनाद्रू क्षं धूम्रवर्णं तथाऽरुणम् कोटरान्तः प्रविष्टं च तथा स्तब्धविलोकनम्","text":"tatra darśanaṃ netrajihvāmūtrādīnāṃ karttavyam netraṃ syātpavanādrū kṣaṃ dhūmravarṇaṃ tathā'ruṇam koṭarāntaḥ praviṣṭaṃ ca tathā stabdhavilokanam"},{"type":"verse","number":"4","sanskrit":"हरिद्रा खण्डवर्णं वा रक्तं वा हरितं तथा दीपद्वेषिसदाहञ्च नेत्रं स्यात्पित्तकोपतः","text":"haridrā khaṇḍavarṇaṃ vā raktaṃ vā haritaṃ tathā dīpadveṣisadāhañca netraṃ syātpittakopataḥ"},{"type":"verse","number":"5","sanskrit":"चक्षुर्बलासबाहुल्यात्स्निग्धं स्यात्सलिलप्लुतम् तथा धवलवर्णञ्च ज्योतिर्हीनं बलान्वितम्","text":"cakṣurbalāsabāhulyātsnigdhaṃ syātsalilaplutam tathā dhavalavarṇañca jyotirhīnaṃ balānvitam"},{"type":"verse","number":"6","sanskrit":"नेत्रं द्विदोषबाहुल्यात्स्याद्दोषद्वयलक्षणम् त्रिदोषलिङ्गसङ्गेन तं मारयति रोगिणम्","text":"netraṃ dvidoṣabāhulyātsyāddoṣadvayalakṣaṇam tridoṣaliṅgasaṅgena taṃ mārayati rogiṇam"},{"type":"verse","number":"7","sanskrit":"त्रिदोषदूषितं नेत्रमन्तर्मग्नं भृशं भवेत् त्रिलिङ्गं सलिलस्रावि प्रान्तेनोन्मीलयत्यपि","text":"tridoṣadūṣitaṃ netramantarmagnaṃ bhṛśaṃ bhavet triliṅgaṃ salilasrāvi prāntenonmīlayatyapi"},{"type":"verse","number":"8","sanskrit":"शाकपत्रप्रभा रूक्षा स्फुटना रसनाऽनिलात् रक्ता श्यावा भवेत्पित्ताल्लिप्ताद्रा र्! धवला कफात्","text":"śākapatraprabhā rūkṣā sphuṭanā rasanā'nilāt raktā śyāvā bhavetpittālliptādrā r! dhavalā kaphāt"},{"type":"verse","number":"9","sanskrit":"परिदग्धा खरस्पर्शा कृष्णा दोषत्रयेऽधिके सैव दोषद्वयाधिक्ये दोषद्वितयलक्षणा","text":"paridagdhā kharasparśā kṛṣṇā doṣatraye'dhike saiva doṣadvayādhikye doṣadvitayalakṣaṇā"},{"type":"verse","number":"10","sanskrit":"वातेन पाण्डुरं मूत्रं रक्तं नीलञ्च पित्ततः रक्तमेव भवेद्र क्ताद्धवलं फेनिलं कफात्","text":"vātena pāṇḍuraṃ mūtraṃ raktaṃ nīlañca pittataḥ raktameva bhavedra ktāddhavalaṃ phenilaṃ kaphāt"},{"type":"verse","number":"11","sanskrit":"अथ शरीरस्य शैत्योष्णत्वादिज्ञानार्थं स्पर्शनं कार्यम् पुंसो दक्षिणहस्तस्य स्त्रियो वामकरस्य तु अङ्गुष्ठमूलगां नाडीं परीक्षेत भिषग्वरः","text":"atha śarīrasya śaityoṣṇatvādijñānārthaṃ sparśanaṃ kāryam puṃso dakṣiṇahastasya striyo vāmakarasya tu aṅguṣṭhamūlagāṃ nāḍīṃ parīkṣeta bhiṣagvaraḥ"},{"type":"verse","number":"12","sanskrit":"अङ्गुलीभिस्तु तिसृभिर्नाडीमवहितः स्पृशेत् तच्चेष्टया सुखं दुःखं जानीयात्कुशलोऽखिलम्","text":"aṅgulībhistu tisṛbhirnāḍīmavahitaḥ spṛśet tacceṣṭayā sukhaṃ duḥkhaṃ jānīyātkuśalo'khilam"},{"type":"verse","number":"13","sanskrit":"सद्यःस्नातस्य सुप्तस्य क्षुत्तृष्णाऽतपशीलिनः व्यायामश्रान्तदेहस्य सम्यङ् नाडी न बुध्यते","text":"sadyaḥsnātasya suptasya kṣuttṛṣṇā'tapaśīlinaḥ vyāyāmaśrāntadehasya samyaṅ nāḍī na budhyate"},{"type":"verse","number":"14","sanskrit":"वातेऽधिके भवेन्नाडी प्रव्यक्ता तर्जनीतले पित्ते व्यक्ता मध्यमायां तृतीयाङ्गुलिगा कफे","text":"vāte'dhike bhavennāḍī pravyaktā tarjanītale pitte vyaktā madhyamāyāṃ tṛtīyāṅguligā kaphe"},{"type":"verse","number":"15","sanskrit":"तर्जनीमध्यमामध्ये वातपित्ताधिके स्फुटा अनामिकायां तर्जन्यां व्यक्ता वातकफे भवेत्","text":"tarjanīmadhyamāmadhye vātapittādhike sphuṭā anāmikāyāṃ tarjanyāṃ vyaktā vātakaphe bhavet"},{"type":"verse","number":"16","sanskrit":"मध्यमाऽनामिकामध्ये स्फुटा पित्तकफेऽधिके अङ्गुलित्रितयेऽपि स्यात्प्रव्यक्ता सन्निपाततः","text":"madhyamā'nāmikāmadhye sphuṭā pittakaphe'dhike aṅgulitritaye'pi syātpravyaktā sannipātataḥ"},{"type":"verse","number":"17","sanskrit":"वाताद्वक्रगतिं धत्ते पित्तादुत्प्लुत्य गामिनी कफान्मन्दगतिर्ज्ञेया सन्निपातादतिद्रुता","text":"vātādvakragatiṃ dhatte pittādutplutya gāminī kaphānmandagatirjñeyā sannipātādatidrutā"},{"type":"verse","number":"18","sanskrit":"वक्रमुत्प्लुत्य चलति धमनी वातपित्ततः वहेद्वक्रञ्च मन्दञ्च वातश्लेष्माधिकत्वतः","text":"vakramutplutya calati dhamanī vātapittataḥ vahedvakrañca mandañca vātaśleṣmādhikatvataḥ"},{"type":"verse","number":"19","sanskrit":"उत्प्लुत्य मन्दं चलति नाडी पित्तकफेऽधिके कामात्क्रोधाद्वेगवहा क्षीणा चिन्ताभयप्लुता","text":"utplutya mandaṃ calati nāḍī pittakaphe'dhike kāmātkrodhādvegavahā kṣīṇā cintābhayaplutā"},{"type":"verse","number":"20","sanskrit":"स्थित्वा स्थित्वा चलेद्या सा हन्ति स्थानच्युता तथा अतिक्षीणा च शीता च प्राणान्हन्ति न संशयः","text":"sthitvā sthitvā caledyā sā hanti sthānacyutā tathā atikṣīṇā ca śītā ca prāṇānhanti na saṃśayaḥ"},{"type":"verse","number":"21","sanskrit":"ज्वरकोपेन धमनी सोष्णावेगवती भवेत् मन्दाग्नेः क्षीणधातोश्च सैव मन्दतरा मता","text":"jvarakopena dhamanī soṣṇāvegavatī bhavet mandāgneḥ kṣīṇadhātośca saiva mandatarā matā"},{"type":"verse","number":"22","sanskrit":"चपला क्षुधितस्य स्यात्तृप्तस्य भवति स्थिरा सुखिनोऽपि स्थिरा ज्ञेया तथा बलवती मता","text":"capalā kṣudhitasya syāttṛptasya bhavati sthirā sukhino'pi sthirā jñeyā tathā balavatī matā"},{"type":"verse","number":"23","sanskrit":"हेतुस्तदनु सम्प्राप्तिः पूर्वरूपञ्च लक्षणम् तथैवोपशयः पञ्च रोगविज्ञानहेतवः","text":"hetustadanu samprāptiḥ pūrvarūpañca lakṣaṇam tathaivopaśayaḥ pañca rogavijñānahetavaḥ"},{"type":"verse","number":"24","sanskrit":"यत्तु न स्याद्विना येन तस्य तद्धेतुरुच्यते शास्त्रे संव्यवहाराय तत्पर्यायान्प्रचक्ष्महे","text":"yattu na syādvinā yena tasya taddheturucyate śāstre saṃvyavahārāya tatparyāyānpracakṣmahe"},{"type":"verse","number":"25","sanskrit":"निदानं कारणं हेतुर्निमित्तं च निबन्धनम् मूलमायतनं तत्र प्रत्ययोऽपि निगद्यते","text":"nidānaṃ kāraṇaṃ heturnimittaṃ ca nibandhanam mūlamāyatanaṃ tatra pratyayo'pi nigadyate"},{"type":"verse","number":"26","sanskrit":"यथा दुष्टेन दोषेण यथा चानुविसर्पता उत्पत्तिरामयस्यासौ सम्प्राप्तिर्जातिरागतिः","text":"yathā duṣṭena doṣeṇa yathā cānuvisarpatā utpattirāmayasyāsau samprāptirjātirāgatiḥ"},{"type":"verse","number":"27","sanskrit":"संख्याविकल्पप्राधान्यबलकालविशेषतः साभिद्यते यथाऽत्रैव वक्ष्यन्तेऽष्टौ ज्वरा इति","text":"saṃkhyāvikalpaprādhānyabalakālaviśeṣataḥ sābhidyate yathā'traiva vakṣyante'ṣṭau jvarā iti"},{"type":"verse","number":"28","sanskrit":"दोषाणां समवेतानां विकल्पॐऽशाशकल्पना","text":"doṣāṇāṃ samavetānāṃ vikalpaoṃ'śāśakalpanā"},{"type":"verse","number":"29","sanskrit":"स्वातन्त्र्! यपारतन्त्र्! याभ्यां व्याधेः प्राधान्यमादिशेत्","text":"svātantr! yapāratantr! yābhyāṃ vyādheḥ prādhānyamādiśet"},{"type":"verse","number":"30","sanskrit":"हेत्वादिकार्त्स्न्यावयवैर्बलाबलविशेषणम्","text":"hetvādikārtsnyāvayavairbalābalaviśeṣaṇam"},{"type":"verse","number":"31","sanskrit":"नक्तंदिनर्त्तुभुक्तांशैर्व्याधिकालो यथामलम्","text":"naktaṃdinarttubhuktāṃśairvyādhikālo yathāmalam"},{"type":"verse","number":"32","sanskrit":"नक्तादेरंशेषु वातादिप्रकोप उक्तो वाग्भटेन ते व्यापिनोऽपि हृन्नाभ्योरधोमध्योर्ध्वसंश्रयाः वयोऽहोरात्रभुक्तानामन्तमध्यादिगाः क्रमात्","text":"naktāderaṃśeṣu vātādiprakopa ukto vāgbhaṭena te vyāpino'pi hṛnnābhyoradhomadhyordhvasaṃśrayāḥ vayo'horātrabhuktānāmantamadhyādigāḥ kramāt"},{"type":"verse","number":"33","sanskrit":"इति ऋतुषु वातादिकोपो यथा वर्षासु शिशिरे वायुः पित्तं शरदि चोष्णके वसन्ते तु कफः कुप्येदेषा प्रकृतिरार्तवी","text":"iti ṛtuṣu vātādikopo yathā varṣāsu śiśire vāyuḥ pittaṃ śaradi coṣṇake vasante tu kaphaḥ kupyedeṣā prakṛtirārtavī"},{"type":"verse","number":"34","sanskrit":"पूर्वरूपन्तु तद्येन विद्याद्भाविनमामयम् सामान्यं च विशिष्टञ्च द्विविधं तदुदाहृतम् सामान्यं तत्र दोषाणां विशेषैरनधिष्ठितम् विशिष्टमीषद्व्यक्तं स्याद्विशेषैश्च समन्वितम्","text":"pūrvarūpantu tadyena vidyādbhāvinamāmayam sāmānyaṃ ca viśiṣṭañca dvividhaṃ tadudāhṛtam sāmānyaṃ tatra doṣāṇāṃ viśeṣairanadhiṣṭhitam viśiṣṭamīṣadvyaktaṃ syādviśeṣaiśca samanvitam"},{"type":"verse","number":"35","sanskrit":"पूर्वरूपं विशिष्टं यद्व्यक्तं तल्लक्षणं स्मृतम् संस्थानं लिङ्गं चिह्नञ्च व्यञ्जनं रूपमाकृतिः","text":"pūrvarūpaṃ viśiṣṭaṃ yadvyaktaṃ tallakṣaṇaṃ smṛtam saṃsthānaṃ liṅgaṃ cihnañca vyañjanaṃ rūpamākṛtiḥ"},{"type":"verse","number":"36","sanskrit":"औषधान्नविहाराणामुपयोगं सुखावहम् नृणामुपशयं विद्यात्सहि सात्म्यमिति स्मृतः","text":"auṣadhānnavihārāṇāmupayogaṃ sukhāvaham nṛṇāmupaśayaṃ vidyātsahi sātmyamiti smṛtaḥ"},{"type":"verse","number":"37","sanskrit":"मधुरलवणसाम्लस्निग्धनस्योष्णनिद्रा गुरुरविकरवस्तिस्वेदसंमर्दनानि दधिघृततिलतैलाभ्यङ्गसन्तर्पणानिप्रकुपितपवमानं शान्तमेतानि कुर्य्युः","text":"madhuralavaṇasāmlasnigdhanasyoṣṇanidrā gururavikaravastisvedasaṃmardanāni dadhighṛtatilatailābhyaṅgasantarpaṇāniprakupitapavamānaṃ śāntametāni kuryyuḥ"},{"type":"verse","number":"38","sanskrit":"तिक्तस्वादुकषायशीतपवनच्छायानिशावीजनं ज्योत्स्नाभूगृहयन्त्रवारिजलजं स्त्रीगात्रसंस्पर्शनम् सर्पिःक्षीरविरेकसेकरुधिरस्रावप्रदेहादिकं पानाहारविहारभेषजमिदं पित्तप्रशान्तिं नयेत्","text":"tiktasvādukaṣāyaśītapavanacchāyāniśāvījanaṃ jyotsnābhūgṛhayantravārijalajaṃ strīgātrasaṃsparśanam sarpiḥkṣīravirekasekarudhirasrāvapradehādikaṃ pānāhāravihārabheṣajamidaṃ pittapraśāntiṃ nayet"},{"type":"verse","number":"39","sanskrit":"रूक्षक्षारकषायतिक्तकटुकव्यायामनिष्ठीवनं धूमात्युष्णशिरोविरेकवमनस्वेदोपवासादिकम् तृड्वाताध्वनियुद्धजागरजलक्रीडाऽङ्गनासेवनं- पानाहारविहारभेषजमिदं श्लेष्माणमुग्रं हरेत्","text":"rūkṣakṣārakaṣāyatiktakaṭukavyāyāmaniṣṭhīvanaṃ dhūmātyuṣṇaśirovirekavamanasvedopavāsādikam tṛḍvātādhvaniyuddhajāgarajalakrīḍā'ṅganāsevanaṃ- pānāhāravihārabheṣajamidaṃ śleṣmāṇamugraṃ haret"},{"type":"verse","number":"40","sanskrit":"सर्वेषामेव रोगाणां निदानं कुपिता मलाः तत्प्रकोपस्य तु प्रोक्तं विविधाहितसेवनम्","text":"sarveṣāmeva rogāṇāṃ nidānaṃ kupitā malāḥ tatprakopasya tu proktaṃ vividhāhitasevanam"},{"type":"verse","number":"41","sanskrit":"नीवारस्त्रिपुटः सतीनचणकश्यामाकमुद्गाढकी निष्पावाश्च मकुष्ठकश्चवरटी मङ्गल्यकः कोद्र वः यद् द्र व्यं कटुकं सतिक्ततुवरं शीतञ्च रूक्षं लघु- स्वल्पाशो विषमाशनं निरशनं भुक्तेह्यजीर्णेऽशनम्","text":"nīvārastripuṭaḥ satīnacaṇakaśyāmākamudgāḍhakī niṣpāvāśca makuṣṭhakaścavaraṭī maṅgalyakaḥ kodra vaḥ yad dra vyaṃ kaṭukaṃ satiktatuvaraṃ śītañca rūkṣaṃ laghu- svalpāśo viṣamāśanaṃ niraśanaṃ bhuktehyajīrṇe'śanam"},{"type":"verse","number":"42","sanskrit":"भुक्तं जीर्णतरं परिश्रमभरोगर्त्तादिकोष्णं ल्लिंइ! घनं- बाहुभ्यांतरणं तरोः प्रपतनं मार्गेऽतियानं पदा दण्डादिप्रहृतिस्तथोच्चपतनं धातुक्षयो जागरो- मार्गस्यावरणंव्यवायभृशता वातादिवेगाहतिः","text":"bhuktaṃ jīrṇataraṃ pariśramabharogarttādikoṣṇaṃ lliṃi! ghanaṃ- bāhubhyāṃtaraṇaṃ taroḥ prapatanaṃ mārge'tiyānaṃ padā daṇḍādiprahṛtistathoccapatanaṃ dhātukṣayo jāgaro- mārgasyāvaraṇaṃvyavāyabhṛśatā vātādivegāhatiḥ"},{"type":"verse","number":"43","sanskrit":"अत्यर्थं वमनं विरेचनमतिस्रावोऽधिकश्चासृजो- रोगान्मांसविहीनताऽतिमदनश्चिन्ता च शोको भयम् वर्षा वै शिशिरो दिनस्य रजनेर्भागौ तृतीयौ घनाः प्राग्वातस्तुहिनं शरीरमरुतो दुष्टेरमी हेतवः","text":"atyarthaṃ vamanaṃ virecanamatisrāvo'dhikaścāsṛjo- rogānmāṃsavihīnatā'timadanaścintā ca śoko bhayam varṣā vai śiśiro dinasya rajanerbhāgau tṛtīyau ghanāḥ prāgvātastuhinaṃ śarīramaruto duṣṭeramī hetavaḥ"},{"type":"verse","number":"44","sanskrit":"कट्वम्लोष्णविदाहितीक्ष्णलवणक्रोधोपवासातप- स्त्रीसम्भोगतृषाक्षुधाऽभिहननव्यायाममद्यादिभिः भुक्ते जीर्यति भोजने च शरदि ग्रीष्मे तथा प्राणिनां मध्याह्ने च तथाऽधरात्रिसमये पित्तप्रकोपो भवेत्","text":"kaṭvamloṣṇavidāhitīkṣṇalavaṇakrodhopavāsātapa- strīsambhogatṛṣākṣudhā'bhihananavyāyāmamadyādibhiḥ bhukte jīryati bhojane ca śaradi grīṣme tathā prāṇināṃ madhyāhne ca tathā'dharātrisamaye pittaprakopo bhavet"},{"type":"verse","number":"45","sanskrit":"विदाहिद्र व्यमुद्गारमम्लं कुर्यात्तथा तृषाम् हृद्विदाहञ्च जनयेत्पाकं गच्छति तच्चिरात्","text":"vidāhidra vyamudgāramamlaṃ kuryāttathā tṛṣām hṛdvidāhañca janayetpākaṃ gacchati taccirāt"},{"type":"verse","number":"46","sanskrit":"माषैस्तिलैः कुलत्थैश्च मत्स्यैर्मेषामिषेण च गव्येन दधितक्रेण नृणां पित्तं प्रकुप्यति","text":"māṣaistilaiḥ kulatthaiśca matsyairmeṣāmiṣeṇa ca gavyena dadhitakreṇa nṛṇāṃ pittaṃ prakupyati"},{"type":"verse","number":"47","sanskrit":"गुरुपटुमधुराम्लस्निग्धमाषैस्तिलैश्च द्र वदधिदिननिद्रा शीतसर्पिः प्रपूरैः प्रथमदिवसभागे रात्रिभागेऽपि चाद्येभवति हि कफकोपो भुक्तमात्रे वसन्ते","text":"gurupaṭumadhurāmlasnigdhamāṣaistilaiśca dra vadadhidinanidrā śītasarpiḥ prapūraiḥ prathamadivasabhāge rātribhāge'pi cādyebhavati hi kaphakopo bhuktamātre vasante"},{"type":"verse","number":"48","sanskrit":"निदानार्थकरो रोगो रोगस्याप्युपलक्ष्यते","text":"nidānārthakaro rogo rogasyāpyupalakṣyate"},{"type":"verse","number":"49","sanskrit":"कश्चिद्धि रोगो रोगस्य हेतुर्भूत्वा प्रशाम्यति","text":"kaściddhi rogo rogasya heturbhūtvā praśāmyati"},{"type":"verse","number":"50","sanskrit":"न प्रशाम्यति चाप्यन्यो हेत्वर्थं कुरुतेऽपि च","text":"na praśāmyati cāpyanyo hetvarthaṃ kurute'pi ca"},{"type":"verse","number":"51","sanskrit":"अत्यन्तकुत्सितावेतौ सदा स्थूलकृशौ नरौ श्रेष्ठो मध्यशरीरस्तु स्थूलः क्षीणो न पूजितः कर्षयेद् बृंहयेच्चापि सदा स्थूलकृशौ नरौ रक्षणञ्चापि मध्यस्य कुर्वीत कुशलो भिषक्","text":"atyantakutsitāvetau sadā sthūlakṛśau narau śreṣṭho madhyaśarīrastu sthūlaḥ kṣīṇo na pūjitaḥ karṣayed bṛṃhayeccāpi sadā sthūlakṛśau narau rakṣaṇañcāpi madhyasya kurvīta kuśalo bhiṣak"},{"type":"verse","number":"52","sanskrit":"क्षपयेद् बृंहयेच्चापि दोषधातुमलान्भिषक् नरो रोगान्वितो यावद्रो गेण रहितो भवेत्","text":"kṣapayed bṛṃhayeccāpi doṣadhātumalānbhiṣak naro rogānvito yāvadro geṇa rahito bhavet"},{"type":"verse","number":"53","sanskrit":"अस्वस्थो येन विधिना स्वस्थो भवति मानवः तमेव कारयेद्वैद्यो यतः स्वास्थ्यं सदेप्सितम्","text":"asvastho yena vidhinā svastho bhavati mānavaḥ tameva kārayedvaidyo yataḥ svāsthyaṃ sadepsitam"},{"type":"verse","number":"54","sanskrit":"समदोषः समाग्निश्च समधातुमलक्रियः प्रसन्नात्मेन्द्रि यमनाः स्वस्थ इत्यभिधीयते","text":"samadoṣaḥ samāgniśca samadhātumalakriyaḥ prasannātmendri yamanāḥ svastha ityabhidhīyate"},{"type":"verse","number":"55","sanskrit":"विण्मूत्राखिलदोषधातुसमता काङ्क्षाऽन्नपाने रुचि- र्भुक्तं जीर्यति पुष्टये परिणतिः स्वप्नावबोधौ सुखम् गृह्णीते विषयान्यथास्वमुचितान्वृत्तिं मनोवृत्तितः स्वस्थस्याभिहितं चतुर्दशविधं जन्तोरिदं लक्षणम्","text":"viṇmūtrākhiladoṣadhātusamatā kāṅkṣā'nnapāne ruci- rbhuktaṃ jīryati puṣṭaye pariṇatiḥ svapnāvabodhau sukham gṛhṇīte viṣayānyathāsvamucitānvṛttiṃ manovṛttitaḥ svasthasyābhihitaṃ caturdaśavidhaṃ jantoridaṃ lakṣaṇam"},{"type":"verse","number":"56","sanskrit":"तत्तद्वृद्धिकराहारविहारातिनिषेवणात् दोषधातुमलानां हि वृद्धिरुक्ता भिषग्वरैः","text":"tattadvṛddhikarāhāravihārātiniṣevaṇāt doṣadhātumalānāṃ hi vṛddhiruktā bhiṣagvaraiḥ"},{"type":"verse","number":"57","sanskrit":"वाते वृद्धे भवेत्कार्श्यं पारुष्यं चोष्णकामिता गाढं मलं बलञ्चाल्पं गात्रस्फूर्त्तिर्विनिद्र ता विण्मूत्रनेत्रगात्राणां पीतत्वं क्षीणमिन्द्रि यम् शीतेच्छातापमूर्च्छाःस्युः पित्ते वृद्धेऽल्पमूत्रता","text":"vāte vṛddhe bhavetkārśyaṃ pāruṣyaṃ coṣṇakāmitā gāḍhaṃ malaṃ balañcālpaṃ gātrasphūrttirvinidra tā viṇmūtranetragātrāṇāṃ pītatvaṃ kṣīṇamindri yam śītecchātāpamūrcchāḥsyuḥ pitte vṛddhe'lpamūtratā"},{"type":"verse","number":"58","sanskrit":"विडादिशौक्ल्यं शीतत्वं गौरवञ्चातिनिद्र ता सन्धिशैथिल्यमुत्क्लेदो मुखसेकः कफेऽधिके","text":"viḍādiśauklyaṃ śītatvaṃ gauravañcātinidra tā sandhiśaithilyamutkledo mukhasekaḥ kaphe'dhike"},{"type":"verse","number":"59","sanskrit":"रसे वृद्धेऽन्नविद्वेषो जायते गात्रगौरवम् लालाप्रसेकश्छर्दिश्च मूर्च्छा सादो भ्रमः कफः","text":"rase vṛddhe'nnavidveṣo jāyate gātragauravam lālāprasekaśchardiśca mūrcchā sādo bhramaḥ kaphaḥ"},{"type":"verse","number":"60","sanskrit":"प्रवृद्धं रुधिरं कुर्याद् गात्रमारक्तवर्णकम् लोचनञ्च तथा रुक्तं सिराः पूरयतेऽपि च","text":"pravṛddhaṃ rudhiraṃ kuryād gātramāraktavarṇakam locanañca tathā ruktaṃ sirāḥ pūrayate'pi ca"},{"type":"verse","number":"61","sanskrit":"रक्तन्तु कुरुते वृद्धं विसर्पप्लीहविद्र धीन् कुष्ठं वातास्रकं गुल्मं सिरापूर्णत्वकामले","text":"raktantu kurute vṛddhaṃ visarpaplīhavidra dhīn kuṣṭhaṃ vātāsrakaṃ gulmaṃ sirāpūrṇatvakāmale"},{"type":"verse","number":"62","sanskrit":"गात्राणां गौरवं निद्रा मदो दाहश्च जायते व्यङ्गाग्निसादसंमोहरक्तत्वङ्नेत्रमूत्रताः","text":"gātrāṇāṃ gauravaṃ nidrā mado dāhaśca jāyate vyaṅgāgnisādasaṃmoharaktatvaṅnetramūtratāḥ"},{"type":"verse","number":"63","sanskrit":"गुदमेढ्रास्यपाकार्शःपिडकामशकास्तथा इन्द्र लुप्ताङ्गमर्दासृग्दरास्तापं कराङ्घ्रिषु","text":"gudameḍhrāsyapākārśaḥpiḍakāmaśakāstathā indra luptāṅgamardāsṛgdarāstāpaṃ karāṅghriṣu"},{"type":"verse","number":"64","sanskrit":"शमयेद्र क्तवृद्ध्य्त्थुआ!न् रक्तस्रुतिविरेचनैः मांसं वृद्धन्तु गण्डौष्ठस्फिगुपस्थोरुवाहुषु जङ्घयोः कुरुते वृद्धिं तथा गात्रस्य गौरवम्","text":"śamayedra ktavṛddhytthuā!n raktasrutivirecanaiḥ māṃsaṃ vṛddhantu gaṇḍauṣṭhasphigupasthoruvāhuṣu jaṅghayoḥ kurute vṛddhiṃ tathā gātrasya gauravam"},{"type":"verse","number":"65","sanskrit":"उदरे पार्श्वयोर्वृद्धिः कासश्वासादयस्तथा दौर्गन्ध्यं स्निग्धता गात्रे मेदोवृद्धौ भवेदिति","text":"udare pārśvayorvṛddhiḥ kāsaśvāsādayastathā daurgandhyaṃ snigdhatā gātre medovṛddhau bhavediti"},{"type":"verse","number":"66","sanskrit":"प्रवृद्धं कुरुते मेदः श्रममल्पेऽपि चेष्टिते तृट्स्वेदगलगण्डौष्ठरोगमेहादिजन्म च","text":"pravṛddhaṃ kurute medaḥ śramamalpe'pi ceṣṭite tṛṭsvedagalagaṇḍauṣṭharogamehādijanma ca"},{"type":"verse","number":"67","sanskrit":"श्वासं स्फिग्जठरग्रीवास्तनानां लम्बनं तथा वृद्धान्यस्थीनि कुर्वन्ति अस्थीन्यन्यानि चास्थिषु","text":"śvāsaṃ sphigjaṭharagrīvāstanānāṃ lambanaṃ tathā vṛddhānyasthīni kurvanti asthīnyanyāni cāsthiṣu"},{"type":"verse","number":"68","sanskrit":"आचरन्ति तथा दन्तान्विकटान्महतस्तथा मज्जा वृद्धः समस्ताङ्गनेत्रगौरवमाचरेत्","text":"ācaranti tathā dantānvikaṭānmahatastathā majjā vṛddhaḥ samastāṅganetragauravamācaret"},{"type":"verse","number":"69","sanskrit":"शुक्राश्मरी शुक्रवृद्धौ शुक्रस्यातिप्रवर्त्तनम् मलप्रवृद्धावाटोपो जायते जठरे व्यथा","text":"śukrāśmarī śukravṛddhau śukrasyātipravarttanam malapravṛddhāvāṭopo jāyate jaṭhare vyathā"},{"type":"verse","number":"70","sanskrit":"मूत्रे वृद्धे मुहुर्मूत्रमाध्मानं वस्तिवेदना स्वेदे वृद्धे तु दौर्गन्ध्यं त्वचि कण्डूश्च जायते","text":"mūtre vṛddhe muhurmūtramādhmānaṃ vastivedanā svede vṛddhe tu daurgandhyaṃ tvaci kaṇḍūśca jāyate"},{"type":"verse","number":"71","sanskrit":"आर्त्तवातिप्रवृत्तिः स्याद्दौर्गन्ध्यं चार्त्तवे भवेत् अङ्गमर्दश्च जायेत लिङ्गं स्यादार्त्तवेऽधिके","text":"ārttavātipravṛttiḥ syāddaurgandhyaṃ cārttave bhavet aṅgamardaśca jāyeta liṅgaṃ syādārttave'dhike"},{"type":"verse","number":"72","sanskrit":"स्तनयोरतिपीनत्वं क्षीरस्रावो मुहुर्मुहुः तोदश्च तत्र भवति स्तन्याधिक्यस्य लक्षणम्","text":"stanayoratipīnatvaṃ kṣīrasrāvo muhurmuhuḥ todaśca tatra bhavati stanyādhikyasya lakṣaṇam"},{"type":"verse","number":"73","sanskrit":"उदरादिप्रवृद्धिस्तु वृद्धे गर्भेऽभिजायते स्वेदश्च गर्भवत्याः स्यात्प्रसवे व्यसनं महत्","text":"udarādipravṛddhistu vṛddhe garbhe'bhijāyate svedaśca garbhavatyāḥ syātprasave vyasanaṃ mahat"},{"type":"verse","number":"74","sanskrit":"तत्तद्ध्रासकराहारविहारपरिषेवणात् दोषधातुमलानां हि ह्रासो निगदितो नृणाम्","text":"tattaddhrāsakarāhāravihārapariṣevaṇāt doṣadhātumalānāṃ hi hrāso nigadito nṛṇām"},{"type":"verse","number":"75","sanskrit":"पूर्वः पूर्वोऽतिवृद्धत्वाद्वर्द्धयेद्धि परस्परम् तस्मादतिप्रवृद्धानां धातूनां ह्रासनं हितम्","text":"pūrvaḥ pūrvo'tivṛddhatvādvarddhayeddhi parasparam tasmādatipravṛddhānāṃ dhātūnāṃ hrāsanaṃ hitam"},{"type":"verse","number":"76","sanskrit":"असात्म्यान्नसदाक्रोधशोकचिन्ताभयश्रमै अतिव्यवायानशनात्यर्थसंशोधन्रपि","text":"asātmyānnasadākrodhaśokacintābhayaśramai ativyavāyānaśanātyarthasaṃśodhanrapi"},{"type":"verse","number":"77","sanskrit":"वेगानां धारणाच्चापि साहसादविघाततः दोषाणामथ धातूनां मलानाञ्च भवेत्क्षयः","text":"vegānāṃ dhāraṇāccāpi sāhasādavighātataḥ doṣāṇāmatha dhātūnāṃ malānāñca bhavetkṣayaḥ"},{"type":"verse","number":"78","sanskrit":"वातक्षयेऽल्पचेष्टत्वं मन्दवाक्यं विसंज्ञता पित्तक्षयेऽधिकः श्लेष्मा वह्निमान्द्यं प्रभाक्षयः","text":"vātakṣaye'lpaceṣṭatvaṃ mandavākyaṃ visaṃjñatā pittakṣaye'dhikaḥ śleṣmā vahnimāndyaṃ prabhākṣayaḥ"},{"type":"verse","number":"79","sanskrit":"सन्धयः शिथिला मूर्च्छा रौक्ष्यं दाहः कफक्षये हृत्पीडा कण्ठशोषौत्वक्शून्यातृट् च रसक्षये","text":"sandhayaḥ śithilā mūrcchā raukṣyaṃ dāhaḥ kaphakṣaye hṛtpīḍā kaṇṭhaśoṣautvakśūnyātṛṭ ca rasakṣaye"},{"type":"verse","number":"80","sanskrit":"सिराः श्लथा हिमाम्लेच्छा त्वक्पारुष्यं क्षयेऽसृजः गण्डौष्ठकन्धरास्कन्धवक्षोजठरसन्धिषु","text":"sirāḥ ślathā himāmlecchā tvakpāruṣyaṃ kṣaye'sṛjaḥ gaṇḍauṣṭhakandharāskandhavakṣojaṭharasandhiṣu"},{"type":"verse","number":"81","sanskrit":"उपस्थशोथपिण्डीषु शुष्कता गात्ररूक्षता तोदो धमन्यः शिथिला भवेयुर्मांससंक्षये","text":"upasthaśothapiṇḍīṣu śuṣkatā gātrarūkṣatā todo dhamanyaḥ śithilā bhaveyurmāṃsasaṃkṣaye"},{"type":"verse","number":"82","sanskrit":"प्लीहाभिवृद्धिः सन्धीनां शून्यता तनुरूक्षता प्रार्थना स्निग्धमांसस्य लिङ्गं स्यान्मेदसः क्षये","text":"plīhābhivṛddhiḥ sandhīnāṃ śūnyatā tanurūkṣatā prārthanā snigdhamāṃsasya liṅgaṃ syānmedasaḥ kṣaye"},{"type":"verse","number":"83","sanskrit":"अस्थिशूलं तनौ रौक्ष्यं नखदन्तत्रुटिस्तथा अस्थिक्षये लिङ्गमेतद्वैद्यैः सर्वैरुदाहृतम्","text":"asthiśūlaṃ tanau raukṣyaṃ nakhadantatruṭistathā asthikṣaye liṅgametadvaidyaiḥ sarvairudāhṛtam"},{"type":"verse","number":"84","sanskrit":"शुक्राल्पत्वं पर्वभेदस्तोदः शून्यत्वमस्थिनि लिङ्गान्येतानि जायन्ते नराणां मज्जसंक्षये","text":"śukrālpatvaṃ parvabhedastodaḥ śūnyatvamasthini liṅgānyetāni jāyante narāṇāṃ majjasaṃkṣaye"},{"type":"verse","number":"85","sanskrit":"शुक्रक्षये रतेऽशक्तिर्व्यथा शेफसि मुष्कयोः चिरेण शुक्रसेकः स्यात्सेके रक्ताल्पशुक्रता","text":"śukrakṣaye rate'śaktirvyathā śephasi muṣkayoḥ cireṇa śukrasekaḥ syātseke raktālpaśukratā"},{"type":"verse","number":"86","sanskrit":"ओजः संक्षीयते कोपाच्चिन्ताशोकश्रमादिभिः रूक्षतीक्ष्णोष्णकटुकैः कर्षणैरपरैरपि","text":"ojaḥ saṃkṣīyate kopāccintāśokaśramādibhiḥ rūkṣatīkṣṇoṣṇakaṭukaiḥ karṣaṇairaparairapi"},{"type":"verse","number":"87","sanskrit":"बिभेति दुर्बलोऽभीक्ष्णं चिन्तयेद्व्यथितेन्द्रि यः अभ्युत्थायोन्मना रूक्षः क्षामः स्यादोजसः क्षये","text":"bibheti durbalo'bhīkṣṇaṃ cintayedvyathitendri yaḥ abhyutthāyonmanā rūkṣaḥ kṣāmaḥ syādojasaḥ kṣaye"},{"type":"verse","number":"88","sanskrit":"पुरीषस्य क्षये पार्श्वे हृदये च व्यथा भवेत् सशब्दस्यानिलस्योर्ध्वगमनं कुक्षिसंवृतिः","text":"purīṣasya kṣaye pārśve hṛdaye ca vyathā bhavet saśabdasyānilasyordhvagamanaṃ kukṣisaṃvṛtiḥ"},{"type":"verse","number":"89","sanskrit":"मूत्रक्षयेऽल्पमूत्रत्वं वस्तौ तोदश्च जायते स्वेदनाशस्त्वचो रौक्ष्यं चक्षुषोरपि रूक्षता","text":"mūtrakṣaye'lpamūtratvaṃ vastau todaśca jāyate svedanāśastvaco raukṣyaṃ cakṣuṣorapi rūkṣatā"},{"type":"verse","number":"90","sanskrit":"स्तब्धाश्च रोमकूपाः स्युर्लिङ्गं स्वेदक्षये भवेत् आर्त्तवस्य स्वकाले चाभावस्तस्याल्पताऽथ वा","text":"stabdhāśca romakūpāḥ syurliṅgaṃ svedakṣaye bhavet ārttavasya svakāle cābhāvastasyālpatā'tha vā"},{"type":"verse","number":"91","sanskrit":"जायते वेदना योनौ लिङ्गं स्यादार्त्तवक्षये अभावः स्वल्पता वा स्यात्स्तन्यस्य भवतस्तथा","text":"jāyate vedanā yonau liṅgaṃ syādārttavakṣaye abhāvaḥ svalpatā vā syātstanyasya bhavatastathā"},{"type":"verse","number":"92","sanskrit":"ग्लानौ पयोधरावेतल्लक्षणं स्तन्यसंक्षये अनुन्नतो भवेत्कुक्षिर्गर्भस्यास्पन्दनं तथा इति गर्भक्षये प्राज्ञैर्लक्षणं समुदाहृतम्","text":"glānau payodharāvetallakṣaṇaṃ stanyasaṃkṣaye anunnato bhavetkukṣirgarbhasyāspandanaṃ tathā iti garbhakṣaye prājñairlakṣaṇaṃ samudāhṛtam"},{"type":"verse","number":"93","sanskrit":"तत्तत्संवर्द्धनाहारविहारातिनिषेवणात् तत्तत्प्राप्य नरः शीघ्रं तत्तत्क्षयमपोहति","text":"tattatsaṃvarddhanāhāravihārātiniṣevaṇāt tattatprāpya naraḥ śīghraṃ tattatkṣayamapohati"},{"type":"verse","number":"94","sanskrit":"ओजस्तु वर्द्धते नॄणां सुस्निग्धैः स्वादुभिस्तथा वृष्यैरन्यैर्विशेषात्तु क्षीरमांसरसादिभिः","text":"ojastu varddhate nṝṇāṃ susnigdhaiḥ svādubhistathā vṛṣyairanyairviśeṣāttu kṣīramāṃsarasādibhiḥ"},{"type":"verse","number":"95","sanskrit":"दोषधातुमलक्षीणो बलक्षीणोऽपि मानवः तत्तत्संवर्द्धनं यत्तदन्नपानं प्रकाङ्क्षति","text":"doṣadhātumalakṣīṇo balakṣīṇo'pi mānavaḥ tattatsaṃvarddhanaṃ yattadannapānaṃ prakāṅkṣati"},{"type":"verse","number":"96","sanskrit":"यद्यदाहारजातन्तु क्षीणः प्रार्थयते नरः तस्य तस्य स लाभेन तत्तत्क्षयमपोहति","text":"yadyadāhārajātantu kṣīṇaḥ prārthayate naraḥ tasya tasya sa lābhena tattatkṣayamapohati"},{"type":"verse","number":"97","sanskrit":"कषायकटुतिक्तानि रूक्षशीतलघूनि च यवमुद्गप्रियङ्गूंश्च वातक्षीणोऽभिकाङ्क्षति","text":"kaṣāyakaṭutiktāni rūkṣaśītalaghūni ca yavamudgapriyaṅgūṃśca vātakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"98","sanskrit":"तिलमाषकुलत्थादिपिष्टान्नविकृतिं तथा मस्तुशुक्ताम्लतक्राणि काञ्जिकञ्चतथा दधि","text":"tilamāṣakulatthādipiṣṭānnavikṛtiṃ tathā mastuśuktāmlatakrāṇi kāñjikañcatathā dadhi"},{"type":"verse","number":"99","sanskrit":"कट्वम्ललवणोष्णानि तीक्ष्णं क्रोधं विदाहि च समयं देशमुष्णञ्च पित्तक्षीणोऽभिकाङ्क्षति","text":"kaṭvamlalavaṇoṣṇāni tīkṣṇaṃ krodhaṃ vidāhi ca samayaṃ deśamuṣṇañca pittakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"100","sanskrit":"मधुरस्निग्धशीतानि लवणाम्लगुरूणि च दधि क्षीरं दिवास्वप्नं कफक्षीणोऽभिकाङ्क्षति","text":"madhurasnigdhaśītāni lavaṇāmlagurūṇi ca dadhi kṣīraṃ divāsvapnaṃ kaphakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"101","sanskrit":"रसक्षीणो नरः काङ्क्षत्यम्भोऽतिशिशिरं मुहुः रात्रिनिद्रा ं! हिमं चन्द्रं भोक्तुञ्च मधुरं रसम्","text":"rasakṣīṇo naraḥ kāṅkṣatyambho'tiśiśiraṃ muhuḥ rātrinidrā ṃ! himaṃ candraṃ bhoktuñca madhuraṃ rasam"},{"type":"verse","number":"102","sanskrit":"इक्षुं मांसरसं मन्थं मधु सर्पिर्गुडोदकम्","text":"ikṣuṃ māṃsarasaṃ manthaṃ madhu sarpirguḍodakam"},{"type":"verse","number":"103","sanskrit":"द्रा क्षादाडिमशुक्तानि सस्नेहलवणानि च रक्तसिद्धानि मांसानि रक्तक्षीणोऽभिकाङ्क्षति","text":"drā kṣādāḍimaśuktāni sasnehalavaṇāni ca raktasiddhāni māṃsāni raktakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"104","sanskrit":"अन्नानि दधिसिद्धानि षाडवांश्च बहूनपि स्थूलक्रव्यादमांसानि मांसक्षीणोऽभिकाङ्क्षति","text":"annāni dadhisiddhāni ṣāḍavāṃśca bahūnapi sthūlakravyādamāṃsāni māṃsakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"105","sanskrit":"मेदः सिद्धानि मांसानि ग्राम्यानूपौदकानि च सक्षाराणि विशेषेण मेदःक्षीणोऽभिकाङ्क्षति","text":"medaḥ siddhāni māṃsāni grāmyānūpaudakāni ca sakṣārāṇi viśeṣeṇa medaḥkṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"106","sanskrit":"अस्थिक्षीणस्तथा मांसं मज्जास्थिस्नेहसंयुतम् स्वाद्वम्लसंयुतं द्र व्यं मज्जाक्षीणोऽभिकाङ्क्षति","text":"asthikṣīṇastathā māṃsaṃ majjāsthisnehasaṃyutam svādvamlasaṃyutaṃ dra vyaṃ majjākṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"107","sanskrit":"शिखिनः कुक्कुटस्याण्डं हंससारसयोस्तथा ग्राम्यानूपौदकानाञ्च शुक्रक्षीणोऽभिकाङ्क्षति","text":"śikhinaḥ kukkuṭasyāṇḍaṃ haṃsasārasayostathā grāmyānūpaudakānāñca śukrakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"108","sanskrit":"यवान्नं यवकान्नञ्च शाकानि विविधानि च मसूरमाषयूषञ्च मलक्षीणोऽभिकाङ्क्षति","text":"yavānnaṃ yavakānnañca śākāni vividhāni ca masūramāṣayūṣañca malakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"109","sanskrit":"पेयमिक्षुरसं क्षीरं सगुडं बदरोदकम् मूत्रक्षीणोऽभिलषति त्रपुसैर्वारुकाणि च","text":"peyamikṣurasaṃ kṣīraṃ saguḍaṃ badarodakam mūtrakṣīṇo'bhilaṣati trapusairvārukāṇi ca"},{"type":"verse","number":"110","sanskrit":"अभ्यङ्गोद्वर्त्तने मद्यं निवातशयनासने गुरु प्रावरणं चैव स्वेदक्षीणोऽभिकाङ्क्षति","text":"abhyaṅgodvarttane madyaṃ nivātaśayanāsane guru prāvaraṇaṃ caiva svedakṣīṇo'bhikāṅkṣati"},{"type":"verse","number":"111","sanskrit":"कट्वम्ललवणोष्णानि विदाहीनि गुरूणि च फलशाकानि पानानि स्त्री काङ्क्षत्यार्त्तवक्षये","text":"kaṭvamlalavaṇoṣṇāni vidāhīni gurūṇi ca phalaśākāni pānāni strī kāṅkṣatyārttavakṣaye"},{"type":"verse","number":"112","sanskrit":"सुराशाल्यन्नमांसानि गोक्षीरं शर्करां तथा आसवं दधि हृद्यानि स्तन्यक्षीणाऽभिवाञ्छति","text":"surāśālyannamāṃsāni gokṣīraṃ śarkarāṃ tathā āsavaṃ dadhi hṛdyāni stanyakṣīṇā'bhivāñchati"},{"type":"verse","number":"113","sanskrit":"मृगाजाविवराहाणां गर्भान्वाञ्छति संस्कृतान् वसाशूल्यप्रकारादीन्भोक्तुं गर्भपरिक्षये","text":"mṛgājāvivarāhāṇāṃ garbhānvāñchati saṃskṛtān vasāśūlyaprakārādīnbhoktuṃ garbhaparikṣaye"},{"type":"verse","number":"114","sanskrit":"रसादिशुक्रपर्य्यन्तं धातुपुष्टिनिमित्तकम् चेष्टासु पाटवं यत्तु बलं तदभिधीयते","text":"rasādiśukraparyyantaṃ dhātupuṣṭinimittakam ceṣṭāsu pāṭavaṃ yattu balaṃ tadabhidhīyate"},{"type":"verse","number":"115","sanskrit":"अभिघाताद्भयात्क्रोधाच्चिन्तया च परिश्रमात् धातूनां संक्षयाच्छोकाद्बलं संक्षीयते नृणाम्","text":"abhighātādbhayātkrodhāccintayā ca pariśramāt dhātūnāṃ saṃkṣayācchokādbalaṃ saṃkṣīyate nṛṇām"},{"type":"verse","number":"116","sanskrit":"गौरवं स्तब्धता गात्रे मुखम्लानिर्विवर्णता तन्द्रा निद्रा वातशोथो बलव्यापत्तिलक्षणम्","text":"gauravaṃ stabdhatā gātre mukhamlānirvivarṇatā tandrā nidrā vātaśotho balavyāpattilakṣaṇam"},{"type":"verse","number":"117","sanskrit":"दोषसाम्यकरं यत्तु बह्निसाम्यकरं च यत् धातुपुष्टिकरं द्र व्यं बलं तदभिवर्द्धयेत्","text":"doṣasāmyakaraṃ yattu bahnisāmyakaraṃ ca yat dhātupuṣṭikaraṃ dra vyaṃ balaṃ tadabhivarddhayet"},{"type":"verse","number":"118","sanskrit":"कृशोऽपि बलवान्कश्चित् स्थूलोऽत्यल्पबलो यतः तस्माच्चेष्टापटुत्वेन बलवन्तं विदुर्बुधाः","text":"kṛśo'pi balavānkaścit sthūlo'tyalpabalo yataḥ tasmācceṣṭāpaṭutvena balavantaṃ vidurbudhāḥ"},{"type":"verse","number":"119","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमन्मिश्रभाव विरचिते श्रीभावप्रकाशे पूर्वखण्डे परिभाषादिप्रकरणे सप्तमं रोगिपरीक्षाप्रकरणं समाप्तम् ७ इति पूर्व खण्डं समाप्तम् भावप्रकाशपूर्वखण्डं","text":"iti śrīmiśralaṭakana tanaya śrīmanmiśrabhāva viracite śrībhāvaprakāśe pūrvakhaṇḍe paribhāṣādiprakaraṇe saptamaṃ rogiparīkṣāprakaraṇaṃ samāptam 7 iti pūrva khaṇḍaṃ samāptam bhāvaprakāśapūrvakhaṇḍaṃ"}]},{"sthana":"Мадхьямакханда","number":1,"lang":"sa","content":[{"type":"heading","heading":"harītakyādi-варга — группа харитаки"},{"type":"verse","number":"1","sanskrit":"दक्षं प्रजापतिं स्वस्थमश्विनौ वाक्यमूचतुः कुतो हरीतकी जाता तस्यास्तु कति जातयः","text":"dakṣaṃ prajāpatiṃ svasthamaśvinau vākyamūcatuḥ kuto harītakī jātā tasyāstu kati jātayaḥ"},{"type":"verse","number":"2","sanskrit":"रसाः कति समाख्याताः कति चोपरसाः स्मृताः नामानि कति चोक्तानि किं वा तासां च लक्षणम्","text":"rasāḥ kati samākhyātāḥ kati coparasāḥ smṛtāḥ nāmāni kati coktāni kiṃ vā tāsāṃ ca lakṣaṇam"},{"type":"verse","number":"3","sanskrit":"के च वर्णा गुणाः के च का च कुत्र प्रयुज्यते केन द्रव्येण संयुक्ता कांश्च रोगान्व्यपोहति","text":"ke ca varṇā guṇāḥ ke ca kā ca kutra prayujyate kena dravyeṇa saṃyuktā kāṃśca rogānvyapohati"},{"type":"verse","number":"4","sanskrit":"प्रश्नमेतद्यथा पृष्टं भगवन्वक्तुमर्हसि अश्विनोर्वचनं श्रुत्वा दक्षो वचनमब्रवीत्","text":"praśnametadyathā pṛṣṭaṃ bhagavanvaktumarhasi aśvinorvacanaṃ śrutvā dakṣo vacanamabravīt"},{"type":"verse","number":"5","sanskrit":"पपात बिन्दुर्मेदिन्यां शक्रस्य पिबतोऽमृतम् ततो दिव्यात्समुत्पन्ना सप्तजातिर्हरीतकी","text":"papāta bindurmedinyāṃ śakrasya pibato'mṛtam tato divyātsamutpannā saptajātirharītakī"},{"type":"verse","number":"6","sanskrit":"हरीतक्यभया पथ्या कायस्था पूतनाऽमृता हैमवत्यव्यथा चापि चेतकी श्रेयसी शिवा","text":"harītakyabhayā pathyā kāyasthā pūtanā'mṛtā haimavatyavyathā cāpi cetakī śreyasī śivā"},{"type":"verse","number":"7","sanskrit":"वयस्था विजया चापि जीवन्ती रोहिणीति च","text":"vayasthā vijayā cāpi jīvantī rohiṇīti ca"},{"type":"verse","number":"8","sanskrit":"विजया रोहिणी चैव पूतना चामृताऽभया जीवन्ती चेतकी चेति पथ्यायाः सप्तजातयः","text":"vijayā rohiṇī caiva pūtanā cāmṛtā'bhayā jīvantī cetakī ceti pathyāyāḥ saptajātayaḥ"},{"type":"verse","number":"9","sanskrit":"अलाबुवृत्ता विजया वृत्ता सा रोहिणी स्मृता पूतनाऽस्थिमती सूक्ष्मा कथिता मांसलाऽमृताः","text":"alābuvṛttā vijayā vṛttā sā rohiṇī smṛtā pūtanā'sthimatī sūkṣmā kathitā māṃsalā'mṛtāḥ"},{"type":"verse","number":"10","sanskrit":"पञ्चरेखाऽभया प्रोक्ता जीवन्ती स्वर्णवर्णिनी त्रिरेखा चेतकी ज्ञेया सप्तानामियमाकृतिः २.","text":"pañcarekhā'bhayā proktā jīvantī svarṇavarṇinī trirekhā cetakī jñeyā saptānāmiyamākṛtiḥ 2."},{"type":"verse","number":"11","sanskrit":"विजया सर्वरोगेषु रोहिणी व्रणरोहिणी प्रलेपे पूतना योज्या शोधनार्थेऽमृता हिता","text":"vijayā sarvarogeṣu rohiṇī vraṇarohiṇī pralepe pūtanā yojyā śodhanārthe'mṛtā hitā"},{"type":"verse","number":"12","sanskrit":"अक्षिरोगेऽभयाशस्ता जीवन्ती सर्वरोगृहृत् चूर्णार्थे चेतकी शस्ता यथायुक्तं प्रयोजयेत्","text":"akṣiroge'bhayāśastā jīvantī sarvarogṛhṛt cūrṇārthe cetakī śastā yathāyuktaṃ prayojayet"},{"type":"verse","number":"13","sanskrit":"चेतकी द्विविधा प्रोक्ता श्वेता कृष्णा च वर्णतः षडङ्गुलायता शुक्ला कृष्णा त्वेकाङ्गुला स्मृता","text":"cetakī dvividhā proktā śvetā kṛṣṇā ca varṇataḥ ṣaḍaṅgulāyatā śuklā kṛṣṇā tvekāṅgulā smṛtā"},{"type":"verse","number":"14","sanskrit":"काचिदास्वादमात्रेण काचिद्गन्धेन भेदयेत् काचित्स्पर्शेन दृष्ट्याऽन्या चतुर्द्धा भेदयेच्छिवा","text":"kācidāsvādamātreṇa kācidgandhena bhedayet kācitsparśena dṛṣṭyā'nyā caturddhā bhedayecchivā"},{"type":"verse","number":"15","sanskrit":"चेतकीपादपच्छायामुपसर्पन्ति ये नराः भिद्यन्ते तत्क्षणादेव पशुपक्षिमृगादयः","text":"cetakīpādapacchāyāmupasarpanti ye narāḥ bhidyante tatkṣaṇādeva paśupakṣimṛgādayaḥ"},{"type":"verse","number":"16","sanskrit":"चेतकी तु घृता हस्ते यावत्तिष्ठति देहिनः तावद्भिद्येत वेगैस्तु प्रभावान्नात्र संशयः","text":"cetakī tu ghṛtā haste yāvattiṣṭhati dehinaḥ tāvadbhidyeta vegaistu prabhāvānnātra saṃśayaḥ"},{"type":"verse","number":"17","sanskrit":"नृपाणां सुकुमाराणां कृशानां भेषजद्विषाम् चेतकी परमा शस्ता हिता सुखविरेचनी","text":"nṛpāṇāṃ sukumārāṇāṃ kṛśānāṃ bheṣajadviṣām cetakī paramā śastā hitā sukhavirecanī"},{"type":"verse","number":"18","sanskrit":"सप्तानामपि जातीनां प्रधाना विजया स्मृता सुखप्रयोगा सुलभा सर्वरोगेषु शस्यते","text":"saptānāmapi jātīnāṃ pradhānā vijayā smṛtā sukhaprayogā sulabhā sarvarogeṣu śasyate"},{"type":"verse","number":"19","sanskrit":"हरीतकी पञ्चरसाऽलवणातुवरा परम् रूक्षोष्णा दीपनी मेध्या स्वादुपाका रसायनी","text":"harītakī pañcarasā'lavaṇātuvarā param rūkṣoṣṇā dīpanī medhyā svādupākā rasāyanī"},{"type":"verse","number":"20","sanskrit":"चक्षुष्या लघुरायुष्या बृंहणी चानुलोमिनी श्वासकासप्रमेहार्शः कुष्ठशोथोदरकृमीन् २.","text":"cakṣuṣyā laghurāyuṣyā bṛṃhaṇī cānulominī śvāsakāsapramehārśaḥ kuṣṭhaśothodarakṛmīn 2."},{"type":"verse","number":"21","sanskrit":"गुल्माध्मानतृषाछर्दिहिक्काकण्डूहृदामयान्","text":"gulmādhmānatṛṣāchardihikkākaṇḍūhṛdāmayān"},{"type":"verse","number":"22","sanskrit":"कामलां शूलमानाहं प्लीहानञ्च यकृत्तथा अश्मरीं मूत्रकृच्छ्रञ्च मूत्राघातञ्च नाशयेत्","text":"kāmalāṃ śūlamānāhaṃ plīhānañca yakṛttathā aśmarīṃ mūtrakṛcchrañca mūtrāghātañca nāśayet"},{"type":"verse","number":"23","sanskrit":"स्वादुतिक्तकषायत्वात्पित्तहृत्कफहृत्तु सा कटुतिक्तकषायत्वादम्लत्वाद्वातहृच्छिवा","text":"svādutiktakaṣāyatvātpittahṛtkaphahṛttu sā kaṭutiktakaṣāyatvādamlatvādvātahṛcchivā"},{"type":"verse","number":"24","sanskrit":"पित्तकृत्कटुकाम्लत्वाद्वातकृन्न कथं शिवा","text":"pittakṛtkaṭukāmlatvādvātakṛnna kathaṃ śivā"},{"type":"verse","number":"25","sanskrit":"प्रभावाद्दोषहन्तृत्वं सिद्धं यत्तत्प्रकाश्यते हेतुभिः शिष्यबोधार्थं नापूर्वं क्रियतेऽधुना","text":"prabhāvāddoṣahantṛtvaṃ siddhaṃ yattatprakāśyate hetubhiḥ śiṣyabodhārthaṃ nāpūrvaṃ kriyate'dhunā"},{"type":"verse","number":"26","sanskrit":"कर्मान्यत्वं गुणैः साम्यं दृष्टमाश्रयभेदतः यतस्ततो नेति चिन्त्यं धात्रीलकुचयोर्यथा","text":"karmānyatvaṃ guṇaiḥ sāmyaṃ dṛṣṭamāśrayabhedataḥ yatastato neti cintyaṃ dhātrīlakucayoryathā"},{"type":"verse","number":"27","sanskrit":"पथ्याया मज्जनि स्वादुः स्नाय्वामम्लो व्यवस्थितः वृन्ते तिक्तस्त्वचि कटुरस्थिस्थस्तुवरो रसः","text":"pathyāyā majjani svāduḥ snāyvāmamlo vyavasthitaḥ vṛnte tiktastvaci kaṭurasthisthastuvaro rasaḥ"},{"type":"verse","number":"28","sanskrit":"नवा स्निग्धा घना वृत्ता गुर्वी क्षिप्ता च याऽम्भसि निमज्जेत्सा प्रशस्ता च कथिताऽतिगुणप्रदा","text":"navā snigdhā ghanā vṛttā gurvī kṣiptā ca yā'mbhasi nimajjetsā praśastā ca kathitā'tiguṇapradā"},{"type":"verse","number":"29","sanskrit":"नवादिगुणयुक्तत्वं तथैवात्र द्विकर्षता हरीतक्याः फले यत्र द्वयं तच्छ्रेष्ठमुच्यते","text":"navādiguṇayuktatvaṃ tathaivātra dvikarṣatā harītakyāḥ phale yatra dvayaṃ tacchreṣṭhamucyate"},{"type":"verse","number":"30","sanskrit":"चर्विता वर्द्धयत्यग्निं पेषिता मलशोधिनी स्विन्ना संग्राहिणी पथ्या भृष्टा प्रोक्ता त्रिदोषनुत् २.","text":"carvitā varddhayatyagniṃ peṣitā malaśodhinī svinnā saṃgrāhiṇī pathyā bhṛṣṭā proktā tridoṣanut 2."},{"type":"verse","number":"31","sanskrit":"उन्मीलिनी बुद्धिबलेन्द्रि याणां निर्मूलिनी पित्तकफानिलानाम् विस्रंसिनी मूत्रशकृन्मलानां हरीतकी स्यात् सह भोजनेन","text":"unmīlinī buddhibalendri yāṇāṃ nirmūlinī pittakaphānilānām visraṃsinī mūtraśakṛnmalānāṃ harītakī syāt saha bhojanena"},{"type":"verse","number":"32","sanskrit":"हरीतकी हरत्याशु भुक्तस्योपरि योजिता","text":"harītakī haratyāśu bhuktasyopari yojitā"},{"type":"verse","number":"33","sanskrit":"लवणेन कफं हन्ति पित्तं हन्ति सशर्करा घृतेन वातजान् रोगान्सर्वरोगान्गुडान्विता","text":"lavaṇena kaphaṃ hanti pittaṃ hanti saśarkarā ghṛtena vātajān rogānsarvarogānguḍānvitā"},{"type":"verse","number":"34","sanskrit":"सिंधूत्थशर्कराशुण्ठीकणामधुगुडैः क्रमात् वर्षादिष्वभया प्राश्या रसायनगुणैषिणा","text":"siṃdhūtthaśarkarāśuṇṭhīkaṇāmadhuguḍaiḥ kramāt varṣādiṣvabhayā prāśyā rasāyanaguṇaiṣiṇā"},{"type":"verse","number":"35","sanskrit":"अध्वातिखिन्नो बलवर्जितश्च रूक्षः कृशो लङ्घनकर्शितश्च पित्ताधिको गर्भवती च नारी विमुक्तरक्तस्त्वभयां न खादेत्","text":"adhvātikhinno balavarjitaśca rūkṣaḥ kṛśo laṅghanakarśitaśca pittādhiko garbhavatī ca nārī vimuktaraktastvabhayāṃ na khādet"},{"type":"verse","number":"36","sanskrit":"विभीतकस्त्रिलिङ्गं स्यादक्षः कर्षफलस्तु सः कलिद्रुमो भूतवासस्तथा कलियुगालयः विभीतकं स्वादुपाकं कषायं कफपित्तनुत् उष्णवीर्यं हिमस्पर्शं भेदनं कासनाशनम्","text":"vibhītakastriliṅgaṃ syādakṣaḥ karṣaphalastu saḥ kalidrumo bhūtavāsastathā kaliyugālayaḥ vibhītakaṃ svādupākaṃ kaṣāyaṃ kaphapittanut uṣṇavīryaṃ himasparśaṃ bhedanaṃ kāsanāśanam"},{"type":"verse","number":"37","sanskrit":"रूक्षं नेत्रहितं केश्यं कृमिवैस्वर्यनाशनम् विभीतमज्जातृट्छर्दिकफवातहरी लघुः कषायो मदकृच्चाथ धात्रीमज्जाऽपि तद्गुणः","text":"rūkṣaṃ netrahitaṃ keśyaṃ kṛmivaisvaryanāśanam vibhītamajjātṛṭchardikaphavātaharī laghuḥ kaṣāyo madakṛccātha dhātrīmajjā'pi tadguṇaḥ"},{"type":"verse","number":"38","sanskrit":"वयस्यामलकी वृष्या जातीफलरसं शिवम् धात्रीफलं श्रीफलं च तथामृतफलं स्मृतम् त्रिष्वामलकमाख्यातं धात्री तिष्यफलाऽमृता","text":"vayasyāmalakī vṛṣyā jātīphalarasaṃ śivam dhātrīphalaṃ śrīphalaṃ ca tathāmṛtaphalaṃ smṛtam triṣvāmalakamākhyātaṃ dhātrī tiṣyaphalā'mṛtā"},{"type":"verse","number":"39","sanskrit":"हरीतकीसमं धात्रीफलं किन्तु विशेषतः रक्तपित्तप्रमेहघ्नं परं वृष्यं रसायनम्","text":"harītakīsamaṃ dhātrīphalaṃ kintu viśeṣataḥ raktapittapramehaghnaṃ paraṃ vṛṣyaṃ rasāyanam"},{"type":"verse","number":"40","sanskrit":"हन्ति वातं तदम्लत्वात्पित्तं माधुर्यशैत्यतः कफं रूक्षकषायत्वात्फलं धात्र्! यास्त्रिदोषजित् २.","text":"hanti vātaṃ tadamlatvātpittaṃ mādhuryaśaityataḥ kaphaṃ rūkṣakaṣāyatvātphalaṃ dhātr! yāstridoṣajit 2."},{"type":"verse","number":"41","sanskrit":"यस्य यस्य फलस्येह वीर्यं भवति यादृशम् तस्य तस्यैव वीर्य्येण मज्जानमपि निर्दिशेत्","text":"yasya yasya phalasyeha vīryaṃ bhavati yādṛśam tasya tasyaiva vīryyeṇa majjānamapi nirdiśet"},{"type":"verse","number":"42","sanskrit":"पथ्याविभीतधात्रीणां फलैः स्यात्त्रिफला समैः फलत्रिकञ्च त्रिफला सा वरा च प्रकीर्तिता","text":"pathyāvibhītadhātrīṇāṃ phalaiḥ syāttriphalā samaiḥ phalatrikañca triphalā sā varā ca prakīrtitā"},{"type":"verse","number":"43","sanskrit":"त्रिफला कफपित्तघ्नी मेहकुष्ठहरा सरा चक्षुष्या दीपनी रुच्या विषमज्वरनाशिनी","text":"triphalā kaphapittaghnī mehakuṣṭhaharā sarā cakṣuṣyā dīpanī rucyā viṣamajvaranāśinī"},{"type":"verse","number":"44","sanskrit":"शुण्ठी विश्वा च विश्वञ्च नागरं विश्वभेषजम् ऊषणं कटुभद्र ञ्च शृङ्गवेरं मह्षधम्","text":"śuṇṭhī viśvā ca viśvañca nāgaraṃ viśvabheṣajam ūṣaṇaṃ kaṭubhadra ñca śṛṅgaveraṃ mahṣadham"},{"type":"verse","number":"45","sanskrit":"शुण्ठी रुच्यामवातघ्नी पाचनी कटुका लघुः स्निग्धोष्णा मधुरा पाके कफवातविबन्धनुत्","text":"śuṇṭhī rucyāmavātaghnī pācanī kaṭukā laghuḥ snigdhoṣṇā madhurā pāke kaphavātavibandhanut"},{"type":"verse","number":"46","sanskrit":"वृष्या स्वर्य्यावमिश्वासशूलकासहृदामयान् हन्ति श्लीपदशोथार्श आनाहोदरमारुतान्","text":"vṛṣyā svaryyāvamiśvāsaśūlakāsahṛdāmayān hanti ślīpadaśothārśa ānāhodaramārutān"},{"type":"verse","number":"47","sanskrit":"आग्नेयगुणभूयिष्ठात् तोयांशपरिशोषि यत् संगृह्णाति मलं तत्तु ग्राहि शुण्ठ्यादयो यथा","text":"āgneyaguṇabhūyiṣṭhāt toyāṃśapariśoṣi yat saṃgṛhṇāti malaṃ tattu grāhi śuṇṭhyādayo yathā"},{"type":"verse","number":"48","sanskrit":"विबन्धभेदिनी या तु सा कथं ग्राहिणी भवेत् शक्तिर्विबन्धभेदे स्याद्यतो न मलपातनो","text":"vibandhabhedinī yā tu sā kathaṃ grāhiṇī bhavet śaktirvibandhabhede syādyato na malapātano"},{"type":"verse","number":"49","sanskrit":"आर्द्र कं शृङ्गवेरं स्यात्कटुभद्रं तथाऽद्रि का आर्द्रि का भेदिनी गुर्वीतीक्ष्णोष्णा दीपनी मता","text":"ārdra kaṃ śṛṅgaveraṃ syātkaṭubhadraṃ tathā'dri kā ārdri kā bhedinī gurvītīkṣṇoṣṇā dīpanī matā"},{"type":"verse","number":"50","sanskrit":"कटुका मधुरा पाके रूक्षा वातकफापहा ये गुणाः कथिता शुण्ठ्यास्तेऽपि सन्त्यार्द्र केऽखिलाः २.","text":"kaṭukā madhurā pāke rūkṣā vātakaphāpahā ye guṇāḥ kathitā śuṇṭhyāste'pi santyārdra ke'khilāḥ 2."},{"type":"verse","number":"51","sanskrit":"भोजनाग्रे सदा पथ्यं लवणार्द्र कभक्षणम् अग्निसन्दीपनं रुच्यं जिह्वाकण्ठविशोधनम्","text":"bhojanāgre sadā pathyaṃ lavaṇārdra kabhakṣaṇam agnisandīpanaṃ rucyaṃ jihvākaṇṭhaviśodhanam"},{"type":"verse","number":"52","sanskrit":"कुष्ठपाण्ड्वामये कृच्छ्रे रक्तपित्ते व्रणे ज्वरे दाहे निदाघशरदोर्नैव पूजितमार्द्र कम्","text":"kuṣṭhapāṇḍvāmaye kṛcchre raktapitte vraṇe jvare dāhe nidāghaśaradornaiva pūjitamārdra kam"},{"type":"verse","number":"53","sanskrit":"पिप्पली मागधी कृष्णा वैदेही चपला कणा उपकुल्योषणा शौण्डी कोला स्यात्तीक्ष्णतण्डुला","text":"pippalī māgadhī kṛṣṇā vaidehī capalā kaṇā upakulyoṣaṇā śauṇḍī kolā syāttīkṣṇataṇḍulā"},{"type":"verse","number":"54","sanskrit":"पिप्पली दीपना वृष्या स्वादुपाका रसायनी अनुष्णा कटुका स्निग्धा वातश्लेष्महरी लघुः","text":"pippalī dīpanā vṛṣyā svādupākā rasāyanī anuṣṇā kaṭukā snigdhā vātaśleṣmaharī laghuḥ"},{"type":"verse","number":"55","sanskrit":"पिप्पली रेचनी हन्ति श्वासकासोदरज्वरान् कुष्ठप्रमेहगुल्मार्शः प्लीहशूलाममारुतान्","text":"pippalī recanī hanti śvāsakāsodarajvarān kuṣṭhapramehagulmārśaḥ plīhaśūlāmamārutān"},{"type":"verse","number":"56","sanskrit":"आद्रा र्! कफप्रदा स्निग्धा शीतला मधुरा गुरुः पित्तप्रशमनी सा तु शुष्का पित्तप्रकोपिणी","text":"ādrā r! kaphapradā snigdhā śītalā madhurā guruḥ pittapraśamanī sā tu śuṣkā pittaprakopiṇī"},{"type":"verse","number":"57","sanskrit":"पिप्पली मधुसंयुक्ता मेदः कफविनाशिनी श्वासकासज्वरहरी वृष्या मेध्याऽग्निवर्द्धिनी","text":"pippalī madhusaṃyuktā medaḥ kaphavināśinī śvāsakāsajvaraharī vṛṣyā medhyā'gnivarddhinī"},{"type":"verse","number":"58","sanskrit":"जीर्णज्वरेऽग्निमान्द्ये च शस्यते गुडपिप्पली कासाजीर्णारुचिश्वासहृत्पाण्डुकृमिरोगनुत् द्विगुणः पिप्पलीचूर्णाद् गुडोऽत्र भिषजां मतः","text":"jīrṇajvare'gnimāndye ca śasyate guḍapippalī kāsājīrṇāruciśvāsahṛtpāṇḍukṛmiroganut dviguṇaḥ pippalīcūrṇād guḍo'tra bhiṣajāṃ mataḥ"},{"type":"verse","number":"59","sanskrit":"मरिचं वेल्लजं कृष्णमूषणं धर्मपत्तनम्","text":"maricaṃ vellajaṃ kṛṣṇamūṣaṇaṃ dharmapattanam"},{"type":"verse","number":"60","sanskrit":"मरिचं कटुकं तीक्ष्णं दीपनं कफवातजित् उष्णं पित्तकरं रूक्षं श्वासशूलकृमीन्हरेत् २.","text":"maricaṃ kaṭukaṃ tīkṣṇaṃ dīpanaṃ kaphavātajit uṣṇaṃ pittakaraṃ rūkṣaṃ śvāsaśūlakṛmīnharet 2."},{"type":"verse","number":"61","sanskrit":"तदाद्र रं! मधुरं पाके नात्युष्णं कटुकं गुरु किञ्चित्तीक्ष्णगुणं श्लेष्मप्रसेकि स्यादपित्तलम्","text":"tadādra raṃ! madhuraṃ pāke nātyuṣṇaṃ kaṭukaṃ guru kiñcittīkṣṇaguṇaṃ śleṣmapraseki syādapittalam"},{"type":"verse","number":"62","sanskrit":"विश्वोपकुल्या मरिचं त्रयं त्रिकटु कथ्यते कटुत्रिकं तु त्रिकटु त्र्! यूषणं व्योष उच्यते","text":"viśvopakulyā maricaṃ trayaṃ trikaṭu kathyate kaṭutrikaṃ tu trikaṭu tr! yūṣaṇaṃ vyoṣa ucyate"},{"type":"verse","number":"63","sanskrit":"त्र्! यूषणं दीपनं हन्ति श्वासकासत्वगामयान् गुल्ममेहकफस्थौल्यमेदःश्लीपदपीनसान्","text":"tr! yūṣaṇaṃ dīpanaṃ hanti śvāsakāsatvagāmayān gulmamehakaphasthaulyamedaḥślīpadapīnasān"},{"type":"verse","number":"64","sanskrit":"ग्रन्थिकं पिप्पलीमूलमूषणं चटकाशिरः दीपनं पिप्पलीमूलं कटूष्णं पाचनं लघु","text":"granthikaṃ pippalīmūlamūṣaṇaṃ caṭakāśiraḥ dīpanaṃ pippalīmūlaṃ kaṭūṣṇaṃ pācanaṃ laghu"},{"type":"verse","number":"65","sanskrit":"रूक्षं पित्तकरं भेदि कफवातोदरापहम् आनाहप्लीहगुल्मघ्नं कृमिश्वासक्षयापहम्","text":"rūkṣaṃ pittakaraṃ bhedi kaphavātodarāpaham ānāhaplīhagulmaghnaṃ kṛmiśvāsakṣayāpaham"},{"type":"verse","number":"66","sanskrit":"त्र्! यूषणं सकणामूलं कथितं चतुरूषणम् व्योषस्येव गुणाः प्रोक्ता अधिकाश्चतुरूषणे","text":"tr! yūṣaṇaṃ sakaṇāmūlaṃ kathitaṃ caturūṣaṇam vyoṣasyeva guṇāḥ proktā adhikāścaturūṣaṇe"},{"type":"verse","number":"67","sanskrit":"भवेच्चव्यं तु चविका कथिता सा तथोषणा कणामूलगुणं चव्यं विशेषाद्गुदजापहम्","text":"bhaveccavyaṃ tu cavikā kathitā sā tathoṣaṇā kaṇāmūlaguṇaṃ cavyaṃ viśeṣādgudajāpaham"},{"type":"verse","number":"68","sanskrit":"चविकायाः फलं प्राज्ञैः कथिता गजपिप्पली कपिवल्ली कोलवल्ली श्रेयसीवशिरश्च सा","text":"cavikāyāḥ phalaṃ prājñaiḥ kathitā gajapippalī kapivallī kolavallī śreyasīvaśiraśca sā"},{"type":"verse","number":"69","sanskrit":"गजकृष्णा कटुर्वातश्लेप्महृद्वह्निवर्धिनी उष्णा निहन्त्यतीसारं श्वासकण्ठामयकृमीन्","text":"gajakṛṣṇā kaṭurvātaślepmahṛdvahnivardhinī uṣṇā nihantyatīsāraṃ śvāsakaṇṭhāmayakṛmīn"},{"type":"verse","number":"70","sanskrit":"चित्रकोऽनलनामाच पाठी व्यालस्तथोषणः चित्रकः कटुकः पाके वह्निकृत्पाचनो लघुः २.","text":"citrako'nalanāmāca pāṭhī vyālastathoṣaṇaḥ citrakaḥ kaṭukaḥ pāke vahnikṛtpācano laghuḥ 2."},{"type":"verse","number":"71","sanskrit":"रूक्षोष्णो ग्रहणीकुष्ठशोथार्शः कृमिकासनुत् वातश्लेष्महरो ग्राही वातघ्नः श्लेष्मपित्तहृत्","text":"rūkṣoṣṇo grahaṇīkuṣṭhaśothārśaḥ kṛmikāsanut vātaśleṣmaharo grāhī vātaghnaḥ śleṣmapittahṛt"},{"type":"verse","number":"72","sanskrit":"पिप्पली पिप्पलीमूलं चव्यचित्रकनागरैः पञ्चभिः कोलमात्रं यत्पञ्चकोलं तदुच्यते","text":"pippalī pippalīmūlaṃ cavyacitrakanāgaraiḥ pañcabhiḥ kolamātraṃ yatpañcakolaṃ taducyate"},{"type":"verse","number":"73","sanskrit":"पञ्चकोलं रसे पाके कटुकं रुचिकृन्मतम् तीक्ष्णोष्णं पाचनं श्रेष्ठं दीपनं कफवातनुत् गुल्मप्लीहोदरानाहशूलघ्नं पित्तकोपनम्","text":"pañcakolaṃ rase pāke kaṭukaṃ rucikṛnmatam tīkṣṇoṣṇaṃ pācanaṃ śreṣṭhaṃ dīpanaṃ kaphavātanut gulmaplīhodarānāhaśūlaghnaṃ pittakopanam"},{"type":"verse","number":"74","sanskrit":"पञ्चकोलं समरिचं षडूषणमुदाहृतम् पञ्चकोलगुणं तत्तु रूक्षमुष्णं विषापहम्","text":"pañcakolaṃ samaricaṃ ṣaḍūṣaṇamudāhṛtam pañcakolaguṇaṃ tattu rūkṣamuṣṇaṃ viṣāpaham"},{"type":"verse","number":"75","sanskrit":"यवानिकोग्रगन्धा च ब्रह्मदर्भाऽजमोदिका","text":"yavānikogragandhā ca brahmadarbhā'jamodikā"},{"type":"verse","number":"76","sanskrit":"सैवोक्ता दीप्यका दीप्या तथा स्याद्यवसाह्वया यवानी पाचनी रुच्या तीक्ष्णोष्णा कटुका लघुः","text":"saivoktā dīpyakā dīpyā tathā syādyavasāhvayā yavānī pācanī rucyā tīkṣṇoṣṇā kaṭukā laghuḥ"},{"type":"verse","number":"77","sanskrit":"दीपनी च तथा तिक्ता पित्तला शुक्रशूलहृत् वातश्लेष्मोदरानाहगुल्मप्लीहकृमिप्रणुत्","text":"dīpanī ca tathā tiktā pittalā śukraśūlahṛt vātaśleṣmodarānāhagulmaplīhakṛmipraṇut"},{"type":"verse","number":"78","sanskrit":"अजमोदा खराश्वा च मायूरो दीप्यकस्तथा तथा ब्रह्मकुशा प्रोक्ता कारवी लोचमस्तका","text":"ajamodā kharāśvā ca māyūro dīpyakastathā tathā brahmakuśā proktā kāravī locamastakā"},{"type":"verse","number":"79","sanskrit":"अजमोदा कटुस्तीक्ष्णा दीपनी कफवातनुत् उष्णा विदाहिनी हृद्या वृष्या बलकरी लघुः नेत्रामय कृमिच्छर्दिहिक्कावस्तिरुजो हरेत्","text":"ajamodā kaṭustīkṣṇā dīpanī kaphavātanut uṣṇā vidāhinī hṛdyā vṛṣyā balakarī laghuḥ netrāmaya kṛmicchardihikkāvastirujo haret"},{"type":"verse","number":"80","sanskrit":"पारसीकयवानी तु यवानीसदृशी गुणैः विशेषात्पाचनी रुच्या ग्राहिणी मादिनी गुरुः २.","text":"pārasīkayavānī tu yavānīsadṛśī guṇaiḥ viśeṣātpācanī rucyā grāhiṇī mādinī guruḥ 2."},{"type":"verse","number":"81","sanskrit":"जीरको जरणोऽजाजी कणा स्याद्दीर्घजीरकः","text":"jīrako jaraṇo'jājī kaṇā syāddīrghajīrakaḥ"},{"type":"verse","number":"82","sanskrit":"कृष्णजीरः सुगन्धश्च तथैवोद्गारशोधनः कालाजाजी तु सुषवी कालिका चोपकालिका","text":"kṛṣṇajīraḥ sugandhaśca tathaivodgāraśodhanaḥ kālājājī tu suṣavī kālikā copakālikā"},{"type":"verse","number":"83","sanskrit":"पृथ्वीका कारवी पृथ्वी पृथुकृष्णोपकुञ्चिका उपकुञ्ची च कुञ्ची च बृहज्जीरक इत्यपि","text":"pṛthvīkā kāravī pṛthvī pṛthukṛṣṇopakuñcikā upakuñcī ca kuñcī ca bṛhajjīraka ityapi"},{"type":"verse","number":"84","sanskrit":"जीरकत्रितयं रूक्षं कटूष्णं दीपनं लघु संग्राही पित्तलं मेध्यं गर्भाशयविशुद्धिकृत्","text":"jīrakatritayaṃ rūkṣaṃ kaṭūṣṇaṃ dīpanaṃ laghu saṃgrāhī pittalaṃ medhyaṃ garbhāśayaviśuddhikṛt"},{"type":"verse","number":"85","sanskrit":"ज्वरघ्नं पाचनं वृष्यं बल्यं रुच्यं कफापहम् चक्षुष्यं पवनाघ्मानगुल्मच्छर्द्यतिसार हृत्","text":"jvaraghnaṃ pācanaṃ vṛṣyaṃ balyaṃ rucyaṃ kaphāpaham cakṣuṣyaṃ pavanāghmānagulmacchardyatisāra hṛt"},{"type":"verse","number":"86","sanskrit":"धान्यकं धानकं धान्यं धाना धानेयकं तथा कुनटी धेनुका छत्रा कुस्तुम्बुरु वितुन्नकम्","text":"dhānyakaṃ dhānakaṃ dhānyaṃ dhānā dhāneyakaṃ tathā kunaṭī dhenukā chatrā kustumburu vitunnakam"},{"type":"verse","number":"87","sanskrit":"धान्यकं तुवरं स्निग्धमवृष्यं मूत्रलं लघु तिक्तं कटूष्णवीर्यञ्च दीपनं पाचनं स्मृतम्","text":"dhānyakaṃ tuvaraṃ snigdhamavṛṣyaṃ mūtralaṃ laghu tiktaṃ kaṭūṣṇavīryañca dīpanaṃ pācanaṃ smṛtam"},{"type":"verse","number":"88","sanskrit":"ज्वरघ्नं रोचकं ग्राहि स्वादुपाकि त्रिदोषनुत् तृष्णादाहवमिश्वासकासकार्श्यकृमिप्रणुत् आर्द्र न्तु तद्गुणं स्वादु विशेषात्पित्तनाशनम्","text":"jvaraghnaṃ rocakaṃ grāhi svādupāki tridoṣanut tṛṣṇādāhavamiśvāsakāsakārśyakṛmipraṇut ārdra ntu tadguṇaṃ svādu viśeṣātpittanāśanam"},{"type":"verse","number":"89","sanskrit":"शतपुष्पा शताह्वा च मधुरा कारवी मिसिः अतिलम्बी सितच्छत्रा संहितच्छत्रिकाऽपि च","text":"śatapuṣpā śatāhvā ca madhurā kāravī misiḥ atilambī sitacchatrā saṃhitacchatrikā'pi ca"},{"type":"verse","number":"90","sanskrit":"छत्रा शालेयशालीनो मिश्रेया मधुरा मिसिः शतपुष्पा लघुस्तीक्ष्णा पित्तकृद्दीपनी कटुः २.","text":"chatrā śāleyaśālīno miśreyā madhurā misiḥ śatapuṣpā laghustīkṣṇā pittakṛddīpanī kaṭuḥ 2."},{"type":"verse","number":"91","sanskrit":"उष्णा ज्वरानिलश्लेष्मव्रणशूलाक्षिरोगहृत् मिश्रेया तद्गुणा प्रोक्ता विशेषाद्योनिशूलनुत्","text":"uṣṇā jvarānilaśleṣmavraṇaśūlākṣirogahṛt miśreyā tadguṇā proktā viśeṣādyoniśūlanut"},{"type":"verse","number":"92","sanskrit":"अग्निंमान्द्यहरी हृद्या बद्धविट्कृमिशुक्रहृत् रूक्षोष्णा पाचनी कासवमिश्लेष्मानिलान्हरेत्","text":"agniṃmāndyaharī hṛdyā baddhaviṭkṛmiśukrahṛt rūkṣoṣṇā pācanī kāsavamiśleṣmānilānharet"},{"type":"verse","number":"93","sanskrit":"मेथिका मेथिनी मेथी दीपनी बहुपत्रिका बोधिनी बहुबीजा च ज्योतिर्गन्धफला तथा","text":"methikā methinī methī dīpanī bahupatrikā bodhinī bahubījā ca jyotirgandhaphalā tathā"},{"type":"verse","number":"94","sanskrit":"वल्लरी चन्द्रि का मन्था मिश्रपुष्पा च कैरवी कुञ्चिका बहुपर्णी च पीतबीजा मुनिच्छदा","text":"vallarī candri kā manthā miśrapuṣpā ca kairavī kuñcikā bahuparṇī ca pītabījā municchadā"},{"type":"verse","number":"95","sanskrit":"ततः स्वल्पगुणावन्या वाजिनां सा तु पूजिता","text":"tataḥ svalpaguṇāvanyā vājināṃ sā tu pūjitā"},{"type":"verse","number":"96","sanskrit":"चन्द्रि का चर्महन्त्री च पशुमेहनकारिका नन्दिनी कारवी भद्रा वासपुष्पा सुवासरा","text":"candri kā carmahantrī ca paśumehanakārikā nandinī kāravī bhadrā vāsapuṣpā suvāsarā"},{"type":"verse","number":"97","sanskrit":"चन्द्र शूरं हितं हिक्कावातश्लेष्मातिसारिणाम् असृग्वातगदद्वेषि बलपुष्टिविवर्द्धनम्","text":"candra śūraṃ hitaṃ hikkāvātaśleṣmātisāriṇām asṛgvātagadadveṣi balapuṣṭivivarddhanam"},{"type":"verse","number":"98","sanskrit":"मेथिका चन्द्र शूरश्च कालाऽजाजी यवानिका एतच्चतुष्टयं युक्तं चतुर्बीजमिति स्मृतम्","text":"methikā candra śūraśca kālā'jājī yavānikā etaccatuṣṭayaṃ yuktaṃ caturbījamiti smṛtam"},{"type":"verse","number":"99","sanskrit":"तच्चूर्णं भक्षितं नित्यं निहन्ति पवनामयम् अजीर्णं शूलमाध्मानं पार्श्वशूलं कटिव्यथाम्","text":"taccūrṇaṃ bhakṣitaṃ nityaṃ nihanti pavanāmayam ajīrṇaṃ śūlamādhmānaṃ pārśvaśūlaṃ kaṭivyathām"},{"type":"verse","number":"100","sanskrit":"सहस्रवेधि जतुकं बाह्लीकं हिङ्गु रामठम् २.","text":"sahasravedhi jatukaṃ bāhlīkaṃ hiṅgu rāmaṭham 2."},{"type":"verse","number":"101","sanskrit":"हिङ्गूष्णं पाचनं रुच्यं तीक्ष्णं वातबलासनुत् शूलगुल्मोदरानाहकृमिघ्नं पित्तवर्द्धनम्","text":"hiṅgūṣṇaṃ pācanaṃ rucyaṃ tīkṣṇaṃ vātabalāsanut śūlagulmodarānāhakṛmighnaṃ pittavarddhanam"},{"type":"verse","number":"102","sanskrit":"वचोग्रगन्धा षड्र्गन्था गोलोमी शतपर्विका क्षुद्र पत्री च मङ्गल्या जटिलोग्रा च लोमशा","text":"vacogragandhā ṣaḍrganthā golomī śataparvikā kṣudra patrī ca maṅgalyā jaṭilogrā ca lomaśā"},{"type":"verse","number":"103","sanskrit":"वचोग्रगन्धा कटुका तिक्तोष्णा वान्तिवह्निकृत् विबन्धाध्मानशूलघ्नी शकृन्मूत्रविशोधिनी अपस्मारकफोन्मादभूतजन्त्वनिलान्हरेत्","text":"vacogragandhā kaṭukā tiktoṣṇā vāntivahnikṛt vibandhādhmānaśūlaghnī śakṛnmūtraviśodhinī apasmārakaphonmādabhūtajantvanilānharet"},{"type":"verse","number":"104","sanskrit":"पारसीक वचा शुक्ला प्रोक्ता हैमवतीति सा हैमवत्युदिता तद्वद्वातं हन्ति विशेषत","text":"pārasīka vacā śuklā proktā haimavatīti sā haimavatyuditā tadvadvātaṃ hanti viśeṣata"},{"type":"verse","number":"105","sanskrit":"सुगन्धाऽप्युग्रगन्धा च विशेषात्कफकासनुत् सुस्वरत्वकरी रुच्या हृत्कण्ठमुखशोधिनी","text":"sugandhā'pyugragandhā ca viśeṣātkaphakāsanut susvaratvakarī rucyā hṛtkaṇṭhamukhaśodhinī"},{"type":"verse","number":"106","sanskrit":"स्थूलग्रन्थिः सुगन्धा स्यात्ततो हीनगुणा स्मृता","text":"sthūlagranthiḥ sugandhā syāttato hīnaguṇā smṛtā"},{"type":"verse","number":"107","sanskrit":"द्वीपान्तरवचा किञ्चित्तिक्तोष्णा वह्निदीप्तिकृत् विबन्धाध्मानशूलघ्नी शकृन्मूत्रविशोधिनी","text":"dvīpāntaravacā kiñcittiktoṣṇā vahnidīptikṛt vibandhādhmānaśūlaghnī śakṛnmūtraviśodhinī"},{"type":"verse","number":"108","sanskrit":"वातव्याधीनपस्मारमुन्मादं तनुवेदनाम् व्यपोहति विशेषेण फिरङ्गामयनाशिनी","text":"vātavyādhīnapasmāramunmādaṃ tanuvedanām vyapohati viśeṣeṇa phiraṅgāmayanāśinī"},{"type":"verse","number":"109","sanskrit":"हपुषा हबुषा विस्रा पराऽश्वत्थफला मता मत्स्यगन्धाप्लीहहन्त्री विषघ्नी ध्वांक्षनाशिनी","text":"hapuṣā habuṣā visrā parā'śvatthaphalā matā matsyagandhāplīhahantrī viṣaghnī dhvāṃkṣanāśinī"},{"type":"verse","number":"110","sanskrit":"हपुषा दीपनी तिक्ता मृदूष्णा तुवरा गुरुः पित्तोदरसमीरार्शोग्रहणीगुल्मशूलहृत् पराऽप्येतद्गुणा प्रोक्ता रूपभेदो द्वयोरपिन २.","text":"hapuṣā dīpanī tiktā mṛdūṣṇā tuvarā guruḥ pittodarasamīrārśograhaṇīgulmaśūlahṛt parā'pyetadguṇā proktā rūpabhedo dvayorapina 2."},{"type":"verse","number":"111","sanskrit":"पुंसि क्लीवे विडङ्गः स्यात्कृमिघ्नो जन्तुनाशनः तण्डुलश्च तथा वेल्लममोघा चित्रतण्डुलः","text":"puṃsi klīve viḍaṅgaḥ syātkṛmighno jantunāśanaḥ taṇḍulaśca tathā vellamamoghā citrataṇḍulaḥ"},{"type":"verse","number":"112","sanskrit":"विडङ्गं कटु तीक्ष्णोष्णं रूक्षं वह्निकरं लघु शूलाध्मानोदरश्लेष्मकृमिवातविबन्धनुत्","text":"viḍaṅgaṃ kaṭu tīkṣṇoṣṇaṃ rūkṣaṃ vahnikaraṃ laghu śūlādhmānodaraśleṣmakṛmivātavibandhanut"},{"type":"verse","number":"113","sanskrit":"नाडी हिङ्गु पलाशाख्या जन्तुका रामठी च सा वंशपत्री च पिण्डाह्वा सुवीर्य्या हिङ्गुनाडिका तुम्बुरुः सौरभः सौरो वनजः सानुजोऽन्धकः","text":"nāḍī hiṅgu palāśākhyā jantukā rāmaṭhī ca sā vaṃśapatrī ca piṇḍāhvā suvīryyā hiṅgunāḍikā tumburuḥ saurabhaḥ sauro vanajaḥ sānujo'ndhakaḥ"},{"type":"verse","number":"114","sanskrit":"तुम्बुरु प्रथितं तिक्तं कटुपाकेऽपि तत्कटु रूक्षोष्णं दीपनं तीक्ष्णं रुच्यं लघु विदाहि च","text":"tumburu prathitaṃ tiktaṃ kaṭupāke'pi tatkaṭu rūkṣoṣṇaṃ dīpanaṃ tīkṣṇaṃ rucyaṃ laghu vidāhi ca"},{"type":"verse","number":"115","sanskrit":"कुष्ठशूलारुचिश्वासप्लीहकृच्छ्राणि नाशयेत्","text":"kuṣṭhaśūlāruciśvāsaplīhakṛcchrāṇi nāśayet"},{"type":"verse","number":"116","sanskrit":"स्याद्वंशरोचना वांशी तुगाक्षीरी तुगा शुभा त्वक्क्षीरी वंशजा शुभ्रा वंशक्षीरी च वैणवी","text":"syādvaṃśarocanā vāṃśī tugākṣīrī tugā śubhā tvakkṣīrī vaṃśajā śubhrā vaṃśakṣīrī ca vaiṇavī"},{"type":"verse","number":"117","sanskrit":"वंशजा वृंहणी वृष्या बल्या स्वाद्वी च शीतला तृष्णाकासज्वरश्वासक्षयपित्तास्रकामलाः हरेत्कुष्ठं व्रणं पाण्डुं कषाया वातकृच्छ्रजित्","text":"vaṃśajā vṛṃhaṇī vṛṣyā balyā svādvī ca śītalā tṛṣṇākāsajvaraśvāsakṣayapittāsrakāmalāḥ haretkuṣṭhaṃ vraṇaṃ pāṇḍuṃ kaṣāyā vātakṛcchrajit"},{"type":"verse","number":"118","sanskrit":"समुद्र फेनः फेनश्च हिण्डीरोऽब्धिकफस्तथा","text":"samudra phenaḥ phenaśca hiṇḍīro'bdhikaphastathā"},{"type":"verse","number":"119","sanskrit":"समुद्र फेनश्चक्षुष्यो लेखनः शीतलश्च सः कषायो विषपित्तघ्नः कर्णरुक्कफहृत्सरः","text":"samudra phenaścakṣuṣyo lekhanaḥ śītalaśca saḥ kaṣāyo viṣapittaghnaḥ karṇarukkaphahṛtsaraḥ"},{"type":"verse","number":"120","sanskrit":"जीवकर्षभकौ मेदे काकोल्यौ ऋद्धिवृद्धिके २.","text":"jīvakarṣabhakau mede kākolyau ṛddhivṛddhike 2."},{"type":"verse","number":"121","sanskrit":"अष्टवर्गोऽष्टभिर्द्र व्यैः कथितश्चरकादिभिः","text":"aṣṭavargo'ṣṭabhirdra vyaiḥ kathitaścarakādibhiḥ"},{"type":"verse","number":"122","sanskrit":"अष्टवर्गो हिमः स्वादुर्बृंहणः शुक्रलो गुरुः भग्नसन्धानकृत्कामबलासबलवर्द्धनः वातपित्तास्रतृड्दाहज्वरमेहक्षयप्रणुत्","text":"aṣṭavargo himaḥ svādurbṛṃhaṇaḥ śukralo guruḥ bhagnasandhānakṛtkāmabalāsabalavarddhanaḥ vātapittāsratṛḍdāhajvaramehakṣayapraṇut"},{"type":"verse","number":"123","sanskrit":"जीवकर्षभकौ ज्ञेयौ हिमाद्रि शिखरोद्भवौ रसोनकन्दवत्कन्दौ निःसारौ सूक्ष्मपत्रकौ","text":"jīvakarṣabhakau jñeyau himādri śikharodbhavau rasonakandavatkandau niḥsārau sūkṣmapatrakau"},{"type":"verse","number":"124","sanskrit":"जीवकः कूर्चकाकार ऋषभो वृष शृङ्गवत् जीवको मधुरः शृङ्गो ह्रस्वाङ्गः कूर्चशीर्षकः","text":"jīvakaḥ kūrcakākāra ṛṣabho vṛṣa śṛṅgavat jīvako madhuraḥ śṛṅgo hrasvāṅgaḥ kūrcaśīrṣakaḥ"},{"type":"verse","number":"125","sanskrit":"जीवकर्षभकौ बल्यौ शीतौ शुक्रकफप्रदौ मधुरौ पित्तदाहास्रकार्श्यवातक्षयापहौ","text":"jīvakarṣabhakau balyau śītau śukrakaphapradau madhurau pittadāhāsrakārśyavātakṣayāpahau"},{"type":"verse","number":"126","sanskrit":"महामेदाऽभिधः कन्दो मोरङ्गादौ प्रजायते","text":"mahāmedā'bhidhaḥ kando moraṅgādau prajāyate"},{"type":"verse","number":"127","sanskrit":"महामेदा वनीमेदा स्यादित्युक्तं मुनीश्वरैः","text":"mahāmedā vanīmedā syādityuktaṃ munīśvaraiḥ"},{"type":"verse","number":"128","sanskrit":"शुक्लार्द्र कनिभः कन्दो लताजातः सुपाण्डुरः महामेदाभिधो ज्ञेयो मेदालक्षणमुच्यते","text":"śuklārdra kanibhaḥ kando latājātaḥ supāṇḍuraḥ mahāmedābhidho jñeyo medālakṣaṇamucyate"},{"type":"verse","number":"129","sanskrit":"शुक्लकन्दो नखच्छेद्यो मेदोधातुमिव स्रवेत् यः स मेदेति विज्ञेयो जिज्ञासातत्परैर्जनैः","text":"śuklakando nakhacchedyo medodhātumiva sravet yaḥ sa medeti vijñeyo jijñāsātatparairjanaiḥ"},{"type":"verse","number":"130","sanskrit":"शल्यपर्णी मणिच्छिद्रा मेदा मेदाभवाध्वरा महामेदा वसुच्छिद्रा त्रिदन्ती देवतामणिः २.","text":"śalyaparṇī maṇicchidrā medā medābhavādhvarā mahāmedā vasucchidrā tridantī devatāmaṇiḥ 2."},{"type":"verse","number":"131","sanskrit":"मेदायुगं गुरु स्वादु वृष्यं स्तन्यकफावहम् वृंहणं शीतलं पित्तरक्तवातज्वरप्रणुत्","text":"medāyugaṃ guru svādu vṛṣyaṃ stanyakaphāvaham vṛṃhaṇaṃ śītalaṃ pittaraktavātajvarapraṇut"},{"type":"verse","number":"132","sanskrit":"जायते क्षीरकाकोली महामेदोद्भवस्थले","text":"jāyate kṣīrakākolī mahāmedodbhavasthale"},{"type":"verse","number":"133","sanskrit":"यत्र स्यात्क्षीरकाकोली काकोली तत्र जायते पीवरीसदृशः कन्दः सक्षीरः प्रियगन्धवान्","text":"yatra syātkṣīrakākolī kākolī tatra jāyate pīvarīsadṛśaḥ kandaḥ sakṣīraḥ priyagandhavān"},{"type":"verse","number":"134","sanskrit":"सा प्रोक्ताक्षीरकाकोली काकोलीलिङ्गमुच्यते यथास्यात्क्षीरकाकोली काकोल्यपि तथा भवेत्","text":"sā proktākṣīrakākolī kākolīliṅgamucyate yathāsyātkṣīrakākolī kākolyapi tathā bhavet"},{"type":"verse","number":"135","sanskrit":"एषा किञ्चिद्भवेत्कृष्णा भेदोऽयमुभयोरपि काकोली वायसोली च वीरा कायस्थिका तथा","text":"eṣā kiñcidbhavetkṛṣṇā bhedo'yamubhayorapi kākolī vāyasolī ca vīrā kāyasthikā tathā"},{"type":"verse","number":"136","sanskrit":"सा शुक्ला क्षीरकाकोली वयस्था क्षीरवल्लिका कथिता क्षीरिणी धीरा क्षीरशुक्ला पयस्विनी","text":"sā śuklā kṣīrakākolī vayasthā kṣīravallikā kathitā kṣīriṇī dhīrā kṣīraśuklā payasvinī"},{"type":"verse","number":"137","sanskrit":"काकोलीयुगलं शीतं शुक्रलं मधुरं गुरु वृंहणं वातदाहास्रपित्तशोषज्वरापहम्","text":"kākolīyugalaṃ śītaṃ śukralaṃ madhuraṃ guru vṛṃhaṇaṃ vātadāhāsrapittaśoṣajvarāpaham"},{"type":"verse","number":"138","sanskrit":"ऋद्धिर्वृद्धिश्च कन्दौ द्वौ भवतः कोशलेऽचले श्वेतलोमान्वितः कन्दो लताजातः सरन्ध्रकः","text":"ṛddhirvṛddhiśca kandau dvau bhavataḥ kośale'cale śvetalomānvitaḥ kando latājātaḥ sarandhrakaḥ"},{"type":"verse","number":"139","sanskrit":"स एव ऋद्धिर्वृद्धिश्च भेदमप्येतयोर्ब्रुवे तूलग्रन्थिसमा ऋद्धिर्वामावर्त्तफला च सा","text":"sa eva ṛddhirvṛddhiśca bhedamapyetayorbruve tūlagranthisamā ṛddhirvāmāvarttaphalā ca sā"},{"type":"verse","number":"140","sanskrit":"वृद्धिस्तु दक्षिणावर्त्तफला प्रोक्ता महर्षिभिः ऋद्धिर्योग्यं सिद्धिलक्ष्म्यौ वृद्धेरप्याह्वया इमे २.","text":"vṛddhistu dakṣiṇāvarttaphalā proktā maharṣibhiḥ ṛddhiryogyaṃ siddhilakṣmyau vṛddherapyāhvayā ime 2."},{"type":"verse","number":"141","sanskrit":"ऋद्धिर्बल्या त्रिदोषघ्नी शुक्रला मधुरा गुरुः प्राणैश्वर्यकरी मूर्च्छारक्तपित्तविनाशिनी","text":"ṛddhirbalyā tridoṣaghnī śukralā madhurā guruḥ prāṇaiśvaryakarī mūrcchāraktapittavināśinī"},{"type":"verse","number":"142","sanskrit":"वृद्धिर्गर्भप्रदा शीता वृंहणी मधुरा स्मृता वृष्या पित्तास्रशमनी क्षतकासक्षयापहा","text":"vṛddhirgarbhapradā śītā vṛṃhaṇī madhurā smṛtā vṛṣyā pittāsraśamanī kṣatakāsakṣayāpahā"},{"type":"verse","number":"143","sanskrit":"राज्ञामप्यष्टवर्गस्तु यतोऽयमतिदुर्लभः तस्मादस्य प्रतिनिधिं गृह्णीयात्तद्गुणं भिषक्","text":"rājñāmapyaṣṭavargastu yato'yamatidurlabhaḥ tasmādasya pratinidhiṃ gṛhṇīyāttadguṇaṃ bhiṣak"},{"type":"verse","number":"144","sanskrit":"मेदा जीवक काकोली ऋद्धि द्वन्द्वेऽपि चासति वरीविदार्यश्वगन्धावाराहींश्च क्रमात् क्षिपेत्","text":"medā jīvaka kākolī ṛddhi dvandve'pi cāsati varīvidāryaśvagandhāvārāhīṃśca kramāt kṣipet"},{"type":"verse","number":"145","sanskrit":"यष्टीमधु तथा यष्टीमधुकं क्लीतकं तथा अन्यत्क्लीतनकं तत्तु भवेत्तोये मधूलिका","text":"yaṣṭīmadhu tathā yaṣṭīmadhukaṃ klītakaṃ tathā anyatklītanakaṃ tattu bhavettoye madhūlikā"},{"type":"verse","number":"146","sanskrit":"यष्टी हिमा गुरुः स्वाद्वी चक्षुष्या बलवर्णकृत् सुस्निग्धा शुक्रला केश्या स्वर्या पित्तानिलास्रजित् व्रण शोथ विष च्छर्दि तृष्णाग्लानिक्षयापहा","text":"yaṣṭī himā guruḥ svādvī cakṣuṣyā balavarṇakṛt susnigdhā śukralā keśyā svaryā pittānilāsrajit vraṇa śotha viṣa cchardi tṛṣṇāglānikṣayāpahā"},{"type":"verse","number":"147","sanskrit":"काम्पिल्लः कर्कशश्चन्द्रो रक्ताङ्गो रोचनोऽपि च काम्पिल्लः कफपित्तास्रकृमिगुल्मोदरव्रणान् हन्ति रेची कटूष्णश्च मेहानाहविषाश्मनुत्","text":"kāmpillaḥ karkaśaścandro raktāṅgo rocano'pi ca kāmpillaḥ kaphapittāsrakṛmigulmodaravraṇān hanti recī kaṭūṣṇaśca mehānāhaviṣāśmanut"},{"type":"verse","number":"148","sanskrit":"आरग्बवधो राजवृक्षः शम्पाकश्चतुरङ्गुलः आरेवतो व्याधिघातः कृतमालः सुवर्णकः","text":"āragbavadho rājavṛkṣaḥ śampākaścaturaṅgulaḥ ārevato vyādhighātaḥ kṛtamālaḥ suvarṇakaḥ"},{"type":"verse","number":"149","sanskrit":"कर्णिकारो दीर्घफलः स्वर्णाङ्गः स्वर्णभूषणः आरग्वधोगुरुःस्वादुः शीतलः स्रंसनोत्तमः","text":"karṇikāro dīrghaphalaḥ svarṇāṅgaḥ svarṇabhūṣaṇaḥ āragvadhoguruḥsvāduḥ śītalaḥ sraṃsanottamaḥ"},{"type":"verse","number":"150","sanskrit":"ज्वरहृद्रो गापित्तास्रवातोदावर्त्तशूलनुत् तत्फलं स्रंसनं रुच्यं कुष्ठपित्तकफापहम् ज्वरे तु सततं पथ्यं कोष्ठशुद्धिकरं परम् २.","text":"jvarahṛdro gāpittāsravātodāvarttaśūlanut tatphalaṃ sraṃsanaṃ rucyaṃ kuṣṭhapittakaphāpaham jvare tu satataṃ pathyaṃ koṣṭhaśuddhikaraṃ param 2."},{"type":"verse","number":"151","sanskrit":"कट्वी तु कटुका तिक्ता कृष्णभेदा कटम्भरा अशोका मत्स्यशकला चक्राङ्गी शकुलादनी मत्स्यपित्ता काण्डरुहा रोहिणी कटुरोहिणी","text":"kaṭvī tu kaṭukā tiktā kṛṣṇabhedā kaṭambharā aśokā matsyaśakalā cakrāṅgī śakulādanī matsyapittā kāṇḍaruhā rohiṇī kaṭurohiṇī"},{"type":"verse","number":"152","sanskrit":"कट्वी तु कटुका पाके तिक्ता रूक्षा हिमा लघुः भेदिनी दीपनी हृद्या कफपित्तज्वरापहा प्रमेहश्वासकासास्रदाहकुष्ठकृमिप्रणुत्","text":"kaṭvī tu kaṭukā pāke tiktā rūkṣā himā laghuḥ bhedinī dīpanī hṛdyā kaphapittajvarāpahā pramehaśvāsakāsāsradāhakuṣṭhakṛmipraṇut"},{"type":"verse","number":"153","sanskrit":"किराततिक्तः कैरातः कटुतिक्तः किरातकः","text":"kirātatiktaḥ kairātaḥ kaṭutiktaḥ kirātakaḥ"},{"type":"verse","number":"154","sanskrit":"काण्डतिक्तोऽनार्यतिक्तो भूनिम्बो रामसेनकः किरातकोऽन्यो नैपालः सोऽद्धतिक्तो ज्वरान्तकः","text":"kāṇḍatikto'nāryatikto bhūnimbo rāmasenakaḥ kirātako'nyo naipālaḥ so'ddhatikto jvarāntakaḥ"},{"type":"verse","number":"155","sanskrit":"किरातः सारको रूक्षः शीतलस्तिक्तको लघुः सन्निपातज्वरश्वासकफपित्तास्रदाहनुत् कासशोथतृषाकुष्ठज्वरव्रणकृमिप्रणुत्","text":"kirātaḥ sārako rūkṣaḥ śītalastiktako laghuḥ sannipātajvaraśvāsakaphapittāsradāhanut kāsaśothatṛṣākuṣṭhajvaravraṇakṛmipraṇut"},{"type":"verse","number":"156","sanskrit":"उक्तं कुटजबीजं तु यवमिन्द्र यवं तथा कलिङ्गं चापि कालिङ्गं तथा भद्र यवा अपि","text":"uktaṃ kuṭajabījaṃ tu yavamindra yavaṃ tathā kaliṅgaṃ cāpi kāliṅgaṃ tathā bhadra yavā api"},{"type":"verse","number":"157","sanskrit":"क्वचिदिन्द्र स्य नामैव भवेत्तदभिधायकम् फलानीन्द्र यवास्तस्य तथा भद्र यवा अपि","text":"kvacidindra sya nāmaiva bhavettadabhidhāyakam phalānīndra yavāstasya tathā bhadra yavā api"},{"type":"verse","number":"158","sanskrit":"इन्द्र यवं त्रिदोषघ्नं संग्राहि कटु शीतलम्","text":"indra yavaṃ tridoṣaghnaṃ saṃgrāhi kaṭu śītalam"},{"type":"verse","number":"159","sanskrit":"दीपनं गुदकीलास्रवातास्रश्लेष्मशूलजित्","text":"dīpanaṃ gudakīlāsravātāsraśleṣmaśūlajit"},{"type":"verse","number":"160","sanskrit":"मदनश्छर्दनः पिण्डो नटः पिण्डीतकस्तथा करहाटो मरुवकः शल्यको विषपुष्पकः २.","text":"madanaśchardanaḥ piṇḍo naṭaḥ piṇḍītakastathā karahāṭo maruvakaḥ śalyako viṣapuṣpakaḥ 2."},{"type":"verse","number":"161","sanskrit":"मदनो मधुरस्तिक्तो वीर्योष्णो लेखनो लघुः वान्तिकृद्विद्र धिहरः प्रतिश्यायव्रणान्तकः रूक्ष कुष्ठकफानाहशोथगुल्मव्रणापहः","text":"madano madhurastikto vīryoṣṇo lekhano laghuḥ vāntikṛdvidra dhiharaḥ pratiśyāyavraṇāntakaḥ rūkṣa kuṣṭhakaphānāhaśothagulmavraṇāpahaḥ"},{"type":"verse","number":"162","sanskrit":"रास्ना युक्तरसा रस्या सुवहा रसना रसा एलापर्णी च सुरसा सुगन्धा श्रेयसी तथा","text":"rāsnā yuktarasā rasyā suvahā rasanā rasā elāparṇī ca surasā sugandhā śreyasī tathā"},{"type":"verse","number":"163","sanskrit":"रास्नाऽमपाचिनी तिक्ता गुरूष्णा कफवातजित्","text":"rāsnā'mapācinī tiktā gurūṣṇā kaphavātajit"},{"type":"verse","number":"164","sanskrit":"कासज्वरविषाशीतिवातिकामयसिध्महृत्","text":"kāsajvaraviṣāśītivātikāmayasidhmahṛt"},{"type":"verse","number":"165","sanskrit":"नाकुली सुरसा नागसुगन्धा गन्धनाकुली नकुलेष्टा भुजङ्गाक्षी सर्पाङ्गी विषनाशिनी","text":"nākulī surasā nāgasugandhā gandhanākulī nakuleṣṭā bhujaṅgākṣī sarpāṅgī viṣanāśinī"},{"type":"verse","number":"166","sanskrit":"नाकुली तुवरा तिक्ता कटुकोष्णा विनाशयेत् भोगिलूतावृश्चिकाखुविषज्वरकृमिव्रणान्","text":"nākulī tuvarā tiktā kaṭukoṣṇā vināśayet bhogilūtāvṛścikākhuviṣajvarakṛmivraṇān"},{"type":"verse","number":"167","sanskrit":"माचिकाप्रस्थिकाऽम्बष्ठा तथा चाम्बालिकांऽबिका मयूरविदला केशीसहस्रा बालमूलिका","text":"mācikāprasthikā'mbaṣṭhā tathā cāmbālikāṃ'bikā mayūravidalā keśīsahasrā bālamūlikā"},{"type":"verse","number":"168","sanskrit":"माचिकाऽम्ला रसे पाके कषाया शीतला लघुः पक्वातीसारपित्तास्रकफकण्ठामयापहा","text":"mācikā'mlā rase pāke kaṣāyā śītalā laghuḥ pakvātīsārapittāsrakaphakaṇṭhāmayāpahā"},{"type":"verse","number":"169","sanskrit":"तेजस्विनी तेजवती तेजोह्वा तेजनी तथा","text":"tejasvinī tejavatī tejohvā tejanī tathā"},{"type":"verse","number":"170","sanskrit":"तेजस्विनी कफश्वासकासास्यामयवातहृत् पाचन्युष्णाकटुस्तिक्तारुचिवह्निप्रदीपिनी २.","text":"tejasvinī kaphaśvāsakāsāsyāmayavātahṛt pācanyuṣṇākaṭustiktārucivahnipradīpinī 2."},{"type":"verse","number":"171","sanskrit":"ज्योतिष्मती स्यात्कटभी ज्योतिष्का कङ्गुनीति च पारावतपदी पिण्या लता प्रोक्ता ककुन्दनी","text":"jyotiṣmatī syātkaṭabhī jyotiṣkā kaṅgunīti ca pārāvatapadī piṇyā latā proktā kakundanī"},{"type":"verse","number":"172","sanskrit":"ज्योतिष्मती कटुस्तिक्ता सरा कफसमीरजित् अत्युष्णा वामनी तीक्ष्णा वह्निबुद्धिस्मृतिप्रदा","text":"jyotiṣmatī kaṭustiktā sarā kaphasamīrajit atyuṣṇā vāmanī tīkṣṇā vahnibuddhismṛtipradā"},{"type":"verse","number":"173","sanskrit":"कुष्ठं रोगाह्वयं वाप्यं पारिभव्यं तथोत्पलम् कुष्ठमुष्णं कटु स्वादु शुक्रलं तिक्तकं लघु हन्ति वातास्रवीसर्पकासकुष्ठमरुत्कफान्","text":"kuṣṭhaṃ rogāhvayaṃ vāpyaṃ pāribhavyaṃ tathotpalam kuṣṭhamuṣṇaṃ kaṭu svādu śukralaṃ tiktakaṃ laghu hanti vātāsravīsarpakāsakuṣṭhamarutkaphān"},{"type":"verse","number":"174","sanskrit":"उक्तं पुष्करमूलं तु पौष्करं पुष्करञ्च तत् पद्मपत्रञ्च काश्मीरं कुष्ठभेदमिमं जगुः","text":"uktaṃ puṣkaramūlaṃ tu pauṣkaraṃ puṣkarañca tat padmapatrañca kāśmīraṃ kuṣṭhabhedamimaṃ jaguḥ"},{"type":"verse","number":"175","sanskrit":"पौष्करं कटुकं तिक्तमुक्तं वातकफज्वरान् हन्ति शोथारुचिश्वासान्विशेषात्पार्श्वशूलनुत्","text":"pauṣkaraṃ kaṭukaṃ tiktamuktaṃ vātakaphajvarān hanti śothāruciśvāsānviśeṣātpārśvaśūlanut"},{"type":"verse","number":"176","sanskrit":"कटुपर्णी हैमवती हेमक्षीरी हिमावती हेमाह्वा पीतदुग्धा च तन्मूलं चोकमुच्यते","text":"kaṭuparṇī haimavatī hemakṣīrī himāvatī hemāhvā pītadugdhā ca tanmūlaṃ cokamucyate"},{"type":"verse","number":"177","sanskrit":"हेमाह्वा रेचनी तिक्ता भेदिन्युत्क्लेशकारिणी कृमिकण्डूविषानाहकफपित्तास्रकुष्ठनुत्","text":"hemāhvā recanī tiktā bhedinyutkleśakāriṇī kṛmikaṇḍūviṣānāhakaphapittāsrakuṣṭhanut"},{"type":"verse","number":"178","sanskrit":"शृङ्गी कर्कटशृङ्गी च स्यात्कुलीरविषाणिका अजशृङ्गी च चक्रा च कर्कटाख्या च कीर्त्तिता","text":"śṛṅgī karkaṭaśṛṅgī ca syātkulīraviṣāṇikā ajaśṛṅgī ca cakrā ca karkaṭākhyā ca kīrttitā"},{"type":"verse","number":"179","sanskrit":"शृङ्गी कषाया तिक्तोष्णा कफवातक्षयज्वरान् श्वासोर्ध्ववाततृट्कासहिक्काऽरुचिवमीन्हरेत्","text":"śṛṅgī kaṣāyā tiktoṣṇā kaphavātakṣayajvarān śvāsordhvavātatṛṭkāsahikkā'rucivamīnharet"},{"type":"verse","number":"180","sanskrit":"कट्फलः सोमवल्कश्च कैटर्य्यः कुम्भिकाऽपि च श्रीपर्णिका कुमुदिका भद्रा भद्र वतीति च २.","text":"kaṭphalaḥ somavalkaśca kaiṭaryyaḥ kumbhikā'pi ca śrīparṇikā kumudikā bhadrā bhadra vatīti ca 2."},{"type":"verse","number":"181","sanskrit":"कट्फलस्तुवरस्तिक्तः कटुर्वातकफज्वरान् हन्ति श्वासप्रमेहार्शः कासकण्ठामयारुचीः","text":"kaṭphalastuvarastiktaḥ kaṭurvātakaphajvarān hanti śvāsapramehārśaḥ kāsakaṇṭhāmayārucīḥ"},{"type":"verse","number":"182","sanskrit":"भार्गी भृगुभवा पद्मा फञ्जी ब्राह्मणयष्टिका ब्राह्मण्यङ्गारवल्ली च खरशाकश्च हञ्जिका","text":"bhārgī bhṛgubhavā padmā phañjī brāhmaṇayaṣṭikā brāhmaṇyaṅgāravallī ca kharaśākaśca hañjikā"},{"type":"verse","number":"183","sanskrit":"भार्गी रूक्षा कटुस्तिक्ता रुच्योष्णा पाचनी लघुः दीपनी तुवरा गुल्मरक्तनुन्नाशयेद् ध्रुवम् शोथकासकफश्वासपीनसज्वरमारुतान्","text":"bhārgī rūkṣā kaṭustiktā rucyoṣṇā pācanī laghuḥ dīpanī tuvarā gulmaraktanunnāśayed dhruvam śothakāsakaphaśvāsapīnasajvaramārutān"},{"type":"verse","number":"184","sanskrit":"पाषाणभेदकोऽश्मघ्नो गिरिभिद्भिन्नयोजिनी अश्मभेदो हिमस्तिक्तः कषायो वस्तिशोधनः","text":"pāṣāṇabhedako'śmaghno giribhidbhinnayojinī aśmabhedo himastiktaḥ kaṣāyo vastiśodhanaḥ"},{"type":"verse","number":"185","sanskrit":"भेदनो हन्ति दोषार्शोगुल्मकृच्छ्राश्महृद्द्रुजः योनि रोगान्प्रमेहांश्च प्लीह शूल व्रणानि च","text":"bhedano hanti doṣārśogulmakṛcchrāśmahṛddrujaḥ yoni rogānpramehāṃśca plīha śūla vraṇāni ca"},{"type":"verse","number":"186","sanskrit":"धातकी धातुपुष्पी च ताम्रपुष्पी च कुञ्जरा सुभिक्षा बहुपुष्पी च वह्निज्वाला च सा स्मृता","text":"dhātakī dhātupuṣpī ca tāmrapuṣpī ca kuñjarā subhikṣā bahupuṣpī ca vahnijvālā ca sā smṛtā"},{"type":"verse","number":"187","sanskrit":"धातकी कटुका शीता मृदुकृत्तुवरा लघुः तृष्णाऽतीसारपित्तास्रविषकृमिविसर्पजित्","text":"dhātakī kaṭukā śītā mṛdukṛttuvarā laghuḥ tṛṣṇā'tīsārapittāsraviṣakṛmivisarpajit"},{"type":"verse","number":"188","sanskrit":"मञ्जिष्ठा विकसा जिङ्गी समङ्गा कालमेषिका","text":"mañjiṣṭhā vikasā jiṅgī samaṅgā kālameṣikā"},{"type":"verse","number":"189","sanskrit":"मण्डूकपर्णी भण्डीरी भण्डी योजनवल्ल्यपि रसायन्यरुणा काला रक्ताङ्गी रक्तयष्टिका","text":"maṇḍūkaparṇī bhaṇḍīrī bhaṇḍī yojanavallyapi rasāyanyaruṇā kālā raktāṅgī raktayaṣṭikā"},{"type":"verse","number":"190","sanskrit":"भण्डीतकी च गण्डीरी मञ्जूषा वस्त्ररञ्जिनी मञ्जिष्ठा मधुरा तिक्ता कषाया स्वरवर्णकृत् २.","text":"bhaṇḍītakī ca gaṇḍīrī mañjūṣā vastrarañjinī mañjiṣṭhā madhurā tiktā kaṣāyā svaravarṇakṛt 2."},{"type":"verse","number":"191","sanskrit":"गुरुरुष्णा विषश्लेष्मशोथयोन्यक्षिकर्णरुक् रक्तातीसार कुष्ठास्र वीसर्पव्रणमेहनुत्","text":"gururuṣṇā viṣaśleṣmaśothayonyakṣikarṇaruk raktātīsāra kuṣṭhāsra vīsarpavraṇamehanut"},{"type":"verse","number":"192","sanskrit":"स्यात्कुसुम्भं वह्निशिखं वस्त्ररञ्जकमित्यपि कुसुम्भं वातलं कृच्छ्ररक्तपित्तकफापहम्","text":"syātkusumbhaṃ vahniśikhaṃ vastrarañjakamityapi kusumbhaṃ vātalaṃ kṛcchraraktapittakaphāpaham"},{"type":"verse","number":"193","sanskrit":"लाक्षा पलंकषालक्तो यावो वृक्षामयो जतुः लाक्षा वर्ण्या हिमा बल्या स्निग्धा च तुवरा लघुः","text":"lākṣā palaṃkaṣālakto yāvo vṛkṣāmayo jatuḥ lākṣā varṇyā himā balyā snigdhā ca tuvarā laghuḥ"},{"type":"verse","number":"194","sanskrit":"ब्रिआ!ह्मण्यङ्गारवल्ली च खरशाखा च हञ्जिका अनुष्णा कफपित्तास्रहिक्काकासज्वरप्रणुत्","text":"briā!hmaṇyaṅgāravallī ca kharaśākhā ca hañjikā anuṣṇā kaphapittāsrahikkākāsajvarapraṇut"},{"type":"verse","number":"195","sanskrit":"अलक्तको गुणैस्तद्वद्विशेषाद्व्यङ्गनाशनः","text":"alaktako guṇaistadvadviśeṣādvyaṅganāśanaḥ"},{"type":"verse","number":"196","sanskrit":"हरिद्रा काञ्चनी पीता निशाऽख्या वरवर्णिनी कृमिघ्नी हलदी योषित्प्रिया हट्टविलासिनी","text":"haridrā kāñcanī pītā niśā'khyā varavarṇinī kṛmighnī haladī yoṣitpriyā haṭṭavilāsinī"},{"type":"verse","number":"197","sanskrit":"हरिद्रा कटुका तिक्ता रूक्षोष्णा कफपित्तनुत् वर्ण्या त्वग्दोषमेहास्रशोथपाण्डुव्रणापहा","text":"haridrā kaṭukā tiktā rūkṣoṣṇā kaphapittanut varṇyā tvagdoṣamehāsraśothapāṇḍuvraṇāpahā"},{"type":"verse","number":"198","sanskrit":"दार्वी मेदाऽम्रगन्धा च सुरभीदारु दारु च कर्पूरा पद्मपत्रा स्यात्सुरीमत्सुरतारका","text":"dārvī medā'mragandhā ca surabhīdāru dāru ca karpūrā padmapatrā syātsurīmatsuratārakā"},{"type":"verse","number":"199","sanskrit":"आम्रगंधिर्हरिद्रा या सा शीता वातला मता पित्तहृन्मधुरा तिक्ता सर्वकण्डूविनाशिनी","text":"āmragaṃdhirharidrā yā sā śītā vātalā matā pittahṛnmadhurā tiktā sarvakaṇḍūvināśinī"},{"type":"verse","number":"200","sanskrit":"अरण्यहलदीकन्दः कुष्ठवातास्रनाशनः २.","text":"araṇyahaladīkandaḥ kuṣṭhavātāsranāśanaḥ 2."},{"type":"verse","number":"201","sanskrit":"दार्वी दारुहरिद्रा च पर्जन्या पर्जनीति च कटङ्कटेरी पीता च भवेत्सैव पचम्पचा सैव कालीयकः प्रोक्तस्तथा कालेयकोऽपि च","text":"dārvī dāruharidrā ca parjanyā parjanīti ca kaṭaṅkaṭerī pītā ca bhavetsaiva pacampacā saiva kālīyakaḥ proktastathā kāleyako'pi ca"},{"type":"verse","number":"202","sanskrit":"पीतद्रुश्च हरिद्रुश्च पीतदारु च पीतकम् दार्वी निशागुणा किन्तु नेत्र कर्णास्यरोगनुत्","text":"pītadruśca haridruśca pītadāru ca pītakam dārvī niśāguṇā kintu netra karṇāsyaroganut"},{"type":"verse","number":"203","sanskrit":"दार्वीक्वाथसमं क्षीरं पादं पक्त्वा यदा घनम् तदा रसाञ्जनाख्यं तन्नेत्रयोः परमं हितम्","text":"dārvīkvāthasamaṃ kṣīraṃ pādaṃ paktvā yadā ghanam tadā rasāñjanākhyaṃ tannetrayoḥ paramaṃ hitam"},{"type":"verse","number":"204","sanskrit":"रसाञ्जनं तार्क्ष्यशैलं रसगर्भश्च तार्क्ष्यजम् रसाञ्जनं कटु श्लेष्मविषनेत्रविकारनुत्","text":"rasāñjanaṃ tārkṣyaśailaṃ rasagarbhaśca tārkṣyajam rasāñjanaṃ kaṭu śleṣmaviṣanetravikāranut"},{"type":"verse","number":"205","sanskrit":"उष्णं रसायनं तिक्तं छेदनं व्रणदोषहृत्","text":"uṣṇaṃ rasāyanaṃ tiktaṃ chedanaṃ vraṇadoṣahṛt"},{"type":"verse","number":"206","sanskrit":"अवल्गुजो वाकुची स्यात्सोमराजी सुपर्णिका शशिलेखा कृष्णफला सोमा पूतिफलीति च","text":"avalgujo vākucī syātsomarājī suparṇikā śaśilekhā kṛṣṇaphalā somā pūtiphalīti ca"},{"type":"verse","number":"207","sanskrit":"सोमवल्ली कालमेषी कुष्ठघ्नी च प्रकीर्त्तिता बाकुची मधुरा तिक्ता कटुपाका रसायनी","text":"somavallī kālameṣī kuṣṭhaghnī ca prakīrttitā bākucī madhurā tiktā kaṭupākā rasāyanī"},{"type":"verse","number":"208","sanskrit":"विष्टम्भहृद्धिमा रुच्या सरा श्लेष्मास्रपित्तनुत् रूक्षा हृद्या श्वासकुष्ठमेहज्वरकृमिप्रणुत्","text":"viṣṭambhahṛddhimā rucyā sarā śleṣmāsrapittanut rūkṣā hṛdyā śvāsakuṣṭhamehajvarakṛmipraṇut"},{"type":"verse","number":"209","sanskrit":"तत्फलं पित्तलं कुष्ठकफानिलहरं कटु केश्यं त्वच्यं कृमिश्वासकासशोथामपाण्डुनुत्","text":"tatphalaṃ pittalaṃ kuṣṭhakaphānilaharaṃ kaṭu keśyaṃ tvacyaṃ kṛmiśvāsakāsaśothāmapāṇḍunut"},{"type":"verse","number":"210","sanskrit":"चक्रमर्दः प्रपुन्नाटो दद्रुघ्नो मेषलोचनः पद्माटः स्यादेडगजश्चक्री पुन्नाट इत्यपि २.","text":"cakramardaḥ prapunnāṭo dadrughno meṣalocanaḥ padmāṭaḥ syādeḍagajaścakrī punnāṭa ityapi 2."},{"type":"verse","number":"211","sanskrit":"चक्रमर्दो लघुः स्वादू रूक्षः पित्तानिलापहः हृद्यो हिमः कफश्वासकुष्ठदद्रुकृमीन्हरेत्","text":"cakramardo laghuḥ svādū rūkṣaḥ pittānilāpahaḥ hṛdyo himaḥ kaphaśvāsakuṣṭhadadrukṛmīnharet"},{"type":"verse","number":"212","sanskrit":"हन्त्युष्णं तत्फलं कुष्ठकण्डूदद्रुविषानिलान् गुल्मकासकृमिश्वासनाशनं कटुकं स्मृतम्","text":"hantyuṣṇaṃ tatphalaṃ kuṣṭhakaṇḍūdadruviṣānilān gulmakāsakṛmiśvāsanāśanaṃ kaṭukaṃ smṛtam"},{"type":"verse","number":"213","sanskrit":"विषा त्वतिविषा विश्वा शृङ्गी प्रतिविषाऽरुणा शुक्लकन्दा चोपविषा भङ्गुरा घुणवल्लभा","text":"viṣā tvativiṣā viśvā śṛṅgī prativiṣā'ruṇā śuklakandā copaviṣā bhaṅgurā ghuṇavallabhā"},{"type":"verse","number":"214","sanskrit":"विषा सोष्णा कटुस्तिक्ता पाचनी दीपनी हरेत् कफपित्तातिसारामविषकासवमिकृमीन्","text":"viṣā soṣṇā kaṭustiktā pācanī dīpanī haret kaphapittātisārāmaviṣakāsavamikṛmīn"},{"type":"verse","number":"215","sanskrit":"लोध्रस्तिल्वस्तिरीटश्च शावरो गालवस्तथा द्वितीयः पट्टिकालोध्रः क्रमुकः स्थूलवल्कलः जीर्णपत्रो बृहत्पत्रः पट्टी लाक्षाप्रसादनः","text":"lodhrastilvastirīṭaśca śāvaro gālavastathā dvitīyaḥ paṭṭikālodhraḥ kramukaḥ sthūlavalkalaḥ jīrṇapatro bṛhatpatraḥ paṭṭī lākṣāprasādanaḥ"},{"type":"verse","number":"216","sanskrit":"लोध्रो ग्राही लघुः शीतश्चक्षुष्यः कफपित्तनुत् कषायो रक्तपित्तासृग्ज्वरातीसारशोथहृत्","text":"lodhro grāhī laghuḥ śītaścakṣuṣyaḥ kaphapittanut kaṣāyo raktapittāsṛgjvarātīsāraśothahṛt"},{"type":"verse","number":"217","sanskrit":"लशुनस्तु रसोनः स्यादुग्रगन्धो महौषधम् अरिष्टो म्लेच्छकन्दश्च यवनेष्टो रसोनकः","text":"laśunastu rasonaḥ syādugragandho mahauṣadham ariṣṭo mlecchakandaśca yavaneṣṭo rasonakaḥ"},{"type":"verse","number":"218","sanskrit":"यदाऽमृतं वैनतेयो जहार सुरसत्तमात् तदा ततोऽपतद् विन्दुः स रसोनोऽभवद्भुवि","text":"yadā'mṛtaṃ vainateyo jahāra surasattamāt tadā tato'patad vinduḥ sa rasono'bhavadbhuvi"},{"type":"verse","number":"219","sanskrit":"पञ्चभिश्च रसैर्युक्तो रसेनाम्लेन वर्जितः तस्माद्र सोन इत्युक्तो द्र व्याणां गुणवेदिभिः","text":"pañcabhiśca rasairyukto rasenāmlena varjitaḥ tasmādra sona ityukto dra vyāṇāṃ guṇavedibhiḥ"},{"type":"verse","number":"220","sanskrit":"कटुकश्चापि मूलेषु तिक्तः पत्रेषु संस्थितः नाले कषाय उद्दिष्टो नालाग्रे लवणः स्मृतः बीजे तु मधुरः प्रोक्तो रसस्तद्गुणवेदिभिः २.","text":"kaṭukaścāpi mūleṣu tiktaḥ patreṣu saṃsthitaḥ nāle kaṣāya uddiṣṭo nālāgre lavaṇaḥ smṛtaḥ bīje tu madhuraḥ prokto rasastadguṇavedibhiḥ 2."},{"type":"verse","number":"221","sanskrit":"रसोनो वृंहणो वृष्यः स्निग्धोष्णः पाचनः सरः रसे पाके च कटुकस्तीक्ष्णो मधुरको मतः","text":"rasono vṛṃhaṇo vṛṣyaḥ snigdhoṣṇaḥ pācanaḥ saraḥ rase pāke ca kaṭukastīkṣṇo madhurako mataḥ"},{"type":"verse","number":"222","sanskrit":"भग्नसन्धानकृत्कण्ठ्यो गुरुः पित्तास्रवृद्धिदः बलवर्णकरो मेधाहितो नेत्र्! यो रसायनः","text":"bhagnasandhānakṛtkaṇṭhyo guruḥ pittāsravṛddhidaḥ balavarṇakaro medhāhito netr! yo rasāyanaḥ"},{"type":"verse","number":"223","sanskrit":"हृद्रो गजीर्णज्वरकुक्षिशूलविबन्धगुल्मारुचिकासशोफान् दुर्नामकुष्ठानलसादजन्तुसमीरणश्वासकफांश्च हन्ति","text":"hṛdro gajīrṇajvarakukṣiśūlavibandhagulmārucikāsaśophān durnāmakuṣṭhānalasādajantusamīraṇaśvāsakaphāṃśca hanti"},{"type":"verse","number":"224","sanskrit":"मद्यं मांसं तथाऽम्लञ्च हितं लशुनसेविनाम् व्यायाममातपं रोषमतिनीरं पयो गुडम्","text":"madyaṃ māṃsaṃ tathā'mlañca hitaṃ laśunasevinām vyāyāmamātapaṃ roṣamatinīraṃ payo guḍam"},{"type":"verse","number":"225","sanskrit":"रसोनमश्नन् पुरुषस्त्यजेदेतान् निरन्तरम्","text":"rasonamaśnan puruṣastyajedetān nirantaram"},{"type":"verse","number":"226","sanskrit":"पलाण्डुर्यवनेष्टश्च दुर्गन्धो मुखदूषकः पलाण्डुस्तु बुधैर्ज्ञेयो रसोनसदृशो गुणैः","text":"palāṇḍuryavaneṣṭaśca durgandho mukhadūṣakaḥ palāṇḍustu budhairjñeyo rasonasadṛśo guṇaiḥ"},{"type":"verse","number":"227","sanskrit":"स्वादुः पाके रसेऽनुष्णः कफकृन्नातिपित्तलः हरते केवलं वातं बलवीर्यकरो गुरुः","text":"svāduḥ pāke rase'nuṣṇaḥ kaphakṛnnātipittalaḥ harate kevalaṃ vātaṃ balavīryakaro guruḥ"},{"type":"verse","number":"228","sanskrit":"भल्लातकं त्रिषु प्रोक्तमरुष्कोरुष्करोऽग्निकः तथैवाग्निमुखी भल्ली वीरवृक्षश्च शोफकृत्","text":"bhallātakaṃ triṣu proktamaruṣkoruṣkaro'gnikaḥ tathaivāgnimukhī bhallī vīravṛkṣaśca śophakṛt"},{"type":"verse","number":"229","sanskrit":"भल्लातकफलं पक्वं स्वादुपाकरसं लघु कषायं पाचनं स्निग्धं तीक्ष्णोष्णं छेदि भेदनम्","text":"bhallātakaphalaṃ pakvaṃ svādupākarasaṃ laghu kaṣāyaṃ pācanaṃ snigdhaṃ tīkṣṇoṣṇaṃ chedi bhedanam"},{"type":"verse","number":"230","sanskrit":"मेध्यं वह्निकरं हन्ति कफवातव्रणोदरम् कुष्ठार्शोग्रहणीगुल्मशोफानाहज्वरकृमीन् २.","text":"medhyaṃ vahnikaraṃ hanti kaphavātavraṇodaram kuṣṭhārśograhaṇīgulmaśophānāhajvarakṛmīn 2."},{"type":"verse","number":"231","sanskrit":"तन्मज्जा मधुरा वृष्या बृंहणी वातपित्तहा वृन्तमारुष्करं स्वादु पित्तघ्नं केश्यमग्निकृत्","text":"tanmajjā madhurā vṛṣyā bṛṃhaṇī vātapittahā vṛntamāruṣkaraṃ svādu pittaghnaṃ keśyamagnikṛt"},{"type":"verse","number":"232","sanskrit":"भल्लातकः कषायोष्णः शुक्रलो मधुरो लघुः वातश्लेष्मोदरानाहकुष्ठार्शोग्रहणीगदान् हन्ति गुल्मज्वरश्वित्रवह्निमान्द्यकृमिव्रणान्","text":"bhallātakaḥ kaṣāyoṣṇaḥ śukralo madhuro laghuḥ vātaśleṣmodarānāhakuṣṭhārśograhaṇīgadān hanti gulmajvaraśvitravahnimāndyakṛmivraṇān"},{"type":"verse","number":"233","sanskrit":"भङ्गा गञ्जा मातुलानी मादिनी विजया जया","text":"bhaṅgā gañjā mātulānī mādinī vijayā jayā"},{"type":"verse","number":"234","sanskrit":"भङ्गा कफ हरी तिक्ता ग्राहिणी पाचनी लघुः तीक्ष्णोष्णा पित्तला मोहमदवाग्वह्निवर्द्धिनी","text":"bhaṅgā kapha harī tiktā grāhiṇī pācanī laghuḥ tīkṣṇoṣṇā pittalā mohamadavāgvahnivarddhinī"},{"type":"verse","number":"235","sanskrit":"तिलभेदः खसतिलः खाखसश्चापि स स्मृतः स्यात् खाखसफलोद्भूतं वल्कलं शीतलं लघु","text":"tilabhedaḥ khasatilaḥ khākhasaścāpi sa smṛtaḥ syāt khākhasaphalodbhūtaṃ valkalaṃ śītalaṃ laghu"},{"type":"verse","number":"236","sanskrit":"ग्राहि तिक्तं कषायञ्च वातकृत् कफकासहृत्","text":"grāhi tiktaṃ kaṣāyañca vātakṛt kaphakāsahṛt"},{"type":"verse","number":"237","sanskrit":"धातूनां शोषकं रूक्षंमदकृद्वाग्विवर्धनम् मुहुर्मोहकरं रुच्यं सेवनात्पुंस्त्वनाशनम्","text":"dhātūnāṃ śoṣakaṃ rūkṣaṃmadakṛdvāgvivardhanam muhurmohakaraṃ rucyaṃ sevanātpuṃstvanāśanam"},{"type":"verse","number":"238","sanskrit":"उक्तं खसफलक्षीरमाफूकमहिफेनकम् आफूकं शोषणं ग्राहि श्लेष्मघ्नं वातपित्तलम् तथा खसफलोद्भूतवल्कलप्रायमित्यपि","text":"uktaṃ khasaphalakṣīramāphūkamahiphenakam āphūkaṃ śoṣaṇaṃ grāhi śleṣmaghnaṃ vātapittalam tathā khasaphalodbhūtavalkalaprāyamityapi"},{"type":"verse","number":"239","sanskrit":"उच्यन्ते खसबीजानि ते खाखसतिला अपि","text":"ucyante khasabījāni te khākhasatilā api"},{"type":"verse","number":"240","sanskrit":"खसबीजानिबल्यानि वृष्याणि सुगुरूणि च जनयन्ति कफं तानि शमयन्ति समीरणम् २.","text":"khasabījānibalyāni vṛṣyāṇi sugurūṇi ca janayanti kaphaṃ tāni śamayanti samīraṇam 2."},{"type":"verse","number":"241","sanskrit":"सैन्धवोऽस्त्री शीतशिवं मणिमन्थञ्च सिन्धुजम् सैन्धवं लवणं स्वादु दीपनं पाचनं लघु स्निग्धं रुच्यं हिमं वृष्यं सूक्ष्मं नेत्र्! यं त्रिदोषहृत्","text":"saindhavo'strī śītaśivaṃ maṇimanthañca sindhujam saindhavaṃ lavaṇaṃ svādu dīpanaṃ pācanaṃ laghu snigdhaṃ rucyaṃ himaṃ vṛṣyaṃ sūkṣmaṃ netr! yaṃ tridoṣahṛt"},{"type":"verse","number":"242","sanskrit":"शाकम्भरीयं कथितं गडाख्यं रोमकं तथा","text":"śākambharīyaṃ kathitaṃ gaḍākhyaṃ romakaṃ tathā"},{"type":"verse","number":"243","sanskrit":"गडाख्यं लघु वातघ्नमत्युष्णं भेदिपित्तलम् तीक्ष्णोष्णं चापि सूक्ष्मञ्चाभिष्यन्दिकटुपाकि च","text":"gaḍākhyaṃ laghu vātaghnamatyuṣṇaṃ bhedipittalam tīkṣṇoṣṇaṃ cāpi sūkṣmañcābhiṣyandikaṭupāki ca"},{"type":"verse","number":"244","sanskrit":"सामुद्रं यत्तुलवणमक्षीवं वशिरञ्च तत् समुद्र जं सागरजं लवणोदधिसम्भवम्","text":"sāmudraṃ yattulavaṇamakṣīvaṃ vaśirañca tat samudra jaṃ sāgarajaṃ lavaṇodadhisambhavam"},{"type":"verse","number":"245","sanskrit":"सामुद्रं मधुरं पाके सतिक्तं मधुरं गुरु नात्युष्णं दीपनं भेदि सक्षारमविदाहि च श्लेष्मलं वातनुत्तीक्ष्णमरूक्षं नातिशीतलम्","text":"sāmudraṃ madhuraṃ pāke satiktaṃ madhuraṃ guru nātyuṣṇaṃ dīpanaṃ bhedi sakṣāramavidāhi ca śleṣmalaṃ vātanuttīkṣṇamarūkṣaṃ nātiśītalam"},{"type":"verse","number":"246","sanskrit":"बिडं पाक्यञ्च कृतकं तथा द्रा विडमासुरम् बिडं सक्षारमूर्ध्वाधः कफवातानुलोमनम्","text":"biḍaṃ pākyañca kṛtakaṃ tathā drā viḍamāsuram biḍaṃ sakṣāramūrdhvādhaḥ kaphavātānulomanam"},{"type":"verse","number":"247","sanskrit":"दीपनं लघु तीक्ष्णोष्णं रूक्षं रुच्यं व्यवायि च विबन्धानाहविष्टम्भहृद्रुग्गौरवशूलनुत्","text":"dīpanaṃ laghu tīkṣṇoṣṇaṃ rūkṣaṃ rucyaṃ vyavāyi ca vibandhānāhaviṣṭambhahṛdruggauravaśūlanut"},{"type":"verse","number":"248","sanskrit":"सौवर्चलं स्याद्रुचकं मन्थपाकञ्च तन्मतम् रुचकं रोचनं भेदि दीपनं पाचनं परम्","text":"sauvarcalaṃ syādrucakaṃ manthapākañca tanmatam rucakaṃ rocanaṃ bhedi dīpanaṃ pācanaṃ param"},{"type":"verse","number":"249","sanskrit":"सस्नेहं वातनुन्नातिपित्तलं विशदं लघु उद्गारशुद्धिदं सूक्ष्मं विबन्धानाहशूलजित्","text":"sasnehaṃ vātanunnātipittalaṃ viśadaṃ laghu udgāraśuddhidaṃ sūkṣmaṃ vibandhānāhaśūlajit"},{"type":"verse","number":"250","sanskrit":"औद्भिदं पांशुलवणं यज्जातं भूमितः स्वयम् क्षारं गुरु कटु स्निग्धं शीतलं वातनाशनम् २.","text":"audbhidaṃ pāṃśulavaṇaṃ yajjātaṃ bhūmitaḥ svayam kṣāraṃ guru kaṭu snigdhaṃ śītalaṃ vātanāśanam 2."},{"type":"verse","number":"251","sanskrit":"चणकाम्लकमत्युष्णं दीपनं दन्तहर्षणम् लवणानुरसं रुच्यं शूलाजीर्णविबन्धनुत्","text":"caṇakāmlakamatyuṣṇaṃ dīpanaṃ dantaharṣaṇam lavaṇānurasaṃ rucyaṃ śūlājīrṇavibandhanut"},{"type":"verse","number":"252","sanskrit":"पाक्यं क्षारो यवक्षारो यावशूको यवाग्रजः स्वर्जिकाऽपि स्मृतः क्षारः कापोतः सुखवर्चकः","text":"pākyaṃ kṣāro yavakṣāro yāvaśūko yavāgrajaḥ svarjikā'pi smṛtaḥ kṣāraḥ kāpotaḥ sukhavarcakaḥ"},{"type":"verse","number":"253","sanskrit":"कथितः स्वर्जिकाभेदो विशेषज्ञैः सुवर्चिका यवक्षारो लघुः स्निग्धः सुसूक्ष्मो वह्निदीपनः","text":"kathitaḥ svarjikābhedo viśeṣajñaiḥ suvarcikā yavakṣāro laghuḥ snigdhaḥ susūkṣmo vahnidīpanaḥ"},{"type":"verse","number":"254","sanskrit":"निहन्ति शूलवातामश्लेष्मश्वासगलामयान् पाण्ड्वर्शोग्रहणीगुल्मानाहप्लीहहृदामयान्","text":"nihanti śūlavātāmaśleṣmaśvāsagalāmayān pāṇḍvarśograhaṇīgulmānāhaplīhahṛdāmayān"},{"type":"verse","number":"255","sanskrit":"स्वर्जिकाऽल्पगुणा तस्माद्विज्ञेया गुल्मशूलहृत् सुवर्चिका स्वर्जिकावद् बोद्धव्या गुणतो जनैः","text":"svarjikā'lpaguṇā tasmādvijñeyā gulmaśūlahṛt suvarcikā svarjikāvad boddhavyā guṇato janaiḥ"},{"type":"verse","number":"256","sanskrit":"सौभाग्यं टङ्कणं क्षारं धातुद्रा वकमुच्यते टङ्कणं वह्निकृद्रू क्षं कफहृद्वातपित्तकृत्","text":"saubhāgyaṃ ṭaṅkaṇaṃ kṣāraṃ dhātudrā vakamucyate ṭaṅkaṇaṃ vahnikṛdrū kṣaṃ kaphahṛdvātapittakṛt"},{"type":"verse","number":"257","sanskrit":"स्वर्जिका यावशूकश्च क्षारद्वयमुदाहृतम् टङ्कणेन युतं तत्तु क्षारत्रयमुदीरितम्","text":"svarjikā yāvaśūkaśca kṣāradvayamudāhṛtam ṭaṅkaṇena yutaṃ tattu kṣāratrayamudīritam"},{"type":"verse","number":"258","sanskrit":"मिलितं तूक्तगुणकृद्विशेषाद्गुल्महृत्परम् पलाश वज्रि शिखरि चिञ्चाऽकतिलनालजाः","text":"militaṃ tūktaguṇakṛdviśeṣādgulmahṛtparam palāśa vajri śikhari ciñcā'katilanālajāḥ"},{"type":"verse","number":"259","sanskrit":"यवजः स्वर्जिका चेति क्षाराष्टकमुदाहृतम् क्षारा एतेऽग्निना तुल्या गुल्मशूलहरा भृशम्","text":"yavajaḥ svarjikā ceti kṣārāṣṭakamudāhṛtam kṣārā ete'gninā tulyā gulmaśūlaharā bhṛśam"},{"type":"verse","number":"260","sanskrit":"चुक्रंसहस्रवेधि स्याद्र साम्लं शुक्तमित्यपि चुक्रमत्यम्लमुष्णञ्च दीपनं पाचनं परम् २.","text":"cukraṃsahasravedhi syādra sāmlaṃ śuktamityapi cukramatyamlamuṣṇañca dīpanaṃ pācanaṃ param 2."},{"type":"verse","number":"261","sanskrit":"शूलगुल्मविबन्धामवातश्लेष्महरं सरम् वमितृष्णाऽस्यवैरस्यहृत्पीडावह्निमान्द्यहृत्","text":"śūlagulmavibandhāmavātaśleṣmaharaṃ saram vamitṛṣṇā'syavairasyahṛtpīḍāvahnimāndyahṛt"}]},{"sthana":"Мадхьямакханда","number":2,"lang":"sa","content":[{"type":"heading","heading":"karpūrādi-варга — камфора и ароматические"},{"type":"verse","number":"1","sanskrit":"पुंसि क्लीबे च कर्पूरः सिताभ्रो हिमवालुकः घनसारश्चन्द्र संज्ञो हिमनामाऽपि स स्मृतः","text":"puṃsi klībe ca karpūraḥ sitābhro himavālukaḥ ghanasāraścandra saṃjño himanāmā'pi sa smṛtaḥ"},{"type":"verse","number":"2","sanskrit":"कर्पूरः शीतलो वृष्यश्चक्षुष्यो लेखनो लघुः सुरभिर्मधुरस्तिक्तः कफपित्तविषापहः","text":"karpūraḥ śītalo vṛṣyaścakṣuṣyo lekhano laghuḥ surabhirmadhurastiktaḥ kaphapittaviṣāpahaḥ"},{"type":"verse","number":"3","sanskrit":"कर्पूरो द्विविधः प्रोक्तः पक्वापक्वप्रभेदतः पक्वात्कर्पूरतः प्राहुरपक्वं गुणवत्तरम्","text":"karpūro dvividhaḥ proktaḥ pakvāpakvaprabhedataḥ pakvātkarpūrataḥ prāhurapakvaṃ guṇavattaram"},{"type":"verse","number":"4","sanskrit":"चीनाकसंज्ञः कर्पूरः कफक्षयकरः स्मृतः कुष्ठकण्डूवमिहरस्तथा तिक्तरसश्च सः","text":"cīnākasaṃjñaḥ karpūraḥ kaphakṣayakaraḥ smṛtaḥ kuṣṭhakaṇḍūvamiharastathā tiktarasaśca saḥ"},{"type":"verse","number":"5","sanskrit":"मृगनाभिर्मृगमदः कथितस्तु सहस्रभित् कस्तूरिका च कस्तूरी वेधमुख्या च सा स्मृता","text":"mṛganābhirmṛgamadaḥ kathitastu sahasrabhit kastūrikā ca kastūrī vedhamukhyā ca sā smṛtā"},{"type":"verse","number":"6","sanskrit":"कामरूपोद्भवा कृष्णा नैपाली नीलवर्णयुक् काश्मीरी कपिलच्छाया कस्तूरी त्रिविधा स्मृता","text":"kāmarūpodbhavā kṛṣṇā naipālī nīlavarṇayuk kāśmīrī kapilacchāyā kastūrī trividhā smṛtā"},{"type":"verse","number":"7","sanskrit":"कामरूपोद्भवा श्रेष्ठा नैपाली मध्यमा भवेत् काश्मीरदेशसम्भूता कस्तूरी ह्यधमा मता","text":"kāmarūpodbhavā śreṣṭhā naipālī madhyamā bhavet kāśmīradeśasambhūtā kastūrī hyadhamā matā"},{"type":"verse","number":"8","sanskrit":"कस्तूरिका कटुस्तिक्ता क्षारोष्णा शुक्रला गुरुः कफवातविषच्छर्दिशीतदौर्गन्ध्यशोषहृत्","text":"kastūrikā kaṭustiktā kṣāroṣṇā śukralā guruḥ kaphavātaviṣacchardiśītadaurgandhyaśoṣahṛt"},{"type":"verse","number":"9","sanskrit":"लता कस्तूरिका तिक्ता स्वाद्वी वृष्या हिमा लघुः चक्षुष्या छेदिनी श्लेष्मतृष्णाबस्त्यास्यरोगहृत्","text":"latā kastūrikā tiktā svādvī vṛṣyā himā laghuḥ cakṣuṣyā chedinī śleṣmatṛṣṇābastyāsyarogahṛt"},{"type":"verse","number":"10","sanskrit":"गन्धमार्जारवीर्यन्तु वीर्यकृत्कफवातहृत् कण्डूकुष्ठहरं नेत्र्! यं सुगन्धं स्वेदगन्धनुत् ३.","text":"gandhamārjāravīryantu vīryakṛtkaphavātahṛt kaṇḍūkuṣṭhaharaṃ netr! yaṃ sugandhaṃ svedagandhanut 3."},{"type":"verse","number":"11","sanskrit":"श्रीखण्डं चन्दनं न स्त्री भद्र श्रीस्तैलपर्णिकः गन्धसारो मलजयस्तथा चन्द्र द्युतिश्च सः","text":"śrīkhaṇḍaṃ candanaṃ na strī bhadra śrīstailaparṇikaḥ gandhasāro malajayastathā candra dyutiśca saḥ"},{"type":"verse","number":"12","sanskrit":"स्वादे तिक्तं कषे पीतं छेदे रक्तं तनौ सितम् ग्रन्थिकोटरसंयुक्तं चन्दनं श्रेष्ठमुच्यते","text":"svāde tiktaṃ kaṣe pītaṃ chede raktaṃ tanau sitam granthikoṭarasaṃyuktaṃ candanaṃ śreṣṭhamucyate"},{"type":"verse","number":"13","sanskrit":"चन्दनं शीतलं रूक्षं तिक्तमाह्लादनं लघु श्रमशोषविषश्लेष्मतृष्णापित्तास्रदाहनुत्","text":"candanaṃ śītalaṃ rūkṣaṃ tiktamāhlādanaṃ laghu śramaśoṣaviṣaśleṣmatṛṣṇāpittāsradāhanut"},{"type":"verse","number":"14","sanskrit":"कालीयकं तु कालीयं पीताभं हरिचन्दनम्","text":"kālīyakaṃ tu kālīyaṃ pītābhaṃ haricandanam"},{"type":"verse","number":"15","sanskrit":"हरिप्रियं कालसारं तथा कालानुसार्यकम् कालीयकं रक्तगुणं विशेषाद् व्यङ्गनाशनम्","text":"haripriyaṃ kālasāraṃ tathā kālānusāryakam kālīyakaṃ raktaguṇaṃ viśeṣād vyaṅganāśanam"},{"type":"verse","number":"16","sanskrit":"रक्तचन्दनमाख्यातं रक्ताङ्गं क्षुद्र चन्दनम् तिलपर्णं रक्तसारं तत्प्रवालफलं स्मृतम्","text":"raktacandanamākhyātaṃ raktāṅgaṃ kṣudra candanam tilaparṇaṃ raktasāraṃ tatpravālaphalaṃ smṛtam"},{"type":"verse","number":"17","sanskrit":"रक्तं शीतं गुरु स्वादुच्छर्दितृष्णाऽस्रपित्तहृत् तिक्तं नेत्रहितं वृष्यं ज्वरव्रणविषापहम्","text":"raktaṃ śītaṃ guru svāduccharditṛṣṇā'srapittahṛt tiktaṃ netrahitaṃ vṛṣyaṃ jvaravraṇaviṣāpaham"},{"type":"verse","number":"18","sanskrit":"पतङ्गं रक्तसारञ्च सुरङ्गं रञ्जनं तथा पट्टरञ्जकमाख्यातं पत्तूरञ्च कुचन्दनम्","text":"pataṅgaṃ raktasārañca suraṅgaṃ rañjanaṃ tathā paṭṭarañjakamākhyātaṃ pattūrañca kucandanam"},{"type":"verse","number":"19","sanskrit":"पतङ्गं मधुरं शीतं पित्तश्लेष्मव्रणास्रनुत् हरिचन्दनवद्वेद्यं विशेषाद्दाहनाशनम्","text":"pataṅgaṃ madhuraṃ śītaṃ pittaśleṣmavraṇāsranut haricandanavadvedyaṃ viśeṣāddāhanāśanam"},{"type":"verse","number":"20","sanskrit":"चन्दनानि तु सर्वाणि सदृशानि रसादिभिः गन्धेन तु विशेषोऽस्ति पूर्वः श्रेष्ठतमो गुणैः ३.","text":"candanāni tu sarvāṇi sadṛśāni rasādibhiḥ gandhena tu viśeṣo'sti pūrvaḥ śreṣṭhatamo guṇaiḥ 3."},{"type":"verse","number":"21","sanskrit":"अगुरु प्रवरं लोहं राजार्हं योगजं तथा वंशिकं कृमिजं वाऽपि कृमिजग्धमनार्यकम्","text":"aguru pravaraṃ lohaṃ rājārhaṃ yogajaṃ tathā vaṃśikaṃ kṛmijaṃ vā'pi kṛmijagdhamanāryakam"},{"type":"verse","number":"22","sanskrit":"अगुरूष्णं कटु त्वच्यं तिक्तं तीक्ष्णञ्च पित्तलम् लघु कर्णाक्षिरोगघ्नं शीतवातकफप्रणुत्","text":"agurūṣṇaṃ kaṭu tvacyaṃ tiktaṃ tīkṣṇañca pittalam laghu karṇākṣirogaghnaṃ śītavātakaphapraṇut"},{"type":"verse","number":"23","sanskrit":"कृष्णं गुणाधिकं तत्तु लोहवद्वारि मज्जति अगुरुप्रभवः स्नेहः कृष्णागुरुसमः स्मृतः","text":"kṛṣṇaṃ guṇādhikaṃ tattu lohavadvāri majjati aguruprabhavaḥ snehaḥ kṛṣṇāgurusamaḥ smṛtaḥ"},{"type":"verse","number":"24","sanskrit":"देवदारु स्मृतं दारुभद्रं दार्विन्द्र दारु च मस्तदारु द्रुकिलिमं किलिमं सुरभूरुहः","text":"devadāru smṛtaṃ dārubhadraṃ dārvindra dāru ca mastadāru drukilimaṃ kilimaṃ surabhūruhaḥ"},{"type":"verse","number":"25","sanskrit":"देवदारु लघु स्निग्धं तिक्तोष्णं कटुपाकि च विबन्धाध्मानशोथामतन्द्रा हिक्काज्वरास्रजित् प्रमेहपीनसश्लेष्मकासकण्डूसमीरनुत्","text":"devadāru laghu snigdhaṃ tiktoṣṇaṃ kaṭupāki ca vibandhādhmānaśothāmatandrā hikkājvarāsrajit pramehapīnasaśleṣmakāsakaṇḍūsamīranut"},{"type":"verse","number":"26","sanskrit":"सरलः पीतवृक्षः स्यात्तथा सुरभिदारुकः सरलो मधुरस्तिक्तो कटुपाकरसो लघुः","text":"saralaḥ pītavṛkṣaḥ syāttathā surabhidārukaḥ saralo madhurastikto kaṭupākaraso laghuḥ"},{"type":"verse","number":"27","sanskrit":"स्निग्धोष्णः कर्णकण्ठाक्षिरोगरक्षोहरः स्मृतः कफानिलस्वेददाहकासमूर्छाव्रणापहः","text":"snigdhoṣṇaḥ karṇakaṇṭhākṣirogarakṣoharaḥ smṛtaḥ kaphānilasvedadāhakāsamūrchāvraṇāpahaḥ"},{"type":"verse","number":"28","sanskrit":"कालानुसार्यं तगरं कुटिलं नहुषं नतम् अपरं पिण्डतगरं दण्डहस्ती च बर्हिणम्","text":"kālānusāryaṃ tagaraṃ kuṭilaṃ nahuṣaṃ natam aparaṃ piṇḍatagaraṃ daṇḍahastī ca barhiṇam"},{"type":"verse","number":"29","sanskrit":"तगरद्वयमुष्णं स्यात्स्वादु स्निग्धं लघु स्मृतम् विषापस्मारशूलाक्षिरोगदोषत्रयापहम्","text":"tagaradvayamuṣṇaṃ syātsvādu snigdhaṃ laghu smṛtam viṣāpasmāraśūlākṣirogadoṣatrayāpaham"},{"type":"verse","number":"30","sanskrit":"पद्मकं पद्मगन्धि स्यात्तथा पद्माह्वयं स्मृतम् पद्मकं तुवरं तिक्तं शीतलं वातलं लघु ३.","text":"padmakaṃ padmagandhi syāttathā padmāhvayaṃ smṛtam padmakaṃ tuvaraṃ tiktaṃ śītalaṃ vātalaṃ laghu 3."},{"type":"verse","number":"31","sanskrit":"गर्भसंस्थापनं रुच्यं वमिव्रणतृषाप्रणुत्","text":"garbhasaṃsthāpanaṃ rucyaṃ vamivraṇatṛṣāpraṇut"},{"type":"verse","number":"32","sanskrit":"गुग्गुलर्देवधूपश्च जटायुः कौशिकः पुरः कुम्भोलूखलकं क्लीबे महिषाक्षः पलङ्कषः","text":"guggulardevadhūpaśca jaṭāyuḥ kauśikaḥ puraḥ kumbholūkhalakaṃ klībe mahiṣākṣaḥ palaṅkaṣaḥ"},{"type":"verse","number":"33","sanskrit":"महिषाक्षो महानीलः कुमुदः पद्म इत्यपि हिरण्यः पञ्चमो ज्ञेयो गुग्गुलोः पञ्च जातयः","text":"mahiṣākṣo mahānīlaḥ kumudaḥ padma ityapi hiraṇyaḥ pañcamo jñeyo gugguloḥ pañca jātayaḥ"},{"type":"verse","number":"34","sanskrit":"भृङ्गाञ्जनसवर्णस्तु महिषाक्ष इति स्मृतः महानीलस्तु विज्ञेयः स्वनामसमलक्षणः","text":"bhṛṅgāñjanasavarṇastu mahiṣākṣa iti smṛtaḥ mahānīlastu vijñeyaḥ svanāmasamalakṣaṇaḥ"},{"type":"verse","number":"35","sanskrit":"कुमुदः कुमुदाभः स्यात्पद्मो माणिक्यसन्निभः हिरण्याख्यस्तु हेमाभः पञ्चानां लिङ्गमीरितम्","text":"kumudaḥ kumudābhaḥ syātpadmo māṇikyasannibhaḥ hiraṇyākhyastu hemābhaḥ pañcānāṃ liṅgamīritam"},{"type":"verse","number":"36","sanskrit":"महिषाक्षो महानीलो गजेन्द्रा णां हितावुभौ हयानां कुमुदः पद्मः स्वस्त्यारोग्यकरौ परौ","text":"mahiṣākṣo mahānīlo gajendrā ṇāṃ hitāvubhau hayānāṃ kumudaḥ padmaḥ svastyārogyakarau parau"},{"type":"verse","number":"37","sanskrit":"विशेषेण मनुष्याणां कनकः परिकीर्त्तितः कदाचिन्महिषाक्षश्च मतः कैश्चिन्नृणामपि","text":"viśeṣeṇa manuṣyāṇāṃ kanakaḥ parikīrttitaḥ kadācinmahiṣākṣaśca mataḥ kaiścinnṛṇāmapi"},{"type":"verse","number":"38","sanskrit":"गुग्गुलुर्विशदस्तिक्तो वीर्योष्णः पित्तलः सरः कषायः कटुकः पाके कटू रूक्षो लघुः परः","text":"guggulurviśadastikto vīryoṣṇaḥ pittalaḥ saraḥ kaṣāyaḥ kaṭukaḥ pāke kaṭū rūkṣo laghuḥ paraḥ"},{"type":"verse","number":"39","sanskrit":"भग्नसन्धानकृद् वृष्यः सूक्ष्मः स्वर्यो रसायनः दीपनः पिच्छिलो बल्यः कफवातव्रणापचीः","text":"bhagnasandhānakṛd vṛṣyaḥ sūkṣmaḥ svaryo rasāyanaḥ dīpanaḥ picchilo balyaḥ kaphavātavraṇāpacīḥ"},{"type":"verse","number":"40","sanskrit":"मेदोमेहाश्मवातांश्च क्लेदकुष्ठाममारुतान् पिडकाग्रन्थिशोफार्श्गण्डमालाकृमीञ्जयेत् ३.","text":"medomehāśmavātāṃśca kledakuṣṭhāmamārutān piḍakāgranthiśophārśgaṇḍamālākṛmīñjayet 3."},{"type":"verse","number":"41","sanskrit":"माधुर्याच्छमयेद्वातं कषायत्वाच्च पित्तहा तिक्तत्वाद् कफजित्तेन गुग्गुलुः सर्वदोषहा","text":"mādhuryācchamayedvātaṃ kaṣāyatvācca pittahā tiktatvād kaphajittena gugguluḥ sarvadoṣahā"},{"type":"verse","number":"42","sanskrit":"स नवो बृंहणो वृष्यः पुराणस्त्वतिलेखनः","text":"sa navo bṛṃhaṇo vṛṣyaḥ purāṇastvatilekhanaḥ"},{"type":"verse","number":"43","sanskrit":"स्निग्धः काञ्चनसङ्काशः पक्वजम्बूफलोपमः नूतनो गुग्गुलुः प्रोक्तः सुगन्धिर्यस्तु पिच्छिलः","text":"snigdhaḥ kāñcanasaṅkāśaḥ pakvajambūphalopamaḥ nūtano gugguluḥ proktaḥ sugandhiryastu picchilaḥ"},{"type":"verse","number":"44","sanskrit":"शुष्को दुर्गन्धकश्चैव त्यक्तप्रकृतिवर्णकः पुराणः स तु विज्ञेयो गुग्गुलुर्वीर्यवर्जितः","text":"śuṣko durgandhakaścaiva tyaktaprakṛtivarṇakaḥ purāṇaḥ sa tu vijñeyo guggulurvīryavarjitaḥ"},{"type":"verse","number":"45","sanskrit":"अम्लं तीक्ष्णमजीर्णञ्च व्यवायं श्रममातपम् मद्यं रोषं त्यजेत्सम्यग् गुणार्थी पुरसेवकः","text":"amlaṃ tīkṣṇamajīrṇañca vyavāyaṃ śramamātapam madyaṃ roṣaṃ tyajetsamyag guṇārthī purasevakaḥ"},{"type":"verse","number":"46","sanskrit":"श्रीवासः सरलस्रावः श्रीवेष्टो वृक्षधूपकः श्रीवासो मधुरस्तिक्तः स्निग्धोष्णस्तुवरः सरः","text":"śrīvāsaḥ saralasrāvaḥ śrīveṣṭo vṛkṣadhūpakaḥ śrīvāso madhurastiktaḥ snigdhoṣṇastuvaraḥ saraḥ"},{"type":"verse","number":"47","sanskrit":"पित्तलो वातमूर्द्धाक्षिस्वररोगकफापहः रक्षोघ्नः स्वेददौर्गन्ध्ययूकाकण्डूव्रणप्रणुत्","text":"pittalo vātamūrddhākṣisvararogakaphāpahaḥ rakṣoghnaḥ svedadaurgandhyayūkākaṇḍūvraṇapraṇut"},{"type":"verse","number":"48","sanskrit":"रालस्तु शालनिर्यासस्तथा सर्ज्जरसः स्मृतः देवधूपो यक्षधूपस्तथा सर्वरसश्च सः","text":"rālastu śālaniryāsastathā sarjjarasaḥ smṛtaḥ devadhūpo yakṣadhūpastathā sarvarasaśca saḥ"},{"type":"verse","number":"49","sanskrit":"रालो हिमो गुरुस्तिक्तः कषायो ग्राहको हरेत् दोषास्रस्वेदवीसर्पज्वरव्रणविपादिकाः ग्रहभग्नाग्निदग्धांश्च शूलातीसारनाशनः","text":"rālo himo gurustiktaḥ kaṣāyo grāhako haret doṣāsrasvedavīsarpajvaravraṇavipādikāḥ grahabhagnāgnidagdhāṃśca śūlātīsāranāśanaḥ"},{"type":"verse","number":"50","sanskrit":"कुन्दुरुस्तु मुकुन्दः स्यात्सुगन्धः कुन्द इत्यपि ३.","text":"kundurustu mukundaḥ syātsugandhaḥ kunda ityapi 3."},{"type":"verse","number":"51","sanskrit":"कुन्दुरुर्मधुरस्तिक्तस्तीक्ष्णस्त्वच्यः कटुर्हरेत् ज्वरस्वेदग्रहालक्ष्मीमुखरोगकफानिलान्","text":"kundururmadhurastiktastīkṣṇastvacyaḥ kaṭurharet jvarasvedagrahālakṣmīmukharogakaphānilān"},{"type":"verse","number":"52","sanskrit":"सिह्लकस्तु तुरुष्कः स्याद्यतो यवनदेशजः कपितैलश्च संख्यातस्तथा च कपिनामकः","text":"sihlakastu turuṣkaḥ syādyato yavanadeśajaḥ kapitailaśca saṃkhyātastathā ca kapināmakaḥ"},{"type":"verse","number":"53","sanskrit":"सिह्लकःकटुकःस्वादुः स्निग्धोष्णःशुक्रकान्तिकृत् वृष्यः कण्ठ्यः स्वेदकुष्ठज्वरदाहग्रहापहः","text":"sihlakaḥkaṭukaḥsvāduḥ snigdhoṣṇaḥśukrakāntikṛt vṛṣyaḥ kaṇṭhyaḥ svedakuṣṭhajvaradāhagrahāpahaḥ"},{"type":"verse","number":"54","sanskrit":"जातीफलं जातिकोशं मालतीफलमित्यपि जातीफलं रसे तिक्तं तीक्ष्णोष्णं रोचनं लघु कटुकं दीपनं ग्राहि स्वर्यं श्लेष्मानिलापहम्","text":"jātīphalaṃ jātikośaṃ mālatīphalamityapi jātīphalaṃ rase tiktaṃ tīkṣṇoṣṇaṃ rocanaṃ laghu kaṭukaṃ dīpanaṃ grāhi svaryaṃ śleṣmānilāpaham"},{"type":"verse","number":"55","sanskrit":"निहन्ति मुखवैरस्यं मलदौर्गन्ध्यकृष्णताः कृमिकासवमिश्वासशोषपीनसहृद्रुजः","text":"nihanti mukhavairasyaṃ maladaurgandhyakṛṣṇatāḥ kṛmikāsavamiśvāsaśoṣapīnasahṛdrujaḥ"},{"type":"verse","number":"56","sanskrit":"जातीफलस्य त्वक् प्रोक्ता जातीपत्री भिषग्वरैः","text":"jātīphalasya tvak proktā jātīpatrī bhiṣagvaraiḥ"},{"type":"verse","number":"57","sanskrit":"जातीपत्री लघुः स्वादुः कटूष्णा रुचिवर्णकृत् कफकासवमिश्वासतृष्णाकृमिविषापहा","text":"jātīpatrī laghuḥ svāduḥ kaṭūṣṇā rucivarṇakṛt kaphakāsavamiśvāsatṛṣṇākṛmiviṣāpahā"},{"type":"verse","number":"58","sanskrit":"लवङ्गं देवकुसुमं श्रीसंज्ञं श्रीप्रसूनकम् लवङ्गं कटुकं तिक्तं लघु नेत्रहितं हिमम्","text":"lavaṅgaṃ devakusumaṃ śrīsaṃjñaṃ śrīprasūnakam lavaṅgaṃ kaṭukaṃ tiktaṃ laghu netrahitaṃ himam"},{"type":"verse","number":"59","sanskrit":"दीपनं पाचनं रुच्यं कफपित्तास्रनाशकृत् तृष्णां छर्दिं तथाऽध्मानं शूलमाशु विनाशयेत् कासं श्वासञ्च हिक्काञ्च क्षयं क्षपयति ध्रुवम्","text":"dīpanaṃ pācanaṃ rucyaṃ kaphapittāsranāśakṛt tṛṣṇāṃ chardiṃ tathā'dhmānaṃ śūlamāśu vināśayet kāsaṃ śvāsañca hikkāñca kṣayaṃ kṣapayati dhruvam"},{"type":"verse","number":"60","sanskrit":"एला स्थूला च बहुला पृथ्वीका त्रिपुटाऽपि च ३.","text":"elā sthūlā ca bahulā pṛthvīkā tripuṭā'pi ca 3."},{"type":"verse","number":"61","sanskrit":"भद्रै ला बृहदेला च चन्द्र बाला च निष्कुटिः स्थूलैला कटुका पाके रसे चानलकृल्लघुः","text":"bhadrai lā bṛhadelā ca candra bālā ca niṣkuṭiḥ sthūlailā kaṭukā pāke rase cānalakṛllaghuḥ"},{"type":"verse","number":"62","sanskrit":"रूक्षोष्णा श्लेष्मपित्तास्रकण्डूश्वासतृषाऽपहा हृल्लासविषबस्त्यास्यशिरोरुग्वमिकासनुत्","text":"rūkṣoṣṇā śleṣmapittāsrakaṇḍūśvāsatṛṣā'pahā hṛllāsaviṣabastyāsyaśirorugvamikāsanut"},{"type":"verse","number":"63","sanskrit":"सूक्ष्मोपकुञ्चिका तुत्था कोरङ्गी द्रा विडी त्रुटिः एला सूक्ष्मा कफश्वासकासार्शोमूत्रकृच्छ्रहृत् रसे तु कटुका शीता लघ्वी वातहरी मता","text":"sūkṣmopakuñcikā tutthā koraṅgī drā viḍī truṭiḥ elā sūkṣmā kaphaśvāsakāsārśomūtrakṛcchrahṛt rase tu kaṭukā śītā laghvī vātaharī matā"},{"type":"verse","number":"64","sanskrit":"त्वक्पत्रञ्च वराङ्गं स्याद् भृङ्गं चोचं तथोत्कटम् त्वचं लघूष्णं कटुकं स्वादु तिक्तञ्च रूक्षकम्","text":"tvakpatrañca varāṅgaṃ syād bhṛṅgaṃ cocaṃ tathotkaṭam tvacaṃ laghūṣṇaṃ kaṭukaṃ svādu tiktañca rūkṣakam"},{"type":"verse","number":"65","sanskrit":"पित्तलं कफवातघ्नं कण्ड्वामारुचिनाशनम् हृद्बस्तिरोगवातार्शः कृमिपीनसशुक्रहृत्","text":"pittalaṃ kaphavātaghnaṃ kaṇḍvāmārucināśanam hṛdbastirogavātārśaḥ kṛmipīnasaśukrahṛt"},{"type":"verse","number":"66","sanskrit":"त्वक्स्वाद्वी तु तनुत्वक्स्यात्तथा दारुसिता मता","text":"tvaksvādvī tu tanutvaksyāttathā dārusitā matā"},{"type":"verse","number":"67","sanskrit":"उक्ता दारुसिता स्वाद्वी तिक्ताचानिलपित्तहृत् सुरभिः शुक्रलाबल्या मुखशोषतृषापहा","text":"uktā dārusitā svādvī tiktācānilapittahṛt surabhiḥ śukralābalyā mukhaśoṣatṛṣāpahā"},{"type":"verse","number":"68","sanskrit":"पत्रं तमालपत्रञ्च तथा स्यात्पत्रनामकम् पत्रकं मधुरं किञ्चित्तीक्ष्णोष्णं पिच्छिलं लघु निहन्ति कफवातार्शोहृल्लासारुचिपीनसान्","text":"patraṃ tamālapatrañca tathā syātpatranāmakam patrakaṃ madhuraṃ kiñcittīkṣṇoṣṇaṃ picchilaṃ laghu nihanti kaphavātārśohṛllāsārucipīnasān"},{"type":"verse","number":"69","sanskrit":"नागपुष्प स्मृतो नागः केशरो नागकेशरः चाम्पेयो नागकिञ्जल्कः कथितः काञ्चनाह्वयः","text":"nāgapuṣpa smṛto nāgaḥ keśaro nāgakeśaraḥ cāmpeyo nāgakiñjalkaḥ kathitaḥ kāñcanāhvayaḥ"},{"type":"verse","number":"70","sanskrit":"नागपुष्पं कषायोष्णं रूक्षं लघ्वामपाचनम् ३.","text":"nāgapuṣpaṃ kaṣāyoṣṇaṃ rūkṣaṃ laghvāmapācanam 3."},{"type":"verse","number":"71","sanskrit":"दौर्गन्ध्यकुष्ठवीसर्पकफपित्तविषापहम्","text":"daurgandhyakuṣṭhavīsarpakaphapittaviṣāpaham"},{"type":"verse","number":"72","sanskrit":"त्वगेलापत्रकैस्तुल्यैस्त्रिसुगन्धि त्रिजातकम् नागकेशरसंयुक्तं चातुर्जातकमुच्यते","text":"tvagelāpatrakaistulyaistrisugandhi trijātakam nāgakeśarasaṃyuktaṃ cāturjātakamucyate"},{"type":"verse","number":"73","sanskrit":"तद् द्वयं रोचनं रूक्षं तीक्ष्णोष्णं मुखगन्धहृत् लघुपित्ताग्निकृद्वर्ण्यं कफवातविषापहम्","text":"tad dvayaṃ rocanaṃ rūkṣaṃ tīkṣṇoṣṇaṃ mukhagandhahṛt laghupittāgnikṛdvarṇyaṃ kaphavātaviṣāpaham"},{"type":"verse","number":"74","sanskrit":"कुङ्कुमं घुसृणं रक्तं काश्मीरं पीतकं वरम् संकोचं पिशुनं धीरं बाह्लीकं शोणिताभिधम्","text":"kuṅkumaṃ ghusṛṇaṃ raktaṃ kāśmīraṃ pītakaṃ varam saṃkocaṃ piśunaṃ dhīraṃ bāhlīkaṃ śoṇitābhidham"},{"type":"verse","number":"75","sanskrit":"काश्मीरदेशजे क्षेत्रे कुङ्कुमं यद्भवेद्धि तत् सूक्ष्मकेशरमारक्तं पद्मगन्धि तदुत्तमम्","text":"kāśmīradeśaje kṣetre kuṅkumaṃ yadbhaveddhi tat sūkṣmakeśaramāraktaṃ padmagandhi taduttamam"},{"type":"verse","number":"76","sanskrit":"बाह्लीकदेशसञ्जातं कुङ्कुमं पाण्डुरं स्मृतम् केतकीगन्धयुक्तं तन्मध्यमं सूक्ष्मकेशरम्","text":"bāhlīkadeśasañjātaṃ kuṅkumaṃ pāṇḍuraṃ smṛtam ketakīgandhayuktaṃ tanmadhyamaṃ sūkṣmakeśaram"},{"type":"verse","number":"77","sanskrit":"कुङ्कुमं पारसीकं यन्मधुगन्धि तदीरितम् ईषत्पाण्डुरवर्णं तदधमं स्थूलकेशरम्","text":"kuṅkumaṃ pārasīkaṃ yanmadhugandhi tadīritam īṣatpāṇḍuravarṇaṃ tadadhamaṃ sthūlakeśaram"},{"type":"verse","number":"78","sanskrit":"कुङ्कुमं कटुकं स्निग्धं शिरोरुग्व्रणजन्तुजित् तिक्तं वमिहरं वर्ण्यं व्यङ्गदोषत्रयापहम्","text":"kuṅkumaṃ kaṭukaṃ snigdhaṃ śirorugvraṇajantujit tiktaṃ vamiharaṃ varṇyaṃ vyaṅgadoṣatrayāpaham"},{"type":"verse","number":"79","sanskrit":"गोरोचना तु मङ्गल्या वन्द्या गौरी च रोचना गोरोचना हिमा तिक्ता वश्या मङ्गलकान्तिदा विषालक्ष्मीग्रहोन्मादगर्भस्रावक्षतास्रहृत्","text":"gorocanā tu maṅgalyā vandyā gaurī ca rocanā gorocanā himā tiktā vaśyā maṅgalakāntidā viṣālakṣmīgrahonmādagarbhasrāvakṣatāsrahṛt"},{"type":"verse","number":"80","sanskrit":"नखं व्याघ्रनखं व्याघ्रायुधं तच्चक्रकारकम् ३.","text":"nakhaṃ vyāghranakhaṃ vyāghrāyudhaṃ taccakrakārakam 3."},{"type":"verse","number":"81","sanskrit":"नखं स्वल्पं नखी प्रोक्ता हनुर्हट्टविलासिनी नखद्वयं ग्रहश्लेष्मवातास्रज्वरकुष्ठहृत्","text":"nakhaṃ svalpaṃ nakhī proktā hanurhaṭṭavilāsinī nakhadvayaṃ grahaśleṣmavātāsrajvarakuṣṭhahṛt"},{"type":"verse","number":"82","sanskrit":"लघूष्णं शुक्रलं वर्ण्यं स्वादु व्रणविषापहम् अलक्ष्मीमुखदौर्गन्ध्यहृत्पाकरसयोः कटुः","text":"laghūṣṇaṃ śukralaṃ varṇyaṃ svādu vraṇaviṣāpaham alakṣmīmukhadaurgandhyahṛtpākarasayoḥ kaṭuḥ"},{"type":"verse","number":"83","sanskrit":"बालं ह्रीबेरबर्हिष्ठोदीच्यं केशाम्बुनाम च बालकं शीतलं रूक्षं लघु दीपनपाचनम् हृल्लासारुचिवीसर्पहृद्रो गामातिसारजित्","text":"bālaṃ hrīberabarhiṣṭhodīcyaṃ keśāmbunāma ca bālakaṃ śītalaṃ rūkṣaṃ laghu dīpanapācanam hṛllāsārucivīsarpahṛdro gāmātisārajit"},{"type":"verse","number":"84","sanskrit":"स्याद्वीरणं वीरतरुर्वीरञ्च बहुमूलकम् वीरणं पाचनं शीतं वान्तिहृल्लघु तिक्तकम्","text":"syādvīraṇaṃ vīratarurvīrañca bahumūlakam vīraṇaṃ pācanaṃ śītaṃ vāntihṛllaghu tiktakam"},{"type":"verse","number":"85","sanskrit":"स्तम्भनं ज्वरनुद् भ्रान्तिमदजित्कफपित्तहृत् तृष्णाऽस्रविषवीसर्पकृच्छ्रदाहव्रणापहम्","text":"stambhanaṃ jvaranud bhrāntimadajitkaphapittahṛt tṛṣṇā'sraviṣavīsarpakṛcchradāhavraṇāpaham"},{"type":"verse","number":"86","sanskrit":"वीरणस्य तु मूलं स्यादुशीरं नलदञ्च तत् अमृणालञ्च सेव्यञ्च समगन्धिकमित्यपि","text":"vīraṇasya tu mūlaṃ syāduśīraṃ naladañca tat amṛṇālañca sevyañca samagandhikamityapi"},{"type":"verse","number":"87","sanskrit":"उशीरं पाचनं शीतं स्तम्भनं लघु तिक्तकम्","text":"uśīraṃ pācanaṃ śītaṃ stambhanaṃ laghu tiktakam"},{"type":"verse","number":"88","sanskrit":"मधुरं ज्वरहृद्वान्तिमदनुत्कफपित्तहृत् तृष्णाऽस्रविषवीसर्पदाहकृच्छ्र्रवणापहम्","text":"madhuraṃ jvarahṛdvāntimadanutkaphapittahṛt tṛṣṇā'sraviṣavīsarpadāhakṛcchrravaṇāpaham"},{"type":"verse","number":"89","sanskrit":"जटामांसी भूतजटा जटिला च तपस्विनी मांसी तिक्ता कषाया च मेध्या कान्तिबलप्रदा स्वाद्वी हिमा त्रिदोषास्रदाहवीसर्पकुष्ठनुत्","text":"jaṭāmāṃsī bhūtajaṭā jaṭilā ca tapasvinī māṃsī tiktā kaṣāyā ca medhyā kāntibalapradā svādvī himā tridoṣāsradāhavīsarpakuṣṭhanut"},{"type":"verse","number":"90","sanskrit":"शैलेयन्तु शिलापुष्पं वृद्धं कालानुसार्य्यकम् ३.","text":"śaileyantu śilāpuṣpaṃ vṛddhaṃ kālānusāryyakam 3."},{"type":"verse","number":"91","sanskrit":"शैलेयं शीतलं हृद्यं कफपित्तहरं लघु कण्डूकुष्ठाश्मरीदाहविष हृद् गुदरक्तहृत्","text":"śaileyaṃ śītalaṃ hṛdyaṃ kaphapittaharaṃ laghu kaṇḍūkuṣṭhāśmarīdāhaviṣa hṛd gudaraktahṛt"},{"type":"verse","number":"92","sanskrit":"मुस्तकं न स्त्रियां मुस्तं त्रिषु वारिदनामकम् कुरुविन्दश्च संख्यातोऽपरः क्रोडकसेरुकः","text":"mustakaṃ na striyāṃ mustaṃ triṣu vāridanāmakam kuruvindaśca saṃkhyāto'paraḥ kroḍakaserukaḥ"},{"type":"verse","number":"93","sanskrit":"भद्र मुस्तञ्च गुन्द्रा च तथा नागरमुस्तकः मुस्तं कटु हिमं ग्राहि तिक्तं दीपनपाचनम्","text":"bhadra mustañca gundrā ca tathā nāgaramustakaḥ mustaṃ kaṭu himaṃ grāhi tiktaṃ dīpanapācanam"},{"type":"verse","number":"94","sanskrit":"कषायं कफपित्तास्रतृड्ज्वरारुचिजन्तुहृत् अनूपदेशे यज्जातं मुस्तकं तत्प्रशस्यते तत्रापि मुनिभिः प्रोक्तं वरं नागरमुस्तकम्","text":"kaṣāyaṃ kaphapittāsratṛḍjvarārucijantuhṛt anūpadeśe yajjātaṃ mustakaṃ tatpraśasyate tatrāpi munibhiḥ proktaṃ varaṃ nāgaramustakam"},{"type":"verse","number":"95","sanskrit":"कर्चूरो वेधमुख्यश्च द्रा विडः कल्पकः शटी कर्चुरो दीपनो रुच्यः कटुकस्तिक्त एव च","text":"karcūro vedhamukhyaśca drā viḍaḥ kalpakaḥ śaṭī karcuro dīpano rucyaḥ kaṭukastikta eva ca"},{"type":"verse","number":"96","sanskrit":"सुगन्धिः कटुपाकः स्यात्कुष्ठार्शोव्रणकासनुत् उष्णो लघुर्हरेछ्वासं गुल्मवातकफकृमीन्","text":"sugandhiḥ kaṭupākaḥ syātkuṣṭhārśovraṇakāsanut uṣṇo laghurharechvāsaṃ gulmavātakaphakṛmīn"},{"type":"verse","number":"97","sanskrit":"मुरा गन्धकुटी दैत्या सुरभिः शालपर्णिका","text":"murā gandhakuṭī daityā surabhiḥ śālaparṇikā"},{"type":"verse","number":"98","sanskrit":"मुरा तिक्ता हिमा स्वाद्वी लघ्वी पित्तानिलापहा ज्वरासृग्भूतरक्षोघ्नी कुष्ठकासविनाशिनी","text":"murā tiktā himā svādvī laghvī pittānilāpahā jvarāsṛgbhūtarakṣoghnī kuṣṭhakāsavināśinī"},{"type":"verse","number":"99","sanskrit":"शठी पलाशी षड्ग्रन्था सुव्रता गन्धमूलिका गन्धारिका गन्धवधूर्वधूः पृथुपलाशिका","text":"śaṭhī palāśī ṣaḍgranthā suvratā gandhamūlikā gandhārikā gandhavadhūrvadhūḥ pṛthupalāśikā"},{"type":"verse","number":"100","sanskrit":"भवेद्गन्धपलाशी तु कषाया ग्राहिणी लघुः तिक्ता तीक्ष्णा च कटुकाऽनुष्णाऽस्यमलनाशिनी शोथकासव्रणश्वासशूलसिध्मग्रहापहा ३.","text":"bhavedgandhapalāśī tu kaṣāyā grāhiṇī laghuḥ tiktā tīkṣṇā ca kaṭukā'nuṣṇā'syamalanāśinī śothakāsavraṇaśvāsaśūlasidhmagrahāpahā 3."},{"type":"verse","number":"101","sanskrit":"प्रियङ्गुः फलिनी कान्ता लता च महिलाऽह्वया","text":"priyaṅguḥ phalinī kāntā latā ca mahilā'hvayā"},{"type":"verse","number":"102","sanskrit":"गुन्द्रा गन्धफला श्यामा विष्वक्सेनाङ्गनाप्रिया प्रियङ्गुः शीतला तिक्ता तुवराऽनिलपित्तहृत्","text":"gundrā gandhaphalā śyāmā viṣvaksenāṅganāpriyā priyaṅguḥ śītalā tiktā tuvarā'nilapittahṛt"},{"type":"verse","number":"103","sanskrit":"विआ!न्तिभ्रान्त्यतिसारघ्नी वक्त्रजाड्यविनाशिनी गुल्मतृड्विषमोहघ्नी तद्वद् गन्धप्रियङ्गुका","text":"viā!ntibhrāntyatisāraghnī vaktrajāḍyavināśinī gulmatṛḍviṣamohaghnī tadvad gandhapriyaṅgukā"},{"type":"verse","number":"104","sanskrit":"तत्फलं मधुरं रूक्षं कषायं शीतलं गुरु विबन्धाध्मानबलकृत्संग्राहि कफपित्तजित्","text":"tatphalaṃ madhuraṃ rūkṣaṃ kaṣāyaṃ śītalaṃ guru vibandhādhmānabalakṛtsaṃgrāhi kaphapittajit"},{"type":"verse","number":"105","sanskrit":"रेणुकाराजपुत्री च नन्दिनी कपिला द्विजा भस्मगन्धा पाण्डुपुत्री स्मृता कौन्ती हरेणुका","text":"reṇukārājaputrī ca nandinī kapilā dvijā bhasmagandhā pāṇḍuputrī smṛtā kauntī hareṇukā"},{"type":"verse","number":"106","sanskrit":"रेणुका कटुका पाके तिक्ताऽनुष्णा कटुर्लघुः पित्तला दीपनी मेध्या पाचनी गर्भपातिनी बलासवातकृच्चैव तृट्कण्डूविषदाहनुत्","text":"reṇukā kaṭukā pāke tiktā'nuṣṇā kaṭurlaghuḥ pittalā dīpanī medhyā pācanī garbhapātinī balāsavātakṛccaiva tṛṭkaṇḍūviṣadāhanut"},{"type":"verse","number":"107","sanskrit":"ग्रन्थिपर्णं ग्रन्थिकञ्च काकपुच्छञ्च गुच्छकम् नीलपुष्पं सुगन्धञ्च कथितं तैलपर्णकम्","text":"granthiparṇaṃ granthikañca kākapucchañca gucchakam nīlapuṣpaṃ sugandhañca kathitaṃ tailaparṇakam"},{"type":"verse","number":"108","sanskrit":"ग्रन्थिपर्णं तिक्ततीक्ष्णं कटूष्णं दीपनं लघु कफवातविषश्वासकण्डूदौर्गन्ध्यनाशनम्","text":"granthiparṇaṃ tiktatīkṣṇaṃ kaṭūṣṇaṃ dīpanaṃ laghu kaphavātaviṣaśvāsakaṇḍūdaurgandhyanāśanam"},{"type":"verse","number":"109","sanskrit":"स्थौणेयकं बर्हिबर्हं शुक्रबर्हञ्च कुक्कुरम् शीर्णरोमशुकञ्चापि शुकपुष्पं शुकच्छदम्","text":"sthauṇeyakaṃ barhibarhaṃ śukrabarhañca kukkuram śīrṇaromaśukañcāpi śukapuṣpaṃ śukacchadam"},{"type":"verse","number":"110","sanskrit":"स्थौणेयकं कटु स्वादु तिक्तं स्निग्धं त्रिदोषनुत् ३.","text":"sthauṇeyakaṃ kaṭu svādu tiktaṃ snigdhaṃ tridoṣanut 3."},{"type":"verse","number":"111","sanskrit":"मेधाशुक्रकरं रुच्यं रक्षोघ्नं ज्वरजन्तुजित् हन्ति कुष्ठास्रतृड्दाहदौर्गन्ध्यतिलकालकान्","text":"medhāśukrakaraṃ rucyaṃ rakṣoghnaṃ jvarajantujit hanti kuṣṭhāsratṛḍdāhadaurgandhyatilakālakān"},{"type":"verse","number":"112","sanskrit":"निशाचरो धनहरः कितवो गणहासकः चोरकः शङ्कितश्चण्डो दुष्पत्रः क्षेमको रिपुः चोरको मधुरस्तिक्तः कटुः पाके कटुर्लघुः","text":"niśācaro dhanaharaḥ kitavo gaṇahāsakaḥ corakaḥ śaṅkitaścaṇḍo duṣpatraḥ kṣemako ripuḥ corako madhurastiktaḥ kaṭuḥ pāke kaṭurlaghuḥ"},{"type":"verse","number":"113","sanskrit":"तीक्ष्णो हृद्यो हिमो हन्ति कुष्ठकण्डूकफानिलान् रक्षोऽश्रीस्वेदमेदोऽस्रज्वरगन्धविषव्रणान्","text":"tīkṣṇo hṛdyo himo hanti kuṣṭhakaṇḍūkaphānilān rakṣo'śrīsvedamedo'srajvaragandhaviṣavraṇān"},{"type":"verse","number":"114","sanskrit":"तालीसमुक्तं पत्राढ्यं धात्रीपत्रञ्च तत्स्मृतम्","text":"tālīsamuktaṃ patrāḍhyaṃ dhātrīpatrañca tatsmṛtam"},{"type":"verse","number":"115","sanskrit":"तालीसं लघु तीक्ष्णोष्णं श्वासकासकफानिलान् निहन्त्यरुचिगुल्मामवह्निमांद्यक्षयामयान्","text":"tālīsaṃ laghu tīkṣṇoṣṇaṃ śvāsakāsakaphānilān nihantyarucigulmāmavahnimāṃdyakṣayāmayān"},{"type":"verse","number":"116","sanskrit":"कङ्कोलं कोलकं प्रोक्तं तथा कोषफलं स्मृतम् कङ्कोलं लघु तीक्ष्णोष्णं तिक्तं हृद्यं रुचिप्रदम् आस्यदौर्गन्ध्यहृद्रो गकफवातामयान्ध्यहृत्","text":"kaṅkolaṃ kolakaṃ proktaṃ tathā koṣaphalaṃ smṛtam kaṅkolaṃ laghu tīkṣṇoṣṇaṃ tiktaṃ hṛdyaṃ rucipradam āsyadaurgandhyahṛdro gakaphavātāmayāndhyahṛt"},{"type":"verse","number":"117","sanskrit":"स्निग्धोष्णा कफहृत्तिक्ता सुगन्धा गन्धकोकिला गन्धकोकिलया तुल्या विज्ञेया गन्धमालती","text":"snigdhoṣṇā kaphahṛttiktā sugandhā gandhakokilā gandhakokilayā tulyā vijñeyā gandhamālatī"},{"type":"verse","number":"118","sanskrit":"लामज्जकं सुनालं स्यादमृणालं लवं लघु इष्टकापथकं सेव्यं नलदञ्चावदातकम्","text":"lāmajjakaṃ sunālaṃ syādamṛṇālaṃ lavaṃ laghu iṣṭakāpathakaṃ sevyaṃ naladañcāvadātakam"},{"type":"verse","number":"119","sanskrit":"लामज्जकं हिमं तिक्तं लघु दोषत्रयास्रजित् त्वगामयस्वेदकृच्छ्रदाहपित्तास्ररोगनुत्","text":"lāmajjakaṃ himaṃ tiktaṃ laghu doṣatrayāsrajit tvagāmayasvedakṛcchradāhapittāsraroganut"},{"type":"verse","number":"120","sanskrit":"एलवालुकमैलेयं सुगन्धि हरिवालुकम् एलवालुकमेलालु कपित्थत्वचमीरितम् ३.","text":"elavālukamaileyaṃ sugandhi harivālukam elavālukamelālu kapitthatvacamīritam 3."},{"type":"verse","number":"121","sanskrit":"एलालु कटुकं पाके कषायं शीतलं लघु हन्तिकण्डूव्रणच्छर्दितृट्कासारुचिहृद्रुजः बलासविषपित्तास्रकुष्ठमूत्रगदकृमीन्","text":"elālu kaṭukaṃ pāke kaṣāyaṃ śītalaṃ laghu hantikaṇḍūvraṇaccharditṛṭkāsārucihṛdrujaḥ balāsaviṣapittāsrakuṣṭhamūtragadakṛmīn"},{"type":"verse","number":"122","sanskrit":"कुटन्नटं दासपुरं बालेयं परिपेलवम् प्लवगोपुरगोनर्दकैवर्तीमुस्तकानि च","text":"kuṭannaṭaṃ dāsapuraṃ bāleyaṃ paripelavam plavagopuragonardakaivartīmustakāni ca"},{"type":"verse","number":"123","sanskrit":"मुस्तावत्पेलवपुरं शुकाभं स्याद्बितुन्नकं","text":"mustāvatpelavapuraṃ śukābhaṃ syādbitunnakaṃ"},{"type":"verse","number":"124","sanskrit":"वितुन्नकं हिमं तिक्तं कषायं कटु कान्तिदम् कफपितास्रवीसर्पकुष्ठकण्डूविषप्रणुत्","text":"vitunnakaṃ himaṃ tiktaṃ kaṣāyaṃ kaṭu kāntidam kaphapitāsravīsarpakuṣṭhakaṇḍūviṣapraṇut"},{"type":"verse","number":"125","sanskrit":"स्पृक्काऽसृग् ब्राह्मणी देवी मरुन्माला लता लघुः समुद्रा न्ता वधूः कोटिवर्षा लङ्कोपिकेत्यपि","text":"spṛkkā'sṛg brāhmaṇī devī marunmālā latā laghuḥ samudrā ntā vadhūḥ koṭivarṣā laṅkopiketyapi"},{"type":"verse","number":"126","sanskrit":"स्पृक्का स्वाद्वी हिमा वृष्या तिक्ता निखिलदोषनुत् कुष्ठकण्डूविषस्वेददाहाश्री ज्वररक्तहृत्","text":"spṛkkā svādvī himā vṛṣyā tiktā nikhiladoṣanut kuṣṭhakaṇḍūviṣasvedadāhāśrī jvararaktahṛt"},{"type":"verse","number":"127","sanskrit":"पर्पटी रञ्जना कृष्णा जतुका जननी जनी जतुकृष्णाऽग्निसंस्पर्शा जतुकृच्चक्रवर्त्तिनी","text":"parpaṭī rañjanā kṛṣṇā jatukā jananī janī jatukṛṣṇā'gnisaṃsparśā jatukṛccakravarttinī"},{"type":"verse","number":"128","sanskrit":"पर्पटी तुवरा तिक्ता शिशिरा वर्णकृल्लघुः विषव्रणहरी कण्डूकफपित्तास्रकुष्ठनुत्","text":"parpaṭī tuvarā tiktā śiśirā varṇakṛllaghuḥ viṣavraṇaharī kaṇḍūkaphapittāsrakuṣṭhanut"},{"type":"verse","number":"129","sanskrit":"नलिका विद्रुमलता कपोतचरणा नटी धमन्यञ्जनकेशी च निर्मध्या सुषिरा नली","text":"nalikā vidrumalatā kapotacaraṇā naṭī dhamanyañjanakeśī ca nirmadhyā suṣirā nalī"},{"type":"verse","number":"130","sanskrit":"नलिका शीतला लघ्वी चक्षुष्या कफपित्तहृत् कृच्छ्राश्मवाततृष्णाऽस्रकुष्ठकण्डूज्वरापहा ३.","text":"nalikā śītalā laghvī cakṣuṣyā kaphapittahṛt kṛcchrāśmavātatṛṣṇā'srakuṣṭhakaṇḍūjvarāpahā 3."},{"type":"verse","number":"131","sanskrit":"प्रपौण्डरीकं पौण्डर्यं चक्षुष्यं पौण्डरीयकम् पौण्डर्यं मधुरं तिक्तं कषायं शुक्रलं हिमम् चक्षुष्यं मधुरं पाके वर्ण्यं पित्तकफप्रणुत्","text":"prapauṇḍarīkaṃ pauṇḍaryaṃ cakṣuṣyaṃ pauṇḍarīyakam pauṇḍaryaṃ madhuraṃ tiktaṃ kaṣāyaṃ śukralaṃ himam cakṣuṣyaṃ madhuraṃ pāke varṇyaṃ pittakaphapraṇut"},{"type":"verse","number":"3","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे वर्गप्रकरणे तृतीयः कर्पूरादिवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe vargaprakaraṇe tṛtīyaḥ karpūrādivargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":3,"lang":"sa","content":[{"type":"heading","heading":"guḍūcyādi-варга — группа гудучи"},{"type":"verse","number":"1","sanskrit":"अथ लङ्केश्वरो मानी रावणो राक्षसाधिपः रामपत्नीं बलात्सीतां जहार मदनातुरः","text":"atha laṅkeśvaro mānī rāvaṇo rākṣasādhipaḥ rāmapatnīṃ balātsītāṃ jahāra madanāturaḥ"},{"type":"verse","number":"2","sanskrit":"ततस्तं वलवान् रामो रिपुं जायाऽपहारिणम् वृतो बानरसैन्येन जघान रणमूर्धनि","text":"tatastaṃ valavān rāmo ripuṃ jāyā'pahāriṇam vṛto bānarasainyena jaghāna raṇamūrdhani"},{"type":"verse","number":"3","sanskrit":"हते तस्मिन्सुरारातौ रावणे बलगर्विते देवराजः सहस्राक्षः परितुष्टश्चराघवे","text":"hate tasminsurārātau rāvaṇe balagarvite devarājaḥ sahasrākṣaḥ parituṣṭaścarāghave"},{"type":"verse","number":"4","sanskrit":"तत्र ये वानराः कैचिद्रा क्षसैर्निहता रणे तानिन्द्रो जीवयामास संसिच्यामृतवृष्टिभिः","text":"tatra ye vānarāḥ kaicidrā kṣasairnihatā raṇe tānindro jīvayāmāsa saṃsicyāmṛtavṛṣṭibhiḥ"},{"type":"verse","number":"5","sanskrit":"ततो येषु प्रदेशेषु कपिगात्रात्परिच्युताः पीयूषबिन्दवः पेतुस्तेभ्यो जाता गुडूचिका","text":"tato yeṣu pradeśeṣu kapigātrātparicyutāḥ pīyūṣabindavaḥ petustebhyo jātā guḍūcikā"},{"type":"verse","number":"6","sanskrit":"गुडूची मधुपर्णी स्यादमृताऽमृतवल्लरी छिन्ना छिन्नरुहा छिन्नोद्भवा वत्सादनीति च","text":"guḍūcī madhuparṇī syādamṛtā'mṛtavallarī chinnā chinnaruhā chinnodbhavā vatsādanīti ca"},{"type":"verse","number":"7","sanskrit":"जीवन्ती तन्त्रिका सोमा सोमवल्ली च कुण्डली चक्रलक्षणिका धीरा विशल्या च रसायनी","text":"jīvantī tantrikā somā somavallī ca kuṇḍalī cakralakṣaṇikā dhīrā viśalyā ca rasāyanī"},{"type":"verse","number":"8","sanskrit":"चन्द्र हासा वयस्था च मण्डली देवनिर्मिता गुडूची कटुका तिक्ता स्वादुपाका रसायनी","text":"candra hāsā vayasthā ca maṇḍalī devanirmitā guḍūcī kaṭukā tiktā svādupākā rasāyanī"},{"type":"verse","number":"9","sanskrit":"संग्राहिणी कषायोष्णा लघ्वी बल्याऽग्निदीपिनी दोषत्रयामतृड्दाहमेहकासांश्च पाण्डुताम्","text":"saṃgrāhiṇī kaṣāyoṣṇā laghvī balyā'gnidīpinī doṣatrayāmatṛḍdāhamehakāsāṃśca pāṇḍutām"},{"type":"verse","number":"10","sanskrit":"प्रिमेहश्वासकासार्शः कृच्छ्रहृद्रो गवातनुत् ४.","text":"primehaśvāsakāsārśaḥ kṛcchrahṛdro gavātanut 4."},{"type":"verse","number":"11","sanskrit":"ताम्बूलवल्ली ताम्बूली नागिनी नागवल्लरी ताम्बूलं विशदं रुच्यं तीक्ष्णोष्णं तुवरं सरम्","text":"tāmbūlavallī tāmbūlī nāginī nāgavallarī tāmbūlaṃ viśadaṃ rucyaṃ tīkṣṇoṣṇaṃ tuvaraṃ saram"},{"type":"verse","number":"12","sanskrit":"वश्यं तिक्तं कटु क्षारं रक्तपित्तकरं लघु बल्यं श्लेष्मास्यदौर्गन्ध्यमलवातश्रमापहम्","text":"vaśyaṃ tiktaṃ kaṭu kṣāraṃ raktapittakaraṃ laghu balyaṃ śleṣmāsyadaurgandhyamalavātaśramāpaham"},{"type":"verse","number":"13","sanskrit":"बिल्वः शाण्डिल्यशैलूषौ मालूरश्रीफलावपि श्रीफलस्तुवरस्तिक्तो ग्राही रूक्षोऽग्निपित्तकृत् वातश्लेष्महरो बल्यो लघुरुष्णश्च पाचनः","text":"bilvaḥ śāṇḍilyaśailūṣau mālūraśrīphalāvapi śrīphalastuvarastikto grāhī rūkṣo'gnipittakṛt vātaśleṣmaharo balyo laghuruṣṇaśca pācanaḥ"},{"type":"verse","number":"14","sanskrit":"गम्भारी भद्र पर्णी च श्रीपर्णी मधुपर्णिका काश्मीरी काश्मरी हीरा काश्मर्यः पीतरोहिणी","text":"gambhārī bhadra parṇī ca śrīparṇī madhuparṇikā kāśmīrī kāśmarī hīrā kāśmaryaḥ pītarohiṇī"},{"type":"verse","number":"15","sanskrit":"कृष्णवृन्ता मधुरसा महाकुसुमिकाऽपि च काश्मीरी तुवरा तिक्ता वीर्योष्णा मधुरा गुरुः","text":"kṛṣṇavṛntā madhurasā mahākusumikā'pi ca kāśmīrī tuvarā tiktā vīryoṣṇā madhurā guruḥ"},{"type":"verse","number":"16","sanskrit":"दीपनी पाचनी मेध्या भेदिनी भ्रमशोषजित् दोषतृष्णाऽमशूलार्शोविषदाहज्वरापहा","text":"dīpanī pācanī medhyā bhedinī bhramaśoṣajit doṣatṛṣṇā'maśūlārśoviṣadāhajvarāpahā"},{"type":"verse","number":"17","sanskrit":"तत्फलं बृंहणं वृष्यं गुरु केश्यं रसायनम् वातपित्ततृषारक्तक्षयमूत्रविबन्धनुत्","text":"tatphalaṃ bṛṃhaṇaṃ vṛṣyaṃ guru keśyaṃ rasāyanam vātapittatṛṣāraktakṣayamūtravibandhanut"},{"type":"verse","number":"18","sanskrit":"स्वादु पाके हिमं स्निग्धं तुवराम्लं विशुद्धिकृत् हन्याद्दाहतृषावातरक्तपित्तक्षतक्षयान्","text":"svādu pāke himaṃ snigdhaṃ tuvarāmlaṃ viśuddhikṛt hanyāddāhatṛṣāvātaraktapittakṣatakṣayān"},{"type":"verse","number":"19","sanskrit":"पाटलि पाटलाऽमोघा मधुदूतो फलेरुहा कृष्णवृन्ता कुबेराक्षी कालस्थाल्यलिवल्लभा","text":"pāṭali pāṭalā'moghā madhudūto phaleruhā kṛṣṇavṛntā kuberākṣī kālasthālyalivallabhā"},{"type":"verse","number":"20","sanskrit":"ताम्रपुष्पी च कथिताऽपरा स्यात्पाटला सिता मुष्कको मोक्षको घण्टापाटलिकाष्टपाटला ४.","text":"tāmrapuṣpī ca kathitā'parā syātpāṭalā sitā muṣkako mokṣako ghaṇṭāpāṭalikāṣṭapāṭalā 4."},{"type":"verse","number":"21","sanskrit":"पाटला तुवरा तिक्ताऽनुष्णा दोषत्रयापहा अरुचिश्वासशोथास्रच्छर्दिहिक्कातृषाहरी","text":"pāṭalā tuvarā tiktā'nuṣṇā doṣatrayāpahā aruciśvāsaśothāsracchardihikkātṛṣāharī"},{"type":"verse","number":"22","sanskrit":"पुष्पं कषायं मधुरं हिमं हृद्यं कफास्रनुत् पित्तातिसारहृत्कण्ठ्यं फलं हिक्काऽस्रपित्तहृत्","text":"puṣpaṃ kaṣāyaṃ madhuraṃ himaṃ hṛdyaṃ kaphāsranut pittātisārahṛtkaṇṭhyaṃ phalaṃ hikkā'srapittahṛt"},{"type":"verse","number":"23","sanskrit":"अग्निमन्थो जयः सस्याच्छ्रीपर्णी गणिकारिका जया जयन्ती तर्कारी नादेयी वैजयन्तिका","text":"agnimantho jayaḥ sasyācchrīparṇī gaṇikārikā jayā jayantī tarkārī nādeyī vaijayantikā"},{"type":"verse","number":"24","sanskrit":"अग्निमन्थः श्वयथुनुद्वीर्योष्णः कफवातहृत् पाण्डुनुत्कटुकस्तिक्तस्तुवरो मधुरोऽग्निदः","text":"agnimanthaḥ śvayathunudvīryoṣṇaḥ kaphavātahṛt pāṇḍunutkaṭukastiktastuvaro madhuro'gnidaḥ"},{"type":"verse","number":"25","sanskrit":"श्योनाकः शोषणश्च स्यान्नटकट्वङ्गटुण्टुकाः मण्डूकपर्णपत्रोर्णशुकनासकुटन्नटाः","text":"śyonākaḥ śoṣaṇaśca syānnaṭakaṭvaṅgaṭuṇṭukāḥ maṇḍūkaparṇapatrorṇaśukanāsakuṭannaṭāḥ"},{"type":"verse","number":"26","sanskrit":"दीर्घवृन्तोऽरलुश्चापि पृथुशिम्बः कटम्भरः श्योनाको दीपनः पाके कटुकस्तुवरो हिमः ग्राही तिक्तोऽनिलश्लेष्मपित्तकासप्रणाशनः","text":"dīrghavṛnto'raluścāpi pṛthuśimbaḥ kaṭambharaḥ śyonāko dīpanaḥ pāke kaṭukastuvaro himaḥ grāhī tikto'nilaśleṣmapittakāsapraṇāśanaḥ"},{"type":"verse","number":"27","sanskrit":"टुण्टुकस्य फलं बालं रूक्षं वातकफापहम्","text":"ṭuṇṭukasya phalaṃ bālaṃ rūkṣaṃ vātakaphāpaham"},{"type":"verse","number":"28","sanskrit":"हृद्यं कषायं मधुरं रोचनं लघु दीपनम् गुल्मार्शःकृमिहृत् प्रौढं गुरु वातप्रकोपणम्","text":"hṛdyaṃ kaṣāyaṃ madhuraṃ rocanaṃ laghu dīpanam gulmārśaḥkṛmihṛt prauḍhaṃ guru vātaprakopaṇam"},{"type":"verse","number":"29","sanskrit":"श्रीफलः सर्वतोभद्रा पाटला गणिकारिका श्योनाकः पञ्चभिश्चैतैः पञ्चमूलं महन्मतम्","text":"śrīphalaḥ sarvatobhadrā pāṭalā gaṇikārikā śyonākaḥ pañcabhiścaitaiḥ pañcamūlaṃ mahanmatam"},{"type":"verse","number":"30","sanskrit":"पञ्चमूलं महत् तिक्तं कषायँ कफवातनुत् मधुरं श्वासकासघ्नमुष्णं लघ्वग्निदीपनम् ४.","text":"pañcamūlaṃ mahat tiktaṃ kaṣāya~ kaphavātanut madhuraṃ śvāsakāsaghnamuṣṇaṃ laghvagnidīpanam 4."},{"type":"verse","number":"31","sanskrit":"शालपर्णी स्थिरा सौम्या त्रिपर्णी पीवरी गुहा विदारिगन्धा दीर्घाङ्गी दीर्घपत्रांऽशुमत्यपि","text":"śālaparṇī sthirā saumyā triparṇī pīvarī guhā vidārigandhā dīrghāṅgī dīrghapatrāṃ'śumatyapi"},{"type":"verse","number":"32","sanskrit":"शालपर्णी गुरुश्छर्दिज्वरश्वासातिसारजित्","text":"śālaparṇī guruśchardijvaraśvāsātisārajit"},{"type":"verse","number":"33","sanskrit":"शोषदोषत्रयहरी बृंहण्युक्ता रसायनी तिक्ता विषहरी स्वादुः क्षतकासकृमिप्रणुत्","text":"śoṣadoṣatrayaharī bṛṃhaṇyuktā rasāyanī tiktā viṣaharī svāduḥ kṣatakāsakṛmipraṇut"},{"type":"verse","number":"34","sanskrit":"पृश्निपर्णी पृथक्पर्णी चित्रपर्ण्यहिपर्ण्यपि क्रोष्टुविन्ना सिंहपुच्छी कलशी धावनिर्गुहा","text":"pṛśniparṇī pṛthakparṇī citraparṇyahiparṇyapi kroṣṭuvinnā siṃhapucchī kalaśī dhāvanirguhā"},{"type":"verse","number":"35","sanskrit":"पृश्निपर्णी त्रिदोषघ्नी वृष्योष्णा मधुराऽसरा हन्ति दाहज्वरश्वासरक्तातीसारतृड्वमीः","text":"pṛśniparṇī tridoṣaghnī vṛṣyoṣṇā madhurā'sarā hanti dāhajvaraśvāsaraktātīsāratṛḍvamīḥ"},{"type":"verse","number":"36","sanskrit":"वार्त्ताकी क्षुद्र भण्टाकी महती बृहती कुली हिङ्गुली राष्ट्रिका सिंही महोष्ट्री दुष्प्रधर्षिणी बृहती ग्राहिणी हृद्या पाचनी कफवातहृत्","text":"vārttākī kṣudra bhaṇṭākī mahatī bṛhatī kulī hiṅgulī rāṣṭrikā siṃhī mahoṣṭrī duṣpradharṣiṇī bṛhatī grāhiṇī hṛdyā pācanī kaphavātahṛt"},{"type":"verse","number":"37","sanskrit":"उष्णा कुष्ठज्वरश्वासशूलकासाग्निमान्द्यजित्","text":"uṣṇā kuṣṭhajvaraśvāsaśūlakāsāgnimāndyajit"},{"type":"verse","number":"38","sanskrit":"कण्टकारी तु दुःस्पर्शा क्षुद्रा व्याघ्री निदिग्धिका कण्टालिका कण्टकिनी धावनी बृहती तथा","text":"kaṇṭakārī tu duḥsparśā kṣudrā vyāghrī nidigdhikā kaṇṭālikā kaṇṭakinī dhāvanī bṛhatī tathā"},{"type":"verse","number":"39","sanskrit":"श्वेता क्षुद्रा चन्द्र हासा लक्ष्मणा क्षेत्रदूतिका गर्भदा चन्द्र मा चन्द्री चन्द्र पुष्पा प्रियङ्करी","text":"śvetā kṣudrā candra hāsā lakṣmaṇā kṣetradūtikā garbhadā candra mā candrī candra puṣpā priyaṅkarī"},{"type":"verse","number":"40","sanskrit":"कण्टकारी सरा तिक्ता कटुका दीपनी लघुः ४.","text":"kaṇṭakārī sarā tiktā kaṭukā dīpanī laghuḥ 4."},{"type":"verse","number":"41","sanskrit":"रूक्षोष्णा पाचनी कासश्वासज्वरकफानिलान् निहन्ति पीनसं पार्श्वपीडाकृमिहृदामयान्","text":"rūkṣoṣṇā pācanī kāsaśvāsajvarakaphānilān nihanti pīnasaṃ pārśvapīḍākṛmihṛdāmayān"},{"type":"verse","number":"42","sanskrit":"तयोः फलं कटु रसे पाके च कटुकं भवेत् शुक्रस्य रेचनं भेदि तिक्तं पित्ताग्निकृल्लघु हन्यात्कफमरुत्कण्डूकासमेदः कृमिज्वरान्","text":"tayoḥ phalaṃ kaṭu rase pāke ca kaṭukaṃ bhavet śukrasya recanaṃ bhedi tiktaṃ pittāgnikṛllaghu hanyātkaphamarutkaṇḍūkāsamedaḥ kṛmijvarān"},{"type":"verse","number":"43","sanskrit":"तद्वत्प्रोक्ता सिता क्षुद्रा विशेषाद् गर्भकारिणी","text":"tadvatproktā sitā kṣudrā viśeṣād garbhakāriṇī"},{"type":"verse","number":"44","sanskrit":"गोक्षुरः क्षुरकोऽपि स्यात्त्रिकण्टः स्वादुकण्टकः गोकण्टको गोक्षुरको वनशृङ्गाट इत्यपि","text":"gokṣuraḥ kṣurako'pi syāttrikaṇṭaḥ svādukaṇṭakaḥ gokaṇṭako gokṣurako vanaśṛṅgāṭa ityapi"},{"type":"verse","number":"45","sanskrit":"पलङ्कषा श्वदंष्ट्रा च तथा स्यादिक्षुगन्धिका गोक्षुरः शीतलःस्वादुर्बलकृद्बस्तिशोधनः","text":"palaṅkaṣā śvadaṃṣṭrā ca tathā syādikṣugandhikā gokṣuraḥ śītalaḥsvādurbalakṛdbastiśodhanaḥ"},{"type":"verse","number":"46","sanskrit":"मधुरो दीपनो वृष्यः पुष्टिदश्चाश्मरीहरः प्रमेहश्वासकासार्शः कृच्छ्रहृद्रो गवातनुत्","text":"madhuro dīpano vṛṣyaḥ puṣṭidaścāśmarīharaḥ pramehaśvāsakāsārśaḥ kṛcchrahṛdro gavātanut"},{"type":"verse","number":"47","sanskrit":"शालपर्णी पृश्निपर्णी वार्त्ताकी कण्टकारिका गोक्षुरः पञ्चभिश्चैतैः कनिष्ठं पञ्चमूलकम्","text":"śālaparṇī pṛśniparṇī vārttākī kaṇṭakārikā gokṣuraḥ pañcabhiścaitaiḥ kaniṣṭhaṃ pañcamūlakam"},{"type":"verse","number":"48","sanskrit":"पञ्चमूलं लघु स्वादु बल्यं पित्तानिलापहम् नात्युष्णं बृंहणं ग्राहि ज्वरश्वासाश्मरीप्रणुत्","text":"pañcamūlaṃ laghu svādu balyaṃ pittānilāpaham nātyuṣṇaṃ bṛṃhaṇaṃ grāhi jvaraśvāsāśmarīpraṇut"},{"type":"verse","number":"49","sanskrit":"उभाभ्यां पञ्चमूलाभ्यां दशमूलमुदाहृतम् दशमूलं त्रिदोषघ्नं श्वासकासशिरोरुजः तन्द्रा शोथज्वरानाहपार्श्वपीडाऽरुचीर्हरेत्","text":"ubhābhyāṃ pañcamūlābhyāṃ daśamūlamudāhṛtam daśamūlaṃ tridoṣaghnaṃ śvāsakāsaśirorujaḥ tandrā śothajvarānāhapārśvapīḍā'rucīrharet"},{"type":"verse","number":"50","sanskrit":"जीवन्ती जीवनी जीवा जीवनीया मधुस्रवा माङ्गल्यनामधेया च शाकश्रेष्ठा पयस्विनी ४.","text":"jīvantī jīvanī jīvā jīvanīyā madhusravā māṅgalyanāmadheyā ca śākaśreṣṭhā payasvinī 4."},{"type":"verse","number":"51","sanskrit":"जीवन्ती शीतला स्वादुः स्निग्धा दोषत्रयापहा रसायनी बलकरी चक्षुष्या ग्राहिणी लघुः","text":"jīvantī śītalā svāduḥ snigdhā doṣatrayāpahā rasāyanī balakarī cakṣuṣyā grāhiṇī laghuḥ"},{"type":"verse","number":"52","sanskrit":"मुद्गपर्णी काकपर्णी सूर्यपर्ण्यल्पिका सहा","text":"mudgaparṇī kākaparṇī sūryaparṇyalpikā sahā"},{"type":"verse","number":"53","sanskrit":"काकमुद्गा च सा प्रोक्ता तथा मार्जारगन्धिका मुद्गपर्णी हिमा रूक्षा तिक्ता स्वादुश्च शुक्रला","text":"kākamudgā ca sā proktā tathā mārjāragandhikā mudgaparṇī himā rūkṣā tiktā svāduśca śukralā"},{"type":"verse","number":"54","sanskrit":"चक्षुष्या क्षतशोथघ्नी ग्राहिणी ज्वरदाहनुत् दोषत्रयहरी लघ्वी ग्रहण्यर्शोऽतिसारजित्","text":"cakṣuṣyā kṣataśothaghnī grāhiṇī jvaradāhanut doṣatrayaharī laghvī grahaṇyarśo'tisārajit"},{"type":"verse","number":"55","sanskrit":"माषपर्णी सूर्यपर्णी काम्बोजी हयपुच्छिका पाण्डुलोमशपर्णी च कृष्णवृन्ता महासहा","text":"māṣaparṇī sūryaparṇī kāmbojī hayapucchikā pāṇḍulomaśaparṇī ca kṛṣṇavṛntā mahāsahā"},{"type":"verse","number":"56","sanskrit":"माषपर्णी हिमा तिक्ता रूक्षा शुक्रबलासकृत् मधुरा ग्राहिणी शोथवातपित्तज्वरास्रजित्","text":"māṣaparṇī himā tiktā rūkṣā śukrabalāsakṛt madhurā grāhiṇī śothavātapittajvarāsrajit"},{"type":"verse","number":"57","sanskrit":"अष्टवर्गः सयष्टीको जीवन्ती मुद्गपर्णिका माषपर्णी गणोऽय तु जीवनीय इति स्मृतः","text":"aṣṭavargaḥ sayaṣṭīko jīvantī mudgaparṇikā māṣaparṇī gaṇo'ya tu jīvanīya iti smṛtaḥ"},{"type":"verse","number":"58","sanskrit":"जीवनो मधुरश्चापि नाम्ना स परिकीर्त्तितः जीवनीयगणः प्रोक्तः शुक्रकृद् बृंहणो हिमः","text":"jīvano madhuraścāpi nāmnā sa parikīrttitaḥ jīvanīyagaṇaḥ proktaḥ śukrakṛd bṛṃhaṇo himaḥ"},{"type":"verse","number":"59","sanskrit":"गुरुर्गर्भप्रदः स्तन्यकफकृत्पित्तरक्तहृत् तृष्णां शोषं ज्वरं दाहं रक्तपित्तं व्यपोहति","text":"gururgarbhapradaḥ stanyakaphakṛtpittaraktahṛt tṛṣṇāṃ śoṣaṃ jvaraṃ dāhaṃ raktapittaṃ vyapohati"},{"type":"verse","number":"60","sanskrit":"शुक्ल एरण्ड आमण्डश्चित्रो गन्धर्वहस्तकः पञ्चाङ्गुलो वर्द्धमानो दीर्घदण्डो व्यडम्बकः ४.","text":"śukla eraṇḍa āmaṇḍaścitro gandharvahastakaḥ pañcāṅgulo varddhamāno dīrghadaṇḍo vyaḍambakaḥ 4."},{"type":"verse","number":"61","sanskrit":"वातारिस्तरुणश्चापि रुबूकश्च निगद्यते रक्तोऽपरो रुबूकः स्यादुरुबूको रुबुस्तथा","text":"vātāristaruṇaścāpi rubūkaśca nigadyate rakto'paro rubūkaḥ syādurubūko rubustathā"},{"type":"verse","number":"62","sanskrit":"व्याघ्रपुच्छश्च वातारिश्चञ्चुरुत्तानपत्रकः एरण्डयुग्मं मधुरमुष्णं गुरु विनाशयेत्","text":"vyāghrapucchaśca vātāriścañcuruttānapatrakaḥ eraṇḍayugmaṃ madhuramuṣṇaṃ guru vināśayet"},{"type":"verse","number":"63","sanskrit":"व्रघ्नश्वासकफानाहकासकुष्ठाप्तमारुतान्","text":"vraghnaśvāsakaphānāhakāsakuṣṭhāptamārutān"},{"type":"verse","number":"64","sanskrit":"एरण्डपत्रं वातघ्नं कफक्रिमिविनाशनम् मूत्रकृच्छ्रहरं चापि पित्तरक्तप्रकोपणम् वातार्यग्रदलं गुल्मबस्तिशूलहरं परम्","text":"eraṇḍapatraṃ vātaghnaṃ kaphakrimivināśanam mūtrakṛcchraharaṃ cāpi pittaraktaprakopaṇam vātāryagradalaṃ gulmabastiśūlaharaṃ param"},{"type":"verse","number":"65","sanskrit":"कफवातकृमीन्हन्ति वृद्धिं सप्तविधामपि एरण्डफलमत्युष्णं गुल्मशूलानिलापहम्","text":"kaphavātakṛmīnhanti vṛddhiṃ saptavidhāmapi eraṇḍaphalamatyuṣṇaṃ gulmaśūlānilāpaham"},{"type":"verse","number":"66","sanskrit":"यकृत्प्लीहोदरार्शोघ्नं कटुकं दीपनं परम् तद्वन्मज्जा च विडभेदी वातश्लेष्मोदरापहः","text":"yakṛtplīhodarārśoghnaṃ kaṭukaṃ dīpanaṃ param tadvanmajjā ca viḍabhedī vātaśleṣmodarāpahaḥ"},{"type":"verse","number":"67","sanskrit":"श्वेतार्को गणरूपः स्यान्मन्दारो वसुकोऽपि च श्वेतपुष्पः सदापुष्पः स चालर्कः प्रतापसः","text":"śvetārko gaṇarūpaḥ syānmandāro vasuko'pi ca śvetapuṣpaḥ sadāpuṣpaḥ sa cālarkaḥ pratāpasaḥ"},{"type":"verse","number":"68","sanskrit":"रक्तोऽपरोऽकनामा स्यादर्कपर्णो विकीरणः रक्तपुष्पः शुक्लफलस्तथाऽस्फोटः प्रकीर्त्तितः","text":"rakto'paro'kanāmā syādarkaparṇo vikīraṇaḥ raktapuṣpaḥ śuklaphalastathā'sphoṭaḥ prakīrttitaḥ"},{"type":"verse","number":"69","sanskrit":"अर्कद्वयं सरं वातकुष्ठकण्डूविषव्रणान् निहन्ति प्लीहगुल्मार्शःश्लेष्मोदरशकृत्कृमीन्","text":"arkadvayaṃ saraṃ vātakuṣṭhakaṇḍūviṣavraṇān nihanti plīhagulmārśaḥśleṣmodaraśakṛtkṛmīn"},{"type":"verse","number":"70","sanskrit":"अलर्ककुसुमं वृष्यं लघु दीपनपाचनम् अरोचकप्रसेकार्शः कासश्वासनिवारणम् ४.","text":"alarkakusumaṃ vṛṣyaṃ laghu dīpanapācanam arocakaprasekārśaḥ kāsaśvāsanivāraṇam 4."},{"type":"verse","number":"71","sanskrit":"रक्तार्कपुष्पं मधुरं सतिक्तं कुष्ठकृमिघ्नं कफनाशनञ्च अर्शो विषं हन्ति च रक्तपित्तं संग्राहि गुल्मे श्वयथौ हितं तत्","text":"raktārkapuṣpaṃ madhuraṃ satiktaṃ kuṣṭhakṛmighnaṃ kaphanāśanañca arśo viṣaṃ hanti ca raktapittaṃ saṃgrāhi gulme śvayathau hitaṃ tat"},{"type":"verse","number":"72","sanskrit":"क्षीरमर्कस्य तिक्तोष्णं स्निग्धं सलवणं लघु कुष्ठगुल्मोदरहरं श्रेष्ठमेतद्विरेचनम्","text":"kṣīramarkasya tiktoṣṇaṃ snigdhaṃ salavaṇaṃ laghu kuṣṭhagulmodaraharaṃ śreṣṭhametadvirecanam"},{"type":"verse","number":"73","sanskrit":"सेहुण्डः सिंहतुण्डः स्याद्वज्री वज्रद्रुमोऽपि च सुधासमन्तदुग्धा च स्नुक्स्त्रियां स्यात्स्नुही गुडा","text":"sehuṇḍaḥ siṃhatuṇḍaḥ syādvajrī vajradrumo'pi ca sudhāsamantadugdhā ca snukstriyāṃ syātsnuhī guḍā"},{"type":"verse","number":"74","sanskrit":"सेहुण्डो रेचनस्तीक्ष्णो दीपनः कटुको गुरुः शूलामाष्ठीलिकाऽध्मानकफगुल्मोदरानिलान्","text":"sehuṇḍo recanastīkṣṇo dīpanaḥ kaṭuko guruḥ śūlāmāṣṭhīlikā'dhmānakaphagulmodarānilān"},{"type":"verse","number":"75","sanskrit":"उन्मादमोहकुष्ठार्शः शोथमेदोऽश्मपाण्डुताः व्रणशोथज्वरप्लीहविषदूषीविषं हरेत्","text":"unmādamohakuṣṭhārśaḥ śothamedo'śmapāṇḍutāḥ vraṇaśothajvaraplīhaviṣadūṣīviṣaṃ haret"},{"type":"verse","number":"76","sanskrit":"उष्णवीर्यं स्नुहीक्षीरं स्निग्धञ्च कटुकं लघु गुल्मिनां कुष्ठिनाञ्चापि तथैवोदररोगिणाम्","text":"uṣṇavīryaṃ snuhīkṣīraṃ snigdhañca kaṭukaṃ laghu gulmināṃ kuṣṭhināñcāpi tathaivodararogiṇām"},{"type":"verse","number":"77","sanskrit":"हितमेतद्विरेकार्थं ये चान्ये दीर्घरोगिणः","text":"hitametadvirekārthaṃ ye cānye dīrgharogiṇaḥ"},{"type":"verse","number":"78","sanskrit":"शातला सप्तला सारा विमला विदुला च सा तथा निगदिता भूरिफेना चर्मकषेत्यपि","text":"śātalā saptalā sārā vimalā vidulā ca sā tathā nigaditā bhūriphenā carmakaṣetyapi"},{"type":"verse","number":"79","sanskrit":"शातला कटुका पाके वातला शीतला लघुः तिक्ता शोथकफानाहपित्तोदावर्त्तरक्तजित्","text":"śātalā kaṭukā pāke vātalā śītalā laghuḥ tiktā śothakaphānāhapittodāvarttaraktajit"},{"type":"verse","number":"80","sanskrit":"कलिहारी तु हलिनी लाङ्गली शक्रपुष्प्यपि विशल्याऽग्निशिखाऽनन्तावह्निवक्त्रा च गर्भनुत् कलिहारी सरा कुष्ठशोफार्शोव्रणशूलजित् ४.","text":"kalihārī tu halinī lāṅgalī śakrapuṣpyapi viśalyā'gniśikhā'nantāvahnivaktrā ca garbhanut kalihārī sarā kuṣṭhaśophārśovraṇaśūlajit 4."},{"type":"verse","number":"81","sanskrit":"सक्षारा श्लेष्मजित्तिक्ताकटुका तुवराऽपि च तीक्ष्णोष्णा कृमिहृल्लघ्वी पित्तलागर्भपातिनी","text":"sakṣārā śleṣmajittiktākaṭukā tuvarā'pi ca tīkṣṇoṣṇā kṛmihṛllaghvī pittalāgarbhapātinī"},{"type":"verse","number":"82","sanskrit":"करवीरः श्वेतपुष्पः शतकुम्भोऽश्वमारकः द्वितीयो रक्तपुष्पश्च चण्डातो लगुडस्तथा","text":"karavīraḥ śvetapuṣpaḥ śatakumbho'śvamārakaḥ dvitīyo raktapuṣpaśca caṇḍāto laguḍastathā"},{"type":"verse","number":"83","sanskrit":"करवीरद्वयं तिक्तं कषायं कटुकञ्च तत् व्रणलाघवकृन्नेत्रकोपकुष्ठव्रणापहम्","text":"karavīradvayaṃ tiktaṃ kaṣāyaṃ kaṭukañca tat vraṇalāghavakṛnnetrakopakuṣṭhavraṇāpaham"},{"type":"verse","number":"84","sanskrit":"वीर्योष्णं कृमिकण्डूघ्नं भक्षितं विषवन्मतम्","text":"vīryoṣṇaṃ kṛmikaṇḍūghnaṃ bhakṣitaṃ viṣavanmatam"},{"type":"verse","number":"85","sanskrit":"धत्तूरधूर्त्तधुत्तूरा उन्मत्तः कनकाह्वयः देवता कितवस्तूरी महामोही शिवप्रियः","text":"dhattūradhūrttadhuttūrā unmattaḥ kanakāhvayaḥ devatā kitavastūrī mahāmohī śivapriyaḥ"},{"type":"verse","number":"86","sanskrit":"मातुलो मदनश्चास्य फले मातुलपुत्रकः धत्तूरो मदवर्णाग्निवातकृज्ज्वरकुष्ठनुत्","text":"mātulo madanaścāsya phale mātulaputrakaḥ dhattūro madavarṇāgnivātakṛjjvarakuṣṭhanut"},{"type":"verse","number":"87","sanskrit":"कषायो मधुरस्तिक्तो यूकालिक्षाविनाशकः उष्णो गुरुर्व्रणश्लेष्मकण्डूकृमिविषापहः","text":"kaṣāyo madhurastikto yūkālikṣāvināśakaḥ uṣṇo gururvraṇaśleṣmakaṇḍūkṛmiviṣāpahaḥ"},{"type":"verse","number":"88","sanskrit":"वासको वासिका वासा भिषङ्माता च सिंहिका सिंहास्यो वाजिदन्ता स्यादाटरूषोऽटरूषकः","text":"vāsako vāsikā vāsā bhiṣaṅmātā ca siṃhikā siṃhāsyo vājidantā syādāṭarūṣo'ṭarūṣakaḥ"},{"type":"verse","number":"89","sanskrit":"अटरूषो वृषस्ताम्रः सिंहपर्णश्च स स्मृतः वासको वातकृत्स्वर्यः कफपित्तास्रनाशनः","text":"aṭarūṣo vṛṣastāmraḥ siṃhaparṇaśca sa smṛtaḥ vāsako vātakṛtsvaryaḥ kaphapittāsranāśanaḥ"},{"type":"verse","number":"90","sanskrit":"तिक्तस्तुवरको हृद्यो लघुशीतस्तृडर्त्तिहृत् श्वासकासज्वरच्छर्दिमेहकुष्ठक्षयापहः ४.","text":"tiktastuvarako hṛdyo laghuśītastṛḍarttihṛt śvāsakāsajvaracchardimehakuṣṭhakṣayāpahaḥ 4."},{"type":"verse","number":"91","sanskrit":"पर्पटो वरतिक्तश्च स्मृतः पर्पटकश्च सः कथितः पांशुपर्यायस्तथा कवचनामकः","text":"parpaṭo varatiktaśca smṛtaḥ parpaṭakaśca saḥ kathitaḥ pāṃśuparyāyastathā kavacanāmakaḥ"},{"type":"verse","number":"92","sanskrit":"पर्पटो हन्ति पित्तास्रभ्रमतृष्णाकफज्वरान् संग्राही शीतलस्तिक्तो दाहनुद्वातलो लघुः","text":"parpaṭo hanti pittāsrabhramatṛṣṇākaphajvarān saṃgrāhī śītalastikto dāhanudvātalo laghuḥ"},{"type":"verse","number":"93","sanskrit":"निम्बः स्यात्पिचुमर्दश्च पिचुमन्दश्च तिक्तकः अरिष्टः पारिभद्र श्च हिङ्गुनिर्यास इत्यपि","text":"nimbaḥ syātpicumardaśca picumandaśca tiktakaḥ ariṣṭaḥ pāribhadra śca hiṅguniryāsa ityapi"},{"type":"verse","number":"94","sanskrit":"निम्बः शीतो लघुर्ग्राही कटुपाकोऽग्निवातनुत् अहृद्यः श्रमतृट्कासज्वरारुचिकृमिप्रणुत् व्रणपित्तकफच्छर्दिकुष्ठहृल्लासमेहनुत्","text":"nimbaḥ śīto laghurgrāhī kaṭupāko'gnivātanut ahṛdyaḥ śramatṛṭkāsajvarārucikṛmipraṇut vraṇapittakaphacchardikuṣṭhahṛllāsamehanut"},{"type":"verse","number":"95","sanskrit":"निम्बपत्रं स्मृतं नेत्र्! यं कृमिपित्तविषप्रणुत् वातलं कटुपाकञ्च सर्वारोचककुष्ठनुत्","text":"nimbapatraṃ smṛtaṃ netr! yaṃ kṛmipittaviṣapraṇut vātalaṃ kaṭupākañca sarvārocakakuṣṭhanut"},{"type":"verse","number":"96","sanskrit":"निम्बफलं रसे तिक्तं पाके तु कटुभेदनम् स्निग्धं लघूष्णं कुष्ठघ्नं गुल्मार्शःकृमिमेहनुत्","text":"nimbaphalaṃ rase tiktaṃ pāke tu kaṭubhedanam snigdhaṃ laghūṣṇaṃ kuṣṭhaghnaṃ gulmārśaḥkṛmimehanut"},{"type":"verse","number":"97","sanskrit":"महानिम्बः स्मृतो द्रे का रम्यको विषमुष्टिकः केशमुष्टिर्निम्बकश्च कार्मुको जीव इत्यपि","text":"mahānimbaḥ smṛto dre kā ramyako viṣamuṣṭikaḥ keśamuṣṭirnimbakaśca kārmuko jīva ityapi"},{"type":"verse","number":"98","sanskrit":"महानिम्बो हिमो रूक्षस्तिक्तो ग्राही कषायकः","text":"mahānimbo himo rūkṣastikto grāhī kaṣāyakaḥ"},{"type":"verse","number":"99","sanskrit":"प्रमेहश्वासगुल्मार्शोमूषिकाविषनाशनः","text":"pramehaśvāsagulmārśomūṣikāviṣanāśanaḥ"},{"type":"verse","number":"100","sanskrit":"पारिभद्रो निम्बतरुर्मन्दारः पारिजातकः पारिभद्रो ऽनिलश्लेष्मशोथमेदः कृमिप्रणुत् तत्पत्रं पित्तरोगघ्नं कर्णव्याधिविनाशनम् ४.","text":"pāribhadro nimbatarurmandāraḥ pārijātakaḥ pāribhadro 'nilaśleṣmaśothamedaḥ kṛmipraṇut tatpatraṃ pittarogaghnaṃ karṇavyādhivināśanam 4."},{"type":"verse","number":"101","sanskrit":"काञ्चनारः काञ्चनको गण्डारिः शोणपुष्पकः","text":"kāñcanāraḥ kāñcanako gaṇḍāriḥ śoṇapuṣpakaḥ"},{"type":"verse","number":"102","sanskrit":"कोविदारश्च मरिकः कुद्दालो युगपत्रकः कुण्डली ताम्रपुष्पश्चाश्मन्तकः स्वल्पकेशरी","text":"kovidāraśca marikaḥ kuddālo yugapatrakaḥ kuṇḍalī tāmrapuṣpaścāśmantakaḥ svalpakeśarī"},{"type":"verse","number":"103","sanskrit":"काञ्चनारो हिमो ग्राही तुवरः श्लेष्मपित्तनुत् कृमिकुष्ठगुदभ्रंशगण्डमालाव्रणापहः","text":"kāñcanāro himo grāhī tuvaraḥ śleṣmapittanut kṛmikuṣṭhagudabhraṃśagaṇḍamālāvraṇāpahaḥ"},{"type":"verse","number":"104","sanskrit":"कोविदारोऽपि तद्वत्स्यात्तयोः पुष्पं लघु स्मृतम् रूक्षं संग्राहि पित्तास्रप्रदरक्षयकासनुत्","text":"kovidāro'pi tadvatsyāttayoḥ puṣpaṃ laghu smṛtam rūkṣaṃ saṃgrāhi pittāsrapradarakṣayakāsanut"},{"type":"verse","number":"105","sanskrit":"शोभाञ्जनः शिग्रुतीक्ष्णगन्धकाक्षीवमोचकाः तद्बीजं श्वेतमरिचंमधुशिग्रुः सलोहितः शिग्रुः कटुः कटुः पाके तीक्ष्णोष्णो मधुरो लघुः","text":"śobhāñjanaḥ śigrutīkṣṇagandhakākṣīvamocakāḥ tadbījaṃ śvetamaricaṃmadhuśigruḥ salohitaḥ śigruḥ kaṭuḥ kaṭuḥ pāke tīkṣṇoṣṇo madhuro laghuḥ"},{"type":"verse","number":"106","sanskrit":"दीपनो रोचनो रूक्षः क्षारस्तिक्तो विदाहकृत् संग्राही शुक्रलो हृद्यः पित्तरक्तप्रकोपणः","text":"dīpano rocano rūkṣaḥ kṣārastikto vidāhakṛt saṃgrāhī śukralo hṛdyaḥ pittaraktaprakopaṇaḥ"},{"type":"verse","number":"107","sanskrit":"चक्षुष्यः कफवातघ्नो विद्र धिश्वयथुक्रिमीन् मेदोऽपचीविषप्लीहगुल्मगण्डव्रणान्हरेत्","text":"cakṣuṣyaḥ kaphavātaghno vidra dhiśvayathukrimīn medo'pacīviṣaplīhagulmagaṇḍavraṇānharet"},{"type":"verse","number":"108","sanskrit":"श्वेतः प्रोक्तगुणो ज्ञेयो विशेषाद्दाहकृद्भवेत् प्लीहानं विद्र धिं हन्ति व्रणघ्नः पित्तरक्तहृत् मधुशिग्रुः प्रोक्तगुणो विशेषाद्दीपनः सरः","text":"śvetaḥ proktaguṇo jñeyo viśeṣāddāhakṛdbhavet plīhānaṃ vidra dhiṃ hanti vraṇaghnaḥ pittaraktahṛt madhuśigruḥ proktaguṇo viśeṣāddīpanaḥ saraḥ"},{"type":"verse","number":"109","sanskrit":"शिग्रुवल्कलपत्राणां स्वरसः परमार्त्तिहृत्","text":"śigruvalkalapatrāṇāṃ svarasaḥ paramārttihṛt"},{"type":"verse","number":"110","sanskrit":"चक्षुष्यं शिग्रुजं बीजं तीक्ष्णोष्णं विषनाशनम् अवृष्यं कफवातघ्नं तन्नस्येन शिरोऽत्तिनुत् ४.","text":"cakṣuṣyaṃ śigrujaṃ bījaṃ tīkṣṇoṣṇaṃ viṣanāśanam avṛṣyaṃ kaphavātaghnaṃ tannasyena śiro'ttinut 4."},{"type":"verse","number":"111","sanskrit":"आस्फोता गिरिकर्णीस्याद्विष्णुक्रान्ताऽपराजिता अपराजिते कटू मेध्ये शीते कण्ठ्येसुदृष्टिदे","text":"āsphotā girikarṇīsyādviṣṇukrāntā'parājitā aparājite kaṭū medhye śīte kaṇṭhyesudṛṣṭide"},{"type":"verse","number":"112","sanskrit":"कषाये कटुके पाके तिक्ते च स्मृतिबुद्धिदे","text":"kaṣāye kaṭuke pāke tikte ca smṛtibuddhide"},{"type":"verse","number":"113","sanskrit":"सिन्दुवारः श्वेतपुष्पः सिन्दुकः सिन्दुवारकः नीलपुष्पी तु निर्गुण्डी शेफाली सुवहा च सा","text":"sinduvāraḥ śvetapuṣpaḥ sindukaḥ sinduvārakaḥ nīlapuṣpī tu nirguṇḍī śephālī suvahā ca sā"},{"type":"verse","number":"114","sanskrit":"सिन्दुकः स्मृतिदस्तिक्तः कषायः कटुको लघुः केश्यो नेत्रहितो हन्ति शूलशोथाममारुतान् कृमिकुष्ठारुचिश्लेष्मज्वरान्नीलापि तद्विधा","text":"sindukaḥ smṛtidastiktaḥ kaṣāyaḥ kaṭuko laghuḥ keśyo netrahito hanti śūlaśothāmamārutān kṛmikuṣṭhāruciśleṣmajvarānnīlāpi tadvidhā"},{"type":"verse","number":"115","sanskrit":"सिन्दुवारदलं जन्तुवातश्लेष्महरं लघु","text":"sinduvāradalaṃ jantuvātaśleṣmaharaṃ laghu"},{"type":"verse","number":"116","sanskrit":"कुटजः कूटजः कौटो वत्सको गिरिमल्लिका","text":"kuṭajaḥ kūṭajaḥ kauṭo vatsako girimallikā"},{"type":"verse","number":"117","sanskrit":"कालिङ्गः शक्रशाखी च मल्लिकापुष्प इत्यपि इन्द्रो यवफलः प्रोक्तो वृक्षकः पाण्डुरद्रुमः","text":"kāliṅgaḥ śakraśākhī ca mallikāpuṣpa ityapi indro yavaphalaḥ prokto vṛkṣakaḥ pāṇḍuradrumaḥ"},{"type":"verse","number":"118","sanskrit":"कुटजः कटुको रूक्षो दीपनस्तुवरो हिमः अर्शोऽतिसारपित्तास्नकफतृष्णाऽमकुष्ठनुत्","text":"kuṭajaḥ kaṭuko rūkṣo dīpanastuvaro himaḥ arśo'tisārapittāsnakaphatṛṣṇā'makuṣṭhanut"},{"type":"verse","number":"119","sanskrit":"करञ्जो नक्तमालश्च करजश्चिरबिल्वकः घृतपूर्णकरञ्जोऽन्य प्रकीर्यः पूतिकोऽपि च","text":"karañjo naktamālaśca karajaścirabilvakaḥ ghṛtapūrṇakarañjo'nya prakīryaḥ pūtiko'pi ca"},{"type":"verse","number":"120","sanskrit":"स चोक्तः पूतिकरञ्जः सोमवल्कश्च स स्मृतः करञ्जः कटुकस्तीक्ष्णो वीर्योष्णो योनिदोषहृत् कुष्ठोदावर्त्तगुल्मार्शोव्रणक्रिमिकफापहः ४.","text":"sa coktaḥ pūtikarañjaḥ somavalkaśca sa smṛtaḥ karañjaḥ kaṭukastīkṣṇo vīryoṣṇo yonidoṣahṛt kuṣṭhodāvarttagulmārśovraṇakrimikaphāpahaḥ 4."},{"type":"verse","number":"121","sanskrit":"तत्पत्रं कफवातार्शः कृमिशोथहरं परम् भेदनं कटुकं पाके वीर्योष्णं पित्तलं लघुः","text":"tatpatraṃ kaphavātārśaḥ kṛmiśothaharaṃ param bhedanaṃ kaṭukaṃ pāke vīryoṣṇaṃ pittalaṃ laghuḥ"},{"type":"verse","number":"122","sanskrit":"तत्फलं कफवातघ्नं मेहार्शःकृमिकुष्ठजित् घृतपूर्णकरञ्जोऽपि करञ्जसदृशो गुणैः","text":"tatphalaṃ kaphavātaghnaṃ mehārśaḥkṛmikuṣṭhajit ghṛtapūrṇakarañjo'pi karañjasadṛśo guṇaiḥ"},{"type":"verse","number":"123","sanskrit":"उदकीर्यस्तृतीयोऽन्य षड्ग्रन्था हस्तिवारुणी मर्कटी वायसी चापि करञ्जी करभञ्जिका","text":"udakīryastṛtīyo'nya ṣaḍgranthā hastivāruṇī markaṭī vāyasī cāpi karañjī karabhañjikā"},{"type":"verse","number":"124","sanskrit":"करञ्जी स्तम्भनी तिक्ता तुवरा कटुपाकिनी वीर्योष्णा वमिपित्तार्शः कृमिकुष्ठप्रमेहजित्","text":"karañjī stambhanī tiktā tuvarā kaṭupākinī vīryoṣṇā vamipittārśaḥ kṛmikuṣṭhapramehajit"},{"type":"verse","number":"125","sanskrit":"श्वेता गुञ्जोच्चटा प्रोक्ता कृष्णला चापि सा स्मृता रक्ता सा काकचिञ्ची स्यात्काकणन्ती च रक्तिका","text":"śvetā guñjoccaṭā proktā kṛṣṇalā cāpi sā smṛtā raktā sā kākaciñcī syātkākaṇantī ca raktikā"},{"type":"verse","number":"126","sanskrit":"काकादनी काकपीलुः सा स्मृता काकवल्लरी गुञ्जाद्वयन्तु केश्यं स्याद्वातपित्तज्वरापहम्","text":"kākādanī kākapīluḥ sā smṛtā kākavallarī guñjādvayantu keśyaṃ syādvātapittajvarāpaham"},{"type":"verse","number":"127","sanskrit":"नेत्रामयहरं वृष्यं बल्यं कण्डूं व्रणं हरेत्","text":"netrāmayaharaṃ vṛṣyaṃ balyaṃ kaṇḍūṃ vraṇaṃ haret"},{"type":"verse","number":"128","sanskrit":"कृमीन्द्र लुप्तकुष्ठानि रक्ता च धवलाऽपि च","text":"kṛmīndra luptakuṣṭhāni raktā ca dhavalā'pi ca"},{"type":"verse","number":"129","sanskrit":"कपिच्छूरात्मगुप्ता वृष्या प्रोक्ता च मर्कटी अजडा कण्डुरा व्यङ्गा दुःस्पर्शा प्रावृषायणी","text":"kapicchūrātmaguptā vṛṣyā proktā ca markaṭī ajaḍā kaṇḍurā vyaṅgā duḥsparśā prāvṛṣāyaṇī"},{"type":"verse","number":"130","sanskrit":"लाङ्गली शूकशिम्बी च सैव प्रोक्ता महर्षिभिः कपिकच्छूर्भृशं वृष्या मधुरा बृंहणी गुरुः तिक्ता वातहरी बल्या कफपित्तास्रनाशिनी ४.","text":"lāṅgalī śūkaśimbī ca saiva proktā maharṣibhiḥ kapikacchūrbhṛśaṃ vṛṣyā madhurā bṛṃhaṇī guruḥ tiktā vātaharī balyā kaphapittāsranāśinī 4."},{"type":"verse","number":"131","sanskrit":"तद्बीजं वातशमनं स्मृतं वाजीकरं परम्","text":"tadbījaṃ vātaśamanaṃ smṛtaṃ vājīkaraṃ param"},{"type":"verse","number":"132","sanskrit":"मांसरोहिण्यतिरुहा वृत्ता चर्मकषा वसा प्रहारवल्ली विकशा वीरवत्यपि कथ्यते स्यान्मांसरोहिणी वृष्या सरा दोषत्रयापहा","text":"māṃsarohiṇyatiruhā vṛttā carmakaṣā vasā prahāravallī vikaśā vīravatyapi kathyate syānmāṃsarohiṇī vṛṣyā sarā doṣatrayāpahā"},{"type":"verse","number":"133","sanskrit":"चिह्लकोवातनिर्हारः श्लेष्मघ्नो धातुपुष्टिकृत् आग्नेयो विषवद्यस्य फलं मत्स्यनिषूदनम्","text":"cihlakovātanirhāraḥ śleṣmaghno dhātupuṣṭikṛt āgneyo viṣavadyasya phalaṃ matsyaniṣūdanam"},{"type":"verse","number":"134","sanskrit":"टङ्कारी वातजित्तिक्ता श्लेष्मघ्नी दीपनी लघुः शोथोदरव्यथाहन्त्री हिता पीठविसर्पिणाम्","text":"ṭaṅkārī vātajittiktā śleṣmaghnī dīpanī laghuḥ śothodaravyathāhantrī hitā pīṭhavisarpiṇām"},{"type":"verse","number":"135","sanskrit":"वेतसो नम्रकः प्रोक्तो वानीरो वञ्जुलस्तथा अभ्रपुष्पश्च विदुलो रथः शीतश्च कीर्त्तितः","text":"vetaso namrakaḥ prokto vānīro vañjulastathā abhrapuṣpaśca vidulo rathaḥ śītaśca kīrttitaḥ"},{"type":"verse","number":"136","sanskrit":"वेतसः शीतलो दाहशोथार्शोयोनिरुक्प्रणुत् हन्ति वीसर्पकृच्छ्रास्रपित्ताश्मरिकफानिलान्","text":"vetasaḥ śītalo dāhaśothārśoyonirukpraṇut hanti vīsarpakṛcchrāsrapittāśmarikaphānilān"},{"type":"verse","number":"137","sanskrit":"निकुञ्जकः परिव्याधो नादेयो जलवेतसः जलजो वेतसः शीतः कुष्ठहृद्वातकोपनः","text":"nikuñjakaḥ parivyādho nādeyo jalavetasaḥ jalajo vetasaḥ śītaḥ kuṣṭhahṛdvātakopanaḥ"},{"type":"verse","number":"138","sanskrit":"इज्जलो हिज्जलश्चापि निचुलश्चाम्बुजस्तथा जलवेतसवद्वेद्यो हिज्जलोऽय विषापहः","text":"ijjalo hijjalaścāpi niculaścāmbujastathā jalavetasavadvedyo hijjalo'ya viṣāpahaḥ"},{"type":"verse","number":"139","sanskrit":"अङ्कोटो दीर्घकीलः स्यादङ्कोलश्च निकोचकः अङ्कोटकः कटुस्तीक्ष्णः स्निग्धोष्णस्तुवरो लघुः","text":"aṅkoṭo dīrghakīlaḥ syādaṅkolaśca nikocakaḥ aṅkoṭakaḥ kaṭustīkṣṇaḥ snigdhoṣṇastuvaro laghuḥ"},{"type":"verse","number":"140","sanskrit":"रेचनः कृमिशूलामशोफग्रहविषापहः विसर्पकफपित्तास्रमूषकाहिविषापहः ४.","text":"recanaḥ kṛmiśūlāmaśophagrahaviṣāpahaḥ visarpakaphapittāsramūṣakāhiviṣāpahaḥ 4."},{"type":"verse","number":"141","sanskrit":"तत्फलं शीतलं स्वादु श्लेष्मघ्नं बृंहणं गुरु बल्यं विरेचनं वातपित्तदाहक्षयास्रजित्","text":"tatphalaṃ śītalaṃ svādu śleṣmaghnaṃ bṛṃhaṇaṃ guru balyaṃ virecanaṃ vātapittadāhakṣayāsrajit"},{"type":"verse","number":"142","sanskrit":"बलावाट्यालिका वाट्या सैव वाट्यालकाऽपि च महाबला पीतपुष्पा सहदेवी च सा स्मृता","text":"balāvāṭyālikā vāṭyā saiva vāṭyālakā'pi ca mahābalā pītapuṣpā sahadevī ca sā smṛtā"},{"type":"verse","number":"143","sanskrit":"ततोऽन्याऽतिबला ऋष्यप्रोक्ता कङ्कतिका च सा गाङ्गेरुकी नागबला झषा ह्रस्वगवेधुका","text":"tato'nyā'tibalā ṛṣyaproktā kaṅkatikā ca sā gāṅgerukī nāgabalā jhaṣā hrasvagavedhukā"},{"type":"verse","number":"144","sanskrit":"बलाचतुष्टयं शीतं मधुरं बलकान्तिकृत् स्निग्धं ग्राहि समीरास्रपित्तास्रक्षतनाशनम्","text":"balācatuṣṭayaṃ śītaṃ madhuraṃ balakāntikṛt snigdhaṃ grāhi samīrāsrapittāsrakṣatanāśanam"},{"type":"verse","number":"145","sanskrit":"बलामूलत्वचश्चूर्णं पीतं सक्षीरशर्करम् मूत्रातिसारं हरति दृष्टमेतन्न संशयः","text":"balāmūlatvacaścūrṇaṃ pītaṃ sakṣīraśarkaram mūtrātisāraṃ harati dṛṣṭametanna saṃśayaḥ"},{"type":"verse","number":"146","sanskrit":"हरेन्महाबला कृच्छ्रम् भवेद्वातानुलोमिनी हन्यादतिवला मेहं पयसा सितया समम्","text":"harenmahābalā kṛcchram bhavedvātānulominī hanyādativalā mehaṃ payasā sitayā samam"},{"type":"verse","number":"147","sanskrit":"पुत्रकाकाररक्ताल्पबिन्दुभिर्लाञ्छितच्छदा","text":"putrakākāraraktālpabindubhirlāñchitacchadā"},{"type":"verse","number":"148","sanskrit":"लक्ष्मणा पुत्रजननी वस्तगन्धाकृतिर्भवेत् कथिता पुत्रदाऽवश्या लक्ष्मणा मुनिपुङ्गवैः","text":"lakṣmaṇā putrajananī vastagandhākṛtirbhavet kathitā putradā'vaśyā lakṣmaṇā munipuṅgavaiḥ"},{"type":"verse","number":"149","sanskrit":"स्वर्णवल्लीरक्तफला काकायुः काकवल्लरी स्वर्णवल्ली शिरः पीडां त्रिदोषान्हन्ति दुग्धदा","text":"svarṇavallīraktaphalā kākāyuḥ kākavallarī svarṇavallī śiraḥ pīḍāṃ tridoṣānhanti dugdhadā"},{"type":"verse","number":"150","sanskrit":"कार्पासी तुण्डकेशी च समुद्रा न्ता चकथ्यते कर्पासकी लघु कोष्णा मधुरा वातनाशिनी ४.","text":"kārpāsī tuṇḍakeśī ca samudrā ntā cakathyate karpāsakī laghu koṣṇā madhurā vātanāśinī 4."},{"type":"verse","number":"151","sanskrit":"तत्पलाशं समीरघ्नं रक्तकृन्मूत्रवर्द्धनम् तत्कर्णपिडकानादपूयास्रावविनाशनम्","text":"tatpalāśaṃ samīraghnaṃ raktakṛnmūtravarddhanam tatkarṇapiḍakānādapūyāsrāvavināśanam"},{"type":"verse","number":"152","sanskrit":"तद्बीजं स्तन्यदं वृष्यं स्निग्धं कफकरं गुरु","text":"tadbījaṃ stanyadaṃ vṛṣyaṃ snigdhaṃ kaphakaraṃ guru"},{"type":"verse","number":"153","sanskrit":"शतपर्वा यवफलो वेणुमस्करतेजनाः","text":"śataparvā yavaphalo veṇumaskaratejanāḥ"},{"type":"verse","number":"154","sanskrit":"वंशः सरो हिमः स्वादुः कषायो वस्तिशोधनः छेदनः कफपित्तघ्नः कुष्ठास्रव्रणशोथजित्","text":"vaṃśaḥ saro himaḥ svāduḥ kaṣāyo vastiśodhanaḥ chedanaḥ kaphapittaghnaḥ kuṣṭhāsravraṇaśothajit"},{"type":"verse","number":"155","sanskrit":"तत्करीरः कटुः पाके रसे रूक्षो गुरुः सरः कषायः कफकृत्स्वादुर्विदाही वातपित्तलः","text":"tatkarīraḥ kaṭuḥ pāke rase rūkṣo guruḥ saraḥ kaṣāyaḥ kaphakṛtsvādurvidāhī vātapittalaḥ"},{"type":"verse","number":"156","sanskrit":"तद्यवास्तु सरा रूक्षाः कषायाः कटुपाकिनः वातपित्तकरा उष्णा बद्धमूत्राः कफापहाः","text":"tadyavāstu sarā rūkṣāḥ kaṣāyāḥ kaṭupākinaḥ vātapittakarā uṣṇā baddhamūtrāḥ kaphāpahāḥ"},{"type":"verse","number":"157","sanskrit":"नलः पोटगलः शून्यमध्यश्च धमनस्तथा नलस्तुमधुरस्तिक्तः कषायः कफरक्तजित् उष्णो हृद्वस्तियोन्यर्त्तिदाहपित्तविसर्पहृत्","text":"nalaḥ poṭagalaḥ śūnyamadhyaśca dhamanastathā nalastumadhurastiktaḥ kaṣāyaḥ kapharaktajit uṣṇo hṛdvastiyonyarttidāhapittavisarpahṛt"},{"type":"verse","number":"158","sanskrit":"भद्र मुञ्जः शरो बाणस्तेजनश्चेक्षुवेष्टनः","text":"bhadra muñjaḥ śaro bāṇastejanaścekṣuveṣṭanaḥ"},{"type":"verse","number":"159","sanskrit":"मुञ्जो मुञ्जातको बाणः स्थूलदर्भः सुमेखलः मुञ्जद्वयन्तु मधुरं तुवरं शिशिरं तथा","text":"muñjo muñjātako bāṇaḥ sthūladarbhaḥ sumekhalaḥ muñjadvayantu madhuraṃ tuvaraṃ śiśiraṃ tathā"},{"type":"verse","number":"160","sanskrit":"दोषत्रयहरं वृष्यं मेखलासूपयुज्यते ४.","text":"doṣatrayaharaṃ vṛṣyaṃ mekhalāsūpayujyate 4."},{"type":"verse","number":"161","sanskrit":"कासः कासेक्षुरुद्दिष्टः स स्यादिक्षुरसस्तथा इक्ष्वालिकेक्षुगन्धा च तथा पोटगलः स्मृतः","text":"kāsaḥ kāsekṣuruddiṣṭaḥ sa syādikṣurasastathā ikṣvālikekṣugandhā ca tathā poṭagalaḥ smṛtaḥ"},{"type":"verse","number":"162","sanskrit":"कासः स्यान्मधुरस्तिक्तः स्वादुपाको हिमः खरः मूत्रकृच्छ्राश्मदाहास्रक्षयपित्तजरोगजित्","text":"kāsaḥ syānmadhurastiktaḥ svādupāko himaḥ kharaḥ mūtrakṛcchrāśmadāhāsrakṣayapittajarogajit"},{"type":"verse","number":"163","sanskrit":"गुन्द्र ः! पटेरको गुल्मः शृङ्गवेराभमूलकः गुन्द्र ः! कषायो मधुरः शिशिरः पित्तरक्तजित् स्तन्यशुक्ररजोमूत्रशोधनो मूत्रकृच्छ्रहृत्","text":"gundra ḥ! paṭerako gulmaḥ śṛṅgaverābhamūlakaḥ gundra ḥ! kaṣāyo madhuraḥ śiśiraḥ pittaraktajit stanyaśukrarajomūtraśodhano mūtrakṛcchrahṛt"},{"type":"verse","number":"164","sanskrit":"एरका गुन्द्र मूला च शिविर्गुन्द्रा शरीति च एरका शिशिरा वृष्या चक्षुष्या वातकोपिनी मूत्रकृच्छ्राश्मरीदाहपित्तशोणितनाशिनी","text":"erakā gundra mūlā ca śivirgundrā śarīti ca erakā śiśirā vṛṣyā cakṣuṣyā vātakopinī mūtrakṛcchrāśmarīdāhapittaśoṇitanāśinī"},{"type":"verse","number":"165","sanskrit":"कुशो दर्भस्तथा बर्हिः सूच्यग्रो यज्ञभूषणः ततोऽन्यो दीर्घपत्रः स्यात्क्षुरपत्रस्तथैव च","text":"kuśo darbhastathā barhiḥ sūcyagro yajñabhūṣaṇaḥ tato'nyo dīrghapatraḥ syātkṣurapatrastathaiva ca"},{"type":"verse","number":"166","sanskrit":"दर्भद्वयं त्रिदोषघ्नं मधुरं तुवरं हिमम् मूत्रकृच्छ्राश्मरीतृष्णावस्तिरुक्प्रदरास्रजित्","text":"darbhadvayaṃ tridoṣaghnaṃ madhuraṃ tuvaraṃ himam mūtrakṛcchrāśmarītṛṣṇāvastirukpradarāsrajit"},{"type":"verse","number":"167","sanskrit":"कत्तृणं रौहिषं देवजग्धं सौगन्धिकं तथा भूतिकं ध्यामपौरञ्च श्यामकं धूपगन्धिकम्","text":"kattṛṇaṃ rauhiṣaṃ devajagdhaṃ saugandhikaṃ tathā bhūtikaṃ dhyāmapaurañca śyāmakaṃ dhūpagandhikam"},{"type":"verse","number":"168","sanskrit":"रौहिषं तुवरं तिक्तं कटुपाकं व्यपोहति हृत्कण्ठव्याधिपित्तास्रशूलकासकफज्वरान्","text":"rauhiṣaṃ tuvaraṃ tiktaṃ kaṭupākaṃ vyapohati hṛtkaṇṭhavyādhipittāsraśūlakāsakaphajvarān"},{"type":"verse","number":"169","sanskrit":"गुह्यबीजं तु भूतीकं सुगन्धं जम्बुकप्रियम् भूतृणं तु भवेच्छत्रा मालातृणकमित्यपि","text":"guhyabījaṃ tu bhūtīkaṃ sugandhaṃ jambukapriyam bhūtṛṇaṃ tu bhavecchatrā mālātṛṇakamityapi"},{"type":"verse","number":"170","sanskrit":"भूतृणं कटुकं तिक्तं तीक्ष्णोष्णं रेचनं लघु विदाहि दीपनं रूक्षमनेत्र्! यं मुखशोधनम् ४.","text":"bhūtṛṇaṃ kaṭukaṃ tiktaṃ tīkṣṇoṣṇaṃ recanaṃ laghu vidāhi dīpanaṃ rūkṣamanetr! yaṃ mukhaśodhanam 4."},{"type":"verse","number":"171","sanskrit":"अवृष्यं बहुविट्कञ्च पित्तरक्तप्रदूषणम्","text":"avṛṣyaṃ bahuviṭkañca pittaraktapradūṣaṇam"},{"type":"verse","number":"172","sanskrit":"नीलदूर्बा रुहाऽनन्ता भार्गवी शतपर्विका शष्पं सहस्रवीर्या च शतवल्ली च कीर्त्तिता","text":"nīladūrbā ruhā'nantā bhārgavī śataparvikā śaṣpaṃ sahasravīryā ca śatavallī ca kīrttitā"},{"type":"verse","number":"173","sanskrit":"नीलदूर्वा हिमा तिक्ता मधुरा तुवरा हरेत् कफपित्तास्रवीसर्पतृष्णादाहत्वगामयान्","text":"nīladūrvā himā tiktā madhurā tuvarā haret kaphapittāsravīsarpatṛṣṇādāhatvagāmayān"},{"type":"verse","number":"174","sanskrit":"दूर्वा शुक्ला तु गोलोमी शतवीर्या च कथ्यते श्वेता दूर्वा कषाया स्यात्स्वाद्वी व्रण्या च जीवनी तिक्ता हिमा विसर्पास्रतृट्पित्तकफदाहहृत्","text":"dūrvā śuklā tu golomī śatavīryā ca kathyate śvetā dūrvā kaṣāyā syātsvādvī vraṇyā ca jīvanī tiktā himā visarpāsratṛṭpittakaphadāhahṛt"},{"type":"verse","number":"175","sanskrit":"गण्डदूर्वा तु गण्डाली मत्स्याक्षी शकुलादनी गण्डदूर्वा हिमा लोहद्रा विणी ग्राहिणी लघुः","text":"gaṇḍadūrvā tu gaṇḍālī matsyākṣī śakulādanī gaṇḍadūrvā himā lohadrā viṇī grāhiṇī laghuḥ"},{"type":"verse","number":"176","sanskrit":"तिक्ता कषाया मधुरा वातकृत्कटुपाकिनी दाहतृष्णाबलासास्रकुष्ठपित्तज्वरापहा","text":"tiktā kaṣāyā madhurā vātakṛtkaṭupākinī dāhatṛṣṇābalāsāsrakuṣṭhapittajvarāpahā"},{"type":"verse","number":"177","sanskrit":"वाराहीकन्दसंज्ञस्तु पश्चिमे गृष्टिसंज्ञकः वाराहीकन्द एवान्यैश्चर्मकारालुको मतः","text":"vārāhīkandasaṃjñastu paścime gṛṣṭisaṃjñakaḥ vārāhīkanda evānyaiścarmakārāluko mataḥ"},{"type":"verse","number":"178","sanskrit":"अनूपसम्भवे देशे वराह इव लोमवान् वाराहवदना गृष्टिर्वरदेत्यपि कथ्यते","text":"anūpasambhave deśe varāha iva lomavān vārāhavadanā gṛṣṭirvaradetyapi kathyate"},{"type":"verse","number":"179","sanskrit":"वाराही तु रसे स्वाद्वी तिक्ता पाके पुनः कटुः शुक्रायुःस्वरवर्णाग्निबलपित्तविवर्द्धिनी कफकुष्ठमरुन्मेहकृमिहृच्च रसायनी","text":"vārāhī tu rase svādvī tiktā pāke punaḥ kaṭuḥ śukrāyuḥsvaravarṇāgnibalapittavivarddhinī kaphakuṣṭhamarunmehakṛmihṛcca rasāyanī"},{"type":"verse","number":"180","sanskrit":"विदारी स्वादुकन्दा च सा तु क्रोष्ट्रीसिता स्मृता इक्षुगन्धा क्षीरवल्ली क्षीरशुक्ला पयस्विनी ४.","text":"vidārī svādukandā ca sā tu kroṣṭrīsitā smṛtā ikṣugandhā kṣīravallī kṣīraśuklā payasvinī 4."},{"type":"verse","number":"181","sanskrit":"विदारी मधुरा स्निग्धा बृंहणी स्तन्यशुक्रदा","text":"vidārī madhurā snigdhā bṛṃhaṇī stanyaśukradā"},{"type":"verse","number":"182","sanskrit":"शीता स्वर्या मूत्रला च जीवनी बलवर्णदा गुरुः पित्तास्रपवनदाहान् हन्ति रसायनी","text":"śītā svaryā mūtralā ca jīvanī balavarṇadā guruḥ pittāsrapavanadāhān hanti rasāyanī"},{"type":"verse","number":"183","sanskrit":"तालमूली तु विद्वद्भिर्मुशली परिकीर्त्तिता मुशली मधुरा वृष्या वीर्योष्णा बृंहणी गुरुः तिक्ता रसायनी हन्ति गुदजान्यनिलं तथा","text":"tālamūlī tu vidvadbhirmuśalī parikīrttitā muśalī madhurā vṛṣyā vīryoṣṇā bṛṃhaṇī guruḥ tiktā rasāyanī hanti gudajānyanilaṃ tathā"},{"type":"verse","number":"184","sanskrit":"शतावरी बुहसुता भीरुरिन्दीवरी वरी नारायणी शतपदी शतवीर्या च पीवरी","text":"śatāvarī buhasutā bhīrurindīvarī varī nārāyaṇī śatapadī śatavīryā ca pīvarī"},{"type":"verse","number":"185","sanskrit":"महाशतावरी चान्या शतमूल्यूर्ध्वकण्टिका सहस्रवीर्या हेतुश्च ऋष्यप्रोक्ता महोदरी","text":"mahāśatāvarī cānyā śatamūlyūrdhvakaṇṭikā sahasravīryā hetuśca ṛṣyaproktā mahodarī"},{"type":"verse","number":"186","sanskrit":"शतावरी गुरुः शीता तिक्ता स्वाद्वी रसायनी मेधाऽग्निपुष्टिदा स्निग्धा नेत्र्! या गुल्मातिसारजित्","text":"śatāvarī guruḥ śītā tiktā svādvī rasāyanī medhā'gnipuṣṭidā snigdhā netr! yā gulmātisārajit"},{"type":"verse","number":"187","sanskrit":"शुक्रस्तन्यकरी बल्या वातपित्तास्रशोथजित् महाशतावरी मेध्या हृद्या वृष्या रसायनी","text":"śukrastanyakarī balyā vātapittāsraśothajit mahāśatāvarī medhyā hṛdyā vṛṣyā rasāyanī"},{"type":"verse","number":"188","sanskrit":"शीतवीर्या निहन्त्यर्शोग्रहणीनयनामयान् तदङ्कुरस्रिदोषघ्नो लघुरर्शःक्षयापहा","text":"śītavīryā nihantyarśograhaṇīnayanāmayān tadaṅkurasridoṣaghno laghurarśaḥkṣayāpahā"},{"type":"verse","number":"189","sanskrit":"गन्धान्ता वाजिनामादिरश्वगन्धा हयाह्वया वराहकर्णी वरदा बलदा कुष्ठगन्धिनी","text":"gandhāntā vājināmādiraśvagandhā hayāhvayā varāhakarṇī varadā baladā kuṣṭhagandhinī"},{"type":"verse","number":"190","sanskrit":"बल्या रसायनी तिक्ता कषायोष्णाऽतिशुक्रला ४.","text":"balyā rasāyanī tiktā kaṣāyoṣṇā'tiśukralā 4."},{"type":"verse","number":"191","sanskrit":"पाठाऽम्बष्ठाऽम्बष्ठकी च प्राचीना पापचेलिका एकाष्ठीला रसा प्रोक्ता पाठिका वरतिक्तिका","text":"pāṭhā'mbaṣṭhā'mbaṣṭhakī ca prācīnā pāpacelikā ekāṣṭhīlā rasā proktā pāṭhikā varatiktikā"},{"type":"verse","number":"193","sanskrit":"पाठोष्णा कटुका तीक्ष्णा वातश्लेष्महरी लघुः हन्ति शूलज्वरच्छर्दिकुष्ठातीसारहृद्रुजः दाहकण्डूविषश्वासकृमिगुल्मगरव्रणान्","text":"pāṭhoṣṇā kaṭukā tīkṣṇā vātaśleṣmaharī laghuḥ hanti śūlajvaracchardikuṣṭhātīsārahṛdrujaḥ dāhakaṇḍūviṣaśvāsakṛmigulmagaravraṇān"},{"type":"verse","number":"193","sanskrit":"श्वेता त्रिर्वृत् त्रिभण्डी स्यात् त्रिवृतात्रिपुटाऽपि च सर्वानुभूतिः सरला निशोत्रा रेचनीति च","text":"śvetā trirvṛt tribhaṇḍī syāt trivṛtātripuṭā'pi ca sarvānubhūtiḥ saralā niśotrā recanīti ca"},{"type":"verse","number":"194","sanskrit":"श्वेता त्रिवृद्रे चनी स्यात्स्वादुरुष्णा समीरहृत् रूक्षा पित्तज्वरश्लेष्मपित्तशोथोदरापहा","text":"śvetā trivṛdre canī syātsvāduruṣṇā samīrahṛt rūkṣā pittajvaraśleṣmapittaśothodarāpahā"},{"type":"verse","number":"195","sanskrit":"त्रिवृच्छ्यामाऽद्धचन्द्रा च पालिन्दी च सुषेणिका मसूरविदला काली कैषिका कालमेषिका","text":"trivṛcchyāmā'ddhacandrā ca pālindī ca suṣeṇikā masūravidalā kālī kaiṣikā kālameṣikā"},{"type":"verse","number":"196","sanskrit":"श्यामा त्रिवृत्ततो हीनगुणा तीव्रविरेचिनी मूर्च्छादाहमदभ्रान्तिकण्ठोत्कर्षणकारिणी","text":"śyāmā trivṛttato hīnaguṇā tīvravirecinī mūrcchādāhamadabhrāntikaṇṭhotkarṣaṇakāriṇī"},{"type":"verse","number":"197","sanskrit":"लघुदन्ती विशल्या च स्यादुदुम्बरपर्ण्यपि तथैरण्डफला शीघ्रा श्वेतघण्टा घुणप्रिया","text":"laghudantī viśalyā ca syādudumbaraparṇyapi tathairaṇḍaphalā śīghrā śvetaghaṇṭā ghuṇapriyā"},{"type":"verse","number":"198","sanskrit":"वाराहाङ्गी च कथिता निकुम्भश्च मकूलकः द्र वन्ती शम्बरी चित्रा प्रत्यक्पर्ण्याखुपर्ण्यपि","text":"vārāhāṅgī ca kathitā nikumbhaśca makūlakaḥ dra vantī śambarī citrā pratyakparṇyākhuparṇyapi"},{"type":"verse","number":"199","sanskrit":"उपचित्रा श्रुतश्रोणी न्यग्रोधी च तथा वृषा दन्तीद्वयं सरं पाकं रसे च कटु दीपनम्","text":"upacitrā śrutaśroṇī nyagrodhī ca tathā vṛṣā dantīdvayaṃ saraṃ pākaṃ rase ca kaṭu dīpanam"},{"type":"verse","number":"200","sanskrit":"तीक्ष्णोष्णं हन्ति पित्तास्रकफशोथोदरक्रिमीन् ४.","text":"tīkṣṇoṣṇaṃ hanti pittāsrakaphaśothodarakrimīn 4."},{"type":"verse","number":"201","sanskrit":"क्षुद्र दन्तीफलं तु स्यान्मधुरं रसपाकयोः शीतलं सृष्टविण्मूत्रं गरशोथकफापहम्","text":"kṣudra dantīphalaṃ tu syānmadhuraṃ rasapākayoḥ śītalaṃ sṛṣṭaviṇmūtraṃ garaśothakaphāpaham"},{"type":"verse","number":"202","sanskrit":"जयपालो दन्तिबीजं विख्यातं तिन्तिडीफलम् जयपालो गुरुः स्निग्धो रेची पित्तकफापहः","text":"jayapālo dantibījaṃ vikhyātaṃ tintiḍīphalam jayapālo guruḥ snigdho recī pittakaphāpahaḥ"},{"type":"verse","number":"203","sanskrit":"अथेन्द्र वारुणी महेन्द्र वारुणी च एन्द्री न्द्र वारुणी चित्रा गवाक्षी च गवादनी वारुणी च पराऽप्युक्ता सा विशाला महाफला","text":"athendra vāruṇī mahendra vāruṇī ca endrī ndra vāruṇī citrā gavākṣī ca gavādanī vāruṇī ca parā'pyuktā sā viśālā mahāphalā"},{"type":"verse","number":"204","sanskrit":"श्वेतपुष्पा मृगाक्षी च मृगैर्वारुर्मृगादनी गवादनीद्वयं तिक्तं पाके कटु सरं लघु","text":"śvetapuṣpā mṛgākṣī ca mṛgairvārurmṛgādanī gavādanīdvayaṃ tiktaṃ pāke kaṭu saraṃ laghu"},{"type":"verse","number":"205","sanskrit":"वीर्योष्णं कामलापित्तकफप्लीहोदरापहम्","text":"vīryoṣṇaṃ kāmalāpittakaphaplīhodarāpaham"},{"type":"verse","number":"206","sanskrit":"श्वासकासापहं कुष्ठगुल्मग्रन्थिव्रणप्रणुत् प्रमेहमूढगर्भामगण्डामयविषापहम्","text":"śvāsakāsāpahaṃ kuṣṭhagulmagranthivraṇapraṇut pramehamūḍhagarbhāmagaṇḍāmayaviṣāpaham"},{"type":"verse","number":"207","sanskrit":"नीली तु नीलिनी तूणी काला दोला च नीलिका रञ्जनी श्रीफली तुच्छा ग्रामीणा मधुपर्णिका","text":"nīlī tu nīlinī tūṇī kālā dolā ca nīlikā rañjanī śrīphalī tucchā grāmīṇā madhuparṇikā"},{"type":"verse","number":"208","sanskrit":"क्लीतका कालकेशी च नीलपुष्पा च सा स्मृता नीलिनी रेचनी तिक्ता केश्या मोहभ्रमापहा","text":"klītakā kālakeśī ca nīlapuṣpā ca sā smṛtā nīlinī recanī tiktā keśyā mohabhramāpahā"},{"type":"verse","number":"209","sanskrit":"उष्णा हन्त्युदरप्लीहवातरक्तकफानिलान् आमवातमुदावर्त्तं मदं च विषमुद्धतम्","text":"uṣṇā hantyudaraplīhavātaraktakaphānilān āmavātamudāvarttaṃ madaṃ ca viṣamuddhatam"},{"type":"verse","number":"210","sanskrit":"शरपुङ्खः प्लीहशत्रुर्नीलीवृक्षाकृतिश्च सः शरपुङ्खो यकृत्प्लीहगुल्मव्रणविषापहः तिक्तः कषायः कासास्रश्वासज्वरहरो लघुः ४.","text":"śarapuṅkhaḥ plīhaśatrurnīlīvṛkṣākṛtiśca saḥ śarapuṅkho yakṛtplīhagulmavraṇaviṣāpahaḥ tiktaḥ kaṣāyaḥ kāsāsraśvāsajvaraharo laghuḥ 4."},{"type":"verse","number":"1","sanskrit":"विऋ!द्धदारुक आवेगी छागान्त्री वृष्यगन्धिका वृद्धद्वारुः कषायोष्णः कटुस्तिक्तो रसायनः","text":"viṛ!ddhadāruka āvegī chāgāntrī vṛṣyagandhikā vṛddhadvāruḥ kaṣāyoṣṇaḥ kaṭustikto rasāyanaḥ"},{"type":"verse","number":"2","sanskrit":"वृष्यो वातामवातार्शः शोथमेहकफप्रणुत् शुक्रायुर्बलमेधाऽग्निस्वरकान्तिकरःसरः","text":"vṛṣyo vātāmavātārśaḥ śothamehakaphapraṇut śukrāyurbalamedhā'gnisvarakāntikaraḥsaraḥ"},{"type":"verse","number":"211","sanskrit":"थासो यवासो दुःस्पर्शो धन्वयासः कुनाशकः दुरालभा दुरालम्भा समुद्रा न्ता च रोदिनी","text":"thāso yavāso duḥsparśo dhanvayāsaḥ kunāśakaḥ durālabhā durālambhā samudrā ntā ca rodinī"},{"type":"verse","number":"212","sanskrit":"गान्धारी कच्छुराऽनन्ता काषाया हरिविग्रहा यासः स्वादुः सरस्तिक्तस्तुवरः शीतलो लघुः","text":"gāndhārī kacchurā'nantā kāṣāyā harivigrahā yāsaḥ svāduḥ sarastiktastuvaraḥ śītalo laghuḥ"},{"type":"verse","number":"213","sanskrit":"तृष्णाविसर्पवातास्रवमिज्वरहरः स्मृतः","text":"tṛṣṇāvisarpavātāsravamijvaraharaḥ smṛtaḥ"},{"type":"verse","number":"214","sanskrit":"यवासस्य गुर्णैस्तुल्या बुधैरुक्ता दुरालभा","text":"yavāsasya gurṇaistulyā budhairuktā durālabhā"},{"type":"verse","number":"215","sanskrit":"मुण्डी भिक्षुरपि प्रोक्ता श्रावणी च तपोधना श्रवणाह्वा मुण्डतिका तथा श्रवणशीर्षका","text":"muṇḍī bhikṣurapi proktā śrāvaṇī ca tapodhanā śravaṇāhvā muṇḍatikā tathā śravaṇaśīrṣakā"},{"type":"verse","number":"216","sanskrit":"महाश्रावणिकाऽन्या तु सा स्मृता भूकदम्बिका कदम्बपुष्पिका च स्यादव्यथाऽतितपस्विनी","text":"mahāśrāvaṇikā'nyā tu sā smṛtā bhūkadambikā kadambapuṣpikā ca syādavyathā'titapasvinī"},{"type":"verse","number":"217","sanskrit":"मुण्डतिका कटुः पाके वीर्योष्णा मधुरा लघुः मेध्या गण्डापचीकृच्छ्रकृमियोन्यर्त्तिपाण्डुनुत्","text":"muṇḍatikā kaṭuḥ pāke vīryoṣṇā madhurā laghuḥ medhyā gaṇḍāpacīkṛcchrakṛmiyonyarttipāṇḍunut"},{"type":"verse","number":"218","sanskrit":"महामुण्डी च तत्तुल्या गुणैरुक्ता महर्षिभिः","text":"mahāmuṇḍī ca tattulyā guṇairuktā maharṣibhiḥ"},{"type":"verse","number":"219","sanskrit":"अपामार्गस्तु शिखरी ह्यधः शल्यो मयूरकः मर्कटी दुर्ग्रहा चापि किणिही खरमञ्जरी","text":"apāmārgastu śikharī hyadhaḥ śalyo mayūrakaḥ markaṭī durgrahā cāpi kiṇihī kharamañjarī"},{"type":"verse","number":"220","sanskrit":"अपामार्गः सरस्तीक्ष्णो दीपनस्तिक्तकः कटुः पाचनो रोचनश्छर्दिकफमेदोऽनिलापहः निहन्ति हृद्रुजाध्मार्शः कण्डूशूलोदरापचीः ४.","text":"apāmārgaḥ sarastīkṣṇo dīpanastiktakaḥ kaṭuḥ pācano rocanaśchardikaphamedo'nilāpahaḥ nihanti hṛdrujādhmārśaḥ kaṇḍūśūlodarāpacīḥ 4."},{"type":"verse","number":"221","sanskrit":"रक्तोऽन्यो वशिरो वृत्तफलो धामार्गवोऽपि च प्रत्यक्पर्णी केशपर्णी कथिता कपिपिप्पली","text":"rakto'nyo vaśiro vṛttaphalo dhāmārgavo'pi ca pratyakparṇī keśaparṇī kathitā kapipippalī"},{"type":"verse","number":"222","sanskrit":"अपामार्गोऽरुणो वातविष्टम्भी कफहृद्धिमः रूक्षः पूर्वगुणैर्न्यूनः कथितो गुणवेदिभिः","text":"apāmārgo'ruṇo vātaviṣṭambhī kaphahṛddhimaḥ rūkṣaḥ pūrvaguṇairnyūnaḥ kathito guṇavedibhiḥ"},{"type":"verse","number":"223","sanskrit":"अपामार्गफलं स्वादु रसे पाके च दुर्जरम् विष्टम्भि वातलं रूक्षं रक्तपित्तप्रसादनम्","text":"apāmārgaphalaṃ svādu rase pāke ca durjaram viṣṭambhi vātalaṃ rūkṣaṃ raktapittaprasādanam"},{"type":"verse","number":"224","sanskrit":"कोकिलाक्षस्तु काकेक्षुरिक्षुरः क्षुरकः क्षुरः भिक्षुः काण्डेक्षुरप्युक्त इक्षुगन्धेक्षुबालिका","text":"kokilākṣastu kākekṣurikṣuraḥ kṣurakaḥ kṣuraḥ bhikṣuḥ kāṇḍekṣurapyukta ikṣugandhekṣubālikā"},{"type":"verse","number":"225","sanskrit":"क्षुरकः शीतलो वृप्यः स्वाद्वम्लः पिच्छिलस्तथा तिक्तो वातामशोथाश्मतृष्णादृष्ट्यनिलास्रजित्","text":"kṣurakaḥ śītalo vṛpyaḥ svādvamlaḥ picchilastathā tikto vātāmaśothāśmatṛṣṇādṛṣṭyanilāsrajit"},{"type":"verse","number":"226","sanskrit":"अस्थिसंहारकः प्रोक्तो वातश्लेष्महरोऽस्थियुक्","text":"asthisaṃhārakaḥ prokto vātaśleṣmaharo'sthiyuk"},{"type":"verse","number":"227","sanskrit":"उष्णः सरः कृमिघ्नश्चदुर्नामघ्नोऽक्षिरोगजित् रूक्षः स्वादुर्लघुर्वृष्यः पाचनः पित्तलः स्मृतः","text":"uṣṇaḥ saraḥ kṛmighnaścadurnāmaghno'kṣirogajit rūkṣaḥ svādurlaghurvṛṣyaḥ pācanaḥ pittalaḥ smṛtaḥ"},{"type":"verse","number":"228","sanskrit":"काण्डं त्वग्विरहितमस्थिशृङ्खलायामाषार्द्र द्विदलमकञ्चुकं तदर्द्धम् संपिष्टं सुतनु ततस्तिलस्य तैलेसंपक्वं वटकमतीव वातहारि","text":"kāṇḍaṃ tvagvirahitamasthiśṛṅkhalāyāmāṣārdra dvidalamakañcukaṃ tadarddham saṃpiṣṭaṃ sutanu tatastilasya tailesaṃpakvaṃ vaṭakamatīva vātahāri"},{"type":"verse","number":"229","sanskrit":"कुमारी गृहकन्या च कन्या घृतकुमारिका कुमारी भेदनी शीता तिक्ता नेत्र्! या रसायनी","text":"kumārī gṛhakanyā ca kanyā ghṛtakumārikā kumārī bhedanī śītā tiktā netr! yā rasāyanī"},{"type":"verse","number":"230","sanskrit":"मधुरा बृंहणी बल्या वृष्या वातविषप्रणुत् गुल्मप्लीहयकृद्वृद्धिकफज्वरहरी हरेत् ग्रन्थ्यग्निदग्धविस्फोटपित्तरक्तत्वगामयान् ४.","text":"madhurā bṛṃhaṇī balyā vṛṣyā vātaviṣapraṇut gulmaplīhayakṛdvṛddhikaphajvaraharī haret granthyagnidagdhavisphoṭapittaraktatvagāmayān 4."},{"type":"verse","number":"231","sanskrit":"पुनर्नवा श्वेतमूला शोथघ्नी दीर्घपत्रिका कटु कषायानुरसा पाण्डुघ्नी दीपनी परा शोफानिलगरश्लेष्महरी ब्रघ्नोदरप्रणुत्","text":"punarnavā śvetamūlā śothaghnī dīrghapatrikā kaṭu kaṣāyānurasā pāṇḍughnī dīpanī parā śophānilagaraśleṣmaharī braghnodarapraṇut"},{"type":"verse","number":"232","sanskrit":"पुनर्नवाऽपरा रक्ता रक्तपुष्पा शिलाटिका शोथघ्नी क्षुद्र वर्षाभूर्वर्षकेतुः कठिल्लकः","text":"punarnavā'parā raktā raktapuṣpā śilāṭikā śothaghnī kṣudra varṣābhūrvarṣaketuḥ kaṭhillakaḥ"},{"type":"verse","number":"233","sanskrit":"पुनर्नवाऽरुणा तिक्ता कटुपाका हिमा लघुः वातला ग्राहिणी श्लेष्मपित्तरक्तविनाशिनी","text":"punarnavā'ruṇā tiktā kaṭupākā himā laghuḥ vātalā grāhiṇī śleṣmapittaraktavināśinī"},{"type":"verse","number":"234","sanskrit":"प्रसारणी राजबला भद्र पर्णी प्रतानिनी सरणी सारणी भद्रा बला चापि कटम्भरा","text":"prasāraṇī rājabalā bhadra parṇī pratāninī saraṇī sāraṇī bhadrā balā cāpi kaṭambharā"},{"type":"verse","number":"235","sanskrit":"प्रसारणी गुरुर्वृष्या वलसन्धानकृत्सरा वीर्योष्णा वातहृत्तिक्ता वातरक्तकफापहा","text":"prasāraṇī gururvṛṣyā valasandhānakṛtsarā vīryoṣṇā vātahṛttiktā vātaraktakaphāpahā"},{"type":"verse","number":"236","sanskrit":"कृष्णा तु शारिवा श्यामा गोपी गोपवधूश्च सा","text":"kṛṣṇā tu śārivā śyāmā gopī gopavadhūśca sā"},{"type":"verse","number":"237","sanskrit":"धवला शारिवा गोपा गोपकन्या कृशोदरी स्फोटा श्यामा गोपवल्ली लताऽस्फोता च चन्दना","text":"dhavalā śārivā gopā gopakanyā kṛśodarī sphoṭā śyāmā gopavallī latā'sphotā ca candanā"},{"type":"verse","number":"238","sanskrit":"सारिवायुगलं स्वादु स्निग्धं शुक्रकरं गुरु अग्निमान्द्यारुचिश्वासकासामविषनाशनम् दोषत्रयास्रप्रदरज्वरातीसारनाशनम्","text":"sārivāyugalaṃ svādu snigdhaṃ śukrakaraṃ guru agnimāndyāruciśvāsakāsāmaviṣanāśanam doṣatrayāsrapradarajvarātīsāranāśanam"},{"type":"verse","number":"239","sanskrit":"भृङ्गराजो भृङ्गरजो मार्कवो भृङ्ग एव च अङ्गारकः केशराजो भृङ्गारः केशरञ्जनः","text":"bhṛṅgarājo bhṛṅgarajo mārkavo bhṛṅga eva ca aṅgārakaḥ keśarājo bhṛṅgāraḥ keśarañjanaḥ"},{"type":"verse","number":"240","sanskrit":"भृङ्गारः कटुकस्तीक्ष्णो रूक्षोष्णः कफवातनुत् ४.","text":"bhṛṅgāraḥ kaṭukastīkṣṇo rūkṣoṣṇaḥ kaphavātanut 4."},{"type":"verse","number":"241","sanskrit":"केश्यस्त्वच्यः कृमिश्वासकासशोथामपाण्डुनुत् दन्त्यो रसायनो बल्यः कुष्ठनेत्रशिरोऽत्तिनुत्","text":"keśyastvacyaḥ kṛmiśvāsakāsaśothāmapāṇḍunut dantyo rasāyano balyaḥ kuṣṭhanetraśiro'ttinut"},{"type":"verse","number":"242","sanskrit":"शणपुष्पी स्मृता घण्टा शणपुष्पसमाकृतिः शणपुष्पी कटुस्तिक्ता वामिनी कफपित्तजित्","text":"śaṇapuṣpī smṛtā ghaṇṭā śaṇapuṣpasamākṛtiḥ śaṇapuṣpī kaṭustiktā vāminī kaphapittajit"},{"type":"verse","number":"243","sanskrit":"बलभद्रा त्रायमाणा त्रायन्ती गिरिजाऽनुजा त्रायन्ती तुवरा तिक्ता सरा पित्तकफापहा ज्वरहृद्रो गगुल्मार्शोभ्रमशूलविषप्रणुत्","text":"balabhadrā trāyamāṇā trāyantī girijā'nujā trāyantī tuvarā tiktā sarā pittakaphāpahā jvarahṛdro gagulmārśobhramaśūlaviṣapraṇut"},{"type":"verse","number":"244","sanskrit":"मूर्वा मधुरसा देवी मोरटा तेजनी स्रुवा मधुलिका मधुश्रेणी गोकर्णी पीलुपर्ण्यपि","text":"mūrvā madhurasā devī moraṭā tejanī sruvā madhulikā madhuśreṇī gokarṇī pīluparṇyapi"},{"type":"verse","number":"245","sanskrit":"मूर्वा सरा गुरुः स्वादुस्तिक्ता पित्तास्रमेहनुत् त्रिदोषतृष्णाहृद्रो गकण्डूकुष्ठज्वरापहाः","text":"mūrvā sarā guruḥ svādustiktā pittāsramehanut tridoṣatṛṣṇāhṛdro gakaṇḍūkuṣṭhajvarāpahāḥ"},{"type":"verse","number":"246","sanskrit":"काकमाची ध्वाङ्क्षमाची काकाह्वा चैव वायसी काकमाची त्रिदोषघ्नी स्निग्धोष्णा स्वरशुक्रदा","text":"kākamācī dhvāṅkṣamācī kākāhvā caiva vāyasī kākamācī tridoṣaghnī snigdhoṣṇā svaraśukradā"},{"type":"verse","number":"247","sanskrit":"तिक्ता रसायनी शोथकुष्टार्शोज्वरमेहजित् कटुर्नेत्रहिता हिक्काच्छर्दिहृद्रो गनाशिनी","text":"tiktā rasāyanī śothakuṣṭārśojvaramehajit kaṭurnetrahitā hikkācchardihṛdro ganāśinī"},{"type":"verse","number":"248","sanskrit":"काकनासा तु काकाङ्गी काकतुण्डफला च सा","text":"kākanāsā tu kākāṅgī kākatuṇḍaphalā ca sā"},{"type":"verse","number":"249","sanskrit":"काकनासा कषायोष्णा कटुका रसपाकयोः कफघ्नी वामनी तिक्ता शोथार्शश्वित्रकुष्ठहृत्","text":"kākanāsā kaṣāyoṣṇā kaṭukā rasapākayoḥ kaphaghnī vāmanī tiktā śothārśaśvitrakuṣṭhahṛt"},{"type":"verse","number":"250","sanskrit":"काकजङ्घा नदीकान्ता काकतिक्ता सुलोमशा पारावतपदी दासी काका चापि प्रकीर्त्तिता ४.","text":"kākajaṅghā nadīkāntā kākatiktā sulomaśā pārāvatapadī dāsī kākā cāpi prakīrttitā 4."},{"type":"verse","number":"251","sanskrit":"काकजंघा हिमा तिक्ता कषाया कफपित्तजित् निहन्ति ज्वरपित्तास्रव्रणकण्डूविषक्रिमीन्","text":"kākajaṃghā himā tiktā kaṣāyā kaphapittajit nihanti jvarapittāsravraṇakaṇḍūviṣakrimīn"},{"type":"verse","number":"252","sanskrit":"नागपुष्पी श्वेत पुष्पा नागिनी रामदूतिका नागिनी रोचनी तिक्ता तीक्ष्णोष्णा कफपित्तनुत् विनिहन्ति विषं शूलं योनिदोषवमिक्रिमीन्","text":"nāgapuṣpī śveta puṣpā nāginī rāmadūtikā nāginī rocanī tiktā tīkṣṇoṣṇā kaphapittanut vinihanti viṣaṃ śūlaṃ yonidoṣavamikrimīn"},{"type":"verse","number":"253","sanskrit":"मेषशृङ्गी विषाणी स्यान्मेषवल्ल्यजशृङ्गिका मेषशृङ्गी रसे तिक्ता वातला श्वासकासहृत्","text":"meṣaśṛṅgī viṣāṇī syānmeṣavallyajaśṛṅgikā meṣaśṛṅgī rase tiktā vātalā śvāsakāsahṛt"},{"type":"verse","number":"254","sanskrit":"रूक्षा पाके कटुः पित्तव्रणश्लेष्माक्षिशूलनुत्","text":"rūkṣā pāke kaṭuḥ pittavraṇaśleṣmākṣiśūlanut"},{"type":"verse","number":"255","sanskrit":"मेषशृङ्गीफलं तिक्तं कुष्ठमेहकफप्रणुत् दीपनं स्रंसनं कासक्रिमिव्रणविषापहम्","text":"meṣaśṛṅgīphalaṃ tiktaṃ kuṣṭhamehakaphapraṇut dīpanaṃ sraṃsanaṃ kāsakrimivraṇaviṣāpaham"},{"type":"verse","number":"256","sanskrit":"हंसपादी हंसपदी कीटमाता त्रिपादिका हंसपादी गुरुः शीता हन्ति रक्तविषव्रणान् विसर्पदाहातीसारलूताभूताग्निरोहिणीः","text":"haṃsapādī haṃsapadī kīṭamātā tripādikā haṃsapādī guruḥ śītā hanti raktaviṣavraṇān visarpadāhātīsāralūtābhūtāgnirohiṇīḥ"},{"type":"verse","number":"257","sanskrit":"सोमवल्ली सोमलता सोमक्षीरी द्विजप्रिया सोमवल्ली त्रिदोषघ्नी कटुस्तिक्ता रसायनी","text":"somavallī somalatā somakṣīrī dvijapriyā somavallī tridoṣaghnī kaṭustiktā rasāyanī"},{"type":"verse","number":"258","sanskrit":"आकाशवल्ली तु बुधैः कथिताऽमरवल्लरी","text":"ākāśavallī tu budhaiḥ kathitā'maravallarī"},{"type":"verse","number":"259","sanskrit":"खवल्ली ग्राहिणी तिक्ता पिच्छिलाऽक्ष्यामयापहा तुवराऽग्निकरी हृद्या पित्तश्लेष्मामनाशिनी","text":"khavallī grāhiṇī tiktā picchilā'kṣyāmayāpahā tuvarā'gnikarī hṛdyā pittaśleṣmāmanāśinī"},{"type":"verse","number":"260","sanskrit":"छिलिहिण्टो महामूलःपातालगरुडाह्वयः छिलिहिण्टः परं वृष्यः कफघ्नः पवनापहः ४.","text":"chilihiṇṭo mahāmūlaḥpātālagaruḍāhvayaḥ chilihiṇṭaḥ paraṃ vṛṣyaḥ kaphaghnaḥ pavanāpahaḥ 4."},{"type":"verse","number":"261","sanskrit":"वन्दा वृक्षादनी वृक्षभक्ष्या वृक्षरुहाऽपि च वन्दाकः स्याद्धिमस्तिक्तः कषायो मधुरो रसे मङ्गल्यः कफवातास्ररक्षोव्रणविषापहः","text":"vandā vṛkṣādanī vṛkṣabhakṣyā vṛkṣaruhā'pi ca vandākaḥ syāddhimastiktaḥ kaṣāyo madhuro rase maṅgalyaḥ kaphavātāsrarakṣovraṇaviṣāpahaḥ"},{"type":"verse","number":"262","sanskrit":"वटपत्री तु कथिता मोहिन्यैरावती बुधैः वटपत्री कषायोष्णा योनिमूत्रगदापहा","text":"vaṭapatrī tu kathitā mohinyairāvatī budhaiḥ vaṭapatrī kaṣāyoṣṇā yonimūtragadāpahā"},{"type":"verse","number":"263","sanskrit":"हिङ्गुपत्री तु कवरी पृथ्वीका पृथुका पृथुः","text":"hiṅgupatrī tu kavarī pṛthvīkā pṛthukā pṛthuḥ"},{"type":"verse","number":"264","sanskrit":"हिङ्गुपत्री भवेद्रुच्या तीक्ष्णोष्णा पाचनी कटुः हृद्बस्तिरुग्विबन्धार्शःश्लेष्मगुल्मानिलापहा","text":"hiṅgupatrī bhavedrucyā tīkṣṇoṣṇā pācanī kaṭuḥ hṛdbastirugvibandhārśaḥśleṣmagulmānilāpahā"},{"type":"verse","number":"265","sanskrit":"वंशपत्री वेणुपत्री पिण्डा हिङ्गुशिवाटिका हिङ्गुपत्रीगुणा विज्ञैर्वंशपत्री च कीर्त्तिता","text":"vaṃśapatrī veṇupatrī piṇḍā hiṅguśivāṭikā hiṅgupatrīguṇā vijñairvaṃśapatrī ca kīrttitā"},{"type":"verse","number":"266","sanskrit":"मत्स्याक्षी बाह्लिका मत्स्यगन्धा मत्स्यादनीति च मत्स्याक्षी ग्राहिणी शीतकुष्ठपित्तकफास्रजित् लघुस्तिक्ता कषाया च स्वाद्वी कटुविपाकिनी","text":"matsyākṣī bāhlikā matsyagandhā matsyādanīti ca matsyākṣī grāhiṇī śītakuṣṭhapittakaphāsrajit laghustiktā kaṣāyā ca svādvī kaṭuvipākinī"},{"type":"verse","number":"267","sanskrit":"सर्पाक्षी स्यात्तु गण्डाली तथा नाडीकलापकः","text":"sarpākṣī syāttu gaṇḍālī tathā nāḍīkalāpakaḥ"},{"type":"verse","number":"268","sanskrit":"सर्पाक्षी कटुका तिक्ता सोष्णा कृमिनिकृन्तनी वृश्चिकोन्दुरुसर्पाणां विषघ्नी व्रणरोपिणी","text":"sarpākṣī kaṭukā tiktā soṣṇā kṛminikṛntanī vṛścikondurusarpāṇāṃ viṣaghnī vraṇaropiṇī"},{"type":"verse","number":"269","sanskrit":"शङ्ख्नपुष्पी तु शङ्खाह्वा मङ्गल्यकुसुमाऽपि च शङ्खपुष्पी सरा मेध्या वृष्या मानसरोगहृत्","text":"śaṅkhnapuṣpī tu śaṅkhāhvā maṅgalyakusumā'pi ca śaṅkhapuṣpī sarā medhyā vṛṣyā mānasarogahṛt"},{"type":"verse","number":"270","sanskrit":"रसायनी कषायोष्णा स्मृतिकान्तिबलाग्निदा दोषापस्मारभूताश्रीकुष्ठक्रिमिविषप्रणुत् ४.","text":"rasāyanī kaṣāyoṣṇā smṛtikāntibalāgnidā doṣāpasmārabhūtāśrīkuṣṭhakrimiviṣapraṇut 4."},{"type":"verse","number":"271","sanskrit":"अर्कपुष्पी क्रूरकर्मा पयस्या जलकामुका अर्कपुष्पी कृमिश्लेष्ममेहपित्तविकारजित्","text":"arkapuṣpī krūrakarmā payasyā jalakāmukā arkapuṣpī kṛmiśleṣmamehapittavikārajit"},{"type":"verse","number":"272","sanskrit":"लज्जालुः स्वाच्छमीपत्रा समङ्गा जलकारिका रक्तपादी नमस्कारी नाम्ना खदिरकेत्यपि","text":"lajjāluḥ svācchamīpatrā samaṅgā jalakārikā raktapādī namaskārī nāmnā khadiraketyapi"},{"type":"verse","number":"273","sanskrit":"लज्जालुः शीतला तिक्ता कषाया कफपित्तजित् रक्तपित्तमतीसारं योनिरोगान् विनाशयेत्","text":"lajjāluḥ śītalā tiktā kaṣāyā kaphapittajit raktapittamatīsāraṃ yonirogān vināśayet"},{"type":"verse","number":"274","sanskrit":"अलम्बुषा खरत्वक् च तथा मेदोगला स्मृता अलम्बुषा लघुः स्वादुः क्रिमिपित्तकफापहा","text":"alambuṣā kharatvak ca tathā medogalā smṛtā alambuṣā laghuḥ svāduḥ krimipittakaphāpahā"},{"type":"verse","number":"275","sanskrit":"दुग्धिका स्वादुपर्णी स्यात्क्षीरा विक्षीरिणी तथा दुग्धिकोष्णा गुरू रूक्षा वातलागर्भकारिणी","text":"dugdhikā svāduparṇī syātkṣīrā vikṣīriṇī tathā dugdhikoṣṇā gurū rūkṣā vātalāgarbhakāriṇī"},{"type":"verse","number":"276","sanskrit":"स्वादुक्षीरा कटुस्तिक्ता सृष्टमूत्रा मलापहा स्वादुविष्टम्भिनी वृष्या कफकुष्ठक्रिमिप्रणुत्","text":"svādukṣīrā kaṭustiktā sṛṣṭamūtrā malāpahā svāduviṣṭambhinī vṛṣyā kaphakuṣṭhakrimipraṇut"},{"type":"verse","number":"277","sanskrit":"भूम्यामलकिका प्रोक्ता शिवा तामलकीति च बहुपत्रा बहुफला बहुवीर्याऽजटाऽपि च","text":"bhūmyāmalakikā proktā śivā tāmalakīti ca bahupatrā bahuphalā bahuvīryā'jaṭā'pi ca"},{"type":"verse","number":"278","sanskrit":"भूधात्री वातकृत्तिक्ता कषाया मधुरा हिमा पिपासाकासपितास्रकफकण्डूक्षतापहा","text":"bhūdhātrī vātakṛttiktā kaṣāyā madhurā himā pipāsākāsapitāsrakaphakaṇḍūkṣatāpahā"},{"type":"verse","number":"279","sanskrit":"ब्राह्मी कपोतवङ्का च सोमवल्ली सरस्वती मण्डूकपर्णी माण्डूकी त्वाष्ट्री दिव्या महौषधी","text":"brāhmī kapotavaṅkā ca somavallī sarasvatī maṇḍūkaparṇī māṇḍūkī tvāṣṭrī divyā mahauṣadhī"},{"type":"verse","number":"280","sanskrit":"ब्राह्मी हिमा सरा तिक्ता लघुर्मध्या च शीतला कषाया मधुरा स्वादुपाकाऽयुष्या रसायनी ४.","text":"brāhmī himā sarā tiktā laghurmadhyā ca śītalā kaṣāyā madhurā svādupākā'yuṣyā rasāyanī 4."},{"type":"verse","number":"281","sanskrit":"स्वर्या स्मृतिप्रद्रा कुष्ठपाण्डुमेहास्रकासजित् विषशोथज्वरहरी तद्वन्मण्डूकपर्णिनी","text":"svaryā smṛtipradrā kuṣṭhapāṇḍumehāsrakāsajit viṣaśothajvaraharī tadvanmaṇḍūkaparṇinī"},{"type":"verse","number":"282","sanskrit":"द्रो णा च द्रो णपुष्पी च फलेपुष्पा च कीर्त्तिता द्रो णपुष्पी गुरुः स्वादू रूक्षोष्णा वातपित्तकृत्","text":"dro ṇā ca dro ṇapuṣpī ca phalepuṣpā ca kīrttitā dro ṇapuṣpī guruḥ svādū rūkṣoṣṇā vātapittakṛt"},{"type":"verse","number":"283","sanskrit":"सतीक्ष्णलवणा स्वादुपाका कट्वी च भेदिनी कफामकामलाशोथतमकश्वासजन्तुजित्","text":"satīkṣṇalavaṇā svādupākā kaṭvī ca bhedinī kaphāmakāmalāśothatamakaśvāsajantujit"},{"type":"verse","number":"284","sanskrit":"सुवर्चला सूर्यभक्ता वरदा बदराऽपि च सूर्यावर्त्ता रविप्रीताऽपरा ब्रह्मसुदुर्लभा","text":"suvarcalā sūryabhaktā varadā badarā'pi ca sūryāvarttā raviprītā'parā brahmasudurlabhā"},{"type":"verse","number":"285","sanskrit":"सुवर्चला हिमा रूक्षा स्वादुपाका सरा गुरुः अपित्तला कटुः क्षारा विष्टम्भकफवातजित्","text":"suvarcalā himā rūkṣā svādupākā sarā guruḥ apittalā kaṭuḥ kṣārā viṣṭambhakaphavātajit"},{"type":"verse","number":"286","sanskrit":"अन्या तिक्ता कषायोष्णा सरा रुक्षा लघुः कटुः निहन्ति कफपित्तास्रश्वासकासारुचिज्वरान् विस्फोटकुष्ठमेहास्रयोनिरुक्कृमिपाण्डुताः","text":"anyā tiktā kaṣāyoṣṇā sarā rukṣā laghuḥ kaṭuḥ nihanti kaphapittāsraśvāsakāsārucijvarān visphoṭakuṣṭhamehāsrayonirukkṛmipāṇḍutāḥ"},{"type":"verse","number":"287","sanskrit":"वन्ध्याकर्कोटकी देवी कन्या योगीश्वरीति च नागरिर्नक्रदमनी विषकण्टकिनी तथा","text":"vandhyākarkoṭakī devī kanyā yogīśvarīti ca nāgarirnakradamanī viṣakaṇṭakinī tathā"},{"type":"verse","number":"288","sanskrit":"बन्ध्याकर्कोटकी लघ्वी कफनुद् व्रणशोधिनी सर्पदर्पहरी तीक्ष्णा विसर्पविषहारिणी","text":"bandhyākarkoṭakī laghvī kaphanud vraṇaśodhinī sarpadarpaharī tīkṣṇā visarpaviṣahāriṇī"},{"type":"verse","number":"289","sanskrit":"मार्कण्डिका भूमिवल्ली मार्कण्डी मृदुरेचनी","text":"mārkaṇḍikā bhūmivallī mārkaṇḍī mṛdurecanī"},{"type":"verse","number":"290","sanskrit":"मार्कण्डिका कुष्ठहरी ऊर्ध्वाधःकायशोधिनी विषदुर्गंन्धकासघ्नी गुल्मोदरविनाशिनी ४.","text":"mārkaṇḍikā kuṣṭhaharī ūrdhvādhaḥkāyaśodhinī viṣadurgaṃndhakāsaghnī gulmodaravināśinī 4."},{"type":"verse","number":"291","sanskrit":"देवदाली यु वेणी स्यात्कर्कटी च गरागरी देवताडो वृत्तकोशस्तथा जीमूत इत्यपि","text":"devadālī yu veṇī syātkarkaṭī ca garāgarī devatāḍo vṛttakośastathā jīmūta ityapi"},{"type":"verse","number":"292","sanskrit":"पीता परा खरस्पर्श विषघ्नी गरनाशिनी देवदाली रसे तिक्ता कफार्शःशोफपाण्डुताः नाशयेद्वामनी तीक्ष्णा क्षयहिक्काकृमिज्वरान्","text":"pītā parā kharasparśa viṣaghnī garanāśinī devadālī rase tiktā kaphārśaḥśophapāṇḍutāḥ nāśayedvāmanī tīkṣṇā kṣayahikkākṛmijvarān"},{"type":"verse","number":"293","sanskrit":"देवदालीफलं तिक्तं कृमिश्लेष्मविनाशनम् स्रंसनं गुल्मशूलघ्नमर्शोघ्नं वातजित्परम्","text":"devadālīphalaṃ tiktaṃ kṛmiśleṣmavināśanam sraṃsanaṃ gulmaśūlaghnamarśoghnaṃ vātajitparam"},{"type":"verse","number":"294","sanskrit":"जलपिप्पल्यभिहिता शारदी शकुलादनी मत्स्यादनी मत्स्यगन्धा लाङ्गलीत्यपि कीर्त्तिता","text":"jalapippalyabhihitā śāradī śakulādanī matsyādanī matsyagandhā lāṅgalītyapi kīrttitā"},{"type":"verse","number":"295","sanskrit":"जलपिप्पलिका हृद्या चक्षुष्या शुक्रला लघुः","text":"jalapippalikā hṛdyā cakṣuṣyā śukralā laghuḥ"},{"type":"verse","number":"296","sanskrit":"संग्राहिणी हिमा रूक्षा रक्तदाहव्रणापहा कटुपाकरसा रुच्या कषाया वह्निवर्द्धिनी","text":"saṃgrāhiṇī himā rūkṣā raktadāhavraṇāpahā kaṭupākarasā rucyā kaṣāyā vahnivarddhinī"},{"type":"verse","number":"297","sanskrit":"गोजिह्वा गोजिका गोभी दार्विका खरपर्णिनी गोजिह्वा वातला शीता ग्राहिणी कफपित्तनुत्","text":"gojihvā gojikā gobhī dārvikā kharaparṇinī gojihvā vātalā śītā grāhiṇī kaphapittanut"},{"type":"verse","number":"298","sanskrit":"हृद्या प्रमेहकासास्रव्रणज्वरहरी लघुः कोमला तुवरा तिक्ता स्वादुपाकरसा स्मृता","text":"hṛdyā pramehakāsāsravraṇajvaraharī laghuḥ komalā tuvarā tiktā svādupākarasā smṛtā"},{"type":"verse","number":"299","sanskrit":"विज्ञेया नागदमनी बलमोदा विषापहा नागपुष्पी नागपत्रा महायोगेश्वरीति च","text":"vijñeyā nāgadamanī balamodā viṣāpahā nāgapuṣpī nāgapatrā mahāyogeśvarīti ca"},{"type":"verse","number":"300","sanskrit":"बलामोटा कटुस्तिक्ता लघुः पित्तकफापहा मूत्रकृच्छ्रव्रणान् रक्षो नाशयेज्जालगर्दभम् ४.","text":"balāmoṭā kaṭustiktā laghuḥ pittakaphāpahā mūtrakṛcchravraṇān rakṣo nāśayejjālagardabham 4."},{"type":"verse","number":"301","sanskrit":"सर्वग्रहप्रशमनी निःशेषविषनाशिनी जयं सर्वत्र कुरुते धनदासुमतिप्रदा","text":"sarvagrahapraśamanī niḥśeṣaviṣanāśinī jayaṃ sarvatra kurute dhanadāsumatipradā"},{"type":"verse","number":"302","sanskrit":"वेल्लन्तरो जगति वीरतरुः प्रसिद्धः श्वेतासितारुणविलोहितनीलपुष्पः स्याज्जातितुल्यकुसुमः शमिसूक्ष्मपत्रः स्यात्कण्टकी विजलदेशज एव वृक्षः","text":"vellantaro jagati vīrataruḥ prasiddhaḥ śvetāsitāruṇavilohitanīlapuṣpaḥ syājjātitulyakusumaḥ śamisūkṣmapatraḥ syātkaṇṭakī vijaladeśaja eva vṛkṣaḥ"},{"type":"verse","number":"303","sanskrit":"वेल्लन्तरो रसे पाके तिक्तस्तृष्णाकफापहः मूत्राघाताश्मजिद्ग्राही योनिमूत्रानिलार्त्तिजित्","text":"vellantaro rase pāke tiktastṛṣṇākaphāpahaḥ mūtrāghātāśmajidgrāhī yonimūtrānilārttijit"},{"type":"verse","number":"304","sanskrit":"छिक्क्नी क्षवकृत्तीक्ष्णा छिक्किका घ्राणदुःखदा छिक्कनी कटुका रुक्ष्या तीक्ष्णोष्णावह्निपित्तकृत् वातरक्तहरी कुष्ठक्रिमिवातकफापहा","text":"chikknī kṣavakṛttīkṣṇā chikkikā ghrāṇaduḥkhadā chikkanī kaṭukā rukṣyā tīkṣṇoṣṇāvahnipittakṛt vātaraktaharī kuṣṭhakrimivātakaphāpahā"},{"type":"verse","number":"305","sanskrit":"कुकुन्दर स्ताम्रचूडः सूक्ष्मपत्रो मृदुच्छदः","text":"kukundara stāmracūḍaḥ sūkṣmapatro mṛducchadaḥ"},{"type":"verse","number":"306","sanskrit":"कुकुन्दरः कटुस्तिक्तो ज्वररक्तकफापहः तन्मूलमाद्र रं! निक्षिप्तं वदने मुखशोषहृत्","text":"kukundaraḥ kaṭustikto jvararaktakaphāpahaḥ tanmūlamādra raṃ! nikṣiptaṃ vadane mukhaśoṣahṛt"},{"type":"verse","number":"307","sanskrit":"सुदर्शना सोमवल्ली चक्राह्वा मधुपर्णिका सुदर्शना स्वादुरुष्णा कफशोथास्रवातजित्","text":"sudarśanā somavallī cakrāhvā madhuparṇikā sudarśanā svāduruṣṇā kaphaśothāsravātajit"},{"type":"verse","number":"308","sanskrit":"आखुकर्णी त्वाखुपर्णी पर्णिका भूदरीभवा आखुकर्णी कटुस्तिक्ता कषाया शीतला लघुः विपाके कटुका मूत्रकफामयकृमिप्रणुत्","text":"ākhukarṇī tvākhuparṇī parṇikā bhūdarībhavā ākhukarṇī kaṭustiktā kaṣāyā śītalā laghuḥ vipāke kaṭukā mūtrakaphāmayakṛmipraṇut"},{"type":"verse","number":"309","sanskrit":"मयूराह्वशिखा प्रोक्ता सहस्राहिर्मधुच्छदा नीलकण्ठशिखा लघ्वी पित्तश्लेष्मातिसारजित्","text":"mayūrāhvaśikhā proktā sahasrāhirmadhucchadā nīlakaṇṭhaśikhā laghvī pittaśleṣmātisārajit"},{"type":"verse","number":"4","sanskrit":"इति श्रीमिश्रलटकनतनयश्रीमिश्रभावविरचिते भावप्रकाशे पूर्वखण्डे मिश्रप्रकरणे चतुर्थो गुडूच्यादिवर्गः समाप्तः","text":"iti śrīmiśralaṭakanatanayaśrīmiśrabhāvaviracite bhāvaprakāśe pūrvakhaṇḍe miśraprakaraṇe caturtho guḍūcyādivargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":4,"lang":"sa","content":[{"type":"heading","heading":"puṣpa-варга — цветы"},{"type":"verse","number":"1","sanskrit":"वा पुंसि पद्मं नलिनमरविन्दं महोत्पलम् सहस्रपत्रं कमलं शतपत्रं कुशेशयम्","text":"vā puṃsi padmaṃ nalinamaravindaṃ mahotpalam sahasrapatraṃ kamalaṃ śatapatraṃ kuśeśayam"},{"type":"verse","number":"2","sanskrit":"पङ्केरुहं तामरसं सारसं सरसीरुहम् बिसप्रसूनराजीवपुष्कराम्भोरुहाणि च","text":"paṅkeruhaṃ tāmarasaṃ sārasaṃ sarasīruham bisaprasūnarājīvapuṣkarāmbhoruhāṇi ca"},{"type":"verse","number":"3","sanskrit":"कमलं शीतलं वर्ण्यं मधुरं कफपित्तजित् तृष्णादाहास्रविस्फोटविषवीसर्पनाशनम्","text":"kamalaṃ śītalaṃ varṇyaṃ madhuraṃ kaphapittajit tṛṣṇādāhāsravisphoṭaviṣavīsarpanāśanam"},{"type":"verse","number":"4","sanskrit":"विशेषतः सितं पद्मं पुण्डरीकमिति स्मृतम् रक्तं कोकनदं ज्ञेयं नीलमिन्दीवरं स्मृतम्","text":"viśeṣataḥ sitaṃ padmaṃ puṇḍarīkamiti smṛtam raktaṃ kokanadaṃ jñeyaṃ nīlamindīvaraṃ smṛtam"},{"type":"verse","number":"5","sanskrit":"धवलं कमलं शीतं मधुरं कफपित्तजित् तस्मादल्पगुणं किञ्चिदन्यद्र क्तोत्पलादिकम्","text":"dhavalaṃ kamalaṃ śītaṃ madhuraṃ kaphapittajit tasmādalpaguṇaṃ kiñcidanyadra ktotpalādikam"},{"type":"verse","number":"6","sanskrit":"मूलनालदलोत्फुल्लफलैः समुदिता पुनः पद्मिनी प्रोच्यते प्राज्ञैर्बिसिन्यादि च सा स्मृता","text":"mūlanāladalotphullaphalaiḥ samuditā punaḥ padminī procyate prājñairbisinyādi ca sā smṛtā"},{"type":"verse","number":"7","sanskrit":"पद्मिनी शीतला गुर्वी मधुरा लवणा च सा पित्तासृक्कफनुद्रू क्षा वातविष्टम्भकारिणी","text":"padminī śītalā gurvī madhurā lavaṇā ca sā pittāsṛkkaphanudrū kṣā vātaviṣṭambhakāriṇī"},{"type":"verse","number":"8","sanskrit":"संवर्त्तिका नवदलं बीजकोशस्तु कर्णिका किञ्जल्कः केशरः प्रोक्तो मकरन्दो रसः स्मृतः पद्मनालं मृणालं स्यात्तथा बिसमिति स्मृतम्","text":"saṃvarttikā navadalaṃ bījakośastu karṇikā kiñjalkaḥ keśaraḥ prokto makarando rasaḥ smṛtaḥ padmanālaṃ mṛṇālaṃ syāttathā bisamiti smṛtam"},{"type":"verse","number":"9","sanskrit":"संवर्त्तिका हिमा तिक्ता कषाया दाहतृट्प्रणुत् मूत्रकृच्छ्रगुदव्याधिरक्तपित्तविनाशिनी","text":"saṃvarttikā himā tiktā kaṣāyā dāhatṛṭpraṇut mūtrakṛcchragudavyādhiraktapittavināśinī"},{"type":"verse","number":"10","sanskrit":"पद्मस्य कर्णिका तिक्ता कषाया मधुरा हिमा मुखवैशद्यकृल्लघ्वी तृष्णाऽस्रकफपित्तनुत् ५.","text":"padmasya karṇikā tiktā kaṣāyā madhurā himā mukhavaiśadyakṛllaghvī tṛṣṇā'srakaphapittanut 5."},{"type":"verse","number":"11","sanskrit":"किञ्जल्कः शीतलो वृष्यः कषायो ग्राहकोऽपिसः कफपित्ततृषादाहरक्तार्शोविषशोथजित्","text":"kiñjalkaḥ śītalo vṛṣyaḥ kaṣāyo grāhako'pisaḥ kaphapittatṛṣādāharaktārśoviṣaśothajit"},{"type":"verse","number":"12","sanskrit":"मृणालं शीतलं वृष्यं पित्तदाहास्रजिद् गुरु","text":"mṛṇālaṃ śītalaṃ vṛṣyaṃ pittadāhāsrajid guru"},{"type":"verse","number":"13","sanskrit":"दुर्जरं स्वादुपाकञ्च स्तन्यानिलकफप्रदम् संग्राहि मधुरं रूक्षं शालूकमपि तद्गुणम्","text":"durjaraṃ svādupākañca stanyānilakaphapradam saṃgrāhi madhuraṃ rūkṣaṃ śālūkamapi tadguṇam"},{"type":"verse","number":"14","sanskrit":"पद्मचारिण्यतिचराऽव्यथा पद्मा च शारदा पद्माऽनुष्णा कटुस्तिक्ता कषाया कफवातजित् मूत्रकृच्छ्श्मशूलघ्नो श्वासकासविषापहा","text":"padmacāriṇyaticarā'vyathā padmā ca śāradā padmā'nuṣṇā kaṭustiktā kaṣāyā kaphavātajit mūtrakṛcchśmaśūlaghno śvāsakāsaviṣāpahā"},{"type":"verse","number":"15","sanskrit":"श्वेतं कुवलयं प्रोक्तं कुमुदं कैरवं तथा कुमुदं पिच्छिलं स्निग्धं मधुरं ह्लादि शीतलम्","text":"śvetaṃ kuvalayaṃ proktaṃ kumudaṃ kairavaṃ tathā kumudaṃ picchilaṃ snigdhaṃ madhuraṃ hlādi śītalam"},{"type":"verse","number":"16","sanskrit":"कुमुद्वती कैरविका तथा कुमुदिनीति च","text":"kumudvatī kairavikā tathā kumudinīti ca"},{"type":"verse","number":"17","sanskrit":"सा तु मूलादिसर्वाङ्गैरुक्ता समुदिता बुधैः पद्मिन्या ये गुणाः प्रोक्ताः कुमुदिन्याश्च ते स्मृताः","text":"sā tu mūlādisarvāṅgairuktā samuditā budhaiḥ padminyā ye guṇāḥ proktāḥ kumudinyāśca te smṛtāḥ"},{"type":"verse","number":"18","sanskrit":"सौगन्धिकं तु कल्हारं हल्लकं रक्तसन्ध्यकम् कल्हारं शीतलं ग्राहि विष्टम्भि गुरु रूक्षणम्","text":"saugandhikaṃ tu kalhāraṃ hallakaṃ raktasandhyakam kalhāraṃ śītalaṃ grāhi viṣṭambhi guru rūkṣaṇam"},{"type":"verse","number":"19","sanskrit":"वारिपर्णी कुम्भिका स्याद्वारिमूली खमूलिका शैवालं जलनीली स्याच्छैवलं जलजञ्च तत्","text":"vāriparṇī kumbhikā syādvārimūlī khamūlikā śaivālaṃ jalanīlī syācchaivalaṃ jalajañca tat"},{"type":"verse","number":"20","sanskrit":"वारिपर्णी हिमा तिक्ता लघ्वी स्वाद्वी सरा कटुः दोषत्रयहरी रूक्षा शोणितज्वरशोषकृत् ५.","text":"vāriparṇī himā tiktā laghvī svādvī sarā kaṭuḥ doṣatrayaharī rūkṣā śoṇitajvaraśoṣakṛt 5."},{"type":"verse","number":"21","sanskrit":"शैवालं तुवरं तिक्तं मधुरं शीतलं लघु स्निग्धं दाहतृषापित्तरक्तज्वरहरं परम्","text":"śaivālaṃ tuvaraṃ tiktaṃ madhuraṃ śītalaṃ laghu snigdhaṃ dāhatṛṣāpittaraktajvaraharaṃ param"},{"type":"verse","number":"22","sanskrit":"शतपत्री तरुण्युक्ता कर्णिका चारुकेशरा महाकुमारी गन्धाढ्या लाक्षापुष्पा ऽतिमञ्जुला","text":"śatapatrī taruṇyuktā karṇikā cārukeśarā mahākumārī gandhāḍhyā lākṣāpuṣpā 'timañjulā"},{"type":"verse","number":"23","sanskrit":"शतपत्री हिमा हृद्या ग्राहिणी शुक्रला लघुः दोषत्रयास्रजिद्वर्ण्या कट्वी तिक्ता च पाचनी","text":"śatapatrī himā hṛdyā grāhiṇī śukralā laghuḥ doṣatrayāsrajidvarṇyā kaṭvī tiktā ca pācanī"},{"type":"verse","number":"24","sanskrit":"नेपाली कथिता तज्ज्ञैः सप्तला नवमालिका वासन्ती शीतला लघ्वी तिक्ता दोषत्रयास्रजित्","text":"nepālī kathitā tajjñaiḥ saptalā navamālikā vāsantī śītalā laghvī tiktā doṣatrayāsrajit"},{"type":"verse","number":"25","sanskrit":"श्रीपदी षट्पदानन्दा वार्षिकी मुक्तबन्धना","text":"śrīpadī ṣaṭpadānandā vārṣikī muktabandhanā"},{"type":"verse","number":"26","sanskrit":"वार्षिकी शीतला लघ्वी तिक्ता दोषत्रयापहा कर्णाक्षिमुखरोगघ्नी तत्तैलं तद्गुणं स्मृतम्","text":"vārṣikī śītalā laghvī tiktā doṣatrayāpahā karṇākṣimukharogaghnī tattailaṃ tadguṇaṃ smṛtam"},{"type":"verse","number":"27","sanskrit":"जातिर्जाती च सुमना मालती राजपुत्रिका चेतिका हृद्यगन्धा च सा पीता स्वर्णजातिका","text":"jātirjātī ca sumanā mālatī rājaputrikā cetikā hṛdyagandhā ca sā pītā svarṇajātikā"},{"type":"verse","number":"28","sanskrit":"जातीयुगं तिक्तमुष्णं तुवरं लघु दोषजित् शिरोऽक्षिमुखदन्तार्त्तिविषकुष्ठानिलास्रजित्","text":"jātīyugaṃ tiktamuṣṇaṃ tuvaraṃ laghu doṣajit śiro'kṣimukhadantārttiviṣakuṣṭhānilāsrajit"},{"type":"verse","number":"29","sanskrit":"यूथिका गणिकाऽम्बष्ठा सा पीता हेमपुष्पिका यूथीयुगं हिमं तिक्तं कटुपाकरसं लघु","text":"yūthikā gaṇikā'mbaṣṭhā sā pītā hemapuṣpikā yūthīyugaṃ himaṃ tiktaṃ kaṭupākarasaṃ laghu"},{"type":"verse","number":"30","sanskrit":"मधुरं तुवरं हृद्यं पित्तघ्नं कफवातलम् व्रणास्रमुखदन्ताक्षिशिरोरोगविषापहम् ५.","text":"madhuraṃ tuvaraṃ hṛdyaṃ pittaghnaṃ kaphavātalam vraṇāsramukhadantākṣiśirorogaviṣāpaham 5."},{"type":"verse","number":"31","sanskrit":"चाम्पेयश्चम्पकः प्रोक्तोहेमपुष्पश्च स स्मृतः एतस्य कलिका गन्धफलेति कथिता बुधैः","text":"cāmpeyaścampakaḥ proktohemapuṣpaśca sa smṛtaḥ etasya kalikā gandhaphaleti kathitā budhaiḥ"},{"type":"verse","number":"32","sanskrit":"चम्पकः कटुकस्तिक्तः कषायो मधुरो हिमः विषक्रिमिहरः कृच्छ्रकफवातास्नपित्तजित्","text":"campakaḥ kaṭukastiktaḥ kaṣāyo madhuro himaḥ viṣakrimiharaḥ kṛcchrakaphavātāsnapittajit"},{"type":"verse","number":"33","sanskrit":"बकुलो मधुगन्धश्च सिंहकेसरकस्तथा बकुलस्तुवरोऽनुष्णः कटुपाकरसो गुरुः कफपित्तविषश्वित्रकृमिदन्तगदापहः","text":"bakulo madhugandhaśca siṃhakesarakastathā bakulastuvaro'nuṣṇaḥ kaṭupākaraso guruḥ kaphapittaviṣaśvitrakṛmidantagadāpahaḥ"},{"type":"verse","number":"34","sanskrit":"शिवमल्ली पाशुपत एकाष्ठीलो वको वसुः","text":"śivamallī pāśupata ekāṣṭhīlo vako vasuḥ"},{"type":"verse","number":"35","sanskrit":"वकोऽनुष्णः कटुस्तिक्तः कफपित्तविषापहः योनिशूलतृषादाहकुष्ठशोथास्रनाशनः","text":"vako'nuṣṇaḥ kaṭustiktaḥ kaphapittaviṣāpahaḥ yoniśūlatṛṣādāhakuṣṭhaśothāsranāśanaḥ"},{"type":"verse","number":"36","sanskrit":"कदम्बः प्रियको नीपो वृत्तपुष्पो हलिप्रियः कदम्बो मधुरः शीतः कषायो लवणो गुरुः सरो विष्टम्भकृद्रू क्षः कफस्तन्यानिलप्रदः","text":"kadambaḥ priyako nīpo vṛttapuṣpo halipriyaḥ kadambo madhuraḥ śītaḥ kaṣāyo lavaṇo guruḥ saro viṣṭambhakṛdrū kṣaḥ kaphastanyānilapradaḥ"},{"type":"verse","number":"37","sanskrit":"कुब्जको भद्र तरुणी वृत्तपुष्पोऽतिकेसरः महासहा कण्टकाढ्या नीलालिकुलसंकुला","text":"kubjako bhadra taruṇī vṛttapuṣpo'tikesaraḥ mahāsahā kaṇṭakāḍhyā nīlālikulasaṃkulā"},{"type":"verse","number":"38","sanskrit":"कुब्जकः सुरभिः स्वादुः कषायानुरसः सरः त्रिदोषशमनो वृष्यः शीतहर्त्ता च स स्मृतः","text":"kubjakaḥ surabhiḥ svāduḥ kaṣāyānurasaḥ saraḥ tridoṣaśamano vṛṣyaḥ śītaharttā ca sa smṛtaḥ"},{"type":"verse","number":"39","sanskrit":"मल्लिका मदयन्ती च शीतभीरुश्च भूपदी","text":"mallikā madayantī ca śītabhīruśca bhūpadī"},{"type":"verse","number":"40","sanskrit":"मल्लिकोष्णा लघुर्वृष्या तिक्ता च कटुका हरेत् वातपित्तास्यदृग्व्याधिकुष्ठारुचिविषव्रणान् ५.","text":"mallikoṣṇā laghurvṛṣyā tiktā ca kaṭukā haret vātapittāsyadṛgvyādhikuṣṭhāruciviṣavraṇān 5."},{"type":"verse","number":"41","sanskrit":"माधवी स्यात्तु वासन्ती पुण्ड्रको मण्डकोऽपि च अतिमुक्तो विमुक्तश्च कामुको भ्रमरोत्सवः माधवी मधुरा शीता लघ्वी दोषत्रयापहा","text":"mādhavī syāttu vāsantī puṇḍrako maṇḍako'pi ca atimukto vimuktaśca kāmuko bhramarotsavaḥ mādhavī madhurā śītā laghvī doṣatrayāpahā"},{"type":"verse","number":"42","sanskrit":"केतकः सूचिकापुष्पो जम्बुकः क्रकचच्छदः सुवर्णकेतकी त्वन्या लघुपुष्पा सुगन्धिनी","text":"ketakaḥ sūcikāpuṣpo jambukaḥ krakacacchadaḥ suvarṇaketakī tvanyā laghupuṣpā sugandhinī"},{"type":"verse","number":"43","sanskrit":"केतकः कटुकः स्वादुर्लघुस्तिक्तः कफापहः उष्णा तिक्तरसा ज्ञेया चक्षुष्या हेमकेतकी","text":"ketakaḥ kaṭukaḥ svādurlaghustiktaḥ kaphāpahaḥ uṣṇā tiktarasā jñeyā cakṣuṣyā hemaketakī"},{"type":"verse","number":"44","sanskrit":"किङ्किरातो हेमगौरः पीतकः पीतभद्र कः","text":"kiṅkirāto hemagauraḥ pītakaḥ pītabhadra kaḥ"},{"type":"verse","number":"45","sanskrit":"किङ्किरातो हिमस्तिक्तः कषायश्च हरेदसौ कफपित्तपिपासाऽस्रदाहशोषवमिक्रिमीन्","text":"kiṅkirāto himastiktaḥ kaṣāyaśca haredasau kaphapittapipāsā'sradāhaśoṣavamikrimīn"},{"type":"verse","number":"46","sanskrit":"कर्णिकारः परिव्याधः पादपोत्पल इत्यपि कर्णिकारः कटुस्तिक्तस्तुवरो शोधनो लघुः रञ्जनः सुखदः शोथश्लेष्मास्रव्रणकुष्ठजित्","text":"karṇikāraḥ parivyādhaḥ pādapotpala ityapi karṇikāraḥ kaṭustiktastuvaro śodhano laghuḥ rañjanaḥ sukhadaḥ śothaśleṣmāsravraṇakuṣṭhajit"},{"type":"verse","number":"47","sanskrit":"अशोको हेमपुष्पश्च वञ्जुलस्ताम्रपल्लवः कङ्केलि पिण्डपुष्पश्च गन्धपुष्पो नटस्तथा","text":"aśoko hemapuṣpaśca vañjulastāmrapallavaḥ kaṅkeli piṇḍapuṣpaśca gandhapuṣpo naṭastathā"},{"type":"verse","number":"48","sanskrit":"अशोकः शीतलस्तिक्तो ग्राही वर्ण्यः कषायकः दोषापचीतृषादाहकृमिशोषविषास्रजित्","text":"aśokaḥ śītalastikto grāhī varṇyaḥ kaṣāyakaḥ doṣāpacītṛṣādāhakṛmiśoṣaviṣāsrajit"},{"type":"verse","number":"49","sanskrit":"अम्लातोऽम्लाटनः प्रोक्तस्तथाऽम्लातक इत्यपि","text":"amlāto'mlāṭanaḥ proktastathā'mlātaka ityapi"},{"type":"verse","number":"50","sanskrit":"कुरण्टको वर्णपुष्पः स एवोक्तो महासहः अम्लाटनः कषायोष्णः स्निग्धः स्वादुश्च तिक्तकः ५.","text":"kuraṇṭako varṇapuṣpaḥ sa evokto mahāsahaḥ amlāṭanaḥ kaṣāyoṣṇaḥ snigdhaḥ svāduśca tiktakaḥ 5."},{"type":"verse","number":"51","sanskrit":"सैरेयकः श्वेतपुष्पः सैरेयः कटसारिका सहाचरः सहचरः स च भिन्द्यपि कथ्यते","text":"saireyakaḥ śvetapuṣpaḥ saireyaḥ kaṭasārikā sahācaraḥ sahacaraḥ sa ca bhindyapi kathyate"},{"type":"verse","number":"52","sanskrit":"कुरण्टकोऽत्रपीते स्याद्र क्त कुरबकः स्मृतः नीले बाणा द्वयोरुक्तो दासी चार्त्तगलश्च सः","text":"kuraṇṭako'trapīte syādra kta kurabakaḥ smṛtaḥ nīle bāṇā dvayorukto dāsī cārttagalaśca saḥ"},{"type":"verse","number":"53","sanskrit":"र्स्यैः! कुष्ठवातास्रकफकण्डूविषापहः तिक्तोष्णो मधुरोऽनम्लः सुस्निग्धः केशरञ्जनः","text":"rsyaiḥ! kuṣṭhavātāsrakaphakaṇḍūviṣāpahaḥ tiktoṣṇo madhuro'namlaḥ susnigdhaḥ keśarañjanaḥ"},{"type":"verse","number":"54","sanskrit":"कुन्दं तु कथितं माध्यं सदापुष्पञ्च तत्स्मृतम् कुन्दं शीतं लघु श्लेष्मशिरोरुग्विषपित्तहृत्","text":"kundaṃ tu kathitaṃ mādhyaṃ sadāpuṣpañca tatsmṛtam kundaṃ śītaṃ laghu śleṣmaśirorugviṣapittahṛt"},{"type":"verse","number":"55","sanskrit":"मुचुकुन्दः क्षत्रवृक्षश्चित्रकः प्रतिविष्णुकः मुचुकुन्दः शिरःपीडापित्तास्रविषनाशनः","text":"mucukundaḥ kṣatravṛkṣaścitrakaḥ prativiṣṇukaḥ mucukundaḥ śiraḥpīḍāpittāsraviṣanāśanaḥ"},{"type":"verse","number":"56","sanskrit":"तिलकः क्षुरकः श्रीमान्पुरुषश्छिन्नपुष्पकः तिलकः कटुकः पाके रसे चोष्णो रसायनः कफकुष्ठक्रिमीन्वस्तिमुखदन्तगदान्हरेत्","text":"tilakaḥ kṣurakaḥ śrīmānpuruṣaśchinnapuṣpakaḥ tilakaḥ kaṭukaḥ pāke rase coṣṇo rasāyanaḥ kaphakuṣṭhakrimīnvastimukhadantagadānharet"},{"type":"verse","number":"57","sanskrit":"बन्धूको बन्धुजीवश्च रक्तो माध्याह्निकोऽपि च बन्धूकः कफकृद् ग्राही वातपित्तहरो लघुः","text":"bandhūko bandhujīvaśca rakto mādhyāhniko'pi ca bandhūkaḥ kaphakṛd grāhī vātapittaharo laghuḥ"},{"type":"verse","number":"58","sanskrit":"ओड्रपुष्पं जपा चाथ त्रिसन्ध्या साऽरुणा सिता जपा संग्राहिणी केश्या त्रिसन्ध्या कफवातजित्","text":"oḍrapuṣpaṃ japā cātha trisandhyā sā'ruṇā sitā japā saṃgrāhiṇī keśyā trisandhyā kaphavātajit"},{"type":"verse","number":"59","sanskrit":"सिन्दूरी रक्तबीजा च रक्तपुष्पा सुकोमला सिन्दूरी विषपित्तास्रतृष्णावान्तिहरी हिमा","text":"sindūrī raktabījā ca raktapuṣpā sukomalā sindūrī viṣapittāsratṛṣṇāvāntiharī himā"},{"type":"verse","number":"60","sanskrit":"अथागस्त्यो वङ्गसेनो मुनिपुष्पो मुनिद्रुमः ५.","text":"athāgastyo vaṅgaseno munipuṣpo munidrumaḥ 5."},{"type":"verse","number":"61","sanskrit":"अगस्तिः पित्तकफजिच्चातुर्थिकहरो हिमः रूक्षो वातकरस्तिक्तः प्रतिश्यायनिवारणः","text":"agastiḥ pittakaphajiccāturthikaharo himaḥ rūkṣo vātakarastiktaḥ pratiśyāyanivāraṇaḥ"},{"type":"verse","number":"62","sanskrit":"तुलसी सुरसा ग्राम्या सुलभा बहुमञ्जरी अपेतराक्षसी गौरी भूतघ्नी देवदुन्दभिः","text":"tulasī surasā grāmyā sulabhā bahumañjarī apetarākṣasī gaurī bhūtaghnī devadundabhiḥ"},{"type":"verse","number":"63","sanskrit":"तुलसी कटुका तिक्ता हृद्योष्णा दाहपित्तकृत् दीपनी कुष्ठकृच्छ्रास्रपार्श्वरुक्कफवातजित् शुक्ला कृष्णा च तुलसी गुणैस्तुल्या प्रकीर्त्तिता","text":"tulasī kaṭukā tiktā hṛdyoṣṇā dāhapittakṛt dīpanī kuṣṭhakṛcchrāsrapārśvarukkaphavātajit śuklā kṛṣṇā ca tulasī guṇaistulyā prakīrttitā"},{"type":"verse","number":"64","sanskrit":"मारुतोऽसौ मरुबको मरुन्मरुरपि स्मृतः फणी फणिज्जकश्चापि प्रस्थपुष्पः समीरणः","text":"māruto'sau marubako marunmarurapi smṛtaḥ phaṇī phaṇijjakaścāpi prasthapuṣpaḥ samīraṇaḥ"},{"type":"verse","number":"65","sanskrit":"मरुदग्निप्रदो हृद्यस्तीक्ष्णोष्णः पित्तलो लघुः","text":"marudagniprado hṛdyastīkṣṇoṣṇaḥ pittalo laghuḥ"},{"type":"verse","number":"66","sanskrit":"कटुपाकरसो रुच्यस्तिक्तो रूक्षः सुगन्धिकः","text":"kaṭupākaraso rucyastikto rūkṣaḥ sugandhikaḥ"},{"type":"verse","number":"67","sanskrit":"उक्तो दमनको दान्तो मुनिपुत्रस्तपोधनः गन्धोत्कटो ब्रह्मजटो विनीतः कलपत्रकः","text":"ukto damanako dānto muniputrastapodhanaḥ gandhotkaṭo brahmajaṭo vinītaḥ kalapatrakaḥ"},{"type":"verse","number":"68","sanskrit":"दमनस्तुवरस्तिक्तो हृद्यो वृष्यः सुगन्धिकः ग्रहणाद् विषकुष्ठास्रक्लेदकण्डूत्रिदोषजित्","text":"damanastuvarastikto hṛdyo vṛṣyaḥ sugandhikaḥ grahaṇād viṣakuṣṭhāsrakledakaṇḍūtridoṣajit"},{"type":"verse","number":"69","sanskrit":"बर्बरी तुवरी तुङ्गी खरपुष्पाऽजगन्धिका पर्णाशस्तत्र कृष्णे तु कठिल्लककुठेरकौ","text":"barbarī tuvarī tuṅgī kharapuṣpā'jagandhikā parṇāśastatra kṛṣṇe tu kaṭhillakakuṭherakau"},{"type":"verse","number":"70","sanskrit":"तत्र शुक्लेऽजकः प्रोक्तो वटपत्रस्ततोऽपरः बर्बरीत्रितयं रूक्षं शीतं कटु विदाहि च ५.","text":"tatra śukle'jakaḥ prokto vaṭapatrastato'paraḥ barbarītritayaṃ rūkṣaṃ śītaṃ kaṭu vidāhi ca 5."},{"type":"verse","number":"71","sanskrit":"तीक्ष्णं रुचिकरं हृद्यं दीपनं लघुपाकि च पित्तलं कफवातास्रकण्डूकृमिविषापहम्","text":"tīkṣṇaṃ rucikaraṃ hṛdyaṃ dīpanaṃ laghupāki ca pittalaṃ kaphavātāsrakaṇḍūkṛmiviṣāpaham"},{"type":"verse","number":"5","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे पञ्चमः पुष्पवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe pañcamaḥ puṣpavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":5,"lang":"sa","content":[{"type":"heading","heading":"vaṭādi-варга — баньян и др."},{"type":"verse","number":"1","sanskrit":"वटो रक्तफलः शृङ्गीन्यग्रोधः स्कन्धजो ध्रुवः क्षीरी वैश्रवणो वासो बहुपादो वनस्पतिः","text":"vaṭo raktaphalaḥ śṛṅgīnyagrodhaḥ skandhajo dhruvaḥ kṣīrī vaiśravaṇo vāso bahupādo vanaspatiḥ"},{"type":"verse","number":"2","sanskrit":"वटः शीतो गुरुर्ग्राही कफपित्तव्रणापहः वर्ण्यो विसर्पदाहघ्नः कषायो योनिदोषहृत्","text":"vaṭaḥ śīto gururgrāhī kaphapittavraṇāpahaḥ varṇyo visarpadāhaghnaḥ kaṣāyo yonidoṣahṛt"},{"type":"verse","number":"3","sanskrit":"बोधिद्रुः पिप्पलोऽश्वत्थश्चलपत्रो गजाशनः पिप्पलो दुर्जरः शीतःपित्तश्लेष्मव्रणास्रजित् गुरुस्तुवरको रूक्षो वर्ण्यो योनिविशोधनः","text":"bodhidruḥ pippalo'śvatthaścalapatro gajāśanaḥ pippalo durjaraḥ śītaḥpittaśleṣmavraṇāsrajit gurustuvarako rūkṣo varṇyo yoniviśodhanaḥ"},{"type":"verse","number":"4","sanskrit":"पारीषोऽन्य पलाशश्च कपिचूतः कमण्डलुः गर्दभाण्डः कन्दरालः कपीतनसुपार्श्वकौ","text":"pārīṣo'nya palāśaśca kapicūtaḥ kamaṇḍaluḥ gardabhāṇḍaḥ kandarālaḥ kapītanasupārśvakau"},{"type":"verse","number":"5","sanskrit":"पारीषो दुर्जरः स्निग्धः कृमिशुक्रकफप्रदः फलेऽम्लो मधुरो मूले कषायस्वादुमज्जकः","text":"pārīṣo durjaraḥ snigdhaḥ kṛmiśukrakaphapradaḥ phale'mlo madhuro mūle kaṣāyasvādumajjakaḥ"},{"type":"verse","number":"6","sanskrit":"नन्दीवृक्षोऽश्वत्थभेदः प्ररोही गजपादपः स्थालीवृक्षः क्षयतरुः क्षीरी च स्याद्वनस्पतिः","text":"nandīvṛkṣo'śvatthabhedaḥ prarohī gajapādapaḥ sthālīvṛkṣaḥ kṣayataruḥ kṣīrī ca syādvanaspatiḥ"},{"type":"verse","number":"7","sanskrit":"नन्दीवृक्षो लघुः स्वादुस्तिक्तस्तुवर उष्णकः कटुपाकरसो ग्राही विषपित्तकफास्रजित्","text":"nandīvṛkṣo laghuḥ svādustiktastuvara uṣṇakaḥ kaṭupākaraso grāhī viṣapittakaphāsrajit"},{"type":"verse","number":"8","sanskrit":"उदुम्बरो जन्तुफलो यज्ञाङ्गो हेमदुग्धकः","text":"udumbaro jantuphalo yajñāṅgo hemadugdhakaḥ"},{"type":"verse","number":"9","sanskrit":"उदुम्बरो हिमो रूक्षो गुरुः पित्तकफास्रजित् मधुरस्तुवरो वर्ण्यो व्रणशोधनरोपणः","text":"udumbaro himo rūkṣo guruḥ pittakaphāsrajit madhurastuvaro varṇyo vraṇaśodhanaropaṇaḥ"},{"type":"verse","number":"10","sanskrit":"काकोदुम्बरिका फल्गुर्मलयूर्जघनेफला मलयुः स्तम्भकृत्तिक्ता शीतला तुवरा जयेत् कफपित्तव्रणश्वित्रकुष्ठपाण्ड्वर्शकामलाः ६.","text":"kākodumbarikā phalgurmalayūrjaghanephalā malayuḥ stambhakṛttiktā śītalā tuvarā jayet kaphapittavraṇaśvitrakuṣṭhapāṇḍvarśakāmalāḥ 6."},{"type":"verse","number":"11","sanskrit":"प्लक्षो जटी पर्करी च पर्कटी च स्त्रियामपि","text":"plakṣo jaṭī parkarī ca parkaṭī ca striyāmapi"},{"type":"verse","number":"12","sanskrit":"प्लक्षः कषायः शिशिरो व्रणयोनिगदापहः दाहपित्तकफास्रघ्नः शोथहा रक्तपित्तहृत्","text":"plakṣaḥ kaṣāyaḥ śiśiro vraṇayonigadāpahaḥ dāhapittakaphāsraghnaḥ śothahā raktapittahṛt"},{"type":"verse","number":"13","sanskrit":"शिरीषो भण्डिलो भण्डी भण्डीरश्च कपीतनः शुकपुष्पः शुकतरुर्मृदुपुष्पः शुकप्रियः","text":"śirīṣo bhaṇḍilo bhaṇḍī bhaṇḍīraśca kapītanaḥ śukapuṣpaḥ śukatarurmṛdupuṣpaḥ śukapriyaḥ"},{"type":"verse","number":"14","sanskrit":"शिरीषो मधुरोऽनुष्णस्तिक्तश्च तुवरो लघुः दोषशोथविसर्पघ्नः कासव्रणविषापहः","text":"śirīṣo madhuro'nuṣṇastiktaśca tuvaro laghuḥ doṣaśothavisarpaghnaḥ kāsavraṇaviṣāpahaḥ"},{"type":"verse","number":"15","sanskrit":"अथ क्षीरिवृक्षपञ्चकं त्वक्पञ्चकञ्च न्यग्रोधोदुम्बराश्वत्थपारीषप्लक्षपादपाः पञ्चैते क्षीरिणो वृक्षास्तेषां त्वक्पञ्चवल्कलम्","text":"atha kṣīrivṛkṣapañcakaṃ tvakpañcakañca nyagrodhodumbarāśvatthapārīṣaplakṣapādapāḥ pañcaite kṣīriṇo vṛkṣāsteṣāṃ tvakpañcavalkalam"},{"type":"verse","number":"16","sanskrit":"क्षीरिवृक्षा हिमा वर्ण्या योनिरोगव्रणापहाः रूक्षाः कषाया मेदोघ्ना विसर्पामथनाशनाः","text":"kṣīrivṛkṣā himā varṇyā yonirogavraṇāpahāḥ rūkṣāḥ kaṣāyā medoghnā visarpāmathanāśanāḥ"},{"type":"verse","number":"17","sanskrit":"शोथपित्तकफास्रघ्नाः स्तन्या भग्नास्थियोजकः त्वक्पञ्चकं हिमं ग्राहि व्रणशोथविसर्पजित्","text":"śothapittakaphāsraghnāḥ stanyā bhagnāsthiyojakaḥ tvakpañcakaṃ himaṃ grāhi vraṇaśothavisarpajit"},{"type":"verse","number":"18","sanskrit":"तेषां पत्रं हिमं ग्राहि कफवातास्रनुल्लघु विष्टम्भाघ्मानजित्तिक्तं कषायं लघु लेखनम्","text":"teṣāṃ patraṃ himaṃ grāhi kaphavātāsranullaghu viṣṭambhāghmānajittiktaṃ kaṣāyaṃ laghu lekhanam"},{"type":"verse","number":"19","sanskrit":"शालस्तु सर्जकार्श्याश्वकर्णकाः शस्यशम्बरः अश्वकर्णः कषायः स्याद् व्रणस्वेदकफक्रिमीन् ब्रध्नविद्र धिबाधिर्ययोनिकर्णगदान् हरेत्","text":"śālastu sarjakārśyāśvakarṇakāḥ śasyaśambaraḥ aśvakarṇaḥ kaṣāyaḥ syād vraṇasvedakaphakrimīn bradhnavidra dhibādhiryayonikarṇagadān haret"},{"type":"verse","number":"20","sanskrit":"सर्जकोऽन्योऽजकर्णः स्याच्छालो मरिचपत्रकः ६.","text":"sarjako'nyo'jakarṇaḥ syācchālo maricapatrakaḥ 6."},{"type":"verse","number":"21","sanskrit":"अजकर्णः कटुस्तिक्तः कषायोष्णो व्यपोहति कफपाण्डुश्रुतिगदान् मेहकुष्ठविषव्रणान्","text":"ajakarṇaḥ kaṭustiktaḥ kaṣāyoṣṇo vyapohati kaphapāṇḍuśrutigadān mehakuṣṭhaviṣavraṇān"},{"type":"verse","number":"22","sanskrit":"शल्लकी गजभक्ष्या च सुवहा सुरभी रसा महेरुणा कुन्दुरुकी वल्लकी च बहुस्रवा","text":"śallakī gajabhakṣyā ca suvahā surabhī rasā maheruṇā kundurukī vallakī ca bahusravā"},{"type":"verse","number":"23","sanskrit":"शल्लकी तुवरा शीता पित्तश्लेष्मातिसारजित् रक्तपित्तव्रणहरी पुष्टिकृत्समुदीरिता","text":"śallakī tuvarā śītā pittaśleṣmātisārajit raktapittavraṇaharī puṣṭikṛtsamudīritā"},{"type":"verse","number":"24","sanskrit":"शिंशपा पिच्छिला श्यामा कृष्णसारा च सा गुरु कपिला सैव मुनिभिर्भस्मगर्भेतिकीर्त्तिता","text":"śiṃśapā picchilā śyāmā kṛṣṇasārā ca sā guru kapilā saiva munibhirbhasmagarbhetikīrttitā"},{"type":"verse","number":"25","sanskrit":"शिंशपा कटुका तिक्ता कषाया शोषहारिणी उष्णवीर्या हरेन्मेदः कुष्ठश्वित्रवमिक्रिमीन् बस्तिरुग्व्रणदाहास्रबलासान् गर्भपातिनी","text":"śiṃśapā kaṭukā tiktā kaṣāyā śoṣahāriṇī uṣṇavīryā harenmedaḥ kuṣṭhaśvitravamikrimīn bastirugvraṇadāhāsrabalāsān garbhapātinī"},{"type":"verse","number":"26","sanskrit":"ककुभोऽजुननामाख्यो नदीसर्जश्च कीर्त्तितः इन्द्र द्रुर्वीरवृक्षश्च वीरश्च धवलः स्मृतः","text":"kakubho'junanāmākhyo nadīsarjaśca kīrttitaḥ indra drurvīravṛkṣaśca vīraśca dhavalaḥ smṛtaḥ"},{"type":"verse","number":"27","sanskrit":"कुकुभः शीतलो हृद्यः क्षतक्षयविषास्रजित् मेदोमेहव्रणान् हन्ति तुवरः कफपित्तहृत्","text":"kukubhaḥ śītalo hṛdyaḥ kṣatakṣayaviṣāsrajit medomehavraṇān hanti tuvaraḥ kaphapittahṛt"},{"type":"verse","number":"28","sanskrit":"बीजकः पीतसारश्च पीतशालक इत्यपि बन्धूकपुष्पः प्रियकः सर्जकश्चासनः स्मृतः","text":"bījakaḥ pītasāraśca pītaśālaka ityapi bandhūkapuṣpaḥ priyakaḥ sarjakaścāsanaḥ smṛtaḥ"},{"type":"verse","number":"29","sanskrit":"बीजकः कुष्ठवीसर्पश्वित्रमेहगुद क्रिमीन् हन्ति श्लेष्मास्रपित्तञ्च त्वच्यः केश्यो रसायनः","text":"bījakaḥ kuṣṭhavīsarpaśvitramehaguda krimīn hanti śleṣmāsrapittañca tvacyaḥ keśyo rasāyanaḥ"},{"type":"verse","number":"30","sanskrit":"खदिरो रक्तसारश्च गायत्री दन्तधावनः कण्टकी बालपत्रश्च बहुशल्यश्च यज्ञियः ६.","text":"khadiro raktasāraśca gāyatrī dantadhāvanaḥ kaṇṭakī bālapatraśca bahuśalyaśca yajñiyaḥ 6."},{"type":"verse","number":"31","sanskrit":"खदिरः शीतलो दन्त्यः कण्डूकासारुचिप्रणुत्","text":"khadiraḥ śītalo dantyaḥ kaṇḍūkāsārucipraṇut"},{"type":"verse","number":"32","sanskrit":"तिक्तः कषायो मेदोघ्नः कृमिमेहज्वरव्रणान् श्वित्रशोथामपित्तास्रपाण्डुकुष्ठकफान् हरेत्","text":"tiktaḥ kaṣāyo medoghnaḥ kṛmimehajvaravraṇān śvitraśothāmapittāsrapāṇḍukuṣṭhakaphān haret"},{"type":"verse","number":"33","sanskrit":"खदिरः श्वेतसारोऽन्य कदरः सोमवल्कलः कदरो विशदो वर्ण्यो मुखरोगकफास्रजित्","text":"khadiraḥ śvetasāro'nya kadaraḥ somavalkalaḥ kadaro viśado varṇyo mukharogakaphāsrajit"},{"type":"verse","number":"34","sanskrit":"इरिमेदो विट्खदिरः कालस्कन्धोऽरिमेदकः इरिमेदः कषायोष्णो मुखदन्तगदास्रजित् हन्ति कण्डूविषश्लेष्मकृमिकुष्ठविषव्रणान्","text":"irimedo viṭkhadiraḥ kālaskandho'rimedakaḥ irimedaḥ kaṣāyoṣṇo mukhadantagadāsrajit hanti kaṇḍūviṣaśleṣmakṛmikuṣṭhaviṣavraṇān"},{"type":"verse","number":"35","sanskrit":"रोहीतको रोहितको रोही दाडिमपुष्पकः रोहीतकः प्लीहघाती रुच्यो रक्तप्रसादनः","text":"rohītako rohitako rohī dāḍimapuṣpakaḥ rohītakaḥ plīhaghātī rucyo raktaprasādanaḥ"},{"type":"verse","number":"36","sanskrit":"बब्बूलः किङ्किरातः स्यात्किङ्किराटः सपीतकः","text":"babbūlaḥ kiṅkirātaḥ syātkiṅkirāṭaḥ sapītakaḥ"},{"type":"verse","number":"37","sanskrit":"स एव कथितस्तज्ज्ञैराभाषट्पदमोदिनी बब्बूलः कफनुद् ग्राही कुष्ठक्रिमिविषापहः","text":"sa eva kathitastajjñairābhāṣaṭpadamodinī babbūlaḥ kaphanud grāhī kuṣṭhakrimiviṣāpahaḥ"},{"type":"verse","number":"38","sanskrit":"अरिष्टकस्तु मङ्गल्यः कृष्णवर्णोऽथसाधनः रक्तबीजः पीतफेनः फेनिलो गर्भपातनः अरिष्टकस्त्रिदोषघ्नो ग्रहजिद् गर्भपातनः","text":"ariṣṭakastu maṅgalyaḥ kṛṣṇavarṇo'thasādhanaḥ raktabījaḥ pītaphenaḥ phenilo garbhapātanaḥ ariṣṭakastridoṣaghno grahajid garbhapātanaḥ"},{"type":"verse","number":"39","sanskrit":"पुत्रजीवो गर्भकरो यष्टीपुष्पोऽथसाधकः","text":"putrajīvo garbhakaro yaṣṭīpuṣpo'thasādhakaḥ"},{"type":"verse","number":"40","sanskrit":"पुत्रजीवी गुरुर्वृष्यो गर्भदः श्लेष्मवातहृत् सृष्टमूत्रमलो रूक्षो हिमः स्वादुः पटुः कटुः ६.","text":"putrajīvī gururvṛṣyo garbhadaḥ śleṣmavātahṛt sṛṣṭamūtramalo rūkṣo himaḥ svāduḥ paṭuḥ kaṭuḥ 6."},{"type":"verse","number":"41","sanskrit":"इङ्गुदोऽङ्गारवृक्षश्च तिक्तकस्तापसद्रुमः इङ्गुदः कुष्ठभूतादिग्रहव्रणविषक्रिमीन् हन्त्युष्णः श्वित्रशूलघ्नस्तिक्तकः कटुपाकवान्","text":"iṅgudo'ṅgāravṛkṣaśca tiktakastāpasadrumaḥ iṅgudaḥ kuṣṭhabhūtādigrahavraṇaviṣakrimīn hantyuṣṇaḥ śvitraśūlaghnastiktakaḥ kaṭupākavān"},{"type":"verse","number":"42","sanskrit":"जिङ्गिनी झिङ्गिनी झिङ्गी सुनिर्यासा प्रमोदिनी","text":"jiṅginī jhiṅginī jhiṅgī suniryāsā pramodinī"},{"type":"verse","number":"43","sanskrit":"जिङ्गिनी मधुरा सोष्णा कषाया योनिशोधिनी कटुका व्रणहृद्रो गवातातीसारहृत् पटुः","text":"jiṅginī madhurā soṣṇā kaṣāyā yoniśodhinī kaṭukā vraṇahṛdro gavātātīsārahṛt paṭuḥ"},{"type":"verse","number":"44","sanskrit":"तमाल उक्तस्तापिच्छः कालस्कन्धोऽमितद्रुमः लोकस्कन्धो नीलध्वजो नीलतालश्च स स्मृतः तमालः शालवद्वेद्यो दाहविस्फोटहृत् पुनः","text":"tamāla uktastāpicchaḥ kālaskandho'mitadrumaḥ lokaskandho nīladhvajo nīlatālaśca sa smṛtaḥ tamālaḥ śālavadvedyo dāhavisphoṭahṛt punaḥ"},{"type":"verse","number":"45","sanskrit":"तूणी तुन्नक आपीनस्तुणिकः कच्छकस्तथा कुठेरकः कान्तलको नन्दीवृक्षश्च नन्दकः","text":"tūṇī tunnaka āpīnastuṇikaḥ kacchakastathā kuṭherakaḥ kāntalako nandīvṛkṣaśca nandakaḥ"},{"type":"verse","number":"46","sanskrit":"तूणी रक्तः कटुः पाके कषायो मधुरो लघुः तिक्तो ग्राही हिमो वृष्यो व्रणकुष्ठास्रपित्तजित्","text":"tūṇī raktaḥ kaṭuḥ pāke kaṣāyo madhuro laghuḥ tikto grāhī himo vṛṣyo vraṇakuṣṭhāsrapittajit"},{"type":"verse","number":"47","sanskrit":"भूर्जपत्रः स्मृतो भूर्जश्चर्मी बहुलवल्कलः भूर्जो भूतग्रहश्लेष्मकर्णरुक्पित्तरक्तजित्","text":"bhūrjapatraḥ smṛto bhūrjaścarmī bahulavalkalaḥ bhūrjo bhūtagrahaśleṣmakarṇarukpittaraktajit"},{"type":"verse","number":"48","sanskrit":"कषायो राक्षसघ्नश्च मेदोविषहरः परः","text":"kaṣāyo rākṣasaghnaśca medoviṣaharaḥ paraḥ"},{"type":"verse","number":"49","sanskrit":"पलाशः किंशुकः पर्णो यज्ञियो रक्तपुष्पकः क्षारश्रेष्ठो वातपोथो ब्रह्मवृक्षः समिद्वरः","text":"palāśaḥ kiṃśukaḥ parṇo yajñiyo raktapuṣpakaḥ kṣāraśreṣṭho vātapotho brahmavṛkṣaḥ samidvaraḥ"},{"type":"verse","number":"50","sanskrit":"पलाशो दीपनो वृष्यः सरोष्णो व्रणगुल्मजित् भग्नसंधानकृद् दोषग्रहण्यर्शः क्रिमीन् हरेत् ६.","text":"palāśo dīpano vṛṣyaḥ saroṣṇo vraṇagulmajit bhagnasaṃdhānakṛd doṣagrahaṇyarśaḥ krimīn haret 6."},{"type":"verse","number":"51","sanskrit":"तत्पुष्पं स्वादु पाके तु कटु तिक्तं कषायकम्","text":"tatpuṣpaṃ svādu pāke tu kaṭu tiktaṃ kaṣāyakam"},{"type":"verse","number":"52","sanskrit":"वातलं कफपित्तास्रकृच्छ्रजिद् ग्राहि शीतलम् तृड्दाहशमकं वातरक्तकुष्ठहरं परम्","text":"vātalaṃ kaphapittāsrakṛcchrajid grāhi śītalam tṛḍdāhaśamakaṃ vātaraktakuṣṭhaharaṃ param"},{"type":"verse","number":"53","sanskrit":"फलं लघूष्णं मेहार्शःकृमिवातकफापहम् विपाके कटुकं रूक्षं कुष्ठं गुल्मोदरप्रणुत्","text":"phalaṃ laghūṣṇaṃ mehārśaḥkṛmivātakaphāpaham vipāke kaṭukaṃ rūkṣaṃ kuṣṭhaṃ gulmodarapraṇut"},{"type":"verse","number":"54","sanskrit":"शाल्मलिस्तु भवेन्मोचा पिच्छिला पूरणीति च रक्तपुष्पा स्थिरायुश्च कण्टकाढ्या च तूलिनी","text":"śālmalistu bhavenmocā picchilā pūraṇīti ca raktapuṣpā sthirāyuśca kaṇṭakāḍhyā ca tūlinī"},{"type":"verse","number":"55","sanskrit":"शाल्मली शीतला स्वाद्वी रसे पाके रसायनी श्लेष्मला पित्तवातास्रहारिणी रक्तपित्तजित्","text":"śālmalī śītalā svādvī rase pāke rasāyanī śleṣmalā pittavātāsrahāriṇī raktapittajit"},{"type":"verse","number":"56","sanskrit":"निर्यासः शाल्मलेः पिच्छा शाल्मलीवेष्टकोऽपि च मोचास्रावोमोचरसो मोचनिर्यास इत्यपि","text":"niryāsaḥ śālmaleḥ picchā śālmalīveṣṭako'pi ca mocāsrāvomocaraso mocaniryāsa ityapi"},{"type":"verse","number":"57","sanskrit":"मोचास्रावो हिमो ग्राही स्निग्धो वृष्यः कषायकः प्रवाहिकाऽतिसारामकफपित्तास्रदाहनुत्","text":"mocāsrāvo himo grāhī snigdho vṛṣyaḥ kaṣāyakaḥ pravāhikā'tisārāmakaphapittāsradāhanut"},{"type":"verse","number":"58","sanskrit":"कुत्सितः शाल्मलि प्रोक्तो रोचनः कूटशाल्मलि कूटशाल्मलिकस्तिक्तः कटुकः कफवातनुत्","text":"kutsitaḥ śālmali prokto rocanaḥ kūṭaśālmali kūṭaśālmalikastiktaḥ kaṭukaḥ kaphavātanut"},{"type":"verse","number":"59","sanskrit":"भेद्युष्णः प्लीहजठरयकृद्गुल्मविषापहः भूतानाहविबन्धास्रमेदः शूलकफापहः","text":"bhedyuṣṇaḥ plīhajaṭharayakṛdgulmaviṣāpahaḥ bhūtānāhavibandhāsramedaḥ śūlakaphāpahaḥ"},{"type":"verse","number":"60","sanskrit":"धवो धटो नन्दितरुः स्थिरो गौरो धुरन्धरः धवः शीतः प्रमेहार्शः पाण्डुपित्तकफापहः मधुरस्तुवरस्तस्य फलञ्च मधुरं मनाक् ६.","text":"dhavo dhaṭo nanditaruḥ sthiro gauro dhurandharaḥ dhavaḥ śītaḥ pramehārśaḥ pāṇḍupittakaphāpahaḥ madhurastuvarastasya phalañca madhuraṃ manāk 6."},{"type":"verse","number":"61","sanskrit":"धन्वङ्गस्तु धनुर्वृक्षो गोत्रवृक्षः सुतेजनः","text":"dhanvaṅgastu dhanurvṛkṣo gotravṛkṣaḥ sutejanaḥ"},{"type":"verse","number":"62","sanskrit":"धन्वङ्गः कफपित्तास्रकासहृत्तुवरो लघुः बृंहणो बलकृद्रू क्षः सन्धिकृद् व्रणरोपणः","text":"dhanvaṅgaḥ kaphapittāsrakāsahṛttuvaro laghuḥ bṛṃhaṇo balakṛdrū kṣaḥ sandhikṛd vraṇaropaṇaḥ"},{"type":"verse","number":"63","sanskrit":"करीरः क्रकरीपत्रो ग्रन्थिलो मरुभूरुहः करीरः कटुकस्तिक्त स्वेद्युष्णो भेदनः स्मृतः दुर्नामकफवातामगरशोथव्रणप्रणुत्","text":"karīraḥ krakarīpatro granthilo marubhūruhaḥ karīraḥ kaṭukastikta svedyuṣṇo bhedanaḥ smṛtaḥ durnāmakaphavātāmagaraśothavraṇapraṇut"},{"type":"verse","number":"64","sanskrit":"शाखोटः पीतफलको भूतावासः खरच्छदः शाखोटो रक्तपित्तार्शोवातश्लेष्मातिसारजित्","text":"śākhoṭaḥ pītaphalako bhūtāvāsaḥ kharacchadaḥ śākhoṭo raktapittārśovātaśleṣmātisārajit"},{"type":"verse","number":"65","sanskrit":"वरुणो वरणः सेतुस्तिक्तशाकः कुमारकः वरुणः पित्तलो भेदीश्लेष्मकृच्छ्राश्ममारुतान्","text":"varuṇo varaṇaḥ setustiktaśākaḥ kumārakaḥ varuṇaḥ pittalo bhedīśleṣmakṛcchrāśmamārutān"},{"type":"verse","number":"66","sanskrit":"निहन्ति गुल्मवातास्रकृमींश्चोष्णोऽग्निदीपनः कषायो मधुरस्तिक्तः कटुकोरूक्षको लघुः","text":"nihanti gulmavātāsrakṛmīṃścoṣṇo'gnidīpanaḥ kaṣāyo madhurastiktaḥ kaṭukorūkṣako laghuḥ"},{"type":"verse","number":"67","sanskrit":"कटभी स्वादुपुष्पश्च मधुरेणुः कटम्भरः कटभी तु प्रमेहार्शोनाडीव्रणविषक्रिमीन्","text":"kaṭabhī svādupuṣpaśca madhureṇuḥ kaṭambharaḥ kaṭabhī tu pramehārśonāḍīvraṇaviṣakrimīn"},{"type":"verse","number":"68","sanskrit":"हन्त्युष्णा कफकुष्ठघ्नी कटू रूक्षा च कीर्तिता तत्फलं तुवरं ज्ञेयं विशेषात्कफशुक्रहृत्","text":"hantyuṣṇā kaphakuṣṭhaghnī kaṭū rūkṣā ca kīrtitā tatphalaṃ tuvaraṃ jñeyaṃ viśeṣātkaphaśukrahṛt"},{"type":"verse","number":"69","sanskrit":"मोक्षस्तु मोक्षकोऽपि स्याद् गोलीढोगोलिहस्तथा क्षारश्रेष्ठः क्षारवृक्षो द्विविधः श्वेतकृष्णकः","text":"mokṣastu mokṣako'pi syād golīḍhogolihastathā kṣāraśreṣṭhaḥ kṣāravṛkṣo dvividhaḥ śvetakṛṣṇakaḥ"},{"type":"verse","number":"70","sanskrit":"मोक्षकः कटुकस्तिक्तो ग्राह्युष्णः कफवातहृत् विषमेदोगुल्मकण्डूबस्तिरुक्कृमिशुक्रनुत् ६.","text":"mokṣakaḥ kaṭukastikto grāhyuṣṇaḥ kaphavātahṛt viṣamedogulmakaṇḍūbastirukkṛmiśukranut 6."},{"type":"verse","number":"71","sanskrit":"शिरीषिका टिण्टिनिका दुर्बलाऽम्बुशिरीषिका त्रिदोषविषकुष्ठार्शोहरी वारिशिरीषिका","text":"śirīṣikā ṭiṇṭinikā durbalā'mbuśirīṣikā tridoṣaviṣakuṣṭhārśoharī vāriśirīṣikā"},{"type":"verse","number":"72","sanskrit":"शमी शक्तुफला तुङ्गा केशहन्त्री शिवाफला मंगल्या च तथा लक्ष्मीः शमीरः साऽल्पिका स्मृता","text":"śamī śaktuphalā tuṅgā keśahantrī śivāphalā maṃgalyā ca tathā lakṣmīḥ śamīraḥ sā'lpikā smṛtā"},{"type":"verse","number":"73","sanskrit":"शमी तिक्ता कटुः शीता कषाया रेचनी लघुः कफकासभ्रमश्वासकुष्ठार्शः कृमिजित् स्मृता","text":"śamī tiktā kaṭuḥ śītā kaṣāyā recanī laghuḥ kaphakāsabhramaśvāsakuṣṭhārśaḥ kṛmijit smṛtā"},{"type":"verse","number":"74","sanskrit":"सप्तपर्णो विशालत्वक् शारदो विषमच्छदः","text":"saptaparṇo viśālatvak śārado viṣamacchadaḥ"},{"type":"verse","number":"75","sanskrit":"सप्तपर्णो व्रणश्लेष्मवातकुष्ठास्रजन्तुजित् दीपनः श्वासगुल्मघ्नः स्निग्धोष्णस्तुवरः सरः","text":"saptaparṇo vraṇaśleṣmavātakuṣṭhāsrajantujit dīpanaḥ śvāsagulmaghnaḥ snigdhoṣṇastuvaraḥ saraḥ"},{"type":"verse","number":"76","sanskrit":"तिनिशः स्यन्दनो नेमी रथद्रुर्वञ्जुलस्तथा तिनिशः श्लेष्मपित्तास्रमेदःकुष्ठप्रमेहजित् तुवरः श्वित्रदाहघ्नो व्रणपाण्डुकृमिप्रणुत्","text":"tiniśaḥ syandano nemī rathadrurvañjulastathā tiniśaḥ śleṣmapittāsramedaḥkuṣṭhapramehajit tuvaraḥ śvitradāhaghno vraṇapāṇḍukṛmipraṇut"},{"type":"verse","number":"77","sanskrit":"भूमीसहो द्वारदारुर्वरदारुः खरच्छदः भूमीसहस्तु शिशिरो रक्तपित्तप्रसादनः","text":"bhūmīsaho dvāradārurvaradāruḥ kharacchadaḥ bhūmīsahastu śiśiro raktapittaprasādanaḥ"},{"type":"verse","number":"6","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे षष्ठो वटादिवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe ṣaṣṭho vaṭādivargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":6,"lang":"sa","content":[{"type":"heading","heading":"āmrādiphala-варга — плоды (манго и др.)"},{"type":"verse","number":"1","sanskrit":"आम्रश्चूतो रसालश्च सहकारोऽतिसौरभः कामाङ्गो मधुदूतश्च माकन्दः पिकवल्लभः","text":"āmraścūto rasālaśca sahakāro'tisaurabhaḥ kāmāṅgo madhudūtaśca mākandaḥ pikavallabhaḥ"},{"type":"verse","number":"2","sanskrit":"असृग्दुष्टिहरं शीतं रुचिकृद् ग्राहि वातलम्","text":"asṛgduṣṭiharaṃ śītaṃ rucikṛd grāhi vātalam"},{"type":"verse","number":"3","sanskrit":"आमं बालं कषायाम्लं रुच्यं मारुतपित्तकृत् तरुणं तु तदत्यम्लं रूक्षं दोषत्रयास्रकृत्","text":"āmaṃ bālaṃ kaṣāyāmlaṃ rucyaṃ mārutapittakṛt taruṇaṃ tu tadatyamlaṃ rūkṣaṃ doṣatrayāsrakṛt"},{"type":"verse","number":"4","sanskrit":"आम्रमामं त्वचाहीनमातपेऽतिविशोषितम् अम्लं स्वादु कषायं स्याद्भेदनं कफवातजित्","text":"āmramāmaṃ tvacāhīnamātape'tiviśoṣitam amlaṃ svādu kaṣāyaṃ syādbhedanaṃ kaphavātajit"},{"type":"verse","number":"5","sanskrit":"पक्वं तु मधुरं वृष्यं स्निग्धं बलसुखप्रदम् गुरु वातहरं हृद्यं वर्ण्यं शीतमपित्तलम् कषायानुरसं वह्निश्लेश्मशुक्रविवर्द्धनम्","text":"pakvaṃ tu madhuraṃ vṛṣyaṃ snigdhaṃ balasukhapradam guru vātaharaṃ hṛdyaṃ varṇyaṃ śītamapittalam kaṣāyānurasaṃ vahniśleśmaśukravivarddhanam"},{"type":"verse","number":"6","sanskrit":"तदेव वृक्षसम्पक्वं गुरु वातहरं परम् मधुराम्लरसं किञ्चिद्भवेत्पित्तप्रकोपणम्","text":"tadeva vṛkṣasampakvaṃ guru vātaharaṃ param madhurāmlarasaṃ kiñcidbhavetpittaprakopaṇam"},{"type":"verse","number":"7","sanskrit":"आम्रं कृत्रिमपक्वञ्च तद्भवेत्पित्तनाशनम् रसस्याम्लस्य हीनस्तु माधुर्याच्च विशेषतः","text":"āmraṃ kṛtrimapakvañca tadbhavetpittanāśanam rasasyāmlasya hīnastu mādhuryācca viśeṣataḥ"},{"type":"verse","number":"8","sanskrit":"चूषितं तत्परं रुच्यं बलवीर्यकरं लघु शीतलं शीघ्रपाकि स्याद्वातपित्तहरं सरम्","text":"cūṣitaṃ tatparaṃ rucyaṃ balavīryakaraṃ laghu śītalaṃ śīghrapāki syādvātapittaharaṃ saram"},{"type":"verse","number":"9","sanskrit":"तद्र सो गालितो बल्यो गुरुर्वातहरः सरः अहृद्यस्तर्पणोऽतीव बृंहणः कफवर्द्धनः","text":"tadra so gālito balyo gururvātaharaḥ saraḥ ahṛdyastarpaṇo'tīva bṛṃhaṇaḥ kaphavarddhanaḥ"},{"type":"verse","number":"10","sanskrit":"तस्य खण्डं गुरु परं रोचनं चिरपाकि च मधुरं बृंहणं बल्यं शीतलं वातनाशनम् ७.","text":"tasya khaṇḍaṃ guru paraṃ rocanaṃ cirapāki ca madhuraṃ bṛṃhaṇaṃ balyaṃ śītalaṃ vātanāśanam 7."},{"type":"verse","number":"11","sanskrit":"वातपित्तहरं रुच्यं बृंहणं बलवर्द्धनम् वृष्यं वर्णकरं स्वादु दुग्धाम्र गुरु शीतलम्","text":"vātapittaharaṃ rucyaṃ bṛṃhaṇaṃ balavarddhanam vṛṣyaṃ varṇakaraṃ svādu dugdhāmra guru śītalam"},{"type":"verse","number":"12","sanskrit":"मन्दानलत्वं विषमज्वरं च रक्तामयं बद्धगुदोदरं च आम्रातियोगो नयनामयं वा करोति तस्मादति तानि नाद्यात्","text":"mandānalatvaṃ viṣamajvaraṃ ca raktāmayaṃ baddhagudodaraṃ ca āmrātiyogo nayanāmayaṃ vā karoti tasmādati tāni nādyāt"},{"type":"verse","number":"13","sanskrit":"एतदम्लाम्रविषयं मधुराम्लपरं न तु मधुरस्य परं नेत्रहितत्वाद्या गुणा यतः","text":"etadamlāmraviṣayaṃ madhurāmlaparaṃ na tu madhurasya paraṃ netrahitatvādyā guṇā yataḥ"},{"type":"verse","number":"14","sanskrit":"शुण्ठ्यम्भसोऽनुपानं स्यादाम्राणामतिभक्षणे जीरकं वा प्रयोक्तव्यं सह सौवर्चलेन च","text":"śuṇṭhyambhaso'nupānaṃ syādāmrāṇāmatibhakṣaṇe jīrakaṃ vā prayoktavyaṃ saha sauvarcalena ca"},{"type":"verse","number":"15","sanskrit":"पक्वस्य सहकारस्य पटे विस्तारितो रसः घर्मशुष्को मुहुर्दत्त आम्रावर्त्त इति स्मृतः","text":"pakvasya sahakārasya paṭe vistārito rasaḥ gharmaśuṣko muhurdatta āmrāvartta iti smṛtaḥ"},{"type":"verse","number":"16","sanskrit":"आम्रावर्त्तस्तृषाच्छर्दि वातपित्तहरः सरः रुच्यः सूर्यांशुभिः पाकाल्लघुश्च स हि कीर्त्तितः","text":"āmrāvarttastṛṣācchardi vātapittaharaḥ saraḥ rucyaḥ sūryāṃśubhiḥ pākāllaghuśca sa hi kīrttitaḥ"},{"type":"verse","number":"17","sanskrit":"आम्रबीजं कषायं स्याच्छर्द्यतीसारनाशनम् ईषदम्लञ्च मधुरं तथा हृदयदाहनुत्","text":"āmrabījaṃ kaṣāyaṃ syācchardyatīsāranāśanam īṣadamlañca madhuraṃ tathā hṛdayadāhanut"},{"type":"verse","number":"18","sanskrit":"आम्रस्य पल्लवो रुच्यः कफपित्तविनाशनः","text":"āmrasya pallavo rucyaḥ kaphapittavināśanaḥ"},{"type":"verse","number":"19","sanskrit":"आम्रातकः पीतनश्च मर्कटाम्रः कपीतनः आम्रातमम्लं वातघ्नं गुरूष्णं रुचिकृत्सरम्","text":"āmrātakaḥ pītanaśca markaṭāmraḥ kapītanaḥ āmrātamamlaṃ vātaghnaṃ gurūṣṇaṃ rucikṛtsaram"},{"type":"verse","number":"20","sanskrit":"पक्वन्तु तुवरं स्वादु रसे पाके हिमं स्मृतम् तर्पणं श्लेष्मलं स्निग्धं वृष्यं विष्टम्भि बृंहणम् गुरु बल्यं मरुत्पित्तक्षतदाहक्षयास्रजित् ७.","text":"pakvantu tuvaraṃ svādu rase pāke himaṃ smṛtam tarpaṇaṃ śleṣmalaṃ snigdhaṃ vṛṣyaṃ viṣṭambhi bṛṃhaṇam guru balyaṃ marutpittakṣatadāhakṣayāsrajit 7."},{"type":"verse","number":"21","sanskrit":"राजाम्रष्टङ्क आम्रातः कामाह्वो राजपुत्रकः","text":"rājāmraṣṭaṅka āmrātaḥ kāmāhvo rājaputrakaḥ"},{"type":"verse","number":"22","sanskrit":"राजाम्रं तुवरं स्वादु विशदं शीतलं गुरु ग्राहि रूक्षं विबन्धाध्मवातकृत्कफपित्तनुत्","text":"rājāmraṃ tuvaraṃ svādu viśadaṃ śītalaṃ guru grāhi rūkṣaṃ vibandhādhmavātakṛtkaphapittanut"},{"type":"verse","number":"23","sanskrit":"कोशाम्र उक्तः क्षुद्रा म्रः कृमिवृक्षः सुकोशकः कोशाम्रः कुष्ठशोथास्रपित्तव्रणकफापहः","text":"kośāmra uktaḥ kṣudrā mraḥ kṛmivṛkṣaḥ sukośakaḥ kośāmraḥ kuṣṭhaśothāsrapittavraṇakaphāpahaḥ"},{"type":"verse","number":"24","sanskrit":"तत्फलं ग्राहि वातघ्नमम्लोष्णं गुरु पित्तलम् पक्वन्तु दीपनं रुच्यं लघूष्णं कफवातनुत्","text":"tatphalaṃ grāhi vātaghnamamloṣṇaṃ guru pittalam pakvantu dīpanaṃ rucyaṃ laghūṣṇaṃ kaphavātanut"},{"type":"verse","number":"25","sanskrit":"पनशः कण्टकिफलः पलसोऽतिबृहत्फलः पनसं शीतलं पक्वं स्निग्धं पित्तानिलापहम्","text":"panaśaḥ kaṇṭakiphalaḥ palaso'tibṛhatphalaḥ panasaṃ śītalaṃ pakvaṃ snigdhaṃ pittānilāpaham"},{"type":"verse","number":"26","sanskrit":"तर्पणं बृंहणं स्वादु मांसलं श्लेष्मलंभृशम् बल्यं शुक्रपदं हन्ति रक्तपित्तक्षतव्रणान्","text":"tarpaṇaṃ bṛṃhaṇaṃ svādu māṃsalaṃ śleṣmalaṃbhṛśam balyaṃ śukrapadaṃ hanti raktapittakṣatavraṇān"},{"type":"verse","number":"27","sanskrit":"आमं तदेव विष्टम्भि वातलं तुवरं गुरु दाहकृन्मधुरं बल्यं कफमेदोविवर्द्धनम्","text":"āmaṃ tadeva viṣṭambhi vātalaṃ tuvaraṃ guru dāhakṛnmadhuraṃ balyaṃ kaphamedovivarddhanam"},{"type":"verse","number":"28","sanskrit":"पनसोद्भूतबीजानि वृष्याणि मधुराणि च गुरूणि बद्धविट्कानि सृष्टमूत्राणि संवदेत्","text":"panasodbhūtabījāni vṛṣyāṇi madhurāṇi ca gurūṇi baddhaviṭkāni sṛṣṭamūtrāṇi saṃvadet"},{"type":"verse","number":"29","sanskrit":"मज्जा पनसजो वृष्यो वातपित्तकफापहः विशेषात्पनसो वर्ज्यो गुल्मिभिर्मन्दवह्निभिः","text":"majjā panasajo vṛṣyo vātapittakaphāpahaḥ viśeṣātpanaso varjyo gulmibhirmandavahnibhiḥ"},{"type":"verse","number":"30","sanskrit":"लकुचः छुद्र पनसो लिकुचो डहुर्रित्यपि आमं लकुचमुष्णञ्च गुरु विष्टम्भकृत्तथा ७.","text":"lakucaḥ chudra panaso likuco ḍahurrityapi āmaṃ lakucamuṣṇañca guru viṣṭambhakṛttathā 7."},{"type":"verse","number":"31","sanskrit":"मधुरश्च तथाऽम्लञ्च दोषत्रितयरक्तकृत् शुक्राग्निनाशनं वाऽपि नेत्रयोरहितं स्मृतम्","text":"madhuraśca tathā'mlañca doṣatritayaraktakṛt śukrāgnināśanaṃ vā'pi netrayorahitaṃ smṛtam"},{"type":"verse","number":"32","sanskrit":"सुपक्वं तत्तु मधुरमम्लं चानिलपित्तहृत् कफवह्निकरं रुच्यं वृष्यं विष्टम्भकञ्च तत्","text":"supakvaṃ tattu madhuramamlaṃ cānilapittahṛt kaphavahnikaraṃ rucyaṃ vṛṣyaṃ viṣṭambhakañca tat"},{"type":"verse","number":"33","sanskrit":"कदली वारणा मोचाऽम्बुसारांऽशुमतीफला मोचाफलं स्वादु शीतं विष्टम्भि कफकृद् गुरु","text":"kadalī vāraṇā mocā'mbusārāṃ'śumatīphalā mocāphalaṃ svādu śītaṃ viṣṭambhi kaphakṛd guru"},{"type":"verse","number":"34","sanskrit":"स्निग्धं पित्तास्रतृड्दाहक्षतक्षयसमीरजित् पक्वं स्वादु हिमं पाके स्वादु वृष्यञ्च बृंहणम् क्षुत्तृष्णानेत्रगदहृन्मेहघ्नं रुचिमांसकृत्","text":"snigdhaṃ pittāsratṛḍdāhakṣatakṣayasamīrajit pakvaṃ svādu himaṃ pāke svādu vṛṣyañca bṛṃhaṇam kṣuttṛṣṇānetragadahṛnmehaghnaṃ rucimāṃsakṛt"},{"type":"verse","number":"35","sanskrit":"माणिक्यमर्त्यामृतचम्पकाद्या भेदाः कदल्या बहवोऽपि सन्ति उक्ता गुणास्तेष्वधिका भवन्ति निर्दोषता स्याल्लघुता च तेषाम्","text":"māṇikyamartyāmṛtacampakādyā bhedāḥ kadalyā bahavo'pi santi uktā guṇāsteṣvadhikā bhavanti nirdoṣatā syāllaghutā ca teṣām"},{"type":"verse","number":"36","sanskrit":"चिर्भिटं धेनुदुग्धं च तथा गोरक्षकर्कटी","text":"cirbhiṭaṃ dhenudugdhaṃ ca tathā gorakṣakarkaṭī"},{"type":"verse","number":"37","sanskrit":"चिर्भिटं मधुरं रूक्षं गुरु पित्तकफापहम् अनुष्णं ग्राहि विष्टम्भि पक्वं तूष्णञ्च पित्तलम्","text":"cirbhiṭaṃ madhuraṃ rūkṣaṃ guru pittakaphāpaham anuṣṇaṃ grāhi viṣṭambhi pakvaṃ tūṣṇañca pittalam"},{"type":"verse","number":"38","sanskrit":"नारिकेलो दृढफलो लाङ्गली कूर्चर्श्षकः तुङ्गः स्कन्धफलश्चैव तृणराजः सदाफलः","text":"nārikelo dṛḍhaphalo lāṅgalī kūrcarśṣakaḥ tuṅgaḥ skandhaphalaścaiva tṛṇarājaḥ sadāphalaḥ"},{"type":"verse","number":"39","sanskrit":"नारिकेलफलं शीतं दुर्जरं बस्तिशोधनम् विष्टम्भि बृंहणं बल्यं वातपित्तास्रदाहनुत्","text":"nārikelaphalaṃ śītaṃ durjaraṃ bastiśodhanam viṣṭambhi bṛṃhaṇaṃ balyaṃ vātapittāsradāhanut"},{"type":"verse","number":"40","sanskrit":"विशेषतः कोमलनारिकेलं निहन्ति पित्तज्वरपित्तदोषान् तदेव जीर्णं गुरु पित्तकारि विदाहि विष्टम्भि मतं भिषग्भिः ७.","text":"viśeṣataḥ komalanārikelaṃ nihanti pittajvarapittadoṣān tadeva jīrṇaṃ guru pittakāri vidāhi viṣṭambhi mataṃ bhiṣagbhiḥ 7."},{"type":"verse","number":"41","sanskrit":"तस्याम्भः शीतलं हृद्यं दीपनं शुक्रलं लघु पिपासापित्तजित्स्वादु बस्तिशुद्धिकरं परम्","text":"tasyāmbhaḥ śītalaṃ hṛdyaṃ dīpanaṃ śukralaṃ laghu pipāsāpittajitsvādu bastiśuddhikaraṃ param"},{"type":"verse","number":"42","sanskrit":"नारिकेलस्य तालस्य खर्जूरस्य शिरांसि तु कषायस्निग्धमधुरबृंहणानि गुरूणि च","text":"nārikelasya tālasya kharjūrasya śirāṃsi tu kaṣāyasnigdhamadhurabṛṃhaṇāni gurūṇi ca"},{"type":"verse","number":"43","sanskrit":"कालिन्दं कृष्णबीजं स्यात्कालिङ्गञ्च सुवर्त्तुलम् कालिन्दं ग्राहि दृक्पित्त शुक्र हृच्छीतलं गुरु पक्वन्तु सोष्णं सक्षारं पित्तलं कफवातजित्","text":"kālindaṃ kṛṣṇabījaṃ syātkāliṅgañca suvarttulam kālindaṃ grāhi dṛkpitta śukra hṛcchītalaṃ guru pakvantu soṣṇaṃ sakṣāraṃ pittalaṃ kaphavātajit"},{"type":"verse","number":"44","sanskrit":"दशाङ्गुलं तु खर्बूजं कथ्यन्ते तद्गुणा अथ","text":"daśāṅgulaṃ tu kharbūjaṃ kathyante tadguṇā atha"},{"type":"verse","number":"45","sanskrit":"खर्बूजं मूत्रलं बल्यं कोष्ठशुद्धिकरं गुरु स्निग्धं स्वादुतरं शीतं वृष्यं पित्तानिलापहम्","text":"kharbūjaṃ mūtralaṃ balyaṃ koṣṭhaśuddhikaraṃ guru snigdhaṃ svādutaraṃ śītaṃ vṛṣyaṃ pittānilāpaham"},{"type":"verse","number":"46","sanskrit":"तेषु यच्चाम्लमधुरं सक्षारञ्च रसाद्भवेत् रक्तपित्तकरं तत्तु मूत्रकृच्छ्रकरं परम्","text":"teṣu yaccāmlamadhuraṃ sakṣārañca rasādbhavet raktapittakaraṃ tattu mūtrakṛcchrakaraṃ param"},{"type":"verse","number":"47","sanskrit":"त्रपुसं कण्टकिफलं सुधावासः सुशीतलम् त्रपुसं लघु नीलञ्च नवं तृट्क्लमदाहजित्","text":"trapusaṃ kaṇṭakiphalaṃ sudhāvāsaḥ suśītalam trapusaṃ laghu nīlañca navaṃ tṛṭklamadāhajit"},{"type":"verse","number":"48","sanskrit":"स्वादु पित्तापहं शीतं रक्तपित्तहरं परम् तत्पक्वमम्लमुष्णं स्यात्पित्तलं कफवातनुत् तद्बीजं मूत्रलं शीतं रूक्षं पित्तास्रकृच्छ्रजित्","text":"svādu pittāpahaṃ śītaṃ raktapittaharaṃ param tatpakvamamlamuṣṇaṃ syātpittalaṃ kaphavātanut tadbījaṃ mūtralaṃ śītaṃ rūkṣaṃ pittāsrakṛcchrajit"},{"type":"verse","number":"49","sanskrit":"घोरण्टः पूगी पूगश्च गुवाकः क्रमुकोऽस्य तु फलं पूगीफलं प्रोक्तमुद्वेगं च तदीरितम्","text":"ghoraṇṭaḥ pūgī pūgaśca guvākaḥ kramuko'sya tu phalaṃ pūgīphalaṃ proktamudvegaṃ ca tadīritam"},{"type":"verse","number":"50","sanskrit":"पूगं गुरु हिमं रूक्षं कषायं कफपित्तजित् मोहनं दीपनं रुच्यमास्यवैरस्यनाशनम् ७.","text":"pūgaṃ guru himaṃ rūkṣaṃ kaṣāyaṃ kaphapittajit mohanaṃ dīpanaṃ rucyamāsyavairasyanāśanam 7."},{"type":"verse","number":"51","sanskrit":"आद्र रं! तद् गुर्वभिष्यन्दि वह्निदृष्टिहरं स्मृतम् स्विन्नं दोषत्रयच्छेदि दृढमध्यं तदुत्तमम्","text":"ādra raṃ! tad gurvabhiṣyandi vahnidṛṣṭiharaṃ smṛtam svinnaṃ doṣatrayacchedi dṛḍhamadhyaṃ taduttamam"},{"type":"verse","number":"52","sanskrit":"तालस्तु लेख्यपत्रः स्यात्तृणराजो महोन्नतः","text":"tālastu lekhyapatraḥ syāttṛṇarājo mahonnataḥ"},{"type":"verse","number":"53","sanskrit":"पक्वं तालफलं पित्तरक्तश्लेष्मविवर्द्धनम् दुर्जरं बहुमूत्रञ्च तन्द्रा ऽभिष्यन्दशुक्रदम्","text":"pakvaṃ tālaphalaṃ pittaraktaśleṣmavivarddhanam durjaraṃ bahumūtrañca tandrā 'bhiṣyandaśukradam"},{"type":"verse","number":"54","sanskrit":"तालमज्जा तु तरुणः किञ्चिन्मदकरो लघुः श्लेष्मलो वातपित्तघ्नः सस्नेहो मधुरः सरः","text":"tālamajjā tu taruṇaḥ kiñcinmadakaro laghuḥ śleṣmalo vātapittaghnaḥ sasneho madhuraḥ saraḥ"},{"type":"verse","number":"55","sanskrit":"तालजं तरुणं तोयमतीव मदकृन्मतम् अम्लीभूतं तदा तु स्यात्पित्तकृद्वातदोषहृत्","text":"tālajaṃ taruṇaṃ toyamatīva madakṛnmatam amlībhūtaṃ tadā tu syātpittakṛdvātadoṣahṛt"},{"type":"verse","number":"56","sanskrit":"बिल्वः शाण्डिल्यशैलूषौ मालूरश्रीफलावपि बालं बिल्बफलं बिल्वकर्कटी बिल्वपेशिका ग्राहिणी कफवातामशूलघ्नी बिल्वपेषिका","text":"bilvaḥ śāṇḍilyaśailūṣau mālūraśrīphalāvapi bālaṃ bilbaphalaṃ bilvakarkaṭī bilvapeśikā grāhiṇī kaphavātāmaśūlaghnī bilvapeṣikā"},{"type":"verse","number":"57","sanskrit":"बालं बिल्वफलं ग्राहि दीपनं पाचनं कटु कषायोष्णं लघु स्निग्धं तिक्तं वातकफापहम्","text":"bālaṃ bilvaphalaṃ grāhi dīpanaṃ pācanaṃ kaṭu kaṣāyoṣṇaṃ laghu snigdhaṃ tiktaṃ vātakaphāpaham"},{"type":"verse","number":"58","sanskrit":"पक्वं गुरु त्रिदोषं स्याद् दुर्जरं पूतिमारुतम् विदाहि विष्टम्भकरं मधुरं वह्निमान्द्यकृत्","text":"pakvaṃ guru tridoṣaṃ syād durjaraṃ pūtimārutam vidāhi viṣṭambhakaraṃ madhuraṃ vahnimāndyakṛt"},{"type":"verse","number":"59","sanskrit":"फलेषु परिपक्वं यद् गुणवत्तदुदाहृतम्","text":"phaleṣu paripakvaṃ yad guṇavattadudāhṛtam"},{"type":"verse","number":"60","sanskrit":"बिल्वादन्यत्र विज्ञेयमामं तद्धि गुणाधिकम् द्रा क्षाबिल्वशिवाऽदीनां फलं शुष्कं गुणाधिकम् ७.","text":"bilvādanyatra vijñeyamāmaṃ taddhi guṇādhikam drā kṣābilvaśivā'dīnāṃ phalaṃ śuṣkaṃ guṇādhikam 7."},{"type":"verse","number":"61","sanskrit":"कपित्थस्तु दधित्थः स्यात्तथा पुष्पफलः स्मृतः कपिप्रियो दधिफलस्तथा दन्तशठोऽपि च","text":"kapitthastu dadhitthaḥ syāttathā puṣpaphalaḥ smṛtaḥ kapipriyo dadhiphalastathā dantaśaṭho'pi ca"},{"type":"verse","number":"62","sanskrit":"कपित्थमामं संग्राहि कषायं लघु लेखनम् पक्वं गुरु तृषाहिक्काशमनं वातपित्तजित् स्यादम्लं तुवरं कण्ठशोधनं ग्राहि दुर्जरम्","text":"kapitthamāmaṃ saṃgrāhi kaṣāyaṃ laghu lekhanam pakvaṃ guru tṛṣāhikkāśamanaṃ vātapittajit syādamlaṃ tuvaraṃ kaṇṭhaśodhanaṃ grāhi durjaram"},{"type":"verse","number":"63","sanskrit":"नारङ्गो नागरङ्गः स्यात्त्वक्सुगन्धो मुखप्रियः","text":"nāraṅgo nāgaraṅgaḥ syāttvaksugandho mukhapriyaḥ"},{"type":"verse","number":"64","sanskrit":"नारङ्गो मधुराम्लः स्याद्रो चनो वातनाशनः अपरं त्वम्लमत्युष्णं दुर्जरं वातहृत् सरम्","text":"nāraṅgo madhurāmlaḥ syādro cano vātanāśanaḥ aparaṃ tvamlamatyuṣṇaṃ durjaraṃ vātahṛt saram"},{"type":"verse","number":"65","sanskrit":"तिन्दुकः स्फूर्जकः कालस्कन्धश्चासितकारकः स्यादामं तिन्दुकं ग्राहि वातलं शीतलं लघु पक्वं पित्तप्रमेहास्रश्लेष्मघ्नं मधुरं गुरु","text":"tindukaḥ sphūrjakaḥ kālaskandhaścāsitakārakaḥ syādāmaṃ tindukaṃ grāhi vātalaṃ śītalaṃ laghu pakvaṃ pittapramehāsraśleṣmaghnaṃ madhuraṃ guru"},{"type":"verse","number":"66","sanskrit":"तिन्दुको यस्तु कथितो जलदो दीर्घपत्रकः","text":"tinduko yastu kathito jalado dīrghapatrakaḥ"},{"type":"verse","number":"67","sanskrit":"कुपीलुः कुलकः काकतिन्दुकः काकपीलुकः काकेन्दुर्विषतिन्दुश्च तथा मर्कटतिन्दुकः","text":"kupīluḥ kulakaḥ kākatindukaḥ kākapīlukaḥ kākendurviṣatinduśca tathā markaṭatindukaḥ"},{"type":"verse","number":"68","sanskrit":"कुपीलुः शीतलं तिक्तं वातलं मदकृल्लघु परं व्यथाहरं ग्राहि कफपित्तास्रनाशनम्","text":"kupīluḥ śītalaṃ tiktaṃ vātalaṃ madakṛllaghu paraṃ vyathāharaṃ grāhi kaphapittāsranāśanam"},{"type":"verse","number":"69","sanskrit":"फलेन्द्रा कथिता नन्दी राजजम्बूर्महाफला तथा सुरभिपत्रा च महाजम्बूरपि स्मृता राजजम्बूफलं स्वादु विष्टम्भि गुरु रोचनम्","text":"phalendrā kathitā nandī rājajambūrmahāphalā tathā surabhipatrā ca mahājambūrapi smṛtā rājajambūphalaṃ svādu viṣṭambhi guru rocanam"},{"type":"verse","number":"70","sanskrit":"क्षुद्र जम्बुः सूक्ष्मपत्रा नादेयी जलजम्बुका जम्बूः संग्राहिणी रूक्षा कफपित्तास्रदाहजित् ७.","text":"kṣudra jambuḥ sūkṣmapatrā nādeyī jalajambukā jambūḥ saṃgrāhiṇī rūkṣā kaphapittāsradāhajit 7."},{"type":"verse","number":"71","sanskrit":"पुंसि स्त्रियाञ्च कर्कन्धूर्बदरी कोलमित्यपि","text":"puṃsi striyāñca karkandhūrbadarī kolamityapi"},{"type":"verse","number":"72","sanskrit":"फेनिलं कुवलं घोण्टा सौवीरं बदरं महत् अजप्रिया कुहा कोली विषमोभयकण्टका","text":"phenilaṃ kuvalaṃ ghoṇṭā sauvīraṃ badaraṃ mahat ajapriyā kuhā kolī viṣamobhayakaṇṭakā"},{"type":"verse","number":"73","sanskrit":"पच्यमानं सुमधुरं सौवीरं बदरं महत् सौवीरं बदरं शीतं भेदनं गुरु शुक्रलम्","text":"pacyamānaṃ sumadhuraṃ sauvīraṃ badaraṃ mahat sauvīraṃ badaraṃ śītaṃ bhedanaṃ guru śukralam"},{"type":"verse","number":"74","sanskrit":"बृंहणं पित्तदाहास्रक्षयतृष्णानिवारणम् सौवीरं लघु सम्पक्वं मधुरं कोलमुच्यते","text":"bṛṃhaṇaṃ pittadāhāsrakṣayatṛṣṇānivāraṇam sauvīraṃ laghu sampakvaṃ madhuraṃ kolamucyate"},{"type":"verse","number":"75","sanskrit":"कोलन्तु बदरं ग्राहि रुच्यमुष्णञ्च वातहृत् कफपित्तकरं चापि गुरु सारकमीरितम्","text":"kolantu badaraṃ grāhi rucyamuṣṇañca vātahṛt kaphapittakaraṃ cāpi guru sārakamīritam"},{"type":"verse","number":"76","sanskrit":"कर्कन्धूः क्षुद्र वदरं कथितं पूर्वसूरिभिः अम्लं स्यात्क्षुद्र वदरं कषायं मधुरं मनाक्","text":"karkandhūḥ kṣudra vadaraṃ kathitaṃ pūrvasūribhiḥ amlaṃ syātkṣudra vadaraṃ kaṣāyaṃ madhuraṃ manāk"},{"type":"verse","number":"77","sanskrit":"स्निग्धं गुरु च तिक्तञ्च वातपित्तापहं स्मृतम् शुष्कं भेद्यग्निकृत्सर्वं लघु तृष्णाक्लमास्रजित्","text":"snigdhaṃ guru ca tiktañca vātapittāpahaṃ smṛtam śuṣkaṃ bhedyagnikṛtsarvaṃ laghu tṛṣṇāklamāsrajit"},{"type":"verse","number":"78","sanskrit":"प्राचीनामलकं लोके पानीयामलकं स्मृतम् प्राचीनामलकं दोषत्रयजिज्ज्वरघाति च","text":"prācīnāmalakaṃ loke pānīyāmalakaṃ smṛtam prācīnāmalakaṃ doṣatrayajijjvaraghāti ca"},{"type":"verse","number":"79","sanskrit":"सुगन्धमूला लवली पाण्डुः कोमलवल्कला","text":"sugandhamūlā lavalī pāṇḍuḥ komalavalkalā"},{"type":"verse","number":"80","sanskrit":"लवलीफलमश्मार्शःकफपित्तहरं गुरु विशदं रोचनं रूक्षं स्वाद्वम्लं तुवरं रसे ७.","text":"lavalīphalamaśmārśaḥkaphapittaharaṃ guru viśadaṃ rocanaṃ rūkṣaṃ svādvamlaṃ tuvaraṃ rase 7."},{"type":"verse","number":"81","sanskrit":"करमर्दः सुषेणः स्यात्कृष्णपाकफलस्तथा तस्माल्लघुफला या तु सा ज्ञेया करमर्दिका","text":"karamardaḥ suṣeṇaḥ syātkṛṣṇapākaphalastathā tasmāllaghuphalā yā tu sā jñeyā karamardikā"},{"type":"verse","number":"82","sanskrit":"करमर्दद्वयं त्वाममम्लं गुरु तृषाहरम् उष्णं रुचिकरं प्रोक्तं रक्तपित्तकफप्रदम् तत्पक्वं मधुरं रुच्यं लघु पित्तसमीरजित्","text":"karamardadvayaṃ tvāmamamlaṃ guru tṛṣāharam uṣṇaṃ rucikaraṃ proktaṃ raktapittakaphapradam tatpakvaṃ madhuraṃ rucyaṃ laghu pittasamīrajit"},{"type":"verse","number":"83","sanskrit":"प्रियालस्तु खरस्कन्धश्चारो बहुलवल्कलः राजादनस्तापसेष्टः सन्नकद्रुर्धनुष्पटः","text":"priyālastu kharaskandhaścāro bahulavalkalaḥ rājādanastāpaseṣṭaḥ sannakadrurdhanuṣpaṭaḥ"},{"type":"verse","number":"84","sanskrit":"चारः पित्तकफास्रघ्नस्तत्फलं मधुरं गुरु स्निग्धं सरं मरुत्पित्तदाहज्वरतृषाऽपहम्","text":"cāraḥ pittakaphāsraghnastatphalaṃ madhuraṃ guru snigdhaṃ saraṃ marutpittadāhajvaratṛṣā'paham"},{"type":"verse","number":"85","sanskrit":"प्रियालमज्जा मधुरो वृष्यः पित्तानिलापहः हृद्योऽतिदुर्जरः स्निग्धो विष्टम्भी चामवर्द्धनः","text":"priyālamajjā madhuro vṛṣyaḥ pittānilāpahaḥ hṛdyo'tidurjaraḥ snigdho viṣṭambhī cāmavarddhanaḥ"},{"type":"verse","number":"86","sanskrit":"राजादनः फलाध्यक्षो राजन्या क्षीरिकाऽपि च","text":"rājādanaḥ phalādhyakṣo rājanyā kṣīrikā'pi ca"},{"type":"verse","number":"87","sanskrit":"क्षीरिकायाः फलं वृष्यं बल्यं स्निग्धं हिमं गुरु तृष्णामूर्च्छामदभ्रान्तिक्षयदोषत्रयास्रजित्","text":"kṣīrikāyāḥ phalaṃ vṛṣyaṃ balyaṃ snigdhaṃ himaṃ guru tṛṣṇāmūrcchāmadabhrāntikṣayadoṣatrayāsrajit"},{"type":"verse","number":"88","sanskrit":"विकङ्कतः स्रुवावृक्षो ग्रन्थिलः स्वादुकण्टकः स एव यक्षवृक्षश्च कण्टकी व्याघ्रपादपि विकङ्कतफलं पक्वं मधुरं सर्वदोषजित्","text":"vikaṅkataḥ sruvāvṛkṣo granthilaḥ svādukaṇṭakaḥ sa eva yakṣavṛkṣaśca kaṇṭakī vyāghrapādapi vikaṅkataphalaṃ pakvaṃ madhuraṃ sarvadoṣajit"},{"type":"verse","number":"89","sanskrit":"पद्मबीजं तु पद्माक्षं गालोड्यं पद्मकर्कटी पद्मबीजं हिमं स्वादु कषायं तिक्तकं गुरु","text":"padmabījaṃ tu padmākṣaṃ gāloḍyaṃ padmakarkaṭī padmabījaṃ himaṃ svādu kaṣāyaṃ tiktakaṃ guru"},{"type":"verse","number":"90","sanskrit":"विष्टम्भि वृष्यं रूक्षञ्च गर्भसंस्थापकं परम् कफवातकरं बल्यं ग्राहि पित्तास्रदाहनुत् ७.","text":"viṣṭambhi vṛṣyaṃ rūkṣañca garbhasaṃsthāpakaṃ param kaphavātakaraṃ balyaṃ grāhi pittāsradāhanut 7."},{"type":"verse","number":"91","sanskrit":"मखान्नं पद्मबीजाभं पानीयफलमित्यपि मखान्नं पद्मबीजस्य गुणैस्तुल्यं विनिर्दिशेत्","text":"makhānnaṃ padmabījābhaṃ pānīyaphalamityapi makhānnaṃ padmabījasya guṇaistulyaṃ vinirdiśet"},{"type":"verse","number":"92","sanskrit":"शृङ्गाटकं जलफलं त्रिकोणफलमित्यपि","text":"śṛṅgāṭakaṃ jalaphalaṃ trikoṇaphalamityapi"},{"type":"verse","number":"93","sanskrit":"शृङ्गाटकं हिमं स्वादु गुरु वृष्यं कषायकम् ग्राही शुक्रानिलश्लेष्मप्रदं पित्तास्रदाहनुत्","text":"śṛṅgāṭakaṃ himaṃ svādu guru vṛṣyaṃ kaṣāyakam grāhī śukrānilaśleṣmapradaṃ pittāsradāhanut"},{"type":"verse","number":"94","sanskrit":"उक्तं कुमुदबीजन्तु बुधैः कैरविणीफलम् भवेत्कुमुद्वतीबीजं स्वादु रूक्षं हिमं गुरु","text":"uktaṃ kumudabījantu budhaiḥ kairaviṇīphalam bhavetkumudvatībījaṃ svādu rūkṣaṃ himaṃ guru"},{"type":"verse","number":"95","sanskrit":"मधूको गुडपुष्पः स्यान्मधुपुष्पो मधुस्रवः वानप्रस्थो मधुष्ठीलो जलजेऽत्र मधूलकः","text":"madhūko guḍapuṣpaḥ syānmadhupuṣpo madhusravaḥ vānaprastho madhuṣṭhīlo jalaje'tra madhūlakaḥ"},{"type":"verse","number":"96","sanskrit":"मधूकपुष्पं मधुरं शीतलं गुरु बृंहणम् बलशुक्रकरं प्रोक्तं वातपित्तविनाशनम्","text":"madhūkapuṣpaṃ madhuraṃ śītalaṃ guru bṛṃhaṇam balaśukrakaraṃ proktaṃ vātapittavināśanam"},{"type":"verse","number":"97","sanskrit":"फलं शीतं गुरु स्वादु शुक्रलं वातपित्तनुत् अहृद्यं हन्ति तृष्णाऽस्रदाहश्वासक्षतक्षयान्","text":"phalaṃ śītaṃ guru svādu śukralaṃ vātapittanut ahṛdyaṃ hanti tṛṣṇā'sradāhaśvāsakṣatakṣayān"},{"type":"verse","number":"98","sanskrit":"परूषकं तु परुषमल्पास्थि च परापरम् परूषकं कषायाम्लमामं पित्तकरं लघु","text":"parūṣakaṃ tu paruṣamalpāsthi ca parāparam parūṣakaṃ kaṣāyāmlamāmaṃ pittakaraṃ laghu"},{"type":"verse","number":"99","sanskrit":"तत्पक्वं मधुरं पाके शीतं विष्टम्भि बृंहणम् हृद्यन्तु पित्तदाहास्रज्वरक्षयसमीरहृत्","text":"tatpakvaṃ madhuraṃ pāke śītaṃ viṣṭambhi bṛṃhaṇam hṛdyantu pittadāhāsrajvarakṣayasamīrahṛt"},{"type":"verse","number":"100","sanskrit":"तूतस्तूलश्च पूगश्च क्रमुको ब्रह्मदारु च तूतं पक्वं गुरु स्वादु हिमं पित्तानिलापहम् तदेवामं गुरु सरमम्लोष्णं रक्तपित्तकृत् ७.","text":"tūtastūlaśca pūgaśca kramuko brahmadāru ca tūtaṃ pakvaṃ guru svādu himaṃ pittānilāpaham tadevāmaṃ guru saramamloṣṇaṃ raktapittakṛt 7."},{"type":"verse","number":"101","sanskrit":"दाडिमः करको दन्तबीजो लोहितपुष्पकः तत्फलं त्रिविधं स्वादु स्वाद्वम्लं केवलाम्लकम्","text":"dāḍimaḥ karako dantabījo lohitapuṣpakaḥ tatphalaṃ trividhaṃ svādu svādvamlaṃ kevalāmlakam"},{"type":"verse","number":"102","sanskrit":"तत्तु स्वादु त्रिदोषघ्नं तृड्दाहज्वरनाशनम् हृत्कण्ठमुखगन्धघ्नं तर्पणं शुक्रलं लघु","text":"tattu svādu tridoṣaghnaṃ tṛḍdāhajvaranāśanam hṛtkaṇṭhamukhagandhaghnaṃ tarpaṇaṃ śukralaṃ laghu"},{"type":"verse","number":"103","sanskrit":"कषायानुरसं ग्राहि स्निग्धं मेधाबलावहम्","text":"kaṣāyānurasaṃ grāhi snigdhaṃ medhābalāvaham"},{"type":"verse","number":"104","sanskrit":"स्वाद्वम्लं दीपनं रुच्यं किञ्चित्पित्तकरं लघु अम्लन्तु पित्तजनकमामं वातकफापहम्","text":"svādvamlaṃ dīpanaṃ rucyaṃ kiñcitpittakaraṃ laghu amlantu pittajanakamāmaṃ vātakaphāpaham"},{"type":"verse","number":"105","sanskrit":"अथ बहुवारः इ!लिसोडांइ! तस्य नामानि बहुवारस्तु शीतः स्यादुद्दालो बहुवारकः शेलुः श्लेष्मातकश्चापि पिच्छिलो भूतवृक्षकः","text":"atha bahuvāraḥ i!lisoḍāṃi! tasya nāmāni bahuvārastu śītaḥ syāduddālo bahuvārakaḥ śeluḥ śleṣmātakaścāpi picchilo bhūtavṛkṣakaḥ"},{"type":"verse","number":"106","sanskrit":"बहुवारो विषस्फोटव्रणवीसर्पकुष्ठनुत् मधुरस्तुवरस्तिक्तः केश्यश्च कफपित्तहृत्","text":"bahuvāro viṣasphoṭavraṇavīsarpakuṣṭhanut madhurastuvarastiktaḥ keśyaśca kaphapittahṛt"},{"type":"verse","number":"107","sanskrit":"फलमामन्तु विष्टम्भि रूक्षं पित्तकफास्रजित् तत्पक्वं मधुरं स्निग्धं श्लेष्मलं शीतलं गुरु","text":"phalamāmantu viṣṭambhi rūkṣaṃ pittakaphāsrajit tatpakvaṃ madhuraṃ snigdhaṃ śleṣmalaṃ śītalaṃ guru"},{"type":"verse","number":"108","sanskrit":"पयः प्रसादी कतकः कतकं तत्फलं च तत् कतकस्य फलं नेत्र्! यं जलनिर्मलताकरम् वातश्लेष्महरं शीतं मधुरं तुवरं गुरु","text":"payaḥ prasādī katakaḥ katakaṃ tatphalaṃ ca tat katakasya phalaṃ netr! yaṃ jalanirmalatākaram vātaśleṣmaharaṃ śītaṃ madhuraṃ tuvaraṃ guru"},{"type":"verse","number":"109","sanskrit":"द्रा क्षास्वादुफला प्रोक्ता तथा मधुरसाऽपि च मृद्वीका हारहूरा च गोस्तनी चापि कीर्त्तिता","text":"drā kṣāsvāduphalā proktā tathā madhurasā'pi ca mṛdvīkā hārahūrā ca gostanī cāpi kīrttitā"},{"type":"verse","number":"110","sanskrit":"द्रा क्षा पक्वा सरा शीता चक्षुष्या बृंहणी गुरुः स्वादुपाकरसा स्वर्या तुवरा सृष्टमूत्रविट् ७.","text":"drā kṣā pakvā sarā śītā cakṣuṣyā bṛṃhaṇī guruḥ svādupākarasā svaryā tuvarā sṛṣṭamūtraviṭ 7."},{"type":"verse","number":"111","sanskrit":"कोष्ठमारुतकृद् वृष्या कफपुष्टिरुचिप्रदा","text":"koṣṭhamārutakṛd vṛṣyā kaphapuṣṭirucipradā"},{"type":"verse","number":"112","sanskrit":"हन्ति तृष्णाज्चरश्वासवातवातास्रकामलाः कृच्छ्रास्रपित्तसंमोहदाहशोषमदात्ययान्","text":"hanti tṛṣṇājcaraśvāsavātavātāsrakāmalāḥ kṛcchrāsrapittasaṃmohadāhaśoṣamadātyayān"},{"type":"verse","number":"113","sanskrit":"आमा स्वल्पगुणा गुर्वी सैवाम्ला रक्तपित्तकृत् वृष्या स्याद् गोस्तनी द्रा क्षा गुर्वी च कफपित्तनुत्","text":"āmā svalpaguṇā gurvī saivāmlā raktapittakṛt vṛṣyā syād gostanī drā kṣā gurvī ca kaphapittanut"},{"type":"verse","number":"114","sanskrit":"अबीजाऽन्या स्वल्पतरा गोस्तनीसदृशी गुणैः द्रा क्षा पर्वतजा लघ्वी साऽम्ला श्लेष्माम्लपित्तकृत् द्रा क्षा पर्वतजा यादृक् तादृशी करमर्दिका","text":"abījā'nyā svalpatarā gostanīsadṛśī guṇaiḥ drā kṣā parvatajā laghvī sā'mlā śleṣmāmlapittakṛt drā kṣā parvatajā yādṛk tādṛśī karamardikā"},{"type":"verse","number":"115","sanskrit":"भूमिखर्जूरीका स्वाद्वी दुरारोहाः मृदुच्छदा तथा स्कन्धफला काककर्कटी स्वादुमस्तका","text":"bhūmikharjūrīkā svādvī durārohāḥ mṛducchadā tathā skandhaphalā kākakarkaṭī svādumastakā"},{"type":"verse","number":"116","sanskrit":"पिण्डखर्जूरिका त्वन्या सा देशे पश्चिमे भवेत् खर्जुरी गोस्तनाकारा परद्वीपादिहागता","text":"piṇḍakharjūrikā tvanyā sā deśe paścime bhavet kharjurī gostanākārā paradvīpādihāgatā"},{"type":"verse","number":"117","sanskrit":"जायते पश्चिमे देशे सा छोहारेति कीत्तर्यते खर्जूरीत्रितयं शीतं मधुरं रसपाकयोः","text":"jāyate paścime deśe sā chohāreti kīttaryate kharjūrītritayaṃ śītaṃ madhuraṃ rasapākayoḥ"},{"type":"verse","number":"118","sanskrit":"स्निग्धं रुचिकरं हृद्यं क्षतक्षयहरं गुरु तर्पणं रक्तपित्तघ्नं पुष्टिविष्टम्भशुक्रदम्","text":"snigdhaṃ rucikaraṃ hṛdyaṃ kṣatakṣayaharaṃ guru tarpaṇaṃ raktapittaghnaṃ puṣṭiviṣṭambhaśukradam"},{"type":"verse","number":"119","sanskrit":"कोष्ठमारुतहृद् बल्यं वान्तिवातकफापहम् ज्वरातिसारक्षुत्तृष्णाकासश्वासनिवारकम्","text":"koṣṭhamārutahṛd balyaṃ vāntivātakaphāpaham jvarātisārakṣuttṛṣṇākāsaśvāsanivārakam"},{"type":"verse","number":"120","sanskrit":"महतीभ्यां गुणैरल्पास्वल्पखर्जूरिका स्मृता ७.","text":"mahatībhyāṃ guṇairalpāsvalpakharjūrikā smṛtā 7."},{"type":"verse","number":"121","sanskrit":"खर्जूरीतरुतोयं तु मदपित्तकरं भवेत् वातश्लेष्महरं रुच्यं दीपनं बलशुक्रकृत्","text":"kharjūrītarutoyaṃ tu madapittakaraṃ bhavet vātaśleṣmaharaṃ rucyaṃ dīpanaṃ balaśukrakṛt"},{"type":"verse","number":"122","sanskrit":"सुलेमानी तु मृदुला दलहीनफला च सा सुलेमानी श्रमभ्रान्तिदाहमूर्च्छाऽस्रपित्तहृत्","text":"sulemānī tu mṛdulā dalahīnaphalā ca sā sulemānī śramabhrāntidāhamūrcchā'srapittahṛt"},{"type":"verse","number":"123","sanskrit":"वातादौ वातवैरी स्यान्नेत्रोपमफलस्तथा वातादः उष्णः सुस्निग्धो वातघ्नः शुक्रकृद् गुरुः","text":"vātādau vātavairī syānnetropamaphalastathā vātādaḥ uṣṇaḥ susnigdho vātaghnaḥ śukrakṛd guruḥ"},{"type":"verse","number":"124","sanskrit":"वातादमज्जा मधुरो वृष्यः पित्तानिलापहः स्निग्धोष्णः कफकृन्नेष्टो रक्तपित्तविकारिणाम्","text":"vātādamajjā madhuro vṛṣyaḥ pittānilāpahaḥ snigdhoṣṇaḥ kaphakṛnneṣṭo raktapittavikāriṇām"},{"type":"verse","number":"125","sanskrit":"मुष्टिप्रमाणं बदरं सेवं सिवितिकाफलम्","text":"muṣṭipramāṇaṃ badaraṃ sevaṃ sivitikāphalam"},{"type":"verse","number":"126","sanskrit":"सेवं समीरपित्तघ्नं बृंहणं कफकृद् गुरु रसे पाके च मधुरं शिशिरं रुचिशुक्रकृत्","text":"sevaṃ samīrapittaghnaṃ bṛṃhaṇaṃ kaphakṛd guru rase pāke ca madhuraṃ śiśiraṃ ruciśukrakṛt"},{"type":"verse","number":"127","sanskrit":"अमृतफलं लघु वृष्यं सुस्वादु त्रीन्हरेद्दोषान् देशेषु मुद्गलानां-बहुलं तल्लभ्यते लोकैः","text":"amṛtaphalaṃ laghu vṛṣyaṃ susvādu trīnhareddoṣān deśeṣu mudgalānāṃ-bahulaṃ tallabhyate lokaiḥ"},{"type":"verse","number":"128","sanskrit":"पीलुर्गुडफलः स्रंसी तथा शीतफलोऽपि च पीलु श्लेष्मसमीरघ्नं पित्तलं भेदि गुल्मनुत् स्वादु तिक्तञ्च यत्पीलु तन्नात्युष्णं त्रिदोषहृत्","text":"pīlurguḍaphalaḥ sraṃsī tathā śītaphalo'pi ca pīlu śleṣmasamīraghnaṃ pittalaṃ bhedi gulmanut svādu tiktañca yatpīlu tannātyuṣṇaṃ tridoṣahṛt"},{"type":"verse","number":"129","sanskrit":"पीलुः शैलभवोऽक्षोटः कर्परालश्च कीर्तितः अक्षोटकोपि वातादसदृशः कफपित्तकृत्","text":"pīluḥ śailabhavo'kṣoṭaḥ karparālaśca kīrtitaḥ akṣoṭakopi vātādasadṛśaḥ kaphapittakṛt"},{"type":"verse","number":"130","sanskrit":"बीजपूरो मातुलुङ्गो रुचकः फलपूरकः बीजपूरफलं स्वादु रसेऽम्ल दीपनं लघु ७.","text":"bījapūro mātuluṅgo rucakaḥ phalapūrakaḥ bījapūraphalaṃ svādu rase'mla dīpanaṃ laghu 7."},{"type":"verse","number":"131","sanskrit":"रक्तपित्तहरं कण्ठजिह्वाहृदयशोधनम् श्वासकासारुचिहरं हृद्यं तृष्णाहरं स्मृतम्","text":"raktapittaharaṃ kaṇṭhajihvāhṛdayaśodhanam śvāsakāsāruciharaṃ hṛdyaṃ tṛṣṇāharaṃ smṛtam"},{"type":"verse","number":"132","sanskrit":"बीजपूरोऽपरः प्रोक्तो मधुरो मधुकर्कटी","text":"bījapūro'paraḥ prokto madhuro madhukarkaṭī"},{"type":"verse","number":"133","sanskrit":"मधुकर्कटिका स्वाद्वी रोचनी शीतला गुरुः रक्तपित्तक्षयश्वासकासहिक्काभ्रमापहा","text":"madhukarkaṭikā svādvī rocanī śītalā guruḥ raktapittakṣayaśvāsakāsahikkābhramāpahā"},{"type":"verse","number":"134","sanskrit":"स्याज्जम्बीरो दन्तशठो जम्भजम्भीरजम्भलाः जम्बीरमुष्णं गुर्वम्लं वातश्लेष्मविबन्धनुत्","text":"syājjambīro dantaśaṭho jambhajambhīrajambhalāḥ jambīramuṣṇaṃ gurvamlaṃ vātaśleṣmavibandhanut"},{"type":"verse","number":"135","sanskrit":"आस्यवैरस्यहृत्पीडावह्निमान्द्यक्रिमीन् हरेत् स्वल्पजम्बीरिका तद्वत्तृष्णाच्छर्दिनिवारिणी","text":"āsyavairasyahṛtpīḍāvahnimāndyakrimīn haret svalpajambīrikā tadvattṛṣṇācchardinivāriṇī"},{"type":"verse","number":"136","sanskrit":"निम्बूः स्त्री निम्बुकं क्लीबे निम्बूकमपि कीर्त्तितम् निम्बूकमम्लं वातघ्नं दीपनं पाचनं लघु","text":"nimbūḥ strī nimbukaṃ klībe nimbūkamapi kīrttitam nimbūkamamlaṃ vātaghnaṃ dīpanaṃ pācanaṃ laghu"},{"type":"verse","number":"137","sanskrit":"निम्बुकं कृमिसमूहनाशनं तीक्ष्णमम्लमुदरग्रहापहम् वातपित्तकफशूलिने हितं कष्टनष्टरुचिरोचनं परम्","text":"nimbukaṃ kṛmisamūhanāśanaṃ tīkṣṇamamlamudaragrahāpaham vātapittakaphaśūline hitaṃ kaṣṭanaṣṭarucirocanaṃ param"},{"type":"verse","number":"138","sanskrit":"त्रिदोषवह्निक्षयवातरोगनिपीडितानां विषविह्वलानाम् मन्दानले बद्धगुदे प्रदेयं विषूचिकायां मुनयो वदन्ति","text":"tridoṣavahnikṣayavātaroganipīḍitānāṃ viṣavihvalānām mandānale baddhagude pradeyaṃ viṣūcikāyāṃ munayo vadanti"},{"type":"verse","number":"139","sanskrit":"मिष्टनिम्बूफलं स्वादु गुरु मारुतपित्तनुत्","text":"miṣṭanimbūphalaṃ svādu guru mārutapittanut"},{"type":"verse","number":"140","sanskrit":"गलरोगविषध्वंसिकफोत्क्लेशि च रक्तहृत् शोषारुचितृषाच्छर्दिहरं बल्यञ्च बृंहणम् ७.","text":"galarogaviṣadhvaṃsikaphotkleśi ca raktahṛt śoṣārucitṛṣācchardiharaṃ balyañca bṛṃhaṇam 7."},{"type":"verse","number":"141","sanskrit":"कर्मरङ्गं शिरालं च बृहदम्लं रुजाकरम् कर्मरङ्गं हिमं ग्राहि स्वाद्वम्लं कफवातहृत्","text":"karmaraṅgaṃ śirālaṃ ca bṛhadamlaṃ rujākaram karmaraṅgaṃ himaṃ grāhi svādvamlaṃ kaphavātahṛt"},{"type":"verse","number":"142","sanskrit":"अम्लिका चुक्रिकाऽम्ली च चुका दन्तशठाऽपि च अम्ला च चिञ्चिका चिञ्चा तिन्तिडीका च तिन्तिडी","text":"amlikā cukrikā'mlī ca cukā dantaśaṭhā'pi ca amlā ca ciñcikā ciñcā tintiḍīkā ca tintiḍī"},{"type":"verse","number":"143","sanskrit":"अम्लिकाऽम्ला गुरुर्वातहरी पित्तकफास्रकृत् पक्वा तु दीपनी रूक्षा सरोष्णा कफवातनुत्","text":"amlikā'mlā gururvātaharī pittakaphāsrakṛt pakvā tu dīpanī rūkṣā saroṣṇā kaphavātanut"},{"type":"verse","number":"144","sanskrit":"स्यादम्लवेतसश्चुक्रं शतवेधि सहस्रनुत् अम्लवेतसमत्यम्लं भेदनं लघु दीपनम्","text":"syādamlavetasaścukraṃ śatavedhi sahasranut amlavetasamatyamlaṃ bhedanaṃ laghu dīpanam"},{"type":"verse","number":"145","sanskrit":"हृद्रो गशूलगुल्मघ्नं पित्तलं लोमहर्षणम् रूक्षं विण्मूत्रदोषघ्नं प्लीहोदावर्त्तनाशनम्","text":"hṛdro gaśūlagulmaghnaṃ pittalaṃ lomaharṣaṇam rūkṣaṃ viṇmūtradoṣaghnaṃ plīhodāvarttanāśanam"},{"type":"verse","number":"146","sanskrit":"कफवातामयध्वंसिच्छागमांसद्र वत्वकृत् चणकाम्लगुणं ज्ञेयं लोहसूचीद्र वत्वकृत्","text":"kaphavātāmayadhvaṃsicchāgamāṃsadra vatvakṛt caṇakāmlaguṇaṃ jñeyaṃ lohasūcīdra vatvakṛt"},{"type":"verse","number":"147","sanskrit":"वृक्षाम्लं तिन्तिडीकञ्चचुक्रं स्यादम्लवृक्षकम् वृक्षाम्लमाममम्लोष्णं वातघ्नं कफपित्तलम्","text":"vṛkṣāmlaṃ tintiḍīkañcacukraṃ syādamlavṛkṣakam vṛkṣāmlamāmamamloṣṇaṃ vātaghnaṃ kaphapittalam"},{"type":"verse","number":"148","sanskrit":"पक्वन्तु गुरु संग्राहि कटुकं तुवरं लघु","text":"pakvantu guru saṃgrāhi kaṭukaṃ tuvaraṃ laghu"},{"type":"verse","number":"149","sanskrit":"अम्लोष्णं रोचनं रूक्षं दीपनं कफवातकृत् तृष्णाऽशोग्रहणीगुल्मशूलहृद्रो गजन्तुजित्","text":"amloṣṇaṃ rocanaṃ rūkṣaṃ dīpanaṃ kaphavātakṛt tṛṣṇā'śograhaṇīgulmaśūlahṛdro gajantujit"},{"type":"verse","number":"150","sanskrit":"चतुरम्लं हि पञ्चाम्लं बीजपूरयुतैर्भवेत् ७.","text":"caturamlaṃ hi pañcāmlaṃ bījapūrayutairbhavet 7."},{"type":"verse","number":"151","sanskrit":"फलेषु परिपक्वं यद् गुणवत्तदुदाहृतम् बिल्वादन्यत्र विज्ञेयमामं तद्धि गुणाधिकम् फलेषु सरसं यत्स्याद् गुणवत्तदुदाहृतम्","text":"phaleṣu paripakvaṃ yad guṇavattadudāhṛtam bilvādanyatra vijñeyamāmaṃ taddhi guṇādhikam phaleṣu sarasaṃ yatsyād guṇavattadudāhṛtam"},{"type":"verse","number":"152","sanskrit":"द्रा क्षाबिल्वशिवाऽदीनां फलं शुष्कं गुणाधिकम् फलतुल्यगुणं सर्वं मज्जानमपि निर्दिशेत्","text":"drā kṣābilvaśivā'dīnāṃ phalaṃ śuṣkaṃ guṇādhikam phalatulyaguṇaṃ sarvaṃ majjānamapi nirdiśet"},{"type":"verse","number":"153","sanskrit":"फलं हिमाग्निदुर्वातव्यालकीटादिदूषितम् अकालजं कुभूमीजं पाकातीतं न भक्षयेत्","text":"phalaṃ himāgnidurvātavyālakīṭādidūṣitam akālajaṃ kubhūmījaṃ pākātītaṃ na bhakṣayet"},{"type":"verse","number":"7","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे सप्तम आम्रादिफलवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe saptama āmrādiphalavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":7,"lang":"sa","content":[{"type":"heading","heading":"dhātūpadhāturasoparasaratnoparatnaviṣopaviṣa-варга — металлы, минералы, яды"},{"type":"verse","number":"1","sanskrit":"अथाष्टमो धात्वादिवर्गोपरनामको धातूपधातुरसोपरसरत्नोपरत्नविषोपविषवर्गः स्वर्णं रूप्यञ्च ताम्रं च रङ्गं यशदमेव च सीसं लौहञ्च सप्तैते धातवो गिरिसम्भवः","text":"athāṣṭamo dhātvādivargoparanāmako dhātūpadhāturasoparasaratnoparatnaviṣopaviṣavargaḥ svarṇaṃ rūpyañca tāmraṃ ca raṅgaṃ yaśadameva ca sīsaṃ lauhañca saptaite dhātavo girisambhavaḥ"},{"type":"verse","number":"2","sanskrit":"वली पलित खालित्य कार्श्याबल्य जरामयान् निवार्य देहं दधति नृणां तद्धातवो मताः","text":"valī palita khālitya kārśyābalya jarāmayān nivārya dehaṃ dadhati nṛṇāṃ taddhātavo matāḥ"},{"type":"verse","number":"3","sanskrit":"पुरा निजाश्रमस्थानां सप्तर्षीणां जितात्मनाम् पत्नीर्विलोक्य लावण्यलक्ष्मीसम्पन्नयौवनाः","text":"purā nijāśramasthānāṃ saptarṣīṇāṃ jitātmanām patnīrvilokya lāvaṇyalakṣmīsampannayauvanāḥ"},{"type":"verse","number":"4","sanskrit":"कन्दर्पदर्पविध्वस्तचेतसो जातवेदसः पतितं यद्धरापृष्ठे रेतस्तद्धेमतामगात् कृत्रिमञ्चापि भवति तद्र सेन्द्र स्य वेधतः","text":"kandarpadarpavidhvastacetaso jātavedasaḥ patitaṃ yaddharāpṛṣṭhe retastaddhematāmagāt kṛtrimañcāpi bhavati tadra sendra sya vedhataḥ"},{"type":"verse","number":"5","sanskrit":"स्वर्णं सुवर्णं कनकं हिरण्यं हेम हाटकम्","text":"svarṇaṃ suvarṇaṃ kanakaṃ hiraṇyaṃ hema hāṭakam"},{"type":"verse","number":"6","sanskrit":"तपनीयं च गाङ्गेयं कलधौतञ्च काञ्चनम् चामीकरं शातकुम्भं तथा कार्त्तस्वरं च तत्","text":"tapanīyaṃ ca gāṅgeyaṃ kaladhautañca kāñcanam cāmīkaraṃ śātakumbhaṃ tathā kārttasvaraṃ ca tat"},{"type":"verse","number":"7","sanskrit":"जाम्बूनदं जातरूपं महारजतमित्यपि","text":"jāmbūnadaṃ jātarūpaṃ mahārajatamityapi"},{"type":"verse","number":"8","sanskrit":"दाहे रक्तं सितं छेदे निकषे कुङ्कुमप्रभम् तारशुल्वोज्झितं स्निग्धं कोमलं गुरु हेम सत्","text":"dāhe raktaṃ sitaṃ chede nikaṣe kuṅkumaprabham tāraśulvojjhitaṃ snigdhaṃ komalaṃ guru hema sat"},{"type":"verse","number":"9","sanskrit":"तच्छ्वेतं कठिनं रूक्षं विवर्णं समलं दलम् दाहे छेदेऽसितं श्वेतं कषे त्याज्यं लघु स्फुटम्","text":"tacchvetaṃ kaṭhinaṃ rūkṣaṃ vivarṇaṃ samalaṃ dalam dāhe chede'sitaṃ śvetaṃ kaṣe tyājyaṃ laghu sphuṭam"},{"type":"verse","number":"10","sanskrit":"सुवर्णं शीतलं वृष्यं बल्यं गुरु रसायनम् स्वादु तिक्तं च तुवरं पाके च स्वादु पिच्छिलम् ८.","text":"suvarṇaṃ śītalaṃ vṛṣyaṃ balyaṃ guru rasāyanam svādu tiktaṃ ca tuvaraṃ pāke ca svādu picchilam 8."},{"type":"verse","number":"11","sanskrit":"पवित्रं बृंहणं नेत्र्! यं मेधास्मृतिमतिप्रदम् हृद्यमायुष्करं कान्तिवाग्विशुद्धिस्थिरत्वकृत् विषद्वयक्षयोन्मादत्रिदोषज्वरशोषजित्","text":"pavitraṃ bṛṃhaṇaṃ netr! yaṃ medhāsmṛtimatipradam hṛdyamāyuṣkaraṃ kāntivāgviśuddhisthiratvakṛt viṣadvayakṣayonmādatridoṣajvaraśoṣajit"},{"type":"verse","number":"12","sanskrit":"बलं सवीर्यं हरते नराणां रोगव्रजान् पोषयतीह काये असौख्यकृच्चापि सदा सुवर्णमशुद्धमेतन्मरणञ्च कुर्यात्","text":"balaṃ savīryaṃ harate narāṇāṃ rogavrajān poṣayatīha kāye asaukhyakṛccāpi sadā suvarṇamaśuddhametanmaraṇañca kuryāt"},{"type":"verse","number":"13","sanskrit":"असम्यङ्मारितं स्वर्णं बलं वीर्य्यञ्च नाशयेत् करोति रोगान् मृत्युं च तद्धन्याद्यत्नतस्ततः","text":"asamyaṅmāritaṃ svarṇaṃ balaṃ vīryyañca nāśayet karoti rogān mṛtyuṃ ca taddhanyādyatnatastataḥ"},{"type":"verse","number":"14","sanskrit":"त्रिपुरस्य वधार्थाय निर्निमेषैर्विलोचनैः निरीक्षयामास शिवः क्रोधेन परिपूरितः","text":"tripurasya vadhārthāya nirnimeṣairvilocanaiḥ nirīkṣayāmāsa śivaḥ krodhena paripūritaḥ"},{"type":"verse","number":"15","sanskrit":"ततो रुद्र ः! समभवद् वैश्वानर इव ज्वलन्","text":"tato rudra ḥ! samabhavad vaiśvānara iva jvalan"},{"type":"verse","number":"16","sanskrit":"द्वितीयादपतन्नेत्रादश्रुबिन्दुस्तु वामकात् तस्माद्र जतमुत्पन्नमुक्तकर्मसु योजयेत्","text":"dvitīyādapatannetrādaśrubindustu vāmakāt tasmādra jatamutpannamuktakarmasu yojayet"},{"type":"verse","number":"17","sanskrit":"कृत्रिमं च भवेत्तद्धि वङ्गादिरसयोगतः","text":"kṛtrimaṃ ca bhavettaddhi vaṅgādirasayogataḥ"},{"type":"verse","number":"18","sanskrit":"रूप्यं तु रजतं तारं चन्द्र कान्ति सितप्रभम्","text":"rūpyaṃ tu rajataṃ tāraṃ candra kānti sitaprabham"},{"type":"verse","number":"19","sanskrit":"गुरु स्निग्धं मृदु श्वेतं दाहे छेदे घनक्षमम् वर्णाढ्यं चन्द्र वत्स्वच्छं रूप्यं नवगुणं शुभम् कठिनं कृत्रिमं रूक्षं रक्तं पीतदलं लघु दाहच्छेदघनैर्नष्टं रूप्यं दुष्टं प्रकीर्त्तितम्","text":"guru snigdhaṃ mṛdu śvetaṃ dāhe chede ghanakṣamam varṇāḍhyaṃ candra vatsvacchaṃ rūpyaṃ navaguṇaṃ śubham kaṭhinaṃ kṛtrimaṃ rūkṣaṃ raktaṃ pītadalaṃ laghu dāhacchedaghanairnaṣṭaṃ rūpyaṃ duṣṭaṃ prakīrttitam"},{"type":"verse","number":"20","sanskrit":"रूप्यं शीतं कषायाम्लं स्वादुपाकरसं सरम् वयसः स्थापनं स्निग्धं लेखनं वातपित्तजित् प्रमेहादिकरोगांश्च नाशयत्यचिराद् ध्रुवम् ८.","text":"rūpyaṃ śītaṃ kaṣāyāmlaṃ svādupākarasaṃ saram vayasaḥ sthāpanaṃ snigdhaṃ lekhanaṃ vātapittajit pramehādikarogāṃśca nāśayatyacirād dhruvam 8."},{"type":"verse","number":"21","sanskrit":"तारं शरीरस्य करोति तापं विध्वंसनं यच्छति शुक्रनाशम् वीर्यं बलं हन्ति तनोश्च पुष्टिं महागदान्पोषयति ह्यशुद्धम्","text":"tāraṃ śarīrasya karoti tāpaṃ vidhvaṃsanaṃ yacchati śukranāśam vīryaṃ balaṃ hanti tanośca puṣṭiṃ mahāgadānpoṣayati hyaśuddham"},{"type":"verse","number":"22","sanskrit":"शुक्रं यत् कार्त्तिकेयस्य पतितं धरणीतले तस्मात्ताम्रं समुत्पन्नमिदमाहुः पुराविदः","text":"śukraṃ yat kārttikeyasya patitaṃ dharaṇītale tasmāttāmraṃ samutpannamidamāhuḥ purāvidaḥ"},{"type":"verse","number":"23","sanskrit":"ताम्रमौदुम्बरं शुल्वमुदुम्बरमपि स्मृतम् रविप्रियं म्लेच्छमुखं सूर्यपर्यायनामकम्","text":"tāmramaudumbaraṃ śulvamudumbaramapi smṛtam ravipriyaṃ mlecchamukhaṃ sūryaparyāyanāmakam"},{"type":"verse","number":"24","sanskrit":"जपाकुसुमसङ्काशं स्निग्धं मृदु घनक्षमम् लौहनागोज्झितं ताम्रं मारणाय प्रशस्यते","text":"japākusumasaṅkāśaṃ snigdhaṃ mṛdu ghanakṣamam lauhanāgojjhitaṃ tāmraṃ māraṇāya praśasyate"},{"type":"verse","number":"25","sanskrit":"कृष्णं रूक्षमतिस्तब्धं श्वेतञ्चापि घनासहम् लौहनागयुतञ्चेति शुल्बं दुष्टं प्रकीर्त्तितम्","text":"kṛṣṇaṃ rūkṣamatistabdhaṃ śvetañcāpi ghanāsaham lauhanāgayutañceti śulbaṃ duṣṭaṃ prakīrttitam"},{"type":"verse","number":"26","sanskrit":"ताम्रं कषायं मधुरं च तिक्तमम्लं च पाके कटु सारकं च पित्तापहं श्लेष्महरं च शीतं तद्रो पणं स्याल्लघु लेखनञ्च","text":"tāmraṃ kaṣāyaṃ madhuraṃ ca tiktamamlaṃ ca pāke kaṭu sārakaṃ ca pittāpahaṃ śleṣmaharaṃ ca śītaṃ tadro paṇaṃ syāllaghu lekhanañca"},{"type":"verse","number":"27","sanskrit":"पाण्डूदरार्शोज्व्रकुष्ठकासश्वासक्षयान् पीनसमम्लपित्तम् शोथं कृमिं शूलमपाकरोति प्राहुः परे बृंहणमल्पमेतत्","text":"pāṇḍūdarārśojvrakuṣṭhakāsaśvāsakṣayān pīnasamamlapittam śothaṃ kṛmiṃ śūlamapākaroti prāhuḥ pare bṛṃhaṇamalpametat"},{"type":"verse","number":"28","sanskrit":"एको दोषो विषे ताम्रेत्वसम्यङ्मारितेऽष्टते दाहः स्वेदोऽरुचिर्मूर्च्छाक्लेदो रेको वमिर्भ्रमः","text":"eko doṣo viṣe tāmretvasamyaṅmārite'ṣṭate dāhaḥ svedo'rucirmūrcchākledo reko vamirbhramaḥ"},{"type":"verse","number":"29","sanskrit":"रङ्गं वङ्गं त्रपु प्रोक्तं तथा पिच्चटमित्यपि क्षुरकं मिश्रकं चापि द्विविधं वङ्ग मुच्यते","text":"raṅgaṃ vaṅgaṃ trapu proktaṃ tathā piccaṭamityapi kṣurakaṃ miśrakaṃ cāpi dvividhaṃ vaṅga mucyate"},{"type":"verse","number":"30","sanskrit":"उत्तमं क्षुरकं तत्र मिश्रकं त्ववरं मतम् ८.","text":"uttamaṃ kṣurakaṃ tatra miśrakaṃ tvavaraṃ matam 8."},{"type":"verse","number":"31","sanskrit":"रङ्गं लघु सरं रूक्षमुष्णं मेहकफक्रिमीन् निहन्ति पाण्डुं सश्वासं चक्षुष्यं पित्तलं मनाक्","text":"raṅgaṃ laghu saraṃ rūkṣamuṣṇaṃ mehakaphakrimīn nihanti pāṇḍuṃ saśvāsaṃ cakṣuṣyaṃ pittalaṃ manāk"},{"type":"verse","number":"32","sanskrit":"सिंहो यथा हस्तिगणं निहन्ति तथैव वङ्गोऽखिलमेहवर्गम् देहस्य सौख्यं प्रबलेन्द्रि यत्वं नरस्य पुष्टिं विदधाति नूनम्","text":"siṃho yathā hastigaṇaṃ nihanti tathaiva vaṅgo'khilamehavargam dehasya saukhyaṃ prabalendri yatvaṃ narasya puṣṭiṃ vidadhāti nūnam"},{"type":"verse","number":"33","sanskrit":"यशदं रङ्गसदृशं रीतिहेतुश्च तन्मतम् यशदं तुवरं तिक्तं शीतलं कफपित्तहृत् चक्षुष्यं परमं मेहान् पाण्डुं श्वासं च नाशयेत्","text":"yaśadaṃ raṅgasadṛśaṃ rītihetuśca tanmatam yaśadaṃ tuvaraṃ tiktaṃ śītalaṃ kaphapittahṛt cakṣuṣyaṃ paramaṃ mehān pāṇḍuṃ śvāsaṃ ca nāśayet"},{"type":"verse","number":"34","sanskrit":"दृष्ट्वा भोगिसुतां रम्यां वासुकिस्तुमुमोच यत् वीर्यं जातस्ततो नागः सर्वरोगापहा नृणाम्","text":"dṛṣṭvā bhogisutāṃ ramyāṃ vāsukistumumoca yat vīryaṃ jātastato nāgaḥ sarvarogāpahā nṛṇām"},{"type":"verse","number":"35","sanskrit":"सीसं ब्रध्नं च वप्रं च योगेष्टं नागनामकम्","text":"sīsaṃ bradhnaṃ ca vapraṃ ca yogeṣṭaṃ nāganāmakam"},{"type":"verse","number":"36","sanskrit":"सीसं रङ्गगुणं ज्ञेयं विशेषान्मेहनाशनम्","text":"sīsaṃ raṅgaguṇaṃ jñeyaṃ viśeṣānmehanāśanam"},{"type":"verse","number":"37","sanskrit":"नागस्तु नागशततुल्यबलं ददाति व्याधिं विनाशयति जीवनमातनोति बह्निं प्रदीपयति कामबलं करोति मृत्युं च नाशयति सन्ततसेवितः सः","text":"nāgastu nāgaśatatulyabalaṃ dadāti vyādhiṃ vināśayati jīvanamātanoti bahniṃ pradīpayati kāmabalaṃ karoti mṛtyuṃ ca nāśayati santatasevitaḥ saḥ"},{"type":"verse","number":"38","sanskrit":"पाकेन हीनौ किल वङ्गनागौ कुष्ठानि गुल्मांश्च तथाऽतिकष्टान् कण्डूप्रमेहानिलसादशोथभगन्दरादीन् कुरुतः प्रयुक्तौ","text":"pākena hīnau kila vaṅganāgau kuṣṭhāni gulmāṃśca tathā'tikaṣṭān kaṇḍūpramehānilasādaśothabhagandarādīn kurutaḥ prayuktau"},{"type":"verse","number":"39","sanskrit":"पुरा लोमिनदैत्यानां निहतानां सुरैर्युधि उत्पन्नानि शरीरेभ्यो लोहानि विविधानि च लोहोऽस्त्री शस्त्रकं तीक्ष्णं पिण्डं कालायसायसी","text":"purā lominadaityānāṃ nihatānāṃ surairyudhi utpannāni śarīrebhyo lohāni vividhāni ca loho'strī śastrakaṃ tīkṣṇaṃ piṇḍaṃ kālāyasāyasī"},{"type":"verse","number":"40","sanskrit":"गुरुता दृढतोत्क्लेदः कश्मलं दाहकारिता अश्मदोषः सुदुर्गन्धो दोषाः सप्तायसस्य तु ८.","text":"gurutā dṛḍhatotkledaḥ kaśmalaṃ dāhakāritā aśmadoṣaḥ sudurgandho doṣāḥ saptāyasasya tu 8."},{"type":"verse","number":"41","sanskrit":"लोहं तिक्तं सरं शीतं मधुरं तुवरं गुरु रूक्षं वयस्यं चक्षुष्यं लेखनं वातलं जयेत्","text":"lohaṃ tiktaṃ saraṃ śītaṃ madhuraṃ tuvaraṃ guru rūkṣaṃ vayasyaṃ cakṣuṣyaṃ lekhanaṃ vātalaṃ jayet"},{"type":"verse","number":"42","sanskrit":"कफं पित्तं गरं शूलं शोथार्शः प्लीहपाण्डुताः मेदोमेहकृमीन् कुष्ठं तत्किट्टं तद्वदेव हि","text":"kaphaṃ pittaṃ garaṃ śūlaṃ śothārśaḥ plīhapāṇḍutāḥ medomehakṛmīn kuṣṭhaṃ tatkiṭṭaṃ tadvadeva hi"},{"type":"verse","number":"43","sanskrit":"षण्ढत्वकुष्ठामयमृत्युदं भवेद् हृद्रो गशूलौ कुरुतेऽश्मरीञ्च नानारुजानाञ्च तथा प्रकोपं करोति हृल्लासमशुद्धलोहम्","text":"ṣaṇḍhatvakuṣṭhāmayamṛtyudaṃ bhaved hṛdro gaśūlau kurute'śmarīñca nānārujānāñca tathā prakopaṃ karoti hṛllāsamaśuddhaloham"},{"type":"verse","number":"44","sanskrit":"जीवहारि मदकारि चायसं चेदशुद्धिमदसंस्कृतं ध्रुवम् पाटवं न तनुते शरीरके दारुणां हृदि रुजाञ्च यच्छति","text":"jīvahāri madakāri cāyasaṃ cedaśuddhimadasaṃskṛtaṃ dhruvam pāṭavaṃ na tanute śarīrake dāruṇāṃ hṛdi rujāñca yacchati"},{"type":"verse","number":"45","sanskrit":"कूष्माण्डं तिलतैलञ्च माषान्नं राजिकां तथा मद्यम्लरसं चापि त्यजेल्लोहस्य सेवकः","text":"kūṣmāṇḍaṃ tilatailañca māṣānnaṃ rājikāṃ tathā madyamlarasaṃ cāpi tyajellohasya sevakaḥ"},{"type":"verse","number":"46","sanskrit":"क्षमाभृच्छिखराकाराण्यङ्गान्यम्लेन लेपिते लौहे स्युर्यत्र सूक्ष्माणि तत्सारमभिधीयते लौहं साराह्वयं हन्याद् ग्रहणीमतिसारकम्","text":"kṣamābhṛcchikharākārāṇyaṅgānyamlena lepite lauhe syuryatra sūkṣmāṇi tatsāramabhidhīyate lauhaṃ sārāhvayaṃ hanyād grahaṇīmatisārakam"},{"type":"verse","number":"47","sanskrit":"अर्द्धं सर्वाङ्गजं वातं शूलं च परिणामजम् छर्दिं च पीनसं पित्तं श्वासं कासं व्यपोहति","text":"arddhaṃ sarvāṅgajaṃ vātaṃ śūlaṃ ca pariṇāmajam chardiṃ ca pīnasaṃ pittaṃ śvāsaṃ kāsaṃ vyapohati"},{"type":"verse","number":"48","sanskrit":"यत्पात्रे न प्रसरति जले तैलविन्दुः प्रतप्ते हिङ्गुर्गन्धं त्यजति च निजं तिक्ततां निम्बवल्कः तप्तं दुग्धं भवति शिखराकारकंनैति भूमिं कृष्णाङ्गः स्यात् सजलचणकः कान्तलोहंतदुक्तम्","text":"yatpātre na prasarati jale tailavinduḥ pratapte hiṅgurgandhaṃ tyajati ca nijaṃ tiktatāṃ nimbavalkaḥ taptaṃ dugdhaṃ bhavati śikharākārakaṃnaiti bhūmiṃ kṛṣṇāṅgaḥ syāt sajalacaṇakaḥ kāntalohaṃtaduktam"},{"type":"verse","number":"49","sanskrit":"गुल्मोदरार्शःशूलाममामवातं भगन्दरम् कामलाशोथकुष्ठानि क्षयं कान्तमयो हरेत्","text":"gulmodarārśaḥśūlāmamāmavātaṃ bhagandaram kāmalāśothakuṣṭhāni kṣayaṃ kāntamayo haret"},{"type":"verse","number":"50","sanskrit":"प्लीहानमम्लपित्तञ्च यकृच्चापि शिरोरुजम् ८.","text":"plīhānamamlapittañca yakṛccāpi śirorujam 8."},{"type":"verse","number":"51","sanskrit":"सर्वान् रोगान् विजयते कान्तलोहं न संशयः बलं वीर्यं वपुःपुष्टिं कुरुतेऽग्नि विवर्द्धयेत्","text":"sarvān rogān vijayate kāntalohaṃ na saṃśayaḥ balaṃ vīryaṃ vapuḥpuṣṭiṃ kurute'gni vivarddhayet"},{"type":"verse","number":"52","sanskrit":"ध्मायमानस्य लोहस्य मलं मण्डूर मुच्यते लोहसिंहानिका किट्टी सिंहानञ्च निगद्यते यल्लोहं यद्गुणंप्रोक्तं तत्किट्टमपि तद्गुणम्","text":"dhmāyamānasya lohasya malaṃ maṇḍūra mucyate lohasiṃhānikā kiṭṭī siṃhānañca nigadyate yallohaṃ yadguṇaṃproktaṃ tatkiṭṭamapi tadguṇam"},{"type":"verse","number":"53","sanskrit":"सप्तोपधातवः स्वर्णमाक्षिकं तारमाक्षिकं तुत्थं कांस्यं च रीतिश्च सिन्दूरञ्च शिलाजतु","text":"saptopadhātavaḥ svarṇamākṣikaṃ tāramākṣikaṃ tutthaṃ kāṃsyaṃ ca rītiśca sindūrañca śilājatu"},{"type":"verse","number":"54","sanskrit":"उपधातुषु सर्वेषु तत्तद्धातुगुणा अपि सन्ति किन्त्वेषु ते गौणास्तत्तदंशाल्पभावतः","text":"upadhātuṣu sarveṣu tattaddhātuguṇā api santi kintveṣu te gauṇāstattadaṃśālpabhāvataḥ"},{"type":"verse","number":"55","sanskrit":"स्वर्णमाक्षिकमाख्यातं तापीजं मधुमाक्षिकम्","text":"svarṇamākṣikamākhyātaṃ tāpījaṃ madhumākṣikam"},{"type":"verse","number":"56","sanskrit":"ताप्यं माक्षिकधातुश्च मधुधातुश्च स स्मृतः किञ्चित्सुवर्णं साहित्यात्स्वर्णमाक्षिकमीरितम्","text":"tāpyaṃ mākṣikadhātuśca madhudhātuśca sa smṛtaḥ kiñcitsuvarṇaṃ sāhityātsvarṇamākṣikamīritam"},{"type":"verse","number":"57","sanskrit":"उपधातुः सुवर्णस्य किञ्चित्स्वर्णगुणान्वितम् तथा च काञ्चनाभावे दीयते स्वर्णमाक्षिकम्","text":"upadhātuḥ suvarṇasya kiñcitsvarṇaguṇānvitam tathā ca kāñcanābhāve dīyate svarṇamākṣikam"},{"type":"verse","number":"58","sanskrit":"किन्तु तस्यानुकल्पत्वात्किञ्चिदूनगुणास्ततः न केवलं स्वर्णगुणा वर्त्तन्ते स्वर्णमाक्षिके","text":"kintu tasyānukalpatvātkiñcidūnaguṇāstataḥ na kevalaṃ svarṇaguṇā varttante svarṇamākṣike"},{"type":"verse","number":"59","sanskrit":"द्र व्यान्तरस्य संसर्गात्सन्त्यन्येऽपि गुणा यतः सुवर्णमाक्षिकं स्वादु तिक्तं वृष्यं रसायनम्","text":"dra vyāntarasya saṃsargātsantyanye'pi guṇā yataḥ suvarṇamākṣikaṃ svādu tiktaṃ vṛṣyaṃ rasāyanam"},{"type":"verse","number":"60","sanskrit":"चक्षुष्यं बस्तिरुक्कुष्ठपाण्डुमेहविषोदरान् अर्शः शोथं विषं कण्डूं त्रिदोषमपि नाशयेत् ८.","text":"cakṣuṣyaṃ bastirukkuṣṭhapāṇḍumehaviṣodarān arśaḥ śothaṃ viṣaṃ kaṇḍūṃ tridoṣamapi nāśayet 8."},{"type":"verse","number":"61","sanskrit":"मन्दानलत्वं बलहानिमुग्रां विष्टम्भितां नेत्रगदान्सकुष्ठान् तथैव मालां व्रणपूर्विकां च करोति तापीजमशुद्धमेतत्","text":"mandānalatvaṃ balahānimugrāṃ viṣṭambhitāṃ netragadānsakuṣṭhān tathaiva mālāṃ vraṇapūrvikāṃ ca karoti tāpījamaśuddhametat"},{"type":"verse","number":"62","sanskrit":"तारमाक्षिकमन्यत्तु तद्भवेद्र जतोपमम् किञ्चिद्र जतसाहित्यात्तारमाक्षिकमीरितम्","text":"tāramākṣikamanyattu tadbhavedra jatopamam kiñcidra jatasāhityāttāramākṣikamīritam"},{"type":"verse","number":"63","sanskrit":"अनुकल्पतया तस्य ततो हीनगुणाः स्मृताः न केवलं रूप्यगुणा यतः स्यात्तारमाक्षिकम्","text":"anukalpatayā tasya tato hīnaguṇāḥ smṛtāḥ na kevalaṃ rūpyaguṇā yataḥ syāttāramākṣikam"},{"type":"verse","number":"64","sanskrit":"स्वादु पाके रसे किञ्चित्तिक्तं वृष्यं रसायनम् चक्षुष्यं वस्तिरुक्कुष्ठपाण्डुमेहविषोदरान् अर्शः शोथं क्षयङ्कण्डूं त्रिदोषमपि नाशयेत्","text":"svādu pāke rase kiñcittiktaṃ vṛṣyaṃ rasāyanam cakṣuṣyaṃ vastirukkuṣṭhapāṇḍumehaviṣodarān arśaḥ śothaṃ kṣayaṅkaṇḍūṃ tridoṣamapi nāśayet"},{"type":"verse","number":"65","sanskrit":"मन्दानलत्वं बलहानिमुग्रां विष्टग्भितां नेत्रगदान्सकुष्ठान् तथैव मालां व्रणपूर्विकाञ्च करोति तापीजमिदञ्च तद्वत्","text":"mandānalatvaṃ balahānimugrāṃ viṣṭagbhitāṃ netragadānsakuṣṭhān tathaiva mālāṃ vraṇapūrvikāñca karoti tāpījamidañca tadvat"},{"type":"verse","number":"66","sanskrit":"तुत्थं वितुन्नकं चापि शिखिग्रीवं मयूरकम् तुत्थं ताम्रोपधातुर्हि किञ्चित्ताम्रेण तद्भवेत्","text":"tutthaṃ vitunnakaṃ cāpi śikhigrīvaṃ mayūrakam tutthaṃ tāmropadhāturhi kiñcittāmreṇa tadbhavet"},{"type":"verse","number":"67","sanskrit":"किञ्चित्ताम्रगुणं तस्माद्वक्ष्यमाणगुणं च तत् तुत्थकं कटुकं क्षारं कषायं वामकं लघु","text":"kiñcittāmraguṇaṃ tasmādvakṣyamāṇaguṇaṃ ca tat tutthakaṃ kaṭukaṃ kṣāraṃ kaṣāyaṃ vāmakaṃ laghu"},{"type":"verse","number":"68","sanskrit":"लेखनं भेदनं शीतं चक्षुष्यं कफपित्तहृत् विषाश्मकुष्ठकण्डूघ्नं खर्परं चापि तद्गुणम्","text":"lekhanaṃ bhedanaṃ śītaṃ cakṣuṣyaṃ kaphapittahṛt viṣāśmakuṣṭhakaṇḍūghnaṃ kharparaṃ cāpi tadguṇam"},{"type":"verse","number":"69","sanskrit":"ताम्रत्रपुजमाख्यातं कांस्यं घोषं च कंसकम् उपधातुर्भवेत्कांस्यं द्वयोस्तरणिरङ्गयोः","text":"tāmratrapujamākhyātaṃ kāṃsyaṃ ghoṣaṃ ca kaṃsakam upadhāturbhavetkāṃsyaṃ dvayostaraṇiraṅgayoḥ"},{"type":"verse","number":"70","sanskrit":"कांस्यस्य तु गुणा ज्ञेयाः स्वयोनिसदृशाजनैः संयोगजप्रभावेण तस्यान्येऽपि गुणाः स्मृताः ८.","text":"kāṃsyasya tu guṇā jñeyāḥ svayonisadṛśājanaiḥ saṃyogajaprabhāveṇa tasyānye'pi guṇāḥ smṛtāḥ 8."},{"type":"verse","number":"71","sanskrit":"कांस्यं कषायं तिक्तोष्णं लेखनं विशदं सरम् गुरु नेत्रहितं रूक्षं कफपित्तहरं परम्","text":"kāṃsyaṃ kaṣāyaṃ tiktoṣṇaṃ lekhanaṃ viśadaṃ saram guru netrahitaṃ rūkṣaṃ kaphapittaharaṃ param"},{"type":"verse","number":"72","sanskrit":"पित्तलं त्वारकूटं स्यादारो रीतिश्च कथ्यते राजरीतिर्ब्रह्मरीतिः कपिला पिङ्गलापि च","text":"pittalaṃ tvārakūṭaṃ syādāro rītiśca kathyate rājarītirbrahmarītiḥ kapilā piṅgalāpi ca"},{"type":"verse","number":"73","sanskrit":"रीतिरप्युपधातुः स्यात्ताम्रस्य यशदस्य च पित्तलस्य गुणा ज्ञेयाः स्वयोनिसदृशा जनैः","text":"rītirapyupadhātuḥ syāttāmrasya yaśadasya ca pittalasya guṇā jñeyāḥ svayonisadṛśā janaiḥ"},{"type":"verse","number":"74","sanskrit":"संयोगजप्रभावेण तस्याप्यन्ये गुणाः स्मृताः","text":"saṃyogajaprabhāveṇa tasyāpyanye guṇāḥ smṛtāḥ"},{"type":"verse","number":"75","sanskrit":"रीतिकायुगलं रूक्षं तिक्तञ्च लवणं रसे शोधनं पाण्डुरोगघ्नं कृमिघ्नं नातिलेखनम्","text":"rītikāyugalaṃ rūkṣaṃ tiktañca lavaṇaṃ rase śodhanaṃ pāṇḍurogaghnaṃ kṛmighnaṃ nātilekhanam"},{"type":"verse","number":"76","sanskrit":"सिन्दूरं रक्तरेणुश्च नागगर्भश्च सीसजम् सीसोपधातुः सिन्दूरं गुणैस्तत्सीसवन्मतम्","text":"sindūraṃ raktareṇuśca nāgagarbhaśca sīsajam sīsopadhātuḥ sindūraṃ guṇaistatsīsavanmatam"},{"type":"verse","number":"77","sanskrit":"संयोगजप्रभावेण तस्यान्येऽपि गुणाः स्मृताः सिन्दूरमुष्णं वीसर्पकुष्ठकण्डूविषापहम् भग्नसन्धानजननं व्रणशोधनरोपणम्","text":"saṃyogajaprabhāveṇa tasyānye'pi guṇāḥ smṛtāḥ sindūramuṣṇaṃ vīsarpakuṣṭhakaṇḍūviṣāpaham bhagnasandhānajananaṃ vraṇaśodhanaropaṇam"},{"type":"verse","number":"78","sanskrit":"निदाघे घर्मसन्तप्ता धातुसारं धराधराः निर्यासवत्प्रमुञ्चन्ति तच्छिलाजतु कीर्त्तितम्","text":"nidāghe gharmasantaptā dhātusāraṃ dharādharāḥ niryāsavatpramuñcanti tacchilājatu kīrttitam"},{"type":"verse","number":"79","sanskrit":"सौवर्णं राजतं ताम्रमायसं तच्चतुर्विधम् शिलाजत्वद्रि जतु च शैलनिर्यास इत्यपि","text":"sauvarṇaṃ rājataṃ tāmramāyasaṃ taccaturvidham śilājatvadri jatu ca śailaniryāsa ityapi"},{"type":"verse","number":"80","sanskrit":"गैरेयमश्मजं चापि गिरिजं शैलधातुजम् शिलाजं कटु तिक्तोष्णं कटुपाकं रसायनम् ८.","text":"gaireyamaśmajaṃ cāpi girijaṃ śailadhātujam śilājaṃ kaṭu tiktoṣṇaṃ kaṭupākaṃ rasāyanam 8."},{"type":"verse","number":"81","sanskrit":"छेदि योगवहं हन्ति कफमेहाश्मशर्कराः मूत्रकृच्छ्रं क्षयं श्वासं वातार्शांसि च पाण्डुताम्","text":"chedi yogavahaṃ hanti kaphamehāśmaśarkarāḥ mūtrakṛcchraṃ kṣayaṃ śvāsaṃ vātārśāṃsi ca pāṇḍutām"},{"type":"verse","number":"82","sanskrit":"अपस्मारं तथोन्मादं शोथकुष्ठोदरकृमीन्","text":"apasmāraṃ tathonmādaṃ śothakuṣṭhodarakṛmīn"},{"type":"verse","number":"83","sanskrit":"सौवर्णं तु जपापुष्पवर्णं भवति तद्र सात् मधुरं कटु तिक्तं च शीतलं कटुपाकि च","text":"sauvarṇaṃ tu japāpuṣpavarṇaṃ bhavati tadra sāt madhuraṃ kaṭu tiktaṃ ca śītalaṃ kaṭupāki ca"},{"type":"verse","number":"84","sanskrit":"राजतं पाण्डुरं शीतं कटुकं स्वादुपाकि च ताम्रं मयूरकण्ठाभं तीक्ष्णमुष्णं च जायते","text":"rājataṃ pāṇḍuraṃ śītaṃ kaṭukaṃ svādupāki ca tāmraṃ mayūrakaṇṭhābhaṃ tīkṣṇamuṣṇaṃ ca jāyate"},{"type":"verse","number":"85","sanskrit":"लौहं जटायुपक्षाभं सत्तिक्तं लवणं भवेत् विपाके कटुकं शीतं सर्वं श्रेष्ठमुदाहृतम्","text":"lauhaṃ jaṭāyupakṣābhaṃ sattiktaṃ lavaṇaṃ bhavet vipāke kaṭukaṃ śītaṃ sarvaṃ śreṣṭhamudāhṛtam"},{"type":"verse","number":"86","sanskrit":"रसायनार्थिभिर्लोकैः पारदो रस्यते यतः ततो रस इति प्रोक्तः स च धातुरपि स्मृतः","text":"rasāyanārthibhirlokaiḥ pārado rasyate yataḥ tato rasa iti proktaḥ sa ca dhāturapi smṛtaḥ"},{"type":"verse","number":"87","sanskrit":"शिवाङ्गात्प्रच्युतं रेतः पतितं धरणीतले तद्देहसारजातत्वाच्छुक्लमच्छमभूच्च तत्","text":"śivāṅgātpracyutaṃ retaḥ patitaṃ dharaṇītale taddehasārajātatvācchuklamacchamabhūcca tat"},{"type":"verse","number":"88","sanskrit":"क्षेत्रभेदेन विज्ञेयं शिववीर्यं चतुर्विधम् श्वेतं रक्तं तथा पीतं कृष्णं तत्तु भवेत्क्रमात् ब्राह्मणः क्षत्रियो वैश्यः शूद्र श्च खलु जातितः","text":"kṣetrabhedena vijñeyaṃ śivavīryaṃ caturvidham śvetaṃ raktaṃ tathā pītaṃ kṛṣṇaṃ tattu bhavetkramāt brāhmaṇaḥ kṣatriyo vaiśyaḥ śūdra śca khalu jātitaḥ"},{"type":"verse","number":"89","sanskrit":"श्वेतं शस्तं रुजां नाशे रक्तं किल रसायने धातुवादे तु तत्पीतं खे गतौ कृष्णमेव च","text":"śvetaṃ śastaṃ rujāṃ nāśe raktaṃ kila rasāyane dhātuvāde tu tatpītaṃ khe gatau kṛṣṇameva ca"},{"type":"verse","number":"90","sanskrit":"पारदो रसधातुश्च रसेन्द्र श्च महारसः ८.","text":"pārado rasadhātuśca rasendra śca mahārasaḥ 8."},{"type":"verse","number":"91","sanskrit":"चपलः शिववीर्यश्च रसः सूतः शिवाह्वयः पारदः षड्रसः स्निग्धस्त्रिदोषघ्नो रसायनः","text":"capalaḥ śivavīryaśca rasaḥ sūtaḥ śivāhvayaḥ pāradaḥ ṣaḍrasaḥ snigdhastridoṣaghno rasāyanaḥ"},{"type":"verse","number":"92","sanskrit":"योगवाही महावृष्यः सदा दृष्टिबलप्रदः सर्वामयहरः प्रोक्तो विशेषात्सर्वकुष्ठनुत्","text":"yogavāhī mahāvṛṣyaḥ sadā dṛṣṭibalapradaḥ sarvāmayaharaḥ prokto viśeṣātsarvakuṣṭhanut"},{"type":"verse","number":"93","sanskrit":"स्वस्थो रसो भवेद् ब्रह्मा बद्धो ज्ञेयो जनार्दनः रञ्जितः कामितश्चापि साक्षाद्देवो महेश्वरः","text":"svastho raso bhaved brahmā baddho jñeyo janārdanaḥ rañjitaḥ kāmitaścāpi sākṣāddevo maheśvaraḥ"},{"type":"verse","number":"94","sanskrit":"मूर्च्छितो हरति रुजं बन्धनमनुभूय खे गतिं कुरुते अजरीकरोति हि मृतः कोऽन्य करुणाऽकरः सूतात्","text":"mūrcchito harati rujaṃ bandhanamanubhūya khe gatiṃ kurute ajarīkaroti hi mṛtaḥ ko'nya karuṇā'karaḥ sūtāt"},{"type":"verse","number":"95","sanskrit":"असाध्यो यो भवेद्रो गो यस्य नास्ति चिकित्सितम् रसेन्द्रो हन्ति तं रोगं नरकुञ्जरवाजिनाम्","text":"asādhyo yo bhavedro go yasya nāsti cikitsitam rasendro hanti taṃ rogaṃ narakuñjaravājinām"},{"type":"verse","number":"96","sanskrit":"मलं विषं वह्निगिरित्वचापलं नैसर्गिकं दोषमुशन्ति पारदे उपाधिजौ द्वौ त्रपुनागयोगजौ दोषौ रसेन्द्रे कथितौ मुनीश्वरैः","text":"malaṃ viṣaṃ vahnigiritvacāpalaṃ naisargikaṃ doṣamuśanti pārade upādhijau dvau trapunāgayogajau doṣau rasendre kathitau munīśvaraiḥ"},{"type":"verse","number":"97","sanskrit":"मलेन मूर्च्छा मरणं विषेण दाहोऽग्निना कष्टतरः शरीरे देहस्य जाड्यं गिरिणा सदा स्युश्चाञ्चल्यतो वीर्यहृतिश्च पुंसाम् वङ्गेन कुष्ठं भुजगेन षण्ढो भवेदतोऽसौ परिशोधनीयः","text":"malena mūrcchā maraṇaṃ viṣeṇa dāho'gninā kaṣṭataraḥ śarīre dehasya jāḍyaṃ giriṇā sadā syuścāñcalyato vīryahṛtiśca puṃsām vaṅgena kuṣṭhaṃ bhujagena ṣaṇḍho bhavedato'sau pariśodhanīyaḥ"},{"type":"verse","number":"98","sanskrit":"वह्निर्विषं मलं चेति मुख्या दोषास्त्रयो रसे एते कुर्वन्ति सन्तापं मृतिं मूर्च्छां नृणां क्रमात्","text":"vahnirviṣaṃ malaṃ ceti mukhyā doṣāstrayo rase ete kurvanti santāpaṃ mṛtiṃ mūrcchāṃ nṛṇāṃ kramāt"},{"type":"verse","number":"99","sanskrit":"अन्येऽपि कथिता दोषा भिषग्भिः पारदे यदि तथाऽप्येते त्रयो दोषाहरणीया विशेषतः","text":"anye'pi kathitā doṣā bhiṣagbhiḥ pārade yadi tathā'pyete trayo doṣāharaṇīyā viśeṣataḥ"},{"type":"verse","number":"100","sanskrit":"संस्कारहीनं खलु सूतराजं यः सेवते तस्य करोति बाधाम् देहस्य नाशं विदधाति नूनं कष्टांश्च रोगाञ्जनयेन्नराणाम् ८.","text":"saṃskārahīnaṃ khalu sūtarājaṃ yaḥ sevate tasya karoti bādhām dehasya nāśaṃ vidadhāti nūnaṃ kaṣṭāṃśca rogāñjanayennarāṇām 8."},{"type":"verse","number":"101","sanskrit":"गन्धो हिङ्गुलमभ्रतालकशिलाः स्रोतोऽञ्जनं टङ्कणं राजावर्तकचुम्बकौ स्फटिकया शङ्खः खटी गैरिकम् कासीसं रसकं कपर्दसिकताबोलाश्च कुङ्कष्ठकं सौराष्ट्री च मता अमी उपरसाः सूतस्य किञ्चिद्गुणैः","text":"gandho hiṅgulamabhratālakaśilāḥ sroto'ñjanaṃ ṭaṅkaṇaṃ rājāvartakacumbakau sphaṭikayā śaṅkhaḥ khaṭī gairikam kāsīsaṃ rasakaṃ kapardasikatābolāśca kuṅkaṣṭhakaṃ saurāṣṭrī ca matā amī uparasāḥ sūtasya kiñcidguṇaiḥ"},{"type":"verse","number":"102","sanskrit":"हिङ्गुलं दरदं म्लेच्छमिङ्गुलं चूर्णपारदम् दरदस्त्रिविधः प्रोक्तश्चर्मारः शुकतुण्डकः","text":"hiṅgulaṃ daradaṃ mlecchamiṅgulaṃ cūrṇapāradam daradastrividhaḥ proktaścarmāraḥ śukatuṇḍakaḥ"},{"type":"verse","number":"103","sanskrit":"हंसपादस्तृतीयः स्याद् गुणवानुत्तरोत्तरम्","text":"haṃsapādastṛtīyaḥ syād guṇavānuttarottaram"},{"type":"verse","number":"104","sanskrit":"चर्मारः शुक्लवर्णः स्यात्स पीतः शुकतुण्डकः जपाकुसुमसङ्काशो हंसपादो महोत्तमः","text":"carmāraḥ śuklavarṇaḥ syātsa pītaḥ śukatuṇḍakaḥ japākusumasaṅkāśo haṃsapādo mahottamaḥ"},{"type":"verse","number":"105","sanskrit":"तिक्तं कषायं कटु हिङ्गुलं स्यान्नेत्रामयघ्नं कफपित्तहारि हृल्लासकुष्ठज्वरकामलाश्च प्लीहामवातौ च गरं निहन्ति","text":"tiktaṃ kaṣāyaṃ kaṭu hiṅgulaṃ syānnetrāmayaghnaṃ kaphapittahāri hṛllāsakuṣṭhajvarakāmalāśca plīhāmavātau ca garaṃ nihanti"},{"type":"verse","number":"106","sanskrit":"उर्ध्वपातनयुक्त्या तु डमरुयंत्रपाचितम् हिङ्गुलं तस्य सूतं तु शुद्धमेव न शोधयेत्","text":"urdhvapātanayuktyā tu ḍamaruyaṃtrapācitam hiṅgulaṃ tasya sūtaṃ tu śuddhameva na śodhayet"},{"type":"verse","number":"107","sanskrit":"श्वेतद्वीपे पुरा देव्याः क्रीडन्त्या रजसाऽप्लुतम् दुकूलं तेन वस्त्रेण स्नातायाः क्षीरनीरधौ","text":"śvetadvīpe purā devyāḥ krīḍantyā rajasā'plutam dukūlaṃ tena vastreṇa snātāyāḥ kṣīranīradhau"},{"type":"verse","number":"108","sanskrit":"प्रसृतं यद्र जस्तस्माद्गन्धकः समभूत्ततः गन्धको गान्धिकश्चापि गन्धपाषाण इत्यपि","text":"prasṛtaṃ yadra jastasmādgandhakaḥ samabhūttataḥ gandhako gāndhikaścāpi gandhapāṣāṇa ityapi"},{"type":"verse","number":"109","sanskrit":"सौगन्धिकश्च कथितो बलिर्बलरसोऽपि च चतुर्धा गन्धकः प्रोक्तो रक्तः पीतः सितोऽसितः","text":"saugandhikaśca kathito balirbalaraso'pi ca caturdhā gandhakaḥ prokto raktaḥ pītaḥ sito'sitaḥ"},{"type":"verse","number":"110","sanskrit":"रक्तो हेमक्रियासूक्तः पीतश्चैव रसायने व्रणादिलेपने श्वेतः कृष्णः श्रेष्ठः सुदुर्लभः ८.","text":"rakto hemakriyāsūktaḥ pītaścaiva rasāyane vraṇādilepane śvetaḥ kṛṣṇaḥ śreṣṭhaḥ sudurlabhaḥ 8."},{"type":"verse","number":"111","sanskrit":"गन्धकः कटुकस्तिक्तो वीर्योष्णस्तुवरः सरः पित्तलः कटुकः पाके जन्तुकण्डूविसर्पजित् हन्ति कुष्ठक्षयप्लीहकफवातान् रसायनः","text":"gandhakaḥ kaṭukastikto vīryoṣṇastuvaraḥ saraḥ pittalaḥ kaṭukaḥ pāke jantukaṇḍūvisarpajit hanti kuṣṭhakṣayaplīhakaphavātān rasāyanaḥ"},{"type":"verse","number":"112","sanskrit":"अशोधितो गन्धक एव कुष्ठं करोति तापं विषमं शरीरे सौख्यं च रूपं च वलं तथौजः शुक्रं निहन्त्येव करोति चास्रम्","text":"aśodhito gandhaka eva kuṣṭhaṃ karoti tāpaṃ viṣamaṃ śarīre saukhyaṃ ca rūpaṃ ca valaṃ tathaujaḥ śukraṃ nihantyeva karoti cāsram"},{"type":"verse","number":"113","sanskrit":"पुरा वधाय वृत्रस्य वज्रिणा वज्रमुद्धृतम् विस्फुलिङ्गास्ततस्तस्य गगने परिसर्पिताः","text":"purā vadhāya vṛtrasya vajriṇā vajramuddhṛtam visphuliṅgāstatastasya gagane parisarpitāḥ"},{"type":"verse","number":"114","sanskrit":"ते निपेतुर्घनध्वानाच्छिखरेषु महीभृताम् तेभ्य एव समुत्पन्नं तत्तद्गिरिषु चाभ्रकम्","text":"te nipeturghanadhvānācchikhareṣu mahībhṛtām tebhya eva samutpannaṃ tattadgiriṣu cābhrakam"},{"type":"verse","number":"115","sanskrit":"तद्वज्रं वज्रजातत्वादभ्रमभ्ररवोद्भवात् गगनात्स्खलितं यस्माद्गगनं च ततो मतम्","text":"tadvajraṃ vajrajātatvādabhramabhraravodbhavāt gaganātskhalitaṃ yasmādgaganaṃ ca tato matam"},{"type":"verse","number":"116","sanskrit":"विप्रक्षत्रियविट्शूद्र भेदात्तत्स्याच्चतुर्विधम् क्रमेणैव सितं रक्तं पीतं कृष्णं च वर्णतः","text":"viprakṣatriyaviṭśūdra bhedāttatsyāccaturvidham krameṇaiva sitaṃ raktaṃ pītaṃ kṛṣṇaṃ ca varṇataḥ"},{"type":"verse","number":"117","sanskrit":"प्रशस्यते सितं तारे रक्तं तत्तु रसायने पीतं हेमनि कृष्णं तु गदेषु द्रुतयेऽपि च","text":"praśasyate sitaṃ tāre raktaṃ tattu rasāyane pītaṃ hemani kṛṣṇaṃ tu gadeṣu drutaye'pi ca"},{"type":"verse","number":"118","sanskrit":"पिनाकं दर्दुरं नागं वज्रं चेति चतुर्विधम् मुच्चत्यग्नौ विनिक्षिप्तं पिनाकं दलसञ्चयम्","text":"pinākaṃ darduraṃ nāgaṃ vajraṃ ceti caturvidham muccatyagnau vinikṣiptaṃ pinākaṃ dalasañcayam"},{"type":"verse","number":"119","sanskrit":"अज्ञानाद्भक्षणं तस्य महाकुष्ठप्रदायकम् दुर्दरं त्वग्निनिक्षिप्तं कुरुते दुर्दरध्वनिम्","text":"ajñānādbhakṣaṇaṃ tasya mahākuṣṭhapradāyakam durdaraṃ tvagninikṣiptaṃ kurute durdaradhvanim"},{"type":"verse","number":"120","sanskrit":"गोलकान्बहुशः कृत्वा स स्यान्मृत्युप्रदायकः नागं तु नागवद्बह्वौ फूत्कारं परिमुञ्चति ८.","text":"golakānbahuśaḥ kṛtvā sa syānmṛtyupradāyakaḥ nāgaṃ tu nāgavadbahvau phūtkāraṃ parimuñcati 8."},{"type":"verse","number":"121","sanskrit":"तद्भक्षितमवश्यं तु विदधाति भगन्दरम् वज्रं तु वज्रवत्तिष्टेत्तन्नाग्नौ विकृतिं व्रजेत्","text":"tadbhakṣitamavaśyaṃ tu vidadhāti bhagandaram vajraṃ tu vajravattiṣṭettannāgnau vikṛtiṃ vrajet"},{"type":"verse","number":"122","sanskrit":"सर्वाभ्रेषु वरं वज्रं व्याधिवार्द्धक्यमृत्युहृत्","text":"sarvābhreṣu varaṃ vajraṃ vyādhivārddhakyamṛtyuhṛt"},{"type":"verse","number":"123","sanskrit":"अभ्रमुत्तरशैलोत्थं बहुसत्त्वं गुणाधिकम् दक्षिणाद्रि भवं स्वल्पसत्वमल्पगुणप्रदम्","text":"abhramuttaraśailotthaṃ bahusattvaṃ guṇādhikam dakṣiṇādri bhavaṃ svalpasatvamalpaguṇapradam"},{"type":"verse","number":"124","sanskrit":"अभ्रं कषायं मधुरं सुशीतमायुष्करं धातुविवर्द्धनं च हन्यात्त्रिदोषं व्रणमेहकुष्टप्लीहोदरग्रन्थिविषकृमींश्च","text":"abhraṃ kaṣāyaṃ madhuraṃ suśītamāyuṣkaraṃ dhātuvivarddhanaṃ ca hanyāttridoṣaṃ vraṇamehakuṣṭaplīhodaragranthiviṣakṛmīṃśca"},{"type":"verse","number":"125","sanskrit":"रोगान्हन्ति द्र ढयति वपुर्वीर्यवृद्धिं विधत्ते तारुण्याढ्यं रमयति शतं योषितां नित्यमेव दीर्घायुष्काञ्जनयति सुतान्विक्रमैः सिंहतुल्यान् मृत्योर्भीतिं हरति सततं सेव्यमानं मृताभ्रम्","text":"rogānhanti dra ḍhayati vapurvīryavṛddhiṃ vidhatte tāruṇyāḍhyaṃ ramayati śataṃ yoṣitāṃ nityameva dīrghāyuṣkāñjanayati sutānvikramaiḥ siṃhatulyān mṛtyorbhītiṃ harati satataṃ sevyamānaṃ mṛtābhram"},{"type":"verse","number":"126","sanskrit":"पीडां विधत्ते विविधां नराणां कुष्ठं क्षयं पाण्डुगदं च शोथम् हृत्पार्श्वपीडां च करोत्यशुद्धमभ्रं त्वसिद्धं गुरु तापदं स्यात्","text":"pīḍāṃ vidhatte vividhāṃ narāṇāṃ kuṣṭhaṃ kṣayaṃ pāṇḍugadaṃ ca śotham hṛtpārśvapīḍāṃ ca karotyaśuddhamabhraṃ tvasiddhaṃ guru tāpadaṃ syāt"},{"type":"verse","number":"127","sanskrit":"हरितालं तु तालं स्यादालं तालकमित्यपि हरितालं द्विधा प्रोक्तं पत्राख्यं पिण्डसंज्ञकम्","text":"haritālaṃ tu tālaṃ syādālaṃ tālakamityapi haritālaṃ dvidhā proktaṃ patrākhyaṃ piṇḍasaṃjñakam"},{"type":"verse","number":"128","sanskrit":"तयोराद्यं गुणैः श्रेष्ठं ततो हीनगुणं परम् स्वर्णवर्णं गुरु स्निग्धं सपत्रं चाभ्रपत्रवत्","text":"tayorādyaṃ guṇaiḥ śreṣṭhaṃ tato hīnaguṇaṃ param svarṇavarṇaṃ guru snigdhaṃ sapatraṃ cābhrapatravat"},{"type":"verse","number":"129","sanskrit":"पत्राख्यं तालकं विद्याद् गुणाढ्यं तद्र सायनम् निष्पत्रं पिण्डसदृशं स्वल्पसत्त्वं तथा गुरु","text":"patrākhyaṃ tālakaṃ vidyād guṇāḍhyaṃ tadra sāyanam niṣpatraṃ piṇḍasadṛśaṃ svalpasattvaṃ tathā guru"},{"type":"verse","number":"130","sanskrit":"स्त्रीपुष्पहारकं स्वल्पगुणं तत्पिण्डतालकम् हरितालं कटु स्निग्धं कषायोष्णं हरेद्विषम् कण्डूकुष्ठास्यरोगास्रकफपित्तकचव्रणान् ८.","text":"strīpuṣpahārakaṃ svalpaguṇaṃ tatpiṇḍatālakam haritālaṃ kaṭu snigdhaṃ kaṣāyoṣṇaṃ haredviṣam kaṇḍūkuṣṭhāsyarogāsrakaphapittakacavraṇān 8."},{"type":"verse","number":"131","sanskrit":"हरति च हरितालं चारुतां देहजातां सृजति च बहुतापञ्चाङ्गसङ्कोचपीडाम् वितरति कफवातौ कुष्ठरोगं विदध्यात् इदमशितमशुद्धं मारितं चाप्यसम्यक्","text":"harati ca haritālaṃ cārutāṃ dehajātāṃ sṛjati ca bahutāpañcāṅgasaṅkocapīḍām vitarati kaphavātau kuṣṭharogaṃ vidadhyāt idamaśitamaśuddhaṃ māritaṃ cāpyasamyak"},{"type":"verse","number":"132","sanskrit":"मनःशिला मनोगुप्ता मनोह्वा नागजिह्विका नैपाली कुनटी गोला शिला दिव्यौषधिः स्मृता","text":"manaḥśilā manoguptā manohvā nāgajihvikā naipālī kunaṭī golā śilā divyauṣadhiḥ smṛtā"},{"type":"verse","number":"133","sanskrit":"मनःशिला गुरुर्वर्ण्या सरोष्णा लेखनी कटुः तिक्ता स्निग्धा विषश्वासकासभूतकफास्रनुत्","text":"manaḥśilā gururvarṇyā saroṣṇā lekhanī kaṭuḥ tiktā snigdhā viṣaśvāsakāsabhūtakaphāsranut"},{"type":"verse","number":"134","sanskrit":"मनः शिला मन्दबलं करोति जन्तुं ध्रुवं शोधनमन्तरेण मलानुबन्धं किल मूत्ररोधं सशर्करं कृच्छ्रगदं च कुर्यात्","text":"manaḥ śilā mandabalaṃ karoti jantuṃ dhruvaṃ śodhanamantareṇa malānubandhaṃ kila mūtrarodhaṃ saśarkaraṃ kṛcchragadaṃ ca kuryāt"},{"type":"verse","number":"135","sanskrit":"अञ्जनं यामुनं चापि कापोताञ्जनमित्यपि तत्तु स्रोतोऽञ्जनं कृष्णं सौवीरं श्वेतमीरितम्","text":"añjanaṃ yāmunaṃ cāpi kāpotāñjanamityapi tattu sroto'ñjanaṃ kṛṣṇaṃ sauvīraṃ śvetamīritam"},{"type":"verse","number":"136","sanskrit":"वल्मीकशिखराकारे भिन्नमञ्जनसन्निभम् घृष्टं तु गैरिकाकारमेतत्स्रोतोऽञ्जनं स्मृतम्","text":"valmīkaśikharākāre bhinnamañjanasannibham ghṛṣṭaṃ tu gairikākārametatsroto'ñjanaṃ smṛtam"},{"type":"verse","number":"137","sanskrit":"स्रोतोऽञ्जनसमं ज्ञेयं सौवीरं तत्तु पाण्डुरम् स्रोतोऽञ्जनं स्मृतं स्वादु चक्षुष्यं कफपित्तनुत्","text":"sroto'ñjanasamaṃ jñeyaṃ sauvīraṃ tattu pāṇḍuram sroto'ñjanaṃ smṛtaṃ svādu cakṣuṣyaṃ kaphapittanut"},{"type":"verse","number":"138","sanskrit":"कषायं लेखनं स्निग्धं ग्राहि च्छर्दिविषापहम् सिध्मक्षयास्रहृच्छीतं सेवनीयं सदा बुधैः","text":"kaṣāyaṃ lekhanaṃ snigdhaṃ grāhi cchardiviṣāpaham sidhmakṣayāsrahṛcchītaṃ sevanīyaṃ sadā budhaiḥ"},{"type":"verse","number":"139","sanskrit":"स्रोतोऽञ्जनगुणाः सर्वे सौवीरेऽपि मता बुधैः किन्तु द्वयोरञ्जनयोः श्रेष्ठं स्रोतोऽञ्जनं स्मृतम्","text":"sroto'ñjanaguṇāḥ sarve sauvīre'pi matā budhaiḥ kintu dvayorañjanayoḥ śreṣṭhaṃ sroto'ñjanaṃ smṛtam"},{"type":"verse","number":"140","sanskrit":"टङ्कणोऽग्निकरो रूक्षः कफघ्नो वातपित्तकृत् ८.","text":"ṭaṅkaṇo'gnikaro rūkṣaḥ kaphaghno vātapittakṛt 8."},{"type":"verse","number":"141","sanskrit":"स्फटी च स्फटिका प्रोक्ता श्वेता शुभ्रा च रङ्गदा दृढरङ्गा रङ्गदृढा रङ्गाङ्गापि च कथ्यते","text":"sphaṭī ca sphaṭikā proktā śvetā śubhrā ca raṅgadā dṛḍharaṅgā raṅgadṛḍhā raṅgāṅgāpi ca kathyate"},{"type":"verse","number":"142","sanskrit":"स्फटिका तु कषायोष्णा वातपित्तकफव्रणान् निहन्ति श्वित्रवीसर्पान् योनिसङ्कोचकारिणी","text":"sphaṭikā tu kaṣāyoṣṇā vātapittakaphavraṇān nihanti śvitravīsarpān yonisaṅkocakāriṇī"},{"type":"verse","number":"143","sanskrit":"राजावर्त्तो नृपावर्त्तो राजन्यावर्त्तकस्तथा आवर्त्तमणिसंज्ञश्च ह्यावर्त्तोऽपि तथैव च","text":"rājāvartto nṛpāvartto rājanyāvarttakastathā āvarttamaṇisaṃjñaśca hyāvartto'pi tathaiva ca"},{"type":"verse","number":"144","sanskrit":"राजावर्त्तं कटुस्तिक्तः शिशिरः पित्तनाशनः राजावर्त्तः प्रमेहघ्नश्छर्दिहिक्कानिवारणः","text":"rājāvarttaṃ kaṭustiktaḥ śiśiraḥ pittanāśanaḥ rājāvarttaḥ pramehaghnaśchardihikkānivāraṇaḥ"},{"type":"verse","number":"145","sanskrit":"चुम्बकः कान्तपाषाणोऽयस्कान्तो लौहकर्षकः चुम्बको लेखनः शीतो मेदोविषगरापहः","text":"cumbakaḥ kāntapāṣāṇo'yaskānto lauhakarṣakaḥ cumbako lekhanaḥ śīto medoviṣagarāpahaḥ"},{"type":"verse","number":"146","sanskrit":"गैरिकं रक्तधातुश्च गैरेयं गिरिजं तथा सुवर्णगैरिकं त्वन्यत्ततो रक्ततरं हि तत्","text":"gairikaṃ raktadhātuśca gaireyaṃ girijaṃ tathā suvarṇagairikaṃ tvanyattato raktataraṃ hi tat"},{"type":"verse","number":"147","sanskrit":"गैरिकद्वितयं स्निग्धं मधुरं तुवरं हिमम् चक्षुष्यं दाहपित्तास्रकफहिक्काविषापहम्","text":"gairikadvitayaṃ snigdhaṃ madhuraṃ tuvaraṃ himam cakṣuṣyaṃ dāhapittāsrakaphahikkāviṣāpaham"},{"type":"verse","number":"148","sanskrit":"खटिका कठिनी चापि लेखनी च निगद्यते खटी दाहास्रजिच्छीता मधुरा विषशोथजित्","text":"khaṭikā kaṭhinī cāpi lekhanī ca nigadyate khaṭī dāhāsrajicchītā madhurā viṣaśothajit"},{"type":"verse","number":"149","sanskrit":"लेपादेतद्गुणा प्रोक्ता भक्षिता मृत्तिकासमा खटी गौरखटी द्वे च गुणैस्तुल्ये प्रकीर्त्तिते","text":"lepādetadguṇā proktā bhakṣitā mṛttikāsamā khaṭī gaurakhaṭī dve ca guṇaistulye prakīrttite"},{"type":"verse","number":"150","sanskrit":"बालुका सिकता प्रोक्ता शर्करा रेतजाऽपि च वालुका लेखनी शीता व्रणोरःक्षतनाशिनी ८.","text":"bālukā sikatā proktā śarkarā retajā'pi ca vālukā lekhanī śītā vraṇoraḥkṣatanāśinī 8."},{"type":"verse","number":"151","sanskrit":"खर्परी तुत्थकं तुत्थादन्यत्तद्र सकं स्मृतम् ये गुणास्तुत्थके प्रोक्तास्ते गुणा रसके स्मृता","text":"kharparī tutthakaṃ tutthādanyattadra sakaṃ smṛtam ye guṇāstutthake proktāste guṇā rasake smṛtā"},{"type":"verse","number":"152","sanskrit":"काशीशं धातुकाशीशं पांशुकाशीशमित्यपि तदेव किञ्चित्पीतं तु पुष्पकाशीशमुच्यते","text":"kāśīśaṃ dhātukāśīśaṃ pāṃśukāśīśamityapi tadeva kiñcitpītaṃ tu puṣpakāśīśamucyate"},{"type":"verse","number":"153","sanskrit":"काशीशमम्लमुष्णं च तिक्तञ्च तुवरं तथा वातश्लेष्महरं केश्यं नेत्रकण्डूविषप्रणुत् मूत्रकृच्छ्राश्मरीश्वित्रनाशनं परिकीर्त्तितम्","text":"kāśīśamamlamuṣṇaṃ ca tiktañca tuvaraṃ tathā vātaśleṣmaharaṃ keśyaṃ netrakaṇḍūviṣapraṇut mūtrakṛcchrāśmarīśvitranāśanaṃ parikīrttitam"},{"type":"verse","number":"154","sanskrit":"सौराष्ट्री तुवरी काली मृत्तालकसुराष्ट्रजे","text":"saurāṣṭrī tuvarī kālī mṛttālakasurāṣṭraje"},{"type":"verse","number":"155","sanskrit":"आढकी चापि सा ख्याता मृत्स्ना च सुरमृत्तिका स्फटिकायागुणाः सर्वे सौराष्ट्र्या अपि कीर्त्तिताः","text":"āḍhakī cāpi sā khyātā mṛtsnā ca suramṛttikā sphaṭikāyāguṇāḥ sarve saurāṣṭryā api kīrttitāḥ"},{"type":"verse","number":"156","sanskrit":"मृन्मृदा मृत्तिका मृत्स्ना क्षेत्रजा कृष्णमृत्तिका कृष्णमृत् क्षतदाहास्रप्रदरश्लेष्मपित्तनुत्","text":"mṛnmṛdā mṛttikā mṛtsnā kṣetrajā kṛṣṇamṛttikā kṛṣṇamṛt kṣatadāhāsrapradaraśleṣmapittanut"},{"type":"verse","number":"157","sanskrit":"पङ्कस्तु जलकल्कश्च चुलुकः कर्दमो मलः चिकिलः पलितो द्रा पः पललश्च निषद्वरः कर्दमो दाहपित्तास्रशोथघ्नः शीतलः सरः","text":"paṅkastu jalakalkaśca culukaḥ kardamo malaḥ cikilaḥ palito drā paḥ palalaśca niṣadvaraḥ kardamo dāhapittāsraśothaghnaḥ śītalaḥ saraḥ"},{"type":"verse","number":"158","sanskrit":"कपर्दको वराटश्च कपर्दी च वराटिका कर्णस्रावाग्निमान्द्यघ्नी पित्तास्रकफनाशिनी","text":"kapardako varāṭaśca kapardī ca varāṭikā karṇasrāvāgnimāndyaghnī pittāsrakaphanāśinī"},{"type":"verse","number":"159","sanskrit":"शङ्खः समुद्र जः कम्बुः सुनादः पावनध्वनिः शङ्खो नेत्र्! यो हिमः शीतो लघुः पित्तकफास्रजित्","text":"śaṅkhaḥ samudra jaḥ kambuḥ sunādaḥ pāvanadhvaniḥ śaṅkho netr! yo himaḥ śīto laghuḥ pittakaphāsrajit"},{"type":"verse","number":"160","sanskrit":"बोलगन्धरसप्राणपिण्डगोपरसाः समाः बोलं रक्तहरं शीतं मेध्यं दीपनपाचनम् मधुरं कटु तिक्तं च दाहस्वेदत्रिदोषजित् ज्वरापस्मारकुष्ठघ्नं गर्भाशयविशुद्धिकृत् ८.","text":"bolagandharasaprāṇapiṇḍagoparasāḥ samāḥ bolaṃ raktaharaṃ śītaṃ medhyaṃ dīpanapācanam madhuraṃ kaṭu tiktaṃ ca dāhasvedatridoṣajit jvarāpasmārakuṣṭhaghnaṃ garbhāśayaviśuddhikṛt 8."},{"type":"verse","number":"161","sanskrit":"हिमवत्पादशिखरे कङ्कुष्ठमुपजायते तत्रैकं रक्तकालं स्यात्तदन्यद्दण्डकं स्मृतम्","text":"himavatpādaśikhare kaṅkuṣṭhamupajāyate tatraikaṃ raktakālaṃ syāttadanyaddaṇḍakaṃ smṛtam"},{"type":"verse","number":"162","sanskrit":"पीतप्रभं गुरु स्निग्धं श्रेष्ठं कङ्कुष्ठमादिमम् श्यामं पीतं लघु त्यक्तसत्त्वं नेष्टं तथाऽण्डकम्","text":"pītaprabhaṃ guru snigdhaṃ śreṣṭhaṃ kaṅkuṣṭhamādimam śyāmaṃ pītaṃ laghu tyaktasattvaṃ neṣṭaṃ tathā'ṇḍakam"},{"type":"verse","number":"163","sanskrit":"कङ्कुष्टं काककुष्ठं च विरङ्गं कोलकाकुलम्","text":"kaṅkuṣṭaṃ kākakuṣṭhaṃ ca viraṅgaṃ kolakākulam"},{"type":"verse","number":"164","sanskrit":"कङ्कुष्ठं रेचनं तिक्तं कटूष्णं वर्णकारकम् कृमिशोथोदराध्मानगुल्मानाहकफापहम्","text":"kaṅkuṣṭhaṃ recanaṃ tiktaṃ kaṭūṣṇaṃ varṇakārakam kṛmiśothodarādhmānagulmānāhakaphāpaham"},{"type":"verse","number":"165","sanskrit":"धनार्थिनो जनाःसर्वे रमन्तेऽस्मिन्नतीव यत् ततो रत्नमिति प्रोक्तं शब्दशास्त्रविशारदैः","text":"dhanārthino janāḥsarve ramante'sminnatīva yat tato ratnamiti proktaṃ śabdaśāstraviśāradaiḥ"},{"type":"verse","number":"166","sanskrit":"रत्नं क्लीबे मणिः पुंसि स्त्रियामपि निगद्यते तत्तु पाषाणभेदोऽस्ति मुक्तादि च तदुच्यते","text":"ratnaṃ klībe maṇiḥ puṃsi striyāmapi nigadyate tattu pāṣāṇabhedo'sti muktādi ca taducyate"},{"type":"verse","number":"167","sanskrit":"रत्नं गारुत्मतं पुष्परागो माणिक्यमेव च इन्द्र नीलश्च गोमेदस्तथा वैदूर्यमित्यपि मौक्तिकं विद्रुमश्चेति रत्नान्युक्तानि वै नव","text":"ratnaṃ gārutmataṃ puṣparāgo māṇikyameva ca indra nīlaśca gomedastathā vaidūryamityapi mauktikaṃ vidrumaśceti ratnānyuktāni vai nava"},{"type":"verse","number":"168","sanskrit":"मुक्ताफलं हीरकं च वैदूर्यं पद्मरागकम्","text":"muktāphalaṃ hīrakaṃ ca vaidūryaṃ padmarāgakam"},{"type":"verse","number":"169","sanskrit":"पुष्परागं च गोमेदं नीलं गारुत्मतं तथा प्रवालयुक्तान्येतानि महारत्नानि वै नव","text":"puṣparāgaṃ ca gomedaṃ nīlaṃ gārutmataṃ tathā pravālayuktānyetāni mahāratnāni vai nava"},{"type":"verse","number":"170","sanskrit":"हीरकः पुंसि वज्रोऽस्त्री चन्द्रो मणिवरश्च सः स तु श्वेतः स्मृतो विप्रो लोहितः क्षत्रियः स्मृतः पीतो वैश्योऽसितः शूद्र श्चतुर्वर्णात्मकश्च सः ८.","text":"hīrakaḥ puṃsi vajro'strī candro maṇivaraśca saḥ sa tu śvetaḥ smṛto vipro lohitaḥ kṣatriyaḥ smṛtaḥ pīto vaiśyo'sitaḥ śūdra ścaturvarṇātmakaśca saḥ 8."},{"type":"verse","number":"171","sanskrit":"रसायने मतो विप्रः सर्वसिद्धिप्रदायकः क्षत्रियो व्याधिविध्वंसी जरामृत्युहरः स्मृतः","text":"rasāyane mato vipraḥ sarvasiddhipradāyakaḥ kṣatriyo vyādhividhvaṃsī jarāmṛtyuharaḥ smṛtaḥ"},{"type":"verse","number":"172","sanskrit":"वैश्यो धनप्रदः प्रोक्तस्तथा देहस्यदार्ढ्यकृत् शूद्रो नाशयति व्याधीन् वयःस्तम्भं करोति च","text":"vaiśyo dhanapradaḥ proktastathā dehasyadārḍhyakṛt śūdro nāśayati vyādhīn vayaḥstambhaṃ karoti ca"},{"type":"verse","number":"173","sanskrit":"अथ पुंस्त्रीनपुंसकभेदात् त्रिविधस्य तस्य पुंस्त्रीनपुंसकानीह लक्षणीयानि लक्षणैः सुवृत्ताः फलसम्पूर्णास्तेजोयुक्ता बृहत्तराः","text":"atha puṃstrīnapuṃsakabhedāt trividhasya tasya puṃstrīnapuṃsakānīha lakṣaṇīyāni lakṣaṇaiḥ suvṛttāḥ phalasampūrṇāstejoyuktā bṛhattarāḥ"},{"type":"verse","number":"174","sanskrit":"पुरुषास्ते समाख्याता रेखाविन्दु विवर्जिताः रेखाविन्दुसमायुक्ताः षडस्रास्ते स्त्रियः स्मृताः","text":"puruṣāste samākhyātā rekhāvindu vivarjitāḥ rekhāvindusamāyuktāḥ ṣaḍasrāste striyaḥ smṛtāḥ"},{"type":"verse","number":"175","sanskrit":"त्रिकोणाश्च सुदीर्घास्ते विज्ञेयाश्च नपुंसकाः तेषु स्युः पुरुषाः श्रेष्ठा रसबन्धनकारिणः","text":"trikoṇāśca sudīrghāste vijñeyāśca napuṃsakāḥ teṣu syuḥ puruṣāḥ śreṣṭhā rasabandhanakāriṇaḥ"},{"type":"verse","number":"176","sanskrit":"स्त्रियः कुर्वन्ति कायस्य कान्तिं स्त्रीणां सुखप्रदाः नपुंसकास्त्ववीर्याः स्युरकामा सत्ववर्जिताः","text":"striyaḥ kurvanti kāyasya kāntiṃ strīṇāṃ sukhapradāḥ napuṃsakāstvavīryāḥ syurakāmā satvavarjitāḥ"},{"type":"verse","number":"177","sanskrit":"स्त्रियः स्त्रीभ्यः प्रदातव्याः क्लीबं क्लीबे प्रयोजयेत् सर्वेभ्यः सर्वदादेयाः पुरुषा वीर्यवर्धनाः","text":"striyaḥ strībhyaḥ pradātavyāḥ klībaṃ klībe prayojayet sarvebhyaḥ sarvadādeyāḥ puruṣā vīryavardhanāḥ"},{"type":"verse","number":"178","sanskrit":"अशुद्धं कुरुते वज्रं कुष्ठं पार्श्वव्यथां तथा पाण्डुतां पङ्गुलत्वं च तस्मात्संशोध्य मारयेत्","text":"aśuddhaṃ kurute vajraṃ kuṣṭhaṃ pārśvavyathāṃ tathā pāṇḍutāṃ paṅgulatvaṃ ca tasmātsaṃśodhya mārayet"},{"type":"verse","number":"179","sanskrit":"आयुः पुष्टिं बलं वीर्यं वर्णं सौख्यं करोति च सेवितं सर्वरोगघ्नं मृतं वज्रं न संशयः","text":"āyuḥ puṣṭiṃ balaṃ vīryaṃ varṇaṃ saukhyaṃ karoti ca sevitaṃ sarvarogaghnaṃ mṛtaṃ vajraṃ na saṃśayaḥ"},{"type":"verse","number":"180","sanskrit":"गारुत्मतं मरकतमश्मगर्भो हरिन्मणिः ८.","text":"gārutmataṃ marakatamaśmagarbho harinmaṇiḥ 8."},{"type":"verse","number":"181","sanskrit":"माणिक्यं पद्मरागः स्याच्छोणरत्नञ्च लोहितम्","text":"māṇikyaṃ padmarāgaḥ syācchoṇaratnañca lohitam"},{"type":"verse","number":"182","sanskrit":"पुष्परागो मञ्जुमणिः स्याद्वाचस्पतिवल्लभः","text":"puṣparāgo mañjumaṇiḥ syādvācaspativallabhaḥ"},{"type":"verse","number":"183","sanskrit":"नीलं तथेन्द्र नीलञ्च गोमेदः पीतरत्नकम्","text":"nīlaṃ tathendra nīlañca gomedaḥ pītaratnakam"},{"type":"verse","number":"184","sanskrit":"वैदूर्यं दूरजं रत्नं स्यात्केतुग्रहवल्लभम्","text":"vaidūryaṃ dūrajaṃ ratnaṃ syātketugrahavallabham"},{"type":"verse","number":"185","sanskrit":"मौक्तिकं शौतिक्तं मुक्ता तथा मुक्ताफलञ्च तत् शुक्तिः शङ्खो गजः क्रोडः फणी मत्स्यश्च दर्दुरः वेणुरेते समाख्यातास्तज्ज्ञैर्मौक्तिकयोनयः मौक्तितं शीतलं वृष्यं चक्षुष्यं बलपुष्टिदम्","text":"mauktikaṃ śautiktaṃ muktā tathā muktāphalañca tat śuktiḥ śaṅkho gajaḥ kroḍaḥ phaṇī matsyaśca darduraḥ veṇurete samākhyātāstajjñairmauktikayonayaḥ mauktitaṃ śītalaṃ vṛṣyaṃ cakṣuṣyaṃ balapuṣṭidam"},{"type":"verse","number":"186","sanskrit":"पुंसि क्लीबे प्रवालः स्यात्पुमानेव तु विद्रुमः","text":"puṃsi klībe pravālaḥ syātpumāneva tu vidrumaḥ"},{"type":"verse","number":"187","sanskrit":"रत्नानि भक्षितानि स्युर्मधुराणि सराणि च चक्षुष्याणि च शीतानि विषघ्नानि धृतानि च मङ्गल्यानि मनोज्ञानि ग्रहदोषहराणि च","text":"ratnāni bhakṣitāni syurmadhurāṇi sarāṇi ca cakṣuṣyāṇi ca śītāni viṣaghnāni dhṛtāni ca maṅgalyāni manojñāni grahadoṣaharāṇi ca"},{"type":"verse","number":"188","sanskrit":"किं रत्नं कस्य ग्रहस्य प्रीतिकारित्वेन दोषहरं भवतीति प्रश्ने तदुत्तरमाहै रत्नमालायाम् माणिक्यं तरणेः सुजातममलं मुक्ताफलं शीतगो र्माहेयस्य तु विद्रुमो निगदितः सौम्यस्य गारुत्मतम् देवेज्यस्य च पुष्परागमसुराचार्यस्य वज्रं शने र्नीलं निर्मलमन्ययोर्निगदिते गोमेदवैदूर्यके","text":"kiṃ ratnaṃ kasya grahasya prītikāritvena doṣaharaṃ bhavatīti praśne taduttaramāhai ratnamālāyām māṇikyaṃ taraṇeḥ sujātamamalaṃ muktāphalaṃ śītago rmāheyasya tu vidrumo nigaditaḥ saumyasya gārutmatam devejyasya ca puṣparāgamasurācāryasya vajraṃ śane rnīlaṃ nirmalamanyayornigadite gomedavaidūryake"},{"type":"verse","number":"189","sanskrit":"उपरत्नानि काचश्च कर्पूराश्मा तथैव च मुक्ताशुक्तिस्तथा शङ्ख इत्यादीनि बहून्यपि","text":"uparatnāni kācaśca karpūrāśmā tathaiva ca muktāśuktistathā śaṅkha ityādīni bahūnyapi"},{"type":"verse","number":"190","sanskrit":"गुणा यथैव रत्नानामुपरत्नेषु ते तथा किन्तु किञ्चित्ततो हीना विशेषोऽयमुदाहृतः ८.","text":"guṇā yathaiva ratnānāmuparatneṣu te tathā kintu kiñcittato hīnā viśeṣo'yamudāhṛtaḥ 8."},{"type":"verse","number":"191","sanskrit":"विषं तु गरलः क्षवेडस्तस्य भेदानुदाहरे वत्सनाभः सहारिद्र ः! सक्तुकश्च प्रदीपनः सौराष्ट्रिकः शृङ्गिकश्च कालकूटस्तथैव च हालाहलो ब्रह्मपुत्रो विषभेदा अमी नव","text":"viṣaṃ tu garalaḥ kṣaveḍastasya bhedānudāhare vatsanābhaḥ sahāridra ḥ! saktukaśca pradīpanaḥ saurāṣṭrikaḥ śṛṅgikaśca kālakūṭastathaiva ca hālāhalo brahmaputro viṣabhedā amī nava"},{"type":"verse","number":"192","sanskrit":"सिन्दुवारसदृक्पत्रो वत्सनाभ्याकृतिस्तथा यत्पार्श्वे न तरोर्वृद्धिर्वत्सनाभः स भाषितः","text":"sinduvārasadṛkpatro vatsanābhyākṛtistathā yatpārśve na tarorvṛddhirvatsanābhaḥ sa bhāṣitaḥ"},{"type":"verse","number":"193","sanskrit":"हरिद्रा तुल्यमूलो यो हारिद्र ः! स उदाहृतः","text":"haridrā tulyamūlo yo hāridra ḥ! sa udāhṛtaḥ"},{"type":"verse","number":"194","sanskrit":"यद्ग्रन्थिः सक्तुकेनैव पूर्णमध्यः स सक्तुकः","text":"yadgranthiḥ saktukenaiva pūrṇamadhyaḥ sa saktukaḥ"},{"type":"verse","number":"195","sanskrit":"वर्णतो लोहितो यः स्याद्दीप्तिमान् दहनप्रभः महादाहकरः पूर्वैः कथितं स प्रदीपनः","text":"varṇato lohito yaḥ syāddīptimān dahanaprabhaḥ mahādāhakaraḥ pūrvaiḥ kathitaṃ sa pradīpanaḥ"},{"type":"verse","number":"196","sanskrit":"सुराष्ट्रविषये यः स्यात्स सौराष्ट्रिक उच्यते","text":"surāṣṭraviṣaye yaḥ syātsa saurāṣṭrika ucyate"},{"type":"verse","number":"197","sanskrit":"यस्मिन् गोशृङ्गके बद्धे दुग्धं भवति लोहितम् स शृङ्गिक इति प्रोक्तो द्र व्यतत्त्वविशारदैः","text":"yasmin gośṛṅgake baddhe dugdhaṃ bhavati lohitam sa śṛṅgika iti prokto dra vyatattvaviśāradaiḥ"},{"type":"verse","number":"198","sanskrit":"देवासुररणे देवैर्हतस्य पृथुमालिनः दैत्यस्य रुधिराज्जातस्तरुरश्वत्थसन्निभः निर्यासः कालकूटोऽस्य मुनिभिः परिकीर्त्तितः सोऽहिक्षेत्रे शृङ्गवेरे कोङ्कणे मलये भवेत्","text":"devāsuraraṇe devairhatasya pṛthumālinaḥ daityasya rudhirājjātastaruraśvatthasannibhaḥ niryāsaḥ kālakūṭo'sya munibhiḥ parikīrttitaḥ so'hikṣetre śṛṅgavere koṅkaṇe malaye bhavet"},{"type":"verse","number":"199","sanskrit":"गोस्तनाभफलो गुच्छस्तालपत्रच्छदस्तथा तेजसा यस्य दह्यन्ते समीपस्था द्रुमादयः असौ हालाहलो ज्ञेयः किष्किन्धायां हिमालये दक्षिणाब्धितटे देशे कोङ्कणेऽपि च जायते","text":"gostanābhaphalo gucchastālapatracchadastathā tejasā yasya dahyante samīpasthā drumādayaḥ asau hālāhalo jñeyaḥ kiṣkindhāyāṃ himālaye dakṣiṇābdhitaṭe deśe koṅkaṇe'pi ca jāyate"},{"type":"verse","number":"200","sanskrit":"वर्णतः कपिलो यः स्यात्तथा भवति सारतः ब्रह्मपुत्रः सविज्ञेयो जायते मलयाचले ८.","text":"varṇataḥ kapilo yaḥ syāttathā bhavati sārataḥ brahmaputraḥ savijñeyo jāyate malayācale 8."},{"type":"verse","number":"201","sanskrit":"ब्राह्मणः पाण्डुरस्तेषु क्षत्रियो लोहितप्रभः वैश्यः पीतोऽसितः शूद्रो विष उक्तश्चतुर्विधः","text":"brāhmaṇaḥ pāṇḍurasteṣu kṣatriyo lohitaprabhaḥ vaiśyaḥ pīto'sitaḥ śūdro viṣa uktaścaturvidhaḥ"},{"type":"verse","number":"202","sanskrit":"रसायने विषं विप्रं क्षत्रियं देहपुष्टये वैश्यं कुष्ठविनाशाय शूद्रं दद्याद्वधाय हि","text":"rasāyane viṣaṃ vipraṃ kṣatriyaṃ dehapuṣṭaye vaiśyaṃ kuṣṭhavināśāya śūdraṃ dadyādvadhāya hi"},{"type":"verse","number":"203","sanskrit":"विषं प्राणहरं प्रोक्तं व्यवायि च विकाशि च आग्नेयं वातकफहृद्योगवाहि मदावहम्","text":"viṣaṃ prāṇaharaṃ proktaṃ vyavāyi ca vikāśi ca āgneyaṃ vātakaphahṛdyogavāhi madāvaham"},{"type":"verse","number":"204","sanskrit":"तदेव युक्तियुक्तं तु प्राणदायि रसायनम् योगवाहि त्रिदोषघ्नं बृंहणं वीर्यवर्द्धनम्","text":"tadeva yuktiyuktaṃ tu prāṇadāyi rasāyanam yogavāhi tridoṣaghnaṃ bṛṃhaṇaṃ vīryavarddhanam"},{"type":"verse","number":"205","sanskrit":"ये दुर्गुणा विषेऽशुद्धे ते स्युर्हीना विशोधनात् तस्माद्विषं प्रयोगेषु शोधयित्वा प्रयोजयेत्","text":"ye durguṇā viṣe'śuddhe te syurhīnā viśodhanāt tasmādviṣaṃ prayogeṣu śodhayitvā prayojayet"},{"type":"verse","number":"206","sanskrit":"अर्कक्षीरं स्नुहीक्षीरं लाङ्गली करवीरकः गुञ्जाऽहिफेनो धत्तूरः सप्तोपविषजातयः","text":"arkakṣīraṃ snuhīkṣīraṃ lāṅgalī karavīrakaḥ guñjā'hipheno dhattūraḥ saptopaviṣajātayaḥ"},{"type":"verse","number":"8","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे अष्टमः धात्वादिवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe aṣṭamaḥ dhātvādivargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":8,"lang":"sa","content":[{"type":"heading","heading":"dhānya-варга — зерновые"},{"type":"verse","number":"1","sanskrit":"शालिधान्यं व्रीहिधान्यं शूकधान्यं तृतीयकम् शिम्बीधान्यं क्षुद्र धान्यमित्युक्तं धान्यपञ्चकम्","text":"śālidhānyaṃ vrīhidhānyaṃ śūkadhānyaṃ tṛtīyakam śimbīdhānyaṃ kṣudra dhānyamityuktaṃ dhānyapañcakam"},{"type":"verse","number":"2","sanskrit":"शालयो रक्तशाल्याद्या व्रीहयः षष्टिकादयः यवादिकं शूकधान्यं मुद्गाद्यंशिम्बिधान्यकम् कङ्ग्वादिकं क्षुद्र धान्यं तृणधान्यञ्च तत्स्मृतम्","text":"śālayo raktaśālyādyā vrīhayaḥ ṣaṣṭikādayaḥ yavādikaṃ śūkadhānyaṃ mudgādyaṃśimbidhānyakam kaṅgvādikaṃ kṣudra dhānyaṃ tṛṇadhānyañca tatsmṛtam"},{"type":"verse","number":"3","sanskrit":"कण्डनेन विना शुक्ला हैमन्ताः शालयः स्मृताः","text":"kaṇḍanena vinā śuklā haimantāḥ śālayaḥ smṛtāḥ"},{"type":"verse","number":"4","sanskrit":"रक्तशालि सकलमः पाण्डुकः शकुनाहृतः सुगन्धकः कर्दमको महाशालिश्च दूषकः","text":"raktaśāli sakalamaḥ pāṇḍukaḥ śakunāhṛtaḥ sugandhakaḥ kardamako mahāśāliśca dūṣakaḥ"},{"type":"verse","number":"5","sanskrit":"पुष्पाण्डकः पुण्डरीकस्तथा महिषमस्तकः दीर्घशूकः काञ्चनको हायनो लोध्रपुष्पकः","text":"puṣpāṇḍakaḥ puṇḍarīkastathā mahiṣamastakaḥ dīrghaśūkaḥ kāñcanako hāyano lodhrapuṣpakaḥ"},{"type":"verse","number":"6","sanskrit":"इत्याद्याः शालयः सन्ति बहवो बहुदेशजाः ग्रन्थविस्तरभीतेस्ते समस्ता नात्र भाषिताः","text":"ityādyāḥ śālayaḥ santi bahavo bahudeśajāḥ granthavistarabhīteste samastā nātra bhāṣitāḥ"},{"type":"verse","number":"7","sanskrit":"शालयो मधुरा स्निग्धा बल्या बद्धाल्पवर्चसः कषाया लघवो रुच्याः स्वर्या वृष्याश्च बृंहणाः अल्पानिलकफाः शीताः पित्तघ्ना मूत्रलास्तथा","text":"śālayo madhurā snigdhā balyā baddhālpavarcasaḥ kaṣāyā laghavo rucyāḥ svaryā vṛṣyāśca bṛṃhaṇāḥ alpānilakaphāḥ śītāḥ pittaghnā mūtralāstathā"},{"type":"verse","number":"8","sanskrit":"शालयो दग्धमृज्जाताः कषाया लघुपाकिनः सृष्टमूत्रपुरीषाश्च रूक्षाः श्लेष्मापकर्षणाः","text":"śālayo dagdhamṛjjātāḥ kaṣāyā laghupākinaḥ sṛṣṭamūtrapurīṣāśca rūkṣāḥ śleṣmāpakarṣaṇāḥ"},{"type":"verse","number":"9","sanskrit":"कैदारा वातपित्तघ्ना गुरवः कफशुक्रलाः कषायाश्चाल्पवर्चस्का मेध्याश्चैव बलावहाः","text":"kaidārā vātapittaghnā guravaḥ kaphaśukralāḥ kaṣāyāścālpavarcaskā medhyāścaiva balāvahāḥ"},{"type":"verse","number":"10","sanskrit":"स्थलजाः स्वादवः पित्तकफघ्ना वातपित्तदाः किञ्चित्तिक्ताः कषायाश्च विपाके कटुका अपि ९.","text":"sthalajāḥ svādavaḥ pittakaphaghnā vātapittadāḥ kiñcittiktāḥ kaṣāyāśca vipāke kaṭukā api 9."},{"type":"verse","number":"11","sanskrit":"वापिता मधुरा वृष्या बल्याः पित्तप्रणाशनाः श्लेष्मलाश्चाल्पवर्चस्काः कषाया गुरवो हिमाः","text":"vāpitā madhurā vṛṣyā balyāḥ pittapraṇāśanāḥ śleṣmalāścālpavarcaskāḥ kaṣāyā guravo himāḥ"},{"type":"verse","number":"12","sanskrit":"वापितेभ्यो गुणैः किञ्चिद्धीनाः प्रोक्ता अवापिताः","text":"vāpitebhyo guṇaiḥ kiñciddhīnāḥ proktā avāpitāḥ"},{"type":"verse","number":"13","sanskrit":"रोपितास्तु नवा वृष्या पुराणा लघवः स्मृताः तेभ्यस्तुरोपिता भूयः शीघ्रपाका गुणाधिकाः","text":"ropitāstu navā vṛṣyā purāṇā laghavaḥ smṛtāḥ tebhyasturopitā bhūyaḥ śīghrapākā guṇādhikāḥ"},{"type":"verse","number":"14","sanskrit":"छिन्नरूढा हिमा रूक्षा बल्याः पित्तकफापहाः बद्धविट्काः कषायाश्च लघवश्चाल्पतिक्तकाः","text":"chinnarūḍhā himā rūkṣā balyāḥ pittakaphāpahāḥ baddhaviṭkāḥ kaṣāyāśca laghavaścālpatiktakāḥ"},{"type":"verse","number":"15","sanskrit":"रक्तशालिर्वरस्तेषु बल्यो वर्ण्यस्त्रिदोषजित् चक्षुष्यो मूत्रलः स्वर्यः शुक्रलस्तृड्ज्वरापहः","text":"raktaśālirvarasteṣu balyo varṇyastridoṣajit cakṣuṣyo mūtralaḥ svaryaḥ śukralastṛḍjvarāpahaḥ"},{"type":"verse","number":"16","sanskrit":"विषव्रणश्वासकासदाहनुद् वह्निपुष्टिदः तस्मादल्पान्तरगुणाः शालयो महदादयः","text":"viṣavraṇaśvāsakāsadāhanud vahnipuṣṭidaḥ tasmādalpāntaraguṇāḥ śālayo mahadādayaḥ"},{"type":"verse","number":"17","sanskrit":"वार्षिकाः कण्डिताः शुक्ला व्रीहयश्चिरपाकिनः कृष्णव्रीहिः पाटलश्च कुक्कुटाण्डक इत्यपि","text":"vārṣikāḥ kaṇḍitāḥ śuklā vrīhayaścirapākinaḥ kṛṣṇavrīhiḥ pāṭalaśca kukkuṭāṇḍaka ityapi"},{"type":"verse","number":"18","sanskrit":"शालामुखो जतुमुख इत्याद्या व्रीहयः स्मृताः कृष्णब्रीहिः स विज्ञेयो यत्कृष्णतुषतण्डुलः","text":"śālāmukho jatumukha ityādyā vrīhayaḥ smṛtāḥ kṛṣṇabrīhiḥ sa vijñeyo yatkṛṣṇatuṣataṇḍulaḥ"},{"type":"verse","number":"19","sanskrit":"पाटलः पाटलापुष्पवर्णको ब्रीहिरुच्यते कुक्कुटाण्डाकृतिव्रीहिः कुक्कुटाण्डक उच्यते","text":"pāṭalaḥ pāṭalāpuṣpavarṇako brīhirucyate kukkuṭāṇḍākṛtivrīhiḥ kukkuṭāṇḍaka ucyate"},{"type":"verse","number":"20","sanskrit":"शालामुखः कृष्णशूकः कृष्णतण्डुल उच्यते लाक्षावर्णं मुखं यस्य ज्ञेयो जतुमुखस्तु सः ९.","text":"śālāmukhaḥ kṛṣṇaśūkaḥ kṛṣṇataṇḍula ucyate lākṣāvarṇaṃ mukhaṃ yasya jñeyo jatumukhastu saḥ 9."},{"type":"verse","number":"21","sanskrit":"व्रीहयः कथिताः पाके मधुरा वीर्यतो हिमाः अल्पाभिष्यदिनो बद्धवर्चस्काः षष्टिकैः समाः कृष्णव्रीहिर्वरस्तेषां तस्मादल्पगुणाः परे","text":"vrīhayaḥ kathitāḥ pāke madhurā vīryato himāḥ alpābhiṣyadino baddhavarcaskāḥ ṣaṣṭikaiḥ samāḥ kṛṣṇavrīhirvarasteṣāṃ tasmādalpaguṇāḥ pare"},{"type":"verse","number":"22","sanskrit":"गर्भस्था एव ये पाकं यान्ति ते षष्टिका मताः","text":"garbhasthā eva ye pākaṃ yānti te ṣaṣṭikā matāḥ"},{"type":"verse","number":"23","sanskrit":"षष्टिकः शतपुष्पश्च प्रमोदकमुकुन्दकौ महाषष्टिक इत्याद्याः षष्टिकाः समुदाहृताः एतेऽपि व्रीहयः प्रोक्ता व्रीहिलक्षणदर्शनात्","text":"ṣaṣṭikaḥ śatapuṣpaśca pramodakamukundakau mahāṣaṣṭika ityādyāḥ ṣaṣṭikāḥ samudāhṛtāḥ ete'pi vrīhayaḥ proktā vrīhilakṣaṇadarśanāt"},{"type":"verse","number":"24","sanskrit":"षष्टिका मधुरा शीता लघवो बद्धवर्चसः वातपित्तप्रशमनाः शालिभिः सदृशा गुणैः","text":"ṣaṣṭikā madhurā śītā laghavo baddhavarcasaḥ vātapittapraśamanāḥ śālibhiḥ sadṛśā guṇaiḥ"},{"type":"verse","number":"25","sanskrit":"षष्टिका प्रवरा तेषां लघ्वी स्निग्धा त्रिदोषजित्","text":"ṣaṣṭikā pravarā teṣāṃ laghvī snigdhā tridoṣajit"},{"type":"verse","number":"26","sanskrit":"स्वाद्वी मृद्वी ग्राहिणी च बलदा ज्वरहारिणी रक्तशालिगुणैस्तुल्या ततः स्वल्पगुणाः परे","text":"svādvī mṛdvī grāhiṇī ca baladā jvarahāriṇī raktaśāliguṇaistulyā tataḥ svalpaguṇāḥ pare"},{"type":"verse","number":"27","sanskrit":"यवस्तु सितशूकः स्यान्निःशूकोऽतियवः स्मृतः तोक्यस्तद्वत्स हरितस्ततः स्वल्पश्च कीर्त्तितः","text":"yavastu sitaśūkaḥ syānniḥśūko'tiyavaḥ smṛtaḥ tokyastadvatsa haritastataḥ svalpaśca kīrttitaḥ"},{"type":"verse","number":"28","sanskrit":"यवः कषायो मधुरः शीतलो लेखनो मृदुः व्रणेषु तिलवत्पथ्यो रूक्षो मेधाऽग्निवर्धनः","text":"yavaḥ kaṣāyo madhuraḥ śītalo lekhano mṛduḥ vraṇeṣu tilavatpathyo rūkṣo medhā'gnivardhanaḥ"},{"type":"verse","number":"29","sanskrit":"कटुपाकोऽनभिष्यन्दी स्वर्यो बलकरो गुरुः बहुवातमलो वर्णस्थैर्यकारी च पिच्छिलः","text":"kaṭupāko'nabhiṣyandī svaryo balakaro guruḥ bahuvātamalo varṇasthairyakārī ca picchilaḥ"},{"type":"verse","number":"30","sanskrit":"अस्मादतियवो न्यूनस्तोक्यो न्यूनतरस्ततः ९.","text":"asmādatiyavo nyūnastokyo nyūnatarastataḥ 9."},{"type":"verse","number":"31","sanskrit":"गोधूमः सुमनोऽपि स्यात्त्रिविधः स च कीर्त्तितः महागोधूम इत्याख्यः पश्चाद्देशात्समागतः","text":"godhūmaḥ sumano'pi syāttrividhaḥ sa ca kīrttitaḥ mahāgodhūma ityākhyaḥ paścāddeśātsamāgataḥ"},{"type":"verse","number":"32","sanskrit":"मधूली तु ततः किञ्चिदल्पा सा मध्यदेशजा निः शूको दीर्घगोधूमः क्वचिन्नन्दीमुखाभिघः","text":"madhūlī tu tataḥ kiñcidalpā sā madhyadeśajā niḥ śūko dīrghagodhūmaḥ kvacinnandīmukhābhighaḥ"},{"type":"verse","number":"33","sanskrit":"गोधूमः मधुरः शीतो वातपित्तहरो गुरुः कफशुक्रप्रदो बल्यः स्निग्धः सन्धानकृत्सरः","text":"godhūmaḥ madhuraḥ śīto vātapittaharo guruḥ kaphaśukraprado balyaḥ snigdhaḥ sandhānakṛtsaraḥ"},{"type":"verse","number":"34","sanskrit":"जीवनो बृंहणो वर्ण्यो व्रण्यो रुच्यः स्थिरत्वकृत्","text":"jīvano bṛṃhaṇo varṇyo vraṇyo rucyaḥ sthiratvakṛt"},{"type":"verse","number":"35","sanskrit":"मधूली शीतला स्निग्धा पित्तघ्नी मधुरा लघुः शुक्रला वृंहणी पथ्या तद्वन्नन्दीमुखः स्मृतः","text":"madhūlī śītalā snigdhā pittaghnī madhurā laghuḥ śukralā vṛṃhaṇī pathyā tadvannandīmukhaḥ smṛtaḥ"},{"type":"verse","number":"36","sanskrit":"शमीजाः शिम्बिजाः शिम्बीभवाः सूप्याश्च वैदलाः","text":"śamījāḥ śimbijāḥ śimbībhavāḥ sūpyāśca vaidalāḥ"},{"type":"verse","number":"37","sanskrit":"वैदला मधुरा रूक्षाः कषायाः कटुपाकिनः वातलाः कफपित्तघ्ना बद्धमूत्रमला हिमाः ऋते मुद्गमसूराभ्यामन्ये त्वाध्मानकारिणः","text":"vaidalā madhurā rūkṣāḥ kaṣāyāḥ kaṭupākinaḥ vātalāḥ kaphapittaghnā baddhamūtramalā himāḥ ṛte mudgamasūrābhyāmanye tvādhmānakāriṇaḥ"},{"type":"verse","number":"38","sanskrit":"मुद्गो रूक्षो लघुर्ग्राही कफपित्तहरो हिमः स्वादुरल्पानिलो नेत्र्! यो ज्वरघ्नो वनजस्तथा","text":"mudgo rūkṣo laghurgrāhī kaphapittaharo himaḥ svāduralpānilo netr! yo jvaraghno vanajastathā"},{"type":"verse","number":"39","sanskrit":"मुद्गो बहुविधः श्यामो हरितः पीतकस्तथा श्वेतो रक्तश्च तेषान्तु पूर्वः पूर्वो लघुः स्मृतः","text":"mudgo bahuvidhaḥ śyāmo haritaḥ pītakastathā śveto raktaśca teṣāntu pūrvaḥ pūrvo laghuḥ smṛtaḥ"},{"type":"verse","number":"40","sanskrit":"सुश्रुतेन पुनः प्रोक्तो हरितः प्रवरो गुणैः चरकादिभिरप्युक्त एष एव गुणाधिकः ९.","text":"suśrutena punaḥ prokto haritaḥ pravaro guṇaiḥ carakādibhirapyukta eṣa eva guṇādhikaḥ 9."},{"type":"verse","number":"41","sanskrit":"माषो गुरुः स्वादुपाकः स्निग्धो रुच्योऽनिलापहः स्रंसनस्तर्पणो बल्यः शुक्रलो वृंहणः परः","text":"māṣo guruḥ svādupākaḥ snigdho rucyo'nilāpahaḥ sraṃsanastarpaṇo balyaḥ śukralo vṛṃhaṇaḥ paraḥ"},{"type":"verse","number":"42","sanskrit":"भिन्नमूत्रमलः स्तन्यो मेदःपित्तकफप्रदः गुदकीलार्दितश्वासपक्तिशूलानि नाशयेत्","text":"bhinnamūtramalaḥ stanyo medaḥpittakaphapradaḥ gudakīlārditaśvāsapaktiśūlāni nāśayet"},{"type":"verse","number":"43","sanskrit":"कफपित्तकरा माषाः कफपित्तकरं दधि कफपित्तकरा मत्स्या वृन्ताकं कफपित्तकृत्","text":"kaphapittakarā māṣāḥ kaphapittakaraṃ dadhi kaphapittakarā matsyā vṛntākaṃ kaphapittakṛt"},{"type":"verse","number":"44","sanskrit":"राजमाषो महामाषश्चपलश्च बलः स्मृतः राजमाषो गुरुः स्वादुस्तुवरस्तर्पणः सरः","text":"rājamāṣo mahāmāṣaścapalaśca balaḥ smṛtaḥ rājamāṣo guruḥ svādustuvarastarpaṇaḥ saraḥ"},{"type":"verse","number":"45","sanskrit":"रूक्षो वातकरो रुच्यः स्तन्यो भूरिबलप्रदः श्वेतो रक्तस्तथा कृष्णस्त्रिविधः स प्रकीर्त्तितः यो महांस्तेषु भवति स एवोक्तो गुणाधिकः","text":"rūkṣo vātakaro rucyaḥ stanyo bhūribalapradaḥ śveto raktastathā kṛṣṇastrividhaḥ sa prakīrttitaḥ yo mahāṃsteṣu bhavati sa evokto guṇādhikaḥ"},{"type":"verse","number":"46","sanskrit":"निष्पावो राजशिम्बिः स्याद्वल्लकः श्वेतशिम्बिकः निष्पावो मधुरो रूक्षो विपाकेऽम्लो गुरुः सरः","text":"niṣpāvo rājaśimbiḥ syādvallakaḥ śvetaśimbikaḥ niṣpāvo madhuro rūkṣo vipāke'mlo guruḥ saraḥ"},{"type":"verse","number":"47","sanskrit":"कषायः स्तन्यपित्तास्रमूत्रवातविबन्धकृत् विदाह्युष्णो विषश्लेष्मशोथहृच्छुक्रनाशनः","text":"kaṣāyaḥ stanyapittāsramūtravātavibandhakṛt vidāhyuṣṇo viṣaśleṣmaśothahṛcchukranāśanaḥ"},{"type":"verse","number":"48","sanskrit":"मकुष्ठो वनमुद्गः स्यान्मकुष्ठकमुकुष्ठकौ","text":"makuṣṭho vanamudgaḥ syānmakuṣṭhakamukuṣṭhakau"},{"type":"verse","number":"49","sanskrit":"मकुष्ठो वातलो ग्राही कफपित्तहरो लघुः वह्निजिन्मधुरः पाके कृमिकृज्ज्वरनाशनः","text":"makuṣṭho vātalo grāhī kaphapittaharo laghuḥ vahnijinmadhuraḥ pāke kṛmikṛjjvaranāśanaḥ"},{"type":"verse","number":"50","sanskrit":"मङ्गल्यको मसूरः स्यान्मङ्गल्या च मसूरिका मसूरो मधुरः पाके संग्राही शीतलो लघुः कफपित्तास्रजिद्रू क्षो वातलो ज्वरनाशनः ९.","text":"maṅgalyako masūraḥ syānmaṅgalyā ca masūrikā masūro madhuraḥ pāke saṃgrāhī śītalo laghuḥ kaphapittāsrajidrū kṣo vātalo jvaranāśanaḥ 9."},{"type":"verse","number":"51","sanskrit":"आढकी तुवरी चापि सा प्रोक्ता शणपुष्पिका","text":"āḍhakī tuvarī cāpi sā proktā śaṇapuṣpikā"},{"type":"verse","number":"52","sanskrit":"आढकी तुवरा रूक्षा मधुरा शीतला लघुः ग्राहिणी वातजननी वर्ण्या पित्तकफास्रजित्","text":"āḍhakī tuvarā rūkṣā madhurā śītalā laghuḥ grāhiṇī vātajananī varṇyā pittakaphāsrajit"},{"type":"verse","number":"53","sanskrit":"चणको हरिमन्थः स्यात्सकलप्रिय इत्यपि चणकः शीतलो रूक्षः पित्तरक्तकफापहः लघुः कषायो विष्टम्भी वातलो ज्वरनाशनः","text":"caṇako harimanthaḥ syātsakalapriya ityapi caṇakaḥ śītalo rūkṣaḥ pittaraktakaphāpahaḥ laghuḥ kaṣāyo viṣṭambhī vātalo jvaranāśanaḥ"},{"type":"verse","number":"54","sanskrit":"स चाङ्गारेण सम्भृष्टस्तैलभृष्टश्च तद्गुणः आर्द्र भृष्टो बलकरो रोचनश्च प्रकीर्त्तितः","text":"sa cāṅgāreṇa sambhṛṣṭastailabhṛṣṭaśca tadguṇaḥ ārdra bhṛṣṭo balakaro rocanaśca prakīrttitaḥ"},{"type":"verse","number":"55","sanskrit":"शुष्कभृष्टोऽतिरूक्षश्च वातकुष्ठप्रकोपणः स्विन्नः पित्तकफौ हन्यात् सूपः क्षोभकरो मतः","text":"śuṣkabhṛṣṭo'tirūkṣaśca vātakuṣṭhaprakopaṇaḥ svinnaḥ pittakaphau hanyāt sūpaḥ kṣobhakaro mataḥ"},{"type":"verse","number":"56","sanskrit":"आद्रो र्!ऽतिकोमलो रुच्यः पित्तशुक्रहरो हिमः कषायो वातलो ग्राही कफपित्तहरो लघुः","text":"ādro r!'tikomalo rucyaḥ pittaśukraharo himaḥ kaṣāyo vātalo grāhī kaphapittaharo laghuḥ"},{"type":"verse","number":"57","sanskrit":"कलायो वर्त्तुलः प्रोक्तः सतीनश्च हरेणुकः कलायो मधुरः स्वादुः पाके रूक्षश्च शीतलः","text":"kalāyo varttulaḥ proktaḥ satīnaśca hareṇukaḥ kalāyo madhuraḥ svāduḥ pāke rūkṣaśca śītalaḥ"},{"type":"verse","number":"58","sanskrit":"त्रिपुटः खण्डिकोऽपि स्यात्कथ्यन्ते तद्गुणा अथ त्रिपुटो मधुरस्तिक्तस्तुवरो रूक्षणो भृशम्","text":"tripuṭaḥ khaṇḍiko'pi syātkathyante tadguṇā atha tripuṭo madhurastiktastuvaro rūkṣaṇo bhṛśam"},{"type":"verse","number":"59","sanskrit":"कफपित्तहरो रुच्यो ग्राहकः शीतलस्तथा किन्तु खञ्जत्वपङ्गुत्वकारी वातातिकोपनः","text":"kaphapittaharo rucyo grāhakaḥ śītalastathā kintu khañjatvapaṅgutvakārī vātātikopanaḥ"},{"type":"verse","number":"60","sanskrit":"कुलत्थिका कुलत्थश्च कथ्यन्ते तद्गुणा अथ ९.","text":"kulatthikā kulatthaśca kathyante tadguṇā atha 9."},{"type":"verse","number":"61","sanskrit":"कुलत्थः कटुकः पाके कषायः पित्तरक्तकृत् लघुर्विदाही वीर्योष्णः श्वासकासकफानिलान्","text":"kulatthaḥ kaṭukaḥ pāke kaṣāyaḥ pittaraktakṛt laghurvidāhī vīryoṣṇaḥ śvāsakāsakaphānilān"},{"type":"verse","number":"62","sanskrit":"हन्ति हिक्काऽश्मरीशुक्रदाहानाहान् सपीनसान् स्वेदसंग्राहको मेदोज्वरकृमिहरः सरः","text":"hanti hikkā'śmarīśukradāhānāhān sapīnasān svedasaṃgrāhako medojvarakṛmiharaḥ saraḥ"},{"type":"verse","number":"63","sanskrit":"तिलः कृष्णः सितो रक्तः स वन्योऽल्पतिलःस्मृतः तिलो रसे कटुस्तिक्तो मधुरस्तुवरो गुरुः","text":"tilaḥ kṛṣṇaḥ sito raktaḥ sa vanyo'lpatilaḥsmṛtaḥ tilo rase kaṭustikto madhurastuvaro guruḥ"},{"type":"verse","number":"64","sanskrit":"विपाके कटुकः स्वादुः स्निग्धोष्णः कफपित्तनुत् बल्यः केश्यो हिमस्पर्शस्त्वच्यः स्तन्यो व्रणे हितः","text":"vipāke kaṭukaḥ svāduḥ snigdhoṣṇaḥ kaphapittanut balyaḥ keśyo himasparśastvacyaḥ stanyo vraṇe hitaḥ"},{"type":"verse","number":"65","sanskrit":"दन्त्योऽल्पमूत्रकृद् ग्राही वातघ्नोऽग्निमतिप्रदः कृष्णः श्रेष्ठतमस्तेषु शुक्रलो मध्यमः सितः अन्ये हीनतराः प्रोक्तास्तज्ज्ञै रक्तादयस्तिलाः","text":"dantyo'lpamūtrakṛd grāhī vātaghno'gnimatipradaḥ kṛṣṇaḥ śreṣṭhatamasteṣu śukralo madhyamaḥ sitaḥ anye hīnatarāḥ proktāstajjñai raktādayastilāḥ"},{"type":"verse","number":"66","sanskrit":"अतसी नीलपुष्पी च पार्वती स्यादुमा क्षुमा","text":"atasī nīlapuṣpī ca pārvatī syādumā kṣumā"},{"type":"verse","number":"67","sanskrit":"अतसी मधुरा तिक्ता स्निग्धा पाके कटुर्गुरुः उष्णा दृक्छुक्रवातघ्नी कफपित्तविनाशिनी","text":"atasī madhurā tiktā snigdhā pāke kaṭurguruḥ uṣṇā dṛkchukravātaghnī kaphapittavināśinī"},{"type":"verse","number":"68","sanskrit":"तुवरी ग्राहिणी प्रोक्ता लघ्वी कफविषास्रजित् तीक्ष्णोष्णा वह्निदा कण्डूकुष्ठकोष्ठकृमिप्रणुत्","text":"tuvarī grāhiṇī proktā laghvī kaphaviṣāsrajit tīkṣṇoṣṇā vahnidā kaṇḍūkuṣṭhakoṣṭhakṛmipraṇut"},{"type":"verse","number":"69","sanskrit":"सर्षपः कटुकः स्नेहस्तुन्तुभश्च कदम्बकः गौरस्तु सर्षपः प्राज्ञैः सिद्धार्थ इति कथ्यते","text":"sarṣapaḥ kaṭukaḥ snehastuntubhaśca kadambakaḥ gaurastu sarṣapaḥ prājñaiḥ siddhārtha iti kathyate"},{"type":"verse","number":"70","sanskrit":"सर्षपस्तु रसे पाके कटुः स्निग्धः सतिक्तकः तीक्ष्णोष्णः कफवातघ्नो रक्तपित्ताग्निवर्धनः ९.","text":"sarṣapastu rase pāke kaṭuḥ snigdhaḥ satiktakaḥ tīkṣṇoṣṇaḥ kaphavātaghno raktapittāgnivardhanaḥ 9."},{"type":"verse","number":"71","sanskrit":"रक्षोहरो जयेत्कण्डूं कुष्ठकोष्ठकृमिग्रहान् यथा रक्तस्तथा गौरः किन्तु गौरो वरो मतः","text":"rakṣoharo jayetkaṇḍūṃ kuṣṭhakoṣṭhakṛmigrahān yathā raktastathā gauraḥ kintu gauro varo mataḥ"},{"type":"verse","number":"72","sanskrit":"राजीतु राजिका तीक्ष्णगन्धा क्षुज्जनिकाऽसुरी क्षवः क्षुताभिजनकः कृष्णीका कृष्णसर्षपः","text":"rājītu rājikā tīkṣṇagandhā kṣujjanikā'surī kṣavaḥ kṣutābhijanakaḥ kṛṣṇīkā kṛṣṇasarṣapaḥ"},{"type":"verse","number":"73","sanskrit":"राजिका कफपित्तघ्नी तीक्ष्णोष्णा रक्तपित्तकृत् किञ्चित् रूक्षाऽग्निदा कण्डूकुष्ठकोष्ठकृमीन्हरेत् अतितीक्ष्णा विशेषेण तद्वत्कृष्णाऽपि राजिका","text":"rājikā kaphapittaghnī tīkṣṇoṣṇā raktapittakṛt kiñcit rūkṣā'gnidā kaṇḍūkuṣṭhakoṣṭhakṛmīnharet atitīkṣṇā viśeṣeṇa tadvatkṛṣṇā'pi rājikā"},{"type":"verse","number":"74","sanskrit":"क्षुद्र धान्यं कुधान्यं च तृणधान्यमिति स्मृतम् क्षुद्र धान्यमनुष्णं स्यात्कषायं लघु लेखनम्","text":"kṣudra dhānyaṃ kudhānyaṃ ca tṛṇadhānyamiti smṛtam kṣudra dhānyamanuṣṇaṃ syātkaṣāyaṃ laghu lekhanam"},{"type":"verse","number":"75","sanskrit":"मधुरं कटुकं पाके रूक्षं च क्लेदशोषकम् वातकृद् बद्धविट्कं च पित्तरक्तकफापहम्","text":"madhuraṃ kaṭukaṃ pāke rūkṣaṃ ca kledaśoṣakam vātakṛd baddhaviṭkaṃ ca pittaraktakaphāpaham"},{"type":"verse","number":"76","sanskrit":"स्त्रियां कङ्गुप्रियङ्गु द्वे कृष्णारक्ता सिता तथा पीता चतुर्विधा कङ्गुस्तासां पीता वरा स्मृता","text":"striyāṃ kaṅgupriyaṅgu dve kṛṣṇāraktā sitā tathā pītā caturvidhā kaṅgustāsāṃ pītā varā smṛtā"},{"type":"verse","number":"77","sanskrit":"कङ्गुस्तु भग्नसन्धानवातकृद् बृंहणी गुरुः रूक्षा श्लेष्महराऽतीव वाजिनां गुणकृद् भृशम्","text":"kaṅgustu bhagnasandhānavātakṛd bṛṃhaṇī guruḥ rūkṣā śleṣmaharā'tīva vājināṃ guṇakṛd bhṛśam"},{"type":"verse","number":"78","sanskrit":"चीनाकः काककङ्गुश्च सुश्लक्ष्णः श्लक्ष्णकः स्मृतः चीनाकः कङ्गुभेदोऽस्ति स ज्ञेयः कङ्गुवद् गुणैः","text":"cīnākaḥ kākakaṅguśca suślakṣṇaḥ ślakṣṇakaḥ smṛtaḥ cīnākaḥ kaṅgubhedo'sti sa jñeyaḥ kaṅguvad guṇaiḥ"},{"type":"verse","number":"79","sanskrit":"श्यामाकः श्यामकः श्यामास्त्रिबीजः स्यादविप्रियः सुकुमारो राजधान्यं तृणबीजोत्तमश्च सः श्यामाकः शोषणो रूक्षो वातलः कफपित्तहृत्","text":"śyāmākaḥ śyāmakaḥ śyāmāstribījaḥ syādavipriyaḥ sukumāro rājadhānyaṃ tṛṇabījottamaśca saḥ śyāmākaḥ śoṣaṇo rūkṣo vātalaḥ kaphapittahṛt"},{"type":"verse","number":"80","sanskrit":"कोद्र वः कोरदूषः स्यादुद्दालो वनकोद्र वः कोद्र वो वातलो ग्राही हिमः पित्तकफापहः उद्दालस्तु भवेदुष्णो ग्राही वातकरो भृशम् ९.","text":"kodra vaḥ koradūṣaḥ syāduddālo vanakodra vaḥ kodra vo vātalo grāhī himaḥ pittakaphāpahaḥ uddālastu bhaveduṣṇo grāhī vātakaro bhṛśam 9."},{"type":"verse","number":"81","sanskrit":"चारुकः शरबीजः स्यात्कथ्यन्ते तद्गुणा अथ चारुको मधुरो रूक्षो रक्तपित्तकफापहः शीतलो लघुवृष्यश्च कषायो वातकोपनः","text":"cārukaḥ śarabījaḥ syātkathyante tadguṇā atha cāruko madhuro rūkṣo raktapittakaphāpahaḥ śītalo laghuvṛṣyaśca kaṣāyo vātakopanaḥ"},{"type":"verse","number":"82","sanskrit":"यवा वंशभवा रूक्षाः कषायाः कटुपाकिनः बद्धमूत्राः कफघ्नाश्च वातपित्तकराः सराः","text":"yavā vaṃśabhavā rūkṣāḥ kaṣāyāḥ kaṭupākinaḥ baddhamūtrāḥ kaphaghnāśca vātapittakarāḥ sarāḥ"},{"type":"verse","number":"83","sanskrit":"कुसुम्भबीजं वरटा सैव प्रोक्ता वरट्टिका","text":"kusumbhabījaṃ varaṭā saiva proktā varaṭṭikā"},{"type":"verse","number":"84","sanskrit":"वरटा मधुरा स्निग्धा रक्तपित्तकफापहा कषाया शीतला गुर्वी स्यादवृष्याऽनिलापहा","text":"varaṭā madhurā snigdhā raktapittakaphāpahā kaṣāyā śītalā gurvī syādavṛṣyā'nilāpahā"},{"type":"verse","number":"85","sanskrit":"गवेधुका तु विद्वद्भिर्गवेधुः कथिता स्त्रियाम् गवेधुः कटुका स्वाद्वी कार्श्यकृत्कफनाशिनी","text":"gavedhukā tu vidvadbhirgavedhuḥ kathitā striyām gavedhuḥ kaṭukā svādvī kārśyakṛtkaphanāśinī"},{"type":"verse","number":"86","sanskrit":"प्रसाधिका तु नीवारस्तृणान्नमिति च स्मृतम् नीवारः शीतलो ग्राही पित्तघ्नः कफवातकृत्","text":"prasādhikā tu nīvārastṛṇānnamiti ca smṛtam nīvāraḥ śītalo grāhī pittaghnaḥ kaphavātakṛt"},{"type":"verse","number":"87","sanskrit":"यावनालो हिमः स्वादुर्लोहितः श्लेष्मपित्तजित् अवृष्यस्तुवरो रूक्षः क्लेदकृत्कथितो लघुः","text":"yāvanālo himaḥ svādurlohitaḥ śleṣmapittajit avṛṣyastuvaro rūkṣaḥ kledakṛtkathito laghuḥ"},{"type":"verse","number":"88","sanskrit":"धान्यं सर्वं नवं स्वादु गुरु श्लेष्मकरं स्मृतम् तत्तु वर्षोषितं पथ्यं यतो लघुतरं हि तत्","text":"dhānyaṃ sarvaṃ navaṃ svādu guru śleṣmakaraṃ smṛtam tattu varṣoṣitaṃ pathyaṃ yato laghutaraṃ hi tat"},{"type":"verse","number":"89","sanskrit":"वर्षोषितं सर्वधान्यं गौरवं परिमुञ्चति न तु त्यजति वीर्यं स्वं क्रमान्मुञ्चत्यतः परम्","text":"varṣoṣitaṃ sarvadhānyaṃ gauravaṃ parimuñcati na tu tyajati vīryaṃ svaṃ kramānmuñcatyataḥ param"},{"type":"verse","number":"90","sanskrit":"एतेषु यवगोधूमतिलमाषा नवा हिताः पुराणा विरसा रूक्षा न तथा गुणकारिणः ९.","text":"eteṣu yavagodhūmatilamāṣā navā hitāḥ purāṇā virasā rūkṣā na tathā guṇakāriṇaḥ 9."},{"type":"verse","number":"9","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे नवमो धान्यवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe navamo dhānyavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":9,"lang":"sa","content":[{"type":"heading","heading":"śāka-варга — овощи и зелень"},{"type":"verse","number":"1","sanskrit":"पत्रं पुष्पं फलं नालं कन्दं संस्वेदजं तथा शाकं षड्विधमुदृष्टं गुरुं विद्याद्यथोत्तरम्","text":"patraṃ puṣpaṃ phalaṃ nālaṃ kandaṃ saṃsvedajaṃ tathā śākaṃ ṣaḍvidhamudṛṣṭaṃ guruṃ vidyādyathottaram"},{"type":"verse","number":"2","sanskrit":"प्रायः शाकानि सर्वाणि विष्टम्भीनि गुरूणि च रूक्षाणि बहुवर्चांसि सृष्टविण्मारुतानि च","text":"prāyaḥ śākāni sarvāṇi viṣṭambhīni gurūṇi ca rūkṣāṇi bahuvarcāṃsi sṛṣṭaviṇmārutāni ca"},{"type":"verse","number":"3","sanskrit":"शाकं भिनत्ति वपुरस्थि निहन्ति नेत्रं वर्णं विनाशयति रक्तमथापि शुक्रम् प्रज्ञाक्षयं च कुरुते पलितं च नूनं हन्ति स्मृतिं गतिमिति प्रवदन्ति तज्ज्ञाः","text":"śākaṃ bhinatti vapurasthi nihanti netraṃ varṇaṃ vināśayati raktamathāpi śukram prajñākṣayaṃ ca kurute palitaṃ ca nūnaṃ hanti smṛtiṃ gatimiti pravadanti tajjñāḥ"},{"type":"verse","number":"4","sanskrit":"शाकेषु सर्वेषु वसन्ति रोगास्ते हेतवो देहविनाशनाय तस्माद् बुधः शाकविवर्जनं तु कुर्यात्तथाऽम्लेषु स एव दोषः","text":"śākeṣu sarveṣu vasanti rogāste hetavo dehavināśanāya tasmād budhaḥ śākavivarjanaṃ tu kuryāttathā'mleṣu sa eva doṣaḥ"},{"type":"verse","number":"5","sanskrit":"वास्तूकं वास्तुकं च स्यात्क्षारपत्रं च शाकराट् तदेव तु बृहत्पत्रं रक्तं स्याद्गौडवास्तुकम्","text":"vāstūkaṃ vāstukaṃ ca syātkṣārapatraṃ ca śākarāṭ tadeva tu bṛhatpatraṃ raktaṃ syādgauḍavāstukam"},{"type":"verse","number":"6","sanskrit":"प्रायशो यवमध्ये स्याद्यवशाकमतः स्मृतम् वास्तूकद्वितयं स्वादु क्षारं पाके कटूदितम्","text":"prāyaśo yavamadhye syādyavaśākamataḥ smṛtam vāstūkadvitayaṃ svādu kṣāraṃ pāke kaṭūditam"},{"type":"verse","number":"7","sanskrit":"दीपनं पाचनं रुच्यं लघु शुक्रबलप्रदम् सरं प्लीहास्रपित्तार्शः कृमिदोषत्रयापहम्","text":"dīpanaṃ pācanaṃ rucyaṃ laghu śukrabalapradam saraṃ plīhāsrapittārśaḥ kṛmidoṣatrayāpaham"},{"type":"verse","number":"8","sanskrit":"पोतक्युपोदिका सा तु मालवाऽमृतवल्लरी पोतकी शीतला स्निग्धा श्लेष्मला वातपित्तनुत्","text":"potakyupodikā sā tu mālavā'mṛtavallarī potakī śītalā snigdhā śleṣmalā vātapittanut"},{"type":"verse","number":"9","sanskrit":"अकण्ठ्या पिच्छिला निद्रा शुक्रदा रक्त पित्तजित् बलदा रुचिकृत्पथ्या बृंहणी तृप्तिकारिणी","text":"akaṇṭhyā picchilā nidrā śukradā rakta pittajit baladā rucikṛtpathyā bṛṃhaṇī tṛptikāriṇī"},{"type":"verse","number":"10","sanskrit":"मारिषो वाष्पको मार्ष श्वेतो रक्तश्च संस्मृतः मारिषो मधुरः शीतो विष्टम्भी पित्तनुद् गुरुः १०.","text":"māriṣo vāṣpako mārṣa śveto raktaśca saṃsmṛtaḥ māriṣo madhuraḥ śīto viṣṭambhī pittanud guruḥ 10."},{"type":"verse","number":"11","sanskrit":"वातश्लेष्मकरो रक्तपित्तनुद् विषमाग्निजित् रक्तमार्षो गुरुर्नाति सक्षारो मधुरः सरः श्लेष्मलः कटुकः पाके स्वल्पदोष उदीरितः","text":"vātaśleṣmakaro raktapittanud viṣamāgnijit raktamārṣo gururnāti sakṣāro madhuraḥ saraḥ śleṣmalaḥ kaṭukaḥ pāke svalpadoṣa udīritaḥ"},{"type":"verse","number":"12","sanskrit":"तण्डुलीयो मेघनादः काण्डेरस्तण्डुलेरकः भण्डीरस्तण्डुलीबीजो विषघ्नश्चाल्पमारिषः","text":"taṇḍulīyo meghanādaḥ kāṇḍerastaṇḍulerakaḥ bhaṇḍīrastaṇḍulībījo viṣaghnaścālpamāriṣaḥ"},{"type":"verse","number":"13","sanskrit":"तण्डुलीयो लघुः शीतो रूक्षः पित्तकफास्रजित् सृष्टमूत्रमलो रुच्यो दीपनो विषहारकः","text":"taṇḍulīyo laghuḥ śīto rūkṣaḥ pittakaphāsrajit sṛṣṭamūtramalo rucyo dīpano viṣahārakaḥ"},{"type":"verse","number":"14","sanskrit":"पानीयतण्डुलीयं तु कञ्चटं समुदाहृतम् कञ्चटं तिक्तकं रक्तपित्तानिलहरं लघु","text":"pānīyataṇḍulīyaṃ tu kañcaṭaṃ samudāhṛtam kañcaṭaṃ tiktakaṃ raktapittānilaharaṃ laghu"},{"type":"verse","number":"15","sanskrit":"पलक्या वास्तुकाकारा छुरिका चीरितच्छदा","text":"palakyā vāstukākārā churikā cīritacchadā"},{"type":"verse","number":"16","sanskrit":"पलक्या वातला शीता श्मेष्मला भेदिनी गुरुः विष्टम्भिनी मदश्वासपित्तरक्तकफापहा","text":"palakyā vātalā śītā śmeṣmalā bhedinī guruḥ viṣṭambhinī madaśvāsapittaraktakaphāpahā"},{"type":"verse","number":"17","sanskrit":"नाडिकं कालशाकं च श्राद्धशाकं च कालकम् कालशाकं सरं रुच्यं वातकृत्कफशोथहृत् बल्यं रुचिकरं मेध्यं रक्तपित्तहरं हिमम्","text":"nāḍikaṃ kālaśākaṃ ca śrāddhaśākaṃ ca kālakam kālaśākaṃ saraṃ rucyaṃ vātakṛtkaphaśothahṛt balyaṃ rucikaraṃ medhyaṃ raktapittaharaṃ himam"},{"type":"verse","number":"18","sanskrit":"पट्टशाकस्तु नाडीको नाडीशाकश्च स स्मृतः नाडीको रक्तपित्तघ्नो विष्टम्भो वातकोपनः","text":"paṭṭaśākastu nāḍīko nāḍīśākaśca sa smṛtaḥ nāḍīko raktapittaghno viṣṭambho vātakopanaḥ"},{"type":"verse","number":"19","sanskrit":"कलम्बी शतपर्वी च कथ्यन्ते तद्गुणा अथ कलम्बी स्तन्यदा प्रोक्ता मधुरा शुक्रकारिणी","text":"kalambī śataparvī ca kathyante tadguṇā atha kalambī stanyadā proktā madhurā śukrakāriṇī"},{"type":"verse","number":"20","sanskrit":"लोणालोणी च कथिता वृहल्लोणी तु घोटिका लोणी रूक्षा स्मृता गुर्वी वातश्लेष्महरी पटुः १०.","text":"loṇāloṇī ca kathitā vṛhalloṇī tu ghoṭikā loṇī rūkṣā smṛtā gurvī vātaśleṣmaharī paṭuḥ 10."},{"type":"verse","number":"21","sanskrit":"अर्शोघ्नी दीपनी चाम्ला मन्दाग्निविषनाशिनी घोटिकाऽम्ला सराचोष्णा वातकृत्कफपित्तहृत्","text":"arśoghnī dīpanī cāmlā mandāgniviṣanāśinī ghoṭikā'mlā sarācoṣṇā vātakṛtkaphapittahṛt"},{"type":"verse","number":"22","sanskrit":"वाग्दोषव्रणगुल्मघ्नी श्वासकासप्रमेहनुत् शोथे लोचनरोगे च हिता तज्ज्ञैरुदाहृता","text":"vāgdoṣavraṇagulmaghnī śvāsakāsapramehanut śothe locanaroge ca hitā tajjñairudāhṛtā"},{"type":"verse","number":"23","sanskrit":"चाङ्गेरी चुक्रिका दन्तशठाम्बष्ठाऽम्ललोणिका अश्मन्तकस्तु शफरी कुशली चाम्लपत्रकः","text":"cāṅgerī cukrikā dantaśaṭhāmbaṣṭhā'mlaloṇikā aśmantakastu śapharī kuśalī cāmlapatrakaḥ"},{"type":"verse","number":"24","sanskrit":"चाङ्गेरी दीपनी रुच्या रुक्षोष्णा कफवातनुत् पित्तलाऽम्ला ग्रहण्यर्शः कुष्ठातीसारनाशिनी","text":"cāṅgerī dīpanī rucyā rukṣoṣṇā kaphavātanut pittalā'mlā grahaṇyarśaḥ kuṣṭhātīsāranāśinī"},{"type":"verse","number":"25","sanskrit":"चुक्रिका स्यात्तु पत्राम्ला रोचनी शतवेधिनी","text":"cukrikā syāttu patrāmlā rocanī śatavedhinī"},{"type":"verse","number":"26","sanskrit":"चुक्रा त्वम्लतरा स्वाद्वी वातघ्नी कफपित्तकृत् रुच्या लघुतरा पाके वृन्ताकेनातिरोचनी","text":"cukrā tvamlatarā svādvī vātaghnī kaphapittakṛt rucyā laghutarā pāke vṛntākenātirocanī"},{"type":"verse","number":"27","sanskrit":"चिञ्चा चञ्चुश्चञ्चुकी च दीर्घपत्रा सतिक्तका चञ्चुः शीता सरा रुच्या स्वाद्वी दोषत्रयापहा धातुपुष्टिकरी बल्या मेध्या पिच्छिलका स्मृता","text":"ciñcā cañcuścañcukī ca dīrghapatrā satiktakā cañcuḥ śītā sarā rucyā svādvī doṣatrayāpahā dhātupuṣṭikarī balyā medhyā picchilakā smṛtā"},{"type":"verse","number":"28","sanskrit":"ब्राह्मी शङ्खधराऽचारी मत्स्याक्षी हिलमोचिका शोथं कुष्ठं कफं पित्तं हरते हिलमोचिका","text":"brāhmī śaṅkhadharā'cārī matsyākṣī hilamocikā śothaṃ kuṣṭhaṃ kaphaṃ pittaṃ harate hilamocikā"},{"type":"verse","number":"29","sanskrit":"शितिवारः शितिवरः स्वस्तिकः सुनिषण्णकः श्रीवारकः सूचिपत्रः पर्णकः कुक्कुटः शिखी","text":"śitivāraḥ śitivaraḥ svastikaḥ suniṣaṇṇakaḥ śrīvārakaḥ sūcipatraḥ parṇakaḥ kukkuṭaḥ śikhī"},{"type":"verse","number":"30","sanskrit":"चाङ्गेरीसदृशः पत्रैश्चतुर्दल इतीरितः शाको जलान्विते देशे चतुष्पत्रीति चोच्यते १०.","text":"cāṅgerīsadṛśaḥ patraiścaturdala itīritaḥ śāko jalānvite deśe catuṣpatrīti cocyate 10."},{"type":"verse","number":"31","sanskrit":"सुनिषण्णो हिमो ग्राही मेदोदोषत्रयापहः","text":"suniṣaṇṇo himo grāhī medodoṣatrayāpahaḥ"},{"type":"verse","number":"32","sanskrit":"अविदाही लघुः स्वादुः कषायो रूक्षदीपनः वृष्यो रुच्योज्वरश्वासमेहकुष्ठभ्रम प्रणुत्","text":"avidāhī laghuḥ svāduḥ kaṣāyo rūkṣadīpanaḥ vṛṣyo rucyojvaraśvāsamehakuṣṭhabhrama praṇut"},{"type":"verse","number":"33","sanskrit":"पाचनं लघु रुच्योष्णं पत्रं मूलकजं नवम् स्नेहसिद्धं त्रिदोषघ्नमसिद्धं कफपित्तकृत्","text":"pācanaṃ laghu rucyoṣṇaṃ patraṃ mūlakajaṃ navam snehasiddhaṃ tridoṣaghnamasiddhaṃ kaphapittakṛt"},{"type":"verse","number":"34","sanskrit":"द्रो णपुष्पीदलं स्वादु रूक्षं गुरु च पित्तकृत् भेदनं कामलाशोथमेहज्वरहरं कटु","text":"dro ṇapuṣpīdalaṃ svādu rūkṣaṃ guru ca pittakṛt bhedanaṃ kāmalāśothamehajvaraharaṃ kaṭu"},{"type":"verse","number":"35","sanskrit":"यवानीशाकमाग्नेयं रुच्यं वातकफप्रणुत् उष्णं कटु च तिक्तं च पित्तलं लघु शूलहृत्","text":"yavānīśākamāgneyaṃ rucyaṃ vātakaphapraṇut uṣṇaṃ kaṭu ca tiktaṃ ca pittalaṃ laghu śūlahṛt"},{"type":"verse","number":"36","sanskrit":"दद्रुघ्नपत्रं दोषघ्नमम्लं वातकफापहम् कण्डूकासक्रिमिश्वासदद्रुकुष्ठप्रणुल्लघु","text":"dadrughnapatraṃ doṣaghnamamlaṃ vātakaphāpaham kaṇḍūkāsakrimiśvāsadadrukuṣṭhapraṇullaghu"},{"type":"verse","number":"37","sanskrit":"सेहुण्डस्य दलं तीक्ष्णं दीपनं रेचनं हरेत् आध्मानाष्ठीलिकागुल्मशूलशोथोदराणि च","text":"sehuṇḍasya dalaṃ tīkṣṇaṃ dīpanaṃ recanaṃ haret ādhmānāṣṭhīlikāgulmaśūlaśothodarāṇi ca"},{"type":"verse","number":"38","sanskrit":"पर्पटो हन्ति पित्तास्रज्वरतृष्णाकफभ्रमान् संग्राही शीतलस्तिक्तो दाहनुद्वातलो लघुः","text":"parpaṭo hanti pittāsrajvaratṛṣṇākaphabhramān saṃgrāhī śītalastikto dāhanudvātalo laghuḥ"},{"type":"verse","number":"39","sanskrit":"गोजिह्वा कुष्ठमेहास्रकृच्छ्रज्वरहरी लघुः","text":"gojihvā kuṣṭhamehāsrakṛcchrajvaraharī laghuḥ"},{"type":"verse","number":"40","sanskrit":"पटोलपत्रं पित्तघ्नं दीपनं पाचनं लघु स्निग्धं वृष्यं तथोष्णं च ज्वरकासक्रिमिप्रणुत् १०.","text":"paṭolapatraṃ pittaghnaṃ dīpanaṃ pācanaṃ laghu snigdhaṃ vṛṣyaṃ tathoṣṇaṃ ca jvarakāsakrimipraṇut 10."},{"type":"verse","number":"41","sanskrit":"गुडूचीपत्रमाग्नेयं सर्वज्वरहरं लघु कषायं कटुतित्तं च स्वादुपाकं रसायनम्","text":"guḍūcīpatramāgneyaṃ sarvajvaraharaṃ laghu kaṣāyaṃ kaṭutittaṃ ca svādupākaṃ rasāyanam"},{"type":"verse","number":"42","sanskrit":"बल्यमुष्णं च संग्राहि हन्याद्दोषत्रयं तृषाम् दाहप्रमेहवातासृक्कामलाकुष्ठपाण्डुताः","text":"balyamuṣṇaṃ ca saṃgrāhi hanyāddoṣatrayaṃ tṛṣām dāhapramehavātāsṛkkāmalākuṣṭhapāṇḍutāḥ"},{"type":"verse","number":"43","sanskrit":"कासमर्दोऽरिमर्दश्च कासारिः कर्कशस्तथा कासमर्ददलं रुच्यं वृष्यं कासविषास्रनुत्","text":"kāsamardo'rimardaśca kāsāriḥ karkaśastathā kāsamardadalaṃ rucyaṃ vṛṣyaṃ kāsaviṣāsranut"},{"type":"verse","number":"44","sanskrit":"मधुरं कफवातघ्नं पाचनं कण्ठशोधनम् विशेषतः कासहरं पित्तघ्नं ग्राहकं लघु","text":"madhuraṃ kaphavātaghnaṃ pācanaṃ kaṇṭhaśodhanam viśeṣataḥ kāsaharaṃ pittaghnaṃ grāhakaṃ laghu"},{"type":"verse","number":"45","sanskrit":"रुच्यं चणकशाकं स्याद् दुर्जरं कफवातकृत् अम्लं विष्टम्भजनकं पित्तनुदृन्तशोथहृत्","text":"rucyaṃ caṇakaśākaṃ syād durjaraṃ kaphavātakṛt amlaṃ viṣṭambhajanakaṃ pittanudṛntaśothahṛt"},{"type":"verse","number":"46","sanskrit":"कलायशाकं भेदि स्याल्लघु तिक्तं त्रिदोषजित्","text":"kalāyaśākaṃ bhedi syāllaghu tiktaṃ tridoṣajit"},{"type":"verse","number":"47","sanskrit":"कटुकं सार्षपं शाकं बहुमूत्रमलं गुरु अम्लपाकं विदाहि स्यादुष्णं रूक्षं त्रिदोषकृत् सक्षारलवणं तीक्ष्णं स्वादु शाकेषु निन्दितम्","text":"kaṭukaṃ sārṣapaṃ śākaṃ bahumūtramalaṃ guru amlapākaṃ vidāhi syāduṣṇaṃ rūkṣaṃ tridoṣakṛt sakṣāralavaṇaṃ tīkṣṇaṃ svādu śākeṣu ninditam"},{"type":"verse","number":"48","sanskrit":"अगस्तिकुसुमं शीतं चातुर्थिकनिवारणम् नक्तान्ध्यनाशनं तिक्तं कषायं कटुपाकि च पीनसश्लेष्मपित्तघ्नं वातघ्नं मुनिभिर्मतम्","text":"agastikusumaṃ śītaṃ cāturthikanivāraṇam naktāndhyanāśanaṃ tiktaṃ kaṣāyaṃ kaṭupāki ca pīnasaśleṣmapittaghnaṃ vātaghnaṃ munibhirmatam"},{"type":"verse","number":"49","sanskrit":"कदल्याः कुसुमं स्निग्धं मधुरं तुवरं गुरु वातपित्तहरं शीतं रक्तपित्तक्षयप्रणुत्","text":"kadalyāḥ kusumaṃ snigdhaṃ madhuraṃ tuvaraṃ guru vātapittaharaṃ śītaṃ raktapittakṣayapraṇut"},{"type":"verse","number":"50","sanskrit":"शिग्रोः पुष्पं तु कटुकं तीक्ष्णोष्णं स्नायुशोथनुत् कृमिहृत्कफवातघ्नं विद्र धिप्लीहगुल्मजित् मधु शिग्रोस्त्वक्षिहितं रक्तपित्तप्रसादनम् १०.","text":"śigroḥ puṣpaṃ tu kaṭukaṃ tīkṣṇoṣṇaṃ snāyuśothanut kṛmihṛtkaphavātaghnaṃ vidra dhiplīhagulmajit madhu śigrostvakṣihitaṃ raktapittaprasādanam 10."},{"type":"verse","number":"51","sanskrit":"शाल्मलीपुष्पशाकं तु घृतसैन्धवसाधितम् प्रदरं नाशयत्येव दुःसाध्यं च न संशयः","text":"śālmalīpuṣpaśākaṃ tu ghṛtasaindhavasādhitam pradaraṃ nāśayatyeva duḥsādhyaṃ ca na saṃśayaḥ"},{"type":"verse","number":"52","sanskrit":"रसे पाके च मधुरं कषायं शीतलं गुरु कफपित्तास्रजिद् ग्राहि वातलं च प्रकीर्त्तितम्","text":"rase pāke ca madhuraṃ kaṣāyaṃ śītalaṃ guru kaphapittāsrajid grāhi vātalaṃ ca prakīrttitam"},{"type":"verse","number":"53","sanskrit":"कूष्माडं स्यात्पुष्पफलं पीतपुष्पं बृहत्फलम्","text":"kūṣmāḍaṃ syātpuṣpaphalaṃ pītapuṣpaṃ bṛhatphalam"},{"type":"verse","number":"54","sanskrit":"कूष्माण्डं बृंहणं वृष्यं गुरु पित्तास्रवातनुत् बालं पित्तापहं शीतं मध्यमं कफकारकम्","text":"kūṣmāṇḍaṃ bṛṃhaṇaṃ vṛṣyaṃ guru pittāsravātanut bālaṃ pittāpahaṃ śītaṃ madhyamaṃ kaphakārakam"},{"type":"verse","number":"55","sanskrit":"बृद्धंनातिहिमं स्वादु सक्षारं दीपनं लघु बस्तिशुद्धिकरं चेतोरोगहृत्सर्वदोषजित्","text":"bṛddhaṃnātihimaṃ svādu sakṣāraṃ dīpanaṃ laghu bastiśuddhikaraṃ cetorogahṛtsarvadoṣajit"},{"type":"verse","number":"56","sanskrit":"कूष्माण्डी तु भृशं लघ्वी कर्कारुरपि कीर्त्तिता कर्कारुग्राहिणी शीता रक्तपित्तहरा गुरुः पक्वा तिक्ताऽग्निजननी सक्षारा कफवातनुत्","text":"kūṣmāṇḍī tu bhṛśaṃ laghvī karkārurapi kīrttitā karkārugrāhiṇī śītā raktapittaharā guruḥ pakvā tiktā'gnijananī sakṣārā kaphavātanut"},{"type":"verse","number":"57","sanskrit":"अलाबूः कथिता तुम्बी द्विधा दीर्घा च वर्तुला","text":"alābūḥ kathitā tumbī dvidhā dīrghā ca vartulā"},{"type":"verse","number":"58","sanskrit":"मिष्टतुम्बीफलं हृद्यं पित्तश्लेष्मापहं गुरु वृष्यं रुचिकरं प्रोक्तं धातु पुष्टिविवर्धनम्","text":"miṣṭatumbīphalaṃ hṛdyaṃ pittaśleṣmāpahaṃ guru vṛṣyaṃ rucikaraṃ proktaṃ dhātu puṣṭivivardhanam"},{"type":"verse","number":"59","sanskrit":"इक्ष्वाकुः कटुतुम्बी स्यात्सा तूम्बी च महाफला कटुतुम्बी हिमा हृद्या पित्तकासविषापहा तिक्ता कटुर्विपाके च वातपित्तज्वरान्तकृत्","text":"ikṣvākuḥ kaṭutumbī syātsā tūmbī ca mahāphalā kaṭutumbī himā hṛdyā pittakāsaviṣāpahā tiktā kaṭurvipāke ca vātapittajvarāntakṛt"},{"type":"verse","number":"60","sanskrit":"एर्वारुः कर्कटी प्रोक्ता कथ्यन्ते तद्गुणा अथ १०.","text":"ervāruḥ karkaṭī proktā kathyante tadguṇā atha 10."},{"type":"verse","number":"61","sanskrit":"कर्कटी शीतला रूक्षा ग्राहिणी मधुरा गुरुः रुच्या पित्तहरा सामा पक्वा तृष्णाऽग्निपित्तकृत्","text":"karkaṭī śītalā rūkṣā grāhiṇī madhurā guruḥ rucyā pittaharā sāmā pakvā tṛṣṇā'gnipittakṛt"},{"type":"verse","number":"62","sanskrit":"चिचिण्डः श्वेतराजिः स्यात्सुदीर्घो गृहकूलकः चिचिण्डो वातपित्तघ्नो बल्यः पथ्यो रुचिप्रदः शोषणोऽतिहितः किञ्चिद् गुणैर्न्यूनः पटोलतः","text":"ciciṇḍaḥ śvetarājiḥ syātsudīrgho gṛhakūlakaḥ ciciṇḍo vātapittaghno balyaḥ pathyo rucipradaḥ śoṣaṇo'tihitaḥ kiñcid guṇairnyūnaḥ paṭolataḥ"},{"type":"verse","number":"63","sanskrit":"कारवेल्लं कटिल्लं स्यात्कारवेल्ली ततोलघुः कारवेल्लं हिमं भेदि लघुतिक्तमवातलम्","text":"kāravellaṃ kaṭillaṃ syātkāravellī tatolaghuḥ kāravellaṃ himaṃ bhedi laghutiktamavātalam"},{"type":"verse","number":"64","sanskrit":"ज्वरपित्तकफास्रघ्नं पाण्डुमेहकृमीन् हरेत् तद्गुणा कारवेल्ली स्याद्विशेषाद्दीपनी लघुः","text":"jvarapittakaphāsraghnaṃ pāṇḍumehakṛmīn haret tadguṇā kāravellī syādviśeṣāddīpanī laghuḥ"},{"type":"verse","number":"65","sanskrit":"महाकोशातकी प्रोक्ता हस्तिघोषा महाफला","text":"mahākośātakī proktā hastighoṣā mahāphalā"},{"type":"verse","number":"66","sanskrit":"धामार्गवो घोषकश्च हस्तिपर्णश्च स स्मृतः महाकोशातकीस्निग्धा रक्तपित्तानिलापहा","text":"dhāmārgavo ghoṣakaśca hastiparṇaśca sa smṛtaḥ mahākośātakīsnigdhā raktapittānilāpahā"},{"type":"verse","number":"67","sanskrit":"धामार्गवः पीतपुष्पो जालिनी कृतवेधना राजकोशातकी चेति तथोक्ता राजिमत्फला","text":"dhāmārgavaḥ pītapuṣpo jālinī kṛtavedhanā rājakośātakī ceti tathoktā rājimatphalā"},{"type":"verse","number":"68","sanskrit":"राजकोशातकी शीता मधुरा कफवातकृत् पितघ्नी दीपनी श्वासज्वरकासकृमिप्रणुत्","text":"rājakośātakī śītā madhurā kaphavātakṛt pitaghnī dīpanī śvāsajvarakāsakṛmipraṇut"},{"type":"verse","number":"69","sanskrit":"पटोलः कुलकस्तिक्तः पाण्डुकः कर्कशच्छदः राजीफलः पाण्डुफलो राजेयश्चामृतफलः","text":"paṭolaḥ kulakastiktaḥ pāṇḍukaḥ karkaśacchadaḥ rājīphalaḥ pāṇḍuphalo rājeyaścāmṛtaphalaḥ"},{"type":"verse","number":"70","sanskrit":"बीजगर्भः प्रतीकश्च कुष्ठहा कासभञ्जनः पटोलं पाचनं हृद्यं वृष्यं लघ्वग्निदीपनम् स्निग्धोष्णं हन्ति कासास्रज्वरदोषत्रयक्रिमीन् १०.","text":"bījagarbhaḥ pratīkaśca kuṣṭhahā kāsabhañjanaḥ paṭolaṃ pācanaṃ hṛdyaṃ vṛṣyaṃ laghvagnidīpanam snigdhoṣṇaṃ hanti kāsāsrajvaradoṣatrayakrimīn 10."},{"type":"verse","number":"71","sanskrit":"पटोलस्य भवेन्मूलं विरेचनकरं सुखात्","text":"paṭolasya bhavenmūlaṃ virecanakaraṃ sukhāt"},{"type":"verse","number":"72","sanskrit":"नालं श्लेष्महरं पत्रं पित्तहारी फलं पुनः दोषत्रयहरं प्रोक्तं तद्वतिक्ता पटोलिका","text":"nālaṃ śleṣmaharaṃ patraṃ pittahārī phalaṃ punaḥ doṣatrayaharaṃ proktaṃ tadvatiktā paṭolikā"},{"type":"verse","number":"73","sanskrit":"बिम्बी रक्तफला तुण्डी तुण्डीकेरी च बिम्बिका ओष्ठोपमफला प्रोक्ता पीलुपर्णी च कथ्यते","text":"bimbī raktaphalā tuṇḍī tuṇḍīkerī ca bimbikā oṣṭhopamaphalā proktā pīluparṇī ca kathyate"},{"type":"verse","number":"74","sanskrit":"बिम्बीफलं स्वादु शीतं गुरु पित्तास्रवातजित् स्तभनं लेखनं रुच्यं विबन्धाध्मानकारकम्","text":"bimbīphalaṃ svādu śītaṃ guru pittāsravātajit stabhanaṃ lekhanaṃ rucyaṃ vibandhādhmānakārakam"},{"type":"verse","number":"75","sanskrit":"शिम्बिः शिम्बी पुस्तशिम्बी तथा पुस्तकशिम्बिका शिम्बीद्वयं च मधुरं रसे पाके हिमं गुरु बल्यं दाहकरं प्रोक्तं श्लेष्मलं वातपित्तजित्","text":"śimbiḥ śimbī pustaśimbī tathā pustakaśimbikā śimbīdvayaṃ ca madhuraṃ rase pāke himaṃ guru balyaṃ dāhakaraṃ proktaṃ śleṣmalaṃ vātapittajit"},{"type":"verse","number":"76","sanskrit":"कोलशिम्बिः कृष्णफला तथा पर्यङ्कपट्टिका","text":"kolaśimbiḥ kṛṣṇaphalā tathā paryaṅkapaṭṭikā"},{"type":"verse","number":"77","sanskrit":"कोलशिम्बिः समीरघ्नी गुर्व्युष्णा कफपित्तकृत् शुक्राग्निसादकृत् वृष्या रुचिकृद् बद्धविड् गुरुः","text":"kolaśimbiḥ samīraghnī gurvyuṣṇā kaphapittakṛt śukrāgnisādakṛt vṛṣyā rucikṛd baddhaviḍ guruḥ"},{"type":"verse","number":"78","sanskrit":"शोभाञ्जनफलं स्वादु कषायं कफपित्तनुत् शूलकुष्ठक्षयश्वासगुल्महृद् दीपनं परम्","text":"śobhāñjanaphalaṃ svādu kaṣāyaṃ kaphapittanut śūlakuṣṭhakṣayaśvāsagulmahṛd dīpanaṃ param"},{"type":"verse","number":"79","sanskrit":"वृन्ताकं स्त्री तु वार्त्ताकुर्भण्टाकी भाण्टिकाऽपि च वृन्ताकं स्वादु तीक्ष्णोष्णं कटुपाकमपित्तलम् ज्वरवातबलासघ्नं दीपनं शुक्रलं लघु","text":"vṛntākaṃ strī tu vārttākurbhaṇṭākī bhāṇṭikā'pi ca vṛntākaṃ svādu tīkṣṇoṣṇaṃ kaṭupākamapittalam jvaravātabalāsaghnaṃ dīpanaṃ śukralaṃ laghu"},{"type":"verse","number":"80","sanskrit":"तद्बालं कफपित्तघ्नं वृद्धं पित्तकरं गुरु १०.","text":"tadbālaṃ kaphapittaghnaṃ vṛddhaṃ pittakaraṃ guru 10."},{"type":"verse","number":"81","sanskrit":"वृन्ताकं पित्तलं किञ्चिदङ्गारपरिपाचितम् कफमेदोऽनिलामघ्नमत्यर्थं लघु दीपनम्","text":"vṛntākaṃ pittalaṃ kiñcidaṅgāraparipācitam kaphamedo'nilāmaghnamatyarthaṃ laghu dīpanam"},{"type":"verse","number":"82","sanskrit":"तदेव हि गुरु स्निग्धं सतैलं लवणान्वितम् अपरं श्वेतवृन्ताकं कुक्कुटाण्डसमं भवेत् तदर्शःसु विशेषेण हितं हीनं च पूर्वतः","text":"tadeva hi guru snigdhaṃ satailaṃ lavaṇānvitam aparaṃ śvetavṛntākaṃ kukkuṭāṇḍasamaṃ bhavet tadarśaḥsu viśeṣeṇa hitaṃ hīnaṃ ca pūrvataḥ"},{"type":"verse","number":"83","sanskrit":"डिण्डिशो रोमशफलो मुनिनिर्मित इत्यपि","text":"ḍiṇḍiśo romaśaphalo muninirmita ityapi"},{"type":"verse","number":"84","sanskrit":"डिण्डिशो रुचिकृद्भेदी पित्तश्लेष्मापहः स्मृतः सुशीतो वातलो रूक्षो मूत्रलश्चाश्मरीहरः","text":"ḍiṇḍiśo rucikṛdbhedī pittaśleṣmāpahaḥ smṛtaḥ suśīto vātalo rūkṣo mūtralaścāśmarīharaḥ"},{"type":"verse","number":"85","sanskrit":"पिण्डारं शीतलं बल्यं पित्तघ्नंरुचिकारकम् पाके लघु विशेषेण विषशान्तिकरं स्मृतम्","text":"piṇḍāraṃ śītalaṃ balyaṃ pittaghnaṃrucikārakam pāke laghu viśeṣeṇa viṣaśāntikaraṃ smṛtam"},{"type":"verse","number":"86","sanskrit":"कर्कोटकी पीतपुष्पा महाजालीति चोच्यते कर्कोटी मलहृत्कुष्ठहृल्लासारुचिनाशिनी श्वासकासज्वरान्हन्ति कटुपाका च दीपनी","text":"karkoṭakī pītapuṣpā mahājālīti cocyate karkoṭī malahṛtkuṣṭhahṛllāsārucināśinī śvāsakāsajvarānhanti kaṭupākā ca dīpanī"},{"type":"verse","number":"87","sanskrit":"डोडिका विषमुष्टिश्च डोडित्यपि सुमुष्टिका","text":"ḍoḍikā viṣamuṣṭiśca ḍoḍityapi sumuṣṭikā"},{"type":"verse","number":"88","sanskrit":"डोडिका पुष्टिदा वृष्या रुच्या वह्निप्रदा लघुः हन्ति पित्तकफार्शांसि कृमिगुल्मविषामयान्","text":"ḍoḍikā puṣṭidā vṛṣyā rucyā vahnipradā laghuḥ hanti pittakaphārśāṃsi kṛmigulmaviṣāmayān"},{"type":"verse","number":"89","sanskrit":"कण्टकारीफलं तिक्तं कटुकं दीपनं लघु रूक्षोष्णं श्वासकासघ्नं ज्वरानिलकफापहम्","text":"kaṇṭakārīphalaṃ tiktaṃ kaṭukaṃ dīpanaṃ laghu rūkṣoṣṇaṃ śvāsakāsaghnaṃ jvarānilakaphāpaham"},{"type":"verse","number":"90","sanskrit":"तीक्ष्णोष्णं सार्षपं नालं वातश्लेष्मव्रणापहम् कण्डूकृमिहरं दद्रुकुष्ठघ्नं रुचिकारकम् १०.","text":"tīkṣṇoṣṇaṃ sārṣapaṃ nālaṃ vātaśleṣmavraṇāpaham kaṇḍūkṛmiharaṃ dadrukuṣṭhaghnaṃ rucikārakam 10."},{"type":"verse","number":"91","sanskrit":"सूरणः कन्द ओलश्च कन्दलोऽशोघ्न इत्यपि सूरणो दीपनो रूक्षः कषायः कण्डुकृत् कटुः","text":"sūraṇaḥ kanda olaśca kandalo'śoghna ityapi sūraṇo dīpano rūkṣaḥ kaṣāyaḥ kaṇḍukṛt kaṭuḥ"},{"type":"verse","number":"92","sanskrit":"विष्टम्भी विशदो रुच्यः कफार्शः कृन्तनो लघुः विशेषादर्शसे पथ्यः प्लीहगुल्मविनाशनः","text":"viṣṭambhī viśado rucyaḥ kaphārśaḥ kṛntano laghuḥ viśeṣādarśase pathyaḥ plīhagulmavināśanaḥ"},{"type":"verse","number":"93","sanskrit":"सर्वेषां कन्दशाकानां सूरणः श्रेष्ठ उच्यते दद्रू णां कुष्ठिनां रक्तपित्तिनां न हितो हि सः सन्धानयोगं सम्प्राप्तः सूरणो गुणवत्तरः","text":"sarveṣāṃ kandaśākānāṃ sūraṇaḥ śreṣṭha ucyate dadrū ṇāṃ kuṣṭhināṃ raktapittināṃ na hito hi saḥ sandhānayogaṃ samprāptaḥ sūraṇo guṇavattaraḥ"},{"type":"verse","number":"94","sanskrit":"आरूकं वीरसेनञ्च वीरं वीरारुकं तथा आरुकमप्यालुकं तत्कथितं वीरसेनकम्","text":"ārūkaṃ vīrasenañca vīraṃ vīrārukaṃ tathā ārukamapyālukaṃ tatkathitaṃ vīrasenakam"},{"type":"verse","number":"95","sanskrit":"काष्ठालुकशङ्खालुकहस्त्यालुकानि कथ्यन्ते पिण्डालुकमघ्वालुक रक्तालुकानि चोक्तानि","text":"kāṣṭhālukaśaṅkhālukahastyālukāni kathyante piṇḍālukamaghvāluka raktālukāni coktāni"},{"type":"verse","number":"96","sanskrit":"आलुकं शीतलं सर्वं विष्टम्भि मधुरं गुरु","text":"ālukaṃ śītalaṃ sarvaṃ viṣṭambhi madhuraṃ guru"},{"type":"verse","number":"97","sanskrit":"सृष्टमूत्रमलं रूक्षं दुर्जरं रक्तपित्तनुत् कफानिलकरं बल्यं वृष्यं स्वल्पाग्निवर्द्धनम्","text":"sṛṣṭamūtramalaṃ rūkṣaṃ durjaraṃ raktapittanut kaphānilakaraṃ balyaṃ vṛṣyaṃ svalpāgnivarddhanam"},{"type":"verse","number":"98","sanskrit":"रक्तालुभेदो या दीर्घा तन्वी च प्रथिताऽलुकी आलुकी बलकृत्स्निग्धा गुर्वी हृत्कफनाशिनी विष्टम्भकारिणी तैले तलिताऽतिरुचिप्रदा","text":"raktālubhedo yā dīrghā tanvī ca prathitā'lukī ālukī balakṛtsnigdhā gurvī hṛtkaphanāśinī viṣṭambhakāriṇī taile talitā'tirucipradā"},{"type":"verse","number":"99","sanskrit":"मूलकं द्विविधं प्रोक्तं तत्रैकं लघुमूलकम् शालामर्कटकं विस्रं शालेयं मरुसम्भवम्","text":"mūlakaṃ dvividhaṃ proktaṃ tatraikaṃ laghumūlakam śālāmarkaṭakaṃ visraṃ śāleyaṃ marusambhavam"},{"type":"verse","number":"100","sanskrit":"चाणक्यमूलकं तीक्ष्णं तथा मूलकपोतिका नेपालमूलकं चान्यत्तद्भवेद्गजदन्तवत् १०.","text":"cāṇakyamūlakaṃ tīkṣṇaṃ tathā mūlakapotikā nepālamūlakaṃ cānyattadbhavedgajadantavat 10."},{"type":"verse","number":"101","sanskrit":"लघुमूलं कटूष्णं स्याद्रुच्यं लघु च पाचनम् दोषत्रयहरं स्वर्यं ज्वरश्वासविनाशनम्","text":"laghumūlaṃ kaṭūṣṇaṃ syādrucyaṃ laghu ca pācanam doṣatrayaharaṃ svaryaṃ jvaraśvāsavināśanam"},{"type":"verse","number":"102","sanskrit":"नासिकाकण्ठरोगघ्नं नयनामयनाशनम्","text":"nāsikākaṇṭharogaghnaṃ nayanāmayanāśanam"},{"type":"verse","number":"103","sanskrit":"महत्तदेव रूक्षोष्णं गुरु दोषत्रयप्रदस् स्नेहसिद्धं तदेव स्याद् दोषत्रयविनाशनम्","text":"mahattadeva rūkṣoṣṇaṃ guru doṣatrayapradas snehasiddhaṃ tadeva syād doṣatrayavināśanam"},{"type":"verse","number":"104","sanskrit":"गृञ्जनं गाजरं प्रोक्तं तथा नारङ्गवर्णकम् गाजरं मधुरं तीक्ष्णं तिक्तोष्णं दीपनं लघु संग्राहि रक्तपित्तार्शोग्रहणीकफवातजित्","text":"gṛñjanaṃ gājaraṃ proktaṃ tathā nāraṅgavarṇakam gājaraṃ madhuraṃ tīkṣṇaṃ tiktoṣṇaṃ dīpanaṃ laghu saṃgrāhi raktapittārśograhaṇīkaphavātajit"},{"type":"verse","number":"105","sanskrit":"शीतलः कदलीकन्दो बल्यः केश्योऽम्लपित्तजित् वह्निकृद्दाहहारी च मधुरो रुचिकारकः","text":"śītalaḥ kadalīkando balyaḥ keśyo'mlapittajit vahnikṛddāhahārī ca madhuro rucikārakaḥ"},{"type":"verse","number":"106","sanskrit":"मानकः स्यान्महापत्रः कथ्यन्ते तद्गुणा अथ मानकः शोथहृच्छीतो रक्तपित्तहरो लघुः","text":"mānakaḥ syānmahāpatraḥ kathyante tadguṇā atha mānakaḥ śothahṛcchīto raktapittaharo laghuḥ"},{"type":"verse","number":"107","sanskrit":"वाराही पित्तला बल्या कट्वी तिक्ता रसायनी आयुःशुक्राग्निकृन्मेहकफकुष्ठानिलापहा","text":"vārāhī pittalā balyā kaṭvī tiktā rasāyanī āyuḥśukrāgnikṛnmehakaphakuṣṭhānilāpahā"},{"type":"verse","number":"108","sanskrit":"गजकर्णा तु तिक्तोष्णा तथा वातकफाञ्जयेत् शीतज्वरहरी स्वादुः पाके तस्यास्तु कन्दकः","text":"gajakarṇā tu tiktoṣṇā tathā vātakaphāñjayet śītajvaraharī svāduḥ pāke tasyāstu kandakaḥ"},{"type":"verse","number":"109","sanskrit":"ग्रहण्यर्शोविकारघ्नी वनसूरणकन्दवत्","text":"grahaṇyarśovikāraghnī vanasūraṇakandavat"},{"type":"verse","number":"110","sanskrit":"केमुकं कटुकं पाके तिक्तं ग्राहि हिमं लघु १०.","text":"kemukaṃ kaṭukaṃ pāke tiktaṃ grāhi himaṃ laghu 10."},{"type":"verse","number":"111","sanskrit":"दीपनं पाचनं हृद्यं कफपित्तज्वरापहम् कुष्ठकासप्रमेहास्रनाशनं वातलं कटु","text":"dīpanaṃ pācanaṃ hṛdyaṃ kaphapittajvarāpaham kuṣṭhakāsapramehāsranāśanaṃ vātalaṃ kaṭu"},{"type":"verse","number":"112","sanskrit":"कसेरु द्विविधं तत्तु महद्रा जकसेरुकम् मुस्ताकृति लघु स्याद्यत्तच्चिचोढमिति स्मृतम्","text":"kaseru dvividhaṃ tattu mahadrā jakaserukam mustākṛti laghu syādyattaccicoḍhamiti smṛtam"},{"type":"verse","number":"113","sanskrit":"कसेरुकद्वयं शीतं मधुरं तुवरं गुरु पित्तशोणितदाहघ्नं नयनामयनाशनम् ग्राहि शुक्रानिलश्लेष्मारुचिस्तन्यकरं स्मृतम्","text":"kaserukadvayaṃ śītaṃ madhuraṃ tuvaraṃ guru pittaśoṇitadāhaghnaṃ nayanāmayanāśanam grāhi śukrānilaśleṣmārucistanyakaraṃ smṛtam"},{"type":"verse","number":"114","sanskrit":"पद्मादिकन्दः शालूकं करहाटश्च कथ्यते","text":"padmādikandaḥ śālūkaṃ karahāṭaśca kathyate"},{"type":"verse","number":"115","sanskrit":"मृणालमूलं भिस्साण्डं जलालूकञ्च कथ्यते शालूकं शीतलं वृष्यं पित्तदाहास्रनुद् गुरु","text":"mṛṇālamūlaṃ bhissāṇḍaṃ jalālūkañca kathyate śālūkaṃ śītalaṃ vṛṣyaṃ pittadāhāsranud guru"},{"type":"verse","number":"116","sanskrit":"दुर्जरं स्वादुपाकश्च स्तन्यानिलकफप्रदम् संग्राहि मधुरं रूक्षं भिस्साण्डमपि तद्गुणम्","text":"durjaraṃ svādupākaśca stanyānilakaphapradam saṃgrāhi madhuraṃ rūkṣaṃ bhissāṇḍamapi tadguṇam"},{"type":"verse","number":"117","sanskrit":"बालं ह्यनार्त्तवं जीर्णं व्याधितं कृमिभक्षितम् कन्दं विवर्जयेत्सर्वं यद्वाऽग्न्यादिविदूषितम् अतिजीर्णमकालोत्थं रूक्षसिद्धमदेशजम्","text":"bālaṃ hyanārttavaṃ jīrṇaṃ vyādhitaṃ kṛmibhakṣitam kandaṃ vivarjayetsarvaṃ yadvā'gnyādividūṣitam atijīrṇamakālotthaṃ rūkṣasiddhamadeśajam"},{"type":"verse","number":"118","sanskrit":"कर्कशं कोमलं चातिशीतव्यालादिदूषितम् संशुष्कं सकलं शाकं नाश्नीयान्मूलकं विना","text":"karkaśaṃ komalaṃ cātiśītavyālādidūṣitam saṃśuṣkaṃ sakalaṃ śākaṃ nāśnīyānmūlakaṃ vinā"},{"type":"verse","number":"119","sanskrit":"उक्तं संस्वेदजं शाकं भूमिच्छत्रं शिलीन्ध्रकम् क्षितिगोमयकाष्ठेषु वृक्षादिषु तदुद्भवेत्","text":"uktaṃ saṃsvedajaṃ śākaṃ bhūmicchatraṃ śilīndhrakam kṣitigomayakāṣṭheṣu vṛkṣādiṣu tadudbhavet"},{"type":"verse","number":"120","sanskrit":"सर्वे संस्वेदजाः शीता दोषलाः पिच्छिलाश्च ते गुरवश्छर्द्यतीसारज्वरश्लेष्मामयप्रदाः १०.","text":"sarve saṃsvedajāḥ śītā doṣalāḥ picchilāśca te guravaśchardyatīsārajvaraśleṣmāmayapradāḥ 10."},{"type":"verse","number":"121","sanskrit":"नातिदोषकरास्ते स्युः शेषास्तेभ्यो विगर्हिताः","text":"nātidoṣakarāste syuḥ śeṣāstebhyo vigarhitāḥ"},{"type":"verse","number":"10","sanskrit":"इति श्रीलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिस्रप्रकरणे दशमः शाकवर्गं समाप्तः","text":"iti śrīlaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe misraprakaraṇe daśamaḥ śākavargaṃ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":10,"lang":"sa","content":[{"type":"heading","heading":"māṃsa-варга — мясо"},{"type":"verse","number":"1","sanskrit":"मासं तु पिशितं क्रव्यमामिषं पललं पलम् मांसं वातहरं सर्वं बृंहणं बलपुष्टिकृत् प्रीणनं गुरु हृद्यञ्च मधुरं रसपाकयोः","text":"māsaṃ tu piśitaṃ kravyamāmiṣaṃ palalaṃ palam māṃsaṃ vātaharaṃ sarvaṃ bṛṃhaṇaṃ balapuṣṭikṛt prīṇanaṃ guru hṛdyañca madhuraṃ rasapākayoḥ"},{"type":"verse","number":"2","sanskrit":"मांसवर्गो द्विधा ज्ञेयो जाङ्गलानूपभेदतः","text":"māṃsavargo dvidhā jñeyo jāṅgalānūpabhedataḥ"},{"type":"verse","number":"3","sanskrit":"मांसवर्गेऽत्र जङ्घाला बिलस्थाश्च गुहाशयाः तथा पर्णमृगा ज्ञेया विष्किराः प्रतुदस्तथा","text":"māṃsavarge'tra jaṅghālā bilasthāśca guhāśayāḥ tathā parṇamṛgā jñeyā viṣkirāḥ pratudastathā"},{"type":"verse","number":"4","sanskrit":"प्रसहा अथ च ग्राम्या अष्टौ जाङ्गलजातयः जाङ्गला मधुरा रूक्षास्तुवरा लघवस्तथा","text":"prasahā atha ca grāmyā aṣṭau jāṅgalajātayaḥ jāṅgalā madhurā rūkṣāstuvarā laghavastathā"},{"type":"verse","number":"5","sanskrit":"बल्यास्ते बृंहणं वृष्या दीपना दोषहारिणः मूकतां मिन्मिनत्वं च गद्गदत्वार्दिते तथा","text":"balyāste bṛṃhaṇaṃ vṛṣyā dīpanā doṣahāriṇaḥ mūkatāṃ minminatvaṃ ca gadgadatvārdite tathā"},{"type":"verse","number":"6","sanskrit":"बाधिर्य्यमरुचिच्छर्दिप्रमेहमुखजान् गदान् श्लीपदं गलगण्डञ्च नाशयत्यनिलामयान्","text":"bādhiryyamarucicchardipramehamukhajān gadān ślīpadaṃ galagaṇḍañca nāśayatyanilāmayān"},{"type":"verse","number":"7","sanskrit":"कूलेचराः प्लवाश्चापि कोशस्थाः पादिनस्तथा मत्स्या एते समाख्याताः पञ्चधाऽनूपजातयः","text":"kūlecarāḥ plavāścāpi kośasthāḥ pādinastathā matsyā ete samākhyātāḥ pañcadhā'nūpajātayaḥ"},{"type":"verse","number":"8","sanskrit":"अनूपा मधुराः स्निग्धा गुरवो वह्निसादनाः श्लेष्मलाः पिच्छिलाश्चापि मांसपुष्टिप्रदा भृशम् तथाऽभिष्यन्दिनस्ते हि प्रायः पथ्यतमाः स्मृताः","text":"anūpā madhurāḥ snigdhā guravo vahnisādanāḥ śleṣmalāḥ picchilāścāpi māṃsapuṣṭipradā bhṛśam tathā'bhiṣyandinaste hi prāyaḥ pathyatamāḥ smṛtāḥ"},{"type":"verse","number":"9","sanskrit":"हरिणैणकुरङ्गर्ष्यपृषतन्यङ्कुशम्बराः","text":"hariṇaiṇakuraṅgarṣyapṛṣatanyaṅkuśambarāḥ"},{"type":"verse","number":"10","sanskrit":"राजीवोऽपि च मुण्डी चेत्याद्या जङ्घालसंज्ञकाः हरिणस्ताम्रवर्णः स्यादेणः कृष्णः प्रकीर्त्तितः","text":"rājīvo'pi ca muṇḍī cetyādyā jaṅghālasaṃjñakāḥ hariṇastāmravarṇaḥ syādeṇaḥ kṛṣṇaḥ prakīrttitaḥ"},{"type":"verse","number":"11","sanskrit":"कुरङ्गईषत्ताम्रः स्यादेणतुल्याकृतिर्महान् ऋष्यो नीलाङ्गको लोके स रोझ इति कीर्त्तितः","text":"kuraṅgaīṣattāmraḥ syādeṇatulyākṛtirmahān ṛṣyo nīlāṅgako loke sa rojha iti kīrttitaḥ"},{"type":"verse","number":"12","sanskrit":"पृषतश्चन्द्र बिन्दुः स्याद्धरिणात्किञ्चिदल्पकः न्यङ्कुर्बहुविषाणोऽथ शम्बरो गवयो महान्","text":"pṛṣataścandra binduḥ syāddhariṇātkiñcidalpakaḥ nyaṅkurbahuviṣāṇo'tha śambaro gavayo mahān"},{"type":"verse","number":"13","sanskrit":"राजीवस्तु मृगो ज्ञेयो राजिभिः परितोवृतः यो मृगः शृङ्गहीनः स्यात्स मुण्डीति निगद्यते","text":"rājīvastu mṛgo jñeyo rājibhiḥ paritovṛtaḥ yo mṛgaḥ śṛṅgahīnaḥ syātsa muṇḍīti nigadyate"},{"type":"verse","number":"14","sanskrit":"जङ्घालाः प्रायशः सर्वे पित्तश्लेष्महराः स्मृतः किञ्चिद्वातकराश्चापि लघवो बलवर्द्धनाः","text":"jaṅghālāḥ prāyaśaḥ sarve pittaśleṣmaharāḥ smṛtaḥ kiñcidvātakarāścāpi laghavo balavarddhanāḥ"},{"type":"verse","number":"15","sanskrit":"गोधाशशभुजङ्गाखुशल्लक्याद्या बिलेशयाः बिलेशया वातहरा मधुरा रसपाकयोः बृंहणा बद्धविण्मूत्रा वीर्योष्णाश्च प्रकीर्त्तिताः","text":"godhāśaśabhujaṅgākhuśallakyādyā bileśayāḥ bileśayā vātaharā madhurā rasapākayoḥ bṛṃhaṇā baddhaviṇmūtrā vīryoṣṇāśca prakīrttitāḥ"},{"type":"verse","number":"16","sanskrit":"सिंहव्याघ्रवृका ॠक्षतरक्षुद्वीपिनस्तथा बभ्रुजम्बूकमार्जारा इत्याद्याः स्युर्गुहाशयाः","text":"siṃhavyāghravṛkā ṝkṣatarakṣudvīpinastathā babhrujambūkamārjārā ityādyāḥ syurguhāśayāḥ"},{"type":"verse","number":"17","sanskrit":"गुहाशया वातहरा गुरूष्णा मधुराश्च ते स्निग्धा बल्या हिता नित्यं नेत्र गुद विकारिणाम्","text":"guhāśayā vātaharā gurūṣṇā madhurāśca te snigdhā balyā hitā nityaṃ netra guda vikāriṇām"},{"type":"verse","number":"18","sanskrit":"अथ पर्णमृगाः तेषां गणनां (वृक्ष पर चढने वाले प्राणी) वनौका वृक्षमार्जारो वृक्षमर्कटिकाऽदयः एते पर्णमृगाः प्रोक्ताः सुश्रुताद्यैर्महर्षिभिः","text":"atha parṇamṛgāḥ teṣāṃ gaṇanāṃ (vṛkṣa para caḍhane vāle prāṇī) vanaukā vṛkṣamārjāro vṛkṣamarkaṭikā'dayaḥ ete parṇamṛgāḥ proktāḥ suśrutādyairmaharṣibhiḥ"},{"type":"verse","number":"19","sanskrit":"स्मृताः पर्ण मृगा वृष्याश्चक्षुष्या शोषिणे हिताः श्वासार्शः कास शमनाः सृष्ट मूत्र पुरीषकाः","text":"smṛtāḥ parṇa mṛgā vṛṣyāścakṣuṣyā śoṣiṇe hitāḥ śvāsārśaḥ kāsa śamanāḥ sṛṣṭa mūtra purīṣakāḥ"},{"type":"verse","number":"20","sanskrit":"वर्त्तका लाववर्त्तीरकपिञ्जलकतित्तिराः कुलिङ्गकुक्कुटाद्याश्च विष्किरा समुदाहृताः","text":"varttakā lāvavarttīrakapiñjalakatittirāḥ kuliṅgakukkuṭādyāśca viṣkirā samudāhṛtāḥ"},{"type":"verse","number":"21","sanskrit":"विकीर्य भक्षयन्त्येते यस्मात्तस्माद्धि विष्किराः कपिञ्जल इति प्राज्ञैः कथितो गौरतित्तिरिः","text":"vikīrya bhakṣayantyete yasmāttasmāddhi viṣkirāḥ kapiñjala iti prājñaiḥ kathito gauratittiriḥ"},{"type":"verse","number":"22","sanskrit":"विष्किरा मधुराः शीताः कषायाः कटुपाकिनः बल्या वृष्यास्रिदोषघ्नाः पथ्यास्ते लघवः स्मृताः","text":"viṣkirā madhurāḥ śītāḥ kaṣāyāḥ kaṭupākinaḥ balyā vṛṣyāsridoṣaghnāḥ pathyāste laghavaḥ smṛtāḥ"},{"type":"verse","number":"23","sanskrit":"पारावतः खञ्जरीटः पिकाद्याः प्रतुदाः स्मृताः प्रतुद्य भक्षयन्त्येते तुण्डेन प्रतुदास्ततः","text":"pārāvataḥ khañjarīṭaḥ pikādyāḥ pratudāḥ smṛtāḥ pratudya bhakṣayantyete tuṇḍena pratudāstataḥ"},{"type":"verse","number":"24","sanskrit":"प्रतुदा मधुराः पित्तकफघ्नास्तुवरा हिमाः लघवो बद्धवर्चस्काः किञ्चिद्वातकराःस्मृताः","text":"pratudā madhurāḥ pittakaphaghnāstuvarā himāḥ laghavo baddhavarcaskāḥ kiñcidvātakarāḥsmṛtāḥ"},{"type":"verse","number":"25","sanskrit":"काको गृध्र उलूकश्च चिल्लश्च शशघातकः चाषो भासश्च कुरर इत्याद्याः प्रसहाः स्मृताः","text":"kāko gṛdhra ulūkaśca cillaśca śaśaghātakaḥ cāṣo bhāsaśca kurara ityādyāḥ prasahāḥ smṛtāḥ"},{"type":"verse","number":"26","sanskrit":"प्रसहाः कीर्त्तिता एते प्रसह्याच्छिद्य भक्षणात्","text":"prasahāḥ kīrttitā ete prasahyācchidya bhakṣaṇāt"},{"type":"verse","number":"27","sanskrit":"प्रसहाः खलु वीर्योष्णास्तन्मांसं भक्षयन्ति ये ते शोषभस्मकोन्मादशुक्रक्षीणा भवन्ति हि","text":"prasahāḥ khalu vīryoṣṇāstanmāṃsaṃ bhakṣayanti ye te śoṣabhasmakonmādaśukrakṣīṇā bhavanti hi"},{"type":"verse","number":"28","sanskrit":"छागमेषवृषाश्वाद्या ग्राम्याः प्रोक्ता महर्षिभिः ग्राम्या वातहराः सर्वे दीपनाः कफपित्तलाः मधुरा रसपाकाभ्यां बृंहणा बलवर्द्धनाः","text":"chāgameṣavṛṣāśvādyā grāmyāḥ proktā maharṣibhiḥ grāmyā vātaharāḥ sarve dīpanāḥ kaphapittalāḥ madhurā rasapākābhyāṃ bṛṃhaṇā balavarddhanāḥ"},{"type":"verse","number":"29","sanskrit":"एते कूलेचराः प्रोक्ता यतः कूले चरन्त्यपाम्","text":"ete kūlecarāḥ proktā yataḥ kūle carantyapām"},{"type":"verse","number":"30","sanskrit":"कूलेचरा मरुत्पित्तहरा वृष्या बलावहाः मधुराः शीतलाः स्निग्धामूत्रलाः श्लेष्म वर्धना","text":"kūlecarā marutpittaharā vṛṣyā balāvahāḥ madhurāḥ śītalāḥ snigdhāmūtralāḥ śleṣma vardhanā"},{"type":"verse","number":"31","sanskrit":"हंससारसकारण्डबकक्रौञ्चशरारिकाः","text":"haṃsasārasakāraṇḍabakakrauñcaśarārikāḥ"},{"type":"verse","number":"32","sanskrit":"नन्दीमुखी सकादम्बा बलाकाद्याः प्लवाः स्मृताः प्लवन्ति सलिले यस्मादेते तस्मात्प्लवाः स्मृताः","text":"nandīmukhī sakādambā balākādyāḥ plavāḥ smṛtāḥ plavanti salile yasmādete tasmātplavāḥ smṛtāḥ"},{"type":"verse","number":"33","sanskrit":"प्लवाः पित्तहराः स्निग्धा मधुरा गुखो हिमाः वात श्लेष्म प्रदाश्चापि बल शुक्र कराः सराः","text":"plavāḥ pittaharāḥ snigdhā madhurā gukho himāḥ vāta śleṣma pradāścāpi bala śukra karāḥ sarāḥ"},{"type":"verse","number":"34","sanskrit":"शङ्खः शङ्खनखश्चापिशुक्तिशम्बूककर्कटाः जीवा एवंविधाश्चान्येकोशस्थाः परिकीर्त्तिताः","text":"śaṅkhaḥ śaṅkhanakhaścāpiśuktiśambūkakarkaṭāḥ jīvā evaṃvidhāścānyekośasthāḥ parikīrttitāḥ"},{"type":"verse","number":"35","sanskrit":"कोशस्था मधुराःस्निग्धा वातपित्तहरा हिमाः बृंहणा बहुवर्चस्का वृष्याश्च बलवर्द्धनाः","text":"kośasthā madhurāḥsnigdhā vātapittaharā himāḥ bṛṃhaṇā bahuvarcaskā vṛṣyāśca balavarddhanāḥ"},{"type":"verse","number":"36","sanskrit":"कुम्भीरकूर्मनक्राश्च गोधामकरशङ्कव घण्टिकः शिशुमारश्चेत्यादयः पादिनः स्मृताः","text":"kumbhīrakūrmanakrāśca godhāmakaraśaṅkava ghaṇṭikaḥ śiśumāraścetyādayaḥ pādinaḥ smṛtāḥ"},{"type":"verse","number":"37","sanskrit":"पादनोऽपि च ये तेतु कोशस्थानां गुणैः समाः","text":"pādano'pi ca ye tetu kośasthānāṃ guṇaiḥ samāḥ"},{"type":"verse","number":"38","sanskrit":"मत्स्यो मीनो विसारश्च झषो वैसारिणोऽण्डजः शकुली पृथुरोमा च स सुदर्शन इत्यपि","text":"matsyo mīno visāraśca jhaṣo vaisāriṇo'ṇḍajaḥ śakulī pṛthuromā ca sa sudarśana ityapi"},{"type":"verse","number":"39","sanskrit":"रोहिताद्यास्तु ये जीवास्ते मत्स्याः परिकीर्त्तिताः मत्स्याः स्निग्धोष्णमधुरा गुरवः कफपित्तलाः","text":"rohitādyāstu ye jīvāste matsyāḥ parikīrttitāḥ matsyāḥ snigdhoṣṇamadhurā guravaḥ kaphapittalāḥ"},{"type":"verse","number":"40","sanskrit":"वातघ्ना बृंहणा वृष्या रोचका बलवर्द्धनाः मद्यव्यवायसक्तानां दीप्ताग्नीनाञ्च पूजिताः","text":"vātaghnā bṛṃhaṇā vṛṣyā rocakā balavarddhanāḥ madyavyavāyasaktānāṃ dīptāgnīnāñca pūjitāḥ"},{"type":"verse","number":"41","sanskrit":"हरिणः शीतलो बद्धविण्मूत्रो दीपनो लघुः रसे पाके च मधुरः सुगन्धिः सन्निपातहा","text":"hariṇaḥ śītalo baddhaviṇmūtro dīpano laghuḥ rase pāke ca madhuraḥ sugandhiḥ sannipātahā"},{"type":"verse","number":"42","sanskrit":"एणः कषायो मधुरः पित्तासृक्कफवातहृत् संग्राही रोचनो बल्यो ज्वरप्रशमनः स्मृतः","text":"eṇaḥ kaṣāyo madhuraḥ pittāsṛkkaphavātahṛt saṃgrāhī rocano balyo jvarapraśamanaḥ smṛtaḥ"},{"type":"verse","number":"43","sanskrit":"कुरङ्गो बृंहणो बल्यः शीतलः पित्तहृद् गुरुः मधुरो वातहृद् ग्राही किञ्चित्कफकरः स्मृतः","text":"kuraṅgo bṛṃhaṇo balyaḥ śītalaḥ pittahṛd guruḥ madhuro vātahṛd grāhī kiñcitkaphakaraḥ smṛtaḥ"},{"type":"verse","number":"44","sanskrit":"ऋष्यो नीलाण्डकश्चापि गवयो रोझ इत्यपि गवयो मधुरो बल्यः स्निग्धोष्णः कफपित्तलः","text":"ṛṣyo nīlāṇḍakaścāpi gavayo rojha ityapi gavayo madhuro balyaḥ snigdhoṣṇaḥ kaphapittalaḥ"},{"type":"verse","number":"45","sanskrit":"पृषतस्तु भवेत्स्वादुर्ग्राहकः शीतलो लघुः दीपनो रोचनः श्वासज्वरदोषत्रयास्रजित्","text":"pṛṣatastu bhavetsvādurgrāhakaḥ śītalo laghuḥ dīpano rocanaḥ śvāsajvaradoṣatrayāsrajit"},{"type":"verse","number":"46","sanskrit":"न्यङ्कुः स्वादुर्लघुर्बल्यो वृष्यो दोषत्रयापहः","text":"nyaṅkuḥ svādurlaghurbalyo vṛṣyo doṣatrayāpahaḥ"},{"type":"verse","number":"47","sanskrit":"साबरं पललं स्निग्धं शीतलं गुरु च स्मृतम् रसे पाके च मधुरं कफदं रक्तपित्तहृत्","text":"sābaraṃ palalaṃ snigdhaṃ śītalaṃ guru ca smṛtam rase pāke ca madhuraṃ kaphadaṃ raktapittahṛt"},{"type":"verse","number":"48","sanskrit":"राजीवस्तु गुणैर्ज्ञेयः पृषतेन समो जनैः","text":"rājīvastu guṇairjñeyaḥ pṛṣatena samo janaiḥ"},{"type":"verse","number":"49","sanskrit":"मुण्डी तु ज्वरकासास्रक्षयश्वासापहो हिमः","text":"muṇḍī tu jvarakāsāsrakṣayaśvāsāpaho himaḥ"},{"type":"verse","number":"50","sanskrit":"लम्बकर्णः शशः शूली लोमकर्णो बिलेशयः शशः शीतो लघुर्ग्राही रूक्षः स्वादुः सदा हितः वह्निकृत्कफपित्तघ्नो वातसाधारणः स्मृतः ज्वरातीसारशोषास्रश्वासामयहरश्च सः","text":"lambakarṇaḥ śaśaḥ śūlī lomakarṇo bileśayaḥ śaśaḥ śīto laghurgrāhī rūkṣaḥ svāduḥ sadā hitaḥ vahnikṛtkaphapittaghno vātasādhāraṇaḥ smṛtaḥ jvarātīsāraśoṣāsraśvāsāmayaharaśca saḥ"},{"type":"verse","number":"51","sanskrit":"सेधा तु शल्यकः श्वावित्कथ्यन्ते तद्गुणा अथ शल्यकः श्वासकासास्रशोषदोषत्रयापहः","text":"sedhā tu śalyakaḥ śvāvitkathyante tadguṇā atha śalyakaḥ śvāsakāsāsraśoṣadoṣatrayāpahaḥ"},{"type":"verse","number":"52","sanskrit":"पक्षी खगो विहङ्गश्च विहगश्च विहङ्गमः शकुनिर्विः पतत्री च विष्किरो विकिरोऽण्डजः धान्याङ्कुरचरा येऽत्र तेषां मांसं लघूत्तमम् आनूपं बलकृन्मांसं स्निग्धं गुरुतरं स्मृतम्","text":"pakṣī khago vihaṅgaśca vihagaśca vihaṅgamaḥ śakunirviḥ patatrī ca viṣkiro vikiro'ṇḍajaḥ dhānyāṅkuracarā ye'tra teṣāṃ māṃsaṃ laghūttamam ānūpaṃ balakṛnmāṃsaṃ snigdhaṃ gurutaraṃ smṛtam"},{"type":"verse","number":"53","sanskrit":"वर्तीको वर्त्तकश्चित्रस्ततोऽन्या वर्त्तका स्मृता वर्त्तकोऽग्निकरः शीतो ज्वरदोषत्रयापहः सुरुच्यः शुक्रदो बल्यो वर्त्तकाऽल्पगुणा ततः","text":"vartīko varttakaścitrastato'nyā varttakā smṛtā varttako'gnikaraḥ śīto jvaradoṣatrayāpahaḥ surucyaḥ śukrado balyo varttakā'lpaguṇā tataḥ"},{"type":"verse","number":"54","sanskrit":"लावा विष्करवर्गेषु ते चतुर्धा मता बुधैः","text":"lāvā viṣkaravargeṣu te caturdhā matā budhaiḥ"},{"type":"verse","number":"55","sanskrit":"पांशुलोगौरकोऽन्यस्तु पौण्ड्रको दर्भरस्तथा लावा वह्निकराः स्निग्धा गरघ्ना ग्राहका हिताः","text":"pāṃśulogaurako'nyastu pauṇḍrako darbharastathā lāvā vahnikarāḥ snigdhā garaghnā grāhakā hitāḥ"},{"type":"verse","number":"56","sanskrit":"पांशुलः श्लेष्मलस्तेषु वीर्योऽष्णोनिलनाशनः गौरोलघुतरो रूक्षो वह्निकारी त्रिदोषजित्","text":"pāṃśulaḥ śleṣmalasteṣu vīryo'ṣṇonilanāśanaḥ gaurolaghutaro rūkṣo vahnikārī tridoṣajit"},{"type":"verse","number":"57","sanskrit":"पौण्ड्रकः पित्तकृत्किञ्चिल्लघुर्वातकफापहः दर्भरो रक्तपित्तघ्नो हृदामयहरो हिमः","text":"pauṇḍrakaḥ pittakṛtkiñcillaghurvātakaphāpahaḥ darbharo raktapittaghno hṛdāmayaharo himaḥ"},{"type":"verse","number":"58","sanskrit":"वर्त्तीको वर्त्तिचटको वार्त्तीकश्चैव स स्मृतः वर्त्तीको मधुरः शीतो रूक्षश्च कफपित्तनुत्","text":"varttīko vartticaṭako vārttīkaścaiva sa smṛtaḥ varttīko madhuraḥ śīto rūkṣaśca kaphapittanut"},{"type":"verse","number":"59","sanskrit":"तित्तिरिः कृष्णवर्णः स्यात्स तु गौरः कपिञ्जलः तित्तिरिर्बलदो ग्राही हिक्कादोषत्रयापहः श्वासकासज्वरहरस्तस्माद्गौरोऽधिको गुणैः","text":"tittiriḥ kṛṣṇavarṇaḥ syātsa tu gauraḥ kapiñjalaḥ tittirirbalado grāhī hikkādoṣatrayāpahaḥ śvāsakāsajvaraharastasmādgauro'dhiko guṇaiḥ"},{"type":"verse","number":"60","sanskrit":"चटकः कलविङ्कः स्यात्कुलिङ्गः कालकण्ठकः","text":"caṭakaḥ kalaviṅkaḥ syātkuliṅgaḥ kālakaṇṭhakaḥ"},{"type":"verse","number":"61","sanskrit":"कुलिङ्गः शीतलः स्निग्धः स्वादुः शुक्रकफप्रदः सन्निपातहरो वेश्मचटकश्चातिशुक्रलः","text":"kuliṅgaḥ śītalaḥ snigdhaḥ svāduḥ śukrakaphapradaḥ sannipātaharo veśmacaṭakaścātiśukralaḥ"},{"type":"verse","number":"62","sanskrit":"कुक्कुटः कृकवाकुः स्यात्कालज्ञश्चरणायुधः ताम्रचूडस्तथा दक्षो यामनादी शिखण्डिकः","text":"kukkuṭaḥ kṛkavākuḥ syātkālajñaścaraṇāyudhaḥ tāmracūḍastathā dakṣo yāmanādī śikhaṇḍikaḥ"},{"type":"verse","number":"63","sanskrit":"कुक्कुटो बृंहणः स्निग्धो वीर्योष्णोऽनिलहृद् गुरुः चक्षुष्यः शुक्रकफकृद् बल्यो वृष्यः कषायकः","text":"kukkuṭo bṛṃhaṇaḥ snigdho vīryoṣṇo'nilahṛd guruḥ cakṣuṣyaḥ śukrakaphakṛd balyo vṛṣyaḥ kaṣāyakaḥ"},{"type":"verse","number":"64","sanskrit":"आरण्यकुक्कुटः स्निग्धो बृंहणः श्लेष्मलो गुरुः वातपित्तक्षयवमिविषमज्वरनाशनः","text":"āraṇyakukkuṭaḥ snigdho bṛṃhaṇaḥ śleṣmalo guruḥ vātapittakṣayavamiviṣamajvaranāśanaḥ"},{"type":"verse","number":"65","sanskrit":"हारीतो रक्तपीतः स्याद्धरितोऽपि स कथ्यते हारीतो रूक्ष उष्णश्च रक्तपित्तकफापहः स्वेदस्वरकरः प्रोक्तः ईषद्वातकरश्च सः","text":"hārīto raktapītaḥ syāddharito'pi sa kathyate hārīto rūkṣa uṣṇaśca raktapittakaphāpahaḥ svedasvarakaraḥ proktaḥ īṣadvātakaraśca saḥ"},{"type":"verse","number":"66","sanskrit":"पाण्डुस्तु द्विविधो ज्ञेयश्चित्रपक्षः कलध्वनिः","text":"pāṇḍustu dvividho jñeyaścitrapakṣaḥ kaladhvaniḥ"},{"type":"verse","number":"67","sanskrit":"द्वितीयो धवलः प्रोक्तः स कपोतः स्फुटध्वनिः चित्रपक्षः कफहरो वातघ्नो ग्रहणीप्रणुत्","text":"dvitīyo dhavalaḥ proktaḥ sa kapotaḥ sphuṭadhvaniḥ citrapakṣaḥ kaphaharo vātaghno grahaṇīpraṇut"},{"type":"verse","number":"68","sanskrit":"धवलः पाण्डुरुद्दिष्टो रक्तपित्तहरो हिमः रसे पाके च मधुरः संग्राही वातशान्तिकृत्","text":"dhavalaḥ pāṇḍuruddiṣṭo raktapittaharo himaḥ rase pāke ca madhuraḥ saṃgrāhī vātaśāntikṛt"},{"type":"verse","number":"69","sanskrit":"मयूरश्चन्द्र की केकी मेघरावो भुजङ्गभुक् शिखी शिखावलो बर्ही शिखण्डी नीलकण्ठकः","text":"mayūraścandra kī kekī megharāvo bhujaṅgabhuk śikhī śikhāvalo barhī śikhaṇḍī nīlakaṇṭhakaḥ"},{"type":"verse","number":"70","sanskrit":"शुक्लापाङ्गः कलापी च मेघनादानुलास्यपि रसे पाके च मधुरः संग्राही वातशान्तिकृत्","text":"śuklāpāṅgaḥ kalāpī ca meghanādānulāsyapi rase pāke ca madhuraḥ saṃgrāhī vātaśāntikṛt"},{"type":"verse","number":"71","sanskrit":"पारावतः कलरवः कपोतो रक्तलोचनः पारावतो गुरुः स्निग्धो रक्तपित्तानिलापहः संग्राही शीतलस्तज्ज्ञैः कथितो वीर्यवर्द्धनः","text":"pārāvataḥ kalaravaḥ kapoto raktalocanaḥ pārāvato guruḥ snigdho raktapittānilāpahaḥ saṃgrāhī śītalastajjñaiḥ kathito vīryavarddhanaḥ"},{"type":"verse","number":"72","sanskrit":"नातिस्निग्धानि वृष्याणि स्वादुपाकरसानि च वातघ्नान्यतिशुक्राणि गुरूण्यण्डानि पक्षिणाम्","text":"nātisnigdhāni vṛṣyāṇi svādupākarasāni ca vātaghnānyatiśukrāṇi gurūṇyaṇḍāni pakṣiṇām"},{"type":"verse","number":"73","sanskrit":"छागलो बर्करश्छागो बस्तोऽजश्छेलकः स्तुभः","text":"chāgalo barkaraśchāgo basto'jaśchelakaḥ stubhaḥ"},{"type":"verse","number":"74","sanskrit":"अजा छागी स्तुभा चापि छेलिका च गलस्तनी छागमांसं लघु स्निग्धं स्वादुपाकं त्रिदोषनुत्","text":"ajā chāgī stubhā cāpi chelikā ca galastanī chāgamāṃsaṃ laghu snigdhaṃ svādupākaṃ tridoṣanut"},{"type":"verse","number":"75","sanskrit":"नातिशीतमदाहि स्यात्स्वादु पीनसनाशनम् परं बलकरं रुच्यं बृहणं वीर्यवर्द्धनम्","text":"nātiśītamadāhi syātsvādu pīnasanāśanam paraṃ balakaraṃ rucyaṃ bṛhaṇaṃ vīryavarddhanam"},{"type":"verse","number":"76","sanskrit":"अजायास्त्वप्रसूताया मांसं पीनसनाशनम् शुष्ककासेऽरुचौ शोषे हितमग्नेश्च दीपनम्","text":"ajāyāstvaprasūtāyā māṃsaṃ pīnasanāśanam śuṣkakāse'rucau śoṣe hitamagneśca dīpanam"},{"type":"verse","number":"77","sanskrit":"अजासुतस्य बालस्य मांसं लघुतरं स्मृतम् हृद्यं ज्वरहरं श्रेष्ठं सुखदं बलदं भृशम्","text":"ajāsutasya bālasya māṃsaṃ laghutaraṃ smṛtam hṛdyaṃ jvaraharaṃ śreṣṭhaṃ sukhadaṃ baladaṃ bhṛśam"},{"type":"verse","number":"78","sanskrit":"मासंनिष्कासिताण्डस्य छागस्य कफकृद् गुरु स्रोतःशुद्धिकरं बल्यं मांसदं वातपित्तनुत्","text":"māsaṃniṣkāsitāṇḍasya chāgasya kaphakṛd guru srotaḥśuddhikaraṃ balyaṃ māṃsadaṃ vātapittanut"},{"type":"verse","number":"79","sanskrit":"वृद्धस्य वातलं रूक्षं तथा व्याधिमृतस्य च ऊर्ध्वजत्रुविकारघ्नं छागमुण्डं रुचिप्रदम्","text":"vṛddhasya vātalaṃ rūkṣaṃ tathā vyādhimṛtasya ca ūrdhvajatruvikāraghnaṃ chāgamuṇḍaṃ rucipradam"},{"type":"verse","number":"80","sanskrit":"अथ मेषः मिए!ढाइ! तस्य नामान्यण्डविहीनस्य तस्य च मेढ्रो मेढो हुडो मेष उरणोऽप्येडकोऽपि च अविर्वृष्णिस्तथोर्णायुः कथ्यन्ते तद्गुणा अथ","text":"atha meṣaḥ mie!ḍhāi! tasya nāmānyaṇḍavihīnasya tasya ca meḍhro meḍho huḍo meṣa uraṇo'pyeḍako'pi ca avirvṛṣṇistathorṇāyuḥ kathyante tadguṇā atha"},{"type":"verse","number":"81","sanskrit":"मेषस्य मांसं पुष्टौ स्यात्पित्तश्लेष्मकरं गुरु तस्यैवाण्डविहीनस्य मांसं किञ्चिल्लघु स्मृतम्","text":"meṣasya māṃsaṃ puṣṭau syātpittaśleṣmakaraṃ guru tasyaivāṇḍavihīnasya māṃsaṃ kiñcillaghu smṛtam"},{"type":"verse","number":"82","sanskrit":"अथैडकः दिउ!म्बा मेढाइ! तस्य नामानि तद्भेदस्य च एडकः पृथुशृङ्गः स्यान्मेदः पुच्छस्तु दुम्बकः एडकस्य पलं ज्ञेयं मेषामिषसमं गुणैः","text":"athaiḍakaḥ diu!mbā meḍhāi! tasya nāmāni tadbhedasya ca eḍakaḥ pṛthuśṛṅgaḥ syānmedaḥ pucchastu dumbakaḥ eḍakasya palaṃ jñeyaṃ meṣāmiṣasamaṃ guṇaiḥ"},{"type":"verse","number":"83","sanskrit":"मेदः पुच्छोद्भवं मांसं हृद्यं वृष्यं श्रमापहम् पित्तश्लेष्मकरं किञ्चिद्वातव्याधिविनाशानम्","text":"medaḥ pucchodbhavaṃ māṃsaṃ hṛdyaṃ vṛṣyaṃ śramāpaham pittaśleṣmakaraṃ kiñcidvātavyādhivināśānam"},{"type":"verse","number":"84","sanskrit":"बलीवर्दस्तु वृषभः ऋषभश्च तथा वृषः अनड्वान्सौरभेयोऽपि गौरुक्षा भद्र इत्यपि","text":"balīvardastu vṛṣabhaḥ ṛṣabhaśca tathā vṛṣaḥ anaḍvānsaurabheyo'pi gaurukṣā bhadra ityapi"},{"type":"verse","number":"85","sanskrit":"सुरभिः सौरभेयी च माहेयी गौरुदाहृता गोमांसं सुगुरु स्निग्धं पित्तश्लेष्मविवर्द्धनम् बृंहणं वातहृत् बल्यमपथ्यं पीनसप्रणुत्","text":"surabhiḥ saurabheyī ca māheyī gaurudāhṛtā gomāṃsaṃ suguru snigdhaṃ pittaśleṣmavivarddhanam bṛṃhaṇaṃ vātahṛt balyamapathyaṃ pīnasapraṇut"},{"type":"verse","number":"86","sanskrit":"घोटकेऽप्यश्वतुरगास्तुरङ्गमाश्च तुरङ्गाः बाजिवाहार्वगन्धर्वहयसैन्धवसप्तयः","text":"ghoṭake'pyaśvaturagāsturaṅgamāśca turaṅgāḥ bājivāhārvagandharvahayasaindhavasaptayaḥ"},{"type":"verse","number":"87","sanskrit":"अश्वमांसन्तु तुवरं वह्निकृत्कफपित्तलम् वातहृद् बृहणं बल्यं चक्षुष्यं मधुरं लघु","text":"aśvamāṃsantu tuvaraṃ vahnikṛtkaphapittalam vātahṛd bṛhaṇaṃ balyaṃ cakṣuṣyaṃ madhuraṃ laghu"},{"type":"verse","number":"88","sanskrit":"महिषो घोटकारिः स्यात्कासरश्च रजस्वलः","text":"mahiṣo ghoṭakāriḥ syātkāsaraśca rajasvalaḥ"},{"type":"verse","number":"89","sanskrit":"पीनस्कन्धः कृष्णकायो लुलायो यमवाहनः महिषस्यामिषं स्वादु स्निग्धोष्णं वातनाशनम्","text":"pīnaskandhaḥ kṛṣṇakāyo lulāyo yamavāhanaḥ mahiṣasyāmiṣaṃ svādu snigdhoṣṇaṃ vātanāśanam"},{"type":"verse","number":"90","sanskrit":"निद्रा शुक्रप्रदं बल्यं तनुदार्ढ्यकरं गुरु वृष्यञ्च सृष्टविण्मूत्रं वातपित्तास्रनाशनम्","text":"nidrā śukrapradaṃ balyaṃ tanudārḍhyakaraṃ guru vṛṣyañca sṛṣṭaviṇmūtraṃ vātapittāsranāśanam"},{"type":"verse","number":"91","sanskrit":"मण्डूकः प्लवगो भेको वर्षाभूर्दर्दुरो हरिः मण्डूकः श्लेष्मलो नातिपित्तलो बलकारकः","text":"maṇḍūkaḥ plavago bheko varṣābhūrdarduro hariḥ maṇḍūkaḥ śleṣmalo nātipittalo balakārakaḥ"},{"type":"verse","number":"92","sanskrit":"कच्छपो गूढपात्कूर्मः कमठो दृढपृष्ठकः कच्छपो बलदो वातपित्तनुत्पुंस्त्वकारकः","text":"kacchapo gūḍhapātkūrmaḥ kamaṭho dṛḍhapṛṣṭhakaḥ kacchapo balado vātapittanutpuṃstvakārakaḥ"},{"type":"verse","number":"93","sanskrit":"सद्योहतस्य मांसं स्थाद्व्याधिघाति यथाऽमृतम् वयस्यं बृंहणं सात्म्यमन्यथा तद् विवर्जयेत्","text":"sadyohatasya māṃsaṃ sthādvyādhighāti yathā'mṛtam vayasyaṃ bṛṃhaṇaṃ sātmyamanyathā tad vivarjayet"},{"type":"verse","number":"94","sanskrit":"स्वयं मृतस्य चाबल्यमतीसारकरं गुरु","text":"svayaṃ mṛtasya cābalyamatīsārakaraṃ guru"},{"type":"verse","number":"95","sanskrit":"वृद्धानां दोषलं मांसं बालानां बलदं लघु","text":"vṛddhānāṃ doṣalaṃ māṃsaṃ bālānāṃ baladaṃ laghu"},{"type":"verse","number":"96","sanskrit":"सर्पदष्टस्य मांसञ्च शुष्कमांस त्रिदोषकृत् त्रिदोषकृद् व्यालदष्टं शुष्कं शूलकरं परम्","text":"sarpadaṣṭasya māṃsañca śuṣkamāṃsa tridoṣakṛt tridoṣakṛd vyāladaṣṭaṃ śuṣkaṃ śūlakaraṃ param"},{"type":"verse","number":"97","sanskrit":"क्लिन्नमुत्क्लेशजनकं कृशं वातप्रकोपणम् तोयपूर्णं शिराराजं मृतमप्सु त्रिदोषकृत्","text":"klinnamutkleśajanakaṃ kṛśaṃ vātaprakopaṇam toyapūrṇaṃ śirārājaṃ mṛtamapsu tridoṣakṛt"},{"type":"verse","number":"98","sanskrit":"विहङ्गेषु पुमाञ्छ्रेष्ठः स्त्री चतुष्पदजातिषु परार्द्धं लघु पुंसां स्यात्स्त्रीणां पूर्वार्द्धमादिशेत् देहमध्यं गुरुप्रायं सर्वेषां प्राणिनां स्मृतम्","text":"vihaṅgeṣu pumāñchreṣṭhaḥ strī catuṣpadajātiṣu parārddhaṃ laghu puṃsāṃ syātstrīṇāṃ pūrvārddhamādiśet dehamadhyaṃ guruprāyaṃ sarveṣāṃ prāṇināṃ smṛtam"},{"type":"verse","number":"99","sanskrit":"पक्षक्षेपाद्विहङ्गानां तदेव लघु कथ्यते गुरूण्यण्डानि सर्वेषां गुर्वी ग्रीवा च पक्षिणाम्","text":"pakṣakṣepādvihaṅgānāṃ tadeva laghu kathyate gurūṇyaṇḍāni sarveṣāṃ gurvī grīvā ca pakṣiṇām"},{"type":"verse","number":"100","sanskrit":"उरः स्कन्धोदरं कुक्षी पादौ पाणी कटी तथा पृष्ठत्वग्यकृदन्त्राणि गुरूणीह यथोत्तरम्","text":"uraḥ skandhodaraṃ kukṣī pādau pāṇī kaṭī tathā pṛṣṭhatvagyakṛdantrāṇi gurūṇīha yathottaram"},{"type":"verse","number":"101","sanskrit":"लघुवातकरं मांसं खगानां धान्यचारिणाम् मत्स्याशिनां पित्तकरं वातघ्नं गुरु कीर्त्तितम्","text":"laghuvātakaraṃ māṃsaṃ khagānāṃ dhānyacāriṇām matsyāśināṃ pittakaraṃ vātaghnaṃ guru kīrttitam"},{"type":"verse","number":"102","sanskrit":"फलाशिनां श्लेष्मकरं लघु रूक्षमुदीरितम् बृंहणं गुरु वातघ्नं तेषामेव पलाशिनाम्","text":"phalāśināṃ śleṣmakaraṃ laghu rūkṣamudīritam bṛṃhaṇaṃ guru vātaghnaṃ teṣāmeva palāśinām"},{"type":"verse","number":"103","sanskrit":"तुल्यजातिष्वल्पदेहा महादेहेषु पूजिताः अल्पदेहेषु शस्यन्ते तथैव स्थूलदेहिनाः","text":"tulyajātiṣvalpadehā mahādeheṣu pūjitāḥ alpadeheṣu śasyante tathaiva sthūladehināḥ"},{"type":"verse","number":"104","sanskrit":"रक्तोदरो रक्तमुखो रक्ताक्षो रक्तपक्षतिः कृष्णपुच्छो झषः श्रेष्ठो रोहितः कथितो बुधैः","text":"raktodaro raktamukho raktākṣo raktapakṣatiḥ kṛṣṇapuccho jhaṣaḥ śreṣṭho rohitaḥ kathito budhaiḥ"},{"type":"verse","number":"105","sanskrit":"रोहितः सर्वमत्स्यानां वरो वृष्योऽदितार्त्तिजित् कषायानुरसः स्वादुर्वातघ्नो नातिपित्तकृत् ऊर्ध्वजत्रुगतान् रोगान् हन्याद्रो हितमुण्डकम्","text":"rohitaḥ sarvamatsyānāṃ varo vṛṣyo'ditārttijit kaṣāyānurasaḥ svādurvātaghno nātipittakṛt ūrdhvajatrugatān rogān hanyādro hitamuṇḍakam"},{"type":"verse","number":"106","sanskrit":"शिलीन्ध्रः श्लेष्मलो बल्यो विपाके मधुरो गुरुः वातपित्तहरो हृद्यः आमवातकरश्च सः","text":"śilīndhraḥ śleṣmalo balyo vipāke madhuro guruḥ vātapittaharo hṛdyaḥ āmavātakaraśca saḥ"},{"type":"verse","number":"107","sanskrit":"भाकुरो मधुरः शीतो वृष्यः श्लेष्मकरो गुरुः विष्टम्भजनकश्चापि रक्तपित्तहरः स्मृतः","text":"bhākuro madhuraḥ śīto vṛṣyaḥ śleṣmakaro guruḥ viṣṭambhajanakaścāpi raktapittaharaḥ smṛtaḥ"},{"type":"verse","number":"108","sanskrit":"मोचिका वातहृद् बल्या बृंहणी मधुरा गुरुः पित्तहृत्कफकृद्रुच्या वृष्या दीप्ताग्नये हिता","text":"mocikā vātahṛd balyā bṛṃhaṇī madhurā guruḥ pittahṛtkaphakṛdrucyā vṛṣyā dīptāgnaye hitā"},{"type":"verse","number":"109","sanskrit":"पाठीनः श्लेष्मलो बल्यो निद्रा लुः पिशिताशनः दूषयेद्रुधिरं पित्तं कुष्ठरोगं करोति च","text":"pāṭhīnaḥ śleṣmalo balyo nidrā luḥ piśitāśanaḥ dūṣayedrudhiraṃ pittaṃ kuṣṭharogaṃ karoti ca"},{"type":"verse","number":"110","sanskrit":"शृङ्गी तु वातशमनी स्निग्धा श्लेष्मप्रकोपणी रसे तिक्ता कषाया च लघ्वी रुच्या स्मृताबुधैः","text":"śṛṅgī tu vātaśamanī snigdhā śleṣmaprakopaṇī rase tiktā kaṣāyā ca laghvī rucyā smṛtābudhaiḥ"},{"type":"verse","number":"111","sanskrit":"इल्लीसो मधुरः स्निग्धो रोचनो वह्निवर्द्धनः पित्तहृत्कफकृत्किञ्चिल्लघुर्वृष्योऽनिलापहः","text":"illīso madhuraḥ snigdho rocano vahnivarddhanaḥ pittahṛtkaphakṛtkiñcillaghurvṛṣyo'nilāpahaḥ"},{"type":"verse","number":"112","sanskrit":"शष्कुली ग्राहिणी हृद्या मधुरा तुवरा स्मृता","text":"śaṣkulī grāhiṇī hṛdyā madhurā tuvarā smṛtā"},{"type":"verse","number":"113","sanskrit":"गर्गरः पित्तलः किञ्चिद्वातजित्कफकोपनः","text":"gargaraḥ pittalaḥ kiñcidvātajitkaphakopanaḥ"},{"type":"verse","number":"114","sanskrit":"कविका मधुरा स्निग्धा कफघ्नी रुचिकारिणी कञ्चित्पित्तकरी वातनाशिनी वह्निवर्द्धिनी","text":"kavikā madhurā snigdhā kaphaghnī rucikāriṇī kañcitpittakarī vātanāśinī vahnivarddhinī"},{"type":"verse","number":"115","sanskrit":"वर्मिमत्स्यो हरेद्वातं पित्तं रुचिकरो लघुः","text":"varmimatsyo haredvātaṃ pittaṃ rucikaro laghuḥ"},{"type":"verse","number":"116","sanskrit":"दण्डमत्स्यो रसे तिक्तः पित्तरक्तं कफं हरेत् वातसाधारणः प्रोक्तः शुक्रलो बलवर्द्धनः","text":"daṇḍamatsyo rase tiktaḥ pittaraktaṃ kaphaṃ haret vātasādhāraṇaḥ proktaḥ śukralo balavarddhanaḥ"},{"type":"verse","number":"117","sanskrit":"एरङ्गो मधुरः स्निग्धो विष्टम्भी शीतलो लघुः","text":"eraṅgo madhuraḥ snigdho viṣṭambhī śītalo laghuḥ"},{"type":"verse","number":"118","sanskrit":"महाशफरसंज्ञस्तु तिक्तः पित्तकफापहः शिशिरो मधुरो रुच्यो वातसाधारणः स्मृतः","text":"mahāśapharasaṃjñastu tiktaḥ pittakaphāpahaḥ śiśiro madhuro rucyo vātasādhāraṇaḥ smṛtaḥ"},{"type":"verse","number":"119","sanskrit":"गरघ्नी मधुरा तिक्ता तुवरा वातपित्तहृत् कफघ्नी रुचिकृल्लघ्वी दीपनी बलवीर्यकृत्","text":"garaghnī madhurā tiktā tuvarā vātapittahṛt kaphaghnī rucikṛllaghvī dīpanī balavīryakṛt"},{"type":"verse","number":"120","sanskrit":"मद्गुरो वातहृद् बल्यो वृष्यः कफकरो लघुः","text":"madguro vātahṛd balyo vṛṣyaḥ kaphakaro laghuḥ"},{"type":"verse","number":"121","sanskrit":"सपादमत्स्यो मेधाकृन्मेदः क्षयकरश्च सः वातपित्तकरश्चापि रुचिकृत्परमो मतः","text":"sapādamatsyo medhākṛnmedaḥ kṣayakaraśca saḥ vātapittakaraścāpi rucikṛtparamo mataḥ"},{"type":"verse","number":"122","sanskrit":"प्रोष्ठी तिक्ता कटुः स्वादुः शुक्रदा कफवातजित् स्निग्धाऽस्यकण्ठरोगघ्नी रोचनी च लघुः स्मृता","text":"proṣṭhī tiktā kaṭuḥ svāduḥ śukradā kaphavātajit snigdhā'syakaṇṭharogaghnī rocanī ca laghuḥ smṛtā"},{"type":"verse","number":"123","sanskrit":"क्षुद्र मत्स्याः स्वादुरसा दोषत्रयविनाशनाः लघुपाका रुचिकरा बलदास्ते हिता मताः","text":"kṣudra matsyāḥ svādurasā doṣatrayavināśanāḥ laghupākā rucikarā baladāste hitā matāḥ"},{"type":"verse","number":"124","sanskrit":"अतिसूक्ष्माः पुंस्त्वहरा रुच्याः कासानिलापहाः","text":"atisūkṣmāḥ puṃstvaharā rucyāḥ kāsānilāpahāḥ"},{"type":"verse","number":"125","sanskrit":"मत्स्यगर्भो भृशं वृष्यः स्निग्धः पुष्टिकरो लघुः कफमेदःप्रदो बल्यो ग्लानिकृन्मेहनाशनः","text":"matsyagarbho bhṛśaṃ vṛṣyaḥ snigdhaḥ puṣṭikaro laghuḥ kaphamedaḥprado balyo glānikṛnmehanāśanaḥ"},{"type":"verse","number":"126","sanskrit":"शुष्कमत्स्या नवा बल्या दुर्जरा विड्विबन्धिनः","text":"śuṣkamatsyā navā balyā durjarā viḍvibandhinaḥ"},{"type":"verse","number":"127","sanskrit":"दग्धमत्स्यो गुणैः श्रेष्ठः पुष्टिकृद् बलवर्द्धनः","text":"dagdhamatsyo guṇaiḥ śreṣṭhaḥ puṣṭikṛd balavarddhanaḥ"},{"type":"verse","number":"128","sanskrit":"कौपमत्स्याः शुक्रमूत्रकुष्ठश्लेष्मविवर्द्धनाः सरोजा मधुराः स्निग्धा बल्या वातविनाशनाः नादेया बृंहणा मत्स्या गुरवोऽनिलनाशनाः रक्तपित्तकरा वृष्याः स्निग्धोष्णाः स्वल्पवर्चसः चौञ्ज्याः पित्तकराः स्निग्धा मधुरा लघवो हिमाः तडागा गुरवो वृष्याः शीतला मलमूत्रदाः ताडागवन्निर्झरजा बलायुर्मतिदृक्कराः","text":"kaupamatsyāḥ śukramūtrakuṣṭhaśleṣmavivarddhanāḥ sarojā madhurāḥ snigdhā balyā vātavināśanāḥ nādeyā bṛṃhaṇā matsyā guravo'nilanāśanāḥ raktapittakarā vṛṣyāḥ snigdhoṣṇāḥ svalpavarcasaḥ cauñjyāḥ pittakarāḥ snigdhā madhurā laghavo himāḥ taḍāgā guravo vṛṣyāḥ śītalā malamūtradāḥ tāḍāgavannirjharajā balāyurmatidṛkkarāḥ"},{"type":"verse","number":"129","sanskrit":"हेमन्ते कूपजा मत्स्याः शिशिरे सारसा हिताः वसन्ते ते तु नादेया ग्रीष्मे चौञ्ज्यसमुद्भवाः तडागजाता वर्षासु तास्वपथ्या नदीभवाः नैर्झरा शरदि श्रेष्ठा विशेषोऽयमुदाहृतः","text":"hemante kūpajā matsyāḥ śiśire sārasā hitāḥ vasante te tu nādeyā grīṣme cauñjyasamudbhavāḥ taḍāgajātā varṣāsu tāsvapathyā nadībhavāḥ nairjharā śaradi śreṣṭhā viśeṣo'yamudāhṛtaḥ"},{"type":"verse","number":"11","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे एकादशो मांसवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe ekādaśo māṃsavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":11,"lang":"sa","content":[{"type":"heading","heading":"kṛtānna-варга — приготовленная пища"},{"type":"verse","number":"1","sanskrit":"समवायिनि हेतौ ये मुनिभिर्गणिता गुणाः कार्येऽपि तेऽखिलाज्ञेयाः परिभाषेति भाषिताः","text":"samavāyini hetau ye munibhirgaṇitā guṇāḥ kārye'pi te'khilājñeyāḥ paribhāṣeti bhāṣitāḥ"},{"type":"verse","number":"2","sanskrit":"क्वचित्संस्कारभेदेन गुणभेदो भवेद्यतः भक्तं लघु पुराणस्यशालेस्तच्चिपिटो गुरुः","text":"kvacitsaṃskārabhedena guṇabhedo bhavedyataḥ bhaktaṃ laghu purāṇasyaśālestaccipiṭo guruḥ"},{"type":"verse","number":"3","sanskrit":"क्वचिद्योगप्रभावेण गुणान्तरमपेक्षते कदन्नं गुरु सर्पिश्च तद्युक्तं सुपचं भवेत्","text":"kvacidyogaprabhāveṇa guṇāntaramapekṣate kadannaṃ guru sarpiśca tadyuktaṃ supacaṃ bhavet"},{"type":"verse","number":"4","sanskrit":"भक्तमन्नं तथाऽन्धश्च क्वचित्कूरं च कीर्त्तितम् ओदनोऽस्त्री स्रियां भिस्सा दीदिविः पुंसि भाषितः","text":"bhaktamannaṃ tathā'ndhaśca kvacitkūraṃ ca kīrttitam odano'strī sriyāṃ bhissā dīdiviḥ puṃsi bhāṣitaḥ"},{"type":"verse","number":"5","sanskrit":"सुधौतांस्तण्डुलान् स्फीतांस्तोये पञ्चगुणे पचेत् तदुक्तं प्रस्रुतं चोष्णं विशदं गुणवन्मतम्","text":"sudhautāṃstaṇḍulān sphītāṃstoye pañcaguṇe pacet taduktaṃ prasrutaṃ coṣṇaṃ viśadaṃ guṇavanmatam"},{"type":"verse","number":"6","sanskrit":"भक्तं वह्निकरं पथ्यं तर्पणं रोचनं लघु अधौतमस्रुतं शीतं गुर्वरुच्यं कफप्रदम्","text":"bhaktaṃ vahnikaraṃ pathyaṃ tarpaṇaṃ rocanaṃ laghu adhautamasrutaṃ śītaṃ gurvarucyaṃ kaphapradam"},{"type":"verse","number":"7","sanskrit":"दलितन्तु शमीधान्यं दालिर्दाली स्त्रियामुभे दाली तु सलिले सिद्धा लवणार्द्र कहिङ्गुभिः","text":"dalitantu śamīdhānyaṃ dālirdālī striyāmubhe dālī tu salile siddhā lavaṇārdra kahiṅgubhiḥ"},{"type":"verse","number":"8","sanskrit":"संयुक्ता सूपनाम्नी स्यात्कथ्यन्ते तद्गुणा अथ सूपो विष्टम्भको रूक्षः शीतस्तु स विशेषतः निस्तुषो भृष्टसंसिद्धो लाघवं सुतरां व्रजेत्","text":"saṃyuktā sūpanāmnī syātkathyante tadguṇā atha sūpo viṣṭambhako rūkṣaḥ śītastu sa viśeṣataḥ nistuṣo bhṛṣṭasaṃsiddho lāghavaṃ sutarāṃ vrajet"},{"type":"verse","number":"9","sanskrit":"तण्डुला दालिसंमिश्रा लवणार्द्र कहिङ्गुभिः संयुक्ताः सलिले सिद्धाः कृशरा कथिता बुधैः","text":"taṇḍulā dālisaṃmiśrā lavaṇārdra kahiṅgubhiḥ saṃyuktāḥ salile siddhāḥ kṛśarā kathitā budhaiḥ"},{"type":"verse","number":"10","sanskrit":"कृशरा शुक्रला बल्या गुरुः पित्तकफप्रदा दुर्जरा बुद्धिविष्टम्भमलमूत्रकरी स्मृता","text":"kṛśarā śukralā balyā guruḥ pittakaphapradā durjarā buddhiviṣṭambhamalamūtrakarī smṛtā"},{"type":"verse","number":"11","sanskrit":"वृते हरिद्रा संयुक्ते माषजा भर्जयेद्वटीम्","text":"vṛte haridrā saṃyukte māṣajā bharjayedvaṭīm"},{"type":"verse","number":"12","sanskrit":"तण्डुलांश्चापि निर्धौतान्सहैव परिभर्जयेत् सिद्धयोग्यं जलं तत्र प्रक्षिप्य कुशलः पचेत्","text":"taṇḍulāṃścāpi nirdhautānsahaiva paribharjayet siddhayogyaṃ jalaṃ tatra prakṣipya kuśalaḥ pacet"},{"type":"verse","number":"13","sanskrit":"लवणार्द्र कहिङ्गूनि मात्रया तत्र निक्षिपेत् एषा सिद्धि समायाता प्रोक्ता तापहरी बुधैः","text":"lavaṇārdra kahiṅgūni mātrayā tatra nikṣipet eṣā siddhi samāyātā proktā tāpaharī budhaiḥ"},{"type":"verse","number":"14","sanskrit":"भवेत्तापहरी बल्या वृष्या श्लेष्माणमाचरेत् बृंहणी तर्पणी रुच्या गुर्वी पित्तहरी स्मृता","text":"bhavettāpaharī balyā vṛṣyā śleṣmāṇamācaret bṛṃhaṇī tarpaṇī rucyā gurvī pittaharī smṛtā"},{"type":"verse","number":"15","sanskrit":"पायसं परमान्नं स्यात्क्षीरिकाऽपि तदुच्यते शुद्धेर्द्धऽपक्वे दुग्धे तु घृताक्तांस्तण्डुलान्पचेत्","text":"pāyasaṃ paramānnaṃ syātkṣīrikā'pi taducyate śuddherddha'pakve dugdhe tu ghṛtāktāṃstaṇḍulānpacet"},{"type":"verse","number":"16","sanskrit":"ते सिद्धाः क्षीरिका ख्याताः ससिताऽज्ययुतोत्तमा क्षीरिका दुर्जरा प्रोक्ता बृंहणी बलवर्द्धिनी विष्टम्भिनी हरेत् पित्तं रक्तपित्ताग्निमारुतान्","text":"te siddhāḥ kṣīrikā khyātāḥ sasitā'jyayutottamā kṣīrikā durjarā proktā bṛṃhaṇī balavarddhinī viṣṭambhinī haret pittaṃ raktapittāgnimārutān"},{"type":"verse","number":"17","sanskrit":"नारिकेरं तनूकृत्य छिन्नं पयसि गोः क्षिपेत् सितागव्याज्यसंयुक्ते तत्पचेन्मृदुनाऽग्निना","text":"nārikeraṃ tanūkṛtya chinnaṃ payasi goḥ kṣipet sitāgavyājyasaṃyukte tatpacenmṛdunā'gninā"},{"type":"verse","number":"18","sanskrit":"नारिकेरोद्भवा क्षीरी स्निग्धा शीताऽतिपुष्टिदा गुर्वी सुमधुरावृष्या रक्तपित्तानिलापहा","text":"nārikerodbhavā kṣīrī snigdhā śītā'tipuṣṭidā gurvī sumadhurāvṛṣyā raktapittānilāpahā"},{"type":"verse","number":"19","sanskrit":"समितावर्त्तिकाः कृत्वा सुसूक्ष्मा यवसन्निभा शुष्काः क्षीरेणसंसाध्या भोज्यावृत्तसिताऽन्विताः","text":"samitāvarttikāḥ kṛtvā susūkṣmā yavasannibhā śuṣkāḥ kṣīreṇasaṃsādhyā bhojyāvṛttasitā'nvitāḥ"},{"type":"verse","number":"20","sanskrit":"सेविका तर्पणी बल्या गुर्वी पित्तानिलापहा ग्राहिणी सन्धिकृद्रुच्या तां खादेन्नातिमात्रया","text":"sevikā tarpaṇī balyā gurvī pittānilāpahā grāhiṇī sandhikṛdrucyā tāṃ khādennātimātrayā"},{"type":"verse","number":"21","sanskrit":"गोधूमा धवला धौताः कुट्टिताः शोषितास्ततः प्रोक्षितायन्त्रनिष्पष्टाश्चालिताः समिताः स्मृताः","text":"godhūmā dhavalā dhautāḥ kuṭṭitāḥ śoṣitāstataḥ prokṣitāyantraniṣpaṣṭāścālitāḥ samitāḥ smṛtāḥ"},{"type":"verse","number":"22","sanskrit":"वारिणा कोमलां कृत्वा समितां साधु मर्दयेत् हस्तचालनया तस्या लोप्त्रद्यं सम्यक्प्रसारयेत्","text":"vāriṇā komalāṃ kṛtvā samitāṃ sādhu mardayet hastacālanayā tasyā loptradyaṃ samyakprasārayet"},{"type":"verse","number":"23","sanskrit":"अधोमुखघटस्यैतद्बिस्तृतं प्रक्षिपेद् बहिः मृदुना वह्निना साध्या सिद्धो मण्डक उच्यते","text":"adhomukhaghaṭasyaitadbistṛtaṃ prakṣiped bahiḥ mṛdunā vahninā sādhyā siddho maṇḍaka ucyate"},{"type":"verse","number":"24","sanskrit":"दुग्धेन साज्यखण्डेन मण्डकं भक्षयेन्नरः अथवा सिद्धमांसेन सतक्रवटकेन वा","text":"dugdhena sājyakhaṇḍena maṇḍakaṃ bhakṣayennaraḥ athavā siddhamāṃsena satakravaṭakena vā"},{"type":"verse","number":"25","sanskrit":"मण्डको बृंहणो वृष्यो बल्यो रुचिकरो भृशम् पाकेऽपि मधुरो ग्राही लघुर्दोषत्रयापहः","text":"maṇḍako bṛṃhaṇo vṛṣyo balyo rucikaro bhṛśam pāke'pi madhuro grāhī laghurdoṣatrayāpahaḥ"},{"type":"verse","number":"26","sanskrit":"कुर्यात्समितयाऽतीव तन्वी पर्पटिका ततः","text":"kuryātsamitayā'tīva tanvī parpaṭikā tataḥ"},{"type":"verse","number":"27","sanskrit":"स्वेदयेत्तप्तके तां तु पोलिकां जगदुर्बुधाः तां खादेल्लप्सिकायुक्तां तस्या मण्डकवद् गुणाः","text":"svedayettaptake tāṃ tu polikāṃ jagadurbudhāḥ tāṃ khādellapsikāyuktāṃ tasyā maṇḍakavad guṇāḥ"},{"type":"verse","number":"28","sanskrit":"समितां सर्पिषा भृष्टां शर्करां पयसि क्षिपेत् तस्मिन्घनीकृते न्यस्येल्लवङ्गं मरिचादिकम् सिद्धषा लप्सिका ख्याता गुणानस्या वदाम्यहम्","text":"samitāṃ sarpiṣā bhṛṣṭāṃ śarkarāṃ payasi kṣipet tasminghanīkṛte nyasyellavaṅgaṃ maricādikam siddhaṣā lapsikā khyātā guṇānasyā vadāmyaham"},{"type":"verse","number":"29","sanskrit":"लप्सिका बृंहणी वृष्या बल्या पित्तानिलापहा स्निग्धा श्लेष्मकरी गुर्वी रोचनी तर्पणी परम्","text":"lapsikā bṛṃhaṇī vṛṣyā balyā pittānilāpahā snigdhā śleṣmakarī gurvī rocanī tarpaṇī param"},{"type":"verse","number":"30","sanskrit":"शुष्कगोधूमचूर्णेन किञ्चित्पुष्टाञ्च पोलिकाम्","text":"śuṣkagodhūmacūrṇena kiñcitpuṣṭāñca polikām"},{"type":"verse","number":"31","sanskrit":"तप्तके स्वेदयेत्कृत्वा भूर्यङ्गारेऽपि तां पचेत् सिद्धैषारोटिका प्रोक्ता गुणानस्याः प्रचक्ष्महे","text":"taptake svedayetkṛtvā bhūryaṅgāre'pi tāṃ pacet siddhaiṣāroṭikā proktā guṇānasyāḥ pracakṣmahe"},{"type":"verse","number":"32","sanskrit":"रोटिका बलकृद्रुच्या बृंहणी धातुवर्द्धनी वातघ्नी कफकृद् गुर्वी दीप्ताग्नीनां प्रपूजिता","text":"roṭikā balakṛdrucyā bṛṃhaṇī dhātuvarddhanī vātaghnī kaphakṛd gurvī dīptāgnīnāṃ prapūjitā"},{"type":"verse","number":"33","sanskrit":"शुष्कगोधूमचूर्णन्तु साम्बु गाढं विमर्दयेत् विधाय वटकाकारं निर्धूमेऽग्नौ शनैः पचेत्","text":"śuṣkagodhūmacūrṇantu sāmbu gāḍhaṃ vimardayet vidhāya vaṭakākāraṃ nirdhūme'gnau śanaiḥ pacet"},{"type":"verse","number":"34","sanskrit":"अङ्गारकर्कटी ह्येषा बृंहणी शुक्रला लघुः दीपनी कफकृद्बल्या पीनसश्वासकासजित्","text":"aṅgārakarkaṭī hyeṣā bṛṃhaṇī śukralā laghuḥ dīpanī kaphakṛdbalyā pīnasaśvāsakāsajit"},{"type":"verse","number":"35","sanskrit":"यवजारोटिका रुच्या मधुरा विशदा लघुः मलशुक्रानिलकरी बल्या हन्ति कफामयान्","text":"yavajāroṭikā rucyā madhurā viśadā laghuḥ malaśukrānilakarī balyā hanti kaphāmayān"},{"type":"verse","number":"36","sanskrit":"चूर्ण यच्छुष्कमाषाणां चमसी साऽभिधीयते चमसीरचिता रोटी कथ्यते बलभद्रि का रूक्षोष्णा वातला बल्या दीप्ताग्नीनां सुपूजिता","text":"cūrṇa yacchuṣkamāṣāṇāṃ camasī sā'bhidhīyate camasīracitā roṭī kathyate balabhadri kā rūkṣoṣṇā vātalā balyā dīptāgnīnāṃ supūjitā"},{"type":"verse","number":"37","sanskrit":"माषाणां दालयस्तोये स्यापितास्त्यक्तकञ्चुकाः आतपे शोषिता यन्त्रे पिष्टास्ता धूमसी स्मृता","text":"māṣāṇāṃ dālayastoye syāpitāstyaktakañcukāḥ ātape śoṣitā yantre piṣṭāstā dhūmasī smṛtā"},{"type":"verse","number":"38","sanskrit":"धूमसीरचिता चैव प्रोक्ता झर्झरिका बुधैः झर्झरी कफपित्तघ्नी किञ्चिद्वातकरी स्मृता","text":"dhūmasīracitā caiva proktā jharjharikā budhaiḥ jharjharī kaphapittaghnī kiñcidvātakarī smṛtā"},{"type":"verse","number":"39","sanskrit":"चणक्या रोटिका रूक्षा श्लेष्मपित्तास्रनुद्गुरुः विष्टम्भिनी न चक्षुष्या तद्गुणा चापि शष्कुली","text":"caṇakyā roṭikā rūkṣā śleṣmapittāsranudguruḥ viṣṭambhinī na cakṣuṣyā tadguṇā cāpi śaṣkulī"},{"type":"verse","number":"40","sanskrit":"दालि संस्थापिता तोये ततोऽपहृतकञ्चुका शिलायां साधु सम्पिष्टा पिष्टिका कथिता बुधैः","text":"dāli saṃsthāpitā toye tato'pahṛtakañcukā śilāyāṃ sādhu sampiṣṭā piṣṭikā kathitā budhaiḥ"},{"type":"verse","number":"41","sanskrit":"माषपिष्टिकया पूर्णगर्भा गोधूमचूर्णतः रचिता रोटिका सैव प्रोक्ता बेढमिका बुधैः","text":"māṣapiṣṭikayā pūrṇagarbhā godhūmacūrṇataḥ racitā roṭikā saiva proktā beḍhamikā budhaiḥ"},{"type":"verse","number":"42","sanskrit":"भवेद्बेढमिका बल्या वृष्या रुच्याऽनिलापहा उष्णा सन्तर्पणी गुर्वी बृंहणी शुक्रला परम्","text":"bhavedbeḍhamikā balyā vṛṣyā rucyā'nilāpahā uṣṇā santarpaṇī gurvī bṛṃhaṇī śukralā param"},{"type":"verse","number":"43","sanskrit":"भिन्नमूत्रमला स्तन्यमेदःपित्तकफप्रदा गुदकीलार्दितश्वासपक्तिशूलानि नाशयेत्","text":"bhinnamūtramalā stanyamedaḥpittakaphapradā gudakīlārditaśvāsapaktiśūlāni nāśayet"},{"type":"verse","number":"44","sanskrit":"धूमसीरचिता हिङ्गुहरिद्रा लवणैर्युताः जीरकस्वर्जिकाभ्याञ्च तनूकृत्य च वेल्लिताः","text":"dhūmasīracitā hiṅguharidrā lavaṇairyutāḥ jīrakasvarjikābhyāñca tanūkṛtya ca vellitāḥ"},{"type":"verse","number":"45","sanskrit":"पर्पटास्ते सदाऽङ्गारभृष्टाः परमरोचकाः दीपनाः पाचनाः रूक्षा गुरवः किञ्चिदीरिताः","text":"parpaṭāste sadā'ṅgārabhṛṣṭāḥ paramarocakāḥ dīpanāḥ pācanāḥ rūkṣā guravaḥ kiñcidīritāḥ"},{"type":"verse","number":"46","sanskrit":"मौद्गाश्च तद्गुणाः प्रोक्ता विशेषाल्लघवो हिताः","text":"maudgāśca tadguṇāḥ proktā viśeṣāllaghavo hitāḥ"},{"type":"verse","number":"47","sanskrit":"चणकस्य गुणैर्युक्ताः पर्पटाश्चणकोद्भवाः स्नेहभृष्टास्तु ते सर्वे भवेयुर्मध्यमा गुणैः","text":"caṇakasya guṇairyuktāḥ parpaṭāścaṇakodbhavāḥ snehabhṛṣṭāstu te sarve bhaveyurmadhyamā guṇaiḥ"},{"type":"verse","number":"48","sanskrit":"माषाणां पिष्टिकां पूर्याल्लवणार्द्र कहिङ्गुभिः तया पिष्टिकया पूर्णा समिता कृत पोलिका","text":"māṣāṇāṃ piṣṭikāṃ pūryāllavaṇārdra kahiṅgubhiḥ tayā piṣṭikayā pūrṇā samitā kṛta polikā"},{"type":"verse","number":"49","sanskrit":"ततस्तैलेन पक्वा सा पूरिका कथिता बुधैः रुच्या स्वादी गुरुः स्निग्धा बल्या पितास्रदूषिका","text":"tatastailena pakvā sā pūrikā kathitā budhaiḥ rucyā svādī guruḥ snigdhā balyā pitāsradūṣikā"},{"type":"verse","number":"50","sanskrit":"चक्षुस्तेजोहरी चोष्णा पाके वातविनाशिनी तथैव घृतपक्वाऽपि चक्षुष्या रक्तपित्तहृत्","text":"cakṣustejoharī coṣṇā pāke vātavināśinī tathaiva ghṛtapakvā'pi cakṣuṣyā raktapittahṛt"},{"type":"verse","number":"51","sanskrit":"अथ वटकः शुष्कः सरसश्च सूखा व रसदार बरा माषाणांपिष्टिकां युक्तां लवणार्द्र कहिङ्गुभिः कृत्वा विदध्याद्वटकांस्तांस्तैलेषु पचेच्छनैः","text":"atha vaṭakaḥ śuṣkaḥ sarasaśca sūkhā va rasadāra barā māṣāṇāṃpiṣṭikāṃ yuktāṃ lavaṇārdra kahiṅgubhiḥ kṛtvā vidadhyādvaṭakāṃstāṃstaileṣu pacecchanaiḥ"},{"type":"verse","number":"52","sanskrit":"विशुष्का वटका बल्या बृंहणा वीर्य्यवर्द्धनाः वातामयहरा रुच्या विशेषादर्दितापहाः","text":"viśuṣkā vaṭakā balyā bṛṃhaṇā vīryyavarddhanāḥ vātāmayaharā rucyā viśeṣādarditāpahāḥ"},{"type":"verse","number":"53","sanskrit":"विबन्धभेदिनः श्लेष्मकारिणोऽत्यग्निपूजिताः संचूर्ण्यनिक्षिपेत्तक्रे भृष्टं जीरकहिङ्गु च","text":"vibandhabhedinaḥ śleṣmakāriṇo'tyagnipūjitāḥ saṃcūrṇyanikṣipettakre bhṛṣṭaṃ jīrakahiṅgu ca"},{"type":"verse","number":"54","sanskrit":"लवणं तत्र वटकान्सकलानपि मज्जयेत् शुक्रलस्तत्र वटको बलकृद्रो चनो गुरुः","text":"lavaṇaṃ tatra vaṭakānsakalānapi majjayet śukralastatra vaṭako balakṛdro cano guruḥ"},{"type":"verse","number":"55","sanskrit":"विबन्धहृद्विदाही च श्लेष्मलः पवनापहः राज्यक्तयाऽतिरोचन्या पाचन्या तांस्तु भक्षयेत्","text":"vibandhahṛdvidāhī ca śleṣmalaḥ pavanāpahaḥ rājyaktayā'tirocanyā pācanyā tāṃstu bhakṣayet"},{"type":"verse","number":"56","sanskrit":"मन्थनी नूतना धार्या कटुतैलेन लेपिता निर्मलेनाम्बुनाऽपूर्य तस्यां चूर्णं विनिक्षिपेत् राजिकाजीरकलवणहिङ्गुशुण्ठीनिशाकृतम्","text":"manthanī nūtanā dhāryā kaṭutailena lepitā nirmalenāmbunā'pūrya tasyāṃ cūrṇaṃ vinikṣipet rājikājīrakalavaṇahiṅguśuṇṭhīniśākṛtam"},{"type":"verse","number":"57","sanskrit":"निक्षिपेद्वटकांस्तत्र भाण्डस्यास्यञ्च मुद्र येत् ततो दिनत्रयादूर्ध्वमम्लाः स्युर्वटका ध्रुवम्","text":"nikṣipedvaṭakāṃstatra bhāṇḍasyāsyañca mudra yet tato dinatrayādūrdhvamamlāḥ syurvaṭakā dhruvam"},{"type":"verse","number":"58","sanskrit":"काञ्जिकावटको रुच्यो वातघ्नः श्लेष्मकारकः शूलघ्नोऽजीर्णदाहनुद् नेत्ररोगे तु नो हितः","text":"kāñjikāvaṭako rucyo vātaghnaḥ śleṣmakārakaḥ śūlaghno'jīrṇadāhanud netraroge tu no hitaḥ"},{"type":"verse","number":"59","sanskrit":"अम्लिकां स्वेदयित्वा तु जलेन सह मर्दयेत् तन्नीरे कृतसंस्कारे वटकान्मज्जयेज्जनः","text":"amlikāṃ svedayitvā tu jalena saha mardayet tannīre kṛtasaṃskāre vaṭakānmajjayejjanaḥ"},{"type":"verse","number":"60","sanskrit":"अम्लिकावटकास्ते तु रुच्या वह्निप्रदीपनाः वटकस्य गुणैः पूर्वै रेतेऽपि च समन्विताः","text":"amlikāvaṭakāste tu rucyā vahnipradīpanāḥ vaṭakasya guṇaiḥ pūrvai rete'pi ca samanvitāḥ"},{"type":"verse","number":"61","sanskrit":"मुद्गानां वटकास्तक्रे मज्जिता लघवो हिमाः संस्कारजप्रभावेण त्रिदोषशमना हिताः","text":"mudgānāṃ vaṭakāstakre majjitā laghavo himāḥ saṃskārajaprabhāveṇa tridoṣaśamanā hitāḥ"},{"type":"verse","number":"62","sanskrit":"माषाणां पिष्टिका हिङ्गुलवणार्द्र कसंस्कृता तया विरचिता वस्त्रे वटिकाः साधु शोषिताः","text":"māṣāṇāṃ piṣṭikā hiṅgulavaṇārdra kasaṃskṛtā tayā viracitā vastre vaṭikāḥ sādhu śoṣitāḥ"},{"type":"verse","number":"63","sanskrit":"भर्जितास्तप्ततैलैस्ता अथवाऽम्बुप्रयोगतः वटकस्य गुणैर्युक्ता ज्ञातव्या रोचना भृशम्","text":"bharjitāstaptatailaistā athavā'mbuprayogataḥ vaṭakasya guṇairyuktā jñātavyā rocanā bhṛśam"},{"type":"verse","number":"64","sanskrit":"कूष्माण्डकवटी ज्ञेया पूर्वोक्तवटिकागुणा विशेषात्पित्तरक्तघ्नी लघ्वी च कथिता बुधैः","text":"kūṣmāṇḍakavaṭī jñeyā pūrvoktavaṭikāguṇā viśeṣātpittaraktaghnī laghvī ca kathitā budhaiḥ"},{"type":"verse","number":"65","sanskrit":"मूद्गानां वटिका तद्वद्र चिता साधिता तथा पथ्या रुच्या तथा लघ्वी मुद्गसूपगुणा स्मृता","text":"mūdgānāṃ vaṭikā tadvadra citā sādhitā tathā pathyā rucyā tathā laghvī mudgasūpaguṇā smṛtā"},{"type":"verse","number":"66","sanskrit":"माषपिष्टिकया लिप्तं नागवल्लीदलं महत्","text":"māṣapiṣṭikayā liptaṃ nāgavallīdalaṃ mahat"},{"type":"verse","number":"67","sanskrit":"तत्तु संस्वेदयेद्युक्त्या स्थाल्यामास्तारकोपरि ततो निष्कास्य तं खण्ड्यं ततस्तैलेन भर्जयेत्","text":"tattu saṃsvedayedyuktyā sthālyāmāstārakopari tato niṣkāsya taṃ khaṇḍyaṃ tatastailena bharjayet"},{"type":"verse","number":"68","sanskrit":"अलीकमत्स्य उक्तोऽय प्रकारः पाक पण्डितैः तं वृन्ताक भटित्रेण वास्तूकेन च भक्षयेत्","text":"alīkamatsya ukto'ya prakāraḥ pāka paṇḍitaiḥ taṃ vṛntāka bhaṭitreṇa vāstūkena ca bhakṣayet"},{"type":"verse","number":"69","sanskrit":"स्थाल्यां घृते वा तैले वा हरिद्रा ं! हिङ्गु भर्जयेत् अवलेहनसंयुक्तं तक्रं तत्रैव निक्षिपेत् एषा सिद्धा समरिचा क्वथिता कथिता बुधैः","text":"sthālyāṃ ghṛte vā taile vā haridrā ṃ! hiṅgu bharjayet avalehanasaṃyuktaṃ takraṃ tatraiva nikṣipet eṣā siddhā samaricā kvathitā kathitā budhaiḥ"},{"type":"verse","number":"70","sanskrit":"क्वथिता पाचनी रुच्या लघ्वी वह्निप्रदीपनी कफानिलाविबन्धघ्नी किञ्चित्पित्तप्रकोपणी","text":"kvathitā pācanī rucyā laghvī vahnipradīpanī kaphānilāvibandhaghnī kiñcitpittaprakopaṇī"},{"type":"verse","number":"71","sanskrit":"अलीकमत्स्याः शुष्का वा किं वा क्वथितया पुनः बृंहणा रोचना वृष्या बल्या वातगदापहः","text":"alīkamatsyāḥ śuṣkā vā kiṃ vā kvathitayā punaḥ bṛṃhaṇā rocanā vṛṣyā balyā vātagadāpahaḥ"},{"type":"verse","number":"72","sanskrit":"कोष्ठशुद्धिकराः शुष्काः किञ्चित्पित्तप्रकोपणाः अर्दिते सहनुस्तम्भे विशेषेण हिताः स्मृताः","text":"koṣṭhaśuddhikarāḥ śuṣkāḥ kiñcitpittaprakopaṇāḥ ardite sahanustambhe viśeṣeṇa hitāḥ smṛtāḥ"},{"type":"verse","number":"73","sanskrit":"मुद्गपिष्टीविरचितान् वटकांस्तैलपाचितान् हस्तेन चूर्णयेत्सम्यक् तस्मिंश्चूर्णं विनिक्षिपेत्","text":"mudgapiṣṭīviracitān vaṭakāṃstailapācitān hastena cūrṇayetsamyak tasmiṃścūrṇaṃ vinikṣipet"},{"type":"verse","number":"74","sanskrit":"भृष्टं हिङ्ग्वार्द्र कं सूक्ष्मं मरिचं जीरकं तथा निम्बूरसं यवानीं च युक्त्या सर्वं विमिश्रयेत्","text":"bhṛṣṭaṃ hiṅgvārdra kaṃ sūkṣmaṃ maricaṃ jīrakaṃ tathā nimbūrasaṃ yavānīṃ ca yuktyā sarvaṃ vimiśrayet"},{"type":"verse","number":"75","sanskrit":"मुद्गपिष्टि पचेत्सम्यक् स्थाल्याभास्तारकोपरि तस्यास्तु गोलकं कुर्यात्तन्मध्ये पूरण क्षिपेत्","text":"mudgapiṣṭi pacetsamyak sthālyābhāstārakopari tasyāstu golakaṃ kuryāttanmadhye pūraṇa kṣipet"},{"type":"verse","number":"76","sanskrit":"तैले तान्गोलकान्पक्त्वा क्वथितायां निमज्जयेत् गोलकाःपाचक्! प्रोक्तास्ते त्वार्द्र कवटा अपि","text":"taile tāngolakānpaktvā kvathitāyāṃ nimajjayet golakāḥpācak! proktāste tvārdra kavaṭā api"},{"type":"verse","number":"77","sanskrit":"मुद्गार्द्र कवटा रुच्या लघ्वो बलकारकाः दीपनास्तर्पणाः पथ्यास्त्रिषु दोषेषु पूजिताः","text":"mudgārdra kavaṭā rucyā laghvo balakārakāḥ dīpanāstarpaṇāḥ pathyāstriṣu doṣeṣu pūjitāḥ"},{"type":"verse","number":"78","sanskrit":"दालयश्चणकानां तु निस्तुषा यन्त्रपेषिताः तच्चूर्णं वेसनं प्रोक्तं पाकशास्त्रविशारदैः","text":"dālayaścaṇakānāṃ tu nistuṣā yantrapeṣitāḥ taccūrṇaṃ vesanaṃ proktaṃ pākaśāstraviśāradaiḥ"},{"type":"verse","number":"79","sanskrit":"वटिकावेसनस्यापि क्वथितायां निमज्जिता रुच्या विष्टम्भजननी बल्या पुष्टिकरी स्मृता","text":"vaṭikāvesanasyāpi kvathitāyāṃ nimajjitā rucyā viṣṭambhajananī balyā puṣṭikarī smṛtā"},{"type":"verse","number":"80","sanskrit":"पाकपात्रे घृतं दद्यात्तैलञ्च तदभावतः तत्र हिङ्गुहरिद्रा ं! च भर्जयेत्तदनन्तरम्","text":"pākapātre ghṛtaṃ dadyāttailañca tadabhāvataḥ tatra hiṅguharidrā ṃ! ca bharjayettadanantaram"},{"type":"verse","number":"81","sanskrit":"छागादेरस्थिरहितं मांसं तत्खण्डितं ध्रुवम् धौतं निर्गालितं तस्मिन्घृते तद्भर्जयेच्छनैः","text":"chāgāderasthirahitaṃ māṃsaṃ tatkhaṇḍitaṃ dhruvam dhautaṃ nirgālitaṃ tasminghṛte tadbharjayecchanaiḥ"},{"type":"verse","number":"82","sanskrit":"सिद्धयोग्यं जलं दत्वा लवणन्तु पचेत्ततः सिद्धे जलेन सम्पिष्य वेशवारं परिक्षिपेत्","text":"siddhayogyaṃ jalaṃ datvā lavaṇantu pacettataḥ siddhe jalena sampiṣya veśavāraṃ parikṣipet"},{"type":"verse","number":"83","sanskrit":"द्र व्याणि वेशवारस्य नागवल्लीदलानि च तण्डुलाश्च लवङ्गानि मरिचानि समासतः","text":"dra vyāṇi veśavārasya nāgavallīdalāni ca taṇḍulāśca lavaṅgāni maricāni samāsataḥ"},{"type":"verse","number":"84","sanskrit":"अनेन विधिना सिद्धं शुद्धमांसमिति स्मृतम्","text":"anena vidhinā siddhaṃ śuddhamāṃsamiti smṛtam"},{"type":"verse","number":"85","sanskrit":"शुद्धमांसं परं वृष्यं बल्यं रुच्यञ्च बृंहणम् त्रिदोषशमनं श्रेष्ठं दीपनं धातुवर्द्धनम्","text":"śuddhamāṃsaṃ paraṃ vṛṣyaṃ balyaṃ rucyañca bṛṃhaṇam tridoṣaśamanaṃ śreṣṭhaṃ dīpanaṃ dhātuvarddhanam"},{"type":"verse","number":"86","sanskrit":"छागादेर्मांसमूर्वादेः कुट्टितं खण्डितं पुनः शुद्धमांसविधानेन पचेदेतत्सहद्र कम् सहद्र कं गुणैर्ग्रन्थे शुद्धमांसगुणं स्मृतम्","text":"chāgādermāṃsamūrvādeḥ kuṭṭitaṃ khaṇḍitaṃ punaḥ śuddhamāṃsavidhānena pacedetatsahadra kam sahadra kaṃ guṇairgranthe śuddhamāṃsaguṇaṃ smṛtam"},{"type":"verse","number":"87","sanskrit":"पाकपात्रे घृतं दत्त्वा हरिद्रा ं! हिङ्गु भर्जयेत् छागादेः सकलस्यापि खण्डान्यपि च भर्जयेत्","text":"pākapātre ghṛtaṃ dattvā haridrā ṃ! hiṅgu bharjayet chāgādeḥ sakalasyāpi khaṇḍānyapi ca bharjayet"},{"type":"verse","number":"88","sanskrit":"सिद्धयोग्यं जलं दत्त्वा पचेन्मृदुतरं तथा जीरकादियुते तक्रे मांसखण्डानि भावयेत्","text":"siddhayogyaṃ jalaṃ dattvā pacenmṛdutaraṃ tathā jīrakādiyute takre māṃsakhaṇḍāni bhāvayet"},{"type":"verse","number":"89","sanskrit":"तक्रमांसन्तु वातघ्नं लघु रुच्यं बलप्रदम् कफघ्नं पित्तलं किञ्चित्सर्वाहारस्य पाचनम्","text":"takramāṃsantu vātaghnaṃ laghu rucyaṃ balapradam kaphaghnaṃ pittalaṃ kiñcitsarvāhārasya pācanam"},{"type":"verse","number":"90","sanskrit":"पाकपात्रे तु बृहति मांसखण्डानि निक्षिपेत् पानीयं प्रचुरं सर्पिः प्रभूतं हिङ्गु जीरकम्","text":"pākapātre tu bṛhati māṃsakhaṇḍāni nikṣipet pānīyaṃ pracuraṃ sarpiḥ prabhūtaṃ hiṅgu jīrakam"},{"type":"verse","number":"91","sanskrit":"हरिद्रा मार्द्र कं शुण्ठीं लवणं मरिचानि च तण्डुलांश्चापि गोधूमाञ्जम्बीराणां रसान् बहून्","text":"haridrā mārdra kaṃ śuṇṭhīṃ lavaṇaṃ maricāni ca taṇḍulāṃścāpi godhūmāñjambīrāṇāṃ rasān bahūn"},{"type":"verse","number":"92","sanskrit":"यथा सर्वाणि वस्तूनि सुपक्वानि भवन्ति हि तथा पचेत्तु निपुणो बहुमण्डस्थितिर्यथा","text":"yathā sarvāṇi vastūni supakvāni bhavanti hi tathā pacettu nipuṇo bahumaṇḍasthitiryathā"},{"type":"verse","number":"93","sanskrit":"एषा हरीसा बलकृद्वातपित्तापहा गुरुः शीतोष्णा शुक्रदा स्निग्धा सरा सन्धानकारिणी","text":"eṣā harīsā balakṛdvātapittāpahā guruḥ śītoṣṇā śukradā snigdhā sarā sandhānakāriṇī"},{"type":"verse","number":"94","sanskrit":"शुद्धमांसविधानेन मांसं सम्यक्प्रसाधितम् पुनस्तदाज्ये सम्भृष्टं तलितं प्रोच्यते बुधैः","text":"śuddhamāṃsavidhānena māṃsaṃ samyakprasādhitam punastadājye sambhṛṣṭaṃ talitaṃ procyate budhaiḥ"},{"type":"verse","number":"95","sanskrit":"तलितं बलमेधाऽग्निमांसौजःशुक्रवृद्धिकृत् तर्पणं लघु सुस्निग्धं रोचनं दृढताकरम्","text":"talitaṃ balamedhā'gnimāṃsaujaḥśukravṛddhikṛt tarpaṇaṃ laghu susnigdhaṃ rocanaṃ dṛḍhatākaram"},{"type":"verse","number":"96","sanskrit":"कालखण्डादिमांसानि ग्रथितानि शलाकया घृतं सलवणं दत्त्वा निर्धूमे दहने पचेत्","text":"kālakhaṇḍādimāṃsāni grathitāni śalākayā ghṛtaṃ salavaṇaṃ dattvā nirdhūme dahane pacet"},{"type":"verse","number":"97","sanskrit":"तत्तु शूल्यमिति प्रोक्तं पाककर्मविचक्षणैः","text":"tattu śūlyamiti proktaṃ pākakarmavicakṣaṇaiḥ"},{"type":"verse","number":"98","sanskrit":"शूल्यं पलं सुधातुल्यं रुच्यं बह्निकरं लघु कफवातहरं बल्यं किञ्चित्पित्तकरं हि तत्","text":"śūlyaṃ palaṃ sudhātulyaṃ rucyaṃ bahnikaraṃ laghu kaphavātaharaṃ balyaṃ kiñcitpittakaraṃ hi tat"},{"type":"verse","number":"99","sanskrit":"शुद्धमांसं तनूकृत्य कर्त्तितं स्वेदितं जले लवङ्गहिङ्गुलवणमरिचार्द्र कसंयुतम्","text":"śuddhamāṃsaṃ tanūkṛtya karttitaṃ sveditaṃ jale lavaṅgahiṅgulavaṇamaricārdra kasaṃyutam"},{"type":"verse","number":"100","sanskrit":"घृते सुगन्धे तद् भृष्टं पूरणं प्रोच्यते बुधैः","text":"ghṛte sugandhe tad bhṛṣṭaṃ pūraṇaṃ procyate budhaiḥ"},{"type":"verse","number":"101","sanskrit":"शृङ्गाटकं समितया कृतं पूरणपूरितम् पुनः सर्पिषि सभृष्टं मांसशृङ्गाटकं वदेत्","text":"śṛṅgāṭakaṃ samitayā kṛtaṃ pūraṇapūritam punaḥ sarpiṣi sabhṛṣṭaṃ māṃsaśṛṅgāṭakaṃ vadet"},{"type":"verse","number":"102","sanskrit":"मांसशृङ्गाटकं रुच्यं बृंहणं बलकृद् गुरु वातपित्तहरं वृष्यं कफघ्नं वीर्यवर्धनम्","text":"māṃsaśṛṅgāṭakaṃ rucyaṃ bṛṃhaṇaṃ balakṛd guru vātapittaharaṃ vṛṣyaṃ kaphaghnaṃ vīryavardhanam"},{"type":"verse","number":"103","sanskrit":"सिद्धमांसरसो रुच्यः श्रमश्वासक्षयापहः प्रीणनो वातपित्तघ्नः क्षीणानामल्परेतसाम् विश्लिष्टभग्नसन्धीनां शुद्धानां शुद्धिकाङ्क्षिणाम्","text":"siddhamāṃsaraso rucyaḥ śramaśvāsakṣayāpahaḥ prīṇano vātapittaghnaḥ kṣīṇānāmalparetasām viśliṣṭabhagnasandhīnāṃ śuddhānāṃ śuddhikāṅkṣiṇām"},{"type":"verse","number":"104","sanskrit":"स्मृत्योजोबलहीनानां ज्वरक्षीणक्षतोरसाम् शस्यते स्वरहीनानां दृष्ट्यायुःश्रवणार्थिनाम्","text":"smṛtyojobalahīnānāṃ jvarakṣīṇakṣatorasām śasyate svarahīnānāṃ dṛṣṭyāyuḥśravaṇārthinām"},{"type":"verse","number":"105","sanskrit":"प्रकाराः कथिताः सन्ति बहवो मांससम्भवाः ग्रन्थविस्तरभीतेस्ते मया नात्र प्रकीर्त्तिताः","text":"prakārāḥ kathitāḥ santi bahavo māṃsasambhavāḥ granthavistarabhīteste mayā nātra prakīrttitāḥ"},{"type":"verse","number":"106","sanskrit":"हिङ्गुजीरयुते तैले क्षिपेच्छाकं सुखण्डितम्","text":"hiṅgujīrayute taile kṣipecchākaṃ sukhaṇḍitam"},{"type":"verse","number":"107","sanskrit":"लवणं चात्र चूर्णादि सिद्धे हिङ्गूदकं क्षिपेत् इत्येवं सर्वशाकानां साधनेऽभिहितो विधिः","text":"lavaṇaṃ cātra cūrṇādi siddhe hiṅgūdakaṃ kṣipet ityevaṃ sarvaśākānāṃ sādhane'bhihito vidhiḥ"},{"type":"verse","number":"108","sanskrit":"समितां मर्दयेदाज्यैर्जलेनापि च सन्नयेत् तस्यास्तु वटिकां कृत्वा पचेत्सर्पिषि नीरसम् एलालवङ्गकर्पूरमरिचाद्यैरलङ्कृते","text":"samitāṃ mardayedājyairjalenāpi ca sannayet tasyāstu vaṭikāṃ kṛtvā pacetsarpiṣi nīrasam elālavaṅgakarpūramaricādyairalaṅkṛte"},{"type":"verse","number":"109","sanskrit":"मज्जयित्वा सितापाके ततस्तञ्च समुद्धरेत् अयं प्रकारः संसिद्धौ मण्ठ इत्यभिधीयते","text":"majjayitvā sitāpāke tatastañca samuddharet ayaṃ prakāraḥ saṃsiddhau maṇṭha ityabhidhīyate"},{"type":"verse","number":"110","sanskrit":"मण्ठस्तु बृंहणो वृष्यो बल्यः सुमधुरो गुरुः पित्तानिलहरो रुच्यो दीप्ताग्नीनां सुपूजितः","text":"maṇṭhastu bṛṃhaṇo vṛṣyo balyaḥ sumadhuro guruḥ pittānilaharo rucyo dīptāgnīnāṃ supūjitaḥ"},{"type":"verse","number":"111","sanskrit":"समिताशर्करासर्पिर्निर्मिता अपरेऽपि ये प्रकारा अमुना तुल्यास्तेऽपि चेत्तद्गुणाः स्मृताः","text":"samitāśarkarāsarpirnirmitā apare'pi ye prakārā amunā tulyāste'pi cettadguṇāḥ smṛtāḥ"},{"type":"verse","number":"112","sanskrit":"पर्पट्यः साज्यसमिता निर्मिता घृतभर्जिताः कुट्टिताश्चालिताः शुद्धशर्कराभिर्विमर्दिताः","text":"parpaṭyaḥ sājyasamitā nirmitā ghṛtabharjitāḥ kuṭṭitāścālitāḥ śuddhaśarkarābhirvimarditāḥ"},{"type":"verse","number":"113","sanskrit":"तत्र चूर्णं क्षिपेदेलालवङ्गमरिचानि च नारिकेरं सकर्पूरं चारबीजान्यनेकधा","text":"tatra cūrṇaṃ kṣipedelālavaṅgamaricāni ca nārikeraṃ sakarpūraṃ cārabījānyanekadhā"},{"type":"verse","number":"114","sanskrit":"घृताक्तसमिता पुष्टरोटिका रचिता ततः तस्यान्तःपूरणं तस्य कुर्यान्मुद्रा ं! दृढां सुधीः","text":"ghṛtāktasamitā puṣṭaroṭikā racitā tataḥ tasyāntaḥpūraṇaṃ tasya kuryānmudrā ṃ! dṛḍhāṃ sudhīḥ"},{"type":"verse","number":"115","sanskrit":"सर्पिषि प्रचुरे तान्तु सुपचेन्निपुणो जनः प्रकारज्ञैः प्रकारोऽय सम्पाव इति कीर्त्तितः","text":"sarpiṣi pracure tāntu supacennipuṇo janaḥ prakārajñaiḥ prakāro'ya sampāva iti kīrttitaḥ"},{"type":"verse","number":"116","sanskrit":"मण्ठकेन समो ज्ञेयः सम्पावोऽपि गुणैर्जनैः","text":"maṇṭhakena samo jñeyaḥ sampāvo'pi guṇairjanaiḥ"},{"type":"verse","number":"117","sanskrit":"घृताढ्यया समितया लम्बं कृत्वा पुटं ततः लवङ्गोषणकर्पूरयुतया सितयाऽन्वितम्","text":"ghṛtāḍhyayā samitayā lambaṃ kṛtvā puṭaṃ tataḥ lavaṅgoṣaṇakarpūrayutayā sitayā'nvitam"},{"type":"verse","number":"118","sanskrit":"पचेदाज्येन सिद्धैषा ज्ञेया कर्पूरनालिका सम्पावसदृशा ज्ञेया गुणैः कर्पूरनालिका","text":"pacedājyena siddhaiṣā jñeyā karpūranālikā sampāvasadṛśā jñeyā guṇaiḥ karpūranālikā"},{"type":"verse","number":"119","sanskrit":"समिताया घृताढ्याया वर्त्तीर्दीर्घाः समाचरेत् तास्तु सन्निहिता दीर्घाः पीठस्योपरि धारयेत्","text":"samitāyā ghṛtāḍhyāyā varttīrdīrghāḥ samācaret tāstu sannihitā dīrghāḥ pīṭhasyopari dhārayet"},{"type":"verse","number":"120","sanskrit":"वेल्लयेद्वेल्लनेनैता यथैका पर्पटी भवेत् ततश्छुरिकया तान्तु संलग्नामेव कर्त्तयेत्","text":"vellayedvellanenaitā yathaikā parpaṭī bhavet tataśchurikayā tāntu saṃlagnāmeva karttayet"},{"type":"verse","number":"121","sanskrit":"ततस्तु वेल्लयेद्भूयः सट्टकेन च लेपयेत् शालिचूर्णं घृतं तोयं मिश्रितं सट्टकं वदेत्","text":"tatastu vellayedbhūyaḥ saṭṭakena ca lepayet śālicūrṇaṃ ghṛtaṃ toyaṃ miśritaṃ saṭṭakaṃ vadet"},{"type":"verse","number":"122","sanskrit":"ततः संवृत्य तल्लोप्त्रद्यं विदधीत पृथक्पृथक् पुनस्तां वेल्लययेल्लोप्त्रद्यं यथा स्यान्मण्डलाकृतिः","text":"tataḥ saṃvṛtya talloptradyaṃ vidadhīta pṛthakpṛthak punastāṃ vellayayelloptradyaṃ yathā syānmaṇḍalākṛtiḥ"},{"type":"verse","number":"123","sanskrit":"ततस्तां सुपचेदाज्ये भवेयुश्च स्फुटाः स्फुटाः सुगन्धया शर्करया तद्धूलनमाचरेत्","text":"tatastāṃ supacedājye bhaveyuśca sphuṭāḥ sphuṭāḥ sugandhayā śarkarayā taddhūlanamācaret"},{"type":"verse","number":"124","sanskrit":"सिद्धैषा फेनिकानाम्नी मण्ठकेन समा गुणैः ततः किञ्चिल्लघुरियं विशेषोऽयमुदाहृतः","text":"siddhaiṣā phenikānāmnī maṇṭhakena samā guṇaiḥ tataḥ kiñcillaghuriyaṃ viśeṣo'yamudāhṛtaḥ"},{"type":"verse","number":"125","sanskrit":"समिताया घृताक्ताया लोप्त्रद्यं कृत्वा च वेल्लयेत् आज्ये तां भर्जयेत्सिद्धा शष्कुली फेनिकागुणा","text":"samitāyā ghṛtāktāyā loptradyaṃ kṛtvā ca vellayet ājye tāṃ bharjayetsiddhā śaṣkulī phenikāguṇā"},{"type":"verse","number":"126","sanskrit":"वृताढ्यया समितया कृत्वा सूत्राणि तानि तु निपुणो भर्जयेदाज्ये खण्डपाकेन योजयेत् युक्तेन मोदकान् कुर्यात्ते गुणैर्मण्ठका यथा","text":"vṛtāḍhyayā samitayā kṛtvā sūtrāṇi tāni tu nipuṇo bharjayedājye khaṇḍapākena yojayet yuktena modakān kuryātte guṇairmaṇṭhakā yathā"},{"type":"verse","number":"127","sanskrit":"मुद्गानां धूमसीं सम्यग्घोलयेन्निर्मलाऽम्बुना","text":"mudgānāṃ dhūmasīṃ samyaggholayennirmalā'mbunā"},{"type":"verse","number":"128","sanskrit":"कटाहस्य घृतस्योर्ध्वं झर्झरं स्थापयेत्ततः घूमसीन्तु द्र वीभूतां प्रक्षिपेज्झर्झरोपरि","text":"kaṭāhasya ghṛtasyordhvaṃ jharjharaṃ sthāpayettataḥ ghūmasīntu dra vībhūtāṃ prakṣipejjharjharopari"},{"type":"verse","number":"129","sanskrit":"पतन्ति बिन्दवस्तस्मात्तान्सुपक्वान्समुद्धरेत् सितापाकेन संयोज्य कुर्याद्धस्तेन मोदकान्","text":"patanti bindavastasmāttānsupakvānsamuddharet sitāpākena saṃyojya kuryāddhastena modakān"},{"type":"verse","number":"130","sanskrit":"लघुर्ग्राही त्रिदोषघ्नः स्वादुः शीतो रुचिप्रदः चक्षुष्यो ज्वरहृद्बल्यस्तर्पणो मुद्गमोदकः","text":"laghurgrāhī tridoṣaghnaḥ svāduḥ śīto rucipradaḥ cakṣuṣyo jvarahṛdbalyastarpaṇo mudgamodakaḥ"},{"type":"verse","number":"131","sanskrit":"एवमेव प्रकारेण कार्या वेसनमोदकाः","text":"evameva prakāreṇa kāryā vesanamodakāḥ"},{"type":"verse","number":"132","sanskrit":"ते बल्या लघवः शीताः किञ्चिद्वातकरास्तथा विष्टम्भिनो ज्वरघ्नाश्च पित्तरक्तकफापहाः","text":"te balyā laghavaḥ śītāḥ kiñcidvātakarāstathā viṣṭambhino jvaraghnāśca pittaraktakaphāpahāḥ"},{"type":"verse","number":"133","sanskrit":"तण्डुलचूर्णविमिश्रितनष्टक्षीरेण सान्द्र पिष्टेन दृढकूपिकां विदध्यात्ताञ्च पचेत्सर्पिषा सम्यक्","text":"taṇḍulacūrṇavimiśritanaṣṭakṣīreṇa sāndra piṣṭena dṛḍhakūpikāṃ vidadhyāttāñca pacetsarpiṣā samyak"},{"type":"verse","number":"134","sanskrit":"अथ तां कोरितमध्यां घनपयसा पूर्णगर्भाञ्च सट्टकमुद्रि तवदनां तप्तघृते सुपक्ववदनाञ्च अथ पाण्डुखण्डपाके स्नपयेत्कर्पूरवासिते कुशलः अथ दुग्धकूपिका सा बल्या पित्तानिलापहाचैव","text":"atha tāṃ koritamadhyāṃ ghanapayasā pūrṇagarbhāñca saṭṭakamudri tavadanāṃ taptaghṛte supakvavadanāñca atha pāṇḍukhaṇḍapāke snapayetkarpūravāsite kuśalaḥ atha dugdhakūpikā sā balyā pittānilāpahācaiva"},{"type":"verse","number":"135","sanskrit":"वृष्या शीता गुर्वी शुक्रकरी च तर्पणी रुच्या विदधाति कायपुष्टिं दृष्टिं दूरप्रसारिणीं सुचिरम्","text":"vṛṣyā śītā gurvī śukrakarī ca tarpaṇī rucyā vidadhāti kāyapuṣṭiṃ dṛṣṭiṃ dūraprasāriṇīṃ suciram"},{"type":"verse","number":"137","sanskrit":"नूतनं घटमानीय तस्यान्तः कुशलो जनः प्रस्थार्द्धपरिमाणेन दध्नाऽम्लेन प्रलेपयेत्","text":"nūtanaṃ ghaṭamānīya tasyāntaḥ kuśalo janaḥ prasthārddhaparimāṇena dadhnā'mlena pralepayet"},{"type":"verse","number":"138","sanskrit":"द्विप्रस्थां समितां तत्र दध्यम्ल प्रस्थसम्मितम् घृतमर्द्धशरावञ्च घोलयित्वा घटे क्षिपेत्","text":"dviprasthāṃ samitāṃ tatra dadhyamla prasthasammitam ghṛtamarddhaśarāvañca gholayitvā ghaṭe kṣipet"},{"type":"verse","number":"139","sanskrit":"आतपे स्थापयेत्तावद् यावद्याति तदम्लताम् ततस्तत्प्रक्षिपेत्पात्रे सच्छिद्रे भाजने तु तत्","text":"ātape sthāpayettāvad yāvadyāti tadamlatām tatastatprakṣipetpātre sacchidre bhājane tu tat"},{"type":"verse","number":"140","sanskrit":"परिभ्राम्य परिभ्राम्य सुसन्तप्ते घृते क्षिपेत् पुनः पुनः स्तदावृत्त्या विदध्यान्मण्डलाकृतिम्","text":"paribhrāmya paribhrāmya susantapte ghṛte kṣipet punaḥ punaḥ stadāvṛttyā vidadhyānmaṇḍalākṛtim"},{"type":"verse","number":"141","sanskrit":"तां सुपक्वां घृतान्नीत्वा सितापाके तनुद्र वे कर्पूरादिसुगन्धे च स्नापयित्वोद्धरेत्ततः","text":"tāṃ supakvāṃ ghṛtānnītvā sitāpāke tanudra ve karpūrādisugandhe ca snāpayitvoddharettataḥ"},{"type":"verse","number":"142","sanskrit":"एषा कुण्डलिनी नाम्ना पुष्टिकान्तिबलप्रदा धातुवृद्धिकरी वृष्या रुच्या चेन्द्रि यतर्पणी","text":"eṣā kuṇḍalinī nāmnā puṣṭikāntibalapradā dhātuvṛddhikarī vṛṣyā rucyā cendri yatarpaṇī"},{"type":"verse","number":"143","sanskrit":"आदौ माहिषमम्लमम्बुरहितं दध्याढकं शर्करां शुभ्रां प्रस्थयुगोन्मितां शुचिपटे किञ्चिच्च किञ्चित्क्षिपेत् दुग्धेनार्द्धघटेन मृण्मयनवंस्थाल्यां दृढं स्रावये देलाबीजलवङ्गचन्द्र मरिचैर्योग्यैश्च तद्योजयेत्","text":"ādau māhiṣamamlamamburahitaṃ dadhyāḍhakaṃ śarkarāṃ śubhrāṃ prasthayugonmitāṃ śucipaṭe kiñcicca kiñcitkṣipet dugdhenārddhaghaṭena mṛṇmayanavaṃsthālyāṃ dṛḍhaṃ srāvaye delābījalavaṅgacandra maricairyogyaiśca tadyojayet"},{"type":"verse","number":"144","sanskrit":"भीमेन प्रियभोजनेन रचिता नाम्ना रसाला स्वयं श्रीकृष्णेन पुरा पुनः पुनरियं प्रीत्या समास्वादिता एषा येन वसन्तवर्जितदिने संसेव्यते नित्यश स्तस्य स्यादतिवीर्य्यवृद्धिरनिशं सर्वेन्द्रि याणां बलम्","text":"bhīmena priyabhojanena racitā nāmnā rasālā svayaṃ śrīkṛṣṇena purā punaḥ punariyaṃ prītyā samāsvāditā eṣā yena vasantavarjitadine saṃsevyate nityaśa stasya syādativīryyavṛddhiraniśaṃ sarvendri yāṇāṃ balam"},{"type":"verse","number":"145","sanskrit":"ग्रीष्मे तथाशरदि ये रविशोषिताङ्गा ये च प्रमत्तवनितासुरतातिखिन्नाः ये चापि मार्गपरिसर्पणशीर्णगात्रास्तेषामियं वपुषि पोषणमाशु कुर्यात्","text":"grīṣme tathāśaradi ye raviśoṣitāṅgā ye ca pramattavanitāsuratātikhinnāḥ ye cāpi mārgaparisarpaṇaśīrṇagātrāsteṣāmiyaṃ vapuṣi poṣaṇamāśu kuryāt"},{"type":"verse","number":"146","sanskrit":"रसाला शुक्रला वल्या रोचनी वातपित्तजित्","text":"rasālā śukralā valyā rocanī vātapittajit"},{"type":"verse","number":"147","sanskrit":"दीपनी बृंहणी स्निग्धा मधुरा शिशिरा सरा रक्तपित्तं तृषां दाहं प्रतिश्यायं विनाशयेत्","text":"dīpanī bṛṃhaṇī snigdhā madhurā śiśirā sarā raktapittaṃ tṛṣāṃ dāhaṃ pratiśyāyaṃ vināśayet"},{"type":"verse","number":"148","sanskrit":"जलेन शीतलेनैव घोलिता शुभ्रशर्करा एलालवङ्गकर्पूरमरिचैश्च समन्विता","text":"jalena śītalenaiva gholitā śubhraśarkarā elālavaṅgakarpūramaricaiśca samanvitā"},{"type":"verse","number":"149","sanskrit":"शर्करोदकनाम्ना तत्प्रसिद्धं विदुषां मुखैः शर्करोदकमाख्यातं शुक्रलं शिशिरं सरम्","text":"śarkarodakanāmnā tatprasiddhaṃ viduṣāṃ mukhaiḥ śarkarodakamākhyātaṃ śukralaṃ śiśiraṃ saram"},{"type":"verse","number":"150","sanskrit":"बल्यं रुच्यं लघु स्वादु वातपित्तप्रणाशनम् मूर्च्छाछर्दितृषादाहज्वरशान्तिकरं परम्","text":"balyaṃ rucyaṃ laghu svādu vātapittapraṇāśanam mūrcchācharditṛṣādāhajvaraśāntikaraṃ param"},{"type":"verse","number":"151","sanskrit":"आम्रमामं जले स्विन्नं मर्दितं दृढपाणिना सिताशीताम्बुसंयुक्तं कर्पूरमरिचान्वितम्","text":"āmramāmaṃ jale svinnaṃ marditaṃ dṛḍhapāṇinā sitāśītāmbusaṃyuktaṃ karpūramaricānvitam"},{"type":"verse","number":"152","sanskrit":"प्रपाणकमिदं श्रेष्ठं भीमसेनेन निर्मितम् सद्यो रुचिकरं बल्यं शीघ्रमिन्द्रि वतर्पणम्","text":"prapāṇakamidaṃ śreṣṭhaṃ bhīmasenena nirmitam sadyo rucikaraṃ balyaṃ śīghramindri vatarpaṇam"},{"type":"verse","number":"153","sanskrit":"अम्लिकायाः फलं पक्वं मर्दितं वारिणा दृढम् शर्करामरिचैर्मिश्रं लवङ्गेन्दुसुवासितम्","text":"amlikāyāḥ phalaṃ pakvaṃ marditaṃ vāriṇā dṛḍham śarkarāmaricairmiśraṃ lavaṅgendusuvāsitam"},{"type":"verse","number":"154","sanskrit":"अम्लिकाफलसम्भूतं पानकं वातनाशनम् पित्तश्लेष्मकरं किञ्चित्सुरुच्यं वह्निबोधनम्","text":"amlikāphalasambhūtaṃ pānakaṃ vātanāśanam pittaśleṣmakaraṃ kiñcitsurucyaṃ vahnibodhanam"},{"type":"verse","number":"155","sanskrit":"भागैकं निम्बुजं तोयं षड्भागं शर्करोदकम् लवङ्गमरिचैर्मिश्रं पानं पानकमुत्तमम्","text":"bhāgaikaṃ nimbujaṃ toyaṃ ṣaḍbhāgaṃ śarkarodakam lavaṅgamaricairmiśraṃ pānaṃ pānakamuttamam"},{"type":"verse","number":"156","sanskrit":"निम्बूकफलभवं पानमत्यम्लं वातनाशनम् वह्निदीप्तिकरं रुच्यं समस्ताहारपाचकम्","text":"nimbūkaphalabhavaṃ pānamatyamlaṃ vātanāśanam vahnidīptikaraṃ rucyaṃ samastāhārapācakam"},{"type":"verse","number":"157","sanskrit":"शिलायां साधु सम्पिष्टं धान्याकं वस्त्रगालितम् शर्करोदकसंयुक्तं कर्पूरादिसुसंस्कृतम् नूतने मृण्मये पात्रे स्थितं पित्तहरं परम्","text":"śilāyāṃ sādhu sampiṣṭaṃ dhānyākaṃ vastragālitam śarkarodakasaṃyuktaṃ karpūrādisusaṃskṛtam nūtane mṛṇmaye pātre sthitaṃ pittaharaṃ param"},{"type":"verse","number":"158","sanskrit":"काञ्जिकं रोचनं रुच्यं पाचनं वह्निदीपनम्","text":"kāñjikaṃ rocanaṃ rucyaṃ pācanaṃ vahnidīpanam"},{"type":"verse","number":"159","sanskrit":"शूलाजीर्णविबन्धघ्नं कोष्ठशुद्धिकरं परम् न भवेत्काञ्जिकं यत्र तत्र जालि प्रदीयते","text":"śūlājīrṇavibandhaghnaṃ koṣṭhaśuddhikaraṃ param na bhavetkāñjikaṃ yatra tatra jāli pradīyate"},{"type":"verse","number":"160","sanskrit":"आममाम्रफलं पिष्टं राजिकालवणान्वितम् मृष्टहिङ्गुयुतं पूतं घोलितं जालिरुच्यते","text":"āmamāmraphalaṃ piṣṭaṃ rājikālavaṇānvitam mṛṣṭahiṅguyutaṃ pūtaṃ gholitaṃ jālirucyate"},{"type":"verse","number":"161","sanskrit":"जालिर्हरति जिह्वायाः कुण्ठत्वं कण्ठशोधिनी मन्दं मन्दन्तु पीता सा रोचनी वह्निबोधिनी","text":"jālirharati jihvāyāḥ kuṇṭhatvaṃ kaṇṭhaśodhinī mandaṃ mandantu pītā sā rocanī vahnibodhinī"},{"type":"verse","number":"162","sanskrit":"तुर्यांशेन जलेन संयुतमतिस्थूलं सदम्लं दधि प्रायोमाहिषमम्बुकेन विमले मृद्भाजने गालयेत् भृष्टं हिंगुच जीरकञ्चलवणं राजीञ्च किञ्चिन्मितां पिष्टां तत्र विमिश्रयेद्भवति तत्तक्रं न कस्य प्रियम्","text":"turyāṃśena jalena saṃyutamatisthūlaṃ sadamlaṃ dadhi prāyomāhiṣamambukena vimale mṛdbhājane gālayet bhṛṣṭaṃ hiṃguca jīrakañcalavaṇaṃ rājīñca kiñcinmitāṃ piṣṭāṃ tatra vimiśrayedbhavati tattakraṃ na kasya priyam"},{"type":"verse","number":"163","sanskrit":"तक्रं रुचिकरं वह्निदीपनं पाचनं परम् उदरे ये गदास्तेषां नाशनं तृप्तिकारकम्","text":"takraṃ rucikaraṃ vahnidīpanaṃ pācanaṃ param udare ye gadāsteṣāṃ nāśanaṃ tṛptikārakam"},{"type":"verse","number":"164","sanskrit":"विदाहीन्यन्नपानानि यानि भुङ्क्ते हि मानवः तद्विदाहप्रशान्त्यर्थं भोजनान्ते पयः पिबेत्","text":"vidāhīnyannapānāni yāni bhuṅkte hi mānavaḥ tadvidāhapraśāntyarthaṃ bhojanānte payaḥ pibet"},{"type":"verse","number":"165","sanskrit":"धान्यानि भ्राष्ट्रभृष्टानि यन्त्रपिष्टानि सक्तवः","text":"dhānyāni bhrāṣṭrabhṛṣṭāni yantrapiṣṭāni saktavaḥ"},{"type":"verse","number":"166","sanskrit":"यवजाः सक्तवः शीता दीपना लघवः सराः कफपित्तहरा रूक्षा लेखनाश्च प्रकीर्त्तिताः","text":"yavajāḥ saktavaḥ śītā dīpanā laghavaḥ sarāḥ kaphapittaharā rūkṣā lekhanāśca prakīrttitāḥ"},{"type":"verse","number":"167","sanskrit":"ते पीता बलदा वृष्या बृंहणा भेदनास्तथा तर्पणा मधुरा रुच्याः परिणामे बलावहाः","text":"te pītā baladā vṛṣyā bṛṃhaṇā bhedanāstathā tarpaṇā madhurā rucyāḥ pariṇāme balāvahāḥ"},{"type":"verse","number":"168","sanskrit":"प्रशस्ता घर्मदाहाध्वव्यायामार्त्तशरीरिणाम्","text":"praśastā gharmadāhādhvavyāyāmārttaśarīriṇām"},{"type":"verse","number":"169","sanskrit":"निस्तुषैश्चणकैर्भृष्टैस्तुर्यांशैश्च यवैः कृताः सक्तवः शर्करासर्पिर्युक्ता ग्रीष्मेऽपि पूजिता","text":"nistuṣaiścaṇakairbhṛṣṭaisturyāṃśaiśca yavaiḥ kṛtāḥ saktavaḥ śarkarāsarpiryuktā grīṣme'pi pūjitā"},{"type":"verse","number":"170","sanskrit":"सक्तवः शालिसम्भूता वह्निदा लघवो हिमाः मधुरा ग्राहिणो रुच्याः पथ्याश्च बलशुक्रदा","text":"saktavaḥ śālisambhūtā vahnidā laghavo himāḥ madhurā grāhiṇo rucyāḥ pathyāśca balaśukradā"},{"type":"verse","number":"171","sanskrit":"न भुक्त्वा न रदैश्छित्वा न निशायां न वा बहून् नजलान्तरितानद्भिः सक्तूनद्यान्न केवलान्","text":"na bhuktvā na radaiśchitvā na niśāyāṃ na vā bahūn najalāntaritānadbhiḥ saktūnadyānna kevalān"},{"type":"verse","number":"172","sanskrit":"पृथक्पानं पुनर्दानं सामिषं पयसा निशि दन्तच्छेदनमुष्णञ्च सप्त सक्तुषु वर्जयेत्","text":"pṛthakpānaṃ punardānaṃ sāmiṣaṃ payasā niśi dantacchedanamuṣṇañca sapta saktuṣu varjayet"},{"type":"verse","number":"173","sanskrit":"यवास्तु निस्तुषा भृष्टाः स्मृता धाना इति स्त्रियाम् धानाः स्युर्दुर्जरा रुक्षास्तृट्प्रदा गुरवश्च ताः तथा मेहकफच्छर्दिनाशिन्यः सम्प्रकीर्त्तिताः","text":"yavāstu nistuṣā bhṛṣṭāḥ smṛtā dhānā iti striyām dhānāḥ syurdurjarā rukṣāstṛṭpradā guravaśca tāḥ tathā mehakaphacchardināśinyaḥ samprakīrttitāḥ"},{"type":"verse","number":"174","sanskrit":"येषां स्युस्तण्डुलास्तानि धान्यानि सतुषाणि च भृष्टानि स्फुटितान्याहुर्लाजा इति मनीषिणः","text":"yeṣāṃ syustaṇḍulāstāni dhānyāni satuṣāṇi ca bhṛṣṭāni sphuṭitānyāhurlājā iti manīṣiṇaḥ"},{"type":"verse","number":"175","sanskrit":"लाजाः स्युर्मधुराः शीता लघवो दीपनाश्च ते स्वल्पमूत्रमला रूक्षा बल्याः पित्तकफच्छिदः छर्द्यतीसारदाहास्रमेहमेदस्तृषाऽपहाः","text":"lājāḥ syurmadhurāḥ śītā laghavo dīpanāśca te svalpamūtramalā rūkṣā balyāḥ pittakaphacchidaḥ chardyatīsāradāhāsramehamedastṛṣā'pahāḥ"},{"type":"verse","number":"176","sanskrit":"शालयः सतुषा आद्रा र्! भृष्टा अस्फुटितास्ततः कुट्टिताश्चिपिटाःप्रोक्तास्ते स्मृताः पृथुका अपि","text":"śālayaḥ satuṣā ādrā r! bhṛṣṭā asphuṭitāstataḥ kuṭṭitāścipiṭāḥproktāste smṛtāḥ pṛthukā api"},{"type":"verse","number":"177","sanskrit":"पृथुका गुरवो वातनाशनाः श्लेष्मला अपि सक्षीरा बृंहणा वृष्या बल्या भिन्नमलाश्च ते","text":"pṛthukā guravo vātanāśanāḥ śleṣmalā api sakṣīrā bṛṃhaṇā vṛṣyā balyā bhinnamalāśca te"},{"type":"verse","number":"178","sanskrit":"अर्द्धपक्वैः शमीधान्यैस्तृणभृष्टैश्च होलकः होलकोऽल्पानिलोः मेदः कफदोषत्रयापहः भवेद् यो होलको यस्य स च तत्तद्गुणो भवेत्","text":"arddhapakvaiḥ śamīdhānyaistṛṇabhṛṣṭaiśca holakaḥ holako'lpāniloḥ medaḥ kaphadoṣatrayāpahaḥ bhaved yo holako yasya sa ca tattadguṇo bhavet"},{"type":"verse","number":"179","sanskrit":"मञ्जरी त्वर्द्धपक्वा वा यवगोधूमयोर्भवेत् तृणानलेन संभृष्टा बुधैरूचीति सा स्मृता ऊची कफप्रदा बल्या लघ्वी पित्तानिलापहा","text":"mañjarī tvarddhapakvā vā yavagodhūmayorbhavet tṛṇānalena saṃbhṛṣṭā budhairūcīti sā smṛtā ūcī kaphapradā balyā laghvī pittānilāpahā"},{"type":"verse","number":"180","sanskrit":"अर्धस्विन्नास्तु गोधूमा अन्येऽपि चणकादयः","text":"ardhasvinnāstu godhūmā anye'pi caṇakādayaḥ"},{"type":"verse","number":"181","sanskrit":"कुल्माषा इति कथ्यन्ते शब्दशास्त्रेषु पण्डितैः कुल्माषागुरवो रूक्षा वातला भिन्नवर्चसः","text":"kulmāṣā iti kathyante śabdaśāstreṣu paṇḍitaiḥ kulmāṣāguravo rūkṣā vātalā bhinnavarcasaḥ"},{"type":"verse","number":"182","sanskrit":"पललन्तु समाख्यातं सैक्षवं तिलपिष्टकम् पललं मलकृद् वृष्यं वातघ्नं कफपित्तकृत् बृंहणं च गुरु स्निग्धं मूत्राधिक्यनिवर्त्तकम्","text":"palalantu samākhyātaṃ saikṣavaṃ tilapiṣṭakam palalaṃ malakṛd vṛṣyaṃ vātaghnaṃ kaphapittakṛt bṛṃhaṇaṃ ca guru snigdhaṃ mūtrādhikyanivarttakam"},{"type":"verse","number":"183","sanskrit":"तिलकिट्टन्तु पिण्याकस्तथा तिलखलि स्मृता पिण्याको लेखनो रूक्षो विष्टम्भी दृष्टिदूषणः","text":"tilakiṭṭantu piṇyākastathā tilakhali smṛtā piṇyāko lekhano rūkṣo viṣṭambhī dṛṣṭidūṣaṇaḥ"},{"type":"verse","number":"184","sanskrit":"तुण्डुलो मेहजन्तुघ्नः स नवस्त्वतिदुर्जरः","text":"tuṇḍulo mehajantughnaḥ sa navastvatidurjaraḥ"},{"type":"verse","number":"12","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे द्वादशः कृतान्नवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe dvādaśaḥ kṛtānnavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":12,"lang":"sa","content":[{"type":"heading","heading":"vāri-варга — вода"},{"type":"verse","number":"1","sanskrit":"पानीयं सलिलं नीरं कीलालं जलमम्बु च आपो वार्वारि कं तोयं पयः पाथस्तथोदकम् जीवनं वनमम्भोऽणोऽमृतं घनरसोऽपि च","text":"pānīyaṃ salilaṃ nīraṃ kīlālaṃ jalamambu ca āpo vārvāri kaṃ toyaṃ payaḥ pāthastathodakam jīvanaṃ vanamambho'ṇo'mṛtaṃ ghanaraso'pi ca"},{"type":"verse","number":"2","sanskrit":"पानीयं श्रमनाशनं क्लमहरं मूर्च्छापिपासापहं तन्द्रा च्छर्दिविबन्धहृद्बलकरं निद्रा हरं तर्पणम् हृद्यं गुप्तरसं ह्यजीर्णशमकं नित्यं हितं शीतलं लघ्वच्छं रसकारणं निगदितं पीयूषवज्जीवनम्","text":"pānīyaṃ śramanāśanaṃ klamaharaṃ mūrcchāpipāsāpahaṃ tandrā cchardivibandhahṛdbalakaraṃ nidrā haraṃ tarpaṇam hṛdyaṃ guptarasaṃ hyajīrṇaśamakaṃ nityaṃ hitaṃ śītalaṃ laghvacchaṃ rasakāraṇaṃ nigaditaṃ pīyūṣavajjīvanam"},{"type":"verse","number":"3","sanskrit":"पानीयं मुनिभिः प्रोक्तं दिव्यं भौममिति द्विधा","text":"pānīyaṃ munibhiḥ proktaṃ divyaṃ bhaumamiti dvidhā"},{"type":"verse","number":"4","sanskrit":"दिव्यं चतुर्विधं प्रोक्तं धाराजं करकाभवम् तौषारञ्च तथा हैमं तेषु धारं गुणाधिकम्","text":"divyaṃ caturvidhaṃ proktaṃ dhārājaṃ karakābhavam tauṣārañca tathā haimaṃ teṣu dhāraṃ guṇādhikam"},{"type":"verse","number":"5","sanskrit":"धाराभिः पतितं तोयं गृहीतं स्फीतवाससा शिलायां वसुधायां वा धौतायां पतितञ्च तत्","text":"dhārābhiḥ patitaṃ toyaṃ gṛhītaṃ sphītavāsasā śilāyāṃ vasudhāyāṃ vā dhautāyāṃ patitañca tat"},{"type":"verse","number":"6","sanskrit":"सौवर्णे राजते ताम्रे स्फाटिके काचनिर्मिते भाजने मृण्मये वाऽपि स्थापितं धारमुच्यते","text":"sauvarṇe rājate tāmre sphāṭike kācanirmite bhājane mṛṇmaye vā'pi sthāpitaṃ dhāramucyate"},{"type":"verse","number":"7","sanskrit":"धारं नीरं त्रिदोषघ्नमनिर्देश्यरसं लघु सौम्यं रसायनं बल्यं तर्पणं ह्लादि जीवनम्","text":"dhāraṃ nīraṃ tridoṣaghnamanirdeśyarasaṃ laghu saumyaṃ rasāyanaṃ balyaṃ tarpaṇaṃ hlādi jīvanam"},{"type":"verse","number":"8","sanskrit":"पाचनं मतिकृन्मूर्च्छातन्द्रा दाहश्रमक्लमान् तृष्णां हरति तत् पथ्यं विशेषात्प्रावृषि स्मृतम्","text":"pācanaṃ matikṛnmūrcchātandrā dāhaśramaklamān tṛṣṇāṃ harati tat pathyaṃ viśeṣātprāvṛṣi smṛtam"},{"type":"verse","number":"9","sanskrit":"धाराजलं च द्विविधं गाङ्गसामुद्र भेदतः","text":"dhārājalaṃ ca dvividhaṃ gāṅgasāmudra bhedataḥ"},{"type":"verse","number":"10","sanskrit":"आकाशगङ्गासम्बन्धिजलमादाय दिग्गजाः मेघैरन्तरिता वृष्टिं कुर्वन्तीति वचः सताम्","text":"ākāśagaṅgāsambandhijalamādāya diggajāḥ meghairantaritā vṛṣṭiṃ kurvantīti vacaḥ satām"},{"type":"verse","number":"11","sanskrit":"गाङ्गमाश्वयुजे मासि प्रायो वर्षति वारिदः सर्वथा तज्जलं ज्ञेयं तथैव चरके वचः","text":"gāṅgamāśvayuje māsi prāyo varṣati vāridaḥ sarvathā tajjalaṃ jñeyaṃ tathaiva carake vacaḥ"},{"type":"verse","number":"12","sanskrit":"स्थापिते हेमजे पात्रे राजते मृण्मयेऽपि वा शाल्यन्नं येन संसिक्तं भवेदक्लेदि वर्णवत्","text":"sthāpite hemaje pātre rājate mṛṇmaye'pi vā śālyannaṃ yena saṃsiktaṃ bhavedakledi varṇavat"},{"type":"verse","number":"13","sanskrit":"तद्गाङ्गं सर्वदोषघ्नं ज्ञेयं सामुद्र मन्यथा तत्तु सक्षारलवणं शुक्रदृष्टिबलापहम्","text":"tadgāṅgaṃ sarvadoṣaghnaṃ jñeyaṃ sāmudra manyathā tattu sakṣāralavaṇaṃ śukradṛṣṭibalāpaham"},{"type":"verse","number":"14","sanskrit":"विस्रञ्च दोषलं तीक्ष्णं सर्वकर्मसु नो हितम् सामुद्रं त्वाश्विने मासि गुणैर्गाङ्गवदादिशेत्","text":"visrañca doṣalaṃ tīkṣṇaṃ sarvakarmasu no hitam sāmudraṃ tvāśvine māsi guṇairgāṅgavadādiśet"},{"type":"verse","number":"15","sanskrit":"यतोऽगस्त्यस्य दिव्यर्षेरुदयात्सकलं जलम् निर्मलं निर्विषं स्वादु शुक्रलं स्याददोषलम्","text":"yato'gastyasya divyarṣerudayātsakalaṃ jalam nirmalaṃ nirviṣaṃ svādu śukralaṃ syādadoṣalam"},{"type":"verse","number":"16","sanskrit":"फूत्कारविषवातेन नागानां व्योमचारिणाम् वर्षासु सविषं तोयं दिव्यमप्याश्विनं विना","text":"phūtkāraviṣavātena nāgānāṃ vyomacāriṇām varṣāsu saviṣaṃ toyaṃ divyamapyāśvinaṃ vinā"},{"type":"verse","number":"17","sanskrit":"अनार्त्तवं प्रमुञ्चन्ति वारि वारिधरास्तु यत् तत्त्रिदोषाय सर्वेषां देहिनां परिकीर्त्तितम्","text":"anārttavaṃ pramuñcanti vāri vāridharāstu yat tattridoṣāya sarveṣāṃ dehināṃ parikīrttitam"},{"type":"verse","number":"18","sanskrit":"दिव्यवाय्वग्निसंयोगात् संहताः खात् पतन्ति याः पाषाणखण्डवच्चापस्ताः कारक्योऽमृतोपमाः","text":"divyavāyvagnisaṃyogāt saṃhatāḥ khāt patanti yāḥ pāṣāṇakhaṇḍavaccāpastāḥ kārakyo'mṛtopamāḥ"},{"type":"verse","number":"19","sanskrit":"करकाजं जलं रूक्षं विशदं गुरु च स्थिरम् दारुणं शीतलं सान्द्रं पित्तहृत्कफवातकृत्","text":"karakājaṃ jalaṃ rūkṣaṃ viśadaṃ guru ca sthiram dāruṇaṃ śītalaṃ sāndraṃ pittahṛtkaphavātakṛt"},{"type":"verse","number":"20","sanskrit":"अपि नद्याः समुद्रा न्ते वह्निरापस्तदुद्भवाः धूमावयवनिर्मुक्तास्तुषाराख्यास्तु ताः स्मृताः","text":"api nadyāḥ samudrā nte vahnirāpastadudbhavāḥ dhūmāvayavanirmuktāstuṣārākhyāstu tāḥ smṛtāḥ"},{"type":"verse","number":"21","sanskrit":"अपथ्याः प्राणिनां प्रायो भूरुहाणान्तु ता हिताः तुषाराम्बु हिमं रूक्षं स्याद्वातलमपित्तलम् कफोरुस्तम्भकण्ठाग्निमेहगण्डादिरोगनुत्","text":"apathyāḥ prāṇināṃ prāyo bhūruhāṇāntu tā hitāḥ tuṣārāmbu himaṃ rūkṣaṃ syādvātalamapittalam kaphorustambhakaṇṭhāgnimehagaṇḍādiroganut"},{"type":"verse","number":"22","sanskrit":"हिमवच्छिखरादिभ्यो द्र वीभूयाभिवर्षति यत्तदेव हिमं हैमं जलमाहुर्मनीषिणः हिमाम्बु शीतं पित्तघ्नं गुरु वातविवर्द्धनम्","text":"himavacchikharādibhyo dra vībhūyābhivarṣati yattadeva himaṃ haimaṃ jalamāhurmanīṣiṇaḥ himāmbu śītaṃ pittaghnaṃ guru vātavivarddhanam"},{"type":"verse","number":"23","sanskrit":"और्वानलधूमेरितमम्बु समुद्र स्य यद्घनीभूतम् पवनानीतमुदीच्यां तद्धिममिति कथ्यते सद्भिः","text":"aurvānaladhūmeritamambu samudra sya yadghanībhūtam pavanānītamudīcyāṃ taddhimamiti kathyate sadbhiḥ"},{"type":"verse","number":"24","sanskrit":"हिमन्तु शीतलं रूक्षं दारुणं सूक्ष्ममित्यपि न तद् दूषयते वातं न च पित्तं न वा कफम्","text":"himantu śītalaṃ rūkṣaṃ dāruṇaṃ sūkṣmamityapi na tad dūṣayate vātaṃ na ca pittaṃ na vā kapham"},{"type":"verse","number":"25","sanskrit":"भौममम्भो निगदितं प्रथमं त्रिविधं बुधैः जाङ्गलं परमानूपं ततः साधारणं क्रमात्","text":"bhaumamambho nigaditaṃ prathamaṃ trividhaṃ budhaiḥ jāṅgalaṃ paramānūpaṃ tataḥ sādhāraṇaṃ kramāt"},{"type":"verse","number":"26","sanskrit":"अल्पोदकोऽल्पवृक्षश्च पित्तरक्तामयान्वितः ज्ञातव्यो जाङ्गलो देशस्तत्रत्यं जाङ्गलं जलम्","text":"alpodako'lpavṛkṣaśca pittaraktāmayānvitaḥ jñātavyo jāṅgalo deśastatratyaṃ jāṅgalaṃ jalam"},{"type":"verse","number":"27","sanskrit":"वह्वम्बुर्बहुवृक्षश्च वातश्लेष्मामयान्वितः देशोऽनूप इति ख्यात आनूपं तद्भवं जलम्","text":"vahvamburbahuvṛkṣaśca vātaśleṣmāmayānvitaḥ deśo'nūpa iti khyāta ānūpaṃ tadbhavaṃ jalam"},{"type":"verse","number":"28","sanskrit":"मिश्रचिह्नस्तु यो देशः स हि साधारणः स्मृतः तस्मिन्देशे यदुदकं तत्तु साधारणं स्मृतम्","text":"miśracihnastu yo deśaḥ sa hi sādhāraṇaḥ smṛtaḥ tasmindeśe yadudakaṃ tattu sādhāraṇaṃ smṛtam"},{"type":"verse","number":"29","sanskrit":"जाङ्गलं सलिलं रूक्षं लवणं लघु पित्तनुत् वह्निकृत्कफहृत्पथ्यं विकारान्हरते बहून्","text":"jāṅgalaṃ salilaṃ rūkṣaṃ lavaṇaṃ laghu pittanut vahnikṛtkaphahṛtpathyaṃ vikārānharate bahūn"},{"type":"verse","number":"30","sanskrit":"आनूपं वार्यभिष्यन्दि स्वादु स्निग्धं घनं गुरु वह्निहृत्कफकृद्हृद्यं विकारान्कुरुते बहून्","text":"ānūpaṃ vāryabhiṣyandi svādu snigdhaṃ ghanaṃ guru vahnihṛtkaphakṛdhṛdyaṃ vikārānkurute bahūn"},{"type":"verse","number":"31","sanskrit":"साधारणं तु मधुरं दीपनं शीतलं लघु तर्पणं रोचनं तृष्णादाहदोषत्रयप्रणुत्","text":"sādhāraṇaṃ tu madhuraṃ dīpanaṃ śītalaṃ laghu tarpaṇaṃ rocanaṃ tṛṣṇādāhadoṣatrayapraṇut"},{"type":"verse","number":"32","sanskrit":"नद्या नदस्य वा नीरं नादेयमिति कीर्त्तितम्","text":"nadyā nadasya vā nīraṃ nādeyamiti kīrttitam"},{"type":"verse","number":"33","sanskrit":"नादेयमुदकं रूक्षं वातलं लघु दीपनम् अनभिष्यन्दि विशदं कटुकं कफपित्तनुत्","text":"nādeyamudakaṃ rūkṣaṃ vātalaṃ laghu dīpanam anabhiṣyandi viśadaṃ kaṭukaṃ kaphapittanut"},{"type":"verse","number":"34","sanskrit":"नद्यः शीघ्रवहा लघ्व्यः सर्वा याश्चामलोदकाः गुर्व्यः शैवलसंछन्ना मन्दगाः कलुषाश्च याः","text":"nadyaḥ śīghravahā laghvyaḥ sarvā yāścāmalodakāḥ gurvyaḥ śaivalasaṃchannā mandagāḥ kaluṣāśca yāḥ"},{"type":"verse","number":"35","sanskrit":"हिमवत्प्रभवाः पथ्या नद्योऽश्माहतपाथसः गङ्गाशतद्रुसरयूयमुनाऽद्या गुणोत्तमाः","text":"himavatprabhavāḥ pathyā nadyo'śmāhatapāthasaḥ gaṅgāśatadrusarayūyamunā'dyā guṇottamāḥ"},{"type":"verse","number":"36","sanskrit":"सह्यशैलभवा नद्यो वेणागोदावरीमुखाः कुर्वन्ति प्रायशः कुष्ठमीषद्वातकफावहाः","text":"sahyaśailabhavā nadyo veṇāgodāvarīmukhāḥ kurvanti prāyaśaḥ kuṣṭhamīṣadvātakaphāvahāḥ"},{"type":"verse","number":"37","sanskrit":"नदीसरस्तडागस्थे कूपप्रस्रवणादिजे उदके देशभेदेन गुणान्दोषांश्च लक्षयेत्","text":"nadīsarastaḍāgasthe kūpaprasravaṇādije udake deśabhedena guṇāndoṣāṃśca lakṣayet"},{"type":"verse","number":"38","sanskrit":"विदार्य भूमिं निम्नां यन्महत्या धारया स्रवेत् तत्तोयमौद्भिदं नाम वदन्तीति महर्षयः","text":"vidārya bhūmiṃ nimnāṃ yanmahatyā dhārayā sravet tattoyamaudbhidaṃ nāma vadantīti maharṣayaḥ"},{"type":"verse","number":"49","sanskrit":"औद्भिदं वारि पित्तघ्नमविदाह्यतिशीतलम् प्रीणनं मधुरं बल्यमीषद्वातकरं लघु","text":"audbhidaṃ vāri pittaghnamavidāhyatiśītalam prīṇanaṃ madhuraṃ balyamīṣadvātakaraṃ laghu"},{"type":"verse","number":"40","sanskrit":"शैलसानुस्रवद्वारिप्रवाहो निर्झरो झरः स तु प्रस्रवणश्चापि तत्रत्यं नैर्झरं जलम्","text":"śailasānusravadvāripravāho nirjharo jharaḥ sa tu prasravaṇaścāpi tatratyaṃ nairjharaṃ jalam"},{"type":"verse","number":"41","sanskrit":"नैर्झरं रुचिकृन्नीरं कफघ्नं दीपनं लघु मधुरं कटुपाकं च वातलं स्यादपित्तलम्","text":"nairjharaṃ rucikṛnnīraṃ kaphaghnaṃ dīpanaṃ laghu madhuraṃ kaṭupākaṃ ca vātalaṃ syādapittalam"},{"type":"verse","number":"42","sanskrit":"नद्याः शैलादिरुद्धायाः यत्र संस्रुत्य तिष्ठति तत्सरो जलजच्छन्नं तदम्भः सारसं स्मृतम्","text":"nadyāḥ śailādiruddhāyāḥ yatra saṃsrutya tiṣṭhati tatsaro jalajacchannaṃ tadambhaḥ sārasaṃ smṛtam"},{"type":"verse","number":"43","sanskrit":"सारसं सलिलं बल्यं तृष्णाघ्नं मधुरं लघु रोचनं तुवरं रूक्षं बद्धमूत्रमलं स्मृतम्","text":"sārasaṃ salilaṃ balyaṃ tṛṣṇāghnaṃ madhuraṃ laghu rocanaṃ tuvaraṃ rūkṣaṃ baddhamūtramalaṃ smṛtam"},{"type":"verse","number":"44","sanskrit":"प्रशस्तभूमिभागस्थो बहुसंवत्सरोषितः जलाशयस्तडागः स्यात्ताडागं तज्जलं स्मृतम्","text":"praśastabhūmibhāgastho bahusaṃvatsaroṣitaḥ jalāśayastaḍāgaḥ syāttāḍāgaṃ tajjalaṃ smṛtam"},{"type":"verse","number":"45","sanskrit":"ताडागमुदकं स्वादु कषायं कटुपाकि च वातलं बद्धविण्मूत्रमसृक्पित्तकफापहम्","text":"tāḍāgamudakaṃ svādu kaṣāyaṃ kaṭupāki ca vātalaṃ baddhaviṇmūtramasṛkpittakaphāpaham"},{"type":"verse","number":"46","sanskrit":"पाषाणैरिष्टकाभिर्वा बद्धः कूपो बृहत्तरः ससोपानो भवेद्वापी तज्जलं वाप्यमुच्यते","text":"pāṣāṇairiṣṭakābhirvā baddhaḥ kūpo bṛhattaraḥ sasopāno bhavedvāpī tajjalaṃ vāpyamucyate"},{"type":"verse","number":"47","sanskrit":"वाप्यं वारि यदि क्षारं पित्तकृत्कफवातहृत् तदेव मिष्टं कफकृद्वातपित्तहरं भवेत्","text":"vāpyaṃ vāri yadi kṣāraṃ pittakṛtkaphavātahṛt tadeva miṣṭaṃ kaphakṛdvātapittaharaṃ bhavet"},{"type":"verse","number":"48","sanskrit":"भूमौ खातोऽल्पविस्तारो गम्भीरो मण्डलाकृतिः बद्धोऽबद्धः स कूपः स्यात्तदम्भः कौपमुच्यते","text":"bhūmau khāto'lpavistāro gambhīro maṇḍalākṛtiḥ baddho'baddhaḥ sa kūpaḥ syāttadambhaḥ kaupamucyate"},{"type":"verse","number":"49","sanskrit":"कौपं पयो यदि स्वादु त्रिदोषघ्नं हितं लघु तत्क्षारं कफवातघ्नं दीपनं पित्तकृत्परम्","text":"kaupaṃ payo yadi svādu tridoṣaghnaṃ hitaṃ laghu tatkṣāraṃ kaphavātaghnaṃ dīpanaṃ pittakṛtparam"},{"type":"verse","number":"50","sanskrit":"शिलाकीर्णं स्वयं श्वभ्रं नीलाञ्जनसमोदकम् लतावितानसंच्छन्नं चौञ्ज्यमित्यभिधीयते","text":"śilākīrṇaṃ svayaṃ śvabhraṃ nīlāñjanasamodakam latāvitānasaṃcchannaṃ cauñjyamityabhidhīyate"},{"type":"verse","number":"51","sanskrit":"अश्मादिभिरबद्धं यत्तच्चौञ्ज्यमिति वा परे तत्रत्त्यमुदकं चौञ्ज्यं मुनिभिस्तदुदाहृतम्","text":"aśmādibhirabaddhaṃ yattaccauñjyamiti vā pare tatrattyamudakaṃ cauñjyaṃ munibhistadudāhṛtam"},{"type":"verse","number":"52","sanskrit":"चौञ्ज्यं वह्निकरं नीरं रूक्षं कफहरं लघु मधुरं पित्तनुद्रुच्यं पाचनं विशदं स्मृतम्","text":"cauñjyaṃ vahnikaraṃ nīraṃ rūkṣaṃ kaphaharaṃ laghu madhuraṃ pittanudrucyaṃ pācanaṃ viśadaṃ smṛtam"},{"type":"verse","number":"53","sanskrit":"अल्पं सरः पल्वलं स्याद्यत्र चन्द्र र्क्षगे रवौ","text":"alpaṃ saraḥ palvalaṃ syādyatra candra rkṣage ravau"},{"type":"verse","number":"54","sanskrit":"न तिष्ठति जलं किञ्चित्तत्रत्यं वारि पाल्वलम् पाल्वलं वार्यभिष्यन्दि गुरु स्वादु त्रिदोषकृत्","text":"na tiṣṭhati jalaṃ kiñcittatratyaṃ vāri pālvalam pālvalaṃ vāryabhiṣyandi guru svādu tridoṣakṛt"},{"type":"verse","number":"55","sanskrit":"नद्यादिनिकटे भूमिर्या भवेद्वालुकामयी उद्भाव्यते ततो यत्तु तज्जलं विकिरं विदुः","text":"nadyādinikaṭe bhūmiryā bhavedvālukāmayī udbhāvyate tato yattu tajjalaṃ vikiraṃ viduḥ"},{"type":"verse","number":"56","sanskrit":"विकिरं शीतलं स्वच्छं निर्दोषं लघु च स्मृतम् तुवरं स्वादु पित्तघ्नं क्षारं तर्त्पित्तलं मनाक्","text":"vikiraṃ śītalaṃ svacchaṃ nirdoṣaṃ laghu ca smṛtam tuvaraṃ svādu pittaghnaṃ kṣāraṃ tartpittalaṃ manāk"},{"type":"verse","number":"57","sanskrit":"केदारः क्षेत्रमुद्दिष्टं कैदारं तज्जलं स्मृतम् कैदारं वार्यभिष्यन्दि मधुरं गुरु दोषकृत्","text":"kedāraḥ kṣetramuddiṣṭaṃ kaidāraṃ tajjalaṃ smṛtam kaidāraṃ vāryabhiṣyandi madhuraṃ guru doṣakṛt"},{"type":"verse","number":"58","sanskrit":"वार्षिकं तदहर्वृष्टं भूमिस्थमहितं जलम् त्रिरात्रमुषितं तत्तु प्रसन्नममृतोपमम्","text":"vārṣikaṃ tadaharvṛṣṭaṃ bhūmisthamahitaṃ jalam trirātramuṣitaṃ tattu prasannamamṛtopamam"},{"type":"verse","number":"59","sanskrit":"हेमन्ते सारसं तोयं ताडागं वा हितं स्मृतम् हेमन्ते विहितं तोयं शिशिरेऽपि प्रशस्यते","text":"hemante sārasaṃ toyaṃ tāḍāgaṃ vā hitaṃ smṛtam hemante vihitaṃ toyaṃ śiśire'pi praśasyate"},{"type":"verse","number":"60","sanskrit":"वसन्तग्रीष्मयोः कौपं वाप्यं वा नैर्झरं जलम् नादेयं वारि नादेयं वसन्तग्रीष्मयोर्बुधैः","text":"vasantagrīṣmayoḥ kaupaṃ vāpyaṃ vā nairjharaṃ jalam nādeyaṃ vāri nādeyaṃ vasantagrīṣmayorbudhaiḥ"},{"type":"verse","number":"61","sanskrit":"विषवद्वनवृक्षाणां पत्राद्यैर्दूषितं यतः औद्भिदं वाऽन्तरिक्षं वा कौपं वा प्रावृषि स्मृतम् शस्तं शरदि नादेयं नीरमंशूदकं परम्","text":"viṣavadvanavṛkṣāṇāṃ patrādyairdūṣitaṃ yataḥ audbhidaṃ vā'ntarikṣaṃ vā kaupaṃ vā prāvṛṣi smṛtam śastaṃ śaradi nādeyaṃ nīramaṃśūdakaṃ param"},{"type":"verse","number":"62","sanskrit":"दिवा रविकरैर्जुष्टं निशि शीतकरांशुभिः ज्ञेयमंशूदकं नाम स्निग्धं दोषत्रयापहम्","text":"divā ravikarairjuṣṭaṃ niśi śītakarāṃśubhiḥ jñeyamaṃśūdakaṃ nāma snigdhaṃ doṣatrayāpaham"},{"type":"verse","number":"63","sanskrit":"अनभिष्यन्दि निर्दोषमान्तरिक्षजलोपमम् बल्यं रसायनं मेध्यं शीतं लघु सुधासमम्","text":"anabhiṣyandi nirdoṣamāntarikṣajalopamam balyaṃ rasāyanaṃ medhyaṃ śītaṃ laghu sudhāsamam"},{"type":"verse","number":"64","sanskrit":"शरदि स्वच्छमुदयादगस्त्यादखिलं हितम्","text":"śaradi svacchamudayādagastyādakhilaṃ hitam"},{"type":"verse","number":"65","sanskrit":"पौषे वारि सरोजातं माघे तत्तु तडागजम् फाल्गुने कूपसम्भूतं चैत्रे चौञ्ज्यं हितम् मतम्","text":"pauṣe vāri sarojātaṃ māghe tattu taḍāgajam phālgune kūpasambhūtaṃ caitre cauñjyaṃ hitam matam"},{"type":"verse","number":"66","sanskrit":"वैशाखे नैर्झरं नीरं ज्येष्ठे शस्तं तथौद्भिदम् आषाढे शस्यते कौपं श्रावणे दिव्यमेव च","text":"vaiśākhe nairjharaṃ nīraṃ jyeṣṭhe śastaṃ tathaudbhidam āṣāḍhe śasyate kaupaṃ śrāvaṇe divyameva ca"},{"type":"verse","number":"67","sanskrit":"भाद्रे कौपं पयः शस्तमाश्विने चौञ्ज्यमेव च कार्त्तिके मार्गशीर्षे च जलमात्रं प्रशस्यते","text":"bhādre kaupaṃ payaḥ śastamāśvine cauñjyameva ca kārttike mārgaśīrṣe ca jalamātraṃ praśasyate"},{"type":"verse","number":"68","sanskrit":"भौमानामम्भसां प्रायो ग्रहणं प्रातरिष्यते शीतत्वं निर्मलत्वञ्च यतस्तेषां मतो गुणः","text":"bhaumānāmambhasāṃ prāyo grahaṇaṃ prātariṣyate śītatvaṃ nirmalatvañca yatasteṣāṃ mato guṇaḥ"},{"type":"verse","number":"69","sanskrit":"अत्यम्बुपानान्न पिच्यतेऽन्न निरम्बुपानाच्च स एव दोषः तस्मान्नरो वह्निविवर्द्धनाय मुहुर्मुहुर्वारि पिबेदभूरि","text":"atyambupānānna picyate'nna nirambupānācca sa eva doṣaḥ tasmānnaro vahnivivarddhanāya muhurmuhurvāri pibedabhūri"},{"type":"verse","number":"70","sanskrit":"मूर्च्छापित्तोष्ण दाहेषु विषे रक्ते मदात्यये श्रमे भ्रमे विदग्धेऽन्नेतमके वमथौ तथा ऊर्ध्वगे रक्त पित्ते च शीतमम्भः प्रशस्यते","text":"mūrcchāpittoṣṇa dāheṣu viṣe rakte madātyaye śrame bhrame vidagdhe'nnetamake vamathau tathā ūrdhvage rakta pitte ca śītamambhaḥ praśasyate"},{"type":"verse","number":"71","sanskrit":"पार्श्वशूले प्रतिश्याये वातरोगे गलग्रहे आध्माने स्तिमिते कोष्ठे सद्यःशुद्धौ नवज्वरे","text":"pārśvaśūle pratiśyāye vātaroge galagrahe ādhmāne stimite koṣṭhe sadyaḥśuddhau navajvare"},{"type":"verse","number":"72","sanskrit":"अरुचिग्रहणीगुल्मश्वासकासेषु विद्र धौ हिक्कायां स्नेहपाने च शीताम्बु परिवर्जयेत्","text":"arucigrahaṇīgulmaśvāsakāseṣu vidra dhau hikkāyāṃ snehapāne ca śītāmbu parivarjayet"},{"type":"verse","number":"73","sanskrit":"अरोचके प्रतिश्याये मन्देऽग्नौ श्वयथौ क्षये मुखप्रसेके जठरे कुष्ठे नेत्रामये ज्वरे व्रणे च मधुमेहे च पिबेत्पानीयमल्पकम्","text":"arocake pratiśyāye mande'gnau śvayathau kṣaye mukhapraseke jaṭhare kuṣṭhe netrāmaye jvare vraṇe ca madhumehe ca pibetpānīyamalpakam"},{"type":"verse","number":"74","sanskrit":"जीवनं जीविनां जीवो जगत् सर्वन्तु तन्मयम् नातोऽत्यन्तनिषेधेन कदाचिद्वारि वार्य्यते","text":"jīvanaṃ jīvināṃ jīvo jagat sarvantu tanmayam nāto'tyantaniṣedhena kadācidvāri vāryyate"},{"type":"verse","number":"75","sanskrit":"तृष्णा गरीयसी घोरा सद्यःप्राणविनाशिनी तस्माद् देयं तृषाऽत्ताय पानीयं प्राणधारणम्","text":"tṛṣṇā garīyasī ghorā sadyaḥprāṇavināśinī tasmād deyaṃ tṛṣā'ttāya pānīyaṃ prāṇadhāraṇam"},{"type":"verse","number":"76","sanskrit":"तृषितो मोहमायाति मोहात्प्राणान्विमुञ्चति अतः सर्वास्ववस्थासु न क्वचिद्वारि वारयेत्","text":"tṛṣito mohamāyāti mohātprāṇānvimuñcati ataḥ sarvāsvavasthāsu na kvacidvāri vārayet"},{"type":"verse","number":"77","sanskrit":"अगन्धमव्यक्तरसं सुशीतं तर्षनाशनम् स्वच्छं लघु च हृद्यञ्च तोयं गुणवदुच्यते","text":"agandhamavyaktarasaṃ suśītaṃ tarṣanāśanam svacchaṃ laghu ca hṛdyañca toyaṃ guṇavaducyate"},{"type":"verse","number":"78","sanskrit":"पिच्छिलं कृमिलं क्लिन्नं वर्णशैवालकर्दमैः विवर्णं विरसं सान्द्रं दुर्गन्धं न हितं जलम्","text":"picchilaṃ kṛmilaṃ klinnaṃ varṇaśaivālakardamaiḥ vivarṇaṃ virasaṃ sāndraṃ durgandhaṃ na hitaṃ jalam"},{"type":"verse","number":"79","sanskrit":"कलुषं छन्नमम्भोजपर्णनीलीतृणादिभिः दुःस्पर्शनमसंस्पृष्टं सौरचान्द्र मरीचिभिः","text":"kaluṣaṃ channamambhojaparṇanīlītṛṇādibhiḥ duḥsparśanamasaṃspṛṣṭaṃ sauracāndra marīcibhiḥ"},{"type":"verse","number":"80","sanskrit":"अनार्त्तवं वार्षिकं तु प्रथमं तच्च भूमिगम् व्यापन्नं परिहर्त्तव्यं सर्वदोषप्रकोपणम्","text":"anārttavaṃ vārṣikaṃ tu prathamaṃ tacca bhūmigam vyāpannaṃ pariharttavyaṃ sarvadoṣaprakopaṇam"},{"type":"verse","number":"81","sanskrit":"तत् कुर्यात्स्नानपानाभ्यां तृष्णाऽध्मानचिरज्वरान् कासाग्निमान्द्याभिष्यन्दकण्डूगण्डादिकं तथा","text":"tat kuryātsnānapānābhyāṃ tṛṣṇā'dhmānacirajvarān kāsāgnimāndyābhiṣyandakaṇḍūgaṇḍādikaṃ tathā"},{"type":"verse","number":"82","sanskrit":"निन्दितं चापि पानीयं क्वथितं सूर्यतापितम् सुवर्णं रजतं लौहं पाषाणं सिकतामपि","text":"ninditaṃ cāpi pānīyaṃ kvathitaṃ sūryatāpitam suvarṇaṃ rajataṃ lauhaṃ pāṣāṇaṃ sikatāmapi"},{"type":"verse","number":"83","sanskrit":"भृशं सन्ताप्य निर्वाप्य सप्तधा साधितं तथा कर्पूरजातिपुन्नागपाटलादिसुवासितम्","text":"bhṛśaṃ santāpya nirvāpya saptadhā sādhitaṃ tathā karpūrajātipunnāgapāṭalādisuvāsitam"},{"type":"verse","number":"84","sanskrit":"शुचिसान्द्र पटस्रावि क्षुद्र जन्तुविवर्जितम् स्वच्छं कनकमुक्ताऽद्यै शुद्धं स्याद्दोषवर्जितम्","text":"śucisāndra paṭasrāvi kṣudra jantuvivarjitam svacchaṃ kanakamuktā'dyai śuddhaṃ syāddoṣavarjitam"},{"type":"verse","number":"85","sanskrit":"गोमेदेन च वस्त्रेण कुर्य्यादम्बुप्रसादनम्","text":"gomedena ca vastreṇa kuryyādambuprasādanam"},{"type":"verse","number":"86","sanskrit":"पीतं जलं जीर्य्यति यामयुग्माद्यामैकमात्राच्छृतशीतलञ्च तदर्धमात्रेण शृतं कदुष्णं पयःप्रपाके त्रय एव कालाः","text":"pītaṃ jalaṃ jīryyati yāmayugmādyāmaikamātrācchṛtaśītalañca tadardhamātreṇa śṛtaṃ kaduṣṇaṃ payaḥprapāke traya eva kālāḥ"},{"type":"verse","number":"13","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकणे त्रयोदशो वारिवर्गः समाप्त","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaṇe trayodaśo vārivargaḥ samāpta"}]},{"sthana":"Мадхьямакханда","number":13,"lang":"sa","content":[{"type":"heading","heading":"dugdha-варга — молоко"},{"type":"verse","number":"1","sanskrit":"दुग्धं क्षीरं पयः स्तन्यं बालजीवनमित्यपि दुग्धं सुमधुरं स्निग्धं वातपित्तहरं सरम्","text":"dugdhaṃ kṣīraṃ payaḥ stanyaṃ bālajīvanamityapi dugdhaṃ sumadhuraṃ snigdhaṃ vātapittaharaṃ saram"},{"type":"verse","number":"2","sanskrit":"सद्यः शुक्रकरं शीतं सात्म्यं सर्वशरीरिणाम् जीवनं बृहणं बल्यं मेध्यं वाजीकरं परम् वयःस्थापनमायुष्यं सन्धिकारि रसायनम्","text":"sadyaḥ śukrakaraṃ śītaṃ sātmyaṃ sarvaśarīriṇām jīvanaṃ bṛhaṇaṃ balyaṃ medhyaṃ vājīkaraṃ param vayaḥsthāpanamāyuṣyaṃ sandhikāri rasāyanam"},{"type":"verse","number":"3","sanskrit":"विरेकवान्तिवस्तीनां सेव्यमोजोविवर्द्धनम्","text":"virekavāntivastīnāṃ sevyamojovivarddhanam"},{"type":"verse","number":"4","sanskrit":"जीर्णज्वरे मनोरोगे शोषमूर्च्छाभ्रमेषु च ग्रहण्यां पाण्डुरोगे च दाहे तृषि हृदामये","text":"jīrṇajvare manoroge śoṣamūrcchābhrameṣu ca grahaṇyāṃ pāṇḍuroge ca dāhe tṛṣi hṛdāmaye"},{"type":"verse","number":"5","sanskrit":"शूलोदावर्त्तगुल्मेषु वस्तिरोगे गुदाङ्कुरे रक्तपित्तेऽतिसारे च योनिरोगे श्रमे क्लमे","text":"śūlodāvarttagulmeṣu vastiroge gudāṅkure raktapitte'tisāre ca yoniroge śrame klame"},{"type":"verse","number":"6","sanskrit":"गर्भस्रावे च सततं हितं मुनिवरैः स्मृतम् बालवृद्धक्षतक्षीणाः क्षुद्व्यवायकृशाश्च ये तेभ्यः सदाऽतिशयितं हितमेतदुदाहृतम्","text":"garbhasrāve ca satataṃ hitaṃ munivaraiḥ smṛtam bālavṛddhakṣatakṣīṇāḥ kṣudvyavāyakṛśāśca ye tebhyaḥ sadā'tiśayitaṃ hitametadudāhṛtam"},{"type":"verse","number":"7","sanskrit":"गव्यं दुग्धं विशेषेण मधुरं रसपाकयोः दोषधातुमलस्रोतः किञ्चित्क्लेदकरं गुरु","text":"gavyaṃ dugdhaṃ viśeṣeṇa madhuraṃ rasapākayoḥ doṣadhātumalasrotaḥ kiñcitkledakaraṃ guru"},{"type":"verse","number":"8","sanskrit":"शीतलं स्तन्यकृत्स्निग्धं वातपित्तास्रनाशनम् जरासमस्तरोगाणां शान्तिकृत् सेविनां सदा","text":"śītalaṃ stanyakṛtsnigdhaṃ vātapittāsranāśanam jarāsamastarogāṇāṃ śāntikṛt sevināṃ sadā"},{"type":"verse","number":"9","sanskrit":"कृष्णाया गोर्भवेद् दुग्धं वातहारि गुणाधिकम्","text":"kṛṣṇāyā gorbhaved dugdhaṃ vātahāri guṇādhikam"},{"type":"verse","number":"10","sanskrit":"पीताया हरते पित्तं तथा वातहरं भवेत् श्लेष्मलं गुरु शुक्लाया रक्ता चित्रा च वातहृत्","text":"pītāyā harate pittaṃ tathā vātaharaṃ bhavet śleṣmalaṃ guru śuklāyā raktā citrā ca vātahṛt"},{"type":"verse","number":"11","sanskrit":"बालवत्सविवत्सानां गवां दुग्धं त्रिदोषकृत्","text":"bālavatsavivatsānāṃ gavāṃ dugdhaṃ tridoṣakṛt"},{"type":"verse","number":"12","sanskrit":"वष्कयिण्यास्त्रिदोषघ्नं तर्पणं बलकृत्पयः","text":"vaṣkayiṇyāstridoṣaghnaṃ tarpaṇaṃ balakṛtpayaḥ"},{"type":"verse","number":"13","sanskrit":"जाङ्गलानूपशैलेषु चरन्तीनां यथोत्तररम् पयो गुरुतरं स्नेहो यथाऽहारं प्रवर्त्तते","text":"jāṅgalānūpaśaileṣu carantīnāṃ yathottararam payo gurutaraṃ sneho yathā'hāraṃ pravarttate"},{"type":"verse","number":"14","sanskrit":"स्वल्पान्नभक्षणाज्जातं क्षीरं गुरु कफप्रदम् तत्तु बल्यं परं वृष्यं स्वस्थानां गुणदायकम् पलालतृणकार्पासबीजजं रोगिणे हितम्","text":"svalpānnabhakṣaṇājjātaṃ kṣīraṃ guru kaphapradam tattu balyaṃ paraṃ vṛṣyaṃ svasthānāṃ guṇadāyakam palālatṛṇakārpāsabījajaṃ rogiṇe hitam"},{"type":"verse","number":"15","sanskrit":"माहिषं मधुरं गव्यात्स्निग्धं शुक्रकरं गुरु निद्रा करमभिष्यन्दि क्षुधाऽधिक्यहरं हिमम्","text":"māhiṣaṃ madhuraṃ gavyātsnigdhaṃ śukrakaraṃ guru nidrā karamabhiṣyandi kṣudhā'dhikyaharaṃ himam"},{"type":"verse","number":"16","sanskrit":"छागं कषायं मधुरं शीतं ग्राहि तथा लघु रक्तपित्तातिसारघ्नं क्षयकासज्वरापहम्","text":"chāgaṃ kaṣāyaṃ madhuraṃ śītaṃ grāhi tathā laghu raktapittātisāraghnaṃ kṣayakāsajvarāpaham"},{"type":"verse","number":"17","sanskrit":"स्तोकाम्बुपानाद्व्यायामात्सर्वरोगापहं पयः","text":"stokāmbupānādvyāyāmātsarvarogāpahaṃ payaḥ"},{"type":"verse","number":"18","sanskrit":"मृगीणां जाङ्गलोत्थानामजाक्षीरगुणं पयः","text":"mṛgīṇāṃ jāṅgalotthānāmajākṣīraguṇaṃ payaḥ"},{"type":"verse","number":"19","sanskrit":"आविकं लवणं स्वादु स्निग्धोष्णं चाश्मरीप्रणुत् अहृद्यं तर्पणं केश्यं शुक्रपित्तकफप्रदम् गुरु कासानिलोद्भूते केवले चानिले वरम्","text":"āvikaṃ lavaṇaṃ svādu snigdhoṣṇaṃ cāśmarīpraṇut ahṛdyaṃ tarpaṇaṃ keśyaṃ śukrapittakaphapradam guru kāsānilodbhūte kevale cānile varam"},{"type":"verse","number":"20","sanskrit":"रूक्षोष्णं वडवाक्षीरं बल्यं शोषानिलापहम् अम्लं पटु लघु स्वादु सर्वमेकशफं तथा","text":"rūkṣoṣṇaṃ vaḍavākṣīraṃ balyaṃ śoṣānilāpaham amlaṃ paṭu laghu svādu sarvamekaśaphaṃ tathā"},{"type":"verse","number":"21","sanskrit":"औष्ट्रं दुग्धं लघु स्वादु लवणं दीपनं तथा कृमिकुष्ठकफानाहशोथोदरहरं सरम्","text":"auṣṭraṃ dugdhaṃ laghu svādu lavaṇaṃ dīpanaṃ tathā kṛmikuṣṭhakaphānāhaśothodaraharaṃ saram"},{"type":"verse","number":"22","sanskrit":"बृंहणं हस्तिनीदुग्धं मधुरं तुवरं गुरु वृष्यं बल्यं हिमं स्निग्धं चक्षुष्यं स्थिरताकरम्","text":"bṛṃhaṇaṃ hastinīdugdhaṃ madhuraṃ tuvaraṃ guru vṛṣyaṃ balyaṃ himaṃ snigdhaṃ cakṣuṣyaṃ sthiratākaram"},{"type":"verse","number":"23","sanskrit":"भार्या लघु पयः शीतं दीपनं वातपित्तजित् चक्षुः शूलाभिवातघ्नं नस्याश्च्योतनयोर्वरम्","text":"bhāryā laghu payaḥ śītaṃ dīpanaṃ vātapittajit cakṣuḥ śūlābhivātaghnaṃ nasyāścyotanayorvaram"},{"type":"verse","number":"24","sanskrit":"धारोष्णं गोपयो बल्यं लघु शीतं सुधासमम् दीपनञ्च त्रिदोषघ्नं तद्धाराशिशिरं त्यजेत्","text":"dhāroṣṇaṃ gopayo balyaṃ laghu śītaṃ sudhāsamam dīpanañca tridoṣaghnaṃ taddhārāśiśiraṃ tyajet"},{"type":"verse","number":"25","sanskrit":"धारोष्णं शस्यते गव्यं धाराशीतन्तु माहिषम् शृतोष्णमाविकं पथ्यं शृतशीतमजापयः","text":"dhāroṣṇaṃ śasyate gavyaṃ dhārāśītantu māhiṣam śṛtoṣṇamāvikaṃ pathyaṃ śṛtaśītamajāpayaḥ"},{"type":"verse","number":"26","sanskrit":"आमं क्षीरमभिष्यन्दि गुरु श्लेष्मामवर्द्धनम् ज्ञेयं सर्वमपथ्यं तु गव्यमाहिषवर्जितम्","text":"āmaṃ kṣīramabhiṣyandi guru śleṣmāmavarddhanam jñeyaṃ sarvamapathyaṃ tu gavyamāhiṣavarjitam"},{"type":"verse","number":"27","sanskrit":"नारीक्षीरं त्वाममेव हितं न तु शृतं हितम् शृतोष्णं कफवातघ्नं शृतशीतन्तु पित्तनुत्","text":"nārīkṣīraṃ tvāmameva hitaṃ na tu śṛtaṃ hitam śṛtoṣṇaṃ kaphavātaghnaṃ śṛtaśītantu pittanut"},{"type":"verse","number":"28","sanskrit":"अर्द्धोदकं क्षीरशिष्टमामाल्लघुतरं पयः जलेन रहितं दुग्धमतिपक्वं यथा यथा तथा तथा गुरु स्निग्धं वृष्यं बलविवर्धनम्","text":"arddhodakaṃ kṣīraśiṣṭamāmāllaghutaraṃ payaḥ jalena rahitaṃ dugdhamatipakvaṃ yathā yathā tathā tathā guru snigdhaṃ vṛṣyaṃ balavivardhanam"},{"type":"verse","number":"29","sanskrit":"क्षीरं तत्कालसूताया घनं पीयूषमुच्यते नष्टदुग्धस्य पक्वस्य पिण्डः प्रोक्तः किलाटकः","text":"kṣīraṃ tatkālasūtāyā ghanaṃ pīyūṣamucyate naṣṭadugdhasya pakvasya piṇḍaḥ proktaḥ kilāṭakaḥ"},{"type":"verse","number":"30","sanskrit":"अपक्वमेव यन्नष्टं क्षीरशाकं हि तत्पयः","text":"apakvameva yannaṣṭaṃ kṣīraśākaṃ hi tatpayaḥ"},{"type":"verse","number":"31","sanskrit":"दघ्ना तक्रेण वा नष्टं दुग्धं बद्धं सुवाससा द्र वभावेन सहितं तक्रपिण्डः स उच्यते","text":"daghnā takreṇa vā naṣṭaṃ dugdhaṃ baddhaṃ suvāsasā dra vabhāvena sahitaṃ takrapiṇḍaḥ sa ucyate"},{"type":"verse","number":"32","sanskrit":"नष्टदुग्धभवं नीरं मोरटं जेज्जटोऽब्रवीत् पीयूषञ्च किलाटञ्च क्षीरशाकं तथैव च","text":"naṣṭadugdhabhavaṃ nīraṃ moraṭaṃ jejjaṭo'bravīt pīyūṣañca kilāṭañca kṣīraśākaṃ tathaiva ca"},{"type":"verse","number":"33","sanskrit":"तक्रपिण्ड इमे वृष्या बृंहणा बलवर्द्धनाः गुरवः श्लेष्मला हृद्या वातपित्तविनाशनाः","text":"takrapiṇḍa ime vṛṣyā bṛṃhaṇā balavarddhanāḥ guravaḥ śleṣmalā hṛdyā vātapittavināśanāḥ"},{"type":"verse","number":"34","sanskrit":"दीप्ताग्नीनां विनिद्रा णां विद्र धौ चाभिपूजिताः मुखशोष तृषा दाह रक्त पित्त ज्वरप्रणुत् लघुर्बलकरो रुच्यो मोरटः स्यात्सितायुतः","text":"dīptāgnīnāṃ vinidrā ṇāṃ vidra dhau cābhipūjitāḥ mukhaśoṣa tṛṣā dāha rakta pitta jvarapraṇut laghurbalakaro rucyo moraṭaḥ syātsitāyutaḥ"},{"type":"verse","number":"35","sanskrit":"सन्तानिका गुरुः शीता वृष्या पित्तास्रवातनुत् तर्पणी वृंहणी स्निग्धा बलासबलशुक्रला","text":"santānikā guruḥ śītā vṛṣyā pittāsravātanut tarpaṇī vṛṃhaṇī snigdhā balāsabalaśukralā"},{"type":"verse","number":"36","sanskrit":"खण्डेन सहितं दुग्धं कफकृत्पवनापहम् सितासितोपलायुक्तं शुक्रलं त्रिमलापहम् सगुडं मूत्रकृच्छ्रघ्नं पित्तश्लेष्मकरं परम्","text":"khaṇḍena sahitaṃ dugdhaṃ kaphakṛtpavanāpaham sitāsitopalāyuktaṃ śukralaṃ trimalāpaham saguḍaṃ mūtrakṛcchraghnaṃ pittaśleṣmakaraṃ param"},{"type":"verse","number":"37","sanskrit":"रात्रौ चन्द्र गुणाधिक्याद्व्यायामाकरणात्तथा प्राभातिकं पयः प्रायः प्रादोषाद् गुरु शीतलम्","text":"rātrau candra guṇādhikyādvyāyāmākaraṇāttathā prābhātikaṃ payaḥ prāyaḥ prādoṣād guru śītalam"},{"type":"verse","number":"38","sanskrit":"प्राभातिकात्तु प्रादोषं लघु वातकफापहम्","text":"prābhātikāttu prādoṣaṃ laghu vātakaphāpaham"},{"type":"verse","number":"39","sanskrit":"वृष्यं बृंहणमग्निदीपनकरं पूर्वाह्नकाले पयो मध्याह्ने तु बलावहं कफहरं पित्तापहं दीपनम् बाले बृद्धिकरं क्षयेऽक्षयकरं वृद्धेषु रेतोवहं रात्रौ पथ्यमनेकदोषशमनं चक्षुर्हितं संस्मृतम्","text":"vṛṣyaṃ bṛṃhaṇamagnidīpanakaraṃ pūrvāhnakāle payo madhyāhne tu balāvahaṃ kaphaharaṃ pittāpahaṃ dīpanam bāle bṛddhikaraṃ kṣaye'kṣayakaraṃ vṛddheṣu retovahaṃ rātrau pathyamanekadoṣaśamanaṃ cakṣurhitaṃ saṃsmṛtam"},{"type":"verse","number":"40","sanskrit":"वदन्ति पेयं निशि केवलं पयो भोज्यं न तेनेह सहौदनादिकम् भवत्यजीर्णं न शयीत शर्वरीं क्षीरस्य पीतस्य न शेषमुत्सृजेत्","text":"vadanti peyaṃ niśi kevalaṃ payo bhojyaṃ na teneha sahaudanādikam bhavatyajīrṇaṃ na śayīta śarvarīṃ kṣīrasya pītasya na śeṣamutsṛjet"},{"type":"verse","number":"41","sanskrit":"विदाहीन्यन्नपानानि दिवा भुङ्क्ते हि यन्नरः तद्विदाहप्रशान्त्यर्थं रात्रौ क्षीरं सदा पिबेत्","text":"vidāhīnyannapānāni divā bhuṅkte hi yannaraḥ tadvidāhapraśāntyarthaṃ rātrau kṣīraṃ sadā pibet"},{"type":"verse","number":"42","sanskrit":"दीप्तानले कृशे पुंसि बाले वृद्धे पयःप्रिये मतं हिततमं दुग्धं सद्यःशुक्रकरं यतः","text":"dīptānale kṛśe puṃsi bāle vṛddhe payaḥpriye mataṃ hitatamaṃ dugdhaṃ sadyaḥśukrakaraṃ yataḥ"},{"type":"verse","number":"43","sanskrit":"क्षीरं गव्यमथाजं वा कोष्णं दण्डाहतं पिबेत् लघु वृष्यं ज्वरहरं वातपित्तकफापहम्","text":"kṣīraṃ gavyamathājaṃ vā koṣṇaṃ daṇḍāhataṃ pibet laghu vṛṣyaṃ jvaraharaṃ vātapittakaphāpaham"},{"type":"verse","number":"44","sanskrit":"गोदुग्धप्रभवं किं वा छागीदुग्धसमुद्भवम् भवेत् फेनं त्रिदोषघ्नं रोचनं बलवर्द्धनम्","text":"godugdhaprabhavaṃ kiṃ vā chāgīdugdhasamudbhavam bhavet phenaṃ tridoṣaghnaṃ rocanaṃ balavarddhanam"},{"type":"verse","number":"45","sanskrit":"वह्निबृद्धिकरं वृष्यं सद्यस्तृप्तिकरं लघु अतीसारेऽग्निमान्द्ये च ज्वरे जीर्णे प्रशस्यते","text":"vahnibṛddhikaraṃ vṛṣyaṃ sadyastṛptikaraṃ laghu atīsāre'gnimāndye ca jvare jīrṇe praśasyate"},{"type":"verse","number":"46","sanskrit":"विवर्णं विरसं चाम्लं दुर्गन्धं ग्रथितं पयः वर्जयेदम्ललवणयुक्तं कुष्ठादिकृद् यतः","text":"vivarṇaṃ virasaṃ cāmlaṃ durgandhaṃ grathitaṃ payaḥ varjayedamlalavaṇayuktaṃ kuṣṭhādikṛd yataḥ"},{"type":"verse","number":"14","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे चतुर्दशो दुग्धवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe caturdaśo dugdhavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":14,"lang":"sa","content":[{"type":"heading","heading":"dadhi-варга — творог и йогурт"},{"type":"verse","number":"1","sanskrit":"दध्युष्णं दीपनं स्निग्धं कषायानुरसं गुरु पाकेऽम्ल ग्राहि पित्तास्रशोथमेदः कफप्रदम्","text":"dadhyuṣṇaṃ dīpanaṃ snigdhaṃ kaṣāyānurasaṃ guru pāke'mla grāhi pittāsraśothamedaḥ kaphapradam"},{"type":"verse","number":"2","sanskrit":"मूत्रकृच्छ्रे प्रतिश्याये शीतगे विषमज्वरे अतीसारेऽरुचौ कार्श्ये शस्यते बलशुक्रकृत्","text":"mūtrakṛcchre pratiśyāye śītage viṣamajvare atīsāre'rucau kārśye śasyate balaśukrakṛt"},{"type":"verse","number":"3","sanskrit":"आदौ मन्दं ततः स्वादु स्वाद्वम्लञ्च ततःपरम् अम्लं चतुर्थमत्यम्लं पञ्चमं दधि पञ्चधा","text":"ādau mandaṃ tataḥ svādu svādvamlañca tataḥparam amlaṃ caturthamatyamlaṃ pañcamaṃ dadhi pañcadhā"},{"type":"verse","number":"4","sanskrit":"मन्दं दुग्धवदव्यक्तरसं किञ्चिद्घनं भवेत् मन्दं स्यात्सृष्टविण्मूत्रं दोषत्रयविदाहकृत्","text":"mandaṃ dugdhavadavyaktarasaṃ kiñcidghanaṃ bhavet mandaṃ syātsṛṣṭaviṇmūtraṃ doṣatrayavidāhakṛt"},{"type":"verse","number":"5","sanskrit":"यत्सम्यग्घनतां यातं व्यक्तस्वादुरसं भवेत् अव्यक्ताम्लरसं तत्तु स्वादु विज्ञैरुदाहृतम्","text":"yatsamyagghanatāṃ yātaṃ vyaktasvādurasaṃ bhavet avyaktāmlarasaṃ tattu svādu vijñairudāhṛtam"},{"type":"verse","number":"6","sanskrit":"स्वादु स्यादत्यभिष्यन्दि वृष्यं मेदःकफावहम् वातघ्नं मधुरं पाके रक्तपित्तप्रसादनम्","text":"svādu syādatyabhiṣyandi vṛṣyaṃ medaḥkaphāvaham vātaghnaṃ madhuraṃ pāke raktapittaprasādanam"},{"type":"verse","number":"7","sanskrit":"स्वाद्वम्लं सान्द्र मधुरं कषायानुरसं भवेत् स्वाद्वम्लस्य गुणा ज्ञेया सामान्यदधिवज्जनैः","text":"svādvamlaṃ sāndra madhuraṃ kaṣāyānurasaṃ bhavet svādvamlasya guṇā jñeyā sāmānyadadhivajjanaiḥ"},{"type":"verse","number":"8","sanskrit":"यत्तिरोहितमाधुर्यं व्यक्ताम्लत्वं तदम्लकम् अम्लं तु दीपनं पित्तरक्तश्लेष्मविवर्द्धनम्","text":"yattirohitamādhuryaṃ vyaktāmlatvaṃ tadamlakam amlaṃ tu dīpanaṃ pittaraktaśleṣmavivarddhanam"},{"type":"verse","number":"9","sanskrit":"तदत्यम्लं दन्तरोमहर्षकण्ठादिदाहकृत् अत्यम्लं दीपनं रक्तवातपित्तकरं परम्","text":"tadatyamlaṃ dantaromaharṣakaṇṭhādidāhakṛt atyamlaṃ dīpanaṃ raktavātapittakaraṃ param"},{"type":"verse","number":"10","sanskrit":"गव्यं दधि विशेषेण स्वाद्वम्लं च रुचिप्रदम् पवित्रं दीपनं हृद्यं पुष्टिकृत्पवनापहम् उक्तं दध्नामशेषाणां मध्ये गव्यं गुणाधिकम्","text":"gavyaṃ dadhi viśeṣeṇa svādvamlaṃ ca rucipradam pavitraṃ dīpanaṃ hṛdyaṃ puṣṭikṛtpavanāpaham uktaṃ dadhnāmaśeṣāṇāṃ madhye gavyaṃ guṇādhikam"},{"type":"verse","number":"11","sanskrit":"माहिषं दधि सुस्निग्धं श्लेष्मलं वातपित्तनुत् स्वादुपाकमभिष्यन्दि वृष्यं गुर्वस्रदूषकम्","text":"māhiṣaṃ dadhi susnigdhaṃ śleṣmalaṃ vātapittanut svādupākamabhiṣyandi vṛṣyaṃ gurvasradūṣakam"},{"type":"verse","number":"12","sanskrit":"आजं दध्युत्तमं ग्राहि लघु दोषत्रयापहम् शस्यते श्वासकासार्शः क्षयकार्श्येषु दीपनम्","text":"ājaṃ dadhyuttamaṃ grāhi laghu doṣatrayāpaham śasyate śvāsakāsārśaḥ kṣayakārśyeṣu dīpanam"},{"type":"verse","number":"13","sanskrit":"पक्वदुग्धभवं रुच्यं दधि स्निग्धं गुणोत्तमम् पित्तानिलापहं सर्वधात्वग्निबलवर्द्धनम्","text":"pakvadugdhabhavaṃ rucyaṃ dadhi snigdhaṃ guṇottamam pittānilāpahaṃ sarvadhātvagnibalavarddhanam"},{"type":"verse","number":"14","sanskrit":"असारं दधि सङ्ग्राहि शीतलं वातलं लघु विष्टम्भि दीपनं रुच्यं ग्रहणीरोगनाशनम्","text":"asāraṃ dadhi saṅgrāhi śītalaṃ vātalaṃ laghu viṣṭambhi dīpanaṃ rucyaṃ grahaṇīroganāśanam"},{"type":"verse","number":"15","sanskrit":"गालितं दधि सुस्निग्धं वातघ्नं कफकृद् गुरु बलपुष्टिकरं रुच्यं मधुरं नातिपित्तकृत्","text":"gālitaṃ dadhi susnigdhaṃ vātaghnaṃ kaphakṛd guru balapuṣṭikaraṃ rucyaṃ madhuraṃ nātipittakṛt"},{"type":"verse","number":"16","sanskrit":"सशर्करं दधि श्रेष्ठं तृष्णापित्तास्रदाहजित् सगुडं वातनुद् वृष्यं बृंहणं तर्पणं गुरु","text":"saśarkaraṃ dadhi śreṣṭhaṃ tṛṣṇāpittāsradāhajit saguḍaṃ vātanud vṛṣyaṃ bṛṃhaṇaṃ tarpaṇaṃ guru"},{"type":"verse","number":"17","sanskrit":"न नक्तं दधि भुञ्जीत न चाप्यघृतशर्करम् नामुद्गसूपं नाक्षौद्रं नोष्णं नामलकैर्विना","text":"na naktaṃ dadhi bhuñjīta na cāpyaghṛtaśarkaram nāmudgasūpaṃ nākṣaudraṃ noṣṇaṃ nāmalakairvinā"},{"type":"verse","number":"18","sanskrit":"हेमन्ते शिशिरे चापि वर्षासु दधि शस्यते शरद्ग्रीष्मवसन्तेषु प्रायशस्तद्विगर्हितम्","text":"hemante śiśire cāpi varṣāsu dadhi śasyate śaradgrīṣmavasanteṣu prāyaśastadvigarhitam"},{"type":"verse","number":"19","sanskrit":"ज्वरासृक्पित्त वीसर्पकुष्ठपाण्ड्वामयभ्रमान् प्राप्नुयात्कामलां चोग्रां विधिं हत्वा दधिप्रियः","text":"jvarāsṛkpitta vīsarpakuṣṭhapāṇḍvāmayabhramān prāpnuyātkāmalāṃ cogrāṃ vidhiṃ hatvā dadhipriyaḥ"},{"type":"verse","number":"20","sanskrit":"दध्नस्तूपरि यो भागो घनः स्नेहसमन्वितः स लोके सर इत्युक्तो दध्नो मण्डस्तु मस्त्विति","text":"dadhnastūpari yo bhāgo ghanaḥ snehasamanvitaḥ sa loke sara ityukto dadhno maṇḍastu mastviti"},{"type":"verse","number":"21","sanskrit":"सरः स्वादुर्गुरुर्वृष्यो वातवह्निप्रणाशनः सोऽम्लो वस्तिप्रशमनः पित्तश्लेष्मविवर्द्धनः","text":"saraḥ svādurgururvṛṣyo vātavahnipraṇāśanaḥ so'mlo vastipraśamanaḥ pittaśleṣmavivarddhanaḥ"},{"type":"verse","number":"22","sanskrit":"मस्तु क्लमहरं बल्यं लघु भक्ताभिलाषकृत्","text":"mastu klamaharaṃ balyaṃ laghu bhaktābhilāṣakṛt"},{"type":"verse","number":"23","sanskrit":"स्रोतोविशोधनं ह्लादि कफतृष्णानिलापहम् अवृष्यं प्रीणनं शीघ्रं भिनत्ति मलसञ्चयम्","text":"srotoviśodhanaṃ hlādi kaphatṛṣṇānilāpaham avṛṣyaṃ prīṇanaṃ śīghraṃ bhinatti malasañcayam"},{"type":"verse","number":"15","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे पञ्चदशो दधिवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe pañcadaśo dadhivargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":15,"lang":"sa","content":[{"type":"heading","heading":"takra-варга — пахта"},{"type":"verse","number":"1","sanskrit":"घोलं तु मथितं तक्रमुदश्विच्छच्छिकाऽपि च ससरं निर्जलं घोलं मथितं त्वसरोदकम्","text":"gholaṃ tu mathitaṃ takramudaśvicchacchikā'pi ca sasaraṃ nirjalaṃ gholaṃ mathitaṃ tvasarodakam"},{"type":"verse","number":"2","sanskrit":"तक्रं पादजलं प्रोक्तमुदश्वित्त्वर्द्धवारिकम् छच्छिका सारहीना स्यात्स्वच्छा प्रचुरवारिका घोलं तु शर्करायुक्तं गुणैर्ज्ञेयं रसालवत्","text":"takraṃ pādajalaṃ proktamudaśvittvarddhavārikam chacchikā sārahīnā syātsvacchā pracuravārikā gholaṃ tu śarkarāyuktaṃ guṇairjñeyaṃ rasālavat"},{"type":"verse","number":"3","sanskrit":"वातपित्तहरं ह्लादि मथितं कफपित्तनुत्","text":"vātapittaharaṃ hlādi mathitaṃ kaphapittanut"},{"type":"verse","number":"4","sanskrit":"तक्रं ग्राहि कषायाम्लं स्वादुपाकरसं लघु वीर्योष्णं दीपनं वृष्यं प्रीणनं वातनाशनम्","text":"takraṃ grāhi kaṣāyāmlaṃ svādupākarasaṃ laghu vīryoṣṇaṃ dīpanaṃ vṛṣyaṃ prīṇanaṃ vātanāśanam"},{"type":"verse","number":"5","sanskrit":"ग्रहण्यादिमतां पथ्यं भवेत्संग्राहि लाघवात् किञ्च स्वादुविपाकित्वान्न च पित्तप्रकोपणम्","text":"grahaṇyādimatāṃ pathyaṃ bhavetsaṃgrāhi lāghavāt kiñca svāduvipākitvānna ca pittaprakopaṇam"},{"type":"verse","number":"6","sanskrit":"अम्लोष्णं दीपनं वृष्यं प्रीणनं वातनाशनम् कषायोष्णविकाशित्वाद्रौ क्ष्याच्चापि कफापहम्","text":"amloṣṇaṃ dīpanaṃ vṛṣyaṃ prīṇanaṃ vātanāśanam kaṣāyoṣṇavikāśitvādrau kṣyāccāpi kaphāpaham"},{"type":"verse","number":"7","sanskrit":"न तक्रसेवी व्यथते कदाचिन्न तक्रदग्धाः प्रभवन्ति रोगाः यथा सुराणाममृतं सुखाय तथा नराणां भुवि तक्रमाहुः","text":"na takrasevī vyathate kadācinna takradagdhāḥ prabhavanti rogāḥ yathā surāṇāmamṛtaṃ sukhāya tathā narāṇāṃ bhuvi takramāhuḥ"},{"type":"verse","number":"8","sanskrit":"उदश्वित् कफकृद् बल्यमामघ्नं परमं मतम् छच्छिका शीतला लघ्वी पित्तश्रमतृषाहरी वातनुत् कफकृत् सा तु दीपनी लवणान्विता","text":"udaśvit kaphakṛd balyamāmaghnaṃ paramaṃ matam chacchikā śītalā laghvī pittaśramatṛṣāharī vātanut kaphakṛt sā tu dīpanī lavaṇānvitā"},{"type":"verse","number":"9","sanskrit":"समुद्धृतघृतं तक्रं पथ्यं लघु विशेषतः","text":"samuddhṛtaghṛtaṃ takraṃ pathyaṃ laghu viśeṣataḥ"},{"type":"verse","number":"10","sanskrit":"स्तोकोद्धृतघृतं तस्माद् गुरु वृष्यं कफापहम् अनुद्धृतघृतं सान्द्रं गुरुपुष्टिकफप्रदम्","text":"stokoddhṛtaghṛtaṃ tasmād guru vṛṣyaṃ kaphāpaham anuddhṛtaghṛtaṃ sāndraṃ gurupuṣṭikaphapradam"},{"type":"verse","number":"11","sanskrit":"वातेऽम्ल शस्यते तक्रं शुण्ठीसैन्धवसंयुतम् पित्ते स्वादु सितायुक्तं व्योषक्षारयुतं कफे","text":"vāte'mla śasyate takraṃ śuṇṭhīsaindhavasaṃyutam pitte svādu sitāyuktaṃ vyoṣakṣārayutaṃ kaphe"},{"type":"verse","number":"12","sanskrit":"हिङ्गुजीरयुतं घोलं सैन्धवेन च संयुतम् भवेदतीव वातघ्नमर्शोऽतीसारहृत्परम्","text":"hiṅgujīrayutaṃ gholaṃ saindhavena ca saṃyutam bhavedatīva vātaghnamarśo'tīsārahṛtparam"},{"type":"verse","number":"13","sanskrit":"रुचिदं पुष्टिदं बल्यं वस्तिशूलविनाशनम् मूत्रकृच्छ्रे तु सगुडं पाण्डुरोगे सचित्रकम्","text":"rucidaṃ puṣṭidaṃ balyaṃ vastiśūlavināśanam mūtrakṛcchre tu saguḍaṃ pāṇḍuroge sacitrakam"},{"type":"verse","number":"14","sanskrit":"तक्रमामं कफं कोष्ठे हन्ति कण्ठे करोति च पीनसश्वासकासादौ पक्वमेव प्रयुज्यते","text":"takramāmaṃ kaphaṃ koṣṭhe hanti kaṇṭhe karoti ca pīnasaśvāsakāsādau pakvameva prayujyate"},{"type":"verse","number":"15","sanskrit":"शीतकालेऽग्निमान्द्ये च तथा वातामयेषु च अरुचौ स्रोतसां रोधे तक्रं स्यादमृतोपमम् तत्तु हन्ति गरच्छर्दिप्रसेकविषमज्वरान् पाण्डुमेदोग्रहण्यर्शोमूत्रग्रहभगन्दरान्","text":"śītakāle'gnimāndye ca tathā vātāmayeṣu ca arucau srotasāṃ rodhe takraṃ syādamṛtopamam tattu hanti garacchardiprasekaviṣamajvarān pāṇḍumedograhaṇyarśomūtragrahabhagandarān"},{"type":"verse","number":"16","sanskrit":"मेहं गुल्ममतीसारं शूलप्लीहोदरारुचीः श्वित्रकोष्ठगतव्याधीन् कुष्ठशोथतृषाकृमीन्","text":"mehaṃ gulmamatīsāraṃ śūlaplīhodarārucīḥ śvitrakoṣṭhagatavyādhīn kuṣṭhaśothatṛṣākṛmīn"},{"type":"verse","number":"17","sanskrit":"नैव तक्रं क्षये दद्यान्नोष्णकाले न दुर्बले न मूर्च्छाभ्रमदाहेषु न रोगे रक्तपित्तजे","text":"naiva takraṃ kṣaye dadyānnoṣṇakāle na durbale na mūrcchābhramadāheṣu na roge raktapittaje"},{"type":"verse","number":"18","sanskrit":"यान्युक्तानि दधीन्यष्टौ तद्गुणं तक्रमादिशेत्","text":"yānyuktāni dadhīnyaṣṭau tadguṇaṃ takramādiśet"},{"type":"verse","number":"16","sanskrit":"इति श्रीमिश्रलटक नतनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे षोडशस्तक्रवर्गः समाप्तः","text":"iti śrīmiśralaṭaka natanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe ṣoḍaśastakravargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":16,"lang":"sa","content":[{"type":"heading","heading":"navanīta-варга — сливочное масло"},{"type":"verse","number":"1","sanskrit":"म्रक्षणं सरजं हैयङ्गवीनं नवनीतकम् नवनीतं हितं गव्यं वृष्यं वर्णबलाग्निकृत्","text":"mrakṣaṇaṃ sarajaṃ haiyaṅgavīnaṃ navanītakam navanītaṃ hitaṃ gavyaṃ vṛṣyaṃ varṇabalāgnikṛt"},{"type":"verse","number":"2","sanskrit":"संग्राहि वातपित्तासृक्क्षयार्शोऽदितकासहृत् तद्धितं बालके वृद्धे विशेषादमृतं शिशोः","text":"saṃgrāhi vātapittāsṛkkṣayārśo'ditakāsahṛt taddhitaṃ bālake vṛddhe viśeṣādamṛtaṃ śiśoḥ"},{"type":"verse","number":"3","sanskrit":"नवनीतं महिष्यास्तु वातश्लेष्मकरं गुरु दाहपित्तश्रमहरं मेदः शुक्रविवर्द्धनम्","text":"navanītaṃ mahiṣyāstu vātaśleṣmakaraṃ guru dāhapittaśramaharaṃ medaḥ śukravivarddhanam"},{"type":"verse","number":"4","sanskrit":"दुग्धोत्थं नवनीतं तु चक्षुष्यं रक्तपित्तनुत् वृष्यं बल्यमतिस्निग्धं मधुरं ग्राहि शीतलम्","text":"dugdhotthaṃ navanītaṃ tu cakṣuṣyaṃ raktapittanut vṛṣyaṃ balyamatisnigdhaṃ madhuraṃ grāhi śītalam"},{"type":"verse","number":"5","sanskrit":"नवनीतं तु सद्यस्कं स्वादु ग्राहि हिमं लघु मेध्यं किञ्चित्कषायाम्लमीषत्तक्रांश सङ्क्रमात्","text":"navanītaṃ tu sadyaskaṃ svādu grāhi himaṃ laghu medhyaṃ kiñcitkaṣāyāmlamīṣattakrāṃśa saṅkramāt"},{"type":"verse","number":"6","sanskrit":"श्लेष्मलं गुरु मेदस्यं नवनीतं चिरन्तनम्","text":"śleṣmalaṃ guru medasyaṃ navanītaṃ cirantanam"},{"type":"verse","number":"17","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे सप्तदशो नवनीतवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe saptadaśo navanītavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":17,"lang":"sa","content":[{"type":"heading","heading":"ghṛta-варга — топлёное масло (гхи)"},{"type":"verse","number":"1","sanskrit":"घृतमाज्यं हविः सर्पिः कथ्यन्ते तद्गुणा अथ घृतं रसायनं स्वादु चक्षुष्यं वह्निदीपनम्","text":"ghṛtamājyaṃ haviḥ sarpiḥ kathyante tadguṇā atha ghṛtaṃ rasāyanaṃ svādu cakṣuṣyaṃ vahnidīpanam"},{"type":"verse","number":"2","sanskrit":"अल्पाभिष्यन्दि कान्त्योजस्तेजोलावण्यवृद्धिकृत्","text":"alpābhiṣyandi kāntyojastejolāvaṇyavṛddhikṛt"},{"type":"verse","number":"3","sanskrit":"स्वरस्मृतिकरं मेध्यमायुष्यं बलकृद्गुरु उदावर्त्तज्वरोन्मादशूलानाहव्रणान् हरेत् स्निग्धं कफकरं रक्षःक्षयवीसर्परक्तनुत्","text":"svarasmṛtikaraṃ medhyamāyuṣyaṃ balakṛdguru udāvarttajvaronmādaśūlānāhavraṇān haret snigdhaṃ kaphakaraṃ rakṣaḥkṣayavīsarparaktanut"},{"type":"verse","number":"4","sanskrit":"गव्यं घृतं विशेषेण चक्षुष्यं वृष्यमग्निकृत् स्वादु पाककरं शीतं वातपित्तकफापहम्","text":"gavyaṃ ghṛtaṃ viśeṣeṇa cakṣuṣyaṃ vṛṣyamagnikṛt svādu pākakaraṃ śītaṃ vātapittakaphāpaham"},{"type":"verse","number":"5","sanskrit":"मेधालावण्यकान्त्योजस्तेजोवृद्धिकरं परम् अलक्ष्मीपापरक्षोघ्नं वयसः स्थापकं गुरु","text":"medhālāvaṇyakāntyojastejovṛddhikaraṃ param alakṣmīpāparakṣoghnaṃ vayasaḥ sthāpakaṃ guru"},{"type":"verse","number":"6","sanskrit":"बल्यं पवित्रमायुष्यं सुमङ्गल्यं रसायनम् सुगन्धं रोचनं चारु सर्वाज्येषु गुणाधिकम्","text":"balyaṃ pavitramāyuṣyaṃ sumaṅgalyaṃ rasāyanam sugandhaṃ rocanaṃ cāru sarvājyeṣu guṇādhikam"},{"type":"verse","number":"7","sanskrit":"माहिषन्तु घृतं स्वादु पित्तरक्तानिलापहम् शीतलं श्लेष्मलं वृष्यं गुरु स्वादु विपच्यते","text":"māhiṣantu ghṛtaṃ svādu pittaraktānilāpaham śītalaṃ śleṣmalaṃ vṛṣyaṃ guru svādu vipacyate"},{"type":"verse","number":"8","sanskrit":"आजमाज्यं करोत्यग्निं चक्षुष्यं बलवर्द्धनम् कासे श्वासे क्षये चापि हितं पाके भवेत् कटु","text":"ājamājyaṃ karotyagniṃ cakṣuṣyaṃ balavarddhanam kāse śvāse kṣaye cāpi hitaṃ pāke bhavet kaṭu"},{"type":"verse","number":"9","sanskrit":"औष्ट्रं कटु घृतं पाके शोषकृमिविषापहम् दीपनं कफवातघ्नं कुष्ठगुल्मोदरापहम्","text":"auṣṭraṃ kaṭu ghṛtaṃ pāke śoṣakṛmiviṣāpaham dīpanaṃ kaphavātaghnaṃ kuṣṭhagulmodarāpaham"},{"type":"verse","number":"10","sanskrit":"पाके लघ्वाविकं सर्पिः सर्वरोगविनाशनम्","text":"pāke laghvāvikaṃ sarpiḥ sarvarogavināśanam"},{"type":"verse","number":"11","sanskrit":"वृद्धिं करोति चास्थ्नां वा अश्मरीशर्कराऽपहम् चक्षुष्यमग्निसंधुक्ष्यं वातदोषनिवारणम्","text":"vṛddhiṃ karoti cāsthnāṃ vā aśmarīśarkarā'paham cakṣuṣyamagnisaṃdhukṣyaṃ vātadoṣanivāraṇam"},{"type":"verse","number":"12","sanskrit":"कफेऽनिले योनिदोषे पित्ते रक्ते च तद्धितम् चज्ञुष्यमाज्यं स्त्रीणां वा सर्पिः स्यादमृतोपमम्","text":"kaphe'nile yonidoṣe pitte rakte ca taddhitam cajñuṣyamājyaṃ strīṇāṃ vā sarpiḥ syādamṛtopamam"},{"type":"verse","number":"13","sanskrit":"वृद्धिं करोति देहाग्नेर्लघु पाके विषापहम् तर्पणं नेत्ररोगघ्नं दाहनुद् वडवाघृतम्","text":"vṛddhiṃ karoti dehāgnerlaghu pāke viṣāpaham tarpaṇaṃ netrarogaghnaṃ dāhanud vaḍavāghṛtam"},{"type":"verse","number":"14","sanskrit":"घृतं दुग्धभवं ग्राहि शीतलं नेत्ररोगहृत् निहन्ति पित्तदाहास्रमदमूर्च्छाभ्रमानिलान्","text":"ghṛtaṃ dugdhabhavaṃ grāhi śītalaṃ netrarogahṛt nihanti pittadāhāsramadamūrcchābhramānilān"},{"type":"verse","number":"15","sanskrit":"हविर्ह्यस्तनदुग्धोत्थं तत्स्याद्धैयङ्गवीनकम् हैयङ्गवीनं चक्षुष्यं दीपनं रुचिकृत्परम् बलकृद् बृंहणं वृष्यं विशेषाज्ज्वरनाशनम्","text":"havirhyastanadugdhotthaṃ tatsyāddhaiyaṅgavīnakam haiyaṅgavīnaṃ cakṣuṣyaṃ dīpanaṃ rucikṛtparam balakṛd bṛṃhaṇaṃ vṛṣyaṃ viśeṣājjvaranāśanam"},{"type":"verse","number":"16","sanskrit":"बर्षादूर्ध्वं भवेदाज्यं पुराणं तत् त्रिदोषनुत् मूर्च्छाकुष्ठविषोन्मादापस्मारतिमिरापहम्","text":"barṣādūrdhvaṃ bhavedājyaṃ purāṇaṃ tat tridoṣanut mūrcchākuṣṭhaviṣonmādāpasmāratimirāpaham"},{"type":"verse","number":"17","sanskrit":"यथा यथा ऽखिलं सर्पिः पुराणमधिकं भवेत् तथा तथा गुणैः स्वैः स्वैरधिकं तदुदाहृतम्","text":"yathā yathā 'khilaṃ sarpiḥ purāṇamadhikaṃ bhavet tathā tathā guṇaiḥ svaiḥ svairadhikaṃ tadudāhṛtam"},{"type":"verse","number":"18","sanskrit":"योजयेन्नवमेवाज्यं भोजने तर्पणे श्रमे बलक्षये पाण्डुरोगे कामलानेत्ररोगयोः","text":"yojayennavamevājyaṃ bhojane tarpaṇe śrame balakṣaye pāṇḍuroge kāmalānetrarogayoḥ"},{"type":"verse","number":"19","sanskrit":"राजयक्ष्मणि बाले च वृद्धे श्लेष्मकृते गदे","text":"rājayakṣmaṇi bāle ca vṛddhe śleṣmakṛte gade"},{"type":"verse","number":"20","sanskrit":"रोगे सोमे विषूच्याञ्च विबन्धे च मदात्यये ज्वरे च दहने मन्दे न सर्पिर्बहु मन्यते","text":"roge some viṣūcyāñca vibandhe ca madātyaye jvare ca dahane mande na sarpirbahu manyate"},{"type":"verse","number":"18","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणेऽष्टादशो घृतवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe'ṣṭādaśo ghṛtavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":18,"lang":"sa","content":[{"type":"heading","heading":"mūtra-варга — мочи (лечебные)"},{"type":"verse","number":"1","sanskrit":"गोमूत्रं कटु तीक्ष्णोष्णं क्षारं तिक्तकषायकम् लघ्वग्निदीपनं मेध्यं पित्तकृत्कफवातहृत्","text":"gomūtraṃ kaṭu tīkṣṇoṣṇaṃ kṣāraṃ tiktakaṣāyakam laghvagnidīpanaṃ medhyaṃ pittakṛtkaphavātahṛt"},{"type":"verse","number":"2","sanskrit":"कासश्वासापहं शोथकामलापाण्डुरोगहृत्","text":"kāsaśvāsāpahaṃ śothakāmalāpāṇḍurogahṛt"},{"type":"verse","number":"3","sanskrit":"कासं सकुष्ठजठरकृमिपाण्डुरोगान्गोमूत्रमेकमपि पीतमपाकरोति","text":"kāsaṃ sakuṣṭhajaṭharakṛmipāṇḍurogāngomūtramekamapi pītamapākaroti"},{"type":"verse","number":"4","sanskrit":"सर्वेष्वपि च मूत्रेषु गोमूत्रं गुणतोऽधिकम् अतोऽविशेषात्कथने मूत्रं गोमूत्रमुच्यते","text":"sarveṣvapi ca mūtreṣu gomūtraṃ guṇato'dhikam ato'viśeṣātkathane mūtraṃ gomūtramucyate"},{"type":"verse","number":"5","sanskrit":"प्लीहोदरश्वासकासशोथवर्चोग्रहापहम्","text":"plīhodaraśvāsakāsaśothavarcograhāpaham"},{"type":"verse","number":"6","sanskrit":"कषायं तिक्ततीक्ष्णं च पूरणात्कर्णशूलहृत्","text":"kaṣāyaṃ tiktatīkṣṇaṃ ca pūraṇātkarṇaśūlahṛt"},{"type":"verse","number":"7","sanskrit":"नरमूत्रं गरं हन्ति सेवितं तद्र सायनम् रक्तपामाहरं तीक्ष्णं सक्षारलवणं स्मृतम्","text":"naramūtraṃ garaṃ hanti sevitaṃ tadra sāyanam raktapāmāharaṃ tīkṣṇaṃ sakṣāralavaṇaṃ smṛtam"},{"type":"verse","number":"8","sanskrit":"गोऽजाऽविमहिषीणां तु स्त्रीणां मूत्रं प्रशस्यते खरोष्ट्रेभनराश्वानां पुंसां मूत्रं हितं स्मृतम्","text":"go'jā'vimahiṣīṇāṃ tu strīṇāṃ mūtraṃ praśasyate kharoṣṭrebhanarāśvānāṃ puṃsāṃ mūtraṃ hitaṃ smṛtam"},{"type":"verse","number":"19","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे एकोनिविंशो मूत्रवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe ekoniviṃśo mūtravargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":19,"lang":"sa","content":[{"type":"heading","heading":"taila-варга — масла"},{"type":"verse","number":"1","sanskrit":"तिलादिस्निग्धवस्तूनां स्नेहस्तैलमुदाहृतम् तत्तु वातहरं सर्वं विशेषात्तिलसम्भवम्","text":"tilādisnigdhavastūnāṃ snehastailamudāhṛtam tattu vātaharaṃ sarvaṃ viśeṣāttilasambhavam"},{"type":"verse","number":"2","sanskrit":"तिलतैलं गुरु स्थैर्यबलवर्णकरं सरम् वृष्यं विकाशि विशदं मधुरं रसपाकयोः","text":"tilatailaṃ guru sthairyabalavarṇakaraṃ saram vṛṣyaṃ vikāśi viśadaṃ madhuraṃ rasapākayoḥ"},{"type":"verse","number":"3","sanskrit":"सूक्ष्मं कषायानुरसं तिक्तं वातकफापहम् वीर्येणोष्णं हिमं स्पर्शे बृंहणं रक्तपित्तकृत्","text":"sūkṣmaṃ kaṣāyānurasaṃ tiktaṃ vātakaphāpaham vīryeṇoṣṇaṃ himaṃ sparśe bṛṃhaṇaṃ raktapittakṛt"},{"type":"verse","number":"4","sanskrit":"लेखनं बद्धविण्मूत्रं गर्भाशयविशोधनम् दीपनं बुद्धिदं मेध्यं व्यवायि व्रणमेहनुत्","text":"lekhanaṃ baddhaviṇmūtraṃ garbhāśayaviśodhanam dīpanaṃ buddhidaṃ medhyaṃ vyavāyi vraṇamehanut"},{"type":"verse","number":"5","sanskrit":"श्रोत्रयोनिशिरःशूलनाशनं लघुताकरम् त्वच्यं केश्यं च चक्षुष्यमभ्यङ्गे भोजनेऽन्यथा","text":"śrotrayoniśiraḥśūlanāśanaṃ laghutākaram tvacyaṃ keśyaṃ ca cakṣuṣyamabhyaṅge bhojane'nyathā"},{"type":"verse","number":"6","sanskrit":"भग्नस्फुटितविद्धाग्निदग्धविश्लिष्टदारिते","text":"bhagnasphuṭitaviddhāgnidagdhaviśliṣṭadārite"},{"type":"verse","number":"7","sanskrit":"वस्तौ पानेऽन्नसंस्कारे नस्ये कर्णाक्षिपूरणे सेकाभ्यङ्गावगाहेषु तिलतैलं प्रशस्यते","text":"vastau pāne'nnasaṃskāre nasye karṇākṣipūraṇe sekābhyaṅgāvagāheṣu tilatailaṃ praśasyate"},{"type":"verse","number":"8","sanskrit":"रूक्षादिदुष्टः पवनः स्रोतः संकोचयेद् यदा रसोऽसम्यग्वहन् कार्श्यं कुर्याद्र क्तान्यवर्द्धयन्","text":"rūkṣādiduṣṭaḥ pavanaḥ srotaḥ saṃkocayed yadā raso'samyagvahan kārśyaṃ kuryādra ktānyavarddhayan"},{"type":"verse","number":"9","sanskrit":"तेषु प्रवेष्टुं सरतासौक्ष्म्यस्निग्धत्वमार्दवैः तैलं क्षमं रसं नेतुं कृशानां तेन बृंहणम्","text":"teṣu praveṣṭuṃ saratāsaukṣmyasnigdhatvamārdavaiḥ tailaṃ kṣamaṃ rasaṃ netuṃ kṛśānāṃ tena bṛṃhaṇam"},{"type":"verse","number":"10","sanskrit":"व्यवायिसूक्ष्मतीक्ष्णोष्णसरत्वैर्मेदसः क्षयम् शनैः प्रकुरुते तैलं तेन लेखनमीरितम्","text":"vyavāyisūkṣmatīkṣṇoṣṇasaratvairmedasaḥ kṣayam śanaiḥ prakurute tailaṃ tena lekhanamīritam"},{"type":"verse","number":"11","sanskrit":"द्रुतं पुरीषं बध्नाति स्खलितं तत्प्रवर्त्तयेत् ग्राहकं सारकञ्चापि तेन तैलमुदीरितम्","text":"drutaṃ purīṣaṃ badhnāti skhalitaṃ tatpravarttayet grāhakaṃ sārakañcāpi tena tailamudīritam"},{"type":"verse","number":"12","sanskrit":"घृतमब्दात्परं पक्वं हीनवीर्यं प्रजायते तैलं पक्वमपक्वं वा चिरस्थायि गुणाधिकम्","text":"ghṛtamabdātparaṃ pakvaṃ hīnavīryaṃ prajāyate tailaṃ pakvamapakvaṃ vā cirasthāyi guṇādhikam"},{"type":"verse","number":"13","sanskrit":"दीपनं सार्षपं तैलं कटुपाकरसं लघु लेखनं स्पर्शवीर्य्योष्णं तीक्ष्णं पित्तास्रदूषकम्","text":"dīpanaṃ sārṣapaṃ tailaṃ kaṭupākarasaṃ laghu lekhanaṃ sparśavīryyoṣṇaṃ tīkṣṇaṃ pittāsradūṣakam"},{"type":"verse","number":"14","sanskrit":"कफमेदोऽनिलार्शोघ्नं शिरःकर्णामयापहम् कण्डूकुष्ठकृमिश्वित्रकोठदुष्टकृमिप्रणुत्","text":"kaphamedo'nilārśoghnaṃ śiraḥkarṇāmayāpaham kaṇḍūkuṣṭhakṛmiśvitrakoṭhaduṣṭakṛmipraṇut"},{"type":"verse","number":"15","sanskrit":"तद्वद्रा जिकयोस्तैलं विशेषान्मूत्रकृच्छ्रकृत्","text":"tadvadrā jikayostailaṃ viśeṣānmūtrakṛcchrakṛt"},{"type":"verse","number":"16","sanskrit":"तीक्ष्णोष्णं तुवरी तैलं लघु ग्राहि कफास्रजित् बह्निकृद्विषहृत्कण्डूकुष्ठकोठकृमिप्रणुत् मेदोदोषापहं चापि व्रणशोथहरं परम्","text":"tīkṣṇoṣṇaṃ tuvarī tailaṃ laghu grāhi kaphāsrajit bahnikṛdviṣahṛtkaṇḍūkuṣṭhakoṭhakṛmipraṇut medodoṣāpahaṃ cāpi vraṇaśothaharaṃ param"},{"type":"verse","number":"17","sanskrit":"अतसीतैलमाग्नेयं स्निग्धोष्णं कफपित्तकृत् कटुपाकमचक्षुष्यं बल्यं वातहरं गुरु","text":"atasītailamāgneyaṃ snigdhoṣṇaṃ kaphapittakṛt kaṭupākamacakṣuṣyaṃ balyaṃ vātaharaṃ guru"},{"type":"verse","number":"18","sanskrit":"मलकृद्र सतः स्वादु ग्राहि त्वग्दोषहृद् घनम्","text":"malakṛdra sataḥ svādu grāhi tvagdoṣahṛd ghanam"},{"type":"verse","number":"19","sanskrit":"वस्तौ पाने तथाऽभ्यङ्गे नस्ये कर्णस्य पूरणे अनुपानविधौ चापि प्रयोज्यं वातशान्तये","text":"vastau pāne tathā'bhyaṅge nasye karṇasya pūraṇe anupānavidhau cāpi prayojyaṃ vātaśāntaye"},{"type":"verse","number":"20","sanskrit":"कुसुम्भतैलमम्लं स्यादुष्णं गुरुविदाहि च चक्षुर्भ्यामहितं बल्यं रक्तपित्तकफप्रदम्","text":"kusumbhatailamamlaṃ syāduṣṇaṃ guruvidāhi ca cakṣurbhyāmahitaṃ balyaṃ raktapittakaphapradam"},{"type":"verse","number":"21","sanskrit":"तैलं तु खसबीजानां बल्यं वृष्यं गुरुस्मृतम् वातहृत्कफहृच्छीतं स्वादुपाकरसं च तत्","text":"tailaṃ tu khasabījānāṃ balyaṃ vṛṣyaṃ gurusmṛtam vātahṛtkaphahṛcchītaṃ svādupākarasaṃ ca tat"},{"type":"verse","number":"22","sanskrit":"एरण्डतैलं तीक्ष्णोष्णं दीपनं पिच्छिलं गुरु वृष्यं त्वच्यं वयःस्थापि मेधाकान्तिबलप्रदम्","text":"eraṇḍatailaṃ tīkṣṇoṣṇaṃ dīpanaṃ picchilaṃ guru vṛṣyaṃ tvacyaṃ vayaḥsthāpi medhākāntibalapradam"},{"type":"verse","number":"23","sanskrit":"कषायानुरसं सूक्ष्मं योनिशुक्रविशोधनम् विस्रं स्वादु रसे पाके सतिक्तं कटुकं रसम्","text":"kaṣāyānurasaṃ sūkṣmaṃ yoniśukraviśodhanam visraṃ svādu rase pāke satiktaṃ kaṭukaṃ rasam"},{"type":"verse","number":"24","sanskrit":"बिषमज्वरहृद्रो गपृष्ठगुह्यादिशूलनुत् हन्ति वातोदरानाहगुल्माष्ठीलाकटिग्रहान्","text":"biṣamajvarahṛdro gapṛṣṭhaguhyādiśūlanut hanti vātodarānāhagulmāṣṭhīlākaṭigrahān"},{"type":"verse","number":"25","sanskrit":"वातशोणितविड्बन्धव्रघ्नशोथामविद्र धीन् आमवातगजेन्द्र स्य शरीरवनचारिणः एक एव निहन्ताऽयमैरण्डस्नेहकेसरी","text":"vātaśoṇitaviḍbandhavraghnaśothāmavidra dhīn āmavātagajendra sya śarīravanacāriṇaḥ eka eva nihantā'yamairaṇḍasnehakesarī"},{"type":"verse","number":"26","sanskrit":"तैलं सर्जरसोद्भूतं विस्फोटव्रणनाशनम् कुष्ठपामाकृमिहरं वातश्लेष्मामयापहम्","text":"tailaṃ sarjarasodbhūtaṃ visphoṭavraṇanāśanam kuṣṭhapāmākṛmiharaṃ vātaśleṣmāmayāpaham"},{"type":"verse","number":"27","sanskrit":"तैलं स्वयोनिगुणकृद्वाग्भटेनाखिलं मतम् अतः शेषस्य तैलस्य गुणा ज्ञेयाः स्वयोनिवत्","text":"tailaṃ svayoniguṇakṛdvāgbhaṭenākhilaṃ matam ataḥ śeṣasya tailasya guṇā jñeyāḥ svayonivat"},{"type":"verse","number":"20","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे विंशस्तैलवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe viṃśastailavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":20,"lang":"sa","content":[{"type":"heading","heading":"sandhāna-варга — ферментированные"},{"type":"verse","number":"1","sanskrit":"सन्धितं धान्यमण्डादि काञ्जिकं कथ्यते जनैः काञ्जिकं भेदि तीक्ष्णोष्णं रोचनं पाचनं लघु","text":"sandhitaṃ dhānyamaṇḍādi kāñjikaṃ kathyate janaiḥ kāñjikaṃ bhedi tīkṣṇoṣṇaṃ rocanaṃ pācanaṃ laghu"},{"type":"verse","number":"2","sanskrit":"दाहज्वरहरं स्पर्शात्पानाद्वातकफापहम् माषादिवटकैर्यत्तु क्रियते तद् गुणाधिकम्","text":"dāhajvaraharaṃ sparśātpānādvātakaphāpaham māṣādivaṭakairyattu kriyate tad guṇādhikam"},{"type":"verse","number":"3","sanskrit":"लघु वातहरं तत्तु रोचनं पाचनं परम् शूलाजीर्णविबन्धामनाशनं वस्तिशोधनम्","text":"laghu vātaharaṃ tattu rocanaṃ pācanaṃ param śūlājīrṇavibandhāmanāśanaṃ vastiśodhanam"},{"type":"verse","number":"4","sanskrit":"शोषमूर्च्छाभ्रमार्त्तानां मदकण्डूविशोषिणाम् कुष्ठिनां रक्तपित्तीनां काञ्जिकं न प्रशस्यते","text":"śoṣamūrcchābhramārttānāṃ madakaṇḍūviśoṣiṇām kuṣṭhināṃ raktapittīnāṃ kāñjikaṃ na praśasyate"},{"type":"verse","number":"5","sanskrit":"पाण्डुरोगे यक्ष्मणि च तथा शोषातुरेषु च क्षतक्षीणे तथा श्रान्ते मन्दज्वरनिपीडिते एतेषां न हितं प्रोक्तं काञ्जिकं दोषकारकम्","text":"pāṇḍuroge yakṣmaṇi ca tathā śoṣātureṣu ca kṣatakṣīṇe tathā śrānte mandajvaranipīḍite eteṣāṃ na hitaṃ proktaṃ kāñjikaṃ doṣakārakam"},{"type":"verse","number":"6","sanskrit":"तुषोदकं यवैरामैः सतुषैः शकलीकृतैः","text":"tuṣodakaṃ yavairāmaiḥ satuṣaiḥ śakalīkṛtaiḥ"},{"type":"verse","number":"7","sanskrit":"तुषाम्बु दीपनं हृद्यं पाण्डुकृमिगदापहम् तीक्ष्णोष्णं पाचनं पित्तरक्तकृद्वस्तिशूलनुत्","text":"tuṣāmbu dīpanaṃ hṛdyaṃ pāṇḍukṛmigadāpaham tīkṣṇoṣṇaṃ pācanaṃ pittaraktakṛdvastiśūlanut"},{"type":"verse","number":"8","sanskrit":"सौवीरं तु यवैरामैः पक्वैर्वा निस्तुषैः कृतम् गोधूमैरपि सौवीरमाचार्याः केचिदूचिरे","text":"sauvīraṃ tu yavairāmaiḥ pakvairvā nistuṣaiḥ kṛtam godhūmairapi sauvīramācāryāḥ kecidūcire"},{"type":"verse","number":"9","sanskrit":"सौवीरं तु ग्रहण्यर्शःकफघ्नं भेदि दीपनम् उदावर्त्ताङ्गमर्दास्थिशूलानाहेषु शस्यते","text":"sauvīraṃ tu grahaṇyarśaḥkaphaghnaṃ bhedi dīpanam udāvarttāṅgamardāsthiśūlānāheṣu śasyate"},{"type":"verse","number":"10","sanskrit":"आरनालं तु गोधूमैरामैः स्यान्निस्तुषीकृतैः पक्वैर्वा सन्धितैस्तत्तु सौवीरसदृशं गुणैः","text":"āranālaṃ tu godhūmairāmaiḥ syānnistuṣīkṛtaiḥ pakvairvā sandhitaistattu sauvīrasadṛśaṃ guṇaiḥ"},{"type":"verse","number":"11","sanskrit":"धान्याम्लं शालिचूर्णं च कोद्र वादिकृतं भवेत् धान्याम्लं धान्ययोनित्वात्प्रीणनं लघु दीपनम् अरुचौ वातरोगेषु सर्वेष्वास्थापने हितम्","text":"dhānyāmlaṃ śālicūrṇaṃ ca kodra vādikṛtaṃ bhavet dhānyāmlaṃ dhānyayonitvātprīṇanaṃ laghu dīpanam arucau vātarogeṣu sarveṣvāsthāpane hitam"},{"type":"verse","number":"12","sanskrit":"शिण्डाकी राजिकायुक्तैः स्यान्मूलकदलद्र वैः सर्षपस्वरसैर्वाऽपि शालिपिष्टकसंयुतैः","text":"śiṇḍākī rājikāyuktaiḥ syānmūlakadaladra vaiḥ sarṣapasvarasairvā'pi śālipiṣṭakasaṃyutaiḥ"},{"type":"verse","number":"13","sanskrit":"शिण्डाकी रोचनी गुर्वी पित्तश्लेष्मकरी स्मृता","text":"śiṇḍākī rocanī gurvī pittaśleṣmakarī smṛtā"},{"type":"verse","number":"14","sanskrit":"कन्दमूलफलादीनि सस्नेहलवणानि च यत्र द्र वेऽभिषूयन्ते तच्छुक्तमभिधीयते","text":"kandamūlaphalādīni sasnehalavaṇāni ca yatra dra ve'bhiṣūyante tacchuktamabhidhīyate"},{"type":"verse","number":"15","sanskrit":"शुक्तं कफघ्नं तीक्ष्णोष्णं रोचनं पाचनं लघु पाण्डुकृमिहरं रूक्षं भेदनं रक्तपित्तकृत्","text":"śuktaṃ kaphaghnaṃ tīkṣṇoṣṇaṃ rocanaṃ pācanaṃ laghu pāṇḍukṛmiharaṃ rūkṣaṃ bhedanaṃ raktapittakṛt"},{"type":"verse","number":"16","sanskrit":"कन्दमूलफलाढ्यं यत्तत्तु विज्ञेयमासुतम् तद्रुच्यं पाचनं वातहरं लघु विशेषतः","text":"kandamūlaphalāḍhyaṃ yattattu vijñeyamāsutam tadrucyaṃ pācanaṃ vātaharaṃ laghu viśeṣataḥ"},{"type":"verse","number":"17","sanskrit":"मद्यन्तु सीधुमैरेयमिरा च मदिरा सुरा कादम्बरी वारुणी च हालाऽपि बलवल्लभा","text":"madyantu sīdhumaireyamirā ca madirā surā kādambarī vāruṇī ca hālā'pi balavallabhā"},{"type":"verse","number":"18","sanskrit":"पेयं यन्मादकं लोकैस्तन्मद्यमभिधीयते यथाऽरिष्टं सुरा सीधुरासवाद्यमनेकधा","text":"peyaṃ yanmādakaṃ lokaistanmadyamabhidhīyate yathā'riṣṭaṃ surā sīdhurāsavādyamanekadhā"},{"type":"verse","number":"19","sanskrit":"मद्यं सर्वं भवेदुष्णं पित्तकृद्वातनाशनम् भेदनं शीघ्रपाकं च रूक्षं कफहरं परम्","text":"madyaṃ sarvaṃ bhaveduṣṇaṃ pittakṛdvātanāśanam bhedanaṃ śīghrapākaṃ ca rūkṣaṃ kaphaharaṃ param"},{"type":"verse","number":"20","sanskrit":"अम्लं च दीपनं रुच्यं पाचनं चाशुकारि च तीक्ष्णं सूक्ष्मं च विशदं व्यवायि च विकाशि च","text":"amlaṃ ca dīpanaṃ rucyaṃ pācanaṃ cāśukāri ca tīkṣṇaṃ sūkṣmaṃ ca viśadaṃ vyavāyi ca vikāśi ca"},{"type":"verse","number":"21","sanskrit":"पक्वौषधाम्बुसिद्धं यन्मद्यं तत्स्यादरिष्टकम्","text":"pakvauṣadhāmbusiddhaṃ yanmadyaṃ tatsyādariṣṭakam"},{"type":"verse","number":"22","sanskrit":"अरिष्टं लघुपाकेन सर्वतश्च गुणाधिकम् अरिष्टस्य गुणा ज्ञेया बीजद्र व्यगुणैः समाः","text":"ariṣṭaṃ laghupākena sarvataśca guṇādhikam ariṣṭasya guṇā jñeyā bījadra vyaguṇaiḥ samāḥ"},{"type":"verse","number":"23","sanskrit":"शालिषष्टिकपिष्टादिकृतं मद्यं सुरा स्मृता सुरा गुर्वी बलस्तन्यपुष्टिमेदःकफप्रदा ग्राहिणी शोथगुल्मार्शोग्रहणीमूत्रकृच्छ्रनुत्","text":"śāliṣaṣṭikapiṣṭādikṛtaṃ madyaṃ surā smṛtā surā gurvī balastanyapuṣṭimedaḥkaphapradā grāhiṇī śothagulmārśograhaṇīmūtrakṛcchranut"},{"type":"verse","number":"24","sanskrit":"पुनर्नवाशिलापिष्टैर्विहिता वारुणी स्मृता संहितैस्तालखर्जूररसैर्या साऽपि वारुणी सुरावद्वारुणी लघ्वी पीनसाध्मानशूलनुत्","text":"punarnavāśilāpiṣṭairvihitā vāruṇī smṛtā saṃhitaistālakharjūrarasairyā sā'pi vāruṇī surāvadvāruṇī laghvī pīnasādhmānaśūlanut"},{"type":"verse","number":"25","sanskrit":"इक्षोः पक्वै रसैः सिद्धः सीधुः पक्वरसश्च सः आमैस्तैरेव यः सीधुः स च शीतरसः स्मृतः","text":"ikṣoḥ pakvai rasaiḥ siddhaḥ sīdhuḥ pakvarasaśca saḥ āmaistaireva yaḥ sīdhuḥ sa ca śītarasaḥ smṛtaḥ"},{"type":"verse","number":"26","sanskrit":"सीधुः पक्वरसः श्रेष्ठः स्वराग्निबलवर्णकृत् वातपित्तकरः सद्यः स्नेहनो रोचनो हरेत्","text":"sīdhuḥ pakvarasaḥ śreṣṭhaḥ svarāgnibalavarṇakṛt vātapittakaraḥ sadyaḥ snehano rocano haret"},{"type":"verse","number":"27","sanskrit":"विबन्धमेदः शोफार्शः शोफोदरकफामयान् तस्मादल्पगुणः शीतरसः संलेखनः स्मृतः","text":"vibandhamedaḥ śophārśaḥ śophodarakaphāmayān tasmādalpaguṇaḥ śītarasaḥ saṃlekhanaḥ smṛtaḥ"},{"type":"verse","number":"28","sanskrit":"यदपक्व्षधाम्बुभ्यां सिद्धं मद्यं स आसवः","text":"yadapakvṣadhāmbubhyāṃ siddhaṃ madyaṃ sa āsavaḥ"},{"type":"verse","number":"29","sanskrit":"आसवस्य गुणा ज्ञेया बीजद्र व्यगुणैः समाः","text":"āsavasya guṇā jñeyā bījadra vyaguṇaiḥ samāḥ"},{"type":"verse","number":"30","sanskrit":"मद्यं नवमभिष्यन्दि त्रिदोषजनकं सरम् अहृद्यं बृंहणं दाहि दुर्गन्धं विशदं गुरु","text":"madyaṃ navamabhiṣyandi tridoṣajanakaṃ saram ahṛdyaṃ bṛṃhaṇaṃ dāhi durgandhaṃ viśadaṃ guru"},{"type":"verse","number":"31","sanskrit":"जीर्णं तदेव रोचिष्णु कृमिश्लेष्मानिलापहम् हृद्यं सुगन्धि गुणवल्लघु स्रोतोविशोधनम्","text":"jīrṇaṃ tadeva rociṣṇu kṛmiśleṣmānilāpaham hṛdyaṃ sugandhi guṇavallaghu srotoviśodhanam"},{"type":"verse","number":"32","sanskrit":"सात्त्विकेगीतहास्यादि राजसे साहासादिकम् तामसे निन्द्यकर्माणि निद्रा ञ्च मदिराऽचरेत्","text":"sāttvikegītahāsyādi rājase sāhāsādikam tāmase nindyakarmāṇi nidrā ñca madirā'caret"},{"type":"verse","number":"33","sanskrit":"विधिना मात्रया काले हितैरन्नैर्यथाबलम् प्रहृष्टो यः पिबेन्मद्यं तस्य स्यादमृतं यथा","text":"vidhinā mātrayā kāle hitairannairyathābalam prahṛṣṭo yaḥ pibenmadyaṃ tasya syādamṛtaṃ yathā"},{"type":"verse","number":"34","sanskrit":"किन्तु मद्यं स्वभावेन यथैवान्नं तथा स्मृतम् अयुक्तियुक्तं रोगाय युक्तियुक्तं यथाऽमृतम्","text":"kintu madyaṃ svabhāvena yathaivānnaṃ tathā smṛtam ayuktiyuktaṃ rogāya yuktiyuktaṃ yathā'mṛtam"},{"type":"verse","number":"35","sanskrit":"मुस्तैलवालुगदजीरकधान्यकैला यश्चर्वयन्सदसि वाचमभिव्यनक्ति स्वाभाविकं मुखजमुञ्झति पूतिगन्धं गन्धञ्च मद्यलशुनादि भवञ्च नूनम्","text":"mustailavālugadajīrakadhānyakailā yaścarvayansadasi vācamabhivyanakti svābhāvikaṃ mukhajamuñjhati pūtigandhaṃ gandhañca madyalaśunādi bhavañca nūnam"},{"type":"verse","number":"21","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे एकविंशः सन्धानवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe ekaviṃśaḥ sandhānavargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":21,"lang":"sa","content":[{"type":"heading","heading":"madhu-варга — мёд"},{"type":"verse","number":"1","sanskrit":"मधु माक्षिक माध्वीकक्षौद्र सारघमीरितम् मक्षिकावरटीभृङ्गवान्तं पुष्परसोद्भवम्","text":"madhu mākṣika mādhvīkakṣaudra sāraghamīritam makṣikāvaraṭībhṛṅgavāntaṃ puṣparasodbhavam"},{"type":"verse","number":"2","sanskrit":"मधु शीतं लघु स्वादु रूक्षं ग्राहि विलेखनम् चक्षुष्यं दीपनं स्वर्यं व्रणशोधनरोपणम्","text":"madhu śītaṃ laghu svādu rūkṣaṃ grāhi vilekhanam cakṣuṣyaṃ dīpanaṃ svaryaṃ vraṇaśodhanaropaṇam"},{"type":"verse","number":"3","sanskrit":"सौकुमार्यकरं सूक्ष्मं परं स्रोतोविशोधनम् कषायानुरसं ह्लादि प्रसादजनकं परम्","text":"saukumāryakaraṃ sūkṣmaṃ paraṃ srotoviśodhanam kaṣāyānurasaṃ hlādi prasādajanakaṃ param"},{"type":"verse","number":"4","sanskrit":"वर्ण्यं मेधाकरं वृष्यं विशदं रोचनं हरेत् कुष्ठार्शःकास पित्तास्र कफ मेह क्लमकृमीन्","text":"varṇyaṃ medhākaraṃ vṛṣyaṃ viśadaṃ rocanaṃ haret kuṣṭhārśaḥkāsa pittāsra kapha meha klamakṛmīn"},{"type":"verse","number":"5","sanskrit":"मेदस्तृष्णा वमिश्वास हिक्काऽतीसारविड्ग्रहान् दाहक्षतक्षयांस्तत्तु योगवाह्यल्पवातलम्","text":"medastṛṣṇā vamiśvāsa hikkā'tīsāraviḍgrahān dāhakṣatakṣayāṃstattu yogavāhyalpavātalam"},{"type":"verse","number":"6","sanskrit":"माक्षिकं भ्रामरं क्षौद्रं पौत्तिकंछात्रमित्यपि आर्घ्यमौद्दालकं दालमित्यष्टौ मधुजातयः","text":"mākṣikaṃ bhrāmaraṃ kṣaudraṃ pauttikaṃchātramityapi ārghyamauddālakaṃ dālamityaṣṭau madhujātayaḥ"},{"type":"verse","number":"7","sanskrit":"मक्षिकाः पिङ्गवर्णास्तु महत्यो मधुमक्षिकाः ताभिः कृतं तैलवर्णं माक्षिकं परिकीर्त्तितम्","text":"makṣikāḥ piṅgavarṇāstu mahatyo madhumakṣikāḥ tābhiḥ kṛtaṃ tailavarṇaṃ mākṣikaṃ parikīrttitam"},{"type":"verse","number":"8","sanskrit":"माक्षिकं मधुषु श्रेष्ठं नेत्रामयहरं लघु कामलाऽशक्षतश्वासकासक्षयविनाशनम्","text":"mākṣikaṃ madhuṣu śreṣṭhaṃ netrāmayaharaṃ laghu kāmalā'śakṣataśvāsakāsakṣayavināśanam"},{"type":"verse","number":"9","sanskrit":"किञ्चित्सूक्ष्मैः प्रसिद्धेभ्यः षट्पदेभ्योऽलिभिश्चितं निर्मलं स्फटिकाभं यत्तन्मधु भ्रामरं स्मृतम्","text":"kiñcitsūkṣmaiḥ prasiddhebhyaḥ ṣaṭpadebhyo'libhiścitaṃ nirmalaṃ sphaṭikābhaṃ yattanmadhu bhrāmaraṃ smṛtam"},{"type":"verse","number":"10","sanskrit":"भ्रामरं रक्तपित्तघ्नं मूत्रजाड्यकरं गुरु स्वादुपाकमभिष्यन्दि विशेषात्पिच्छिलं हिमम्","text":"bhrāmaraṃ raktapittaghnaṃ mūtrajāḍyakaraṃ guru svādupākamabhiṣyandi viśeṣātpicchilaṃ himam"},{"type":"verse","number":"11","sanskrit":"मक्षिकाःकपिलाः सूक्ष्माः क्षुद्रा ऽख्यास्तत्कृतं मधु मुनिभिः क्षौद्र मित्युक्तंतद्वर्णात्कपिलं भवेत् गुणैर्माक्षिकवत्क्षौद्रं विशेषान्मेहनाशनम्","text":"makṣikāḥkapilāḥ sūkṣmāḥ kṣudrā 'khyāstatkṛtaṃ madhu munibhiḥ kṣaudra mityuktaṃtadvarṇātkapilaṃ bhavet guṇairmākṣikavatkṣaudraṃ viśeṣānmehanāśanam"},{"type":"verse","number":"12","sanskrit":"कृष्णा या मशकोपमा लघुतराः प्रायो महापीडिका वृक्षाणां पृथुकोटरान्तरगताः पुष्पासवं कुर्वते तास्तज्ज्ञैरिह पुत्तिका निगदितास्ताभिः कृतं सर्पिषा तुल्यं यन्मधु तद्वनेचरजनैः संकीर्तितं पौत्तिकम्","text":"kṛṣṇā yā maśakopamā laghutarāḥ prāyo mahāpīḍikā vṛkṣāṇāṃ pṛthukoṭarāntaragatāḥ puṣpāsavaṃ kurvate tāstajjñairiha puttikā nigaditāstābhiḥ kṛtaṃ sarpiṣā tulyaṃ yanmadhu tadvanecarajanaiḥ saṃkīrtitaṃ pauttikam"},{"type":"verse","number":"13","sanskrit":"पौत्तिकं मधु रूक्षोष्णं पित्तदाहास्रवातकृत् विदाहि मेहकृच्छ्रघ्नं ग्रन्थ्यादिक्षतशोषि च","text":"pauttikaṃ madhu rūkṣoṣṇaṃ pittadāhāsravātakṛt vidāhi mehakṛcchraghnaṃ granthyādikṣataśoṣi ca"},{"type":"verse","number":"14","sanskrit":"वरटाः कपिलाः पीताः प्रायो हिमवतो वने","text":"varaṭāḥ kapilāḥ pītāḥ prāyo himavato vane"},{"type":"verse","number":"15","sanskrit":"कुर्वन्ति च्छत्रकाकारं तज्जं छात्रं मधु स्मृतम् छात्रं कपिलपीतं स्यात्पिच्छिलं शीतलं गुरु","text":"kurvanti cchatrakākāraṃ tajjaṃ chātraṃ madhu smṛtam chātraṃ kapilapītaṃ syātpicchilaṃ śītalaṃ guru"},{"type":"verse","number":"16","sanskrit":"स्वादुपाकं कृमिश्वित्ररक्तपित्तप्रमेहजित् भ्रमतृण्मोहविषहृत्तर्पणञ्चगुणाधिकम्","text":"svādupākaṃ kṛmiśvitraraktapittapramehajit bhramatṛṇmohaviṣahṛttarpaṇañcaguṇādhikam"},{"type":"verse","number":"17","sanskrit":"मधूकवृक्षनिर्यासं जरत्कार्वाश्रभोद्भवम् स्रवत्यार्घ्यं तदाख्यातं श्वेतकं मालवे पुनः","text":"madhūkavṛkṣaniryāsaṃ jaratkārvāśrabhodbhavam sravatyārghyaṃ tadākhyātaṃ śvetakaṃ mālave punaḥ"},{"type":"verse","number":"18","sanskrit":"तीक्ष्णतुण्डास्तु याः पीता मक्षिकाः षट्पदोपमाः अर्घ्यास्तास्तत्कृतं यत्तदार्घ्यमित्यपरे जगुः","text":"tīkṣṇatuṇḍāstu yāḥ pītā makṣikāḥ ṣaṭpadopamāḥ arghyāstāstatkṛtaṃ yattadārghyamityapare jaguḥ"},{"type":"verse","number":"19","sanskrit":"आर्घ्यं मध्वतिचक्षुष्यं कफपित्तहरं परम् कषायं कटुकं पाके तिक्तञ्च बलपुष्टिकृत्","text":"ārghyaṃ madhvaticakṣuṣyaṃ kaphapittaharaṃ param kaṣāyaṃ kaṭukaṃ pāke tiktañca balapuṣṭikṛt"},{"type":"verse","number":"20","sanskrit":"प्रायो वल्मीकमध्यस्थाः कपिलाः स्वल्पकीटकाः कुर्वन्ति कपिलं स्वल्पं तत्स्यादौद्दालकं मधु","text":"prāyo valmīkamadhyasthāḥ kapilāḥ svalpakīṭakāḥ kurvanti kapilaṃ svalpaṃ tatsyādauddālakaṃ madhu"},{"type":"verse","number":"21","sanskrit":"औद्दालकं रुचिकरं स्वर्यं कुष्ठविषापहम् कपायमुष्णमम्लञ्च कटुपाकञ्च पित्तकृत्","text":"auddālakaṃ rucikaraṃ svaryaṃ kuṣṭhaviṣāpaham kapāyamuṣṇamamlañca kaṭupākañca pittakṛt"},{"type":"verse","number":"22","sanskrit":"संस्रुत्य पतितं पुष्पाद्यत्तु पत्रोपरि स्थितम् मधुराम्लकषायञ्च तद्दालं मधु कीर्त्तितम्","text":"saṃsrutya patitaṃ puṣpādyattu patropari sthitam madhurāmlakaṣāyañca taddālaṃ madhu kīrttitam"},{"type":"verse","number":"23","sanskrit":"दालं मधु लघु प्रोक्तं दीपनीयं कफापहम् कषायानुरसं रूक्षं रुच्यं छर्दिप्रमेहजित्","text":"dālaṃ madhu laghu proktaṃ dīpanīyaṃ kaphāpaham kaṣāyānurasaṃ rūkṣaṃ rucyaṃ chardipramehajit"},{"type":"verse","number":"24","sanskrit":"अधिकं मधुरं स्निग्धं बृंहणं गुरु भारिकम्","text":"adhikaṃ madhuraṃ snigdhaṃ bṛṃhaṇaṃ guru bhārikam"},{"type":"verse","number":"25","sanskrit":"नवं मधुभवेत्पुष्टयै नातिश्लेष्महरं सरम् पुराणं ग्राहकं रूक्षं मेदोघ्नमतिलेखनम्","text":"navaṃ madhubhavetpuṣṭayai nātiśleṣmaharaṃ saram purāṇaṃ grāhakaṃ rūkṣaṃ medoghnamatilekhanam"},{"type":"verse","number":"26","sanskrit":"मधुनः शर्करायाश्च गुडस्यापि विशेषतः एकसंवत्सरे वृत्ते पुराणत्वं स्मृतं बुधैः","text":"madhunaḥ śarkarāyāśca guḍasyāpi viśeṣataḥ ekasaṃvatsare vṛtte purāṇatvaṃ smṛtaṃ budhaiḥ"},{"type":"verse","number":"27","sanskrit":"विषपुष्पादपि रसं सविषा भ्रमरादयः गृहीत्वा मधु कुर्वन्ति तच्छीतं गुणवन्मधु","text":"viṣapuṣpādapi rasaṃ saviṣā bhramarādayaḥ gṛhītvā madhu kurvanti tacchītaṃ guṇavanmadhu"},{"type":"verse","number":"28","sanskrit":"विषान्वयात्तदुष्णन्तु द्र व्येणोष्णेन वा सह उष्णार्त्तस्योष्णकाले च स्मृतं विषसमं मधु","text":"viṣānvayāttaduṣṇantu dra vyeṇoṣṇena vā saha uṣṇārttasyoṣṇakāle ca smṛtaṃ viṣasamaṃ madhu"},{"type":"verse","number":"29","sanskrit":"मयनं तु मधूच्छिष्टं मधुशेषं च सिक्थकम् मध्वाधारो मदनकं मधूषितमति स्मृतम्","text":"mayanaṃ tu madhūcchiṣṭaṃ madhuśeṣaṃ ca sikthakam madhvādhāro madanakaṃ madhūṣitamati smṛtam"},{"type":"verse","number":"30","sanskrit":"मदनं मृदु सुस्निग्धं भूतघ्नं व्रणरोपणम् भग्नसन्धान्कृद्वातकुष्ठवीसर्परक्तजित्","text":"madanaṃ mṛdu susnigdhaṃ bhūtaghnaṃ vraṇaropaṇam bhagnasandhānkṛdvātakuṣṭhavīsarparaktajit"},{"type":"verse","number":"22","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे द्वाविंशो मधुवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe dvāviṃśo madhuvargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":22,"lang":"sa","content":[{"type":"heading","heading":"ikṣu-варга — сахарный тростник"},{"type":"verse","number":"1","sanskrit":"इक्षुर्दीर्घच्छदः प्रोक्तस्तथा भूरिरसोऽपि च गुडमूलोऽसिपत्रश्च तथा मधुतृणः स्मृतः","text":"ikṣurdīrghacchadaḥ proktastathā bhūriraso'pi ca guḍamūlo'sipatraśca tathā madhutṛṇaḥ smṛtaḥ"},{"type":"verse","number":"2","sanskrit":"इक्षवो रक्तपित्तघ्ना बल्या वृष्याः कफप्रदाः स्वादुपाकरसाः स्निग्धाः गुरवो मूत्रला हिमाः","text":"ikṣavo raktapittaghnā balyā vṛṣyāḥ kaphapradāḥ svādupākarasāḥ snigdhāḥ guravo mūtralā himāḥ"},{"type":"verse","number":"3","sanskrit":"पौण्ड्रको भीरुकश्चापि वंशकः शतपोरकः कान्तारतापसेक्षुश्च काण्डेक्षुः सूचिपत्रकः","text":"pauṇḍrako bhīrukaścāpi vaṃśakaḥ śataporakaḥ kāntāratāpasekṣuśca kāṇḍekṣuḥ sūcipatrakaḥ"},{"type":"verse","number":"4","sanskrit":"नैपालो दीर्घपत्रश्च नीलपोरोऽथ कोशकृत् मनोगुप्ता च इत्येता जातयस्तत्र कीर्त्तिताः","text":"naipālo dīrghapatraśca nīlaporo'tha kośakṛt manoguptā ca ityetā jātayastatra kīrttitāḥ"},{"type":"verse","number":"5","sanskrit":"वातपित्तप्रशमनो मधुरो रसपाकयोः सुशीतो वृंहणो बल्यः पौण्ड्रको भीरुकस्तथा","text":"vātapittapraśamano madhuro rasapākayoḥ suśīto vṛṃhaṇo balyaḥ pauṇḍrako bhīrukastathā"},{"type":"verse","number":"6","sanskrit":"कोशकारो गुरुः शीतो रक्तपित्तक्षयापहः","text":"kośakāro guruḥ śīto raktapittakṣayāpahaḥ"},{"type":"verse","number":"7","sanskrit":"कान्तारेक्षुर्गुरुर्वृष्यः श्लेष्मलो वृंहणः सरः","text":"kāntārekṣurgururvṛṣyaḥ śleṣmalo vṛṃhaṇaḥ saraḥ"},{"type":"verse","number":"8","sanskrit":"दीर्घपोरः सुकठिनः सक्षारो वंशकः स्मृतः","text":"dīrghaporaḥ sukaṭhinaḥ sakṣāro vaṃśakaḥ smṛtaḥ"},{"type":"verse","number":"9","sanskrit":"शतपर्वा भवेत्किञ्चित्कोशकारगुणान्वितः विशेषात्किञ्चिदुष्णश्च सक्षारः पवनापहः","text":"śataparvā bhavetkiñcitkośakāraguṇānvitaḥ viśeṣātkiñciduṣṇaśca sakṣāraḥ pavanāpahaḥ"},{"type":"verse","number":"10","sanskrit":"तापसेक्षुर्भवेन्मृद्वी मधुरा श्लेष्मकोपनी तर्पणी रुचिकृच्चापि वृष्या च बलकारिणी","text":"tāpasekṣurbhavenmṛdvī madhurā śleṣmakopanī tarpaṇī rucikṛccāpi vṛṣyā ca balakāriṇī"},{"type":"verse","number":"11","sanskrit":"एवं गुणैस्तु काण्डेक्षुः स तु वातप्रकोपणः","text":"evaṃ guṇaistu kāṇḍekṣuḥ sa tu vātaprakopaṇaḥ"},{"type":"verse","number":"12","sanskrit":"सूचीपत्रो नीलपोरो नैपालो दीर्घपत्रकः वातलाः कफपित्तघ्नाः सकषाया विदाहिनः","text":"sūcīpatro nīlaporo naipālo dīrghapatrakaḥ vātalāḥ kaphapittaghnāḥ sakaṣāyā vidāhinaḥ"},{"type":"verse","number":"13","sanskrit":"मनोगुप्ता वातहरी तृष्णाऽमयविनाशिनी सुशीता मधुराऽतीव रक्तपित्तप्रणाशिनी","text":"manoguptā vātaharī tṛṣṇā'mayavināśinī suśītā madhurā'tīva raktapittapraṇāśinī"},{"type":"verse","number":"14","sanskrit":"बालइक्षुः कफं कुर्य्यान्मेदोमेहकरश्च सः युवा तु वातहृत् स्वादुरीषत्तीक्ष्णश्च पित्तनुत् रक्तपित्तहरो वृद्धः क्षतहृद्बलवीर्यकृत्","text":"bālaikṣuḥ kaphaṃ kuryyānmedomehakaraśca saḥ yuvā tu vātahṛt svādurīṣattīkṣṇaśca pittanut raktapittaharo vṛddhaḥ kṣatahṛdbalavīryakṛt"},{"type":"verse","number":"15","sanskrit":"मूले तु मधुरोऽत्यर्थं मध्येऽपि मधुरः स्मृतः अग्रे ग्रन्थिषु विज्ञेय इक्षुः पटुरसोजनैः","text":"mūle tu madhuro'tyarthaṃ madhye'pi madhuraḥ smṛtaḥ agre granthiṣu vijñeya ikṣuḥ paṭurasojanaiḥ"},{"type":"verse","number":"16","sanskrit":"दन्तनिष्पीडितस्येक्षो रसः पित्तास्रनाशनः शर्करासमवीर्यः स्यादविदाही कफप्रदः","text":"dantaniṣpīḍitasyekṣo rasaḥ pittāsranāśanaḥ śarkarāsamavīryaḥ syādavidāhī kaphapradaḥ"},{"type":"verse","number":"17","sanskrit":"किञ्चित्कालविधृत्या च विकृतिं याति यान्त्रिकः तस्माद्विदाही विष्टम्भी गुरुः स्याद्यान्त्रिको रसः","text":"kiñcitkālavidhṛtyā ca vikṛtiṃ yāti yāntrikaḥ tasmādvidāhī viṣṭambhī guruḥ syādyāntriko rasaḥ"},{"type":"verse","number":"18","sanskrit":"रसः पर्युषितो नेष्टो ह्यम्लो वातापहो गुरुः कफपित्तकरः शोषी भेदनश्चातिमूत्रलः","text":"rasaḥ paryuṣito neṣṭo hyamlo vātāpaho guruḥ kaphapittakaraḥ śoṣī bhedanaścātimūtralaḥ"},{"type":"verse","number":"19","sanskrit":"पक्वो रसो गुरुः स्निग्धः सुतीक्ष्णः कफवातनुत् गुल्मानाहप्रशमनः किञ्चित्पित्तकरः स्मृतः","text":"pakvo raso guruḥ snigdhaḥ sutīkṣṇaḥ kaphavātanut gulmānāhapraśamanaḥ kiñcitpittakaraḥ smṛtaḥ"},{"type":"verse","number":"20","sanskrit":"गुरवो मधुरा बल्याः स्निग्धा वातहराः सराः वृष्या मोहहराः शीता वृंहणा विषहारिणः","text":"guravo madhurā balyāḥ snigdhā vātaharāḥ sarāḥ vṛṣyā mohaharāḥ śītā vṛṃhaṇā viṣahāriṇaḥ"},{"type":"verse","number":"21","sanskrit":"इक्षो रसस्तु यः पक्वः किञ्चिद्गाढो बहुद्र वः स एवेक्षुविकारेषु ख्यातः फाणितसंज्ञया फाणितं गुर्वभिष्यन्दि वृंहणं कफशुक्रकृत् वातपित्तश्रमान्हन्ति मूत्रवस्तिविशोधनम्","text":"ikṣo rasastu yaḥ pakvaḥ kiñcidgāḍho bahudra vaḥ sa evekṣuvikāreṣu khyātaḥ phāṇitasaṃjñayā phāṇitaṃ gurvabhiṣyandi vṛṃhaṇaṃ kaphaśukrakṛt vātapittaśramānhanti mūtravastiviśodhanam"},{"type":"verse","number":"22","sanskrit":"इक्षो रसो यः सम्पक्वो घनः किञ्चिद्द्र वान्वितः","text":"ikṣo raso yaḥ sampakvo ghanaḥ kiñciddra vānvitaḥ"},{"type":"verse","number":"23","sanskrit":"मन्दं यत्स्यन्दते तस्मात्तन्मत्स्यण्डी निगद्यते मत्स्यण्डी भेदिनी बल्या लघ्वी पित्तानिलापहा मधुरा बृंहणी वृष्या रक्तदोषापहा स्मृता","text":"mandaṃ yatsyandate tasmāttanmatsyaṇḍī nigadyate matsyaṇḍī bhedinī balyā laghvī pittānilāpahā madhurā bṛṃhaṇī vṛṣyā raktadoṣāpahā smṛtā"},{"type":"verse","number":"24","sanskrit":"इक्षो रसो यः सम्पन्नो जायते लोष्टवद् दृढः","text":"ikṣo raso yaḥ sampanno jāyate loṣṭavad dṛḍhaḥ"},{"type":"verse","number":"25","sanskrit":"स गुडो गौडदेशे तु मत्स्यण्ड्येव गुडो मतः गुडो वृष्यो गुरुः स्निग्धो वातघ्नो मूत्रशोधनः नातिपित्तहरो मेदःकफकृमिबलप्रदः","text":"sa guḍo gauḍadeśe tu matsyaṇḍyeva guḍo mataḥ guḍo vṛṣyo guruḥ snigdho vātaghno mūtraśodhanaḥ nātipittaharo medaḥkaphakṛmibalapradaḥ"},{"type":"verse","number":"26","sanskrit":"गुडो जीर्णो लघुः पथ्योऽनभिष्यन्द्यग्निपुष्टिकृत् पित्तघ्नो मधुरो वृष्यो वातघ्नोऽसृक्प्रसादनः","text":"guḍo jīrṇo laghuḥ pathyo'nabhiṣyandyagnipuṣṭikṛt pittaghno madhuro vṛṣyo vātaghno'sṛkprasādanaḥ"},{"type":"verse","number":"27","sanskrit":"गुडो नवः कफश्वासकासकृमिकरोऽग्निकृत्","text":"guḍo navaḥ kaphaśvāsakāsakṛmikaro'gnikṛt"},{"type":"verse","number":"28","sanskrit":"श्लेष्माणमाशु विनिहन्ति सहार्द्र केण पित्तं निहन्ति च तदेव हरीतकीभिः शुण्ठ्या समं हरति वातमशेषमित्थं दोषत्रयक्षयकराय नमो गुडाय","text":"śleṣmāṇamāśu vinihanti sahārdra keṇa pittaṃ nihanti ca tadeva harītakībhiḥ śuṇṭhyā samaṃ harati vātamaśeṣamitthaṃ doṣatrayakṣayakarāya namo guḍāya"},{"type":"verse","number":"29","sanskrit":"खण्डन्तु मधुरं वृष्यं चक्षुष्यं बृंहणं हिमम् वातपित्तहरं स्निग्धं बल्यं वान्तिहरं परम्","text":"khaṇḍantu madhuraṃ vṛṣyaṃ cakṣuṣyaṃ bṛṃhaṇaṃ himam vātapittaharaṃ snigdhaṃ balyaṃ vāntiharaṃ param"},{"type":"verse","number":"30","sanskrit":"खण्डन्तु सिकतारूपं सुश्वेतं शर्करा सिता सिता सुमधुरा रुच्या वातपित्तास्रदाहहृत् मूर्च्छाच्छर्दिज्वरान्हन्ति सुशीता शुक्रकारिणी","text":"khaṇḍantu sikatārūpaṃ suśvetaṃ śarkarā sitā sitā sumadhurā rucyā vātapittāsradāhahṛt mūrcchācchardijvarānhanti suśītā śukrakāriṇī"},{"type":"verse","number":"31","sanskrit":"भवेत्पुष्पसिता शीता रक्तपित्तहरी लघुः सितोपला सरा लघ्वी वातपित्तहरी हिमा","text":"bhavetpuṣpasitā śītā raktapittaharī laghuḥ sitopalā sarā laghvī vātapittaharī himā"},{"type":"verse","number":"32","sanskrit":"मधुजा शर्करा रूक्षा कफपित्तहरा गुरुः छर्द्यतीसारतृड्दाहरक्तहृत्तुवरा हिमा","text":"madhujā śarkarā rūkṣā kaphapittaharā guruḥ chardyatīsāratṛḍdāharaktahṛttuvarā himā"},{"type":"verse","number":"33","sanskrit":"यथा यथैषां नैर्मल्यं मधुरत्वं यथा यथा स्नेहलाघवशैत्यादि सरत्वञ्च तथा तथा","text":"yathā yathaiṣāṃ nairmalyaṃ madhuratvaṃ yathā yathā snehalāghavaśaityādi saratvañca tathā tathā"},{"type":"verse","number":"23","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे त्रयोविंश इक्षुवर्गः समाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe trayoviṃśa ikṣuvargaḥ samāptaḥ"}]},{"sthana":"Мадхьямакханда","number":23,"lang":"sa","content":[{"type":"heading","heading":"anekārtha-варга — разное"},{"type":"verse","number":"1","sanskrit":"अक्षशब्दः स्मृतोऽष्टासु सौवर्चलबिभीतके कर्षपद्माक्षरुद्रा क्षशकटेन्द्रि यपाशके","text":"akṣaśabdaḥ smṛto'ṣṭāsu sauvarcalabibhītake karṣapadmākṣarudrā kṣaśakaṭendri yapāśake"},{"type":"verse","number":"2","sanskrit":"काकाख्यः काकमाची च काकोली काकणन्तिका काकजङ्घा काकनासा काकोदुम्बरिकाऽपि च सप्तस्वर्थेषु कथितः काकशब्दो विचक्षणैः","text":"kākākhyaḥ kākamācī ca kākolī kākaṇantikā kākajaṅghā kākanāsā kākodumbarikā'pi ca saptasvartheṣu kathitaḥ kākaśabdo vicakṣaṇaiḥ"},{"type":"verse","number":"3","sanskrit":"सर्पद्विरदमेषेषु सीसके नागकेसरे नागबल्ल्यां नागदन्त्यां नागशब्दः प्रयुज्यते","text":"sarpadviradameṣeṣu sīsake nāgakesare nāgaballyāṃ nāgadantyāṃ nāgaśabdaḥ prayujyate"},{"type":"verse","number":"4","sanskrit":"मांसेद्र वे चेक्षुरसे पारदे मधुरादिषु बोले रागे विषे नीरे रसो नवसु वर्त्तते","text":"māṃsedra ve cekṣurase pārade madhurādiṣu bole rāge viṣe nīre raso navasu varttate"},{"type":"verse","number":"24","sanskrit":"इति श्रीमिश्रलटकन तनय श्रीमिश्रभाव विरचिते भावप्रकाशे मिश्रप्रकरणे चतुर्विंशोऽनेकार्थवर्गःसमाप्तः","text":"iti śrīmiśralaṭakana tanaya śrīmiśrabhāva viracite bhāvaprakāśe miśraprakaraṇe caturviṃśo'nekārthavargaḥsamāptaḥ"},{"type":"verse","number":"6","sanskrit":"इति भावप्रकाशे पूर्वखण्डे प्रथमभागे द्रव्यगुणप्रकरणापरनामकं षष्ठं मिश्रप्रकरणं समाप्तम्","text":"iti bhāvaprakāśe pūrvakhaṇḍe prathamabhāge dravyaguṇaprakaraṇāparanāmakaṃ ṣaṣṭhaṃ miśraprakaraṇaṃ samāptam"}]},{"sthana":"Уттаракханда","number":1,"lang":"sa","content":[{"type":"heading","heading":"Джвара — лечение лихорадки"},{"type":"verse","number":"1","sanskrit":"यतः समस्तरोगाणां ज्वरो राजेति विश्रुतः अतो ज्वराधिकारोऽत्र प्रथमं लिख्यते मया","text":"yataḥ samastarogāṇāṃ jvaro rājeti viśrutaḥ ato jvarādhikāro'tra prathamaṃ likhyate mayā"},{"type":"verse","number":"2","sanskrit":"दक्षापमानसंक्रुद्धरुद्र निः श्वाससम्भवः ज्वरोऽष्टधा पृथग्द्वन्द्वसंघातागन्तुजः स्मृतः","text":"dakṣāpamānasaṃkruddharudra niḥ śvāsasambhavaḥ jvaro'ṣṭadhā pṛthagdvandvasaṃghātāgantujaḥ smṛtaḥ"},{"type":"verse","number":"3","sanskrit":"मिथ्याऽहारविहाराभ्यां दोषा ह्यामाशयाश्रयाः बहिर्निरस्य कोष्ठाग्निं ज्वरदाः स्यू रसानुगाः","text":"mithyā'hāravihārābhyāṃ doṣā hyāmāśayāśrayāḥ bahirnirasya koṣṭhāgniṃ jvaradāḥ syū rasānugāḥ"},{"type":"verse","number":"4","sanskrit":"श्रमोऽरतिर्विवर्णत्वं वैरस्यं नयनप्लवः इच्छाद्वेषौ मुहुश्चापि शीतवातातपादिषु","text":"śramo'ratirvivarṇatvaṃ vairasyaṃ nayanaplavaḥ icchādveṣau muhuścāpi śītavātātapādiṣu"},{"type":"verse","number":"5","sanskrit":"जृम्भाऽङ्गमर्दो गुरुता रोमहर्षोऽरुचिस्तमः अप्रहर्षश्च शीतं च भवत्युत्पत्स्यति ज्वरे","text":"jṛmbhā'ṅgamardo gurutā romaharṣo'rucistamaḥ apraharṣaśca śītaṃ ca bhavatyutpatsyati jvare"},{"type":"verse","number":"6","sanskrit":"सामान्यतो विशेषात्तु जृम्भाऽत्यर्थं समीरणात् पित्तान्नयनयोर्दाहः कफन्नान्नाभिनन्दनम्","text":"sāmānyato viśeṣāttu jṛmbhā'tyarthaṃ samīraṇāt pittānnayanayordāhaḥ kaphannānnābhinandanam"},{"type":"verse","number":"7","sanskrit":"रूपैरन्यतराभ्यां तु संसृष्टैर्द्वन्द्वजं विदुः","text":"rūpairanyatarābhyāṃ tu saṃsṛṣṭairdvandvajaṃ viduḥ"},{"type":"verse","number":"8","sanskrit":"सर्वलिङ्गसमावायः सर्वदोषप्रकोपजे","text":"sarvaliṅgasamāvāyaḥ sarvadoṣaprakopaje"},{"type":"verse","number":"9","sanskrit":"स्वेदावरोधः सन्तापः सर्वाङ्गग्रहणं तथा युगपद्यत्र रोगे तु स ज्वरो व्यपदिश्यते","text":"svedāvarodhaḥ santāpaḥ sarvāṅgagrahaṇaṃ tathā yugapadyatra roge tu sa jvaro vyapadiśyate"},{"type":"verse","number":"10","sanskrit":"रुणद्धि चाप्यपां धातून् यस्मात्तस्माज्ज्वरातुरः भवत्यत्युष्णगात्रश्च स्विद्यते न च सर्वशः","text":"ruṇaddhi cāpyapāṃ dhātūn yasmāttasmājjvarāturaḥ bhavatyatyuṣṇagātraśca svidyate na ca sarvaśaḥ"},{"type":"verse","number":"11","sanskrit":"अंशांशं यत्र दोषाणां विवेक्तुं नैव शक्नुयात् साधारणीं क्रियां तत्र विदध्यात्तु चिकित्सकः सामान्यतो ज्वरी पूर्वं निर्वाते निलये वसेत् निर्वातमायुषो वृद्धिमारोग्यं कुरुते यतः","text":"aṃśāṃśaṃ yatra doṣāṇāṃ vivektuṃ naiva śaknuyāt sādhāraṇīṃ kriyāṃ tatra vidadhyāttu cikitsakaḥ sāmānyato jvarī pūrvaṃ nirvāte nilaye vaset nirvātamāyuṣo vṛddhimārogyaṃ kurute yataḥ"},{"type":"verse","number":"12","sanskrit":"व्यजनस्यानिलस्तृष्णास्वेदमूर्च्छाश्रमापहः तालवृन्तभवो वातस्त्रिदोषशमनो मतः","text":"vyajanasyānilastṛṣṇāsvedamūrcchāśramāpahaḥ tālavṛntabhavo vātastridoṣaśamano mataḥ"},{"type":"verse","number":"13","sanskrit":"वंशव्यजनजः सोष्णो रक्तपित्तप्रकोपणः चामरो वस्त्रसम्भूतो मायूरो वेत्रजस्तथा एते दोषजितो वाताः स्निग्धा हृद्याः सुपूजिताः","text":"vaṃśavyajanajaḥ soṣṇo raktapittaprakopaṇaḥ cāmaro vastrasambhūto māyūro vetrajastathā ete doṣajito vātāḥ snigdhā hṛdyāḥ supūjitāḥ"},{"type":"verse","number":"14","sanskrit":"नवज्वरी भवेद् यत्नाद् गुरूष्णवसनावृतः यथर्त्तुपक्वपानीयं पिवेत्किञ्चिंन्निवारयन्","text":"navajvarī bhaved yatnād gurūṣṇavasanāvṛtaḥ yatharttupakvapānīyaṃ pivetkiñciṃnnivārayan"},{"type":"verse","number":"15","sanskrit":"विनाऽपि भेषजैर्व्याधिः पथ्यादेव निवर्तते न तु पथ्यविहीनस्य भेषजानां शतैरपि","text":"vinā'pi bheṣajairvyādhiḥ pathyādeva nivartate na tu pathyavihīnasya bheṣajānāṃ śatairapi"},{"type":"verse","number":"16","sanskrit":"परिषेकान्प्रदेहांश्च स्नेहान्संशोधनानि च दिवास्वप्नं व्यवायञ्च व्यायामं शिशिरं जलम् क्रोधप्रवातभोज्यांश्च वर्जयेत्तरुणज्वरी","text":"pariṣekānpradehāṃśca snehānsaṃśodhanāni ca divāsvapnaṃ vyavāyañca vyāyāmaṃ śiśiraṃ jalam krodhapravātabhojyāṃśca varjayettaruṇajvarī"},{"type":"verse","number":"17","sanskrit":"शोषं छर्दिं मदं मूर्च्छां भ्रमं तृष्णामरोचकम् प्राप्नोत्युपद्र वानेतान्परिषेकादिसेवनात्","text":"śoṣaṃ chardiṃ madaṃ mūrcchāṃ bhramaṃ tṛṣṇāmarocakam prāpnotyupadra vānetānpariṣekādisevanāt"},{"type":"verse","number":"18","sanskrit":"व्यायामाज्ज्वरसंबृद्धिर्व्यवायात्स्तम्भमूर्च्छनम् मृतिश्च स्नेहपानाद्यैर्मूर्च्छा च्छर्दिर्मदोऽरुचिः","text":"vyāyāmājjvarasaṃbṛddhirvyavāyātstambhamūrcchanam mṛtiśca snehapānādyairmūrcchā cchardirmado'ruciḥ"},{"type":"verse","number":"19","sanskrit":"गुर्वन्नभोजनात्स्वप्नाद्विष्टम्भो दोषकोपनम् अग्निसादः खरत्वञ्च स्रोतसां च प्रवर्त्तनम्","text":"gurvannabhojanātsvapnādviṣṭambho doṣakopanam agnisādaḥ kharatvañca srotasāṃ ca pravarttanam"},{"type":"verse","number":"20","sanskrit":"सज्वरो ज्वरमुक्तो वा विदाहीनि गुरूणि च असात्म्यान्नानि पानानि विरुद्धाध्यशनानि च","text":"sajvaro jvaramukto vā vidāhīni gurūṇi ca asātmyānnāni pānāni viruddhādhyaśanāni ca"},{"type":"verse","number":"21","sanskrit":"व्यायाममतिचेष्टां वाऽभ्यङ्गं स्नानञ्च वर्जयेत् तेन ज्वरः शमं याति शान्तश्च न पुनर्भवेत्","text":"vyāyāmamaticeṣṭāṃ vā'bhyaṅgaṃ snānañca varjayet tena jvaraḥ śamaṃ yāti śāntaśca na punarbhavet"},{"type":"verse","number":"22","sanskrit":"आमाशयस्थो हत्वाऽग्नि सामो मार्गान् पिधापयन् विदधाति ज्वरं दोषस्तस्माल्लङ्घनमाचरेत्","text":"āmāśayastho hatvā'gni sāmo mārgān pidhāpayan vidadhāti jvaraṃ doṣastasmāllaṅghanamācaret"},{"type":"verse","number":"23","sanskrit":"ज्वरादौ लङ्घनं प्रोक्तं ज्वरमध्ये तु पाचनम् ज्वरान्ते भेषजंदद्याज्ज्वरमुक्ते विरेचनम्","text":"jvarādau laṅghanaṃ proktaṃ jvaramadhye tu pācanam jvarānte bheṣajaṃdadyājjvaramukte virecanam"},{"type":"verse","number":"24","sanskrit":"त्रिविधं त्रिविधे दोषे तत्समीक्ष्य प्रयोजयेत् दोषेऽल्पे लङ्घनं पथ्यं मध्ये लङ्घनपाचनम् प्रभूते शोधनं तच्च मूलादुन्मूलयेन्मलान्","text":"trividhaṃ trividhe doṣe tatsamīkṣya prayojayet doṣe'lpe laṅghanaṃ pathyaṃ madhye laṅghanapācanam prabhūte śodhanaṃ tacca mūlādunmūlayenmalān"},{"type":"verse","number":"25","sanskrit":"तरुणं तु ज्वरं पूर्वं लङ्घनेन क्षयं नयेत् आमदोषमलिङ्गाद्वा लङ्घयेत्तं यथाविधि","text":"taruṇaṃ tu jvaraṃ pūrvaṃ laṅghanena kṣayaṃ nayet āmadoṣamaliṅgādvā laṅghayettaṃ yathāvidhi"},{"type":"verse","number":"26","sanskrit":"वातः पचति सप्ताहात्पित्तं तु दशभिर्दिनैः श्लेष्मा द्वादशभिर्घस्रैः पच्यते वदतां वर","text":"vātaḥ pacati saptāhātpittaṃ tu daśabhirdinaiḥ śleṣmā dvādaśabhirghasraiḥ pacyate vadatāṃ vara"},{"type":"verse","number":"27","sanskrit":"लङ्घनं लङ्घनीयस्तु कुर्याद्दोषानुरूपतः त्रिरात्रमेकरात्रं वाऽहोरात्रमथवा ज्वरे","text":"laṅghanaṃ laṅghanīyastu kuryāddoṣānurūpataḥ trirātramekarātraṃ vā'horātramathavā jvare"},{"type":"verse","number":"28","sanskrit":"निर्वातसेवनात्स्वेदाल्लङ्घनादुष्णवारिणः पानादामज्वरे क्षीणे पश्चादौषधमाचरेत्","text":"nirvātasevanātsvedāllaṅghanāduṣṇavāriṇaḥ pānādāmajvare kṣīṇe paścādauṣadhamācaret"},{"type":"verse","number":"29","sanskrit":"ज्वरादौ लङ्घनं प्रोक्तं ज्वरमध्ये तु पाचनम् ज्वरान्ते भेषजं दद्याज्ज्वरमुक्ते विरेचनम्","text":"jvarādau laṅghanaṃ proktaṃ jvaramadhye tu pācanam jvarānte bheṣajaṃ dadyājjvaramukte virecanam"},{"type":"verse","number":"30","sanskrit":"दोषशेषस्य पाकार्थमग्नेः सन्धुक्षणाय च लङ्घितश्चाप्यदोषश्चेद्यवागूपानमाचरेत्","text":"doṣaśeṣasya pākārthamagneḥ sandhukṣaṇāya ca laṅghitaścāpyadoṣaścedyavāgūpānamācaret"},{"type":"verse","number":"31","sanskrit":"शालिषष्टिकमुद्गानां यूषं वा शस्तमाचरेत् पञ्चकोलेन संसिद्धां यवागूं मध्यलङ्घने","text":"śāliṣaṣṭikamudgānāṃ yūṣaṃ vā śastamācaret pañcakolena saṃsiddhāṃ yavāgūṃ madhyalaṅghane"},{"type":"verse","number":"32","sanskrit":"अत्यर्थं लङ्घितं दृष्ट्वा तस्य संतर्पणं हितम् द्रा क्षादाडिमखर्जूरप्रियालैः सपरूषकैः","text":"atyarthaṃ laṅghitaṃ dṛṣṭvā tasya saṃtarpaṇaṃ hitam drā kṣādāḍimakharjūrapriyālaiḥ saparūṣakaiḥ"},{"type":"verse","number":"33","sanskrit":"तर्पणार्हस्य कर्त्तव्यं तर्पणं ज्वरशान्तये","text":"tarpaṇārhasya karttavyaṃ tarpaṇaṃ jvaraśāntaye"},{"type":"verse","number":"34","sanskrit":"लङ्घनेन क्षयं नीते दोषे सन्धुक्षितेऽनले विज्वरत्वं लघुत्वं च क्षुच्चैवास्योपजायते","text":"laṅghanena kṣayaṃ nīte doṣe sandhukṣite'nale vijvaratvaṃ laghutvaṃ ca kṣuccaivāsyopajāyate"},{"type":"verse","number":"35","sanskrit":"अनवस्थितदोषाग्नेर्लङ्घनं दोषपाचनम् ज्वरघ्नं दीपनं काङ्क्षारुचिलाघवकारकम्","text":"anavasthitadoṣāgnerlaṅghanaṃ doṣapācanam jvaraghnaṃ dīpanaṃ kāṅkṣārucilāghavakārakam"},{"type":"verse","number":"36","sanskrit":"वातमूत्रपुरीषाणां विसर्गे गात्रलाघवे हृदयोद्गारकण्ठास्यशुद्धौ तन्द्रा क्लमे गते","text":"vātamūtrapurīṣāṇāṃ visarge gātralāghave hṛdayodgārakaṇṭhāsyaśuddhau tandrā klame gate"},{"type":"verse","number":"37","sanskrit":"स्वेदे जाते रुचौ चापि क्षुत्पिपासासहोदये कृतं लङ्घनमादेश्यं निर्व्यथे चान्तरात्मनि","text":"svede jāte rucau cāpi kṣutpipāsāsahodaye kṛtaṃ laṅghanamādeśyaṃ nirvyathe cāntarātmani"},{"type":"verse","number":"38","sanskrit":"कफोत्क्लेशः सहृल्लासः ष्ठीवनं च मुहुर्मुहुः कण्ठास्यहृदयाशुद्धिस्तन्द्रा स्याद्धीनलङ्घने","text":"kaphotkleśaḥ sahṛllāsaḥ ṣṭhīvanaṃ ca muhurmuhuḥ kaṇṭhāsyahṛdayāśuddhistandrā syāddhīnalaṅghane"},{"type":"verse","number":"39","sanskrit":"पर्वभेदोऽङ्गमर्दश्च कासः शोषो मुखस्य च क्षुत्प्रणाशोऽरुचिस्तृष्णा दौर्बल्यं श्रोत्रनेत्रयोः","text":"parvabhedo'ṅgamardaśca kāsaḥ śoṣo mukhasya ca kṣutpraṇāśo'rucistṛṣṇā daurbalyaṃ śrotranetrayoḥ"},{"type":"verse","number":"40","sanskrit":"मनसः संभ्रमोऽभीक्ष्णमूर्ध्ववातस्तमो हृदि देहाग्निबलहानिश्च लङ्घनेऽतिकृते भवेत्","text":"manasaḥ saṃbhramo'bhīkṣṇamūrdhvavātastamo hṛdi dehāgnibalahāniśca laṅghane'tikṛte bhavet"},{"type":"verse","number":"41","sanskrit":"बलाविरोधिना चैनं लङ्घनेनोपपादयेत् बलाधिष्ठानमारोग्यं यदर्थोऽय क्रियाक्रमः","text":"balāvirodhinā cainaṃ laṅghanenopapādayet balādhiṣṭhānamārogyaṃ yadartho'ya kriyākramaḥ"},{"type":"verse","number":"42","sanskrit":"तद्धि मारुततृष्णाक्षुन्मुखशोषभ्रमान्वितः न कार्यं गुर्विणीबालवृद्धदुर्बलभीरुभिः न क्षयाध्वश्रमक्रोधकामशोषचिरज्वरी","text":"taddhi mārutatṛṣṇākṣunmukhaśoṣabhramānvitaḥ na kāryaṃ gurviṇībālavṛddhadurbalabhīrubhiḥ na kṣayādhvaśramakrodhakāmaśoṣacirajvarī"},{"type":"verse","number":"43","sanskrit":"अवश्यमेव कुर्वीत ज्वरी सामे समीरणे लङ्घनं ह्यामपाकार्थं न तदूर्ध्वं यथा कफे","text":"avaśyameva kurvīta jvarī sāme samīraṇe laṅghanaṃ hyāmapākārthaṃ na tadūrdhvaṃ yathā kaphe"},{"type":"verse","number":"44","sanskrit":"आहारस्य रसः सारो यो न पक्वोऽग्निलाघवात् आमसंज्ञाञ्च लभते बहुव्याधिसमाश्रयः","text":"āhārasya rasaḥ sāro yo na pakvo'gnilāghavāt āmasaṃjñāñca labhate bahuvyādhisamāśrayaḥ"},{"type":"verse","number":"45","sanskrit":"आममन्नरसं केचित् केचित्तु मलसञ्चयम् प्रथमां दोषदुष्टिं वा केचिदामं प्रचक्षते","text":"āmamannarasaṃ kecit kecittu malasañcayam prathamāṃ doṣaduṣṭiṃ vā kecidāmaṃ pracakṣate"},{"type":"verse","number":"46","sanskrit":"अविपक्वमसंसक्तं दुर्गन्धं बहुपिच्छिलम् सादनं सर्वगात्राणामाम इत्यभिशब्दितः","text":"avipakvamasaṃsaktaṃ durgandhaṃ bahupicchilam sādanaṃ sarvagātrāṇāmāma ityabhiśabditaḥ"},{"type":"verse","number":"47","sanskrit":"तेनामेन समायुक्ता दोषा दूष्याश्च तादृशाः तदुद्भवा आमयाश्च सामा इति बुधैः स्मृताः","text":"tenāmena samāyuktā doṣā dūṣyāśca tādṛśāḥ tadudbhavā āmayāśca sāmā iti budhaiḥ smṛtāḥ"},{"type":"verse","number":"48","sanskrit":"वायुः सामो विबन्धाग्नि सादतन्द्रा ऽन्त्रकूजनः वेदनाशोथनिस्तोदैः क्रमतोऽङ्गानि पीडयेत्","text":"vāyuḥ sāmo vibandhāgni sādatandrā 'ntrakūjanaḥ vedanāśothanistodaiḥ kramato'ṅgāni pīḍayet"},{"type":"verse","number":"49","sanskrit":"विचरेद् युगपच्चापि गृह्णाति कुपितो भृशम् स्नेहाद्यैर्वृद्धिमायाति मेघे सूर्य्योदये निशि","text":"vicared yugapaccāpi gṛhṇāti kupito bhṛśam snehādyairvṛddhimāyāti meghe sūryyodaye niśi"},{"type":"verse","number":"50","sanskrit":"निरामो विशदो रूक्षो निर्गन्धोऽत्यल्पवेदनः विपरीतगुणैः शान्तिं स्निग्धैर्याति विशेषतः","text":"nirāmo viśado rūkṣo nirgandho'tyalpavedanaḥ viparītaguṇaiḥ śāntiṃ snigdhairyāti viśeṣataḥ"},{"type":"verse","number":"51","sanskrit":"पित्तं सामं भवेदम्लं दुर्गन्धं हरितं गुरु अम्लिकाकण्ठहृद्दाह करं श्यावं तथा स्थिरम्","text":"pittaṃ sāmaṃ bhavedamlaṃ durgandhaṃ haritaṃ guru amlikākaṇṭhahṛddāha karaṃ śyāvaṃ tathā sthiram"},{"type":"verse","number":"52","sanskrit":"निरामं पित्तमाताम्रमत्युष्णं कटुकं सरम् दुर्गन्धि रुचिकृद् वह्निबलवर्धनमीरितम्","text":"nirāmaṃ pittamātāmramatyuṣṇaṃ kaṭukaṃ saram durgandhi rucikṛd vahnibalavardhanamīritam"},{"type":"verse","number":"53","sanskrit":"आविलस्तन्तुलः स्त्यानः कण्ठदेशे च तिष्ठति सामो बलासो दुर्गन्धस्तृट्क्षुधोरुपघातकृत्","text":"āvilastantulaḥ styānaḥ kaṇṭhadeśe ca tiṣṭhati sāmo balāso durgandhastṛṭkṣudhorupaghātakṛt"},{"type":"verse","number":"54","sanskrit":"श्लेष्मा निरामो निर्गन्धः फेनवांश्छेदवानपि भवेत् स पिण्डितः पाण्डु रास्यवैरस्यनाशकृत्","text":"śleṣmā nirāmo nirgandhaḥ phenavāṃśchedavānapi bhavet sa piṇḍitaḥ pāṇḍu rāsyavairasyanāśakṛt"},{"type":"verse","number":"55","sanskrit":"आलस्यतन्द्रा हृदयाविशुद्धि दोषप्रवृत्त्याविलमूत्रताभिः गुरूदरत्वारुचिसुप्तताभिरामान्वितं व्याधिमुदाहरन्ति","text":"ālasyatandrā hṛdayāviśuddhi doṣapravṛttyāvilamūtratābhiḥ gurūdaratvārucisuptatābhirāmānvitaṃ vyādhimudāharanti"},{"type":"verse","number":"56","sanskrit":"आमं जयेल्लङ्घनकोष्णपेया लघ्वन्नसूपौदनतिक्तयूषैः विरूक्षणस्वेदनपाचनैश्च संशोधनैरूर्ध्वमधस्तथैव","text":"āmaṃ jayellaṅghanakoṣṇapeyā laghvannasūpaudanatiktayūṣaiḥ virūkṣaṇasvedanapācanaiśca saṃśodhanairūrdhvamadhastathaiva"},{"type":"verse","number":"57","sanskrit":"तृषितो मोहमायाति मोहात् प्राणान् विमुञ्चति अतः सर्वास्ववस्थासु न क्वचिद् वारि वर्जयेत्","text":"tṛṣito mohamāyāti mohāt prāṇān vimuñcati ataḥ sarvāsvavasthāsu na kvacid vāri varjayet"},{"type":"verse","number":"58","sanskrit":"तृष्णा गरीयसी घोरा सद्यः प्राणविनाशिनी तस्माद्देयं तृषाऽत्ताय पानीयम्प्राणधारणम्","text":"tṛṣṇā garīyasī ghorā sadyaḥ prāṇavināśinī tasmāddeyaṃ tṛṣā'ttāya pānīyamprāṇadhāraṇam"},{"type":"verse","number":"59","sanskrit":"नवज्वरे प्रतिश्याये पार्श्वशूले गलग्रहे सद्यः शुद्धौ तथाऽध्माने व्याधौ वातकफोद्भवे","text":"navajvare pratiśyāye pārśvaśūle galagrahe sadyaḥ śuddhau tathā'dhmāne vyādhau vātakaphodbhave"},{"type":"verse","number":"60","sanskrit":"अरुचिग्रहणीगुल्म श्वासकासेषु विद्र धौ हिक्कायां स्नेहपाने च शीतं वारि विवर्जयेत्","text":"arucigrahaṇīgulma śvāsakāseṣu vidra dhau hikkāyāṃ snehapāne ca śītaṃ vāri vivarjayet"},{"type":"verse","number":"61","sanskrit":"सेव्यमानेन शीतेन ज्वरस्तोयेन वर्द्धते","text":"sevyamānena śītena jvarastoyena varddhate"},{"type":"verse","number":"62","sanskrit":"क्वाथ्यमानं तु निर्वेगं निष्फेनं निर्मलं तथा अर्द्धावशिष्टं यत् तोयं तदुष्णोदकमुच्यते","text":"kvāthyamānaṃ tu nirvegaṃ niṣphenaṃ nirmalaṃ tathā arddhāvaśiṣṭaṃ yat toyaṃ taduṣṇodakamucyate"},{"type":"verse","number":"63","sanskrit":"ज्वरकासकफश्वास पित्तवाताममेदसाम् नाशनं पाचनञ्चैव पथ्यमुष्णोदकं सदा","text":"jvarakāsakaphaśvāsa pittavātāmamedasām nāśanaṃ pācanañcaiva pathyamuṣṇodakaṃ sadā"},{"type":"verse","number":"64","sanskrit":"त्रिपादशेषं सलिलं ग्रीष्मे शरदि शस्यते हिमेऽद्धशेषं शिशिरे तथा वर्षावसन्तयोः","text":"tripādaśeṣaṃ salilaṃ grīṣme śaradi śasyate hime'ddhaśeṣaṃ śiśire tathā varṣāvasantayoḥ"},{"type":"verse","number":"65","sanskrit":"निदाघे त्वर्द्धपादोनं पादहीनन्तु शारदम् शिशिरे च वसन्ते च हिमे चार्द्धावशेषितम्","text":"nidāghe tvarddhapādonaṃ pādahīnantu śāradam śiśire ca vasante ca hime cārddhāvaśeṣitam"},{"type":"verse","number":"66","sanskrit":"अष्टमांशावशेषन्तु वारि वर्षासु शस्यते इति केचिद् बुधाः प्राहुर्जेज्जटागमदर्शनात्","text":"aṣṭamāṃśāvaśeṣantu vāri varṣāsu śasyate iti kecid budhāḥ prāhurjejjaṭāgamadarśanāt"},{"type":"verse","number":"67","sanskrit":"पक्षयोस्त्रिषु वेदेषु बाणेष्वङ्गेषु सप्तसु एषु भागावशेषं स्यादम्बु वर्षाऽदिषु क्रमात्","text":"pakṣayostriṣu vedeṣu bāṇeṣvaṅgeṣu saptasu eṣu bhāgāvaśeṣaṃ syādambu varṣā'diṣu kramāt"},{"type":"verse","number":"68","sanskrit":"तत्पादहीनं पित्तघ्नमर्द्धहीनन्तु वातनुत् त्रिपादहीनं श्लेष्मघ्नं संग्राह्यग्निप्रदं लघु","text":"tatpādahīnaṃ pittaghnamarddhahīnantu vātanut tripādahīnaṃ śleṣmaghnaṃ saṃgrāhyagnipradaṃ laghu"},{"type":"verse","number":"69","sanskrit":"पादशेषं तु यत्तोयमारोग्याम्बु तदुच्यते आरोग्याम्बु सदा पथ्यं कासश्वासकफापहम्","text":"pādaśeṣaṃ tu yattoyamārogyāmbu taducyate ārogyāmbu sadā pathyaṃ kāsaśvāsakaphāpaham"},{"type":"verse","number":"70","sanskrit":"सद्योज्वरहरं ग्राहि दीपनं पाचनं लघु आनाहपाण्डुशूलार्शो गुल्मशोथोदरापहम्","text":"sadyojvaraharaṃ grāhi dīpanaṃ pācanaṃ laghu ānāhapāṇḍuśūlārśo gulmaśothodarāpaham"},{"type":"verse","number":"71","sanskrit":"हेमन्ते शिशिरे चाम्बु सारसं वा तडागजम् वसन्तग्रीष्मयोः कौप्यं वाप्यं वा नैर्झरं हितम्","text":"hemante śiśire cāmbu sārasaṃ vā taḍāgajam vasantagrīṣmayoḥ kaupyaṃ vāpyaṃ vā nairjharaṃ hitam"},{"type":"verse","number":"72","sanskrit":"नादेयं वारि नादेयं वसन्तग्रीष्मयोर्बुधः विषवत्पत्रपुष्पादि दुष्टनिर्झरयोगतः","text":"nādeyaṃ vāri nādeyaṃ vasantagrīṣmayorbudhaḥ viṣavatpatrapuṣpādi duṣṭanirjharayogataḥ"},{"type":"verse","number":"73","sanskrit":"आद्भिदं चान्तरिक्षं वा कौप्यं वा प्रावृषि स्मृतम् शस्तं शरदि नादेयं नीरमंशूदकं परम्","text":"ādbhidaṃ cāntarikṣaṃ vā kaupyaṃ vā prāvṛṣi smṛtam śastaṃ śaradi nādeyaṃ nīramaṃśūdakaṃ param"},{"type":"verse","number":"74","sanskrit":"दिवा रविकरैर्जुष्टं निशि शीतकरांशुभिः ज्ञेयमंशूदकं नाम स्निग्धं दोषत्रयापहम्","text":"divā ravikarairjuṣṭaṃ niśi śītakarāṃśubhiḥ jñeyamaṃśūdakaṃ nāma snigdhaṃ doṣatrayāpaham"},{"type":"verse","number":"75","sanskrit":"अनभिष्यन्दि निर्दोषञ्चान्तरिक्षजलोपमम् बल्यं रसायनं मेध्यं शीतं लघु सुधासमम्","text":"anabhiṣyandi nirdoṣañcāntarikṣajalopamam balyaṃ rasāyanaṃ medhyaṃ śītaṃ laghu sudhāsamam"},{"type":"verse","number":"76","sanskrit":"शरद्यगस्तेरुदयादखिलं सलिलं हितम्","text":"śaradyagasterudayādakhilaṃ salilaṃ hitam"},{"type":"verse","number":"77","sanskrit":"कार्त्तिके मार्गशीर्षे च जलमात्रं प्रशस्यते","text":"kārttike mārgaśīrṣe ca jalamātraṃ praśasyate"},{"type":"verse","number":"78","sanskrit":"दाहातिसारपित्तास्त्र मूर्च्छामद्यविषार्त्तिषु मूत्र कृच्छ्रे पाण्डुरोगे तृष्णाच्छर्दिश्रमेषु च मद्यपानसभुद्भूते रोगे पित्तोत्थिते तथा सन्निपातसमुत्थेषु शृतशीतं प्रशस्यते","text":"dāhātisārapittāstra mūrcchāmadyaviṣārttiṣu mūtra kṛcchre pāṇḍuroge tṛṣṇācchardiśrameṣu ca madyapānasabhudbhūte roge pittotthite tathā sannipātasamuttheṣu śṛtaśītaṃ praśasyate"},{"type":"verse","number":"79","sanskrit":"शृताम्बु तत्त्रिदोषघ्नं तदन्तर्बाष्पशीतलम् अरूक्षमनभिष्यन्दि कृमितृड्ज्वरहृल्लघु धारापातेन विष्टम्भि दुर्जरं पवनाहतम्","text":"śṛtāmbu tattridoṣaghnaṃ tadantarbāṣpaśītalam arūkṣamanabhiṣyandi kṛmitṛḍjvarahṛllaghu dhārāpātena viṣṭambhi durjaraṃ pavanāhatam"},{"type":"verse","number":"80","sanskrit":"भिनत्ति श्लेष्मसङ्घातं मारुतं चापकर्षति अजीर्णं जरयत्याशु पीतमुष्णोदकं निशि","text":"bhinatti śleṣmasaṅghātaṃ mārutaṃ cāpakarṣati ajīrṇaṃ jarayatyāśu pītamuṣṇodakaṃ niśi"},{"type":"verse","number":"81","sanskrit":"दिवा शृतंपयो रात्रौ गुरुतामधिगच्छति रात्रौ शृतं दिवा पीतं गुरुत्वमधिगच्छति","text":"divā śṛtaṃpayo rātrau gurutāmadhigacchati rātrau śṛtaṃ divā pītaṃ gurutvamadhigacchati"},{"type":"verse","number":"82","sanskrit":"तत्तु पर्य्युषितं वह्निगुणोत्सृष्टं त्रिदोषकृत् गुर्वम्लपाकं विष्टम्भि सर्वरोगेषु निन्दितम्","text":"tattu paryyuṣitaṃ vahniguṇotsṛṣṭaṃ tridoṣakṛt gurvamlapākaṃ viṣṭambhi sarvarogeṣu ninditam"},{"type":"verse","number":"83","sanskrit":"शृतशीतं पुनस्तप्तं तोयं विषसमं भवेत् निर्य्यूहोऽपि तथा शीतः पुनस्तप्तो विषोपमः","text":"śṛtaśītaṃ punastaptaṃ toyaṃ viṣasamaṃ bhavet niryyūho'pi tathā śītaḥ punastapto viṣopamaḥ"},{"type":"verse","number":"84","sanskrit":"अष्टमेनांशशेषेण चतुर्थेनार्द्धकेन वा अथ वा क्वथनेनैवसिद्धमुष्णोदकं वदेत्","text":"aṣṭamenāṃśaśeṣeṇa caturthenārddhakena vā atha vā kvathanenaivasiddhamuṣṇodakaṃ vadet"},{"type":"verse","number":"85","sanskrit":"श्लेष्मानिलाममेदोघ्नं दीपनं बस्तिशोधनम् श्वासकासज्वरहरं पीतमुष्णोदकं निशि","text":"śleṣmānilāmamedoghnaṃ dīpanaṃ bastiśodhanam śvāsakāsajvaraharaṃ pītamuṣṇodakaṃ niśi"},{"type":"verse","number":"86","sanskrit":"रात्रावुष्णोदकञ्च तप्तमेव पिबेदित्याह उष्णं तदग्निजननं लघ्वच्छं बस्तिशोधनम्","text":"rātrāvuṣṇodakañca taptameva pibedityāha uṣṇaṃ tadagnijananaṃ laghvacchaṃ bastiśodhanam"},{"type":"verse","number":"87","sanskrit":"पार्श्वरुक्पीनसाध्मानहिक्काऽनिलकफापहम् शस्तं तृट्श्वासशूलेषु सद्यःशुद्धौ नवज्वरे","text":"pārśvarukpīnasādhmānahikkā'nilakaphāpaham śastaṃ tṛṭśvāsaśūleṣu sadyaḥśuddhau navajvare"},{"type":"verse","number":"88","sanskrit":"मूर्च्छापित्तोष्णदाहेषु विषे रक्ते मदात्यये भ्रमश्रमपरीतेषु तमके श्वयथौ तथा","text":"mūrcchāpittoṣṇadāheṣu viṣe rakte madātyaye bhramaśramaparīteṣu tamake śvayathau tathā"},{"type":"verse","number":"89","sanskrit":"धूमोद्गारे विदग्धेऽन्ने शोषे च मुखकण्ठयोः ऊर्ध्वगे रक्तपित्ते च शीतलाम्बु प्रशस्यते","text":"dhūmodgāre vidagdhe'nne śoṣe ca mukhakaṇṭhayoḥ ūrdhvage raktapitte ca śītalāmbu praśasyate"},{"type":"verse","number":"90","sanskrit":"आमं जलं पाकमुपैति यामं पक्वं पुनः शीतलमर्द्धयामम् पक्वं कदुष्णञ्च ततोऽद्धकालात् त्रयः सुपीतस्य जलस्य पाके","text":"āmaṃ jalaṃ pākamupaiti yāmaṃ pakvaṃ punaḥ śītalamarddhayāmam pakvaṃ kaduṣṇañca tato'ddhakālāt trayaḥ supītasya jalasya pāke"},{"type":"verse","number":"91","sanskrit":"पित्तमद्यविषार्त्तेषु तिक्तकैः शृतशीतलम्","text":"pittamadyaviṣārtteṣu tiktakaiḥ śṛtaśītalam"},{"type":"verse","number":"92","sanskrit":"मुस्तपर्पटकोदीच्यच्छत्राऽख्योशीरचन्दनैः शृतं शीतं जलं दद्यात्तृड्दाहज्वरशान्तये","text":"mustaparpaṭakodīcyacchatrā'khyośīracandanaiḥ śṛtaṃ śītaṃ jalaṃ dadyāttṛḍdāhajvaraśāntaye"},{"type":"verse","number":"93","sanskrit":"दिवास्वापं न कुर्वीत यतोऽसौ स्यात्कफावहः ग्रींष्मवर्ज्येषु कालेषु दिवास्वापो निषिध्यते","text":"divāsvāpaṃ na kurvīta yato'sau syātkaphāvahaḥ grīṃṣmavarjyeṣu kāleṣu divāsvāpo niṣidhyate"},{"type":"verse","number":"94","sanskrit":"उचितो हि दिवास्वापो नित्यं येषां शरीरिणाम् वातादयः प्रकुप्यन्ति तेषामस्वपतां दिवा","text":"ucito hi divāsvāpo nityaṃ yeṣāṃ śarīriṇām vātādayaḥ prakupyanti teṣāmasvapatāṃ divā"},{"type":"verse","number":"95","sanskrit":"व्यायामप्रमदाऽध्ववाहनरतान् क्लान्तानतीसारिणः शूलश्वासवमीतृषापरिगतान् हिक्कामरुत्पीडितान् क्षीणान्क्षीणकफाञ्छिशून्मदहतान्वृद्धांस्तथाऽजीर्णिनो रात्रौ जागरितान्नरान्निरशनान्कामं दिवा स्वापयेत्","text":"vyāyāmapramadā'dhvavāhanaratān klāntānatīsāriṇaḥ śūlaśvāsavamītṛṣāparigatān hikkāmarutpīḍitān kṣīṇānkṣīṇakaphāñchiśūnmadahatānvṛddhāṃstathā'jīrṇino rātrau jāgaritānnarānniraśanānkāmaṃ divā svāpayet"},{"type":"verse","number":"96","sanskrit":"वातिकः सप्तरात्रेण दशरात्रेण पैत्तिकः श्लैष्मिको द्वादशाहेन ज्वरः पाकमुपैति हि","text":"vātikaḥ saptarātreṇa daśarātreṇa paittikaḥ ślaiṣmiko dvādaśāhena jvaraḥ pākamupaiti hi"},{"type":"verse","number":"97","sanskrit":"आ सप्तरात्रात्तरुणं ज्वरमाहुर्मनीषिणः द्वादशाहमभिव्याप्य मध्यं जीर्णं ततः परम्","text":"ā saptarātrāttaruṇaṃ jvaramāhurmanīṣiṇaḥ dvādaśāhamabhivyāpya madhyaṃ jīrṇaṃ tataḥ param"},{"type":"verse","number":"98","sanskrit":"वातिके सप्तरात्रेण दशरात्रेण पैत्तिके श्लैष्मिके द्वादशाहेन ज्वरे युञ्जीत भेषजम्","text":"vātike saptarātreṇa daśarātreṇa paittike ślaiṣmike dvādaśāhena jvare yuñjīta bheṣajam"},{"type":"verse","number":"99","sanskrit":"ज्ञेयः पञ्चविधः कालो भैषज्यग्रहणे नृणाम्","text":"jñeyaḥ pañcavidhaḥ kālo bhaiṣajyagrahaṇe nṛṇām"},{"type":"verse","number":"100","sanskrit":"तत्राऽनुक्ते प्रभातं स्यात्कषायेषु विशेषतः मुख्यभैषज्यसम्बन्धो निषिद्धस्तरुणज्वरे","text":"tatrā'nukte prabhātaṃ syātkaṣāyeṣu viśeṣataḥ mukhyabhaiṣajyasambandho niṣiddhastaruṇajvare"},{"type":"verse","number":"101","sanskrit":"तोयपेयाऽदिसंस्कारेर्निर्दोषं तत्र भेषजम्","text":"toyapeyā'disaṃskārernirdoṣaṃ tatra bheṣajam"},{"type":"verse","number":"102","sanskrit":"दोषा वृद्धाः कषायेण स्तम्भितास्तरुणज्वरे स्तभ्यन्ते न विपच्यन्ते कुर्वन्ति विषमज्वरम्","text":"doṣā vṛddhāḥ kaṣāyeṇa stambhitāstaruṇajvare stabhyante na vipacyante kurvanti viṣamajvaram"},{"type":"verse","number":"103","sanskrit":"न च्यवन्ते न पच्यन्ते कषायैः स्तम्भिता मलाः तिर्यग्विमार्गगा वाते घोरं कुर्युर्नवज्वरम्","text":"na cyavante na pacyante kaṣāyaiḥ stambhitā malāḥ tiryagvimārgagā vāte ghoraṃ kuryurnavajvaram"},{"type":"verse","number":"104","sanskrit":"अनवस्थितदोषाणां वमनं तरुणज्वरे हृद्रो गं श्वासमानाहं मोहं च कुरुते भृशम्","text":"anavasthitadoṣāṇāṃ vamanaṃ taruṇajvare hṛdro gaṃ śvāsamānāhaṃ mohaṃ ca kurute bhṛśam"},{"type":"verse","number":"105","sanskrit":"सद्योभुक्तस्य वा जाते ज्वरे सन्तर्पणोत्थिते वमनं वमनार्हस्य शस्तमित्याह वाग्भटः","text":"sadyobhuktasya vā jāte jvare santarpaṇotthite vamanaṃ vamanārhasya śastamityāha vāgbhaṭaḥ"},{"type":"verse","number":"106","sanskrit":"पाययेदातुरं सामं पाचनं सप्तमे दिने शमनेनाथ वा दृष्ट्वा निरामं तमुपाचरेत्","text":"pāyayedāturaṃ sāmaṃ pācanaṃ saptame dine śamanenātha vā dṛṣṭvā nirāmaṃ tamupācaret"},{"type":"verse","number":"107","sanskrit":"कृशं चैवाल्पदोषञ्च शमनीयैरुपाचरेत्","text":"kṛśaṃ caivālpadoṣañca śamanīyairupācaret"},{"type":"verse","number":"108","sanskrit":"नागरं देवकाष्ठञ्च ध्यामकं बृहतीद्वयम् दद्यात्पाचनकं पूर्वं ज्वरितेभ्यो ज्वरापहम्","text":"nāgaraṃ devakāṣṭhañca dhyāmakaṃ bṛhatīdvayam dadyātpācanakaṃ pūrvaṃ jvaritebhyo jvarāpaham"},{"type":"verse","number":"109","sanskrit":"अथ संशमनीयानि कषायाणि निबोध मे सर्वज्वरेषु देयानि यानि वैद्येन जानता","text":"atha saṃśamanīyāni kaṣāyāṇi nibodha me sarvajvareṣu deyāni yāni vaidyena jānatā"},{"type":"verse","number":"110","sanskrit":"बृश्चीरो विश्ववर्षाभूः पयः सोदकमेव च पचेत्क्षीरावशेषं तत्पेयं सर्वज्वरापहम्","text":"bṛścīro viśvavarṣābhūḥ payaḥ sodakameva ca pacetkṣīrāvaśeṣaṃ tatpeyaṃ sarvajvarāpaham"},{"type":"verse","number":"111","sanskrit":"उदकाद् द्विगुणं क्षीरं शिंशपोशीरमेव च तत्क्षीरशेषं क्वथितं पेयं सर्वज्वरापहम्","text":"udakād dviguṇaṃ kṣīraṃ śiṃśapośīrameva ca tatkṣīraśeṣaṃ kvathitaṃ peyaṃ sarvajvarāpaham"},{"type":"verse","number":"112","sanskrit":"गुडूचीधान्यकारिष्टं पद्मकं रक्तचन्दनम् एषां क्वाथः सुप्रसिद्धः सर्वज्वरहरः स्मृतः दीपनो दाहहृल्लासतृष्णाच्छर्द्यरुचीर्हरेत्","text":"guḍūcīdhānyakāriṣṭaṃ padmakaṃ raktacandanam eṣāṃ kvāthaḥ suprasiddhaḥ sarvajvaraharaḥ smṛtaḥ dīpano dāhahṛllāsatṛṣṇācchardyarucīrharet"},{"type":"verse","number":"113","sanskrit":"छर्दिमूर्च्छामदश्वासभ्रमतृड्विषमज्वरान् संशोधनस्य पानेन प्राप्नोति तरुणज्वरी","text":"chardimūrcchāmadaśvāsabhramatṛḍviṣamajvarān saṃśodhanasya pānena prāpnoti taruṇajvarī"},{"type":"verse","number":"114","sanskrit":"रोगे शोधनसाध्ये तु यं विद्याद् दोषदुर्बलम् तं समीक्ष्य भिषक्कुर्याद् दोषप्रच्यावनं मृदु","text":"roge śodhanasādhye tu yaṃ vidyād doṣadurbalam taṃ samīkṣya bhiṣakkuryād doṣapracyāvanaṃ mṛdu"},{"type":"verse","number":"115","sanskrit":"सद्योज्वरे विषेऽजीर्णे मन्देऽग्नावुदरे तथा स्तन्यरोगे च हृद्रो गे कासश्वासेषुवामयेत्","text":"sadyojvare viṣe'jīrṇe mande'gnāvudare tathā stanyaroge ca hṛdro ge kāsaśvāseṣuvāmayet"},{"type":"verse","number":"116","sanskrit":"जीर्णज्वरगरच्छर्दिगुल्मप्लीहोदरेषु च शूले शोथे मूत्रघाते कृमिरोगे विरेचयेत्","text":"jīrṇajvaragaracchardigulmaplīhodareṣu ca śūle śothe mūtraghāte kṛmiroge virecayet"},{"type":"verse","number":"117","sanskrit":"चले दोषे मृदौ कोष्ठे नेक्षेत्तत्र बलं नृणाम् अव्यापद् दुर्बलस्यापि शोधनं हि तदा भवेत्","text":"cale doṣe mṛdau koṣṭhe nekṣettatra balaṃ nṛṇām avyāpad durbalasyāpi śodhanaṃ hi tadā bhavet"},{"type":"verse","number":"118","sanskrit":"पक्वोऽप्यनिर्हृतो दोषो देहे तिष्ठन्महात्ययम् विषमं वा ज्वरं कुर्याद् बलव्यापदमेव वा","text":"pakvo'pyanirhṛto doṣo dehe tiṣṭhanmahātyayam viṣamaṃ vā jvaraṃ kuryād balavyāpadameva vā"},{"type":"verse","number":"119","sanskrit":"आरग्वधग्रन्थिकमुस्ततिक्ताहरीतकीभिः क्वथितः कषायः सामे सशूले कफवातयुक्ते ज्वरे हितो दीपनपाचनश्च","text":"āragvadhagranthikamustatiktāharītakībhiḥ kvathitaḥ kaṣāyaḥ sāme saśūle kaphavātayukte jvare hito dīpanapācanaśca"},{"type":"verse","number":"120","sanskrit":"इत्यारग्वधादिः क्वाथः पथ्याऽरग्वधतिक्तात्रिवृदामलकैः शृतं तोयम् पाचनसारकमुक्तं मुनिभिर्जीर्णज्वरे सामे इत्यारोग्यपञ्चकद्वयम्","text":"ityāragvadhādiḥ kvāthaḥ pathyā'ragvadhatiktātrivṛdāmalakaiḥ śṛtaṃ toyam pācanasārakamuktaṃ munibhirjīrṇajvare sāme ityārogyapañcakadvayam"},{"type":"verse","number":"121","sanskrit":"अनन्ता बालकं मुस्तं नागरं कटुरोहिणी पिष्ट्वा सुखाम्बुना कल्कं पाययेदक्षसम्मितम्","text":"anantā bālakaṃ mustaṃ nāgaraṃ kaṭurohiṇī piṣṭvā sukhāmbunā kalkaṃ pāyayedakṣasammitam"},{"type":"verse","number":"122","sanskrit":"कल्कः स्वल्पेन कालेन हन्यात्सर्वज्वरामयान् विदध्यात्कोष्ठसंशुद्धिं दीपयेच्च हुताशनम्","text":"kalkaḥ svalpena kālena hanyātsarvajvarāmayān vidadhyātkoṣṭhasaṃśuddhiṃ dīpayecca hutāśanam"},{"type":"verse","number":"123","sanskrit":"पीताम्बुर्लङ्घनक्षीणो जीर्णो भुक्तः पिपासितः न पिबेदौषधं जन्तुः संशोधनमथेतरत्","text":"pītāmburlaṅghanakṣīṇo jīrṇo bhuktaḥ pipāsitaḥ na pibedauṣadhaṃ jantuḥ saṃśodhanamathetarat"},{"type":"verse","number":"124","sanskrit":"त्रिफला रजनीयुग्मं कण्टकारीयुगं शटी त्रिकटु ग्रन्थिकं मूर्वा गुडूची धन्वयासकः","text":"triphalā rajanīyugmaṃ kaṇṭakārīyugaṃ śaṭī trikaṭu granthikaṃ mūrvā guḍūcī dhanvayāsakaḥ"},{"type":"verse","number":"125","sanskrit":"कटुका पर्पटो मुस्तं त्रायमाणा च बालकम् निम्बः पुष्करमूलञ्च मधुयष्टी च वत्सकः","text":"kaṭukā parpaṭo mustaṃ trāyamāṇā ca bālakam nimbaḥ puṣkaramūlañca madhuyaṣṭī ca vatsakaḥ"},{"type":"verse","number":"126","sanskrit":"यवानीन्द्र्यवो भार्गी शिग्रुबीजं सुराष्ट्रजा वचात्वक्पद्मकोशीरचन्दनातिविषाबलाः","text":"yavānīndryavo bhārgī śigrubījaṃ surāṣṭrajā vacātvakpadmakośīracandanātiviṣābalāḥ"},{"type":"verse","number":"127","sanskrit":"शालिपर्णी पृश्निपर्णी विडङ्गं तगरं तथा चित्रकं देवकाष्ठञ्च चव्यं पत्रं पटोलजम्","text":"śāliparṇī pṛśniparṇī viḍaṅgaṃ tagaraṃ tathā citrakaṃ devakāṣṭhañca cavyaṃ patraṃ paṭolajam"},{"type":"verse","number":"128","sanskrit":"जीवकर्षभकौ चैव लवङ्गं वंशलोचनम् पुण्डरीकञ्च काकोली पत्रकं जातिपत्रकम्","text":"jīvakarṣabhakau caiva lavaṅgaṃ vaṃśalocanam puṇḍarīkañca kākolī patrakaṃ jātipatrakam"},{"type":"verse","number":"129","sanskrit":"तालीसपत्रमेतानि समभागानि चूर्णयेत् अर्द्धांशं सर्वचूर्णस्य किरातं प्रक्षिपेत्सुधीः","text":"tālīsapatrametāni samabhāgāni cūrṇayet arddhāṃśaṃ sarvacūrṇasya kirātaṃ prakṣipetsudhīḥ"},{"type":"verse","number":"130","sanskrit":"एतत्सुदर्शनं नाम चूर्णं दोषत्रयापहम् ज्वरांश्च निखिलान् हन्ति नात्र कार्या विचारणा","text":"etatsudarśanaṃ nāma cūrṇaṃ doṣatrayāpaham jvarāṃśca nikhilān hanti nātra kāryā vicāraṇā"},{"type":"verse","number":"131","sanskrit":"दोषजागन्तुकांश्चापि धातुस्थान्विषमज्वरान् सन्निपातोद्भवांश्चापि मानसानपि नाशयेत्","text":"doṣajāgantukāṃścāpi dhātusthānviṣamajvarān sannipātodbhavāṃścāpi mānasānapi nāśayet"},{"type":"verse","number":"132","sanskrit":"शीतादीनपि दाहादीन्मेहं तन्द्रां भ्रमं तृषाम् कासं श्वासञ्च पाण्डुञ्च हृद्रो गं कामलामपि","text":"śītādīnapi dāhādīnmehaṃ tandrāṃ bhramaṃ tṛṣām kāsaṃ śvāsañca pāṇḍuñca hṛdro gaṃ kāmalāmapi"},{"type":"verse","number":"133","sanskrit":"त्रिकपृष्ठकटीजानुपार्श्वशूलं निवारयेत् शीताम्बुना पिबेदेतत्सर्वज्वरनिवृत्तये","text":"trikapṛṣṭhakaṭījānupārśvaśūlaṃ nivārayet śītāmbunā pibedetatsarvajvaranivṛttaye"},{"type":"verse","number":"134","sanskrit":"सुदर्शनं यथा चक्रं दानवानां विनाशनम् तथा ज्वराणां सर्वेषां चूर्णमेतत्प्रणाशनम्","text":"sudarśanaṃ yathā cakraṃ dānavānāṃ vināśanam tathā jvarāṇāṃ sarveṣāṃ cūrṇametatpraṇāśanam"},{"type":"verse","number":"135","sanskrit":"निम्बपत्रवराव्योषयवानी लवणत्रयम् क्षारो दिग्वह्निरामेषुत्रिनेत्रान् क्रमतॐऽशकान्","text":"nimbapatravarāvyoṣayavānī lavaṇatrayam kṣāro digvahnirāmeṣutrinetrān kramataoṃ'śakān"},{"type":"verse","number":"136","sanskrit":"सर्वमेकीकृतं चूर्णं प्रत्यूषे भक्षयेन्नरः एकाहिकं द्व्याहिकञ्च तथा त्रिदिवसज्वरम्","text":"sarvamekīkṛtaṃ cūrṇaṃ pratyūṣe bhakṣayennaraḥ ekāhikaṃ dvyāhikañca tathā tridivasajvaram"},{"type":"verse","number":"137","sanskrit":"चातुर्थिकं महाघोरं सततं सन्ततं दिवा धातुस्थं च त्रिदोषोत्थं ज्वरं हन्ति नसंशयम्","text":"cāturthikaṃ mahāghoraṃ satataṃ santataṃ divā dhātusthaṃ ca tridoṣotthaṃ jvaraṃ hanti nasaṃśayam"},{"type":"verse","number":"138","sanskrit":"इति निम्बादिचूर्णम् शटी निशाद्वयं शुण्ठी दारु पुष्करमूलकम् एला गुडूची कटुका पर्पटश्च यवासकः शृङ्गी किराततिक्तञ्च दशमूली तथैव च","text":"iti nimbādicūrṇam śaṭī niśādvayaṃ śuṇṭhī dāru puṣkaramūlakam elā guḍūcī kaṭukā parpaṭaśca yavāsakaḥ śṛṅgī kirātatiktañca daśamūlī tathaiva ca"},{"type":"verse","number":"139","sanskrit":"क्वाथमेषां पिबेत्कोष्णं सिन्धुचूर्णयुतं नरः ज्वरान्सर्वान्द्रुतं हन्ति नात्र कार्या विचारणा","text":"kvāthameṣāṃ pibetkoṣṇaṃ sindhucūrṇayutaṃ naraḥ jvarānsarvāndrutaṃ hanti nātra kāryā vicāraṇā"},{"type":"verse","number":"140","sanskrit":"हरीतकीत्रिवृद्वृद्धदारकाणां पृथग्भवेत् पलद्वयं कणा शुण्ठी गुडूची गोक्षुरो वरी","text":"harītakītrivṛdvṛddhadārakāṇāṃ pṛthagbhavet paladvayaṃ kaṇā śuṇṭhī guḍūcī gokṣuro varī"},{"type":"verse","number":"141","sanskrit":"सहदेवी विडङ्गञ्च प्रत्येकं पलसम्मितम् मधुना वटिकां कृत्वा खादञ्ज्वरमपोहति","text":"sahadevī viḍaṅgañca pratyekaṃ palasammitam madhunā vaṭikāṃ kṛtvā khādañjvaramapohati"},{"type":"verse","number":"142","sanskrit":"कासं श्वासं मलस्तम्भं वह्निमान्द्यं नियच्छति","text":"kāsaṃ śvāsaṃ malastambhaṃ vahnimāndyaṃ niyacchati"},{"type":"verse","number":"143","sanskrit":"लाक्षा दशाक्षा त्वरुणा षडक्षा सचन्दनं लोहितचन्दनञ्च त्वक्पत्रकं वारि मुरा समुस्ता प्रत्येकमेतानि पलोन्मितानि","text":"lākṣā daśākṣā tvaruṇā ṣaḍakṣā sacandanaṃ lohitacandanañca tvakpatrakaṃ vāri murā samustā pratyekametāni palonmitāni"},{"type":"verse","number":"144","sanskrit":"किराततिक्तात्रिवृतासतिक्ताऽमृताकणापर्पटकण्टकार्यः विडङ्गविश्वाऽमलकानि वासारसानिशावीरणसिन्दुवाराः","text":"kirātatiktātrivṛtāsatiktā'mṛtākaṇāparpaṭakaṇṭakāryaḥ viḍaṅgaviśvā'malakāni vāsārasāniśāvīraṇasinduvārāḥ"},{"type":"verse","number":"145","sanskrit":"एतानि देयानि पृथक्पलार्द्धमानानिसर्वाणि च भेषजानि कल्कानमीषां विदधीत गव्यदुग्धेन वै सार्द्धतुलामितेन","text":"etāni deyāni pṛthakpalārddhamānānisarvāṇi ca bheṣajāni kalkānamīṣāṃ vidadhīta gavyadugdhena vai sārddhatulāmitena"},{"type":"verse","number":"146","sanskrit":"तैलं तिलानां तु तुलाऽनुमानं तेनैव कल्केन शनैः पचेच्च हन्याज्ज्वरांस्तैलमिदं समस्तान् कुर्याद् बलं वीर्यमतीव पुष्टिम्","text":"tailaṃ tilānāṃ tu tulā'numānaṃ tenaiva kalkena śanaiḥ pacecca hanyājjvarāṃstailamidaṃ samastān kuryād balaṃ vīryamatīva puṣṭim"},{"type":"verse","number":"147","sanskrit":"विमर्दनादाशु परिश्रमं भ्रमं शमं नयेत्सञ्जनयेद् द्युतिं तनोः तथा व्यथामस्थिसमुद्भवामपि प्रहृत्य निद्रां समुपार्जयेत्सुखम्","text":"vimardanādāśu pariśramaṃ bhramaṃ śamaṃ nayetsañjanayed dyutiṃ tanoḥ tathā vyathāmasthisamudbhavāmapi prahṛtya nidrāṃ samupārjayetsukham"},{"type":"verse","number":"148","sanskrit":"लाक्षारससमं तैलं तैलान्मस्तु चतुर्गुणम् अश्वगन्धानिशादारुकौन्तीकुष्ठाब्दचन्दनैः","text":"lākṣārasasamaṃ tailaṃ tailānmastu caturguṇam aśvagandhāniśādārukauntīkuṣṭhābdacandanaiḥ"},{"type":"verse","number":"149","sanskrit":"समूर्वारोहिणीरास्नाशताह्वामधुकैः समैः सिद्धं लाक्षाऽदिकं नाम तैलमभ्यञ्जनादिना","text":"samūrvārohiṇīrāsnāśatāhvāmadhukaiḥ samaiḥ siddhaṃ lākṣā'dikaṃ nāma tailamabhyañjanādinā"},{"type":"verse","number":"150","sanskrit":"सर्वज्वरक्षयोन्मादश्वासापस्मारवातनुत् यक्षराक्षसभूतध्नं गर्भिणीनां च शस्यते","text":"sarvajvarakṣayonmādaśvāsāpasmāravātanut yakṣarākṣasabhūtadhnaṃ garbhiṇīnāṃ ca śasyate"},{"type":"verse","number":"151","sanskrit":"लाक्षा हरिद्रा मञ्जिष्ठा फेनिलं मधुकं वला लामज्जकं चन्दनं च चम्पकं नीलमुत्पलम्","text":"lākṣā haridrā mañjiṣṭhā phenilaṃ madhukaṃ valā lāmajjakaṃ candanaṃ ca campakaṃ nīlamutpalam"},{"type":"verse","number":"152","sanskrit":"प्रत्येकमेषां षण्मुष्टीः पक्त्वा तोये चतुर्गुणे चतुर्भागावशेषे तु गर्भे चैतत्समावपेत्","text":"pratyekameṣāṃ ṣaṇmuṣṭīḥ paktvā toye caturguṇe caturbhāgāvaśeṣe tu garbhe caitatsamāvapet"},{"type":"verse","number":"153","sanskrit":"रेणुका पद्मकञ्चैव वाजिगन्धा तथैव च वेतसं चोरकं कुष्ठं देवदारु नखं त्वचम्","text":"reṇukā padmakañcaiva vājigandhā tathaiva ca vetasaṃ corakaṃ kuṣṭhaṃ devadāru nakhaṃ tvacam"},{"type":"verse","number":"154","sanskrit":"शतपुष्पा पुण्डरीकं मांसी मधुकमेव च एभिरक्षमितैः कल्कैः कषायेणैव पेषितैः","text":"śatapuṣpā puṇḍarīkaṃ māṃsī madhukameva ca ebhirakṣamitaiḥ kalkaiḥ kaṣāyeṇaiva peṣitaiḥ"},{"type":"verse","number":"155","sanskrit":"मस्तुशुक्तारनालानामाढकांशं समावपेत् क्षीराढकसमायुक्तं तैलप्रस्थं विपाचयेत्","text":"mastuśuktāranālānāmāḍhakāṃśaṃ samāvapet kṣīrāḍhakasamāyuktaṃ tailaprasthaṃ vipācayet"},{"type":"verse","number":"156","sanskrit":"अभ्यङ्गात्तैलमेतद्धि शीघ्रं दाहमपोहति व्यपोहति तथा वातपित्तश्लेष्मभवज्वरम्","text":"abhyaṅgāttailametaddhi śīghraṃ dāhamapohati vyapohati tathā vātapittaśleṣmabhavajvaram"},{"type":"verse","number":"157","sanskrit":"सप्रलापं सतृष्णञ्च तालुशोषभ्रमान्वितम् ग्रहोपसृष्टा ये बाला रक्षसा दूषिताश्च ये तेषां कष्टं प्रशमयेत्तैलं लाक्षाऽदिकं महत्","text":"sapralāpaṃ satṛṣṇañca tāluśoṣabhramānvitam grahopasṛṣṭā ye bālā rakṣasā dūṣitāśca ye teṣāṃ kaṣṭaṃ praśamayettailaṃ lākṣā'dikaṃ mahat"},{"type":"verse","number":"158","sanskrit":"सूतो गन्धष्टङ्कणः शोषणश्च सर्वैस्तुल्या शर्करा मत्स्यपित्तैः भूयो भूयो मर्दयेत्तत् त्रिरात्रं वल्लो देयः शृङ्गवेरद्र वेण","text":"sūto gandhaṣṭaṅkaṇaḥ śoṣaṇaśca sarvaistulyā śarkarā matsyapittaiḥ bhūyo bhūyo mardayettat trirātraṃ vallo deyaḥ śṛṅgaveradra veṇa"},{"type":"verse","number":"159","sanskrit":"तापे शीतं व्यञ्जनैस्तक्रभक्तं वृन्ताकाढ्यं पथ्यमेतत्प्रदिष्टम् अह्नायोग्रं हन्ति सद्यो ज्वरन्तु पित्ताधिक्ये मूर्ध्नि तोयं च दद्यात्","text":"tāpe śītaṃ vyañjanaistakrabhaktaṃ vṛntākāḍhyaṃ pathyametatpradiṣṭam ahnāyograṃ hanti sadyo jvarantu pittādhikye mūrdhni toyaṃ ca dadyāt"},{"type":"verse","number":"160","sanskrit":"भवेत् समं सूतसमुद्र फेनहिङ्गूलगन्धं परिमर्द्य यामम् नवज्वरे वह्रयुगं त्रिघस्रमार्द्राम्भसाऽय ज्वरधूमकेतुः","text":"bhavet samaṃ sūtasamudra phenahiṅgūlagandhaṃ parimardya yāmam navajvare vahrayugaṃ trighasramārdrāmbhasā'ya jvaradhūmaketuḥ"},{"type":"verse","number":"161","sanskrit":"शुद्धसूतो विषं गन्धः प्रत्येकं शाणसम्मितः धूर्त्तबीजं त्रिशाणं स्यात्सर्वेभ्यो द्विगुणा भवेत्","text":"śuddhasūto viṣaṃ gandhaḥ pratyekaṃ śāṇasammitaḥ dhūrttabījaṃ triśāṇaṃ syātsarvebhyo dviguṇā bhavet"},{"type":"verse","number":"162","sanskrit":"हेमाह्व कारयेदेषां सूक्ष्मं चूर्णं प्रयत्नतः देयं जम्बीरमज्जाभिश्चूर्णं गुञ्जाद्वयोन्मितम्","text":"hemāhva kārayedeṣāṃ sūkṣmaṃ cūrṇaṃ prayatnataḥ deyaṃ jambīramajjābhiścūrṇaṃ guñjādvayonmitam"},{"type":"verse","number":"163","sanskrit":"आर्द्र कस्य रसेनापि ज्वरं हन्ति त्रिदोषजम् एकाहिकं द्वयाहिकं च त्र्याहिकं च चतुर्थकम्","text":"ārdra kasya rasenāpi jvaraṃ hanti tridoṣajam ekāhikaṃ dvayāhikaṃ ca tryāhikaṃ ca caturthakam"},{"type":"verse","number":"164","sanskrit":"विषमञ्च ज्वरं हन्यान्नवं जीर्णञ्च सर्वथा महाज्वराङ्कुशो नाम्ना रसोऽय सर्वसम्मतः","text":"viṣamañca jvaraṃ hanyānnavaṃ jīrṇañca sarvathā mahājvarāṅkuśo nāmnā raso'ya sarvasammataḥ"},{"type":"verse","number":"165","sanskrit":"एको भागो रसाच्छुद्धाच्छैलेयःपिप्पली शिवा आकारकरभो गन्धः कटुतैलेन शोधितः","text":"eko bhāgo rasācchuddhācchaileyaḥpippalī śivā ākārakarabho gandhaḥ kaṭutailena śodhitaḥ"},{"type":"verse","number":"166","sanskrit":"फलानि चेन्द्र वारुण्याश्चतुर्भागमिता अमी एकत्र मर्दयेच्चूर्णमिन्द्र वारुणिकारसैः","text":"phalāni cendra vāruṇyāścaturbhāgamitā amī ekatra mardayeccūrṇamindra vāruṇikārasaiḥ"},{"type":"verse","number":"167","sanskrit":"माषोन्मितां वटीं कृत्वा दद्यात्सद्योज्वरे बुधः छिन्नारसानुपानेन ज्वरघ्नी वटिका मता","text":"māṣonmitāṃ vaṭīṃ kṛtvā dadyātsadyojvare budhaḥ chinnārasānupānena jvaraghnī vaṭikā matā"},{"type":"verse","number":"168","sanskrit":"रसं गन्धञ्च दरदं जैपालंक्रमवर्द्धितम् दन्तीरसेन संपिष्य वटी गुञ्जामिता भवेत्","text":"rasaṃ gandhañca daradaṃ jaipālaṃkramavarddhitam dantīrasena saṃpiṣya vaṭī guñjāmitā bhavet"},{"type":"verse","number":"169","sanskrit":"प्रभाते सितया सार्द्धमशिता शीतवारिणा एकेन दिवसेनैषा नवज्वरहरी भवेत्","text":"prabhāte sitayā sārddhamaśitā śītavāriṇā ekena divasenaiṣā navajvaraharī bhavet"},{"type":"verse","number":"170","sanskrit":"रसो गन्धो विषं शुण्ठीपिप्पलीमरिचानि च पथ्या बिभीतकं धात्री दन्तीबीजं च शोधितम्","text":"raso gandho viṣaṃ śuṇṭhīpippalīmaricāni ca pathyā bibhītakaṃ dhātrī dantībījaṃ ca śodhitam"},{"type":"verse","number":"171","sanskrit":"चूर्णमेषां समांशानां द्रो णपुष्पीरसैः पुटेत् वटीं माषनिभांकुर्याद्भक्षयेन्नूतने ज्वरे","text":"cūrṇameṣāṃ samāṃśānāṃ dro ṇapuṣpīrasaiḥ puṭet vaṭīṃ māṣanibhāṃkuryādbhakṣayennūtane jvare"},{"type":"verse","number":"172","sanskrit":"एकभागो रसो भागद्वयं शुद्धञ्च गन्धकम् गरलस्य त्रयो भागाश्चतुर्भागा हिमावती","text":"ekabhāgo raso bhāgadvayaṃ śuddhañca gandhakam garalasya trayo bhāgāścaturbhāgā himāvatī"},{"type":"verse","number":"173","sanskrit":"जैपालकः पञ्चभागो निम्बूद्र वविमर्दितः कृमिघ्नप्रमिता वट्यः कार्याः सर्वज्वरच्छिदः","text":"jaipālakaḥ pañcabhāgo nimbūdra vavimarditaḥ kṛmighnapramitā vaṭyaḥ kāryāḥ sarvajvaracchidaḥ"},{"type":"verse","number":"174","sanskrit":"शृङ्गवेरेण दातव्या वटिकैका दिने दिने जीर्णज्वरे तथाऽजीर्णे सामे वा विषमे तथा","text":"śṛṅgavereṇa dātavyā vaṭikaikā dine dine jīrṇajvare tathā'jīrṇe sāme vā viṣame tathā"},{"type":"verse","number":"175","sanskrit":"ज्वरं सर्व निहन्त्यसौ दावो वनमिवानलः","text":"jvaraṃ sarva nihantyasau dāvo vanamivānalaḥ"},{"type":"verse","number":"176","sanskrit":"शुद्धं सूतं विषं गन्धं धूर्त्तबीजं त्रिभिः समम् चतुर्णां द्विगुणं व्योषं चूर्णं गुञ्जाद्वयोन्मितम्","text":"śuddhaṃ sūtaṃ viṣaṃ gandhaṃ dhūrttabījaṃ tribhiḥ samam caturṇāṃ dviguṇaṃ vyoṣaṃ cūrṇaṃ guñjādvayonmitam"},{"type":"verse","number":"177","sanskrit":"आर्द्र कस्य रसैः किं वा जम्बीरस्य रसैर्युतम् महाज्वराङ्कुशो नाम्ना सर्वज्वरविनाशनः","text":"ārdra kasya rasaiḥ kiṃ vā jambīrasya rasairyutam mahājvarāṅkuśo nāmnā sarvajvaravināśanaḥ"},{"type":"verse","number":"178","sanskrit":"एकाहिकं द्व्याहिकञ्च त्र्याहिकञ्च चतुर्थकम् विषमं वा त्रिदोषं वा ज्वरं हन्ति न संशयः","text":"ekāhikaṃ dvyāhikañca tryāhikañca caturthakam viṣamaṃ vā tridoṣaṃ vā jvaraṃ hanti na saṃśayaḥ"},{"type":"verse","number":"179","sanskrit":"सूतं गन्धं विषं चैव टङ्कणं च मनःशिला एतानि टङ्कमात्राणि मरिचं त्वष्टटङ्ककम्","text":"sūtaṃ gandhaṃ viṣaṃ caiva ṭaṅkaṇaṃ ca manaḥśilā etāni ṭaṅkamātrāṇi maricaṃ tvaṣṭaṭaṅkakam"},{"type":"verse","number":"180","sanskrit":"कटुत्रयं टङ्कषट्कं खल्ले क्षिप्त्वा विचूर्णयेत् रसः श्वासकुठारोऽय सर्वज्वरहरः परः","text":"kaṭutrayaṃ ṭaṅkaṣaṭkaṃ khalle kṣiptvā vicūrṇayet rasaḥ śvāsakuṭhāro'ya sarvajvaraharaḥ paraḥ"},{"type":"verse","number":"181","sanskrit":"दारुमुखां शिखिग्रीवां रसकञ्च पृथक् पृथक् टङ्कत्रयानुमानेन गृहीत्वा कनकद्र वैः","text":"dārumukhāṃ śikhigrīvāṃ rasakañca pṛthak pṛthak ṭaṅkatrayānumānena gṛhītvā kanakadra vaiḥ"},{"type":"verse","number":"182","sanskrit":"मर्दयेत् त्रिदिनं कार्या वटी चणकमात्रया मरिचैरेकविंशत्या सप्तभिस्तुलसीदलैः","text":"mardayet tridinaṃ kāryā vaṭī caṇakamātrayā maricairekaviṃśatyā saptabhistulasīdalaiḥ"},{"type":"verse","number":"183","sanskrit":"खादेद्वटीद्वयं पथ्यं दुग्धभक्तं सशर्करम् तरुणं विषमं जीर्णं हन्यात्सर्वज्वरं ध्रुवम्","text":"khādedvaṭīdvayaṃ pathyaṃ dugdhabhaktaṃ saśarkaram taruṇaṃ viṣamaṃ jīrṇaṃ hanyātsarvajvaraṃ dhruvam"},{"type":"verse","number":"184","sanskrit":"नागरं कर्षमात्रञ्च टङ्कणं कर्षकद्वयम् मरिचं सार्द्धकर्षं स्यात्तावद्दग्धवराटकम्","text":"nāgaraṃ karṣamātrañca ṭaṅkaṇaṃ karṣakadvayam maricaṃ sārddhakarṣaṃ syāttāvaddagdhavarāṭakam"},{"type":"verse","number":"185","sanskrit":"विषं कर्षचतुर्थांशं सर्वमेकत्र चूर्णयेत् रसो हुताशनो नाम्ना खाद्यो गुञ्जामितो ज्वरे","text":"viṣaṃ karṣacaturthāṃśaṃ sarvamekatra cūrṇayet raso hutāśano nāmnā khādyo guñjāmito jvare"},{"type":"verse","number":"186","sanskrit":"शुद्धजैपालटङ्कं तु कट्वीं टङ्कद्वयोन्मिताम् गैरिकं टङ्कमेकञ्च कन्यानीरेण मर्दयेत्","text":"śuddhajaipālaṭaṅkaṃ tu kaṭvīṃ ṭaṅkadvayonmitām gairikaṃ ṭaṅkamekañca kanyānīreṇa mardayet"},{"type":"verse","number":"187","sanskrit":"कलायसदृशी कार्या वटिका ताञ्च भक्षयेत् शीतलेन जलेनैव वटी जीर्णज्वरापहा","text":"kalāyasadṛśī kāryā vaṭikā tāñca bhakṣayet śītalena jalenaiva vaṭī jīrṇajvarāpahā"},{"type":"verse","number":"188","sanskrit":"द्विभागतालेन हतं च ताम्रं रसं च गन्धं च समीनमायुम् विषं समं च द्विगुणञ्च ताम्रं त्रिःसप्तवारेण दिवाकरांशौ","text":"dvibhāgatālena hataṃ ca tāmraṃ rasaṃ ca gandhaṃ ca samīnamāyum viṣaṃ samaṃ ca dviguṇañca tāmraṃ triḥsaptavāreṇa divākarāṃśau"},{"type":"verse","number":"189","sanskrit":"विमर्द्य चारिष्टरसेनचूर्णं गुञ्जैकदत्तं सितया समेतम् ज्वराङ्कुशोऽय रविसुन्दराख्यो ज्वरान्निहन्त्यष्टविधान्समस्तान्","text":"vimardya cāriṣṭarasenacūrṇaṃ guñjaikadattaṃ sitayā sametam jvarāṅkuśo'ya ravisundarākhyo jvarānnihantyaṣṭavidhānsamastān"},{"type":"verse","number":"190","sanskrit":"शुद्धं सूतं तथा गन्धं खल्ले तावद्विमर्दयेत् सूतं न दृश्यते यावत्किन्तु तत्कज्जलं भवेत्","text":"śuddhaṃ sūtaṃ tathā gandhaṃ khalle tāvadvimardayet sūtaṃ na dṛśyate yāvatkintu tatkajjalaṃ bhavet"},{"type":"verse","number":"191","sanskrit":"एषा कज्जलिका ख्याता वृंहणी वीर्यवर्द्धिनी नानाऽनुपानयोगेन सर्वव्याधिविनाशिनी","text":"eṣā kajjalikā khyātā vṛṃhaṇī vīryavarddhinī nānā'nupānayogena sarvavyādhivināśinī"},{"type":"verse","number":"192","sanskrit":"जपापत्ररसेनाथ वर्द्धमानरसेन च भृङ्गराजरसेनापि काकमाच्या रसेन च","text":"japāpatrarasenātha varddhamānarasena ca bhṛṅgarājarasenāpi kākamācyā rasena ca"},{"type":"verse","number":"193","sanskrit":"रसं संशोधयेत्तेन तत्समं शोधयेद्वलिम् भृङ्गराजरसैः पिष्ट्वा शोषयेदर्करश्मिभिः","text":"rasaṃ saṃśodhayettena tatsamaṃ śodhayedvalim bhṛṅgarājarasaiḥ piṣṭvā śoṣayedarkaraśmibhiḥ"},{"type":"verse","number":"194","sanskrit":"सप्तधा वा त्रिधा वाऽपि पश्चाच्चूर्णन्तु कारयेत् चूर्णयित्वा समं तेन रसेन सह मर्दयेत्","text":"saptadhā vā tridhā vā'pi paścāccūrṇantu kārayet cūrṇayitvā samaṃ tena rasena saha mardayet"},{"type":"verse","number":"195","sanskrit":"नष्टसूतं यदा चूर्णं भवेत्कज्जलसन्निभम् निर्धूमबदराङ्गारे द्र वीकुर्यात्प्रयत्नतः","text":"naṣṭasūtaṃ yadā cūrṇaṃ bhavetkajjalasannibham nirdhūmabadarāṅgāre dra vīkuryātprayatnataḥ"},{"type":"verse","number":"196","sanskrit":"तत्र तं महिषीविष्ठास्थापिते कदलीदले निक्षिपेत्तदुपर्य्यन्यत् पत्रं दत्वा प्रपीडयेत्","text":"tatra taṃ mahiṣīviṣṭhāsthāpite kadalīdale nikṣipettaduparyyanyat patraṃ datvā prapīḍayet"},{"type":"verse","number":"197","sanskrit":"शीतलञ्च ततः पत्रात् समुद्धृत्य विचूर्णयेत् एवं सिद्धा भवेद्व्याधिघातिनी रसपर्पटी","text":"śītalañca tataḥ patrāt samuddhṛtya vicūrṇayet evaṃ siddhā bhavedvyādhighātinī rasaparpaṭī"},{"type":"verse","number":"198","sanskrit":"ज्वरादिव्याधिभिर्व्याप्तं विश्वं दृष्ट्वा पुरा हरः चकार कृपया युक्तः सुधावद्र सपर्पटीम्","text":"jvarādivyādhibhirvyāptaṃ viśvaṃ dṛṣṭvā purā haraḥ cakāra kṛpayā yuktaḥ sudhāvadra saparpaṭīm"},{"type":"verse","number":"199","sanskrit":"रक्तिकासम्मितां तावद् भृष्टजीरकसंयुताम् गुञ्जाऽद्धभृष्टहिङ्ग्वाढ्यां भक्षयेद्र सपर्पटीम्","text":"raktikāsammitāṃ tāvad bhṛṣṭajīrakasaṃyutām guñjā'ddhabhṛṣṭahiṅgvāḍhyāṃ bhakṣayedra saparpaṭīm"},{"type":"verse","number":"200","sanskrit":"रोगानुरूपभैषज्यैरपि तां भक्षयेद्बुधः पिबेत्तदनु पानीयं शीतलंचुलुकत्रयम्","text":"rogānurūpabhaiṣajyairapi tāṃ bhakṣayedbudhaḥ pibettadanu pānīyaṃ śītalaṃculukatrayam"},{"type":"verse","number":"201","sanskrit":"प्रत्यहं वर्धयेत्तस्याएकैकां रक्तिकां भिषक् नाधिकां दशगुञ्जातो भक्षयेत्तां कदाचन","text":"pratyahaṃ vardhayettasyāekaikāṃ raktikāṃ bhiṣak nādhikāṃ daśaguñjāto bhakṣayettāṃ kadācana"},{"type":"verse","number":"202","sanskrit":"एकादशदिनारम्भात्तां ततो वाऽपकर्षयेत् एवमेतां समश्नीयान्नरो विंशतिवासरान्","text":"ekādaśadinārambhāttāṃ tato vā'pakarṣayet evametāṃ samaśnīyānnaro viṃśativāsarān"},{"type":"verse","number":"203","sanskrit":"शिवं गुरूंस्तथा विप्रान्पूजयित्वा प्रणम्य च श्रद्धया भक्षयेदेतां क्षीरमांसरसाशनः","text":"śivaṃ gurūṃstathā viprānpūjayitvā praṇamya ca śraddhayā bhakṣayedetāṃ kṣīramāṃsarasāśanaḥ"},{"type":"verse","number":"204","sanskrit":"ज्वरञ्च ग्रहणीं वाऽपि तथाऽतीसारमेव च कामला पाण्डुरोगञ्च शूलं प्लीहं जलोदरम्","text":"jvarañca grahaṇīṃ vā'pi tathā'tīsārameva ca kāmalā pāṇḍurogañca śūlaṃ plīhaṃ jalodaram"},{"type":"verse","number":"205","sanskrit":"एवमादीन् गदान् हत्वा हृष्टः पुष्टश्च वीर्यवान् जीवेद्वर्षशतं साग्रं वलीपलितवर्जितः","text":"evamādīn gadān hatvā hṛṣṭaḥ puṣṭaśca vīryavān jīvedvarṣaśataṃ sāgraṃ valīpalitavarjitaḥ"},{"type":"verse","number":"206","sanskrit":"अथ ज्वरिणोऽन्नदानसमयस्तत्र चरकः क्षुत्सम्भवति पक्वेषु रसदोषमलेषु च काले वा यदि वाऽकालेसोऽन्नकाल उदाहृतः","text":"atha jvariṇo'nnadānasamayastatra carakaḥ kṣutsambhavati pakveṣu rasadoṣamaleṣu ca kāle vā yadi vā'kāleso'nnakāla udāhṛtaḥ"},{"type":"verse","number":"207","sanskrit":"आमे पाकं गते नॄणां यदा भोजनलालसा भवेत्काले ह्यकाले वा सोऽन्नकाल उदाहृतः","text":"āme pākaṃ gate nṝṇāṃ yadā bhojanalālasā bhavetkāle hyakāle vā so'nnakāla udāhṛtaḥ"},{"type":"verse","number":"208","sanskrit":"सर्वज्वरेषु सप्ताहं मात्रावल्लघु भोजयेत् वेगापायेऽन्यथा तद्धिज्वरवेगाभिवर्द्धनम्","text":"sarvajvareṣu saptāhaṃ mātrāvallaghu bhojayet vegāpāye'nyathā taddhijvaravegābhivarddhanam"},{"type":"verse","number":"209","sanskrit":"आहारनिर्हारविहारयोगाःसदैव सद्भिर्विजने विधेयाः","text":"āhāranirhāravihārayogāḥsadaiva sadbhirvijane vidheyāḥ"},{"type":"verse","number":"210","sanskrit":"ज्वरे प्रमेहो भवति स्वल्पैरपि विचेष्टितैः निषण्णं भोजयेत्तस्मान्मूत्रोच्चारौ च कारयेत्","text":"jvare prameho bhavati svalpairapi viceṣṭitaiḥ niṣaṇṇaṃ bhojayettasmānmūtroccārau ca kārayet"},{"type":"verse","number":"211","sanskrit":"यथादोषोचितैर्द्र्रव्यैः कर्त्तव्यः कवल ग्रहः अरोचकास्यवैरस्यमलपूतिप्रसेकहृत्","text":"yathādoṣocitairdrravyaiḥ karttavyaḥ kavala grahaḥ arocakāsyavairasyamalapūtiprasekahṛt"},{"type":"verse","number":"212","sanskrit":"भृष्टजीरकचूर्णेन सिन्धुजन्मयुतेन च जिह्वादन्तान्मुखस्यान्तर्घृष्ट्वा कवलमाचरेत्","text":"bhṛṣṭajīrakacūrṇena sindhujanmayutena ca jihvādantānmukhasyāntarghṛṣṭvā kavalamācaret"},{"type":"verse","number":"213","sanskrit":"मुखे मलं विगन्धत्वं विरसत्वंच नश्यति मनःप्रसन्नं भवति भोजनेऽतिरुचिर्भवेत्","text":"mukhe malaṃ vigandhatvaṃ virasatvaṃca naśyati manaḥprasannaṃ bhavati bhojane'tirucirbhavet"},{"type":"verse","number":"214","sanskrit":"ज्वरितो हितमश्नीयाद्यद्यप्यस्यारुचिर्भवेत् अन्नकाले ह्यभुञ्जानः क्षीयते म्रियतेऽपि च","text":"jvarito hitamaśnīyādyadyapyasyārucirbhavet annakāle hyabhuñjānaḥ kṣīyate mriyate'pi ca"},{"type":"verse","number":"215","sanskrit":"रक्तशाल्यादयः शस्ताःपुराणाः षष्टिकैः सह यवाग्वोदनलाजार्थे ज्वरितानां ज्वरापहाः","text":"raktaśālyādayaḥ śastāḥpurāṇāḥ ṣaṣṭikaiḥ saha yavāgvodanalājārthe jvaritānāṃ jvarāpahāḥ"},{"type":"verse","number":"216","sanskrit":"मुद्गान् मसूरांश्चणकान् कुलत्थान्समकुष्ठकान् यूषार्थे यूषसात्म्यानं ज्वरितानां प्रदापयेत्","text":"mudgān masūrāṃścaṇakān kulatthānsamakuṣṭhakān yūṣārthe yūṣasātmyānaṃ jvaritānāṃ pradāpayet"},{"type":"verse","number":"217","sanskrit":"पटोलपत्रं वार्त्ताकुं कुलकं कारवेल्लकम् कर्कोटकं पर्पटकं गोजिह्वां बालमूलकम्","text":"paṭolapatraṃ vārttākuṃ kulakaṃ kāravellakam karkoṭakaṃ parpaṭakaṃ gojihvāṃ bālamūlakam"},{"type":"verse","number":"218","sanskrit":"पत्रं गुडूच्याःशाकार्थे ज्वरितानां ज्वरापहम् लावान् कपिञ्जलानेणान् हरिणान्पृषताञ्छशान्","text":"patraṃ guḍūcyāḥśākārthe jvaritānāṃ jvarāpaham lāvān kapiñjalāneṇān hariṇānpṛṣatāñchaśān"},{"type":"verse","number":"219","sanskrit":"कुरङ्गान्कालपुच्छांश्च तथैव मृगमातृकान् मांसार्थं मांससात्म्यानां ज्वरितानां प्रदापयेत्","text":"kuraṅgānkālapucchāṃśca tathaiva mṛgamātṛkān māṃsārthaṃ māṃsasātmyānāṃ jvaritānāṃ pradāpayet"},{"type":"verse","number":"220","sanskrit":"सारसक्रौञ्चशिखिनस्तथा तित्तिरकुक्कुटान् गुरूष्णत्वान्न शंसन्ति केचिदेवं व्यवस्थिताः","text":"sārasakrauñcaśikhinastathā tittirakukkuṭān gurūṣṇatvānna śaṃsanti kecidevaṃ vyavasthitāḥ"},{"type":"verse","number":"221","sanskrit":"ज्वरितानां प्रकोपं तु यदा याति समीरणः तदैतेऽपि हि शस्यन्ते मात्राकालोपपादिताः","text":"jvaritānāṃ prakopaṃ tu yadā yāti samīraṇaḥ tadaite'pi hi śasyante mātrākālopapāditāḥ"},{"type":"verse","number":"222","sanskrit":"निम्बुकं दाडिमं धात्रीफलमम्लं प्रकाङ्क्षते प्रदद्यादम्लसात्म्याय काञ्जिकं वा पुरातनम्","text":"nimbukaṃ dāḍimaṃ dhātrīphalamamlaṃ prakāṅkṣate pradadyādamlasātmyāya kāñjikaṃ vā purātanam"},{"type":"verse","number":"223","sanskrit":"तण्डुलानां सुसिद्धानां चतुर्दशगुणे जले रसः सिक्थैर्विरहितो मण्ड इत्यभिधीयते","text":"taṇḍulānāṃ susiddhānāṃ caturdaśaguṇe jale rasaḥ sikthairvirahito maṇḍa ityabhidhīyate"},{"type":"verse","number":"224","sanskrit":"शुण्ठीसैन्धवसंयुक्तो दीपनः पाचनश्च सः अन्नस्य सम्यक्सिद्धत्वं ज्ञेया मण्डस्य सिद्धता","text":"śuṇṭhīsaindhavasaṃyukto dīpanaḥ pācanaśca saḥ annasya samyaksiddhatvaṃ jñeyā maṇḍasya siddhatā"},{"type":"verse","number":"225","sanskrit":"पेयायूषयवागूनां विलेपीभक्तयोरपि मण्डो ग्राही लघुः शीतो दीपनो धातुसाम्यकृत् ज्वरघ्नस्तर्पणो बल्यः पित्तश्लेष्मश्रमापहः","text":"peyāyūṣayavāgūnāṃ vilepībhaktayorapi maṇḍo grāhī laghuḥ śīto dīpano dhātusāmyakṛt jvaraghnastarpaṇo balyaḥ pittaśleṣmaśramāpahaḥ"},{"type":"verse","number":"226","sanskrit":"चतुर्दशगुणे नीरे रक्तशाल्यादिभिः कृता द्र वाधिका स्वल्पसिक्था पेया प्रोक्ता भिषग्वरैः","text":"caturdaśaguṇe nīre raktaśālyādibhiḥ kṛtā dra vādhikā svalpasikthā peyā proktā bhiṣagvaraiḥ"},{"type":"verse","number":"227","sanskrit":"साऽतिलघ्वी ग्राहिणी च धातुपुष्टिविधायिनी तृड्ज्वरानिलदौर्बल्यकुक्षिरोगविनाशिनी","text":"sā'tilaghvī grāhiṇī ca dhātupuṣṭividhāyinī tṛḍjvarāniladaurbalyakukṣirogavināśinī"},{"type":"verse","number":"228","sanskrit":"स्वेदाग्निजननी ज्ञेया वातवर्चोऽनुलोमनी शुण्ठीसैन्धवसंयुक्ता दीपनी पाचनी च सा","text":"svedāgnijananī jñeyā vātavarco'nulomanī śuṇṭhīsaindhavasaṃyuktā dīpanī pācanī ca sā"},{"type":"verse","number":"229","sanskrit":"आमशूलहरी रुच्या स्याद्विबन्धविनाशिनी","text":"āmaśūlaharī rucyā syādvibandhavināśinī"},{"type":"verse","number":"230","sanskrit":"प्रमथ्या प्रोच्यते द्र्रव्यपलात्कल्कीकृताच्छ्रतात् तोयेऽष्टगुणिते तस्याः पानमाहुः पलद्वयम् गुणैः प्रमथ्या पेयावत्ततो लघ्वी विशेषतः","text":"pramathyā procyate drravyapalātkalkīkṛtācchratāt toye'ṣṭaguṇite tasyāḥ pānamāhuḥ paladvayam guṇaiḥ pramathyā peyāvattato laghvī viśeṣataḥ"},{"type":"verse","number":"231","sanskrit":"अष्टादशगुणे नीरे शिम्बीधान्यशृतो रसः विरलान्नो घनः किञ्चित्पेयातो यूष उच्यते उक्तः स एव निर्यूहो रुचिकृच्च विशेषतः","text":"aṣṭādaśaguṇe nīre śimbīdhānyaśṛto rasaḥ viralānno ghanaḥ kiñcitpeyāto yūṣa ucyate uktaḥ sa eva niryūho rucikṛcca viśeṣataḥ"},{"type":"verse","number":"232","sanskrit":"कल्कद्र्रव्यपलं शुण्ठी पिप्पली चार्द्धकार्षिकी वारिप्रस्थेन विपचेत्तद्भवो यूष उच्यते","text":"kalkadrravyapalaṃ śuṇṭhī pippalī cārddhakārṣikī vāriprasthena vipacettadbhavo yūṣa ucyate"},{"type":"verse","number":"233","sanskrit":"यूषो बल्यो लघुःपाके रुच्यः कण्ड्यः कफापहः","text":"yūṣo balyo laghuḥpāke rucyaḥ kaṇḍyaḥ kaphāpahaḥ"},{"type":"verse","number":"234","sanskrit":"मुद्गानां द्विपलं तोये शृतमर्द्धाढकोन्मिते पादस्थं मर्दितं पूतं दाडिमस्य पलेन तत्","text":"mudgānāṃ dvipalaṃ toye śṛtamarddhāḍhakonmite pādasthaṃ marditaṃ pūtaṃ dāḍimasya palena tat"},{"type":"verse","number":"235","sanskrit":"युक्तं सैन्धवविश्वाह्वधान्यकैः पादिकांशिकैः कणाजीरकयोश्चूर्णाच्छाणैकेनावचूर्णितम् संस्कृतो मुद्गयूषोऽय पित्तश्लेष्महरो मतः","text":"yuktaṃ saindhavaviśvāhvadhānyakaiḥ pādikāṃśikaiḥ kaṇājīrakayoścūrṇācchāṇaikenāvacūrṇitam saṃskṛto mudgayūṣo'ya pittaśleṣmaharo mataḥ"},{"type":"verse","number":"236","sanskrit":"मुद्गानामुत्तमो यूषः दीपनः शीतलो लघुः व्रणोर्द्ध्वजत्रुरुग्दाहकफपित्तज्वरास्रजित्","text":"mudgānāmuttamo yūṣaḥ dīpanaḥ śītalo laghuḥ vraṇorddhvajatrurugdāhakaphapittajvarāsrajit"},{"type":"verse","number":"237","sanskrit":"मुद्गामलकयूषस्तु भेदी पित्तानिलापहः तृड्दाहशमनः शीतो मूर्च्छाश्रममदापहः","text":"mudgāmalakayūṣastu bhedī pittānilāpahaḥ tṛḍdāhaśamanaḥ śīto mūrcchāśramamadāpahaḥ"},{"type":"verse","number":"238","sanskrit":"मसूरयूषः संग्राही बृंही स्वादुः प्रमेहनुत्","text":"masūrayūṣaḥ saṃgrāhī bṛṃhī svāduḥ pramehanut"},{"type":"verse","number":"239","sanskrit":"यवागू षडगुणे तोये संसिद्धा घनसिक्थका पृथग्द्र वैस्तु विरलैः संयुक्ता ज्वरिणे हिता","text":"yavāgū ṣaḍaguṇe toye saṃsiddhā ghanasikthakā pṛthagdra vaistu viralaiḥ saṃyuktā jvariṇe hitā"},{"type":"verse","number":"240","sanskrit":"यवागूर्दीपनी लघ्वी तृष्णघ्नी वस्तिशोधिनी श्रमग्लानिहरी पथ्या ज्वरे चैवातिसारके","text":"yavāgūrdīpanī laghvī tṛṣṇaghnī vastiśodhinī śramaglāniharī pathyā jvare caivātisārake"},{"type":"verse","number":"241","sanskrit":"चतुर्गुणाम्बुसंसिद्धा विलेपी घनसिक्थका पृथग्द्र वेण रहिता ख्याता शिथिलभक्तिका","text":"caturguṇāmbusaṃsiddhā vilepī ghanasikthakā pṛthagdra veṇa rahitā khyātā śithilabhaktikā"},{"type":"verse","number":"242","sanskrit":"विलेपी दीपनी बल्या हृद्या संग्राहिणी लघुः व्रणाक्षिरोगिणां पथ्या तर्पणी तृड्ज्वरापहा","text":"vilepī dīpanī balyā hṛdyā saṃgrāhiṇī laghuḥ vraṇākṣirogiṇāṃ pathyā tarpaṇī tṛḍjvarāpahā"},{"type":"verse","number":"243","sanskrit":"जले चतुर्दशगुणे तण्डुलानां चतुष्पलम् विपचेत्स्रावयेन्मण्डं तद्भक्तं मधुरं लघु","text":"jale caturdaśaguṇe taṇḍulānāṃ catuṣpalam vipacetsrāvayenmaṇḍaṃ tadbhaktaṃ madhuraṃ laghu"},{"type":"verse","number":"244","sanskrit":"अन्नं पञ्चगुणे तोये यवागूं षडगुणे पचेत् भक्तं वह्निकरं पथ्यं तर्पणं मूत्रलं लघु","text":"annaṃ pañcaguṇe toye yavāgūṃ ṣaḍaguṇe pacet bhaktaṃ vahnikaraṃ pathyaṃ tarpaṇaṃ mūtralaṃ laghu"},{"type":"verse","number":"245","sanskrit":"सुधौतं प्रस्रुतं चोष्णं विशदं गुणवत्तरम् अधौतमस्रतं शीतं वृष्यं गुरु कफप्रदम्","text":"sudhautaṃ prasrutaṃ coṣṇaṃ viśadaṃ guṇavattaram adhautamasrataṃ śītaṃ vṛṣyaṃ guru kaphapradam"},{"type":"verse","number":"246","sanskrit":"अत्युष्णं बलहृद्भक्तं शीतं शुष्कञ्च दुर्जरम् अतिक्लिन्नं ग्लानिकरं दुर्जरं तण्डुलान्वितम्","text":"atyuṣṇaṃ balahṛdbhaktaṃ śītaṃ śuṣkañca durjaram atiklinnaṃ glānikaraṃ durjaraṃ taṇḍulānvitam"},{"type":"verse","number":"247","sanskrit":"भृष्टतण्डुलजं रुच्यं सुगन्धिं कफहृल्लघु वातास्थापितमन्दाग्निविरिक्तानां प्रशस्यते","text":"bhṛṣṭataṇḍulajaṃ rucyaṃ sugandhiṃ kaphahṛllaghu vātāsthāpitamandāgniviriktānāṃ praśasyate"},{"type":"verse","number":"248","sanskrit":"मांसलं सक्थिजं मांसं तथाऽनस्थि च तैत्तिरम् चतुष्पलोन्मितं सूक्ष्मं कल्पितं क्षालितं जले","text":"māṃsalaṃ sakthijaṃ māṃsaṃ tathā'nasthi ca taittiram catuṣpalonmitaṃ sūkṣmaṃ kalpitaṃ kṣālitaṃ jale"},{"type":"verse","number":"249","sanskrit":"पिप्पलीपिप्पली मूल शुण्ठीजीरकधान्यकैः द्विशाणैः संयुते तोये क्वाथ्यमर्द्धाढकोन्मिते पादस्थितं जलं तत्र दाडिमात् कुट्टिताद्धरेत् तं रसं मर्दितं हिङ्गुभृष्टसैन्धवजीरकैः","text":"pippalīpippalī mūla śuṇṭhījīrakadhānyakaiḥ dviśāṇaiḥ saṃyute toye kvāthyamarddhāḍhakonmite pādasthitaṃ jalaṃ tatra dāḍimāt kuṭṭitāddharet taṃ rasaṃ marditaṃ hiṅgubhṛṣṭasaindhavajīrakaiḥ"},{"type":"verse","number":"250","sanskrit":"युक्तं प्रधूपितं पथ्यं शुद्धानां शुद्धिकाङ्क्षिणाम्","text":"yuktaṃ pradhūpitaṃ pathyaṃ śuddhānāṃ śuddhikāṅkṣiṇām"},{"type":"verse","number":"251","sanskrit":"रसौदनो गुरुर्वृष्यो बल्यो वातज्वरापहः","text":"rasaudano gururvṛṣyo balyo vātajvarāpahaḥ"},{"type":"verse","number":"252","sanskrit":"साध्यं चतुष्पलं द्र्रव्यं चतुःषष्टिपलेऽम्बुनि तत्क्वाथेनार्द्धशिष्टेन मण्डपेयाऽदि साधयेत्","text":"sādhyaṃ catuṣpalaṃ drravyaṃ catuḥṣaṣṭipale'mbuni tatkvāthenārddhaśiṣṭena maṇḍapeyā'di sādhayet"},{"type":"verse","number":"253","sanskrit":"वृद्धवैद्याः पलं द्र व्यं ग्राहयन्त्याढकेऽम्भसि भेषजस्यातिबाहुल्यात् कदाचिदरुचिर्भवेत्","text":"vṛddhavaidyāḥ palaṃ dra vyaṃ grāhayantyāḍhake'mbhasi bheṣajasyātibāhulyāt kadācidarucirbhavet"},{"type":"verse","number":"254","sanskrit":"यैरन्नैरौषधैर्यैश्च कृता मण्डादयो बुधैः विचार्य तद्गुणानेतांस्तद्गुणानेव निर्दिशेत्","text":"yairannairauṣadhairyaiśca kṛtā maṇḍādayo budhaiḥ vicārya tadguṇānetāṃstadguṇāneva nirdiśet"},{"type":"verse","number":"255","sanskrit":"अन्नकाले हिता पेया यथास्वं पाचनैः कृता दीपनी पाचनी लघ्वी ज्वरार्त्तानांज्वरापहा","text":"annakāle hitā peyā yathāsvaṃ pācanaiḥ kṛtā dīpanī pācanī laghvī jvarārttānāṃjvarāpahā"},{"type":"verse","number":"256","sanskrit":"पञ्चमूल्याः कषायन्तु पाचनं वातिके ज्वरे सक्षौद्रं पैत्तिके मुस्तकटुकेन्द्र्रयवैः कृतम्","text":"pañcamūlyāḥ kaṣāyantu pācanaṃ vātike jvare sakṣaudraṃ paittike mustakaṭukendrrayavaiḥ kṛtam"},{"type":"verse","number":"257","sanskrit":"पिप्पल्यादिकषायं तु पाचनं कफजे ज्वरे लघुना पञ्चमूलेन पिप्पल्या सह धान्यया","text":"pippalyādikaṣāyaṃ tu pācanaṃ kaphaje jvare laghunā pañcamūlena pippalyā saha dhānyayā"},{"type":"verse","number":"258","sanskrit":"महत्या पञ्चमूल्याऽथ व्याघ्रीदुःस्पर्शगोक्षुरैः सिद्धानि भिषगन्नानि प्रयुञ्जीत यथाक्रमम् वातपित्ते श्लेष्मपित्ते कफवाते त्रिदोषजे","text":"mahatyā pañcamūlyā'tha vyāghrīduḥsparśagokṣuraiḥ siddhāni bhiṣagannāni prayuñjīta yathākramam vātapitte śleṣmapitte kaphavāte tridoṣaje"},{"type":"verse","number":"259","sanskrit":"पेयां वा रक्तशालीनां वस्तिपार्श्वशिरोरुजि श्वदंष्ट्राकण्टकारीभ्यां सिद्धां ज्वरहरीं पिबेत्","text":"peyāṃ vā raktaśālīnāṃ vastipārśvaśiroruji śvadaṃṣṭrākaṇṭakārībhyāṃ siddhāṃ jvaraharīṃ pibet"},{"type":"verse","number":"260","sanskrit":"विबद्धवर्चाः सयवां पिप्पल्यामलकैः शृताम् सर्पिष्मतीं पिबेत्पेयां ज्वरी दोषानुलोमिनीम्","text":"vibaddhavarcāḥ sayavāṃ pippalyāmalakaiḥ śṛtām sarpiṣmatīṃ pibetpeyāṃ jvarī doṣānulominīm"},{"type":"verse","number":"261","sanskrit":"कासी श्वासी च हिक्की च पञ्चमूलीशृतां पिबेत्","text":"kāsī śvāsī ca hikkī ca pañcamūlīśṛtāṃ pibet"},{"type":"verse","number":"262","sanskrit":"पेया भेषजसंयोगाल्लघुत्वाच्चाग्निदीपनी वातमूत्रपुरीषाणां दोषाणां चानुलोमिका","text":"peyā bheṣajasaṃyogāllaghutvāccāgnidīpanī vātamūtrapurīṣāṇāṃ doṣāṇāṃ cānulomikā"},{"type":"verse","number":"263","sanskrit":"स्वेदनाय च सोष्णत्वाद् द्र्रवत्वात्तृट्क्षयाय च आहारभावात्प्राणाय सरत्वाल्लाघवाय च ज्वरध्नी हेतुसाम्यत्वात्तस्मात्तां पूर्वमाचरेत्","text":"svedanāya ca soṣṇatvād drravatvāttṛṭkṣayāya ca āhārabhāvātprāṇāya saratvāllāghavāya ca jvaradhnī hetusāmyatvāttasmāttāṃ pūrvamācaret"},{"type":"verse","number":"264","sanskrit":"यवकोलकुलत्थानां मुद्गमूलकशुण्ठयोः एकैकमुष्टिमादाय पचेदष्टगुणे जले","text":"yavakolakulatthānāṃ mudgamūlakaśuṇṭhayoḥ ekaikamuṣṭimādāya pacedaṣṭaguṇe jale"},{"type":"verse","number":"265","sanskrit":"पञ्चमुष्टिक इत्येष वातपित्तकफापहः शूले प्रशस्यते गुल्मे कासे श्वासे क्षये ज्वरे","text":"pañcamuṣṭika ityeṣa vātapittakaphāpahaḥ śūle praśasyate gulme kāse śvāse kṣaye jvare"},{"type":"verse","number":"266","sanskrit":"रुद्धमूत्रपुरीषस्य गुदे वर्त्तिं निधापयेत्","text":"ruddhamūtrapurīṣasya gude varttiṃ nidhāpayet"},{"type":"verse","number":"267","sanskrit":"पिप्पलीपिप्पलीमूलयवानीचव्यसाधिताम् पाययेत्तु यवागूं वा मारुताद्यनुलोमिनीम्","text":"pippalīpippalīmūlayavānīcavyasādhitām pāyayettu yavāgūṃ vā mārutādyanulominīm"},{"type":"verse","number":"268","sanskrit":"मदात्यये मद्यनित्ये ग्रीष्मे पित्तकफोत्थिते ऊर्ध्वगे रक्तपित्ते च यवागूर्न हिता ज्वरे","text":"madātyaye madyanitye grīṣme pittakaphotthite ūrdhvage raktapitte ca yavāgūrna hitā jvare"},{"type":"verse","number":"269","sanskrit":"दाहच्छर्द्यर्दितं क्षामं निरन्नं तृष्णयाऽन्वितम् घर्मार्त्तं मद्यपं चापि तोयालोडितसक्तुकम्","text":"dāhacchardyarditaṃ kṣāmaṃ nirannaṃ tṛṣṇayā'nvitam gharmārttaṃ madyapaṃ cāpi toyāloḍitasaktukam"},{"type":"verse","number":"270","sanskrit":"शर्करामधुसंयुक्तं पाययेल्लाजतर्पणम् ज्वरापहैः फलरसैर्युक्तमन्नं हितं क्वचित्","text":"śarkarāmadhusaṃyuktaṃ pāyayellājatarpaṇam jvarāpahaiḥ phalarasairyuktamannaṃ hitaṃ kvacit"},{"type":"verse","number":"271","sanskrit":"द्रा क्षादाडिमखर्जूरमृदिताम्बु सशर्करम् लाजचूर्णं समध्वाज्यं सन्तर्पणमुदाहृतम्","text":"drā kṣādāḍimakharjūramṛditāmbu saśarkaram lājacūrṇaṃ samadhvājyaṃ santarpaṇamudāhṛtam"},{"type":"verse","number":"272","sanskrit":"लाजानां सक्तवः क्षौद्र सितायुक्ता विशेषतः छर्द्यतीसारतृड्दाहविषमूर्च्छाज्वरापहाः","text":"lājānāṃ saktavaḥ kṣaudra sitāyuktā viśeṣataḥ chardyatīsāratṛḍdāhaviṣamūrcchājvarāpahāḥ"},{"type":"verse","number":"273","sanskrit":"तत्र तर्पणमेवादौ प्रदेयं लाजसक्तुभिः ज्वरापहैः फलरसैर्युक्तं समधुशर्करम्","text":"tatra tarpaṇamevādau pradeyaṃ lājasaktubhiḥ jvarāpahaiḥ phalarasairyuktaṃ samadhuśarkaram"},{"type":"verse","number":"274","sanskrit":"द्रा क्षादाडिमखर्जूरप्रियालैः सपरूषकैः तर्पणार्हस्य दातव्यं तर्पणं ज्वरनाशनम्","text":"drā kṣādāḍimakharjūrapriyālaiḥ saparūṣakaiḥ tarpaṇārhasya dātavyaṃ tarpaṇaṃ jvaranāśanam"},{"type":"verse","number":"275","sanskrit":"श्रमोपवासानिलजे हितो नित्यं रसौदनः","text":"śramopavāsānilaje hito nityaṃ rasaudanaḥ"},{"type":"verse","number":"276","sanskrit":"मुद्गयूषौदनश्चैव हितः कफसमुत्थिते स एव सितयायुक्तः शीतः पित्तज्वरे हितः","text":"mudgayūṣaudanaścaiva hitaḥ kaphasamutthite sa eva sitayāyuktaḥ śītaḥ pittajvare hitaḥ"},{"type":"verse","number":"277","sanskrit":"कृशोऽल्पदोषो यः क्षीणकफो जीर्णज्वरान्वितः विवद्धासृष्टदोषश्च रूक्षपित्तानिलज्वरी पिपासाऽत्त सदाहश्च पयसा स सुखी भवेत्","text":"kṛśo'lpadoṣo yaḥ kṣīṇakapho jīrṇajvarānvitaḥ vivaddhāsṛṣṭadoṣaśca rūkṣapittānilajvarī pipāsā'tta sadāhaśca payasā sa sukhī bhavet"},{"type":"verse","number":"278","sanskrit":"अजादुग्धं गुडोपेतं पातव्यं ज्वरशान्तये तदेव तु पयः पीतं तरुणे हन्ति मानवम्","text":"ajādugdhaṃ guḍopetaṃ pātavyaṃ jvaraśāntaye tadeva tu payaḥ pītaṃ taruṇe hanti mānavam"},{"type":"verse","number":"279","sanskrit":"जीर्णज्वरे कफे क्षीणे क्षीरं स्यादमृतोपमम् तदेव तरुणे पीतं विषवद्धन्ति मानवम्","text":"jīrṇajvare kaphe kṣīṇe kṣīraṃ syādamṛtopamam tadeva taruṇe pītaṃ viṣavaddhanti mānavam"},{"type":"verse","number":"280","sanskrit":"न द्विरद्यान्न पूर्वाह्णे नाभिष्यन्दि कदा चन न तीक्ष्णं न गुरुप्रायं भुञ्जीत तरुणज्वरी","text":"na dviradyānna pūrvāhṇe nābhiṣyandi kadā cana na tīkṣṇaṃ na guruprāyaṃ bhuñjīta taruṇajvarī"},{"type":"verse","number":"281","sanskrit":"न जातु तर्पयेत्प्राज्ञः सहसा ज्वरकर्शितम् तेन संशमितोऽप्यस्यपुनरेव भवेज्ज्वरः","text":"na jātu tarpayetprājñaḥ sahasā jvarakarśitam tena saṃśamito'pyasyapunareva bhavejjvaraḥ"},{"type":"verse","number":"282","sanskrit":"दाहः स्वेदो भ्रमस्तृष्णा कम्पो विड्भिदसंज्ञता कूजनं चातिवैगन्ध्यमाकृतिर्ज्वरमोक्षणे","text":"dāhaḥ svedo bhramastṛṣṇā kampo viḍbhidasaṃjñatā kūjanaṃ cātivaigandhyamākṛtirjvaramokṣaṇe"},{"type":"verse","number":"283","sanskrit":"त्रिदोषजे ज्वरे ह्येतदन्तर्वेगे च धातुगे लक्षणं मोक्षकाले स्यादन्यस्मिन्स्वेददर्शनम्","text":"tridoṣaje jvare hyetadantarvege ca dhātuge lakṣaṇaṃ mokṣakāle syādanyasminsvedadarśanam"},{"type":"verse","number":"284","sanskrit":"देहो लघुर्व्यपगतक्लममोहतापः पाको मुखे करणसौष्ठवमव्यथत्वम् स्वेदः क्षवः प्रकृतियो गिमनोऽन्नलिप्सा कण्डूश्च मूर्ध्निविगतज्वरलक्षणानि","text":"deho laghurvyapagataklamamohatāpaḥ pāko mukhe karaṇasauṣṭhavamavyathatvam svedaḥ kṣavaḥ prakṛtiyo gimano'nnalipsā kaṇḍūśca mūrdhnivigatajvaralakṣaṇāni"},{"type":"verse","number":"285","sanskrit":"स्वेदो लघुत्वं शिरसः कण्डूः पाको मुखस्य च क्षवथुश्चान्नकाङ्क्षा च ज्वरमुक्तस्य लक्षणम्","text":"svedo laghutvaṃ śirasaḥ kaṇḍūḥ pāko mukhasya ca kṣavathuścānnakāṅkṣā ca jvaramuktasya lakṣaṇam"},{"type":"verse","number":"286","sanskrit":"व्यायामञ्च व्यवायञ्च स्नानं चङ्क्रमणानि च ज्वरमुक्तो न सेवेत यावन्न बलवान्भवेत्","text":"vyāyāmañca vyavāyañca snānaṃ caṅkramaṇāni ca jvaramukto na seveta yāvanna balavānbhavet"},{"type":"verse","number":"287","sanskrit":"व्ययामञ्च व्यवायञ्च प्रवातं शिशिरं जलम् ज्वर मुक्तो नसेवेत यावन्न बलवान्भवेत्","text":"vyayāmañca vyavāyañca pravātaṃ śiśiraṃ jalam jvara mukto naseveta yāvanna balavānbhavet"},{"type":"verse","number":"288","sanskrit":"जन्तोर्ज्वरविमुक्तस्य स्नानं कुर्यात्पुनर्ज्वरम् तस्माज्ज्वरविमुक्तोऽपि स्नानं विषमिव त्यजेत्","text":"jantorjvaravimuktasya snānaṃ kuryātpunarjvaram tasmājjvaravimukto'pi snānaṃ viṣamiva tyajet"},{"type":"verse","number":"289","sanskrit":"बलवर्णाग्निवपुषां यावन्न प्रकृतिर्भवेत् तावज्ज्वरेण मुक्तोऽपि वर्जनीयानि वर्जयेत्","text":"balavarṇāgnivapuṣāṃ yāvanna prakṛtirbhavet tāvajjvareṇa mukto'pi varjanīyāni varjayet"},{"type":"verse","number":"290","sanskrit":"वातलाहारचेष्टाभ्यां वायुरामाशयाश्रयः बहिर्निरस्य कोष्ठाग्निं ज्वरकृत्स्याद् रसानुगः","text":"vātalāhāraceṣṭābhyāṃ vāyurāmāśayāśrayaḥ bahirnirasya koṣṭhāgniṃ jvarakṛtsyād rasānugaḥ"},{"type":"verse","number":"291","sanskrit":"वेपथुर्विषमो वेगः कण्ठौष्ठमुखशोषणम् निद्रा नाशः क्षवस्तम्भो गात्राणां रौक्ष्यमेव च","text":"vepathurviṣamo vegaḥ kaṇṭhauṣṭhamukhaśoṣaṇam nidrā nāśaḥ kṣavastambho gātrāṇāṃ raukṣyameva ca"},{"type":"verse","number":"292","sanskrit":"शिरोहृद्गात्ररुग्वक्त्रवैरस्यां बद्धविट्कता शूलाध्माने जृम्भणञ्च भवन्त्यनिलजे ज्वरे","text":"śirohṛdgātrarugvaktravairasyāṃ baddhaviṭkatā śūlādhmāne jṛmbhaṇañca bhavantyanilaje jvare"},{"type":"verse","number":"293","sanskrit":"भवन्ति विविधा वातवेदनाः स्यादसुप्तता पिण्डिकोद्वेष्टनं कर्णस्वनो वक्त्रकषायता गात्रसादो हनुस्तम्भो विश्लेषः सन्धिजानुनोः","text":"bhavanti vividhā vātavedanāḥ syādasuptatā piṇḍikodveṣṭanaṃ karṇasvano vaktrakaṣāyatā gātrasādo hanustambho viśleṣaḥ sandhijānunoḥ"},{"type":"verse","number":"294","sanskrit":"शुष्ककासो वमिर्लोमदन्तहर्षः श्रमभ्रमौ अरुणं मूत्रनेत्रादि तृट्प्रलापोष्णगात्रताः","text":"śuṣkakāso vamirlomadantaharṣaḥ śramabhramau aruṇaṃ mūtranetrādi tṛṭpralāpoṣṇagātratāḥ"},{"type":"verse","number":"295","sanskrit":"ज्वरितं षडहेऽतीते लघ्वन्नं प्रतिभोजितम् पाचनं शमनीयञ्च कषायं पाययेद्भिषक्","text":"jvaritaṃ ṣaḍahe'tīte laghvannaṃ pratibhojitam pācanaṃ śamanīyañca kaṣāyaṃ pāyayedbhiṣak"},{"type":"verse","number":"296","sanskrit":"वातिके सप्तरात्रेण दशरात्रेण पैत्तिके श्लैष्मिके द्वादशाहेन ज्वरे युञ्जीत भेषजम्","text":"vātike saptarātreṇa daśarātreṇa paittike ślaiṣmike dvādaśāhena jvare yuñjīta bheṣajam"},{"type":"verse","number":"297","sanskrit":"दोषाणामेव सा शक्तिर्लङ्घने या सहिष्णुता न हि दोषक्षये कश्चित्सहते लङ्घनं महत्","text":"doṣāṇāmeva sā śaktirlaṅghane yā sahiṣṇutā na hi doṣakṣaye kaścitsahate laṅghanaṃ mahat"},{"type":"verse","number":"298","sanskrit":"कफपित्ते द्र्रवे धातू सहेते लङ्घनं बहु आमक्षयादूर्ध्वमपि वायुर्न सहते क्षणम्","text":"kaphapitte drrave dhātū sahete laṅghanaṃ bahu āmakṣayādūrdhvamapi vāyurna sahate kṣaṇam"},{"type":"verse","number":"299","sanskrit":"तत्र भेषजम् श्रीफलः सर्वतोभद्रा कामदूती च शोणकः तर्कारी गोक्षुरः क्षुद्रा बृहती कलशी स्थिरा","text":"tatra bheṣajam śrīphalaḥ sarvatobhadrā kāmadūtī ca śoṇakaḥ tarkārī gokṣuraḥ kṣudrā bṛhatī kalaśī sthirā"},{"type":"verse","number":"300","sanskrit":"रास्ना कणा कणामूलं कुष्ठं शुण्ठी किरातकः मुस्ता बलाऽमृता बालं द्रा क्षायासशताह्विकाः","text":"rāsnā kaṇā kaṇāmūlaṃ kuṣṭhaṃ śuṇṭhī kirātakaḥ mustā balā'mṛtā bālaṃ drā kṣāyāsaśatāhvikāḥ"},{"type":"verse","number":"301","sanskrit":"एषां क्वाथो निहन्त्येव प्रभञ्जनकृतं ज्वरम् सोपद्र वञ्च योगोऽय सर्वयोगवरः स्मृतः","text":"eṣāṃ kvātho nihantyeva prabhañjanakṛtaṃ jvaram sopadra vañca yogo'ya sarvayogavaraḥ smṛtaḥ"},{"type":"verse","number":"302","sanskrit":"त्रिशतीतर्कारी श्रीफलटुण्टुकपाटलामूलैः पाचनमुचितं मारुतजनितज्वरहारि वारिणा क्वथितैः","text":"triśatītarkārī śrīphalaṭuṇṭukapāṭalāmūlaiḥ pācanamucitaṃ mārutajanitajvarahāri vāriṇā kvathitaiḥ"},{"type":"verse","number":"303","sanskrit":"किराताब्दामृतोदीच्य बृहतीद्वयगोक्षुरैः त्रिपर्णीकलशीबिल्वैः क्वाथो वातज्वरापहः","text":"kirātābdāmṛtodīcya bṛhatīdvayagokṣuraiḥ triparṇīkalaśībilvaiḥ kvātho vātajvarāpahaḥ"},{"type":"verse","number":"304","sanskrit":"गुडूचीपिप्पलीमूलनागरैःपाचनं शृतम् वातज्वरे तथा पेयं कालिङ्गं सप्तमेऽहनि","text":"guḍūcīpippalīmūlanāgaraiḥpācanaṃ śṛtam vātajvare tathā peyaṃ kāliṅgaṃ saptame'hani"},{"type":"verse","number":"305","sanskrit":"विश्वाऽमृताग्रन्थिकसिद्धतोयं मरुज्ज्वरः स्यात्पिबतः कुतोऽयम् क्वाथोऽथ कुस्तुम्बुरुदेवदारुक्षुद्रौ षधैः पाचनमत्र चारु","text":"viśvā'mṛtāgranthikasiddhatoyaṃ marujjvaraḥ syātpibataḥ kuto'yam kvātho'tha kustumburudevadārukṣudrau ṣadhaiḥ pācanamatra cāru"},{"type":"verse","number":"306","sanskrit":"पञ्चमूलीवलारास्नाकुलत्थैः सह पौष्करैः क्वाथो हन्याच्छिरःकम्पं पर्वभेदं मरुज्ज्वरम्","text":"pañcamūlīvalārāsnākulatthaiḥ saha pauṣkaraiḥ kvātho hanyācchiraḥkampaṃ parvabhedaṃ marujjvaram"},{"type":"verse","number":"307","sanskrit":"कणारसोनामृतवल्लिविश्वानिदिग्धिकासिन्धुकभूमिनिम्बैः समुस्तकैराचरितः कषायो हिताशिनां हन्ति गदानिमांस्तु","text":"kaṇārasonāmṛtavalliviśvānidigdhikāsindhukabhūminimbaiḥ samustakairācaritaḥ kaṣāyo hitāśināṃ hanti gadānimāṃstu"},{"type":"verse","number":"308","sanskrit":"ज्वरं मरुद्दुष्टिसमुद्भवं तथा बलासजं चानलमन्दताञ्च कण्ठावरोधं हृदयावरोधं स्वेदञ्च रोमाञ्चहिमत्वमोहान्","text":"jvaraṃ marudduṣṭisamudbhavaṃ tathā balāsajaṃ cānalamandatāñca kaṇṭhāvarodhaṃ hṛdayāvarodhaṃ svedañca romāñcahimatvamohān"},{"type":"verse","number":"309","sanskrit":"अथ कल्पतरुरसः शुद्धं शंकरशुक्रमक्षतुलितं मारारिनारी रजस्तद्वत्तावदुमापतिस्फुट गलालङ्कारवस्तु स्मृतम् तावत्येव मनःशिला च विमला तावत्तथा टङ्कणंशुण्ठी द्व्यक्षमिता कणाच मरिचं दिक्पालसंख्याक्षकम्","text":"atha kalpatarurasaḥ śuddhaṃ śaṃkaraśukramakṣatulitaṃ mārārinārī rajastadvattāvadumāpatisphuṭa galālaṅkāravastu smṛtam tāvatyeva manaḥśilā ca vimalā tāvattathā ṭaṅkaṇaṃśuṇṭhī dvyakṣamitā kaṇāca maricaṃ dikpālasaṃkhyākṣakam"},{"type":"verse","number":"310","sanskrit":"विषादिवस्तूनि शिलोपरिष्टाद् विचूर्णयेद्बाससि शोधयेच्च ततस्तु खल्वे रसगन्धकौ च चूर्णञ्च तद्यामयुगंविमर्द्यम्","text":"viṣādivastūni śilopariṣṭād vicūrṇayedbāsasi śodhayecca tatastu khalve rasagandhakau ca cūrṇañca tadyāmayugaṃvimardyam"},{"type":"verse","number":"311","sanskrit":"कल्पतरुनामधेयो यथार्थनामा रसः श्रेष्ठ समीरणश्लेष्मगदान्हरते मात्राऽस्य स्मृता गुञ्जैका","text":"kalpatarunāmadheyo yathārthanāmā rasaḥ śreṣṭha samīraṇaśleṣmagadānharate mātrā'sya smṛtā guñjaikā"},{"type":"verse","number":"312","sanskrit":"आर्द्र्रकेण सममेष भक्षितो हन्ति वातकफसम्भवं ज्वरम् श्वासकासमुखसेकशीतता वह्निमान्द्यविसुचीश्च नाशयेत्","text":"ārdrrakeṇa samameṣa bhakṣito hanti vātakaphasambhavaṃ jvaram śvāsakāsamukhasekaśītatā vahnimāndyavisucīśca nāśayet"},{"type":"verse","number":"313","sanskrit":"नस्येनाश्वेव हरति शिरोर्तिं कफवातजाम् मोहं महान्तमपि च प्रलापं क्षवथुग्रहम्","text":"nasyenāśveva harati śirortiṃ kaphavātajām mohaṃ mahāntamapi ca pralāpaṃ kṣavathugraham"},{"type":"verse","number":"314","sanskrit":"सामन्यज्वरचिकित्सोक्तो महाज्वराङ्कुशः प्रदेयोऽत्र अथ त्रिपुरभैरवरसः विषमहौषधमागधिकोषणद्युमणिरक्तकमार्द्र्रकमर्दितम् क्रमविवर्द्धितमुद्दलितज्वरस्त्रिपुरभैरव एष रसो वरः","text":"sāmanyajvaracikitsokto mahājvarāṅkuśaḥ pradeyo'tra atha tripurabhairavarasaḥ viṣamahauṣadhamāgadhikoṣaṇadyumaṇiraktakamārdrrakamarditam kramavivarddhitamuddalitajvarastripurabhairava eṣa raso varaḥ"},{"type":"verse","number":"315","sanskrit":"वातश्लेष्मज्वरे स्वेदं जङ्घापार्श्वास्थिशूलिनि पीनसश्वासबाधिर्ये कारयेत्तद्विधानवित्","text":"vātaśleṣmajvare svedaṃ jaṅghāpārśvāsthiśūlini pīnasaśvāsabādhirye kārayettadvidhānavit"},{"type":"verse","number":"316","sanskrit":"स्रोतसां मार्दवं कृत्वा नीत्वा पावकमाशयम् हत्वा वातकफस्तम्भं स्वेदो ज्वरमपोहति","text":"srotasāṃ mārdavaṃ kṛtvā nītvā pāvakamāśayam hatvā vātakaphastambhaṃ svedo jvaramapohati"},{"type":"verse","number":"317","sanskrit":"खर्परभृष्टपटस्थितकाञ्जिकसंसिक्तबालुकास्वेदः शमयति वातकफामयशूलाङ्गभङ्गकम्पादीन्","text":"kharparabhṛṣṭapaṭasthitakāñjikasaṃsiktabālukāsvedaḥ śamayati vātakaphāmayaśūlāṅgabhaṅgakampādīn"},{"type":"verse","number":"318","sanskrit":"कम्पे शिरोहृदयगात्रव्यथायां जृम्भायां पादसुप्ततायाम् पिण्डिकोद्वेष्टनेऽङ्गसादे हनुस्तम्भे च लोमहर्षे","text":"kampe śirohṛdayagātravyathāyāṃ jṛmbhāyāṃ pādasuptatāyām piṇḍikodveṣṭane'ṅgasāde hanustambhe ca lomaharṣe"},{"type":"verse","number":"319","sanskrit":"मातुलुङ्गफलकेशरो धृतः सिन्धुजन्ममरिचान्वितो मुखे हन्ति वातकफरोगमास्यगं शोषमाशु जडतामरोचकम्","text":"mātuluṅgaphalakeśaro dhṛtaḥ sindhujanmamaricānvito mukhe hanti vātakapharogamāsyagaṃ śoṣamāśu jaḍatāmarocakam"},{"type":"verse","number":"320","sanskrit":"शर्करादाडिमाभ्याञ्च द्रा क्षादाडिमयोस्तथा कल्कं विधारयेदास्ये शोषवैरस्यनाशनम्","text":"śarkarādāḍimābhyāñca drā kṣādāḍimayostathā kalkaṃ vidhārayedāsye śoṣavairasyanāśanam"},{"type":"verse","number":"321","sanskrit":"द्रा क्षाऽमलकयोः कल्कं सघृतं वदने क्षिपेत् तेन घृष्ट्वा मुखस्यान्तः कुर्वीत प्रतिसारणम्","text":"drā kṣā'malakayoḥ kalkaṃ saghṛtaṃ vadane kṣipet tena ghṛṣṭvā mukhasyāntaḥ kurvīta pratisāraṇam"},{"type":"verse","number":"322","sanskrit":"तेन तालुगलान्तःस्थः संशोषश्चैव शाम्यति सुरसं जायते वक्त्रं रुचिर्भवति भोजने","text":"tena tālugalāntaḥsthaḥ saṃśoṣaścaiva śāmyati surasaṃ jāyate vaktraṃ rucirbhavati bhojane"},{"type":"verse","number":"323","sanskrit":"नावनं लङ्घनं चिन्ता व्यायामः शोकभीरुषः एभिरेव भवेन्निद्रा नाशः श्लेष्मातिसंक्षयात्","text":"nāvanaṃ laṅghanaṃ cintā vyāyāmaḥ śokabhīruṣaḥ ebhireva bhavennidrā nāśaḥ śleṣmātisaṃkṣayāt"},{"type":"verse","number":"324","sanskrit":"भृष्टन्तु विजयाचूर्णं मधुना निशि भक्षयेत् निद्रा नाशेऽतिसारे च ग्रहण्यां पावकक्षये","text":"bhṛṣṭantu vijayācūrṇaṃ madhunā niśi bhakṣayet nidrā nāśe'tisāre ca grahaṇyāṃ pāvakakṣaye"},{"type":"verse","number":"325","sanskrit":"गुडं पिप्पलिमूलस्य चूर्णेनालोडितं लिहेत् चिरादपि च संनष्टां निद्रा माप्नोति मानवः","text":"guḍaṃ pippalimūlasya cūrṇenāloḍitaṃ lihet cirādapi ca saṃnaṣṭāṃ nidrā māpnoti mānavaḥ"},{"type":"verse","number":"326","sanskrit":"वायसजङ्घामूलं बद्धं वा शिरसि काकमाच्याश्च विधृतं निद्रा जनकं त्वङ्मूलं वा शृतं सगुडम्","text":"vāyasajaṅghāmūlaṃ baddhaṃ vā śirasi kākamācyāśca vidhṛtaṃ nidrā janakaṃ tvaṅmūlaṃ vā śṛtaṃ saguḍam"},{"type":"verse","number":"327","sanskrit":"मूलन्तु काकमाच्या बद्धं सूत्रेण मस्तके नियतम् विदधाति नष्टनिद्रो निद्रा माश्वेव सिद्धमिदम्","text":"mūlantu kākamācyā baddhaṃ sūtreṇa mastake niyatam vidadhāti naṣṭanidro nidrā māśveva siddhamidam"},{"type":"verse","number":"328","sanskrit":"शीलयेन्मन्दनिद्र स्तु क्षीरमद्यरसान्दधि अभ्यङ्गोद्वर्त्तनस्नानमूर्द्धकर्णाक्षितर्पणम्","text":"śīlayenmandanidra stu kṣīramadyarasāndadhi abhyaṅgodvarttanasnānamūrddhakarṇākṣitarpaṇam"},{"type":"verse","number":"329","sanskrit":"कान्ताबाहुलताऽश्लेषो निर्वृतिः कृतकृत्यता मनोऽनुकूला विषयाः कामं निद्रा सुखप्रदाः","text":"kāntābāhulatā'śleṣo nirvṛtiḥ kṛtakṛtyatā mano'nukūlā viṣayāḥ kāmaṃ nidrā sukhapradāḥ"},{"type":"verse","number":"330","sanskrit":"रसे शाके च सूपे च सर्पिर्यूषपयःसु च निद्रां सञ्जनयत्याशु पलाण्डुरुपयोजितः","text":"rase śāke ca sūpe ca sarpiryūṣapayaḥsu ca nidrāṃ sañjanayatyāśu palāṇḍurupayojitaḥ"},{"type":"verse","number":"331","sanskrit":"एक्षवं पोतकी माषः सुरा मांसरसः पयः गोधूमतिलमत्स्याश्च निद्रां कुर्वन्ति देहिनाम्","text":"ekṣavaṃ potakī māṣaḥ surā māṃsarasaḥ payaḥ godhūmatilamatsyāśca nidrāṃ kurvanti dehinām"},{"type":"verse","number":"332","sanskrit":"दारुहैमवती कुष्ठशताह्वाहिङ्गुसैन्धवैः लिम्पेत्कोष्णैरम्लपिष्टैः शूलाध्मानयुतोदरम्","text":"dāruhaimavatī kuṣṭhaśatāhvāhiṅgusaindhavaiḥ limpetkoṣṇairamlapiṣṭaiḥ śūlādhmānayutodaram"},{"type":"verse","number":"333","sanskrit":"कटुतैलं कणाहिङ्गुवचालशुनसाधितम् उष्णं विनिहितं हन्ति कर्णयोर्निःस्वनं व्यथाम्","text":"kaṭutailaṃ kaṇāhiṅguvacālaśunasādhitam uṣṇaṃ vinihitaṃ hanti karṇayorniḥsvanaṃ vyathām"},{"type":"verse","number":"334","sanskrit":"कणा सुगन्धिवचया यवान्या च समन्विता ताम्बूलसहिता हन्ति शुष्ककासं मुखे धृता","text":"kaṇā sugandhivacayā yavānyā ca samanvitā tāmbūlasahitā hanti śuṣkakāsaṃ mukhe dhṛtā"},{"type":"verse","number":"335","sanskrit":"श्रमोपवासानिलजे हितो नित्यं रसौदनः मुद्गामलकयूषस्तु बद्धविट्काय दीयते","text":"śramopavāsānilaje hito nityaṃ rasaudanaḥ mudgāmalakayūṣastu baddhaviṭkāya dīyate"},{"type":"verse","number":"336","sanskrit":"पेयां वा रक्तशालीनां वस्तिपार्श्वशिरोरुजि श्वदंष्ट्रकण्टकारीभ्यां सिद्धां ज्वरहरीं पिबेत् कासी श्वासी च हिक्की च पञ्चमूलीशृतां पिबेत्","text":"peyāṃ vā raktaśālīnāṃ vastipārśvaśiroruji śvadaṃṣṭrakaṇṭakārībhyāṃ siddhāṃ jvaraharīṃ pibet kāsī śvāsī ca hikkī ca pañcamūlīśṛtāṃ pibet"},{"type":"verse","number":"337","sanskrit":"पित्तलाहारचेष्टायां पित्तमामाशयाश्रयम् बहिर्निरस्य कोष्ठाग्निंज्वरकृत्स्याद्र्रसानुगम्","text":"pittalāhāraceṣṭāyāṃ pittamāmāśayāśrayam bahirnirasya koṣṭhāgniṃjvarakṛtsyādrrasānugam"},{"type":"verse","number":"338","sanskrit":"वेगस्तीक्ष्णोऽतिसारश्च निद्रा ऽल्पत्वं तथा वमिः कण्ठौष्ठमुखनासानां पाकः स्वेदश्च जायते","text":"vegastīkṣṇo'tisāraśca nidrā 'lpatvaṃ tathā vamiḥ kaṇṭhauṣṭhamukhanāsānāṃ pākaḥ svedaśca jāyate"},{"type":"verse","number":"339","sanskrit":"प्रलापो वक्त्रकटुता मूर्च्छा दाहो मदस्तृषा पीतविण्मूत्र नेत्रत्वं पैत्तिके भ्रम एव च","text":"pralāpo vaktrakaṭutā mūrcchā dāho madastṛṣā pītaviṇmūtra netratvaṃ paittike bhrama eva ca"},{"type":"verse","number":"340","sanskrit":"पैत्तिके दशरात्रेण ज्वरे युञ्जीत भेषजम्","text":"paittike daśarātreṇa jvare yuñjīta bheṣajam"},{"type":"verse","number":"341","sanskrit":"अथ तिक्ताऽदिक्वाथः तिक्तामुस्तायवैः पाठाकट्फलाभ्यां सहोदकम् पक्वं सशर्करं पीतं पाचनं पैत्तिके ज्वरे","text":"atha tiktā'dikvāthaḥ tiktāmustāyavaiḥ pāṭhākaṭphalābhyāṃ sahodakam pakvaṃ saśarkaraṃ pītaṃ pācanaṃ paittike jvare"},{"type":"verse","number":"342","sanskrit":"अथ पर्पटादिक्वाथ पर्पटो वासकस्तिक्ता कैरातो धन्वयासकः प्रियङ्गुश्च कृतः क्वाथ एषां शर्करया युतः पिपासादाहपित्तास्रयुक्तं पित्तज्वरं हरेत्","text":"atha parpaṭādikvātha parpaṭo vāsakastiktā kairāto dhanvayāsakaḥ priyaṅguśca kṛtaḥ kvātha eṣāṃ śarkarayā yutaḥ pipāsādāhapittāsrayuktaṃ pittajvaraṃ haret"},{"type":"verse","number":"343","sanskrit":"अथ द्रा क्षाऽदिक्वाथः द्रा क्षा हरीतकी मुस्ता कटुका कृतमालकः पर्पटश्च कृतः क्वाथ एषां पित्तज्वरापहः","text":"atha drā kṣā'dikvāthaḥ drā kṣā harītakī mustā kaṭukā kṛtamālakaḥ parpaṭaśca kṛtaḥ kvātha eṣāṃ pittajvarāpahaḥ"},{"type":"verse","number":"344","sanskrit":"मुखशोषप्रलापार्त्तिदाह मूर्च्छाभ्रमप्रणुत् पिपासारक्तपित्तानां शमनो भेदनो मतः","text":"mukhaśoṣapralāpārttidāha mūrcchābhramapraṇut pipāsāraktapittānāṃ śamano bhedano mataḥ"},{"type":"verse","number":"345","sanskrit":"अथ पटोलादिक्वाथः पटोलयवधान्याकमधुकं मधुसंयुतम् हन्ति पित्तज्वरं दाहं तृष्णाञ्चातिप्रमाथिनीम्","text":"atha paṭolādikvāthaḥ paṭolayavadhānyākamadhukaṃ madhusaṃyutam hanti pittajvaraṃ dāhaṃ tṛṣṇāñcātipramāthinīm"},{"type":"verse","number":"346","sanskrit":"अथ गुडूच्यादिक्वाथः गुडूच्यामलकैर्युक्तः केवलो वाऽपि पर्पटः पित्तज्वरं हरेत्तूर्णं दाहशोषभ्रमान्वितम्","text":"atha guḍūcyādikvāthaḥ guḍūcyāmalakairyuktaḥ kevalo vā'pi parpaṭaḥ pittajvaraṃ harettūrṇaṃ dāhaśoṣabhramānvitam"},{"type":"verse","number":"347","sanskrit":"एकः पर्पटकः श्रेष्ठः पित्तज्वरविनाशनः किं पुनर्यदि युज्येत चन्दनोशीरबालकैः","text":"ekaḥ parpaṭakaḥ śreṣṭhaḥ pittajvaravināśanaḥ kiṃ punaryadi yujyeta candanośīrabālakaiḥ"},{"type":"verse","number":"348","sanskrit":"अथ ह्रीवेरादिक्वाथः ह्रीवेरचन्दनोशीरघनपर्पटसाधितम् दद्यात्सुशीतलं वारि तृट्छर्दिज्वरदाहनुत्","text":"atha hrīverādikvāthaḥ hrīveracandanośīraghanaparpaṭasādhitam dadyātsuśītalaṃ vāri tṛṭchardijvaradāhanut"},{"type":"verse","number":"349","sanskrit":"अथ भूनिम्बादिक्वाथः भूनिम्बातिविषालोध्रमुस्तकेन्द्र यवामृताः","text":"atha bhūnimbādikvāthaḥ bhūnimbātiviṣālodhramustakendra yavāmṛtāḥ"},{"type":"verse","number":"350","sanskrit":"बालकं धान्यकं बिल्वं कषायो माक्षिकान्वितः विड्भेदश्वासकासांश्च रक्तपित्तज्वरं हरेत्","text":"bālakaṃ dhānyakaṃ bilvaṃ kaṣāyo mākṣikānvitaḥ viḍbhedaśvāsakāsāṃśca raktapittajvaraṃ haret"},{"type":"verse","number":"351","sanskrit":"अथ महाद्रा क्षाऽदिक्वाथः द्रा क्षाचन्दनपद्मानि मुस्तातिक्ताऽमृताऽपि च धात्री बालमुशीरं च लोध्रेन्द्र यवपर्पटाः","text":"atha mahādrā kṣā'dikvāthaḥ drā kṣācandanapadmāni mustātiktā'mṛtā'pi ca dhātrī bālamuśīraṃ ca lodhrendra yavaparpaṭāḥ"},{"type":"verse","number":"352","sanskrit":"परूषकं प्रियङ्गुश्च यवासो वासकस्तथा मधुकं कुलकञ्चापि किरातो धान्यकं तथा","text":"parūṣakaṃ priyaṅguśca yavāso vāsakastathā madhukaṃ kulakañcāpi kirāto dhānyakaṃ tathā"},{"type":"verse","number":"353","sanskrit":"एषां क्वाथो निहन्त्येव ज्वरं पित्तसमुत्थितम् तृष्णां दाहं प्रलापञ्च रक्तपित्तं भ्रमं क्लमम्","text":"eṣāṃ kvātho nihantyeva jvaraṃ pittasamutthitam tṛṣṇāṃ dāhaṃ pralāpañca raktapittaṃ bhramaṃ klamam"},{"type":"verse","number":"354","sanskrit":"मृर्च्छां छर्दिं तथा शूलं मुखशोषमरोचकम् कासं श्वासञ्च हृल्लासं नाशयेन्नात्र संशयः","text":"mṛrcchāṃ chardiṃ tathā śūlaṃ mukhaśoṣamarocakam kāsaṃ śvāsañca hṛllāsaṃ nāśayennātra saṃśayaḥ"},{"type":"verse","number":"355","sanskrit":"अथ धान्याकक्वाथः ससितो निशि पर्युषितः प्रातर्धान्याकतण्डुलक्वाथः पीतः शमयत्यचिरादन्तर्दाहं ज्वरं पैत्तम्","text":"atha dhānyākakvāthaḥ sasito niśi paryuṣitaḥ prātardhānyākataṇḍulakvāthaḥ pītaḥ śamayatyacirādantardāhaṃ jvaraṃ paittam"},{"type":"verse","number":"356","sanskrit":"अथामृताहिमवासाहिमौ अमृतायाता हिमः प्रातः ससितः पैत्तिकं ज्वरम् वासायाश्च तथा कासरक्तपित्तज्वराञ्जयेत्","text":"athāmṛtāhimavāsāhimau amṛtāyātā himaḥ prātaḥ sasitaḥ paittikaṃ jvaram vāsāyāśca tathā kāsaraktapittajvarāñjayet"},{"type":"verse","number":"357","sanskrit":"अथद्वितीयो गुडूच्यादिक्वाथः गुडूची भूमिनिम्बश्च बालं वीरणमूलकम् लघुमुस्तं त्रिवृद्धात्री द्रा क्षा वासा च पर्पटः","text":"athadvitīyo guḍūcyādikvāthaḥ guḍūcī bhūminimbaśca bālaṃ vīraṇamūlakam laghumustaṃ trivṛddhātrī drā kṣā vāsā ca parpaṭaḥ"},{"type":"verse","number":"358","sanskrit":"एषां क्वाथो हरत्येव ज्वरं पित्तकृतं द्रुतम् सोपद्र्रवमपि प्रातर्निपीतो मधुना सह","text":"eṣāṃ kvātho haratyeva jvaraṃ pittakṛtaṃ drutam sopadrravamapi prātarnipīto madhunā saha"},{"type":"verse","number":"359","sanskrit":"पलाशस्य बदर्या वा निम्बस्य मृदुपल्लवैः अम्लपिष्टैः प्रलेपोऽय हन्याद्दाहयुतं ज्वरम्","text":"palāśasya badaryā vā nimbasya mṛdupallavaiḥ amlapiṣṭaiḥ pralepo'ya hanyāddāhayutaṃ jvaram"},{"type":"verse","number":"360","sanskrit":"उत्तानसुप्तस्य गभीरताम्रकांस्यादिपात्रे निहिते च नाभौ शीताम्बुधारा बहुला पतन्ती निहन्ति दाहं त्वरितं ज्वरं च","text":"uttānasuptasya gabhīratāmrakāṃsyādipātre nihite ca nābhau śītāmbudhārā bahulā patantī nihanti dāhaṃ tvaritaṃ jvaraṃ ca"},{"type":"verse","number":"361","sanskrit":"अथ पथ्याऽवलेहः पथ्यां तैलघृतक्षौद्र्रैर्लिहन्दाहज्वरापहाम् कासासृक्पित्तवीसर्पश्वासान्हन्ति वमीमपि","text":"atha pathyā'valehaḥ pathyāṃ tailaghṛtakṣaudrrairlihandāhajvarāpahām kāsāsṛkpittavīsarpaśvāsānhanti vamīmapi"},{"type":"verse","number":"362","sanskrit":"काञ्जिकार्द्र पटेनावगुण्ठनं दाहनाशनम् अथ गोतक्रसंस्विन्नशीतलीकृतवाससा","text":"kāñjikārdra paṭenāvaguṇṭhanaṃ dāhanāśanam atha gotakrasaṃsvinnaśītalīkṛtavāsasā"},{"type":"verse","number":"363","sanskrit":"द्रा क्षाऽमलककल्केन कवलोऽत्र हितो मतः पक्वदाडिमबीजैर्वा धानाकल्केन च क्वचित्","text":"drā kṣā'malakakalkena kavalo'tra hito mataḥ pakvadāḍimabījairvā dhānākalkena ca kvacit"},{"type":"verse","number":"364","sanskrit":"दाहकम्पार्दितं क्षामं निरन्नं तृष्णयान्वितम् शर्करामधुसंयुक्तं पाययेल्लाजतर्पणम्","text":"dāhakampārditaṃ kṣāmaṃ nirannaṃ tṛṣṇayānvitam śarkarāmadhusaṃyuktaṃ pāyayellājatarpaṇam"},{"type":"verse","number":"365","sanskrit":"मुद्गयूषौदनो देयः सितया पैत्तिके ज्वरे हर्म्ये शुभ्राभ्रसङ्काशे शशाङ्ककरशीतले मलयोद्भवसंसिक्ते सुप्यात्पित्तज्वरी नरः","text":"mudgayūṣaudano deyaḥ sitayā paittike jvare harmye śubhrābhrasaṅkāśe śaśāṅkakaraśītale malayodbhavasaṃsikte supyātpittajvarī naraḥ"},{"type":"verse","number":"366","sanskrit":"हारावलीचन्दनशीतलानां सुगन्धपुष्पाम्बरभूषितानाम् नितम्बिनीनां सुपयोधराणामालिङ्गनान्याशु हरन्ति दाहम्","text":"hārāvalīcandanaśītalānāṃ sugandhapuṣpāmbarabhūṣitānām nitambinīnāṃ supayodharāṇāmāliṅganānyāśu haranti dāham"},{"type":"verse","number":"367","sanskrit":"आह्लादश्चास्य विज्ञाय ताः स्त्रीरपनयेत्पुनः हितञ्च भोजयेदन्नं न प्रीतिसुरतंमहत्","text":"āhlādaścāsya vijñāya tāḥ strīrapanayetpunaḥ hitañca bhojayedannaṃ na prītisurataṃmahat"},{"type":"verse","number":"368","sanskrit":"वाप्यः कमलहासिन्यो जलयन्त्रगृहाः शुभाः नार्यश्चन्दनदिग्धाङ्ग्यो दाहदैन्यहरा मताः","text":"vāpyaḥ kamalahāsinyo jalayantragṛhāḥ śubhāḥ nāryaścandanadigdhāṅgyo dāhadainyaharā matāḥ"},{"type":"verse","number":"369","sanskrit":"इति पित्तज्वराधिकार अथ कफज्वराधिकारः श्लेष्मलाहारचेष्टाभ्यां कफो ह्यामाशयाश्रयः बहिर्निरस्य कोष्ठाग्निं ज्वरकृत्स्याद्र सानुगः","text":"iti pittajvarādhikāra atha kaphajvarādhikāraḥ śleṣmalāhāraceṣṭābhyāṃ kapho hyāmāśayāśrayaḥ bahirnirasya koṣṭhāgniṃ jvarakṛtsyādra sānugaḥ"},{"type":"verse","number":"370","sanskrit":"स्तैमित्यं स्तिमितोवेग आलस्यं मधुरास्यता शुक्लमूत्रपुरीषत्वं स्तम्भस्तृप्तिरथापि वा","text":"staimityaṃ stimitovega ālasyaṃ madhurāsyatā śuklamūtrapurīṣatvaṃ stambhastṛptirathāpi vā"},{"type":"verse","number":"371","sanskrit":"गौरवं शीतमुत्क्लेदो रोमहर्षोऽतिनिद्रि ता प्रतिश्यायोऽरूचिः कासः कफजेऽक्ष्णोश्च शुक्लता","text":"gauravaṃ śītamutkledo romaharṣo'tinidri tā pratiśyāyo'rūciḥ kāsaḥ kaphaje'kṣṇośca śuklatā"},{"type":"verse","number":"372","sanskrit":"श्लैष्मिके द्वादशाहेन ज्वरे युञ्जीत भेषजम् पिप्पल्यादिकषायन्तु कफजे परिपाचनम्","text":"ślaiṣmike dvādaśāhena jvare yuñjīta bheṣajam pippalyādikaṣāyantu kaphaje paripācanam"},{"type":"verse","number":"373","sanskrit":"पिप्पली पिप्पलीमूलं मरिचं गजपिप्पली नागरं चित्रकं चव्यं रेणुकैलाऽजमोदिकाः","text":"pippalī pippalīmūlaṃ maricaṃ gajapippalī nāgaraṃ citrakaṃ cavyaṃ reṇukailā'jamodikāḥ"},{"type":"verse","number":"374","sanskrit":"सर्षपो हिङ्गु भार्गी च पाठेन्द्र यवजीरकाः महानिम्बश्च मूर्वा च विषा तिक्ता विडङ्गकम्","text":"sarṣapo hiṅgu bhārgī ca pāṭhendra yavajīrakāḥ mahānimbaśca mūrvā ca viṣā tiktā viḍaṅgakam"},{"type":"verse","number":"375","sanskrit":"पिप्पल्यादिगणो ह्येषः कफमारुतनाशनः गुल्मशूलज्वरहरो दीपनस्त्वामपाचनः","text":"pippalyādigaṇo hyeṣaḥ kaphamārutanāśanaḥ gulmaśūlajvaraharo dīpanastvāmapācanaḥ"},{"type":"verse","number":"376","sanskrit":"क्षौद्रो पकुल्यासंयोगः श्वासकासज्वरापहः प्लीहानं हन्ति हिक्काञ्च बालानामपि शस्यते","text":"kṣaudro pakulyāsaṃyogaḥ śvāsakāsajvarāpahaḥ plīhānaṃ hanti hikkāñca bālānāmapi śasyate"},{"type":"verse","number":"377","sanskrit":"पिप्पलद्यं त्रिफलां चापि समभागां ज्वरी लिहन् मधुना सर्पिषा चापि कासी श्वासी सुखी भवेत्","text":"pippaladyaṃ triphalāṃ cāpi samabhāgāṃ jvarī lihan madhunā sarpiṣā cāpi kāsī śvāsī sukhī bhavet"},{"type":"verse","number":"378","sanskrit":"कट्फलं पौष्करं शृङ्गी कृष्णाच मधुना सह श्वासकासज्वरहरो लेहोऽय कफनाशनः","text":"kaṭphalaṃ pauṣkaraṃ śṛṅgī kṛṣṇāca madhunā saha śvāsakāsajvaraharo leho'ya kaphanāśanaḥ"},{"type":"verse","number":"379","sanskrit":"कट्फलं पौष्करं शृङ्गी यवानी कारवी तथा कटुत्रयञ्चसर्वाणि समभागानि चूर्णयेत्","text":"kaṭphalaṃ pauṣkaraṃ śṛṅgī yavānī kāravī tathā kaṭutrayañcasarvāṇi samabhāgāni cūrṇayet"},{"type":"verse","number":"380","sanskrit":"आर्द्र कस्वरसैर्लिह्यान्मधुना वा कफज्वरी कासश्वासारुचिच्छर्दिहिक्काश्लेष्मानिलापहः","text":"ārdra kasvarasairlihyānmadhunā vā kaphajvarī kāsaśvāsārucicchardihikkāśleṣmānilāpahaḥ"},{"type":"verse","number":"381","sanskrit":"सिन्दुवारदलक्वाथं कणाऽढ्य कफजे ज्वरे जङ्घयोश्च बले क्षीणे कर्णे च पिहिते पिबेत्","text":"sinduvāradalakvāthaṃ kaṇā'ḍhya kaphaje jvare jaṅghayośca bale kṣīṇe karṇe ca pihite pibet"},{"type":"verse","number":"382","sanskrit":"यवानी पिप्पली वासा तथा खाखसवल्कलम् एषां क्वाथं पिबेत्कासे श्वासे च कफजे ज्वरे","text":"yavānī pippalī vāsā tathā khākhasavalkalam eṣāṃ kvāthaṃ pibetkāse śvāse ca kaphaje jvare"},{"type":"verse","number":"383","sanskrit":"वासाक्षुद्रा ऽमृताक्वाथः क्षौद्रे ण ज्वरकासहृत्","text":"vāsākṣudrā 'mṛtākvāthaḥ kṣaudre ṇa jvarakāsahṛt"},{"type":"verse","number":"384","sanskrit":"मरिचं पिप्पलीमूलं नागरं कारवी कणा चित्रकं कट्फलं कुष्ठं ससुगन्धि वचा शिवा","text":"maricaṃ pippalīmūlaṃ nāgaraṃ kāravī kaṇā citrakaṃ kaṭphalaṃ kuṣṭhaṃ sasugandhi vacā śivā"},{"type":"verse","number":"385","sanskrit":"कण्टकारीजटा शृङ्गी यवानी पिचुमन्दकः एषां क्वाथो हरत्येव ज्वरं सोपद्र वं कफात्","text":"kaṇṭakārījaṭā śṛṅgī yavānī picumandakaḥ eṣāṃ kvātho haratyeva jvaraṃ sopadra vaṃ kaphāt"},{"type":"verse","number":"386","sanskrit":"कफवातव्याधिहरत्वाद्वाता धिकारोक्तकल्पतरुरसोयोज्यः सिन्धुत्रिकटुराजीभिरार्द्र केण कफे हितः","text":"kaphavātavyādhiharatvādvātā dhikāroktakalpatarurasoyojyaḥ sindhutrikaṭurājībhirārdra keṇa kaphe hitaḥ"},{"type":"verse","number":"387","sanskrit":"मुद्गयूषौदनो देयो ज्वरे कफसमुत्थिते","text":"mudgayūṣaudano deyo jvare kaphasamutthite"},{"type":"verse","number":"388","sanskrit":"इति श्लेष्म ज्वराधिकारः अथ वातपित्तज्वराधिकारः वातपित्तकरैर्वातपित्ते ह्यामाशयाश्रये बहिर्निरस्य कोष्ठाग्निं रसगे ज्वरकारिणी","text":"iti śleṣma jvarādhikāraḥ atha vātapittajvarādhikāraḥ vātapittakarairvātapitte hyāmāśayāśraye bahirnirasya koṣṭhāgniṃ rasage jvarakāriṇī"},{"type":"verse","number":"389","sanskrit":"प्राग्रूपे वातपित्तस्य भवतो वातपैत्तिके","text":"prāgrūpe vātapittasya bhavato vātapaittike"},{"type":"verse","number":"390","sanskrit":"तृष्णा मूर्च्छा भ्रमो दाहो निद्रा नाशः शिरोरुजा कण्ठास्यशोषो वमथू रोमहर्षोऽरुचिस्तमः पर्वभेदश्च जृम्भा च वातपित्तज्वराकृतिः","text":"tṛṣṇā mūrcchā bhramo dāho nidrā nāśaḥ śirorujā kaṇṭhāsyaśoṣo vamathū romaharṣo'rucistamaḥ parvabhedaśca jṛmbhā ca vātapittajvarākṛtiḥ"},{"type":"verse","number":"391","sanskrit":"वातपित्तज्वरे देयमौषधं पञ्चमेऽहनि","text":"vātapittajvare deyamauṣadhaṃ pañcame'hani"},{"type":"verse","number":"392","sanskrit":"किराततिक्तममृतां द्रा क्षामामलकं शटीम् निष्क्वाथ्य सगुडं क्वाथं वातपित्तज्वरे पिबेत्","text":"kirātatiktamamṛtāṃ drā kṣāmāmalakaṃ śaṭīm niṣkvāthya saguḍaṃ kvāthaṃ vātapittajvare pibet"},{"type":"verse","number":"393","sanskrit":"गुडूची पर्पटो मुस्तं किरातो विश्वभेषजम् वातपित्तज्वरे देयं पञ्चभद्र मिदं शुभम्","text":"guḍūcī parpaṭo mustaṃ kirāto viśvabheṣajam vātapittajvare deyaṃ pañcabhadra midaṃ śubham"},{"type":"verse","number":"394","sanskrit":"त्रिफलाशाल्मलीरास्नाराजवृक्षाटरूषकैः श्रृतमम्बु हरत्याशु वातपित्तभवं ज्वरम्","text":"triphalāśālmalīrāsnārājavṛkṣāṭarūṣakaiḥ śrṛtamambu haratyāśu vātapittabhavaṃ jvaram"},{"type":"verse","number":"395","sanskrit":"मधुकं सारिवा द्रा क्षा मधूकं चन्दनोत्पलम् काश्मरीफलकं लोध्रं त्रिफला पद्मकेशरम् परूषकं मृणालञ्च क्षिपेत्संचूर्ण्य वारिणि निशोषितं सिताक्षौद्र लाजयुक्तन्तु तत्पिबेत् वातपित्तज्वरं दाहं तृष्णां मूर्च्छाऽरुचिभ्रमान् शमयेद्र क्तपित्तञ्चजीमूतमिव मारुतः","text":"madhukaṃ sārivā drā kṣā madhūkaṃ candanotpalam kāśmarīphalakaṃ lodhraṃ triphalā padmakeśaram parūṣakaṃ mṛṇālañca kṣipetsaṃcūrṇya vāriṇi niśoṣitaṃ sitākṣaudra lājayuktantu tatpibet vātapittajvaraṃ dāhaṃ tṛṣṇāṃ mūrcchā'rucibhramān śamayedra ktapittañcajīmūtamiva mārutaḥ"},{"type":"verse","number":"396","sanskrit":"मुद्गामलकयूषस्तु वातपित्तज्वरे हितः महादाहे प्रदातव्यो यूषश्चणकसम्भवः","text":"mudgāmalakayūṣastu vātapittajvare hitaḥ mahādāhe pradātavyo yūṣaścaṇakasambhavaḥ"},{"type":"verse","number":"397","sanskrit":"दाडिमामलकमुद्गसम्भवो यूष उक्त इति वातपैत्तिके इति कफपित्तहरा मुद्गाः कारवेल्ल्यादयस्तथा प्रायेण न च ते देया वातपित्तोत्तरे ज्वरे दत्तास्तु ज्वरविष्टम्भशूलोदावर्त्तकारिणः","text":"dāḍimāmalakamudgasambhavo yūṣa ukta iti vātapaittike iti kaphapittaharā mudgāḥ kāravellyādayastathā prāyeṇa na ca te deyā vātapittottare jvare dattāstu jvaraviṣṭambhaśūlodāvarttakāriṇaḥ"},{"type":"verse","number":"398","sanskrit":"इति वातपित्तज्वराधिकारः समाप्तः अथ वातश्लेष्मज्वराधिकारः वातश्लेष्मकरैर्वातकफावामाशयाश्रयौ बहिर्निरस्य कोष्ठाग्निं रसगौ ज्वरकारिणौ","text":"iti vātapittajvarādhikāraḥ samāptaḥ atha vātaśleṣmajvarādhikāraḥ vātaśleṣmakarairvātakaphāvāmāśayāśrayau bahirnirasya koṣṭhāgniṃ rasagau jvarakāriṇau"},{"type":"verse","number":"399","sanskrit":"प्राग्रूपे वातकफयोः स्यातां वातकफज्वरे","text":"prāgrūpe vātakaphayoḥ syātāṃ vātakaphajvare"},{"type":"verse","number":"400","sanskrit":"स्तैमित्यं पर्वणां भेदो निद्रा गौरवमेव च शिरोग्रहः प्रतिश्यायः कासः स्वेदाप्रवर्त्तनम् सन्तापो मध्यवेगश्च वातश्लेष्मज्वराकृतिः","text":"staimityaṃ parvaṇāṃ bhedo nidrā gauravameva ca śirograhaḥ pratiśyāyaḥ kāsaḥ svedāpravarttanam santāpo madhyavegaśca vātaśleṣmajvarākṛtiḥ"},{"type":"verse","number":"401","sanskrit":"वातश्लेष्मज्वरे देयमौषधं नवमेऽहनि","text":"vātaśleṣmajvare deyamauṣadhaṃ navame'hani"},{"type":"verse","number":"402","sanskrit":"अथ पञ्चकोलम् पिप्पलीपिप्पली मूलचव्यचित्रकनागरैः दीपनीयः स्मृतो वर्गो वातश्लेष्मज्वरापहः","text":"atha pañcakolam pippalīpippalī mūlacavyacitrakanāgaraiḥ dīpanīyaḥ smṛto vargo vātaśleṣmajvarāpahaḥ"},{"type":"verse","number":"403","sanskrit":"कोलमात्रोपयोगित्वात्पञ्चकोलमिदं स्मृतम् तीक्ष्णोष्णं पाचनं श्रेष्ठं दीपनं कफदाहनुत् गुल्मप्लीहोदरानाहशूलघ्नं पित्तकोपनम्","text":"kolamātropayogitvātpañcakolamidaṃ smṛtam tīkṣṇoṣṇaṃ pācanaṃ śreṣṭhaṃ dīpanaṃ kaphadāhanut gulmaplīhodarānāhaśūlaghnaṃ pittakopanam"},{"type":"verse","number":"404","sanskrit":"अथ द्वितीयः किरातादिक्वाथः किरातविश्वाऽमृतवल्लिसिंहिकाव्याघ्रीकणामूलरसोनसिन्दुकैः कृतः कषायो विनिहन्ति सत्वरं ज्वरं समीरात्सकफात्समुत्त्थितम्","text":"atha dvitīyaḥ kirātādikvāthaḥ kirātaviśvā'mṛtavallisiṃhikāvyāghrīkaṇāmūlarasonasindukaiḥ kṛtaḥ kaṣāyo vinihanti satvaraṃ jvaraṃ samīrātsakaphātsamuttthitam"},{"type":"verse","number":"405","sanskrit":"अथ पिप्पल्यादिक्वाथः पिप्पल्यादिगणक्वाथं पिबेद्वातकफज्वरी नातः परं किञ्चिदस्ति ज्वरे भेषजमुत्तमम्","text":"atha pippalyādikvāthaḥ pippalyādigaṇakvāthaṃ pibedvātakaphajvarī nātaḥ paraṃ kiñcidasti jvare bheṣajamuttamam"},{"type":"verse","number":"406","sanskrit":"अथ बृहत्पिप्पल्यादिक्वाथः पिप्पली पिप्पलीमूलं चव्यचित्रकनागरम् वचा सातिविषाऽजाजी पाठावत्सकरेणुकाः","text":"atha bṛhatpippalyādikvāthaḥ pippalī pippalīmūlaṃ cavyacitrakanāgaram vacā sātiviṣā'jājī pāṭhāvatsakareṇukāḥ"},{"type":"verse","number":"407","sanskrit":"किराततिक्तको मूर्वा सर्षपा मरिचानि च कट्फलं पुष्करं भार्गो विडङ्गंकर्कटाह्वयम्","text":"kirātatiktako mūrvā sarṣapā maricāni ca kaṭphalaṃ puṣkaraṃ bhārgo viḍaṅgaṃkarkaṭāhvayam"},{"type":"verse","number":"408","sanskrit":"अर्कमूलं वृहत्सिंही श्रेयसी सदुरालभा दीप्यकश्चाजमोदा च शुकनासा सहिङ्गुका","text":"arkamūlaṃ vṛhatsiṃhī śreyasī sadurālabhā dīpyakaścājamodā ca śukanāsā sahiṅgukā"},{"type":"verse","number":"409","sanskrit":"एतानि समभागानि गण एकोऽष्टविंशतिः एषां क्वाथो निपीतः स्याद्वातश्लेष्मज्वरापहः","text":"etāni samabhāgāni gaṇa eko'ṣṭaviṃśatiḥ eṣāṃ kvātho nipītaḥ syādvātaśleṣmajvarāpahaḥ"},{"type":"verse","number":"410","sanskrit":"हन्ति वातं तथा शीतं प्रस्वेदमतिवेपथुम् प्रलापञ्चातिनिद्रा ञ्च रोमहर्षारुची तथा","text":"hanti vātaṃ tathā śītaṃ prasvedamativepathum pralāpañcātinidrā ñca romaharṣārucī tathā"},{"type":"verse","number":"411","sanskrit":"महावातेऽपतन्त्रे च शून्यत्वे सर्वगात्रजे पिप्पल्यादिमहाक्वाथो ज्वरे सर्वत्र पूजितः","text":"mahāvāte'patantre ca śūnyatve sarvagātraje pippalyādimahākvātho jvare sarvatra pūjitaḥ"},{"type":"verse","number":"412","sanskrit":"अथ दशमूलीक्वाथः दशमूलीरसः पीतः कणाऽढ्य कफवातजे ज्वरेऽविपाके निद्रा यां पार्श्वरुक्छ्वासकासके","text":"atha daśamūlīkvāthaḥ daśamūlīrasaḥ pītaḥ kaṇā'ḍhya kaphavātaje jvare'vipāke nidrā yāṃ pārśvarukchvāsakāsake"},{"type":"verse","number":"413","sanskrit":"अथ पिप्पलीक्वाथः पिप्पलीभिः शृतं तोयमनभिष्यन्दि दीपनम् वातश्लेष्मज्वरं हन्ति सेवितं प्लीहनाशनम्","text":"atha pippalīkvāthaḥ pippalībhiḥ śṛtaṃ toyamanabhiṣyandi dīpanam vātaśleṣmajvaraṃ hanti sevitaṃ plīhanāśanam"},{"type":"verse","number":"414","sanskrit":"अथ सूर्यशेखररसः सूतकं टङ्कणं भृष्टं गन्धं शुद्धं समं समम् द्विगुणं सूतकाद्देयं जैपालं तुषवर्जितम्","text":"atha sūryaśekhararasaḥ sūtakaṃ ṭaṅkaṇaṃ bhṛṣṭaṃ gandhaṃ śuddhaṃ samaṃ samam dviguṇaṃ sūtakāddeyaṃ jaipālaṃ tuṣavarjitam"},{"type":"verse","number":"415","sanskrit":"सैन्धवं मरिचं चिञ्चात्वक्क्षारः शर्कराऽपि च प्रत्येकं सूततुल्यं स्याज्जम्बीरैर्मर्दयेद्दिनम्","text":"saindhavaṃ maricaṃ ciñcātvakkṣāraḥ śarkarā'pi ca pratyekaṃ sūtatulyaṃ syājjambīrairmardayeddinam"},{"type":"verse","number":"416","sanskrit":"सूर्यशेखरनामाऽय रसो गुञ्जाद्वयोन्मितः भक्षितस्तप्ततोयेन वातश्लेष्मज्वरापहः","text":"sūryaśekharanāmā'ya raso guñjādvayonmitaḥ bhakṣitastaptatoyena vātaśleṣmajvarāpahaḥ"},{"type":"verse","number":"417","sanskrit":"स्वेदोद्गमे भृष्टकुलत्थचूर्णनिपातनं शस्तमिति ब्रुवन्ति जीर्णं शकृद्गोर्लवणस्य भाजनं संचूर्णितं स्वेदहरं सुधूलनात्","text":"svedodgame bhṛṣṭakulatthacūrṇanipātanaṃ śastamiti bruvanti jīrṇaṃ śakṛdgorlavaṇasya bhājanaṃ saṃcūrṇitaṃ svedaharaṃ sudhūlanāt"},{"type":"verse","number":"418","sanskrit":"अथ मरिचाद्युद्धूलनम् मरिचं पिप्पली शुण्ठी पथ्या लोध्रञ्च पौष्करम् भूनिम्बः कटुकाकुष्ठं कचूरोलिङ्गिका शटी","text":"atha maricādyuddhūlanam maricaṃ pippalī śuṇṭhī pathyā lodhrañca pauṣkaram bhūnimbaḥ kaṭukākuṣṭhaṃ kacūroliṅgikā śaṭī"},{"type":"verse","number":"419","sanskrit":"एतानि समभागानि सूक्ष्मचूर्णानि कारयेत् एतदुद्धूलनं श्रेष्ठं स्रोतोवत्स्वेदनिर्गमे","text":"etāni samabhāgāni sūkṣmacūrṇāni kārayet etaduddhūlanaṃ śreṣṭhaṃ srotovatsvedanirgame"},{"type":"verse","number":"420","sanskrit":"अथ भूनिम्बाद्युद्धूलनम् भूनिम्बः कारवी तिक्ता वचा कट्फलजं रजः एषामुद्धूलनं श्रेष्ठं सततं स्वेदसंस्रवे","text":"atha bhūnimbādyuddhūlanam bhūnimbaḥ kāravī tiktā vacā kaṭphalajaṃ rajaḥ eṣāmuddhūlanaṃ śreṣṭhaṃ satataṃ svedasaṃsrave"},{"type":"verse","number":"421","sanskrit":"अथ वालुका स्वेदः पूर्वोक्तो वालुकास्वेदोऽप्यत्र समुचितः यदुक्तम् पीनसश्वासबाधिर्यजङ्घापार्श्वास्थिशूलिनि वातश्लेष्मज्वरे देयमौषधं तद्विधानवित्","text":"atha vālukā svedaḥ pūrvokto vālukāsvedo'pyatra samucitaḥ yaduktam pīnasaśvāsabādhiryajaṅghāpārśvāsthiśūlini vātaśleṣmajvare deyamauṣadhaṃ tadvidhānavit"},{"type":"verse","number":"422","sanskrit":"मातुलुङ्गफलकेशरो धृतः सिन्धुजन्ममरिचान्वितो मुखे हन्तिवातकफरोगमास्यगं शोषमाशु जडतामरोचकम्","text":"mātuluṅgaphalakeśaro dhṛtaḥ sindhujanmamaricānvito mukhe hantivātakapharogamāsyagaṃ śoṣamāśu jaḍatāmarocakam"},{"type":"verse","number":"423","sanskrit":"महत्या पञ्चमूल्याऽन्न सम्यक्सिद्धं चिकित्सकः सप्तमे दिवसे दद्याज्ज्वरे वातवलासजे","text":"mahatyā pañcamūlyā'nna samyaksiddhaṃ cikitsakaḥ saptame divase dadyājjvare vātavalāsaje"},{"type":"verse","number":"424","sanskrit":"इति वात कफज्वराधिकारः समाप्तः अथ पित्तकफज्वराधिकारः पित्तश्लेष्मकरैः पित्तकफावामाशयाश्रयौ बहिर्निरस्य कोष्ठाग्निं रसगौज्वरकारिणौ","text":"iti vāta kaphajvarādhikāraḥ samāptaḥ atha pittakaphajvarādhikāraḥ pittaśleṣmakaraiḥ pittakaphāvāmāśayāśrayau bahirnirasya koṣṭhāgniṃ rasagaujvarakāriṇau"},{"type":"verse","number":"425","sanskrit":"प्राग्रूपे पित्तकफयोः स्यातां पित्तकफज्वरे","text":"prāgrūpe pittakaphayoḥ syātāṃ pittakaphajvare"},{"type":"verse","number":"426","sanskrit":"लिप्ततिक्तास्यता तन्द्रा मोहः कासोऽरुचिस्तृषा मुहुर्दाहो मुहुः शीतं पित्तश्लेष्मज्वराकृतिः","text":"liptatiktāsyatā tandrā mohaḥ kāso'rucistṛṣā muhurdāho muhuḥ śītaṃ pittaśleṣmajvarākṛtiḥ"},{"type":"verse","number":"427","sanskrit":"पित्तश्लेष्मज्वरे देयमौषधं दशमेऽहनि","text":"pittaśleṣmajvare deyamauṣadhaṃ daśame'hani"},{"type":"verse","number":"428","sanskrit":"गुडूची निम्बधान्याकं चन्दनं कटुरोहिणी गुडूच्यादिरयं क्वाथः पाचनो दीपनः स्मृतः तृष्णादाहारुचिच्छर्दिपित्तश्लेष्मज्वरापहः","text":"guḍūcī nimbadhānyākaṃ candanaṃ kaṭurohiṇī guḍūcyādirayaṃ kvāthaḥ pācano dīpanaḥ smṛtaḥ tṛṣṇādāhārucicchardipittaśleṣmajvarāpahaḥ"},{"type":"verse","number":"429","sanskrit":"अमृताकटुकाऽरिष्टपटोलघनचन्दनम् नागरेन्द्र यवं चैतदमृताष्टकमीरितम्","text":"amṛtākaṭukā'riṣṭapaṭolaghanacandanam nāgarendra yavaṃ caitadamṛtāṣṭakamīritam"},{"type":"verse","number":"430","sanskrit":"क्वथितं सकणाचूर्णं पित्तश्लेष्मज्वरापहम् हृल्लासारोचकच्छर्दितृष्णादाहनिवारणम्","text":"kvathitaṃ sakaṇācūrṇaṃ pittaśleṣmajvarāpaham hṛllāsārocakaccharditṛṣṇādāhanivāraṇam"},{"type":"verse","number":"431","sanskrit":"अथ कण्टकार्यादिक्वाथः कण्टकार्यमृताभार्गी विश्वेन्द्र्रयववासकम् भूनिम्बं चन्दनं मुस्तं पटोलं कटुरोहिणीम्","text":"atha kaṇṭakāryādikvāthaḥ kaṇṭakāryamṛtābhārgī viśvendrrayavavāsakam bhūnimbaṃ candanaṃ mustaṃ paṭolaṃ kaṭurohiṇīm"},{"type":"verse","number":"432","sanskrit":"विपाच्य पाययेत्क्वाथं पित्तश्लेष्मज्वरापहम् दाहतृष्णाऽरुचिच्छर्दिकासशूलनिवारणम्","text":"vipācya pāyayetkvāthaṃ pittaśleṣmajvarāpaham dāhatṛṣṇā'rucicchardikāsaśūlanivāraṇam"},{"type":"verse","number":"433","sanskrit":"नागरोशीरबिल्वाब्द धान्यमोचरसाम्बुभिः कृतः क्वाथो भवेद् ग्राही पित्तश्लेष्मज्वरापहः","text":"nāgarośīrabilvābda dhānyamocarasāmbubhiḥ kṛtaḥ kvātho bhaved grāhī pittaśleṣmajvarāpahaḥ"},{"type":"verse","number":"434","sanskrit":"शर्करामक्षमात्राञ्च कटुकीं चोष्णवारिणा पीत्वा ज्वरं जयेज्जन्तुः पित्तश्लेष्मसमुद्भवम्","text":"śarkarāmakṣamātrāñca kaṭukīṃ coṣṇavāriṇā pītvā jvaraṃ jayejjantuḥ pittaśleṣmasamudbhavam"},{"type":"verse","number":"435","sanskrit":"सपत्रपुष्पवासाया रसः क्षौद्र सितायुतः पित्तष्लेमज्वरं हन्ति साम्लपित्तं सकामलम्","text":"sapatrapuṣpavāsāyā rasaḥ kṣaudra sitāyutaḥ pittaṣlemajvaraṃ hanti sāmlapittaṃ sakāmalam"},{"type":"verse","number":"436","sanskrit":"कषायः परिपीतस्तु शृङ्गबेरपटोलयोः पित्तश्लेष्मज्वरवमीदाहकण्डूहरो भवेत्","text":"kaṣāyaḥ paripītastu śṛṅgaberapaṭolayoḥ pittaśleṣmajvaravamīdāhakaṇḍūharo bhavet"},{"type":"verse","number":"437","sanskrit":"पटोलधान्ययोर्यूषः पित्तश्लेष्मज्वरापहः","text":"paṭoladhānyayoryūṣaḥ pittaśleṣmajvarāpahaḥ"},{"type":"verse","number":"438","sanskrit":"इति पित्तकफज्वराधिकारः समाप्तः अथ सन्निपातज्वराधिकारः त्रिदोषजनकैर्वातः पित्तां श्लेष्माऽमगेहगाः बहिर्निरस्य कोष्ठाग्निं रसगा ज्वरकारिणः","text":"iti pittakaphajvarādhikāraḥ samāptaḥ atha sannipātajvarādhikāraḥ tridoṣajanakairvātaḥ pittāṃ śleṣmā'magehagāḥ bahirnirasya koṣṭhāgniṃ rasagā jvarakāriṇaḥ"},{"type":"verse","number":"439","sanskrit":"क्षणे दाहः क्षणे शीतमस्थिसन्धिशिरोरुजा सास्रावे कलुषे रक्ते निर्भुग्ने चापि लोचने","text":"kṣaṇe dāhaḥ kṣaṇe śītamasthisandhiśirorujā sāsrāve kaluṣe rakte nirbhugne cāpi locane"},{"type":"verse","number":"440","sanskrit":"सस्वनौ सरुजौ कर्णौ कण्ठः शूकैरिवावृतः तन्द्रा मोहः प्रलापश्च कासः श्वासोऽरुचिर्भ्रमः","text":"sasvanau sarujau karṇau kaṇṭhaḥ śūkairivāvṛtaḥ tandrā mohaḥ pralāpaśca kāsaḥ śvāso'rucirbhramaḥ"},{"type":"verse","number":"441","sanskrit":"परिदग्धा खरस्पर्शा जिह्वा स्रस्ताङ्गता परा ष्ठीवनं रक्तपित्तस्य कफेनोन्मिश्रितस्य च शिरसो लोठनं तृष्णा निद्रा नाशो हृदि व्यथा स्वेदमूत्रपुरीषाणां चिराद्दर्शनमल्पशः","text":"paridagdhā kharasparśā jihvā srastāṅgatā parā ṣṭhīvanaṃ raktapittasya kaphenonmiśritasya ca śiraso loṭhanaṃ tṛṣṇā nidrā nāśo hṛdi vyathā svedamūtrapurīṣāṇāṃ cirāddarśanamalpaśaḥ"},{"type":"verse","number":"442","sanskrit":"कृशत्वं नातिगात्राणां प्रततं कण्ठकूजनम् कोठानां श्यावरक्तानां मण्डलानाञ्च दर्शनम्","text":"kṛśatvaṃ nātigātrāṇāṃ pratataṃ kaṇṭhakūjanam koṭhānāṃ śyāvaraktānāṃ maṇḍalānāñca darśanam"},{"type":"verse","number":"443","sanskrit":"मूकत्वं स्रोतसां पाको गुरुत्वमुदरस्य च चिरात्पाकश्च दोषाणांसन्निपातज्वराकृतिः","text":"mūkatvaṃ srotasāṃ pāko gurutvamudarasya ca cirātpākaśca doṣāṇāṃsannipātajvarākṛtiḥ"},{"type":"verse","number":"444","sanskrit":"एकोल्वणास्त्रयस्तेषु द्व्युल्वणाश्च तथेति षट् त्र्युल्वणश्च भवेदेको विज्ञेयः स तु सप्तमः","text":"ekolvaṇāstrayasteṣu dvyulvaṇāśca tatheti ṣaṭ tryulvaṇaśca bhavedeko vijñeyaḥ sa tu saptamaḥ"},{"type":"verse","number":"445","sanskrit":"प्रवृद्धमध्यहीनैस्तु वातपित्तकफैश्च षट् सन्निपातज्वरस्यैवं स्युर्विशेषास्त्रयोदश","text":"pravṛddhamadhyahīnaistu vātapittakaphaiśca ṣaṭ sannipātajvarasyaivaṃ syurviśeṣāstrayodaśa"},{"type":"verse","number":"446","sanskrit":"विस्फारकश्चाशुकारी कम्पनो बभ्रसंज्ञकः शीघ्रकारी तथा भल्लुः सप्तमः कूटपाकलः","text":"visphārakaścāśukārī kampano babhrasaṃjñakaḥ śīghrakārī tathā bhalluḥ saptamaḥ kūṭapākalaḥ"},{"type":"verse","number":"447","sanskrit":"सम्मोहकः पाकलश्च याम्यः क्रकच इत्यपि ततः कर्कटकः प्रोक्तस्ततो वैदारिकाभिधः","text":"sammohakaḥ pākalaśca yāmyaḥ krakaca ityapi tataḥ karkaṭakaḥ proktastato vaidārikābhidhaḥ"},{"type":"verse","number":"448","sanskrit":"तत्र वातोल्वणविस्फारकलक्षणम् श्वासः कासो भ्रमो मूर्च्छा प्रलापो मोहवेपथू पार्श्वस्य वेदना जृम्भा कषायत्वं मुखस्य च","text":"tatra vātolvaṇavisphārakalakṣaṇam śvāsaḥ kāso bhramo mūrcchā pralāpo mohavepathū pārśvasya vedanā jṛmbhā kaṣāyatvaṃ mukhasya ca"},{"type":"verse","number":"449","sanskrit":"वातोल्वणस्य लिङ्गानि सन्निपातस्य लक्षयेत् एष विस्फारको नाम्ना सन्निपातः सुदारुणः","text":"vātolvaṇasya liṅgāni sannipātasya lakṣayet eṣa visphārako nāmnā sannipātaḥ sudāruṇaḥ"},{"type":"verse","number":"450","sanskrit":"अतिसारो भ्रमो मूर्च्छा मुखपाकस्तथैव च गात्रे च बिन्दवो रक्ता दाहोऽतीव प्रजायते","text":"atisāro bhramo mūrcchā mukhapākastathaiva ca gātre ca bindavo raktā dāho'tīva prajāyate"},{"type":"verse","number":"451","sanskrit":"पित्तोल्वणस्य लिङ्गानि सन्निपातस्य लक्षयेत् भिषग्भिः सन्निपातोऽयमाशुकारी प्रकीर्त्तितः","text":"pittolvaṇasya liṅgāni sannipātasya lakṣayet bhiṣagbhiḥ sannipāto'yamāśukārī prakīrttitaḥ"},{"type":"verse","number":"452","sanskrit":"जडता गद्गदा वाणी रात्रौ निद्रा भवत्यपि प्रस्तब्धे नयने चैव मुखमाधुर्यमेव च","text":"jaḍatā gadgadā vāṇī rātrau nidrā bhavatyapi prastabdhe nayane caiva mukhamādhuryameva ca"},{"type":"verse","number":"453","sanskrit":"कफोल्वणस्य लिङ्गानि सन्निपातस्य लक्षयेत् मुनिभिः सन्निपातोऽयमुक्तःकम्पनसंज्ञकः","text":"kapholvaṇasya liṅgāni sannipātasya lakṣayet munibhiḥ sannipāto'yamuktaḥkampanasaṃjñakaḥ"},{"type":"verse","number":"454","sanskrit":"वातपित्ताधिको यस्तु सन्निपातः प्रकुप्यति तस्य ज्वरो मदस्तृष्णा मुखशोषः प्रमीलकः","text":"vātapittādhiko yastu sannipātaḥ prakupyati tasya jvaro madastṛṣṇā mukhaśoṣaḥ pramīlakaḥ"},{"type":"verse","number":"455","sanskrit":"आध्मानारुचितन्द्रा श्च कासश्वासभ्रमश्रमाः मुनिभिर्बभ्रनामाऽय सन्निपात उदाहृतः","text":"ādhmānārucitandrā śca kāsaśvāsabhramaśramāḥ munibhirbabhranāmā'ya sannipāta udāhṛtaḥ"},{"type":"verse","number":"456","sanskrit":"वातश्लेष्माधिको यस्य सन्निपातः प्रकुप्यति तस्य शीतज्वरो मूर्च्छा क्षुत्तृष्णा पार्श्वनिग्रहः","text":"vātaśleṣmādhiko yasya sannipātaḥ prakupyati tasya śītajvaro mūrcchā kṣuttṛṣṇā pārśvanigrahaḥ"},{"type":"verse","number":"457","sanskrit":"शूलमस्विद्यमानस्य तन्द्रा श्वासश्च जायते असाध्यः सन्निपातोऽय शीघ्रकारीति कथ्यते न हि जीवत्यहोरात्रमनेनाविष्टविग्रहः","text":"śūlamasvidyamānasya tandrā śvāsaśca jāyate asādhyaḥ sannipāto'ya śīghrakārīti kathyate na hi jīvatyahorātramanenāviṣṭavigrahaḥ"},{"type":"verse","number":"458","sanskrit":"पित्तश्लेष्माधिको यस्य सन्निपातः प्रकुप्यति अन्तर्दाहो बहिः शीतं तस्य तृष्णा प्रवर्द्धते","text":"pittaśleṣmādhiko yasya sannipātaḥ prakupyati antardāho bahiḥ śītaṃ tasya tṛṣṇā pravarddhate"},{"type":"verse","number":"459","sanskrit":"तुद्यते दक्षिणे पार्श्वे उरःशीर्षगलग्रहः ष्ठीवति श्लेष्मपित्तञ्च कृच्छ्रात्कोठश्च जायते","text":"tudyate dakṣiṇe pārśve uraḥśīrṣagalagrahaḥ ṣṭhīvati śleṣmapittañca kṛcchrātkoṭhaśca jāyate"},{"type":"verse","number":"460","sanskrit":"विड्भेदश्वासहिक्काश्च वर्द्धन्ते सप्रमीलकाः ऋषिभिर्भल्लुनामाऽय सन्निपात उदाहृतः","text":"viḍbhedaśvāsahikkāśca varddhante sapramīlakāḥ ṛṣibhirbhallunāmā'ya sannipāta udāhṛtaḥ"},{"type":"verse","number":"461","sanskrit":"सर्वदोषोल्वणो यस्य सन्निपातः प्रकुप्यति त्रयाणामपि दोषाणां तस्य रूपाणि लक्षयेत्","text":"sarvadoṣolvaṇo yasya sannipātaḥ prakupyati trayāṇāmapi doṣāṇāṃ tasya rūpāṇi lakṣayet"},{"type":"verse","number":"462","sanskrit":"व्याधिभ्यो दारूणश्चैव वज्रशस्त्राग्निसन्निभः केवलोच्छ्वासपरमः स्तब्धाङ्गः स्तब्धलोचनः","text":"vyādhibhyo dārūṇaścaiva vajraśastrāgnisannibhaḥ kevalocchvāsaparamaḥ stabdhāṅgaḥ stabdhalocanaḥ"},{"type":"verse","number":"463","sanskrit":"त्रिरात्रात्परमेतस्य जन्तोर्हरति जीवितम् तदवस्थन्तु तं दृष्ट्वा मूढो व्याहरते जनः","text":"trirātrātparametasya jantorharati jīvitam tadavasthantu taṃ dṛṣṭvā mūḍho vyāharate janaḥ"},{"type":"verse","number":"464","sanskrit":"धर्षितो राक्षसैर्नूनमवेलायां चरन्ति ये अम्बया ब्रुवते केचिद्यक्षिण्या ब्रह्मराक्षसैः","text":"dharṣito rākṣasairnūnamavelāyāṃ caranti ye ambayā bruvate kecidyakṣiṇyā brahmarākṣasaiḥ"},{"type":"verse","number":"465","sanskrit":"पिशाचैर्गुह्यकैश्चैव तथाऽन्यैर्मस्तके हतम् कुलदेवार्च्चनाहीनं धर्षितं कुलदैवतैः","text":"piśācairguhyakaiścaiva tathā'nyairmastake hatam kuladevārccanāhīnaṃ dharṣitaṃ kuladaivataiḥ"},{"type":"verse","number":"466","sanskrit":"नक्षत्रपीडामपरे गरकर्मेति चापरे सन्निपातमिमं प्राहुर्भिषजः कूटपाकलम्","text":"nakṣatrapīḍāmapare garakarmeti cāpare sannipātamimaṃ prāhurbhiṣajaḥ kūṭapākalam"},{"type":"verse","number":"467","sanskrit":"प्रवृद्धमध्यहीनैस्तु वातपित्तकफैश्च यः तेन रोगास्त एवोक्ता यथादोषबलाश्रयाः","text":"pravṛddhamadhyahīnaistu vātapittakaphaiśca yaḥ tena rogāsta evoktā yathādoṣabalāśrayāḥ"},{"type":"verse","number":"468","sanskrit":"प्रलापायाससम्मोहकम्पमूर्च्छाऽरतिभ्रमाः एकपक्षाभिघातश्च तत्राप्येते विशेषतः","text":"pralāpāyāsasammohakampamūrcchā'ratibhramāḥ ekapakṣābhighātaśca tatrāpyete viśeṣataḥ"},{"type":"verse","number":"469","sanskrit":"एष सम्मोहको नाम्ना सन्निपातः सुदारुणः","text":"eṣa sammohako nāmnā sannipātaḥ sudāruṇaḥ"},{"type":"verse","number":"470","sanskrit":"मध्यप्रवृद्धहीनैस्तु वातपित्तकफैश्च यः तेन रोगास्त एवोक्ता यथादोषवलाश्रयाः","text":"madhyapravṛddhahīnaistu vātapittakaphaiśca yaḥ tena rogāsta evoktā yathādoṣavalāśrayāḥ"},{"type":"verse","number":"471","sanskrit":"मोहप्रलापमूर्च्छाः स्युर्मन्यास्तम्भः शिरोग्रहः कासः श्वासो भ्रमस्तन्द्रा संज्ञानाशो हृदि व्यथा खेभ्यो रक्तं विसृजति सरक्तस्तब्धनेत्रता तत्राप्येते विशेषाः स्युर्मृत्युरर्वाक् त्रिवासरात् भिषग्भिः सन्निपातोऽय कथितःपाकलाभिधः","text":"mohapralāpamūrcchāḥ syurmanyāstambhaḥ śirograhaḥ kāsaḥ śvāso bhramastandrā saṃjñānāśo hṛdi vyathā khebhyo raktaṃ visṛjati saraktastabdhanetratā tatrāpyete viśeṣāḥ syurmṛtyurarvāk trivāsarāt bhiṣagbhiḥ sannipāto'ya kathitaḥpākalābhidhaḥ"},{"type":"verse","number":"472","sanskrit":"हीनप्रवृद्धमध्यैस्तु वातपित्तकफैश्च यः तेन रोगास्त एवोक्ता यथादोषबलाश्रयाः","text":"hīnapravṛddhamadhyaistu vātapittakaphaiśca yaḥ tena rogāsta evoktā yathādoṣabalāśrayāḥ"},{"type":"verse","number":"473","sanskrit":"हृदयं दह्यते चास्य यकृत्प्लीहान्त्रफुफ्फुसाः पच्यन्तेऽत्यर्थमूर्द्ध्वाधः पूयशोणितनिर्गमः","text":"hṛdayaṃ dahyate cāsya yakṛtplīhāntraphuphphusāḥ pacyante'tyarthamūrddhvādhaḥ pūyaśoṇitanirgamaḥ"},{"type":"verse","number":"474","sanskrit":"शीर्णदन्तश्च मृत्युश्च तत्राप्येतद्विशेषतः भिषग्भिः सन्निपातोऽय याम्यो नाम्ना प्रकीर्त्तितः","text":"śīrṇadantaśca mṛtyuśca tatrāpyetadviśeṣataḥ bhiṣagbhiḥ sannipāto'ya yāmyo nāmnā prakīrttitaḥ"},{"type":"verse","number":"475","sanskrit":"प्रवृद्धहीनमध्यस्तु वातपित्तकफैश्च यः तेन रोगास्त एवोक्ता यथादोषबलश्रयाः","text":"pravṛddhahīnamadhyastu vātapittakaphaiśca yaḥ tena rogāsta evoktā yathādoṣabalaśrayāḥ"},{"type":"verse","number":"476","sanskrit":"प्रलापायाससम्मोहाः कम्पमूर्च्छाऽरतिभ्रमाः मन्यास्तम्भेन मृत्युःस्यात्तत्राप्येतद्विशेषतः","text":"pralāpāyāsasammohāḥ kampamūrcchā'ratibhramāḥ manyāstambhena mṛtyuḥsyāttatrāpyetadviśeṣataḥ"},{"type":"verse","number":"477","sanskrit":"भिषग्भिः सन्न्पितोऽय क्रकचः सम्प्रकीर्त्तितः","text":"bhiṣagbhiḥ sannpito'ya krakacaḥ samprakīrttitaḥ"},{"type":"verse","number":"478","sanskrit":"मध्यहीनप्रबृद्धैस्तु वातपित्तकफैश्च यः तेन रोगास्त एवोक्ता यथादोषबलाश्रयाः","text":"madhyahīnaprabṛddhaistu vātapittakaphaiśca yaḥ tena rogāsta evoktā yathādoṣabalāśrayāḥ"},{"type":"verse","number":"479","sanskrit":"अन्तर्दाहो विशेषोऽत्र नच वक्तुं स शक्यते रक्तमालक्तकेनेव लक्ष्यते मुखमण्डलम्","text":"antardāho viśeṣo'tra naca vaktuṃ sa śakyate raktamālaktakeneva lakṣyate mukhamaṇḍalam"},{"type":"verse","number":"480","sanskrit":"पित्तेनाकर्षितः श्लेष्मा हृदयान्न प्रसिच्यते इषुणेवाहतं पार्श्वं तुद्यते खन्यते हृदि","text":"pittenākarṣitaḥ śleṣmā hṛdayānna prasicyate iṣuṇevāhataṃ pārśvaṃ tudyate khanyate hṛdi"},{"type":"verse","number":"481","sanskrit":"प्रमीलकश्वासहिक्का वर्द्धन्ते तु दिने दिने जिह्वा दग्धा खरस्पर्शा गलः शूकैरिवावृतः","text":"pramīlakaśvāsahikkā varddhante tu dine dine jihvā dagdhā kharasparśā galaḥ śūkairivāvṛtaḥ"},{"type":"verse","number":"482","sanskrit":"विसर्गं नाभिजानाति कूजेच्चापि कपोतवत् अतीव श्लेष्मणा पूर्णः शुष्कवक्त्रौष्ठतालुकः","text":"visargaṃ nābhijānāti kūjeccāpi kapotavat atīva śleṣmaṇā pūrṇaḥ śuṣkavaktrauṣṭhatālukaḥ"},{"type":"verse","number":"483","sanskrit":"तन्द्रा निद्रा ऽतियोगार्त्तो हतवाङ् निहतद्युतिः न रतिं लभते नित्यं विपरीतानि चेच्छति","text":"tandrā nidrā 'tiyogārtto hatavāṅ nihatadyutiḥ na ratiṃ labhate nityaṃ viparītāni cecchati"},{"type":"verse","number":"484","sanskrit":"आयम्यते च बहुशो रक्तं ष्ठीवति चाल्पशः एष कर्कटको नाम्ना सन्निपातःसुदारुणः","text":"āyamyate ca bahuśo raktaṃ ṣṭhīvati cālpaśaḥ eṣa karkaṭako nāmnā sannipātaḥsudāruṇaḥ"},{"type":"verse","number":"485","sanskrit":"हीनमध्यप्रवृद्धैस्तु वातपित्तकफैश्च यः तेन रोगास्त एवोक्ता यथादोषबलाश्रयाः","text":"hīnamadhyapravṛddhaistu vātapittakaphaiśca yaḥ tena rogāsta evoktā yathādoṣabalāśrayāḥ"},{"type":"verse","number":"486","sanskrit":"अल्पशूलं कटीतोदो मध्ये दाहो रुजा भ्रमः भृशं क्लमः शिरोवस्तिमन्याहृदयवाग्रुजः","text":"alpaśūlaṃ kaṭītodo madhye dāho rujā bhramaḥ bhṛśaṃ klamaḥ śirovastimanyāhṛdayavāgrujaḥ"},{"type":"verse","number":"487","sanskrit":"प्रमीलकः श्वासकासहिक्काजाड्यविसंज्ञताः प्रथमोत्पन्नमेनन्तु साधयन्ति कदाचन","text":"pramīlakaḥ śvāsakāsahikkājāḍyavisaṃjñatāḥ prathamotpannamenantu sādhayanti kadācana"},{"type":"verse","number":"488","sanskrit":"एतस्मिन्सन्निवृत्ते तु कर्णमूले सुदारुणा पिडिका जायते जन्तोर्यया कृच्छ्रेण जीवति","text":"etasminsannivṛtte tu karṇamūle sudāruṇā piḍikā jāyate jantoryayā kṛcchreṇa jīvati"},{"type":"verse","number":"489","sanskrit":"स वैदारिकसंज्ञोऽय सन्निपातःसुदारुणः त्रिरात्रात्परमेतस्य व्यर्थमौषधकल्पनम्","text":"sa vaidārikasaṃjño'ya sannipātaḥsudāruṇaḥ trirātrātparametasya vyarthamauṣadhakalpanam"},{"type":"verse","number":"490","sanskrit":"शीता ङ्गस्त्रिमलोद्भवज्वरगणे तन्द्री प्रलापी ततो रक्तष्ठीवयिता च तत्र गणितः सम्भुग्ननेत्रस्तथा साभिन्यासकजिह्वकश्च कथितः प्राक्सन्धिगोऽथान्तको रुग्दाहः सहचित्तविभ्रम इह द्वौ कर्णकण्ठग्रहौ","text":"śītā ṅgastrimalodbhavajvaragaṇe tandrī pralāpī tato raktaṣṭhīvayitā ca tatra gaṇitaḥ sambhugnanetrastathā sābhinyāsakajihvakaśca kathitaḥ prāksandhigo'thāntako rugdāhaḥ sahacittavibhrama iha dvau karṇakaṇṭhagrahau"},{"type":"verse","number":"491","sanskrit":"हिमशिशिरशरीरः सन्निपातज्वरी यः श्वसनकसनहिक्कामोहकम्पप्रलापः क्लमबहुकफवातादाहवभ्यङ्गपीडास्वरविकृतिभिरार्त्तः शीतगात्रः स उक्तः","text":"himaśiśiraśarīraḥ sannipātajvarī yaḥ śvasanakasanahikkāmohakampapralāpaḥ klamabahukaphavātādāhavabhyaṅgapīḍāsvaravikṛtibhirārttaḥ śītagātraḥ sa uktaḥ"},{"type":"verse","number":"492","sanskrit":"तन्द्रा ऽतीव ततस्तृषाऽतिसरणं श्वासोऽधिकः कासरुक् सन्तप्तार्तितनुर्गले श्वयथुना सार्द्धञ्च कण्डूः कफः सुश्यामा रसना क्लमः श्रवणयोर्मान्द्यञ्च दाहस्तथा यत्र स्यात्स हि तन्द्रि को निगदितो दोषत्रयोत्थो ज्वरः","text":"tandrā 'tīva tatastṛṣā'tisaraṇaṃ śvāso'dhikaḥ kāsaruk santaptārtitanurgale śvayathunā sārddhañca kaṇḍūḥ kaphaḥ suśyāmā rasanā klamaḥ śravaṇayormāndyañca dāhastathā yatra syātsa hi tandri ko nigadito doṣatrayottho jvaraḥ"},{"type":"verse","number":"493","sanskrit":"यत्र ज्वरे निखिलदोषनितान्तरोष जाते प्रलापबहुलाः सहसोत्थिताश्च कम्पव्यथापतनदाहविसंज्ञताः स्युर्नाम्ना प्रलापक इति प्रथितः पृथिव्याम्","text":"yatra jvare nikhiladoṣanitāntaroṣa jāte pralāpabahulāḥ sahasotthitāśca kampavyathāpatanadāhavisaṃjñatāḥ syurnāmnā pralāpaka iti prathitaḥ pṛthivyām"},{"type":"verse","number":"494","sanskrit":"निष्ठीवो रुधिरस्य रक्तसदृशं कृष्णं तनौ मण्डलं लौहित्यं नयने तृषाऽरुचिवमिश्वासातिसारभ्रमाः आध्मानञ्च विसंज्ञता च पतनं हिक्काऽङ्गपीडा भृशं रक्तष्ठीविनि सन्निपातजनिते लिङ्गं ज्वरे जायते","text":"niṣṭhīvo rudhirasya raktasadṛśaṃ kṛṣṇaṃ tanau maṇḍalaṃ lauhityaṃ nayane tṛṣā'rucivamiśvāsātisārabhramāḥ ādhmānañca visaṃjñatā ca patanaṃ hikkā'ṅgapīḍā bhṛśaṃ raktaṣṭhīvini sannipātajanite liṅgaṃ jvare jāyate"},{"type":"verse","number":"495","sanskrit":"भृशं नयनवक्रता श्वसनकासतन्द्रा भृशं प्रलापमदवेपथुश्रवणहानिमोहास्तथा पुरो निखिलदोषजे भवति यत्र लिङ्गं ज्वरे पुरातनचिकित्सकैः स इह भुग्ननेत्रो मतः","text":"bhṛśaṃ nayanavakratā śvasanakāsatandrā bhṛśaṃ pralāpamadavepathuśravaṇahānimohāstathā puro nikhiladoṣaje bhavati yatra liṅgaṃ jvare purātanacikitsakaiḥ sa iha bhugnanetro mataḥ"},{"type":"verse","number":"496","sanskrit":"दोषास्तीव्रतरा भवन्ति बलिनः सर्वेऽपि यत्र ज्वरे मोहोऽतीव विचेष्टता विकलता श्वासो भृशं मूकता दाहश्चिक्कणमाननञ्च दहनो मन्दो बलस्य क्षयः सोऽभिन्यास इति प्रकीर्त्तित इह प्राज्ञैर्भिषग्भिः पुरा","text":"doṣāstīvratarā bhavanti balinaḥ sarve'pi yatra jvare moho'tīva viceṣṭatā vikalatā śvāso bhṛśaṃ mūkatā dāhaścikkaṇamānanañca dahano mando balasya kṣayaḥ so'bhinyāsa iti prakīrttita iha prājñairbhiṣagbhiḥ purā"},{"type":"verse","number":"497","sanskrit":"त्रिदोषजनिते ज्वरे भवति यत्र जिह्वा भृशं वृता कठिनकण्टकैस्तदनु निर्भरंमूकता श्रुतिक्षतिबलक्षति श्वसनकाससन्तप्तताः पुरातनभिषग्वरास्तमिह जिह्वकं चक्षते","text":"tridoṣajanite jvare bhavati yatra jihvā bhṛśaṃ vṛtā kaṭhinakaṇṭakaistadanu nirbharaṃmūkatā śrutikṣatibalakṣati śvasanakāsasantaptatāḥ purātanabhiṣagvarāstamiha jihvakaṃ cakṣate"},{"type":"verse","number":"498","sanskrit":"व्यथाऽतिशयिता भवेच्छ्वयथुसंयुता सन्धिषु प्रभूतकफता मुखे विगतनिद्र ता कासरुक् समस्तमिति कीर्त्तितं भवति लक्ष्म यत्र ज्वरे त्रिदोषजनिते बुधैः स हि निगद्यते सन्धिगः","text":"vyathā'tiśayitā bhavecchvayathusaṃyutā sandhiṣu prabhūtakaphatā mukhe vigatanidra tā kāsaruk samastamiti kīrttitaṃ bhavati lakṣma yatra jvare tridoṣajanite budhaiḥ sa hi nigadyate sandhigaḥ"},{"type":"verse","number":"499","sanskrit":"यस्मिँ ल्लक्षणमेतदस्ति सकलैर्दोषैरुदीते ज्वरे ऽजस्रं मूर्द्धविधूननं सकसनं सर्वाङ्गपीडाऽधिका हिक्काश्वाससदाहमोहसहिता देहेऽतिसन्तप्तता वैकल्यञ्च वृथावचांसि मुनिभिः संकीर्त्तितः सोऽन्तकः","text":"yasmi~ llakṣaṇametadasti sakalairdoṣairudīte jvare 'jasraṃ mūrddhavidhūnanaṃ sakasanaṃ sarvāṅgapīḍā'dhikā hikkāśvāsasadāhamohasahitā dehe'tisantaptatā vaikalyañca vṛthāvacāṃsi munibhiḥ saṃkīrttitaḥ so'ntakaḥ"},{"type":"verse","number":"500","sanskrit":"दाहोऽधिको भवति यत्र तृषा च तीव्रा श्वासप्रलापविरुचिभ्रममोहपीडाः मन्याहनुव्यथनकण्ठरूजः श्रमश्च रूग्दाहसंज्ञ उदितस्त्रिभवो ज्वरोऽयम्","text":"dāho'dhiko bhavati yatra tṛṣā ca tīvrā śvāsapralāpavirucibhramamohapīḍāḥ manyāhanuvyathanakaṇṭharūjaḥ śramaśca rūgdāhasaṃjña uditastribhavo jvaro'yam"},{"type":"verse","number":"501","sanskrit":"गायति नृत्यति हसति प्रलपति विकृतं निरीक्षते मुह्येत् दाहव्यथाभयार्त्तो नरस्तु चित्तभ्रमे ज्वरे भवति","text":"gāyati nṛtyati hasati pralapati vikṛtaṃ nirīkṣate muhyet dāhavyathābhayārtto narastu cittabhrame jvare bhavati"},{"type":"verse","number":"502","sanskrit":"दोषत्रयेण जनितः किल कर्णमूले तीव्रा ज्वरे भवति तु श्वयथुव्यथा च कण्ठग्रहो बधिरता श्वसनं प्रलापः प्रस्वेदमोहदहनानि च कर्णिकाख्ये","text":"doṣatrayeṇa janitaḥ kila karṇamūle tīvrā jvare bhavati tu śvayathuvyathā ca kaṇṭhagraho badhiratā śvasanaṃ pralāpaḥ prasvedamohadahanāni ca karṇikākhye"},{"type":"verse","number":"503","sanskrit":"कण्ठःशूकशतावरुद्धवदतिश्वासः प्रलापोऽरुचि र्दाहोदेहरुजा तृषाऽपि च हनुस्तम्भः शिरोऽतिस्तथा मोहो वेपथुना सहेति सकलं लिङ्गं त्रिदोषज्वरे यत्रस्यात्स हि कण्ठकुब्ज उदितः प्राच्यैश्चिकित्साबुधैः","text":"kaṇṭhaḥśūkaśatāvaruddhavadatiśvāsaḥ pralāpo'ruci rdāhodeharujā tṛṣā'pi ca hanustambhaḥ śiro'tistathā moho vepathunā saheti sakalaṃ liṅgaṃ tridoṣajvare yatrasyātsa hi kaṇṭhakubja uditaḥ prācyaiścikitsābudhaiḥ"},{"type":"verse","number":"504","sanskrit":"सन्धिगस्तेषुसाध्यः स्यात्तन्द्रि कश्चित्तविभ्रमः कर्णिको जिह्वकः कण्ठकुब्जः पञ्चापि कष्टकाः","text":"sandhigasteṣusādhyaḥ syāttandri kaścittavibhramaḥ karṇiko jihvakaḥ kaṇṭhakubjaḥ pañcāpi kaṣṭakāḥ"},{"type":"verse","number":"505","sanskrit":"रुग्दाहस्त्वतिकष्टेन संसाध्यस्तेषु भाषितः रक्तष्ठीवी भुग्ननेत्रः शीतगात्रः प्रलापकः अभिन्यासोऽन्तकश्चैते षडसाध्याः प्रकीर्त्तिताः","text":"rugdāhastvatikaṣṭena saṃsādhyasteṣu bhāṣitaḥ raktaṣṭhīvī bhugnanetraḥ śītagātraḥ pralāpakaḥ abhinyāso'ntakaścaite ṣaḍasādhyāḥ prakīrttitāḥ"},{"type":"verse","number":"506","sanskrit":"कुम्भीपाकः प्रोर्णुनावः प्रलापी ह्यन्तैर्दाहो दण्डपातोऽन्तकश्च एणीदाहश्चाथ हारिद्र संज्ञो भेदा एते सन्निपातज्वरस्य","text":"kumbhīpākaḥ prorṇunāvaḥ pralāpī hyantairdāho daṇḍapāto'ntakaśca eṇīdāhaścātha hāridra saṃjño bhedā ete sannipātajvarasya"},{"type":"verse","number":"507","sanskrit":"अजघोषभूतहासौ यन्त्रापीडश्च संन्यासः संशोषी च विशेषास्तस्यैवोक्तास्त्रयोदशान्यत्र","text":"ajaghoṣabhūtahāsau yantrāpīḍaśca saṃnyāsaḥ saṃśoṣī ca viśeṣāstasyaivoktāstrayodaśānyatra"},{"type":"verse","number":"508","sanskrit":"घोणाविवरझरद्वहु शोणासितलोहितं सान्द्र म् विलुठन्मस्तकमभितः कुम्भीपाकेन पीडितं विद्यात्","text":"ghoṇāvivarajharadvahu śoṇāsitalohitaṃ sāndra m viluṭhanmastakamabhitaḥ kumbhīpākena pīḍitaṃ vidyāt"},{"type":"verse","number":"509","sanskrit":"उत्क्षिप्य यः स्वमङ्गं क्षिपत्यधस्तान्नितान्तमुच्छ्वसिति तं प्रोर्णुनावजुष्टं विचित्रकष्टं विजानीयात्","text":"utkṣipya yaḥ svamaṅgaṃ kṣipatyadhastānnitāntamucchvasiti taṃ prorṇunāvajuṣṭaṃ vicitrakaṣṭaṃ vijānīyāt"},{"type":"verse","number":"510","sanskrit":"स्वेदभ्रमाङ्गभेदाः कम्पोदवथुर्वमिर्व्यथा कण्ठे गात्रश्च गुर्वतीव प्रलापिजुष्टस्य जायते लिङ्गम्","text":"svedabhramāṅgabhedāḥ kampodavathurvamirvyathā kaṇṭhe gātraśca gurvatīva pralāpijuṣṭasya jāyate liṅgam"},{"type":"verse","number":"511","sanskrit":"अन्तर्दाहः शैत्यं बहिः श्वयथुररतिरति तथा श्वासः अङ्गमपि दग्धकल्पं सोऽन्तर्दाहार्दितः कथितः","text":"antardāhaḥ śaityaṃ bahiḥ śvayathuraratirati tathā śvāsaḥ aṅgamapi dagdhakalpaṃ so'ntardāhārditaḥ kathitaḥ"},{"type":"verse","number":"512","sanskrit":"नक्तन्दिवा न निद्रा मुपगृह्णाति मूढधीर्नभसः उत्थाय दण्डपाती भ्रमातुरः सर्वतो भ्रमति","text":"naktandivā na nidrā mupagṛhṇāti mūḍhadhīrnabhasaḥ utthāya daṇḍapātī bhramāturaḥ sarvato bhramati"},{"type":"verse","number":"513","sanskrit":"सम्पूर्यते शरीरं ग्रन्थिभिरभितस्तथोदरं मरुता श्वासातुरस्य सततं विचेतनस्यान्तकार्त्तस्य","text":"sampūryate śarīraṃ granthibhirabhitastathodaraṃ marutā śvāsāturasya satataṃ vicetanasyāntakārttasya"},{"type":"verse","number":"514","sanskrit":"परिधावतीव गात्रे रुक्पात्रे भुजगपतगहरिणगणः वेपथुमतः सदाहस्यैणीदाहज्वरार्त्तस्य","text":"paridhāvatīva gātre rukpātre bhujagapatagahariṇagaṇaḥ vepathumataḥ sadāhasyaiṇīdāhajvarārttasya"},{"type":"verse","number":"515","sanskrit":"यस्यातिपीतमङ्गं नयने सुतरां मलस्ततोऽप्यधिकम् दाहेऽतिशीतता बहिरस्य स हारिद्र को ज्ञेयः","text":"yasyātipītamaṅgaṃ nayane sutarāṃ malastato'pyadhikam dāhe'tiśītatā bahirasya sa hāridra ko jñeyaḥ"},{"type":"verse","number":"516","sanskrit":"छगलकसमानगन्धः स्कन्धरुजावान्निरूद्धगलरन्ध्रः अजघोषसन्निपातादाताम्राक्षः पुमान् भवति","text":"chagalakasamānagandhaḥ skandharujāvānnirūddhagalarandhraḥ ajaghoṣasannipātādātāmrākṣaḥ pumān bhavati"},{"type":"verse","number":"517","sanskrit":"शब्दादीनधिगच्छति न स्वान् विषयान् यदिन्द्रि यग्रामैः हसति प्रलपति परुषं स ज्ञेयो भूतहासार्त्तः","text":"śabdādīnadhigacchati na svān viṣayān yadindri yagrāmaiḥ hasati pralapati paruṣaṃ sa jñeyo bhūtahāsārttaḥ"},{"type":"verse","number":"518","sanskrit":"येन मुहुर्ज्वरवेगाद् यन्त्रेणेवावपीड्यते गात्रम् रक्तं पित्तञ्च वमेद् यन्त्रापीडः स विज्ञेयः","text":"yena muhurjvaravegād yantreṇevāvapīḍyate gātram raktaṃ pittañca vamed yantrāpīḍaḥ sa vijñeyaḥ"},{"type":"verse","number":"519","sanskrit":"अतिसरति वमति कूजति गात्राण्यभितश्चिरं नरः क्षिपति संन्याससन्निपाते प्रलपत्युग्राक्षिमण्डलो भवति","text":"atisarati vamati kūjati gātrāṇyabhitaściraṃ naraḥ kṣipati saṃnyāsasannipāte pralapatyugrākṣimaṇḍalo bhavati"},{"type":"verse","number":"520","sanskrit":"मेचकवपुरतिमेचक लोचनयुगलो मलोत्सर्गात् संशोषिणि सितपिडिका मण्डलयुक्तो ज्वरे नरो भवति","text":"mecakavapuratimecaka locanayugalo malotsargāt saṃśoṣiṇi sitapiḍikā maṇḍalayukto jvare naro bhavati"},{"type":"verse","number":"521","sanskrit":"नारायण एव भिषग् भेषजमेतेषु जाह्नवीनीरम् नैरुज्यहेतुरेको नित्यं मृत्युञ्जयो ध्येयः","text":"nārāyaṇa eva bhiṣag bheṣajameteṣu jāhnavīnīram nairujyahetureko nityaṃ mṛtyuñjayo dhyeyaḥ"},{"type":"verse","number":"522","sanskrit":"सन्निपातज्वरस्यान्ते कर्णमूले सुदारुणः शोथः सञ्जायते तेन कश्चिदेव प्रमुच्यते ६५२४ सन्निपातज्वरान्कष्टानसाध्यानपरे जगुः","text":"sannipātajvarasyānte karṇamūle sudāruṇaḥ śothaḥ sañjāyate tena kaścideva pramucyate 6524 sannipātajvarānkaṣṭānasādhyānapare jaguḥ"},{"type":"verse","number":"523","sanskrit":"दोषे प्रवृद्धे नष्टेऽग्नौ सर्वसम्पूर्णलक्षणः सन्निपातज्वरोऽसाध्यः कष्टसाध्यस्ततोऽन्यथा","text":"doṣe pravṛddhe naṣṭe'gnau sarvasampūrṇalakṣaṇaḥ sannipātajvaro'sādhyaḥ kaṣṭasādhyastato'nyathā"},{"type":"verse","number":"524","sanskrit":"सन्निपातार्णवे मग्नं योऽभ्युद्धरति मानवम् कस्तेन न कृतो धर्मः काञ्च पूजां न सोऽहति","text":"sannipātārṇave magnaṃ yo'bhyuddharati mānavam kastena na kṛto dharmaḥ kāñca pūjāṃ na so'hati"},{"type":"verse","number":"525","sanskrit":"मृत्युना सह योद्धव्यं सन्निपातं चिकित्सता यश्च तत्र भवेज्जेता सजेताऽमयसंकुले","text":"mṛtyunā saha yoddhavyaṃ sannipātaṃ cikitsatā yaśca tatra bhavejjetā sajetā'mayasaṃkule"},{"type":"verse","number":"526","sanskrit":"श्लेष्मनिग्रहमेवादौ कुर्याद्व्याधौ त्रिदोषजे संसर्गे यो गरीयान्स्या दुपक्रम्यस वै भवेत्","text":"śleṣmanigrahamevādau kuryādvyādhau tridoṣaje saṃsarge yo garīyānsyā dupakramyasa vai bhavet"},{"type":"verse","number":"527","sanskrit":"अंशाशं यत्र दोषाणां विवेक्तुं नैव शक्नुयात् क्रियां साधारणीं तत्र विदधीत चिकित्सकः","text":"aṃśāśaṃ yatra doṣāṇāṃ vivektuṃ naiva śaknuyāt kriyāṃ sādhāraṇīṃ tatra vidadhīta cikitsakaḥ"},{"type":"verse","number":"528","sanskrit":"लङ्घनं बालुकास्वेदो नस्यं निष्ठीवनं तथा अवलेहोऽञ्जनं चैव प्राक्प्रयोज्यं त्रिदोषजे","text":"laṅghanaṃ bālukāsvedo nasyaṃ niṣṭhīvanaṃ tathā avaleho'ñjanaṃ caiva prākprayojyaṃ tridoṣaje"},{"type":"verse","number":"529","sanskrit":"क्रियाभिस्तुल्यरूपाभिः क्रियासांकर्यमिष्यते भिन्नरूपतया तास्तु न हि कुर्वन्ति दूषणम्","text":"kriyābhistulyarūpābhiḥ kriyāsāṃkaryamiṣyate bhinnarūpatayā tāstu na hi kurvanti dūṣaṇam"},{"type":"verse","number":"530","sanskrit":"त्रिरात्रं पञ्चरात्रं वा दशरात्रमथापि वा लङ्घनं सन्निपातेषु कुर्यादारोग्यदर्शनात्","text":"trirātraṃ pañcarātraṃ vā daśarātramathāpi vā laṅghanaṃ sannipāteṣu kuryādārogyadarśanāt"},{"type":"verse","number":"531","sanskrit":"सप्तमे दिवसे प्राप्ते दशमे द्वादशेऽपि वा पुनर्घोरतरो भूत्वा प्रशमं याति हन्ति वा","text":"saptame divase prāpte daśame dvādaśe'pi vā punarghorataro bhūtvā praśamaṃ yāti hanti vā"},{"type":"verse","number":"532","sanskrit":"पित्तकफानिलवृद्ध्या दशदिवसद्वादशाहसप्ताहात् हन्ति विमुञ्चत्यथ वा त्रिदोषजो धातुमलपाकात्","text":"pittakaphānilavṛddhyā daśadivasadvādaśāhasaptāhāt hanti vimuñcatyatha vā tridoṣajo dhātumalapākāt"},{"type":"verse","number":"533","sanskrit":"निद्रा नाशो हृदिस्तम्भो विष्टम्भो गौरवारुची अरतिर्बलहानिश्च धातूनां पाकलक्षणम्","text":"nidrā nāśo hṛdistambho viṣṭambho gauravārucī aratirbalahāniśca dhātūnāṃ pākalakṣaṇam"},{"type":"verse","number":"534","sanskrit":"सम्बाध्यमानोहृदि नाभिदेशे गात्रेषु वा पाकरुजाऽन्वितेषु पीडां ज्वरार्त्तोऽङगुलिभिश्च गच्छेत् स धातुपाकी कथितो भिषग्भिः","text":"sambādhyamānohṛdi nābhideśe gātreṣu vā pākarujā'nviteṣu pīḍāṃ jvarārtto'ṅagulibhiśca gacchet sa dhātupākī kathito bhiṣagbhiḥ"},{"type":"verse","number":"535","sanskrit":"नाभेरूर्ध्वं हृदोऽधस्तात् पीडिते चेद्ब्यथा भवेत् धातोः पाकंविजानीयादन्यथा तु मलस्य च","text":"nābherūrdhvaṃ hṛdo'dhastāt pīḍite cedbyathā bhavet dhātoḥ pākaṃvijānīyādanyathā tu malasya ca"},{"type":"verse","number":"536","sanskrit":"दोषप्रकृतिवैकृत्यं लघुताज्वरदेहयोः इन्द्रि याणाञ्च वैमल्यं मलानां पाकलक्षणम्","text":"doṣaprakṛtivaikṛtyaṃ laghutājvaradehayoḥ indri yāṇāñca vaimalyaṃ malānāṃ pākalakṣaṇam"},{"type":"verse","number":"537","sanskrit":"शश्वत्त्विन्द्रि यपञ्चकस्य पटुता वह्नेश्च यत्र क्रमा त्तृष्णाऽदिप्रशमो ज्वरस्य मृदुता तं दोषपाकं वदेत् हृन्नाभ्योरतिवेदनाऽतिसरणं तीव्रो ज्वरस्तृण्मदः श्वासाधिक्यमरोचकोऽरतिरिति स्याद्धातुपाकाकृतिः","text":"śaśvattvindri yapañcakasya paṭutā vahneśca yatra kramā ttṛṣṇā'dipraśamo jvarasya mṛdutā taṃ doṣapākaṃ vadet hṛnnābhyorativedanā'tisaraṇaṃ tīvro jvarastṛṇmadaḥ śvāsādhikyamarocako'ratiriti syāddhātupākākṛtiḥ"},{"type":"verse","number":"538","sanskrit":"सप्तमी द्विगुणा यावन्नवम्येकादशी तथा एषा त्रिदोषमर्यादा मोक्षाय च वधाय च","text":"saptamī dviguṇā yāvannavamyekādaśī tathā eṣā tridoṣamaryādā mokṣāya ca vadhāya ca"},{"type":"verse","number":"539","sanskrit":"सन्निपातज्वरी पूर्वं सम्यग् लङ्घनमाचरेत् शृतं शीतं पिबेदम्भः समये भेषजं भजेत्","text":"sannipātajvarī pūrvaṃ samyag laṅghanamācaret śṛtaṃ śītaṃ pibedambhaḥ samaye bheṣajaṃ bhajet"},{"type":"verse","number":"540","sanskrit":"सन्निपातेन तृष्यन्तं पार्श्वरुक्तालुशोषिणम् यःपाययेज्जलं शीतं स मृत्युर्नरविग्रहः","text":"sannipātena tṛṣyantaṃ pārśvaruktāluśoṣiṇam yaḥpāyayejjalaṃ śītaṃ sa mṛtyurnaravigrahaḥ"},{"type":"verse","number":"541","sanskrit":"वातश्लेष्मकृते स्वेदान्कारयेद्रू क्षनिर्मितान् स्निग्धः स्वेदो निषिद्धोऽत्र विना केवलवातजात्","text":"vātaśleṣmakṛte svedānkārayedrū kṣanirmitān snigdhaḥ svedo niṣiddho'tra vinā kevalavātajāt"},{"type":"verse","number":"542","sanskrit":"खर्परभृष्टपटस्थितकाञ्जिकसंसिक्तवालुकास्वेदः शमयति वातकफामयमस्तकशूलाङ्गभङ्गादीन्","text":"kharparabhṛṣṭapaṭasthitakāñjikasaṃsiktavālukāsvedaḥ śamayati vātakaphāmayamastakaśūlāṅgabhaṅgādīn"},{"type":"verse","number":"543","sanskrit":"स्रोतसां मार्दवं कृत्वा नीत्वा पावकमाशयम् हृत्वावातकफस्तम्भं स्वेदो ज्वरमपोहति","text":"srotasāṃ mārdavaṃ kṛtvā nītvā pāvakamāśayam hṛtvāvātakaphastambhaṃ svedo jvaramapohati"},{"type":"verse","number":"544","sanskrit":"सैन्धवं श्वेतमरिचं सर्षपाः कुष्ठमेव च बस्तमूत्रेण सम्पिष्टं नस्यं तन्द्रा निवारणम्","text":"saindhavaṃ śvetamaricaṃ sarṣapāḥ kuṣṭhameva ca bastamūtreṇa sampiṣṭaṃ nasyaṃ tandrā nivāraṇam"},{"type":"verse","number":"545","sanskrit":"मधूकसारसिन्धूत्थवचोषणकणाः समाः श्लक्ष्णं पिष्ट्वाऽम्भसा नस्यं दद्यात्संज्ञाप्रबोधनम्","text":"madhūkasārasindhūtthavacoṣaṇakaṇāḥ samāḥ ślakṣṇaṃ piṣṭvā'mbhasā nasyaṃ dadyātsaṃjñāprabodhanam"},{"type":"verse","number":"546","sanskrit":"मातुलुङ्गार्द्र्रकरसं कोष्णं त्रिलवणान्वितम् अन्यद्वा सिद्धिविहितं नस्यं तीक्ष्णं प्रयोजयेत्","text":"mātuluṅgārdrrakarasaṃ koṣṇaṃ trilavaṇānvitam anyadvā siddhivihitaṃ nasyaṃ tīkṣṇaṃ prayojayet"},{"type":"verse","number":"547","sanskrit":"तेन प्रभिद्यते श्लेष्मा प्रभिन्नश्च प्रसिच्यते शिरोहृदयकण्ठास्यपार्श्वरुक् चोपशाम्यति","text":"tena prabhidyate śleṣmā prabhinnaśca prasicyate śirohṛdayakaṇṭhāsyapārśvaruk copaśāmyati"},{"type":"verse","number":"548","sanskrit":"मोहामयेन मुग्धं बोधयितुं यादृशः शक्तः कल्पतरुनामधेयो रसो न तादृक् परं किञ्चित्","text":"mohāmayena mugdhaṃ bodhayituṃ yādṛśaḥ śaktaḥ kalpatarunāmadheyo raso na tādṛk paraṃ kiñcit"},{"type":"verse","number":"549","sanskrit":"जिह्वातालुगलक्लोम मरुत्पित्तेन दूषितम् तदा सञ्चारयेच्छोषं जिह्वाविरसतां तथा","text":"jihvātālugalakloma marutpittena dūṣitam tadā sañcārayecchoṣaṃ jihvāvirasatāṃ tathā"},{"type":"verse","number":"550","sanskrit":"स्फुटनञ्च तदा जिह्वां लेपयेन्मधुपिष्टया द्रा क्षया साज्यया तेन जिह्वा स्यात्सरसा मृदुः","text":"sphuṭanañca tadā jihvāṃ lepayenmadhupiṣṭayā drā kṣayā sājyayā tena jihvā syātsarasā mṛduḥ"},{"type":"verse","number":"551","sanskrit":"आर्द्र्रकस्वरसोपेतं सैन्धवं कटुकत्रयम् आकण्ठाद्धारयेदास्ये निष्ठीवेच्च पुनः पुनः","text":"ārdrrakasvarasopetaṃ saindhavaṃ kaṭukatrayam ākaṇṭhāddhārayedāsye niṣṭhīvecca punaḥ punaḥ"},{"type":"verse","number":"552","sanskrit":"तेनास्यतालुकोष्ठांसमन्यापार्श्वशिरोगलात् लीनोऽप्याकृष्यते श्लेष्मा लाघवं चास्य जायते","text":"tenāsyatālukoṣṭhāṃsamanyāpārśvaśirogalāt līno'pyākṛṣyate śleṣmā lāghavaṃ cāsya jāyate"},{"type":"verse","number":"553","sanskrit":"पर्वभेदो ज्वरो मूर्च्छानिद्रा श्वासगलामयाः मुखाक्षिगौरवं जाड्यमुत्क्लेशश्चोपशाम्यति","text":"parvabhedo jvaro mūrcchānidrā śvāsagalāmayāḥ mukhākṣigauravaṃ jāḍyamutkleśaścopaśāmyati"},{"type":"verse","number":"554","sanskrit":"सकृद्द्विस्त्रिश्चतुष्कुर्याद् दृष्ट्वा दोषबलाबलम् एतद्धि परमं प्राहुर्भेषजं सन्निपातिनाम्","text":"sakṛddvistriścatuṣkuryād dṛṣṭvā doṣabalābalam etaddhi paramaṃ prāhurbheṣajaṃ sannipātinām"},{"type":"verse","number":"555","sanskrit":"इति कवल ग्रहः कट्फलं पौष्करं शृङ्गी व्योषं यासश्च कारवी श्लक्ष्णं चूर्णीकृतं चैतन्मधुना सह लेहयेत्","text":"iti kavala grahaḥ kaṭphalaṃ pauṣkaraṃ śṛṅgī vyoṣaṃ yāsaśca kāravī ślakṣṇaṃ cūrṇīkṛtaṃ caitanmadhunā saha lehayet"},{"type":"verse","number":"556","sanskrit":"एषाऽवलेहिका हन्ति सन्निपातं सुदारूणम् हिक्कां श्वासं च कासञ्च कण्ठरोगञ्च नाशयेत् एतद्योज्यं कफोद्रे के चूर्णमार्द्र कजै रसैः","text":"eṣā'valehikā hanti sannipātaṃ sudārūṇam hikkāṃ śvāsaṃ ca kāsañca kaṇṭharogañca nāśayet etadyojyaṃ kaphodre ke cūrṇamārdra kajai rasaiḥ"},{"type":"verse","number":"557","sanskrit":"अष्टाङ्गं मधुना लिह्यादार्द्र कस्य रसेन वा सम्मोहं दारुणं हन्यात्तन्द्रा काससमन्वितम्","text":"aṣṭāṅgaṃ madhunā lihyādārdra kasya rasena vā sammohaṃ dāruṇaṃ hanyāttandrā kāsasamanvitam"},{"type":"verse","number":"558","sanskrit":"सर्वेषु सन्निपातेषु न क्षौद्र्रमवचारयेत् शीतोपचारि क्षौद्रं स्याच्छीतं चात्र विरुद्ध्य्ते","text":"sarveṣu sannipāteṣu na kṣaudrramavacārayet śītopacāri kṣaudraṃ syācchītaṃ cātra viruddhyte"},{"type":"verse","number":"559","sanskrit":"स्विन्नमामलकं पिष्ट्वा द्रा क्षया सह मेलयेत् विश्वभेषजसुंयुक्तं मधुना सह लेहयेत् तेनास्य शाम्यति श्वासः कासो मूर्च्छाऽरुचिस्तथा","text":"svinnamāmalakaṃ piṣṭvā drā kṣayā saha melayet viśvabheṣajasuṃyuktaṃ madhunā saha lehayet tenāsya śāmyati śvāsaḥ kāso mūrcchā'rucistathā"},{"type":"verse","number":"560","sanskrit":"शिरीषबीजं गोम्रूत्रकृष्णामरिचसैन्धवैः अञ्जनं स्यात्प्रबोधायसरसोनशिलावचैः","text":"śirīṣabījaṃ gomrūtrakṛṣṇāmaricasaindhavaiḥ añjanaṃ syātprabodhāyasarasonaśilāvacaiḥ"},{"type":"verse","number":"561","sanskrit":"अयोरजः श्वेतलोध्रं मरिचं चाञ्जनं तथा गोमूत्रेण समायुक्तं तन्द्रा नाशनमुत्तमम्","text":"ayorajaḥ śvetalodhraṃ maricaṃ cāñjanaṃ tathā gomūtreṇa samāyuktaṃ tandrā nāśanamuttamam"},{"type":"verse","number":"562","sanskrit":"अञ्जनं सम्यगारब्धं मधुसिन्धुशिलोषणैः प्रमोहद्र्रोहि भवति भाषितं दण्डपाणिना","text":"añjanaṃ samyagārabdhaṃ madhusindhuśiloṣaṇaiḥ pramohadrrohi bhavati bhāṣitaṃ daṇḍapāṇinā"},{"type":"verse","number":"563","sanskrit":"इत्यञ्जनम् सूतं विषञ्च मरिचंतुत्थकं नवसादरम् चूर्णितं स्वरसैर्मर्द्यं धूर्त्तपत्ररसोनयोः","text":"ityañjanam sūtaṃ viṣañca maricaṃtutthakaṃ navasādaram cūrṇitaṃ svarasairmardyaṃ dhūrttapatrarasonayoḥ"},{"type":"verse","number":"564","sanskrit":"सन्निपातकृते मोहे मूर्ध्नि लिम्पेत्पदोपरि अस्थिव्यथास्वनेनैव लेपं कुर्यात्पदोपरि","text":"sannipātakṛte mohe mūrdhni limpetpadopari asthivyathāsvanenaiva lepaṃ kuryātpadopari"},{"type":"verse","number":"565","sanskrit":"बिल्वः श्योनाकगाम्भारीपाटलागणिकारिकाः पित्तघ्नंवातकफहृत्पञ्चमूलमिदं महत्","text":"bilvaḥ śyonākagāmbhārīpāṭalāgaṇikārikāḥ pittaghnaṃvātakaphahṛtpañcamūlamidaṃ mahat"},{"type":"verse","number":"566","sanskrit":"शालिपर्णी पृश्निपर्णी बृहती कण्टकारिका गोक्षुरुर्वातपित्तघ्नं कनीयः पञ्चमूलकम्","text":"śāliparṇī pṛśniparṇī bṛhatī kaṇṭakārikā gokṣururvātapittaghnaṃ kanīyaḥ pañcamūlakam"},{"type":"verse","number":"567","sanskrit":"उभयं दशमूलं तत्पिप्पलीचूर्णसंयुतम् सन्निपातज्वरं हन्ति हृत्कण्ठग्रहनाशनम्","text":"ubhayaṃ daśamūlaṃ tatpippalīcūrṇasaṃyutam sannipātajvaraṃ hanti hṛtkaṇṭhagrahanāśanam"},{"type":"verse","number":"568","sanskrit":"तन्द्रा वातकफातङ्कश्वासपार्श्वार्त्तिकासनुत्","text":"tandrā vātakaphātaṅkaśvāsapārśvārttikāsanut"},{"type":"verse","number":"569","sanskrit":"महान्ति यानि मूलानि काष्ठगर्भाणि यानि च तेषान्तु वल्कलं ग्राह्यं ह्रस्वमूलानि कृत्स्नशः","text":"mahānti yāni mūlāni kāṣṭhagarbhāṇi yāni ca teṣāntu valkalaṃ grāhyaṃ hrasvamūlāni kṛtsnaśaḥ"},{"type":"verse","number":"570","sanskrit":"दशमूलीकषायस्तु पिप्पलीपौष्करान्वितः सन्निपातज्वरे देयः श्वासकाससमन्विते","text":"daśamūlīkaṣāyastu pippalīpauṣkarānvitaḥ sannipātajvare deyaḥ śvāsakāsasamanvite"},{"type":"verse","number":"571","sanskrit":"चिरज्वरे वातकफोल्वणे वा त्रिदोषजे वा दशमूलमिश्रः किराततिक्तादिगणः प्रयोज्यः शुद्ध्य्र्थिने वा त्रिवृताविमिश्रः","text":"cirajvare vātakapholvaṇe vā tridoṣaje vā daśamūlamiśraḥ kirātatiktādigaṇaḥ prayojyaḥ śuddhyrthine vā trivṛtāvimiśraḥ"},{"type":"verse","number":"572","sanskrit":"किराततिक्तको मुस्तं गुडूची विश्वभेषजम् किरातादिर्गणो ह्येष चातुर्भद्र कमित्यपि","text":"kirātatiktako mustaṃ guḍūcī viśvabheṣajam kirātādirgaṇo hyeṣa cāturbhadra kamityapi"},{"type":"verse","number":"573","sanskrit":"दशमूली शटी शृङ्गी पौष्करं सदुरालभम् भार्गी कुटजबीजञ्च पटोलं कटुरोहिणी","text":"daśamūlī śaṭī śṛṅgī pauṣkaraṃ sadurālabham bhārgī kuṭajabījañca paṭolaṃ kaṭurohiṇī"},{"type":"verse","number":"574","sanskrit":"अष्टादशाङ्ग इत्येष सन्निपातज्वरापहः कासहृद्ग्रहपार्श्वार्त्तिश्वासहिक्कावमीहरः","text":"aṣṭādaśāṅga ityeṣa sannipātajvarāpahaḥ kāsahṛdgrahapārśvārttiśvāsahikkāvamīharaḥ"},{"type":"verse","number":"575","sanskrit":"भूनिम्बदारुदशमूलमहौषधाब्द तिक्तेन्द्र्रबीजधनिकेभकणाकषायः तन्द्रा प्रलापकसनारुचिदाहमोह श्वासत्रिदोषजनितज्वरनाशनः स्यात्","text":"bhūnimbadārudaśamūlamahauṣadhābda tiktendrrabījadhanikebhakaṇākaṣāyaḥ tandrā pralāpakasanārucidāhamoha śvāsatridoṣajanitajvaranāśanaḥ syāt"},{"type":"verse","number":"576","sanskrit":"सन्निपातज्वरे रसप्रदीपे विषं त्रिकटुकं गन्धं टङ्कणं मृतशुल्वकम् धत्तूरस्य च बीजानि हिङ्गुलं नवमं स्मृतम्","text":"sannipātajvare rasapradīpe viṣaṃ trikaṭukaṃ gandhaṃ ṭaṅkaṇaṃ mṛtaśulvakam dhattūrasya ca bījāni hiṅgulaṃ navamaṃ smṛtam"},{"type":"verse","number":"577","sanskrit":"एतानि समभागानि दिनैकं विजयाद्र वैः मर्दयेच्चणकाकारा कर्त्तव्या वटिकाऽथ सा","text":"etāni samabhāgāni dinaikaṃ vijayādra vaiḥ mardayeccaṇakākārā karttavyā vaṭikā'tha sā"},{"type":"verse","number":"578","sanskrit":"भक्षणीयोऽनुपातव्यो रविमूलकषायकः मृतसञ्जीवनी नाम्नासन्निपातज्वरान्तकृत्","text":"bhakṣaṇīyo'nupātavyo ravimūlakaṣāyakaḥ mṛtasañjīvanī nāmnāsannipātajvarāntakṛt"},{"type":"verse","number":"579","sanskrit":"शुद्धसूतं समं गन्धं सूतांशं मृतताम्रकम् त्रिभिस्तुल्यैर्गवां क्षीरैर्मर्दयेदातपे खरे","text":"śuddhasūtaṃ samaṃ gandhaṃ sūtāṃśaṃ mṛtatāmrakam tribhistulyairgavāṃ kṣīrairmardayedātape khare"},{"type":"verse","number":"580","sanskrit":"मर्दयेद्दिनमेकन्तु निर्गुण्डीशिग्रुजद्र वैः विधाय गोलं तं गोलमन्धमूषागतं पचेत्","text":"mardayeddinamekantu nirguṇḍīśigrujadra vaiḥ vidhāya golaṃ taṃ golamandhamūṣāgataṃ pacet"},{"type":"verse","number":"581","sanskrit":"त्रियामं बालुकायन्त्रे ततः खल्वे विचूर्णयेत् अष्टमांशं विषं तत्र क्षिपेत्तेनापि मर्दयेत्","text":"triyāmaṃ bālukāyantre tataḥ khalve vicūrṇayet aṣṭamāṃśaṃ viṣaṃ tatra kṣipettenāpi mardayet"},{"type":"verse","number":"582","sanskrit":"त्रिनेत्राख्यो रसो ह्येष देयो गुञ्जाद्वयोन्मितः पञ्चकोलकषायेण छागीदुग्धेन वा सह","text":"trinetrākhyo raso hyeṣa deyo guñjādvayonmitaḥ pañcakolakaṣāyeṇa chāgīdugdhena vā saha"},{"type":"verse","number":"583","sanskrit":"रसेनानेनभुक्तेन सन्निपातज्वरो महान् संक्षयं व्रजति क्षिप्रं कर्त्तव्यो नात्र संशयः","text":"rasenānenabhuktena sannipātajvaro mahān saṃkṣayaṃ vrajati kṣipraṃ karttavyo nātra saṃśayaḥ"},{"type":"verse","number":"584","sanskrit":"भस्म षोडशनिष्कं स्यादरण्योपलसम्भवम् मरिचं निष्कमात्रञ्च विषं निष्कं विचूर्णयेत्","text":"bhasma ṣoḍaśaniṣkaṃ syādaraṇyopalasambhavam maricaṃ niṣkamātrañca viṣaṃ niṣkaṃ vicūrṇayet"},{"type":"verse","number":"585","sanskrit":"रसो भस्मेश्वरो नाम सन्निपातज्वरान्तकृत् एकगुञ्जामितो भक्ष्य आर्द्र कस्य द्र्रवेण हि","text":"raso bhasmeśvaro nāma sannipātajvarāntakṛt ekaguñjāmito bhakṣya ārdra kasya drraveṇa hi"},{"type":"verse","number":"586","sanskrit":"द्वौ कर्षौ सूतकाद् ग्राह्यौ गन्धकाद् द्वौ तथैव च यत्नतस्तूभयं मर्द्यं दिनं हंसपदीद्र्रवैः","text":"dvau karṣau sūtakād grāhyau gandhakād dvau tathaiva ca yatnatastūbhayaṃ mardyaṃ dinaṃ haṃsapadīdrravaiḥ"},{"type":"verse","number":"587","sanskrit":"कल्कस्य वटिकां कृत्वा निक्षिपेत्काचभाजने कर्षैकममृतं तत्र क्षिप्त्वा वक्त्रं निरोधयेत्","text":"kalkasya vaṭikāṃ kṛtvā nikṣipetkācabhājane karṣaikamamṛtaṃ tatra kṣiptvā vaktraṃ nirodhayet"},{"type":"verse","number":"588","sanskrit":"कूपिकायाः परौ भागौ बालुकाभिश्च पूरयेत् सार्द्धं यावदहोरात्रं तावत्तत्र पचेद्र सम्","text":"kūpikāyāḥ parau bhāgau bālukābhiśca pūrayet sārddhaṃ yāvadahorātraṃ tāvattatra pacedra sam"},{"type":"verse","number":"589","sanskrit":"याममात्रोऽनलो देयः स्वाङ्गशीतं समुद्धरेत् तोलार्द्धममृतं तत्र क्षिपेत्तावत्तथोषणम्","text":"yāmamātro'nalo deyaḥ svāṅgaśītaṃ samuddharet tolārddhamamṛtaṃ tatra kṣipettāvattathoṣaṇam"},{"type":"verse","number":"590","sanskrit":"भक्षितो रक्तिकामात्रो रसस्त्वग्निकुमारकः सन्निपातज्वरं हन्याद्वातं मन्दाग्नितामपि","text":"bhakṣito raktikāmātro rasastvagnikumārakaḥ sannipātajvaraṃ hanyādvātaṃ mandāgnitāmapi"},{"type":"verse","number":"591","sanskrit":"शूलञ्च ग्रहणीं गुल्मं क्षयं जत्रुगदं तथा श्वासकासादिकान्सर्वान् गदानेष विनाशयेत्","text":"śūlañca grahaṇīṃ gulmaṃ kṣayaṃ jatrugadaṃ tathā śvāsakāsādikānsarvān gadāneṣa vināśayet"},{"type":"verse","number":"592","sanskrit":"गन्धेशटङ्कमरिचं विषं धत्तूरजैर्द्र वैः दिनं सम्मर्दितं शुष्कं पञ्चवक्त्रो रसो भवेत्","text":"gandheśaṭaṅkamaricaṃ viṣaṃ dhattūrajairdra vaiḥ dinaṃ sammarditaṃ śuṣkaṃ pañcavaktro raso bhavet"},{"type":"verse","number":"593","sanskrit":"आर्द्र्रकस्य द्र्रवेणैष दातव्यो रक्तिकामितः सन्निपातज्वरे देयो घोरे तद्दोषनाशनः","text":"ārdrrakasya drraveṇaiṣa dātavyo raktikāmitaḥ sannipātajvare deyo ghore taddoṣanāśanaḥ"},{"type":"verse","number":"594","sanskrit":"अमृतवराटकमरिचै र्द्विपञ्चनवभागयोजितै रचिता वटिका मुद्गसमाना कफत्रिदोषाग्निमान्द्यहरी","text":"amṛtavarāṭakamaricai rdvipañcanavabhāgayojitai racitā vaṭikā mudgasamānā kaphatridoṣāgnimāndyaharī"},{"type":"verse","number":"595","sanskrit":"सूतकं गन्धकञ्चैव हरितालं मनःशिला एकनिष्कं द्विनिष्कञ्च चतुर्निष्कं तथैव च","text":"sūtakaṃ gandhakañcaiva haritālaṃ manaḥśilā ekaniṣkaṃ dviniṣkañca caturniṣkaṃ tathaiva ca"},{"type":"verse","number":"596","sanskrit":"पञ्चनिष्कं रसैः कारवेल्ल्याः सम्यक्प्रकल्पयेत् ताम्रपत्राणि तुल्यानि तेन कल्केन लेपयेत्","text":"pañcaniṣkaṃ rasaiḥ kāravellyāḥ samyakprakalpayet tāmrapatrāṇi tulyāni tena kalkena lepayet"},{"type":"verse","number":"597","sanskrit":"शरावसम्पुटे तानि कृत्वा तेषामुपर्यपि दद्यात्तां पिष्टिकां पश्चात्पुटपाकेन पाचयेत्","text":"śarāvasampuṭe tāni kṛtvā teṣāmuparyapi dadyāttāṃ piṣṭikāṃ paścātpuṭapākena pācayet"},{"type":"verse","number":"598","sanskrit":"ततः सञ्चूर्णयेदेवं रसः क्षौद्रे ण भक्षितः यवैकमात्रया हन्ति घोरं शीतज्वरं ध्रुवम्","text":"tataḥ sañcūrṇayedevaṃ rasaḥ kṣaudre ṇa bhakṣitaḥ yavaikamātrayā hanti ghoraṃ śītajvaraṃ dhruvam"},{"type":"verse","number":"599","sanskrit":"पारदं गन्धकञ्चैव तुत्थञ्च दरदं विषम् विषादष्टगुणं योज्यं मरिचं विश्वभेषजम्","text":"pāradaṃ gandhakañcaiva tutthañca daradaṃ viṣam viṣādaṣṭaguṇaṃ yojyaṃ maricaṃ viśvabheṣajam"},{"type":"verse","number":"600","sanskrit":"अश्वगन्धाऽथ विजया कासमर्दः कठिल्लकः चतुर्णाञ्च रसैरेतैश्चूणान्येतानि मर्दयेत्","text":"aśvagandhā'tha vijayā kāsamardaḥ kaṭhillakaḥ caturṇāñca rasairetaiścūṇānyetāni mardayet"},{"type":"verse","number":"601","sanskrit":"तुलस्यास्तु दलैः सार्द्धं भक्षितो रक्तिकामितः हन्ति शीतज्वरं घोरं नाम्नाऽय शीतकेसरी","text":"tulasyāstu dalaiḥ sārddhaṃ bhakṣito raktikāmitaḥ hanti śītajvaraṃ ghoraṃ nāmnā'ya śītakesarī"},{"type":"verse","number":"602","sanskrit":"तालकं शुक्तिकाचूर्णं तुल्यं तत्रोभयोरपि नवमांशञ्च तुल्यं स्यान्मर्दयेत्कन्यकाद्र वैः","text":"tālakaṃ śuktikācūrṇaṃ tulyaṃ tatrobhayorapi navamāṃśañca tulyaṃ syānmardayetkanyakādra vaiḥ"},{"type":"verse","number":"603","sanskrit":"तत्तु संशुष्कमुपलैर्वन्यैर्गजपुटे पचेत् शीतं तच्चूर्णयेदर्द्धगुञ्जामात्रं सितायुतम्","text":"tattu saṃśuṣkamupalairvanyairgajapuṭe pacet śītaṃ taccūrṇayedarddhaguñjāmātraṃ sitāyutam"},{"type":"verse","number":"604","sanskrit":"प्रभाते भक्षयेत्तेन याति शीतज्वरःक्षयम् वान्तिर्भवति कस्यापि कस्यचिन्न भवत्यपि","text":"prabhāte bhakṣayettena yāti śītajvaraḥkṣayam vāntirbhavati kasyāpi kasyacinna bhavatyapi"},{"type":"verse","number":"605","sanskrit":"तालकं तुत्थकं ताम्रंसूतगन्धकटङ्कणम् सर्वमेतत्समं चूर्णं कारवेल्लीरसद्र वैः","text":"tālakaṃ tutthakaṃ tāmraṃsūtagandhakaṭaṅkaṇam sarvametatsamaṃ cūrṇaṃ kāravellīrasadra vaiḥ"},{"type":"verse","number":"606","sanskrit":"दिनैकं मर्दयेत्तेन रसकर्दमकेन तु ताम्रस्यभाजनस्यान्तर्लिम्पेदर्द्धाङ्गुलोन्मितम्","text":"dinaikaṃ mardayettena rasakardamakena tu tāmrasyabhājanasyāntarlimpedarddhāṅgulonmitam"},{"type":"verse","number":"607","sanskrit":"तत्पचेद्वालुकायन्त्रे यवा यावत्स्फुटन्तिहि शीतलं तद्धि गृह्णीयात्ताम्रपात्रोदराद्भिषक्","text":"tatpacedvālukāyantre yavā yāvatsphuṭantihi śītalaṃ taddhi gṛhṇīyāttāmrapātrodarādbhiṣak"},{"type":"verse","number":"608","sanskrit":"शीतभञ्जी रसो माषमात्रो मरिचसंयुतः भक्षितःपर्णखण्डेन नाशयेद्विषमज्वरान्","text":"śītabhañjī raso māṣamātro maricasaṃyutaḥ bhakṣitaḥparṇakhaṇḍena nāśayedviṣamajvarān"},{"type":"verse","number":"609","sanskrit":"तालको दरदोद्भूतः पारदो गन्धकःशिला क्रमाद्भागार्द्धरहितं कारवेल्ल्यम्बुमर्दितम्","text":"tālako daradodbhūtaḥ pārado gandhakaḥśilā kramādbhāgārddharahitaṃ kāravellyambumarditam"},{"type":"verse","number":"610","sanskrit":"अनेनास्यप्रमाणेन ताम्रपात्रं प्रलेपयेत् अधोमुखं दृढे भाण्डे तन्निरुध्याथ पूरयेत्","text":"anenāsyapramāṇena tāmrapātraṃ pralepayet adhomukhaṃ dṛḍhe bhāṇḍe tannirudhyātha pūrayet"},{"type":"verse","number":"611","sanskrit":"चुल्ल्यां बालुकया घस्रमग्निं प्रज्वालयेदधः शीतं सञ्चूर्ण्य माषोऽस्य नागवल्लीदले स्थितः","text":"cullyāṃ bālukayā ghasramagniṃ prajvālayedadhaḥ śītaṃ sañcūrṇya māṣo'sya nāgavallīdale sthitaḥ"},{"type":"verse","number":"612","sanskrit":"भक्षितो मरिचैः सार्द्धं समस्तविषमज्वरान् शीतदाहादिकान्हन्ति पथ्यं शाल्योदनं पयः","text":"bhakṣito maricaiḥ sārddhaṃ samastaviṣamajvarān śītadāhādikānhanti pathyaṃ śālyodanaṃ payaḥ"},{"type":"verse","number":"613","sanskrit":"कट्फलं त्रिफला दारु चन्दनं सपरूषकम् कटुका पद्मकोशीरं विपचेत्कर्षकं जले","text":"kaṭphalaṃ triphalā dāru candanaṃ saparūṣakam kaṭukā padmakośīraṃ vipacetkarṣakaṃ jale"},{"type":"verse","number":"614","sanskrit":"त्रिदोषदाहतृष्णाघ्नं पानमात्रे प्रपूजितम् दीर्घकालज्वरार्त्तानामेतत्स्यादमृतोपमम्","text":"tridoṣadāhatṛṣṇāghnaṃ pānamātre prapūjitam dīrghakālajvarārttānāmetatsyādamṛtopamam"},{"type":"verse","number":"615","sanskrit":"सन्निपाते तु दाहार्त्तं यः सिञ्चेच्छीतवारिणा आतुरः स कथं जीवेद्भिषग्वा स कथं भवेत्","text":"sannipāte tu dāhārttaṃ yaḥ siñcecchītavāriṇā āturaḥ sa kathaṃ jīvedbhiṣagvā sa kathaṃ bhavet"},{"type":"verse","number":"616","sanskrit":"दुःस्पर्शगोक्षुर क्षुद्रा सिद्धमाहारमर्पयेत् दोषशान्तिबलाग्न्यर्थं त्रिदोषज्वरिणे भिषक्","text":"duḥsparśagokṣura kṣudrā siddhamāhāramarpayet doṣaśāntibalāgnyarthaṃ tridoṣajvariṇe bhiṣak"},{"type":"verse","number":"617","sanskrit":"लाजसक्तून्समश्नीयात्सैन्धवेन समन्वितान् ते च जीर्यन्त्यविघ्नेन ज्वरी जीवेत्तदा ध्रुवम्","text":"lājasaktūnsamaśnīyātsaindhavena samanvitān te ca jīryantyavighnena jvarī jīvettadā dhruvam"},{"type":"verse","number":"618","sanskrit":"रक्तपित्तहितत्वेन तृषादाहज्वरेषु च लाजानां सक्तवः शीता नैव तेऽत्र हिता मताः","text":"raktapittahitatvena tṛṣādāhajvareṣu ca lājānāṃ saktavaḥ śītā naiva te'tra hitā matāḥ"},{"type":"verse","number":"619","sanskrit":"पाचनो दीपनः स्वेद्यो लाजमण्डो यतः स्मृतः दशमूलादिसंसिद्धः संनिपातज्वरे हितः","text":"pācano dīpanaḥ svedyo lājamaṇḍo yataḥ smṛtaḥ daśamūlādisaṃsiddhaḥ saṃnipātajvare hitaḥ"},{"type":"verse","number":"620","sanskrit":"सन्निपातज्वरी यस्तु कम्पते प्रलपत्यपि किञ्चिदेव न जानाति चिकित्सा तस्य कथ्यते","text":"sannipātajvarī yastu kampate pralapatyapi kiñcideva na jānāti cikitsā tasya kathyate"},{"type":"verse","number":"621","sanskrit":"अभ्यञ्जयेत्पुराणेन सर्पिषा पूर्वमेव तम् बलारास्नागुडूच्याद्यैस्तैलैश्च परिषेचयेत्","text":"abhyañjayetpurāṇena sarpiṣā pūrvameva tam balārāsnāguḍūcyādyaistailaiśca pariṣecayet"},{"type":"verse","number":"622","sanskrit":"वर्त्तको वर्त्तिका लावो वार्त्तिकस्तित्तिरिः शशः कुलिङ्गश्च रसेनैषां तर्पयेत यथाऽनलम्","text":"varttako varttikā lāvo vārttikastittiriḥ śaśaḥ kuliṅgaśca rasenaiṣāṃ tarpayeta yathā'nalam"},{"type":"verse","number":"623","sanskrit":"सन्निपाते क्षुधाऽत्त यो भोजयेत्पिशितौदनम् स कथं भिषगाख्यान्तु लभते मनुजाधमः","text":"sannipāte kṣudhā'tta yo bhojayetpiśitaudanam sa kathaṃ bhiṣagākhyāntu labhate manujādhamaḥ"},{"type":"verse","number":"624","sanskrit":"अथ वातोल्वणसन्निपातज्वरस्य चिकित्सा पञ्चमूलीकषायन्तु दशाद्वातोल्बणे ज्वरे भृशोष्णं वा सुखोष्णं वा दृष्ट्वा दोषबलाबलम्","text":"atha vātolvaṇasannipātajvarasya cikitsā pañcamūlīkaṣāyantu daśādvātolbaṇe jvare bhṛśoṣṇaṃ vā sukhoṣṇaṃ vā dṛṣṭvā doṣabalābalam"},{"type":"verse","number":"625","sanskrit":"अथ पित्तोल्वणसन्निपातज्वरस्य चिकित्सा परूषकञ्च त्रिफला देवदारु च कट्फलम् चन्दनं पद्मकञ्चैव तथा कटुकरोहिणी","text":"atha pittolvaṇasannipātajvarasya cikitsā parūṣakañca triphalā devadāru ca kaṭphalam candanaṃ padmakañcaiva tathā kaṭukarohiṇī"},{"type":"verse","number":"626","sanskrit":"पृश्निपर्णी शृतं त्वेभिरुषितं शीतलं जलम् पित्तोत्तरे नृणामेतत्सन्निपातचिकित्सितम्","text":"pṛśniparṇī śṛtaṃ tvebhiruṣitaṃ śītalaṃ jalam pittottare nṛṇāmetatsannipātacikitsitam"},{"type":"verse","number":"627","sanskrit":"किराततिक्तकं मुस्तं गुडूची विश्वभेषजम् पाठोदीच्यं मृणालञ्च शृतं पित्ताधिके पिबेत्","text":"kirātatiktakaṃ mustaṃ guḍūcī viśvabheṣajam pāṭhodīcyaṃ mṛṇālañca śṛtaṃ pittādhike pibet"},{"type":"verse","number":"628","sanskrit":"अथ कफोल्वणसन्निपातज्वरस्य चिकित्सा बृहत्यौ पौष्करं भार्गी शटी शृङ्गी दुरालभा वत्सकस्य तु बीजानि पटोलं कटुरोहिणी","text":"atha kapholvaṇasannipātajvarasya cikitsā bṛhatyau pauṣkaraṃ bhārgī śaṭī śṛṅgī durālabhā vatsakasya tu bījāni paṭolaṃ kaṭurohiṇī"},{"type":"verse","number":"629","sanskrit":"बृहत्यादिगणः शस्तः सन्निपाते कफोत्तरे श्वासादिषु च सर्वेषु हितः सोपद्र वेष्वपि","text":"bṛhatyādigaṇaḥ śastaḥ sannipāte kaphottare śvāsādiṣu ca sarveṣu hitaḥ sopadra veṣvapi"},{"type":"verse","number":"630","sanskrit":"अथ वातपित्तोल्वणसन्निपातज्वरस्य चिकित्सा वातपित्तहरं वृष्यं कनीयः पञ्चमूलकम् तत्क्वाथो मधुना हन्ति वातपित्तोल्वणं ज्वरम्","text":"atha vātapittolvaṇasannipātajvarasya cikitsā vātapittaharaṃ vṛṣyaṃ kanīyaḥ pañcamūlakam tatkvātho madhunā hanti vātapittolvaṇaṃ jvaram"},{"type":"verse","number":"631","sanskrit":"किराततिक्तकं मुस्तं गुडूची विश्वभेषजम् चातुर्भद्र कमित्याहुर्वातपित्तोल्बणे ज्वरे","text":"kirātatiktakaṃ mustaṃ guḍūcī viśvabheṣajam cāturbhadra kamityāhurvātapittolbaṇe jvare"},{"type":"verse","number":"632","sanskrit":"अथ पित्तकफोल्वणसन्निपातज्वरस्य चिकित्सा पर्पटः कट्फलं कुष्ठमुशीरं चन्दनं जलम् नागरं मुस्तकं शृङ्गी पिप्पल्येषां शृतं हितम् तृष्णादाहाग्निमान्द्येषु पित्तश्लेष्मोल्वणो ज्वरे","text":"atha pittakapholvaṇasannipātajvarasya cikitsā parpaṭaḥ kaṭphalaṃ kuṣṭhamuśīraṃ candanaṃ jalam nāgaraṃ mustakaṃ śṛṅgī pippalyeṣāṃ śṛtaṃ hitam tṛṣṇādāhāgnimāndyeṣu pittaśleṣmolvaṇo jvare"},{"type":"verse","number":"633","sanskrit":"अथ वातपित्तकफोल्वणसन्निपातज्वरस्य चिकित्सा नागरं धान्यकं भार्गी पद्मकं रक्तचन्दनम् पटोलः पिचुमन्दश्च त्रिफला मधुकं बला","text":"atha vātapittakapholvaṇasannipātajvarasya cikitsā nāgaraṃ dhānyakaṃ bhārgī padmakaṃ raktacandanam paṭolaḥ picumandaśca triphalā madhukaṃ balā"},{"type":"verse","number":"634","sanskrit":"शर्करा कटुका मुस्तं गजाह्वा व्याधिघातकः किराततिक्तममृता दशमूली निदिग्धिका","text":"śarkarā kaṭukā mustaṃ gajāhvā vyādhighātakaḥ kirātatiktamamṛtā daśamūlī nidigdhikā"},{"type":"verse","number":"635","sanskrit":"योगराजो निहन्त्येष सन्निपातं त्रिकोल्वणम् सन्निपातसमुत्थानं मृत्युमप्यागतं जयेत्","text":"yogarājo nihantyeṣa sannipātaṃ trikolvaṇam sannipātasamutthānaṃ mṛtyumapyāgataṃ jayet"},{"type":"verse","number":"636","sanskrit":"अथ प्रवृद्धमध्यहीनवातादिसन्निपातज्वराणां चिकित्सा प्रवृद्धं कर्शयेद्दोषं क्षीणं संवर्द्धयेद्भिषक् चिकित्सेयं विधातव्या दोषयोर्वृद्धहीनयोः","text":"atha pravṛddhamadhyahīnavātādisannipātajvarāṇāṃ cikitsā pravṛddhaṃ karśayeddoṣaṃ kṣīṇaṃ saṃvarddhayedbhiṣak cikitseyaṃ vidhātavyā doṣayorvṛddhahīnayoḥ"},{"type":"verse","number":"637","sanskrit":"प्रवृद्धे शमिते दोषे मध्यमः स्वयमेव हि शान्तिं याति शमं नीतेऽनुबन्ध्ये त्वनुबन्धवत्","text":"pravṛddhe śamite doṣe madhyamaḥ svayameva hi śāntiṃ yāti śamaṃ nīte'nubandhye tvanubandhavat"},{"type":"verse","number":"638","sanskrit":"भास्वन्मूलं जीरकव्योषभार्गी व्याघ्रीशुण्ठीपुष्करं गोजलेन सिद्धं सद्यः शीतगात्रार्तिमोहश्वासश्लेष्मोद्रे ककासान्निहन्ति","text":"bhāsvanmūlaṃ jīrakavyoṣabhārgī vyāghrīśuṇṭhīpuṣkaraṃ gojalena siddhaṃ sadyaḥ śītagātrārtimohaśvāsaśleṣmodre kakāsānnihanti"},{"type":"verse","number":"639","sanskrit":"कर्कोटिकाकन्दरजः कुलत्थ कृष्णावचाकट्फलकृष्णजीरैः किराततिक्तानलकट्फलाम्बु पथ्याभिरुद्वर्त्तनमत्र शस्तम्","text":"karkoṭikākandarajaḥ kulattha kṛṣṇāvacākaṭphalakṛṣṇajīraiḥ kirātatiktānalakaṭphalāmbu pathyābhirudvarttanamatra śastam"},{"type":"verse","number":"640","sanskrit":"रसविषमरिचमहेश प्रियफलभस्मैकभूचतुर्वसुभिः भागैर्मितमुद् धूलनमिदमधिकस्वेदशैत्यहरम्","text":"rasaviṣamaricamaheśa priyaphalabhasmaikabhūcaturvasubhiḥ bhāgairmitamud dhūlanamidamadhikasvedaśaityaharam"},{"type":"verse","number":"641","sanskrit":"क्षुद्रा ऽमृतापौष्करनागराणि शृतानि पीतानि शिवायुतानि शुण्ठीकणाऽगस्तिरसोषणानि नस्येन तन्द्रा विजयोल्वणानि","text":"kṣudrā 'mṛtāpauṣkaranāgarāṇi śṛtāni pītāni śivāyutāni śuṇṭhīkaṇā'gastirasoṣaṇāni nasyena tandrā vijayolvaṇāni"},{"type":"verse","number":"642","sanskrit":"मरिचकचपचम्पचावचारुक् कृमिहरनागरशर्वरीगवाक्ष्यः छगलकजलकल्किता नितान्तं नसि निहिता ननु तन्द्रि कं जयन्ति","text":"maricakacapacampacāvacāruk kṛmiharanāgaraśarvarīgavākṣyaḥ chagalakajalakalkitā nitāntaṃ nasi nihitā nanu tandri kaṃ jayanti"},{"type":"verse","number":"643","sanskrit":"तुरङ्गलालालवणोत्तमेन्दु मनःशिलामागधिकामधूनि नियोजितान्यक्षिणि निश्चितं च तन्द्रा ञ्च निद्रा ञ्च निवारयन्ति","text":"turaṅgalālālavaṇottamendu manaḥśilāmāgadhikāmadhūni niyojitānyakṣiṇi niścitaṃ ca tandrā ñca nidrā ñca nivārayanti"},{"type":"verse","number":"644","sanskrit":"सतगरवरतिक्तारेवताम्भोदतिक्ता नलदतुरगगन्धाभारतीहारहूराः मलयजदशमूलीशङ्खपुष्पीसुपक्वाः प्रलपनमपहन्युः पानतो नातिदूरात्","text":"satagaravaratiktārevatāmbhodatiktā naladaturagagandhābhāratīhārahūrāḥ malayajadaśamūlīśaṅkhapuṣpīsupakvāḥ pralapanamapahanyuḥ pānato nātidūrāt"},{"type":"verse","number":"645","sanskrit":"सान्त्वनरञ्जनैस्तीक्ष्णै र्नस्यैस्तिमिरसेवनैः सर्वतो विकृतं चित्त मस्य प्रकृतिमानयेत्","text":"sāntvanarañjanaistīkṣṇai rnasyaistimirasevanaiḥ sarvato vikṛtaṃ citta masya prakṛtimānayet"},{"type":"verse","number":"646","sanskrit":"रोहिषधन्वयवासकवासा पर्पटगन्धलताकटुकाभिः शर्करया सममेष कषायः क्षतजष्ठीविन उद्यदुपायः","text":"rohiṣadhanvayavāsakavāsā parpaṭagandhalatākaṭukābhiḥ śarkarayā samameṣa kaṣāyaḥ kṣatajaṣṭhīvina udyadupāyaḥ"},{"type":"verse","number":"647","sanskrit":"पद्मकचन्दनपर्पटमुस्तं जातिकजीवकचन्दनवारि क्लींतकनिम्बयुतं परिपक्वं वारि भवेदिह शोणितहारि","text":"padmakacandanaparpaṭamustaṃ jātikajīvakacandanavāri klīṃtakanimbayutaṃ paripakvaṃ vāri bhavediha śoṇitahāri"},{"type":"verse","number":"648","sanskrit":"मधुकमधूकपरूषकपाथ श्चन्दनपल्लवदारुसनाथः श्रीपर्णीफलशीतकषायः ससित इहस्यादस्रजयाय","text":"madhukamadhūkaparūṣakapātha ścandanapallavadārusanāthaḥ śrīparṇīphalaśītakaṣāyaḥ sasita ihasyādasrajayāya"},{"type":"verse","number":"649","sanskrit":"तुरङ्गगन्धालवणोग्रगन्धा मधूकसारोषणमागधीभिः बस्ताम्बुशुण्ठीलशुनान्विताभिर्नस्यं कृशं भुग्नदृशं करोति","text":"turaṅgagandhālavaṇogragandhā madhūkasāroṣaṇamāgadhībhiḥ bastāmbuśuṇṭhīlaśunānvitābhirnasyaṃ kṛśaṃ bhugnadṛśaṃ karoti"},{"type":"verse","number":"650","sanskrit":"शृङ्गीभार्ग्यभयाऽजाजी कणाभूनिम्बपर्पटः देवदारुवचाकुष्ठ यासकट्फलनागरैः","text":"śṛṅgībhārgyabhayā'jājī kaṇābhūnimbaparpaṭaḥ devadāruvacākuṣṭha yāsakaṭphalanāgaraiḥ"},{"type":"verse","number":"651","sanskrit":"मुस्तधान्याकतिक्तेन्द्रः यवपाठाहरेणुभिः हस्तिपिप्पल्यपामार्गः पिप्पलीमूलचित्रकैः","text":"mustadhānyākatiktendraḥ yavapāṭhāhareṇubhiḥ hastipippalyapāmārgaḥ pippalīmūlacitrakaiḥ"},{"type":"verse","number":"652","sanskrit":"विशालाऽरग्वधारिष्ट शटीवाकुचिकाफलैः विडङ्गरजनीदार्वी यवानीद्वयसंयुतैः","text":"viśālā'ragvadhāriṣṭa śaṭīvākucikāphalaiḥ viḍaṅgarajanīdārvī yavānīdvayasaṃyutaiḥ"},{"type":"verse","number":"653","sanskrit":"समांशैर्विहितः क्वाथो हिङ्ग्वार्द्र करसान्वितः अभिन्यासज्वरं घोरं हन्ति तन्द्रा ञ्च तत्क्षणात्","text":"samāṃśairvihitaḥ kvātho hiṅgvārdra karasānvitaḥ abhinyāsajvaraṃ ghoraṃ hanti tandrā ñca tatkṣaṇāt"},{"type":"verse","number":"654","sanskrit":"प्रमेहं कर्णशूलञ्च सन्निपातांस्त्रयोदश हिक्कां श्वासञ्च कासञ्च तथा सर्वानुपद्र वान्","text":"pramehaṃ karṇaśūlañca sannipātāṃstrayodaśa hikkāṃ śvāsañca kāsañca tathā sarvānupadra vān"},{"type":"verse","number":"655","sanskrit":"किराततिक्ताकुलकृत्कुलिङ्गी कर्पूरकृष्णाकटुतैलयुक्तः अम्लद्र वः संशमयेद्र सज्ञा दोषान्स्तुतो दाशरथिर्यथाऽत्र","text":"kirātatiktākulakṛtkuliṅgī karpūrakṛṣṇākaṭutailayuktaḥ amladra vaḥ saṃśamayedra sajñā doṣānstuto dāśarathiryathā'tra"},{"type":"verse","number":"656","sanskrit":"शालूरपर्णी मालूर मूलामयमधुप्लुता शङ्खकपुष्पीसहिता सेव्या वाचां विशुद्धये","text":"śālūraparṇī mālūra mūlāmayamadhuplutā śaṅkhakapuṣpīsahitā sevyā vācāṃ viśuddhaye"},{"type":"verse","number":"657","sanskrit":"क्षुद्र्रानागरपुष्करामृतलता ब्राह्मीवचासुव्रता भार्गीवासकयासतोयसुरसाक्वाथोजयेज्जिह्वकम् विश्वावर्मविभावरी युगवरावत्सादनीवारिद व्याघ्रीनिम्बपटोलपुष्करजटारुग्दारुभिर्वा कृतः","text":"kṣudrrānāgarapuṣkarāmṛtalatā brāhmīvacāsuvratā bhārgīvāsakayāsatoyasurasākvāthojayejjihvakam viśvāvarmavibhāvarī yugavarāvatsādanīvārida vyāghrīnimbapaṭolapuṣkarajaṭārugdārubhirvā kṛtaḥ"},{"type":"verse","number":"658","sanskrit":"शटीसुरतरूत्तमास्थविरदारुरास्नाः समाः सनागरसुधाऽन्विताः पिब शतावरीसंयुताः मृदुज्वलनपाचिताः सह पुरेण संधिग्रह व्यथाऽपहृतये वृथा शिशिरसेवनं मा कृथाः","text":"śaṭīsuratarūttamāsthaviradārurāsnāḥ samāḥ sanāgarasudhā'nvitāḥ piba śatāvarīsaṃyutāḥ mṛdujvalanapācitāḥ saha pureṇa saṃdhigraha vyathā'pahṛtaye vṛthā śiśirasevanaṃ mā kṛthāḥ"},{"type":"verse","number":"659","sanskrit":"वचाकवचकच्छुरासहचरामृताभङ्गुरासुराह्वघननागरातरुणदारुरास्नापुराः वृषातरुणभीरुभिः सह भवन्ति संधिग्रह व्यथोरुजडिमक्लमभ्रमणपक्षघातद्रुहः","text":"vacākavacakacchurāsahacarāmṛtābhaṅgurāsurāhvaghananāgarātaruṇadārurāsnāpurāḥ vṛṣātaruṇabhīrubhiḥ saha bhavanti saṃdhigraha vyathorujaḍimaklamabhramaṇapakṣaghātadruhaḥ"},{"type":"verse","number":"660","sanskrit":"सुरदारुशटीसुधालता सुवहाशुण्ठ्यमृताः शृता जले सपुराः शमयन्ति सेविताः सततं सन्धिगतं सदागतिम्","text":"suradāruśaṭīsudhālatā suvahāśuṇṭhyamṛtāḥ śṛtā jale sapurāḥ śamayanti sevitāḥ satataṃ sandhigataṃ sadāgatim"},{"type":"verse","number":"661","sanskrit":"मुस्तैरण्डप्राणदाबाणादारू च्छिन्नारास्नाभीरूकर्चूरतिक्ताः वासाविश्वापञ्चमूलाश्वगन्धा हन्युर्मन्यास्तम्भसन्धिग्रहार्त्तीः","text":"mustairaṇḍaprāṇadābāṇādārū cchinnārāsnābhīrūkarcūratiktāḥ vāsāviśvāpañcamūlāśvagandhā hanyurmanyāstambhasandhigrahārttīḥ"},{"type":"verse","number":"662","sanskrit":"इहापहाय व्रतमुष्णवारि ज्वरारियूषादि गदापहारि ज्वरच्छिदं जीवितदञ्च नित्यं मृत्युञ्जयं चेतसि चिन्तयस्व","text":"ihāpahāya vratamuṣṇavāri jvarāriyūṣādi gadāpahāri jvaracchidaṃ jīvitadañca nityaṃ mṛtyuñjayaṃ cetasi cintayasva"},{"type":"verse","number":"663","sanskrit":"कर्पूरप्रकरावदातवपुषं संयोगमुद्रा जुषं शश्वद्भक्तजनेषु भावुकजुषं भालस्फुरच्चक्षुषम् सम्पूर्णामृतकुम्भसम्भृतकरं शुभ्राक्षमालाधरं पिङ्गात्तुङ्गजटाकलापरुचिरं चन्द्रा र्द्धमौलि स्तुहि","text":"karpūraprakarāvadātavapuṣaṃ saṃyogamudrā juṣaṃ śaśvadbhaktajaneṣu bhāvukajuṣaṃ bhālasphuraccakṣuṣam sampūrṇāmṛtakumbhasambhṛtakaraṃ śubhrākṣamālādharaṃ piṅgāttuṅgajaṭākalāparuciraṃ candrā rddhamauli stuhi"},{"type":"verse","number":"664","sanskrit":"भिषग्भिरिति निर्णीतं सन्निपातेऽन्तकाभिधे भेषजं जाह्ववीनीरं वैद्यो गोविन्द एव हि","text":"bhiṣagbhiriti nirṇītaṃ sannipāte'ntakābhidhe bheṣajaṃ jāhvavīnīraṃ vaidyo govinda eva hi"},{"type":"verse","number":"665","sanskrit":"उशीरचन्दनोदीच्य द्रा क्षाऽमलकपर्पटैः शृतं शीतं जलं दद्याद् दाहतृड्ज्वरशान्तये","text":"uśīracandanodīcya drā kṣā'malakaparpaṭaiḥ śṛtaṃ śītaṃ jalaṃ dadyād dāhatṛḍjvaraśāntaye"},{"type":"verse","number":"666","sanskrit":"ससितो निशि पर्युषितः प्रातर्धान्याकतण्डुलक्वाथः पीतः शमयत्यचिरादन्तर्दाहं ज्वरं पैत्तम्","text":"sasito niśi paryuṣitaḥ prātardhānyākataṇḍulakvāthaḥ pītaḥ śamayatyacirādantardāhaṃ jvaraṃ paittam"},{"type":"verse","number":"667","sanskrit":"पथ्यां तैलघृतक्षौद्रै र्लिह्याद्दाहविनाशिनीम्","text":"pathyāṃ tailaghṛtakṣaudrai rlihyāddāhavināśinīm"},{"type":"verse","number":"668","sanskrit":"प्रशमयति दाहमचिराद् दधियुक्कर्कन्धुपल्लवैर्लेपः लेपो हिमकरमलयज निम्बदलैस्तक्रपिष्टैर्वा","text":"praśamayati dāhamacirād dadhiyukkarkandhupallavairlepaḥ lepo himakaramalayaja nimbadalaistakrapiṣṭairvā"},{"type":"verse","number":"669","sanskrit":"उत्तानसुप्तस्य गभीरताम्र कांस्यादिपात्रे निहिते च नाभौ शीताम्बुधारा बहुलापतन्ती निहन्ति दाहं त्वरितं ज्वरञ्च","text":"uttānasuptasya gabhīratāmra kāṃsyādipātre nihite ca nābhau śītāmbudhārā bahulāpatantī nihanti dāhaṃ tvaritaṃ jvarañca"},{"type":"verse","number":"670","sanskrit":"शीताम्भसा तु शतशश्च विलोडितेन गव्येन चन्दनयुतेन घृतेन दिग्ध्वा दाहज्वरी सकमलोत्पलमाल्यधारी क्षिप्रं विशेत्सलिलकोष्ठमनल्पकालम्","text":"śītāmbhasā tu śataśaśca viloḍitena gavyena candanayutena ghṛtena digdhvā dāhajvarī sakamalotpalamālyadhārī kṣipraṃ viśetsalilakoṣṭhamanalpakālam"},{"type":"verse","number":"671","sanskrit":"काञ्जिकार्द्र पटेनावगुण्ठनं दाहनाशनम् अथ गोतक्रसंस्विन्न शीतलीकृतवाससा","text":"kāñjikārdra paṭenāvaguṇṭhanaṃ dāhanāśanam atha gotakrasaṃsvinna śītalīkṛtavāsasā"},{"type":"verse","number":"672","sanskrit":"दाहवम्यर्दितं क्षामं निरन्नं तृष्णयाऽन्वितम् शर्करामधुसंयुक्तं पाययेल्लाजतर्पणम्","text":"dāhavamyarditaṃ kṣāmaṃ nirannaṃ tṛṣṇayā'nvitam śarkarāmadhusaṃyuktaṃ pāyayellājatarpaṇam"},{"type":"verse","number":"673","sanskrit":"वाप्यःकमलहासिन्यो जलयन्त्रगृहाः शुभाः नार्यश्चन्दनदिग्धाङ्ग्यो दाहदैन्यहरा मताः","text":"vāpyaḥkamalahāsinyo jalayantragṛhāḥ śubhāḥ nāryaścandanadigdhāṅgyo dāhadainyaharā matāḥ"},{"type":"verse","number":"674","sanskrit":"मुक्तावलीचन्दनशीतलानां सुगन्धपुष्पाम्बरभूषितानाम् नितम्बिनीनां सुपयोधराणामालिङ्गनान्याशु हरन्ति दाहम्","text":"muktāvalīcandanaśītalānāṃ sugandhapuṣpāmbarabhūṣitānām nitambinīnāṃ supayodharāṇāmāliṅganānyāśu haranti dāham"},{"type":"verse","number":"675","sanskrit":"प्रह्लादञ्चास्य विज्ञाय ताः स्त्रीरपनयेत्पुनः हितञ्च भोजयेदन्नं येनाप्नोति सुखं महत्","text":"prahlādañcāsya vijñāya tāḥ strīrapanayetpunaḥ hitañca bhojayedannaṃ yenāpnoti sukhaṃ mahat"},{"type":"verse","number":"676","sanskrit":"कणोषणोग्रालवणोत्तमानि करञ्जबीजं प्रमदामलानि पथ्याऽक्षसिद्धार्थकहिङ्गुशुण्ठी युतानि बस्ताम्बुविमिश्रितानि","text":"kaṇoṣaṇogrālavaṇottamāni karañjabījaṃ pramadāmalāni pathyā'kṣasiddhārthakahiṅguśuṇṭhī yutāni bastāmbuvimiśritāni"},{"type":"verse","number":"677","sanskrit":"पिष्ट्वा गुटीयं नयने विधेया प्रचेतनेऽतिप्रथिताऽन्वितार्था चित्तभ्रमापस्मृतिभूतदोष शिरोऽक्षिरोगभ्रमनाशहेतुः","text":"piṣṭvā guṭīyaṃ nayane vidheyā pracetane'tiprathitā'nvitārthā cittabhramāpasmṛtibhūtadoṣa śiro'kṣirogabhramanāśahetuḥ"},{"type":"verse","number":"678","sanskrit":"कुम्भोद्भवतरोरम्भो गुडं विश्वकणाऽन्वितम् निहितं नसि नूनं स्याच्चित्तभ्रमविनाशनम्","text":"kumbhodbhavatarorambho guḍaṃ viśvakaṇā'nvitam nihitaṃ nasi nūnaṃ syāccittabhramavināśanam"},{"type":"verse","number":"679","sanskrit":"मुरामूर्द्धजमेघाह्व मधूकमलयोद्भवैः मरुत्तरुमधून्मिश्रैः पुरपाणिजपांशुभिः","text":"murāmūrddhajameghāhva madhūkamalayodbhavaiḥ maruttarumadhūnmiśraiḥ purapāṇijapāṃśubhiḥ"},{"type":"verse","number":"680","sanskrit":"लोहलामज्जकैला भिर्धूपश्चित्तभ्रमापहः ग्रहदोषहरः श्रीदः सौभाग्यकर उत्तमः","text":"lohalāmajjakailā bhirdhūpaścittabhramāpahaḥ grahadoṣaharaḥ śrīdaḥ saubhāgyakara uttamaḥ"},{"type":"verse","number":"681","sanskrit":"मृद्वीकाऽमरदारुमत्स्यशकलामुस्तामलक्योऽमृता पथ्याऽरेवतरामसेनकरजोराजीफलैः संयुताः हन्युश्चित्तरुजोऽथ दर्दुरदलापाठापटोलीपयः पथ्यापर्पटराजवृक्षकटुकाशम्बूकपुष्प्यः शृताः","text":"mṛdvīkā'maradārumatsyaśakalāmustāmalakyo'mṛtā pathyā'revatarāmasenakarajorājīphalaiḥ saṃyutāḥ hanyuścittarujo'tha darduradalāpāṭhāpaṭolīpayaḥ pathyāparpaṭarājavṛkṣakaṭukāśambūkapuṣpyaḥ śṛtāḥ"},{"type":"verse","number":"682","sanskrit":"प्रलेपस्तमस्तं नयत्यल्पमेकः समुद्रि क्तशोथञ्च रक्तावशेषः पक्वे च शस्त्रक्रिया पूयजित्सा व्रणत्वं गते चोचिता तच्चिकित्सा","text":"pralepastamastaṃ nayatyalpamekaḥ samudri ktaśothañca raktāvaśeṣaḥ pakve ca śastrakriyā pūyajitsā vraṇatvaṃ gate cocitā taccikitsā"},{"type":"verse","number":"683","sanskrit":"निशाविशालाऽमयमाणिमन्थ दार्वीङ्गुदीमूलकृतः प्रलेपः प्रभाकरक्षीरयुतः प्रभावाद् व्यस्तः समस्तोऽप्यथ कर्णिकघ्नः","text":"niśāviśālā'mayamāṇimantha dārvīṅgudīmūlakṛtaḥ pralepaḥ prabhākarakṣīrayutaḥ prabhāvād vyastaḥ samasto'pyatha karṇikaghnaḥ"},{"type":"verse","number":"684","sanskrit":"कुलत्थः कट्फलं शुण्ठी कारवी च समांशकैः सुखोष्णैर्लेपनं कार्यं कर्णमूले मुहुर्मुहुः","text":"kulatthaḥ kaṭphalaṃ śuṇṭhī kāravī ca samāṃśakaiḥ sukhoṣṇairlepanaṃ kāryaṃ karṇamūle muhurmuhuḥ"},{"type":"verse","number":"685","sanskrit":"गैरिकं कठिनी शुण्ठी कट्फलारग्वधैः समैः उष्णैः काञ्जिकसम्पिष्टैर्लेपः कर्णकमूलनुत्","text":"gairikaṃ kaṭhinī śuṇṭhī kaṭphalāragvadhaiḥ samaiḥ uṣṇaiḥ kāñjikasampiṣṭairlepaḥ karṇakamūlanut"},{"type":"verse","number":"686","sanskrit":"शिग्रुराजिकयोः कल्कं कर्णमूले प्रलेपयेत् कर्णमूलभवः शोथस्तेन लेपेन शाम्यति","text":"śigrurājikayoḥ kalkaṃ karṇamūle pralepayet karṇamūlabhavaḥ śothastena lepena śāmyati"},{"type":"verse","number":"687","sanskrit":"अशिशिरजलपरिमृदितं मरिचकणाजीरसिन्धुजं त्वरितम् नस्यविधिसेवितं ननु कर्णकरूङ्नाशकृद् गदितम्","text":"aśiśirajalaparimṛditaṃ maricakaṇājīrasindhujaṃ tvaritam nasyavidhisevitaṃ nanu karṇakarūṅnāśakṛd gaditam"},{"type":"verse","number":"688","sanskrit":"भार्गीजयापौष्करकण्टकारी कटुत्रिकोग्राघनकुण्डलीभिः कुलीरशृङ्गीकटुकारसाभिः कृतः कषायः किल कर्णिकघ्नः","text":"bhārgījayāpauṣkarakaṇṭakārī kaṭutrikogrāghanakuṇḍalībhiḥ kulīraśṛṅgīkaṭukārasābhiḥ kṛtaḥ kaṣāyaḥ kila karṇikaghnaḥ"},{"type":"verse","number":"689","sanskrit":"दशमूलमत्स्यशकला चपलात्रिफलामहौषधकिरातैः मरिचं चाशु क्वथितं बलादपहन्ति कर्णरुजः सकलाः","text":"daśamūlamatsyaśakalā capalātriphalāmahauṣadhakirātaiḥ maricaṃ cāśu kvathitaṃ balādapahanti karṇarujaḥ sakalāḥ"},{"type":"verse","number":"690","sanskrit":"फलत्रिकत्र्यूषणमुस्तकट्वी कलिङ्गसिंहाननशर्वरीभिः क्वाथः कृतः कृन्तति कण्ठकुब्जं कण्ठीरवः कुञ्जरमाशु तद्वत्","text":"phalatrikatryūṣaṇamustakaṭvī kaliṅgasiṃhānanaśarvarībhiḥ kvāthaḥ kṛtaḥ kṛntati kaṇṭhakubjaṃ kaṇṭhīravaḥ kuñjaramāśu tadvat"},{"type":"verse","number":"691","sanskrit":"किरातकटुकाकणाकुटजकण्टकारीशटी कलिद्रुकिलिमाभयाकटुककट्फलाम्भोधरः विषाऽमलकपुष्करानलकुलीरशृङ्गीवृषैर्महौषधसखैरयं जयति कण्ठकुब्जं गणः","text":"kirātakaṭukākaṇākuṭajakaṇṭakārīśaṭī kalidrukilimābhayākaṭukakaṭphalāmbhodharaḥ viṣā'malakapuṣkarānalakulīraśṛṅgīvṛṣairmahauṣadhasakhairayaṃ jayati kaṇṭhakubjaṃ gaṇaḥ"},{"type":"verse","number":"692","sanskrit":"अभिघाताभिषङ्गाभ्याम भिचाराभिशापतः आगन्तुर्जायते दोषैर्यथास्वं तं विभावयेत्","text":"abhighātābhiṣaṅgābhyāma bhicārābhiśāpataḥ āganturjāyate doṣairyathāsvaṃ taṃ vibhāvayet"},{"type":"verse","number":"693","sanskrit":"ये भूतविषवाय्वग्निक्षतभङ्गादिसम्भवाः रागद्वेषभयाद्यैश्च ते स्युरागन्तवो गदाः","text":"ye bhūtaviṣavāyvagnikṣatabhaṅgādisambhavāḥ rāgadveṣabhayādyaiśca te syurāgantavo gadāḥ"},{"type":"verse","number":"694","sanskrit":"कामशोकभयाद्वायुः क्रोधात्पित्तं त्रयो मलाः भूताभिषङ्गात्कुप्यन्ति भूतसामान्यलक्षणाः","text":"kāmaśokabhayādvāyuḥ krodhātpittaṃ trayo malāḥ bhūtābhiṣaṅgātkupyanti bhūtasāmānyalakṣaṇāḥ"},{"type":"verse","number":"695","sanskrit":"श्यावास्यता विषकृते तथाऽतीसार एव च भक्तारूचिः पिपासा च तोदश्च सह मूर्च्छया","text":"śyāvāsyatā viṣakṛte tathā'tīsāra eva ca bhaktārūciḥ pipāsā ca todaśca saha mūrcchayā"},{"type":"verse","number":"696","sanskrit":"ओषधीगन्धजे मूर्च्छा शिरोरुग्वमथुस्तथा कामजे चित्तविभ्रंशस्तन्द्रा ऽलस्यमभोजनम् हृदये वेदना चास्य गात्रञ्च परिशुष्यति","text":"oṣadhīgandhaje mūrcchā śirorugvamathustathā kāmaje cittavibhraṃśastandrā 'lasyamabhojanam hṛdaye vedanā cāsya gātrañca pariśuṣyati"},{"type":"verse","number":"697","sanskrit":"मूर्च्छाङ्गमर्दस्तृण्नेत्रचापल्यं कुचवक्त्रयोः स्वेदः स्याद्धृदि दाहश्च स्त्रीणां कामज्वरे भवेत्","text":"mūrcchāṅgamardastṛṇnetracāpalyaṃ kucavaktrayoḥ svedaḥ syāddhṛdi dāhaśca strīṇāṃ kāmajvare bhavet"},{"type":"verse","number":"698","sanskrit":"बालकं शतपत्राणि गन्धसारमुशीरकम् चोचधान्येयकं मांसी क्वाथः कामज्वरापहः","text":"bālakaṃ śatapatrāṇi gandhasāramuśīrakam cocadhānyeyakaṃ māṃsī kvāthaḥ kāmajvarāpahaḥ"},{"type":"verse","number":"699","sanskrit":"सन्ध्यायां संस्तरः कार्यः सुगन्धैः कुसुमैर्भृशम् क्रीडनीयं स्वकान्तेन सह रात्रौ तथा स्त्रिया","text":"sandhyāyāṃ saṃstaraḥ kāryaḥ sugandhaiḥ kusumairbhṛśam krīḍanīyaṃ svakāntena saha rātrau tathā striyā"},{"type":"verse","number":"700","sanskrit":"भयात्प्रलापः शोकाच्च भवेत्कोपाच्च वेपथुः","text":"bhayātpralāpaḥ śokācca bhavetkopācca vepathuḥ"},{"type":"verse","number":"701","sanskrit":"भूताभिषङ्गादुद्वेगो हास्यरोदनकम्पनम् केचिद्भूताभिषङ्गोत्थं ब्रुवते विषमज्वरम्","text":"bhūtābhiṣaṅgādudvego hāsyarodanakampanam kecidbhūtābhiṣaṅgotthaṃ bruvate viṣamajvaram"},{"type":"verse","number":"702","sanskrit":"अभिचाराभिशापाभ्यां मोहस्तृष्णा च जायते","text":"abhicārābhiśāpābhyāṃ mohastṛṣṇā ca jāyate"},{"type":"verse","number":"703","sanskrit":"आगन्तुजे ज्वरे नैव नरः कुर्वीत लङ्घनम्","text":"āgantuje jvare naiva naraḥ kurvīta laṅghanam"},{"type":"verse","number":"704","sanskrit":"लङ्घनं न हितं कामशोकचिन्ताप्रहारजे भयभूतश्रमक्रोधलङ्घनैश्च कृते ज्वरे","text":"laṅghanaṃ na hitaṃ kāmaśokacintāprahāraje bhayabhūtaśramakrodhalaṅghanaiśca kṛte jvare"},{"type":"verse","number":"705","sanskrit":"किन्त्वग्नौ दीपिते तत्र दद्यान्मांसरसौदनम् अभिघातज्वरे युञ्ज्यात् क्रियामुष्णविवर्जिताम् कषाय मधुरं स्निग्धं यथादोषमथापि च अभिघातज्वरो नश्येत् पानाभ्यङ्गेन सर्पिषः रक्तावसेकैर्मेध्यैश्च तथा मांसरसौदनैः","text":"kintvagnau dīpite tatra dadyānmāṃsarasaudanam abhighātajvare yuñjyāt kriyāmuṣṇavivarjitām kaṣāya madhuraṃ snigdhaṃ yathādoṣamathāpi ca abhighātajvaro naśyet pānābhyaṅgena sarpiṣaḥ raktāvasekairmedhyaiśca tathā māṃsarasaudanaiḥ"},{"type":"verse","number":"706","sanskrit":"व्यधबन्धश्रमात्यध्वभङ्गभ्रंशसमुद्भवान् ज्वरानुपाचरेत्पूर्वं क्षीरमांसरसौदनैः","text":"vyadhabandhaśramātyadhvabhaṅgabhraṃśasamudbhavān jvarānupācaretpūrvaṃ kṣīramāṃsarasaudanaiḥ"},{"type":"verse","number":"707","sanskrit":"अध्वश्रान्तेषु वाऽभ्यङ्गं दिवा निद्रा ञ्च कारयेत्","text":"adhvaśrānteṣu vā'bhyaṅgaṃ divā nidrā ñca kārayet"},{"type":"verse","number":"708","sanskrit":"ओषधीगन्धविषजौ विषपित्तप्रबाधनैः जयेत्कषायैर्मतिमान् सर्वगन्धकृतैर्भिषक्","text":"oṣadhīgandhaviṣajau viṣapittaprabādhanaiḥ jayetkaṣāyairmatimān sarvagandhakṛtairbhiṣak"},{"type":"verse","number":"709","sanskrit":"चातुर्जातककर्पूरकङ्को लागुरुकुङ्कुमम् लवङ्गसहितञ्चैव सर्वगन्धं विनिर्दिशेत्","text":"cāturjātakakarpūrakaṅko lāgurukuṅkumam lavaṅgasahitañcaiva sarvagandhaṃ vinirdiśet"},{"type":"verse","number":"710","sanskrit":"क्रोधजे पित्तजित्कार्यं धार्यं सद्वाक्यमेव च आश्वासेनेष्टलाभेन वायोः प्रशमनेन च हर्षणैश्च शमं यान्ति कामक्रोधभयज्वराः","text":"krodhaje pittajitkāryaṃ dhāryaṃ sadvākyameva ca āśvāseneṣṭalābhena vāyoḥ praśamanena ca harṣaṇaiśca śamaṃ yānti kāmakrodhabhayajvarāḥ"},{"type":"verse","number":"711","sanskrit":"कामैरथ मनोघ्नैश्च पित्तघ्नैश्चाप्युपक्रमैः सद्वाक्यैश्च शमं याति ज्वरः क्रोधसमुत्थितः","text":"kāmairatha manoghnaiśca pittaghnaiścāpyupakramaiḥ sadvākyaiśca śamaṃ yāti jvaraḥ krodhasamutthitaḥ"},{"type":"verse","number":"712","sanskrit":"कामात्क्रोधज्वरो नश्येत् क्रोधात्कामज्वरस्तथा घातिताभ्यामुभाभ्याञ्च कामक्रोधज्वरक्षयः","text":"kāmātkrodhajvaro naśyet krodhātkāmajvarastathā ghātitābhyāmubhābhyāñca kāmakrodhajvarakṣayaḥ"},{"type":"verse","number":"713","sanskrit":"भूतविद्यासमुद्दिष्टैर्बन्धावेशनताडनैः जयेद् भूताभिषङ्गोत्थं मनः शान्त्या च मानसम्","text":"bhūtavidyāsamuddiṣṭairbandhāveśanatāḍanaiḥ jayed bhūtābhiṣaṅgotthaṃ manaḥ śāntyā ca mānasam"},{"type":"verse","number":"714","sanskrit":"सहदेवाया मूलं विधिना कण्ठे निबद्धमपहरति एकद्वित्रिचतुर्भिर्दिवसैर्भूतज्वरं पुंसाम्","text":"sahadevāyā mūlaṃ vidhinā kaṇṭhe nibaddhamapaharati ekadvitricaturbhirdivasairbhūtajvaraṃ puṃsām"},{"type":"verse","number":"715","sanskrit":"अभिचाराभिशापोत्थौ ज्वरौ होमादिभिर्जयेत् दानस्वस्त्ययनातिथ्यैरुत्पातग्रहदुष्टिजौ","text":"abhicārābhiśāpotthau jvarau homādibhirjayet dānasvastyayanātithyairutpātagrahaduṣṭijau"},{"type":"verse","number":"716","sanskrit":"इत्यागन्तुज्वराधिकारः दोषोऽल्पोऽहितसम्भूतो ज्वरोत्सृष्टस्य वा पुनः धातुमन्यतमं प्राप्य करोति विषमज्वरम्","text":"ityāgantujvarādhikāraḥ doṣo'lpo'hitasambhūto jvarotsṛṣṭasya vā punaḥ dhātumanyatamaṃ prāpya karoti viṣamajvaram"},{"type":"verse","number":"717","sanskrit":"सन्ततं रस रक्तस्थः सततं रक्तधातुगः दोषः क्रुद्धो ज्वरं पुंसां सोऽन्येद्युः पिशिताश्रितः","text":"santataṃ rasa raktasthaḥ satataṃ raktadhātugaḥ doṣaḥ kruddho jvaraṃ puṃsāṃ so'nyedyuḥ piśitāśritaḥ"},{"type":"verse","number":"718","sanskrit":"मेदोगतस्तृतीयेऽह्नि अस्थिमज्जगतः पुनः कुर्य्याच्चातुर्थिकं घोरमन्तकं रोगसङ्करम्","text":"medogatastṛtīye'hni asthimajjagataḥ punaḥ kuryyāccāturthikaṃ ghoramantakaṃ rogasaṅkaram"},{"type":"verse","number":"719","sanskrit":"यः स्यादनियतात्कालाच्छीतोष्णाभ्यां तथैव च वेगतश्चापि विषमो ज्वरः स विषमः स्मृतः","text":"yaḥ syādaniyatātkālācchītoṣṇābhyāṃ tathaiva ca vegataścāpi viṣamo jvaraḥ sa viṣamaḥ smṛtaḥ"},{"type":"verse","number":"720","sanskrit":"सन्ततः सततोऽन्येद्युस्तृतीयकचतुर्थकौ","text":"santataḥ satato'nyedyustṛtīyakacaturthakau"},{"type":"verse","number":"721","sanskrit":"सप्ताहं वा दशाहं द्वादशाहमथापि वा सन्तत्या योऽविसर्गी स्यात् सन्ततः स निगद्यते","text":"saptāhaṃ vā daśāhaṃ dvādaśāhamathāpi vā santatyā yo'visargī syāt santataḥ sa nigadyate"},{"type":"verse","number":"722","sanskrit":"अहोरात्रे सततको द्वौ कालावनुर्त्तते","text":"ahorātre satatako dvau kālāvanurttate"},{"type":"verse","number":"723","sanskrit":"अन्येद्युष्कस्त्वहोरात्रादेककालं प्रवर्त्तते","text":"anyedyuṣkastvahorātrādekakālaṃ pravarttate"},{"type":"verse","number":"724","sanskrit":"तृतीयकस्तृतीयेऽह्नि चतुर्थेऽह्नि चतुर्थकः","text":"tṛtīyakastṛtīye'hni caturthe'hni caturthakaḥ"},{"type":"verse","number":"725","sanskrit":"कफस्थानविभागेन यथासंख्यं करोति हि सततान्येद्युस्तृतीय चतुर्थकप्रलेपकान् अहोरात्रादहोरात्रात् स्थानात्स्थानं प्रपद्यते दोष आमाशयं प्राप्य करोति विषमज्वरम्","text":"kaphasthānavibhāgena yathāsaṃkhyaṃ karoti hi satatānyedyustṛtīya caturthakapralepakān ahorātrādahorātrāt sthānātsthānaṃ prapadyate doṣa āmāśayaṃ prāpya karoti viṣamajvaram"},{"type":"verse","number":"726","sanskrit":"निवृत्तः पुनरायाति विषमो नियते दिने स्वभावं कारणं तत्र मन्यन्ते मुनिपुङ्गवाः","text":"nivṛttaḥ punarāyāti viṣamo niyate dine svabhāvaṃ kāraṇaṃ tatra manyante munipuṅgavāḥ"},{"type":"verse","number":"727","sanskrit":"अधिशेते यथा भूमिं बीजं काले प्ररोहति अधिशेते तथा धातून् दोषः काले प्रकुप्यति","text":"adhiśete yathā bhūmiṃ bījaṃ kāle prarohati adhiśete tathā dhātūn doṣaḥ kāle prakupyati"},{"type":"verse","number":"728","sanskrit":"स चापि विषमो देहं न कदाचित्प्रमुञ्चति ग्लानिगौरवकार्श्येभ्यः स यस्मान्न प्रमुच्यते","text":"sa cāpi viṣamo dehaṃ na kadācitpramuñcati glānigauravakārśyebhyaḥ sa yasmānna pramucyate"},{"type":"verse","number":"729","sanskrit":"वेगे तु समतिक्रान्ते गतोऽयमिति लक्ष्यते धात्वन्तरेषु लीनत्वात् सौक्ष्म्यान्नैवोपलभ्यते","text":"vege tu samatikrānte gato'yamiti lakṣyate dhātvantareṣu līnatvāt saukṣmyānnaivopalabhyate"},{"type":"verse","number":"730","sanskrit":"कफपित्तात्त्रिकग्राही पृष्ठाद्वातकफात्मकः वातपित्ताच्छिरोग्राही त्रिविधः स्यात्तृतीयकः","text":"kaphapittāttrikagrāhī pṛṣṭhādvātakaphātmakaḥ vātapittācchirogrāhī trividhaḥ syāttṛtīyakaḥ"},{"type":"verse","number":"731","sanskrit":"चतुर्थको दर्शयति स्वभावं द्बिविधं ज्वरः जङ्घाभ्यां श्लैष्मिकः पूर्वं शिरसोऽनिलसम्भवः","text":"caturthako darśayati svabhāvaṃ dbividhaṃ jvaraḥ jaṅghābhyāṃ ślaiṣmikaḥ pūrvaṃ śiraso'nilasambhavaḥ"},{"type":"verse","number":"732","sanskrit":"मध्यकायन्तु गृह्णाति पूर्वं यस्तु स पित्तजः विषमज्वर एवान्यश्चतुर्थकविपर्ययः","text":"madhyakāyantu gṛhṇāti pūrvaṃ yastu sa pittajaḥ viṣamajvara evānyaścaturthakaviparyayaḥ"},{"type":"verse","number":"733","sanskrit":"अस्थिमज्जगतो दोषश्चतुर्थकविपर्ययः जायते भिषजा ज्ञेयो विषमज्वर एव सः","text":"asthimajjagato doṣaścaturthakaviparyayaḥ jāyate bhiṣajā jñeyo viṣamajvara eva saḥ"},{"type":"verse","number":"734","sanskrit":"स मध्ये ज्वरयत्यह्नी आद्यन्ते च विमुञ्चति","text":"sa madhye jvarayatyahnī ādyante ca vimuñcati"},{"type":"verse","number":"735","sanskrit":"त्वक्स्थौ श्लेष्मानिलौ शीतमादौ जनयतो ज्वरम् तयोः प्रशान्तयोः पित्तमन्तर्दाहं करोति च","text":"tvaksthau śleṣmānilau śītamādau janayato jvaram tayoḥ praśāntayoḥ pittamantardāhaṃ karoti ca"},{"type":"verse","number":"736","sanskrit":"करोत्यादौ तथा पित्तं त्वक्स्थं दाहमतीव च तस्मिन्प्रशान्ते त्वितरौ कुरुतः शीतमन्ततः","text":"karotyādau tathā pittaṃ tvaksthaṃ dāhamatīva ca tasminpraśānte tvitarau kurutaḥ śītamantataḥ"},{"type":"verse","number":"737","sanskrit":"द्वावेतौ दाहशीतादौ ज्वरौ संसर्गजौ स्मृतौ दाहपूर्वस्तयोः कष्टः सुखसाध्यतमोऽपरः","text":"dvāvetau dāhaśītādau jvarau saṃsargajau smṛtau dāhapūrvastayoḥ kaṣṭaḥ sukhasādhyatamo'paraḥ"},{"type":"verse","number":"738","sanskrit":"विदग्धेऽन्नरसे देहे श्लेष्मपित्ते व्यवस्थिते तेनार्द्धं शीतलं देहमर्द्धमुष्णं प्रजायते","text":"vidagdhe'nnarase dehe śleṣmapitte vyavasthite tenārddhaṃ śītalaṃ dehamarddhamuṣṇaṃ prajāyate"},{"type":"verse","number":"739","sanskrit":"काये दुष्टं यदा पित्तं श्लेष्मा चान्ते व्यवस्थितम् तेनोष्णत्वं शरीरस्य शीतत्वं हस्त पादयोः","text":"kāye duṣṭaṃ yadā pittaṃ śleṣmā cānte vyavasthitam tenoṣṇatvaṃ śarīrasya śītatvaṃ hasta pādayoḥ"},{"type":"verse","number":"740","sanskrit":"काये श्लेष्मा यदा दुष्टः पित्तं चान्ते व्यवस्थितम् शीतत्वं तेन गात्रे स्यादुष्णत्वं हस्तपादयोः","text":"kāye śleṣmā yadā duṣṭaḥ pittaṃ cānte vyavasthitam śītatvaṃ tena gātre syāduṣṇatvaṃ hastapādayoḥ"},{"type":"verse","number":"741","sanskrit":"प्रलिम्पन्निव गात्राणि घर्मेण गौरवेण च मन्दज्वरविलेपी च स शीतः स्यात्प्रलेपकः","text":"pralimpanniva gātrāṇi gharmeṇa gauraveṇa ca mandajvaravilepī ca sa śītaḥ syātpralepakaḥ"},{"type":"verse","number":"742","sanskrit":"ज्वराश्च विषमाः सर्वे सन्निपातसमुद्भवाः यथोल्वणस्य दोषस्य तेषु कार्यं चिकित्सितम्","text":"jvarāśca viṣamāḥ sarve sannipātasamudbhavāḥ yatholvaṇasya doṣasya teṣu kāryaṃ cikitsitam"},{"type":"verse","number":"743","sanskrit":"विषमेष्वपि कर्त्तव्यमूर्ध्वञ्चाधश्च शोधनम् स्निग्धोष्णैरन्नपानैश्च शमयेद्विषमज्वरम्","text":"viṣameṣvapi karttavyamūrdhvañcādhaśca śodhanam snigdhoṣṇairannapānaiśca śamayedviṣamajvaram"},{"type":"verse","number":"744","sanskrit":"कालिङ्गकः पटोलस्य पत्रं कटुकरोहिणी पटोलं सारिवा मुस्तं पाठा कटुकरोहिणी","text":"kāliṅgakaḥ paṭolasya patraṃ kaṭukarohiṇī paṭolaṃ sārivā mustaṃ pāṭhā kaṭukarohiṇī"},{"type":"verse","number":"745","sanskrit":"निम्बः पटोलं त्रिफला मृद्बीका मुस्तवत्सकौ किराततिक्तममृता चन्दनं विश्वभेषजम्","text":"nimbaḥ paṭolaṃ triphalā mṛdbīkā mustavatsakau kirātatiktamamṛtā candanaṃ viśvabheṣajam"},{"type":"verse","number":"746","sanskrit":"गुडूच्यामलकं मुस्तमर्द्धश्लोकसमापनाः कषायाः शमयन्त्याशु पञ्च पञ्चविधं ज्वरम्","text":"guḍūcyāmalakaṃ mustamarddhaślokasamāpanāḥ kaṣāyāḥ śamayantyāśu pañca pañcavidhaṃ jvaram"},{"type":"verse","number":"747","sanskrit":"महाबलामूलमहौषधाभ्यां क्वाथो निहन्याद्बिषमज्वरं हि शीतं सकम्पं परिदाहयुक्तं विनाशयेद् द्वित्रिदिनप्रयोगात्","text":"mahābalāmūlamahauṣadhābhyāṃ kvātho nihanyādbiṣamajvaraṃ hi śītaṃ sakampaṃ paridāhayuktaṃ vināśayed dvitridinaprayogāt"},{"type":"verse","number":"748","sanskrit":"मुस्ताऽमलकगुडूची विश्वौषधकण्टकारिकाक्वाथः पीतः सकणाचूर्णः समधुर्विषमं ज्वरं हन्ति","text":"mustā'malakaguḍūcī viśvauṣadhakaṇṭakārikākvāthaḥ pītaḥ sakaṇācūrṇaḥ samadhurviṣamaṃ jvaraṃ hanti"},{"type":"verse","number":"749","sanskrit":"तिलतैललवणयुक्तः कल्को लशुनस्य सेवितः प्रातः विषज्वरमपहरते वातव्याधीनशेषांश्च","text":"tilatailalavaṇayuktaḥ kalko laśunasya sevitaḥ prātaḥ viṣajvaramapaharate vātavyādhīnaśeṣāṃśca"},{"type":"verse","number":"750","sanskrit":"कालजाजी तु सगुडा विषमज्वरनाशिनी मधुना चाभया लीढा हन्त्याशु विषमज्वरान्","text":"kālajājī tu saguḍā viṣamajvaranāśinī madhunā cābhayā līḍhā hantyāśu viṣamajvarān"},{"type":"verse","number":"751","sanskrit":"पीतो मरिचचूर्णेन तुलसीपत्रजो रसः द्रो णपुष्पीरसो वाऽपि निहन्ति विषमज्वरान्","text":"pīto maricacūrṇena tulasīpatrajo rasaḥ dro ṇapuṣpīraso vā'pi nihanti viṣamajvarān"},{"type":"verse","number":"752","sanskrit":"समगुडमसितं जीरकमीषन्मरिचेन भक्षितं सद्यः एकाहिकंप्रशमयेत् समरेष्विव दानवानिन्द्रः","text":"samaguḍamasitaṃ jīrakamīṣanmaricena bhakṣitaṃ sadyaḥ ekāhikaṃpraśamayet samareṣviva dānavānindraḥ"},{"type":"verse","number":"753","sanskrit":"शुण्ठ्यजाजी गुडं पिष्टं पीतमुष्णेन वारिणा जीर्णमद्येन तक्रेण तीव्रं शीतज्वरं जयेत्","text":"śuṇṭhyajājī guḍaṃ piṣṭaṃ pītamuṣṇena vāriṇā jīrṇamadyena takreṇa tīvraṃ śītajvaraṃ jayet"},{"type":"verse","number":"754","sanskrit":"अथ सन्ततादिज्वराणां सामान्यचिकित्सा अमृतायाः शतं चूर्णं वाससा परिशोधितम् पृथक षोडश भागाः स्युर्गुडमाक्षिकसर्पिषाम्","text":"atha santatādijvarāṇāṃ sāmānyacikitsā amṛtāyāḥ śataṃ cūrṇaṃ vāsasā pariśodhitam pṛthaka ṣoḍaśa bhāgāḥ syurguḍamākṣikasarpiṣām"},{"type":"verse","number":"755","sanskrit":"यथाऽग्नि भक्षयेदेतन्नरो हितमिताशनः नास्य कश्चिद्भवेद्व्याधिर्न जरा पलितं न च","text":"yathā'gni bhakṣayedetannaro hitamitāśanaḥ nāsya kaścidbhavedvyādhirna jarā palitaṃ na ca"},{"type":"verse","number":"756","sanskrit":"न ज्वरा विषमा नैव मोहो नानिलरक्तकम् न च नेत्रगता रोगाः परमेतद्र्रसायनम्","text":"na jvarā viṣamā naiva moho nānilaraktakam na ca netragatā rogāḥ parametadrrasāyanam"},{"type":"verse","number":"757","sanskrit":"मेधाकरं त्रिदोषघ्नं प्रयोगादस्य बुद्धिमान् जीवेद्वर्षशतं साग्रं यथैवादितिजस्तथा","text":"medhākaraṃ tridoṣaghnaṃ prayogādasya buddhimān jīvedvarṣaśataṃ sāgraṃ yathaivāditijastathā"},{"type":"verse","number":"758","sanskrit":"तक्रमांसं पयोमांसं दधिमांसमथापि वा माषमांसञ्च भुञ्जानो मुच्यते विषमज्वरात्","text":"takramāṃsaṃ payomāṃsaṃ dadhimāṃsamathāpi vā māṣamāṃsañca bhuñjāno mucyate viṣamajvarāt"},{"type":"verse","number":"759","sanskrit":"अग्निवेशेनोक्तम् सुरा समण्डा पानार्थे भोजने चरणायुधाः तित्तिरा विष्किराः पथ्याः कुक्कुटा विषमज्वरे","text":"agniveśenoktam surā samaṇḍā pānārthe bhojane caraṇāyudhāḥ tittirā viṣkirāḥ pathyāḥ kukkuṭā viṣamajvare"},{"type":"verse","number":"760","sanskrit":"त्रायन्तीकटुकाऽनन्तासारिवाभिः शृतं जलम् पटोलाब्दवृषातिक्तासारिवाभिः शृतं जलम् सन्तताख्ये ज्वरे देयं वातादीनां निवृत्तये","text":"trāyantīkaṭukā'nantāsārivābhiḥ śṛtaṃ jalam paṭolābdavṛṣātiktāsārivābhiḥ śṛtaṃ jalam santatākhye jvare deyaṃ vātādīnāṃ nivṛttaye"},{"type":"verse","number":"761","sanskrit":"पटोलेन्द्र यवानन्तापथ्याऽरिष्टामृताजलम् क्वथितं तज्जलं पीतं ज्वरं सततकं जयेत्","text":"paṭolendra yavānantāpathyā'riṣṭāmṛtājalam kvathitaṃ tajjalaṃ pītaṃ jvaraṃ satatakaṃ jayet"},{"type":"verse","number":"762","sanskrit":"द्रा क्षापटोलनिम्बाब्दशक्राह्वत्रिफलाशृतम् जलं जन्तुः पिबेच्छीघ्रमन्येद्युर्ज्वरशान्तये","text":"drā kṣāpaṭolanimbābdaśakrāhvatriphalāśṛtam jalaṃ jantuḥ pibecchīghramanyedyurjvaraśāntaye"},{"type":"verse","number":"763","sanskrit":"कर्म साधारणं जह्यात् तृतीयकचतुर्थकौ भिषजा प्रतिकर्त्तव्यौ विशेषोक्तचिकित्सितैः","text":"karma sādhāraṇaṃ jahyāt tṛtīyakacaturthakau bhiṣajā pratikarttavyau viśeṣoktacikitsitaiḥ"},{"type":"verse","number":"764","sanskrit":"उशीरं चन्दनं मुस्तं गुडूची धान्यनागरम् अम्भसा क्वथितं पेयं शर्करामधुयोजितम्","text":"uśīraṃ candanaṃ mustaṃ guḍūcī dhānyanāgaram ambhasā kvathitaṃ peyaṃ śarkarāmadhuyojitam"},{"type":"verse","number":"765","sanskrit":"ज्वरे तृतीयके पुंसां तृष्णादाहसमन्विते","text":"jvare tṛtīyake puṃsāṃ tṛṣṇādāhasamanvite"},{"type":"verse","number":"766","sanskrit":"अपामार्गजटां कट्यां लोहितैः सप्ततन्तुभिः बद्ध्वा वारे रवेस्तूर्णं ज्वरं हन्ति तृतीयकम्","text":"apāmārgajaṭāṃ kaṭyāṃ lohitaiḥ saptatantubhiḥ baddhvā vāre ravestūrṇaṃ jvaraṃ hanti tṛtīyakam"},{"type":"verse","number":"767","sanskrit":"स्थिरातामलकीदारु शिवावृषमहौषधैः सितामधुयुतः क्वाथश्चतुर्थकहरः परः","text":"sthirātāmalakīdāru śivāvṛṣamahauṣadhaiḥ sitāmadhuyutaḥ kvāthaścaturthakaharaḥ paraḥ"},{"type":"verse","number":"768","sanskrit":"अगस्तिपत्रस्य रसेन नस्यं निहन्ति चातुर्थकमुग्रवीर्यम् शिरीषपुष्पस्य निशाद्वयस्य कल्केन वा तद् घृतसंयुतेन","text":"agastipatrasya rasena nasyaṃ nihanti cāturthakamugravīryam śirīṣapuṣpasya niśādvayasya kalkena vā tad ghṛtasaṃyutena"},{"type":"verse","number":"769","sanskrit":"ज्वरस्य वेगकालञ्च चिन्तयञ्ज्वर्यते तु यः तस्येष्टैरद्भुतैर्वाऽपि विषमैर्नाशयेत्स्मृतम्","text":"jvarasya vegakālañca cintayañjvaryate tu yaḥ tasyeṣṭairadbhutairvā'pi viṣamairnāśayetsmṛtam"},{"type":"verse","number":"770","sanskrit":"सन्ततं विषमं चापि सततं सुचिरोत्थितम् ज्वरं सुभोजनैः पथ्यैरिष्टैश्च समुपाचरेत्","text":"santataṃ viṣamaṃ cāpi satataṃ sucirotthitam jvaraṃ subhojanaiḥ pathyairiṣṭaiśca samupācaret"},{"type":"verse","number":"771","sanskrit":"शीताभिभूते पुरुषे कुर्य्याच्छीतहरीं क्रियाम् दाहाभिभूते तु विधिं विदध्याद्दाहनाशनम्","text":"śītābhibhūte puruṣe kuryyācchītaharīṃ kriyām dāhābhibhūte tu vidhiṃ vidadhyāddāhanāśanam"},{"type":"verse","number":"772","sanskrit":"आच्छादनैर्बहुतरैर्गुरुभिः कम्बलादिभिः तूलवत्या महाशीतं शीतादिज्वरिणो हरेत्","text":"ācchādanairbahutarairgurubhiḥ kambalādibhiḥ tūlavatyā mahāśītaṃ śītādijvariṇo haret"},{"type":"verse","number":"773","sanskrit":"तं स्तनाभ्यां सुपीनाभ्यां पीवरोरुर्नितम्बिनी युवतिर्गाढमालिङ्गेत् तेन शीतं प्रशाम्यति","text":"taṃ stanābhyāṃ supīnābhyāṃ pīvarorurnitambinī yuvatirgāḍhamāliṅget tena śītaṃ praśāmyati"},{"type":"verse","number":"774","sanskrit":"कान्ताऽङ्गसङ्गसञ्जाते तद्वच्छीते निवारिते प्रह्लादं चास्य विज्ञाय पृथक् तां कारयेत्स्त्रियम्","text":"kāntā'ṅgasaṅgasañjāte tadvacchīte nivārite prahlādaṃ cāsya vijñāya pṛthak tāṃ kārayetstriyam"},{"type":"verse","number":"775","sanskrit":"ततो दाहे तु सञ्जाते पत्रैरेरण्डसम्भवैः शीतलैर्धारितैरङ्गे दाहं तस्यापनोदयेत्","text":"tato dāhe tu sañjāte patraireraṇḍasambhavaiḥ śītalairdhāritairaṅge dāhaṃ tasyāpanodayet"},{"type":"verse","number":"776","sanskrit":"तालकं शुक्तिकाचूर्णे दत्तं तत्रोभयोरपि नवमांशञ्च तुत्थं स्यान्मर्दयेत्कन्यकाद्र वैः","text":"tālakaṃ śuktikācūrṇe dattaṃ tatrobhayorapi navamāṃśañca tutthaṃ syānmardayetkanyakādra vaiḥ"},{"type":"verse","number":"777","sanskrit":"तत्तु संशुष्कमुपलैर्वन्यैर्गजपुटे पचेत् शीतं तच्चूर्णयेच्चूर्णं गुञ्जामात्रं सितायुतम्","text":"tattu saṃśuṣkamupalairvanyairgajapuṭe pacet śītaṃ taccūrṇayeccūrṇaṃ guñjāmātraṃ sitāyutam"},{"type":"verse","number":"778","sanskrit":"प्रभाते भक्षयेत्तेन याति शीतज्वरः क्षयम् वान्तिर्भवति कस्यापि कस्यचिन्न भवत्यपि","text":"prabhāte bhakṣayettena yāti śītajvaraḥ kṣayam vāntirbhavati kasyāpi kasyacinna bhavatyapi"},{"type":"verse","number":"779","sanskrit":"एकेन दिवसेनैव शीतज्वरहरं परम् मध्याह्नसमये पथ्यं शिखरिण्योदनं तथा","text":"ekena divasenaiva śītajvaraharaṃ param madhyāhnasamaye pathyaṃ śikhariṇyodanaṃ tathā"},{"type":"verse","number":"780","sanskrit":"कायस्थानाकुलीतिक्तावयः स्थापुरचोरकैः सहदेवावचाकुष्ठैः शीतघ्नैर्धूपलेपनैः","text":"kāyasthānākulītiktāvayaḥ sthāpuracorakaiḥ sahadevāvacākuṣṭhaiḥ śītaghnairdhūpalepanaiḥ"},{"type":"verse","number":"781","sanskrit":"साम्लैर्विपाचितं तैलमभ्यङ्गाच्छीतनाशनम्","text":"sāmlairvipācitaṃ tailamabhyaṅgācchītanāśanam"},{"type":"verse","number":"782","sanskrit":"एरण्डस्य तु पत्राणि लिप्तभूमौ निधापयेत् दाहादिज्वरिणो देहे तानि पत्राणि धारयेत्","text":"eraṇḍasya tu patrāṇi liptabhūmau nidhāpayet dāhādijvariṇo dehe tāni patrāṇi dhārayet"},{"type":"verse","number":"783","sanskrit":"तेन नश्यति दाहोऽस्य ज्वरश्चैवोपशाम्यति दाहे शान्ते यदा शैत्यं तच्च युक्त्यानिवारयेत्","text":"tena naśyati dāho'sya jvaraścaivopaśāmyati dāhe śānte yadā śaityaṃ tacca yuktyānivārayet"},{"type":"verse","number":"784","sanskrit":"जघनचक्रचलन्मणिमेखला सरसचन्दनचन्द्र विलेपना वनलतेव तनुं परिवेष्टयेत् प्रबलदाहनिपीडितमङ्गना","text":"jaghanacakracalanmaṇimekhalā sarasacandanacandra vilepanā vanalateva tanuṃ pariveṣṭayet prabaladāhanipīḍitamaṅganā"},{"type":"verse","number":"785","sanskrit":"तदङ्गसङ्गसञ्जाते शैत्ये दाहे निवारिते प्रह्लादञ्चास्य विज्ञाय तां स्त्रीमपनयेत्पुनः","text":"tadaṅgasaṅgasañjāte śaitye dāhe nivārite prahlādañcāsya vijñāya tāṃ strīmapanayetpunaḥ"},{"type":"verse","number":"786","sanskrit":"सुवर्चिकानागरकुष्ठमूर्वालाक्षानिशालोहितयष्टिकाभिः सिद्धं हरेत्षड्गुणतक्रपक्वं तैलं ज्वरं दाहसमन्वितं च","text":"suvarcikānāgarakuṣṭhamūrvālākṣāniśālohitayaṣṭikābhiḥ siddhaṃ haretṣaḍguṇatakrapakvaṃ tailaṃ jvaraṃ dāhasamanvitaṃ ca"},{"type":"verse","number":"787","sanskrit":"रास्नानागरकुष्ठचन्दननिशायष्ट्याह्वकृष्णाबला लाक्षासैन्धवसारिवामधुरसादेवाह्वरोहीतकैः सोशीराम्बुधिफेनरोहिषजलैस्तैलंपचेत्षड्गुणे तक्रे तच्च जयेज्ज्वरं दृढतरं दाहादिशीतादिकम्","text":"rāsnānāgarakuṣṭhacandananiśāyaṣṭyāhvakṛṣṇābalā lākṣāsaindhavasārivāmadhurasādevāhvarohītakaiḥ sośīrāmbudhiphenarohiṣajalaistailaṃpacetṣaḍguṇe takre tacca jayejjvaraṃ dṛḍhataraṃ dāhādiśītādikam"},{"type":"verse","number":"788","sanskrit":"पद्मकोत्पलकह्लार मृणालबिसपौष्करैः कुमुदोशीरमञ्जिष्ठा पद्मगैरिककट्फलैः","text":"padmakotpalakahlāra mṛṇālabisapauṣkaraiḥ kumudośīramañjiṣṭhā padmagairikakaṭphalaiḥ"},{"type":"verse","number":"789","sanskrit":"सारिवाद्वयलोध्रा ह्वक्षीरीखर्जूरमस्तकैः धात्रीशतावरीयुक्तैः क्वाथे कल्के प्रयोजितैः","text":"sārivādvayalodhrā hvakṣīrīkharjūramastakaiḥ dhātrīśatāvarīyuktaiḥ kvāthe kalke prayojitaiḥ"},{"type":"verse","number":"790","sanskrit":"लाक्षारसपयःशुक्त मस्तुभिः सह काञ्जिकैः पक्वं तैलमिदं त्वच्यं दाहज्वरहरं परम्","text":"lākṣārasapayaḥśukta mastubhiḥ saha kāñjikaiḥ pakvaṃ tailamidaṃ tvacyaṃ dāhajvaraharaṃ param"},{"type":"verse","number":"791","sanskrit":"प्रलेपके प्रयुञ्जीत श्लेष्मज्वरहरीं क्रियाम्","text":"pralepake prayuñjīta śleṣmajvaraharīṃ kriyām"},{"type":"verse","number":"792","sanskrit":"रूद्र जटा गोशृङ्गं विडालविष्ठोरगस्य निर्मोकः मदनफलभूतकेश्यौ वंशत्वग्रुद्र निर्माल्यम्","text":"rūdra jaṭā gośṛṅgaṃ viḍālaviṣṭhoragasya nirmokaḥ madanaphalabhūtakeśyau vaṃśatvagrudra nirmālyam"},{"type":"verse","number":"793","sanskrit":"घृतयवमयूरपुच्छच्छगलकलोमानि सर्षपाःसवचाः हिङ्गुगवास्थिमरीचाः समभागाश्छागमूत्रसंपिष्टाः","text":"ghṛtayavamayūrapucchacchagalakalomāni sarṣapāḥsavacāḥ hiṅgugavāsthimarīcāḥ samabhāgāśchāgamūtrasaṃpiṣṭāḥ"},{"type":"verse","number":"794","sanskrit":"धूपनविधिना शमयन्त्येते सर्वाञ्ज्वरान्नियतम् ग्रहडाकिनीपिशाचप्रेतविकारानयं धूपः","text":"dhūpanavidhinā śamayantyete sarvāñjvarānniyatam grahaḍākinīpiśācapretavikārānayaṃ dhūpaḥ"},{"type":"verse","number":"795","sanskrit":"सोमं सानुचरं देवं समातृगणमीश्वरम् पूजयन्प्रयतः शीघ्रं मुच्यते विषमज्वरात्","text":"somaṃ sānucaraṃ devaṃ samātṛgaṇamīśvaram pūjayanprayataḥ śīghraṃ mucyate viṣamajvarāt"},{"type":"verse","number":"796","sanskrit":"विष्णुं सहस्त्रमूर्द्धानं चराचरपतिं विभुम् स्तुवन्नामसहस्त्रेण ज्वरान्सर्वान्व्यपोहति","text":"viṣṇuṃ sahastramūrddhānaṃ carācarapatiṃ vibhum stuvannāmasahastreṇa jvarānsarvānvyapohati"},{"type":"verse","number":"797","sanskrit":"तीर्थायतनदेवाग्निगुरुवृद्धोपसर्पणैः श्रद्धया पूजनैश्चापि सहसा शाम्यति ज्वरः","text":"tīrthāyatanadevāgniguruvṛddhopasarpaṇaiḥ śraddhayā pūjanaiścāpi sahasā śāmyati jvaraḥ"},{"type":"verse","number":"798","sanskrit":"इति विषमज्वराधिकारः समाप्तः गुरुता हृदयोत्क्लेशः सदनं छर्द्यरोचकौ रसस्थे तु ज्वरे लिङ्गं दैन्यं चास्योपजायते","text":"iti viṣamajvarādhikāraḥ samāptaḥ gurutā hṛdayotkleśaḥ sadanaṃ chardyarocakau rasasthe tu jvare liṅgaṃ dainyaṃ cāsyopajāyate"},{"type":"verse","number":"799","sanskrit":"रसस्थे तु ज्वरे तस्मिन् कुर्याद्वमनलङ्घने","text":"rasasthe tu jvare tasmin kuryādvamanalaṅghane"},{"type":"verse","number":"800","sanskrit":"रक्तनिष्ठीवनं दाहो मोहश्छर्दनविभ्रमौ प्रलापः पिडिका तृष्णा रक्तप्राप्ते ज्वरे नृणाम्","text":"raktaniṣṭhīvanaṃ dāho mohaśchardanavibhramau pralāpaḥ piḍikā tṛṣṇā raktaprāpte jvare nṛṇām"},{"type":"verse","number":"801","sanskrit":"सेकः संशमनो लेपो रक्तमोक्षमसृग्गते","text":"sekaḥ saṃśamano lepo raktamokṣamasṛggate"},{"type":"verse","number":"802","sanskrit":"पिण्डकोद्वेष्टनं तृष्णा सृष्टमूत्रपुरीषता ऊष्माऽन्तर्दाहविक्षेपौ ग्लानिः स्यान्मांसगे ज्वरे","text":"piṇḍakodveṣṭanaṃ tṛṣṇā sṛṣṭamūtrapurīṣatā ūṣmā'ntardāhavikṣepau glāniḥ syānmāṃsage jvare"},{"type":"verse","number":"803","sanskrit":"तीक्ष्णं विरेकञ्च तथा कुर्यान्मांसगते ज्वरे","text":"tīkṣṇaṃ virekañca tathā kuryānmāṃsagate jvare"},{"type":"verse","number":"804","sanskrit":"भृशं स्वेदस्तृषा मूर्च्छा प्रलापश्छर्दिरेव च दौर्गन्ध्यारोचकौ ग्लानिर्मेदःस्थे चासहिष्णुता","text":"bhṛśaṃ svedastṛṣā mūrcchā pralāpaśchardireva ca daurgandhyārocakau glānirmedaḥsthe cāsahiṣṇutā"},{"type":"verse","number":"805","sanskrit":"मेदःस्थे मेदसो नाशं विदधीत चिकित्सकः","text":"medaḥsthe medaso nāśaṃ vidadhīta cikitsakaḥ"},{"type":"verse","number":"806","sanskrit":"भेदोऽस्थ्ना कूजनं श्वासो विरेकश्छर्दिरेव च विक्षेपणञ्च गात्राणां विद्यादस्थिगते ज्वरे","text":"bhedo'sthnā kūjanaṃ śvāso virekaśchardireva ca vikṣepaṇañca gātrāṇāṃ vidyādasthigate jvare"},{"type":"verse","number":"807","sanskrit":"अस्थिस्थे तु ज्वरे कुर्याद् वातनाशनकं विधिम् वस्तिकर्म प्रयोक्तव्यमभ्यङ्गोन्मर्दनं तथा","text":"asthisthe tu jvare kuryād vātanāśanakaṃ vidhim vastikarma prayoktavyamabhyaṅgonmardanaṃ tathā"},{"type":"verse","number":"808","sanskrit":"तमःप्रवेशनं हिक्का कासः शैत्यं वमिस्तथा अन्तर्दाहो महाश्वासो मर्मच्छेदश्च मज्जगे","text":"tamaḥpraveśanaṃ hikkā kāsaḥ śaityaṃ vamistathā antardāho mahāśvāso marmacchedaśca majjage"},{"type":"verse","number":"809","sanskrit":"मरणं प्राप्नुयात्तत्र शुक्रस्थानगते ज्वरे शेफसः स्तब्धता मोक्षः शुक्रस्य तु विशेषतः","text":"maraṇaṃ prāpnuyāttatra śukrasthānagate jvare śephasaḥ stabdhatā mokṣaḥ śukrasya tu viśeṣataḥ"},{"type":"verse","number":"810","sanskrit":"इति सप्तधातुगतज्वराधिकार समाप्तः अथ जीर्णज्वराधिकारः यो द्वादशेभ्यो दिवसेभ्य ऊर्द्ध्वं दोषत्रयेभ्यो द्विगुणेभ्य ऊर्द्ध्वम् नृणां तनौ तिष्ठति मन्दवेगो भिषग्भिरुक्तो ज्वर एष जीर्णः","text":"iti saptadhātugatajvarādhikāra samāptaḥ atha jīrṇajvarādhikāraḥ yo dvādaśebhyo divasebhya ūrddhvaṃ doṣatrayebhyo dviguṇebhya ūrddhvam nṛṇāṃ tanau tiṣṭhati mandavego bhiṣagbhirukto jvara eṣa jīrṇaḥ"},{"type":"verse","number":"811","sanskrit":"नित्यं मन्दज्वरो रूक्षः शूनः कृच्छ्रेणसिद्ध्य्ति स्तब्धाङ्गःश्लेष्मभूयिष्ठो नरो वातबलासकी","text":"nityaṃ mandajvaro rūkṣaḥ śūnaḥ kṛcchreṇasiddhyti stabdhāṅgaḥśleṣmabhūyiṣṭho naro vātabalāsakī"},{"type":"verse","number":"812","sanskrit":"जीर्णज्वरी नरः कुर्यान्नोपवासं कदाचन लङ्घनात्स भवेत्क्षीणो ज्वरस्तु स्याद्बली यतः पुराणेऽपि ज्वरे दोषा यद्यपथ्यैः पुनस्तथा लङ्घयेत्तत्र तत्पश्चात् पूर्वामेवाचरेत्क्रियाम्","text":"jīrṇajvarī naraḥ kuryānnopavāsaṃ kadācana laṅghanātsa bhavetkṣīṇo jvarastu syādbalī yataḥ purāṇe'pi jvare doṣā yadyapathyaiḥ punastathā laṅghayettatra tatpaścāt pūrvāmevācaretkriyām"},{"type":"verse","number":"813","sanskrit":"निदिग्धकानागरकामृतानां क्वाथं पिबेन्मिश्रितपिप्पलीकम् जीर्णज्वरारोचककासशूल श्वासाग्निमान्द्यार्दितपीनसेषु","text":"nidigdhakānāgarakāmṛtānāṃ kvāthaṃ pibenmiśritapippalīkam jīrṇajvarārocakakāsaśūla śvāsāgnimāndyārditapīnaseṣu"},{"type":"verse","number":"814","sanskrit":"हन्त्यूर्द्ध्वजामयं प्रायः सायन्तेनोपयुज्यते","text":"hantyūrddhvajāmayaṃ prāyaḥ sāyantenopayujyate"},{"type":"verse","number":"815","sanskrit":"पिप्पलीमधुसंयुक्तः क्वाथश्छिन्नोद्भवोद्भवः जीर्णज्वरकफध्वंसी पञ्चमूलकृतोऽथ वा अमृतायाः कषायन्तु शीतलीकृतमीरितम् मधुपादयुतं पीतं जीर्णज्वरहरं परम् पिप्पलीमधुसम्मिश्रं गुडूचीस्वरसं पिबेत् जीर्णज्वरकफप्लीह कासारोचकनाशनम्","text":"pippalīmadhusaṃyuktaḥ kvāthaśchinnodbhavodbhavaḥ jīrṇajvarakaphadhvaṃsī pañcamūlakṛto'tha vā amṛtāyāḥ kaṣāyantu śītalīkṛtamīritam madhupādayutaṃ pītaṃ jīrṇajvaraharaṃ param pippalīmadhusammiśraṃ guḍūcīsvarasaṃ pibet jīrṇajvarakaphaplīha kāsārocakanāśanam"},{"type":"verse","number":"816","sanskrit":"जीर्णज्वरेऽग्निमान्द्ये च शस्यते गुडपिप्पली कासाजीर्णारुचिश्वासहृत्पाण्डु कृमिरोगनुत् द्विगुणः पिप्पलीचूर्णाद् गुडोऽत्र भिषजां मतः","text":"jīrṇajvare'gnimāndye ca śasyate guḍapippalī kāsājīrṇāruciśvāsahṛtpāṇḍu kṛmiroganut dviguṇaḥ pippalīcūrṇād guḍo'tra bhiṣajāṃ mataḥ"},{"type":"verse","number":"817","sanskrit":"पिप्पली मधुसंयुक्ता मेदः कफविनाशिनी श्वासकासज्वरहरी पाण्डुप्लीहोदरापहा","text":"pippalī madhusaṃyuktā medaḥ kaphavināśinī śvāsakāsajvaraharī pāṇḍuplīhodarāpahā"},{"type":"verse","number":"818","sanskrit":"आमलं चित्रकं पथ्या पिप्पली सैन्धवं तथा","text":"āmalaṃ citrakaṃ pathyā pippalī saindhavaṃ tathā"},{"type":"verse","number":"819","sanskrit":"चूर्णितोऽय गणो ज्ञेयः सर्वज्वरहरः परः भेदी रुचिकरः श्लेष्महन्ता दीपनपाचनः","text":"cūrṇito'ya gaṇo jñeyaḥ sarvajvaraharaḥ paraḥ bhedī rucikaraḥ śleṣmahantā dīpanapācanaḥ"},{"type":"verse","number":"820","sanskrit":"द्रा क्षाऽमृता शटी शृङ्गी मुस्तकं रक्तचन्दनम् नागरं कटुका पाठा भूनिम्बः सदुरालभः","text":"drā kṣā'mṛtā śaṭī śṛṅgī mustakaṃ raktacandanam nāgaraṃ kaṭukā pāṭhā bhūnimbaḥ sadurālabhaḥ"},{"type":"verse","number":"821","sanskrit":"उशीरं धान्यकं पद्मं बालकं कण्टकारिका पुष्करं पिचुमन्दश्च दशाष्टाङ्गमिदं स्मृतम् जीर्णज्वरारुचिश्वास कासश्वयथुनाशनम्","text":"uśīraṃ dhānyakaṃ padmaṃ bālakaṃ kaṇṭakārikā puṣkaraṃ picumandaśca daśāṣṭāṅgamidaṃ smṛtam jīrṇajvarāruciśvāsa kāsaśvayathunāśanam"},{"type":"verse","number":"822","sanskrit":"त्रिवृद्ध्या पञ्चवृद्ध्या वा सप्तवृद्ध्याऽथवाऽपि वा गव्यक्षीरेण सम्पिष्टाः पिबेद्दशदिनानि हि","text":"trivṛddhyā pañcavṛddhyā vā saptavṛddhyā'thavā'pi vā gavyakṣīreṇa sampiṣṭāḥ pibeddaśadināni hi"},{"type":"verse","number":"823","sanskrit":"तथैवापनयेदेता एवं विंशतिवासरान् पिबतां ज्वरशान्तिः स्यात् पाण्डुरोगश्च शाम्यति","text":"tathaivāpanayedetā evaṃ viṃśativāsarān pibatāṃ jvaraśāntiḥ syāt pāṇḍurogaśca śāmyati"},{"type":"verse","number":"824","sanskrit":"कासः श्वासोऽग्निमान्द्यञ्च कफाधिक्यञ्च नश्यति","text":"kāsaḥ śvāso'gnimāndyañca kaphādhikyañca naśyati"},{"type":"verse","number":"825","sanskrit":"वातश्लेष्मज्वरोक्ता स्यात् क्रियावातबलासके जीर्णज्वरे कफे क्षीणे दाहे तृष्णासमन्विते","text":"vātaśleṣmajvaroktā syāt kriyāvātabalāsake jīrṇajvare kaphe kṣīṇe dāhe tṛṣṇāsamanvite"},{"type":"verse","number":"826","sanskrit":"पयः पीयूषसदृशं तन्नवे तु विषोपमम् चन्दनाद्यं हितं तैलं शोषाधिकारकीर्त्तितम् तथा नारायणं तैलं जीर्णज्वरहरं परम्","text":"payaḥ pīyūṣasadṛśaṃ tannave tu viṣopamam candanādyaṃ hitaṃ tailaṃ śoṣādhikārakīrttitam tathā nārāyaṇaṃ tailaṃ jīrṇajvaraharaṃ param"},{"type":"verse","number":"827","sanskrit":"इति जीर्णज्वराधिकारः समाप्तः हरीतकी निम्बपत्रं नागरं सैन्धवोऽनलः एषां चूर्णं सदा खादेद् दुर्जलज्वरशान्तये","text":"iti jīrṇajvarādhikāraḥ samāptaḥ harītakī nimbapatraṃ nāgaraṃ saindhavo'nalaḥ eṣāṃ cūrṇaṃ sadā khāded durjalajvaraśāntaye"},{"type":"verse","number":"828","sanskrit":"अरुचिमनलमान्द्यं पीनसश्वासकासानुदरमुदकदोषानाशु हन्यादशेषान् जनयति तनुकान्तिं चित्तनेत्रप्रसादं पलपरिमितशुण्ठीक्षौद्र सिद्धः कषायः","text":"arucimanalamāndyaṃ pīnasaśvāsakāsānudaramudakadoṣānāśu hanyādaśeṣān janayati tanukāntiṃ cittanetraprasādaṃ palaparimitaśuṇṭhīkṣaudra siddhaḥ kaṣāyaḥ"},{"type":"verse","number":"829","sanskrit":"विषं भागद्वयं दग्धं कपर्दं पञ्चभागकम् मरिचं नागरञ्चैव चूर्णं वस्त्रेण शोधयेत्","text":"viṣaṃ bhāgadvayaṃ dagdhaṃ kapardaṃ pañcabhāgakam maricaṃ nāgarañcaiva cūrṇaṃ vastreṇa śodhayet"},{"type":"verse","number":"830","sanskrit":"आर्द्र कस्य रसेनास्य कुर्यान्मुद्गनिभां वटीम् वारिणा वटिकायुग्मं प्रातः सायञ्च भक्षयेत्","text":"ārdra kasya rasenāsya kuryānmudganibhāṃ vaṭīm vāriṇā vaṭikāyugmaṃ prātaḥ sāyañca bhakṣayet"},{"type":"verse","number":"831","sanskrit":"अयं रसो ज्वरे योज्यः सामे दुर्जलजेऽपि च अजीर्णाध्मानविष्टम्भ शूलेषु श्वासकासयोः","text":"ayaṃ raso jvare yojyaḥ sāme durjalaje'pi ca ajīrṇādhmānaviṣṭambha śūleṣu śvāsakāsayoḥ"},{"type":"verse","number":"832","sanskrit":"पटोलमुस्ताऽमृतवल्लिवासकं सनागरं धान्यकिराततिक्तकम् कषायमेषां मधुना पिबेन्नरो निवारयेद् दुर्जलदोषमुल्बणम्","text":"paṭolamustā'mṛtavallivāsakaṃ sanāgaraṃ dhānyakirātatiktakam kaṣāyameṣāṃ madhunā pibennaro nivārayed durjaladoṣamulbaṇam"},{"type":"verse","number":"833","sanskrit":"किराततिक्तात्रिबृदम्बुपिप्पली विडङ्गविश्वाकटुरोहिणीरजः निहन्ति लीढं मधुनाऽतिसत्वरं सुदुस्तरं दुर्जलदोषजं ज्वरम्","text":"kirātatiktātribṛdambupippalī viḍaṅgaviśvākaṭurohiṇīrajaḥ nihanti līḍhaṃ madhunā'tisatvaraṃ sudustaraṃ durjaladoṣajaṃ jvaram"},{"type":"verse","number":"834","sanskrit":"भोजनाग्रे नरैर्भुक्तं शुण्ठ्यजाज्यभयोत्थितम् कल्कन्तु सेवितं नित्यं नानादेशोद्भवं जलम्","text":"bhojanāgre narairbhuktaṃ śuṇṭhyajājyabhayotthitam kalkantu sevitaṃ nityaṃ nānādeśodbhavaṃ jalam"},{"type":"verse","number":"835","sanskrit":"सहार्द्र कयवक्षारौ पीत्वा कोष्णेन वारिणा नानादेशसमुद्भूतं वारिदोषमपोहति","text":"sahārdra kayavakṣārau pītvā koṣṇena vāriṇā nānādeśasamudbhūtaṃ vāridoṣamapohati"},{"type":"verse","number":"836","sanskrit":"बलवत्स्वल्पदोषेषु ज्वरः साध्योऽनुपद्र वः","text":"balavatsvalpadoṣeṣu jvaraḥ sādhyo'nupadra vaḥ"},{"type":"verse","number":"837","sanskrit":"श्वासो मूर्च्छाऽरुचिश्छर्दिस्तृष्णाऽतीसारविड्ग्रहाः हिक्काकासाङ्गदाहाश्च ज्वरस्योपद्र वा दश","text":"śvāso mūrcchā'ruciśchardistṛṣṇā'tīsāraviḍgrahāḥ hikkākāsāṅgadāhāśca jvarasyopadra vā daśa"},{"type":"verse","number":"838","sanskrit":"सञ्जातोपद्र वो व्याधिस्त्याज्यो न स्याच्चिकित्सकैः व्याधौ शान्ते प्रणश्यन्ति सद्यःसर्वेऽप्युपद्र वाः","text":"sañjātopadra vo vyādhistyājyo na syāccikitsakaiḥ vyādhau śānte praṇaśyanti sadyaḥsarve'pyupadra vāḥ"},{"type":"verse","number":"839","sanskrit":"अतो व्याधिं जयेद्यत्नात् पूर्वं पश्चादुपद्र वान् भिषग् यःकुशलः सोऽत्र जयेत्पूर्वमुपद्र वम्","text":"ato vyādhiṃ jayedyatnāt pūrvaṃ paścādupadra vān bhiṣag yaḥkuśalaḥ so'tra jayetpūrvamupadra vam"},{"type":"verse","number":"840","sanskrit":"तेष्वपि प्रचुरेषु प्राङ् नाशयेदाशुकारिणाम् मूलव्याधिं जयेत्पूर्वं यत्र यो वा भवेद्बली अविरोधेन कार्या तदुभयोरपि च क्रिया","text":"teṣvapi pracureṣu prāṅ nāśayedāśukāriṇām mūlavyādhiṃ jayetpūrvaṃ yatra yo vā bhavedbalī avirodhena kāryā tadubhayorapi ca kriyā"},{"type":"verse","number":"841","sanskrit":"सिंही व्याघ्री ताम्रमूली पटोली शृङ्गी पद्मा पुष्करं रोहिणी च शाकं शठ्याः शैलमल्ल्याश्च बीजं श्वासं हन्यात्सन्निपातं दशाङ्गः","text":"siṃhī vyāghrī tāmramūlī paṭolī śṛṅgī padmā puṣkaraṃ rohiṇī ca śākaṃ śaṭhyāḥ śailamallyāśca bījaṃ śvāsaṃ hanyātsannipātaṃ daśāṅgaḥ"},{"type":"verse","number":"842","sanskrit":"भार्गीनिम्बघनाभयाऽमृतलताभूनिम्बवासाविषात्रातयन्ती कटुकावचात्रिकटुकश्योनाकशक्रद्रुमैः","text":"bhārgīnimbaghanābhayā'mṛtalatābhūnimbavāsāviṣātrātayantī kaṭukāvacātrikaṭukaśyonākaśakradrumaiḥ"},{"type":"verse","number":"843","sanskrit":"रास्नायासपटोलपाटलशटीदार्वीविशालत्रिवृद्ब्राह्मीपुष्करसिंहिकाद्वयनिशाधात्र्यक्षदेवद्रुमैः क्वाथोऽय खलु सन्निपातनिवहान्द्वात्रिंशतां पानतो दुर्द्धर्षान्निजतेजसा विजयते सर्पान्गरुत्मानिव किञ्च श्वासवलासकासगुदरुग्घृद्रो गहिक्कामरुन् मन्यास्तम्भगलामयार्दितमलावष्टम्भब्रध्नानपि","text":"rāsnāyāsapaṭolapāṭalaśaṭīdārvīviśālatrivṛdbrāhmīpuṣkarasiṃhikādvayaniśādhātryakṣadevadrumaiḥ kvātho'ya khalu sannipātanivahāndvātriṃśatāṃ pānato durddharṣānnijatejasā vijayate sarpāngarutmāniva kiñca śvāsavalāsakāsagudarugghṛdro gahikkāmarun manyāstambhagalāmayārditamalāvaṣṭambhabradhnānapi"},{"type":"verse","number":"844","sanskrit":"मधुना कृष्णाकट्फलकर्कटशृङ्गीभवं चूर्णम् श्वासामये महोग्रे लीढ्वा लोकः सुखी भवति","text":"madhunā kṛṣṇākaṭphalakarkaṭaśṛṅgībhavaṃ cūrṇam śvāsāmaye mahogre līḍhvā lokaḥ sukhī bhavati"},{"type":"verse","number":"845","sanskrit":"वन्योपलाग्नितापितदात्रस्याग्रेण पञ्जरे दाहः अपहरति श्वासामयमसंशयं भाषितं मुनिभिः","text":"vanyopalāgnitāpitadātrasyāgreṇa pañjare dāhaḥ apaharati śvāsāmayamasaṃśayaṃ bhāṣitaṃ munibhiḥ"},{"type":"verse","number":"846","sanskrit":"आर्द्र कस्य रसैर्नस्यं मूर्च्छायामाचरेन्नरः अञ्जनञ्च प्रयुञ्जीत मधुसिन्धुशिलोषणैः","text":"ārdra kasya rasairnasyaṃ mūrcchāyāmācarennaraḥ añjanañca prayuñjīta madhusindhuśiloṣaṇaiḥ"},{"type":"verse","number":"847","sanskrit":"शीताम्भसाऽक्षिसेकः सुरभिर्धूपः सुगन्धि पुष्पञ्च मृदुतालवृन्तवातः कोमलकदली दल स्पर्शः","text":"śītāmbhasā'kṣisekaḥ surabhirdhūpaḥ sugandhi puṣpañca mṛdutālavṛntavātaḥ komalakadalī dala sparśaḥ"},{"type":"verse","number":"848","sanskrit":"अरुचौ तु शृङ्गबेरजरसकैः सोष्णैः ससिन्धुजैः कवलः सिन्धूत्थमातुलुङ्गीफलकेसरधारणं वक्त्रे","text":"arucau tu śṛṅgaberajarasakaiḥ soṣṇaiḥ sasindhujaiḥ kavalaḥ sindhūtthamātuluṅgīphalakesaradhāraṇaṃ vaktre"},{"type":"verse","number":"849","sanskrit":"क्वाथो गुडूच्याः समधुः सुशीतः पीतः प्रशान्तिं वमनस्य कुर्यात् विण्मक्षिकाणां मधुनाऽवलीढा सचन्दना शर्करयाऽन्विता वा","text":"kvātho guḍūcyāḥ samadhuḥ suśītaḥ pītaḥ praśāntiṃ vamanasya kuryāt viṇmakṣikāṇāṃ madhunā'valīḍhā sacandanā śarkarayā'nvitā vā"},{"type":"verse","number":"850","sanskrit":"दन्तशठबीजपूरकदाडिमबदरैः सचुक्रकैर्वदने लेपो जयति पिपासामथ रजतगुटी मुखान्तःस्था","text":"dantaśaṭhabījapūrakadāḍimabadaraiḥ sacukrakairvadane lepo jayati pipāsāmatha rajataguṭī mukhāntaḥsthā"},{"type":"verse","number":"851","sanskrit":"शीतं पयः क्षौद्र युतं निपीतमाकण्ठमाश्वेव तदुद्वमेच्च तर्षं महान्तं शमयेद्धि वक्त्रे धृत्वाऽथवा क्षौद्र वटाग्रलाजान्","text":"śītaṃ payaḥ kṣaudra yutaṃ nipītamākaṇṭhamāśveva tadudvamecca tarṣaṃ mahāntaṃ śamayeddhi vaktre dhṛtvā'thavā kṣaudra vaṭāgralājān"},{"type":"verse","number":"852","sanskrit":"लङ्घनमेकं मुक्त्वा न चान्यदस्तीह भेषजं बलिनः समुदीर्णदोषनिचयं शमयति तत्पाचयेदपि च","text":"laṅghanamekaṃ muktvā na cānyadastīha bheṣajaṃ balinaḥ samudīrṇadoṣanicayaṃ śamayati tatpācayedapi ca"},{"type":"verse","number":"853","sanskrit":"वत्सादनीवत्सकवारिवाह विश्वम्भरानिम्बविषाः सविश्वाः ज्वरेऽतिसारं त्वरितं जयन्ति विश्वाऽमृतावत्सकवारिवाहाः","text":"vatsādanīvatsakavārivāha viśvambharānimbaviṣāḥ saviśvāḥ jvare'tisāraṃ tvaritaṃ jayanti viśvā'mṛtāvatsakavārivāhāḥ"},{"type":"verse","number":"854","sanskrit":"पाठाऽमृतापर्पटमुस्तविश्व किराततिक्तेन्द्र यवान्विपाच्य पिबन्हरत्येव हठेन सर्वाञ्ज्वरातिसारानपि दुर्निवारान्","text":"pāṭhā'mṛtāparpaṭamustaviśva kirātatiktendra yavānvipācya pibanharatyeva haṭhena sarvāñjvarātisārānapi durnivārān"},{"type":"verse","number":"855","sanskrit":"विड्ग्रहे वातजित्कर्म कुर्यादत्रानुलोमनम् मलं प्रवर्त्तयेदाशु तीक्ष्णाभिः फलवर्त्तिभिः","text":"viḍgrahe vātajitkarma kuryādatrānulomanam malaṃ pravarttayedāśu tīkṣṇābhiḥ phalavarttibhiḥ"},{"type":"verse","number":"856","sanskrit":"पथ्याऽरग्वधतिक्तात्रिवृदामलकैः शृतं तोयम् जीर्णज्वरे विबंधे दद्यादश्वेव विड्ग्रहः शाम्येत्","text":"pathyā'ragvadhatiktātrivṛdāmalakaiḥ śṛtaṃ toyam jīrṇajvare vibaṃdhe dadyādaśveva viḍgrahaḥ śāmyet"},{"type":"verse","number":"857","sanskrit":"नीरेण सिन्धूत्थरजोऽतिसूक्ष्मं नस्येन नूनं विनिहन्ति हिक्काम् शुण्ठी हठाद्वा सितया समेता धूपोऽथवा हिङ्गुसमुद्भवश्च","text":"nīreṇa sindhūttharajo'tisūkṣmaṃ nasyena nūnaṃ vinihanti hikkām śuṇṭhī haṭhādvā sitayā sametā dhūpo'thavā hiṅgusamudbhavaśca"},{"type":"verse","number":"858","sanskrit":"कासे कणा कणामूलं कलिङ्गद्रुफलं रजः सविश्वभेषजं लिह्यान्मधुना वा वृषाद्र सम्","text":"kāse kaṇā kaṇāmūlaṃ kaliṅgadruphalaṃ rajaḥ saviśvabheṣajaṃ lihyānmadhunā vā vṛṣādra sam"},{"type":"verse","number":"859","sanskrit":"पुष्करमूलकटुत्रिकशृङ्गी कट्फलयासककारविकाभिः मधुलुलिताभिरयं खलु लेहः कासरिपुः कफरोगहरश्च","text":"puṣkaramūlakaṭutrikaśṛṅgī kaṭphalayāsakakāravikābhiḥ madhululitābhirayaṃ khalu lehaḥ kāsaripuḥ kapharogaharaśca"},{"type":"verse","number":"860","sanskrit":"दाहाधिकारे लिखितं दाहे कुर्याच्चिकित्सितम् परं ज्वरे विरुद्धं यन्नोचितं तच्चिकित्सितम्","text":"dāhādhikāre likhitaṃ dāhe kuryāccikitsitam paraṃ jvare viruddhaṃ yannocitaṃ taccikitsitam"},{"type":"verse","number":"861","sanskrit":"सन्तापोऽभ्यधिको बाह्यस्तृष्णाऽदीनां च मार्दवम् बहिर्बेगस्य लिङ्गानि सुखसाध्यत्वमेव च","text":"santāpo'bhyadhiko bāhyastṛṣṇā'dīnāṃ ca mārdavam bahirbegasya liṅgāni sukhasādhyatvameva ca"},{"type":"verse","number":"862","sanskrit":"वर्षाशरद्वसन्तेषु वाताद्यैः प्राकृतः क्रमात् प्राकृतः सुखसाध्यस्तु ज्वरः सुरभिसम्भवः","text":"varṣāśaradvasanteṣu vātādyaiḥ prākṛtaḥ kramāt prākṛtaḥ sukhasādhyastu jvaraḥ surabhisambhavaḥ"},{"type":"verse","number":"863","sanskrit":"वैकृतोऽन्य स दुःसाध्यः प्राकृतश्चानिलोद्भवः","text":"vaikṛto'nya sa duḥsādhyaḥ prākṛtaścānilodbhavaḥ"},{"type":"verse","number":"864","sanskrit":"वर्षासु मारुतो दुष्टः पित्तश्लेष्मान्वितो ज्वरम् कुर्यात्पित्तञ्चशरदि तस्य चानुबलः कफः","text":"varṣāsu māruto duṣṭaḥ pittaśleṣmānvito jvaram kuryātpittañcaśaradi tasya cānubalaḥ kaphaḥ"},{"type":"verse","number":"865","sanskrit":"तत्प्रकृत्या विसर्गाच्च तत्र नानशनाद्भयम् कफो वसन्ते तमपि वातपित्तं भवेदनु","text":"tatprakṛtyā visargācca tatra nānaśanādbhayam kapho vasante tamapi vātapittaṃ bhavedanu"},{"type":"verse","number":"866","sanskrit":"अन्तर्दाहोऽधिका तृष्णा प्रलापः श्वसनं भ्रमः सन्ध्यस्थिशूलमस्वेदो दोषवर्चोविनिग्रहः अन्तर्वेगस्य लिङ्गानि कष्टसाध्यत्वमेव च","text":"antardāho'dhikā tṛṣṇā pralāpaḥ śvasanaṃ bhramaḥ sandhyasthiśūlamasvedo doṣavarcovinigrahaḥ antarvegasya liṅgāni kaṣṭasādhyatvameva ca"},{"type":"verse","number":"867","sanskrit":"ज्वरः क्षीणस्य शूनस्य गम्भीरो दीर्घरात्रिकः असाध्यो बलवान्यश्च केशसीमन्तकृज्ज्वरः","text":"jvaraḥ kṣīṇasya śūnasya gambhīro dīrgharātrikaḥ asādhyo balavānyaśca keśasīmantakṛjjvaraḥ"},{"type":"verse","number":"868","sanskrit":"गम्भीरस्तु ज्वरो ज्ञेयो ह्यन्तर्दाहेन तृष्णया आनद्धत्वेन चात्यर्थं कासश्वासोद्गमेन च","text":"gambhīrastu jvaro jñeyo hyantardāhena tṛṣṇayā ānaddhatvena cātyarthaṃ kāsaśvāsodgamena ca"},{"type":"verse","number":"869","sanskrit":"ज्वरस्य पूर्वं ज्वरमध्यतो वा ज्वरान्ततो वा श्रुतिमूलशोथः क्रमादसाध्यः खलु कृच्छ्रसाध्यः सुखेन साध्यो मुनिभिः प्रदिष्टः","text":"jvarasya pūrvaṃ jvaramadhyato vā jvarāntato vā śrutimūlaśothaḥ kramādasādhyaḥ khalu kṛcchrasādhyaḥ sukhena sādhyo munibhiḥ pradiṣṭaḥ"},{"type":"verse","number":"870","sanskrit":"रोगिणो मरणं यस्मादवश्यम्भावि लक्ष्यते तल्लक्षणमरिष्टं स्याद् रिष्टमप्यभिधीयते","text":"rogiṇo maraṇaṃ yasmādavaśyambhāvi lakṣyate tallakṣaṇamariṣṭaṃ syād riṣṭamapyabhidhīyate"},{"type":"verse","number":"871","sanskrit":"हेतुभिर्बहुभिर्जातो बलिभिर्बहुलक्षणः ज्वरः प्राणान्तकृद्यश्च शीघ्रमिन्द्रि यनाशनः","text":"hetubhirbahubhirjāto balibhirbahulakṣaṇaḥ jvaraḥ prāṇāntakṛdyaśca śīghramindri yanāśanaḥ"},{"type":"verse","number":"872","sanskrit":"विसंज्ञस्ताम्यते यस्तु शेते निपतितोऽपि वा शीतार्दितोऽन्तरुष्णश्च ज्वरेण म्रियते नरः","text":"visaṃjñastāmyate yastu śete nipatito'pi vā śītārdito'ntaruṣṇaśca jvareṇa mriyate naraḥ"},{"type":"verse","number":"873","sanskrit":"यो हृष्टरोमा रक्ताक्षो हृदि संघातशूलवान् वक्त्रेण चवोच्छ्वसिति तं ज्वरो हन्ति मानवम्","text":"yo hṛṣṭaromā raktākṣo hṛdi saṃghātaśūlavān vaktreṇa cavocchvasiti taṃ jvaro hanti mānavam"},{"type":"verse","number":"874","sanskrit":"हिक्काश्वासतृषायुक्तं मूढं विभ्रान्तलोचनम् सन्ततोच्छ्वासिनं क्षीणं नरं क्षपयति ज्वरः","text":"hikkāśvāsatṛṣāyuktaṃ mūḍhaṃ vibhrāntalocanam santatocchvāsinaṃ kṣīṇaṃ naraṃ kṣapayati jvaraḥ"},{"type":"verse","number":"875","sanskrit":"हतप्रभेन्द्रि यं क्षाममरोचकनिपीडितम् गम्भीरतीक्ष्णवेगार्त्तं ज्वरितं परिवर्जयेत्","text":"hataprabhendri yaṃ kṣāmamarocakanipīḍitam gambhīratīkṣṇavegārttaṃ jvaritaṃ parivarjayet"},{"type":"verse","number":"876","sanskrit":"मरणं प्राप्नुयात्तत्र शुक्रस्थानगते ज्वरे शेफसः स्तब्धता मोक्षः शुक्रस्य तु विशेषतः","text":"maraṇaṃ prāpnuyāttatra śukrasthānagate jvare śephasaḥ stabdhatā mokṣaḥ śukrasya tu viśeṣataḥ"},{"type":"verse","number":"877","sanskrit":"आरम्भाद्विषमो यस्य यस्य वा दीर्घरात्रिकः क्षीणस्य चातिरूक्षस्य गम्भीरो यस्य हन्ति तम्","text":"ārambhādviṣamo yasya yasya vā dīrgharātrikaḥ kṣīṇasya cātirūkṣasya gambhīro yasya hanti tam"},{"type":"verse","number":"878","sanskrit":"इति प्रथमो ज्वराधिकारः समाप्तः","text":"iti prathamo jvarādhikāraḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":2,"lang":"sa","content":[{"type":"heading","heading":"Атисара — лечение диареи"},{"type":"verse","number":"1","sanskrit":"गुर्वतिस्निग्धरूक्षोष्णद्र वस्थूलातिशीतलैः विरूद्धाध्यशनाजीणैर्विषमैश्चापि भोजनैः","text":"gurvatisnigdharūkṣoṣṇadra vasthūlātiśītalaiḥ virūddhādhyaśanājīṇairviṣamaiścāpi bhojanaiḥ"},{"type":"verse","number":"2","sanskrit":"स्नेहाद्यैरतियुक्तैश्च मिथ्यायुक्तैर्विषैर्भयैः शोकदुष्टाम्बुमद्यातिपानैः सात्म्यर्त्तुपर्ययैः","text":"snehādyairatiyuktaiśca mithyāyuktairviṣairbhayaiḥ śokaduṣṭāmbumadyātipānaiḥ sātmyarttuparyayaiḥ"},{"type":"verse","number":"3","sanskrit":"जलाभिरमणैर्वेगविघातैः कृमिदोषतः नृणां भवत्यतीसारो लक्षणं तस्य वक्ष्यते","text":"jalābhiramaṇairvegavighātaiḥ kṛmidoṣataḥ nṛṇāṃ bhavatyatīsāro lakṣaṇaṃ tasya vakṣyate"},{"type":"verse","number":"4","sanskrit":"हृन्नाभिपार्श्वोदरकुक्षितोदगात्रावसादा निलसन्निरोधाः विट्सङ्गआध्मानमथाविपाको भविष्यतस्तस्य पुरःसराणि","text":"hṛnnābhipārśvodarakukṣitodagātrāvasādā nilasannirodhāḥ viṭsaṅgaādhmānamathāvipāko bhaviṣyatastasya puraḥsarāṇi"},{"type":"verse","number":"5","sanskrit":"संशम्यापां धातुरग्निं प्रवृद्धो वर्चोमिश्रो वायुनाऽध प्रणुन्नः सरत्यतीवातिसारं तमाहुर्व्याधिं घोरं षड्विधं तं वदन्ति","text":"saṃśamyāpāṃ dhāturagniṃ pravṛddho varcomiśro vāyunā'dha praṇunnaḥ saratyatīvātisāraṃ tamāhurvyādhiṃ ghoraṃ ṣaḍvidhaṃ taṃ vadanti"},{"type":"verse","number":"6","sanskrit":"एकैकशः सर्वशश्चापि दोषैः शोकेनान्यःषष्ठ आमेन चोक्तः","text":"ekaikaśaḥ sarvaśaścāpi doṣaiḥ śokenānyaḥṣaṣṭha āmena coktaḥ"},{"type":"verse","number":"7","sanskrit":"आमपक्वक्रमं हित्वा नातिसारे क्रिया यतः अतोऽतिसारे सर्वस्मिन्नामं पक्वञ्च लक्षयेत्","text":"āmapakvakramaṃ hitvā nātisāre kriyā yataḥ ato'tisāre sarvasminnāmaṃ pakvañca lakṣayet"},{"type":"verse","number":"8","sanskrit":"संसृष्टमामैर्दोषैस्तु न्यस्तमप्सु निमज्जति पुरीषं भृशदुर्गन्धि पिच्छिलं चामसंज्ञितम्","text":"saṃsṛṣṭamāmairdoṣaistu nyastamapsu nimajjati purīṣaṃ bhṛśadurgandhi picchilaṃ cāmasaṃjñitam"},{"type":"verse","number":"9","sanskrit":"एतान्येव तु लिङ्गानि विपरीतानि यस्य वै लाघवञ्च विशेषेण तं तु पक्वं विनिर्दिशेत्","text":"etānyeva tu liṅgāni viparītāni yasya vai lāghavañca viśeṣeṇa taṃ tu pakvaṃ vinirdiśet"},{"type":"verse","number":"10","sanskrit":"न च संग्राहकं दद्यात्पूर्वमामातिसारिणे अकाले संगृहीतस्तु विकारान्कुरुते बहून्","text":"na ca saṃgrāhakaṃ dadyātpūrvamāmātisāriṇe akāle saṃgṛhītastu vikārānkurute bahūn"},{"type":"verse","number":"11","sanskrit":"दण्डकालसकाध्मानग्रहण्यर्शोभगन्दरान् शोथपाण्ड्वामयप्लीहगुल्ममेहोदरज्वरान्","text":"daṇḍakālasakādhmānagrahaṇyarśobhagandarān śothapāṇḍvāmayaplīhagulmamehodarajvarān"},{"type":"verse","number":"12","sanskrit":"डिम्भस्थः स्थविरस्थश्च वातपित्तात्मकश्च यः क्षीणधातुबलश्चापि बहुदोषोऽतिनिस्रुतः आमोऽपि स्तम्भनीयः स्यात्पाचनान्मरणं भवेत्","text":"ḍimbhasthaḥ sthavirasthaśca vātapittātmakaśca yaḥ kṣīṇadhātubalaścāpi bahudoṣo'tinisrutaḥ āmo'pi stambhanīyaḥ syātpācanānmaraṇaṃ bhavet"},{"type":"verse","number":"13","sanskrit":"लङ्घनमेकं मुक्त्वा न चान्यदस्तीह भेषजं बलिनः समुदीर्णदोषनिचयं तत्पाचयेत्तथा च शमयेत्","text":"laṅghanamekaṃ muktvā na cānyadastīha bheṣajaṃ balinaḥ samudīrṇadoṣanicayaṃ tatpācayettathā ca śamayet"},{"type":"verse","number":"14","sanskrit":"धान्याम्बुभ्यां शृतं तोयं तृष्णादाहातिसारिणे ह्रीबेरशृङ्गबेराभ्यां मुस्तपर्पटकेन वा मुस्तोदीच्यशृतं शीतं प्रदातव्यं पिपासवे","text":"dhānyāmbubhyāṃ śṛtaṃ toyaṃ tṛṣṇādāhātisāriṇe hrīberaśṛṅgaberābhyāṃ mustaparpaṭakena vā mustodīcyaśṛtaṃ śītaṃ pradātavyaṃ pipāsave"},{"type":"verse","number":"15","sanskrit":"हितं लङ्घनमेवादौ पूर्वरूपेऽतिसारिणे कार्यं वाऽनशनस्यान्ते प्रद्र वं लघु भोजनम्","text":"hitaṃ laṅghanamevādau pūrvarūpe'tisāriṇe kāryaṃ vā'naśanasyānte pradra vaṃ laghu bhojanam"},{"type":"verse","number":"16","sanskrit":"पथ्यादारुवचामुस्तैर्नागरातिविषाऽन्वितैः आमातिसारनाशाय क्वाथमेभिः पिबेन्नरः","text":"pathyādāruvacāmustairnāgarātiviṣā'nvitaiḥ āmātisāranāśāya kvāthamebhiḥ pibennaraḥ"},{"type":"verse","number":"17","sanskrit":"पाठाहिङ्ग्वजमोदोग्रापञ्चकोलाह्वजं रजः उष्णाम्बुपीतं सरुजं जयत्यामं ससैन्धवम्","text":"pāṭhāhiṅgvajamodogrāpañcakolāhvajaṃ rajaḥ uṣṇāmbupītaṃ sarujaṃ jayatyāmaṃ sasaindhavam"},{"type":"verse","number":"18","sanskrit":"हरीतकी सातिविषा हिङ्गु सौवर्चलं वचा सैन्धवञ्चापि संपिष्य पाययेदुष्णवारिणा","text":"harītakī sātiviṣā hiṅgu sauvarcalaṃ vacā saindhavañcāpi saṃpiṣya pāyayeduṣṇavāriṇā"},{"type":"verse","number":"19","sanskrit":"आमातिसारयोगोऽय पाचयित्वा चिकित्सति आमातिसारो योगेन यस्त्वेतेन न शाम्यति","text":"āmātisārayogo'ya pācayitvā cikitsati āmātisāro yogena yastvetena na śāmyati"},{"type":"verse","number":"20","sanskrit":"न तं योगशतेनापि चिकित्सति चिकित्सकः","text":"na taṃ yogaśatenāpi cikitsati cikitsakaḥ"},{"type":"verse","number":"21","sanskrit":"वत्सकातिविषाबिल्वं मुस्तकं बालकं शटी अतीसारं जयेत्सामं चिरजं रक्तशूलजित्","text":"vatsakātiviṣābilvaṃ mustakaṃ bālakaṃ śaṭī atīsāraṃ jayetsāmaṃ cirajaṃ raktaśūlajit"},{"type":"verse","number":"22","sanskrit":"एरण्डरससम्पिष्टं पक्वमामञ्च नागरम् आमातिसारशूलघ्नं पाचनं दीपनं परम्","text":"eraṇḍarasasampiṣṭaṃ pakvamāmañca nāgaram āmātisāraśūlaghnaṃ pācanaṃ dīpanaṃ param"},{"type":"verse","number":"23","sanskrit":"धान्यबालकबिल्वाब्दनागरैः पाचितं जलम् आमशूलविबन्धघ्नं पाचनं दीपनं परम्","text":"dhānyabālakabilvābdanāgaraiḥ pācitaṃ jalam āmaśūlavibandhaghnaṃ pācanaṃ dīpanaṃ param"},{"type":"verse","number":"24","sanskrit":"पित्ते धान्यचतुष्कन्तु शुण्ठीत्यागाद्वदन्ति हि रक्तेऽपि पित्तसाधर्म्याद्देयं धान्यचतुष्टयम्","text":"pitte dhānyacatuṣkantu śuṇṭhītyāgādvadanti hi rakte'pi pittasādharmyāddeyaṃ dhānyacatuṣṭayam"},{"type":"verse","number":"25","sanskrit":"इत्यामातिसारचिकित्सा अथ पक्कातीसारचिकित्सा सलोध्रं धातकीबिल्वमुस्ताऽम्रास्थिकलिङ्गकम् पिबेन्माहिषतक्रेण पक्वातीसारनाशनम्","text":"ityāmātisāracikitsā atha pakkātīsāracikitsā salodhraṃ dhātakībilvamustā'mrāsthikaliṅgakam pibenmāhiṣatakreṇa pakvātīsāranāśanam"},{"type":"verse","number":"26","sanskrit":"समङ्गा धातकीपुष्पं मञ्जिष्ठा लोध्र एव च शाल्मलीवेष्टको लोध्रो दाडिमद्रुफलत्वचौ","text":"samaṅgā dhātakīpuṣpaṃ mañjiṣṭhā lodhra eva ca śālmalīveṣṭako lodhro dāḍimadruphalatvacau"},{"type":"verse","number":"27","sanskrit":"आम्रास्थिमध्यं लोध्रश्च विल्वमध्यं प्रियङ्गु च मधुकं शृङ्गबेरञ्च दीर्घवृन्तत्वगेव च","text":"āmrāsthimadhyaṃ lodhraśca vilvamadhyaṃ priyaṅgu ca madhukaṃ śṛṅgaberañca dīrghavṛntatvageva ca"},{"type":"verse","number":"28","sanskrit":"चत्वार एते योगाः स्युः पक्वातीसारनाशनाः ते योगा उपयोज्याःस्युः सक्षौद्रा स्तण्डुलाम्बुना","text":"catvāra ete yogāḥ syuḥ pakvātīsāranāśanāḥ te yogā upayojyāḥsyuḥ sakṣaudrā staṇḍulāmbunā"},{"type":"verse","number":"29","sanskrit":"कञ्चटदाडिमजम्बू शृङ्गाटकपत्रबिल्वबर्हिष्ठम् जलधरनागरसहितं गङ्गामपि वेगवाहिनीं रुन्ध्यात्","text":"kañcaṭadāḍimajambū śṛṅgāṭakapatrabilvabarhiṣṭham jaladharanāgarasahitaṃ gaṅgāmapi vegavāhinīṃ rundhyāt"},{"type":"verse","number":"30","sanskrit":"मोचरसमुस्तनागर पाठाऽरलुधातकीकुसुमैः चूर्ण मथितसमेतं रुणद्धि गङ्गाप्रवाहमपि सद्यं","text":"mocarasamustanāgara pāṭhā'raludhātakīkusumaiḥ cūrṇa mathitasametaṃ ruṇaddhi gaṅgāpravāhamapi sadyaṃ"},{"type":"verse","number":"31","sanskrit":"मुस्ता वत्सकबीजं मोचरसो बिल्वधातकीलोध्रम् गुडमथितसंप्रयुक्तं गङ्गामपि वेगवाहिनीं रुन्ध्यात्","text":"mustā vatsakabījaṃ mocaraso bilvadhātakīlodhram guḍamathitasaṃprayuktaṃ gaṅgāmapi vegavāhinīṃ rundhyāt"},{"type":"verse","number":"32","sanskrit":"मुस्ताऽरलुकशुण्ठीभिर्धातकीलोध्रबालकैः बिल्वमोचरसाभ्यां च पाठेन्द्र यववत्सकैः","text":"mustā'ralukaśuṇṭhībhirdhātakīlodhrabālakaiḥ bilvamocarasābhyāṃ ca pāṭhendra yavavatsakaiḥ"},{"type":"verse","number":"33","sanskrit":"आम्रबीजसमङ्गाऽतिविषायुक्तैश्च चूर्णितैः मधु तण्डुलपानीयं पीतं हन्ति प्रवाहिकाम्","text":"āmrabījasamaṅgā'tiviṣāyuktaiśca cūrṇitaiḥ madhu taṇḍulapānīyaṃ pītaṃ hanti pravāhikām"},{"type":"verse","number":"34","sanskrit":"हन्ति सर्वानतीसारान् ग्रहणीं हन्ति वेगतः वृद्धगङ्गाधरं चूर्णरुन्ध्याद्गीर्वाणवाहिनीम्","text":"hanti sarvānatīsārān grahaṇīṃ hanti vegataḥ vṛddhagaṅgādharaṃ cūrṇarundhyādgīrvāṇavāhinīm"},{"type":"verse","number":"35","sanskrit":"अङ्कोलमूलकल्कस्तण्डुलपयसा समाक्षिकः पीतः सेतुरिववारिवेगं झटिति निरुन्ध्यादतीसारम्","text":"aṅkolamūlakalkastaṇḍulapayasā samākṣikaḥ pītaḥ seturivavārivegaṃ jhaṭiti nirundhyādatīsāram"},{"type":"verse","number":"36","sanskrit":"कुटजत्वक्तुलामार्द्रां द्रोणनीरे पचेद्भिषक् पादशेषं शृतं नीत्वा वस्त्रपूतं पुनः पचेत्","text":"kuṭajatvaktulāmārdrāṃ droṇanīre pacedbhiṣak pādaśeṣaṃ śṛtaṃ nītvā vastrapūtaṃ punaḥ pacet"},{"type":"verse","number":"37","sanskrit":"लज्जालुर्धातकी बिल्वं पाठा मोचरसस्तथा मुस्ता चातिविषा चैव चूर्णमेषां पलं पलम्","text":"lajjālurdhātakī bilvaṃ pāṭhā mocarasastathā mustā cātiviṣā caiva cūrṇameṣāṃ palaṃ palam"},{"type":"verse","number":"38","sanskrit":"निक्षिप्य विपचेत्तावद् यावद्दर्वी प्रलिप्यते जलेन च्छागदुग्धेन पीतो मण्डेन वा जयेत्","text":"nikṣipya vipacettāvad yāvaddarvī pralipyate jalena cchāgadugdhena pīto maṇḍena vā jayet"},{"type":"verse","number":"39","sanskrit":"घोरान्सर्वानतीसारान्नाना वर्णान्सवेदनान् असृग्दरं समस्तञ्च तथाऽशासि प्रवाहिकाम्","text":"ghorānsarvānatīsārānnānā varṇānsavedanān asṛgdaraṃ samastañca tathā'śāsi pravāhikām"},{"type":"verse","number":"40","sanskrit":"कृत्वाऽलवालं सुदृढं पिष्टैरामलकैर्भिषक् आर्द्र कस्य रसेनाशु पूरयेन्नाभिमण्डलम्","text":"kṛtvā'lavālaṃ sudṛḍhaṃ piṣṭairāmalakairbhiṣak ārdra kasya rasenāśu pūrayennābhimaṇḍalam"},{"type":"verse","number":"41","sanskrit":"नदीवेगोपमं घोरं प्रवृद्धं दुर्द्धरं नृणाम् सद्योऽतीसारमजयं नाशयत्येष योगराट्","text":"nadīvegopamaṃ ghoraṃ pravṛddhaṃ durddharaṃ nṛṇām sadyo'tīsāramajayaṃ nāśayatyeṣa yogarāṭ"},{"type":"verse","number":"42","sanskrit":"पाठा पिष्टा च गोदध्ना तथा मध्यत्वगाम्रजा अतीसारं व्यथादाहं हन्त्येवाशु न संशयः","text":"pāṭhā piṣṭā ca godadhnā tathā madhyatvagāmrajā atīsāraṃ vyathādāhaṃ hantyevāśu na saṃśayaḥ"},{"type":"verse","number":"43","sanskrit":"अरुणं फेनिलं रूक्षमल्पमल्पं मुहुर्मुहुः शकृदामं सरुक्शब्दं मारुतेनातिसार्यते","text":"aruṇaṃ phenilaṃ rūkṣamalpamalpaṃ muhurmuhuḥ śakṛdāmaṃ sarukśabdaṃ mārutenātisāryate"},{"type":"verse","number":"44","sanskrit":"वचा चातिविषा मुस्तं बीजानि कुटजस्य च श्रेष्ठः कषाय एतेषां वातातीसारशान्तये","text":"vacā cātiviṣā mustaṃ bījāni kuṭajasya ca śreṣṭhaḥ kaṣāya eteṣāṃ vātātīsāraśāntaye"},{"type":"verse","number":"45","sanskrit":"पित्तात्पीतं शकृद्र क्तं दुर्गन्धि हरितं द्रुतम् गुदपाकतृषामूर्च्छादाहयुक्तं प्रवर्त्तते","text":"pittātpītaṃ śakṛdra ktaṃ durgandhi haritaṃ drutam gudapākatṛṣāmūrcchādāhayuktaṃ pravarttate"},{"type":"verse","number":"46","sanskrit":"बिल्वशक्रयवाम्भोदबालकातिविषाकृतः कषायो हन्त्यतीसारं सामं पित्तसमुद्भवम्","text":"bilvaśakrayavāmbhodabālakātiviṣākṛtaḥ kaṣāyo hantyatīsāraṃ sāmaṃ pittasamudbhavam"},{"type":"verse","number":"47","sanskrit":"रसाञ्जनं सातिविषं कुटजस्य फलत्वचम् धातकी शृङ्गबेरञ्च पाययेत्तण्डुलाम्बुना","text":"rasāñjanaṃ sātiviṣaṃ kuṭajasya phalatvacam dhātakī śṛṅgaberañca pāyayettaṇḍulāmbunā"},{"type":"verse","number":"48","sanskrit":"निहन्ति मधुना पीतं पित्तातीसारमुल्वणम् अग्निं सन्दीपयेदेतच्छूलमाशु निवारयेत्","text":"nihanti madhunā pītaṃ pittātīsāramulvaṇam agniṃ sandīpayedetacchūlamāśu nivārayet"},{"type":"verse","number":"49","sanskrit":"पित्तकृन्ति यदाऽत्यर्थं द्र व्याण्यश्नाति पैत्तिके तदाऽस्य जायतेऽभीक्ष्णं रक्तातीसार उल्वणः","text":"pittakṛnti yadā'tyarthaṃ dra vyāṇyaśnāti paittike tadā'sya jāyate'bhīkṣṇaṃ raktātīsāra ulvaṇaḥ"},{"type":"verse","number":"50","sanskrit":"वत्सत्वग्दाडिमतरु शलाटुफलसम्भवां त्वक् च त्वग्युगलं पलमानं विपचेदष्टांशसंमिते तोये अं","text":"vatsatvagdāḍimataru śalāṭuphalasambhavāṃ tvak ca tvagyugalaṃ palamānaṃ vipacedaṣṭāṃśasaṃmite toye aṃ"},{"type":"verse","number":"51","sanskrit":"अष्टमभागं शेषं क्वाथं मधुना पिबेत्पुरुषः रक्तातिसारमुल्वणमतिशयितं नाशयेन्नियतम्","text":"aṣṭamabhāgaṃ śeṣaṃ kvāthaṃ madhunā pibetpuruṣaḥ raktātisāramulvaṇamatiśayitaṃ nāśayenniyatam"},{"type":"verse","number":"52","sanskrit":"कुटजातिविषामुस्ताबालकं लोध्रचन्दनम् धातकी दाडिमं पाठा क्वाथमेषां समाक्षिकम्","text":"kuṭajātiviṣāmustābālakaṃ lodhracandanam dhātakī dāḍimaṃ pāṭhā kvāthameṣāṃ samākṣikam"},{"type":"verse","number":"53","sanskrit":"पिबद्र क्तातिसारे तु दाहशूलप्रशान्तये कुटजादिकषायोऽय सर्वातीसारनाशनः","text":"pibadra ktātisāre tu dāhaśūlapraśāntaye kuṭajādikaṣāyo'ya sarvātīsāranāśanaḥ"},{"type":"verse","number":"54","sanskrit":"कल्कस्तिलानां कृष्णानां शर्करापञ्चभागिकः आजेन पयसा पीतः सद्योऽतीसारनाशनः","text":"kalkastilānāṃ kṛṣṇānāṃ śarkarāpañcabhāgikaḥ ājena payasā pītaḥ sadyo'tīsāranāśanaḥ"},{"type":"verse","number":"55","sanskrit":"सवत्सकः सातिविषः सबिल्वः सोदीच्यमुस्तश्च कृतः कषायः सामे सशूले सहशोणिते च चिरप्रवृत्तेऽपि हितोऽतिसारे","text":"savatsakaḥ sātiviṣaḥ sabilvaḥ sodīcyamustaśca kṛtaḥ kaṣāyaḥ sāme saśūle sahaśoṇite ca cirapravṛtte'pi hito'tisāre"},{"type":"verse","number":"56","sanskrit":"कृष्णमृन्मधुकं लोध्रं कौटजं तण्डुलाम्बुना पीतमेकत्र सक्षौद्रं रक्तसंग्रहणं परम्","text":"kṛṣṇamṛnmadhukaṃ lodhraṃ kauṭajaṃ taṇḍulāmbunā pītamekatra sakṣaudraṃ raktasaṃgrahaṇaṃ param"},{"type":"verse","number":"57","sanskrit":"गुडेन भक्षयेद्बिल्वं रक्तातीसारनाशनम् आमशूलविबन्धघ्नं कुक्षिरोगहरं परम्","text":"guḍena bhakṣayedbilvaṃ raktātīsāranāśanam āmaśūlavibandhaghnaṃ kukṣirogaharaṃ param"},{"type":"verse","number":"58","sanskrit":"जम्ब्वाम्रामलकीनान्तु कुट्टयेत्पल्लवान्नवान् तत्पीतं मधुना युक्तं रक्तातीसारनाशनम्","text":"jambvāmrāmalakīnāntu kuṭṭayetpallavānnavān tatpītaṃ madhunā yuktaṃ raktātīsāranāśanam"},{"type":"verse","number":"59","sanskrit":"निक्वाथ्य मूलममलं गिरिमल्लिकायाःसम्यक् पलद्वितयमम्बुचतुःशरावे तत्पादशेषसलिलं खलु शोषणीयं क्षीरे पलद्वयमिते कुशलैरजप्याः","text":"nikvāthya mūlamamalaṃ girimallikāyāḥsamyak paladvitayamambucatuḥśarāve tatpādaśeṣasalilaṃ khalu śoṣaṇīyaṃ kṣīre paladvayamite kuśalairajapyāḥ"},{"type":"verse","number":"60","sanskrit":"प्रक्षिप्य माषकानष्टौ मधुनस्तत्र शीतले रक्तातिसारी तत्पीत्वा नैरुज्यंक्षिप्रमाप्नुयात्","text":"prakṣipya māṣakānaṣṭau madhunastatra śītale raktātisārī tatpītvā nairujyaṃkṣipramāpnuyāt"},{"type":"verse","number":"61","sanskrit":"पीत्वा शतावरीकल्कं पयसा क्षीरभुग् जयेत् रक्तातिसारं पीत्वा वा तया सिद्धं घृतं नरः","text":"pītvā śatāvarīkalkaṃ payasā kṣīrabhug jayet raktātisāraṃ pītvā vā tayā siddhaṃ ghṛtaṃ naraḥ"},{"type":"verse","number":"62","sanskrit":"गोदुग्धनवनीतं च मधुना सितया सह लीढं रक्तातिसारे तु ग्राहकं परमं मतम्","text":"godugdhanavanītaṃ ca madhunā sitayā saha līḍhaṃ raktātisāre tu grāhakaṃ paramaṃ matam"},{"type":"verse","number":"63","sanskrit":"पीतं मधुसितायुक्तं चन्दनं तण्डुलाम्बुना रक्तातीसारजिद्र क्तपित्ततृड्दाहमेहनुत्","text":"pītaṃ madhusitāyuktaṃ candanaṃ taṇḍulāmbunā raktātīsārajidra ktapittatṛḍdāhamehanut"},{"type":"verse","number":"64","sanskrit":"विरेकैर्बहुभिर्यस्य गुदं पित्तेन दह्यते पच्यते वा तयोः कार्यं सेकप्रक्षालनादिकम्","text":"virekairbahubhiryasya gudaṃ pittena dahyate pacyate vā tayoḥ kāryaṃ sekaprakṣālanādikam"},{"type":"verse","number":"65","sanskrit":"पटोलयष्टिमधुकक्वाथेन शिशिरेण हि गुदप्रक्षालनं कार्यं तेनैव गुदसेचनम्","text":"paṭolayaṣṭimadhukakvāthena śiśireṇa hi gudaprakṣālanaṃ kāryaṃ tenaiva gudasecanam"},{"type":"verse","number":"66","sanskrit":"दाहे पाके हितं छागीदुग्धं सक्षौद्र शर्करम् गुदस्य क्षालने सेके युक्तं पाने च भोजने","text":"dāhe pāke hitaṃ chāgīdugdhaṃ sakṣaudra śarkaram gudasya kṣālane seke yuktaṃ pāne ca bhojane"},{"type":"verse","number":"67","sanskrit":"अतिप्रवृत्त्या महती भवेद्यदि गुदव्यथा स्विन्नमूषकमांसेन तदा संस्वेदयेद् गुदम्","text":"atipravṛttyā mahatī bhavedyadi gudavyathā svinnamūṣakamāṃsena tadā saṃsvedayed gudam"},{"type":"verse","number":"68","sanskrit":"अथ गोधूमचूर्णस्य संशृतस्य तु वारिणा साज्यस्य गोलकं कृत्वा मृदु संस्वेदयेद् गुदम्","text":"atha godhūmacūrṇasya saṃśṛtasya tu vāriṇā sājyasya golakaṃ kṛtvā mṛdu saṃsvedayed gudam"},{"type":"verse","number":"69","sanskrit":"गुदनिःसरणे प्रोक्तं चाङ्गेरीघृतमुत्तमम् गुदभ्रंशे गुदं स्नेहैरभ्यज्यान्तःप्रवेशयेत्","text":"gudaniḥsaraṇe proktaṃ cāṅgerīghṛtamuttamam gudabhraṃśe gudaṃ snehairabhyajyāntaḥpraveśayet"},{"type":"verse","number":"70","sanskrit":"प्रविष्टं स्वेदयेन्मन्दं मूषकस्यामिषेण हि","text":"praviṣṭaṃ svedayenmandaṃ mūṣakasyāmiṣeṇa hi"},{"type":"verse","number":"71","sanskrit":"शम्बूकमांसं सुस्विन्नंसतैललवणान्वितम् ईषद् घृतेन चाभ्यज्य स्वेदयेत्तेन यत्नतः","text":"śambūkamāṃsaṃ susvinnaṃsatailalavaṇānvitam īṣad ghṛtena cābhyajya svedayettena yatnataḥ"},{"type":"verse","number":"72","sanskrit":"गुदभ्रंशमशेषेण नाशयेत्क्षिप्रमेव च मूषकस्याथ वसया पायुं सम्यक्प्रलेपयेत् गुदभ्रंशाभिधो व्याधिः प्रणश्यति न संशयः","text":"gudabhraṃśamaśeṣeṇa nāśayetkṣiprameva ca mūṣakasyātha vasayā pāyuṃ samyakpralepayet gudabhraṃśābhidho vyādhiḥ praṇaśyati na saṃśayaḥ"},{"type":"verse","number":"73","sanskrit":"चाङ्गेरीकोलदध्यम्लक्षारनागरसंयुतम् घृतं विपक्वं पातव्यं गुदभ्रंशगदापहम्","text":"cāṅgerīkoladadhyamlakṣāranāgarasaṃyutam ghṛtaṃ vipakvaṃ pātavyaṃ gudabhraṃśagadāpaham"},{"type":"verse","number":"74","sanskrit":"कोमलं पद्मिनीपत्रं यः खादेच्छर्कराऽन्वितम् एतन्निश्चित्य निर्दिष्टं न तस्य गुदनिर्गमः","text":"komalaṃ padminīpatraṃ yaḥ khādeccharkarā'nvitam etanniścitya nirdiṣṭaṃ na tasya gudanirgamaḥ"},{"type":"verse","number":"75","sanskrit":"श्वेतं स्निग्धं घनं बद्धं शीतलं मन्दवेदनम् गौरवारुचिसंयुक्तं श्लेष्मणा सार्यते शकृत्","text":"śvetaṃ snigdhaṃ ghanaṃ baddhaṃ śītalaṃ mandavedanam gauravārucisaṃyuktaṃ śleṣmaṇā sāryate śakṛt"},{"type":"verse","number":"76","sanskrit":"श्लेष्मातिसारे प्रथमं हितंलङ्घनपाचनम् योज्यश्चामातिसारघ्नो यथोक्तो दीपनो गणः","text":"śleṣmātisāre prathamaṃ hitaṃlaṅghanapācanam yojyaścāmātisāraghno yathokto dīpano gaṇaḥ"},{"type":"verse","number":"77","sanskrit":"चव्यं सातिविषामुस्तं बालबिल्वं सनागरम् वत्सकत्वक्फलं पथ्या च्छर्दिश्लेष्मातिसारनुत्","text":"cavyaṃ sātiviṣāmustaṃ bālabilvaṃ sanāgaram vatsakatvakphalaṃ pathyā cchardiśleṣmātisāranut"},{"type":"verse","number":"78","sanskrit":"हिङ्गु सौवर्चलंव्योषमभयाऽतिविषा वचा पीतमुष्णाम्बुना चूर्णमेषां श्लेष्मातिसारनुत्","text":"hiṅgu sauvarcalaṃvyoṣamabhayā'tiviṣā vacā pītamuṣṇāmbunā cūrṇameṣāṃ śleṣmātisāranut"},{"type":"verse","number":"79","sanskrit":"अथ द्विदोषजातीसारस्य सामान्यचिकित्सा तत्र कृमिशत्र्वादिक्वाथः कृमिशत्रुवचाबिल्वपाठाधान्याककट्फलम् एषां क्वाथं भिषग्दद्यादतीसारे द्विदोषजे","text":"atha dvidoṣajātīsārasya sāmānyacikitsā tatra kṛmiśatrvādikvāthaḥ kṛmiśatruvacābilvapāṭhādhānyākakaṭphalam eṣāṃ kvāthaṃ bhiṣagdadyādatīsāre dvidoṣaje"},{"type":"verse","number":"80","sanskrit":"तेषां चिकित्सा प्रोक्तैव विशिष्टा च निगद्यते","text":"teṣāṃ cikitsā proktaiva viśiṣṭā ca nigadyate"},{"type":"verse","number":"81","sanskrit":"अथ वातश्लेष्मातिसारस्य चिकित्सा तत्र कट्फलादिक्वाथः कट्फलं मधुकं लोध्रं त्वग्दाडिमफलस्य च सतण्डुलजलं चूर्णं वातश्लेष्मातिसारनुत्","text":"atha vātaśleṣmātisārasya cikitsā tatra kaṭphalādikvāthaḥ kaṭphalaṃ madhukaṃ lodhraṃ tvagdāḍimaphalasya ca sataṇḍulajalaṃ cūrṇaṃ vātaśleṣmātisāranut"},{"type":"verse","number":"82","sanskrit":"अथ वातपित्तातिसारस्य चिकित्सा तत्र चित्रकादिक्वाथः चित्रकातिविषामुस्तं वालबिल्वं सनागरम् वत्सकत्वक्फलं पथ्या वातपित्तातिसारनुत्","text":"atha vātapittātisārasya cikitsā tatra citrakādikvāthaḥ citrakātiviṣāmustaṃ vālabilvaṃ sanāgaram vatsakatvakphalaṃ pathyā vātapittātisāranut"},{"type":"verse","number":"83","sanskrit":"अथ पित्तकफातीसारस्य चिकित्सा तत्र मुस्तादिक्वाथः मुस्ता सातिविषा मूर्वा वचा च कुटजः समाः एषां कषायः सक्षौद्रः पित्तश्लेष्मातिसारनुत्","text":"atha pittakaphātīsārasya cikitsā tatra mustādikvāthaḥ mustā sātiviṣā mūrvā vacā ca kuṭajaḥ samāḥ eṣāṃ kaṣāyaḥ sakṣaudraḥ pittaśleṣmātisāranut"},{"type":"verse","number":"84","sanskrit":"तन्द्रा युक्तो मोहसादास्यशोषी वर्चः कुर्यान्नैकरूपं तृषाऽत्त सर्वोद्भूते सर्वलिङ्गोपपत्तिः कृच्छ्रः साध्योबालवृद्धाबलानाम्","text":"tandrā yukto mohasādāsyaśoṣī varcaḥ kuryānnaikarūpaṃ tṛṣā'tta sarvodbhūte sarvaliṅgopapattiḥ kṛcchraḥ sādhyobālavṛddhābalānām"},{"type":"verse","number":"85","sanskrit":"अथ सन्निपातातीसारस्य चिकित्सा पञ्चमूलीबलाबिल्वगुडूची मुस्तनागरैः पाठाभूनिम्बबर्हिष्ठकुटजत्वक्फलैः शृतम्","text":"atha sannipātātīsārasya cikitsā pañcamūlībalābilvaguḍūcī mustanāgaraiḥ pāṭhābhūnimbabarhiṣṭhakuṭajatvakphalaiḥ śṛtam"},{"type":"verse","number":"86","sanskrit":"सर्वजं हन्त्यतीसारं ज्वरञ्चापि तथा वमिम् सशूलोपद्र वं श्वासं कासं चापि सुदुस्तरम्","text":"sarvajaṃ hantyatīsāraṃ jvarañcāpi tathā vamim saśūlopadra vaṃ śvāsaṃ kāsaṃ cāpi sudustaram"},{"type":"verse","number":"87","sanskrit":"पञ्चमूली च सामान्या पित्ते योज्या कनीयसी वाते पुनर्बलासे च सा योज्या महती मता","text":"pañcamūlī ca sāmānyā pitte yojyā kanīyasī vāte punarbalāse ca sā yojyā mahatī matā"},{"type":"verse","number":"88","sanskrit":"अभया नागरं मुस्तं गुडेन सह योजितम् चतुःसमेयं गुटिका सर्वातीसारनाशनी","text":"abhayā nāgaraṃ mustaṃ guḍena saha yojitam catuḥsameyaṃ guṭikā sarvātīsāranāśanī"},{"type":"verse","number":"89","sanskrit":"आमातीसारमानाहं सविबन्धं विसूचिकाम् कृमीनरोचकं हन्याद्दीपयत्याशु चानलम्","text":"āmātīsāramānāhaṃ savibandhaṃ visūcikām kṛmīnarocakaṃ hanyāddīpayatyāśu cānalam"},{"type":"verse","number":"90","sanskrit":"तत्कालाकृष्टकुटजत्वचं तण्डुलवारिणा पिष्ट्वा चतुःपलमितां जम्बूपत्रेण वेष्टिताम्","text":"tatkālākṛṣṭakuṭajatvacaṃ taṇḍulavāriṇā piṣṭvā catuḥpalamitāṃ jambūpatreṇa veṣṭitām"},{"type":"verse","number":"91","sanskrit":"सूत्रेण बद्ध्वा गोधूमपिष्टेन परिवेष्टिताम् लिप्ताञ्च घनपङ्केन निर्दहेद् गोमयाग्निना","text":"sūtreṇa baddhvā godhūmapiṣṭena pariveṣṭitām liptāñca ghanapaṅkena nirdahed gomayāgninā"},{"type":"verse","number":"92","sanskrit":"अङ्गारवर्णाञ्च मृदं दृष्ट्वा वह्नेः समुद्धरेत् ततो रसं समादाय शीतं क्षौद्र युतं पिबेत्","text":"aṅgāravarṇāñca mṛdaṃ dṛṣṭvā vahneḥ samuddharet tato rasaṃ samādāya śītaṃ kṣaudra yutaṃ pibet"},{"type":"verse","number":"93","sanskrit":"उक्तः कृष्णात्रिपुत्रेण पुटपाकस्तु कौटजः जयेत्सर्वानतीसारान् रक्तजान्सुचिरोत्थितान्","text":"uktaḥ kṛṣṇātriputreṇa puṭapākastu kauṭajaḥ jayetsarvānatīsārān raktajānsucirotthitān"},{"type":"verse","number":"94","sanskrit":"कुटजत्वक्कृतः क्वाथो वस्त्रपूतो हिमीकृतः स लीढोऽतिविषायुक्तः स्यात् त्रिदोषातिसारनुत्","text":"kuṭajatvakkṛtaḥ kvātho vastrapūto himīkṛtaḥ sa līḍho'tiviṣāyuktaḥ syāt tridoṣātisāranut"},{"type":"verse","number":"95","sanskrit":"इच्छन्त्यत्राष्टमांशेन क्वाथादतिविषारजः प्रक्षेपयेच्चतुर्थांशमिति केचिद्वदन्ति हि","text":"icchantyatrāṣṭamāṃśena kvāthādativiṣārajaḥ prakṣepayeccaturthāṃśamiti kecidvadanti hi"},{"type":"verse","number":"96","sanskrit":"पलमङ्कोटमूलस्य पाठां दार्वीञ्च तत्समाम् पिष्ट्वा तण्डुलतोयेन वटकानक्षसम्मितान्","text":"palamaṅkoṭamūlasya pāṭhāṃ dārvīñca tatsamām piṣṭvā taṇḍulatoyena vaṭakānakṣasammitān"},{"type":"verse","number":"97","sanskrit":"छायाशुष्कांश्च तान्कुर्यात्तेष्वेकं तण्डुलाम्बुना पेषयित्वा प्रदद्यात्तं पानाय गदिने भिषक्","text":"chāyāśuṣkāṃśca tānkuryātteṣvekaṃ taṇḍulāmbunā peṣayitvā pradadyāttaṃ pānāya gadine bhiṣak"},{"type":"verse","number":"98","sanskrit":"वातपित्तकफोद्भूतान्द्वन्द्वजान्सान्निपातिकान् हन्यात्सर्वानतीसारान्वटकोऽय प्रयोजितः","text":"vātapittakaphodbhūtāndvandvajānsānnipātikān hanyātsarvānatīsārānvaṭako'ya prayojitaḥ"},{"type":"verse","number":"99","sanskrit":"तैस्तैर्भावैः शोचतोऽल्पाशनस्य बाष्पोष्मा वै वह्निमाविश्य जन्तोः कोष्ठं गत्वा क्षोभयेत्तस्य रक्तं तच्चाधस्तात्काकणन्तीप्रकाशम्","text":"taistairbhāvaiḥ śocato'lpāśanasya bāṣpoṣmā vai vahnimāviśya jantoḥ koṣṭhaṃ gatvā kṣobhayettasya raktaṃ taccādhastātkākaṇantīprakāśam"},{"type":"verse","number":"100","sanskrit":"निर्गच्छेद् वै विड्विमिश्रं ह्यविड् वा निर्गन्धं वा गन्धवद्वाऽतिसारः शोकोत्पन्नो दुश्चिकित्स्योऽतिमात्रं रोगो वैद्यैः कष्ट एष प्रदिष्टः","text":"nirgacched vai viḍvimiśraṃ hyaviḍ vā nirgandhaṃ vā gandhavadvā'tisāraḥ śokotpanno duścikitsyo'timātraṃ rogo vaidyaiḥ kaṣṭa eṣa pradiṣṭaḥ"},{"type":"verse","number":"101","sanskrit":"भयेन क्षोभिता दोषा दूषयन्ति मलं यदा तदाऽतिसार्यते जन्तुः क्षिप्रमुष्णं जलप्लवम्","text":"bhayena kṣobhitā doṣā dūṣayanti malaṃ yadā tadā'tisāryate jantuḥ kṣipramuṣṇaṃ jalaplavam"},{"type":"verse","number":"102","sanskrit":"वातपित्तातिसारस्य प्रायो लिङ्गैः समन्वितम् अभयोपशमाच्छर्म यस्मिन्स्यात्स भयात्स्मृतः","text":"vātapittātisārasya prāyo liṅgaiḥ samanvitam abhayopaśamāccharma yasminsyātsa bhayātsmṛtaḥ"},{"type":"verse","number":"103","sanskrit":"भयशोकसमुद्भूतौ ज्ञेयौ वातातिसारवत् तयोर्वातहरी कार्या हर्षणाश्वासनैः क्रिया","text":"bhayaśokasamudbhūtau jñeyau vātātisāravat tayorvātaharī kāryā harṣaṇāśvāsanaiḥ kriyā"},{"type":"verse","number":"104","sanskrit":"अन्नाजीर्णात्प्रद्रुताः क्षोभयन्तो दोषाः कोष्ठे धातुसंघान्मलांश्च नानावर्णान्नैकशः सारयन्ति शूलोपेतं षष्ठमेनं वदन्ति","text":"annājīrṇātpradrutāḥ kṣobhayanto doṣāḥ koṣṭhe dhātusaṃghānmalāṃśca nānāvarṇānnaikaśaḥ sārayanti śūlopetaṃ ṣaṣṭhamenaṃ vadanti"},{"type":"verse","number":"105","sanskrit":"अथामातीसारस्य चिकित्सा तत्र वत्सकादिक्वाथः वत्सकातिविषाशुण्ठीबिल्वहिङ्गुयवाम्बुदाः चित्रकेण युतः क्वाथ आमातीसारनाशनः","text":"athāmātīsārasya cikitsā tatra vatsakādikvāthaḥ vatsakātiviṣāśuṇṭhībilvahiṅguyavāmbudāḥ citrakeṇa yutaḥ kvātha āmātīsāranāśanaḥ"},{"type":"verse","number":"106","sanskrit":"अथ शोथातीसारस्य चिकित्सा तत्र शोथघ्न्यादिक्वाथः शोथघ्नीन्द्र यवौ पाठा श्रीफलातिविषाघनः क्वथिताः सोषणाः पीताः शोथातीसारनाशनाः","text":"atha śothātīsārasya cikitsā tatra śothaghnyādikvāthaḥ śothaghnīndra yavau pāṭhā śrīphalātiviṣāghanaḥ kvathitāḥ soṣaṇāḥ pītāḥ śothātīsāranāśanāḥ"},{"type":"verse","number":"107","sanskrit":"अथ छर्द्यतीसारस्य चिकित्सा तत्राम्रास्थ्यादिक्वाथः आम्रास्थिमध्यमालूरफलक्वाथः समाक्षिकः शर्करासहितो हन्याच्छर्द्यतीसारमुल्वणम्","text":"atha chardyatīsārasya cikitsā tatrāmrāsthyādikvāthaḥ āmrāsthimadhyamālūraphalakvāthaḥ samākṣikaḥ śarkarāsahito hanyācchardyatīsāramulvaṇam"},{"type":"verse","number":"108","sanskrit":"कषायो भृष्टमुद्गस्य सलाजमधुशर्करः निहन्याच्छर्द्यतीसारं तृष्णां दाहं ज्वरं भ्रमम्","text":"kaṣāyo bhṛṣṭamudgasya salājamadhuśarkaraḥ nihanyācchardyatīsāraṃ tṛṣṇāṃ dāhaṃ jvaraṃ bhramam"},{"type":"verse","number":"109","sanskrit":"दध्ना ससारेण समाक्षिकेण भुञ्जीत निःसारकपीडितस्तु सुतप्तकुप्यक्वथितेन वाऽपि क्षीरेण शीतेन मधुप्लुतेन","text":"dadhnā sasāreṇa samākṣikeṇa bhuñjīta niḥsārakapīḍitastu sutaptakupyakvathitena vā'pi kṣīreṇa śītena madhuplutena"},{"type":"verse","number":"110","sanskrit":"दीप्ताग्निर्निष्पुरीषो यः सार्यते फेनिलं शकृत् स पिबेत्फाणितं शुण्ठीं दधि तैलं पयो घृतम् बलाविश्वाशृतं क्षीरं गुडतैलानुयोजितम् दीप्ताग्निं पाययेत्प्रातः सुखदं वर्चसः क्षये","text":"dīptāgnirniṣpurīṣo yaḥ sāryate phenilaṃ śakṛt sa pibetphāṇitaṃ śuṇṭhīṃ dadhi tailaṃ payo ghṛtam balāviśvāśṛtaṃ kṣīraṃ guḍatailānuyojitam dīptāgniṃ pāyayetprātaḥ sukhadaṃ varcasaḥ kṣaye"},{"type":"verse","number":"111","sanskrit":"तुलां संकुट्य बिल्वस्य पचेत्पादावशेषितम् सक्षीरं साधयेत्तैलं श्लक्ष्णपिष्टैरिमैः समैः","text":"tulāṃ saṃkuṭya bilvasya pacetpādāvaśeṣitam sakṣīraṃ sādhayettailaṃ ślakṣṇapiṣṭairimaiḥ samaiḥ"},{"type":"verse","number":"112","sanskrit":"बिल्वं सधातकीकुष्ठं शुण्ठीरास्नापुनर्नवाः देवदारुवचामुस्तं लोध्रमोचरसान्वितम्","text":"bilvaṃ sadhātakīkuṣṭhaṃ śuṇṭhīrāsnāpunarnavāḥ devadāruvacāmustaṃ lodhramocarasānvitam"},{"type":"verse","number":"113","sanskrit":"एभिर्मृद्वग्निना पक्वं ग्रहण्यर्शोऽतिसारनुत् बिल्वतैलमितिख्यातमत्रिपुत्रेण भाषितम्","text":"ebhirmṛdvagninā pakvaṃ grahaṇyarśo'tisāranut bilvatailamitikhyātamatriputreṇa bhāṣitam"},{"type":"verse","number":"114","sanskrit":"ग्रहण्यर्शोऽधिकारे ये स्नेहाः समुपदर्शिताः योज्यास्ते ह्यतिसारेऽपि त्रयाणां तुल्यहेतुना","text":"grahaṇyarśo'dhikāre ye snehāḥ samupadarśitāḥ yojyāste hyatisāre'pi trayāṇāṃ tulyahetunā"},{"type":"verse","number":"115","sanskrit":"वायुः प्रवृद्धो निचितं बलासं नुदत्यधस्तादहिताशनस्य प्रवाहतोऽल्प बहुशो मलाक्तं प्रवाहिकां तां प्रवदन्ति तज्ज्ञाः","text":"vāyuḥ pravṛddho nicitaṃ balāsaṃ nudatyadhastādahitāśanasya pravāhato'lpa bahuśo malāktaṃ pravāhikāṃ tāṃ pravadanti tajjñāḥ"},{"type":"verse","number":"116","sanskrit":"प्रवाहिका वातकृता सशूला पित्तात्सदाहा सकफा कफाच्च सशोणिता शोणितसम्भवा च ताः स्नेहरूक्षप्रभवा मतास्तु","text":"pravāhikā vātakṛtā saśūlā pittātsadāhā sakaphā kaphācca saśoṇitā śoṇitasambhavā ca tāḥ sneharūkṣaprabhavā matāstu"},{"type":"verse","number":"117","sanskrit":"तासामतीसारवदादिशेच्च लिङ्गं क्रमं चामविपक्वतां च","text":"tāsāmatīsāravadādiśecca liṅgaṃ kramaṃ cāmavipakvatāṃ ca"},{"type":"verse","number":"118","sanskrit":"अथ प्रवाहिकाचिकित्सा बिल्वपेषी गुडं लोध्रं तैलं मरिचसंयुतम् लीढ्वा प्रवाहिकाऽक्रान्तः सत्वरं सुखमाप्नुयात्","text":"atha pravāhikācikitsā bilvapeṣī guḍaṃ lodhraṃ tailaṃ maricasaṃyutam līḍhvā pravāhikā'krāntaḥ satvaraṃ sukhamāpnuyāt"},{"type":"verse","number":"119","sanskrit":"धातकी बदरीपत्रं कपित्थं रसमाक्षिकम् सलोध्रमेकतो दध्ना पिबेन्निर्वाहिकाऽदितः","text":"dhātakī badarīpatraṃ kapitthaṃ rasamākṣikam salodhramekato dadhnā pibennirvāhikā'ditaḥ"},{"type":"verse","number":"120","sanskrit":"पक्कजाम्बवसङ्काशं यकृत्खण्डनिभं तनु घृततैलवसामज्जवेसवारपयोदधि","text":"pakkajāmbavasaṅkāśaṃ yakṛtkhaṇḍanibhaṃ tanu ghṛtatailavasāmajjavesavārapayodadhi"},{"type":"verse","number":"121","sanskrit":"मांसधावनतोयाभं कृष्णं नीलारुणप्रभम् कर्वुरं मेचकं स्निग्धं चन्द्र कोपगतं घनम्","text":"māṃsadhāvanatoyābhaṃ kṛṣṇaṃ nīlāruṇaprabham karvuraṃ mecakaṃ snigdhaṃ candra kopagataṃ ghanam"},{"type":"verse","number":"122","sanskrit":"कुणपं मस्तुलुङ्गाभं सगन्धं कुथितं बहु तृष्णादाहारुचिश्वासहिक्वापार्श्वास्थिशूलिनम्","text":"kuṇapaṃ mastuluṅgābhaṃ sagandhaṃ kuthitaṃ bahu tṛṣṇādāhāruciśvāsahikvāpārśvāsthiśūlinam"},{"type":"verse","number":"123","sanskrit":"संमूर्च्छाऽरतिसंमोहयुक्तं पक्ववलीगुदम् प्रलापयुक्तञ्च भिषग्वर्जयेदतिसारिणम्","text":"saṃmūrcchā'ratisaṃmohayuktaṃ pakvavalīgudam pralāpayuktañca bhiṣagvarjayedatisāriṇam"},{"type":"verse","number":"124","sanskrit":"असंवृतगुदं क्षीणं शूलाध्मानैरुपद्रुतम् गुदे पक्वे गतोष्माणमतिसारिणमुत्सृजेत्","text":"asaṃvṛtagudaṃ kṣīṇaṃ śūlādhmānairupadrutam gude pakve gatoṣmāṇamatisāriṇamutsṛjet"},{"type":"verse","number":"125","sanskrit":"श्वासशूलपिपासाऽत्त क्षीणंज्वरनिपीडितम् विशेषेण नरं वृद्धमतिसारो विनाशयेत्","text":"śvāsaśūlapipāsā'tta kṣīṇaṃjvaranipīḍitam viśeṣeṇa naraṃ vṛddhamatisāro vināśayet"},{"type":"verse","number":"126","sanskrit":"शोथं शूलं ज्वरं तृष्णां श्वासं कासमरोचकम् छर्दिं मूर्च्छां च हिक्काञ्च दृष्ट्वाऽतीसारिणं त्यजेत्","text":"śothaṃ śūlaṃ jvaraṃ tṛṣṇāṃ śvāsaṃ kāsamarocakam chardiṃ mūrcchāṃ ca hikkāñca dṛṣṭvā'tīsāriṇaṃ tyajet"},{"type":"verse","number":"127","sanskrit":"हस्तपादाङ्गुलीसन्धिप्रपाको मूत्रनिग्रहः पुरीषस्योष्णताऽतीव मरणायातिसारिणः","text":"hastapādāṅgulīsandhiprapāko mūtranigrahaḥ purīṣasyoṣṇatā'tīva maraṇāyātisāriṇaḥ"},{"type":"verse","number":"128","sanskrit":"अतिसारी राजरोगी ग्रहणीरोगवानपि मांसाग्निबलहीनो यो दुर्लभं तस्य जीवनम्","text":"atisārī rājarogī grahaṇīrogavānapi māṃsāgnibalahīno yo durlabhaṃ tasya jīvanam"},{"type":"verse","number":"129","sanskrit":"बाले वृद्धे त्वसाध्योऽय लिङ्गैरेतैरुपद्रुतः अपि यूनामसाध्यं स्यादतिदुष्टेपु धातुषु","text":"bāle vṛddhe tvasādhyo'ya liṅgairetairupadrutaḥ api yūnāmasādhyaṃ syādatiduṣṭepu dhātuṣu"},{"type":"verse","number":"130","sanskrit":"यस्योच्चारं विना मूत्रं सम्यग्वायुश्च गच्छति दीप्ताग्नेर्लघुकोष्ठस्य स्थितस्तस्योदरामयः","text":"yasyoccāraṃ vinā mūtraṃ samyagvāyuśca gacchati dīptāgnerlaghukoṣṭhasya sthitastasyodarāmayaḥ"},{"type":"verse","number":"131","sanskrit":"स्नानावगहावभ्यङ्गं गुरुस्निग्धादिभोजनम् व्यायाममग्निसन्तापमतिसारी विवर्जयेत्","text":"snānāvagahāvabhyaṅgaṃ gurusnigdhādibhojanam vyāyāmamagnisantāpamatisārī vivarjayet"},{"type":"verse","number":"132","sanskrit":"प्रत्येकं दश गद्याणाः शुद्धसूतकगन्धयोः विंशतिस्त्रिदिनं खल्वे पिष्ट्वा तां कज्जलद्यं त्र्यहम्","text":"pratyekaṃ daśa gadyāṇāḥ śuddhasūtakagandhayoḥ viṃśatistridinaṃ khalve piṣṭvā tāṃ kajjaladyaṃ tryaham"},{"type":"verse","number":"133","sanskrit":"ततो वज्रस्य दुग्धेन पिष्ट्वा तां कज्जलद्यं त्र्यहम् आर्द्र कं चित्रकं श्वेतं निःसहायञ्च मर्दयेत्","text":"tato vajrasya dugdhena piṣṭvā tāṃ kajjaladyaṃ tryaham ārdra kaṃ citrakaṃ śvetaṃ niḥsahāyañca mardayet"},{"type":"verse","number":"134","sanskrit":"पेषयेत्तद्र सैरेवं कज्जलद्यं तां दिनत्रयम् पीतानाञ्च कपर्दीनां चूर्णं गद्याणविंशतिः","text":"peṣayettadra sairevaṃ kajjaladyaṃ tāṃ dinatrayam pītānāñca kapardīnāṃ cūrṇaṃ gadyāṇaviṃśatiḥ"},{"type":"verse","number":"135","sanskrit":"विशतिः शङ्खचूर्णस्य चत्वारिंशच्च मिश्रितम् त्रिदिनं मर्दयेत्खल्वे पूर्वोक्तेन क्रमेण च","text":"viśatiḥ śaṅkhacūrṇasya catvāriṃśacca miśritam tridinaṃ mardayetkhalve pūrvoktena krameṇa ca"},{"type":"verse","number":"136","sanskrit":"त्र्यहमर्कस्य दुग्धेन वज्रीदुग्धेन च त्र्यहम् तन्मध्ये कज्जलद्यं क्षिप्त्वा चित्रकार्द्र रसेन तु","text":"tryahamarkasya dugdhena vajrīdugdhena ca tryaham tanmadhye kajjaladyaṃ kṣiptvā citrakārdra rasena tu"},{"type":"verse","number":"137","sanskrit":"खल्वे पिष्ट्वा द्वयोः कार्या गुट्यो बदरसम्मिताः लिप्त्वा दग्ध्वाऽशु चूर्णेन पक्वकुह्लरिकांतरम्","text":"khalve piṣṭvā dvayoḥ kāryā guṭyo badarasammitāḥ liptvā dagdhvā'śu cūrṇena pakvakuhlarikāṃtaram"},{"type":"verse","number":"138","sanskrit":"प्रक्षिप्य गुटिकास्तत्र चूर्णलिप्तपिधानकम् दत्त्वा वस्त्रं मृदा लिप्त्वा गर्त्तं हस्तप्रमाणकम्","text":"prakṣipya guṭikāstatra cūrṇaliptapidhānakam dattvā vastraṃ mṛdā liptvā garttaṃ hastapramāṇakam"},{"type":"verse","number":"139","sanskrit":"तद्गर्भे कुह्लरीं मुक्त्वा पुटो देयश्च शाणकैः पश्चाच्चित्रकनीरेण स्वाङ्गशीतञ्च पेषयेत्","text":"tadgarbhe kuhlarīṃ muktvā puṭo deyaśca śāṇakaiḥ paścāccitrakanīreṇa svāṅgaśītañca peṣayet"},{"type":"verse","number":"140","sanskrit":"गुटिकां पूर्वरीत्यैव कृत्वा देयः पुनः पुटः दग्धानां गुटिकानाञ्च चूर्णं कृत्वाऽथ कूपके","text":"guṭikāṃ pūrvarītyaiva kṛtvā deyaḥ punaḥ puṭaḥ dagdhānāṃ guṭikānāñca cūrṇaṃ kṛtvā'tha kūpake"},{"type":"verse","number":"141","sanskrit":"क्षेप्यं चैव हि निष्पन्नो रसोऽय शङ्खपोटली आमज्वरातिसारे च श्वासे कासे तथैव च","text":"kṣepyaṃ caiva hi niṣpanno raso'ya śaṅkhapoṭalī āmajvarātisāre ca śvāse kāse tathaiva ca"},{"type":"verse","number":"142","sanskrit":"श्लेष्मपित्तामवातेषु मन्दाग्नौ ग्रहणीषु च अष्टादशप्रमेहेषु जीर्णे जीर्णबलेषु च","text":"śleṣmapittāmavāteṣu mandāgnau grahaṇīṣu ca aṣṭādaśaprameheṣu jīrṇe jīrṇabaleṣu ca"},{"type":"verse","number":"143","sanskrit":"द्बात्रिंशन्मरिचैः साकं सघृतं वल्लपञ्चकम् सर्वरोगेषु दातव्यं मरिचाज्यं विना ज्वरे","text":"dbātriṃśanmaricaiḥ sākaṃ saghṛtaṃ vallapañcakam sarvarogeṣu dātavyaṃ maricājyaṃ vinā jvare"},{"type":"verse","number":"144","sanskrit":"शालयो दधि दुग्धादि भोजनं मधुरं हितम् कट्वम्लक्षारतैलाद्यान्दूरतः परिवर्जयेत्","text":"śālayo dadhi dugdhādi bhojanaṃ madhuraṃ hitam kaṭvamlakṣāratailādyāndūrataḥ parivarjayet"},{"type":"verse","number":"145","sanskrit":"विधिनाऽनेनकर्त्तव्यो रसोऽसौ शङ्खपोटली क्रमेण विनिवर्त्तन्ते प्रोक्तरोगा न संशयः","text":"vidhinā'nenakarttavyo raso'sau śaṅkhapoṭalī krameṇa vinivarttante proktarogā na saṃśayaḥ"},{"type":"verse","number":"146","sanskrit":"त्रैलोक्यविजयाजातीफले तुल्ये कलिङ्गकम् गृहीत्वा द्विगुणं श्रेष्ठो लेहः सर्वातिसारनुत्","text":"trailokyavijayājātīphale tulye kaliṅgakam gṛhītvā dviguṇaṃ śreṣṭho lehaḥ sarvātisāranut"},{"type":"verse","number":"147","sanskrit":"बिल्वमोचरसलोध्रधातकीपुष्पचूतफलबीजसंयुता नाशयेदतिविषाऽवलेहिका सिन्धुवेगमपि दुर्धरं ध्रुवम्","text":"bilvamocarasalodhradhātakīpuṣpacūtaphalabījasaṃyutā nāśayedativiṣā'valehikā sindhuvegamapi durdharaṃ dhruvam"},{"type":"verse","number":"148","sanskrit":"इति द्वितीयोऽतीसाराधिकारः समाप्तः २","text":"iti dvitīyo'tīsārādhikāraḥ samāptaḥ 2"}]},{"sthana":"Уттаракханда","number":3,"lang":"sa","content":[{"type":"heading","heading":"Джвара-атисара — лихорадка с диареей"},{"type":"verse","number":"1","sanskrit":"ज्वरातिसारयोरुक्तं निदानं यत्पृथक्पृथक् तस्माज्ज्वरातिसारस्य निदानं नोदितं पुनः","text":"jvarātisārayoruktaṃ nidānaṃ yatpṛthakpṛthak tasmājjvarātisārasya nidānaṃ noditaṃ punaḥ"},{"type":"verse","number":"2","sanskrit":"ज्वरातिसारयोरुक्तं भेषजं यत्पृथक्पृथक् न तन्मिलितयोः कार्यमन्योऽन्य वर्धयेद्यतः","text":"jvarātisārayoruktaṃ bheṣajaṃ yatpṛthakpṛthak na tanmilitayoḥ kāryamanyo'nya vardhayedyataḥ"},{"type":"verse","number":"3","sanskrit":"अतस्तौ प्रतिकुर्वीत विशेषोक्तचिकित्सितैः","text":"atastau pratikurvīta viśeṣoktacikitsitaiḥ"},{"type":"verse","number":"4","sanskrit":"लङ्घनमेकं मुक्त्वा न चान्यदस्तीह भेषजंबलिनः समुदीर्णदोषनिचयं तत्पाचयेत्तथा शमयेत्","text":"laṅghanamekaṃ muktvā na cānyadastīha bheṣajaṃbalinaḥ samudīrṇadoṣanicayaṃ tatpācayettathā śamayet"},{"type":"verse","number":"5","sanskrit":"लङ्घनमुभयोरुक्तं मिलिते कार्यं विशेषतस्तदनु उत्पलषष्ठकसिद्धं लाजामण्डादिकं सकलम्","text":"laṅghanamubhayoruktaṃ milite kāryaṃ viśeṣatastadanu utpalaṣaṣṭhakasiddhaṃ lājāmaṇḍādikaṃ sakalam"},{"type":"verse","number":"6","sanskrit":"पृश्निपर्णीबला बिल्वधनिकानागरोत्पलैः ज्वरातिसारयोर्वाऽपि पिबेत्साम्लं शृतं नरः","text":"pṛśniparṇībalā bilvadhanikānāgarotpalaiḥ jvarātisārayorvā'pi pibetsāmlaṃ śṛtaṃ naraḥ"},{"type":"verse","number":"7","sanskrit":"कणाकरिकणालाजक्वाथो मधुसितायुतः पीतो ज्वरातिसारस्य तृष्णामाशु विनाशयेत्","text":"kaṇākarikaṇālājakvātho madhusitāyutaḥ pīto jvarātisārasya tṛṣṇāmāśu vināśayet"},{"type":"verse","number":"8","sanskrit":"नागरातिविषामुस्ताऽमृताभूनिम्बवत्सकैः क्वाथः सर्वज्वरान्हन्ति चातिसारं सुदारुणम्","text":"nāgarātiviṣāmustā'mṛtābhūnimbavatsakaiḥ kvāthaḥ sarvajvarānhanti cātisāraṃ sudāruṇam"},{"type":"verse","number":"9","sanskrit":"गुडूच्यतिविषाधान्यशुण्ठीबिल्वाब्दबालकैः पाठाभूनिम्बकुटजचन्दनोशीरपर्पटैः","text":"guḍūcyativiṣādhānyaśuṇṭhībilvābdabālakaiḥ pāṭhābhūnimbakuṭajacandanośīraparpaṭaiḥ"},{"type":"verse","number":"10","sanskrit":"पिबेत्कषायं सक्षौद्रं ज्वरातीसारनाशनम् हृल्लासारुचितृड्दाहवमीनाञ्च निवृत्तये","text":"pibetkaṣāyaṃ sakṣaudraṃ jvarātīsāranāśanam hṛllāsārucitṛḍdāhavamīnāñca nivṛttaye"},{"type":"verse","number":"11","sanskrit":"उत्पलं दाडिमत्वक्च पद्मकेशरमेव च पीतं तण्डुलतोयेन ज्वरातीसारनाशनम्","text":"utpalaṃ dāḍimatvakca padmakeśarameva ca pītaṃ taṇḍulatoyena jvarātīsāranāśanam"},{"type":"verse","number":"12","sanskrit":"बिल्वबालकभूनिम्बगुडूचीमुस्तवत्सकैः कषायःपाचनःशोथज्वरातीसारनाशनः","text":"bilvabālakabhūnimbaguḍūcīmustavatsakaiḥ kaṣāyaḥpācanaḥśothajvarātīsāranāśanaḥ"},{"type":"verse","number":"13","sanskrit":"नागरातिविषाबिल्वगुडूचीमुस्तवत्सकैः कषायः पाचनः शोथज्वरातीसारनाशनः","text":"nāgarātiviṣābilvaguḍūcīmustavatsakaiḥ kaṣāyaḥ pācanaḥ śothajvarātīsāranāśanaḥ"},{"type":"verse","number":"14","sanskrit":"दशमूलीकषायेण विश्वमक्षसमां पिबेत् ज्वरे चैवातिसारे च सशोथे ग्रहणी गदे","text":"daśamūlīkaṣāyeṇa viśvamakṣasamāṃ pibet jvare caivātisāre ca saśothe grahaṇī gade"},{"type":"verse","number":"15","sanskrit":"इति तृतीयाज्वरातिसारः समाप्तः ३","text":"iti tṛtīyājvarātisāraḥ samāptaḥ 3"}]},{"sthana":"Уттаракханда","number":4,"lang":"sa","content":[{"type":"heading","heading":"Грахани — нарушение пищеварения"},{"type":"verse","number":"1","sanskrit":"अतिसारे निवृत्तेऽपि मन्दाग्नेरहिताशिनः भूयः सन्दूषितो वह्निर्ग्रहणीमपि दूषयेत्","text":"atisāre nivṛtte'pi mandāgnerahitāśinaḥ bhūyaḥ sandūṣito vahnirgrahaṇīmapi dūṣayet"},{"type":"verse","number":"2","sanskrit":"अग्न्यधिष्ठानमन्नस्य ग्रहणाद् ग्रहणी मता अपक्वं धारयत्यन्नं पक्वं त्यजति चाप्यधः","text":"agnyadhiṣṭhānamannasya grahaṇād grahaṇī matā apakvaṃ dhārayatyannaṃ pakvaṃ tyajati cāpyadhaḥ"},{"type":"verse","number":"3","sanskrit":"षष्ठी पित्तधरा नाम या कला परिकीर्त्तिता आमपक्वाशयान्तःस्था ग्रहणी साऽभिधीयते","text":"ṣaṣṭhī pittadharā nāma yā kalā parikīrttitā āmapakvāśayāntaḥsthā grahaṇī sā'bhidhīyate"},{"type":"verse","number":"4","sanskrit":"ग्रहण्या बलमग्निर्हि स चापि ग्रहणीबलः तस्मादग्नौ प्रदुष्टे तु ग्रहण्यपि विदुष्यति तस्मात्कार्यः परीहारो ह्यतिसारे विरिक्तवत्","text":"grahaṇyā balamagnirhi sa cāpi grahaṇībalaḥ tasmādagnau praduṣṭe tu grahaṇyapi viduṣyati tasmātkāryaḥ parīhāro hyatisāre viriktavat"},{"type":"verse","number":"5","sanskrit":"एकैकशः सर्वशश्च दोषैरत्यन्तमूर्च्छितैः सा दुष्टा बहुशो भुक्तमाममेव विमुञ्चति","text":"ekaikaśaḥ sarvaśaśca doṣairatyantamūrcchitaiḥ sā duṣṭā bahuśo bhuktamāmameva vimuñcati"},{"type":"verse","number":"6","sanskrit":"पक्वं वा सरुजं पूति मुहुर्बद्धं मुहुर्द्र वम् ग्रहणीरोगमाहुस्तमायुर्वेदविदो जनाः","text":"pakvaṃ vā sarujaṃ pūti muhurbaddhaṃ muhurdra vam grahaṇīrogamāhustamāyurvedavido janāḥ"},{"type":"verse","number":"7","sanskrit":"कटुतिक्तकषायाति रुक्षशीतलभोजनैः प्रमितानशनात्यध्यवेग निग्रहमैथुनैः","text":"kaṭutiktakaṣāyāti rukṣaśītalabhojanaiḥ pramitānaśanātyadhyavega nigrahamaithunaiḥ"},{"type":"verse","number":"8","sanskrit":"मारुतः कुपितो वह्विं संछाद्य कुरुते गदम् तस्यान्नं पच्यते दुःखं शुक्तपाकं खराङ्गता","text":"mārutaḥ kupito vahviṃ saṃchādya kurute gadam tasyānnaṃ pacyate duḥkhaṃ śuktapākaṃ kharāṅgatā"},{"type":"verse","number":"9","sanskrit":"कण्ठास्यशोषः क्षुत्तृष्णा तिमिरं कर्णयोः स्वनः पार्श्वोरुवङ्क्षणग्रीवारुगभीक्ष्णं विसूचिका","text":"kaṇṭhāsyaśoṣaḥ kṣuttṛṣṇā timiraṃ karṇayoḥ svanaḥ pārśvoruvaṅkṣaṇagrīvārugabhīkṣṇaṃ visūcikā"},{"type":"verse","number":"10","sanskrit":"हृत्पीडाकार्श्यदौर्बल्यं वैरस्यं परिकर्त्तिका गृद्धिः सर्वरसानाञ्च मनसः सदनं तथा","text":"hṛtpīḍākārśyadaurbalyaṃ vairasyaṃ parikarttikā gṛddhiḥ sarvarasānāñca manasaḥ sadanaṃ tathā"},{"type":"verse","number":"11","sanskrit":"जीर्णेजीर्यति चाध्मानं भुक्ते स्वास्थ्यमुपैति च स वातगुल्महृद्रो गप्लीहाशङ्की च मानवः","text":"jīrṇejīryati cādhmānaṃ bhukte svāsthyamupaiti ca sa vātagulmahṛdro gaplīhāśaṅkī ca mānavaḥ"},{"type":"verse","number":"12","sanskrit":"चिराद् दुःखं द्र्रवं शुष्कं तन्वामं शब्दफेनवत् पुनः पुनः सृजेद्वर्चः कासश्वासार्दितोऽनिलात्","text":"cirād duḥkhaṃ drravaṃ śuṣkaṃ tanvāmaṃ śabdaphenavat punaḥ punaḥ sṛjedvarcaḥ kāsaśvāsārdito'nilāt"},{"type":"verse","number":"13","sanskrit":"कटुतिक्तविदाह्यम्लक्षाराद्यैः पित्तमुल्वणम् आप्लावयद्धन्त्यनलं जलं तप्तमिवानलम्","text":"kaṭutiktavidāhyamlakṣārādyaiḥ pittamulvaṇam āplāvayaddhantyanalaṃ jalaṃ taptamivānalam"},{"type":"verse","number":"14","sanskrit":"सोऽजीर्णं पीतनीलाभं पीताभः सार्यते द्र वम् अत्यम्लोद्गारहृत्कण्ठदाहारुचितृषाऽदितः","text":"so'jīrṇaṃ pītanīlābhaṃ pītābhaḥ sāryate dra vam atyamlodgārahṛtkaṇṭhadāhārucitṛṣā'ditaḥ"},{"type":"verse","number":"15","sanskrit":"गुर्वतिस्निग्धशीतादि भोजनादतिभोजनात् भुक्तमात्रस्य च स्वप्नाद्धन्त्यग्निं कुपितःकफः","text":"gurvatisnigdhaśītādi bhojanādatibhojanāt bhuktamātrasya ca svapnāddhantyagniṃ kupitaḥkaphaḥ"},{"type":"verse","number":"16","sanskrit":"तस्यान्नं पच्यते दुःखं हृल्लासच्छर्द्यरोचकाः आस्योपदेहमाधुर्यकासष्ठी वनपीनसाः","text":"tasyānnaṃ pacyate duḥkhaṃ hṛllāsacchardyarocakāḥ āsyopadehamādhuryakāsaṣṭhī vanapīnasāḥ"},{"type":"verse","number":"17","sanskrit":"हृदयं मन्यते स्तब्धमुदरं स्तिमितं गुरु दुष्टो मधुर उद्गारः सदनं स्त्रीष्वहर्षणम्","text":"hṛdayaṃ manyate stabdhamudaraṃ stimitaṃ guru duṣṭo madhura udgāraḥ sadanaṃ strīṣvaharṣaṇam"},{"type":"verse","number":"18","sanskrit":"भिन्नामश्लेष्मसंश्लिष्टगुरुवर्चः प्रवर्त्तनम् अकृशस्यापि दौर्बल्यमालस्यञ्च कफात्मके","text":"bhinnāmaśleṣmasaṃśliṣṭaguruvarcaḥ pravarttanam akṛśasyāpi daurbalyamālasyañca kaphātmake"},{"type":"verse","number":"19","sanskrit":"पृथग्वातादिनिर्दिष्टहेतु लिङ्गसमागमे त्रिदोषं निर्दिशेदेवं तेषां वक्ष्यामि भेषजम्","text":"pṛthagvātādinirdiṣṭahetu liṅgasamāgame tridoṣaṃ nirdiśedevaṃ teṣāṃ vakṣyāmi bheṣajam"},{"type":"verse","number":"20","sanskrit":"द्र वं घनं सितं स्निग्धं सकटीवेदनं शकृत् आमं बहु सपैच्छिल्यं सशब्दं मन्दवेदनम्","text":"dra vaṃ ghanaṃ sitaṃ snigdhaṃ sakaṭīvedanaṃ śakṛt āmaṃ bahu sapaicchilyaṃ saśabdaṃ mandavedanam"},{"type":"verse","number":"21","sanskrit":"पक्षान्मासाद्दशाहाद्वा नित्यञ्चापि विमुञ्चति अन्त्रकूजनमालस्यं दौर्बल्यं सदनं भवेत्","text":"pakṣānmāsāddaśāhādvā nityañcāpi vimuñcati antrakūjanamālasyaṃ daurbalyaṃ sadanaṃ bhavet"},{"type":"verse","number":"22","sanskrit":"दिवा प्रकोपो भवति रात्रौ शान्तिं च गच्छति दुर्विज्ञेया दुर्निवारा चिरकालानुबन्धिनी","text":"divā prakopo bhavati rātrau śāntiṃ ca gacchati durvijñeyā durnivārā cirakālānubandhinī"},{"type":"verse","number":"23","sanskrit":"सा भवेदामवातेन सङ्ग्रहग्रहणी मता","text":"sā bhavedāmavātena saṅgrahagrahaṇī matā"},{"type":"verse","number":"24","sanskrit":"प्रसुप्तिः पार्श्वयोःशूलं तथा जलघटीध्वनिः तं वदन्ति घटीयन्त्रमसाध्यं ग्रहणीगदम्","text":"prasuptiḥ pārśvayoḥśūlaṃ tathā jalaghaṭīdhvaniḥ taṃ vadanti ghaṭīyantramasādhyaṃ grahaṇīgadam"},{"type":"verse","number":"25","sanskrit":"ग्रहणीमाश्रितं रोगमजीर्णवदुपाचरेत् लङ्घनैर्दीपनीयैश्च सदाऽतीसारभेषजैः","text":"grahaṇīmāśritaṃ rogamajīrṇavadupācaret laṅghanairdīpanīyaiśca sadā'tīsārabheṣajaiḥ"},{"type":"verse","number":"26","sanskrit":"दोषं सामं निरामञ्च विद्यादत्रातिसारवत् अतिसारोक्तविधिना तस्यामञ्च विपाचयेत्","text":"doṣaṃ sāmaṃ nirāmañca vidyādatrātisāravat atisāroktavidhinā tasyāmañca vipācayet"},{"type":"verse","number":"27","sanskrit":"पेयाऽदि पटु लघ्वन्नं पञ्चकोलादिभिर्युतम् दीपनानि च तक्रं च ग्रहण्यां योजयेद्भिषक्","text":"peyā'di paṭu laghvannaṃ pañcakolādibhiryutam dīpanāni ca takraṃ ca grahaṇyāṃ yojayedbhiṣak"},{"type":"verse","number":"28","sanskrit":"कपित्थबिल्वचाङ्गेरीत क्रदाडिमसाधिता यवागूः पाचयत्यामं शकृत्संवर्त्तयत्यपि","text":"kapitthabilvacāṅgerīta kradāḍimasādhitā yavāgūḥ pācayatyāmaṃ śakṛtsaṃvarttayatyapi"},{"type":"verse","number":"29","sanskrit":"गव्यं दध्युत्तमं बल्यं पाके स्वादु रुचिप्रदम् पवित्रं दीपनं स्निग्धं पुष्टिकृत्पवनापहम् उक्तं दध्नामशेषाणां मध्ये गव्यं गुणाधिकम्","text":"gavyaṃ dadhyuttamaṃ balyaṃ pāke svādu rucipradam pavitraṃ dīpanaṃ snigdhaṃ puṣṭikṛtpavanāpaham uktaṃ dadhnāmaśeṣāṇāṃ madhye gavyaṃ guṇādhikam"},{"type":"verse","number":"30","sanskrit":"माहिषं दधि सुस्निग्धं श्लेष्मलं वातपित्तनुत् स्वादुपाकमभिष्यन्दि वृष्यं गुर्वस्रदूषणम्","text":"māhiṣaṃ dadhi susnigdhaṃ śleṣmalaṃ vātapittanut svādupākamabhiṣyandi vṛṣyaṃ gurvasradūṣaṇam"},{"type":"verse","number":"31","sanskrit":"आजं दध्युत्तमं ग्राहि लघु दोषत्रयापहम् शस्यते श्वासकासार्शःक्षयकार्श्येषु दीपनम्","text":"ājaṃ dadhyuttamaṃ grāhi laghu doṣatrayāpaham śasyate śvāsakāsārśaḥkṣayakārśyeṣu dīpanam"},{"type":"verse","number":"32","sanskrit":"तक्रन्तु घोलं मथितोदश्वित्तक्रप्रभेदतः सुश्रुताद्यैर्मुनिश्रेष्ठैश्चतुर्द्धा परिकीर्त्तितम्","text":"takrantu gholaṃ mathitodaśvittakraprabhedataḥ suśrutādyairmuniśreṣṭhaiścaturddhā parikīrttitam"},{"type":"verse","number":"33","sanskrit":"ससरं निर्जलं घोलं मथितं त्वसरोदकम् तक्रं पादजलं प्रोक्तमुदश्विच्चार्द्धवारिकम्","text":"sasaraṃ nirjalaṃ gholaṃ mathitaṃ tvasarodakam takraṃ pādajalaṃ proktamudaśviccārddhavārikam"},{"type":"verse","number":"34","sanskrit":"वातपित्तहरं घोलं मथितं कफपित्तनुत् उदश्वित्कफदं बल्यं श्रमघ्नं परमं मतम्","text":"vātapittaharaṃ gholaṃ mathitaṃ kaphapittanut udaśvitkaphadaṃ balyaṃ śramaghnaṃ paramaṃ matam"},{"type":"verse","number":"35","sanskrit":"तक्रं ग्राहि कषायाम्लं मधुरं दीपनं लघु वीर्योष्णं बलदं वृष्यं प्रीणनं वातनाशनम्","text":"takraṃ grāhi kaṣāyāmlaṃ madhuraṃ dīpanaṃ laghu vīryoṣṇaṃ baladaṃ vṛṣyaṃ prīṇanaṃ vātanāśanam"},{"type":"verse","number":"36","sanskrit":"यान्युक्तानि दधीन्यष्टौ तद्गुणं तक्रमादिशेत् ग्रहण्यादिमतां तक्रं पथ्यं संग्राहि लाघवात्","text":"yānyuktāni dadhīnyaṣṭau tadguṇaṃ takramādiśet grahaṇyādimatāṃ takraṃ pathyaṃ saṃgrāhi lāghavāt"},{"type":"verse","number":"37","sanskrit":"वातघ्नमम्लसान्द्र त्वात्सद्यस्कं त्वविदाहि च किञ्च स्वादुविपाकं च अन्ते पित्तप्रकोपणम्","text":"vātaghnamamlasāndra tvātsadyaskaṃ tvavidāhi ca kiñca svāduvipākaṃ ca ante pittaprakopaṇam"},{"type":"verse","number":"38","sanskrit":"कषायोष्णविकासित्वाद्रौ क्ष्याच्चैव कफे हितम्","text":"kaṣāyoṣṇavikāsitvādrau kṣyāccaiva kaphe hitam"},{"type":"verse","number":"39","sanskrit":"समुद्धृतघृतं तक्रं पथ्यं लघु विशेषतः स्तोकोद्धृतघृतं तस्माद् गुरु वृप्यं कफावहम् अनुद्धृतघृतं सान्द्रं गुरु पुष्टिवलप्रदम्","text":"samuddhṛtaghṛtaṃ takraṃ pathyaṃ laghu viśeṣataḥ stokoddhṛtaghṛtaṃ tasmād guru vṛpyaṃ kaphāvaham anuddhṛtaghṛtaṃ sāndraṃ guru puṣṭivalapradam"},{"type":"verse","number":"40","sanskrit":"वातेऽम्ल सैन्धवोपेतं पित्ते स्वादु सशर्करम् पिबेत्तक्रं कफे चापि क्षारत्रिकटुसंयुतम्","text":"vāte'mla saindhavopetaṃ pitte svādu saśarkaram pibettakraṃ kaphe cāpi kṣāratrikaṭusaṃyutam"},{"type":"verse","number":"41","sanskrit":"हिङ्गुजीरयुतं घोलं सैन्धवेनावधूलितम् ग्रहण्यर्शोऽतिसारघ्नं भवेद्वातहरं परम्","text":"hiṅgujīrayutaṃ gholaṃ saindhavenāvadhūlitam grahaṇyarśo'tisāraghnaṃ bhavedvātaharaṃ param"},{"type":"verse","number":"42","sanskrit":"रोचनं पुष्टिदं बल्यं बस्तिशूलविनाशनम्","text":"rocanaṃ puṣṭidaṃ balyaṃ bastiśūlavināśanam"},{"type":"verse","number":"43","sanskrit":"तक्रमामं कफं कोष्ठे हन्ति कण्ठे करोति च पीनसश्वासकासादौ पक्वमेव विशिष्यते","text":"takramāmaṃ kaphaṃ koṣṭhe hanti kaṇṭhe karoti ca pīnasaśvāsakāsādau pakvameva viśiṣyate"},{"type":"verse","number":"44","sanskrit":"नैव तक्रं क्षते दद्यान्नोष्णकाले न दुर्बले न मूर्च्छाभ्रमदाहेषु न रोगे रक्तपैत्तिके","text":"naiva takraṃ kṣate dadyānnoṣṇakāle na durbale na mūrcchābhramadāheṣu na roge raktapaittike"},{"type":"verse","number":"45","sanskrit":"न तक्रसेवी व्यथते कदाचिन्न तक्रदग्धाः प्रभवन्ति रोगाः यथा सुराणाममृतं सुखाय तथा नराणां भुवि तक्रमाहुः","text":"na takrasevī vyathate kadācinna takradagdhāḥ prabhavanti rogāḥ yathā surāṇāmamṛtaṃ sukhāya tathā narāṇāṃ bhuvi takramāhuḥ"},{"type":"verse","number":"46","sanskrit":"मुद्गयूषं रसं तक्रंधान्यजीरकसंयुतम् सैन्धवेनान्वितं दद्यात्षड्यूषणमितीरितम्","text":"mudgayūṣaṃ rasaṃ takraṃdhānyajīrakasaṃyutam saindhavenānvitaṃ dadyātṣaḍyūṣaṇamitīritam"},{"type":"verse","number":"47","sanskrit":"कर्षं गन्धकमर्द्धपारदमुभे कुर्याच्छुभां कज्जलद्यं द्व्यक्षं त्र्यूषणतश्च पञ्चलवणं सार्द्धञ्च कर्षं पृथक् भृष्टं हिङ्गु च जीरकद्वययुतं सर्वार्द्धभङ्गाऽन्वितं खादेट्टङ्कमितं प्रवृत्तिगदवांस्तक्रेण बिल्वेन वा","text":"karṣaṃ gandhakamarddhapāradamubhe kuryācchubhāṃ kajjaladyaṃ dvyakṣaṃ tryūṣaṇataśca pañcalavaṇaṃ sārddhañca karṣaṃ pṛthak bhṛṣṭaṃ hiṅgu ca jīrakadvayayutaṃ sarvārddhabhaṅgā'nvitaṃ khādeṭṭaṅkamitaṃ pravṛttigadavāṃstakreṇa bilvena vā"},{"type":"verse","number":"48","sanskrit":"जातीफललवङ्गैला पत्रत्वङ्नागकेशरैः कर्पूरचन्दनतिलत्वक्क्षीरीतगरामलैः","text":"jātīphalalavaṅgailā patratvaṅnāgakeśaraiḥ karpūracandanatilatvakkṣīrītagarāmalaiḥ"},{"type":"verse","number":"49","sanskrit":"तालीसपिप्लीपथ्यास्थूलजीरकचित्रकैः शुण्ठीविडङ्गमरिचैः समभागं विचूर्णितैः","text":"tālīsapiplīpathyāsthūlajīrakacitrakaiḥ śuṇṭhīviḍaṅgamaricaiḥ samabhāgaṃ vicūrṇitaiḥ"},{"type":"verse","number":"50","sanskrit":"यावन्त्येतानि सर्वाणि दद्याद्भङ्गाञ्च तावतीम् सर्वचूर्णसमं कृत्वा प्रदेया शुभ्रशर्करा","text":"yāvantyetāni sarvāṇi dadyādbhaṅgāñca tāvatīm sarvacūrṇasamaṃ kṛtvā pradeyā śubhraśarkarā"},{"type":"verse","number":"51","sanskrit":"कर्षमात्रमिदं खादेन्मधुना प्लावितं जनः नाशयेद ग्रहणीं कासं क्षयकासमरोचकम्","text":"karṣamātramidaṃ khādenmadhunā plāvitaṃ janaḥ nāśayeda grahaṇīṃ kāsaṃ kṣayakāsamarocakam"},{"type":"verse","number":"52","sanskrit":"चित्रकं पिप्पलीमूलं क्षारो लवणपञ्चकम् व्योषं हिङ्ग्वजमोदा च चव्यं चैकत्र चूर्णयेत्","text":"citrakaṃ pippalīmūlaṃ kṣāro lavaṇapañcakam vyoṣaṃ hiṅgvajamodā ca cavyaṃ caikatra cūrṇayet"},{"type":"verse","number":"53","sanskrit":"वटिका मातुलुङ्गस्य रसैर्वा दाडिमस्य च कृता विपाचयत्यामं दीपयत्याशु चानलम्","text":"vaṭikā mātuluṅgasya rasairvā dāḍimasya ca kṛtā vipācayatyāmaṃ dīpayatyāśu cānalam"},{"type":"verse","number":"54","sanskrit":"श्रीफलशलाटुमज्जा नागरचूर्णेन मिश्रितः सगुडः ग्रहणीगदमत्युग्रं तक्रभुजा शीलितो जयति","text":"śrīphalaśalāṭumajjā nāgaracūrṇena miśritaḥ saguḍaḥ grahaṇīgadamatyugraṃ takrabhujā śīlito jayati"},{"type":"verse","number":"55","sanskrit":"चतुष्पलं सुधाकाण्डं त्रिपलं लवणत्रयम् वार्ताकोः कुडवं चार्कमूलाद्बिल्वं तथाऽनलात्","text":"catuṣpalaṃ sudhākāṇḍaṃ tripalaṃ lavaṇatrayam vārtākoḥ kuḍavaṃ cārkamūlādbilvaṃ tathā'nalāt"},{"type":"verse","number":"56","sanskrit":"दग्ध्वा द्र्रवेण वार्त्ताकोर्गुटिका भोजनान्तरे भुक्ता भुक्तं पचत्याशु नाशयेद् ग्रहणीगदम् कासं श्वासं तथाऽशासि विसूचीञ्च हृदामयम्","text":"dagdhvā drraveṇa vārttākorguṭikā bhojanāntare bhuktā bhuktaṃ pacatyāśu nāśayed grahaṇīgadam kāsaṃ śvāsaṃ tathā'śāsi visūcīñca hṛdāmayam"},{"type":"verse","number":"57","sanskrit":"मुस्तकातिविषाबिल्वकौटजं सूक्ष्मचूर्णितम् मधुना च समालीढं ग्रहणीं सर्वजां जयेत्","text":"mustakātiviṣābilvakauṭajaṃ sūkṣmacūrṇitam madhunā ca samālīḍhaṃ grahaṇīṃ sarvajāṃ jayet"},{"type":"verse","number":"58","sanskrit":"श्वेतो वा यदि वा रक्तः सुपक्को ग्रहणीगदः गुडेनाधिकसर्जेन भक्षितेनाशु नश्यति","text":"śveto vā yadi vā raktaḥ supakko grahaṇīgadaḥ guḍenādhikasarjena bhakṣitenāśu naśyati"},{"type":"verse","number":"59","sanskrit":"बिल्वाब्दशक्रयवबालकमोचसिद्धमाजं पयः पिबति यो दिवसत्रयं ना सोऽतिप्रवृद्धचिरजं ग्रहणीविकारं सामं सशोणितमसाध्यमपि क्षिणोति","text":"bilvābdaśakrayavabālakamocasiddhamājaṃ payaḥ pibati yo divasatrayaṃ nā so'tipravṛddhacirajaṃ grahaṇīvikāraṃ sāmaṃ saśoṇitamasādhyamapi kṣiṇoti"},{"type":"verse","number":"60","sanskrit":"प्रस्थत्रयं त्वामलकीरसस्य शुद्धस्य दत्वाऽद्धतुलां गुडस्य चूर्णीकृतैर्ग्रन्थिकजीरचव्यव्योषैः सकृष्णाहपुषाऽजमोदैः","text":"prasthatrayaṃ tvāmalakīrasasya śuddhasya datvā'ddhatulāṃ guḍasya cūrṇīkṛtairgranthikajīracavyavyoṣaiḥ sakṛṣṇāhapuṣā'jamodaiḥ"},{"type":"verse","number":"61","sanskrit":"विडङ्गसिन्धुत्रिफलायवानीपाठाऽग्निधान्यैश्च पलप्रमाणैः दत्वा त्रिवृच्चूर्णपलानि चाष्टावष्टौ च तैलस्य पचेद्यथावत्","text":"viḍaṅgasindhutriphalāyavānīpāṭhā'gnidhānyaiśca palapramāṇaiḥ datvā trivṛccūrṇapalāni cāṣṭāvaṣṭau ca tailasya pacedyathāvat"},{"type":"verse","number":"62","sanskrit":"तं भक्षयेदक्षपलप्रमाणं यथेष्टचेष्टस्त्रिसुगन्धियुक्तम् अनेन सर्वे ग्रहणीविकाराः सश्वासकासस्वरभेदशोथाः","text":"taṃ bhakṣayedakṣapalapramāṇaṃ yatheṣṭaceṣṭastrisugandhiyuktam anena sarve grahaṇīvikārāḥ saśvāsakāsasvarabhedaśothāḥ"},{"type":"verse","number":"63","sanskrit":"शाम्यन्ति चायं चिरमन्तरग्नेर्हतस्य पुंस्त्क्वस्य च वृद्धिहेतुः स्त्रीणान्तु वन्ध्याऽमयनाशनः स्यात् कल्याणको नाम गुडः प्रसिद्धः","text":"śāmyanti cāyaṃ ciramantaragnerhatasya puṃstkvasya ca vṛddhihetuḥ strīṇāntu vandhyā'mayanāśanaḥ syāt kalyāṇako nāma guḍaḥ prasiddhaḥ"},{"type":"verse","number":"64","sanskrit":"तैले मनाक् त्रिवृद् भृष्ट्वा त्रिफलायाः पलत्रयम् सिद्धे निधेयमत्रैव गुडे कल्याणपूर्वके","text":"taile manāk trivṛd bhṛṣṭvā triphalāyāḥ palatrayam siddhe nidheyamatraiva guḍe kalyāṇapūrvake"},{"type":"verse","number":"65","sanskrit":"पिप्पली पिप्पलीमूलं चित्रकं गजपिप्पली धान्यकञ्च विडङ्गानि यवानी मरिचानि च","text":"pippalī pippalīmūlaṃ citrakaṃ gajapippalī dhānyakañca viḍaṅgāni yavānī maricāni ca"},{"type":"verse","number":"66","sanskrit":"त्रिफला चाजमोदा च नीलिनी जीरकस्तथा सैन्धवं रोमकञ्चापि सामुद्रं रुचकं विडम्","text":"triphalā cājamodā ca nīlinī jīrakastathā saindhavaṃ romakañcāpi sāmudraṃ rucakaṃ viḍam"},{"type":"verse","number":"67","sanskrit":"आरग्वधश्च त्वक्पत्रं सूक्ष्मैला चोपकुञ्जिका शुण्ठी शक्रयवाश्चैव प्रत्येकं कर्षसम्मिताः","text":"āragvadhaśca tvakpatraṃ sūkṣmailā copakuñjikā śuṇṭhī śakrayavāścaiva pratyekaṃ karṣasammitāḥ"},{"type":"verse","number":"68","sanskrit":"मृद्वीकायाः पलान्यत्र चत्वारि कथितानि हि त्रिवृतायाःपलान्यष्टौ गुडस्यार्द्धतुलां तथा","text":"mṛdvīkāyāḥ palānyatra catvāri kathitāni hi trivṛtāyāḥpalānyaṣṭau guḍasyārddhatulāṃ tathā"},{"type":"verse","number":"69","sanskrit":"तिलतैलपलान्यष्टावामलक्या रसस्य तु प्रस्थत्रयमिदं सर्वं शनैर्मृद्वग्निना पचेत्","text":"tilatailapalānyaṣṭāvāmalakyā rasasya tu prasthatrayamidaṃ sarvaṃ śanairmṛdvagninā pacet"},{"type":"verse","number":"70","sanskrit":"औदुम्बरं चामलकं बादरञ्च यथाबलम् तावन्मात्रमिदं खादेद् भक्षयेद्वा यथाऽनलम्","text":"audumbaraṃ cāmalakaṃ bādarañca yathābalam tāvanmātramidaṃ khāded bhakṣayedvā yathā'nalam"},{"type":"verse","number":"71","sanskrit":"निखिलान्ग्रहणीरोगान्प्रमेहांश्चैव विंशतिम् उरोघातं प्रतिश्यायं दौर्बल्यं वह्निसंक्षयम्","text":"nikhilāngrahaṇīrogānpramehāṃścaiva viṃśatim uroghātaṃ pratiśyāyaṃ daurbalyaṃ vahnisaṃkṣayam"},{"type":"verse","number":"72","sanskrit":"ज्वरानपि हरेत्सर्वान्कुर्यात्कान्तिं मतिं बलम् पाण्डुरोगाञ्जवाद्धन्ति रक्तपित्तञ्च विड्ग्रहम्","text":"jvarānapi haretsarvānkuryātkāntiṃ matiṃ balam pāṇḍurogāñjavāddhanti raktapittañca viḍgraham"},{"type":"verse","number":"73","sanskrit":"धातुक्षीणो वयः क्षीणः स्त्रीपु क्षीणः क्षयी च यः तेभ्योहितश्च वन्ध्यायै महाकल्याणको गुडः","text":"dhātukṣīṇo vayaḥ kṣīṇaḥ strīpu kṣīṇaḥ kṣayī ca yaḥ tebhyohitaśca vandhyāyai mahākalyāṇako guḍaḥ"},{"type":"verse","number":"74","sanskrit":"कूष्माण्डानां सुपक्वानां स्विन्नानां निष्कुलत्वचाम् सर्पिःप्रस्थं पलशतं ताम्रपात्रे शनैः पचेत्","text":"kūṣmāṇḍānāṃ supakvānāṃ svinnānāṃ niṣkulatvacām sarpiḥprasthaṃ palaśataṃ tāmrapātre śanaiḥ pacet"},{"type":"verse","number":"75","sanskrit":"पिप्पली पिप्पलीमूलं चित्रकं गजपिप्पली धान्यकानि विडङ्गानिनागरं मरिचानि च","text":"pippalī pippalīmūlaṃ citrakaṃ gajapippalī dhānyakāni viḍaṅgānināgaraṃ maricāni ca"},{"type":"verse","number":"76","sanskrit":"त्रिफला चाजमोदा च कलिङ्गाजाजिसैन्धवम् एकैकस्य पलञ्चैकं त्रिवृतोऽष्टौ पलानि च","text":"triphalā cājamodā ca kaliṅgājājisaindhavam ekaikasya palañcaikaṃ trivṛto'ṣṭau palāni ca"},{"type":"verse","number":"77","sanskrit":"तैलस्य च पलान्यष्टौ गुडात्पञ्चाशदेव तु आमलक्या रसस्यात्र प्रस्थत्रयमुदीरितम्","text":"tailasya ca palānyaṣṭau guḍātpañcāśadeva tu āmalakyā rasasyātra prasthatrayamudīritam"},{"type":"verse","number":"78","sanskrit":"तावत्पाकं प्रकुर्वीत मृदुना वह्निना भिषक् यावद्दर्व्याः प्रलेपः स्यात्तदैनमवतारयेत्","text":"tāvatpākaṃ prakurvīta mṛdunā vahninā bhiṣak yāvaddarvyāḥ pralepaḥ syāttadainamavatārayet"},{"type":"verse","number":"79","sanskrit":"औदुम्बरं चामलकं बादरं वा यथाबलम् तावन्मात्रमिदं खादेद् भक्षयेद्वा यथाऽनलम्","text":"audumbaraṃ cāmalakaṃ bādaraṃ vā yathābalam tāvanmātramidaṃ khāded bhakṣayedvā yathā'nalam"},{"type":"verse","number":"80","sanskrit":"अनेनैव विधानेन प्रयुक्तश्च दिने दिने निहन्ति ग्रहणीरोगान्कुष्ठानर्शोभगन्दरान्","text":"anenaiva vidhānena prayuktaśca dine dine nihanti grahaṇīrogānkuṣṭhānarśobhagandarān"},{"type":"verse","number":"81","sanskrit":"ज्वरमानाहहृद्रो गं गुल्मोदरविसूचिकाः कामलां पाण्डुरोगञ्च प्रमेहांश्चैव विंशतिम्","text":"jvaramānāhahṛdro gaṃ gulmodaravisūcikāḥ kāmalāṃ pāṇḍurogañca pramehāṃścaiva viṃśatim"},{"type":"verse","number":"82","sanskrit":"वातशोणितवी सर्पदद्रुयक्ष्महलीमकान् वातपित्तकफान्सर्वान्दुष्टाञ्छुद्धान्समाचरेत्","text":"vātaśoṇitavī sarpadadruyakṣmahalīmakān vātapittakaphānsarvānduṣṭāñchuddhānsamācaret"},{"type":"verse","number":"83","sanskrit":"व्याधिक्षीणा वयः क्षीणाः स्त्रीषुक्षीणाश्च ये नराः तेभ्यो हितो गुडोऽय स्याद्वन्ध्यानामपि पुत्रदः वृष्यो बल्यो बृंहणश्च वयसः स्थापनं तथा","text":"vyādhikṣīṇā vayaḥ kṣīṇāḥ strīṣukṣīṇāśca ye narāḥ tebhyo hito guḍo'ya syādvandhyānāmapi putradaḥ vṛṣyo balyo bṛṃhaṇaśca vayasaḥ sthāpanaṃ tathā"},{"type":"verse","number":"84","sanskrit":"अतीसाराधिकार लिखितं बिल्वतैलञ्चात्र हितम् इति चतुर्थोग्रहणीरोगाधिकारः समाप्तः ४","text":"atīsārādhikāra likhitaṃ bilvatailañcātra hitam iti caturthograhaṇīrogādhikāraḥ samāptaḥ 4"}]},{"sthana":"Уттаракханда","number":5,"lang":"sa","content":[{"type":"heading","heading":"Арша — геморрой"},{"type":"verse","number":"1","sanskrit":"पृथग्दोषैः समस्तैश्र शोणितात्सहजानि च अर्शांसि षट् प्रकाराणि विद्याद् गुद्वलित्रये","text":"pṛthagdoṣaiḥ samastaiśra śoṇitātsahajāni ca arśāṃsi ṣaṭ prakārāṇi vidyād gudvalitraye"},{"type":"verse","number":"2","sanskrit":"कषायकटुतिक्तानि रुक्षशीतलघूनि च प्रमिताल्पाशनं तीक्ष्णं मद्यं मैथुनसेवनम्","text":"kaṣāyakaṭutiktāni rukṣaśītalaghūni ca pramitālpāśanaṃ tīkṣṇaṃ madyaṃ maithunasevanam"},{"type":"verse","number":"3","sanskrit":"लङ्घनं देशकालौ च शीतौ व्यायामकर्म च शोको वातातपस्पर्शो हेतुर्वातार्शसां ततः","text":"laṅghanaṃ deśakālau ca śītau vyāyāmakarma ca śoko vātātapasparśo heturvātārśasāṃ tataḥ"},{"type":"verse","number":"4","sanskrit":"कट्वम्ललवणोष्णानि व्यायामाग्न्यातपप्रभाः देशकालावशिशिरौ क्रोधो मद्यमसूयनम्","text":"kaṭvamlalavaṇoṣṇāni vyāyāmāgnyātapaprabhāḥ deśakālāvaśiśirau krodho madyamasūyanam"},{"type":"verse","number":"5","sanskrit":"विदाहि तीक्ष्णमुष्णञ्च सर्वं पानान्नभोजनम् पित्तोल्वणानां विज्ञेयः प्रकोपे हेतुरर्शसाम्","text":"vidāhi tīkṣṇamuṣṇañca sarvaṃ pānānnabhojanam pittolvaṇānāṃ vijñeyaḥ prakope heturarśasām"},{"type":"verse","number":"6","sanskrit":"मधुरस्निग्धशीतानि लवणाम्लगुरूणि च अव्यायामदिवास्वप्नशय्याऽसनसुखे रतिः","text":"madhurasnigdhaśītāni lavaṇāmlagurūṇi ca avyāyāmadivāsvapnaśayyā'sanasukhe ratiḥ"},{"type":"verse","number":"7","sanskrit":"प्राग्वातसेवाशीतौ च देशकालावचिन्तनम् श्लैष्मिकाणां समुद्दिष्टमेतत्कारणमर्शसाम्","text":"prāgvātasevāśītau ca deśakālāvacintanam ślaiṣmikāṇāṃ samuddiṣṭametatkāraṇamarśasām"},{"type":"verse","number":"8","sanskrit":"हेतुलक्षणसंसर्गाद्विद्याद् द्वन्द्वोल्वणानि च सर्वो हेतुस्त्रिदोषाणां सहजैर्लक्षणं समम्","text":"hetulakṣaṇasaṃsargādvidyād dvandvolvaṇāni ca sarvo hetustridoṣāṇāṃ sahajairlakṣaṇaṃ samam"},{"type":"verse","number":"9","sanskrit":"विष्टम्भोऽन्नस्य दौर्बल्यं कुक्षेराटोप एव च कार्श्यमुद्गारबाहुल्यं सक्थिसादोऽल्पविट्कता","text":"viṣṭambho'nnasya daurbalyaṃ kukṣerāṭopa eva ca kārśyamudgārabāhulyaṃ sakthisādo'lpaviṭkatā"},{"type":"verse","number":"10","sanskrit":"ग्रहणीदोषपाण्ड्वर्त्ति प्रशङ्का चोदरस्य च पूर्वरूपं विनिर्दिष्टमर्शसामभिवृद्धये","text":"grahaṇīdoṣapāṇḍvartti praśaṅkā codarasya ca pūrvarūpaṃ vinirdiṣṭamarśasāmabhivṛddhaye"},{"type":"verse","number":"11","sanskrit":"दोषास्त्वङ्मांसमेदांसि सन्दूष्य विविधाकृतीन् मांसाङ्कुरानपानादौ कुर्वन्त्यर्शांसि ताञ्जगुः","text":"doṣāstvaṅmāṃsamedāṃsi sandūṣya vividhākṛtīn māṃsāṅkurānapānādau kurvantyarśāṃsi tāñjaguḥ"},{"type":"verse","number":"12","sanskrit":"गुदाङ्कुरा बह्वनिलाः शुष्काश्चिमिचिमान्विताः म्लानाः श्यावारुणाः स्तब्धा विशदाः परुषाः खराः","text":"gudāṅkurā bahvanilāḥ śuṣkāścimicimānvitāḥ mlānāḥ śyāvāruṇāḥ stabdhā viśadāḥ paruṣāḥ kharāḥ"},{"type":"verse","number":"13","sanskrit":"मिथो विसदृशा वक्रास्तीक्ष्णा विस्फुटिताननाः बिम्बीकर्कन्धुखर्जूरकर्कोटीफलसन्निभाः","text":"mitho visadṛśā vakrāstīkṣṇā visphuṭitānanāḥ bimbīkarkandhukharjūrakarkoṭīphalasannibhāḥ"},{"type":"verse","number":"14","sanskrit":"केचित्कदम्बपुष्पाभाः केचित्सिद्धार्थकोपमाः शिरःपार्श्वांसकट्यूरुवङ्क्षणाभ्यधिकव्यथाः","text":"kecitkadambapuṣpābhāḥ kecitsiddhārthakopamāḥ śiraḥpārśvāṃsakaṭyūruvaṅkṣaṇābhyadhikavyathāḥ"},{"type":"verse","number":"15","sanskrit":"क्षवथूद्गारविष्टम्भहृद्रो गा रोचकप्रदाः कासश्वासाग्निवैषम्य कर्णनादभ्रमावहाः","text":"kṣavathūdgāraviṣṭambhahṛdro gā rocakapradāḥ kāsaśvāsāgnivaiṣamya karṇanādabhramāvahāḥ"},{"type":"verse","number":"16","sanskrit":"तैरार्त्तो ग्रथितं स्तोकं सशब्दं सप्रवाहिकम् रुक्फेनपिच्छाऽनुगतं विड्बद्धमुपवेश्यते","text":"tairārtto grathitaṃ stokaṃ saśabdaṃ sapravāhikam rukphenapicchā'nugataṃ viḍbaddhamupaveśyate"},{"type":"verse","number":"17","sanskrit":"कृष्णत्वङ्नखविण्मूत्रनेत्रवक्त्रश्च जायते गुल्मप्लीहोदराष्ठीलासम्भवस्तत एव च","text":"kṛṣṇatvaṅnakhaviṇmūtranetravaktraśca jāyate gulmaplīhodarāṣṭhīlāsambhavastata eva ca"},{"type":"verse","number":"18","sanskrit":"पित्तोत्तरा नीलमुखा रक्तपीतासितप्रभाः तन्वस्रस्राविणो विस्रास्तनवो मृदवः श्लथाः","text":"pittottarā nīlamukhā raktapītāsitaprabhāḥ tanvasrasrāviṇo visrāstanavo mṛdavaḥ ślathāḥ"},{"type":"verse","number":"19","sanskrit":"शुकजिह्वा यकृत्खण्डजलौकोवक्त्रसन्निभाः दाहपाकज्वरस्वेदतृण्मूर्च्छाऽरतिमोहदाः","text":"śukajihvā yakṛtkhaṇḍajalaukovaktrasannibhāḥ dāhapākajvarasvedatṛṇmūrcchā'ratimohadāḥ"},{"type":"verse","number":"20","sanskrit":"सोष्माणो द्र्रवनीलोष्णपीतरक्तामवर्चसः यवमध्या हरित्पीतहारिद्र्रत्वङ्नखादयः","text":"soṣmāṇo drravanīloṣṇapītaraktāmavarcasaḥ yavamadhyā haritpītahāridrratvaṅnakhādayaḥ"},{"type":"verse","number":"21","sanskrit":"रक्तोल्वणा गुदे कीलाः पित्ताकृतिसमन्विताः वटप्ररोहसदृशा गुञ्जाविद्रुमसन्निभाः","text":"raktolvaṇā gude kīlāḥ pittākṛtisamanvitāḥ vaṭaprarohasadṛśā guñjāvidrumasannibhāḥ"},{"type":"verse","number":"22","sanskrit":"तेऽत्यर्थं दुष्टमुष्णं च गाढविट्कप्रपीडिताः स्रवन्ति सहसा रक्तं तस्य चातिप्रवृत्तितः","text":"te'tyarthaṃ duṣṭamuṣṇaṃ ca gāḍhaviṭkaprapīḍitāḥ sravanti sahasā raktaṃ tasya cātipravṛttitaḥ"},{"type":"verse","number":"23","sanskrit":"भेकाभः पीड्यते दुःखैः शोणितक्षयसम्भवैः हीनवर्णबलोत्साहो हतौजाः कलुषेन्द्रि यः","text":"bhekābhaḥ pīḍyate duḥkhaiḥ śoṇitakṣayasambhavaiḥ hīnavarṇabalotsāho hataujāḥ kaluṣendri yaḥ"},{"type":"verse","number":"24","sanskrit":"विट् श्यावं कठिनं रुक्षमधोवायुर्न वर्त्तते तनु चारुणबर्णं च फेनिलं चासृगर्शसाम्","text":"viṭ śyāvaṃ kaṭhinaṃ rukṣamadhovāyurna varttate tanu cāruṇabarṇaṃ ca phenilaṃ cāsṛgarśasām"},{"type":"verse","number":"25","sanskrit":"कट्यूरुगुदशूलञ्च दौर्बल्यं यदि चाधिकम् तत्रानुबन्धो वातस्य हेतुर्यदि च रुक्षणम्","text":"kaṭyūrugudaśūlañca daurbalyaṃ yadi cādhikam tatrānubandho vātasya heturyadi ca rukṣaṇam"},{"type":"verse","number":"26","sanskrit":"शिथिलं श्वेतपीतं च विट् स्निग्धं गुरुशीतलम् यद्यर्शसां घनं चासृक् तन्तुमत्पाण्डुपिच्छिलम्","text":"śithilaṃ śvetapītaṃ ca viṭ snigdhaṃ guruśītalam yadyarśasāṃ ghanaṃ cāsṛk tantumatpāṇḍupicchilam"},{"type":"verse","number":"27","sanskrit":"गुदं सपिच्छं स्तिमितं गुरु स्निग्धं च कारणम् श्लेष्मानुबन्धो विज्ञेयस्तत्र रक्तार्शसां बुधैः","text":"gudaṃ sapicchaṃ stimitaṃ guru snigdhaṃ ca kāraṇam śleṣmānubandho vijñeyastatra raktārśasāṃ budhaiḥ"},{"type":"verse","number":"28","sanskrit":"श्लेष्मोल्वणा महामूला घना मन्दरुजः सिताः उत्सन्नपचिताः स्निग्धाःस्तब्धवृत्तगुरुस्थिराः","text":"śleṣmolvaṇā mahāmūlā ghanā mandarujaḥ sitāḥ utsannapacitāḥ snigdhāḥstabdhavṛttagurusthirāḥ"},{"type":"verse","number":"29","sanskrit":"पिच्छिलाः स्तिमिताः श्लक्ष्णाः कण्ड्वाढ्याः स्पर्शनप्रियाः करीरपनसास्थ्याभास्तथा गोस्तनसन्निभाः","text":"picchilāḥ stimitāḥ ślakṣṇāḥ kaṇḍvāḍhyāḥ sparśanapriyāḥ karīrapanasāsthyābhāstathā gostanasannibhāḥ"},{"type":"verse","number":"30","sanskrit":"वङ्कणानाहिनः पायुबस्तिनाभिविकर्षिणः सकासश्वासहृल्लासप्रसेकारुचिपीनसाः","text":"vaṅkaṇānāhinaḥ pāyubastinābhivikarṣiṇaḥ sakāsaśvāsahṛllāsaprasekārucipīnasāḥ"},{"type":"verse","number":"31","sanskrit":"मेहकृच्छ्रशिरोजाड्यशिशिरज्वरकारिणः क्लैब्याग्निमार्दवच्छर्दिरामप्रायविकारदाः","text":"mehakṛcchraśirojāḍyaśiśirajvarakāriṇaḥ klaibyāgnimārdavacchardirāmaprāyavikāradāḥ"},{"type":"verse","number":"32","sanskrit":"वसाभसकफप्राज्यपुरीषाः सप्रवाहिकाः न स्रवन्ति न भिद्यन्ते पाण्डुस्निग्धत्वगादयः","text":"vasābhasakaphaprājyapurīṣāḥ sapravāhikāḥ na sravanti na bhidyante pāṇḍusnigdhatvagādayaḥ"},{"type":"verse","number":"33","sanskrit":"हेतुलक्षणसंसर्गाद्विद्याद् द्वन्द्वोल्वणानि च","text":"hetulakṣaṇasaṃsargādvidyād dvandvolvaṇāni ca"},{"type":"verse","number":"34","sanskrit":"सर्वैः सर्वात्मकान्याहुर्लक्षणैः सहजानि च","text":"sarvaiḥ sarvātmakānyāhurlakṣaṇaiḥ sahajāni ca"},{"type":"verse","number":"35","sanskrit":"अर्शांसि सहजातानि दारुणानि भवन्ति हि दुर्दर्शनानि पाण्डूनि परुषाण्यरुणानि च","text":"arśāṃsi sahajātāni dāruṇāni bhavanti hi durdarśanāni pāṇḍūni paruṣāṇyaruṇāni ca"},{"type":"verse","number":"36","sanskrit":"अन्तर्मुखाणि तैरार्त्तः क्षीणः क्षीणस्वरो भवेत् क्षीणानलः क्षीणरेताः शिरासन्नतविग्रहः अल्पप्रजः क्रोधशीलो भग्नकांस्यस्वनान्वितः शिरोदृक्कर्णनासासु रोगो हृल्लेपसेकवान्","text":"antarmukhāṇi tairārttaḥ kṣīṇaḥ kṣīṇasvaro bhavet kṣīṇānalaḥ kṣīṇaretāḥ śirāsannatavigrahaḥ alpaprajaḥ krodhaśīlo bhagnakāṃsyasvanānvitaḥ śirodṛkkarṇanāsāsu rogo hṛllepasekavān"},{"type":"verse","number":"37","sanskrit":"बाह्यायां तु वलौ जातान्येकदोषोल्वणानि च अर्शांसि सुखसाध्यानि न चिरोत्पतितानि च","text":"bāhyāyāṃ tu valau jātānyekadoṣolvaṇāni ca arśāṃsi sukhasādhyāni na cirotpatitāni ca"},{"type":"verse","number":"38","sanskrit":"द्वन्द्वजानि द्वितीयायां वलौ यान्याश्रितानि च कृच्छ्रसाध्यानि तान्याहुःपरिसंवत्सराणि च","text":"dvandvajāni dvitīyāyāṃ valau yānyāśritāni ca kṛcchrasādhyāni tānyāhuḥparisaṃvatsarāṇi ca"},{"type":"verse","number":"39","sanskrit":"सहजानि त्रिदोषाणि यानि चाभ्यन्तरां बलिम् जायन्तेऽशासि संश्रित्य तान्यसाध्यानि निर्दिशेत्","text":"sahajāni tridoṣāṇi yāni cābhyantarāṃ balim jāyante'śāsi saṃśritya tānyasādhyāni nirdiśet"},{"type":"verse","number":"40","sanskrit":"शेषत्वादायुषस्तानि चतुष्पादसमन्वये याप्यन्ते दीप्तकायाग्नेः प्रत्याख्येयान्यतोऽन्यथा","text":"śeṣatvādāyuṣastāni catuṣpādasamanvaye yāpyante dīptakāyāgneḥ pratyākhyeyānyato'nyathā"},{"type":"verse","number":"41","sanskrit":"हस्ते पादे मुखे नाभ्यां गुदे बृषणयोस्तथा शोथो हृत्पार्श्वशूलं च यस्यासाध्योऽशसो हि सः","text":"haste pāde mukhe nābhyāṃ gude bṛṣaṇayostathā śotho hṛtpārśvaśūlaṃ ca yasyāsādhyo'śaso hi saḥ"},{"type":"verse","number":"42","sanskrit":"हृत्पार्श्वशूलं संमोहश्छर्दिरङ्गस्य रुग्ज्वरः तृष्णा गुदाऽस्यपाकश्च निहन्युर्गुदजातुरम्","text":"hṛtpārśvaśūlaṃ saṃmohaśchardiraṅgasya rugjvaraḥ tṛṣṇā gudā'syapākaśca nihanyurgudajāturam"},{"type":"verse","number":"43","sanskrit":"तृष्णाऽरोचकशूलार्त्तमतिप्रस्रुतशोणितम् शोथातीसारसंयुक्तमर्शांसि क्षपयन्ति हि","text":"tṛṣṇā'rocakaśūlārttamatiprasrutaśoṇitam śothātīsārasaṃyuktamarśāṃsi kṣapayanti hi"},{"type":"verse","number":"44","sanskrit":"मेढ्रादिष्वपि वक्ष्यन्ते यथास्वं नाभिजानि च गण्डूपदास्यरूपाणि पिच्छिलानि मृदूनि च","text":"meḍhrādiṣvapi vakṣyante yathāsvaṃ nābhijāni ca gaṇḍūpadāsyarūpāṇi picchilāni mṛdūni ca"},{"type":"verse","number":"45","sanskrit":"व्यानो गृहीत्वा श्लेष्माणं करोत्यर्शस्त्वचो बहिः कीलोपमं स्थिरखरं चर्मकीलं तु तद्विदुः","text":"vyāno gṛhītvā śleṣmāṇaṃ karotyarśastvaco bahiḥ kīlopamaṃ sthirakharaṃ carmakīlaṃ tu tadviduḥ"},{"type":"verse","number":"46","sanskrit":"वातेन तोदपारुष्यं पित्तादतिसरक्तता श्लेष्मणा स्निग्धता तस्य ग्रन्थितत्वं सवर्णता","text":"vātena todapāruṣyaṃ pittādatisaraktatā śleṣmaṇā snigdhatā tasya granthitatvaṃ savarṇatā"},{"type":"verse","number":"47","sanskrit":"यद्वातस्यानुलोम्याय यदग्निबलवृद्धये अन्नपानौषधं सर्वं तत्सेव्यं नित्यमर्शसैः","text":"yadvātasyānulomyāya yadagnibalavṛddhaye annapānauṣadhaṃ sarvaṃ tatsevyaṃ nityamarśasaiḥ"},{"type":"verse","number":"48","sanskrit":"शालिषष्टिकगोधूमयवान्नानि घृतैः सह अजाक्षीरेण वा निम्बपटोलानां रसेन वा","text":"śāliṣaṣṭikagodhūmayavānnāni ghṛtaiḥ saha ajākṣīreṇa vā nimbapaṭolānāṃ rasena vā"},{"type":"verse","number":"49","sanskrit":"वार्त्ताकुमूलजैः कान्दै रसैर्मांसरसेन वा जीवन्त्युपोदिकाशाकैस्तण्डुलीयकवास्तुकैः","text":"vārttākumūlajaiḥ kāndai rasairmāṃsarasena vā jīvantyupodikāśākaistaṇḍulīyakavāstukaiḥ"},{"type":"verse","number":"50","sanskrit":"अन्यैश्च सृष्टविण्मूत्रमरुद्भिर्वह्निदीपनैः अर्शांसि भिन्नवर्चांसि हन्याद्वातार्तिसारवत्","text":"anyaiśca sṛṣṭaviṇmūtramarudbhirvahnidīpanaiḥ arśāṃsi bhinnavarcāṃsi hanyādvātārtisāravat"},{"type":"verse","number":"51","sanskrit":"सतक्रं लवणं दद्याद्वातवर्चोऽनुलोमनम् न प्ररोहन्ति गुदजाः पुनस्तक्रसमाहताः","text":"satakraṃ lavaṇaṃ dadyādvātavarco'nulomanam na prarohanti gudajāḥ punastakrasamāhatāḥ"},{"type":"verse","number":"52","sanskrit":"तक्राभ्यासोऽशसैः कार्यो बलवर्णाग्निवृद्धये स्रोतःसु तक्रशुद्धेषु सम्यक् सरति तद्र सः","text":"takrābhyāso'śasaiḥ kāryo balavarṇāgnivṛddhaye srotaḥsu takraśuddheṣu samyak sarati tadra saḥ"},{"type":"verse","number":"53","sanskrit":"तेन पुष्टिस्तथा तुष्टिर्बलं वर्णश्च जायते वातश्लेष्मविकाराणां शतञ्च विनिवर्त्तते","text":"tena puṣṭistathā tuṣṭirbalaṃ varṇaśca jāyate vātaśleṣmavikārāṇāṃ śatañca vinivarttate"},{"type":"verse","number":"54","sanskrit":"चिरबिल्वाग्निसिन्धूत्थनागरेन्द्र यवारलु तक्रेण पिबतोऽशासि निपतन्त्यसृजा सह","text":"cirabilvāgnisindhūtthanāgarendra yavāralu takreṇa pibato'śāsi nipatantyasṛjā saha"},{"type":"verse","number":"55","sanskrit":"लेपं रजनिचूर्णेन सुधादुग्धयुतेन च अर्शोरोगनिवृत्त्यर्थं कारयेत्तु चिकित्सकः","text":"lepaṃ rajanicūrṇena sudhādugdhayutena ca arśoroganivṛttyarthaṃ kārayettu cikitsakaḥ"},{"type":"verse","number":"56","sanskrit":"पिप्पली सैन्धवं कुष्ठं शिरीषस्य फलं तथा सुधादुग्धार्कदुग्धं वा लेपोऽय गुदजान् हरेत्","text":"pippalī saindhavaṃ kuṣṭhaṃ śirīṣasya phalaṃ tathā sudhādugdhārkadugdhaṃ vā lepo'ya gudajān haret"},{"type":"verse","number":"57","sanskrit":"हरिद्रा जालिनीचूर्णं कटुतैलसमन्वितम् एष लेपो वरः प्रोक्तो ह्यर्शसामन्तकारकः","text":"haridrā jālinīcūrṇaṃ kaṭutailasamanvitam eṣa lepo varaḥ prokto hyarśasāmantakārakaḥ"},{"type":"verse","number":"58","sanskrit":"असितानां तिलानान्तु पलं शीतजलेन च खादतोऽशासिशाम्यन्ति दृढा दन्ता भवन्ति च","text":"asitānāṃ tilānāntu palaṃ śītajalena ca khādato'śāsiśāmyanti dṛḍhā dantā bhavanti ca"},{"type":"verse","number":"59","sanskrit":"शस्त्रैर्वाऽथ जलौकाभिः प्रोच्छूनकठिनार्शंसः शोणितं सञ्चितं दृष्ट्वा हरेत्प्राज्ञः पुनः पुनः","text":"śastrairvā'tha jalaukābhiḥ procchūnakaṭhinārśaṃsaḥ śoṇitaṃ sañcitaṃ dṛṣṭvā haretprājñaḥ punaḥ punaḥ"},{"type":"verse","number":"60","sanskrit":"काशीसं सैन्धवं कृष्णा शुण्ठी कुष्ठञ्च लाङ्गली शिलाभिदश्वमारश्च दन्तीजन्तुघ्नचित्रकम्","text":"kāśīsaṃ saindhavaṃ kṛṣṇā śuṇṭhī kuṣṭhañca lāṅgalī śilābhidaśvamāraśca dantījantughnacitrakam"},{"type":"verse","number":"61","sanskrit":"तालकं कुनटी स्वर्णक्षीरी चैतैः पचेद्भिषक् तैलं स्नुह्यर्कपयसा गवां मूत्रं चतुर्गुणम्","text":"tālakaṃ kunaṭī svarṇakṣīrī caitaiḥ pacedbhiṣak tailaṃ snuhyarkapayasā gavāṃ mūtraṃ caturguṇam"},{"type":"verse","number":"62","sanskrit":"एतदभ्यङ्गतोऽशासि क्षारेणेव पतन्ति हि क्षारकर्मकरं ह्येतन्न च सन्दूषयेद्वलिम्","text":"etadabhyaṅgato'śāsi kṣāreṇeva patanti hi kṣārakarmakaraṃ hyetanna ca sandūṣayedvalim"},{"type":"verse","number":"63","sanskrit":"शुण्ठीकणामरिचनागदलत्वगेलं चूर्णीकृतं क्रमविवर्द्धितमूर्ध्वमन्त्यात् खादेदिदं समसितं गुदजाग्निमान्द्यगुल्मारुचिश्वसनकण्ठहृदामयेषु","text":"śuṇṭhīkaṇāmaricanāgadalatvagelaṃ cūrṇīkṛtaṃ kramavivarddhitamūrdhvamantyāt khādedidaṃ samasitaṃ gudajāgnimāndyagulmāruciśvasanakaṇṭhahṛdāmayeṣu"},{"type":"verse","number":"64","sanskrit":"त्रिकत्रयं वचा हिङ्गु पाठाक्षारौ निशाद्वयम् चव्यतिक्ताकलिङ्गानि शक्राह्वा लवणानि च","text":"trikatrayaṃ vacā hiṅgu pāṭhākṣārau niśādvayam cavyatiktākaliṅgāni śakrāhvā lavaṇāni ca"},{"type":"verse","number":"65","sanskrit":"ग्रन्थिबिल्वाजमोदाश्च गणोऽष्टाविंशतिर्मतः एतानि समभागानि सूक्ष्मचूर्णानि कारयेत्","text":"granthibilvājamodāśca gaṇo'ṣṭāviṃśatirmataḥ etāni samabhāgāni sūkṣmacūrṇāni kārayet"},{"type":"verse","number":"66","sanskrit":"चूर्णं विडालपदकं पिबेदुष्णेन वारिणा एरण्डतैलयुक्तं वा लिह्याच्चूर्णमिदं नरः","text":"cūrṇaṃ viḍālapadakaṃ pibeduṣṇena vāriṇā eraṇḍatailayuktaṃ vā lihyāccūrṇamidaṃ naraḥ"},{"type":"verse","number":"67","sanskrit":"हन्यादर्शांसि सर्वाणि श्वासशोषभगन्दरान् हृच्छूलं पार्श्वशूलञ्च वातगुल्मं तथोदरम्","text":"hanyādarśāṃsi sarvāṇi śvāsaśoṣabhagandarān hṛcchūlaṃ pārśvaśūlañca vātagulmaṃ tathodaram"},{"type":"verse","number":"68","sanskrit":"हिक्कां कासं प्रमेहांश्च पाण्डुरोगं सकामलम् आमवातमुदावर्त्तमन्त्रवृद्धिं गुदाकृमीन्","text":"hikkāṃ kāsaṃ pramehāṃśca pāṇḍurogaṃ sakāmalam āmavātamudāvarttamantravṛddhiṃ gudākṛmīn"},{"type":"verse","number":"69","sanskrit":"अन्ये च ग्रहणीदोषा भिषग्भिर्ये प्रकीर्त्तिताः विजयो नाम चूर्णोऽय तान्सर्वानाशु नाशयेत्","text":"anye ca grahaṇīdoṣā bhiṣagbhirye prakīrttitāḥ vijayo nāma cūrṇo'ya tānsarvānāśu nāśayet"},{"type":"verse","number":"70","sanskrit":"महाज्वरोपसृष्टानां भूतोपहतचेतसाम् अप्रजानाञ्च नारीणां हितमेतद्धि भेषजम्","text":"mahājvaropasṛṣṭānāṃ bhūtopahatacetasām aprajānāñca nārīṇāṃ hitametaddhi bheṣajam"},{"type":"verse","number":"71","sanskrit":"मरिचमहौषधचित्रकशूरणभागा यथोत्तरं द्विगुणाः सर्वसमो गुडभागः सेव्योऽय मोदकः प्रसिद्धफलः","text":"maricamahauṣadhacitrakaśūraṇabhāgā yathottaraṃ dviguṇāḥ sarvasamo guḍabhāgaḥ sevyo'ya modakaḥ prasiddhaphalaḥ"},{"type":"verse","number":"72","sanskrit":"ज्वलनं ज्वलयति जाठरमुन्मूलयतीह शूलगुल्मगदान् निःशेषयति श्लीपदमर्शांसि विनाशयत्याशु","text":"jvalanaṃ jvalayati jāṭharamunmūlayatīha śūlagulmagadān niḥśeṣayati ślīpadamarśāṃsi vināśayatyāśu"},{"type":"verse","number":"73","sanskrit":"षोडश शूरणभागा वह्नेरष्टौ महौषधस्यातः अर्द्धेन भागयुक्तिर्मरिचस्य ततोऽपि चार्द्धेन","text":"ṣoḍaśa śūraṇabhāgā vahneraṣṭau mahauṣadhasyātaḥ arddhena bhāgayuktirmaricasya tato'pi cārddhena"},{"type":"verse","number":"74","sanskrit":"त्रिफला कणा समूला तालीसारुष्करकृमिघ्नानाम् भागा महौषधसमा दहनांशा तालमूली च","text":"triphalā kaṇā samūlā tālīsāruṣkarakṛmighnānām bhāgā mahauṣadhasamā dahanāṃśā tālamūlī ca"},{"type":"verse","number":"75","sanskrit":"भागाः शूरणतुल्या दातव्या वृद्धदारकस्यापि भृङ्गैले मरिचांशे सर्वाण्येकत्र कारयेच्चूर्णम्","text":"bhāgāḥ śūraṇatulyā dātavyā vṛddhadārakasyāpi bhṛṅgaile maricāṃśe sarvāṇyekatra kārayeccūrṇam"},{"type":"verse","number":"76","sanskrit":"द्विगुणेन गुडेन युतः सेव्योऽय मोदकः प्रकामधनैः गुरुवृष्यभोजनरतैरितरेषूपद्र वं कुर्यात्","text":"dviguṇena guḍena yutaḥ sevyo'ya modakaḥ prakāmadhanaiḥ guruvṛṣyabhojanaratairitareṣūpadra vaṃ kuryāt"},{"type":"verse","number":"77","sanskrit":"भस्मकमनेन जनितं पूर्वमगस्त्यस्य योगराजेन भीमस्य मारुतेरपि महाशनौ तेन तौ यातौ","text":"bhasmakamanena janitaṃ pūrvamagastyasya yogarājena bhīmasya māruterapi mahāśanau tena tau yātau"},{"type":"verse","number":"78","sanskrit":"अग्निबलवर्णहेतुर्न केवलं शूरणो महावीर्यः हन्ता शस्त्रक्षारानलैर्विनाऽप्यर्शसामेषः","text":"agnibalavarṇaheturna kevalaṃ śūraṇo mahāvīryaḥ hantā śastrakṣārānalairvinā'pyarśasāmeṣaḥ"},{"type":"verse","number":"79","sanskrit":"श्वयथुश्लीपदमदहृद् ग्रहणीं च कफानिलोद्भूताम् नाशयति बलीपलितं मेधांकुरुतेजराञ्चहरेत्","text":"śvayathuślīpadamadahṛd grahaṇīṃ ca kaphānilodbhūtām nāśayati balīpalitaṃ medhāṃkurutejarāñcaharet"},{"type":"verse","number":"80","sanskrit":"हिक्कां कासं श्वासं च राजरोगं प्रमेहांश्च प्लीहानं च तथोग्रं हन्त्याशु रसायनं पुंसाम्","text":"hikkāṃ kāsaṃ śvāsaṃ ca rājarogaṃ pramehāṃśca plīhānaṃ ca tathograṃ hantyāśu rasāyanaṃ puṃsām"},{"type":"verse","number":"81","sanskrit":"त्रिवृत्तेजोवती दन्ती श्वदंष्ट्रा चित्रकं शटी गवाक्षी मुस्तविश्वाह्वविडङ्गानि हरीतकी","text":"trivṛttejovatī dantī śvadaṃṣṭrā citrakaṃ śaṭī gavākṣī mustaviśvāhvaviḍaṅgāni harītakī"},{"type":"verse","number":"82","sanskrit":"पलोन्मितानि चैतानि पलान्यष्टावरुष्करात् बृद्धदारात् पलान्यष्टौ शूरणस्य तु षोडश","text":"palonmitāni caitāni palānyaṣṭāvaruṣkarāt bṛddhadārāt palānyaṣṭau śūraṇasya tu ṣoḍaśa"},{"type":"verse","number":"83","sanskrit":"जलद्रो णद्वये क्वाथ्यं चतुर्भागावशेषितम् पूतन्तु तं रसं भूयः क्वाथ्येभ्यस्त्रिगुणं गुडम्","text":"jaladro ṇadvaye kvāthyaṃ caturbhāgāvaśeṣitam pūtantu taṃ rasaṃ bhūyaḥ kvāthyebhyastriguṇaṃ guḍam"},{"type":"verse","number":"84","sanskrit":"मेलयित्वा पचेत्तावद्यावद्दर्वींप्रलेपनम् अवतार्य ततः पश्चाच्चूर्णानीमानि दापयेत्","text":"melayitvā pacettāvadyāvaddarvīṃpralepanam avatārya tataḥ paścāccūrṇānīmāni dāpayet"},{"type":"verse","number":"85","sanskrit":"त्रिवृत्तेजोवतीकन्दचित्रकान्द्विपलांशिकान् एलात्वङ्मरिचं चापि नागाह्वाञ्चापि षट्पलम्","text":"trivṛttejovatīkandacitrakāndvipalāṃśikān elātvaṅmaricaṃ cāpi nāgāhvāñcāpi ṣaṭpalam"},{"type":"verse","number":"86","sanskrit":"द्वात्रिंशच्च पलान्यत्र चूर्णयित्वा निधापयेत् ततो मात्रां प्रयुञ्जीत जीर्णे क्षीररसाशिनः","text":"dvātriṃśacca palānyatra cūrṇayitvā nidhāpayet tato mātrāṃ prayuñjīta jīrṇe kṣīrarasāśinaḥ"},{"type":"verse","number":"87","sanskrit":"हन्यादर्शांसि सर्वाणि तथा सर्वोदराण्यपि गुल्मानपि प्रमेहांश्च पाण्डुरोगं हलीमकम्","text":"hanyādarśāṃsi sarvāṇi tathā sarvodarāṇyapi gulmānapi pramehāṃśca pāṇḍurogaṃ halīmakam"},{"type":"verse","number":"88","sanskrit":"दीपयेदनलं मन्दं यक्ष्माणं चापकर्षति आढ्यवाते प्रतिश्याये पीनसे च हितो मतः","text":"dīpayedanalaṃ mandaṃ yakṣmāṇaṃ cāpakarṣati āḍhyavāte pratiśyāye pīnase ca hito mataḥ"},{"type":"verse","number":"89","sanskrit":"भवन्त्यनेन पुरुषाः शतं वर्षाण्यनामयाः दीर्घायुषः प्रजनना वलीपलितवर्जिताः","text":"bhavantyanena puruṣāḥ śataṃ varṣāṇyanāmayāḥ dīrghāyuṣaḥ prajananā valīpalitavarjitāḥ"},{"type":"verse","number":"90","sanskrit":"गुडः श्रीबाहुशालोऽय रसायनवरो मतः दुर्नामान्तकरो ह्येष दृष्टो वारसहस्रशः","text":"guḍaḥ śrībāhuśālo'ya rasāyanavaro mataḥ durnāmāntakaro hyeṣa dṛṣṭo vārasahasraśaḥ"},{"type":"verse","number":"91","sanskrit":"यावद्दर्वीप्रलेपः स्याद् गुडो वा तन्तुमान् भवेत् तोयपूर्णे यदा पात्रे क्षिप्तो न प्लवते गुडः","text":"yāvaddarvīpralepaḥ syād guḍo vā tantumān bhavet toyapūrṇe yadā pātre kṣipto na plavate guḍaḥ"},{"type":"verse","number":"92","sanskrit":"क्षिप्तस्तु निश्चलस्तिष्ठेत्पतितस्तु न शीर्यति एष पाकः समस्तानां गुडानां परिकीर्त्तितः","text":"kṣiptastu niścalastiṣṭhetpatitastu na śīryati eṣa pākaḥ samastānāṃ guḍānāṃ parikīrttitaḥ"},{"type":"verse","number":"93","sanskrit":"सार्द्धं पलं पलं चार्द्धं भक्षयेद् गुडखण्डयोः श्रेष्ठा तु मध्यमा हीना मात्रोक्ता मुनिभिस्त्रिधा","text":"sārddhaṃ palaṃ palaṃ cārddhaṃ bhakṣayed guḍakhaṇḍayoḥ śreṣṭhā tu madhyamā hīnā mātroktā munibhistridhā"},{"type":"verse","number":"94","sanskrit":"तिलभल्लातकैः पथ्या गुडश्चेति समांशकैः दुर्नामश्वासकासघ्नं प्लीहपाण्डुज्वरापहम्","text":"tilabhallātakaiḥ pathyā guḍaśceti samāṃśakaiḥ durnāmaśvāsakāsaghnaṃ plīhapāṇḍujvarāpaham"},{"type":"verse","number":"95","sanskrit":"पित्तश्लेष्मप्रशमनी कण्डूकुक्षिरुजाऽपहा गुदजान्नाशयत्याशु भक्षिता सगुडाऽभया","text":"pittaśleṣmapraśamanī kaṇḍūkukṣirujā'pahā gudajānnāśayatyāśu bhakṣitā saguḍā'bhayā"},{"type":"verse","number":"96","sanskrit":"प्रणम्य शङ्करं रुद्र्र दण्डपाणिं महेश्वरम् जीवितारोग्यमन्विच्छन्नारदोऽपृच्छदीश्वरम्","text":"praṇamya śaṅkaraṃ rudrra daṇḍapāṇiṃ maheśvaram jīvitārogyamanvicchannārado'pṛcchadīśvaram"},{"type":"verse","number":"97","sanskrit":"सुखोपायेन हे नाथ शस्त्रक्षाराग्निभिर्विना चिकित्सामर्शसां नॄणांकारुण्याद्वक्तुमर्हसि","text":"sukhopāyena he nātha śastrakṣārāgnibhirvinā cikitsāmarśasāṃ nṝṇāṃkāruṇyādvaktumarhasi"},{"type":"verse","number":"98","sanskrit":"नारदस्य वचः श्रुत्वा नराणां हितकाम्यया अर्शसां नाशनं श्रेष्ठं भैषज्यं शङ्करोऽवदत्","text":"nāradasya vacaḥ śrutvā narāṇāṃ hitakāmyayā arśasāṃ nāśanaṃ śreṣṭhaṃ bhaiṣajyaṃ śaṅkaro'vadat"},{"type":"verse","number":"99","sanskrit":"पाण्ड्यवज्रादिलोहानामादायान्यतमं शुभम् कृत्वा निर्मलमादौ तु कुनट्या माक्षिकेण च","text":"pāṇḍyavajrādilohānāmādāyānyatamaṃ śubham kṛtvā nirmalamādau tu kunaṭyā mākṣikeṇa ca"},{"type":"verse","number":"100","sanskrit":"पत्तूरमूलकल्केन लिम्पेद्र्रसयुतेन च वह्नौ निक्षिप्य विधिवत्साराङ्गारेण निर्द्धमेत्","text":"pattūramūlakalkena limpedrrasayutena ca vahnau nikṣipya vidhivatsārāṅgāreṇa nirddhamet"},{"type":"verse","number":"101","sanskrit":"ज्वाला च तस्य रोद्धव्या त्रिफलाया रसेन च ततो विज्ञान गलितं शङ्कुनोर्ध्वं समुच्छ्रयेत्","text":"jvālā ca tasya roddhavyā triphalāyā rasena ca tato vijñāna galitaṃ śaṅkunordhvaṃ samucchrayet"},{"type":"verse","number":"102","sanskrit":"त्रिफलाया रसे पूते तदाकृष्य तु निर्धमेत् न सम्यग्गालितं यत्तु तेनैव विधिना पुनः","text":"triphalāyā rase pūte tadākṛṣya tu nirdhamet na samyaggālitaṃ yattu tenaiva vidhinā punaḥ"},{"type":"verse","number":"103","sanskrit":"ध्मातं निर्वापयेत्तस्मिंल्लोहं तत्त्रिफलारसे यल्लोहं न मृतं तत्तु पाच्यं भूयोऽपि पूर्ववत्","text":"dhmātaṃ nirvāpayettasmiṃllohaṃ tattriphalārase yallohaṃ na mṛtaṃ tattu pācyaṃ bhūyo'pi pūrvavat"},{"type":"verse","number":"104","sanskrit":"मारणान्न मृतं यच्च तत्त्यक्तव्यमलोहवत् ततः सशोष्य विधिवच्चूर्णयेल्लोहभाजने","text":"māraṇānna mṛtaṃ yacca tattyaktavyamalohavat tataḥ saśoṣya vidhivaccūrṇayellohabhājane"},{"type":"verse","number":"105","sanskrit":"लोहेन च तथा पिष्याद् दृषदा सूक्ष्मचूर्णितम् कृत्वा लोहमये पात्रे मार्दे वा लिप्तरन्ध्रके रसैः पङ्कोपमं कृत्वा तं पचेद्गोमयाग्निना","text":"lohena ca tathā piṣyād dṛṣadā sūkṣmacūrṇitam kṛtvā lohamaye pātre mārde vā liptarandhrake rasaiḥ paṅkopamaṃ kṛtvā taṃ pacedgomayāgninā"},{"type":"verse","number":"106","sanskrit":"पुटानि क्रमतो दद्यात्पृथगेभिर्विधानतः त्रिफलाऽद्र कभृङ्गाणां केशराजस्य बुद्धिमान्","text":"puṭāni kramato dadyātpṛthagebhirvidhānataḥ triphalā'dra kabhṛṅgāṇāṃ keśarājasya buddhimān"},{"type":"verse","number":"107","sanskrit":"मानकन्दकभल्लातवह्नीनां शूरणस्य च हस्तिकर्णपलाशस्य कुलिशस्य तथैव च","text":"mānakandakabhallātavahnīnāṃ śūraṇasya ca hastikarṇapalāśasya kuliśasya tathaiva ca"},{"type":"verse","number":"108","sanskrit":"पुटे पुटे चूर्णयित्वा लोहात्षोडशिकं पलम्","text":"puṭe puṭe cūrṇayitvā lohātṣoḍaśikaṃ palam"},{"type":"verse","number":"109","sanskrit":"तन्मात्रं त्रिफलायाश्च पलेनाधिकमाहरेत् अष्टभागावशषे तु रसे तस्याः पचेद् बुधः","text":"tanmātraṃ triphalāyāśca palenādhikamāharet aṣṭabhāgāvaśaṣe tu rase tasyāḥ paced budhaḥ"},{"type":"verse","number":"110","sanskrit":"अष्टौ पलानि दत्वा च सर्पिषो लोहभाजने ताम्रे वा लोहदर्व्या तु चालयेद्विधिपूर्वकम्","text":"aṣṭau palāni datvā ca sarpiṣo lohabhājane tāmre vā lohadarvyā tu cālayedvidhipūrvakam"},{"type":"verse","number":"111","sanskrit":"ततः पाकविधानज्ञः स्वच्छे चोर्ध्वं च सर्पिषि मृदुमध्यादिभेदेन गृह्णीयात्पाकमन्यतः","text":"tataḥ pākavidhānajñaḥ svacche cordhvaṃ ca sarpiṣi mṛdumadhyādibhedena gṛhṇīyātpākamanyataḥ"},{"type":"verse","number":"112","sanskrit":"आरम्भे तद्विधानज्ञः कृतकौतुकमङ्गलः घृतभ्रामरसंयुक्तं विलिह्याद्र क्तिकाक्रमात्","text":"ārambhe tadvidhānajñaḥ kṛtakautukamaṅgalaḥ ghṛtabhrāmarasaṃyuktaṃ vilihyādra ktikākramāt"},{"type":"verse","number":"113","sanskrit":"वर्द्धमानानुपानञ्च गव्यक्षीरोत्तमं मतम् गव्याभावे त्वजायाश्च स्निग्धवृष्यादिभोजनम्","text":"varddhamānānupānañca gavyakṣīrottamaṃ matam gavyābhāve tvajāyāśca snigdhavṛṣyādibhojanam"},{"type":"verse","number":"114","sanskrit":"सद्यो वह्निकरश्चैव भस्मकञ्च नियच्छति हन्ति वातं तथा पित्तं कुष्ठानि विषमज्वरम्","text":"sadyo vahnikaraścaiva bhasmakañca niyacchati hanti vātaṃ tathā pittaṃ kuṣṭhāni viṣamajvaram"},{"type":"verse","number":"115","sanskrit":"गुल्माक्षिपाण्डुरोगांश्च निद्रा लस्यमरोचकम् शूलञ्च परिणामञ्च प्रमेहमपबाहुकम्","text":"gulmākṣipāṇḍurogāṃśca nidrā lasyamarocakam śūlañca pariṇāmañca pramehamapabāhukam"},{"type":"verse","number":"116","sanskrit":"श्वयथुंरुधिरस्रावं दुर्नामानं विशेषतः बलकृद् बृंहणञ्चैव कान्तिदं स्वरबोधनम्","text":"śvayathuṃrudhirasrāvaṃ durnāmānaṃ viśeṣataḥ balakṛd bṛṃhaṇañcaiva kāntidaṃ svarabodhanam"},{"type":"verse","number":"117","sanskrit":"शरीरलाघवकरमारोग्य पुष्टिवर्द्धनम् आयुष्यं श्रीकरञ्चैव बलतेजस्करं शुभम्","text":"śarīralāghavakaramārogya puṣṭivarddhanam āyuṣyaṃ śrīkarañcaiva balatejaskaraṃ śubham"},{"type":"verse","number":"118","sanskrit":"सश्रीकपुत्रजननं वलीपलितनाशनम् दुर्नामारिरयं नाम्ना दृष्टो वारसहस्त्रशः","text":"saśrīkaputrajananaṃ valīpalitanāśanam durnāmārirayaṃ nāmnā dṛṣṭo vārasahastraśaḥ"},{"type":"verse","number":"119","sanskrit":"अनेनार्शांसि दह्यन्ते यथा तूलञ्च वह्निना सौकुमार्याल्पकायत्वान्मद्यसेवी यदा नरः जीर्णमद्यादियुक्तादिभोजनैः सह दापयेत्","text":"anenārśāṃsi dahyante yathā tūlañca vahninā saukumāryālpakāyatvānmadyasevī yadā naraḥ jīrṇamadyādiyuktādibhojanaiḥ saha dāpayet"},{"type":"verse","number":"120","sanskrit":"लावतित्तिरिवर्त्तीर मयूरशशकादयः चटकः कलविङ्कश्च वर्त्तका हरितालकः","text":"lāvatittirivarttīra mayūraśaśakādayaḥ caṭakaḥ kalaviṅkaśca varttakā haritālakaḥ"},{"type":"verse","number":"121","sanskrit":"श्येनकश्च बृहल्लावो वनविष्किरकादयः पारावतमृगादीनां मांसं जाङ्गलकं शुभम्","text":"śyenakaśca bṛhallāvo vanaviṣkirakādayaḥ pārāvatamṛgādīnāṃ māṃsaṃ jāṅgalakaṃ śubham"},{"type":"verse","number":"122","sanskrit":"मद्गुरो रोहितः श्रेष्ठः शकुलश्च विशेषतः मत्स्यराजा इति प्रोक्ता हितमत्स्याय देहिने","text":"madguro rohitaḥ śreṣṭhaḥ śakulaśca viśeṣataḥ matsyarājā iti proktā hitamatsyāya dehine"},{"type":"verse","number":"123","sanskrit":"वृन्ताकस्य फलं शस्तं पटोलं बृहतीफलम् प्रलम्बाभीरुवेत्राग्रताडकं तण्डुलीयकम्","text":"vṛntākasya phalaṃ śastaṃ paṭolaṃ bṛhatīphalam pralambābhīruvetrāgratāḍakaṃ taṇḍulīyakam"},{"type":"verse","number":"124","sanskrit":"वास्तूकं धान्यशाकञ्च चित्रकं चक्रमर्दकम् नालिकेरञ्च खर्जूरं दाडिमं लवलीफलम्","text":"vāstūkaṃ dhānyaśākañca citrakaṃ cakramardakam nālikerañca kharjūraṃ dāḍimaṃ lavalīphalam"},{"type":"verse","number":"125","sanskrit":"शृङ्गाटकञ्च पक्वाम्रं द्रा क्षातालफलानि च जातिकोशं लवङ्गं च पूगं ताम्बूलपत्रकम् हितान्येतानि वस्तूनि लोहमेतत्समश्नताम्","text":"śṛṅgāṭakañca pakvāmraṃ drā kṣātālaphalāni ca jātikośaṃ lavaṅgaṃ ca pūgaṃ tāmbūlapatrakam hitānyetāni vastūni lohametatsamaśnatām"},{"type":"verse","number":"126","sanskrit":"नाश्नीयाल्लकुचं कोलकर्कन्धूबदराणि च","text":"nāśnīyāllakucaṃ kolakarkandhūbadarāṇi ca"},{"type":"verse","number":"127","sanskrit":"जम्बीरं बीजपूरञ्च तिन्तिडीं करमर्दकम् आनूपानि च मांसानि क्रकरं पुण्ड्रकाणि च","text":"jambīraṃ bījapūrañca tintiḍīṃ karamardakam ānūpāni ca māṃsāni krakaraṃ puṇḍrakāṇi ca"},{"type":"verse","number":"128","sanskrit":"हंससारसदात्यूहचाषक्रौञ्चबलाकिकाः मानकन्दं कसेरूणि करकञ्च कलिङ्गकम्","text":"haṃsasārasadātyūhacāṣakrauñcabalākikāḥ mānakandaṃ kaserūṇi karakañca kaliṅgakam"},{"type":"verse","number":"129","sanskrit":"कूष्माण्डकञ्च कर्कोटं क्रमुकञ्च विशेपतः कटुकं कालशाकञ्च कुण्टुरुः कर्कटीं तथा","text":"kūṣmāṇḍakañca karkoṭaṃ kramukañca viśepataḥ kaṭukaṃ kālaśākañca kuṇṭuruḥ karkaṭīṃ tathā"},{"type":"verse","number":"130","sanskrit":"ककारादीनि सर्वाणि द्विदलानि च वर्जयेत्","text":"kakārādīni sarvāṇi dvidalāni ca varjayet"},{"type":"verse","number":"131","sanskrit":"शङ्करेण समाख्यातो यक्षराजानुकम्पया जगतामुपकाराय दुर्नामारिरयं ध्रुवम्","text":"śaṅkareṇa samākhyāto yakṣarājānukampayā jagatāmupakārāya durnāmārirayaṃ dhruvam"},{"type":"verse","number":"132","sanskrit":"स्थानाच्चलति मेरुश्च पृथ्वी पर्येति वायुना पतन्ति चन्द्र ताराश्च मिथ्या चेदहमब्रुवम्","text":"sthānāccalati meruśca pṛthvī paryeti vāyunā patanti candra tārāśca mithyā cedahamabruvam"},{"type":"verse","number":"133","sanskrit":"ब्रह्मघ्नाश्च कृतघ्नाश्च क्रूरा येऽसत्यवादिनः वर्जनीयाः सधर्मेण भिषजा गुरुनिन्दकाः","text":"brahmaghnāśca kṛtaghnāśca krūrā ye'satyavādinaḥ varjanīyāḥ sadharmeṇa bhiṣajā gurunindakāḥ"},{"type":"verse","number":"134","sanskrit":"मुनिरसपिष्टविडङ्ग मुनिरसलीढं चिरस्थितं घर्मे द्रा वयति लोहदोषान्वह्निर्नवनीतपिण्डमिव","text":"munirasapiṣṭaviḍaṅga munirasalīḍhaṃ cirasthitaṃ gharme drā vayati lohadoṣānvahnirnavanītapiṇḍamiva"},{"type":"verse","number":"135","sanskrit":"कालेमलप्रवृत्तिर्लाघवमुदरे विशुद्धिरुद्गारे अङ्गेषु नावसादो मनः प्रसादोऽस्य परिपाके","text":"kālemalapravṛttirlāghavamudare viśuddhirudgāre aṅgeṣu nāvasādo manaḥ prasādo'sya paripāke"},{"type":"verse","number":"136","sanskrit":"क्रिमिरिपुर्चूर्णं लीढं सहितं स्वरसेन वङ्गसेनस्य क्षपयत्यचिरान्नियतं लोहाजीर्णोद्भवं शूलम्","text":"krimiripurcūrṇaṃ līḍhaṃ sahitaṃ svarasena vaṅgasenasya kṣapayatyacirānniyataṃ lohājīrṇodbhavaṃ śūlam"},{"type":"verse","number":"137","sanskrit":"भवेद्यद्यतिसारस्तु दुग्धं पीत्वा तु तं जयेत् गुञ्जाद्वादशकादूर्ध्वं वृद्धिरस्य भयप्रदा","text":"bhavedyadyatisārastu dugdhaṃ pītvā tu taṃ jayet guñjādvādaśakādūrdhvaṃ vṛddhirasya bhayapradā"},{"type":"verse","number":"138","sanskrit":"रक्तार्शसामुपेक्षेत रक्तमादौ स्रवद्भिषक् दुष्टास्रे निःसृते न स्युः शूलानाहासृगामयाः","text":"raktārśasāmupekṣeta raktamādau sravadbhiṣak duṣṭāsre niḥsṛte na syuḥ śūlānāhāsṛgāmayāḥ"},{"type":"verse","number":"139","sanskrit":"चन्दनादिक्वाथः चन्दनकिराततिक्तकधन्वयवासाः सनागराः क्वथिताः रक्तार्शसां प्रशमना दार्वीत्वगुशीरनिम्बाश्च","text":"candanādikvāthaḥ candanakirātatiktakadhanvayavāsāḥ sanāgarāḥ kvathitāḥ raktārśasāṃ praśamanā dārvītvaguśīranimbāśca"},{"type":"verse","number":"140","sanskrit":"नवनीततिलाभ्यासात्केशरनवनीतशर्कराऽभ्यासात् दधिसरमथिताभ्यासाद् गुदजाः शाम्यन्ति रक्तवहाः","text":"navanītatilābhyāsātkeśaranavanītaśarkarā'bhyāsāt dadhisaramathitābhyāsād gudajāḥ śāmyanti raktavahāḥ"},{"type":"verse","number":"141","sanskrit":"सपद्मकेशरं क्षौद्रं नवनीतं नवं लिहन् सिताकेशरसंयुक्तं रक्तार्शसि सुखी भवेत्","text":"sapadmakeśaraṃ kṣaudraṃ navanītaṃ navaṃ lihan sitākeśarasaṃyuktaṃ raktārśasi sukhī bhavet"},{"type":"verse","number":"142","sanskrit":"पयसा शृतेन यूषैः सतीनमुद्गाढकीमसूराणाम् ओदनमद्यादम्लैः शालिश्यामाककोद्र वजम् शशहरिणलावमांसैः कपिञ्जलैरेणमांसैश्च","text":"payasā śṛtena yūṣaiḥ satīnamudgāḍhakīmasūrāṇām odanamadyādamlaiḥ śāliśyāmākakodra vajam śaśahariṇalāvamāṃsaiḥ kapiñjalaireṇamāṃsaiśca"},{"type":"verse","number":"143","sanskrit":"समङ्गोत्पलमोचाकतिरीटोत्पलचन्दनैः सिद्धं छागीपयो दद्याद् गुदजे शोणितात्मके","text":"samaṅgotpalamocākatirīṭotpalacandanaiḥ siddhaṃ chāgīpayo dadyād gudaje śoṇitātmake"},{"type":"verse","number":"144","sanskrit":"भावितं रजनीचूर्णं स्नुहीक्षीरैः पुनः पुनः बन्धनात्सुदृढं सूत्रं छिनत्त्यर्शो भगन्दरम्","text":"bhāvitaṃ rajanīcūrṇaṃ snuhīkṣīraiḥ punaḥ punaḥ bandhanātsudṛḍhaṃ sūtraṃ chinattyarśo bhagandaram"},{"type":"verse","number":"145","sanskrit":"नासानाभिसमुत्थेषु तथा मेढ्रादिजेष्वपि त्रिष्वप्यर्शःसु कुर्वीत तत्र तत्र यथोचितम्","text":"nāsānābhisamuttheṣu tathā meḍhrādijeṣvapi triṣvapyarśaḥsu kurvīta tatra tatra yathocitam"},{"type":"verse","number":"146","sanskrit":"चर्मकीलन्तु संछिद्य दहेत्क्षारेण चाग्निना","text":"carmakīlantu saṃchidya dahetkṣāreṇa cāgninā"},{"type":"verse","number":"147","sanskrit":"स्त्रीपृष्ठं वेगरोधं च यानान्युत्कटकासनम् यथास्वं दोषलं चान्नमर्शसः परिवर्जयेत्","text":"strīpṛṣṭhaṃ vegarodhaṃ ca yānānyutkaṭakāsanam yathāsvaṃ doṣalaṃ cānnamarśasaḥ parivarjayet"},{"type":"verse","number":"148","sanskrit":"इति पञ्चमोऽशोरोगाधिकारः समाप्तः ५","text":"iti pañcamo'śorogādhikāraḥ samāptaḥ 5"}]},{"sthana":"Уттаракханда","number":6,"lang":"sa","content":[{"type":"heading","heading":"Джатхарагни — расстройства пищеварит. огня"},{"type":"verse","number":"1","sanskrit":"कफपित्तानिलाधिक्यात्तत्साम्याज्जाठरोऽनलः मन्दस्तीक्ष्णोऽथविषमः समश्चेति चतुर्विधः","text":"kaphapittānilādhikyāttatsāmyājjāṭharo'nalaḥ mandastīkṣṇo'thaviṣamaḥ samaśceti caturvidhaḥ"},{"type":"verse","number":"2","sanskrit":"स्वल्पाऽपि नैव मन्दाग्नेर्मात्रा भुक्ता विपच्यते छर्दिः सादः प्रसेकः स्याच्छिरोजठरगौरवम्","text":"svalpā'pi naiva mandāgnermātrā bhuktā vipacyate chardiḥ sādaḥ prasekaḥ syācchirojaṭharagauravam"},{"type":"verse","number":"3","sanskrit":"मात्रातिमात्राऽप्यशिता तीक्ष्णाग्नेः पच्यते सुखम् अतएव हि केनापि मतस्तीक्ष्णाग्निरुत्तमः","text":"mātrātimātrā'pyaśitā tīkṣṇāgneḥ pacyate sukham ataeva hi kenāpi matastīkṣṇāgniruttamaḥ"},{"type":"verse","number":"4","sanskrit":"अशिता खलु मात्राऽपि विषमाग्नेस्तु देहिनः कदाचित्पच्यते सम्यक् कदाचिन्न विपच्यते","text":"aśitā khalu mātrā'pi viṣamāgnestu dehinaḥ kadācitpacyate samyak kadācinna vipacyate"},{"type":"verse","number":"5","sanskrit":"तस्याध्मानमुदावर्त्तं शूलं जठरगौरवम् प्रवाहणमतीसारस्तथा स्यादन्त्रकूजनम्","text":"tasyādhmānamudāvarttaṃ śūlaṃ jaṭharagauravam pravāhaṇamatīsārastathā syādantrakūjanam"},{"type":"verse","number":"6","sanskrit":"समा समाग्नेरशिता मात्रा सम्यग्विपच्यते एषां मध्ये तु सर्वेषां समाग्निः श्रेष्ठ उच्यते","text":"samā samāgneraśitā mātrā samyagvipacyate eṣāṃ madhye tu sarveṣāṃ samāgniḥ śreṣṭha ucyate"},{"type":"verse","number":"7","sanskrit":"अतिमात्रमजीर्णेऽपि गुरु चान्नं समश्नतः दिवाऽपि स्वपतो येन पच्यते सोऽग्निरुत्तमः","text":"atimātramajīrṇe'pi guru cānnaṃ samaśnataḥ divā'pi svapato yena pacyate so'gniruttamaḥ"},{"type":"verse","number":"8","sanskrit":"तीक्ष्णः पित्तसमुत्थानान्विषमो वातहेतुकान् तथा करोति मन्दाग्निर्विकारान् कफसम्भवान्","text":"tīkṣṇaḥ pittasamutthānānviṣamo vātahetukān tathā karoti mandāgnirvikārān kaphasambhavān"},{"type":"verse","number":"9","sanskrit":"बह्वर्त्तिरुक्षान्नभुजां नराणां क्षीणे कफे मारुतपित्तवृद्धौ अतिप्रवृद्धः पवनान्वितोऽग्निर्भुक्तं क्षणाद्भस्म करोति यस्मात् तस्मादसौ भस्मकसंज्ञकोऽभूदुपेक्षितोऽय पचते च धातून्","text":"bahvarttirukṣānnabhujāṃ narāṇāṃ kṣīṇe kaphe mārutapittavṛddhau atipravṛddhaḥ pavanānvito'gnirbhuktaṃ kṣaṇādbhasma karoti yasmāt tasmādasau bhasmakasaṃjñako'bhūdupekṣito'ya pacate ca dhātūn"},{"type":"verse","number":"10","sanskrit":"तृट्स्वेददाहमूर्च्छादीन्कृत्वैषोऽत्यग्निसम्भवान् पक्त्वाऽन्नमाशु धात्वादीन् स क्षिप्रं नाशयेद् ध्रुवम्","text":"tṛṭsvedadāhamūrcchādīnkṛtvaiṣo'tyagnisambhavān paktvā'nnamāśu dhātvādīn sa kṣipraṃ nāśayed dhruvam"},{"type":"verse","number":"11","sanskrit":"अत्यम्बुपानाद्विषमाशनाच्च सन्धारणात् स्वप्नविपर्ययाच्च कालेऽपि सात्म्यं लघु चापि भुक्तमन्नं न पाकं भजते नरस्य","text":"atyambupānādviṣamāśanācca sandhāraṇāt svapnaviparyayācca kāle'pi sātmyaṃ laghu cāpi bhuktamannaṃ na pākaṃ bhajate narasya"},{"type":"verse","number":"12","sanskrit":"तृष्णाभयक्रोधपरिप्लुतेन लुब्धेन रुग्दैन्यनिपीडितेन प्रद्वेषयुक्तेन च सेव्यमानमन्नं न सम्यक् परिपाकमेति","text":"tṛṣṇābhayakrodhapariplutena lubdhena rugdainyanipīḍitena pradveṣayuktena ca sevyamānamannaṃ na samyak paripākameti"},{"type":"verse","number":"13","sanskrit":"अनात्मवन्तः पशुवद् भुञ्जते येऽप्रमाणतः रोगानीकस्य ते मूलमजीर्णं प्राप्नुवन्ति हि","text":"anātmavantaḥ paśuvad bhuñjate ye'pramāṇataḥ rogānīkasya te mūlamajīrṇaṃ prāpnuvanti hi"},{"type":"verse","number":"14","sanskrit":"प्रायेणाहारवैषम्यादजीर्णं जायते नृणाम् तन्मूलो रोगसङ्घातस्तद्विनाशाद्विनश्यति","text":"prāyeṇāhāravaiṣamyādajīrṇaṃ jāyate nṛṇām tanmūlo rogasaṅghātastadvināśādvinaśyati"},{"type":"verse","number":"15","sanskrit":"ग्लानिगौरवविष्टम्भभ्रम मारुतमूढताः विबन्धो वा प्रवृत्तिर्वा सामान्याजीर्णलक्षणम्","text":"glānigauravaviṣṭambhabhrama mārutamūḍhatāḥ vibandho vā pravṛttirvā sāmānyājīrṇalakṣaṇam"},{"type":"verse","number":"16","sanskrit":"आमं विदग्धं विष्टव्धं कफपित्तानिलैस्त्रिभिः अजीर्णं केचिदिच्छन्ति चतुर्थं रसशेषतः","text":"āmaṃ vidagdhaṃ viṣṭavdhaṃ kaphapittānilaistribhiḥ ajīrṇaṃ kecidicchanti caturthaṃ rasaśeṣataḥ"},{"type":"verse","number":"17","sanskrit":"अजीर्णं पञ्चमं केचिन्निर्दोषं दिनपाकि च वदन्ति षष्ठञ्चाजीर्णं प्राकृतं प्रतिवासरम्","text":"ajīrṇaṃ pañcamaṃ kecinnirdoṣaṃ dinapāki ca vadanti ṣaṣṭhañcājīrṇaṃ prākṛtaṃ prativāsaram"},{"type":"verse","number":"18","sanskrit":"तत्रामे गुरुतोत्क्लेशः शोथो गण्डाक्षिकूटगः उद्गारश्च यथाभुक्तमविदग्धं प्रवर्त्तते","text":"tatrāme gurutotkleśaḥ śotho gaṇḍākṣikūṭagaḥ udgāraśca yathābhuktamavidagdhaṃ pravarttate"},{"type":"verse","number":"19","sanskrit":"विदग्धे भ्रमतृण्मूर्च्छाः पित्ताच्च विविधा रुजः उद्गारश्च सधूमाम्लः स्वेदो दाहश्च जायते","text":"vidagdhe bhramatṛṇmūrcchāḥ pittācca vividhā rujaḥ udgāraśca sadhūmāmlaḥ svedo dāhaśca jāyate"},{"type":"verse","number":"20","sanskrit":"विष्टब्धे शूलमाध्मानं विविधा वातवेदनाः मलवाताप्रवृत्तिश्च स्तम्भो मोहोऽङ्गपीडनम्","text":"viṣṭabdhe śūlamādhmānaṃ vividhā vātavedanāḥ malavātāpravṛttiśca stambho moho'ṅgapīḍanam"},{"type":"verse","number":"21","sanskrit":"रसशेषेऽन्नविद्वेषो हृदयाशुद्धिगौरवे","text":"rasaśeṣe'nnavidveṣo hṛdayāśuddhigaurave"},{"type":"verse","number":"22","sanskrit":"मूर्च्छा प्रलापो वमथुः प्रसेकः सदनं भ्रमः उपद्र वा भवन्त्येते मरणञ्चाप्यजीर्णतः","text":"mūrcchā pralāpo vamathuḥ prasekaḥ sadanaṃ bhramaḥ upadra vā bhavantyete maraṇañcāpyajīrṇataḥ"},{"type":"verse","number":"23","sanskrit":"आमं विदग्धं विष्टव्धमित्यजीर्णं यदीरितम् विसूच्यलसकौ तस्माद्भवेच्चापि विलम्बिका","text":"āmaṃ vidagdhaṃ viṣṭavdhamityajīrṇaṃ yadīritam visūcyalasakau tasmādbhaveccāpi vilambikā"},{"type":"verse","number":"24","sanskrit":"सूचीभिरिव गात्राणि तुदन्सन्तिष्ठतेऽनिलः यत्राजीर्णेन सा वैद्यैर्विसूचीति निगद्यते","text":"sūcībhiriva gātrāṇi tudansantiṣṭhate'nilaḥ yatrājīrṇena sā vaidyairvisūcīti nigadyate"},{"type":"verse","number":"25","sanskrit":"न तां परिमिताहारा लभन्ते विदितागमाः मूढास्तामजितात्मानो लभन्तेऽशनलोलुपाः","text":"na tāṃ parimitāhārā labhante viditāgamāḥ mūḍhāstāmajitātmāno labhante'śanalolupāḥ"},{"type":"verse","number":"26","sanskrit":"मूर्च्छाऽतिसारौ वमथुः पिपासा शूलं भ्रमोद्वेष्टनजृम्भदाहाः वैवर्ण्यकम्पौ हृदये रुजश्च भवन्ति तस्यां शिरसश्च भेदः","text":"mūrcchā'tisārau vamathuḥ pipāsā śūlaṃ bhramodveṣṭanajṛmbhadāhāḥ vaivarṇyakampau hṛdaye rujaśca bhavanti tasyāṃ śirasaśca bhedaḥ"},{"type":"verse","number":"27","sanskrit":"निद्रा नाशोऽरतिः कम्पो मूत्राघातो विसंज्ञता अमी उपद्र वा घोरा विसूच्याः पञ्च दारुणाः","text":"nidrā nāśo'ratiḥ kampo mūtrāghāto visaṃjñatā amī upadra vā ghorā visūcyāḥ pañca dāruṇāḥ"},{"type":"verse","number":"28","sanskrit":"कुक्षिरानह्यतेऽत्यर्थं प्रताम्यत्यथ कूजति निरुद्धो मारुतश्चैव कुक्षावुपरि धावति","text":"kukṣirānahyate'tyarthaṃ pratāmyatyatha kūjati niruddho mārutaścaiva kukṣāvupari dhāvati"},{"type":"verse","number":"29","sanskrit":"वातवर्चोनिरोधश्च यस्यात्यर्थं भवेदपि तस्यालसकमाचष्टे तृष्णोद्गारौ च यस्य तु","text":"vātavarconirodhaśca yasyātyarthaṃ bhavedapi tasyālasakamācaṣṭe tṛṣṇodgārau ca yasya tu"},{"type":"verse","number":"30","sanskrit":"नाधो याति न चाप्यूर्ध्वमाहारो यो नपच्यते कोष्ठे स्थितोऽलसीभूतस्ततोऽसावलसः स्मृतः","text":"nādho yāti na cāpyūrdhvamāhāro yo napacyate koṣṭhe sthito'lasībhūtastato'sāvalasaḥ smṛtaḥ"},{"type":"verse","number":"31","sanskrit":"यः श्यावदन्तौष्ठनखोऽल्पसंज्ञो वम्यर्दितोऽभ्यन्तरयातनेत्रः क्षामस्वरः सर्वविमुक्तसन्धिर्यायान्नरोऽसौ पुनरागमाय","text":"yaḥ śyāvadantauṣṭhanakho'lpasaṃjño vamyardito'bhyantarayātanetraḥ kṣāmasvaraḥ sarvavimuktasandhiryāyānnaro'sau punarāgamāya"},{"type":"verse","number":"32","sanskrit":"दुष्टन्तु भुक्तं कफमारुताभ्यां प्रवर्त्तते नोर्ध्वमधश्च यत्र विलम्बिकां तां भृशदुश्चिकित्स्यामाचक्षते शास्त्रविदः पुराणाः","text":"duṣṭantu bhuktaṃ kaphamārutābhyāṃ pravarttate nordhvamadhaśca yatra vilambikāṃ tāṃ bhṛśaduścikitsyāmācakṣate śāstravidaḥ purāṇāḥ"},{"type":"verse","number":"33","sanskrit":"उद्गारशुद्धिरुत्साहो वेगोत्सर्गो यथोचितः लघुता क्षुत्पिपासा च जीर्णाहारस्य लक्षणम्","text":"udgāraśuddhirutsāho vegotsargo yathocitaḥ laghutā kṣutpipāsā ca jīrṇāhārasya lakṣaṇam"},{"type":"verse","number":"34","sanskrit":"हरीतकी तथा शुण्ठी भक्ष्यमाणा गुडेन च सैन्धवेन युता वा स्यात्सातत्येनाग्निदीपनी","text":"harītakī tathā śuṇṭhī bhakṣyamāṇā guḍena ca saindhavena yutā vā syātsātatyenāgnidīpanī"},{"type":"verse","number":"35","sanskrit":"गुडेन शुण्ठीमथ चोपकुल्यां पथ्यां तृतीयामथ दाडिमं वा आमेष्वजीर्णेषु गुदामयेषु वर्चोविबन्धेषु च नित्यमद्यात्","text":"guḍena śuṇṭhīmatha copakulyāṃ pathyāṃ tṛtīyāmatha dāḍimaṃ vā āmeṣvajīrṇeṣu gudāmayeṣu varcovibandheṣu ca nityamadyāt"},{"type":"verse","number":"36","sanskrit":"व्योषं दन्तीं त्रिवृच्चित्रं कृष्णामूलं विचूर्णितम् तच्चूर्णं गुडसम्मिश्रं भक्षयेत्प्रातरुत्थितः","text":"vyoṣaṃ dantīṃ trivṛccitraṃ kṛṣṇāmūlaṃ vicūrṇitam taccūrṇaṃ guḍasammiśraṃ bhakṣayetprātarutthitaḥ"},{"type":"verse","number":"37","sanskrit":"एतद् गुडाष्टकं नाम बलवर्णाग्निवर्द्धनम् शोथोदावर्त्तशूलघ्नं प्लीहपाण्ड्वामयापहम्","text":"etad guḍāṣṭakaṃ nāma balavarṇāgnivarddhanam śothodāvarttaśūlaghnaṃ plīhapāṇḍvāmayāpaham"},{"type":"verse","number":"38","sanskrit":"दहनाजमोदसैन्धवनागरमरिचानि चाम्लतक्रेण सप्ताहादग्निकरं पाण्ड्वर्शोनाशनं परमम्","text":"dahanājamodasaindhavanāgaramaricāni cāmlatakreṇa saptāhādagnikaraṃ pāṇḍvarśonāśanaṃ paramam"},{"type":"verse","number":"39","sanskrit":"तत्रामे वमनं कार्यं विदग्धे लङ्घनं हितम् विष्टब्धे स्वेदनं शस्तं रसशेषे शयीत च","text":"tatrāme vamanaṃ kāryaṃ vidagdhe laṅghanaṃ hitam viṣṭabdhe svedanaṃ śastaṃ rasaśeṣe śayīta ca"},{"type":"verse","number":"40","sanskrit":"वचालवणतोयेन वान्तिरामे प्रशस्यते कंणासिन्धुवचाकल्कं पीत्वा वा शिशिराम्भसा","text":"vacālavaṇatoyena vāntirāme praśasyate kaṃṇāsindhuvacākalkaṃ pītvā vā śiśirāmbhasā"},{"type":"verse","number":"41","sanskrit":"धान्यनागरसिद्धं वा तोयं दद्याद्विचक्षणः आमाजीर्णप्रशमनं शूलघ्नं वस्तिशोधनम्","text":"dhānyanāgarasiddhaṃ vā toyaṃ dadyādvicakṣaṇaḥ āmājīrṇapraśamanaṃ śūlaghnaṃ vastiśodhanam"},{"type":"verse","number":"42","sanskrit":"भवेद्यदा प्रातरजीर्णशङ्का तदाऽभयां नागरसैन्धवाभ्याम् विचूर्णितां शीतजलेन भुक्त्वा भुञ्ज्यादशङ्कं मितमन्नकाले","text":"bhavedyadā prātarajīrṇaśaṅkā tadā'bhayāṃ nāgarasaindhavābhyām vicūrṇitāṃ śītajalena bhuktvā bhuñjyādaśaṅkaṃ mitamannakāle"},{"type":"verse","number":"43","sanskrit":"विदह्यते यस्य तु भुक्तमात्रं दन्दह्यते हृच्च गलश्च यस्य द्रा क्षां सितामाक्षिकसम्प्रयुक्तां लीढ्वाऽभयां चापि सुखं लभेत","text":"vidahyate yasya tu bhuktamātraṃ dandahyate hṛcca galaśca yasya drā kṣāṃ sitāmākṣikasamprayuktāṃ līḍhvā'bhayāṃ cāpi sukhaṃ labheta"},{"type":"verse","number":"44","sanskrit":"त्रिकटुकमजमोदा सैन्धवं जीरके द्वे समधरणधृतानामष्टमो हिङ्गुभागः प्रथमकवलभुक्तं सर्पिषा चूर्णमेतज्जनयति जठराग्निं वातरोगांश्च हन्ति","text":"trikaṭukamajamodā saindhavaṃ jīrake dve samadharaṇadhṛtānāmaṣṭamo hiṅgubhāgaḥ prathamakavalabhuktaṃ sarpiṣā cūrṇametajjanayati jaṭharāgniṃ vātarogāṃśca hanti"},{"type":"verse","number":"45","sanskrit":"द्वौ क्षारौ चित्रकं पाठा करञ्जं लवणानि च सूक्ष्मैला पत्रकं भार्गी कृमिघ्नं हिङ्गु पौष्करम्","text":"dvau kṣārau citrakaṃ pāṭhā karañjaṃ lavaṇāni ca sūkṣmailā patrakaṃ bhārgī kṛmighnaṃ hiṅgu pauṣkaram"},{"type":"verse","number":"46","sanskrit":"शटी दार्वी त्रिवृन्मुस्तं वचा चेन्द्र यवास्तथा वृक्षाम्लं जीरकं धात्री श्रेयसी चोपकुञ्चिका","text":"śaṭī dārvī trivṛnmustaṃ vacā cendra yavāstathā vṛkṣāmlaṃ jīrakaṃ dhātrī śreyasī copakuñcikā"},{"type":"verse","number":"47","sanskrit":"अम्लवेतसमम्लीका यवानी देवदारु च अभयाऽतिविषा श्यामा हपुषाऽरग्वधं समम्","text":"amlavetasamamlīkā yavānī devadāru ca abhayā'tiviṣā śyāmā hapuṣā'ragvadhaṃ samam"},{"type":"verse","number":"48","sanskrit":"तिलमुष्ककशिग्रूणां कोकिलाक्षपलाशयोः क्षाराणि लौहकिट्टश्च तप्तं गोमूत्रसेचितम्","text":"tilamuṣkakaśigrūṇāṃ kokilākṣapalāśayoḥ kṣārāṇi lauhakiṭṭaśca taptaṃ gomūtrasecitam"},{"type":"verse","number":"49","sanskrit":"सूक्ष्मचूर्णानि कृत्वा तु समभागानि कारयेत् मातुलुङ्गरसेनैव प्रदीप्ताग्निसमप्रभम्","text":"sūkṣmacūrṇāni kṛtvā tu samabhāgāni kārayet mātuluṅgarasenaiva pradīptāgnisamaprabham"},{"type":"verse","number":"50","sanskrit":"दिनत्रयन्तु शुक्तेन तथाऽद्र करसेन च अत्यग्निकारकं चूर्णं प्रदीप्ताग्निसमप्रभम्","text":"dinatrayantu śuktena tathā'dra karasena ca atyagnikārakaṃ cūrṇaṃ pradīptāgnisamaprabham"},{"type":"verse","number":"51","sanskrit":"उपयुक्तं विधानेन नाशयत्यचिराद्गदान् अजीर्णमथ गुल्मञ्च प्लीहानं गुदजानि च","text":"upayuktaṃ vidhānena nāśayatyacirādgadān ajīrṇamatha gulmañca plīhānaṃ gudajāni ca"},{"type":"verse","number":"52","sanskrit":"तथान्त्रवृद्धिमुदराण्यष्ठीलां वातशोणितम् प्रणुदत्युल्वणान्दोषान्नष्टाग्निं च प्रदीपयेत्","text":"tathāntravṛddhimudarāṇyaṣṭhīlāṃ vātaśoṇitam praṇudatyulvaṇāndoṣānnaṣṭāgniṃ ca pradīpayet"},{"type":"verse","number":"53","sanskrit":"स्नुह्यर्कचित्रकैरण्डवरुणं सपुनर्नवम् तिलापामार्गकदलीपलाशं तिन्तिडीं तथा","text":"snuhyarkacitrakairaṇḍavaruṇaṃ sapunarnavam tilāpāmārgakadalīpalāśaṃ tintiḍīṃ tathā"},{"type":"verse","number":"54","sanskrit":"गृहीत्वा ज्वालयेदेतत्प्रस्थं भस्माखिलं यथा जंलाढके विपक्तव्यं यावत्पादावशेषितम्","text":"gṛhītvā jvālayedetatprasthaṃ bhasmākhilaṃ yathā jaṃlāḍhake vipaktavyaṃ yāvatpādāvaśeṣitam"},{"type":"verse","number":"55","sanskrit":"सुप्रसन्नं विनिस्राव्य लवणप्रस्थसंयुतम् पक्वं निर्धूमकठिनं सूक्ष्मचूर्णीकृतं पुनः","text":"suprasannaṃ vinisrāvya lavaṇaprasthasaṃyutam pakvaṃ nirdhūmakaṭhinaṃ sūkṣmacūrṇīkṛtaṃ punaḥ"},{"type":"verse","number":"56","sanskrit":"यवानीजीरकव्योष स्थूलजीरकहिङ्गुभिः पृथगर्धपलैरेभिश्चूर्णि तैस्तद्विमिश्रयेत्","text":"yavānījīrakavyoṣa sthūlajīrakahiṅgubhiḥ pṛthagardhapalairebhiścūrṇi taistadvimiśrayet"},{"type":"verse","number":"57","sanskrit":"आर्द्र कस्वरसेनापि भावयेच्छोषयेत् पुनः शीतोदकेन तच्चूर्णं पिबेत्प्रातर्हि मात्रया","text":"ārdra kasvarasenāpi bhāvayecchoṣayet punaḥ śītodakena taccūrṇaṃ pibetprātarhi mātrayā"},{"type":"verse","number":"58","sanskrit":"तस्मिञ्जीर्णेऽन्नमश्नीयाद्यूषैर्जाङ्गलजैः रसैः ईषदम्लैः सलवणैः सुखोष्णैर्वह्निदीपनैः","text":"tasmiñjīrṇe'nnamaśnīyādyūṣairjāṅgalajaiḥ rasaiḥ īṣadamlaiḥ salavaṇaiḥ sukhoṣṇairvahnidīpanaiḥ"},{"type":"verse","number":"59","sanskrit":"एतेनाग्निर्विवर्द्धेत बलमारोग्यमेव च तत्रानुपानं शस्तं हि तक्रं वा भोजने हितम्","text":"etenāgnirvivarddheta balamārogyameva ca tatrānupānaṃ śastaṃ hi takraṃ vā bhojane hitam"},{"type":"verse","number":"60","sanskrit":"मन्दाग्न्यर्शोविकारेषु वातश्लेष्मामयेषु च अश्मर्यां शर्करायाञ्च विण्मूत्रानिलरोगिषु","text":"mandāgnyarśovikāreṣu vātaśleṣmāmayeṣu ca aśmaryāṃ śarkarāyāñca viṇmūtrānilarogiṣu"},{"type":"verse","number":"61","sanskrit":"सामुद्र लवणं कार्यमष्टकर्षमितं बुधैः सौवर्चलं पञ्चकर्षं विडसैन्धवधान्यकम्","text":"sāmudra lavaṇaṃ kāryamaṣṭakarṣamitaṃ budhaiḥ sauvarcalaṃ pañcakarṣaṃ viḍasaindhavadhānyakam"},{"type":"verse","number":"62","sanskrit":"पिप्पली पिप्पलीमूलं पत्रकं कृष्णजीरकम् तालीशं केशरं चव्यमम्लवेतसकं तथा","text":"pippalī pippalīmūlaṃ patrakaṃ kṛṣṇajīrakam tālīśaṃ keśaraṃ cavyamamlavetasakaṃ tathā"},{"type":"verse","number":"63","sanskrit":"द्विकर्षमात्राण्येतानि प्रत्येकं कारयेद् बुधः मरिचं जीरकं विश्वमेकैकं कर्षमात्रकम्","text":"dvikarṣamātrāṇyetāni pratyekaṃ kārayed budhaḥ maricaṃ jīrakaṃ viśvamekaikaṃ karṣamātrakam"},{"type":"verse","number":"64","sanskrit":"दाडिमं स्याच्चतुष्कर्षं त्वगेला चार्द्धकार्षिकी एतच्चूर्णीकृतं सर्वं लवणं भास्कराभिधम्","text":"dāḍimaṃ syāccatuṣkarṣaṃ tvagelā cārddhakārṣikī etaccūrṇīkṛtaṃ sarvaṃ lavaṇaṃ bhāskarābhidham"},{"type":"verse","number":"65","sanskrit":"भक्षयेच्छाणमानन्तु तक्रमस्तुककाञ्जिकैः वातश्लेष्मभवं गुल्मं प्लीहानमुदरं क्षयम्","text":"bhakṣayecchāṇamānantu takramastukakāñjikaiḥ vātaśleṣmabhavaṃ gulmaṃ plīhānamudaraṃ kṣayam"},{"type":"verse","number":"66","sanskrit":"अर्शांसि ग्रहणीं कुष्ठं विबन्धञ्च भगन्दरम् शूलं शोथं श्वासकासाऽमदोषांश्चापि हृद्रुजम्","text":"arśāṃsi grahaṇīṃ kuṣṭhaṃ vibandhañca bhagandaram śūlaṃ śothaṃ śvāsakāsā'madoṣāṃścāpi hṛdrujam"},{"type":"verse","number":"67","sanskrit":"अश्मरीं शर्कराञ्चापि पाण्डुरोगं कृमीनपि मन्दाग्निं नाशयेदेतद्दीपनं पाचनं परम्","text":"aśmarīṃ śarkarāñcāpi pāṇḍurogaṃ kṛmīnapi mandāgniṃ nāśayedetaddīpanaṃ pācanaṃ param"},{"type":"verse","number":"68","sanskrit":"हिताय सर्वलोकानां भास्करेण विनिर्मितम् हन्यात्सर्वाण्यजीर्णानि भुक्तमात्रमसंशयम्","text":"hitāya sarvalokānāṃ bhāskareṇa vinirmitam hanyātsarvāṇyajīrṇāni bhuktamātramasaṃśayam"},{"type":"verse","number":"69","sanskrit":"सैन्धवसमूलमागधक्षव्यानलनागरं पथ्या क्रमवृद्धमग्निवृद्धौ वडवाऽनलनामचूर्णं स्यात्","text":"saindhavasamūlamāgadhakṣavyānalanāgaraṃ pathyā kramavṛddhamagnivṛddhau vaḍavā'nalanāmacūrṇaṃ syāt"},{"type":"verse","number":"70","sanskrit":"पथ्यानागरकृष्णाकरञ्जबिल्वाग्निभिः सितातुल्यैः वडवाऽनल इव जरयति बहु गुर्वतिभोजनं चूर्णम्","text":"pathyānāgarakṛṣṇākarañjabilvāgnibhiḥ sitātulyaiḥ vaḍavā'nala iva jarayati bahu gurvatibhojanaṃ cūrṇam"},{"type":"verse","number":"71","sanskrit":"एलात्वङ्नागपुष्पाणां मात्रोत्तरविवर्द्धिता मरिचं पिप्पली शुण्ठी चतुष्पञ्चषडुत्तरा","text":"elātvaṅnāgapuṣpāṇāṃ mātrottaravivarddhitā maricaṃ pippalī śuṇṭhī catuṣpañcaṣaḍuttarā"},{"type":"verse","number":"72","sanskrit":"द्र व्याण्येतानि यावन्ति तावती सितशर्करा चूर्णमेतत्प्रयोक्तव्यमग्निसन्दीपनं परम्","text":"dra vyāṇyetāni yāvanti tāvatī sitaśarkarā cūrṇametatprayoktavyamagnisandīpanaṃ param"},{"type":"verse","number":"73","sanskrit":"द्विपलं गन्धकं शुद्धं पलमेकन्तु पारदम् मृतलोहं तथा ताम्रं कर्षद्वयमितं पृथक्","text":"dvipalaṃ gandhakaṃ śuddhaṃ palamekantu pāradam mṛtalohaṃ tathā tāmraṃ karṣadvayamitaṃ pṛthak"},{"type":"verse","number":"74","sanskrit":"सञ्चूर्ण्य सर्वं सम्मिश्रं द्रा वयित्वाऽग्नियोगतः सम्यग् द्रुतं समस्तं तत्पञ्चाङ्गुलदले क्षिपेत्","text":"sañcūrṇya sarvaṃ sammiśraṃ drā vayitvā'gniyogataḥ samyag drutaṃ samastaṃ tatpañcāṅguladale kṣipet"},{"type":"verse","number":"75","sanskrit":"पुनः सञ्चूर्ण्य तत्सर्वं लोहपात्रं निधापयेत् जम्बीरस्य रसं तत्र पूतं पलशतं क्षिपेत्","text":"punaḥ sañcūrṇya tatsarvaṃ lohapātraṃ nidhāpayet jambīrasya rasaṃ tatra pūtaṃ palaśataṃ kṣipet"},{"type":"verse","number":"76","sanskrit":"चुल्ल्यां निवेश्य तद्यत्नान्मृदुना वह्निना पचेत् रसे तस्मिन्घनीभूते तत्संशोष्य विचूर्णयेत्","text":"cullyāṃ niveśya tadyatnānmṛdunā vahninā pacet rase tasminghanībhūte tatsaṃśoṣya vicūrṇayet"},{"type":"verse","number":"77","sanskrit":"पञ्चकोलकषायस्य चुक्रेण सहितस्य च भावना तत्र दातव्या पश्चात्संशोषयेच्छनैः","text":"pañcakolakaṣāyasya cukreṇa sahitasya ca bhāvanā tatra dātavyā paścātsaṃśoṣayecchanaiḥ"},{"type":"verse","number":"78","sanskrit":"भृष्टटङ्कणचूर्णेन तुल्येन सह मेलयेत् मरिचेनापि तुल्येन तदर्द्धेन विडेन च","text":"bhṛṣṭaṭaṅkaṇacūrṇena tulyena saha melayet maricenāpi tulyena tadarddhena viḍena ca"},{"type":"verse","number":"79","sanskrit":"भावयेत्सप्तकृत्वस्तु चणकाम्लजलेन च ततः संशोष्य सम्पिष्य कूपीमध्ये निधापयेत्","text":"bhāvayetsaptakṛtvastu caṇakāmlajalena ca tataḥ saṃśoṣya sampiṣya kūpīmadhye nidhāpayet"},{"type":"verse","number":"80","sanskrit":"रसः क्रव्यादनामाऽय भैरवानन्दयोगिना उक्तः सिंहलराजाय बहुमांसाशिने पुरा","text":"rasaḥ kravyādanāmā'ya bhairavānandayoginā uktaḥ siṃhalarājāya bahumāṃsāśine purā"},{"type":"verse","number":"81","sanskrit":"भक्षयेद्भोजनस्यान्ते माषद्वयमितं रसम् भक्षयित्वा रसं पश्चात्पिबेत्तक्रं ससैन्धवम्","text":"bhakṣayedbhojanasyānte māṣadvayamitaṃ rasam bhakṣayitvā rasaṃ paścātpibettakraṃ sasaindhavam"},{"type":"verse","number":"82","sanskrit":"अत्यर्थं गुरु यद् भुक्तमतिमात्रमथापि च तत्सर्वं जीर्यति क्षिप्रं रसस्यैतस्य भक्षणात्","text":"atyarthaṃ guru yad bhuktamatimātramathāpi ca tatsarvaṃ jīryati kṣipraṃ rasasyaitasya bhakṣaṇāt"},{"type":"verse","number":"83","sanskrit":"शूलं गुल्मञ्च विष्टम्भं प्लीहानमुदरं तथा रसः क्रव्यादनामाऽय विनिहन्ति न संशयः","text":"śūlaṃ gulmañca viṣṭambhaṃ plīhānamudaraṃ tathā rasaḥ kravyādanāmā'ya vinihanti na saṃśayaḥ"},{"type":"verse","number":"84","sanskrit":"क्षारत्रयं सूतगन्धौ पञ्चकोलमिदं समम् सर्वैस्तुल्या जया भृष्टा तदर्द्धा शिग्रुजा जटा","text":"kṣāratrayaṃ sūtagandhau pañcakolamidaṃ samam sarvaistulyā jayā bhṛṣṭā tadarddhā śigrujā jaṭā"},{"type":"verse","number":"85","sanskrit":"एतत्सर्वं जयाशिग्रुवह्नीनां केवलैर्द्र वैः भावयेत्रिदिनं घर्मे ततो लघु पुटे पचेत्","text":"etatsarvaṃ jayāśigruvahnīnāṃ kevalairdra vaiḥ bhāvayetridinaṃ gharme tato laghu puṭe pacet"},{"type":"verse","number":"86","sanskrit":"मार्कवस्य द्र्रवैर्घृष्टो रसो ज्वालानलो भवेत् निष्कोऽस्य मधुना लीढोऽनुपानं गुडनागरम्","text":"mārkavasya drravairghṛṣṭo raso jvālānalo bhavet niṣko'sya madhunā līḍho'nupānaṃ guḍanāgaram"},{"type":"verse","number":"87","sanskrit":"हन्त्यजीर्णमतीसारं ग्रहणीमग्निमार्दवम् श्लेष्महृल्लासवमनमालस्यमरुचिं जयेत्","text":"hantyajīrṇamatīsāraṃ grahaṇīmagnimārdavam śleṣmahṛllāsavamanamālasyamaruciṃ jayet"},{"type":"verse","number":"88","sanskrit":"टङ्कणं रसगन्धौ च समं भागत्रयं विषात् कपर्दः स्वर्जिका क्षारो मागघी विश्वभेषजम्","text":"ṭaṅkaṇaṃ rasagandhau ca samaṃ bhāgatrayaṃ viṣāt kapardaḥ svarjikā kṣāro māgaghī viśvabheṣajam"},{"type":"verse","number":"89","sanskrit":"पृथक् पृथक्कर्षमात्रं वसुभागमिहोषणम् जम्बीराम्लैर्दिनं घृष्टं भवेदग्निकुमारकः विसूचीशूलवातादिवह्निमान्द्यप्रशान्तये","text":"pṛthak pṛthakkarṣamātraṃ vasubhāgamihoṣaṇam jambīrāmlairdinaṃ ghṛṣṭaṃ bhavedagnikumārakaḥ visūcīśūlavātādivahnimāndyapraśāntaye"},{"type":"verse","number":"90","sanskrit":"पारदामृतलवङ्गगन्धकं भागयुग्ममरिचेन मिश्रितम् तत्र जातिफलमर्द्धभागिकं तिन्तिडीफलरसेन मर्दितम्","text":"pāradāmṛtalavaṅgagandhakaṃ bhāgayugmamaricena miśritam tatra jātiphalamarddhabhāgikaṃ tintiḍīphalarasena marditam"},{"type":"verse","number":"91","sanskrit":"माषमात्रमनुपानसेवितं रामबाणगुडिका रसायनम् बिल्वपत्रमरिचेन भक्षितं सद्य एव जठराग्निवर्द्धितम्","text":"māṣamātramanupānasevitaṃ rāmabāṇaguḍikā rasāyanam bilvapatramaricena bhakṣitaṃ sadya eva jaṭharāgnivarddhitam"},{"type":"verse","number":"92","sanskrit":"वातो नाशमुपैति चार्द्र करसैर्निर्गुण्डिकाया द्र्रवैः पित्तं नाशमुपैति धान्यकजलैर्वासा त्रिदोषं हरेत् श्लेष्मा सिन्धुहरीतकीभिरुदरं क्वाथैश्च पौनर्नवैः शोथं पाण्डुगदं निहन्ति गुडिका रोगार्त्तिविध्वंसिनी","text":"vāto nāśamupaiti cārdra karasairnirguṇḍikāyā drravaiḥ pittaṃ nāśamupaiti dhānyakajalairvāsā tridoṣaṃ haret śleṣmā sindhuharītakībhirudaraṃ kvāthaiśca paunarnavaiḥ śothaṃ pāṇḍugadaṃ nihanti guḍikā rogārttividhvaṃsinī"},{"type":"verse","number":"93","sanskrit":"वह्निमान्द्यदशवक्त्रनाशनो रामबाण इति विश्रुतो रसः सङ्ग्रहणिकुम्भकर्णकमामवातखरदूषणं जयेत्","text":"vahnimāndyadaśavaktranāśano rāmabāṇa iti viśruto rasaḥ saṅgrahaṇikumbhakarṇakamāmavātakharadūṣaṇaṃ jayet"},{"type":"verse","number":"94","sanskrit":"दीयते तु मरिचानुपानतः सद्य एव जठराग्निदीपनः रोचनः कफकुलान्तकारकः श्वासकासवमिजन्तुनाशनः","text":"dīyate tu maricānupānataḥ sadya eva jaṭharāgnidīpanaḥ rocanaḥ kaphakulāntakārakaḥ śvāsakāsavamijantunāśanaḥ"},{"type":"verse","number":"95","sanskrit":"पलं चिञ्चाक्षारं पलमितमिदं पञ्चलवणं द्बयं सम्यक्पिष्टं भवति लघुनिम्बूफलरसैः ततः पिष्टे तस्मिन्पलपरिमितं शङ्खशकलं क्षिपेद् वारान्सप्त द्र वमिह च तेनैव विधिना","text":"palaṃ ciñcākṣāraṃ palamitamidaṃ pañcalavaṇaṃ dbayaṃ samyakpiṣṭaṃ bhavati laghunimbūphalarasaiḥ tataḥ piṣṭe tasminpalaparimitaṃ śaṅkhaśakalaṃ kṣiped vārānsapta dra vamiha ca tenaiva vidhinā"},{"type":"verse","number":"96","sanskrit":"पलप्रमाणं कटुकत्रयञ्च पलार्द्धमानं वचहिङ्गुभागः विषं पलद्बादशभागयुक्तं तावद्र सो गन्धक एष चोक्तः","text":"palapramāṇaṃ kaṭukatrayañca palārddhamānaṃ vacahiṅgubhāgaḥ viṣaṃ paladbādaśabhāgayuktaṃ tāvadra so gandhaka eṣa coktaḥ"},{"type":"verse","number":"97","sanskrit":"बदरास्थिप्रमाणेन वटीमेतस्य कारयेत् भक्षयेत्सेवया साम्यात्सर्वाजीर्णप्रशान्तये","text":"badarāsthipramāṇena vaṭīmetasya kārayet bhakṣayetsevayā sāmyātsarvājīrṇapraśāntaye"},{"type":"verse","number":"98","sanskrit":"सर्वोदरेषु शूलेषु विसूच्यां विविधेषु च अग्निमान्द्येषु गुल्मेषु सदा शङ्खवटी हिता","text":"sarvodareṣu śūleṣu visūcyāṃ vividheṣu ca agnimāndyeṣu gulmeṣu sadā śaṅkhavaṭī hitā"},{"type":"verse","number":"99","sanskrit":"स्नुह्यार्कचिञ्चाऽपामार्गरम्भातिलपलाशजान् लवणानाददीतैषां प्रत्येकं पलमात्रया","text":"snuhyārkaciñcā'pāmārgarambhātilapalāśajān lavaṇānādadītaiṣāṃ pratyekaṃ palamātrayā"},{"type":"verse","number":"100","sanskrit":"लवणानि पृथक्पञ्च ग्राह्याणि पलमात्रया स्वर्जिका च यवक्षारष्टङ्कणं त्रितयं पलम्","text":"lavaṇāni pṛthakpañca grāhyāṇi palamātrayā svarjikā ca yavakṣāraṣṭaṅkaṇaṃ tritayaṃ palam"},{"type":"verse","number":"101","sanskrit":"सर्वं त्रयोदशपलं सूक्ष्मं चूर्णं विधाय च निम्बूफलरसे प्रस्थसम्मिते तत्परिक्षिपेत्","text":"sarvaṃ trayodaśapalaṃ sūkṣmaṃ cūrṇaṃ vidhāya ca nimbūphalarase prasthasammite tatparikṣipet"},{"type":"verse","number":"102","sanskrit":"तत्र शङ्खस्य शकलं पलं वह्नौ प्रताप्य तु वारान्निर्वापयेत्सप्त सर्वं द्र वति तद्यथा","text":"tatra śaṅkhasya śakalaṃ palaṃ vahnau pratāpya tu vārānnirvāpayetsapta sarvaṃ dra vati tadyathā"},{"type":"verse","number":"103","sanskrit":"नागरं त्रिपलं ग्राह्यं मरिचन्तु पलद्वयम् पिप्पली पलमाना स्यात्पलार्द्ध भृष्टहिङ्गुतः","text":"nāgaraṃ tripalaṃ grāhyaṃ maricantu paladvayam pippalī palamānā syātpalārddha bhṛṣṭahiṅgutaḥ"},{"type":"verse","number":"104","sanskrit":"ग्रन्थितं चित्रकञ्चापि यवानी जीरकं तथा जातीफलं लवङ्गञ्च पृथक्कर्षद्वयोन्मितम्","text":"granthitaṃ citrakañcāpi yavānī jīrakaṃ tathā jātīphalaṃ lavaṅgañca pṛthakkarṣadvayonmitam"},{"type":"verse","number":"105","sanskrit":"रसो गन्धो विषं चापि टङ्कणञ्च मनः शिला एतानि कर्षमात्राणि सर्वं सञ्चूर्ण्य मिश्रयेत्","text":"raso gandho viṣaṃ cāpi ṭaṅkaṇañca manaḥ śilā etāni karṣamātrāṇi sarvaṃ sañcūrṇya miśrayet"},{"type":"verse","number":"106","sanskrit":"शरावार्द्धेन चुक्रेण वटिकां तस्य कारयेत् माषप्रमाणां सद्वैद्यैर्बृहच्छङ्खवटी स्मृता","text":"śarāvārddhena cukreṇa vaṭikāṃ tasya kārayet māṣapramāṇāṃ sadvaidyairbṛhacchaṅkhavaṭī smṛtā"},{"type":"verse","number":"107","sanskrit":"सर्वाजीर्णप्रशमनी सर्वशूलनिवारिणी विसूच्यलसकादीनां सद्यो भवति नाशनी","text":"sarvājīrṇapraśamanī sarvaśūlanivāriṇī visūcyalasakādīnāṃ sadyo bhavati nāśanī"},{"type":"verse","number":"108","sanskrit":"टङ्कणकणाऽमृतानां सहिङ्गुलानां समं भागम् मरिचस्य भागयुगलं निम्बूनीरैर्वटी कार्या","text":"ṭaṅkaṇakaṇā'mṛtānāṃ sahiṅgulānāṃ samaṃ bhāgam maricasya bhāgayugalaṃ nimbūnīrairvaṭī kāryā"},{"type":"verse","number":"109","sanskrit":"वटिकां कलायसदृशीमेकां द्वे वा समश्नीयात् सत्यमजीर्णेशान्त्यै वह्नेर्वृद्ध्यै कफध्वस्त्यै","text":"vaṭikāṃ kalāyasadṛśīmekāṃ dve vā samaśnīyāt satyamajīrṇeśāntyai vahnervṛddhyai kaphadhvastyai"},{"type":"verse","number":"110","sanskrit":"जलपीतमपामार्गमूलं हन्याद्बिसूचिकाम् सतैलं कारवेल्ल्यम्बु नाशयेद्धि विसूचिकाम्","text":"jalapītamapāmārgamūlaṃ hanyādbisūcikām satailaṃ kāravellyambu nāśayeddhi visūcikām"},{"type":"verse","number":"111","sanskrit":"बालमूलस्य तु क्वाथः पिप्पलीचूर्णसंयुतः विसूचीनाशनः श्रेष्ठो जठराग्निविवर्द्धनः","text":"bālamūlasya tu kvāthaḥ pippalīcūrṇasaṃyutaḥ visūcīnāśanaḥ śreṣṭho jaṭharāgnivivarddhanaḥ"},{"type":"verse","number":"112","sanskrit":"बिल्वनागरनिक्वाथो हन्याच्छर्दिंविसूचिकाम् बिल्वनागरकैटर्यक्वाथस्तदधिको गुणैः","text":"bilvanāgaranikvātho hanyācchardiṃvisūcikām bilvanāgarakaiṭaryakvāthastadadhiko guṇaiḥ"},{"type":"verse","number":"113","sanskrit":"व्योषं करञ्जस्य फलं हरिद्रे मूलं समावाप्य च मातुलुङ्ग्याः छायाविशुष्का वटिका कृता सा हन्याद्विसूचीं नयनाञ्जनेन","text":"vyoṣaṃ karañjasya phalaṃ haridre mūlaṃ samāvāpya ca mātuluṅgyāḥ chāyāviśuṣkā vaṭikā kṛtā sā hanyādvisūcīṃ nayanāñjanena"},{"type":"verse","number":"114","sanskrit":"अपामार्गस्य पत्राणि मरिचानि समानि च अश्वस्य लालया पिष्ट्वाऽञ्जनाद्धन्ति विसूचिकाम्","text":"apāmārgasya patrāṇi maricāni samāni ca aśvasya lālayā piṣṭvā'ñjanāddhanti visūcikām"},{"type":"verse","number":"115","sanskrit":"विसूच्यामतिवृद्धायां तक्रं दधि समं जलम् नारिकेलाम्बु पेयं वा प्राणत्राणाय योजयेत्","text":"visūcyāmativṛddhāyāṃ takraṃ dadhi samaṃ jalam nārikelāmbu peyaṃ vā prāṇatrāṇāya yojayet"},{"type":"verse","number":"116","sanskrit":"त्वक्पत्रकैरण्डकशिग्रुकुष्ठैरम्लप्रपिष्टैः सवचाशताह्वैः उद्वर्त्तनं खल्लिविसूचिकाघ्नं तैलं विपक्वञ्च तदर्थकारि","text":"tvakpatrakairaṇḍakaśigrukuṣṭhairamlaprapiṣṭaiḥ savacāśatāhvaiḥ udvarttanaṃ khallivisūcikāghnaṃ tailaṃ vipakvañca tadarthakāri"},{"type":"verse","number":"117","sanskrit":"कुष्ठसैन्धवयोः कल्कं शुक्रं तैले तु साधितम् विसूच्यां मर्दनं तेन खल्लीशूलनिवारणम्","text":"kuṣṭhasaindhavayoḥ kalkaṃ śukraṃ taile tu sādhitam visūcyāṃ mardanaṃ tena khallīśūlanivāraṇam"},{"type":"verse","number":"118","sanskrit":"पिपासायां तथोत्क्लेशे लवङ्गस्याम्बु शस्यते जातीफलस्य वा पीतं शृतं भद्र घनस्य वा","text":"pipāsāyāṃ tathotkleśe lavaṅgasyāmbu śasyate jātīphalasya vā pītaṃ śṛtaṃ bhadra ghanasya vā"},{"type":"verse","number":"119","sanskrit":"उत्क्लिश्यान्नं न निर्गच्छेत्प्रसेकष्ठीवनेरितम् हृदयं पीड्यते चास्य तमुत्क्लेशं विनिर्दिशेत्","text":"utkliśyānnaṃ na nirgacchetprasekaṣṭhīvaneritam hṛdayaṃ pīḍyate cāsya tamutkleśaṃ vinirdiśet"},{"type":"verse","number":"120","sanskrit":"सरुग् वाऽनद्धमुदरमम्लपिष्टैः प्रलेपयेत् दारुहैमवतीकुष्ठशताह्वाहिङ्गुसैन्धवैः","text":"sarug vā'naddhamudaramamlapiṣṭaiḥ pralepayet dāruhaimavatīkuṣṭhaśatāhvāhiṅgusaindhavaiḥ"},{"type":"verse","number":"121","sanskrit":"तक्रेण युक्तं यवचूर्णमुष्णं सक्षारमर्त्तिं जठरे निहन्यात् स्वेदो घटैर्वाऽप्यथ बाष्पपूर्णैरुष्णैस्तथाऽन्यैरपि पिण्डतापैः","text":"takreṇa yuktaṃ yavacūrṇamuṣṇaṃ sakṣāramarttiṃ jaṭhare nihanyāt svedo ghaṭairvā'pyatha bāṣpapūrṇairuṣṇaistathā'nyairapi piṇḍatāpaiḥ"},{"type":"verse","number":"122","sanskrit":"विलम्बिकाऽलसकयोरयमेव क्रियाक्रमः अत एव तयोरुक्तं पृथङ् नहि चिकित्सितम्","text":"vilambikā'lasakayorayameva kriyākramaḥ ata eva tayoruktaṃ pṛthaṅ nahi cikitsitam"},{"type":"verse","number":"123","sanskrit":"तं भस्मकं गुरुस्निग्धसान्द्र मन्दहिमस्थिरैः अन्नपानैर्नयेच्छान्तिं पित्तघ्नैश्च विरेचनैः","text":"taṃ bhasmakaṃ gurusnigdhasāndra mandahimasthiraiḥ annapānairnayecchāntiṃ pittaghnaiśca virecanaiḥ"},{"type":"verse","number":"124","sanskrit":"अत्यद्भुताग्निशान्त्यै माहिषदधिदुग्धसर्पींषि संसेवेत यवागूं समपिष्टे पयसि सर्पिषा सिद्धाम्","text":"atyadbhutāgniśāntyai māhiṣadadhidugdhasarpīṃṣi saṃseveta yavāgūṃ samapiṣṭe payasi sarpiṣā siddhām"},{"type":"verse","number":"125","sanskrit":"असकृत्पित्तहरणं पायसं प्रतिभोजनम् श्यामात्रिवृद्विपक्वञ्च पयो दद्याद्विरेचनम्","text":"asakṛtpittaharaṇaṃ pāyasaṃ pratibhojanam śyāmātrivṛdvipakvañca payo dadyādvirecanam"},{"type":"verse","number":"126","sanskrit":"यत्किञ्चिन्मधुरं मेध्यं श्लेष्मलं गुरु भोजनम् सर्वं तदत्यग्निहितं भुक्त्वा प्रस्वपनं दिवा","text":"yatkiñcinmadhuraṃ medhyaṃ śleṣmalaṃ guru bhojanam sarvaṃ tadatyagnihitaṃ bhuktvā prasvapanaṃ divā"},{"type":"verse","number":"127","sanskrit":"सिततण्डुलसितकमलं छागक्षीरेण पायसं सिद्धम् भुक्त्वा च तेन पुरुषो दशदिवसात्तुच्छभोजनो भवति","text":"sitataṇḍulasitakamalaṃ chāgakṣīreṇa pāyasaṃ siddham bhuktvā ca tena puruṣo daśadivasāttucchabhojano bhavati"},{"type":"verse","number":"128","sanskrit":"अलं पनसपाकाय फलं कदलसम्भवम् कदलस्य तु पाकाय बुधैरपि घृतं हितम्","text":"alaṃ panasapākāya phalaṃ kadalasambhavam kadalasya tu pākāya budhairapi ghṛtaṃ hitam"},{"type":"verse","number":"129","sanskrit":"घृतस्य परिपाकाय जम्बीरस्य रसो हितः","text":"ghṛtasya paripākāya jambīrasya raso hitaḥ"},{"type":"verse","number":"130","sanskrit":"नारिकेलफलतालबीजयोः पाचकं सपदि तण्डुलं विदुः क्षीरमेव सहकारपाचनं चारमज्जनि हरीतकी हिता","text":"nārikelaphalatālabījayoḥ pācakaṃ sapadi taṇḍulaṃ viduḥ kṣīrameva sahakārapācanaṃ cāramajjani harītakī hitā"},{"type":"verse","number":"131","sanskrit":"मधूकमालूरनृपादनानां परुषखर्जूरकपित्थकानाम् पाकाय पेयं पिचुमन्दबीजं घृतेऽपि तक्रेऽपि तदेव पथ्यम्","text":"madhūkamālūranṛpādanānāṃ paruṣakharjūrakapitthakānām pākāya peyaṃ picumandabījaṃ ghṛte'pi takre'pi tadeva pathyam"},{"type":"verse","number":"132","sanskrit":"खर्जूरशृङ्गाटकयोः प्रशस्तं विश्वौषधं कुत्र च भद्र्रमुस्तम् यज्ञाङ्गबोधिद्रुफलेषु शस्तं प्लक्षे तथा पर्युषितं प्रपीतम्","text":"kharjūraśṛṅgāṭakayoḥ praśastaṃ viśvauṣadhaṃ kutra ca bhadrramustam yajñāṅgabodhidruphaleṣu śastaṃ plakṣe tathā paryuṣitaṃ prapītam"},{"type":"verse","number":"133","sanskrit":"तण्डुलेषु च पयः पयस्वथो दीप्यकस्तु चिपिटे कणायुतम् षष्टिका दधिजलेन जीर्यते कर्कटी च सुमनेषु जीर्यति","text":"taṇḍuleṣu ca payaḥ payasvatho dīpyakastu cipiṭe kaṇāyutam ṣaṣṭikā dadhijalena jīryate karkaṭī ca sumaneṣu jīryati"},{"type":"verse","number":"134","sanskrit":"गोधूममाषहरिमन्थसतीनमुद्ग पाको भवेज्झटिति मातुलपुत्रकेण खर्जूरिकाबिसकशेरुसितासु शस्तं शृङ्गाटके मधुफलेष्वपि भद्र मुस्तम्","text":"godhūmamāṣaharimanthasatīnamudga pāko bhavejjhaṭiti mātulaputrakeṇa kharjūrikābisakaśerusitāsu śastaṃ śṛṅgāṭake madhuphaleṣvapi bhadra mustam"},{"type":"verse","number":"135","sanskrit":"कङ्गुश्यामाकनीवाराः कुलत्थाश्चाविलम्बितम् दध्ना जलेन जीर्यन्ति वैदलः काञ्जिकेन तु","text":"kaṅguśyāmākanīvārāḥ kulatthāścāvilambitam dadhnā jalena jīryanti vaidalaḥ kāñjikena tu"},{"type":"verse","number":"136","sanskrit":"पिष्टान्नं शीतलं वारि कृशरां सैन्धवं पचेत् माषेण्डरीं निम्बुफलं पायसं मुद्गयूषकः","text":"piṣṭānnaṃ śītalaṃ vāri kṛśarāṃ saindhavaṃ pacet māṣeṇḍarīṃ nimbuphalaṃ pāyasaṃ mudgayūṣakaḥ"},{"type":"verse","number":"137","sanskrit":"वटो वेसवाराल्लवङ्गेन फेनः समं पपर्टः शिग्रुबीजेन याति कणामूलतो लड्डुकापूपसट्टाऽदिपाको भवेच्छष्कुलीमण्डयोश्च","text":"vaṭo vesavārāllavaṅgena phenaḥ samaṃ paparṭaḥ śigrubījena yāti kaṇāmūlato laḍḍukāpūpasaṭṭā'dipāko bhavecchaṣkulīmaṇḍayośca"},{"type":"verse","number":"138","sanskrit":"किमत्र चित्रं बहुमत्स्यमांस भोजी सुखी काञ्जिकपानतः स्यात् इत्यद्भुतं केवलवह्निपक्वमांसेन मत्स्यः परिपाकमेति","text":"kimatra citraṃ bahumatsyamāṃsa bhojī sukhī kāñjikapānataḥ syāt ityadbhutaṃ kevalavahnipakvamāṃsena matsyaḥ paripākameti"},{"type":"verse","number":"139","sanskrit":"आममाम्रफलं मत्स्ये तद्बीजं पिशिते हितम् कूर्ममांसं यवक्षारैः शीघ्रं पाकमुपैति हि","text":"āmamāmraphalaṃ matsye tadbījaṃ piśite hitam kūrmamāṃsaṃ yavakṣāraiḥ śīghraṃ pākamupaiti hi"},{"type":"verse","number":"140","sanskrit":"कपोतपारावतनीलकण्ठकपिञ्जलानां पिशितानि भुक्त्वा काशस्य मूलं परिपिष्य पीतं सुखी भवेन्ना बहुशो हि दृष्टम्","text":"kapotapārāvatanīlakaṇṭhakapiñjalānāṃ piśitāni bhuktvā kāśasya mūlaṃ paripiṣya pītaṃ sukhī bhavennā bahuśo hi dṛṣṭam"},{"type":"verse","number":"141","sanskrit":"मांसानि सर्वाण्यपि यान्ति पाकं क्षीरेण सद्यस्तिलनालजेन चञ्चूकसिद्धार्थकवास्तुकानां गायत्रिसारक्वथितेन पाकः","text":"māṃsāni sarvāṇyapi yānti pākaṃ kṣīreṇa sadyastilanālajena cañcūkasiddhārthakavāstukānāṃ gāyatrisārakvathitena pākaḥ"},{"type":"verse","number":"142","sanskrit":"पालङ्किकाकेबुककारवेल्ली वार्त्ताकुवंशाङ्कुरमूलकानाम् उपोदिकाऽलाबुपटोलकानां सिद्धार्थको मेघरवश्च पक्ता","text":"pālaṅkikākebukakāravellī vārttākuvaṃśāṅkuramūlakānām upodikā'lābupaṭolakānāṃ siddhārthako megharavaśca paktā"},{"type":"verse","number":"143","sanskrit":"विपच्यते शूरणको गुडेन तथाऽलुकं तण्डुलधावनेन पिण्डालुकं जीर्यति कोरदूषात्कशेरुपाकः किल नागरेण","text":"vipacyate śūraṇako guḍena tathā'lukaṃ taṇḍuladhāvanena piṇḍālukaṃ jīryati koradūṣātkaśerupākaḥ kila nāgareṇa"},{"type":"verse","number":"144","sanskrit":"लवणस्तण्डु लतोयात्सर्पिर्जम्बीरकाद्यम्लात् मरिचादपि तच्छीघ्रं पाकं यात्येव काञ्जिकात्तैलम्","text":"lavaṇastaṇḍu latoyātsarpirjambīrakādyamlāt maricādapi tacchīghraṃ pākaṃ yātyeva kāñjikāttailam"},{"type":"verse","number":"145","sanskrit":"क्षीरं जीर्यति तक्रेण तद्द्र व्यं कोष्णमण्डकात् माहिषं माणिमन्थेन शङ्खचूर्णेन तद्दधि","text":"kṣīraṃ jīryati takreṇa taddra vyaṃ koṣṇamaṇḍakāt māhiṣaṃ māṇimanthena śaṅkhacūrṇena taddadhi"},{"type":"verse","number":"146","sanskrit":"रसालं जीर्यति व्योषात्खण्डं नागरभक्षणात् सिता नागरमुस्तेन तथेक्षुश्चार्द्रि कारसात्","text":"rasālaṃ jīryati vyoṣātkhaṇḍaṃ nāgarabhakṣaṇāt sitā nāgaramustena tathekṣuścārdri kārasāt"},{"type":"verse","number":"147","sanskrit":"जरामिरा गैरिकचन्दनाभ्यामभ्येति शीघ्रं मुनिभिः प्रदिष्टम् उष्णेन शीतं शिशिरेण चोष्णं जीर्णो भवेत्क्षारगणस्तथाऽम्लै","text":"jarāmirā gairikacandanābhyāmabhyeti śīghraṃ munibhiḥ pradiṣṭam uṣṇena śītaṃ śiśireṇa coṣṇaṃ jīrṇo bhavetkṣāragaṇastathā'mlai"},{"type":"verse","number":"148","sanskrit":"तप्तं तप्तं हेम वा तारमग्नौ तोये क्षिप्तं सप्तकृत्वस्तदम्भः पीत्वाऽजीर्णं तोयजातं निहन्यात्तत्र क्षौद्रं भद्र मुस्तं विशेषात्","text":"taptaṃ taptaṃ hema vā tāramagnau toye kṣiptaṃ saptakṛtvastadambhaḥ pītvā'jīrṇaṃ toyajātaṃ nihanyāttatra kṣaudraṃ bhadra mustaṃ viśeṣāt"},{"type":"verse","number":"149","sanskrit":"इति षष्ठो जठराग्निविकाराधिकारः समाप्तः ६","text":"iti ṣaṣṭho jaṭharāgnivikārādhikāraḥ samāptaḥ 6"}]},{"sthana":"Уттаракханда","number":7,"lang":"sa","content":[{"type":"heading","heading":"Кримирога — глистные инвазии"},{"type":"verse","number":"1","sanskrit":"कृमयस्तु द्विधा प्रोक्ता बाह्याभ्यन्तरभेदतः","text":"kṛmayastu dvidhā proktā bāhyābhyantarabhedataḥ"},{"type":"verse","number":"2","sanskrit":"बहिर्मलकफासृग्विड्जन्मभेदाच्चतुर्विधाः नामतो विंशतिविधा बाह्यास्तत्र मलोद्भवाः","text":"bahirmalakaphāsṛgviḍjanmabhedāccaturvidhāḥ nāmato viṃśatividhā bāhyāstatra malodbhavāḥ"},{"type":"verse","number":"3","sanskrit":"तिलप्रमाणसंस्थानवर्णाः केशाम्बराश्रयाः बहुपादाश्च सूक्ष्माश्च यूका लिख्याश्च नामतः","text":"tilapramāṇasaṃsthānavarṇāḥ keśāmbarāśrayāḥ bahupādāśca sūkṣmāśca yūkā likhyāśca nāmataḥ"},{"type":"verse","number":"4","sanskrit":"द्विधा ते कोठपिडिकाः कण्डूगण्डान्प्रकुर्वते","text":"dvidhā te koṭhapiḍikāḥ kaṇḍūgaṇḍānprakurvate"},{"type":"verse","number":"5","sanskrit":"अजीर्णभोजी मधुराम्लसेवी द्र वप्रियः पिष्टगुडोपभोक्ता व्यायामवर्जी च दिवाशयी च विरुद्धभोजी लभते कृमींश्च","text":"ajīrṇabhojī madhurāmlasevī dra vapriyaḥ piṣṭaguḍopabhoktā vyāyāmavarjī ca divāśayī ca viruddhabhojī labhate kṛmīṃśca"},{"type":"verse","number":"6","sanskrit":"ज्वरो विवर्णता शूलं हृद्रो गः सदनं भ्रमः भक्तद्वेषोऽतिसारश्च सञ्जातकृमिलक्षणम्","text":"jvaro vivarṇatā śūlaṃ hṛdro gaḥ sadanaṃ bhramaḥ bhaktadveṣo'tisāraśca sañjātakṛmilakṣaṇam"},{"type":"verse","number":"7","sanskrit":"मांसमाषगुडक्षीरदधिशुक्तैः कफोद्भवाः","text":"māṃsamāṣaguḍakṣīradadhiśuktaiḥ kaphodbhavāḥ"},{"type":"verse","number":"8","sanskrit":"कफादामाशये जाता वृद्धाः सर्पन्ति सर्वतः पृथुब्रध्ननिभाः केचित्केचिद्गण्डूपदोपमाः","text":"kaphādāmāśaye jātā vṛddhāḥ sarpanti sarvataḥ pṛthubradhnanibhāḥ kecitkecidgaṇḍūpadopamāḥ"},{"type":"verse","number":"9","sanskrit":"रुढधान्याङ्कुराकारास्तनुदीर्घास्तथाऽणवः श्वेतास्ताम्रावभासाश्च नामतः सप्तधा तु ते","text":"ruḍhadhānyāṅkurākārāstanudīrghāstathā'ṇavaḥ śvetāstāmrāvabhāsāśca nāmataḥ saptadhā tu te"},{"type":"verse","number":"10","sanskrit":"अन्त्रादा उदरावेष्टा हृदयादा महागुदाः च्युरवो दर्भकुसुमाः सुगन्धास्ते च कुर्वते","text":"antrādā udarāveṣṭā hṛdayādā mahāgudāḥ cyuravo darbhakusumāḥ sugandhāste ca kurvate"},{"type":"verse","number":"11","sanskrit":"हृल्लासमास्यस्रवणमविपाकमरोचकम् मूर्च्छाच्छर्दिज्वरानाहकासक्षवथुपीनसान्","text":"hṛllāsamāsyasravaṇamavipākamarocakam mūrcchācchardijvarānāhakāsakṣavathupīnasān"},{"type":"verse","number":"12","sanskrit":"विरुद्धाजीर्णशाकाद्यैः शोणितोत्था भवन्ति हि","text":"viruddhājīrṇaśākādyaiḥ śoṇitotthā bhavanti hi"},{"type":"verse","number":"13","sanskrit":"रक्तवाहिशिरास्थाना रक्तजा जन्तवोऽणवः प्रपादा वृत्तताम्राश्च सौक्ष्म्यात्केचिददर्शनाः","text":"raktavāhiśirāsthānā raktajā jantavo'ṇavaḥ prapādā vṛttatāmrāśca saukṣmyātkecidadarśanāḥ"},{"type":"verse","number":"14","sanskrit":"केशादा लोमविध्वंसा रोमद्वीपा उदुम्बराः षट् ते कुष्ठैककर्माणः सहसौरसमातरः","text":"keśādā lomavidhvaṃsā romadvīpā udumbarāḥ ṣaṭ te kuṣṭhaikakarmāṇaḥ sahasaurasamātaraḥ"},{"type":"verse","number":"15","sanskrit":"माषपिष्टाम्ललवणगुडशाकैः पुरीषजाः","text":"māṣapiṣṭāmlalavaṇaguḍaśākaiḥ purīṣajāḥ"},{"type":"verse","number":"16","sanskrit":"पक्वाशये पुरीषोत्था जायन्तेऽधोविसर्पिणः वृद्धास्ते स्युर्भवेयुश्च ते यदाऽमाशयोन्मुखा तदाऽस्योद्गारनिःश्वासा विड्गन्धानुविधायिनः पृथुवृत्ततनुस्थूलाः श्यावपीतसितासिताः","text":"pakvāśaye purīṣotthā jāyante'dhovisarpiṇaḥ vṛddhāste syurbhaveyuśca te yadā'māśayonmukhā tadā'syodgāraniḥśvāsā viḍgandhānuvidhāyinaḥ pṛthuvṛttatanusthūlāḥ śyāvapītasitāsitāḥ"},{"type":"verse","number":"17","sanskrit":"ते पञ्च नाम्ना कृमयः ककेरुकमकेरुकाः सौसुरादाः सलूनाख्या लेलिहा जनयन्ति च विड्भेदशूलविष्टम्भकार्श्यपारुष्यपाण्डुताः रोमहर्षाग्निसदनगुदकण्डूर्विमार्गगाः","text":"te pañca nāmnā kṛmayaḥ kakerukamakerukāḥ sausurādāḥ salūnākhyā lelihā janayanti ca viḍbhedaśūlaviṣṭambhakārśyapāruṣyapāṇḍutāḥ romaharṣāgnisadanagudakaṇḍūrvimārgagāḥ"},{"type":"verse","number":"18","sanskrit":"विडङ्गव्योषसंयुक्तमन्नमण्डं पिबेन्नरः दीपनं कृमिनाशाय जठराग्निविवृद्धये","text":"viḍaṅgavyoṣasaṃyuktamannamaṇḍaṃ pibennaraḥ dīpanaṃ kṛmināśāya jaṭharāgnivivṛddhaye"},{"type":"verse","number":"19","sanskrit":"प्रत्यहं कटुकं तिक्तं भोजनं कफनाशनम् कृमीणां नाशनं रुच्यमग्निसन्दीपनं परम्","text":"pratyahaṃ kaṭukaṃ tiktaṃ bhojanaṃ kaphanāśanam kṛmīṇāṃ nāśanaṃ rucyamagnisandīpanaṃ param"},{"type":"verse","number":"20","sanskrit":"विडङ्गशृतपानीयं विडङ्गेनावधूलितम् पीतं कृमिहरं दृष्टं कृमिजांश्च गदाञ्जयेत्","text":"viḍaṅgaśṛtapānīyaṃ viḍaṅgenāvadhūlitam pītaṃ kṛmiharaṃ dṛṣṭaṃ kṛmijāṃśca gadāñjayet"},{"type":"verse","number":"21","sanskrit":"लिह्याद्विडङ्गचूर्णं वा मधुना कृमिनाशनम् पलाशबीजस्य रसं पिबेन्माक्षिकसंयुतम् पिबेत्तद्बीजकल्कं वा मधुना कृमिनाशनम्","text":"lihyādviḍaṅgacūrṇaṃ vā madhunā kṛmināśanam palāśabījasya rasaṃ pibenmākṣikasaṃyutam pibettadbījakalkaṃ vā madhunā kṛmināśanam"},{"type":"verse","number":"22","sanskrit":"कम्पिल्लचूर्णकर्षार्द्धं गुडेन सह भक्षितम् पातयेत्तु कृमीन्सर्वानुदरस्थान्न संशयः","text":"kampillacūrṇakarṣārddhaṃ guḍena saha bhakṣitam pātayettu kṛmīnsarvānudarasthānna saṃśayaḥ"},{"type":"verse","number":"23","sanskrit":"विडङ्गं कौटजं बीजं तथा बीजं पलाशजम् सञ्चूर्ण्य खादेत्खण्डेन कृमीन्नाशयितुं नरः","text":"viḍaṅgaṃ kauṭajaṃ bījaṃ tathā bījaṃ palāśajam sañcūrṇya khādetkhaṇḍena kṛmīnnāśayituṃ naraḥ"},{"type":"verse","number":"24","sanskrit":"निम्बपत्रसमुद्भूतं रसं क्षौद्र्रयुतं पिबेत् धत्तूरपत्रजं वाऽपि कृमिनाशनमुत्तमम्","text":"nimbapatrasamudbhūtaṃ rasaṃ kṣaudrrayutaṃ pibet dhattūrapatrajaṃ vā'pi kṛmināśanamuttamam"},{"type":"verse","number":"25","sanskrit":"रसेन्द्रे ण समायुक्तो रसो धत्तूरपत्रजः ताम्बूलपत्रजो वाऽपि लेपो यूकाविनाशनः","text":"rasendre ṇa samāyukto raso dhattūrapatrajaḥ tāmbūlapatrajo vā'pi lepo yūkāvināśanaḥ"},{"type":"verse","number":"26","sanskrit":"धत्तूरपत्रकल्केन तद्र्रसेनैव पाचितम् तैलमभ्यङ्गमात्रेण यूका नाशयति क्षणात्","text":"dhattūrapatrakalkena tadrrasenaiva pācitam tailamabhyaṅgamātreṇa yūkā nāśayati kṣaṇāt"},{"type":"verse","number":"27","sanskrit":"कृमीणां विट्कफोत्थानामेतदुक्तं चिकित्सितम् रक्तजानान्तु संहारं कुर्यात्कुष्ठचिकित्सया","text":"kṛmīṇāṃ viṭkaphotthānāmetaduktaṃ cikitsitam raktajānāntu saṃhāraṃ kuryātkuṣṭhacikitsayā"},{"type":"verse","number":"28","sanskrit":"क्षीराणि मांसानिघृतानि चापि दधीनि शाकानि च वर्णयन्ति अम्लञ्च मिष्टञ्च रसं विशेषात्कृमीञ्जिघांसुः परिवर्जयेद्धि","text":"kṣīrāṇi māṃsānighṛtāni cāpi dadhīni śākāni ca varṇayanti amlañca miṣṭañca rasaṃ viśeṣātkṛmīñjighāṃsuḥ parivarjayeddhi"},{"type":"verse","number":"29","sanskrit":"इति सप्तमः कृमिरोगाधिकारः सम्पूर्णः ७","text":"iti saptamaḥ kṛmirogādhikāraḥ sampūrṇaḥ 7"}]},{"sthana":"Уттаракханда","number":8,"lang":"sa","content":[{"type":"heading","heading":"Панду–камала — анемия и желтуха"},{"type":"verse","number":"1","sanskrit":"पण्डुरोगाः स्मृताः पञ्च वातपित्तकफैस्त्रयः चतुर्थः सन्निपातेन पञ्चमो भक्षणान्मृदः","text":"paṇḍurogāḥ smṛtāḥ pañca vātapittakaphaistrayaḥ caturthaḥ sannipātena pañcamo bhakṣaṇānmṛdaḥ"},{"type":"verse","number":"2","sanskrit":"व्यवायमम्लं लवणानि मद्यं मृदं दिवास्वप्नमतीव तीक्ष्णम् निषेवमाणस्य विदूष्य रक्तं दोषास्त्वचं पाण्डुरतां नयन्ति","text":"vyavāyamamlaṃ lavaṇāni madyaṃ mṛdaṃ divāsvapnamatīva tīkṣṇam niṣevamāṇasya vidūṣya raktaṃ doṣāstvacaṃ pāṇḍuratāṃ nayanti"},{"type":"verse","number":"3","sanskrit":"त्वक्स्फोटनिष्ठीवनगात्रसादमृद्भक्षण प्रेक्षणकूटशोथाः विण्म्रूत्रपीतत्वमथाविपाको भविष्यतस्तस्य पुरःसराणि","text":"tvaksphoṭaniṣṭhīvanagātrasādamṛdbhakṣaṇa prekṣaṇakūṭaśothāḥ viṇmrūtrapītatvamathāvipāko bhaviṣyatastasya puraḥsarāṇi"},{"type":"verse","number":"4","sanskrit":"त्वङ्मूत्रनयनादीनां रुक्षकृष्णारुणाभता वातपाण्ड्वामये कम्पस्तोदानाहभ्रमादयः","text":"tvaṅmūtranayanādīnāṃ rukṣakṛṣṇāruṇābhatā vātapāṇḍvāmaye kampastodānāhabhramādayaḥ"},{"type":"verse","number":"5","sanskrit":"पीतत्वङ्नखविण्मूत्रो दाहतृष्णाज्वरान्वितः भिन्नविट्कोऽतिपीताभः पित्तपाण्ड्वामयी नरः","text":"pītatvaṅnakhaviṇmūtro dāhatṛṣṇājvarānvitaḥ bhinnaviṭko'tipītābhaḥ pittapāṇḍvāmayī naraḥ"},{"type":"verse","number":"6","sanskrit":"कफप्रसेकः श्वयथुस्तन्द्रा ऽलस्यातिगौरवैः पाण्डुरोगी कफाच्छुक्लैस्त्वङ्मूत्रनयनाननैः","text":"kaphaprasekaḥ śvayathustandrā 'lasyātigauravaiḥ pāṇḍurogī kaphācchuklaistvaṅmūtranayanānanaiḥ"},{"type":"verse","number":"7","sanskrit":"सर्वान्नसेविनः सर्वे दुष्टा दोषास्त्रिदोषजम् त्रिदोषलिङ्गं कुर्वन्ति पाण्डुरोगं सुदुःसहम्","text":"sarvānnasevinaḥ sarve duṣṭā doṣāstridoṣajam tridoṣaliṅgaṃ kurvanti pāṇḍurogaṃ suduḥsaham"},{"type":"verse","number":"8","sanskrit":"मृत्तिकाऽदनशीलस्यकुप्यत्यन्यतमो मलः कषाया मारुतं पित्तमूषरा मधुरा कफम्","text":"mṛttikā'danaśīlasyakupyatyanyatamo malaḥ kaṣāyā mārutaṃ pittamūṣarā madhurā kapham"},{"type":"verse","number":"9","sanskrit":"कोपयेन्मृद्र्रसादींश्च रौक्ष्याद् भुक्तञ्च रूक्षयेत् पूरयत्यविपक्वैव स्रोतांसि निरुणद्ध्य्पि","text":"kopayenmṛdrrasādīṃśca raukṣyād bhuktañca rūkṣayet pūrayatyavipakvaiva srotāṃsi niruṇaddhypi"},{"type":"verse","number":"10","sanskrit":"इन्द्रि याणां बलं हत्वा तेजो वीर्यौजसी तथा पाण्डुरोगंकरोत्याशु बलवर्णाग्निनाशनम्","text":"indri yāṇāṃ balaṃ hatvā tejo vīryaujasī tathā pāṇḍurogaṃkarotyāśu balavarṇāgnināśanam"},{"type":"verse","number":"11","sanskrit":"मृद्भक्षणाद्भवेत्पाण्डुस्तन्द्रा ऽलस्यनिपीडितः सकासश्वासशूलार्त्तः सदाऽरुचिसमन्वितः","text":"mṛdbhakṣaṇādbhavetpāṇḍustandrā 'lasyanipīḍitaḥ sakāsaśvāsaśūlārttaḥ sadā'rucisamanvitaḥ"},{"type":"verse","number":"12","sanskrit":"शूनाक्षिकूटगण्डभ्रूः शूनपान्नाभिमेहनः कृमिकोष्ठोऽतिसार्येत मलं सासृक्कफान्वितम्","text":"śūnākṣikūṭagaṇḍabhrūḥ śūnapānnābhimehanaḥ kṛmikoṣṭho'tisāryeta malaṃ sāsṛkkaphānvitam"},{"type":"verse","number":"13","sanskrit":"ज्वरारोचकहृल्लासच्छर्दितृष्णाक्लमान्वितः पाण्डुरोगी त्रिभिर्दोषैस्त्याज्यः क्षीणो हतेन्द्रि यः","text":"jvarārocakahṛllāsaccharditṛṣṇāklamānvitaḥ pāṇḍurogī tribhirdoṣaistyājyaḥ kṣīṇo hatendri yaḥ"},{"type":"verse","number":"14","sanskrit":"पाण्डुरोगश्चिरोत्पन्नः खरीभूतो न सिध्यति कालप्रकर्षाच्छूनाङ्गो यो वा पीतानि पश्यति","text":"pāṇḍurogaścirotpannaḥ kharībhūto na sidhyati kālaprakarṣācchūnāṅgo yo vā pītāni paśyati"},{"type":"verse","number":"15","sanskrit":"बद्धाल्पविट् सहरितं सकफं योऽतिसार्यते दीनः स्वेदातिदिग्धाङ्गश्छर्दिमूर्च्छातृषाऽन्वितः","text":"baddhālpaviṭ saharitaṃ sakaphaṃ yo'tisāryate dīnaḥ svedātidigdhāṅgaśchardimūrcchātṛṣā'nvitaḥ"},{"type":"verse","number":"16","sanskrit":"पाण्डुदन्तनखो यस्तु पाण्डुनेत्रश्च यो भवेत् पाण्डुसङ्घातदर्शी च पाण्डुरोगी विनश्यति","text":"pāṇḍudantanakho yastu pāṇḍunetraśca yo bhavet pāṇḍusaṅghātadarśī ca pāṇḍurogī vinaśyati"},{"type":"verse","number":"17","sanskrit":"अन्तेषु शूनं परिहीणमध्यं म्लानं तथाऽन्तेषु च मध्यशूनम् गुदे मुखे शेफसि मुष्कयोश्च शूनं प्रताम्यन्तमसंज्ञकल्पम् विवर्जयेत्पाण्डुकिनं यशोऽथी तथाऽतिसारज्वरपीडितञ्च","text":"anteṣu śūnaṃ parihīṇamadhyaṃ mlānaṃ tathā'nteṣu ca madhyaśūnam gude mukhe śephasi muṣkayośca śūnaṃ pratāmyantamasaṃjñakalpam vivarjayetpāṇḍukinaṃ yaśo'thī tathā'tisārajvarapīḍitañca"},{"type":"verse","number":"18","sanskrit":"पाण्डुरोगी तु योऽत्यर्थं पित्तलानि निषेवते तस्य पित्तमसृङ्मांसं दग्ध्वा रोगाय कल्पते","text":"pāṇḍurogī tu yo'tyarthaṃ pittalāni niṣevate tasya pittamasṛṅmāṃsaṃ dagdhvā rogāya kalpate"},{"type":"verse","number":"19","sanskrit":"हारिद्र नेत्रः स भृशं हारिद्र त्वङ्नखाननः पीतरक्तशकृन्मूत्रो भेकवर्णो हतेन्द्रि यः","text":"hāridra netraḥ sa bhṛśaṃ hāridra tvaṅnakhānanaḥ pītaraktaśakṛnmūtro bhekavarṇo hatendri yaḥ"},{"type":"verse","number":"20","sanskrit":"दाहाविपाकदौर्बल्यसदनारुचिकर्षितः","text":"dāhāvipākadaurbalyasadanārucikarṣitaḥ"},{"type":"verse","number":"21","sanskrit":"कामलाबहुपित्तैषा कोष्ठशाखाऽश्रया मता कालान्तरात्खरीभूता कृच्छ्रास्यात्कुम्भकामला","text":"kāmalābahupittaiṣā koṣṭhaśākhā'śrayā matā kālāntarātkharībhūtā kṛcchrāsyātkumbhakāmalā"},{"type":"verse","number":"22","sanskrit":"छर्द्यरोचकहृल्लासज्वरक्लमनिपीडितः नश्यति श्वासकासार्त्तो विड्भेदी कुम्भकामली","text":"chardyarocakahṛllāsajvaraklamanipīḍitaḥ naśyati śvāsakāsārtto viḍbhedī kumbhakāmalī"},{"type":"verse","number":"23","sanskrit":"कृष्णपीतशकृन्मूत्रो भृशं शूनश्र मानवः सरक्ताक्षिमुखच्छर्दिविण्मूत्रो यश्च ताम्यति","text":"kṛṣṇapītaśakṛnmūtro bhṛśaṃ śūnaśra mānavaḥ saraktākṣimukhacchardiviṇmūtro yaśca tāmyati"},{"type":"verse","number":"24","sanskrit":"दाहारुचितृषाऽनाहतन्द्रा मोहसमन्वितः नष्टाग्निसंज्ञः क्षिप्रं हि कामलावान्विपद्यते","text":"dāhārucitṛṣā'nāhatandrā mohasamanvitaḥ naṣṭāgnisaṃjñaḥ kṣipraṃ hi kāmalāvānvipadyate"},{"type":"verse","number":"25","sanskrit":"यदा तु पाण्डोर्वर्णः स्याद्धरितश्यावपीतकः बलोत्साहक्षयस्तन्द्र मन्दाग्नित्वं मृदुज्वरः","text":"yadā tu pāṇḍorvarṇaḥ syāddharitaśyāvapītakaḥ balotsāhakṣayastandra mandāgnitvaṃ mṛdujvaraḥ"},{"type":"verse","number":"26","sanskrit":"स्त्रीष्वहर्षोऽङ्गमर्दश्च श्वासतृष्णाऽरुचिभ्रमाः हलीमकं तदा तस्य विद्यादनिलपित्ततः","text":"strīṣvaharṣo'ṅgamardaśca śvāsatṛṣṇā'rucibhramāḥ halīmakaṃ tadā tasya vidyādanilapittataḥ"},{"type":"verse","number":"27","sanskrit":"सप्तरात्रं गवां मूत्रैर्भावितञ्चायसो रजः पाण्डुरोगप्रशान्त्यर्थं पयसा प्रपिबेन्नरः","text":"saptarātraṃ gavāṃ mūtrairbhāvitañcāyaso rajaḥ pāṇḍurogapraśāntyarthaṃ payasā prapibennaraḥ"},{"type":"verse","number":"28","sanskrit":"गोमूत्रसिद्धं मण्डूरचूर्णं सगुडमश्नतः पाण्डुरोगः क्षयं याति पक्तिशूलञ्च दारुणम्","text":"gomūtrasiddhaṃ maṇḍūracūrṇaṃ saguḍamaśnataḥ pāṇḍurogaḥ kṣayaṃ yāti paktiśūlañca dāruṇam"},{"type":"verse","number":"29","sanskrit":"अयोमलं सुसन्तप्तं भूयो गोमूत्रसाधितम् मधुसर्पिर्युतं लीढ्वा पाण्डुरोगी सुखी भवेत्","text":"ayomalaṃ susantaptaṃ bhūyo gomūtrasādhitam madhusarpiryutaṃ līḍhvā pāṇḍurogī sukhī bhavet"},{"type":"verse","number":"30","sanskrit":"पुनर्नवा त्रिवृद्व्योषं विडङ्गं दारुचित्रकम् कुष्ठं हरिद्रे त्रिफला दन्ती चव्यं कलिङ्गकम्","text":"punarnavā trivṛdvyoṣaṃ viḍaṅgaṃ dārucitrakam kuṣṭhaṃ haridre triphalā dantī cavyaṃ kaliṅgakam"},{"type":"verse","number":"31","sanskrit":"कटुका पिप्पलीमूलं मुस्तं शृङ्गी च कारवी यवानी कट्फलञ्चेति पृथक्पलमितं समम्","text":"kaṭukā pippalīmūlaṃ mustaṃ śṛṅgī ca kāravī yavānī kaṭphalañceti pṛthakpalamitaṃ samam"},{"type":"verse","number":"32","sanskrit":"मण्डूरं द्विगुणं चूर्णाद् गोमूत्रेऽष्टगुणे पचेत् गुडेन वटकान्कृत्वा तक्रेणालोड्य तान्पिबेत्","text":"maṇḍūraṃ dviguṇaṃ cūrṇād gomūtre'ṣṭaguṇe pacet guḍena vaṭakānkṛtvā takreṇāloḍya tānpibet"},{"type":"verse","number":"33","sanskrit":"पुनर्नवादिमण्डूर वटकोऽश्विविनिर्मितः पाण्डुरोगं निहन्त्याशु कामलाञ्च हलीमकम्","text":"punarnavādimaṇḍūra vaṭako'śvivinirmitaḥ pāṇḍurogaṃ nihantyāśu kāmalāñca halīmakam"},{"type":"verse","number":"34","sanskrit":"श्वासं कासञ्च यक्ष्माणं ज्वरं शोथं तथोदरम् शूलं प्लीहानमाध्मानमर्शांसि ग्रहणीकृमीन् वातरक्तञ्च कुष्ठञ्च सेवनान्नाशयेद् ध्रुवम्","text":"śvāsaṃ kāsañca yakṣmāṇaṃ jvaraṃ śothaṃ tathodaram śūlaṃ plīhānamādhmānamarśāṃsi grahaṇīkṛmīn vātaraktañca kuṣṭhañca sevanānnāśayed dhruvam"},{"type":"verse","number":"35","sanskrit":"त्र्यूषणं त्रिफला मस्तं विडङ्गं चित्रकं तथा एतानि नवभागानि नवभागा हतायसः","text":"tryūṣaṇaṃ triphalā mastaṃ viḍaṅgaṃ citrakaṃ tathā etāni navabhāgāni navabhāgā hatāyasaḥ"},{"type":"verse","number":"36","sanskrit":"एतदेकीकृतं चूर्णं नरोऽष्टादशरक्तिकम् प्रलिह्यान्मधुसर्पिर्भ्यां पिबेत्तक्रेण वा सह","text":"etadekīkṛtaṃ cūrṇaṃ naro'ṣṭādaśaraktikam pralihyānmadhusarpirbhyāṃ pibettakreṇa vā saha"},{"type":"verse","number":"37","sanskrit":"गोमूत्रेण पिबेद्वाऽपि पाण्डुरोगं विनाशयेत् शोथं हृद्र्रोगमुदरकृमिकुष्ठं भगन्दरम्","text":"gomūtreṇa pibedvā'pi pāṇḍurogaṃ vināśayet śothaṃ hṛdrrogamudarakṛmikuṣṭhaṃ bhagandaram"},{"type":"verse","number":"38","sanskrit":"नाशयेदग्निमान्द्यञ्च दुर्नामकमरोचकम् आर्द्र कस्य रसेनापि लिह्यात्कफसमृद्धिमान्","text":"nāśayedagnimāndyañca durnāmakamarocakam ārdra kasya rasenāpi lihyātkaphasamṛddhimān"},{"type":"verse","number":"39","sanskrit":"त्रिफलाया गुडूच्यावा दार्व्या मरिचकस्य वा क्वाथो माक्षिकसंयुक्तः शीतलः कामलाऽपहः","text":"triphalāyā guḍūcyāvā dārvyā maricakasya vā kvātho mākṣikasaṃyuktaḥ śītalaḥ kāmalā'pahaḥ"},{"type":"verse","number":"40","sanskrit":"अञ्जने कामलार्त्तानां द्रो णपुष्पीरसो हितः गुडूचीपत्रकल्कं वा पिबेत्तक्रेण कामली","text":"añjane kāmalārttānāṃ dro ṇapuṣpīraso hitaḥ guḍūcīpatrakalkaṃ vā pibettakreṇa kāmalī"},{"type":"verse","number":"41","sanskrit":"धात्रीलौहरजोव्योषनिशाक्षौद्रा ज्यशर्कराः लीढा निवारयन्त्याशु कामलामुद्धतामपि","text":"dhātrīlauharajovyoṣaniśākṣaudrā jyaśarkarāḥ līḍhā nivārayantyāśu kāmalāmuddhatāmapi"},{"type":"verse","number":"42","sanskrit":"कुम्भाख्यकामलायां तु हितः कामलिको विधिः गोमूत्रेण पिबेत्कुम्भकामलावाञ्छिलाजतुम्","text":"kumbhākhyakāmalāyāṃ tu hitaḥ kāmaliko vidhiḥ gomūtreṇa pibetkumbhakāmalāvāñchilājatum"},{"type":"verse","number":"43","sanskrit":"दग्धाऽक्षकाष्ठैर्मलमायसन्तु गोमूत्रनिर्वापितमष्टवारान् विचूर्ण्य लीढं मधुनाऽचिरेण कुम्भाह्वयं पाण्डुगदं निहन्ति","text":"dagdhā'kṣakāṣṭhairmalamāyasantu gomūtranirvāpitamaṣṭavārān vicūrṇya līḍhaṃ madhunā'cireṇa kumbhāhvayaṃ pāṇḍugadaṃ nihanti"},{"type":"verse","number":"44","sanskrit":"अपहरति कामलार्तिं नस्येन कुमारिकाजलं सद्यः","text":"apaharati kāmalārtiṃ nasyena kumārikājalaṃ sadyaḥ"},{"type":"verse","number":"45","sanskrit":"मारितं चायसं चूर्णं मुस्ताचूर्णेन संयुतम् खदिरस्य कषायेण पिबेद्धन्तुं हलीमकम्","text":"māritaṃ cāyasaṃ cūrṇaṃ mustācūrṇena saṃyutam khadirasya kaṣāyeṇa pibeddhantuṃ halīmakam"},{"type":"verse","number":"46","sanskrit":"सितातिलबलायष्टित्रिफलारजनीयुगैः लौहं लिह्यात्समध्वाज्यं हलीमकनिवृत्तये","text":"sitātilabalāyaṣṭitriphalārajanīyugaiḥ lauhaṃ lihyātsamadhvājyaṃ halīmakanivṛttaye"},{"type":"verse","number":"47","sanskrit":"अमृतलतारसकल्कं प्रसाधितंतुरगविद्विषः सर्पिः क्षीरं चतुर्गुणमेतद्वितरेच्च हलीमकार्त्तेभ्यः","text":"amṛtalatārasakalkaṃ prasādhitaṃturagavidviṣaḥ sarpiḥ kṣīraṃ caturguṇametadvitarecca halīmakārttebhyaḥ"},{"type":"verse","number":"48","sanskrit":"मधुरैरन्नपानैस्तं वातपित्तहरैर्हरेत् कामलापाण्डुरोगोक्तां क्रियां चात्रोपयोजयेत्","text":"madhurairannapānaistaṃ vātapittaharairharet kāmalāpāṇḍurogoktāṃ kriyāṃ cātropayojayet"},{"type":"verse","number":"49","sanskrit":"फलत्रिकामृतावासातिक्ताभूनिम्बनिम्बजः क्वाथः क्षौद्र युतोऽय हन्याद्धलीमकं पाण्डुकामलारोगम्","text":"phalatrikāmṛtāvāsātiktābhūnimbanimbajaḥ kvāthaḥ kṣaudra yuto'ya hanyāddhalīmakaṃ pāṇḍukāmalārogam"},{"type":"verse","number":"50","sanskrit":"त्र्यूषणंत्रिफला मुस्तं विडङ्गं चव्यचित्रकम् दार्वीत्वङ् माक्षिको धातुर्ग्रन्थिको देवदारु च","text":"tryūṣaṇaṃtriphalā mustaṃ viḍaṅgaṃ cavyacitrakam dārvītvaṅ mākṣiko dhāturgranthiko devadāru ca"},{"type":"verse","number":"51","sanskrit":"एषां द्विपलिकान्भागान्कृत्वा चूर्णं पृथक्पृथक् मण्डूरचूर्णं द्विगुणंशुद्धमञ्जनसन्निभम्","text":"eṣāṃ dvipalikānbhāgānkṛtvā cūrṇaṃ pṛthakpṛthak maṇḍūracūrṇaṃ dviguṇaṃśuddhamañjanasannibham"},{"type":"verse","number":"52","sanskrit":"मूत्रे चाष्टगुणे पक्त्वा तस्मिंस्तत्प्रक्षिपेन्नरः उदुम्बरसमाकारान्वटकांस्तान्यथाऽग्नि च","text":"mūtre cāṣṭaguṇe paktvā tasmiṃstatprakṣipennaraḥ udumbarasamākārānvaṭakāṃstānyathā'gni ca"},{"type":"verse","number":"53","sanskrit":"उपयुञ्जीत तक्रेण जीर्णे सात्म्यञ्च भोजनम् मण्डूरवटिका ह्येताः प्राणदाः पाण्डुरोगिणाम्","text":"upayuñjīta takreṇa jīrṇe sātmyañca bhojanam maṇḍūravaṭikā hyetāḥ prāṇadāḥ pāṇḍurogiṇām"},{"type":"verse","number":"54","sanskrit":"कुष्ठानि जठरं शोथमूरुस्तम्भं कफामयान् अर्शांसि कामलां मेहंप्लीहानं शमयन्ति च","text":"kuṣṭhāni jaṭharaṃ śothamūrustambhaṃ kaphāmayān arśāṃsi kāmalāṃ mehaṃplīhānaṃ śamayanti ca"},{"type":"verse","number":"55","sanskrit":"किराततिक्ता सुरदारु दार्वी मुस्ता गुडूची कटुका पटोलम् दुरालभा पर्पटकं सनिम्बं कटुत्रिकं वह्निफलत्रिकञ्च","text":"kirātatiktā suradāru dārvī mustā guḍūcī kaṭukā paṭolam durālabhā parpaṭakaṃ sanimbaṃ kaṭutrikaṃ vahniphalatrikañca"},{"type":"verse","number":"56","sanskrit":"फलं विडङ्गस्य समांशकानि सर्वैः समं चूर्णकमायसञ्च सर्पिर्मधुभ्यां वटिका विधेया तक्रानुपानाद्भिषजा प्रयोज्या","text":"phalaṃ viḍaṅgasya samāṃśakāni sarvaiḥ samaṃ cūrṇakamāyasañca sarpirmadhubhyāṃ vaṭikā vidheyā takrānupānādbhiṣajā prayojyā"},{"type":"verse","number":"57","sanskrit":"निहन्ति पाण्डुञ्च हलीमकं च शोथं प्रमेहं ग्रहणीरुजञ्ज श्वासञ्ज कासञ्च सरक्तपित्तमर्शांस्यथो वाग्ग्रहमामवातम् व्रणांश्च गुल्मान्कफविद्र धिञ्च श्वित्रञ्च कुष्ठञ्च ततः प्रयोगात्","text":"nihanti pāṇḍuñca halīmakaṃ ca śothaṃ pramehaṃ grahaṇīrujañja śvāsañja kāsañca saraktapittamarśāṃsyatho vāggrahamāmavātam vraṇāṃśca gulmānkaphavidra dhiñca śvitrañca kuṣṭhañca tataḥ prayogāt"},{"type":"verse","number":"58","sanskrit":"यवगोधूमशाल्यन्नैः रसैर्जाङ्गलजैर्हितैः मुद्गाढकीमसूराद्यैरेषु भोजनमिष्यते","text":"yavagodhūmaśālyannaiḥ rasairjāṅgalajairhitaiḥ mudgāḍhakīmasūrādyaireṣu bhojanamiṣyate"},{"type":"verse","number":"59","sanskrit":"इत्यष्टमः पाण्डुरोगकामलाहलीमकाधिकारः समाप्तः ८","text":"ityaṣṭamaḥ pāṇḍurogakāmalāhalīmakādhikāraḥ samāptaḥ 8"}]},{"sthana":"Уттаракханда","number":9,"lang":"sa","content":[{"type":"heading","heading":"Рактапитта — кровотечения"},{"type":"verse","number":"1","sanskrit":"घर्मव्यायामशोकाध्वव्यवायैरतिसेवितैः तीक्ष्णोष्णक्षारलवणैरम्लैः कटुभिरेव च पित्तं विदग्धं स्वगुणैर्विदहत्याशु शोणितम्","text":"gharmavyāyāmaśokādhvavyavāyairatisevitaiḥ tīkṣṇoṣṇakṣāralavaṇairamlaiḥ kaṭubhireva ca pittaṃ vidagdhaṃ svaguṇairvidahatyāśu śoṇitam"},{"type":"verse","number":"2","sanskrit":"ततः प्रवर्त्तते रक्तमूर्ध्वं चाधो द्विधाऽपि वा","text":"tataḥ pravarttate raktamūrdhvaṃ cādho dvidhā'pi vā"},{"type":"verse","number":"3","sanskrit":"ऊर्ध्वं नासाऽक्षिकर्णास्यैर्मेढ्रयोनिगुदैरधः कुपितं रोमकूपैश्च समस्तैस्तत्प्रवर्त्तते","text":"ūrdhvaṃ nāsā'kṣikarṇāsyairmeḍhrayonigudairadhaḥ kupitaṃ romakūpaiśca samastaistatpravarttate"},{"type":"verse","number":"4","sanskrit":"सदनं शीतकामित्वं कण्ठधूमायनं वमिः लौहगन्धस्य निश्वासो भवत्यस्मिन्भविष्यति","text":"sadanaṃ śītakāmitvaṃ kaṇṭhadhūmāyanaṃ vamiḥ lauhagandhasya niśvāso bhavatyasminbhaviṣyati"},{"type":"verse","number":"5","sanskrit":"सान्द्रं सपाण्डु सस्नेहं पिच्छिलं च कफान्वितम् श्यावारुणं सफेनं च तनु रूक्षञ्च वातिकम्","text":"sāndraṃ sapāṇḍu sasnehaṃ picchilaṃ ca kaphānvitam śyāvāruṇaṃ saphenaṃ ca tanu rūkṣañca vātikam"},{"type":"verse","number":"6","sanskrit":"रक्तपित्तंकषायाभं कृष्णं गोमूत्रसन्निभम् मेचकाङ्गारधूमाभमञ्जनाभञ्च पैत्तिकम्","text":"raktapittaṃkaṣāyābhaṃ kṛṣṇaṃ gomūtrasannibham mecakāṅgāradhūmābhamañjanābhañca paittikam"},{"type":"verse","number":"7","sanskrit":"संसृष्टलिङ्गसंसर्गात्त्रिलिङ्गं सान्निपातिकम् ऊर्ध्वगं कफसंसृष्टमधोगं मारुतानुगम् द्विमार्गं कफवाताभ्यामुभाभ्यां तत्प्रवर्त्तते","text":"saṃsṛṣṭaliṅgasaṃsargāttriliṅgaṃ sānnipātikam ūrdhvagaṃ kaphasaṃsṛṣṭamadhogaṃ mārutānugam dvimārgaṃ kaphavātābhyāmubhābhyāṃ tatpravarttate"},{"type":"verse","number":"8","sanskrit":"दौर्बल्यश्वासकासज्वरवमथुमदाः पाण्डुतादाहमूर्च्छा भुक्ते घोरो विदाहस्त्वधृतिरपि सदा हृद्यतुल्या च पीडा तृष्णा कोष्ठस्य भेदः शिरसि च तपनं पूयनिष्ठीवनञ्च द्वेषो भक्तेऽविपाको विकृतिरपिभवेद्र क्तपित्तोपसर्गाः","text":"daurbalyaśvāsakāsajvaravamathumadāḥ pāṇḍutādāhamūrcchā bhukte ghoro vidāhastvadhṛtirapi sadā hṛdyatulyā ca pīḍā tṛṣṇā koṣṭhasya bhedaḥ śirasi ca tapanaṃ pūyaniṣṭhīvanañca dveṣo bhakte'vipāko vikṛtirapibhavedra ktapittopasargāḥ"},{"type":"verse","number":"9","sanskrit":"एकदोषानुगं साध्यं द्विदोषं याप्यमुच्यते यत्त्रिदोषमसाध्यं स्यान्मन्दाग्नेरतिवेगवत्","text":"ekadoṣānugaṃ sādhyaṃ dvidoṣaṃ yāpyamucyate yattridoṣamasādhyaṃ syānmandāgnerativegavat"},{"type":"verse","number":"10","sanskrit":"ऊर्ध्वं साध्यमधो याप्यमसाध्यं युगपद्गतम् व्याधिभिः क्षीणदेहस्य वृद्धस्यानश्नतस्तु यत्","text":"ūrdhvaṃ sādhyamadho yāpyamasādhyaṃ yugapadgatam vyādhibhiḥ kṣīṇadehasya vṛddhasyānaśnatastu yat"},{"type":"verse","number":"11","sanskrit":"एकमार्गं बलवतो नातिवेगं नवोत्थितम् रक्तपित्तं सुखे काले साध्यं स्यान्निरुपद्र्रवम्","text":"ekamārgaṃ balavato nātivegaṃ navotthitam raktapittaṃ sukhe kāle sādhyaṃ syānnirupadrravam"},{"type":"verse","number":"12","sanskrit":"मांसप्रक्षालनाभं क्वथितमिव च यत्कर्दमाम्भोनिभं वा मेदः पूयास्रकल्पं यकृदिव यदि वा पक्वजम्बूफलाभम् यत्कृष्णं यच्च नीलं भृशमपि कुणपं यत्र चोक्ता विकारा स्तद्वर्ज्यं रक्तपित्तं सुरपतिधनुषा यच्च तुल्यं विभाति","text":"māṃsaprakṣālanābhaṃ kvathitamiva ca yatkardamāmbhonibhaṃ vā medaḥ pūyāsrakalpaṃ yakṛdiva yadi vā pakvajambūphalābham yatkṛṣṇaṃ yacca nīlaṃ bhṛśamapi kuṇapaṃ yatra coktā vikārā stadvarjyaṃ raktapittaṃ surapatidhanuṣā yacca tulyaṃ vibhāti"},{"type":"verse","number":"13","sanskrit":"येन चोपहतो रक्तं रक्तपित्तेन मानवः पश्येद् दृश्यं वियच्चापि तदसाध्यमसंशयम्","text":"yena copahato raktaṃ raktapittena mānavaḥ paśyed dṛśyaṃ viyaccāpi tadasādhyamasaṃśayam"},{"type":"verse","number":"14","sanskrit":"लोहितं छर्दयेद्यस्तु बहुशो लोहितेक्षणः लोहितोद्गारदर्शी च म्रियते रक्तपैत्तिकः","text":"lohitaṃ chardayedyastu bahuśo lohitekṣaṇaḥ lohitodgāradarśī ca mriyate raktapaittikaḥ"},{"type":"verse","number":"15","sanskrit":"पित्तास्रं स्तम्भयेन्नादौ प्रवृत्तं बलिनो यतः हृत्पाण्डुग्रहणीरोगप्लीहगुल्मज्वरादिकृत्","text":"pittāsraṃ stambhayennādau pravṛttaṃ balino yataḥ hṛtpāṇḍugrahaṇīrogaplīhagulmajvarādikṛt"},{"type":"verse","number":"16","sanskrit":"शालिषष्टिकनीवारकोरदूषप्रसाधिकाः श्यामाकाश्च प्रियङ्गुश्च भोजनं रक्तपित्तिनाम्","text":"śāliṣaṣṭikanīvārakoradūṣaprasādhikāḥ śyāmākāśca priyaṅguśca bhojanaṃ raktapittinām"},{"type":"verse","number":"17","sanskrit":"मसूरमुद्गचणकाः समकुष्ठाढकीफलाः प्रशस्ताः सूपयूषार्थे कल्पिता रक्तपित्तिनाम्","text":"masūramudgacaṇakāḥ samakuṣṭhāḍhakīphalāḥ praśastāḥ sūpayūṣārthe kalpitā raktapittinām"},{"type":"verse","number":"18","sanskrit":"दाडिमामलकं विद्वानम्लार्थं चापि दापयेत् पटोलनिम्बन्यग्रोधप्लक्षवेतसपल्लवाः","text":"dāḍimāmalakaṃ vidvānamlārthaṃ cāpi dāpayet paṭolanimbanyagrodhaplakṣavetasapallavāḥ"},{"type":"verse","number":"19","sanskrit":"शाकार्थं शाकसात्म्यानां तण्डुलीयादयो हिताः पारावतान्कपोतांश्च लावान् रक्ताक्षवर्त्तकान्","text":"śākārthaṃ śākasātmyānāṃ taṇḍulīyādayo hitāḥ pārāvatānkapotāṃśca lāvān raktākṣavarttakān"},{"type":"verse","number":"20","sanskrit":"शशान्कपिञ्जलानेणान्हरिणान्कालपुच्छजान् रक्तपित्तहरान्विद्याद्र्रसांस्तेषां प्रयोजयेत्","text":"śaśānkapiñjalāneṇānhariṇānkālapucchajān raktapittaharānvidyādrrasāṃsteṣāṃ prayojayet"},{"type":"verse","number":"21","sanskrit":"ईषदम्लाननम्लांश्च घृतभृष्टान्ससैन्धवान् कफानुगे यूषशाकान्दद्याद्वातानुगे रसम्","text":"īṣadamlānanamlāṃśca ghṛtabhṛṣṭānsasaindhavān kaphānuge yūṣaśākāndadyādvātānuge rasam"},{"type":"verse","number":"22","sanskrit":"पथ्यं सतीनयूषेण ससितैर्लाजसक्तुभिः","text":"pathyaṃ satīnayūṣeṇa sasitairlājasaktubhiḥ"},{"type":"verse","number":"23","sanskrit":"धान्याकधात्रीवासानां द्रा क्षापर्पटयोर्हिमः रक्तपित्तं ज्वरं दाहं तृष्णां शोषञ्च नाशयेत्","text":"dhānyākadhātrīvāsānāṃ drā kṣāparpaṭayorhimaḥ raktapittaṃ jvaraṃ dāhaṃ tṛṣṇāṃ śoṣañca nāśayet"},{"type":"verse","number":"24","sanskrit":"ह्रीबेरमुत्पलं धान्यं चन्दनं यष्टिकाऽमृता उशीरञ्च त्रिवृच्चैषां क्वाथं समधुशर्करम्","text":"hrīberamutpalaṃ dhānyaṃ candanaṃ yaṣṭikā'mṛtā uśīrañca trivṛccaiṣāṃ kvāthaṃ samadhuśarkaram"},{"type":"verse","number":"25","sanskrit":"पाययेत्तेन सद्यो हि रक्तपित्तं प्रणश्यति रक्तपित्तं जयत्युग्रं तृष्णां दाहं ज्वरं तथा","text":"pāyayettena sadyo hi raktapittaṃ praṇaśyati raktapittaṃ jayatyugraṃ tṛṣṇāṃ dāhaṃ jvaraṃ tathā"},{"type":"verse","number":"26","sanskrit":"पद्मोत्पलानां किञ्जल्कः पृश्निपर्णीप्रियङ्गुकाः जले साध्या रसे तस्मिन्पेया स्याद्र क्तपित्तिनाम्","text":"padmotpalānāṃ kiñjalkaḥ pṛśniparṇīpriyaṅgukāḥ jale sādhyā rase tasminpeyā syādra ktapittinām"},{"type":"verse","number":"27","sanskrit":"वासापत्रसमुद्भूतो रसः समधुशर्करः क्वाथो वा हरते पीतो रक्तपित्तं सुदारुणम्","text":"vāsāpatrasamudbhūto rasaḥ samadhuśarkaraḥ kvātho vā harate pīto raktapittaṃ sudāruṇam"},{"type":"verse","number":"28","sanskrit":"पिष्टानां वृषपत्राणां पुटपाकरसो हिमः समधुर्हरते रक्तपित्तं कासज्वरक्षयान्","text":"piṣṭānāṃ vṛṣapatrāṇāṃ puṭapākaraso himaḥ samadhurharate raktapittaṃ kāsajvarakṣayān"},{"type":"verse","number":"29","sanskrit":"उत्पलं कुमुदं पद्मं कह्लारं लोहितोत्पलम् मधुकञ्चेति पित्तासृक्तृष्णाच्छर्दिहरो गणः","text":"utpalaṃ kumudaṃ padmaṃ kahlāraṃ lohitotpalam madhukañceti pittāsṛktṛṣṇācchardiharo gaṇaḥ"},{"type":"verse","number":"30","sanskrit":"वासायां विद्यमानायामाशायां जीवितस्य च रक्तपित्ती क्षयी कासी किमर्थमवसीदति","text":"vāsāyāṃ vidyamānāyāmāśāyāṃ jīvitasya ca raktapittī kṣayī kāsī kimarthamavasīdati"},{"type":"verse","number":"31","sanskrit":"आटरूषक मृद्वीका पथ्याक्वाथः सशर्करः क्षौद्र्राढ्यःसकलश्वासरक्तपित्तनिबर्हणः","text":"āṭarūṣaka mṛdvīkā pathyākvāthaḥ saśarkaraḥ kṣaudrrāḍhyaḥsakalaśvāsaraktapittanibarhaṇaḥ"},{"type":"verse","number":"32","sanskrit":"दूर्वा सोत्पलकिञ्जल्कमञ्जिष्ठासैलवालुका शीता शीतमुशीरञ्च मुस्तं चन्दनपद्मकम्","text":"dūrvā sotpalakiñjalkamañjiṣṭhāsailavālukā śītā śītamuśīrañca mustaṃ candanapadmakam"},{"type":"verse","number":"33","sanskrit":"विपचेत्कार्षिकैरेतैराजं प्रस्थमितं घृतम् तण्डुलानां जलं छागीक्षीरं दद्याच्चतुर्गुणम्","text":"vipacetkārṣikairetairājaṃ prasthamitaṃ ghṛtam taṇḍulānāṃ jalaṃ chāgīkṣīraṃ dadyāccaturguṇam"},{"type":"verse","number":"34","sanskrit":"तत्पानं वमतो रक्तं नावनं नासिकागते कर्णाभ्यां यस्य गच्छेत्तु तस्य कणौ प्रपूरयेत्","text":"tatpānaṃ vamato raktaṃ nāvanaṃ nāsikāgate karṇābhyāṃ yasya gacchettu tasya kaṇau prapūrayet"},{"type":"verse","number":"35","sanskrit":"चक्षुः स्रवति रक्तञ्चेत्पूरयेत्तेन चक्षुषी मेढ्रपायुप्रवृत्ते तु वस्तिकर्मसु योजयेत्","text":"cakṣuḥ sravati raktañcetpūrayettena cakṣuṣī meḍhrapāyupravṛtte tu vastikarmasu yojayet"},{"type":"verse","number":"36","sanskrit":"रोमकूपप्रवृत्ते तु तदभ्यङ्गं प्रयोजयेत् सर्वेषु रक्तपित्तेषु तस्माच्छ्रेष्ठमिदं घृतम्","text":"romakūpapravṛtte tu tadabhyaṅgaṃ prayojayet sarveṣu raktapitteṣu tasmācchreṣṭhamidaṃ ghṛtam"},{"type":"verse","number":"37","sanskrit":"मृद्वीकां चन्दनं लोध्रं प्रियङ्गुञ्च विचूर्णयेत् चूर्णमेतत्पिबेत्क्षौद्र वासारससमन्वितम्","text":"mṛdvīkāṃ candanaṃ lodhraṃ priyaṅguñca vicūrṇayet cūrṇametatpibetkṣaudra vāsārasasamanvitam"},{"type":"verse","number":"38","sanskrit":"नासिकामुखपायुभ्यो योनिमेढ्रादिवेगितम् रक्तपित्तं स्रवद्धन्ति सिद्ध एष प्रयोगराट्","text":"nāsikāmukhapāyubhyo yonimeḍhrādivegitam raktapittaṃ sravaddhanti siddha eṣa prayogarāṭ"},{"type":"verse","number":"39","sanskrit":"यच्च शस्त्रक्षतेनेव रक्तं स्रवति वेगतः तदप्येतेन चूर्णेन तिष्ठत्येवावचूर्णितम्","text":"yacca śastrakṣateneva raktaṃ sravati vegataḥ tadapyetena cūrṇena tiṣṭhatyevāvacūrṇitam"},{"type":"verse","number":"40","sanskrit":"इक्षूणां मध्यकाण्डानि सकन्दं नीलमुत्पलम् केशरं पुण्डरीकस्य मोचामधुकपद्मकैः","text":"ikṣūṇāṃ madhyakāṇḍāni sakandaṃ nīlamutpalam keśaraṃ puṇḍarīkasya mocāmadhukapadmakaiḥ"},{"type":"verse","number":"41","sanskrit":"वटप्ररोहशुङ्गाश्च द्रा क्षा खर्जूरमेव च एतानि समभागानि कषायं सम्प्रकल्पयेत्","text":"vaṭaprarohaśuṅgāśca drā kṣā kharjūrameva ca etāni samabhāgāni kaṣāyaṃ samprakalpayet"},{"type":"verse","number":"42","sanskrit":"उषितं मधुसंयुक्तं पाययेच्छर्कराऽन्वितम् सप्रमेहं रक्तपित्तं क्षिप्रमेतन्नियच्छति","text":"uṣitaṃ madhusaṃyuktaṃ pāyayeccharkarā'nvitam sapramehaṃ raktapittaṃ kṣiprametanniyacchati"},{"type":"verse","number":"43","sanskrit":"द्रा क्षया फलिनीभिर्वा प्रियालमधुकेन वा श्वदंष्ट्रया शतावर्या रक्तजित्साधितं पयः","text":"drā kṣayā phalinībhirvā priyālamadhukena vā śvadaṃṣṭrayā śatāvaryā raktajitsādhitaṃ payaḥ"},{"type":"verse","number":"44","sanskrit":"पक्वोदुम्बरकाश्मर्यः पथ्याखर्जूरगोस्तनाः मधुना घ्नन्ति संलीढा रक्तपित्तं पृथक्पृथक्","text":"pakvodumbarakāśmaryaḥ pathyākharjūragostanāḥ madhunā ghnanti saṃlīḍhā raktapittaṃ pṛthakpṛthak"},{"type":"verse","number":"45","sanskrit":"अतिनिःसृतरक्तो वा क्षौद्र्रयुक्तं पिबेदसृक् यकृद्वा भक्षयेदाजं मांसं वा पित्तसंयुतम्","text":"atiniḥsṛtarakto vā kṣaudrrayuktaṃ pibedasṛk yakṛdvā bhakṣayedājaṃ māṃsaṃ vā pittasaṃyutam"},{"type":"verse","number":"46","sanskrit":"नासाप्रवृत्तरुधिरं घृतभृष्टं श्लक्ष्णपिष्टमामलकम् सेतुरिव तोयवेगं रुणद्धि मूर्ध्नि प्रलेपेन","text":"nāsāpravṛttarudhiraṃ ghṛtabhṛṣṭaṃ ślakṣṇapiṣṭamāmalakam seturiva toyavegaṃ ruṇaddhi mūrdhni pralepena"},{"type":"verse","number":"47","sanskrit":"घ्राणप्रवृत्ते जलमाशु पेयं सशर्करं नासिकया च यो वा द्रा क्षारसं क्षीरघृतं पिबेद्वा सशर्करञ्चेक्षुरसं हिमं वा","text":"ghrāṇapravṛtte jalamāśu peyaṃ saśarkaraṃ nāsikayā ca yo vā drā kṣārasaṃ kṣīraghṛtaṃ pibedvā saśarkarañcekṣurasaṃ himaṃ vā"},{"type":"verse","number":"48","sanskrit":"नस्ये दाडिमपुष्पस्य रसो दूर्वाभवोऽपि वा आम्रास्थिजः पलाण्डोर्वा नासिकास्राविरक्तजित्","text":"nasye dāḍimapuṣpasya raso dūrvābhavo'pi vā āmrāsthijaḥ palāṇḍorvā nāsikāsrāviraktajit"},{"type":"verse","number":"49","sanskrit":"पुराणं पीनमानीय कूष्माण्डस्य फलं बृहत् तद्बीजाधारबीजत्वक्छिराशून्यं समाचरेत्","text":"purāṇaṃ pīnamānīya kūṣmāṇḍasya phalaṃ bṛhat tadbījādhārabījatvakchirāśūnyaṃ samācaret"},{"type":"verse","number":"50","sanskrit":"ततस्तस्य तुलां नीत्वा पचेज्जलतुलाद्वये तस्मिन्नीरेऽद्धशिष्टे तु यत्नतः शीतलीकृते","text":"tatastasya tulāṃ nītvā pacejjalatulādvaye tasminnīre'ddhaśiṣṭe tu yatnataḥ śītalīkṛte"},{"type":"verse","number":"51","sanskrit":"तानि कूष्माण्डखण्डानि पीडयेद् दृढवाससा यत्नतस्तज्जलं नीत्वा पुनः पाकाय धारयेत्","text":"tāni kūṣmāṇḍakhaṇḍāni pīḍayed dṛḍhavāsasā yatnatastajjalaṃ nītvā punaḥ pākāya dhārayet"},{"type":"verse","number":"52","sanskrit":"कूष्माण्डं शोषयेद्घर्मे ताम्रपात्रे ततः क्षिपेत् क्षिप्त्वा तत्र घृतं प्रस्थं कूष्माण्डं तेन भर्जयेत्","text":"kūṣmāṇḍaṃ śoṣayedgharme tāmrapātre tataḥ kṣipet kṣiptvā tatra ghṛtaṃ prasthaṃ kūṣmāṇḍaṃ tena bharjayet"},{"type":"verse","number":"53","sanskrit":"मधुवर्णं तदालोक्य तज्जलं तत्र निक्षिपेत् सितायाश्च तुलां तत्र क्षिप्त्वा तल्लेहवत्पचेत्","text":"madhuvarṇaṃ tadālokya tajjalaṃ tatra nikṣipet sitāyāśca tulāṃ tatra kṣiptvā tallehavatpacet"},{"type":"verse","number":"54","sanskrit":"सुपक्वे पिप्पलीशुण्ठीजीराणां द्विपले पृथक् पृथक्पलार्द्धं धान्याकं पत्रैलामरिचत्वचम्","text":"supakve pippalīśuṇṭhījīrāṇāṃ dvipale pṛthak pṛthakpalārddhaṃ dhānyākaṃ patrailāmaricatvacam"},{"type":"verse","number":"55","sanskrit":"चूर्णमेषां क्षिपेत्तत्र घृतार्द्धं क्षौद्र्रमावपेत् एतत्पलमितं खादेदथ वाऽग्निबलं यथा","text":"cūrṇameṣāṃ kṣipettatra ghṛtārddhaṃ kṣaudrramāvapet etatpalamitaṃ khādedatha vā'gnibalaṃ yathā"},{"type":"verse","number":"56","sanskrit":"खण्डकूष्माण्डलेहोऽय रक्तपित्तञ्च नाशयेत् पित्तज्वरं तृषां दाहं प्रदरं कृशतां वमिम्","text":"khaṇḍakūṣmāṇḍaleho'ya raktapittañca nāśayet pittajvaraṃ tṛṣāṃ dāhaṃ pradaraṃ kṛśatāṃ vamim"},{"type":"verse","number":"57","sanskrit":"कासं श्वासञ्च हृद्र्रोगं स्वरभेदं क्षतं क्षयम् नाशयत्येव वृद्धिञ्च बृंहणो बलवर्द्धनः","text":"kāsaṃ śvāsañca hṛdrrogaṃ svarabhedaṃ kṣataṃ kṣayam nāśayatyeva vṛddhiñca bṛṃhaṇo balavarddhanaḥ"},{"type":"verse","number":"58","sanskrit":"पुराणं पीनमानीय कूष्माडस्य फलं दृढम् तद्वीजाधारबीजत्वक्छिराशून्यं समाचरेत्","text":"purāṇaṃ pīnamānīya kūṣmāḍasya phalaṃ dṛḍham tadvījādhārabījatvakchirāśūnyaṃ samācaret"},{"type":"verse","number":"59","sanskrit":"ततोऽतिसूक्ष्मखण्डानि कृत्वा तस्य तुलां पचेत् गोदुग्धस्य तुलामध्ये मन्देऽग्नौ वा पचेच्छनैः","text":"tato'tisūkṣmakhaṇḍāni kṛtvā tasya tulāṃ pacet godugdhasya tulāmadhye mande'gnau vā pacecchanaiḥ"},{"type":"verse","number":"60","sanskrit":"शर्करायास्तुलां सार्द्धां गोघृतं प्रस्थमात्रकम् प्रस्थार्द्धं माक्षिकञ्चापि कुडवं नारिकेलतः","text":"śarkarāyāstulāṃ sārddhāṃ goghṛtaṃ prasthamātrakam prasthārddhaṃ mākṣikañcāpi kuḍavaṃ nārikelataḥ"},{"type":"verse","number":"61","sanskrit":"प्रियालफलमज्जानां द्विपलं तिखुरीपलम् क्षिपेदेकं च विपचेल्लेहवत्साधु साधयेत्","text":"priyālaphalamajjānāṃ dvipalaṃ tikhurīpalam kṣipedekaṃ ca vipacellehavatsādhu sādhayet"},{"type":"verse","number":"62","sanskrit":"भिषक्सुपक्वमालोक्य ज्वलनादवतारयेद् कोष्णे तत्र क्षिपेदेषां चूर्णं तानि वदाम्यहम्","text":"bhiṣaksupakvamālokya jvalanādavatārayed koṣṇe tatra kṣipedeṣāṃ cūrṇaṃ tāni vadāmyaham"},{"type":"verse","number":"63","sanskrit":"एकोऽक्ष शतपुष्पाया अथ क्षीरी यवानिका गोक्षुरः क्षुरकः पथ्या कपिकच्छुफलानि च","text":"eko'kṣa śatapuṣpāyā atha kṣīrī yavānikā gokṣuraḥ kṣurakaḥ pathyā kapikacchuphalāni ca"},{"type":"verse","number":"64","sanskrit":"सप्तमी त्वक्च सर्वेषामक्षयुग्मं पृथक्पृथक् धान्यकं पिप्पली मुस्तमश्वगन्धा शतावरी","text":"saptamī tvakca sarveṣāmakṣayugmaṃ pṛthakpṛthak dhānyakaṃ pippalī mustamaśvagandhā śatāvarī"},{"type":"verse","number":"65","sanskrit":"तालमूली नागबला बालकं पत्रकं शटी जातीफलं लवङ्गञ्च सूक्ष्मैला बृहदेलिका","text":"tālamūlī nāgabalā bālakaṃ patrakaṃ śaṭī jātīphalaṃ lavaṅgañca sūkṣmailā bṛhadelikā"},{"type":"verse","number":"66","sanskrit":"शृङ्गाटकं पर्पटकं सर्वं पलमितं पृथक् चन्दनं नागरं धात्रीफलञ्चापि कशेरुजम्","text":"śṛṅgāṭakaṃ parpaṭakaṃ sarvaṃ palamitaṃ pṛthak candanaṃ nāgaraṃ dhātrīphalañcāpi kaśerujam"},{"type":"verse","number":"67","sanskrit":"प्रत्येकं पञ्चकर्षाणि चत्वार्येतानि निक्षिपेत् पलद्वयमुशीरस्य मसनस्योषणस्य च","text":"pratyekaṃ pañcakarṣāṇi catvāryetāni nikṣipet paladvayamuśīrasya masanasyoṣaṇasya ca"},{"type":"verse","number":"68","sanskrit":"कूष्माण्डस्यावलेहोऽय भक्षितः पलमात्रया किं वा यथावह्निबलं भुक्त्वारोगान्विनाशयेत्","text":"kūṣmāṇḍasyāvaleho'ya bhakṣitaḥ palamātrayā kiṃ vā yathāvahnibalaṃ bhuktvārogānvināśayet"},{"type":"verse","number":"69","sanskrit":"रक्तपित्तं शीतपित्तमम्लपित्तमरोचकम् बह्निमान्द्यं सदाहञ्च तृष्णां प्रदरमेव च","text":"raktapittaṃ śītapittamamlapittamarocakam bahnimāndyaṃ sadāhañca tṛṣṇāṃ pradarameva ca"},{"type":"verse","number":"70","sanskrit":"रक्तार्शोऽपि तथा छर्दि पाण्डुरोगञ्च कामलाम् उपदंशं विसर्पञ्च जीर्णञ्च विषमं ज्वरम्","text":"raktārśo'pi tathā chardi pāṇḍurogañca kāmalām upadaṃśaṃ visarpañca jīrṇañca viṣamaṃ jvaram"},{"type":"verse","number":"71","sanskrit":"लेहोऽय परमो वृष्यो बृंहणो बलबर्द्धनः स्थापनीयः प्रयत्नेन भाजने मृण्मये नवे","text":"leho'ya paramo vṛṣyo bṛṃhaṇo balabarddhanaḥ sthāpanīyaḥ prayatnena bhājane mṛṇmaye nave"},{"type":"verse","number":"72","sanskrit":"कूष्माण्डकस्य स्वरसं पलानां शतमात्रया रसतुल्यं गवां क्षीरं धात्रीचूर्णं पलाष्टकम्","text":"kūṣmāṇḍakasya svarasaṃ palānāṃ śatamātrayā rasatulyaṃ gavāṃ kṣīraṃ dhātrīcūrṇaṃ palāṣṭakam"},{"type":"verse","number":"73","sanskrit":"मृद्वग्निना पचेत्तावद्यावद्भवति पिण्डवत् धात्रीतुल्या सिता योज्या पलार्द्धं लेहयेदनु","text":"mṛdvagninā pacettāvadyāvadbhavati piṇḍavat dhātrītulyā sitā yojyā palārddhaṃ lehayedanu"},{"type":"verse","number":"74","sanskrit":"खण्डकूष्माण्डकं ह्येतद् भुक्तमभ्यासतो हरेत् रक्तपित्तमम्लपित्तं दाहं तृष्णाञ्च कामलाम्","text":"khaṇḍakūṣmāṇḍakaṃ hyetad bhuktamabhyāsato haret raktapittamamlapittaṃ dāhaṃ tṛṣṇāñca kāmalām"},{"type":"verse","number":"75","sanskrit":"शतावरी छिन्नरुहा वृषो मुण्डतिका बला तालमूली च गायत्री त्रिफलायास्त्वचस्तथा","text":"śatāvarī chinnaruhā vṛṣo muṇḍatikā balā tālamūlī ca gāyatrī triphalāyāstvacastathā"},{"type":"verse","number":"76","sanskrit":"भार्गी पुष्करमूलञ्च पृथक्पञ्च पलानि च जलद्रो णे विपक्तव्यमष्टभागावशेषितम्","text":"bhārgī puṣkaramūlañca pṛthakpañca palāni ca jaladro ṇe vipaktavyamaṣṭabhāgāvaśeṣitam"},{"type":"verse","number":"77","sanskrit":"दिव्यौषधिहतस्यापि माक्षिकेण हतस्य वा पलद्वादशकं देयं रुक्मलौहस्य चूर्णितम्","text":"divyauṣadhihatasyāpi mākṣikeṇa hatasya vā paladvādaśakaṃ deyaṃ rukmalauhasya cūrṇitam"},{"type":"verse","number":"78","sanskrit":"खण्डतुल्यं घृतं देयं पलषोडशकं बुधैः पचेत्ताम्रमये पात्रे गुडपाको मतो यथा","text":"khaṇḍatulyaṃ ghṛtaṃ deyaṃ palaṣoḍaśakaṃ budhaiḥ pacettāmramaye pātre guḍapāko mato yathā"},{"type":"verse","number":"79","sanskrit":"प्रस्थार्धं मधुना देयं शुभाश्मजतुकस्य च शृङ्गी कृष्णा विडङ्गञ्च शुण्ठ्यजाजी पलं पलम्","text":"prasthārdhaṃ madhunā deyaṃ śubhāśmajatukasya ca śṛṅgī kṛṣṇā viḍaṅgañca śuṇṭhyajājī palaṃ palam"},{"type":"verse","number":"80","sanskrit":"त्रिफला धान्यकं पत्रं कणा मरिचकेशरम् चूर्णं दत्वा सुमथितं स्निग्धे भाण्डे निधापयेत्","text":"triphalā dhānyakaṃ patraṃ kaṇā maricakeśaram cūrṇaṃ datvā sumathitaṃ snigdhe bhāṇḍe nidhāpayet"},{"type":"verse","number":"81","sanskrit":"यथाकालं प्रयुञ्जीत बिडालपदमात्रकम् गव्यक्षीरानुपानञ्च सेव्यो मांसरसः पयः","text":"yathākālaṃ prayuñjīta biḍālapadamātrakam gavyakṣīrānupānañca sevyo māṃsarasaḥ payaḥ"},{"type":"verse","number":"82","sanskrit":"गुरुवृष्यान्नपानानि स्निग्धमांसादि बृंहणम् रक्तपित्तं क्षयं कासं पार्श्वशूलं विशेषतः","text":"guruvṛṣyānnapānāni snigdhamāṃsādi bṛṃhaṇam raktapittaṃ kṣayaṃ kāsaṃ pārśvaśūlaṃ viśeṣataḥ"},{"type":"verse","number":"83","sanskrit":"वातरक्तं प्रमेहञ्च शीतपित्तं वमिं क्लमम् श्वयथुं पाण्डुरोगञ्च कुष्ठं प्लीहोदरं तथा","text":"vātaraktaṃ pramehañca śītapittaṃ vamiṃ klamam śvayathuṃ pāṇḍurogañca kuṣṭhaṃ plīhodaraṃ tathā"},{"type":"verse","number":"84","sanskrit":"आनाहं मूत्रसंस्रावमम्लपित्तं निहन्ति च चक्षुष्यं बृंहणं वृष्यं मङ्गल्यं प्रीतिवर्द्धनम्","text":"ānāhaṃ mūtrasaṃsrāvamamlapittaṃ nihanti ca cakṣuṣyaṃ bṛṃhaṇaṃ vṛṣyaṃ maṅgalyaṃ prītivarddhanam"},{"type":"verse","number":"85","sanskrit":"आरोग्यं पुत्रदं श्रेष्ठं कामाग्निबलवर्द्धनम् श्रीकरंलाघवञ्चैव खण्डकाद्यं प्रकीर्त्तितम्","text":"ārogyaṃ putradaṃ śreṣṭhaṃ kāmāgnibalavarddhanam śrīkaraṃlāghavañcaiva khaṇḍakādyaṃ prakīrttitam"},{"type":"verse","number":"86","sanskrit":"छागं पारावतं मांसं तित्तिरिः क्रकरः शशः कुरङ्गः कृष्णसारश्च मांसमेषां प्रयोजयेत्","text":"chāgaṃ pārāvataṃ māṃsaṃ tittiriḥ krakaraḥ śaśaḥ kuraṅgaḥ kṛṣṇasāraśca māṃsameṣāṃ prayojayet"},{"type":"verse","number":"87","sanskrit":"नारिकेलपयः पानं सुनिषण्णकवास्तुकम् शुष्कमूलकजीवाख्यं पटोलं बृहतीफलम्","text":"nārikelapayaḥ pānaṃ suniṣaṇṇakavāstukam śuṣkamūlakajīvākhyaṃ paṭolaṃ bṛhatīphalam"},{"type":"verse","number":"88","sanskrit":"वार्ताकुं पक्वमाम्रञ्च खर्जूरं स्वादु दाडिमम् ककारपूर्वकं यच्च मांसञ्चानूपसम्भवम्","text":"vārtākuṃ pakvamāmrañca kharjūraṃ svādu dāḍimam kakārapūrvakaṃ yacca māṃsañcānūpasambhavam"},{"type":"verse","number":"89","sanskrit":"वर्जनीयं विशेषेण खण्डकाद्यं समश्नता लोहान्तरवदत्रापि पुटनादिक्रियेष्यते न पुनर्माक्षिकेणैव शिलयैव हि मारणम्","text":"varjanīyaṃ viśeṣeṇa khaṇḍakādyaṃ samaśnatā lohāntaravadatrāpi puṭanādikriyeṣyate na punarmākṣikeṇaiva śilayaiva hi māraṇam"},{"type":"verse","number":"90","sanskrit":"शतावरीमूलकल्कं कल्कात्क्षीरं चतुर्गुणम् क्षीरतुल्यं घृतं गव्यं सितया कल्कतुल्यया","text":"śatāvarīmūlakalkaṃ kalkātkṣīraṃ caturguṇam kṣīratulyaṃ ghṛtaṃ gavyaṃ sitayā kalkatulyayā"},{"type":"verse","number":"91","sanskrit":"घृतशेषं पचेत्तत्तु पलार्द्धं लेहयेत्सदा रक्तपित्तं ह्याम्लपित्तं क्षयं श्वासञ्च नाशयेत्","text":"ghṛtaśeṣaṃ pacettattu palārddhaṃ lehayetsadā raktapittaṃ hyāmlapittaṃ kṣayaṃ śvāsañca nāśayet"},{"type":"verse","number":"92","sanskrit":"इति नवमो रक्तपित्ताधिकारः समाप्तः ९","text":"iti navamo raktapittādhikāraḥ samāptaḥ 9"}]},{"sthana":"Уттаракханда","number":10,"lang":"sa","content":[{"type":"heading","heading":"Амлапитта — кислотность"},{"type":"verse","number":"1","sanskrit":"विरुद्धदुष्टाम्लविदाहिपित्तप्रकोपिपानान्नभुजो विदग्धम् पित्तं स्वहेतूपचितं पुरा यत्तदम्लपित्तं प्रवदन्ति सन्तः","text":"viruddhaduṣṭāmlavidāhipittaprakopipānānnabhujo vidagdham pittaṃ svahetūpacitaṃ purā yattadamlapittaṃ pravadanti santaḥ"},{"type":"verse","number":"2","sanskrit":"अविपाकः क्लमोत्क्लेशस्तिक्ताम्लोद्गारगौरवैः हृत्कण्ठदाहारुचिभिरम्लपिक्तं वदेद्भिषक् अम्लपित्तं द्विधा प्रोक्तमधोगं च तथोर्ध्वगम्","text":"avipākaḥ klamotkleśastiktāmlodgāragauravaiḥ hṛtkaṇṭhadāhārucibhiramlapiktaṃ vadedbhiṣak amlapittaṃ dvidhā proktamadhogaṃ ca tathordhvagam"},{"type":"verse","number":"3","sanskrit":"वातं हरित्पीतकनीलकृष्णमारक्तरक्ताभमतीव चाच्छम् मत्स्योदकाभं त्वतिपिच्छिलाभं श्लेष्मानुजातं सहितं रसेन","text":"vātaṃ haritpītakanīlakṛṣṇamāraktaraktābhamatīva cāccham matsyodakābhaṃ tvatipicchilābhaṃ śleṣmānujātaṃ sahitaṃ rasena"},{"type":"verse","number":"4","sanskrit":"तृड्दाहमूर्च्छाभ्रममोहकारि प्रयात्यधो वा विविधप्रकारम् हृल्लासकोठानलसादहर्षस्वेदाङ्गपीतत्वकरं कदाचित्","text":"tṛḍdāhamūrcchābhramamohakāri prayātyadho vā vividhaprakāram hṛllāsakoṭhānalasādaharṣasvedāṅgapītatvakaraṃ kadācit"},{"type":"verse","number":"5","sanskrit":"भुक्ते विदग्धेऽप्यथ वाऽप्यभुक्ते करोति तिक्ताम्लवमिं कदाचित् उद्गारमेवंविधमेव कण्ठहृत्कुक्षिदाहं शिरसो रुजञ्च","text":"bhukte vidagdhe'pyatha vā'pyabhukte karoti tiktāmlavamiṃ kadācit udgāramevaṃvidhameva kaṇṭhahṛtkukṣidāhaṃ śiraso rujañca"},{"type":"verse","number":"6","sanskrit":"करचरणदाहमौष्ण्यं महतीमरुचिं ज्वरं च कफपित्तम् जनयति कण्डूमण्डलपिडकाशतनिचितरोगचयम्","text":"karacaraṇadāhamauṣṇyaṃ mahatīmaruciṃ jvaraṃ ca kaphapittam janayati kaṇḍūmaṇḍalapiḍakāśatanicitarogacayam"},{"type":"verse","number":"7","sanskrit":"सानिलं सानिलकफं सकफं तच्च लक्षयेत् दोषलिङ्गेन मतिमान् भिषङ्मोहकरं हि तत्","text":"sānilaṃ sānilakaphaṃ sakaphaṃ tacca lakṣayet doṣaliṅgena matimān bhiṣaṅmohakaraṃ hi tat"},{"type":"verse","number":"8","sanskrit":"कम्पप्रलापमूर्च्छाश्चिमिचिमिगात्रावसादशूलानि तमसो दर्शनविभ्रमप्रमोहहर्षास्तथाऽनिलयुतेन","text":"kampapralāpamūrcchāścimicimigātrāvasādaśūlāni tamaso darśanavibhramapramohaharṣāstathā'nilayutena"},{"type":"verse","number":"9","sanskrit":"कफनिष्ठीवनगौरवजडताऽरुचिशीतसादवमिलेपाः दहनबलहानिकण्डूनिद्रा श्चिह्नं कफानुगे भवति उभयमिदमेव चिह्नं मारुतकफसम्भवेऽम्लपित्ते स्यात्","text":"kaphaniṣṭhīvanagauravajaḍatā'ruciśītasādavamilepāḥ dahanabalahānikaṇḍūnidrā ścihnaṃ kaphānuge bhavati ubhayamidameva cihnaṃ mārutakaphasambhave'mlapitte syāt"},{"type":"verse","number":"10","sanskrit":"रोगोऽयमम्लपित्ताख्यो यत्नात्संसाध्यते नवः चिरोत्थितो भवेद्याप्यः कृच्छ्रसाध्यः स कस्यचित्","text":"rogo'yamamlapittākhyo yatnātsaṃsādhyate navaḥ cirotthito bhavedyāpyaḥ kṛcchrasādhyaḥ sa kasyacit"},{"type":"verse","number":"11","sanskrit":"तिक्ताम्लकटुकोद्गारहृत्कुक्षिकण्ठदाहकृत् तमो मूर्च्छाऽरुचिश्छर्दिरालस्यं च शिरोरुजा प्रसेको मुखमाधुर्यं श्लेष्मपित्तस्य लक्षणम्","text":"tiktāmlakaṭukodgārahṛtkukṣikaṇṭhadāhakṛt tamo mūrcchā'ruciśchardirālasyaṃ ca śirorujā praseko mukhamādhuryaṃ śleṣmapittasya lakṣaṇam"},{"type":"verse","number":"12","sanskrit":"अम्लपित्ते तु वमनं पटोलारिष्टवासकैः कारयेन्मदनैः क्षौद्रैः सैन्धवैश्च तथा भिषक्","text":"amlapitte tu vamanaṃ paṭolāriṣṭavāsakaiḥ kārayenmadanaiḥ kṣaudraiḥ saindhavaiśca tathā bhiṣak"},{"type":"verse","number":"13","sanskrit":"विरेचनं त्रिवृच्चूर्णं मधुधात्रीफलद्र वैः ऊर्ध्वगं वमनैर्विद्वानधोगं रेचनैर्हरेत्","text":"virecanaṃ trivṛccūrṇaṃ madhudhātrīphaladra vaiḥ ūrdhvagaṃ vamanairvidvānadhogaṃ recanairharet"},{"type":"verse","number":"14","sanskrit":"यवगोधूमविकृतीस्तीक्ष्ण संस्कारवर्जिताः यथास्वं लाजसक्तून्वा सितामधुयुतान्पिबेत्","text":"yavagodhūmavikṛtīstīkṣṇa saṃskāravarjitāḥ yathāsvaṃ lājasaktūnvā sitāmadhuyutānpibet"},{"type":"verse","number":"15","sanskrit":"निस्तुषयववृषधात्रीक्वथितं सलिलं त्रिगन्धमधुयुक्तम् द्रुततरमपहरति वमिं सञ्जनितामम्लपित्तेन","text":"nistuṣayavavṛṣadhātrīkvathitaṃ salilaṃ trigandhamadhuyuktam drutataramapaharati vamiṃ sañjanitāmamlapittena"},{"type":"verse","number":"16","sanskrit":"छिन्नोद्भवानिम्बपटोलपत्रं क्षौद्रा न्वितं पीतमनेकरूपम् सुदारुणं हन्ति तदम्लपित्तं यथाऽशनिस्तालतरुं प्रवृद्धम्","text":"chinnodbhavānimbapaṭolapatraṃ kṣaudrā nvitaṃ pītamanekarūpam sudāruṇaṃ hanti tadamlapittaṃ yathā'śanistālataruṃ pravṛddham"},{"type":"verse","number":"17","sanskrit":"वासाऽमृतापर्पटक निम्बभूनिम्बमार्कवैः ऐत्रिफलाकुलकैः क्वाथः सक्षौद्र श्चाम्लपित्तहा","text":"vāsā'mṛtāparpaṭaka nimbabhūnimbamārkavaiḥ aitriphalākulakaiḥ kvāthaḥ sakṣaudra ścāmlapittahā"},{"type":"verse","number":"18","sanskrit":"पाठापटोलयवचन्दनधान्य धात्रीवासावराङ्गदल नागकणऽभयाभिः लेहःसिताऽज्यमधुभिःशिवपाल पिण्डीहन्त्यम्ल पित्तमरुचिज्वरदाहशोषान्","text":"pāṭhāpaṭolayavacandanadhānya dhātrīvāsāvarāṅgadala nāgakaṇa'bhayābhiḥ lehaḥsitā'jyamadhubhiḥśivapāla piṇḍīhantyamla pittamarucijvaradāhaśoṣān"},{"type":"verse","number":"19","sanskrit":"हन्त्यम्लपित्तवमनारुचिदाहमोहखालित्यमेहशिशिरव्रणशुक्रदोषान् भुक्त्वा नरः सततमामलकीरसेन वृद्धोऽप्यनेन हि भवेत्तरुणो रिरंसुः","text":"hantyamlapittavamanārucidāhamohakhālityamehaśiśiravraṇaśukradoṣān bhuktvā naraḥ satatamāmalakīrasena vṛddho'pyanena hi bhavettaruṇo riraṃsuḥ"},{"type":"verse","number":"20","sanskrit":"कूष्माण्डकरसो ग्राह्यः पलानां शतमात्रकम् रसतुल्यं गवां क्षीरं धात्रीचूर्णंपलाष्टकम्","text":"kūṣmāṇḍakaraso grāhyaḥ palānāṃ śatamātrakam rasatulyaṃ gavāṃ kṣīraṃ dhātrīcūrṇaṃpalāṣṭakam"},{"type":"verse","number":"21","sanskrit":"धात्रीतुल्यासिता योज्या गव्यमाज्यं पलद्वयम् मन्दाग्निना पचेत्सर्वं यावद्भवति पिण्डितम्","text":"dhātrītulyāsitā yojyā gavyamājyaṃ paladvayam mandāgninā pacetsarvaṃ yāvadbhavati piṇḍitam"},{"type":"verse","number":"22","sanskrit":"पलार्द्धं पलमेकं वा प्रत्यहं भक्षयेदिदम् खण्डकूष्माण्डकं ख्यातमम्लपित्तापहं परम्","text":"palārddhaṃ palamekaṃ vā pratyahaṃ bhakṣayedidam khaṇḍakūṣmāṇḍakaṃ khyātamamlapittāpahaṃ param"},{"type":"verse","number":"23","sanskrit":"कुडवं नारिकेलस्य जले मृद्वग्निना पचेत् नारिकेलजलालाभे गव्ये पयसि तत्पचेत्","text":"kuḍavaṃ nārikelasya jale mṛdvagninā pacet nārikelajalālābhe gavye payasi tatpacet"},{"type":"verse","number":"24","sanskrit":"धान्यकं पिप्पली मुस्तं चातुर्जातं विचूर्णितम् प्रत्येकं टङ्कमात्रं तु शीते तस्मिन्विनिक्षिपेत्","text":"dhānyakaṃ pippalī mustaṃ cāturjātaṃ vicūrṇitam pratyekaṃ ṭaṅkamātraṃ tu śīte tasminvinikṣipet"},{"type":"verse","number":"25","sanskrit":"पलमात्रस्तदर्द्धोऽपि भक्षितः प्रत्यहं नरैः नारिकेलस्य खण्डोऽय पुंस्त्वनिद्रा बलप्रदः","text":"palamātrastadarddho'pi bhakṣitaḥ pratyahaṃ naraiḥ nārikelasya khaṇḍo'ya puṃstvanidrā balapradaḥ"},{"type":"verse","number":"26","sanskrit":"अम्लपित्तं रक्तपित्तं शूलञ्च परिणामजम् क्षयं क्षययति क्षिप्रं शुष्कं दार्वनलो यथा","text":"amlapittaṃ raktapittaṃ śūlañca pariṇāmajam kṣayaṃ kṣayayati kṣipraṃ śuṣkaṃ dārvanalo yathā"},{"type":"verse","number":"27","sanskrit":"प्रस्थन्तु नारिकेलस्य सूक्ष्मं दृषदि पेषितम् निष्कुलीकृतकूष्माण्डखण्डानामर्द्धमाढकम्","text":"prasthantu nārikelasya sūkṣmaṃ dṛṣadi peṣitam niṣkulīkṛtakūṣmāṇḍakhaṇḍānāmarddhamāḍhakam"},{"type":"verse","number":"28","sanskrit":"तद्द्वयं भक्षयेद्ग्रव्ये घृते तु कुडवोन्मिते ततस्तत्र क्षिपेच्छुद्धं गोदुग्धञ्चाढकोन्मितम्","text":"taddvayaṃ bhakṣayedgravye ghṛte tu kuḍavonmite tatastatra kṣipecchuddhaṃ godugdhañcāḍhakonmitam"},{"type":"verse","number":"29","sanskrit":"तत्रैव निक्षिपेद्भव्यां सितां प्रस्थद्वयोन्मिताम् पचेत्सर्वाणि चैकत्र मृदुना वह्निना भिषक्","text":"tatraiva nikṣipedbhavyāṃ sitāṃ prasthadvayonmitām pacetsarvāṇi caikatra mṛdunā vahninā bhiṣak"},{"type":"verse","number":"30","sanskrit":"सुपक्के शीतले तत्र चूर्णीकृत्य विनिक्षिपेत् सूक्ष्मैलां धान्यकं धात्रीं पर्पटं जलदं जलम्","text":"supakke śītale tatra cūrṇīkṛtya vinikṣipet sūkṣmailāṃ dhānyakaṃ dhātrīṃ parpaṭaṃ jaladaṃ jalam"},{"type":"verse","number":"31","sanskrit":"उशीरं चन्दनं द्रा क्षां शृङ्गाटञ्च कशेरुकम् त्वक्पत्रकं सकर्पूरं कर्षयुग्मं पृथक्पृथक्","text":"uśīraṃ candanaṃ drā kṣāṃ śṛṅgāṭañca kaśerukam tvakpatrakaṃ sakarpūraṃ karṣayugmaṃ pṛthakpṛthak"},{"type":"verse","number":"32","sanskrit":"सर्वं संमिश्रयेद्र क्षेद्भाजने मृण्मये नवे पलमात्रमिदं प्रातर्भक्षयेद्वा यथाऽनलम्","text":"sarvaṃ saṃmiśrayedra kṣedbhājane mṛṇmaye nave palamātramidaṃ prātarbhakṣayedvā yathā'nalam"},{"type":"verse","number":"33","sanskrit":"एतन्निषेवितं हन्ति रोगानेतान्न संशयः अम्लपित्तं ज्वरं पित्तं रक्त पित्तमरोचकम्","text":"etanniṣevitaṃ hanti rogānetānna saṃśayaḥ amlapittaṃ jvaraṃ pittaṃ rakta pittamarocakam"},{"type":"verse","number":"34","sanskrit":"वातरक्तं तृषां दाहं पाण्डुरोगञ्च कामलाम् क्षयं क्षपयति क्षिप्रं शूलञ्च परिणामजम्","text":"vātaraktaṃ tṛṣāṃ dāhaṃ pāṇḍurogañca kāmalām kṣayaṃ kṣapayati kṣipraṃ śūlañca pariṇāmajam"},{"type":"verse","number":"35","sanskrit":"नारिकेलस्य खण्डोऽयमश्विभ्यां भाषितः पुरा वर्णदो बृहंणो वृष्यः पुंस्त्वनिद्रा बलप्रदः","text":"nārikelasya khaṇḍo'yamaśvibhyāṃ bhāṣitaḥ purā varṇado bṛhaṃṇo vṛṣyaḥ puṃstvanidrā balapradaḥ"},{"type":"verse","number":"36","sanskrit":"अभया पिप्पली द्रा क्षा सितधान्यकवासकम् मधुना कण्ठदाहघ्नं पित्तश्लेष्महरं परम्","text":"abhayā pippalī drā kṣā sitadhānyakavāsakam madhunā kaṇṭhadāhaghnaṃ pittaśleṣmaharaṃ param"},{"type":"verse","number":"37","sanskrit":"पटोलयवधान्याकपिप्पल्यामलकानि च तेषां क्षौद्र्रयुतः क्वाथः पित्तश्लेष्महरः परः","text":"paṭolayavadhānyākapippalyāmalakāni ca teṣāṃ kṣaudrrayutaḥ kvāthaḥ pittaśleṣmaharaḥ paraḥ"},{"type":"verse","number":"38","sanskrit":"पित्तश्लेष्मवमीकण्डूकोठविस्फोटदाहनुत् दीपनः पाचनः क्वाथः शृङ्गवेरपटोलयोः","text":"pittaśleṣmavamīkaṇḍūkoṭhavisphoṭadāhanut dīpanaḥ pācanaḥ kvāthaḥ śṛṅgaverapaṭolayoḥ"},{"type":"verse","number":"39","sanskrit":"पिप्पलीखण्डपथ्याभिस्तुल्याभिर्मोदकः कृतः पित्तश्लेष्म हरो भुक्तो वह्निमान्द्यं च नाशयेत्","text":"pippalīkhaṇḍapathyābhistulyābhirmodakaḥ kṛtaḥ pittaśleṣma haro bhukto vahnimāndyaṃ ca nāśayet"},{"type":"verse","number":"40","sanskrit":"इति दशमोऽम्ल पित्तश्लेष्मपित्ताधिकारः समाप्तः १०","text":"iti daśamo'mla pittaśleṣmapittādhikāraḥ samāptaḥ 10"}]},{"sthana":"Уттаракханда","number":11,"lang":"sa","content":[{"type":"heading","heading":"Раджаякшма — чахотка (туберкулёз)"},{"type":"verse","number":"1","sanskrit":"वेगरोधात्क्षयाच्चैव साहसाद्विषमाशनात् त्रिदोषो जायते यक्ष्मा गदो हेतुचतुष्टयात्","text":"vegarodhātkṣayāccaiva sāhasādviṣamāśanāt tridoṣo jāyate yakṣmā gado hetucatuṣṭayāt"},{"type":"verse","number":"2","sanskrit":"वैद्यो व्याधिमता यस्माद् व्याधेर्यत्नेन यक्ष्यते स यक्ष्मा प्रोच्यते लोके शब्दशास्त्रविशारदैः","text":"vaidyo vyādhimatā yasmād vyādheryatnena yakṣyate sa yakṣmā procyate loke śabdaśāstraviśāradaiḥ"},{"type":"verse","number":"3","sanskrit":"राज्ञश्चन्द्र्रमसो यस्मादभूदेष किलामयः तस्मात्तं राजयक्ष्मेति प्रवदन्ति मनीषिणः","text":"rājñaścandrramaso yasmādabhūdeṣa kilāmayaḥ tasmāttaṃ rājayakṣmeti pravadanti manīṣiṇaḥ"},{"type":"verse","number":"4","sanskrit":"क्रियाक्षयकरत्वात्तु क्षय इत्युच्यते बुधैः संशोषणाद्र सादीनां शोष इत्यभिधीयते","text":"kriyākṣayakaratvāttu kṣaya ityucyate budhaiḥ saṃśoṣaṇādra sādīnāṃ śoṣa ityabhidhīyate"},{"type":"verse","number":"5","sanskrit":"कफप्रधानैर्दोषैस्तु रुद्धेषु रसवर्त्मसु अतिव्यवायिनो वाऽपि क्षीणे रेतस्यनन्तराः क्षीयन्ते धातवः सर्वे ततः शुष्यति मानवः","text":"kaphapradhānairdoṣaistu ruddheṣu rasavartmasu ativyavāyino vā'pi kṣīṇe retasyanantarāḥ kṣīyante dhātavaḥ sarve tataḥ śuṣyati mānavaḥ"},{"type":"verse","number":"6","sanskrit":"श्वासाङ्गसादकफसंस्रवतालुशोषवम्यग्निसादमदपीनसकासनिद्राः शोषे भविष्यति भवन्ति स चापि जन्तुः शुक्लेक्षणो भवति मांसपरो रिरंसुः","text":"śvāsāṅgasādakaphasaṃsravatāluśoṣavamyagnisādamadapīnasakāsanidrāḥ śoṣe bhaviṣyati bhavanti sa cāpi jantuḥ śuklekṣaṇo bhavati māṃsaparo riraṃsuḥ"},{"type":"verse","number":"7","sanskrit":"स्वप्नेषु काकशुकशल्लकिनीलकण्ठगृध्रास्तथैव कपयः कृकलासकाश्च तं वाहयन्ति स नदीर्विजलाश्च पश्येच्छुष्कांस्तरून्पवनधूमदवार्दितांश्च","text":"svapneṣu kākaśukaśallakinīlakaṇṭhagṛdhrāstathaiva kapayaḥ kṛkalāsakāśca taṃ vāhayanti sa nadīrvijalāśca paśyecchuṣkāṃstarūnpavanadhūmadavārditāṃśca"},{"type":"verse","number":"8","sanskrit":"अंसपार्श्वाभितापश्च सन्तापः करपादयोः ज्वरः सर्वाङ्गिकश्चेति लक्षणं राजयक्ष्मणः","text":"aṃsapārśvābhitāpaśca santāpaḥ karapādayoḥ jvaraḥ sarvāṅgikaśceti lakṣaṇaṃ rājayakṣmaṇaḥ"},{"type":"verse","number":"9","sanskrit":"भक्तद्वेषो ज्वरः श्वासः कासः शोणितदर्शनम् स्वरभेदश्च जायन्ते षड्रूपे राजयक्ष्मणि","text":"bhaktadveṣo jvaraḥ śvāsaḥ kāsaḥ śoṇitadarśanam svarabhedaśca jāyante ṣaḍrūpe rājayakṣmaṇi"},{"type":"verse","number":"10","sanskrit":"स्वरभेदोऽनिलाच्छूलं सङ्कोचश्चांसपार्श्वयोः ज्वरो दाहोऽतिसारश्च पिक्ताद्र क्तस्य चागमः","text":"svarabhedo'nilācchūlaṃ saṅkocaścāṃsapārśvayoḥ jvaro dāho'tisāraśca piktādra ktasya cāgamaḥ"},{"type":"verse","number":"11","sanskrit":"शिरसः परिपूर्णत्वमभक्तच्छन्द एव च कासः कण्ठस्य च ध्वंसो विज्ञेयः कफकोपतः","text":"śirasaḥ paripūrṇatvamabhaktacchanda eva ca kāsaḥ kaṇṭhasya ca dhvaṃso vijñeyaḥ kaphakopataḥ"},{"type":"verse","number":"12","sanskrit":"एकादशभिरेभिर्वा षड्भिर्वाऽपि समन्वितम्","text":"ekādaśabhirebhirvā ṣaḍbhirvā'pi samanvitam"},{"type":"verse","number":"13","sanskrit":"त्रिभिर्वा पीडितं लिङ्गैर्ज्वरकासासृगामयैः जह्याच्छोषार्दितं जन्तुमिच्छन्सुविमलं यशः","text":"tribhirvā pīḍitaṃ liṅgairjvarakāsāsṛgāmayaiḥ jahyācchoṣārditaṃ jantumicchansuvimalaṃ yaśaḥ"},{"type":"verse","number":"14","sanskrit":"सर्वैरर्द्धैस्त्रिभिर्वाऽपि लिङ्गैर्मांसबलक्षये युक्तो वर्ज्यश्चिकित्स्यस्तु सर्वरूपोऽप्यतोऽन्यथा","text":"sarvairarddhaistribhirvā'pi liṅgairmāṃsabalakṣaye yukto varjyaścikitsyastu sarvarūpo'pyato'nyathā"},{"type":"verse","number":"15","sanskrit":"महाशनं क्षीयमाणमतीसारनिपीडितम् शूनमुष्कोदरञ्चैव यक्ष्मिणं परिवर्जयेत्","text":"mahāśanaṃ kṣīyamāṇamatīsāranipīḍitam śūnamuṣkodarañcaiva yakṣmiṇaṃ parivarjayet"},{"type":"verse","number":"16","sanskrit":"शुक्लाक्षमन्नद्वेष्टारमूर्ध्वश्वासनिपीडितम् कृच्छ्रेण बहु मेहन्तं यक्ष्मा हन्तीह मानवम्","text":"śuklākṣamannadveṣṭāramūrdhvaśvāsanipīḍitam kṛcchreṇa bahu mehantaṃ yakṣmā hantīha mānavam"},{"type":"verse","number":"17","sanskrit":"परं दिनसहस्रन्तु यदि जीवति मानवः सुभिषग्भिरुपक्रान्तस्तरुणः शोषपीडितः","text":"paraṃ dinasahasrantu yadi jīvati mānavaḥ subhiṣagbhirupakrāntastaruṇaḥ śoṣapīḍitaḥ"},{"type":"verse","number":"18","sanskrit":"ज्वरानुबन्धरहितं बलवन्तं क्रियासहम् उपक्रमेदात्मवन्तं दीप्ताग्निमकृशं नरम्","text":"jvarānubandharahitaṃ balavantaṃ kriyāsaham upakramedātmavantaṃ dīptāgnimakṛśaṃ naram"},{"type":"verse","number":"19","sanskrit":"व्यवायशोकवार्द्धक्यव्यायामाध्वप्रशोषितान् व्रणोरःक्षतसंज्ञौ च शोषिणौ लक्षणैः शृणु","text":"vyavāyaśokavārddhakyavyāyāmādhvapraśoṣitān vraṇoraḥkṣatasaṃjñau ca śoṣiṇau lakṣaṇaiḥ śṛṇu"},{"type":"verse","number":"20","sanskrit":"व्यवायशोषी शुक्रस्य क्षयलिङ्गैरुपद्रुतः पाण्डुदेहो यथापूर्वं क्षीयन्ते चास्य धातवः","text":"vyavāyaśoṣī śukrasya kṣayaliṅgairupadrutaḥ pāṇḍudeho yathāpūrvaṃ kṣīyante cāsya dhātavaḥ"},{"type":"verse","number":"21","sanskrit":"प्रध्यानशीलः स्रस्ताङ्गः शोकशोष्यपि तादृशः बिना शुक्रक्षयकृतैर्विकारैरुपलक्षितः","text":"pradhyānaśīlaḥ srastāṅgaḥ śokaśoṣyapi tādṛśaḥ binā śukrakṣayakṛtairvikārairupalakṣitaḥ"},{"type":"verse","number":"22","sanskrit":"जराशोषी कृशो मन्दवीर्यबुद्धिबलेन्द्रि यः कम्पनोऽरुमान्भिन्नकांस्यपात्रहतस्वरः","text":"jarāśoṣī kṛśo mandavīryabuddhibalendri yaḥ kampano'rumānbhinnakāṃsyapātrahatasvaraḥ"},{"type":"verse","number":"23","sanskrit":"ष्ठीवति श्लेष्मणा हीनं गौरवारुचिपीडितः सम्प्रस्रुतास्यनासाक्षः शुष्करुक्षमलच्छविः","text":"ṣṭhīvati śleṣmaṇā hīnaṃ gauravārucipīḍitaḥ samprasrutāsyanāsākṣaḥ śuṣkarukṣamalacchaviḥ"},{"type":"verse","number":"24","sanskrit":"अध्वप्रशोषी स्रस्ताङ्ग सम्भृष्टपरुषच्छविः प्रसुप्तगात्रावयवः शुष्कक्लोमगलाननः","text":"adhvapraśoṣī srastāṅga sambhṛṣṭaparuṣacchaviḥ prasuptagātrāvayavaḥ śuṣkaklomagalānanaḥ"},{"type":"verse","number":"25","sanskrit":"व्यायामशोषी भूयिष्ठमेभिरेव समन्वितः लिङ्गैरुरःक्षतकृतैः संयुक्तश्च क्षतं विना","text":"vyāyāmaśoṣī bhūyiṣṭhamebhireva samanvitaḥ liṅgairuraḥkṣatakṛtaiḥ saṃyuktaśca kṣataṃ vinā"},{"type":"verse","number":"26","sanskrit":"रक्तक्षयाद्वेदनाभिस्तथैवाहारयन्त्रणात् व्रणितस्य भवेच्छोषः स चासाध्यतमः स्मृतः","text":"raktakṣayādvedanābhistathaivāhārayantraṇāt vraṇitasya bhavecchoṣaḥ sa cāsādhyatamaḥ smṛtaḥ"},{"type":"verse","number":"27","sanskrit":"धनुषाऽयस्यतोऽत्थ भारमुद्वहतो गुरुम् युद्ध्य्मानस्य बलिभिः पततो विषमोच्चतः","text":"dhanuṣā'yasyato'ttha bhāramudvahato gurum yuddhymānasya balibhiḥ patato viṣamoccataḥ"},{"type":"verse","number":"28","sanskrit":"वृषं हयं वा धावन्तं दम्यं चान्यं निगृह्णत शिलाकाष्ठाश्मनिर्घातान् क्षिपतोनिघ्नतः परान्","text":"vṛṣaṃ hayaṃ vā dhāvantaṃ damyaṃ cānyaṃ nigṛhṇata śilākāṣṭhāśmanirghātān kṣipatonighnataḥ parān"},{"type":"verse","number":"29","sanskrit":"अधीयानस्य चात्युच्चैर्दूरं वा व्रजतो द्रुतम् महानदीं वा तरतो हयैर्वा सह धावतः","text":"adhīyānasya cātyuccairdūraṃ vā vrajato drutam mahānadīṃ vā tarato hayairvā saha dhāvataḥ"},{"type":"verse","number":"30","sanskrit":"सहसोत्पततो दूरं तूर्णञ्चापि प्रनृत्यतः तथाऽन्यै कर्मभिः क्रूरैर्भृशमभ्याहतस्य वा","text":"sahasotpatato dūraṃ tūrṇañcāpi pranṛtyataḥ tathā'nyai karmabhiḥ krūrairbhṛśamabhyāhatasya vā"},{"type":"verse","number":"31","sanskrit":"स्त्रीषु चातिप्रसक्तस्य रुक्षाल्पप्रमिताशिनः विक्षतेवक्षसि व्याधिर्बलवान् समुदीर्यते","text":"strīṣu cātiprasaktasya rukṣālpapramitāśinaḥ vikṣatevakṣasi vyādhirbalavān samudīryate"},{"type":"verse","number":"32","sanskrit":"उरो विरुज्यतेऽत्यर्थं भिद्यतेऽथ विभज्यते प्रपीड्यते तथा पार्श्वे शुष्यत्यङ्गं प्रवेपते","text":"uro virujyate'tyarthaṃ bhidyate'tha vibhajyate prapīḍyate tathā pārśve śuṣyatyaṅgaṃ pravepate"},{"type":"verse","number":"33","sanskrit":"क्रमाद्वीर्यं बलं वर्णो रुचिरग्निश्च हीयते ज्वरो व्यथा मनोदैन्यं विड्भेदोऽग्निवधस्तथा","text":"kramādvīryaṃ balaṃ varṇo ruciragniśca hīyate jvaro vyathā manodainyaṃ viḍbhedo'gnivadhastathā"},{"type":"verse","number":"34","sanskrit":"दुष्टश्यावः सुदुर्गन्धः पीतो विग्रथितो बहुः कासमानस्य चाभीक्ष्णं कफः सासृक् प्रवर्त्तते स क्षती क्षीयतेऽत्यर्थं तथा शुक्रौजसोः क्षयात्","text":"duṣṭaśyāvaḥ sudurgandhaḥ pīto vigrathito bahuḥ kāsamānasya cābhīkṣṇaṃ kaphaḥ sāsṛk pravarttate sa kṣatī kṣīyate'tyarthaṃ tathā śukraujasoḥ kṣayāt"},{"type":"verse","number":"35","sanskrit":"उरोरुक्शोणितच्छर्दिःकासो वैशेषिकः क्षते क्षीणे सरक्तमूत्रत्वं पार्श्वपृष्ठकटीग्रहः","text":"urorukśoṇitacchardiḥkāso vaiśeṣikaḥ kṣate kṣīṇe saraktamūtratvaṃ pārśvapṛṣṭhakaṭīgrahaḥ"},{"type":"verse","number":"36","sanskrit":"व्रणरोधात्क्षयाच्चैव कोष्ठात्प्रतिमलात्तथा क्षतोरस्कस्यान्नपाके निःश्वासो वाति पूतिकः","text":"vraṇarodhātkṣayāccaiva koṣṭhātpratimalāttathā kṣatoraskasyānnapāke niḥśvāso vāti pūtikaḥ"},{"type":"verse","number":"37","sanskrit":"अल्पलिङ्गस्य दीप्ताग्नेःसाध्यो बलवतो नवः परिसंवत्सरो याप्यःसर्वलिङ्गं तु वर्जयेत्","text":"alpaliṅgasya dīptāgneḥsādhyo balavato navaḥ parisaṃvatsaro yāpyaḥsarvaliṅgaṃ tu varjayet"},{"type":"verse","number":"38","sanskrit":"बलिनो बहुदोषस्य पञ्च कर्माणि कारयेत् यक्ष्मिणःक्षीणदेहस्य तत्कृतं स्याद्विषोपमम्","text":"balino bahudoṣasya pañca karmāṇi kārayet yakṣmiṇaḥkṣīṇadehasya tatkṛtaṃ syādviṣopamam"},{"type":"verse","number":"39","sanskrit":"मलायत्तं बलं पुंसां शुक्रायत्तञ्च जीवितम् ततस्माद्यत्नेनसंरक्षेद्यक्ष्मिणो मलरेतसी","text":"malāyattaṃ balaṃ puṃsāṃ śukrāyattañca jīvitam tatasmādyatnenasaṃrakṣedyakṣmiṇo malaretasī"},{"type":"verse","number":"40","sanskrit":"शालिषष्टिकगोधूमयवमुद्गादयो हिताः मद्यानि जाङ्गलाः पक्षिमृगाःपथ्या विशुष्यताम्","text":"śāliṣaṣṭikagodhūmayavamudgādayo hitāḥ madyāni jāṅgalāḥ pakṣimṛgāḥpathyā viśuṣyatām"},{"type":"verse","number":"41","sanskrit":"सपिप्पलीकं सयवं सकुलत्थं सनागरम्","text":"sapippalīkaṃ sayavaṃ sakulatthaṃ sanāgaram"},{"type":"verse","number":"42","sanskrit":"दाडिमामलकोपेतं स्निग्धमाजं रसं पिबेत् तेन षड् विनिवर्त्तन्ते विकाराः पीनसादयः","text":"dāḍimāmalakopetaṃ snigdhamājaṃ rasaṃ pibet tena ṣaḍ vinivarttante vikārāḥ pīnasādayaḥ"},{"type":"verse","number":"43","sanskrit":"द्र्रव्यतो द्विगुणं मांसं सर्वतोऽष्टगुणं जलम् पादस्थं संस्कृतञ्चाज्ये षडङ्गो यूष उच्यते","text":"drravyato dviguṇaṃ māṃsaṃ sarvato'ṣṭaguṇaṃ jalam pādasthaṃ saṃskṛtañcājye ṣaḍaṅgo yūṣa ucyate"},{"type":"verse","number":"44","sanskrit":"ककुभत्वङ्नागबला वानरिबीजं विचूर्णितम्पयसा पीतं मधुघृतयुक्तंससितं यक्ष्मादिकासहरम्","text":"kakubhatvaṅnāgabalā vānaribījaṃ vicūrṇitampayasā pītaṃ madhughṛtayuktaṃsasitaṃ yakṣmādikāsaharam"},{"type":"verse","number":"45","sanskrit":"छागमांसं पयश्छागं छागं सर्पिः सनागरम् छागोपसेवी शयनं छागमध्ये तु यक्ष्मनुत्","text":"chāgamāṃsaṃ payaśchāgaṃ chāgaṃ sarpiḥ sanāgaram chāgopasevī śayanaṃ chāgamadhye tu yakṣmanut"},{"type":"verse","number":"46","sanskrit":"मधुताप्यविडङ्गाश्मजतुलोहघृताभयाः घ्नन्ति यक्ष्माणमत्युग्रं सेव्यमाना हिताशिनः","text":"madhutāpyaviḍaṅgāśmajatulohaghṛtābhayāḥ ghnanti yakṣmāṇamatyugraṃ sevyamānā hitāśinaḥ"},{"type":"verse","number":"47","sanskrit":"शर्करामधुसंयुक्तं नवनीतं लिहन्क्षयी क्षीराशी लभते पुष्टिमतुल्ये चाज्यमाक्षिके","text":"śarkarāmadhusaṃyuktaṃ navanītaṃ lihankṣayī kṣīrāśī labhate puṣṭimatulye cājyamākṣike"},{"type":"verse","number":"48","sanskrit":"सितोपलां तुगाक्षीरी पिप्पली बहुला त्वचः अन्त्यादूर्ध्वं द्विगुणिताश्चूर्णिता मधुसर्पिषा","text":"sitopalāṃ tugākṣīrī pippalī bahulā tvacaḥ antyādūrdhvaṃ dviguṇitāścūrṇitā madhusarpiṣā"},{"type":"verse","number":"49","sanskrit":"लेहयेद्रा जरोगार्त्तं कासश्वासज्वरातुरम् पार्श्वशूलिनमल्पाग्निं सुप्तजिह्वं रुचिच्युतम् हस्तपादाङ्गदाहे च ज्वरे रक्ते तथोर्ध्वगे","text":"lehayedrā jarogārttaṃ kāsaśvāsajvarāturam pārśvaśūlinamalpāgniṃ suptajihvaṃ rucicyutam hastapādāṅgadāhe ca jvare rakte tathordhvage"},{"type":"verse","number":"50","sanskrit":"जातीफलं विडङ्गानि चित्रकं तगरं तिलाः तालीसं चन्दनं शुण्ठी लवङ्गमुपकुञ्चिका","text":"jātīphalaṃ viḍaṅgāni citrakaṃ tagaraṃ tilāḥ tālīsaṃ candanaṃ śuṇṭhī lavaṅgamupakuñcikā"},{"type":"verse","number":"51","sanskrit":"कर्पूरश्चाभया धात्री मरिचं पिप्पली तुगा एषां त्वक्षसमा भागाश्चातुर्जातकसंयुताः","text":"karpūraścābhayā dhātrī maricaṃ pippalī tugā eṣāṃ tvakṣasamā bhāgāścāturjātakasaṃyutāḥ"},{"type":"verse","number":"52","sanskrit":"पलानि सप्त भङ्गायाः सितासर्वसमा मता चूर्णमेतत्क्षयं कासं श्वासञ्च ग्रहणीगदम्","text":"palāni sapta bhaṅgāyāḥ sitāsarvasamā matā cūrṇametatkṣayaṃ kāsaṃ śvāsañca grahaṇīgadam"},{"type":"verse","number":"53","sanskrit":"अरोचकं प्रतिश्यायं तथा चानलमन्दताम् एतान् रोगान्निहन्त्येव वृक्षमिन्द्रा शनिर्यथा","text":"arocakaṃ pratiśyāyaṃ tathā cānalamandatām etān rogānnihantyeva vṛkṣamindrā śaniryathā"},{"type":"verse","number":"54","sanskrit":"बालरोगाधिकारोक्तं तैलं लाक्षादि योजयेत् अभ्यङ्गे यक्ष्मिणो नित्यं वृद्धवैद्योपदेशतः","text":"bālarogādhikāroktaṃ tailaṃ lākṣādi yojayet abhyaṅge yakṣmiṇo nityaṃ vṛddhavaidyopadeśataḥ"},{"type":"verse","number":"55","sanskrit":"वासकस्य रसप्रस्थं मानिका सितशर्करा पिप्पल्या द्विपलं तावत्सर्पिषश्च शनैः पचेत्","text":"vāsakasya rasaprasthaṃ mānikā sitaśarkarā pippalyā dvipalaṃ tāvatsarpiṣaśca śanaiḥ pacet"},{"type":"verse","number":"56","sanskrit":"तस्मिंल्लेहत्वमायाते शीते क्षौद्र पलाष्टकम् दत्वाऽवतारयेद् वैद्यो लीढो लेहोऽयमुत्तमः","text":"tasmiṃllehatvamāyāte śīte kṣaudra palāṣṭakam datvā'vatārayed vaidyo līḍho leho'yamuttamaḥ"},{"type":"verse","number":"57","sanskrit":"हन्त्येव राजयक्ष्माणं कासं श्वासञ्च दारुणम् पार्श्वशूलञ्च हृच्छूलं रक्तपित्तं ज्वरं तथा","text":"hantyeva rājayakṣmāṇaṃ kāsaṃ śvāsañca dāruṇam pārśvaśūlañca hṛcchūlaṃ raktapittaṃ jvaraṃ tathā"},{"type":"verse","number":"58","sanskrit":"व्यवायशोषिणं क्षीणं रसमांसाज्यभोजनैः सुकूलैर्मधुरैर्हृद्यैर्जीवनीयैरुपाचरेत्","text":"vyavāyaśoṣiṇaṃ kṣīṇaṃ rasamāṃsājyabhojanaiḥ sukūlairmadhurairhṛdyairjīvanīyairupācaret"},{"type":"verse","number":"59","sanskrit":"हर्षणाश्वासनैः क्षीरैःस्निग्धैर्मधुरशीतलैः दीपनैर्लघुभिश्चान्नैः शोकशोषमुपाचरेत्","text":"harṣaṇāśvāsanaiḥ kṣīraiḥsnigdhairmadhuraśītalaiḥ dīpanairlaghubhiścānnaiḥ śokaśoṣamupācaret"},{"type":"verse","number":"60","sanskrit":"व्यायामशोषिणं स्निग्धैः क्षतक्षयहितैर्हिमैः उपाचरेज्जीवनीयैर्विधिना श्लैष्मिकेण तु","text":"vyāyāmaśoṣiṇaṃ snigdhaiḥ kṣatakṣayahitairhimaiḥ upācarejjīvanīyairvidhinā ślaiṣmikeṇa tu"},{"type":"verse","number":"61","sanskrit":"आस्यासुखैर्दिवास्वप्नैः शीतैर्मधुरबृंहणैः अन्नमांसरसाहारैरध्वशोषमुपाचरेत्","text":"āsyāsukhairdivāsvapnaiḥ śītairmadhurabṛṃhaṇaiḥ annamāṃsarasāhārairadhvaśoṣamupācaret"},{"type":"verse","number":"62","sanskrit":"व्रणशोषं जयेत्स्निग्धैर्दीपनैः स्वादुशीतलैः ईषदम्लैरनम्लैर्वा यूषमांसरसादिभिः","text":"vraṇaśoṣaṃ jayetsnigdhairdīpanaiḥ svāduśītalaiḥ īṣadamlairanamlairvā yūṣamāṃsarasādibhiḥ"},{"type":"verse","number":"63","sanskrit":"उरः क्षतचिकित्सा बलाऽश्वगन्धा श्रीपर्णी बहुपुत्री पुनर्नवाः पयसा नित्यमभ्यस्ताः शमयन्ति क्षतक्षयम्","text":"uraḥ kṣatacikitsā balā'śvagandhā śrīparṇī bahuputrī punarnavāḥ payasā nityamabhyastāḥ śamayanti kṣatakṣayam"},{"type":"verse","number":"64","sanskrit":"एलापत्र्रत्वचोऽद्धाक्षाः पिप्पल्यर्द्धपलं पृथक् सितामधुकखर्जूरमृद्वीकाश्च पलोन्मिताः","text":"elāpatrratvaco'ddhākṣāḥ pippalyarddhapalaṃ pṛthak sitāmadhukakharjūramṛdvīkāśca palonmitāḥ"},{"type":"verse","number":"65","sanskrit":"सञ्चूर्ण्य मधुना युक्ता वटिकाः सम्प्रकल्पयेत् अक्षमात्रां ततश्चैकां भक्षयेत्तु दिने दिने","text":"sañcūrṇya madhunā yuktā vaṭikāḥ samprakalpayet akṣamātrāṃ tataścaikāṃ bhakṣayettu dine dine"},{"type":"verse","number":"66","sanskrit":"क्षतं क्षयं ज्वरं कासं श्वासं हिक्कां वमिं भ्रमम् मूर्च्छां मदं तृषां शोषं पार्श्वशूलमरोचकम्","text":"kṣataṃ kṣayaṃ jvaraṃ kāsaṃ śvāsaṃ hikkāṃ vamiṃ bhramam mūrcchāṃ madaṃ tṛṣāṃ śoṣaṃ pārśvaśūlamarocakam"},{"type":"verse","number":"67","sanskrit":"प्लीहानमाढ्यवातञ्च रक्तपित्तं स्वरक्षयम् एलादिगुटिका हन्ति वृष्या सन्तर्पणी परा","text":"plīhānamāḍhyavātañca raktapittaṃ svarakṣayam elādiguṭikā hanti vṛṣyā santarpaṇī parā"},{"type":"verse","number":"68","sanskrit":"द्रा क्षायाः प्रस्थमेकन्तु मधुकस्य पलाष्टकम् पचेत्तोयाढके शुद्धे पादशेषेण तेन तु","text":"drā kṣāyāḥ prasthamekantu madhukasya palāṣṭakam pacettoyāḍhake śuddhe pādaśeṣeṇa tena tu"},{"type":"verse","number":"69","sanskrit":"पलिके मधुकद्रा क्षे पिष्टे कृष्णापलद्वयम् प्रदाय सर्पिषः प्रस्थं पचेत्क्षीरे चतुर्गुणे","text":"palike madhukadrā kṣe piṣṭe kṛṣṇāpaladvayam pradāya sarpiṣaḥ prasthaṃ pacetkṣīre caturguṇe"},{"type":"verse","number":"70","sanskrit":"सिद्धे शीते पलान्यष्टौ शर्करायाः प्रदापयेत् एतद् द्रा क्षाघृतं सिद्धं क्षतक्षीणसुखावहम्","text":"siddhe śīte palānyaṣṭau śarkarāyāḥ pradāpayet etad drā kṣāghṛtaṃ siddhaṃ kṣatakṣīṇasukhāvaham"},{"type":"verse","number":"71","sanskrit":"वातं पित्तं ज्वरं श्वासं विस्फोटकहलीमकान् प्रदरं रक्तपित्तञ्च हन्यान्मांसबलप्रदम्","text":"vātaṃ pittaṃ jvaraṃ śvāsaṃ visphoṭakahalīmakān pradaraṃ raktapittañca hanyānmāṃsabalapradam"},{"type":"verse","number":"72","sanskrit":"क्षीरे धात्री च मञ्जिष्ठा क्षीरिण्याश्च तथा रसैः पचेत्समैघृतप्रस्थं मधुरैः कर्षसम्मितैः","text":"kṣīre dhātrī ca mañjiṣṭhā kṣīriṇyāśca tathā rasaiḥ pacetsamaighṛtaprasthaṃ madhuraiḥ karṣasammitaiḥ"},{"type":"verse","number":"73","sanskrit":"द्रा क्षाद्विचन्दनोशीरैः शर्करोत्पलद्मकैः मधूककुसुमानन्ताकाश्मरीतृणसंज्ञकैः","text":"drā kṣādvicandanośīraiḥ śarkarotpaladmakaiḥ madhūkakusumānantākāśmarītṛṇasaṃjñakaiḥ"},{"type":"verse","number":"74","sanskrit":"प्रस्थार्द्धं मधुनः शीते शर्कराऽद्धतुलां तथा पलार्द्धिकांश्च सञ्चूर्ण्य त्वगेलापद्मकेशरान्","text":"prasthārddhaṃ madhunaḥ śīte śarkarā'ddhatulāṃ tathā palārddhikāṃśca sañcūrṇya tvagelāpadmakeśarān"},{"type":"verse","number":"75","sanskrit":"विनीय तत्र संलिह्यान्मात्रां नित्यं सुयन्त्रितः अमृतप्राशमित्येदश्विभ्यां परिकीर्त्तितम्","text":"vinīya tatra saṃlihyānmātrāṃ nityaṃ suyantritaḥ amṛtaprāśamityedaśvibhyāṃ parikīrttitam"},{"type":"verse","number":"76","sanskrit":"क्षीरमांसाशिनां हन्ति रक्तपित्तं क्षतक्षयम् तृष्णाऽरुचिश्वासकासच्छर्दिमूर्च्छाप्रमर्दनम्","text":"kṣīramāṃsāśināṃ hanti raktapittaṃ kṣatakṣayam tṛṣṇā'ruciśvāsakāsacchardimūrcchāpramardanam"},{"type":"verse","number":"77","sanskrit":"मूत्रकृच्छ्रज्वरघ्नञ्च बल्यं स्त्रीरतिवर्द्धनम्","text":"mūtrakṛcchrajvaraghnañca balyaṃ strīrativarddhanam"},{"type":"verse","number":"78","sanskrit":"यद्यच्च तर्पणं शीतमविदाहि हितंलघु अन्नपानं निषेव्यंस्यात्क्षतक्षीणैः सुखार्थिभिः","text":"yadyacca tarpaṇaṃ śītamavidāhi hitaṃlaghu annapānaṃ niṣevyaṃsyātkṣatakṣīṇaiḥ sukhārthibhiḥ"},{"type":"verse","number":"79","sanskrit":"शोकं स्त्रियः क्रोधमसूयताञ्ज त्यजेदुदारान्विषयान्भजेच्च तथा द्विजातींस्त्रिदशान्गुरुंश्च वाचश्च पुण्याः शृणुयाद् द्विजेभ्यः","text":"śokaṃ striyaḥ krodhamasūyatāñja tyajedudārānviṣayānbhajecca tathā dvijātīṃstridaśānguruṃśca vācaśca puṇyāḥ śṛṇuyād dvijebhyaḥ"},{"type":"verse","number":"80","sanskrit":"अथ राजयक्ष्मणि रसाः रसभस्मामृतासत्वं लोहं मधुघृतान्वितम् अमृतेश्वरनामायं षड्गुञ्जोराजयक्ष्मणि","text":"atha rājayakṣmaṇi rasāḥ rasabhasmāmṛtāsatvaṃ lohaṃ madhughṛtānvitam amṛteśvaranāmāyaṃ ṣaḍguñjorājayakṣmaṇi"},{"type":"verse","number":"81","sanskrit":"त्रयॐशा मारितात्सूतादेकॐशो हेमभस्मतः एकॐशो मृतताम्रस्य शिला गन्धश्च तालकम्","text":"trayaoṃśā māritātsūtādekaoṃśo hemabhasmataḥ ekaoṃśo mṛtatāmrasya śilā gandhaśca tālakam"},{"type":"verse","number":"82","sanskrit":"प्रत्येकंभागयुग्मं स्यादेतत्सर्वं विचूर्णयेत् वराटीः पूरयेत्तेन छागीक्षीरेण टङ्कणम्","text":"pratyekaṃbhāgayugmaṃ syādetatsarvaṃ vicūrṇayet varāṭīḥ pūrayettena chāgīkṣīreṇa ṭaṅkaṇam"},{"type":"verse","number":"83","sanskrit":"पिष्ट्वा तेन मुखं रुद्ध्वा मृद्भाण्डे ताश्च धारयेत् कूप्यां पचेद्र जपुटे स्वाङ्गशीतं समुद्धरेत्","text":"piṣṭvā tena mukhaṃ ruddhvā mṛdbhāṇḍe tāśca dhārayet kūpyāṃ pacedra japuṭe svāṅgaśītaṃ samuddharet"},{"type":"verse","number":"84","sanskrit":"रसो राजमृगाङ्कोयंचतुर्गुञ्जः क्षयापहः मरिचैरुनविंशत्याकणाभिर्दशभिस्तथा","text":"raso rājamṛgāṅkoyaṃcaturguñjaḥ kṣayāpahaḥ maricairunaviṃśatyākaṇābhirdaśabhistathā"},{"type":"verse","number":"85","sanskrit":"मधुना सर्पिषा चापि दद्यादेतं रसं भिषग् अनेन नश्यति क्षिप्रं वातश्लेष्मभवः क्षयः","text":"madhunā sarpiṣā cāpi dadyādetaṃ rasaṃ bhiṣag anena naśyati kṣipraṃ vātaśleṣmabhavaḥ kṣayaḥ"},{"type":"verse","number":"86","sanskrit":"शुद्धं सूतं द्विधा गन्धं कुर्यात्खल्वेन कज्जलीम् तयोः समं तीक्ष्णचूर्णं मर्दयेत्कन्यकाद्र्रवैः","text":"śuddhaṃ sūtaṃ dvidhā gandhaṃ kuryātkhalvena kajjalīm tayoḥ samaṃ tīkṣṇacūrṇaṃ mardayetkanyakādrravaiḥ"},{"type":"verse","number":"87","sanskrit":"द्वियाममातपे गोलं ताम्रपात्रे निधापयेत् आच्छाद्यैरण्डपत्रेण स्यादुष्णं यामयुग्मतः","text":"dviyāmamātape golaṃ tāmrapātre nidhāpayet ācchādyairaṇḍapatreṇa syāduṣṇaṃ yāmayugmataḥ"},{"type":"verse","number":"88","sanskrit":"धान्यराशौ न्यसेत्पश्चादष्टरात्रात्तमुद्धरेत् सञ्चूर्ण्य गालयेद्वस्त्रैः सत्यं वारितरं भवेत्","text":"dhānyarāśau nyasetpaścādaṣṭarātrāttamuddharet sañcūrṇya gālayedvastraiḥ satyaṃ vāritaraṃ bhavet"},{"type":"verse","number":"89","sanskrit":"त्रिकटुत्रिफलैलाभिर्जातीफललवङ्गकैः नवभागोन्मितैरेभिः समैरेष रसो भवेत्","text":"trikaṭutriphalailābhirjātīphalalavaṅgakaiḥ navabhāgonmitairebhiḥ samaireṣa raso bhavet"},{"type":"verse","number":"90","sanskrit":"निष्कद्वयमितं नित्यंमधुना सह लेहयेत् अयमग्निरसो नाम्नाकासक्षयहरः परः","text":"niṣkadvayamitaṃ nityaṃmadhunā saha lehayet ayamagniraso nāmnākāsakṣayaharaḥ paraḥ"},{"type":"verse","number":"91","sanskrit":"इत्येकादशो राजयक्ष्माधिकारः सम्पूर्णः ११","text":"ityekādaśo rājayakṣmādhikāraḥ sampūrṇaḥ 11"}]},{"sthana":"Уттаракханда","number":12,"lang":"sa","content":[{"type":"heading","heading":"Каса — кашель"},{"type":"verse","number":"1","sanskrit":"धूमोपघाताद्र जसस्तथैव व्यायामरुक्षान्ननिषेवणाच्च विमार्गगत्वादपि भोजनस्य वेगावरोधात्क्षवथोस्तथैव","text":"dhūmopaghātādra jasastathaiva vyāyāmarukṣānnaniṣevaṇācca vimārgagatvādapi bhojanasya vegāvarodhātkṣavathostathaiva"},{"type":"verse","number":"2","sanskrit":"प्राणो ह्युदानानुगतः प्रदुष्टः सम्भिन्नकांस्यस्वनतुल्यघोषः निरेति वक्त्रात्सहसा सदोषोमनीषिभिः कास इति प्रदिष्टः","text":"prāṇo hyudānānugataḥ praduṣṭaḥ sambhinnakāṃsyasvanatulyaghoṣaḥ nireti vaktrātsahasā sadoṣomanīṣibhiḥ kāsa iti pradiṣṭaḥ"},{"type":"verse","number":"3","sanskrit":"पञ्चकासाः स्मृता वातपित्तश्लेष्मक्षतक्षयैः क्षयायोपेक्षिताः सर्वे बलिनश्चोत्तरोत्तरम्","text":"pañcakāsāḥ smṛtā vātapittaśleṣmakṣatakṣayaiḥ kṣayāyopekṣitāḥ sarve balinaścottarottaram"},{"type":"verse","number":"4","sanskrit":"पूर्वरूपं भवेत्तेषां शूकपूर्णगलास्यता कण्ठे कण्डूश्च भोज्यानामवरोधश्च जायते","text":"pūrvarūpaṃ bhavetteṣāṃ śūkapūrṇagalāsyatā kaṇṭhe kaṇḍūśca bhojyānāmavarodhaśca jāyate"},{"type":"verse","number":"5","sanskrit":"हृच्छङ्खपार्श्वोदरमूर्द्धशूली क्षामाननः क्षीणबलस्वरौजाः प्रसक्तवेगस्तु समीरणेन भिन्नस्वरः कासतिशुष्कमेव","text":"hṛcchaṅkhapārśvodaramūrddhaśūlī kṣāmānanaḥ kṣīṇabalasvaraujāḥ prasaktavegastu samīraṇena bhinnasvaraḥ kāsatiśuṣkameva"},{"type":"verse","number":"6","sanskrit":"उरोविदाहज्वरवक्त्रशोषैरभ्यर्दितस्तिक्तमुखस्तृषाऽत्त पित्तेन पीतानि वमेत्कटूनि कासेत्स पाण्डुः परिदह्यमानः","text":"urovidāhajvaravaktraśoṣairabhyarditastiktamukhastṛṣā'tta pittena pītāni vametkaṭūni kāsetsa pāṇḍuḥ paridahyamānaḥ"},{"type":"verse","number":"7","sanskrit":"प्रलिप्यमानेन मुखेन सीदञ्छिरोरुजाऽत्त कफपूर्णदेहः अभक्तरुग्गौरवकण्डुयुक्तः कासेद् भृशं सान्द्र कफः कफेन","text":"pralipyamānena mukhena sīdañchirorujā'tta kaphapūrṇadehaḥ abhaktaruggauravakaṇḍuyuktaḥ kāsed bhṛśaṃ sāndra kaphaḥ kaphena"},{"type":"verse","number":"8","sanskrit":"अतिव्यवायभाराध्वयुद्धाश्वगजनिग्रहैः रूक्षस्योरःक्षतं वायुर्गृहीत्वाकासमावहेत्","text":"ativyavāyabhārādhvayuddhāśvagajanigrahaiḥ rūkṣasyoraḥkṣataṃ vāyurgṛhītvākāsamāvahet"},{"type":"verse","number":"9","sanskrit":"स पूर्वं कासते शुष्कं ततः ष्ठीवेत् सशोणितम् कण्ठेन कूजताऽत्यर्थं विभग्नेनेव चोरसा","text":"sa pūrvaṃ kāsate śuṣkaṃ tataḥ ṣṭhīvet saśoṇitam kaṇṭhena kūjatā'tyarthaṃ vibhagneneva corasā"},{"type":"verse","number":"10","sanskrit":"सूचीभिरिव तीक्ष्णाभिस्तुद्यमानेनशूलिना दुःखस्पर्शेनशूलेन भेदपीडाऽभितापिना","text":"sūcībhiriva tīkṣṇābhistudyamānenaśūlinā duḥkhasparśenaśūlena bhedapīḍā'bhitāpinā"},{"type":"verse","number":"11","sanskrit":"पर्वभेदज्वरश्वास तृष्णावैस्वर्यपीडितः पारावत इवाकूजन् कासवेगात् क्षतोद्भवात्","text":"parvabhedajvaraśvāsa tṛṣṇāvaisvaryapīḍitaḥ pārāvata ivākūjan kāsavegāt kṣatodbhavāt"},{"type":"verse","number":"12","sanskrit":"विषमासात्म्यभोज्यातिव्यवायाद् वेगनिग्रहात् घृणिनां शोचतां नॄणां व्यापन्नेऽग्नौ त्रयो मलाः कुपिताः क्षयजं कासं कुर्युर्देहक्षयप्रदम्","text":"viṣamāsātmyabhojyātivyavāyād veganigrahāt ghṛṇināṃ śocatāṃ nṝṇāṃ vyāpanne'gnau trayo malāḥ kupitāḥ kṣayajaṃ kāsaṃ kuryurdehakṣayapradam"},{"type":"verse","number":"13","sanskrit":"सगात्रशूलज्वरमोहदाहप्राणक्षयं चोपलभेत कासी","text":"sagātraśūlajvaramohadāhaprāṇakṣayaṃ copalabheta kāsī"},{"type":"verse","number":"14","sanskrit":"शुष्यन् विनिष्ठीवति निर्बलस्तु प्रक्षीणमांसो रुधिरं सपूयम् तं सर्वलिङ्गं भृशदुश्चिकित्स्यं चिकित्सितज्ञाः क्षयजं वदन्ति","text":"śuṣyan viniṣṭhīvati nirbalastu prakṣīṇamāṃso rudhiraṃ sapūyam taṃ sarvaliṅgaṃ bhṛśaduścikitsyaṃ cikitsitajñāḥ kṣayajaṃ vadanti"},{"type":"verse","number":"15","sanskrit":"इत्येष क्षयजः कासःक्षीणानां देहनाशनः साध्यो बलवतां वा स्याद्याप्यस्त्वेवं क्षतोत्थितः","text":"ityeṣa kṣayajaḥ kāsaḥkṣīṇānāṃ dehanāśanaḥ sādhyo balavatāṃ vā syādyāpyastvevaṃ kṣatotthitaḥ"},{"type":"verse","number":"16","sanskrit":"न वै कदाचित्सिद्ध्य्तेमपि पादगुणान्वितौ स्थविराणां जराकासः सर्वो याप्यः प्रकीर्त्तितः","text":"na vai kadācitsiddhytemapi pādaguṇānvitau sthavirāṇāṃ jarākāsaḥ sarvo yāpyaḥ prakīrttitaḥ"},{"type":"verse","number":"17","sanskrit":"त्रीन्पूर्वान्साधयेत्साध्यान्पथ्यैर्याप्यांस्तु यापयेत्","text":"trīnpūrvānsādhayetsādhyānpathyairyāpyāṃstu yāpayet"},{"type":"verse","number":"18","sanskrit":"ज्वरारोचकहृल्लासस्वरभेदक्षयादयः भवन्त्युपेक्षया यस्मात् तस्मात्तत्त्वरया जयेत्","text":"jvarārocakahṛllāsasvarabhedakṣayādayaḥ bhavantyupekṣayā yasmāt tasmāttattvarayā jayet"},{"type":"verse","number":"19","sanskrit":"कासस्य चिकित्सा वास्तूको वायसीशाकं मूलकं सुनिषण्णकम् स्नेहास्तैलादयो भक्ष्यास्तथेक्षुरसगौडिकाः","text":"kāsasya cikitsā vāstūko vāyasīśākaṃ mūlakaṃ suniṣaṇṇakam snehāstailādayo bhakṣyāstathekṣurasagauḍikāḥ"},{"type":"verse","number":"20","sanskrit":"दध्यारनालाम्लफलं प्रसन्नापानमेव च शस्यते वातकासेषु स्वाद्वम्ललवणानि च","text":"dadhyāranālāmlaphalaṃ prasannāpānameva ca śasyate vātakāseṣu svādvamlalavaṇāni ca"},{"type":"verse","number":"21","sanskrit":"ग्राम्यानूपौदकैः शालियवगोधूमषष्टिकान् रसैर्माषात्मगुप्तानां यूषैर्वा भोजयेद्भिषक्","text":"grāmyānūpaudakaiḥ śāliyavagodhūmaṣaṣṭikān rasairmāṣātmaguptānāṃ yūṣairvā bhojayedbhiṣak"},{"type":"verse","number":"22","sanskrit":"दशमूलीकृता श्वासकासहिक्कारुजाऽपहा यवागूर्दीपनी वृष्या वालरोगविनाशिनी","text":"daśamūlīkṛtā śvāsakāsahikkārujā'pahā yavāgūrdīpanī vṛṣyā vālarogavināśinī"},{"type":"verse","number":"23","sanskrit":"रसः कर्कोटकानां वा घृतभृष्टः सनागरः वातकासप्रशमनः शृङ्गीमत्स्यस्य वा पुनः","text":"rasaḥ karkoṭakānāṃ vā ghṛtabhṛṣṭaḥ sanāgaraḥ vātakāsapraśamanaḥ śṛṅgīmatsyasya vā punaḥ"},{"type":"verse","number":"24","sanskrit":"कण्टकारीयुगद्रा क्षा वासाकर्चूरबालकैः नागरेण च पिप्पल्या क्वथितं सलिलं पिबेत् शर्करामधुसंयुक्तं पित्तकासहरं परम्","text":"kaṇṭakārīyugadrā kṣā vāsākarcūrabālakaiḥ nāgareṇa ca pippalyā kvathitaṃ salilaṃ pibet śarkarāmadhusaṃyuktaṃ pittakāsaharaṃ param"},{"type":"verse","number":"25","sanskrit":"कफजकासस्य चिकित्सा पिप्पली कट्फलंशुण्ठी शृङ्गी भार्गी तथोषणम् कारवी कण्टकारी च सिन्दुवारो यवानिका","text":"kaphajakāsasya cikitsā pippalī kaṭphalaṃśuṇṭhī śṛṅgī bhārgī tathoṣaṇam kāravī kaṇṭakārī ca sinduvāro yavānikā"},{"type":"verse","number":"26","sanskrit":"चित्रको वासकश्चैषां कषायं विधिवत्कृतम् कफकासविनाशाय पिबेत्कृष्णारजोयुतम्","text":"citrako vāsakaścaiṣāṃ kaṣāyaṃ vidhivatkṛtam kaphakāsavināśāya pibetkṛṣṇārajoyutam"},{"type":"verse","number":"27","sanskrit":"इक्ष्विक्षुबालिका पद्ममृणालोत्पलचन्दनम् मधुकं पिप्पली द्रा क्षा लाक्षा शृङ्गी शतावरी","text":"ikṣvikṣubālikā padmamṛṇālotpalacandanam madhukaṃ pippalī drā kṣā lākṣā śṛṅgī śatāvarī"},{"type":"verse","number":"28","sanskrit":"द्विगुणा च तुगाक्षीरी सिता सर्वचतुर्गुणा लिह्यात्तन्मधुसर्पिर्भ्यां क्षतकासनिवृत्तये","text":"dviguṇā ca tugākṣīrī sitā sarvacaturguṇā lihyāttanmadhusarpirbhyāṃ kṣatakāsanivṛttaye"},{"type":"verse","number":"29","sanskrit":"चूर्णं काकुभमिष्टं वासकरसभावितं बहून्वारान् मधुघृतसितोपलाभिर्लेह्यं क्षयकासरक्तहरम्","text":"cūrṇaṃ kākubhamiṣṭaṃ vāsakarasabhāvitaṃ bahūnvārān madhughṛtasitopalābhirlehyaṃ kṣayakāsaraktaharam"},{"type":"verse","number":"30","sanskrit":"ताप्यमानस्य कासेन नासास्रावे स्वरे जडे क्षवथौ गन्धनाशेच धूमपानं प्रयोजयेत्","text":"tāpyamānasya kāsena nāsāsrāve svare jaḍe kṣavathau gandhanāśeca dhūmapānaṃ prayojayet"},{"type":"verse","number":"31","sanskrit":"मनः शिलाऽलमरिचमांसीमुस्तेङ्गुदैः पिबेत् धूमं त्र्यहञ्च तस्यानु पयश्च सगुडं पिबेत्","text":"manaḥ śilā'lamaricamāṃsīmusteṅgudaiḥ pibet dhūmaṃ tryahañca tasyānu payaśca saguḍaṃ pibet"},{"type":"verse","number":"32","sanskrit":"एष कासान्पृथग्द्वन्द्वसर्वदोषसमुद्भवान् शतैरपि प्रयोगाणामसाध्यान्साधयेद् ध्रुवम्","text":"eṣa kāsānpṛthagdvandvasarvadoṣasamudbhavān śatairapi prayogāṇāmasādhyānsādhayed dhruvam"},{"type":"verse","number":"33","sanskrit":"बदरीदलमालिप्तं शिलयाऽतपशोषितम् तद्धूमपानं सक्षीरं महाकासनिवारणम्","text":"badarīdalamāliptaṃ śilayā'tapaśoṣitam taddhūmapānaṃ sakṣīraṃ mahākāsanivāraṇam"},{"type":"verse","number":"34","sanskrit":"कण्टकारीकृतः क्वाथः सकृष्णः सर्वकासहः कण्टकार्याः कणायाश्च चूर्णं समधु कासहत्","text":"kaṇṭakārīkṛtaḥ kvāthaḥ sakṛṣṇaḥ sarvakāsahaḥ kaṇṭakāryāḥ kaṇāyāśca cūrṇaṃ samadhu kāsahat"},{"type":"verse","number":"35","sanskrit":"लवङ्गजातीफलपिप्पलीनां भागान्प्रकल्प्याक्षसमानमीषाम् पलार्द्धमानं मरिचं प्रदेयं पलानि चत्वारि महौषधस्य","text":"lavaṅgajātīphalapippalīnāṃ bhāgānprakalpyākṣasamānamīṣām palārddhamānaṃ maricaṃ pradeyaṃ palāni catvāri mahauṣadhasya"},{"type":"verse","number":"36","sanskrit":"सिता समस्तेन समाऽथ चूर्णं रोगानिमानाशु बलान्निहन्ति कासज्वरारोचकमेहगुल्मश्वासाग्निमान्द्यग्रहणीविकारान्","text":"sitā samastena samā'tha cūrṇaṃ rogānimānāśu balānnihanti kāsajvarārocakamehagulmaśvāsāgnimāndyagrahaṇīvikārān"},{"type":"verse","number":"37","sanskrit":"कुनटीसैन्धवव्योषविडङ्गामयहिङ्गुभिः लेहः साज्यमधुः कासश्वासहिक्कानिवारणः","text":"kunaṭīsaindhavavyoṣaviḍaṅgāmayahiṅgubhiḥ lehaḥ sājyamadhuḥ kāsaśvāsahikkānivāraṇaḥ"},{"type":"verse","number":"38","sanskrit":"हरीतकीकणाशुण्ठीमरिचं गुडसंयुतम् कासश्लेष्मापहं प्रोक्तं परं वह्नेः प्रदीपनम्","text":"harītakīkaṇāśuṇṭhīmaricaṃ guḍasaṃyutam kāsaśleṣmāpahaṃ proktaṃ paraṃ vahneḥ pradīpanam"},{"type":"verse","number":"39","sanskrit":"कर्षः कर्षांशपलं पलद्वयं स्यात्ततोर्द्धकर्षञ्च मरिचस्य पिप्पलीनां दाडिमगुडयावशूकानाम्","text":"karṣaḥ karṣāṃśapalaṃ paladvayaṃ syāttatorddhakarṣañca maricasya pippalīnāṃ dāḍimaguḍayāvaśūkānām"},{"type":"verse","number":"40","sanskrit":"सर्वौषधिभिरसाध्याः कासा ये वैद्यनिर्मुक्ताः अपि पूयं छर्दयतां तेषामिदमौषधं परमम्","text":"sarvauṣadhibhirasādhyāḥ kāsā ye vaidyanirmuktāḥ api pūyaṃ chardayatāṃ teṣāmidamauṣadhaṃ paramam"},{"type":"verse","number":"41","sanskrit":"मरिचं कर्षमात्रं स्यात्पिप्पली कर्षसम्मिता अर्द्धकर्षो यवक्षारः कर्षयुग्मन्तु दाडिमम्","text":"maricaṃ karṣamātraṃ syātpippalī karṣasammitā arddhakarṣo yavakṣāraḥ karṣayugmantu dāḍimam"},{"type":"verse","number":"42","sanskrit":"एतच्चूर्णीकृतं युञ्ज्यादष्टकर्षगुडेन हि शाणप्रमाणां गुटिकां कृत्वा वक्त्रे विधारयेत् अस्याः प्रभावात्सर्वेऽपि कासा यान्त्येव सङ्क्षयम्","text":"etaccūrṇīkṛtaṃ yuñjyādaṣṭakarṣaguḍena hi śāṇapramāṇāṃ guṭikāṃ kṛtvā vaktre vidhārayet asyāḥ prabhāvātsarve'pi kāsā yāntyeva saṅkṣayam"},{"type":"verse","number":"43","sanskrit":"समूलवल्कच्छदकण्टकार्यास्तुलां ततो द्रो णमितं जलञ्च हरीतकीनां शतमेकपात्रे विपाच्य कुर्याच्चरणाम्बुशेषम्","text":"samūlavalkacchadakaṇṭakāryāstulāṃ tato dro ṇamitaṃ jalañca harītakīnāṃ śatamekapātre vipācya kuryāccaraṇāmbuśeṣam"},{"type":"verse","number":"44","sanskrit":"तस्मिन्कषाये तनुवस्त्रपूते हरीतकीभिः सहिते गुडस्य तुलां विनिक्षिप्य पचेत्सुपक्वमेतत्समुत्तार्य सुशीतलञ्च","text":"tasminkaṣāye tanuvastrapūte harītakībhiḥ sahite guḍasya tulāṃ vinikṣipya pacetsupakvametatsamuttārya suśītalañca"},{"type":"verse","number":"45","sanskrit":"पलं पलञ्चापि कटुत्रयञ्च तथा चतुर्जातपलं विचूर्ण्य पलानि षट् पुष्परसस्य चापि विनिक्षिपेत्तत्र विमिश्रयेच्च","text":"palaṃ palañcāpi kaṭutrayañca tathā caturjātapalaṃ vicūrṇya palāni ṣaṭ puṣparasasya cāpi vinikṣipettatra vimiśrayecca"},{"type":"verse","number":"46","sanskrit":"प्रयुज्यमानो विधिनैष लेहो यथाबलञ्चापियथाऽनलञ्च वातात्मकं पित्तकृतं कफोत्थं त्रिदोषजातानपि च त्रिदोषम्","text":"prayujyamāno vidhinaiṣa leho yathābalañcāpiyathā'nalañca vātātmakaṃ pittakṛtaṃ kaphotthaṃ tridoṣajātānapi ca tridoṣam"},{"type":"verse","number":"47","sanskrit":"क्षतोद्भवञ्च क्षयजञ्च कासं श्वासञ्च हन्यात्सह पीनसेन यक्ष्माणमेकादशरूपमुग्रं हरीतकी या भृगुणोपदिष्टा","text":"kṣatodbhavañca kṣayajañca kāsaṃ śvāsañca hanyātsaha pīnasena yakṣmāṇamekādaśarūpamugraṃ harītakī yā bhṛguṇopadiṣṭā"},{"type":"verse","number":"48","sanskrit":"कण्टकारीतुलां नीरद्रो णे पक्त्वा कषायकम् पादशेषं गृहीत्वा च तत्र चूर्णानि दापयेत्","text":"kaṇṭakārītulāṃ nīradro ṇe paktvā kaṣāyakam pādaśeṣaṃ gṛhītvā ca tatra cūrṇāni dāpayet"},{"type":"verse","number":"49","sanskrit":"पृथक्पलांशान्येतानि गुडूची चव्यचित्रकौ मुस्तं कर्कटशृङ्गी च त्र्यूषणं धन्वयासकः","text":"pṛthakpalāṃśānyetāni guḍūcī cavyacitrakau mustaṃ karkaṭaśṛṅgī ca tryūṣaṇaṃ dhanvayāsakaḥ"},{"type":"verse","number":"50","sanskrit":"भार्गी रास्नाशटी चैव शर्करापलविंशतिः प्रत्येकञ्च पलान्यष्टौ प्रदद्याद् घृततैलयोः","text":"bhārgī rāsnāśaṭī caiva śarkarāpalaviṃśatiḥ pratyekañca palānyaṣṭau pradadyād ghṛtatailayoḥ"},{"type":"verse","number":"51","sanskrit":"पक्त्वा लेहत्वमानीय शीते मधु पलाष्टकम् चतुर्भागं तुगाक्षीर्याः पिप्पल्याश्च चतुःपलम्","text":"paktvā lehatvamānīya śīte madhu palāṣṭakam caturbhāgaṃ tugākṣīryāḥ pippalyāśca catuḥpalam"},{"type":"verse","number":"52","sanskrit":"क्षिप्त्वा निदध्यात्सुदृढे मृण्मये भाजने शुभं लेहोऽय हन्ति हिक्काऽतिकासश्वासानशेषतः","text":"kṣiptvā nidadhyātsudṛḍhe mṛṇmaye bhājane śubhaṃ leho'ya hanti hikkā'tikāsaśvāsānaśeṣataḥ"},{"type":"verse","number":"53","sanskrit":"इति द्वादश कासाधिकारः समाप्तः","text":"iti dvādaśa kāsādhikāraḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":13,"lang":"sa","content":[{"type":"heading","heading":"Хикка — икота"},{"type":"verse","number":"1","sanskrit":"विदाहिगुरुविष्टम्भि रुक्षाभिष्यन्दिभोजनैः शीतपानाशनस्नानरजो धूमात्तथाऽनिलैः","text":"vidāhiguruviṣṭambhi rukṣābhiṣyandibhojanaiḥ śītapānāśanasnānarajo dhūmāttathā'nilaiḥ"},{"type":"verse","number":"2","sanskrit":"व्ययामकर्मभाराध्व वेगाघातापतर्पणैः हिक्का श्वासश्च कासश्च नृणां समुपजायते","text":"vyayāmakarmabhārādhva vegāghātāpatarpaṇaiḥ hikkā śvāsaśca kāsaśca nṛṇāṃ samupajāyate"},{"type":"verse","number":"3","sanskrit":"वायुःकफेनानुगतः पञ्च हिक्काःकरोति हि अन्नजां यमलां क्षुद्रं गम्भीरां महतीं तथा","text":"vāyuḥkaphenānugataḥ pañca hikkāḥkaroti hi annajāṃ yamalāṃ kṣudraṃ gambhīrāṃ mahatīṃ tathā"},{"type":"verse","number":"4","sanskrit":"मुहुर्मुहुर्वायुरुदेति सस्वनो यकृत्प्लिहान्त्राणि मुखादिवाक्षिपन् स दोषवानाशु हिनस्त्यसून्यतस्ततस्तु हिक्केत्यभिधीयते बुधैः","text":"muhurmuhurvāyurudeti sasvano yakṛtplihāntrāṇi mukhādivākṣipan sa doṣavānāśu hinastyasūnyatastatastu hikketyabhidhīyate budhaiḥ"},{"type":"verse","number":"5","sanskrit":"कण्ठोरसोर्गुरुत्वञ्च वदनस्य कषायता हिक्कानां पूर्वरूपाणि कुक्षेराटोप एव च","text":"kaṇṭhorasorgurutvañca vadanasya kaṣāyatā hikkānāṃ pūrvarūpāṇi kukṣerāṭopa eva ca"},{"type":"verse","number":"6","sanskrit":"पानान्नैरतिसंयुक्तैः सहसा पीडितोऽनिलः हिक्कयेदूर्ध्वगो भूत्वा तां विद्यादन्नजां भिषक्","text":"pānānnairatisaṃyuktaiḥ sahasā pīḍito'nilaḥ hikkayedūrdhvago bhūtvā tāṃ vidyādannajāṃ bhiṣak"},{"type":"verse","number":"7","sanskrit":"चिरेण यमलैर्वेगैर्या हिक्कासम्प्रवर्त्तते कम्पयन्ती शिरो ग्रीवां यमलां तां विनिर्दिशेत्","text":"cireṇa yamalairvegairyā hikkāsampravarttate kampayantī śiro grīvāṃ yamalāṃ tāṃ vinirdiśet"},{"type":"verse","number":"8","sanskrit":"विकृष्टकालैर्या बेगैर्मन्दैः समभिवर्त्तते क्षुद्रि का नाम सा हिक्का जत्रुमूलं प्रधाविता","text":"vikṛṣṭakālairyā begairmandaiḥ samabhivarttate kṣudri kā nāma sā hikkā jatrumūlaṃ pradhāvitā"},{"type":"verse","number":"9","sanskrit":"नाभिप्रवृत्ता या हिक्का घोरा गम्भीरनादिनी अनेकोपद्र ववती गम्भीरा नाम सा स्मृता","text":"nābhipravṛttā yā hikkā ghorā gambhīranādinī anekopadra vavatī gambhīrā nāma sā smṛtā"},{"type":"verse","number":"10","sanskrit":"मर्माणि पीडयन्तीव सततं या प्रवर्त्तते महाहिक्केति सा ज्ञेया सर्वगात्रप्रकम्पिनी","text":"marmāṇi pīḍayantīva satataṃ yā pravarttate mahāhikketi sā jñeyā sarvagātraprakampinī"},{"type":"verse","number":"11","sanskrit":"आकम्पते हिक्कतो यस्य देहो दृष्टिश्चोर्ध्वं ताम्यते नित्यमेव क्षीणोऽन्नद्विट् क्षौति यश्चातिमात्रं तौ चान्त्यौ वर्जयेद्धिक्कमानौ","text":"ākampate hikkato yasya deho dṛṣṭiścordhvaṃ tāmyate nityameva kṣīṇo'nnadviṭ kṣauti yaścātimātraṃ tau cāntyau varjayeddhikkamānau"},{"type":"verse","number":"12","sanskrit":"अतिसञ्चितदोषस्य भक्तद्वेषकृशस्य च व्याधिभिः क्षीणदेहस्य वृद्धस्यातिव्यवायिनः","text":"atisañcitadoṣasya bhaktadveṣakṛśasya ca vyādhibhiḥ kṣīṇadehasya vṛddhasyātivyavāyinaḥ"},{"type":"verse","number":"13","sanskrit":"आयासाच्च समुत्पन्ना हिक्का हन्त्याशु जीवितम् यमिका च प्रलापार्त्तिमोहतृष्णासमन्विता","text":"āyāsācca samutpannā hikkā hantyāśu jīvitam yamikā ca pralāpārttimohatṛṣṇāsamanvitā"},{"type":"verse","number":"14","sanskrit":"अक्षीणस्याप्यदीनस्य स्थिरधात्विन्द्रि यस्य च तस्यसाधयितुं शक्या यमिका हन्त्यतोन्यथा","text":"akṣīṇasyāpyadīnasya sthiradhātvindri yasya ca tasyasādhayituṃ śakyā yamikā hantyatonyathā"},{"type":"verse","number":"15","sanskrit":"यत्किञ्चित्कफवातघ्नमुष्णं वातानुलोमनम् भेषजं पानमन्नं वा हिक्काश्वासेषु तद्धितम्","text":"yatkiñcitkaphavātaghnamuṣṇaṃ vātānulomanam bheṣajaṃ pānamannaṃ vā hikkāśvāseṣu taddhitam"},{"type":"verse","number":"16","sanskrit":"हिक्काश्वासातुरे पूर्वं तैलाक्ते स्वेद इष्यते ऊर्ध्वाधः शोधनं शस्तं दुर्बले शमनं मतम्","text":"hikkāśvāsāture pūrvaṃ tailākte sveda iṣyate ūrdhvādhaḥ śodhanaṃ śastaṃ durbale śamanaṃ matam"},{"type":"verse","number":"17","sanskrit":"प्राणावरोधतर्जनविस्मापनशीतवारिपरिषेकैः चित्रैः कथाप्रयोगैः शमयेद्धिक्कां मनोभिघातैश्च","text":"prāṇāvarodhatarjanavismāpanaśītavāripariṣekaiḥ citraiḥ kathāprayogaiḥ śamayeddhikkāṃ manobhighātaiśca"},{"type":"verse","number":"18","sanskrit":"हिक्कार्त्तस्य पयश्छागं हितं नागरसाधितम् मधुसौवर्चलोपेतं मातुलुङ्गरसं पिबेत्","text":"hikkārttasya payaśchāgaṃ hitaṃ nāgarasādhitam madhusauvarcalopetaṃ mātuluṅgarasaṃ pibet"},{"type":"verse","number":"19","sanskrit":"मधुकं मधुसंयुक्तं पिप्पली शर्करान्विता नागरं गुडसंयुक्तं हिक्काघ्नं नावनत्रयम्","text":"madhukaṃ madhusaṃyuktaṃ pippalī śarkarānvitā nāgaraṃ guḍasaṃyuktaṃ hikkāghnaṃ nāvanatrayam"},{"type":"verse","number":"20","sanskrit":"प्रवालशङ्खत्रिफलाचूर्णं मधुघृतप्लुतम् पिप्पली गैरिकञ्चेति लेहो हिक्कानिवारणः","text":"pravālaśaṅkhatriphalācūrṇaṃ madhughṛtaplutam pippalī gairikañceti leho hikkānivāraṇaḥ"},{"type":"verse","number":"21","sanskrit":"नैपाल्या गोविषाणाद्वा कुष्ठात्सर्जरसस्य वा धूपं कुशस्य वा कार्यं पिबेद्धिक्कोपशान्तये","text":"naipālyā goviṣāṇādvā kuṣṭhātsarjarasasya vā dhūpaṃ kuśasya vā kāryaṃ pibeddhikkopaśāntaye"},{"type":"verse","number":"22","sanskrit":"निर्धूमाङ्गारनिक्षिप्त हिङ्गुमाषरजोभवः हिक्काः पञ्चापि हन्त्याशु धूमः पीतो न संशयः","text":"nirdhūmāṅgāranikṣipta hiṅgumāṣarajobhavaḥ hikkāḥ pañcāpi hantyāśu dhūmaḥ pīto na saṃśayaḥ"},{"type":"verse","number":"23","sanskrit":"हरेणुककणानाञ्च क्वाथो हिङ्गुसमन्वितः हिक्काप्रशमनश्रेष्ठो धन्वन्तरिवचो यथा","text":"hareṇukakaṇānāñca kvātho hiṅgusamanvitaḥ hikkāpraśamanaśreṣṭho dhanvantarivaco yathā"},{"type":"verse","number":"24","sanskrit":"चन्द्र शूरस्य बीजानि क्षिपेदष्टगुणे जले यदा मृदूनि मृद्नीयात्ततो वाससि गालयेत्","text":"candra śūrasya bījāni kṣipedaṣṭaguṇe jale yadā mṛdūni mṛdnīyāttato vāsasi gālayet"},{"type":"verse","number":"25","sanskrit":"हिक्कातिवेगविकलस्तज्जलं पलमात्रया पिबेत्पिबेत्पुनश्चापि हिक्कावश्यं प्रशाम्यति","text":"hikkātivegavikalastajjalaṃ palamātrayā pibetpibetpunaścāpi hikkāvaśyaṃ praśāmyati"},{"type":"verse","number":"26","sanskrit":"इति त्रयोदशो हिक्काऽधिकारः समाप्तः १३","text":"iti trayodaśo hikkā'dhikāraḥ samāptaḥ 13"}]},{"sthana":"Уттаракханда","number":14,"lang":"sa","content":[{"type":"heading","heading":"Шваса — одышка (астма)"},{"type":"verse","number":"1","sanskrit":"यैरेव कारणैर्हिक्का देहिनां सम्प्रवर्त्तते तैरेव बहुभिः श्वासो व्याधिर्घोरः प्रजायते","text":"yaireva kāraṇairhikkā dehināṃ sampravarttate taireva bahubhiḥ śvāso vyādhirghoraḥ prajāyate"},{"type":"verse","number":"2","sanskrit":"महोर्ध्वच्छिन्नतमकक्षुद्र भेदैस्तु पञ्चधा भिद्यते स महाव्याधिः श्वास एको विशेषतः","text":"mahordhvacchinnatamakakṣudra bhedaistu pañcadhā bhidyate sa mahāvyādhiḥ śvāsa eko viśeṣataḥ"},{"type":"verse","number":"3","sanskrit":"प्राग्रूपं तस्य हृत्पीडा शूलमाध्मानमेव च आनाहोवक्त्रवैरस्यं शङ्खनिस्तोद एव च","text":"prāgrūpaṃ tasya hṛtpīḍā śūlamādhmānameva ca ānāhovaktravairasyaṃ śaṅkhanistoda eva ca"},{"type":"verse","number":"4","sanskrit":"यदा स्रोतांसि संरुध्य मारुतः कफपूर्वकः विष्वग्व्रजति संरुद्धस्तदा श्वासान् करोति सः","text":"yadā srotāṃsi saṃrudhya mārutaḥ kaphapūrvakaḥ viṣvagvrajati saṃruddhastadā śvāsān karoti saḥ"},{"type":"verse","number":"5","sanskrit":"उद्धूयमानवातो यःशब्द वद् दुःखितो नरः उच्चैः श्वसिति सन्नद्धो मत्तर्षभ इवानिशम्","text":"uddhūyamānavāto yaḥśabda vad duḥkhito naraḥ uccaiḥ śvasiti sannaddho mattarṣabha ivāniśam"},{"type":"verse","number":"6","sanskrit":"प्रनष्टज्ञानविज्ञानस्तथा विभ्रान्तलोचनः विवृताक्ष्याननो बद्धमूत्रवर्चा विशीर्णवाक्","text":"pranaṣṭajñānavijñānastathā vibhrāntalocanaḥ vivṛtākṣyānano baddhamūtravarcā viśīrṇavāk"},{"type":"verse","number":"7","sanskrit":"दीनस्य श्वसितञ्चास्य दूराद्विज्ञायते भृशम् महाश्वासोपसृष्टस्तु क्षिप्रमेव विपद्यते","text":"dīnasya śvasitañcāsya dūrādvijñāyate bhṛśam mahāśvāsopasṛṣṭastu kṣiprameva vipadyate"},{"type":"verse","number":"8","sanskrit":"ऊर्ध्वं श्वसिति योऽत्यर्थं न च प्रत्याहरत्यधः श्लेष्मावृतमुखस्रोतः क्रुद्धगन्धवहार्दितः","text":"ūrdhvaṃ śvasiti yo'tyarthaṃ na ca pratyāharatyadhaḥ śleṣmāvṛtamukhasrotaḥ kruddhagandhavahārditaḥ"},{"type":"verse","number":"9","sanskrit":"ऊर्ध्वदृष्टिर्विपश्यंस्तु विभ्रान्ताक्ष इतस्ततः प्रमुह्यन्वेदनाऽत्तश्च शुष्कास्योऽरतिपीडितः","text":"ūrdhvadṛṣṭirvipaśyaṃstu vibhrāntākṣa itastataḥ pramuhyanvedanā'ttaśca śuṣkāsyo'ratipīḍitaḥ"},{"type":"verse","number":"10","sanskrit":"ऊर्ध्वश्वासे प्रकुपिते ह्यधःश्वासो निरुद्ध्य्ते मुह्यतस्ताम्यतश्चोर्ध्वश्वासस्तस्य निहन्त्यसून्","text":"ūrdhvaśvāse prakupite hyadhaḥśvāso niruddhyte muhyatastāmyataścordhvaśvāsastasya nihantyasūn"},{"type":"verse","number":"11","sanskrit":"यस्तु श्वसिति विच्छिनं सर्वप्राणेन पीडितः न वा श्वसिति दुःखार्त्तो मर्मच्छेदरुजाऽदितः","text":"yastu śvasiti vicchinaṃ sarvaprāṇena pīḍitaḥ na vā śvasiti duḥkhārtto marmacchedarujā'ditaḥ"},{"type":"verse","number":"12","sanskrit":"आनाहस्वेदमूर्च्छाऽत्तो दह्यमानेन वस्तिना विप्लुताक्षः परिक्षीणः श्वसन् रक्तैकलोचनः","text":"ānāhasvedamūrcchā'tto dahyamānena vastinā viplutākṣaḥ parikṣīṇaḥ śvasan raktaikalocanaḥ"},{"type":"verse","number":"13","sanskrit":"विचेताः परिशुष्कास्यो विवर्णः प्रलपन्नरः छिन्नश्वासेन विच्छिन्नः स शीघ्रं विजहात्यसून्","text":"vicetāḥ pariśuṣkāsyo vivarṇaḥ pralapannaraḥ chinnaśvāsena vicchinnaḥ sa śīghraṃ vijahātyasūn"},{"type":"verse","number":"14","sanskrit":"प्रतिलोमो यदा वायुः स्रोतांसि प्रतिपद्यते ग्रीवां शिरश्च सङ्गृह्य श्लेष्माणं समुदीर्य च","text":"pratilomo yadā vāyuḥ srotāṃsi pratipadyate grīvāṃ śiraśca saṅgṛhya śleṣmāṇaṃ samudīrya ca"},{"type":"verse","number":"15","sanskrit":"करोति पीनसं तेन कण्ठे घुर्घुरकं तथा अतीव तीव्रवेगञ्च श्वासं प्राणप्रपीडकम्","text":"karoti pīnasaṃ tena kaṇṭhe ghurghurakaṃ tathā atīva tīvravegañca śvāsaṃ prāṇaprapīḍakam"},{"type":"verse","number":"16","sanskrit":"प्रताम्यति स वेगेन तृष्यते सन्निरुध्यते प्रमोहं कासमानश्च स गच्छति मुहुर्मुहुः","text":"pratāmyati sa vegena tṛṣyate sannirudhyate pramohaṃ kāsamānaśca sa gacchati muhurmuhuḥ"},{"type":"verse","number":"17","sanskrit":"श्लेष्मण्यमुच्यमाने तु भृशं भवति दुःखितः तस्यैव च विमोक्षान्ते मुहूर्त्तं लभते सुखम्","text":"śleṣmaṇyamucyamāne tu bhṛśaṃ bhavati duḥkhitaḥ tasyaiva ca vimokṣānte muhūrttaṃ labhate sukham"},{"type":"verse","number":"18","sanskrit":"तथाऽस्योद्ध्वंसते कण्ठः कृच्छ्राच्छक्नोति भषितुम् न चापि लभते निद्रां शयानः श्वासपीडितः","text":"tathā'syoddhvaṃsate kaṇṭhaḥ kṛcchrācchaknoti bhaṣitum na cāpi labhate nidrāṃ śayānaḥ śvāsapīḍitaḥ"},{"type":"verse","number":"19","sanskrit":"पार्श्वे तस्यावगृह्णाति शयानस्य समीरणः आसीनो लभते सौख्यमुष्णञ्चैवाभिनन्दति","text":"pārśve tasyāvagṛhṇāti śayānasya samīraṇaḥ āsīno labhate saukhyamuṣṇañcaivābhinandati"},{"type":"verse","number":"20","sanskrit":"उच्छ्रिताक्षो ललाटेन स्विद्यता भृशमर्त्तिमान् विशुष्कास्यो मुहुःश्वासो मुहुश्चैवावधम्यते","text":"ucchritākṣo lalāṭena svidyatā bhṛśamarttimān viśuṣkāsyo muhuḥśvāso muhuścaivāvadhamyate"},{"type":"verse","number":"21","sanskrit":"मेघाम्बुशीतप्राग्वातैः श्लेष्मलैश्च विवर्द्धते स याप्यस्तमकः श्वासः साध्यो वा स्यान्नवोत्थितः","text":"meghāmbuśītaprāgvātaiḥ śleṣmalaiśca vivarddhate sa yāpyastamakaḥ śvāsaḥ sādhyo vā syānnavotthitaḥ"},{"type":"verse","number":"22","sanskrit":"ज्वरमूर्च्छापरीतञ्च विद्यात्प्रतमकं तु तम्","text":"jvaramūrcchāparītañca vidyātpratamakaṃ tu tam"},{"type":"verse","number":"23","sanskrit":"उदावर्त्तरजोऽजीर्णक्लिन्नकायनिरोधजः तमसा वर्द्धतेऽत्यर्थं शीतलैश्च प्रशाम्यति मज्जतस्तमसीवास्य विद्यात्प्रतमकन्तु तम्","text":"udāvarttarajo'jīrṇaklinnakāyanirodhajaḥ tamasā varddhate'tyarthaṃ śītalaiśca praśāmyati majjatastamasīvāsya vidyātpratamakantu tam"},{"type":"verse","number":"24","sanskrit":"रुक्षायासोद्भवः कोष्ठे क्षुद्रो वात उदीरयन् क्षुद्र श्वासो न सोऽत्यर्थं दुःखेनाङ्गप्रबाधकः","text":"rukṣāyāsodbhavaḥ koṣṭhe kṣudro vāta udīrayan kṣudra śvāso na so'tyarthaṃ duḥkhenāṅgaprabādhakaḥ"},{"type":"verse","number":"25","sanskrit":"हिनस्ति न च गात्राणि न च दुःखो यथेतरे न च भोजनपानानां निरुणद्ध्युचितां गतिम्","text":"hinasti na ca gātrāṇi na ca duḥkho yathetare na ca bhojanapānānāṃ niruṇaddhyucitāṃ gatim"},{"type":"verse","number":"26","sanskrit":"नेन्द्रि याणां व्यथाञ्चापिकाञ्चिदुत्पादयेद्रुजम् स साध्य उक्तो बलिनः सर्वे चाव्यक्तलक्षणाः","text":"nendri yāṇāṃ vyathāñcāpikāñcidutpādayedrujam sa sādhya ukto balinaḥ sarve cāvyaktalakṣaṇāḥ"},{"type":"verse","number":"27","sanskrit":"क्षुद्रः साध्यतमस्तेषां तमकः कृच्छ्र उच्यते त्रयः श्वासा न सिध्यन्ति तमको दुर्बलस्य च","text":"kṣudraḥ sādhyatamasteṣāṃ tamakaḥ kṛcchra ucyate trayaḥ śvāsā na sidhyanti tamako durbalasya ca"},{"type":"verse","number":"28","sanskrit":"कामं प्राणहरा रोगा बहवो न तु ते तथा यथा श्वासश्च हिक्का च हरतः प्राणमाशु वै","text":"kāmaṃ prāṇaharā rogā bahavo na tu te tathā yathā śvāsaśca hikkā ca harataḥ prāṇamāśu vai"},{"type":"verse","number":"29","sanskrit":"श्वासहिक्कातुरं प्रायः स्निग्धैः स्वेदैरुपाचरेत् युक्तैर्लवणतैलाभ्यां तैरस्य ग्रन्थितः कफः","text":"śvāsahikkāturaṃ prāyaḥ snigdhaiḥ svedairupācaret yuktairlavaṇatailābhyāṃ tairasya granthitaḥ kaphaḥ"},{"type":"verse","number":"30","sanskrit":"श्वासो विलयमायाति मारुतश्चोपशाम्यति स्विन्नं ज्ञात्वा ततश्चैनं भोजयेच्च रसौदनम्","text":"śvāso vilayamāyāti mārutaścopaśāmyati svinnaṃ jñātvā tataścainaṃ bhojayecca rasaudanam"},{"type":"verse","number":"31","sanskrit":"स्वरसं शृङ्गवेरस्य माक्षिकेण समन्वितम् पाययेच्छ्वासकासघ्नं प्रतिश्यायकफापहम्","text":"svarasaṃ śṛṅgaverasya mākṣikeṇa samanvitam pāyayecchvāsakāsaghnaṃ pratiśyāyakaphāpaham"},{"type":"verse","number":"32","sanskrit":"प्रस्थं बिभीतकानामस्थि विना साधयेदजामूत्रे अयमवलेहो लीढो मधुसहितः श्वासकासघ्नः","text":"prasthaṃ bibhītakānāmasthi vinā sādhayedajāmūtre ayamavaleho līḍho madhusahitaḥ śvāsakāsaghnaḥ"},{"type":"verse","number":"33","sanskrit":"देवदारुबलामांसीः पिष्ट्वा वर्त्तिं प्रकल्पयेत् तां घृताक्तां पिबेद्धूमं श्वासं हन्ति सुदारुणम्","text":"devadārubalāmāṃsīḥ piṣṭvā varttiṃ prakalpayet tāṃ ghṛtāktāṃ pibeddhūmaṃ śvāsaṃ hanti sudāruṇam"},{"type":"verse","number":"34","sanskrit":"दशमूलीशटीरास्नापिप्पलीविश्वपौष्करैः शृङ्गीतामलकीभार्गीगुडूचीनागराग्निभिः","text":"daśamūlīśaṭīrāsnāpippalīviśvapauṣkaraiḥ śṛṅgītāmalakībhārgīguḍūcīnāgarāgnibhiḥ"},{"type":"verse","number":"35","sanskrit":"यवागूं विधिना सिद्धां कषायं वा पिबेन्नरः श्वासहृद्ग्रहपार्श्वार्त्तिहिक्काकासप्रशान्तये","text":"yavāgūṃ vidhinā siddhāṃ kaṣāyaṃ vā pibennaraḥ śvāsahṛdgrahapārśvārttihikkākāsapraśāntaye"},{"type":"verse","number":"36","sanskrit":"दशमूलस्य वा क्वाथः षौष्करेणावचूर्णितः श्वासकासप्रशमनः पार्श्वशूलनिवारणः","text":"daśamūlasya vā kvāthaḥ ṣauṣkareṇāvacūrṇitaḥ śvāsakāsapraśamanaḥ pārśvaśūlanivāraṇaḥ"},{"type":"verse","number":"37","sanskrit":"रम्भाकुन्दशिरीषाणां कुसुमं पिप्पलीयुतम् पिष्ट्वा तण्डुलतोयेन पीत्वा श्वासमपोहति","text":"rambhākundaśirīṣāṇāṃ kusumaṃ pippalīyutam piṣṭvā taṇḍulatoyena pītvā śvāsamapohati"},{"type":"verse","number":"38","sanskrit":"शृङ्गीमहौषधकणाघनपौष्कराणां चूर्णं शटीमरिचयोश्च सिताविमिश्रम् क्वाथेन पीतममृतावृषपञ्चमूल्याः श्वासं त्र्यहेण विनिहन्ति हि घोररूपम्","text":"śṛṅgīmahauṣadhakaṇāghanapauṣkarāṇāṃ cūrṇaṃ śaṭīmaricayośca sitāvimiśram kvāthena pītamamṛtāvṛṣapañcamūlyāḥ śvāsaṃ tryaheṇa vinihanti hi ghorarūpam"},{"type":"verse","number":"39","sanskrit":"पञ्चमूली तु सामान्या पित्ते योज्या कनीयसी महती मारुते देया सैव देया कफाधिके","text":"pañcamūlī tu sāmānyā pitte yojyā kanīyasī mahatī mārute deyā saiva deyā kaphādhike"},{"type":"verse","number":"40","sanskrit":"कूष्माण्डकशिफाचूर्णं पीतं कोष्णेन वारिणा शीघ्रं शमयति श्वासं कासञ्चापि सुदारुणम्","text":"kūṣmāṇḍakaśiphācūrṇaṃ pītaṃ koṣṇena vāriṇā śīghraṃ śamayati śvāsaṃ kāsañcāpi sudāruṇam"},{"type":"verse","number":"41","sanskrit":"हरिद्रां मरिचं द्रा क्षां कणां रास्नां शटीं गुडम् कटुतैलं लिहन्हन्याच्छ्वासान् प्राणहरानपि","text":"haridrāṃ maricaṃ drā kṣāṃ kaṇāṃ rāsnāṃ śaṭīṃ guḍam kaṭutailaṃ lihanhanyācchvāsān prāṇaharānapi"},{"type":"verse","number":"42","sanskrit":"शतं सङ्गृह्य भार्ग्यास्तु दशमूल्यास्तथा शतम् शतं हरीतकीनाञ्च पचेत्तोये चतुर्गुणे","text":"śataṃ saṅgṛhya bhārgyāstu daśamūlyāstathā śatam śataṃ harītakīnāñca pacettoye caturguṇe"},{"type":"verse","number":"43","sanskrit":"पादावशेषे तस्मिंस्तु रसे वस्त्रनिपीडिते आलोड्य च तुलां पूतां गुडस्य त्वभयास्ततः","text":"pādāvaśeṣe tasmiṃstu rase vastranipīḍite āloḍya ca tulāṃ pūtāṃ guḍasya tvabhayāstataḥ"},{"type":"verse","number":"44","sanskrit":"पुनः पचेत्तु मृद्वग्नौ यावल्लेहत्वमेति तत् शीते च मधुनस्तत्र षट्पलानि विनिक्षिपेत्","text":"punaḥ pacettu mṛdvagnau yāvallehatvameti tat śīte ca madhunastatra ṣaṭpalāni vinikṣipet"},{"type":"verse","number":"45","sanskrit":"त्रिकटुं त्रिसुगन्धञ्च पलमात्रं पृथक् पृथक् यवक्षारं कर्षयुग्मं सञ्चूर्ण्य प्रक्षिपेत्ततः","text":"trikaṭuṃ trisugandhañca palamātraṃ pṛthak pṛthak yavakṣāraṃ karṣayugmaṃ sañcūrṇya prakṣipettataḥ"},{"type":"verse","number":"46","sanskrit":"भक्षयेदभयामेकां लेहस्यार्द्धपलं तथा श्वासं सुदारुणं हन्ति कासं पञ्चविधं तथा","text":"bhakṣayedabhayāmekāṃ lehasyārddhapalaṃ tathā śvāsaṃ sudāruṇaṃ hanti kāsaṃ pañcavidhaṃ tathā"},{"type":"verse","number":"47","sanskrit":"अर्शांस्यरोचकं गुल्मं शकृद्भेदं क्षयं तथा स्वरवर्णप्रदो ह्येष जठराग्नेश्च दीपनः नाम्ना भार्गीगुडः ख्यातो भिषग्भिः सकलैर्मतः","text":"arśāṃsyarocakaṃ gulmaṃ śakṛdbhedaṃ kṣayaṃ tathā svaravarṇaprado hyeṣa jaṭharāgneśca dīpanaḥ nāmnā bhārgīguḍaḥ khyāto bhiṣagbhiḥ sakalairmataḥ"},{"type":"verse","number":"48","sanskrit":"अष्टाङ्गचूर्णसंयुक्तं छागक्षीरं प्रयोजयेत् श्वासं कासान्वितं घोरं हन्यादेतन्न संशयः","text":"aṣṭāṅgacūrṇasaṃyuktaṃ chāgakṣīraṃ prayojayet śvāsaṃ kāsānvitaṃ ghoraṃ hanyādetanna saṃśayaḥ"},{"type":"verse","number":"49","sanskrit":"दशमूलरसो देयः श्वासनिर्मूलशान्तये अवश्यंमरणीयो यो जीवेद्वर्षशतं नरः","text":"daśamūlaraso deyaḥ śvāsanirmūlaśāntaye avaśyaṃmaraṇīyo yo jīvedvarṣaśataṃ naraḥ"},{"type":"verse","number":"50","sanskrit":"रसो गन्धो विषञ्चापि टङ्कणञ्च मनः शिला एतानिकर्षमात्राणि मरिचं चाष्टकर्षकम्","text":"raso gandho viṣañcāpi ṭaṅkaṇañca manaḥ śilā etānikarṣamātrāṇi maricaṃ cāṣṭakarṣakam"},{"type":"verse","number":"51","sanskrit":"कटुत्रयं कर्षयुग्मं पृथगत्र विनिक्षिपेत् रसः श्वासकुठारोऽय सर्वश्वासनिवारणः","text":"kaṭutrayaṃ karṣayugmaṃ pṛthagatra vinikṣipet rasaḥ śvāsakuṭhāro'ya sarvaśvāsanivāraṇaḥ"},{"type":"verse","number":"52","sanskrit":"इति चतुर्दशः श्वासाधिकारः समाप्तः १४","text":"iti caturdaśaḥ śvāsādhikāraḥ samāptaḥ 14"}]},{"sthana":"Уттаракханда","number":15,"lang":"sa","content":[{"type":"heading","heading":"Сварабхеда — потеря голоса"},{"type":"verse","number":"1","sanskrit":"अत्युच्चभाषणविषाध्ययनाभिघातसन्दुषणैः प्रकुपिताः पवनादयस्तु स्रोतःसु ते स्वरवहेषु गताः प्रतिष्ठां हन्युः स्वरं भवति चापि हि षड्विधः सः","text":"atyuccabhāṣaṇaviṣādhyayanābhighātasanduṣaṇaiḥ prakupitāḥ pavanādayastu srotaḥsu te svaravaheṣu gatāḥ pratiṣṭhāṃ hanyuḥ svaraṃ bhavati cāpi hi ṣaḍvidhaḥ saḥ"},{"type":"verse","number":"2","sanskrit":"वातेन कृष्णनयनाननमूत्रवर्चा भिन्नं शनैर्वदति गर्दभवत्स्वरञ्च","text":"vātena kṛṣṇanayanānanamūtravarcā bhinnaṃ śanairvadati gardabhavatsvarañca"},{"type":"verse","number":"3","sanskrit":"पित्तेन पीतनयनाननमूत्रवर्चा ब्रूयाद्गलेन स च दाहसमन्वितेन","text":"pittena pītanayanānanamūtravarcā brūyādgalena sa ca dāhasamanvitena"},{"type":"verse","number":"4","sanskrit":"ब्रूयात्कफेन सततं कफरुद्धकण्ठः स्वल्पं शनैर्वदति चापि दिवा विशेषात्","text":"brūyātkaphena satataṃ kapharuddhakaṇṭhaḥ svalpaṃ śanairvadati cāpi divā viśeṣāt"},{"type":"verse","number":"5","sanskrit":"सर्वात्मके भवति सर्वविकारसम्पत्तं चाप्यसाध्यमृषयः स्वरभेदमाहुः","text":"sarvātmake bhavati sarvavikārasampattaṃ cāpyasādhyamṛṣayaḥ svarabhedamāhuḥ"},{"type":"verse","number":"6","sanskrit":"धूम्येत वाक्क्षयकृते क्षयमाप्नुयाच्च स्यादेव चापि गतवाक्परिर्जनीयः","text":"dhūmyeta vākkṣayakṛte kṣayamāpnuyācca syādeva cāpi gatavākparirjanīyaḥ"},{"type":"verse","number":"7","sanskrit":"अन्तर्गलं स्वरमलक्ष्यपदं चिरेण मेदोऽन्वयाद्वदति दिग्धगलस्तृषार्त्तः","text":"antargalaṃ svaramalakṣyapadaṃ cireṇa medo'nvayādvadati digdhagalastṛṣārttaḥ"},{"type":"verse","number":"8","sanskrit":"क्षीणस्य वृद्धस्य कृशस्य चापि चिरोत्थितो यश्च सहोपजातः मेदस्विनः सर्वसमुद्भश्च स्वरामयो नैव स सिद्धिमेति","text":"kṣīṇasya vṛddhasya kṛśasya cāpi cirotthito yaśca sahopajātaḥ medasvinaḥ sarvasamudbhaśca svarāmayo naiva sa siddhimeti"},{"type":"verse","number":"9","sanskrit":"वातादिजनितश्वासकासघ्ना ये प्रकीर्त्तिताः योगास्तानत्र युञ्जीत यथादोषं चिकित्सकः वाते सलवणं तैलं पित्ते सर्पिः समाक्षिकम् कफे सक्षारकटुकं क्षौद्रं कवल इष्यते गले तालुनि जिह्वायां दन्तमूलेषु चाश्रितः तेन निष्कृष्यते श्लेष्मा स्वरश्चाशु प्रसीदति आद्ये कोष्णं जलं पेयं भुक्त्वा घृतरसौदनम् क्षीराम्बुपानं पित्तोत्थे पिबेत्सर्पिरतन्द्रि तः","text":"vātādijanitaśvāsakāsaghnā ye prakīrttitāḥ yogāstānatra yuñjīta yathādoṣaṃ cikitsakaḥ vāte salavaṇaṃ tailaṃ pitte sarpiḥ samākṣikam kaphe sakṣārakaṭukaṃ kṣaudraṃ kavala iṣyate gale tāluni jihvāyāṃ dantamūleṣu cāśritaḥ tena niṣkṛṣyate śleṣmā svaraścāśu prasīdati ādye koṣṇaṃ jalaṃ peyaṃ bhuktvā ghṛtarasaudanam kṣīrāmbupānaṃ pittotthe pibetsarpiratandri taḥ"},{"type":"verse","number":"10","sanskrit":"पिप्पली पिप्पलीमूलं मरिचं विश्वभेषजम् पिबेन्मूत्रेण मतिमान्कफजे स्वरसङ्क्षये","text":"pippalī pippalīmūlaṃ maricaṃ viśvabheṣajam pibenmūtreṇa matimānkaphaje svarasaṅkṣaye"},{"type":"verse","number":"11","sanskrit":"निदिग्धिकातुला ग्राह्या तदर्द्धं ग्रन्थिकस्य तु तदर्द्धं चित्रकस्यापि दशमूलञ्च तत्समम्","text":"nidigdhikātulā grāhyā tadarddhaṃ granthikasya tu tadarddhaṃ citrakasyāpi daśamūlañca tatsamam"},{"type":"verse","number":"12","sanskrit":"जले द्रो णद्वये क्वाथ्यं गृह्णीयादाढकं ततः पूते क्षिपेत्तदर्द्धन्तु पुराणस्य गुडस्य च","text":"jale dro ṇadvaye kvāthyaṃ gṛhṇīyādāḍhakaṃ tataḥ pūte kṣipettadarddhantu purāṇasya guḍasya ca"},{"type":"verse","number":"13","sanskrit":"सर्वमेकत्र कृत्वा तु लेहवत्साधु साधयेत् अष्टौ पलानि पिप्पल्यास्त्रिजातकपलं तथा","text":"sarvamekatra kṛtvā tu lehavatsādhu sādhayet aṣṭau palāni pippalyāstrijātakapalaṃ tathā"},{"type":"verse","number":"14","sanskrit":"मरिचस्य पलं चैकं सर्वमेकत्र चूर्णितम् मधुनः कुडवं दत्वा तदश्नीयाद्यथाऽनलम्","text":"maricasya palaṃ caikaṃ sarvamekatra cūrṇitam madhunaḥ kuḍavaṃ datvā tadaśnīyādyathā'nalam"},{"type":"verse","number":"15","sanskrit":"निदिग्धिकाऽवलेहोऽय भिषग्भिर्मुनिभिर्मतः स्वरभेदहरो मुख्यः प्रतिश्यायहरस्तथा","text":"nidigdhikā'valeho'ya bhiṣagbhirmunibhirmataḥ svarabhedaharo mukhyaḥ pratiśyāyaharastathā"},{"type":"verse","number":"16","sanskrit":"कासश्वासाग्निमान्द्यादीन्गुल्ममेहगलामयान् आनाहमूत्रकृच्छ्राणि हन्याद् ग्रन्थ्यर्बुदानिच","text":"kāsaśvāsāgnimāndyādīngulmamehagalāmayān ānāhamūtrakṛcchrāṇi hanyād granthyarbudānica"},{"type":"verse","number":"17","sanskrit":"मृगनाभिः ससूक्ष्मैला लवङ्गकुसुमानि च त्वक्क्षीरी चेति लेहोऽय मधुसर्पिः समायुतः वाक्स्तम्भमुग्रंजयतिस्वरभ्रंशसमन्वितम्","text":"mṛganābhiḥ sasūkṣmailā lavaṅgakusumāni ca tvakkṣīrī ceti leho'ya madhusarpiḥ samāyutaḥ vākstambhamugraṃjayatisvarabhraṃśasamanvitam"},{"type":"verse","number":"18","sanskrit":"ब्राह्मी वचाऽभया वासा पिप्पली मधुसंयुता अस्य प्रयोगात्सप्ताहात्किन्नरैः सह गीयते","text":"brāhmī vacā'bhayā vāsā pippalī madhusaṃyutā asya prayogātsaptāhātkinnaraiḥ saha gīyate"},{"type":"verse","number":"19","sanskrit":"इति पञ्चदशः स्वरभेदाधिकारः १५","text":"iti pañcadaśaḥ svarabhedādhikāraḥ 15"}]},{"sthana":"Уттаракханда","number":16,"lang":"sa","content":[{"type":"heading","heading":"Арочака — потеря аппетита"},{"type":"verse","number":"1","sanskrit":"वातादिभिः शोकभयातिलोभक्रोधैर्मनोघ्नाशनरूपगन्धैः अरोचकाः स्युः परिहृष्टदन्तः कषायवक्त्रश्च मतोऽनिलेन","text":"vātādibhiḥ śokabhayātilobhakrodhairmanoghnāśanarūpagandhaiḥ arocakāḥ syuḥ parihṛṣṭadantaḥ kaṣāyavaktraśca mato'nilena"},{"type":"verse","number":"2","sanskrit":"कट्वम्लमुष्णं विरसञ्च पूति पित्तेन विद्याल्लवणञ्च वक्त्रम् माधुर्यपैच्छिल्यगुरुत्वशैत्यस्निग्धत्वदौर्गन्ध्ययुतं कफेन","text":"kaṭvamlamuṣṇaṃ virasañca pūti pittena vidyāllavaṇañca vaktram mādhuryapaicchilyagurutvaśaityasnigdhatvadaurgandhyayutaṃ kaphena"},{"type":"verse","number":"3","sanskrit":"अरोचकं शोकभयातिलोभक्रोधाद्यहृद्याशुचिगन्धजे स्यात् स्वाभाविकञ्चास्यमथारुचिश्च त्रिदोषजे नैकरसं भवेच्च","text":"arocakaṃ śokabhayātilobhakrodhādyahṛdyāśucigandhaje syāt svābhāvikañcāsyamathāruciśca tridoṣaje naikarasaṃ bhavecca"},{"type":"verse","number":"4","sanskrit":"हृच्छूलपीडनयुतं पवनेन पित्तात्तृड्दाहचोषबहुलं सकफप्रसेकम् श्लेष्मात्मकं बहुरुजं बहुभिश्च विद्याद् वैगुण्यमोहजडताभिरथापरञ्च","text":"hṛcchūlapīḍanayutaṃ pavanena pittāttṛḍdāhacoṣabahulaṃ sakaphaprasekam śleṣmātmakaṃ bahurujaṃ bahubhiśca vidyād vaiguṇyamohajaḍatābhirathāparañca"},{"type":"verse","number":"5","sanskrit":"प्रक्षिप्तन्तु मुखे चान्नं यत्र नास्वाद्यते नरः अरोचकः स विज्ञेयो भक्तद्वेषमतः शृणु","text":"prakṣiptantu mukhe cānnaṃ yatra nāsvādyate naraḥ arocakaḥ sa vijñeyo bhaktadveṣamataḥ śṛṇu"},{"type":"verse","number":"6","sanskrit":"चिन्तयित्वा तु मनसा दृष्ट्वा स्पृष्ट्वा तु भोजनम् द्वेषमायाति यो जन्तुर्भक्तद्वेषः स उच्यते","text":"cintayitvā tu manasā dṛṣṭvā spṛṣṭvā tu bhojanam dveṣamāyāti yo janturbhaktadveṣaḥ sa ucyate"},{"type":"verse","number":"7","sanskrit":"कुपितस्य भयार्त्तस्य तथा भक्तविरोधिनः यत्र नान्नेभवेच्छ्रद्धा सोऽभक्तच्छन्द उच्यते","text":"kupitasya bhayārttasya tathā bhaktavirodhinaḥ yatra nānnebhavecchraddhā so'bhaktacchanda ucyate"},{"type":"verse","number":"8","sanskrit":"भोजनाग्रे सदा पथ्यं लवणार्द्र कभक्षणम् रोचनं दीपनं वह्नेर्जिह्वाकण्ठविशोधनम्","text":"bhojanāgre sadā pathyaṃ lavaṇārdra kabhakṣaṇam rocanaṃ dīpanaṃ vahnerjihvākaṇṭhaviśodhanam"},{"type":"verse","number":"9","sanskrit":"शृङ्गबेररसंवाऽपि मधुना सह योजयेत् अरुचिश्वासकासघ्नं प्रतिश्यायकफापहम्","text":"śṛṅgaberarasaṃvā'pi madhunā saha yojayet aruciśvāsakāsaghnaṃ pratiśyāyakaphāpaham"},{"type":"verse","number":"10","sanskrit":"पक्वाम्लीका सिता शीतवारिणा वस्त्रगालिता एलालवङ्गकर्पूरमरिचैरवधूलिता","text":"pakvāmlīkā sitā śītavāriṇā vastragālitā elālavaṅgakarpūramaricairavadhūlitā"},{"type":"verse","number":"11","sanskrit":"पानकस्यास्य गण्डूषं धारयित्वा मुखे मुहुः अरुचिं नाशयत्येव पित्तं प्रशमयेत्तथा","text":"pānakasyāsya gaṇḍūṣaṃ dhārayitvā mukhe muhuḥ aruciṃ nāśayatyeva pittaṃ praśamayettathā"},{"type":"verse","number":"12","sanskrit":"राजिकाजीरकौ भृष्टौ भृष्टं हिङ्गु सनागरम् सैन्धवं दधि गोः सर्वं वस्त्रपूतं प्रकल्पयेत्","text":"rājikājīrakau bhṛṣṭau bhṛṣṭaṃ hiṅgu sanāgaram saindhavaṃ dadhi goḥ sarvaṃ vastrapūtaṃ prakalpayet"},{"type":"verse","number":"13","sanskrit":"तावन्मात्रं क्षिपेत्तत्र यथा स्याद्रुचिरुत्तमा तक्रमेतद्भवेत्सद्यो रोचनं वह्निवर्द्धनम्","text":"tāvanmātraṃ kṣipettatra yathā syādruciruttamā takrametadbhavetsadyo rocanaṃ vahnivarddhanam"},{"type":"verse","number":"14","sanskrit":"सम्यगावर्त्तितं दुग्धं निबद्धं दधि माहिषम् एकीकृत्य पटे घृष्टं शुभ्रशर्करया समम्","text":"samyagāvarttitaṃ dugdhaṃ nibaddhaṃ dadhi māhiṣam ekīkṛtya paṭe ghṛṣṭaṃ śubhraśarkarayā samam"},{"type":"verse","number":"15","sanskrit":"एलालवङ्गकर्पूरमरिचैश्च समन्वितम् नाम्ना शिखरिणी कुर्याद्रुचिं सकलवल्लभाम्","text":"elālavaṅgakarpūramaricaiśca samanvitam nāmnā śikhariṇī kuryādruciṃ sakalavallabhām"},{"type":"verse","number":"16","sanskrit":"द्वे पले दाडिमाम्लस्य खण्डं दद्यात्पलत्रयम् त्रिसुगन्धि पलं चैकं चूर्णमेकत्र कारयेत्","text":"dve pale dāḍimāmlasya khaṇḍaṃ dadyātpalatrayam trisugandhi palaṃ caikaṃ cūrṇamekatra kārayet"},{"type":"verse","number":"17","sanskrit":"तच्चूर्णं मात्रया भुक्तमरोचकहरं परम् दीपनं पाचनं च स्यात् पीनसज्वरकासजित्","text":"taccūrṇaṃ mātrayā bhuktamarocakaharaṃ param dīpanaṃ pācanaṃ ca syāt pīnasajvarakāsajit"},{"type":"verse","number":"18","sanskrit":"लवङ्गकङ्कोलमुशीरचन्दनं नतं सनीलोत्पलकृष्णजीरकम् जलं सकृष्णागुरुभृङ्गकेशरं कणा च विश्वा नलदं सहेलया","text":"lavaṅgakaṅkolamuśīracandanaṃ nataṃ sanīlotpalakṛṣṇajīrakam jalaṃ sakṛṣṇāgurubhṛṅgakeśaraṃ kaṇā ca viśvā naladaṃ sahelayā"},{"type":"verse","number":"19","sanskrit":"तुषारजातीफलवंशरोचनाः सिताऽद्धभागाः सकलं विचूर्णितम् सुरोचनं तर्पणमग्निदीपनं बलप्रदं वश्यतमं त्रिदोषजित्","text":"tuṣārajātīphalavaṃśarocanāḥ sitā'ddhabhāgāḥ sakalaṃ vicūrṇitam surocanaṃ tarpaṇamagnidīpanaṃ balapradaṃ vaśyatamaṃ tridoṣajit"},{"type":"verse","number":"20","sanskrit":"उरोविबन्धं तमकं गलग्रहं सकासहिक्काऽरुचियक्ष्मपीनसम् ग्रहण्यतीसारमुरःक्षतं नृणां तथा प्रमेहान्निखिलान्निहन्ति च","text":"urovibandhaṃ tamakaṃ galagrahaṃ sakāsahikkā'ruciyakṣmapīnasam grahaṇyatīsāramuraḥkṣataṃ nṛṇāṃ tathā pramehānnikhilānnihanti ca"},{"type":"verse","number":"21","sanskrit":"यवानी दाडिमं शुण्ठी तिन्तिडीकाम्लवेतसैः बदराम्लञ्च कुर्वीत चतुःशाणमितानि च सार्द्धद्विशाणं मरिचं पिप्पली दशशाणिका","text":"yavānī dāḍimaṃ śuṇṭhī tintiḍīkāmlavetasaiḥ badarāmlañca kurvīta catuḥśāṇamitāni ca sārddhadviśāṇaṃ maricaṃ pippalī daśaśāṇikā"},{"type":"verse","number":"22","sanskrit":"त्वक्सौवर्चलधान्याकजीरकं द्विद्विशाणिकम् चतुःषष्टिमितैः शाणैः शर्करामत्र योजयेत्","text":"tvaksauvarcaladhānyākajīrakaṃ dvidviśāṇikam catuḥṣaṣṭimitaiḥ śāṇaiḥ śarkarāmatra yojayet"},{"type":"verse","number":"23","sanskrit":"चूर्णितं सर्वमेकत्र यवानीखाण्डवाभिधम् चूर्णं जयेत्पाण्डुरोगं हृद्रो गं ग्रहणीज्वरम्","text":"cūrṇitaṃ sarvamekatra yavānīkhāṇḍavābhidham cūrṇaṃ jayetpāṇḍurogaṃ hṛdro gaṃ grahaṇījvaram"},{"type":"verse","number":"24","sanskrit":"छर्दिशोषातिसारांश्च प्लीहानाहविबद्धताम् अरुचिं शूलमन्दाग्निमर्शोजिह्वागलामयान्","text":"chardiśoṣātisārāṃśca plīhānāhavibaddhatām aruciṃ śūlamandāgnimarśojihvāgalāmayān"},{"type":"verse","number":"25","sanskrit":"इति षोडशोऽरोचकाधिकारः समाप्तः १६","text":"iti ṣoḍaśo'rocakādhikāraḥ samāptaḥ 16"}]},{"sthana":"Уттаракханда","number":17,"lang":"sa","content":[{"type":"heading","heading":"Чхарди — рвота"},{"type":"verse","number":"1","sanskrit":"अतिद्र वैरतिस्निग्धै रहृद्यैर्लवणैरपि अकाले चातिमात्रैश्च तथासात्म्यैश्च भोजनैः","text":"atidra vairatisnigdhai rahṛdyairlavaṇairapi akāle cātimātraiśca tathāsātmyaiśca bhojanaiḥ"},{"type":"verse","number":"2","sanskrit":"आमाद्भयात्तथोद्वेगाद जीर्णात्क्रिमिदोषतः नार्याश्चापन्नसत्त्वाया स्तथाऽतिद्रुतमश्नतः बीभत्सैर्हेतुभिश्चान्यैर्भुक्तमुत्क्लिश्यते बलात्","text":"āmādbhayāttathodvegāda jīrṇātkrimidoṣataḥ nāryāścāpannasattvāyā stathā'tidrutamaśnataḥ bībhatsairhetubhiścānyairbhuktamutkliśyate balāt"},{"type":"verse","number":"3","sanskrit":"दुष्टदोषैः पृथक्सर्वैर्विभत्सालोकनादिभिः छर्दयः पञ्च विज्ञेयास्तासां लक्षणमुच्यते","text":"duṣṭadoṣaiḥ pṛthaksarvairvibhatsālokanādibhiḥ chardayaḥ pañca vijñeyāstāsāṃ lakṣaṇamucyate"},{"type":"verse","number":"4","sanskrit":"हृल्लासोद्गारसंरोधौ प्रसेको लवणास्यता द्वेषोऽन्नपाने च भृशं वमीनां पूर्वलक्षणम्","text":"hṛllāsodgārasaṃrodhau praseko lavaṇāsyatā dveṣo'nnapāne ca bhṛśaṃ vamīnāṃ pūrvalakṣaṇam"},{"type":"verse","number":"5","sanskrit":"छादयन्नाननं वेगैरर्दयन्नङ्गभञ्जनैः निरुच्यते छर्दिरिति दोषो वक्त्रं प्रधावितः","text":"chādayannānanaṃ vegairardayannaṅgabhañjanaiḥ nirucyate chardiriti doṣo vaktraṃ pradhāvitaḥ"},{"type":"verse","number":"6","sanskrit":"हृत्पार्श्वपीडामुखशोष शीर्षनाभ्यर्त्तिकासस्वरभेदतोदः उद्गारशब्दप्रबलं सफेनं विच्छिन्नकृष्णं तनुकं कषायम्","text":"hṛtpārśvapīḍāmukhaśoṣa śīrṣanābhyarttikāsasvarabhedatodaḥ udgāraśabdaprabalaṃ saphenaṃ vicchinnakṛṣṇaṃ tanukaṃ kaṣāyam"},{"type":"verse","number":"7","sanskrit":"कृच्छ्रेण चाल्पं महता च वेगेनार्त्तोऽनिलाच्छर्दयतीव दुःखम्","text":"kṛcchreṇa cālpaṃ mahatā ca vegenārtto'nilācchardayatīva duḥkham"},{"type":"verse","number":"8","sanskrit":"मूर्च्छापिपासामुखशोष मूर्द्धताल्वक्षिसन्तापतमोभ्रमार्त्तः पीतं भृशोष्णं हरितञ्च तिक्तं धूम्रञ्च पित्तेन वमेत्सदाहम्","text":"mūrcchāpipāsāmukhaśoṣa mūrddhatālvakṣisantāpatamobhramārttaḥ pītaṃ bhṛśoṣṇaṃ haritañca tiktaṃ dhūmrañca pittena vametsadāham"},{"type":"verse","number":"9","sanskrit":"तन्द्रा ऽस्यमाधुर्यकफप्रसेक सन्तोषनिद्रा ऽरुचिगौरवार्त्तः स्निग्धं घनं स्वादु कफाद्धि शुक्लं सलोमहर्षोऽल्परुजं वमेत्तु","text":"tandrā 'syamādhuryakaphapraseka santoṣanidrā 'rucigauravārttaḥ snigdhaṃ ghanaṃ svādu kaphāddhi śuklaṃ salomaharṣo'lparujaṃ vamettu"},{"type":"verse","number":"10","sanskrit":"असात्म्यजा च कम्जाऽमजा च बीभत्सजा दौर्हृदजा च या हि सा पञ्चमी ताञ्च विभावयेच्च दोषोच्छ्रयेणैव यथोक्तमादौ","text":"asātmyajā ca kamjā'majā ca bībhatsajā daurhṛdajā ca yā hi sā pañcamī tāñca vibhāvayecca doṣocchrayeṇaiva yathoktamādau"},{"type":"verse","number":"11","sanskrit":"शूलहृल्लासबहुला कृमिजा च विशेषतः कृमिहृद्रो गतुल्येन लक्षणेन च लक्षिता","text":"śūlahṛllāsabahulā kṛmijā ca viśeṣataḥ kṛmihṛdro gatulyena lakṣaṇena ca lakṣitā"},{"type":"verse","number":"12","sanskrit":"कासः श्वासो ज्वरस्तृष्णाहिक्कावैचित्त्यमेव च हृद्रो गस्तमकश्चैव ज्ञेयाश्छर्देरुपद्र वाः","text":"kāsaḥ śvāso jvarastṛṣṇāhikkāvaicittyameva ca hṛdro gastamakaścaiva jñeyāścharderupadra vāḥ"},{"type":"verse","number":"13","sanskrit":"क्षीणस्य या छर्दिरतिप्रसक्ता सोपद्र वा शोणितपूययुक्ता सचन्द्रि कां तां प्रवदन्त्यसाध्यां साध्यां चिकित्सेन्निरुपद्र वां च","text":"kṣīṇasya yā chardiratiprasaktā sopadra vā śoṇitapūyayuktā sacandri kāṃ tāṃ pravadantyasādhyāṃ sādhyāṃ cikitsennirupadra vāṃ ca"},{"type":"verse","number":"14","sanskrit":"आमाशयोत्क्लेशभवा हि सर्वाश्छर्द्यो मता लङ्घनमेव तस्मात् विधीयते मारुतजां विना तु संशोधनं वा कफपित्तहारि","text":"āmāśayotkleśabhavā hi sarvāśchardyo matā laṅghanameva tasmāt vidhīyate mārutajāṃ vinā tu saṃśodhanaṃ vā kaphapittahāri"},{"type":"verse","number":"15","sanskrit":"हन्यात्क्षीरोदकं पीतं छर्दिं पवनसम्भवाम् मुद्गामलकयूषो वा ससर्पिष्कः स सैन्धवः","text":"hanyātkṣīrodakaṃ pītaṃ chardiṃ pavanasambhavām mudgāmalakayūṣo vā sasarpiṣkaḥ sa saindhavaḥ"},{"type":"verse","number":"16","sanskrit":"गुडूचीत्रिफलानिम्बपटोलैः क्वथितं जलम् पिबेन्मधुयुतं तेन छर्दिर्नश्यति पित्तजा","text":"guḍūcītriphalānimbapaṭolaiḥ kvathitaṃ jalam pibenmadhuyutaṃ tena chardirnaśyati pittajā"},{"type":"verse","number":"17","sanskrit":"हरीतकीनां चूर्णन्तुलिह्यान्माक्षिकसंयुतम् अधोमार्गीकृते दोषे छर्दिः शीघ्रं निवर्त्तते","text":"harītakīnāṃ cūrṇantulihyānmākṣikasaṃyutam adhomārgīkṛte doṣe chardiḥ śīghraṃ nivarttate"},{"type":"verse","number":"18","sanskrit":"विडङ्गत्रिफलाविश्वा चूर्णं मधुयुतं जयेत् विडङ्गप्लवशुण्ठीनां चूर्णं वा कफजां वमिम्","text":"viḍaṅgatriphalāviśvā cūrṇaṃ madhuyutaṃ jayet viḍaṅgaplavaśuṇṭhīnāṃ cūrṇaṃ vā kaphajāṃ vamim"},{"type":"verse","number":"19","sanskrit":"पिष्ट्वा धात्रीफलं लाजाञ्छर्कराञ्च पलोन्मिताम् दत्वा मधुपलञ्चापि कुडवं सलिलस्य च वाससा गालितं पीतं हन्ति च्छर्दिं त्रिदोषजाम्","text":"piṣṭvā dhātrīphalaṃ lājāñcharkarāñca palonmitām datvā madhupalañcāpi kuḍavaṃ salilasya ca vāsasā gālitaṃ pītaṃ hanti cchardiṃ tridoṣajām"},{"type":"verse","number":"20","sanskrit":"गुडूच्या रचितं हन्ति हिमं मधु समन्वितम् दुर्निवारामपि च्छर्दिं त्रिदोषजनितां बलात्","text":"guḍūcyā racitaṃ hanti himaṃ madhu samanvitam durnivārāmapi cchardiṃ tridoṣajanitāṃ balāt"},{"type":"verse","number":"21","sanskrit":"एलालवङ्गगजकेशरकोलमज्जालाजाप्रियङ्गुघनचन्दनपिप्पलीनाम् चूर्णानि माक्षिकसितासहितानि लीढ्वा छर्दिं निहन्ति कफमारुतपित्तजाताम्","text":"elālavaṅgagajakeśarakolamajjālājāpriyaṅgughanacandanapippalīnām cūrṇāni mākṣikasitāsahitāni līḍhvā chardiṃ nihanti kaphamārutapittajātām"},{"type":"verse","number":"22","sanskrit":"अश्वत्थवल्कलं शुष्कं दग्धं निर्वापितं जले तज्जलं पानमात्रेण छर्दिं जयति दुर्जयाम्","text":"aśvatthavalkalaṃ śuṣkaṃ dagdhaṃ nirvāpitaṃ jale tajjalaṃ pānamātreṇa chardiṃ jayati durjayām"},{"type":"verse","number":"23","sanskrit":"पथ्यात्रिकटुधान्याक जीरकाणां रजो लिहन् मधुना नाशयेच्छर्दिमरुचिञ्च त्रिदोषजाम्","text":"pathyātrikaṭudhānyāka jīrakāṇāṃ rajo lihan madhunā nāśayecchardimaruciñca tridoṣajām"},{"type":"verse","number":"24","sanskrit":"बिल्वत्वचो गुडूच्या वा क्वाथः क्षौद्रे ण संयुतः छर्दिं त्रिदोषजां हन्ति पर्पटः पित्तजां तथा","text":"bilvatvaco guḍūcyā vā kvāthaḥ kṣaudre ṇa saṃyutaḥ chardiṃ tridoṣajāṃ hanti parpaṭaḥ pittajāṃ tathā"},{"type":"verse","number":"25","sanskrit":"आम्रास्थिबिल्वनिर्यूहः पीतः समधुशर्करः निहन्याच्छर्द्यतीसारं वैश्वानर इवाहुतिम्","text":"āmrāsthibilvaniryūhaḥ pītaḥ samadhuśarkaraḥ nihanyācchardyatīsāraṃ vaiśvānara ivāhutim"},{"type":"verse","number":"26","sanskrit":"जम्ब्वाम्रपल्लवशृतं लाजरजः संयुतं शीतम् शमयति मधुना युक्तं वमिमतिसारं तृषामुग्राम्","text":"jambvāmrapallavaśṛtaṃ lājarajaḥ saṃyutaṃ śītam śamayati madhunā yuktaṃ vamimatisāraṃ tṛṣāmugrām"},{"type":"verse","number":"27","sanskrit":"बीभत्सजां हृद्यतमैरिष्टैर्दौर्हृदजां फलैः लङ्घनैरामजां छर्दिं जयेत्सात्म्यैरसात्म्यजाम्","text":"bībhatsajāṃ hṛdyatamairiṣṭairdaurhṛdajāṃ phalaiḥ laṅghanairāmajāṃ chardiṃ jayetsātmyairasātmyajām"},{"type":"verse","number":"28","sanskrit":"कृमिहृद्रो गवद्धन्याच्छर्दिं कृमिसमुद्भवाम् तत्र तत्र यथादोषं क्रियां कुर्याच्चिकित्सकः","text":"kṛmihṛdro gavaddhanyācchardiṃ kṛmisamudbhavām tatra tatra yathādoṣaṃ kriyāṃ kuryāccikitsakaḥ"},{"type":"verse","number":"29","sanskrit":"सोद्गारायां भृशं छर्द्यां मूर्वाया धान्यमुस्तयोः समधुकाञ्जनं चूर्णं लेहयेन्मधुसंयुतम्","text":"sodgārāyāṃ bhṛśaṃ chardyāṃ mūrvāyā dhānyamustayoḥ samadhukāñjanaṃ cūrṇaṃ lehayenmadhusaṃyutam"},{"type":"verse","number":"30","sanskrit":"सौवर्चलमजाजी च शर्करा मरिचानि च क्षौद्रे ण सहितं लीढं सद्यश्छर्दिनिवारणम्","text":"sauvarcalamajājī ca śarkarā maricāni ca kṣaudre ṇa sahitaṃ līḍhaṃ sadyaśchardinivāraṇam"},{"type":"verse","number":"31","sanskrit":"इति सप्तदशश्छर्द्यधिकारः सम्पूर्णः १७","text":"iti saptadaśaśchardyadhikāraḥ sampūrṇaḥ 17"}]},{"sthana":"Уттаракханда","number":18,"lang":"sa","content":[{"type":"heading","heading":"Тришна — патологическая жажда"},{"type":"verse","number":"1","sanskrit":"भयश्रमाभ्यां बलसङ्क्षयाद्वाऽप्यूर्ध्वं चितं पित्तविवर्द्धनैश्च पित्तं सवातं कुपितं नराणां तालुप्रपन्नं जनयेत्पिपासाम्","text":"bhayaśramābhyāṃ balasaṅkṣayādvā'pyūrdhvaṃ citaṃ pittavivarddhanaiśca pittaṃ savātaṃ kupitaṃ narāṇāṃ tāluprapannaṃ janayetpipāsām"},{"type":"verse","number":"2","sanskrit":"स्रोतःस्वपां वाहिषु दूषितेषु दोषैश्च तृट् सम्भवतीह जन्तोः तिस्रः स्मृतास्ताः क्षतजा चतुर्थी क्षयात्तथाऽन्याऽमसमुद्भवा च भक्तोद्भवा सप्तमिकेति तासां निबोध लिङ्गान्यनुपूर्वशस्तु","text":"srotaḥsvapāṃ vāhiṣu dūṣiteṣu doṣaiśca tṛṭ sambhavatīha jantoḥ tisraḥ smṛtāstāḥ kṣatajā caturthī kṣayāttathā'nyā'masamudbhavā ca bhaktodbhavā saptamiketi tāsāṃ nibodha liṅgānyanupūrvaśastu"},{"type":"verse","number":"3","sanskrit":"ताल्वोष्ठकण्ठास्यविशोषदाहाः सन्तापमोहभ्रमविप्रलापाः सर्वाणि रूपाणि भवन्ति तस्यामुत्पत्तिकाले तु विशेषतो हि","text":"tālvoṣṭhakaṇṭhāsyaviśoṣadāhāḥ santāpamohabhramavipralāpāḥ sarvāṇi rūpāṇi bhavanti tasyāmutpattikāle tu viśeṣato hi"},{"type":"verse","number":"4","sanskrit":"क्षामास्यता मारुतसम्भवायां तोदस्तथा शङ्खशिरःसु चापि स्रोतोनिरोधो विरसञ्च वक्त्रं शीताभिरद्भिश्च विवृद्धिमेति","text":"kṣāmāsyatā mārutasambhavāyāṃ todastathā śaṅkhaśiraḥsu cāpi srotonirodho virasañca vaktraṃ śītābhiradbhiśca vivṛddhimeti"},{"type":"verse","number":"5","sanskrit":"मूर्च्छाऽन्नविद्वेषविलापदाहा रक्तेक्षणत्वं प्रततश्च शोषः शीताभिनन्दा मुखतिक्तता च पित्तात्मिकायां परिधूपनञ्च","text":"mūrcchā'nnavidveṣavilāpadāhā raktekṣaṇatvaṃ pratataśca śoṣaḥ śītābhinandā mukhatiktatā ca pittātmikāyāṃ paridhūpanañca"},{"type":"verse","number":"6","sanskrit":"वाष्पावरोधात् कफसंवृतेऽग्नौ तृष्णा बलासेन भवेन्नरस्य निद्रा गुरुत्वं मधुरास्यता च तयाऽदितः शुष्यति चातिमात्रम्","text":"vāṣpāvarodhāt kaphasaṃvṛte'gnau tṛṣṇā balāsena bhavennarasya nidrā gurutvaṃ madhurāsyatā ca tayā'ditaḥ śuṣyati cātimātram"},{"type":"verse","number":"7","sanskrit":"क्षतस्य रुक्छोणितनिर्गमाभ्यां तृष्णा चतुर्थी क्षतजा मता तु","text":"kṣatasya rukchoṇitanirgamābhyāṃ tṛṣṇā caturthī kṣatajā matā tu"},{"type":"verse","number":"8","sanskrit":"रसक्षयाद्या क्षयसम्भवा सा तयाऽभिभूतस्तु निशादिनेषु पेपीयतेऽम्भ स सुखं न याति तां सन्निपातादिति केचिदाहुः रसक्षयोक्तानि च लक्षणानि तस्यामशेषेण भिषग्व्यवस्येत्","text":"rasakṣayādyā kṣayasambhavā sā tayā'bhibhūtastu niśādineṣu pepīyate'mbha sa sukhaṃ na yāti tāṃ sannipātāditi kecidāhuḥ rasakṣayoktāni ca lakṣaṇāni tasyāmaśeṣeṇa bhiṣagvyavasyet"},{"type":"verse","number":"9","sanskrit":"त्रिदोषलिङ्गाऽमसमुद्भवा च हृच्छूलनिष्ठीवनसादकर्त्री","text":"tridoṣaliṅgā'masamudbhavā ca hṛcchūlaniṣṭhīvanasādakartrī"},{"type":"verse","number":"10","sanskrit":"स्निग्धं तथाऽम्ल लवणञ्च भुक्तं गुर्वन्नमेवाशु तृषां करोति","text":"snigdhaṃ tathā'mla lavaṇañca bhuktaṃ gurvannamevāśu tṛṣāṃ karoti"},{"type":"verse","number":"11","sanskrit":"दीनस्वरः प्रताम्यन्दीनाननहृदयशुष्कगलतालुः भवति खलु सोपसर्गा तृष्णा सा शोषिणी कष्टा","text":"dīnasvaraḥ pratāmyandīnānanahṛdayaśuṣkagalatāluḥ bhavati khalu sopasargā tṛṣṇā sā śoṣiṇī kaṣṭā"},{"type":"verse","number":"12","sanskrit":"ज्वरमोहक्षयकासश्वासाद्युप सृष्टदेहानाम् सर्वास्त्वतिप्रसक्ता रोगकृशानां वमिप्रसक्तानाम् घोरोपद्र वयुक्तास्तृष्णा मरणाय विज्ञेयाः","text":"jvaramohakṣayakāsaśvāsādyupa sṛṣṭadehānām sarvāstvatiprasaktā rogakṛśānāṃ vamiprasaktānām ghoropadra vayuktāstṛṣṇā maraṇāya vijñeyāḥ"},{"type":"verse","number":"13","sanskrit":"वातघ्नमन्नपानं मृदु लघु शीतञ्च वाततृष्णायाम्","text":"vātaghnamannapānaṃ mṛdu laghu śītañca vātatṛṣṇāyām"},{"type":"verse","number":"14","sanskrit":"तृष्णायां पवनोत्थायां सगुडं दधि शस्यते स्वादु तिक्तं द्र वं शीतं पित्ततृष्णाऽपहं परम्","text":"tṛṣṇāyāṃ pavanotthāyāṃ saguḍaṃ dadhi śasyate svādu tiktaṃ dra vaṃ śītaṃ pittatṛṣṇā'pahaṃ param"},{"type":"verse","number":"15","sanskrit":"मुस्तपर्पटकोदीच्यच्छत्राख्यो शीरचन्दनैः शृतं शीतं जलं दद्यात्तृड्दाहज्वरशान्तये","text":"mustaparpaṭakodīcyacchatrākhyo śīracandanaiḥ śṛtaṃ śītaṃ jalaṃ dadyāttṛḍdāhajvaraśāntaye"},{"type":"verse","number":"16","sanskrit":"लाजोदकं मधुयुतं शीतं गुडविमर्दितम् काश्मरीशर्करायुक्तं पिबेत्तृष्णाऽदितो नरः","text":"lājodakaṃ madhuyutaṃ śītaṃ guḍavimarditam kāśmarīśarkarāyuktaṃ pibettṛṣṇā'dito naraḥ"},{"type":"verse","number":"17","sanskrit":"आस्तरणमार्द्र वासः प्रावरणं चार्द्र वासः स्यात् तेन पिपासा शाम्यति दाहश्चोग्रोऽपि देहिनां नियतम्","text":"āstaraṇamārdra vāsaḥ prāvaraṇaṃ cārdra vāsaḥ syāt tena pipāsā śāmyati dāhaścogro'pi dehināṃ niyatam"},{"type":"verse","number":"18","sanskrit":"गोस्तनीक्षुरसक्षीरयष्टी मधुमधूत्पलैः नियतं नासिकापीते तृष्णा शाम्यति दारुणा","text":"gostanīkṣurasakṣīrayaṣṭī madhumadhūtpalaiḥ niyataṃ nāsikāpīte tṛṣṇā śāmyati dāruṇā"},{"type":"verse","number":"19","sanskrit":"वैशद्यं जनयत्यास्ये सन्दधाति मुखे जलम् तृष्णादाहप्रशमनं मधुगण्डूषधारणम्","text":"vaiśadyaṃ janayatyāsye sandadhāti mukhe jalam tṛṣṇādāhapraśamanaṃ madhugaṇḍūṣadhāraṇam"},{"type":"verse","number":"20","sanskrit":"जिह्वातालुगलक्लोमशोषे मूर्ध्नि निधापयेत् केशरं मातुलुङ्गस्य घृतसैन्धवसंयुतम्","text":"jihvātālugalaklomaśoṣe mūrdhni nidhāpayet keśaraṃ mātuluṅgasya ghṛtasaindhavasaṃyutam"},{"type":"verse","number":"21","sanskrit":"दाडिमं बदरं लोध्रं कपित्थं बीजपूरकम् पिष्ट्व्वा मूर्द्धनि लेपस्तु पिपासादाहनाशनः","text":"dāḍimaṃ badaraṃ lodhraṃ kapitthaṃ bījapūrakam piṣṭvvā mūrddhani lepastu pipāsādāhanāśanaḥ"},{"type":"verse","number":"22","sanskrit":"वारि शीतं मधुयुतमाकण्ठाद्वा पिपासितम् पाययेद्वामयेच्चाथ तेन तृष्णा प्रशाम्यति","text":"vāri śītaṃ madhuyutamākaṇṭhādvā pipāsitam pāyayedvāmayeccātha tena tṛṣṇā praśāmyati"},{"type":"verse","number":"23","sanskrit":"प्रातः शर्करयोपेतः क्वाथो धान्याकसम्भवः जयेत्तृष्णां तथा दाहं भवेत्स्रोतोविशोधनम्","text":"prātaḥ śarkarayopetaḥ kvātho dhānyākasambhavaḥ jayettṛṣṇāṃ tathā dāhaṃ bhavetsrotoviśodhanam"},{"type":"verse","number":"24","sanskrit":"आमलं कमलं कुष्ठं लाजाश्च वटरोहकम् एतच्चूर्णस्य मधुना गुटिकां धारयेन्मुखे तृष्णां प्रवृद्धां हन्त्येषा मुखशोषञ्च दारुणम्","text":"āmalaṃ kamalaṃ kuṣṭhaṃ lājāśca vaṭarohakam etaccūrṇasya madhunā guṭikāṃ dhārayenmukhe tṛṣṇāṃ pravṛddhāṃ hantyeṣā mukhaśoṣañca dāruṇam"},{"type":"verse","number":"25","sanskrit":"क्षतोद्भवां रुग्विनिवारणेन जयेद्र सानामसृजश्च पानैः क्षयोत्थितां क्षीरजलं निहन्यान्मांसोदकं वा मधुरोदकं वा","text":"kṣatodbhavāṃ rugvinivāraṇena jayedra sānāmasṛjaśca pānaiḥ kṣayotthitāṃ kṣīrajalaṃ nihanyānmāṃsodakaṃ vā madhurodakaṃ vā"},{"type":"verse","number":"26","sanskrit":"आमोद्भवां बिल्ववचायुतानां जयेत्कषायैरथ दीपनानाम् गुर्वान्नजामुल्लिखनैर्जयेच्च क्षयं विना सर्वकृताञ्च तृष्णाम्","text":"āmodbhavāṃ bilvavacāyutānāṃ jayetkaṣāyairatha dīpanānām gurvānnajāmullikhanairjayecca kṣayaṃ vinā sarvakṛtāñca tṛṣṇām"},{"type":"verse","number":"27","sanskrit":"स्निग्धेऽन्ने भुक्ते या तृष्णा स्यात्तां गुडाम्बुना शमयेत् अतिरोगदुर्बलानां तृष्णां शमयेन्नृणामिहाशु पयः","text":"snigdhe'nne bhukte yā tṛṣṇā syāttāṃ guḍāmbunā śamayet atirogadurbalānāṃ tṛṣṇāṃ śamayennṛṇāmihāśu payaḥ"},{"type":"verse","number":"28","sanskrit":"मूर्च्छाच्छर्दितृषानाह स्त्रीमद्यभृशकर्षिताः पिबेयुः शीतलं तोयं रक्तपित्ते मदात्यये","text":"mūrcchāccharditṛṣānāha strīmadyabhṛśakarṣitāḥ pibeyuḥ śītalaṃ toyaṃ raktapitte madātyaye"},{"type":"verse","number":"29","sanskrit":"सात्म्यान्नपानभेषज्यैस्तृष्णां तस्य जयेत्पुनः तस्यां जितायामन्योऽपि व्याधिःशक्यश्चिकित्सितुम्","text":"sātmyānnapānabheṣajyaistṛṣṇāṃ tasya jayetpunaḥ tasyāṃ jitāyāmanyo'pi vyādhiḥśakyaścikitsitum"},{"type":"verse","number":"30","sanskrit":"तृष्यन् पूर्वामयक्षीणो न लभेत जलं यदि मरणं दीर्घरोगं वा प्राप्नुयात्त्वरितं नरः","text":"tṛṣyan pūrvāmayakṣīṇo na labheta jalaṃ yadi maraṇaṃ dīrgharogaṃ vā prāpnuyāttvaritaṃ naraḥ"},{"type":"verse","number":"31","sanskrit":"तृषितो मोहमायाति मोहात्प्राणान्विमुञ्चति तस्मात्सर्वास्ववस्थासु न क्वचिद्वारि वारयेत्","text":"tṛṣito mohamāyāti mohātprāṇānvimuñcati tasmātsarvāsvavasthāsu na kvacidvāri vārayet"},{"type":"verse","number":"32","sanskrit":"अन्नेनापि विना जन्तुः प्राणान्धारयते चिरम् तोयाभावात्पिपासार्त्तः क्षणात्प्राणैर्विमुच्यते","text":"annenāpi vinā jantuḥ prāṇāndhārayate ciram toyābhāvātpipāsārttaḥ kṣaṇātprāṇairvimucyate"},{"type":"verse","number":"33","sanskrit":"इत्यष्टादशस्तृष्णाऽधिकारः समाप्तः १८","text":"ityaṣṭādaśastṛṣṇā'dhikāraḥ samāptaḥ 18"}]},{"sthana":"Уттаракханда","number":19,"lang":"sa","content":[{"type":"heading","heading":"Мурчха–бхрама — обмороки и головокружение"},{"type":"verse","number":"1","sanskrit":"क्षीणस्य बहुदोषस्य विरुद्धाहारसेविनः वेगाघातादभीघाताद्धीनसत्त्वस्य वा पुनः","text":"kṣīṇasya bahudoṣasya viruddhāhārasevinaḥ vegāghātādabhīghātāddhīnasattvasya vā punaḥ"},{"type":"verse","number":"2","sanskrit":"करणायतनेषूग्रो बाह्येष्वाभ्यन्तरेषु च निविशन्ते यदा दोषास्तदा मूर्च्छन्ति मानवाः","text":"karaṇāyataneṣūgro bāhyeṣvābhyantareṣu ca niviśante yadā doṣāstadā mūrcchanti mānavāḥ"},{"type":"verse","number":"3","sanskrit":"संज्ञावहासु नाडीषु पिहितास्वनिलादिभिः तमोऽभ्युपैति सहसा सुखदुःखव्यपोहकृत्","text":"saṃjñāvahāsu nāḍīṣu pihitāsvanilādibhiḥ tamo'bhyupaiti sahasā sukhaduḥkhavyapohakṛt"},{"type":"verse","number":"4","sanskrit":"सुखदुःव्यपोहाच्च नरः पतति काष्ठवत् मोहो मूर्च्छेति तामाहुः षड्विधा सा प्रकीर्त्तिता","text":"sukhaduḥvyapohācca naraḥ patati kāṣṭhavat moho mūrccheti tāmāhuḥ ṣaḍvidhā sā prakīrttitā"},{"type":"verse","number":"5","sanskrit":"वातादिभिः शोणितेन मद्येन च विषेण च षट्स्वप्येतासु पित्तन्तु प्रभुत्वेनावतिष्ठते","text":"vātādibhiḥ śoṇitena madyena ca viṣeṇa ca ṣaṭsvapyetāsu pittantu prabhutvenāvatiṣṭhate"},{"type":"verse","number":"6","sanskrit":"हृत्पीडा जृम्भणं ग्लानिः संज्ञानाशो बलक्षयः सर्वासां पूर्वरूर्पाणि यथास्वं तां विभावयेत्","text":"hṛtpīḍā jṛmbhaṇaṃ glāniḥ saṃjñānāśo balakṣayaḥ sarvāsāṃ pūrvarūrpāṇi yathāsvaṃ tāṃ vibhāvayet"},{"type":"verse","number":"7","sanskrit":"नीलं वा यदि वा कृष्णमाकाशमथ वाऽरुणम् पश्यंस्तमः प्रविशति शीघ्रञ्च प्रतिबुध्यते","text":"nīlaṃ vā yadi vā kṛṣṇamākāśamatha vā'ruṇam paśyaṃstamaḥ praviśati śīghrañca pratibudhyate"},{"type":"verse","number":"8","sanskrit":"वेपथुश्चाङ्गमर्दश्च प्रपीडा हृदयस्य च कार्श्यं श्यावारुणा च्छाया मूर्च्छाये वातसम्भवे","text":"vepathuścāṅgamardaśca prapīḍā hṛdayasya ca kārśyaṃ śyāvāruṇā cchāyā mūrcchāye vātasambhave"},{"type":"verse","number":"9","sanskrit":"रक्तं हरितवर्णं वा वियत्पीतमथापि वा पश्यंस्तमः प्रविशति सस्वेदः प्रतिबुध्यते","text":"raktaṃ haritavarṇaṃ vā viyatpītamathāpi vā paśyaṃstamaḥ praviśati sasvedaḥ pratibudhyate"},{"type":"verse","number":"10","sanskrit":"सपिपासः ससन्तापो रक्तपीताकुलेक्षणः सम्भिन्नवर्चाः पीताभो मूर्च्छाये पित्तसम्भवे","text":"sapipāsaḥ sasantāpo raktapītākulekṣaṇaḥ sambhinnavarcāḥ pītābho mūrcchāye pittasambhave"},{"type":"verse","number":"11","sanskrit":"मेघसङ्काशमाकाशं तमोभिर्वा घनैर्वृतम् पश्यंस्तमः प्रविशति चिराच्च प्रतिबुध्यते","text":"meghasaṅkāśamākāśaṃ tamobhirvā ghanairvṛtam paśyaṃstamaḥ praviśati cirācca pratibudhyate"},{"type":"verse","number":"12","sanskrit":"गुरुभिः प्रावृतैरङ्गैर्यथैवार्द्रेण चर्मणा सप्रसेकःसहृल्लासो मूर्च्छाये कफसम्भवे","text":"gurubhiḥ prāvṛtairaṅgairyathaivārdreṇa carmaṇā saprasekaḥsahṛllāso mūrcchāye kaphasambhave"},{"type":"verse","number":"13","sanskrit":"सर्वाकृतिः सन्निपातादपस्मार इवागतः स जन्तुं पातयत्याशु विना बीभत्सचेष्टितैः","text":"sarvākṛtiḥ sannipātādapasmāra ivāgataḥ sa jantuṃ pātayatyāśu vinā bībhatsaceṣṭitaiḥ"},{"type":"verse","number":"14","sanskrit":"पृथिव्यम्भस्तमोरूपं रक्तगन्धस्तदन्वयः तस्माद्र क्तस्य गन्धेन मूर्च्छन्ति भुवि मानवाः द्र व्यस्वभावमित्येके दृष्ट्वा यदभिमुह्यति","text":"pṛthivyambhastamorūpaṃ raktagandhastadanvayaḥ tasmādra ktasya gandhena mūrcchanti bhuvi mānavāḥ dra vyasvabhāvamityeke dṛṣṭvā yadabhimuhyati"},{"type":"verse","number":"15","sanskrit":"स्तब्धाङ्गदृष्टिस्त्वसृजा गूढोच्छ्वासश्च मूर्च्छितः","text":"stabdhāṅgadṛṣṭistvasṛjā gūḍhocchvāsaśca mūrcchitaḥ"},{"type":"verse","number":"16","sanskrit":"गुणास्तीव्रतरत्वेन स्थितास्तु विषमद्ययोः त एव तस्मात्ताभ्यान्तु मोहौ स्यातां यथेरितौ","text":"guṇāstīvrataratvena sthitāstu viṣamadyayoḥ ta eva tasmāttābhyāntu mohau syātāṃ yatheritau"},{"type":"verse","number":"17","sanskrit":"मद्येन प्रलपञ्छेते नष्टविभ्रान्तमानसः गात्राणि विक्षिपन्भूमौ जरां यावन्न याति तत्","text":"madyena pralapañchete naṣṭavibhrāntamānasaḥ gātrāṇi vikṣipanbhūmau jarāṃ yāvanna yāti tat"},{"type":"verse","number":"18","sanskrit":"वेपथुस्वप्नतृष्णाः स्युस्तमश्च विषमूर्च्छिते वेदितव्यं तीव्रतरं ययास्वं विषलक्षणैः","text":"vepathusvapnatṛṣṇāḥ syustamaśca viṣamūrcchite veditavyaṃ tīvrataraṃ yayāsvaṃ viṣalakṣaṇaiḥ"},{"type":"verse","number":"19","sanskrit":"मूर्च्छा पित्ततमःप्राया रजःपित्तानिलाद् भ्रमः तमोवातकफात्तन्द्रा निद्रा श्लेष्मतमोभवा","text":"mūrcchā pittatamaḥprāyā rajaḥpittānilād bhramaḥ tamovātakaphāttandrā nidrā śleṣmatamobhavā"},{"type":"verse","number":"20","sanskrit":"इन्द्रि यार्थेष्वसंवित्तिर्गौरवं जृम्भणं क्लमः निद्रा ऽत्तस्येव यस्येहा तस्य तन्द्रां विनिर्दिशेत्","text":"indri yārtheṣvasaṃvittirgauravaṃ jṛmbhaṇaṃ klamaḥ nidrā 'ttasyeva yasyehā tasya tandrāṃ vinirdiśet"},{"type":"verse","number":"21","sanskrit":"योऽनायासः श्रमो देहे प्रवृद्धः श्वाससङ्गतः क्लमः स इति विज्ञेय इन्द्रि यार्थप्रबाधकः","text":"yo'nāyāsaḥ śramo dehe pravṛddhaḥ śvāsasaṅgataḥ klamaḥ sa iti vijñeya indri yārthaprabādhakaḥ"},{"type":"verse","number":"22","sanskrit":"यदा तु मनसि क्लान्ते कर्मात्मानः क्लमान्विताः विषयेभ्यो निवर्त्तन्ते तदा स्वपिति मानवः","text":"yadā tu manasi klānte karmātmānaḥ klamānvitāḥ viṣayebhyo nivarttante tadā svapiti mānavaḥ"},{"type":"verse","number":"23","sanskrit":"वाग्देहमनसां चेष्टामाक्षिप्यातिबला मलाः संन्यस्यन्त्यबलं जन्तुं प्राणायतनमाश्रिताः","text":"vāgdehamanasāṃ ceṣṭāmākṣipyātibalā malāḥ saṃnyasyantyabalaṃ jantuṃ prāṇāyatanamāśritāḥ"},{"type":"verse","number":"24","sanskrit":"स ना संन्याससंन्यस्तः काष्ठीभूतो मृतोपमः प्राणैर्विमुच्यते शीघ्रं मुक्त्वा सद्यः फलां क्रियाम्","text":"sa nā saṃnyāsasaṃnyastaḥ kāṣṭhībhūto mṛtopamaḥ prāṇairvimucyate śīghraṃ muktvā sadyaḥ phalāṃ kriyām"},{"type":"verse","number":"25","sanskrit":"दोषेषु मदमूर्च्छाया गतवेगेषु देहिनः स्वयमप्युपशाम्यन्ति संन्यासो नौषधैर्विना","text":"doṣeṣu madamūrcchāyā gatavegeṣu dehinaḥ svayamapyupaśāmyanti saṃnyāso nauṣadhairvinā"},{"type":"verse","number":"26","sanskrit":"सेकावगाहा मणयःसहाराः शीताः प्रदेहा व्यजनानिलाश्च शीतानि पानानि च गन्धवन्ति सर्वासु मूर्च्छास्वनिवारितानि","text":"sekāvagāhā maṇayaḥsahārāḥ śītāḥ pradehā vyajanānilāśca śītāni pānāni ca gandhavanti sarvāsu mūrcchāsvanivāritāni"},{"type":"verse","number":"27","sanskrit":"सिद्धानिवर्गे मधुरे पयांसि सदाडिमा जाङ्गलजा रसाश्च तथा यवो लोहितशालयश्च मूर्च्छासु पथ्याः ससतीनमुद्राः","text":"siddhānivarge madhure payāṃsi sadāḍimā jāṅgalajā rasāśca tathā yavo lohitaśālayaśca mūrcchāsu pathyāḥ sasatīnamudrāḥ"},{"type":"verse","number":"28","sanskrit":"कोलमज्जोषणोशीरकेसरं शीतवारिणा पीतं मूर्च्छां जयेल्लीढ्वा कृष्णां वा मधुसंयुताम्","text":"kolamajjoṣaṇośīrakesaraṃ śītavāriṇā pītaṃ mūrcchāṃ jayellīḍhvā kṛṣṇāṃ vā madhusaṃyutām"},{"type":"verse","number":"29","sanskrit":"शीतेन तोयेन बिसं मृणालं कृष्णां च पथ्यां मधुनाऽवलिह्यात् कुर्याच्च नासावदनावरोधं क्षीरं पिबेद्वाऽप्यथ मानुषीणाम्","text":"śītena toyena bisaṃ mṛṇālaṃ kṛṣṇāṃ ca pathyāṃ madhunā'valihyāt kuryācca nāsāvadanāvarodhaṃ kṣīraṃ pibedvā'pyatha mānuṣīṇām"},{"type":"verse","number":"30","sanskrit":"द्रा क्षासितादाडिमलाजवन्ति कह्लारनीलोत्पलपद्मवन्ति पिबेत्कषायाणि च शीतलानि पिबेज्ज्वरं यानि शमं नयन्ति","text":"drā kṣāsitādāḍimalājavanti kahlāranīlotpalapadmavanti pibetkaṣāyāṇi ca śītalāni pibejjvaraṃ yāni śamaṃ nayanti"},{"type":"verse","number":"31","sanskrit":"शिरीषबीजगोमूत्रकृष्णामरिचसैन्धवैः अञ्जनं स्यात्प्रबोधाय सरसोनशिलावचैः","text":"śirīṣabījagomūtrakṛṣṇāmaricasaindhavaiḥ añjanaṃ syātprabodhāya sarasonaśilāvacaiḥ"},{"type":"verse","number":"32","sanskrit":"अञ्जनं सम्यगारब्धं मधुसिन्धुशिलोषणैः प्रमोहद्रो हि भवति भाषितं भिषजां वरैः","text":"añjanaṃ samyagārabdhaṃ madhusindhuśiloṣaṇaiḥ pramohadro hi bhavati bhāṣitaṃ bhiṣajāṃ varaiḥ"},{"type":"verse","number":"33","sanskrit":"मधूकसारसिन्धूत्थवचोषणकणाः समाः श्लक्ष्णं पिष्ट्वाऽम्भसा नस्यं कुर्यात्संज्ञाप्रबोधनम्","text":"madhūkasārasindhūtthavacoṣaṇakaṇāḥ samāḥ ślakṣṇaṃ piṣṭvā'mbhasā nasyaṃ kuryātsaṃjñāprabodhanam"},{"type":"verse","number":"34","sanskrit":"रक्तजायान्तु मूर्च्छायां हितः शीतक्रियाविधिः मद्यजायां पिवेन्मद्यं निद्रां सेवेत वा सुखम् विषजायां विषघ्नानि भेषजानि प्रयोजयेत्","text":"raktajāyāntu mūrcchāyāṃ hitaḥ śītakriyāvidhiḥ madyajāyāṃ pivenmadyaṃ nidrāṃ seveta vā sukham viṣajāyāṃ viṣaghnāni bheṣajāni prayojayet"},{"type":"verse","number":"35","sanskrit":"प्रभूतदोषस्तमसोऽतिरेकात्सम्मूर्छितो नैव विबुध्यते यः संन्यस्तसंज्ञः स हि दुश्चिकित्स्यो नरो भिषग्भिः परिकीर्तितोऽसौ","text":"prabhūtadoṣastamaso'tirekātsammūrchito naiva vibudhyate yaḥ saṃnyastasaṃjñaḥ sa hi duścikitsyo naro bhiṣagbhiḥ parikīrtito'sau"},{"type":"verse","number":"36","sanskrit":"अञ्जनान्यवपीडाश्च धूमाः प्रधमनानि च सूचीभिस्तोदनं शस्तं दाहः पीडा नखान्तरे","text":"añjanānyavapīḍāśca dhūmāḥ pradhamanāni ca sūcībhistodanaṃ śastaṃ dāhaḥ pīḍā nakhāntare"},{"type":"verse","number":"37","sanskrit":"लुञ्चनं केशलोम्नाञ्च दन्तैर्दशनमेव च आत्मगुप्ताऽवघर्षश्च हितस्तस्य प्रबोधने","text":"luñcanaṃ keśalomnāñca dantairdaśanameva ca ātmaguptā'vagharṣaśca hitastasya prabodhane"},{"type":"verse","number":"38","sanskrit":"कणामधुयुतं सूतं मूर्च्छायां प्राशयेद्भिषक् शीतसेकावगाहादीन्सर्वाङ्गे पीडनं हठात्","text":"kaṇāmadhuyutaṃ sūtaṃ mūrcchāyāṃ prāśayedbhiṣak śītasekāvagāhādīnsarvāṅge pīḍanaṃ haṭhāt"},{"type":"verse","number":"39","sanskrit":"ताम्रचूर्णसमोशीरं केशरं शीतवारिणा पीतं मूर्च्छां द्रुतं हन्याद् वृक्षमिन्द्रा शनिर्यथा","text":"tāmracūrṇasamośīraṃ keśaraṃ śītavāriṇā pītaṃ mūrcchāṃ drutaṃ hanyād vṛkṣamindrā śaniryathā"},{"type":"verse","number":"40","sanskrit":"पिबेद् दुरालभाक्वाथं सघृतं भ्रमशान्तये पथ्याक्वाथेन संसिद्धं घृतं धात्रीरसेन वा","text":"pibed durālabhākvāthaṃ saghṛtaṃ bhramaśāntaye pathyākvāthena saṃsiddhaṃ ghṛtaṃ dhātrīrasena vā"},{"type":"verse","number":"41","sanskrit":"ताम्रं दुरालभाक्वाथः पीतन्तु घृतसंयुतम् निवारयेद् भ्रमं शीघ्रं तं यथा शम्भुभाषितम्","text":"tāmraṃ durālabhākvāthaḥ pītantu ghṛtasaṃyutam nivārayed bhramaṃ śīghraṃ taṃ yathā śambhubhāṣitam"},{"type":"verse","number":"42","sanskrit":"तुरङ्गलालालवणोत्तमेन्दुमनः शिलामागधिकामधूनि","text":"turaṅgalālālavaṇottamendumanaḥ śilāmāgadhikāmadhūni"},{"type":"verse","number":"43","sanskrit":"नियोज्य तान्यक्ष्णि विमिश्रितानि तन्द्रां सनिद्रां विनिवारयन्ति","text":"niyojya tānyakṣṇi vimiśritāni tandrāṃ sanidrāṃ vinivārayanti"},{"type":"verse","number":"44","sanskrit":"सैन्धवं श्वेतमरिचं सर्षपाः कुष्ठमेव च बस्तमूत्रेण सम्पिष्टं नस्यं तन्द्रा निवारणम्","text":"saindhavaṃ śvetamaricaṃ sarṣapāḥ kuṣṭhameva ca bastamūtreṇa sampiṣṭaṃ nasyaṃ tandrā nivāraṇam"},{"type":"verse","number":"45","sanskrit":"शुण्ठीकणोग्रालवणोत्तमानि नस्येन तन्द्रा विजयोल्वणानि क्षुद्रा ऽमृतापौष्करनागराणि भार्गीशिवाभ्यां क्वथितानि पानात्","text":"śuṇṭhīkaṇogrālavaṇottamāni nasyena tandrā vijayolvaṇāni kṣudrā 'mṛtāpauṣkaranāgarāṇi bhārgīśivābhyāṃ kvathitāni pānāt"},{"type":"verse","number":"46","sanskrit":"इत्येकोनविंशो मूर्च्छाभ्रमनिद्रा तन्द्रा सन्यासाधिकारः समाप्तः १९","text":"ityekonaviṃśo mūrcchābhramanidrā tandrā sanyāsādhikāraḥ samāptaḥ 19"}]},{"sthana":"Уттаракханда","number":20,"lang":"sa","content":[{"type":"heading","heading":"Мадатьяя — алкоголизм"},{"type":"verse","number":"1","sanskrit":"मद्यं स्वभावतः प्राज्ञैर्यथैवान्नं तथा स्मृतम् अयुक्तियुक्तं रोगाय युक्तियुक्तं रसायनम्","text":"madyaṃ svabhāvataḥ prājñairyathaivānnaṃ tathā smṛtam ayuktiyuktaṃ rogāya yuktiyuktaṃ rasāyanam"},{"type":"verse","number":"2","sanskrit":"प्राणाः प्राणभृतामन्नं तदयुक्त्या निहन्त्यसून् विषं प्राणहरं तच्च युक्तियुक्तं रसायनम्","text":"prāṇāḥ prāṇabhṛtāmannaṃ tadayuktyā nihantyasūn viṣaṃ prāṇaharaṃ tacca yuktiyuktaṃ rasāyanam"},{"type":"verse","number":"3","sanskrit":"विधिना मात्रया काले हितैरन्नैर्यथाबलम् प्रहृष्टो यः पिबेन्मद्यं तस्य स्यादमृतं यथा","text":"vidhinā mātrayā kāle hitairannairyathābalam prahṛṣṭo yaḥ pibenmadyaṃ tasya syādamṛtaṃ yathā"},{"type":"verse","number":"4","sanskrit":"अभ्यङ्गोत्सादनस्नानवासोधूपानुलेपनैः स्निग्धोष्णैस्तादृशैरन्नैर्वातप्रकृतिकः पिबेत्","text":"abhyaṅgotsādanasnānavāsodhūpānulepanaiḥ snigdhoṣṇaistādṛśairannairvātaprakṛtikaḥ pibet"},{"type":"verse","number":"5","sanskrit":"शीतोपचारैर्विविधैर्मधुरस्निग्धशीतलैः फलैरन्नैः सह नरः पित्तप्रकृतिकः पिबेत्","text":"śītopacārairvividhairmadhurasnigdhaśītalaiḥ phalairannaiḥ saha naraḥ pittaprakṛtikaḥ pibet"},{"type":"verse","number":"6","sanskrit":"श्लैष्मिको जाङ्गलैर्मांसैर्मरिचैर्मदिरां पिबेत् प्राक् पिबेच्छ्लैष्मिको मद्यं भुक्तस्योपरि पैत्तिकः","text":"ślaiṣmiko jāṅgalairmāṃsairmaricairmadirāṃ pibet prāk pibecchlaiṣmiko madyaṃ bhuktasyopari paittikaḥ"},{"type":"verse","number":"7","sanskrit":"वातिकस्तु पिबेन्मध्ये समदोषो यथेच्छति वातिकस्तु पिबेन्मद्यं प्रायो गौडिकपैष्टिकम्","text":"vātikastu pibenmadhye samadoṣo yathecchati vātikastu pibenmadyaṃ prāyo gauḍikapaiṣṭikam"},{"type":"verse","number":"8","sanskrit":"कफपित्तात्मको यस्तु माध्वीकं माधवं पिबेत् विधिर्वसुमतामेष कथितश्चरकादिभिः यथोपपत्तिकं वाऽपि पिबेन्मद्यं हि मात्रया","text":"kaphapittātmako yastu mādhvīkaṃ mādhavaṃ pibet vidhirvasumatāmeṣa kathitaścarakādibhiḥ yathopapattikaṃ vā'pi pibenmadyaṃ hi mātrayā"},{"type":"verse","number":"9","sanskrit":"रसवातादिमार्गाणां सत्त्वबुद्धीन्द्रि यात्मनाम् प्रधानस्यौजसश्चैव हृदयं स्थानमुच्यते","text":"rasavātādimārgāṇāṃ sattvabuddhīndri yātmanām pradhānasyaujasaścaiva hṛdayaṃ sthānamucyate"},{"type":"verse","number":"10","sanskrit":"मद्यं हृदयमाविश्य स्वगुणैरोजसो गुणान् दशभिर्दश सङ्क्षोभ्य चेतो नयति विक्रियाम्","text":"madyaṃ hṛdayamāviśya svaguṇairojaso guṇān daśabhirdaśa saṅkṣobhya ceto nayati vikriyām"},{"type":"verse","number":"11","sanskrit":"लघूष्णतीक्ष्णसूक्ष्माम्लव्यवाय्याशुकरं तथा रुक्षं विकासि विशदं मद्यं दशगुणं स्मृतम्","text":"laghūṣṇatīkṣṇasūkṣmāmlavyavāyyāśukaraṃ tathā rukṣaṃ vikāsi viśadaṃ madyaṃ daśaguṇaṃ smṛtam"},{"type":"verse","number":"12","sanskrit":"गुरु शीतं मृदु स्निग्धं सान्द्रं स्वादु स्थिरं तथा प्रसन्नं पिच्छिलं सूक्ष्ममोजो दशगुणं स्मृतम्","text":"guru śītaṃ mṛdu snigdhaṃ sāndraṃ svādu sthiraṃ tathā prasannaṃ picchilaṃ sūkṣmamojo daśaguṇaṃ smṛtam"},{"type":"verse","number":"13","sanskrit":"गौरवं लाघवाच्छैत्यमौष्ण्यादम्लस्वभावतः माधुर्यं मार्दवं तैक्ष्ण्यात्प्रसादञ्चाशु भावनात्","text":"gauravaṃ lāghavācchaityamauṣṇyādamlasvabhāvataḥ mādhuryaṃ mārdavaṃ taikṣṇyātprasādañcāśu bhāvanāt"},{"type":"verse","number":"14","sanskrit":"रौक्ष्यात्स्नेहं व्यवायित्वात् स्थिरत्वं सूक्ष्मतामपि विकासिभावात्पैच्छिल्यं वैशद्यात्सान्द्र तां तथा","text":"raukṣyātsnehaṃ vyavāyitvāt sthiratvaṃ sūkṣmatāmapi vikāsibhāvātpaicchilyaṃ vaiśadyātsāndra tāṃ tathā"},{"type":"verse","number":"15","sanskrit":"सौक्ष्म्यान्मद्यं निहन्त्येवमोजसः स्वगुणैर्गुणान् सत्त्वं तदाश्रयं चाशु सङ्क्षोभ्यकुरुते मदम्","text":"saukṣmyānmadyaṃ nihantyevamojasaḥ svaguṇairguṇān sattvaṃ tadāśrayaṃ cāśu saṅkṣobhyakurute madam"},{"type":"verse","number":"16","sanskrit":"हृदि मद्यगुणाविष्टे हर्षस्तर्षो रतिः सुखम्","text":"hṛdi madyaguṇāviṣṭe harṣastarṣo ratiḥ sukham"},{"type":"verse","number":"17","sanskrit":"विकाराश्च यथासत्त्वं चित्रा राजसतामसाः जायन्ते मोहनिद्रा न्ता इत्येतन्मदलक्षणम्","text":"vikārāśca yathāsattvaṃ citrā rājasatāmasāḥ jāyante mohanidrā ntā ityetanmadalakṣaṇam"},{"type":"verse","number":"18","sanskrit":"हर्षमोजो बलं पुष्टिमारोग्यं पौरुषं तथा युक्त्या पीतं करोत्याशु मद्यं मदसुखप्रदम्","text":"harṣamojo balaṃ puṣṭimārogyaṃ pauruṣaṃ tathā yuktyā pītaṃ karotyāśu madyaṃ madasukhapradam"},{"type":"verse","number":"19","sanskrit":"रोचनं दीपनं हृद्यं स्वरवर्णप्रसादनम् प्रीणनं बृंहणं बल्यं भयशोकश्रमापहम्","text":"rocanaṃ dīpanaṃ hṛdyaṃ svaravarṇaprasādanam prīṇanaṃ bṛṃhaṇaṃ balyaṃ bhayaśokaśramāpaham"},{"type":"verse","number":"20","sanskrit":"स्वापनं नष्टनिद्रा णां मूकानां वाग्विशोधनम् नाशनं चातिनिद्रा णां विबन्धानां विबन्धनुत्","text":"svāpanaṃ naṣṭanidrā ṇāṃ mūkānāṃ vāgviśodhanam nāśanaṃ cātinidrā ṇāṃ vibandhānāṃ vibandhanut"},{"type":"verse","number":"21","sanskrit":"वधबन्धपरिक्लेशदुःखानां चाप्यबोधनम् अपि प्रवयसां मद्यमुत्सर्गान्मोदकारकम्","text":"vadhabandhaparikleśaduḥkhānāṃ cāpyabodhanam api pravayasāṃ madyamutsargānmodakārakam"},{"type":"verse","number":"22","sanskrit":"बहुदुःखक्षतस्यास्य शोकैरुपहतस्य च विश्रामो जीवलोकस्य मद्यं युक्त्या निषेवितम्","text":"bahuduḥkhakṣatasyāsya śokairupahatasya ca viśrāmo jīvalokasya madyaṃ yuktyā niṣevitam"},{"type":"verse","number":"23","sanskrit":"बुद्धिस्मृतिप्रीतिकरः सुखश्च पानान्ननिद्रा रतिवर्द्धनश्च सम्पाठगीतस्वरवर्द्धनश्च प्रोक्तोऽतिरम्यः प्रथमो मदो हि","text":"buddhismṛtiprītikaraḥ sukhaśca pānānnanidrā rativarddhanaśca sampāṭhagītasvaravarddhanaśca prokto'tiramyaḥ prathamo mado hi"},{"type":"verse","number":"24","sanskrit":"अव्यक्तबुद्धिस्मृतिवाग्विचेष्टः सोन्मत्तलीलाऽकृतिरप्रशान्तः आलस्यनिद्रा ऽभिहतो मुहुश्च मध्येन मत्तः पुरुषो मदेन","text":"avyaktabuddhismṛtivāgviceṣṭaḥ sonmattalīlā'kṛtirapraśāntaḥ ālasyanidrā 'bhihato muhuśca madhyena mattaḥ puruṣo madena"},{"type":"verse","number":"25","sanskrit":"गच्छेदगम्यां न गुरुंश्च मन्येत्खादेदभक्ष्याणि च नष्टसञ्ज्ञः ब्रूयाच्च गुह्यानि हृदि स्थितानिमदे तृतीये पुरुषोऽस्वतन्त्रः","text":"gacchedagamyāṃ na guruṃśca manyetkhādedabhakṣyāṇi ca naṣṭasañjñaḥ brūyācca guhyāni hṛdi sthitānimade tṛtīye puruṣo'svatantraḥ"},{"type":"verse","number":"26","sanskrit":"चतुर्थे तु मदे मूढो भग्नदार्विव निष्क्रियः कार्याकार्यविभागज्ञो मृतादपि परो मृतः","text":"caturthe tu made mūḍho bhagnadārviva niṣkriyaḥ kāryākāryavibhāgajño mṛtādapi paro mṛtaḥ"},{"type":"verse","number":"27","sanskrit":"को मदं तादृशं गच्छेदुन्मादमिव चापरम् बहुदोषमिवामूढः कान्तारं स्ववशः कृती","text":"ko madaṃ tādṛśaṃ gacchedunmādamiva cāparam bahudoṣamivāmūḍhaḥ kāntāraṃ svavaśaḥ kṛtī"},{"type":"verse","number":"28","sanskrit":"नातिमाद्यन्ति बलिनः कृताहारा महाशनाः स्निग्धाः सत्त्ववयोयुक्ता मद्यनित्यास्तदन्वयाः","text":"nātimādyanti balinaḥ kṛtāhārā mahāśanāḥ snigdhāḥ sattvavayoyuktā madyanityāstadanvayāḥ"},{"type":"verse","number":"29","sanskrit":"मेदःकफाधिका मन्दवातपित्तं दृढाग्नयः विपर्ययेऽतिमाद्यन्ति विष्टब्धाः कुपिताश्च ये मद्येन चाम्लरुक्षेण साजीर्णे बहुनाऽपि च","text":"medaḥkaphādhikā mandavātapittaṃ dṛḍhāgnayaḥ viparyaye'timādyanti viṣṭabdhāḥ kupitāśca ye madyena cāmlarukṣeṇa sājīrṇe bahunā'pi ca"},{"type":"verse","number":"30","sanskrit":"विषस्य ये गुणा दृष्टा सन्निपातप्रकोपणाः त एव मद्ये दृश्यन्ते विषे तु बलवत्तराः","text":"viṣasya ye guṇā dṛṣṭā sannipātaprakopaṇāḥ ta eva madye dṛśyante viṣe tu balavattarāḥ"},{"type":"verse","number":"31","sanskrit":"तस्मादविधिपीतेन तथा मात्राऽधिकेन च युक्तेन चाहितैरन्नैरकालेसेवितेन च","text":"tasmādavidhipītena tathā mātrā'dhikena ca yuktena cāhitairannairakālesevitena ca"},{"type":"verse","number":"32","sanskrit":"मद्येन खलु जायन्ते मदात्ययमुखा गदाः","text":"madyena khalu jāyante madātyayamukhā gadāḥ"},{"type":"verse","number":"33","sanskrit":"निर्भुक्तमेकान्तत एव मद्यं निषेव्यमाणं मनुजेन नित्यम् उत्पादयेत्कष्टतमान्विकारानुत्पादयेच्चापि शरीरभेदम्","text":"nirbhuktamekāntata eva madyaṃ niṣevyamāṇaṃ manujena nityam utpādayetkaṣṭatamānvikārānutpādayeccāpi śarīrabhedam"},{"type":"verse","number":"34","sanskrit":"क्रुद्धेन भीतेन पिपासितेन शोकाभितप्तेन बुभुक्षितेन व्यायामभाराध्वपरिक्षतेन वेगावरोधाभिहतेन चापि","text":"kruddhena bhītena pipāsitena śokābhitaptena bubhukṣitena vyāyāmabhārādhvaparikṣatena vegāvarodhābhihatena cāpi"},{"type":"verse","number":"35","sanskrit":"अत्यम्लरुक्षावततोदरेण साजीर्णभुक्तेन तथाऽबलेन उष्णाभितप्तेन च सेव्यमानं करोति मद्यं विविधान्विकारान्","text":"atyamlarukṣāvatatodareṇa sājīrṇabhuktena tathā'balena uṣṇābhitaptena ca sevyamānaṃ karoti madyaṃ vividhānvikārān"},{"type":"verse","number":"36","sanskrit":"मद्योत्पन्नविकारान् विवृणोति पानात्ययं परमदं पानाजीर्णमथापि च पानविभ्रममत्युग्रं तेषां वक्ष्यामि लक्षणम्","text":"madyotpannavikārān vivṛṇoti pānātyayaṃ paramadaṃ pānājīrṇamathāpi ca pānavibhramamatyugraṃ teṣāṃ vakṣyāmi lakṣaṇam"},{"type":"verse","number":"37","sanskrit":"शरीरदुःखं बलवत्प्रमोहो हृदयव्यथा अरुचिः प्रततं तृष्णा ज्वरः शीतोष्णलक्षणः","text":"śarīraduḥkhaṃ balavatpramoho hṛdayavyathā aruciḥ pratataṃ tṛṣṇā jvaraḥ śītoṣṇalakṣaṇaḥ"},{"type":"verse","number":"38","sanskrit":"शिरःपार्श्वास्थिसन्धीनां वेदना विक्षते यथा जायतेऽतिबला जृम्भा स्फुरणं वेपनं श्रमः","text":"śiraḥpārśvāsthisandhīnāṃ vedanā vikṣate yathā jāyate'tibalā jṛmbhā sphuraṇaṃ vepanaṃ śramaḥ"},{"type":"verse","number":"39","sanskrit":"उरोविबन्धः कासश्च हिक्का श्वासः प्रजागरः शरीरकम्पः कर्णाक्षिमुखरोगस्त्रिकग्रहः","text":"urovibandhaḥ kāsaśca hikkā śvāsaḥ prajāgaraḥ śarīrakampaḥ karṇākṣimukharogastrikagrahaḥ"},{"type":"verse","number":"40","sanskrit":"छर्दिर्विड्भेद उत्क्लेशो वातपित्तकफात्मकः श्रमः प्रलापो रूपाणामसताञ्चैव दर्शनम्","text":"chardirviḍbheda utkleśo vātapittakaphātmakaḥ śramaḥ pralāpo rūpāṇāmasatāñcaiva darśanam"},{"type":"verse","number":"41","sanskrit":"तृणभस्मलतापर्णपांशुभिश्चावपूरणम् प्रधर्षणं विहङ्गैश्च भ्रान्तचेताः स मन्यते","text":"tṛṇabhasmalatāparṇapāṃśubhiścāvapūraṇam pradharṣaṇaṃ vihaṅgaiśca bhrāntacetāḥ sa manyate"},{"type":"verse","number":"42","sanskrit":"व्याकुलानामशस्तानां स्वप्नानां दर्शनानि च मदात्ययस्य रूपाणि सर्वाण्येतानि लक्षयेत्","text":"vyākulānāmaśastānāṃ svapnānāṃ darśanāni ca madātyayasya rūpāṇi sarvāṇyetāni lakṣayet"},{"type":"verse","number":"43","sanskrit":"स्त्रीशोकभयभाराध्वकर्मभिर्योऽतिकर्षितः रुक्षाल्पप्रमिताशी च यः पिवत्यतिमात्रया","text":"strīśokabhayabhārādhvakarmabhiryo'tikarṣitaḥ rukṣālpapramitāśī ca yaḥ pivatyatimātrayā"},{"type":"verse","number":"44","sanskrit":"रूक्षं परिणतं मद्यं निशि निद्रां निहत्य च करोति तस्य तच्छीघ्रं वातप्रायं मदात्ययम्","text":"rūkṣaṃ pariṇataṃ madyaṃ niśi nidrāṃ nihatya ca karoti tasya tacchīghraṃ vātaprāyaṃ madātyayam"},{"type":"verse","number":"45","sanskrit":"हिक्काश्वासशिरःकम्पपार्श्वशूलप्रजागरैः विद्याद्बहुप्रलापस्य वातप्रायं मदात्ययम्","text":"hikkāśvāsaśiraḥkampapārśvaśūlaprajāgaraiḥ vidyādbahupralāpasya vātaprāyaṃ madātyayam"},{"type":"verse","number":"46","sanskrit":"तीक्ष्णोष्णमद्यमम्लं च योऽतिमात्रं निषेवते अम्लोष्णतीक्ष्णभोजी च क्रोधनोऽज्ञानवान्नरः तस्योपजायते तीव्रः पित्तप्रायो मदात्ययः","text":"tīkṣṇoṣṇamadyamamlaṃ ca yo'timātraṃ niṣevate amloṣṇatīkṣṇabhojī ca krodhano'jñānavānnaraḥ tasyopajāyate tīvraḥ pittaprāyo madātyayaḥ"},{"type":"verse","number":"47","sanskrit":"तृष्णादाहज्वरस्वेदमोहातीसारविभ्रमैः विद्याद्धरितवर्णस्य पित्तप्रायं मदात्ययम्","text":"tṛṣṇādāhajvarasvedamohātīsāravibhramaiḥ vidyāddharitavarṇasya pittaprāyaṃ madātyayam"},{"type":"verse","number":"48","sanskrit":"मधुरस्निग्धगुर्वाशी यः पिबत्यतिमात्रया","text":"madhurasnigdhagurvāśī yaḥ pibatyatimātrayā"},{"type":"verse","number":"49","sanskrit":"अव्यायामदिवास्वप्नशय्यासनसुखे रतः मदात्ययं कफप्रायं स नरो लभते ध्रुवम्","text":"avyāyāmadivāsvapnaśayyāsanasukhe rataḥ madātyayaṃ kaphaprāyaṃ sa naro labhate dhruvam"},{"type":"verse","number":"50","sanskrit":"छर्द्यरोचकहृंल्लासतन्द्रा स्तैमित्यगौरवैः विद्याच्छीतपरीतस्य कफप्रायं मदात्ययम्","text":"chardyarocakahṛṃllāsatandrā staimityagauravaiḥ vidyācchītaparītasya kaphaprāyaṃ madātyayam"},{"type":"verse","number":"51","sanskrit":"त्रिदोषो हेतुभिः सर्वैः सर्वैर्लिङ्गैर्मदात्ययः","text":"tridoṣo hetubhiḥ sarvaiḥ sarvairliṅgairmadātyayaḥ"},{"type":"verse","number":"52","sanskrit":"श्लेष्मक्षयोऽङ्गगुरुता विरसास्यता च विण्मूत्रसक्तिरथ तन्द्रि ररोचकश्च लिङ्गं परस्य तु मदस्य वदन्ति तज्ज्ञास्तृष्णा रुजा शिरसि सन्धिषु चापि भेदः","text":"śleṣmakṣayo'ṅgagurutā virasāsyatā ca viṇmūtrasaktiratha tandri rarocakaśca liṅgaṃ parasya tu madasya vadanti tajjñāstṛṣṇā rujā śirasi sandhiṣu cāpi bhedaḥ"},{"type":"verse","number":"53","sanskrit":"आध्मानमुग्रमथवोद्गिरणं विदाहः पाने त्वजीर्णमुपगच्छति लक्षणानि ज्ञेयानि तत्र भिषजा सुविनिश्चितानि पित्तप्रकोपजनितानि च कारणानि","text":"ādhmānamugramathavodgiraṇaṃ vidāhaḥ pāne tvajīrṇamupagacchati lakṣaṇāni jñeyāni tatra bhiṣajā suviniścitāni pittaprakopajanitāni ca kāraṇāni"},{"type":"verse","number":"54","sanskrit":"हृद्गात्रतोदकफसंस्रवकण्ठधूम मूर्च्छावमीमदशिरोरुजनप्रदेहाः द्वेषः सुराऽन्नविकृतेषु च तेषु तेषु तं पानविभ्रममुशन्त्यखिलेषु धीराः","text":"hṛdgātratodakaphasaṃsravakaṇṭhadhūma mūrcchāvamīmadaśirorujanapradehāḥ dveṣaḥ surā'nnavikṛteṣu ca teṣu teṣu taṃ pānavibhramamuśantyakhileṣu dhīrāḥ"},{"type":"verse","number":"55","sanskrit":"हीनोत्तरौष्ठमतिशीतममन्ददाहं तैलप्रभाऽस्यमपि पानहतं त्यजेच्च जिह्वौष्ठदन्तमसितन्त्वथ वाऽपि नीलम्पीते च यस्य नयने रुधिरप्रभे च हिक्का ज्वरो वमथुवेपथुपार्श्वशूलाः कासभ्रमावपि च पानहतं त्यजेत्तम्","text":"hīnottarauṣṭhamatiśītamamandadāhaṃ tailaprabhā'syamapi pānahataṃ tyajecca jihvauṣṭhadantamasitantvatha vā'pi nīlampīte ca yasya nayane rudhiraprabhe ca hikkā jvaro vamathuvepathupārśvaśūlāḥ kāsabhramāvapi ca pānahataṃ tyajettam"},{"type":"verse","number":"56","sanskrit":"मद्योत्थानाञ्च रोगाणां मद्यमेव हि भेषजम् यथा दहनदग्धानां दहनं स्वेदनं हितम्","text":"madyotthānāñca rogāṇāṃ madyameva hi bheṣajam yathā dahanadagdhānāṃ dahanaṃ svedanaṃ hitam"},{"type":"verse","number":"57","sanskrit":"मिथ्याऽतिहीनमद्येन यो व्याधिरुपजायते समेनैव निपीतेन मद्येन स हि शाम्यति","text":"mithyā'tihīnamadyena yo vyādhirupajāyate samenaiva nipītena madyena sa hi śāmyati"},{"type":"verse","number":"58","sanskrit":"बीजपूरकवृक्षाम्लकोलदाडिमसंयुतम् यवानीहपुषाजाजी शृङ्गबेरावचूर्णितम्","text":"bījapūrakavṛkṣāmlakoladāḍimasaṃyutam yavānīhapuṣājājī śṛṅgaberāvacūrṇitam"},{"type":"verse","number":"59","sanskrit":"सस्नेहैः शक्तुभिर्युक्तमुपदंशैश्चिरोत्थितम् दद्यात्सलवणं मद्यं वातपैत्तिकशान्तये","text":"sasnehaiḥ śaktubhiryuktamupadaṃśaiścirotthitam dadyātsalavaṇaṃ madyaṃ vātapaittikaśāntaye"},{"type":"verse","number":"60","sanskrit":"मद्यं सौवर्चलव्योषयुक्तं किञ्चिज्जलान्वितम् जीर्णमद्याय दातव्यं वातपानात्ययापहम्","text":"madyaṃ sauvarcalavyoṣayuktaṃ kiñcijjalānvitam jīrṇamadyāya dātavyaṃ vātapānātyayāpaham"},{"type":"verse","number":"61","sanskrit":"चव्यं सौवर्चलं हिङ्गु पूरकं विश्वदीपकम् चूर्णं मद्येन पातव्यं पानात्ययरुजाऽपहम्","text":"cavyaṃ sauvarcalaṃ hiṅgu pūrakaṃ viśvadīpakam cūrṇaṃ madyena pātavyaṃ pānātyayarujā'paham"},{"type":"verse","number":"62","sanskrit":"लावतित्तिरदक्षाणां रसैश्च शिखिनामपि पक्षिणां मृगमत्स्यानामानूपानां तथौदनैः","text":"lāvatittiradakṣāṇāṃ rasaiśca śikhināmapi pakṣiṇāṃ mṛgamatsyānāmānūpānāṃ tathaudanaiḥ"},{"type":"verse","number":"63","sanskrit":"स्निग्धोष्णलवणाम्लैश्च वेशवारैर्मुखप्रियैः स्निग्धैर्गोधूमकैरन्नैर्वातप्रायं मदात्ययम्","text":"snigdhoṣṇalavaṇāmlaiśca veśavārairmukhapriyaiḥ snigdhairgodhūmakairannairvātaprāyaṃ madātyayam"},{"type":"verse","number":"64","sanskrit":"नारीणां यौवनोष्माणां निर्दयैरुपगूहनैः श्रोण्यूरुकुचभारैश्च संरोधोष्णसुखप्रदैः","text":"nārīṇāṃ yauvanoṣmāṇāṃ nirdayairupagūhanaiḥ śroṇyūrukucabhāraiśca saṃrodhoṣṇasukhapradaiḥ"},{"type":"verse","number":"65","sanskrit":"शयनाच्छादनैरुष्णैश्चान्तर्गेहैः सुखप्रदैः मारुतैः प्रबलैः शीघ्रं प्रशाम्यति मदात्ययः","text":"śayanācchādanairuṣṇaiścāntargehaiḥ sukhapradaiḥ mārutaiḥ prabalaiḥ śīghraṃ praśāmyati madātyayaḥ"},{"type":"verse","number":"66","sanskrit":"पित्तपानात्यये योज्याः सर्वतश्च क्रिया हिमाः सितामाक्षिकसंयुक्तं मद्यमर्द्धोदकं पिबेत्","text":"pittapānātyaye yojyāḥ sarvataśca kriyā himāḥ sitāmākṣikasaṃyuktaṃ madyamarddhodakaṃ pibet"},{"type":"verse","number":"67","sanskrit":"मद्यं खर्जूरमृद्वीकापरूषकरसैर्युतम् सदाडिमरसं शीतं शक्तुभिश्चावचूर्णितम्","text":"madyaṃ kharjūramṛdvīkāparūṣakarasairyutam sadāḍimarasaṃ śītaṃ śaktubhiścāvacūrṇitam"},{"type":"verse","number":"68","sanskrit":"सशर्करं वा माध्वीकं संयुक्तमथ वा परम् दद्याद्बहूदकं काले पातुं पित्तमदात्यये","text":"saśarkaraṃ vā mādhvīkaṃ saṃyuktamatha vā param dadyādbahūdakaṃ kāle pātuṃ pittamadātyaye"},{"type":"verse","number":"69","sanskrit":"शशान्कपिञ्जलानेणांल्लावानसितपुच्छकान् मधुराम्लान्प्रयुञ्जीत भोजने शालिषष्टिकान्","text":"śaśānkapiñjalāneṇāṃllāvānasitapucchakān madhurāmlānprayuñjīta bhojane śāliṣaṣṭikān"},{"type":"verse","number":"70","sanskrit":"पटोलयवमिश्रं वा छागलं कल्पयेद्र सम् सतीनमुद्गमिश्रं वा दाडिमामलकान्वितम्","text":"paṭolayavamiśraṃ vā chāgalaṃ kalpayedra sam satīnamudgamiśraṃ vā dāḍimāmalakānvitam"},{"type":"verse","number":"71","sanskrit":"द्रा क्षाऽमलकखर्जूरपरूषकरसेन च कल्पयेत्तर्पणान्यूषान् रसांश्च विविधात्मकान्","text":"drā kṣā'malakakharjūraparūṣakarasena ca kalpayettarpaṇānyūṣān rasāṃśca vividhātmakān"},{"type":"verse","number":"72","sanskrit":"शीतानि चान्नपानानि शीतशय्यासनानि च शीतवातजलस्पर्शाः शीतान्युपवनानि च","text":"śītāni cānnapānāni śītaśayyāsanāni ca śītavātajalasparśāḥ śītānyupavanāni ca"},{"type":"verse","number":"73","sanskrit":"क्षौमपद्मोत्पलानाञ्च मणीनां मौक्तिकस्य च चन्दनोदकशीतानां स्पर्शाश्चन्द्रांशुशीतलाः","text":"kṣaumapadmotpalānāñca maṇīnāṃ mauktikasya ca candanodakaśītānāṃ sparśāścandrāṃśuśītalāḥ"},{"type":"verse","number":"74","sanskrit":"रुक्षतर्पणसंयुक्तं यवानीव्योषसंयुतम् यवगोधूमकञ्चान्नं रुक्षयूषेण भोजयेत्","text":"rukṣatarpaṇasaṃyuktaṃ yavānīvyoṣasaṃyutam yavagodhūmakañcānnaṃ rukṣayūṣeṇa bhojayet"},{"type":"verse","number":"75","sanskrit":"कुलत्थकानां शुष्काणां मूलकानां रसेन वा प्रभूतकटुसंयुक्तं यवान्नं वा प्रदापयेत्","text":"kulatthakānāṃ śuṣkāṇāṃ mūlakānāṃ rasena vā prabhūtakaṭusaṃyuktaṃ yavānnaṃ vā pradāpayet"},{"type":"verse","number":"76","sanskrit":"छागमांसरसं रुक्षमम्लं वा जाङ्गलं रसम् व्योषयूषं मनागम्लं पिबेत् कफमदात्यये","text":"chāgamāṃsarasaṃ rukṣamamlaṃ vā jāṅgalaṃ rasam vyoṣayūṣaṃ manāgamlaṃ pibet kaphamadātyaye"},{"type":"verse","number":"77","sanskrit":"स्थाल्यामथ कपाले वा भृष्टं कृत्वा तु नीरसम् कट्वम्ललवणं मांसं खादेत्कफमदात्यये","text":"sthālyāmatha kapāle vā bhṛṣṭaṃ kṛtvā tu nīrasam kaṭvamlalavaṇaṃ māṃsaṃ khādetkaphamadātyaye"},{"type":"verse","number":"78","sanskrit":"वामकद्र व्ययुक्तेन मद्येनोल्लेखनं मतम् मदात्यये कफोद्भूते लङ्घनञ्च यथाबलम्","text":"vāmakadra vyayuktena madyenollekhanaṃ matam madātyaye kaphodbhūte laṅghanañca yathābalam"},{"type":"verse","number":"79","sanskrit":"यदिदं कर्म्मनिर्दिष्टं वातपित्तकफान्प्रति सर्वजे सर्वमेवेदं प्रयोक्तव्यं चिकित्सकैः","text":"yadidaṃ karmmanirdiṣṭaṃ vātapittakaphānprati sarvaje sarvamevedaṃ prayoktavyaṃ cikitsakaiḥ"},{"type":"verse","number":"80","sanskrit":"सगुडः कूष्माण्डरसः शमयति मदमाशु कोद्र वजम् धत्तूरजञ्च दुग्धं सशर्करं चाशु पानेन","text":"saguḍaḥ kūṣmāṇḍarasaḥ śamayati madamāśu kodra vajam dhattūrajañca dugdhaṃ saśarkaraṃ cāśu pānena"},{"type":"verse","number":"81","sanskrit":"सच्छर्दिमूर्च्छाऽतीसारं मदं पूगफलोद्भवम् सद्यः प्रशमयेत्पीतमातृप्तेर्वारि शीतलम्","text":"sacchardimūrcchā'tīsāraṃ madaṃ pūgaphalodbhavam sadyaḥ praśamayetpītamātṛptervāri śītalam"},{"type":"verse","number":"82","sanskrit":"वन्यकरीषघ्राणाज्जलपानाल्लवणभक्षणादपि च शाम्यति पूगफलोद्भवमदः सशूलः सशर्कराकवलात्","text":"vanyakarīṣaghrāṇājjalapānāllavaṇabhakṣaṇādapi ca śāmyati pūgaphalodbhavamadaḥ saśūlaḥ saśarkarākavalāt"},{"type":"verse","number":"83","sanskrit":"तत्क्षणान्मृदितं चूर्णं समाघ्रातं प्रणाशयेत् ताम्बूलोत्थं मदं पुंसामेकमेव स्वभावतः","text":"tatkṣaṇānmṛditaṃ cūrṇaṃ samāghrātaṃ praṇāśayet tāmbūlotthaṃ madaṃ puṃsāmekameva svabhāvataḥ"},{"type":"verse","number":"84","sanskrit":"जातीफलमदं शीघ्रं हन्ति पथ्या निषेविता शीततोयावगाहश्च शर्करा दधियोजिता बिभीतमदशान्त्यर्थमियमेव मता पुनः","text":"jātīphalamadaṃ śīghraṃ hanti pathyā niṣevitā śītatoyāvagāhaśca śarkarā dadhiyojitā bibhītamadaśāntyarthamiyameva matā punaḥ"},{"type":"verse","number":"85","sanskrit":"मद्यं पीत्वा यदि ना तत्क्षणमवलेढि शर्करां सघृताम् जातु न मदयति मद्यं मनागपि प्रथितवीर्यमपि","text":"madyaṃ pītvā yadi nā tatkṣaṇamavaleḍhi śarkarāṃ saghṛtām jātu na madayati madyaṃ manāgapi prathitavīryamapi"},{"type":"verse","number":"86","sanskrit":"इति विंशो मदात्ययाधिकारः समाप्तः २०","text":"iti viṃśo madātyayādhikāraḥ samāptaḥ 20"}]},{"sthana":"Уттаракханда","number":21,"lang":"sa","content":[{"type":"heading","heading":"Даха — жжение"},{"type":"verse","number":"1","sanskrit":"पित्तज्वरसमः पित्ताद् दाहः स्यात्तस्य संक्रमः","text":"pittajvarasamaḥ pittād dāhaḥ syāttasya saṃkramaḥ"},{"type":"verse","number":"2","sanskrit":"कृत्स्नदेहानुगं रक्तमुद्रि क्तं दहति ध्रुवम् सन्धूप्यते चोष्यते च ताम्राभस्ताम्रलोचनः लोहगन्धाङ्गवदनो वह्निनेवावकीर्यते","text":"kṛtsnadehānugaṃ raktamudri ktaṃ dahati dhruvam sandhūpyate coṣyate ca tāmrābhastāmralocanaḥ lohagandhāṅgavadano vahninevāvakīryate"},{"type":"verse","number":"3","sanskrit":"असृजा पूर्णकोष्ठस्य दाहोऽन्य स्यात्सुदुस्तरः","text":"asṛjā pūrṇakoṣṭhasya dāho'nya syātsudustaraḥ"},{"type":"verse","number":"4","sanskrit":"त्वचं प्राप्तः स पानोष्मा पित्तरक्ताभिमूर्च्छितः दाहं प्रकुरुते घोरं पित्तवत्तत्र भेषजम्","text":"tvacaṃ prāptaḥ sa pānoṣmā pittaraktābhimūrcchitaḥ dāhaṃ prakurute ghoraṃ pittavattatra bheṣajam"},{"type":"verse","number":"5","sanskrit":"तृष्णानिरोधादब्धातौ क्षीणे तेजः समुद्धतम् स बाह्याभ्यन्तरं देहं प्रदहेन्मन्दचेतसः संशुष्कगलताल्वोष्ठो जिह्वां निष्काश्य वेपते","text":"tṛṣṇānirodhādabdhātau kṣīṇe tejaḥ samuddhatam sa bāhyābhyantaraṃ dehaṃ pradahenmandacetasaḥ saṃśuṣkagalatālvoṣṭho jihvāṃ niṣkāśya vepate"},{"type":"verse","number":"6","sanskrit":"धातुक्षयोत्थो यो दाहस्तत्र मूर्च्छातृषाऽन्वितः क्षामस्वरः क्रियाहीनः स सीदेद् भृशपीडितः","text":"dhātukṣayottho yo dāhastatra mūrcchātṛṣā'nvitaḥ kṣāmasvaraḥ kriyāhīnaḥ sa sīded bhṛśapīḍitaḥ"},{"type":"verse","number":"7","sanskrit":"मर्माभिघातजोऽप्यस्ति सोऽसाध्यः सप्तमो मतः","text":"marmābhighātajo'pyasti so'sādhyaḥ saptamo mataḥ"},{"type":"verse","number":"8","sanskrit":"सर्व एव च वर्ज्याः स्युः शीतगात्रस्य देहिनः","text":"sarva eva ca varjyāḥ syuḥ śītagātrasya dehinaḥ"},{"type":"verse","number":"9","sanskrit":"शतधौतघृताभ्यक्तं लेपं वा यवशक्तुभिः कोलामलकयुक्तैर्वा धान्याम्लैरपि बुद्धिमान्","text":"śatadhautaghṛtābhyaktaṃ lepaṃ vā yavaśaktubhiḥ kolāmalakayuktairvā dhānyāmlairapi buddhimān"},{"type":"verse","number":"10","sanskrit":"छादयेत्तस्य सर्वाङ्गमारनालार्द्र वाससा लामज्जकेन युक्तेन चन्दनेनानुलेपयेत् चन्दनाम्वुकणास्यन्दितालवृन्तोपवीजनैः","text":"chādayettasya sarvāṅgamāranālārdra vāsasā lāmajjakena yuktena candanenānulepayet candanāmvukaṇāsyanditālavṛntopavījanaiḥ"},{"type":"verse","number":"11","sanskrit":"सुप्याद् दाहार्दितोऽम्भोजकदलीदलसंस्तरे परिषेकावगाहेषु व्यजनानाञ्च सेवने","text":"supyād dāhārdito'mbhojakadalīdalasaṃstare pariṣekāvagāheṣu vyajanānāñca sevane"},{"type":"verse","number":"12","sanskrit":"शस्यते शिशिरं तोयं दाहतृष्णोपशान्तये फलिनी लोध्रसेव्याम्बुहेमपत्रं कुटन्नटम् कालीयकरसोपेतं दाहे शस्तं प्रलेपनम्","text":"śasyate śiśiraṃ toyaṃ dāhatṛṣṇopaśāntaye phalinī lodhrasevyāmbuhemapatraṃ kuṭannaṭam kālīyakarasopetaṃ dāhe śastaṃ pralepanam"},{"type":"verse","number":"13","sanskrit":"ह्रीबेरपद्मकोशीरचन्दनाम्बुजवारिणा सम्पूर्णामवगाहेत द्रो णीं दाहार्दितो नरः","text":"hrīberapadmakośīracandanāmbujavāriṇā sampūrṇāmavagāheta dro ṇīṃ dāhārdito naraḥ"},{"type":"verse","number":"14","sanskrit":"वाप्यः कमलहासिन्यो जलयन्त्रगृहाः शुभाः नार्यश्चन्दनदिग्धाङ्ग्यो दाहदैन्यहरा मताः","text":"vāpyaḥ kamalahāsinyo jalayantragṛhāḥ śubhāḥ nāryaścandanadigdhāṅgyo dāhadainyaharā matāḥ"},{"type":"verse","number":"15","sanskrit":"पाययेत्कमलस्याम्भः शर्कराऽम्भ पयोऽपि च क्षीरमिक्षुरसञ्चापि कारयेत्पित्तजिद्विधिम्","text":"pāyayetkamalasyāmbhaḥ śarkarā'mbha payo'pi ca kṣīramikṣurasañcāpi kārayetpittajidvidhim"},{"type":"verse","number":"16","sanskrit":"पटीरपर्पटोशीरनीर नीरदनीरजैः मृणालमिसिधान्याकपद्मकामलकैः कृतः","text":"paṭīraparpaṭośīranīra nīradanīrajaiḥ mṛṇālamisidhānyākapadmakāmalakaiḥ kṛtaḥ"},{"type":"verse","number":"17","sanskrit":"अर्द्धशिष्टः सिताशीतः पीतः क्षौद्र समन्वितः क्वांथो व्यपोहयेद् दाहं नृणाञ्च परमोल्बणम्","text":"arddhaśiṣṭaḥ sitāśītaḥ pītaḥ kṣaudra samanvitaḥ kvāṃtho vyapohayed dāhaṃ nṛṇāñca paramolbaṇam"},{"type":"verse","number":"18","sanskrit":"तिलतैलं भवेत्प्रस्थं तत्षोडशगुणे शनैः काञ्जिके विपचेत्तत्स्याद्दाहज्वरहरं परम्","text":"tilatailaṃ bhavetprasthaṃ tatṣoḍaśaguṇe śanaiḥ kāñjike vipacettatsyāddāhajvaraharaṃ param"},{"type":"verse","number":"19","sanskrit":"इत्येकविंशोदाहाधिकारः समाप्तः","text":"ityekaviṃśodāhādhikāraḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":22,"lang":"sa","content":[{"type":"heading","heading":"Унмада — психоз"},{"type":"verse","number":"1","sanskrit":"मदयन्त्युद्धता दोषा यस्मादुन्मार्गमाश्रिताः मानसोऽयमतो व्याधिरुन्माद इति कीर्त्तितः","text":"madayantyuddhatā doṣā yasmādunmārgamāśritāḥ mānaso'yamato vyādhirunmāda iti kīrttitaḥ"},{"type":"verse","number":"2","sanskrit":"स चाप्रवृद्धस्तरुणो मदसंज्ञां बिभर्त्ति च","text":"sa cāpravṛddhastaruṇo madasaṃjñāṃ bibhartti ca"},{"type":"verse","number":"3","sanskrit":"विरुद्धदुष्टाशुचिभोजनानि प्रधर्षणं देवगुरुद्विजानाम् उन्मादहेतुर्भयहर्षपूर्वो मनोऽभिघातो विषमा च चेष्टा","text":"viruddhaduṣṭāśucibhojanāni pradharṣaṇaṃ devagurudvijānām unmādaheturbhayaharṣapūrvo mano'bhighāto viṣamā ca ceṣṭā"},{"type":"verse","number":"4","sanskrit":"एकैकशः सर्वशश्च दोषैरत्यर्थमूर्च्छितैः मानसेन च दुःखेन स पञ्चविध उच्यते विषाद्भवति षष्ठश्च यथास्वं तत्र भेषजम्","text":"ekaikaśaḥ sarvaśaśca doṣairatyarthamūrcchitaiḥ mānasena ca duḥkhena sa pañcavidha ucyate viṣādbhavati ṣaṣṭhaśca yathāsvaṃ tatra bheṣajam"},{"type":"verse","number":"5","sanskrit":"तैरल्पसत्त्वस्य मलाः प्रदुष्टा बुद्धेर्निवासं हृदयं प्रदूष्य स्रोतांस्यधिष्ठाय मनोवहानि प्रमोहयन्त्याशु नरस्य चेतः","text":"tairalpasattvasya malāḥ praduṣṭā buddhernivāsaṃ hṛdayaṃ pradūṣya srotāṃsyadhiṣṭhāya manovahāni pramohayantyāśu narasya cetaḥ"},{"type":"verse","number":"6","sanskrit":"धीविभ्रमः सत्त्वपरिप्लवश्च पर्याकुला दृष्टिरधीरता च अबद्धवाक्यं हृदयञ्च शून्यं सामान्यमुन्मादगदस्य लिङ्गम्","text":"dhīvibhramaḥ sattvapariplavaśca paryākulā dṛṣṭiradhīratā ca abaddhavākyaṃ hṛdayañca śūnyaṃ sāmānyamunmādagadasya liṅgam"},{"type":"verse","number":"7","sanskrit":"रुक्षाल्पशीतान्नविरेकधातुक्ष योपवासैरनिलोऽतिवृद्धः चिन्ताऽदिदुष्टं हृदयं प्रदूष्य बुद्धिं स्मृतिं चाप्युपहन्ति शीघ्रम्","text":"rukṣālpaśītānnavirekadhātukṣa yopavāsairanilo'tivṛddhaḥ cintā'diduṣṭaṃ hṛdayaṃ pradūṣya buddhiṃ smṛtiṃ cāpyupahanti śīghram"},{"type":"verse","number":"8","sanskrit":"अस्थानहास्यस्मितनृत्यगीतवा गङ्गविक्षेपणरोदनानि पारुष्यकार्श्यारुणवर्णताश्च जीर्णे बलञ्चानिलजस्य रूपम्","text":"asthānahāsyasmitanṛtyagītavā gaṅgavikṣepaṇarodanāni pāruṣyakārśyāruṇavarṇatāśca jīrṇe balañcānilajasya rūpam"},{"type":"verse","number":"9","sanskrit":"अजीर्णकट्वम्लविदाहशीतैर्भोज्यैश्चितं पित्तमुदीर्णवेगम् उन्मादमत्युग्रमनात्मकस्य हृदि स्थितं पूर्ववदाशु कुर्यात्","text":"ajīrṇakaṭvamlavidāhaśītairbhojyaiścitaṃ pittamudīrṇavegam unmādamatyugramanātmakasya hṛdi sthitaṃ pūrvavadāśu kuryāt"},{"type":"verse","number":"10","sanskrit":"अमर्षसंरम्भविनग्नभावाः सन्तर्जनाभिद्र वणौष्ण्यरोषाः प्रच्छायशीतान्नजलाभिलाषा पीता च भा पित्तकृतस्य लिङ्गम्","text":"amarṣasaṃrambhavinagnabhāvāḥ santarjanābhidra vaṇauṣṇyaroṣāḥ pracchāyaśītānnajalābhilāṣā pītā ca bhā pittakṛtasya liṅgam"},{"type":"verse","number":"11","sanskrit":"सम्पूरणैर्मन्दविचेष्टितस्य सोष्मा कफो मर्मणि सम्प्रवृद्धः बुद्धिं स्मृतिञ्चाप्युपहन्ति चित्तं प्रमोहयन्सञ्जनयेद्विकारम्","text":"sampūraṇairmandaviceṣṭitasya soṣmā kapho marmaṇi sampravṛddhaḥ buddhiṃ smṛtiñcāpyupahanti cittaṃ pramohayansañjanayedvikāram"},{"type":"verse","number":"12","sanskrit":"वाक्चेष्टितं मन्दमरोचकश्च नारीविविक्तप्रियता च निद्रा छर्दिश्च लाला च बलञ्च भुक्ते नखादिशौक्ल्यञ्च कफात्मके स्यात्","text":"vākceṣṭitaṃ mandamarocakaśca nārīviviktapriyatā ca nidrā chardiśca lālā ca balañca bhukte nakhādiśauklyañca kaphātmake syāt"},{"type":"verse","number":"13","sanskrit":"यः सन्निपातप्रभवोऽतिघोरः सर्वैः समस्तैः स तु हेतुभिः स्यात् सर्वाणि रूपाणि बिभर्त्ति तादृग्विरुद्धभैषज्यविधिर्विवर्ज्यः","text":"yaḥ sannipātaprabhavo'tighoraḥ sarvaiḥ samastaiḥ sa tu hetubhiḥ syāt sarvāṇi rūpāṇi bibhartti tādṛgviruddhabhaiṣajyavidhirvivarjyaḥ"},{"type":"verse","number":"14","sanskrit":"चौरैर्नरेन्द्र पुरुषैररिभिस्तथाऽन्यैर्वित्रासितस्य धनबान्धवसंक्षयाद्वा गाढं क्षते मनसि च प्रियया रिरंसोर्जायेत चोत्कटतरो मनसो विकारः","text":"caurairnarendra puruṣairaribhistathā'nyairvitrāsitasya dhanabāndhavasaṃkṣayādvā gāḍhaṃ kṣate manasi ca priyayā riraṃsorjāyeta cotkaṭataro manaso vikāraḥ"},{"type":"verse","number":"15","sanskrit":"चित्रं ब्रवीति च मनोऽनुगतं विसंज्ञो गायत्यथो हसति रोदिति चातिमूढः","text":"citraṃ bravīti ca mano'nugataṃ visaṃjño gāyatyatho hasati roditi cātimūḍhaḥ"},{"type":"verse","number":"16","sanskrit":"रक्तेक्षणो हतबलेन्द्रि यभाः सुदीनः श्यावाननो विषकृते तु भवेत्परासुः","text":"raktekṣaṇo hatabalendri yabhāḥ sudīnaḥ śyāvānano viṣakṛte tu bhavetparāsuḥ"},{"type":"verse","number":"17","sanskrit":"अवाङ्मुखस्तून्मुखो वा क्षीणमांसबलो नरः जागरूको ह्यसन्देहमुन्मादेन विनश्यति","text":"avāṅmukhastūnmukho vā kṣīṇamāṃsabalo naraḥ jāgarūko hyasandehamunmādena vinaśyati"},{"type":"verse","number":"18","sanskrit":"अमत्तर्यवाग्विक्रमवीर्यचेष्टो ज्ञानादिविज्ञानबलादियुक्तः प्रकोपकालो नियतश्च यस्य देवादिजन्मा मनसो विकारः","text":"amattaryavāgvikramavīryaceṣṭo jñānādivijñānabalādiyuktaḥ prakopakālo niyataśca yasya devādijanmā manaso vikāraḥ"},{"type":"verse","number":"19","sanskrit":"सन्तुष्टः शुचिरतिदिव्यमाल्यगन्धो निस्तन्द्रो ऽप्यवितथसंस्कृतप्रभाषी तेजस्वी स्थिरनयनो वरप्रदाता ब्रह्मण्यो भवति नरः स देवजुष्टः","text":"santuṣṭaḥ śuciratidivyamālyagandho nistandro 'pyavitathasaṃskṛtaprabhāṣī tejasvī sthiranayano varapradātā brahmaṇyo bhavati naraḥ sa devajuṣṭaḥ"},{"type":"verse","number":"20","sanskrit":"संस्वेदी द्विजगुरुदेवदोषवक्ता जिह्माक्षो विगतभयो विमार्गदृष्टिः सन्तुष्टो भवति न चान्नपानजातैर्दुष्टात्मा भवति स देवशत्रुजुष्टः","text":"saṃsvedī dvijagurudevadoṣavaktā jihmākṣo vigatabhayo vimārgadṛṣṭiḥ santuṣṭo bhavati na cānnapānajātairduṣṭātmā bhavati sa devaśatrujuṣṭaḥ"},{"type":"verse","number":"21","sanskrit":"हृष्टात्मा पुलिनवनान्तरोपसेवी स्वाचारः प्रियपरिगीतगन्धमाल्यः नृत्यन्वै प्रहसति चारु चाल्पशब्दं गन्धर्वग्रहपरिपीडितो मनुष्यः","text":"hṛṣṭātmā pulinavanāntaropasevī svācāraḥ priyaparigītagandhamālyaḥ nṛtyanvai prahasati cāru cālpaśabdaṃ gandharvagrahaparipīḍito manuṣyaḥ"},{"type":"verse","number":"22","sanskrit":"ताम्राक्षः प्रियतनुरक्तवस्त्रधारी गम्भीरो द्रुतगतिरल्पवाक्सहिष्णुः तेजस्वी वदति च किं ददामि कस्मै यो यक्षग्रहपरिपीडितो मनुष्यः","text":"tāmrākṣaḥ priyatanuraktavastradhārī gambhīro drutagatiralpavāksahiṣṇuḥ tejasvī vadati ca kiṃ dadāmi kasmai yo yakṣagrahaparipīḍito manuṣyaḥ"},{"type":"verse","number":"23","sanskrit":"प्रेतानां स दिशति संस्तरेषु पिण्डाञ् शान्तात्मा जलमपि चापसव्यवस्त्रः मांसेप्सुस्तिलगुडपायसाभिलाषी तद्भक्तो भवति पितृग्रहाभिजुष्टः","text":"pretānāṃ sa diśati saṃstareṣu piṇḍāñ śāntātmā jalamapi cāpasavyavastraḥ māṃsepsustilaguḍapāyasābhilāṣī tadbhakto bhavati pitṛgrahābhijuṣṭaḥ"},{"type":"verse","number":"24","sanskrit":"यस्तूर्व्यां प्रसरति सर्पवत्कदाचित् सृक्किण्यौ मुहुरपि जिह्वयाऽवलेढि क्रोधालुर्घृतमधुदुग्धपायसेप्सुर्विज्ञेयः स खलु भुजङ्गमेन जुष्टः","text":"yastūrvyāṃ prasarati sarpavatkadācit sṛkkiṇyau muhurapi jihvayā'valeḍhi krodhālurghṛtamadhudugdhapāyasepsurvijñeyaḥ sa khalu bhujaṅgamena juṣṭaḥ"},{"type":"verse","number":"25","sanskrit":"मांसासृग्विविधसुराविकारलिप्सुर्निर्लज्जो भृशमतिनिष्ठुरोऽतिशूरः क्रोधालुर्विविधबलो निशाविहारी शौचद्विड् भवति स राक्षसैर्गृहीतः","text":"māṃsāsṛgvividhasurāvikāralipsurnirlajjo bhṛśamatiniṣṭhuro'tiśūraḥ krodhālurvividhabalo niśāvihārī śaucadviḍ bhavati sa rākṣasairgṛhītaḥ"},{"type":"verse","number":"26","sanskrit":"देवविप्रगुरुद्वेषी वेदवेदाङ्गनिन्दकः आत्मपीडाकरोऽहिस्रो ब्रह्मराक्षससेवितः","text":"devavipragurudveṣī vedavedāṅganindakaḥ ātmapīḍākaro'hisro brahmarākṣasasevitaḥ"},{"type":"verse","number":"27","sanskrit":"उद्बस्त्रः कृशपरुषो विरुद्धभाषी दुर्गन्धो भृशमशुचिस्तथाऽतिलोलः बह्वाशी विजनवनान्तरोपसेवी व्याचेष्टंस्त्रसति रुदन्पिशाचजुष्टः","text":"udbastraḥ kṛśaparuṣo viruddhabhāṣī durgandho bhṛśamaśucistathā'tilolaḥ bahvāśī vijanavanāntaropasevī vyāceṣṭaṃstrasati rudanpiśācajuṣṭaḥ"},{"type":"verse","number":"28","sanskrit":"स्थूलाक्षो द्रुतमटनः सफेनवामी निद्रा लुः पतति च कम्पते च योऽति यश्चाद्रि द्विरदनगादिविच्युतः स्यात्सोऽसाध्यो भवति तथा त्रयोदशेऽब्दे","text":"sthūlākṣo drutamaṭanaḥ saphenavāmī nidrā luḥ patati ca kampate ca yo'ti yaścādri dviradanagādivicyutaḥ syātso'sādhyo bhavati tathā trayodaśe'bde"},{"type":"verse","number":"29","sanskrit":"देवग्रहाः पौर्णमास्यामसुराः सन्ध्ययोरपि गन्धर्वाः प्रायशोऽष्टम्यां यक्षाश्च प्रतिपद्यथ","text":"devagrahāḥ paurṇamāsyāmasurāḥ sandhyayorapi gandharvāḥ prāyaśo'ṣṭamyāṃ yakṣāśca pratipadyatha"},{"type":"verse","number":"30","sanskrit":"पितरः कृष्णपक्षे च पञ्चम्यामपि चोरगाः रक्षःपिशाचा रात्रौ च चतुर्दश्यां विशन्ति हि","text":"pitaraḥ kṛṣṇapakṣe ca pañcamyāmapi coragāḥ rakṣaḥpiśācā rātrau ca caturdaśyāṃ viśanti hi"},{"type":"verse","number":"31","sanskrit":"वातिके स्नेहपानं प्राग्विरेकः पित्तसम्भवे कफजे वमनं कार्यं परो वस्त्यादिकः क्रम यच्चोपद्रे क्ष्यते किञ्चिदपस्मारे चिकित्सितम् उन्मादे तच्च कर्त्तव्यं सामान्याद् दोषदूष्ययोः","text":"vātike snehapānaṃ prāgvirekaḥ pittasambhave kaphaje vamanaṃ kāryaṃ paro vastyādikaḥ krama yaccopadre kṣyate kiñcidapasmāre cikitsitam unmāde tacca karttavyaṃ sāmānyād doṣadūṣyayoḥ"},{"type":"verse","number":"32","sanskrit":"जलाग्निद्रुमशैलेभ्यो विषमेभ्यश्च तं सदा रक्षेदुन्मादिनं यत्नात्सद्यः प्राणहरं हि तत्","text":"jalāgnidrumaśailebhyo viṣamebhyaśca taṃ sadā rakṣedunmādinaṃ yatnātsadyaḥ prāṇaharaṃ hi tat"},{"type":"verse","number":"33","sanskrit":"ब्राह्मीकूष्माण्डीफलषड्ग्रन्थाशङ्खपुष्पिकास्वरसाः दृष्टा उन्मादहृतः पृथगेते कुष्ठमधुमिश्राः","text":"brāhmīkūṣmāṇḍīphalaṣaḍgranthāśaṅkhapuṣpikāsvarasāḥ dṛṣṭā unmādahṛtaḥ pṛthagete kuṣṭhamadhumiśrāḥ"},{"type":"verse","number":"34","sanskrit":"सिद्धार्थको हिङ्गु वचा करञ्जो देवदारु च मञ्जिष्ठा त्रिफला श्वेता कटभी त्वक् कटुत्रयम्","text":"siddhārthako hiṅgu vacā karañjo devadāru ca mañjiṣṭhā triphalā śvetā kaṭabhī tvak kaṭutrayam"},{"type":"verse","number":"35","sanskrit":"समांशानि प्रियङ्गुश्च शिरीषो रजनीद्वयम् बस्तमूत्रेण पिष्टोऽयमगदः पानमञ्जनम्","text":"samāṃśāni priyaṅguśca śirīṣo rajanīdvayam bastamūtreṇa piṣṭo'yamagadaḥ pānamañjanam"},{"type":"verse","number":"36","sanskrit":"नस्यमालेपनञ्चैव स्नानमुद्वर्त्तनं तथा अपस्मारविषोन्मादकृत्याऽलक्ष्मीज्वरापहम्","text":"nasyamālepanañcaiva snānamudvarttanaṃ tathā apasmāraviṣonmādakṛtyā'lakṣmījvarāpaham"},{"type":"verse","number":"37","sanskrit":"भूतेभ्यश्च भयं हन्ति राजद्वारे च शस्यते सर्पिरेतेन संसिद्धं सगोमूत्रं तदर्थकृत्","text":"bhūtebhyaśca bhayaṃ hanti rājadvāre ca śasyate sarpiretena saṃsiddhaṃ sagomūtraṃ tadarthakṛt"},{"type":"verse","number":"38","sanskrit":"ब्रूयादिष्टविनाशञ्च दर्शयेदद्भुतानि च बद्धं सर्षपतैलाक्तं रक्षेदुत्तानमातपे","text":"brūyādiṣṭavināśañca darśayedadbhutāni ca baddhaṃ sarṣapatailāktaṃ rakṣeduttānamātape"},{"type":"verse","number":"39","sanskrit":"कपिकच्छ्वाऽथ वा तप्तैर्लोहतैलजलैः स्पृशेत् कशाभिस्ताडयेत्तं वा सुबद्धं विजने गृहे","text":"kapikacchvā'tha vā taptairlohatailajalaiḥ spṛśet kaśābhistāḍayettaṃ vā subaddhaṃ vijane gṛhe"},{"type":"verse","number":"40","sanskrit":"सर्पेणोद्धृतदंष्ट्रेण दशेत्सिंहैर्गजैश्च तम् त्रासयेच्छस्त्रहस्तैश्च शत्रुभिस्तस्करैस्तथा","text":"sarpeṇoddhṛtadaṃṣṭreṇa daśetsiṃhairgajaiśca tam trāsayecchastrahastaiśca śatrubhistaskaraistathā"},{"type":"verse","number":"41","sanskrit":"अथवा राजपुरुषा बहिर्नीत्वा सुसंयतम् त्रासयेयुर्वधैरेनं तर्जयन्तो नृपाज्ञया","text":"athavā rājapuruṣā bahirnītvā susaṃyatam trāsayeyurvadhairenaṃ tarjayanto nṛpājñayā"},{"type":"verse","number":"42","sanskrit":"देहदुःखभयेभ्यो हि यतः प्राणभयं भवेत् ततस्तस्य शमं याति सर्वतो विप्लुतं मनः","text":"dehaduḥkhabhayebhyo hi yataḥ prāṇabhayaṃ bhavet tatastasya śamaṃ yāti sarvato viplutaṃ manaḥ"},{"type":"verse","number":"43","sanskrit":"इष्टद्र व्यविनाशेन मनो यस्याभिहन्यते तस्य तत्सदृशप्राप्त्या ज्ञात्वाऽश्वासैः शमं नयेत्","text":"iṣṭadra vyavināśena mano yasyābhihanyate tasya tatsadṛśaprāptyā jñātvā'śvāsaiḥ śamaṃ nayet"},{"type":"verse","number":"44","sanskrit":"त्र्यूषणं हिङ्गु लवणं वचा कटुकरोहिणी शिरीषस्य करञ्जस्य बीजं गौराश्च सर्षपाः","text":"tryūṣaṇaṃ hiṅgu lavaṇaṃ vacā kaṭukarohiṇī śirīṣasya karañjasya bījaṃ gaurāśca sarṣapāḥ"},{"type":"verse","number":"45","sanskrit":"गोमूत्रपिष्टैरेभिस्तु वर्तिर्नेत्राञ्जने हिता हन्त्युन्मादमपस्मारं तथा चातुर्थकं ज्वरम्","text":"gomūtrapiṣṭairebhistu vartirnetrāñjane hitā hantyunmādamapasmāraṃ tathā cāturthakaṃ jvaram"},{"type":"verse","number":"46","sanskrit":"कुष्ठाश्वगन्धे लवणाजमोदे द्वेजीरके त्रीणि कटूनि पाठा मङ्गल्यपुष्पी च समान्यमूनि सर्वैः समानाञ्च वचां विचूर्ण्य","text":"kuṣṭhāśvagandhe lavaṇājamode dvejīrake trīṇi kaṭūni pāṭhā maṅgalyapuṣpī ca samānyamūni sarvaiḥ samānāñca vacāṃ vicūrṇya"},{"type":"verse","number":"47","sanskrit":"ब्राह्मीरसेनाखिलमेव भाव्यं वारत्रयं शुष्कमिदं हि चूर्णम् अक्षप्रमाणं मधुना घृतेन लिह्यान्नरः सप्त दिनानि चूर्णम्","text":"brāhmīrasenākhilameva bhāvyaṃ vāratrayaṃ śuṣkamidaṃ hi cūrṇam akṣapramāṇaṃ madhunā ghṛtena lihyānnaraḥ sapta dināni cūrṇam"},{"type":"verse","number":"48","sanskrit":"सारस्वतमिदं चूर्णं ब्रह्मणा निर्मितं पुरा हिताय सर्वलोकानां दुर्मेधानां विचेतसाम्","text":"sārasvatamidaṃ cūrṇaṃ brahmaṇā nirmitaṃ purā hitāya sarvalokānāṃ durmedhānāṃ vicetasām"},{"type":"verse","number":"49","sanskrit":"एतस्याभ्यासतः पुंसां बुद्धिर्मेधा धृतिः स्मृतिः सम्पत्तिः कविताशक्तिः प्रवर्द्धेतोत्तरोत्तरम्","text":"etasyābhyāsataḥ puṃsāṃ buddhirmedhā dhṛtiḥ smṛtiḥ sampattiḥ kavitāśaktiḥ pravarddhetottarottaram"},{"type":"verse","number":"50","sanskrit":"विश्वाऽजमोदरजनीद्वयसैन्धवोग्रायष्ट्याह्वकुष्ठमगधोद्भवजीरकाणाम् चूर्णं प्रभातसमये लिहतः ससर्पिर्वाग्देवता निवसति स्वयमेव वक्त्रे","text":"viśvā'jamodarajanīdvayasaindhavogrāyaṣṭyāhvakuṣṭhamagadhodbhavajīrakāṇām cūrṇaṃ prabhātasamaye lihataḥ sasarpirvāgdevatā nivasati svayameva vaktre"},{"type":"verse","number":"51","sanskrit":"क्वाथे विचूर्णिते क्षिप्त्वा तत्षोडशगुणं जलम् पादशेषं प्रकर्त्तव्यमेष क्वाथविधिः स्मृतः","text":"kvāthe vicūrṇite kṣiptvā tatṣoḍaśaguṇaṃ jalam pādaśeṣaṃ prakarttavyameṣa kvāthavidhiḥ smṛtaḥ"},{"type":"verse","number":"52","sanskrit":"दशमूली तथा रास्ना वातारिस्त्रिवृता बला मूर्वा शतावरी चेति क्वाथैस्तु कुडवैः पृथक्","text":"daśamūlī tathā rāsnā vātāristrivṛtā balā mūrvā śatāvarī ceti kvāthaistu kuḍavaiḥ pṛthak"},{"type":"verse","number":"53","sanskrit":"कृतैः क्वाथैर्घृतप्रस्थद्वयं मृद्वग्निना पचेत् कल्कीकृतैर्वक्ष्यमाणद्र व्यैः सम्यक् पुनः पचेत्","text":"kṛtaiḥ kvāthairghṛtaprasthadvayaṃ mṛdvagninā pacet kalkīkṛtairvakṣyamāṇadra vyaiḥ samyak punaḥ pacet"},{"type":"verse","number":"54","sanskrit":"विशाला त्रिफला कौन्ती देवदार्वेलवालुकम् स्थिराऽनन्ता रजन्यौ द्वे प्रियङ्गुः सारिवाद्वयम्","text":"viśālā triphalā kauntī devadārvelavālukam sthirā'nantā rajanyau dve priyaṅguḥ sārivādvayam"},{"type":"verse","number":"55","sanskrit":"नीलोत्पलैला मञ्जिष्ठा दन्ती दाडिमकेसरम् विडङ्गं ह्यग्निपत्री च कुष्ठं चन्दनपद्मके","text":"nīlotpalailā mañjiṣṭhā dantī dāḍimakesaram viḍaṅgaṃ hyagnipatrī ca kuṣṭhaṃ candanapadmake"},{"type":"verse","number":"56","sanskrit":"तालीशपत्रं बृहती मालतीकुसुमं नवम् अष्टाविंशतिभिः कल्कैरेतैः कर्षमितैः पृथक्","text":"tālīśapatraṃ bṛhatī mālatīkusumaṃ navam aṣṭāviṃśatibhiḥ kalkairetaiḥ karṣamitaiḥ pṛthak"},{"type":"verse","number":"57","sanskrit":"चतुर्गुणं जलं दत्वा पिष्टैस्तद्विपचेद् घृतम् महाचैतसनामेदं सर्वचेतोविकारनुत्","text":"caturguṇaṃ jalaṃ datvā piṣṭaistadvipaced ghṛtam mahācaitasanāmedaṃ sarvacetovikāranut"},{"type":"verse","number":"58","sanskrit":"अपस्मारे महोन्मादे मन्देऽग्नौ ज्वरकासयोः वातरक्ते प्रतिश्याये शोषे कार्श्ये तृतीयके","text":"apasmāre mahonmāde mande'gnau jvarakāsayoḥ vātarakte pratiśyāye śoṣe kārśye tṛtīyake"},{"type":"verse","number":"59","sanskrit":"म्रूत्रकृच्छ्रे कटीशूले विसर्पाभिहतेषु च पाण्ड्वामये तथा कण्ड्वां विषे मेहे गरेऽपि च","text":"mrūtrakṛcchre kaṭīśūle visarpābhihateṣu ca pāṇḍvāmaye tathā kaṇḍvāṃ viṣe mehe gare'pi ca"},{"type":"verse","number":"60","sanskrit":"देवादिहतचित्तानां गद्गदानामचेतसाम् शस्तं स्त्रीणाञ्च वन्ध्यानां धन्यमायुर्बलप्रदम्","text":"devādihatacittānāṃ gadgadānāmacetasām śastaṃ strīṇāñca vandhyānāṃ dhanyamāyurbalapradam"},{"type":"verse","number":"61","sanskrit":"अलक्ष्मी पापरक्षोध्नं सर्वग्रहनिवारणम् हन्ति भ्रमं मदं मूर्च्छां मेधास्मृतिमतिप्रदम्","text":"alakṣmī pāparakṣodhnaṃ sarvagrahanivāraṇam hanti bhramaṃ madaṃ mūrcchāṃ medhāsmṛtimatipradam"},{"type":"verse","number":"62","sanskrit":"पूजाबल्युपहारेष्टिहोममन्त्राञ्जनादिभिः जयेदागन्तुमुन्मादं यथाविधि शुचिर्भिषक्","text":"pūjābalyupahāreṣṭihomamantrāñjanādibhiḥ jayedāgantumunmādaṃ yathāvidhi śucirbhiṣak"},{"type":"verse","number":"63","sanskrit":"कृष्णामरिचसिन्धूत्थमधुगोरोचनाकृतम् अञ्जनं सर्वदेवादिकृतोन्मादहरं परम्","text":"kṛṣṇāmaricasindhūtthamadhugorocanākṛtam añjanaṃ sarvadevādikṛtonmādaharaṃ param"},{"type":"verse","number":"64","sanskrit":"ॠक्षजम्बुकलोमानि शल्लकी लशुनं तथा हिङ्गु मूत्रञ्च बस्तस्य धूममस्य प्रयोजयेत् एतेन शाम्यति क्षिप्रं बलवानपि यो ग्रहः","text":"ṝkṣajambukalomāni śallakī laśunaṃ tathā hiṅgu mūtrañca bastasya dhūmamasya prayojayet etena śāmyati kṣipraṃ balavānapi yo grahaḥ"},{"type":"verse","number":"65","sanskrit":"कल्याणकञ्च युञ्जीत महद् वा चैतसं घृतम् तैलं नारायणं वाऽथ महानारायणं तथा","text":"kalyāṇakañca yuñjīta mahad vā caitasaṃ ghṛtam tailaṃ nārāyaṇaṃ vā'tha mahānārāyaṇaṃ tathā"},{"type":"verse","number":"66","sanskrit":"ॠते पिशाचादन्येषु प्रतिकूलं न वाऽचरेत् रोगिणंभिषजं यत्ते क्रुद्धा हन्युर्महौजसः","text":"ṝte piśācādanyeṣu pratikūlaṃ na vā'caret rogiṇaṃbhiṣajaṃ yatte kruddhā hanyurmahaujasaḥ"},{"type":"verse","number":"67","sanskrit":"इति द्वाविंश उन्मादाधिकारः समाप्तः २२","text":"iti dvāviṃśa unmādādhikāraḥ samāptaḥ 22"}]},{"sthana":"Уттаракханда","number":23,"lang":"sa","content":[{"type":"heading","heading":"Апасмара — эпилепсия"},{"type":"verse","number":"1","sanskrit":"चिन्ताशोकादिभिर्दोषाः क्रुद्धा हृत्स्रोतसि स्थिताः कृत्वा स्मृतेरपध्वंसमपस्मारं प्रकुर्वते","text":"cintāśokādibhirdoṣāḥ kruddhā hṛtsrotasi sthitāḥ kṛtvā smṛterapadhvaṃsamapasmāraṃ prakurvate"},{"type":"verse","number":"2","sanskrit":"वातात्पित्तात्कफात्सर्वैर्दोषैः स स्याच्चतुर्विधः","text":"vātātpittātkaphātsarvairdoṣaiḥ sa syāccaturvidhaḥ"},{"type":"verse","number":"3","sanskrit":"तमःप्रवेशः संरम्भो दोषोद्रे कहतस्मृतेः अपस्मार इति ज्ञेयो गदो घोरतरो हि सः","text":"tamaḥpraveśaḥ saṃrambho doṣodre kahatasmṛteḥ apasmāra iti jñeyo gado ghorataro hi saḥ"},{"type":"verse","number":"4","sanskrit":"हृत्कम्पः शून्यता स्वेदो ध्यानं मूर्च्छा प्रमूढता निद्रा नाशश्च तस्मिंश्च भविष्यति भवत्यथ","text":"hṛtkampaḥ śūnyatā svedo dhyānaṃ mūrcchā pramūḍhatā nidrā nāśaśca tasmiṃśca bhaviṣyati bhavatyatha"},{"type":"verse","number":"5","sanskrit":"कम्पते प्रदशेद्दन्तान्फेनोद्वामी श्वसित्यपि अभितोऽरुणवर्णानि पश्येद्रू पाणि चानिलात्","text":"kampate pradaśeddantānphenodvāmī śvasityapi abhito'ruṇavarṇāni paśyedrū pāṇi cānilāt"},{"type":"verse","number":"6","sanskrit":"पीतफेनाङ्गवक्त्राक्षः पीतासृगूपदर्शनः सतृष्णोष्णानलव्याप्तलोकदर्शी च पैत्तिके","text":"pītaphenāṅgavaktrākṣaḥ pītāsṛgūpadarśanaḥ satṛṣṇoṣṇānalavyāptalokadarśī ca paittike"},{"type":"verse","number":"7","sanskrit":"शुक्लफेनाङ्गवक्त्राक्षः शीतो हृष्टाङ्गजो गुरुः पश्येच्छुक्लानि रूपाणि श्लैष्मिको मुच्यते चिरात्","text":"śuklaphenāṅgavaktrākṣaḥ śīto hṛṣṭāṅgajo guruḥ paśyecchuklāni rūpāṇi ślaiṣmiko mucyate cirāt"},{"type":"verse","number":"8","sanskrit":"समस्तैर्लक्षणैरेतैर्वि ज्ञातव्यस्त्रिदोषजः अपस्मारः स चासाध्यो यः क्षीणस्यानवश्च यः","text":"samastairlakṣaṇairetairvi jñātavyastridoṣajaḥ apasmāraḥ sa cāsādhyo yaḥ kṣīṇasyānavaśca yaḥ"},{"type":"verse","number":"9","sanskrit":"प्रस्फुरन्तञ्च बहुशः क्षीणं प्रचलितभ्रुवम् नेत्राभ्याञ्च विकुर्वाणमपस्मारो विनाशयेत्","text":"prasphurantañca bahuśaḥ kṣīṇaṃ pracalitabhruvam netrābhyāñca vikurvāṇamapasmāro vināśayet"},{"type":"verse","number":"10","sanskrit":"पक्षाद्वा द्वादशाहाद्वा मासाद्वा कुपिता मलाः अपस्मारं प्रकुर्वन्ति वेगं किञ्चिदथान्तरम्","text":"pakṣādvā dvādaśāhādvā māsādvā kupitā malāḥ apasmāraṃ prakurvanti vegaṃ kiñcidathāntaram"},{"type":"verse","number":"11","sanskrit":"तैलेन लशुनः सेव्यः पयसा च शतावरी ब्राह्मीरसश्च मधुना सर्वापस्मारभेषजम्","text":"tailena laśunaḥ sevyaḥ payasā ca śatāvarī brāhmīrasaśca madhunā sarvāpasmārabheṣajam"},{"type":"verse","number":"12","sanskrit":"चूर्णः सिद्धार्थकादीनां भक्षितैरथवाऽपि तैः गोमूत्रपिष्टैः सर्वाङ्गलेपैः शाम्यत्यपस्मृतिः","text":"cūrṇaḥ siddhārthakādīnāṃ bhakṣitairathavā'pi taiḥ gomūtrapiṣṭaiḥ sarvāṅgalepaiḥ śāmyatyapasmṛtiḥ"},{"type":"verse","number":"13","sanskrit":"सिद्धार्थशिग्रुकट्वङ्गकिणिहीभिः प्रलेपनम् चतुर्गुणे गवां मूत्रे तैलमभ्यञ्जने हितम्","text":"siddhārthaśigrukaṭvaṅgakiṇihībhiḥ pralepanam caturguṇe gavāṃ mūtre tailamabhyañjane hitam"},{"type":"verse","number":"14","sanskrit":"निर्गुण्डीभववन्दाकनावनस्य प्रयोगतः उपैति सहसा नाशमपस्मारो महागदः","text":"nirguṇḍībhavavandākanāvanasya prayogataḥ upaiti sahasā nāśamapasmāro mahāgadaḥ"},{"type":"verse","number":"15","sanskrit":"मनोह्वा तार्क्ष्यविष्ठा च शकृत्पारावतस्य च अञ्जनाद्धन्त्यपस्मारमुन्मादञ्च विशेषतः","text":"manohvā tārkṣyaviṣṭhā ca śakṛtpārāvatasya ca añjanāddhantyapasmāramunmādañca viśeṣataḥ"},{"type":"verse","number":"16","sanskrit":"यः खादेत् क्षीरभक्ताशी माक्षिकेण वचारजः अपस्मारं महाघोरं चिरोत्थं स जयेद् ध्रुवम्","text":"yaḥ khādet kṣīrabhaktāśī mākṣikeṇa vacārajaḥ apasmāraṃ mahāghoraṃ cirotthaṃ sa jayed dhruvam"},{"type":"verse","number":"17","sanskrit":"कूष्माण्डकफलोत्थेन रसेन परिपेषितम् अपस्मारविनाशाय यष्ट्याह्वं स पिबेत्त्र्यहम्","text":"kūṣmāṇḍakaphalotthena rasena paripeṣitam apasmāravināśāya yaṣṭyāhvaṃ sa pibettryaham"},{"type":"verse","number":"18","sanskrit":"ब्राह्मीरसवचाकुष्ठशङ्खपुष्पीशृतं घृतम् पुराणं स्यादपस्मारोन्मादग्रहहरं परम्","text":"brāhmīrasavacākuṣṭhaśaṅkhapuṣpīśṛtaṃ ghṛtam purāṇaṃ syādapasmāronmādagrahaharaṃ param"},{"type":"verse","number":"19","sanskrit":"कूष्माण्डकरसे सर्पिरष्टादशगुणे पचेत् यष्ट्याह्वकल्कं तत्पानमपस्मारविनाशनम्","text":"kūṣmāṇḍakarase sarpiraṣṭādaśaguṇe pacet yaṣṭyāhvakalkaṃ tatpānamapasmāravināśanam"},{"type":"verse","number":"20","sanskrit":"हृत्कम्पोऽक्षिरुजा यस्य स्वेदो हस्तादिशीतता दशमूलीजलं तस्य कल्याणाख्यं प्रयोजयेत्","text":"hṛtkampo'kṣirujā yasya svedo hastādiśītatā daśamūlījalaṃ tasya kalyāṇākhyaṃ prayojayet"},{"type":"verse","number":"21","sanskrit":"पञ्चकोलं समरिचं त्रिफला विडसैन्धवम् कृष्णाविडङ्गपूतीकयवानीधान्यजीरकम् पीतमुष्णाम्बुना चूर्णं वातश्लेष्मामयापहम्","text":"pañcakolaṃ samaricaṃ triphalā viḍasaindhavam kṛṣṇāviḍaṅgapūtīkayavānīdhānyajīrakam pītamuṣṇāmbunā cūrṇaṃ vātaśleṣmāmayāpaham"},{"type":"verse","number":"22","sanskrit":"अपस्मारे तथोन्मादेऽप्यर्शसां ग्रहणीगदे एतत्कल्याणकं चूर्णं नष्टस्याग्नेश्च दीपनम्","text":"apasmāre tathonmāde'pyarśasāṃ grahaṇīgade etatkalyāṇakaṃ cūrṇaṃ naṣṭasyāgneśca dīpanam"},{"type":"verse","number":"23","sanskrit":"द्वौ कीटमेढ्रौ विधिवदानीय रविवासरे कण्ठे भुजे वा सन्धार्य जयेदुग्रामपस्मृतिम्","text":"dvau kīṭameḍhrau vidhivadānīya ravivāsare kaṇṭhe bhuje vā sandhārya jayedugrāmapasmṛtim"},{"type":"verse","number":"24","sanskrit":"शिग्रुकुष्ठजलाजाजीलशुनव्योषहिङ्गुभिः बस्तमूत्रे शृतं तैलं नावनं स्यादपस्मृतौ","text":"śigrukuṣṭhajalājājīlaśunavyoṣahiṅgubhiḥ bastamūtre śṛtaṃ tailaṃ nāvanaṃ syādapasmṛtau"},{"type":"verse","number":"25","sanskrit":"उन्मादेषु यदुद्दिष्टं पथ्यं नस्याञ्जनौषधम् अपस्मारेऽपि तत्सर्वं प्रयोक्तव्यं भिषग्वरैः","text":"unmādeṣu yaduddiṣṭaṃ pathyaṃ nasyāñjanauṣadham apasmāre'pi tatsarvaṃ prayoktavyaṃ bhiṣagvaraiḥ"},{"type":"verse","number":"26","sanskrit":"मृतसूताभ्रलोहञ्च शिलागन्धञ्च तालकम् रसाञ्जनञ्च तुल्यांशं नरमूत्रेण मर्दयेत्","text":"mṛtasūtābhralohañca śilāgandhañca tālakam rasāñjanañca tulyāṃśaṃ naramūtreṇa mardayet"},{"type":"verse","number":"27","sanskrit":"तद्गोलद्विगुणं गन्धं लौहपात्रे क्षणं पचेत् पञ्चगुञ्जोन्मितं भक्ष्यमपस्मारहरं परम्","text":"tadgoladviguṇaṃ gandhaṃ lauhapātre kṣaṇaṃ pacet pañcaguñjonmitaṃ bhakṣyamapasmāraharaṃ param"},{"type":"verse","number":"28","sanskrit":"व्योषं सौवर्चलं हिङ्गु नरमूत्रेऽजसर्पिषा पिबेत्कर्षमितं पश्चाद्र सोऽय भूतभैरवः","text":"vyoṣaṃ sauvarcalaṃ hiṅgu naramūtre'jasarpiṣā pibetkarṣamitaṃ paścādra so'ya bhūtabhairavaḥ"},{"type":"verse","number":"29","sanskrit":"इति त्रयोविंशोऽपस्माराधिकारः समाप्तः २३","text":"iti trayoviṃśo'pasmārādhikāraḥ samāptaḥ 23"}]},{"sthana":"Уттаракханда","number":24,"lang":"sa","content":[{"type":"heading","heading":"Вата-вьядхи — болезни Ваты"},{"type":"verse","number":"1","sanskrit":"कषायकटुतिक्तकप्रमितरुक्षलघ्वन्नतः पुरः पवनजागरप्रतरणाभिघातश्रमैः हिमादनशनात्तथा निधुवनाच्च धातुक्षयान्मलादिरयधारणान्मदनशोकचिन्ताभयैः","text":"kaṣāyakaṭutiktakapramitarukṣalaghvannataḥ puraḥ pavanajāgaraprataraṇābhighātaśramaiḥ himādanaśanāttathā nidhuvanācca dhātukṣayānmalādirayadhāraṇānmadanaśokacintābhayaiḥ"},{"type":"verse","number":"2","sanskrit":"अतिक्षतजमोक्षणाद्गदकृतातिमांसक्षयादतीववमनान्नृणामति विरेचनादामतः पयोदसमये दिनक्षण दयोस्तृतीयांश योर्ज रामति गतेऽशिते शिशिरसञ्ज्ञकालेऽपिच","text":"atikṣatajamokṣaṇādgadakṛtātimāṃsakṣayādatīvavamanānnṛṇāmati virecanādāmataḥ payodasamaye dinakṣaṇa dayostṛtīyāṃśa yorja rāmati gate'śite śiśirasañjñakāle'pica"},{"type":"verse","number":"3","sanskrit":"देहेस्रोतांसि रिक्तानि पूरयित्वाऽनिलो बली करोति विविधान् रोगान्सर्वाङ्गैकाङ्गसंश्रयान्","text":"dehesrotāṃsi riktāni pūrayitvā'nilo balī karoti vividhān rogānsarvāṅgaikāṅgasaṃśrayān"},{"type":"verse","number":"4","sanskrit":"शिरोग्रहोऽल्पकृशता जृम्भाऽत्यर्थं हनुग्रहः जिह्वास्तम्भो गद्गदत्वं मिन्मिनत्वञ्च मूकता","text":"śirograho'lpakṛśatā jṛmbhā'tyarthaṃ hanugrahaḥ jihvāstambho gadgadatvaṃ minminatvañca mūkatā"},{"type":"verse","number":"5","sanskrit":"वाचालता प्रलापञ्च रसानामनभिज्ञता बाधिर्यं कर्णनादश्च स्पर्शाज्ञत्वं तथाऽदितम्","text":"vācālatā pralāpañca rasānāmanabhijñatā bādhiryaṃ karṇanādaśca sparśājñatvaṃ tathā'ditam"},{"type":"verse","number":"6","sanskrit":"मन्यास्तम्भोऽत्र गणितो बाहुशोषोऽपबाहुकः वर्णिता चैव विश्वाची ऊर्द्ध्ववात उदीरितः","text":"manyāstambho'tra gaṇito bāhuśoṣo'pabāhukaḥ varṇitā caiva viśvācī ūrddhvavāta udīritaḥ"},{"type":"verse","number":"7","sanskrit":"आध्मानञ्च प्रत्याध्मानं वाताष्ठीला प्रतिष्ठीला तूनी च प्रतितूनी च वह्निवैषम्यमेव च","text":"ādhmānañca pratyādhmānaṃ vātāṣṭhīlā pratiṣṭhīlā tūnī ca pratitūnī ca vahnivaiṣamyameva ca"},{"type":"verse","number":"8","sanskrit":"आटोपः पार्श्वशूलञ्च त्रिकशूलं तथैव च मुहुश्च मूत्रणं मूत्रनिग्रहो मलगाढता","text":"āṭopaḥ pārśvaśūlañca trikaśūlaṃ tathaiva ca muhuśca mūtraṇaṃ mūtranigraho malagāḍhatā"},{"type":"verse","number":"9","sanskrit":"पुरीषस्याप्रवृत्तिश्च गृध्रसी च ततः परा कलायखञ्जता चापि खञ्जता पङ्गुता तथा","text":"purīṣasyāpravṛttiśca gṛdhrasī ca tataḥ parā kalāyakhañjatā cāpi khañjatā paṅgutā tathā"},{"type":"verse","number":"10","sanskrit":"क्रोष्टुशीर्षकखल्ल्यौ च वातकण्टक एव च पादहर्षः पाददाह आक्षेपो दण्डकाभिधः","text":"kroṣṭuśīrṣakakhallyau ca vātakaṇṭaka eva ca pādaharṣaḥ pādadāha ākṣepo daṇḍakābhidhaḥ"},{"type":"verse","number":"11","sanskrit":"वातपित्तकृताक्षेपस्तथा दण्डापतानकः अभिघातकृताक्षेप आयामो द्विविधः स्मृतः","text":"vātapittakṛtākṣepastathā daṇḍāpatānakaḥ abhighātakṛtākṣepa āyāmo dvividhaḥ smṛtaḥ"},{"type":"verse","number":"12","sanskrit":"आन्तरश्च तथा बाह्यो धनुर्वातश्च कुब्जकः अपतन्त्रोऽपतानश्च पक्षाघातः खिलाङ्गकः","text":"āntaraśca tathā bāhyo dhanurvātaśca kubjakaḥ apatantro'patānaśca pakṣāghātaḥ khilāṅgakaḥ"},{"type":"verse","number":"13","sanskrit":"कम्पः स्तम्भो व्यथा तोदो भेदश्च स्फुरणं तथा रौक्ष्यं कार्श्यञ्च कार्ष्ण्यञ्च शैत्यं लोम्नश्च हर्षणम्","text":"kampaḥ stambho vyathā todo bhedaśca sphuraṇaṃ tathā raukṣyaṃ kārśyañca kārṣṇyañca śaityaṃ lomnaśca harṣaṇam"},{"type":"verse","number":"14","sanskrit":"अङ्गमर्दोऽङ्गविभ्रंशः शिरासंकोच एव च अङ्गशोषश्च भीरुत्वं मोहश्च चलचित्तता","text":"aṅgamardo'ṅgavibhraṃśaḥ śirāsaṃkoca eva ca aṅgaśoṣaśca bhīrutvaṃ mohaśca calacittatā"},{"type":"verse","number":"15","sanskrit":"निद्रा नाशः स्वेदनाशो बलहानिस्तथैव च शुक्रक्षयो रजोनाशो गर्भनाशः परिभ्रमः","text":"nidrā nāśaḥ svedanāśo balahānistathaiva ca śukrakṣayo rajonāśo garbhanāśaḥ paribhramaḥ"},{"type":"verse","number":"16","sanskrit":"एत एवाशीतिसंख्या रोगा योगेन रूढितः वातव्याधीतिनामानो मुनिभिःपरिकीर्त्तिताः","text":"eta evāśītisaṃkhyā rogā yogena rūḍhitaḥ vātavyādhītināmāno munibhiḥparikīrttitāḥ"},{"type":"verse","number":"17","sanskrit":"मधुरलवणसाम्लस्निग्धस्योष्णनिद्रा गुरुरविकरवस्तिस्वेदसन्तर्पणानि दहनजलदशोषाभ्यङ्गसम्मर्दनानि प्रकुपितपवनानां शान्तिमेतानिकुर्युः","text":"madhuralavaṇasāmlasnigdhasyoṣṇanidrā gururavikaravastisvedasantarpaṇāni dahanajaladaśoṣābhyaṅgasammardanāni prakupitapavanānāṃ śāntimetānikuryuḥ"},{"type":"verse","number":"18","sanskrit":"अथ विशिष्टानां वातव्याधीनां लक्षणानि चिकित्सा च रक्तमाश्रित्य पवनः कुर्यान्मूर्द्धधराः शिराः रुक्षाः सवेदनाः कृष्णाः सोऽसाध्यः स्याच्छिरोग्रहः","text":"atha viśiṣṭānāṃ vātavyādhīnāṃ lakṣaṇāni cikitsā ca raktamāśritya pavanaḥ kuryānmūrddhadharāḥ śirāḥ rukṣāḥ savedanāḥ kṛṣṇāḥ so'sādhyaḥ syācchirograhaḥ"},{"type":"verse","number":"19","sanskrit":"शिरोग्रहे तु कर्त्तव्या शिरोगतमरुत्क्रिया दशमूलीकषायेण मातुलुङ्गरसेन च शृतेन तैलेनाभ्याङ्गः शिरोबस्तिश्च युज्यते","text":"śirograhe tu karttavyā śirogatamarutkriyā daśamūlīkaṣāyeṇa mātuluṅgarasena ca śṛtena tailenābhyāṅgaḥ śirobastiśca yujyate"},{"type":"verse","number":"20","sanskrit":"पीत्वैकं श्वासमनिलः पुनस्त्यजति वेगवान् आलस्यनिद्रा युक्तश्च स जृम्भ इति कथ्यते","text":"pītvaikaṃ śvāsamanilaḥ punastyajati vegavān ālasyanidrā yuktaśca sa jṛmbha iti kathyate"},{"type":"verse","number":"21","sanskrit":"शुण्ठी पिप्पल्यूषणं दीप्यकञ्च सिन्धूद्भूतं चेति सर्वे पृथग्वा तद्रू पं वा सूक्ष्मचूर्णीकृतं वा जृम्भाऽरम्भस्तम्भकृत्स्यात्तदेव","text":"śuṇṭhī pippalyūṣaṇaṃ dīpyakañca sindhūdbhūtaṃ ceti sarve pṛthagvā tadrū paṃ vā sūkṣmacūrṇīkṛtaṃ vā jṛmbhā'rambhastambhakṛtsyāttadeva"},{"type":"verse","number":"22","sanskrit":"जृम्भावेगे समुत्पन्ने शोभने शयने नरम् स्वापयेत्तेन नियमाज्जृम्भावेगः प्रशाम्यति","text":"jṛmbhāvege samutpanne śobhane śayane naram svāpayettena niyamājjṛmbhāvegaḥ praśāmyati"},{"type":"verse","number":"23","sanskrit":"जृम्भावेगःक्षयं याति कटुतैलेन मर्दनात् भोजनात्स्वादुभोज्यानां तथा ताम्बूलभक्षणात्","text":"jṛmbhāvegaḥkṣayaṃ yāti kaṭutailena mardanāt bhojanātsvādubhojyānāṃ tathā tāmbūlabhakṣaṇāt"},{"type":"verse","number":"24","sanskrit":"जिह्वानिर्लेखनाच्छुष्क भक्षणादभिघाततः कुपितो हनुमूलस्थः स्रंसयित्वानिलो हनुम्","text":"jihvānirlekhanācchuṣka bhakṣaṇādabhighātataḥ kupito hanumūlasthaḥ sraṃsayitvānilo hanum"},{"type":"verse","number":"25","sanskrit":"करोति विवृतास्यत्वमथ वा संवृतास्यताम् हनुग्रहः स तेन स्यात्कृच्छ्राच्चर्वणभाषणम्","text":"karoti vivṛtāsyatvamatha vā saṃvṛtāsyatām hanugrahaḥ sa tena syātkṛcchrāccarvaṇabhāṣaṇam"},{"type":"verse","number":"26","sanskrit":"संवृतं चिबुकं स्निग्धं स्विन्नमुन्नमयेद्भिषक् विवृतं नमयित्वा तु कुर्यात्प्राप्तामिह क्रियाम्","text":"saṃvṛtaṃ cibukaṃ snigdhaṃ svinnamunnamayedbhiṣak vivṛtaṃ namayitvā tu kuryātprāptāmiha kriyām"},{"type":"verse","number":"27","sanskrit":"पिप्पलीमार्द्र कञ्चापि सञ्चर्व्य च मुहुर्मुहुः निष्ठीवेत्तप्ततोयेन शोधयेद्वदनान्तरम्","text":"pippalīmārdra kañcāpi sañcarvya ca muhurmuhuḥ niṣṭhīvettaptatoyena śodhayedvadanāntaram"},{"type":"verse","number":"28","sanskrit":"निष्कुष्य लशुनं सम्यक्संक्षुद्य तिलतैलवत् सैन्धवेनान्वितं खादेद्धनुस्तम्भार्दितो नरः","text":"niṣkuṣya laśunaṃ samyaksaṃkṣudya tilatailavat saindhavenānvitaṃ khādeddhanustambhārdito naraḥ"},{"type":"verse","number":"29","sanskrit":"रसोनगुटिकामाषविदलं परिपेष्य च याजयेत्पिष्टिकां ताञ्च सैन्धवार्द्र कहिङ्गुभिः","text":"rasonaguṭikāmāṣavidalaṃ paripeṣya ca yājayetpiṣṭikāṃ tāñca saindhavārdra kahiṅgubhiḥ"},{"type":"verse","number":"30","sanskrit":"ततस्तु वटकान्कृत्वा तिलतैले पचेच्छनैः भक्षयेत्तान्यथावह्निं हनुस्तम्भात्सुखी भवेत्","text":"tatastu vaṭakānkṛtvā tilataile pacecchanaiḥ bhakṣayettānyathāvahniṃ hanustambhātsukhī bhavet"},{"type":"verse","number":"31","sanskrit":"अभ्यज्य पक्वतैलेन स्वेदयेन्मृदुनाग्नि वस्तिं विधारयेन्मूर्ध्नि तैलेन परिपूरितम्","text":"abhyajya pakvatailena svedayenmṛdunāgni vastiṃ vidhārayenmūrdhni tailena paripūritam"},{"type":"verse","number":"32","sanskrit":"समूलपत्रशाखायाः प्रसारण्याः शतं पलैः सम्यक्संक्षुद्य सलिले द्रो णमात्रे पचेद्भिषक्","text":"samūlapatraśākhāyāḥ prasāraṇyāḥ śataṃ palaiḥ samyaksaṃkṣudya salile dro ṇamātre pacedbhiṣak"},{"type":"verse","number":"33","sanskrit":"सलिलस्य चतुर्थाशं क्वाथं समवशेषयेत् ततः पलशते तैले तं कषायं पुनः पचेत्","text":"salilasya caturthāśaṃ kvāthaṃ samavaśeṣayet tataḥ palaśate taile taṃ kaṣāyaṃ punaḥ pacet"},{"type":"verse","number":"34","sanskrit":"पचेत्पलशतं मस्तु काञ्जिकं मस्तुनः समम् ततः शुद्धं पचेद् दुग्धं गव्यं तैलाच्चतुर्गुणम्","text":"pacetpalaśataṃ mastu kāñjikaṃ mastunaḥ samam tataḥ śuddhaṃ paced dugdhaṃ gavyaṃ tailāccaturguṇam"},{"type":"verse","number":"35","sanskrit":"चित्रकं पिप्पलीमूलं मधुकं सैन्धवं वचा शतपुष्पा देवदारु रास्ना च गजपिप्पली","text":"citrakaṃ pippalīmūlaṃ madhukaṃ saindhavaṃ vacā śatapuṣpā devadāru rāsnā ca gajapippalī"},{"type":"verse","number":"36","sanskrit":"प्रसारणीभवं मूलं मांसी रक्तञ्च चन्दनम् तथा वातारिमूलञ्च बलामूलञ्च नागरम्","text":"prasāraṇībhavaṃ mūlaṃ māṃsī raktañca candanam tathā vātārimūlañca balāmūlañca nāgaram"},{"type":"verse","number":"37","sanskrit":"तैलस्य चाष्टमांशेन सर्वकल्कानि साधयेत् नाम्ना प्रसारणीतैलं विख्यातं तत्प्रयुज्यते","text":"tailasya cāṣṭamāṃśena sarvakalkāni sādhayet nāmnā prasāraṇītailaṃ vikhyātaṃ tatprayujyate"},{"type":"verse","number":"38","sanskrit":"पाने नस्ये शिरोवस्तौ मर्दने स्वेदने तथा प्रयुक्तं वातजान् रोगान्सर्वानपि विनाशयेत्","text":"pāne nasye śirovastau mardane svedane tathā prayuktaṃ vātajān rogānsarvānapi vināśayet"},{"type":"verse","number":"39","sanskrit":"विशेषतो हनुस्तम्भं जिह्वास्तम्भं तथाऽदितम् गद्गदत्वञ्च विश्वाचीं मन्यास्तम्भापबाहुकौ","text":"viśeṣato hanustambhaṃ jihvāstambhaṃ tathā'ditam gadgadatvañca viśvācīṃ manyāstambhāpabāhukau"},{"type":"verse","number":"40","sanskrit":"त्रिकशूलं गृध्रसीञ्च खञ्जतां पङ्गुतां तथा कलायखञ्जतां खल्लीं स्तम्भं सङ्कोचमेव च","text":"trikaśūlaṃ gṛdhrasīñca khañjatāṃ paṅgutāṃ tathā kalāyakhañjatāṃ khallīṃ stambhaṃ saṅkocameva ca"},{"type":"verse","number":"41","sanskrit":"आन्तरं बाह्यमायामं तथा दण्डापतानकम् धनुर्वातञ्च कुब्जत्वं व्यपोहति न संशयः","text":"āntaraṃ bāhyamāyāmaṃ tathā daṇḍāpatānakam dhanurvātañca kubjatvaṃ vyapohati na saṃśayaḥ"},{"type":"verse","number":"42","sanskrit":"क्षीणानां स्थविराणाञ्च वातसङ्कोचितात्मनाम् प्रसारयेद्यतोऽङ्गानि तदुक्तैषा प्रसारणी","text":"kṣīṇānāṃ sthavirāṇāñca vātasaṅkocitātmanām prasārayedyato'ṅgāni taduktaiṣā prasāraṇī"},{"type":"verse","number":"43","sanskrit":"वाग्वाहिनीशिरासंस्थो जिह्वां स्तम्भयतेऽनिलः जिह्वास्तम्भः स तेनाद्मपानवाक्येष्वनीशता","text":"vāgvāhinīśirāsaṃstho jihvāṃ stambhayate'nilaḥ jihvāstambhaḥ sa tenādmapānavākyeṣvanīśatā"},{"type":"verse","number":"44","sanskrit":"जिह्वास्तम्भे यथाऽवस्थं वातव्याधिचिकित्सितम् सामान्योक्ता क्रिया चात्रार्दितस्यापि हिता मता","text":"jihvāstambhe yathā'vasthaṃ vātavyādhicikitsitam sāmānyoktā kriyā cātrārditasyāpi hitā matā"},{"type":"verse","number":"45","sanskrit":"आघृत्य वायुः सकफो धमनीः शब्दवाहिनीः नरान्करोत्यवचनान्मूकमिन्मिनगद्गदान्","text":"āghṛtya vāyuḥ sakapho dhamanīḥ śabdavāhinīḥ narānkarotyavacanānmūkaminminagadgadān"},{"type":"verse","number":"46","sanskrit":"अथ गद्गदमिन्मिनमूकानां चिकित्सा प्रस्थं घृतस्य पलिकैः शिग्रुवचालवणधातकीलोघ्रैः आजे पयसि सपाठैः सिद्धं सारस्वतं नाम्ना","text":"atha gadgadaminminamūkānāṃ cikitsā prasthaṃ ghṛtasya palikaiḥ śigruvacālavaṇadhātakīloghraiḥ āje payasi sapāṭhaiḥ siddhaṃ sārasvataṃ nāmnā"},{"type":"verse","number":"47","sanskrit":"विधिवदुपयुज्यमानं जडगद्गदमूकतां क्षणाज्जित्वा स्मृतिमतिमेधाप्रतिभाः कुर्यात्सुस्पष्टवाग्भवति","text":"vidhivadupayujyamānaṃ jaḍagadgadamūkatāṃ kṣaṇājjitvā smṛtimatimedhāpratibhāḥ kuryātsuspaṣṭavāgbhavati"},{"type":"verse","number":"48","sanskrit":"सहरिद्रा वचा कुष्ठं पिप्पली विश्वभेषजम् अजाजी चाजमोदा च यष्टीमधुकसैन्धवम्","text":"saharidrā vacā kuṣṭhaṃ pippalī viśvabheṣajam ajājī cājamodā ca yaṣṭīmadhukasaindhavam"},{"type":"verse","number":"49","sanskrit":"एतानि समभागानि सूक्ष्मचूर्णानि कारयेत् तच्चूर्णं सर्पिषा लेह्यं प्रत्यहं भक्षयेन्नरः","text":"etāni samabhāgāni sūkṣmacūrṇāni kārayet taccūrṇaṃ sarpiṣā lehyaṃ pratyahaṃ bhakṣayennaraḥ"},{"type":"verse","number":"50","sanskrit":"एकविशंतिरात्रेण भवेच्छुतिधरो नरः मेघदुन्दुभिनिर्घोषो मत्तकोकिलनिस्वनः","text":"ekaviśaṃtirātreṇa bhavecchutidharo naraḥ meghadundubhinirghoṣo mattakokilanisvanaḥ"},{"type":"verse","number":"51","sanskrit":"स्वहेतुकुपिताद्वातादसम्बद्धं निरर्थकम् वचनं यन्नरो ब्रूते स प्रलापः प्रकीर्त्तितः","text":"svahetukupitādvātādasambaddhaṃ nirarthakam vacanaṃ yannaro brūte sa pralāpaḥ prakīrttitaḥ"},{"type":"verse","number":"52","sanskrit":"सतगरवरतिक्तारेवताम्भोदतिक्तानलदतुरगगन्धा भारतीहारहूराः मलयजदशमूलीशङ्खपुष्प्यः सुपक्वाः प्रलपनमपहन्युः पानतो नातिदूरात्","text":"satagaravaratiktārevatāmbhodatiktānaladaturagagandhā bhāratīhārahūrāḥ malayajadaśamūlīśaṅkhapuṣpyaḥ supakvāḥ pralapanamapahanyuḥ pānato nātidūrāt"},{"type":"verse","number":"53","sanskrit":"भुञ्जानस्य नरस्यान्नं मधुरप्रभृतीन् रसान् रसज्ञा यन्न जानाति रसाज्ञानं तदुच्यते","text":"bhuñjānasya narasyānnaṃ madhuraprabhṛtīn rasān rasajñā yanna jānāti rasājñānaṃ taducyate"},{"type":"verse","number":"54","sanskrit":"घर्षेज्जिह्वां जडां सिन्धुत्र्यूषणैः साम्लवेतसैः अम्लवेतसकाभावे चुक्रं दातव्यमीरितम्","text":"gharṣejjihvāṃ jaḍāṃ sindhutryūṣaṇaiḥ sāmlavetasaiḥ amlavetasakābhāve cukraṃ dātavyamīritam"},{"type":"verse","number":"55","sanskrit":"किराततिक्तका कट्वी कुटजस्य फलं त्वचा ब्राह्मी फलञ्च पालाशं सर्जिका कृष्णजीरकम्","text":"kirātatiktakā kaṭvī kuṭajasya phalaṃ tvacā brāhmī phalañca pālāśaṃ sarjikā kṛṣṇajīrakam"},{"type":"verse","number":"56","sanskrit":"पिप्पली पिप्पलीमूलं चित्रं नागरमूषणम् एषां कल्कैर्मुहुर्घर्षेज्जिह्विकामार्द्रि कारसैः","text":"pippalī pippalīmūlaṃ citraṃ nāgaramūṣaṇam eṣāṃ kalkairmuhurgharṣejjihvikāmārdri kārasaiḥ"},{"type":"verse","number":"57","sanskrit":"तेन सम्यग्विजानाति रसना सकलान् रसान् कल्कः किराततिक्तादिर्जिह्वायाःशून्यतां हरेत्","text":"tena samyagvijānāti rasanā sakalān rasān kalkaḥ kirātatiktādirjihvāyāḥśūnyatāṃ haret"},{"type":"verse","number":"58","sanskrit":"स्पृश्यमाना त्वचा या तु शीतोष्णं मृदु कर्कशम् न जानाति बुधैस्त्वक् सा शून्येति परिकीर्त्तिता","text":"spṛśyamānā tvacā yā tu śītoṣṇaṃ mṛdu karkaśam na jānāti budhaistvak sā śūnyeti parikīrttitā"},{"type":"verse","number":"59","sanskrit":"सुप्तवाते त्वसृङ्मोक्षं कारयेद् बहुशो भिषक् दद्याच्च लवणाङ्गारधूमैस्तैलसमन्वितैः","text":"suptavāte tvasṛṅmokṣaṃ kārayed bahuśo bhiṣak dadyācca lavaṇāṅgāradhūmaistailasamanvitaiḥ"},{"type":"verse","number":"60","sanskrit":"उच्चैर्व्याहरतोऽत्यर्थं खादतः कठिनानि च हसतो जृम्भतो भाराद्विषमाच्छयनासनात्","text":"uccairvyāharato'tyarthaṃ khādataḥ kaṭhināni ca hasato jṛmbhato bhārādviṣamācchayanāsanāt"},{"type":"verse","number":"61","sanskrit":"शिरोनासौष्ठचिबुकललाटेक्षणसन्धिगः अर्दयत्यनिलो वक्त्रमर्दितं जनयेत्ततः","text":"śironāsauṣṭhacibukalalāṭekṣaṇasandhigaḥ ardayatyanilo vaktramarditaṃ janayettataḥ"},{"type":"verse","number":"62","sanskrit":"वक्रीभवति वक्त्रार्द्धं ग्रीवा चाप्यपवर्त्तते शिरश्चलति वाक्सङ्गो नेत्रादीनाञ्च वैकृतम्","text":"vakrībhavati vaktrārddhaṃ grīvā cāpyapavarttate śiraścalati vāksaṅgo netrādīnāñca vaikṛtam"},{"type":"verse","number":"63","sanskrit":"ग्रीवाचिबुकदन्तानां तस्मिन्पार्श्वे च वेदना तमर्दितमिति प्राहुर्व्याधिं व्याधिविशारदाः","text":"grīvācibukadantānāṃ tasminpārśve ca vedanā tamarditamiti prāhurvyādhiṃ vyādhiviśāradāḥ"},{"type":"verse","number":"64","sanskrit":"वातात्पित्तात्कफाच्च स्यात्त्रिविधं तत्समासतः लालास्रावो व्यथा कम्पः स्फुरणं हनुवाग्ग्रहः","text":"vātātpittātkaphācca syāttrividhaṃ tatsamāsataḥ lālāsrāvo vyathā kampaḥ sphuraṇaṃ hanuvāggrahaḥ"},{"type":"verse","number":"65","sanskrit":"ओष्ठयोः श्वयथुः शूलं चार्दिते वातजे भवेत्","text":"oṣṭhayoḥ śvayathuḥ śūlaṃ cārdite vātaje bhavet"},{"type":"verse","number":"66","sanskrit":"पीतमास्यं ज्वरस्तृष्णापित्तजे मोहधूपने गण्डे गिरसि मन्यायां शोथः स्तम्भः कफात्मके","text":"pītamāsyaṃ jvarastṛṣṇāpittaje mohadhūpane gaṇḍe girasi manyāyāṃ śothaḥ stambhaḥ kaphātmake"},{"type":"verse","number":"67","sanskrit":"क्षीणस्यानिमिषाक्षस्य प्रसक्ताव्यक्तभाषिणः न सिध्यत्यर्दितं गाढं त्रिवर्षं वेपनस्य च","text":"kṣīṇasyānimiṣākṣasya prasaktāvyaktabhāṣiṇaḥ na sidhyatyarditaṃ gāḍhaṃ trivarṣaṃ vepanasya ca"},{"type":"verse","number":"68","sanskrit":"स्नेहपानानि नस्यश्च भोज्यान्यनिलहन्ति च उपनाहाश्च शस्यन्ते नावनं वस्तयोऽदिते","text":"snehapānāni nasyaśca bhojyānyanilahanti ca upanāhāśca śasyante nāvanaṃ vastayo'dite"},{"type":"verse","number":"69","sanskrit":"बलया पञ्चमूल्या वा क्षीरं वातात्मके हितम् दशमूलकषायेण मातुलुङ्गरसेन वा","text":"balayā pañcamūlyā vā kṣīraṃ vātātmake hitam daśamūlakaṣāyeṇa mātuluṅgarasena vā"},{"type":"verse","number":"70","sanskrit":"पिष्टं मांसघृतं जग्ध्वा नवनीतेन सोऽदिती क्षीरमांसरसैर्भुक्त्वा दशमूलीरसं पिबेत्","text":"piṣṭaṃ māṃsaghṛtaṃ jagdhvā navanītena so'ditī kṣīramāṃsarasairbhuktvā daśamūlīrasaṃ pibet"},{"type":"verse","number":"71","sanskrit":"अर्दिते पित्तजे शीतान्स्नेहांश्चैव विनिर्दिशेत् घृतवस्तिप्रसेकञ्च क्षीरमेकं तथैव च","text":"ardite pittaje śītānsnehāṃścaiva vinirdiśet ghṛtavastiprasekañca kṣīramekaṃ tathaiva ca"},{"type":"verse","number":"72","sanskrit":"जिह्मीभूताननो मूको दाहवान्योऽदिती भवेत् कुर्यात्प्रतिक्रियां तस्य वातपित्तविनाशिनीम्","text":"jihmībhūtānano mūko dāhavānyo'ditī bhavet kuryātpratikriyāṃ tasya vātapittavināśinīm"},{"type":"verse","number":"73","sanskrit":"श्लेष्मभागे क्षयं नीते बृंहणैः समुपाचरेत् अर्दिते शोथसंयुक्ते वमनं च प्रशस्यते","text":"śleṣmabhāge kṣayaṃ nīte bṛṃhaṇaiḥ samupācaret ardite śothasaṃyukte vamanaṃ ca praśasyate"},{"type":"verse","number":"74","sanskrit":"रसोनकल्कं तिलतैलमिश्रं खादेन्नरो योऽदितरोगयुक्तः तस्यार्दितं नाशमुपैति शीघ्रं वृन्दं घनानामिव वायुवेगात्","text":"rasonakalkaṃ tilatailamiśraṃ khādennaro yo'ditarogayuktaḥ tasyārditaṃ nāśamupaiti śīghraṃ vṛndaṃ ghanānāmiva vāyuvegāt"},{"type":"verse","number":"75","sanskrit":"दिवास्वप्नासनस्थानविकृतोर्ध्वनिरीक्षणैः मन्यास्तम्भं प्रकुरुते स एव श्लेष्मणाऽवृतः","text":"divāsvapnāsanasthānavikṛtordhvanirīkṣaṇaiḥ manyāstambhaṃ prakurute sa eva śleṣmaṇā'vṛtaḥ"},{"type":"verse","number":"76","sanskrit":"दशमूलीकृतं क्वाथं पञ्चमूल्याऽपि कल्पितम् रुक्षं स्वेदं तथा नस्यं मन्यास्तम्भे प्रयोजयेत्","text":"daśamūlīkṛtaṃ kvāthaṃ pañcamūlyā'pi kalpitam rukṣaṃ svedaṃ tathā nasyaṃ manyāstambhe prayojayet"},{"type":"verse","number":"77","sanskrit":"तैलेनाज्येन वा ग्रीवामभ्यज्यार्कदलैरथ एरण्डपत्रैराच्छाद्य स्वेदयेद् बहुशो भिषक्","text":"tailenājyena vā grīvāmabhyajyārkadalairatha eraṇḍapatrairācchādya svedayed bahuśo bhiṣak"},{"type":"verse","number":"78","sanskrit":"कुक्कुटाण्डद्र वैरुष्णैः सैन्धवाज्यसमन्वितैः ग्रीवां सम्मर्दयेत्तेन मन्यास्तम्भः प्रशाम्यति","text":"kukkuṭāṇḍadra vairuṣṇaiḥ saindhavājyasamanvitaiḥ grīvāṃ sammardayettena manyāstambhaḥ praśāmyati"},{"type":"verse","number":"79","sanskrit":"अंसदेशे स्थितो वायुः शोषयेदंसबन्धनम् अंसबन्धनशोषात्स्याद् बाहुशोषः सवेदनः","text":"aṃsadeśe sthito vāyuḥ śoṣayedaṃsabandhanam aṃsabandhanaśoṣātsyād bāhuśoṣaḥ savedanaḥ"},{"type":"verse","number":"80","sanskrit":"बाहुशोषे पिबेद् भुक्त्वा सर्पिः कल्याणकं महत् बलामूलशृतं तोयं सैन्धवेन समन्वितम् बाहुशोषकरे वाते मन्यास्तम्भे च शस्यते","text":"bāhuśoṣe pibed bhuktvā sarpiḥ kalyāṇakaṃ mahat balāmūlaśṛtaṃ toyaṃ saindhavena samanvitam bāhuśoṣakare vāte manyāstambhe ca śasyate"},{"type":"verse","number":"81","sanskrit":"शिराः सङ्कोच्य बाहुस्थः स कुर्यादपबाहुकम्","text":"śirāḥ saṅkocya bāhusthaḥ sa kuryādapabāhukam"},{"type":"verse","number":"82","sanskrit":"परमौषधमपबाहु कमन्यास्तम्भोर्ध्वजत्रुगतरोगे शीतलजलेन नस्यं तदुपशमं जिङ्गिनी च पुरः","text":"paramauṣadhamapabāhu kamanyāstambhordhvajatrugataroge śītalajalena nasyaṃ tadupaśamaṃ jiṅginī ca puraḥ"},{"type":"verse","number":"83","sanskrit":"मूलं बलायास्त्वथ पारिभद्र जं तथाऽत्मगुप्तास्वरसं पिबेद्वा युञ्जीत यो माषरसेन नस्यं भवेदसौ वज्रसमानबाहुः","text":"mūlaṃ balāyāstvatha pāribhadra jaṃ tathā'tmaguptāsvarasaṃ pibedvā yuñjīta yo māṣarasena nasyaṃ bhavedasau vajrasamānabāhuḥ"},{"type":"verse","number":"84","sanskrit":"माषातसीयवकुरण्टककण्टकारी गोकण्टटुण्टुकजटाकपिकच्छतोयैः कार्पासकास्थिशणबीजकुलत्थकोलक्वाथेन बस्तपिशितस्य रसेन चापि","text":"māṣātasīyavakuraṇṭakakaṇṭakārī gokaṇṭaṭuṇṭukajaṭākapikacchatoyaiḥ kārpāsakāsthiśaṇabījakulatthakolakvāthena bastapiśitasya rasena cāpi"},{"type":"verse","number":"85","sanskrit":"शुण्ठ्या समागधिकया शतपुष्पया च सैरण्डमूलकपुनर्नवया सरण्या रास्नाबलाऽमृतलताकटुकैर्विपक्वं माषाख्यमेतदपबाहुहरं हि तैलम्","text":"śuṇṭhyā samāgadhikayā śatapuṣpayā ca sairaṇḍamūlakapunarnavayā saraṇyā rāsnābalā'mṛtalatākaṭukairvipakvaṃ māṣākhyametadapabāhuharaṃ hi tailam"},{"type":"verse","number":"86","sanskrit":"तलं प्रत्यङ्गुलीनां याः कण्डरा बाहुपृष्ठतः बाह्वोः कर्मक्षयकरी विश्वाची सा निगद्यते","text":"talaṃ pratyaṅgulīnāṃ yāḥ kaṇḍarā bāhupṛṣṭhataḥ bāhvoḥ karmakṣayakarī viśvācī sā nigadyate"},{"type":"verse","number":"87","sanskrit":"दशमूलीबलामाषक्वाथं तैलाज्यमिश्रितम् सायं भुक्त्वा पिबेन्नस्यं विश्वाच्यामपबाहुके","text":"daśamūlībalāmāṣakvāthaṃ tailājyamiśritam sāyaṃ bhuktvā pibennasyaṃ viśvācyāmapabāhuke"},{"type":"verse","number":"88","sanskrit":"माषसिन्धुबलारास्ना दशमूलकहिङ्गुभिः वचाशिवजटाऽख्याभिः सिद्धं तैलं सनागरम्","text":"māṣasindhubalārāsnā daśamūlakahiṅgubhiḥ vacāśivajaṭā'khyābhiḥ siddhaṃ tailaṃ sanāgaram"},{"type":"verse","number":"89","sanskrit":"ऊर्ध्वं भक्ताशनाद्धन्याद् बाहुशोषापबाहुकौ विश्वाचीमुद्धतां चापि पक्षाघातं तथाऽदितम्","text":"ūrdhvaṃ bhaktāśanāddhanyād bāhuśoṣāpabāhukau viśvācīmuddhatāṃ cāpi pakṣāghātaṃ tathā'ditam"},{"type":"verse","number":"90","sanskrit":"अधःप्रतिहतो वायुः श्लेष्मणा मारुतेन च करोत्युद्गारबाहुल्यमूर्ध्ववातः स उच्यते","text":"adhaḥpratihato vāyuḥ śleṣmaṇā mārutena ca karotyudgārabāhulyamūrdhvavātaḥ sa ucyate"},{"type":"verse","number":"91","sanskrit":"भागा दश विश्वायास्तत्तुल्या वृद्धदारकस्यापि त्रय एव च पथ्यायाश्चतुरंशं हिङ्गु सम्भृष्टम्","text":"bhāgā daśa viśvāyāstattulyā vṛddhadārakasyāpi traya eva ca pathyāyāścaturaṃśaṃ hiṅgu sambhṛṣṭam"},{"type":"verse","number":"92","sanskrit":"एकः सैन्धवभागस्तत्तुल्यं चित्रकं चात्र संवृद्धमूर्ध्ववातं हन्त्येतच्चूर्णितं भुक्तम्","text":"ekaḥ saindhavabhāgastattulyaṃ citrakaṃ cātra saṃvṛddhamūrdhvavātaṃ hantyetaccūrṇitaṃ bhuktam"},{"type":"verse","number":"93","sanskrit":"साटोपमत्युग्ररुजमाध्मातमुदरं भृशम् आध्मानमिति जानीयाद्धोरं वातनिरोधजम्","text":"sāṭopamatyugrarujamādhmātamudaraṃ bhṛśam ādhmānamiti jānīyāddhoraṃ vātanirodhajam"},{"type":"verse","number":"94","sanskrit":"आध्माने लङ्घनं पूर्वं दीपनं पाचनं ततः फलवर्तिक्रियां कुर्याद्वस्तिकर्म च शोधनम्","text":"ādhmāne laṅghanaṃ pūrvaṃ dīpanaṃ pācanaṃ tataḥ phalavartikriyāṃ kuryādvastikarma ca śodhanam"},{"type":"verse","number":"95","sanskrit":"कर्षमात्रा भवेत्कृष्णा त्रिवृता स्यात्पलोन्मिता खण्डादपि पलं ग्राह्यं चूर्णमेकत्र कारयेत् मधुनाऽक्षमितं लिह्याच्चूर्णमाध्माननाशनम्","text":"karṣamātrā bhavetkṛṣṇā trivṛtā syātpalonmitā khaṇḍādapi palaṃ grāhyaṃ cūrṇamekatra kārayet madhunā'kṣamitaṃ lihyāccūrṇamādhmānanāśanam"},{"type":"verse","number":"96","sanskrit":"दारुहैमवतीकुष्ठशताह्वा हिङ्गुसैन्धवैः लिम्पेदुष्णैरम्लपिष्टैः शूलाध्मानयुतोदरम्","text":"dāruhaimavatīkuṣṭhaśatāhvā hiṅgusaindhavaiḥ limpeduṣṇairamlapiṣṭaiḥ śūlādhmānayutodaram"},{"type":"verse","number":"97","sanskrit":"अभयाऽरग्वधो धात्री दन्ती तिक्ता स्नुही त्रिवृत् मुस्ता प्रत्येकमेतानि ग्राह्याणि पलमात्रया","text":"abhayā'ragvadho dhātrī dantī tiktā snuhī trivṛt mustā pratyekametāni grāhyāṇi palamātrayā"},{"type":"verse","number":"98","sanskrit":"तानि सङ्कुट्य सर्वाणि जलाढकयुगे पचेत् तत्र तोयेऽष्टमं भागं कषायमवशेषयेत्","text":"tāni saṅkuṭya sarvāṇi jalāḍhakayuge pacet tatra toye'ṣṭamaṃ bhāgaṃ kaṣāyamavaśeṣayet"},{"type":"verse","number":"99","sanskrit":"निस्त्वग्जैपालबीजानि नवानि पलमात्रया तनुवस्त्रधृतान्येव तस्मिन्क्वाथे शनैः पचेत्","text":"nistvagjaipālabījāni navāni palamātrayā tanuvastradhṛtānyeva tasminkvāthe śanaiḥ pacet"},{"type":"verse","number":"100","sanskrit":"ज्वालयेदनलं मन्दं यावत्क्वाथो घनो भवेत् तत खल्वे क्षिपेद्भागानष्टौ जैपालबीजतः","text":"jvālayedanalaṃ mandaṃ yāvatkvātho ghano bhavet tata khalve kṣipedbhāgānaṣṭau jaipālabījataḥ"},{"type":"verse","number":"101","sanskrit":"भागांस्त्रीन्नागराद् द्वौ च मरिचाद् द्वौ च पारदात् गन्धकाद् द्वौ च तानीह यावद्यामं विमर्दयेत्","text":"bhāgāṃstrīnnāgarād dvau ca maricād dvau ca pāradāt gandhakād dvau ca tānīha yāvadyāmaṃ vimardayet"},{"type":"verse","number":"102","sanskrit":"रसो नाराचनामाऽय भक्षितो रक्तिकामितः जलेन शीतलेनैव रोगानेतान्विनाशयेत्","text":"raso nārācanāmā'ya bhakṣito raktikāmitaḥ jalena śītalenaiva rogānetānvināśayet"},{"type":"verse","number":"103","sanskrit":"आध्मानं शूलमानाहं प्रत्याध्मानं तथैव च उदावर्त्तं तथा गुल्ममुदराणि हरत्यसौ","text":"ādhmānaṃ śūlamānāhaṃ pratyādhmānaṃ tathaiva ca udāvarttaṃ tathā gulmamudarāṇi haratyasau"},{"type":"verse","number":"104","sanskrit":"वेगे शान्ते तु भुञ्जीत शर्करासहितं दधि ततस्तत्सैन्धवेनापि ततो दध्योदनं मनाक्","text":"vege śānte tu bhuñjīta śarkarāsahitaṃ dadhi tatastatsaindhavenāpi tato dadhyodanaṃ manāk"},{"type":"verse","number":"105","sanskrit":"विमुक्तपार्श्वहृदयं तदेवामाशयोत्थितम् प्रत्याध्मानं विजानीयात्कफव्याकुलितानिलम्","text":"vimuktapārśvahṛdayaṃ tadevāmāśayotthitam pratyādhmānaṃ vijānīyātkaphavyākulitānilam"},{"type":"verse","number":"106","sanskrit":"प्रत्याध्माने समुत्पन्ने कुर्याद्वमनलङ्घने दीपनादीनि युञ्जीत पूर्ववद्वस्तिकर्म च","text":"pratyādhmāne samutpanne kuryādvamanalaṅghane dīpanādīni yuñjīta pūrvavadvastikarma ca"},{"type":"verse","number":"107","sanskrit":"नाभेरधस्तात्सञ्जातः सञ्चारी यदि वाऽचलः","text":"nābheradhastātsañjātaḥ sañcārī yadi vā'calaḥ"},{"type":"verse","number":"108","sanskrit":"अष्ठीलावद्घनो ग्रन्थिरुर्ध्वमायत उन्नतः वाताष्ठीलां विजानीयाद् वहिर्मार्गनिरोधिनीम्","text":"aṣṭhīlāvadghano granthirurdhvamāyata unnataḥ vātāṣṭhīlāṃ vijānīyād vahirmārganirodhinīm"},{"type":"verse","number":"109","sanskrit":"एतामेव रुजायुक्तां वातविण्मूत्ररोधिनीम् प्रत्यष्ठीलामिति वदेज्जठरे तिर्यगुत्थिताम्","text":"etāmeva rujāyuktāṃ vātaviṇmūtrarodhinīm pratyaṣṭhīlāmiti vadejjaṭhare tiryagutthitām"},{"type":"verse","number":"110","sanskrit":"अष्ठीलायाः क्रिया कार्या गुल्मस्यान्तरविद्र धेः चूर्णं हिङ्ग्वादिकं चात्र पिबेदुष्णेन वारिणा","text":"aṣṭhīlāyāḥ kriyā kāryā gulmasyāntaravidra dheḥ cūrṇaṃ hiṅgvādikaṃ cātra pibeduṣṇena vāriṇā"},{"type":"verse","number":"111","sanskrit":"हिङ्गुग्रन्थिक धान्यजीरकवचाचव्याग्निपाठाशटी वृक्षाम्लं लवणत्रयं त्रिकटुकं क्षारद्वयं दाडिमम् पथ्यापौष्करवेतसाम्लहपुषायोज्यंतदेभिः कृतं चूर्णं भावितमेतदार्द्र करसैः स्याद् बीजपूरद्र वैः","text":"hiṅgugranthika dhānyajīrakavacācavyāgnipāṭhāśaṭī vṛkṣāmlaṃ lavaṇatrayaṃ trikaṭukaṃ kṣāradvayaṃ dāḍimam pathyāpauṣkaravetasāmlahapuṣāyojyaṃtadebhiḥ kṛtaṃ cūrṇaṃ bhāvitametadārdra karasaiḥ syād bījapūradra vaiḥ"},{"type":"verse","number":"112","sanskrit":"अधो या वेदना याति वर्चोमूत्राशयोत्थिता भिन्दन्तीव गुदोपस्थं सा तूनी नामतो मता","text":"adho yā vedanā yāti varcomūtrāśayotthitā bhindantīva gudopasthaṃ sā tūnī nāmato matā"},{"type":"verse","number":"113","sanskrit":"गुदोपस्थोत्थिता सैव प्रतिलोमं विधाविता वेगैः पक्वाशयं याति प्रतितूनीति सोच्यते","text":"gudopasthotthitā saiva pratilomaṃ vidhāvitā vegaiḥ pakvāśayaṃ yāti pratitūnīti socyate"},{"type":"verse","number":"114","sanskrit":"तून्याञ्च प्रतितून्याञ्च प्रशस्ताः स्नेहवस्तयः पिबेद्वा स्नेहलवणं पिप्पल्यादिमथाम्बुना उष्णेन रामठं क्षारं प्रगाढमथ वा घृतम्","text":"tūnyāñca pratitūnyāñca praśastāḥ snehavastayaḥ pibedvā snehalavaṇaṃ pippalyādimathāmbunā uṣṇena rāmaṭhaṃ kṣāraṃ pragāḍhamatha vā ghṛtam"},{"type":"verse","number":"115","sanskrit":"स्फिगस्थ्नोः पृष्ठवंशास्थ्नोर्यः सन्धिस्तत्त्रिकं मतम् तत्र वातेन या पीडा त्रिकशूलं तदुच्यते","text":"sphigasthnoḥ pṛṣṭhavaṃśāsthnoryaḥ sandhistattrikaṃ matam tatra vātena yā pīḍā trikaśūlaṃ taducyate"},{"type":"verse","number":"116","sanskrit":"कारयेद्वालुकास्वेदं त्रिकशूलेप्रयत्नतः यद्वाऽधस्तात्करीषाग्निं धारयेत्सततं नरः","text":"kārayedvālukāsvedaṃ trikaśūleprayatnataḥ yadvā'dhastātkarīṣāgniṃ dhārayetsatataṃ naraḥ"},{"type":"verse","number":"117","sanskrit":"आभाऽश्वगन्धा हपुषागुडूची शतावरी गोक्षुरकश्च रास्ना श्यामा शताह्वा च शटी यवानी सनागरा चेति समं विचूर्ण्य","text":"ābhā'śvagandhā hapuṣāguḍūcī śatāvarī gokṣurakaśca rāsnā śyāmā śatāhvā ca śaṭī yavānī sanāgarā ceti samaṃ vicūrṇya"},{"type":"verse","number":"118","sanskrit":"सर्वैः समं गुग्गुलुमत्र दद्यात्क्षिपेदिहाज्यञ्च तदर्द्धभागम् तद्भक्षयेदर्द्धपिचुप्रमाणं प्रभातकाले पयसाऽथ यूषैः","text":"sarvaiḥ samaṃ guggulumatra dadyātkṣipedihājyañca tadarddhabhāgam tadbhakṣayedarddhapicupramāṇaṃ prabhātakāle payasā'tha yūṣaiḥ"},{"type":"verse","number":"119","sanskrit":"मद्येन वा कोष्णजलेन चापि क्षीरेण वा मांसरसेन वाऽपि त्रिकग्रहे जानुहनुग्रहे च वाते भुजस्थे चरणस्थिते च","text":"madyena vā koṣṇajalena cāpi kṣīreṇa vā māṃsarasena vā'pi trikagrahe jānuhanugrahe ca vāte bhujasthe caraṇasthite ca"},{"type":"verse","number":"120","sanskrit":"सन्धिस्थिते चास्थिगते च तस्मिन्मज्जस्थिते स्नायुगते च कोष्ठे रोगान् हरेद्वातकफानुविद्धान् वातेरितान् हृद्ग्रहयोनिदोषान्","text":"sandhisthite cāsthigate ca tasminmajjasthite snāyugate ca koṣṭhe rogān haredvātakaphānuviddhān vāteritān hṛdgrahayonidoṣān"},{"type":"verse","number":"121","sanskrit":"भग्नास्थिविद्धेषु च खञ्जतायां सगृध्रसीके खलु पक्षघाते महौषधं गुग्गुलुमेतमाहुस्त्रयोदशाङ्गं भिषजः पुराणाः","text":"bhagnāsthividdheṣu ca khañjatāyāṃ sagṛdhrasīke khalu pakṣaghāte mahauṣadhaṃ guggulumetamāhustrayodaśāṅgaṃ bhiṣajaḥ purāṇāḥ"},{"type":"verse","number":"122","sanskrit":"मारुतेऽविगुणे वस्तौ मूत्रं सम्यक्प्रवर्त्तते विकारा विविधाश्चापि तस्मिन्दुष्टे भवन्ति हि","text":"mārute'viguṇe vastau mūtraṃ samyakpravarttate vikārā vividhāścāpi tasminduṣṭe bhavanti hi"},{"type":"verse","number":"123","sanskrit":"बलामूर्वात्वचश्चूर्णं ससितं कर्षसम्मितम् पिबेत्कुडवदुग्धेन मुहुर्मूत्रणशान्तये","text":"balāmūrvātvacaścūrṇaṃ sasitaṃ karṣasammitam pibetkuḍavadugdhena muhurmūtraṇaśāntaye"},{"type":"verse","number":"124","sanskrit":"पथ्याबिभीतधात्रीणां चूर्णं चूर्णं मृतायसः मधुना सह संलीढं मुहुर्मूत्रणशान्तिकृत्","text":"pathyābibhītadhātrīṇāṃ cūrṇaṃ cūrṇaṃ mṛtāyasaḥ madhunā saha saṃlīḍhaṃ muhurmūtraṇaśāntikṛt"},{"type":"verse","number":"125","sanskrit":"यवक्षारस्य चूर्णस्तु संयोज्य सितया सह भक्षयेन्नियतं तस्य प्रशाम्येन्मूत्रनिग्रहः","text":"yavakṣārasya cūrṇastu saṃyojya sitayā saha bhakṣayenniyataṃ tasya praśāmyenmūtranigrahaḥ"},{"type":"verse","number":"126","sanskrit":"कूष्माण्डस्य तु बीजानि बीजानि त्रपुषस्य च वस्तौ सन्धारयेत्तेन प्रशाम्येन्मूत्रनिग्रहः","text":"kūṣmāṇḍasya tu bījāni bījāni trapuṣasya ca vastau sandhārayettena praśāmyenmūtranigrahaḥ"},{"type":"verse","number":"127","sanskrit":"आमलक्याश्च कल्केन वस्तिभागं प्रलेपयेत् तेन प्रशाम्यति क्षिप्रं नियमान्मूत्रनिग्रहः","text":"āmalakyāśca kalkena vastibhāgaṃ pralepayet tena praśāmyati kṣipraṃ niyamānmūtranigrahaḥ"},{"type":"verse","number":"128","sanskrit":"मेहनस्याथ योनेर्वा मुखस्याभ्यन्तरे शनैः घनसारयुतां वर्त्तिं धारयेन्मूत्रनिग्रहे","text":"mehanasyātha yonervā mukhasyābhyantare śanaiḥ ghanasārayutāṃ varttiṃ dhārayenmūtranigrahe"},{"type":"verse","number":"129","sanskrit":"स्फिक्पूर्वोरुकटीपृष्टजानुजङ्घापदं क्रमात् गृध्रसी स्तम्भरुक्तोदैर्गृह्णाति स्पन्दते मुहुः","text":"sphikpūrvorukaṭīpṛṣṭajānujaṅghāpadaṃ kramāt gṛdhrasī stambharuktodairgṛhṇāti spandate muhuḥ"},{"type":"verse","number":"130","sanskrit":"वाताद्वातकफाभ्यां सा विज्ञेया द्विविधा पुनः वातजायां भवेत्तोदो देहस्यातीव वक्रता","text":"vātādvātakaphābhyāṃ sā vijñeyā dvividhā punaḥ vātajāyāṃ bhavettodo dehasyātīva vakratā"},{"type":"verse","number":"131","sanskrit":"जानुजङ्घोरुसन्धीनां स्फुरणं स्तम्भता भृशम्","text":"jānujaṅghorusandhīnāṃ sphuraṇaṃ stambhatā bhṛśam"},{"type":"verse","number":"132","sanskrit":"वातश्लेष्मोद्भवायान्तु गौरवं वह्निमार्दवम् तन्द्रा मुखप्रसेकश्च भक्तद्वेषस्तथैव च","text":"vātaśleṣmodbhavāyāntu gauravaṃ vahnimārdavam tandrā mukhaprasekaśca bhaktadveṣastathaiva ca"},{"type":"verse","number":"133","sanskrit":"गृध्रस्यार्त्तं नरं सम्यग् रेकेण वमनेन वा ज्ञात्वा निरामं दीप्ताग्निं वस्तिभिः समुपाचरेत्","text":"gṛdhrasyārttaṃ naraṃ samyag rekeṇa vamanena vā jñātvā nirāmaṃ dīptāgniṃ vastibhiḥ samupācaret"},{"type":"verse","number":"134","sanskrit":"नादौ वस्तिविधिं कुर्याद्यावदूर्ध्वं न शुध्यति स्नेहो निरर्थकः स स्याद्भस्मन्येव हुतं यथा","text":"nādau vastividhiṃ kuryādyāvadūrdhvaṃ na śudhyati sneho nirarthakaḥ sa syādbhasmanyeva hutaṃ yathā"},{"type":"verse","number":"135","sanskrit":"तैलमेरण्डजं प्रातर्गोमूत्रेण पिबेन्नरः मासमेकं प्रयोगोऽय गृध्रस्यूरुग्रहापहः","text":"tailameraṇḍajaṃ prātargomūtreṇa pibennaraḥ māsamekaṃ prayogo'ya gṛdhrasyūrugrahāpahaḥ"},{"type":"verse","number":"136","sanskrit":"तैलं घृतं चार्द्र कमातुलुङ्गरसं सचुक्रं सगुडं पिबेद्वा कट्युरुपृष्ठत्रिकशूलगुल्मगृध्रस्युदावर्त्तहरः प्रयोगः","text":"tailaṃ ghṛtaṃ cārdra kamātuluṅgarasaṃ sacukraṃ saguḍaṃ pibedvā kaṭyurupṛṣṭhatrikaśūlagulmagṛdhrasyudāvarttaharaḥ prayogaḥ"},{"type":"verse","number":"137","sanskrit":"निष्कुष्यैरण्डबीजानि पिष्ट्वा क्षीरे विपाचयेत् तत्पानन्तु कटीशूले गृध्रस्यां परमौषधम्","text":"niṣkuṣyairaṇḍabījāni piṣṭvā kṣīre vipācayet tatpānantu kaṭīśūle gṛdhrasyāṃ paramauṣadham"},{"type":"verse","number":"138","sanskrit":"एरण्डमूलं बिल्वञ्च बृहती कण्टकारिका कषायोरुचकोपेतः पीतो वङ्क्षणवस्तिजम् गृध्रसीजं हरेच्छूलं चिरकालानुबन्धि च","text":"eraṇḍamūlaṃ bilvañca bṛhatī kaṇṭakārikā kaṣāyorucakopetaḥ pīto vaṅkṣaṇavastijam gṛdhrasījaṃ harecchūlaṃ cirakālānubandhi ca"},{"type":"verse","number":"139","sanskrit":"गोमूत्रैरण्डतैलाभ्यां कृष्णाचूर्णं पिबेन्नरः दीर्घकालोत्थितां हन्ति गृध्रसीं कफवातजाम्","text":"gomūtrairaṇḍatailābhyāṃ kṛṣṇācūrṇaṃ pibennaraḥ dīrghakālotthitāṃ hanti gṛdhrasīṃ kaphavātajām"},{"type":"verse","number":"140","sanskrit":"सिंहास्यदन्तीकृतमालकानां पिबेत्कषायं रुबुतैलमिश्रम् यो गृध्रसीनष्टगतिः प्रसुप्तः स शीघ्रगः स्याद्धि किमत्र चित्रम्","text":"siṃhāsyadantīkṛtamālakānāṃ pibetkaṣāyaṃ rubutailamiśram yo gṛdhrasīnaṣṭagatiḥ prasuptaḥ sa śīghragaḥ syāddhi kimatra citram"},{"type":"verse","number":"141","sanskrit":"बृहन्निम्बतरोः सारो वारिणा परिपेषितः स पीतो नाशयेत्क्षिप्रमसाध्यामपि गृध्रसीम्","text":"bṛhannimbataroḥ sāro vāriṇā paripeṣitaḥ sa pīto nāśayetkṣipramasādhyāmapi gṛdhrasīm"},{"type":"verse","number":"142","sanskrit":"शेफालिकादलैः क्वाथो मृद्वग्निपरिपाचितः दुर्वारं गृध्रसीरोगं पीतमात्रः प्रणाशयेत्","text":"śephālikādalaiḥ kvātho mṛdvagniparipācitaḥ durvāraṃ gṛdhrasīrogaṃ pītamātraḥ praṇāśayet"},{"type":"verse","number":"143","sanskrit":"रास्नायास्तु पलं चैकं पञ्चकर्षाणि गुग्गुलोः सर्पिषावटिकां कृत्वा भक्षयेद् गृध्रसीहरीम्","text":"rāsnāyāstu palaṃ caikaṃ pañcakarṣāṇi gugguloḥ sarpiṣāvaṭikāṃ kṛtvā bhakṣayed gṛdhrasīharīm"},{"type":"verse","number":"144","sanskrit":"रास्नामृतारग्वधदेवदारुत्रिकण्टकैरण्डपुनर्नवानाम् क्वाथं पिबेन्नागरचूर्णमिश्रं जङ्घोरुपृष्ठत्रिकपार्श्वशूली","text":"rāsnāmṛtāragvadhadevadārutrikaṇṭakairaṇḍapunarnavānām kvāthaṃ pibennāgaracūrṇamiśraṃ jaṅghorupṛṣṭhatrikapārśvaśūlī"},{"type":"verse","number":"145","sanskrit":"पथ्याबिभीतामलकीफलानां शतं क्रमेण द्विगुणाभिवृद्धम् प्रस्थेन युक्तञ्च पलङ्कषाणां द्रो णे जले संस्थितमेकरात्रम्","text":"pathyābibhītāmalakīphalānāṃ śataṃ krameṇa dviguṇābhivṛddham prasthena yuktañca palaṅkaṣāṇāṃ dro ṇe jale saṃsthitamekarātram"},{"type":"verse","number":"146","sanskrit":"अर्धावशिष्टं क्वथितं कषायं भाण्डे पचेत्तत्पुनरेव लौहे अमूनि वह्नेरवतार्य दद्याद् द्र व्याणि सञ्चूर्ण्य पलार्द्धकानि","text":"ardhāvaśiṣṭaṃ kvathitaṃ kaṣāyaṃ bhāṇḍe pacettatpunareva lauhe amūni vahneravatārya dadyād dra vyāṇi sañcūrṇya palārddhakāni"},{"type":"verse","number":"147","sanskrit":"विडङ्गदन्तीत्रिफलागुडूची कृष्णात्रिवृन्नागरकोषणानि यथेष्टचेष्टस्य नरस्य शीघ्रं हिमाम्बुपानानि च भोजनानि","text":"viḍaṅgadantītriphalāguḍūcī kṛṣṇātrivṛnnāgarakoṣaṇāni yatheṣṭaceṣṭasya narasya śīghraṃ himāmbupānāni ca bhojanāni"},{"type":"verse","number":"148","sanskrit":"निषेव्यमाणो विनिहन्ति रोगान्सगृध्रसीं नूतनखञ्जताञ्च प्लीहानमुग्रं जठराग्निगुल्मं पाण्डुत्वकण्डूवमिवातरक्तम्","text":"niṣevyamāṇo vinihanti rogānsagṛdhrasīṃ nūtanakhañjatāñca plīhānamugraṃ jaṭharāgnigulmaṃ pāṇḍutvakaṇḍūvamivātaraktam"},{"type":"verse","number":"149","sanskrit":"पथ्यादिको गुग्गुलुरेष नाम्ना ख्यातः क्षितावप्रमितप्रभावः बलेन नागेन समं मनुष्यं जवेन कुर्यात्तुरगेण तुल्यम्","text":"pathyādiko guggulureṣa nāmnā khyātaḥ kṣitāvapramitaprabhāvaḥ balena nāgena samaṃ manuṣyaṃ javena kuryātturageṇa tulyam"},{"type":"verse","number":"150","sanskrit":"आयुः प्रकर्षं विदधाति चक्षुर्बलं तथा पुष्टिकरो विषघ्नः क्षतस्य सन्धानकरो विशेषाद्रो गेषु शस्तः सकलेषु तज्ज्ञैः","text":"āyuḥ prakarṣaṃ vidadhāti cakṣurbalaṃ tathā puṣṭikaro viṣaghnaḥ kṣatasya sandhānakaro viśeṣādro geṣu śastaḥ sakaleṣu tajjñaiḥ"},{"type":"verse","number":"151","sanskrit":"वायुः कट्याश्रितः सक्थ्नः कण्डरामाक्षिपेद्यदा खञ्जस्तदाभवेज्जन्तुः पङ्गुः सक्थ्नोर्द्वयोर्वधात्","text":"vāyuḥ kaṭyāśritaḥ sakthnaḥ kaṇḍarāmākṣipedyadā khañjastadābhavejjantuḥ paṅguḥ sakthnordvayorvadhāt"},{"type":"verse","number":"152","sanskrit":"उपाचरेदभिनवं खञ्जं पङ्गुमथापि च विरेकास्थापनस्वेदगुग्गुलुस्नेहवस्तिभिः","text":"upācaredabhinavaṃ khañjaṃ paṅgumathāpi ca virekāsthāpanasvedaguggulusnehavastibhiḥ"},{"type":"verse","number":"153","sanskrit":"कम्पते गमनारम्भे खञ्जन्निव च लक्ष्यते कलायखञ्जं तं विद्यान्मुक्तसन्धिप्रबन्धनम्","text":"kampate gamanārambhe khañjanniva ca lakṣyate kalāyakhañjaṃ taṃ vidyānmuktasandhiprabandhanam"},{"type":"verse","number":"154","sanskrit":"क्रमः कलायखञ्जस्य खञ्जपङ्ग्वोरिव स्मृतः विशेषात्स्नेहनं कर्म कार्यमत्र विचक्षणैः","text":"kramaḥ kalāyakhañjasya khañjapaṅgvoriva smṛtaḥ viśeṣātsnehanaṃ karma kāryamatra vicakṣaṇaiḥ"},{"type":"verse","number":"155","sanskrit":"वातशोणितजः शोथो जानुमध्ये महारुजः ज्ञेयः क्रोष्टुकशीर्षस्तु स्थूलः क्रोष्टुकशीर्षवत्","text":"vātaśoṇitajaḥ śotho jānumadhye mahārujaḥ jñeyaḥ kroṣṭukaśīrṣastu sthūlaḥ kroṣṭukaśīrṣavat"},{"type":"verse","number":"156","sanskrit":"गुग्गुलुं क्रोष्टुशीर्षे तु गुडूचीत्रिफलाऽम्भसा क्षीरेणैरण्ड तैलं वा पिबेद्वा वृद्धदारकम्","text":"gugguluṃ kroṣṭuśīrṣe tu guḍūcītriphalā'mbhasā kṣīreṇairaṇḍa tailaṃ vā pibedvā vṛddhadārakam"},{"type":"verse","number":"157","sanskrit":"रसैस्तित्तिरमांसस्य पीतेर्गुग्गुलुसंयुतैः वातरक्तक्रियाभिश्च जयेज्जम्बूकमस्तकम्","text":"rasaistittiramāṃsasya pīterguggulusaṃyutaiḥ vātaraktakriyābhiśca jayejjambūkamastakam"},{"type":"verse","number":"158","sanskrit":"खल्लीतु पादजङ्घोरुकरमूलावमोटिनी","text":"khallītu pādajaṅghorukaramūlāvamoṭinī"},{"type":"verse","number":"159","sanskrit":"कुष्ठसैन्धवयोः कल्कश्चुक्रतैलसमन्वितः सुखोष्णो मर्दने योज्यः खल्लीशूलनिवारणः","text":"kuṣṭhasaindhavayoḥ kalkaścukratailasamanvitaḥ sukhoṣṇo mardane yojyaḥ khallīśūlanivāraṇaḥ"},{"type":"verse","number":"160","sanskrit":"रुक् पादे विषमे न्यस्ते श्रमाद्वा जायते यदा वातेन गुल्फमाश्रित्य तमाहुर्वातकण्टकम्","text":"ruk pāde viṣame nyaste śramādvā jāyate yadā vātena gulphamāśritya tamāhurvātakaṇṭakam"},{"type":"verse","number":"161","sanskrit":"रक्तावसेचनं कुर्यादभीक्ष्णं वातकण्टके पिबेदैरण्डतैलं वा दहेत्सूचीभिरेव च","text":"raktāvasecanaṃ kuryādabhīkṣṇaṃ vātakaṇṭake pibedairaṇḍatailaṃ vā dahetsūcībhireva ca"},{"type":"verse","number":"162","sanskrit":"पादयोः कुरुते दाहं पित्तासृक्सहितोऽनिलः विशेषतश्चङ्क्रमणे पाददाहं तमादिशेत्","text":"pādayoḥ kurute dāhaṃ pittāsṛksahito'nilaḥ viśeṣataścaṅkramaṇe pādadāhaṃ tamādiśet"},{"type":"verse","number":"163","sanskrit":"वातरक्तक्रमं कुर्यात्पाददाहे विशेषतः मसूरविदलैः पिष्टैः शृतशीतेन वारिणा चरणौ लेपयेत्सम्यग्पाददाहप्रशान्तये","text":"vātaraktakramaṃ kuryātpādadāhe viśeṣataḥ masūravidalaiḥ piṣṭaiḥ śṛtaśītena vāriṇā caraṇau lepayetsamyagpādadāhapraśāntaye"},{"type":"verse","number":"164","sanskrit":"नवनीतेन संलिप्तौ वह्निना परिता पितौ मुच्येते चरणौ क्षिप्रं परितापात्सुदारुणात्","text":"navanītena saṃliptau vahninā paritā pitau mucyete caraṇau kṣipraṃ paritāpātsudāruṇāt"},{"type":"verse","number":"165","sanskrit":"हृष्येते चरणौ यस्य भवतश्च प्रसुप्तकौ पादहर्षः स विज्ञेयः कफवातप्रकोपजः","text":"hṛṣyete caraṇau yasya bhavataśca prasuptakau pādaharṣaḥ sa vijñeyaḥ kaphavātaprakopajaḥ"},{"type":"verse","number":"166","sanskrit":"पादहर्षे तु कर्त्तव्यः कफवातहरो विधिः","text":"pādaharṣe tu karttavyaḥ kaphavātaharo vidhiḥ"},{"type":"verse","number":"167","sanskrit":"यदा तु धमनीः सर्वाः कुपितोऽभ्येति मारुतः तदा क्षिपत्याशु मुहुर्मुहुर्देहं मुहुश्चलः मुहुराक्षेपणाद्वायुराक्षेपक इति स्मृतः","text":"yadā tu dhamanīḥ sarvāḥ kupito'bhyeti mārutaḥ tadā kṣipatyāśu muhurmuhurdehaṃ muhuścalaḥ muhurākṣepaṇādvāyurākṣepaka iti smṛtaḥ"},{"type":"verse","number":"168","sanskrit":"पित्तश्लेष्मान्वितो वायुर्वायुरेव च केवलः कुर्यादाक्षेपकं चान्यं चतुर्थमभिघातजम्","text":"pittaśleṣmānvito vāyurvāyureva ca kevalaḥ kuryādākṣepakaṃ cānyaṃ caturthamabhighātajam"},{"type":"verse","number":"169","sanskrit":"पाणिपादशिरः पृष्ठश्रोणीः स्तभ्नाति मारुतः दण्डवत्स्तब्धगात्रस्य दण्डकः सोऽनुपक्रमः","text":"pāṇipādaśiraḥ pṛṣṭhaśroṇīḥ stabhnāti mārutaḥ daṇḍavatstabdhagātrasya daṇḍakaḥ so'nupakramaḥ"},{"type":"verse","number":"170","sanskrit":"कफावृतो यदा वायुर्धमनीष्वेव तिष्ठति स दण्डवत्स्तम्भयति कृच्छ्रो दण्डापतानकः","text":"kaphāvṛto yadā vāyurdhamanīṣveva tiṣṭhati sa daṇḍavatstambhayati kṛcchro daṇḍāpatānakaḥ"},{"type":"verse","number":"171","sanskrit":"बलामूलकषायस्य दशमूलीशृतस्य च यवकोलकुलत्थानां क्वाथस्य पयसस्तथा","text":"balāmūlakaṣāyasya daśamūlīśṛtasya ca yavakolakulatthānāṃ kvāthasya payasastathā"},{"type":"verse","number":"172","sanskrit":"अष्टावष्टौ स्मृता भागास्तैलादेकस्तदेकतः पचेदवाप्य मधुरं गणं सैन्धवसंयुतम्","text":"aṣṭāvaṣṭau smṛtā bhāgāstailādekastadekataḥ pacedavāpya madhuraṃ gaṇaṃ saindhavasaṃyutam"},{"type":"verse","number":"173","sanskrit":"तथाऽगुरुं सर्जरसं सरलं देवदारु च मञ्जिष्ठां पद्मकं कुष्ठमेलां कालानुसारिवाम्","text":"tathā'guruṃ sarjarasaṃ saralaṃ devadāru ca mañjiṣṭhāṃ padmakaṃ kuṣṭhamelāṃ kālānusārivām"},{"type":"verse","number":"174","sanskrit":"मांसीं शैलेयकं पत्रं तगरं सारिवां वचाम् शतावरीमश्वगन्धां शतपुष्पां पुनर्नवाम्","text":"māṃsīṃ śaileyakaṃ patraṃ tagaraṃ sārivāṃ vacām śatāvarīmaśvagandhāṃ śatapuṣpāṃ punarnavām"},{"type":"verse","number":"175","sanskrit":"तत्साधुसिद्धं सौवर्णे राजते मृण्मयेऽपि वा प्रक्षिप्य कलशे सम्यक्स्वनुगुप्तं निधापयेत्","text":"tatsādhusiddhaṃ sauvarṇe rājate mṛṇmaye'pi vā prakṣipya kalaśe samyaksvanuguptaṃ nidhāpayet"},{"type":"verse","number":"176","sanskrit":"एतन्महाबलातैलं प्रयुक्तमविलम्बितम् सर्वानाक्षेपकादींस्तु वातव्याधीन्व्यपोहति","text":"etanmahābalātailaṃ prayuktamavilambitam sarvānākṣepakādīṃstu vātavyādhīnvyapohati"},{"type":"verse","number":"177","sanskrit":"हिक्कां श्वासमधीमन्थं गुल्मं कासं सुदुस्तरम् षण्मासादुपयुक्तं तदन्त्रवृद्धिञ्च नाशयेत्","text":"hikkāṃ śvāsamadhīmanthaṃ gulmaṃ kāsaṃ sudustaram ṣaṇmāsādupayuktaṃ tadantravṛddhiñca nāśayet"},{"type":"verse","number":"178","sanskrit":"यथाबलमतो मात्रां सूतिकायै च दापयेत् या च गर्भार्थिनी नारी क्षीणशुक्रश्च यः पुमान्","text":"yathābalamato mātrāṃ sūtikāyai ca dāpayet yā ca garbhārthinī nārī kṣīṇaśukraśca yaḥ pumān"},{"type":"verse","number":"179","sanskrit":"क्षीणवाते मर्महते ह्यभिघातहते तथा भग्ने श्रमाभिपन्ने च सर्वथैतत्प्रयुज्यते","text":"kṣīṇavāte marmahate hyabhighātahate tathā bhagne śramābhipanne ca sarvathaitatprayujyate"},{"type":"verse","number":"180","sanskrit":"एतद्धि राज्ञा कर्त्तव्यं कर्त्तव्यं राजपूजितैः सुखिभिः सुकुमारैश्च धनिभिर्मानवैः सदा","text":"etaddhi rājñā karttavyaṃ karttavyaṃ rājapūjitaiḥ sukhibhiḥ sukumāraiśca dhanibhirmānavaiḥ sadā"},{"type":"verse","number":"181","sanskrit":"अङ्गुलीगुल्फजठरहृद्व क्षोगलसंश्रितः स्नायुप्रतानमनिलस्तदाऽक्षिपतिवेगवान्","text":"aṅgulīgulphajaṭharahṛdva kṣogalasaṃśritaḥ snāyupratānamanilastadā'kṣipativegavān"},{"type":"verse","number":"182","sanskrit":"विष्टब्धाक्षः स्तब्धहनुर्भग्नपार्श्वः कफं वमन्","text":"viṣṭabdhākṣaḥ stabdhahanurbhagnapārśvaḥ kaphaṃ vaman"},{"type":"verse","number":"183","sanskrit":"अभ्यन्तरे धनुरिव यदा नमति मानवः तदा सोऽभ्यन्तरायामं कुरुते मारुतो बली","text":"abhyantare dhanuriva yadā namati mānavaḥ tadā so'bhyantarāyāmaṃ kurute māruto balī"},{"type":"verse","number":"184","sanskrit":"महाहेतुर्बली वायुःसशिराः स्नायुकण्डराः मन्यापृष्ठाश्रिता बाह्यः संशोष्यानामयेद् बहिः","text":"mahāheturbalī vāyuḥsaśirāḥ snāyukaṇḍarāḥ manyāpṛṣṭhāśritā bāhyaḥ saṃśoṣyānāmayed bahiḥ"},{"type":"verse","number":"185","sanskrit":"यत्र तं बहिरायामं प्रवदन्ति भिषग्वराः तमसाध्यं बुधाः प्राहुर्वक्षः कट्यूरुभञ्जनम्","text":"yatra taṃ bahirāyāmaṃ pravadanti bhiṣagvarāḥ tamasādhyaṃ budhāḥ prāhurvakṣaḥ kaṭyūrubhañjanam"},{"type":"verse","number":"186","sanskrit":"बाह्यायामेऽन्तरायामे विधेयाऽदितवत्क्रिया","text":"bāhyāyāme'ntarāyāme vidheyā'ditavatkriyā"},{"type":"verse","number":"187","sanskrit":"धनुस्तुल्यो नमेद्यस्तु स धनुः स्तम्भसञ्ज्ञितः विवर्णो बद्धवदनः स्रस्ताङ्गो नष्टचेतनः प्रस्विद्यंश्च धनुःस्तम्भी दशरात्रं न जीवति","text":"dhanustulyo namedyastu sa dhanuḥ stambhasañjñitaḥ vivarṇo baddhavadanaḥ srastāṅgo naṣṭacetanaḥ prasvidyaṃśca dhanuḥstambhī daśarātraṃ na jīvati"},{"type":"verse","number":"188","sanskrit":"हृदयं यदि वा पृष्ठमुन्नतं क्रमतः सरुक् क्रुद्धो वायुर्यदा कुर्यात्तदा तं कुब्जमादिशेत्","text":"hṛdayaṃ yadi vā pṛṣṭhamunnataṃ kramataḥ saruk kruddho vāyuryadā kuryāttadā taṃ kubjamādiśet"},{"type":"verse","number":"189","sanskrit":"बाह्यायामेऽन्तरायामे धनुःस्तंभे च कुब्जके योज्यं प्रसारणीतैलं तेन तेषां शमो भवेत्","text":"bāhyāyāme'ntarāyāme dhanuḥstaṃbhe ca kubjake yojyaṃ prasāraṇītailaṃ tena teṣāṃ śamo bhavet"},{"type":"verse","number":"190","sanskrit":"वातव्याधिषु सामान्या याः क्रियाः कथिताः पुरा कर्त्तव्या एव ताः सर्वास्तैलमेतद्विशेषतः","text":"vātavyādhiṣu sāmānyā yāḥ kriyāḥ kathitāḥ purā karttavyā eva tāḥ sarvāstailametadviśeṣataḥ"},{"type":"verse","number":"191","sanskrit":"क्रुद्धः स्वैः कोपनैर्वायुः स्थानादूर्ध्वं प्रपद्यते पीडयन्हृदयं गत्वा शिरः शङ्खौ च पीडयन्","text":"kruddhaḥ svaiḥ kopanairvāyuḥ sthānādūrdhvaṃ prapadyate pīḍayanhṛdayaṃ gatvā śiraḥ śaṅkhau ca pīḍayan"},{"type":"verse","number":"192","sanskrit":"धनुर्वन्नमयेद्गात्राण्या क्षिपेन्मोहयेत्तथा स कृच्छ्रादुच्छ्वसेदुच्चैः स्तब्धाक्षोऽथ निमीलकः कपोत इव कूजेच्च निः संज्ञः सोऽपतन्त्रकः","text":"dhanurvannamayedgātrāṇyā kṣipenmohayettathā sa kṛcchrāducchvaseduccaiḥ stabdhākṣo'tha nimīlakaḥ kapota iva kūjecca niḥ saṃjñaḥ so'patantrakaḥ"},{"type":"verse","number":"193","sanskrit":"अथापतन्त्रकेणार्त्तमातुरं नापतर्पयेत् निरूहवस्तिं वमनं सेवयेन्न कदाचन","text":"athāpatantrakeṇārttamāturaṃ nāpatarpayet nirūhavastiṃ vamanaṃ sevayenna kadācana"},{"type":"verse","number":"194","sanskrit":"श्वसनाः कफवाताभ्यां रुद्धास्तस्य विमोक्षयेत् तीक्ष्णैः प्रधमनैः संज्ञां तासु मुक्तासु विन्दति","text":"śvasanāḥ kaphavātābhyāṃ ruddhāstasya vimokṣayet tīkṣṇaiḥ pradhamanaiḥ saṃjñāṃ tāsu muktāsu vindati"},{"type":"verse","number":"195","sanskrit":"मरिचं शिग्रुबीजानि विडङ्गश्च फणिज्जकम् एतानिसूक्ष्मचूर्णानि दद्याच्छीर्षविरेचने","text":"maricaṃ śigrubījāni viḍaṅgaśca phaṇijjakam etānisūkṣmacūrṇāni dadyācchīrṣavirecane"},{"type":"verse","number":"196","sanskrit":"हरीतकी वचा रास्ना सैन्धवं साम्लवेतसम्","text":"harītakī vacā rāsnā saindhavaṃ sāmlavetasam"},{"type":"verse","number":"197","sanskrit":"घृतमार्द्र कसंयुक्तमपतन्त्रकनाशनम् अम्लवेतसकाभावे चुक्रं दातव्यमीरितम्","text":"ghṛtamārdra kasaṃyuktamapatantrakanāśanam amlavetasakābhāve cukraṃ dātavyamīritam"},{"type":"verse","number":"198","sanskrit":"दृष्टिं संस्तभ्य संज्ञाश्च हत्वा कण्ठेन कूजति हृदि मुक्ते नरः स्वास्थ्यं याति मोहं वृते पुनः वायुना दारुणं प्राहुरेके तमपतानकम्","text":"dṛṣṭiṃ saṃstabhya saṃjñāśca hatvā kaṇṭhena kūjati hṛdi mukte naraḥ svāsthyaṃ yāti mohaṃ vṛte punaḥ vāyunā dāruṇaṃ prāhureke tamapatānakam"},{"type":"verse","number":"199","sanskrit":"गर्भजातनिमित्तश्च शोणितातिस्रवाच्च यः अभिघातनिमितश्च न सिध्यत्यपतानकः","text":"garbhajātanimittaśca śoṇitātisravācca yaḥ abhighātanimitaśca na sidhyatyapatānakaḥ"},{"type":"verse","number":"200","sanskrit":"अथापतानकेनार्त्तमस्रुता क्षमवेपनम् अखट्वापातिनं चैव त्वरया समुपाचरेत्","text":"athāpatānakenārttamasrutā kṣamavepanam akhaṭvāpātinaṃ caiva tvarayā samupācaret"},{"type":"verse","number":"201","sanskrit":"अपतानकिने शस्तं दशमूलीशृतं जलम् पिप्पलीचूर्णसंयुक्तं जीर्णं मांसरसौदनम्","text":"apatānakine śastaṃ daśamūlīśṛtaṃ jalam pippalīcūrṇasaṃyuktaṃ jīrṇaṃ māṃsarasaudanam"},{"type":"verse","number":"202","sanskrit":"तैलेन मर्दनं चैव तथा तीक्ष्णं विरेचनम् स्रोतोविशोधनं पश्चात् सर्पिष्पानं हितं स्मृतम्","text":"tailena mardanaṃ caiva tathā tīkṣṇaṃ virecanam srotoviśodhanaṃ paścāt sarpiṣpānaṃ hitaṃ smṛtam"},{"type":"verse","number":"203","sanskrit":"हन्त्यभुक्तवता पीतमम्लं दध्यपतानकम् मरिचेन समायुक्तं स्नेहवस्तिरथापि वा","text":"hantyabhuktavatā pītamamlaṃ dadhyapatānakam maricena samāyuktaṃ snehavastirathāpi vā"},{"type":"verse","number":"204","sanskrit":"गृहीत्वाऽद्ध तनोर्वायुः शिरा स्नायूर्विशोष्य च पक्षमन्यतरं हन्ति सन्धिबन्धान्विमोक्षयन्","text":"gṛhītvā'ddha tanorvāyuḥ śirā snāyūrviśoṣya ca pakṣamanyataraṃ hanti sandhibandhānvimokṣayan"},{"type":"verse","number":"205","sanskrit":"कृत्स्नोऽद्धकायस्तस्य स्यादकर्मण्यो विचेतनः एकाङ्गवातं तं केचिदन्ये पक्षवधं विदुः","text":"kṛtsno'ddhakāyastasya syādakarmaṇyo vicetanaḥ ekāṅgavātaṃ taṃ kecidanye pakṣavadhaṃ viduḥ"},{"type":"verse","number":"206","sanskrit":"दाहसन्तापमूर्च्छाः स्युर्वायौ पित्तसमन्विते शैत्यशोथगुरुत्वानि तस्मिन्नेव कफावृते","text":"dāhasantāpamūrcchāḥ syurvāyau pittasamanvite śaityaśothagurutvāni tasminneva kaphāvṛte"},{"type":"verse","number":"207","sanskrit":"शुद्धवातहतं पक्षं कृच्छ्रसाध्यतमं विदुः साध्यमन्येन संयुक्तमसाध्यं क्षयहेतुकम्","text":"śuddhavātahataṃ pakṣaṃ kṛcchrasādhyatamaṃ viduḥ sādhyamanyena saṃyuktamasādhyaṃ kṣayahetukam"},{"type":"verse","number":"208","sanskrit":"गर्भिणीसूतिकाबालवृद्धक्षीणेष्वसृक्क्षये पक्षाघातं परिहरेद्वेदनारहितो यदि","text":"garbhiṇīsūtikābālavṛddhakṣīṇeṣvasṛkkṣaye pakṣāghātaṃ pariharedvedanārahito yadi"},{"type":"verse","number":"209","sanskrit":"अथ पक्षाघातचिकित्सा माषात्मगुप्तावातारिवाट्यालकजटाशृतम्","text":"atha pakṣāghātacikitsā māṣātmaguptāvātārivāṭyālakajaṭāśṛtam"},{"type":"verse","number":"210","sanskrit":"हिङ्गुसैन्धवसंयुक्तं पक्षाघातं विनाशयेत् माषिके हिङ्गुसिन्धूत्थे जरणाद्यास्तु शाणिकाः","text":"hiṅgusaindhavasaṃyuktaṃ pakṣāghātaṃ vināśayet māṣike hiṅgusindhūtthe jaraṇādyāstu śāṇikāḥ"},{"type":"verse","number":"211","sanskrit":"ग्रन्थिकाग्निकणाशुण्ठीरास्नासैन्धवकल्कितम् माषाक्वाथशृतं तैलं पक्षाघातं व्यपोहति","text":"granthikāgnikaṇāśuṇṭhīrāsnāsaindhavakalkitam māṣākvāthaśṛtaṃ tailaṃ pakṣāghātaṃ vyapohati"},{"type":"verse","number":"212","sanskrit":"माषात्मगुप्ताऽतिविषोरुबूकरास्नाशताह्वालवणैः सुपिष्टैः चतुर्गुणे माषबलाकषाये तैलं शृतं हन्ति हि पक्षघातम्","text":"māṣātmaguptā'tiviṣorubūkarāsnāśatāhvālavaṇaiḥ supiṣṭaiḥ caturguṇe māṣabalākaṣāye tailaṃ śṛtaṃ hanti hi pakṣaghātam"},{"type":"verse","number":"213","sanskrit":"सर्वाङ्गपवने क्रुद्धे गात्रस्फुरणभञ्जने वेदनाभिः परीताश्च स्फुटन्तीवास्य सन्धयः","text":"sarvāṅgapavane kruddhe gātrasphuraṇabhañjane vedanābhiḥ parītāśca sphuṭantīvāsya sandhayaḥ"},{"type":"verse","number":"214","sanskrit":"सर्वाङ्गगतमेकाङ्गगतञ्चापि समीरणम् तैलावगाहनं हन्ति तोयवेगमिवाचलः","text":"sarvāṅgagatamekāṅgagatañcāpi samīraṇam tailāvagāhanaṃ hanti toyavegamivācalaḥ"},{"type":"verse","number":"215","sanskrit":"स्थाननामानुरूपैश्च लिङ्गैः शेषान्विनिर्दिशेत् सर्वेष्वेतेषु संसर्गं पित्ताद्यैरुपलक्षयेत्","text":"sthānanāmānurūpaiśca liṅgaiḥ śeṣānvinirdiśet sarveṣveteṣu saṃsargaṃ pittādyairupalakṣayet"},{"type":"verse","number":"216","sanskrit":"प्रथमं ह्रस्वकेशत्वं ततो वाचालताऽपि च आटोपः पार्श्वशूलञ्च पुरीषस्यातिगाढता","text":"prathamaṃ hrasvakeśatvaṃ tato vācālatā'pi ca āṭopaḥ pārśvaśūlañca purīṣasyātigāḍhatā"},{"type":"verse","number":"217","sanskrit":"तथा मलाप्रवृत्तिश्च कम्पः स्तम्भश्च रूक्षता कार्श्यं कार्ष्ण्यञ्च शैत्यञ्च लोमहर्षो व्यथा तथा","text":"tathā malāpravṛttiśca kampaḥ stambhaśca rūkṣatā kārśyaṃ kārṣṇyañca śaityañca lomaharṣo vyathā tathā"},{"type":"verse","number":"218","sanskrit":"तोदो भेदः शिरास्फूर्त्तिरङ्गमर्दोऽङ्गशुष्कता संकोचश्चाङ्गविभ्रंशो मोहश्चञ्चलचित्तता","text":"todo bhedaḥ śirāsphūrttiraṅgamardo'ṅgaśuṣkatā saṃkocaścāṅgavibhraṃśo mohaścañcalacittatā"},{"type":"verse","number":"219","sanskrit":"निद्रा नाशः स्वेदनाशो बलहानिश्च भीरुता शुक्रक्षयो रजोनाशो गर्भनाशः परिश्रमः","text":"nidrā nāśaḥ svedanāśo balahāniśca bhīrutā śukrakṣayo rajonāśo garbhanāśaḥ pariśramaḥ"},{"type":"verse","number":"220","sanskrit":"सामान्यवातरोगाणां या चिकित्सा प्रवक्ष्यते एषां सातु विधातव्या तयैते यान्ति संक्षयम्","text":"sāmānyavātarogāṇāṃ yā cikitsā pravakṣyate eṣāṃ sātu vidhātavyā tayaite yānti saṃkṣayam"},{"type":"verse","number":"221","sanskrit":"एवंविधानि रूपाणि करोति कुपितोऽनिलः हेतुस्थानविशेषेण भवेद्रो गविशेषकृत्","text":"evaṃvidhāni rūpāṇi karoti kupito'nilaḥ hetusthānaviśeṣeṇa bhavedro gaviśeṣakṛt"},{"type":"verse","number":"222","sanskrit":"उदाने पित्तसंयुक्ते दाहो मूर्च्छा भ्रमः क्लमः अस्वेदहर्षौ मन्दाग्निः शीतता च कफावृते","text":"udāne pittasaṃyukte dāho mūrcchā bhramaḥ klamaḥ asvedaharṣau mandāgniḥ śītatā ca kaphāvṛte"},{"type":"verse","number":"223","sanskrit":"प्राणे पित्तावृते छर्दिर्दाहश्चैवोपजायते दौर्बल्यं सदनं तन्द्रा वैरस्यञ्च कफावृते","text":"prāṇe pittāvṛte chardirdāhaścaivopajāyate daurbalyaṃ sadanaṃ tandrā vairasyañca kaphāvṛte"},{"type":"verse","number":"224","sanskrit":"स्वेदो दाहस्तृषा मूर्च्छा समाने पित्तसंयुते कफेन सक्ते विण्मूत्रे गात्रहर्षश्च जायते","text":"svedo dāhastṛṣā mūrcchā samāne pittasaṃyute kaphena sakte viṇmūtre gātraharṣaśca jāyate"},{"type":"verse","number":"225","sanskrit":"अपाने पित्तसंयुक्ते दाहौष्ण्यं रक्तमूत्रता अधःकाये गुरुत्वञ्च शीतता च कफावृते","text":"apāne pittasaṃyukte dāhauṣṇyaṃ raktamūtratā adhaḥkāye gurutvañca śītatā ca kaphāvṛte"},{"type":"verse","number":"226","sanskrit":"व्याने पित्तावृते दाहो गात्रविक्षेपणं क्लमः स्तम्भोऽथ दण्डकश्चापि शूलशोथौ कफावृते","text":"vyāne pittāvṛte dāho gātravikṣepaṇaṃ klamaḥ stambho'tha daṇḍakaścāpi śūlaśothau kaphāvṛte"},{"type":"verse","number":"227","sanskrit":"वाते सपित्ते कुर्वीत वातपित्तहरीः क्रियाः सकफे तत्र कुर्वीत वातश्लेष्महरीं क्रियाम्","text":"vāte sapitte kurvīta vātapittaharīḥ kriyāḥ sakaphe tatra kurvīta vātaśleṣmaharīṃ kriyām"},{"type":"verse","number":"228","sanskrit":"त्वग्रूक्षा स्फुटिता सुप्ता कृशा कृष्णा च तुद्यते आतन्यते सरागा च सर्वरुक्त्वग्गतेऽनिले","text":"tvagrūkṣā sphuṭitā suptā kṛśā kṛṣṇā ca tudyate ātanyate sarāgā ca sarvaruktvaggate'nile"},{"type":"verse","number":"229","sanskrit":"रुजस्तीव्राः ससन्तापा वैवर्ण्यं कृशताऽरुचिः गात्रे चारूंषि भुक्तस्यस्तम्भश्चासृग्गतेऽनिले","text":"rujastīvrāḥ sasantāpā vaivarṇyaṃ kṛśatā'ruciḥ gātre cārūṃṣi bhuktasyastambhaścāsṛggate'nile"},{"type":"verse","number":"230","sanskrit":"गुर्वङ्गं तुद्यते स्तब्धं दण्डमुष्टिहतं यथा सरुक्स्तिमितमत्यर्थं वाते मांससमाश्रिते","text":"gurvaṅgaṃ tudyate stabdhaṃ daṇḍamuṣṭihataṃ yathā sarukstimitamatyarthaṃ vāte māṃsasamāśrite"},{"type":"verse","number":"231","sanskrit":"तथा मेदःश्रितः कुर्याद् ग्रन्थीन्मन्दरुजो व्रणान्","text":"tathā medaḥśritaḥ kuryād granthīnmandarujo vraṇān"},{"type":"verse","number":"232","sanskrit":"भेदोऽस्थिपर्वणां सन्धिशूलं मांसबलक्षयः अस्वप्नः सतता रुक् च वाते दुष्टेऽस्थिसंस्थिते वाते मज्जगते पीडा न कदाचित्प्रशाम्यति","text":"bhedo'sthiparvaṇāṃ sandhiśūlaṃ māṃsabalakṣayaḥ asvapnaḥ satatā ruk ca vāte duṣṭe'sthisaṃsthite vāte majjagate pīḍā na kadācitpraśāmyati"},{"type":"verse","number":"233","sanskrit":"क्षिप्रं मुञ्चति बध्नाति शुक्रं गर्भमथापि वा विकृतिं जनयेच्चापि शुक्रस्थः कुपितोऽनिलः","text":"kṣipraṃ muñcati badhnāti śukraṃ garbhamathāpi vā vikṛtiṃ janayeccāpi śukrasthaḥ kupito'nilaḥ"},{"type":"verse","number":"234","sanskrit":"वायौ त्वगाश्रिते स्नेहाभ्यङ्गं स्वेदञ्च कारयेत् रक्तस्थे शीतलांल्लेपान्विरेकं रक्तमोक्षणम्","text":"vāyau tvagāśrite snehābhyaṅgaṃ svedañca kārayet raktasthe śītalāṃllepānvirekaṃ raktamokṣaṇam"},{"type":"verse","number":"235","sanskrit":"मांसमेदोगते वाते सविरेकं निरूहणम् अस्थिमज्जगते स्नेहं बहिरन्तश्च योजयेत्","text":"māṃsamedogate vāte savirekaṃ nirūhaṇam asthimajjagate snehaṃ bahirantaśca yojayet"},{"type":"verse","number":"236","sanskrit":"केतकनागबलाऽतिबलानां यद्बहुलेन रसेन विपक्वम् तैलमनल्पतुषोदकसिद्धं मारुतमस्थिगतं विनिहन्ति","text":"ketakanāgabalā'tibalānāṃ yadbahulena rasena vipakvam tailamanalpatuṣodakasiddhaṃ mārutamasthigataṃ vinihanti"},{"type":"verse","number":"237","sanskrit":"हर्षोऽन्नपानं शुक्रस्थे बलशुक्रकरं हितम्","text":"harṣo'nnapānaṃ śukrasthe balaśukrakaraṃ hitam"},{"type":"verse","number":"238","sanskrit":"अथ स्थानविशेषेण वातव्याधिविशेषाः वाते कोष्ठाश्रिते दुष्टे निग्रहो मूत्रवर्चसोः ब्रध्नहृद्रो गगुल्मार्शः पार्श्वशूलञ्च जायते","text":"atha sthānaviśeṣeṇa vātavyādhiviśeṣāḥ vāte koṣṭhāśrite duṣṭe nigraho mūtravarcasoḥ bradhnahṛdro gagulmārśaḥ pārśvaśūlañca jāyate"},{"type":"verse","number":"239","sanskrit":"पाचनीयै रसेर्युक्तैरन्यैर्वा पाचयेन्मलान् विशेषतः पिबेत्क्षीरं नरः कोष्ठगतेऽनिले","text":"pācanīyai raseryuktairanyairvā pācayenmalān viśeṣataḥ pibetkṣīraṃ naraḥ koṣṭhagate'nile"},{"type":"verse","number":"240","sanskrit":"हृत्पार्श्वोदरनाभीरुक्तृष्णोद्गारविसूचिकाः कासः कण्ठास्यशोषश्च श्वासश्चामाशयेऽनिले","text":"hṛtpārśvodaranābhīruktṛṣṇodgāravisūcikāḥ kāsaḥ kaṇṭhāsyaśoṣaśca śvāsaścāmāśaye'nile"},{"type":"verse","number":"241","sanskrit":"आमाशयस्थे त्वनिले प्रशस्तं प्राग् लङ्घनं दीपनपाचनञ्च प्रच्छर्दनं तीक्ष्णविरेचनं वा मुद्गा यवाः शालियुताः पुराणाः","text":"āmāśayasthe tvanile praśastaṃ prāg laṅghanaṃ dīpanapācanañca pracchardanaṃ tīkṣṇavirecanaṃ vā mudgā yavāḥ śāliyutāḥ purāṇāḥ"},{"type":"verse","number":"242","sanskrit":"भूतीकपथ्याशटिपुष्कराणि बिल्वामृतादारुकनागराणि उग्राविषामागधिकाविडानिक्वाथास्त्रयः सामसमीरणघ्नाः","text":"bhūtīkapathyāśaṭipuṣkarāṇi bilvāmṛtādārukanāgarāṇi ugrāviṣāmāgadhikāviḍānikvāthāstrayaḥ sāmasamīraṇaghnāḥ"},{"type":"verse","number":"243","sanskrit":"चित्रकेन्द्र यवौ पाठा कटुकातिविषाऽभया आमाशयोत्थवातघ्नं चूर्णं पेयं सुखाम्बुना","text":"citrakendra yavau pāṭhā kaṭukātiviṣā'bhayā āmāśayotthavātaghnaṃ cūrṇaṃ peyaṃ sukhāmbunā"},{"type":"verse","number":"244","sanskrit":"योगेऽस्मिन्भिषजा ग्राह्याः षण्णां षड्धरणाः पृथक् दिनेषु षट्सु दातव्यास्तेन षड् धरणः स्मृतः","text":"yoge'sminbhiṣajā grāhyāḥ ṣaṇṇāṃ ṣaḍdharaṇāḥ pṛthak dineṣu ṣaṭsu dātavyāstena ṣaḍ dharaṇaḥ smṛtaḥ"},{"type":"verse","number":"245","sanskrit":"आमाशयगते वाते छर्दिताय यथाक्रमम् देयः षड्धरणो योगः सप्तरात्रं सुखाम्बुना","text":"āmāśayagate vāte charditāya yathākramam deyaḥ ṣaḍdharaṇo yogaḥ saptarātraṃ sukhāmbunā"},{"type":"verse","number":"246","sanskrit":"पक्वाशयस्थोऽन्त्रकूजं शूलाटोपौ करोति च कृच्छ्रमूत्रपुरीषत्वमानाहं त्रिकवेदनाम्","text":"pakvāśayastho'ntrakūjaṃ śūlāṭopau karoti ca kṛcchramūtrapurīṣatvamānāhaṃ trikavedanām"},{"type":"verse","number":"247","sanskrit":"वह्नेः सम्वर्द्धनं कार्यं कर्मौदावर्त्तकं तथा देयः स्नेहविरेकश्च पक्वाशयगतेऽनिले","text":"vahneḥ samvarddhanaṃ kāryaṃ karmaudāvarttakaṃ tathā deyaḥ snehavirekaśca pakvāśayagate'nile"},{"type":"verse","number":"248","sanskrit":"वाते जठरगे दद्यात्क्षारचूर्णादि दीपनम्","text":"vāte jaṭharage dadyātkṣāracūrṇādi dīpanam"},{"type":"verse","number":"249","sanskrit":"शुण्ठीकुटजबीजाग्निचूर्ण कोष्णाम्बु कुक्षिगे","text":"śuṇṭhīkuṭajabījāgnicūrṇa koṣṇāmbu kukṣige"},{"type":"verse","number":"250","sanskrit":"ग्रहो विण्मूत्रवातानां शूलाध्मानाश्मशर्कराः जङ्घोरुत्रिकपार्श्वांसपृष्ठरोगी गुदेऽनिले","text":"graho viṇmūtravātānāṃ śūlādhmānāśmaśarkarāḥ jaṅghorutrikapārśvāṃsapṛṣṭharogī gude'nile"},{"type":"verse","number":"251","sanskrit":"वाते गुदगते दुष्टे कर्मोदावर्त्तकं हितम्","text":"vāte gudagate duṣṭe karmodāvarttakaṃ hitam"},{"type":"verse","number":"252","sanskrit":"हृदयानिलनाशाय गुडूचीं मरिचान्विताम् पिबेत्प्रातः प्रयत्नेन सुखं तप्ताम्भसा सह पिबेदुष्णाम्भसा पिष्टमाश्वगन्धं बिभीतकम् गुडयुक्तं प्रयत्नेन हृदयानिलनाशनम् देवदारुसमायुक्तं नागरं परिपेषितम् हृद्वातवेदनायुक्तः पीत्वा सुखमवाप्नुयात्","text":"hṛdayānilanāśāya guḍūcīṃ maricānvitām pibetprātaḥ prayatnena sukhaṃ taptāmbhasā saha pibeduṣṇāmbhasā piṣṭamāśvagandhaṃ bibhītakam guḍayuktaṃ prayatnena hṛdayānilanāśanam devadārusamāyuktaṃ nāgaraṃ paripeṣitam hṛdvātavedanāyuktaḥ pītvā sukhamavāpnuyāt"},{"type":"verse","number":"253","sanskrit":"श्रोत्रादिष्विन्द्रि यवधं कुर्यात्क्रुद्धः समीरणः","text":"śrotrādiṣvindri yavadhaṃ kuryātkruddhaḥ samīraṇaḥ"},{"type":"verse","number":"254","sanskrit":"श्रोत्रादिष्वनिले दुष्टे कार्यो वातहरः क्रमः स्नेहाभ्यङ्गावगाहाश्च मर्दनालेपनानि च","text":"śrotrādiṣvanile duṣṭe kāryo vātaharaḥ kramaḥ snehābhyaṅgāvagāhāśca mardanālepanāni ca"},{"type":"verse","number":"255","sanskrit":"कुर्याच्छिरागतः शूलं शिराकुञ्चनपूरणम् स बाह्याभ्यन्तरायामं खल्लीं कुब्जत्वमेव च","text":"kuryācchirāgataḥ śūlaṃ śirākuñcanapūraṇam sa bāhyābhyantarāyāmaṃ khallīṃ kubjatvameva ca"},{"type":"verse","number":"256","sanskrit":"स्नेहाभ्यङ्गोपनाहाश्च मर्दनालेपनानि च वाते शिरोगते कुर्यात्तथा चासृग्विमोक्षणम्","text":"snehābhyaṅgopanāhāśca mardanālepanāni ca vāte śirogate kuryāttathā cāsṛgvimokṣaṇam"},{"type":"verse","number":"257","sanskrit":"शूलमाक्षेपकः कम्पः स्तम्भः स्नाय्वनिलाद्भवेत् स्वेदोपनाहाग्निकर्मबन्धनोन्मर्दनानि च क्रुद्धे स्नायुगते वाते कारयेत्कुशलो भिषक्","text":"śūlamākṣepakaḥ kampaḥ stambhaḥ snāyvanilādbhavet svedopanāhāgnikarmabandhanonmardanāni ca kruddhe snāyugate vāte kārayetkuśalo bhiṣak"},{"type":"verse","number":"258","sanskrit":"हन्ति सन्धिगतः सन्धीञ्छूलशोथौ करोति च","text":"hanti sandhigataḥ sandhīñchūlaśothau karoti ca"},{"type":"verse","number":"259","sanskrit":"कुर्यात्सन्धिगते वाते दाहस्नेहोपनाहनम् इन्द्र वारुणिकामूलं मागधीगुडसंयुतम् भक्षयेत्कर्षमात्रं तत्सन्धिवातं व्यपोहति","text":"kuryātsandhigate vāte dāhasnehopanāhanam indra vāruṇikāmūlaṃ māgadhīguḍasaṃyutam bhakṣayetkarṣamātraṃ tatsandhivātaṃ vyapohati"},{"type":"verse","number":"260","sanskrit":"हनुस्तम्भार्दिताक्षेपपक्षाघातापतानकाः कालेन महता यत्नात्सिध्यन्ति न च वा न वा","text":"hanustambhārditākṣepapakṣāghātāpatānakāḥ kālena mahatā yatnātsidhyanti na ca vā na vā"},{"type":"verse","number":"261","sanskrit":"नवान् बलवतां त्वेतान् साधयेन्निरुपद्र वान्","text":"navān balavatāṃ tvetān sādhayennirupadra vān"},{"type":"verse","number":"262","sanskrit":"विसर्पदाहरुग्भङ्गमूर्च्छाऽरुच्यग्निमार्दवैः क्षीणमांसबलं वाता घ्नन्ति पक्षवधादतः","text":"visarpadāharugbhaṅgamūrcchā'rucyagnimārdavaiḥ kṣīṇamāṃsabalaṃ vātā ghnanti pakṣavadhādataḥ"},{"type":"verse","number":"263","sanskrit":"शूनं सुप्तत्वचं म्लानं कम्पाध्माननिपीडितम् रुजाऽत्तिमन्तञ्च नरं वातव्याधिर्विनाशयेत्","text":"śūnaṃ suptatvacaṃ mlānaṃ kampādhmānanipīḍitam rujā'ttimantañca naraṃ vātavyādhirvināśayet"},{"type":"verse","number":"264","sanskrit":"अव्याहतगतिर्यस्य स्थानस्थः प्रकृतौ स्थितः वायुः स्यात्सोऽधिकं जीवेद्वीतरोगः समाः शतम्","text":"avyāhatagatiryasya sthānasthaḥ prakṛtau sthitaḥ vāyuḥ syātso'dhikaṃ jīvedvītarogaḥ samāḥ śatam"},{"type":"verse","number":"265","sanskrit":"अथ वातव्याधीनां सामान्यानि भेषजानि माषस्यार्द्धाढकं देयं तुलार्द्धं दशमूलतः पलानि च्छागमांसस्य त्रिंशद्द्रो णेऽम्भसः पचेत्","text":"atha vātavyādhīnāṃ sāmānyāni bheṣajāni māṣasyārddhāḍhakaṃ deyaṃ tulārddhaṃ daśamūlataḥ palāni cchāgamāṃsasya triṃśaddro ṇe'mbhasaḥ pacet"},{"type":"verse","number":"266","sanskrit":"चतुर्भागावशेषं तं कषायमवतारयेत् प्रस्थञ्च तिलतैलस्य पयो दद्याच्चतुगुर्णम्","text":"caturbhāgāvaśeṣaṃ taṃ kaṣāyamavatārayet prasthañca tilatailasya payo dadyāccatugurṇam"},{"type":"verse","number":"267","sanskrit":"जीवनीयानि मञ्जिष्ठा चव्यं चित्रककट्फलम् सव्योषं पिप्पलीमूलं रास्नामलकगोक्षुरम्","text":"jīvanīyāni mañjiṣṭhā cavyaṃ citrakakaṭphalam savyoṣaṃ pippalīmūlaṃ rāsnāmalakagokṣuram"},{"type":"verse","number":"268","sanskrit":"आत्मगुप्ता तथैरण्डः शताह्वा लवणत्रयम् देवदार्वमृताकुष्ठमश्वगन्धा वचा शटी","text":"ātmaguptā tathairaṇḍaḥ śatāhvā lavaṇatrayam devadārvamṛtākuṣṭhamaśvagandhā vacā śaṭī"},{"type":"verse","number":"269","sanskrit":"एतैरक्षमितैः कल्कैः पाचयेन्मृदुनाग्निना पक्षाघातार्दिते पुंसि हनुस्तम्भार्दिते तथा","text":"etairakṣamitaiḥ kalkaiḥ pācayenmṛdunāgninā pakṣāghātārdite puṃsi hanustambhārdite tathā"},{"type":"verse","number":"270","sanskrit":"कर्णशूले शिरः शूले तिमिरे च त्रिदोषजे पाणिपादशिरोग्रीवाभ्रमणे मन्दचङ्क्रमे","text":"karṇaśūle śiraḥ śūle timire ca tridoṣaje pāṇipādaśirogrīvābhramaṇe mandacaṅkrame"},{"type":"verse","number":"271","sanskrit":"कलायखञ्जे पङ्गौ च गृध्रस्यामपबाहुके पाने वस्तौ तथाऽभ्यङ्गे नस्ये कर्णादिपूरणे","text":"kalāyakhañje paṅgau ca gṛdhrasyāmapabāhuke pāne vastau tathā'bhyaṅge nasye karṇādipūraṇe"},{"type":"verse","number":"272","sanskrit":"तैलमेतत्प्रशंसन्ति सर्ववातविकारनुत् महामाषादिनामेदं भाषितं मुनिभिः पुरा","text":"tailametatpraśaṃsanti sarvavātavikāranut mahāmāṣādināmedaṃ bhāṣitaṃ munibhiḥ purā"},{"type":"verse","number":"273","sanskrit":"माषा यवातसीक्षुद्रा मर्कटी च कुरण्टकः","text":"māṣā yavātasīkṣudrā markaṭī ca kuraṇṭakaḥ"},{"type":"verse","number":"274","sanskrit":"गोकण्टष्टुण्टुकश्चैषां प्रत्येकं पलसप्तकम् चतुर्गुणाम्बुना पक्त्वा पादशेषं शृतं नयेत्","text":"gokaṇṭaṣṭuṇṭukaścaiṣāṃ pratyekaṃ palasaptakam caturguṇāmbunā paktvā pādaśeṣaṃ śṛtaṃ nayet"},{"type":"verse","number":"275","sanskrit":"कार्पासकास्थि बदरं शणबीजं कुलत्थकम् पृथक्चतुर्दशपलं चतुर्गुणजले पचेत्","text":"kārpāsakāsthi badaraṃ śaṇabījaṃ kulatthakam pṛthakcaturdaśapalaṃ caturguṇajale pacet"},{"type":"verse","number":"276","sanskrit":"कषायं तत्र गृह्णीयाच्चतुर्थांशावशेषितम् प्रस्थञ्च च्छागमांसस्य चतुःषष्टिपले जले","text":"kaṣāyaṃ tatra gṛhṇīyāccaturthāṃśāvaśeṣitam prasthañca cchāgamāṃsasya catuḥṣaṣṭipale jale"},{"type":"verse","number":"277","sanskrit":"प्रक्षिप्य पाचयेद्धीमान्पादशेषं रसं नयेत् तैलप्रस्थे ततः क्वाथान्सर्वास्तान्क्रमतः पचेत्","text":"prakṣipya pācayeddhīmānpādaśeṣaṃ rasaṃ nayet tailaprasthe tataḥ kvāthānsarvāstānkramataḥ pacet"},{"type":"verse","number":"278","sanskrit":"कल्कद्र व्यैः पचेदेभिरमृताकुष्ठसैन्धवैः रास्नापुनर्नवैरण्डैः पिप्पल्या शतपुष्पया","text":"kalkadra vyaiḥ pacedebhiramṛtākuṣṭhasaindhavaiḥ rāsnāpunarnavairaṇḍaiḥ pippalyā śatapuṣpayā"},{"type":"verse","number":"279","sanskrit":"बलाप्रसारणीभ्याञ्च मांस्या कटुकया तथा पृथक्कर्षमितैरेतैः साधयेन्मृदुनाग्निना","text":"balāprasāraṇībhyāñca māṃsyā kaṭukayā tathā pṛthakkarṣamitairetaiḥ sādhayenmṛdunāgninā"},{"type":"verse","number":"280","sanskrit":"हन्यात्तैलमिदं शीघ्रं वातव्याधीनशेषतः आक्षेपकं पक्षघातमूरुस्तम्भापबाहुकौ हस्तकम्पं शिरः कम्पं विश्वाचीमर्दितं तथा","text":"hanyāttailamidaṃ śīghraṃ vātavyādhīnaśeṣataḥ ākṣepakaṃ pakṣaghātamūrustambhāpabāhukau hastakampaṃ śiraḥ kampaṃ viśvācīmarditaṃ tathā"},{"type":"verse","number":"281","sanskrit":"अश्वगन्धाबलाबिल्वं पाटलाबृहतीद्वयम् श्वदंष्ट्रातिवलानिम्बश्योनाकञ्च पुनर्नवाम्","text":"aśvagandhābalābilvaṃ pāṭalābṛhatīdvayam śvadaṃṣṭrātivalānimbaśyonākañca punarnavām"},{"type":"verse","number":"282","sanskrit":"प्रसारणीमग्निमन्थं कुर्याद्दशपलं पृथक् चतुर्द्रोणे जले पक्त्वा पादशेषं शृतं नयेत्","text":"prasāraṇīmagnimanthaṃ kuryāddaśapalaṃ pṛthak caturdroṇe jale paktvā pādaśeṣaṃ śṛtaṃ nayet"},{"type":"verse","number":"283","sanskrit":"तैलाढकेन संयोज्य शतावर्या रसाढकम् प्रक्षिपेत्तत्र गोक्षीरं ततस्तैलाच्चतुर्गुणम्","text":"tailāḍhakena saṃyojya śatāvaryā rasāḍhakam prakṣipettatra gokṣīraṃ tatastailāccaturguṇam"},{"type":"verse","number":"284","sanskrit":"पृथक्पलमितैः कल्कैर्द्र व्यैरेभिः पचेद्भिषक् वचाचन्दनकुष्ठैलामांसीशैलेयसैन्धवैः","text":"pṛthakpalamitaiḥ kalkairdra vyairebhiḥ pacedbhiṣak vacācandanakuṣṭhailāmāṃsīśaileyasaindhavaiḥ"},{"type":"verse","number":"285","sanskrit":"अश्वगन्धाबलारास्नाशतपुष्पेन्द्र दारुभिः पर्णीचतुष्टयेनैव तगरेण प्रसाधयेत्","text":"aśvagandhābalārāsnāśatapuṣpendra dārubhiḥ parṇīcatuṣṭayenaiva tagareṇa prasādhayet"},{"type":"verse","number":"286","sanskrit":"तत्तैलं भोजनेऽभ्यङ्गे पाने वस्तौ च योजयेत् पक्षाघातं हनुस्तम्भं मन्यास्तम्भं गलग्रहम्","text":"tattailaṃ bhojane'bhyaṅge pāne vastau ca yojayet pakṣāghātaṃ hanustambhaṃ manyāstambhaṃ galagraham"},{"type":"verse","number":"287","sanskrit":"कुब्जत्वं बधिरत्वञ्च गतिभङ्गं कटीग्रहम् गात्रशोषेन्द्रि यध्वंसं शुक्रनाशं ज्वरक्षयान्","text":"kubjatvaṃ badhiratvañca gatibhaṅgaṃ kaṭīgraham gātraśoṣendri yadhvaṃsaṃ śukranāśaṃ jvarakṣayān"},{"type":"verse","number":"288","sanskrit":"अन्त्रवृद्धिं कुरण्डञ्च दन्तरोगं शिरोग्रहम् पार्श्वशूलञ्च पङ्गुत्वं बुद्धिनाशञ्च गृध्रसीम्","text":"antravṛddhiṃ kuraṇḍañca dantarogaṃ śirograham pārśvaśūlañca paṅgutvaṃ buddhināśañca gṛdhrasīm"},{"type":"verse","number":"289","sanskrit":"अन्यांश्च विविधान्वातान्हरेत्सर्वाङ्गसंश्रयान् अस्याः प्रभावाद्वन्ध्याऽपि नारी पुत्रं प्रसूयते","text":"anyāṃśca vividhānvātānharetsarvāṅgasaṃśrayān asyāḥ prabhāvādvandhyā'pi nārī putraṃ prasūyate"},{"type":"verse","number":"290","sanskrit":"यथा नारायणो देवो दुष्टदैत्यविनाशनः तथेदं वातरोगाणां नाशनं तैलमुत्तमम्","text":"yathā nārāyaṇo devo duṣṭadaityavināśanaḥ tathedaṃ vātarogāṇāṃ nāśanaṃ tailamuttamam"},{"type":"verse","number":"291","sanskrit":"तिलतैलं समादाय चतुराढकसम्मितम् पञ्चपल्लवकल्केन शोधयेद्दोषशान्तये","text":"tilatailaṃ samādāya caturāḍhakasammitam pañcapallavakalkena śodhayeddoṣaśāntaye"},{"type":"verse","number":"292","sanskrit":"तत्राजं दुग्धमथवा गव्यं तैलसमं पचेत् शतावरीरसञ्चापि तैलतुल्यं पचेद्भिषक्","text":"tatrājaṃ dugdhamathavā gavyaṃ tailasamaṃ pacet śatāvarīrasañcāpi tailatulyaṃ pacedbhiṣak"},{"type":"verse","number":"293","sanskrit":"दशमूली बला रास्ना शिग्रूत्पलपुनर्नवाः शेफालिका नागबला बला चैव प्रसारणी","text":"daśamūlī balā rāsnā śigrūtpalapunarnavāḥ śephālikā nāgabalā balā caiva prasāraṇī"},{"type":"verse","number":"294","sanskrit":"अश्वगन्धा सहचरो दशमूलं करञ्जकः खदिरं चन्दनं लोध्रं वचाऽसनपलाशकम्","text":"aśvagandhā sahacaro daśamūlaṃ karañjakaḥ khadiraṃ candanaṃ lodhraṃ vacā'sanapalāśakam"},{"type":"verse","number":"295","sanskrit":"वकुलैरण्डवरुणशालयुग्मकटम्भराः शिरीष शिखरी वासाहिंस्राजम्बूबिभीतकम्","text":"vakulairaṇḍavaruṇaśālayugmakaṭambharāḥ śirīṣa śikharī vāsāhiṃsrājambūbibhītakam"},{"type":"verse","number":"296","sanskrit":"काञ्चनारः कपित्थश्च पारिभद्रः प्रियालकम् पाषाणभेदः शम्पाको दुग्धिका दाडिमीफलम्","text":"kāñcanāraḥ kapitthaśca pāribhadraḥ priyālakam pāṣāṇabhedaḥ śampāko dugdhikā dāḍimīphalam"},{"type":"verse","number":"297","sanskrit":"उदुम्बरः सप्तला च कन्यका मालतीत्वचम् मागधी नलमूलञ्च यवकोलकुलत्थकम्","text":"udumbaraḥ saptalā ca kanyakā mālatītvacam māgadhī nalamūlañca yavakolakulatthakam"},{"type":"verse","number":"298","sanskrit":"आत्मगुप्ताऽककार्पासबीजं वत्सादनी स्नुही केतकीमूलधत्तूरलाङ्गलीगर्दभाण्डकम्","text":"ātmaguptā'kakārpāsabījaṃ vatsādanī snuhī ketakīmūladhattūralāṅgalīgardabhāṇḍakam"},{"type":"verse","number":"299","sanskrit":"चित्रकञ्च महानिम्बं पञ्चवल्कलमेव च मुण्डी टङ्कारी मुशली हंसपादी विशल्यकम्","text":"citrakañca mahānimbaṃ pañcavalkalameva ca muṇḍī ṭaṅkārī muśalī haṃsapādī viśalyakam"},{"type":"verse","number":"300","sanskrit":"एषां दशपलान्भागान्वारिण्यष्टगुणे पचेत् पादशेषं परिस्राव्य तत्र तैलं पुनः पचेत्","text":"eṣāṃ daśapalānbhāgānvāriṇyaṣṭaguṇe pacet pādaśeṣaṃ parisrāvya tatra tailaṃ punaḥ pacet"},{"type":"verse","number":"301","sanskrit":"छागो मेषश्च हरिण एणश्च बहुशृङ्गकः शशः शल्यः शिवा गोधा सिंहो व्याघ्रश्च भल्लुकः","text":"chāgo meṣaśca hariṇa eṇaśca bahuśṛṅgakaḥ śaśaḥ śalyaḥ śivā godhā siṃho vyāghraśca bhallukaḥ"},{"type":"verse","number":"302","sanskrit":"वन्यो वराहः खड्गी च महिषो घोटकस्तथा कपिर्बभ्रुर्विडालश्च मूषकश्चोरुदर्दुरः","text":"vanyo varāhaḥ khaḍgī ca mahiṣo ghoṭakastathā kapirbabhrurviḍālaśca mūṣakaścorudarduraḥ"},{"type":"verse","number":"303","sanskrit":"वर्त्तिकस्तित्तिरिर्लावः खञ्जरीटश्चकोरकः उलूको नीलकण्ठश्च वन्यकुक्कुट एव च","text":"varttikastittirirlāvaḥ khañjarīṭaścakorakaḥ ulūko nīlakaṇṭhaśca vanyakukkuṭa eva ca"},{"type":"verse","number":"304","sanskrit":"गृध्रश्च गरुडो हंसश्चक्रः कारण्डवोऽपि च कपोतः सारसः क्रौञ्चो वन्यः पारावतस्तथा","text":"gṛdhraśca garuḍo haṃsaścakraḥ kāraṇḍavo'pi ca kapotaḥ sārasaḥ krauñco vanyaḥ pārāvatastathā"},{"type":"verse","number":"305","sanskrit":"रोहितो मद्गुरश्चापि शिलीन्ध्रः शृङ्गकस्तथा इल्लिसो गर्गरो वर्मिरथ काकः पिकोऽपि च","text":"rohito madguraścāpi śilīndhraḥ śṛṅgakastathā illiso gargaro varmiratha kākaḥ piko'pi ca"},{"type":"verse","number":"306","sanskrit":"महामत्स्यः कच्छपश्च शिशुमारश्च साङ्कुचिः मकरो घण्टिकाऽकारस्तदलाभे तु गोधिका","text":"mahāmatsyaḥ kacchapaśca śiśumāraśca sāṅkuciḥ makaro ghaṇṭikā'kārastadalābhe tu godhikā"},{"type":"verse","number":"307","sanskrit":"यथालाभममीषाञ्च क्वाथं तैलसमं पचेत्","text":"yathālābhamamīṣāñca kvāthaṃ tailasamaṃ pacet"},{"type":"verse","number":"308","sanskrit":"रास्नाऽश्वगन्धामिसिदारुकुष्ठपर्णीचतुष्कागुरुकेशराणि सिन्धूत्थमांसीरजनीद्वयञ्च शैलेयकं चन्दन पुष्करञ्च","text":"rāsnā'śvagandhāmisidārukuṣṭhaparṇīcatuṣkāgurukeśarāṇi sindhūtthamāṃsīrajanīdvayañca śaileyakaṃ candana puṣkarañca"},{"type":"verse","number":"309","sanskrit":"एला सयष्टी तगराब्दपत्रं भृङ्गोऽष्टवर्गस्तुवचा पलाशी स्थौणेयवृश्चीरकचोरकाख्यं मूर्वात्वचं कट्फलपद्मकं च","text":"elā sayaṣṭī tagarābdapatraṃ bhṛṅgo'ṣṭavargastuvacā palāśī sthauṇeyavṛścīrakacorakākhyaṃ mūrvātvacaṃ kaṭphalapadmakaṃ ca"},{"type":"verse","number":"310","sanskrit":"मृणालजातीफलकेतकाख्यं सनागपुष्पं सरलं मुरा च जीवन्तिकोशीरवरास्तथैव दुरालभा वानरिका नखश्च","text":"mṛṇālajātīphalaketakākhyaṃ sanāgapuṣpaṃ saralaṃ murā ca jīvantikośīravarāstathaiva durālabhā vānarikā nakhaśca"},{"type":"verse","number":"311","sanskrit":"कैवर्त्तमुस्तार्जुनतिक्तकञ्च वातामखर्जूरकतुम्बुराश्च सधातकीग्रन्थिकपर्पटाश्च पटोलहेमाह्वजयन्तिकाश्च","text":"kaivarttamustārjunatiktakañca vātāmakharjūrakatumburāśca sadhātakīgranthikaparpaṭāśca paṭolahemāhvajayantikāśca"},{"type":"verse","number":"312","sanskrit":"त्रायन्तिकाऽलम्बुषशक्रबीजं रसाञ्जनाभात्रिवृतारुणाश्च द्रा क्षाकणाद्रो णपुनर्नवाश्च कौन्ती कृमिघ्नो हयमारकश्च","text":"trāyantikā'lambuṣaśakrabījaṃ rasāñjanābhātrivṛtāruṇāśca drā kṣākaṇādro ṇapunarnavāśca kauntī kṛmighno hayamārakaśca"},{"type":"verse","number":"313","sanskrit":"नीलोत्पलं पद्मककारवीभ्यां रम्भाऽनलो गोक्षुरकः क्षुरश्च कङ्कोलकालेयकुसुम्भपुष्पं तुरुष्ककाश्मीरकसिक्थकञ्च लवङ्गकर्पूररसालकाण्डकस्तूरिकाबालकमम्बरञ्च","text":"nīlotpalaṃ padmakakāravībhyāṃ rambhā'nalo gokṣurakaḥ kṣuraśca kaṅkolakāleyakusumbhapuṣpaṃ turuṣkakāśmīrakasikthakañca lavaṅgakarpūrarasālakāṇḍakastūrikābālakamambarañca"},{"type":"verse","number":"314","sanskrit":"कल्कानमीषां विपचेत्सुवैद्यः पृथक् पृथक् कर्षयुगोन्मितानाम् शुभे च नक्षत्रमुहूर्त्तलग्ने सन्तोष्य विप्रांश्च भिषग्वरांश्च","text":"kalkānamīṣāṃ vipacetsuvaidyaḥ pṛthak pṛthak karṣayugonmitānām śubhe ca nakṣatramuhūrttalagne santoṣya viprāṃśca bhiṣagvarāṃśca"},{"type":"verse","number":"315","sanskrit":"सम्पूज्य नारायणनामधेयं देवं त्रिनेत्रं जगतामधीशम् पात्रे तु हेम्नः खलु राजते वा ताम्रेऽथ वा लोहमयेऽपि रक्षेत्","text":"sampūjya nārāyaṇanāmadheyaṃ devaṃ trinetraṃ jagatāmadhīśam pātre tu hemnaḥ khalu rājate vā tāmre'tha vā lohamaye'pi rakṣet"},{"type":"verse","number":"316","sanskrit":"अभ्यञ्जनेऽञ्जने नस्ये निरूहेचावगाहने पाने चैतद्यथाव्याधि प्रयुञ्जीत चिकित्सकः","text":"abhyañjane'ñjane nasye nirūhecāvagāhane pāne caitadyathāvyādhi prayuñjīta cikitsakaḥ"},{"type":"verse","number":"317","sanskrit":"बहुनाऽत्र किमुक्तेन तैलमेतत्प्रयोजितम् अवश्यं वातजान्व्याधीनशीतिमति नाशयेत्","text":"bahunā'tra kimuktena tailametatprayojitam avaśyaṃ vātajānvyādhīnaśītimati nāśayet"},{"type":"verse","number":"318","sanskrit":"एतस्याभ्यासतो जन्तोर्जरा जातु न जायते पतन्ति वलयो नाङ्गे पलितञ्च न जायते","text":"etasyābhyāsato jantorjarā jātu na jāyate patanti valayo nāṅge palitañca na jāyate"},{"type":"verse","number":"319","sanskrit":"नेत्रं तेजस्वि नितरां गरुडस्येव जायते नोच्चैःश्रुतिर्न बाधिर्यं कर्णनादो न जायते","text":"netraṃ tejasvi nitarāṃ garuḍasyeva jāyate noccaiḥśrutirna bādhiryaṃ karṇanādo na jāyate"},{"type":"verse","number":"320","sanskrit":"पाणिकम्पः शिरः कम्पः प्रलापश्च न जायते बुद्धिभ्रंशो न जायेत तस्मात्कर्मसु पाटवम्","text":"pāṇikampaḥ śiraḥ kampaḥ pralāpaśca na jāyate buddhibhraṃśo na jāyeta tasmātkarmasu pāṭavam"},{"type":"verse","number":"321","sanskrit":"यथा जलेन सिक्तस्य शाखिनः पल्लवादयः वर्द्धन्ते धातवस्तद्वद् देहिनोऽनेन नित्यशः","text":"yathā jalena siktasya śākhinaḥ pallavādayaḥ varddhante dhātavastadvad dehino'nena nityaśaḥ"},{"type":"verse","number":"322","sanskrit":"आमं गर्भं त्यजेज्जातु सूतिका रुग्युता च या याश्च दुष्प्रसवक्षीणास्ताभ्य एतद्धितं परम्","text":"āmaṃ garbhaṃ tyajejjātu sūtikā rugyutā ca yā yāśca duṣprasavakṣīṇāstābhya etaddhitaṃ param"},{"type":"verse","number":"323","sanskrit":"वन्ध्या च लभते पुत्रं गर्भपातो न जायते योनिरोगाः प्रणश्यन्ति प्रदरश्च प्रशाम्यति","text":"vandhyā ca labhate putraṃ garbhapāto na jāyate yonirogāḥ praṇaśyanti pradaraśca praśāmyati"},{"type":"verse","number":"324","sanskrit":"अस्मात्तैलवरादन्यत्कुत्रचिन्नास्ति भेषजम् बल्यं वृष्यं बृहंणञ्च रसायनमिदं महत्","text":"asmāttailavarādanyatkutracinnāsti bheṣajam balyaṃ vṛṣyaṃ bṛhaṃṇañca rasāyanamidaṃ mahat"},{"type":"verse","number":"325","sanskrit":"पुरा देवासुरे युद्धे दैत्यैरभिहतान्सुरान् भिन्नान्भग्नास्थिकान्विद्धान्पिच्चितान्व्यथयाऽदितान्","text":"purā devāsure yuddhe daityairabhihatānsurān bhinnānbhagnāsthikānviddhānpiccitānvyathayā'ditān"},{"type":"verse","number":"326","sanskrit":"दृष्ट्वा हिताय देवानां नराणां चाब्रवीदिदम् तैलं नारायणो देवो महानारायणाभिधम्","text":"dṛṣṭvā hitāya devānāṃ narāṇāṃ cābravīdidam tailaṃ nārāyaṇo devo mahānārāyaṇābhidham"},{"type":"verse","number":"327","sanskrit":"नागरं पिप्पलीमूलंचव्यमूषणचित्रकम् भृष्टं हिङ्ग्वजमोदा च सर्षपो जीरकद्वयम्","text":"nāgaraṃ pippalīmūlaṃcavyamūṣaṇacitrakam bhṛṣṭaṃ hiṅgvajamodā ca sarṣapo jīrakadvayam"},{"type":"verse","number":"328","sanskrit":"रेणुकेन्द्र यवौ पाठा बिडङ्गं गजपिप्पली कटुकाऽतिविषा भार्गी वचा मूर्वा च पत्रकम्","text":"reṇukendra yavau pāṭhā biḍaṅgaṃ gajapippalī kaṭukā'tiviṣā bhārgī vacā mūrvā ca patrakam"},{"type":"verse","number":"329","sanskrit":"देवदारु कणा कुष्ठं रास्ना मुस्ता च सैन्धवम् एला त्रिकण्टकं पथ्या धान्यकञ्च बिभीतकम्","text":"devadāru kaṇā kuṣṭhaṃ rāsnā mustā ca saindhavam elā trikaṇṭakaṃ pathyā dhānyakañca bibhītakam"},{"type":"verse","number":"330","sanskrit":"धात्री च त्वगुशीरञ्च यवक्षारोऽखिलान्यपि एतानि समभागानि सूक्ष्मचूर्णानि कारयेत्","text":"dhātrī ca tvaguśīrañca yavakṣāro'khilānyapi etāni samabhāgāni sūkṣmacūrṇāni kārayet"},{"type":"verse","number":"331","sanskrit":"यावन्त्येतानि चूर्णानि तावानेवात्र गुग्गुलुः संमर्द्य सर्पिषा पश्चात्सर्वं संमिश्रयेच्च तत्","text":"yāvantyetāni cūrṇāni tāvānevātra gugguluḥ saṃmardya sarpiṣā paścātsarvaṃ saṃmiśrayecca tat"},{"type":"verse","number":"332","sanskrit":"एवं पिण्डच्च तत्कृत्वा धारयेद् घृतभाजने गुटिकाष्टङ्कमात्रास्तु खादेत्तास्तु यथोचिताः","text":"evaṃ piṇḍacca tatkṛtvā dhārayed ghṛtabhājane guṭikāṣṭaṅkamātrāstu khādettāstu yathocitāḥ"},{"type":"verse","number":"333","sanskrit":"आदौ शाणोन्मितं खादेत्सार्द्धशाणं ततः परम् तदग्रे कर्षमर्द्धन्तु पूर्णं कर्षं ततः परम्","text":"ādau śāṇonmitaṃ khādetsārddhaśāṇaṃ tataḥ param tadagre karṣamarddhantu pūrṇaṃ karṣaṃ tataḥ param"},{"type":"verse","number":"334","sanskrit":"गुग्गुलुर्योगराजोऽय महामुख्यो रसायनः मैथुनाहारपानानां नियमो नात्र विद्यते","text":"gugguluryogarājo'ya mahāmukhyo rasāyanaḥ maithunāhārapānānāṃ niyamo nātra vidyate"},{"type":"verse","number":"335","sanskrit":"अर्शांसि ग्रहणीरोगं प्लीहगुल्मोदरानपि आनाहं मन्दमग्निञ्च श्वासं कासमरोचकम्","text":"arśāṃsi grahaṇīrogaṃ plīhagulmodarānapi ānāhaṃ mandamagniñca śvāsaṃ kāsamarocakam"},{"type":"verse","number":"336","sanskrit":"प्रमेहं नाभिशूलञ्च कृमिक्षयमुरोग्रहम् सर्वान्वातामयान्हन्यादामवातमपस्मृतिम्","text":"pramehaṃ nābhiśūlañca kṛmikṣayamurograham sarvānvātāmayānhanyādāmavātamapasmṛtim"},{"type":"verse","number":"337","sanskrit":"वातरक्तं तथा कुष्ठं तथा दुष्टव्रणानपि शुक्रदोषं रजोदोषमुदावर्त्तं भगन्दरम्","text":"vātaraktaṃ tathā kuṣṭhaṃ tathā duṣṭavraṇānapi śukradoṣaṃ rajodoṣamudāvarttaṃ bhagandaram"},{"type":"verse","number":"338","sanskrit":"रास्नाऽदिक्वाथसंयुक्तः सर्ववातामयान्हरेत् काकोल्यादिशृतात्पित्तं कफमारग्वधादिना","text":"rāsnā'dikvāthasaṃyuktaḥ sarvavātāmayānharet kākolyādiśṛtātpittaṃ kaphamāragvadhādinā"},{"type":"verse","number":"339","sanskrit":"दार्वीशृतेन मेहांश्च गोमूत्रेण च पाण्डुताम् मधुना मेदसो वृद्धिं कुष्ठं निम्बशृतेन च","text":"dārvīśṛtena mehāṃśca gomūtreṇa ca pāṇḍutām madhunā medaso vṛddhiṃ kuṣṭhaṃ nimbaśṛtena ca"},{"type":"verse","number":"340","sanskrit":"छिन्नाक्वाथेन वातास्रं शोथं मूलकजाच्छृतात् पाटलाक्वाथसहितो विषं मूषकसम्भवम्","text":"chinnākvāthena vātāsraṃ śothaṃ mūlakajācchṛtāt pāṭalākvāthasahito viṣaṃ mūṣakasambhavam"},{"type":"verse","number":"341","sanskrit":"त्रिफलाक्वाथसंयुक्तो दारुणां नेत्रवेदनाम् पुनर्नवाऽदिक्वाथेन हन्ति सर्वोदराण्यपि","text":"triphalākvāthasaṃyukto dāruṇāṃ netravedanām punarnavā'dikvāthena hanti sarvodarāṇyapi"},{"type":"verse","number":"342","sanskrit":"रास्ना पुनर्नवा शुण्ठी गुडूच्येरण्डजं शृतम् सप्तधातुगते वाते सामे सर्वाङ्गगेऽपि चेत्","text":"rāsnā punarnavā śuṇṭhī guḍūcyeraṇḍajaṃ śṛtam saptadhātugate vāte sāme sarvāṅgage'pi cet"},{"type":"verse","number":"343","sanskrit":"युक्तः कल्को रसोनस्य तिलतैलेन सिन्धुना वातरोगान्हरेत्सर्वाञ्ज्वरांश्च विषमानपि","text":"yuktaḥ kalko rasonasya tilatailena sindhunā vātarogānharetsarvāñjvarāṃśca viṣamānapi"},{"type":"verse","number":"344","sanskrit":"क्षीरेण तैलेन घृतेन वाऽपि मांसेन सार्द्धं लशुनानि खादेत् शाल्योदनेनापि च षष्टिकेन पलार्द्धवृद्ध्या दिवसानि सप्त","text":"kṣīreṇa tailena ghṛtena vā'pi māṃsena sārddhaṃ laśunāni khādet śālyodanenāpi ca ṣaṣṭikena palārddhavṛddhyā divasāni sapta"},{"type":"verse","number":"345","sanskrit":"वातोत्थरोगान्विषमज्वरांश्च शूलान्सगुल्मान्दहनस्य मान्द्यम् प्लीहानमुग्रं भुजपार्श्वशूलं शिरोव्यथां कृन्तति शुक्रदोषान्","text":"vātottharogānviṣamajvarāṃśca śūlānsagulmāndahanasya māndyam plīhānamugraṃ bhujapārśvaśūlaṃ śirovyathāṃ kṛntati śukradoṣān"},{"type":"verse","number":"346","sanskrit":"अन्नप्रकारैः पललप्रकारैर्गोधूमकैर्वा यवशक्तुभिर्वा दुग्धेन तैलेन घृतेन वाऽपि युक्तानि शीते लशुनानि खादेत्","text":"annaprakāraiḥ palalaprakārairgodhūmakairvā yavaśaktubhirvā dugdhena tailena ghṛtena vā'pi yuktāni śīte laśunāni khādet"},{"type":"verse","number":"347","sanskrit":"संवर्त्तकैर्लावकपिञ्जलैर्वा मृग्याः पलैर्वाऽप्यथ कौक्कुटैर्वा वाराहवर्त्तीरकहारिणैर्वा सुसंस्कृतैरग्निबलं समीक्ष्य","text":"saṃvarttakairlāvakapiñjalairvā mṛgyāḥ palairvā'pyatha kaukkuṭairvā vārāhavarttīrakahāriṇairvā susaṃskṛtairagnibalaṃ samīkṣya"},{"type":"verse","number":"348","sanskrit":"रसोनपक्वकन्दस्य गुलिका निस्तुषीकृताः पाटयित्वा च मध्यस्थं दूरीकुर्यात्तदङ्कुरम्","text":"rasonapakvakandasya gulikā nistuṣīkṛtāḥ pāṭayitvā ca madhyasthaṃ dūrīkuryāttadaṅkuram"},{"type":"verse","number":"349","sanskrit":"निश्युग्रगन्धनाशाय दध्ना सन्नीय रक्षयेत् ततः प्रक्षाल्य संशोष्य शिलायां परिपेषयेत्","text":"niśyugragandhanāśāya dadhnā sannīya rakṣayet tataḥ prakṣālya saṃśoṣya śilāyāṃ paripeṣayet"},{"type":"verse","number":"350","sanskrit":"कल्कस्य पञ्चमं भागं चूर्णमेषां विनिक्षिपेत् सौवर्चलं यवानीञ्च भर्जितं हिङ्गु सैन्धवम्","text":"kalkasya pañcamaṃ bhāgaṃ cūrṇameṣāṃ vinikṣipet sauvarcalaṃ yavānīñca bharjitaṃ hiṅgu saindhavam"},{"type":"verse","number":"351","sanskrit":"कटुत्रिकं जीरकञ्च समभागानि चूर्णयेत् तिलतैलञ्च कल्कस्य तुर्याशं तत्र मिश्रयेत्","text":"kaṭutrikaṃ jīrakañca samabhāgāni cūrṇayet tilatailañca kalkasya turyāśaṃ tatra miśrayet"},{"type":"verse","number":"352","sanskrit":"खादेत्कर्षमितं प्रातः किं वा दोषाद्यपेक्षया अनुपानं प्रकुर्वीत वातारिशृतमन्वहम्","text":"khādetkarṣamitaṃ prātaḥ kiṃ vā doṣādyapekṣayā anupānaṃ prakurvīta vātāriśṛtamanvaham"},{"type":"verse","number":"353","sanskrit":"सर्वाङ्गैकाङ्गजं वातमर्दितञ्चापतन्त्रकम् अपस्मारं तथोन्मादमूरुस्तम्भञ्च गृध्रसीम्","text":"sarvāṅgaikāṅgajaṃ vātamarditañcāpatantrakam apasmāraṃ tathonmādamūrustambhañca gṛdhrasīm"},{"type":"verse","number":"354","sanskrit":"उरः पृष्ठकटीपार्श्वकुक्षिपीडां कृमीन्हरेत् मद्यं मांसं तथाऽम्लञ्च रसं सेवेत नित्यशः","text":"uraḥ pṛṣṭhakaṭīpārśvakukṣipīḍāṃ kṛmīnharet madyaṃ māṃsaṃ tathā'mlañca rasaṃ seveta nityaśaḥ"},{"type":"verse","number":"355","sanskrit":"आयासमातपं रोषमतिनीरं गुडं स्त्रियम् रसोनमश्नन्पुरुषस्त्यजेदेतन्निरन्तरम्","text":"āyāsamātapaṃ roṣamatinīraṃ guḍaṃ striyam rasonamaśnanpuruṣastyajedetannirantaram"},{"type":"verse","number":"356","sanskrit":"वर्जयेत्तदतीसारी प्रमेही पाण्डुरोगवान् अरोचकी गर्भिणी च मूर्च्छाऽशोरोगसंयुतः","text":"varjayettadatīsārī pramehī pāṇḍurogavān arocakī garbhiṇī ca mūrcchā'śorogasaṃyutaḥ"},{"type":"verse","number":"357","sanskrit":"रक्तपित्ती च शोषी च यक्ष्मी छर्द्यर्दितो नरः पित्ते तु पथ्यभुक्कुर्यात्प्रयोगान्ते विरेचनम्","text":"raktapittī ca śoṣī ca yakṣmī chardyardito naraḥ pitte tu pathyabhukkuryātprayogānte virecanam"},{"type":"verse","number":"358","sanskrit":"अन्यथा तस्य जायन्ते कुष्ठपाण्ड्वामयादयः स्त्रीस्तन्यं त्वरितं दद्याद्वालानामप्यनिच्छताम्","text":"anyathā tasya jāyante kuṣṭhapāṇḍvāmayādayaḥ strīstanyaṃ tvaritaṃ dadyādvālānāmapyanicchatām"},{"type":"verse","number":"359","sanskrit":"तथा च लभते सिद्धिं महावीर्याद्र सोनतः","text":"tathā ca labhate siddhiṃ mahāvīryādra sonataḥ"},{"type":"verse","number":"360","sanskrit":"रसो गन्धो वरा वह्निर्गुग्गुलुः क्रमवर्द्धितः तत्रैकभागः सूतः स्याद्गन्धको द्विगुणः स्मृतः","text":"raso gandho varā vahnirgugguluḥ kramavarddhitaḥ tatraikabhāgaḥ sūtaḥ syādgandhako dviguṇaḥ smṛtaḥ"},{"type":"verse","number":"361","sanskrit":"त्रिभागा त्रिफला योज्या चतुर्भागस्तु चित्रकः गुग्गुलुः पञ्चभागः स्याद्रुबुतैलेन मर्दयेत्","text":"tribhāgā triphalā yojyā caturbhāgastu citrakaḥ gugguluḥ pañcabhāgaḥ syādrubutailena mardayet"},{"type":"verse","number":"362","sanskrit":"क्षित्वा तत्रोदितं चूर्णं तेन तैलेन मर्दयेत् गुटिकां कर्षमात्रान्तु भक्षयेत्प्रातरेव हि","text":"kṣitvā tatroditaṃ cūrṇaṃ tena tailena mardayet guṭikāṃ karṣamātrāntu bhakṣayetprātareva hi"},{"type":"verse","number":"363","sanskrit":"नागरैरण्डमूलानां कषायं प्रपिबेदनु अभ्यज्यैरण्डतैलेन स्वेदयेत्पृष्ठदेशकम्","text":"nāgarairaṇḍamūlānāṃ kaṣāyaṃ prapibedanu abhyajyairaṇḍatailena svedayetpṛṣṭhadeśakam"},{"type":"verse","number":"364","sanskrit":"विरेकपरिणामे तु स्निग्धमुष्णञ्च भोजयेत् वातारिसंज्ञको ह्येष रसो नियतसेवितः मासेन मरुतो रोगान्हरेत्सुरतवर्जिनः","text":"virekapariṇāme tu snigdhamuṣṇañca bhojayet vātārisaṃjñako hyeṣa raso niyatasevitaḥ māsena maruto rogānharetsuratavarjinaḥ"},{"type":"verse","number":"365","sanskrit":"इति चतुर्विंशो वातव्याध्यधिकारः समाप्तः २४","text":"iti caturviṃśo vātavyādhyadhikāraḥ samāptaḥ 24"}]},{"sthana":"Уттаракханда","number":25,"lang":"sa","content":[{"type":"heading","heading":"Урустамбха — скованность бёдер"},{"type":"verse","number":"1","sanskrit":"शीतोष्णद्र वसंशुष्क गुरूस्निग्धैर्निषेवितैः जीर्णाजीर्णे तथायाससङ्क्षोभस्वप्नजागरैः","text":"śītoṣṇadra vasaṃśuṣka gurūsnigdhairniṣevitaiḥ jīrṇājīrṇe tathāyāsasaṅkṣobhasvapnajāgaraiḥ"},{"type":"verse","number":"2","sanskrit":"सश्लेष्ममेदः पवनः साममत्यर्थसञ्चितम् अभिभूयेतरं दोषमूरू चेत् प्रतिपद्यते","text":"saśleṣmamedaḥ pavanaḥ sāmamatyarthasañcitam abhibhūyetaraṃ doṣamūrū cet pratipadyate"},{"type":"verse","number":"3","sanskrit":"सक्थ्यस्थिनी प्रपूर्यान्तः श्लेष्मणा स्तिमितेन सः तदा स्तभ्नाति तेनोरू स्तब्धौ शीतावचेतनौ","text":"sakthyasthinī prapūryāntaḥ śleṣmaṇā stimitena saḥ tadā stabhnāti tenorū stabdhau śītāvacetanau"},{"type":"verse","number":"4","sanskrit":"परकीयाविव गुरू स्यातामतिभृशव्यथौ ध्यानाङ्गमर्दस्तैमित्यतन्द्रा च्छर्द्य रुचिज्वरैः","text":"parakīyāviva gurū syātāmatibhṛśavyathau dhyānāṅgamardastaimityatandrā cchardya rucijvaraiḥ"},{"type":"verse","number":"5","sanskrit":"संयुतौ पादसदनकृच्छ्रोद्धरण सुप्तिभिः तमूरुस्तम्भमित्याहुराढ्य वातमथापरे","text":"saṃyutau pādasadanakṛcchroddharaṇa suptibhiḥ tamūrustambhamityāhurāḍhya vātamathāpare"},{"type":"verse","number":"6","sanskrit":"प्राग्रूपं तस्य निद्रा तिध्यानं स्तिमितता ज्वरः रोमहर्षोऽरुचिश्छर्दिर्जङ्घोर्वोः सदनं तथा","text":"prāgrūpaṃ tasya nidrā tidhyānaṃ stimitatā jvaraḥ romaharṣo'ruciśchardirjaṅghorvoḥ sadanaṃ tathā"},{"type":"verse","number":"7","sanskrit":"वातशङ्किभिरज्ञानात्तत्र स्यात्स्नेहनात्पुनः पादयोः सदनं सुप्तिः कृच्छ्रादुद्धरणं तथा","text":"vātaśaṅkibhirajñānāttatra syātsnehanātpunaḥ pādayoḥ sadanaṃ suptiḥ kṛcchrāduddharaṇaṃ tathā"},{"type":"verse","number":"8","sanskrit":"जङ्घोरुग्लानिरत्यर्थं शश्वद्वादाहवेदना पादञ्च व्यथते न्यस्तं शीतस्पर्शं न वेत्ति च","text":"jaṅghoruglāniratyarthaṃ śaśvadvādāhavedanā pādañca vyathate nyastaṃ śītasparśaṃ na vetti ca"},{"type":"verse","number":"9","sanskrit":"संस्थाने पीडने गत्यां चालने चाप्यनीश्वरः अन्य नेयौ हि सम्भग्नावूरूपादौ च मन्यते","text":"saṃsthāne pīḍane gatyāṃ cālane cāpyanīśvaraḥ anya neyau hi sambhagnāvūrūpādau ca manyate"},{"type":"verse","number":"10","sanskrit":"यदा दाहार्त्तितोदार्त्तो वेपनः पुरुषो भवेत् ऊरुस्तम्भस्तदा हन्यात्साधयेदन्यथा नवम्","text":"yadā dāhārttitodārtto vepanaḥ puruṣo bhavet ūrustambhastadā hanyātsādhayedanyathā navam"},{"type":"verse","number":"11","sanskrit":"स्नेहासृक्स्राववमनं वस्तिकर्म विरेचनम् वर्जयेदाढ्यवाते तु यतस्तैस्तस्य कोपनम्","text":"snehāsṛksrāvavamanaṃ vastikarma virecanam varjayedāḍhyavāte tu yatastaistasya kopanam"},{"type":"verse","number":"12","sanskrit":"तस्मादत्र सदा कार्यं स्वेदलङ्घनरूक्षणम् आममेदः कफाधिक्यान्मारुतं परिरक्षता","text":"tasmādatra sadā kāryaṃ svedalaṅghanarūkṣaṇam āmamedaḥ kaphādhikyānmārutaṃ parirakṣatā"},{"type":"verse","number":"13","sanskrit":"यत्स्यात्कफप्रशमनं न तु मारुतकोपनम् तत्सर्वं सर्वदा कार्यमूरुस्तम्भस्य भेषजम्","text":"yatsyātkaphapraśamanaṃ na tu mārutakopanam tatsarvaṃ sarvadā kāryamūrustambhasya bheṣajam"},{"type":"verse","number":"14","sanskrit":"सर्वो रुक्षः क्रमः कार्यस्तत्रादौ कफनाशनः पश्चाद्वातविनाशाय विधातव्याखिला क्रिया","text":"sarvo rukṣaḥ kramaḥ kāryastatrādau kaphanāśanaḥ paścādvātavināśāya vidhātavyākhilā kriyā"},{"type":"verse","number":"15","sanskrit":"भोज्याः पुराणाः श्यामाककोद्र वोद्दालशालयः जाङ्गलैरघृतैर्मांसैः शाकैश्चालवणैर्हितैः","text":"bhojyāḥ purāṇāḥ śyāmākakodra voddālaśālayaḥ jāṅgalairaghṛtairmāṃsaiḥ śākaiścālavaṇairhitaiḥ"},{"type":"verse","number":"16","sanskrit":"शाकैरलवणैर्दद्याज्जल तैलाज्यसाधितैः सुनिषण्णकनिम्बार्कवृन्ता रग्वधपल्लवैः","text":"śākairalavaṇairdadyājjala tailājyasādhitaiḥ suniṣaṇṇakanimbārkavṛntā ragvadhapallavaiḥ"},{"type":"verse","number":"17","sanskrit":"वायसीवास्तुकाद्यैश्च साधितैः शाकमूलकैः शाकैरलवणैर्युक्तं जीर्णे शाल्योदनं भिषक्","text":"vāyasīvāstukādyaiśca sādhitaiḥ śākamūlakaiḥ śākairalavaṇairyuktaṃ jīrṇe śālyodanaṃ bhiṣak"},{"type":"verse","number":"18","sanskrit":"रूक्षणाद्वातकोपश्चेन्निद्रा नाशार्त्तिपूर्वकः स्नेहस्वेदक्रमस्तत्र कार्यो वातामयापहः","text":"rūkṣaṇādvātakopaścennidrā nāśārttipūrvakaḥ snehasvedakramastatra kāryo vātāmayāpahaḥ"},{"type":"verse","number":"19","sanskrit":"प्रतारयेत्प्रतिस्रोतो नदीं शीतजलां शिवाम् सरश्च विमलं शीतं स्थिरतोयं पुनः पुनः","text":"pratārayetpratisroto nadīṃ śītajalāṃ śivām saraśca vimalaṃ śītaṃ sthiratoyaṃ punaḥ punaḥ"},{"type":"verse","number":"20","sanskrit":"यथा विशुष्केस्य कफे शान्तिमूरुग्रहो व्रजेत् शरीरबलमग्निञ्च कार्यैषा रक्षता क्रिया","text":"yathā viśuṣkesya kaphe śāntimūrugraho vrajet śarīrabalamagniñca kāryaiṣā rakṣatā kriyā"},{"type":"verse","number":"21","sanskrit":"सक्षारमूत्रस्वेदांश्च रुक्षाण्युत्सादनानि च कुर्याद्दाहे च मूत्राद्यैः करञ्जफलसर्षपैः","text":"sakṣāramūtrasvedāṃśca rukṣāṇyutsādanāni ca kuryāddāhe ca mūtrādyaiḥ karañjaphalasarṣapaiḥ"},{"type":"verse","number":"22","sanskrit":"मूलैर्वाप्यश्वगन्धाया मूलैरर्कस्य वा भिषक् पिचुमर्दस्य वा मूलैरथवा देवदारुणः","text":"mūlairvāpyaśvagandhāyā mūlairarkasya vā bhiṣak picumardasya vā mūlairathavā devadāruṇaḥ"},{"type":"verse","number":"23","sanskrit":"क्षौद्र सर्षपवल्मीक मृत्तिकासंयुतैर्भिषक् गाढमुत्सादनं कुर्यादूरूस्तम्भे सवेदने","text":"kṣaudra sarṣapavalmīka mṛttikāsaṃyutairbhiṣak gāḍhamutsādanaṃ kuryādūrūstambhe savedane"},{"type":"verse","number":"24","sanskrit":"दन्तीद्र वन्तीसुरसासर्षपैश्चापि बुद्धिमान् तर्कारीसुरसाशिग्रुव चावत्सकनिम्बकैः पत्रमूलफलैस्तोयं शृतमुष्णञ्च सेवनम्","text":"dantīdra vantīsurasāsarṣapaiścāpi buddhimān tarkārīsurasāśigruva cāvatsakanimbakaiḥ patramūlaphalaistoyaṃ śṛtamuṣṇañca sevanam"},{"type":"verse","number":"25","sanskrit":"भक्लातकामृताशुण्ठीदा रुपथ्यापुनर्नवाः पञ्चमूलीद्वयोन्मिश्रा ऊरुस्तम्भनिबर्हणाः","text":"bhaklātakāmṛtāśuṇṭhīdā rupathyāpunarnavāḥ pañcamūlīdvayonmiśrā ūrustambhanibarhaṇāḥ"},{"type":"verse","number":"26","sanskrit":"पिप्पली पिप्पलीमूलं भल्लातकफलानि च कल्कं मधुयुतं पीत्वा ऊरुस्तम्भाद्विमुच्यते","text":"pippalī pippalīmūlaṃ bhallātakaphalāni ca kalkaṃ madhuyutaṃ pītvā ūrustambhādvimucyate"},{"type":"verse","number":"27","sanskrit":"रास्नाश्यामाकपथ्यामरिचमिसिशिवावेल्लशट्यश्वगन्धा यासच्छिन्नाजमोदासुमुखमतिविषावृद्धदारौ बृहत्यौ शुण्ठी तिक्ता यवानी सहचरचविकैरण्डदार्व्याजकर्णा ऊरुस्तम्भामवातं कफपवनरुजं दण्डकांश्चाशु हन्यात्","text":"rāsnāśyāmākapathyāmaricamisiśivāvellaśaṭyaśvagandhā yāsacchinnājamodāsumukhamativiṣāvṛddhadārau bṛhatyau śuṇṭhī tiktā yavānī sahacaracavikairaṇḍadārvyājakarṇā ūrustambhāmavātaṃ kaphapavanarujaṃ daṇḍakāṃścāśu hanyāt"},{"type":"verse","number":"28","sanskrit":"ग्रन्थिकारुष्ककृष्णानां क्वाथं क्षौद्रा न्वितं पिबेत् लिह्याद्वा त्रिफलाचूर्णं क्षौद्रे ण कटुकायुतम्","text":"granthikāruṣkakṛṣṇānāṃ kvāthaṃ kṣaudrā nvitaṃ pibet lihyādvā triphalācūrṇaṃ kṣaudre ṇa kaṭukāyutam"},{"type":"verse","number":"29","sanskrit":"सुखाम्बुना पिबेद्वापि चूर्णं षड्धरणं नरः पिप्पलीवर्द्धमानं वा माक्षिकेण गुडेन वा","text":"sukhāmbunā pibedvāpi cūrṇaṃ ṣaḍdharaṇaṃ naraḥ pippalīvarddhamānaṃ vā mākṣikeṇa guḍena vā"},{"type":"verse","number":"30","sanskrit":"ऊरुस्तम्भे प्रशंसन्ति गण्डीरारिष्टमेव च","text":"ūrustambhe praśaṃsanti gaṇḍīrāriṣṭameva ca"},{"type":"verse","number":"31","sanskrit":"शिलाजतुं गुग्गुलुं वा पिप्पलीमथ नागरम् ऊरुस्तम्भे पिबेन्मूत्रैर्दशमूलीरसेन वा","text":"śilājatuṃ gugguluṃ vā pippalīmatha nāgaram ūrustambhe pibenmūtrairdaśamūlīrasena vā"},{"type":"verse","number":"32","sanskrit":"त्रिफला पिप्पली मुस्तं चव्यं कटुकरोहिणी लिह्याद्वा मधुना चूर्णमूरुस्तम्भार्दितो नरः","text":"triphalā pippalī mustaṃ cavyaṃ kaṭukarohiṇī lihyādvā madhunā cūrṇamūrustambhārdito naraḥ"},{"type":"verse","number":"33","sanskrit":"घृतं सौरेश्वरं दद्यादूरुस्तम्भे कफोत्तरे दद्याच्छुण्ठीघृतं वापि वैश्वानरमथापि वा सैन्धवाद्यं हितं तैलममृताख्योपि गुग्गुलुः","text":"ghṛtaṃ saureśvaraṃ dadyādūrustambhe kaphottare dadyācchuṇṭhīghṛtaṃ vāpi vaiśvānaramathāpi vā saindhavādyaṃ hitaṃ tailamamṛtākhyopi gugguluḥ"},{"type":"verse","number":"34","sanskrit":"कुष्ठश्रीवेष्टकोदीच्यसरलं दारु केशरम् अजगन्धाश्वगन्धे च तैलं तैः सार्षपं पचेत्","text":"kuṣṭhaśrīveṣṭakodīcyasaralaṃ dāru keśaram ajagandhāśvagandhe ca tailaṃ taiḥ sārṣapaṃ pacet"},{"type":"verse","number":"35","sanskrit":"सक्षौद्र्रं मात्रया तस्मादूरुस्तम्भार्दितः पिबेत्","text":"sakṣaudrraṃ mātrayā tasmādūrustambhārditaḥ pibet"},{"type":"verse","number":"36","sanskrit":"पलाभ्यां पिप्पलीमूलान्नागरादष्टकट्वरम् तैलप्रस्थं समं दध्ना गृध्रस्यूरुग्रहापहम्","text":"palābhyāṃ pippalīmūlānnāgarādaṣṭakaṭvaram tailaprasthaṃ samaṃ dadhnā gṛdhrasyūrugrahāpaham"},{"type":"verse","number":"37","sanskrit":"सस्नेहदधिसम्भूतं तक्रं कट्वरमुच्यते अष्टकट्वरतैलेच तैलंसार्षपमिष्यते पिप्पलीमूलशुण्ठ्योश्च प्रत्येकं द्विपलं कृतम्","text":"sasnehadadhisambhūtaṃ takraṃ kaṭvaramucyate aṣṭakaṭvarataileca tailaṃsārṣapamiṣyate pippalīmūlaśuṇṭhyośca pratyekaṃ dvipalaṃ kṛtam"},{"type":"verse","number":"38","sanskrit":"द्विपञ्चमूली त्रिफला चित्रकं देवदारु च एकाष्ठीला त्वपामार्गे श्रेयसी वायसी शुभा","text":"dvipañcamūlī triphalā citrakaṃ devadāru ca ekāṣṭhīlā tvapāmārge śreyasī vāyasī śubhā"},{"type":"verse","number":"39","sanskrit":"बला भार्गी पृथक्पर्णी सुवहा मदयन्तिका विशालोशीरकाश्मर्यस्तिस्रो देयास्तथाग्निकः","text":"balā bhārgī pṛthakparṇī suvahā madayantikā viśālośīrakāśmaryastisro deyāstathāgnikaḥ"},{"type":"verse","number":"40","sanskrit":"चिरबिल्वो ह्यशोकश्च कलश्यंशुमती तथा पयस्या पीलुपर्ण्यश्च गुडूची च शतावरी","text":"cirabilvo hyaśokaśca kalaśyaṃśumatī tathā payasyā pīluparṇyaśca guḍūcī ca śatāvarī"},{"type":"verse","number":"41","sanskrit":"एषां पञ्च पलान्भागाञ्जलद्रो णेषु सप्तसु अष्टभागावशेषेण पचेत्तैलाढकं भिषक्","text":"eṣāṃ pañca palānbhāgāñjaladro ṇeṣu saptasu aṣṭabhāgāvaśeṣeṇa pacettailāḍhakaṃ bhiṣak"},{"type":"verse","number":"42","sanskrit":"कुष्ठञ्च शतपुष्पा च त्र्यूषणं चित्रकं वरा देवदार्वगुरु श्रेष्ठं विडङ्गं मुस्तमेव च","text":"kuṣṭhañca śatapuṣpā ca tryūṣaṇaṃ citrakaṃ varā devadārvaguru śreṣṭhaṃ viḍaṅgaṃ mustameva ca"},{"type":"verse","number":"43","sanskrit":"अश्वगन्धा स्थिरा पाठा मूली श्यामाकमेव च पिप्पल्यः शृङ्गबेरञ्च दन्ती हिङ्ग्वम्लवेतसम्","text":"aśvagandhā sthirā pāṭhā mūlī śyāmākameva ca pippalyaḥ śṛṅgaberañca dantī hiṅgvamlavetasam"},{"type":"verse","number":"44","sanskrit":"अनेन गर्भेण भिषक्कषायेण च साधयेत् सिद्धशीतञ्चपूतञ्च क्षौद्रे ण सह संसृजेत्","text":"anena garbheṇa bhiṣakkaṣāyeṇa ca sādhayet siddhaśītañcapūtañca kṣaudre ṇa saha saṃsṛjet"},{"type":"verse","number":"45","sanskrit":"तदस्य नस्यपानार्थं तदेवाभ्यञ्जने भवेत्","text":"tadasya nasyapānārthaṃ tadevābhyañjane bhavet"},{"type":"verse","number":"46","sanskrit":"ऊरुस्तम्भश्चिरोद्भूतस्तैलेनानेन शाम्यति आमवातं शीतवातं क्षुद्र वातञ्च नाशयेत्","text":"ūrustambhaścirodbhūtastailenānena śāmyati āmavātaṃ śītavātaṃ kṣudra vātañca nāśayet"},{"type":"verse","number":"47","sanskrit":"सिन्धुरुग्विश्वजासोग्राभार्गीयष्टीस्थिराफलैः दारुविश्वशटीधान्यकृष्णाकट्फलपौष्करः","text":"sindhurugviśvajāsogrābhārgīyaṣṭīsthirāphalaiḥ dāruviśvaśaṭīdhānyakṛṣṇākaṭphalapauṣkaraḥ"},{"type":"verse","number":"48","sanskrit":"दीप्यकातिविषैरण्डनीलीनीलाम्बुजःपचेत् तैलं सकाञ्जिकं हन्ति पानाभ्यञ्जननावनैः","text":"dīpyakātiviṣairaṇḍanīlīnīlāmbujaḥpacet tailaṃ sakāñjikaṃ hanti pānābhyañjananāvanaiḥ"},{"type":"verse","number":"49","sanskrit":"आमवातं कृमीन्गुल्मान्प्लीहोदरशिरोरुजः मन्दाग्निं पक्षसन्ध्यण्डवातस्तम्भगदानपि","text":"āmavātaṃ kṛmīngulmānplīhodaraśirorujaḥ mandāgniṃ pakṣasandhyaṇḍavātastambhagadānapi"},{"type":"verse","number":"50","sanskrit":"द्वे पले सैन्धवात्पञ्च शुण्ठ्या ग्रन्थिकचित्रकात् द्वे द्वे भल्लातकास्थीनि विंशतिर्द्वे तथाऽढके","text":"dve pale saindhavātpañca śuṇṭhyā granthikacitrakāt dve dve bhallātakāsthīni viṃśatirdve tathā'ḍhake"},{"type":"verse","number":"51","sanskrit":"आरनालात् पञ्च प्रस्थं तैलस्यैरण्डजस्य च गृध्रस्यूरुग्रहास्यार्त्तिसर्ववातविकारनुत्","text":"āranālāt pañca prasthaṃ tailasyairaṇḍajasya ca gṛdhrasyūrugrahāsyārttisarvavātavikāranut"},{"type":"verse","number":"52","sanskrit":"इति पञ्चविंश ऊरुस्तम्भाधिकारः समाप्तः २५","text":"iti pañcaviṃśa ūrustambhādhikāraḥ samāptaḥ 25"}]},{"sthana":"Уттаракханда","number":26,"lang":"sa","content":[{"type":"heading","heading":"Амавата — ревматизм"},{"type":"verse","number":"1","sanskrit":"विरुद्धाहारचेष्टस्य मन्दाग्नेर्निश्चलस्यच स्निग्धं भुक्तवतो ह्यन्नं व्यायामं कुर्वतस्तथा","text":"viruddhāhāraceṣṭasya mandāgnerniścalasyaca snigdhaṃ bhuktavato hyannaṃ vyāyāmaṃ kurvatastathā"},{"type":"verse","number":"2","sanskrit":"वायुना प्रेरितो ह्यामः श्लेष्मस्थानं प्रधावति तेनात्यर्थमपक्वोऽसौ धमनीभिः प्रपद्यते","text":"vāyunā prerito hyāmaḥ śleṣmasthānaṃ pradhāvati tenātyarthamapakvo'sau dhamanībhiḥ prapadyate"},{"type":"verse","number":"3","sanskrit":"वातपिक्तकफैर्भूयो दूषितः सोऽन्नजो रसः स्रोतांस्यभिष्यन्दयति नानावर्णोऽतिपिच्छिलः","text":"vātapiktakaphairbhūyo dūṣitaḥ so'nnajo rasaḥ srotāṃsyabhiṣyandayati nānāvarṇo'tipicchilaḥ"},{"type":"verse","number":"4","sanskrit":"जनयत्यग्निदौर्बल्यं हृदयस्य च गौरवम् व्याधीनामाश्रयो ह्येष आमसञ्ज्ञोऽतिरुदारुणः","text":"janayatyagnidaurbalyaṃ hṛdayasya ca gauravam vyādhīnāmāśrayo hyeṣa āmasañjño'tirudāruṇaḥ"},{"type":"verse","number":"5","sanskrit":"अजीर्णाद्योरसो जातः सञ्चितो हि क्रमेण वै आमसञ्ज्ञां स लभते शिरोगात्ररुजाकरः","text":"ajīrṇādyoraso jātaḥ sañcito hi krameṇa vai āmasañjñāṃ sa labhate śirogātrarujākaraḥ"},{"type":"verse","number":"6","sanskrit":"युगपत्कुपितावेतौ त्रिकसन्धिप्रवेशकौ स्तब्धञ्च कुरुतो गात्रमामवातः स उच्यते","text":"yugapatkupitāvetau trikasandhipraveśakau stabdhañca kuruto gātramāmavātaḥ sa ucyate"},{"type":"verse","number":"7","sanskrit":"अङ्गमर्दोऽरुचिस्तृष्णा चालस्यं गौरवं ज्वरः अपाकः शूनताऽङ्गानामामवातस्य लक्षणम्","text":"aṅgamardo'rucistṛṣṇā cālasyaṃ gauravaṃ jvaraḥ apākaḥ śūnatā'ṅgānāmāmavātasya lakṣaṇam"},{"type":"verse","number":"8","sanskrit":"स कष्टः सर्वरोगाणां यदा प्रकुपितो भवेत् हस्तपादशिरोगुल्फत्रिकजानूरुसन्धिषु","text":"sa kaṣṭaḥ sarvarogāṇāṃ yadā prakupito bhavet hastapādaśirogulphatrikajānūrusandhiṣu"},{"type":"verse","number":"9","sanskrit":"करोति सरुजं शोथं यत्र दोषः प्रपद्यते स देशो रुज्यतेऽत्थ व्याविद्ध इव वृश्चिकैः","text":"karoti sarujaṃ śothaṃ yatra doṣaḥ prapadyate sa deśo rujyate'ttha vyāviddha iva vṛścikaiḥ"},{"type":"verse","number":"10","sanskrit":"जनयेत्सोऽग्निदौर्बल्यं प्रसेकारुचिगौरवम् उत्साहहानिं वैरस्यं दाहञ्च बहुमूत्रताम्","text":"janayetso'gnidaurbalyaṃ prasekārucigauravam utsāhahāniṃ vairasyaṃ dāhañca bahumūtratām"},{"type":"verse","number":"11","sanskrit":"कुक्षौ कठिनतां शूलं तथा निद्रा विपर्ययम् तृट्छर्दिभ्रममूर्च्छाश्च हृद्र् गहं विडिवबद्धताम् जाड्यान्त्रकूजनानाहं कष्टांश्चान्यानुपद्र वान्","text":"kukṣau kaṭhinatāṃ śūlaṃ tathā nidrā viparyayam tṛṭchardibhramamūrcchāśca hṛdr gahaṃ viḍivabaddhatām jāḍyāntrakūjanānāhaṃ kaṣṭāṃścānyānupadra vān"},{"type":"verse","number":"12","sanskrit":"पित्तात्सदाहरागञ्च सशूलं पवनात्मकम् स्तिमितं गुरुकण्डूकं कफजुष्टं तमादिशेत्","text":"pittātsadāharāgañca saśūlaṃ pavanātmakam stimitaṃ gurukaṇḍūkaṃ kaphajuṣṭaṃ tamādiśet"},{"type":"verse","number":"13","sanskrit":"एकदोषानुगः साध्यो द्विदोषो याप्य उच्यते सर्वदेहचरैः शोथैः स कष्टं सान्निपातिकः","text":"ekadoṣānugaḥ sādhyo dvidoṣo yāpya ucyate sarvadehacaraiḥ śothaiḥ sa kaṣṭaṃ sānnipātikaḥ"},{"type":"verse","number":"14","sanskrit":"लङ्घनं स्वेदनं तिक्तं दीपनानि कटूनि च विरेचनं स्नेहनञ्च वस्तयश्चाममारुते","text":"laṅghanaṃ svedanaṃ tiktaṃ dīpanāni kaṭūni ca virecanaṃ snehanañca vastayaścāmamārute"},{"type":"verse","number":"15","sanskrit":"रूक्षः स्वेदोविधातव्यो बालुकापुटकैस्तथा उपनाहाश्च कर्त्तव्यास्तेऽपि स्नेहविवर्जिताः","text":"rūkṣaḥ svedovidhātavyo bālukāpuṭakaistathā upanāhāśca karttavyāste'pi snehavivarjitāḥ"},{"type":"verse","number":"16","sanskrit":"आमवाताभिभूताय पीडिताय पिपासया पञ्चकोलेन संसिद्धं पानीयं हितमुच्यते","text":"āmavātābhibhūtāya pīḍitāya pipāsayā pañcakolena saṃsiddhaṃ pānīyaṃ hitamucyate"},{"type":"verse","number":"17","sanskrit":"शुष्कमूलकयूषं वा यूषं वा पाञ्चमौलिकम् रसकं काञ्जिकं वाऽपि शुण्ठीचूर्णविचूर्णितम्","text":"śuṣkamūlakayūṣaṃ vā yūṣaṃ vā pāñcamaulikam rasakaṃ kāñjikaṃ vā'pi śuṇṭhīcūrṇavicūrṇitam"},{"type":"verse","number":"18","sanskrit":"सौवीरं स्विन्नवार्ताकं तथा तिक्तफलानि च वास्तूकशाकं सारिष्टशाकं पौनर्नवं हितम्","text":"sauvīraṃ svinnavārtākaṃ tathā tiktaphalāni ca vāstūkaśākaṃ sāriṣṭaśākaṃ paunarnavaṃ hitam"},{"type":"verse","number":"19","sanskrit":"पटोलं गोक्षुरञ्चैव वरुणं कारवेंल्लकम् यवान्नं कोरदूषान्नं पुराणं शालिषष्टिकम्","text":"paṭolaṃ gokṣurañcaiva varuṇaṃ kāraveṃllakam yavānnaṃ koradūṣānnaṃ purāṇaṃ śāliṣaṣṭikam"},{"type":"verse","number":"20","sanskrit":"लावकानां तथा मांसं हितं तक्रेण संस्कृतम् हितश्च यूषः कौलत्थः कालायश्चणकस्य च","text":"lāvakānāṃ tathā māṃsaṃ hitaṃ takreṇa saṃskṛtam hitaśca yūṣaḥ kaulatthaḥ kālāyaścaṇakasya ca"},{"type":"verse","number":"21","sanskrit":"रुच्यं दद्याद्यथासात्म्यमामवातहितञ्च यत् शतपुष्पा वचा विश्वश्वदंष्ट्रावरुणत्वचः","text":"rucyaṃ dadyādyathāsātmyamāmavātahitañca yat śatapuṣpā vacā viśvaśvadaṃṣṭrāvaruṇatvacaḥ"},{"type":"verse","number":"22","sanskrit":"पुनर्नवासदेवाह्वाशटीमुण्डितिकाः समाः प्रसारणी च तर्कारि फलञ्च मदनस्य च","text":"punarnavāsadevāhvāśaṭīmuṇḍitikāḥ samāḥ prasāraṇī ca tarkāri phalañca madanasya ca"},{"type":"verse","number":"23","sanskrit":"शुक्तकाञ्जिकपिष्टं च कोष्णं च लेपने हितम् अहिंस्रा केबुकान् मूलं शिग्रुर्वल्मीकमृत्तिका","text":"śuktakāñjikapiṣṭaṃ ca koṣṇaṃ ca lepane hitam ahiṃsrā kebukān mūlaṃ śigrurvalmīkamṛttikā"},{"type":"verse","number":"24","sanskrit":"मूत्रपिष्टैश्च कर्त्तव्यमुपनाहः प्रलेपनम्","text":"mūtrapiṣṭaiśca karttavyamupanāhaḥ pralepanam"},{"type":"verse","number":"25","sanskrit":"चित्रकं कटुकापाठाकलिङ्गाति विषाऽमृताः देवदारुवचामुस्त नागरातिविषाऽभयाः पिबेदुष्णाम्बुना नित्यमामवातस्य भेषजम्","text":"citrakaṃ kaṭukāpāṭhākaliṅgāti viṣā'mṛtāḥ devadāruvacāmusta nāgarātiviṣā'bhayāḥ pibeduṣṇāmbunā nityamāmavātasya bheṣajam"},{"type":"verse","number":"26","sanskrit":"शटी शुण्ठ्यभया चोग्रा देवाह्वातिविषाऽमृताः कषायमामवातस्य पाचनं रुक्षभोजनम्","text":"śaṭī śuṇṭhyabhayā cogrā devāhvātiviṣā'mṛtāḥ kaṣāyamāmavātasya pācanaṃ rukṣabhojanam"},{"type":"verse","number":"27","sanskrit":"पुनर्नवा च बृहतीवर्द्धमानफणिज्जकैः कल्पयेत्क्वाथमामे तु मूर्वाशिग्रुद्रुमैर्भिषक्","text":"punarnavā ca bṛhatīvarddhamānaphaṇijjakaiḥ kalpayetkvāthamāme tu mūrvāśigrudrumairbhiṣak"},{"type":"verse","number":"28","sanskrit":"सेचनं चामवातस्य रुबूकपयसाऽपि वा","text":"secanaṃ cāmavātasya rubūkapayasā'pi vā"},{"type":"verse","number":"29","sanskrit":"लिह्यात्पथ्यां सविश्वां वा मूत्रैर्वा गुग्गुलुं पिबेत् विश्वाऽलम्बुषयोः कल्कमद्याद्वा तिलविश्वयोः","text":"lihyātpathyāṃ saviśvāṃ vā mūtrairvā gugguluṃ pibet viśvā'lambuṣayoḥ kalkamadyādvā tilaviśvayoḥ"},{"type":"verse","number":"30","sanskrit":"विश्वापथ्याऽमृताक्वाथं कवोष्णं कौशिकान्वितम् कटीजङ्घोरुपृष्ठानां रुजं पीतं निवर्त्तयेत्","text":"viśvāpathyā'mṛtākvāthaṃ kavoṣṇaṃ kauśikānvitam kaṭījaṅghorupṛṣṭhānāṃ rujaṃ pītaṃ nivarttayet"},{"type":"verse","number":"31","sanskrit":"हिङ्गुं चव्यं विडं शुण्ठी कृष्णाऽजाजी सपुष्करम् भागोत्तरमिदं चूर्णं पीतं वातामजिद्भवेत्","text":"hiṅguṃ cavyaṃ viḍaṃ śuṇṭhī kṛṣṇā'jājī sapuṣkaram bhāgottaramidaṃ cūrṇaṃ pītaṃ vātāmajidbhavet"},{"type":"verse","number":"32","sanskrit":"पिप्पली पिप्पलीमूलं सैन्धवं कृष्णजीरकम् चव्यचित्रकतालीशपत्रकं नागकेशरम्","text":"pippalī pippalīmūlaṃ saindhavaṃ kṛṣṇajīrakam cavyacitrakatālīśapatrakaṃ nāgakeśaram"},{"type":"verse","number":"33","sanskrit":"एषां द्विपलिकान्भागान्पञ्च सौवर्चलस्य च मरिचाजाजिशुण्ठीनामेकैकस्य पलं पलम्","text":"eṣāṃ dvipalikānbhāgānpañca sauvarcalasya ca maricājājiśuṇṭhīnāmekaikasya palaṃ palam"},{"type":"verse","number":"34","sanskrit":"दाडिमात्कुडवञ्चैव द्वे पले चाम्लवेतसात् सर्वमेकत्र सङ्क्षुद्य योजयेत्कुशलो भिषक्","text":"dāḍimātkuḍavañcaiva dve pale cāmlavetasāt sarvamekatra saṅkṣudya yojayetkuśalo bhiṣak"},{"type":"verse","number":"35","sanskrit":"पिप्पल्याद्यमिति ख्यातं नष्टस्याग्नेश्च दीपनम् अर्शांसि ग्रहणीं गुल्ममुदरं सभगन्दरम्","text":"pippalyādyamiti khyātaṃ naṣṭasyāgneśca dīpanam arśāṃsi grahaṇīṃ gulmamudaraṃ sabhagandaram"},{"type":"verse","number":"36","sanskrit":"कृमिकण्ड्वरुचीर्हन्यात्सुरयोष्णोदकेन वा नातः परतरं किञ्चिदामवातस्य भेषजम्","text":"kṛmikaṇḍvarucīrhanyātsurayoṣṇodakena vā nātaḥ parataraṃ kiñcidāmavātasya bheṣajam"},{"type":"verse","number":"37","sanskrit":"पथ्याविश्वयवानीभिस्तुल्याभिश्चूर्णितं पिबेत् तक्रेणोष्णोदकेनापि काञ्जिकेनाथ वा पुनः","text":"pathyāviśvayavānībhistulyābhiścūrṇitaṃ pibet takreṇoṣṇodakenāpi kāñjikenātha vā punaḥ"},{"type":"verse","number":"38","sanskrit":"आमवातं निहन्त्याशु शोथं मन्दाग्नितामपि पीनसं कासहृद्रो गं स्वरभेदमरोचकम्","text":"āmavātaṃ nihantyāśu śothaṃ mandāgnitāmapi pīnasaṃ kāsahṛdro gaṃ svarabhedamarocakam"},{"type":"verse","number":"39","sanskrit":"रसोनविश्वनिर्गुण्डीक्वाथमामार्दितः पिबेत्","text":"rasonaviśvanirguṇḍīkvāthamāmārditaḥ pibet"},{"type":"verse","number":"40","sanskrit":"रास्नां गुडूचीमेरण्डं देवदारु महौषधम् पिबेत्सार्वाङ्गिकेवाते सामे सन्ध्यस्थिमज्जगे","text":"rāsnāṃ guḍūcīmeraṇḍaṃ devadāru mahauṣadham pibetsārvāṅgikevāte sāme sandhyasthimajjage"},{"type":"verse","number":"41","sanskrit":"पिप्पलीपिप्पलीमूलचव्यचित्रकनागरैः क्वथितं वारि तत्पेयमामवातविनाशनम्","text":"pippalīpippalīmūlacavyacitrakanāgaraiḥ kvathitaṃ vāri tatpeyamāmavātavināśanam"},{"type":"verse","number":"42","sanskrit":"शटीविश्वौषधीकल्कं वर्षाभूक्वाथसंयुतम् सप्तरात्रं पिबेज्जन्तुरामवातविनाशनम्","text":"śaṭīviśvauṣadhīkalkaṃ varṣābhūkvāthasaṃyutam saptarātraṃ pibejjanturāmavātavināśanam"},{"type":"verse","number":"43","sanskrit":"रास्नाऽमृतारग्वधदेवदारुत्रिकण्टकैरण्डपुनर्नवानाम् क्वाथं पिबेन्नागरचूर्णमिश्रं जङ्घोरुपार्श्वत्रिकपृष्ठशूली","text":"rāsnā'mṛtāragvadhadevadārutrikaṇṭakairaṇḍapunarnavānām kvāthaṃ pibennāgaracūrṇamiśraṃ jaṅghorupārśvatrikapṛṣṭhaśūlī"},{"type":"verse","number":"44","sanskrit":"आमवाते कणायुक्तं दशमूलीजलं पिबेत् खादेद्वाऽप्यभयाविश्वं गुडूचीं नागरेण वा","text":"āmavāte kaṇāyuktaṃ daśamūlījalaṃ pibet khādedvā'pyabhayāviśvaṃ guḍūcīṃ nāgareṇa vā"},{"type":"verse","number":"45","sanskrit":"चित्रकेन्द्र यवौ पाठा कटुकाऽतिविषाऽभयाः आमाशयोत्थवातघ्नं चूर्णं पेयं सुखाम्बुना","text":"citrakendra yavau pāṭhā kaṭukā'tiviṣā'bhayāḥ āmāśayotthavātaghnaṃ cūrṇaṃ peyaṃ sukhāmbunā"},{"type":"verse","number":"46","sanskrit":"पुनर्नवाऽमृता शुण्ठी शताह्वा वृद्धदारुकम् शटी मुण्डितिका चूर्णमारनालेनपाययेत्","text":"punarnavā'mṛtā śuṇṭhī śatāhvā vṛddhadārukam śaṭī muṇḍitikā cūrṇamāranālenapāyayet"},{"type":"verse","number":"47","sanskrit":"आमाशयोत्थवातघ्नं चूर्णं पेयं सुखाम्बुना आमवातं निहन्त्याशु गृध्रसीमुद्धतामपि","text":"āmāśayotthavātaghnaṃ cūrṇaṃ peyaṃ sukhāmbunā āmavātaṃ nihantyāśu gṛdhrasīmuddhatāmapi"},{"type":"verse","number":"48","sanskrit":"कर्षं नागरचूर्णस्य काञ्जिकेन पिबेत्सदा आमवातप्रशमनं कफवातहरं परम्","text":"karṣaṃ nāgaracūrṇasya kāñjikena pibetsadā āmavātapraśamanaṃ kaphavātaharaṃ param"},{"type":"verse","number":"49","sanskrit":"पञ्चकोलकचूर्णन्तु पिबेदुष्णेन वारिणा मन्दाग्निशूलगुल्मामकफारोचकनाशनम्","text":"pañcakolakacūrṇantu pibeduṣṇena vāriṇā mandāgniśūlagulmāmakaphārocakanāśanam"},{"type":"verse","number":"50","sanskrit":"आमवातगजेन्द्र स्य शरीरवनचारिणः एक एव निहन्त्याशु एरण्डतैलकेशरी","text":"āmavātagajendra sya śarīravanacāriṇaḥ eka eva nihantyāśu eraṇḍatailakeśarī"},{"type":"verse","number":"51","sanskrit":"एरण्डतैलयुक्ता हरीतकी भक्षयेन्नरोविधिवत् आमानिलार्त्तियुक्तोगृध्रसीवृद्ध्यर्दितो नियतम्","text":"eraṇḍatailayuktā harītakī bhakṣayennarovidhivat āmānilārttiyuktogṛdhrasīvṛddhyardito niyatam"},{"type":"verse","number":"52","sanskrit":"आरग्वधस्य पत्राणि भृष्टानि कटुतैलतः आमघ्नानि नरः कुर्यात्सायं भक्तावृतानि च","text":"āragvadhasya patrāṇi bhṛṣṭāni kaṭutailataḥ āmaghnāni naraḥ kuryātsāyaṃ bhaktāvṛtāni ca"},{"type":"verse","number":"53","sanskrit":"वायुः कट्याश्रितः शुद्धः सामो वा जनयेद्रुजम् कटीग्रहः स एवोक्तः पङ्गुः सक्थ्नोर्द्वयोर्वधात्","text":"vāyuḥ kaṭyāśritaḥ śuddhaḥ sāmo vā janayedrujam kaṭīgrahaḥ sa evoktaḥ paṅguḥ sakthnordvayorvadhāt"},{"type":"verse","number":"54","sanskrit":"शुण्ठीगोक्षुरकक्वाथः प्रातः प्रातर्निषेवितः सामे वाते कटीशूले पाचनं रुक्प्रणाशन्","text":"śuṇṭhīgokṣurakakvāthaḥ prātaḥ prātarniṣevitaḥ sāme vāte kaṭīśūle pācanaṃ rukpraṇāśan"},{"type":"verse","number":"55","sanskrit":"यवक्षारसमायुक्तं मूत्रकृच्छ्रविनाशनम् दशमूलीकषायेण पिबेद्वा नागराम्भसा कटीशूलेषु पातव्यं तैलमेरण्डसम्भवम्","text":"yavakṣārasamāyuktaṃ mūtrakṛcchravināśanam daśamūlīkaṣāyeṇa pibedvā nāgarāmbhasā kaṭīśūleṣu pātavyaṃ tailameraṇḍasambhavam"},{"type":"verse","number":"56","sanskrit":"महौषधगुडूच्योश्च क्वाथं पिप्पलिसंयुतम् पिबेदामे सरुक्कोष्ठे कटीशूले विशेषतः","text":"mahauṣadhaguḍūcyośca kvāthaṃ pippalisaṃyutam pibedāme sarukkoṣṭhe kaṭīśūle viśeṣataḥ"},{"type":"verse","number":"57","sanskrit":"विशोध्यैरण्डबीजानि पिष्ट्वा क्षीरे विपाचयेत् तत्पायसं कटीशूले गृध्रस्यां परमौषधम्","text":"viśodhyairaṇḍabījāni piṣṭvā kṣīre vipācayet tatpāyasaṃ kaṭīśūle gṛdhrasyāṃ paramauṣadham"},{"type":"verse","number":"58","sanskrit":"सर्पिस्तैलं गुडं शुक्तं पञ्चमं विश्वभेषजम्","text":"sarpistailaṃ guḍaṃ śuktaṃ pañcamaṃ viśvabheṣajam"},{"type":"verse","number":"59","sanskrit":"पीतमेतद्भवेत्सद्यस्तर्पणं कटिशूलनुत् न हि चैतत्समं किञ्चिन्निरामे कटिमारुते","text":"pītametadbhavetsadyastarpaṇaṃ kaṭiśūlanut na hi caitatsamaṃ kiñcinnirāme kaṭimārute"},{"type":"verse","number":"60","sanskrit":"सुरतरुवल्कलसहितं गोमूत्रं स्थापितन्तु सप्ताहम् हिङ्गुवचाशत पुष्पासैन्धवयुक्तेन तेनाथ","text":"surataruvalkalasahitaṃ gomūtraṃ sthāpitantu saptāham hiṅguvacāśata puṣpāsaindhavayuktena tenātha"},{"type":"verse","number":"61","sanskrit":"तत्पुटपक्वं हन्यात्कटीरुजं दारुणं पुंसाम् आममेदोवृद्धिभवान्विकारांश्चानिलोद्भवान्","text":"tatpuṭapakvaṃ hanyātkaṭīrujaṃ dāruṇaṃ puṃsām āmamedovṛddhibhavānvikārāṃścānilodbhavān"},{"type":"verse","number":"62","sanskrit":"अमृतानागरगोक्षुरमुण्डितिकावरुणकैः कृतं चूर्णम् मस्त्वारनालपीतं सामानिलनाशनं ख्यातम्","text":"amṛtānāgaragokṣuramuṇḍitikāvaruṇakaiḥ kṛtaṃ cūrṇam mastvāranālapītaṃ sāmānilanāśanaṃ khyātam"},{"type":"verse","number":"63","sanskrit":"अलम्बुषा गोक्षुरकं त्रिफलानागरामृताः यथोत्तरं भागवृद्ध्या श्यामाचूर्णञ्च तत्समम्","text":"alambuṣā gokṣurakaṃ triphalānāgarāmṛtāḥ yathottaraṃ bhāgavṛddhyā śyāmācūrṇañca tatsamam"},{"type":"verse","number":"64","sanskrit":"पिबेन्मस्तुसुरातक्रकाञ्जिकोष्णोदकेन वा आमवातं जयत्याशु सशोथं वातशोणितम्","text":"pibenmastusurātakrakāñjikoṣṇodakena vā āmavātaṃ jayatyāśu saśothaṃ vātaśoṇitam"},{"type":"verse","number":"65","sanskrit":"त्रिकजानूरुसन्धिस्थं ज्वरारोचकनाशनम् अलम्बुषाऽदिकं चूर्णं रोगानीकविनाशनम्","text":"trikajānūrusandhisthaṃ jvarārocakanāśanam alambuṣā'dikaṃ cūrṇaṃ rogānīkavināśanam"},{"type":"verse","number":"66","sanskrit":"हरीतक्यक्षधात्रीभिः प्रसिद्धा त्रिफला क्रमात् प्रत्येकं तेन वा युञ्ज्याद्भागवृद्धिं यथोत्तरम्","text":"harītakyakṣadhātrībhiḥ prasiddhā triphalā kramāt pratyekaṃ tena vā yuñjyādbhāgavṛddhiṃ yathottaram"},{"type":"verse","number":"67","sanskrit":"अलम्बुषा गोक्षुरकं मूलं वरुणकस्य च गुडूची नागरञ्चेति समभागानि कारयेत्","text":"alambuṣā gokṣurakaṃ mūlaṃ varuṇakasya ca guḍūcī nāgarañceti samabhāgāni kārayet"},{"type":"verse","number":"68","sanskrit":"काञ्जिकेन तु तत्पेयं विडालपदमात्रकम् आमवाते प्रवृद्धे च योगोऽयममृतोपमः","text":"kāñjikena tu tatpeyaṃ viḍālapadamātrakam āmavāte pravṛddhe ca yogo'yamamṛtopamaḥ"},{"type":"verse","number":"69","sanskrit":"अलम्बुषा गोक्षुरकं गुडूची वृद्धदारुकम् पिप्पली त्रिवृता मुस्ता वरुणं सपुनर्नवम् त्रिफला नागरञ्चेति सूक्ष्मचूर्णानि कारयेत्","text":"alambuṣā gokṣurakaṃ guḍūcī vṛddhadārukam pippalī trivṛtā mustā varuṇaṃ sapunarnavam triphalā nāgarañceti sūkṣmacūrṇāni kārayet"},{"type":"verse","number":"70","sanskrit":"मस्त्वारनालतक्रेण पयोमांसरसेन वा आमवातं निहन्त्याशु श्वयथुं सन्धिसंस्थितम्","text":"mastvāranālatakreṇa payomāṃsarasena vā āmavātaṃ nihantyāśu śvayathuṃ sandhisaṃsthitam"},{"type":"verse","number":"71","sanskrit":"मणिमन्थस्य भागौ द्वौ यवान्यास्तद्वदेव तु भागास्त्रयोऽजमोदाया नागराद्भागपञ्चकम्","text":"maṇimanthasya bhāgau dvau yavānyāstadvadeva tu bhāgāstrayo'jamodāyā nāgarādbhāgapañcakam"},{"type":"verse","number":"72","sanskrit":"दश द्वौ च हरीतक्याः सूक्ष्मचूर्णीकृतं शुभम् मस्त्वारनालतक्रेण सर्पिषोष्णोदकेन वा","text":"daśa dvau ca harītakyāḥ sūkṣmacūrṇīkṛtaṃ śubham mastvāranālatakreṇa sarpiṣoṣṇodakena vā"},{"type":"verse","number":"73","sanskrit":"पीतं जयत्यामवातं गुल्महृद्वस्तिजान्गदान् प्लीहानं ग्रन्थिशूलादीनानाहं गुदजानि च","text":"pītaṃ jayatyāmavātaṃ gulmahṛdvastijāngadān plīhānaṃ granthiśūlādīnānāhaṃ gudajāni ca"},{"type":"verse","number":"74","sanskrit":"विबन्धं जाठरान् रोगान्कटीवस्तिसमुत्थितान् वातानुलोमनमिदं चूर्णं वैश्वानरं स्मृतम्","text":"vibandhaṃ jāṭharān rogānkaṭīvastisamutthitān vātānulomanamidaṃ cūrṇaṃ vaiśvānaraṃ smṛtam"},{"type":"verse","number":"75","sanskrit":"असीतकं मागधिका गुडूची श्यामावराहीगजकर्णशुण्ठीः समा धृताः कृत्स्नमिदन्तु चूर्णं पिबेत्तदुष्णोदकमण्डयूषैः","text":"asītakaṃ māgadhikā guḍūcī śyāmāvarāhīgajakarṇaśuṇṭhīḥ samā dhṛtāḥ kṛtsnamidantu cūrṇaṃ pibettaduṣṇodakamaṇḍayūṣaiḥ"},{"type":"verse","number":"76","sanskrit":"तक्रैः रसैर्मद्यसमस्तुभिर्वा यथेष्टचेष्टस्य च भोजनस्य सबाहुकं गृध्रसिखञ्जवातं विश्वाचितूनीप्रतितूनिरोगान्","text":"takraiḥ rasairmadyasamastubhirvā yatheṣṭaceṣṭasya ca bhojanasya sabāhukaṃ gṛdhrasikhañjavātaṃ viśvācitūnīpratitūnirogān"},{"type":"verse","number":"77","sanskrit":"जङ्घाऽमवातार्दितवातरक्तं कटीग्रहं गुल्मगुदामयञ्च सक्रोष्टुकंपाण्डुगरोग्रशोथं हन्यादुरुस्तम्भमुदीर्णवेगम्","text":"jaṅghā'mavātārditavātaraktaṃ kaṭīgrahaṃ gulmagudāmayañca sakroṣṭukaṃpāṇḍugarograśothaṃ hanyādurustambhamudīrṇavegam"},{"type":"verse","number":"78","sanskrit":"शुण्ठीनां षट्पलं पिष्टं धान्यकं द्विपलं तथा चतुर्गुणं जलं दत्वा घृतप्रस्थं विपाचयेत्","text":"śuṇṭhīnāṃ ṣaṭpalaṃ piṣṭaṃ dhānyakaṃ dvipalaṃ tathā caturguṇaṃ jalaṃ datvā ghṛtaprasthaṃ vipācayet"},{"type":"verse","number":"79","sanskrit":"वातश्लेष्मामयान् हन्यादग्निवृद्धिकरं परम् दुर्नामश्वासकासघ्नं बलवर्णाग्निवर्द्धनम्","text":"vātaśleṣmāmayān hanyādagnivṛddhikaraṃ param durnāmaśvāsakāsaghnaṃ balavarṇāgnivarddhanam"},{"type":"verse","number":"80","sanskrit":"सर्पिर्नागरकल्केन सौवीरं तच्चतुर्गुणम् सिद्धमग्निकरं श्रेष्ठमामवातहरं परम्","text":"sarpirnāgarakalkena sauvīraṃ taccaturguṇam siddhamagnikaraṃ śreṣṭhamāmavātaharaṃ param"},{"type":"verse","number":"81","sanskrit":"पुष्ट्यर्थं पयसा साध्यं दध्ना विण्मूत्रसंग्रहे दीपनार्थं मतिमता मस्तुना च प्रकीर्त्तितम्","text":"puṣṭyarthaṃ payasā sādhyaṃ dadhnā viṇmūtrasaṃgrahe dīpanārthaṃ matimatā mastunā ca prakīrttitam"},{"type":"verse","number":"82","sanskrit":"नागरक्वाथकल्काभ्यां घृतप्रस्थं विपाचयेत् चतुर्गुणेन तेनाथ केवलेनजलेन वा","text":"nāgarakvāthakalkābhyāṃ ghṛtaprasthaṃ vipācayet caturguṇena tenātha kevalenajalena vā"},{"type":"verse","number":"83","sanskrit":"वातश्लेष्मप्रशमनमग्निसन्दीपनं परम् नागरं घृतमित्युक्तं कटीशूलामनाशनम्","text":"vātaśleṣmapraśamanamagnisandīpanaṃ param nāgaraṃ ghṛtamityuktaṃ kaṭīśūlāmanāśanam"},{"type":"verse","number":"84","sanskrit":"हिङ्गुं त्रिकटुकं चव्यं मणिमन्थं तथैव च कल्कान्कृत्वा तु पलिकान्घृतप्रस्थं विपाचयेत्","text":"hiṅguṃ trikaṭukaṃ cavyaṃ maṇimanthaṃ tathaiva ca kalkānkṛtvā tu palikānghṛtaprasthaṃ vipācayet"},{"type":"verse","number":"85","sanskrit":"आरनालाढकं दत्वा तत्सर्पिर्जठरापहम् शूलं विबन्धमानाहमामवातं कटीग्रहम्","text":"āranālāḍhakaṃ datvā tatsarpirjaṭharāpaham śūlaṃ vibandhamānāhamāmavātaṃ kaṭīgraham"},{"type":"verse","number":"86","sanskrit":"नाशयेद् ग्रहणीदोषं मन्दाग्नेर्दीपनं परम्","text":"nāśayed grahaṇīdoṣaṃ mandāgnerdīpanaṃ param"},{"type":"verse","number":"87","sanskrit":"शृङ्गबेरयवक्षारपिप्पलीमूलपिप्पलद्यः पिष्ट्वा विपाचयेत्सर्पिरारनालं चतुर्गुणम्","text":"śṛṅgaberayavakṣārapippalīmūlapippaladyaḥ piṣṭvā vipācayetsarpirāranālaṃ caturguṇam"},{"type":"verse","number":"88","sanskrit":"शूलं विबन्धमानाहमामवातं कटिग्रहम् नाशयेद् ग्रहणीदोषमग्निसन्दीपनं परम्","text":"śūlaṃ vibandhamānāhamāmavātaṃ kaṭigraham nāśayed grahaṇīdoṣamagnisandīpanaṃ param"},{"type":"verse","number":"89","sanskrit":"पिबेद् बिन्दुघृतं वापि धान्वन्तरमथापि वा महाशुण्ठीघृतं वापि आमवाते पुनः पुनः","text":"pibed bindughṛtaṃ vāpi dhānvantaramathāpi vā mahāśuṇṭhīghṛtaṃ vāpi āmavāte punaḥ punaḥ"},{"type":"verse","number":"90","sanskrit":"यत्किञ्चिल्लेखनं सर्पिर्दीपनं पाचनञ्च यत् तत्सर्वमामवातेषु योज्यं वा मस्तु षट्पलम्","text":"yatkiñcillekhanaṃ sarpirdīpanaṃ pācanañca yat tatsarvamāmavāteṣu yojyaṃ vā mastu ṣaṭpalam"},{"type":"verse","number":"91","sanskrit":"अजमोदमरिचपिप्पलीविडङ्गसुरदारुचित्रकशताह्वाः सैन्धवपिप्पलीमूलं भागा नवकस्य पलिकाः स्युः","text":"ajamodamaricapippalīviḍaṅgasuradārucitrakaśatāhvāḥ saindhavapippalīmūlaṃ bhāgā navakasya palikāḥ syuḥ"},{"type":"verse","number":"92","sanskrit":"शुण्ठी दशपलिकास्यात्पलानि तावन्ति वृद्धदारस्य पथ्यापलानि पञ्च च सर्वाण्येकत्र कारयेच्चूर्णम्","text":"śuṇṭhī daśapalikāsyātpalāni tāvanti vṛddhadārasya pathyāpalāni pañca ca sarvāṇyekatra kārayeccūrṇam"},{"type":"verse","number":"93","sanskrit":"समगुडवटकानदतश्चूर्णं वाप्युष्णवारिणा पिबतः नश्यन्त्यामानिलजाः सर्वे रोगाः सुकष्टाश्च","text":"samaguḍavaṭakānadataścūrṇaṃ vāpyuṣṇavāriṇā pibataḥ naśyantyāmānilajāḥ sarve rogāḥ sukaṣṭāśca"},{"type":"verse","number":"94","sanskrit":"प्रतितूनी विश्वाची रोगाश्चान्येऽपि गृध्रसी चोग्रा कटिपृष्ठगुदस्फुटिनञ्चैवार्त्तिर्जङ्घयोस्तीव्रा","text":"pratitūnī viśvācī rogāścānye'pi gṛdhrasī cogrā kaṭipṛṣṭhagudasphuṭinañcaivārttirjaṅghayostīvrā"},{"type":"verse","number":"95","sanskrit":"श्वयथुश्च सर्वसन्धिषु ये चान्येऽप्यामवातसम्भूताः सर्वे प्रयान्ति नाशं तम इव सूर्यांशुविध्वस्तम्","text":"śvayathuśca sarvasandhiṣu ye cānye'pyāmavātasambhūtāḥ sarve prayānti nāśaṃ tama iva sūryāṃśuvidhvastam"},{"type":"verse","number":"96","sanskrit":"क्षुद्बोधमरोगित्वं स्थिरयौवनमथ वलीपलितनाशम् कुरुते च तथाभ्यासाद् गुणानथान्यांस्तथा सुबहून्","text":"kṣudbodhamarogitvaṃ sthirayauvanamatha valīpalitanāśam kurute ca tathābhyāsād guṇānathānyāṃstathā subahūn"},{"type":"verse","number":"97","sanskrit":"चित्रकं पिप्पलीमूलं यवानीं कारवीं तथा विडङ्गमजमोदाञ्च जीरके सुरदारु च","text":"citrakaṃ pippalīmūlaṃ yavānīṃ kāravīṃ tathā viḍaṅgamajamodāñca jīrake suradāru ca"},{"type":"verse","number":"98","sanskrit":"चव्यैलासैन्धवं कुष्ठं रास्नागोक्षुरधान्यकम् त्रिफलां मुस्तकं व्योषन्त्वगुशीरं यवाग्रजम्","text":"cavyailāsaindhavaṃ kuṣṭhaṃ rāsnāgokṣuradhānyakam triphalāṃ mustakaṃ vyoṣantvaguśīraṃ yavāgrajam"},{"type":"verse","number":"99","sanskrit":"तालीशपत्रं पत्रञ्च सूक्ष्मचूर्णानि कारयेत् यावन्त्येतानि चूर्णानि तावन्मात्रन्तु गुग्गुलुम्","text":"tālīśapatraṃ patrañca sūkṣmacūrṇāni kārayet yāvantyetāni cūrṇāni tāvanmātrantu guggulum"},{"type":"verse","number":"100","sanskrit":"सम्मर्द्य सर्पिषा गाढं स्निग्धे भाण्डे निधापयेत् अतो मात्रां प्रयुञ्जीत यथेष्टाहारवानपि योगराज इति ख्यातो योगोऽयममृतोपमः","text":"sammardya sarpiṣā gāḍhaṃ snigdhe bhāṇḍe nidhāpayet ato mātrāṃ prayuñjīta yatheṣṭāhāravānapi yogarāja iti khyāto yogo'yamamṛtopamaḥ"},{"type":"verse","number":"101","sanskrit":"अग्निमान्द्यामवातादीन् कृमिदुष्टव्रणानपि प्लीहगुल्मोदरानाहदुर्नामानिविनाशयेत्","text":"agnimāndyāmavātādīn kṛmiduṣṭavraṇānapi plīhagulmodarānāhadurnāmānivināśayet"},{"type":"verse","number":"102","sanskrit":"अग्निञ्च कुरुते दीप्तं तेजोवृद्धिं बलं तथा वातरोगाञ्जयत्येष सन्धिमज्जगतानपि","text":"agniñca kurute dīptaṃ tejovṛddhiṃ balaṃ tathā vātarogāñjayatyeṣa sandhimajjagatānapi"},{"type":"verse","number":"103","sanskrit":"प्रसारण्याढके क्वाथे प्रस्थो गुडरसो मतः पक्वः पञ्चोषणरजोयुक्तः स्यादामवातहा","text":"prasāraṇyāḍhake kvāthe prastho guḍaraso mataḥ pakvaḥ pañcoṣaṇarajoyuktaḥ syādāmavātahā"},{"type":"verse","number":"104","sanskrit":"नागरस्य पलान्यष्टौ घृतस्य पलविंशतिम् क्षीरद्विप्रस्थसंयुक्तं खण्डस्यार्द्धशतं पचेत्","text":"nāgarasya palānyaṣṭau ghṛtasya palaviṃśatim kṣīradviprasthasaṃyuktaṃ khaṇḍasyārddhaśataṃ pacet"},{"type":"verse","number":"105","sanskrit":"व्योषत्रिजातकद्र व्यात्प्रत्येकञ्च पलं पलम् निदध्याच्चूर्णितं तत्र खादेदग्निबलं प्रति","text":"vyoṣatrijātakadra vyātpratyekañca palaṃ palam nidadhyāccūrṇitaṃ tatra khādedagnibalaṃ prati"},{"type":"verse","number":"106","sanskrit":"आमवातप्रशमनं बलपुष्टिविवर्द्धनम्","text":"āmavātapraśamanaṃ balapuṣṭivivarddhanam"},{"type":"verse","number":"107","sanskrit":"बल्यमायुष्यमोजस्यं वलीपलितनाशनम् आमवातप्रशमनं सौभाग्यकरमुत्तमम्","text":"balyamāyuṣyamojasyaṃ valīpalitanāśanam āmavātapraśamanaṃ saubhāgyakaramuttamam"},{"type":"verse","number":"108","sanskrit":"पलं शतं रसोनस्य तिलस्य कुडवं तथा हिङ्गुं त्रिकटुकं क्षारौ द्वौ पञ्च लवणानि च","text":"palaṃ śataṃ rasonasya tilasya kuḍavaṃ tathā hiṅguṃ trikaṭukaṃ kṣārau dvau pañca lavaṇāni ca"},{"type":"verse","number":"109","sanskrit":"शतपुष्पा निशा कुष्ठं पिप्पलीमूलचित्रकौ अजमोदा यवानी च धान्यकञ्चापि बुद्धिमान्","text":"śatapuṣpā niśā kuṣṭhaṃ pippalīmūlacitrakau ajamodā yavānī ca dhānyakañcāpi buddhimān"},{"type":"verse","number":"110","sanskrit":"प्रत्येकञ्च पलञ्चैषां श्लक्ष्णचूर्णानि कारयेत् घृतभाण्डे दृढे चैव स्थापयेद्दिनषोडशम्","text":"pratyekañca palañcaiṣāṃ ślakṣṇacūrṇāni kārayet ghṛtabhāṇḍe dṛḍhe caiva sthāpayeddinaṣoḍaśam"},{"type":"verse","number":"111","sanskrit":"प्रक्षिप्य तैलमानञ्च प्रस्थार्द्धं काञ्जिकस्य च खादेत्कर्षप्रमाणन्तु तोयं मद्यं पिबेदनु","text":"prakṣipya tailamānañca prasthārddhaṃ kāñjikasya ca khādetkarṣapramāṇantu toyaṃ madyaṃ pibedanu"},{"type":"verse","number":"112","sanskrit":"आमवाते रक्तवाते सर्वाङ्गैकाङ्गसंश्रिते अपस्मारेऽनले मन्दे कासे श्वासे गरेषु च सोन्मादे वातभग्ने च शूले जन्तुषु शस्यते","text":"āmavāte raktavāte sarvāṅgaikāṅgasaṃśrite apasmāre'nale mande kāse śvāse gareṣu ca sonmāde vātabhagne ca śūle jantuṣu śasyate"},{"type":"verse","number":"113","sanskrit":"प्रसारण्या रसे सिद्धं तैलमेरण्डजं पिबेत् सर्वदोषहरञ्चैव कफरोगहरं परम्","text":"prasāraṇyā rase siddhaṃ tailameraṇḍajaṃ pibet sarvadoṣaharañcaiva kapharogaharaṃ param"},{"type":"verse","number":"114","sanskrit":"द्विपञ्चमूलीनिर्यासफलदध्यम्लकाञ्जिकैः","text":"dvipañcamūlīniryāsaphaladadhyamlakāñjikaiḥ"},{"type":"verse","number":"115","sanskrit":"तैलं कट्यूरुपार्श्वार्त्तिकफवातामयान्ग्रहान् हन्ति वस्तिप्रदानेन करोत्यग्निबलं महत्","text":"tailaṃ kaṭyūrupārśvārttikaphavātāmayāngrahān hanti vastipradānena karotyagnibalaṃ mahat"},{"type":"verse","number":"116","sanskrit":"सैन्धवं श्रेयसी रास्ना शतपुष्पा यवानिका स्वर्जिका मरिचं कुष्ठं शुण्ठी सौवर्चलं विडम्","text":"saindhavaṃ śreyasī rāsnā śatapuṣpā yavānikā svarjikā maricaṃ kuṣṭhaṃ śuṇṭhī sauvarcalaṃ viḍam"},{"type":"verse","number":"117","sanskrit":"वचाजमोदाजरणाः पौष्करं मधुकं कणा एतान्यर्द्ध पलांशानि सूक्ष्मपिष्टानि कारयेत्","text":"vacājamodājaraṇāḥ pauṣkaraṃ madhukaṃ kaṇā etānyarddha palāṃśāni sūkṣmapiṣṭāni kārayet"},{"type":"verse","number":"118","sanskrit":"प्रस्थमेरण्डतैलस्य प्रस्थाम्बुशतपुष्पजम् काञ्जिकं द्विगुणं दत्वा मस्तु च द्विगुणं तथा","text":"prasthameraṇḍatailasya prasthāmbuśatapuṣpajam kāñjikaṃ dviguṇaṃ datvā mastu ca dviguṇaṃ tathā"},{"type":"verse","number":"119","sanskrit":"एतं सम्भृत्य सम्भारं शनैर्मृद्वग्निना पचेत् सिद्धमेतत् प्रयोक्तव्यमामवातहरं परम्","text":"etaṃ sambhṛtya sambhāraṃ śanairmṛdvagninā pacet siddhametat prayoktavyamāmavātaharaṃ param"},{"type":"verse","number":"120","sanskrit":"पानाभ्यञ्जनवस्तौ च कुरुतेग्निबलं भृशम् वातार्त्तवङ्क्षणे शस्तं कटीजानूरुसन्धिजे","text":"pānābhyañjanavastau ca kurutegnibalaṃ bhṛśam vātārttavaṅkṣaṇe śastaṃ kaṭījānūrusandhije"},{"type":"verse","number":"121","sanskrit":"शूले हृत्पार्श्वजे तद्वद् वृद्धे श्लेष्मणि पीडिते बाह्यायामार्दितानाहैरन्त्रवृद्धिनिपीडिते अन्यांश्चानिलजान् रोगान्नाशयत्याशु देहिनाम्","text":"śūle hṛtpārśvaje tadvad vṛddhe śleṣmaṇi pīḍite bāhyāyāmārditānāhairantravṛddhinipīḍite anyāṃścānilajān rogānnāśayatyāśu dehinām"},{"type":"verse","number":"122","sanskrit":"स्वल्पप्रसारणीतैलं तैलं वा सैन्धवादिकम् दशमूलाद्यतैलेन वस्तिदानं प्रशस्यते","text":"svalpaprasāraṇītailaṃ tailaṃ vā saindhavādikam daśamūlādyatailena vastidānaṃ praśasyate"},{"type":"verse","number":"123","sanskrit":"तैलस्य द्विपलं दद्यात्काञ्जिकस्य चतुष्पलम् दशमूलरसं मूत्रं पृथक्पञ्च पलानि तु","text":"tailasya dvipalaṃ dadyātkāñjikasya catuṣpalam daśamūlarasaṃ mūtraṃ pṛthakpañca palāni tu"},{"type":"verse","number":"124","sanskrit":"वचा मदनवाट्या वा शताह्वाकुष्ठसैन्धवैः पिप्पल्यतिविषामुस्तारास्नाकट्फलपौष्करैः","text":"vacā madanavāṭyā vā śatāhvākuṣṭhasaindhavaiḥ pippalyativiṣāmustārāsnākaṭphalapauṣkaraiḥ"},{"type":"verse","number":"125","sanskrit":"अक्षांशिकैश्च तत्सर्वं मन्थयेत विचक्षणः प्रस्थार्धं प्रथमं देयो वस्तिर्निरभिशङ्कितः","text":"akṣāṃśikaiśca tatsarvaṃ manthayeta vicakṣaṇaḥ prasthārdhaṃ prathamaṃ deyo vastirnirabhiśaṅkitaḥ"},{"type":"verse","number":"126","sanskrit":"द्वितीये च तृतीये च वर्जयेत्प्रसृतद्वयम् सर्ववातविकारेषु मेहेषु वृषणामये","text":"dvitīye ca tṛtīye ca varjayetprasṛtadvayam sarvavātavikāreṣu meheṣu vṛṣaṇāmaye"},{"type":"verse","number":"127","sanskrit":"कुक्षौ हृत्पृष्ठपार्श्वेषु जानुजङ्घाकटीग्रहे विबन्धानाहरोगेषु शर्कराऽश्मरिपीडिते","text":"kukṣau hṛtpṛṣṭhapārśveṣu jānujaṅghākaṭīgrahe vibandhānāharogeṣu śarkarā'śmaripīḍite"},{"type":"verse","number":"128","sanskrit":"भग्नविश्लिष्टगात्रेषु पिच्चितेषु क्षतेषु च एतन्निरुहवत्प्राज्ञो निरायासो महागुणः","text":"bhagnaviśliṣṭagātreṣu picciteṣu kṣateṣu ca etanniruhavatprājño nirāyāso mahāguṇaḥ"},{"type":"verse","number":"129","sanskrit":"दधिमत्स्यगुडक्षीरं पोतकीमाषपिष्टकम् वर्जयेदामवातार्त्तो मांसमानूपसम्भवम्","text":"dadhimatsyaguḍakṣīraṃ potakīmāṣapiṣṭakam varjayedāmavātārtto māṃsamānūpasambhavam"},{"type":"verse","number":"130","sanskrit":"अभिष्यन्दकरा ये च ये चान्ये गुरुपिच्छलाः वर्जनीयाः प्रयत्नेन आमवातार्दितैर्नरैः","text":"abhiṣyandakarā ye ca ye cānye gurupicchalāḥ varjanīyāḥ prayatnena āmavātārditairnaraiḥ"},{"type":"verse","number":"131","sanskrit":"रास्नैरण्डशतावरीसहचरादुःस्पर्शवासामृता देवाह्वातिविषाभयाघनशटीशुण्ठीकषायःकृतः पीतः सोरुवुतैल एष विहितः सामे सशूलेनिलं कट्यूरुत्रिकपृष्ठकोष्ठजठरक्रोडेषु चामार्त्तिजित्","text":"rāsnairaṇḍaśatāvarīsahacarāduḥsparśavāsāmṛtā devāhvātiviṣābhayāghanaśaṭīśuṇṭhīkaṣāyaḥkṛtaḥ pītaḥ soruvutaila eṣa vihitaḥ sāme saśūlenilaṃ kaṭyūrutrikapṛṣṭhakoṣṭhajaṭharakroḍeṣu cāmārttijit"},{"type":"verse","number":"132","sanskrit":"रास्ना वातारिमूलञ्च वासकञ्च दुरालभम् शटीदारुबलामुस्तनागरातिविषाभयाः","text":"rāsnā vātārimūlañca vāsakañca durālabham śaṭīdārubalāmustanāgarātiviṣābhayāḥ"},{"type":"verse","number":"133","sanskrit":"श्वदंष्ट्रा व्याधिघातश्च मिसिधान्यपुनर्नवाः अश्वगन्धामृताकृष्णा वृद्धदारः शतावरी","text":"śvadaṃṣṭrā vyādhighātaśca misidhānyapunarnavāḥ aśvagandhāmṛtākṛṣṇā vṛddhadāraḥ śatāvarī"},{"type":"verse","number":"134","sanskrit":"वचा सहचरश्चैव चविका बृहतीद्वयम् समभागान्वितैरेतै रास्नाद्विगुणभागिकैः","text":"vacā sahacaraścaiva cavikā bṛhatīdvayam samabhāgānvitairetai rāsnādviguṇabhāgikaiḥ"},{"type":"verse","number":"135","sanskrit":"कषायं पाययेत्सिद्धमष्टभागावशेषितम् शुण्ठीचूर्णसमायुक्तमाभाद्येन युतं तथा","text":"kaṣāyaṃ pāyayetsiddhamaṣṭabhāgāvaśeṣitam śuṇṭhīcūrṇasamāyuktamābhādyena yutaṃ tathā"},{"type":"verse","number":"136","sanskrit":"अलम्बुषादिसंयुक्त मजमोदादिसंयुतम् यथादोषं यथाव्याधि प्रक्षेपं कारयेद्भिषक्","text":"alambuṣādisaṃyukta majamodādisaṃyutam yathādoṣaṃ yathāvyādhi prakṣepaṃ kārayedbhiṣak"},{"type":"verse","number":"137","sanskrit":"सर्वेषु वातरोगेषु सन्धिमज्जगतेषु च आनाहेषु च सर्वेषु सर्वगात्रानुकम्पने","text":"sarveṣu vātarogeṣu sandhimajjagateṣu ca ānāheṣu ca sarveṣu sarvagātrānukampane"},{"type":"verse","number":"138","sanskrit":"कुब्जके वामने चैव पक्षाघाते तथार्दिते जानुजङ्घास्थिपीडासु गृध्रस्यां च हनुग्रहे","text":"kubjake vāmane caiva pakṣāghāte tathārdite jānujaṅghāsthipīḍāsu gṛdhrasyāṃ ca hanugrahe"},{"type":"verse","number":"139","sanskrit":"प्रशस्तं वातरक्ते स्यादूरुस्तम्भे तथार्शसि विश्वाचीगुल्महृद्रो गविषूचीक्रोष्टुशीर्षके","text":"praśastaṃ vātarakte syādūrustambhe tathārśasi viśvācīgulmahṛdro gaviṣūcīkroṣṭuśīrṣake"},{"type":"verse","number":"140","sanskrit":"अन्त्रवृद्धौ श्लीपदे च योनिशुक्रामये तथा पुंसां मेढ्रगते रोगे स्त्रीणां वन्ध्यामये तथा","text":"antravṛddhau ślīpade ca yoniśukrāmaye tathā puṃsāṃ meḍhragate roge strīṇāṃ vandhyāmaye tathā"},{"type":"verse","number":"141","sanskrit":"योषितां गर्भदं मुख्यं नास्ति किञ्चिदतः परम् सर्वेषां पाचनानान्तु श्रेष्ठमेतद्धि पाचनम्","text":"yoṣitāṃ garbhadaṃ mukhyaṃ nāsti kiñcidataḥ param sarveṣāṃ pācanānāntu śreṣṭhametaddhi pācanam"},{"type":"verse","number":"142","sanskrit":"महारास्नादिकं नाम प्रजापतिविनिर्मितम्","text":"mahārāsnādikaṃ nāma prajāpativinirmitam"},{"type":"verse","number":"143","sanskrit":"रास्नाविश्वविडङ्गानि रुबूकं त्रिफला तथा दशमूलं पृथक् श्यामा क्वाथो वातामयापहः अर्द्धावभेदके त्वाढ्ये चार्दिते वातखञ्जके","text":"rāsnāviśvaviḍaṅgāni rubūkaṃ triphalā tathā daśamūlaṃ pṛthak śyāmā kvātho vātāmayāpahaḥ arddhāvabhedake tvāḍhye cārdite vātakhañjake"},{"type":"verse","number":"144","sanskrit":"नेत्ररोगे शिरः शूले ज्वरापस्मारयोस्तथा मनोभ्रंशे च विविधे कथितञ्च शुभप्रदम्","text":"netraroge śiraḥ śūle jvarāpasmārayostathā manobhraṃśe ca vividhe kathitañca śubhapradam"},{"type":"verse","number":"145","sanskrit":"इति षड्विंश आमवाताधिकारः समाप्तः २६","text":"iti ṣaḍviṃśa āmavātādhikāraḥ samāptaḥ 26"}]},{"sthana":"Уттаракханда","number":27,"lang":"sa","content":[{"type":"heading","heading":"Питта-вьядхи — болезни Питты"},{"type":"verse","number":"1","sanskrit":"कट्वम्लोष्णविदाहि तीक्ष्णलवणक्रोधोपवासातप स्त्रीसम्भोगतृषा क्षुधाभिहननव्यायाममद्यादिभिः मध्ये चापि हि भोजनस्य जरता भुक्तेन मध्यन्दिने मध्याह्ने रजनी निदाधशरदोः पित्तं करोत्यामयान्","text":"kaṭvamloṣṇavidāhi tīkṣṇalavaṇakrodhopavāsātapa strīsambhogatṛṣā kṣudhābhihananavyāyāmamadyādibhiḥ madhye cāpi hi bhojanasya jaratā bhuktena madhyandine madhyāhne rajanī nidādhaśaradoḥ pittaṃ karotyāmayān"},{"type":"verse","number":"2","sanskrit":"अकालपलितं नेत्ररक्तता मूत्ररक्तता नेत्रास्यपीतता तद्वन्मूत्रस्यापि च पीतता","text":"akālapalitaṃ netraraktatā mūtraraktatā netrāsyapītatā tadvanmūtrasyāpi ca pītatā"},{"type":"verse","number":"3","sanskrit":"मलस्य पीतता प्रोक्ता शाखानामपि पीतता दन्तानाञ्चापि पीतत्वं पीतत्वं वपुषस्तथा","text":"malasya pītatā proktā śākhānāmapi pītatā dantānāñcāpi pītatvaṃ pītatvaṃ vapuṣastathā"},{"type":"verse","number":"4","sanskrit":"तमसो दर्शनञ्चापि परितः पीतदर्शनम् निद्रा ल्पतादि शोषश्च मुखे गन्धश्च लोहवत्","text":"tamaso darśanañcāpi paritaḥ pītadarśanam nidrā lpatādi śoṣaśca mukhe gandhaśca lohavat"},{"type":"verse","number":"5","sanskrit":"मुखस्य तिक्तता चापि तथा च वदनाम्लता उच्छ्वासस्योष्णता चापि धूमोद्गारस्तथैव च","text":"mukhasya tiktatā cāpi tathā ca vadanāmlatā ucchvāsasyoṣṇatā cāpi dhūmodgārastathaiva ca"},{"type":"verse","number":"6","sanskrit":"भ्रमः क्लमस्तथा क्रोधो दाहो भेदसमन्वितः तेजोद्वेषश्च शीतेच्छाद्यतृप्तिररतिस्तथा","text":"bhramaḥ klamastathā krodho dāho bhedasamanvitaḥ tejodveṣaśca śītecchādyatṛptiraratistathā"},{"type":"verse","number":"7","sanskrit":"भक्षितस्य विदाहश्च जठरानलतीक्ष्णता रक्तप्रवृत्तिर्विड्भेदः पुरीषस्योष्णता तथा","text":"bhakṣitasya vidāhaśca jaṭharānalatīkṣṇatā raktapravṛttirviḍbhedaḥ purīṣasyoṣṇatā tathā"},{"type":"verse","number":"8","sanskrit":"मूत्रोष्णता मूत्रकृच्छ्रं मूत्राल्पत्वं तनूष्णता स्वेदस्य चापि दौर्गन्ध्यं देहप्रावरणं तथा","text":"mūtroṣṇatā mūtrakṛcchraṃ mūtrālpatvaṃ tanūṣṇatā svedasya cāpi daurgandhyaṃ dehaprāvaraṇaṃ tathā"},{"type":"verse","number":"9","sanskrit":"शरीरस्यावसादश्च पाकश्च वपुषस्तथा चत्वारिंशदमी पित्तव्याधयो मुनिभिर्मताः","text":"śarīrasyāvasādaśca pākaśca vapuṣastathā catvāriṃśadamī pittavyādhayo munibhirmatāḥ"},{"type":"verse","number":"10","sanskrit":"इति सप्तविंशः पित्तव्याध्यधिकारः समाप्तः २७ अथाष्टाविंशः श्लेष्मव्याध्यधिकारः २८ गुरुमधुररसादि स्निग्धमन्दोदराग्नि द्र वदधिदिननिद्रा शीतनिश्चेष्टितानि प्रथमदिवसभागे भुक्तमात्रे वसन्ते भवति हि कफरोगो रात्रिभागेपि चाद्ये","text":"iti saptaviṃśaḥ pittavyādhyadhikāraḥ samāptaḥ 27 athāṣṭāviṃśaḥ śleṣmavyādhyadhikāraḥ 28 gurumadhurarasādi snigdhamandodarāgni dra vadadhidinanidrā śītaniśceṣṭitāni prathamadivasabhāge bhuktamātre vasante bhavati hi kapharogo rātribhāgepi cādye"},{"type":"verse","number":"11","sanskrit":"प्रथमं मुखमाधुर्यं तथैव मुखलिप्तता मुखप्रसेकश्च तथा निद्रा धिक्यं तथैव च","text":"prathamaṃ mukhamādhuryaṃ tathaiva mukhaliptatā mukhaprasekaśca tathā nidrā dhikyaṃ tathaiva ca"},{"type":"verse","number":"12","sanskrit":"कण्ठे घुर्घुरता चापि कटुकाङ्क्षोष्णकामिता बुद्धिमान्द्यमचैतन्यमालस्यं तृप्तिरेव च","text":"kaṇṭhe ghurghuratā cāpi kaṭukāṅkṣoṣṇakāmitā buddhimāndyamacaitanyamālasyaṃ tṛptireva ca"},{"type":"verse","number":"13","sanskrit":"अग्निमान्द्यं मलाधिक्यं मलशौक्ल्यं तथैव च मूत्राधिक्यं मूत्रशौक्ल्यं शुक्राधिक्यं तथैव च","text":"agnimāndyaṃ malādhikyaṃ malaśauklyaṃ tathaiva ca mūtrādhikyaṃ mūtraśauklyaṃ śukrādhikyaṃ tathaiva ca"},{"type":"verse","number":"14","sanskrit":"स्तैमित्यं गौरवं शैत्यमेत एव हि विंशतिः योगतो रूढितः प्रोक्ता मुनिभिः श्लैष्मिका गदाः","text":"staimityaṃ gauravaṃ śaityameta eva hi viṃśatiḥ yogato rūḍhitaḥ proktā munibhiḥ ślaiṣmikā gadāḥ"},{"type":"verse","number":"15","sanskrit":"रुक्षक्षारकषायतिक्तकटुकव्यायामनिष्ठीवनं धूमोष्मानलघर्मनस्यवमनं स्वेदोपवासादिकम्","text":"rukṣakṣārakaṣāyatiktakaṭukavyāyāmaniṣṭhīvanaṃ dhūmoṣmānalagharmanasyavamanaṃ svedopavāsādikam"},{"type":"verse","number":"16","sanskrit":"तृड्घाताध्वनियुद्धजागरजलक्रीडाङ्गनासेवनम् पानाहारविहारभेषजमिदं श्लेष्मामयान् संहरेत्","text":"tṛḍghātādhvaniyuddhajāgarajalakrīḍāṅganāsevanam pānāhāravihārabheṣajamidaṃ śleṣmāmayān saṃharet"},{"type":"verse","number":"17","sanskrit":"इत्यष्टाविंशः श्लेष्मव्याध्यधिकारः समाप्तः २८","text":"ityaṣṭāviṃśaḥ śleṣmavyādhyadhikāraḥ samāptaḥ 28"}]},{"sthana":"Уттаракханда","number":28,"lang":"sa","content":[{"type":"heading","heading":"Шлешма-вьядхи — болезни Капхи"},{"type":"verse","number":"1","sanskrit":"गुरुमधुररसादि स्निग्धमन्दोदराग्नि द्र वदधिदिननिद्रा शीतनिश्चेष्टितानि प्रथमदिवसभागे भुक्तमात्रे वसन्ते भवति हि कफरोगो रात्रिभागेपि चाद्ये","text":"gurumadhurarasādi snigdhamandodarāgni dra vadadhidinanidrā śītaniśceṣṭitāni prathamadivasabhāge bhuktamātre vasante bhavati hi kapharogo rātribhāgepi cādye"},{"type":"verse","number":"2","sanskrit":"प्रथमं मुखमाधुर्यं तथैव मुखलिप्तता मुखप्रसेकश्च तथा निद्रा धिक्यं तथैव च","text":"prathamaṃ mukhamādhuryaṃ tathaiva mukhaliptatā mukhaprasekaśca tathā nidrā dhikyaṃ tathaiva ca"},{"type":"verse","number":"3","sanskrit":"कण्ठे घुर्घुरता चापि कटुकाङ्क्षोष्णकामिता बुद्धिमान्द्यमचैतन्यमालस्यं तृप्तिरेव च","text":"kaṇṭhe ghurghuratā cāpi kaṭukāṅkṣoṣṇakāmitā buddhimāndyamacaitanyamālasyaṃ tṛptireva ca"},{"type":"verse","number":"4","sanskrit":"अग्निमान्द्यं मलाधिक्यं मलशौक्ल्यं तथैव च मूत्राधिक्यं मूत्रशौक्ल्यं शुक्राधिक्यं तथैव च","text":"agnimāndyaṃ malādhikyaṃ malaśauklyaṃ tathaiva ca mūtrādhikyaṃ mūtraśauklyaṃ śukrādhikyaṃ tathaiva ca"},{"type":"verse","number":"5","sanskrit":"स्तैमित्यं गौरवं शैत्यमेत एव हि विंशतिः योगतो रूढितः प्रोक्ता मुनिभिः श्लैष्मिका गदाः","text":"staimityaṃ gauravaṃ śaityameta eva hi viṃśatiḥ yogato rūḍhitaḥ proktā munibhiḥ ślaiṣmikā gadāḥ"},{"type":"verse","number":"6","sanskrit":"रुक्षक्षारकषायतिक्तकटुकव्यायामनिष्ठीवनं धूमोष्मानलघर्मनस्यवमनं स्वेदोपवासादिकम्","text":"rukṣakṣārakaṣāyatiktakaṭukavyāyāmaniṣṭhīvanaṃ dhūmoṣmānalagharmanasyavamanaṃ svedopavāsādikam"},{"type":"verse","number":"7","sanskrit":"तृड्घाताध्वनियुद्धजागरजलक्रीडाङ्गनासेवनम् पानाहारविहारभेषजमिदं श्लेष्मामयान् संहरेत्","text":"tṛḍghātādhvaniyuddhajāgarajalakrīḍāṅganāsevanam pānāhāravihārabheṣajamidaṃ śleṣmāmayān saṃharet"},{"type":"verse","number":"8","sanskrit":"इत्यष्टाविंशः श्लेष्मव्याध्यधिकारः समाप्तः २८","text":"ityaṣṭāviṃśaḥ śleṣmavyādhyadhikāraḥ samāptaḥ 28"}]},{"sthana":"Уттаракханда","number":29,"lang":"sa","content":[{"type":"heading","heading":"Ватаракта — подагра"},{"type":"verse","number":"1","sanskrit":"लवणाम्लकटुक्षारस्निग्धोष्णाजीर्णभोजनैः क्लिन्नशुष्काम्बुजानूपमांसपिण्याकमूलकैः","text":"lavaṇāmlakaṭukṣārasnigdhoṣṇājīrṇabhojanaiḥ klinnaśuṣkāmbujānūpamāṃsapiṇyākamūlakaiḥ"},{"type":"verse","number":"2","sanskrit":"कुलत्थमाषनिष्पावशाकादिपललेक्षुभिः दध्यारनालसौवीरशुक्ततक्रसुरासवैः","text":"kulatthamāṣaniṣpāvaśākādipalalekṣubhiḥ dadhyāranālasauvīraśuktatakrasurāsavaiḥ"},{"type":"verse","number":"3","sanskrit":"विरुद्धाध्यशनक्रोधदिवास्वप्नातिजागरैः प्रायशः सुकुमाराणां मिथ्याहारविहारिणाम् स्थूलानां सुखिनाञ्चापि प्रकुप्येद्वातशोणितम्","text":"viruddhādhyaśanakrodhadivāsvapnātijāgaraiḥ prāyaśaḥ sukumārāṇāṃ mithyāhāravihāriṇām sthūlānāṃ sukhināñcāpi prakupyedvātaśoṇitam"},{"type":"verse","number":"4","sanskrit":"हस्त्यश्वोष्ट्रैर्गच्छतश्चाश्नतश्च विदाह्यन्नं सविदाहाशनस्य","text":"hastyaśvoṣṭrairgacchataścāśnataśca vidāhyannaṃ savidāhāśanasya"},{"type":"verse","number":"5","sanskrit":"कृत्स्नं रक्तं विदहत्याशु तच्च दुष्टं शीघ्रं पादयोश्चीयते तु तत्सम्पृक्तं वायुना दूषितेन तत्प्राबल्यादुच्यते वातरक्तम्","text":"kṛtsnaṃ raktaṃ vidahatyāśu tacca duṣṭaṃ śīghraṃ pādayoścīyate tu tatsampṛktaṃ vāyunā dūṣitena tatprābalyāducyate vātaraktam"},{"type":"verse","number":"6","sanskrit":"स्वेदोत्यर्थं न वा कार्ष्ण्यं स्पर्शाज्ञत्वं क्षतेतिरुक् सन्धिशैथिल्यमालस्यं सदनं पिडिकोद्गमः","text":"svedotyarthaṃ na vā kārṣṇyaṃ sparśājñatvaṃ kṣatetiruk sandhiśaithilyamālasyaṃ sadanaṃ piḍikodgamaḥ"},{"type":"verse","number":"7","sanskrit":"जानुजङ्घोरुकट्यंसहस्तपादाङ्गसन्धिषु निस्तोदः स्फुरणं भेदो गुरुत्वं सुप्तिरेव च","text":"jānujaṅghorukaṭyaṃsahastapādāṅgasandhiṣu nistodaḥ sphuraṇaṃ bhedo gurutvaṃ suptireva ca"},{"type":"verse","number":"8","sanskrit":"कण्डूः सन्धिषु रुग्दाहो भूत्वा नश्यति चासकृत् वैवर्ण्यं मण्डलोत्पत्तिर्वातासृक्पूर्वलक्षणम्","text":"kaṇḍūḥ sandhiṣu rugdāho bhūtvā naśyati cāsakṛt vaivarṇyaṃ maṇḍalotpattirvātāsṛkpūrvalakṣaṇam"},{"type":"verse","number":"9","sanskrit":"वातेऽधिकेऽधिकं तत्र शूलं स्फुरणतोदनम् शोथस्य रौक्ष्यं कृष्णत्वं श्यावता वृद्धिहानयः","text":"vāte'dhike'dhikaṃ tatra śūlaṃ sphuraṇatodanam śothasya raukṣyaṃ kṛṣṇatvaṃ śyāvatā vṛddhihānayaḥ"},{"type":"verse","number":"10","sanskrit":"धमन्यङ्गुलिसन्धीनां सङ्कोचोऽङ्गग्रहोऽतिरुक् शीतद्वेषानुपशयौ स्तम्भवेपथुसुप्तयः","text":"dhamanyaṅgulisandhīnāṃ saṅkoco'ṅgagraho'tiruk śītadveṣānupaśayau stambhavepathusuptayaḥ"},{"type":"verse","number":"11","sanskrit":"रक्ते शोथोऽतिरुक्तोदस्ताम्रश्चिमिचिमायते स्निग्धरुक्षैः शमं नैति कण्डूक्लेदसमन्वितः","text":"rakte śotho'tiruktodastāmraścimicimāyate snigdharukṣaiḥ śamaṃ naiti kaṇḍūkledasamanvitaḥ"},{"type":"verse","number":"12","sanskrit":"पित्ते विदाहः संमोहः स्वेदो मूर्च्छा मदस्तृषा स्पर्शासहत्वं रुग्दाहः शोथः पाको भृशोष्णता","text":"pitte vidāhaḥ saṃmohaḥ svedo mūrcchā madastṛṣā sparśāsahatvaṃ rugdāhaḥ śothaḥ pāko bhṛśoṣṇatā"},{"type":"verse","number":"13","sanskrit":"कफे स्तैमित्यगुरुता सुप्तिः स्निग्धत्वशीतता कण्डूर्मन्दा च रुग्द्वन्द्वसर्वलिङ्गञ्च सङ्करे","text":"kaphe staimityagurutā suptiḥ snigdhatvaśītatā kaṇḍūrmandā ca rugdvandvasarvaliṅgañca saṅkare"},{"type":"verse","number":"14","sanskrit":"पादयोर्मूलमास्थाय कदाचिद्धस्तयोरपि आखोर्विषमिव क्रुद्धं तद्देहमनुसर्पति","text":"pādayormūlamāsthāya kadāciddhastayorapi ākhorviṣamiva kruddhaṃ taddehamanusarpati"},{"type":"verse","number":"15","sanskrit":"अस्वप्नारोचकश्वासमांसकोथशिरोग्रहाः मूर्च्छा चामन्दरुक्तृष्णाज्वरमोहप्रवेपकाः","text":"asvapnārocakaśvāsamāṃsakothaśirograhāḥ mūrcchā cāmandaruktṛṣṇājvaramohapravepakāḥ"},{"type":"verse","number":"16","sanskrit":"हिक्कापाङ्गुल्यवीसर्पपाकतोदभ्रमक्लमाः अङ्गुलीवक्रतास्फोटदाहमर्मग्रहार्बुदाः","text":"hikkāpāṅgulyavīsarpapākatodabhramaklamāḥ aṅgulīvakratāsphoṭadāhamarmagrahārbudāḥ"},{"type":"verse","number":"17","sanskrit":"एतैरुपद्र वैर्वर्ज्यं मोहेनैकेन चापि तत् अकृत्स्नोपद्र वं याप्यं साध्यं स्यान्निरुपद्र वम्","text":"etairupadra vairvarjyaṃ mohenaikena cāpi tat akṛtsnopadra vaṃ yāpyaṃ sādhyaṃ syānnirupadra vam"},{"type":"verse","number":"18","sanskrit":"एकदोषानुगं साध्यं नवं याप्यं द्विदोषजम् त्रिदोषजमसाध्यं स्याद्यस्य च स्युरुपद्र वाः","text":"ekadoṣānugaṃ sādhyaṃ navaṃ yāpyaṃ dvidoṣajam tridoṣajamasādhyaṃ syādyasya ca syurupadra vāḥ"},{"type":"verse","number":"19","sanskrit":"आजानु स्फुटितं यच्च प्रभिन्नं प्रस्रुतञ्च यत् उपद्र वैश्च यज्जुष्टं प्राणमांसक्षयादिभिः वातरक्तमसाध्यं स्याद्याप्यं संवत्सरोत्थितम्","text":"ājānu sphuṭitaṃ yacca prabhinnaṃ prasrutañca yat upadra vaiśca yajjuṣṭaṃ prāṇamāṃsakṣayādibhiḥ vātaraktamasādhyaṃ syādyāpyaṃ saṃvatsarotthitam"},{"type":"verse","number":"20","sanskrit":"वातशोणितिनो रक्तं स्निग्धस्य बहुशो हरेत् अल्पाल्पं रक्षयेद्वायुं यथादोषं यथाबलम्","text":"vātaśoṇitino raktaṃ snigdhasya bahuśo haret alpālpaṃ rakṣayedvāyuṃ yathādoṣaṃ yathābalam"},{"type":"verse","number":"21","sanskrit":"उग्राङ्गदाहतोदेषु जलौकोभिर्विनिर्हरेत्","text":"ugrāṅgadāhatodeṣu jalaukobhirvinirharet"},{"type":"verse","number":"22","sanskrit":"शृङ्गेण वै चिमिचिमाकण्डूरुग्वेपनान्वितम् प्रच्छन्नेन शिराभिर्वा देशाद्देशान्तरं व्रजेत्","text":"śṛṅgeṇa vai cimicimākaṇḍūrugvepanānvitam pracchannena śirābhirvā deśāddeśāntaraṃ vrajet"},{"type":"verse","number":"23","sanskrit":"अङ्गेम्लाने तु न स्राव्यं रक्षेद्वातोत्तरञ्च यत् गम्भीरं श्वयथुं स्तम्भं कम्पवायुं शिराऽमयान् ग्लानिमन्यांश्च वातोत्थान्कुर्याद्वायुरसृक्क्षयात्","text":"aṅgemlāne tu na srāvyaṃ rakṣedvātottarañca yat gambhīraṃ śvayathuṃ stambhaṃ kampavāyuṃ śirā'mayān glānimanyāṃśca vātotthānkuryādvāyurasṛkkṣayāt"},{"type":"verse","number":"24","sanskrit":"खञ्जादीन् वातरोगांश्च मृत्युञ्चानवशेषितम् कुर्यात्तस्मात्प्रमाणेन स्निग्धाद्र क्तं विनिर्हरेत्","text":"khañjādīn vātarogāṃśca mṛtyuñcānavaśeṣitam kuryāttasmātpramāṇena snigdhādra ktaṃ vinirharet"},{"type":"verse","number":"25","sanskrit":"रुक्षैर्वा मृदुभिः शस्तमसकृद्वस्तिकर्म च नहि वस्तिसमं किञ्चिद्वातरक्तचिकित्सितम्","text":"rukṣairvā mṛdubhiḥ śastamasakṛdvastikarma ca nahi vastisamaṃ kiñcidvātaraktacikitsitam"},{"type":"verse","number":"26","sanskrit":"बाह्यमालेपनाभ्यङ्गपरिषेकोपनाहनैः विरेकास्थापनस्नेहपानैर्गम्भीरमाचरेत्","text":"bāhyamālepanābhyaṅgapariṣekopanāhanaiḥ virekāsthāpanasnehapānairgambhīramācaret"},{"type":"verse","number":"27","sanskrit":"दिवास्वप्नं ससन्तापं व्यायामं मैथुनं तथा कटूष्णगुर्वभिष्यन्दि लवणाम्लौ च वर्जयेत्","text":"divāsvapnaṃ sasantāpaṃ vyāyāmaṃ maithunaṃ tathā kaṭūṣṇagurvabhiṣyandi lavaṇāmlau ca varjayet"},{"type":"verse","number":"28","sanskrit":"पुराणा यवगोधूमा नीवाराः शालिषष्टिकाः भोजनार्थे रसार्थे तु विष्किराः प्रतुदा हिताः","text":"purāṇā yavagodhūmā nīvārāḥ śāliṣaṣṭikāḥ bhojanārthe rasārthe tu viṣkirāḥ pratudā hitāḥ"},{"type":"verse","number":"29","sanskrit":"आढक्यश्चणका मुद्गा मसूराः सकुलत्थकाः यूषार्थे बहुसर्पिष्काः प्रशस्ता वातशोणिते","text":"āḍhakyaścaṇakā mudgā masūrāḥ sakulatthakāḥ yūṣārthe bahusarpiṣkāḥ praśastā vātaśoṇite"},{"type":"verse","number":"30","sanskrit":"सुनिषण्णकवेत्राग्रकाकमाचीशतावरी वास्तुकोपोदिकाशाकं शाकं सौवर्चलं तथा","text":"suniṣaṇṇakavetrāgrakākamācīśatāvarī vāstukopodikāśākaṃ śākaṃ sauvarcalaṃ tathā"},{"type":"verse","number":"31","sanskrit":"घृतमांसरसैर्भृष्टं शाकसात्म्याय दापयेत्","text":"ghṛtamāṃsarasairbhṛṣṭaṃ śākasātmyāya dāpayet"},{"type":"verse","number":"32","sanskrit":"सर्पिस्तैलवसामज्जपानाभ्यञ्जनवस्तिमिः सुखोष्णैरुपनाहैश्च वातोत्तरमुपाचरेत् हितो गोधूमचूर्णश्च च्छागक्षीरघृताप्लुतः","text":"sarpistailavasāmajjapānābhyañjanavastimiḥ sukhoṣṇairupanāhaiśca vātottaramupācaret hito godhūmacūrṇaśca cchāgakṣīraghṛtāplutaḥ"},{"type":"verse","number":"33","sanskrit":"लेपस्तद्वत्तिला भृष्टाः पिष्टाः पयसि निर्वृताः क्षारपिष्टातसीलेपो वर्द्धमानफलेन वा","text":"lepastadvattilā bhṛṣṭāḥ piṣṭāḥ payasi nirvṛtāḥ kṣārapiṣṭātasīlepo varddhamānaphalena vā"},{"type":"verse","number":"34","sanskrit":"उभे शताह्वे मधुकं बलां चै प्रियालकं चापि कसेरुकं च वृत्तं विदारीञ्च सितोपलाञ्चै कुर्यात्प्रदेहं पवने सरक्ते","text":"ubhe śatāhve madhukaṃ balāṃ cai priyālakaṃ cāpi kaserukaṃ ca vṛttaṃ vidārīñca sitopalāñcai kuryātpradehaṃ pavane sarakte"},{"type":"verse","number":"35","sanskrit":"रास्ना गुडूची मधुकं बले द्वे सजीवकं सर्षभकं पयश्च घृतञ्च सिद्धं मधुशेषयुक्तं रक्तानिलार्त्तिं प्रणुदेत्प्रदेहः","text":"rāsnā guḍūcī madhukaṃ bale dve sajīvakaṃ sarṣabhakaṃ payaśca ghṛtañca siddhaṃ madhuśeṣayuktaṃ raktānilārttiṃ praṇudetpradehaḥ"},{"type":"verse","number":"36","sanskrit":"वासागुडूचीचतुरङ्गुलानामेरण्डतैलेन पिबेत्कषायम् क्रमेण सर्वाङ्गजमप्यशेषं जयेदसृग्वातभवं विकारम्","text":"vāsāguḍūcīcaturaṅgulānāmeraṇḍatailena pibetkaṣāyam krameṇa sarvāṅgajamapyaśeṣaṃ jayedasṛgvātabhavaṃ vikāram"},{"type":"verse","number":"37","sanskrit":"दशमूलीशृतं क्षीरं सद्यः शूलनिवारणम् परिषेकोऽनिलप्राये तद्वत्कोष्णेन सर्पिषा","text":"daśamūlīśṛtaṃ kṣīraṃ sadyaḥ śūlanivāraṇam pariṣeko'nilaprāye tadvatkoṣṇena sarpiṣā"},{"type":"verse","number":"38","sanskrit":"पटोलकटुकाभीरुत्रिफलाऽमृतसाधितम् क्वाथं पीत्वा जयेज्जन्तुः सदाहं वातशोणितम्","text":"paṭolakaṭukābhīrutriphalā'mṛtasādhitam kvāthaṃ pītvā jayejjantuḥ sadāhaṃ vātaśoṇitam"},{"type":"verse","number":"39","sanskrit":"त्रिवृद्विदारीक्षुरकक्वाथो वातास्रनाशनः अमृता कफवातघ्नी कफमेदोविशोषिणी","text":"trivṛdvidārīkṣurakakvātho vātāsranāśanaḥ amṛtā kaphavātaghnī kaphamedoviśoṣiṇī"},{"type":"verse","number":"40","sanskrit":"वातरक्तप्रशमनी कण्डूवीसर्पनाशिनी","text":"vātaraktapraśamanī kaṇḍūvīsarpanāśinī"},{"type":"verse","number":"41","sanskrit":"गुडूच्याः स्वरसं कल्कं चूर्णं वा क्वाथमेव च प्रभूतकालमासेव्य मुच्यते वातशोणितात्","text":"guḍūcyāḥ svarasaṃ kalkaṃ cūrṇaṃ vā kvāthameva ca prabhūtakālamāsevya mucyate vātaśoṇitāt"},{"type":"verse","number":"42","sanskrit":"अमृता नागर धान्यक कर्षत्रितयेन पाचनं सिद्धम् जयति सरक्तं वातं सामं कुष्ठान्यशेषाणि","text":"amṛtā nāgara dhānyaka karṣatritayena pācanaṃ siddham jayati saraktaṃ vātaṃ sāmaṃ kuṣṭhānyaśeṣāṇi"},{"type":"verse","number":"43","sanskrit":"वत्सादन्युद्भवः क्वाथः पीतो गुग्गुलुमिश्रितः समीरणसमायुक्तं शोणितं सम्प्रणाशयेत्","text":"vatsādanyudbhavaḥ kvāthaḥ pīto guggulumiśritaḥ samīraṇasamāyuktaṃ śoṇitaṃ sampraṇāśayet"},{"type":"verse","number":"44","sanskrit":"तिस्रोऽथ वा पञ्च गुडेन पथ्या जग्ध्वा पिबेच्छिन्नरुहाकषायम् तद्वातरक्तं शमयत्युदीर्णमाजानुभिन्नं च्युतमप्यवश्यम्","text":"tisro'tha vā pañca guḍena pathyā jagdhvā pibecchinnaruhākaṣāyam tadvātaraktaṃ śamayatyudīrṇamājānubhinnaṃ cyutamapyavaśyam"},{"type":"verse","number":"45","sanskrit":"गुग्गुल्वमृतवल्लीभिर्द्राक्षा लुङ्गरसेन वा त्रिफलाया रसैर्युक्ता गुटिकाः कोलसम्मिताः","text":"guggulvamṛtavallībhirdrākṣā luṅgarasena vā triphalāyā rasairyuktā guṭikāḥ kolasammitāḥ"},{"type":"verse","number":"46","sanskrit":"भक्षयेन्मधुनालोड्य शृणु कुर्वन्ति यत्फलम् पादस्फोटं महाघोरं स्फुटत्सर्वाङ्गसञ्चयम् तत्सर्वं नाशयत्याशु साध्यञ्चैव सशोणितम्","text":"bhakṣayenmadhunāloḍya śṛṇu kurvanti yatphalam pādasphoṭaṃ mahāghoraṃ sphuṭatsarvāṅgasañcayam tatsarvaṃ nāśayatyāśu sādhyañcaiva saśoṇitam"},{"type":"verse","number":"47","sanskrit":"माहिषं नवनीतं तु बलिना परिमिश्रितम् गोमूत्रमिश्रितं कृत्वा क्षीरेण लवणेन च","text":"māhiṣaṃ navanītaṃ tu balinā parimiśritam gomūtramiśritaṃ kṛtvā kṣīreṇa lavaṇena ca"},{"type":"verse","number":"48","sanskrit":"तदेकत्र समालोड्य वह्निना भावयेच्छनैः गात्रमुद्वर्त्तयेत्तेन देहस्फुटनशान्तये","text":"tadekatra samāloḍya vahninā bhāvayecchanaiḥ gātramudvarttayettena dehasphuṭanaśāntaye"},{"type":"verse","number":"49","sanskrit":"इति गुग्गुलवटिका घृतेन वातं सगुडा विबन्धं पित्तं सिताढ्या मधुना कफञ्च वातासृगुग्रं रुबुतैलमिश्रा शुण्ठ्यामवातं शमयेद् गुडूची","text":"iti guggulavaṭikā ghṛtena vātaṃ saguḍā vibandhaṃ pittaṃ sitāḍhyā madhunā kaphañca vātāsṛgugraṃ rubutailamiśrā śuṇṭhyāmavātaṃ śamayed guḍūcī"},{"type":"verse","number":"50","sanskrit":"सिंहास्यपञ्चमूलीच्छिन्नरुहैरण्डगोक्षुरक्वाथः एरण्डतैलरामठसैन्धवचूर्णान्वितः पीतः","text":"siṃhāsyapañcamūlīcchinnaruhairaṇḍagokṣurakvāthaḥ eraṇḍatailarāmaṭhasaindhavacūrṇānvitaḥ pītaḥ"},{"type":"verse","number":"51","sanskrit":"प्रशमयति वातरक्तं तथामवातं कटीशूलम् मूत्रपुरीषविबन्धं ब्रध्नविकारं सुदुर्वारम्","text":"praśamayati vātaraktaṃ tathāmavātaṃ kaṭīśūlam mūtrapurīṣavibandhaṃ bradhnavikāraṃ sudurvāram"},{"type":"verse","number":"52","sanskrit":"गन्धर्वहस्तवृषगोक्षुरकामृतानां मूलं बलेक्षुरकयोश्च पचेत्तु धीमान् वातासृगाशु विनिहन्ति चिरप्ररुढ माजानुगं स्फुटितमूर्ध्वगतन्तु धीमान्","text":"gandharvahastavṛṣagokṣurakāmṛtānāṃ mūlaṃ balekṣurakayośca pacettu dhīmān vātāsṛgāśu vinihanti cirapraruḍha mājānugaṃ sphuṭitamūrdhvagatantu dhīmān"},{"type":"verse","number":"53","sanskrit":"कफपित्तप्रशमनं कण्डूवीसर्पनाशनम् वातरक्तप्रशमनं हृद्यं गुडघृतं स्मृतम्","text":"kaphapittapraśamanaṃ kaṇḍūvīsarpanāśanam vātaraktapraśamanaṃ hṛdyaṃ guḍaghṛtaṃ smṛtam"},{"type":"verse","number":"54","sanskrit":"पिप्पलीवर्द्धमानं वा सेव्यं पथ्या गुडेन वा","text":"pippalīvarddhamānaṃ vā sevyaṃ pathyā guḍena vā"},{"type":"verse","number":"55","sanskrit":"कोकिलाक्षामृताक्वाथे पिबेत्कृष्णां यथाबलम् पथ्यभोजी त्रिसप्ताहान्मुच्यते वातशोणितात्","text":"kokilākṣāmṛtākvāthe pibetkṛṣṇāṃ yathābalam pathyabhojī trisaptāhānmucyate vātaśoṇitāt"},{"type":"verse","number":"56","sanskrit":"मधुकाद् द्विगुणं तैलं तैलादाजं पयो भवेत् तद्यथाऽग्निबलं पेयं वातरक्तरुजाऽपहम्","text":"madhukād dviguṇaṃ tailaṃ tailādājaṃ payo bhavet tadyathā'gnibalaṃ peyaṃ vātaraktarujā'paham"},{"type":"verse","number":"57","sanskrit":"अगस्ति पुष्पचूर्णेन माहिषं जनयेद्दधि तदुत्थनवनीतेन देहजं स्फुटनं जयेत्","text":"agasti puṣpacūrṇena māhiṣaṃ janayeddadhi tadutthanavanītena dehajaṃ sphuṭanaṃ jayet"},{"type":"verse","number":"58","sanskrit":"नवकार्षिकक्वाथः त्रिफलानिम्बमञ्जिष्ठा वचा कटुकरोहिणी वत्सादनी दारुनिशा कषायो नवकार्षिकः वातरक्तं तथा कुष्ठं पामानं रक्तमण्डलम्","text":"navakārṣikakvāthaḥ triphalānimbamañjiṣṭhā vacā kaṭukarohiṇī vatsādanī dāruniśā kaṣāyo navakārṣikaḥ vātaraktaṃ tathā kuṣṭhaṃ pāmānaṃ raktamaṇḍalam"},{"type":"verse","number":"59","sanskrit":"कण्डूकपालिकाकुष्ठं पानादेवापकर्षति पञ्चरक्तिकमाषेण कषायो नवकार्षिकः","text":"kaṇḍūkapālikākuṣṭhaṃ pānādevāpakarṣati pañcaraktikamāṣeṇa kaṣāyo navakārṣikaḥ"},{"type":"verse","number":"60","sanskrit":"किञ्चैवं साधिते क्वाथे योग्या मात्रा प्रदीयते कर्षादौ तु पलं यावद्दद्यात्षोडशिकं जलम्","text":"kiñcaivaṃ sādhite kvāthe yogyā mātrā pradīyate karṣādau tu palaṃ yāvaddadyātṣoḍaśikaṃ jalam"},{"type":"verse","number":"61","sanskrit":"ततस्तु कुडवं यावदष्टादशगुणं जलम् चतुर्गुणमतश्चोर्ध्वं यावत्प्रस्थादिकं भवेत्","text":"tatastu kuḍavaṃ yāvadaṣṭādaśaguṇaṃ jalam caturguṇamataścordhvaṃ yāvatprasthādikaṃ bhavet"},{"type":"verse","number":"62","sanskrit":"विरेचनैर्घृतक्षीरपानैः सेकैः सवस्तिभिः लेपनं शाल्मलीकल्कमविक्षीरेण संयुतम्","text":"virecanairghṛtakṣīrapānaiḥ sekaiḥ savastibhiḥ lepanaṃ śālmalīkalkamavikṣīreṇa saṃyutam"},{"type":"verse","number":"63","sanskrit":"रक्तोत्तरं क्षीरघृतं मधुकोशीरवारिभिः सेचनं चात्र कर्त्तव्यमविक्षीरैः क्षणं क्षणम्","text":"raktottaraṃ kṣīraghṛtaṃ madhukośīravāribhiḥ secanaṃ cātra karttavyamavikṣīraiḥ kṣaṇaṃ kṣaṇam"},{"type":"verse","number":"64","sanskrit":"सहस्रशतधौतेन घृतेन रुधिरोत्तरे लेपनं सुष्ठु शीतेन घृतसर्जरसेन वा","text":"sahasraśatadhautena ghṛtena rudhirottare lepanaṃ suṣṭhu śītena ghṛtasarjarasena vā"},{"type":"verse","number":"65","sanskrit":"शीतैर्निर्वापणैश्चापि रक्तपित्तोत्तरं जयेत् सरागे सरुजे दाहे रक्तं विस्राव्य लेपयेत्","text":"śītairnirvāpaṇaiścāpi raktapittottaraṃ jayet sarāge saruje dāhe raktaṃ visrāvya lepayet"},{"type":"verse","number":"66","sanskrit":"तिलाः प्रियालं मधुकं बिसमूलं च वेतसम् सघृतं पयसा पिष्टं प्रलेपो दाहरोगनुत्","text":"tilāḥ priyālaṃ madhukaṃ bisamūlaṃ ca vetasam saghṛtaṃ payasā piṣṭaṃ pralepo dāharoganut"},{"type":"verse","number":"67","sanskrit":"पित्तोत्तरे तुकाश्मर्यद्रा क्षाऽरग्वधचन्दनैः","text":"pittottare tukāśmaryadrā kṣā'ragvadhacandanaiḥ"},{"type":"verse","number":"68","sanskrit":"मधुकक्षीरकाकोलीयुक्तैः क्वाथं सुशीतलम् शर्करामधुसंयुक्तं वातरक्ते पिबेन्नरः","text":"madhukakṣīrakākolīyuktaiḥ kvāthaṃ suśītalam śarkarāmadhusaṃyuktaṃ vātarakte pibennaraḥ"},{"type":"verse","number":"69","sanskrit":"धारोष्णं मूत्रसंयुक्तं क्षीरं दोषानुलोमनम् पिबेद्वा सत्रिवृच्चूर्णं पित्तरक्तावृतानिले","text":"dhāroṣṇaṃ mūtrasaṃyuktaṃ kṣīraṃ doṣānulomanam pibedvā satrivṛccūrṇaṃ pittaraktāvṛtānile"},{"type":"verse","number":"70","sanskrit":"क्षीरेणैरण्डतैलं वा प्रयोगेण पिबेन्नरः बहुदोषे विरेकार्थं जीर्णे क्षीरौदनाशनः","text":"kṣīreṇairaṇḍatailaṃ vā prayogeṇa pibennaraḥ bahudoṣe virekārthaṃ jīrṇe kṣīraudanāśanaḥ"},{"type":"verse","number":"71","sanskrit":"पटोलं त्रिफला भीरु गुडूची कटुरोहिणी क्वाथः पित्ताधिके शस्तः शर्करामधुसंयुतः","text":"paṭolaṃ triphalā bhīru guḍūcī kaṭurohiṇī kvāthaḥ pittādhike śastaḥ śarkarāmadhusaṃyutaḥ"},{"type":"verse","number":"72","sanskrit":"तिक्तस्य सर्पिषःपानं बहुशश्च विरेचनम् वमनं मृदुनाऽत्यर्थं स्नेहसेको विलङ्घनम्","text":"tiktasya sarpiṣaḥpānaṃ bahuśaśca virecanam vamanaṃ mṛdunā'tyarthaṃ snehaseko vilaṅghanam"},{"type":"verse","number":"73","sanskrit":"कोष्णाः सेकाश्च शस्यन्ते वारतक्ते कफोत्तरे तैलमूत्रसुराशुक्तैः परिषेकाः सदा हिताः","text":"koṣṇāḥ sekāśca śasyante vāratakte kaphottare tailamūtrasurāśuktaiḥ pariṣekāḥ sadā hitāḥ"},{"type":"verse","number":"74","sanskrit":"गौरसर्षपकल्केन प्रदेहो वा रुजापहः","text":"gaurasarṣapakalkena pradeho vā rujāpahaḥ"},{"type":"verse","number":"75","sanskrit":"सवरुणशिग्रोः कल्को धान्याम्लेनानिलार्त्तिजिल्लेपात् भवति न वेति विकल्पो न विधेयः सिद्धयोगेऽस्मिन्","text":"savaruṇaśigroḥ kalko dhānyāmlenānilārttijillepāt bhavati na veti vikalpo na vidheyaḥ siddhayoge'smin"},{"type":"verse","number":"76","sanskrit":"कल्कः श्लेष्मोत्तरे लेपो वाजिगन्धातिलोद्भवः लेपः सर्षपनिम्बार्क हिंस्राक्षारतिलैर्हितः","text":"kalkaḥ śleṣmottare lepo vājigandhātilodbhavaḥ lepaḥ sarṣapanimbārka hiṃsrākṣāratilairhitaḥ"},{"type":"verse","number":"77","sanskrit":"श्रेष्ठः शक्तुघृतक्षारकपित्थत्वग्भिरेव च मसूरशिग्रोस्तद्बीजं हितं धान्याम्लसंयुतम् मुहूर्त्ताल्लिप्तमम्लैश्च सिञ्चैद्वातकफोत्तरे","text":"śreṣṭhaḥ śaktughṛtakṣārakapitthatvagbhireva ca masūraśigrostadbījaṃ hitaṃ dhānyāmlasaṃyutam muhūrttālliptamamlaiśca siñcaidvātakaphottare"},{"type":"verse","number":"78","sanskrit":"मुस्तामलकनिशाभिः क्वथितं तोयं समाक्षिकं पेयम् जयति सदागतिरक्तं सकफं वा सततयोगेन","text":"mustāmalakaniśābhiḥ kvathitaṃ toyaṃ samākṣikaṃ peyam jayati sadāgatiraktaṃ sakaphaṃ vā satatayogena"},{"type":"verse","number":"79","sanskrit":"हरिद्रा मृतकक्वाथं मधुना मधुरीकृतम् पिबेद्वा त्रिफलाक्वाथं वातरक्ते कफाधिके","text":"haridrā mṛtakakvāthaṃ madhunā madhurīkṛtam pibedvā triphalākvāthaṃ vātarakte kaphādhike"},{"type":"verse","number":"80","sanskrit":"हरीतकीं वा तक्रेण पाययेदुदकेन वा गृहधूमो वचा कुष्ठं शताह्वा रजनीद्वयम् प्रलेपःशूलनुद्वातरक्ते वातकफोत्तरे","text":"harītakīṃ vā takreṇa pāyayedudakena vā gṛhadhūmo vacā kuṣṭhaṃ śatāhvā rajanīdvayam pralepaḥśūlanudvātarakte vātakaphottare"},{"type":"verse","number":"81","sanskrit":"अमृताकटुकायष्टी शुण्ठीकल्कं समाक्षिकम्","text":"amṛtākaṭukāyaṣṭī śuṇṭhīkalkaṃ samākṣikam"},{"type":"verse","number":"82","sanskrit":"गोमूत्रपीतं जयति सकफं वातशोणितम् धात्रीहरिद्रा मुस्तानां कषायं वा समाक्षिकम्","text":"gomūtrapītaṃ jayati sakaphaṃ vātaśoṇitam dhātrīharidrā mustānāṃ kaṣāyaṃ vā samākṣikam"},{"type":"verse","number":"83","sanskrit":"लाङ्गल्यास्त्वमृतातुल्यं कन्दमुद्धृत्य यत्नतः योजयेत्त्रिफलालौहरजस्त्रिकटुकैः समैः","text":"lāṅgalyāstvamṛtātulyaṃ kandamuddhṛtya yatnataḥ yojayettriphalālauharajastrikaṭukaiḥ samaiḥ"},{"type":"verse","number":"84","sanskrit":"गुग्गुल्वमृतवल्लीभिर्द्राक्षालुङ्गरसेन वा त्रिफलाया रसैर्युक्ता गुटिकाः कोलसम्मिताः","text":"guggulvamṛtavallībhirdrākṣāluṅgarasena vā triphalāyā rasairyuktā guṭikāḥ kolasammitāḥ"},{"type":"verse","number":"85","sanskrit":"भक्षयेन्मधुनालोड्य शृणु कुर्वन्ति यत्फलम् पादस्फुटितं दुर्भग्नं जानुप्राप्तं च यद्भवेत्","text":"bhakṣayenmadhunāloḍya śṛṇu kurvanti yatphalam pādasphuṭitaṃ durbhagnaṃ jānuprāptaṃ ca yadbhavet"},{"type":"verse","number":"86","sanskrit":"यच्च देहोद्गतं रक्तं यच्चासाध्यं प्रकीर्त्तितम् घ्नन्त्येता भक्ष्यमाणस्य प्रबलं वातशोणितम्","text":"yacca dehodgataṃ raktaṃ yaccāsādhyaṃ prakīrttitam ghnantyetā bhakṣyamāṇasya prabalaṃ vātaśoṇitam"},{"type":"verse","number":"87","sanskrit":"बलामतिबलां मेदामात्मगुप्तां शतावरीम् काकोलद्यं क्षीरकाकोलद्यं रास्नां मृद्वीं च पेषयेत्","text":"balāmatibalāṃ medāmātmaguptāṃ śatāvarīm kākoladyaṃ kṣīrakākoladyaṃ rāsnāṃ mṛdvīṃ ca peṣayet"},{"type":"verse","number":"88","sanskrit":"घृतं चतुर्गुणं क्षीरं तैः सिद्धं वातरक्तनुत् हृत्पाण्डुरोगवीसर्पकामलादाहनाशनम्","text":"ghṛtaṃ caturguṇaṃ kṣīraṃ taiḥ siddhaṃ vātaraktanut hṛtpāṇḍurogavīsarpakāmalādāhanāśanam"},{"type":"verse","number":"89","sanskrit":"बलास्थिरा नागबला गुडूची शतावरी कल्क कषायसिद्धम् तैलं विदध्यादनुवासनेषुतद्वातरक्तं शमयत्युदीर्णम्","text":"balāsthirā nāgabalā guḍūcī śatāvarī kalka kaṣāyasiddham tailaṃ vidadhyādanuvāsaneṣutadvātaraktaṃ śamayatyudīrṇam"},{"type":"verse","number":"90","sanskrit":"त्रायन्तिका चामलकी द्विकाकोली शतावरी कसेरुका कषायेण कल्कैरेभिः पचेद् घृतम्","text":"trāyantikā cāmalakī dvikākolī śatāvarī kaserukā kaṣāyeṇa kalkairebhiḥ paced ghṛtam"},{"type":"verse","number":"91","sanskrit":"उभे परुषके द्रा क्षा काश्मर्यः ससुरद्रुमाः पृथग्विदार्याः स्वरसं तथा क्षीरं चतुर्गुणम्","text":"ubhe paruṣake drā kṣā kāśmaryaḥ sasuradrumāḥ pṛthagvidāryāḥ svarasaṃ tathā kṣīraṃ caturguṇam"},{"type":"verse","number":"92","sanskrit":"एतदायोजितं सर्पिः पारूषकमिति स्मृतम् वातरक्ते क्षते क्षीणे वीसर्पे पैत्तिके ज्वरे","text":"etadāyojitaṃ sarpiḥ pārūṣakamiti smṛtam vātarakte kṣate kṣīṇe vīsarpe paittike jvare"},{"type":"verse","number":"93","sanskrit":"शतावरीकल्कगर्भं रसे तस्याश्चतुर्गुणे क्षीरतुल्यं घृतं सिद्धं वातशोणितनाशनम्","text":"śatāvarīkalkagarbhaṃ rase tasyāścaturguṇe kṣīratulyaṃ ghṛtaṃ siddhaṃ vātaśoṇitanāśanam"},{"type":"verse","number":"94","sanskrit":"ॠषभक्षीरकाकोलीक्षीरिकाजीवकैः समैः सिद्धं त्वार्षभकं सर्पिः सक्षीरं वातरक्तनुत्","text":"ṝṣabhakṣīrakākolīkṣīrikājīvakaiḥ samaiḥ siddhaṃ tvārṣabhakaṃ sarpiḥ sakṣīraṃ vātaraktanut"},{"type":"verse","number":"95","sanskrit":"गुडूचीक्वाथकल्काभ्यां सपयस्कं घृतं शृतम् हन्ति वातं तथारक्तं कुष्ठं जयति दुस्तरम्","text":"guḍūcīkvāthakalkābhyāṃ sapayaskaṃ ghṛtaṃ śṛtam hanti vātaṃ tathāraktaṃ kuṣṭhaṃ jayati dustaram"},{"type":"verse","number":"96","sanskrit":"क्षीरं स्नेहसमं दद्याच्चतुर्भिश्च चतुर्गुणम् एकद्वित्रिद्र वद्र व्यैः कुर्यात्स्नेहाच्चतुर्गुणम्","text":"kṣīraṃ snehasamaṃ dadyāccaturbhiśca caturguṇam ekadvitridra vadra vyaiḥ kuryātsnehāccaturguṇam"},{"type":"verse","number":"97","sanskrit":"अमृतायाः कषायेण कल्केन च महौषधात् मृद्वग्निना घृतं सिद्धं वातरक्तहरं परम्","text":"amṛtāyāḥ kaṣāyeṇa kalkena ca mahauṣadhāt mṛdvagninā ghṛtaṃ siddhaṃ vātaraktaharaṃ param"},{"type":"verse","number":"98","sanskrit":"आमवाताढ्यवातादीन्कृमिकुष्ठव्रणानपि अर्शांसि गुल्मांश्च तथा नाशयेदाशु योजितम्","text":"āmavātāḍhyavātādīnkṛmikuṣṭhavraṇānapi arśāṃsi gulmāṃśca tathā nāśayedāśu yojitam"},{"type":"verse","number":"99","sanskrit":"अमृतास्वरसविपक्वं सर्पिस्तत्कल्कसाधितं पीतम् अपहरति वातरक्तमुत्तानं चावगाढं च","text":"amṛtāsvarasavipakvaṃ sarpistatkalkasādhitaṃ pītam apaharati vātaraktamuttānaṃ cāvagāḍhaṃ ca"},{"type":"verse","number":"100","sanskrit":"अमृतायाः पलशतं जलद्रो णावशेषितम् घृतप्रस्थं विपक्तव्यं कल्कादष्टौ पलानि च","text":"amṛtāyāḥ palaśataṃ jaladro ṇāvaśeṣitam ghṛtaprasthaṃ vipaktavyaṃ kalkādaṣṭau palāni ca"},{"type":"verse","number":"101","sanskrit":"चतुर्गुणेन पयसा वातासृक्कुष्ठनाशनम् कामलापाण्डुरोगघ्नं प्लीहकासज्वरापहम्","text":"caturguṇena payasā vātāsṛkkuṣṭhanāśanam kāmalāpāṇḍurogaghnaṃ plīhakāsajvarāpaham"},{"type":"verse","number":"102","sanskrit":"अमृता मधुकं द्रा क्षा त्रिफला नागरं बला वासारग्वधवृश्चीरदेवदारुत्रिकण्टकम्","text":"amṛtā madhukaṃ drā kṣā triphalā nāgaraṃ balā vāsāragvadhavṛścīradevadārutrikaṇṭakam"},{"type":"verse","number":"103","sanskrit":"कटुका रोहिणी कृष्णा काश्मर्यस्य फलानि च रास्नाक्षुरकगन्धर्ववृद्धदारघनोत्पलैः","text":"kaṭukā rohiṇī kṛṣṇā kāśmaryasya phalāni ca rāsnākṣurakagandharvavṛddhadāraghanotpalaiḥ"},{"type":"verse","number":"104","sanskrit":"कल्कैरेभिः समैः कृत्वा सर्पिः प्रस्थं विपाचयेत् धात्रीरसः समो देयो वारित्रिगुणसंयुतः","text":"kalkairebhiḥ samaiḥ kṛtvā sarpiḥ prasthaṃ vipācayet dhātrīrasaḥ samo deyo vāritriguṇasaṃyutaḥ"},{"type":"verse","number":"105","sanskrit":"सम्यक्सिद्धं च विज्ञाय भोज्ये पाने च शस्यते बहुदोषोत्थितं वातरक्तेन सह मूर्च्छितम्","text":"samyaksiddhaṃ ca vijñāya bhojye pāne ca śasyate bahudoṣotthitaṃ vātaraktena saha mūrcchitam"},{"type":"verse","number":"106","sanskrit":"उत्तानं चापि गम्भीरं त्रिकजङ्घोरुजानुकम् क्रोष्टुशीर्षे महामूले आमवाते सुदारुणे","text":"uttānaṃ cāpi gambhīraṃ trikajaṅghorujānukam kroṣṭuśīrṣe mahāmūle āmavāte sudāruṇe"},{"type":"verse","number":"107","sanskrit":"दाहरोगोपसृष्टस्य वेदनां चातिदुस्तराम् मूत्रकृच्छ्रमुदावर्त्तं प्रमेहं विषमज्वरान्","text":"dāharogopasṛṣṭasya vedanāṃ cātidustarām mūtrakṛcchramudāvarttaṃ pramehaṃ viṣamajvarān"},{"type":"verse","number":"108","sanskrit":"एतान्सर्वान्निहन्त्याशु वातपित्तकफोत्थितान् सर्वकालोपयोगेन वर्णायुर्बलबर्द्धनम् अश्विभ्यां निर्मितं श्रेष्ठं घृतमेतदनुत्तमम्","text":"etānsarvānnihantyāśu vātapittakaphotthitān sarvakālopayogena varṇāyurbalabarddhanam aśvibhyāṃ nirmitaṃ śreṣṭhaṃ ghṛtametadanuttamam"},{"type":"verse","number":"109","sanskrit":"गुडूचीस्वरसे सर्पिर्जीवनीयैश्च साधितम् कल्कैश्चतुर्गुणैः क्षीरैः सिद्धं वाप्यस्रवातनुत्","text":"guḍūcīsvarase sarpirjīvanīyaiśca sādhitam kalkaiścaturguṇaiḥ kṣīraiḥ siddhaṃ vāpyasravātanut"},{"type":"verse","number":"110","sanskrit":"अमृतायाः शतं प्राप्य जलद्रो णे विपाचयेत् चतुर्भागावशिष्टन्तु घृतप्रस्थं विपाचयेत्","text":"amṛtāyāḥ śataṃ prāpya jaladro ṇe vipācayet caturbhāgāvaśiṣṭantu ghṛtaprasthaṃ vipācayet"},{"type":"verse","number":"111","sanskrit":"क्षीरं चतुर्गुणं तत्र दापयेन्मतिमान् भिषक् कल्कञ्चात्र प्रवक्ष्यामि यथावदनुपूर्वशः","text":"kṣīraṃ caturguṇaṃ tatra dāpayenmatimān bhiṣak kalkañcātra pravakṣyāmi yathāvadanupūrvaśaḥ"},{"type":"verse","number":"112","sanskrit":"काकोली क्षीरकाकोली जीवकर्षभकौ च यत् शतावरी पयस्या च मधुकं नीलमुत्पलम्","text":"kākolī kṣīrakākolī jīvakarṣabhakau ca yat śatāvarī payasyā ca madhukaṃ nīlamutpalam"},{"type":"verse","number":"113","sanskrit":"अश्वकन्दस्य मूलानि स्थिरां वा कटुरोहिणीम् ऋद्धिं वृद्धिं तथा मेदे श्वदंष्ट्रां बृहतीद्वयम्","text":"aśvakandasya mūlāni sthirāṃ vā kaṭurohiṇīm ṛddhiṃ vṛddhiṃ tathā mede śvadaṃṣṭrāṃ bṛhatīdvayam"},{"type":"verse","number":"114","sanskrit":"गुडूचीं पिप्पलद्यं रास्नां वासकं चापि संहरेत् तदेकस्थं समैर्भागैः पाचयेन्मृदुनाग्निना","text":"guḍūcīṃ pippaladyaṃ rāsnāṃ vāsakaṃ cāpi saṃharet tadekasthaṃ samairbhāgaiḥ pācayenmṛdunāgninā"},{"type":"verse","number":"115","sanskrit":"पानाभ्यञ्जननस्येषु परिषेके च दापयेत् वातरक्तं सशोषाढ्यं सदाहं क्रोष्टुशीर्षकम्","text":"pānābhyañjananasyeṣu pariṣeke ca dāpayet vātaraktaṃ saśoṣāḍhyaṃ sadāhaṃ kroṣṭuśīrṣakam"},{"type":"verse","number":"116","sanskrit":"खञ्जोरुस्तम्भवातञ्च वातरक्तं सुदारुणम् बहूदितं वातकृच्छ्रं गृध्रसीं वातकण्टकम्","text":"khañjorustambhavātañca vātaraktaṃ sudāruṇam bahūditaṃ vātakṛcchraṃ gṛdhrasīṃ vātakaṇṭakam"},{"type":"verse","number":"117","sanskrit":"नाशयेद्योजितं सर्पिर्धन्वन्तरिवचो यथा","text":"nāśayedyojitaṃ sarpirdhanvantarivaco yathā"},{"type":"verse","number":"118","sanskrit":"क्वाथेन शतपुष्पायाः कुष्ठस्य मधुकस्य च एकैकं साधयेत्तैलं वातरक्तरुजापह्रम्","text":"kvāthena śatapuṣpāyāḥ kuṣṭhasya madhukasya ca ekaikaṃ sādhayettailaṃ vātaraktarujāpahram"},{"type":"verse","number":"119","sanskrit":"सारिवारिष्टकूष्माण्डपोतकीभस्मजाम्बुना गुडूचीगव्यदुग्धाभ्यां कर्मरङ्गरसेन च","text":"sārivāriṣṭakūṣmāṇḍapotakībhasmajāmbunā guḍūcīgavyadugdhābhyāṃ karmaraṅgarasena ca"},{"type":"verse","number":"120","sanskrit":"विपचेत्तिलजं तैलं दत्वैतानि भिषग्वरः काकोल्यौ जीवकं मेदे शताह्वाक्षीरिणीयुतैः","text":"vipacettilajaṃ tailaṃ datvaitāni bhiṣagvaraḥ kākolyau jīvakaṃ mede śatāhvākṣīriṇīyutaiḥ"},{"type":"verse","number":"121","sanskrit":"जिङ्गीसिक्थामृतानन्तासर्जसैन्धवचन्दनैः हन्याद्वातास्रजं घोरं स्फुटितं गलितं तथा","text":"jiṅgīsikthāmṛtānantāsarjasaindhavacandanaiḥ hanyādvātāsrajaṃ ghoraṃ sphuṭitaṃ galitaṃ tathā"},{"type":"verse","number":"122","sanskrit":"चर्मदलाख्यं पामादींस्त्वग्दोषञ्च विपादिकाम् कुष्ठान्यर्शांसि वीसर्प व्रणशोथं भगन्दरम्","text":"carmadalākhyaṃ pāmādīṃstvagdoṣañca vipādikām kuṣṭhānyarśāṃsi vīsarpa vraṇaśothaṃ bhagandaram"},{"type":"verse","number":"123","sanskrit":"न सोस्ति वातरक्तस्य विकारो योभिवर्द्धितः यं न हन्यात्प्रसह्यैतत्पिण्डतैलं महत्स्मृतम्","text":"na sosti vātaraktasya vikāro yobhivarddhitaḥ yaṃ na hanyātprasahyaitatpiṇḍatailaṃ mahatsmṛtam"},{"type":"verse","number":"124","sanskrit":"सारिवासर्जमञ्जिष्ठायष्टीसिक्थैः पयोन्वितैः तैलं पक्वं प्रयोक्तव्यं पिण्डाख्यं वातशोणिते","text":"sārivāsarjamañjiṣṭhāyaṣṭīsikthaiḥ payonvitaiḥ tailaṃ pakvaṃ prayoktavyaṃ piṇḍākhyaṃ vātaśoṇite"},{"type":"verse","number":"125","sanskrit":"सारिवासर्जयष्ट्याह्वमधुसिक्थैः पयोन्वितैः सिद्धमेरण्डजं तैलं वातरक्तरुजापहम् अपूतमथितस्यास्य पिण्डतैलस्य योगतः","text":"sārivāsarjayaṣṭyāhvamadhusikthaiḥ payonvitaiḥ siddhameraṇḍajaṃ tailaṃ vātaraktarujāpaham apūtamathitasyāsya piṇḍatailasya yogataḥ"},{"type":"verse","number":"126","sanskrit":"पद्मकेशरयष्ट्याह्वफेनिलैः पद्मकोत्पलैः पृथक्पञ्चपलैर्दत्तं बलाकिंशुकचन्दनैः","text":"padmakeśarayaṣṭyāhvaphenilaiḥ padmakotpalaiḥ pṛthakpañcapalairdattaṃ balākiṃśukacandanaiḥ"},{"type":"verse","number":"127","sanskrit":"जले शृतं पचेत्तैलं प्रस्थं सौवीरसम्मितम् लोध्रकाकोलिकोशीरजीवकर्षभकेशरैः","text":"jale śṛtaṃ pacettailaṃ prasthaṃ sauvīrasammitam lodhrakākolikośīrajīvakarṣabhakeśaraiḥ"},{"type":"verse","number":"128","sanskrit":"मदयन्तिलतापत्रपद्मकेशरपद्मकैः प्रपौण्डरीककालीयमेदामांसीप्रियङ्गुभिः","text":"madayantilatāpatrapadmakeśarapadmakaiḥ prapauṇḍarīkakālīyamedāmāṃsīpriyaṅgubhiḥ"},{"type":"verse","number":"129","sanskrit":"कुङ्कुमैर्द्विगुणैः कर्षैर्मञ्जिष्ठायाः पलेन च महापद्ममिदं तैलं वातासृग्ज्वरनाशनम्","text":"kuṅkumairdviguṇaiḥ karṣairmañjiṣṭhāyāḥ palena ca mahāpadmamidaṃ tailaṃ vātāsṛgjvaranāśanam"},{"type":"verse","number":"130","sanskrit":"पद्मकोशीरयष्ट्याह्वरजनीक्वाथसाधितम्","text":"padmakośīrayaṣṭyāhvarajanīkvāthasādhitam"},{"type":"verse","number":"131","sanskrit":"स्यात्पिष्टैः सर्जमञ्जिष्ठावीराकाकोलिचन्दनैः खुड्डाकपद्मकमिदं तैलं वातास्रपित्तनुत्","text":"syātpiṣṭaiḥ sarjamañjiṣṭhāvīrākākolicandanaiḥ khuḍḍākapadmakamidaṃ tailaṃ vātāsrapittanut"},{"type":"verse","number":"132","sanskrit":"तुलां पचेज्जलद्रो णे गुडूच्याः पादशेषितम् क्षीरद्रो णन्तु ताभ्यां च पचेत्तैलाढकं शनैः","text":"tulāṃ pacejjaladro ṇe guḍūcyāḥ pādaśeṣitam kṣīradro ṇantu tābhyāṃ ca pacettailāḍhakaṃ śanaiḥ"},{"type":"verse","number":"133","sanskrit":"कल्कैर्मधुकमञ्जिष्ठाजीवनीयगणोत्थितैः कुष्ठैलाऽगुरुमृद्वीका मांसी व्याघ्रनखं नखी","text":"kalkairmadhukamañjiṣṭhājīvanīyagaṇotthitaiḥ kuṣṭhailā'gurumṛdvīkā māṃsī vyāghranakhaṃ nakhī"},{"type":"verse","number":"134","sanskrit":"हरेणुः श्रावणी व्योषं शताह्वा शृङ्गिसारिवे त्वक्पत्रागुरुविक्रान्ताः स्थिरा तामलकी तथा","text":"hareṇuḥ śrāvaṇī vyoṣaṃ śatāhvā śṛṅgisārive tvakpatrāguruvikrāntāḥ sthirā tāmalakī tathā"},{"type":"verse","number":"135","sanskrit":"नतकेशरह्रीबेरं पद्मकोत्पलचन्दनम् सिद्धं कर्षसमैर्भागैः पानाभ्यङ्गानुवासनैः","text":"natakeśarahrīberaṃ padmakotpalacandanam siddhaṃ karṣasamairbhāgaiḥ pānābhyaṅgānuvāsanaiḥ"},{"type":"verse","number":"136","sanskrit":"सेव्यं वातास्रजान्हन्ति स्रोतोधात्वन्तराश्रितान् धन्यं पुंसवनं स्त्रीणां गर्भदं वातपित्तनुत्","text":"sevyaṃ vātāsrajānhanti srotodhātvantarāśritān dhanyaṃ puṃsavanaṃ strīṇāṃ garbhadaṃ vātapittanut"},{"type":"verse","number":"137","sanskrit":"स्वेदकण्डूरुजाऽयामशिरः कम्पामयार्दितान् हन्याद् ब्रणकृतान्दोषान्गुडूचीतैलमुत्तमम्","text":"svedakaṇḍūrujā'yāmaśiraḥ kampāmayārditān hanyād braṇakṛtāndoṣānguḍūcītailamuttamam"},{"type":"verse","number":"138","sanskrit":"गुडूची मधुकं ह्रस्वपञ्चमूलं पुनर्नवाम् रास्नामेरण्डमूलञ्च जीवनीयानि लाभतः","text":"guḍūcī madhukaṃ hrasvapañcamūlaṃ punarnavām rāsnāmeraṇḍamūlañca jīvanīyāni lābhataḥ"},{"type":"verse","number":"139","sanskrit":"पलानां शतिकैर्भागैर्बलापञ्चशतं भवेत् कोलं बिल्वं यवान्माषान् कुलत्थांश्चाढकोन्मितान्","text":"palānāṃ śatikairbhāgairbalāpañcaśataṃ bhavet kolaṃ bilvaṃ yavānmāṣān kulatthāṃścāḍhakonmitān"},{"type":"verse","number":"140","sanskrit":"काश्मर्याणाञ्च शुष्काणां द्रो णं द्रो णशतेऽम्भसः साधयेज्जर्जरं पूतं चतुर्द्रोणञ्च शेषयेत्","text":"kāśmaryāṇāñca śuṣkāṇāṃ dro ṇaṃ dro ṇaśate'mbhasaḥ sādhayejjarjaraṃ pūtaṃ caturdroṇañca śeṣayet"},{"type":"verse","number":"141","sanskrit":"तैलद्रो णं पचेत्तेन दत्वा पञ्चगुणं पयः पिष्ट्वा त्रिपलिकञ्चैव चन्दनोशीरकेशरम्","text":"tailadro ṇaṃ pacettena datvā pañcaguṇaṃ payaḥ piṣṭvā tripalikañcaiva candanośīrakeśaram"},{"type":"verse","number":"142","sanskrit":"पत्रैलाऽगुरुकुष्ठानि तगरं मधुयष्टिकाम् मञ्जिष्ठाऽद्धपलञ्चैव तत्सिद्धं सर्वयौगिकम्","text":"patrailā'gurukuṣṭhāni tagaraṃ madhuyaṣṭikām mañjiṣṭhā'ddhapalañcaiva tatsiddhaṃ sarvayaugikam"},{"type":"verse","number":"143","sanskrit":"वातरक्ते क्षते क्षीणे भारार्त्ते क्षीणरेतसि वेपनोत्क्षिप्तभग्नानां सर्वैकाङ्गजरोगिणाम्","text":"vātarakte kṣate kṣīṇe bhārārtte kṣīṇaretasi vepanotkṣiptabhagnānāṃ sarvaikāṅgajarogiṇām"},{"type":"verse","number":"144","sanskrit":"योनिदोषमपस्मारमुन्मादं विषमज्वरम् हन्यात्पुंसवनञ्चैव तैलाग्र्यममृताह्वयम्","text":"yonidoṣamapasmāramunmādaṃ viṣamajvaram hanyātpuṃsavanañcaiva tailāgryamamṛtāhvayam"},{"type":"verse","number":"145","sanskrit":"मृणालोत्पलशालूक सारिवोदीच्यकेशरैः चन्दनद्वयभूनिम्ब पद्मबीजकसेरुकैः","text":"mṛṇālotpalaśālūka sārivodīcyakeśaraiḥ candanadvayabhūnimba padmabījakaserukaiḥ"},{"type":"verse","number":"146","sanskrit":"पटोलकटुकानन्ता गुन्द्रा पर्पटवासकैः पिष्ट्वा तैलं घृतं पक्वं तृणमूलरसेन वा","text":"paṭolakaṭukānantā gundrā parpaṭavāsakaiḥ piṣṭvā tailaṃ ghṛtaṃ pakvaṃ tṛṇamūlarasena vā"},{"type":"verse","number":"147","sanskrit":"क्षीरद्विगुणसंयुक्तं वस्तिकर्मसु योजितम् नस्याभ्यञ्जनपानैर्वा हन्यात्पित्तगदानिदम्","text":"kṣīradviguṇasaṃyuktaṃ vastikarmasu yojitam nasyābhyañjanapānairvā hanyātpittagadānidam"},{"type":"verse","number":"148","sanskrit":"कनकशिखरिमानक्षारसंसिद्धतोये कुसुमलवणयुक्तैः सर्जनिर्यासचूर्णैः विधिशृततिलतैलं कल्कयुक्तं निहन्ति प्रचुर तरमिदानीमिन्द्र लुप्तास्रवातम्","text":"kanakaśikharimānakṣārasaṃsiddhatoye kusumalavaṇayuktaiḥ sarjaniryāsacūrṇaiḥ vidhiśṛtatilatailaṃ kalkayuktaṃ nihanti pracura taramidānīmindra luptāsravātam"},{"type":"verse","number":"149","sanskrit":"शुद्धां पचेन्नागबलातुलान्तु जलार्मणे पादकषायसिद्धम् विस्राव्य तैलाढकमत्र देयमजापयस्तैलविमिश्रितन्तु","text":"śuddhāṃ pacennāgabalātulāntu jalārmaṇe pādakaṣāyasiddham visrāvya tailāḍhakamatra deyamajāpayastailavimiśritantu"},{"type":"verse","number":"150","sanskrit":"नतं सयष्टीमधुकञ्चकल्कं दत्वा पृथक्पञ्चपलं विपक्वम् तद्वातरक्तं शमयत्युदीर्णं वस्तिप्रदानेन हि सप्तरात्रात् दशाहयोगेन करोत्यरोगं पीतञ्च तैलोत्तममश्विनोक्तम्","text":"nataṃ sayaṣṭīmadhukañcakalkaṃ datvā pṛthakpañcapalaṃ vipakvam tadvātaraktaṃ śamayatyudīrṇaṃ vastipradānena hi saptarātrāt daśāhayogena karotyarogaṃ pītañca tailottamamaśvinoktam"},{"type":"verse","number":"151","sanskrit":"जीवकर्षभकौ मेदे ॠष्यप्रोक्ता शतावरी मधुकं मधुपर्णी च काकोलीद्वयमेव च","text":"jīvakarṣabhakau mede ṝṣyaproktā śatāvarī madhukaṃ madhuparṇī ca kākolīdvayameva ca"},{"type":"verse","number":"152","sanskrit":"मुद्गमाषाख्यपर्णी च दशमूलं पुनर्नवा बलाऽमृता विदारी च साश्वगन्धाऽश्मभेदकौ","text":"mudgamāṣākhyaparṇī ca daśamūlaṃ punarnavā balā'mṛtā vidārī ca sāśvagandhā'śmabhedakau"},{"type":"verse","number":"153","sanskrit":"कुर्यात्कल्कं कषायञ्च ताभ्यां तैलं घृतं पचेत् लाभतश्च वसामज्जामांसं प्रतुदविष्किरात्","text":"kuryātkalkaṃ kaṣāyañca tābhyāṃ tailaṃ ghṛtaṃ pacet lābhataśca vasāmajjāmāṃsaṃ pratudaviṣkirāt"},{"type":"verse","number":"154","sanskrit":"चतुर्गुणेन पयसा संसिद्धं वातशोणितम् सर्वदेहाश्रितान्हन्ति व्याधीन्घोरांश्च वातजान्","text":"caturguṇena payasā saṃsiddhaṃ vātaśoṇitam sarvadehāśritānhanti vyādhīnghorāṃśca vātajān"},{"type":"verse","number":"155","sanskrit":"बलाकषायकल्काभ्यां तैलं क्षीरचतुर्गुणम् शतपाकं भवेदेतद्वातासृग्वातपित्तनुत्","text":"balākaṣāyakalkābhyāṃ tailaṃ kṣīracaturguṇam śatapākaṃ bhavedetadvātāsṛgvātapittanut"},{"type":"verse","number":"156","sanskrit":"धन्यं पुंसवनञ्चैव नराणां शुक्रवर्द्धनम् रेतोयोनिविकारघ्नमेतद्वातविकारनुत्","text":"dhanyaṃ puṃsavanañcaiva narāṇāṃ śukravarddhanam retoyonivikāraghnametadvātavikāranut"},{"type":"verse","number":"157","sanskrit":"मधुयष्ट्याः पलशतं कषाये पादशेषिते तैलाढकं समक्षीरं पचेत्कल्कैः पलोन्मितैः","text":"madhuyaṣṭyāḥ palaśataṃ kaṣāye pādaśeṣite tailāḍhakaṃ samakṣīraṃ pacetkalkaiḥ palonmitaiḥ"},{"type":"verse","number":"158","sanskrit":"शतपुष्पावरी मूर्वापयस्यागुरुचन्दनैः स्थिरहंसपदीमांसी द्विमेदामधुपर्णिभिः","text":"śatapuṣpāvarī mūrvāpayasyāgurucandanaiḥ sthirahaṃsapadīmāṃsī dvimedāmadhuparṇibhiḥ"},{"type":"verse","number":"159","sanskrit":"काकोलीक्षीर काकोलीतामलक्यृद्धिपद्मकैः जीवकर्षभजीवन्तीत्वक्पत्र नखबालकैः","text":"kākolīkṣīra kākolītāmalakyṛddhipadmakaiḥ jīvakarṣabhajīvantītvakpatra nakhabālakaiḥ"},{"type":"verse","number":"160","sanskrit":"प्रपौण्डरीकमञ्जिष्ठा सारिवेन्दुवितुन्नकैः वातासृक्पित्तदाहार्त्तिज्वरघ्नं बलवर्णकृत्","text":"prapauṇḍarīkamañjiṣṭhā sārivenduvitunnakaiḥ vātāsṛkpittadāhārttijvaraghnaṃ balavarṇakṛt"},{"type":"verse","number":"161","sanskrit":"मधुयष्ट्याः पलं पिष्ट्वा तैलप्रस्थं चतुर्गुणे क्षीरे साध्यं शतं वारांस्तदेव मधुकान्वितम्","text":"madhuyaṣṭyāḥ palaṃ piṣṭvā tailaprasthaṃ caturguṇe kṣīre sādhyaṃ śataṃ vārāṃstadeva madhukānvitam"},{"type":"verse","number":"162","sanskrit":"सिद्धं देयं त्रिदोषे स्याद्वातास्रश्वासकासनुत् धन्यं पुंसवनञ्चैव कामलादाहनाशनम्","text":"siddhaṃ deyaṃ tridoṣe syādvātāsraśvāsakāsanut dhanyaṃ puṃsavanañcaiva kāmalādāhanāśanam"},{"type":"verse","number":"163","sanskrit":"बलाकषायकल्काभ्यां तैलं क्षीरसमं पचेत् सहस्रशतपाकं वा वातासृग्वातरोगनुत्","text":"balākaṣāyakalkābhyāṃ tailaṃ kṣīrasamaṃ pacet sahasraśatapākaṃ vā vātāsṛgvātaroganut"},{"type":"verse","number":"164","sanskrit":"रसायनमिदं श्रेष्ठमिन्द्रि याणां प्रसादनम् जीवनं बृंहणं स्वर्यं शुक्रासृग्दोषनाशनम्","text":"rasāyanamidaṃ śreṣṭhamindri yāṇāṃ prasādanam jīvanaṃ bṛṃhaṇaṃ svaryaṃ śukrāsṛgdoṣanāśanam"},{"type":"verse","number":"165","sanskrit":"पुनर्नवामूलशतं विशुद्धं रुवूकमूलञ्च तथा प्रयोज्य दत्वा पलं षोडशकञ्च शुण्ठ्याः सङ्कुट्य सम्यग्विपचेद्घटेऽपाम्","text":"punarnavāmūlaśataṃ viśuddhaṃ ruvūkamūlañca tathā prayojya datvā palaṃ ṣoḍaśakañca śuṇṭhyāḥ saṅkuṭya samyagvipacedghaṭe'pām"},{"type":"verse","number":"166","sanskrit":"पलानि चाष्टावथ कौशिकस्यतेनाष्टशेषेण पुनः पचेत एरण्डतैलं कुडवञ्च दद्याद्दत्वा त्रिवृच्चूर्णपलानि पञ्च","text":"palāni cāṣṭāvatha kauśikasyatenāṣṭaśeṣeṇa punaḥ paceta eraṇḍatailaṃ kuḍavañca dadyāddatvā trivṛccūrṇapalāni pañca"},{"type":"verse","number":"167","sanskrit":"निकुम्भचूर्णस्य पलं गुडूच्याः पलद्वयं चार्द्धपलं पलं वा पलत्रयत्र्यूषणचित्रकाणि सिन्धूत्थभल्लातविडङ्गकानि","text":"nikumbhacūrṇasya palaṃ guḍūcyāḥ paladvayaṃ cārddhapalaṃ palaṃ vā palatrayatryūṣaṇacitrakāṇi sindhūtthabhallātaviḍaṅgakāni"},{"type":"verse","number":"168","sanskrit":"कर्षं तथा माक्षिकधातुचूर्णं पुनर्नवायाः पलमेव चूर्णम् चूर्णानि दत्वा ह्यवतार्य शीतं खादेन्नरः कर्षसमप्रमाणम्","text":"karṣaṃ tathā mākṣikadhātucūrṇaṃ punarnavāyāḥ palameva cūrṇam cūrṇāni datvā hyavatārya śītaṃ khādennaraḥ karṣasamapramāṇam"},{"type":"verse","number":"169","sanskrit":"वातासृजं वृद्धिगदं च सप्त जयत्यवश्यं त्वथ गृध्रसीं च जङ्घोरुपृष्ठत्रिकवस्तिजं च तथामवातं प्रबलं च हन्ति","text":"vātāsṛjaṃ vṛddhigadaṃ ca sapta jayatyavaśyaṃ tvatha gṛdhrasīṃ ca jaṅghorupṛṣṭhatrikavastijaṃ ca tathāmavātaṃ prabalaṃ ca hanti"},{"type":"verse","number":"170","sanskrit":"यावशूकसुरदारुसैन्धवं मुस्तकत्रुटिवचायवानिकाः व्योषदीप्यकनिशाफलत्रिकं जीरकद्वयविडङ्गचित्रकम्","text":"yāvaśūkasuradārusaindhavaṃ mustakatruṭivacāyavānikāḥ vyoṣadīpyakaniśāphalatrikaṃ jīrakadvayaviḍaṅgacitrakam"},{"type":"verse","number":"171","sanskrit":"कार्षिकं सुमसृणं सुयोजितं संयुतं पुरपलैश्च पञ्चभिः शर्करां पुरसमां सुपेषयेत्तप्तसर्पिषि विनिक्षिपेत्ततः","text":"kārṣikaṃ sumasṛṇaṃ suyojitaṃ saṃyutaṃ purapalaiśca pañcabhiḥ śarkarāṃ purasamāṃ supeṣayettaptasarpiṣi vinikṣipettataḥ"},{"type":"verse","number":"172","sanskrit":"वातरक्तमुदरं भगन्दरं प्लीहयक्ष्मविषमज्वरं गरम् श्वित्रकुष्ठमखिलव्रणानयं चित्तविभ्रमगदांश्च दारुणान्","text":"vātaraktamudaraṃ bhagandaraṃ plīhayakṣmaviṣamajvaraṃ garam śvitrakuṣṭhamakhilavraṇānayaṃ cittavibhramagadāṃśca dāruṇān"},{"type":"verse","number":"173","sanskrit":"गृध्रसीं च गुदजाग्निमन्दतां हन्ति कोष्ठजनितं महागदम् वज्रमिन्द्र सुकरादिव च्युतं गुप्तशैलकुलमुत्तमं द्रुतम्","text":"gṛdhrasīṃ ca gudajāgnimandatāṃ hanti koṣṭhajanitaṃ mahāgadam vajramindra sukarādiva cyutaṃ guptaśailakulamuttamaṃ drutam"},{"type":"verse","number":"174","sanskrit":"अन्नपानपरिहारवर्जितं सर्वकालसुखदं निरत्ययम् सेव्यमानमिदमश्विनिर्मितं गुग्गुलोर्हि वटिका रसायनम्","text":"annapānaparihāravarjitaṃ sarvakālasukhadaṃ niratyayam sevyamānamidamaśvinirmitaṃ guggulorhi vaṭikā rasāyanam"},{"type":"verse","number":"175","sanskrit":"चत्वारो माषका हीने मध्यमेऽष्टौ च माषकाः श्रेष्ठा द्वादशकाः प्रोक्ताः कोष्ठं विज्ञाय पाययेत्","text":"catvāro māṣakā hīne madhyame'ṣṭau ca māṣakāḥ śreṣṭhā dvādaśakāḥ proktāḥ koṣṭhaṃ vijñāya pāyayet"},{"type":"verse","number":"176","sanskrit":"स्रंसनत्वाद् गुरुत्वाद्वा गुग्गुलोः करणक्रमः","text":"sraṃsanatvād gurutvādvā gugguloḥ karaṇakramaḥ"},{"type":"verse","number":"177","sanskrit":"प्रस्थमेकं गुडूच्याश्च अर्द्धप्रस्थं च गुग्गुलोः प्रत्येकं त्रिफलायास्तु तत्प्रमाणं विनिर्दिशेत् सर्वमेकत्र सङ्कुट्य क्वाथयेन्नल्वणेऽम्भसि","text":"prasthamekaṃ guḍūcyāśca arddhaprasthaṃ ca gugguloḥ pratyekaṃ triphalāyāstu tatpramāṇaṃ vinirdiśet sarvamekatra saṅkuṭya kvāthayennalvaṇe'mbhasi"},{"type":"verse","number":"178","sanskrit":"पादशेषं परिस्राव्य कषायं ग्राहयेद्भिषक् पुनः पचेत्कषायन्तु यावत्सान्द्र त्वमागतम्","text":"pādaśeṣaṃ parisrāvya kaṣāyaṃ grāhayedbhiṣak punaḥ pacetkaṣāyantu yāvatsāndra tvamāgatam"},{"type":"verse","number":"179","sanskrit":"दन्तीव्योषविडङ्गानि गुडूची त्रिफलात्वचः ततश्चार्द्धपलं चूर्णं गृह्णीयाच्च प्रतिप्रति","text":"dantīvyoṣaviḍaṅgāni guḍūcī triphalātvacaḥ tataścārddhapalaṃ cūrṇaṃ gṛhṇīyācca pratiprati"},{"type":"verse","number":"180","sanskrit":"कर्षन्तु त्रिवृतायाश्च सर्वमेकत्र चूर्णयेत् तस्मिन्सुसिद्धं विज्ञाय कवोष्णे प्रक्षिपेद् बुधः","text":"karṣantu trivṛtāyāśca sarvamekatra cūrṇayet tasminsusiddhaṃ vijñāya kavoṣṇe prakṣiped budhaḥ"},{"type":"verse","number":"181","sanskrit":"ततश्चाग्निबलं मत्वा खादेत्कर्षप्रमाणतः वातरक्तं तथा कुष्ठं गुदजान्यग्निसादनम्","text":"tataścāgnibalaṃ matvā khādetkarṣapramāṇataḥ vātaraktaṃ tathā kuṣṭhaṃ gudajānyagnisādanam"},{"type":"verse","number":"182","sanskrit":"दुष्टव्रणं प्रमेहांश्च आमवातं भगन्दरम् नाड्याढ्यवातं श्वयथुं सर्वानेतान्व्यपोहति","text":"duṣṭavraṇaṃ pramehāṃśca āmavātaṃ bhagandaram nāḍyāḍhyavātaṃ śvayathuṃ sarvānetānvyapohati"},{"type":"verse","number":"183","sanskrit":"त्रिप्रस्थममृतायाश्च प्रस्थमेकन्तु गुग्गुलोः प्रत्येकं त्रिफलाप्रस्थं वर्षाभूप्रस्थमेव च","text":"triprasthamamṛtāyāśca prasthamekantu gugguloḥ pratyekaṃ triphalāprasthaṃ varṣābhūprasthameva ca"},{"type":"verse","number":"184","sanskrit":"सर्वमेकत्र सङ्कुट्य साधयेन्नल्वणेऽम्भसि पुनः पचेत्पादशेषं यावत्सान्द्र त्वमागतम्","text":"sarvamekatra saṅkuṭya sādhayennalvaṇe'mbhasi punaḥ pacetpādaśeṣaṃ yāvatsāndra tvamāgatam"},{"type":"verse","number":"185","sanskrit":"दन्तीचित्रकमूलानां कणाविश्व फलत्रिकम् गुडुचीत्वग्विडङ्गानां प्रत्येकार्धपलं मतम्","text":"dantīcitrakamūlānāṃ kaṇāviśva phalatrikam guḍucītvagviḍaṅgānāṃ pratyekārdhapalaṃ matam"},{"type":"verse","number":"186","sanskrit":"त्रिवृताकर्षमेकन्तु सर्वमेकत्र चूर्णयेत् सिद्धे चोष्णे क्षिपेत्तत्र अमृतागुग्गुलुं परम्","text":"trivṛtākarṣamekantu sarvamekatra cūrṇayet siddhe coṣṇe kṣipettatra amṛtāgugguluṃ param"},{"type":"verse","number":"187","sanskrit":"अतो यथाबलं खादेदम्लपित्ती विशेषतः वातरक्तं तथा कुष्ठं गुदजान्यग्निसादनम्","text":"ato yathābalaṃ khādedamlapittī viśeṣataḥ vātaraktaṃ tathā kuṣṭhaṃ gudajānyagnisādanam"},{"type":"verse","number":"188","sanskrit":"दुष्टव्रणं प्रमेहांश्च आमवातं भगन्दरम् नाड्याढ्यवातं श्वयथुं हन्यात्सर्वामयांस्तथा","text":"duṣṭavraṇaṃ pramehāṃśca āmavātaṃ bhagandaram nāḍyāḍhyavātaṃ śvayathuṃ hanyātsarvāmayāṃstathā"},{"type":"verse","number":"189","sanskrit":"अश्विभ्यां निर्मिताश्चायममृताऽख्यो हि गुग्गुलुः","text":"aśvibhyāṃ nirmitāścāyamamṛtā'khyo hi gugguluḥ"},{"type":"verse","number":"190","sanskrit":"गुडरामठशुण्ठीनां मांसकूष्माण्डयोरपि गुडूच्या गुग्गुलोश्चैव प्रस्थः षोडशभिः पलैः","text":"guḍarāmaṭhaśuṇṭhīnāṃ māṃsakūṣmāṇḍayorapi guḍūcyā gugguloścaiva prasthaḥ ṣoḍaśabhiḥ palaiḥ"},{"type":"verse","number":"191","sanskrit":"स्निग्धः काञ्चनसङ्कांशः पक्वजम्बूफलोपमः नूतनो गुग्गुलुः प्रोक्तः सुगन्धिर्यस्तु पिच्छिलः","text":"snigdhaḥ kāñcanasaṅkāṃśaḥ pakvajambūphalopamaḥ nūtano gugguluḥ proktaḥ sugandhiryastu picchilaḥ"},{"type":"verse","number":"192","sanskrit":"शुष्को दुर्गन्धिकश्चैव वर्णान्यत्वमुपागतः पुराणः स तु विज्ञेयो न स देयस्तु रोगिणे","text":"śuṣko durgandhikaścaiva varṇānyatvamupāgataḥ purāṇaḥ sa tu vijñeyo na sa deyastu rogiṇe"},{"type":"verse","number":"193","sanskrit":"कृमिरिपुदहनव्योष त्रिफलाऽमरदारुचव्यभूनिम्बाः मागधिमूलं मुस्तं शटीवचाधातुमाक्षिकञ्चैव लवणक्षारनिशायुक्कुस्तुम्बुरुगजकणाः सहातिविषाः","text":"kṛmiripudahanavyoṣa triphalā'maradārucavyabhūnimbāḥ māgadhimūlaṃ mustaṃ śaṭīvacādhātumākṣikañcaiva lavaṇakṣāraniśāyukkustumburugajakaṇāḥ sahātiviṣāḥ"},{"type":"verse","number":"194","sanskrit":"कर्षांशिकान्येव समानि कुर्यात्पलाष्टकं चाश्मजतु प्रदद्यात् निष्पत्रशुद्धस्य पुरस्य धीमान्पलद्वयं लौहरजस्तथैव","text":"karṣāṃśikānyeva samāni kuryātpalāṣṭakaṃ cāśmajatu pradadyāt niṣpatraśuddhasya purasya dhīmānpaladvayaṃ lauharajastathaiva"},{"type":"verse","number":"195","sanskrit":"सिताचतुष्कं पलमत्र वांश्या निकुम्भकुम्भत्रिसुगन्धियुक्तम् पृथक्पलं चूर्णमथावपेच्च चन्द्र्रप्रभेयं गुटिका विधेया","text":"sitācatuṣkaṃ palamatra vāṃśyā nikumbhakumbhatrisugandhiyuktam pṛthakpalaṃ cūrṇamathāvapecca candrraprabheyaṃ guṭikā vidheyā"},{"type":"verse","number":"196","sanskrit":"ज्वरातिसारग्रहणीविकारांश्चार्शांसि निर्णाशयते षडेव भगन्दरान्कामलपाण्डुरोगान्विनष्टवह्नेः कुरुते च दीप्तिम्","text":"jvarātisāragrahaṇīvikārāṃścārśāṃsi nirṇāśayate ṣaḍeva bhagandarānkāmalapāṇḍurogānvinaṣṭavahneḥ kurute ca dīptim"},{"type":"verse","number":"197","sanskrit":"हन्त्यामयान्पित्तकफानिलोत्थान्नाडीगते मर्मगते व्रणे च क्षतक्षये गृध्रसियक्ष्मरोगे मेहे गजाख्ये प्रबले प्रयोज्य","text":"hantyāmayānpittakaphānilotthānnāḍīgate marmagate vraṇe ca kṣatakṣaye gṛdhrasiyakṣmaroge mehe gajākhye prabale prayojya"},{"type":"verse","number":"198","sanskrit":"शुक्रक्षये चाश्मरिमूत्रकृच्छ्रे शुक्रप्रवाहेऽप्युदरामये च शम्भुं समभ्यर्च्य कृतप्रसादं प्राप्ता गुटी चन्द्र मसा प्रशस्ता","text":"śukrakṣaye cāśmarimūtrakṛcchre śukrapravāhe'pyudarāmaye ca śambhuṃ samabhyarcya kṛtaprasādaṃ prāptā guṭī candra masā praśastā"},{"type":"verse","number":"199","sanskrit":"न पानभोज्ये परिहारवादो न शीतवातातपमैथुनेषु भक्तस्य पूर्वं सततं प्रयोज्या तक्रानुपानाऽप्यथ मस्तुपाना","text":"na pānabhojye parihāravādo na śītavātātapamaithuneṣu bhaktasya pūrvaṃ satataṃ prayojyā takrānupānā'pyatha mastupānā"},{"type":"verse","number":"200","sanskrit":"अजारसो जाङ्गलजो रसो वा परोऽथ वा शीतजलानुपानम्","text":"ajāraso jāṅgalajo raso vā paro'tha vā śītajalānupānam"},{"type":"verse","number":"201","sanskrit":"शुक्रदोषान्निहन्त्यष्टौ प्रमेहांश्चापि विंशतिम् वलीपलितनिर्मुक्तो वृद्धोऽपि तरुणायते","text":"śukradoṣānnihantyaṣṭau pramehāṃścāpi viṃśatim valīpalitanirmukto vṛddho'pi taruṇāyate"},{"type":"verse","number":"202","sanskrit":"गिरिजतुगुग्गुलुलौहान्येकीकृत्याथ भावयेद् बहुशः क्वाथैस्तद्व्याधिहरैस्तदनु च चूर्णीकृतं मिलितम् कृमिरिप्वादिकचूर्णैर्गिरिजतुसमधान्यपटोलयूषेण","text":"girijatuguggululauhānyekīkṛtyātha bhāvayed bahuśaḥ kvāthaistadvyādhiharaistadanu ca cūrṇīkṛtaṃ militam kṛmiripvādikacūrṇairgirijatusamadhānyapaṭolayūṣeṇa"},{"type":"verse","number":"203","sanskrit":"वरमहिषलोचनोदरसन्निभवर्णस्य गुग्गुलोः प्रस्थम् प्रक्षिप्य तोयराशौ त्रिफलाञ्च यथोक्तपरिमाणम्","text":"varamahiṣalocanodarasannibhavarṇasya gugguloḥ prastham prakṣipya toyarāśau triphalāñca yathoktaparimāṇam"},{"type":"verse","number":"204","sanskrit":"द्वात्रिंशच्छिन्नरुहापलानि देयानि यत्नेन विपचेत्तदप्रमत्तो दर्व्या सङ्घट्टयेन्मुहुर्यावत्","text":"dvātriṃśacchinnaruhāpalāni deyāni yatnena vipacettadapramatto darvyā saṅghaṭṭayenmuhuryāvat"},{"type":"verse","number":"205","sanskrit":"अर्द्धक्षयितं तोयं जातं ज्वलनस्य सम्पर्कात् अवतार्य वस्त्रपूतं पुनरपि संसाधयेदयः पात्रे","text":"arddhakṣayitaṃ toyaṃ jātaṃ jvalanasya samparkāt avatārya vastrapūtaṃ punarapi saṃsādhayedayaḥ pātre"},{"type":"verse","number":"206","sanskrit":"सान्द्री भूते तस्मिन्नवतार्य हिमोपलप्रख्ये त्रिफलाचूर्णार्द्धपलं त्रिकटोश्चूर्णं षडक्षपरिमाणम्","text":"sāndrī bhūte tasminnavatārya himopalaprakhye triphalācūrṇārddhapalaṃ trikaṭoścūrṇaṃ ṣaḍakṣaparimāṇam"},{"type":"verse","number":"207","sanskrit":"कृमिरिपुचूर्णार्द्धपलं कर्षं कर्षं त्रिवृद्दन्त्योः पलमेकन्तु गुडूच्या दत्वा सञ्चूर्ण्य यत्नेन","text":"kṛmiripucūrṇārddhapalaṃ karṣaṃ karṣaṃ trivṛddantyoḥ palamekantu guḍūcyā datvā sañcūrṇya yatnena"},{"type":"verse","number":"208","sanskrit":"उपयुज्य चानुपानं यूषं क्षीरं सुगन्धि सलिलञ्च इच्छाऽहारविहारी भेषजमुपयुज्य सर्वकालमिदम्","text":"upayujya cānupānaṃ yūṣaṃ kṣīraṃ sugandhi salilañca icchā'hāravihārī bheṣajamupayujya sarvakālamidam"},{"type":"verse","number":"209","sanskrit":"तनुरोधी वातशोणितमेकद्वित्र्युल्बणं चिरोत्थमपि भग्नस्रुतपरिशुष्कं स्फुटितं दीर्णमाजानु यच्चापि","text":"tanurodhī vātaśoṇitamekadvitryulbaṇaṃ cirotthamapi bhagnasrutapariśuṣkaṃ sphuṭitaṃ dīrṇamājānu yaccāpi"},{"type":"verse","number":"210","sanskrit":"व्रणकासकुष्ठगुल्मश्वयथुं गरपाण्डुमेहांश्च नाशयत्याशु मन्दाग्निञ्च विबन्धं प्रमेहपिडकाश्च नाशयत्याशु","text":"vraṇakāsakuṣṭhagulmaśvayathuṃ garapāṇḍumehāṃśca nāśayatyāśu mandāgniñca vibandhaṃ pramehapiḍakāśca nāśayatyāśu"},{"type":"verse","number":"211","sanskrit":"सततं निषेव्यमाणः कालवशाद्धन्ति सर्वगदान् अभिभूय जरादोषं करोति कैशोरकं रूपम्","text":"satataṃ niṣevyamāṇaḥ kālavaśāddhanti sarvagadān abhibhūya jarādoṣaṃ karoti kaiśorakaṃ rūpam"},{"type":"verse","number":"212","sanskrit":"प्रत्येकं त्रिफलाप्रस्थो जलञ्चाढकमाढकम् गुडवद् गुग्गुलोः पाकः सन्धेयस्तु विशेषतः","text":"pratyekaṃ triphalāprastho jalañcāḍhakamāḍhakam guḍavad gugguloḥ pākaḥ sandheyastu viśeṣataḥ"},{"type":"verse","number":"213","sanskrit":"त्रिफलाऽतिविषादारुदार्वीमुस्तापरुषकैः खदिरासननक्ताह्वगुडूचीनृपपादपैः","text":"triphalā'tiviṣādārudārvīmustāparuṣakaiḥ khadirāsananaktāhvaguḍūcīnṛpapādapaiḥ"},{"type":"verse","number":"214","sanskrit":"भूनिम्बनिम्बकटुकाकलिङ्गकुलकैः समैः क्वाथं कृत्वा ततः पूतं शृतमष्टगुणेऽम्भसि","text":"bhūnimbanimbakaṭukākaliṅgakulakaiḥ samaiḥ kvāthaṃ kṛtvā tataḥ pūtaṃ śṛtamaṣṭaguṇe'mbhasi"},{"type":"verse","number":"215","sanskrit":"गुडूच्यास्तत्र सुकृतं चूर्णमर्द्धं तु वारिणि क्षिप्त्वा सुनूतने भाण्डे वासयेद्र जनीगतम् सोमोपेतेन पूतेन कौशिकं परिभावयेत् षड्गुडेन तु सप्ताहं शिलाजतुसमन्वितम्","text":"guḍūcyāstatra sukṛtaṃ cūrṇamarddhaṃ tu vāriṇi kṣiptvā sunūtane bhāṇḍe vāsayedra janīgatam somopetena pūtena kauśikaṃ paribhāvayet ṣaḍguḍena tu saptāhaṃ śilājatusamanvitam"},{"type":"verse","number":"216","sanskrit":"शुक्तस्य तु पलान्यष्टौ समावाप्य विचक्षणः ताप्यचूर्णं पलञ्चैकं द्वे पले मधुसर्पिषोः","text":"śuktasya tu palānyaṣṭau samāvāpya vicakṣaṇaḥ tāpyacūrṇaṃ palañcaikaṃ dve pale madhusarpiṣoḥ"},{"type":"verse","number":"217","sanskrit":"एकीकृत्य समं सर्वं लिह्यात्तु त्रिफलाऽम्बुना तनुना मुद्गयूषेण जाङ्गलानां रसेन वा","text":"ekīkṛtya samaṃ sarvaṃ lihyāttu triphalā'mbunā tanunā mudgayūṣeṇa jāṅgalānāṃ rasena vā"},{"type":"verse","number":"218","sanskrit":"जीर्णेऽजीर्णे तु भुञ्जीत पुराणं शालिषष्टिकम्","text":"jīrṇe'jīrṇe tu bhuñjīta purāṇaṃ śāliṣaṣṭikam"},{"type":"verse","number":"219","sanskrit":"यथारोगं यथासात्म्यं रसैर्यूषैश्च संस्कृतैः त्रिसप्ताहप्रयोगेण वातरक्तं सुदारुणम्","text":"yathārogaṃ yathāsātmyaṃ rasairyūṣaiśca saṃskṛtaiḥ trisaptāhaprayogeṇa vātaraktaṃ sudāruṇam"},{"type":"verse","number":"220","sanskrit":"निहन्ति वीर्यतः क्षिप्रं कुष्ठरोगान्व्रणानपि छिन्नं भिन्नञ्च सन्धत्ते त्रिफलाऽख्यो हि गुग्गुलुः","text":"nihanti vīryataḥ kṣipraṃ kuṣṭharogānvraṇānapi chinnaṃ bhinnañca sandhatte triphalā'khyo hi gugguluḥ"},{"type":"verse","number":"221","sanskrit":"पलत्रयं कषायस्य त्रिफलायाः सुचूर्णितम् सौगन्धिकं पलञ्चैकं कौशिकस्य पलत्रयम्","text":"palatrayaṃ kaṣāyasya triphalāyāḥ sucūrṇitam saugandhikaṃ palañcaikaṃ kauśikasya palatrayam"},{"type":"verse","number":"222","sanskrit":"कुडवं चित्रतैलस्य सर्वमादाय यत्नतः पाचयेत्पाकविद्वैद्यः पात्रे लोहमये दृढे","text":"kuḍavaṃ citratailasya sarvamādāya yatnataḥ pācayetpākavidvaidyaḥ pātre lohamaye dṛḍhe"},{"type":"verse","number":"223","sanskrit":"हन्ति वातं तथा पित्तं श्लेष्माणं खञ्जपङ्गुताम् श्वासं सुदुर्जयं हन्ति कासं पञ्चविधं तथा कुष्ठानिवातरक्तञ्च गुल्मशूलोदराणि च आमवातं जयत्येतदपि वैद्यविवर्जितम्","text":"hanti vātaṃ tathā pittaṃ śleṣmāṇaṃ khañjapaṅgutām śvāsaṃ sudurjayaṃ hanti kāsaṃ pañcavidhaṃ tathā kuṣṭhānivātaraktañca gulmaśūlodarāṇi ca āmavātaṃ jayatyetadapi vaidyavivarjitam"},{"type":"verse","number":"224","sanskrit":"सर्वदाऽस्योपयोगेन जरापलितनाशनम् सर्पिस्तैलरसोपेतमश्नीयाच्छालिषष्टिकम्","text":"sarvadā'syopayogena jarāpalitanāśanam sarpistailarasopetamaśnīyācchāliṣaṣṭikam"},{"type":"verse","number":"225","sanskrit":"सिंहनादइति ख्यातो रोगवारणदर्पहा वह्नेर्दीप्तिकरं पुसां भाषितो दण्डपाणिना","text":"siṃhanādaiti khyāto rogavāraṇadarpahā vahnerdīptikaraṃ pusāṃ bhāṣito daṇḍapāṇinā"},{"type":"verse","number":"226","sanskrit":"अत्राहुस्त्रिफलाक्वाथं पृथक् त्रिपलसम्मितम् किञ्चिन्निर्याति चैरण्डस्नेहे पाकोऽधिके खरः","text":"atrāhustriphalākvāthaṃ pṛthak tripalasammitam kiñcinniryāti cairaṇḍasnehe pāko'dhike kharaḥ"},{"type":"verse","number":"227","sanskrit":"अष्टौ पलान्यत्र पलङ्कषायाः प्रस्थः पृथक् शुद्धफलत्रयस्य दत्वा पचेद् द्रो णयुगे जलस्य पादावशेषं पुनरेव वैद्यः","text":"aṣṭau palānyatra palaṅkaṣāyāḥ prasthaḥ pṛthak śuddhaphalatrayasya datvā paced dro ṇayuge jalasya pādāvaśeṣaṃ punareva vaidyaḥ"},{"type":"verse","number":"228","sanskrit":"दन्तीत्रिवृत्त्र् यूषणवारुणीनां बिडङ्गमुस्तत्रिफलाऽमृतानाम् कटूग्रगन्धालुकमाणकानां सगन्धकानाञ्च सपारदानाम्","text":"dantītrivṛttr yūṣaṇavāruṇīnāṃ biḍaṅgamustatriphalā'mṛtānām kaṭūgragandhālukamāṇakānāṃ sagandhakānāñca sapāradānām"},{"type":"verse","number":"229","sanskrit":"पलार्द्धमानं प्रमितं सुचूर्णं दद्याद्विपक्वं पुनरेव तत्र फलानि सञ्चूर्ण्य च कानकानिसहस्रसङ्ख्याकलितानि पश्चात्","text":"palārddhamānaṃ pramitaṃ sucūrṇaṃ dadyādvipakvaṃ punareva tatra phalāni sañcūrṇya ca kānakānisahasrasaṅkhyākalitāni paścāt"},{"type":"verse","number":"230","sanskrit":"खादेद्धि माषद्वितयं प्रतप्तं तोयादिकं देयमतोऽनुपाने आमानिलं सन्धिगतं सशूलं शिरोगतं जानुकटिस्थितञ्च","text":"khādeddhi māṣadvitayaṃ prataptaṃ toyādikaṃ deyamato'nupāne āmānilaṃ sandhigataṃ saśūlaṃ śirogataṃ jānukaṭisthitañca"},{"type":"verse","number":"231","sanskrit":"अर्शोऽतिवृत्तिं विषमज्वरार्त्तिं प्रमेहकुष्ठानि भगन्दरञ्च हन्यान्नराणामिति सिंहनादो मेदोमरुच्छ्लेष्मगदान्पुरोऽयम्","text":"arśo'tivṛttiṃ viṣamajvarārttiṃ pramehakuṣṭhāni bhagandarañca hanyānnarāṇāmiti siṃhanādo medomarucchleṣmagadānpuro'yam"},{"type":"verse","number":"232","sanskrit":"दाहोऽत्यन्तप्रवृत्तिर्वा विकारोऽन्यो न चेद् बहुः तत्कृतस्तुतदा तत्र तक्रभक्तं हितं भवेत् उद्वर्त्तनं शीतजलस्नानञ्च शयनं तथा","text":"dāho'tyantapravṛttirvā vikāro'nyo na ced bahuḥ tatkṛtastutadā tatra takrabhaktaṃ hitaṃ bhavet udvarttanaṃ śītajalasnānañca śayanaṃ tathā"},{"type":"verse","number":"233","sanskrit":"विरेकातिशयं कुर्यात्सिंहनादो यतः सुधीः ज्ञात्वा बलं शरीरे तु दद्यादेवं न वा भिषक्","text":"virekātiśayaṃ kuryātsiṃhanādo yataḥ sudhīḥ jñātvā balaṃ śarīre tu dadyādevaṃ na vā bhiṣak"},{"type":"verse","number":"234","sanskrit":"तोयारनालगोक्षीरैः क्रमात्पक्वं विशुध्यति फलं कानकसञ्ज्ञन्तु कृत्वा चूर्णं ततः क्षिपेत्","text":"toyāranālagokṣīraiḥ kramātpakvaṃ viśudhyati phalaṃ kānakasañjñantu kṛtvā cūrṇaṃ tataḥ kṣipet"},{"type":"verse","number":"235","sanskrit":"पिण्डितां गुग्गुलोर्मानीं कटुतैले पलाष्टके प्रत्येकं त्रिफलाप्रस्थं सार्द्धद्रो णे जले पचेत्","text":"piṇḍitāṃ guggulormānīṃ kaṭutaile palāṣṭake pratyekaṃ triphalāprasthaṃ sārddhadro ṇe jale pacet"},{"type":"verse","number":"236","sanskrit":"पादशेषं सुपूतञ्च पुनरग्नावधिश्रयेत् त्रिकटुत्रिफलामुस्तविडङ्गामलकानि च","text":"pādaśeṣaṃ supūtañca punaragnāvadhiśrayet trikaṭutriphalāmustaviḍaṅgāmalakāni ca"},{"type":"verse","number":"237","sanskrit":"गुडूच्यग्नित्रिवृद्दन्ती वचासूरणमानकम् कस्तूरीरससूतांशं प्रत्येकं शुक्तिसम्मितम्","text":"guḍūcyagnitrivṛddantī vacāsūraṇamānakam kastūrīrasasūtāṃśaṃ pratyekaṃ śuktisammitam"},{"type":"verse","number":"238","sanskrit":"सहस्रं कानकफलं सिद्धे सञ्चूर्ण्य निक्षिपेत् ततो माषद्वयं जग्ध्वा पिबेत्तप्तजलादिकम्","text":"sahasraṃ kānakaphalaṃ siddhe sañcūrṇya nikṣipet tato māṣadvayaṃ jagdhvā pibettaptajalādikam"},{"type":"verse","number":"239","sanskrit":"अग्निञ्च कुरुते शीघ्रं वडवाऽनलसन्निभम् मेधावृद्धिं वयोवृद्धिं बलं सुविपुलं तथा","text":"agniñca kurute śīghraṃ vaḍavā'nalasannibham medhāvṛddhiṃ vayovṛddhiṃ balaṃ suvipulaṃ tathā"},{"type":"verse","number":"240","sanskrit":"आमवातं शिरोवातं ग्रन्थिवातं भगन्दरम् जानुजङ्घाश्रितं वातं सकटीग्रहवेदनम्","text":"āmavātaṃ śirovātaṃ granthivātaṃ bhagandaram jānujaṅghāśritaṃ vātaṃ sakaṭīgrahavedanam"},{"type":"verse","number":"241","sanskrit":"अश्मरीमूत्रकृच्छ्रे च भग्ने च तिमिरोदरे अम्लपित्तं तथा कुष्ठं प्रमेहं गुदनिर्गमम्","text":"aśmarīmūtrakṛcchre ca bhagne ca timirodare amlapittaṃ tathā kuṣṭhaṃ pramehaṃ gudanirgamam"},{"type":"verse","number":"242","sanskrit":"कासं पञ्चविधं श्वासं क्षयञ्च विषमज्वरम् प्लीहानं श्लीपदं गुल्मान्पाण्डुरोगं सकामलम्","text":"kāsaṃ pañcavidhaṃ śvāsaṃ kṣayañca viṣamajvaram plīhānaṃ ślīpadaṃ gulmānpāṇḍurogaṃ sakāmalam"},{"type":"verse","number":"243","sanskrit":"शोथान्त्रवृद्धिशूलानि गुदजानि विनाशयेत् मेदः कफामसञ्जातरोगवारणदर्पहा","text":"śothāntravṛddhiśūlāni gudajāni vināśayet medaḥ kaphāmasañjātarogavāraṇadarpahā"},{"type":"verse","number":"244","sanskrit":"सिंहनाद इति ख्यातो योगोऽयममृतोपमः भिषग्भिर्वर्जिते रोगे भाषितो दण्डपाणिना","text":"siṃhanāda iti khyāto yogo'yamamṛtopamaḥ bhiṣagbhirvarjite roge bhāṣito daṇḍapāṇinā"},{"type":"verse","number":"245","sanskrit":"शतावरी नागबला वृद्धदारकमुच्चटा पुनर्नवामृता कृष्णा वाजिगन्धा त्रिकण्टकम्","text":"śatāvarī nāgabalā vṛddhadārakamuccaṭā punarnavāmṛtā kṛṣṇā vājigandhā trikaṇṭakam"},{"type":"verse","number":"246","sanskrit":"पृथग्दशपलान्येषां श्लक्ष्णचूर्णानि कारयेत् तदर्धशर्करायुक्तं चूर्णं संमर्दयेद् बुधः","text":"pṛthagdaśapalānyeṣāṃ ślakṣṇacūrṇāni kārayet tadardhaśarkarāyuktaṃ cūrṇaṃ saṃmardayed budhaḥ"},{"type":"verse","number":"247","sanskrit":"स्थापयेत्सुदृढे भाण्डे मध्वर्द्धाढकसंयुतम् घृतप्रस्थेन वालोड्य त्रिसुगन्धपलेन च","text":"sthāpayetsudṛḍhe bhāṇḍe madhvarddhāḍhakasaṃyutam ghṛtaprasthena vāloḍya trisugandhapalena ca"},{"type":"verse","number":"248","sanskrit":"तं खादेदिष्टभक्ष्यान्नो यथावह्निबलं नरः वातरक्तं क्षयं कुष्ठं कार्श्यं पित्तास्रसम्भवम्","text":"taṃ khādediṣṭabhakṣyānno yathāvahnibalaṃ naraḥ vātaraktaṃ kṣayaṃ kuṣṭhaṃ kārśyaṃ pittāsrasambhavam"},{"type":"verse","number":"249","sanskrit":"वातपित्तकफोत्थांश्च रोगानन्यांश्च तत्कृतान् हत्वा करोति पुरुषं हत्वा सर्वामयान् द्रुतम्","text":"vātapittakaphotthāṃśca rogānanyāṃśca tatkṛtān hatvā karoti puruṣaṃ hatvā sarvāmayān drutam"},{"type":"verse","number":"250","sanskrit":"बलीपलितनिर्मुक्तं मेधास्मृतिविभूषितम् करोति पुरुषं धन्यं पञ्चवर्षशतायुषम्","text":"balīpalitanirmuktaṃ medhāsmṛtivibhūṣitam karoti puruṣaṃ dhanyaṃ pañcavarṣaśatāyuṣam"},{"type":"verse","number":"251","sanskrit":"योगसारामृतो नाम लक्ष्मीकीर्त्तिविवर्द्धनः","text":"yogasārāmṛto nāma lakṣmīkīrttivivarddhanaḥ"},{"type":"verse","number":"252","sanskrit":"व्यायामं मैथुनं कोपमुष्णाम्ललवणं रसम् दिवास्वप्नमभिष्यन्दि गुरु चान्यद्विवर्जयेत्","text":"vyāyāmaṃ maithunaṃ kopamuṣṇāmlalavaṇaṃ rasam divāsvapnamabhiṣyandi guru cānyadvivarjayet"},{"type":"verse","number":"253","sanskrit":"इत्येकोनत्रिंशोवातरक्ताधिकारः समाप्तः २९","text":"ityekonatriṃśovātaraktādhikāraḥ samāptaḥ 29"}]},{"sthana":"Уттаракханда","number":30,"lang":"sa","content":[{"type":"heading","heading":"Шула — колики и боли"},{"type":"verse","number":"1","sanskrit":"दोषैः पृथक्समस्तामद्वन्द्वैः शूलोऽष्टधा भवेत् सर्वेष्वेतेषु शूलेषु प्रायेण पवनः प्रभुः","text":"doṣaiḥ pṛthaksamastāmadvandvaiḥ śūlo'ṣṭadhā bhavet sarveṣveteṣu śūleṣu prāyeṇa pavanaḥ prabhuḥ"},{"type":"verse","number":"2","sanskrit":"व्यायामयानादतिमैथुनाच्च प्रजागराच्छीतजलातिपानात् कलायमुद्गाढकिकोरदूषादत्यर्थरुक्षाध्यशनाभिघातात्","text":"vyāyāmayānādatimaithunācca prajāgarācchītajalātipānāt kalāyamudgāḍhakikoradūṣādatyartharukṣādhyaśanābhighātāt"},{"type":"verse","number":"3","sanskrit":"कषायतिक्तातिविरुढजान्नविरुद्धवल्लूरकशुष्कशाकैः विट्छुक्रमूत्रानिलसन्निरोधाच्छोकोपवासादतिहास्यभाषात्","text":"kaṣāyatiktātiviruḍhajānnaviruddhavallūrakaśuṣkaśākaiḥ viṭchukramūtrānilasannirodhācchokopavāsādatihāsyabhāṣāt"},{"type":"verse","number":"4","sanskrit":"वायुः प्रवृद्धो जनयेद्धि शूलं हृत्पृष्ठपार्श्वत्रिकवस्तिदेशे जीर्णे प्रदोषे च घनागमे च शीते च कोपं समुपैति गाढम्","text":"vāyuḥ pravṛddho janayeddhi śūlaṃ hṛtpṛṣṭhapārśvatrikavastideśe jīrṇe pradoṣe ca ghanāgame ca śīte ca kopaṃ samupaiti gāḍham"},{"type":"verse","number":"5","sanskrit":"मुहुर्मुहुश्चोपशमप्रकोपौ विण्मूत्रसंस्तम्भनतोदभेदैः संस्वेदनाभ्यञ्जनमर्दनाद्यैःस्निग्धोष्णभोज्यैश्च शमं प्रयाति","text":"muhurmuhuścopaśamaprakopau viṇmūtrasaṃstambhanatodabhedaiḥ saṃsvedanābhyañjanamardanādyaiḥsnigdhoṣṇabhojyaiśca śamaṃ prayāti"},{"type":"verse","number":"6","sanskrit":"कफपित्तावरुद्धस्तु मारुतो रसवर्द्धितः हृदयस्थः प्रकुरुते शूलमुच्छ्वासरोधकम् सहृच्छूल इति ख्यातो रसमारुतकोपजः","text":"kaphapittāvaruddhastu māruto rasavarddhitaḥ hṛdayasthaḥ prakurute śūlamucchvāsarodhakam sahṛcchūla iti khyāto rasamārutakopajaḥ"},{"type":"verse","number":"7","sanskrit":"कफं निगृह्य पवनः सूचीभिरिव निस्तुदन् पार्श्वस्थः पार्श्वयोः शूलं कुर्यादाध्मानसंयुतम्","text":"kaphaṃ nigṛhya pavanaḥ sūcībhiriva nistudan pārśvasthaḥ pārśvayoḥ śūlaṃ kuryādādhmānasaṃyutam"},{"type":"verse","number":"8","sanskrit":"तेनोच्छ्वसिति वक्त्रेण नरोऽन्नञ्च न काङ्क्षति निद्रा ञ्च नाप्नुयादेव पार्श्वशूलः पकीर्त्तितः","text":"tenocchvasiti vaktreṇa naro'nnañca na kāṅkṣati nidrā ñca nāpnuyādeva pārśvaśūlaḥ pakīrttitaḥ"},{"type":"verse","number":"9","sanskrit":"संरोधात्कुपितोवायुर्बस्तिं संश्रित्य तिष्ठति","text":"saṃrodhātkupitovāyurbastiṃ saṃśritya tiṣṭhati"},{"type":"verse","number":"10","sanskrit":"बस्तेरध्वनि नाडीषु ततः शूलोऽस्य जायते विण्मूत्रवातसंरोधी बस्तिशूलः स उच्यते","text":"basteradhvani nāḍīṣu tataḥ śūlo'sya jāyate viṇmūtravātasaṃrodhī bastiśūlaḥ sa ucyate"},{"type":"verse","number":"11","sanskrit":"क्षारातितीक्ष्णोष्णविदाहितैलनिष्पावपिण्याककुलत्थयूषैः कट्वम्लसौवीरसुराविकारैः क्रोधानलायासरविप्रतापैः","text":"kṣārātitīkṣṇoṣṇavidāhitailaniṣpāvapiṇyākakulatthayūṣaiḥ kaṭvamlasauvīrasurāvikāraiḥ krodhānalāyāsaravipratāpaiḥ"},{"type":"verse","number":"12","sanskrit":"ग्राम्यातियोगादशनैर्विदग्धैः पित्तं प्रकुप्याथ करोति शूलम् तृण्मोहदाहार्त्तिकरं हि नाभ्यां संस्वेदमूर्च्छाभ्रमशोषयुक्तम्","text":"grāmyātiyogādaśanairvidagdhaiḥ pittaṃ prakupyātha karoti śūlam tṛṇmohadāhārttikaraṃ hi nābhyāṃ saṃsvedamūrcchābhramaśoṣayuktam"},{"type":"verse","number":"13","sanskrit":"मध्यन्दिने कुप्यति चार्द्धरात्रे निदाघकाले जलदात्यये च शीते च शीतैः समुपैति शान्तिं सुस्वादुशीतैरपि भोजनैश्च","text":"madhyandine kupyati cārddharātre nidāghakāle jaladātyaye ca śīte ca śītaiḥ samupaiti śāntiṃ susvāduśītairapi bhojanaiśca"},{"type":"verse","number":"14","sanskrit":"आनूपवारिजकिलाटपयोविकारैर्मांसेक्षुपिष्टकृशरातिलशष्कुलीभिः अन्यैर्बलासजनकैरपिहेतुभिश्च श्लेष्मा प्रकोपमुपगम्य करोतिशूलम्","text":"ānūpavārijakilāṭapayovikārairmāṃsekṣupiṣṭakṛśarātilaśaṣkulībhiḥ anyairbalāsajanakairapihetubhiśca śleṣmā prakopamupagamya karotiśūlam"},{"type":"verse","number":"15","sanskrit":"हृल्लासकाससदनारुचिसम्प्रसेकैरामाशये स्तिमितकोष्ठशिरोगुरुत्वैः भुक्ते सदैव हि रुजं कुरुतेऽतिमात्रं सूर्योदयेऽथ शिशिरे कुसुमागमे च","text":"hṛllāsakāsasadanārucisamprasekairāmāśaye stimitakoṣṭhaśirogurutvaiḥ bhukte sadaiva hi rujaṃ kurute'timātraṃ sūryodaye'tha śiśire kusumāgame ca"},{"type":"verse","number":"16","sanskrit":"द्विदोषलक्षणैरेतैर्विद्याच्छूलं द्विदोषजम्","text":"dvidoṣalakṣaṇairetairvidyācchūlaṃ dvidoṣajam"},{"type":"verse","number":"17","sanskrit":"सर्वेषु देशेषु च सर्वलिङ्गं विद्याद्भिषक्सर्वभवं हि शूलम् सुकष्टमेनं विषवज्रकल्पं विवर्जनीयं प्रवदन्ति तज्ज्ञाः","text":"sarveṣu deśeṣu ca sarvaliṅgaṃ vidyādbhiṣaksarvabhavaṃ hi śūlam sukaṣṭamenaṃ viṣavajrakalpaṃ vivarjanīyaṃ pravadanti tajjñāḥ"},{"type":"verse","number":"18","sanskrit":"आटोपहृल्लासवमीगुरुत्वस्तैमित्यकानाहकफप्रसेकैः कफस्य लिङ्गेन समानलिङ्गमामोद्भवं शूलमुदाहरन्ति","text":"āṭopahṛllāsavamīgurutvastaimityakānāhakaphaprasekaiḥ kaphasya liṅgena samānaliṅgamāmodbhavaṃ śūlamudāharanti"},{"type":"verse","number":"19","sanskrit":"वातात्मकं वस्तिगतं वदन्ति पित्तात्मकञ्चापि वदन्ति नाभ्याम् हृत्पार्श्वकुक्षौ कफसन्निविष्टं सर्वेषु देशेषु च सन्निपातात्","text":"vātātmakaṃ vastigataṃ vadanti pittātmakañcāpi vadanti nābhyām hṛtpārśvakukṣau kaphasanniviṣṭaṃ sarveṣu deśeṣu ca sannipātāt"},{"type":"verse","number":"20","sanskrit":"बस्तौ हृत्कटिपार्श्वेषु स शूलः कफवातिकः कुक्षौ हृन्नाभिमध्ये तु स शूलः कफपैत्तिकः दाहज्वरकरो घोरो विज्ञेयो वातपैत्तिकः","text":"bastau hṛtkaṭipārśveṣu sa śūlaḥ kaphavātikaḥ kukṣau hṛnnābhimadhye tu sa śūlaḥ kaphapaittikaḥ dāhajvarakaro ghoro vijñeyo vātapaittikaḥ"},{"type":"verse","number":"21","sanskrit":"अतिमात्रं यदा भुक्तं पावके मृदुतां गते स्थिरीकृतन्तु तत्कोष्ठे वायुरावृत्य तिष्ठति","text":"atimātraṃ yadā bhuktaṃ pāvake mṛdutāṃ gate sthirīkṛtantu tatkoṣṭhe vāyurāvṛtya tiṣṭhati"},{"type":"verse","number":"22","sanskrit":"यदाऽन्न न गतं पाकं तच्छूलं कुरुते भृशम् मूर्च्छाध्मानविदाहांश्च हृत्क्लेशं सविलम्बिकम्","text":"yadā'nna na gataṃ pākaṃ tacchūlaṃ kurute bhṛśam mūrcchādhmānavidāhāṃśca hṛtkleśaṃ savilambikam"},{"type":"verse","number":"23","sanskrit":"कम्पं वान्तिमतीसारं प्रमोहं जनयेदपि अविपाकोद्भवं शूलमेतमाहुर्मनीषिणः","text":"kampaṃ vāntimatīsāraṃ pramohaṃ janayedapi avipākodbhavaṃ śūlametamāhurmanīṣiṇaḥ"},{"type":"verse","number":"24","sanskrit":"वेदनातितृषा मूर्च्छा आनाहो गौरवारुची कासः श्वासो वमिर्हिक्का शूलास्योपद्र वाः स्मृताः","text":"vedanātitṛṣā mūrcchā ānāho gauravārucī kāsaḥ śvāso vamirhikkā śūlāsyopadra vāḥ smṛtāḥ"},{"type":"verse","number":"25","sanskrit":"एकदोषानुगः साध्यः कृच्छ्रसाध्यो द्विदोषजः सर्वदोषान्वितो घोरस्त्वसाध्यो भूर्युपद्र वः","text":"ekadoṣānugaḥ sādhyaḥ kṛcchrasādhyo dvidoṣajaḥ sarvadoṣānvito ghorastvasādhyo bhūryupadra vaḥ"},{"type":"verse","number":"26","sanskrit":"वेदनातितृषामूर्च्छा आनाहो गौरवं ज्वरः","text":"vedanātitṛṣāmūrcchā ānāho gauravaṃ jvaraḥ"},{"type":"verse","number":"27","sanskrit":"भ्रमो रुचिः कृशत्वञ्च बलहानिस्तथैव च उपद्र वा दशैवैते यस्य शूलेषु नास्ति सः","text":"bhramo ruciḥ kṛśatvañca balahānistathaiva ca upadra vā daśaivaite yasya śūleṣu nāsti saḥ"},{"type":"verse","number":"28","sanskrit":"स्वैर्निदानैः प्रकुपितो वातः सन्निहितो यदा कफपित्ते समावृत्य शूलकारी भवेद् बली भुक्ते जीर्यति यच्छूलं तदेव परिणामजम्","text":"svairnidānaiḥ prakupito vātaḥ sannihito yadā kaphapitte samāvṛtya śūlakārī bhaved balī bhukte jīryati yacchūlaṃ tadeva pariṇāmajam"},{"type":"verse","number":"29","sanskrit":"तस्य लक्षणमप्येतत्समासेनाभिधीयते","text":"tasya lakṣaṇamapyetatsamāsenābhidhīyate"},{"type":"verse","number":"30","sanskrit":"आध्मानाटोपविण्मूत्रविबन्धारतिवेपनैः स्निग्धोष्णोपशमप्रायं वातिकं तद्वदेद्भिषक्","text":"ādhmānāṭopaviṇmūtravibandhārativepanaiḥ snigdhoṣṇopaśamaprāyaṃ vātikaṃ tadvadedbhiṣak"},{"type":"verse","number":"31","sanskrit":"तृष्णादाहारतिस्वेदकट्वम्ललवणोत्तरम् शूलं शीतशमप्रायं पैत्तिकं लक्षयेद् बुधः","text":"tṛṣṇādāhāratisvedakaṭvamlalavaṇottaram śūlaṃ śītaśamaprāyaṃ paittikaṃ lakṣayed budhaḥ"},{"type":"verse","number":"32","sanskrit":"छर्दिहृल्लाससंमोहस्वल्परुग्दीर्घसन्तति कटुतिक्तोपशान्तौ च विज्ञेयञ्च कफात्मकम्","text":"chardihṛllāsasaṃmohasvalparugdīrghasantati kaṭutiktopaśāntau ca vijñeyañca kaphātmakam"},{"type":"verse","number":"33","sanskrit":"संसृष्टलक्षणं बुद्ध्वा द्विदोषं परिकल्पयेत् त्रिदोषजमसाध्यं स्यात्क्षीणमांसबलानलम्","text":"saṃsṛṣṭalakṣaṇaṃ buddhvā dvidoṣaṃ parikalpayet tridoṣajamasādhyaṃ syātkṣīṇamāṃsabalānalam"},{"type":"verse","number":"34","sanskrit":"जीर्णे जीर्यति चाप्यन्ने यच्छूलमुपजायते पथ्यापथ्यप्रयोगेण भोजनाभोजनेन वा न शमं याति नियमात्सोऽन्नद्र व उदाहृतः","text":"jīrṇe jīryati cāpyanne yacchūlamupajāyate pathyāpathyaprayogeṇa bhojanābhojanena vā na śamaṃ yāti niyamātso'nnadra va udāhṛtaḥ"},{"type":"verse","number":"35","sanskrit":"वमनं लङ्घनं स्वेदः पाचनं फलवर्त्तयः क्षाराश्चूर्णानि गुटिकाः शस्यन्ते शूलशान्तये","text":"vamanaṃ laṅghanaṃ svedaḥ pācanaṃ phalavarttayaḥ kṣārāścūrṇāni guṭikāḥ śasyante śūlaśāntaye"},{"type":"verse","number":"36","sanskrit":"विज्ञाय वातशूलन्तु स्नेहस्वेदैरुपाचरेत् स्वल्पशूलाकुलस्य स्यात्स्वेद एव सुखावहः","text":"vijñāya vātaśūlantu snehasvedairupācaret svalpaśūlākulasya syātsveda eva sukhāvahaḥ"},{"type":"verse","number":"37","sanskrit":"मृत्तिकां सजलां पाकाद्घनीभूतां पटे क्षिपेत् कृत्वा तत्पोट्टलद्यं शूली यथास्वेदं विधारयेत्","text":"mṛttikāṃ sajalāṃ pākādghanībhūtāṃ paṭe kṣipet kṛtvā tatpoṭṭaladyaṃ śūlī yathāsvedaṃ vidhārayet"},{"type":"verse","number":"38","sanskrit":"कार्पासास्थिकुलत्थ कैस्तिलयवैरेरण्डमूलातसी वर्षाभूशणबीजकाञ्जिकयुतैरेकीकृतैर्वा पृथक्","text":"kārpāsāsthikulattha kaistilayavaireraṇḍamūlātasī varṣābhūśaṇabījakāñjikayutairekīkṛtairvā pṛthak"},{"type":"verse","number":"39","sanskrit":"स्वेदः स्यादथ कूर्परोदरशिरः स्फिग्जानुपादाङ्गुली गुल्फस्कन्धकटीरुजो विजयते निःशेषवातार्त्तिहा ३८ तिलैश्च गुटिकां कृत्वा भ्रामयेज्जठरोपरि","text":"svedaḥ syādatha kūrparodaraśiraḥ sphigjānupādāṅgulī gulphaskandhakaṭīrujo vijayate niḥśeṣavātārttihā 38 tilaiśca guṭikāṃ kṛtvā bhrāmayejjaṭharopari"},{"type":"verse","number":"40","sanskrit":"शूलं सुदुस्तरं तेन शान्तिं गच्छति सत्वरम् नाभिलेपाज्जयेच्छूलं मदनं काञ्जिकान्वितम्","text":"śūlaṃ sudustaraṃ tena śāntiṃ gacchati satvaram nābhilepājjayecchūlaṃ madanaṃ kāñjikānvitam"},{"type":"verse","number":"41","sanskrit":"विश्वमेरण्डजं मूलं क्वाथयित्वा जलं पिबेत् हिङ्गुसौवर्चलोपेतं सद्यः शूलनिवारणम्","text":"viśvameraṇḍajaṃ mūlaṃ kvāthayitvā jalaṃ pibet hiṅgusauvarcalopetaṃ sadyaḥ śūlanivāraṇam"},{"type":"verse","number":"42","sanskrit":"पुंसः शूलाभिपन्नस्य स्वेद एव सुखावहः पायसैः कृशरैः पिण्डैः स्निग्धैर्वा पिशितोत्करैः","text":"puṃsaḥ śūlābhipannasya sveda eva sukhāvahaḥ pāyasaiḥ kṛśaraiḥ piṇḍaiḥ snigdhairvā piśitotkaraiḥ"},{"type":"verse","number":"43","sanskrit":"वातात्मकं हन्त्यचिरेण शूलं स्नेहेन युक्तस्तु कुलत्थयूषः ससैन्धवव्योषयुतः सलावः सहिङ्गुसौवर्चलदाडिमाढ्यः","text":"vātātmakaṃ hantyacireṇa śūlaṃ snehena yuktastu kulatthayūṣaḥ sasaindhavavyoṣayutaḥ salāvaḥ sahiṅgusauvarcaladāḍimāḍhyaḥ"},{"type":"verse","number":"44","sanskrit":"बलापुनर्नवैरण्ड बृहतीद्बयगोक्षुरैः सहिङ्गुलवणोपेतं सद्यो वातरुजापहम्","text":"balāpunarnavairaṇḍa bṛhatīdbayagokṣuraiḥ sahiṅgulavaṇopetaṃ sadyo vātarujāpaham"},{"type":"verse","number":"45","sanskrit":"तुम्बुरुण्यभया हिङ्गु पौष्करं लवणत्रयम् पिबेदुष्णामबुनां वापि शूलगुल्मापतन्त्रकी","text":"tumburuṇyabhayā hiṅgu pauṣkaraṃ lavaṇatrayam pibeduṣṇāmabunāṃ vāpi śūlagulmāpatantrakī"},{"type":"verse","number":"46","sanskrit":"यवानीहिङ्गुसिन्धूत्थ क्षारसौवर्चलाभयाः सुरामण्डेन पातव्या वातशूलनिषूदनाः","text":"yavānīhiṅgusindhūttha kṣārasauvarcalābhayāḥ surāmaṇḍena pātavyā vātaśūlaniṣūdanāḥ"},{"type":"verse","number":"47","sanskrit":"सौवर्चलाम्लिकाजा जीमरिचैर्द्विगुणोत्तरैः मातुलुङ्गरसैः पिष्ट्वा गुटिका वातशूलनुत्","text":"sauvarcalāmlikājā jīmaricairdviguṇottaraiḥ mātuluṅgarasaiḥ piṣṭvā guṭikā vātaśūlanut"},{"type":"verse","number":"48","sanskrit":"बीजपूरकमूलं च घृतेन सह पाययेत् जयेद्वातभवं शूलं कर्षमेकं प्रमाणतः","text":"bījapūrakamūlaṃ ca ghṛtena saha pāyayet jayedvātabhavaṃ śūlaṃ karṣamekaṃ pramāṇataḥ"},{"type":"verse","number":"49","sanskrit":"गुडः शालिर्यवक्षारः सर्पिष्पानं विरेचनम् जाङ्गलानि च मांसानि भेषजं पित्तशूलिनाम्","text":"guḍaḥ śāliryavakṣāraḥ sarpiṣpānaṃ virecanam jāṅgalāni ca māṃsāni bheṣajaṃ pittaśūlinām"},{"type":"verse","number":"50","sanskrit":"मणीरजतताम्राणां भाजनानि गुरूणि च तोयेन परिपूर्णानि शूलस्योपरि धारयेत्","text":"maṇīrajatatāmrāṇāṃ bhājanāni gurūṇi ca toyena paripūrṇāni śūlasyopari dhārayet"},{"type":"verse","number":"51","sanskrit":"विरेचनं पित्तहरं प्रशस्तं रसाश्च शस्ताः शशलावकानाम् सगुडां घृतसंयुक्तां भक्षयेद्वा हरीतकीम् प्रलिह्याच्छूलशान्त्यर्थं धात्रीचूर्णं समाक्षिकम्","text":"virecanaṃ pittaharaṃ praśastaṃ rasāśca śastāḥ śaśalāvakānām saguḍāṃ ghṛtasaṃyuktāṃ bhakṣayedvā harītakīm pralihyācchūlaśāntyarthaṃ dhātrīcūrṇaṃ samākṣikam"},{"type":"verse","number":"52","sanskrit":"शाल्यन्नं जाङ्गलं मांसमरिष्टं कटुकंरसम् मधुना जीर्णगोधूमं कफशूले प्रयोजयेत्","text":"śālyannaṃ jāṅgalaṃ māṃsamariṣṭaṃ kaṭukaṃrasam madhunā jīrṇagodhūmaṃ kaphaśūle prayojayet"},{"type":"verse","number":"53","sanskrit":"लवणत्रयसंयुक्तं पञ्चकोलं सरामठम् सुखोष्णेनाम्बुना पीतं कफशूलं प्रणाशयेत्","text":"lavaṇatrayasaṃyuktaṃ pañcakolaṃ sarāmaṭham sukhoṣṇenāmbunā pītaṃ kaphaśūlaṃ praṇāśayet"},{"type":"verse","number":"54","sanskrit":"आमशूले क्रिया कार्या कफशूलप्रणाशिनी सेव्यमामहरं सर्वमग्नेर्मन्दस्य वर्द्धनम्","text":"āmaśūle kriyā kāryā kaphaśūlapraṇāśinī sevyamāmaharaṃ sarvamagnermandasya varddhanam"},{"type":"verse","number":"55","sanskrit":"तीक्ष्णायाश्चूर्णसंयुक्तं त्रिफलाचूर्णमुत्तमम् प्रयोज्यं मधुसर्पिभ्यां सर्वशूलनिवारणम्","text":"tīkṣṇāyāścūrṇasaṃyuktaṃ triphalācūrṇamuttamam prayojyaṃ madhusarpibhyāṃ sarvaśūlanivāraṇam"},{"type":"verse","number":"56","sanskrit":"दारुहैमवतीकुष्ठशताह्वाहिङ्गुसैन्धवैः अम्लपिष्टैः सुखोष्णैश्च लिम्पेच्छूलयुतोदरम्","text":"dāruhaimavatīkuṣṭhaśatāhvāhiṅgusaindhavaiḥ amlapiṣṭaiḥ sukhoṣṇaiśca limpecchūlayutodaram"},{"type":"verse","number":"57","sanskrit":"मूलं बैल्वं तथैरण्डं चित्रकं विश्वभेषजम् हिङ्गुसैन्धवसंयुक्तं सद्यः शूलनिवारणम्","text":"mūlaṃ bailvaṃ tathairaṇḍaṃ citrakaṃ viśvabheṣajam hiṅgusaindhavasaṃyuktaṃ sadyaḥ śūlanivāraṇam"},{"type":"verse","number":"58","sanskrit":"कूष्माण्डं तनु कृत्वा तु क्षिप्त्वा घर्मे विशोषयेत् स्थाल्यां निक्षिप्य तत्सर्वं पिधानेन पिधाय च","text":"kūṣmāṇḍaṃ tanu kṛtvā tu kṣiptvā gharme viśoṣayet sthālyāṃ nikṣipya tatsarvaṃ pidhānena pidhāya ca"},{"type":"verse","number":"59","sanskrit":"चुल्ल्यां निवेश्य वह्निञ्च ज्वालयेत्कुशलो जनः यथा तन्न भवेद्भस्म किन्त्वङ्गारो दृढो भवेत्","text":"cullyāṃ niveśya vahniñca jvālayetkuśalo janaḥ yathā tanna bhavedbhasma kintvaṅgāro dṛḍho bhavet"},{"type":"verse","number":"60","sanskrit":"तदा निर्वापयेच्छीतं सर्वथा चूर्णितं तु तत् माषद्वयमितं तावच्छुण्ठीचूर्णेन मिश्रितम्","text":"tadā nirvāpayecchītaṃ sarvathā cūrṇitaṃ tu tat māṣadvayamitaṃ tāvacchuṇṭhīcūrṇena miśritam"},{"type":"verse","number":"61","sanskrit":"जलेन भक्षयेन्नित्यं महाशूलाकुलो नरः असाध्यमपि यच्छूलं तदप्येतेन शाम्यति","text":"jalena bhakṣayennityaṃ mahāśūlākulo naraḥ asādhyamapi yacchūlaṃ tadapyetena śāmyati"},{"type":"verse","number":"62","sanskrit":"लङ्घनं प्रथमं कुर्याद्वमनं सविरेचनम् पक्तिशूलोपशान्त्यर्थं तत्र वान्तेर्विधिर्यथा","text":"laṅghanaṃ prathamaṃ kuryādvamanaṃ savirecanam paktiśūlopaśāntyarthaṃ tatra vāntervidhiryathā"},{"type":"verse","number":"63","sanskrit":"पीत्वा तु क्षीरमाकण्ठं मदनक्वाथसंयुतम् कान्तारकस्य पौण्ड्रस्य कोशकारस्य वा रसम्","text":"pītvā tu kṣīramākaṇṭhaṃ madanakvāthasaṃyutam kāntārakasya pauṇḍrasya kośakārasya vā rasam"},{"type":"verse","number":"64","sanskrit":"कषायो वाऽथ निम्बस्य कटुतुम्बीरसोऽथवा यथाविधि वमेद्धीमान्पक्तिशूलार्दितो जनः","text":"kaṣāyo vā'tha nimbasya kaṭutumbīraso'thavā yathāvidhi vameddhīmānpaktiśūlārdito janaḥ"},{"type":"verse","number":"65","sanskrit":"त्रिवृता च तथा दन्त्या तैलेनैरण्डजेन वा दत्तं विरेचनं सद्यः पक्तिशूलनिवारणम्","text":"trivṛtā ca tathā dantyā tailenairaṇḍajena vā dattaṃ virecanaṃ sadyaḥ paktiśūlanivāraṇam"},{"type":"verse","number":"66","sanskrit":"विडङ्गतण्डुलव्योषत्रिवृद्दन्ती सचित्रका सर्वाण्येतानि संहृत्य सूक्ष्मचूर्णानि कारयेत्","text":"viḍaṅgataṇḍulavyoṣatrivṛddantī sacitrakā sarvāṇyetāni saṃhṛtya sūkṣmacūrṇāni kārayet"},{"type":"verse","number":"67","sanskrit":"गुडेन मोदकान्कृत्वा खादेदुष्णेन वारिणा जयेत्त्रिदोषजं शूलं परिणामसमुद्भवम्","text":"guḍena modakānkṛtvā khādeduṣṇena vāriṇā jayettridoṣajaṃ śūlaṃ pariṇāmasamudbhavam"},{"type":"verse","number":"68","sanskrit":"नागरतिलगुडकल्कं पयसा सम्पिष्य यः पुमांल्लिह्यात् उग्रं परिणतिशूलं नश्येत्तस्य त्रिरात्रेण","text":"nāgaratilaguḍakalkaṃ payasā sampiṣya yaḥ pumāṃllihyāt ugraṃ pariṇatiśūlaṃ naśyettasya trirātreṇa"},{"type":"verse","number":"69","sanskrit":"पीतं शम्बूकजं भस्म जलेनोष्णेन तत्क्षणात् पक्तिजं नाशयत्येव शूलं विष्णुरिवासुरान्","text":"pītaṃ śambūkajaṃ bhasma jalenoṣṇena tatkṣaṇāt paktijaṃ nāśayatyeva śūlaṃ viṣṇurivāsurān"},{"type":"verse","number":"70","sanskrit":"लौहपथ्याकणाशुण्ठीचूर्णं समधुसर्पिषा विलिहन्विनिहन्त्येव शूलं हि परिणामजम्","text":"lauhapathyākaṇāśuṇṭhīcūrṇaṃ samadhusarpiṣā vilihanvinihantyeva śūlaṃ hi pariṇāmajam"},{"type":"verse","number":"71","sanskrit":"नारिकेलं सतोयं च लवणेन सुपूरितम् मृदाऽववेष्टितं शुष्कं पक्वं गोमयवह्निना","text":"nārikelaṃ satoyaṃ ca lavaṇena supūritam mṛdā'vaveṣṭitaṃ śuṣkaṃ pakvaṃ gomayavahninā"},{"type":"verse","number":"72","sanskrit":"पिप्पल्या भक्षितं हन्ति शूलं हि परिणामजम् वातिकं पैत्तिकञ्चापि श्लैष्मिकं सान्निपातिकम्","text":"pippalyā bhakṣitaṃ hanti śūlaṃ hi pariṇāmajam vātikaṃ paittikañcāpi ślaiṣmikaṃ sānnipātikam"},{"type":"verse","number":"73","sanskrit":"अन्नद्र वाख्ये शूले तु न तावत्स्वास्थ्यमश्नुते यावत्कटुकपित्ताम्लमन्नं न च्छर्दयेद् द्र वम्","text":"annadra vākhye śūle tu na tāvatsvāsthyamaśnute yāvatkaṭukapittāmlamannaṃ na cchardayed dra vam"},{"type":"verse","number":"74","sanskrit":"जातमात्रे जरत्पित्ते शूलमाशु विनाशयेत् पित्तान्तं वमनं कृत्वा कफान्तञ्च विरेचनम्","text":"jātamātre jaratpitte śūlamāśu vināśayet pittāntaṃ vamanaṃ kṛtvā kaphāntañca virecanam"},{"type":"verse","number":"75","sanskrit":"अन्नद्र वे च तत्कार्यं जरत्पित्ते यदीरितम् जरत्पित्तेऽपि तत्पथ्यं प्रोक्तमन्नद्र वे तु यत्","text":"annadra ve ca tatkāryaṃ jaratpitte yadīritam jaratpitte'pi tatpathyaṃ proktamannadra ve tu yat"},{"type":"verse","number":"76","sanskrit":"आमपक्वाशये शुद्धे गच्छेदन्नद्र वः शमम्","text":"āmapakvāśaye śuddhe gacchedannadra vaḥ śamam"},{"type":"verse","number":"77","sanskrit":"माषेण्डरीं सलवणां सुस्विन्नां तैलपाचिताम् तादृशीं सर्पिषा खादेदन्नद्र वनिपीडितः","text":"māṣeṇḍarīṃ salavaṇāṃ susvinnāṃ tailapācitām tādṛśīṃ sarpiṣā khādedannadra vanipīḍitaḥ"},{"type":"verse","number":"78","sanskrit":"धात्रीफलभवं चूर्णमयश्चूर्णसमन्वितम् यष्टीचूर्णेन वा युक्तं लिह्यात्क्षौद्रे ण तद्गदे","text":"dhātrīphalabhavaṃ cūrṇamayaścūrṇasamanvitam yaṣṭīcūrṇena vā yuktaṃ lihyātkṣaudre ṇa tadgade"},{"type":"verse","number":"79","sanskrit":"श्यामाकतण्डुलैः सिद्धं सिद्धं कोद्र वतण्डुलैः प्रियङ्गुतण्डुलैः सिद्धं पायसं सहितं हितम्","text":"śyāmākataṇḍulaiḥ siddhaṃ siddhaṃ kodra vataṇḍulaiḥ priyaṅgutaṇḍulaiḥ siddhaṃ pāyasaṃ sahitaṃ hitam"},{"type":"verse","number":"80","sanskrit":"गौडिकं शौरणं कन्दं कूष्माण्डमपि भक्षयेत् कलाययवसक्तून्वा सक्तून्वा लाजसम्भवान्","text":"gauḍikaṃ śauraṇaṃ kandaṃ kūṣmāṇḍamapi bhakṣayet kalāyayavasaktūnvā saktūnvā lājasambhavān"},{"type":"verse","number":"81","sanskrit":"गोधूममण्डकं तत्र सर्पिषा गुडसंयुतम् ससितं शीतदुग्धेनं मृदितं क्वथितं हितम्","text":"godhūmamaṇḍakaṃ tatra sarpiṣā guḍasaṃyutam sasitaṃ śītadugdhenaṃ mṛditaṃ kvathitaṃ hitam"},{"type":"verse","number":"82","sanskrit":"अन्नद्र वो दुश्चिकित्स्यो दुर्विज्ञेयो महागदः तस्मात्तस्य प्रशमने परं यत्नं समाचरेत्","text":"annadra vo duścikitsyo durvijñeyo mahāgadaḥ tasmāttasya praśamane paraṃ yatnaṃ samācaret"},{"type":"verse","number":"83","sanskrit":"अन्नद्र वे जरत्पित्ते वह्निर्मन्दो भवेद्यतः तस्मादत्रान्नपानानि मात्राहीनानि कारयेत्","text":"annadra ve jaratpitte vahnirmando bhavedyataḥ tasmādatrānnapānāni mātrāhīnāni kārayet"},{"type":"verse","number":"84","sanskrit":"कलाययवगोधूमाः श्यामाकाः कोरदूषकाः राजमाषाश्च माषाश्च कुलत्थाः कङ्गुशालयः","text":"kalāyayavagodhūmāḥ śyāmākāḥ koradūṣakāḥ rājamāṣāśca māṣāśca kulatthāḥ kaṅguśālayaḥ"},{"type":"verse","number":"85","sanskrit":"दधिलुप्तरसं क्षीरं सर्पिर्गव्यं समाहितम् वास्तूकं कारवेल्ली च कर्कोटकफलानिच","text":"dadhiluptarasaṃ kṣīraṃ sarpirgavyaṃ samāhitam vāstūkaṃ kāravellī ca karkoṭakaphalānica"},{"type":"verse","number":"86","sanskrit":"बर्हिणो हरिणा मत्स्या रोहिताद्याः कपिञ्जलाः एतस्मिन्नामये शस्ता मता मुनिचिकित्सकैः","text":"barhiṇo hariṇā matsyā rohitādyāḥ kapiñjalāḥ etasminnāmaye śastā matā municikitsakaiḥ"},{"type":"verse","number":"87","sanskrit":"गुडामलकपथ्यानां चूर्णं प्रत्येकशः पलम् त्रिपलं लोहकिट्टस्य तत्सर्वं मधुसर्पिषा","text":"guḍāmalakapathyānāṃ cūrṇaṃ pratyekaśaḥ palam tripalaṃ lohakiṭṭasya tatsarvaṃ madhusarpiṣā"},{"type":"verse","number":"88","sanskrit":"समालोड्य समश्नीयादक्षमात्रप्रमाणतः आदिमध्यावसानेषु भोजनस्य निहन्ति तत्","text":"samāloḍya samaśnīyādakṣamātrapramāṇataḥ ādimadhyāvasāneṣu bhojanasya nihanti tat"},{"type":"verse","number":"89","sanskrit":"अन्नद्र वं जरत्पित्तमम्लपित्तं सुदारुणम् परिणामसमुत्थञ्च शूलं संवत्सरोत्थितम्","text":"annadra vaṃ jaratpittamamlapittaṃ sudāruṇam pariṇāmasamutthañca śūlaṃ saṃvatsarotthitam"},{"type":"verse","number":"90","sanskrit":"व्यायामं मैथुनं मद्यं लवणं कटुकं रसम् वेगरोधं शुचं क्रोधं द्विदलं शूलवांस्त्यजेत्","text":"vyāyāmaṃ maithunaṃ madyaṃ lavaṇaṃ kaṭukaṃ rasam vegarodhaṃ śucaṃ krodhaṃ dvidalaṃ śūlavāṃstyajet"},{"type":"verse","number":"91","sanskrit":"इति त्रिंशः शूलाधिकारोऽथवा शूलपरिणामशूलान्नद्र वजरत्पित्ताधिकारः समाप्तः ३०","text":"iti triṃśaḥ śūlādhikāro'thavā śūlapariṇāmaśūlānnadra vajaratpittādhikāraḥ samāptaḥ 30"}]},{"sthana":"Уттаракханда","number":31,"lang":"sa","content":[{"type":"heading","heading":"Удавартта — метеоризм и запор"},{"type":"verse","number":"1","sanskrit":"वातविण्मूत्रजृम्भाऽश्रुक्षवोद्गारवमीन्द्रि यैः क्षुत्तृष्णोच्छ्वासनिद्रा णां धृत्योदावर्त्तसम्भवः","text":"vātaviṇmūtrajṛmbhā'śrukṣavodgāravamīndri yaiḥ kṣuttṛṣṇocchvāsanidrā ṇāṃ dhṛtyodāvarttasambhavaḥ"},{"type":"verse","number":"2","sanskrit":"यथोर्ध्वं जायते वायोरावर्त्तः स चिकित्सकैः उदावर्त्त इति प्रोक्तो व्याधिस्तत्रानिलः प्रभुः","text":"yathordhvaṃ jāyate vāyorāvarttaḥ sa cikitsakaiḥ udāvartta iti prokto vyādhistatrānilaḥ prabhuḥ"},{"type":"verse","number":"3","sanskrit":"वातमूत्रपुरीषाणां सङ्गो ध्मानं क्लमो रुजा जठरे वातजाश्चान्ये रोगाः स्युर्वातनिग्रहात्","text":"vātamūtrapurīṣāṇāṃ saṅgo dhmānaṃ klamo rujā jaṭhare vātajāścānye rogāḥ syurvātanigrahāt"},{"type":"verse","number":"4","sanskrit":"आटोपशूलौ परिकर्त्तिका च सङ्गः पुरीषस्य तथोर्ध्ववातः पुरीषमास्यादथवा निरेति पुरीषवेगेऽभिहते नरस्य","text":"āṭopaśūlau parikarttikā ca saṅgaḥ purīṣasya tathordhvavātaḥ purīṣamāsyādathavā nireti purīṣavege'bhihate narasya"},{"type":"verse","number":"5","sanskrit":"वस्तिमेहनयोः शूलं मूत्रकृच्छ्रं शिरोरुजा विनामो वङ्क्षणानाहः स्याल्लिङ्गं मूत्रनिग्रहे","text":"vastimehanayoḥ śūlaṃ mūtrakṛcchraṃ śirorujā vināmo vaṅkṣaṇānāhaḥ syālliṅgaṃ mūtranigrahe"},{"type":"verse","number":"6","sanskrit":"मन्यागलस्तम्भशिरोविकारा जृम्भोपघातात्पवनात्मकाः स्युः तथाऽक्षिनासावदनामयाश्च भवन्ति तीव्राः सह कर्णरोगैः","text":"manyāgalastambhaśirovikārā jṛmbhopaghātātpavanātmakāḥ syuḥ tathā'kṣināsāvadanāmayāśca bhavanti tīvrāḥ saha karṇarogaiḥ"},{"type":"verse","number":"7","sanskrit":"आनन्दजं वाप्यथ शोकजंवा नेत्रोदकं प्राप्तममुञ्चतो हि शिरो गुरुत्वं न्यनामयाश्च भवन्ति तीव्राः सह पीनसेन","text":"ānandajaṃ vāpyatha śokajaṃvā netrodakaṃ prāptamamuñcato hi śiro gurutvaṃ nyanāmayāśca bhavanti tīvrāḥ saha pīnasena"},{"type":"verse","number":"8","sanskrit":"मन्यास्तम्भः शिरः शूलमर्दितार्द्धावभेदकौ इन्द्रि याणाञ्च दौर्बल्यं क्षवथोः स्याद्विधारणात्","text":"manyāstambhaḥ śiraḥ śūlamarditārddhāvabhedakau indri yāṇāñca daurbalyaṃ kṣavathoḥ syādvidhāraṇāt"},{"type":"verse","number":"9","sanskrit":"कण्ठास्यपूर्णत्वमतीव तोदः कूजश्च वायोरथ वाऽप्रवृत्तिः उद्गारवेगेऽभिहते भवन्ति जन्तोर्विकाराः पवनप्रसूताः","text":"kaṇṭhāsyapūrṇatvamatīva todaḥ kūjaśca vāyoratha vā'pravṛttiḥ udgāravege'bhihate bhavanti jantorvikārāḥ pavanaprasūtāḥ"},{"type":"verse","number":"10","sanskrit":"कण्डूकोठारुचिव्यङ्गशोथपाण्ड्वामयज्वराः कुष्ठहृल्लासवीसर्पाश्छर्दिनिग्रहजा गदाः","text":"kaṇḍūkoṭhārucivyaṅgaśothapāṇḍvāmayajvarāḥ kuṣṭhahṛllāsavīsarpāśchardinigrahajā gadāḥ"},{"type":"verse","number":"11","sanskrit":"मूत्राशये वै गुदमुष्कयोश्च शोथो रुजा मूत्रविनिग्रहश्च शुक्राश्मरी तत्स्रवणं भवेच्च ते ते विकारा विहते तु शुक्रे","text":"mūtrāśaye vai gudamuṣkayośca śotho rujā mūtravinigrahaśca śukrāśmarī tatsravaṇaṃ bhavecca te te vikārā vihate tu śukre"},{"type":"verse","number":"12","sanskrit":"तन्द्रा ऽङ्गमर्दावरुचिः श्रमश्च क्षुधाविघातात्कृशता च दृष्टेः","text":"tandrā 'ṅgamardāvaruciḥ śramaśca kṣudhāvighātātkṛśatā ca dṛṣṭeḥ"},{"type":"verse","number":"13","sanskrit":"कण्ठास्यशोषः श्रवणावरोधस्तृष्णाविघाताद् धृदये व्यथा च","text":"kaṇṭhāsyaśoṣaḥ śravaṇāvarodhastṛṣṇāvighātād dhṛdaye vyathā ca"},{"type":"verse","number":"14","sanskrit":"श्रान्तस्य निश्वासविनिग्रहेण हृद्रो गमोहावथवाऽपि गुल्मः","text":"śrāntasya niśvāsavinigraheṇa hṛdro gamohāvathavā'pi gulmaḥ"},{"type":"verse","number":"15","sanskrit":"जृम्भाऽङ्गमर्दाक्षिशिरोऽतिजाड्यं निद्रा विघातादथ वाऽपि तन्द्रा","text":"jṛmbhā'ṅgamardākṣiśiro'tijāḍyaṃ nidrā vighātādatha vā'pi tandrā"},{"type":"verse","number":"16","sanskrit":"वायुः कोष्ठानुगो रूक्षैः कषायकटुतिक्तकैः भोजनैः कुपितः सद्य उदावर्त्तं करोति च","text":"vāyuḥ koṣṭhānugo rūkṣaiḥ kaṣāyakaṭutiktakaiḥ bhojanaiḥ kupitaḥ sadya udāvarttaṃ karoti ca"},{"type":"verse","number":"17","sanskrit":"वातमूत्रपुरीषाश्रुकफमेदोवहानि वै स्रोतांस्युदावर्त्तयति पुरीषं न प्रवर्त्तयेत्","text":"vātamūtrapurīṣāśrukaphamedovahāni vai srotāṃsyudāvarttayati purīṣaṃ na pravarttayet"},{"type":"verse","number":"18","sanskrit":"ततो हृद्वस्तिशूलार्त्तो हृल्लासारतिपीडितः वातमूत्रपुरीषाणि कृच्छ्रेण लभते नरः","text":"tato hṛdvastiśūlārtto hṛllāsāratipīḍitaḥ vātamūtrapurīṣāṇi kṛcchreṇa labhate naraḥ"},{"type":"verse","number":"19","sanskrit":"श्वासकासप्रतिश्यायदाह मोहतृषाज्वरान् वमिहिक्काशिरोरोग मनः श्रवणविभ्रमान् बहूनन्यांश्च लभते विकारान्वातकोपजान्","text":"śvāsakāsapratiśyāyadāha mohatṛṣājvarān vamihikkāśiroroga manaḥ śravaṇavibhramān bahūnanyāṃśca labhate vikārānvātakopajān"},{"type":"verse","number":"20","sanskrit":"तृष्णाच्छर्दिपरिक्लिष्टं क्षीणं शूकैरुपद्रुतम् शकृद् वमन्तं मतिमानुदावर्त्तिनमुत्सृजेत्","text":"tṛṣṇācchardiparikliṣṭaṃ kṣīṇaṃ śūkairupadrutam śakṛd vamantaṃ matimānudāvarttinamutsṛjet"},{"type":"verse","number":"21","sanskrit":"आमं शकृद्वा निचितं क्रमेण भूयो विबद्धं विगुणानिलेन प्रवर्त्तमानं न यथास्वमेनं विकारमानाहमुदाहरन्ति","text":"āmaṃ śakṛdvā nicitaṃ krameṇa bhūyo vibaddhaṃ viguṇānilena pravarttamānaṃ na yathāsvamenaṃ vikāramānāhamudāharanti"},{"type":"verse","number":"22","sanskrit":"तस्मिन्भवन्त्यामसमुद्भवे तु तृष्णाप्रतिश्यायशिरोविदाहाः आमाशये शूलमथो गुरुत्वं हृत्स्तम्भ उद्गारविघातनञ्च","text":"tasminbhavantyāmasamudbhave tu tṛṣṇāpratiśyāyaśirovidāhāḥ āmāśaye śūlamatho gurutvaṃ hṛtstambha udgāravighātanañca"},{"type":"verse","number":"23","sanskrit":"स्तम्भः कटीपृष्ठपुरीषमूत्रे शूलोऽथ मूर्च्छा शकृतो वमिश्च श्वासश्च पक्वाशयजे भवन्ति तथाऽलसोक्तानि च लक्षणानि","text":"stambhaḥ kaṭīpṛṣṭhapurīṣamūtre śūlo'tha mūrcchā śakṛto vamiśca śvāsaśca pakvāśayaje bhavanti tathā'lasoktāni ca lakṣaṇāni"},{"type":"verse","number":"24","sanskrit":"अधोवातनिरोधोत्थे उदावर्त्ते हितं मतम् स्नेहपानं तथा स्वेदो वर्त्तिर्वस्तिर्हितो मतः","text":"adhovātanirodhotthe udāvartte hitaṃ matam snehapānaṃ tathā svedo varttirvastirhito mataḥ"},{"type":"verse","number":"25","sanskrit":"विड्विघातसमुत्थे तु विड्भङ्गाऽन्न तथौषधम् वत्तर्यभ्यङ्गावगाहाश्च स्वेदो वस्तिर्हितो मतः","text":"viḍvighātasamutthe tu viḍbhaṅgā'nna tathauṣadham vattaryabhyaṅgāvagāhāśca svedo vastirhito mataḥ"},{"type":"verse","number":"26","sanskrit":"मूत्रावरोधजनिते क्षीरवारि वचां पिबेत् दुःस्पर्शास्वरसं वाऽपि कषायं ककुभस्य च","text":"mūtrāvarodhajanite kṣīravāri vacāṃ pibet duḥsparśāsvarasaṃ vā'pi kaṣāyaṃ kakubhasya ca"},{"type":"verse","number":"27","sanskrit":"एर्वारुबीजं तोयेन पिबेद्वा लवणीकृतम् सितामिक्षुरसं क्षीरं द्रा क्षां यष्टीमथापि वा सर्वथैव प्रयुञ्जीत मूत्रकृच्छ्राश्मरीविधिम्","text":"ervārubījaṃ toyena pibedvā lavaṇīkṛtam sitāmikṣurasaṃ kṣīraṃ drā kṣāṃ yaṣṭīmathāpi vā sarvathaiva prayuñjīta mūtrakṛcchrāśmarīvidhim"},{"type":"verse","number":"28","sanskrit":"जृम्भाऽभिघातजे स्नेहं स्वेदं वाऽपि प्रयोजयेत् अन्यानपि प्रयुञ्जीत समीरणहरान्विधीन्","text":"jṛmbhā'bhighātaje snehaṃ svedaṃ vā'pi prayojayet anyānapi prayuñjīta samīraṇaharānvidhīn"},{"type":"verse","number":"29","sanskrit":"नेत्रनीरावरोधोत्थे मुञ्चेद्वाऽपि दृशोर्जलम् स्वप्यात्सुखञ्च तस्याग्रेकथयेच्च कथाः प्रियाः","text":"netranīrāvarodhotthe muñcedvā'pi dṛśorjalam svapyātsukhañca tasyāgrekathayecca kathāḥ priyāḥ"},{"type":"verse","number":"30","sanskrit":"क्षवथोर्घातजे तीक्ष्णघ्राणनस्यार्कदर्शनैः प्रवर्त्तयेत्क्षुतं सक्तां स्नेहस्वेदौ च शीलयेत्","text":"kṣavathorghātaje tīkṣṇaghrāṇanasyārkadarśanaiḥ pravarttayetkṣutaṃ saktāṃ snehasvedau ca śīlayet"},{"type":"verse","number":"31","sanskrit":"उद्गारस्यावरोधे तु स्नैहिकं धूममाचरेत् छर्दिनिग्रहसञ्जाते वमनं लङ्घनं हितम्","text":"udgārasyāvarodhe tu snaihikaṃ dhūmamācaret chardinigrahasañjāte vamanaṃ laṅghanaṃ hitam"},{"type":"verse","number":"32","sanskrit":"विरेचनं चात्र मतं तैलेनाभ्यञ्जनं तथा वस्तिशुद्धिकरैः सिद्धं चतुर्गुणजलं पयः","text":"virecanaṃ cātra mataṃ tailenābhyañjanaṃ tathā vastiśuddhikaraiḥ siddhaṃ caturguṇajalaṃ payaḥ"},{"type":"verse","number":"33","sanskrit":"आ वारिनाशात् क्वथितं पीतवन्तं प्रकामतः रमयेयुः प्रिया नार्यःशुक्रोदावर्तिनं नरम्","text":"ā vārināśāt kvathitaṃ pītavantaṃ prakāmataḥ ramayeyuḥ priyā nāryaḥśukrodāvartinaṃ naram"},{"type":"verse","number":"34","sanskrit":"तस्याभ्यङ्गोऽवगाहश्च मदिरा चरणायुधः शालि पयोनिरुहश्च हितं मैथुनमेव च","text":"tasyābhyaṅgo'vagāhaśca madirā caraṇāyudhaḥ śāli payoniruhaśca hitaṃ maithunameva ca"},{"type":"verse","number":"35","sanskrit":"क्षुद्विघातसमुद्भूते स्निग्धमुष्णं तथा लघु रुच्यमल्पं हितं भक्ष्यं पुष्पं सेव्यं सुगन्धि यत्","text":"kṣudvighātasamudbhūte snigdhamuṣṇaṃ tathā laghu rucyamalpaṃ hitaṃ bhakṣyaṃ puṣpaṃ sevyaṃ sugandhi yat"},{"type":"verse","number":"36","sanskrit":"तृषाविघातसम्भूते शीतःसर्वो विधिर्हितः कर्पूरशिशिरं स्वल्पं पिबेत्तोयं शनैः शनैः श्रमश्वासधृतौ शस्तो विश्रामः सरसौदनः","text":"tṛṣāvighātasambhūte śītaḥsarvo vidhirhitaḥ karpūraśiśiraṃ svalpaṃ pibettoyaṃ śanaiḥ śanaiḥ śramaśvāsadhṛtau śasto viśrāmaḥ sarasaudanaḥ"},{"type":"verse","number":"37","sanskrit":"निद्रा वेगविघातोत्थे पिबेत्क्षीरं सितायुतम् संवाहनं सुशय्याऽत्र हितः स्वप्नः प्रियाः कथाः","text":"nidrā vegavighātotthe pibetkṣīraṃ sitāyutam saṃvāhanaṃ suśayyā'tra hitaḥ svapnaḥ priyāḥ kathāḥ"},{"type":"verse","number":"38","sanskrit":"हिङ्गुमाक्षिकसिन्धूत्थैः पिष्टैर्वर्त्तिं विनिर्मिताम् घृताभ्यक्तं गुदे न्यस्येदुदावर्त्तविनाशिनीम्","text":"hiṅgumākṣikasindhūtthaiḥ piṣṭairvarttiṃ vinirmitām ghṛtābhyaktaṃ gude nyasyedudāvarttavināśinīm"},{"type":"verse","number":"39","sanskrit":"मदनं पिप्पली कुष्ठं वचा गौराश्च सर्षपाः गुडक्षीरसमायुक्ताः फलवर्त्तिरिहोदिता","text":"madanaṃ pippalī kuṣṭhaṃ vacā gaurāśca sarṣapāḥ guḍakṣīrasamāyuktāḥ phalavarttirihoditā"},{"type":"verse","number":"40","sanskrit":"खण्डपलं त्रिवृताऽक्ष कृष्णाकर्षो द्वयोश्चूर्णम् प्राग्भोजनस्य मधुना विडालपदकं नरो लिह्यात्","text":"khaṇḍapalaṃ trivṛtā'kṣa kṛṣṇākarṣo dvayoścūrṇam prāgbhojanasya madhunā viḍālapadakaṃ naro lihyāt"},{"type":"verse","number":"41","sanskrit":"एतद् गाढपुरीषे देयं विज्ञैरुदावर्त्ते मधुरं नरपतियोग्यं चूर्णं नाराचकं नाम्ना","text":"etad gāḍhapurīṣe deyaṃ vijñairudāvartte madhuraṃ narapatiyogyaṃ cūrṇaṃ nārācakaṃ nāmnā"},{"type":"verse","number":"42","sanskrit":"सव्योषपिप्पलीमूलं त्रिवृद्दन्ती च चित्रकम् तच्चूर्णं गुडसम्मिश्रं भक्षयेत्प्रातरुत्थितः","text":"savyoṣapippalīmūlaṃ trivṛddantī ca citrakam taccūrṇaṃ guḍasammiśraṃ bhakṣayetprātarutthitaḥ"},{"type":"verse","number":"43","sanskrit":"एतद् गुडाष्टकं नाम्ना बलवर्णाग्निवर्द्धनम् उदावर्त्तप्लीहगुल्मशोथपाण्ड्वामयापहम्","text":"etad guḍāṣṭakaṃ nāmnā balavarṇāgnivarddhanam udāvarttaplīhagulmaśothapāṇḍvāmayāpaham"},{"type":"verse","number":"44","sanskrit":"मूलकं शुष्कमार्द्रं च वर्षाभूः पञ्चमूलकम् कृतमालफलं चाप्सु पक्त्वा तेन घृतं पचेत् तत्पीतं शमयेत्क्षिप्रमुदावर्त्तमशेषतः","text":"mūlakaṃ śuṣkamārdraṃ ca varṣābhūḥ pañcamūlakam kṛtamālaphalaṃ cāpsu paktvā tena ghṛtaṃ pacet tatpītaṃ śamayetkṣipramudāvarttamaśeṣataḥ"},{"type":"verse","number":"45","sanskrit":"तुल्यकारणकार्यत्वादुदावर्त्तहरीं क्रियाम् आनाहेषु च कुर्वीत विशेषश्चाभिधीयते","text":"tulyakāraṇakāryatvādudāvarttaharīṃ kriyām ānāheṣu ca kurvīta viśeṣaścābhidhīyate"},{"type":"verse","number":"46","sanskrit":"त्रिवृत्कृष्णाहरीतक्यो द्विचतुष्पञ्चभागिकाः गुडेन तुल्या गुटिका हरत्यानाहमुल्वणम्","text":"trivṛtkṛṣṇāharītakyo dvicatuṣpañcabhāgikāḥ guḍena tulyā guṭikā haratyānāhamulvaṇam"},{"type":"verse","number":"47","sanskrit":"वर्त्तिस्त्रिकटुकसैन्धवसर्षपगृहधूमकुष्ठमदनफलैः मधुनि गुडे वा पक्वैर्विहिता साऽङगुष्ठसम्मिता विज्ञैः","text":"varttistrikaṭukasaindhavasarṣapagṛhadhūmakuṣṭhamadanaphalaiḥ madhuni guḍe vā pakvairvihitā sā'ṅaguṣṭhasammitā vijñaiḥ"},{"type":"verse","number":"48","sanskrit":"वर्त्तिरियं दृष्टफला शनैः प्रणिहिता गुदे घृताभ्यक्ता आनाहमुदरजार्त्तिं शमयति जठरे तथा गुल्मम्","text":"varttiriyaṃ dṛṣṭaphalā śanaiḥ praṇihitā gude ghṛtābhyaktā ānāhamudarajārttiṃ śamayati jaṭhare tathā gulmam"},{"type":"verse","number":"49","sanskrit":"इत्येकत्रिंश उदावर्त्तानाहाधिकारः समाप्तः ३१","text":"ityekatriṃśa udāvarttānāhādhikāraḥ samāptaḥ 31"}]},{"sthana":"Уттаракханда","number":32,"lang":"sa","content":[{"type":"heading","heading":"Гульма — абдоминальные уплотнения"},{"type":"verse","number":"1","sanskrit":"दुष्टा वातादयोऽत्यर्थ मिथ्याहारविहारतः कुर्वन्ति पञ्चधा गुल्मं कोष्ठान्तर्ग्रन्थिरूपिणम्","text":"duṣṭā vātādayo'tyartha mithyāhāravihārataḥ kurvanti pañcadhā gulmaṃ koṣṭhāntargranthirūpiṇam"},{"type":"verse","number":"2","sanskrit":"पञ्चविधत्वं विवृणोति स व्यस्तैर्जायते दोषैः समस्तैरपि चोच्छ्रितैः पुरुषाणां तथा स्त्रीणां रक्तजश्चोपजायते","text":"pañcavidhatvaṃ vivṛṇoti sa vyastairjāyate doṣaiḥ samastairapi cocchritaiḥ puruṣāṇāṃ tathā strīṇāṃ raktajaścopajāyate"},{"type":"verse","number":"3","sanskrit":"आर्त्तवादपिगुल्मः स्यात्स तुं स्त्रीणां प्रजायते अन्यस्त्वसृग्भवः पुंसां तथा स्त्रीणां प्रजायते","text":"ārttavādapigulmaḥ syātsa tuṃ strīṇāṃ prajāyate anyastvasṛgbhavaḥ puṃsāṃ tathā strīṇāṃ prajāyate"},{"type":"verse","number":"4","sanskrit":"तस्य पञ्चविधं स्थानं पार्श्वहृन्नाभिवस्तयः","text":"tasya pañcavidhaṃ sthānaṃ pārśvahṛnnābhivastayaḥ"},{"type":"verse","number":"5","sanskrit":"हृन्नाभ्योरन्तरे ग्रन्थिः सञ्चारी यदि वाऽचलः वृत्तश्चयोपचयवान्स गुल्म इति कीर्त्तितः","text":"hṛnnābhyorantare granthiḥ sañcārī yadi vā'calaḥ vṛttaścayopacayavānsa gulma iti kīrttitaḥ"},{"type":"verse","number":"6","sanskrit":"उद्गारबाहुल्यपुरीषबन्धतृप्त्यक्षमत्वान्त्रविकूजनानि आटोपमाध्मानमपक्तिशूलमासन्नगुल्मस्य वदन्ति चिह्नम्","text":"udgārabāhulyapurīṣabandhatṛptyakṣamatvāntravikūjanāni āṭopamādhmānamapaktiśūlamāsannagulmasya vadanti cihnam"},{"type":"verse","number":"7","sanskrit":"अरुचिं कृच्छ्रविण्मूत्रवातत्वं चान्त्रकूजनम् आनाहं चोर्ध्ववातञ्च सर्वगुल्मेषु लक्षयेत्","text":"aruciṃ kṛcchraviṇmūtravātatvaṃ cāntrakūjanam ānāhaṃ cordhvavātañca sarvagulmeṣu lakṣayet"},{"type":"verse","number":"8","sanskrit":"रुक्षान्नपानं विषमातिमात्रं विचेष्टनं वेगविनिग्रहश्च शोकाभिघातोऽतिमलक्षयश्च निरन्नता चानिलगुल्महेतुः","text":"rukṣānnapānaṃ viṣamātimātraṃ viceṣṭanaṃ vegavinigrahaśca śokābhighāto'timalakṣayaśca nirannatā cānilagulmahetuḥ"},{"type":"verse","number":"9","sanskrit":"यः स्थानसंस्थानरुजाविकल्पं विड्वातसङ्गं गलवक्त्रशोषम् श्यावारुणत्वं शिशिरज्वरञ्च हृत्कुक्षिपार्श्वाङ्गशिरोरुजञ्च","text":"yaḥ sthānasaṃsthānarujāvikalpaṃ viḍvātasaṅgaṃ galavaktraśoṣam śyāvāruṇatvaṃ śiśirajvarañca hṛtkukṣipārśvāṅgaśirorujañca"},{"type":"verse","number":"10","sanskrit":"करोति जीर्णेऽत्यधिकं प्रकोपं भुक्ते मृदुत्वं समुपैति यश्च वातात्स गुल्मो न च तत्र रूक्षं कषायतिक्तं कटु चोपशेते","text":"karoti jīrṇe'tyadhikaṃ prakopaṃ bhukte mṛdutvaṃ samupaiti yaśca vātātsa gulmo na ca tatra rūkṣaṃ kaṣāyatiktaṃ kaṭu copaśete"},{"type":"verse","number":"11","sanskrit":"कट्वम्लतीक्ष्णेष्णविदाहिरूक्षक्रोधातिमद्यार्कहुताशसेवा आमोऽभिघातो रुधिरञ्च दुष्टं पैत्तस्य गुल्मस्य निमित्तमुक्तम्","text":"kaṭvamlatīkṣṇeṣṇavidāhirūkṣakrodhātimadyārkahutāśasevā āmo'bhighāto rudhirañca duṣṭaṃ paittasya gulmasya nimittamuktam"},{"type":"verse","number":"12","sanskrit":"ज्वरः पिपासा सदनाङ्गरागौ शूलं महज्जीर्यति भोजने च स्वेदो विदाहो व्रणवच्च गुल्मः स्पर्शासहः पैत्तिकगुल्मरूपम्","text":"jvaraḥ pipāsā sadanāṅgarāgau śūlaṃ mahajjīryati bhojane ca svedo vidāho vraṇavacca gulmaḥ sparśāsahaḥ paittikagulmarūpam"},{"type":"verse","number":"13","sanskrit":"शीतं गुरु स्निग्धमचेष्टनञ्च सम्पूरण प्रस्वपनं दिवा च गुल्मस्य हेतुः कफसम्भवस्य सर्वस्तु दुष्टो निचयात्मकस्य","text":"śītaṃ guru snigdhamaceṣṭanañca sampūraṇa prasvapanaṃ divā ca gulmasya hetuḥ kaphasambhavasya sarvastu duṣṭo nicayātmakasya"},{"type":"verse","number":"14","sanskrit":"स्तैमित्यशीतज्वरगात्रसादहृल्लासकासारुचिगौरवाणि कफस्य लिङ्गानि च यानि तानि भवन्ति गुल्मे कफकोपजाते","text":"staimityaśītajvaragātrasādahṛllāsakāsārucigauravāṇi kaphasya liṅgāni ca yāni tāni bhavanti gulme kaphakopajāte"},{"type":"verse","number":"15","sanskrit":"व्यामिश्रलिङ्गानपरांस्तु गुल्मांस्त्रीनादिशेदौषधकल्पनाऽथम्","text":"vyāmiśraliṅgānaparāṃstu gulmāṃstrīnādiśedauṣadhakalpanā'tham"},{"type":"verse","number":"16","sanskrit":"महारुजं दाहपरीतमश्मवद्घनोन्नतं शीघ्रविदाहि दारुणम् मनः शरीराग्निबलापहारिणं त्रिदोषजं गुल्ममसाध्यमादिशेत्","text":"mahārujaṃ dāhaparītamaśmavadghanonnataṃ śīghravidāhi dāruṇam manaḥ śarīrāgnibalāpahāriṇaṃ tridoṣajaṃ gulmamasādhyamādiśet"},{"type":"verse","number":"17","sanskrit":"नवप्रसूताऽहितभोजना या या चामगर्भं विसृजेदृतौ वा वायुर्हि तस्याः परिगृह्य रक्तं करोति गुल्मं सरुजं सदाहम्","text":"navaprasūtā'hitabhojanā yā yā cāmagarbhaṃ visṛjedṛtau vā vāyurhi tasyāḥ parigṛhya raktaṃ karoti gulmaṃ sarujaṃ sadāham"},{"type":"verse","number":"18","sanskrit":"पैत्तस्य लिङ्गेन समानलिङ्गं विशेषणञ्चाप्यपरं निबोध यः स्पन्दते पिण्डित एव नाङ्गैश्चिरात्सशूलः समगर्भलिङ्गः स रौधिरः स्त्रीभव एव गुल्मो मासे व्यतीते दशमे चिकित्स्यः","text":"paittasya liṅgena samānaliṅgaṃ viśeṣaṇañcāpyaparaṃ nibodha yaḥ spandate piṇḍita eva nāṅgaiścirātsaśūlaḥ samagarbhaliṅgaḥ sa raudhiraḥ strībhava eva gulmo māse vyatīte daśame cikitsyaḥ"},{"type":"verse","number":"19","sanskrit":"सञ्चितः क्रमशो गुल्मो महावास्तुपरिग्रहः कृतमूलः शिरानद्धोयदा कूर्म इवोन्नतः","text":"sañcitaḥ kramaśo gulmo mahāvāstuparigrahaḥ kṛtamūlaḥ śirānaddhoyadā kūrma ivonnataḥ"},{"type":"verse","number":"20","sanskrit":"दौर्बल्यारुचिहृल्लासकासच्छर्द्यरतिज्वरैः तृष्णातन्द्रा प्रतिश्यायैर्युज्यते न स सिध्यति","text":"daurbalyārucihṛllāsakāsacchardyaratijvaraiḥ tṛṣṇātandrā pratiśyāyairyujyate na sa sidhyati"},{"type":"verse","number":"21","sanskrit":"गृहीत्वा सज्वरश्वासं छर्द्यतीसारपीडितम् हृन्नाभिहस्तपादेषु शोथः कर्षति गुल्मिनम्","text":"gṛhītvā sajvaraśvāsaṃ chardyatīsārapīḍitam hṛnnābhihastapādeṣu śothaḥ karṣati gulminam"},{"type":"verse","number":"22","sanskrit":"श्वासः शूलं पिपासाऽन्नविद्वेषो ग्रन्थिमूढता जायते दुर्बलत्वञ्च गुल्मिनो मरणाय वै","text":"śvāsaḥ śūlaṃ pipāsā'nnavidveṣo granthimūḍhatā jāyate durbalatvañca gulmino maraṇāya vai"},{"type":"verse","number":"23","sanskrit":"वातारितैलेन पयोयुतेन पथ्यासमेतेन विरेचनं हि संस्वेदनं स्निग्धमतिप्रशस्तं प्रभञ्जनक्रोधकृते च गुल्मे","text":"vātāritailena payoyutena pathyāsametena virecanaṃ hi saṃsvedanaṃ snigdhamatipraśastaṃ prabhañjanakrodhakṛte ca gulme"},{"type":"verse","number":"24","sanskrit":"स्वर्जिकाकुष्ठसहितः क्षारः केतकसम्भवः पीतस्तैलेन शमयेद् गुल्मं पवनसम्भवम्","text":"svarjikākuṣṭhasahitaḥ kṣāraḥ ketakasambhavaḥ pītastailena śamayed gulmaṃ pavanasambhavam"},{"type":"verse","number":"25","sanskrit":"तित्तिरांश्च मयूरांश्च कुक्कुटान्क्रौञ्चवर्त्तकान् सर्पिः शालि प्रसन्नाञ्च वातगुल्मे प्रयोजयेत्","text":"tittirāṃśca mayūrāṃśca kukkuṭānkrauñcavarttakān sarpiḥ śāli prasannāñca vātagulme prayojayet"},{"type":"verse","number":"26","sanskrit":"पित्तगुल्मे त्रिवृच्चूर्णं पातव्यं त्रिफलाम्बुना विरेकाय सितायुक्तं कम्पिल्लं वा समाक्षिकम्","text":"pittagulme trivṛccūrṇaṃ pātavyaṃ triphalāmbunā virekāya sitāyuktaṃ kampillaṃ vā samākṣikam"},{"type":"verse","number":"27","sanskrit":"अभयां द्रा क्षया खादेत्पित्तगुल्मी गुडेन वा योगैश्च वातगुल्मोक्तैः श्लेष्मगुल्ममुपाचरेत्","text":"abhayāṃ drā kṣayā khādetpittagulmī guḍena vā yogaiśca vātagulmoktaiḥ śleṣmagulmamupācaret"},{"type":"verse","number":"28","sanskrit":"हिङ्गुग्रन्थिकधान्यजीरकवचाचव्याग्निपाठाशटी वृक्षाम्लं लवणत्रयं त्रिकटुकं क्षारद्वयं दाडिमम् पथ्यापौष्करवेतसाम्लहपुषाऽजाज्यस्तदेभिः कृतं चूर्णं भावितमेतदार्द्र करसैः स्याद्बीजपूरद्र वैः गुल्माध्मानगुदाङ्कुरान्ग्रहणिकोदावर्त्तसंज्ञंगदं प्रत्याध्मानगरोदराश्मरियुतांस्तूनीद्वयारोचकान्","text":"hiṅgugranthikadhānyajīrakavacācavyāgnipāṭhāśaṭī vṛkṣāmlaṃ lavaṇatrayaṃ trikaṭukaṃ kṣāradvayaṃ dāḍimam pathyāpauṣkaravetasāmlahapuṣā'jājyastadebhiḥ kṛtaṃ cūrṇaṃ bhāvitametadārdra karasaiḥ syādbījapūradra vaiḥ gulmādhmānagudāṅkurāngrahaṇikodāvarttasaṃjñaṃgadaṃ pratyādhmānagarodarāśmariyutāṃstūnīdvayārocakān"},{"type":"verse","number":"29","sanskrit":"ऊरुस्तंभमतिभ्रमं च मनसो बाधिर्यमष्ठीलिकां प्रत्यष्ठीलकया सहापहरते प्राक्पीतमुष्णाम्बुना","text":"ūrustaṃbhamatibhramaṃ ca manaso bādhiryamaṣṭhīlikāṃ pratyaṣṭhīlakayā sahāpaharate prākpītamuṣṇāmbunā"},{"type":"verse","number":"30","sanskrit":"हृत्कुक्षिवङ्क्षणकटीजठरान्तरेषु वस्तिस्तनांसफलकेषु च पार्श्वयोश्च शूलानि नाशयति वातबलासजानि हिङ्ग्वाद्यमाद्यमिदमाश्विनसंहितोक्तम्","text":"hṛtkukṣivaṅkṣaṇakaṭījaṭharāntareṣu vastistanāṃsaphalakeṣu ca pārśvayośca śūlāni nāśayati vātabalāsajāni hiṅgvādyamādyamidamāśvinasaṃhitoktam"},{"type":"verse","number":"31","sanskrit":"धीमानुपाचरेद् गुल्मं प्रत्याख्याय त्रिदोषजम् सन्निपातोत्थिते गुल्मे त्रिदोषघ्नो विधिर्हितः","text":"dhīmānupācared gulmaṃ pratyākhyāya tridoṣajam sannipātotthite gulme tridoṣaghno vidhirhitaḥ"},{"type":"verse","number":"32","sanskrit":"शरपुङ्खस्य लवणं पथ्याचूर्णं समं द्वयम् शाणप्रमाणमश्नीयाच्चूर्णं गुल्मगदापहम्","text":"śarapuṅkhasya lavaṇaṃ pathyācūrṇaṃ samaṃ dvayam śāṇapramāṇamaśnīyāccūrṇaṃ gulmagadāpaham"},{"type":"verse","number":"33","sanskrit":"स्वर्जिका शाणमाना स्यात्तावदेव गुडं भवेत् उभयोर्वटिकां खादेद् गुल्ममायविनाशिनीम्","text":"svarjikā śāṇamānā syāttāvadeva guḍaṃ bhavet ubhayorvaṭikāṃ khāded gulmamāyavināśinīm"},{"type":"verse","number":"34","sanskrit":"पलाशवज्रीशिखरिचिञ्चाऽकतिलनालजाः यवजः स्वर्जिका चेति क्षारा ह्यष्टौ प्रकीर्त्तिताः एते गुल्महराः क्षारा अजीर्णस्य च पाचकाः","text":"palāśavajrīśikhariciñcā'katilanālajāḥ yavajaḥ svarjikā ceti kṣārā hyaṣṭau prakīrttitāḥ ete gulmaharāḥ kṣārā ajīrṇasya ca pācakāḥ"},{"type":"verse","number":"35","sanskrit":"सामुद्रं सैन्धवं काचंयवक्षारं सुवर्चलम् टङ्कणं स्वर्जिकाक्षारतुल्यं चूर्णं प्रकल्पयेत्","text":"sāmudraṃ saindhavaṃ kācaṃyavakṣāraṃ suvarcalam ṭaṅkaṇaṃ svarjikākṣāratulyaṃ cūrṇaṃ prakalpayet"},{"type":"verse","number":"36","sanskrit":"वज्रीक्षीरैरविक्षीरैरातपे भावयेत् त्र्यहम् वेष्टयेदर्कपत्रेण रुद्ध्वा भाण्डे पुटे पचेत्","text":"vajrīkṣīrairavikṣīrairātape bhāvayet tryaham veṣṭayedarkapatreṇa ruddhvā bhāṇḍe puṭe pacet"},{"type":"verse","number":"37","sanskrit":"तत्क्षारं चूर्णयेत्पश्चात्त्र्यूषणं त्रिफला तथा यवानी जीरको वह्निश्चूर्णमेषाञ्च कारयेत्","text":"tatkṣāraṃ cūrṇayetpaścāttryūṣaṇaṃ triphalā tathā yavānī jīrako vahniścūrṇameṣāñca kārayet"},{"type":"verse","number":"38","sanskrit":"सर्वचूर्णसमं क्षारं सर्वमेकत्र कारयेत् तच्चूर्णं टङ्कयुगलं सलिलेन प्रयोजयेत्","text":"sarvacūrṇasamaṃ kṣāraṃ sarvamekatra kārayet taccūrṇaṃ ṭaṅkayugalaṃ salilena prayojayet"},{"type":"verse","number":"39","sanskrit":"गुल्मे शूले तथाऽजीर्णे शोथे सर्वोदरेषु च मन्दे वह्नावुदावर्त्ते प्लीह्नि चापि परं हितम्","text":"gulme śūle tathā'jīrṇe śothe sarvodareṣu ca mande vahnāvudāvartte plīhni cāpi paraṃ hitam"},{"type":"verse","number":"40","sanskrit":"वातेऽधिके जलैः कोष्णैर्हितं पित्तेऽधिके घृतैः गोमूत्रेण कफाधिक्ये काञ्जिकेन त्रिदोषजे","text":"vāte'dhike jalaiḥ koṣṇairhitaṃ pitte'dhike ghṛtaiḥ gomūtreṇa kaphādhikye kāñjikena tridoṣaje"},{"type":"verse","number":"41","sanskrit":"वज्रक्षार इति ख्यातः प्रोक्तः पूर्वं स्वयम्भुवा सेवितो हरतेऽजीर्णं तथाऽजीर्णभवान्गदान्","text":"vajrakṣāra iti khyātaḥ proktaḥ pūrvaṃ svayambhuvā sevito harate'jīrṇaṃ tathā'jīrṇabhavāngadān"},{"type":"verse","number":"42","sanskrit":"सुवर्चिका टङ्कमिता तत्समानाऽद्रि काऽपि च उभे भुञ्जीत युगपद् गुल्मामयनिवृत्तये","text":"suvarcikā ṭaṅkamitā tatsamānā'dri kā'pi ca ubhe bhuñjīta yugapad gulmāmayanivṛttaye"},{"type":"verse","number":"43","sanskrit":"शुक्तिचूर्णस्य गुटिकां टङ्कमात्रां सुवेष्टयेत् गुडेन शाणामानेन तां लिहेद् गुल्मरोगवान्","text":"śukticūrṇasya guṭikāṃ ṭaṅkamātrāṃ suveṣṭayet guḍena śāṇāmānena tāṃ lihed gulmarogavān"},{"type":"verse","number":"44","sanskrit":"गुल्मी कुमारिकामांसं कर्षार्द्धगोघृतान्वितम् गिलेद्व्योषाभयासिन्धुसूक्ष्मचूर्णावधूलितम्","text":"gulmī kumārikāmāṃsaṃ karṣārddhagoghṛtānvitam giledvyoṣābhayāsindhusūkṣmacūrṇāvadhūlitam"},{"type":"verse","number":"45","sanskrit":"वल्लूरं मूलकं मत्स्यं शुष्कशाकानि वैदलम् न खादेदालुकं गुल्मी मधुराणि फलानि च","text":"vallūraṃ mūlakaṃ matsyaṃ śuṣkaśākāni vaidalam na khādedālukaṃ gulmī madhurāṇi phalāni ca"},{"type":"verse","number":"46","sanskrit":"स्निग्धस्विन्नशरीरस्य योज्यं स्नेहविरेचनम् शताह्वाचिरबिल्वत्वग्दारुभार्गीकणोद्भवः","text":"snigdhasvinnaśarīrasya yojyaṃ snehavirecanam śatāhvācirabilvatvagdārubhārgīkaṇodbhavaḥ"},{"type":"verse","number":"47","sanskrit":"कल्कः पीतो जयेद् गुल्मं तिलक्वाथेन रक्तजम् तिलक्वाथो गुडव्योषघृतभार्गीयुतो भवेत्","text":"kalkaḥ pīto jayed gulmaṃ tilakvāthena raktajam tilakvātho guḍavyoṣaghṛtabhārgīyuto bhavet"},{"type":"verse","number":"48","sanskrit":"योनिरक्तभवे गुल्मे नष्टपुष्पेषु योषिताम् पीतो धात्रीरसो युक्तो मरिचैश्चास्रगुल्मनुत्","text":"yoniraktabhave gulme naṣṭapuṣpeṣu yoṣitām pīto dhātrīraso yukto maricaiścāsragulmanut"},{"type":"verse","number":"49","sanskrit":"गुण्डारोचनिकाचूर्णं शर्करामाक्षिकान्वितम् विदधीताशु गुल्मिन्या मनलसञ्चङ्क्रमाय च","text":"guṇḍārocanikācūrṇaṃ śarkarāmākṣikānvitam vidadhītāśu gulminyā manalasañcaṅkramāya ca"},{"type":"verse","number":"50","sanskrit":"विशेषमपरञ्चाशु शृणु रक्तप्रभेदनम् पलाशक्षारतोयेन सर्पिः सिद्धं पिबेच्च सा","text":"viśeṣamaparañcāśu śṛṇu raktaprabhedanam palāśakṣāratoyena sarpiḥ siddhaṃ pibecca sā"},{"type":"verse","number":"51","sanskrit":"सक्षारं त्र्यूषणं सर्पिः प्रपिबेदस्रगुल्मिनी","text":"sakṣāraṃ tryūṣaṇaṃ sarpiḥ prapibedasragulminī"},{"type":"verse","number":"52","sanskrit":"यस्मिन्न च रसक्षीरतोयसाध्यरसादिषु फेनोद्गारस्य निष्पत्तिर्नष्टदुग्धसमाकृतेः स एव तस्य पाकस्य कालो नेतरलक्षणः","text":"yasminna ca rasakṣīratoyasādhyarasādiṣu phenodgārasya niṣpattirnaṣṭadugdhasamākṛteḥ sa eva tasya pākasya kālo netaralakṣaṇaḥ"},{"type":"verse","number":"53","sanskrit":"इति द्वात्रिंशो गुल्माधिकारः समाप्तः ३२","text":"iti dvātriṃśo gulmādhikāraḥ samāptaḥ 32"}]},{"sthana":"Уттаракханда","number":33,"lang":"sa","content":[{"type":"heading","heading":"Плиха-якрит — селезёнка и печень"},{"type":"verse","number":"1","sanskrit":"शोणिताज्जायते प्लीहा वामतो हृदयादधः रक्तवाहिशिराणां स मूलं ख्यातो महर्षिभिः","text":"śoṇitājjāyate plīhā vāmato hṛdayādadhaḥ raktavāhiśirāṇāṃ sa mūlaṃ khyāto maharṣibhiḥ"},{"type":"verse","number":"2","sanskrit":"विदाह्यभिष्यन्दिरतस्य जन्तोः प्रदुष्टमत्यर्थमसृक्कफश्च प्लीहाऽभिवृद्धिं कुरुतः प्रवृद्धौ तं प्लीहसञ्ज्ञं गदमामनन्ति","text":"vidāhyabhiṣyandiratasya jantoḥ praduṣṭamatyarthamasṛkkaphaśca plīhā'bhivṛddhiṃ kurutaḥ pravṛddhau taṃ plīhasañjñaṃ gadamāmananti"},{"type":"verse","number":"3","sanskrit":"वामे स पार्श्वे परिवृद्धिमेति विशेषतः सीदति चातुरोऽत्र मन्दज्वराग्निःकफपित्तलिङ्गैरुपद्रुतः क्षीणबलोऽतिपाण्डुः","text":"vāme sa pārśve parivṛddhimeti viśeṣataḥ sīdati cāturo'tra mandajvarāgniḥkaphapittaliṅgairupadrutaḥ kṣīṇabalo'tipāṇḍuḥ"},{"type":"verse","number":"4","sanskrit":"क्लमो भ्रमो विदाहश्च वैवर्ण्यं गात्रगौरवम् मोहो रक्तोदरत्वञ्च ज्ञेयं रक्तजलक्षणम्","text":"klamo bhramo vidāhaśca vaivarṇyaṃ gātragauravam moho raktodaratvañca jñeyaṃ raktajalakṣaṇam"},{"type":"verse","number":"5","sanskrit":"सज्वरः सपिपासश्च सदाहो मोहसंयुतः पीतगात्रो विशेषेण प्लीहा पैत्तिक उच्यते","text":"sajvaraḥ sapipāsaśca sadāho mohasaṃyutaḥ pītagātro viśeṣeṇa plīhā paittika ucyate"},{"type":"verse","number":"6","sanskrit":"प्लीहा मन्दव्यथः स्थूलः कठिनो गौरवान्वितः अरोचकेन संयुक्तः प्लीहा कफज उच्यते","text":"plīhā mandavyathaḥ sthūlaḥ kaṭhino gauravānvitaḥ arocakena saṃyuktaḥ plīhā kaphaja ucyate"},{"type":"verse","number":"7","sanskrit":"नित्यमानद्धकोष्ठः स्यान्नित्योदावर्त्तपीडितः वेदनाभिः परीतश्च प्लीहा वातिक उच्यते","text":"nityamānaddhakoṣṭhaḥ syānnityodāvarttapīḍitaḥ vedanābhiḥ parītaśca plīhā vātika ucyate"},{"type":"verse","number":"8","sanskrit":"दोपत्रितयरूपाणि प्लीह्न्यसाध्ये भवन्त्यपि","text":"dopatritayarūpāṇi plīhnyasādhye bhavantyapi"},{"type":"verse","number":"9","sanskrit":"अधो दक्षिणतश्चापि हृदयाद् यकृतः स्थितिः तत्तु रञ्जकपित्तस्य स्थानं शोणितजं मतम्","text":"adho dakṣiṇataścāpi hṛdayād yakṛtaḥ sthitiḥ tattu rañjakapittasya sthānaṃ śoṇitajaṃ matam"},{"type":"verse","number":"10","sanskrit":"प्लीहामयस्यहेत्वादि समस्तं यकृदामये किन्तु स्थितिस्तयोर्ज्ञेया वामदक्षिणपार्श्वयोः","text":"plīhāmayasyahetvādi samastaṃ yakṛdāmaye kintu sthitistayorjñeyā vāmadakṣiṇapārśvayoḥ"},{"type":"verse","number":"11","sanskrit":"पातव्यो युक्तितः क्षारः क्षीरेणोदधिशुक्तिजः तथा दुग्धेन पातव्याः पिप्पल्यः प्लीहशान्तये","text":"pātavyo yuktitaḥ kṣāraḥ kṣīreṇodadhiśuktijaḥ tathā dugdhena pātavyāḥ pippalyaḥ plīhaśāntaye"},{"type":"verse","number":"12","sanskrit":"अर्कपत्रं सलवणं पुटदग्धं सुचूर्णितम् निहन्ति मस्तुना पीतं प्लीहानमतिदारुणम्","text":"arkapatraṃ salavaṇaṃ puṭadagdhaṃ sucūrṇitam nihanti mastunā pītaṃ plīhānamatidāruṇam"},{"type":"verse","number":"13","sanskrit":"हिङ्गु त्रिकटुकं कुष्ठं यवक्षारं च सैन्धवम् मातुलुङ्गरसोपेतं प्लीहशूलहरं भवेत्","text":"hiṅgu trikaṭukaṃ kuṣṭhaṃ yavakṣāraṃ ca saindhavam mātuluṅgarasopetaṃ plīhaśūlaharaṃ bhavet"},{"type":"verse","number":"14","sanskrit":"पलाशक्षारतोयेन पिप्पली परिभाविता प्लीहगुल्मार्त्तिशमनी वह्निमान्द्यहरी मता","text":"palāśakṣāratoyena pippalī paribhāvitā plīhagulmārttiśamanī vahnimāndyaharī matā"},{"type":"verse","number":"15","sanskrit":"रसेन जम्बीरफलस्य शङ्खनाभीरजः पीतमवश्यमेव शाणप्रमाणं शमयेदशेषं प्लीहामयं कूर्मसमानमाशु","text":"rasena jambīraphalasya śaṅkhanābhīrajaḥ pītamavaśyameva śāṇapramāṇaṃ śamayedaśeṣaṃ plīhāmayaṃ kūrmasamānamāśu"},{"type":"verse","number":"16","sanskrit":"शरपुङ्खमूलकल्कस्तक्रेणालोडितः पीतः प्लीहानं यदि न हरति शैलोऽपि तदा जले प्लवते","text":"śarapuṅkhamūlakalkastakreṇāloḍitaḥ pītaḥ plīhānaṃ yadi na harati śailo'pi tadā jale plavate"},{"type":"verse","number":"17","sanskrit":"सुपक्वसहकारस्य रसः क्षौद्र समन्वितः पीतः प्रशमयत्येव प्लीहानं नेह संशयः","text":"supakvasahakārasya rasaḥ kṣaudra samanvitaḥ pītaḥ praśamayatyeva plīhānaṃ neha saṃśayaḥ"},{"type":"verse","number":"18","sanskrit":"सुस्विन्नं शाल्मलीपुष्पं निशापर्युषितं नरः राजिकाचूर्णसंयुक्तं खादेत्प्लीहोपशान्तये","text":"susvinnaṃ śālmalīpuṣpaṃ niśāparyuṣitaṃ naraḥ rājikācūrṇasaṃyuktaṃ khādetplīhopaśāntaye"},{"type":"verse","number":"19","sanskrit":"यवानिकाचित्रकयाव शूकषड्ग्रन्थिदन्तीमगधोद्भवानाम् चूर्णं हरेत् प्लीहगदं निपीतमुष्णाम्बुना मस्तुसुराऽसवैर्वा","text":"yavānikācitrakayāva śūkaṣaḍgranthidantīmagadhodbhavānām cūrṇaṃ haret plīhagadaṃ nipītamuṣṇāmbunā mastusurā'savairvā"},{"type":"verse","number":"20","sanskrit":"प्लीहोद्दिष्टाःक्रियाः सर्वा यकृद्रो गे समाचरेत् कार्यञ्च दक्षिणे बाहौ तत्र शोणितमोक्षणम्","text":"plīhoddiṣṭāḥkriyāḥ sarvā yakṛdro ge samācaret kāryañca dakṣiṇe bāhau tatra śoṇitamokṣaṇam"},{"type":"verse","number":"21","sanskrit":"क्षारं विडङ्गकृष्णाभ्यां पूतीकस्याम्बु निःसृतम् पिबेत्प्रातर्यथावह्नि यकृत्प्लीहप्रशान्तये","text":"kṣāraṃ viḍaṅgakṛṣṇābhyāṃ pūtīkasyāmbu niḥsṛtam pibetprātaryathāvahni yakṛtplīhapraśāntaye"},{"type":"verse","number":"22","sanskrit":"इति त्रयस्त्रिंशः प्लीहयकृदधिकारः समाप्तः ३३","text":"iti trayastriṃśaḥ plīhayakṛdadhikāraḥ samāptaḥ 33"}]},{"sthana":"Уттаракханда","number":34,"lang":"sa","content":[{"type":"heading","heading":"Хридрога — болезни сердца"},{"type":"verse","number":"1","sanskrit":"अत्युष्णगुर्वम्लकषायतिक्तश्रमाभिघाताध्यशनप्रसङ्गैः सञ्चिन्तनैर्वेगविधारणैश्च हृदामयः पञ्चविधः प्रदिष्टः","text":"atyuṣṇagurvamlakaṣāyatiktaśramābhighātādhyaśanaprasaṅgaiḥ sañcintanairvegavidhāraṇaiśca hṛdāmayaḥ pañcavidhaḥ pradiṣṭaḥ"},{"type":"verse","number":"2","sanskrit":"दूषयित्वा रसं दोषा विगुणा हृदयङ्गताः हृदि बाधां प्रकुर्वन्ति हृद्रो गं तं प्रचक्षते","text":"dūṣayitvā rasaṃ doṣā viguṇā hṛdayaṅgatāḥ hṛdi bādhāṃ prakurvanti hṛdro gaṃ taṃ pracakṣate"},{"type":"verse","number":"3","sanskrit":"आयम्यते मारुतजे हृदयं तुद्यते तथा निर्मथ्यते दीर्यते च स्फोट्यते पाट्यतेऽपि वा","text":"āyamyate mārutaje hṛdayaṃ tudyate tathā nirmathyate dīryate ca sphoṭyate pāṭyate'pi vā"},{"type":"verse","number":"4","sanskrit":"तृष्णोष्मदाहचोषाः स्युः पैत्तिके हृदये क्लमः धूमायनं च मूर्च्छा च क्लेदः शोषो मुखस्य च","text":"tṛṣṇoṣmadāhacoṣāḥ syuḥ paittike hṛdaye klamaḥ dhūmāyanaṃ ca mūrcchā ca kledaḥ śoṣo mukhasya ca"},{"type":"verse","number":"5","sanskrit":"गौरवं कफसंस्रावोऽरुचिः स्तम्भोऽग्निमार्दवम् माधुर्यमपि चास्यस्य बलासावतते हृदि","text":"gauravaṃ kaphasaṃsrāvo'ruciḥ stambho'gnimārdavam mādhuryamapi cāsyasya balāsāvatate hṛdi"},{"type":"verse","number":"6","sanskrit":"विद्यात्त्रिदोषमप्येवं सर्वलिङ्गं हृदामयम्","text":"vidyāttridoṣamapyevaṃ sarvaliṅgaṃ hṛdāmayam"},{"type":"verse","number":"7","sanskrit":"त्रिदोषगेतुहृद्रो गे यो दुरात्मा निषेवते तिलक्षीरगुडादींश्च ग्रन्थिस्तस्योपजायते","text":"tridoṣagetuhṛdro ge yo durātmā niṣevate tilakṣīraguḍādīṃśca granthistasyopajāyate"},{"type":"verse","number":"8","sanskrit":"मर्मैकदेशे संक्लेदं रसश्चाप्युपगच्छति संक्लेदात्कृमयश्चास्य भवन्त्युपहतात्मनः","text":"marmaikadeśe saṃkledaṃ rasaścāpyupagacchati saṃkledātkṛmayaścāsya bhavantyupahatātmanaḥ"},{"type":"verse","number":"9","sanskrit":"उत्क्लेदः ष्ठीवनं तोदः शूलं हृंल्लासकस्तमः अरुचिः श्यावनेत्रत्वं शोषश्च कृमिजे भवेत्","text":"utkledaḥ ṣṭhīvanaṃ todaḥ śūlaṃ hṛṃllāsakastamaḥ aruciḥ śyāvanetratvaṃ śoṣaśca kṛmije bhavet"},{"type":"verse","number":"10","sanskrit":"क्लोम्नः सादो भ्रमः शोषो ज्ञेयास्तेषामुपद्र वाः कृमिजे तु कृमीणां ये श्लैष्मिकाणां हि ते मताः","text":"klomnaḥ sādo bhramaḥ śoṣo jñeyāsteṣāmupadra vāḥ kṛmije tu kṛmīṇāṃ ye ślaiṣmikāṇāṃ hi te matāḥ"},{"type":"verse","number":"11","sanskrit":"घृतेन दुग्धेन गुडाम्भसा वा पिबन्ति चूर्णं ककुभत्वचो ये हृद्रो गजीर्णज्वररक्तपित्तं हत्वा भवेयुश्चिरजीविनस्ते","text":"ghṛtena dugdhena guḍāmbhasā vā pibanti cūrṇaṃ kakubhatvaco ye hṛdro gajīrṇajvararaktapittaṃ hatvā bhaveyuścirajīvinaste"},{"type":"verse","number":"12","sanskrit":"हरीतकीवचारास्ना पिप्पलीनागरोद्भवम् शटीपुष्करमूलोत्थं चूर्णं हृद्रो गनाशनम्","text":"harītakīvacārāsnā pippalīnāgarodbhavam śaṭīpuṣkaramūlotthaṃ cūrṇaṃ hṛdro ganāśanam"},{"type":"verse","number":"13","sanskrit":"पुटदग्धहरिणशृङ्गं पिष्ट्वा गव्येन सर्पिषा पिबतः हृत्पृष्ठशूलमचिरादुपैति शान्तिं सुकष्टमपि","text":"puṭadagdhahariṇaśṛṅgaṃ piṣṭvā gavyena sarpiṣā pibataḥ hṛtpṛṣṭhaśūlamacirādupaiti śāntiṃ sukaṣṭamapi"},{"type":"verse","number":"14","sanskrit":"तैलाज्यगुडविपक्वं चूर्णं गोधूमपार्थोत्थम् पिबति पयोभुक्स भवति गतसकलहृदामयः पुरुषः","text":"tailājyaguḍavipakvaṃ cūrṇaṃ godhūmapārthottham pibati payobhuksa bhavati gatasakalahṛdāmayaḥ puruṣaḥ"},{"type":"verse","number":"15","sanskrit":"गोधूमककुभचूर्णं पक्वमजाक्षीरगव्यसर्पिर्भ्याम् मधुशर्करासमेतं शमयति हृद्रो गमुद्धतं पुंसाम्","text":"godhūmakakubhacūrṇaṃ pakvamajākṣīragavyasarpirbhyām madhuśarkarāsametaṃ śamayati hṛdro gamuddhataṃ puṃsām"},{"type":"verse","number":"16","sanskrit":"पार्थस्य कल्केन रसेन सिद्धं शस्तं घृतं सर्वहृदामयेषु","text":"pārthasya kalkena rasena siddhaṃ śastaṃ ghṛtaṃ sarvahṛdāmayeṣu"},{"type":"verse","number":"17","sanskrit":"घृतं बलानागबलाऽजुनानां क्वाथेन कल्केन च यष्टिकायाः सिद्धन्तु हन्याद्घृदयामयं हि सवातरक्तक्षतरक्तपित्तम्","text":"ghṛtaṃ balānāgabalā'junānāṃ kvāthena kalkena ca yaṣṭikāyāḥ siddhantu hanyādghṛdayāmayaṃ hi savātaraktakṣataraktapittam"},{"type":"verse","number":"18","sanskrit":"इति चतुस्त्रिंशोहृद्रोगाधिकारः समाप्तः ३४","text":"iti catustriṃśohṛdrogādhikāraḥ samāptaḥ 34"}]},{"sthana":"Уттаракханда","number":35,"lang":"sa","content":[{"type":"heading","heading":"Мутракриччхра — затруднённое мочеиспускание"},{"type":"verse","number":"1","sanskrit":"व्यायामतीक्ष्णौषधरुक्षमद्यप्रसङ्गनृत्यद्रुतपृष्ठयानात् आनूपमत्स्याध्यशनादजीर्णात् स्युर्मूत्रकृच्छ्राणि नृणां तथाऽष्टौ","text":"vyāyāmatīkṣṇauṣadharukṣamadyaprasaṅganṛtyadrutapṛṣṭhayānāt ānūpamatsyādhyaśanādajīrṇāt syurmūtrakṛcchrāṇi nṛṇāṃ tathā'ṣṭau"},{"type":"verse","number":"2","sanskrit":"पृथङ्मलाः स्वैः कुपिता निदानैः सर्वेऽथ वा कोपमुपेत्य बस्तौ मूत्रस्य मार्गं परिपीडयन्ति यदा तदा मूत्रयतीह कृच्छ्रात्","text":"pṛthaṅmalāḥ svaiḥ kupitā nidānaiḥ sarve'tha vā kopamupetya bastau mūtrasya mārgaṃ paripīḍayanti yadā tadā mūtrayatīha kṛcchrāt"},{"type":"verse","number":"3","sanskrit":"तीव्रा च रुग्वङ्क्षणवस्तिमेढ्रे स्वल्पं मुहुर्मूत्रयतीह वातात्","text":"tīvrā ca rugvaṅkṣaṇavastimeḍhre svalpaṃ muhurmūtrayatīha vātāt"},{"type":"verse","number":"4","sanskrit":"पीतं सरक्तं सरुजं सदाहं कृच्छ्रं मुहुर्मूत्रयतीह पित्तात्","text":"pītaṃ saraktaṃ sarujaṃ sadāhaṃ kṛcchraṃ muhurmūtrayatīha pittāt"},{"type":"verse","number":"5","sanskrit":"वस्तेः सलिङ्गस्य गुरुत्वशोथौ मूत्रं सपिच्छं कफमूत्रकृच्छ्रे","text":"vasteḥ saliṅgasya gurutvaśothau mūtraṃ sapicchaṃ kaphamūtrakṛcchre"},{"type":"verse","number":"6","sanskrit":"सर्वाणि रूपाणि तु सन्निपाताद्भवन्ति तत्कृच्छ्रतमं हि कृच्छ्रम्","text":"sarvāṇi rūpāṇi tu sannipātādbhavanti tatkṛcchratamaṃ hi kṛcchram"},{"type":"verse","number":"7","sanskrit":"मूत्रवाहिषु शल्येन क्षतेष्वभिहतेषु च","text":"mūtravāhiṣu śalyena kṣateṣvabhihateṣu ca"},{"type":"verse","number":"8","sanskrit":"शकृतस्तु प्रतीघाताद्वायुर्विगुणतां गतः आध्मानंवातशूलञ्च मूत्रसङ्गं करोति च","text":"śakṛtastu pratīghātādvāyurviguṇatāṃ gataḥ ādhmānaṃvātaśūlañca mūtrasaṅgaṃ karoti ca"},{"type":"verse","number":"9","sanskrit":"शुक्रे दोषैरुपहते मूत्रमार्गं विधाविते सशुक्रं मूत्रयेत्कृच्छ्राद्वस्तिमेहनशूलवान्","text":"śukre doṣairupahate mūtramārgaṃ vidhāvite saśukraṃ mūtrayetkṛcchrādvastimehanaśūlavān"},{"type":"verse","number":"10","sanskrit":"अश्मरीहेतु तत्पूर्वं मूत्रकृच्छ्रमुदाहृतम् अश्मरी शर्करा चैव तुल्यसम्भवलक्षणे विशेषणं शर्करायाः शृणु कीर्त्तयतो मम पच्यमानाऽश्मरी पित्ताच्छोष्यमाणा च वायुना विमुक्तकफसन्धाना क्षरन्ती शर्करा मता","text":"aśmarīhetu tatpūrvaṃ mūtrakṛcchramudāhṛtam aśmarī śarkarā caiva tulyasambhavalakṣaṇe viśeṣaṇaṃ śarkarāyāḥ śṛṇu kīrttayato mama pacyamānā'śmarī pittācchoṣyamāṇā ca vāyunā vimuktakaphasandhānā kṣarantī śarkarā matā"},{"type":"verse","number":"11","sanskrit":"हृत्पीडा वेपथुः शूलं कुक्षावग्निश्च दुर्बलः तथा भवति मूर्च्छा च मूत्रकृच्छ्रञ्च दारुणम्","text":"hṛtpīḍā vepathuḥ śūlaṃ kukṣāvagniśca durbalaḥ tathā bhavati mūrcchā ca mūtrakṛcchrañca dāruṇam"},{"type":"verse","number":"12","sanskrit":"अभ्यञ्जनस्नेहनिरूहवस्तिस्वेदोपनाहोत्तरवस्तिसेकान् स्थिराऽदिभिर्वातहरैश्च सिद्धान्दद्याद्र सांश्चानिलमूत्रकृच्छ्रे","text":"abhyañjanasnehanirūhavastisvedopanāhottaravastisekān sthirā'dibhirvātaharaiśca siddhāndadyādra sāṃścānilamūtrakṛcchre"},{"type":"verse","number":"13","sanskrit":"अमृता नागरं धात्री वाजिगन्धा त्रिकण्टकः प्रपिबेद्वातरोगार्त्तः शूलवान्मूत्रकृच्छ्रवान्","text":"amṛtā nāgaraṃ dhātrī vājigandhā trikaṇṭakaḥ prapibedvātarogārttaḥ śūlavānmūtrakṛcchravān"},{"type":"verse","number":"14","sanskrit":"पुनर्नवैरण्डशतावरीभिःपत्तूरवृश्चीरबलाऽश्मभिद्भिः द्विपञ्चमूलेन कुलत्थकेन यवैश्च तोयोत्क्वथिते कषाये","text":"punarnavairaṇḍaśatāvarībhiḥpattūravṛścīrabalā'śmabhidbhiḥ dvipañcamūlena kulatthakena yavaiśca toyotkvathite kaṣāye"},{"type":"verse","number":"15","sanskrit":"तैलं वराहर्क्षवसाघृतञ्च तैरेवकल्कैर्लवणैश्च सिद्धम् तन्मात्रयाऽत्र प्रतिहन्ति पीतं शूलान्वितं मारुतमूत्रकृच्छ्रम्","text":"tailaṃ varāharkṣavasāghṛtañca tairevakalkairlavaṇaiśca siddham tanmātrayā'tra pratihanti pītaṃ śūlānvitaṃ mārutamūtrakṛcchram"},{"type":"verse","number":"16","sanskrit":"सेकावगाहाः शिशिराः प्रदेहा ग्रैष्मो विधिर्वस्तिपयोविकाराः द्रा क्षाविदारीक्षुरसैर्घृतैश्च कृच्छ्रेषु पित्तप्रभवेषु कार्याः","text":"sekāvagāhāḥ śiśirāḥ pradehā graiṣmo vidhirvastipayovikārāḥ drā kṣāvidārīkṣurasairghṛtaiśca kṛcchreṣu pittaprabhaveṣu kāryāḥ"},{"type":"verse","number":"17","sanskrit":"कुशः काशः शरो दर्भ इक्षुश्चेति तृणोद्भवम् पित्तकृछ्रहरं पञ्चमूलं वस्तिविशोधनम्","text":"kuśaḥ kāśaḥ śaro darbha ikṣuśceti tṛṇodbhavam pittakṛchraharaṃ pañcamūlaṃ vastiviśodhanam"},{"type":"verse","number":"18","sanskrit":"शतावरीकाशकुशश्वदंष्ट्राविदारिशालीक्षुकसेरुकाणाम् क्वाथं सुशीतं मधुशर्कराभ्यां युक्तं पिबेत्पैत्तिकमूत्रकृच्छ्रे","text":"śatāvarīkāśakuśaśvadaṃṣṭrāvidāriśālīkṣukaserukāṇām kvāthaṃ suśītaṃ madhuśarkarābhyāṃ yuktaṃ pibetpaittikamūtrakṛcchre"},{"type":"verse","number":"19","sanskrit":"एर्वारुबीजं मधुकञ्च दार्वी पैत्ते पिबेत्तण्डुलधावनेन दार्वी तथैवामलकीरसेन समाक्षिकं पित्तकृते तु कृच्छ्रे","text":"ervārubījaṃ madhukañca dārvī paitte pibettaṇḍuladhāvanena dārvī tathaivāmalakīrasena samākṣikaṃ pittakṛte tu kṛcchre"},{"type":"verse","number":"20","sanskrit":"हरीतकीगोक्षुरराज वृक्षपाषाणभिद्धन्वयवासकानाम् क्वाथं पिबेन्माक्षिकसम्प्रयुक्तं कृच्छ्रे सदाहे स रुजे विबन्धे","text":"harītakīgokṣurarāja vṛkṣapāṣāṇabhiddhanvayavāsakānām kvāthaṃ pibenmākṣikasamprayuktaṃ kṛcchre sadāhe sa ruje vibandhe"},{"type":"verse","number":"21","sanskrit":"शतावरीकाशकुशश्वदंष्ट्राविदारिकेक्ष्वामलकेषु सिद्धम् सर्पिः पयो वा सितया विमिश्रं कृच्छ्रेषु पित्तप्रभवेषु योज्यम्","text":"śatāvarīkāśakuśaśvadaṃṣṭrāvidārikekṣvāmalakeṣu siddham sarpiḥ payo vā sitayā vimiśraṃ kṛcchreṣu pittaprabhaveṣu yojyam"},{"type":"verse","number":"22","sanskrit":"त्रिकण्टकैरण्डकुशाद्यभीरुकर्कारुकेषु स्वरसेषु सिद्धम् सर्पिर्गुडार्द्धांशयुतं प्रयोज्यं कृच्छ्राश्मरीमूत्रविघातदोषे अयं विशेषेण पुनर्विधेयः सर्वाश्मरीणां प्रवरः प्रयोगः","text":"trikaṇṭakairaṇḍakuśādyabhīrukarkārukeṣu svaraseṣu siddham sarpirguḍārddhāṃśayutaṃ prayojyaṃ kṛcchrāśmarīmūtravighātadoṣe ayaṃ viśeṣeṇa punarvidheyaḥ sarvāśmarīṇāṃ pravaraḥ prayogaḥ"},{"type":"verse","number":"23","sanskrit":"क्षारोष्णतीव्रौषधमन्नपानं स्वेदो यवान्नं वमनं निरूहः तक्रञ्च तिक्तौषधसिद्धतैलान्यभ्यङ्गपानं कफमूत्रकृच्छ्रे","text":"kṣāroṣṇatīvrauṣadhamannapānaṃ svedo yavānnaṃ vamanaṃ nirūhaḥ takrañca tiktauṣadhasiddhatailānyabhyaṅgapānaṃ kaphamūtrakṛcchre"},{"type":"verse","number":"24","sanskrit":"मूत्रेण सुरया वाऽपि कदलीस्वरसेन वा कफकृच्छ्रविनाशाय सूक्ष्मं पिष्ट्वा गुटीं पिबेत्","text":"mūtreṇa surayā vā'pi kadalīsvarasena vā kaphakṛcchravināśāya sūkṣmaṃ piṣṭvā guṭīṃ pibet"},{"type":"verse","number":"25","sanskrit":"तक्रेण युक्तं शितिमारकस्य बीजं पिबेन्मूत्रविघातहेतोः पिबेत्तथा तण्डुलधावनेन प्रवालचूर्णं कफमूत्रकृच्छ्रे","text":"takreṇa yuktaṃ śitimārakasya bījaṃ pibenmūtravighātahetoḥ pibettathā taṇḍuladhāvanena pravālacūrṇaṃ kaphamūtrakṛcchre"},{"type":"verse","number":"26","sanskrit":"त्रिकटु त्रिफला मुस्तंगुग्गुलुञ्च समाक्षिकम् गोक्षुरक्वाथ संयुक्तं गुटिकां भक्षयेद् बुधः","text":"trikaṭu triphalā mustaṃgugguluñca samākṣikam gokṣurakvātha saṃyuktaṃ guṭikāṃ bhakṣayed budhaḥ"},{"type":"verse","number":"27","sanskrit":"प्रमेहं मूत्रकृच्छ्रञ्च म्रूत्राघातं तथैव च अश्मरीं प्रदरञ्चैव नाशयेदविकल्पतः","text":"pramehaṃ mūtrakṛcchrañca mrūtrāghātaṃ tathaiva ca aśmarīṃ pradarañcaiva nāśayedavikalpataḥ"},{"type":"verse","number":"28","sanskrit":"सर्वत्रिदोषप्रभवे च वायोः स्थानानुपूर्व्या प्रसमीक्ष्य कार्यम् त्रिभ्योऽधिके प्राग्वमनं कफे स्यात्पित्ते विरेकः पवने तु वस्तिः","text":"sarvatridoṣaprabhave ca vāyoḥ sthānānupūrvyā prasamīkṣya kāryam tribhyo'dhike prāgvamanaṃ kaphe syātpitte virekaḥ pavane tu vastiḥ"},{"type":"verse","number":"29","sanskrit":"बृहतीधावनीपाठायष्टी मधुकलिङ्गकाः पाचनीयो बृहत्यादिः कृच्छ्रदोषत्रयापहः","text":"bṛhatīdhāvanīpāṭhāyaṣṭī madhukaliṅgakāḥ pācanīyo bṛhatyādiḥ kṛcchradoṣatrayāpahaḥ"},{"type":"verse","number":"30","sanskrit":"गुडेनमिश्रितं क्षीरं कदुष्णं कामतः पिबेत् मूत्रकृच्छ्रेषु सर्वेषु शर्करावातरोगनुत्","text":"guḍenamiśritaṃ kṣīraṃ kaduṣṇaṃ kāmataḥ pibet mūtrakṛcchreṣu sarveṣu śarkarāvātaroganut"},{"type":"verse","number":"31","sanskrit":"मूत्रकृच्छेऽभिघातोत्थे वातकृच्छ्रक्रिया मता","text":"mūtrakṛcche'bhighātotthe vātakṛcchrakriyā matā"},{"type":"verse","number":"32","sanskrit":"मद्यं पिबेद्वा ससितं ससर्पिः शृतं पयो वाऽद्धसिताप्रयुक्तम् धात्रीरसञ्चेक्षुरसं पिबेद्वा कृच्छ्रे सरक्ते मधुना विमिश्रम्","text":"madyaṃ pibedvā sasitaṃ sasarpiḥ śṛtaṃ payo vā'ddhasitāprayuktam dhātrīrasañcekṣurasaṃ pibedvā kṛcchre sarakte madhunā vimiśram"},{"type":"verse","number":"33","sanskrit":"स्वेदचूर्णक्रियाऽभ्यङ्गवस्तयः स्युः पुरीषजे क्वाथो गोक्षुरबीजस्य यवक्षारयुतः सदा मूत्रकृच्छ्रं शकृज्जन्म पीतः शीघ्रं नियच्छति","text":"svedacūrṇakriyā'bhyaṅgavastayaḥ syuḥ purīṣaje kvātho gokṣurabījasya yavakṣārayutaḥ sadā mūtrakṛcchraṃ śakṛjjanma pītaḥ śīghraṃ niyacchati"},{"type":"verse","number":"34","sanskrit":"लेहः शुक्रविबन्धोत्थे सशिलाजतु माक्षिकम् एलाहिङ्गुयुतं क्षीरं सर्पिर्मिश्रं पिबेन्नरः","text":"lehaḥ śukravibandhotthe saśilājatu mākṣikam elāhiṅguyutaṃ kṣīraṃ sarpirmiśraṃ pibennaraḥ"},{"type":"verse","number":"35","sanskrit":"मूत्रदोषप्रशुर्द्ध्य्थं शुक्रदोषहरञ्च तत् वृष्यैर्बृंहितधातोश्च विधेयाः प्रमदोत्तमा","text":"mūtradoṣapraśurddhythaṃ śukradoṣaharañca tat vṛṣyairbṛṃhitadhātośca vidheyāḥ pramadottamā"},{"type":"verse","number":"36","sanskrit":"सप्तच्छदारग्वधकेवु कैला निम्बः करञ्जः कुटजो गुडूची साध्या जले तेन पचेद्यवागूं सिद्धं कषायं मधुसंयुतं वा","text":"saptacchadāragvadhakevu kailā nimbaḥ karañjaḥ kuṭajo guḍūcī sādhyā jale tena pacedyavāgūṃ siddhaṃ kaṣāyaṃ madhusaṃyutaṃ vā"},{"type":"verse","number":"37","sanskrit":"एर्वारुबीजकल्कश्च श्लक्ष्णपिष्टोऽक्षसंमितः धान्याम्ललवणैः पेयो मूत्रकृच्छ्रविनाशनः","text":"ervārubījakalkaśca ślakṣṇapiṣṭo'kṣasaṃmitaḥ dhānyāmlalavaṇaiḥ peyo mūtrakṛcchravināśanaḥ"},{"type":"verse","number":"38","sanskrit":"त्रिकण्टकारग्वधदर्भकाश दुरालभापर्वतभेदपथ्याः निघ्नन्ति पीता मधुनाऽश्मरीन्तु सम्प्राप्तमृत्योरपि मूत्रकृच्छ्रम्","text":"trikaṇṭakāragvadhadarbhakāśa durālabhāparvatabhedapathyāḥ nighnanti pītā madhunā'śmarīntu samprāptamṛtyorapi mūtrakṛcchram"},{"type":"verse","number":"39","sanskrit":"निदिग्धिकायाः स्वरसं कुडवं मधुसंयुतम् मूत्रदोषहरं पीत्वा नरः सम्पद्यते सुखी","text":"nidigdhikāyāḥ svarasaṃ kuḍavaṃ madhusaṃyutam mūtradoṣaharaṃ pītvā naraḥ sampadyate sukhī"},{"type":"verse","number":"40","sanskrit":"कषायोऽतिबलामूलसाधितोऽशेषकृच्छ्रजित् पीतञ्च त्रपुसीबीजं सतिलाज्यपयोऽन्वितम्","text":"kaṣāyo'tibalāmūlasādhito'śeṣakṛcchrajit pītañca trapusībījaṃ satilājyapayo'nvitam"},{"type":"verse","number":"41","sanskrit":"त्रिफलायाः सुपिष्टायाः कल्कं कोलसमन्वितम् वारिणा लवणीकृत्य पिबेन्मूत्ररुजाऽपहम्","text":"triphalāyāḥ supiṣṭāyāḥ kalkaṃ kolasamanvitam vāriṇā lavaṇīkṛtya pibenmūtrarujā'paham"},{"type":"verse","number":"42","sanskrit":"यवारुबूकैस्तृणपञ्चमूलीपाषाणभेदैः सशतावरीभिः कृच्छ्रेषु गुग्गुल्वभयाविमिश्रैः कृतः कषायो गुडसम्प्रयुक्तः","text":"yavārubūkaistṛṇapañcamūlīpāṣāṇabhedaiḥ saśatāvarībhiḥ kṛcchreṣu guggulvabhayāvimiśraiḥ kṛtaḥ kaṣāyo guḍasamprayuktaḥ"},{"type":"verse","number":"43","sanskrit":"मूलानि कुशकाशेक्षुशराणां चेक्षुबालिका मूत्राघाताश्मरीकृच्छ्रे पञ्चमूली तृणात्मिका","text":"mūlāni kuśakāśekṣuśarāṇāṃ cekṣubālikā mūtrāghātāśmarīkṛcchre pañcamūlī tṛṇātmikā"},{"type":"verse","number":"44","sanskrit":"गुडमामलकं वृष्यं श्रमघ्नं तर्पणं प्रियम् पित्तासृग्दाहशूलघ्नं मूत्रकृच्छ्रनिवारणम्","text":"guḍamāmalakaṃ vṛṣyaṃ śramaghnaṃ tarpaṇaṃ priyam pittāsṛgdāhaśūlaghnaṃ mūtrakṛcchranivāraṇam"},{"type":"verse","number":"45","sanskrit":"सितातुल्यो यवक्षारः सर्वकृच्छ्रप्रसाधनः द्रा क्षासितोपलाकल्कं कृच्छ्रघ्नं मस्तुना युतम्","text":"sitātulyo yavakṣāraḥ sarvakṛcchraprasādhanaḥ drā kṣāsitopalākalkaṃ kṛcchraghnaṃ mastunā yutam"},{"type":"verse","number":"46","sanskrit":"विदारि सारिवा छागशृङ्गी वत्सादनी निशा कृच्छ्रं पित्तानिलाद्धन्ति वल्लीजं पञ्चमूलकम्","text":"vidāri sārivā chāgaśṛṅgī vatsādanī niśā kṛcchraṃ pittānilāddhanti vallījaṃ pañcamūlakam"},{"type":"verse","number":"47","sanskrit":"एलाऽश्मभेदकशिलाजतुप्पिलीनामेर्वारुबीजलवणोत्तमकुङ्कुमानाम् चूर्णानि तण्डुलजले लुलितानि पीत्वा प्रत्यग्रमृत्युरपि जीवति मूत्रकृच्छ्री","text":"elā'śmabhedakaśilājatuppilīnāmervārubījalavaṇottamakuṅkumānām cūrṇāni taṇḍulajale lulitāni pītvā pratyagramṛtyurapi jīvati mūtrakṛcchrī"},{"type":"verse","number":"48","sanskrit":"अयोरजः सूक्ष्मपिष्टं मधुना सह योजितम् मूत्रकृच्छ्रं निहन्त्याशु त्रिभिर्लेहैर्न संशयः","text":"ayorajaḥ sūkṣmapiṣṭaṃ madhunā saha yojitam mūtrakṛcchraṃ nihantyāśu tribhirlehairna saṃśayaḥ"},{"type":"verse","number":"49","sanskrit":"पुनर्नवामूलतुलां दशमूलं शतावरीम् बलां तुरङ्गगन्धां च तृणमूलं त्रिकण्टकम्","text":"punarnavāmūlatulāṃ daśamūlaṃ śatāvarīm balāṃ turaṅgagandhāṃ ca tṛṇamūlaṃ trikaṇṭakam"},{"type":"verse","number":"50","sanskrit":"विदारिकन्दनागाह्वगुडूच्यतिबलास्तथा पृथग्दशपलान्भागानपां द्रो णे विपाचयेत्","text":"vidārikandanāgāhvaguḍūcyatibalāstathā pṛthagdaśapalānbhāgānapāṃ dro ṇe vipācayet"},{"type":"verse","number":"51","sanskrit":"तेन पादावशेषेण घृतस्यार्धाढकं पचेत् मधुकं शृङ्गबेरञ्च द्रा क्षां सैन्धवपिप्पलीम्","text":"tena pādāvaśeṣeṇa ghṛtasyārdhāḍhakaṃ pacet madhukaṃ śṛṅgaberañca drā kṣāṃ saindhavapippalīm"},{"type":"verse","number":"52","sanskrit":"द्विपलांशान्पृथग्दत्वा यवान्याः कुडवं तथा त्रिंशद्गुडपलान्यत्र तैलस्यैरण्डजस्य च","text":"dvipalāṃśānpṛthagdatvā yavānyāḥ kuḍavaṃ tathā triṃśadguḍapalānyatra tailasyairaṇḍajasya ca"},{"type":"verse","number":"53","sanskrit":"एतदीश्वरपुत्राणां प्राग्भोजनमनिन्दितम् राज्ञां राजसमानानां बहुस्त्रीपतयश्च ये","text":"etadīśvaraputrāṇāṃ prāgbhojanamaninditam rājñāṃ rājasamānānāṃ bahustrīpatayaśca ye"},{"type":"verse","number":"54","sanskrit":"मूत्रकृच्छ्रे कटिस्रस्ते तथा गाढ पुरीषिणाम् मेढ्रवङ्क्षणशूले च योनिशूले च शस्यते","text":"mūtrakṛcchre kaṭisraste tathā gāḍha purīṣiṇām meḍhravaṅkṣaṇaśūle ca yoniśūle ca śasyate"},{"type":"verse","number":"55","sanskrit":"यथोक्तानाञ्च गुल्मानां वातशोणितिनश्च ये बल्यं रसायनं श्रीदं सुकुमारकुमारकम्","text":"yathoktānāñca gulmānāṃ vātaśoṇitinaśca ye balyaṃ rasāyanaṃ śrīdaṃ sukumārakumārakam"},{"type":"verse","number":"56","sanskrit":"पुनर्नवाशते द्रो णः प्रदेयोऽन्येऽपि चापरः","text":"punarnavāśate dro ṇaḥ pradeyo'nye'pi cāparaḥ"},{"type":"verse","number":"57","sanskrit":"इति पञ्चत्रिंशो मूत्रकृच्छ्राधिकारः समाप्तः ३५","text":"iti pañcatriṃśo mūtrakṛcchrādhikāraḥ samāptaḥ 35"}]},{"sthana":"Уттаракханда","number":36,"lang":"sa","content":[{"type":"heading","heading":"Мутрагхата — задержка мочи"},{"type":"verse","number":"1","sanskrit":"जायन्ते कुपितैर्दोषैमूत्राघातास्त्रयोदश प्रायो मूत्रविघाताद्यैर्वातकुण्डलिकाऽदयः","text":"jāyante kupitairdoṣaimūtrāghātāstrayodaśa prāyo mūtravighātādyairvātakuṇḍalikā'dayaḥ"},{"type":"verse","number":"2","sanskrit":"रौक्ष्याद्वेगविघाताद्वा वार्युवस्तौ सवेदनः मूत्रमाविश्य चरति विगुणः कुण्डलीकृतः","text":"raukṣyādvegavighātādvā vāryuvastau savedanaḥ mūtramāviśya carati viguṇaḥ kuṇḍalīkṛtaḥ"},{"type":"verse","number":"3","sanskrit":"मूत्रमल्पाल्पमथवा सरुजं सम्प्रवर्त्तते वातकुण्डलिकां तीव्रां व्याधिं विद्यात्सुदारुणम्","text":"mūtramalpālpamathavā sarujaṃ sampravarttate vātakuṇḍalikāṃ tīvrāṃ vyādhiṃ vidyātsudāruṇam"},{"type":"verse","number":"4","sanskrit":"आध्मापयन्वस्तिगुदं रुद्ध्वा वायुश्चलोन्नताम् कुर्यात्तीव्रार्त्तिमष्ठीलां मूत्रविण्मार्गरोधिनीम्","text":"ādhmāpayanvastigudaṃ ruddhvā vāyuścalonnatām kuryāttīvrārttimaṣṭhīlāṃ mūtraviṇmārgarodhinīm"},{"type":"verse","number":"5","sanskrit":"वेगं विधारयेद्यस्तु मूत्रस्याकुशलो नरः निरुणद्धि मुखं तस्य वस्तेर्वस्तिगतोऽनिलः","text":"vegaṃ vidhārayedyastu mūtrasyākuśalo naraḥ niruṇaddhi mukhaṃ tasya vastervastigato'nilaḥ"},{"type":"verse","number":"6","sanskrit":"मूत्रसङ्गो भवेत्तेन वस्तिकुक्षिनिपीडितः वातवस्तिः स विज्ञेयो व्याधिः कृच्छ्रप्रसाधनः","text":"mūtrasaṅgo bhavettena vastikukṣinipīḍitaḥ vātavastiḥ sa vijñeyo vyādhiḥ kṛcchraprasādhanaḥ"},{"type":"verse","number":"7","sanskrit":"चिरं धारयतो मूत्रं त्वरया न प्रवर्त्तते मेहमानस्य मन्दं वा मूत्रातीतः स उच्यते","text":"ciraṃ dhārayato mūtraṃ tvarayā na pravarttate mehamānasya mandaṃ vā mūtrātītaḥ sa ucyate"},{"type":"verse","number":"8","sanskrit":"मूत्रस्य वेगेऽभिहते तदुदावर्त्तहेतुकः अपानः कुपितो वायुरुदरं पूरयेद् भृशम्","text":"mūtrasya vege'bhihate tadudāvarttahetukaḥ apānaḥ kupito vāyurudaraṃ pūrayed bhṛśam"},{"type":"verse","number":"9","sanskrit":"नाभेरधस्तादाध्मानं जनयेत्तीव्रवेदनम् तन्मूत्रजठरं विद्यादधोवस्तिनिरोधजम्","text":"nābheradhastādādhmānaṃ janayettīvravedanam tanmūtrajaṭharaṃ vidyādadhovastinirodhajam"},{"type":"verse","number":"10","sanskrit":"वस्तौ वाप्यथवा नाले मणौ वा यस्य देहिनः मूत्रं प्रवृत्तं सज्जेत सरक्तंवा प्रवाहतः","text":"vastau vāpyathavā nāle maṇau vā yasya dehinaḥ mūtraṃ pravṛttaṃ sajjeta saraktaṃvā pravāhataḥ"},{"type":"verse","number":"11","sanskrit":"स्रवेच्छनैरल्पमल्पं सरुजं वापि नीरुजम् विगुणानिलजो व्याधिः स मूत्रोत्सङ्गसंज्ञितः","text":"sravecchanairalpamalpaṃ sarujaṃ vāpi nīrujam viguṇānilajo vyādhiḥ sa mūtrotsaṅgasaṃjñitaḥ"},{"type":"verse","number":"12","sanskrit":"रूक्षस्य क्लान्तदेहस्य वस्तिस्थौ पित्तमारुतौ मूत्रक्षयं सरुग्दाहं जनयेतां तदाह्वयम्","text":"rūkṣasya klāntadehasya vastisthau pittamārutau mūtrakṣayaṃ sarugdāhaṃ janayetāṃ tadāhvayam"},{"type":"verse","number":"13","sanskrit":"अन्तर्बस्तिमुखे वृत्तः स्थिरोऽल्प सहसा भवेत् अश्मरी तुल्यरुग्ग्रन्थिर्मूत्रे ग्रन्थिः स उच्यते","text":"antarbastimukhe vṛttaḥ sthiro'lpa sahasā bhavet aśmarī tulyaruggranthirmūtre granthiḥ sa ucyate"},{"type":"verse","number":"14","sanskrit":"मूत्रितस्य स्त्रियं यातो वायुना शुक्रमुद्धृतम् स्थानाच्च्युतं मूत्रयतः प्राक् पश्चाद्वा प्रवर्त्तते भस्मोदकप्रतीकाशं मूत्रशुक्रं तदुच्यते","text":"mūtritasya striyaṃ yāto vāyunā śukramuddhṛtam sthānāccyutaṃ mūtrayataḥ prāk paścādvā pravarttate bhasmodakapratīkāśaṃ mūtraśukraṃ taducyate"},{"type":"verse","number":"15","sanskrit":"व्यायामाध्वातपैः पित्तं वस्तिं प्राप्यानिलावृतम् वस्तिं मेढ्रं गुदञ्चैव प्रदहत् स्रावयेदधः","text":"vyāyāmādhvātapaiḥ pittaṃ vastiṃ prāpyānilāvṛtam vastiṃ meḍhraṃ gudañcaiva pradahat srāvayedadhaḥ"},{"type":"verse","number":"16","sanskrit":"मूत्रं हारिद्र मथवा सरसं रक्तमेव वा कृच्छ्रात्पुनः पुनर्जन्तोरुष्णवातं वदन्ति तम्","text":"mūtraṃ hāridra mathavā sarasaṃ raktameva vā kṛcchrātpunaḥ punarjantoruṣṇavātaṃ vadanti tam"},{"type":"verse","number":"17","sanskrit":"पित्तं कफो द्वावपि वा संहन्यतेऽनिलेन चेत् कृच्छ्रान्मूत्रं तदा पीतं रक्तं श्वेतं घनं स्रवेत्","text":"pittaṃ kapho dvāvapi vā saṃhanyate'nilena cet kṛcchrānmūtraṃ tadā pītaṃ raktaṃ śvetaṃ ghanaṃ sravet"},{"type":"verse","number":"18","sanskrit":"सदाहं रोचनाशङ्खचूर्णवर्णं भवेच्च तत् शुष्कं समस्तवर्णं वा मूत्रसादं वदन्ति तम्","text":"sadāhaṃ rocanāśaṅkhacūrṇavarṇaṃ bhavecca tat śuṣkaṃ samastavarṇaṃ vā mūtrasādaṃ vadanti tam"},{"type":"verse","number":"19","sanskrit":"रूक्षदुर्बलयोर्वातेनोदावर्त्तं शकृद्यदा","text":"rūkṣadurbalayorvātenodāvarttaṃ śakṛdyadā"},{"type":"verse","number":"20","sanskrit":"मूत्रस्रोतोऽनुपद्येत विट्संसृष्टं तदा नरः विड्गन्धं मूत्रयेत्कृच्छ्राद्विडिवघातं विनिर्दिशेत्","text":"mūtrasroto'nupadyeta viṭsaṃsṛṣṭaṃ tadā naraḥ viḍgandhaṃ mūtrayetkṛcchrādviḍivaghātaṃ vinirdiśet"},{"type":"verse","number":"21","sanskrit":"द्रुताध्वलङ्घनायासैरभि घातात्प्रपीडनात् स्वस्थानाद्वस्तिरुद्वृत्तः स्थूलस्तिष्ठिति गर्भवत्","text":"drutādhvalaṅghanāyāsairabhi ghātātprapīḍanāt svasthānādvastirudvṛttaḥ sthūlastiṣṭhiti garbhavat"},{"type":"verse","number":"22","sanskrit":"शूलस्पन्दनदाहार्त्तो विन्दुं बिन्दुं स्रवत्यपि पीडितस्तु सृजेद्धारां संस्तम्भोद्वेष्टनार्त्तिमान्","text":"śūlaspandanadāhārtto vinduṃ binduṃ sravatyapi pīḍitastu sṛjeddhārāṃ saṃstambhodveṣṭanārttimān"},{"type":"verse","number":"23","sanskrit":"वस्तिकुण्डलमाहुस्तं घोरं शस्त्रविषोपमम् पवनप्रबलं प्रायो दुर्निवारमबुद्धिभिः","text":"vastikuṇḍalamāhustaṃ ghoraṃ śastraviṣopamam pavanaprabalaṃ prāyo durnivāramabuddhibhiḥ"},{"type":"verse","number":"24","sanskrit":"तस्मिन् पित्तान्विते दाहः शूलं मूत्रविवर्णता श्लेष्मणा गौरवं शोथः स्निग्धं मूत्रं घनं सितम्","text":"tasmin pittānvite dāhaḥ śūlaṃ mūtravivarṇatā śleṣmaṇā gauravaṃ śothaḥ snigdhaṃ mūtraṃ ghanaṃ sitam"},{"type":"verse","number":"25","sanskrit":"श्लेष्मरुद्धबिलो वस्तिः पित्तोदीर्णो न सिद्ध्य्ति अविभ्रान्तबिलः साध्यो न च यः कुण्डलीकृतः स्याद्बस्तौ कुण्डलीभूते तृण्मोहः श्वास एव च","text":"śleṣmaruddhabilo vastiḥ pittodīrṇo na siddhyti avibhrāntabilaḥ sādhyo na ca yaḥ kuṇḍalīkṛtaḥ syādbastau kuṇḍalībhūte tṛṇmohaḥ śvāsa eva ca"},{"type":"verse","number":"26","sanskrit":"मूत्राघातचिकित्सा स्नेहस्वेदोपपन्नस्य हितं स्नेहविरेचनम् दद्यादुत्तरवस्तिं च मूत्राघाते सवेदने","text":"mūtrāghātacikitsā snehasvedopapannasya hitaṃ snehavirecanam dadyāduttaravastiṃ ca mūtrāghāte savedane"},{"type":"verse","number":"27","sanskrit":"नलकुशकाशेक्षुबलाक्वाथं प्रातः सुशीतलंससितम् पिबतो नश्यति नियतं मूत्रग्रह इत्युवाच कचः","text":"nalakuśakāśekṣubalākvāthaṃ prātaḥ suśītalaṃsasitam pibato naśyati niyataṃ mūtragraha ityuvāca kacaḥ"},{"type":"verse","number":"28","sanskrit":"गोजीनाम्नोमूलं पलमेकं क्वथितशेषितं पीतम् क्षिप्त्वा मधु च सिताञ्च प्रणुदति मूत्रस्य संरोधम्","text":"gojīnāmnomūlaṃ palamekaṃ kvathitaśeṣitaṃ pītam kṣiptvā madhu ca sitāñca praṇudati mūtrasya saṃrodham"},{"type":"verse","number":"29","sanskrit":"गोधापद्या मूलं क्वथितं घृततैलगोरसोन्मिश्रम् पीतं निरुद्धमचिराद्भिनत्ति मूत्रस्य संघातम्","text":"godhāpadyā mūlaṃ kvathitaṃ ghṛtatailagorasonmiśram pītaṃ niruddhamacirādbhinatti mūtrasya saṃghātam"},{"type":"verse","number":"30","sanskrit":"पिबेच्छिलाजतु क्वाथे युक्तं वीरतरादिजे क्वाथं सपत्रमूलस्य गोक्षुरस्य फलस्य च","text":"pibecchilājatu kvāthe yuktaṃ vīratarādije kvāthaṃ sapatramūlasya gokṣurasya phalasya ca"},{"type":"verse","number":"31","sanskrit":"पिबेन्मधुसितायुक्तं मूत्रकृच्छ्ररुजाऽपहम्","text":"pibenmadhusitāyuktaṃ mūtrakṛcchrarujā'paham"},{"type":"verse","number":"32","sanskrit":"घनसारस्य चूर्णेन वस्तस्याथाविकाम्बुना गुण्डयित्वा ध्वजे क्षिप्त्वा मूत्ररोधो जहाति तम्","text":"ghanasārasya cūrṇena vastasyāthāvikāmbunā guṇḍayitvā dhvaje kṣiptvā mūtrarodho jahāti tam"},{"type":"verse","number":"33","sanskrit":"सदाभद्रा ऽश्मभिन्मूलं शतावर्याः सचित्रकम् रोहिणीकोकिलाक्षौ च वचाशैलत्रिकण्टकम्","text":"sadābhadrā 'śmabhinmūlaṃ śatāvaryāḥ sacitrakam rohiṇīkokilākṣau ca vacāśailatrikaṇṭakam"},{"type":"verse","number":"34","sanskrit":"श्लक्ष्णपिष्टः सुरापीतो मूत्राघातप्रबाधनः पिबेद्वर्हिशिखामूलं दुग्धभुक्तण्डुलाम्भसा","text":"ślakṣṇapiṣṭaḥ surāpīto mūtrāghātaprabādhanaḥ pibedvarhiśikhāmūlaṃ dugdhabhuktaṇḍulāmbhasā"},{"type":"verse","number":"35","sanskrit":"वस्तिमुत्तरवस्तिं वा सर्वेषामेव दापयेत् निदिग्धिकायाः स्वरसं पिबेद्वस्त्रात्परिस्रुतम्","text":"vastimuttaravastiṃ vā sarveṣāmeva dāpayet nidigdhikāyāḥ svarasaṃ pibedvastrātparisrutam"},{"type":"verse","number":"36","sanskrit":"जले कुङ्कुमकल्कं वा सक्षौद्र मुषितं निशि सतैलं पाटलाभस्मक्षारं बद्ध्वा परिस्रुतम्","text":"jale kuṅkumakalkaṃ vā sakṣaudra muṣitaṃ niśi satailaṃ pāṭalābhasmakṣāraṃ baddhvā parisrutam"},{"type":"verse","number":"37","sanskrit":"त्रिकण्टकैरण्डशतावरीभिः सिद्धं पयो वा तृणपञ्चमूलैः गुडप्रगाढं सघृतं पयो वा रोगेषु कृच्छ्रादिषु शस्तमेतत्","text":"trikaṇṭakairaṇḍaśatāvarībhiḥ siddhaṃ payo vā tṛṇapañcamūlaiḥ guḍapragāḍhaṃ saghṛtaṃ payo vā rogeṣu kṛcchrādiṣu śastametat"},{"type":"verse","number":"38","sanskrit":"सिताक्षारान्वितं मूलं वायसीतिलकन्दयोः कोशकाररसैः पीतं वस्तिकुण्डलजिद्भवेत्","text":"sitākṣārānvitaṃ mūlaṃ vāyasītilakandayoḥ kośakārarasaiḥ pītaṃ vastikuṇḍalajidbhavet"},{"type":"verse","number":"39","sanskrit":"शृतशीतपयोऽन्नाशी चन्दनं तण्डुलाम्बुना पिबेत्सशर्करं श्रेष्ठमुष्णवाते सशोणिते","text":"śṛtaśītapayo'nnāśī candanaṃ taṇḍulāmbunā pibetsaśarkaraṃ śreṣṭhamuṣṇavāte saśoṇite"},{"type":"verse","number":"40","sanskrit":"शिलोद्भिदैरण्डसमस्थिराभिः पुनर्नवाभीरुरसेषु सिद्धम् तैलं शृतं क्षीरमथानुपानं कालेषु कृच्छ्रादिषु सम्प्रयोज्यम्","text":"śilodbhidairaṇḍasamasthirābhiḥ punarnavābhīruraseṣu siddham tailaṃ śṛtaṃ kṣīramathānupānaṃ kāleṣu kṛcchrādiṣu samprayojyam"},{"type":"verse","number":"41","sanskrit":"धान्य गोक्षुरकक्वाथकल्कयुक्तं घृतं हितम् मूत्राघाते मूत्रकृच्छ्रे शुक्रदोषे च दारुणे","text":"dhānya gokṣurakakvāthakalkayuktaṃ ghṛtaṃ hitam mūtrāghāte mūtrakṛcchre śukradoṣe ca dāruṇe"},{"type":"verse","number":"42","sanskrit":"पाषाणभेदो वाराही शालिमूलं शरस्तथा भल्लातकं शिरीषस्य मूलमेषामथाहरेत्","text":"pāṣāṇabhedo vārāhī śālimūlaṃ śarastathā bhallātakaṃ śirīṣasya mūlameṣāmathāharet"},{"type":"verse","number":"43","sanskrit":"समभागानि सर्वाणि क्वाथयित्वा विचक्षणः पादशेषकषायेण घृतप्रस्थं विपाचयेत्","text":"samabhāgāni sarvāṇi kvāthayitvā vicakṣaṇaḥ pādaśeṣakaṣāyeṇa ghṛtaprasthaṃ vipācayet"},{"type":"verse","number":"44","sanskrit":"कल्कं दत्वाऽथ मतिमान् गिरिजं मधुकं तथा नीलोत्पलञ्च काकोली बीजं त्रापुषमेव च","text":"kalkaṃ datvā'tha matimān girijaṃ madhukaṃ tathā nīlotpalañca kākolī bījaṃ trāpuṣameva ca"},{"type":"verse","number":"45","sanskrit":"कूष्माण्डञ्च तथैर्वारुसम्भवञ्च समं भवेत् उष्णवातं निहन्त्येतद् घृतं भद्रा वहं स्मृतम्","text":"kūṣmāṇḍañca tathairvārusambhavañca samaṃ bhavet uṣṇavātaṃ nihantyetad ghṛtaṃ bhadrā vahaṃ smṛtam"},{"type":"verse","number":"46","sanskrit":"विदारी बृषको यूथी मातुलुङ्गी च भूतृणम् पाषाणभेदः कस्तूरी वसुको वशिरोऽनलः","text":"vidārī bṛṣako yūthī mātuluṅgī ca bhūtṛṇam pāṣāṇabhedaḥ kastūrī vasuko vaśiro'nalaḥ"},{"type":"verse","number":"47","sanskrit":"पुनर्नवा वचा रास्ना बला चातिबला तथा कशेरुविषशृङ्गाटतामलक्यः स्थिराऽदयः","text":"punarnavā vacā rāsnā balā cātibalā tathā kaśeruviṣaśṛṅgāṭatāmalakyaḥ sthirā'dayaḥ"},{"type":"verse","number":"48","sanskrit":"शरेक्षुदर्भमूलञ्च कुशः काशस्तथैव च पलद्वयन्तु संहृत्य जलद्रो णे विपाचयेत्","text":"śarekṣudarbhamūlañca kuśaḥ kāśastathaiva ca paladvayantu saṃhṛtya jaladro ṇe vipācayet"},{"type":"verse","number":"49","sanskrit":"पादशेषे रसे तस्मिन्घृतप्रस्थं विपाचयेत् शतावर्यास्तथा धात्र्याः स्वरसो घृतसम्मितः","text":"pādaśeṣe rase tasminghṛtaprasthaṃ vipācayet śatāvaryāstathā dhātryāḥ svaraso ghṛtasammitaḥ"},{"type":"verse","number":"50","sanskrit":"षट्पलं शर्करायाश्च कार्षिकाण्यपराणि च यष्ट्याह्वं पिप्पलीद्रा क्षाकाश्मर्यं सपरुषकम्","text":"ṣaṭpalaṃ śarkarāyāśca kārṣikāṇyaparāṇi ca yaṣṭyāhvaṃ pippalīdrā kṣākāśmaryaṃ saparuṣakam"},{"type":"verse","number":"51","sanskrit":"एला दुरालभाकौन्तीकुङ्कुमं नागकेशरम् जीवनीयानि चाष्टौ च दत्वा च द्विगुणं पयः","text":"elā durālabhākauntīkuṅkumaṃ nāgakeśaram jīvanīyāni cāṣṭau ca datvā ca dviguṇaṃ payaḥ"},{"type":"verse","number":"52","sanskrit":"एतत्सर्पिर्विपक्तव्यं शनैर्मृद्वग्निना बुधैः मूत्राघातेषु सर्वेषु विशेषात्पित्तजेषु च","text":"etatsarpirvipaktavyaṃ śanairmṛdvagninā budhaiḥ mūtrāghāteṣu sarveṣu viśeṣātpittajeṣu ca"},{"type":"verse","number":"53","sanskrit":"शर्कराऽश्मरिशूलेषुशोणितप्रभवेषु च हृद्रो गे पित्तगुल्मे च वातासृक्पित्तजेषु च","text":"śarkarā'śmariśūleṣuśoṇitaprabhaveṣu ca hṛdro ge pittagulme ca vātāsṛkpittajeṣu ca"},{"type":"verse","number":"54","sanskrit":"कासश्वासक्षतोरस्कधनुः स्त्रीभारकर्षिते तृष्णाच्छर्दिमनः कम्पशोणितच्छर्दने तथा","text":"kāsaśvāsakṣatoraskadhanuḥ strībhārakarṣite tṛṣṇācchardimanaḥ kampaśoṇitacchardane tathā"},{"type":"verse","number":"55","sanskrit":"रक्ते यक्ष्मण्यपस्मारे तथोन्मादे शिरोग्रहे योनिदोषे रजोदोषे शुक्रदोषे स्वरामये","text":"rakte yakṣmaṇyapasmāre tathonmāde śirograhe yonidoṣe rajodoṣe śukradoṣe svarāmaye"},{"type":"verse","number":"56","sanskrit":"एतत्स्मृतिकरं वृष्यं वाजीकरणमुत्तमम् पुत्रदं बलवर्णाढ्यं विशेषाद्वातनाशनम्","text":"etatsmṛtikaraṃ vṛṣyaṃ vājīkaraṇamuttamam putradaṃ balavarṇāḍhyaṃ viśeṣādvātanāśanam"},{"type":"verse","number":"57","sanskrit":"पानभोजननस्येषु न क्वचित्प्रतिहन्यते विदारीघृतमित्युक्तं रसायनमनुत्तमम्","text":"pānabhojananasyeṣu na kvacitpratihanyate vidārīghṛtamityuktaṃ rasāyanamanuttamam"},{"type":"verse","number":"58","sanskrit":"पिष्ट्वाऽखुमलमुष्णेन चारनालेन लिप्यते बद्धमूत्रं निहन्त्याशु तथैव करभीभवम्","text":"piṣṭvā'khumalamuṣṇena cāranālena lipyate baddhamūtraṃ nihantyāśu tathaiva karabhībhavam"},{"type":"verse","number":"59","sanskrit":"स्त्रीणामतिप्रसङ्गेन शोणितं यस्य रिच्यते मैथुनोपरमश्चास्य बृंहणीयो विधिर्हितः","text":"strīṇāmatiprasaṅgena śoṇitaṃ yasya ricyate maithunoparamaścāsya bṛṃhaṇīyo vidhirhitaḥ"},{"type":"verse","number":"60","sanskrit":"ताम्रचूडवसातैलं हितं चोत्तरवस्तिषु स्वगुप्ताफलमृद्वीकाकृष्णेक्षुरसितारजः","text":"tāmracūḍavasātailaṃ hitaṃ cottaravastiṣu svaguptāphalamṛdvīkākṛṣṇekṣurasitārajaḥ"},{"type":"verse","number":"61","sanskrit":"समांशमर्धभागानि क्षीरक्षौद्र घृतानि च सर्वं सम्यग्विमथ्याक्षमात्रं लीढ्वा पयः पिबेत् हन्ति शुक्रक्षयोत्थांश्च दोषान्वन्ध्यासुतप्रदम्","text":"samāṃśamardhabhāgāni kṣīrakṣaudra ghṛtāni ca sarvaṃ samyagvimathyākṣamātraṃ līḍhvā payaḥ pibet hanti śukrakṣayotthāṃśca doṣānvandhyāsutapradam"},{"type":"verse","number":"62","sanskrit":"क्षौद्रा र्द्धभागः कर्त्तव्यो भागः स्यात्क्षीरसर्पिषोः","text":"kṣaudrā rddhabhāgaḥ karttavyo bhāgaḥ syātkṣīrasarpiṣoḥ"},{"type":"verse","number":"63","sanskrit":"शर्करायाश्च चूर्णं च द्रा क्षाचूर्णं च तत्समम् स्वयं गुप्ताफलञ्चैव तथैवेक्षुरसस्य च","text":"śarkarāyāśca cūrṇaṃ ca drā kṣācūrṇaṃ ca tatsamam svayaṃ guptāphalañcaiva tathaivekṣurasasya ca"},{"type":"verse","number":"64","sanskrit":"पिप्पलीनां तथा चूर्णं समभागं प्रदापयेत् तदैकध्यं समानीय खल्ले नातिविमथ्य च","text":"pippalīnāṃ tathā cūrṇaṃ samabhāgaṃ pradāpayet tadaikadhyaṃ samānīya khalle nātivimathya ca"},{"type":"verse","number":"65","sanskrit":"तस्य पाणितलं चूर्णं लिहेत्क्षीरं ततः पिबेत् एतत्सम्यक् प्रयुञ्जानो योनिदोषात्प्रमुच्यते","text":"tasya pāṇitalaṃ cūrṇaṃ lihetkṣīraṃ tataḥ pibet etatsamyak prayuñjāno yonidoṣātpramucyate"},{"type":"verse","number":"66","sanskrit":"कर्पूररसजा युक्ता वस्त्रवर्त्तिः शनैः शनैः मेढमार्गान्तरे न्यस्ता मूत्राघातं व्यपोहति","text":"karpūrarasajā yuktā vastravarttiḥ śanaiḥ śanaiḥ meḍhamārgāntare nyastā mūtrāghātaṃ vyapohati"},{"type":"verse","number":"67","sanskrit":"मूत्रकृच्छ्रेऽश्मरीरोगे भेषजं यत्प्रकीर्त्तितम् मूत्राघातेषु कृच्छ्रेषु तत्कुर्याद् देशकालवित्","text":"mūtrakṛcchre'śmarīroge bheṣajaṃ yatprakīrttitam mūtrāghāteṣu kṛcchreṣu tatkuryād deśakālavit"}]},{"sthana":"Уттаракханда","number":37,"lang":"sa","content":[{"type":"heading","heading":"Ашмари — мочекаменная болезнь"},{"type":"verse","number":"1","sanskrit":"वातपित्तकफैस्तिस्रश्चतुर्थी शुक्रजा मता प्रायः श्लेष्माश्रयाः सर्वा अश्मर्यः स्युर्यमोपमाः","text":"vātapittakaphaistisraścaturthī śukrajā matā prāyaḥ śleṣmāśrayāḥ sarvā aśmaryaḥ syuryamopamāḥ"},{"type":"verse","number":"2","sanskrit":"विशोषयेद्वस्तिगतं सशुक्रं मूत्रं सपित्तं पवनः कफं वा यदा तदाऽश्मर्युपजायते तु क्रमेण पित्तेष्विव रोचना गोः","text":"viśoṣayedvastigataṃ saśukraṃ mūtraṃ sapittaṃ pavanaḥ kaphaṃ vā yadā tadā'śmaryupajāyate tu krameṇa pitteṣviva rocanā goḥ"},{"type":"verse","number":"3","sanskrit":"नैकदोषाश्रयाः सर्वा अथासां पूर्वलक्षणम् वस्त्याध्मानं तदासन्नदेशेषु परितोऽतिरुक् मूत्रे बस्तसगन्धत्वं मूत्रकृच्छ्रं ज्वरोऽरुचिः","text":"naikadoṣāśrayāḥ sarvā athāsāṃ pūrvalakṣaṇam vastyādhmānaṃ tadāsannadeśeṣu parito'tiruk mūtre bastasagandhatvaṃ mūtrakṛcchraṃ jvaro'ruciḥ"},{"type":"verse","number":"4","sanskrit":"सामान्यलिङ्गं रुग् नाभिसेवनीवस्तिमूर्द्धसु विशीर्णधारं मूत्रं स्यात्तया मार्गनिरोधने","text":"sāmānyaliṅgaṃ rug nābhisevanīvastimūrddhasu viśīrṇadhāraṃ mūtraṃ syāttayā mārganirodhane"},{"type":"verse","number":"5","sanskrit":"तद्व्यपायात्सुखं मेहेदच्छं गोमेदकोपमम् तत्संक्षोभात्क्षते सास्रमायासाच्चातिरुग्भवेत्","text":"tadvyapāyātsukhaṃ mehedacchaṃ gomedakopamam tatsaṃkṣobhātkṣate sāsramāyāsāccātirugbhavet"},{"type":"verse","number":"6","sanskrit":"तत्र वाताद् भृशं चार्त्तो दन्तान्खादति वेपते मृद्नाति मेहनं नाभिं पीडयत्यनिशं क्वणन्","text":"tatra vātād bhṛśaṃ cārtto dantānkhādati vepate mṛdnāti mehanaṃ nābhiṃ pīḍayatyaniśaṃ kvaṇan"},{"type":"verse","number":"7","sanskrit":"सानिलं मुञ्चति शकृन्मुहुर्मेहति बिन्दुशः श्यावा रूक्षाश्मरी सा स्यात्सञ्चिता कण्टकैरिव","text":"sānilaṃ muñcati śakṛnmuhurmehati binduśaḥ śyāvā rūkṣāśmarī sā syātsañcitā kaṇṭakairiva"},{"type":"verse","number":"8","sanskrit":"तस्याः पूर्वेषु रूपेषु स्नेहादिक्रम इष्यते","text":"tasyāḥ pūrveṣu rūpeṣu snehādikrama iṣyate"},{"type":"verse","number":"9","sanskrit":"शुण्ठ्यग्निमन्थपाषाणशिग्रुवरुणगोक्षुरैः काश्मर्यारग्वधफलैः क्वाथं कृत्वा विचक्षणः","text":"śuṇṭhyagnimanthapāṣāṇaśigruvaruṇagokṣuraiḥ kāśmaryāragvadhaphalaiḥ kvāthaṃ kṛtvā vicakṣaṇaḥ"},{"type":"verse","number":"10","sanskrit":"रामठक्षारलवणचूर्णं दत्वा पिबेन्नरः अश्मरीमूत्रकृच्छघ्नं दीपनं पाचनं परम् हन्यात्कोष्ठाश्रितं वातं कट्यूरुगुदमेढ्रजम्","text":"rāmaṭhakṣāralavaṇacūrṇaṃ datvā pibennaraḥ aśmarīmūtrakṛcchaghnaṃ dīpanaṃ pācanaṃ param hanyātkoṣṭhāśritaṃ vātaṃ kaṭyūrugudameḍhrajam"},{"type":"verse","number":"11","sanskrit":"एलोपकुल्यामधुकाश्मभेदकौन्तीश्वदंष्ट्रावृषकोरुबूकैः शृतं पिबेदश्मजतु प्रगाढं सशर्करे चाश्मरिमूत्रकृच्छ्रे","text":"elopakulyāmadhukāśmabhedakauntīśvadaṃṣṭrāvṛṣakorubūkaiḥ śṛtaṃ pibedaśmajatu pragāḍhaṃ saśarkare cāśmarimūtrakṛcchre"},{"type":"verse","number":"12","sanskrit":"वरुणस्य त्वचं श्रेष्ठां शुण्ठीं गोक्षुरसंयुताम् यवक्षारगुडं दत्वा क्वाथयित्वा पिबेद्धिमम् अश्मरीं वातजां हन्ति चिरकालानुबन्धिनीम्","text":"varuṇasya tvacaṃ śreṣṭhāṃ śuṇṭhīṃ gokṣurasaṃyutām yavakṣāraguḍaṃ datvā kvāthayitvā pibeddhimam aśmarīṃ vātajāṃ hanti cirakālānubandhinīm"},{"type":"verse","number":"13","sanskrit":"पाषाणभेदो वसुको वशिरोऽश्मन्तकस्तथा शतावरी श्वदंष्ट्रा च बृहती कण्टकारिका","text":"pāṣāṇabhedo vasuko vaśiro'śmantakastathā śatāvarī śvadaṃṣṭrā ca bṛhatī kaṇṭakārikā"},{"type":"verse","number":"14","sanskrit":"कपोतवङ्कार्त्तगलकाञ्चनोशीरगुन्द्र काः वृक्षादनी भल्लुकश्च वरुणः शाकजं फलम्","text":"kapotavaṅkārttagalakāñcanośīragundra kāḥ vṛkṣādanī bhallukaśca varuṇaḥ śākajaṃ phalam"},{"type":"verse","number":"15","sanskrit":"यवाः कुलत्थाः कोलानि कतकस्य फलानि च","text":"yavāḥ kulatthāḥ kolāni katakasya phalāni ca"},{"type":"verse","number":"16","sanskrit":"ऊषकादिप्रतीवापमेषां क्वाथे शृतं घृतम् भिनत्ति वातसम्भूतामश्मरीं क्षिप्रमेव तु","text":"ūṣakādipratīvāpameṣāṃ kvāthe śṛtaṃ ghṛtam bhinatti vātasambhūtāmaśmarīṃ kṣiprameva tu"},{"type":"verse","number":"17","sanskrit":"क्षारान्यवागूः पेयाश्चकषायांश्च पयांसि च भोजनानि प्रकुर्वीत वर्गेऽस्मिन्वातनाशने","text":"kṣārānyavāgūḥ peyāścakaṣāyāṃśca payāṃsi ca bhojanāni prakurvīta varge'sminvātanāśane"},{"type":"verse","number":"18","sanskrit":"वीरवृक्षोग्निमन्थश्च काशवृक्षादनीकुशाः मोरटेन्दीवरीसूर्यभक्तागोक्षुरटुण्टुकाः","text":"vīravṛkṣognimanthaśca kāśavṛkṣādanīkuśāḥ moraṭendīvarīsūryabhaktāgokṣuraṭuṇṭukāḥ"},{"type":"verse","number":"19","sanskrit":"वसुको वशिरो दर्भशैरीयावश्मभेदकः गुन्द्रो नलः कुरुण्टश्च गणो वीरतरादिकः","text":"vasuko vaśiro darbhaśairīyāvaśmabhedakaḥ gundro nalaḥ kuruṇṭaśca gaṇo vīratarādikaḥ"},{"type":"verse","number":"20","sanskrit":"अश्मरीशर्कराकृच्छ्रमारुतार्त्तिहरो मतः बृहद्वाते वीरतरस्तदभावे मतः शरः","text":"aśmarīśarkarākṛcchramārutārttiharo mataḥ bṛhadvāte vīratarastadabhāve mataḥ śaraḥ"},{"type":"verse","number":"21","sanskrit":"पित्तेन दह्यते वस्तिः पच्यमान इवोष्मणा भल्लातकास्थिसंस्थाना रक्ता पीता सिताश्मरी","text":"pittena dahyate vastiḥ pacyamāna ivoṣmaṇā bhallātakāsthisaṃsthānā raktā pītā sitāśmarī"},{"type":"verse","number":"22","sanskrit":"अथ पित्ताश्मरीचिकित्सा कुशः काशः शरो गुन्द्र इत्कटो मोरटाश्मभित् दर्भो विदारी वाराही शालिमूलं त्रिकण्टकः","text":"atha pittāśmarīcikitsā kuśaḥ kāśaḥ śaro gundra itkaṭo moraṭāśmabhit darbho vidārī vārāhī śālimūlaṃ trikaṇṭakaḥ"},{"type":"verse","number":"23","sanskrit":"भल्लुकः पाटला पाठा पत्तूरोऽथ कुरुण्टकः पुनर्नवा शिरीषश्च क्वथितास्तेषु साधितम्","text":"bhallukaḥ pāṭalā pāṭhā pattūro'tha kuruṇṭakaḥ punarnavā śirīṣaśca kvathitāsteṣu sādhitam"},{"type":"verse","number":"24","sanskrit":"घृतं शिलाऽह्वमधुकैर्बीजैरिन्दीवरस्य च त्रपुसैर्वारुकादीनां बीजैश्चावापितं शुभम् भिनत्ति पित्तसंभूतामश्मरीं क्षिप्रमेव च","text":"ghṛtaṃ śilā'hvamadhukairbījairindīvarasya ca trapusairvārukādīnāṃ bījaiścāvāpitaṃ śubham bhinatti pittasaṃbhūtāmaśmarīṃ kṣiprameva ca"},{"type":"verse","number":"25","sanskrit":"क्षारान्यवागूः पेयाश्च कषायांश्च पयांसि च भोजनानि च कुर्वीत वर्गेऽस्मिन्पित्तनाशने","text":"kṣārānyavāgūḥ peyāśca kaṣāyāṃśca payāṃsi ca bhojanāni ca kurvīta varge'sminpittanāśane"},{"type":"verse","number":"26","sanskrit":"मधुकः कृतह्रस्वत्वाद्वीजैर्बीजकमुच्यते शिलाजतु शिलाऽह्व स्यात्पटीरो गुत्थगुन्द्र कौ","text":"madhukaḥ kṛtahrasvatvādvījairbījakamucyate śilājatu śilā'hva syātpaṭīro gutthagundra kau"},{"type":"verse","number":"27","sanskrit":"कुर्यात्क्षीरादिकं क्वाथे तस्मिन्क्षेपमावापकैः वर्गत्वेन यथालाभं परिभाषा प्रवर्त्तते","text":"kuryātkṣīrādikaṃ kvāthe tasminkṣepamāvāpakaiḥ vargatvena yathālābhaṃ paribhāṣā pravarttate"},{"type":"verse","number":"28","sanskrit":"वस्तिर्निस्तुद्यत इव श्लेष्मणा शीतलो गुरुः अश्मरी महती श्लक्ष्णा मधुवर्णाऽथवा सिता","text":"vastirnistudyata iva śleṣmaṇā śītalo guruḥ aśmarī mahatī ślakṣṇā madhuvarṇā'thavā sitā"},{"type":"verse","number":"29","sanskrit":"एता भवन्ति बालानां तेषामेव तु भूयसा आश्रयोपचयाल्पत्वाद् ग्रहणाहरणे सुखाः","text":"etā bhavanti bālānāṃ teṣāmeva tu bhūyasā āśrayopacayālpatvād grahaṇāharaṇe sukhāḥ"},{"type":"verse","number":"30","sanskrit":"अथ कफाश्मरीचिकित्सा गणे वरुणकादौ तु गुग्गुल्वेलाहरेणुभिः कुष्ठभद्रा ह्वमरिचचित्रकैः ससुराह्वयैः एतैः सिद्धमजासर्पिरुषकादिगणेन च","text":"atha kaphāśmarīcikitsā gaṇe varuṇakādau tu guggulvelāhareṇubhiḥ kuṣṭhabhadrā hvamaricacitrakaiḥ sasurāhvayaiḥ etaiḥ siddhamajāsarpiruṣakādigaṇena ca"},{"type":"verse","number":"31","sanskrit":"भिनत्ति कफसम्भूतामश्मरीं क्षिप्रमेव च शट्यादिस्तेन चात्रेष्टो गणः श्यामाऽदिको बुधः","text":"bhinatti kaphasambhūtāmaśmarīṃ kṣiprameva ca śaṭyādistena cātreṣṭo gaṇaḥ śyāmā'diko budhaḥ"},{"type":"verse","number":"32","sanskrit":"वरुणार्त्तगलौ शिग्रुस्तर्कारीनक्तमालकौ मोरटारणिबिल्वाश्च बिम्वीवसुकचित्रकाः","text":"varuṇārttagalau śigrustarkārīnaktamālakau moraṭāraṇibilvāśca bimvīvasukacitrakāḥ"},{"type":"verse","number":"33","sanskrit":"शैरीयो वशिरोऽक्षीवश्चाजशृङ्गी शतावरी दर्भो बृहतिका व्याघ्री मुनिभिः परिकीर्त्तितः वरुणादिगणो ह्येष कफमेदोनिवारणः विनिहन्ति शिरः शूलं गुल्माभ्यन्तरविद्र धीन्","text":"śairīyo vaśiro'kṣīvaścājaśṛṅgī śatāvarī darbho bṛhatikā vyāghrī munibhiḥ parikīrttitaḥ varuṇādigaṇo hyeṣa kaphamedonivāraṇaḥ vinihanti śiraḥ śūlaṃ gulmābhyantaravidra dhīn"},{"type":"verse","number":"34","sanskrit":"क्षारान्यवागूः पेयाश्च कषायाश्च पयांसि च भोजनानि च कुर्वीत वर्गेऽस्मिन्कफनाशने","text":"kṣārānyavāgūḥ peyāśca kaṣāyāśca payāṃsi ca bhojanāni ca kurvīta varge'sminkaphanāśane"},{"type":"verse","number":"35","sanskrit":"शुक्राश्मरी तु महती जायते शुक्रधारणात्","text":"śukrāśmarī tu mahatī jāyate śukradhāraṇāt"},{"type":"verse","number":"36","sanskrit":"स्थानाच्च्युतममुक्तं हि मुष्कयोरन्तरेऽनिलः शोषयित्वोपसंहृत्य शुक्रं तच्छुक्रमश्मरी","text":"sthānāccyutamamuktaṃ hi muṣkayorantare'nilaḥ śoṣayitvopasaṃhṛtya śukraṃ tacchukramaśmarī"},{"type":"verse","number":"37","sanskrit":"वस्तिरुक्कृच्छ्रमूत्रत्वमुष्कश्वयथुकारिणी तस्यामुत्पन्नमात्रायां शुक्रमेति विलीयते पीडिते त्ववकाशेऽस्मिन्नश्मर्येव च शर्करा","text":"vastirukkṛcchramūtratvamuṣkaśvayathukāriṇī tasyāmutpannamātrāyāṃ śukrameti vilīyate pīḍite tvavakāśe'sminnaśmaryeva ca śarkarā"},{"type":"verse","number":"38","sanskrit":"सा भिन्नमूर्त्तिर्वातेन शर्करेत्यभिधीयते","text":"sā bhinnamūrttirvātena śarkaretyabhidhīyate"},{"type":"verse","number":"39","sanskrit":"अणुशो वायुना भिन्ना सा तस्मिन्ननुलोमगे निरेति सह मूत्रेण प्रतिलोमे निरुध्यते मूत्रस्रोतःप्रवृत्ता सा सक्ता कुर्यादुपद्र वान्","text":"aṇuśo vāyunā bhinnā sā tasminnanulomage nireti saha mūtreṇa pratilome nirudhyate mūtrasrotaḥpravṛttā sā saktā kuryādupadra vān"},{"type":"verse","number":"40","sanskrit":"दौर्बल्यं सदनं कार्श्यं कुक्षिरोगमथारुचिम् पाण्डुत्वमुष्णवातञ्च तृष्णां हृत्पीडनं वमिम्","text":"daurbalyaṃ sadanaṃ kārśyaṃ kukṣirogamathārucim pāṇḍutvamuṣṇavātañca tṛṣṇāṃ hṛtpīḍanaṃ vamim"},{"type":"verse","number":"41","sanskrit":"प्रसूननाभिवृषणं बद्धमूत्रं रुजाऽतुरम् अश्मरी क्षपयत्याशु शर्करा सिकताऽन्विता","text":"prasūnanābhivṛṣaṇaṃ baddhamūtraṃ rujā'turam aśmarī kṣapayatyāśu śarkarā sikatā'nvitā"},{"type":"verse","number":"42","sanskrit":"शुक्राश्मर्यान्तु सामान्यो विधिरश्मरिनाशनः यवक्षारगुडोन्मिश्रं रसं पुष्पफलोद्भवम्","text":"śukrāśmaryāntu sāmānyo vidhiraśmarināśanaḥ yavakṣāraguḍonmiśraṃ rasaṃ puṣpaphalodbhavam"},{"type":"verse","number":"43","sanskrit":"पिबेन्मूत्रविबन्धघ्नं शर्कराऽश्मरिनाशनम् तिलापामार्गकदलीपलाशयवबिल्वजः","text":"pibenmūtravibandhaghnaṃ śarkarā'śmarināśanam tilāpāmārgakadalīpalāśayavabilvajaḥ"},{"type":"verse","number":"44","sanskrit":"क्वाथः पेयोऽविमूत्रेण शर्कराऽश्मरिनाशनः","text":"kvāthaḥ peyo'vimūtreṇa śarkarā'śmarināśanaḥ"},{"type":"verse","number":"45","sanskrit":"केबुकाङ्कोलकतकशाकेन्दीवरजैः फलैः पीतमुष्णाम्बु सगुडं शर्करां पातयत्यधः","text":"kebukāṅkolakatakaśākendīvarajaiḥ phalaiḥ pītamuṣṇāmbu saguḍaṃ śarkarāṃ pātayatyadhaḥ"},{"type":"verse","number":"46","sanskrit":"पाषाणभिद्गोक्षुरकोरुवूकौ द्बे कण्टकार्ये क्षुरकाह्वमूलम् दध्ना पिबेत्क्षीरसुपिष्टमेतत् स्याद् भेदनार्थं सिकताऽश्मरीणाम्","text":"pāṣāṇabhidgokṣurakoruvūkau dbe kaṇṭakārye kṣurakāhvamūlam dadhnā pibetkṣīrasupiṣṭametat syād bhedanārthaṃ sikatā'śmarīṇām"},{"type":"verse","number":"47","sanskrit":"यः पिबेद्र जनीं सम्यक् सगुडां तुषवारिणा तस्याशु चिररूढाऽपि यात्यस्तं मेढ्रशर्करा","text":"yaḥ pibedra janīṃ samyak saguḍāṃ tuṣavāriṇā tasyāśu cirarūḍhā'pi yātyastaṃ meḍhraśarkarā"},{"type":"verse","number":"48","sanskrit":"पिबतः कुटजं दध्ना पथ्यमन्नञ्च खादतः निपतन्त्यचिरात्तस्य नियतं मेढ्रशर्कराः","text":"pibataḥ kuṭajaṃ dadhnā pathyamannañca khādataḥ nipatantyacirāttasya niyataṃ meḍhraśarkarāḥ"},{"type":"verse","number":"49","sanskrit":"त्रापुसबीजं पयसा पीतं वा नारिकेरजं कुसुमम् विण्मूत्रशर्करायां भवति सुखी कतिपयैर्दिवसैः","text":"trāpusabījaṃ payasā pītaṃ vā nārikerajaṃ kusumam viṇmūtraśarkarāyāṃ bhavati sukhī katipayairdivasaiḥ"},{"type":"verse","number":"50","sanskrit":"श्वदंष्ट्रा वरुणः शुण्ठीक्वाथं क्षौद्र युतं पिबेत् शर्कराऽश्मरिशूलघ्नं मूत्रकृच्छ्रहरं परम्","text":"śvadaṃṣṭrā varuṇaḥ śuṇṭhīkvāthaṃ kṣaudra yutaṃ pibet śarkarā'śmariśūlaghnaṃ mūtrakṛcchraharaṃ param"},{"type":"verse","number":"51","sanskrit":"कूष्माण्डकरसो हिङ्गुयवक्षारसमायुतः वस्तौ मेढ्रे सशूलघ्नो मूत्रकृच्छ्रहरः परम्","text":"kūṣmāṇḍakaraso hiṅguyavakṣārasamāyutaḥ vastau meḍhre saśūlaghno mūtrakṛcchraharaḥ param"},{"type":"verse","number":"52","sanskrit":"पुनर्नवाऽयो रजनी श्वदंष्ट्रा वरी प्रवालश्च सदर्भपुष्पः क्षीराम्रमद्येक्षुरसप्रपिष्टो हितो भवेदश्मरिशर्करासु","text":"punarnavā'yo rajanī śvadaṃṣṭrā varī pravālaśca sadarbhapuṣpaḥ kṣīrāmramadyekṣurasaprapiṣṭo hito bhavedaśmariśarkarāsu"},{"type":"verse","number":"53","sanskrit":"वरुणत्वक्छिलाभेदशुण्ठीगोक्षुरकैः कृतः कषायः क्षारसंयुक्तः शर्कराश्च भिनत्यपि","text":"varuṇatvakchilābhedaśuṇṭhīgokṣurakaiḥ kṛtaḥ kaṣāyaḥ kṣārasaṃyuktaḥ śarkarāśca bhinatyapi"},{"type":"verse","number":"54","sanskrit":"पञ्चमूल्यास्तृणाख्यायास्तथा गोक्षुरकस्य तु पृथग्दशपलान्भागाञ्जलद्रो णे विपाचयेत्","text":"pañcamūlyāstṛṇākhyāyāstathā gokṣurakasya tu pṛthagdaśapalānbhāgāñjaladro ṇe vipācayet"},{"type":"verse","number":"55","sanskrit":"तत्सिद्धं मूत्रदोषेषु शर्करास्वश्मरीषु च चतुर्भागावशिष्टेन घृतप्रस्थं विपाचयेत् गुडगोक्षुरबीजञ्च कल्कं तत्र प्रदापयेत्","text":"tatsiddhaṃ mūtradoṣeṣu śarkarāsvaśmarīṣu ca caturbhāgāvaśiṣṭena ghṛtaprasthaṃ vipācayet guḍagokṣurabījañca kalkaṃ tatra pradāpayet"},{"type":"verse","number":"56","sanskrit":"तत्सिद्धंमूत्रदोषेषु शर्करास्वश्मरीषु च स्नेहने भोजने चैव प्रयोज्यं सर्पिरुत्तमम्","text":"tatsiddhaṃmūtradoṣeṣu śarkarāsvaśmarīṣu ca snehane bhojane caiva prayojyaṃ sarpiruttamam"},{"type":"verse","number":"57","sanskrit":"त्वक्पत्रफलमूलस्य वरुणस्य त्रिकण्टकात् कषायेण पचेत्तैलं वस्तिनाऽस्थापनेन च शर्कराऽश्मरिशूलघ्नं मूत्रकृच्छ्रात्प्रमुच्यते","text":"tvakpatraphalamūlasya varuṇasya trikaṇṭakāt kaṣāyeṇa pacettailaṃ vastinā'sthāpanena ca śarkarā'śmariśūlaghnaṃ mūtrakṛcchrātpramucyate"},{"type":"verse","number":"58","sanskrit":"कुशाग्निमन्थशैरीयनल दर्भेक्षुगोक्षुराः कपोतवङ्कावसुकवशि रेन्दीवरीशराः","text":"kuśāgnimanthaśairīyanala darbhekṣugokṣurāḥ kapotavaṅkāvasukavaśi rendīvarīśarāḥ"},{"type":"verse","number":"59","sanskrit":"धातक्यरलुवन्दाकाः कर्णपूराश्मभेदकाः एषां कल्ककषायाभ्यां सिद्धं तैलं प्रयोजयेत्","text":"dhātakyaraluvandākāḥ karṇapūrāśmabhedakāḥ eṣāṃ kalkakaṣāyābhyāṃ siddhaṃ tailaṃ prayojayet"},{"type":"verse","number":"60","sanskrit":"पानाभ्यञ्जनयोगेन वस्तिनोत्तरवस्तिना शर्कराश्मरिरोगेषु मूत्रकृच्छ्रं च दारुणे","text":"pānābhyañjanayogena vastinottaravastinā śarkarāśmarirogeṣu mūtrakṛcchraṃ ca dāruṇe"},{"type":"verse","number":"61","sanskrit":"प्रदरे योनिशूले च शुक्रदोषे तथैव च वन्ध्यागर्भप्रदं प्रोक्तं तैलमेतत्कुशादिकम्","text":"pradare yoniśūle ca śukradoṣe tathaiva ca vandhyāgarbhapradaṃ proktaṃ tailametatkuśādikam"},{"type":"verse","number":"62","sanskrit":"नागरवारुणगोक्षुर पाषाणभित्कपोतवङ्कजः क्वाथः गुडयवशूकविमिश्रः पीतो हन्त्यश्मरीमुग्राम्","text":"nāgaravāruṇagokṣura pāṣāṇabhitkapotavaṅkajaḥ kvāthaḥ guḍayavaśūkavimiśraḥ pīto hantyaśmarīmugrām"},{"type":"verse","number":"63","sanskrit":"त्रिकण्टकस्य बीजानां चूर्णं माक्षिकसंयुतम् अविक्षीरेण सप्ताहं पेयमश्मरिनाशनम्","text":"trikaṇṭakasya bījānāṃ cūrṇaṃ mākṣikasaṃyutam avikṣīreṇa saptāhaṃ peyamaśmarināśanam"},{"type":"verse","number":"64","sanskrit":"पिबेद्वरुणजं मूलं क्वाथं तत्कल्कसंयुतम् क्वाथश्च शिग्रुमूलोत्थः कदुष्णोऽश्मरिनाशनः","text":"pibedvaruṇajaṃ mūlaṃ kvāthaṃ tatkalkasaṃyutam kvāthaśca śigrumūlotthaḥ kaduṣṇo'śmarināśanaḥ"},{"type":"verse","number":"65","sanskrit":"शृङ्गवेरयवक्षार पथ्याकालीयकान्वितः दधिमण्डो भिनत्त्युग्रामश्मरीमाशु पानतः","text":"śṛṅgaverayavakṣāra pathyākālīyakānvitaḥ dadhimaṇḍo bhinattyugrāmaśmarīmāśu pānataḥ"},{"type":"verse","number":"66","sanskrit":"पाषाणभेदवरुणगोक्षुरककपोतवङ्कजः क्वाथः गिरिजतुगुडप्रगाढः कर्कटिकात्रपुसबीजयुतः","text":"pāṣāṇabhedavaruṇagokṣurakakapotavaṅkajaḥ kvāthaḥ girijatuguḍapragāḍhaḥ karkaṭikātrapusabījayutaḥ"},{"type":"verse","number":"67","sanskrit":"पेयोऽश्मरीमवश्यं दुर्भेदामपि भिनत्ति योगवरः शिखरिणमिव शतकोटिः शतमन्योर्हस्तनिर्मुक्तः","text":"peyo'śmarīmavaśyaṃ durbhedāmapi bhinatti yogavaraḥ śikhariṇamiva śatakoṭiḥ śatamanyorhastanirmuktaḥ"},{"type":"verse","number":"68","sanskrit":"श्रीकरिणीफलबीजं पिष्टं मथितेन यः पुमानद्यात् शाकमशितमथवाऽस्या हन्याद् रोगाश्मरीपीडाम्","text":"śrīkariṇīphalabījaṃ piṣṭaṃ mathitena yaḥ pumānadyāt śākamaśitamathavā'syā hanyād rogāśmarīpīḍām"},{"type":"verse","number":"69","sanskrit":"श्वदंष्ट्रैरण्डबीजानि नागरं वरुणत्वचः एतत्क्वाथवरं प्रातः पिबेदश्मरिनाशनम्","text":"śvadaṃṣṭrairaṇḍabījāni nāgaraṃ varuṇatvacaḥ etatkvāthavaraṃ prātaḥ pibedaśmarināśanam"},{"type":"verse","number":"70","sanskrit":"रक्तोद्भवे रुक्षमृणालतालकाशेक्षुबालेक्षुकुशोदकानि पिबेत्सिताक्षौद्र युतानि खादेद्विदारिमिक्षुत्रपुसानि चैव","text":"raktodbhave rukṣamṛṇālatālakāśekṣubālekṣukuśodakāni pibetsitākṣaudra yutāni khādedvidārimikṣutrapusāni caiva"},{"type":"verse","number":"71","sanskrit":"पलान्यष्टौ तु कुर्वीत क्षाराणां वरुणत्वचाम् तदर्द्धं यावशूकन्तु ततोऽप्यर्द्धं गुडात्स्मृतम्","text":"palānyaṣṭau tu kurvīta kṣārāṇāṃ varuṇatvacām tadarddhaṃ yāvaśūkantu tato'pyarddhaṃ guḍātsmṛtam"},{"type":"verse","number":"72","sanskrit":"एकीकृत्य विमृद्यैतत्खादेत्कर्षप्रमाणतः घर्माग्बुपानतोऽवश्यं कृच्छ्राश्मरिविनाशनम्","text":"ekīkṛtya vimṛdyaitatkhādetkarṣapramāṇataḥ gharmāgbupānato'vaśyaṃ kṛcchrāśmarivināśanam"},{"type":"verse","number":"73","sanskrit":"वरुणकभस्मपरिस्रुतसलिलं तच्चूर्णं यावशूकयुतम् क्वथनीयं तत्तावद्यावच्चूर्णत्वमायाति","text":"varuṇakabhasmaparisrutasalilaṃ taccūrṇaṃ yāvaśūkayutam kvathanīyaṃ tattāvadyāvaccūrṇatvamāyāti"},{"type":"verse","number":"74","sanskrit":"तद्गुडयुक्तं हन्यात्तदुदारामश्मरीं घोराम् प्लीहानं गुल्मवरं श्रोण्यां कुक्षौ रुजां तीव्राम्","text":"tadguḍayuktaṃ hanyāttadudārāmaśmarīṃ ghorām plīhānaṃ gulmavaraṃ śroṇyāṃ kukṣau rujāṃ tīvrām"},{"type":"verse","number":"75","sanskrit":"आमचयं बस्तिगदान्कृच्छ्रं वा वातजं घोरम् वह्निसदनं सुकष्टामश्ममयीमश्मरीञ्चाशु","text":"āmacayaṃ bastigadānkṛcchraṃ vā vātajaṃ ghoram vahnisadanaṃ sukaṣṭāmaśmamayīmaśmarīñcāśu"},{"type":"verse","number":"76","sanskrit":"नो जग्धं कृमिभिर्घनं सुतरुणं स्निग्धं शुचिस्थानजं घस्रे पुण्यनिरीक्षिते वरुणकं छित्वा तुलां ग्राहयेत् संगृह्माशु चतुर्गुणासु विपचेत्पादावशेषं जलं तत्तुल्येन गुडेन वै दृढतरे भाण्डे पचेत्तत्पुनः","text":"no jagdhaṃ kṛmibhirghanaṃ sutaruṇaṃ snigdhaṃ śucisthānajaṃ ghasre puṇyanirīkṣite varuṇakaṃ chitvā tulāṃ grāhayet saṃgṛhmāśu caturguṇāsu vipacetpādāvaśeṣaṃ jalaṃ tattulyena guḍena vai dṛḍhatare bhāṇḍe pacettatpunaḥ"},{"type":"verse","number":"77","sanskrit":"ज्ञात्वैवं घनतां गुडे परिणते प्रत्येकमेषां पलं शुण्ठ्येर्वारुकबीजगोक्षुरकणापाषाणभिच्छीतलाः कूष्माण्डात्रपुसाक्षबीजकुनटीवास्तूकशोभाञ्जनैः द्रा क्षैलागिरिजाभयाकृमिहृतां चूर्णीकृतानां क्षिपेत्","text":"jñātvaivaṃ ghanatāṃ guḍe pariṇate pratyekameṣāṃ palaṃ śuṇṭhyervārukabījagokṣurakaṇāpāṣāṇabhicchītalāḥ kūṣmāṇḍātrapusākṣabījakunaṭīvāstūkaśobhāñjanaiḥ drā kṣailāgirijābhayākṛmihṛtāṃ cūrṇīkṛtānāṃ kṣipet"},{"type":"verse","number":"78","sanskrit":"पथ्याशी प्रतिवासरं गुडममुं युञ्ज्यात्प्रमाणं नरः खादेत्तस्य समस्तदोषजनिताश्मर्यः पतन्ति द्रुतम्","text":"pathyāśī prativāsaraṃ guḍamamuṃ yuñjyātpramāṇaṃ naraḥ khādettasya samastadoṣajanitāśmaryaḥ patanti drutam"},{"type":"verse","number":"79","sanskrit":"कुलत्थसिन्धूत्थविडङ्गसारं सशर्करं शीतलियावशूकम् बीजानि कूष्माण्डकगोक्षुराभ्यां घृतं पचेत्तद्वरुणस्य तोये","text":"kulatthasindhūtthaviḍaṅgasāraṃ saśarkaraṃ śītaliyāvaśūkam bījāni kūṣmāṇḍakagokṣurābhyāṃ ghṛtaṃ pacettadvaruṇasya toye"},{"type":"verse","number":"80","sanskrit":"दुःसाध्यसर्वाश्मरिमूत्रकृच्छ्रं मूत्राभिघातञ्च समूत्रबन्धम् आमूलमेतानि निहन्ति शीघ्रं प्ररूढवृक्षानिव वज्रपातः","text":"duḥsādhyasarvāśmarimūtrakṛcchraṃ mūtrābhighātañca samūtrabandham āmūlametāni nihanti śīghraṃ prarūḍhavṛkṣāniva vajrapātaḥ"},{"type":"verse","number":"81","sanskrit":"शरादिपञ्चमूल्या वा कषायेण पचेद् घृतम् प्रस्थं गोक्षुरकल्केन सिद्धमद्यात्सशर्करम् अश्मरीमूत्रकृच्छघ्नं रेतोमार्गरुजाऽपहम्","text":"śarādipañcamūlyā vā kaṣāyeṇa paced ghṛtam prasthaṃ gokṣurakalkena siddhamadyātsaśarkaram aśmarīmūtrakṛcchaghnaṃ retomārgarujā'paham"},{"type":"verse","number":"82","sanskrit":"वरुणस्य तुलां क्षुण्णां जलद्रो णे विपाचयेत् पादशेषं परिस्राव्य घृतप्रस्थं विपाचयेत्","text":"varuṇasya tulāṃ kṣuṇṇāṃ jaladro ṇe vipācayet pādaśeṣaṃ parisrāvya ghṛtaprasthaṃ vipācayet"},{"type":"verse","number":"83","sanskrit":"वरुणं कदलद्यं बिल्वं तृणजं पञ्चमूलकम् अमृतां चाश्मभेदञ्च बीजञ्च त्रपुसस्यच","text":"varuṇaṃ kadaladyaṃ bilvaṃ tṛṇajaṃ pañcamūlakam amṛtāṃ cāśmabhedañca bījañca trapusasyaca"},{"type":"verse","number":"84","sanskrit":"शतपर्वा तिलक्षारं पालाशक्षारमेव च यूथिकायाश्च मूलानि कार्षिकाणि समावपेत्","text":"śataparvā tilakṣāraṃ pālāśakṣārameva ca yūthikāyāśca mūlāni kārṣikāṇi samāvapet"},{"type":"verse","number":"85","sanskrit":"अस्य मात्रां पिबेज्जन्तुर्देशकालाद्यपेक्षया","text":"asya mātrāṃ pibejjanturdeśakālādyapekṣayā"},{"type":"verse","number":"86","sanskrit":"जीर्णे चास्मिन्पिबेत्पूर्वं गुडं जीर्णञ्च मस्तु च अश्मरीं शर्कराञ्चैव मूत्रकृच्छ्रञ्च नाशयेत्","text":"jīrṇe cāsminpibetpūrvaṃ guḍaṃ jīrṇañca mastu ca aśmarīṃ śarkarāñcaiva mūtrakṛcchrañca nāśayet"},{"type":"verse","number":"87","sanskrit":"सैन्धवाद्यन्तु यत्तैलमृषिभिः परिकीर्त्तितम् तत्तैलं द्विगुणं क्षीरं पचेद्वीरतरादिना","text":"saindhavādyantu yattailamṛṣibhiḥ parikīrttitam tattailaṃ dviguṇaṃ kṣīraṃ pacedvīratarādinā"},{"type":"verse","number":"88","sanskrit":"क्वाथेन पूर्वकल्केन साधितन्तु भिषग्वरैः एतत्तैलवरं श्रेष्ठमश्मरीणां निवारणम्","text":"kvāthena pūrvakalkena sādhitantu bhiṣagvaraiḥ etattailavaraṃ śreṣṭhamaśmarīṇāṃ nivāraṇam"},{"type":"verse","number":"89","sanskrit":"मूत्राघाते मूत्रकृच्छ्रे पिच्चिते मथिते तथा भग्ने श्रमाभिपन्ने च सर्वथैव प्रशस्यते","text":"mūtrāghāte mūtrakṛcchre piccite mathite tathā bhagne śramābhipanne ca sarvathaiva praśasyate"},{"type":"verse","number":"90","sanskrit":"वीरावृक्षाश्म भेदाग्निमन्थश्योनाकपाटलाः वृक्षादनीसहैरण्ड भल्लूकोशीरपद्मकम्","text":"vīrāvṛkṣāśma bhedāgnimanthaśyonākapāṭalāḥ vṛkṣādanīsahairaṇḍa bhallūkośīrapadmakam"},{"type":"verse","number":"91","sanskrit":"कुशकाशशरेक्षूणामास्फोताकोकिलाक्षयोः शतावरी श्वदंष्ट्रा च सेत्कटाह्वयवञ्जुलाः","text":"kuśakāśaśarekṣūṇāmāsphotākokilākṣayoḥ śatāvarī śvadaṃṣṭrā ca setkaṭāhvayavañjulāḥ"},{"type":"verse","number":"92","sanskrit":"कपोतवङ्का श्रीपर्णी काश्मरीमूलसंयुता एतैः कषायैः कल्कैश्च तैलं धीरो विपाचयेत्","text":"kapotavaṅkā śrīparṇī kāśmarīmūlasaṃyutā etaiḥ kaṣāyaiḥ kalkaiśca tailaṃ dhīro vipācayet"},{"type":"verse","number":"93","sanskrit":"वातपित्तविकारेषु वस्तिं दद्याद्विचक्षणः शर्कराऽश्मरिशूलघ्नं मृत्रकृच्छ्रविनाशनम्","text":"vātapittavikāreṣu vastiṃ dadyādvicakṣaṇaḥ śarkarā'śmariśūlaghnaṃ mṛtrakṛcchravināśanam"},{"type":"verse","number":"94","sanskrit":"पुनर्नवाऽमृता भीरुसक्षारलवणत्रयैः शटीकुष्ठवचा मुस्तरास्नाकट्फलपौष्करैः","text":"punarnavā'mṛtā bhīrusakṣāralavaṇatrayaiḥ śaṭīkuṣṭhavacā mustarāsnākaṭphalapauṣkaraiḥ"},{"type":"verse","number":"95","sanskrit":"यवानीहपुषाहिङ्गु शताह्वासाजमोदकैः विडङ्गातिविषायष्टी पञ्चकोलकसंयुतैः","text":"yavānīhapuṣāhiṅgu śatāhvāsājamodakaiḥ viḍaṅgātiviṣāyaṣṭī pañcakolakasaṃyutaiḥ"},{"type":"verse","number":"96","sanskrit":"एतैरक्षसमैः कल्कैस्तैलप्रस्थं विपाचयेत् गोमूत्रं द्विगुणं देयं काञ्जिकं तद्वदेव तु","text":"etairakṣasamaiḥ kalkaistailaprasthaṃ vipācayet gomūtraṃ dviguṇaṃ deyaṃ kāñjikaṃ tadvadeva tu"},{"type":"verse","number":"97","sanskrit":"पुनर्नवाऽद्यमित्येतत्तैलं पानेन वस्तिना शर्कराऽश्मरिशूलघ्नं मूत्रकृच्छ्रप्रमोचनम्","text":"punarnavā'dyamityetattailaṃ pānena vastinā śarkarā'śmariśūlaghnaṃ mūtrakṛcchrapramocanam"},{"type":"verse","number":"98","sanskrit":"कठ्यूरुवस्तिमेढ्रस्य कुक्षिवङ्क्षणसंयुतम् कफवातामशूलघ्नमन्त्रवृद्धेश्च नाशनम्","text":"kaṭhyūruvastimeḍhrasya kukṣivaṅkṣaṇasaṃyutam kaphavātāmaśūlaghnamantravṛddheśca nāśanam"},{"type":"verse","number":"99","sanskrit":"ब्रध्नाधिकारनिर्दिष्टं सैन्धवाद्यमिहेष्यते सर्वदैवोपयोज्यस्तु गणो वीरतरादिकः","text":"bradhnādhikāranirdiṣṭaṃ saindhavādyamiheṣyate sarvadaivopayojyastu gaṇo vīratarādikaḥ"},{"type":"verse","number":"100","sanskrit":"घृतैः शीतैः कषायैश्च क्षीरैश्चोत्तरवस्तिभिः बलवत्यो न शाम्यन्ति प्रत्याख्याय समुद्धरेत्","text":"ghṛtaiḥ śītaiḥ kaṣāyaiśca kṣīraiścottaravastibhiḥ balavatyo na śāmyanti pratyākhyāya samuddharet"},{"type":"verse","number":"101","sanskrit":"यदृच्छया मूत्रमार्गमायान्त्यस्त्वन्तराश्रिताः स्रोतसाऽपहरेच्छित्त्वा बडिशेनाथ चोद्धरेत्","text":"yadṛcchayā mūtramārgamāyāntyastvantarāśritāḥ srotasā'paharecchittvā baḍiśenātha coddharet"},{"type":"verse","number":"102","sanskrit":"इति सप्तत्रिंशोऽश्मरीरोगाधिकारः समाप्तः ३७","text":"iti saptatriṃśo'śmarīrogādhikāraḥ samāptaḥ 37"}]},{"sthana":"Уттаракханда","number":38,"lang":"sa","content":[{"type":"heading","heading":"Прамеха-пидака — диабетические нарывы"},{"type":"verse","number":"1","sanskrit":"आस्यासुखं स्वप्नसुखं दधीनि ग्राम्यौदकानूपरसाः पयांसि नवान्नपानं गुडवैकृतं च प्रमेहहेतुः कफकृच्च सर्वम्","text":"āsyāsukhaṃ svapnasukhaṃ dadhīni grāmyaudakānūparasāḥ payāṃsi navānnapānaṃ guḍavaikṛtaṃ ca pramehahetuḥ kaphakṛcca sarvam"},{"type":"verse","number":"2","sanskrit":"मेदश्च मांसञ्च शरीरजञ्च क्लेदं कफो वस्तिगतं प्रदूष्य करोति मेहान्समुदीर्णमुष्णैस्तानेव पित्तं परिदूष्य चापि क्षीणेषु दोषेष्ववकृष्य धातून्सन्दूष्य मेहान्कुरुतेऽनिलश्च","text":"medaśca māṃsañca śarīrajañca kledaṃ kapho vastigataṃ pradūṣya karoti mehānsamudīrṇamuṣṇaistāneva pittaṃ paridūṣya cāpi kṣīṇeṣu doṣeṣvavakṛṣya dhātūnsandūṣya mehānkurute'nilaśca"},{"type":"verse","number":"3","sanskrit":"साध्याः कफोत्था दश पित्तजाः षट् याप्या न साध्याः पवनाच्चतुष्काः समक्रियत्वाद्विषमक्रियत्वान्महात्ययत्वाच्च यथाक्रमं ते","text":"sādhyāḥ kaphotthā daśa pittajāḥ ṣaṭ yāpyā na sādhyāḥ pavanāccatuṣkāḥ samakriyatvādviṣamakriyatvānmahātyayatvācca yathākramaṃ te"},{"type":"verse","number":"4","sanskrit":"कफश्च पित्तं पवनश्च दोषा मेदोऽस्रशुक्राम्बुवसालसीकाः मज्जारसौजः पिशितञ्च दूष्याः प्रमेहिणां विंशतिरेव मेहाः","text":"kaphaśca pittaṃ pavanaśca doṣā medo'sraśukrāmbuvasālasīkāḥ majjārasaujaḥ piśitañca dūṣyāḥ pramehiṇāṃ viṃśatireva mehāḥ"},{"type":"verse","number":"5","sanskrit":"दन्तादीनां मलाढ्यत्वं प्राग्रूपं पाणिपादयोः दाहश्चिक्कणता देहे तृट् स्वाद्वास्यञ्च जायते","text":"dantādīnāṃ malāḍhyatvaṃ prāgrūpaṃ pāṇipādayoḥ dāhaścikkaṇatā dehe tṛṭ svādvāsyañca jāyate"},{"type":"verse","number":"6","sanskrit":"सामान्यं लक्षणं तेषां प्रभूताविलमूत्रता","text":"sāmānyaṃ lakṣaṇaṃ teṣāṃ prabhūtāvilamūtratā"},{"type":"verse","number":"7","sanskrit":"दोषदूष्याविशेषेऽपि तत्संयोगविशेषतः मूत्रवर्णादिभेदेन भेदो मेहेषु कल्प्यते","text":"doṣadūṣyāviśeṣe'pi tatsaṃyogaviśeṣataḥ mūtravarṇādibhedena bhedo meheṣu kalpyate"},{"type":"verse","number":"8","sanskrit":"अच्छं बहु सितं शीतं निर्गन्धमुदकोपमम् मेहत्युदकमेहेन किञ्चिच्चाविलपिच्छलम्","text":"acchaṃ bahu sitaṃ śītaṃ nirgandhamudakopamam mehatyudakamehena kiñciccāvilapicchalam"},{"type":"verse","number":"9","sanskrit":"इक्षो रसमिवात्यर्थं मधुरं चेक्षुमेहतः सान्द्री भवेत्पर्युषितं सान्द्र मेहेन मेहति","text":"ikṣo rasamivātyarthaṃ madhuraṃ cekṣumehataḥ sāndrī bhavetparyuṣitaṃ sāndra mehena mehati"},{"type":"verse","number":"10","sanskrit":"सुरामेही सुरातुल्यमुपर्यच्छमधोघनम् संहृष्टरोमा पिष्टेन पिष्टवद् बहुलं सितम्","text":"surāmehī surātulyamuparyacchamadhoghanam saṃhṛṣṭaromā piṣṭena piṣṭavad bahulaṃ sitam"},{"type":"verse","number":"11","sanskrit":"शुक्राभं शुक्रमिश्रं वा शुक्रमेही प्रमेहति मूर्ताणून्सिकता मेही सिकतारूपिणो मलान्","text":"śukrābhaṃ śukramiśraṃ vā śukramehī pramehati mūrtāṇūnsikatā mehī sikatārūpiṇo malān"},{"type":"verse","number":"12","sanskrit":"शीतमेही सुबहुशो मधुरं भृशशीतलम् शनैः शनैः शनैर्मेही मन्दं मन्दं प्रमेहति लालातन्तुयुतं मूत्रं लालामेहेन पिच्छलम्","text":"śītamehī subahuśo madhuraṃ bhṛśaśītalam śanaiḥ śanaiḥ śanairmehī mandaṃ mandaṃ pramehati lālātantuyutaṃ mūtraṃ lālāmehena picchalam"},{"type":"verse","number":"13","sanskrit":"गन्धवर्णरसस्पर्शैः क्षारेण क्षारतोयवत्","text":"gandhavarṇarasasparśaiḥ kṣāreṇa kṣāratoyavat"},{"type":"verse","number":"14","sanskrit":"नीलमेहेन नीलाभं कालमेही मसीनिभम् हारिद्र मेही कटुकंहरिद्रा सन्निभं दहत्","text":"nīlamehena nīlābhaṃ kālamehī masīnibham hāridra mehī kaṭukaṃharidrā sannibhaṃ dahat"},{"type":"verse","number":"15","sanskrit":"विस्रं माञ्जिष्ठमेहेन मञ्जिष्ठासलिलोपमम् विस्रमुष्णं सलवणं रक्ताभं रक्तमेहिनः","text":"visraṃ māñjiṣṭhamehena mañjiṣṭhāsalilopamam visramuṣṇaṃ salavaṇaṃ raktābhaṃ raktamehinaḥ"},{"type":"verse","number":"16","sanskrit":"वसामेही वसामिश्रं वसाऽभ मूत्रयेन्मुहुः मज्जाभं मज्जमिश्रं वा मज्जमेही मुहुर्मुहः","text":"vasāmehī vasāmiśraṃ vasā'bha mūtrayenmuhuḥ majjābhaṃ majjamiśraṃ vā majjamehī muhurmuhaḥ"},{"type":"verse","number":"17","sanskrit":"कषायं मधुरं रूक्षं क्षौद्र मेहं वदेद् बुधः हस्ती मत्त इवाजस्रं मूत्रवेगविवर्जितम् सलसीकं विबद्धञ्च हस्तिमेही प्रमेहति","text":"kaṣāyaṃ madhuraṃ rūkṣaṃ kṣaudra mehaṃ vaded budhaḥ hastī matta ivājasraṃ mūtravegavivarjitam salasīkaṃ vibaddhañca hastimehī pramehati"},{"type":"verse","number":"18","sanskrit":"अविपाकोऽरुचिश्छर्दिर्निद्रा कासः सपीनसः उपद्र वाः प्रजायन्ते मेहानां कफजन्मनाम्","text":"avipāko'ruciśchardirnidrā kāsaḥ sapīnasaḥ upadra vāḥ prajāyante mehānāṃ kaphajanmanām"},{"type":"verse","number":"19","sanskrit":"वस्तिमेहनयोस्तोदो मुष्कावदरणं ज्वरः दाहस्तृष्णाऽम्लको मूर्च्छा विड्भेदः पित्तजन्मनाम्","text":"vastimehanayostodo muṣkāvadaraṇaṃ jvaraḥ dāhastṛṣṇā'mlako mūrcchā viḍbhedaḥ pittajanmanām"},{"type":"verse","number":"20","sanskrit":"वातजानामुदावर्त्तकम्पहृद्ग्रहलोलताः शूलमुन्निद्र ता शोषःश्वासः कासश्चजायते","text":"vātajānāmudāvarttakampahṛdgrahalolatāḥ śūlamunnidra tā śoṣaḥśvāsaḥ kāsaścajāyate"},{"type":"verse","number":"21","sanskrit":"यथोक्तोपद्र वाविष्टमतिप्रस्रुतमेव च पिडिकापीडितं गाढं प्रमेहो हन्ति मानवम्","text":"yathoktopadra vāviṣṭamatiprasrutameva ca piḍikāpīḍitaṃ gāḍhaṃ prameho hanti mānavam"},{"type":"verse","number":"22","sanskrit":"मूर्च्छाच्छर्दि ज्वरश्वासकासवीसर्पगौरवैः उपद्र वैरुपेतो यः प्रमेही दुष्प्रतिक्रियः","text":"mūrcchācchardi jvaraśvāsakāsavīsarpagauravaiḥ upadra vairupeto yaḥ pramehī duṣpratikriyaḥ"},{"type":"verse","number":"23","sanskrit":"रजः प्रवर्त्ततेयस्मान्मासि मासि विशोधयेत् सर्वाञ्छरीरदोषांश्च न प्रमेहन्त्यतः स्त्रियः","text":"rajaḥ pravarttateyasmānmāsi māsi viśodhayet sarvāñcharīradoṣāṃśca na pramehantyataḥ striyaḥ"},{"type":"verse","number":"24","sanskrit":"जातः प्रमेहीमधुमेहिनो वा न साध्यरोगः स हि बीजदोषात् ये चापि केचित्कुलजा विकारा भवन्ति तांश्चापि वदन्त्यसाध्यान्","text":"jātaḥ pramehīmadhumehino vā na sādhyarogaḥ sa hi bījadoṣāt ye cāpi kecitkulajā vikārā bhavanti tāṃścāpi vadantyasādhyān"},{"type":"verse","number":"25","sanskrit":"सर्व एव प्रमेहास्तु कालेनाप्रतिकारिणः मधुमेहत्वमायान्ति तदाऽसाध्या भवन्ति च","text":"sarva eva pramehāstu kālenāpratikāriṇaḥ madhumehatvamāyānti tadā'sādhyā bhavanti ca"},{"type":"verse","number":"26","sanskrit":"मधुमेहोमधुनिभो जायते स किल द्विधा क्रुद्धे धातुक्षयाद्वायौ दोषावृतपथेऽथवा","text":"madhumehomadhunibho jāyate sa kila dvidhā kruddhe dhātukṣayādvāyau doṣāvṛtapathe'thavā"},{"type":"verse","number":"27","sanskrit":"आवृतो दोषलिङ्गानि सोऽनिमित्तं प्रदर्शयन् क्षणात्क्षीणःक्षणात्पूर्णो भजते कृच्छ्रसाध्यताम्","text":"āvṛto doṣaliṅgāni so'nimittaṃ pradarśayan kṣaṇātkṣīṇaḥkṣaṇātpūrṇo bhajate kṛcchrasādhyatām"},{"type":"verse","number":"28","sanskrit":"मधुरं यच्च सर्वेषु प्रायो मध्विव मेहति सर्वेऽपि मधुमेहाख्या माधुर्य्याच्च तनोरतः","text":"madhuraṃ yacca sarveṣu prāyo madhviva mehati sarve'pi madhumehākhyā mādhuryyācca tanorataḥ"},{"type":"verse","number":"29","sanskrit":"शराविका कच्छपिका जालिनी विनताऽलजी मसूरिका सर्षपिका पुत्रिणी सविदारिका","text":"śarāvikā kacchapikā jālinī vinatā'lajī masūrikā sarṣapikā putriṇī savidārikā"},{"type":"verse","number":"30","sanskrit":"विद्र धिश्चेति पिडिकाः प्रमेहोपेक्षया दश सन्धिमर्मसु जायन्ते मांसलेषु च धामसु","text":"vidra dhiśceti piḍikāḥ pramehopekṣayā daśa sandhimarmasu jāyante māṃsaleṣu ca dhāmasu"},{"type":"verse","number":"31","sanskrit":"अन्तोन्नता च तद्रू पा निम्नमध्या शराविका गौरसर्षपसंस्थाना तत्प्रमाणा तु सर्षपी","text":"antonnatā ca tadrū pā nimnamadhyā śarāvikā gaurasarṣapasaṃsthānā tatpramāṇā tu sarṣapī"},{"type":"verse","number":"32","sanskrit":"सदाहा कूर्मसंस्थाना ज्ञेया कच्छपिका बुधैः जालिनी तीव्रदाहा तु मांसजालसमावृता","text":"sadāhā kūrmasaṃsthānā jñeyā kacchapikā budhaiḥ jālinī tīvradāhā tu māṃsajālasamāvṛtā"},{"type":"verse","number":"33","sanskrit":"अवगाढरुजाक्लेदा पृष्ठे वाऽप्युदरेऽपि वा महती पिडिका नीला सा बुधैर्विनता स्मृता","text":"avagāḍharujākledā pṛṣṭhe vā'pyudare'pi vā mahatī piḍikā nīlā sā budhairvinatā smṛtā"},{"type":"verse","number":"34","sanskrit":"महत्यल्पचिता ज्ञेया पिडिकाऽपि च पुत्रिणी मसूरदलसंस्थाना विज्ञेया तु मसूरिका","text":"mahatyalpacitā jñeyā piḍikā'pi ca putriṇī masūradalasaṃsthānā vijñeyā tu masūrikā"},{"type":"verse","number":"35","sanskrit":"रक्ताऽसिता स्फोटचिता विज्ञेया त्वलजी बुधैः विदारीकन्दवद् वृत्ता कठिना च विदारिका","text":"raktā'sitā sphoṭacitā vijñeyā tvalajī budhaiḥ vidārīkandavad vṛttā kaṭhinā ca vidārikā"},{"type":"verse","number":"36","sanskrit":"विद्र धेर्लक्षणैर्युक्ता ज्ञेया विद्र धिका तु सा","text":"vidra dherlakṣaṇairyuktā jñeyā vidra dhikā tu sā"},{"type":"verse","number":"37","sanskrit":"ये यन्मयाः स्मृता मेहास्तेषामेतास्तु तन्मयाः","text":"ye yanmayāḥ smṛtā mehāsteṣāmetāstu tanmayāḥ"},{"type":"verse","number":"38","sanskrit":"विना प्रमेहमप्येता जायन्ते दुष्टमेदसः तावच्चैता न लक्ष्यन्ते यावद्वास्तुपरिग्रहाः","text":"vinā pramehamapyetā jāyante duṣṭamedasaḥ tāvaccaitā na lakṣyante yāvadvāstuparigrahāḥ"},{"type":"verse","number":"39","sanskrit":"गुदे हृदि शिरस्यंसे पृष्ठे मर्मसु चोत्थिताः सोपद्र वादुर्बलाग्नेः पिडिकाः परिवर्जयेत्","text":"gude hṛdi śirasyaṃse pṛṣṭhe marmasu cotthitāḥ sopadra vādurbalāgneḥ piḍikāḥ parivarjayet"},{"type":"verse","number":"40","sanskrit":"तृट्शोषमांससंकोचमोहहिक्कामदज्वराः विसर्पमर्मसंरोधाः पिडिकानामुपद्र वाः","text":"tṛṭśoṣamāṃsasaṃkocamohahikkāmadajvarāḥ visarpamarmasaṃrodhāḥ piḍikānāmupadra vāḥ"},{"type":"verse","number":"41","sanskrit":"श्यामाककोद्र वोद्दाल गोधूमाश्चणकास्तथा आढक्यश्च कुलत्थाश्चपुराणा मेहिनां हिताः","text":"śyāmākakodra voddāla godhūmāścaṇakāstathā āḍhakyaśca kulatthāścapurāṇā mehināṃ hitāḥ"},{"type":"verse","number":"42","sanskrit":"मेहिनां तिक्तशाकानिजाङ्गला हरिणाण्डजाः यवान्नविकृतिर्मुद्गाः शस्यन्ते शालिषष्टिकाः","text":"mehināṃ tiktaśākānijāṅgalā hariṇāṇḍajāḥ yavānnavikṛtirmudgāḥ śasyante śāliṣaṣṭikāḥ"},{"type":"verse","number":"43","sanskrit":"सौवीरकं सुरा तक्रं तैलं क्षीरं घृतं गुडम् अम्लेक्षुरसपिष्टान्नानूपमांसानि वर्जयेत्","text":"sauvīrakaṃ surā takraṃ tailaṃ kṣīraṃ ghṛtaṃ guḍam amlekṣurasapiṣṭānnānūpamāṃsāni varjayet"},{"type":"verse","number":"44","sanskrit":"तत्रादित एव प्रमेहिणमुपस्निग्धमन्यतमेन प्रियङ्ग्वादिसिद्धेन तैलेन वामयेत् प्रगाढं विरेचयेच्च विरेचनादनन्तरं सुरसाऽदिक कषायेणास्थापयेतै महौषधभद्र दारुमुस्तावापेन मधुसैन्धवयुक्तेनै दह्यमानं वा न्यग्रोधादिकषायेण निस्तैलेन वातोत्कटेषु मेहेषु स्नेहपानं विशेषतः पारिजातजयानिम्बवह्निगायत्रीणां पृथक्","text":"tatrādita eva pramehiṇamupasnigdhamanyatamena priyaṅgvādisiddhena tailena vāmayet pragāḍhaṃ virecayecca virecanādanantaraṃ surasā'dika kaṣāyeṇāsthāpayetai mahauṣadhabhadra dārumustāvāpena madhusaindhavayuktenai dahyamānaṃ vā nyagrodhādikaṣāyeṇa nistailena vātotkaṭeṣu meheṣu snehapānaṃ viśeṣataḥ pārijātajayānimbavahnigāyatrīṇāṃ pṛthak"},{"type":"verse","number":"45","sanskrit":"पाठायाः सागुरोः पीताद्बयस्य शारदस्य च जलेक्षुमद्यसिकताशनैर्ल वणपिष्टकान् सान्द्र मेहान्क्रमाद् घ्नन्ति क्वाथाश्चाष्टौ समाक्षिकाः","text":"pāṭhāyāḥ sāguroḥ pītādbayasya śāradasya ca jalekṣumadyasikatāśanairla vaṇapiṣṭakān sāndra mehānkramād ghnanti kvāthāścāṣṭau samākṣikāḥ"},{"type":"verse","number":"46","sanskrit":"हरीतकीकट्फलमुस्तलोध्राः पाठाविडङ्गार्जुनधन्वनाश्च उभे हरिद्रे तगरं विडङ्गं कन्दं विशालाऽजुनदीप्यकाश्च","text":"harītakīkaṭphalamustalodhrāḥ pāṭhāviḍaṅgārjunadhanvanāśca ubhe haridre tagaraṃ viḍaṅgaṃ kandaṃ viśālā'junadīpyakāśca"},{"type":"verse","number":"47","sanskrit":"दार्वी विडङ्गः खदिरो धवश्च सुराह्वकुष्ठागुरुचन्दनानि दार्व्यग्निमन्थो त्रिफलावचा च पाठा च मूर्वा च तथा श्वदंष्ट्रा","text":"dārvī viḍaṅgaḥ khadiro dhavaśca surāhvakuṣṭhāgurucandanāni dārvyagnimantho triphalāvacā ca pāṭhā ca mūrvā ca tathā śvadaṃṣṭrā"},{"type":"verse","number":"48","sanskrit":"वचा ह्युशीराण्यभया गुडूची वृषं शिवाचित्रकसप्तपर्णाः पादैः कषायाः कफमेहविज्ञैर्दशोपदिष्टा मधुसम्प्रयुक्ताः","text":"vacā hyuśīrāṇyabhayā guḍūcī vṛṣaṃ śivācitrakasaptaparṇāḥ pādaiḥ kaṣāyāḥ kaphamehavijñairdaśopadiṣṭā madhusamprayuktāḥ"},{"type":"verse","number":"49","sanskrit":"उशीरलोध्रार्जुन चन्दनानामुशीरमुस्तामलकाभयानाम् पटोलनिम्बामलकामृतानां मुस्ताभयामुष्ककवृक्षकाणाम्","text":"uśīralodhrārjuna candanānāmuśīramustāmalakābhayānām paṭolanimbāmalakāmṛtānāṃ mustābhayāmuṣkakavṛkṣakāṇām"},{"type":"verse","number":"50","sanskrit":"लोध्राम्रकासीसकधातकीनां विश्वार्जुनैलाशिरिषोत्पलानाम् शिरीषधान्यार्जुनकेशराणां प्रियङ्गुपद्मोत्पलकिंशुकानाम्","text":"lodhrāmrakāsīsakadhātakīnāṃ viśvārjunailāśiriṣotpalānām śirīṣadhānyārjunakeśarāṇāṃ priyaṅgupadmotpalakiṃśukānām"},{"type":"verse","number":"51","sanskrit":"अश्वत्थपाठाऽसनवेतसानां कटङ्कटेर्युत्पलमुस्तकानाम् पैत्तेषु मेहेषु दशोपदिष्टाः कषाययोगा मधुसम्प्रयुक्ताः","text":"aśvatthapāṭhā'sanavetasānāṃ kaṭaṅkaṭeryutpalamustakānām paitteṣu meheṣu daśopadiṣṭāḥ kaṣāyayogā madhusamprayuktāḥ"},{"type":"verse","number":"52","sanskrit":"कफमेहहरक्वाथसिद्धं सर्पिः कफे हितम् पित्तमेहघ्ननिर्यूहसिद्धं पित्तहरं घृतम्","text":"kaphamehaharakvāthasiddhaṃ sarpiḥ kaphe hitam pittamehaghnaniryūhasiddhaṃ pittaharaṃ ghṛtam"},{"type":"verse","number":"53","sanskrit":"कम्पिल्लसप्तच्छदशालजानि बैभीतरोहीतककौटजानि पटोलकालीयगदागुरूणि क्षौद्रे ण लिह्यात्कफपित्तमेही","text":"kampillasaptacchadaśālajāni baibhītarohītakakauṭajāni paṭolakālīyagadāgurūṇi kṣaudre ṇa lihyātkaphapittamehī"},{"type":"verse","number":"54","sanskrit":"दूर्वाकसेरुपूतीक कुम्भीकप्लवशैवलम् जलेन क्वथितं पीतं शुक्रमेहहरं परम्","text":"dūrvākaserupūtīka kumbhīkaplavaśaivalam jalena kvathitaṃ pītaṃ śukramehaharaṃ param"},{"type":"verse","number":"55","sanskrit":"त्रिफलाऽरग्वधद्रा क्षाकषायो मधुसंयुतः पीतो निहन्ति फेनाभं प्रमेहं नियतं नृणाम्","text":"triphalā'ragvadhadrā kṣākaṣāyo madhusaṃyutaḥ pīto nihanti phenābhaṃ pramehaṃ niyataṃ nṛṇām"},{"type":"verse","number":"56","sanskrit":"अश्वत्थाच्चतुरङ्गुल्यान्न्यग्रोधादेः फलत्रयात् सरक्तसारमञ्जिष्ठाः क्वाथाः पञ्च समाक्षिकाः नीलहारिद्र फेनाख्यक्षारमाञ्जिष्ठकाह्वयान्","text":"aśvatthāccaturaṅgulyānnyagrodhādeḥ phalatrayāt saraktasāramañjiṣṭhāḥ kvāthāḥ pañca samākṣikāḥ nīlahāridra phenākhyakṣāramāñjiṣṭhakāhvayān"},{"type":"verse","number":"57","sanskrit":"मधुना त्रिफलाचूर्णमथवाश्मजतूद्भवम् लौहजं वाभयोत्थं वा लिहेन्मेहनिवृत्तये","text":"madhunā triphalācūrṇamathavāśmajatūdbhavam lauhajaṃ vābhayotthaṃ vā lihenmehanivṛttaye"},{"type":"verse","number":"58","sanskrit":"कटङ्कटेरीमधुकत्रिफलाचित्रकैः समैः सिद्धः कषायः पातव्यः प्रमेहाणां विनाशनः","text":"kaṭaṅkaṭerīmadhukatriphalācitrakaiḥ samaiḥ siddhaḥ kaṣāyaḥ pātavyaḥ pramehāṇāṃ vināśanaḥ"},{"type":"verse","number":"59","sanskrit":"फलत्रिकंदारुनिशां विशालां मुस्तां च निष्क्वाथ्य निशांश कल्कम् पिबेत्कषायं मधुसम्प्रयुक्तं सर्वप्रमेहेषु समुच्छ्रितेषु","text":"phalatrikaṃdāruniśāṃ viśālāṃ mustāṃ ca niṣkvāthya niśāṃśa kalkam pibetkaṣāyaṃ madhusamprayuktaṃ sarvaprameheṣu samucchriteṣu"},{"type":"verse","number":"60","sanskrit":"गोभक्षितान्यवान्मूत्रभावितान्केवलानपि चित्रकोदश्विता खादेन्निम्बमुद्गरसेन वा","text":"gobhakṣitānyavānmūtrabhāvitānkevalānapi citrakodaśvitā khādennimbamudgarasena vā"},{"type":"verse","number":"61","sanskrit":"भक्षयीताम्बुना मासं प्रमेही यवपिष्टकम् मेदोघ्ना बद्धमूत्राश्च समाः सर्वेषु धातुषु यवास्तस्माद्विशिष्यन्ते प्रमेहेषु विशेषतः","text":"bhakṣayītāmbunā māsaṃ pramehī yavapiṣṭakam medoghnā baddhamūtrāśca samāḥ sarveṣu dhātuṣu yavāstasmādviśiṣyante prameheṣu viśeṣataḥ"},{"type":"verse","number":"62","sanskrit":"त्रिकटु त्रिफला पाठा मूलं शोभाञ्जनस्य च विडङ्गतण्डुला हिङ्गु तथा कटुकरोहिणी","text":"trikaṭu triphalā pāṭhā mūlaṃ śobhāñjanasya ca viḍaṅgataṇḍulā hiṅgu tathā kaṭukarohiṇī"},{"type":"verse","number":"63","sanskrit":"बृहती कण्टकारी च हरिद्रे द्वे यवानिका केबुकं शालपर्णी च तथाऽतिविषचित्रकौ","text":"bṛhatī kaṇṭakārī ca haridre dve yavānikā kebukaṃ śālaparṇī ca tathā'tiviṣacitrakau"},{"type":"verse","number":"64","sanskrit":"सौवर्चलं जीरकञ्च हपुषा धान्यमेव च एषां कर्षप्रमाणञ्च श्लक्ष्णचूर्णञ्च कारयेत्","text":"sauvarcalaṃ jīrakañca hapuṣā dhānyameva ca eṣāṃ karṣapramāṇañca ślakṣṇacūrṇañca kārayet"},{"type":"verse","number":"65","sanskrit":"यवशक्तु पलानाञ्च नवतिं द्वितयाधिकाम् घृततैलमधूनाञ्च प्रत्येकञ्च पलानि षट्","text":"yavaśaktu palānāñca navatiṃ dvitayādhikām ghṛtatailamadhūnāñca pratyekañca palāni ṣaṭ"},{"type":"verse","number":"66","sanskrit":"एभिः कर्षप्रमाणञ्च प्रत्यहं मोदकं सुधीः भक्षयेन्नाशयेदुग्रान्प्रमेहानतिदारुणान्","text":"ebhiḥ karṣapramāṇañca pratyahaṃ modakaṃ sudhīḥ bhakṣayennāśayedugrānpramehānatidāruṇān"},{"type":"verse","number":"67","sanskrit":"न्यग्रोधोदुम्बराश्वत्थश्योनाकारग्वधासनम् आम्रं कपित्थं जम्बूञ्च प्रियालं ककुभं धवम्","text":"nyagrodhodumbarāśvatthaśyonākāragvadhāsanam āmraṃ kapitthaṃ jambūñca priyālaṃ kakubhaṃ dhavam"},{"type":"verse","number":"68","sanskrit":"मधूकं मधुकं लोध्रं वरुणं पारिभद्र कम् पटोलं मेषशृङ्गी च दन्ती चित्रकमाढकी","text":"madhūkaṃ madhukaṃ lodhraṃ varuṇaṃ pāribhadra kam paṭolaṃ meṣaśṛṅgī ca dantī citrakamāḍhakī"},{"type":"verse","number":"69","sanskrit":"करञ्जत्रिफलाशक्रभल्लातकफलानि च एतानि समभागानि सूक्ष्मचूर्णानि कारयेत्","text":"karañjatriphalāśakrabhallātakaphalāni ca etāni samabhāgāni sūkṣmacūrṇāni kārayet"},{"type":"verse","number":"70","sanskrit":"न्यग्रोधाद्यमिदं चूर्णं मधुना सह योजयेत् फलत्रयरसं चानु पिबेन्मूत्रं विशुद्ध्य्ति","text":"nyagrodhādyamidaṃ cūrṇaṃ madhunā saha yojayet phalatrayarasaṃ cānu pibenmūtraṃ viśuddhyti"},{"type":"verse","number":"71","sanskrit":"एतेन विंशतिर्मेहा मूत्रकृच्छ्राणि यानि च प्रशमं यान्ति योगेन पिडिका न च जायते","text":"etena viṃśatirmehā mūtrakṛcchrāṇi yāni ca praśamaṃ yānti yogena piḍikā na ca jāyate"},{"type":"verse","number":"72","sanskrit":"चूर्णानिलोहत्रिफलासितानां क्षौद्रे ण लिह्याच्च पृथक् समं वा मेहान्समस्तानपि नाशयन्ति पीतः कदाचित्स्वरसो गुडूच्याः","text":"cūrṇānilohatriphalāsitānāṃ kṣaudre ṇa lihyācca pṛthak samaṃ vā mehānsamastānapi nāśayanti pītaḥ kadācitsvaraso guḍūcyāḥ"},{"type":"verse","number":"73","sanskrit":"त्रिकटु त्रिफलातुल्यं गुग्गुलुञ्च समांशिकम् गोक्षुरक्वाथसंयुक्तं गुटिकां कारयेद् बुधः","text":"trikaṭu triphalātulyaṃ gugguluñca samāṃśikam gokṣurakvāthasaṃyuktaṃ guṭikāṃ kārayed budhaḥ"},{"type":"verse","number":"74","sanskrit":"दोषकालबलापेक्षी भक्षयेच्चानुलोमिकीम् न चात्र परिहारोऽस्ति कर्म कुर्याद्यथेप्सितम्","text":"doṣakālabalāpekṣī bhakṣayeccānulomikīm na cātra parihāro'sti karma kuryādyathepsitam"},{"type":"verse","number":"75","sanskrit":"प्रमेहान्वातरोगांश्च वातशोणितमेव च मूत्राघातं मूत्रदोषं प्रदरं चाशु नाशयेत्","text":"pramehānvātarogāṃśca vātaśoṇitameva ca mūtrāghātaṃ mūtradoṣaṃ pradaraṃ cāśu nāśayet"},{"type":"verse","number":"76","sanskrit":"दाडिमस्य च बीजानि कृमिघ्नस्य च तण्डुलाः रजनी चविकाऽजाजी नागरं त्रिफला कणा","text":"dāḍimasya ca bījāni kṛmighnasya ca taṇḍulāḥ rajanī cavikā'jājī nāgaraṃ triphalā kaṇā"},{"type":"verse","number":"77","sanskrit":"त्रिकण्टकस्य च फलं यवानी धान्यकं तथा वृक्षाम्लचविकालोध्रसिन्धूद्भवसमाहितैः","text":"trikaṇṭakasya ca phalaṃ yavānī dhānyakaṃ tathā vṛkṣāmlacavikālodhrasindhūdbhavasamāhitaiḥ"},{"type":"verse","number":"78","sanskrit":"कल्कैरक्षसमैरेभिर्घृतप्रस्थं विपाचयेत् भोज्ये पाने प्रदातव्यं सर्वर्त्तुषु च मात्रया","text":"kalkairakṣasamairebhirghṛtaprasthaṃ vipācayet bhojye pāne pradātavyaṃ sarvarttuṣu ca mātrayā"},{"type":"verse","number":"79","sanskrit":"प्रमेहान्विंशतिं चैव मूत्राघातं तथाऽश्मरीम् कृच्छ्रं सुदारुणञ्चैव हन्यादेव न संशयः","text":"pramehānviṃśatiṃ caiva mūtrāghātaṃ tathā'śmarīm kṛcchraṃ sudāruṇañcaiva hanyādeva na saṃśayaḥ"},{"type":"verse","number":"80","sanskrit":"विबन्धानाहशूलघ्नं कामलाज्वरनाशनम् दाडिमाद्यं घृतं चैतदश्विभ्यां परकीर्त्तितम्","text":"vibandhānāhaśūlaghnaṃ kāmalājvaranāśanam dāḍimādyaṃ ghṛtaṃ caitadaśvibhyāṃ parakīrttitam"},{"type":"verse","number":"81","sanskrit":"श्वदंष्ट्रा सकणा मुस्ता गुडूची फल्गुपल्लवाः दर्भाङ्कुरास्तु गण्डीरो रोहिषस्य च पल्लवाः","text":"śvadaṃṣṭrā sakaṇā mustā guḍūcī phalgupallavāḥ darbhāṅkurāstu gaṇḍīro rohiṣasya ca pallavāḥ"},{"type":"verse","number":"82","sanskrit":"काला पुनर्नवा श्यामा शारिवा देवदारु च पिप्पली शृङ्गवेरञ्च विडङ्गं मरिचानि च पाठा कम्पिल्लकं भार्गी द्वे हरिद्रे निदिग्धिका एरण्डमूलं दन्ती च चित्रकं कटुरोहिणी","text":"kālā punarnavā śyāmā śārivā devadāru ca pippalī śṛṅgaverañca viḍaṅgaṃ maricāni ca pāṭhā kampillakaṃ bhārgī dve haridre nidigdhikā eraṇḍamūlaṃ dantī ca citrakaṃ kaṭurohiṇī"},{"type":"verse","number":"83","sanskrit":"एतानि समभागानि सूक्ष्मचूर्णानि कारयेत् यावन्त्येतानि चूर्णानि तावत्स्याच्चाप्ययोरजः","text":"etāni samabhāgāni sūkṣmacūrṇāni kārayet yāvantyetāni cūrṇāni tāvatsyāccāpyayorajaḥ"},{"type":"verse","number":"84","sanskrit":"ततो विडालपदकं पिबेदुष्णेन वारिणा अलाभे चापि मद्यानां प्रमेहान्हन्तिविंशतिम्","text":"tato viḍālapadakaṃ pibeduṣṇena vāriṇā alābhe cāpi madyānāṃ pramehānhantiviṃśatim"},{"type":"verse","number":"85","sanskrit":"श्वयथुञ्च तथाऽशासि पाण्डुरोगं हलीमकम् उदाराण्यथ शूलानि प्लीहानं चापकर्षति","text":"śvayathuñca tathā'śāsi pāṇḍurogaṃ halīmakam udārāṇyatha śūlāni plīhānaṃ cāpakarṣati"},{"type":"verse","number":"86","sanskrit":"एभिर्गोमूत्रपिष्टैस्तु गुटिकाः कारयेद्भिषक् रोगेष्वेतेषु मुख्याः स्युर्बलमांसविवर्द्धनाः","text":"ebhirgomūtrapiṣṭaistu guṭikāḥ kārayedbhiṣak rogeṣveteṣu mukhyāḥ syurbalamāṃsavivarddhanāḥ"},{"type":"verse","number":"87","sanskrit":"कण्टकार्या गुडूच्याश्च संहरेच्च शतं शतम् संकुट्योदूखले विद्वांश्चतुर्द्रोणेऽम्भसः पचेत्","text":"kaṇṭakāryā guḍūcyāśca saṃharecca śataṃ śatam saṃkuṭyodūkhale vidvāṃścaturdroṇe'mbhasaḥ pacet"},{"type":"verse","number":"88","sanskrit":"तेन पादावशेषेण घृतप्रस्थं विपाचयेत् त्रिकटुत्रिफलारास्नाविडङ्गान्यथ चित्रकम्","text":"tena pādāvaśeṣeṇa ghṛtaprasthaṃ vipācayet trikaṭutriphalārāsnāviḍaṅgānyatha citrakam"},{"type":"verse","number":"89","sanskrit":"काश्मर्याणाञ्च मूलानि पूतीकस्य त्वगेव च कलिङ्ग इति सर्वाणि सूक्ष्मपिष्टानि कारयेत्","text":"kāśmaryāṇāñca mūlāni pūtīkasya tvageva ca kaliṅga iti sarvāṇi sūkṣmapiṣṭāni kārayet"},{"type":"verse","number":"90","sanskrit":"अक्षमात्रां पिबेत्प्राज्ञः शालिभिः पयसा हि तैः प्रमेहं मधुमेहञ्च मूत्रकृच्छ्रं भगन्दरम्","text":"akṣamātrāṃ pibetprājñaḥ śālibhiḥ payasā hi taiḥ pramehaṃ madhumehañca mūtrakṛcchraṃ bhagandaram"},{"type":"verse","number":"91","sanskrit":"आलस्यं चान्त्रवृद्धिञ्च कुष्ठरोगं विशेषतः क्षयञ्चैव निहन्त्येतन्नाम्ना सिंहामृतं घृतम्","text":"ālasyaṃ cāntravṛddhiñca kuṣṭharogaṃ viśeṣataḥ kṣayañcaiva nihantyetannāmnā siṃhāmṛtaṃ ghṛtam"},{"type":"verse","number":"92","sanskrit":"दशमूलं करञ्जौ द्वौ देवदारु हरीतकी वर्षाभूर्वरुणो दन्ती चित्रकं सपुनर्नवम्","text":"daśamūlaṃ karañjau dvau devadāru harītakī varṣābhūrvaruṇo dantī citrakaṃ sapunarnavam"},{"type":"verse","number":"93","sanskrit":"सुधानीपकदम्बाश्च बिल्वं भल्लातकानिच शटी पुष्करमूलं च पिप्पलीमूलमेव च","text":"sudhānīpakadambāśca bilvaṃ bhallātakānica śaṭī puṣkaramūlaṃ ca pippalīmūlameva ca"},{"type":"verse","number":"94","sanskrit":"पृथग्दशपलान्भागानेतास्तोयेऽमणे पचेत् यवकोलकुलत्थानां प्रस्थं प्रस्थं विपाचयेत्","text":"pṛthagdaśapalānbhāgānetāstoye'maṇe pacet yavakolakulatthānāṃ prasthaṃ prasthaṃ vipācayet"},{"type":"verse","number":"95","sanskrit":"तेन पादावशेषेण घृतप्रस्थं पचेद्भिषक् निचुलं त्रिफला भार्गी रोहिषं गजपिप्पली","text":"tena pādāvaśeṣeṇa ghṛtaprasthaṃ pacedbhiṣak niculaṃ triphalā bhārgī rohiṣaṃ gajapippalī"},{"type":"verse","number":"96","sanskrit":"शृङ्गबेरविडङ्गानि चव्यं कम्पिल्लकं तथा गर्भेणानेन तत्सिद्धं पाययेत्तु यथाबलम्","text":"śṛṅgaberaviḍaṅgāni cavyaṃ kampillakaṃ tathā garbheṇānena tatsiddhaṃ pāyayettu yathābalam"},{"type":"verse","number":"97","sanskrit":"एतद्धान्वन्तरं नाम विख्यातं सर्पिरुत्तमम् कुष्ठप्रमेहगुल्मांश्च श्वयथुं वातशोणितम्","text":"etaddhānvantaraṃ nāma vikhyātaṃ sarpiruttamam kuṣṭhapramehagulmāṃśca śvayathuṃ vātaśoṇitam"},{"type":"verse","number":"98","sanskrit":"प्लीहोदराणि चार्शांसि विद्र धिं पिडिकाश्च याः अपस्मारं तथोन्मादं सर्पिरेतन्नियच्छति","text":"plīhodarāṇi cārśāṃsi vidra dhiṃ piḍikāśca yāḥ apasmāraṃ tathonmādaṃ sarpiretanniyacchati"},{"type":"verse","number":"99","sanskrit":"पृथक्तोयेऽमणे ह्यत्र पचेद् द्र व्याच्छतं शतम् शतत्रयाधिके तोये व्युत्सर्गः क्रमतो भवेत्","text":"pṛthaktoye'maṇe hyatra paced dra vyācchataṃ śatam śatatrayādhike toye vyutsargaḥ kramato bhavet"},{"type":"verse","number":"100","sanskrit":"अर्जुनपटोलनिम्बैः सवचादीप्यकरसासमञ्जिष्ठैः भल्लातकागुरुघनैः सगदानलचन्दनोशीरैः","text":"arjunapaṭolanimbaiḥ savacādīpyakarasāsamañjiṣṭhaiḥ bhallātakāgurughanaiḥ sagadānalacandanośīraiḥ"},{"type":"verse","number":"101","sanskrit":"गोक्षुरकसोमवल्कैर्नवपटोलैर्हरिद्र या त्रिफलया अश्मन्तकार्जुनाभ्यां दीप्यकयुक्तेन चैव लोध्रेण","text":"gokṣurakasomavalkairnavapaṭolairharidra yā triphalayā aśmantakārjunābhyāṃ dīpyakayuktena caiva lodhreṇa"},{"type":"verse","number":"102","sanskrit":"मञ्जिष्ठाऽतिविषाभ्यां कल्ककषायैः पचेत्तैलम् कफवातोत्थे मेहे पित्तकृते साधयेत्सर्पिः","text":"mañjiṣṭhā'tiviṣābhyāṃ kalkakaṣāyaiḥ pacettailam kaphavātotthe mehe pittakṛte sādhayetsarpiḥ"},{"type":"verse","number":"103","sanskrit":"सारवर्गकषायं चतुर्थांशावशिष्टमवतार्य परिस्राव्य पुनरपनीय साधयेत् सिद्ध्य्ति चामलकलोध्रप्रियङ्गुदन्तीकृष्णायसताम्रचूर्णान्यावपेत् तदेतद् दग्धं लेहीभूतमवतार्यानुगुप्तं निदध्यात् ततो यथायोगमुपयञ्जीत एष लेहः सर्वमेहानपहन्ति","text":"sāravargakaṣāyaṃ caturthāṃśāvaśiṣṭamavatārya parisrāvya punarapanīya sādhayet siddhyti cāmalakalodhrapriyaṅgudantīkṛṣṇāyasatāmracūrṇānyāvapet tadetad dagdhaṃ lehībhūtamavatāryānuguptaṃ nidadhyāt tato yathāyogamupayañjīta eṣa lehaḥ sarvamehānapahanti"},{"type":"verse","number":"104","sanskrit":"गोकण्टकं सदलमूलफलं गृहीत्वा सङकुट्टितं पलशतं क्वथितं तु तोये पादस्थितेन सलिलेन पलानि दत्वा पञ्चाशतं तु विपचेदथ शर्करायाः","text":"gokaṇṭakaṃ sadalamūlaphalaṃ gṛhītvā saṅakuṭṭitaṃ palaśataṃ kvathitaṃ tu toye pādasthitena salilena palāni datvā pañcāśataṃ tu vipacedatha śarkarāyāḥ"},{"type":"verse","number":"105","sanskrit":"तस्मिन्घनत्वमुपगच्छति चूर्णितानि दद्यात्पलद्वयमितानि सुभाजनानि शुण्ठीकणामरिचनागदलत्वगेला जातीयकोषककुभत्रपुसीफलानि","text":"tasminghanatvamupagacchati cūrṇitāni dadyātpaladvayamitāni subhājanāni śuṇṭhīkaṇāmaricanāgadalatvagelā jātīyakoṣakakubhatrapusīphalāni"},{"type":"verse","number":"106","sanskrit":"वांशीपलाष्टकमिह प्रणिधाय नित्यं लेह्यं तु शुद्धममृतं पलसम्मितन्तु हन्त्याशु मूत्रपरिदाहविबन्धशुक्रकृच्छ्राश्मरीरुधिरमेहमधुप्रमेहान्","text":"vāṃśīpalāṣṭakamiha praṇidhāya nityaṃ lehyaṃ tu śuddhamamṛtaṃ palasammitantu hantyāśu mūtraparidāhavibandhaśukrakṛcchrāśmarīrudhiramehamadhupramehān"},{"type":"verse","number":"107","sanskrit":"असनश्च प्रियालञ्च शालं खादिरकं तथा शालवर्गं तथा ग्राह्यं भवेच्चैतद्विचक्षणैः","text":"asanaśca priyālañca śālaṃ khādirakaṃ tathā śālavargaṃ tathā grāhyaṃ bhaveccaitadvicakṣaṇaiḥ"},{"type":"verse","number":"108","sanskrit":"मधुमेहत्वमापन्नं भिषग्भिः परिवर्जितम् योगेनानेन मतिमान्प्रमेहिणमुपाचरेत्","text":"madhumehatvamāpannaṃ bhiṣagbhiḥ parivarjitam yogenānena matimānpramehiṇamupācaret"},{"type":"verse","number":"109","sanskrit":"मासि शुक्रे शुचौ वाऽपि शैलाः सूर्यांशुतापिताः जतुप्रकाशं स्वरसं शिलाभ्यः प्रस्रवन्ति हि","text":"māsi śukre śucau vā'pi śailāḥ sūryāṃśutāpitāḥ jatuprakāśaṃ svarasaṃ śilābhyaḥ prasravanti hi"},{"type":"verse","number":"110","sanskrit":"शिलाजत्विति विख्यातं महाव्याधिनिवारणम् त्रप्वादीनां तु लोहानां षण्णामन्यतमञ्च यत्","text":"śilājatviti vikhyātaṃ mahāvyādhinivāraṇam trapvādīnāṃ tu lohānāṃ ṣaṇṇāmanyatamañca yat"},{"type":"verse","number":"111","sanskrit":"ज्ञेयं स्वगन्धतश्चापि षड्योनिप्रथितं क्षितौ लोहाद्भवति तद्यस्माच्छिलाजतु जतुप्रभम्","text":"jñeyaṃ svagandhataścāpi ṣaḍyoniprathitaṃ kṣitau lohādbhavati tadyasmācchilājatu jatuprabham"},{"type":"verse","number":"112","sanskrit":"तस्य लोहस्य तद्वीर्यं रसं वापि बिभर्त्ति तत् त्रपुसीसायसादीनि प्रधानान्युत्तरोत्तरम्","text":"tasya lohasya tadvīryaṃ rasaṃ vāpi bibhartti tat trapusīsāyasādīni pradhānānyuttarottaram"},{"type":"verse","number":"113","sanskrit":"यथा तथा प्रयोगेपि श्रेष्ठे श्रेष्ठगुणाः स्मृताः तत्सर्वं तिक्तकटुकं कषायानुरसं सरम्","text":"yathā tathā prayogepi śreṣṭhe śreṣṭhaguṇāḥ smṛtāḥ tatsarvaṃ tiktakaṭukaṃ kaṣāyānurasaṃ saram"},{"type":"verse","number":"114","sanskrit":"कटुपाक्युष्णवीर्यञ्च शोषणं छेदनं तथा तत्र यल्लघु कृष्णाभं स्निग्धं निःशर्करञ्च यत्","text":"kaṭupākyuṣṇavīryañca śoṣaṇaṃ chedanaṃ tathā tatra yallaghu kṛṣṇābhaṃ snigdhaṃ niḥśarkarañca yat"},{"type":"verse","number":"115","sanskrit":"गोमूत्रगन्धि नीलं वा तत्प्रधानञ्च वक्ष्यते तद्भावितं सारगणैर्हृतदोषं दिनादितः","text":"gomūtragandhi nīlaṃ vā tatpradhānañca vakṣyate tadbhāvitaṃ sāragaṇairhṛtadoṣaṃ dināditaḥ"},{"type":"verse","number":"116","sanskrit":"पिबेत्सारोदकेनैव श्लक्ष्णपिष्टं यथाबलम् जाङ्गलेन रसेनाद्यात्तस्मिञ्जीर्णे तु भोजनम्","text":"pibetsārodakenaiva ślakṣṇapiṣṭaṃ yathābalam jāṅgalena rasenādyāttasmiñjīrṇe tu bhojanam"},{"type":"verse","number":"117","sanskrit":"उपयुज्य तुलामेकाममृतस्यास्य जन्मतः विजित्य मधुमेहाख्यमातङ्कं रोगकारकम्","text":"upayujya tulāmekāmamṛtasyāsya janmataḥ vijitya madhumehākhyamātaṅkaṃ rogakārakam"},{"type":"verse","number":"118","sanskrit":"वपुर्वर्णबलोपेतः शतं जीवत्यनामयः शतं शतं तुलायां तु सहस्रं दशतौलिकम्","text":"vapurvarṇabalopetaḥ śataṃ jīvatyanāmayaḥ śataṃ śataṃ tulāyāṃ tu sahasraṃ daśataulikam"},{"type":"verse","number":"119","sanskrit":"भल्लातकविधानेन परिहारविधिः स्मृतः मेहं कुष्ठमपस्मारमुन्मादं श्लीपदं गरम्","text":"bhallātakavidhānena parihāravidhiḥ smṛtaḥ mehaṃ kuṣṭhamapasmāramunmādaṃ ślīpadaṃ garam"},{"type":"verse","number":"120","sanskrit":"शोषं शोफार्शसी गुल्मं पाण्डुतां विषमज्वरम् व्यपोहत्यचिरात्कालाच्छिलाजतु निषेवितम्","text":"śoṣaṃ śophārśasī gulmaṃ pāṇḍutāṃ viṣamajvaram vyapohatyacirātkālācchilājatu niṣevitam"},{"type":"verse","number":"121","sanskrit":"न सोऽस्ति रोगो यं वापि न निहन्याच्छिलाजतु शर्करा चिरसम्भूतां भिनत्ति च तथाश्मरीम्","text":"na so'sti rogo yaṃ vāpi na nihanyācchilājatu śarkarā cirasambhūtāṃ bhinatti ca tathāśmarīm"},{"type":"verse","number":"122","sanskrit":"भावनालोडने चास्य कर्त्तव्ये भेषजैर्हितैः एवं च माक्षिकं धातुं तापीजममृतोपमम्","text":"bhāvanāloḍane cāsya karttavye bheṣajairhitaiḥ evaṃ ca mākṣikaṃ dhātuṃ tāpījamamṛtopamam"},{"type":"verse","number":"123","sanskrit":"मधुरं काञ्चनाभासमम्लं वा रजतप्रभम् व्यपोहति जराकुष्ठमेहपाण्ड्वामयक्षयान्","text":"madhuraṃ kāñcanābhāsamamlaṃ vā rajataprabham vyapohati jarākuṣṭhamehapāṇḍvāmayakṣayān"},{"type":"verse","number":"124","sanskrit":"तद्भावितान्कुलत्थांश्च कपोतांश्च विवर्जयेत्","text":"tadbhāvitānkulatthāṃśca kapotāṃśca vivarjayet"},{"type":"verse","number":"125","sanskrit":"प्रमेहपिडिकानां प्राक्कार्यं रक्तावसेचनम् पाटनञ्च विपक्वानां तासां पाने प्रशस्यते","text":"pramehapiḍikānāṃ prākkāryaṃ raktāvasecanam pāṭanañca vipakvānāṃ tāsāṃ pāne praśasyate"},{"type":"verse","number":"126","sanskrit":"क्वाथो वनस्पतेर्बास्त्यं मूत्रं तीक्ष्णञ्च शोधनम् एलादिकेन कल्केन तैलं च व्रणरोपणम्","text":"kvātho vanaspaterbāstyaṃ mūtraṃ tīkṣṇañca śodhanam elādikena kalkena tailaṃ ca vraṇaropaṇam"},{"type":"verse","number":"127","sanskrit":"आरग्वधादिना क्वाथं कुर्यादुद्वर्त्तनानि च शालसारादिना सेकान्भोज्यादींश्चणकादिना","text":"āragvadhādinā kvāthaṃ kuryādudvarttanāni ca śālasārādinā sekānbhojyādīṃścaṇakādinā"},{"type":"verse","number":"128","sanskrit":"प्रमेहिणो यदा मूत्रमनाविलमपिच्छिलम् विशदं तिक्तकटुकं तदारोग्यं प्रचक्षते","text":"pramehiṇo yadā mūtramanāvilamapicchilam viśadaṃ tiktakaṭukaṃ tadārogyaṃ pracakṣate"},{"type":"verse","number":"129","sanskrit":"इत्यष्टत्रिंशः प्रमेहपिडिकाऽधिकारः समाप्तः ३८","text":"ityaṣṭatriṃśaḥ pramehapiḍikā'dhikāraḥ samāptaḥ 38"}]},{"sthana":"Уттаракханда","number":39,"lang":"sa","content":[{"type":"heading","heading":"Стхаулья — ожирение"},{"type":"verse","number":"1","sanskrit":"अव्यायामदिवा स्वप्नश्लेष्मलाहारसेविनः मधुरोऽन्नरसः प्रायः स्नेहान्मेदो विवर्द्धयेत्","text":"avyāyāmadivā svapnaśleṣmalāhārasevinaḥ madhuro'nnarasaḥ prāyaḥ snehānmedo vivarddhayet"},{"type":"verse","number":"2","sanskrit":"मेदसावृतमार्गत्वात्पुष्यन्त्यन्ये न धातवः मेदस्तु चीयते तस्मादशक्तः सर्वकर्मसु","text":"medasāvṛtamārgatvātpuṣyantyanye na dhātavaḥ medastu cīyate tasmādaśaktaḥ sarvakarmasu"},{"type":"verse","number":"3","sanskrit":"क्षुद्र श्वासतृषामोहस्वप्नक्रथनसादनैः युक्तः क्षुत्स्वेददौर्गन्ध्यैरल्पप्राणोऽल्पमैथुनः","text":"kṣudra śvāsatṛṣāmohasvapnakrathanasādanaiḥ yuktaḥ kṣutsvedadaurgandhyairalpaprāṇo'lpamaithunaḥ"},{"type":"verse","number":"4","sanskrit":"मेदस्तु सर्वभूतानामुदरे हि व्यवस्थितम् अत एवोदरे वृद्धिः प्रायो मेदस्विनो भवेत्","text":"medastu sarvabhūtānāmudare hi vyavasthitam ata evodare vṛddhiḥ prāyo medasvino bhavet"},{"type":"verse","number":"5","sanskrit":"मेदसाऽवृतमार्गत्वाद्वायुः कोष्ठे विशेषतः चरन्सन्धुक्षयत्यग्निमाहारं शोषयत्यपि","text":"medasā'vṛtamārgatvādvāyuḥ koṣṭhe viśeṣataḥ caransandhukṣayatyagnimāhāraṃ śoṣayatyapi"},{"type":"verse","number":"6","sanskrit":"तस्मात्स शीघ्रं जरयत्याहारञ्चाभिकाङ्क्षति विकारांश्चाश्नुते घोरान्कांश्चित्कालव्यतिक्रमात्","text":"tasmātsa śīghraṃ jarayatyāhārañcābhikāṅkṣati vikārāṃścāśnute ghorānkāṃścitkālavyatikramāt"},{"type":"verse","number":"7","sanskrit":"एतावुपद्र वकरौ विशेषादग्निमारुतौ एतौ हि दहतः स्थूलं वनं दावानिलौ यथा","text":"etāvupadra vakarau viśeṣādagnimārutau etau hi dahataḥ sthūlaṃ vanaṃ dāvānilau yathā"},{"type":"verse","number":"8","sanskrit":"मेदस्यतीव संवृद्धे सहसैवानिलादयः विकारान्दारुणान्कृत्वा नाशयन्त्याशु जीवितम्","text":"medasyatīva saṃvṛddhe sahasaivānilādayaḥ vikārāndāruṇānkṛtvā nāśayantyāśu jīvitam"},{"type":"verse","number":"9","sanskrit":"मेदोमांसातिवृद्धत्वाच्चलस्फिगुदरस्तनः अयथोपचयोत्साहो नरोऽतिस्थूल उच्यते","text":"medomāṃsātivṛddhatvāccalasphigudarastanaḥ ayathopacayotsāho naro'tisthūla ucyate"},{"type":"verse","number":"10","sanskrit":"स्थूले स्युर्दुस्तराः कुष्ठा विसर्पाः सभगन्दराः ज्वरातीसारमेहार्शःश्लीपदापचिकामलाः मेदसः स्वेददौर्गन्ध्याज्जायन्ते जन्तवोऽणवः","text":"sthūle syurdustarāḥ kuṣṭhā visarpāḥ sabhagandarāḥ jvarātīsāramehārśaḥślīpadāpacikāmalāḥ medasaḥ svedadaurgandhyājjāyante jantavo'ṇavaḥ"},{"type":"verse","number":"11","sanskrit":"पुराणाः शालयो मुद्गाः कुलत्थोद्दालकोद्र वाः लेखना वस्तयश्चैव सेव्या मेदस्विना सदा","text":"purāṇāḥ śālayo mudgāḥ kulatthoddālakodra vāḥ lekhanā vastayaścaiva sevyā medasvinā sadā"},{"type":"verse","number":"12","sanskrit":"धूम्रपानं तथा क्रोधो रक्तमोक्षणमेव च जीर्णे च भोजनं कार्यं यवगोधूमयोःसदा","text":"dhūmrapānaṃ tathā krodho raktamokṣaṇameva ca jīrṇe ca bhojanaṃ kāryaṃ yavagodhūmayoḥsadā"},{"type":"verse","number":"13","sanskrit":"उपवासोऽसुखा शय्या सत्त्वौदार्यं तमोजयः सन्तर्पणकृतैर्दोषैःस्थौल्याद् युक्त्या विमुच्यते","text":"upavāso'sukhā śayyā sattvaudāryaṃ tamojayaḥ santarpaṇakṛtairdoṣaiḥsthaulyād yuktyā vimucyate"},{"type":"verse","number":"14","sanskrit":"श्रमचिन्ताव्यवायाध्व क्षौद्र जागरणप्रियः हन्त्यवश्यमतिस्थौल्यं यवश्यामाकभोजनः","text":"śramacintāvyavāyādhva kṣaudra jāgaraṇapriyaḥ hantyavaśyamatisthaulyaṃ yavaśyāmākabhojanaḥ"},{"type":"verse","number":"15","sanskrit":"सचव्यजीरकव्योषहिङ्गु सौवर्चलानलाः मस्तुना शक्तवः पीता मेदोघ्ना वह्निदीपनाः","text":"sacavyajīrakavyoṣahiṅgu sauvarcalānalāḥ mastunā śaktavaḥ pītā medoghnā vahnidīpanāḥ"},{"type":"verse","number":"16","sanskrit":"फलत्रयं त्रिकटुकं सतैलं लवणान्वितम् षण्मासादुपयोगेन कफमेदोऽनिलापहम्","text":"phalatrayaṃ trikaṭukaṃ satailaṃ lavaṇānvitam ṣaṇmāsādupayogena kaphamedo'nilāpaham"},{"type":"verse","number":"17","sanskrit":"विडङ्गं नागरं क्षारः काललोहरजो मधु यवामलकचूर्णन्तु योगोऽतिस्थौल्यनाशनः","text":"viḍaṅgaṃ nāgaraṃ kṣāraḥ kālaloharajo madhu yavāmalakacūrṇantu yogo'tisthaulyanāśanaḥ"},{"type":"verse","number":"18","sanskrit":"मूलं वा त्रिफलाचूर्णं मधुयुक्तं मधूदकम् बिल्वादिपञ्चमूलस्य प्रयोगः क्षौद्र संयुतः","text":"mūlaṃ vā triphalācūrṇaṃ madhuyuktaṃ madhūdakam bilvādipañcamūlasya prayogaḥ kṣaudra saṃyutaḥ"},{"type":"verse","number":"19","sanskrit":"अतिस्थौल्यहरः प्रोक्तो मण्डकः सेवितो ध्रुवम्","text":"atisthaulyaharaḥ prokto maṇḍakaḥ sevito dhruvam"},{"type":"verse","number":"20","sanskrit":"कर्कशदलवह्निसलिलं शतपुष्पाहिङ्गुसंयुक्तम् पिबतो निहन्तिनियतं सर्वभवां मेदसांवृद्धिम्","text":"karkaśadalavahnisalilaṃ śatapuṣpāhiṅgusaṃyuktam pibato nihantiniyataṃ sarvabhavāṃ medasāṃvṛddhim"},{"type":"verse","number":"21","sanskrit":"क्षारं वातारिपत्रस्य हिङ्गुयुक्तं पिबेन्नरः मेदोवृद्धिविनाशाय भक्तं मण्डसमन्वितम्","text":"kṣāraṃ vātāripatrasya hiṅguyuktaṃ pibennaraḥ medovṛddhivināśāya bhaktaṃ maṇḍasamanvitam"},{"type":"verse","number":"22","sanskrit":"गवेधुकानां पिष्टानां यवानाञ्चाथ सक्तवः सक्षौद्र त्रिफलाक्वाथः पीतो मेदोहरो मतः","text":"gavedhukānāṃ piṣṭānāṃ yavānāñcātha saktavaḥ sakṣaudra triphalākvāthaḥ pīto medoharo mataḥ"},{"type":"verse","number":"23","sanskrit":"गुडूचीत्रिफलाक्वाथस्तथा लोहरजोऽन्वितः अश्मजं महिषाक्षं वा तेनैव विधिना पचेत्","text":"guḍūcītriphalākvāthastathā loharajo'nvitaḥ aśmajaṃ mahiṣākṣaṃ vā tenaiva vidhinā pacet"},{"type":"verse","number":"24","sanskrit":"अतिमुक्तबीजमध्यं मधुलीढंहन्त्युदरवृद्धिम् मधुना चित्रकमूलं तथैव हितभोजनो भुङ्क्ते","text":"atimuktabījamadhyaṃ madhulīḍhaṃhantyudaravṛddhim madhunā citrakamūlaṃ tathaiva hitabhojano bhuṅkte"},{"type":"verse","number":"25","sanskrit":"यद्वोरुवूकमूलं मधुदिग्धं स्थाप्यते निशां सकलाम् तस्य सलिलस्य पानाज्जठरे वृद्धिः शमं याति","text":"yadvoruvūkamūlaṃ madhudigdhaṃ sthāpyate niśāṃ sakalām tasya salilasya pānājjaṭhare vṛddhiḥ śamaṃ yāti"},{"type":"verse","number":"26","sanskrit":"प्रातर्मधुयुतं वारि सेवितं स्थौल्यनाशनम् उष्णमन्नस्य मण्डं वा पिबन्कृशतनुर्भवेत्","text":"prātarmadhuyutaṃ vāri sevitaṃ sthaulyanāśanam uṣṇamannasya maṇḍaṃ vā pibankṛśatanurbhavet"},{"type":"verse","number":"27","sanskrit":"बदरीपत्रकल्केन पेया काञ्जिकसाधिता स्थौल्यनुत्स्यादग्निमन्थरसक्वाथः शिलाजतु","text":"badarīpatrakalkena peyā kāñjikasādhitā sthaulyanutsyādagnimantharasakvāthaḥ śilājatu"},{"type":"verse","number":"28","sanskrit":"शैलेयकुष्ठागुरुदेवदारुकौन्तीसमुस्तान्यथ पञ्चपत्रैः श्रीवासस्पृक्काखरपुष्पदेवपुष्पं तथा सर्वमिदं प्रपिष्य धत्तूरपत्रस्य रसेन गाढमुद्वर्त्तनं स्थौल्यहरं प्रदिष्टम्","text":"śaileyakuṣṭhāgurudevadārukauntīsamustānyatha pañcapatraiḥ śrīvāsaspṛkkākharapuṣpadevapuṣpaṃ tathā sarvamidaṃ prapiṣya dhattūrapatrasya rasena gāḍhamudvarttanaṃ sthaulyaharaṃ pradiṣṭam"},{"type":"verse","number":"29","sanskrit":"अमृतात्रुटिवेल्लवत्सकं कलिपथ्याऽमलकानि गुग्गुलुः क्रमवृद्धमिदं मधुप्लुतं पिडिकास्थौल्यभगन्दराञ्जयेत्","text":"amṛtātruṭivellavatsakaṃ kalipathyā'malakāni gugguluḥ kramavṛddhamidaṃ madhuplutaṃ piḍikāsthaulyabhagandarāñjayet"},{"type":"verse","number":"30","sanskrit":"व्योषाग्नित्रिफलामुस्तविडङ्गैर्गुग्गुलं समम् खादन्सर्वाञ्जयेद् व्याधीन्मेदःश्लेष्मामवातजान्","text":"vyoṣāgnitriphalāmustaviḍaṅgairguggulaṃ samam khādansarvāñjayed vyādhīnmedaḥśleṣmāmavātajān"},{"type":"verse","number":"31","sanskrit":"त्र्यूषणाग्निघनवेल्लवचाभिर्भक्षयन्समघृतं महिषाक्षम् आशु हन्ति कफमारुतमेदोदोषजान्बलवतोऽपि विकारान्","text":"tryūṣaṇāgnighanavellavacābhirbhakṣayansamaghṛtaṃ mahiṣākṣam āśu hanti kaphamārutamedodoṣajānbalavato'pi vikārān"},{"type":"verse","number":"32","sanskrit":"गुग्गुलुस्तालमूली च त्रिफला खदिरं वृषम् त्रिवृताऽलम्बुषा शुण्ठी निर्गुण्डी चित्रकस्तथा","text":"guggulustālamūlī ca triphalā khadiraṃ vṛṣam trivṛtā'lambuṣā śuṇṭhī nirguṇḍī citrakastathā"},{"type":"verse","number":"33","sanskrit":"एषां दशपलान्भागांस्तोये पञ्चाढके पचेत् पादशेषं ततः कृत्वा कषायमवतारयेत्","text":"eṣāṃ daśapalānbhāgāṃstoye pañcāḍhake pacet pādaśeṣaṃ tataḥ kṛtvā kaṣāyamavatārayet"},{"type":"verse","number":"34","sanskrit":"पलद्वादशकं देयं रुक्मलोहं सुचूर्णितम्","text":"paladvādaśakaṃ deyaṃ rukmalohaṃ sucūrṇitam"},{"type":"verse","number":"35","sanskrit":"पुराणसर्पिषः प्रस्थं शर्कराऽष्टपलान्वितम् पचेत्ताम्रमये पात्रे सुशीते चावदारिते","text":"purāṇasarpiṣaḥ prasthaṃ śarkarā'ṣṭapalānvitam pacettāmramaye pātre suśīte cāvadārite"},{"type":"verse","number":"36","sanskrit":"प्रस्थार्द्धं माक्षिकं देयं शिलाजतु पलद्वयम् एलात्वचोः पलार्द्धञ्च विडङ्गानि पलत्रयम्","text":"prasthārddhaṃ mākṣikaṃ deyaṃ śilājatu paladvayam elātvacoḥ palārddhañca viḍaṅgāni palatrayam"},{"type":"verse","number":"37","sanskrit":"मरिचं चाञ्जनं कृष्णा द्विपलं त्रिफलाऽन्वितम् पलद्वयन्तु कासीसं सूक्ष्मचूर्णीकृतं बुधैः","text":"maricaṃ cāñjanaṃ kṛṣṇā dvipalaṃ triphalā'nvitam paladvayantu kāsīsaṃ sūkṣmacūrṇīkṛtaṃ budhaiḥ"},{"type":"verse","number":"38","sanskrit":"चूर्णं दत्वा सुमथितं स्निग्धे भाण्डे निधापयेत् ततः संशुद्धदेहस्तु भक्षयेदक्षमात्रकम्","text":"cūrṇaṃ datvā sumathitaṃ snigdhe bhāṇḍe nidhāpayet tataḥ saṃśuddhadehastu bhakṣayedakṣamātrakam"},{"type":"verse","number":"39","sanskrit":"अनुपानं पिबेत्क्षीरं जाङ्गलानां रसं तथा वातश्लेष्महरं श्रेष्ठं कुष्ठमेहोदरापहम्","text":"anupānaṃ pibetkṣīraṃ jāṅgalānāṃ rasaṃ tathā vātaśleṣmaharaṃ śreṣṭhaṃ kuṣṭhamehodarāpaham"},{"type":"verse","number":"40","sanskrit":"कामलां पाण्डुरोगञ्च श्वयथुं सभगन्दरम् मूर्च्छामोहविषोन्मादगराणि विषमाणि च","text":"kāmalāṃ pāṇḍurogañca śvayathuṃ sabhagandaram mūrcchāmohaviṣonmādagarāṇi viṣamāṇi ca"},{"type":"verse","number":"41","sanskrit":"स्थूलानां कर्षणं श्रेष्ठं मेदुरे परमौषधम् कर्षयेच्चातिमात्रेण कुक्षिं पातालसन्निभम्","text":"sthūlānāṃ karṣaṇaṃ śreṣṭhaṃ medure paramauṣadham karṣayeccātimātreṇa kukṣiṃ pātālasannibham"},{"type":"verse","number":"42","sanskrit":"बल्यं रसायनं मेध्यं वाजीकरणमुत्तमम् श्रीकरं पुत्रजननं वलीपलितनाशनम्","text":"balyaṃ rasāyanaṃ medhyaṃ vājīkaraṇamuttamam śrīkaraṃ putrajananaṃ valīpalitanāśanam"},{"type":"verse","number":"43","sanskrit":"नाश्नीयात्कदलीकन्दं काञ्जिकं करमर्दकम् करीरं कारवेल्लञ्च ककारादि विवर्जयेत्","text":"nāśnīyātkadalīkandaṃ kāñjikaṃ karamardakam karīraṃ kāravellañca kakārādi vivarjayet"},{"type":"verse","number":"44","sanskrit":"शालसारादिनिर्यूहं चतुर्थांशावशेषितम् परिस्रुतं ततः शीतं मधुना मधुरीकृतम्","text":"śālasārādiniryūhaṃ caturthāṃśāvaśeṣitam parisrutaṃ tataḥ śītaṃ madhunā madhurīkṛtam"},{"type":"verse","number":"45","sanskrit":"फाणितीभावमापन्नं गुडं शोधितमेव च सूक्ष्मपिष्टानि चूर्णानि पिप्पल्यादेर्गणस्य च","text":"phāṇitībhāvamāpannaṃ guḍaṃ śodhitameva ca sūkṣmapiṣṭāni cūrṇāni pippalyādergaṇasya ca"},{"type":"verse","number":"46","sanskrit":"एकध्यमावपेत्कुम्भे संस्कृते घृतभाविते पिप्पलीचूर्णमधुभिः प्रलिप्ते चान्तरे शुचौ","text":"ekadhyamāvapetkumbhe saṃskṛte ghṛtabhāvite pippalīcūrṇamadhubhiḥ pralipte cāntare śucau"},{"type":"verse","number":"47","sanskrit":"सूक्ष्माणि तीक्ष्णलोहस्य तनुपत्राणि बुद्धिमान् खदिराङ्गारतप्तानि बहुशः प्रक्षिपेद् बुधः","text":"sūkṣmāṇi tīkṣṇalohasya tanupatrāṇi buddhimān khadirāṅgārataptāni bahuśaḥ prakṣiped budhaḥ"},{"type":"verse","number":"48","sanskrit":"सुपिधानं ततः कृत्वा यवपल्वे निधापयेत् मासांस्त्रींश्चतुरो वाऽपि यावद्वा लोहसंक्षयात्","text":"supidhānaṃ tataḥ kṛtvā yavapalve nidhāpayet māsāṃstrīṃścaturo vā'pi yāvadvā lohasaṃkṣayāt"},{"type":"verse","number":"49","sanskrit":"ततो जातरसं जन्तुः प्रातः प्रातर्यथाबलम् उपयुञ्ज्याद्यथायोग्यमाहारं चास्य कल्पयेत्","text":"tato jātarasaṃ jantuḥ prātaḥ prātaryathābalam upayuñjyādyathāyogyamāhāraṃ cāsya kalpayet"},{"type":"verse","number":"50","sanskrit":"एष स्थूलं समाकर्षेन्नष्टस्याग्नेः प्रबोधनः शोथघ्नः कुष्ठमेहघ्नो गुल्मपाण्ड्वामयापहः","text":"eṣa sthūlaṃ samākarṣennaṣṭasyāgneḥ prabodhanaḥ śothaghnaḥ kuṣṭhamehaghno gulmapāṇḍvāmayāpahaḥ"},{"type":"verse","number":"51","sanskrit":"प्लीहोदरहरः शीघ्रं विषमज्वरनाशनः अभिष्यन्दापहरणे लोहारिष्टो महागुणः","text":"plīhodaraharaḥ śīghraṃ viṣamajvaranāśanaḥ abhiṣyandāpaharaṇe lohāriṣṭo mahāguṇaḥ"},{"type":"verse","number":"52","sanskrit":"व्योषचित्रकशिग्रूणि त्रिफलां कटुरोहिणीम् बृहत्यौ द्वे हरिद्रे च पाठामतिविषां स्थिराम् हिङ्गुकेवुकमूलानि यवानीं धान्यचित्रकम् सौवर्च्चलमजाजीञ्च हपुषां चेति चूर्णयेत्","text":"vyoṣacitrakaśigrūṇi triphalāṃ kaṭurohiṇīm bṛhatyau dve haridre ca pāṭhāmativiṣāṃ sthirām hiṅgukevukamūlāni yavānīṃ dhānyacitrakam sauvarccalamajājīñca hapuṣāṃ ceti cūrṇayet"},{"type":"verse","number":"53","sanskrit":"चूर्णतैलघृतक्षौद्र भागाः स्युर्मानतः समाः शक्तूनां षोडशगुणो भागः सन्तर्पणं पिबेत्","text":"cūrṇatailaghṛtakṣaudra bhāgāḥ syurmānataḥ samāḥ śaktūnāṃ ṣoḍaśaguṇo bhāgaḥ santarpaṇaṃ pibet"},{"type":"verse","number":"54","sanskrit":"प्रयोगात्त्वस्य शाम्यन्ति रोगाः सन्तर्पणोत्थिताः प्रमेहा मूढवाताश्च कुष्ठान्यर्शांसि कामलाः","text":"prayogāttvasya śāmyanti rogāḥ santarpaṇotthitāḥ pramehā mūḍhavātāśca kuṣṭhānyarśāṃsi kāmalāḥ"},{"type":"verse","number":"55","sanskrit":"प्लीहा पाण्ड्वामयः शोथो मूत्रकृच्छ्रमरोचकः हृद्रो गो राजयक्ष्मा च कासश्वासौ गलग्रहः","text":"plīhā pāṇḍvāmayaḥ śotho mūtrakṛcchramarocakaḥ hṛdro go rājayakṣmā ca kāsaśvāsau galagrahaḥ"},{"type":"verse","number":"56","sanskrit":"कृमयो ग्रहणीदोषः श्वैत्र्यं स्थौल्यमतीव च नराणां दीप्यते वह्निः स्मृतिर्बुद्धिश्च वर्द्धते","text":"kṛmayo grahaṇīdoṣaḥ śvaitryaṃ sthaulyamatīva ca narāṇāṃ dīpyate vahniḥ smṛtirbuddhiśca varddhate"},{"type":"verse","number":"57","sanskrit":"त्रिफलातिविषामूर्वात्रि वृच्चित्रकवासकैः निम्बारग्वधषड्ग्रन्था सप्तपर्णनिशाद्वयैः","text":"triphalātiviṣāmūrvātri vṛccitrakavāsakaiḥ nimbāragvadhaṣaḍgranthā saptaparṇaniśādvayaiḥ"},{"type":"verse","number":"58","sanskrit":"गुडूचीन्द्रा सुरीकृष्णा कुष्ठसर्षपनागरैः तैलमेभिः समैः पक्वं सुरसादिरसाप्लुतम्","text":"guḍūcīndrā surīkṛṣṇā kuṣṭhasarṣapanāgaraiḥ tailamebhiḥ samaiḥ pakvaṃ surasādirasāplutam"},{"type":"verse","number":"59","sanskrit":"पानाभ्यञ्जनगण्डूषनस्यवस्तिषु योजितम् स्थूलतालस्यपाण्ड्वादीञ्जयेत्कफकृतान्गदान्","text":"pānābhyañjanagaṇḍūṣanasyavastiṣu yojitam sthūlatālasyapāṇḍvādīñjayetkaphakṛtāngadān"},{"type":"verse","number":"60","sanskrit":"चन्दनं कुङ्कमोशीरप्रियङ्गुत्रुटिरोचनाः तुरुष्कागुरुकस्तूरीकर्पूरा जातिपत्रिका","text":"candanaṃ kuṅkamośīrapriyaṅgutruṭirocanāḥ turuṣkāgurukastūrīkarpūrā jātipatrikā"},{"type":"verse","number":"61","sanskrit":"जातीकङ्कोलपूगानां लवङ्गस्य फलानि च नलिका नलदं कुष्ठं हरेणु तगरं प्लवम्","text":"jātīkaṅkolapūgānāṃ lavaṅgasya phalāni ca nalikā naladaṃ kuṣṭhaṃ hareṇu tagaraṃ plavam"},{"type":"verse","number":"62","sanskrit":"नवव्याघ्रनखं स्पृक्का बोलं दमनकं तथा स्थौणेयकं चोरकञ्च शैलेयं सैलवालुकम्","text":"navavyāghranakhaṃ spṛkkā bolaṃ damanakaṃ tathā sthauṇeyakaṃ corakañca śaileyaṃ sailavālukam"},{"type":"verse","number":"63","sanskrit":"सरलं सप्तपर्णञ्च लाक्षा तामलकी तथा लामज्जकं पद्मकञ्च धातक्याः कुसुमानि च","text":"saralaṃ saptaparṇañca lākṣā tāmalakī tathā lāmajjakaṃ padmakañca dhātakyāḥ kusumāni ca"},{"type":"verse","number":"64","sanskrit":"प्रपौण्डरीकं कर्चूरं समांशैः शाणमात्रकैः महासुगन्धमित्येतत्तैलप्रस्थेन साधयेत्","text":"prapauṇḍarīkaṃ karcūraṃ samāṃśaiḥ śāṇamātrakaiḥ mahāsugandhamityetattailaprasthena sādhayet"},{"type":"verse","number":"65","sanskrit":"प्रस्वेदजलदौर्गन्ध्यकण्डूकुष्ठहरं परम् अनेनाभ्यक्तगात्रस्तु वृद्धः सप्ततिकोपि वा","text":"prasvedajaladaurgandhyakaṇḍūkuṣṭhaharaṃ param anenābhyaktagātrastu vṛddhaḥ saptatikopi vā"},{"type":"verse","number":"66","sanskrit":"युवा भवति शुक्राढ्यः स्त्रीणामत्यन्तवल्लभः सुभगो दर्शनीयश्च गच्छेच्च प्रमदाशतम्","text":"yuvā bhavati śukrāḍhyaḥ strīṇāmatyantavallabhaḥ subhago darśanīyaśca gacchecca pramadāśatam"},{"type":"verse","number":"67","sanskrit":"वन्ध्यापि लभते गर्भं षण्ढोपि पुरुषायते अपुत्रः पुत्रमाप्नोति जीवेच्च शरदां शतम्","text":"vandhyāpi labhate garbhaṃ ṣaṇḍhopi puruṣāyate aputraḥ putramāpnoti jīvecca śaradāṃ śatam"},{"type":"verse","number":"68","sanskrit":"इति महासुगन्धि तैलम् वासादलरसो लेपाच्छङ्खचूर्णेन संयुतः बिल्वपत्ररसो वापि गात्रदौर्गन्ध्यनाशनः","text":"iti mahāsugandhi tailam vāsādalaraso lepācchaṅkhacūrṇena saṃyutaḥ bilvapatraraso vāpi gātradaurgandhyanāśanaḥ"},{"type":"verse","number":"69","sanskrit":"अलम्बुषाभवं चूर्णं पीतं काञ्जिकसंयुतम् दौर्गन्ध्यं नाशयत्याशु दुष्टं मेदोभवं नृणाम्","text":"alambuṣābhavaṃ cūrṇaṃ pītaṃ kāñjikasaṃyutam daurgandhyaṃ nāśayatyāśu duṣṭaṃ medobhavaṃ nṛṇām"},{"type":"verse","number":"70","sanskrit":"बिल्वशिवा समभागा लेपाद् भुजमूलगन्धमपहरति परिणतपिडिकाञ्चापि पूतिकरञ्जोत्थबीजं वा","text":"bilvaśivā samabhāgā lepād bhujamūlagandhamapaharati pariṇatapiḍikāñcāpi pūtikarañjotthabījaṃ vā"},{"type":"verse","number":"71","sanskrit":"चिञ्चापत्रस्वरसं म्रक्षितकल्कादियोजितं जयति दग्धहरिद्रो द्वर्त्तनमचिराच्चिरदेहदौर्गन्ध्यम्","text":"ciñcāpatrasvarasaṃ mrakṣitakalkādiyojitaṃ jayati dagdhaharidro dvarttanamacirācciradehadaurgandhyam"},{"type":"verse","number":"72","sanskrit":"शिरीषलामज्जकहेमलोध्रैस्त्वग्दोषसंस्वेदहरः प्रघर्षः पत्राम्बुलोहाभयचन्दनानि शरीरदौर्गन्ध्यहरः प्रदेहः","text":"śirīṣalāmajjakahemalodhraistvagdoṣasaṃsvedaharaḥ pragharṣaḥ patrāmbulohābhayacandanāni śarīradaurgandhyaharaḥ pradehaḥ"},{"type":"verse","number":"73","sanskrit":"हिलमोचिरसो युक्तश्चूर्णैरुदधिफेनजैः प्रलेपेन हरत्याशु देहदौर्गन्ध्यमुत्कटम्","text":"hilamociraso yuktaścūrṇairudadhiphenajaiḥ pralepena haratyāśu dehadaurgandhyamutkaṭam"},{"type":"verse","number":"74","sanskrit":"हरीतकीं तु सम्पिष्य गात्रमुद्वर्त्तयेन्नरः पश्चात्स्नानं प्रकुर्वीत देहस्वेदप्रशान्तये","text":"harītakīṃ tu sampiṣya gātramudvarttayennaraḥ paścātsnānaṃ prakurvīta dehasvedapraśāntaye"},{"type":"verse","number":"75","sanskrit":"हरीतकी लोध्रमरिष्टपत्रं चूतत्वचो दाडिमवल्कलञ्च एषोऽङ्गरागः कथितोऽङ्गनानां जम्ब्वाः कषायस्तु नराधिपानाम्","text":"harītakī lodhramariṣṭapatraṃ cūtatvaco dāḍimavalkalañca eṣo'ṅgarāgaḥ kathito'ṅganānāṃ jambvāḥ kaṣāyastu narādhipānām"},{"type":"verse","number":"76","sanskrit":"गोमूत्रपिष्टं विनिहन्ति कुष्ठं वर्णोज्ज्वलं गोपयसा च युक्तम् कक्षादिदौर्गन्ध्यहरं पयोभिः शस्तं वशीकृद्र जनीद्वयेन","text":"gomūtrapiṣṭaṃ vinihanti kuṣṭhaṃ varṇojjvalaṃ gopayasā ca yuktam kakṣādidaurgandhyaharaṃ payobhiḥ śastaṃ vaśīkṛdra janīdvayena"},{"type":"verse","number":"77","sanskrit":"बब्बूलस्य दलैः सम्यग्वारिणा परिपेषितैः गात्रमुद्वर्त्तयेत्पश्चाद्धरीतक्या सुपिष्टया","text":"babbūlasya dalaiḥ samyagvāriṇā paripeṣitaiḥ gātramudvarttayetpaścāddharītakyā supiṣṭayā"},{"type":"verse","number":"78","sanskrit":"भूय उद्वर्त्तनं कृत्वा पश्चात्स्नानं समाचरेत् प्रस्वेदान्मुच्यते शीघ्रं ततस्त्वेवं समाचरेत्","text":"bhūya udvarttanaṃ kṛtvā paścātsnānaṃ samācaret prasvedānmucyate śīghraṃ tatastvevaṃ samācaret"},{"type":"verse","number":"79","sanskrit":"बिल्वाम्रजम्बूफलपूरकाणां पत्रैः कपित्थस्य दलानुमिश्रैः आपूर्ववत्कर्मविधानयोगैर्वचा विशोध्या वरगन्धहेतोः","text":"bilvāmrajambūphalapūrakāṇāṃ patraiḥ kapitthasya dalānumiśraiḥ āpūrvavatkarmavidhānayogairvacā viśodhyā varagandhahetoḥ"},{"type":"verse","number":"80","sanskrit":"पथ्यानखीचन्दनकुष्ठसर्जैः पुनः पुनश्चागुरुशर्कराभ्याम् धूपो जनानां हृदयापहारी विख्यातनामा मलयानिलोऽयम्","text":"pathyānakhīcandanakuṣṭhasarjaiḥ punaḥ punaścāguruśarkarābhyām dhūpo janānāṃ hṛdayāpahārī vikhyātanāmā malayānilo'yam"},{"type":"verse","number":"81","sanskrit":"चण्डांशुकतिलैर्लोध्र शिरीषोशीरकेशरैः उद्वर्त्तनं भवेद् ग्रीष्मे स्वेदकर्मनिवारणम्","text":"caṇḍāṃśukatilairlodhra śirīṣośīrakeśaraiḥ udvarttanaṃ bhaved grīṣme svedakarmanivāraṇam"},{"type":"verse","number":"82","sanskrit":"सुरया सममभयाफलचूर्णं मधुना विलिह्य प्रत्यूषे स्वेदान्हत्वा लभते पुरुषोप्यत्यन्तसौरभ्यम्","text":"surayā samamabhayāphalacūrṇaṃ madhunā vilihya pratyūṣe svedānhatvā labhate puruṣopyatyantasaurabhyam"},{"type":"verse","number":"83","sanskrit":"मल्लीकुसुमाभयकरिलेपो घर्मे विचर्चिकादाहे विचकिलपत्रहरिद्रे पर्कटिपत्रञ्च दूर्वया सहितम्","text":"mallīkusumābhayakarilepo gharme vicarcikādāhe vicakilapatraharidre parkaṭipatrañca dūrvayā sahitam"},{"type":"verse","number":"84","sanskrit":"सम्पिष्य गात्रलेपाद्घर्मविचर्ची शमं याति","text":"sampiṣya gātralepādgharmavicarcī śamaṃ yāti"},{"type":"verse","number":"85","sanskrit":"हस्तपादस्रुतौ योज्यो गुग्गुलः पञ्चतिक्तकः अशक्तौ पञ्चतिक्ताख्यं घृतं खादेदतन्द्रि तः","text":"hastapādasrutau yojyo guggulaḥ pañcatiktakaḥ aśaktau pañcatiktākhyaṃ ghṛtaṃ khādedatandri taḥ"},{"type":"verse","number":"86","sanskrit":"इत्येकोनचत्वारिंशत्तमः स्थौल्याधिकारो वा मेदोरोगाधिकारः समाप्तः ३९","text":"ityekonacatvāriṃśattamaḥ sthaulyādhikāro vā medorogādhikāraḥ samāptaḥ 39"}]},{"sthana":"Уттаракханда","number":40,"lang":"sa","content":[{"type":"heading","heading":"Каршья — истощение"},{"type":"verse","number":"1","sanskrit":"वातो रुक्षान्नपानानि लङ्घनं प्रमिताशनम् क्रियाऽतियोगः शोकश्च वेगनिद्रा विनिग्रहः","text":"vāto rukṣānnapānāni laṅghanaṃ pramitāśanam kriyā'tiyogaḥ śokaśca veganidrā vinigrahaḥ"},{"type":"verse","number":"2","sanskrit":"नित्यं रोगो रतिर्नित्यं व्यायामो भोजनाल्पता भीतिर्धनादिचिन्ता च कार्श्यकारणमीरितम्","text":"nityaṃ rogo ratirnityaṃ vyāyāmo bhojanālpatā bhītirdhanādicintā ca kārśyakāraṇamīritam"},{"type":"verse","number":"3","sanskrit":"शुष्कस्फिगुदरग्रीवा धमनीजालसन्ततिः त्वगस्थिशोषोऽतिकृशः स्थूलपर्वाननो मतः","text":"śuṣkasphigudaragrīvā dhamanījālasantatiḥ tvagasthiśoṣo'tikṛśaḥ sthūlaparvānano mataḥ"},{"type":"verse","number":"4","sanskrit":"प्लीहकासक्षयश्वासगुल्मार्शांस्युदराणि च भृशं कृशं प्रधावन्ति रोगाश्च ग्रहणीमुखाः कश्चिदन्यः कृशोऽतीव बलवान्दृश्यते तदा","text":"plīhakāsakṣayaśvāsagulmārśāṃsyudarāṇi ca bhṛśaṃ kṛśaṃ pradhāvanti rogāśca grahaṇīmukhāḥ kaścidanyaḥ kṛśo'tīva balavāndṛśyate tadā"},{"type":"verse","number":"5","sanskrit":"आधानसमये यस्य शुक्रभागोऽधिको भवेत् मेदोभागस्तु हीनः स्यात्स कृशोऽपि महाबलः","text":"ādhānasamaye yasya śukrabhāgo'dhiko bhavet medobhāgastu hīnaḥ syātsa kṛśo'pi mahābalaḥ"},{"type":"verse","number":"6","sanskrit":"मेदसस्त्वधिको यस्य शुक्रभागोऽल्पको भवेत् स स्निग्धोऽपि सुपुष्टोऽपि बलहीनो विलोक्यते","text":"medasastvadhiko yasya śukrabhāgo'lpako bhavet sa snigdho'pi supuṣṭo'pi balahīno vilokyate"},{"type":"verse","number":"7","sanskrit":"रुक्षान्नादिनिमित्ते तु कृशे युञ्जीत भेषजम् बृंहणं बलकृद् वृष्यं तथा वाजीकरञ्च यत्","text":"rukṣānnādinimitte tu kṛśe yuñjīta bheṣajam bṛṃhaṇaṃ balakṛd vṛṣyaṃ tathā vājīkarañca yat"},{"type":"verse","number":"8","sanskrit":"पीताऽश्वगन्धा पयसाऽद्धमासं घृतेन तैलेन सुखाम्बुना वा कृशस्य पुष्टिं वपुषो विधत्ते बालस्य सस्यस्य यथाऽम्बुवृष्टिः","text":"pītā'śvagandhā payasā'ddhamāsaṃ ghṛtena tailena sukhāmbunā vā kṛśasya puṣṭiṃ vapuṣo vidhatte bālasya sasyasya yathā'mbuvṛṣṭiḥ"},{"type":"verse","number":"9","sanskrit":"अश्वगन्धस्य कल्केन क्वाथे तस्मिन्पयस्यपि सिद्धं तैलं कृशाङ्गानामभ्यङ्गादङ्गपुष्टिदम्","text":"aśvagandhasya kalkena kvāthe tasminpayasyapi siddhaṃ tailaṃ kṛśāṅgānāmabhyaṅgādaṅgapuṣṭidam"},{"type":"verse","number":"10","sanskrit":"पुष्टिकृद्वालरोगोक्तमश्वगन्धाघृतं भजेत् वाजीकरोदितं तद्वदश्वगन्धाघृतादिकम्","text":"puṣṭikṛdvālarogoktamaśvagandhāghṛtaṃ bhajet vājīkaroditaṃ tadvadaśvagandhāghṛtādikam"},{"type":"verse","number":"11","sanskrit":"स्वभावादतिकार्श्योयः स्वभावादल्पपावकः स्वभावादबलो यश्च तस्य नास्ति चिकित्सितम्","text":"svabhāvādatikārśyoyaḥ svabhāvādalpapāvakaḥ svabhāvādabalo yaśca tasya nāsti cikitsitam"},{"type":"verse","number":"12","sanskrit":"इति चत्वारिंशत्तमः कार्श्याधिकारः समाप्तः ४०","text":"iti catvāriṃśattamaḥ kārśyādhikāraḥ samāptaḥ 40"}]},{"sthana":"Уттаракханда","number":41,"lang":"sa","content":[{"type":"heading","heading":"Удара — болезни живота (асцит)"},{"type":"verse","number":"1","sanskrit":"रोगाः सर्वेऽपि मन्देऽग्नौ सुतरामुदराणि च अजीर्णान्मलिनैश्चान्नैश्चीयन्ते मलसञ्चयात्","text":"rogāḥ sarve'pi mande'gnau sutarāmudarāṇi ca ajīrṇānmalinaiścānnaiścīyante malasañcayāt"},{"type":"verse","number":"2","sanskrit":"रुद्ध्वा स्वेदाम्बुवाहीनि दोषाः स्रोतांसि सञ्चिताः प्राणानपानान्संदूष्य जनयन्त्युदरं नृणाम्","text":"ruddhvā svedāmbuvāhīni doṣāḥ srotāṃsi sañcitāḥ prāṇānapānānsaṃdūṣya janayantyudaraṃ nṛṇām"},{"type":"verse","number":"3","sanskrit":"आध्मानं गमनेऽशक्तिर्दौर्बल्यं दुर्बलाग्निता शोथः सदनमङ्गानां सङ्गो वातपुरीषयोः दाहस्तन्द्रा च सर्वेषु जठरेषु भवन्ति हि","text":"ādhmānaṃ gamane'śaktirdaurbalyaṃ durbalāgnitā śothaḥ sadanamaṅgānāṃ saṅgo vātapurīṣayoḥ dāhastandrā ca sarveṣu jaṭhareṣu bhavanti hi"},{"type":"verse","number":"4","sanskrit":"पृथग्दोषैः समस्तैश्च प्लीहबद्धक्षतोदकैः सम्भवन्त्युदराण्यष्टौ तेषां लिङ्गं पृथक् शृणु","text":"pṛthagdoṣaiḥ samastaiśca plīhabaddhakṣatodakaiḥ sambhavantyudarāṇyaṣṭau teṣāṃ liṅgaṃ pṛthak śṛṇu"},{"type":"verse","number":"5","sanskrit":"तत्र वातोदरे शोथः पाणिपान्नाभिकुक्षिषु कुक्षिपार्श्वोदरकटी पृष्ठरुक्पर्वभेदनम्","text":"tatra vātodare śothaḥ pāṇipānnābhikukṣiṣu kukṣipārśvodarakaṭī pṛṣṭharukparvabhedanam"},{"type":"verse","number":"6","sanskrit":"शुष्ककासोऽङ्गमर्दश्च गुरुतामलसंग्रहः श्यावारुणत्वगादित्वमकस्माद्ध्रासवृद्धिमत्","text":"śuṣkakāso'ṅgamardaśca gurutāmalasaṃgrahaḥ śyāvāruṇatvagāditvamakasmāddhrāsavṛddhimat"},{"type":"verse","number":"7","sanskrit":"सतोदभेदमुदरं तनुकृष्णशिराततम् आध्मातदृतिवच्छब्दमाहतं प्रकरोति च","text":"satodabhedamudaraṃ tanukṛṣṇaśirātatam ādhmātadṛtivacchabdamāhataṃ prakaroti ca"},{"type":"verse","number":"8","sanskrit":"वायुश्चात्र सरुक्छब्दो विचरेत्सर्वतो गतिः","text":"vāyuścātra sarukchabdo vicaretsarvato gatiḥ"},{"type":"verse","number":"9","sanskrit":"पित्तोदरे ज्वरो मूर्च्छा दाहस्तृट् कटुकास्यता भ्रमोऽतिसारः पीतत्वं त्वगादावुदरं हरित्","text":"pittodare jvaro mūrcchā dāhastṛṭ kaṭukāsyatā bhramo'tisāraḥ pītatvaṃ tvagādāvudaraṃ harit"},{"type":"verse","number":"10","sanskrit":"पीतताम्रशिरानद्धं सस्वेदं सोष्म दह्यते धूमायते मृदुस्पर्शः क्षिप्रपाकं प्रदूयते","text":"pītatāmraśirānaddhaṃ sasvedaṃ soṣma dahyate dhūmāyate mṛdusparśaḥ kṣiprapākaṃ pradūyate"},{"type":"verse","number":"11","sanskrit":"श्लेष्मोदरेऽङ्गसदनं श्वयथुर्गौरवं तथा तन्द्रो त्क्लेशोऽरुचिः स्वापः कासः शौक्ल्यं त्वगादिषु","text":"śleṣmodare'ṅgasadanaṃ śvayathurgauravaṃ tathā tandro tkleśo'ruciḥ svāpaḥ kāsaḥ śauklyaṃ tvagādiṣu"},{"type":"verse","number":"12","sanskrit":"उदरं स्तिमितं स्निग्धं शुक्लराजीततं महत् चिराभिवृद्धि कठिनं शीतस्पर्शं गुरु स्थिरम्","text":"udaraṃ stimitaṃ snigdhaṃ śuklarājītataṃ mahat cirābhivṛddhi kaṭhinaṃ śītasparśaṃ guru sthiram"},{"type":"verse","number":"13","sanskrit":"स्त्रियोऽन्नपानं नखलोममूत्रविडार्त्तवैर्युक्तमसाधुवृत्ताः यस्मै प्रयच्छन्त्यरयो गरांश्च दुष्टाम्बुदूषीविषसेवनाच्च","text":"striyo'nnapānaṃ nakhalomamūtraviḍārttavairyuktamasādhuvṛttāḥ yasmai prayacchantyarayo garāṃśca duṣṭāmbudūṣīviṣasevanācca"},{"type":"verse","number":"14","sanskrit":"तस्याशु रक्तं कुपिताश्च दोषाः कुर्युः सुघोरं जठरं त्रिलिङ्गम् तच्छीतवाते भृशदुर्दिने च विशेषतः कुप्यति दह्यते च","text":"tasyāśu raktaṃ kupitāśca doṣāḥ kuryuḥ sughoraṃ jaṭharaṃ triliṅgam tacchītavāte bhṛśadurdine ca viśeṣataḥ kupyati dahyate ca"},{"type":"verse","number":"15","sanskrit":"स चातुरो मूर्च्छति हि प्रसक्तं पाण्डुः कृशः शुष्यति तृष्णया च दूष्योदरं कीर्त्तितमेतदेव प्लीहोदरं कीर्त्तयता निबोध","text":"sa cāturo mūrcchati hi prasaktaṃ pāṇḍuḥ kṛśaḥ śuṣyati tṛṣṇayā ca dūṣyodaraṃ kīrttitametadeva plīhodaraṃ kīrttayatā nibodha"},{"type":"verse","number":"16","sanskrit":"वर्द्धते प्लीहवृद्ध्या यद्विद्यात्प्लीहोदरं हि तत् हृद्वामे वर्द्धते पार्श्वे निमित्तं तत्र यस्य यत्","text":"varddhate plīhavṛddhyā yadvidyātplīhodaraṃ hi tat hṛdvāme varddhate pārśve nimittaṃ tatra yasya yat"},{"type":"verse","number":"17","sanskrit":"प्रवृद्धे प्लीह्नि लिङ्गानि यान्युक्तानि भिषग्वरैः प्लीहोदरेपि दृश्यन्ते तानि सर्वाणि देहिनाम् प्लीहोदरस्यैव मेदो यकृद्दाल्युदरं तथा","text":"pravṛddhe plīhni liṅgāni yānyuktāni bhiṣagvaraiḥ plīhodarepi dṛśyante tāni sarvāṇi dehinām plīhodarasyaiva medo yakṛddālyudaraṃ tathā"},{"type":"verse","number":"18","sanskrit":"सव्यान्यपार्श्वे यकृति प्रवृद्धे ज्ञेयं यकृद्दाल्युदरं तदेव","text":"savyānyapārśve yakṛti pravṛddhe jñeyaṃ yakṛddālyudaraṃ tadeva"},{"type":"verse","number":"19","sanskrit":"यस्यान्त्रमन्नैरुपलेपिभिर्वा बालश्मभिर्वा पिहितं यथावत् सञ्चीयते यस्य मलो नरस्य शनैः शनैः सङ्करवच्च नाड्याम्","text":"yasyāntramannairupalepibhirvā bālaśmabhirvā pihitaṃ yathāvat sañcīyate yasya malo narasya śanaiḥ śanaiḥ saṅkaravacca nāḍyām"},{"type":"verse","number":"20","sanskrit":"निरुध्यते तस्य गुदे पुरीषं निरेति कृच्छ्रादतिचाल्पमल्पम् हृन्नाभिमध्ये परिवृद्धिमेति तस्योदरं बद्धगुदं वदन्ति","text":"nirudhyate tasya gude purīṣaṃ nireti kṛcchrādaticālpamalpam hṛnnābhimadhye parivṛddhimeti tasyodaraṃ baddhagudaṃ vadanti"},{"type":"verse","number":"21","sanskrit":"शल्यं तथाऽन्नोपहितं यदन्त्रं भुक्तं भिनत्त्यागतमन्यथा वा तस्मात्स्रुतोऽन्त्रात्सलिलप्रकाशः स्रावः स्रवेद्वै गुदतस्तु भूयः","text":"śalyaṃ tathā'nnopahitaṃ yadantraṃ bhuktaṃ bhinattyāgatamanyathā vā tasmātsruto'ntrātsalilaprakāśaḥ srāvaḥ sravedvai gudatastu bhūyaḥ"},{"type":"verse","number":"22","sanskrit":"नाभेरधश्चोदरमेति वृद्धिं निस्तुद्यते दाल्यति चातिमात्रम् एतत्परिस्राव्युदरं प्रदिष्टं क्षतोदरं कीर्त्तयतो निबोध","text":"nābheradhaścodarameti vṛddhiṃ nistudyate dālyati cātimātram etatparisrāvyudaraṃ pradiṣṭaṃ kṣatodaraṃ kīrttayato nibodha"},{"type":"verse","number":"23","sanskrit":"यः स्नेहपीतोऽप्यनुवासितो वा वान्तो विरिक्तोऽप्यथ वा निरूढः पिबेज्जलं शीतलमाशु तस्य स्रोतांसि दूष्यन्ति हि तद्वहानि","text":"yaḥ snehapīto'pyanuvāsito vā vānto virikto'pyatha vā nirūḍhaḥ pibejjalaṃ śītalamāśu tasya srotāṃsi dūṣyanti hi tadvahāni"},{"type":"verse","number":"24","sanskrit":"स्नेहोपलिप्तेष्वथ वाऽपि तेषु दकोदरं पूर्ववदभ्युपैति स्निग्धं महत्तत्परिवृत्तनाभि समन्ततः पूर्णमिवाम्बुना च यथा दृतिः क्षुभ्यति कम्पते च शब्दायते वाऽप्युदकोदरं तत्","text":"snehopalipteṣvatha vā'pi teṣu dakodaraṃ pūrvavadabhyupaiti snigdhaṃ mahattatparivṛttanābhi samantataḥ pūrṇamivāmbunā ca yathā dṛtiḥ kṣubhyati kampate ca śabdāyate vā'pyudakodaraṃ tat"},{"type":"verse","number":"25","sanskrit":"जन्मनैवोदरं सर्वं प्रायः कृच्छ्रतमं मतम् बलिनस्तदजाताम्बु यत्नसाध्यं नवोत्थितम्","text":"janmanaivodaraṃ sarvaṃ prāyaḥ kṛcchratamaṃ matam balinastadajātāmbu yatnasādhyaṃ navotthitam"},{"type":"verse","number":"26","sanskrit":"पक्षाद् बद्धगुदं तूर्ध्वं सर्वं जातोदकं तथा प्रायो भवत्यभावाय छिद्रा न्त्रं चोदरं नृणाम्","text":"pakṣād baddhagudaṃ tūrdhvaṃ sarvaṃ jātodakaṃ tathā prāyo bhavatyabhāvāya chidrā ntraṃ codaraṃ nṛṇām"},{"type":"verse","number":"27","sanskrit":"पयः पूर्णा दृतिरिव क्षोभे शब्दकरं मृदु अप्रव्यक्तशिराशून्यं नीरार्त्तमुदरं महत्","text":"payaḥ pūrṇā dṛtiriva kṣobhe śabdakaraṃ mṛdu apravyaktaśirāśūnyaṃ nīrārttamudaraṃ mahat"},{"type":"verse","number":"28","sanskrit":"आलस्यमास्यवैरस्यं मूत्रं बहुशकृद् द्रुतम् जातोदकस्य लिङ्गंस्यान्मन्दाग्निः पाण्डुताऽपि च","text":"ālasyamāsyavairasyaṃ mūtraṃ bahuśakṛd drutam jātodakasya liṅgaṃsyānmandāgniḥ pāṇḍutā'pi ca"},{"type":"verse","number":"29","sanskrit":"शूनाक्षं कुटिलोपस्थमुपक्लिन्नतनुत्वचम् बलशोणितमांसाग्निपरिक्षीणञ्च वर्जयेत्","text":"śūnākṣaṃ kuṭilopasthamupaklinnatanutvacam balaśoṇitamāṃsāgniparikṣīṇañca varjayet"},{"type":"verse","number":"30","sanskrit":"पार्श्वभङ्गान्नविद्वेष शोफातीसारपीडितम् विरिक्तं चाप्युदरिणं पूर्यमाणं विवर्जयेत्","text":"pārśvabhaṅgānnavidveṣa śophātīsārapīḍitam viriktaṃ cāpyudariṇaṃ pūryamāṇaṃ vivarjayet"},{"type":"verse","number":"31","sanskrit":"एरण्डतैलं दशमूलमिश्रं गोमूत्रयुक्तस्त्रिफलारसो वा निहन्ति वातोदरशोथशूलं क्वाथः समूत्रो दशमूलजश्च","text":"eraṇḍatailaṃ daśamūlamiśraṃ gomūtrayuktastriphalāraso vā nihanti vātodaraśothaśūlaṃ kvāthaḥ samūtro daśamūlajaśca"},{"type":"verse","number":"32","sanskrit":"कुष्ठं दन्ती यवक्षारो व्योषं त्रिलवणं वचा","text":"kuṣṭhaṃ dantī yavakṣāro vyoṣaṃ trilavaṇaṃ vacā"},{"type":"verse","number":"33","sanskrit":"अजाजी दीप्यकं हिङ्गु स्वर्जिकाचव्यचित्रकम् शुण्ठी चोष्णाम्भसा पीता वातोदररुजाऽपहा","text":"ajājī dīpyakaṃ hiṅgu svarjikācavyacitrakam śuṇṭhī coṣṇāmbhasā pītā vātodararujā'pahā"},{"type":"verse","number":"34","sanskrit":"लशुनस्य तुलामेकां जलद्रो णे विपाचयेत् त्रिकुटु त्रिफला दन्ती हिङ्गुसैन्धवचित्रकम्","text":"laśunasya tulāmekāṃ jaladro ṇe vipācayet trikuṭu triphalā dantī hiṅgusaindhavacitrakam"},{"type":"verse","number":"35","sanskrit":"देवदारु वचा कुष्ठं मधु शिग्रुः पुनर्नवा सौवर्चलं विडङ्गानि दीप्यको गजपिप्पली","text":"devadāru vacā kuṣṭhaṃ madhu śigruḥ punarnavā sauvarcalaṃ viḍaṅgāni dīpyako gajapippalī"},{"type":"verse","number":"36","sanskrit":"एतेषां पलिकान्भागांस्त्रिवृतः षट् पलानि च पिष्ट्वा कषायेणानेन तैलं मृद्वग्निना पचेत्","text":"eteṣāṃ palikānbhāgāṃstrivṛtaḥ ṣaṭ palāni ca piṣṭvā kaṣāyeṇānena tailaṃ mṛdvagninā pacet"},{"type":"verse","number":"37","sanskrit":"तत्पिबेत्प्रातरुत्थाय यथाऽग्निबलमात्रया निहन्ति सकलान् रोगानुदराणि विशेषतः","text":"tatpibetprātarutthāya yathā'gnibalamātrayā nihanti sakalān rogānudarāṇi viśeṣataḥ"},{"type":"verse","number":"38","sanskrit":"मूत्रकृच्छ्रमुदावर्त्तमन्त्रवृद्धिं गुदकृमीन् पार्श्वकुक्षिभवं शूलमामशूलमरोचकम्","text":"mūtrakṛcchramudāvarttamantravṛddhiṃ gudakṛmīn pārśvakukṣibhavaṃ śūlamāmaśūlamarocakam"},{"type":"verse","number":"39","sanskrit":"यकृदष्ठीलिकानाहान्प्लीहानं चाङ्गवेदनाम् मासमात्रेण नश्यन्ति ह्यशीतिर्वातजा गदाः","text":"yakṛdaṣṭhīlikānāhānplīhānaṃ cāṅgavedanām māsamātreṇa naśyanti hyaśītirvātajā gadāḥ"},{"type":"verse","number":"40","sanskrit":"पित्तोदरे तु बलिनं पूर्वमेहं विरेचयेत् पयसा च त्रिवृत्कल्कै रुबूकस्य शृतेन च","text":"pittodare tu balinaṃ pūrvamehaṃ virecayet payasā ca trivṛtkalkai rubūkasya śṛtena ca"},{"type":"verse","number":"41","sanskrit":"पिप्पल्यादिगणेनाज्यं पाचितं पाययेद्भिषक् नरं पथ्यभुजं नित्यं कफोदरनिवृत्तये","text":"pippalyādigaṇenājyaṃ pācitaṃ pāyayedbhiṣak naraṃ pathyabhujaṃ nityaṃ kaphodaranivṛttaye"},{"type":"verse","number":"42","sanskrit":"नागरत्रिफलाकल्कै र्दध्यम्बुपरिपेषितैः पाचितं तैलमाज्यं वा पिबेत्सर्वोदरेषु च","text":"nāgaratriphalākalkai rdadhyambuparipeṣitaiḥ pācitaṃ tailamājyaṃ vā pibetsarvodareṣu ca"},{"type":"verse","number":"43","sanskrit":"शालिषष्टिक गोधूमयवनीवारभोजनम् निरूहो रेचनं श्रेष्ठं सर्वेषु जठरेषु च","text":"śāliṣaṣṭika godhūmayavanīvārabhojanam nirūho recanaṃ śreṣṭhaṃ sarveṣu jaṭhareṣu ca"},{"type":"verse","number":"44","sanskrit":"आनूपमौदकं मांसं शाकं पिष्टकृतं तिलाः व्यायामाध्वदिवास्वप्नस्नेहपानानि वर्जयेत्","text":"ānūpamaudakaṃ māṃsaṃ śākaṃ piṣṭakṛtaṃ tilāḥ vyāyāmādhvadivāsvapnasnehapānāni varjayet"},{"type":"verse","number":"45","sanskrit":"तथोग्रलवणोष्णानि विदाहीनि गुरूणि च नाद्यादन्नानि जठरे तोयपानञ्च वर्जयेत्","text":"tathogralavaṇoṣṇāni vidāhīni gurūṇi ca nādyādannāni jaṭhare toyapānañca varjayet"},{"type":"verse","number":"46","sanskrit":"उदराणां मलाढ्यत्वाद् बहुशः शोधनं हितम् क्षीरमेरण्डजं तैलं पिबेन्मूत्रेण वाऽसकृत्","text":"udarāṇāṃ malāḍhyatvād bahuśaḥ śodhanaṃ hitam kṣīrameraṇḍajaṃ tailaṃ pibenmūtreṇa vā'sakṛt"},{"type":"verse","number":"47","sanskrit":"वातोदरी पिबेत्तक्रं पिप्पलीलवणान्वितम् शर्करामरिचोपेतं स्वादु पित्तोदरी पिबेत्","text":"vātodarī pibettakraṃ pippalīlavaṇānvitam śarkarāmaricopetaṃ svādu pittodarī pibet"},{"type":"verse","number":"48","sanskrit":"यवानीहपुषाऽजाजीव्योषयुक्तं कफोदरी सन्निपातोदरी युक्तं त्रिकटुक्षारसैन्धवैः","text":"yavānīhapuṣā'jājīvyoṣayuktaṃ kaphodarī sannipātodarī yuktaṃ trikaṭukṣārasaindhavaiḥ"},{"type":"verse","number":"49","sanskrit":"यवानी हपुषा धान्यं त्रिफला चोपकुञ्चिका कारवी पिप्पलीमूलमजगन्धा शटी वचा","text":"yavānī hapuṣā dhānyaṃ triphalā copakuñcikā kāravī pippalīmūlamajagandhā śaṭī vacā"},{"type":"verse","number":"50","sanskrit":"शताह्वा जीरकं व्योषं स्वर्णक्षीरी च चित्रकम् द्वौ क्षारौ पौष्करं मूलं कुष्ठं लवणपञ्चकम्","text":"śatāhvā jīrakaṃ vyoṣaṃ svarṇakṣīrī ca citrakam dvau kṣārau pauṣkaraṃ mūlaṃ kuṣṭhaṃ lavaṇapañcakam"},{"type":"verse","number":"51","sanskrit":"विडङ्गश्च समांशानि दन्त्या भागत्रयं भवेत् त्रिवृद्विशाला द्विगुणा शातला स्याच्चतुर्गुणा","text":"viḍaṅgaśca samāṃśāni dantyā bhāgatrayaṃ bhavet trivṛdviśālā dviguṇā śātalā syāccaturguṇā"},{"type":"verse","number":"52","sanskrit":"एष नारायणो नाम्ना चूर्णो रोगगणापहः एनं प्राप्य निवर्त्तन्ते रोगा विष्णुमिवासुराः","text":"eṣa nārāyaṇo nāmnā cūrṇo rogagaṇāpahaḥ enaṃ prāpya nivarttante rogā viṣṇumivāsurāḥ"},{"type":"verse","number":"53","sanskrit":"तक्रेणोदरिभिः पेयो गुल्मिभिर्वदराम्बुना आनद्धवाते सुरया वातरोगे प्रसन्नया","text":"takreṇodaribhiḥ peyo gulmibhirvadarāmbunā ānaddhavāte surayā vātaroge prasannayā"},{"type":"verse","number":"54","sanskrit":"दधिमण्डेन विड्भेदे दाडिमाम्बुभिरर्शसि परिकर्त्तिषु वृक्षाम्लैरुष्णाम्बुभिरजीर्णके","text":"dadhimaṇḍena viḍbhede dāḍimāmbubhirarśasi parikarttiṣu vṛkṣāmlairuṣṇāmbubhirajīrṇake"},{"type":"verse","number":"55","sanskrit":"भगन्दरे पाण्डुरोगे कासे श्वासे गलग्रहे हृद्रो गे ग्रहणीरोगे कुब्जे मन्देऽनले ज्वरे","text":"bhagandare pāṇḍuroge kāse śvāse galagrahe hṛdro ge grahaṇīroge kubje mande'nale jvare"},{"type":"verse","number":"56","sanskrit":"दंष्ट्राविषे मूलविषे सगरे कृत्त्रिमे विषे यथाऽह स्निग्धकोष्ठेन पेयमेतद्विरेचनम्","text":"daṃṣṭrāviṣe mūlaviṣe sagare kṛttrime viṣe yathā'ha snigdhakoṣṭhena peyametadvirecanam"},{"type":"verse","number":"57","sanskrit":"स्नुक्क्षीरदन्तीत्रिफलाविडङ्गसिंहीत्रिवृच्चित्रककर्षकर्षम् घृतं विपक्वं कुडवप्रमाणं तोयेन तस्याक्षमथार्द्धकर्षम्","text":"snukkṣīradantītriphalāviḍaṅgasiṃhītrivṛccitrakakarṣakarṣam ghṛtaṃ vipakvaṃ kuḍavapramāṇaṃ toyena tasyākṣamathārddhakarṣam"},{"type":"verse","number":"58","sanskrit":"पीत्वोष्णमम्भोऽनुपिबेद्विरेके पेयां रसं वा प्रपिबेद्विधिज्ञः नाराचमेतज्जठरामयानां युक्त्योपयुक्तं प्रवदन्ति सन्तः","text":"pītvoṣṇamambho'nupibedvireke peyāṃ rasaṃ vā prapibedvidhijñaḥ nārācametajjaṭharāmayānāṃ yuktyopayuktaṃ pravadanti santaḥ"},{"type":"verse","number":"59","sanskrit":"वज्राण्ड्याः कर्षमात्रायाः कल्कं दध्यादिवेष्टितम् निगिलेद्वारिणा नित्यमुदरव्याधिशान्तये","text":"vajrāṇḍyāḥ karṣamātrāyāḥ kalkaṃ dadhyādiveṣṭitam nigiledvāriṇā nityamudaravyādhiśāntaye"},{"type":"verse","number":"60","sanskrit":"पुनर्नवा दारुनिशा सतिक्ता पटोलपथ्यापिचुमन्दमुस्ताः सनागराच्छिन्नरुहेति सर्वैः कृतः कषायो विधिना विधिज्ञैः","text":"punarnavā dāruniśā satiktā paṭolapathyāpicumandamustāḥ sanāgarācchinnaruheti sarvaiḥ kṛtaḥ kaṣāyo vidhinā vidhijñaiḥ"},{"type":"verse","number":"61","sanskrit":"गोमूत्रयुग्गुग्गुलुना च युक्तः पीतः प्रभाते नियतं नराणाम् सर्वाङ्गशोथोदरकासशूलश्वासान्वितं पाण्डुगदं निहन्ति","text":"gomūtrayugguggulunā ca yuktaḥ pītaḥ prabhāte niyataṃ narāṇām sarvāṅgaśothodarakāsaśūlaśvāsānvitaṃ pāṇḍugadaṃ nihanti"},{"type":"verse","number":"62","sanskrit":"इत्येकचत्त्वारिंशत्तम उदरोगाधिकारः समाप्तः ४१","text":"ityekacattvāriṃśattama udarogādhikāraḥ samāptaḥ 41"}]},{"sthana":"Уттаракханда","number":42,"lang":"sa","content":[{"type":"heading","heading":"Шотха — отёки"},{"type":"verse","number":"1","sanskrit":"शुद्ध्य्मायाभक्तकृशाबलानां क्षाराम्लतीक्ष्णोष्णगुरूपसेवा दध्याममृच्छाकविरोधिपिष्टगरोषसृष्टान्ननिषेवणाच्च","text":"śuddhymāyābhaktakṛśābalānāṃ kṣārāmlatīkṣṇoṣṇagurūpasevā dadhyāmamṛcchākavirodhipiṣṭagaroṣasṛṣṭānnaniṣevaṇācca"},{"type":"verse","number":"2","sanskrit":"अर्शांस्यचेष्टा वपुषो ह्यशुद्धिर्मर्माभिघाती विषमा प्रसूतिः मिथ्योपचारः प्रतिकर्मणाञ्च निजस्य हेतुः श्वयथोः प्रदिष्टः","text":"arśāṃsyaceṣṭā vapuṣo hyaśuddhirmarmābhighātī viṣamā prasūtiḥ mithyopacāraḥ pratikarmaṇāñca nijasya hetuḥ śvayathoḥ pradiṣṭaḥ"},{"type":"verse","number":"3","sanskrit":"रक्तपित्तकफान्वायुर्दुष्टो दुष्टान्बहिः शिराः नीत्वा रुद्धगतिस्तैर्हि कुर्यात्त्वङ्मांससंश्रयम् उत्सेधं संहतं शोथं तमाहुर्निचयादतः","text":"raktapittakaphānvāyurduṣṭo duṣṭānbahiḥ śirāḥ nītvā ruddhagatistairhi kuryāttvaṅmāṃsasaṃśrayam utsedhaṃ saṃhataṃ śothaṃ tamāhurnicayādataḥ"},{"type":"verse","number":"4","sanskrit":"सगौरवं स्यादनवस्थितत्वं सोत्सेधमूष्माऽथ शिरातनुत्वम् सलोमहर्षञ्च विवर्णतां च सामान्यलिङ्गं श्वयथोः प्रदिष्टम्","text":"sagauravaṃ syādanavasthitatvaṃ sotsedhamūṣmā'tha śirātanutvam salomaharṣañca vivarṇatāṃ ca sāmānyaliṅgaṃ śvayathoḥ pradiṣṭam"},{"type":"verse","number":"5","sanskrit":"चरस्तनुत्वक्परुषोऽरुणोऽसितः प्रसुप्तिहर्षार्त्तियुतोऽनिमित्ततः प्रशाम्यति प्रोन्नमति प्रपीडितो दिवाबली स्याच्छ्वयथुः समीरणात्","text":"carastanutvakparuṣo'ruṇo'sitaḥ prasuptiharṣārttiyuto'nimittataḥ praśāmyati pronnamati prapīḍito divābalī syācchvayathuḥ samīraṇāt"},{"type":"verse","number":"6","sanskrit":"मृदुः सगन्धाऽसितपीतरागवान् भ्रमज्वरस्वेदतृषामदान्वितः यस्तूष्यते स्पर्शरुगक्षिरागवान्स पित्तशोथो भृशदाहपाकवान्","text":"mṛduḥ sagandhā'sitapītarāgavān bhramajvarasvedatṛṣāmadānvitaḥ yastūṣyate sparśarugakṣirāgavānsa pittaśotho bhṛśadāhapākavān"},{"type":"verse","number":"7","sanskrit":"गुरुः स्थिरः पाण्डुररोचकान्वितः प्रसेकनिद्रा वमिवह्निमान्द्यकृत् सकृच्छ्रजन्मप्रशमो निपीडितो नचोन्नमेद्रा त्रिबली कफात्मकः","text":"guruḥ sthiraḥ pāṇḍurarocakānvitaḥ prasekanidrā vamivahnimāndyakṛt sakṛcchrajanmapraśamo nipīḍito naconnamedrā tribalī kaphātmakaḥ"},{"type":"verse","number":"8","sanskrit":"निदानाकृतिसंसर्गाज्ज्ञेयः शोथो द्विदोषजः","text":"nidānākṛtisaṃsargājjñeyaḥ śotho dvidoṣajaḥ"},{"type":"verse","number":"9","sanskrit":"सर्वाकृतिः सन्निपाताच्छोथो व्यामिश्रलक्षणः","text":"sarvākṛtiḥ sannipātācchotho vyāmiśralakṣaṇaḥ"},{"type":"verse","number":"10","sanskrit":"अभिघातेन शस्त्रादिच्छेदभेदक्षतादिभिः हिमानिलोदध्यनिलैर्भल्लातकपिकच्छुजैः","text":"abhighātena śastrādicchedabhedakṣatādibhiḥ himānilodadhyanilairbhallātakapikacchujaiḥ"},{"type":"verse","number":"11","sanskrit":"रसैः शूकैश्च संस्पर्शाच्छ्वयथुः स्याद्विसर्पवान् भृशोष्मा लोहिताभासः प्रायशः पित्तलक्षणः","text":"rasaiḥ śūkaiśca saṃsparśācchvayathuḥ syādvisarpavān bhṛśoṣmā lohitābhāsaḥ prāyaśaḥ pittalakṣaṇaḥ"},{"type":"verse","number":"12","sanskrit":"विषजः सविषप्राणिपरिसर्पणमूत्रणात् दंष्ट्रादन्तनखाघातादविषप्राणिनामपि","text":"viṣajaḥ saviṣaprāṇiparisarpaṇamūtraṇāt daṃṣṭrādantanakhāghātādaviṣaprāṇināmapi"},{"type":"verse","number":"13","sanskrit":"विण्मूत्रशुक्रोपहतमलवद्वस्तुसङ्करात् विषवृक्षानिलस्पर्शाद्गरयोगावचूर्णनात् मृदुश्चलोऽवलम्बी च शीघ्रो दाहरुजाकरः","text":"viṇmūtraśukropahatamalavadvastusaṅkarāt viṣavṛkṣānilasparśādgarayogāvacūrṇanāt mṛduścalo'valambī ca śīghro dāharujākaraḥ"},{"type":"verse","number":"14","sanskrit":"दोषाः श्वयथुमूर्ध्वं हि कुर्वन्त्यामाशये स्थिताः पित्ताशयस्था मध्ये तु वर्चः स्थानगतास्त्वधः कृत्स्नं देहमनुप्राप्य कुर्युः सर्वसरन्तथा","text":"doṣāḥ śvayathumūrdhvaṃ hi kurvantyāmāśaye sthitāḥ pittāśayasthā madhye tu varcaḥ sthānagatāstvadhaḥ kṛtsnaṃ dehamanuprāpya kuryuḥ sarvasarantathā"},{"type":"verse","number":"15","sanskrit":"छर्दिः श्वासोऽरुचिस्तृष्णा ज्वरोऽतीसार एव च सप्तकोऽय सदौर्बल्यः शोथस्यैते उपद्र वाः","text":"chardiḥ śvāso'rucistṛṣṇā jvaro'tīsāra eva ca saptako'ya sadaurbalyaḥ śothasyaite upadra vāḥ"},{"type":"verse","number":"16","sanskrit":"श्वासः पिपासा छर्दिश्च दौर्बल्यं ज्वर एव च यस्य चान्ने रुचिर्नास्ति शोथिनं तं विवर्जयेत्","text":"śvāsaḥ pipāsā chardiśca daurbalyaṃ jvara eva ca yasya cānne rucirnāsti śothinaṃ taṃ vivarjayet"},{"type":"verse","number":"17","sanskrit":"यो मध्यदेशे श्वयथुः कष्टः सर्वाङ्गगश्च यः अर्द्धाङ्गेऽरिष्टभूतः स्याद्यश्चोर्ध्वं परिसर्पति","text":"yo madhyadeśe śvayathuḥ kaṣṭaḥ sarvāṅgagaśca yaḥ arddhāṅge'riṣṭabhūtaḥ syādyaścordhvaṃ parisarpati"},{"type":"verse","number":"18","sanskrit":"अनन्योपद्र वकृतः शोथः पादसमुत्थितः पुरुषं हन्ति नारीन्तु मुखजो बस्तिजो द्वयम्","text":"ananyopadra vakṛtaḥ śothaḥ pādasamutthitaḥ puruṣaṃ hanti nārīntu mukhajo bastijo dvayam"},{"type":"verse","number":"19","sanskrit":"शुण्ठीपुनर्नवैरण्डपञ्चमूलीशृतं जलम् वातिके श्वयथौ शस्तं पानाहारपरिग्रहे","text":"śuṇṭhīpunarnavairaṇḍapañcamūlīśṛtaṃ jalam vātike śvayathau śastaṃ pānāhāraparigrahe"},{"type":"verse","number":"20","sanskrit":"पटोलत्रिफलाऽरिष्टदार्वीक्वाथः सगुग्गुलुः तद्वत्पित्तकृतं शोथं हन्ति श्लेष्मोद्भवं तथा","text":"paṭolatriphalā'riṣṭadārvīkvāthaḥ sagugguluḥ tadvatpittakṛtaṃ śothaṃ hanti śleṣmodbhavaṃ tathā"},{"type":"verse","number":"21","sanskrit":"मिश्रे मिश्रक्रमं कुर्यात्सर्वजे सर्वमेव हि बिल्वपत्ररसं पूतं सोषणं त्रिभवे पिबेत्","text":"miśre miśrakramaṃ kuryātsarvaje sarvameva hi bilvapatrarasaṃ pūtaṃ soṣaṇaṃ tribhave pibet"},{"type":"verse","number":"22","sanskrit":"शोथे त्वागन्तुजे कुर्यात्सेकलेपादि शीतलम् भल्लातक्या हरेच्छोथं सतिला कृष्णमृत्तिका","text":"śothe tvāgantuje kuryātsekalepādi śītalam bhallātakyā harecchothaṃ satilā kṛṣṇamṛttikā"},{"type":"verse","number":"23","sanskrit":"महिषीक्षीरसंपिष्टैर्नवनीतसमन्वितैः तिलैर्लिप्तः शमं याति शोथो भल्लातकोत्थितः","text":"mahiṣīkṣīrasaṃpiṣṭairnavanītasamanvitaiḥ tilairliptaḥ śamaṃ yāti śotho bhallātakotthitaḥ"},{"type":"verse","number":"24","sanskrit":"यष्टीदुग्धतिलैर्लेपो नवनीतेन संयुतः शोथमारुष्करं हन्ति चूर्णैः शालदलस्य च","text":"yaṣṭīdugdhatilairlepo navanītena saṃyutaḥ śothamāruṣkaraṃ hanti cūrṇaiḥ śāladalasya ca"},{"type":"verse","number":"25","sanskrit":"महिष्या नवनीतं वा लेपाद् दुग्धतिलान्वितम्","text":"mahiṣyā navanītaṃ vā lepād dugdhatilānvitam"},{"type":"verse","number":"26","sanskrit":"पथ्यानिशाभार्ग्यमृताऽग्निदार्वीपुनर्नवादारुमहौषधानाम् क्वाथः प्रसह्योदरपाणिपादमुखाश्रितं हन्त्यचिरेण शोथम्","text":"pathyāniśābhārgyamṛtā'gnidārvīpunarnavādārumahauṣadhānām kvāthaḥ prasahyodarapāṇipādamukhāśritaṃ hantyacireṇa śotham"},{"type":"verse","number":"27","sanskrit":"फलत्रिकोद्भवं क्वाथं गोमूत्रेणैव साधितम् वातश्लेष्मोद्भवं शोथं हन्याद् वृषणसम्भवम्","text":"phalatrikodbhavaṃ kvāthaṃ gomūtreṇaiva sādhitam vātaśleṣmodbhavaṃ śothaṃ hanyād vṛṣaṇasambhavam"},{"type":"verse","number":"28","sanskrit":"बृश्चीरदेवद्रुमनागरैर्वा दन्तीत्रिवृत्त्र् यूषणचित्रकैर्वा दुग्धं सुसिद्धं विधिना निपीतं गीतं परं शोथहरं भिषग्भिः","text":"bṛścīradevadrumanāgarairvā dantītrivṛttr yūṣaṇacitrakairvā dugdhaṃ susiddhaṃ vidhinā nipītaṃ gītaṃ paraṃ śothaharaṃ bhiṣagbhiḥ"},{"type":"verse","number":"29","sanskrit":"सेकस्तथार्कवर्षाभूनिम्बक्वाथेन शोथहृत् गोमूत्रेणापि कुर्वीत सुखोष्णेनावसेचनम्","text":"sekastathārkavarṣābhūnimbakvāthena śothahṛt gomūtreṇāpi kurvīta sukhoṣṇenāvasecanam"},{"type":"verse","number":"30","sanskrit":"पुनर्नवा दारु शुण्ठी शिग्रुः सिद्धार्थकस्तथा अम्लपिष्टः सुखोष्णोऽय प्रलेपः सर्वशोथहृत्","text":"punarnavā dāru śuṇṭhī śigruḥ siddhārthakastathā amlapiṣṭaḥ sukhoṣṇo'ya pralepaḥ sarvaśothahṛt"},{"type":"verse","number":"31","sanskrit":"गुडार्द्र कं वा गुडनागरं वा गुडाभयां वा गुडपिप्पलद्यं वा कर्षाभिवृद्ध्या त्रिपलप्रमाणं खादेन्नरः पक्षमथापि मासम्","text":"guḍārdra kaṃ vā guḍanāgaraṃ vā guḍābhayāṃ vā guḍapippaladyaṃ vā karṣābhivṛddhyā tripalapramāṇaṃ khādennaraḥ pakṣamathāpi māsam"},{"type":"verse","number":"32","sanskrit":"शोथप्रतिश्यायगलास्यरोगान्सश्वासकासारुचिपीनसादीन् जीर्णज्वरार्शोग्रहणीविकारान्हन्यात्तथान्यान्कफवातरोगान्","text":"śothapratiśyāyagalāsyarogānsaśvāsakāsārucipīnasādīn jīrṇajvarārśograhaṇīvikārānhanyāttathānyānkaphavātarogān"},{"type":"verse","number":"33","sanskrit":"विश्वं गुडेन तुल्यं बृश्चीररसानुपानमभ्यस्तम् विनिहन्ति सर्वशोथं घनवृन्दं चण्डवायुरिव","text":"viśvaṃ guḍena tulyaṃ bṛścīrarasānupānamabhyastam vinihanti sarvaśothaṃ ghanavṛndaṃ caṇḍavāyuriva"},{"type":"verse","number":"34","sanskrit":"कणानागरजं चूर्णं सगुडं शोथनाशनम् आमाजीर्णप्रशमनं शूलघ्नं बस्तिशोधनम्","text":"kaṇānāgarajaṃ cūrṇaṃ saguḍaṃ śothanāśanam āmājīrṇapraśamanaṃ śūlaghnaṃ bastiśodhanam"},{"type":"verse","number":"35","sanskrit":"गुडात्पलत्रयं ग्राह्यं शृङ्गबेरपलत्रयम् शृङ्गबेरसमा कृष्णा लोहविट्तिलयोः पलम् चूर्णमेतत्समुद्दिष्टं सर्वश्वयथुनाशनम्","text":"guḍātpalatrayaṃ grāhyaṃ śṛṅgaberapalatrayam śṛṅgaberasamā kṛṣṇā lohaviṭtilayoḥ palam cūrṇametatsamuddiṣṭaṃ sarvaśvayathunāśanam"},{"type":"verse","number":"36","sanskrit":"माणकक्वाथकल्काभ्यां घृतप्रस्थं विपाचयेत् एकजं द्वन्द्वजं शोथं त्रिदोषञ्च व्यपोहति","text":"māṇakakvāthakalkābhyāṃ ghṛtaprasthaṃ vipācayet ekajaṃ dvandvajaṃ śothaṃ tridoṣañca vyapohati"},{"type":"verse","number":"37","sanskrit":"शुष्कमूलकवर्षा भूदारुरास्नामहौषधैः पक्वमभ्यञ्जनं तैलं सशूलं श्वयथुं हरेत्","text":"śuṣkamūlakavarṣā bhūdārurāsnāmahauṣadhaiḥ pakvamabhyañjanaṃ tailaṃ saśūlaṃ śvayathuṃ haret"},{"type":"verse","number":"38","sanskrit":"इति द्विचत्वारिंशत्तमः शोथाधिकारः समाप्तः ४२","text":"iti dvicatvāriṃśattamaḥ śothādhikāraḥ samāptaḥ 42"}]},{"sthana":"Уттаракханда","number":43,"lang":"sa","content":[{"type":"heading","heading":"Вриддхи — грыжа"},{"type":"verse","number":"1","sanskrit":"दोषास्रमेदोमूत्रान्त्रैः स वृद्धिः सप्तधा गदः मूत्रान्त्रजावप्यनिलाद्धेतुभेदस्तु केवलः","text":"doṣāsramedomūtrāntraiḥ sa vṛddhiḥ saptadhā gadaḥ mūtrāntrajāvapyanilāddhetubhedastu kevalaḥ"},{"type":"verse","number":"2","sanskrit":"वृद्धिं करोति कोषस्यफलकोषाभिवाहिनीः रुद्ध्वा रुद्धगतिर्वायुर्धमनीर्मुष्कगामिनीः","text":"vṛddhiṃ karoti koṣasyaphalakoṣābhivāhinīḥ ruddhvā ruddhagatirvāyurdhamanīrmuṣkagāminīḥ"},{"type":"verse","number":"3","sanskrit":"वातपूर्णदृतिस्पर्शो रुक्षो वातादहेतुरुक्","text":"vātapūrṇadṛtisparśo rukṣo vātādaheturuk"},{"type":"verse","number":"4","sanskrit":"पक्वोदुम्बरसङ्काशःपित्ताद् दाहोष्मपाकवान्","text":"pakvodumbarasaṅkāśaḥpittād dāhoṣmapākavān"},{"type":"verse","number":"5","sanskrit":"कफाच्छीतो गुरुः स्निग्धः कण्डूमान्कठिनोऽल्परुक्","text":"kaphācchīto guruḥ snigdhaḥ kaṇḍūmānkaṭhino'lparuk"},{"type":"verse","number":"6","sanskrit":"कृष्णस्फोटावृतः पित्तवृद्धिलिङ्गश्च रक्तजः","text":"kṛṣṇasphoṭāvṛtaḥ pittavṛddhiliṅgaśca raktajaḥ"},{"type":"verse","number":"7","sanskrit":"कफवन्मेदसो वृद्धिर्मृदुस्तालफलोपमः","text":"kaphavanmedaso vṛddhirmṛdustālaphalopamaḥ"},{"type":"verse","number":"8","sanskrit":"मूत्रधारणशीलस्य मूत्रजः स तु गच्छतः अम्भोभिः पूर्णदृतिवत्क्षोभं याति सरुङ् मृदुः मूत्रकृच्छ्रमधः कुर्यात्सञ्चलं फलकोषयोः","text":"mūtradhāraṇaśīlasya mūtrajaḥ sa tu gacchataḥ ambhobhiḥ pūrṇadṛtivatkṣobhaṃ yāti saruṅ mṛduḥ mūtrakṛcchramadhaḥ kuryātsañcalaṃ phalakoṣayoḥ"},{"type":"verse","number":"9","sanskrit":"वातकोपिभिराहारैः शीततोयावगाहनैः धारणेरणभाराध्व विषमाङ्गप्रवर्त्तनैः क्षोभणैः क्षोभितोऽन्यैश्च क्षुद्रा न्त्रावयवं यदा पवनो विगुणीकृत्य स्वनिवेशादधो नयेत् कुर्याद्वङ्क्षणसन्धिस्थो ग्रन्थ्याभं श्वयथुं तदा","text":"vātakopibhirāhāraiḥ śītatoyāvagāhanaiḥ dhāraṇeraṇabhārādhva viṣamāṅgapravarttanaiḥ kṣobhaṇaiḥ kṣobhito'nyaiśca kṣudrā ntrāvayavaṃ yadā pavano viguṇīkṛtya svaniveśādadho nayet kuryādvaṅkṣaṇasandhistho granthyābhaṃ śvayathuṃ tadā"},{"type":"verse","number":"10","sanskrit":"उपेक्ष्यमाणस्य च मुष्कवृद्धिमाध्मानरुक्स्तम्भवतीं स वायुः प्रपीडितोऽन्त स्वनवान्प्रयाति प्रध्मापयन्नेति पुनश्च मुक्तः","text":"upekṣyamāṇasya ca muṣkavṛddhimādhmānarukstambhavatīṃ sa vāyuḥ prapīḍito'nta svanavānprayāti pradhmāpayanneti punaśca muktaḥ"},{"type":"verse","number":"11","sanskrit":"यस्यान्त्रावयवाश्लेषो मुष्कयोर्वातसञ्चयात् अन्त्रवृद्धिरसाध्योऽय वातवृद्धिसमाकृतिः","text":"yasyāntrāvayavāśleṣo muṣkayorvātasañcayāt antravṛddhirasādhyo'ya vātavṛddhisamākṛtiḥ"},{"type":"verse","number":"12","sanskrit":"अत्यभिष्यन्दिगुर्वन्न शुष्कपूत्यामिषाशनात् करोति ग्रन्थिवच्छोथं दोषो वङ्क्षणसन्धिषु ज्वरशूलाङ्गसादाढ्यं तं ब्रध्नेति विनिर्दिशेत्","text":"atyabhiṣyandigurvanna śuṣkapūtyāmiṣāśanāt karoti granthivacchothaṃ doṣo vaṅkṣaṇasandhiṣu jvaraśūlāṅgasādāḍhyaṃ taṃ bradhneti vinirdiśet"},{"type":"verse","number":"13","sanskrit":"वृद्धावत्यशनं मार्गमुपवासं गुरूणि च वेगाघातं पृष्ठयानं व्यायामं मैथुनं त्यजेत्","text":"vṛddhāvatyaśanaṃ mārgamupavāsaṃ gurūṇi ca vegāghātaṃ pṛṣṭhayānaṃ vyāyāmaṃ maithunaṃ tyajet"},{"type":"verse","number":"14","sanskrit":"वातवृद्धौ पिबेत् स्निग्धं यथाप्राप्तं विरेचनम् सक्षीरञ्च पिबेत्तैलं मासमेरण्डसम्भवम्","text":"vātavṛddhau pibet snigdhaṃ yathāprāptaṃ virecanam sakṣīrañca pibettailaṃ māsameraṇḍasambhavam"},{"type":"verse","number":"15","sanskrit":"गुग्गुल्वेरण्डजं तैलं गोमूत्रेण पिबेन्नरः वातवृद्धिं जयत्याशु चिरकालानुबन्धिनीम्","text":"guggulveraṇḍajaṃ tailaṃ gomūtreṇa pibennaraḥ vātavṛddhiṃ jayatyāśu cirakālānubandhinīm"},{"type":"verse","number":"16","sanskrit":"पित्तग्रन्थिक्रमेणैव पित्तवृद्धिमुपाचरेत् जलौकाभिर्हरेद्र क्तं वृद्धौ पित्तसमुद्भवे","text":"pittagranthikrameṇaiva pittavṛddhimupācaret jalaukābhirharedra ktaṃ vṛddhau pittasamudbhave"},{"type":"verse","number":"17","sanskrit":"चन्दनं मधुकं पद्ममुशीरं नीलमुत्पलम् क्षीरपिष्टं प्रलेपेन दाहशोथरुजाऽपहम्","text":"candanaṃ madhukaṃ padmamuśīraṃ nīlamutpalam kṣīrapiṣṭaṃ pralepena dāhaśotharujā'paham"},{"type":"verse","number":"18","sanskrit":"त्रिकटुत्रिफलाक्वाथं सक्षारलवणं पिबेत् विरेचनमिदं श्रेष्ठं कफवृद्धिविनाशनम्","text":"trikaṭutriphalākvāthaṃ sakṣāralavaṇaṃ pibet virecanamidaṃ śreṣṭhaṃ kaphavṛddhivināśanam"},{"type":"verse","number":"19","sanskrit":"लेपनाः कटुतीक्ष्णोष्णाः स्वेदनं रूक्षमेव च परिषेकोपनाहौ च सर्वमुष्णमिहेष्यते","text":"lepanāḥ kaṭutīkṣṇoṣṇāḥ svedanaṃ rūkṣameva ca pariṣekopanāhau ca sarvamuṣṇamiheṣyate"},{"type":"verse","number":"20","sanskrit":"मुहुर्मुहुर्जलौकाभिः शोणितं रक्तजे हरेत् पिबेद्विरेचनं वाऽपि शर्कराक्षौद्र संयुतम्","text":"muhurmuhurjalaukābhiḥ śoṇitaṃ raktaje haret pibedvirecanaṃ vā'pi śarkarākṣaudra saṃyutam"},{"type":"verse","number":"21","sanskrit":"शीतमालेपनं शस्तं सर्वपित्तहरं तथा पित्तवृद्धिक्रमं कुर्यादामे पक्वे च रक्तजे","text":"śītamālepanaṃ śastaṃ sarvapittaharaṃ tathā pittavṛddhikramaṃ kuryādāme pakve ca raktaje"},{"type":"verse","number":"22","sanskrit":"स्विन्नं मेदः समुत्थन्तु लेपयेत्सुरसाऽदिना शिरोविरेचनद्र व्यैः सुखोष्णैर्मूत्रसंयुतैः","text":"svinnaṃ medaḥ samutthantu lepayetsurasā'dinā śirovirecanadra vyaiḥ sukhoṣṇairmūtrasaṃyutaiḥ"},{"type":"verse","number":"23","sanskrit":"संस्वेद्य मूत्रप्रभवं वस्त्रपटटेन वेष्टयेत् सीवन्याः पार्श्वतोऽधस्ताद्विध्येद् ब्रीहिमुखेन वै","text":"saṃsvedya mūtraprabhavaṃ vastrapaṭaṭena veṣṭayet sīvanyāḥ pārśvato'dhastādvidhyed brīhimukhena vai"},{"type":"verse","number":"24","sanskrit":"मुष्ककोषमगच्छन्त्या मन्त्रवृद्धौ विचक्षणः वातवृद्धिक्रमं कुर्यात्स्वेदं तत्राग्निना हितम्","text":"muṣkakoṣamagacchantyā mantravṛddhau vicakṣaṇaḥ vātavṛddhikramaṃ kuryātsvedaṃ tatrāgninā hitam"},{"type":"verse","number":"25","sanskrit":"तैलमेरण्डजं पीत्वा बलासिद्धं यथोचितम् आध्मानशूलोपचितामन्त्रवृद्धिं जयन्नेरः","text":"tailameraṇḍajaṃ pītvā balāsiddhaṃ yathocitam ādhmānaśūlopacitāmantravṛddhiṃ jayanneraḥ"},{"type":"verse","number":"26","sanskrit":"रास्नायष्ट्यमृतैरण्डबलाऽरग्वधगोक्षुरैः पटोलेन वृषेणापि विधिना विहितं शृतम् रुवुतैलेन संयुक्तमन्त्रवृद्धिं व्यपोहति","text":"rāsnāyaṣṭyamṛtairaṇḍabalā'ragvadhagokṣuraiḥ paṭolena vṛṣeṇāpi vidhinā vihitaṃ śṛtam ruvutailena saṃyuktamantravṛddhiṃ vyapohati"},{"type":"verse","number":"27","sanskrit":"गन्धर्वहस्त तैलेन क्षीरेण विहितं शृतम् विशालामूलजं चूर्णं वृद्धिं हन्ति न संशयः","text":"gandharvahasta tailena kṣīreṇa vihitaṃ śṛtam viśālāmūlajaṃ cūrṇaṃ vṛddhiṃ hanti na saṃśayaḥ"},{"type":"verse","number":"28","sanskrit":"वचासर्षपकल्केन प्रलेपः शोथनाशनः शिग्रुत्वक्सर्षपैर्लेपः शोथश्लेष्मानिलापहः","text":"vacāsarṣapakalkena pralepaḥ śothanāśanaḥ śigrutvaksarṣapairlepaḥ śothaśleṣmānilāpahaḥ"},{"type":"verse","number":"29","sanskrit":"शुद्धसूतं तथा गन्धं मृतान्येतानियोजयेत् लोहं वङ्गं तथा ताम्रं कांस्यञ्चाथ विशोधितम्","text":"śuddhasūtaṃ tathā gandhaṃ mṛtānyetāniyojayet lohaṃ vaṅgaṃ tathā tāmraṃ kāṃsyañcātha viśodhitam"},{"type":"verse","number":"30","sanskrit":"तालकं तुत्थकञ्चापि तथा शङ्खवराटकम् त्रिकटु त्रिफलां चव्यं विडङ्गं वृद्धदारकम्","text":"tālakaṃ tutthakañcāpi tathā śaṅkhavarāṭakam trikaṭu triphalāṃ cavyaṃ viḍaṅgaṃ vṛddhadārakam"},{"type":"verse","number":"31","sanskrit":"कर्चूरं मागधीमूलं पाठां सहवुषां वचाम् एलाबीजं देवकाष्ठं तथा लवणपञ्चकम्","text":"karcūraṃ māgadhīmūlaṃ pāṭhāṃ sahavuṣāṃ vacām elābījaṃ devakāṣṭhaṃ tathā lavaṇapañcakam"},{"type":"verse","number":"32","sanskrit":"एतानि समभागानि चूर्णयेदथ कारयेत् कषायेण हरीतक्या वटिकां टङ्कसम्मिताम्","text":"etāni samabhāgāni cūrṇayedatha kārayet kaṣāyeṇa harītakyā vaṭikāṃ ṭaṅkasammitām"},{"type":"verse","number":"33","sanskrit":"एकां तां वटिकां यस्तु निगिलेद्वारिणा सह अण्डवृद्धिरसाध्याऽपि तथ्यं नश्यति सत्वरम्","text":"ekāṃ tāṃ vaṭikāṃ yastu nigiledvāriṇā saha aṇḍavṛddhirasādhyā'pi tathyaṃ naśyati satvaram"},{"type":"verse","number":"34","sanskrit":"भृष्टश्चैरण्डतैलेन सम्यक्कल्कोऽभयाभवः कृष्णासैन्धवसंयुक्तो ब्रध्नरोगहरः परः","text":"bhṛṣṭaścairaṇḍatailena samyakkalko'bhayābhavaḥ kṛṣṇāsaindhavasaṃyukto bradhnarogaharaḥ paraḥ"},{"type":"verse","number":"35","sanskrit":"अजाजी हवुषा कुष्ठं गोमेदं बदरान्वितम् काञ्जिकेन तु सम्पिष्टं तल्लेपो ब्रध्नजित्परः","text":"ajājī havuṣā kuṣṭhaṃ gomedaṃ badarānvitam kāñjikena tu sampiṣṭaṃ tallepo bradhnajitparaḥ"},{"type":"verse","number":"36","sanskrit":"इति त्रिचत्वारिंशत्तमो वृद्धिब्रध्नाधिकारः समाप्तः ४३","text":"iti tricatvāriṃśattamo vṛddhibradhnādhikāraḥ samāptaḥ 43"}]},{"sthana":"Уттаракханда","number":44,"lang":"sa","content":[{"type":"heading","heading":"Галаганда — зоб и опухоли"},{"type":"verse","number":"1","sanskrit":"निबद्धः श्वयथुर्यस्य मुष्कवल्लम्बते गले महान्वा यदिवा ह्रस्वो गलगण्डं तमादिशेत्","text":"nibaddhaḥ śvayathuryasya muṣkavallambate gale mahānvā yadivā hrasvo galagaṇḍaṃ tamādiśet"},{"type":"verse","number":"2","sanskrit":"वातः कफश्चापि गले प्रदुष्टौ मन्ये तु संश्रित्य तथैव मेदः कुर्वन्ति गण्डं क्रमतः स्वलिङ्गैः समाचितं तं गलगण्डमाहुः","text":"vātaḥ kaphaścāpi gale praduṣṭau manye tu saṃśritya tathaiva medaḥ kurvanti gaṇḍaṃ kramataḥ svaliṅgaiḥ samācitaṃ taṃ galagaṇḍamāhuḥ"},{"type":"verse","number":"3","sanskrit":"तोदान्वितः कृष्णशिराऽवनद्धः श्यावारुणो वा पवनात्मकस्तु पारुष्ययुक्तश्चिरवृद्ध्य्पाको यदृच्छया पाकमियात्कदाचित् वैरस्यमास्यस्य च तस्य जन्तोर्भवेत्तथा तालुगलप्रशोषः","text":"todānvitaḥ kṛṣṇaśirā'vanaddhaḥ śyāvāruṇo vā pavanātmakastu pāruṣyayuktaściravṛddhypāko yadṛcchayā pākamiyātkadācit vairasyamāsyasya ca tasya jantorbhavettathā tālugalapraśoṣaḥ"},{"type":"verse","number":"4","sanskrit":"स्थिरः सवर्णो गुरुरुग्रकण्डूः शीतो महांश्चापि कफात्मकस्तु चिराच्च वृद्धिं भजते चिराद्वा प्रपच्यते मन्दरुजः कदाचित्","text":"sthiraḥ savarṇo gururugrakaṇḍūḥ śīto mahāṃścāpi kaphātmakastu cirācca vṛddhiṃ bhajate cirādvā prapacyate mandarujaḥ kadācit"},{"type":"verse","number":"5","sanskrit":"माधुर्यमास्यस्य च तस्य जन्तोर्भवेत्तथा तालुगलप्रलेपः","text":"mādhuryamāsyasya ca tasya jantorbhavettathā tālugalapralepaḥ"},{"type":"verse","number":"6","sanskrit":"स्निग्धो मृदुः पाण्डुरनिष्टगन्धो मेदोऽन्वितः कण्डुयुतोऽरुजश्च प्रलम्बतेऽलाबुवदल्पमूलो देहानुरूपक्षयवृद्धियुक्तः स्निग्धास्यता तस्य भवेच्च जन्तोर्गलेऽणुशब्दं कुरुते च नित्यम्","text":"snigdho mṛduḥ pāṇḍuraniṣṭagandho medo'nvitaḥ kaṇḍuyuto'rujaśca pralambate'lābuvadalpamūlo dehānurūpakṣayavṛddhiyuktaḥ snigdhāsyatā tasya bhavecca jantorgale'ṇuśabdaṃ kurute ca nityam"},{"type":"verse","number":"7","sanskrit":"कृच्छ्राच्छ्वसन्तं मृदु सर्वगात्रं संवत्सरातीतमरोचकार्त्तम् क्षीणञ्च वैद्यो गलगण्डयुक्तं भिन्नस्वरं नैव नरं चिकित्सेत्","text":"kṛcchrācchvasantaṃ mṛdu sarvagātraṃ saṃvatsarātītamarocakārttam kṣīṇañca vaidyo galagaṇḍayuktaṃ bhinnasvaraṃ naiva naraṃ cikitset"},{"type":"verse","number":"8","sanskrit":"कर्कन्धुकोलामलकप्रमाणैः कक्षांसमन्यागलवङ्क्षणेषु मेदः कफाभ्यां चिरमन्दपाकैः स्याद्गण्डमाला बहुभिश्च गण्डः","text":"karkandhukolāmalakapramāṇaiḥ kakṣāṃsamanyāgalavaṅkṣaṇeṣu medaḥ kaphābhyāṃ ciramandapākaiḥ syādgaṇḍamālā bahubhiśca gaṇḍaḥ"},{"type":"verse","number":"9","sanskrit":"ते ग्रन्थयः केचिदवाप्तपाकाः स्रवन्ति नश्यन्ति भवन्ति चान्ये कालानुबन्धं चिरमादधाति सैवापचीति प्रवदन्ति केचित्","text":"te granthayaḥ kecidavāptapākāḥ sravanti naśyanti bhavanti cānye kālānubandhaṃ ciramādadhāti saivāpacīti pravadanti kecit"},{"type":"verse","number":"10","sanskrit":"साध्या स्मृता पीनसपार्श्वशूलकासज्वरच्छर्दियुता त्वसाध्या","text":"sādhyā smṛtā pīnasapārśvaśūlakāsajvaracchardiyutā tvasādhyā"},{"type":"verse","number":"11","sanskrit":"वातादयो मांसमसृक्प्रदुष्टाः सन्दूष्य मेदश्च तथा सिराश्च वृत्तोन्नतं विग्रथितन्तु शोथं कुर्वन्त्यतो ग्रन्थिरिति प्रदिष्टः","text":"vātādayo māṃsamasṛkpraduṣṭāḥ sandūṣya medaśca tathā sirāśca vṛttonnataṃ vigrathitantu śothaṃ kurvantyato granthiriti pradiṣṭaḥ"},{"type":"verse","number":"12","sanskrit":"आयम्यते वृश्च्यति तुद्यते च प्रभ्रश्यते मथ्यति भिद्यते च कृष्णो मृदुर्वस्तिरिवाततश्च भिन्नः स्रवेच्चानिलजोऽस्रमच्छम्","text":"āyamyate vṛścyati tudyate ca prabhraśyate mathyati bhidyate ca kṛṣṇo mṛdurvastirivātataśca bhinnaḥ sraveccānilajo'sramaccham"},{"type":"verse","number":"13","sanskrit":"दन्दह्मते धूप्यति चूष्यते च पापच्यते प्रज्वलतीव चापि रक्तः सपीतोऽप्यथवाऽपि पित्ताद्भिन्नःस्रवेद् दुष्टमतीव चास्रम्","text":"dandahmate dhūpyati cūṣyate ca pāpacyate prajvalatīva cāpi raktaḥ sapīto'pyathavā'pi pittādbhinnaḥsraved duṣṭamatīva cāsram"},{"type":"verse","number":"14","sanskrit":"शीतोऽविवर्णोऽल्परुजोऽतिकण्डूः पाषाणवत्संहननोपपन्नः चिराभिवृद्धिश्च कफप्रकोपाद्भिन्नः स्रवेच्छुक्लघनञ्च पूयम्","text":"śīto'vivarṇo'lparujo'tikaṇḍūḥ pāṣāṇavatsaṃhananopapannaḥ cirābhivṛddhiśca kaphaprakopādbhinnaḥ sravecchuklaghanañca pūyam"},{"type":"verse","number":"15","sanskrit":"शरीरवृद्धिक्षयवृद्धिहानिः स्निग्धो महान् कण्डुयुतोऽरुजश्च मेदः कृतो गच्छति चात्र भिन्नो पिण्याकसर्पिःप्रतिमन्तु मेदः","text":"śarīravṛddhikṣayavṛddhihāniḥ snigdho mahān kaṇḍuyuto'rujaśca medaḥ kṛto gacchati cātra bhinno piṇyākasarpiḥpratimantu medaḥ"},{"type":"verse","number":"16","sanskrit":"व्यायामजातैरबलस्य तैस्तैराक्षिप्य वायुश्च शिराप्रतानम् सङ्कोच्य सम्पीड्य विशोष्य चापि ग्रन्थिं करोत्युन्नतमाशु वृत्तम्","text":"vyāyāmajātairabalasya taistairākṣipya vāyuśca śirāpratānam saṅkocya sampīḍya viśoṣya cāpi granthiṃ karotyunnatamāśu vṛttam"},{"type":"verse","number":"17","sanskrit":"ग्रन्थिः शिराजः स तु कृच्छ्रसाध्यो भवेद्यदि स्यात्सरुजश्चलश्च अरुक्स एवाप्यचलो महांश्च मर्मोत्थितश्चापि विवर्जनीयः","text":"granthiḥ śirājaḥ sa tu kṛcchrasādhyo bhavedyadi syātsarujaścalaśca aruksa evāpyacalo mahāṃśca marmotthitaścāpi vivarjanīyaḥ"},{"type":"verse","number":"18","sanskrit":"गात्रप्रदेशे क्वचिदेव दोषाः सम्मूर्च्छिता मांसमसृक्प्रदूष्य वृत्तं स्थिरं मन्दरुजं महान्तमनल्पमूलं चिरवृद्ध्य्पाकम् कुर्वन्ति मांसोच्छ्रयमत्यगाधं तदर्बुदं शास्त्रविदो वदन्ति","text":"gātrapradeśe kvacideva doṣāḥ sammūrcchitā māṃsamasṛkpradūṣya vṛttaṃ sthiraṃ mandarujaṃ mahāntamanalpamūlaṃ ciravṛddhypākam kurvanti māṃsocchrayamatyagādhaṃ tadarbudaṃ śāstravido vadanti"},{"type":"verse","number":"19","sanskrit":"वातेन पित्तेन कफेन चापि रक्तेन मांसेन च मेदसा च तज्जायते तस्य च लक्षणानि ग्रन्थेः समानानि सदा भवन्ति","text":"vātena pittena kaphena cāpi raktena māṃsena ca medasā ca tajjāyate tasya ca lakṣaṇāni grantheḥ samānāni sadā bhavanti"},{"type":"verse","number":"20","sanskrit":"दोषः प्रदुष्टो रुधिरं सिराश्च सङ्कोच्य सम्पीड्य ततस्त्वपाकम् सास्रावमुन्नह्यति मांसपिण्डं मासाङ्कुरैरावृतमाशु वृद्धिम्","text":"doṣaḥ praduṣṭo rudhiraṃ sirāśca saṅkocya sampīḍya tatastvapākam sāsrāvamunnahyati māṃsapiṇḍaṃ māsāṅkurairāvṛtamāśu vṛddhim"},{"type":"verse","number":"21","sanskrit":"स्रवत्यजस्रं रुधिरं प्रदुष्टमसाध्यमेतद्रुधिरात्मकं तु रक्तक्षयोपद्र वपीडितत्वात्पाण्डुर्भवेदर्बुदपीडितस्तु","text":"sravatyajasraṃ rudhiraṃ praduṣṭamasādhyametadrudhirātmakaṃ tu raktakṣayopadra vapīḍitatvātpāṇḍurbhavedarbudapīḍitastu"},{"type":"verse","number":"22","sanskrit":"मुष्टिप्रहारादिभिरर्दितेऽङ्गे मांसं प्रदुष्टं समुपैति शोथम् अवेदनं स्निग्धमनन्यवर्णमपाकमश्मोपममप्रचाल्यम्","text":"muṣṭiprahārādibhirardite'ṅge māṃsaṃ praduṣṭaṃ samupaiti śotham avedanaṃ snigdhamananyavarṇamapākamaśmopamamapracālyam"},{"type":"verse","number":"23","sanskrit":"प्रदुष्टमांसस्य नरस्य गाढमेतद्भवेन्मांसपरायणस्य","text":"praduṣṭamāṃsasya narasya gāḍhametadbhavenmāṃsaparāyaṇasya"},{"type":"verse","number":"24","sanskrit":"यज्जायतेऽन्यात्खलु पूर्वजाते ज्ञेयं तदध्यर्बुदमर्बुदज्ञैः यद् द्वन्द्वजातं युगपत्क्रमाद्वा द्विरर्बुदं तच्च भवेदसाध्यम्","text":"yajjāyate'nyātkhalu pūrvajāte jñeyaṃ tadadhyarbudamarbudajñaiḥ yad dvandvajātaṃ yugapatkramādvā dvirarbudaṃ tacca bhavedasādhyam"},{"type":"verse","number":"25","sanskrit":"मांसार्बुदं त्वेतदसाध्यमाहुः साध्येष्वपीमानि विवर्जयेच्च सम्प्रस्रुतं मर्मसु यच्च जातं स्रोतःसु वा यत्तु भवेदचाल्यम्","text":"māṃsārbudaṃ tvetadasādhyamāhuḥ sādhyeṣvapīmāni vivarjayecca samprasrutaṃ marmasu yacca jātaṃ srotaḥsu vā yattu bhavedacālyam"},{"type":"verse","number":"26","sanskrit":"न पाकमायान्ति कफाधिकत्वान्मेदोबहुत्वाच्च विशेषतस्तु दोषस्थिरत्वाद् ग्रथनाच्च तेषां सर्वार्बुदान्येव निसर्गतस्तु","text":"na pākamāyānti kaphādhikatvānmedobahutvācca viśeṣatastu doṣasthiratvād grathanācca teṣāṃ sarvārbudānyeva nisargatastu"},{"type":"verse","number":"27","sanskrit":"सर्षपाञ्छिग्रुबीजानि शणबीजातसीयवान् मूलकस्य च बीजानि तक्रेणाम्लेन पेषयेत्","text":"sarṣapāñchigrubījāni śaṇabījātasīyavān mūlakasya ca bījāni takreṇāmlena peṣayet"},{"type":"verse","number":"28","sanskrit":"गलगण्डगण्डमालाग्रन्थयश्चैव दारुणाः प्रलेपादेव नश्यन्ति विलयं यान्ति सत्वरम्","text":"galagaṇḍagaṇḍamālāgranthayaścaiva dāruṇāḥ pralepādeva naśyanti vilayaṃ yānti satvaram"},{"type":"verse","number":"29","sanskrit":"रक्षोघ्नतैलयुक्तेन जलकुम्भीकभस्मना लेपनं गलगण्डस्य चिरोत्थस्यापि शस्यते","text":"rakṣoghnatailayuktena jalakumbhīkabhasmanā lepanaṃ galagaṇḍasya cirotthasyāpi śasyate"},{"type":"verse","number":"30","sanskrit":"श्वेतापराजितामूलं प्रातः पिष्ट्वा पिबेन्नरः सर्पिषा नियताहारो गलगण्डप्रशान्तये","text":"śvetāparājitāmūlaṃ prātaḥ piṣṭvā pibennaraḥ sarpiṣā niyatāhāro galagaṇḍapraśāntaye"},{"type":"verse","number":"31","sanskrit":"तिक्तालाबुफले पक्वे सप्ताहमुषितं जलम् सद्यः स्याद्गलगण्डघ्नं पानात् पथ्यान्नसेविनाम्","text":"tiktālābuphale pakve saptāhamuṣitaṃ jalam sadyaḥ syādgalagaṇḍaghnaṃ pānāt pathyānnasevinām"},{"type":"verse","number":"32","sanskrit":"तैलं पिबेद्वाऽमृतवल्लिनिम्बहिंस्राऽभयावृक्षकपिप्पलीभिः सिद्धं बलाभ्यां सह देवदारुणा हिताय नित्यं गलगण्डरोगी","text":"tailaṃ pibedvā'mṛtavallinimbahiṃsrā'bhayāvṛkṣakapippalībhiḥ siddhaṃ balābhyāṃ saha devadāruṇā hitāya nityaṃ galagaṇḍarogī"},{"type":"verse","number":"33","sanskrit":"यवमुद्गपटोलादिकटु रूक्षान्नभोजनम् वमनं रक्तमोक्षञ्च गलगण्डे प्रयोजयेत्","text":"yavamudgapaṭolādikaṭu rūkṣānnabhojanam vamanaṃ raktamokṣañca galagaṇḍe prayojayet"},{"type":"verse","number":"34","sanskrit":"दापयेत्प्रच्छनान्यत्र गण्डगोपालिकोद्भवः प्रलेपस्त्वनुभूतोऽय बहुधा बहुभिर्जनैः","text":"dāpayetpracchanānyatra gaṇḍagopālikodbhavaḥ pralepastvanubhūto'ya bahudhā bahubhirjanaiḥ"},{"type":"verse","number":"35","sanskrit":"लवणं जलकुम्भीञ्च कणाचूर्णेन संयुतम् प्रभाते नित्यमश्नीयाद्गलगण्डप्रशान्तये","text":"lavaṇaṃ jalakumbhīñca kaṇācūrṇena saṃyutam prabhāte nityamaśnīyādgalagaṇḍapraśāntaye"},{"type":"verse","number":"36","sanskrit":"काञ्चनारत्वचः क्वाथः शुण्ठीचूर्णेन संयुतः माक्षिकाढ्यः सकृत्पीतः क्वाथो वरुणमूलजः","text":"kāñcanāratvacaḥ kvāthaḥ śuṇṭhīcūrṇena saṃyutaḥ mākṣikāḍhyaḥ sakṛtpītaḥ kvātho varuṇamūlajaḥ"},{"type":"verse","number":"37","sanskrit":"गण्डमालां हरत्याशु चिरकालानुबन्धिनीम्","text":"gaṇḍamālāṃ haratyāśu cirakālānubandhinīm"},{"type":"verse","number":"38","sanskrit":"पलमर्द्धपलञ्चापि पिष्टां तण्डुलवारिणा काञ्चनारत्वचं पीत्वा गण्डमालां व्यपोहति","text":"palamarddhapalañcāpi piṣṭāṃ taṇḍulavāriṇā kāñcanāratvacaṃ pītvā gaṇḍamālāṃ vyapohati"},{"type":"verse","number":"39","sanskrit":"काञ्चनारस्य गृह्णीयात्त्वचं पञ्चपलोन्मिताम् नागरस्य कणायाश्च मरिचस्य पलं पलम्","text":"kāñcanārasya gṛhṇīyāttvacaṃ pañcapalonmitām nāgarasya kaṇāyāśca maricasya palaṃ palam"},{"type":"verse","number":"40","sanskrit":"पथ्याबिभीतधात्रीणां पलमर्द्धं पृथक्पृथक् वरुणस्याक्षमेकं च पत्रकैलात्वचां पुनः","text":"pathyābibhītadhātrīṇāṃ palamarddhaṃ pṛthakpṛthak varuṇasyākṣamekaṃ ca patrakailātvacāṃ punaḥ"},{"type":"verse","number":"41","sanskrit":"टङ्कं टङ्कं समादाय सर्वाण्येकत्र चूर्णयेत् यावच्चूर्णमिदं सर्वं तावानेवात्र गुग्गुलुः","text":"ṭaṅkaṃ ṭaṅkaṃ samādāya sarvāṇyekatra cūrṇayet yāvaccūrṇamidaṃ sarvaṃ tāvānevātra gugguluḥ"},{"type":"verse","number":"42","sanskrit":"संकुट्य सर्वमेकत्र पिण्डं कृत्वा विधारयेत् गुटिकाः शाणिकाः कृत्वा प्रभाते भक्षयेन्नरः","text":"saṃkuṭya sarvamekatra piṇḍaṃ kṛtvā vidhārayet guṭikāḥ śāṇikāḥ kṛtvā prabhāte bhakṣayennaraḥ"},{"type":"verse","number":"43","sanskrit":"गलगण्डं जयत्युग्रमपचीमर्बुदानि च ग्रन्थीन्व्रणानि गुल्मांश्च कुष्ठानि च भगन्दरम्","text":"galagaṇḍaṃ jayatyugramapacīmarbudāni ca granthīnvraṇāni gulmāṃśca kuṣṭhāni ca bhagandaram"},{"type":"verse","number":"44","sanskrit":"प्रदेयश्चानुपानार्थं क्वाथो मुण्डितिकाभवः क्वाथः खदिरसारस्य क्वाथः कोष्णोऽभयाभवः","text":"pradeyaścānupānārthaṃ kvātho muṇḍitikābhavaḥ kvāthaḥ khadirasārasya kvāthaḥ koṣṇo'bhayābhavaḥ"},{"type":"verse","number":"45","sanskrit":"चक्रमर्दकमूलस्य पलकल्के विपाचयेत् केशरागरसे तैलं कटुकं मृदुनाऽग्निना","text":"cakramardakamūlasya palakalke vipācayet keśarāgarase tailaṃ kaṭukaṃ mṛdunā'gninā"},{"type":"verse","number":"46","sanskrit":"पादांशिकं विनिक्षिप्य सिन्दूरमवतारयेत् एतत्तैलं निहन्त्याशु गण्डमालां सुदारुणाम्","text":"pādāṃśikaṃ vinikṣipya sindūramavatārayet etattailaṃ nihantyāśu gaṇḍamālāṃ sudāruṇām"},{"type":"verse","number":"47","sanskrit":"गुञ्जामूलफलैस्तैलं विपक्वं द्बिगुणाम्भसा हरेदभ्यङ्गनस्याभ्यां गण्डमालां सुदारुणाम्","text":"guñjāmūlaphalaistailaṃ vipakvaṃ dbiguṇāmbhasā haredabhyaṅganasyābhyāṃ gaṇḍamālāṃ sudāruṇām"},{"type":"verse","number":"48","sanskrit":"चन्दनं साभया लाक्षा वचा कटुकरोहिणी एतैस्तैलं शृतं पीत्वा समूलामपचीं हरेत्","text":"candanaṃ sābhayā lākṣā vacā kaṭukarohiṇī etaistailaṃ śṛtaṃ pītvā samūlāmapacīṃ haret"},{"type":"verse","number":"49","sanskrit":"व्योषं बिडङ्गं मधुकं सैन्धवं देवदारु च तैलमेभिः शृतं नस्यात्सकृच्छ्रामपचीं हरेत्","text":"vyoṣaṃ biḍaṅgaṃ madhukaṃ saindhavaṃ devadāru ca tailamebhiḥ śṛtaṃ nasyātsakṛcchrāmapacīṃ haret"},{"type":"verse","number":"50","sanskrit":"स्वर्जिकामूलकक्षारः शङ्खचूर्णसमन्वितः एतेन विहितो लेपो हन्ति ग्रन्थिं तथाऽबुदम्","text":"svarjikāmūlakakṣāraḥ śaṅkhacūrṇasamanvitaḥ etena vihito lepo hanti granthiṃ tathā'budam"},{"type":"verse","number":"51","sanskrit":"ग्रन्थिर्न यो नश्यति भेषजेन निष्काश्य तं शस्त्रचिकित्सकेन जात्यादिपक्वेन घृतेन वैद्यो व्रणेन चान्येन च सञ्चिकित्सेत्","text":"granthirna yo naśyati bheṣajena niṣkāśya taṃ śastracikitsakena jātyādipakvena ghṛtena vaidyo vraṇena cānyena ca sañcikitset"},{"type":"verse","number":"52","sanskrit":"ग्रन्थिमुद्धृत्य तत्रापि व्रणोक्तं क्रममाचरेत् शिराग्रन्थिं विहायान्ये शेषे शस्त्रं प्रयुज्यते","text":"granthimuddhṛtya tatrāpi vraṇoktaṃ kramamācaret śirāgranthiṃ vihāyānye śeṣe śastraṃ prayujyate"},{"type":"verse","number":"53","sanskrit":"ग्रन्थ्यर्बुदानां न यतो विशेषः प्रदेशहेत्वाकृतिदोषदूष्यैः अतश्चिकित्सेद्भिषगर्बुदानि विधानविद् ग्रन्थिचिकित्सितेन","text":"granthyarbudānāṃ na yato viśeṣaḥ pradeśahetvākṛtidoṣadūṣyaiḥ ataścikitsedbhiṣagarbudāni vidhānavid granthicikitsitena"},{"type":"verse","number":"54","sanskrit":"हरिद्रा लोध्रपत्राङ्गगृह धूममनःशिलाः मधुप्रगाढो लेपोऽय मेदोऽबुदहरः परः","text":"haridrā lodhrapatrāṅgagṛha dhūmamanaḥśilāḥ madhupragāḍho lepo'ya medo'budaharaḥ paraḥ"},{"type":"verse","number":"55","sanskrit":"मूलकस्य कृतः क्षारो हरिद्रा यास्तथैव च शङ्खचूर्णेन संयुक्तो लेपः सिद्धोऽबुदापहः","text":"mūlakasya kṛtaḥ kṣāro haridrā yāstathaiva ca śaṅkhacūrṇena saṃyukto lepaḥ siddho'budāpahaḥ"},{"type":"verse","number":"56","sanskrit":"वटदुग्धकुष्ठरोमकलिप्तं बद्धं वटस्य पत्रेण अध्यस्थि सप्तरात्रान्महदप्युपशान्तिमर्बुदं गच्छेत्","text":"vaṭadugdhakuṣṭharomakaliptaṃ baddhaṃ vaṭasya patreṇa adhyasthi saptarātrānmahadapyupaśāntimarbudaṃ gacchet"},{"type":"verse","number":"57","sanskrit":"शिग्रुमूलकयोर्बीजं रक्षोघ्नं सुरसा यवम् तक्रेणाश्वरिपुं पिष्ट्वा लिम्पेदर्बुदशान्तये","text":"śigrumūlakayorbījaṃ rakṣoghnaṃ surasā yavam takreṇāśvaripuṃ piṣṭvā limpedarbudaśāntaye"},{"type":"verse","number":"58","sanskrit":"इति चतुश्चत्वारिंशत्तमो गलगण्डगण्डमालाग्रन्थ्यर्बुदाधिकारः समाप्तः ४४","text":"iti catuścatvāriṃśattamo galagaṇḍagaṇḍamālāgranthyarbudādhikāraḥ samāptaḥ 44"}]},{"sthana":"Уттаракханда","number":45,"lang":"sa","content":[{"type":"heading","heading":"Шлипада — слоновость"},{"type":"verse","number":"1","sanskrit":"पुराणोदकभूयिष्ठाः सर्वर्तुषु च शीतलाः ये देशास्तेषु जायन्ते श्लीपदानि विशेषतः","text":"purāṇodakabhūyiṣṭhāḥ sarvartuṣu ca śītalāḥ ye deśāsteṣu jāyante ślīpadāni viśeṣataḥ"},{"type":"verse","number":"2","sanskrit":"यः सज्वरो बङ्क्षणजो भृशार्त्तिः शोथो नृणां पादगतः क्रमेण तच्छ्लीपदं स्यात्करकर्णनेत्रशिश्नौष्टनासास्वपि केचिदाहुः","text":"yaḥ sajvaro baṅkṣaṇajo bhṛśārttiḥ śotho nṛṇāṃ pādagataḥ krameṇa tacchlīpadaṃ syātkarakarṇanetraśiśnauṣṭanāsāsvapi kecidāhuḥ"},{"type":"verse","number":"3","sanskrit":"वातजं कृष्णरूक्षं हि स्फुटितं तीव्रवेदनम् अनिमित्तरुजञ्चास्य बहुशो ज्वर एव च","text":"vātajaṃ kṛṣṇarūkṣaṃ hi sphuṭitaṃ tīvravedanam animittarujañcāsya bahuśo jvara eva ca"},{"type":"verse","number":"4","sanskrit":"पित्तजं पीतसंकाशं दाहज्वरयुतं भृशम् श्लैष्मिकन्तुभवेत्स्निग्धं श्वेतं पाण्डु गुरु स्थिरम्","text":"pittajaṃ pītasaṃkāśaṃ dāhajvarayutaṃ bhṛśam ślaiṣmikantubhavetsnigdhaṃ śvetaṃ pāṇḍu guru sthiram"},{"type":"verse","number":"5","sanskrit":"त्रीण्यप्येतानि जानीयाच्छ्लीपदानि कफोच्छ्रयात् गुरुत्वञ्च महत्वञ्च यस्मान्नास्ति विना कफात्","text":"trīṇyapyetāni jānīyācchlīpadāni kaphocchrayāt gurutvañca mahatvañca yasmānnāsti vinā kaphāt"},{"type":"verse","number":"6","sanskrit":"वल्मीकमिव सञ्जातं कण्टकैरुपचीयते अब्दात्मकं महत्तत्तु वर्जनीयं विशेषतः","text":"valmīkamiva sañjātaṃ kaṇṭakairupacīyate abdātmakaṃ mahattattu varjanīyaṃ viśeṣataḥ"},{"type":"verse","number":"7","sanskrit":"यच्छ्लैष्मिकाहारविहारजातैर्जातं तथा भूरिकफस्य पुंसः सास्रावमत्युन्नतसर्वलिङ्गं सकण्डुकं चापि विवर्जनीयम्","text":"yacchlaiṣmikāhāravihārajātairjātaṃ tathā bhūrikaphasya puṃsaḥ sāsrāvamatyunnatasarvaliṅgaṃ sakaṇḍukaṃ cāpi vivarjanīyam"},{"type":"verse","number":"8","sanskrit":"लङ्घनालेपनस्वेदरेचनै रक्तमोक्षणैः प्रायः श्लेष्महरैरुष्णैः श्लीपदं समुपाचरेत्","text":"laṅghanālepanasvedarecanai raktamokṣaṇaiḥ prāyaḥ śleṣmaharairuṣṇaiḥ ślīpadaṃ samupācaret"},{"type":"verse","number":"9","sanskrit":"सिद्धार्थशोभाञ्जनदेवदारुविश्वौषधैर्मूत्रयुतैः प्रलिम्पेत् पुनर्नवानागरसर्षपाणां कल्केन वा काञ्जिकमिश्रितेन","text":"siddhārthaśobhāñjanadevadāruviśvauṣadhairmūtrayutaiḥ pralimpet punarnavānāgarasarṣapāṇāṃ kalkena vā kāñjikamiśritena"},{"type":"verse","number":"10","sanskrit":"धत्तूरैरण्डनिर्गुण्डी वर्षाभूशिग्रुसर्षपैः प्रलेपः श्लीपदं हन्ति चिरोत्थमपि दारुणम्","text":"dhattūrairaṇḍanirguṇḍī varṣābhūśigrusarṣapaiḥ pralepaḥ ślīpadaṃ hanti cirotthamapi dāruṇam"},{"type":"verse","number":"11","sanskrit":"असाध्यमपि यात्यस्तं श्लीपदं चिरकालजम् मूलेन सहदेवायास्तालमिश्रेण लेपनात्","text":"asādhyamapi yātyastaṃ ślīpadaṃ cirakālajam mūlena sahadevāyāstālamiśreṇa lepanāt"},{"type":"verse","number":"12","sanskrit":"सप्तताम्बूलपत्राणां कल्कं तप्तेन वारिणा संसृष्टं लवणोपेतं सेवितं श्लीपदं हरेत्","text":"saptatāmbūlapatrāṇāṃ kalkaṃ taptena vāriṇā saṃsṛṣṭaṃ lavaṇopetaṃ sevitaṃ ślīpadaṃ haret"},{"type":"verse","number":"13","sanskrit":"शाखोटवल्कलक्वाथं गोमूत्रेण युतं पिबेत् श्लीपदानां विनाशाय मेदोदोषनिवृत्तये","text":"śākhoṭavalkalakvāthaṃ gomūtreṇa yutaṃ pibet ślīpadānāṃ vināśāya medodoṣanivṛttaye"},{"type":"verse","number":"14","sanskrit":"रजनीं गुडसंयुक्तां गोमूत्रेण पिबेन्नरः वर्षाभूत्रिफलाचूर्णं पिप्पल्या सह योजितम् सक्षौद्रं श्लीपदे लिह्याच्चिरोत्थं श्लीपदं जयेत् गन्धर्वतैलसिद्धां हरीतकीं गोऽम्बुना पिबेन्नित्यम् श्लीपदबन्धनमुक्तो भवत्यसौ सप्तरात्रेण","text":"rajanīṃ guḍasaṃyuktāṃ gomūtreṇa pibennaraḥ varṣābhūtriphalācūrṇaṃ pippalyā saha yojitam sakṣaudraṃ ślīpade lihyāccirotthaṃ ślīpadaṃ jayet gandharvatailasiddhāṃ harītakīṃ go'mbunā pibennityam ślīpadabandhanamukto bhavatyasau saptarātreṇa"},{"type":"verse","number":"15","sanskrit":"इति पञ्चचत्वारिंशत्तमः श्लीपदाधिकारः समाप्तः ४५","text":"iti pañcacatvāriṃśattamaḥ ślīpadādhikāraḥ samāptaḥ 45"}]},{"sthana":"Уттаракханда","number":46,"lang":"sa","content":[{"type":"heading","heading":"Видрадхи — абсцессы"},{"type":"verse","number":"1","sanskrit":"त्वग्रक्तमांसमेदांसि प्रदूष्यास्थिसमाश्रिताः दोषाः शोथं शनैर्घोरं जनयन्त्युच्छ्रिता भृशम्","text":"tvagraktamāṃsamedāṃsi pradūṣyāsthisamāśritāḥ doṣāḥ śothaṃ śanairghoraṃ janayantyucchritā bhṛśam"},{"type":"verse","number":"2","sanskrit":"महामूलं रुजावन्तं वृत्तं वाऽप्यथ वाऽयतम् स विद्र धिरिति ख्यातो विज्ञेयः षड्विधश्च सः","text":"mahāmūlaṃ rujāvantaṃ vṛttaṃ vā'pyatha vā'yatam sa vidra dhiriti khyāto vijñeyaḥ ṣaḍvidhaśca saḥ"},{"type":"verse","number":"3","sanskrit":"विद्र धिषड्विधत्वं विवृणोति पृथग् दोषैः समस्तैश्च क्षतेनाप्यसृजा तथा षण्णामपि हि तेषां तु लक्षणं सम्प्रचक्ष्यते","text":"vidra dhiṣaḍvidhatvaṃ vivṛṇoti pṛthag doṣaiḥ samastaiśca kṣatenāpyasṛjā tathā ṣaṇṇāmapi hi teṣāṃ tu lakṣaṇaṃ sampracakṣyate"},{"type":"verse","number":"4","sanskrit":"कृष्णोऽरुणो वा विषमो भृशमत्यर्थवेदनः चिरोत्थानप्रपाकश्च विद्र धिर्वातसम्भवः","text":"kṛṣṇo'ruṇo vā viṣamo bhṛśamatyarthavedanaḥ cirotthānaprapākaśca vidra dhirvātasambhavaḥ"},{"type":"verse","number":"5","sanskrit":"पक्वोदुम्बरसंकाशःश्यावो वा ज्वरदाहवान् क्षिप्रोत्थानप्रपाकश्च विद्र धिः पित्तसम्भवः","text":"pakvodumbarasaṃkāśaḥśyāvo vā jvaradāhavān kṣiprotthānaprapākaśca vidra dhiḥ pittasambhavaḥ"},{"type":"verse","number":"6","sanskrit":"शरावसदृशः पाण्डुः शीतः स्निग्धोऽल्पवेदनः चिरोत्थानप्रपाकश्च विद्र धिः कफसम्भवः तनुपीतसिताश्चैषामास्रावाः क्रमतो मताः","text":"śarāvasadṛśaḥ pāṇḍuḥ śītaḥ snigdho'lpavedanaḥ cirotthānaprapākaśca vidra dhiḥ kaphasambhavaḥ tanupītasitāścaiṣāmāsrāvāḥ kramato matāḥ"},{"type":"verse","number":"7","sanskrit":"नानावर्णरुजास्रावी घाटालो विषमो महान् विषमं पच्यते वाऽपि विद्र धिः सान्निपातिकः","text":"nānāvarṇarujāsrāvī ghāṭālo viṣamo mahān viṣamaṃ pacyate vā'pi vidra dhiḥ sānnipātikaḥ"},{"type":"verse","number":"8","sanskrit":"तैस्तैर्भावैरभिहते क्षतेवाऽपथ्यकारिणाम् क्षतोष्मा वायुविसृतः सरक्तं पित्तमीरयेत्","text":"taistairbhāvairabhihate kṣatevā'pathyakāriṇām kṣatoṣmā vāyuvisṛtaḥ saraktaṃ pittamīrayet"},{"type":"verse","number":"9","sanskrit":"ज्वरस्तृषा च दाहश्च जायते तस्य देहिनः आगन्तुर्विद्र धिर्ह्येष पित्तविद्र धिलक्षणः","text":"jvarastṛṣā ca dāhaśca jāyate tasya dehinaḥ āganturvidra dhirhyeṣa pittavidra dhilakṣaṇaḥ"},{"type":"verse","number":"10","sanskrit":"कृष्णस्फोटावृतः श्यावस्तीव्रदाहरुजाज्वरः पित्तविद्र धिलिङ्गस्तु रक्तविद्र धिरुच्यते","text":"kṛṣṇasphoṭāvṛtaḥ śyāvastīvradāharujājvaraḥ pittavidra dhiliṅgastu raktavidra dhirucyate"},{"type":"verse","number":"11","sanskrit":"आभ्यन्तरानतस्तूर्ध्वं विद्र धीन् परिचक्षते गुर्वसात्म्यविरुद्धान्नशुष्कशाकाम्लभोजनैः","text":"ābhyantarānatastūrdhvaṃ vidra dhīn paricakṣate gurvasātmyaviruddhānnaśuṣkaśākāmlabhojanaiḥ"},{"type":"verse","number":"12","sanskrit":"अतिव्यवायव्यायामवेगाघातविदाहिभिः पृथक् सम्भूय वा दोषाः कुपिता गुल्मरूपिणम्","text":"ativyavāyavyāyāmavegāghātavidāhibhiḥ pṛthak sambhūya vā doṣāḥ kupitā gulmarūpiṇam"},{"type":"verse","number":"13","sanskrit":"वल्मीकवत्समुन्नद्धमन्तः कुर्वन्ति विद्र धिम् गुदे वस्तिमुखे नाभ्यां कुक्षौ वङ्क्षणयोस्तथा","text":"valmīkavatsamunnaddhamantaḥ kurvanti vidra dhim gude vastimukhe nābhyāṃ kukṣau vaṅkṣaṇayostathā"},{"type":"verse","number":"14","sanskrit":"वृक्कयोः प्लीह्नि यकृति हृदि वा क्लोम्नि चाप्यथ एषां लिङ्गानि जानीयाद् बाह्यविद्र धिलक्षणैः","text":"vṛkkayoḥ plīhni yakṛti hṛdi vā klomni cāpyatha eṣāṃ liṅgāni jānīyād bāhyavidra dhilakṣaṇaiḥ"},{"type":"verse","number":"15","sanskrit":"गुदे वातनिरोधस्तु वस्तौ कृच्छ्राल्पमूत्रता नाभ्यां हिक्काजृम्भणं च कुक्षौ मारुतकोपनम्","text":"gude vātanirodhastu vastau kṛcchrālpamūtratā nābhyāṃ hikkājṛmbhaṇaṃ ca kukṣau mārutakopanam"},{"type":"verse","number":"16","sanskrit":"कटिपृष्ठग्रहस्तीव्रो वङ्क्षणोत्थे तु विद्र धौ वृक्कयोः पार्श्वसङ्कोचः प्लीह्न्युच्छ्वासावरोधनम्","text":"kaṭipṛṣṭhagrahastīvro vaṅkṣaṇotthe tu vidra dhau vṛkkayoḥ pārśvasaṅkocaḥ plīhnyucchvāsāvarodhanam"},{"type":"verse","number":"17","sanskrit":"सर्वाङ्गप्रग्रहस्तीव्रो हृदि कासश्च जायते श्वासो यकृति हिक्का च क्लोम्नि पेपीयते पयः","text":"sarvāṅgapragrahastīvro hṛdi kāsaśca jāyate śvāso yakṛti hikkā ca klomni pepīyate payaḥ"},{"type":"verse","number":"18","sanskrit":"नाभेरुपरिजाः पक्वा यान्त्यूर्ध्वमितरे त्वधः","text":"nābheruparijāḥ pakvā yāntyūrdhvamitare tvadhaḥ"},{"type":"verse","number":"19","sanskrit":"अधःस्रुतेषु जीवेत्तु स्रुतेषूर्ध्वं न जीवति हृन्नाभिवस्तिवर्ज्येषु तेषु भिन्नेषु वाह्यतः जीवेत् कदाचित्पुरुषो नेतरेषु कदाचन","text":"adhaḥsruteṣu jīvettu sruteṣūrdhvaṃ na jīvati hṛnnābhivastivarjyeṣu teṣu bhinneṣu vāhyataḥ jīvet kadācitpuruṣo netareṣu kadācana"},{"type":"verse","number":"20","sanskrit":"साध्या विद्र धयः पञ्च विवर्ज्यः सान्निपातिकः आमपक्वविदग्धत्वं तेषां ज्ञेयञ्च शोथवत्","text":"sādhyā vidra dhayaḥ pañca vivarjyaḥ sānnipātikaḥ āmapakvavidagdhatvaṃ teṣāṃ jñeyañca śothavat"},{"type":"verse","number":"21","sanskrit":"जलौकापातनं शस्तं सर्वस्मिन्नेव विद्र धौ रेको मृदुर्लङ्घनञ्च स्वेदः पित्तोत्तरं विना","text":"jalaukāpātanaṃ śastaṃ sarvasminneva vidra dhau reko mṛdurlaṅghanañca svedaḥ pittottaraṃ vinā"},{"type":"verse","number":"22","sanskrit":"अपक्वे विद्र धौ युञ्ज्याद् व्रणशोथवदौषधम् वातघ्नमूलकल्कैस्तु वसातैलघृतान्वितैः","text":"apakve vidra dhau yuñjyād vraṇaśothavadauṣadham vātaghnamūlakalkaistu vasātailaghṛtānvitaiḥ"},{"type":"verse","number":"23","sanskrit":"सुखोष्णैर्बहुलैर्लेपः प्रयोज्यो वातविद्र धौ यवगोधूममुद्गैश्च पिष्टैराज्येन लेपयेत्","text":"sukhoṣṇairbahulairlepaḥ prayojyo vātavidra dhau yavagodhūmamudgaiśca piṣṭairājyena lepayet"},{"type":"verse","number":"24","sanskrit":"विलीयते क्षणेनैव ह्यविपक्वस्तु विद्र धिः","text":"vilīyate kṣaṇenaiva hyavipakvastu vidra dhiḥ"},{"type":"verse","number":"25","sanskrit":"पैत्तिकं विद्र धिं वैद्यः प्रदिह्यात्सर्पिषा युतैः पयस्योशीरमधुकचन्दनैर्दुग्धपेषितैः","text":"paittikaṃ vidra dhiṃ vaidyaḥ pradihyātsarpiṣā yutaiḥ payasyośīramadhukacandanairdugdhapeṣitaiḥ"},{"type":"verse","number":"26","sanskrit":"पञ्चवल्कलकल्केन घृतमिश्रेण लेपयेत् पिबेद्वा त्रिफलाक्वाथं त्रिवृत्कल्काक्षसंयुतम्","text":"pañcavalkalakalkena ghṛtamiśreṇa lepayet pibedvā triphalākvāthaṃ trivṛtkalkākṣasaṃyutam"},{"type":"verse","number":"27","sanskrit":"इष्टिका सिकता लोहकिट्टं गोशकृता सह मूत्रैः सुखोष्णैर्लेपेन स्वेदयेच्छ्लेष्मविद्र धिम्","text":"iṣṭikā sikatā lohakiṭṭaṃ gośakṛtā saha mūtraiḥ sukhoṣṇairlepena svedayecchleṣmavidra dhim"},{"type":"verse","number":"28","sanskrit":"दशमूलीकषायेण सस्नेहेन रसेन वा शोथव्रणं वा कोष्णेन सशूलं परिषेचयेत्","text":"daśamūlīkaṣāyeṇa sasnehena rasena vā śothavraṇaṃ vā koṣṇena saśūlaṃ pariṣecayet"},{"type":"verse","number":"29","sanskrit":"पित्तविद्र धिवत्सर्वाः क्रिया निरवशेषतः विद्र ध्योः कुशलः कुर्याद्र क्तागन्तुनिमित्तयोः","text":"pittavidra dhivatsarvāḥ kriyā niravaśeṣataḥ vidra dhyoḥ kuśalaḥ kuryādra ktāgantunimittayoḥ"},{"type":"verse","number":"30","sanskrit":"रक्तचन्दन मञ्जिष्ठानिशा मधुकगैरिकैः क्षीरेण विद्र धौ लेपो रक्तागन्तुनिमित्तके","text":"raktacandana mañjiṣṭhāniśā madhukagairikaiḥ kṣīreṇa vidra dhau lepo raktāgantunimittake"},{"type":"verse","number":"31","sanskrit":"पीता ह्येते निहन्त्याशु विद्र धिं कोष्ठसम्भवम् कृष्णाऽजाजी विशाला च धामार्गवफलं तथा","text":"pītā hyete nihantyāśu vidra dhiṃ koṣṭhasambhavam kṛṣṇā'jājī viśālā ca dhāmārgavaphalaṃ tathā"},{"type":"verse","number":"32","sanskrit":"श्वेतवर्षाभुवो मूलं मूलं वा वरुणस्य च जलेन क्वथितं पीतमन्तर्विद्र धिहृत्परम्","text":"śvetavarṣābhuvo mūlaṃ mūlaṃ vā varuṇasya ca jalena kvathitaṃ pītamantarvidra dhihṛtparam"},{"type":"verse","number":"33","sanskrit":"गायत्रीत्रिफलानिम्बकटुकामधुकं समम् त्रिवृत्पटोलमूलाभ्यां चत्वारॐऽशा पृथक् पृथक्","text":"gāyatrītriphalānimbakaṭukāmadhukaṃ samam trivṛtpaṭolamūlābhyāṃ catvāraoṃ'śā pṛthak pṛthak"},{"type":"verse","number":"34","sanskrit":"मसूरान्निस्तुषान्दद्यादेष क्वाथो व्रणाञ्चयेत् गुल्मविद्र धिबीसर्पदाह मोहज्वरापहः","text":"masūrānnistuṣāndadyādeṣa kvātho vraṇāñcayet gulmavidra dhibīsarpadāha mohajvarāpahaḥ"},{"type":"verse","number":"35","sanskrit":"तृण्मूर्च्छाच्छर्दिहृद्रो गपित्तासृक्कुष्ठकामलाः शिग्रुमूलं जले धौतं पिष्टं वस्त्रेण गालयेत् तद्र सं मधुना पीत्वा हन्त्यन्तर्विद्र धिं नरः","text":"tṛṇmūrcchācchardihṛdro gapittāsṛkkuṣṭhakāmalāḥ śigrumūlaṃ jale dhautaṃ piṣṭaṃ vastreṇa gālayet tadra saṃ madhunā pītvā hantyantarvidra dhiṃ naraḥ"},{"type":"verse","number":"36","sanskrit":"शोभाञ्जनकनिर्यूहोहिङ्गुसैन्धवसंयुतः हन्त्यन्तर्विद्र धिं शीघ्रं प्रातः प्रातर्विशेषतः","text":"śobhāñjanakaniryūhohiṅgusaindhavasaṃyutaḥ hantyantarvidra dhiṃ śīghraṃ prātaḥ prātarviśeṣataḥ"},{"type":"verse","number":"37","sanskrit":"इति षट्चत्वारिंशत्तमो विद्र ध्यधिकारः समाप्तः ४६","text":"iti ṣaṭcatvāriṃśattamo vidra dhyadhikāraḥ samāptaḥ 46"}]},{"sthana":"Уттаракханда","number":47,"lang":"sa","content":[{"type":"heading","heading":"Врана-шотха — раны и воспаления"},{"type":"verse","number":"1","sanskrit":"पृथक्समस्तदोषोत्था रक्तजागन्तुजौ तथा व्रणशोथाः षडेते स्युः संयुक्ताः शोथलक्षणैः","text":"pṛthaksamastadoṣotthā raktajāgantujau tathā vraṇaśothāḥ ṣaḍete syuḥ saṃyuktāḥ śothalakṣaṇaiḥ"},{"type":"verse","number":"2","sanskrit":"विषमं पच्यते वातात्पित्तोत्थश्चाचिराच्चिरम् कफजः पित्तवच्छोथौ रक्तागन्तुसमुद्भवौ","text":"viṣamaṃ pacyate vātātpittotthaścācirācciram kaphajaḥ pittavacchothau raktāgantusamudbhavau"},{"type":"verse","number":"3","sanskrit":"मन्दोष्णताऽल्पशोथत्वं काठिन्यं त्वक्सवर्णता मन्दवेदनता चापि शोथस्यामस्य लक्षणम्","text":"mandoṣṇatā'lpaśothatvaṃ kāṭhinyaṃ tvaksavarṇatā mandavedanatā cāpi śothasyāmasya lakṣaṇam"},{"type":"verse","number":"4","sanskrit":"दह्यते दहनेनेव क्षारेणेव प्रपच्यते पिपीलिकागणेनेव दश्यते छिद्यते तथा","text":"dahyate dahaneneva kṣāreṇeva prapacyate pipīlikāgaṇeneva daśyate chidyate tathā"},{"type":"verse","number":"5","sanskrit":"भिद्यते चैव शस्त्रेण दण्डेनेव च ताड्यते पीड्यते पाणिनेवान्तः सूचीभिरिव तुद्यते","text":"bhidyate caiva śastreṇa daṇḍeneva ca tāḍyate pīḍyate pāṇinevāntaḥ sūcībhiriva tudyate"},{"type":"verse","number":"6","sanskrit":"सोषचोषो विवर्णः स्यादङ्गुल्येवावपीड्यते आसने शयने स्थाने शान्तिं वृश्चिकविद्धवत्","text":"soṣacoṣo vivarṇaḥ syādaṅgulyevāvapīḍyate āsane śayane sthāne śāntiṃ vṛścikaviddhavat"},{"type":"verse","number":"7","sanskrit":"न गच्छेदाततः शोथो भवेदाध्मातवस्तिवत् ज्वरस्तृष्णाऽरुचिश्चैतत्पच्यमानस्य लक्षणम्","text":"na gacchedātataḥ śotho bhavedādhmātavastivat jvarastṛṣṇā'ruciścaitatpacyamānasya lakṣaṇam"},{"type":"verse","number":"8","sanskrit":"वेदनोपशमः शोथो लोहितोऽल्पो न चोन्नतः प्रादुर्भावो वलीनाञ्च तोदः कण्डूर्मुहुर्मुहुः","text":"vedanopaśamaḥ śotho lohito'lpo na connataḥ prādurbhāvo valīnāñca todaḥ kaṇḍūrmuhurmuhuḥ"},{"type":"verse","number":"9","sanskrit":"उपद्र वाणां प्रशमो निम्नता स्फुटनं त्वचाम् वस्ताविवाम्बुसञ्चारः स्याच्छोथेऽङगुलिपीडिते","text":"upadra vāṇāṃ praśamo nimnatā sphuṭanaṃ tvacām vastāvivāmbusañcāraḥ syācchothe'ṅagulipīḍite"},{"type":"verse","number":"10","sanskrit":"पूयश्च पीडयेदेकमन्तमन्ते च पीडिते बुभुक्षा व्रणशोथस्य भवेत्पक्वस्य लक्षणम्","text":"pūyaśca pīḍayedekamantamante ca pīḍite bubhukṣā vraṇaśothasya bhavetpakvasya lakṣaṇam"},{"type":"verse","number":"11","sanskrit":"ॠतेऽनिलाद्रुङ् न विना न पित्तं पाकः कफञ्चापिविना न पूयः तस्माद्धि सर्वं परिपाककाले पचन्ति शोथास्त्रिभिरेव दोषैः","text":"ṝte'nilādruṅ na vinā na pittaṃ pākaḥ kaphañcāpivinā na pūyaḥ tasmāddhi sarvaṃ paripākakāle pacanti śothāstribhireva doṣaiḥ"},{"type":"verse","number":"12","sanskrit":"कालान्तरेणाभ्युदितन्तु पित्तं कृत्वा वशे वातकफौ प्रसह्य पचत्यतः शोणितमेष पाको मतः परेषां विदुषां द्वितीयः","text":"kālāntareṇābhyuditantu pittaṃ kṛtvā vaśe vātakaphau prasahya pacatyataḥ śoṇitameṣa pāko mataḥ pareṣāṃ viduṣāṃ dvitīyaḥ"},{"type":"verse","number":"13","sanskrit":"कफजेषु च शोथेषु गम्भीरं पाकमेत्यसृक् पक्वलिङ्गं ततः स्पष्टं यतः स्याच्छोथशीतता त्वक्सावर्ण्यं रुजोऽल्पत्वं घनस्पर्शत्वमश्मवत्","text":"kaphajeṣu ca śotheṣu gambhīraṃ pākametyasṛk pakvaliṅgaṃ tataḥ spaṣṭaṃ yataḥ syācchothaśītatā tvaksāvarṇyaṃ rujo'lpatvaṃ ghanasparśatvamaśmavat"},{"type":"verse","number":"14","sanskrit":"कक्षं समासाद्य यथैव वह्निर्वातेरितः संदहति प्रसह्य तथैव पूयो ह्यविनिःसृतस्तु मांसं शिराः स्नायुमपीह खादेत्","text":"kakṣaṃ samāsādya yathaiva vahnirvāteritaḥ saṃdahati prasahya tathaiva pūyo hyaviniḥsṛtastu māṃsaṃ śirāḥ snāyumapīha khādet"},{"type":"verse","number":"15","sanskrit":"आमं विदह्यमानञ्च सम्यक्पक्वन्तु यो भिषक् जानीयात्स भवेद्वैद्यः शेषास्तस्करवृत्तयः","text":"āmaṃ vidahyamānañca samyakpakvantu yo bhiṣak jānīyātsa bhavedvaidyaḥ śeṣāstaskaravṛttayaḥ"},{"type":"verse","number":"16","sanskrit":"यश्छिनत्त्याममज्ञानाद्यश्च पक्वमुपेक्षते श्वपचाविव विज्ञेयौ तावनिश्चितकारिणौ","text":"yaśchinattyāmamajñānādyaśca pakvamupekṣate śvapacāviva vijñeyau tāvaniścitakāriṇau"},{"type":"verse","number":"17","sanskrit":"आदौ शोथहरोलेपस्ततस्तु परिषेचनम् विम्लापनमसृङ्मोक्षस्ततः स्यादुपनाहनम्","text":"ādau śothaharolepastatastu pariṣecanam vimlāpanamasṛṅmokṣastataḥ syādupanāhanam"},{"type":"verse","number":"18","sanskrit":"पाचनं भेदनं पश्चात्पीडनं शोधनं तथा रोपणं वर्णकरणं व्रणस्यैते क्रमाः स्मृताः","text":"pācanaṃ bhedanaṃ paścātpīḍanaṃ śodhanaṃ tathā ropaṇaṃ varṇakaraṇaṃ vraṇasyaite kramāḥ smṛtāḥ"},{"type":"verse","number":"19","sanskrit":"यथा प्रज्वलिते वेश्मन्यम्भसा परिषेचनम् क्षिप्रं प्रशमयत्यग्निमेवमालेपनं रुजः","text":"yathā prajvalite veśmanyambhasā pariṣecanam kṣipraṃ praśamayatyagnimevamālepanaṃ rujaḥ"},{"type":"verse","number":"20","sanskrit":"बीजपूरजटाहिंस्रा देवदारु महौषधम् रास्नाऽग्निमन्थौ लेपोऽय वातशोथविनाशनः","text":"bījapūrajaṭāhiṃsrā devadāru mahauṣadham rāsnā'gnimanthau lepo'ya vātaśothavināśanaḥ"},{"type":"verse","number":"21","sanskrit":"कल्कः काञ्जिकसम्पिष्टः स्निग्धो मधुकचन्दनैः दूर्वा च नलमूलञ्च पद्मकाष्ठञ्च केशरम् उशीरं बालकं पद्मं लेपोऽय पित्तशोथहा","text":"kalkaḥ kāñjikasampiṣṭaḥ snigdho madhukacandanaiḥ dūrvā ca nalamūlañca padmakāṣṭhañca keśaram uśīraṃ bālakaṃ padmaṃ lepo'ya pittaśothahā"},{"type":"verse","number":"22","sanskrit":"न्यग्रोधोदुम्बराश्वत्थप्लक्षवेतसकल्कलैः ससर्पिष्कैः प्रदेहः स्याच्छोथे पित्तसमुद्भवे","text":"nyagrodhodumbarāśvatthaplakṣavetasakalkalaiḥ sasarpiṣkaiḥ pradehaḥ syācchothe pittasamudbhave"},{"type":"verse","number":"23","sanskrit":"आगन्तुजे रक्तजे च लेप एषोऽभिपूजितः","text":"āgantuje raktaje ca lepa eṣo'bhipūjitaḥ"},{"type":"verse","number":"24","sanskrit":"अजगन्धाऽजशृंगी च मञ्जिष्ठा सरलस्तथा एकैषिकाऽश्वगन्धा च लेपोऽयश्लेष्मशोथहा","text":"ajagandhā'jaśṛṃgī ca mañjiṣṭhā saralastathā ekaiṣikā'śvagandhā ca lepo'yaśleṣmaśothahā"},{"type":"verse","number":"25","sanskrit":"कृष्णापुराणपिण्याकं शिग्रुत्वक् सिकता शिवा मूत्रपिष्टः सुखोष्णोऽय प्रलेपः श्लेष्मशोथहा","text":"kṛṣṇāpurāṇapiṇyākaṃ śigrutvak sikatā śivā mūtrapiṣṭaḥ sukhoṣṇo'ya pralepaḥ śleṣmaśothahā"},{"type":"verse","number":"26","sanskrit":"न रात्रौ लेपनं दद्याद्दत्तञ्च पतितं तथा न च पर्युषितं शुष्यमाणं तन्नैव धारयेत्","text":"na rātrau lepanaṃ dadyāddattañca patitaṃ tathā na ca paryuṣitaṃ śuṣyamāṇaṃ tannaiva dhārayet"},{"type":"verse","number":"27","sanskrit":"तमसा पिहितोऽत्युष्मा रोमकूपमुखोत्थितः विना लेपेन निर्याति रात्रौ नालेपयेदतः","text":"tamasā pihito'tyuṣmā romakūpamukhotthitaḥ vinā lepena niryāti rātrau nālepayedataḥ"},{"type":"verse","number":"28","sanskrit":"रात्रावपि प्रलेपस्तुविधातव्योविचक्षणैः अपाकिशोथे गम्भीरे रक्तपित्तसमुद्भवे","text":"rātrāvapi pralepastuvidhātavyovicakṣaṇaiḥ apākiśothe gambhīre raktapittasamudbhave"},{"type":"verse","number":"29","sanskrit":"यथाऽम्बुभिः सिच्यमानःशान्तिमग्निर्हि गच्छति दोषाग्निरेवं सहसा परिषेकेण शाम्यति","text":"yathā'mbubhiḥ sicyamānaḥśāntimagnirhi gacchati doṣāgnirevaṃ sahasā pariṣekeṇa śāmyati"},{"type":"verse","number":"30","sanskrit":"वातघ्नौषधनिष्क्वाथै स्तैलैर्मांसरसैर्घृतैः उष्णैः संसेचयेच्छोथं वातिकं काञ्जिकेन च","text":"vātaghnauṣadhaniṣkvāthai stailairmāṃsarasairghṛtaiḥ uṣṇaiḥ saṃsecayecchothaṃ vātikaṃ kāñjikena ca"},{"type":"verse","number":"31","sanskrit":"पित्तरक्ताभिघातोत्थं शोथं सिञ्चेत्सुशीतलैः क्षीराज्यमधुखण्डेक्षुरसैःपित्तहरैःशृतैः","text":"pittaraktābhighātotthaṃ śothaṃ siñcetsuśītalaiḥ kṣīrājyamadhukhaṇḍekṣurasaiḥpittaharaiḥśṛtaiḥ"},{"type":"verse","number":"32","sanskrit":"कफघ्नौषधनिष्क्वाथैः शीतैस्तु परिषेचयेत् तैलक्षाराम्बुमूत्रैश्च शोथं श्लेष्मसमुद्भवम्","text":"kaphaghnauṣadhaniṣkvāthaiḥ śītaistu pariṣecayet tailakṣārāmbumūtraiśca śothaṃ śleṣmasamudbhavam"},{"type":"verse","number":"33","sanskrit":"जातस्य कठिनस्यास्य कार्यं विम्लापनं शनैः","text":"jātasya kaṭhinasyāsya kāryaṃ vimlāpanaṃ śanaiḥ"},{"type":"verse","number":"34","sanskrit":"अभ्यज्य स्वेदयित्वा तु वेणुनाढ्या शनैः शनैः विमर्दयेद्भिषङ् मन्दं तलेनाङ्गुष्ठकेन वा","text":"abhyajya svedayitvā tu veṇunāḍhyā śanaiḥ śanaiḥ vimardayedbhiṣaṅ mandaṃ talenāṅguṣṭhakena vā"},{"type":"verse","number":"35","sanskrit":"वेदनोपशमार्थाय तथा पाकशमाय च अचिरोत्पतिते शोथे शोणितस्रावणं चरेत्","text":"vedanopaśamārthāya tathā pākaśamāya ca acirotpatite śothe śoṇitasrāvaṇaṃ caret"},{"type":"verse","number":"36","sanskrit":"एकतस्तु क्रियाः सर्वा रक्तमोक्षणमेकतः रक्तं हि वेदनामूलं तच्चेन्नास्ति न चास्ति रुक्","text":"ekatastu kriyāḥ sarvā raktamokṣaṇamekataḥ raktaṃ hi vedanāmūlaṃ taccennāsti na cāsti ruk"},{"type":"verse","number":"37","sanskrit":"विवर्णःकठिनः श्यावो व्रणोयश्चाल्पवेदनः विषाणैश्च विशेषेण जलौकाभिः पदैरपि","text":"vivarṇaḥkaṭhinaḥ śyāvo vraṇoyaścālpavedanaḥ viṣāṇaiśca viśeṣeṇa jalaukābhiḥ padairapi"},{"type":"verse","number":"38","sanskrit":"रुजावतां दारुणानां कठिनानां तथैव च शोथानां स्वेदनं कार्यं ये चाप्येवंविधा व्रणाः","text":"rujāvatāṃ dāruṇānāṃ kaṭhinānāṃ tathaiva ca śothānāṃ svedanaṃ kāryaṃ ye cāpyevaṃvidhā vraṇāḥ"},{"type":"verse","number":"39","sanskrit":"शोथयोरुपनाहञ्च दद्यादामविदग्धयोः प्रशाम्यत्यविदग्धस्तु विदग्धः पक्वतां व्रजेत्","text":"śothayorupanāhañca dadyādāmavidagdhayoḥ praśāmyatyavidagdhastu vidagdhaḥ pakvatāṃ vrajet"},{"type":"verse","number":"40","sanskrit":"दशमूली बला रास्ना वाजिगन्धा प्रसारिणी मूलं वातरिपोः सिन्धुर्वारिपूर्णे घटे क्षिपेत्","text":"daśamūlī balā rāsnā vājigandhā prasāriṇī mūlaṃ vātaripoḥ sindhurvāripūrṇe ghaṭe kṣipet"},{"type":"verse","number":"41","sanskrit":"शोभाञ्जनः कणा चापि सैन्धवं विश्वभेषजम् शणकार्पासयोर्बीजमतसी च कुलत्थिका","text":"śobhāñjanaḥ kaṇā cāpi saindhavaṃ viśvabheṣajam śaṇakārpāsayorbījamatasī ca kulatthikā"},{"type":"verse","number":"42","sanskrit":"तिला यवाश्च सिद्धार्थः कुठेरो मूलकं मिसिः यथाप्राप्तैरमीभिश्च द्र व्यैरम्लेन संयुतैः","text":"tilā yavāśca siddhārthaḥ kuṭhero mūlakaṃ misiḥ yathāprāptairamībhiśca dra vyairamlena saṃyutaiḥ"},{"type":"verse","number":"43","sanskrit":"कल्कीकृतैः सुखोष्णैश्च स्वेदयेद्विधिवच्छनैः अनेन प्रशमं याति वातशोथो न संशयः","text":"kalkīkṛtaiḥ sukhoṣṇaiśca svedayedvidhivacchanaiḥ anena praśamaṃ yāti vātaśotho na saṃśayaḥ"},{"type":"verse","number":"44","sanskrit":"पुनर्नवा दारु शुण्ठी शिग्रुः सिद्धार्थ एव च अम्लपिष्टः सुखोष्णोऽय प्रलेपः सर्वशोथहा","text":"punarnavā dāru śuṇṭhī śigruḥ siddhārtha eva ca amlapiṣṭaḥ sukhoṣṇo'ya pralepaḥ sarvaśothahā"},{"type":"verse","number":"45","sanskrit":"न प्रशाम्यति यः शोथः प्रलेपादिविधानतः द्र व्याणि पाचनीयानि दद्यात्तत्रोपनाहने","text":"na praśāmyati yaḥ śothaḥ pralepādividhānataḥ dra vyāṇi pācanīyāni dadyāttatropanāhane"},{"type":"verse","number":"46","sanskrit":"शणमूलकशिग्रुणां फलानि तिलसर्षपाः अतसी शक्तवः किण्वमुष्णद्र व्यञ्च पाचनम्","text":"śaṇamūlakaśigruṇāṃ phalāni tilasarṣapāḥ atasī śaktavaḥ kiṇvamuṣṇadra vyañca pācanam"},{"type":"verse","number":"47","sanskrit":"अन्तः पूयेष्ववक्त्रेषु तथा चोत्सङ्गवत्स्वपि गतिमत्सु च रोगेषु भेदनं सम्प्रयुज्यते","text":"antaḥ pūyeṣvavaktreṣu tathā cotsaṅgavatsvapi gatimatsu ca rogeṣu bhedanaṃ samprayujyate"},{"type":"verse","number":"48","sanskrit":"रोगे व्यधेन साध्येतु यथादेशं प्रमाणतः शस्त्रं विधाय दोषांस्तु स्रावयेत्कथितं यथा","text":"roge vyadhena sādhyetu yathādeśaṃ pramāṇataḥ śastraṃ vidhāya doṣāṃstu srāvayetkathitaṃ yathā"},{"type":"verse","number":"49","sanskrit":"बालवृद्धासहक्षीणभीरूणां योषितामपि व्रणेषु मर्मजातेषु भेदनं द्र व्यलेपनम्","text":"bālavṛddhāsahakṣīṇabhīrūṇāṃ yoṣitāmapi vraṇeṣu marmajāteṣu bhedanaṃ dra vyalepanam"},{"type":"verse","number":"50","sanskrit":"चिरबिल्वोऽग्निको दन्ती चित्रको हयमारकः कपोतकाकगृध्राणां मललेपेन भेदनम्","text":"cirabilvo'gniko dantī citrako hayamārakaḥ kapotakākagṛdhrāṇāṃ malalepena bhedanam"},{"type":"verse","number":"51","sanskrit":"क्षारद्र व्यं तथा क्षारो दारणः परिकीर्तितः हस्तिदन्तो जले पिष्टो बिन्दुमात्रप्रलेपितः अत्यर्थं कठिने शोथे कथितो भेदनः परः","text":"kṣāradra vyaṃ tathā kṣāro dāraṇaḥ parikīrtitaḥ hastidanto jale piṣṭo bindumātrapralepitaḥ atyarthaṃ kaṭhine śothe kathito bhedanaḥ paraḥ"},{"type":"verse","number":"52","sanskrit":"द्र व्याणां पिच्छिलानान्तु त्वङ्मूलातिप्रपीडनम् यवगोधूममाषाणां चूर्णानि च समासतः","text":"dra vyāṇāṃ picchilānāntu tvaṅmūlātiprapīḍanam yavagodhūmamāṣāṇāṃ cūrṇāni ca samāsataḥ"},{"type":"verse","number":"53","sanskrit":"शुष्यमाणमुपेक्षेत प्रलेपं पीडनं प्रति न चापिमुखमालिम्पेत्तथा दोषः प्रसिच्यते","text":"śuṣyamāṇamupekṣeta pralepaṃ pīḍanaṃ prati na cāpimukhamālimpettathā doṣaḥ prasicyate"},{"type":"verse","number":"54","sanskrit":"व्रणस्य तु विशुद्धस्य क्वाथः शुद्धिकरः परः पटोलनिम्बपत्रोत्थः सर्वत्रैव प्रयुज्यते","text":"vraṇasya tu viśuddhasya kvāthaḥ śuddhikaraḥ paraḥ paṭolanimbapatrotthaḥ sarvatraiva prayujyate"},{"type":"verse","number":"55","sanskrit":"वातिके दशमूलानां क्षीरिणां पैत्तिके व्रणे आरग्वधादेः कफजे कषायः शोधने हितः","text":"vātike daśamūlānāṃ kṣīriṇāṃ paittike vraṇe āragvadhādeḥ kaphaje kaṣāyaḥ śodhane hitaḥ"},{"type":"verse","number":"56","sanskrit":"अश्वत्थोदुम्बरप्लक्षवटवेतसजं शृतम् व्रणशोथोपदंशानां नाशनं क्षालनात्स्मृतम्","text":"aśvatthodumbaraplakṣavaṭavetasajaṃ śṛtam vraṇaśothopadaṃśānāṃ nāśanaṃ kṣālanātsmṛtam"},{"type":"verse","number":"57","sanskrit":"तिलसैन्धवयष्ट्याह्वनिम्बपत्रनिशायुगैः त्रिवृद्घृतयुतैः पिष्टैः प्रलेपो व्रणशोधनः","text":"tilasaindhavayaṣṭyāhvanimbapatraniśāyugaiḥ trivṛdghṛtayutaiḥ piṣṭaiḥ pralepo vraṇaśodhanaḥ"},{"type":"verse","number":"58","sanskrit":"एकं वा सारिवामूलं सर्वव्रणविशोधनम्","text":"ekaṃ vā sārivāmūlaṃ sarvavraṇaviśodhanam"},{"type":"verse","number":"59","sanskrit":"निम्बपत्रं तिला दन्ती त्रिवृत्सैन्धवमाक्षिकम् दुष्टव्रणप्रशमनो लेपः शोधनकेशरी","text":"nimbapatraṃ tilā dantī trivṛtsaindhavamākṣikam duṣṭavraṇapraśamano lepaḥ śodhanakeśarī"},{"type":"verse","number":"60","sanskrit":"लेपान्निम्बदलैः कल्को व्रणशोधनरोपणः भक्षणाच्छर्दिमन्दाग्निपित्तश्लेष्मकृमीन्हरेत् व्रणान्विशोधयेद्वत्तर्या सूक्ष्मान् हि सन्धिमर्मजान्","text":"lepānnimbadalaiḥ kalko vraṇaśodhanaropaṇaḥ bhakṣaṇācchardimandāgnipittaśleṣmakṛmīnharet vraṇānviśodhayedvattaryā sūkṣmān hi sandhimarmajān"},{"type":"verse","number":"61","sanskrit":"अभयात्रिवृतादन्ती लाङ्गलीमधुसैन्धवैः","text":"abhayātrivṛtādantī lāṅgalīmadhusaindhavaiḥ"},{"type":"verse","number":"62","sanskrit":"निम्बपत्रघृत क्षौद्र दार्वीमधुकसंयुतैः वर्त्तिस्तिलानां कल्को वा शोधयेद्रो पयेद् व्रणम्","text":"nimbapatraghṛta kṣaudra dārvīmadhukasaṃyutaiḥ varttistilānāṃ kalko vā śodhayedro payed vraṇam"},{"type":"verse","number":"63","sanskrit":"अपेतपूतिमांसानां मांसस्थानामरोहताम् कल्कस्तु रोपणोदेयस्तिलजो मधुसंयुतः","text":"apetapūtimāṃsānāṃ māṃsasthānāmarohatām kalkastu ropaṇodeyastilajo madhusaṃyutaḥ"},{"type":"verse","number":"64","sanskrit":"अश्वगन्धा रुहा लोध्रं कट्फलं मधुयष्टिका समङ्गा धातकीपुष्पं परमं व्रणरोपणम्","text":"aśvagandhā ruhā lodhraṃ kaṭphalaṃ madhuyaṣṭikā samaṅgā dhātakīpuṣpaṃ paramaṃ vraṇaropaṇam"},{"type":"verse","number":"65","sanskrit":"मधुयुक्ता सुरा पुंसां कथिता व्रणरोपणी सुषवीपत्रधत्तूर बलामोटाकुठेरकाः पृथगेतैः प्रलेपेन गम्भीरव्रणरोपणम्","text":"madhuyuktā surā puṃsāṃ kathitā vraṇaropaṇī suṣavīpatradhattūra balāmoṭākuṭherakāḥ pṛthagetaiḥ pralepena gambhīravraṇaropaṇam"},{"type":"verse","number":"66","sanskrit":"ककुभोदुम्बराश्वत्थजम्बू कफललोध्रजैः त्वक्चूर्णैर्धूलिताः क्षिप्रं संरोहन्ति व्रणा ध्रुवम्","text":"kakubhodumbarāśvatthajambū kaphalalodhrajaiḥ tvakcūrṇairdhūlitāḥ kṣipraṃ saṃrohanti vraṇā dhruvam"},{"type":"verse","number":"67","sanskrit":"प्रियङ्गुधातकीपुष्पं यष्टीमधुजतूनि च सूक्ष्मचूर्णीकृतानि स्यू रोपणान्यवधूलनात्","text":"priyaṅgudhātakīpuṣpaṃ yaṣṭīmadhujatūni ca sūkṣmacūrṇīkṛtāni syū ropaṇānyavadhūlanāt"},{"type":"verse","number":"68","sanskrit":"यवचूर्णं समधुकं सतैलं सह सर्पिषा दद्यादालेपनं कोष्णं दाहशूलोपशान्तये","text":"yavacūrṇaṃ samadhukaṃ satailaṃ saha sarpiṣā dadyādālepanaṃ koṣṇaṃ dāhaśūlopaśāntaye"},{"type":"verse","number":"69","sanskrit":"करञ्जारिष्टनिर्गुण्डीलेपो हन्याद् व्रणकृमीन् लशुनस्याथवा लेपो हिङ्गुनिम्बकृतोऽथवा","text":"karañjāriṣṭanirguṇḍīlepo hanyād vraṇakṛmīn laśunasyāthavā lepo hiṅgunimbakṛto'thavā"},{"type":"verse","number":"70","sanskrit":"निम्बपत्रवचाहिङ्गुसर्पिर्लवणसर्षपैः धूपनं स्याद् व्रणे रुक्षकृमिकण्डूरुजाऽपहम्","text":"nimbapatravacāhiṅgusarpirlavaṇasarṣapaiḥ dhūpanaṃ syād vraṇe rukṣakṛmikaṇḍūrujā'paham"},{"type":"verse","number":"71","sanskrit":"ये क्लेदपाकस्रुतिगन्धवन्तो व्रणाश्चिरोत्थाः सतताश्च शोथाः प्रयान्ति ये गुग्गुलुमिश्रितेन पीतेन शान्तिं त्रिफलाशृतेन","text":"ye kledapākasrutigandhavanto vraṇāścirotthāḥ satatāśca śothāḥ prayānti ye guggulumiśritena pītena śāntiṃ triphalāśṛtena"},{"type":"verse","number":"72","sanskrit":"पटोलनिम्बासनसार धात्रीपथ्याऽक्षनिर्यूहमहर्मुखेषु पिबेद्युतं गुग्गुलुना विसर्पविस्फोट दुष्टव्रणशान्तिमिच्छन्","text":"paṭolanimbāsanasāra dhātrīpathyā'kṣaniryūhamaharmukheṣu pibedyutaṃ guggulunā visarpavisphoṭa duṣṭavraṇaśāntimicchan"},{"type":"verse","number":"73","sanskrit":"मनःशिला समञ्जिष्ठा सलाक्षा रजनीद्वयम् प्रलेपः सघृतक्षौद्र स्त्वचः सावर्ण्यकृत्स्मृतः","text":"manaḥśilā samañjiṣṭhā salākṣā rajanīdvayam pralepaḥ saghṛtakṣaudra stvacaḥ sāvarṇyakṛtsmṛtaḥ"},{"type":"verse","number":"74","sanskrit":"जीर्णशाल्योदनं स्निग्धमल्पमुष्णं द्र वान्तरम् भुञ्जानो जाङ्गलैर्मांसैः शीघ्रं व्रणमपोहति","text":"jīrṇaśālyodanaṃ snigdhamalpamuṣṇaṃ dra vāntaram bhuñjāno jāṅgalairmāṃsaiḥ śīghraṃ vraṇamapohati"},{"type":"verse","number":"75","sanskrit":"तण्डुलीयकजीवन्तीवास्तूकसुनिषण्णकैः बालमूलकवार्त्ताकुपटोलैः कारवेल्लकैः","text":"taṇḍulīyakajīvantīvāstūkasuniṣaṇṇakaiḥ bālamūlakavārttākupaṭolaiḥ kāravellakaiḥ"},{"type":"verse","number":"76","sanskrit":"सदाडिमैः सामलकैर्घृतभृष्टैः ससैन्धवैः अन्यैरेवङ्गुणैर्वाऽपि मुद्गादीनां रसेन वा","text":"sadāḍimaiḥ sāmalakairghṛtabhṛṣṭaiḥ sasaindhavaiḥ anyairevaṅguṇairvā'pi mudgādīnāṃ rasena vā"},{"type":"verse","number":"77","sanskrit":"अम्लं दधि च शाकञ्च मांसमानूपमौदकम् क्षीरं गुरूणि चान्नानि व्रणे च परिवर्जयेत्","text":"amlaṃ dadhi ca śākañca māṃsamānūpamaudakam kṣīraṃ gurūṇi cānnāni vraṇe ca parivarjayet"},{"type":"verse","number":"78","sanskrit":"व्रणे श्वयथुरायासात्स च रागश्च जागरात् तौ च रुक्च दिवास्वापात्ते च मृत्युश्च मैथुनात्","text":"vraṇe śvayathurāyāsātsa ca rāgaśca jāgarāt tau ca rukca divāsvāpātte ca mṛtyuśca maithunāt"},{"type":"verse","number":"79","sanskrit":"क्रुद्धे सद्योव्रणे कुर्यादूर्ध्वं चाधश्च शोधनम् क्रिया शीता प्रयोक्तव्या रक्तपित्तोष्मनाशिनी","text":"kruddhe sadyovraṇe kuryādūrdhvaṃ cādhaśca śodhanam kriyā śītā prayoktavyā raktapittoṣmanāśinī"},{"type":"verse","number":"80","sanskrit":"लङ्घनञ्च बलं ज्ञात्वा भोजनं चास्रमोक्षणम् घृष्टे विदलिते चैव सुतरामिष्यते विधिः","text":"laṅghanañca balaṃ jñātvā bhojanaṃ cāsramokṣaṇam ghṛṣṭe vidalite caiva sutarāmiṣyate vidhiḥ"},{"type":"verse","number":"81","sanskrit":"छिन्ने भिन्ने तथा विद्धे क्षते वाऽसृगतिस्रवेत् रक्तक्षयात्तत्र रुजः करोति पवनो भृशम्","text":"chinne bhinne tathā viddhe kṣate vā'sṛgatisravet raktakṣayāttatra rujaḥ karoti pavano bhṛśam"},{"type":"verse","number":"82","sanskrit":"परिषेकं स्नेहपानं लेपं तत्रोपनाहनम् कुर्वन्ति स्नेहवस्तिञ्च रुजाघ्नं चौषधं पृथक्","text":"pariṣekaṃ snehapānaṃ lepaṃ tatropanāhanam kurvanti snehavastiñca rujāghnaṃ cauṣadhaṃ pṛthak"},{"type":"verse","number":"83","sanskrit":"खड्गादिच्छिन्नगात्रस्य तत्काले पूरितो व्रणः गाङ्गेरुकीमूलरसैः सद्यः स्याद्गतवेदनः","text":"khaḍgādicchinnagātrasya tatkāle pūrito vraṇaḥ gāṅgerukīmūlarasaiḥ sadyaḥ syādgatavedanaḥ"},{"type":"verse","number":"84","sanskrit":"कषाया मधुराः शीताः क्रियाः सर्वाः प्रयोजयेत् सद्योव्रणानां सप्ताहात्पश्चात्पूर्वोक्तमाचरेत्","text":"kaṣāyā madhurāḥ śītāḥ kriyāḥ sarvāḥ prayojayet sadyovraṇānāṃ saptāhātpaścātpūrvoktamācaret"},{"type":"verse","number":"85","sanskrit":"आमाशयस्थे रुधिरे विदध्याद्वमनं नरः तस्मिन्पक्वाशयस्थे तु प्रकुर्वीत विरेचनम्","text":"āmāśayasthe rudhire vidadhyādvamanaṃ naraḥ tasminpakvāśayasthe tu prakurvīta virecanam"},{"type":"verse","number":"86","sanskrit":"क्वाथो वंशत्वगैरण्डश्वदंष्ट्राऽश्मभिदा कृतः हिङ्गुसैन्धवसंयुक्तः कोष्ठस्थं स्रावयेदसृक्","text":"kvātho vaṃśatvagairaṇḍaśvadaṃṣṭrā'śmabhidā kṛtaḥ hiṅgusaindhavasaṃyuktaḥ koṣṭhasthaṃ srāvayedasṛk"},{"type":"verse","number":"87","sanskrit":"यवकोलकुलत्थानां निःस्नेहेन रसेन च भुञ्जीतान्नं यवागूं वा पिबेत्सैन्धवसंयुताम्","text":"yavakolakulatthānāṃ niḥsnehena rasena ca bhuñjītānnaṃ yavāgūṃ vā pibetsaindhavasaṃyutām"},{"type":"verse","number":"88","sanskrit":"जातीनिम्बपटोलपत्रकटुकादार्वीनिशासारिवा मञ्जिष्ठाऽभयसिक्थ तुत्थमधुकैर्नक्ताह्वबीजं समैः सर्पिः सिद्धमनेन सूक्ष्मवदना मर्माश्रिताः स्राविणो गम्भीराः सरुजो व्रणाः सगतिकाः शुध्यन्ति रोहन्ति च","text":"jātīnimbapaṭolapatrakaṭukādārvīniśāsārivā mañjiṣṭhā'bhayasiktha tutthamadhukairnaktāhvabījaṃ samaiḥ sarpiḥ siddhamanena sūkṣmavadanā marmāśritāḥ srāviṇo gambhīrāḥ sarujo vraṇāḥ sagatikāḥ śudhyanti rohanti ca"},{"type":"verse","number":"89","sanskrit":"वृद्धवैद्योपदेशेन पारम्पर्योपदेशतः जातीवृते तु संसिद्धं क्षेप्तव्यं सिक्थकं बुधैः","text":"vṛddhavaidyopadeśena pāramparyopadeśataḥ jātīvṛte tu saṃsiddhaṃ kṣeptavyaṃ sikthakaṃ budhaiḥ"},{"type":"verse","number":"90","sanskrit":"जातीनिम्बपटोलानां नक्तमालस्य पल्लवाः सिक्थकं मधुकं कुष्ठं द्वे निशे कटुरोहिणी","text":"jātīnimbapaṭolānāṃ naktamālasya pallavāḥ sikthakaṃ madhukaṃ kuṣṭhaṃ dve niśe kaṭurohiṇī"},{"type":"verse","number":"91","sanskrit":"मञ्जिष्ठा पद्मकं पथ्या लोध्रत्वङ्नीलमुत्पलम् सारिवा तुत्थकञ्चापि नक्तमालफलं तथा एतानि समभागानि कल्कीकृत्य प्रयत्नतः तिलतैलं पचेत्सम्यग्वैद्यः पाकविचक्षणः","text":"mañjiṣṭhā padmakaṃ pathyā lodhratvaṅnīlamutpalam sārivā tutthakañcāpi naktamālaphalaṃ tathā etāni samabhāgāni kalkīkṛtya prayatnataḥ tilatailaṃ pacetsamyagvaidyaḥ pākavicakṣaṇaḥ"},{"type":"verse","number":"92","sanskrit":"विषव्रणे समुत्पन्ने स्फोटके कुष्ठरोगिणी दद्रुवीसर्परोगेषुकीटदष्टेषु सर्वथा","text":"viṣavraṇe samutpanne sphoṭake kuṣṭharogiṇī dadruvīsarparogeṣukīṭadaṣṭeṣu sarvathā"},{"type":"verse","number":"93","sanskrit":"सद्यः शस्त्रप्रहारेण दग्धविद्धेषु चैव हि नखदन्तक्षते देहे दुष्टमांसापकर्षणे","text":"sadyaḥ śastraprahāreṇa dagdhaviddheṣu caiva hi nakhadantakṣate dehe duṣṭamāṃsāpakarṣaṇe"},{"type":"verse","number":"94","sanskrit":"म्रक्षणेन हितं तैलमिदं शोधनरोपणम् तैलं जात्यादिनाम्नैतत्प्रसिद्धं भिषगादृतम्","text":"mrakṣaṇena hitaṃ tailamidaṃ śodhanaropaṇam tailaṃ jātyādināmnaitatprasiddhaṃ bhiṣagādṛtam"},{"type":"verse","number":"95","sanskrit":"चित्रकरसोनरामठशरपुङ्खालाङ्गलीकसिन्दूरैः सविषैस्तथा सकुष्ठैः कटुतैलं साधु सम्पक्वम्","text":"citrakarasonarāmaṭhaśarapuṅkhālāṅgalīkasindūraiḥ saviṣaistathā sakuṣṭhaiḥ kaṭutailaṃ sādhu sampakvam"},{"type":"verse","number":"96","sanskrit":"विपरीतमल्लसंज्ञं तैलं दुष्टव्रणं तथा नाडीम् बहुभेषजैरसाध्यामपथ्यभोक्तुश्च निस्तुदति","text":"viparītamallasaṃjñaṃ tailaṃ duṣṭavraṇaṃ tathā nāḍīm bahubheṣajairasādhyāmapathyabhoktuśca nistudati"},{"type":"verse","number":"97","sanskrit":"अमृतापटोलमूलत्रिफलात्रिकटुककृमिघ्नानाम् समभागानां चूर्णं सर्वसमो गुग्गुलोर्भागः","text":"amṛtāpaṭolamūlatriphalātrikaṭukakṛmighnānām samabhāgānāṃ cūrṇaṃ sarvasamo guggulorbhāgaḥ"},{"type":"verse","number":"98","sanskrit":"प्रतिवासरमेकैकां गुटिकां खादेदिहापि परिमाणम् जेतुं व्रणवातासृग्गुल्मोदरशोथवातरोगांश्च","text":"prativāsaramekaikāṃ guṭikāṃ khādedihāpi parimāṇam jetuṃ vraṇavātāsṛggulmodaraśothavātarogāṃśca"},{"type":"verse","number":"99","sanskrit":"प्लुष्टस्याग्निषु तपनं कार्यमुष्णं तथौषधम् सम्यक् स्विन्ने शरीरे तु स्विन्नं भवति शोभनम्","text":"pluṣṭasyāgniṣu tapanaṃ kāryamuṣṇaṃ tathauṣadham samyak svinne śarīre tu svinnaṃ bhavati śobhanam"},{"type":"verse","number":"100","sanskrit":"प्रकृत्या सलिलं शीतं स्कन्दयत्यतिशोणितम् तस्मात्सुखयति ह्युष्णं न तु शीतं कदाचन","text":"prakṛtyā salilaṃ śītaṃ skandayatyatiśoṇitam tasmātsukhayati hyuṣṇaṃ na tu śītaṃ kadācana"},{"type":"verse","number":"101","sanskrit":"शीतामुष्णाञ्च दुर्दग्धे क्रियां कुर्यात्ततः पुनः घृतलेपप्रदेहांश्च शीतानेवास्य कारयेत्","text":"śītāmuṣṇāñca durdagdhe kriyāṃ kuryāttataḥ punaḥ ghṛtalepapradehāṃśca śītānevāsya kārayet"},{"type":"verse","number":"102","sanskrit":"सम्यदग्धे तुगाक्षीरीप्लक्षचन्दनगैरिकैः सामृतैः सर्पिषा युक्तैरालेपं कारयेद्भिषक् ग्राम्यानूपौदकैर्मांसैः पिष्टैरेनं प्रलेपयेत्","text":"samyadagdhe tugākṣīrīplakṣacandanagairikaiḥ sāmṛtaiḥ sarpiṣā yuktairālepaṃ kārayedbhiṣak grāmyānūpaudakairmāṃsaiḥ piṣṭairenaṃ pralepayet"},{"type":"verse","number":"103","sanskrit":"अतिदग्धे विशीर्णानि मांसान्युद्धृत्य शीतलाम् क्रियां कुर्यात्ततः पश्चाच्छालितण्डुलकण्डनैः","text":"atidagdhe viśīrṇāni māṃsānyuddhṛtya śītalām kriyāṃ kuryāttataḥ paścācchālitaṇḍulakaṇḍanaiḥ"},{"type":"verse","number":"104","sanskrit":"तिन्दुक्याश्च कषायैर्वा घृतमिश्रैर्प्रलेपयेत् सर्वेषामग्निदग्धानामेतद्रो पणमुत्तमम्","text":"tindukyāśca kaṣāyairvā ghṛtamiśrairpralepayet sarveṣāmagnidagdhānāmetadro paṇamuttamam"},{"type":"verse","number":"105","sanskrit":"सिक्थककर्दमजीरकमधुपथ्यासर्वमिश्रितं लेपात् गव्यं घृतमपहरति विपाकजनितं व्रणं सद्यः","text":"sikthakakardamajīrakamadhupathyāsarvamiśritaṃ lepāt gavyaṃ ghṛtamapaharati vipākajanitaṃ vraṇaṃ sadyaḥ"},{"type":"verse","number":"106","sanskrit":"सिद्धं कषायकल्काभ्यां पटोल्याः कटुतैलकम् दग्धव्रणरुजास्रावदाहविस्फोटनाशनम्","text":"siddhaṃ kaṣāyakalkābhyāṃ paṭolyāḥ kaṭutailakam dagdhavraṇarujāsrāvadāhavisphoṭanāśanam"},{"type":"verse","number":"107","sanskrit":"वातास्रमस्रतं दुष्टं सशोथं ग्रथितं व्रणम् कुर्यात्सदाहंकण्ड्वाद्यं व्रणग्रन्थिस्तु स स्मृतः","text":"vātāsramasrataṃ duṣṭaṃ saśothaṃ grathitaṃ vraṇam kuryātsadāhaṃkaṇḍvādyaṃ vraṇagranthistu sa smṛtaḥ"},{"type":"verse","number":"108","sanskrit":"कम्पिल्लकं विडङ्गानि त्वचं दार्व्यास्तथैव च पिष्ट्वा तैलं पचेत्तत्तु व्रणग्रन्थिहरं परम्","text":"kampillakaṃ viḍaṅgāni tvacaṃ dārvyāstathaiva ca piṣṭvā tailaṃ pacettattu vraṇagranthiharaṃ param"},{"type":"verse","number":"109","sanskrit":"इति सप्तचत्वारिंशत्तमो व्रणशोथाधिकारो वा व्रणशोथा गन्तुव्रणाग्निदग्धव्रणाधिकारः समाप्तः ४७","text":"iti saptacatvāriṃśattamo vraṇaśothādhikāro vā vraṇaśothā gantuvraṇāgnidagdhavraṇādhikāraḥ samāptaḥ 47"}]},{"sthana":"Уттаракханда","number":48,"lang":"sa","content":[{"type":"heading","heading":"Бхагна — переломы"},{"type":"verse","number":"1","sanskrit":"भग्नं समासाद् द्विविधं हुताश काण्डे च सन्धावपि तत्र सन्धौ उत्पिष्टविश्लिष्टविवर्त्तितानि तिर्यग्गतं क्षिप्तमधश्च भग्नम्","text":"bhagnaṃ samāsād dvividhaṃ hutāśa kāṇḍe ca sandhāvapi tatra sandhau utpiṣṭaviśliṣṭavivarttitāni tiryaggataṃ kṣiptamadhaśca bhagnam"},{"type":"verse","number":"2","sanskrit":"प्रसारणाकुञ्चनवर्त्तनोग्रा रुक् स्पर्शविद्वेषणमेतदुक्तम् सामान्यतः सन्धिगतस्य लिङ्गमुत्पिष्टसन्धेः श्वयथोः समन्तात् विशेषतो रात्रिभवा रुजा च विश्लिष्टकेतौ च रुजा च नित्यम्","text":"prasāraṇākuñcanavarttanogrā ruk sparśavidveṣaṇametaduktam sāmānyataḥ sandhigatasya liṅgamutpiṣṭasandheḥ śvayathoḥ samantāt viśeṣato rātribhavā rujā ca viśliṣṭaketau ca rujā ca nityam"},{"type":"verse","number":"3","sanskrit":"विवर्त्तिते पार्श्वरुजश्च तीव्रास्तिर्यग्गते तीव्ररुजो भवन्ति क्षिप्तेऽतिशूलं विगमं रुजश्च क्षिप्ते त्वधोरुग्विघटश्च सन्धेः","text":"vivarttite pārśvarujaśca tīvrāstiryaggate tīvrarujo bhavanti kṣipte'tiśūlaṃ vigamaṃ rujaśca kṣipte tvadhorugvighaṭaśca sandheḥ"},{"type":"verse","number":"4","sanskrit":"भग्नन्तु काण्डे बहुधा प्रयाति विशेषतो नामभिरेव तुल्यम्","text":"bhagnantu kāṇḍe bahudhā prayāti viśeṣato nāmabhireva tulyam"},{"type":"verse","number":"5","sanskrit":"काण्डे त्वतः कर्कटकाश्वकर्णौ विचूर्णितं पिच्चितमस्थिखल्लितम् काण्डेषु भग्नं ह्यतिपातितञ्च मज्जागतं विस्फुटितञ्च वक्रम्","text":"kāṇḍe tvataḥ karkaṭakāśvakarṇau vicūrṇitaṃ piccitamasthikhallitam kāṇḍeṣu bhagnaṃ hyatipātitañca majjāgataṃ visphuṭitañca vakram"},{"type":"verse","number":"6","sanskrit":"छिन्नं द्विधा द्वादशधाऽपि काण्डे सामान्यमग्रे किल तस्य लिङ्गम्","text":"chinnaṃ dvidhā dvādaśadhā'pi kāṇḍe sāmānyamagre kila tasya liṅgam"},{"type":"verse","number":"7","sanskrit":"स्रस्ताङ्गता शोथरुजाऽतिवृद्धिस्तथा व्यथावृद्धिरतीव नित्यम् सम्पीड्यमाने भवतीह शब्दः स्पर्शासहं स्पन्दनतोदशूलाः सर्वास्ववस्थासु न शर्मलाभो भग्नस्य काण्डे खलु चिह्नमेतत्","text":"srastāṅgatā śotharujā'tivṛddhistathā vyathāvṛddhiratīva nityam sampīḍyamāne bhavatīha śabdaḥ sparśāsahaṃ spandanatodaśūlāḥ sarvāsvavasthāsu na śarmalābho bhagnasya kāṇḍe khalu cihnametat"},{"type":"verse","number":"8","sanskrit":"अल्पाशिनोऽनात्मवतो जन्तोर्वातात्मकस्य च उपद्र वैर्वा जुष्टस्य भग्नं कृच्छ्रेण सिध्यति","text":"alpāśino'nātmavato jantorvātātmakasya ca upadra vairvā juṣṭasya bhagnaṃ kṛcchreṇa sidhyati"},{"type":"verse","number":"9","sanskrit":"भिन्नं कपालं कट्यान्तु सन्धिमुक्तं तथा च्युतम् जघनं प्रतिपिष्टञ्च वर्जयेत्तु चिकित्सकः","text":"bhinnaṃ kapālaṃ kaṭyāntu sandhimuktaṃ tathā cyutam jaghanaṃ pratipiṣṭañca varjayettu cikitsakaḥ"},{"type":"verse","number":"10","sanskrit":"असंश्लिष्टकपालञ्च ललाटे चूर्णितञ्च यत् भग्नं स्तने गुदे पृष्ठे शङ्खे मूर्द्धनि वर्जयेत्","text":"asaṃśliṣṭakapālañca lalāṭe cūrṇitañca yat bhagnaṃ stane gude pṛṣṭhe śaṅkhe mūrddhani varjayet"},{"type":"verse","number":"11","sanskrit":"सम्यक्संहितमप्यस्थि दुर्न्यासाद् दुष्टबन्धनात् सङ्क्षोभाद्वाऽपि यद्गच्छेद्विक्रियां तच्च वर्जयेत्","text":"samyaksaṃhitamapyasthi durnyāsād duṣṭabandhanāt saṅkṣobhādvā'pi yadgacchedvikriyāṃ tacca varjayet"},{"type":"verse","number":"12","sanskrit":"तरुणास्थीनि नम्यन्ते भिद्यन्ते नलकानि तु कपालानि विभज्यन्ते स्फुटन्ति रुचकानि च","text":"taruṇāsthīni namyante bhidyante nalakāni tu kapālāni vibhajyante sphuṭanti rucakāni ca"},{"type":"verse","number":"13","sanskrit":"पाण्योः पार्श्वयुगे पृष्ठे वक्षोजठरपायुषु पादयोरपि चास्थीनि वलयानि बभाषिरे","text":"pāṇyoḥ pārśvayuge pṛṣṭhe vakṣojaṭharapāyuṣu pādayorapi cāsthīni valayāni babhāṣire"},{"type":"verse","number":"14","sanskrit":"आदौ भग्नं विदित्वा तु सेचयेच्छीतलाम्बुना पङ्केनालेपनं कार्यं बन्धनञ्च कुशाऽन्वितम्","text":"ādau bhagnaṃ viditvā tu secayecchītalāmbunā paṅkenālepanaṃ kāryaṃ bandhanañca kuśā'nvitam"},{"type":"verse","number":"15","sanskrit":"अवनामितमुन्नह्येदुन्नतं चावपीडयेत् आञ्जेदतिक्षिप्तमधो गतं चोपरिवर्त्तयेत्","text":"avanāmitamunnahyedunnataṃ cāvapīḍayet āñjedatikṣiptamadho gataṃ coparivarttayet"},{"type":"verse","number":"16","sanskrit":"मधूकोदुम्बराश्वत्थकदम्बनिचुलत्वचः वंशसर्जार्जुनानाञ्च कुशार्थमुपसंहरेत्","text":"madhūkodumbarāśvatthakadambaniculatvacaḥ vaṃśasarjārjunānāñca kuśārthamupasaṃharet"},{"type":"verse","number":"17","sanskrit":"पटस्योपरि बध्नीयान्न गाढं शिथिलं न च सप्तसप्तदिनाच्छीते घर्मे मुञ्चेत्त्र् यहात्त्र् यहात् मासान्ते पञ्चपञ्चाहाद्भग्नदोषवशेन वा","text":"paṭasyopari badhnīyānna gāḍhaṃ śithilaṃ na ca saptasaptadinācchīte gharme muñcettr yahāttr yahāt māsānte pañcapañcāhādbhagnadoṣavaśena vā"},{"type":"verse","number":"18","sanskrit":"आलेपनार्थं मञ्जिष्ठा मधूकं चाम्बुपेषितम् शतधौतघृतोन्मिश्रं शालिपिष्टञ्च लेपनम्","text":"ālepanārthaṃ mañjiṣṭhā madhūkaṃ cāmbupeṣitam śatadhautaghṛtonmiśraṃ śālipiṣṭañca lepanam"},{"type":"verse","number":"19","sanskrit":"सद्योऽभिघातजनिता आगन्तुश्वयथवः प्रशाम्यन्ति पिष्टकलवणालेपादम्लीकाफलरसाभ्यां वा","text":"sadyo'bhighātajanitā āgantuśvayathavaḥ praśāmyanti piṣṭakalavaṇālepādamlīkāphalarasābhyāṃ vā"},{"type":"verse","number":"20","sanskrit":"आम्रातकजटाऽम्लीकाफलं पत्राणि शिग्रुजम्","text":"āmrātakajaṭā'mlīkāphalaṃ patrāṇi śigrujam"},{"type":"verse","number":"21","sanskrit":"मूलं पौनर्नवं वर्द्धमानस्यापि च केम्बुकात् सर्वं संक्षुद्य तक्रेण काञ्जिकेन तथैव च","text":"mūlaṃ paunarnavaṃ varddhamānasyāpi ca kembukāt sarvaṃ saṃkṣudya takreṇa kāñjikena tathaiva ca"},{"type":"verse","number":"22","sanskrit":"पाचयित्वा चरेच्छ्रेष्ठं तेन पीडा प्रणश्यति शोथश्चास्थि च शीघ्रेण सन्धानं याति वै ध्रुवम्","text":"pācayitvā carecchreṣṭhaṃ tena pīḍā praṇaśyati śothaścāsthi ca śīghreṇa sandhānaṃ yāti vai dhruvam"},{"type":"verse","number":"23","sanskrit":"न्यग्रोधादिकषायन्तु सुशीतं परिषेचने पञ्चमूलीकषायं सक्षीरं दद्यात्सवेदने","text":"nyagrodhādikaṣāyantu suśītaṃ pariṣecane pañcamūlīkaṣāyaṃ sakṣīraṃ dadyātsavedane"},{"type":"verse","number":"24","sanskrit":"सुखोष्णमवचार्यं वा चक्रतैलं विजानता अविदाहिभिरन्नैश्च पिष्टकैः समुपाचरेत्","text":"sukhoṣṇamavacāryaṃ vā cakratailaṃ vijānatā avidāhibhirannaiśca piṣṭakaiḥ samupācaret"},{"type":"verse","number":"25","sanskrit":"ग्लानिर्हि निहता तस्य सन्धिविश्लेषकारिका मांसं मांसरसः क्षीरं सर्पिर्यूषःसतीनजः बृहणञ्चान्नपानञ्च देयं भग्नाय जानता","text":"glānirhi nihatā tasya sandhiviśleṣakārikā māṃsaṃ māṃsarasaḥ kṣīraṃ sarpiryūṣaḥsatīnajaḥ bṛhaṇañcānnapānañca deyaṃ bhagnāya jānatā"},{"type":"verse","number":"26","sanskrit":"गृष्टिक्षीरं ससर्पिष्कं मधुरौषधसाधितम् शीतलं लाक्षया युक्तं प्रातर्भग्नः पिबेन्नरः","text":"gṛṣṭikṣīraṃ sasarpiṣkaṃ madhurauṣadhasādhitam śītalaṃ lākṣayā yuktaṃ prātarbhagnaḥ pibennaraḥ"},{"type":"verse","number":"27","sanskrit":"सघृतेनास्थिसंहारं लाक्षागोधूममर्जुनम् सन्धिमुक्तेऽस्थिसम्भग्ने पिबेत्क्षीरेण वा पुनः","text":"saghṛtenāsthisaṃhāraṃ lākṣāgodhūmamarjunam sandhimukte'sthisambhagne pibetkṣīreṇa vā punaḥ"},{"type":"verse","number":"28","sanskrit":"रसोन मधुलाक्षाऽज्यसिताकल्कं समश्नताम् छिन्नभिन्नच्युतास्थीनां सन्धानमचिराद्भवेत्","text":"rasona madhulākṣā'jyasitākalkaṃ samaśnatām chinnabhinnacyutāsthīnāṃ sandhānamacirādbhavet"},{"type":"verse","number":"29","sanskrit":"चूर्णं पुरेण संयोज्य घृतेनार्जुनलाक्षयोः भग्नःसन्धानमायाति लीढं क्षीरघृताशिना","text":"cūrṇaṃ pureṇa saṃyojya ghṛtenārjunalākṣayoḥ bhagnaḥsandhānamāyāti līḍhaṃ kṣīraghṛtāśinā"},{"type":"verse","number":"30","sanskrit":"मूलं शृगालविन्नायाः पीत्वा मांसरसेन तु चूर्णीकृत्य त्रिसप्ताहादस्थिभग्नमपोहति","text":"mūlaṃ śṛgālavinnāyāḥ pītvā māṃsarasena tu cūrṇīkṛtya trisaptāhādasthibhagnamapohati"},{"type":"verse","number":"31","sanskrit":"आभाचूर्णं मधुयुतमस्थिभग्नस्त्र्यहं पिबेत् पीते चास्थि भवेत्सम्यग्वज्रसारनिभं दृढम्","text":"ābhācūrṇaṃ madhuyutamasthibhagnastryahaṃ pibet pīte cāsthi bhavetsamyagvajrasāranibhaṃ dṛḍham"},{"type":"verse","number":"32","sanskrit":"अम्लीकाफलकल्कैः सौवीरैस्तैलमिश्रितैः स्वेदात् भग्नाभिहतरुजाघ्नैरथ वौषधसाधितं श्वयथौ","text":"amlīkāphalakalkaiḥ sauvīraistailamiśritaiḥ svedāt bhagnābhihatarujāghnairatha vauṣadhasādhitaṃ śvayathau"},{"type":"verse","number":"33","sanskrit":"आभाफलत्रिकव्योषैः सर्वैरेतैः समांशकैः तुल्यं गुग्गुलुना योज्यं भग्नसन्धिप्रसाधनम्","text":"ābhāphalatrikavyoṣaiḥ sarvairetaiḥ samāṃśakaiḥ tulyaṃ guggulunā yojyaṃ bhagnasandhiprasādhanam"},{"type":"verse","number":"34","sanskrit":"लाक्षाऽस्थिसंहृत्ककुभोऽश्वगन्धा चूर्णीकृता नागबला पुरश्च सम्भग्नमुक्तास्थिरुजं निहन्यादङ्गानि कुर्यात्कुलिशोपमानि","text":"lākṣā'sthisaṃhṛtkakubho'śvagandhā cūrṇīkṛtā nāgabalā puraśca sambhagnamuktāsthirujaṃ nihanyādaṅgāni kuryātkuliśopamāni"},{"type":"verse","number":"35","sanskrit":"रात्रौ रात्रौ तिलान्कृष्णान्वासयेदस्थिरे जले दिवा दिवा शोषयित्वा गवां क्षीरेण भावयेत्","text":"rātrau rātrau tilānkṛṣṇānvāsayedasthire jale divā divā śoṣayitvā gavāṃ kṣīreṇa bhāvayet"},{"type":"verse","number":"36","sanskrit":"तृतीयं सप्तरात्रन्तु भावयेन्मधुकाम्बुना ततः क्षीरं पुनः पीताञ्छुष्कान्सूक्ष्मान्विचूर्णयेत्","text":"tṛtīyaṃ saptarātrantu bhāvayenmadhukāmbunā tataḥ kṣīraṃ punaḥ pītāñchuṣkānsūkṣmānvicūrṇayet"},{"type":"verse","number":"37","sanskrit":"काकोल्यादि सयष्ट्याह्वां मञ्जिष्ठां सारिवां तथा","text":"kākolyādi sayaṣṭyāhvāṃ mañjiṣṭhāṃ sārivāṃ tathā"},{"type":"verse","number":"38","sanskrit":"कुष्ठं सर्जरसं मांसीं सुरदारु सचन्दनम् शतपुष्पाञ्च सञ्चूर्ण्य तिलचूर्णेन योजयेत्","text":"kuṣṭhaṃ sarjarasaṃ māṃsīṃ suradāru sacandanam śatapuṣpāñca sañcūrṇya tilacūrṇena yojayet"},{"type":"verse","number":"39","sanskrit":"पीडनार्थं तु कर्त्तव्यं सर्वगन्धैः शृतं पयः चतुर्गुणेन पयसा तत्तैलं पाचयेत्पुनः","text":"pīḍanārthaṃ tu karttavyaṃ sarvagandhaiḥ śṛtaṃ payaḥ caturguṇena payasā tattailaṃ pācayetpunaḥ"},{"type":"verse","number":"40","sanskrit":"यष्टीमंशुमतीम्पत्रं जीवन्तीं तुरगं तथा रोध्रं प्रपौण्डरीकञ्च तथा कालानुसारिवाम्","text":"yaṣṭīmaṃśumatīmpatraṃ jīvantīṃ turagaṃ tathā rodhraṃ prapauṇḍarīkañca tathā kālānusārivām"},{"type":"verse","number":"41","sanskrit":"शैलेयकं क्षीरशुक्लामनन्तां समधूलिकाम् पिष्ट्वा शृङ्गाटकञ्चैव प्रागुक्तान्यौषधानि च","text":"śaileyakaṃ kṣīraśuklāmanantāṃ samadhūlikām piṣṭvā śṛṅgāṭakañcaiva prāguktānyauṣadhāni ca"},{"type":"verse","number":"42","sanskrit":"एभिस्तद्विपचेत्तैलं शास्त्रविन्मृदुनाऽग्नि एतत्तैलं सदा पथ्यं भग्नानां सर्वकर्मसु","text":"ebhistadvipacettailaṃ śāstravinmṛdunā'gni etattailaṃ sadā pathyaṃ bhagnānāṃ sarvakarmasu"},{"type":"verse","number":"43","sanskrit":"आक्षेपके पक्षघाते तालुशोषे तथाऽदिते मन्यास्तम्भे शिरोरोगे कर्णशूले हनुग्रहे","text":"ākṣepake pakṣaghāte tāluśoṣe tathā'dite manyāstambhe śiroroge karṇaśūle hanugrahe"},{"type":"verse","number":"44","sanskrit":"बाधिर्ये तिमिरे चैव ये च स्त्रीषु क्षयङ्गताः पथ्यं पाने तथाऽभ्यङ्गे नस्ये वस्तिषु भोजने","text":"bādhirye timire caiva ye ca strīṣu kṣayaṅgatāḥ pathyaṃ pāne tathā'bhyaṅge nasye vastiṣu bhojane"},{"type":"verse","number":"45","sanskrit":"ग्रीवास्कन्धोरसां वृद्धिरेतेनैव प्रजायते मुखञ्च पद्मप्रतिमं ससुगन्धिसमीरणम्","text":"grīvāskandhorasāṃ vṛddhiretenaiva prajāyate mukhañca padmapratimaṃ sasugandhisamīraṇam"},{"type":"verse","number":"46","sanskrit":"राजार्हमेतत्कर्त्तव्यं राज्ञामेव चिकित्सकैः तिलचूर्णसमं तत्र मिलितं चूर्णमिष्यते","text":"rājārhametatkarttavyaṃ rājñāmeva cikitsakaiḥ tilacūrṇasamaṃ tatra militaṃ cūrṇamiṣyate"},{"type":"verse","number":"47","sanskrit":"पूर्वे वयसि जातं हि भग्नं सुकरमादिशेत् अल्पदोषस्य जन्तोश्च काले तु समशीतले","text":"pūrve vayasi jātaṃ hi bhagnaṃ sukaramādiśet alpadoṣasya jantośca kāle tu samaśītale"},{"type":"verse","number":"48","sanskrit":"प्रथमे वयसि त्वेवं मासात्सन्धिः स्थिरो भवेत् मध्यमे द्विगुणात्कालादन्तिमे त्रिगुणात्तथा","text":"prathame vayasi tvevaṃ māsātsandhiḥ sthiro bhavet madhyame dviguṇātkālādantime triguṇāttathā"},{"type":"verse","number":"49","sanskrit":"नैति पाकं यथा भग्नं तथा यत्नेन रक्षयेत् पक्वमांसशिरास्नायु तद्धि कृच्छ्रेण सिध्यति","text":"naiti pākaṃ yathā bhagnaṃ tathā yatnena rakṣayet pakvamāṃsaśirāsnāyu taddhi kṛcchreṇa sidhyati"},{"type":"verse","number":"50","sanskrit":"पतनादभिघाताद्वा शूनभङ्गं यदक्षतम् शीतान्सेकान्प्रदेहांश्च भिषक्तस्यावचारयेत्","text":"patanādabhighātādvā śūnabhaṅgaṃ yadakṣatam śītānsekānpradehāṃśca bhiṣaktasyāvacārayet"},{"type":"verse","number":"51","sanskrit":"सव्रणस्य तु भग्नस्य व्रणं सर्पिर्मधूत्तरैः प्रतिसार्य कषायैश्च शेषं भग्नवदाचरेत् वातव्याधिविनिर्दिष्टान्स्नेहांस्तत्रापि योजयेत्","text":"savraṇasya tu bhagnasya vraṇaṃ sarpirmadhūttaraiḥ pratisārya kaṣāyaiśca śeṣaṃ bhagnavadācaret vātavyādhivinirdiṣṭānsnehāṃstatrāpi yojayet"},{"type":"verse","number":"52","sanskrit":"लवणं कटुकक्षारमम्लमायासमैथुनम् व्यायामञ्च न सेवेत भग्नो रुक्षान्नमेव च","text":"lavaṇaṃ kaṭukakṣāramamlamāyāsamaithunam vyāyāmañca na seveta bhagno rukṣānnameva ca"},{"type":"verse","number":"53","sanskrit":"भग्नसन्धिमनाविद्धमहीनाङ्गमनुल्वणम् शुभचेष्टाप्रचारञ्च सम्यक्सन्धितमादिशेत्","text":"bhagnasandhimanāviddhamahīnāṅgamanulvaṇam śubhaceṣṭāpracārañca samyaksandhitamādiśet"},{"type":"verse","number":"54","sanskrit":"इति श्री मिश्रलटकनतनयश्रीमन्मिश्रभावविरचिते भावप्रकाशे मध्यखण्डेऽष्टचत्वारिंशत्तमो भग्नाधिकारः समाप्तः ४८ तृतीयोभागेऽपि समाप्तः","text":"iti śrī miśralaṭakanatanayaśrīmanmiśrabhāvaviracite bhāvaprakāśe madhyakhaṇḍe'ṣṭacatvāriṃśattamo bhagnādhikāraḥ samāptaḥ 48 tṛtīyobhāge'pi samāptaḥ"}]},{"sthana":"Уттаракханда","number":49,"lang":"sa","content":[{"type":"heading","heading":"Нади-врана — свищи"},{"type":"verse","number":"1","sanskrit":"यः शोथमाममिति पक्वमुपेक्षतेऽज्ञो यो वा व्रणं प्रचुरपूयमसाधुवृत्तः अभ्यन्तरं प्रविशति प्रविदार्य तस्य स्थानानि पूर्वविहितानि ततः स पूयः तस्यातिमात्रगमनाद् गतिरिष्यते तु नाडीव यद्वहति तेन मता च नाडी","text":"yaḥ śothamāmamiti pakvamupekṣate'jño yo vā vraṇaṃ pracurapūyamasādhuvṛttaḥ abhyantaraṃ praviśati pravidārya tasya sthānāni pūrvavihitāni tataḥ sa pūyaḥ tasyātimātragamanād gatiriṣyate tu nāḍīva yadvahati tena matā ca nāḍī"},{"type":"verse","number":"2","sanskrit":"दोषैस्त्रिभिर्भवति सा पृथगेकशश्च सम्मूर्च्छितैरपि च शल्यनिमित्ततोऽन्या","text":"doṣaistribhirbhavati sā pṛthagekaśaśca sammūrcchitairapi ca śalyanimittato'nyā"},{"type":"verse","number":"3","sanskrit":"तत्रानिलात्परुषसूक्ष्ममुखी सशूला फेनानुविद्धमधिकं स्रवति क्षपासु","text":"tatrānilātparuṣasūkṣmamukhī saśūlā phenānuviddhamadhikaṃ sravati kṣapāsu"},{"type":"verse","number":"4","sanskrit":"पित्तात्तु तृड्ज्वरकरी परिदाहयुक्ता पीतं स्रवत्यधिकमुष्णमहःसु चापि","text":"pittāttu tṛḍjvarakarī paridāhayuktā pītaṃ sravatyadhikamuṣṇamahaḥsu cāpi"},{"type":"verse","number":"5","sanskrit":"ज्ञेया कफाद् बहुघना सितपिच्छिलास्रां स्तब्धा सकण्डुररुजा रजनीप्रवृद्धा","text":"jñeyā kaphād bahughanā sitapicchilāsrāṃ stabdhā sakaṇḍurarujā rajanīpravṛddhā"},{"type":"verse","number":"6","sanskrit":"दाहज्वरश्वसनमूर्च्छनवक्त्रशोषा यस्यां भवन्त्यभिहितानि च लक्षणानि तामादिशेत्पवनपित्तकफप्रकोपाद् घोरां गतिं त्वसुहरामिव कालरात्रिम्","text":"dāhajvaraśvasanamūrcchanavaktraśoṣā yasyāṃ bhavantyabhihitāni ca lakṣaṇāni tāmādiśetpavanapittakaphaprakopād ghorāṃ gatiṃ tvasuharāmiva kālarātrim"},{"type":"verse","number":"7","sanskrit":"नष्टं कथञ्चिदणुमार्गमुदीरितेषु स्थानेषु शल्यमचिरेण गतिं करोति सा फेनिलं मथितमुष्णमसृग्विमिश्रं स्रावं करोति सहसा सरुजञ्च नित्यम्","text":"naṣṭaṃ kathañcidaṇumārgamudīriteṣu sthāneṣu śalyamacireṇa gatiṃ karoti sā phenilaṃ mathitamuṣṇamasṛgvimiśraṃ srāvaṃ karoti sahasā sarujañca nityam"},{"type":"verse","number":"8","sanskrit":"नाडी त्रिदोषप्रभवा न सिध्येदन्त्याश्चतस्रः खलु यत्नसाध्याः","text":"nāḍī tridoṣaprabhavā na sidhyedantyāścatasraḥ khalu yatnasādhyāḥ"},{"type":"verse","number":"9","sanskrit":"अथ नाडीव्रणचिकित्सा तत्रानिलोत्थामुपनाह्य पूर्वमशेषतः पूयगतिं विदार्य तिलैरपामार्गफलैः सुपिष्टैः ससैन्धवैः सम्परिपूर्य बन्धेत् प्रक्षालने वाऽपि सदा व्रणस्य योज्यं महद्यत्खलु पञ्चमूलम्","text":"atha nāḍīvraṇacikitsā tatrānilotthāmupanāhya pūrvamaśeṣataḥ pūyagatiṃ vidārya tilairapāmārgaphalaiḥ supiṣṭaiḥ sasaindhavaiḥ samparipūrya bandhet prakṣālane vā'pi sadā vraṇasya yojyaṃ mahadyatkhalu pañcamūlam"},{"type":"verse","number":"10","sanskrit":"हिंस्रां हरिद्रां कटुकां बलाञ्च गोजिह्विकाञ्चापि सबिल्वमूलाम् संहृत्य तैलं विपचेद् व्रणस्य संशोधनं पूरणरोपणञ्च","text":"hiṃsrāṃ haridrāṃ kaṭukāṃ balāñca gojihvikāñcāpi sabilvamūlām saṃhṛtya tailaṃ vipaced vraṇasya saṃśodhanaṃ pūraṇaropaṇañca"},{"type":"verse","number":"11","sanskrit":"पित्तात्मिकां प्रागुपनाह्य धीमानुत्कारिकाभिः सपयोघृताभिः निपात्य शस्त्रं तिलनागदन्तीयष्ट्याह्वकल्कैः परिपूरयेच्च प्रक्षालने चापि ससोमनिम्बा निशा प्रयोज्या कुशलेन नित्यम्","text":"pittātmikāṃ prāgupanāhya dhīmānutkārikābhiḥ sapayoghṛtābhiḥ nipātya śastraṃ tilanāgadantīyaṣṭyāhvakalkaiḥ paripūrayecca prakṣālane cāpi sasomanimbā niśā prayojyā kuśalena nityam"},{"type":"verse","number":"12","sanskrit":"श्यामात्रिभण्डी त्रिफलासुसिद्धं हरिद्र या तिल्वकवृक्षकेण घृतं सदुग्धं व्रणतर्पणेन हन्याद्गतिं कोष्ठगताऽपि या स्यात्","text":"śyāmātribhaṇḍī triphalāsusiddhaṃ haridra yā tilvakavṛkṣakeṇa ghṛtaṃ sadugdhaṃ vraṇatarpaṇena hanyādgatiṃ koṣṭhagatā'pi yā syāt"},{"type":"verse","number":"13","sanskrit":"नाडीं कफोत्थामुपनाह्य पूर्वं कुलत्थसिद्धार्थकसक्तुकिण्वैः मृदूकृतामेष्यगतिं विदित्वा निपातयेच्छस्त्रमशेषकारि","text":"nāḍīṃ kaphotthāmupanāhya pūrvaṃ kulatthasiddhārthakasaktukiṇvaiḥ mṛdūkṛtāmeṣyagatiṃ viditvā nipātayecchastramaśeṣakāri"},{"type":"verse","number":"14","sanskrit":"दद्याद् व्रणे निम्बतिलाग्निदन्तीसुराष्ट्रजाः सैन्धवसम्प्रयुक्ताः प्रक्षालने चापि करञ्जनिम्बजात्यर्कपीलुस्वरसाः प्रयोज्याः","text":"dadyād vraṇe nimbatilāgnidantīsurāṣṭrajāḥ saindhavasamprayuktāḥ prakṣālane cāpi karañjanimbajātyarkapīlusvarasāḥ prayojyāḥ"},{"type":"verse","number":"15","sanskrit":"स्वर्जिकासिन्धुदन्त्यग्नियूथिका जलनीलिका खरमञ्जरिबीजेषु तैलं गोमूत्रसाधितम् दुष्टव्रणप्रशमनं कफनाडीव्रणापहम्","text":"svarjikāsindhudantyagniyūthikā jalanīlikā kharamañjaribījeṣu tailaṃ gomūtrasādhitam duṣṭavraṇapraśamanaṃ kaphanāḍīvraṇāpaham"},{"type":"verse","number":"16","sanskrit":"सैन्धवार्कमरिचज्वलनाख्यैर्मार्कवेण रजनीद्वयसिद्धम् तैलमेतदचिरेण निहन्याद् दूरगामपि कफानिलनाडीम्","text":"saindhavārkamaricajvalanākhyairmārkaveṇa rajanīdvayasiddham tailametadacireṇa nihanyād dūragāmapi kaphānilanāḍīm"},{"type":"verse","number":"17","sanskrit":"नाडीं तु शल्यप्रभवां विदार्य निष्कास्य शल्यं प्रतिशोध्य मार्गम् बन्धेद् व्रणं क्षौद्र घृतप्रगाढैस्तिलैस्ततो रोपणमस्य कुर्यात्","text":"nāḍīṃ tu śalyaprabhavāṃ vidārya niṣkāsya śalyaṃ pratiśodhya mārgam bandhed vraṇaṃ kṣaudra ghṛtapragāḍhaistilaistato ropaṇamasya kuryāt"},{"type":"verse","number":"18","sanskrit":"कुम्भीकखर्जूरकपित्थबिल्ववनस्पतीनाञ्च शलाटुवर्गे कृत्वा कषायं विपचेत्तु तैलमावाप्य मुस्तं सरलां प्रियङ्गुम्","text":"kumbhīkakharjūrakapitthabilvavanaspatīnāñca śalāṭuvarge kṛtvā kaṣāyaṃ vipacettu tailamāvāpya mustaṃ saralāṃ priyaṅgum"},{"type":"verse","number":"19","sanskrit":"सौगन्धिकं मोचरसाहिपुष्पं लोध्राणि दत्वा खलु धातकीञ्च एतेन शल्यप्रभवा हि नाडी रोहेद् व्रणो वा सुखमाशु चैव","text":"saugandhikaṃ mocarasāhipuṣpaṃ lodhrāṇi datvā khalu dhātakīñca etena śalyaprabhavā hi nāḍī rohed vraṇo vā sukhamāśu caiva"},{"type":"verse","number":"20","sanskrit":"इति कुम्भीकाद्यतैलम् स्नुह्यर्कदुग्धदार्वीणां वर्त्तिं कृत्वा प्रपूरयेत् एष सर्वशरीरस्थां नाडीं हन्यात्प्रयोगराट्","text":"iti kumbhīkādyatailam snuhyarkadugdhadārvīṇāṃ varttiṃ kṛtvā prapūrayet eṣa sarvaśarīrasthāṃ nāḍīṃ hanyātprayogarāṭ"},{"type":"verse","number":"21","sanskrit":"आरग्वधनिशाकाला चूर्णाज्यक्षौद्र संयुता सूत्रवर्त्तिव्रणे योज्या शोधनी गतिनाशिनी","text":"āragvadhaniśākālā cūrṇājyakṣaudra saṃyutā sūtravarttivraṇe yojyā śodhanī gatināśinī"},{"type":"verse","number":"22","sanskrit":"वर्त्तीकृतं माक्षिकसम्प्रयुक्तं नाडीघ्नमुक्तं लवणोत्तमं वा दुष्टव्रणे यद्विहितं तु तैलं तत्सेव्यमानं गतिमाशु हन्ति","text":"varttīkṛtaṃ mākṣikasamprayuktaṃ nāḍīghnamuktaṃ lavaṇottamaṃ vā duṣṭavraṇe yadvihitaṃ tu tailaṃ tatsevyamānaṃ gatimāśu hanti"},{"type":"verse","number":"23","sanskrit":"जात्यर्कसम्पाक करञ्जदन्ती सिन्धूत्थसौवर्चलयावशूकैः वर्त्तिः कृता हन्त्यचिरेण नाडीं स्नुक्क्षीरपिष्टा तु सचित्रकेण","text":"jātyarkasampāka karañjadantī sindhūtthasauvarcalayāvaśūkaiḥ varttiḥ kṛtā hantyacireṇa nāḍīṃ snukkṣīrapiṣṭā tu sacitrakeṇa"},{"type":"verse","number":"24","sanskrit":"बिभीतकाम्रास्थि वटप्रवाल हरेणुकाशङ्खिनिबीजमिश्रा वाराहविट्सूक्ष्ममसी प्रदेया नाडीषु तैलेन च मिश्रयित्वा","text":"bibhītakāmrāsthi vaṭapravāla hareṇukāśaṅkhinibījamiśrā vārāhaviṭsūkṣmamasī pradeyā nāḍīṣu tailena ca miśrayitvā"},{"type":"verse","number":"25","sanskrit":"मेषरोममसीतुम्ब्या कटुतैलं विपाचितम् नाडीव्रणं चिरोद्भूतं जयेत्तु तूलसङ्गमात्","text":"meṣaromamasītumbyā kaṭutailaṃ vipācitam nāḍīvraṇaṃ cirodbhūtaṃ jayettu tūlasaṅgamāt"},{"type":"verse","number":"26","sanskrit":"कर्चूरकस्य स्वरसे कटुतैलं विपाचयेत् सिन्दूरकल्कितं नाडीदुष्टव्रणविसर्पनुत्","text":"karcūrakasya svarase kaṭutailaṃ vipācayet sindūrakalkitaṃ nāḍīduṣṭavraṇavisarpanut"},{"type":"verse","number":"27","sanskrit":"कर्चूरकरसे तैलं पुरसिन्दूरकल्कितम् पामादुष्टव्रणं नाडीं हन्यात्सर्वव्रणान्तकृत्","text":"karcūrakarase tailaṃ purasindūrakalkitam pāmāduṣṭavraṇaṃ nāḍīṃ hanyātsarvavraṇāntakṛt"},{"type":"verse","number":"28","sanskrit":"भल्लातकार्कमरिचैर्लवणोत्तमेन सिद्धं विडङ्गरजनीद्वयचित्रकैश्च स्यान्मार्कवस्य च रसेन निहन्ति तैलं नाडीं कफानिलकृतामपचीं व्रणांश्च","text":"bhallātakārkamaricairlavaṇottamena siddhaṃ viḍaṅgarajanīdvayacitrakaiśca syānmārkavasya ca rasena nihanti tailaṃ nāḍīṃ kaphānilakṛtāmapacīṃ vraṇāṃśca"},{"type":"verse","number":"29","sanskrit":"स्वर्जिका सैन्धवं दन्ती नीलीमूलं फलं तथा मूत्रे चतुर्गुणे सिद्धं तैलं नाडीव्रणापहम् सर्वो व्रणक्रमः कार्यः शोधनारोपणादिकः","text":"svarjikā saindhavaṃ dantī nīlīmūlaṃ phalaṃ tathā mūtre caturguṇe siddhaṃ tailaṃ nāḍīvraṇāpaham sarvo vraṇakramaḥ kāryaḥ śodhanāropaṇādikaḥ"},{"type":"verse","number":"30","sanskrit":"गुग्गुलुत्रिफलाव्योषैः समांशैराज्ययोजितैः अक्षप्रमाणां गुटिकां खादेदेकामतन्द्रि तः","text":"guggulutriphalāvyoṣaiḥ samāṃśairājyayojitaiḥ akṣapramāṇāṃ guṭikāṃ khādedekāmatandri taḥ"},{"type":"verse","number":"31","sanskrit":"नाडीं दुष्टव्रणं शूलमुदावर्त्तं भगन्दरम् गुल्मञ्च गुदजान्हन्यात्पक्षिराट् पन्नगानिव","text":"nāḍīṃ duṣṭavraṇaṃ śūlamudāvarttaṃ bhagandaram gulmañca gudajānhanyātpakṣirāṭ pannagāniva"},{"type":"verse","number":"32","sanskrit":"या द्विव्रणीये विहितास्तु वत्तर्यस्ताः सर्वनाडीषु भिषग्विदध्यात्","text":"yā dvivraṇīye vihitāstu vattaryastāḥ sarvanāḍīṣu bhiṣagvidadhyāt"},{"type":"verse","number":"33","sanskrit":"कृशदुर्बलभीरूणां नाडीं मर्माश्रितामपि क्षारसूत्रेण तां छिन्द्यान्न शस्त्रेण कदाचन","text":"kṛśadurbalabhīrūṇāṃ nāḍīṃ marmāśritāmapi kṣārasūtreṇa tāṃ chindyānna śastreṇa kadācana"},{"type":"verse","number":"34","sanskrit":"एषण्या गतिमन्विष्य क्षारसूत्रानुसारिणीम् सूचीं निदध्याद्गत्यन्ते प्रोन्नाम्याशु विनिर्हरेत्","text":"eṣaṇyā gatimanviṣya kṣārasūtrānusāriṇīm sūcīṃ nidadhyādgatyante pronnāmyāśu vinirharet"},{"type":"verse","number":"35","sanskrit":"सूत्रस्यान्तं समानीय गाढं बन्धनमाचरेत् ततः क्षारबलं वीक्ष्य सूत्रमन्यत्प्रवेशयेत्","text":"sūtrasyāntaṃ samānīya gāḍhaṃ bandhanamācaret tataḥ kṣārabalaṃ vīkṣya sūtramanyatpraveśayet"},{"type":"verse","number":"36","sanskrit":"क्षाराक्तं मतिमान्वैद्यो यावन्न च्छिद्यते गतिः भगन्दरेष्वेष विधिः कार्यो वैद्येन जानता","text":"kṣārāktaṃ matimānvaidyo yāvanna cchidyate gatiḥ bhagandareṣveṣa vidhiḥ kāryo vaidyena jānatā"},{"type":"verse","number":"37","sanskrit":"अर्बुदादिषु चोत्क्षिप्य मूले सूत्रं निधापयेत् सूचीभिर्यववक्त्राभिराचितं वा समन्ततः मूले सूत्रेण बध्नीयाच्छिन्ने चोपचरेद् व्रणम्","text":"arbudādiṣu cotkṣipya mūle sūtraṃ nidhāpayet sūcībhiryavavaktrābhirācitaṃ vā samantataḥ mūle sūtreṇa badhnīyācchinne copacared vraṇam"},{"type":"verse","number":"38","sanskrit":"इत्येकोनपञ्चाशत्तमो नाडीव्रणाधिकारः समाप्तः ४९","text":"ityekonapañcāśattamo nāḍīvraṇādhikāraḥ samāptaḥ 49"}]},{"sthana":"Уттаракханда","number":50,"lang":"sa","content":[{"type":"heading","heading":"Бхагандара — анальный свищ"},{"type":"verse","number":"1","sanskrit":"कटीकपालनिस्तोददाह कण्डूरुजाऽदयः भवन्ति पूर्वरूपाणि भविष्यति भगन्दरे","text":"kaṭīkapālanistodadāha kaṇḍūrujā'dayaḥ bhavanti pūrvarūpāṇi bhaviṣyati bhagandare"},{"type":"verse","number":"2","sanskrit":"गुदस्य द्व्यङ्गुले क्षेत्रे पार्श्वतः पिडकाऽत्तिकृत् भिन्नो भगन्दरो ज्ञेयः स च पञ्चविधो भवेत्","text":"gudasya dvyaṅgule kṣetre pārśvataḥ piḍakā'ttikṛt bhinno bhagandaro jñeyaḥ sa ca pañcavidho bhavet"},{"type":"verse","number":"3","sanskrit":"भगन्दरशब्दस्य निरुक्तिमाह भोजः भगं परिसमन्ताच्च गुदं वस्तिं तथैव च भगवद् दारयेद्यस्मात्तस्मादेष भगन्दरः","text":"bhagandaraśabdasya niruktimāha bhojaḥ bhagaṃ parisamantācca gudaṃ vastiṃ tathaiva ca bhagavad dārayedyasmāttasmādeṣa bhagandaraḥ"},{"type":"verse","number":"4","sanskrit":"कषायरुक्षैरतिकोपितोऽनिलस्त्वपानदेशे पिडकां करोति याम् उपेक्षणात्पाकमुपैति दारुणं रुजा च भिन्नाऽरुणफेनवाहिनी तत्रागमो मूत्रपुरीषरेतसां व्रणैरनेकैः शतपोनकं वदेत्","text":"kaṣāyarukṣairatikopito'nilastvapānadeśe piḍakāṃ karoti yām upekṣaṇātpākamupaiti dāruṇaṃ rujā ca bhinnā'ruṇaphenavāhinī tatrāgamo mūtrapurīṣaretasāṃ vraṇairanekaiḥ śataponakaṃ vadet"},{"type":"verse","number":"5","sanskrit":"प्रकोपनैः पित्तमतिप्रकोपितं करोति रक्तां पिडकां गुदे गताम् तदाशुपाकाऽहिमपूतिवाहिनीं भगन्दरं चोष्ट्रशिरोधरं वदेत्","text":"prakopanaiḥ pittamatiprakopitaṃ karoti raktāṃ piḍakāṃ gude gatām tadāśupākā'himapūtivāhinīṃ bhagandaraṃ coṣṭraśirodharaṃ vadet"},{"type":"verse","number":"6","sanskrit":"कण्डूयनो घनस्रावी कठिनो मन्दवेदनः श्वेतावभासः कफजः परिस्रावी भगन्दरः","text":"kaṇḍūyano ghanasrāvī kaṭhino mandavedanaḥ śvetāvabhāsaḥ kaphajaḥ parisrāvī bhagandaraḥ"},{"type":"verse","number":"7","sanskrit":"बहुवर्णरुजास्रावा पिडका गोस्तनोपमा शम्बूकावर्त्तगतिकः शम्बूकावर्त्तको मतः","text":"bahuvarṇarujāsrāvā piḍakā gostanopamā śambūkāvarttagatikaḥ śambūkāvarttako mataḥ"},{"type":"verse","number":"8","sanskrit":"क्षताद्गतिः पायुगता विवर्द्धते ह्यपेक्षणात्स्युः कृमयो विदार्य ते प्रकुर्वते मार्गमनेकधा मुखैर्व्रणैस्तमुन्मार्गिभगन्दरं वदेत्","text":"kṣatādgatiḥ pāyugatā vivarddhate hyapekṣaṇātsyuḥ kṛmayo vidārya te prakurvate mārgamanekadhā mukhairvraṇaistamunmārgibhagandaraṃ vadet"},{"type":"verse","number":"9","sanskrit":"घोराः साधयितुं दुःखाः सर्व एव भगन्दराः तेष्वसाध्यस्त्रिदोषोत्थः क्षतजश्चविशेषतः","text":"ghorāḥ sādhayituṃ duḥkhāḥ sarva eva bhagandarāḥ teṣvasādhyastridoṣotthaḥ kṣatajaścaviśeṣataḥ"},{"type":"verse","number":"10","sanskrit":"वातमूत्रपुरीषाणि शुक्रञ्च कृमयस्तथा भगन्दरात्स्रवन्तस्तु नाशयन्ति तमातुरम्","text":"vātamūtrapurīṣāṇi śukrañca kṛmayastathā bhagandarātsravantastu nāśayanti tamāturam"},{"type":"verse","number":"11","sanskrit":"अथास्य पिडकामेव तथा यत्नादुपाचरेत् शुद्ध्य्स्रस्रुतिसेकाद्यैर्यथा पाकं न गच्छति","text":"athāsya piḍakāmeva tathā yatnādupācaret śuddhysrasrutisekādyairyathā pākaṃ na gacchati"},{"type":"verse","number":"12","sanskrit":"वटपत्रेष्टका शुण्ठीसगुडूचीपुनर्नवाः सुपिष्टः पिडकाऽवस्थे लेपः शस्तो भगन्दरे","text":"vaṭapatreṣṭakā śuṇṭhīsaguḍūcīpunarnavāḥ supiṣṭaḥ piḍakā'vasthe lepaḥ śasto bhagandare"},{"type":"verse","number":"13","sanskrit":"पिडकानाम पक्वानामपतर्पणपूर्वकम् कर्म कुर्याद्विरेकान्तं भिन्नानां वक्ष्यते क्रिया","text":"piḍakānāma pakvānāmapatarpaṇapūrvakam karma kuryādvirekāntaṃ bhinnānāṃ vakṣyate kriyā"},{"type":"verse","number":"14","sanskrit":"एषणीपाटनक्षारवह्निदाहादिकं क्रमम् विधाय व्रणवत्कार्यं यथादोषं यथाक्रमम्","text":"eṣaṇīpāṭanakṣāravahnidāhādikaṃ kramam vidhāya vraṇavatkāryaṃ yathādoṣaṃ yathākramam"},{"type":"verse","number":"15","sanskrit":"पयः पिष्टैस्तिलारिष्टमधुकैश्च सुशीतलैः भगन्दरे प्रशस्तोऽय सरक्ते वेदनावति","text":"payaḥ piṣṭaistilāriṣṭamadhukaiśca suśītalaiḥ bhagandare praśasto'ya sarakte vedanāvati"},{"type":"verse","number":"16","sanskrit":"सुमना वटपत्राणि गुडूची विश्वभेषजम् ससैन्धवस्तक्रपिष्टो लेपो हन्ति भगन्दरम्","text":"sumanā vaṭapatrāṇi guḍūcī viśvabheṣajam sasaindhavastakrapiṣṭo lepo hanti bhagandaram"},{"type":"verse","number":"17","sanskrit":"त्रिवृत्तिला नागदन्ती मञ्जिष्ठा सह सर्पिषा उत्सादनं भवेदेतत्सैन्धवक्षौद्र संयुतम्","text":"trivṛttilā nāgadantī mañjiṣṭhā saha sarpiṣā utsādanaṃ bhavedetatsaindhavakṣaudra saṃyutam"},{"type":"verse","number":"18","sanskrit":"खदिराम्बुरतो भूत्वा कषायं त्रैफलं पिबेत् महिषाक्षविडङ्गानां भगन्दरविनाशनम्","text":"khadirāmburato bhūtvā kaṣāyaṃ traiphalaṃ pibet mahiṣākṣaviḍaṅgānāṃ bhagandaravināśanam"},{"type":"verse","number":"19","sanskrit":"शम्बूकमांसं भुञ्जीत प्रकारैर्व्यञ्जनादिभिः अजीर्णवर्जी मासेन मुच्यते तु भगन्दरात्","text":"śambūkamāṃsaṃ bhuñjīta prakārairvyañjanādibhiḥ ajīrṇavarjī māsena mucyate tu bhagandarāt"},{"type":"verse","number":"20","sanskrit":"न्यग्रोधादिर्गणो यस्तु हितः शोधनरोपणः तैलं घृतं वा तत् पक्वं भगन्दरविनाशनम्","text":"nyagrodhādirgaṇo yastu hitaḥ śodhanaropaṇaḥ tailaṃ ghṛtaṃ vā tat pakvaṃ bhagandaravināśanam"},{"type":"verse","number":"21","sanskrit":"तिला ज्योतिष्मती कुष्ठं लाङ्गली गिरिकर्णिका शताह्वात्रिवृतादन्त्यः शोधनाश्च भगन्दरे","text":"tilā jyotiṣmatī kuṣṭhaṃ lāṅgalī girikarṇikā śatāhvātrivṛtādantyaḥ śodhanāśca bhagandare"},{"type":"verse","number":"22","sanskrit":"तिलाभयालोध्रमरिष्टपत्रं निशे बला लोध्रमगारधूमम् भगन्दरे चाप्युपदंशजे च द्रुष्टव्रणे रोपणशोधनाय","text":"tilābhayālodhramariṣṭapatraṃ niśe balā lodhramagāradhūmam bhagandare cāpyupadaṃśaje ca druṣṭavraṇe ropaṇaśodhanāya"},{"type":"verse","number":"23","sanskrit":"स्नुह्यर्कदुग्धदार्वीभिर्वर्त्तिं कृत्वा विचक्षणः भगन्दरगतिं ज्ञात्वा पूरयेत्तां प्रयत्नतः","text":"snuhyarkadugdhadārvībhirvarttiṃ kṛtvā vicakṣaṇaḥ bhagandaragatiṃ jñātvā pūrayettāṃ prayatnataḥ"},{"type":"verse","number":"24","sanskrit":"एषा सर्वशरीरस्थां नाडीं हन्यान्नसंशयः त्रिफलारससंयुक्तं विडालास्थिप्रलेपनम्","text":"eṣā sarvaśarīrasthāṃ nāḍīṃ hanyānnasaṃśayaḥ triphalārasasaṃyuktaṃ viḍālāsthipralepanam"},{"type":"verse","number":"25","sanskrit":"भगन्दरं निहन्त्याशु दुष्टव्रणहरं परम् त्रिवृत्तेजोवतीदन्तीकल्को नाडीव्रणापहः","text":"bhagandaraṃ nihantyāśu duṣṭavraṇaharaṃ param trivṛttejovatīdantīkalko nāḍīvraṇāpahaḥ"},{"type":"verse","number":"26","sanskrit":"ज्योतिष्मती लाङ्गलकी श्यामा दन्ती त्रिवृत्तिलाः कुष्ठं शताह्वा गोलोमी तिल्वको गिरिकर्णिका","text":"jyotiṣmatī lāṅgalakī śyāmā dantī trivṛttilāḥ kuṣṭhaṃ śatāhvā golomī tilvako girikarṇikā"},{"type":"verse","number":"27","sanskrit":"कासीसकाञ्चनक्षीर्यौ वर्गः शोधन इष्यते","text":"kāsīsakāñcanakṣīryau vargaḥ śodhana iṣyate"},{"type":"verse","number":"28","sanskrit":"मधुतैलयुता विडङ्गसारत्रिफलामागधिकाकणाश्च लीढाः कृमिकुष्ठभगन्दरप्रमेहक्षयनाडीव्रणरोपणा भवन्ति","text":"madhutailayutā viḍaṅgasāratriphalāmāgadhikākaṇāśca līḍhāḥ kṛmikuṣṭhabhagandarapramehakṣayanāḍīvraṇaropaṇā bhavanti"},{"type":"verse","number":"29","sanskrit":"चित्रकार्कौ त्रिवृत्पाठे मलयूहयमारकौ सुधां वचां लाङ्गलकीं हरितालं सुवर्चिकाम्","text":"citrakārkau trivṛtpāṭhe malayūhayamārakau sudhāṃ vacāṃ lāṅgalakīṃ haritālaṃ suvarcikām"},{"type":"verse","number":"30","sanskrit":"ज्योतिष्मतीञ्च संहृत्य तैलं धीमान्विपाचयेत् एतद्विष्यन्दनं नाम तैलं दद्याद्भगन्दरे शोधनं रोपणञ्चैव सवर्णकरणं तथा","text":"jyotiṣmatīñca saṃhṛtya tailaṃ dhīmānvipācayet etadviṣyandanaṃ nāma tailaṃ dadyādbhagandare śodhanaṃ ropaṇañcaiva savarṇakaraṇaṃ tathā"},{"type":"verse","number":"31","sanskrit":"निशाऽकक्षीर सिन्धूत्थपुराश्वहरवत्सकैः सिद्धमभ्यञ्जनं तैलं भगन्दरहरं परम्","text":"niśā'kakṣīra sindhūtthapurāśvaharavatsakaiḥ siddhamabhyañjanaṃ tailaṃ bhagandaraharaṃ param"},{"type":"verse","number":"32","sanskrit":"करवीरनिशा दन्तीलाङ्गलीलवणाग्निभिः मातुलुङ्गकवत्साह्वैः पचेत्तैलं भगन्दरे","text":"karavīraniśā dantīlāṅgalīlavaṇāgnibhiḥ mātuluṅgakavatsāhvaiḥ pacettailaṃ bhagandare"},{"type":"verse","number":"33","sanskrit":"त्रिफलापुरकृष्णानां त्रिपञ्चकांशयोजिता गुटिका शोथगुल्मार्शोभगन्दरवतां हिता","text":"triphalāpurakṛṣṇānāṃ tripañcakāṃśayojitā guṭikā śothagulmārśobhagandaravatāṃ hitā"},{"type":"verse","number":"34","sanskrit":"नाड्यन्तरे व्रणान्कुर्याद्भिषक् तु शतपोनके ततस्तेष्ववरूढेषु शेषा नाडीरुपाचरेत्","text":"nāḍyantare vraṇānkuryādbhiṣak tu śataponake tatasteṣvavarūḍheṣu śeṣā nāḍīrupācaret"},{"type":"verse","number":"35","sanskrit":"व्याधौ तत्र बहुच्छिद्रे भिषजा तु विजानता अर्द्धलाङ्गलकच्छेदः कार्यो लाङ्गलकोऽपि वा","text":"vyādhau tatra bahucchidre bhiṣajā tu vijānatā arddhalāṅgalakacchedaḥ kāryo lāṅgalako'pi vā"},{"type":"verse","number":"36","sanskrit":"सर्वतोभद्र को वाऽपि कार्यो गोतीर्थकोऽपि वा","text":"sarvatobhadra ko vā'pi kāryo gotīrthako'pi vā"},{"type":"verse","number":"37","sanskrit":"द्वाभ्यां समाभ्यां पार्श्वाभ्यां छेदो लाङ्गलको मतः ह्रस्वमेकतरं यत्तु सोऽद्धलाङ्गलकः स्मृतः","text":"dvābhyāṃ samābhyāṃ pārśvābhyāṃ chedo lāṅgalako mataḥ hrasvamekataraṃ yattu so'ddhalāṅgalakaḥ smṛtaḥ"},{"type":"verse","number":"38","sanskrit":"सेवनीं वर्जयित्वा तु चतुर्द्धा दारिते गुदे सर्वतोभद्र कं छेदमाहुश्छेदविदो जनाः पार्श्वादागतशस्त्रेण च्छेदो गोतीर्थको मतः","text":"sevanīṃ varjayitvā tu caturddhā dārite gude sarvatobhadra kaṃ chedamāhuśchedavido janāḥ pārśvādāgataśastreṇa cchedo gotīrthako mataḥ"},{"type":"verse","number":"39","sanskrit":"सर्वानास्रावमार्गांस्तु दहेद्वैद्यस्तथाऽग्निना अथोष्ट्रग्रीवमेषिण्या छित्वा क्षारं निपातयेत्","text":"sarvānāsrāvamārgāṃstu dahedvaidyastathā'gninā athoṣṭragrīvameṣiṇyā chitvā kṣāraṃ nipātayet"},{"type":"verse","number":"40","sanskrit":"उत्कृत्यास्रावमार्गन्तु परिस्राविणि बुद्धिमान् क्षारेण वा स्रावगतिं दहेद्धुतवहेन वा","text":"utkṛtyāsrāvamārgantu parisrāviṇi buddhimān kṣāreṇa vā srāvagatiṃ daheddhutavahena vā"},{"type":"verse","number":"41","sanskrit":"गतिमन्विष्य शस्त्रेण च्छिन्द्यात्खर्जूरपत्रकम्","text":"gatimanviṣya śastreṇa cchindyātkharjūrapatrakam"},{"type":"verse","number":"42","sanskrit":"चन्द्रा र्द्ध चन्द्र चक्रञ्च सूचीमुखमवाङ्मुखम् छित्वाऽग्निना दहेत्सम्यगेवं क्षारेण वा पुनः","text":"candrā rddha candra cakrañca sūcīmukhamavāṅmukham chitvā'gninā dahetsamyagevaṃ kṣāreṇa vā punaḥ"},{"type":"verse","number":"43","sanskrit":"एषां तु शस्त्र पतनाद्वेदना यत्र जायते तत्राणुतैलेनोष्णेन परिषेकः प्रशस्यते","text":"eṣāṃ tu śastra patanādvedanā yatra jāyate tatrāṇutailenoṣṇena pariṣekaḥ praśasyate"},{"type":"verse","number":"44","sanskrit":"आगन्तुजे भिषङ् नाडीं शस्त्रेणोत्कृत्य यत्नतः","text":"āgantuje bhiṣaṅ nāḍīṃ śastreṇotkṛtya yatnataḥ"},{"type":"verse","number":"45","sanskrit":"जम्ब्वोष्ठेनाग्निवर्णेन तप्तया वा शलाकया दहेद्यथोक्तं मतिमांस्तं व्रणं सुसमाहितः","text":"jambvoṣṭhenāgnivarṇena taptayā vā śalākayā dahedyathoktaṃ matimāṃstaṃ vraṇaṃ susamāhitaḥ"},{"type":"verse","number":"46","sanskrit":"व्यायामं मैथुनं युद्धं पृष्ठयानं गुरूणि च संवत्सरं परिहरेदुपरूढव्रणो नरः","text":"vyāyāmaṃ maithunaṃ yuddhaṃ pṛṣṭhayānaṃ gurūṇi ca saṃvatsaraṃ parihareduparūḍhavraṇo naraḥ"},{"type":"verse","number":"47","sanskrit":"इति पञ्चाशत्तमो भगन्दराधिकारः समाप्तः","text":"iti pañcāśattamo bhagandarādhikāraḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":51,"lang":"sa","content":[{"type":"heading","heading":"Упаданша — венерические язвы"},{"type":"verse","number":"1","sanskrit":"हस्ताभिघातान्नख दन्तघातादधावनादत्युपसेवनाद्वा योनिप्रदोषाच्च भवन्ति शिश्ने पञ्चोपदंशा विविधापचारैः","text":"hastābhighātānnakha dantaghātādadhāvanādatyupasevanādvā yonipradoṣācca bhavanti śiśne pañcopadaṃśā vividhāpacāraiḥ"},{"type":"verse","number":"2","sanskrit":"सतोदभेदस्फुरणैः सकृष्णैः स्फोटैर्व्यवस्येत्पवनोपदंशम् पीतैर्बहुक्लेदयुतैः सदाहैः पित्तेन रक्तैः पिशितावभासैः","text":"satodabhedasphuraṇaiḥ sakṛṣṇaiḥ sphoṭairvyavasyetpavanopadaṃśam pītairbahukledayutaiḥ sadāhaiḥ pittena raktaiḥ piśitāvabhāsaiḥ"},{"type":"verse","number":"3","sanskrit":"स्फोटैः सकृष्णै रुधिरं स्रवन्तं रक्तात्मकं पित्तसमानलिङ्गम् सकण्डुरैः शोथयुतैर्महद्भिः शुक्लैर्घनैः स्रावयुतैः कफेन नानाविधस्रावरुजोपपन्नमसाध्यमाहुस्त्रिमलोपदंशम्","text":"sphoṭaiḥ sakṛṣṇai rudhiraṃ sravantaṃ raktātmakaṃ pittasamānaliṅgam sakaṇḍuraiḥ śothayutairmahadbhiḥ śuklairghanaiḥ srāvayutaiḥ kaphena nānāvidhasrāvarujopapannamasādhyamāhustrimalopadaṃśam"},{"type":"verse","number":"4","sanskrit":"प्रशीर्णमांसं कृमिभिःप्रजग्धं मुष्कावशेषं परिवर्जनीयम्","text":"praśīrṇamāṃsaṃ kṛmibhiḥprajagdhaṃ muṣkāvaśeṣaṃ parivarjanīyam"},{"type":"verse","number":"5","sanskrit":"सञ्जातमात्रे न करोति मूढः क्रियां नरो यो विषये प्रसक्तः कालेन शोथकृमिदाहपाकैः प्रशीर्णशिश्नो म्रियते स तेन","text":"sañjātamātre na karoti mūḍhaḥ kriyāṃ naro yo viṣaye prasaktaḥ kālena śothakṛmidāhapākaiḥ praśīrṇaśiśno mriyate sa tena"},{"type":"verse","number":"6","sanskrit":"उपदंशेषु साध्येषु स्निग्धस्विन्नस्य देहिनः मेढ्रमध्ये शिरां विध्यात्पातयेद्वा जलौकसः","text":"upadaṃśeṣu sādhyeṣu snigdhasvinnasya dehinaḥ meḍhramadhye śirāṃ vidhyātpātayedvā jalaukasaḥ"},{"type":"verse","number":"7","sanskrit":"हरेदुभयतश्चापि दोषानत्यर्थमूर्च्छितान् सद्यो निर्हृतदोषस्य रुक्शोथावुपशाम्यतः","text":"haredubhayataścāpi doṣānatyarthamūrcchitān sadyo nirhṛtadoṣasya rukśothāvupaśāmyataḥ"},{"type":"verse","number":"8","sanskrit":"यदि वा दुर्बलोजन्तुर्न वा प्राप्तविरेचनः निरूहेण हरेत्तस्य दोषानत्यर्थमूर्च्छितान् पाको रक्ष्यः प्रयत्नेन शिश्नक्षयकरो हि सः","text":"yadi vā durbalojanturna vā prāptavirecanaḥ nirūheṇa harettasya doṣānatyarthamūrcchitān pāko rakṣyaḥ prayatnena śiśnakṣayakaro hi saḥ"},{"type":"verse","number":"9","sanskrit":"प्रपौण्डरीकयष्ट्याह्वसरलागुरुदारुभिः सरास्नाकुष्ठपृथ्वीकैर्वातिके लेपसेचने","text":"prapauṇḍarīkayaṣṭyāhvasaralāgurudārubhiḥ sarāsnākuṣṭhapṛthvīkairvātike lepasecane"},{"type":"verse","number":"10","sanskrit":"निचुलैरण्डबीजानि यवगोधूमसक्तवः एतैश्च वातजं स्निग्धैः सुखोष्णैः सम्प्रलेपयेत्","text":"niculairaṇḍabījāni yavagodhūmasaktavaḥ etaiśca vātajaṃ snigdhaiḥ sukhoṣṇaiḥ sampralepayet"},{"type":"verse","number":"11","sanskrit":"गैरिकाञ्चनमञ्जिष्ठा मधुकोशीरपद्मकैः सचन्दनोत्पलैः स्निग्धः पैत्तिकं सम्प्रलेपयेत्","text":"gairikāñcanamañjiṣṭhā madhukośīrapadmakaiḥ sacandanotpalaiḥ snigdhaḥ paittikaṃ sampralepayet"},{"type":"verse","number":"12","sanskrit":"पद्मोत्पलमृणालैश्च ससर्जार्जुनवेतसैः सर्पिः स्निग्धैः समधुकैः पैत्तिकं सम्प्रलेपयेत्","text":"padmotpalamṛṇālaiśca sasarjārjunavetasaiḥ sarpiḥ snigdhaiḥ samadhukaiḥ paittikaṃ sampralepayet"},{"type":"verse","number":"13","sanskrit":"सेचयेच्च घृतक्षीरशर्करेक्षुमधूदकैः अथवाऽपि सुशीतेन कषायेण वटादिना","text":"secayecca ghṛtakṣīraśarkarekṣumadhūdakaiḥ athavā'pi suśītena kaṣāyeṇa vaṭādinā"},{"type":"verse","number":"14","sanskrit":"शालाजकर्णाश्वकर्णधवत्वग्भिः कफोत्थितम् सुरापिष्टाभिरुष्णाभिः सतैलाभिः प्रलेपयेत्","text":"śālājakarṇāśvakarṇadhavatvagbhiḥ kaphotthitam surāpiṣṭābhiruṣṇābhiḥ satailābhiḥ pralepayet"},{"type":"verse","number":"15","sanskrit":"आरग्वधादिक्वाथेन परिषेकञ्च दापयेत्","text":"āragvadhādikvāthena pariṣekañca dāpayet"},{"type":"verse","number":"16","sanskrit":"निम्बार्जुनाश्वत्थकदम्बशालजम्बूवटोदुम्बरवेतसैश्च प्रक्षालनालेपकृतानिकुर्याच्चूर्णं सपित्तास्रभवोपदंशे","text":"nimbārjunāśvatthakadambaśālajambūvaṭodumbaravetasaiśca prakṣālanālepakṛtānikuryāccūrṇaṃ sapittāsrabhavopadaṃśe"},{"type":"verse","number":"17","sanskrit":"त्वचो दारुहरिद्रा याः शङ्खनाभी रसाञ्जनम् लाक्षागोमयनिर्यासस्तैलं क्षौद्रं घृतं पयः","text":"tvaco dāruharidrā yāḥ śaṅkhanābhī rasāñjanam lākṣāgomayaniryāsastailaṃ kṣaudraṃ ghṛtaṃ payaḥ"},{"type":"verse","number":"18","sanskrit":"एभिस्तु पिष्टैस्तुल्यांशैरुपदंशं प्रलेपयेत् व्रणाश्च तेन शाम्यन्ति श्वयथुर्दाह एव च","text":"ebhistu piṣṭaistulyāṃśairupadaṃśaṃ pralepayet vraṇāśca tena śāmyanti śvayathurdāha eva ca"},{"type":"verse","number":"19","sanskrit":"उपदंशद्वयेऽप्येतां प्रत्याख्यायाचरेत्क्रियाम् तयोरेव च या योग्या वीक्ष्य दोषबलाबलम्","text":"upadaṃśadvaye'pyetāṃ pratyākhyāyācaretkriyām tayoreva ca yā yogyā vīkṣya doṣabalābalam"},{"type":"verse","number":"20","sanskrit":"शस्त्रेणोल्लेखयेत्क्वापि पाकमागतमाशु वै तमपोह्य तिलैः सर्पिः क्षौद्र युक्तैः प्रलेपयेत्","text":"śastreṇollekhayetkvāpi pākamāgatamāśu vai tamapohya tilaiḥ sarpiḥ kṣaudra yuktaiḥ pralepayet"},{"type":"verse","number":"21","sanskrit":"वटप्ररोहार्जुनजम्बुपथ्या लोध्रं हरिद्रा च हिताः प्रलेपे तथोपदंशेष्ववरोहणार्थं चूर्णञ्च कार्यं विमलाञ्जनेन","text":"vaṭaprarohārjunajambupathyā lodhraṃ haridrā ca hitāḥ pralepe tathopadaṃśeṣvavarohaṇārthaṃ cūrṇañca kāryaṃ vimalāñjanena"},{"type":"verse","number":"22","sanskrit":"त्रिफलायाः कषायेण भृङ्गराजरसेन वा व्रणप्रक्षालनं कार्यमुपदंशप्रशान्तये","text":"triphalāyāḥ kaṣāyeṇa bhṛṅgarājarasena vā vraṇaprakṣālanaṃ kāryamupadaṃśapraśāntaye"},{"type":"verse","number":"23","sanskrit":"जयाजपाऽश्वमारार्कशम्पाकानां दलैः क्रमात् कृतं प्रक्षालनं क्वाथं मेढ्रपाके प्रयोजयेत्","text":"jayājapā'śvamārārkaśampākānāṃ dalaiḥ kramāt kṛtaṃ prakṣālanaṃ kvāthaṃ meḍhrapāke prayojayet"},{"type":"verse","number":"24","sanskrit":"शम्पाकनिम्बत्रिफलाकिरातक्वाथं पिबेद्वा खदिरासनाभ्याम् सगुग्गुलुं वा त्रिफलायुतं वा सर्वोपदंशापहरःप्रयोगः","text":"śampākanimbatriphalākirātakvāthaṃ pibedvā khadirāsanābhyām sagugguluṃ vā triphalāyutaṃ vā sarvopadaṃśāpaharaḥprayogaḥ"},{"type":"verse","number":"25","sanskrit":"नीलोत्पलानि कुमुदं पद्मसौगन्धिकानि च उपदंशेषु चूर्णानि प्रदेहोऽय प्रशस्यते","text":"nīlotpalāni kumudaṃ padmasaugandhikāni ca upadaṃśeṣu cūrṇāni pradeho'ya praśasyate"},{"type":"verse","number":"26","sanskrit":"बन्धूकदलचूर्णेन दाडिमत्वग्रजोऽथवा गुण्डनं वृषणे शस्तं लेपः पूगफलेन वा","text":"bandhūkadalacūrṇena dāḍimatvagrajo'thavā guṇḍanaṃ vṛṣaṇe śastaṃ lepaḥ pūgaphalena vā"},{"type":"verse","number":"27","sanskrit":"सौराष्ट्री गैरिकं तुत्थं पुष्पकासीससैन्धवम् लोध्रं रसाञ्जनञ्चापि हरितालं मनः शिला","text":"saurāṣṭrī gairikaṃ tutthaṃ puṣpakāsīsasaindhavam lodhraṃ rasāñjanañcāpi haritālaṃ manaḥ śilā"},{"type":"verse","number":"28","sanskrit":"हरेणुकैले तु तथा समं संहृत्य चूर्णयेत् तच्चूर्णं क्षौद्र संयुक्तमुपदंशेषु पूजितम्","text":"hareṇukaile tu tathā samaṃ saṃhṛtya cūrṇayet taccūrṇaṃ kṣaudra saṃyuktamupadaṃśeṣu pūjitam"},{"type":"verse","number":"29","sanskrit":"पुटदग्धं कृतं भस्म हरितालं मनःशिला उपदंशविसर्पाणामेतद्धानिकरं परम्","text":"puṭadagdhaṃ kṛtaṃ bhasma haritālaṃ manaḥśilā upadaṃśavisarpāṇāmetaddhānikaraṃ param"},{"type":"verse","number":"30","sanskrit":"दहेत्कटाहे त्रिफलां तां मसीं मधुसैन्धवम् उपदंशे प्रलेपोऽय सद्यो रोपयति व्रणम्","text":"dahetkaṭāhe triphalāṃ tāṃ masīṃ madhusaindhavam upadaṃśe pralepo'ya sadyo ropayati vraṇam"},{"type":"verse","number":"31","sanskrit":"तिरीटाञ्जनवज्राक्षकोविदारेभकेशरैः लेपनं पुरुषव्याधौ जलपिष्टैः प्रशस्यते","text":"tirīṭāñjanavajrākṣakovidārebhakeśaraiḥ lepanaṃ puruṣavyādhau jalapiṣṭaiḥ praśasyate"},{"type":"verse","number":"32","sanskrit":"रसाञ्जनं शिरीषेण पथ्यया वा समन्वितम् सक्षौद्रं लेपनं योज्यं सर्वाङ्गगगदापहम्","text":"rasāñjanaṃ śirīṣeṇa pathyayā vā samanvitam sakṣaudraṃ lepanaṃ yojyaṃ sarvāṅgagagadāpaham"},{"type":"verse","number":"33","sanskrit":"भार्गीसम्भवशिखरिजमूलं भद्र श्रियं सुसम्पिष्टम् मनःशिला वै मधुना शमयत्युपदंशमचिरेण","text":"bhārgīsambhavaśikharijamūlaṃ bhadra śriyaṃ susampiṣṭam manaḥśilā vai madhunā śamayatyupadaṃśamacireṇa"},{"type":"verse","number":"34","sanskrit":"शतधौतं प्रयत्नेन लिङ्गोत्थमवचूर्णयेत् रोगं कासीसचूर्णेन पुरुषः सुखमाप्नुयात्","text":"śatadhautaṃ prayatnena liṅgotthamavacūrṇayet rogaṃ kāsīsacūrṇena puruṣaḥ sukhamāpnuyāt"},{"type":"verse","number":"35","sanskrit":"करवीरस्य मूलेन परिपिष्टेन वारिणा असाध्याऽपि व्रजत्यस्तं लिङ्गोत्था रुक्प्रलेपनात्","text":"karavīrasya mūlena paripiṣṭena vāriṇā asādhyā'pi vrajatyastaṃ liṅgotthā rukpralepanāt"},{"type":"verse","number":"36","sanskrit":"वरानिम्बार्जुनाश्वत्थखदिरासनवासकैः चूर्णितैर्गुग्गुलुसमैर्वटका अक्षसंमिताः","text":"varānimbārjunāśvatthakhadirāsanavāsakaiḥ cūrṇitairguggulusamairvaṭakā akṣasaṃmitāḥ"},{"type":"verse","number":"37","sanskrit":"कर्त्तव्या नाशयन्त्याशु सर्वांल्लिङ्गसमुत्थितान् उपदंशानसृग्दोषांस्तथा दुष्टव्रणानपि","text":"karttavyā nāśayantyāśu sarvāṃlliṅgasamutthitān upadaṃśānasṛgdoṣāṃstathā duṣṭavraṇānapi"},{"type":"verse","number":"38","sanskrit":"करञ्जनिम्बार्जुनशालजम्बूवटादिभिः कल्ककषायसिद्धम् सर्पिर्निहन्यादुपदंशदोषं सदाहपाकस्रुतिरागयुक्तम्","text":"karañjanimbārjunaśālajambūvaṭādibhiḥ kalkakaṣāyasiddham sarpirnihanyādupadaṃśadoṣaṃ sadāhapākasrutirāgayuktam"},{"type":"verse","number":"39","sanskrit":"भूनिम्बनिम्बत्रिफलापटोलकरञ्जधात्रीखदिरासनानाम् सतोयकल्कैर्घृतमाशु पक्वं सर्वोपदंशापहरं प्रदिष्टम्","text":"bhūnimbanimbatriphalāpaṭolakarañjadhātrīkhadirāsanānām satoyakalkairghṛtamāśu pakvaṃ sarvopadaṃśāpaharaṃ pradiṣṭam"},{"type":"verse","number":"40","sanskrit":"घृतानि यानि वक्ष्यामि कुष्ठे नाडीव्रणे व्रणे उपदंशे प्रयोज्यानि सेकाभ्यञ्जनभोजनैः","text":"ghṛtāni yāni vakṣyāmi kuṣṭhe nāḍīvraṇe vraṇe upadaṃśe prayojyāni sekābhyañjanabhojanaiḥ"},{"type":"verse","number":"41","sanskrit":"आगारधूमो रजनी सुराकिट्टं च तैस्त्रिभिः यथोत्तरैः पचेत्तैलं कण्डूशोथरुजाऽपहम् शोधनं रोपणं चैव ह्युपदंशहरं परम्","text":"āgāradhūmo rajanī surākiṭṭaṃ ca taistribhiḥ yathottaraiḥ pacettailaṃ kaṇḍūśotharujā'paham śodhanaṃ ropaṇaṃ caiva hyupadaṃśaharaṃ param"},{"type":"verse","number":"42","sanskrit":"गोजीविडङ्गयष्टीभिः सर्वगन्धैश्च संयुतम् एतत्सर्वोपदंशेषु तैलं रोपणमिष्यते","text":"gojīviḍaṅgayaṣṭībhiḥ sarvagandhaiśca saṃyutam etatsarvopadaṃśeṣu tailaṃ ropaṇamiṣyate"},{"type":"verse","number":"43","sanskrit":"जम्बुवेतसपत्राणि धात्रीपत्रं तथैव च नक्तमालस्य पत्राणि तद्वत्पद्मोत्पलानि च","text":"jambuvetasapatrāṇi dhātrīpatraṃ tathaiva ca naktamālasya patrāṇi tadvatpadmotpalāni ca"},{"type":"verse","number":"44","sanskrit":"एला चातिविषाऽम्रास्थि मधुकञ्च प्रियङ्गवः लाक्षा कालीयकं लोध्रं चन्दनं त्रिवृताह्वया","text":"elā cātiviṣā'mrāsthi madhukañca priyaṅgavaḥ lākṣā kālīyakaṃ lodhraṃ candanaṃ trivṛtāhvayā"},{"type":"verse","number":"45","sanskrit":"एतान्येकीकृतान्येव बस्तमूत्रेण पेषयेत् अक्षमात्रैरिमैर्द्र व्यैस्तैलप्रस्थं विपाचयेत्","text":"etānyekīkṛtānyeva bastamūtreṇa peṣayet akṣamātrairimairdra vyaistailaprasthaṃ vipācayet"},{"type":"verse","number":"46","sanskrit":"सर्वव्रणहरं तैलमेतत्सिद्धं न संशयः उपदंशहरं श्रेष्ठं मुनिभिः परिकीर्तितम्","text":"sarvavraṇaharaṃ tailametatsiddhaṃ na saṃśayaḥ upadaṃśaharaṃ śreṣṭhaṃ munibhiḥ parikīrtitam"},{"type":"verse","number":"47","sanskrit":"यस्य लिङ्गस्य मांसं तु शीर्यते मुष्कशेषतः","text":"yasya liṅgasya māṃsaṃ tu śīryate muṣkaśeṣataḥ"},{"type":"verse","number":"48","sanskrit":"तिक्तकोशातकीलाबुबीजं नागरसाधितम् तैलं हन्त्यविशेषेण व्रणं दुष्टमनेकधा","text":"tiktakośātakīlābubījaṃ nāgarasādhitam tailaṃ hantyaviśeṣeṇa vraṇaṃ duṣṭamanekadhā"},{"type":"verse","number":"49","sanskrit":"सेवेन्नित्यं यवान्नञ्च पानीयं कौपमेव च अर्शसां च्छिन्नदग्धानां क्रियां चात्र प्रयोजयेत्","text":"sevennityaṃ yavānnañca pānīyaṃ kaupameva ca arśasāṃ cchinnadagdhānāṃ kriyāṃ cātra prayojayet"},{"type":"verse","number":"50","sanskrit":"इत्येकपञ्चाशत्तम उपदंशाधिकारः समाप्तः","text":"ityekapañcāśattama upadaṃśādhikāraḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":52,"lang":"sa","content":[{"type":"heading","heading":"Линга-арша — болезни мочеполовой сферы"},{"type":"verse","number":"1","sanskrit":"अङ्कुरैरिव सञ्जातैरुपर्युपरि संस्थितैः क्रमेण जायते वर्त्तिस्ताम्रचूडशिखोपमा","text":"aṅkurairiva sañjātairuparyupari saṃsthitaiḥ krameṇa jāyate varttistāmracūḍaśikhopamā"},{"type":"verse","number":"2","sanskrit":"कोषस्याभ्यन्तरे सन्धौ पर्वसन्धिगतापि वा लिङ्गवर्त्तिरिति ख्याता लिङ्गार्श इति चापरे सवेदनापिच्छिला च दुश्चिकित्स्या त्रिदोषजा","text":"koṣasyābhyantare sandhau parvasandhigatāpi vā liṅgavarttiriti khyātā liṅgārśa iti cāpare savedanāpicchilā ca duścikitsyā tridoṣajā"},{"type":"verse","number":"3","sanskrit":"क्षारेण प्रदहेच्छित्त्वा लिङ्गवर्त्तिमशेषतः व्रणवच्चाचरेत्सम्यक् समं चूर्णमुपद्र वान्","text":"kṣāreṇa pradahecchittvā liṅgavarttimaśeṣataḥ vraṇavaccācaretsamyak samaṃ cūrṇamupadra vān"},{"type":"verse","number":"4","sanskrit":"स्वर्जिकातुत्थशैलेयमञ्जनं सरसाञ्जनम् मनःशिलाऽले च समं चूर्णं मांसाङ्कुरापहम्","text":"svarjikātutthaśaileyamañjanaṃ sarasāñjanam manaḥśilā'le ca samaṃ cūrṇaṃ māṃsāṅkurāpaham"},{"type":"verse","number":"5","sanskrit":"हरति घृतकुमारीपत्रमावेष्टेनेन ग्रथनविधिविशेषांश्चर्मकीलांस्तृतीये अहनि गुरुतरानप्यङ्गलब्धप्रतिष्ठान् विधिरिव विपरीतः पौरुषस्य प्रकारान्","text":"harati ghṛtakumārīpatramāveṣṭenena grathanavidhiviśeṣāṃścarmakīlāṃstṛtīye ahani gurutarānapyaṅgalabdhapratiṣṭhān vidhiriva viparītaḥ pauruṣasya prakārān"},{"type":"verse","number":"6","sanskrit":"शुभे तु चारटीमूलं वृषमूत्रेण पेषयेत् चर्मकीलान्निहन्त्याशु प्रलेपात्साधनोद्भवान्","text":"śubhe tu cāraṭīmūlaṃ vṛṣamūtreṇa peṣayet carmakīlānnihantyāśu pralepātsādhanodbhavān"},{"type":"verse","number":"7","sanskrit":"इति द्विपञ्चाशत्तमो लिङ्गार्शोऽधिकारः समाप्तः ५२","text":"iti dvipañcāśattamo liṅgārśo'dhikāraḥ samāptaḥ 52"}]},{"sthana":"Уттаракханда","number":53,"lang":"sa","content":[{"type":"heading","heading":"Шукадоша — поражения семени"},{"type":"verse","number":"1","sanskrit":"अक्रमाच्छेफसो वृद्धिं योऽभिवाञ्छति मूढधीः व्याधयस्तस्य जायन्ते दश चाष्टौ च शूकजाः","text":"akramācchephaso vṛddhiṃ yo'bhivāñchati mūḍhadhīḥ vyādhayastasya jāyante daśa cāṣṭau ca śūkajāḥ"},{"type":"verse","number":"2","sanskrit":"शूकदोषा दश चाष्टौ च भवन्ति गौरसर्षपसंस्थाना शूकदुर्भगहेतुका पिडिका श्लेष्मवाताभ्यां ज्ञेया सर्षपिका तु सा","text":"śūkadoṣā daśa cāṣṭau ca bhavanti gaurasarṣapasaṃsthānā śūkadurbhagahetukā piḍikā śleṣmavātābhyāṃ jñeyā sarṣapikā tu sā"},{"type":"verse","number":"3","sanskrit":"कठिना विषमैर्भुग्नैर्वायुनाष्ठीलिका भवेत्","text":"kaṭhinā viṣamairbhugnairvāyunāṣṭhīlikā bhavet"},{"type":"verse","number":"4","sanskrit":"शूकैर्यत्पूरितं शश्वद् ग्रथितं नाम तत्कफात्","text":"śūkairyatpūritaṃ śaśvad grathitaṃ nāma tatkaphāt"},{"type":"verse","number":"5","sanskrit":"कुम्भिका रक्तपित्तात्स्याज्जाम्बुवास्थिनिभा सिता","text":"kumbhikā raktapittātsyājjāmbuvāsthinibhā sitā"},{"type":"verse","number":"6","sanskrit":"अलजी स्यात्तथा यादृक्प्रमेहपिडका तथा सा च रक्तासिता स्फोटचिता च कथिता बुधैः","text":"alajī syāttathā yādṛkpramehapiḍakā tathā sā ca raktāsitā sphoṭacitā ca kathitā budhaiḥ"},{"type":"verse","number":"7","sanskrit":"मृदितं पीडितं यत्तु संरब्धं वातकोपतः","text":"mṛditaṃ pīḍitaṃ yattu saṃrabdhaṃ vātakopataḥ"},{"type":"verse","number":"8","sanskrit":"पाणिभ्यां भृशसंमूढे संमूढ पिडिका भवेत्","text":"pāṇibhyāṃ bhṛśasaṃmūḍhe saṃmūḍha piḍikā bhavet"},{"type":"verse","number":"9","sanskrit":"दीर्घा बह्व्यश्चपिडका दीर्यन्ते मध्यतस्तु याः सोवमन्थः कफासृग्भ्यां वेदनारोमहर्षकृत्","text":"dīrghā bahvyaścapiḍakā dīryante madhyatastu yāḥ sovamanthaḥ kaphāsṛgbhyāṃ vedanāromaharṣakṛt"},{"type":"verse","number":"10","sanskrit":"पिडिका पिडिकाव्याप्ता पित्तशोणितसम्भवा पद्मकर्णिकसंस्थाना ज्ञेया पुष्करिकेति सा","text":"piḍikā piḍikāvyāptā pittaśoṇitasambhavā padmakarṇikasaṃsthānā jñeyā puṣkariketi sā"},{"type":"verse","number":"11","sanskrit":"स्पर्शहानिन्तु जनयेच्छोणितं शूकदूषितम्","text":"sparśahānintu janayecchoṇitaṃ śūkadūṣitam"},{"type":"verse","number":"12","sanskrit":"मुद्गमाषोपमा रक्ता रक्तपित्तोद्भवा च या एषोत्तमाख्यपिडका शूकाजीर्णसमुद्भवा","text":"mudgamāṣopamā raktā raktapittodbhavā ca yā eṣottamākhyapiḍakā śūkājīrṇasamudbhavā"},{"type":"verse","number":"13","sanskrit":"छिद्रै रणुमुखैलिङ्गं चिरं यस्य समन्ततः वातशोणितजो व्याधिर्विज्ञेयःशतपोनकः","text":"chidrai raṇumukhailiṅgaṃ ciraṃ yasya samantataḥ vātaśoṇitajo vyādhirvijñeyaḥśataponakaḥ"},{"type":"verse","number":"14","sanskrit":"वातपित्तकृतो ज्ञेयस्त्वक्पाको ज्वरदाहकृत्","text":"vātapittakṛto jñeyastvakpāko jvaradāhakṛt"},{"type":"verse","number":"15","sanskrit":"कृष्णैः स्फोटैः सरक्ताभिः पिडकाभिर्निपीडितम् लिङ्गं वास्तुरुजश्चोग्रा ज्ञेयं तच्छोणितार्बुदम्","text":"kṛṣṇaiḥ sphoṭaiḥ saraktābhiḥ piḍakābhirnipīḍitam liṅgaṃ vāsturujaścogrā jñeyaṃ tacchoṇitārbudam"},{"type":"verse","number":"16","sanskrit":"मांसदुष्टं विजानीयादर्बुदं मांससम्भवम्","text":"māṃsaduṣṭaṃ vijānīyādarbudaṃ māṃsasambhavam"},{"type":"verse","number":"17","sanskrit":"शीर्यन्ते यस्य मांसानि यस्य सर्वाश्च वेदनाः विद्यात् तं मांसपाकं तु सर्वदोषकृतं भिषक्","text":"śīryante yasya māṃsāni yasya sarvāśca vedanāḥ vidyāt taṃ māṃsapākaṃ tu sarvadoṣakṛtaṃ bhiṣak"},{"type":"verse","number":"18","sanskrit":"विद्र धिं सन्निपातेन यथोक्तमभिनिर्दिशेत्","text":"vidra dhiṃ sannipātena yathoktamabhinirdiśet"},{"type":"verse","number":"19","sanskrit":"कृष्णानि चित्राण्यथवा शुक्लानि सविषाणि तु पातितानि पचन्त्याशु मेढ्रं निरवशेषतः १८ कालानि भूत्वा मांसानि शीर्यन्ते यस्य देहिनः सन्निपातसमुत्थांश्च तान्विद्यात्तिलकालकान्","text":"kṛṣṇāni citrāṇyathavā śuklāni saviṣāṇi tu pātitāni pacantyāśu meḍhraṃ niravaśeṣataḥ 18 kālāni bhūtvā māṃsāni śīryante yasya dehinaḥ sannipātasamutthāṃśca tānvidyāttilakālakān"},{"type":"verse","number":"20","sanskrit":"तत्र मांसार्बुदं यच्च मांसपाकश्च यःस्मृतः विद्र धिश्च न सिध्यन्ति ये च स्युस्तिलकालकाः","text":"tatra māṃsārbudaṃ yacca māṃsapākaśca yaḥsmṛtaḥ vidra dhiśca na sidhyanti ye ca syustilakālakāḥ"},{"type":"verse","number":"21","sanskrit":"शूकदोषेषु सर्वेषु विषघ्नीं कारयेत्क्रियाम् जलौकाभिर्हरेद्र क्तं रेचनं लघु भोजयेत् गुग्गुलुं पाचयेच्चापि त्रिफलाक्वाथसंयुतम् क्षीरेण लेपसेकांश्च शीतेनैव हि कारयेत्","text":"śūkadoṣeṣu sarveṣu viṣaghnīṃ kārayetkriyām jalaukābhirharedra ktaṃ recanaṃ laghu bhojayet gugguluṃ pācayeccāpi triphalākvāthasaṃyutam kṣīreṇa lepasekāṃśca śītenaiva hi kārayet"},{"type":"verse","number":"22","sanskrit":"दार्वीसुरसयष्ट्याह्वैर्गृहधूमनिशायुतैः सम्पक्वं तैलमभ्यङ्गान्मेढ्ररोगं हि नाशयेत्","text":"dārvīsurasayaṣṭyāhvairgṛhadhūmaniśāyutaiḥ sampakvaṃ tailamabhyaṅgānmeḍhrarogaṃ hi nāśayet"},{"type":"verse","number":"23","sanskrit":"रसाञ्जनं साह्वयमेकमेव प्रलेपमात्रेण नयत्प्रशान्तिम् सपूतिपूयव्रणशोथकण्डूशूलान्वितं सर्वमनङ्गरोगम्","text":"rasāñjanaṃ sāhvayamekameva pralepamātreṇa nayatpraśāntim sapūtipūyavraṇaśothakaṇḍūśūlānvitaṃ sarvamanaṅgarogam"},{"type":"verse","number":"24","sanskrit":"इति त्रिपञ्चाशत्तमः शूकदोषाधिकारः समाप्तः ५३","text":"iti tripañcāśattamaḥ śūkadoṣādhikāraḥ samāptaḥ 53"}]},{"sthana":"Уттаракханда","number":54,"lang":"sa","content":[{"type":"heading","heading":"Куштха — кожные болезни"},{"type":"verse","number":"1","sanskrit":"विरोधीन्यन्नपानानि द्र वस्निग्धगुरूणि च भजतामागतां छर्दिं वेगांश्चान्यान्प्रतिघ्नताम्","text":"virodhīnyannapānāni dra vasnigdhagurūṇi ca bhajatāmāgatāṃ chardiṃ vegāṃścānyānpratighnatām"},{"type":"verse","number":"2","sanskrit":"व्यायाममग्नितापञ्चाप्यतिभुक्त्वा निषेविणाम् शीतोष्णलङ्घनाहारान्क्रमं मुक्त्वा निषेविणाम्","text":"vyāyāmamagnitāpañcāpyatibhuktvā niṣeviṇām śītoṣṇalaṅghanāhārānkramaṃ muktvā niṣeviṇām"},{"type":"verse","number":"3","sanskrit":"घर्मश्रमभयार्त्तानां द्रुतं शीताम्बुसेविनाम् अजीर्णाध्यशिनां चापि पञ्चकर्मापचारिणाम्","text":"gharmaśramabhayārttānāṃ drutaṃ śītāmbusevinām ajīrṇādhyaśināṃ cāpi pañcakarmāpacāriṇām"},{"type":"verse","number":"4","sanskrit":"नवान्नदधिमत्स्यादिलवणाम्लनिषेविणाम् माषमूलकपिष्टान्नतिलक्षीरगुडाशिनाम्","text":"navānnadadhimatsyādilavaṇāmlaniṣeviṇām māṣamūlakapiṣṭānnatilakṣīraguḍāśinām"},{"type":"verse","number":"5","sanskrit":"व्यवायं चाप्यजीर्णेऽन्ने दिवानिद्रां निषेविणाम् विप्रान्गुरून्धर्षयतां पापं कर्म च कुर्वताम्","text":"vyavāyaṃ cāpyajīrṇe'nne divānidrāṃ niṣeviṇām viprāngurūndharṣayatāṃ pāpaṃ karma ca kurvatām"},{"type":"verse","number":"6","sanskrit":"वातादयस्त्रयो दोषास्त्वग्रक्तं मांसमम्बु च दूषयन्ति स कुष्ठानां सप्तको द्र व्यसङ्ग्रहः अतः कुष्ठानि जायन्ते सप्तधैकादशैव च","text":"vātādayastrayo doṣāstvagraktaṃ māṃsamambu ca dūṣayanti sa kuṣṭhānāṃ saptako dra vyasaṅgrahaḥ ataḥ kuṣṭhāni jāyante saptadhaikādaśaiva ca"},{"type":"verse","number":"7","sanskrit":"पूर्वं त्रिकं तथा सिध्मं ततः काकणकं तथा पुण्डरीकर्क्षजिह्वके महाकुष्ठानि सप्त च","text":"pūrvaṃ trikaṃ tathā sidhmaṃ tataḥ kākaṇakaṃ tathā puṇḍarīkarkṣajihvake mahākuṣṭhāni sapta ca"},{"type":"verse","number":"8","sanskrit":"एककुष्ठं स्मृतं पूर्वं गजचर्म ततः स्मृतम् ततश्चर्मदलं प्रोक्तं ततश्चापि विचर्चिका","text":"ekakuṣṭhaṃ smṛtaṃ pūrvaṃ gajacarma tataḥ smṛtam tataścarmadalaṃ proktaṃ tataścāpi vicarcikā"},{"type":"verse","number":"9","sanskrit":"विपादिकाऽभिधा सैव पामा कच्छूस्ततः परम् दद्रुविस्फोटकिटिभालसकानि च वेष्टितम्","text":"vipādikā'bhidhā saiva pāmā kacchūstataḥ param dadruvisphoṭakiṭibhālasakāni ca veṣṭitam"},{"type":"verse","number":"10","sanskrit":"क्षुद्र कुष्ठानि चैतानि कथितानि भिषग्वरैः","text":"kṣudra kuṣṭhāni caitāni kathitāni bhiṣagvaraiḥ"},{"type":"verse","number":"11","sanskrit":"कुष्ठानि सप्तधा दोषैः पृथग्द्वन्द्वैः समागतैः सर्वेष्वपि त्रिदोषेषु व्यपदेशोऽधिकत्वतः","text":"kuṣṭhāni saptadhā doṣaiḥ pṛthagdvandvaiḥ samāgataiḥ sarveṣvapi tridoṣeṣu vyapadeśo'dhikatvataḥ"},{"type":"verse","number":"12","sanskrit":"अतिश्लक्ष्णः खरस्पर्शः स्वेदास्वेदविवर्णता दाहःकण्डूस्त्वचि स्वापस्तोदः कोठोन्नतिः क्लमः","text":"atiślakṣṇaḥ kharasparśaḥ svedāsvedavivarṇatā dāhaḥkaṇḍūstvaci svāpastodaḥ koṭhonnatiḥ klamaḥ"},{"type":"verse","number":"13","sanskrit":"व्रणानामधिकं शूलं शीघ्रोत्पत्तिश्चिरस्थितिः रूढानामपि रूक्षत्वं निमित्तेऽल्पेऽपि कोपनम् रोमहर्षोऽसृजः कार्ष्ण्यं कुष्ठलक्षणमग्रजम्","text":"vraṇānāmadhikaṃ śūlaṃ śīghrotpattiścirasthitiḥ rūḍhānāmapi rūkṣatvaṃ nimitte'lpe'pi kopanam romaharṣo'sṛjaḥ kārṣṇyaṃ kuṣṭhalakṣaṇamagrajam"},{"type":"verse","number":"14","sanskrit":"दूषयन्ति श्लथीकृत्य निश्चलत्वादितस्ततः त्वचः कुर्वन्ति वैवर्ण्यं दोषाः कुष्ठमुशन्ति तम्","text":"dūṣayanti ślathīkṛtya niścalatvāditastataḥ tvacaḥ kurvanti vaivarṇyaṃ doṣāḥ kuṣṭhamuśanti tam"},{"type":"verse","number":"15","sanskrit":"वातेन कुष्ठं कापालं पित्तेनौदुम्बरं कफात् मण्डलाख्यं विचर्ची च ॠक्षाख्यं वातपित्ततः","text":"vātena kuṣṭhaṃ kāpālaṃ pittenaudumbaraṃ kaphāt maṇḍalākhyaṃ vicarcī ca ṝkṣākhyaṃ vātapittataḥ"},{"type":"verse","number":"16","sanskrit":"चर्मैककुष्ठकिटिभसिध्मालसविपादिकाः वातश्लेष्मोद्भवाः पित्तकफाद्दद्रुशतारुषी","text":"carmaikakuṣṭhakiṭibhasidhmālasavipādikāḥ vātaśleṣmodbhavāḥ pittakaphāddadruśatāruṣī"},{"type":"verse","number":"17","sanskrit":"पुण्डरीकं सविस्फोटं पामा चर्मदलं तथा सर्वैरेवोल्वणैर्दोषैराहुः काकणकं बुधाः","text":"puṇḍarīkaṃ savisphoṭaṃ pāmā carmadalaṃ tathā sarvairevolvaṇairdoṣairāhuḥ kākaṇakaṃ budhāḥ"},{"type":"verse","number":"18","sanskrit":"कृष्णारुणकपालाभं यद्रू क्षं परुषं तनु कापालं तोदबहुलं तत्कुष्ठं विषमं स्मृतम्","text":"kṛṣṇāruṇakapālābhaṃ yadrū kṣaṃ paruṣaṃ tanu kāpālaṃ todabahulaṃ tatkuṣṭhaṃ viṣamaṃ smṛtam"},{"type":"verse","number":"19","sanskrit":"उदुम्बरफलाभासं कुष्ठमौदुम्बरं वदेत् रुग्दाहरागकण्डूभिः परीतं रोमपिञ्जरम्","text":"udumbaraphalābhāsaṃ kuṣṭhamaudumbaraṃ vadet rugdāharāgakaṇḍūbhiḥ parītaṃ romapiñjaram"},{"type":"verse","number":"20","sanskrit":"श्वेतरक्तं स्थिरं स्त्यानं स्निग्धमुत्सन्नमण्डलम् कृच्छ्रमन्योऽन्यसंसक्तं कुष्ठं मण्डलमुच्यते","text":"śvetaraktaṃ sthiraṃ styānaṃ snigdhamutsannamaṇḍalam kṛcchramanyo'nyasaṃsaktaṃ kuṣṭhaṃ maṇḍalamucyate"},{"type":"verse","number":"21","sanskrit":"श्वेतताम्रञ्च तनु यद्र जो घृष्टं विमुञ्चति प्रायेणोरसि तत्सिध्ममलाबुकुसुमोपमम्","text":"śvetatāmrañca tanu yadra jo ghṛṣṭaṃ vimuñcati prāyeṇorasi tatsidhmamalābukusumopamam"},{"type":"verse","number":"22","sanskrit":"यत्काकणन्तिकावर्णमपाकं तीव्रवेदनम् त्रिदोषलिङ्गं तत्कुष्ठं काकणं नैव सिध्यति","text":"yatkākaṇantikāvarṇamapākaṃ tīvravedanam tridoṣaliṅgaṃ tatkuṣṭhaṃ kākaṇaṃ naiva sidhyati"},{"type":"verse","number":"23","sanskrit":"तच्छ्वेतं रक्तपर्यन्तं पुण्डरीकदलोपमम् सरागञ्चैव सोत्सेधं पुण्डरीकं कफोल्वणम्","text":"tacchvetaṃ raktaparyantaṃ puṇḍarīkadalopamam sarāgañcaiva sotsedhaṃ puṇḍarīkaṃ kapholvaṇam"},{"type":"verse","number":"24","sanskrit":"कर्कशं रक्तपर्यन्तमन्तः श्यावं सवेदनम् यदृक्षजिह्वासंस्थानमृक्षजिह्वं तदुच्यते","text":"karkaśaṃ raktaparyantamantaḥ śyāvaṃ savedanam yadṛkṣajihvāsaṃsthānamṛkṣajihvaṃ taducyate"},{"type":"verse","number":"25","sanskrit":"अस्वेदनं महावास्तु यन्मत्स्यशकलोपमम् तदेककुष्ठं चर्माख्यं बहलं गजचर्मवत्","text":"asvedanaṃ mahāvāstu yanmatsyaśakalopamam tadekakuṣṭhaṃ carmākhyaṃ bahalaṃ gajacarmavat"},{"type":"verse","number":"26","sanskrit":"रक्तं सशूलं कण्डूमत्सस्फोटं दलयत्यपि तच्चर्मदलमाख्यातं स्पर्शस्यासहनञ्च यत्","text":"raktaṃ saśūlaṃ kaṇḍūmatsasphoṭaṃ dalayatyapi taccarmadalamākhyātaṃ sparśasyāsahanañca yat"},{"type":"verse","number":"27","sanskrit":"सकण्डूः पिडका श्यावा बहुस्रावा विचर्चिका","text":"sakaṇḍūḥ piḍakā śyāvā bahusrāvā vicarcikā"},{"type":"verse","number":"28","sanskrit":"वैपादिकं पाणिपादस्फुटनं तीव्रवेदनम्","text":"vaipādikaṃ pāṇipādasphuṭanaṃ tīvravedanam"},{"type":"verse","number":"29","sanskrit":"सूक्ष्मा बह्व्यः स्राववत्यः प्रदाहाः पामेत्युक्ताः पिडकाः कण्डुमत्यः","text":"sūkṣmā bahvyaḥ srāvavatyaḥ pradāhāḥ pāmetyuktāḥ piḍakāḥ kaṇḍumatyaḥ"},{"type":"verse","number":"30","sanskrit":"सैव स्फोटस्तीव्रदाहैरुपेता ज्ञेया पाण्योः कच्छुरुग्रा स्फिचोश्च","text":"saiva sphoṭastīvradāhairupetā jñeyā pāṇyoḥ kacchurugrā sphicośca"},{"type":"verse","number":"31","sanskrit":"सकण्डूरागपिडकं दद्रुर्मण्डलमुद्गतम्","text":"sakaṇḍūrāgapiḍakaṃ dadrurmaṇḍalamudgatam"},{"type":"verse","number":"32","sanskrit":"स्फोटाः श्यावारुणाभासा विस्फोटाः स्युस्तनुत्वचः","text":"sphoṭāḥ śyāvāruṇābhāsā visphoṭāḥ syustanutvacaḥ"},{"type":"verse","number":"33","sanskrit":"श्यामं किणखरस्पर्शं परुषं किटिभं स्मृतम्","text":"śyāmaṃ kiṇakharasparśaṃ paruṣaṃ kiṭibhaṃ smṛtam"},{"type":"verse","number":"34","sanskrit":"कण्डूमद्भिः सरागैश्च गण्डैरलसकं चितम्","text":"kaṇḍūmadbhiḥ sarāgaiśca gaṇḍairalasakaṃ citam"},{"type":"verse","number":"35","sanskrit":"रक्तश्यावं सदाहार्त्ति शतारुःस्याद् बहुव्रणम्","text":"raktaśyāvaṃ sadāhārtti śatāruḥsyād bahuvraṇam"},{"type":"verse","number":"36","sanskrit":"त्वक्स्थे वैवर्ण्यमङ्गेषु कुष्ठे रौक्ष्यञ्च जायते त्वक्स्वापो रोमहर्षश्च स्वेदस्यातिप्रवर्त्तनम्","text":"tvaksthe vaivarṇyamaṅgeṣu kuṣṭhe raukṣyañca jāyate tvaksvāpo romaharṣaśca svedasyātipravarttanam"},{"type":"verse","number":"37","sanskrit":"कण्डूर्विपूयकश्चैव कुष्ठे शोणितसम्भवे","text":"kaṇḍūrvipūyakaścaiva kuṣṭhe śoṇitasambhave"},{"type":"verse","number":"38","sanskrit":"बाहुल्यं वक्त्रशोषश्च कार्कश्यं पिडकोद्गमः तोदः स्फोटः स्थिरत्वञ्च कुष्ठे मांससमाश्रिते","text":"bāhulyaṃ vaktraśoṣaśca kārkaśyaṃ piḍakodgamaḥ todaḥ sphoṭaḥ sthiratvañca kuṣṭhe māṃsasamāśrite"},{"type":"verse","number":"39","sanskrit":"कौण्यं गतिक्षयोऽङ्गानां सम्भेदः क्षतसर्पणम् मेदः स्थानगते लिङ्गं प्रागुक्तानि तथैव च","text":"kauṇyaṃ gatikṣayo'ṅgānāṃ sambhedaḥ kṣatasarpaṇam medaḥ sthānagate liṅgaṃ prāguktāni tathaiva ca"},{"type":"verse","number":"40","sanskrit":"नासाभङ्गोऽक्षिरागश्च क्षतेषु कृमिसम्भवः स्वरोपघातः पीडा च भवेत्कुष्ठेऽस्थिमज्जगे","text":"nāsābhaṅgo'kṣirāgaśca kṣateṣu kṛmisambhavaḥ svaropaghātaḥ pīḍā ca bhavetkuṣṭhe'sthimajjage"},{"type":"verse","number":"41","sanskrit":"दम्पत्योः कुष्ठबाहुल्याद् दुष्टशोणितशुक्रयोः यदपत्यं तयोर्जातं ज्ञेयं तदपि कुष्ठितम्","text":"dampatyoḥ kuṣṭhabāhulyād duṣṭaśoṇitaśukrayoḥ yadapatyaṃ tayorjātaṃ jñeyaṃ tadapi kuṣṭhitam"},{"type":"verse","number":"42","sanskrit":"खरं श्यावारुणं रूक्षं वातकुष्ठं सवेदनम् पित्तात्प्रकुथितं दाहरागस्रावान्वितं मतम् कफोत्क्लेदि घनं स्निग्धं सकण्डूशैत्यगौरवम् द्विलिङ्गं द्वन्द्वजं कुष्ठं त्रिलिङ्गं सान्निपातिकम्","text":"kharaṃ śyāvāruṇaṃ rūkṣaṃ vātakuṣṭhaṃ savedanam pittātprakuthitaṃ dāharāgasrāvānvitaṃ matam kaphotkledi ghanaṃ snigdhaṃ sakaṇḍūśaityagauravam dviliṅgaṃ dvandvajaṃ kuṣṭhaṃ triliṅgaṃ sānnipātikam"},{"type":"verse","number":"43","sanskrit":"साध्यं त्वग्रक्तमांसस्थं वातश्लेष्माधिकञ्च यत् मेदोगं द्वन्द्वजं याप्यं वर्ज्यं मज्जास्थिसंश्रितम् कृमिकृद् दाहमन्दाग्निसंयुक्तं यत् त्रिदोषजम्","text":"sādhyaṃ tvagraktamāṃsasthaṃ vātaśleṣmādhikañca yat medogaṃ dvandvajaṃ yāpyaṃ varjyaṃ majjāsthisaṃśritam kṛmikṛd dāhamandāgnisaṃyuktaṃ yat tridoṣajam"},{"type":"verse","number":"44","sanskrit":"प्रभिन्नं प्रस्रुताङ्गञ्च रक्तनेत्रं हतस्वरम् पञ्चकर्मगुणातीतं कुष्ठं हन्तीह कुष्ठिनम्","text":"prabhinnaṃ prasrutāṅgañca raktanetraṃ hatasvaram pañcakarmaguṇātītaṃ kuṣṭhaṃ hantīha kuṣṭhinam"},{"type":"verse","number":"45","sanskrit":"कुष्ठैकसम्भवं श्वित्रं किलासं चारुणं भवेत् निर्दिष्टमपरिस्रावि त्रिधातूद्भवसंश्रयम्","text":"kuṣṭhaikasambhavaṃ śvitraṃ kilāsaṃ cāruṇaṃ bhavet nirdiṣṭamaparisrāvi tridhātūdbhavasaṃśrayam"},{"type":"verse","number":"46","sanskrit":"वाताद्रू क्षारुणं पित्तात्ताम्रं कमलपत्रवत् सदाहं रोमविध्वंसि कफाच्छ्वेतं घनं गुरु सकण्डूकं क्रमाद्र क्तमांसमेदःसु चादिशेत् वर्णेनैवेदृगुभयं कृच्छ्रं तच्चोत्तरोत्तरम्","text":"vātādrū kṣāruṇaṃ pittāttāmraṃ kamalapatravat sadāhaṃ romavidhvaṃsi kaphācchvetaṃ ghanaṃ guru sakaṇḍūkaṃ kramādra ktamāṃsamedaḥsu cādiśet varṇenaivedṛgubhayaṃ kṛcchraṃ taccottarottaram"},{"type":"verse","number":"47","sanskrit":"अशुक्लरोमाबहलमसंश्लिष्टमथो नवम् अनग्निदग्धजं साध्यं श्वित्रं वर्ज्यमतोऽन्यथा","text":"aśuklaromābahalamasaṃśliṣṭamatho navam anagnidagdhajaṃ sādhyaṃ śvitraṃ varjyamato'nyathā"},{"type":"verse","number":"48","sanskrit":"गुह्यपाणितलौष्ठेषु जातमप्यचिरन्तनम् वर्जनीयं विशेषेण किलासं सिद्धिमिच्छता","text":"guhyapāṇitalauṣṭheṣu jātamapyacirantanam varjanīyaṃ viśeṣeṇa kilāsaṃ siddhimicchatā"},{"type":"verse","number":"49","sanskrit":"प्रसङ्गाद्गात्रसंस्पर्शान्निश्वासात्सहभोजनात् एकशय्याऽसनाच्चापिवस्त्रमाल्यानुलेपनात् कण्डूकुष्ठोपदंशाश्च भूतोन्मादव्रणज्वराः औपसर्गिकरोगाश्च सङ्क्रामन्ति नरान्नरम्","text":"prasaṅgādgātrasaṃsparśānniśvāsātsahabhojanāt ekaśayyā'sanāccāpivastramālyānulepanāt kaṇḍūkuṣṭhopadaṃśāśca bhūtonmādavraṇajvarāḥ aupasargikarogāśca saṅkrāmanti narānnaram"},{"type":"verse","number":"50","sanskrit":"म्रियते यदि कुष्ठेन पुनर्जातस्य तद्भवेत् अतो निन्दितरोगोऽय कुष्ठं कष्टं प्रकीर्त्तितम्","text":"mriyate yadi kuṣṭhena punarjātasya tadbhavet ato ninditarogo'ya kuṣṭhaṃ kaṣṭaṃ prakīrttitam"},{"type":"verse","number":"51","sanskrit":"वातोत्तरेषु सर्पिर्वमनं श्लेष्मोत्तरेषु कुष्ठेषु पित्तोत्तरेषु लेपः सेको रक्तस्य मोचनं श्रेष्ठम्","text":"vātottareṣu sarpirvamanaṃ śleṣmottareṣu kuṣṭheṣu pittottareṣu lepaḥ seko raktasya mocanaṃ śreṣṭham"},{"type":"verse","number":"52","sanskrit":"पथ्याकरञ्जसिद्धार्थनिशाऽवल्गुजसैन्धवैः विडङ्गसहितैः पिष्टैर्लेपो मूत्रेण कुष्ठनुत्","text":"pathyākarañjasiddhārthaniśā'valgujasaindhavaiḥ viḍaṅgasahitaiḥ piṣṭairlepo mūtreṇa kuṣṭhanut"},{"type":"verse","number":"53","sanskrit":"सोमराजीभवं चूर्णं शृङ्गबेरसमन्वितम् उद्वर्त्तनमिदं हन्ति कुष्ठमुग्रं कृतास्पदम्","text":"somarājībhavaṃ cūrṇaṃ śṛṅgaberasamanvitam udvarttanamidaṃ hanti kuṣṭhamugraṃ kṛtāspadam"},{"type":"verse","number":"54","sanskrit":"रसायनं प्रवक्ष्यामि ब्रह्मणा यदुदाहृतम् मार्कण्डेयप्रभृतिभिर्यत्प्रयुक्तं महर्षिभिः","text":"rasāyanaṃ pravakṣyāmi brahmaṇā yadudāhṛtam mārkaṇḍeyaprabhṛtibhiryatprayuktaṃ maharṣibhiḥ"},{"type":"verse","number":"55","sanskrit":"पुष्पकाले तु पुष्पाणि फलकाले फलानि च संगृह्य पिचुमर्दस्य त्वङ्मूलानि दलानि च","text":"puṣpakāle tu puṣpāṇi phalakāle phalāni ca saṃgṛhya picumardasya tvaṅmūlāni dalāni ca"},{"type":"verse","number":"56","sanskrit":"द्विरंशानि समाहृत्य भागिकानि प्रकल्पयेत् त्रिफला त्र्यूषणं ब्राह्मी श्वदंष्ट्राऽरुष्कराग्नयः","text":"dviraṃśāni samāhṛtya bhāgikāni prakalpayet triphalā tryūṣaṇaṃ brāhmī śvadaṃṣṭrā'ruṣkarāgnayaḥ"},{"type":"verse","number":"57","sanskrit":"विडङ्गसारवाराहीलोहचूर्णामृताः समाः निशाद्वयावल्गुजकं व्याधिघातः सशर्करः","text":"viḍaṅgasāravārāhīlohacūrṇāmṛtāḥ samāḥ niśādvayāvalgujakaṃ vyādhighātaḥ saśarkaraḥ"},{"type":"verse","number":"58","sanskrit":"कुष्ठमिन्द्र यवाः पाठाः चूर्णमेषां तु संयुतम् खादिरासननिम्बानां घनक्वाथेन भावयेत् सप्तधा पञ्चनिम्बं तु मार्कवस्यरसेन च स्निग्धः शुद्धतनुर्धीमान्योजयेत्तच्छुभे दिने","text":"kuṣṭhamindra yavāḥ pāṭhāḥ cūrṇameṣāṃ tu saṃyutam khādirāsananimbānāṃ ghanakvāthena bhāvayet saptadhā pañcanimbaṃ tu mārkavasyarasena ca snigdhaḥ śuddhatanurdhīmānyojayettacchubhe dine"},{"type":"verse","number":"59","sanskrit":"मधुना तिक्तहविषा खदिरासनवारिणा लेह्यमुष्णाम्भसा वाऽपि कालवृद्ध्या पलं भवेत् जीर्णे तस्मिन्समश्नीयात्स्निग्धं लघु हितञ्च यत्","text":"madhunā tiktahaviṣā khadirāsanavāriṇā lehyamuṣṇāmbhasā vā'pi kālavṛddhyā palaṃ bhavet jīrṇe tasminsamaśnīyātsnigdhaṃ laghu hitañca yat"},{"type":"verse","number":"60","sanskrit":"विचर्चिकौदुम्बर पुण्डरीककापालदद्रू किटिभालसादि शतारुविस्फोटविसर्पमालाः कफप्रकोपं त्रिविधं किलासम्","text":"vicarcikaudumbara puṇḍarīkakāpāladadrū kiṭibhālasādi śatāruvisphoṭavisarpamālāḥ kaphaprakopaṃ trividhaṃ kilāsam"},{"type":"verse","number":"61","sanskrit":"भगन्दरश्लीपदवातरक्तजडान्ध नाडीव्रणशीर्षरोगान् सर्वान्प्रमेहान्प्रदरांश्च सर्वान्दंष्ट्राविषं मूलविषं निहन्ति","text":"bhagandaraślīpadavātaraktajaḍāndha nāḍīvraṇaśīrṣarogān sarvānpramehānpradarāṃśca sarvāndaṃṣṭrāviṣaṃ mūlaviṣaṃ nihanti"},{"type":"verse","number":"62","sanskrit":"स्थूलोदरः सिंहकृशोदरः स्यात्सुश्लिष्टसन्धिर्मधुनोपयोगात् सदोपयोगादपि ये दशन्ति सर्पादयो यान्ति विनाशमाशु","text":"sthūlodaraḥ siṃhakṛśodaraḥ syātsuśliṣṭasandhirmadhunopayogāt sadopayogādapi ye daśanti sarpādayo yānti vināśamāśu"},{"type":"verse","number":"63","sanskrit":"जीवेच्चिरं व्याधिजराविमुक्तः शुभे रतश्चन्द्र समानकान्तिः","text":"jīvecciraṃ vyādhijarāvimuktaḥ śubhe rataścandra samānakāntiḥ"},{"type":"verse","number":"64","sanskrit":"शशिलेखा पञ्चपलं तावद्गिरिजस्य गुग्गुलोस्तु दश ताप्यस्य पलत्रितयं द्वे लोहस्रावणीकयोश्च पले","text":"śaśilekhā pañcapalaṃ tāvadgirijasya guggulostu daśa tāpyasya palatritayaṃ dve lohasrāvaṇīkayośca pale"},{"type":"verse","number":"65","sanskrit":"त्रिफलाकरञ्जपल्लवखदिरगुडूचीत्रिवृद्दन्त्यः मुस्ताविडङ्गरजनीकुटजत्वङ्निम्बवह्निसंपाकाः","text":"triphalākarañjapallavakhadiraguḍūcītrivṛddantyaḥ mustāviḍaṅgarajanīkuṭajatvaṅnimbavahnisaṃpākāḥ"},{"type":"verse","number":"66","sanskrit":"एतै रचितां वटिकां मधुसंमिश्रां गिलेत्प्रातः गोमूत्रेण च कुष्ठं नुदत्यसृग्वातमचिरेण","text":"etai racitāṃ vaṭikāṃ madhusaṃmiśrāṃ giletprātaḥ gomūtreṇa ca kuṣṭhaṃ nudatyasṛgvātamacireṇa"},{"type":"verse","number":"67","sanskrit":"श्वित्राणि पाण्डुरोगं विषमानुदरप्रमेहगुल्मांश्च नाशयति वलीपलितं योगः स्वायम्भुवो नाम्ना","text":"śvitrāṇi pāṇḍurogaṃ viṣamānudarapramehagulmāṃśca nāśayati valīpalitaṃ yogaḥ svāyambhuvo nāmnā"},{"type":"verse","number":"68","sanskrit":"चित्रकं त्रिफला व्योषमजाजी कारवी वचा सैन्धवातिविषाकुष्ठं चव्यैला च यवासकम्","text":"citrakaṃ triphalā vyoṣamajājī kāravī vacā saindhavātiviṣākuṣṭhaṃ cavyailā ca yavāsakam"},{"type":"verse","number":"69","sanskrit":"विडङ्गान्यजमोदा च मुस्ता चामरदारु च यावन्त्येतानि सर्वाणि तावन्मानन्तु गुग्गुलोः","text":"viḍaṅgānyajamodā ca mustā cāmaradāru ca yāvantyetāni sarvāṇi tāvanmānantu gugguloḥ"},{"type":"verse","number":"70","sanskrit":"सङ्कुट्य सर्पिषा सार्द्धं गुटिकां कारयेद्भिषक् प्रातर्भोजनकाले च खादेदग्निबलं यथा","text":"saṅkuṭya sarpiṣā sārddhaṃ guṭikāṃ kārayedbhiṣak prātarbhojanakāle ca khādedagnibalaṃ yathā"},{"type":"verse","number":"71","sanskrit":"हन्त्यष्टादश कुष्ठानि कृमिदुष्टव्रणानि च ग्रहण्यर्शोविकारांश्च मुखामयगलग्रहान्","text":"hantyaṣṭādaśa kuṣṭhāni kṛmiduṣṭavraṇāni ca grahaṇyarśovikārāṃśca mukhāmayagalagrahān"},{"type":"verse","number":"72","sanskrit":"गृध्रसीमथ भग्नञ्च गुल्मं चापि नियच्छति व्याधीन्कोष्ठगतांश्चापि जयेद्विष्णुरिवासुरान्","text":"gṛdhrasīmatha bhagnañca gulmaṃ cāpi niyacchati vyādhīnkoṣṭhagatāṃścāpi jayedviṣṇurivāsurān"},{"type":"verse","number":"73","sanskrit":"वातरक्ताधिकारोक्तः पुरः कैशोरकाभिधः कुष्ठानां वातरक्तानां नाशनं परमौषधम्","text":"vātaraktādhikāroktaḥ puraḥ kaiśorakābhidhaḥ kuṣṭhānāṃ vātaraktānāṃ nāśanaṃ paramauṣadham"},{"type":"verse","number":"74","sanskrit":"भल्लातकप्रस्थयुगं छित्वा द्रो णजले क्षिपेत् प्रस्थद्वयंगुडूच्याश्च क्षुण्णं तत्राम्भसि क्षिपेत् चतुर्थांशावशेषं तु कषायमवतारयेत् वस्त्रपूते कषाये तु वक्ष्यमाणं विनिक्षिपेत्","text":"bhallātakaprasthayugaṃ chitvā dro ṇajale kṣipet prasthadvayaṃguḍūcyāśca kṣuṇṇaṃ tatrāmbhasi kṣipet caturthāṃśāvaśeṣaṃ tu kaṣāyamavatārayet vastrapūte kaṣāye tu vakṣyamāṇaṃ vinikṣipet"},{"type":"verse","number":"75","sanskrit":"शरावमात्रकंसर्पिर्दुग्धं स्यादाढकं तथा सितां प्रस्थमितां दद्यात्प्रस्थार्द्धं माक्षिकं क्षिपेत्","text":"śarāvamātrakaṃsarpirdugdhaṃ syādāḍhakaṃ tathā sitāṃ prasthamitāṃ dadyātprasthārddhaṃ mākṣikaṃ kṣipet"},{"type":"verse","number":"76","sanskrit":"सर्वाण्येकत्र भाण्डे तु पचेन्मृद्वग्निना शनैः सर्वद्र वे घनीभूते पावकादवतारयेत्","text":"sarvāṇyekatra bhāṇḍe tu pacenmṛdvagninā śanaiḥ sarvadra ve ghanībhūte pāvakādavatārayet"},{"type":"verse","number":"77","sanskrit":"तत्र क्षेप्याणि चूर्णानि ब्रूमो बिल्वविषामृताः वाकुची चाथ दद्र घ्नुः पिचुमर्दो हरीतकी","text":"tatra kṣepyāṇi cūrṇāni brūmo bilvaviṣāmṛtāḥ vākucī cātha dadra ghnuḥ picumardo harītakī"},{"type":"verse","number":"78","sanskrit":"अक्षो धात्री च मञ्जिष्ठा मरिचं नागरं कणा यवानी सैन्धवं मुस्तं त्वगेला नागकेशरम्","text":"akṣo dhātrī ca mañjiṣṭhā maricaṃ nāgaraṃ kaṇā yavānī saindhavaṃ mustaṃ tvagelā nāgakeśaram"},{"type":"verse","number":"79","sanskrit":"पर्पटं पत्रकं बालमुशीरं चन्दनं तथा गोक्षुरस्य च बीजानि कर्चूरो रक्तचन्दनम्","text":"parpaṭaṃ patrakaṃ bālamuśīraṃ candanaṃ tathā gokṣurasya ca bījāni karcūro raktacandanam"},{"type":"verse","number":"80","sanskrit":"पृथक्पलार्द्धमानानां चूर्णमेषामिह क्षिपेत् पलमात्रमितं प्रातः समश्नीयाज्जलेन हि","text":"pṛthakpalārddhamānānāṃ cūrṇameṣāmiha kṣipet palamātramitaṃ prātaḥ samaśnīyājjalena hi"},{"type":"verse","number":"81","sanskrit":"नाशयेदवलेहोऽय पथ्यान्यन्नानि खादतः कुष्ठानि वातरक्तानि सर्वाण्यर्शांसि सेवितः","text":"nāśayedavaleho'ya pathyānyannāni khādataḥ kuṣṭhāni vātaraktāni sarvāṇyarśāṃsi sevitaḥ"},{"type":"verse","number":"82","sanskrit":"व्यायाममातपं वह्निमम्लं मांसं दधि स्त्रियम् तैलाभ्यङ्गं तथाध्वानं नरो भल्लातकी त्यजेत्","text":"vyāyāmamātapaṃ vahnimamlaṃ māṃsaṃ dadhi striyam tailābhyaṅgaṃ tathādhvānaṃ naro bhallātakī tyajet"},{"type":"verse","number":"83","sanskrit":"निम्बगोपारुणाः कट्वी त्रायन्ती त्रिफला घनम् पर्पटावल्गुजानन्तावचाखदिरचन्दनम्","text":"nimbagopāruṇāḥ kaṭvī trāyantī triphalā ghanam parpaṭāvalgujānantāvacākhadiracandanam"},{"type":"verse","number":"84","sanskrit":"पाठाशुण्ठीशटीभार्गीवासाभूनिम्बवत्सकम् श्यामेन्द्र वारुणीमूर्वाविडङ्गेन्द्र यवानलम्","text":"pāṭhāśuṇṭhīśaṭībhārgīvāsābhūnimbavatsakam śyāmendra vāruṇīmūrvāviḍaṅgendra yavānalam"},{"type":"verse","number":"85","sanskrit":"हस्तिकर्णामृताद्रे कापटोलरजनीद्वयम् कणारग्वधसप्ताह्वत्रिवृद्वेत्रोच्चटाफलम्","text":"hastikarṇāmṛtādre kāpaṭolarajanīdvayam kaṇāragvadhasaptāhvatrivṛdvetroccaṭāphalam"},{"type":"verse","number":"86","sanskrit":"मञ्जिष्ठा लाङ्गली रास्ना नक्तमालं पुनर्नवा दन्तीबीजकसारञ्च भृङ्गराजं कुरण्टकम्","text":"mañjiṣṭhā lāṅgalī rāsnā naktamālaṃ punarnavā dantībījakasārañca bhṛṅgarājaṃ kuraṇṭakam"},{"type":"verse","number":"87","sanskrit":"अङ्कोटकञ्च शाखोटं द्विपलांशं पृथक्पृथक् गृह्णीयात्तानि सर्वाणि जलद्रो णे पचेच्छनैः","text":"aṅkoṭakañca śākhoṭaṃ dvipalāṃśaṃ pṛthakpṛthak gṛhṇīyāttāni sarvāṇi jaladro ṇe pacecchanaiḥ"},{"type":"verse","number":"88","sanskrit":"अष्टमांशावशेषन्तु कषायमवतारयेत् विधाय वाससा पूतं स्थापयेद्भाजने दृढे","text":"aṣṭamāṃśāvaśeṣantu kaṣāyamavatārayet vidhāya vāsasā pūtaṃ sthāpayedbhājane dṛḍhe"},{"type":"verse","number":"89","sanskrit":"भल्लातकसहस्राणि च्छित्वा तु त्र्यर्मणाम्भसि पचेदष्टावशेषं तत्कषायमवतारयेत्","text":"bhallātakasahasrāṇi cchitvā tu tryarmaṇāmbhasi pacedaṣṭāvaśeṣaṃ tatkaṣāyamavatārayet"},{"type":"verse","number":"90","sanskrit":"तच्च वस्त्रेण संशोध्य द्वौ कषायौ विमिश्रयेत् गुडं शतपलं दत्वा लेहवत्तत्पचेच्छनैः","text":"tacca vastreṇa saṃśodhya dvau kaṣāyau vimiśrayet guḍaṃ śatapalaṃ datvā lehavattatpacecchanaiḥ"},{"type":"verse","number":"91","sanskrit":"त्रिकटु त्रिफला मुस्तं विडङ्गं चित्रकं तथा सैन्धवं चन्दनं कुष्ठं दीप्यकञ्च पलं पृथक् सौगन्ध्यार्थं क्षिपेत्तत्र चातुर्जातं पलं पलम्","text":"trikaṭu triphalā mustaṃ viḍaṅgaṃ citrakaṃ tathā saindhavaṃ candanaṃ kuṣṭhaṃ dīpyakañca palaṃ pṛthak saugandhyārthaṃ kṣipettatra cāturjātaṃ palaṃ palam"},{"type":"verse","number":"92","sanskrit":"महाभल्लातको ह्येष महादेवेन भाषितः प्राणिनां हितकामेन जयेच्छीघ्रं प्रयोजितः","text":"mahābhallātako hyeṣa mahādevena bhāṣitaḥ prāṇināṃ hitakāmena jayecchīghraṃ prayojitaḥ"},{"type":"verse","number":"93","sanskrit":"श्वित्रमौदुम्बरं दद्रुमृक्षजिह्वन्तु काकणम् पुण्डरीकं सचर्माख्यं विस्फोटं रक्तमण्डलम्","text":"śvitramaudumbaraṃ dadrumṛkṣajihvantu kākaṇam puṇḍarīkaṃ sacarmākhyaṃ visphoṭaṃ raktamaṇḍalam"},{"type":"verse","number":"94","sanskrit":"कण्डूं कपालकं कुष्ठं पामानञ्च विपादिकाम् वातरक्तं षडर्शांसि पाण्डुरोगव्रणान्कृमीन्","text":"kaṇḍūṃ kapālakaṃ kuṣṭhaṃ pāmānañca vipādikām vātaraktaṃ ṣaḍarśāṃsi pāṇḍurogavraṇānkṛmīn"},{"type":"verse","number":"95","sanskrit":"रक्तपित्तमुदावर्त्तं कासं श्वासं भगन्दरम् सदाभ्यासेन पलितमामवातं सुदुस्तरम्","text":"raktapittamudāvarttaṃ kāsaṃ śvāsaṃ bhagandaram sadābhyāsena palitamāmavātaṃ sudustaram"},{"type":"verse","number":"96","sanskrit":"निर्यन्त्रणस्तु कथितो विहाराहारमैथुने कुरुते परमां कान्तिं प्रदीप्तं जठरानलम्","text":"niryantraṇastu kathito vihārāhāramaithune kurute paramāṃ kāntiṃ pradīptaṃ jaṭharānalam"},{"type":"verse","number":"97","sanskrit":"अनुपानं प्रयोक्तव्यं छिन्नातोयं पयोऽथवा भोजने तु सदा त्याज्यमुष्णमम्लं विशेषतः","text":"anupānaṃ prayoktavyaṃ chinnātoyaṃ payo'thavā bhojane tu sadā tyājyamuṣṇamamlaṃ viśeṣataḥ"},{"type":"verse","number":"98","sanskrit":"मञ्जिष्ठा त्रिफला तिक्ता वचादारुनिशाऽमयाः निम्बश्चैषां कृतः क्थाथः सर्वकुष्ठं विनाशयेत्","text":"mañjiṣṭhā triphalā tiktā vacādāruniśā'mayāḥ nimbaścaiṣāṃ kṛtaḥ kthāthaḥ sarvakuṣṭhaṃ vināśayet"},{"type":"verse","number":"99","sanskrit":"वातरक्तं तथा कण्डूं पामां वै रक्तमण्डलम् दद्रूं विसर्पं विस्फोटं पानाभ्यासेन नाशयेत्","text":"vātaraktaṃ tathā kaṇḍūṃ pāmāṃ vai raktamaṇḍalam dadrūṃ visarpaṃ visphoṭaṃ pānābhyāsena nāśayet"},{"type":"verse","number":"100","sanskrit":"मञ्जिष्ठा वाकुची चक्रमर्दश्च पिचुमर्दकः हरीतकी हरिद्रा च धात्री वासा शतावरी","text":"mañjiṣṭhā vākucī cakramardaśca picumardakaḥ harītakī haridrā ca dhātrī vāsā śatāvarī"},{"type":"verse","number":"101","sanskrit":"बला नागबला यष्टीमधुकं क्षुरकोपि च पटोलस्य लतोशीरं गुडूची रक्तचन्दनम्","text":"balā nāgabalā yaṣṭīmadhukaṃ kṣurakopi ca paṭolasya latośīraṃ guḍūcī raktacandanam"},{"type":"verse","number":"102","sanskrit":"मञ्जिष्ठादिरयं क्वाथः कुष्ठानां नाशनः परः वातरक्तस्य संहर्त्ता कण्डूमण्डलनाशनः","text":"mañjiṣṭhādirayaṃ kvāthaḥ kuṣṭhānāṃ nāśanaḥ paraḥ vātaraktasya saṃharttā kaṇḍūmaṇḍalanāśanaḥ"},{"type":"verse","number":"103","sanskrit":"मञ्जिष्ठाकुटजामृताघन वचामुण्डीहरिद्रा द्वयं क्षुद्रा रिष्टपटोलतिक्तकटु काभार्गीविडङ्गाग्निकम् मूर्वादारुकलिङ्गभृङ्गम गधात्रायान्तपाठावरी गायत्री त्रिफलाकिरातकमहानिम्बासनारग्वधाः","text":"mañjiṣṭhākuṭajāmṛtāghana vacāmuṇḍīharidrā dvayaṃ kṣudrā riṣṭapaṭolatiktakaṭu kābhārgīviḍaṅgāgnikam mūrvādārukaliṅgabhṛṅgama gadhātrāyāntapāṭhāvarī gāyatrī triphalākirātakamahānimbāsanāragvadhāḥ"},{"type":"verse","number":"104","sanskrit":"श्यामावल्गुजचन्दनं वरुणकं दन्तीकशाखोटकं वासासर्पटसारिवा प्रतिविषानन्ताविशालाजलम् मञ्जिष्ठाप्रथमं कषायमिति यः संसेवते तस्य तु त्वग्दोषाः सुचिरेण यान्ति विलयं कुष्ठानि चाष्टादश","text":"śyāmāvalgujacandanaṃ varuṇakaṃ dantīkaśākhoṭakaṃ vāsāsarpaṭasārivā prativiṣānantāviśālājalam mañjiṣṭhāprathamaṃ kaṣāyamiti yaḥ saṃsevate tasya tu tvagdoṣāḥ sucireṇa yānti vilayaṃ kuṣṭhāni cāṣṭādaśa"},{"type":"verse","number":"105","sanskrit":"नाशं गच्छति वातरक्तमखिला नश्यन्ति रक्तामयाः वीसर्पस्त्वचि शून्यता नयनजा रोगाः प्रशाम्यन्ति च","text":"nāśaṃ gacchati vātaraktamakhilā naśyanti raktāmayāḥ vīsarpastvaci śūnyatā nayanajā rogāḥ praśāmyanti ca"},{"type":"verse","number":"106","sanskrit":"मरिचं त्रिवृता मुस्तं हरितालं मनः शिला देवदारु हरिद्रे द्वे मांसी कुष्ठं सचन्दनम्","text":"maricaṃ trivṛtā mustaṃ haritālaṃ manaḥ śilā devadāru haridre dve māṃsī kuṣṭhaṃ sacandanam"},{"type":"verse","number":"107","sanskrit":"विशाला करवीरञ्च क्षीरमर्कसमुद्भवम् गोमयस्य रसं कुर्यात्प्रत्येकं कर्षसम्मितम्","text":"viśālā karavīrañca kṣīramarkasamudbhavam gomayasya rasaṃ kuryātpratyekaṃ karṣasammitam"},{"type":"verse","number":"108","sanskrit":"विषस्यार्द्धपलं देयं तैलं प्रस्थमितं कटु पचेच्चतुर्गुणे नीरे गोमूत्रे द्विगुणे तथा","text":"viṣasyārddhapalaṃ deyaṃ tailaṃ prasthamitaṃ kaṭu paceccaturguṇe nīre gomūtre dviguṇe tathā"},{"type":"verse","number":"109","sanskrit":"मरिचाद्यमिदं तैलमभ्यङ्गात्कुष्ठनाशनम् एतस्याभ्यङ्गतः श्वित्रं विवर्णं तत्क्षणाद्भवेत्","text":"maricādyamidaṃ tailamabhyaṅgātkuṣṭhanāśanam etasyābhyaṅgataḥ śvitraṃ vivarṇaṃ tatkṣaṇādbhavet"},{"type":"verse","number":"110","sanskrit":"तैलमेतज्जयेत्कण्डूं पामां सिध्मविचर्चिकाम् पुण्डरीकं तथा दद्रुं शून्यतां नित्यसेविनाम्","text":"tailametajjayetkaṇḍūṃ pāmāṃ sidhmavicarcikām puṇḍarīkaṃ tathā dadruṃ śūnyatāṃ nityasevinām"},{"type":"verse","number":"111","sanskrit":"मरिचं त्रिवृता दन्ती क्षीरमार्कं शकृद्र सः देवदारु हरिद्रे द्वे मांसी कुष्ठं सचन्दनम्","text":"maricaṃ trivṛtā dantī kṣīramārkaṃ śakṛdra saḥ devadāru haridre dve māṃsī kuṣṭhaṃ sacandanam"},{"type":"verse","number":"112","sanskrit":"विशाला करवीरञ्च हरितालं मनःशिला चित्रकं लाङ्गली मुस्तं विडङ्गं चक्रमर्दकः","text":"viśālā karavīrañca haritālaṃ manaḥśilā citrakaṃ lāṅgalī mustaṃ viḍaṅgaṃ cakramardakaḥ"},{"type":"verse","number":"113","sanskrit":"शिरीषःकुटजो निम्बः सप्तपर्णोऽमृता स्नुही श्यामाको नक्तमालश्च खदिरो वाकुची वचा","text":"śirīṣaḥkuṭajo nimbaḥ saptaparṇo'mṛtā snuhī śyāmāko naktamālaśca khadiro vākucī vacā"},{"type":"verse","number":"114","sanskrit":"ज्योतिष्मती च पलिका विषं द्विपलिकं भवेत् आढकं कटुतैलस्य गोमूत्रञ्च चतुर्गुणम्","text":"jyotiṣmatī ca palikā viṣaṃ dvipalikaṃ bhavet āḍhakaṃ kaṭutailasya gomūtrañca caturguṇam"},{"type":"verse","number":"115","sanskrit":"मृत्पात्रे लोहपात्रे च शनैर्मृद्वग्निना पचेत् मरिचाद्यमिदं तैलं महन्मुनिभिरीरितम्","text":"mṛtpātre lohapātre ca śanairmṛdvagninā pacet maricādyamidaṃ tailaṃ mahanmunibhirīritam"},{"type":"verse","number":"116","sanskrit":"भिषगेतेन तैलेन म्रक्षयेत्कौष्ठिकान्व्रणान् पामाविचर्चिकादद्रू कण्डूविस्फोटकानि च","text":"bhiṣagetena tailena mrakṣayetkauṣṭhikānvraṇān pāmāvicarcikādadrū kaṇḍūvisphoṭakāni ca"},{"type":"verse","number":"117","sanskrit":"वलयः पलितं छाया नीलं व्यङ्गं तथैव च अभ्यङ्गेन प्रणश्यन्ति सौकुमार्यञ्च जायते","text":"valayaḥ palitaṃ chāyā nīlaṃ vyaṅgaṃ tathaiva ca abhyaṅgena praṇaśyanti saukumāryañca jāyate"},{"type":"verse","number":"118","sanskrit":"प्रथमे वयसि स्त्रीणां यासां नस्यं प्रदीयते तासामपि जरां प्राप्य न स्यातां स्खलितौ स्तनौ","text":"prathame vayasi strīṇāṃ yāsāṃ nasyaṃ pradīyate tāsāmapi jarāṃ prāpya na syātāṃ skhalitau stanau"},{"type":"verse","number":"119","sanskrit":"बलीवर्दस्तुरङ्गो वा गजो वा वायुपीडितः त्रिभिरभ्यञ्जनैरस्य भवेन्मारुतविक्रमः","text":"balīvardasturaṅgo vā gajo vā vāyupīḍitaḥ tribhirabhyañjanairasya bhavenmārutavikramaḥ"},{"type":"verse","number":"120","sanskrit":"तालताप्यशिलासूतटङ्कणाः सिन्धुसंयुताः गन्धको द्विगुणः सूताच्छङ्खचूर्णञ्च तत्समम्","text":"tālatāpyaśilāsūtaṭaṅkaṇāḥ sindhusaṃyutāḥ gandhako dviguṇaḥ sūtācchaṅkhacūrṇañca tatsamam"},{"type":"verse","number":"121","sanskrit":"जम्बीराद्भिर्दिनं घृष्ट्वा त्रिंशदंशं विषं क्षिपेत् अस्य माषद्वयं खादेन्महिषीघृतसंयुतम्","text":"jambīrādbhirdinaṃ ghṛṣṭvā triṃśadaṃśaṃ viṣaṃ kṣipet asya māṣadvayaṃ khādenmahiṣīghṛtasaṃyutam"},{"type":"verse","number":"122","sanskrit":"मध्वाज्यैर्वाकुचीबीजकर्षं लिह्यात्ततः परम् तालकेश्वरनामाऽय सर्वकुष्ठहरो रसः","text":"madhvājyairvākucībījakarṣaṃ lihyāttataḥ param tālakeśvaranāmā'ya sarvakuṣṭhaharo rasaḥ"},{"type":"verse","number":"123","sanskrit":"रसो वलिस्ताम्रमयः पुरोग्निः शिलाजतु स्याद्विषतिन्दुकश्च वरा च तुल्यं गगनञ्च सर्वैः करञ्जबीजं सचतुष्टयञ्च","text":"raso valistāmramayaḥ purogniḥ śilājatu syādviṣatindukaśca varā ca tulyaṃ gaganañca sarvaiḥ karañjabījaṃ sacatuṣṭayañca"},{"type":"verse","number":"124","sanskrit":"सम्मर्द्य सर्वं मधुना घृतेन घृतस्य पात्रे निहितं प्रयत्नात् कर्षं भजेत्प्रत्यहमस्य पथ्यं शाल्योदनं दुग्धमधुत्रयञ्च","text":"sammardya sarvaṃ madhunā ghṛtena ghṛtasya pātre nihitaṃ prayatnāt karṣaṃ bhajetpratyahamasya pathyaṃ śālyodanaṃ dugdhamadhutrayañca"},{"type":"verse","number":"125","sanskrit":"विशीर्णकर्णाङ्गुलिनासिकोऽपि भवेदनेन स्मरतुल्यमूर्त्तिः दारापरित्याग इह प्रदिष्टो जलौदनं तत्र निबद्धमूले","text":"viśīrṇakarṇāṅgulināsiko'pi bhavedanena smaratulyamūrttiḥ dārāparityāga iha pradiṣṭo jalaudanaṃ tatra nibaddhamūle"},{"type":"verse","number":"126","sanskrit":"कुष्ठं मूलकबीजं प्रियङ्गवः सर्षपास्तथा रजनी एतत्केशरषष्ठं निहन्ति चिरकालजं सिध्मम्","text":"kuṣṭhaṃ mūlakabījaṃ priyaṅgavaḥ sarṣapāstathā rajanī etatkeśaraṣaṣṭhaṃ nihanti cirakālajaṃ sidhmam"},{"type":"verse","number":"127","sanskrit":"शिखरीरसेन पिष्टं मूलकबीजं प्रलेपतः सिध्मम् क्षारेण वा कदल्या रजनीमिश्रेण नाशयति","text":"śikharīrasena piṣṭaṃ mūlakabījaṃ pralepataḥ sidhmam kṣāreṇa vā kadalyā rajanīmiśreṇa nāśayati"},{"type":"verse","number":"128","sanskrit":"दार्वीमूलकबीजानि तालकं सुरदारु च ताम्बूलपत्रं सर्वाणि कार्षिकाणि पृथक्पृथक्","text":"dārvīmūlakabījāni tālakaṃ suradāru ca tāmbūlapatraṃ sarvāṇi kārṣikāṇi pṛthakpṛthak"},{"type":"verse","number":"129","sanskrit":"शङ्खचूर्णन्तु शाणं स्यात्सर्वाण्येकत्र वारिणा प्रलेपयेत्प्रलेपोऽय सिध्मनाशन उत्तमः","text":"śaṅkhacūrṇantu śāṇaṃ syātsarvāṇyekatra vāriṇā pralepayetpralepo'ya sidhmanāśana uttamaḥ"},{"type":"verse","number":"130","sanskrit":"सलिले चाम्रपेशी तु किञ्चित्सैन्धवसंयुता ताम्रपात्रे विनिर्घृष्टा लेपाच्चर्मदलापहा","text":"salile cāmrapeśī tu kiñcitsaindhavasaṃyutā tāmrapātre vinirghṛṣṭā lepāccarmadalāpahā"},{"type":"verse","number":"131","sanskrit":"सलिलेन तु शुष्काणि घृष्ट्वा धात्रीफलानि च कराभ्यां सुखमाप्नोति नरश्चर्मदलान्वितः","text":"salilena tu śuṣkāṇi ghṛṣṭvā dhātrīphalāni ca karābhyāṃ sukhamāpnoti naraścarmadalānvitaḥ"},{"type":"verse","number":"132","sanskrit":"जीरकस्य पलं पिष्टं सिन्दूरार्द्धपलं तथा कटुतैलं पचेदाभ्यां सर्वपामाहरं परम्","text":"jīrakasya palaṃ piṣṭaṃ sindūrārddhapalaṃ tathā kaṭutailaṃ pacedābhyāṃ sarvapāmāharaṃ param"},{"type":"verse","number":"133","sanskrit":"मञ्जिष्ठात्रिफलालाक्षालाङ्गली रात्रिगन्धकैः चूर्णितैस्तैलमादित्यपाकं पामाहरं परम्","text":"mañjiṣṭhātriphalālākṣālāṅgalī rātrigandhakaiḥ cūrṇitaistailamādityapākaṃ pāmāharaṃ param"},{"type":"verse","number":"134","sanskrit":"सैन्धवं चक्रमर्दश्च सर्षपाः पिप्पली तथा आरनालेन संपिष्टाः पामाकण्डूहराः पराः","text":"saindhavaṃ cakramardaśca sarṣapāḥ pippalī tathā āranālena saṃpiṣṭāḥ pāmākaṇḍūharāḥ parāḥ"},{"type":"verse","number":"135","sanskrit":"अर्कपत्ररसे पक्वं हरिद्रा कल्कसंयुतम् नाशयेत्सार्षपं तैलं पामाकच्छूविचर्चिकाः","text":"arkapatrarase pakvaṃ haridrā kalkasaṃyutam nāśayetsārṣapaṃ tailaṃ pāmākacchūvicarcikāḥ"},{"type":"verse","number":"136","sanskrit":"मनः शिलाऽल कासीसं गन्धाश्म सिन्धुजन्म च स्वर्णक्षीरी शिलाभेदी शुण्ठी कुष्ठञ्च मागधी","text":"manaḥ śilā'la kāsīsaṃ gandhāśma sindhujanma ca svarṇakṣīrī śilābhedī śuṇṭhī kuṣṭhañca māgadhī"},{"type":"verse","number":"137","sanskrit":"लाङ्गली करवीरञ्च दद्रुघ्नः कृमिहाऽनलः दन्ती निम्बदलं चैभिः पृथक्कर्षमितैर्भिषक्","text":"lāṅgalī karavīrañca dadrughnaḥ kṛmihā'nalaḥ dantī nimbadalaṃ caibhiḥ pṛthakkarṣamitairbhiṣak"},{"type":"verse","number":"138","sanskrit":"कल्लीकृत्य पचेत्तैलं कटु प्रस्थद्वयोन्मितम् अर्कसेहुण्डदुग्धेन पृथक्पलमितेन च","text":"kallīkṛtya pacettailaṃ kaṭu prasthadvayonmitam arkasehuṇḍadugdhena pṛthakpalamitena ca"},{"type":"verse","number":"139","sanskrit":"गोमूत्रस्याढकेनापि शनैर्मृद्वग्निना पचेत् अभ्यङ्गेन हरेदेतत्कच्छू दुःसाध्यतामपि","text":"gomūtrasyāḍhakenāpi śanairmṛdvagninā pacet abhyaṅgena haredetatkacchū duḥsādhyatāmapi"},{"type":"verse","number":"140","sanskrit":"पामानञ्च तथा कण्डूं त्वग्व्याधिरुधिरामयान् कण्डूराक्षसनामेदं तैलं हारीतभाषितम्","text":"pāmānañca tathā kaṇḍūṃ tvagvyādhirudhirāmayān kaṇḍūrākṣasanāmedaṃ tailaṃ hārītabhāṣitam"},{"type":"verse","number":"141","sanskrit":"कृतमालस्य पत्राणि नक्तमालदलानि च द्रो णपुष्पीपलाशानि सर्षपा राजिका निशा","text":"kṛtamālasya patrāṇi naktamāladalāni ca dro ṇapuṣpīpalāśāni sarṣapā rājikā niśā"},{"type":"verse","number":"142","sanskrit":"कुटजो मधुकं मुस्तं नागरं रक्तचन्दनम् धांत्री यवानिका दारु कल्क एष प्रकल्पितः","text":"kuṭajo madhukaṃ mustaṃ nāgaraṃ raktacandanam dhāṃtrī yavānikā dāru kalka eṣa prakalpitaḥ"},{"type":"verse","number":"143","sanskrit":"उद्वर्त्तनादयं कल्कः कटुतैलसमन्वितः कच्छूं पामां हरत्येव शीतपित्तादिकान्गदान्","text":"udvarttanādayaṃ kalkaḥ kaṭutailasamanvitaḥ kacchūṃ pāmāṃ haratyeva śītapittādikāngadān"},{"type":"verse","number":"144","sanskrit":"कुष्ठं कृमिघ्नो दद्रुघ्नो निशासैन्धवसर्षपाः अम्लपिष्टः प्रलेपोऽय दद्रुकुष्ठनिषूदनः","text":"kuṣṭhaṃ kṛmighno dadrughno niśāsaindhavasarṣapāḥ amlapiṣṭaḥ pralepo'ya dadrukuṣṭhaniṣūdanaḥ"},{"type":"verse","number":"145","sanskrit":"दूर्वाभयासैन्धवचक्रमर्दकुठेरकाः काञ्जिकतक्रपिष्टाः त्रिभिः प्रलेपैरपि बद्धमूलां दद्रू ञ्च कुष्ठञ्च विनाशयन्ति","text":"dūrvābhayāsaindhavacakramardakuṭherakāḥ kāñjikatakrapiṣṭāḥ tribhiḥ pralepairapi baddhamūlāṃ dadrū ñca kuṣṭhañca vināśayanti"},{"type":"verse","number":"146","sanskrit":"गण्डलिकाख्यं तृणमपि सिद्धार्थकश्च स्नुहीपत्रम् त्रयमपि समभागं स्यादेषां द्विगुणस्तु दद्र्रुघ्नः","text":"gaṇḍalikākhyaṃ tṛṇamapi siddhārthakaśca snuhīpatram trayamapi samabhāgaṃ syādeṣāṃ dviguṇastu dadrrughnaḥ"},{"type":"verse","number":"147","sanskrit":"अष्टगुणे गोतक्रे तानि प्रकृतानि सन्दध्यात् दिवसत्रितयादूर्ध्वं सम्यङ्निष्पेषयेत्तानि","text":"aṣṭaguṇe gotakre tāni prakṛtāni sandadhyāt divasatritayādūrdhvaṃ samyaṅniṣpeṣayettāni"},{"type":"verse","number":"148","sanskrit":"वन्योपलेन घृष्ट्वा च दद्रुमालेपयेत्तेन सप्ताहाल्लेपोऽय दद्र्रूमचिराद्विनाशयति","text":"vanyopalena ghṛṣṭvā ca dadrumālepayettena saptāhāllepo'ya dadrrūmacirādvināśayati"},{"type":"verse","number":"149","sanskrit":"बिभीतकत्वङ्मलयूजटानां क्वाथेन पीतं गुडसंयुतेन आवल्गुजं बीजमपाकरोति श्वित्राणि कृच्छ्राण्यपि पुण्डरीकम्","text":"bibhītakatvaṅmalayūjaṭānāṃ kvāthena pītaṃ guḍasaṃyutena āvalgujaṃ bījamapākaroti śvitrāṇi kṛcchrāṇyapi puṇḍarīkam"},{"type":"verse","number":"150","sanskrit":"कुडवमवल्गुणबीजं हरितालचतुर्थभागसम्मिश्रम्","text":"kuḍavamavalguṇabījaṃ haritālacaturthabhāgasammiśram"},{"type":"verse","number":"151","sanskrit":"मनः शिलां तोलकार्द्धं गुञ्जाफलमग्निमूलञ्च मूत्रेण गवां पिष्टं सवर्णताकारकं श्वित्रे","text":"manaḥ śilāṃ tolakārddhaṃ guñjāphalamagnimūlañca mūtreṇa gavāṃ piṣṭaṃ savarṇatākārakaṃ śvitre"},{"type":"verse","number":"152","sanskrit":"श्वेतं कुष्ठं व्रजत्यस्तं पक्षार्द्धेनाधिकेन वा गिरिकर्ण्यास्तु कृष्णाया मूलेन परिलेपितम्","text":"śvetaṃ kuṣṭhaṃ vrajatyastaṃ pakṣārddhenādhikena vā girikarṇyāstu kṛṣṇāyā mūlena parilepitam"},{"type":"verse","number":"153","sanskrit":"क्वाथः सवाकुचीचूर्णो धात्रीखदिरसारयोः शङ्खेन्दुकुन्दधवलं श्वित्रं संसेवितो हरेत्","text":"kvāthaḥ savākucīcūrṇo dhātrīkhadirasārayoḥ śaṅkhendukundadhavalaṃ śvitraṃ saṃsevito haret"},{"type":"verse","number":"154","sanskrit":"मथितेन पिबेच्चूर्णं काकोदुम्बर्यवल्गुजम् तैलाक्तो घर्मसेवी स्यात्तक्राशी श्वित्रहृद्भवेत्","text":"mathitena pibeccūrṇaṃ kākodumbaryavalgujam tailākto gharmasevī syāttakrāśī śvitrahṛdbhavet"},{"type":"verse","number":"155","sanskrit":"चतुष्पलं सोमराज्याः खदिरस्य पलं तथा पटोलमूलं त्रिफला त्रायमाणा दुरालभा","text":"catuṣpalaṃ somarājyāḥ khadirasya palaṃ tathā paṭolamūlaṃ triphalā trāyamāṇā durālabhā"},{"type":"verse","number":"156","sanskrit":"कल्कार्थं कटुकं चापि कार्षिकान्सूक्ष्मपेषितान् पलद्वयं कौशिकस्य शुद्धस्यात्र प्रदापयेत्","text":"kalkārthaṃ kaṭukaṃ cāpi kārṣikānsūkṣmapeṣitān paladvayaṃ kauśikasya śuddhasyātra pradāpayet"},{"type":"verse","number":"157","sanskrit":"सिद्धं सर्पिरिदं श्वित्रं हन्यादम्भ इवानलम् अष्टादशानां कुष्ठानां परमं चैतदौषधम्","text":"siddhaṃ sarpiridaṃ śvitraṃ hanyādambha ivānalam aṣṭādaśānāṃ kuṣṭhānāṃ paramaṃ caitadauṣadham"},{"type":"verse","number":"158","sanskrit":"सोमराजीघृतं नाम निर्मितं ब्रह्मणा पुरा लोकानामुपकाराय श्वित्रकुष्ठादिरोगिणाम्","text":"somarājīghṛtaṃ nāma nirmitaṃ brahmaṇā purā lokānāmupakārāya śvitrakuṣṭhādirogiṇām"},{"type":"verse","number":"159","sanskrit":"इति चतुष्पञ्चाशत्तमः कुष्ठाधिकारः समाप्तः ५४","text":"iti catuṣpañcāśattamaḥ kuṣṭhādhikāraḥ samāptaḥ 54"}]},{"sthana":"Уттаракханда","number":55,"lang":"sa","content":[{"type":"heading","heading":"Шитапитта — крапивница"},{"type":"verse","number":"1","sanskrit":"शीतमारुतसम्पर्कात्प्रवृद्धौ कफमारुतौ पित्तेन सह सम्भूय बहिरन्तर्विसर्पतः","text":"śītamārutasamparkātpravṛddhau kaphamārutau pittena saha sambhūya bahirantarvisarpataḥ"},{"type":"verse","number":"2","sanskrit":"पिपासाऽरुचिहृल्लास देहसादाङ्गगौरवम् रक्तलोचनता तेषां पूर्वरूपस्य लक्षणम्","text":"pipāsā'rucihṛllāsa dehasādāṅgagauravam raktalocanatā teṣāṃ pūrvarūpasya lakṣaṇam"},{"type":"verse","number":"3","sanskrit":"वरटीदष्टसंस्थानः शोथः सञ्जायते बहिः सकण्डूतोदबहुलश्छर्दि ज्वरविदाहवान् वाताधिकतमं विद्याच्छीतपित्तमिमं भिषक्","text":"varaṭīdaṣṭasaṃsthānaḥ śothaḥ sañjāyate bahiḥ sakaṇḍūtodabahulaśchardi jvaravidāhavān vātādhikatamaṃ vidyācchītapittamimaṃ bhiṣak"},{"type":"verse","number":"4","sanskrit":"सोत्सङ्गैश्च सरागैश्च कण्डूमद्भिश्च मण्डलैः शैशिरः श्लेष्मबहुल उदर्दइति कीर्त्तितः","text":"sotsaṅgaiśca sarāgaiśca kaṇḍūmadbhiśca maṇḍalaiḥ śaiśiraḥ śleṣmabahula udardaiti kīrttitaḥ"},{"type":"verse","number":"5","sanskrit":"असम्यग्वमनोदीर्णपित्तश्लेष्मान्ननिग्रहैः","text":"asamyagvamanodīrṇapittaśleṣmānnanigrahaiḥ"},{"type":"verse","number":"6","sanskrit":"मण्डलानि सकण्डूनि रागवन्ति बहूनि च सानुबन्धस्तु स प्राज्ञैरुत्कोठ इति कथ्यते","text":"maṇḍalāni sakaṇḍūni rāgavanti bahūni ca sānubandhastu sa prājñairutkoṭha iti kathyate"},{"type":"verse","number":"7","sanskrit":"शीतपित्ते तु वमनं पटोलारिष्टवासकैः त्रिफलापुरकोष्णाभिर्विरेकश्च प्रशस्यते","text":"śītapitte tu vamanaṃ paṭolāriṣṭavāsakaiḥ triphalāpurakoṣṇābhirvirekaśca praśasyate"},{"type":"verse","number":"8","sanskrit":"अभ्यङ्गः कटुतैलेन सेकश्चोष्णेन वारिणा त्रिफलां क्षौद्र्रसंयुक्तां खादेच्च नवकार्षिकम्","text":"abhyaṅgaḥ kaṭutailena sekaścoṣṇena vāriṇā triphalāṃ kṣaudrrasaṃyuktāṃ khādecca navakārṣikam"},{"type":"verse","number":"9","sanskrit":"त्रिफलापुरकृष्णानां त्रिपञ्चैकांशयोजिता गुटिका शीतपित्तार्शोभगन्दरवतां हिता","text":"triphalāpurakṛṣṇānāṃ tripañcaikāṃśayojitā guṭikā śītapittārśobhagandaravatāṃ hitā"},{"type":"verse","number":"10","sanskrit":"इति नव कार्षिकः सितां त्रिकटुसंयुक्तां गुडमामलकैः सह यवानीं खादयेच्चापि सव्योषक्षारसंयुताम्","text":"iti nava kārṣikaḥ sitāṃ trikaṭusaṃyuktāṃ guḍamāmalakaiḥ saha yavānīṃ khādayeccāpi savyoṣakṣārasaṃyutām"},{"type":"verse","number":"11","sanskrit":"आर्द्र्रकस्य रसःपेयः पुराणगुडसंयुतः शीतपित्तापहः श्रेष्ठो वह्निमान्द्यविनाशनः","text":"ārdrrakasya rasaḥpeyaḥ purāṇaguḍasaṃyutaḥ śītapittāpahaḥ śreṣṭho vahnimāndyavināśanaḥ"},{"type":"verse","number":"12","sanskrit":"सिद्धार्थरजनीकल्कैः प्रपुन्नाटतिलैः सह कटुतैलेन सम्मिश्रमेतदुद्वर्त्तनं हितम्","text":"siddhārtharajanīkalkaiḥ prapunnāṭatilaiḥ saha kaṭutailena sammiśrametadudvarttanaṃ hitam"},{"type":"verse","number":"13","sanskrit":"सुगुडं दीप्यकं यस्तु खादेत्पथ्यान्नभुङ्नरः तस्य नश्यति सप्ताहादुदर्दःसर्वदेहजः","text":"suguḍaṃ dīpyakaṃ yastu khādetpathyānnabhuṅnaraḥ tasya naśyati saptāhādudardaḥsarvadehajaḥ"},{"type":"verse","number":"14","sanskrit":"घृतं पीत्वा महातिक्तं शोणितं मोक्षयेत्तथा स्निग्धस्विन्नस्य संशुद्धिमादौ कोठे समाचरेत् उत्कोठे शुद्धदेहस्य कुष्ठघ्नीं कारयेत्क्रियाम्","text":"ghṛtaṃ pītvā mahātiktaṃ śoṇitaṃ mokṣayettathā snigdhasvinnasya saṃśuddhimādau koṭhe samācaret utkoṭhe śuddhadehasya kuṣṭhaghnīṃ kārayetkriyām"},{"type":"verse","number":"15","sanskrit":"निम्बस्य पत्राणि सदा घृतेन धात्रीविमिश्राणि नरः प्रयुञ्ज्यात् विस्फोटकण्डूकृमिशीतपित्तमुदर्दकोठौ च कफञ्च हन्यात्","text":"nimbasya patrāṇi sadā ghṛtena dhātrīvimiśrāṇi naraḥ prayuñjyāt visphoṭakaṇḍūkṛmiśītapittamudardakoṭhau ca kaphañca hanyāt"},{"type":"verse","number":"16","sanskrit":"आर्द्र कं प्रस्थमेकं स्याद् गोघृतं कुडवद्वयम् गोदुग्धं प्रस्थयुगलं तदर्द्धं शर्करा मता","text":"ārdra kaṃ prasthamekaṃ syād goghṛtaṃ kuḍavadvayam godugdhaṃ prasthayugalaṃ tadarddhaṃ śarkarā matā"},{"type":"verse","number":"17","sanskrit":"पिप्पली पिप्पलीमूलं मरिचं विश्वभेषजम् चित्रकञ्च विडङ्गञ्च मुस्तकं नागकेशरम्","text":"pippalī pippalīmūlaṃ maricaṃ viśvabheṣajam citrakañca viḍaṅgañca mustakaṃ nāgakeśaram"},{"type":"verse","number":"18","sanskrit":"त्वगेलापत्रकर्चूरं प्रत्येकं पलमात्रकम् विधाय पाकं विधिवत्खादेत्तत्पलसम्मितम्","text":"tvagelāpatrakarcūraṃ pratyekaṃ palamātrakam vidhāya pākaṃ vidhivatkhādettatpalasammitam"},{"type":"verse","number":"19","sanskrit":"इदमार्द्र कखण्डं हि प्रातर्भुक्तं व्यपोहति शीतपित्तमुदर्दञ्च कोठमुत्कोठमेव च यक्ष्माणं रक्तपित्तञ्च कासं श्वासमरोचकम् वातगुल्ममुदावर्तं शोथं कण्डूं कृमीनपि","text":"idamārdra kakhaṇḍaṃ hi prātarbhuktaṃ vyapohati śītapittamudardañca koṭhamutkoṭhameva ca yakṣmāṇaṃ raktapittañca kāsaṃ śvāsamarocakam vātagulmamudāvartaṃ śothaṃ kaṇḍūṃ kṛmīnapi"},{"type":"verse","number":"20","sanskrit":"दीपयेदुदरे वह्निं बलं वीर्यञ्च वर्द्धयेत् वपुः पुष्टं प्रकुरुते तस्मात्सेव्यमिदं सदा","text":"dīpayedudare vahniṃ balaṃ vīryañca varddhayet vapuḥ puṣṭaṃ prakurute tasmātsevyamidaṃ sadā"},{"type":"verse","number":"21","sanskrit":"इति पञ्चपञ्चाशत्तमः शीतपित्तोदर्दकोठोत्कोठाधिकारः समाप्तः ५५","text":"iti pañcapañcāśattamaḥ śītapittodardakoṭhotkoṭhādhikāraḥ samāptaḥ 55"}]},{"sthana":"Уттаракханда","number":56,"lang":"sa","content":[{"type":"heading","heading":"Висарпа — рожа"},{"type":"verse","number":"1","sanskrit":"लवणाम्ल कटूष्णादिसेवनाद्दोषकोपतः विसर्पः सप्तधा ज्ञेयः सर्वतः परिसर्पणात्","text":"lavaṇāmla kaṭūṣṇādisevanāddoṣakopataḥ visarpaḥ saptadhā jñeyaḥ sarvataḥ parisarpaṇāt"},{"type":"verse","number":"2","sanskrit":"विसर्पस्य सप्तधात्वं विवृणोति वातिकः पैत्तिकश्चैव कफजः सान्निपातिकः चत्वार एते वीसर्पा वक्ष्यन्ते द्वन्द्वजास्त्रयः","text":"visarpasya saptadhātvaṃ vivṛṇoti vātikaḥ paittikaścaiva kaphajaḥ sānnipātikaḥ catvāra ete vīsarpā vakṣyante dvandvajāstrayaḥ"},{"type":"verse","number":"3","sanskrit":"आग्नेयो वातपित्ताभ्यां ग्रन्थ्याख्यः कफवातजः यस्तु कर्दमको घोरः स पित्तकफसम्भवः","text":"āgneyo vātapittābhyāṃ granthyākhyaḥ kaphavātajaḥ yastu kardamako ghoraḥ sa pittakaphasambhavaḥ"},{"type":"verse","number":"4","sanskrit":"रक्तं लसीका त्वङ्मांसं दूष्यं दोषास्त्रयो मलाः विसर्पाणां समुत्पत्तौ हेतवः सप्त धातवः","text":"raktaṃ lasīkā tvaṅmāṃsaṃ dūṣyaṃ doṣāstrayo malāḥ visarpāṇāṃ samutpattau hetavaḥ sapta dhātavaḥ"},{"type":"verse","number":"5","sanskrit":"तत्र वातात्परीसर्पो वातज्वरसमव्यथः शोफस्फुरणनिस्तोदभेदायामार्त्तिहर्षवान्","text":"tatra vātātparīsarpo vātajvarasamavyathaḥ śophasphuraṇanistodabhedāyāmārttiharṣavān"},{"type":"verse","number":"6","sanskrit":"पित्ताद् द्रुतगतिः पित्तज्वरलिङ्गोऽतिलोहितः","text":"pittād drutagatiḥ pittajvaraliṅgo'tilohitaḥ"},{"type":"verse","number":"7","sanskrit":"कफात्कण्डूयुतः स्निग्धः कफज्वरसमानरुक्","text":"kaphātkaṇḍūyutaḥ snigdhaḥ kaphajvarasamānaruk"},{"type":"verse","number":"8","sanskrit":"सन्निपातसमुत्थश्च सर्वरूपसमन्वितः","text":"sannipātasamutthaśca sarvarūpasamanvitaḥ"},{"type":"verse","number":"9","sanskrit":"वातपित्ताज्ज्वरच्छर्दिमूर्च्छाऽतीसारतृड्भ्रमैः अस्थिभेदाग्निसदनतमकारोचकैर्युतः करोति सर्वमङ्गञ्च दीप्ताङ्गारावकीर्णवत् यं यं देशं विसर्पश्च विसर्पति भवेत्स सः","text":"vātapittājjvaracchardimūrcchā'tīsāratṛḍbhramaiḥ asthibhedāgnisadanatamakārocakairyutaḥ karoti sarvamaṅgañca dīptāṅgārāvakīrṇavat yaṃ yaṃ deśaṃ visarpaśca visarpati bhavetsa saḥ"},{"type":"verse","number":"10","sanskrit":"शीताङ्गारासितो नीलो रक्तो वाऽशूपचीयते अग्निदग्ध इव स्फोटः शीघ्रगत्वाद् द्रुतञ्च सः","text":"śītāṅgārāsito nīlo rakto vā'śūpacīyate agnidagdha iva sphoṭaḥ śīghragatvād drutañca saḥ"},{"type":"verse","number":"11","sanskrit":"मर्मानुसारी वीसर्पःस्याद्वातोऽतिबलस्ततः व्यथेताङ्गं हरेत्संज्ञां निद्रा ञ्च श्वासमीरयेत्","text":"marmānusārī vīsarpaḥsyādvāto'tibalastataḥ vyathetāṅgaṃ haretsaṃjñāṃ nidrā ñca śvāsamīrayet"},{"type":"verse","number":"12","sanskrit":"हिध्माञ्च स गतोऽवस्थामीदृशीं लभते न ना क्वचिच्छर्मारतिग्रस्तो भूमिशय्याऽसनादिषु","text":"hidhmāñca sa gato'vasthāmīdṛśīṃ labhate na nā kvaciccharmāratigrasto bhūmiśayyā'sanādiṣu"},{"type":"verse","number":"13","sanskrit":"चेष्टमानस्ततः क्लिष्टो मनोदेहसमुद्भवाम् दुष्प्रबोधोऽश्नुते निद्रां सोऽग्निवीसर्प उच्यते","text":"ceṣṭamānastataḥ kliṣṭo manodehasamudbhavām duṣprabodho'śnute nidrāṃ so'gnivīsarpa ucyate"},{"type":"verse","number":"14","sanskrit":"कफेन रुद्धः पवनो भित्वा तं बहुधा कफम् रक्तं वा वृद्धरक्तस्य त्वक्शिरास्नायुमांसगम्","text":"kaphena ruddhaḥ pavano bhitvā taṃ bahudhā kapham raktaṃ vā vṛddharaktasya tvakśirāsnāyumāṃsagam"},{"type":"verse","number":"15","sanskrit":"दूषयित्वा तु दीर्घाणां वृत्तस्थूलखरात्मनाम् ग्रन्थीनां कुरुते मालां रक्तानां तीव्ररुग्ज्वराम्","text":"dūṣayitvā tu dīrghāṇāṃ vṛttasthūlakharātmanām granthīnāṃ kurute mālāṃ raktānāṃ tīvrarugjvarām"},{"type":"verse","number":"16","sanskrit":"श्वासकासातिसारास्य शोषहिक्कावमिभ्रमैः मोहवैवर्ण्यमूर्च्छाऽङ्ग भङ्गाग्निसदनैर्युतः इत्ययं ग्रन्थिवीसर्पो वातश्लेष्मप्रकोपजः","text":"śvāsakāsātisārāsya śoṣahikkāvamibhramaiḥ mohavaivarṇyamūrcchā'ṅga bhaṅgāgnisadanairyutaḥ ityayaṃ granthivīsarpo vātaśleṣmaprakopajaḥ"},{"type":"verse","number":"17","sanskrit":"कफपित्ताज्ज्वरस्तम्भनिद्रा तन्द्रा शिरोरुजाः अङ्गावसादविक्षेपप्रलेपारोचकभ्रमाः","text":"kaphapittājjvarastambhanidrā tandrā śirorujāḥ aṅgāvasādavikṣepapralepārocakabhramāḥ"},{"type":"verse","number":"18","sanskrit":"मूर्च्छाऽग्निहानिर्भेदोऽस्थ्ना पिपासेन्द्रि यगौरवम् सामोपवेसनं लेपः स्रोतसां स च सर्पति","text":"mūrcchā'gnihānirbhedo'sthnā pipāsendri yagauravam sāmopavesanaṃ lepaḥ srotasāṃ sa ca sarpati"},{"type":"verse","number":"19","sanskrit":"प्रायेणामाशयं गृह्णन्नेकदेशं न चातिरुक् पिडकैरवकीर्णोऽतिपीतलोहितपाण्डुरः","text":"prāyeṇāmāśayaṃ gṛhṇannekadeśaṃ na cātiruk piḍakairavakīrṇo'tipītalohitapāṇḍuraḥ"},{"type":"verse","number":"20","sanskrit":"स्निग्धोऽसितो मेचकाभो मलिनः शोफवान्गुरुः गम्भीरपाकः प्राज्योष्मा स्पृष्टः क्लिन्नोऽवदीर्यते","text":"snigdho'sito mecakābho malinaḥ śophavānguruḥ gambhīrapākaḥ prājyoṣmā spṛṣṭaḥ klinno'vadīryate"},{"type":"verse","number":"21","sanskrit":"पङ्कत्वक्शीर्णमांसश्च स्पष्टस्नायुशिरागणः शवगन्धी च वीसर्पः कर्दमाख्यमुशन्ति तम्","text":"paṅkatvakśīrṇamāṃsaśca spaṣṭasnāyuśirāgaṇaḥ śavagandhī ca vīsarpaḥ kardamākhyamuśanti tam"},{"type":"verse","number":"22","sanskrit":"सन्निपातसमुत्थस्तु सर्वरूपसमन्वितः","text":"sannipātasamutthastu sarvarūpasamanvitaḥ"},{"type":"verse","number":"23","sanskrit":"बाह्यहेतोः क्षतात्क्रुद्धः सरक्तं पित्तमीरयन् विसर्पं मारुतः कुर्यात्कुलत्थसदृशैश्चितम् स्फोटः शोथज्वररुजादाहाढ्यं श्यावशोणितम्","text":"bāhyahetoḥ kṣatātkruddhaḥ saraktaṃ pittamīrayan visarpaṃ mārutaḥ kuryātkulatthasadṛśaiścitam sphoṭaḥ śothajvararujādāhāḍhyaṃ śyāvaśoṇitam"},{"type":"verse","number":"24","sanskrit":"ज्वरातिसारौ वमथुस्त्वङ्मांसदरणक्लमाः अरोचकाविपाकौ च विसर्पाणामुपद्र वाः","text":"jvarātisārau vamathustvaṅmāṃsadaraṇaklamāḥ arocakāvipākau ca visarpāṇāmupadra vāḥ"},{"type":"verse","number":"25","sanskrit":"सिद्ध्य्न्ति वातकफपित्तकृता विसर्पाः सर्वात्मकः क्षतकृतश्च न सिद्धिमेति पित्तात्मकोऽञ्जनवपुश्च भवेदसाध्यः कृच्छ्राश्च मर्मसु भवन्ति हि सर्व एव","text":"siddhynti vātakaphapittakṛtā visarpāḥ sarvātmakaḥ kṣatakṛtaśca na siddhimeti pittātmako'ñjanavapuśca bhavedasādhyaḥ kṛcchrāśca marmasu bhavanti hi sarva eva"},{"type":"verse","number":"26","sanskrit":"विरेकवमनालेप सेचनास्रविमोक्षणैः उपाचरेद्यथादोषं विसर्पानविदाहिभिः","text":"virekavamanālepa secanāsravimokṣaṇaiḥ upācaredyathādoṣaṃ visarpānavidāhibhiḥ"},{"type":"verse","number":"27","sanskrit":"रास्ना नीलोत्पलं दारु चन्दनं मधुकं बला घृतक्षीरयुतो लेपो वातवीसर्पनाशनः","text":"rāsnā nīlotpalaṃ dāru candanaṃ madhukaṃ balā ghṛtakṣīrayuto lepo vātavīsarpanāśanaḥ"},{"type":"verse","number":"28","sanskrit":"कशेरुशृङ्गाटकपद्मगुन्द्रः सशैवलैः सोत्पलकर्दमैश्च वस्त्रान्तरैः पित्तकृते विसर्पे लेपो विधेयः सघृतः सुशीतः","text":"kaśeruśṛṅgāṭakapadmagundraḥ saśaivalaiḥ sotpalakardamaiśca vastrāntaraiḥ pittakṛte visarpe lepo vidheyaḥ saghṛtaḥ suśītaḥ"},{"type":"verse","number":"29","sanskrit":"त्रिफलापद्मकोशीर समङ्गाकरवीरकम् नलमूलमनन्ता च लेपः श्लेष्मविसर्पके","text":"triphalāpadmakośīra samaṅgākaravīrakam nalamūlamanantā ca lepaḥ śleṣmavisarpake"},{"type":"verse","number":"30","sanskrit":"वातपित्तप्रशमनमग्निवीसर्पणे हितम् वातश्लेष्महरं कर्म ग्रन्थिविसर्पणे हितम्","text":"vātapittapraśamanamagnivīsarpaṇe hitam vātaśleṣmaharaṃ karma granthivisarpaṇe hitam"},{"type":"verse","number":"31","sanskrit":"पित्तश्लेष्मप्रशमनं हितं कर्दमसंज्ञके त्रिदोषजे क्रियां कुर्याद्विसर्पे त्रितयापहाम्","text":"pittaśleṣmapraśamanaṃ hitaṃ kardamasaṃjñake tridoṣaje kriyāṃ kuryādvisarpe tritayāpahām"},{"type":"verse","number":"32","sanskrit":"शिरीषयष्टीनतचन्दनैलामांसीहरिद्रा द्वयकुष्ठबालैः लेपो दशाङ्गः सघृतः प्रयोज्यो विसर्पकुष्ठज्वरशोथहारी","text":"śirīṣayaṣṭīnatacandanailāmāṃsīharidrā dvayakuṣṭhabālaiḥ lepo daśāṅgaḥ saghṛtaḥ prayojyo visarpakuṣṭhajvaraśothahārī"},{"type":"verse","number":"33","sanskrit":"परिषेकाः प्रलेपाश्च शस्यन्ते पञ्चवल्कलैः पद्मकोशीरमधुकैश्चन्दनैर्वा विसर्पणे","text":"pariṣekāḥ pralepāśca śasyante pañcavalkalaiḥ padmakośīramadhukaiścandanairvā visarpaṇe"},{"type":"verse","number":"34","sanskrit":"भूनिम्बवासाकटुकापटोलीफलत्रयीचन्दननिम्बसिद्धः विसर्पदाहज्वरशोथकण्डूविस्फोटतृष्णावमिहृत्कषायः","text":"bhūnimbavāsākaṭukāpaṭolīphalatrayīcandananimbasiddhaḥ visarpadāhajvaraśothakaṇḍūvisphoṭatṛṣṇāvamihṛtkaṣāyaḥ"},{"type":"verse","number":"35","sanskrit":"कुष्ठेषु यानि सर्पींषि व्रणेषु विविधेषु च विसर्पे तानि योज्यानि सेकालेपनभोजनैः","text":"kuṣṭheṣu yāni sarpīṃṣi vraṇeṣu vividheṣu ca visarpe tāni yojyāni sekālepanabhojanaiḥ"},{"type":"verse","number":"36","sanskrit":"करञ्जसप्तच्छदलाङ्गली कस्नुह्यर्कदुग्धानलभृङ्गराजैः तैलं निशामूत्रविषैर्विपक्वं विसर्पविस्फोटविचर्चिकाघ्नम्","text":"karañjasaptacchadalāṅgalī kasnuhyarkadugdhānalabhṛṅgarājaiḥ tailaṃ niśāmūtraviṣairvipakvaṃ visarpavisphoṭavicarcikāghnam"},{"type":"verse","number":"37","sanskrit":"कुष्ठामयस्फोटमसूरिकोक्तचिकित्सयाऽप्याशु हरेद्विसर्पान् सर्वान्विपक्वान्परिशोध्य धीमान्व्रणक्रमेणोपचरेद्यथोक्तम्","text":"kuṣṭhāmayasphoṭamasūrikoktacikitsayā'pyāśu haredvisarpān sarvānvipakvānpariśodhya dhīmānvraṇakrameṇopacaredyathoktam"},{"type":"verse","number":"38","sanskrit":"इति षट्पञ्चाशत्तमो विसर्पाधिकारः समाप्तः ५६","text":"iti ṣaṭpañcāśattamo visarpādhikāraḥ samāptaḥ 56"}]},{"sthana":"Уттаракханда","number":57,"lang":"sa","content":[{"type":"heading","heading":"Виспхотака — пузырчатка"},{"type":"verse","number":"1","sanskrit":"कट्वम्लतीक्ष्णोष्णविदाहिरुक्षक्षारैरजीर्णाध्यशनातपैश्च तथर्त्तुदोषेण विपर्ययेण कुप्यन्ति दोषाः पवनादयस्तु","text":"kaṭvamlatīkṣṇoṣṇavidāhirukṣakṣārairajīrṇādhyaśanātapaiśca tatharttudoṣeṇa viparyayeṇa kupyanti doṣāḥ pavanādayastu"},{"type":"verse","number":"2","sanskrit":"त्वचमाश्रित्य ते रक्तं मांसास्थीनि प्रदूष्य च घोरान्कुर्वन्ति विस्फोटान्सर्वाञ्ज्वरपुरःसरान्","text":"tvacamāśritya te raktaṃ māṃsāsthīni pradūṣya ca ghorānkurvanti visphoṭānsarvāñjvarapuraḥsarān"},{"type":"verse","number":"3","sanskrit":"अग्निदग्धा इव स्फोटाः सज्वरा रक्तपित्तजाः क्वचित्सर्वत्र वा देहे विफोटा इति ते स्मृताः","text":"agnidagdhā iva sphoṭāḥ sajvarā raktapittajāḥ kvacitsarvatra vā dehe viphoṭā iti te smṛtāḥ"},{"type":"verse","number":"4","sanskrit":"शिरोरुक् शूलभूयिष्ठं ज्वरतृट्पर्वभेदनम् सकृष्णवर्णता चेति वातविस्फोटलक्षणम्","text":"śiroruk śūlabhūyiṣṭhaṃ jvaratṛṭparvabhedanam sakṛṣṇavarṇatā ceti vātavisphoṭalakṣaṇam"},{"type":"verse","number":"5","sanskrit":"ज्वरदाहरुजापाकस्रावतृष्णासमन्वितम् पीतलोहितवर्णञ्च पित्तविस्फोटलक्षणम्","text":"jvaradāharujāpākasrāvatṛṣṇāsamanvitam pītalohitavarṇañca pittavisphoṭalakṣaṇam"},{"type":"verse","number":"6","sanskrit":"छर्द्यरोचकजाड्यानिकण्डू काठिन्यपाण्डुताः यस्मिन्न रुक् चिरात्पाकः स विस्फोटः कफात्मकः","text":"chardyarocakajāḍyānikaṇḍū kāṭhinyapāṇḍutāḥ yasminna ruk cirātpākaḥ sa visphoṭaḥ kaphātmakaḥ"},{"type":"verse","number":"7","sanskrit":"कण्डूर्दाहो ज्वरश्छर्दिरेतैश्च कफपैत्तिकः","text":"kaṇḍūrdāho jvaraśchardiretaiśca kaphapaittikaḥ"},{"type":"verse","number":"8","sanskrit":"वातपित्तकृतो यस्तु तत्र स्यात्तीव्रवेदना","text":"vātapittakṛto yastu tatra syāttīvravedanā"},{"type":"verse","number":"9","sanskrit":"कण्डूस्तैमित्यगुरुभिर्जानीयात्कफवातिकम्","text":"kaṇḍūstaimityagurubhirjānīyātkaphavātikam"},{"type":"verse","number":"10","sanskrit":"मध्यनिम्नोन्नतान्तश्च कठिनः स्वल्पपाकवान् दाहरागतृषामोहच्छर्दिमूर्च्छारुजाज्वराः प्रलापो वेपथुस्तन्द्रा सोऽसाध्यश्च त्रिदोषजः","text":"madhyanimnonnatāntaśca kaṭhinaḥ svalpapākavān dāharāgatṛṣāmohacchardimūrcchārujājvarāḥ pralāpo vepathustandrā so'sādhyaśca tridoṣajaḥ"},{"type":"verse","number":"11","sanskrit":"वेदितव्याश्च रक्तेन पैत्तिकेन च हेतुना गुञ्जाफलसमा रक्ता रक्तस्रावा विदाहिनः न ते सिद्धिं समायान्ति सिद्धैर्योगशतैरपि","text":"veditavyāśca raktena paittikena ca hetunā guñjāphalasamā raktā raktasrāvā vidāhinaḥ na te siddhiṃ samāyānti siddhairyogaśatairapi"},{"type":"verse","number":"12","sanskrit":"एते चाष्टविधा बाह्या आन्तरोऽपि भवेदयम् तस्मिन्नन्तर्व्यथातीव्रा ज्वरयुक्ताऽभिजायते","text":"ete cāṣṭavidhā bāhyā āntaro'pi bhavedayam tasminnantarvyathātīvrā jvarayuktā'bhijāyate"},{"type":"verse","number":"13","sanskrit":"यस्मिन्बहिर्गते स्वास्थ्यं न वा तस्य बहिर्गतिः तत्र वातिकविस्फोटक्रिया कार्या विजानता","text":"yasminbahirgate svāsthyaṃ na vā tasya bahirgatiḥ tatra vātikavisphoṭakriyā kāryā vijānatā"},{"type":"verse","number":"14","sanskrit":"तृट्श्वासमांससङ्कोथदाह हिक्कामदज्वराः विसर्पमर्मसंरोधास्तेषामुक्ता उपद्र वाः","text":"tṛṭśvāsamāṃsasaṅkothadāha hikkāmadajvarāḥ visarpamarmasaṃrodhāsteṣāmuktā upadra vāḥ"},{"type":"verse","number":"15","sanskrit":"हिक्का श्वासोऽरुचिस्तृष्णा साङ्गमर्दा हृदि व्यथा विसर्पज्वरहृल्लासा विस्फोटानामुपद्र वाः","text":"hikkā śvāso'rucistṛṣṇā sāṅgamardā hṛdi vyathā visarpajvarahṛllāsā visphoṭānāmupadra vāḥ"},{"type":"verse","number":"16","sanskrit":"एकदोषो स्थितः साध्यः कृच्छ्रसाध्यो द्विदोषजः सर्वरूपान्वितो घोरो ह्यसाध्यो भूर्युपद्र वः","text":"ekadoṣo sthitaḥ sādhyaḥ kṛcchrasādhyo dvidoṣajaḥ sarvarūpānvito ghoro hyasādhyo bhūryupadra vaḥ"},{"type":"verse","number":"17","sanskrit":"विस्फोटे लङ्घनं कार्यं वमनं पथ्यभोजनम् यथादोषबलं वीक्ष्य युक्तमुक्तं विरेचनम्","text":"visphoṭe laṅghanaṃ kāryaṃ vamanaṃ pathyabhojanam yathādoṣabalaṃ vīkṣya yuktamuktaṃ virecanam"},{"type":"verse","number":"18","sanskrit":"जीर्णशालियवा मुद्गा मसूराश्चाढकी तथा एतान्यन्नानि विस्फोटे हितानि मुनयोऽब्रुवन्","text":"jīrṇaśāliyavā mudgā masūrāścāḍhakī tathā etānyannāni visphoṭe hitāni munayo'bruvan"},{"type":"verse","number":"19","sanskrit":"द्वे पञ्चमूल्यौ रास्ना च दार्व्युशीरं दुरालभा गुडूची धान्यकं मुस्तमेषां क्वाथं पिबेन्नरः विस्फोटान्नाशयन्त्याशु समीरणनिमित्तकान्","text":"dve pañcamūlyau rāsnā ca dārvyuśīraṃ durālabhā guḍūcī dhānyakaṃ mustameṣāṃ kvāthaṃ pibennaraḥ visphoṭānnāśayantyāśu samīraṇanimittakān"},{"type":"verse","number":"20","sanskrit":"द्रा क्षाकाश्मर्य खर्जूरपटोलारिष्टवासकैः कटुकालाजदुःस्पर्शैः सितायुक्तं तु पैत्तिके","text":"drā kṣākāśmarya kharjūrapaṭolāriṣṭavāsakaiḥ kaṭukālājaduḥsparśaiḥ sitāyuktaṃ tu paittike"},{"type":"verse","number":"21","sanskrit":"भूनिम्बसवचावासा त्रिफलेन्द्र जवत्सकैः पिचुमर्दपटोलाभ्यां कफजे मधुयुक्शृतम्","text":"bhūnimbasavacāvāsā triphalendra javatsakaiḥ picumardapaṭolābhyāṃ kaphaje madhuyukśṛtam"},{"type":"verse","number":"22","sanskrit":"किराततिक्तकारिष्टयष्ट्या ह्वाम्बुदवासकैः पटोलपर्पटोशीरत्रि फलाकौटजान्वितैः क्वथितैर्द्वादशाङ्गन्तु सर्वविस्फोटनाशनम्","text":"kirātatiktakāriṣṭayaṣṭyā hvāmbudavāsakaiḥ paṭolaparpaṭośīratri phalākauṭajānvitaiḥ kvathitairdvādaśāṅgantu sarvavisphoṭanāśanam"},{"type":"verse","number":"23","sanskrit":"विस्फोटव्याधिनाशाय तण्डुलाम्बुप्रपेषितैः बीजैः कुटजवृक्षस्य लेपः कार्यो विजानता","text":"visphoṭavyādhināśāya taṇḍulāmbuprapeṣitaiḥ bījaiḥ kuṭajavṛkṣasya lepaḥ kāryo vijānatā"},{"type":"verse","number":"24","sanskrit":"छिन्नापटोलभूनिम्ब वासकारिष्टपर्पटैः खदिराब्दयुतैः क्वाथो हन्ति विस्फोटकज्वरम्","text":"chinnāpaṭolabhūnimba vāsakāriṣṭaparpaṭaiḥ khadirābdayutaiḥ kvātho hanti visphoṭakajvaram"},{"type":"verse","number":"25","sanskrit":"चन्दनं नागपुष्पञ्च सारिवा तण्डुलीयकम् शिरीषवल्कलं जातीलेपः स्याद्दाहनाशनः","text":"candanaṃ nāgapuṣpañca sārivā taṇḍulīyakam śirīṣavalkalaṃ jātīlepaḥ syāddāhanāśanaḥ"},{"type":"verse","number":"26","sanskrit":"उत्पलं चन्दनं लोध्रमुशीरंसारिवाद्वयम् जलपिष्टेन लेपेन स्फोटदाहार्त्तिनाशनम्","text":"utpalaṃ candanaṃ lodhramuśīraṃsārivādvayam jalapiṣṭena lepena sphoṭadāhārttināśanam"},{"type":"verse","number":"27","sanskrit":"पुत्रजीवस्य मज्जानं जले पिष्ट्वा प्रलेपयेत् कालस्फोटं च विस्फोटं सद्यो हन्ति सवेदनम्","text":"putrajīvasya majjānaṃ jale piṣṭvā pralepayet kālasphoṭaṃ ca visphoṭaṃ sadyo hanti savedanam"},{"type":"verse","number":"28","sanskrit":"कक्षग्रन्थिं गलग्रन्थिं कर्णग्रन्थिञ्च नाशयेत् हन्याच्च स्फोटकं ताम्रं पुत्रजीवो विनाशयेत्","text":"kakṣagranthiṃ galagranthiṃ karṇagranthiñca nāśayet hanyācca sphoṭakaṃ tāmraṃ putrajīvo vināśayet"},{"type":"verse","number":"29","sanskrit":"इत्यष्टपञ्चाशत्तमोविस्फोटकाधिकारः समाप्तः ५८","text":"ityaṣṭapañcāśattamovisphoṭakādhikāraḥ samāptaḥ 58"}]},{"sthana":"Уттаракханда","number":58,"lang":"sa","content":[{"type":"heading","heading":"Фиранга — сифилис"},{"type":"verse","number":"1","sanskrit":"फिरङ्गसंज्ञके देशे बाहुल्येनैव यद्भवेत् तस्मात्फिरङ्ग इत्युक्तो व्याधिर्व्याधिविशारदैः","text":"phiraṅgasaṃjñake deśe bāhulyenaiva yadbhavet tasmātphiraṅga ityukto vyādhirvyādhiviśāradaiḥ"},{"type":"verse","number":"2","sanskrit":"गन्धरोगः फिरङ्गोऽय जायते देहिनां ध्रुवम् फिरङ्गिणोऽङ्गसंसर्गात्फिरङ्गिण्याः प्रसङ्गतः","text":"gandharogaḥ phiraṅgo'ya jāyate dehināṃ dhruvam phiraṅgiṇo'ṅgasaṃsargātphiraṅgiṇyāḥ prasaṅgataḥ"},{"type":"verse","number":"3","sanskrit":"व्याधिरागन्तुजो ह्येष दोषाणामत्र सङ्क्रमः भवेत्तं लक्षयेत्तेषां लक्षणैर्भिषजां वरः","text":"vyādhirāgantujo hyeṣa doṣāṇāmatra saṅkramaḥ bhavettaṃ lakṣayetteṣāṃ lakṣaṇairbhiṣajāṃ varaḥ"},{"type":"verse","number":"4","sanskrit":"फिरङ्गस्त्रिविधो ज्ञेयो बाह्य आभ्यन्तरस्तथा बहिरन्तर्भवश्चापि तेषां लिङ्गानि च ब्रुवे","text":"phiraṅgastrividho jñeyo bāhya ābhyantarastathā bahirantarbhavaścāpi teṣāṃ liṅgāni ca bruve"},{"type":"verse","number":"5","sanskrit":"तत्र बाह्यः फिरङ्गः स्याद्विस्फोटसदृशोऽल्परुक् स्फुटितोव्रणवद्वेद्यः सुखसाध्योऽपि स स्मृतः","text":"tatra bāhyaḥ phiraṅgaḥ syādvisphoṭasadṛśo'lparuk sphuṭitovraṇavadvedyaḥ sukhasādhyo'pi sa smṛtaḥ"},{"type":"verse","number":"6","sanskrit":"सन्धिष्वाभ्यन्तरः स स्यादामवात इव व्यथाम् शोथञ्च जनयेदेष कष्टसाध्यो बुधैः स्मृतः","text":"sandhiṣvābhyantaraḥ sa syādāmavāta iva vyathām śothañca janayedeṣa kaṣṭasādhyo budhaiḥ smṛtaḥ"},{"type":"verse","number":"7","sanskrit":"कार्श्यं बलक्षयो नासाभङ्गो बह्नेश्च मन्दता अस्थिशोषोऽस्थिवक्रत्वं फिरङ्गोपद्र वा अमी","text":"kārśyaṃ balakṣayo nāsābhaṅgo bahneśca mandatā asthiśoṣo'sthivakratvaṃ phiraṅgopadra vā amī"},{"type":"verse","number":"8","sanskrit":"बहिर्भवो भवेत्साध्यो नवीनो निरुपद्र वः आभ्यन्तरस्तु कष्टेन साध्यः स्यादयमामयः बहिरन्तर्भवो जीर्णः क्षीणस्योपद्र वैर्युतः व्याप्तो व्याधिरसाध्योऽयमित्याहुर्मुनयः पुरा","text":"bahirbhavo bhavetsādhyo navīno nirupadra vaḥ ābhyantarastu kaṣṭena sādhyaḥ syādayamāmayaḥ bahirantarbhavo jīrṇaḥ kṣīṇasyopadra vairyutaḥ vyāpto vyādhirasādhyo'yamityāhurmunayaḥ purā"},{"type":"verse","number":"9","sanskrit":"अथ फिरङ्गरोगस्य चिकित्सा फिरङ्गसंज्ञकं रोगं रसः कर्पूरसंज्ञकः अवश्यं नाशयेदेतदूचुः पूर्वाश्चिकित्सकाः","text":"atha phiraṅgarogasya cikitsā phiraṅgasaṃjñakaṃ rogaṃ rasaḥ karpūrasaṃjñakaḥ avaśyaṃ nāśayedetadūcuḥ pūrvāścikitsakāḥ"},{"type":"verse","number":"10","sanskrit":"लिख्यते रसकर्पूरप्राशने विधिरुत्तमः अनेन विधिना खादेन्मुखे शोथं न विन्दति","text":"likhyate rasakarpūraprāśane vidhiruttamaḥ anena vidhinā khādenmukhe śothaṃ na vindati"},{"type":"verse","number":"11","sanskrit":"गोधूमचूर्णं सन्नीय विदध्यात्सूक्ष्मकूपिकाम् तन्मध्ये निक्षिपेत्सूतं चतुर्गुञ्जामितं भिषक्","text":"godhūmacūrṇaṃ sannīya vidadhyātsūkṣmakūpikām tanmadhye nikṣipetsūtaṃ caturguñjāmitaṃ bhiṣak"},{"type":"verse","number":"12","sanskrit":"ततस्तु गुटिकां कुर्याद्यथा न दृश्यते बहिः सूक्ष्मचूर्णे लवङ्गस्य तां वटीमवधूलयेत्","text":"tatastu guṭikāṃ kuryādyathā na dṛśyate bahiḥ sūkṣmacūrṇe lavaṅgasya tāṃ vaṭīmavadhūlayet"},{"type":"verse","number":"13","sanskrit":"दन्तस्पर्शो यथा न स्यात्तथा तामम्भसा गिलेत् ताम्बूलं भक्षयेत्पश्चाच्छाकाम्ललवणांस्त्यजेत् श्रममातपमध्वानं विशेषात्स्त्रीनिषेवणम्","text":"dantasparśo yathā na syāttathā tāmambhasā gilet tāmbūlaṃ bhakṣayetpaścācchākāmlalavaṇāṃstyajet śramamātapamadhvānaṃ viśeṣātstrīniṣevaṇam"},{"type":"verse","number":"14","sanskrit":"पारदष्टङ्कमानः स्यात्खदिरष्टङ्कसंमितः आकारकरभश्चापि ग्राह्यष्टङ्कद्वयोन्मितः","text":"pāradaṣṭaṅkamānaḥ syātkhadiraṣṭaṅkasaṃmitaḥ ākārakarabhaścāpi grāhyaṣṭaṅkadvayonmitaḥ"},{"type":"verse","number":"15","sanskrit":"टङ्कत्रयोन्मितं क्षौद्रं खल्वे सर्वं विनिक्षिपेत् संमर्द्य तस्य सर्वस्य कुर्यात्सप्तवटीर्भिषक्","text":"ṭaṅkatrayonmitaṃ kṣaudraṃ khalve sarvaṃ vinikṣipet saṃmardya tasya sarvasya kuryātsaptavaṭīrbhiṣak"},{"type":"verse","number":"16","sanskrit":"स रोगी भक्षयेत्प्रातरेकैकामम्बुना वटीम् वर्जयेदम्ललवणं फिरङ्गस्तस्य नश्यति","text":"sa rogī bhakṣayetprātarekaikāmambunā vaṭīm varjayedamlalavaṇaṃ phiraṅgastasya naśyati"},{"type":"verse","number":"17","sanskrit":"पारदः कर्षमात्रः स्यात्तावानेव हि गन्धकः तण्डुलाश्चाक्षमात्राः स्युरेषां कुर्वीत कज्जलीम्","text":"pāradaḥ karṣamātraḥ syāttāvāneva hi gandhakaḥ taṇḍulāścākṣamātrāḥ syureṣāṃ kurvīta kajjalīm"},{"type":"verse","number":"18","sanskrit":"तस्याःसप्त वटीः कुर्यात्ताभिर्धूमं प्रयोजयेत् दिनानि सप्त तेन स्यात्फिरङ्गान्तो न संशयः","text":"tasyāḥsapta vaṭīḥ kuryāttābhirdhūmaṃ prayojayet dināni sapta tena syātphiraṅgānto na saṃśayaḥ"},{"type":"verse","number":"19","sanskrit":"पीतपुष्पबलापत्ररसैष्टङ्कमितं रसम् हस्ताभ्यां मर्दयेत्तावद्यावत्सूतो न दृश्यते","text":"pītapuṣpabalāpatrarasaiṣṭaṅkamitaṃ rasam hastābhyāṃ mardayettāvadyāvatsūto na dṛśyate"},{"type":"verse","number":"20","sanskrit":"ततः संस्वेदयेद्धस्तावेवं वासरसप्तकम् त्यजेल्लवणमम्लञ्च फिरङ्गस्तस्य नश्यति","text":"tataḥ saṃsvedayeddhastāvevaṃ vāsarasaptakam tyajellavaṇamamlañca phiraṅgastasya naśyati"},{"type":"verse","number":"21","sanskrit":"चूर्णयेन्निम्बपत्राणि पथ्या निम्बाष्टमांशिका धात्री च तावती रात्रिर्निम्बषोडशभागिका","text":"cūrṇayennimbapatrāṇi pathyā nimbāṣṭamāṃśikā dhātrī ca tāvatī rātrirnimbaṣoḍaśabhāgikā"},{"type":"verse","number":"22","sanskrit":"शाणमानमिदं चूर्णमश्नीयादम्भसा सह फिरङ्गं नाशयत्येव बाह्यमाभ्यन्तरं तथा","text":"śāṇamānamidaṃ cūrṇamaśnīyādambhasā saha phiraṅgaṃ nāśayatyeva bāhyamābhyantaraṃ tathā"},{"type":"verse","number":"23","sanskrit":"चोपचीनीभवं चूर्णं शाणमानं समाक्षिकम् फिरङ्गव्याधिनाशाय भक्षयेल्लंवणं त्यजेत्","text":"copacīnībhavaṃ cūrṇaṃ śāṇamānaṃ samākṣikam phiraṅgavyādhināśāya bhakṣayellaṃvaṇaṃ tyajet"},{"type":"verse","number":"24","sanskrit":"लवणं यदि वा त्यक्तुं न शक्नोति यदा जनः सैन्धवं स हि भुञ्जीत मधुरं परमं हितम्","text":"lavaṇaṃ yadi vā tyaktuṃ na śaknoti yadā janaḥ saindhavaṃ sa hi bhuñjīta madhuraṃ paramaṃ hitam"},{"type":"verse","number":"25","sanskrit":"पारदः कर्षमात्रः स्यात्तावन्मात्रं तु गन्धकम् तावन्मात्रस्तु खदिरस्तेषां कुर्यात्तु कज्जलीम्","text":"pāradaḥ karṣamātraḥ syāttāvanmātraṃ tu gandhakam tāvanmātrastu khadirasteṣāṃ kuryāttu kajjalīm"},{"type":"verse","number":"26","sanskrit":"रजनी केशरं त्रुट्यौ जीरयुग्मं यवानिका चन्दनद्वितयं कृष्णा वांशी मांसी च पत्रकम्","text":"rajanī keśaraṃ truṭyau jīrayugmaṃ yavānikā candanadvitayaṃ kṛṣṇā vāṃśī māṃsī ca patrakam"},{"type":"verse","number":"27","sanskrit":"अर्द्धकर्षमितं सर्वं चूर्णयित्वा च निक्षिपेत् तत्सर्वं मधुसर्पिर्भ्यां द्विपलाभ्यां पृथक्पृथक्","text":"arddhakarṣamitaṃ sarvaṃ cūrṇayitvā ca nikṣipet tatsarvaṃ madhusarpirbhyāṃ dvipalābhyāṃ pṛthakpṛthak"},{"type":"verse","number":"28","sanskrit":"मर्दयेदथ तत्खादेदर्द्धकर्षमितं नरः व्रणः फिरङ्गरोगोत्थस्तस्यावश्यं विनश्यति","text":"mardayedatha tatkhādedarddhakarṣamitaṃ naraḥ vraṇaḥ phiraṅgarogotthastasyāvaśyaṃ vinaśyati"},{"type":"verse","number":"29","sanskrit":"अन्योऽपि चिरजातोऽपि प्रशाम्यति महाव्रणः एतद्भक्षयतः शोथो मुखस्यान्तर्न जायते","text":"anyo'pi cirajāto'pi praśāmyati mahāvraṇaḥ etadbhakṣayataḥ śotho mukhasyāntarna jāyate"},{"type":"verse","number":"30","sanskrit":"वर्जयेदत्र लवणमेकविंशतिवासरान्","text":"varjayedatra lavaṇamekaviṃśativāsarān"},{"type":"verse","number":"31","sanskrit":"इत्येकोनषष्टितमः फिरङ्गरोगाधिकारः समाप्तः ५९","text":"ityekonaṣaṣṭitamaḥ phiraṅgarogādhikāraḥ samāptaḥ 59"}]},{"sthana":"Уттаракханда","number":59,"lang":"sa","content":[{"type":"heading","heading":"Масурика — оспа"},{"type":"verse","number":"1","sanskrit":"कट्वम्ललवणक्षार विरुद्धाध्यशनाशनैः दुष्टनिष्पावशाकाद्यैः प्रदुष्टपवनोदकैः","text":"kaṭvamlalavaṇakṣāra viruddhādhyaśanāśanaiḥ duṣṭaniṣpāvaśākādyaiḥ praduṣṭapavanodakaiḥ"},{"type":"verse","number":"2","sanskrit":"क्रूरग्रहेक्षणाच्चापि देशे दोषाः समुद्धताः जनयन्ति शरीरेऽस्मिन्दुष्टरक्तेन सङ्गताः मसूराकृतिसंस्थानाः पिडकास्ता मसूरिकाः","text":"krūragrahekṣaṇāccāpi deśe doṣāḥ samuddhatāḥ janayanti śarīre'sminduṣṭaraktena saṅgatāḥ masūrākṛtisaṃsthānāḥ piḍakāstā masūrikāḥ"},{"type":"verse","number":"3","sanskrit":"तासां पूर्वं ज्वरः कण्डूर्गात्रभङ्गोऽरतिर्भ्रमः त्वचि शोथः सवैवर्ण्यो नेत्ररागस्तथैव च","text":"tāsāṃ pūrvaṃ jvaraḥ kaṇḍūrgātrabhaṅgo'ratirbhramaḥ tvaci śothaḥ savaivarṇyo netrarāgastathaiva ca"},{"type":"verse","number":"4","sanskrit":"स्फोटाः कृष्णारुणा रुक्षास्तीव्रवेदनयान्विताः कठिनाश्चिरपाकाश्च भवन्त्यनिलसम्भवाः","text":"sphoṭāḥ kṛṣṇāruṇā rukṣāstīvravedanayānvitāḥ kaṭhināścirapākāśca bhavantyanilasambhavāḥ"},{"type":"verse","number":"5","sanskrit":"सन्ध्यस्थिपर्वणां भेदः कासः कम्पोऽरतिर्भ्रमः शोषस्ताल्वोष्ठजिह्वानां तृष्णा चारुचिसंयुता","text":"sandhyasthiparvaṇāṃ bhedaḥ kāsaḥ kampo'ratirbhramaḥ śoṣastālvoṣṭhajihvānāṃ tṛṣṇā cārucisaṃyutā"},{"type":"verse","number":"6","sanskrit":"रक्ताः पीताः सिताः स्फोटाः सदाहस्तीव्रवेदनाः भवन्त्यचिरपाकाश्च पित्तकोपसमुद्भवाः","text":"raktāḥ pītāḥ sitāḥ sphoṭāḥ sadāhastīvravedanāḥ bhavantyacirapākāśca pittakopasamudbhavāḥ"},{"type":"verse","number":"7","sanskrit":"विड्भेदश्चाङ्गमर्दश्च दाहस्तृष्णाऽरुचिस्तथा","text":"viḍbhedaścāṅgamardaśca dāhastṛṣṇā'rucistathā"},{"type":"verse","number":"8","sanskrit":"मुखपाकोऽक्षिपाकश्च ज्वरस्तीव्रः सुदारुणः रक्तजासु भवन्त्येते विकाराः पित्तलक्षणाः","text":"mukhapāko'kṣipākaśca jvarastīvraḥ sudāruṇaḥ raktajāsu bhavantyete vikārāḥ pittalakṣaṇāḥ"},{"type":"verse","number":"9","sanskrit":"कफप्रसेकः स्तैमित्यं शिरोरुग्गात्रगौरवम् हृल्लासः सारुचिर्निद्रा तन्द्रा ऽलस्यसमन्विता","text":"kaphaprasekaḥ staimityaṃ śiroruggātragauravam hṛllāsaḥ sārucirnidrā tandrā 'lasyasamanvitā"},{"type":"verse","number":"10","sanskrit":"श्वेताः स्निग्धा भृशं स्थूलाः कण्डूरा मन्दवेदनाः मसूरिकाः कफोद्भूताश्चिरपाकाः प्रकीर्त्तिताः","text":"śvetāḥ snigdhā bhṛśaṃ sthūlāḥ kaṇḍūrā mandavedanāḥ masūrikāḥ kaphodbhūtāścirapākāḥ prakīrttitāḥ"},{"type":"verse","number":"11","sanskrit":"नीलाश्चिपिटविस्तीर्णा मध्ये निम्ना महारुजः पूतिस्रावाश्चिरात्पाकाः प्रभूताः सर्वदोषजाः","text":"nīlāścipiṭavistīrṇā madhye nimnā mahārujaḥ pūtisrāvāścirātpākāḥ prabhūtāḥ sarvadoṣajāḥ"},{"type":"verse","number":"12","sanskrit":"अथ सप्तधातुगतमसूरिकाणां पृथक् पृथक् लक्षणानि मसूरिकास्त्वचं प्राप्तास्तोयबुद्बुदसन्निभाः स्वल्पदोषाः प्रजायन्ते भिन्नास्तोयं स्रवन्ति च","text":"atha saptadhātugatamasūrikāṇāṃ pṛthak pṛthak lakṣaṇāni masūrikāstvacaṃ prāptāstoyabudbudasannibhāḥ svalpadoṣāḥ prajāyante bhinnāstoyaṃ sravanti ca"},{"type":"verse","number":"13","sanskrit":"रक्तस्था लोहिताकाराः शीघ्रपाकास्तनुत्वचः साध्या नात्यर्थदुष्टास्तु भिन्ना रक्तं स्रवन्ति च","text":"raktasthā lohitākārāḥ śīghrapākāstanutvacaḥ sādhyā nātyarthaduṣṭāstu bhinnā raktaṃ sravanti ca"},{"type":"verse","number":"14","sanskrit":"मांसस्थाः कठिनाः स्निग्धाश्चिरपाका घनत्वचः गात्रशूलतृषाकण्डूज्वरारतिसमन्विताः","text":"māṃsasthāḥ kaṭhināḥ snigdhāścirapākā ghanatvacaḥ gātraśūlatṛṣākaṇḍūjvarāratisamanvitāḥ"},{"type":"verse","number":"15","sanskrit":"मेदोजा मण्डलाकारा मृदवः किञ्चिदुन्नताः घोरज्वरपरीताश्च स्थूलाः स्निग्धाः सवेदनाः सम्मोहारतिसन्तापाः कश्चिदाभ्यो विनिस्तरेत्","text":"medojā maṇḍalākārā mṛdavaḥ kiñcidunnatāḥ ghorajvaraparītāśca sthūlāḥ snigdhāḥ savedanāḥ sammohāratisantāpāḥ kaścidābhyo vinistaret"},{"type":"verse","number":"16","sanskrit":"क्षुद्रा गात्रसमा रुक्षाश्चिपिटाः किञ्चिदुन्नताः मज्जोत्था भृशसम्मोहा वेदनाऽरतिसंयुताः","text":"kṣudrā gātrasamā rukṣāścipiṭāḥ kiñcidunnatāḥ majjotthā bhṛśasammohā vedanā'ratisaṃyutāḥ"},{"type":"verse","number":"17","sanskrit":"भ्रमरेणेव विद्धानि कुर्वन्त्यस्थीनि सर्वतः छिन्दन्ति मर्मधामानि प्राणानाशु हरन्ति च","text":"bhramareṇeva viddhāni kurvantyasthīni sarvataḥ chindanti marmadhāmāni prāṇānāśu haranti ca"},{"type":"verse","number":"18","sanskrit":"पक्वाभाः पिडकाः स्निग्धाः श्लक्ष्णाश्चात्यर्थवेदनाः स्तैमित्यारतिसंमोहदाहोन्मादसमन्विताः","text":"pakvābhāḥ piḍakāḥ snigdhāḥ ślakṣṇāścātyarthavedanāḥ staimityāratisaṃmohadāhonmādasamanvitāḥ"},{"type":"verse","number":"19","sanskrit":"शुक्रजायां मसूर्यान्तु लक्षणानि भवन्ति हि निर्दिष्टं केवलं चिह्नं जीवनं न तु दृश्यते","text":"śukrajāyāṃ masūryāntu lakṣaṇāni bhavanti hi nirdiṣṭaṃ kevalaṃ cihnaṃ jīvanaṃ na tu dṛśyate"},{"type":"verse","number":"20","sanskrit":"दोषमिश्रास्तु सप्तैता द्र ष्टव्या दोषलक्षणैः","text":"doṣamiśrāstu saptaitā dra ṣṭavyā doṣalakṣaṇaiḥ"},{"type":"verse","number":"21","sanskrit":"कण्ठरोधारुचिस्तम्भ प्रलापारतिसंयुताः दुश्चिकित्स्याः समुद्दिष्टाः पिडकाश्चर्मसंज्ञिताः","text":"kaṇṭharodhārucistambha pralāpāratisaṃyutāḥ duścikitsyāḥ samuddiṣṭāḥ piḍakāścarmasaṃjñitāḥ"},{"type":"verse","number":"22","sanskrit":"रोमकूपोन्नतिसमा रागिण्यः कफपित्तजाः कासारोचकसंयुक्ता रोमान्त्यो ज्वरपूर्विकाः","text":"romakūponnatisamā rāgiṇyaḥ kaphapittajāḥ kāsārocakasaṃyuktā romāntyo jvarapūrvikāḥ"},{"type":"verse","number":"23","sanskrit":"त्वग्गता रक्तगाश्चैव पित्तजाः श्लेष्मजास्तथा श्लेष्मपित्तकृताश्चैव सुखसाध्या मसूरिकाः एता विनाऽपि क्रियया प्रशाम्यन्ति शरीरिणाम्","text":"tvaggatā raktagāścaiva pittajāḥ śleṣmajāstathā śleṣmapittakṛtāścaiva sukhasādhyā masūrikāḥ etā vinā'pi kriyayā praśāmyanti śarīriṇām"},{"type":"verse","number":"24","sanskrit":"वातजा वातपित्तोत्था वातश्लेष्मकृताश्च याः कष्टसाध्यतमास्तस्माद् यत्नादेता उपाचरेत्","text":"vātajā vātapittotthā vātaśleṣmakṛtāśca yāḥ kaṣṭasādhyatamāstasmād yatnādetā upācaret"},{"type":"verse","number":"25","sanskrit":"असाध्याः सन्निपातोत्थास्तासां वक्ष्यामि लक्षणम् प्रवालसदृशाः काश्चित्काश्चिज्जम्बूफलोपमाः","text":"asādhyāḥ sannipātotthāstāsāṃ vakṣyāmi lakṣaṇam pravālasadṛśāḥ kāścitkāścijjambūphalopamāḥ"},{"type":"verse","number":"26","sanskrit":"लोहजालसमाः काश्चिदतसीफलसन्निभाः आसां बहुविधा वर्णा जायन्ते दोषभेदतः","text":"lohajālasamāḥ kāścidatasīphalasannibhāḥ āsāṃ bahuvidhā varṇā jāyante doṣabhedataḥ"},{"type":"verse","number":"27","sanskrit":"कासो हिक्का प्रमेहश्च ज्वरस्तीव्रः सुदारुणः प्रलापारतिमूर्च्छाश्च तृष्णा दाहोऽतिघूर्णता","text":"kāso hikkā pramehaśca jvarastīvraḥ sudāruṇaḥ pralāpāratimūrcchāśca tṛṣṇā dāho'tighūrṇatā"},{"type":"verse","number":"28","sanskrit":"मुखेन प्रस्रवेद्र क्तं तथा घ्राणेन चक्षुषा कण्ठे घुर्घुरकं कृत्वा श्वसित्यत्यर्थदारुणम्","text":"mukhena prasravedra ktaṃ tathā ghrāṇena cakṣuṣā kaṇṭhe ghurghurakaṃ kṛtvā śvasityatyarthadāruṇam"},{"type":"verse","number":"29","sanskrit":"मसूरिकाऽभिभूतस्य यस्य तानि भिषग्वरैः लक्षणानीह दृश्यन्ते न देयं तस्य भेषजम्","text":"masūrikā'bhibhūtasya yasya tāni bhiṣagvaraiḥ lakṣaṇānīha dṛśyante na deyaṃ tasya bheṣajam"},{"type":"verse","number":"30","sanskrit":"मसूरिकाऽभिभूतो यो भृशं घ्राणेन निःश्वसेत् स भृशंत्यजति प्राणांस्तृष्णावान्वायुदूषितः","text":"masūrikā'bhibhūto yo bhṛśaṃ ghrāṇena niḥśvaset sa bhṛśaṃtyajati prāṇāṃstṛṣṇāvānvāyudūṣitaḥ"},{"type":"verse","number":"31","sanskrit":"मसूरिकिऽन्ते शोथः स्यात्कूर्परे मणिबन्धके तथांऽसफलके वाऽपि दुश्चिकित्स्यः सुदारुणः","text":"masūriki'nte śothaḥ syātkūrpare maṇibandhake tathāṃ'saphalake vā'pi duścikitsyaḥ sudāruṇaḥ"},{"type":"verse","number":"32","sanskrit":"काश्चिद्विनाऽपि यत्नेन सिध्यन्त्याशु मसूरिकाः","text":"kāścidvinā'pi yatnena sidhyantyāśu masūrikāḥ"},{"type":"verse","number":"33","sanskrit":"दृष्टाः कृच्छ्रतराः काश्चित्काश्चित्सिध्यन्ति वा न वा काश्चिन्नैव तु सिध्यन्ति साध्यपाकाः प्रयत्नतः","text":"dṛṣṭāḥ kṛcchratarāḥ kāścitkāścitsidhyanti vā na vā kāścinnaiva tu sidhyanti sādhyapākāḥ prayatnataḥ"},{"type":"verse","number":"34","sanskrit":"मसूरिकायां कुष्ठेषु लेपनादिक्रियाहिता पित्तश्लेष्मविसर्पोक्ता क्रिया चात्र प्रशस्यते","text":"masūrikāyāṃ kuṣṭheṣu lepanādikriyāhitā pittaśleṣmavisarpoktā kriyā cātra praśasyate"},{"type":"verse","number":"35","sanskrit":"श्वेतचन्दनकल्कोत्थं हिलमोचीभवं द्र वम् पिबेन्मसूरिकाऽरम्भे नैव वा केवलं रसम्","text":"śvetacandanakalkotthaṃ hilamocībhavaṃ dra vam pibenmasūrikā'rambhe naiva vā kevalaṃ rasam"},{"type":"verse","number":"36","sanskrit":"द्वौ पञ्चमूल्यौ रास्ना च धात्र्युशीरं दुरालभा सामृता धान्यकं मुस्तं जयेद्वातमसूरिकाम्","text":"dvau pañcamūlyau rāsnā ca dhātryuśīraṃ durālabhā sāmṛtā dhānyakaṃ mustaṃ jayedvātamasūrikām"},{"type":"verse","number":"37","sanskrit":"मञ्जिष्ठाबहुपात्प्लक्ष शिरीषोदुम्बरत्वचः वातजायां मसूर्यां स्यात्प्रलेपः सर्वतो हितः","text":"mañjiṣṭhābahupātplakṣa śirīṣodumbaratvacaḥ vātajāyāṃ masūryāṃ syātpralepaḥ sarvato hitaḥ"},{"type":"verse","number":"38","sanskrit":"गुडूची मधुकं द्रा क्षा मोरटं दाडिमैः सह पाककाले प्रदातव्यं भेषजं गुडसंयुतम् तेन कुप्यति नो वायुः पाकं यान्ति मसूरिकाः","text":"guḍūcī madhukaṃ drā kṣā moraṭaṃ dāḍimaiḥ saha pākakāle pradātavyaṃ bheṣajaṃ guḍasaṃyutam tena kupyati no vāyuḥ pākaṃ yānti masūrikāḥ"},{"type":"verse","number":"39","sanskrit":"मसूरिकासु भुञ्जीत शालीन्मुद्गमसूरकान्","text":"masūrikāsu bhuñjīta śālīnmudgamasūrakān"},{"type":"verse","number":"40","sanskrit":"रसं मधुरमेवाद्यात्सैन्धवं चाल्पमात्रकम् पटोलमूलं क्वथितं मोरटस्वरसं तथा आदावेव मसूर्यां तु पित्तजायां प्रयोजयेत्","text":"rasaṃ madhuramevādyātsaindhavaṃ cālpamātrakam paṭolamūlaṃ kvathitaṃ moraṭasvarasaṃ tathā ādāveva masūryāṃ tu pittajāyāṃ prayojayet"},{"type":"verse","number":"41","sanskrit":"निम्बः पर्पटकः पाठा पटोलश्चन्दनद्वयम्","text":"nimbaḥ parpaṭakaḥ pāṭhā paṭolaścandanadvayam"},{"type":"verse","number":"42","sanskrit":"उशीरं कटुका धात्री तथा वासा दुरालभा एषां पानं शृतं शीतमुत्तमं शर्कराऽन्वितम्","text":"uśīraṃ kaṭukā dhātrī tathā vāsā durālabhā eṣāṃ pānaṃ śṛtaṃ śītamuttamaṃ śarkarā'nvitam"},{"type":"verse","number":"43","sanskrit":"मसूर्यां पित्तजायान्तु प्रयोक्तव्यं विजानता दाहे ज्वरे विसर्पे च व्रणे पित्ताधिकेऽपि च","text":"masūryāṃ pittajāyāntu prayoktavyaṃ vijānatā dāhe jvare visarpe ca vraṇe pittādhike'pi ca"},{"type":"verse","number":"44","sanskrit":"मसूर्यो रक्तजा नाशं यान्ति शोणितमोक्षणैः वासामुस्तकभूनिम्बत्रिफलेन्द्र यवासकम्","text":"masūryo raktajā nāśaṃ yānti śoṇitamokṣaṇaiḥ vāsāmustakabhūnimbatriphalendra yavāsakam"},{"type":"verse","number":"45","sanskrit":"पटोलारिष्टकं चापि क्वाथयित्वा समाक्षिकम् पिबेत्तेन प्रशाम्यन्ति मसूर्यः कफसम्भवाः","text":"paṭolāriṣṭakaṃ cāpi kvāthayitvā samākṣikam pibettena praśāmyanti masūryaḥ kaphasambhavāḥ"},{"type":"verse","number":"46","sanskrit":"शिरीषोदुम्बरत्वग्भ्यां खदिरारिष्टजैर्दलैः कफोत्थासु मसूरीषु लेपः पित्तोत्थितासु च","text":"śirīṣodumbaratvagbhyāṃ khadirāriṣṭajairdalaiḥ kaphotthāsu masūrīṣu lepaḥ pittotthitāsu ca"},{"type":"verse","number":"47","sanskrit":"निम्बः पर्पटकः पाठा पटोलः कटुरोहिणी चन्दने द्वे उशीरञ्च धात्री वासा दुरालभा","text":"nimbaḥ parpaṭakaḥ pāṭhā paṭolaḥ kaṭurohiṇī candane dve uśīrañca dhātrī vāsā durālabhā"},{"type":"verse","number":"48","sanskrit":"एष निम्बादिकः क्वाथः पीतः शर्करयाऽन्वितः मसूरीं सर्वजां हन्ति विसर्पज्वरसंयुताम्","text":"eṣa nimbādikaḥ kvāthaḥ pītaḥ śarkarayā'nvitaḥ masūrīṃ sarvajāṃ hanti visarpajvarasaṃyutām"},{"type":"verse","number":"49","sanskrit":"उत्थिता प्रविशेद्या च तां पुनर्बाह्यतो नयेत् काञ्चनारत्वचः क्वाथस्ताप्यचूर्णावचूर्णितः","text":"utthitā praviśedyā ca tāṃ punarbāhyato nayet kāñcanāratvacaḥ kvāthastāpyacūrṇāvacūrṇitaḥ"},{"type":"verse","number":"50","sanskrit":"धात्रीफलं समधुकं क्वथितं मधुसंयुतम् मुखे कण्ठे व्रणे जाते गण्डूषार्थं प्रशस्यते अक्ष्णोः सेकं प्रशंसन्ति गवेधुमधुकाम्बुना","text":"dhātrīphalaṃ samadhukaṃ kvathitaṃ madhusaṃyutam mukhe kaṇṭhe vraṇe jāte gaṇḍūṣārthaṃ praśasyate akṣṇoḥ sekaṃ praśaṃsanti gavedhumadhukāmbunā"},{"type":"verse","number":"51","sanskrit":"मधुकं त्रिफला मूर्वा दार्वीत्वङ्नीलमुत्पलम् उशीरलोध्रमञ्जिष्ठाः प्रलेपाश्च्योतने हिताः","text":"madhukaṃ triphalā mūrvā dārvītvaṅnīlamutpalam uśīralodhramañjiṣṭhāḥ pralepāścyotane hitāḥ"},{"type":"verse","number":"52","sanskrit":"नश्यन्त्यनेन दृग्जाता मसूर्यो न भवन्ति च प्रलेपं चक्षुषोर्दद्याद् बहुवारस्य वल्कलैः","text":"naśyantyanena dṛgjātā masūryo na bhavanti ca pralepaṃ cakṣuṣordadyād bahuvārasya valkalaiḥ"},{"type":"verse","number":"53","sanskrit":"पञ्चवल्कलचूर्णेन क्लेदिनीमवधूलयेत् भस्मनाकेचिदिच्छन्ति केचिद्गोमयरेणुना","text":"pañcavalkalacūrṇena kledinīmavadhūlayet bhasmanākecidicchanti kecidgomayareṇunā"},{"type":"verse","number":"54","sanskrit":"सुषवीपत्रनिर्यासं हरिद्रा चूर्णसंयुतम् रोमान्तीज्वरवीसर्पव्रणानां शान्तये पिबेत्","text":"suṣavīpatraniryāsaṃ haridrā cūrṇasaṃyutam romāntījvaravīsarpavraṇānāṃ śāntaye pibet"},{"type":"verse","number":"55","sanskrit":"इति मसूरिकाधिकारः समाप्तः अथ मसूरिकाभेदशीतलाऽधिकारः देव्या शीतलयाऽक्रान्ता मसूर्येव ही शीतला ज्वरयेच्च यथा भूताधिष्ठितो विषमज्वरः","text":"iti masūrikādhikāraḥ samāptaḥ atha masūrikābhedaśītalā'dhikāraḥ devyā śītalayā'krāntā masūryeva hī śītalā jvarayecca yathā bhūtādhiṣṭhito viṣamajvaraḥ"},{"type":"verse","number":"56","sanskrit":"सा च सप्तविधा ख्याता तासां भेदान्प्रचक्ष्महे ज्वरपूर्वा बृहत्स्फोटैः शीतला बृहती भवेत्","text":"sā ca saptavidhā khyātā tāsāṃ bhedānpracakṣmahe jvarapūrvā bṛhatsphoṭaiḥ śītalā bṛhatī bhavet"},{"type":"verse","number":"57","sanskrit":"सप्ताहान्निःसरत्येव सप्ताहात्पूर्णतां व्रजेत् ततस्तृतीये सप्ताहे शुष्यति स्खलति स्वयम्","text":"saptāhānniḥsaratyeva saptāhātpūrṇatāṃ vrajet tatastṛtīye saptāhe śuṣyati skhalati svayam"},{"type":"verse","number":"58","sanskrit":"तासां मध्ये यदा काचित्पाकं गत्वा स्फुटेत्स्रवेत् तत्रावधूलनं कुर्याद्वनगोमयभस्मना","text":"tāsāṃ madhye yadā kācitpākaṃ gatvā sphuṭetsravet tatrāvadhūlanaṃ kuryādvanagomayabhasmanā"},{"type":"verse","number":"59","sanskrit":"निम्बसत्पत्र शाखाभिर्मक्षिकामपसारयेत् जलञ्च शीतलं दद्याज्ज्वरेऽपि न तु तत्पचेत्","text":"nimbasatpatra śākhābhirmakṣikāmapasārayet jalañca śītalaṃ dadyājjvare'pi na tu tatpacet"},{"type":"verse","number":"60","sanskrit":"स्थापयेत्तं स्थले पूते रम्ये रहसि शीतले नाशुचिः संस्पृशेत्तन्तु नच तस्यान्तिकंव्रजेत्","text":"sthāpayettaṃ sthale pūte ramye rahasi śītale nāśuciḥ saṃspṛśettantu naca tasyāntikaṃvrajet"},{"type":"verse","number":"61","sanskrit":"बहवो भिषजो नात्र भेषजं योजयन्ति हि केचित्प्रयोजयन्त्येव मतं तेषामथ ब्रुवे","text":"bahavo bhiṣajo nātra bheṣajaṃ yojayanti hi kecitprayojayantyeva mataṃ teṣāmatha bruve"},{"type":"verse","number":"62","sanskrit":"ये शीतलेन सलिलेन विपिष्य सम्यङ् निम्बाक्षबीजसहितां रजनीं पिबन्ति तेषां भवन्ति न कदाचिदपीह देहे पीडाकराजगति शीतलिकाविकाराः","text":"ye śītalena salilena vipiṣya samyaṅ nimbākṣabījasahitāṃ rajanīṃ pibanti teṣāṃ bhavanti na kadācidapīha dehe pīḍākarājagati śītalikāvikārāḥ"},{"type":"verse","number":"63","sanskrit":"मोचारसेन सहितं सितचन्दनेन वासारसेन मधुकं मधुकेन चाथ आदौ पिबन्ति सुमनास्वरसेन मिश्रं ते नाप्नुवन्ति भुवि शीतलिकाविकारान्","text":"mocārasena sahitaṃ sitacandanena vāsārasena madhukaṃ madhukena cātha ādau pibanti sumanāsvarasena miśraṃ te nāpnuvanti bhuvi śītalikāvikārān"},{"type":"verse","number":"64","sanskrit":"शीतलासु क्रिया कार्या शीतला रक्षया सह बध्नीयान्निम्बपत्राणि परितो भवनान्तरे","text":"śītalāsu kriyā kāryā śītalā rakṣayā saha badhnīyānnimbapatrāṇi parito bhavanāntare"},{"type":"verse","number":"65","sanskrit":"कदाचिदपि नो कार्यमुच्छिष्टस्य प्रवेशनम्","text":"kadācidapi no kāryamucchiṣṭasya praveśanam"},{"type":"verse","number":"66","sanskrit":"स्फोटेष्वपि सदाहेषु रक्षारेणूत्करो हितः तेन ते शोषमायान्ति प्रपाकं न भजन्ति च","text":"sphoṭeṣvapi sadāheṣu rakṣāreṇūtkaro hitaḥ tena te śoṣamāyānti prapākaṃ na bhajanti ca"},{"type":"verse","number":"67","sanskrit":"चन्दनं वासको मुस्तं गुडूची द्रा क्षया सह एषां शीतकषायस्तु शीतलाज्वरनाशनः","text":"candanaṃ vāsako mustaṃ guḍūcī drā kṣayā saha eṣāṃ śītakaṣāyastu śītalājvaranāśanaḥ"},{"type":"verse","number":"68","sanskrit":"जपहोमोपहारैश्च दानस्वस्त्ययनार्चनैः विप्रगोशम्भुगौरीणां पूजनैस्ताः शमं नयेत् स्तोत्रञ्च शीतलादेव्याः पठेच्छीतलिकाऽन्तिके ब्राह्मणः श्रद्धया युक्तस्तेन शाम्यन्ति शीतलाः","text":"japahomopahāraiśca dānasvastyayanārcanaiḥ vipragośambhugaurīṇāṃ pūjanaistāḥ śamaṃ nayet stotrañca śītalādevyāḥ paṭhecchītalikā'ntike brāhmaṇaḥ śraddhayā yuktastena śāmyanti śītalāḥ"},{"type":"verse","number":"69","sanskrit":"अस्य श्रीशीतलास्तोत्रस्य महादेवॠषिरनुष्टुपछन्दः शीतला देवता शीतलोपद्र व शान्त्यर्थं जपे विनियोगः","text":"asya śrīśītalāstotrasya mahādevaṝṣiranuṣṭupachandaḥ śītalā devatā śītalopadra va śāntyarthaṃ jape viniyogaḥ"},{"type":"verse","number":"70","sanskrit":"स्कन्द उवाच भगवन्देवदेवेश शीतलायाः स्तवं शुभम् वक्तुमर्हस्यशेषेण विस्फोटकभयापहम्","text":"skanda uvāca bhagavandevadeveśa śītalāyāḥ stavaṃ śubham vaktumarhasyaśeṣeṇa visphoṭakabhayāpaham"},{"type":"verse","number":"71","sanskrit":"ईश्वर उवाच वन्देऽह शीतलां देवीं रासभस्थां दिगम्बराम् यामासाद्य निवर्त्तेत विस्फोटकभयं महत्","text":"īśvara uvāca vande'ha śītalāṃ devīṃ rāsabhasthāṃ digambarām yāmāsādya nivartteta visphoṭakabhayaṃ mahat"},{"type":"verse","number":"72","sanskrit":"शीतले शीतले चेति यो ब्रूयाद्दाहपीडितः विस्फोटकभयं घोरं क्षिप्रं तस्य प्रणश्यति","text":"śītale śītale ceti yo brūyāddāhapīḍitaḥ visphoṭakabhayaṃ ghoraṃ kṣipraṃ tasya praṇaśyati"},{"type":"verse","number":"73","sanskrit":"यस्त्वामुदकमध्ये तु ध्यात्वासम्पूजयेन्नरः विस्फोटकभयं घोरं कुले तस्य न जायते","text":"yastvāmudakamadhye tu dhyātvāsampūjayennaraḥ visphoṭakabhayaṃ ghoraṃ kule tasya na jāyate"},{"type":"verse","number":"74","sanskrit":"शीतले ज्वरदग्धस्य पूतिगन्धयुतस्य च प्रणष्टचक्षुषः पुंसस्त्वामाहुर्जीवितौषधम्","text":"śītale jvaradagdhasya pūtigandhayutasya ca praṇaṣṭacakṣuṣaḥ puṃsastvāmāhurjīvitauṣadham"},{"type":"verse","number":"75","sanskrit":"नमामि शीतलां देवीं रासभस्थां दिगम्बराम् मार्जनीकलशोपेतां शूर्पालङ्कृतमस्तकाम्","text":"namāmi śītalāṃ devīṃ rāsabhasthāṃ digambarām mārjanīkalaśopetāṃ śūrpālaṅkṛtamastakām"},{"type":"verse","number":"76","sanskrit":"शीतले तनुजान्रोगान्नृणां हरसि दुस्तरान् विस्फोटकविशीर्णानां त्वमेकाऽमृतवर्षिणी","text":"śītale tanujānrogānnṛṇāṃ harasi dustarān visphoṭakaviśīrṇānāṃ tvamekā'mṛtavarṣiṇī"},{"type":"verse","number":"77","sanskrit":"गलगण्डग्रहा रोगा ये चान्ये दारुणा नृणाम् त्वदनुध्यानमात्रेण शीतले यान्ति ते क्षयम्","text":"galagaṇḍagrahā rogā ye cānye dāruṇā nṛṇām tvadanudhyānamātreṇa śītale yānti te kṣayam"},{"type":"verse","number":"78","sanskrit":"न मन्त्रो नौषधं किञ्चित्पापरोगस्य विद्यते त्वमेका शीतले धात्री नान्यां पश्यामि देवताम्","text":"na mantro nauṣadhaṃ kiñcitpāparogasya vidyate tvamekā śītale dhātrī nānyāṃ paśyāmi devatām"},{"type":"verse","number":"79","sanskrit":"मृणालतन्तुसदृशीं नाभिहृन्मध्यसंस्थिताम् यस्त्वां सञ्चिन्तयेद्देवि तस्य मृत्युर्न जायते","text":"mṛṇālatantusadṛśīṃ nābhihṛnmadhyasaṃsthitām yastvāṃ sañcintayeddevi tasya mṛtyurna jāyate"},{"type":"verse","number":"80","sanskrit":"अष्टकं शीतलादेव्या यःपठेन्मानवः सदा विस्फोटकभयं घोरं कुले तस्य न जायते","text":"aṣṭakaṃ śītalādevyā yaḥpaṭhenmānavaḥ sadā visphoṭakabhayaṃ ghoraṃ kule tasya na jāyate"},{"type":"verse","number":"81","sanskrit":"श्रोतव्यं पठिव्यञ्च नरैर्भक्तिसमन्वितैः उपसर्गविनाशाय परं स्वस्त्ययनं महत्","text":"śrotavyaṃ paṭhivyañca narairbhaktisamanvitaiḥ upasargavināśāya paraṃ svastyayanaṃ mahat"},{"type":"verse","number":"82","sanskrit":"शीतलाऽष्टकमेतद्धि न देयं यस्य कस्यचित् किन्तु तस्मै प्रदातव्यं भक्तिश्रद्धाऽन्वितो हि यः","text":"śītalā'ṣṭakametaddhi na deyaṃ yasya kasyacit kintu tasmai pradātavyaṃ bhaktiśraddhā'nvito hi yaḥ"},{"type":"verse","number":"83","sanskrit":"इति श्रीकाशीखण्डे शीतलाष्टकस्तोत्रं सम्पूर्णम् अथ शीतलाया भेदाः वातश्लेष्मसमुद्भूता कोद्र वा कोद्र वाकृतिः तां कश्चित्प्राह पक्वेति सातु पाकं न गच्छति","text":"iti śrīkāśīkhaṇḍe śītalāṣṭakastotraṃ sampūrṇam atha śītalāyā bhedāḥ vātaśleṣmasamudbhūtā kodra vā kodra vākṛtiḥ tāṃ kaścitprāha pakveti sātu pākaṃ na gacchati"},{"type":"verse","number":"84","sanskrit":"जलशूकवदङ्गानि सा विध्यति विशेषतः सप्ताहाद्वादशाहाद्वा शान्तिं याति विनौषधम्","text":"jalaśūkavadaṅgāni sā vidhyati viśeṣataḥ saptāhādvādaśāhādvā śāntiṃ yāti vinauṣadham"},{"type":"verse","number":"85","sanskrit":"यदि वा भेषजं दद्यात्खदिराष्टकनिर्मितम् कषायं हि तदा दद्यात्कोद्र वायाः प्रशान्तये","text":"yadi vā bheṣajaṃ dadyātkhadirāṣṭakanirmitam kaṣāyaṃ hi tadā dadyātkodra vāyāḥ praśāntaye"},{"type":"verse","number":"86","sanskrit":"ऊष्मणा तूष्मजारूपा सकण्डूः स्पर्शनप्रिया नाम्ना पाणिसहा ख्याता सप्ताहाच्छुष्यति स्वयम्","text":"ūṣmaṇā tūṣmajārūpā sakaṇḍūḥ sparśanapriyā nāmnā pāṇisahā khyātā saptāhācchuṣyati svayam"},{"type":"verse","number":"87","sanskrit":"चतुर्थी सर्षपाकारा पीतसर्षपवर्णिनी नाम्ना सर्षपिका ज्ञेयाऽभ्यङ्गमत्र विवर्जयेत्","text":"caturthī sarṣapākārā pītasarṣapavarṇinī nāmnā sarṣapikā jñeyā'bhyaṅgamatra vivarjayet"},{"type":"verse","number":"88","sanskrit":"किञ्चिदूष्मनिमित्तेन जायते राजिकाऽकृतिः एषा भवति बालानां सुखं शुष्यति च स्वयम्","text":"kiñcidūṣmanimittena jāyate rājikā'kṛtiḥ eṣā bhavati bālānāṃ sukhaṃ śuṣyati ca svayam"},{"type":"verse","number":"89","sanskrit":"कोठवज्जायते षष्ठी लोहितोन्नतमण्डला ज्वरपूर्वा व्यथायुक्ता ज्वरस्तिष्ठेद्दिनत्रयम् स्फोटानां मेलनादेषा बहुस्फोटाऽपि दृश्यते","text":"koṭhavajjāyate ṣaṣṭhī lohitonnatamaṇḍalā jvarapūrvā vyathāyuktā jvarastiṣṭheddinatrayam sphoṭānāṃ melanādeṣā bahusphoṭā'pi dṛśyate"},{"type":"verse","number":"90","sanskrit":"एकस्फोटा च कृष्णा च बोद्धव्या चर्मजाऽभिधा","text":"ekasphoṭā ca kṛṣṇā ca boddhavyā carmajā'bhidhā"},{"type":"verse","number":"91","sanskrit":"एताः सप्तापि बोद्धव्याः शीतलादेब्यधिष्ठिताः शीतलोचितमाचारमासु सर्वासु वा चरेत्","text":"etāḥ saptāpi boddhavyāḥ śītalādebyadhiṣṭhitāḥ śītalocitamācāramāsu sarvāsu vā caret"},{"type":"verse","number":"92","sanskrit":"काश्चिद्विनाऽपि यत्नेन सुखं सिद्ध्य्न्ति शीतलाः दृष्टाः कष्टतराः काश्चित्काश्चित्सिध्यन्ति वा न वा काश्चिन्नैव तु सिद्ध्य्न्ति यत्नतोऽपि चिकित्सिताः","text":"kāścidvinā'pi yatnena sukhaṃ siddhynti śītalāḥ dṛṣṭāḥ kaṣṭatarāḥ kāścitkāścitsidhyanti vā na vā kāścinnaiva tu siddhynti yatnato'pi cikitsitāḥ"},{"type":"verse","number":"93","sanskrit":"इति षष्टितमः शीतलामसूरिकाऽधिकारः समाप्तः ६०","text":"iti ṣaṣṭitamaḥ śītalāmasūrikā'dhikāraḥ samāptaḥ 60"}]},{"sthana":"Уттаракханда","number":60,"lang":"sa","content":[{"type":"heading","heading":"Кшудрарога — малые болезни"},{"type":"verse","number":"1","sanskrit":"क्रोधशोकश्रमकृतः शरीरोष्मा शिरोगतः पित्तञ्च केशान्पचति पलितं तेन जायते","text":"krodhaśokaśramakṛtaḥ śarīroṣmā śirogataḥ pittañca keśānpacati palitaṃ tena jāyate"},{"type":"verse","number":"2","sanskrit":"लोहचूर्णस्य कर्षं तु दशार्द्धं चूतमज्जतः धात्रीपलद्वयं पथ्ये द्वे तथैकं बिभीतकम्","text":"lohacūrṇasya karṣaṃ tu daśārddhaṃ cūtamajjataḥ dhātrīpaladvayaṃ pathye dve tathaikaṃ bibhītakam"},{"type":"verse","number":"3","sanskrit":"पिष्ट्वा लोहमये भाण्डे स्थापयेन्निशि वासयेत् लेपोऽयमचिराद्धन्ति पलितं नात्र संशयः","text":"piṣṭvā lohamaye bhāṇḍe sthāpayenniśi vāsayet lepo'yamacirāddhanti palitaṃ nātra saṃśayaḥ"},{"type":"verse","number":"4","sanskrit":"काश्मर्या मूलमादौ सहचरकुसुमं केतकस्यापि मूलं लौहं चूर्ण सभृङ्गं त्रिफलपलयुतं तैलमेभिः पचेद्यः कृत्वा लौहस्य भाण्डे क्षितितलनिहितं स्थापयेन्मासमेकं केशाः काशप्रकाशा अपि मधुपनिभा अस्य योगाद्भवन्ति","text":"kāśmaryā mūlamādau sahacarakusumaṃ ketakasyāpi mūlaṃ lauhaṃ cūrṇa sabhṛṅgaṃ triphalapalayutaṃ tailamebhiḥ pacedyaḥ kṛtvā lauhasya bhāṇḍe kṣititalanihitaṃ sthāpayenmāsamekaṃ keśāḥ kāśaprakāśā api madhupanibhā asya yogādbhavanti"},{"type":"verse","number":"5","sanskrit":"त्रिफला नीलिकापत्रं भृङ्गराजोऽयसो रजः अविमूत्रेण संपिष्टं लेपात्कृष्णीकरं परम्","text":"triphalā nīlikāpatraṃ bhṛṅgarājo'yaso rajaḥ avimūtreṇa saṃpiṣṭaṃ lepātkṛṣṇīkaraṃ param"},{"type":"verse","number":"6","sanskrit":"रोमकूपानुगं पित्तं वातेन सह मूर्च्छितम् प्रच्यावयति रोमाणि ततः श्लेष्मा सशोणितः","text":"romakūpānugaṃ pittaṃ vātena saha mūrcchitam pracyāvayati romāṇi tataḥ śleṣmā saśoṇitaḥ"},{"type":"verse","number":"7","sanskrit":"रुणद्धि रोमकूपांस्तु ततोऽन्येषामसम्भवः तदिन्द्र लुप्तं खालित्यं रुह्येति च विभावयेत्","text":"ruṇaddhi romakūpāṃstu tato'nyeṣāmasambhavaḥ tadindra luptaṃ khālityaṃ ruhyeti ca vibhāvayet"},{"type":"verse","number":"8","sanskrit":"तिक्तपटोलीपत्रस्वरसैर्घृष्ट्वा शमं याति चिरकालजाऽपि रुह्या नियतं दिवसत्रयेणापि","text":"tiktapaṭolīpatrasvarasairghṛṣṭvā śamaṃ yāti cirakālajā'pi ruhyā niyataṃ divasatrayeṇāpi"},{"type":"verse","number":"9","sanskrit":"गोक्षुरस्तिलपुष्पाणि तुल्ये च मधुसर्पिषी शिरः प्रलेपितं तेन केशैः समुपचीयते","text":"gokṣurastilapuṣpāṇi tulye ca madhusarpiṣī śiraḥ pralepitaṃ tena keśaiḥ samupacīyate"},{"type":"verse","number":"10","sanskrit":"हस्तिदन्तमसीं कृत्वा छागीदुग्धं रसाञ्जनम् लोमान्येतेन जायन्ते लेपात्पाणितलेष्वपि","text":"hastidantamasīṃ kṛtvā chāgīdugdhaṃ rasāñjanam lomānyetena jāyante lepātpāṇitaleṣvapi"},{"type":"verse","number":"11","sanskrit":"यष्टीन्दीवरमृद्वीकातैलाज्यक्षीरलेपनैः इन्द्र लुप्तं शमं याति केशाः स्युश्च घना दृढाः","text":"yaṣṭīndīvaramṛdvīkātailājyakṣīralepanaiḥ indra luptaṃ śamaṃ yāti keśāḥ syuśca ghanā dṛḍhāḥ"},{"type":"verse","number":"12","sanskrit":"जातीकरञ्जवरुण करवीराग्निपाचितम् तैलमभ्यञ्जनाद्धन्यादिन्द्र लुप्तं न संशयः","text":"jātīkarañjavaruṇa karavīrāgnipācitam tailamabhyañjanāddhanyādindra luptaṃ na saṃśayaḥ"},{"type":"verse","number":"13","sanskrit":"स्नुहीपयः पयोऽकस्य लाङ्गली मार्कवो विषम् अजामूत्रं सगोमूत्रं रक्तिका सेन्द्र वारुणी","text":"snuhīpayaḥ payo'kasya lāṅgalī mārkavo viṣam ajāmūtraṃ sagomūtraṃ raktikā sendra vāruṇī"},{"type":"verse","number":"14","sanskrit":"सिद्धार्थकस्तीक्ष्णगन्धा सम्यगेभिर्विपाचितम् तैलं भवति नियमात्खालित्यव्याधिनाशनम्","text":"siddhārthakastīkṣṇagandhā samyagebhirvipācitam tailaṃ bhavati niyamātkhālityavyādhināśanam"},{"type":"verse","number":"15","sanskrit":"दारुणा कण्डुरा रूक्षा केशभूमिः प्रजायते मारुतश्लेष्मकोपेन विद्याद्दारुणकन्तु तत्","text":"dāruṇā kaṇḍurā rūkṣā keśabhūmiḥ prajāyate mārutaśleṣmakopena vidyāddāruṇakantu tat"},{"type":"verse","number":"16","sanskrit":"कार्यो दारुणके मूर्ध्नि प्रलेपोमधुसंयुतः प्रियालबीजमधुककुष्ठमाषैः ससैन्धवैः","text":"kāryo dāruṇake mūrdhni pralepomadhusaṃyutaḥ priyālabījamadhukakuṣṭhamāṣaiḥ sasaindhavaiḥ"},{"type":"verse","number":"17","sanskrit":"आम्रबीजं तथा पथ्या द्वयं स्यान्मात्रया समम् दुग्धेन पिष्टं तल्लेपो दारुणं हन्ति दारुणम् दुग्धेन खाखसं बीजं प्रलेपाद्दारुणं हरेत्","text":"āmrabījaṃ tathā pathyā dvayaṃ syānmātrayā samam dugdhena piṣṭaṃ tallepo dāruṇaṃ hanti dāruṇam dugdhena khākhasaṃ bījaṃ pralepāddāruṇaṃ haret"},{"type":"verse","number":"18","sanskrit":"गुञ्जाफलैः शृतं तैलम्भृङ्गराजरसेन च कण्डूदारुणहृत्कुष्ठकापालव्याधिनाशनम्","text":"guñjāphalaiḥ śṛtaṃ tailambhṛṅgarājarasena ca kaṇḍūdāruṇahṛtkuṣṭhakāpālavyādhināśanam"},{"type":"verse","number":"19","sanskrit":"अरुंषि बहुवक्त्राणि बहुक्लेदीनि मूर्द्धनि कफासृक्कृमिकोपेन तानि विद्यादरुंषिकाम्","text":"aruṃṣi bahuvaktrāṇi bahukledīni mūrddhani kaphāsṛkkṛmikopena tāni vidyādaruṃṣikām"},{"type":"verse","number":"20","sanskrit":"नीलोत्पलस्य किञ्जल्को धात्रीफलसमन्वितः यष्टीमधुकयुक्तश्च लेपाद्धन्यादरूषिकाम्","text":"nīlotpalasya kiñjalko dhātrīphalasamanvitaḥ yaṣṭīmadhukayuktaśca lepāddhanyādarūṣikām"},{"type":"verse","number":"21","sanskrit":"त्रिफलाऽयोरजोयष्टीमार्कवोत्पलसारिवाः सैन्धवं पक्वमेतैस्तु तैलं हन्यादरुंषिकाम्","text":"triphalā'yorajoyaṣṭīmārkavotpalasārivāḥ saindhavaṃ pakvametaistu tailaṃ hanyādaruṃṣikām"},{"type":"verse","number":"22","sanskrit":"पिडकामुत्तमाङ्गस्थां वृत्तामुग्ररुजाज्वराम् सर्वात्मिकां सर्वलिङ्गां जानीयादिरिवेल्लिकाम्","text":"piḍakāmuttamāṅgasthāṃ vṛttāmugrarujājvarām sarvātmikāṃ sarvaliṅgāṃ jānīyādirivellikām"},{"type":"verse","number":"23","sanskrit":"पैत्तिकस्य विसर्पस्य याचिकित्सा प्रकीर्त्तिता तयैव भिषगेताञ्च चिकित्सेदिरिवेल्लकाम्","text":"paittikasya visarpasya yācikitsā prakīrttitā tayaiva bhiṣagetāñca cikitsedirivellakām"},{"type":"verse","number":"24","sanskrit":"कर्णस्याभ्यन्तरे जातां पिडकामुग्रवेदनाम् स्थिरां पनसिकां तान्तु विद्याद्वातकफोत्थिताम्","text":"karṇasyābhyantare jātāṃ piḍakāmugravedanām sthirāṃ panasikāṃ tāntu vidyādvātakaphotthitām"},{"type":"verse","number":"25","sanskrit":"भिषक् पनसिकां पूर्वं स्वेदयेदथ लेपयेत्","text":"bhiṣak panasikāṃ pūrvaṃ svedayedatha lepayet"},{"type":"verse","number":"26","sanskrit":"कल्कैर्मनः शिलाकुष्ठनिशातालकदारुभिः पक्वां विज्ञाय तां भित्त्वा व्रणवत्समुपाचरेत्","text":"kalkairmanaḥ śilākuṣṭhaniśātālakadārubhiḥ pakvāṃ vijñāya tāṃ bhittvā vraṇavatsamupācaret"},{"type":"verse","number":"27","sanskrit":"वातश्लेष्मसमुद्भूतः श्वयथुर्हनुसन्धिजः स्थिरो मन्दरुजः स्निग्धः ज्ञेयः पाषाणगर्दभः","text":"vātaśleṣmasamudbhūtaḥ śvayathurhanusandhijaḥ sthiro mandarujaḥ snigdhaḥ jñeyaḥ pāṣāṇagardabhaḥ"},{"type":"verse","number":"28","sanskrit":"पाषाणगर्दभं पूर्वं स्वेदयेत्कुशलो भिषक् ततः पनसिकाप्रोक्तैः कल्कैरुष्णैः प्रलेपयेत्","text":"pāṣāṇagardabhaṃ pūrvaṃ svedayetkuśalo bhiṣak tataḥ panasikāproktaiḥ kalkairuṣṇaiḥ pralepayet"},{"type":"verse","number":"29","sanskrit":"गतश्लैष्मिकशोथघ्नैः कल्कैरन्यैश्च लेपयेत् परिपाकगतं भित्वा व्रणवत्तमुपाचरेत्","text":"gataślaiṣmikaśothaghnaiḥ kalkairanyaiśca lepayet paripākagataṃ bhitvā vraṇavattamupācaret"},{"type":"verse","number":"30","sanskrit":"जलौकोभिर्हृते रक्ते स शाम्यति विनौषधम् एतत्स्थलेषु बहुषु प्रेक्षितं लिखितं ततः","text":"jalaukobhirhṛte rakte sa śāmyati vinauṣadham etatsthaleṣu bahuṣu prekṣitaṃ likhitaṃ tataḥ"},{"type":"verse","number":"31","sanskrit":"शाल्मलीकण्टकप्रख्याः कफमारुतरक्तजाः जायन्ते पिडका यूनां ज्ञेयास्ता मुखदूषिकाः","text":"śālmalīkaṇṭakaprakhyāḥ kaphamārutaraktajāḥ jāyante piḍakā yūnāṃ jñeyāstā mukhadūṣikāḥ"},{"type":"verse","number":"32","sanskrit":"अथ मुखदूषिकाचिकित्सा अङ्गुलस्य चतुर्थांशो मुखलेपो विधीयते मध्यमस्तु त्रिभागः स्यादुत्तमोऽद्धाङ्गुलो भवेत्","text":"atha mukhadūṣikācikitsā aṅgulasya caturthāṃśo mukhalepo vidhīyate madhyamastu tribhāgaḥ syāduttamo'ddhāṅgulo bhavet"},{"type":"verse","number":"33","sanskrit":"स्थितिकालोऽपि तस्योक्तो यावत्कल्को न शुष्यति शुष्कस्तु गुणहीनः स्यात्तथा दूषयति त्वचम्","text":"sthitikālo'pi tasyokto yāvatkalko na śuṣyati śuṣkastu guṇahīnaḥ syāttathā dūṣayati tvacam"},{"type":"verse","number":"34","sanskrit":"लोध्रधान्यवचालेपस्तारुण्यपिडकाऽपहः तद्वद्ग्रोरोचनायुक्तं मरिचं मुखलेपितम्","text":"lodhradhānyavacālepastāruṇyapiḍakā'pahaḥ tadvadgrorocanāyuktaṃ maricaṃ mukhalepitam"},{"type":"verse","number":"35","sanskrit":"सिद्धार्थकवचालोध्रसैन्धवैश्च प्रलेपनम् वमनञ्च निहन्त्याशु पिडकां यौवनोद्भवाम्","text":"siddhārthakavacālodhrasaindhavaiśca pralepanam vamanañca nihantyāśu piḍakāṃ yauvanodbhavām"},{"type":"verse","number":"36","sanskrit":"केवलाः पयसा पिष्टास्तीक्ष्णाः शाल्मलिकण्टकाः आलिप्तं त्र्यहमेतेन भवेत्पद्मोपमं मुखम्","text":"kevalāḥ payasā piṣṭāstīkṣṇāḥ śālmalikaṇṭakāḥ āliptaṃ tryahametena bhavetpadmopamaṃ mukham"},{"type":"verse","number":"37","sanskrit":"क्रोधायासप्रकुपितो वायुः पित्तेन संयुतः मुखमागत्य सहसा मण्डलं प्रसृजत्यतः नीरुजं तनुकं श्यावं मुखे व्यङ्गं तमादिशेत्","text":"krodhāyāsaprakupito vāyuḥ pittena saṃyutaḥ mukhamāgatya sahasā maṇḍalaṃ prasṛjatyataḥ nīrujaṃ tanukaṃ śyāvaṃ mukhe vyaṅgaṃ tamādiśet"},{"type":"verse","number":"38","sanskrit":"कृष्णमेवङ्गुणं वक्त्रे गात्रे वा नीलिकां विदुः","text":"kṛṣṇamevaṅguṇaṃ vaktre gātre vā nīlikāṃ viduḥ"},{"type":"verse","number":"39","sanskrit":"शिरोवेधैः प्रलेपैश्च तथाऽभ्यङ्गैरुपाचरेत् व्यङ्गं च नीलिकां वाऽपि न्यच्छञ्च तिलकालकम्","text":"śirovedhaiḥ pralepaiśca tathā'bhyaṅgairupācaret vyaṅgaṃ ca nīlikāṃ vā'pi nyacchañca tilakālakam"},{"type":"verse","number":"40","sanskrit":"वटङ्कुरा मसूराश्च प्रलेपाद्व्यङ्गनाशनम् व्यङ्गे मञ्जिष्ठया लेपः प्रशस्तो मधुयुक्तया","text":"vaṭaṅkurā masūrāśca pralepādvyaṅganāśanam vyaṅge mañjiṣṭhayā lepaḥ praśasto madhuyuktayā"},{"type":"verse","number":"41","sanskrit":"अथवा लेपनं शस्तं शशस्य रुधिरेण च व्यङ्गहृद्वरुणत्वक्स्यादजामूत्रेण पेषिता","text":"athavā lepanaṃ śastaṃ śaśasya rudhireṇa ca vyaṅgahṛdvaruṇatvaksyādajāmūtreṇa peṣitā"},{"type":"verse","number":"42","sanskrit":"जातीफलस्य लेपस्तु हरेद्व्यङ्गञ्च नीलिकाम् अर्कक्षीरहरिद्रा भ्यां मर्दयित्वा प्रलेपनात् मुखकार्ष्ण्यं शमं याति चिरकालोद्भवं ध्रुवम्","text":"jātīphalasya lepastu haredvyaṅgañca nīlikām arkakṣīraharidrā bhyāṃ mardayitvā pralepanāt mukhakārṣṇyaṃ śamaṃ yāti cirakālodbhavaṃ dhruvam"},{"type":"verse","number":"43","sanskrit":"मसूरैः क्षीरसम्पिष्टैर्लिप्तमास्यं घृतान्वितैः सप्तरात्राद्भवेत्सत्यं पुण्डरीकदलोपमम् वटस्य पाण्डुपत्राणि मालती रक्तचन्दनम्","text":"masūraiḥ kṣīrasampiṣṭairliptamāsyaṃ ghṛtānvitaiḥ saptarātrādbhavetsatyaṃ puṇḍarīkadalopamam vaṭasya pāṇḍupatrāṇi mālatī raktacandanam"},{"type":"verse","number":"44","sanskrit":"कुष्ठं कालीयकं लोध्रमेभिर्लैपं प्रयोजयेत् युवानपिडकानां तु व्यङ्गानां तु विनाशनम् स्यादेतेन मुखञ्चापि वर्जितं नीलिकादिभिः","text":"kuṣṭhaṃ kālīyakaṃ lodhramebhirlaipaṃ prayojayet yuvānapiḍakānāṃ tu vyaṅgānāṃ tu vināśanam syādetena mukhañcāpi varjitaṃ nīlikādibhiḥ"},{"type":"verse","number":"45","sanskrit":"कुङ्कुमं चन्दनं लोघ्रं पतङ्गं रक्तचन्दनम् कालीयकमुशीरञ्च मञ्जिष्ठा मधुयष्टिका","text":"kuṅkumaṃ candanaṃ loghraṃ pataṅgaṃ raktacandanam kālīyakamuśīrañca mañjiṣṭhā madhuyaṣṭikā"},{"type":"verse","number":"46","sanskrit":"पत्रकं पद्मकं पद्मं कुष्ठं गोरोचना निशा लाक्षा दारुहरिद्रा च गैरिकं नागकेशरम्","text":"patrakaṃ padmakaṃ padmaṃ kuṣṭhaṃ gorocanā niśā lākṣā dāruharidrā ca gairikaṃ nāgakeśaram"},{"type":"verse","number":"47","sanskrit":"पलाशकुसुमञ्चापि प्रियङ्गुश्च वटाङ्कुराः मालती च मधूच्छिष्टं सर्षपः सुरभिर्वचा","text":"palāśakusumañcāpi priyaṅguśca vaṭāṅkurāḥ mālatī ca madhūcchiṣṭaṃ sarṣapaḥ surabhirvacā"},{"type":"verse","number":"48","sanskrit":"चतुर्गुणपयः पिष्टैरेतैरक्षमितैः पृथक् पचेन्मन्दाग्नि वैद्यस्तैलं प्रस्थद्वयोन्मितम्","text":"caturguṇapayaḥ piṣṭairetairakṣamitaiḥ pṛthak pacenmandāgni vaidyastailaṃ prasthadvayonmitam"},{"type":"verse","number":"49","sanskrit":"वदनाभ्यञ्जनादेतद्व्यङ्गं नीलिकया सह तिलकं माषकं न्यच्छं नाशयेन्मुखमदूषिकाम्","text":"vadanābhyañjanādetadvyaṅgaṃ nīlikayā saha tilakaṃ māṣakaṃ nyacchaṃ nāśayenmukhamadūṣikām"},{"type":"verse","number":"50","sanskrit":"पद्मिनीकण्टकञ्चापि हरेज्जतुमणिं तथा विदध्याद्वदनं पूर्णचन्द्र मण्डलसुन्दरम्","text":"padminīkaṇṭakañcāpi harejjatumaṇiṃ tathā vidadhyādvadanaṃ pūrṇacandra maṇḍalasundaram"},{"type":"verse","number":"51","sanskrit":"ग्रीवांसकक्षाकरपाददेशे सन्धौ गले वा त्रिभिरेव दोषैः ग्रन्थिः स वल्मीकवदक्रियाणां जातः क्रमेणैवगतः प्रवृद्धिम्","text":"grīvāṃsakakṣākarapādadeśe sandhau gale vā tribhireva doṣaiḥ granthiḥ sa valmīkavadakriyāṇāṃ jātaḥ krameṇaivagataḥ pravṛddhim"},{"type":"verse","number":"52","sanskrit":"मुखैरनेकैः स्रुतितोदवद्भिर्विसर्पवत्सर्पति चोन्नताग्रैः वल्मीकमाहुर्भिषजो विकारं निष्प्रत्यनीकं चिरजं विशेषात्","text":"mukhairanekaiḥ srutitodavadbhirvisarpavatsarpati connatāgraiḥ valmīkamāhurbhiṣajo vikāraṃ niṣpratyanīkaṃ cirajaṃ viśeṣāt"},{"type":"verse","number":"53","sanskrit":"पाणिपादोपरिष्टात्तु च्छिद्रै र्बहुभिरावृतम् वल्मीकं यत्सशोफं स्याद्वर्ज्यं तद्धि विजानता","text":"pāṇipādopariṣṭāttu cchidrai rbahubhirāvṛtam valmīkaṃ yatsaśophaṃ syādvarjyaṃ taddhi vijānatā"},{"type":"verse","number":"54","sanskrit":"शस्त्रेणोत्कृत्य वल्मीकं क्षाराग्निभ्यां प्रसाधयेत् विधानेनार्बुदोक्तेन शोधयित्वा च रोपयेत्","text":"śastreṇotkṛtya valmīkaṃ kṣārāgnibhyāṃ prasādhayet vidhānenārbudoktena śodhayitvā ca ropayet"},{"type":"verse","number":"55","sanskrit":"वल्मीकं तु भवेद्यस्य नातिवृद्धममर्मजम् तत्र संशोधनं कृत्वा शोणितं मोक्षयेद्भिषक्","text":"valmīkaṃ tu bhavedyasya nātivṛddhamamarmajam tatra saṃśodhanaṃ kṛtvā śoṇitaṃ mokṣayedbhiṣak"},{"type":"verse","number":"56","sanskrit":"कुलत्थकानां मूलैश्च गुडूच्या लवणेन च आरेवतस्य मूलैश्च दन्तीमूलैस्तथैव च","text":"kulatthakānāṃ mūlaiśca guḍūcyā lavaṇena ca ārevatasya mūlaiśca dantīmūlaistathaiva ca"},{"type":"verse","number":"57","sanskrit":"श्यामामूलैःसपललैः सक्तुमिश्रैः प्रलेपयेत् सुस्निग्धैश्च सुखोष्णैश्च भिषक्तमुपनाहयेत्","text":"śyāmāmūlaiḥsapalalaiḥ saktumiśraiḥ pralepayet susnigdhaiśca sukhoṣṇaiśca bhiṣaktamupanāhayet"},{"type":"verse","number":"58","sanskrit":"पक्वं तदा विजानीयाद्गतीः सर्वायथाक्रमम् अभिज्ञाय गतिं छित्वा प्रदिह्यान्मतिमान्भिषक्","text":"pakvaṃ tadā vijānīyādgatīḥ sarvāyathākramam abhijñāya gatiṃ chitvā pradihyānmatimānbhiṣak"},{"type":"verse","number":"59","sanskrit":"संशोध्यदुष्टमांसानि क्षारेण प्रतिसारयेत् व्रणं विशुद्धं विज्ञाय रोपयेन्मतिमान्भिषक्","text":"saṃśodhyaduṣṭamāṃsāni kṣāreṇa pratisārayet vraṇaṃ viśuddhaṃ vijñāya ropayenmatimānbhiṣak"},{"type":"verse","number":"60","sanskrit":"मनः शिलालभल्लातसूक्ष्मैलाऽगुरुचन्दनैः जातीपल्लवतक्रैश्च निम्बतैलं विपाचयेत्","text":"manaḥ śilālabhallātasūkṣmailā'gurucandanaiḥ jātīpallavatakraiśca nimbatailaṃ vipācayet"},{"type":"verse","number":"61","sanskrit":"वल्मीकं नाशयेत्तद्धि बहुच्छिद्रं बहुव्रणम्","text":"valmīkaṃ nāśayettaddhi bahucchidraṃ bahuvraṇam"},{"type":"verse","number":"62","sanskrit":"बाहुकक्षांऽसपार्श्वेषु कृष्णस्फोटां सवेदनाम् पित्तप्रकोपसम्भूतां कक्षां तामिति निर्दिशेत्","text":"bāhukakṣāṃ'sapārśveṣu kṛṣṇasphoṭāṃ savedanām pittaprakopasambhūtāṃ kakṣāṃ tāmiti nirdiśet"},{"type":"verse","number":"63","sanskrit":"एकान्तु तादृशीं दृष्ट्वा पिडकां स्फोटसन्निभाम् त्वग्जातां पित्तकोपेन गन्ध मालां प्रचक्षते","text":"ekāntu tādṛśīṃ dṛṣṭvā piḍakāṃ sphoṭasannibhām tvagjātāṃ pittakopena gandha mālāṃ pracakṣate"},{"type":"verse","number":"64","sanskrit":"कक्षाञ्च गन्ध मालाञ्च चिकित्सेच्च चिकित्सकः पैत्तिकस्य विसर्पस्य क्रियया पूर्वमुक्तया","text":"kakṣāñca gandha mālāñca cikitsecca cikitsakaḥ paittikasya visarpasya kriyayā pūrvamuktayā"},{"type":"verse","number":"65","sanskrit":"कक्षाभागेषु विस्फोटा जायन्ते मांसदारणाः अन्तर्दाहज्वरकरा दीप्तपावकसन्निभाः","text":"kakṣābhāgeṣu visphoṭā jāyante māṃsadāraṇāḥ antardāhajvarakarā dīptapāvakasannibhāḥ"},{"type":"verse","number":"66","sanskrit":"सप्ताहाद्वा दशाहाद्वा पक्षाद्वा घ्नन्ति मानवम् तामग्निरोहिणीं विद्यादसाध्यां सान्निपातिकीम्","text":"saptāhādvā daśāhādvā pakṣādvā ghnanti mānavam tāmagnirohiṇīṃ vidyādasādhyāṃ sānnipātikīm"},{"type":"verse","number":"67","sanskrit":"पित्तवीसर्पविधिना साधयेदग्निरोहिणीम् रोहिण्यां लङ्घनं कुर्याद्र क्तमोक्षणरूक्षणम् शरीरस्य च संशुद्धिं तान्तु वृद्धां परित्यजेत्","text":"pittavīsarpavidhinā sādhayedagnirohiṇīm rohiṇyāṃ laṅghanaṃ kuryādra ktamokṣaṇarūkṣaṇam śarīrasya ca saṃśuddhiṃ tāntu vṛddhāṃ parityajet"},{"type":"verse","number":"68","sanskrit":"विदारीकन्दवद् वृत्तां कक्षावङ्क्षणसन्धिषु रक्तां विदारिकां विद्यात्सर्वजां सर्वलक्षणाम्","text":"vidārīkandavad vṛttāṃ kakṣāvaṅkṣaṇasandhiṣu raktāṃ vidārikāṃ vidyātsarvajāṃ sarvalakṣaṇām"},{"type":"verse","number":"69","sanskrit":"विदारिकायां प्रथमं जलौकायोजनं हितम् पाटनञ्च विपक्वायां ततो व्रणविधिः स्मृतः","text":"vidārikāyāṃ prathamaṃ jalaukāyojanaṃ hitam pāṭanañca vipakvāyāṃ tato vraṇavidhiḥ smṛtaḥ"},{"type":"verse","number":"70","sanskrit":"नखमांसमधिष्ठाय वातःपित्तञ्च देहिनाम् करोति दाहपाकौ च तं व्याधिं चिप्पमादिशेत्","text":"nakhamāṃsamadhiṣṭhāya vātaḥpittañca dehinām karoti dāhapākau ca taṃ vyādhiṃ cippamādiśet"},{"type":"verse","number":"71","sanskrit":"अभिघातात्प्रदुष्टो यो नखो रूक्षःसितः खरः भवेत्तं कुनखं विद्यात्कुलीरं वाभिधानतः","text":"abhighātātpraduṣṭo yo nakho rūkṣaḥsitaḥ kharaḥ bhavettaṃ kunakhaṃ vidyātkulīraṃ vābhidhānataḥ"},{"type":"verse","number":"72","sanskrit":"चिप्पं रुधिरमोक्षेण शोधनेनाप्युपाचरेत् गतोष्माणमथैनन्तु सेचयेदुष्णवारिणा","text":"cippaṃ rudhiramokṣeṇa śodhanenāpyupācaret gatoṣmāṇamathainantu secayeduṣṇavāriṇā"},{"type":"verse","number":"73","sanskrit":"शस्त्रेणापि यथायोग्यमुच्छिद्य स्रावयेत्ततः व्रणोक्तेन विधानेन रोपयेत्तं विचक्षणः","text":"śastreṇāpi yathāyogyamucchidya srāvayettataḥ vraṇoktena vidhānena ropayettaṃ vicakṣaṇaḥ"},{"type":"verse","number":"74","sanskrit":"स्वरसेन हरिद्रा याः पात्रे कृत्वायसेऽभयाम् घृष्ट्वा तज्जेन कल्केन लिम्पेच्चिप्पं पुनः पुनः","text":"svarasena haridrā yāḥ pātre kṛtvāyase'bhayām ghṛṣṭvā tajjena kalkena limpeccippaṃ punaḥ punaḥ"},{"type":"verse","number":"75","sanskrit":"काश्मर्याः सप्तभिः पत्रैः कोमलैः परिवेष्टितः अङ्गुलीवेष्टकः पुंसां ध्रुवमाशु प्रशाम्यति","text":"kāśmaryāḥ saptabhiḥ patraiḥ komalaiḥ pariveṣṭitaḥ aṅgulīveṣṭakaḥ puṃsāṃ dhruvamāśu praśāmyati"},{"type":"verse","number":"76","sanskrit":"श्लेष्मविद्र धिकल्पेन कुनखं समुपाचरेत्","text":"śleṣmavidra dhikalpena kunakhaṃ samupācaret"},{"type":"verse","number":"77","sanskrit":"नखकोटिप्रविष्टेन टङ्कणेन न शाम्यति कुनखश्चेत्तदा शैलः सलिले प्लवतेऽपि च","text":"nakhakoṭipraviṣṭena ṭaṅkaṇena na śāmyati kunakhaścettadā śailaḥ salile plavate'pi ca"},{"type":"verse","number":"78","sanskrit":"मर्दनात्पीडनाद्वापि तथैवाप्यभिघाततः मेढ्रचर्म यदा वायुर्भजते सर्वतश्चरन्","text":"mardanātpīḍanādvāpi tathaivāpyabhighātataḥ meḍhracarma yadā vāyurbhajate sarvataścaran"},{"type":"verse","number":"79","sanskrit":"तदा वातोपसृष्टन्तु तच्चर्म परिवर्त्तते सवेदनं सदाहं च पाकञ्च व्रजति क्वचित्","text":"tadā vātopasṛṣṭantu taccarma parivarttate savedanaṃ sadāhaṃ ca pākañca vrajati kvacit"},{"type":"verse","number":"80","sanskrit":"मणेरधस्तात्कोषस्तु ग्रन्थिरूपेण लम्बते सरुजां वातसम्भूतां विद्यात्तां परिवर्त्तिकाम् सकण्डूः कठिना चापि सैव श्लेष्मसमन्विता","text":"maṇeradhastātkoṣastu granthirūpeṇa lambate sarujāṃ vātasambhūtāṃ vidyāttāṃ parivarttikām sakaṇḍūḥ kaṭhinā cāpi saiva śleṣmasamanvitā"},{"type":"verse","number":"81","sanskrit":"परिवर्त्तिं घृताभ्यक्तां सुस्विन्नामुपनाहयेत् त्रिरात्रं पञ्चरात्रञ्च वातघ्नैः शाल्वणादिभिः","text":"parivarttiṃ ghṛtābhyaktāṃ susvinnāmupanāhayet trirātraṃ pañcarātrañca vātaghnaiḥ śālvaṇādibhiḥ"},{"type":"verse","number":"82","sanskrit":"ततोऽभ्यज्य शनैश्चर्म पाटयेत्पीडयेन्मणिम् प्रविष्टे चर्मणि मणौ स्वेदयेदुपनाहनैः","text":"tato'bhyajya śanaiścarma pāṭayetpīḍayenmaṇim praviṣṭe carmaṇi maṇau svedayedupanāhanaiḥ"},{"type":"verse","number":"83","sanskrit":"दद्याद्वातहरान्वस्तीन् स्निग्धान्यन्नानि भोजयेत्","text":"dadyādvātaharānvastīn snigdhānyannāni bhojayet"},{"type":"verse","number":"84","sanskrit":"अल्पीयःखां यदा हर्षाद् बलाद्गच्छेत्स्त्रियं नरः हस्ताभिघातादथवा चर्मण्युद्वर्त्तिते बलात्","text":"alpīyaḥkhāṃ yadā harṣād balādgacchetstriyaṃ naraḥ hastābhighātādathavā carmaṇyudvarttite balāt"},{"type":"verse","number":"85","sanskrit":"मर्दनात्पीडनाद्वापि शुक्रवेगाभिघाततः यस्यावपाट्यते चर्म तं विद्यादवपाटिकाम्","text":"mardanātpīḍanādvāpi śukravegābhighātataḥ yasyāvapāṭyate carma taṃ vidyādavapāṭikām"},{"type":"verse","number":"86","sanskrit":"वातेन कर्कशा रूक्षा सूक्ष्मा कृष्णा रुगन्विता पित्तेन पीता रक्ता वा दाहतृष्णासमन्विता श्लेष्मणा कठिना स्निग्धा कण्डूमत्स्वल्पवेदना","text":"vātena karkaśā rūkṣā sūkṣmā kṛṣṇā ruganvitā pittena pītā raktā vā dāhatṛṣṇāsamanvitā śleṣmaṇā kaṭhinā snigdhā kaṇḍūmatsvalpavedanā"},{"type":"verse","number":"87","sanskrit":"स्नेहस्वेदैरिमां वैद्यश्चिकित्सेदवपाटिकाम्","text":"snehasvedairimāṃ vaidyaścikitsedavapāṭikām"},{"type":"verse","number":"88","sanskrit":"वातोपसृष्टे मेढ्रे तु चर्म संश्रयते मणिम् मणिश्चर्मोपनद्धस्तु मूत्रस्रोतो रुणद्धि च निरुद्धप्रकशे तस्मिन्मन्दधारमवेदनम् मूत्रं प्रवर्त्तते जन्तोर्मणिर्विव्रियते न च","text":"vātopasṛṣṭe meḍhre tu carma saṃśrayate maṇim maṇiścarmopanaddhastu mūtrasroto ruṇaddhi ca niruddhaprakaśe tasminmandadhāramavedanam mūtraṃ pravarttate jantormaṇirvivriyate na ca"},{"type":"verse","number":"89","sanskrit":"निरुद्धप्रकशं विद्यात्सरुजं वातसम्भवम्","text":"niruddhaprakaśaṃ vidyātsarujaṃ vātasambhavam"},{"type":"verse","number":"90","sanskrit":"निरुद्धप्रकशे नाडीं लौहीमुभयतोमुखीम् दारवीं जतुकृतां वा घृताक्तां सम्प्रवेशयेत्","text":"niruddhaprakaśe nāḍīṃ lauhīmubhayatomukhīm dāravīṃ jatukṛtāṃ vā ghṛtāktāṃ sampraveśayet"},{"type":"verse","number":"91","sanskrit":"परिषिञ्चेद्वसां मज्जां शिशुमारवराहयोः चक्रतैलं तथा योज्यं वातघ्नद्र व्यसंयुतम्","text":"pariṣiñcedvasāṃ majjāṃ śiśumāravarāhayoḥ cakratailaṃ tathā yojyaṃ vātaghnadra vyasaṃyutam"},{"type":"verse","number":"92","sanskrit":"त्र्यहात्स्थूलतरां सम्यङ् नाडीं मार्गे प्रवेशयेत् स्रोतो विवर्द्धयेदेवं स्निग्धमन्नञ्च भोजयेत् भित्वा वा सेवनीं मुक्त्वा सद्यः क्षतवदाचरेत्","text":"tryahātsthūlatarāṃ samyaṅ nāḍīṃ mārge praveśayet sroto vivarddhayedevaṃ snigdhamannañca bhojayet bhitvā vā sevanīṃ muktvā sadyaḥ kṣatavadācaret"},{"type":"verse","number":"93","sanskrit":"वेगसन्धारणाद्वायुर्विहतो गुदसंश्रितः निरुणद्धि महत्स्रोतः सूक्ष्मद्वारं करोति च","text":"vegasandhāraṇādvāyurvihato gudasaṃśritaḥ niruṇaddhi mahatsrotaḥ sūkṣmadvāraṃ karoti ca"},{"type":"verse","number":"94","sanskrit":"मार्गस्य सौक्ष्म्यात्कृच्छ्रेण पुरीषं तस्य गच्छति सन्निरुद्ध गुदं व्याधिमेतं विद्यात्सुदुस्तरम्","text":"mārgasya saukṣmyātkṛcchreṇa purīṣaṃ tasya gacchati sanniruddha gudaṃ vyādhimetaṃ vidyātsudustaram"},{"type":"verse","number":"95","sanskrit":"सन्निरुद्धगुदे तैलैः सेको वातहरैर्हितः तथा निरुद्धप्रकशक्रियाऽपि कथिताऽथवा","text":"sanniruddhagude tailaiḥ seko vātaharairhitaḥ tathā niruddhaprakaśakriyā'pi kathitā'thavā"},{"type":"verse","number":"96","sanskrit":"स्नानोत्सादनहीनस्य मलो वृषणसंस्थितः प्रक्लिद्यते यदा स्वेदात्कण्डूं जनयते तदा","text":"snānotsādanahīnasya malo vṛṣaṇasaṃsthitaḥ praklidyate yadā svedātkaṇḍūṃ janayate tadā"},{"type":"verse","number":"97","sanskrit":"ततः कण्डूयनात्क्षिप्रं स्फोटः स्रावश्च जायते प्राहुर्वृषणकच्छूं तां श्लेष्मरक्तप्रकोपजाम्","text":"tataḥ kaṇḍūyanātkṣipraṃ sphoṭaḥ srāvaśca jāyate prāhurvṛṣaṇakacchūṃ tāṃ śleṣmaraktaprakopajām"},{"type":"verse","number":"98","sanskrit":"सर्जाह्वकुष्ठसैन्धवसितसिद्धार्थैः प्रकल्पितो योगः उद्वर्त्तनेन नियतं शमयति वृषणस्य कण्डूतिम्","text":"sarjāhvakuṣṭhasaindhavasitasiddhārthaiḥ prakalpito yogaḥ udvarttanena niyataṃ śamayati vṛṣaṇasya kaṇḍūtim"},{"type":"verse","number":"99","sanskrit":"भिषग्वृषणकच्छूं तु चिकित्सेत्पामरोगवत् अहिपूतननिर्दिष्टक्रिययाऽपि च तां हरेत्","text":"bhiṣagvṛṣaṇakacchūṃ tu cikitsetpāmarogavat ahipūtananirdiṣṭakriyayā'pi ca tāṃ haret"},{"type":"verse","number":"100","sanskrit":"शकृन्मूत्रसमायुक्तेऽधौतेऽपाने शिशोर्भवेत् स्विन्ने वाऽस्नाप्यमानस्य कण्डू रक्तकफोद्भवा","text":"śakṛnmūtrasamāyukte'dhaute'pāne śiśorbhavet svinne vā'snāpyamānasya kaṇḍū raktakaphodbhavā"},{"type":"verse","number":"101","sanskrit":"कण्डूयनात्ततः क्षिप्रं स्फोटः स्रावश्च जायते एकीभूतं व्रणैर्घोरं तं विद्यादहिपूतनम्","text":"kaṇḍūyanāttataḥ kṣipraṃ sphoṭaḥ srāvaśca jāyate ekībhūtaṃ vraṇairghoraṃ taṃ vidyādahipūtanam"},{"type":"verse","number":"102","sanskrit":"तत्र संशोधनैः पूर्वं धात्रीस्तन्यं विशोधयेत् त्रिफलाखदिरक्वाथैर्व्रणानां क्षालनं हितम् शङ्खसौवीरयष्ट्याह्वैर्लेपः कार्योऽहिपूतने","text":"tatra saṃśodhanaiḥ pūrvaṃ dhātrīstanyaṃ viśodhayet triphalākhadirakvāthairvraṇānāṃ kṣālanaṃ hitam śaṅkhasauvīrayaṣṭyāhvairlepaḥ kāryo'hipūtane"},{"type":"verse","number":"103","sanskrit":"प्रवाहिकाऽतिसाराभ्यां निर्गच्छति गुदं बहिः रूक्षदुर्बलदेहस्य गुदभ्रंशं तमादिशेत्","text":"pravāhikā'tisārābhyāṃ nirgacchati gudaṃ bahiḥ rūkṣadurbaladehasya gudabhraṃśaṃ tamādiśet"},{"type":"verse","number":"104","sanskrit":"गुदभ्रंशे गुदं स्विन्नं स्नेहेनाक्तं प्रवेशयेत् प्रविष्टं रोधयेद्यत्नाद्गव्यसच्छिद्र चर्मणा","text":"gudabhraṃśe gudaṃ svinnaṃ snehenāktaṃ praveśayet praviṣṭaṃ rodhayedyatnādgavyasacchidra carmaṇā"},{"type":"verse","number":"105","sanskrit":"पद्मिन्याः कोमलं पत्रं यः खादेच्छर्कराऽन्वितम् एतन्निश्चित्य निर्दिष्टं न तस्य गुदनिर्गमः","text":"padminyāḥ komalaṃ patraṃ yaḥ khādeccharkarā'nvitam etanniścitya nirdiṣṭaṃ na tasya gudanirgamaḥ"},{"type":"verse","number":"106","sanskrit":"मूषकाणां वसाभिर्वा गुदभ्रंशे प्रलेपनम् सुस्विन्नं मूषिकामांसेनाथवा स्वेदयेद् गुदम्","text":"mūṣakāṇāṃ vasābhirvā gudabhraṃśe pralepanam susvinnaṃ mūṣikāmāṃsenāthavā svedayed gudam"},{"type":"verse","number":"107","sanskrit":"वृक्षाम्लानलचङ्गेरीबिल्वपाठायवाग्रजम् तक्रेण शीलयेत् पायुभ्रंशार्त्तोऽनलदीपनम्","text":"vṛkṣāmlānalacaṅgerībilvapāṭhāyavāgrajam takreṇa śīlayet pāyubhraṃśārtto'naladīpanam"},{"type":"verse","number":"108","sanskrit":"मूषका दशमूलानि गृह्णीयादुभयं समम् तयोः क्वाथेन कल्केन पचेत्तैलं यथोदितम्","text":"mūṣakā daśamūlāni gṛhṇīyādubhayaṃ samam tayoḥ kvāthena kalkena pacettailaṃ yathoditam"},{"type":"verse","number":"109","sanskrit":"अभ्यङ्गात्तस्य तैलस्य गुदभ्रंशो विनश्यति विनश्यति तथाऽनेन गुदशूलं भगन्दरम्","text":"abhyaṅgāttasya tailasya gudabhraṃśo vinaśyati vinaśyati tathā'nena gudaśūlaṃ bhagandaram"},{"type":"verse","number":"110","sanskrit":"सदाहो रक्तपर्यन्तस्त्वपाकी तीव्रवेदनः कण्डूमाञ्ज्वरकारी च स स्याच्छूकरदंष्ट्रकः","text":"sadāho raktaparyantastvapākī tīvravedanaḥ kaṇḍūmāñjvarakārī ca sa syācchūkaradaṃṣṭrakaḥ"},{"type":"verse","number":"111","sanskrit":"भृङ्गराजकमूलस्य रजन्या सहितस्य च चूर्णन्तु सहसा लेपाद्वाराहद्विजनाशनम्","text":"bhṛṅgarājakamūlasya rajanyā sahitasya ca cūrṇantu sahasā lepādvārāhadvijanāśanam"},{"type":"verse","number":"112","sanskrit":"राजीवमूलकल्कःपीते गव्येन सर्पिषा प्रातः शमयति शूकरदंष्ट्रं दंष्ट्रोद्भूतंज्वरं घोरम्","text":"rājīvamūlakalkaḥpīte gavyena sarpiṣā prātaḥ śamayati śūkaradaṃṣṭraṃ daṃṣṭrodbhūtaṃjvaraṃ ghoram"},{"type":"verse","number":"113","sanskrit":"रजनी मार्कवं मूलं पिष्टं शीतेन वारिणा तल्लेपाद्धन्ति वीसर्पवाराहदशनाह्वयम्","text":"rajanī mārkavaṃ mūlaṃ piṣṭaṃ śītena vāriṇā tallepāddhanti vīsarpavārāhadaśanāhvayam"},{"type":"verse","number":"114","sanskrit":"गम्भीरामल्पशोथां च सवर्णामुपरिस्थिताम् पाकस्यानुशयीं तान्तु विद्यादन्तः प्रपाकिनीम्","text":"gambhīrāmalpaśothāṃ ca savarṇāmuparisthitām pākasyānuśayīṃ tāntu vidyādantaḥ prapākinīm"},{"type":"verse","number":"115","sanskrit":"हरेदनुशयीं वैद्यः क्रियया श्लेष्मविद्र धेः","text":"haredanuśayīṃ vaidyaḥ kriyayā śleṣmavidra dheḥ"},{"type":"verse","number":"116","sanskrit":"क्लिन्नाङ्गुल्यन्तरौ पादौ कण्डूदाहसमन्वितौ दुष्टकर्दमसंस्पर्शादलसं तं विभावयेत्","text":"klinnāṅgulyantarau pādau kaṇḍūdāhasamanvitau duṣṭakardamasaṃsparśādalasaṃ taṃ vibhāvayet"},{"type":"verse","number":"117","sanskrit":"पादौ सिक्त्वाऽरनालेन लेपनं त्वलसे हितम् पटोलकुनटीनिम्बरोचनामरिचैस्तिलैः","text":"pādau siktvā'ranālena lepanaṃ tvalase hitam paṭolakunaṭīnimbarocanāmaricaistilaiḥ"},{"type":"verse","number":"118","sanskrit":"क्षुद्रा स्वरससिद्धेन कटुतैलेन लेपयेत् ततः कासीसकुनटीतिलचूर्णैर्विचूर्णयेत्","text":"kṣudrā svarasasiddhena kaṭutailena lepayet tataḥ kāsīsakunaṭītilacūrṇairvicūrṇayet"},{"type":"verse","number":"119","sanskrit":"करञ्जबीजं रजनी कासीसं पद्मकं मधु रोचना हरितालञ्च लेपोऽयमलसे हितः","text":"karañjabījaṃ rajanī kāsīsaṃ padmakaṃ madhu rocanā haritālañca lepo'yamalase hitaḥ"},{"type":"verse","number":"120","sanskrit":"परिक्रमणशीलस्य वायुरत्यर्थरूक्षयोः पादयोः कुरुते दारीं सरुजां तलसंश्रिताम्","text":"parikramaṇaśīlasya vāyuratyartharūkṣayoḥ pādayoḥ kurute dārīṃ sarujāṃ talasaṃśritām"},{"type":"verse","number":"121","sanskrit":"पाददार्यां शिरां प्राज्ञो मोचयेत्तलशोधिनीम् स्नेहस्वेदोपपन्नौ तु पादौ वा लेपयेन्मुहुः मधूच्छिष्ठवसामज्जाघृतैः क्षारविमिश्रितैः","text":"pādadāryāṃ śirāṃ prājño mocayettalaśodhinīm snehasvedopapannau tu pādau vā lepayenmuhuḥ madhūcchiṣṭhavasāmajjāghṛtaiḥ kṣāravimiśritaiḥ"},{"type":"verse","number":"122","sanskrit":"सर्जाह्वसिन्धूद्भवयोश्चूर्णं घृतमधुप्लुतम् निर्मथ्य कटुतैलाक्तं हितं पादप्रमार्जने","text":"sarjāhvasindhūdbhavayoścūrṇaṃ ghṛtamadhuplutam nirmathya kaṭutailāktaṃ hitaṃ pādapramārjane"},{"type":"verse","number":"123","sanskrit":"मधुसिक्थकगैरिकवृतगुडमहिषाक्षशालनिर्यासैः गैरिकसहितैर्लेपः पाकस्फुटनापहः सिद्धः","text":"madhusikthakagairikavṛtaguḍamahiṣākṣaśālaniryāsaiḥ gairikasahitairlepaḥ pākasphuṭanāpahaḥ siddhaḥ"},{"type":"verse","number":"124","sanskrit":"उन्मत्तकस्य बीजेन मानकक्षारवारिणा विपक्वं कटुतैलन्तु हन्याद्दारीं न संशयः","text":"unmattakasya bījena mānakakṣāravāriṇā vipakvaṃ kaṭutailantu hanyāddārīṃ na saṃśayaḥ"},{"type":"verse","number":"125","sanskrit":"शर्करोन्मथिते पादे क्षते वा कण्टकादिभिः ग्रन्थिः कोलवदुत्सन्नो जायते कदरस्तु सः","text":"śarkaronmathite pāde kṣate vā kaṇṭakādibhiḥ granthiḥ kolavadutsanno jāyate kadarastu saḥ"},{"type":"verse","number":"126","sanskrit":"दहेत्कदरमुद्धृत्य तैलेन दहनेन वा","text":"dahetkadaramuddhṛtya tailena dahanena vā"},{"type":"verse","number":"127","sanskrit":"कृष्णानि तिलमात्राणि नीरुजानि तमानिच वातपित्तकफोद्रे कात्तान्विद्यात्तिलकालकान्","text":"kṛṣṇāni tilamātrāṇi nīrujāni tamānica vātapittakaphodre kāttānvidyāttilakālakān"},{"type":"verse","number":"128","sanskrit":"अवेदनं स्थिरञ्चैव यत्तु गात्रे प्रदृश्यते माषवत्कृष्णमुत्सन्नमनिलान्मशकं दिशेत्","text":"avedanaṃ sthirañcaiva yattu gātre pradṛśyate māṣavatkṛṣṇamutsannamanilānmaśakaṃ diśet"},{"type":"verse","number":"129","sanskrit":"वित्वचस्तनवः स्फोटाः सूक्ष्माग्राः श्यावपिण्डिकाः भवन्ति कफपित्ताभ्यां क्षिप्रं नाशं प्रयान्ति च","text":"vitvacastanavaḥ sphoṭāḥ sūkṣmāgrāḥ śyāvapiṇḍikāḥ bhavanti kaphapittābhyāṃ kṣipraṃ nāśaṃ prayānti ca"},{"type":"verse","number":"130","sanskrit":"सममुत्सन्नमरुजं मण्डलं कफरक्तजम् सहजं लक्ष्म चैकेषां लक्ष्यो जतुमणिश्च सः","text":"samamutsannamarujaṃ maṇḍalaṃ kapharaktajam sahajaṃ lakṣma caikeṣāṃ lakṣyo jatumaṇiśca saḥ"},{"type":"verse","number":"131","sanskrit":"कृष्णः स्निग्धो जतुमणिर्ज्ञेयः श्लेष्मोत्तरैस्त्रिभिः अरुजं त्वपरे रक्तं लक्ष्मेत्याहुर्भिषग्वराः","text":"kṛṣṇaḥ snigdho jatumaṇirjñeyaḥ śleṣmottaraistribhiḥ arujaṃ tvapare raktaṃ lakṣmetyāhurbhiṣagvarāḥ"},{"type":"verse","number":"132","sanskrit":"चर्मकीलं जतुमणिं मशकांस्तिकालकान् उत्कृत्य शस्त्रेण दहेत्क्षाराग्निभ्यामशेषतः","text":"carmakīlaṃ jatumaṇiṃ maśakāṃstikālakān utkṛtya śastreṇa dahetkṣārāgnibhyāmaśeṣataḥ"},{"type":"verse","number":"133","sanskrit":"महद्वा यदि वा चाल्पं श्यावं वा यदि वाऽसितम् नीरुजं मण्डलं गात्रे न्यच्छं तदभिधीयते","text":"mahadvā yadi vā cālpaṃ śyāvaṃ vā yadi vā'sitam nīrujaṃ maṇḍalaṃ gātre nyacchaṃ tadabhidhīyate"},{"type":"verse","number":"134","sanskrit":"शिरावेधैः प्रलेपैश्च तथाऽभ्यङ्गैरुपाचरेत् न्यच्छं लिम्पेत्पयः पित्तैः कल्कैः क्षीरतरूद्भवैः","text":"śirāvedhaiḥ pralepaiśca tathā'bhyaṅgairupācaret nyacchaṃ limpetpayaḥ pittaiḥ kalkaiḥ kṣīratarūdbhavaiḥ"},{"type":"verse","number":"135","sanskrit":"त्रिभुवनविजयापत्रं मूलं स्थविरस्य शिंशपा चैभिः उद्वर्त्तनं विरचितं न्यच्छव्यङ्गापहं सिद्धम्","text":"tribhuvanavijayāpatraṃ mūlaṃ sthavirasya śiṃśapā caibhiḥ udvarttanaṃ viracitaṃ nyacchavyaṅgāpahaṃ siddham"},{"type":"verse","number":"136","sanskrit":"कण्टकैराचितं वृत्तं कण्डूमत्पाण्डु मण्डलम् पद्मिनीकण्टकप्रख्यैस्तदाख्यं कफवातजम्","text":"kaṇṭakairācitaṃ vṛttaṃ kaṇḍūmatpāṇḍu maṇḍalam padminīkaṇṭakaprakhyaistadākhyaṃ kaphavātajam"},{"type":"verse","number":"137","sanskrit":"पद्मिनीकण्टके रोगे छर्दयेन्निम्बवारिणा तेनैव सिद्धं सक्षौद्रं सर्पिः पातुं प्रदापयेत्","text":"padminīkaṇṭake roge chardayennimbavāriṇā tenaiva siddhaṃ sakṣaudraṃ sarpiḥ pātuṃ pradāpayet"},{"type":"verse","number":"138","sanskrit":"निम्बारग्वधकल्कैर्वा मुहुरुद्वर्त्तनं हितम्","text":"nimbāragvadhakalkairvā muhurudvarttanaṃ hitam"},{"type":"verse","number":"139","sanskrit":"चतुर्गुणेन निम्बोत्थपत्रक्वाथेन गोघृतम् पचेत्ततस्तु निम्बस्य कृतमालस्य पत्रजैः","text":"caturguṇena nimbotthapatrakvāthena goghṛtam pacettatastu nimbasya kṛtamālasya patrajaiḥ"},{"type":"verse","number":"140","sanskrit":"कल्कैर्भूयः पचेत्सिद्धं तत्पिबेत्पलसम्मितम् पद्मिनीकण्टकाद्रो गान्मुक्तो भवति नान्यथा","text":"kalkairbhūyaḥ pacetsiddhaṃ tatpibetpalasammitam padminīkaṇṭakādro gānmukto bhavati nānyathā"},{"type":"verse","number":"141","sanskrit":"स्निग्धा सवर्णा ग्रथिता नीरुजा मुद्गसन्निभा कफवातोत्थिता ज्ञेया बालानामजगल्लिका","text":"snigdhā savarṇā grathitā nīrujā mudgasannibhā kaphavātotthitā jñeyā bālānāmajagallikā"},{"type":"verse","number":"142","sanskrit":"तत्राजगल्लिकां सामां जलौकोभिरुपाचरेत् शुक्तिसौराष्ट्रिकाक्षारकल्कैश्चालेपयेन्मुहुः कठिनां क्षारयोगेन द्रा वयेदजगल्लिकाम्","text":"tatrājagallikāṃ sāmāṃ jalaukobhirupācaret śuktisaurāṣṭrikākṣārakalkaiścālepayenmuhuḥ kaṭhināṃ kṣārayogena drā vayedajagallikām"},{"type":"verse","number":"143","sanskrit":"यवाकारा प्रकठिना ग्रथिता मांससंश्रया पिडका श्लेष्मवाताभ्यां यवप्रख्येति सोच्यते","text":"yavākārā prakaṭhinā grathitā māṃsasaṃśrayā piḍakā śleṣmavātābhyāṃ yavaprakhyeti socyate"},{"type":"verse","number":"144","sanskrit":"घनामवक्रां पिडकामुन्नतां परिमण्डलाम् अन्त्रालजीमल्पपूयां तां विद्यात्कफवातजाम्","text":"ghanāmavakrāṃ piḍakāmunnatāṃ parimaṇḍalām antrālajīmalpapūyāṃ tāṃ vidyātkaphavātajām"},{"type":"verse","number":"145","sanskrit":"अन्त्रालजीयवप्रख्ये पूर्वं स्वेदैरुपाचरेत् मनःशिलादेवदारुकुष्ठकल्कैः प्रलेपयेत् पक्वां व्रणविधानेन तथोक्तेन प्रसाधयेत्","text":"antrālajīyavaprakhye pūrvaṃ svedairupācaret manaḥśilādevadārukuṣṭhakalkaiḥ pralepayet pakvāṃ vraṇavidhānena tathoktena prasādhayet"},{"type":"verse","number":"146","sanskrit":"विवृतास्यां महादाहां पक्वोदुम्बरसन्निभाम् विवृतामिति तां विद्यात्पित्तोत्थां परिमण्डलम् १८८ पद्मकर्णिकवन्मध्ये पिडकां पिडकाचिताम् इन्द्र विद्धान्तु तां विद्याद्वातपित्तोत्थितां भिषक् मण्डलं वृतमुत्सन्नं सरक्तं पिडकाचितम् रुजाकरीं गर्दभिकां तां विद्याद्वातपित्तजाम् विसर्पवत्सर्पति यः शोथस्तनुरपाकवान् दाहज्वरकरः पित्तात्सज्ञेयो जालगर्दभः","text":"vivṛtāsyāṃ mahādāhāṃ pakvodumbarasannibhām vivṛtāmiti tāṃ vidyātpittotthāṃ parimaṇḍalam 188 padmakarṇikavanmadhye piḍakāṃ piḍakācitām indra viddhāntu tāṃ vidyādvātapittotthitāṃ bhiṣak maṇḍalaṃ vṛtamutsannaṃ saraktaṃ piḍakācitam rujākarīṃ gardabhikāṃ tāṃ vidyādvātapittajām visarpavatsarpati yaḥ śothastanurapākavān dāhajvarakaraḥ pittātsajñeyo jālagardabhaḥ"},{"type":"verse","number":"147","sanskrit":"विवृतामिन्द्र विद्धाञ्च गर्दभीं जालगर्दभम् पैत्तिकस्य विसर्पस्य क्रिययासाधयेद् भिषक् पाके तु रोपयेदाज्यैः पक्वैर्मधुरभेषजैः","text":"vivṛtāmindra viddhāñca gardabhīṃ jālagardabham paittikasya visarpasya kriyayāsādhayed bhiṣak pāke tu ropayedājyaiḥ pakvairmadhurabheṣajaiḥ"},{"type":"verse","number":"148","sanskrit":"ग्रथिताः पञ्च वा षड् वा दारुणाः कच्छपोन्नताः कफानिलाभ्यां पिडकाः सा स्मृता कच्छपी बुधैः","text":"grathitāḥ pañca vā ṣaḍ vā dāruṇāḥ kacchaponnatāḥ kaphānilābhyāṃ piḍakāḥ sā smṛtā kacchapī budhaiḥ"},{"type":"verse","number":"149","sanskrit":"कच्छपीं स्वेदयेत्पूर्वं तत एव प्रलेपयेत्","text":"kacchapīṃ svedayetpūrvaṃ tata eva pralepayet"},{"type":"verse","number":"150","sanskrit":"कल्कीकृतैर्निशा कुष्टसितातालकदारुभिः तां पक्वां साधयेच्छीघ्रं भिषग्व्रणचिकित्सया","text":"kalkīkṛtairniśā kuṣṭasitātālakadārubhiḥ tāṃ pakvāṃ sādhayecchīghraṃ bhiṣagvraṇacikitsayā"},{"type":"verse","number":"151","sanskrit":"प्राप्य मांसशिरास्नायुमेदः श्लेष्मा तथाऽनिलः ग्रन्थिं करोत्यसौ भिन्नो मधुसर्पिर्वसानिभम्","text":"prāpya māṃsaśirāsnāyumedaḥ śleṣmā tathā'nilaḥ granthiṃ karotyasau bhinno madhusarpirvasānibham"},{"type":"verse","number":"152","sanskrit":"स्रवति स्रावमत्यर्थं तत्र वृद्धिं गतोऽनिलः मांसं विशोष्य ग्रथितां शर्करां जनयत्यतः","text":"sravati srāvamatyarthaṃ tatra vṛddhiṃ gato'nilaḥ māṃsaṃ viśoṣya grathitāṃ śarkarāṃ janayatyataḥ"},{"type":"verse","number":"153","sanskrit":"दुर्गन्धं क्लिन्नमत्यर्थं नानावर्णं ततः शिराः स्रवन्ति सहसा रक्तं तां विद्याच्छर्कराऽबुदम्","text":"durgandhaṃ klinnamatyarthaṃ nānāvarṇaṃ tataḥ śirāḥ sravanti sahasā raktaṃ tāṃ vidyāccharkarā'budam"},{"type":"verse","number":"154","sanskrit":"मेदोऽबुदविधानेन साधयेच्छर्कराऽबुदम्","text":"medo'budavidhānena sādhayeccharkarā'budam"},{"type":"verse","number":"155","sanskrit":"शक्तस्य चाप्यनुत्साहः कर्मण्यालस्यमुच्यते अस्वास्थ्यं चिन्तयाऽत्यर्थमरतिः कथ्यते बुधैः","text":"śaktasya cāpyanutsāhaḥ karmaṇyālasyamucyate asvāsthyaṃ cintayā'tyarthamaratiḥ kathyate budhaiḥ"},{"type":"verse","number":"156","sanskrit":"उत्क्लिश्यान्नं न निर्गच्छेत्प्रसेकः ष्ठीवनोरितम् हृदयं पीड्यते चास्य तमुत्क्लेशं विनिर्दिशेत्","text":"utkliśyānnaṃ na nirgacchetprasekaḥ ṣṭhīvanoritam hṛdayaṃ pīḍyate cāsya tamutkleśaṃ vinirdiśet"},{"type":"verse","number":"157","sanskrit":"वक्त्रे मधुरता तन्द्रा हृदयोद्वेष्टनं भ्रमः न चान्नं रोचते यस्मै ग्लानिं तस्य विनिर्दिशेत् ग्लानिरोजःक्षयाद् दुःखादजीर्णाच्च श्रमाद्भवेत्","text":"vaktre madhuratā tandrā hṛdayodveṣṭanaṃ bhramaḥ na cānnaṃ rocate yasmai glāniṃ tasya vinirdiśet glānirojaḥkṣayād duḥkhādajīrṇācca śramādbhavet"},{"type":"verse","number":"158","sanskrit":"उदानकोपादाहारसुस्थितत्वाच्च यद्भवेत् पवनस्योर्ध्वगमनं तमुद्गारं प्रचक्षते","text":"udānakopādāhārasusthitatvācca yadbhavet pavanasyordhvagamanaṃ tamudgāraṃ pracakṣate"},{"type":"verse","number":"159","sanskrit":"आटोपो गुडगुडाशब्दः प्रोक्तो जठरसम्भवः तमःस्थस्येव यज्ज्ञानं तत्तमः कथ्यते बुधैः","text":"āṭopo guḍaguḍāśabdaḥ prokto jaṭharasambhavaḥ tamaḥsthasyeva yajjñānaṃ tattamaḥ kathyate budhaiḥ"},{"type":"verse","number":"160","sanskrit":"इत्येक षष्टितमः क्षुद्ररोगाधिकारः समाप्तः ६१","text":"ityeka ṣaṣṭitamaḥ kṣudrarogādhikāraḥ samāptaḥ 61"}]},{"sthana":"Уттаракханда","number":61,"lang":"sa","content":[{"type":"heading","heading":"Широрога — болезни головы"},{"type":"verse","number":"1","sanskrit":"शिरोरोगास्तु जायन्ते वातपित्तकफैस्त्रिभिः सन्निपातेन रक्तेन क्षयेण कृमिभिस्तथा","text":"śirorogāstu jāyante vātapittakaphaistribhiḥ sannipātena raktena kṣayeṇa kṛmibhistathā"},{"type":"verse","number":"2","sanskrit":"सूर्यावर्त्तानन्तवातशङ्ख कार्द्धावभेदकाः एकादशविधस्यास्य लक्षणानि प्रचक्षते","text":"sūryāvarttānantavātaśaṅkha kārddhāvabhedakāḥ ekādaśavidhasyāsya lakṣaṇāni pracakṣate"},{"type":"verse","number":"3","sanskrit":"यस्यानिमित्तं शिरसो रुजश्च भवन्ति तीव्रा निशि चातिमात्रम् बन्धोपतापैः प्रशमो भवेच्च शिरोऽभितापः स समीरणेन","text":"yasyānimittaṃ śiraso rujaśca bhavanti tīvrā niśi cātimātram bandhopatāpaiḥ praśamo bhavecca śiro'bhitāpaḥ sa samīraṇena"},{"type":"verse","number":"4","sanskrit":"यस्योष्णमङ्गारचितं यथैव भवेच्छिरो दह्यति चाक्षिनासम् शीतेन रात्रौ च भवेच्छ्रमश्च शिरोऽभितापः स तु पित्तकोपात्","text":"yasyoṣṇamaṅgāracitaṃ yathaiva bhavecchiro dahyati cākṣināsam śītena rātrau ca bhavecchramaśca śiro'bhitāpaḥ sa tu pittakopāt"},{"type":"verse","number":"5","sanskrit":"शिरो भवेद् यस्य कफोपदिग्धं गुरु प्रतिष्टब्धमथो हिमञ्च शूनाक्षिनासावदनञ्च यस्य शिरोऽभितापः स कफप्रकोपात्","text":"śiro bhaved yasya kaphopadigdhaṃ guru pratiṣṭabdhamatho himañca śūnākṣināsāvadanañca yasya śiro'bhitāpaḥ sa kaphaprakopāt"},{"type":"verse","number":"6","sanskrit":"शिरोऽभितापे त्रितयप्रवृत्ते सर्वाणि लिङ्गानि समुद्भवन्ति","text":"śiro'bhitāpe tritayapravṛtte sarvāṇi liṅgāni samudbhavanti"},{"type":"verse","number":"7","sanskrit":"रक्तात्मकः पित्तसमावलिङ्गः स्पर्शासहत्वं शिरसो भवेच्च","text":"raktātmakaḥ pittasamāvaliṅgaḥ sparśāsahatvaṃ śiraso bhavecca"},{"type":"verse","number":"8","sanskrit":"वसाबलासक्षतसम्भवानां शिरोगतानामतिसङ्क्षयेण क्षयप्रवृत्तः शिरसोऽभितापः कष्टो भवेदुग्ररुजोऽतिमात्रम् संस्वेदनच्छर्दनधूमनस्यैरसृग्विमोक्षैश्च विवृद्धिमेति","text":"vasābalāsakṣatasambhavānāṃ śirogatānāmatisaṅkṣayeṇa kṣayapravṛttaḥ śiraso'bhitāpaḥ kaṣṭo bhavedugrarujo'timātram saṃsvedanacchardanadhūmanasyairasṛgvimokṣaiśca vivṛddhimeti"},{"type":"verse","number":"9","sanskrit":"अङ्गं भ्रमति तुद्येत शिरो विभ्रान्तनेत्रता मूर्च्छा गात्रावसादश्च शिरोरोगे क्षयात्मके","text":"aṅgaṃ bhramati tudyeta śiro vibhrāntanetratā mūrcchā gātrāvasādaśca śiroroge kṣayātmake"},{"type":"verse","number":"10","sanskrit":"निस्तुद्यते यस्य शिरोऽतिमात्रं सम्भक्ष्यमाणं स्फुरतीव चान्तः घ्राणाच्च गच्छेद्रुधिरं सपूयं शिरोऽभितापः कृमिभिः स घोरः","text":"nistudyate yasya śiro'timātraṃ sambhakṣyamāṇaṃ sphuratīva cāntaḥ ghrāṇācca gacchedrudhiraṃ sapūyaṃ śiro'bhitāpaḥ kṛmibhiḥ sa ghoraḥ"},{"type":"verse","number":"11","sanskrit":"सूर्योदयं या प्रति मन्दमन्दमक्षिभ्रुवौ रुक् समुपैति गाढम् विवर्द्धते चांशुमता सहैव सूर्यापवृत्तौ विनिवर्त्तते च","text":"sūryodayaṃ yā prati mandamandamakṣibhruvau ruk samupaiti gāḍham vivarddhate cāṃśumatā sahaiva sūryāpavṛttau vinivarttate ca"},{"type":"verse","number":"12","sanskrit":"शीतेन शान्तिं लभते कदाचिदुष्णेन जन्तुः सुखमाप्नुयाद्वा सर्वात्मकं कष्टतमं विकारं सूर्यापवर्त्तं तमुदाहरन्ति","text":"śītena śāntiṃ labhate kadāciduṣṇena jantuḥ sukhamāpnuyādvā sarvātmakaṃ kaṣṭatamaṃ vikāraṃ sūryāpavarttaṃ tamudāharanti"},{"type":"verse","number":"13","sanskrit":"दोषास्तु दुष्टास्त्रय एव मन्यां सम्पीड्य गाढं स्वरुजां सुतीव्राम् कुर्वन्ति योऽक्ष्णि भ्रुवि शङ्खदेशे स्थितिं करोत्याशु विशेषतस्तु","text":"doṣāstu duṣṭāstraya eva manyāṃ sampīḍya gāḍhaṃ svarujāṃ sutīvrām kurvanti yo'kṣṇi bhruvi śaṅkhadeśe sthitiṃ karotyāśu viśeṣatastu"},{"type":"verse","number":"14","sanskrit":"गण्डस्य पार्श्वे तु करोति कम्पं हनुग्रहं लोचनजान्विकारान् अनन्तवातं तमुदाहरन्ति दोषत्रयोत्थं शिरसो विकारम्","text":"gaṇḍasya pārśve tu karoti kampaṃ hanugrahaṃ locanajānvikārān anantavātaṃ tamudāharanti doṣatrayotthaṃ śiraso vikāram"},{"type":"verse","number":"15","sanskrit":"पित्तरक्तानिला दुष्टाः शङ्खदेशे विमूर्च्छिताः तीव्ररुग्दाहरागं हि शोथं कुर्वन्ति दारुणम्","text":"pittaraktānilā duṣṭāḥ śaṅkhadeśe vimūrcchitāḥ tīvrarugdāharāgaṃ hi śothaṃ kurvanti dāruṇam"},{"type":"verse","number":"16","sanskrit":"स शिरो विषवद्वेगान्निरुध्याशु गलं तथा त्रिरात्राज्जीवितं हन्ति शङ्खको नाम नामतः त्र्यहं जीवति भैषज्यं प्रत्याख्यायास्य कारयेत्","text":"sa śiro viṣavadvegānnirudhyāśu galaṃ tathā trirātrājjīvitaṃ hanti śaṅkhako nāma nāmataḥ tryahaṃ jīvati bhaiṣajyaṃ pratyākhyāyāsya kārayet"},{"type":"verse","number":"17","sanskrit":"रूक्षाशनाद्यध्यशनप्राग्वातावश्यमैथुनैः वेगसन्धारणायासव्यायामैः कुपितोऽनिलः","text":"rūkṣāśanādyadhyaśanaprāgvātāvaśyamaithunaiḥ vegasandhāraṇāyāsavyāyāmaiḥ kupito'nilaḥ"},{"type":"verse","number":"18","sanskrit":"केवलः सकफो वाऽद्ध गृहीत्वा शिरसो बली मन्याभ्रूशङ्खकर्णाक्षिललाटार्द्धेषु वेदनाम्","text":"kevalaḥ sakapho vā'ddha gṛhītvā śiraso balī manyābhrūśaṅkhakarṇākṣilalāṭārddheṣu vedanām"},{"type":"verse","number":"19","sanskrit":"शस्त्राशनिनिभां कुर्यात्तीव्रां सोऽद्धावभेदकः नयनं वाऽथवा श्रोत्रमतिवृद्धो विनाशयेत्","text":"śastrāśaninibhāṃ kuryāttīvrāṃ so'ddhāvabhedakaḥ nayanaṃ vā'thavā śrotramativṛddho vināśayet"},{"type":"verse","number":"20","sanskrit":"वातजातशिरोरोगे स्नेहस्वेदं विघर्षणम् पानाहारोपनाहांश्च कुर्याद्वातामयापहान्","text":"vātajātaśiroroge snehasvedaṃ vigharṣaṇam pānāhāropanāhāṃśca kuryādvātāmayāpahān"},{"type":"verse","number":"21","sanskrit":"कुष्ठमेरण्डमूलञ्च नागरं तक्रपेषितम् कदुष्णं शिरसः पीडां भाले लेपनतो हरेत्","text":"kuṣṭhameraṇḍamūlañca nāgaraṃ takrapeṣitam kaduṣṇaṃ śirasaḥ pīḍāṃ bhāle lepanato haret"},{"type":"verse","number":"22","sanskrit":"रसः श्वासकुठारो यस्तस्य नस्यं विशेषतः शिरः शूलं हरत्येव विधेयो नात्र संशयः","text":"rasaḥ śvāsakuṭhāro yastasya nasyaṃ viśeṣataḥ śiraḥ śūlaṃ haratyeva vidheyo nātra saṃśayaḥ"},{"type":"verse","number":"23","sanskrit":"आ शिरो व्यायतं चर्म षोडशाङ्गुलमुच्छ्रितम् तेनावेष्ट्य शिरोऽधस्तान्माषकल्केन लेपयेत्","text":"ā śiro vyāyataṃ carma ṣoḍaśāṅgulamucchritam tenāveṣṭya śiro'dhastānmāṣakalkena lepayet"},{"type":"verse","number":"24","sanskrit":"निश्चलस्योपविष्टस्य तैलैः कोष्णैः प्रपूरयेत् धारयेदारुजः शान्तेर्यामंयामार्द्धमेव वा","text":"niścalasyopaviṣṭasya tailaiḥ koṣṇaiḥ prapūrayet dhārayedārujaḥ śānteryāmaṃyāmārddhameva vā"},{"type":"verse","number":"25","sanskrit":"शिरोवस्तिर्हरत्येष शिरोरोगं मरुद्भवम् हनुमन्याऽक्षिकर्णार्त्तिमर्दितं मूर्द्धकम्पनम्","text":"śirovastirharatyeṣa śirorogaṃ marudbhavam hanumanyā'kṣikarṇārttimarditaṃ mūrddhakampanam"},{"type":"verse","number":"26","sanskrit":"विना भोजनमेवैष शिरोवस्तिः प्रयुज्यते दिनानि पञ्च वा सप्त रुचितोऽग्रे ततोऽपि च","text":"vinā bhojanamevaiṣa śirovastiḥ prayujyate dināni pañca vā sapta rucito'gre tato'pi ca"},{"type":"verse","number":"27","sanskrit":"ततोऽपनीतस्नेहस्तु मोचयेद्वस्तिबन्धनम् शिरोललाटवदनं ग्रीवांऽसादीन्विमर्दयेत्","text":"tato'panītasnehastu mocayedvastibandhanam śirolalāṭavadanaṃ grīvāṃ'sādīnvimardayet"},{"type":"verse","number":"28","sanskrit":"सुखोष्णेनाम्भसा गात्रं प्रक्षाल्याश्नाति यद्धितम् आमिषं जाङ्गलं पथ्यं तत्र शाल्यादयोऽपि च","text":"sukhoṣṇenāmbhasā gātraṃ prakṣālyāśnāti yaddhitam āmiṣaṃ jāṅgalaṃ pathyaṃ tatra śālyādayo'pi ca"},{"type":"verse","number":"29","sanskrit":"मुद्गमाषान्कुलत्थांश्च खादेद्वा निशि केवलान् कटुकोष्णान्ससर्पिष्कानुष्णं क्षीरं पिबेत्तथा","text":"mudgamāṣānkulatthāṃśca khādedvā niśi kevalān kaṭukoṣṇānsasarpiṣkānuṣṇaṃ kṣīraṃ pibettathā"},{"type":"verse","number":"30","sanskrit":"पित्तात्मके शिरोरोगे शीतानां चन्दनाम्भसा कुमुदोत्पलपद्मानां स्पर्शाः सेव्याश्च मारुताः","text":"pittātmake śiroroge śītānāṃ candanāmbhasā kumudotpalapadmānāṃ sparśāḥ sevyāśca mārutāḥ"},{"type":"verse","number":"31","sanskrit":"सर्पिषः शतधौतस्य शिरसा धारणं हितम् रसः श्वासकुठारोऽल्प कर्पूरः कुङ्कुमं नवम्","text":"sarpiṣaḥ śatadhautasya śirasā dhāraṇaṃ hitam rasaḥ śvāsakuṭhāro'lpa karpūraḥ kuṅkumaṃ navam"},{"type":"verse","number":"32","sanskrit":"सिता छागीपयः सर्वं चन्दनेनानुघर्षयेत् तस्य नस्यं भिषग्दद्यात्पित्तजायां शिरोरुजि किन्तु मस्तकशूलेषु सर्वेष्वेवं हितं मतम्","text":"sitā chāgīpayaḥ sarvaṃ candanenānugharṣayet tasya nasyaṃ bhiṣagdadyātpittajāyāṃ śiroruji kintu mastakaśūleṣu sarveṣvevaṃ hitaṃ matam"},{"type":"verse","number":"33","sanskrit":"गुडनागरकल्कस्य नस्यं मस्तकशूलनुत्","text":"guḍanāgarakalkasya nasyaṃ mastakaśūlanut"},{"type":"verse","number":"34","sanskrit":"रक्तजे पित्तवत्सर्वं भोजनालेपसेचनम् शीतोष्णयोश्च विन्यस्य विशेषो रक्तमोक्षणम्","text":"raktaje pittavatsarvaṃ bhojanālepasecanam śītoṣṇayośca vinyasya viśeṣo raktamokṣaṇam"},{"type":"verse","number":"35","sanskrit":"कफजे लङ्घनं स्वेदो रूक्षोष्णैः पावकात्मकैः सन्निपातभवे कार्या सन्निपातहरी क्रिया पुराणसर्पिषः पानं विशेषेण दिशन्ति हि","text":"kaphaje laṅghanaṃ svedo rūkṣoṣṇaiḥ pāvakātmakaiḥ sannipātabhave kāryā sannipātaharī kriyā purāṇasarpiṣaḥ pānaṃ viśeṣeṇa diśanti hi"},{"type":"verse","number":"36","sanskrit":"एरण्डमूलं तगरं शताह्वा जीवन्तिका रास्निकसैन्धवं च भृङ्गं विडङ्गं मधुयष्टिका च विश्वौषधं कृष्णतिलस्य तैलम्","text":"eraṇḍamūlaṃ tagaraṃ śatāhvā jīvantikā rāsnikasaindhavaṃ ca bhṛṅgaṃ viḍaṅgaṃ madhuyaṣṭikā ca viśvauṣadhaṃ kṛṣṇatilasya tailam"},{"type":"verse","number":"37","sanskrit":"अजापयस्तैलविमिश्रितञ्च चतुर्गुणं भृङ्गरसे विपक्वम् षड्बिन्दवो नासिकया प्रदेयाः सर्वान्निहन्युः शिरसो विकारान्","text":"ajāpayastailavimiśritañca caturguṇaṃ bhṛṅgarase vipakvam ṣaḍbindavo nāsikayā pradeyāḥ sarvānnihanyuḥ śiraso vikārān"},{"type":"verse","number":"38","sanskrit":"च्युतांश्च केशान्पलितांश्च दन्तान्निर्बन्धमूलान्सुदृढीकरोति सुपर्णगृध्रप्रतिमञ्च चक्षुः कुर्वन्ति बाह्वोरधिकं बलञ्च","text":"cyutāṃśca keśānpalitāṃśca dantānnirbandhamūlānsudṛḍhīkaroti suparṇagṛdhrapratimañca cakṣuḥ kurvanti bāhvoradhikaṃ balañca"},{"type":"verse","number":"39","sanskrit":"क्षयजे क्षयनाशाय कर्त्तव्यो बृंहणो विधिः पाने नस्ये च सर्पिः स्याद्वातघ्नैर्मधुरैः शृतम्","text":"kṣayaje kṣayanāśāya karttavyo bṛṃhaṇo vidhiḥ pāne nasye ca sarpiḥ syādvātaghnairmadhuraiḥ śṛtam"},{"type":"verse","number":"40","sanskrit":"कृमिजे व्योषनक्ताह्वशिग्रुबीजैश्च नावनम् अजामूत्रयुतं नस्यं कर्त्तव्यं कृमिनुत्परम्","text":"kṛmije vyoṣanaktāhvaśigrubījaiśca nāvanam ajāmūtrayutaṃ nasyaṃ karttavyaṃ kṛminutparam"},{"type":"verse","number":"41","sanskrit":"सूर्यावर्त्ते विधातव्यं नस्यकर्मादि भेषजम्","text":"sūryāvartte vidhātavyaṃ nasyakarmādi bheṣajam"},{"type":"verse","number":"42","sanskrit":"कुमार्याः स्वरसप्रस्थे धत्तूरस्य रसे तथा भृङ्गराजस्य च रसे प्रस्थद्वयसमायुते","text":"kumāryāḥ svarasaprasthe dhattūrasya rase tathā bhṛṅgarājasya ca rase prasthadvayasamāyute"},{"type":"verse","number":"43","sanskrit":"चतुःप्रस्थमिते क्षीरे तैलप्रस्थं विपाचयेत् कल्कैर्मधुकह्रीबेरमञ्जिष्ठा भद्र मुस्तकैः","text":"catuḥprasthamite kṣīre tailaprasthaṃ vipācayet kalkairmadhukahrīberamañjiṣṭhā bhadra mustakaiḥ"},{"type":"verse","number":"44","sanskrit":"नखकर्पूरभृङ्गैलाजीवन्ती पद्मकुष्ठकैः मार्कवासकतालीस सर्जनिर्यासपत्रकैः","text":"nakhakarpūrabhṛṅgailājīvantī padmakuṣṭhakaiḥ mārkavāsakatālīsa sarjaniryāsapatrakaiḥ"},{"type":"verse","number":"45","sanskrit":"विडङ्गशतपुष्पाऽश्व गन्धागन्धर्वहस्तकैः शोथहृन्नारिकेलाभ्यां कर्षमानैर्विपाचिते","text":"viḍaṅgaśatapuṣpā'śva gandhāgandharvahastakaiḥ śothahṛnnārikelābhyāṃ karṣamānairvipācite"},{"type":"verse","number":"46","sanskrit":"उत्तार्य वस्त्रपूतं तु शुभे भाण्डे सुधूपिते त्रिरात्रमथ गुप्तञ्च धारयेद्विधिवद्भिषक्","text":"uttārya vastrapūtaṃ tu śubhe bhāṇḍe sudhūpite trirātramatha guptañca dhārayedvidhivadbhiṣak"},{"type":"verse","number":"47","sanskrit":"ततस्तु तैलमभ्यङ्गे मूर्ध्नि क्षेपे नियोजयेत् शमयेदर्दितं गाढं मन्यास्तम्भशिरोगदान्","text":"tatastu tailamabhyaṅge mūrdhni kṣepe niyojayet śamayedarditaṃ gāḍhaṃ manyāstambhaśirogadān"},{"type":"verse","number":"48","sanskrit":"तालुनासाऽक्षिजातन्तु शोषं मूर्च्छां हलीमकम् हनुग्रहगदार्त्तिं वा बाधिर्यं कर्णवेदनाम्","text":"tālunāsā'kṣijātantu śoṣaṃ mūrcchāṃ halīmakam hanugrahagadārttiṃ vā bādhiryaṃ karṇavedanām"},{"type":"verse","number":"49","sanskrit":"योजयेत्सगुडं सर्पिर्घृतपूरांश्च भक्षयेत् नावनं क्षीरसर्पिर्भ्यां पानञ्च क्षीरसर्पिषोः","text":"yojayetsaguḍaṃ sarpirghṛtapūrāṃśca bhakṣayet nāvanaṃ kṣīrasarpirbhyāṃ pānañca kṣīrasarpiṣoḥ"},{"type":"verse","number":"50","sanskrit":"क्षीरपिष्टैस्तिलैः स्वेदो जीवनीयैश्च शस्यते भृङ्गराजरसश्छागी क्षीरतुल्योऽकतापितः सूर्यावर्त्तं निहन्त्याशु नस्येनैव प्रयोगराट्","text":"kṣīrapiṣṭaistilaiḥ svedo jīvanīyaiśca śasyate bhṛṅgarājarasaśchāgī kṣīratulyo'katāpitaḥ sūryāvarttaṃ nihantyāśu nasyenaiva prayogarāṭ"},{"type":"verse","number":"51","sanskrit":"अर्द्धावभेदके पूर्वं स्नेहस्वेदौ हि भेषजम् विरेकः कायशुद्धिश्च धूपः स्निग्धोष्णभोजनम्","text":"arddhāvabhedake pūrvaṃ snehasvedau hi bheṣajam virekaḥ kāyaśuddhiśca dhūpaḥ snigdhoṣṇabhojanam"},{"type":"verse","number":"52","sanskrit":"विडङ्गानि तिलान्कृष्णान्समान्पिष्टान्विलेपयेत् नस्यञ्चाप्याचरेत्तस्मादर्द्धभेदो व्यपोहति","text":"viḍaṅgāni tilānkṛṣṇānsamānpiṣṭānvilepayet nasyañcāpyācarettasmādarddhabhedo vyapohati"},{"type":"verse","number":"53","sanskrit":"पिबेत्सशर्करं क्षीरं नीरं वा नारिकेलजम् सुशीतं वाऽपि पानीयं सर्पिर्वा नस्यतस्तयोः","text":"pibetsaśarkaraṃ kṣīraṃ nīraṃ vā nārikelajam suśītaṃ vā'pi pānīyaṃ sarpirvā nasyatastayoḥ"},{"type":"verse","number":"54","sanskrit":"अनन्तवाते कर्त्तव्यः सूर्यावर्तहितो विधिः शिरावेधश्च कर्त्तव्योऽनन्तवातप्रशान्तये","text":"anantavāte karttavyaḥ sūryāvartahito vidhiḥ śirāvedhaśca karttavyo'nantavātapraśāntaye"},{"type":"verse","number":"55","sanskrit":"आहारश्च प्रदातव्यो वातपित्तविनाशनः मधुमस्तकसंयावो घृतपूपो विशेषतः","text":"āhāraśca pradātavyo vātapittavināśanaḥ madhumastakasaṃyāvo ghṛtapūpo viśeṣataḥ"},{"type":"verse","number":"56","sanskrit":"पथ्याऽक्षधात्रीरजनीगुडूचीभूनिम्बनिम्बैःसगुडः कषायः भ्रूशङ्खकर्णाक्षिशिरोऽद्धशूलं निहन्ति नासानिहितः क्षणेन","text":"pathyā'kṣadhātrīrajanīguḍūcībhūnimbanimbaiḥsaguḍaḥ kaṣāyaḥ bhrūśaṅkhakarṇākṣiśiro'ddhaśūlaṃ nihanti nāsānihitaḥ kṣaṇena"},{"type":"verse","number":"57","sanskrit":"दार्वीः हरिद्रा मञ्जिष्ठा सनिम्बोशीरपद्मकम् एतत्प्रलेपनं कुर्याच्छङ्खकस्य प्रशान्तये","text":"dārvīḥ haridrā mañjiṣṭhā sanimbośīrapadmakam etatpralepanaṃ kuryācchaṅkhakasya praśāntaye"},{"type":"verse","number":"58","sanskrit":"शीततोयाभिषेकश्च शीतलक्षीरसेवनम् कल्पश्च क्षीरवृक्षाणां शङ्खके लेपनंहितम्","text":"śītatoyābhiṣekaśca śītalakṣīrasevanam kalpaśca kṣīravṛkṣāṇāṃ śaṅkhake lepanaṃhitam"},{"type":"verse","number":"59","sanskrit":"यष्टीमधुकमाषः स्यात्तुर्यांशं तु विषं भवेत् तयोश्चूर्णं सुसूक्ष्मं स्यात्तच्चूर्णं सर्षपोन्मितम्","text":"yaṣṭīmadhukamāṣaḥ syātturyāṃśaṃ tu viṣaṃ bhavet tayoścūrṇaṃ susūkṣmaṃ syāttaccūrṇaṃ sarṣaponmitam"},{"type":"verse","number":"60","sanskrit":"नासिकाऽभ्यन्तरे न्यस्तं सर्वां शीर्षव्यथांहरेत् दृष्टप्रयोगो योगोऽयमनुभाविभिरादृतः","text":"nāsikā'bhyantare nyastaṃ sarvāṃ śīrṣavyathāṃharet dṛṣṭaprayogo yogo'yamanubhāvibhirādṛtaḥ"},{"type":"verse","number":"61","sanskrit":"आर्द्रं यच्छुक्तिकाचूर्णं चूर्णितं नवसादरम् उभयं योजितं तस्य गन्धान्नश्यति शीर्षरुक्","text":"ārdraṃ yacchuktikācūrṇaṃ cūrṇitaṃ navasādaram ubhayaṃ yojitaṃ tasya gandhānnaśyati śīrṣaruk"},{"type":"verse","number":"62","sanskrit":"इति द्विषष्टित्तमः शिरोरोगाधिकारः समाप्तः","text":"iti dviṣaṣṭittamaḥ śirorogādhikāraḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":62,"lang":"sa","content":[{"type":"heading","heading":"Нетра — болезни глаз"},{"type":"verse","number":"1","sanskrit":"विद्याद्द्व्यङ्गुलबाहुल्यं स्वाङ्गुष्ठोदरसम्मितम् द्व्यङ्गुलंसर्वतः सार्द्धं भिषङ् नयनमण्डलम्","text":"vidyāddvyaṅgulabāhulyaṃ svāṅguṣṭhodarasammitam dvyaṅgulaṃsarvataḥ sārddhaṃ bhiṣaṅ nayanamaṇḍalam"},{"type":"verse","number":"2","sanskrit":"पक्ष्मवर्त्मश्वेतकृष्णदृष्टीनां मण्डलानि तु अनुपूर्वन्तु ते मध्याश्चत्वारोऽन्त्या यथोत्तरम्","text":"pakṣmavartmaśvetakṛṣṇadṛṣṭīnāṃ maṇḍalāni tu anupūrvantu te madhyāścatvāro'ntyā yathottaram"},{"type":"verse","number":"3","sanskrit":"द्वादश व्याधयो दृष्टौ तत्रैवान्यौ गदावुभौ कृष्णमार्गे तु चत्वारो दशैकः शुक्लभागजाः","text":"dvādaśa vyādhayo dṛṣṭau tatraivānyau gadāvubhau kṛṣṇamārge tu catvāro daśaikaḥ śuklabhāgajāḥ"},{"type":"verse","number":"4","sanskrit":"वर्त्मन्येको विंशतिश्च पक्ष्मजौ द्वौ प्रकीर्त्तितौ नव सन्धिषु सर्वस्मिन्नेत्रे सप्तदशोदिताः एवं नेत्रे समस्ताः स्युरष्टसप्ततिरामयाः","text":"vartmanyeko viṃśatiśca pakṣmajau dvau prakīrttitau nava sandhiṣu sarvasminnetre saptadaśoditāḥ evaṃ netre samastāḥ syuraṣṭasaptatirāmayāḥ"},{"type":"verse","number":"5","sanskrit":"वाताद्दश तथा पित्तात्कफाच्चैव त्रयोदश","text":"vātāddaśa tathā pittātkaphāccaiva trayodaśa"},{"type":"verse","number":"6","sanskrit":"रक्तात्षोडश विज्ञेयाः सर्वजाः पञ्चविशतिः बाह्यौ पुनर्द्वौ नयने रोगाः षट्सप्ततिः स्मृताः","text":"raktātṣoḍaśa vijñeyāḥ sarvajāḥ pañcaviśatiḥ bāhyau punardvau nayane rogāḥ ṣaṭsaptatiḥ smṛtāḥ"},{"type":"verse","number":"7","sanskrit":"उष्णाभितप्तस्यजलप्रवेशाद् दूरेक्षणात्स्वप्नविपर्ययाच्च स्वेदाद्र जोधूमनिषेवणाच्च छर्देर्विघाताद्वमनातियोगात्","text":"uṣṇābhitaptasyajalapraveśād dūrekṣaṇātsvapnaviparyayācca svedādra jodhūmaniṣevaṇācca chardervighātādvamanātiyogāt"},{"type":"verse","number":"8","sanskrit":"शुक्तारनालाम्बुकुलत्थमाषाद्विण्मूत्रवातागमनिग्रहाच्च प्रसक्तसंरोदनशोकतापाच्छिरोऽभिघातादतिशीघ्रयानात्","text":"śuktāranālāmbukulatthamāṣādviṇmūtravātāgamanigrahācca prasaktasaṃrodanaśokatāpācchiro'bhighātādatiśīghrayānāt"},{"type":"verse","number":"9","sanskrit":"तथा ॠतूनाञ्च विपर्ययेण क्लेशाभितापादतिमैथुनाच्च बाष्पग्रहात्सूक्ष्मनिरीक्षणाच्च नेत्रे विकारं जनयति दोषाः","text":"tathā ṝtūnāñca viparyayeṇa kleśābhitāpādatimaithunācca bāṣpagrahātsūkṣmanirīkṣaṇācca netre vikāraṃ janayati doṣāḥ"},{"type":"verse","number":"10","sanskrit":"शिराऽनुसारिभिर्दोषैर्विगुणैरूर्ध्वमाश्रितैः जायन्ते नेत्रभागेषु रोगाः परमदारुणाः","text":"śirā'nusāribhirdoṣairviguṇairūrdhvamāśritaiḥ jāyante netrabhāgeṣu rogāḥ paramadāruṇāḥ"},{"type":"verse","number":"11","sanskrit":"मसूरदलमात्रां तु पञ्चभूतप्रसादजाम् खद्योतविस्फुलिङ्गाभां सिद्धां तेजोभिरव्ययैः","text":"masūradalamātrāṃ tu pañcabhūtaprasādajām khadyotavisphuliṅgābhāṃ siddhāṃ tejobhiravyayaiḥ"},{"type":"verse","number":"12","sanskrit":"आवृतां पटलेनाक्ष्णोर्बाह्येन विवराकृतिम् शीतसात्म्यां नृणां दृष्टिमाहुर्नयनचिन्तकाः","text":"āvṛtāṃ paṭalenākṣṇorbāhyena vivarākṛtim śītasātmyāṃ nṛṇāṃ dṛṣṭimāhurnayanacintakāḥ"},{"type":"verse","number":"13","sanskrit":"तेजोजलाश्रितं बाह्यं तेष्वन्यत्पिशिताश्रितम् मेदस्तृतीयं पटलमाश्रितं त्वस्थ्नि चापरम् पञ्चमांशसमं दृष्टेस्तेषां बाहुल्यमिष्यते","text":"tejojalāśritaṃ bāhyaṃ teṣvanyatpiśitāśritam medastṛtīyaṃ paṭalamāśritaṃ tvasthni cāparam pañcamāṃśasamaṃ dṛṣṭesteṣāṃ bāhulyamiṣyate"},{"type":"verse","number":"14","sanskrit":"प्रथमे पटले यस्य दोषो दृष्टेर्व्यवस्थितः अव्यक्तानि स्वरूपाणि कदाचिदथ पश्यति","text":"prathame paṭale yasya doṣo dṛṣṭervyavasthitaḥ avyaktāni svarūpāṇi kadācidatha paśyati"},{"type":"verse","number":"15","sanskrit":"दृष्टिर्भृशं विह्वलति द्वितीयं पटले गते मक्षिकामशकान् केशाञ्चालकानीव पश्यति","text":"dṛṣṭirbhṛśaṃ vihvalati dvitīyaṃ paṭale gate makṣikāmaśakān keśāñcālakānīva paśyati"},{"type":"verse","number":"16","sanskrit":"मण्डलानि पताकाश्च मरीचीन्कुण्डलानि च परिप्लवांश्च विविधान्वर्षमभ्रं तमांसि च","text":"maṇḍalāni patākāśca marīcīnkuṇḍalāni ca pariplavāṃśca vividhānvarṣamabhraṃ tamāṃsi ca"},{"type":"verse","number":"17","sanskrit":"दूरस्थानि च रूपाणि मन्यते च समीपतः समीपस्थानि दूरे च दृष्टेर्गोचरविभ्रमात्","text":"dūrasthāni ca rūpāṇi manyate ca samīpataḥ samīpasthāni dūre ca dṛṣṭergocaravibhramāt"},{"type":"verse","number":"18","sanskrit":"यत्नवानपि चात्यर्थं सूचीच्छिद्रं न पश्यति","text":"yatnavānapi cātyarthaṃ sūcīcchidraṃ na paśyati"},{"type":"verse","number":"19","sanskrit":"ऊर्ध्वं पश्यति नाधस्तात्तृतीयं पटलं गते सुमहान्त्यपि रूपाणि च्छादितानीव चाम्बरैः","text":"ūrdhvaṃ paśyati nādhastāttṛtīyaṃ paṭalaṃ gate sumahāntyapi rūpāṇi cchāditānīva cāmbaraiḥ"},{"type":"verse","number":"20","sanskrit":"कर्णनासाऽक्षिरूपाणि विकृतानि च पश्यति यथादोषञ्च रज्येत दृष्टिर्दोषे बलीयसि","text":"karṇanāsā'kṣirūpāṇi vikṛtāni ca paśyati yathādoṣañca rajyeta dṛṣṭirdoṣe balīyasi"},{"type":"verse","number":"21","sanskrit":"अधःस्थे तु समीपस्थं दूरस्थं चोपरिस्थिते पार्श्वस्थिते पुनर्दोषे पार्श्वस्थानि न पश्यति","text":"adhaḥsthe tu samīpasthaṃ dūrasthaṃ coparisthite pārśvasthite punardoṣe pārśvasthāni na paśyati"},{"type":"verse","number":"22","sanskrit":"समन्ततः स्थिते दोषे संकुलानीव पश्यति दृष्टिमध्यस्थिते दोषे महद्ध्रस्वं च पश्यति","text":"samantataḥ sthite doṣe saṃkulānīva paśyati dṛṣṭimadhyasthite doṣe mahaddhrasvaṃ ca paśyati"},{"type":"verse","number":"23","sanskrit":"दोषे दृष्टिस्थिते तिर्यगेकं वा मन्यते द्विधा द्विधास्थिते द्विधा पश्येद्बहुधा चानवस्थिते","text":"doṣe dṛṣṭisthite tiryagekaṃ vā manyate dvidhā dvidhāsthite dvidhā paśyedbahudhā cānavasthite"},{"type":"verse","number":"24","sanskrit":"तिमिराख्यः स यो दोषश्चतुर्थं पटलं गतः रुणद्धि सर्वतो दृष्टिं लिङ्गनाश इति क्वचित्","text":"timirākhyaḥ sa yo doṣaścaturthaṃ paṭalaṃ gataḥ ruṇaddhi sarvato dṛṣṭiṃ liṅganāśa iti kvacit"},{"type":"verse","number":"25","sanskrit":"अस्मिन्नपि तमोभूते नातिरूढे महागदे चन्द्रा दित्यौ सनक्षत्रावन्तरिक्षे च विद्युतः","text":"asminnapi tamobhūte nātirūḍhe mahāgade candrā dityau sanakṣatrāvantarikṣe ca vidyutaḥ"},{"type":"verse","number":"26","sanskrit":"निर्मलानि च तेजांसि भ्राजिष्णूनीव पश्यति स एव लिङ्गनाशस्तु नीलिकाकाचसंज्ञितः","text":"nirmalāni ca tejāṃsi bhrājiṣṇūnīva paśyati sa eva liṅganāśastu nīlikākācasaṃjñitaḥ"},{"type":"verse","number":"27","sanskrit":"दृष्ट्याश्रयाः षट् च षडेव रोगाः षड् लिङ्गनाशा हि भवन्ति तत्र वातेन पित्तेन कफेन सर्वे रक्तात्परिम्लाय्यभिधश्च षष्ठः","text":"dṛṣṭyāśrayāḥ ṣaṭ ca ṣaḍeva rogāḥ ṣaḍ liṅganāśā hi bhavanti tatra vātena pittena kaphena sarve raktātparimlāyyabhidhaśca ṣaṣṭhaḥ"},{"type":"verse","number":"28","sanskrit":"तथा नरः पित्तविदग्धदृष्टिः कफेन वाऽन्यस्त्वथ धूमदर्शी यो ह्रस्वजात्यो नकुलान्ध्यसंज्ञो गम्भीरसंज्ञश्च तथैव दृष्टिः","text":"tathā naraḥ pittavidagdhadṛṣṭiḥ kaphena vā'nyastvatha dhūmadarśī yo hrasvajātyo nakulāndhyasaṃjño gambhīrasaṃjñaśca tathaiva dṛṣṭiḥ"},{"type":"verse","number":"29","sanskrit":"वातेन खलु रूपाणि भ्रमन्तीव च पश्यति आविलान्यरुणाभानि व्याविद्धानीव मानवः","text":"vātena khalu rūpāṇi bhramantīva ca paśyati āvilānyaruṇābhāni vyāviddhānīva mānavaḥ"},{"type":"verse","number":"30","sanskrit":"पित्तेनादित्यखद्योत शक्रचापतडिद्गुणान् नृत्यतश्चैव शिखिनः सर्वं नीलञ्च पश्यति","text":"pittenādityakhadyota śakracāpataḍidguṇān nṛtyataścaiva śikhinaḥ sarvaṃ nīlañca paśyati"},{"type":"verse","number":"31","sanskrit":"गौरचामरगौराणि श्वेताभ्रप्रतिमानिच पश्येदसूक्ष्माण्यत्यर्थं व्यभ्रे चैवाभ्रसंप्लवम्","text":"gauracāmaragaurāṇi śvetābhrapratimānica paśyedasūkṣmāṇyatyarthaṃ vyabhre caivābhrasaṃplavam"},{"type":"verse","number":"32","sanskrit":"कफेन पश्येद्रू पाणि स्निग्धानि च सितानि च सलिलप्लावितानीव जालकानीव मानवः","text":"kaphena paśyedrū pāṇi snigdhāni ca sitāni ca salilaplāvitānīva jālakānīva mānavaḥ"},{"type":"verse","number":"33","sanskrit":"सन्निपातेन चित्राणि विप्लुतानि च पश्यति बहुधाऽपि द्विधा वाऽपि सर्वाण्येव समन्ततः हीनाधिकाङ्गान्यथ वा ज्योतींष्यपि च पश्यति","text":"sannipātena citrāṇi viplutāni ca paśyati bahudhā'pi dvidhā vā'pi sarvāṇyeva samantataḥ hīnādhikāṅgānyatha vā jyotīṃṣyapi ca paśyati"},{"type":"verse","number":"34","sanskrit":"पश्ये द्र क्तेनरक्तानि तमांसि विविधानि च हरितान्यथ कृष्णानि पीतान्यपि च मानवः","text":"paśye dra ktenaraktāni tamāṃsi vividhāni ca haritānyatha kṛṣṇāni pītānyapi ca mānavaḥ"},{"type":"verse","number":"35","sanskrit":"रक्तेन मूर्च्छितं पित्तंपरिम्लायिनमाचरेत्","text":"raktena mūrcchitaṃ pittaṃparimlāyinamācaret"},{"type":"verse","number":"36","sanskrit":"तेन पीता दिशः पश्येदुद्यन्तमिव भास्करम् विकीर्यमाणान्खद्योतैर्वृक्षांस्तेजोभिरेव हि","text":"tena pītā diśaḥ paśyedudyantamiva bhāskaram vikīryamāṇānkhadyotairvṛkṣāṃstejobhireva hi"},{"type":"verse","number":"37","sanskrit":"वातादिजनितैर्नेत्रवर्णैरपि च षड्विधः लिङ्गनाशो निगदितो वर्णो वातादिजो यथा","text":"vātādijanitairnetravarṇairapi ca ṣaḍvidhaḥ liṅganāśo nigadito varṇo vātādijo yathā"},{"type":"verse","number":"38","sanskrit":"रागोऽरुणो मारुतजः प्रदिष्टो म्लायी च नीलश्च तथैव पित्तात् कफात्सितः शोणितजः सरक्तः समस्तदोषप्रभवो विचित्रः","text":"rāgo'ruṇo mārutajaḥ pradiṣṭo mlāyī ca nīlaśca tathaiva pittāt kaphātsitaḥ śoṇitajaḥ saraktaḥ samastadoṣaprabhavo vicitraḥ"},{"type":"verse","number":"39","sanskrit":"अरुणं मण्डलं वाताच्चञ्चलं परुषं तथा पित्ततो मण्डलं नीलं कांस्याभं वा सपीतकम्","text":"aruṇaṃ maṇḍalaṃ vātāccañcalaṃ paruṣaṃ tathā pittato maṇḍalaṃ nīlaṃ kāṃsyābhaṃ vā sapītakam"},{"type":"verse","number":"40","sanskrit":"श्लेष्मणा बहलं स्निग्धं शङ्खकुन्देन्दुपाण्डुरम्","text":"śleṣmaṇā bahalaṃ snigdhaṃ śaṅkhakundendupāṇḍuram"},{"type":"verse","number":"41","sanskrit":"चलत्पद्मपलाशस्थः शुक्लो बिन्दुरिवाम्भसः मृद्यमाने तु नयने मण्डलं तद्विसर्पति","text":"calatpadmapalāśasthaḥ śuklo bindurivāmbhasaḥ mṛdyamāne tu nayane maṇḍalaṃ tadvisarpati"},{"type":"verse","number":"42","sanskrit":"मण्डलं तु भवेच्चित्रं लिङ्गनाशे त्रिदोषजे प्रवालपद्मपत्राभं मण्डलं शोणितात्मकम्","text":"maṇḍalaṃ tu bhaveccitraṃ liṅganāśe tridoṣaje pravālapadmapatrābhaṃ maṇḍalaṃ śoṇitātmakam"},{"type":"verse","number":"43","sanskrit":"रक्तजं मण्डलं दृष्टौ स्थूलकाचारुणप्रभम् परिम्लायिनि रोगे स्यान्म्लानं नीलमथापि वा दोषक्षयात्स्वयं तत्र कदाचित्स्यात्तु दर्शनम्","text":"raktajaṃ maṇḍalaṃ dṛṣṭau sthūlakācāruṇaprabham parimlāyini roge syānmlānaṃ nīlamathāpi vā doṣakṣayātsvayaṃ tatra kadācitsyāttu darśanam"},{"type":"verse","number":"44","sanskrit":"यथास्वं दोषलिङ्गानि सर्वेष्वेव भवन्ति हि","text":"yathāsvaṃ doṣaliṅgāni sarveṣveva bhavanti hi"},{"type":"verse","number":"45","sanskrit":"पित्तेन दुष्टेन गतेन दृष्टिं पीता भवेद्यस्य नरस्य दृष्टिः पीतानि रूपाणि च तेन पश्येत्स वै नरः पित्तविदग्धदृष्टिः","text":"pittena duṣṭena gatena dṛṣṭiṃ pītā bhavedyasya narasya dṛṣṭiḥ pītāni rūpāṇi ca tena paśyetsa vai naraḥ pittavidagdhadṛṣṭiḥ"},{"type":"verse","number":"46","sanskrit":"प्राप्ते तृतीयं पटलं तु दोषे दिवा न पश्येन्निशि वीक्षते सः रात्रौ स शीतानुगृहीतदृष्टिः पित्ताल्पभावात्सकलानि पश्येत्","text":"prāpte tṛtīyaṃ paṭalaṃ tu doṣe divā na paśyenniśi vīkṣate saḥ rātrau sa śītānugṛhītadṛṣṭiḥ pittālpabhāvātsakalāni paśyet"},{"type":"verse","number":"47","sanskrit":"तथा नरः श्लेष्मविदग्धदृष्टिस्तान्येव शुक्लानि हि मन्यते तु त्रिषु स्थितोऽल्प पटलेषु दोषो नक्तान्ध्यमापादयति प्रसह्य दिवा स सूर्यानुगृहीतदृष्टिः पश्येत्तु रूपाणि कफाल्पभावात्","text":"tathā naraḥ śleṣmavidagdhadṛṣṭistānyeva śuklāni hi manyate tu triṣu sthito'lpa paṭaleṣu doṣo naktāndhyamāpādayati prasahya divā sa sūryānugṛhītadṛṣṭiḥ paśyettu rūpāṇi kaphālpabhāvāt"},{"type":"verse","number":"48","sanskrit":"शोकज्वरायासशिरोऽभितापैरभ्याहता यस्य नरस्य दृष्टिः धूमांस्तु यःपश्यति सर्वभावात्स धूमदर्शीति नरः प्रदिष्टः","text":"śokajvarāyāsaśiro'bhitāpairabhyāhatā yasya narasya dṛṣṭiḥ dhūmāṃstu yaḥpaśyati sarvabhāvātsa dhūmadarśīti naraḥ pradiṣṭaḥ"},{"type":"verse","number":"49","sanskrit":"यो वासरे पश्यति कष्टतोऽथ रूपं महच्चापि निरीक्षतेऽल्पम् रात्रौ पुनर्यः प्रकृतानि पश्येत्स ह्रस्वजात्यो मुनिभिः प्रदिष्टः","text":"yo vāsare paśyati kaṣṭato'tha rūpaṃ mahaccāpi nirīkṣate'lpam rātrau punaryaḥ prakṛtāni paśyetsa hrasvajātyo munibhiḥ pradiṣṭaḥ"},{"type":"verse","number":"50","sanskrit":"विद्योतते यस्य नरस्य दृष्टिर्दोषाभिपन्ना नकुलस्य यद्वत् चित्राणि रूपाणि दिवा च पश्येत्स वै विकारो नकुलान्ध्यसंज्ञः","text":"vidyotate yasya narasya dṛṣṭirdoṣābhipannā nakulasya yadvat citrāṇi rūpāṇi divā ca paśyetsa vai vikāro nakulāndhyasaṃjñaḥ"},{"type":"verse","number":"51","sanskrit":"दृष्टिर्विरूपा श्वसनोपसृष्टा सङ्कोचमभ्यन्तरतः प्रयाति रुजाऽवगाढा च तमक्षिरोगे गम्भीरिकेति प्रवदन्ति धीराः","text":"dṛṣṭirvirūpā śvasanopasṛṣṭā saṅkocamabhyantarataḥ prayāti rujā'vagāḍhā ca tamakṣiroge gambhīriketi pravadanti dhīrāḥ"},{"type":"verse","number":"52","sanskrit":"बाह्यौ पुनर्द्वाविह सम्प्रदिष्टौ निमित्ततश्चाप्यनिमित्ततश्च निमित्ततस्तत्र शिरोऽभितापाज्ज्ञेयस्त्वभिष्यन्दनिदर्शनैः सः","text":"bāhyau punardvāviha sampradiṣṭau nimittataścāpyanimittataśca nimittatastatra śiro'bhitāpājjñeyastvabhiṣyandanidarśanaiḥ saḥ"},{"type":"verse","number":"53","sanskrit":"सुरर्षिगन्धर्वमहोरगाणां सन्दर्शनेनापि च भास्करस्य हन्येत दृष्टिर्मनुजस्य यस्य स लिङ्गनाशस्त्वनिमित्तसञ्ज्ञः","text":"surarṣigandharvamahoragāṇāṃ sandarśanenāpi ca bhāskarasya hanyeta dṛṣṭirmanujasya yasya sa liṅganāśastvanimittasañjñaḥ"},{"type":"verse","number":"54","sanskrit":"तत्राक्षि विस्पष्टमिवावभाति वैदूर्यवर्णा विमला च दृष्टिः विदीर्यते सीदति हीयते वा नृणामभीघातहता तु दृष्टिः","text":"tatrākṣi vispaṣṭamivāvabhāti vaidūryavarṇā vimalā ca dṛṣṭiḥ vidīryate sīdati hīyate vā nṛṇāmabhīghātahatā tu dṛṣṭiḥ"},{"type":"verse","number":"55","sanskrit":"इति दृष्टिगत रोगाः अथ कृष्णमण्डलजा रोगाः यत्सव्रणं शुक्लमथाव्रणञ्च पाकात्ययश्चाप्यजका तथैव चत्वार एते नयनामयास्तु कृष्णप्रदेशे नियता भवन्ति","text":"iti dṛṣṭigata rogāḥ atha kṛṣṇamaṇḍalajā rogāḥ yatsavraṇaṃ śuklamathāvraṇañca pākātyayaścāpyajakā tathaiva catvāra ete nayanāmayāstu kṛṣṇapradeśe niyatā bhavanti"},{"type":"verse","number":"56","sanskrit":"निमग्नरूपं तु भवेद्धि कृष्णे सूच्येव विद्धं प्रतिभाति यद्वै स्रावं स्रवेदुष्णमतीव चापि तत्सव्रणं शुक्लमुदाहरन्ति","text":"nimagnarūpaṃ tu bhaveddhi kṛṣṇe sūcyeva viddhaṃ pratibhāti yadvai srāvaṃ sraveduṣṇamatīva cāpi tatsavraṇaṃ śuklamudāharanti"},{"type":"verse","number":"57","sanskrit":"दृष्टेः समीपे न भवेत्तु यच्च न चावगाढं न च संस्रवेद्यत् अवेदनं यन्न च युग्मशुक्लं तत्सिद्धिमायाति कदाचिदेव","text":"dṛṣṭeḥ samīpe na bhavettu yacca na cāvagāḍhaṃ na ca saṃsravedyat avedanaṃ yanna ca yugmaśuklaṃ tatsiddhimāyāti kadācideva"},{"type":"verse","number":"58","sanskrit":"स्यन्दात्मकं कृष्णगतन्तु शुक्लं शङ्खेन्दुकुन्दप्रतिमावभासम् वैहायसाभ्रप्रतनुप्रकाशमथाव्रणं साध्यतमं वदन्ति","text":"syandātmakaṃ kṛṣṇagatantu śuklaṃ śaṅkhendukundapratimāvabhāsam vaihāyasābhrapratanuprakāśamathāvraṇaṃ sādhyatamaṃ vadanti"},{"type":"verse","number":"59","sanskrit":"गम्भीरजातं बहलञ्च शुक्लं चिरोत्थितञ्चापि वदन्ति कृच्छ्रम्","text":"gambhīrajātaṃ bahalañca śuklaṃ cirotthitañcāpi vadanti kṛcchram"},{"type":"verse","number":"60","sanskrit":"विच्छिन्नमध्यं पिशितावृतञ्च चलं शिरासूतमदृष्टिकृच्च द्वित्वग्गतं लोहितमन्ततश्च चिरोत्थितञ्चापि विवर्जनीयम्","text":"vicchinnamadhyaṃ piśitāvṛtañca calaṃ śirāsūtamadṛṣṭikṛcca dvitvaggataṃ lohitamantataśca cirotthitañcāpi vivarjanīyam"},{"type":"verse","number":"61","sanskrit":"उष्णाश्रुपातः पिडका च कृष्णे यस्मिन्भवेन्मुद्गनिभञ्च शुक्लम् तदप्यसाध्यं प्रवदन्ति केचिदन्ये तु तत्तित्तिरिपक्षतुल्यम्","text":"uṣṇāśrupātaḥ piḍakā ca kṛṣṇe yasminbhavenmudganibhañca śuklam tadapyasādhyaṃ pravadanti kecidanye tu tattittiripakṣatulyam"},{"type":"verse","number":"62","sanskrit":"श्वेतः समाक्रामति सर्वतो हि दोषेण यस्यासितमण्डले तु तमक्षिपाकात्ययमक्षिकोपं सर्वात्मकं वर्जयितव्यमाहुः","text":"śvetaḥ samākrāmati sarvato hi doṣeṇa yasyāsitamaṇḍale tu tamakṣipākātyayamakṣikopaṃ sarvātmakaṃ varjayitavyamāhuḥ"},{"type":"verse","number":"63","sanskrit":"अजापुरीषप्रतिमो रुजावान् सलोहितो लोहितपिच्छिलाश्रुः विगृह्य कृष्णं प्रचयोऽभ्युपैति तं चाजकाजातमिति व्यवस्येत्","text":"ajāpurīṣapratimo rujāvān salohito lohitapicchilāśruḥ vigṛhya kṛṣṇaṃ pracayo'bhyupaiti taṃ cājakājātamiti vyavasyet"},{"type":"verse","number":"64","sanskrit":"इति कृष्णमण्डलजा रोगाः अथ नेत्रशुक्लभागजा रोगाः प्रस्तारिशुक्लक्षतजाधिमांसस्नाय्वर्मसंज्ञाः खलु पञ्च रोगाः स्याच्छुक्तिका चार्जुनपिष्टकौ च जालं शिराणां पिडकाश्च याः स्युः रोगा बलासग्रथितेन सार्द्धमेकादशाक्ष्णोः खलु शुक्लभागे","text":"iti kṛṣṇamaṇḍalajā rogāḥ atha netraśuklabhāgajā rogāḥ prastāriśuklakṣatajādhimāṃsasnāyvarmasaṃjñāḥ khalu pañca rogāḥ syācchuktikā cārjunapiṣṭakau ca jālaṃ śirāṇāṃ piḍakāśca yāḥ syuḥ rogā balāsagrathitena sārddhamekādaśākṣṇoḥ khalu śuklabhāge"},{"type":"verse","number":"65","sanskrit":"प्रस्तार्यर्म तनु स्तीर्णं श्यावं रक्तनिभं सितम्","text":"prastāryarma tanu stīrṇaṃ śyāvaṃ raktanibhaṃ sitam"},{"type":"verse","number":"66","sanskrit":"सुश्वेतं मृदु शुक्लार्म शुक्ले तद् वर्द्धते चिरात्","text":"suśvetaṃ mṛdu śuklārma śukle tad varddhate cirāt"},{"type":"verse","number":"67","sanskrit":"पद्माभं मृदु रक्तार्म यन्मांसं चीयते सिते","text":"padmābhaṃ mṛdu raktārma yanmāṃsaṃ cīyate site"},{"type":"verse","number":"68","sanskrit":"पृथु मृद्वधिमांसार्म बहलञ्च यकृन्निभम्","text":"pṛthu mṛdvadhimāṃsārma bahalañca yakṛnnibham"},{"type":"verse","number":"69","sanskrit":"स्थिरं प्रसारि मांसाढ्यं शुष्कं स्नाय्वर्म पञ्चमम्","text":"sthiraṃ prasāri māṃsāḍhyaṃ śuṣkaṃ snāyvarma pañcamam"},{"type":"verse","number":"70","sanskrit":"श्यावाः स्युः पिशितनिभाश्च बिन्दवो ये शुक्लाभाः सितनिचिताः स शुक्तिसञ्ज्ञः","text":"śyāvāḥ syuḥ piśitanibhāśca bindavo ye śuklābhāḥ sitanicitāḥ sa śuktisañjñaḥ"},{"type":"verse","number":"71","sanskrit":"एको यः शशरुधिरप्रभस्तु बिन्दुः शुक्लस्थो भवति तमर्जुनं वदन्ति","text":"eko yaḥ śaśarudhiraprabhastu binduḥ śuklastho bhavati tamarjunaṃ vadanti"},{"type":"verse","number":"72","sanskrit":"श्लेष्ममारुतकोपेन शुक्ले मांसं समुन्नतम् पिष्टवत्पिष्टकं विद्धि मलाक्तादर्शसन्निभम्","text":"śleṣmamārutakopena śukle māṃsaṃ samunnatam piṣṭavatpiṣṭakaṃ viddhi malāktādarśasannibham"},{"type":"verse","number":"73","sanskrit":"जालाभः कठिनशिरोऽरुणः शिराणां सन्तानो भवति शिराऽदिजालसञ्ज्ञः","text":"jālābhaḥ kaṭhinaśiro'ruṇaḥ śirāṇāṃ santāno bhavati śirā'dijālasañjñaḥ"},{"type":"verse","number":"74","sanskrit":"शुक्लस्थाः सितपिडकाःशिरावृता यास्ता विद्यादसितसमीपजाः शिराजाः","text":"śuklasthāḥ sitapiḍakāḥśirāvṛtā yāstā vidyādasitasamīpajāḥ śirājāḥ"},{"type":"verse","number":"75","sanskrit":"कांस्याभोऽमृदुरथ वारिबिन्दुकल्पो विज्ञेयो नयनसिते बलाससञ्ज्ञः","text":"kāṃsyābho'mṛduratha vāribindukalpo vijñeyo nayanasite balāsasañjñaḥ"},{"type":"verse","number":"76","sanskrit":"इति शुक्ल भागजा रोगा अथ वर्त्मजा रोगाः उत्सङ्गिन्यथ कुम्भीका पोथकी वर्त्मशर्करा तथाऽशोवर्त्म शुष्कार्शस्तथैवाञ्जनदूषिका","text":"iti śukla bhāgajā rogā atha vartmajā rogāḥ utsaṅginyatha kumbhīkā pothakī vartmaśarkarā tathā'śovartma śuṣkārśastathaivāñjanadūṣikā"},{"type":"verse","number":"77","sanskrit":"अभ्यन्तरमुखी ताम्रा बाह्यतो वर्त्मसंश्रया सोत्सङ्गोत्सङ्गपिडका सर्वजा स्थूलकण्डुरा","text":"abhyantaramukhī tāmrā bāhyato vartmasaṃśrayā sotsaṅgotsaṅgapiḍakā sarvajā sthūlakaṇḍurā"},{"type":"verse","number":"78","sanskrit":"वर्त्मान्ते पिडकाध्माता भिद्यन्ते च स्रवन्ति च कुम्भीकाबीजसदृशाः कुम्भीकाः सन्निपातजाः","text":"vartmānte piḍakādhmātā bhidyante ca sravanti ca kumbhīkābījasadṛśāḥ kumbhīkāḥ sannipātajāḥ"},{"type":"verse","number":"79","sanskrit":"स्राविण्यः कण्डुरा गुर्व्यो रक्तसर्षपसन्निभाः रुजावत्यश्च पिडकाः पोथक्य इति कीर्त्तिताः","text":"srāviṇyaḥ kaṇḍurā gurvyo raktasarṣapasannibhāḥ rujāvatyaśca piḍakāḥ pothakya iti kīrttitāḥ"},{"type":"verse","number":"80","sanskrit":"पिडकाभिः सुसूक्ष्माभिर्घनाभिरभिसंवृता पिडका या खरा स्थूला वर्त्मस्था वर्त्मशर्करा","text":"piḍakābhiḥ susūkṣmābhirghanābhirabhisaṃvṛtā piḍakā yā kharā sthūlā vartmasthā vartmaśarkarā"},{"type":"verse","number":"81","sanskrit":"एर्वारुबीजप्रतिमाः पिडका मन्दवेदनाः श्लक्ष्णाः खराश्च वर्त्मस्थास्तदर्शोवर्त्म कीत्तर्यते","text":"ervārubījapratimāḥ piḍakā mandavedanāḥ ślakṣṇāḥ kharāśca vartmasthāstadarśovartma kīttaryate"},{"type":"verse","number":"82","sanskrit":"दीर्घाङ्कुरः खरः स्तब्धो दारुणोऽभ्यन्तरोद्भवः व्याधिरेषोऽभिविख्यातः शुष्कार्शो नाम नामतः","text":"dīrghāṅkuraḥ kharaḥ stabdho dāruṇo'bhyantarodbhavaḥ vyādhireṣo'bhivikhyātaḥ śuṣkārśo nāma nāmataḥ"},{"type":"verse","number":"83","sanskrit":"दाहतोदवती ताम्रा पिडका वर्त्मसम्भवा मृद्वी मन्दरुजा सूक्ष्मा ज्ञेया साऽञ्जनदूषिका","text":"dāhatodavatī tāmrā piḍakā vartmasambhavā mṛdvī mandarujā sūkṣmā jñeyā sā'ñjanadūṣikā"},{"type":"verse","number":"84","sanskrit":"वर्त्मोपचीयते यस्य पिडकाभिः समन्ततः सवर्णाभिः स्थिराभिश्च विद्याद्वहलवर्त्म तत्","text":"vartmopacīyate yasya piḍakābhiḥ samantataḥ savarṇābhiḥ sthirābhiśca vidyādvahalavartma tat"},{"type":"verse","number":"85","sanskrit":"कण्डूरेणाल्पतोदेन वर्त्मशोफेन मानवः न समं छादयेदक्षि यत्रासौ वर्त्मबन्धकः","text":"kaṇḍūreṇālpatodena vartmaśophena mānavaḥ na samaṃ chādayedakṣi yatrāsau vartmabandhakaḥ"},{"type":"verse","number":"86","sanskrit":"मृद्वल्पवेदनं ताम्रं यद्वर्त्म सममेव च अकस्माच्च भवेद्र क्तं क्लिष्टवर्त्मेति तद्विदुः","text":"mṛdvalpavedanaṃ tāmraṃ yadvartma samameva ca akasmācca bhavedra ktaṃ kliṣṭavartmeti tadviduḥ"},{"type":"verse","number":"87","sanskrit":"क्लिष्टं पुनः पित्तयुतं शोणितं विदहेद्यदा तदा क्लिन्नत्वमापन्नमुच्यते वर्त्मकर्दमः","text":"kliṣṭaṃ punaḥ pittayutaṃ śoṇitaṃ vidahedyadā tadā klinnatvamāpannamucyate vartmakardamaḥ"},{"type":"verse","number":"88","sanskrit":"यद्वर्त्म बाह्यतोऽन्तश्च श्यावं शूनं सवेदनम् सकण्डूकं परिक्लेदि श्याववर्त्मेति तन्मतम्","text":"yadvartma bāhyato'ntaśca śyāvaṃ śūnaṃ savedanam sakaṇḍūkaṃ parikledi śyāvavartmeti tanmatam"},{"type":"verse","number":"89","sanskrit":"अरुजं बाह्यतः शूनं वर्त्म यस्य नरस्य हि प्रक्लिन्नवर्त्म तद्विद्यात्क्लिन्नमत्यर्थमन्ततः","text":"arujaṃ bāhyataḥ śūnaṃ vartma yasya narasya hi praklinnavartma tadvidyātklinnamatyarthamantataḥ"},{"type":"verse","number":"90","sanskrit":"यस्य धौतान्यधौतानि सम्बध्यन्ते पुनः पुनः वर्त्मान्यपरिपक्वानि विद्यादक्लिन्नवर्त्म तत्","text":"yasya dhautānyadhautāni sambadhyante punaḥ punaḥ vartmānyaparipakvāni vidyādaklinnavartma tat"},{"type":"verse","number":"91","sanskrit":"विमुक्तसन्धि निश्चेष्टं वर्त्म यस्य न मील्यते एतद्वातहतं विद्यात्सरुजं यदि वारुजम्","text":"vimuktasandhi niśceṣṭaṃ vartma yasya na mīlyate etadvātahataṃ vidyātsarujaṃ yadi vārujam"},{"type":"verse","number":"92","sanskrit":"वर्त्मान्तरस्थं विषमं ग्रन्थिभूतमवेदनम् आचक्षीतार्बुदमिति सरक्तमवलम्बि च","text":"vartmāntarasthaṃ viṣamaṃ granthibhūtamavedanam ācakṣītārbudamiti saraktamavalambi ca"},{"type":"verse","number":"93","sanskrit":"निमेषिणीः शिरा वायुः प्रविष्टो वर्त्मसंश्रयाः सञ्चालयति वर्त्मानि निमेषः स न सिध्यति","text":"nimeṣiṇīḥ śirā vāyuḥ praviṣṭo vartmasaṃśrayāḥ sañcālayati vartmāni nimeṣaḥ sa na sidhyati"},{"type":"verse","number":"94","sanskrit":"वर्त्मस्थो यो विवर्द्धेत लोहितो मृदुरङ्कुरः तद्र क्तजं शोणितार्शश्छिन्नं वाऽपि विवर्द्धते","text":"vartmastho yo vivarddheta lohito mṛduraṅkuraḥ tadra ktajaṃ śoṇitārśaśchinnaṃ vā'pi vivarddhate"},{"type":"verse","number":"95","sanskrit":"अपाकी कठिनः स्थूलो ग्रन्थिवर्त्मभवोऽरुजः सकण्डूः पिच्छिलः कोलप्रमाणो लगणः स्मृतः","text":"apākī kaṭhinaḥ sthūlo granthivartmabhavo'rujaḥ sakaṇḍūḥ picchilaḥ kolapramāṇo lagaṇaḥ smṛtaḥ"},{"type":"verse","number":"96","sanskrit":"त्रयो दोषा बहिः शोथं कुर्युश्छिद्रा णि वर्त्मनोः प्रस्रवन्त्यन्तरुदकं बिसवद्बिसवर्त्म तत्","text":"trayo doṣā bahiḥ śothaṃ kuryuśchidrā ṇi vartmanoḥ prasravantyantarudakaṃ bisavadbisavartma tat"},{"type":"verse","number":"97","sanskrit":"वाताद्या वर्त्मसंकोचं जनयन्ति मला यदा तदा द्र ष्टुं न शक्नोति कुञ्चनं नाम तद्विदुः","text":"vātādyā vartmasaṃkocaṃ janayanti malā yadā tadā dra ṣṭuṃ na śaknoti kuñcanaṃ nāma tadviduḥ"},{"type":"verse","number":"98","sanskrit":"इति वर्त्मजा रोगाः अथ पक्ष्मरोगाः पक्ष्मकोपः पक्ष्मशातो रोगौ द्वौ पक्ष्मसंश्रयौ","text":"iti vartmajā rogāḥ atha pakṣmarogāḥ pakṣmakopaḥ pakṣmaśāto rogau dvau pakṣmasaṃśrayau"},{"type":"verse","number":"99","sanskrit":"प्रचालितानि वातेन पक्ष्माण्यक्षि विशन्ति हि घृष्यन्त्यक्षि मुहुस्तानि संरम्भं जनयन्ति च असिते सितभागे च मूलकोशात्पतन्त्यपि पक्ष्मकोपः स विज्ञेयो व्याधिः परमदारुणः","text":"pracālitāni vātena pakṣmāṇyakṣi viśanti hi ghṛṣyantyakṣi muhustāni saṃrambhaṃ janayanti ca asite sitabhāge ca mūlakośātpatantyapi pakṣmakopaḥ sa vijñeyo vyādhiḥ paramadāruṇaḥ"},{"type":"verse","number":"100","sanskrit":"यत्पक्ष्मदेहलद्यं मुक्त्वा वर्त्मनोऽन्त प्रजायते घर्षेत्पक्ष्मासिते श्वेते पक्ष्मकोपः च उच्यते","text":"yatpakṣmadehaladyaṃ muktvā vartmano'nta prajāyate gharṣetpakṣmāsite śvete pakṣmakopaḥ ca ucyate"},{"type":"verse","number":"101","sanskrit":"वर्त्मपक्ष्माशयगतं पित्तं लोमानि शातयेत् कण्डूं दाहं च कुरुते पक्ष्मशातं तमादिशेत्","text":"vartmapakṣmāśayagataṃ pittaṃ lomāni śātayet kaṇḍūṃ dāhaṃ ca kurute pakṣmaśātaṃ tamādiśet"},{"type":"verse","number":"102","sanskrit":"इति पक्ष्म रोगौ अथ सन्धिजा रोगाः पक्ष्मवर्त्मगतः सन्धिर्वर्त्मशुक्ल गतोऽपरः शुक्लकृष्ण गतश्चान्यः कृष्ण दृष्टिगतोऽपि च मतः कनीनक गतः षष्ठश्चापाङ्ग संश्रितः","text":"iti pakṣma rogau atha sandhijā rogāḥ pakṣmavartmagataḥ sandhirvartmaśukla gato'paraḥ śuklakṛṣṇa gataścānyaḥ kṛṣṇa dṛṣṭigato'pi ca mataḥ kanīnaka gataḥ ṣaṣṭhaścāpāṅga saṃśritaḥ"},{"type":"verse","number":"103","sanskrit":"पूयालसः सोपनाहः स्रावाश्चत्वार एव च पर्वणिकाऽलजी जन्तुग्रन्थिः सन्धौ नवामयाः","text":"pūyālasaḥ sopanāhaḥ srāvāścatvāra eva ca parvaṇikā'lajī jantugranthiḥ sandhau navāmayāḥ"},{"type":"verse","number":"104","sanskrit":"पक्वः शोथः सन्धिजः संस्रवेद्यः सान्द्रं पूयं पूति पूयालसाख्यः","text":"pakvaḥ śothaḥ sandhijaḥ saṃsravedyaḥ sāndraṃ pūyaṃ pūti pūyālasākhyaḥ"},{"type":"verse","number":"105","sanskrit":"ग्रन्थिर्नाल्पो दृष्टिसन्धावपाकी कण्डूप्रायो नीरुजश्चोपनाहः","text":"granthirnālpo dṛṣṭisandhāvapākī kaṇḍūprāyo nīrujaścopanāhaḥ"},{"type":"verse","number":"106","sanskrit":"गत्वा सन्धीनश्रुमार्गेण दोषाः कुर्युः स्रावांल्लक्षणैः स्वैरुपेतान् तं हि स्रावं नेत्रनाडीति चैके लिङ्गं तस्या कीर्त्तयिष्ये चतुर्द्धा","text":"gatvā sandhīnaśrumārgeṇa doṣāḥ kuryuḥ srāvāṃllakṣaṇaiḥ svairupetān taṃ hi srāvaṃ netranāḍīti caike liṅgaṃ tasyā kīrttayiṣye caturddhā"},{"type":"verse","number":"107","sanskrit":"हारिद्रा भं पीतमुष्णं जलं वा पित्तस्रावः संस्रवेत्सन्धिमध्यात्","text":"hāridrā bhaṃ pītamuṣṇaṃ jalaṃ vā pittasrāvaḥ saṃsravetsandhimadhyāt"},{"type":"verse","number":"108","sanskrit":"श्वेतं सान्द्रं पिच्छिलं यः स्रवेत्तु श्लेष्मस्रावोऽसौ विकारः प्रदिष्टः","text":"śvetaṃ sāndraṃ picchilaṃ yaḥ sravettu śleṣmasrāvo'sau vikāraḥ pradiṣṭaḥ"},{"type":"verse","number":"109","sanskrit":"शोथः सन्धौ संस्रवेद्यस्तु पक्वः पूयं स्रावः सर्वजः सम्मतः स्यात्","text":"śothaḥ sandhau saṃsravedyastu pakvaḥ pūyaṃ srāvaḥ sarvajaḥ sammataḥ syāt"},{"type":"verse","number":"110","sanskrit":"रक्तास्रावः शोणिताद्यो विकारो गच्छेदुष्णं तत्र रक्तं प्रभूतम्","text":"raktāsrāvaḥ śoṇitādyo vikāro gaccheduṣṇaṃ tatra raktaṃ prabhūtam"},{"type":"verse","number":"111","sanskrit":"ताम्रा तन्वी दाहपाकोपपन्ना रक्ताज्ज्ञेया पर्वणी वृत्तशोका जाता सन्धौ कृष्णशुक्लेऽलजी स्यात्तस्मिन्नेव व्याहृता पूर्वलिङ्गैः","text":"tāmrā tanvī dāhapākopapannā raktājjñeyā parvaṇī vṛttaśokā jātā sandhau kṛṣṇaśukle'lajī syāttasminneva vyāhṛtā pūrvaliṅgaiḥ"},{"type":"verse","number":"112","sanskrit":"जन्तुग्रन्थिर्वर्त्मनः पक्ष्मणश्च कण्डूं कुर्युर्जन्तवः सन्धिजाताः नानारूपा वर्त्मशुक्लान्तसन्धौ गच्छन्त्यन्तर्लोचनं दूषयन्तः","text":"jantugranthirvartmanaḥ pakṣmaṇaśca kaṇḍūṃ kuryurjantavaḥ sandhijātāḥ nānārūpā vartmaśuklāntasandhau gacchantyantarlocanaṃ dūṣayantaḥ"},{"type":"verse","number":"113","sanskrit":"इति सन्धिजा रोगाः अथ समस्तनेत्रजा रोगाः स्यन्दाश्चतुष्का इह सम्प्रदिष्टाश्चत्वार एवेह तथाऽधिमन्थाः पाकः सशोथः स च शोथहीनो हताधिमन्थोऽनिलपर्ययश्च","text":"iti sandhijā rogāḥ atha samastanetrajā rogāḥ syandāścatuṣkā iha sampradiṣṭāścatvāra eveha tathā'dhimanthāḥ pākaḥ saśothaḥ sa ca śothahīno hatādhimantho'nilaparyayaśca"},{"type":"verse","number":"114","sanskrit":"शुष्काक्षिपाकस्त्विह कीर्त्तितश्च तथाऽन्यतो वात उदीरितश्च दृष्टिस्तथाऽम्लाध्युषिता शिराणामुत्पातहर्षौ च समस्तनेत्रे","text":"śuṣkākṣipākastviha kīrttitaśca tathā'nyato vāta udīritaśca dṛṣṭistathā'mlādhyuṣitā śirāṇāmutpātaharṣau ca samastanetre"},{"type":"verse","number":"115","sanskrit":"एवं समस्तनेत्रे स्युरामया दश सप्त च तेषामिह पृथग्वक्ष्ये यथावल्लक्षणान्यपि","text":"evaṃ samastanetre syurāmayā daśa sapta ca teṣāmiha pṛthagvakṣye yathāvallakṣaṇānyapi"},{"type":"verse","number":"116","sanskrit":"वातात्पित्तात्कफाद्र क्ता दभिष्यन्दश्चतुर्विधः प्रायेण जायते घोरःसर्वनेत्रामयाकरः","text":"vātātpittātkaphādra ktā dabhiṣyandaścaturvidhaḥ prāyeṇa jāyate ghoraḥsarvanetrāmayākaraḥ"},{"type":"verse","number":"117","sanskrit":"निस्तोदनस्तम्भनरोमहर्षसंघर्षपारुष्यशिरोऽभितापाः विशुष्कभावः शिशिराश्रुता च वाताभिपन्ने नयने भवन्ति","text":"nistodanastambhanaromaharṣasaṃgharṣapāruṣyaśiro'bhitāpāḥ viśuṣkabhāvaḥ śiśirāśrutā ca vātābhipanne nayane bhavanti"},{"type":"verse","number":"118","sanskrit":"दाहः प्रपाकः शिशिराभिनन्दा धूमायनं वाष्पसमुद्भवश्च उष्णाश्रुता पीतकनेत्रता च पित्ताभिपन्ने नयने भवन्ति","text":"dāhaḥ prapākaḥ śiśirābhinandā dhūmāyanaṃ vāṣpasamudbhavaśca uṣṇāśrutā pītakanetratā ca pittābhipanne nayane bhavanti"},{"type":"verse","number":"119","sanskrit":"उष्णाभिनन्दा गुरुताऽक्षिशोथः कण्डूपदेहावतिशीतता च स्रावो मुहुः पिच्छिल एव चापि कफाभिपन्ने नयने भवन्ति","text":"uṣṇābhinandā gurutā'kṣiśothaḥ kaṇḍūpadehāvatiśītatā ca srāvo muhuḥ picchila eva cāpi kaphābhipanne nayane bhavanti"},{"type":"verse","number":"120","sanskrit":"ताम्राश्रुता लोहितनेत्रता च राज्यः समन्तादतिलोहिताश्च पित्तस्य लिङ्गानि च यानि तानि रक्ताभिपन्ने नयने भवन्ति","text":"tāmrāśrutā lohitanetratā ca rājyaḥ samantādatilohitāśca pittasya liṅgāni ca yāni tāni raktābhipanne nayane bhavanti"},{"type":"verse","number":"121","sanskrit":"वृद्धैरेतैरभिष्यन्दैर्नराणाम क्रियावताम् तावन्तस्त्वधिमन्थाः स्युर्नयने तीव्रवेदनाः","text":"vṛddhairetairabhiṣyandairnarāṇāma kriyāvatām tāvantastvadhimanthāḥ syurnayane tīvravedanāḥ"},{"type":"verse","number":"122","sanskrit":"उत्पाट्यत इवात्यर्थं तथा निर्मथ्यतेऽपि च शिरसोऽद्ध तु तं विद्यादधिमन्थं स्वलक्षणैः","text":"utpāṭyata ivātyarthaṃ tathā nirmathyate'pi ca śiraso'ddha tu taṃ vidyādadhimanthaṃ svalakṣaṇaiḥ"},{"type":"verse","number":"123","sanskrit":"हन्याद् दृष्टिं श्लैष्मिकः सप्तरात्राद्योऽधीमन्थो रक्तजः पञ्चरात्रात् षड्रात्राद्वा वातिको वै निहन्यान्मिथ्याऽचारात्पैत्तिकः सद्य एव","text":"hanyād dṛṣṭiṃ ślaiṣmikaḥ saptarātrādyo'dhīmantho raktajaḥ pañcarātrāt ṣaḍrātrādvā vātiko vai nihanyānmithyā'cārātpaittikaḥ sadya eva"},{"type":"verse","number":"124","sanskrit":"कण्डूपदेहाश्रुयुतः पक्वोदुम्बरसन्निभः संरम्भी पच्यते यस्तु नेत्रपाकः सशोथकः शोथहीनानि लिङ्गानि नेत्रपाके त्वशोथजे","text":"kaṇḍūpadehāśruyutaḥ pakvodumbarasannibhaḥ saṃrambhī pacyate yastu netrapākaḥ saśothakaḥ śothahīnāni liṅgāni netrapāke tvaśothaje"},{"type":"verse","number":"125","sanskrit":"उपेक्षणादक्षि यदाऽधिमन्थो वाताधिकः शोषयति प्रसह्य रुजाभिरुग्राभिरसाध्य एष हताधिमन्थः खलु नाम रोगः","text":"upekṣaṇādakṣi yadā'dhimantho vātādhikaḥ śoṣayati prasahya rujābhirugrābhirasādhya eṣa hatādhimanthaḥ khalu nāma rogaḥ"},{"type":"verse","number":"126","sanskrit":"वारंवारञ्च पर्येति भ्रुवौ नेत्रे च मारुतः रुजाश्च विविधास्तीव्राः स ज्ञेयो वातपर्ययः","text":"vāraṃvārañca paryeti bhruvau netre ca mārutaḥ rujāśca vividhāstīvrāḥ sa jñeyo vātaparyayaḥ"},{"type":"verse","number":"127","sanskrit":"यत्कूणितं दारुणरूक्षवर्त्म सन्दह्यते चाविलदर्शनं यत् सुदारुणं यत्प्रतिबोधने च शुष्काक्षिपाकोपहतं तदक्षि","text":"yatkūṇitaṃ dāruṇarūkṣavartma sandahyate cāviladarśanaṃ yat sudāruṇaṃ yatpratibodhane ca śuṣkākṣipākopahataṃ tadakṣi"},{"type":"verse","number":"128","sanskrit":"यस्यावटूकर्णशिरोहनुस्थो मन्यागतो वाऽप्यनिलोऽन्यतो वा कुर्याद्रुजोऽति भ्रुवि लोचने च तमन्यतोवातमुदाहरन्ति","text":"yasyāvaṭūkarṇaśirohanustho manyāgato vā'pyanilo'nyato vā kuryādrujo'ti bhruvi locane ca tamanyatovātamudāharanti"},{"type":"verse","number":"129","sanskrit":"श्यावं लोहितपर्यन्तं सर्वमक्षि प्रपच्यते सदाहशोथं सास्रावमम्लाध्युषितमम्लतः","text":"śyāvaṃ lohitaparyantaṃ sarvamakṣi prapacyate sadāhaśothaṃ sāsrāvamamlādhyuṣitamamlataḥ"},{"type":"verse","number":"130","sanskrit":"अवेदना वाऽपि सवेदना वा यस्याक्षिराज्यो हि भवन्ति ताम्राः मुहुर्विरज्यन्ति च याः समन्ताद् व्याधिः शिरोत्पात इति प्रदिष्टः","text":"avedanā vā'pi savedanā vā yasyākṣirājyo hi bhavanti tāmrāḥ muhurvirajyanti ca yāḥ samantād vyādhiḥ śirotpāta iti pradiṣṭaḥ"},{"type":"verse","number":"131","sanskrit":"मोहाच्छिरोत्पात उपेक्षितस्तु जायेत रोगः स शिराप्रहर्षः ताम्राक्षिता स्रावयति प्रगाढं तथा न शक्नोत्यभिवीक्षितुञ्च","text":"mohācchirotpāta upekṣitastu jāyeta rogaḥ sa śirāpraharṣaḥ tāmrākṣitā srāvayati pragāḍhaṃ tathā na śaknotyabhivīkṣituñca"},{"type":"verse","number":"132","sanskrit":"उदीर्णवेदनं नेत्रं रागशोथसमन्वितम् घर्षनिस्तोदशूलाश्रुयुक्तमामान्वितं विदुः","text":"udīrṇavedanaṃ netraṃ rāgaśothasamanvitam gharṣanistodaśūlāśruyuktamāmānvitaṃ viduḥ"},{"type":"verse","number":"133","sanskrit":"मन्दवेदनताकण्डू संरम्भाश्रुप्रशान्तताः प्रसन्नवर्णता चाक्ष्णोर्निरामेक्षणलक्षणम्","text":"mandavedanatākaṇḍū saṃrambhāśrupraśāntatāḥ prasannavarṇatā cākṣṇornirāmekṣaṇalakṣaṇam"},{"type":"verse","number":"134","sanskrit":"इति समस्तनेत्रजा रोगाः द्वे पादमध्ये पृथुसन्निवेशे शिरोगते ते बहुधा हि नेत्रे ताः प्रोक्षणोत्सादनलेपनादीन्पादप्रयुक्तान्नयनं नयन्ति","text":"iti samastanetrajā rogāḥ dve pādamadhye pṛthusanniveśe śirogate te bahudhā hi netre tāḥ prokṣaṇotsādanalepanādīnpādaprayuktānnayanaṃ nayanti"},{"type":"verse","number":"135","sanskrit":"मलोष्मसंघट्टनपीडनाद्यैस्ता दूषयन्ते नयनानि दुष्टाः भजेत्सदा दृष्टिहितानि तस्मादुपानदभ्यञ्जनधावनानि","text":"maloṣmasaṃghaṭṭanapīḍanādyaistā dūṣayante nayanāni duṣṭāḥ bhajetsadā dṛṣṭihitāni tasmādupānadabhyañjanadhāvanāni"},{"type":"verse","number":"136","sanskrit":"चक्षुष्याः शालयो मुद्गा यवा मांसन्तु जाङ्गलम् पक्षिमांसं विशेषेण वास्तूकं तण्डूलीयकम् पटोलकर्कोटककारवेल्लफलानि सर्पिः परिपाचितानि तथैव वार्त्ताकफलं नवीनमक्ष्णोर्हितः स्वादुरथापि तिक्तः कट्वम्लगुरु तीक्ष्णोष्णमाषनिष्पावमैथुनम् मद्यवल्लूरपिण्याकमत्स्य शाकविरूढजम् विदाहीन्यन्नपानानि नहितान्यक्षिरोगिणे सेक आश्च्योतनं पिण्डी विडालस्तर्पणं तथा पुटपाकोऽञ्जनं चैभिः कल्कैर्नेत्रमुपाचरेत्","text":"cakṣuṣyāḥ śālayo mudgā yavā māṃsantu jāṅgalam pakṣimāṃsaṃ viśeṣeṇa vāstūkaṃ taṇḍūlīyakam paṭolakarkoṭakakāravellaphalāni sarpiḥ paripācitāni tathaiva vārttākaphalaṃ navīnamakṣṇorhitaḥ svādurathāpi tiktaḥ kaṭvamlaguru tīkṣṇoṣṇamāṣaniṣpāvamaithunam madyavallūrapiṇyākamatsya śākavirūḍhajam vidāhīnyannapānāni nahitānyakṣirogiṇe seka āścyotanaṃ piṇḍī viḍālastarpaṇaṃ tathā puṭapāko'ñjanaṃ caibhiḥ kalkairnetramupācaret"},{"type":"verse","number":"137","sanskrit":"सेकस्तु सूक्ष्मधाराभिः सर्वस्मिन्नयने हितः मीलिताक्षस्य मर्त्यस्य प्रदेयश्चतुरङ्गुलः","text":"sekastu sūkṣmadhārābhiḥ sarvasminnayane hitaḥ mīlitākṣasya martyasya pradeyaścaturaṅgulaḥ"},{"type":"verse","number":"138","sanskrit":"स चापि स्नेहनो वाते पित्ते रक्ते च रोपणः लेखनस्तु कफे कार्यस्तस्य मात्राऽभिधीयते","text":"sa cāpi snehano vāte pitte rakte ca ropaṇaḥ lekhanastu kaphe kāryastasya mātrā'bhidhīyate"},{"type":"verse","number":"139","sanskrit":"षड्भिर्वाचां शतैः स्नेहे चतुर्भिस्तैस्तु रोपणे तैस्त्रिभिर्लोचने कार्यः सेको नेत्रप्रसादने","text":"ṣaḍbhirvācāṃ śataiḥ snehe caturbhistaistu ropaṇe taistribhirlocane kāryaḥ seko netraprasādane"},{"type":"verse","number":"140","sanskrit":"निमेषोन्मेषणं पुंसामङ्गुल्या च्छोटिकाऽथवा गुर्वक्षरोच्चारणं वा वाङ्मात्रेयं स्मृता बुधैः","text":"nimeṣonmeṣaṇaṃ puṃsāmaṅgulyā cchoṭikā'thavā gurvakṣaroccāraṇaṃ vā vāṅmātreyaṃ smṛtā budhaiḥ"},{"type":"verse","number":"141","sanskrit":"सेकस्तु दिवसे कार्यो रात्रावत्यन्तिके गदे एरण्डदलमूलत्वक्छृतमाजं पयो हितम् सुखोष्णं नेत्रयोः सिक्तं वाताभिष्यन्दनाशनम्","text":"sekastu divase kāryo rātrāvatyantike gade eraṇḍadalamūlatvakchṛtamājaṃ payo hitam sukhoṣṇaṃ netrayoḥ siktaṃ vātābhiṣyandanāśanam"},{"type":"verse","number":"142","sanskrit":"पथ्याऽक्षामलखाखसवल्कलकल्केन सूक्ष्मवस्त्रेण कृत्वा पोटलिकां तामहिफेनोत्थद्र वेण संयुक्ताम्","text":"pathyā'kṣāmalakhākhasavalkalakalkena sūkṣmavastreṇa kṛtvā poṭalikāṃ tāmahiphenotthadra veṇa saṃyuktām"},{"type":"verse","number":"143","sanskrit":"निदधीत लोचने स्यात्सर्वाभिष्यन्दसंक्षयः शीघ्रम् योगोऽयमृषिभिरुक्तो जगदुपकाराय कारुणिकैः","text":"nidadhīta locane syātsarvābhiṣyandasaṃkṣayaḥ śīghram yogo'yamṛṣibhirukto jagadupakārāya kāruṇikaiḥ"},{"type":"verse","number":"144","sanskrit":"भुक्त्वा पाणितलं घृष्ट्वा चक्षुषोर्यदि दीयते अचिरेणैव तद्वारि तिमिराणि व्यपोहति","text":"bhuktvā pāṇitalaṃ ghṛṣṭvā cakṣuṣoryadi dīyate acireṇaiva tadvāri timirāṇi vyapohati"},{"type":"verse","number":"145","sanskrit":"स्नानं कृष्णतिलैश्चापि चक्षुष्यमनिलापहम् आमलैः सततं स्नानं परं दृष्टिबलावहम्","text":"snānaṃ kṛṣṇatilaiścāpi cakṣuṣyamanilāpaham āmalaiḥ satataṃ snānaṃ paraṃ dṛṣṭibalāvaham"},{"type":"verse","number":"146","sanskrit":"त्रिफलायाः कषायस्तु धावनान्नेत्ररोगजित् कवलान्मुखरोगघ्नः पानतः कामलाऽपहः","text":"triphalāyāḥ kaṣāyastu dhāvanānnetrarogajit kavalānmukharogaghnaḥ pānataḥ kāmalā'pahaḥ"},{"type":"verse","number":"147","sanskrit":"क्वाथक्षीरद्र्रवस्नेहबिन्दूनां यत्तु पातनम् द्व्यङ्गुलोन्मीलिते नेत्रे प्रोक्तमाश्च्योतनं हि तत्","text":"kvāthakṣīradrravasnehabindūnāṃ yattu pātanam dvyaṅgulonmīlite netre proktamāścyotanaṃ hi tat"},{"type":"verse","number":"148","sanskrit":"विन्दवोऽष्टौ लेखनेषु रोपणे दश विन्दवः स्नेहने द्वादश प्रोक्तास्ते शीते कोष्णरूपिणः","text":"vindavo'ṣṭau lekhaneṣu ropaṇe daśa vindavaḥ snehane dvādaśa proktāste śīte koṣṇarūpiṇaḥ"},{"type":"verse","number":"149","sanskrit":"उष्णे तु शीतरूपाः स्यु सर्वत्रैवैष निश्चयः वाते तिक्तं तथा स्निग्धं पित्ते मधुरशीतलम्","text":"uṣṇe tu śītarūpāḥ syu sarvatraivaiṣa niścayaḥ vāte tiktaṃ tathā snigdhaṃ pitte madhuraśītalam"},{"type":"verse","number":"150","sanskrit":"कफे तिक्तोष्णरूक्षं स्यात्क्रमादाश्च्योतनं हितम् आश्च्योतनानां सर्वेषां मात्रा स्याद्वाक्छतोन्मिता","text":"kaphe tiktoṣṇarūkṣaṃ syātkramādāścyotanaṃ hitam āścyotanānāṃ sarveṣāṃ mātrā syādvākchatonmitā"},{"type":"verse","number":"151","sanskrit":"बिल्वादिपञ्चमूलेन बृहत्येरण्डशिग्रुभिः क्वाथ आश्च्योतने कोष्णो वाताभिष्यन्दनाशनः","text":"bilvādipañcamūlena bṛhatyeraṇḍaśigrubhiḥ kvātha āścyotane koṣṇo vātābhiṣyandanāśanaḥ"},{"type":"verse","number":"152","sanskrit":"त्रिफलाऽश्च्योतनं नेत्रे सर्वाभिष्यन्दनाशनम्","text":"triphalā'ścyotanaṃ netre sarvābhiṣyandanāśanam"},{"type":"verse","number":"153","sanskrit":"उक्तभेषजकल्कस्य पिण्डी च कोलमात्रया वस्त्रखण्डेन सम्बद्धाऽभिष्यन्दव्रणनाशिनी","text":"uktabheṣajakalkasya piṇḍī ca kolamātrayā vastrakhaṇḍena sambaddhā'bhiṣyandavraṇanāśinī"},{"type":"verse","number":"154","sanskrit":"स्निग्धोष्णा पिण्डिका वाते पित्ते सा शीतला मता रूक्षोष्णा श्लेष्मणि प्रोक्ता विधिरुक्तो बुधैरयम्","text":"snigdhoṣṇā piṇḍikā vāte pitte sā śītalā matā rūkṣoṣṇā śleṣmaṇi proktā vidhirukto budhairayam"},{"type":"verse","number":"155","sanskrit":"एरण्डपत्रमूलत्वङ्निर्मिता वातनाशिनी धात्रीविरचिता पित्ते शिग्रुपत्रकृता कफे","text":"eraṇḍapatramūlatvaṅnirmitā vātanāśinī dhātrīviracitā pitte śigrupatrakṛtā kaphe"},{"type":"verse","number":"156","sanskrit":"निम्बपत्रकृतापिण्डी पित्तश्लेष्महरी भवेत् शुण्ठीनिम्बदलैः पिण्डी सुखोष्णा स्वल्पसैन्धवा","text":"nimbapatrakṛtāpiṇḍī pittaśleṣmaharī bhavet śuṇṭhīnimbadalaiḥ piṇḍī sukhoṣṇā svalpasaindhavā"},{"type":"verse","number":"157","sanskrit":"धार्या नेत्रेऽनिलकफे शोथकण्डूव्यथाहरी त्रिफलापिण्डिका नेत्रे वातपित्तकफापहा","text":"dhāryā netre'nilakaphe śothakaṇḍūvyathāharī triphalāpiṇḍikā netre vātapittakaphāpahā"},{"type":"verse","number":"158","sanskrit":"पथ्याऽक्षामलखाखसवल्कलकल्कोऽहिफेनजलयुक्तः तेन विरचिता पिण्डी शमयति सकलानभिष्यन्दान्","text":"pathyā'kṣāmalakhākhasavalkalakalko'hiphenajalayuktaḥ tena viracitā piṇḍī śamayati sakalānabhiṣyandān"},{"type":"verse","number":"159","sanskrit":"विडालको बहिर्लेपो नेत्रे पक्ष्मविवर्जिते तस्य मात्रा परिज्ञेया मुखालेपविधानवत्","text":"viḍālako bahirlepo netre pakṣmavivarjite tasya mātrā parijñeyā mukhālepavidhānavat"},{"type":"verse","number":"160","sanskrit":"अङ्गुलस्य चतुर्थांशो मुखलेपः कनिष्ठकः मध्यमस्तु त्रिभागः स्यादुत्तमोऽद्धाङ्गुलो भवेत्","text":"aṅgulasya caturthāṃśo mukhalepaḥ kaniṣṭhakaḥ madhyamastu tribhāgaḥ syāduttamo'ddhāṅgulo bhavet"},{"type":"verse","number":"161","sanskrit":"स्थितिकालेऽपि तस्योक्तो यावत्कल्को न शुष्यति शुष्कस्तु गुणहीनः स्यात्तथा दूषयति त्वचम्","text":"sthitikāle'pi tasyokto yāvatkalko na śuṣyati śuṣkastu guṇahīnaḥ syāttathā dūṣayati tvacam"},{"type":"verse","number":"162","sanskrit":"यष्टिगैरिकसिन्धूत्थदार्वीतार्क्ष्यैः समांशकैः जलपिष्टैर्बहिर्लेपः सर्वनेत्रामयापहः","text":"yaṣṭigairikasindhūtthadārvītārkṣyaiḥ samāṃśakaiḥ jalapiṣṭairbahirlepaḥ sarvanetrāmayāpahaḥ"},{"type":"verse","number":"163","sanskrit":"रसाञ्जनेन वा लेपः पथ्याबिल्वदलैरपि वचाहरिद्रा विश्वैर्वा तथा नागरगैरिकैः","text":"rasāñjanena vā lepaḥ pathyābilvadalairapi vacāharidrā viśvairvā tathā nāgaragairikaiḥ"},{"type":"verse","number":"164","sanskrit":"वातातपरजोहीने वेश्मन्युत्तानशायिनः आधारौ माषचूर्णेन क्लिन्नेन परिमण्डलौ","text":"vātātaparajohīne veśmanyuttānaśāyinaḥ ādhārau māṣacūrṇena klinnena parimaṇḍalau"},{"type":"verse","number":"165","sanskrit":"समौ दृढावसन्धानौ कर्त्तव्यौ नेत्रकोशयोः पूरयेद् घृतमण्डेन विलीनेन सुखोदकैः","text":"samau dṛḍhāvasandhānau karttavyau netrakośayoḥ pūrayed ghṛtamaṇḍena vilīnena sukhodakaiḥ"},{"type":"verse","number":"166","sanskrit":"सर्पिषा शतधौतेन क्षीरजेन घृतेन वा निमग्नान्यक्षिपक्ष्माणि यावत्स्युस्तावदेव हि","text":"sarpiṣā śatadhautena kṣīrajena ghṛtena vā nimagnānyakṣipakṣmāṇi yāvatsyustāvadeva hi"},{"type":"verse","number":"167","sanskrit":"पूरयेन्मीलिते नेत्रे तत उन्मीलयेच्छनैः भिषग्भिरेष कथितः पुराणैस्तर्पणो विधिः","text":"pūrayenmīlite netre tata unmīlayecchanaiḥ bhiṣagbhireṣa kathitaḥ purāṇaistarpaṇo vidhiḥ"},{"type":"verse","number":"168","sanskrit":"यद्रू क्षं परिशुष्कञ्च नेत्रं कुटिलमाविलम् शीर्णपक्ष्मशिरोत्पातकृच्छ्रोन्मीलनसंयुतम्","text":"yadrū kṣaṃ pariśuṣkañca netraṃ kuṭilamāvilam śīrṇapakṣmaśirotpātakṛcchronmīlanasaṃyutam"},{"type":"verse","number":"169","sanskrit":"तिमिरार्जुन शुक्राद्यैरभिष्यन्दाधिमन्थकैः शुष्काक्षिपाकशोथाभ्यां युक्तं पवनपर्ययैः तन्नेत्रं तर्पयेत्सम्यङ् नेत्ररोगविशारदः","text":"timirārjuna śukrādyairabhiṣyandādhimanthakaiḥ śuṣkākṣipākaśothābhyāṃ yuktaṃ pavanaparyayaiḥ tannetraṃ tarpayetsamyaṅ netrarogaviśāradaḥ"},{"type":"verse","number":"170","sanskrit":"तर्पणं धारयेद्वर्त्मरोगे वाचां शतं बुधः","text":"tarpaṇaṃ dhārayedvartmaroge vācāṃ śataṃ budhaḥ"},{"type":"verse","number":"171","sanskrit":"स्वस्थे कफे सन्धिरोगे वाचां पञ्चशतानि च षट्शतानि कफे कृष्णरोगे सप्तशतानि हि","text":"svasthe kaphe sandhiroge vācāṃ pañcaśatāni ca ṣaṭśatāni kaphe kṛṣṇaroge saptaśatāni hi"},{"type":"verse","number":"172","sanskrit":"दृष्टिगे च शतान्यष्टावधिमन्थे सहस्रकम् सहस्रं वातरोगेषु धार्यमेवं हि तर्पणम्","text":"dṛṣṭige ca śatānyaṣṭāvadhimanthe sahasrakam sahasraṃ vātarogeṣu dhāryamevaṃ hi tarpaṇam"},{"type":"verse","number":"173","sanskrit":"ततश्चापाङ्गतः स्नेहं स्रावयित्वाऽक्षिशोधयेत् स्विन्नेन यवपिष्टेन स्नेहवीर्येरितं ततः","text":"tataścāpāṅgataḥ snehaṃ srāvayitvā'kṣiśodhayet svinnena yavapiṣṭena snehavīryeritaṃ tataḥ"},{"type":"verse","number":"174","sanskrit":"यथास्वं धूमपानेन कफमस्य विरेचयेत् एकाहं वा त्र्यहं वाऽपि पञ्चाहं वाऽपि तर्पयेत्","text":"yathāsvaṃ dhūmapānena kaphamasya virecayet ekāhaṃ vā tryahaṃ vā'pi pañcāhaṃ vā'pi tarpayet"},{"type":"verse","number":"175","sanskrit":"तर्पणे तृप्तिलिङ्गानि नेत्रस्यैतानि लक्षयेत्","text":"tarpaṇe tṛptiliṅgāni netrasyaitāni lakṣayet"},{"type":"verse","number":"176","sanskrit":"सुखसुप्तावबोधत्वं वैशद्यं दृष्टिपाटवम् निर्वृतिर्व्याधिशान्तिश्च क्रियालाघवमेव च","text":"sukhasuptāvabodhatvaṃ vaiśadyaṃ dṛṣṭipāṭavam nirvṛtirvyādhiśāntiśca kriyālāghavameva ca"},{"type":"verse","number":"177","sanskrit":"गुर्वाविलमतिस्निग्धमश्रु कण्डूपदेहवत् घर्षतोदयुतं नेत्रमतितर्पितमादिशेत्","text":"gurvāvilamatisnigdhamaśru kaṇḍūpadehavat gharṣatodayutaṃ netramatitarpitamādiśet"},{"type":"verse","number":"178","sanskrit":"आस्रावशोफरोगाढ्यमसहं रूपदर्शने आविलं परुषं रूक्षं नेत्रं स्याद्धीनतर्पितम्","text":"āsrāvaśopharogāḍhyamasahaṃ rūpadarśane āvilaṃ paruṣaṃ rūkṣaṃ netraṃ syāddhīnatarpitam"},{"type":"verse","number":"179","sanskrit":"अनयोर्दोषबाहुल्यात् प्रयत्नेन चिकित्सिते रुक्षस्निग्धोपचाराभ्यामनयोःस्यात्प्रतिक्रिया","text":"anayordoṣabāhulyāt prayatnena cikitsite rukṣasnigdhopacārābhyāmanayoḥsyātpratikriyā"},{"type":"verse","number":"180","sanskrit":"दुर्दिनात्युष्णशीतेषु चिन्तायां सम्भ्रमेषु च अशान्तोपद्र वे वाऽक्ष्णि तर्पणं न प्रशस्यते","text":"durdinātyuṣṇaśīteṣu cintāyāṃ sambhrameṣu ca aśāntopadra ve vā'kṣṇi tarpaṇaṃ na praśasyate"},{"type":"verse","number":"181","sanskrit":"द्वे बिल्वे स्निग्धमांसस्य परं द्र व्यपलं मतम् द्र व्यस्य कुडवोन्मानं सर्वमेकत्र पेषयेत्","text":"dve bilve snigdhamāṃsasya paraṃ dra vyapalaṃ matam dra vyasya kuḍavonmānaṃ sarvamekatra peṣayet"},{"type":"verse","number":"182","sanskrit":"तदेकत्र समालोड्य पत्रैः सुपरिवेष्टितम् पुटपाकविधानेन तत्पक्त्वा तद्र सं बुधः","text":"tadekatra samāloḍya patraiḥ supariveṣṭitam puṭapākavidhānena tatpaktvā tadra saṃ budhaḥ"},{"type":"verse","number":"183","sanskrit":"तर्पणोक्तेन विधिना यथावद्विनियोजयेत् दृष्टिमध्ये निषेक्तव्यो नित्यमुत्तानशायिनः","text":"tarpaṇoktena vidhinā yathāvadviniyojayet dṛṣṭimadhye niṣektavyo nityamuttānaśāyinaḥ"},{"type":"verse","number":"184","sanskrit":"तेजांस्यनिलमाकाशमातपं भास्करस्य च नेक्षेत तर्पिते नेत्रे यश्च वा पुटपाकवान्","text":"tejāṃsyanilamākāśamātapaṃ bhāskarasya ca nekṣeta tarpite netre yaśca vā puṭapākavān"},{"type":"verse","number":"185","sanskrit":"अथ सम्पक्वदोषस्य प्राप्तमञ्जनमाचरेत् अञ्जनं क्रियते येन तद् द्र व्यं चाञ्जनं मतम्","text":"atha sampakvadoṣasya prāptamañjanamācaret añjanaṃ kriyate yena tad dra vyaṃ cāñjanaṃ matam"},{"type":"verse","number":"186","sanskrit":"वटिकारसचूर्णानि त्रिविधान्यञ्जनानि हि कुर्याच्छलाकयाऽङगुल्या हीनानि स्युर्यथोत्तरम्","text":"vaṭikārasacūrṇāni trividhānyañjanāni hi kuryācchalākayā'ṅagulyā hīnāni syuryathottaram"},{"type":"verse","number":"187","sanskrit":"स्नेहनं रोपणं चापि लेखनं तत्त्रिधा पृथक् मधुरं स्नेहसम्पन्नमञ्जनं स्नेहनं मतम्","text":"snehanaṃ ropaṇaṃ cāpi lekhanaṃ tattridhā pṛthak madhuraṃ snehasampannamañjanaṃ snehanaṃ matam"},{"type":"verse","number":"188","sanskrit":"कषायतिक्तरसयुक्सस्नेहं रोपणं स्मृतम् अञ्जनं क्षारतिक्ताम्लरसैर्लेखनमुच्यते","text":"kaṣāyatiktarasayuksasnehaṃ ropaṇaṃ smṛtam añjanaṃ kṣāratiktāmlarasairlekhanamucyate"},{"type":"verse","number":"189","sanskrit":"हरेणुमात्रां कुर्वीत वटीं तीक्ष्णाञ्जने भिषक् प्रमाणं मध्यमे सार्द्धद्विगुणं तु मृदौ भवेत्","text":"hareṇumātrāṃ kurvīta vaṭīṃ tīkṣṇāñjane bhiṣak pramāṇaṃ madhyame sārddhadviguṇaṃ tu mṛdau bhavet"},{"type":"verse","number":"190","sanskrit":"रसक्रिया तूत्तमा स्यात् त्रिविडङ्गमिता मता मध्यमा द्विविडङ्गा सा हीना त्वेकविडङ्गिका","text":"rasakriyā tūttamā syāt triviḍaṅgamitā matā madhyamā dviviḍaṅgā sā hīnā tvekaviḍaṅgikā"},{"type":"verse","number":"191","sanskrit":"शलाकाः स्नेहने चूर्णे चतस्रः प्राहुरञ्जने रोपणे तासु तिस्रः स्युस्ते उभे लेखने स्मृते","text":"śalākāḥ snehane cūrṇe catasraḥ prāhurañjane ropaṇe tāsu tisraḥ syuste ubhe lekhane smṛte"},{"type":"verse","number":"192","sanskrit":"मुखयोः कुञ्चिता श्लक्ष्णां शलाकाऽष्टाङ्गुलोन्मिता अश्मजा धातुजा वा स्यात्कलायपरिमण्डला","text":"mukhayoḥ kuñcitā ślakṣṇāṃ śalākā'ṣṭāṅgulonmitā aśmajā dhātujā vā syātkalāyaparimaṇḍalā"},{"type":"verse","number":"193","sanskrit":"सुवर्णरजतोद्भूता शलाका स्नेहने स्मृता तीव्रलोहाश्मसञ्जाता शलाका लेखने मता अङ्गुली तु मृदुत्वेन रोपणे कथिता बुधैः","text":"suvarṇarajatodbhūtā śalākā snehane smṛtā tīvralohāśmasañjātā śalākā lekhane matā aṅgulī tu mṛdutvena ropaṇe kathitā budhaiḥ"},{"type":"verse","number":"194","sanskrit":"त्रिफालाभृङ्गशुण्ठीनां रसैः शुद्धश्च सर्पिषा","text":"triphālābhṛṅgaśuṇṭhīnāṃ rasaiḥ śuddhaśca sarpiṣā"},{"type":"verse","number":"195","sanskrit":"गोमूत्रमध्वजाक्षीरैः सिक्तो नागः प्रतापितः तच्छलाका हरत्येव सकलान्नेत्रजान्गदान्","text":"gomūtramadhvajākṣīraiḥ sikto nāgaḥ pratāpitaḥ tacchalākā haratyeva sakalānnetrajāngadān"},{"type":"verse","number":"196","sanskrit":"कृष्णभागादधः कुर्याद्यावन्नयनमञ्जनम् हेमन्ते शिशिरे चापि मध्याह्नेऽञ्जनमिष्यते","text":"kṛṣṇabhāgādadhaḥ kuryādyāvannayanamañjanam hemante śiśire cāpi madhyāhne'ñjanamiṣyate"},{"type":"verse","number":"197","sanskrit":"पूर्वाह्णे वाऽपराह्णे वा ग्रीष्मे शरदि चेष्यते वर्षास्वदभ्रे नात्युष्णे वसन्ते तु सदैव हि","text":"pūrvāhṇe vā'parāhṇe vā grīṣme śaradi ceṣyate varṣāsvadabhre nātyuṣṇe vasante tu sadaiva hi"},{"type":"verse","number":"198","sanskrit":"प्रातः सायन्तु तत्कुर्यान्न च कुर्यात्सदैव हि","text":"prātaḥ sāyantu tatkuryānna ca kuryātsadaiva hi"},{"type":"verse","number":"199","sanskrit":"श्रान्ते प्ररुदिते भीते पीतमद्ये नवज्वरे अजीर्णे वेगघाते च नाञ्जनं सम्प्रशस्यते","text":"śrānte prarudite bhīte pītamadye navajvare ajīrṇe vegaghāte ca nāñjanaṃ sampraśasyate"},{"type":"verse","number":"200","sanskrit":"पथ्याऽक्षधात्रीबीजानि एकद्वित्रिगुणानि च पिष्ट्वाऽम्बुना वटीं कुर्यादञ्जनं द्विहरेणुकम् नेत्रस्रावं हरत्याशु वातरक्तरुजं तथा","text":"pathyā'kṣadhātrībījāni ekadvitriguṇāni ca piṣṭvā'mbunā vaṭīṃ kuryādañjanaṃ dvihareṇukam netrasrāvaṃ haratyāśu vātaraktarujaṃ tathā"},{"type":"verse","number":"201","sanskrit":"रसाञ्जनं हरिद्रे द्वे मालतीनिम्बपल्लवाः गोशकृद्र ससंयुक्ता वटी नक्तान्ध्यनाशिनी एतस्याश्चाञ्जने मात्रा प्रोक्ता सार्द्धं हरेणुका","text":"rasāñjanaṃ haridre dve mālatīnimbapallavāḥ gośakṛdra sasaṃyuktā vaṭī naktāndhyanāśinī etasyāścāñjane mātrā proktā sārddhaṃ hareṇukā"},{"type":"verse","number":"202","sanskrit":"शङ्खनाभिर्बिभीतस्य मज्जा पथ्या मनः शिला पिप्पली मरिचं कुष्ठं वचा चेति समांशकम्","text":"śaṅkhanābhirbibhītasya majjā pathyā manaḥ śilā pippalī maricaṃ kuṣṭhaṃ vacā ceti samāṃśakam"},{"type":"verse","number":"203","sanskrit":"छागीक्षीरेण संपिष्य वटीं कुर्याद्यवोन्मिताम् हरेणुमात्रं संघृष्य जलेनाञ्जनमाचरेत्","text":"chāgīkṣīreṇa saṃpiṣya vaṭīṃ kuryādyavonmitām hareṇumātraṃ saṃghṛṣya jalenāñjanamācaret"},{"type":"verse","number":"204","sanskrit":"तिमिरं मांसवृद्धिञ्च काचं पटलमर्बुदम् रात्र्यन्ध्यं वार्षिकं पुष्पं वटी चन्द्रो दया जयेत्","text":"timiraṃ māṃsavṛddhiñca kācaṃ paṭalamarbudam rātryandhyaṃ vārṣikaṃ puṣpaṃ vaṭī candro dayā jayet"},{"type":"verse","number":"205","sanskrit":"पलाशपुष्पस्वरसैर्बहुशः परिभावितम् करञ्जबीजं तद्वर्त्तिर्दृष्टेः पुष्पं विनाशयेत्","text":"palāśapuṣpasvarasairbahuśaḥ paribhāvitam karañjabījaṃ tadvarttirdṛṣṭeḥ puṣpaṃ vināśayet"},{"type":"verse","number":"206","sanskrit":"कतकस्य फलं पिष्ट्वा मधुना नेत्रमञ्जयेत् ईषत्कर्पूरसहितं तत्स्यान्नेत्रप्रसादनम्","text":"katakasya phalaṃ piṣṭvā madhunā netramañjayet īṣatkarpūrasahitaṃ tatsyānnetraprasādanam"},{"type":"verse","number":"207","sanskrit":"रसाञ्जनं सर्जरसो जातीपुष्पं मनःशिला समुद्र फेनं लवणं गैरिकं मरिचं तथा","text":"rasāñjanaṃ sarjaraso jātīpuṣpaṃ manaḥśilā samudra phenaṃ lavaṇaṃ gairikaṃ maricaṃ tathā"},{"type":"verse","number":"208","sanskrit":"एतत्समांशं मधुना पिष्टं प्रक्लिन्नवर्त्मनि अञ्जनं क्लेदकण्डूघ्नं पक्ष्मणाञ्च प्ररोहणम्","text":"etatsamāṃśaṃ madhunā piṣṭaṃ praklinnavartmani añjanaṃ kledakaṇḍūghnaṃ pakṣmaṇāñca prarohaṇam"},{"type":"verse","number":"209","sanskrit":"दुग्धेन कण्डूं क्षौद्रे ण नेत्रस्रावञ्च सर्पिषा पुष्प तैलेन तिमिरं काञ्जिकेन निशाऽन्धताम्","text":"dugdhena kaṇḍūṃ kṣaudre ṇa netrasrāvañca sarpiṣā puṣpa tailena timiraṃ kāñjikena niśā'ndhatām"},{"type":"verse","number":"210","sanskrit":"पुनर्नवा हरत्याशु भास्करस्तिमिरं यथा","text":"punarnavā haratyāśu bhāskarastimiraṃ yathā"},{"type":"verse","number":"211","sanskrit":"बब्बूलदलनिक्वाथो लेहीभूतस्तदञ्जनात् नेत्रस्रावो व्रजेच्छोषं मधुयुक्तान्न संशयः","text":"babbūladalanikvātho lehībhūtastadañjanāt netrasrāvo vrajecchoṣaṃ madhuyuktānna saṃśayaḥ"},{"type":"verse","number":"212","sanskrit":"वटक्षीरेण संयुक्तं मुख्यकर्पूरजं रजः क्षिप्रमञ्जनतो हन्ति कुसुमं तु द्विमासिकम्","text":"vaṭakṣīreṇa saṃyuktaṃ mukhyakarpūrajaṃ rajaḥ kṣipramañjanato hanti kusumaṃ tu dvimāsikam"},{"type":"verse","number":"213","sanskrit":"क्षौद्रा श्वलालासंघृष्टैर्मरिचैर्नेत्रमञ्जयेत् अतिनिद्रा शमं याति तमः सूर्योदयादिव","text":"kṣaudrā śvalālāsaṃghṛṣṭairmaricairnetramañjayet atinidrā śamaṃ yāti tamaḥ sūryodayādiva"},{"type":"verse","number":"214","sanskrit":"अग्नितप्तं हि सौवीरं निषिञ्चेत्त्रिफलारसैः सप्तवेलं तथा स्तन्यैः स्त्रीणां सिक्तं विचूर्णितम्","text":"agnitaptaṃ hi sauvīraṃ niṣiñcettriphalārasaiḥ saptavelaṃ tathā stanyaiḥ strīṇāṃ siktaṃ vicūrṇitam"},{"type":"verse","number":"215","sanskrit":"अञ्जयेत्तेन नयने प्रत्यहं चक्षुषो हितम् सर्वानक्षिविकारांस्तु हन्यादेतन्न संशयः","text":"añjayettena nayane pratyahaṃ cakṣuṣo hitam sarvānakṣivikārāṃstu hanyādetanna saṃśayaḥ"},{"type":"verse","number":"216","sanskrit":"शिलायां रसकं पिष्ट्वा सम्यगाप्लाव्य वारिणा गृह्णीयात्तज्जलं सर्वं त्यजेच्चूर्णमधोगतम्","text":"śilāyāṃ rasakaṃ piṣṭvā samyagāplāvya vāriṇā gṛhṇīyāttajjalaṃ sarvaṃ tyajeccūrṇamadhogatam"},{"type":"verse","number":"217","sanskrit":"शुष्कञ्च तज्जलं सर्व पर्पटीसन्निभं भवेत् विचूर्ण्य भावयेत्सम्यक्त्रिवेलं त्रिफलारसैः","text":"śuṣkañca tajjalaṃ sarva parpaṭīsannibhaṃ bhavet vicūrṇya bhāvayetsamyaktrivelaṃ triphalārasaiḥ"},{"type":"verse","number":"218","sanskrit":"कर्पूरस्य रजस्तत्र दशमांशेन निक्षिपेत् अञ्जयन्नेयने तेन नेत्राखिलगदच्छिदा","text":"karpūrasya rajastatra daśamāṃśena nikṣipet añjayanneyane tena netrākhilagadacchidā"},{"type":"verse","number":"219","sanskrit":"दक्षाण्डत्वक्छिलाकाचशङ्खचन्दनसैन्धवैः चूर्णितैरञ्जनं प्रोक्तं पुष्पादीनां निकृन्तनम्","text":"dakṣāṇḍatvakchilākācaśaṅkhacandanasaindhavaiḥ cūrṇitairañjanaṃ proktaṃ puṣpādīnāṃ nikṛntanam"},{"type":"verse","number":"220","sanskrit":"मुक्ताकर्पूरकाचागुरुमरिचकणासैन्धवं सैलवालं शुण्ठीकक्लोलकांस्यत्रपुरजनिशिलाशङ्खनाभ्यभ्रतुत्थम् दक्षाण्डत्वक्च साक्षं क्षतजमथ शिवा क्लीतकं राजवर्त्त जातीपुष्पं तुलस्याः कुसुममभिनवं बीजकं स्यात्तथैव","text":"muktākarpūrakācāgurumaricakaṇāsaindhavaṃ sailavālaṃ śuṇṭhīkaklolakāṃsyatrapurajaniśilāśaṅkhanābhyabhratuttham dakṣāṇḍatvakca sākṣaṃ kṣatajamatha śivā klītakaṃ rājavartta jātīpuṣpaṃ tulasyāḥ kusumamabhinavaṃ bījakaṃ syāttathaiva"},{"type":"verse","number":"221","sanskrit":"पूतीकनिम्बार्जुनभद्र मुस्तं सताम्रसारं रसगर्भयुक्तम् प्रत्येकमेषां खलु माषकैकं यत्नेन पिष्येन्मधुनाऽतिसूक्ष्मम्","text":"pūtīkanimbārjunabhadra mustaṃ satāmrasāraṃ rasagarbhayuktam pratyekameṣāṃ khalu māṣakaikaṃ yatnena piṣyenmadhunā'tisūkṣmam"},{"type":"verse","number":"222","sanskrit":"भवन्ति रोगा नयनाश्रिता ये नितान्तमात्रोपचिताश्च तेषाम् विधीयते शान्तिरवश्यमेव मुक्ताऽदिनाऽनेन महाञ्जनेन","text":"bhavanti rogā nayanāśritā ye nitāntamātropacitāśca teṣām vidhīyate śāntiravaśyameva muktā'dinā'nena mahāñjanena"},{"type":"verse","number":"223","sanskrit":"कणा सलवणोषणा सहरसाञ्जना साञ्जना सरित्पतिकफः सिता सितपुनर्नवासम्भवा रजन्यरुणचन्दनं मधुकतुत्थपथ्याशिला ह्यरिष्टदलशावरस्फटिकशङ्खनाभीन्दवः","text":"kaṇā salavaṇoṣaṇā saharasāñjanā sāñjanā saritpatikaphaḥ sitā sitapunarnavāsambhavā rajanyaruṇacandanaṃ madhukatutthapathyāśilā hyariṣṭadalaśāvarasphaṭikaśaṅkhanābhīndavaḥ"},{"type":"verse","number":"224","sanskrit":"इमानि तु विचूर्णयेन्निबिडवाससा शोधयेत् तथाऽयसि विमर्दयेत्समधु ताम्रखण्डेन तत् इदं मुनिभिरीरितं नयनशोणनामाञ्जनं करोति तिमिरक्षयं पटलपुष्पनाशं बलात्","text":"imāni tu vicūrṇayennibiḍavāsasā śodhayet tathā'yasi vimardayetsamadhu tāmrakhaṇḍena tat idaṃ munibhirīritaṃ nayanaśoṇanāmāñjanaṃ karoti timirakṣayaṃ paṭalapuṣpanāśaṃ balāt"},{"type":"verse","number":"225","sanskrit":"हरीतकी वचा कुष्ठं पिप्पली मरिचानि च बिभीतकस्य मज्जा च शङ्खनाभिर्मनः शिला","text":"harītakī vacā kuṣṭhaṃ pippalī maricāni ca bibhītakasya majjā ca śaṅkhanābhirmanaḥ śilā"},{"type":"verse","number":"226","sanskrit":"सर्वमेतत्समं कृत्वा गव्यक्षीरेण पेषयेत् नाशयेत्तिमिरं कण्डूपटलान्यर्बुदानि च","text":"sarvametatsamaṃ kṛtvā gavyakṣīreṇa peṣayet nāśayettimiraṃ kaṇḍūpaṭalānyarbudāni ca"},{"type":"verse","number":"227","sanskrit":"अपि त्रिवार्षिकं शुक्लं मासेनैकेन नाशयेत् अधिकानि च मांसानि रात्रावन्धत्वमेव च","text":"api trivārṣikaṃ śuklaṃ māsenaikena nāśayet adhikāni ca māṃsāni rātrāvandhatvameva ca"},{"type":"verse","number":"228","sanskrit":"रजनी निम्बपत्राणि पिप्पली मरिचानि च विडङ्गं भद्र मुस्तं च सप्तमीत्वभया स्मृता","text":"rajanī nimbapatrāṇi pippalī maricāni ca viḍaṅgaṃ bhadra mustaṃ ca saptamītvabhayā smṛtā"},{"type":"verse","number":"229","sanskrit":"अजामूत्रेण सम्पिष्य च्छायायां शोषयेद्वटीम् वारिणा तिमिरं हन्ति गोमूत्रेण तु पिष्टकम्","text":"ajāmūtreṇa sampiṣya cchāyāyāṃ śoṣayedvaṭīm vāriṇā timiraṃ hanti gomūtreṇa tu piṣṭakam"},{"type":"verse","number":"230","sanskrit":"मधुना पटलं हन्ति नारीक्षीरेण पुष्पकम् एषा चन्द्र प्रभा वर्त्तिः स्वयं रुद्रे ण निर्मिता","text":"madhunā paṭalaṃ hanti nārīkṣīreṇa puṣpakam eṣā candra prabhā varttiḥ svayaṃ rudre ṇa nirmitā"},{"type":"verse","number":"231","sanskrit":"कणा च्छागयकृन्मध्ये पक्त्वा तद्र सपेषिता अचिराद्धन्ति नक्तान्ध्यं तद्वत्सक्षौद्र मूषणम्","text":"kaṇā cchāgayakṛnmadhye paktvā tadra sapeṣitā acirāddhanti naktāndhyaṃ tadvatsakṣaudra mūṣaṇam"},{"type":"verse","number":"232","sanskrit":"त्रिफलाया रसं प्रस्थं प्रस्थं भृङ्गरजस्य च वृषस्य च रसं प्रस्थं शतावर्याश्च तत्समम्","text":"triphalāyā rasaṃ prasthaṃ prasthaṃ bhṛṅgarajasya ca vṛṣasya ca rasaṃ prasthaṃ śatāvaryāśca tatsamam"},{"type":"verse","number":"233","sanskrit":"गुडूच्या आमलक्याश्च रसं छागीपयस्तथा प्रस्थं प्रस्थं समाहृत्य सर्वैरेभिर्घृतं पचेत्","text":"guḍūcyā āmalakyāśca rasaṃ chāgīpayastathā prasthaṃ prasthaṃ samāhṛtya sarvairebhirghṛtaṃ pacet"},{"type":"verse","number":"234","sanskrit":"कल्कः कणा सिता द्रा क्षा त्रिफला नीलमुत्पलम् मधुकं क्षीरकाकोली मधुपर्णी निदिग्धिका","text":"kalkaḥ kaṇā sitā drā kṣā triphalā nīlamutpalam madhukaṃ kṣīrakākolī madhuparṇī nidigdhikā"},{"type":"verse","number":"235","sanskrit":"तत्साधु सिद्धं विज्ञाय शुभे भाण्डे निधापयेत् ऊर्द्ध्वं पानमधःपानं मध्ये पानं च शस्यते","text":"tatsādhu siddhaṃ vijñāya śubhe bhāṇḍe nidhāpayet ūrddhvaṃ pānamadhaḥpānaṃ madhye pānaṃ ca śasyate"},{"type":"verse","number":"236","sanskrit":"यावन्तो नेत्ररोगाः स्युस्तान्पानादपकर्षति सरक्ते रक्तदुष्टे च रक्ते वा विस्रुते तथा","text":"yāvanto netrarogāḥ syustānpānādapakarṣati sarakte raktaduṣṭe ca rakte vā visrute tathā"},{"type":"verse","number":"237","sanskrit":"नक्तान्ध्ये तिमिरे काचे नीलिकापटलार्बुदे अभिष्यन्देऽधिमन्थे च पक्ष्मकोषे सुदारुणे","text":"naktāndhye timire kāce nīlikāpaṭalārbude abhiṣyande'dhimanthe ca pakṣmakoṣe sudāruṇe"},{"type":"verse","number":"238","sanskrit":"नेत्ररोगेषु सर्वेषु दोषत्रयकृतेष्वपि परं हितमिदं प्रोक्तं त्रिफलाऽद्य महाघृतम्","text":"netrarogeṣu sarveṣu doṣatrayakṛteṣvapi paraṃ hitamidaṃ proktaṃ triphalā'dya mahāghṛtam"},{"type":"verse","number":"239","sanskrit":"शतमेकं हरीतक्या द्विगुणञ्च बिभीतकम् चतुर्गुणं त्वामलकं वृषमार्कवयोः समम्","text":"śatamekaṃ harītakyā dviguṇañca bibhītakam caturguṇaṃ tvāmalakaṃ vṛṣamārkavayoḥ samam"},{"type":"verse","number":"240","sanskrit":"चतुर्गुणोदकं दत्वा शनैर्मृद्वग्निना पचेत् भागं चतुर्थं संरक्ष्य क्वाथं तमवतारयेत्","text":"caturguṇodakaṃ datvā śanairmṛdvagninā pacet bhāgaṃ caturthaṃ saṃrakṣya kvāthaṃ tamavatārayet"},{"type":"verse","number":"241","sanskrit":"शर्करा मधुकं द्रा क्षा मधुयष्टी निदिग्धिका काकोली क्षीरकाकोली त्रिफला नागकेशरम्","text":"śarkarā madhukaṃ drā kṣā madhuyaṣṭī nidigdhikā kākolī kṣīrakākolī triphalā nāgakeśaram"},{"type":"verse","number":"242","sanskrit":"पिप्पली नन्दनं मुस्तं त्रायमाणा तथोत्पलम् घृतप्रस्थं समं क्षीरं कल्कैरेतैः शनैः पचेत्","text":"pippalī nandanaṃ mustaṃ trāyamāṇā tathotpalam ghṛtaprasthaṃ samaṃ kṣīraṃ kalkairetaiḥ śanaiḥ pacet"},{"type":"verse","number":"243","sanskrit":"हन्यात्सतिमिरं काचं नक्तान्ध्यं शुल्कमेव च तथा स्रावं च कण्डूञ्च श्वयथुं च कषायताम्","text":"hanyātsatimiraṃ kācaṃ naktāndhyaṃ śulkameva ca tathā srāvaṃ ca kaṇḍūñca śvayathuṃ ca kaṣāyatām"},{"type":"verse","number":"244","sanskrit":"कलुषत्वं च नेत्रस्य बिन्द्वर्मपटलानि च बहुनाऽत्र किमुक्तेन सर्वान्नेत्रामयान्हरेत्","text":"kaluṣatvaṃ ca netrasya bindvarmapaṭalāni ca bahunā'tra kimuktena sarvānnetrāmayānharet"},{"type":"verse","number":"245","sanskrit":"यस्य चोपहता दृष्टिः सूर्याग्निभ्यां प्रपश्यतः तस्यैतद् भेषजं प्रोक्तं मुनिभिः परमं हितम्","text":"yasya copahatā dṛṣṭiḥ sūryāgnibhyāṃ prapaśyataḥ tasyaitad bheṣajaṃ proktaṃ munibhiḥ paramaṃ hitam"},{"type":"verse","number":"246","sanskrit":"मार्जितं दर्पणं यद्वत्परां निर्मलतां व्रजेत् तद्वदेतेन पीतेन नेत्रं निर्मलतामियात् वारिद्रो णद्वयं चात्र बृषमार्कवयोस्तुले","text":"mārjitaṃ darpaṇaṃ yadvatparāṃ nirmalatāṃ vrajet tadvadetena pītena netraṃ nirmalatāmiyāt vāridro ṇadvayaṃ cātra bṛṣamārkavayostule"},{"type":"verse","number":"247","sanskrit":"वासविश्वाऽमृतादार्वीरक्तचन्दनचित्रकैः भूनिम्बनिम्बकटुकापटोलत्रिफलाऽम्बुदैः","text":"vāsaviśvā'mṛtādārvīraktacandanacitrakaiḥ bhūnimbanimbakaṭukāpaṭolatriphalā'mbudaiḥ"},{"type":"verse","number":"248","sanskrit":"निशाकलिङ्गकुटजः क्वाथः सर्वाक्षिरोगहा वैस्वर्यं पीनसं श्वासं कासं नाशयति ध्रुवम् २४७ इति त्रिषष्टितमो नेत्ररोगाधिकारः समाप्तः ६३","text":"niśākaliṅgakuṭajaḥ kvāthaḥ sarvākṣirogahā vaisvaryaṃ pīnasaṃ śvāsaṃ kāsaṃ nāśayati dhruvam 247 iti triṣaṣṭitamo netrarogādhikāraḥ samāptaḥ 63"}]},{"sthana":"Уттаракханда","number":63,"lang":"sa","content":[{"type":"heading","heading":"Карна — болезни ушей"},{"type":"verse","number":"1","sanskrit":"कर्णशूलः कर्णनादो बाधिर्यं क्ष्वेड एव च कर्ण स्रावकर्णकण्डूः कर्णगूथस्तथैव च","text":"karṇaśūlaḥ karṇanādo bādhiryaṃ kṣveḍa eva ca karṇa srāvakarṇakaṇḍūḥ karṇagūthastathaiva ca"},{"type":"verse","number":"2","sanskrit":"प्रतिनाहो जन्तुकर्णो विद्र धिर्द्विविधस्तथा कर्णपाकःपूतिकर्णस्तथैवार्शश्चतुर्विधः","text":"pratināho jantukarṇo vidra dhirdvividhastathā karṇapākaḥpūtikarṇastathaivārśaścaturvidhaḥ"},{"type":"verse","number":"3","sanskrit":"तथाऽबुदं सप्तविधं शोफश्चापि चतुर्विधः एते कर्णगता रोगा अष्टाविंशतिरीरिताः","text":"tathā'budaṃ saptavidhaṃ śophaścāpi caturvidhaḥ ete karṇagatā rogā aṣṭāviṃśatirīritāḥ"},{"type":"verse","number":"4","sanskrit":"समीरणः श्रोत्रगतोऽन्यथा चरन्समन्ततः शूलमतीव कर्णयोः करोति दोषैश्च यथास्वमावृतः स कर्णशूलः कथितो दुराचरः","text":"samīraṇaḥ śrotragato'nyathā caransamantataḥ śūlamatīva karṇayoḥ karoti doṣaiśca yathāsvamāvṛtaḥ sa karṇaśūlaḥ kathito durācaraḥ"},{"type":"verse","number":"5","sanskrit":"मूर्च्छा दाहो ज्वरः कासः श्वासोऽथ वमथुस्तथा उपद्र वाः कर्णशूले भवन्त्येते मरिष्यतः","text":"mūrcchā dāho jvaraḥ kāsaḥ śvāso'tha vamathustathā upadra vāḥ karṇaśūle bhavantyete mariṣyataḥ"},{"type":"verse","number":"6","sanskrit":"कर्णश्रोत्रस्थिते वाते शृणोति विविधान्स्वनान् भेरीमृदङ्गशङ्खानां कर्णनादः स उच्यते","text":"karṇaśrotrasthite vāte śṛṇoti vividhānsvanān bherīmṛdaṅgaśaṅkhānāṃ karṇanādaḥ sa ucyate"},{"type":"verse","number":"7","sanskrit":"यदा शब्दवहं वायुः स्रोत आवृत्य तिष्ठति शुद्धः श्लेष्मान्वितो वाऽपि बाधिर्य तेन जायते","text":"yadā śabdavahaṃ vāyuḥ srota āvṛtya tiṣṭhati śuddhaḥ śleṣmānvito vā'pi bādhirya tena jāyate"},{"type":"verse","number":"8","sanskrit":"बाधिर्यं बालवृद्धोत्थं चिरोत्थञ्च विवर्जयेत्","text":"bādhiryaṃ bālavṛddhotthaṃ cirotthañca vivarjayet"},{"type":"verse","number":"9","sanskrit":"वायुः पित्तादिभिर्युक्तो वेणुघोषसमं स्वनम् करोति कर्णयोः क्ष्वेडं कर्णक्ष्वेडः स उच्यते","text":"vāyuḥ pittādibhiryukto veṇughoṣasamaṃ svanam karoti karṇayoḥ kṣveḍaṃ karṇakṣveḍaḥ sa ucyate"},{"type":"verse","number":"10","sanskrit":"शिरोऽभिघातादथ वा निमज्जतो जले प्रपातादथ वाऽपि विद्र धेः स्रवेद्धि पूयं श्रवणोऽनिलार्दितः स कर्णसंस्राव इति प्रकीर्त्तितः","text":"śiro'bhighātādatha vā nimajjato jale prapātādatha vā'pi vidra dheḥ sraveddhi pūyaṃ śravaṇo'nilārditaḥ sa karṇasaṃsrāva iti prakīrttitaḥ"},{"type":"verse","number":"11","sanskrit":"मारुतः कफसंयुक्तः कर्णे कण्डूं करोति हि","text":"mārutaḥ kaphasaṃyuktaḥ karṇe kaṇḍūṃ karoti hi"},{"type":"verse","number":"12","sanskrit":"पित्तोष्मशोषितः श्लेष्मा कुरुते कर्णगूथकम्","text":"pittoṣmaśoṣitaḥ śleṣmā kurute karṇagūthakam"},{"type":"verse","number":"13","sanskrit":"स कर्णगूथो द्र वतां यदा गतो विलायितो घ्राणमुखं प्रपद्यते तदा स कर्णप्रतिनाहसंज्ञितो भवेद्विकारः शिरसाऽद्धभेदकृत्","text":"sa karṇagūtho dra vatāṃ yadā gato vilāyito ghrāṇamukhaṃ prapadyate tadā sa karṇapratināhasaṃjñito bhavedvikāraḥ śirasā'ddhabhedakṛt"},{"type":"verse","number":"14","sanskrit":"यदा तु मूर्च्छन्त्यथवा तु जन्तवः सृजन्त्यपत्त्यान्यथवाऽपि मक्षिकाः तदञ्जनत्वाच्छ्रवणे निरुच्यते भिषग्भिराद्यैः कृमिकर्णको गदः","text":"yadā tu mūrcchantyathavā tu jantavaḥ sṛjantyapattyānyathavā'pi makṣikāḥ tadañjanatvācchravaṇe nirucyate bhiṣagbhirādyaiḥ kṛmikarṇako gadaḥ"},{"type":"verse","number":"15","sanskrit":"पतङ्गाः शतपद्यश्च कर्णस्रोतः प्रविश्य हि अरतिं व्याकुलत्वञ्च भृशं कुर्वन्ति वेदनाम् कर्णो निस्तुद्यते तस्य तथा च फर्फरायते कीटे चरति रुक्तीव्रा निस्पन्दे मन्दवेदना","text":"pataṅgāḥ śatapadyaśca karṇasrotaḥ praviśya hi aratiṃ vyākulatvañca bhṛśaṃ kurvanti vedanām karṇo nistudyate tasya tathā ca pharpharāyate kīṭe carati ruktīvrā nispande mandavedanā"},{"type":"verse","number":"16","sanskrit":"क्षताभिघातप्रभवस्तु विद्र धिर्भवेत्तथा दोषकृतोऽपरः पुनः स रक्तपीतारुणमस्रमास्रवेत्प्रतोदधूमायनदाहचोषवान्","text":"kṣatābhighātaprabhavastu vidra dhirbhavettathā doṣakṛto'paraḥ punaḥ sa raktapītāruṇamasramāsravetpratodadhūmāyanadāhacoṣavān"},{"type":"verse","number":"17","sanskrit":"कर्णपाकस्तु पित्तेन कोथविक्लेदकृद्भवेत्","text":"karṇapākastu pittena kothavikledakṛdbhavet"},{"type":"verse","number":"18","sanskrit":"कर्णविद्र धपाकेन कर्णे वा वारिपूरणात् पूयं स्रवति यः पूति स ज्ञेयः पूतिकर्णकः","text":"karṇavidra dhapākena karṇe vā vāripūraṇāt pūyaṃ sravati yaḥ pūti sa jñeyaḥ pūtikarṇakaḥ"},{"type":"verse","number":"19","sanskrit":"कर्णशोथार्बुदार्शांसि जानीयादुक्तलक्षणैः","text":"karṇaśothārbudārśāṃsi jānīyāduktalakṣaṇaiḥ"},{"type":"verse","number":"20","sanskrit":"नादोऽतिरुक्कर्णमलस्य शोथः स्रावस्तनुश्चावणञ्च वातात्","text":"nādo'tirukkarṇamalasya śothaḥ srāvastanuścāvaṇañca vātāt"},{"type":"verse","number":"21","sanskrit":"शोथः सरागो दरणं विदाहः सपूतिपीतस्रवणञ्च पित्तात्","text":"śothaḥ sarāgo daraṇaṃ vidāhaḥ sapūtipītasravaṇañca pittāt"},{"type":"verse","number":"22","sanskrit":"वैश्रुत्यकण्डूस्थिरशोथशुक्ल स्निग्धा स्रुतिः स्वल्परुजा कफाच्च","text":"vaiśrutyakaṇḍūsthiraśothaśukla snigdhā srutiḥ svalparujā kaphācca"},{"type":"verse","number":"23","sanskrit":"सर्वाणि रूपाणि च सन्निपातात्स्रावश्च तत्राधिकदोषवर्णः","text":"sarvāṇi rūpāṇi ca sannipātātsrāvaśca tatrādhikadoṣavarṇaḥ"},{"type":"verse","number":"24","sanskrit":"अथ कर्णपालीरोगाः सौकुमार्याच्चिरोत्सृष्टे सहसैवातिवर्धिते कर्णे शोथो भवेत्पाल्यां सरुजः परिपोटवान् कृष्णारुणनिभः स्तब्धः स वातात्परिपोटकः","text":"atha karṇapālīrogāḥ saukumāryāccirotsṛṣṭe sahasaivātivardhite karṇe śotho bhavetpālyāṃ sarujaḥ paripoṭavān kṛṣṇāruṇanibhaḥ stabdhaḥ sa vātātparipoṭakaḥ"},{"type":"verse","number":"25","sanskrit":"गुर्वाभरण संयोगात्ताडनाद्घर्षणादपि शोथः पाल्यां भवेच्छ्यावो दाहपाकरुजाऽन्वितः रक्तो वा रक्तपित्ताभ्यामुत्पातः सगदः स्मृतः","text":"gurvābharaṇa saṃyogāttāḍanādgharṣaṇādapi śothaḥ pālyāṃ bhavecchyāvo dāhapākarujā'nvitaḥ rakto vā raktapittābhyāmutpātaḥ sagadaḥ smṛtaḥ"},{"type":"verse","number":"26","sanskrit":"कर्णं बलाद्वर्द्धयतः पाल्यां वायुः प्रकुप्यति कफं संगृह्य कुरुते शोथं स्तब्धमवेदनम् उन्मन्थकः सकण्डूको विकारः कफवातजः","text":"karṇaṃ balādvarddhayataḥ pālyāṃ vāyuḥ prakupyati kaphaṃ saṃgṛhya kurute śothaṃ stabdhamavedanam unmanthakaḥ sakaṇḍūko vikāraḥ kaphavātajaḥ"},{"type":"verse","number":"27","sanskrit":"संवर्ध्यमाने दुर्विद्धे कण्डूदाहरुजाऽन्वितः शोथो भवति पाकश्च त्रिदोषो दुःखवर्द्धनः","text":"saṃvardhyamāne durviddhe kaṇḍūdāharujā'nvitaḥ śotho bhavati pākaśca tridoṣo duḥkhavarddhanaḥ"},{"type":"verse","number":"28","sanskrit":"कफासृक्कृमयः क्रुद्धाः सर्षपाभा विसारिणः कुर्वन्ति पिडकां पाल्यां कण्डूदाहसमन्विताम् कफासृक्कृमिसम्भूतः स विसर्पन्नितस्ततः लिह्यात्सशष्कुलद्यं पालद्यं परिलेही च स स्मृतः","text":"kaphāsṛkkṛmayaḥ kruddhāḥ sarṣapābhā visāriṇaḥ kurvanti piḍakāṃ pālyāṃ kaṇḍūdāhasamanvitām kaphāsṛkkṛmisambhūtaḥ sa visarpannitastataḥ lihyātsaśaṣkuladyaṃ pāladyaṃ parilehī ca sa smṛtaḥ"},{"type":"verse","number":"29","sanskrit":"कर्णशूले कर्णनादे बाधिर्ये क्ष्वेड एव च चतुर्ष्वपि च रोगेषु सामान्यं भेषजं स्मृतम् शृङ्गवेरं सहमधु सैन्धवं तैलमेव च कदुष्णं कर्णयोर्धार्यमेतत्स्याद् वेदनाऽपहम्","text":"karṇaśūle karṇanāde bādhirye kṣveḍa eva ca caturṣvapi ca rogeṣu sāmānyaṃ bheṣajaṃ smṛtam śṛṅgaveraṃ sahamadhu saindhavaṃ tailameva ca kaduṣṇaṃ karṇayordhāryametatsyād vedanā'paham"},{"type":"verse","number":"30","sanskrit":"लशुनार्द्र कशिग्रूणां वारुण्या मूलकस्य च कदल्याः स्वरसः श्रेष्ठः कदुष्णः कर्णपूरणे","text":"laśunārdra kaśigrūṇāṃ vāruṇyā mūlakasya ca kadalyāḥ svarasaḥ śreṣṭhaḥ kaduṣṇaḥ karṇapūraṇe"},{"type":"verse","number":"31","sanskrit":"अर्काङ्कुरानम्लपिष्टान्स तैललवणान्वितान् सन्निदध्यात्सुधाकाण्डे कोरिते मृत्स्नयाऽवृते","text":"arkāṅkurānamlapiṣṭānsa tailalavaṇānvitān sannidadhyātsudhākāṇḍe korite mṛtsnayā'vṛte"},{"type":"verse","number":"32","sanskrit":"पुटपाकक्रमात्स्विन्नं पीडयेदारसागमात् सुखोष्णं तद्र सं कर्णे प्रक्षिपेच्छूलशान्तये","text":"puṭapākakramātsvinnaṃ pīḍayedārasāgamāt sukhoṣṇaṃ tadra saṃ karṇe prakṣipecchūlaśāntaye"},{"type":"verse","number":"33","sanskrit":"अर्कस्य पत्रं परिणामपीतमाज्येन लिप्तं शिखियोगतप्तम् आपीड्य तस्याम्बु सुखोष्णमेव कर्णे निषिक्तं हरते हि शूलम्","text":"arkasya patraṃ pariṇāmapītamājyena liptaṃ śikhiyogataptam āpīḍya tasyāmbu sukhoṣṇameva karṇe niṣiktaṃ harate hi śūlam"},{"type":"verse","number":"34","sanskrit":"तीव्रशूलातुरे कर्णे सशब्दे क्लेदवाहिनि छागमूत्रं प्रशंसन्ति कोष्णं सैन्धवसंयुतम्","text":"tīvraśūlāture karṇe saśabde kledavāhini chāgamūtraṃ praśaṃsanti koṣṇaṃ saindhavasaṃyutam"},{"type":"verse","number":"35","sanskrit":"तैलं श्वेतार्कमूलेन मन्देऽग्नौ विधिना कृतम् हरेदाशु त्रिदोषोत्थं कर्णशूलप्रपूरणात्","text":"tailaṃ śvetārkamūlena mande'gnau vidhinā kṛtam haredāśu tridoṣotthaṃ karṇaśūlaprapūraṇāt"},{"type":"verse","number":"36","sanskrit":"हिङ्गुसैन्धवशुण्ठीभिस्तैलं सर्षपसम्भवम् विपक्वं हरतेऽवश्यं कर्णशूलं प्रपूरणात्","text":"hiṅgusaindhavaśuṇṭhībhistailaṃ sarṣapasambhavam vipakvaṃ harate'vaśyaṃ karṇaśūlaṃ prapūraṇāt"},{"type":"verse","number":"37","sanskrit":"कर्णशूले कर्णनादे बाधिर्ये क्ष्वेड एव च पूरणं कटुतैलेन हितं वातघ्नमौषधम्","text":"karṇaśūle karṇanāde bādhirye kṣveḍa eva ca pūraṇaṃ kaṭutailena hitaṃ vātaghnamauṣadham"},{"type":"verse","number":"38","sanskrit":"शिखरिक्षारजवारि तत्कृतकल्केन साधितं तैलम् अपहरति कर्णनादं बाधिर्यं चापि पूरणतः","text":"śikharikṣārajavāri tatkṛtakalkena sādhitaṃ tailam apaharati karṇanādaṃ bādhiryaṃ cāpi pūraṇataḥ"},{"type":"verse","number":"39","sanskrit":"गवां मूत्रेण बिल्वानि पिष्ट्वा तैलं विपाचयेत् सजलञ्च सदुग्धञ्च तद्बाधिर्यहरं परम् इति बिल्व तैलम् कर्णस्रावे पूतिकर्णे तथैव कृमिकर्णके सामान्यं कर्म कुर्वीत योगान्वैशेषिकानपि","text":"gavāṃ mūtreṇa bilvāni piṣṭvā tailaṃ vipācayet sajalañca sadugdhañca tadbādhiryaharaṃ param iti bilva tailam karṇasrāve pūtikarṇe tathaiva kṛmikarṇake sāmānyaṃ karma kurvīta yogānvaiśeṣikānapi"},{"type":"verse","number":"40","sanskrit":"स्वर्जिकाचूर्णसंयुक्तं बीजपूररसं क्षिपेत् कर्णस्रावरुजो दाहास्ते नश्यन्ति न संशयः","text":"svarjikācūrṇasaṃyuktaṃ bījapūrarasaṃ kṣipet karṇasrāvarujo dāhāste naśyanti na saṃśayaḥ"},{"type":"verse","number":"41","sanskrit":"आम्रजम्बूप्रवालानि मधुकस्य वटस्य च एभिस्तु साधितं तैलं पूतिकर्णगदं हरेत्","text":"āmrajambūpravālāni madhukasya vaṭasya ca ebhistu sādhitaṃ tailaṃ pūtikarṇagadaṃ haret"},{"type":"verse","number":"42","sanskrit":"जातीपत्ररसैस्तैलं विपक्वं पूतिकर्णजित् पिष्टं रसाञ्जनं नार्याः क्षीरेण क्षौद्र संयुतम् प्रशस्यते चिरोत्थे तत्स्रावके पूतिकर्णके","text":"jātīpatrarasaistailaṃ vipakvaṃ pūtikarṇajit piṣṭaṃ rasāñjanaṃ nāryāḥ kṣīreṇa kṣaudra saṃyutam praśasyate cirotthe tatsrāvake pūtikarṇake"},{"type":"verse","number":"43","sanskrit":"कुष्ठहिङ्गुबचा दारुशताह्वाविश्वसैन्धवैः पूतिकर्णापहं तैलं बस्तमूत्रेण साधितम्","text":"kuṣṭhahiṅgubacā dāruśatāhvāviśvasaindhavaiḥ pūtikarṇāpahaṃ tailaṃ bastamūtreṇa sādhitam"},{"type":"verse","number":"44","sanskrit":"शम्बूकस्य तु मांसेन कटुतैलं विपाचयेत् तस्य पूरणमात्रेण कर्णनाडी प्रशाम्यति","text":"śambūkasya tu māṃsena kaṭutailaṃ vipācayet tasya pūraṇamātreṇa karṇanāḍī praśāmyati"},{"type":"verse","number":"45","sanskrit":"चूर्णेन गन्धकशिलारजनीभवेन मुष्ट्यंशकेन कटुतैलपलाष्टकन्तु धत्तूरपत्ररसतुल्यमिदं विपक्वं नाडीं जयेच्चिरभवामपि कर्णजाताम्","text":"cūrṇena gandhakaśilārajanībhavena muṣṭyaṃśakena kaṭutailapalāṣṭakantu dhattūrapatrarasatulyamidaṃ vipakvaṃ nāḍīṃ jayeccirabhavāmapi karṇajātām"},{"type":"verse","number":"46","sanskrit":"कृमिकर्णविनाशाय कृमिघ्नीं कारयेत्क्रियाम् वार्त्ताकुधूमश्च हितःसार्षपः स्नेह एव च","text":"kṛmikarṇavināśāya kṛmighnīṃ kārayetkriyām vārttākudhūmaśca hitaḥsārṣapaḥ sneha eva ca"},{"type":"verse","number":"47","sanskrit":"पूरणं हरितालेन गव्यमूत्रयुतेन च धूपने कर्णदौर्गन्ध्ये गुग्गुलुः श्रेष्ठ उच्यते","text":"pūraṇaṃ haritālena gavyamūtrayutena ca dhūpane karṇadaurgandhye gugguluḥ śreṣṭha ucyate"},{"type":"verse","number":"48","sanskrit":"चिकित्सा कर्णशोथानां तथा कर्णार्शसामपि कर्णार्बुदानां कुर्वीत शोथार्शोऽबुदवद्भिषक्","text":"cikitsā karṇaśothānāṃ tathā karṇārśasāmapi karṇārbudānāṃ kurvīta śothārśo'budavadbhiṣak"},{"type":"verse","number":"49","sanskrit":"पालीसंशोषणे कुर्याद्वातकर्णरुजः क्रियाः स्वेदयेद्यत्नतस्तां च स्विन्नां संवर्धयेत्तिलैः","text":"pālīsaṃśoṣaṇe kuryādvātakarṇarujaḥ kriyāḥ svedayedyatnatastāṃ ca svinnāṃ saṃvardhayettilaiḥ"},{"type":"verse","number":"50","sanskrit":"शतावरीवाजिगन्धापय स्यैरण्डबीजकैः तैलं विपक्वं सक्षीरं पालद्यं संवर्द्धयेत्सुखम्","text":"śatāvarīvājigandhāpaya syairaṇḍabījakaiḥ tailaṃ vipakvaṃ sakṣīraṃ pāladyaṃ saṃvarddhayetsukham"},{"type":"verse","number":"51","sanskrit":"जीवनीयस्य कल्केन तैलं दुग्धेन पाचयेत् चिकित्सेत्तेन तैलेन हृतास्रं परिपोटकम्","text":"jīvanīyasya kalkena tailaṃ dugdhena pācayet cikitsettena tailena hṛtāsraṃ paripoṭakam"},{"type":"verse","number":"52","sanskrit":"शीतलेपैर्जलौकोभिरुत्पातं समुपाचरेत् हलिनीसुरसाभ्यां च गोधाकङ्कवसाऽन्वितम्","text":"śītalepairjalaukobhirutpātaṃ samupācaret halinīsurasābhyāṃ ca godhākaṅkavasā'nvitam"},{"type":"verse","number":"53","sanskrit":"तैलञ्च पक्वमभ्यङ्गादुन्मन्थं नाशयेद् ध्रुवम् दुःखवर्द्धनकं सिक्त्वा जम्ब्वाम्रबिल्वपत्रजैः","text":"tailañca pakvamabhyaṅgādunmanthaṃ nāśayed dhruvam duḥkhavarddhanakaṃ siktvā jambvāmrabilvapatrajaiḥ"},{"type":"verse","number":"54","sanskrit":"क्वाथैस्तैलेन सुस्निग्धं तच्चूर्णैश्चावधूलयेत् बहुशो गोमयैस्तप्तैः स्वेदितं परिलेहितम् घनसारैः समालिम्पेदजामूत्रेण कल्कितैः","text":"kvāthaistailena susnigdhaṃ taccūrṇaiścāvadhūlayet bahuśo gomayaistaptaiḥ sveditaṃ parilehitam ghanasāraiḥ samālimpedajāmūtreṇa kalkitaiḥ"},{"type":"verse","number":"55","sanskrit":"इति चतुःषष्टितमः कर्णरोगाधिकारः समाप्तः ६४","text":"iti catuḥṣaṣṭitamaḥ karṇarogādhikāraḥ samāptaḥ 64"}]},{"sthana":"Уттаракханда","number":64,"lang":"sa","content":[{"type":"heading","heading":"Наса — болезни носа"},{"type":"verse","number":"1","sanskrit":"आदौ च पीनसः प्रोक्तः पूतिनस्यस्ततः परम् नासापाकोऽत्र गणितः पूयशोणितमेव च","text":"ādau ca pīnasaḥ proktaḥ pūtinasyastataḥ param nāsāpāko'tra gaṇitaḥ pūyaśoṇitameva ca"},{"type":"verse","number":"2","sanskrit":"क्षवथुर्भ्रंशथुर्दीप्तिः प्रतीनाहः परिस्रवः नासाशोषः प्रतिश्यायाः पञ्च सप्तार्बुदानि च","text":"kṣavathurbhraṃśathurdīptiḥ pratīnāhaḥ parisravaḥ nāsāśoṣaḥ pratiśyāyāḥ pañca saptārbudāni ca"},{"type":"verse","number":"3","sanskrit":"चत्वार्यर्शांसि चत्वारः शोथाश्चत्वारि तानि च रक्तपित्तानि नासायां चतुस्त्रिंशद्गदाः स्मृताः","text":"catvāryarśāṃsi catvāraḥ śothāścatvāri tāni ca raktapittāni nāsāyāṃ catustriṃśadgadāḥ smṛtāḥ"},{"type":"verse","number":"4","sanskrit":"आनह्यते शुष्यति यस्य नासा प्रक्लेदमायाति तु धूप्यते च न वेत्ति यो गन्धरसांश्च जन्तुर्जुष्टं व्यवस्येदिह पीनसेन","text":"ānahyate śuṣyati yasya nāsā prakledamāyāti tu dhūpyate ca na vetti yo gandharasāṃśca janturjuṣṭaṃ vyavasyediha pīnasena"},{"type":"verse","number":"5","sanskrit":"तं चानिलश्लेष्मभवं विकारं ब्रूयात्प्रतिश्यायसमानलिङ्गम्","text":"taṃ cānilaśleṣmabhavaṃ vikāraṃ brūyātpratiśyāyasamānaliṅgam"},{"type":"verse","number":"6","sanskrit":"दोषैर्विदग्धैर्गलतालुमूले सन्दूषितो यस्य समीरणस्तु निरेति पूतिर्मुखनासिकाभ्यां तं पूतिनस्यं प्रवदन्ति रोगम्","text":"doṣairvidagdhairgalatālumūle sandūṣito yasya samīraṇastu nireti pūtirmukhanāsikābhyāṃ taṃ pūtinasyaṃ pravadanti rogam"},{"type":"verse","number":"7","sanskrit":"घ्राणाश्रितं पित्तमरूषि कुर्याद्यस्मिन्विकारे बलवांश्च पाकः तं नासिकापाकमिति व्यवस्येद्विक्लेदकोथावथवाऽपि यत्र","text":"ghrāṇāśritaṃ pittamarūṣi kuryādyasminvikāre balavāṃśca pākaḥ taṃ nāsikāpākamiti vyavasyedvikledakothāvathavā'pi yatra"},{"type":"verse","number":"8","sanskrit":"दोषैर्विदग्धैरथवाऽपि जन्तोर्ललाटदेशेऽभिहतस्य तैस्तैः नासा स्रवेत्पूयमसृग्विमिश्रं तं पूयरक्तं प्रवदन्ति रोगम्","text":"doṣairvidagdhairathavā'pi jantorlalāṭadeśe'bhihatasya taistaiḥ nāsā sravetpūyamasṛgvimiśraṃ taṃ pūyaraktaṃ pravadanti rogam"},{"type":"verse","number":"9","sanskrit":"घ्राणाश्रिते मर्मणि सम्प्रदुष्टो यस्यानिलो नासिकया निरेति कफानुयातो बहुशोऽतिशब्दस्तं रोगमाहुः क्षवथुं गदज्ञाः","text":"ghrāṇāśrite marmaṇi sampraduṣṭo yasyānilo nāsikayā nireti kaphānuyāto bahuśo'tiśabdastaṃ rogamāhuḥ kṣavathuṃ gadajñāḥ"},{"type":"verse","number":"10","sanskrit":"तीक्ष्णोपयोगादतिजिघ्रतो वा भावान्कटूनर्कनिरीक्षणाद्वा सूत्रादिभिर्वा तरुणास्थिमर्मण्युद्घर्षतेऽन्य क्षवथुर्निरेति","text":"tīkṣṇopayogādatijighrato vā bhāvānkaṭūnarkanirīkṣaṇādvā sūtrādibhirvā taruṇāsthimarmaṇyudgharṣate'nya kṣavathurnireti"},{"type":"verse","number":"11","sanskrit":"प्रभ्रश्यते नासिकया तु यस्य सान्द्रो विदग्धो लवणः कफस्तु प्राक्सञ्चितो मूर्धनि पित्ततप्ते तं भ्रंशथुं व्याधिमुदाहारन्ति","text":"prabhraśyate nāsikayā tu yasya sāndro vidagdho lavaṇaḥ kaphastu prāksañcito mūrdhani pittatapte taṃ bhraṃśathuṃ vyādhimudāhāranti"},{"type":"verse","number":"12","sanskrit":"घ्राणे भृशं दाहसमन्विते तु विनिःसरेद् धूम इवेह वायुः नासा प्रदीप्तेव च यस्य जन्तोर्व्याधिन्तु तं दीप्तिमुदाहरन्ति","text":"ghrāṇe bhṛśaṃ dāhasamanvite tu viniḥsared dhūma iveha vāyuḥ nāsā pradīpteva ca yasya jantorvyādhintu taṃ dīptimudāharanti"},{"type":"verse","number":"13","sanskrit":"उच्छ्वासमार्गन्तु कफः सवातो रुन्ध्यात्प्रतीनाहमुदाहरेत्तम्","text":"ucchvāsamārgantu kaphaḥ savāto rundhyātpratīnāhamudāharettam"},{"type":"verse","number":"14","sanskrit":"घ्राणाद्घनः पीतसितस्तनुर्वा दोषः स्रवेत्स्रावमुदाहरेत्तम्","text":"ghrāṇādghanaḥ pītasitastanurvā doṣaḥ sravetsrāvamudāharettam"},{"type":"verse","number":"15","sanskrit":"घ्राणाश्रिते श्लेष्मणि मारुतेन पित्तेन गाढं परिशोषिते च कृच्छ्राच्छ्वसित्यूर्ध्वमधश्च जन्तुर्यस्मिन्स नासापरिशोष उक्तः","text":"ghrāṇāśrite śleṣmaṇi mārutena pittena gāḍhaṃ pariśoṣite ca kṛcchrācchvasityūrdhvamadhaśca janturyasminsa nāsāpariśoṣa uktaḥ"},{"type":"verse","number":"16","sanskrit":"सन्धारणाजीर्णरसोऽतिभाष्यक्रोधर्त्तुवैषम्यशिरोऽभितापैः सञ्जागरातिस्वपनाम्बुशीतावश्यायकैर्मैथुनवाष्पसेकैः संस्त्यानदोषे शिरसि प्रवृद्धो वायुः प्रतिश्यायमुदीरयेत्तु","text":"sandhāraṇājīrṇaraso'tibhāṣyakrodharttuvaiṣamyaśiro'bhitāpaiḥ sañjāgarātisvapanāmbuśītāvaśyāyakairmaithunavāṣpasekaiḥ saṃstyānadoṣe śirasi pravṛddho vāyuḥ pratiśyāyamudīrayettu"},{"type":"verse","number":"17","sanskrit":"चयं गता मूर्द्धनि मारुतादयः पृथक्समस्ताश्च तथैव शोणितम् प्रकुप्यमाणा विविधैः प्रकोपणैस्ततः प्रतिश्यायकरा भवन्ति हि","text":"cayaṃ gatā mūrddhani mārutādayaḥ pṛthaksamastāśca tathaiva śoṇitam prakupyamāṇā vividhaiḥ prakopaṇaistataḥ pratiśyāyakarā bhavanti hi"},{"type":"verse","number":"18","sanskrit":"क्षवप्रवृत्तिः शिरसोऽभिपूर्णता स्तम्भोऽङ्गमर्दः परिहृष्टरोमता उपद्र वाश्चाप्यपरे पृथग्विधा नृणां प्रतिश्यायपुरःसराः स्मृताः","text":"kṣavapravṛttiḥ śiraso'bhipūrṇatā stambho'ṅgamardaḥ parihṛṣṭaromatā upadra vāścāpyapare pṛthagvidhā nṛṇāṃ pratiśyāyapuraḥsarāḥ smṛtāḥ"},{"type":"verse","number":"19","sanskrit":"आनद्धाऽपिहिता नासा तनुस्रावप्रसेकिनी गलताल्वोष्टशोषश्च निस्तोदः शंङ्खयोस्तथा क्षवप्रवृत्तिरत्यर्थं वक्त्रवैरस्यमेव च भवेत्स्वरोपघातश्च प्रतिश्यायेऽनिलात्मके","text":"ānaddhā'pihitā nāsā tanusrāvaprasekinī galatālvoṣṭaśoṣaśca nistodaḥ śaṃṅkhayostathā kṣavapravṛttiratyarthaṃ vaktravairasyameva ca bhavetsvaropaghātaśca pratiśyāye'nilātmake"},{"type":"verse","number":"20","sanskrit":"उष्णः सपीतकः स्रावो घ्राणात्स्रवति पैत्तिके कृशोऽतिपाण्डुः सन्तप्तो भवेदुष्णाभिपीडितः","text":"uṣṇaḥ sapītakaḥ srāvo ghrāṇātsravati paittike kṛśo'tipāṇḍuḥ santapto bhaveduṣṇābhipīḍitaḥ"},{"type":"verse","number":"21","sanskrit":"घ्राणात्कफकृते श्वेतः कफः शीतः स्रवेद् बहुः","text":"ghrāṇātkaphakṛte śvetaḥ kaphaḥ śītaḥ sraved bahuḥ"},{"type":"verse","number":"22","sanskrit":"शुक्लावभासः शूनाक्षो भवेद् गुरुशिरा नरः गलताल्वोष्ठशिरसां कण्डूभिरतिपीडितः","text":"śuklāvabhāsaḥ śūnākṣo bhaved guruśirā naraḥ galatālvoṣṭhaśirasāṃ kaṇḍūbhiratipīḍitaḥ"},{"type":"verse","number":"23","sanskrit":"भूत्वा भूत्वा प्रतिश्यायो योऽकस्मात्सन्निवर्त्तते सम्पक्वो वाऽप्यपक्वो वा स च सर्वभवः स्मृतः","text":"bhūtvā bhūtvā pratiśyāyo yo'kasmātsannivarttate sampakvo vā'pyapakvo vā sa ca sarvabhavaḥ smṛtaḥ"},{"type":"verse","number":"24","sanskrit":"प्रक्लिद्यते मुहुर्नासा पुनश्च परिशुष्यति पुनरानह्यते वाऽपि पुनर्विव्रियते तथा","text":"praklidyate muhurnāsā punaśca pariśuṣyati punarānahyate vā'pi punarvivriyate tathā"},{"type":"verse","number":"25","sanskrit":"निश्वासो वाऽपि दुर्गन्धो नरो गन्धान्न वेत्ति च एवं दुष्टं प्रतिश्यायं जानीयात्कृच्छ्रसाधनम्","text":"niśvāso vā'pi durgandho naro gandhānna vetti ca evaṃ duṣṭaṃ pratiśyāyaṃ jānīyātkṛcchrasādhanam"},{"type":"verse","number":"26","sanskrit":"रक्तजे तु प्रतिश्याये रक्तस्रावः प्रवर्त्तते पित्तप्रतिश्यायकृतैर्लिङ्गैश्चापि समन्वितः","text":"raktaje tu pratiśyāye raktasrāvaḥ pravarttate pittapratiśyāyakṛtairliṅgaiścāpi samanvitaḥ"},{"type":"verse","number":"27","sanskrit":"ताम्राक्षश्च भवेज्जन्तुरुरोघातप्रपीडितः दुर्गन्धोच्छ्वासवक्त्रश्च गन्धानपि न वेत्ति सः","text":"tāmrākṣaśca bhavejjantururoghātaprapīḍitaḥ durgandhocchvāsavaktraśca gandhānapi na vetti saḥ"},{"type":"verse","number":"28","sanskrit":"सर्व एव प्रतिश्याया नरस्याप्रतिकारिणः दुष्टतां यान्ति कालेन तदाऽसाध्या भवन्ति च","text":"sarva eva pratiśyāyā narasyāpratikāriṇaḥ duṣṭatāṃ yānti kālena tadā'sādhyā bhavanti ca"},{"type":"verse","number":"29","sanskrit":"मूर्च्छन्ति कृमयश्चात्र श्वेताः स्निग्धास्तथाऽणवः कृमिजन्यशिरोरोगैस्तुल्यं तेनात्र लक्षणम्","text":"mūrcchanti kṛmayaścātra śvetāḥ snigdhāstathā'ṇavaḥ kṛmijanyaśirorogaistulyaṃ tenātra lakṣaṇam"},{"type":"verse","number":"30","sanskrit":"बाधिर्यमान्ध्यमघ्रत्वं घोरांश्च नयनामयान् शोषाग्निमान्द्यकासांश्च वृद्धाः कुर्वन्ति पीनसाः","text":"bādhiryamāndhyamaghratvaṃ ghorāṃśca nayanāmayān śoṣāgnimāndyakāsāṃśca vṛddhāḥ kurvanti pīnasāḥ"},{"type":"verse","number":"31","sanskrit":"अर्बुदं सप्तधा शोथाश्चत्वारोऽशश्चतुर्विधम् चतुर्विधं रक्तपित्तमुक्तं घ्राणेऽपि तद्विदुः","text":"arbudaṃ saptadhā śothāścatvāro'śaścaturvidham caturvidhaṃ raktapittamuktaṃ ghrāṇe'pi tadviduḥ"},{"type":"verse","number":"32","sanskrit":"शिरोगुरुत्वमरुचिर्नासास्रावस्तनुः स्वरः क्षामःष्ठीवति चाभीक्ष्णमामपीनसलक्षणम्","text":"śirogurutvamarucirnāsāsrāvastanuḥ svaraḥ kṣāmaḥṣṭhīvati cābhīkṣṇamāmapīnasalakṣaṇam"},{"type":"verse","number":"33","sanskrit":"आमालिङ्गान्वितः श्लेष्मा घनः खेषु निमज्जति स्वरवर्णविशुद्धिश्च पक्वपीनसलक्षणम्","text":"āmāliṅgānvitaḥ śleṣmā ghanaḥ kheṣu nimajjati svaravarṇaviśuddhiśca pakvapīnasalakṣaṇam"},{"type":"verse","number":"34","sanskrit":"सर्वेषु सर्वकालं पीनसरोगेषु जातमात्रेषु मरिचं गुडेन दध्ना भुञ्जीत नरः सुखं लभते","text":"sarveṣu sarvakālaṃ pīnasarogeṣu jātamātreṣu maricaṃ guḍena dadhnā bhuñjīta naraḥ sukhaṃ labhate"},{"type":"verse","number":"35","sanskrit":"कट्फलं पौष्करं शृङ्गी व्योषं यासश्च कारवी एषांचूर्णं कषायं वा दद्यादार्द्र कजैः रसैः","text":"kaṭphalaṃ pauṣkaraṃ śṛṅgī vyoṣaṃ yāsaśca kāravī eṣāṃcūrṇaṃ kaṣāyaṃ vā dadyādārdra kajaiḥ rasaiḥ"},{"type":"verse","number":"36","sanskrit":"पीनसे स्वरभेदे च तमके च हलीमके सन्निपाते कफे कासे ज्वरे श्वासे च शस्यते","text":"pīnase svarabhede ca tamake ca halīmake sannipāte kaphe kāse jvare śvāse ca śasyate"},{"type":"verse","number":"37","sanskrit":"कलिङ्गहिङ्गुमरिचलाक्षासुरसकट्फलैः कुष्ठोग्राशिग्रुजन्तुघ्नैरवपीडः प्रशस्यते","text":"kaliṅgahiṅgumaricalākṣāsurasakaṭphalaiḥ kuṣṭhogrāśigrujantughnairavapīḍaḥ praśasyate"},{"type":"verse","number":"38","sanskrit":"व्योषचित्रकतालीसतिन्तिडीकाम्लवेतसम् सचव्याजाजितुल्यांशमेलात्वक्पत्रपादिकम्","text":"vyoṣacitrakatālīsatintiḍīkāmlavetasam sacavyājājitulyāṃśamelātvakpatrapādikam"},{"type":"verse","number":"39","sanskrit":"व्योषादिकमिदं चूर्णं पुराणगुडमिश्रितम् पीनसश्वासकासघ्नं रुचिस्वरकरं परम्","text":"vyoṣādikamidaṃ cūrṇaṃ purāṇaguḍamiśritam pīnasaśvāsakāsaghnaṃ rucisvarakaraṃ param"},{"type":"verse","number":"40","sanskrit":"व्याघ्रीदन्तीवचाशिग्रुसुरसाव्योषसिन्धुजैः सिद्धं तैलं नासि क्षिप्तं पूतिनासागदापहम्","text":"vyāghrīdantīvacāśigrusurasāvyoṣasindhujaiḥ siddhaṃ tailaṃ nāsi kṣiptaṃ pūtināsāgadāpaham"},{"type":"verse","number":"41","sanskrit":"शिग्रुसिंहीनिकुम्भानां बीजैः सव्योषसैन्धवैः बिल्वपत्ररसैः सिद्धं तैलं स्यात्पूतिनस्यनुत्","text":"śigrusiṃhīnikumbhānāṃ bījaiḥ savyoṣasaindhavaiḥ bilvapatrarasaiḥ siddhaṃ tailaṃ syātpūtinasyanut"},{"type":"verse","number":"42","sanskrit":"घृतगुग्गुलुमिश्रस्य सिक्थकस्य प्रयत्नतः धूमं क्षवथुरोगघ्नं भ्रंशथुघ्नञ्च निर्दिशेत्","text":"ghṛtaguggulumiśrasya sikthakasya prayatnataḥ dhūmaṃ kṣavathurogaghnaṃ bhraṃśathughnañca nirdiśet"},{"type":"verse","number":"43","sanskrit":"शुण्ठीकुष्ठकणाबिल्वद्रा क्षाकल्ककषायवत् तैलं पक्वमथाज्यं वा नस्यात्क्षवथुनाशनम्","text":"śuṇṭhīkuṣṭhakaṇābilvadrā kṣākalkakaṣāyavat tailaṃ pakvamathājyaṃ vā nasyātkṣavathunāśanam"},{"type":"verse","number":"44","sanskrit":"नस्यं हितं निम्बरसाञ्जनाभ्यां दीप्ते शिरः स्वेदनमल्पशस्तु नस्ये कृते क्षीरजलावसेकाञ्छ्वसन्ति भुञ्जीत च मुद्गयूषैः","text":"nasyaṃ hitaṃ nimbarasāñjanābhyāṃ dīpte śiraḥ svedanamalpaśastu nasye kṛte kṣīrajalāvasekāñchvasanti bhuñjīta ca mudgayūṣaiḥ"},{"type":"verse","number":"45","sanskrit":"नासास्रावे घ्राणयोश्चूर्णमुक्तं नाड्या देयं येऽवपीडाश्च पथ्याः तीक्ष्णान्धूमान्देवदार्वग्निकाभ्यां मांसं त्वाजं पथ्यमत्रादिशन्ति","text":"nāsāsrāve ghrāṇayoścūrṇamuktaṃ nāḍyā deyaṃ ye'vapīḍāśca pathyāḥ tīkṣṇāndhūmāndevadārvagnikābhyāṃ māṃsaṃ tvājaṃ pathyamatrādiśanti"},{"type":"verse","number":"46","sanskrit":"प्रतिश्यायेषु सर्वेषु गृहं वातविवर्जितम् वस्त्रेण गुरुणा तेन शिरसो वेष्टनं हितम्","text":"pratiśyāyeṣu sarveṣu gṛhaṃ vātavivarjitam vastreṇa guruṇā tena śiraso veṣṭanaṃ hitam"},{"type":"verse","number":"47","sanskrit":"विडङ्गं सैन्धवं हिङ्गु गुग्गुलुः समनःशिलः बचैतच्चूर्णमाघ्रातं प्रतिश्यायं विनाशयेत्","text":"viḍaṅgaṃ saindhavaṃ hiṅgu gugguluḥ samanaḥśilaḥ bacaitaccūrṇamāghrātaṃ pratiśyāyaṃ vināśayet"},{"type":"verse","number":"48","sanskrit":"घृततैलसमायुक्तं शक्तुधूमं पिबेन्नरः सधूमः त्यात्प्रतिश्यायकासहिक्काहरः परः","text":"ghṛtatailasamāyuktaṃ śaktudhūmaṃ pibennaraḥ sadhūmaḥ tyātpratiśyāyakāsahikkāharaḥ paraḥ"},{"type":"verse","number":"49","sanskrit":"प्रतिश्याये पिबेद्धूमं सर्वगन्धसमायुतम् चातुर्जातकचूर्णं वा घ्रेयं वा कृष्णजीरकम्","text":"pratiśyāye pibeddhūmaṃ sarvagandhasamāyutam cāturjātakacūrṇaṃ vā ghreyaṃ vā kṛṣṇajīrakam"},{"type":"verse","number":"50","sanskrit":"पुटपक्वं जयापत्रं तैलंसैन्धवसंयुतम् प्रतिश्यायेषु सर्वेषु शीलितं परमौषधम्","text":"puṭapakvaṃ jayāpatraṃ tailaṃsaindhavasaṃyutam pratiśyāyeṣu sarveṣu śīlitaṃ paramauṣadham"},{"type":"verse","number":"51","sanskrit":"पिप्पल्यः शिग्रुबीजानि विडङ्गमरिचानि च अवपीडः प्रशस्तोऽय प्रतिश्यायनिवारणे","text":"pippalyaḥ śigrubījāni viḍaṅgamaricāni ca avapīḍaḥ praśasto'ya pratiśyāyanivāraṇe"},{"type":"verse","number":"52","sanskrit":"शिरसोऽभ्यञ्जनैः स्वेदैर्नस्यैर्मन्दोष्णभोजनैः वमनैर्घृतपानैश्च तान्यथास्वमुपाचरेत्","text":"śiraso'bhyañjanaiḥ svedairnasyairmandoṣṇabhojanaiḥ vamanairghṛtapānaiśca tānyathāsvamupācaret"},{"type":"verse","number":"53","sanskrit":"कृमिघ्ना ये क्रमाः प्रोक्तास्तान्वै कृमिषु योजयेत् नावनानि कृमिघ्नानि भेषजानि च बुद्धिमान्","text":"kṛmighnā ye kramāḥ proktāstānvai kṛmiṣu yojayet nāvanāni kṛmighnāni bheṣajāni ca buddhimān"},{"type":"verse","number":"54","sanskrit":"रक्तपित्तानि शोथांश्च तथाऽशास्यर्बुदानि च नासिकायां स्युरेतेषां स्वं स्वं कुर्याच्चिकित्सितम्","text":"raktapittāni śothāṃśca tathā'śāsyarbudāni ca nāsikāyāṃ syureteṣāṃ svaṃ svaṃ kuryāccikitsitam"},{"type":"verse","number":"55","sanskrit":"गृहधूमकणा दारुक्षारनक्ताह्वसैन्धवैः सिद्धं शिखरिबीजैश्च तैलं नासाऽशसां हितम्","text":"gṛhadhūmakaṇā dārukṣāranaktāhvasaindhavaiḥ siddhaṃ śikharibījaiśca tailaṃ nāsā'śasāṃ hitam"},{"type":"verse","number":"56","sanskrit":"इति पञ्चषष्टितमो नासारोगाधिकारः समाप्तः ६५","text":"iti pañcaṣaṣṭitamo nāsārogādhikāraḥ samāptaḥ 65"}]},{"sthana":"Уттаракханда","number":65,"lang":"sa","content":[{"type":"heading","heading":"Мукха — болезни рта"},{"type":"verse","number":"1","sanskrit":"ओष्ठौ च दन्तमूलानि दन्ता जिह्वा च तालु च गलो मुखादि सकलं सप्ताङ्गं मुखमुच्यते","text":"oṣṭhau ca dantamūlāni dantā jihvā ca tālu ca galo mukhādi sakalaṃ saptāṅgaṃ mukhamucyate"},{"type":"verse","number":"2","sanskrit":"स्युरष्टावोष्ठयोर्दन्तमूले तु दश षट् तथा दन्तेष्वष्टौ च जिह्वायां पञ्च स्युर्नव तालुनि","text":"syuraṣṭāvoṣṭhayordantamūle tu daśa ṣaṭ tathā danteṣvaṣṭau ca jihvāyāṃ pañca syurnava tāluni"},{"type":"verse","number":"3","sanskrit":"कण्ठे त्वष्टादश प्रोक्तास्त्रयः सर्वेषु च स्मृताः एवं मुखामयाः सर्वे सप्तषष्टिर्मता बुधैः","text":"kaṇṭhe tvaṣṭādaśa proktāstrayaḥ sarveṣu ca smṛtāḥ evaṃ mukhāmayāḥ sarve saptaṣaṣṭirmatā budhaiḥ"},{"type":"verse","number":"4","sanskrit":"आनूपपिशितक्षार दधिमाषादिसेवनात् मुखमध्ये गदान्कुर्युः क्रुद्धा दोषाः कफोत्तराः","text":"ānūpapiśitakṣāra dadhimāṣādisevanāt mukhamadhye gadānkuryuḥ kruddhā doṣāḥ kaphottarāḥ"},{"type":"verse","number":"5","sanskrit":"पृथग्दोषैः समस्तैश्च रक्तजो मांसजस्तथा मेदोजश्चाभिघातोत्थ एवमष्टौष्ठजा गदाः","text":"pṛthagdoṣaiḥ samastaiśca raktajo māṃsajastathā medojaścābhighātottha evamaṣṭauṣṭhajā gadāḥ"},{"type":"verse","number":"6","sanskrit":"कर्कशौ परुषौ स्तब्धौ संप्राप्तानिलवेदनौ दाल्येते परिपाट्येते ओष्ठौ मारुतकोपतः","text":"karkaśau paruṣau stabdhau saṃprāptānilavedanau dālyete paripāṭyete oṣṭhau mārutakopataḥ"},{"type":"verse","number":"7","sanskrit":"चीयते पिडकाभिस्तु सरुजाभिः समन्ततः सदाहपाकपिडकौ पीताभासौ च पित्ततः","text":"cīyate piḍakābhistu sarujābhiḥ samantataḥ sadāhapākapiḍakau pītābhāsau ca pittataḥ"},{"type":"verse","number":"8","sanskrit":"सवर्णाभिस्तु चीयेते पिडकाभिरवेदनौ कण्डूमन्तौ कफाच्छ्वेतौ पिच्छिलौ शीतलौ गुरु","text":"savarṇābhistu cīyete piḍakābhiravedanau kaṇḍūmantau kaphācchvetau picchilau śītalau guru"},{"type":"verse","number":"9","sanskrit":"सकृत्कृष्णौ सकृत्पीतौ सकृच्छ्वेतौ तथैव च सन्निपातेन विज्ञेयावनेकपिडकाऽन्वितौ","text":"sakṛtkṛṣṇau sakṛtpītau sakṛcchvetau tathaiva ca sannipātena vijñeyāvanekapiḍakā'nvitau"},{"type":"verse","number":"10","sanskrit":"खर्जूरफलवर्णाभिः पिडकाभिर्निपीडितौ रक्तोपसृष्टौ रुधिरं स्रवन्तौ शोणितप्रभौ","text":"kharjūraphalavarṇābhiḥ piḍakābhirnipīḍitau raktopasṛṣṭau rudhiraṃ sravantau śoṇitaprabhau"},{"type":"verse","number":"11","sanskrit":"मांसदुष्टौ गुरु स्थूलौ मांसपिण्डवदुद्गतौ जन्तवश्चात्र मूर्च्छन्ति नरस्योभयतो मुखात्","text":"māṃsaduṣṭau guru sthūlau māṃsapiṇḍavadudgatau jantavaścātra mūrcchanti narasyobhayato mukhāt"},{"type":"verse","number":"12","sanskrit":"सर्पिर्मण्डप्रतीकाशौ मेदसा कण्डुरौ मृदू स्वच्छस्फटिकसंकाशमास्रावं स्रवतो भृशम्","text":"sarpirmaṇḍapratīkāśau medasā kaṇḍurau mṛdū svacchasphaṭikasaṃkāśamāsrāvaṃ sravato bhṛśam"},{"type":"verse","number":"13","sanskrit":"क्षतजाभौ विदीर्येते पीड्येते चाभिघाततः मथितौ च समाख्यातावोष्ठौ कण्डूसमन्वितौ","text":"kṣatajābhau vidīryete pīḍyete cābhighātataḥ mathitau ca samākhyātāvoṣṭhau kaṇḍūsamanvitau"},{"type":"verse","number":"14","sanskrit":"गलदन्तमूलदशनच्छदेषु रोगाः कफास्रभूयिष्ठाः तस्मादेतेष्वसकृद्रुधिरं विस्रावयेदुष्णम्","text":"galadantamūladaśanacchadeṣu rogāḥ kaphāsrabhūyiṣṭhāḥ tasmādeteṣvasakṛdrudhiraṃ visrāvayeduṣṇam"},{"type":"verse","number":"15","sanskrit":"चतुर्विधेन स्नेहेन मधूच्छिष्टयुतेन च वातजेऽभ्यञ्जनं कुर्यान्नाडीस्वेदञ्च बुद्धिमान्","text":"caturvidhena snehena madhūcchiṣṭayutena ca vātaje'bhyañjanaṃ kuryānnāḍīsvedañca buddhimān"},{"type":"verse","number":"16","sanskrit":"वेधं शिराणां वमनं विरेकं तिक्तस्य पानं रसभोजनञ्च शीताः प्रदेहाः परिषेचनञ्च पित्तोपसृष्टेष्वधरेषु कुर्यात्","text":"vedhaṃ śirāṇāṃ vamanaṃ virekaṃ tiktasya pānaṃ rasabhojanañca śītāḥ pradehāḥ pariṣecanañca pittopasṛṣṭeṣvadhareṣu kuryāt"},{"type":"verse","number":"17","sanskrit":"शिरोविरेचनं धूमः स्वेदः कवल एव च हृते रक्ते प्रयोक्तव्यमोष्ठकोपे कफात्मके मेदोजे शोधिते स्विन्ने स्वेदिते कवलो हितः प्रियङ्गुत्रिफलालोघ्रं सक्षौद्रं प्रतिसारणम्","text":"śirovirecanaṃ dhūmaḥ svedaḥ kavala eva ca hṛte rakte prayoktavyamoṣṭhakope kaphātmake medoje śodhite svinne svedite kavalo hitaḥ priyaṅgutriphalāloghraṃ sakṣaudraṃ pratisāraṇam"},{"type":"verse","number":"18","sanskrit":"दन्तजिह्वामुखानां यच्चूर्णकल्कावलेहकः शनैर्घर्षणमङ्गुल्या तदुक्तं प्रतिसारणम्","text":"dantajihvāmukhānāṃ yaccūrṇakalkāvalehakaḥ śanairgharṣaṇamaṅgulyā taduktaṃ pratisāraṇam"},{"type":"verse","number":"19","sanskrit":"ओष्ठरोगेष्वशेषेषु दृष्ट्वा दोषमुपाचरेत् तेषु व्रणत्वं जातेषु व्रणवत्समुपाचरेत्","text":"oṣṭharogeṣvaśeṣeṣu dṛṣṭvā doṣamupācaret teṣu vraṇatvaṃ jāteṣu vraṇavatsamupācaret"},{"type":"verse","number":"20","sanskrit":"शीतादो गदितः पूर्वं दन्तपुप्पुटकस्तथा दन्तवेष्टः सौषिरश्च महासौषिर एव च","text":"śītādo gaditaḥ pūrvaṃ dantapuppuṭakastathā dantaveṣṭaḥ sauṣiraśca mahāsauṣira eva ca"},{"type":"verse","number":"21","sanskrit":"ततः परिदरः प्रोक्तस्ततस्तूपकुशः स्मृतः वैदर्भश्च ततः प्रोक्तः खल्लीवर्द्धन एव च","text":"tataḥ paridaraḥ proktastatastūpakuśaḥ smṛtaḥ vaidarbhaśca tataḥ proktaḥ khallīvarddhana eva ca"},{"type":"verse","number":"22","sanskrit":"अधिमांसकनामा च दन्तनाड्यश्च पञ्च च दन्तविद्र धिरप्यत्र दन्तवेष्टेषु षोडश","text":"adhimāṃsakanāmā ca dantanāḍyaśca pañca ca dantavidra dhirapyatra dantaveṣṭeṣu ṣoḍaśa"},{"type":"verse","number":"23","sanskrit":"शोणितं दन्तवेष्टेभ्यो यस्याकस्मात्प्रवर्त्तते दुर्गन्धीनि सकृष्णानि प्रक्लेदीनि मृदूनि च","text":"śoṇitaṃ dantaveṣṭebhyo yasyākasmātpravarttate durgandhīni sakṛṣṇāni prakledīni mṛdūni ca"},{"type":"verse","number":"24","sanskrit":"दन्तमांसानि शीर्यन्ते पचन्ति च परस्परम् शीतादो नाम स व्याधिः कफशोणितसम्भवः","text":"dantamāṃsāni śīryante pacanti ca parasparam śītādo nāma sa vyādhiḥ kaphaśoṇitasambhavaḥ"},{"type":"verse","number":"25","sanskrit":"दन्तयोस्त्रिषु वाऽप्यत्र श्वयथुर्जायते महान् दन्तपुप्पुटको नाम स व्याधिः कफरक्तजः","text":"dantayostriṣu vā'pyatra śvayathurjāyate mahān dantapuppuṭako nāma sa vyādhiḥ kapharaktajaḥ"},{"type":"verse","number":"26","sanskrit":"स्रवन्ति पूयं रुधिरं चला दन्ता भवन्ति च दन्तवेष्टः स विज्ञेयो दुष्टशोणितसम्भवः","text":"sravanti pūyaṃ rudhiraṃ calā dantā bhavanti ca dantaveṣṭaḥ sa vijñeyo duṣṭaśoṇitasambhavaḥ"},{"type":"verse","number":"27","sanskrit":"श्वयथुर्दन्तमूलेषु रुजावान्कफवातजः लालास्रावी च कण्डूरः स ज्ञेयः सौषिरो गदः","text":"śvayathurdantamūleṣu rujāvānkaphavātajaḥ lālāsrāvī ca kaṇḍūraḥ sa jñeyaḥ sauṣiro gadaḥ"},{"type":"verse","number":"28","sanskrit":"दन्ताश्चलन्ति वेष्टेभ्यस्तालु चाप्यवदीर्यते दन्तमांसानि पच्यन्ते मुखञ्च परिपच्यते यस्मिन्स सर्वजो व्याधिर्महासौषिरसंज्ञकः","text":"dantāścalanti veṣṭebhyastālu cāpyavadīryate dantamāṃsāni pacyante mukhañca paripacyate yasminsa sarvajo vyādhirmahāsauṣirasaṃjñakaḥ"},{"type":"verse","number":"29","sanskrit":"दन्तमांसानि शीर्यन्ते यस्मिन्ष्ठीवति चाप्यसृक् पित्तासृक्कफजो व्याधिर्ज्ञेयः परिदरो हि सः","text":"dantamāṃsāni śīryante yasminṣṭhīvati cāpyasṛk pittāsṛkkaphajo vyādhirjñeyaḥ paridaro hi saḥ"},{"type":"verse","number":"30","sanskrit":"वेष्टेषु दाहः पाकश्च ताभ्यां दन्ताश्चलन्ति च आघटिट्ताः प्रस्रवन्ति शोणितं मन्दवेदनम् आध्मायन्तेऽस्रुते रक्ते मुखं पूति च जायते यस्मिन्नुपकुशः स स्यात्पित्तरक्तसमुद्भवः","text":"veṣṭeṣu dāhaḥ pākaśca tābhyāṃ dantāścalanti ca āghaṭiṭtāḥ prasravanti śoṇitaṃ mandavedanam ādhmāyante'srute rakte mukhaṃ pūti ca jāyate yasminnupakuśaḥ sa syātpittaraktasamudbhavaḥ"},{"type":"verse","number":"31","sanskrit":"घृष्टेषु दन्तमूलेषु संरम्भो जायते महान् चलन्ति च रदा यस्मिन्स वैदर्भोऽभिघातजः","text":"ghṛṣṭeṣu dantamūleṣu saṃrambho jāyate mahān calanti ca radā yasminsa vaidarbho'bhighātajaḥ"},{"type":"verse","number":"32","sanskrit":"मारुतेनाधिको दन्तो जायते तीव्रवेदनः खल्लीवर्द्धनसंज्ञोऽसौ सञ्जाते रुक्प्रशाम्यति","text":"mārutenādhiko danto jāyate tīvravedanaḥ khallīvarddhanasaṃjño'sau sañjāte rukpraśāmyati"},{"type":"verse","number":"33","sanskrit":"हानव्ये पश्चिमे दन्ते महाशोथो महारुजः लालास्रावी कफकृतो विज्ञेयः सोऽधिमांसकः","text":"hānavye paścime dante mahāśotho mahārujaḥ lālāsrāvī kaphakṛto vijñeyaḥ so'dhimāṃsakaḥ"},{"type":"verse","number":"34","sanskrit":"दन्तमूलगता नाड्यः पञ्च ज्ञेया यथेरिताः","text":"dantamūlagatā nāḍyaḥ pañca jñeyā yatheritāḥ"},{"type":"verse","number":"35","sanskrit":"दन्तमांसमलैः सास्रैर्बाह्यान्तः श्वयथुर्महान् सदाहरुक् स्रवेद्भिन्नः पूयास्रं दन्तविद्र धिः","text":"dantamāṃsamalaiḥ sāsrairbāhyāntaḥ śvayathurmahān sadāharuk sravedbhinnaḥ pūyāsraṃ dantavidra dhiḥ"},{"type":"verse","number":"36","sanskrit":"शीतादे हृतरक्ते तु तोये नागरसर्षपान् निष्क्वाथ्य त्रिफलाञ्चापि कुर्याद्गण्डूषधारणम्","text":"śītāde hṛtarakte tu toye nāgarasarṣapān niṣkvāthya triphalāñcāpi kuryādgaṇḍūṣadhāraṇam"},{"type":"verse","number":"37","sanskrit":"कासीसलोध्रकृष्णा मनःशिला प्रियङ्गु तेजोह्वाः एषां चूर्णं मधुयुक्छीतादे पूतिमांसहरम्","text":"kāsīsalodhrakṛṣṇā manaḥśilā priyaṅgu tejohvāḥ eṣāṃ cūrṇaṃ madhuyukchītāde pūtimāṃsaharam"},{"type":"verse","number":"38","sanskrit":"तैलं घृतं वा वातघ्नं शीतादे सम्प्रशस्यते दन्तपुप्पुटके कार्यं तरुणे रक्तमोक्षणम्","text":"tailaṃ ghṛtaṃ vā vātaghnaṃ śītāde sampraśasyate dantapuppuṭake kāryaṃ taruṇe raktamokṣaṇam"},{"type":"verse","number":"39","sanskrit":"सपञ्चलवणक्षारः सक्षौद्रः प्रतिसारणम् शिरोविरेकश्च हितो नस्यं स्निग्धञ्च भोजनम्","text":"sapañcalavaṇakṣāraḥ sakṣaudraḥ pratisāraṇam śirovirekaśca hito nasyaṃ snigdhañca bhojanam"},{"type":"verse","number":"40","sanskrit":"विस्राविते दन्तवेष्टे व्रणन्तु प्रतिसारयेत् लोध्रपत्तङ्गमधुक लाक्षाचूर्णैर्मधुप्लुतैः","text":"visrāvite dantaveṣṭe vraṇantu pratisārayet lodhrapattaṅgamadhuka lākṣācūrṇairmadhuplutaiḥ"},{"type":"verse","number":"41","sanskrit":"गण्डूषे क्षीरिणो योज्याः सक्षौद्र घृतशर्कराः चलदन्तस्थिरकरं कार्यं बकुलचर्वणम्","text":"gaṇḍūṣe kṣīriṇo yojyāḥ sakṣaudra ghṛtaśarkarāḥ caladantasthirakaraṃ kāryaṃ bakulacarvaṇam"},{"type":"verse","number":"42","sanskrit":"भद्र मुस्ताऽभयाव्योषविडङ्गारिष्टपल्लवैः गोमूत्रपिष्टैर्गुटिकां छायाशुष्कां प्रकल्पयेत्","text":"bhadra mustā'bhayāvyoṣaviḍaṅgāriṣṭapallavaiḥ gomūtrapiṣṭairguṭikāṃ chāyāśuṣkāṃ prakalpayet"},{"type":"verse","number":"43","sanskrit":"तां निधाय मुखे स्वप्याच्चलदन्तातुरो नरः नातः परतरं किञ्चिच्चलदन्तस्य भेषजम्","text":"tāṃ nidhāya mukhe svapyāccaladantāturo naraḥ nātaḥ parataraṃ kiñciccaladantasya bheṣajam"},{"type":"verse","number":"44","sanskrit":"तुलावृतं नीलसहाचरन्तु द्रो णाम्भसा संश्रपयेद्यथावत् ततश्चतुर्भागरसे तु तैलं पचेच्छनैरर्द्धपलप्रमाणैः","text":"tulāvṛtaṃ nīlasahācarantu dro ṇāmbhasā saṃśrapayedyathāvat tataścaturbhāgarase tu tailaṃ pacecchanairarddhapalapramāṇaiḥ"},{"type":"verse","number":"45","sanskrit":"कल्कैरनन्ताखदिरेरिमेदजम्ब्वाम्रयष्टीमधुकोत्पलानाम् तत्तैलमाज्यञ्च धृतं मुखेन स्थैर्यं द्विजानां विदधाति सद्यः","text":"kalkairanantākhadirerimedajambvāmrayaṣṭīmadhukotpalānām tattailamājyañca dhṛtaṃ mukhena sthairyaṃ dvijānāṃ vidadhāti sadyaḥ"},{"type":"verse","number":"46","sanskrit":"सौषिरे हृतरक्ते तु लोध्रमुस्तारसाञ्जनैः सक्षौद्रैः शस्यते लेपो गण्डूषे क्षीरिणो हिताः","text":"sauṣire hṛtarakte tu lodhramustārasāñjanaiḥ sakṣaudraiḥ śasyate lepo gaṇḍūṣe kṣīriṇo hitāḥ"},{"type":"verse","number":"47","sanskrit":"क्रियां परिदरे कुर्याच्छीतादोक्तां विचक्षणः संशोध्योभयतः कार्यं शिरश्चोपकुशे तथा","text":"kriyāṃ paridare kuryācchītādoktāṃ vicakṣaṇaḥ saṃśodhyobhayataḥ kāryaṃ śiraścopakuśe tathā"},{"type":"verse","number":"48","sanskrit":"काष्ठोदुम्बरिकापत्रैर्व्रणं विस्रावयेद्भिषक् लवणैः क्षौद्र युक्तैश्च सव्योषैः प्रतिसारयेत्","text":"kāṣṭhodumbarikāpatrairvraṇaṃ visrāvayedbhiṣak lavaṇaiḥ kṣaudra yuktaiśca savyoṣaiḥ pratisārayet"},{"type":"verse","number":"49","sanskrit":"शास्त्रेणोद्धृत्य वैदर्भे दन्तमूलानि शोधयेत् ततः क्षीरं प्रयुञ्जीत क्रियाः सर्वाश्च शीतलाः","text":"śāstreṇoddhṛtya vaidarbhe dantamūlāni śodhayet tataḥ kṣīraṃ prayuñjīta kriyāḥ sarvāśca śītalāḥ"},{"type":"verse","number":"50","sanskrit":"उद्धृत्याधिकदन्तं तु ततोऽग्निमवचारयेत् कृमिदन्तकवच्चात्र विधिः कार्या विजानता","text":"uddhṛtyādhikadantaṃ tu tato'gnimavacārayet kṛmidantakavaccātra vidhiḥ kāryā vijānatā"},{"type":"verse","number":"51","sanskrit":"छित्वाऽधिमांसं सक्षौद्रै रेतैश्चूर्णैरुपाचरेत् वचातेजोवतीपाठास्वर्जिकायावशूकजैः","text":"chitvā'dhimāṃsaṃ sakṣaudrai retaiścūrṇairupācaret vacātejovatīpāṭhāsvarjikāyāvaśūkajaiḥ"},{"type":"verse","number":"52","sanskrit":"क्षौद्र द्वितीयाः पिप्पल्यः कवले चात्र कीर्त्तिताः पटोलनिम्बत्रिफलाकषायश्चात्र धावने","text":"kṣaudra dvitīyāḥ pippalyaḥ kavale cātra kīrttitāḥ paṭolanimbatriphalākaṣāyaścātra dhāvane"},{"type":"verse","number":"53","sanskrit":"नाडीव्रणहरं कर्म दन्तनाडीषु कारयेत् यद्दन्तमध्ये जायेत नाडीदन्तं तदुद्धरेत्","text":"nāḍīvraṇaharaṃ karma dantanāḍīṣu kārayet yaddantamadhye jāyeta nāḍīdantaṃ taduddharet"},{"type":"verse","number":"54","sanskrit":"छित्वा मांसानि शस्त्रेण यदि नोपरिजो भवेत् उद्धृत्य च दहेच्चापि क्षारेण ज्वलनेन वा","text":"chitvā māṃsāni śastreṇa yadi noparijo bhavet uddhṛtya ca daheccāpi kṣāreṇa jvalanena vā"},{"type":"verse","number":"55","sanskrit":"भिनत्त्युपेक्षिते दन्ते हनुमस्थिगतिर्ध्रुवम् समूलं दशनं तस्मादुद्धरेद्भग्नमस्थि च","text":"bhinattyupekṣite dante hanumasthigatirdhruvam samūlaṃ daśanaṃ tasmāduddharedbhagnamasthi ca"},{"type":"verse","number":"56","sanskrit":"उद्धृते तूत्तरे दन्ते शोणितं प्रस्रवेदति रक्ताभिषेकात्पूर्वोक्ता घोरा रोगा भवन्ति हि","text":"uddhṛte tūttare dante śoṇitaṃ prasravedati raktābhiṣekātpūrvoktā ghorā rogā bhavanti hi"},{"type":"verse","number":"57","sanskrit":"काणः सञ्जायते जन्तुरर्दितं तस्य जायते चलमप्युत्तरं दन्तमतो नैवोद्धरेद्भिषक् धावनं जातिमदनस्वादुकण्टकखादिरैः","text":"kāṇaḥ sañjāyate janturarditaṃ tasya jāyate calamapyuttaraṃ dantamato naivoddharedbhiṣak dhāvanaṃ jātimadanasvādukaṇṭakakhādiraiḥ"},{"type":"verse","number":"58","sanskrit":"कषायैर्जातिमदनकण्टकीस्वादुकण्टकैः","text":"kaṣāyairjātimadanakaṇṭakīsvādukaṇṭakaiḥ"},{"type":"verse","number":"59","sanskrit":"मञ्जिष्ठालोध्रखदिरयष्ट्याह्वैश्चापि यत्कृतम् तैलं यत्साधितं तत्तु हन्याद् दन्तगतां गतिम्","text":"mañjiṣṭhālodhrakhadirayaṣṭyāhvaiścāpi yatkṛtam tailaṃ yatsādhitaṃ tattu hanyād dantagatāṃ gatim"},{"type":"verse","number":"60","sanskrit":"विद्र ध्युक्तं विधिं युक्तं विदध्याद् दन्तविद्र धौ शस्त्रकर्म नरस्तत्र कुशलो नैव कारयेत्","text":"vidra dhyuktaṃ vidhiṃ yuktaṃ vidadhyād dantavidra dhau śastrakarma narastatra kuśalo naiva kārayet"},{"type":"verse","number":"61","sanskrit":"दालनः कथितः पूर्वं कृमिदन्तक एव च प्रोक्तो भञ्जनको दन्तहर्षो वै दन्तशर्करा","text":"dālanaḥ kathitaḥ pūrvaṃ kṛmidantaka eva ca prokto bhañjanako dantaharṣo vai dantaśarkarā"},{"type":"verse","number":"62","sanskrit":"कपालिकाऽत्र कथिता श्यावदन्तक एव च करालसंज्ञ इत्यष्टौ दन्तरोगाः प्रकीर्त्तिताः","text":"kapālikā'tra kathitā śyāvadantaka eva ca karālasaṃjña ityaṣṭau dantarogāḥ prakīrttitāḥ"},{"type":"verse","number":"63","sanskrit":"दीर्यमाणेष्विव रुजा यत्र दन्तेषु जायते दालनो नाम स व्याधिः सदागतिनिमित्तजः","text":"dīryamāṇeṣviva rujā yatra danteṣu jāyate dālano nāma sa vyādhiḥ sadāgatinimittajaḥ"},{"type":"verse","number":"64","sanskrit":"कृष्णच्छिद्र श्चलः स्रावी ससंरम्भो महारुजः अनिमित्तरुजो वातात्स ज्ञेयः कृमिदन्तकः","text":"kṛṣṇacchidra ścalaḥ srāvī sasaṃrambho mahārujaḥ animittarujo vātātsa jñeyaḥ kṛmidantakaḥ"},{"type":"verse","number":"65","sanskrit":"वक्त्रं वक्रं भवेद्यत्र दन्तभङ्गश्च जायते कफवातकृतो व्याधिः स भञ्जनकसंज्ञकः","text":"vaktraṃ vakraṃ bhavedyatra dantabhaṅgaśca jāyate kaphavātakṛto vyādhiḥ sa bhañjanakasaṃjñakaḥ"},{"type":"verse","number":"66","sanskrit":"शीतरूक्षप्रवाताम्लस्पर्शानामसहा द्विजाः तत्र स्युर्वातपित्ताभ्यां दन्तहर्षः स कीर्त्तितः","text":"śītarūkṣapravātāmlasparśānāmasahā dvijāḥ tatra syurvātapittābhyāṃ dantaharṣaḥ sa kīrttitaḥ"},{"type":"verse","number":"67","sanskrit":"मलो दन्तगतो यस्तु कफश्चानिलशोषितः शर्करेव खरस्पर्शा सा ज्ञेया दन्तशर्करा","text":"malo dantagato yastu kaphaścānilaśoṣitaḥ śarkareva kharasparśā sā jñeyā dantaśarkarā"},{"type":"verse","number":"68","sanskrit":"कपालेष्विव दीर्यत्सु दन्तेषु समलेषु च कपालिकेति विज्ञेया दन्तच्छिद् दन्तशर्करा","text":"kapāleṣviva dīryatsu danteṣu samaleṣu ca kapāliketi vijñeyā dantacchid dantaśarkarā"},{"type":"verse","number":"69","sanskrit":"योऽसृङ्मिश्रेण पित्तेन दग्धो दन्तस्त्वशेषतः श्यावतां नीलतां वापि गतः स श्यावदन्तकः","text":"yo'sṛṅmiśreṇa pittena dagdho dantastvaśeṣataḥ śyāvatāṃ nīlatāṃ vāpi gataḥ sa śyāvadantakaḥ"},{"type":"verse","number":"70","sanskrit":"शनैः शनैः प्रकुरुते यत्र दन्ताश्रितोऽनिलः करालान्विकटान्दन्तान्स करालो न सिद्ध्य्ति","text":"śanaiḥ śanaiḥ prakurute yatra dantāśrito'nilaḥ karālānvikaṭāndantānsa karālo na siddhyti"},{"type":"verse","number":"71","sanskrit":"अथ दन्तरोगचिकित्सा तैलं लाक्षारसं क्षारं पृथक्प्रस्थमितं पचेत् द्र व्यैः पलमितैरेतैः क्वाथैश्चापि चतुर्गुणैः","text":"atha dantarogacikitsā tailaṃ lākṣārasaṃ kṣāraṃ pṛthakprasthamitaṃ pacet dra vyaiḥ palamitairetaiḥ kvāthaiścāpi caturguṇaiḥ"},{"type":"verse","number":"72","sanskrit":"लोध्रकट्फल मञ्जिष्ठापद्मकेशरपद्मकैः चन्दनोत्पलयष्ट्याह्वैस्तत्तैलं वदने धृतम्","text":"lodhrakaṭphala mañjiṣṭhāpadmakeśarapadmakaiḥ candanotpalayaṣṭyāhvaistattailaṃ vadane dhṛtam"},{"type":"verse","number":"73","sanskrit":"दालनं दन्तचालं च दन्तमोक्षं कपालिकाम् शीतादं पूतिवक्त्रञ्च विरुचिं विरसास्यताम्","text":"dālanaṃ dantacālaṃ ca dantamokṣaṃ kapālikām śītādaṃ pūtivaktrañca viruciṃ virasāsyatām"},{"type":"verse","number":"74","sanskrit":"हन्यादाशु गदानेतान्कुर्याद् दन्तानपि स्थिरान् लाक्षादिकमिदं तैलं दन्तरोगेषु पूजितम्","text":"hanyādāśu gadānetānkuryād dantānapi sthirān lākṣādikamidaṃ tailaṃ dantarogeṣu pūjitam"},{"type":"verse","number":"75","sanskrit":"जयेद्विस्रावणैः स्विन्नमचलं कृमिदन्तकम् तथाऽवपीडवातघ्नः स्नेहगण्डूषधारणैः","text":"jayedvisrāvaṇaiḥ svinnamacalaṃ kṛmidantakam tathā'vapīḍavātaghnaḥ snehagaṇḍūṣadhāraṇaiḥ"},{"type":"verse","number":"76","sanskrit":"भद्र दार्वादिवर्षाभूलेपैः स्निग्धैश्च भोजनैः कृमिदन्तापहं कोष्णं हिङ्गु दन्तान्तरे स्थितम्","text":"bhadra dārvādivarṣābhūlepaiḥ snigdhaiśca bhojanaiḥ kṛmidantāpahaṃ koṣṇaṃ hiṅgu dantāntare sthitam"},{"type":"verse","number":"77","sanskrit":"बृहतीभूमिकदम्बपञ्चाङ्गुलकण्टकारिकाक्वाथः गण्डूषस्तैलयुतः कृमिदन्तकवेदनाशमनः","text":"bṛhatībhūmikadambapañcāṅgulakaṇṭakārikākvāthaḥ gaṇḍūṣastailayutaḥ kṛmidantakavedanāśamanaḥ"},{"type":"verse","number":"78","sanskrit":"नीलीवायसजङ्घाकटुतुम्बीमूलमेकैकम् सञ्चूर्ण्य दशनविधृतं दशनकृमिनाशनं प्राहुः","text":"nīlīvāyasajaṅghākaṭutumbīmūlamekaikam sañcūrṇya daśanavidhṛtaṃ daśanakṛmināśanaṃ prāhuḥ"},{"type":"verse","number":"79","sanskrit":"स्नेहानां कवलाः कोष्णाः सर्पिषस्त्रैवृतस्य च निर्यूहाश्चानिलघ्नानां दन्तहर्षप्रमर्दनाः","text":"snehānāṃ kavalāḥ koṣṇāḥ sarpiṣastraivṛtasya ca niryūhāścānilaghnānāṃ dantaharṣapramardanāḥ"},{"type":"verse","number":"80","sanskrit":"स्नैहिकोऽत्र हितो धूमो नस्यं स्नैहिकमेव च पेया रसा यवाग्वश्च क्षीरसन्तानिकाघृतम् शिरोवस्तिहितश्चापि क्रमो यश्चानिलापहः","text":"snaihiko'tra hito dhūmo nasyaṃ snaihikameva ca peyā rasā yavāgvaśca kṣīrasantānikāghṛtam śirovastihitaścāpi kramo yaścānilāpahaḥ"},{"type":"verse","number":"81","sanskrit":"अच्छिन्दन्दन्तमूलानि शर्करामुद्धरेद्भिषक् लाक्षाचूर्णैर्मधुयुतैस्ततस्तां प्रतिसारयेत् दन्तहर्षक्रियां चात्र कुर्यान्निरवशेषतः कपालिका कृच्छ्रतमा तत्राप्येषा क्रिया मता","text":"acchindandantamūlāni śarkarāmuddharedbhiṣak lākṣācūrṇairmadhuyutaistatastāṃ pratisārayet dantaharṣakriyāṃ cātra kuryānniravaśeṣataḥ kapālikā kṛcchratamā tatrāpyeṣā kriyā matā"},{"type":"verse","number":"82","sanskrit":"फलान्यम्लानि शीताम्बु रूक्षान्नं दन्तधावनम् तथाऽतिकठिनं भक्ष्यं दन्तरोगी न भक्षयेत्","text":"phalānyamlāni śītāmbu rūkṣānnaṃ dantadhāvanam tathā'tikaṭhinaṃ bhakṣyaṃ dantarogī na bhakṣayet"},{"type":"verse","number":"83","sanskrit":"वातजः पित्तजश्चापि कफजोऽलाससंज्ञकः उपजिह्विका च गदा जिह्वायां पञ्च कीर्त्तिताः","text":"vātajaḥ pittajaścāpi kaphajo'lāsasaṃjñakaḥ upajihvikā ca gadā jihvāyāṃ pañca kīrttitāḥ"},{"type":"verse","number":"84","sanskrit":"जिह्वाऽनिलेन स्फुटिता प्रसुप्ता भवेच्च शाकच्छदनप्रकाशा","text":"jihvā'nilena sphuṭitā prasuptā bhavecca śākacchadanaprakāśā"},{"type":"verse","number":"85","sanskrit":"पित्तात्सदाहैरुपचीयते च दीर्घैः सरक्तैरपि कण्टकैश्च","text":"pittātsadāhairupacīyate ca dīrghaiḥ saraktairapi kaṇṭakaiśca"},{"type":"verse","number":"86","sanskrit":"कफेन गुर्वी बहुला चिता च मांसोच्छ्रयैः शाल्मलिकण्टकाभैः","text":"kaphena gurvī bahulā citā ca māṃsocchrayaiḥ śālmalikaṇṭakābhaiḥ"},{"type":"verse","number":"87","sanskrit":"जिह्वातले यः श्वयथुः प्रगाढः सोऽलाससंज्ञः कफरक्तमूर्त्तिः जिह्वां स तु स्तम्भयति प्रवृद्धो मूले च जिह्वा भृशमेति पाकम्","text":"jihvātale yaḥ śvayathuḥ pragāḍhaḥ so'lāsasaṃjñaḥ kapharaktamūrttiḥ jihvāṃ sa tu stambhayati pravṛddho mūle ca jihvā bhṛśameti pākam"},{"type":"verse","number":"88","sanskrit":"जिह्वाऽग्ररूपः श्वयथुर्हि जिह्वामन्नुम्य जातः कफरक्तयोनिः प्रसेककण्डूपरिदाहयुक्तः प्रकथ्यतेऽसावुपजिह्विकेति","text":"jihvā'grarūpaḥ śvayathurhi jihvāmannumya jātaḥ kapharaktayoniḥ prasekakaṇḍūparidāhayuktaḥ prakathyate'sāvupajihviketi"},{"type":"verse","number":"89","sanskrit":"जिह्वागतविकाराणां शस्तं शोणितमोक्षणम् गुडूचीपिप्पलीनिम्बकवलः कटुभिः सुखः","text":"jihvāgatavikārāṇāṃ śastaṃ śoṇitamokṣaṇam guḍūcīpippalīnimbakavalaḥ kaṭubhiḥ sukhaḥ"},{"type":"verse","number":"90","sanskrit":"ओष्ठप्रकोपेऽनिलजे यदुक्तं प्राक्चिकित्सितम् कण्टकेष्वनिलोत्थेषु तत्कार्यं भिषजा खलु ९२ पित्तजे परिघृष्टे तु निःसृते दुष्टशोणिते प्रतिसारणगण्डूषनस्यञ्च मधुरं हितम्","text":"oṣṭhaprakope'nilaje yaduktaṃ prākcikitsitam kaṇṭakeṣvanilottheṣu tatkāryaṃ bhiṣajā khalu 92 pittaje parighṛṣṭe tu niḥsṛte duṣṭaśoṇite pratisāraṇagaṇḍūṣanasyañca madhuraṃ hitam"},{"type":"verse","number":"91","sanskrit":"कण्टकेषु कफोत्थेषु लिखितेष्वसृजः क्षये पिप्पल्यादिर्मधुयुतः कार्यस्तु प्रतिसारणे","text":"kaṇṭakeṣu kaphottheṣu likhiteṣvasṛjaḥ kṣaye pippalyādirmadhuyutaḥ kāryastu pratisāraṇe"},{"type":"verse","number":"92","sanskrit":"उपजिह्वां तु संलिख्य क्षारेण प्रतिसारयेत् शिरोविरेकगण्डूषधूमैश्चैनामुपाचरेत्","text":"upajihvāṃ tu saṃlikhya kṣāreṇa pratisārayet śirovirekagaṇḍūṣadhūmaiścaināmupācaret"},{"type":"verse","number":"93","sanskrit":"व्योषक्षाराभयावह्नि चूर्णमेतत्प्रघर्षणम् उपजिह्वाप्रशान्त्यर्थमेभिस्तैलञ्च पाचयेत्","text":"vyoṣakṣārābhayāvahni cūrṇametatpragharṣaṇam upajihvāpraśāntyarthamebhistailañca pācayet"},{"type":"verse","number":"94","sanskrit":"गलशुण्ठी तुण्डिकेर्यभ्रूषः कच्छप एव च ताल्वर्बुदश्च कथितो मांससङ्घात एव च","text":"galaśuṇṭhī tuṇḍikeryabhrūṣaḥ kacchapa eva ca tālvarbudaśca kathito māṃsasaṅghāta eva ca"},{"type":"verse","number":"95","sanskrit":"तालुपुप्पुटनामा च तालुशोषस्तथैव च तालुपाकश्च कथितास्तालुरोगा अमी नव","text":"tālupuppuṭanāmā ca tāluśoṣastathaiva ca tālupākaśca kathitāstālurogā amī nava"},{"type":"verse","number":"96","sanskrit":"श्लेष्मासृग्भ्यांतालुमूलात्प्रवृद्धो दीर्घः शोथो ध्मातवस्तिप्रकाशः तृष्णाकासश्वासकृत्तं वदन्ति व्याधिं वैद्याः कण्ठशुण्डीति नाम्ना","text":"śleṣmāsṛgbhyāṃtālumūlātpravṛddho dīrghaḥ śotho dhmātavastiprakāśaḥ tṛṣṇākāsaśvāsakṛttaṃ vadanti vyādhiṃ vaidyāḥ kaṇṭhaśuṇḍīti nāmnā"},{"type":"verse","number":"97","sanskrit":"शोथः स्थूलस्तोददाहप्रपाकी श्लेष्मासृग्भ्यां कीर्त्तिता तुण्डिकेरी","text":"śothaḥ sthūlastodadāhaprapākī śleṣmāsṛgbhyāṃ kīrttitā tuṇḍikerī"},{"type":"verse","number":"98","sanskrit":"शोथः स्तब्धो लोहितः शोणितोत्थो ज्ञेयोऽभ्रूषः सज्वरस्तीव्ररुक्च","text":"śothaḥ stabdho lohitaḥ śoṇitottho jñeyo'bhrūṣaḥ sajvarastīvrarukca"},{"type":"verse","number":"99","sanskrit":"कूर्मोत्सन्नोऽवेदनोऽशीघ्रजन्मा रोगो ज्ञेयः कच्छपः श्लेष्मणः स्यात्","text":"kūrmotsanno'vedano'śīghrajanmā rogo jñeyaḥ kacchapaḥ śleṣmaṇaḥ syāt"},{"type":"verse","number":"100","sanskrit":"पद्माकारं तालुमध्ये तु शोथं विद्याद्र क्तादर्बुदं पित्तलिङ्गम्","text":"padmākāraṃ tālumadhye tu śothaṃ vidyādra ktādarbudaṃ pittaliṅgam"},{"type":"verse","number":"101","sanskrit":"दुष्टं मांसश्लेष्मणा नीरुजञ्च ताल्वन्तःस्थं मांससंघातमाहुः","text":"duṣṭaṃ māṃsaśleṣmaṇā nīrujañca tālvantaḥsthaṃ māṃsasaṃghātamāhuḥ"},{"type":"verse","number":"102","sanskrit":"नीरुक्स्थायी कोलमात्रः कफात्स्यान्मेदोयुक्तात् पुप्पुटस्तालुदेशे","text":"nīruksthāyī kolamātraḥ kaphātsyānmedoyuktāt puppuṭastāludeśe"},{"type":"verse","number":"103","sanskrit":"शोषोऽत्यर्थं दीर्यते वाऽपि तालु श्वासश्चोग्रस्तालुशोषोऽनिलाच्च","text":"śoṣo'tyarthaṃ dīryate vā'pi tālu śvāsaścograstāluśoṣo'nilācca"},{"type":"verse","number":"104","sanskrit":"पित्तं कुर्यात्पाकमत्यर्थघोरं तालुन्येवं तालुपाकं वदन्ति","text":"pittaṃ kuryātpākamatyarthaghoraṃ tālunyevaṃ tālupākaṃ vadanti"},{"type":"verse","number":"105","sanskrit":"कुष्ठोषणवचासिन्धुकणापाठाप्लवैः सह सक्षौद्रै र्भिषजा कार्यं गलशुण्डीप्रघर्षणम्","text":"kuṣṭhoṣaṇavacāsindhukaṇāpāṭhāplavaiḥ saha sakṣaudrai rbhiṣajā kāryaṃ galaśuṇḍīpragharṣaṇam"},{"type":"verse","number":"106","sanskrit":"अङ्गुष्ठाङ्गुलिसन्दंशेनाकृष्य गलशुण्डिकाम् छेदयेन्मण्डलाग्रेण जिह्वोपरि तु संस्थिताम्","text":"aṅguṣṭhāṅgulisandaṃśenākṛṣya galaśuṇḍikām chedayenmaṇḍalāgreṇa jihvopari tu saṃsthitām"},{"type":"verse","number":"107","sanskrit":"अत्यादानात्स्रवेद्र क्तं ततः स म्रियते नरः हीनच्छेदाद्भवेच्छोथो लालास्रावो भ्रमस्तथा तस्माद्वैद्यः प्रयत्नेन दृष्टकर्मा विशारदः गलशुण्डीं तु संच्छिद्य कुर्यात्प्राप्तमिमं क्रमम् पिप्पल्यतिविषाकुष्ठवचामरिचनागरैः क्षौद्र युक्तैः सलवणैस्ततस्तां प्रतिसारयेत् वचामतिविषापाठारास्नाकटुकरोहिणीः निक्वाथ्य पिचुमर्दञ्च कवलं तत्र कारयेत् तुण्डिकेर्यभ्रुषे कूर्मे सङ्घाते तालुपुप्पुटे एष एव विधिः कार्यो विशेषः शस्त्रकर्मणि","text":"atyādānātsravedra ktaṃ tataḥ sa mriyate naraḥ hīnacchedādbhavecchotho lālāsrāvo bhramastathā tasmādvaidyaḥ prayatnena dṛṣṭakarmā viśāradaḥ galaśuṇḍīṃ tu saṃcchidya kuryātprāptamimaṃ kramam pippalyativiṣākuṣṭhavacāmaricanāgaraiḥ kṣaudra yuktaiḥ salavaṇaistatastāṃ pratisārayet vacāmativiṣāpāṭhārāsnākaṭukarohiṇīḥ nikvāthya picumardañca kavalaṃ tatra kārayet tuṇḍikeryabhruṣe kūrme saṅghāte tālupuppuṭe eṣa eva vidhiḥ kāryo viśeṣaḥ śastrakarmaṇi"},{"type":"verse","number":"108","sanskrit":"तालुपाके तु कर्त्तव्यं विधानं पित्तनाशनम् स्नेहस्वेदौ तालुशोषे विधिश्चानिलनाशनः","text":"tālupāke tu karttavyaṃ vidhānaṃ pittanāśanam snehasvedau tāluśoṣe vidhiścānilanāśanaḥ"},{"type":"verse","number":"109","sanskrit":"रोहिणी पञ्चधा प्रोक्ता कण्ठशालूक एव च अधिजिह्वश्च वलयो बलासश्चैकवृन्दकः","text":"rohiṇī pañcadhā proktā kaṇṭhaśālūka eva ca adhijihvaśca valayo balāsaścaikavṛndakaḥ"},{"type":"verse","number":"110","sanskrit":"ततो वृन्दः शतघ्नी च गिलायुः कण्ठविद्र धिः गलौघश्च स्वरघ्नश्च मांसतानस्तथैव च","text":"tato vṛndaḥ śataghnī ca gilāyuḥ kaṇṭhavidra dhiḥ galaughaśca svaraghnaśca māṃsatānastathaiva ca"},{"type":"verse","number":"111","sanskrit":"विदारी कण्ठदेशे तु रोगा अष्टादश स्मृताः","text":"vidārī kaṇṭhadeśe tu rogā aṣṭādaśa smṛtāḥ"},{"type":"verse","number":"112","sanskrit":"गलेऽनिलः पित्तकफौ च मूर्च्छितौ प्रदूष्य मांसञ्च तथैव शोणितम् गलोपसंरोधकरैस्तथाङ्कुरैर्निहन्त्यसून्व्याधिरयं च रोहिणी","text":"gale'nilaḥ pittakaphau ca mūrcchitau pradūṣya māṃsañca tathaiva śoṇitam galopasaṃrodhakaraistathāṅkurairnihantyasūnvyādhirayaṃ ca rohiṇī"},{"type":"verse","number":"113","sanskrit":"जिह्वासमन्ताद् भृशवेदनास्तु मांसाङ्कुराः कण्ठनिरोधनाः स्युः सा रोहिणी वातकृता प्रदिष्टा वातात्मकोपद्र वगाढजुष्टा","text":"jihvāsamantād bhṛśavedanāstu māṃsāṅkurāḥ kaṇṭhanirodhanāḥ syuḥ sā rohiṇī vātakṛtā pradiṣṭā vātātmakopadra vagāḍhajuṣṭā"},{"type":"verse","number":"114","sanskrit":"क्षिप्रोद्गमा क्षिप्रविदाहपाका तीव्रज्वरा पित्तनिमित्तजाता","text":"kṣiprodgamā kṣipravidāhapākā tīvrajvarā pittanimittajātā"},{"type":"verse","number":"115","sanskrit":"स्रोतोनिरोधिन्यपि मन्दपाका गुर्वी स्थिरा सा कफसम्भवा तु","text":"srotonirodhinyapi mandapākā gurvī sthirā sā kaphasambhavā tu"},{"type":"verse","number":"116","sanskrit":"गम्भीरपाकिन्यनिवार्यवीर्या त्रिदोषलिङ्गा त्रिभवा भवेत्सा","text":"gambhīrapākinyanivāryavīryā tridoṣaliṅgā tribhavā bhavetsā"},{"type":"verse","number":"117","sanskrit":"स्फोटैश्चिता पित्तसमानलिङ्गा साध्या प्रदिष्टा रुधिरात्मिका तु","text":"sphoṭaiścitā pittasamānaliṅgā sādhyā pradiṣṭā rudhirātmikā tu"},{"type":"verse","number":"118","sanskrit":"सद्यस्त्रिदोषजा हन्ति त्र्यहात्कफसमुद्भवा पञ्चाहात्पित्तसम्भूता सप्ताहात्पवनोत्थिता","text":"sadyastridoṣajā hanti tryahātkaphasamudbhavā pañcāhātpittasambhūtā saptāhātpavanotthitā"},{"type":"verse","number":"119","sanskrit":"कोलास्थिगात्रः कफसम्भवो यो ग्रन्थिर्गले कण्टकशूकभूतः खरः स्थिरः शस्त्रनिपातसाध्यस्तत्कण्ठशालूकमिति ब्रुवन्ति","text":"kolāsthigātraḥ kaphasambhavo yo granthirgale kaṇṭakaśūkabhūtaḥ kharaḥ sthiraḥ śastranipātasādhyastatkaṇṭhaśālūkamiti bruvanti"},{"type":"verse","number":"120","sanskrit":"जिह्वाऽग्ररूपः श्वयथुः कफात्तु जिह्वोपरिष्टादसृजैव मिश्रात् ज्ञेयोऽधिजिह्वः खलु रोग एव विवर्जयेदागतपाकमेनम्","text":"jihvā'grarūpaḥ śvayathuḥ kaphāttu jihvopariṣṭādasṛjaiva miśrāt jñeyo'dhijihvaḥ khalu roga eva vivarjayedāgatapākamenam"},{"type":"verse","number":"121","sanskrit":"बलास एवागतमुन्नतञ्च शोथं करोत्यन्नगतिं निवार्य तं सर्वथैवाप्रतिवार्यमेव विवर्जनीयं वलयं वदन्ति","text":"balāsa evāgatamunnatañca śothaṃ karotyannagatiṃ nivārya taṃ sarvathaivāprativāryameva vivarjanīyaṃ valayaṃ vadanti"},{"type":"verse","number":"122","sanskrit":"गले तु शोथं कुरुतः प्रवृद्धौ श्लेष्मानिलौ श्वासरुजोपपन्नम् मर्मच्छिदं दुस्तरमेनमाहुर्बलाससंज्ञं भिषजो विकारम्","text":"gale tu śothaṃ kurutaḥ pravṛddhau śleṣmānilau śvāsarujopapannam marmacchidaṃ dustaramenamāhurbalāsasaṃjñaṃ bhiṣajo vikāram"},{"type":"verse","number":"123","sanskrit":"वृत्तोन्नतोऽन्त श्वयथुः सदाहः सकण्डुरोऽपाक्यमृदुर्गुरुश्च नाम्नैकवृन्दः परिकीर्त्तितोऽसौ व्याधिर्बलासक्षतजप्रसूतः","text":"vṛttonnato'nta śvayathuḥ sadāhaḥ sakaṇḍuro'pākyamṛdurguruśca nāmnaikavṛndaḥ parikīrttito'sau vyādhirbalāsakṣatajaprasūtaḥ"},{"type":"verse","number":"124","sanskrit":"समुन्नतं वृत्तममन्ददाहं तीव्रज्वरं वृन्दमुदाहरन्ति तं चापि पित्तक्षतजप्रकोपाद्विद्यात्सतोदं पवनात्मकं तु","text":"samunnataṃ vṛttamamandadāhaṃ tīvrajvaraṃ vṛndamudāharanti taṃ cāpi pittakṣatajaprakopādvidyātsatodaṃ pavanātmakaṃ tu"},{"type":"verse","number":"125","sanskrit":"वर्त्तिर्घना कण्ठनिरोधिनी तु चिताऽतिमात्रं पिशितप्ररोहैः अनेकरुक्प्राणहरी त्रिदोषाज्ज्ञेया शतघ्नीसदृशी शतघ्नी","text":"varttirghanā kaṇṭhanirodhinī tu citā'timātraṃ piśitaprarohaiḥ anekarukprāṇaharī tridoṣājjñeyā śataghnīsadṛśī śataghnī"},{"type":"verse","number":"126","sanskrit":"ग्रन्थिर्गले त्वामलकास्थिमात्रः स्थिरोऽल्परुक्स्यात्कफरक्तमूर्त्तिः संलक्ष्यते सक्तमिवाशितञ्च स शस्त्रसाध्यस्तु गिलायुसंज्ञः","text":"granthirgale tvāmalakāsthimātraḥ sthiro'lparuksyātkapharaktamūrttiḥ saṃlakṣyate saktamivāśitañca sa śastrasādhyastu gilāyusaṃjñaḥ"},{"type":"verse","number":"127","sanskrit":"सर्वं गलं व्याप्य समुत्थितो यः शोथो रुजः सन्ति च यत्र सर्वाः स सर्वदोषैर्गलविद्र धिस्तु तस्यैव तुल्यः खलु सर्वजस्य","text":"sarvaṃ galaṃ vyāpya samutthito yaḥ śotho rujaḥ santi ca yatra sarvāḥ sa sarvadoṣairgalavidra dhistu tasyaiva tulyaḥ khalu sarvajasya"},{"type":"verse","number":"128","sanskrit":"शोथो महान्यस्तु गलावरोधी तीव्रज्वरो वायुगतेर्निहन्ता कफेन जातो रुधिरान्वितेन गले गलौधः परिकीर्त्तितोऽसौ","text":"śotho mahānyastu galāvarodhī tīvrajvaro vāyugaternihantā kaphena jāto rudhirānvitena gale galaudhaḥ parikīrttito'sau"},{"type":"verse","number":"129","sanskrit":"यस्ताम्यमानः श्वसिति प्रसक्तं भिन्नस्वरः शुष्कविमुक्तकण्ठः कफोपदुष्टेष्वनिलायनेषु ज्ञेयः स रोगः श्वसनात्स्वरघ्नः","text":"yastāmyamānaḥ śvasiti prasaktaṃ bhinnasvaraḥ śuṣkavimuktakaṇṭhaḥ kaphopaduṣṭeṣvanilāyaneṣu jñeyaḥ sa rogaḥ śvasanātsvaraghnaḥ"},{"type":"verse","number":"130","sanskrit":"प्रतानवान्यः श्वयथुः सुकष्टो गलोपरोधं कुरुते क्रमेण स मांसतानः कथितोऽवलम्बी प्राणप्रणुत्सर्वकृतो विकारः","text":"pratānavānyaḥ śvayathuḥ sukaṣṭo galoparodhaṃ kurute krameṇa sa māṃsatānaḥ kathito'valambī prāṇapraṇutsarvakṛto vikāraḥ"},{"type":"verse","number":"131","sanskrit":"सदाहतोदं श्वयथुं सताम्रमन्तर्गले पूतिविशीर्णमांसम् पित्तेन विद्याद्वदने विदारीं पार्श्वे विशेषात्स तु येन शेते","text":"sadāhatodaṃ śvayathuṃ satāmramantargale pūtiviśīrṇamāṃsam pittena vidyādvadane vidārīṃ pārśve viśeṣātsa tu yena śete"},{"type":"verse","number":"132","sanskrit":"रोहिणीनान्तु साध्यानां हितं शोणितमोचनम् वमनं धूमपानञ्च गण्डूषो नस्यकर्म च वातजान्तु हृते रक्ते लवणैः प्रतिसारयेत् सुखोष्णान्स्नेहगण्डूषान्धारयेच्चाप्यभीक्ष्णशः विस्राव्य पित्तसम्भूतां सिताक्षौद्र प्रियङ्गुभिः घर्षयेत्कवलो द्रा क्षापरुषैः क्वथितो हितः आगारधूमकटुकैः कफजां प्रतिसारयेत्","text":"rohiṇīnāntu sādhyānāṃ hitaṃ śoṇitamocanam vamanaṃ dhūmapānañca gaṇḍūṣo nasyakarma ca vātajāntu hṛte rakte lavaṇaiḥ pratisārayet sukhoṣṇānsnehagaṇḍūṣāndhārayeccāpyabhīkṣṇaśaḥ visrāvya pittasambhūtāṃ sitākṣaudra priyaṅgubhiḥ gharṣayetkavalo drā kṣāparuṣaiḥ kvathito hitaḥ āgāradhūmakaṭukaiḥ kaphajāṃ pratisārayet"},{"type":"verse","number":"133","sanskrit":"श्वेताविडङ्गदन्तीषु तैलं सिद्धं ससैन्धवम् नस्यकर्मणि दातव्यं कवलञ्च कफोच्छ्रये","text":"śvetāviḍaṅgadantīṣu tailaṃ siddhaṃ sasaindhavam nasyakarmaṇi dātavyaṃ kavalañca kaphocchraye"},{"type":"verse","number":"134","sanskrit":"पित्तवत्साधयेद्वैद्यो रोहिणीं रक्तसम्भवाम् विस्राव्य कण्ठशालूकं साधयेत्तुण्डिकेरिवत्","text":"pittavatsādhayedvaidyo rohiṇīṃ raktasambhavām visrāvya kaṇṭhaśālūkaṃ sādhayettuṇḍikerivat"},{"type":"verse","number":"135","sanskrit":"एककालं यवान्नञ्च भुञ्जीत स्निग्धमल्पशः उपजिह्वकवच्चापि साधयेदधिजिह्वकम्","text":"ekakālaṃ yavānnañca bhuñjīta snigdhamalpaśaḥ upajihvakavaccāpi sādhayedadhijihvakam"},{"type":"verse","number":"136","sanskrit":"एकवृन्दं तु विस्राव्य विधिं शोधनमाचरेत् एकवृन्दमिव प्रायो वृन्दञ्च समुपाचरेत्","text":"ekavṛndaṃ tu visrāvya vidhiṃ śodhanamācaret ekavṛndamiva prāyo vṛndañca samupācaret"},{"type":"verse","number":"137","sanskrit":"गिलायुश्चापि यो व्याधिस्तञ्च शस्त्रेण साधयेत् अमर्मस्थं सुसम्पक्वं छेदयेद्गलविद्र धिम्","text":"gilāyuścāpi yo vyādhistañca śastreṇa sādhayet amarmasthaṃ susampakvaṃ chedayedgalavidra dhim"},{"type":"verse","number":"138","sanskrit":"कण्ठरोगेष्वसृङ्मोक्षैस्तीक्ष्णैर्नस्यादिकर्मभिः चिकित्सकश्चिकित्सान्तु कुशलोऽत्र समाचरेत्","text":"kaṇṭharogeṣvasṛṅmokṣaistīkṣṇairnasyādikarmabhiḥ cikitsakaścikitsāntu kuśalo'tra samācaret"},{"type":"verse","number":"139","sanskrit":"क्वाथं दद्याच्च दार्वीत्वङ्निम्बतार्क्ष्यकलिङ्गजम् हरीतकीकषायो वा हितो माक्षिकसंयुतः","text":"kvāthaṃ dadyācca dārvītvaṅnimbatārkṣyakaliṅgajam harītakīkaṣāyo vā hito mākṣikasaṃyutaḥ"},{"type":"verse","number":"140","sanskrit":"कटुकाऽतिविषादारुपाठामुस्तकलिङ्गकाः गोमूत्रक्वथिताः पीता कण्ठरोगविनाशनाः","text":"kaṭukā'tiviṣādārupāṭhāmustakaliṅgakāḥ gomūtrakvathitāḥ pītā kaṇṭharogavināśanāḥ"},{"type":"verse","number":"141","sanskrit":"मृद्वीका कटुका व्योषं दार्वीत्वक् त्रिफला घनम् पाठा रसाञ्जनं दूर्वा तेजोह्वेति सुचूर्णितम्","text":"mṛdvīkā kaṭukā vyoṣaṃ dārvītvak triphalā ghanam pāṭhā rasāñjanaṃ dūrvā tejohveti sucūrṇitam"},{"type":"verse","number":"142","sanskrit":"क्षौद्र युक्तं विधातव्यं गलरोगे महौषधम् योगाश्चैते त्रयः प्रोक्ता वातपित्तकफापहाः","text":"kṣaudra yuktaṃ vidhātavyaṃ galaroge mahauṣadham yogāścaite trayaḥ proktā vātapittakaphāpahāḥ"},{"type":"verse","number":"143","sanskrit":"यवाग्रजं तेजवताञ्च पाठां रसाञ्जनं दारुनिशां सकृष्णाम् क्षौद्रे ण कुर्याद् गुटिकां मुखेन तां धारयेत्सर्वगलामयेषु","text":"yavāgrajaṃ tejavatāñca pāṭhāṃ rasāñjanaṃ dāruniśāṃ sakṛṣṇām kṣaudre ṇa kuryād guṭikāṃ mukhena tāṃ dhārayetsarvagalāmayeṣu"},{"type":"verse","number":"144","sanskrit":"पृथगदोषैस्त्रयो रोगाः समस्तमुखजाः स्मृताः","text":"pṛthagadoṣaistrayo rogāḥ samastamukhajāḥ smṛtāḥ"},{"type":"verse","number":"145","sanskrit":"स्फोटैः सतोदैर्वदनं समन्ताद्यत्राचितं सर्वसरः स वातात्","text":"sphoṭaiḥ satodairvadanaṃ samantādyatrācitaṃ sarvasaraḥ sa vātāt"},{"type":"verse","number":"146","sanskrit":"रक्तैः सदाहैः पिडकैः सपीतैर्यत्राचितं चापि स पित्तकोपात्","text":"raktaiḥ sadāhaiḥ piḍakaiḥ sapītairyatrācitaṃ cāpi sa pittakopāt"},{"type":"verse","number":"147","sanskrit":"अवेदनैः कण्डुयुतैः सवणैर्यत्राचितं चापि स वै कफेन","text":"avedanaiḥ kaṇḍuyutaiḥ savaṇairyatrācitaṃ cāpi sa vai kaphena"},{"type":"verse","number":"148","sanskrit":"ओष्ठप्रकोपे वर्ज्यास्तु मांसरक्तत्रिदोषजाः दन्तवेष्टेषु वर्ज्यौ तु त्रिलिङ्गगति सौषिरौ","text":"oṣṭhaprakope varjyāstu māṃsaraktatridoṣajāḥ dantaveṣṭeṣu varjyau tu triliṅgagati sauṣirau"},{"type":"verse","number":"149","sanskrit":"दन्तेषु च न सिध्यन्ति श्यावदालनभञ्जनाः जिह्वारोगेष्वलासस्तु तालुजेष्वर्बुदं तथा स्वरघ्नो वलयो बृन्दो बलासः स हि दारुणः च विदारिका गलौघो मांसतानश्च शतघ्नी रोहिणी गले असाध्याः कीर्त्तिता ह्येते रोगा दश नवोत्तराः तेषु वाऽपि क्रियां वैद्यः प्रत्याख्याय समाचरेत्","text":"danteṣu ca na sidhyanti śyāvadālanabhañjanāḥ jihvārogeṣvalāsastu tālujeṣvarbudaṃ tathā svaraghno valayo bṛndo balāsaḥ sa hi dāruṇaḥ ca vidārikā galaugho māṃsatānaśca śataghnī rohiṇī gale asādhyāḥ kīrttitā hyete rogā daśa navottarāḥ teṣu vā'pi kriyāṃ vaidyaḥ pratyākhyāya samācaret"},{"type":"verse","number":"150","sanskrit":"वातात्सर्वसरं चूर्णैर्लवणैः प्रतिसारयेत् तैलं वातहरैः सिद्धं हितं कवलनस्ययोः","text":"vātātsarvasaraṃ cūrṇairlavaṇaiḥ pratisārayet tailaṃ vātaharaiḥ siddhaṃ hitaṃ kavalanasyayoḥ"},{"type":"verse","number":"151","sanskrit":"पित्तात्मके सर्वसरे शुद्धकायस्य देहिनः सर्वः पित्तहरः कार्यो विधिर्मधुरशीतलः","text":"pittātmake sarvasare śuddhakāyasya dehinaḥ sarvaḥ pittaharaḥ kāryo vidhirmadhuraśītalaḥ"},{"type":"verse","number":"152","sanskrit":"प्रतिसारणगण्डूषधूमसंशोधनानि च कफात्मके सर्वसरे क्रमं कुर्यात्कफापहम्","text":"pratisāraṇagaṇḍūṣadhūmasaṃśodhanāni ca kaphātmake sarvasare kramaṃ kuryātkaphāpaham"},{"type":"verse","number":"153","sanskrit":"मुखपाके शिरावेधः शिरसश्च विरेचनम् मधुमूत्रघृतक्षीरैः शीतैश्च कवलग्रहः","text":"mukhapāke śirāvedhaḥ śirasaśca virecanam madhumūtraghṛtakṣīraiḥ śītaiśca kavalagrahaḥ"},{"type":"verse","number":"154","sanskrit":"जातीपत्रामृताद्रा क्षायासदार्वीफलत्रिकैः क्वाथः क्षौद्र युतः शीतो गण्डूषो मुखपाकनुत्","text":"jātīpatrāmṛtādrā kṣāyāsadārvīphalatrikaiḥ kvāthaḥ kṣaudra yutaḥ śīto gaṇḍūṣo mukhapākanut"},{"type":"verse","number":"155","sanskrit":"कार्यञ्च बहुधा नित्यं जातीपत्रस्य चर्वणम् कृष्णजीरककुष्ठेन्द्र यवचर्वणतस्त्र्यहात्","text":"kāryañca bahudhā nityaṃ jātīpatrasya carvaṇam kṛṣṇajīrakakuṣṭhendra yavacarvaṇatastryahāt"},{"type":"verse","number":"156","sanskrit":"मुखपाकव्रणक्लेद दौर्गन्ध्यमुपशाम्यति पटोलनिम्बजम्ब्वाम्र मालतीनवपल्लवैः","text":"mukhapākavraṇakleda daurgandhyamupaśāmyati paṭolanimbajambvāmra mālatīnavapallavaiḥ"},{"type":"verse","number":"157","sanskrit":"पञ्चपल्लवजः श्रेष्ठः कषायो मुखधावने पञ्चवल्कलजः क्वाथस्त्रिफलासम्भवोऽथ वा","text":"pañcapallavajaḥ śreṣṭhaḥ kaṣāyo mukhadhāvane pañcavalkalajaḥ kvāthastriphalāsambhavo'tha vā"},{"type":"verse","number":"158","sanskrit":"मुखपाके प्रयोक्तव्यः सक्षौद्रो मुखधावने स्वरसः क्वथितो दार्व्या घनीभूतो रसक्रिया सक्षौद्रा मुखरोगा सृग्दोषनाडीव्रणापहा","text":"mukhapāke prayoktavyaḥ sakṣaudro mukhadhāvane svarasaḥ kvathito dārvyā ghanībhūto rasakriyā sakṣaudrā mukharogā sṛgdoṣanāḍīvraṇāpahā"},{"type":"verse","number":"159","sanskrit":"सप्तच्छदोशीरपटोलमुस्तहरीतकीतिक्तकरोहिणीभिः यष्ट्याह्वराजद्रुमचन्दनैश्च क्वाथं पिबेत्पाकहरं मुखस्य","text":"saptacchadośīrapaṭolamustaharītakītiktakarohiṇībhiḥ yaṣṭyāhvarājadrumacandanaiśca kvāthaṃ pibetpākaharaṃ mukhasya"},{"type":"verse","number":"160","sanskrit":"तिला नीलोत्पलं सर्पिः शर्करा क्षीरमेव च क्षौद्रा ढ्या दग्धवक्त्रस्य गण्डूषो मुखपाकनुत्","text":"tilā nīlotpalaṃ sarpiḥ śarkarā kṣīrameva ca kṣaudrā ḍhyā dagdhavaktrasya gaṇḍūṣo mukhapākanut"},{"type":"verse","number":"161","sanskrit":"आस्वादिता सकृदपि मुखगन्धं सकलमपनयति त्वग्बीजपूरफलजा पवनमपाच्यं वारयति","text":"āsvāditā sakṛdapi mukhagandhaṃ sakalamapanayati tvagbījapūraphalajā pavanamapācyaṃ vārayati"},{"type":"verse","number":"162","sanskrit":"हरिद्रा निम्बपत्राणि मधुकं नीलमुत्पलम् तैलमेभिर्विपक्तव्यं मुखपाकहरं परम्","text":"haridrā nimbapatrāṇi madhukaṃ nīlamutpalam tailamebhirvipaktavyaṃ mukhapākaharaṃ param"},{"type":"verse","number":"163","sanskrit":"यष्टीमधु पलमेकं त्रिंशन्नीलोत्पलस्य तैलस्य प्रस्थं तद् द्विगुणपयोविधिनापक्वं तु नस्येन","text":"yaṣṭīmadhu palamekaṃ triṃśannīlotpalasya tailasya prasthaṃ tad dviguṇapayovidhināpakvaṃ tu nasyena"},{"type":"verse","number":"164","sanskrit":"निशि वदनस्य स्रावं क्षपयति गात्रस्य दोषसंघातम् कचघर्षत्वमवश्यं क्रमतोऽभ्यङ्गेन जन्तूनाम्","text":"niśi vadanasya srāvaṃ kṣapayati gātrasya doṣasaṃghātam kacagharṣatvamavaśyaṃ kramato'bhyaṅgena jantūnām"},{"type":"verse","number":"165","sanskrit":"इति षट्षष्टितमो मुख रोगाधिकारः समाप्तः ६६","text":"iti ṣaṭṣaṣṭitamo mukha rogādhikāraḥ samāptaḥ 66"}]},{"sthana":"Уттаракханда","number":66,"lang":"sa","content":[{"type":"heading","heading":"Виша — токсикология (яды)"},{"type":"verse","number":"1","sanskrit":"स्थावरं जङ्गमञ्चैव द्विविधं विषमुच्यते दशाधिष्ठानमाद्यं तु द्वितीयं षोडशाश्रयम्","text":"sthāvaraṃ jaṅgamañcaiva dvividhaṃ viṣamucyate daśādhiṣṭhānamādyaṃ tu dvitīyaṃ ṣoḍaśāśrayam"},{"type":"verse","number":"2","sanskrit":"मूलं पत्रं फलं पुष्पं त्वक् क्षीरं सारमेव च निर्यासो धातवः कन्दः स्थावरस्याश्रया दश","text":"mūlaṃ patraṃ phalaṃ puṣpaṃ tvak kṣīraṃ sārameva ca niryāso dhātavaḥ kandaḥ sthāvarasyāśrayā daśa"},{"type":"verse","number":"3","sanskrit":"दृष्टिनिश्वासदंष्ट्राश्च नखमूलमलानि च शुक्रं लालाऽत्तवस्पर्शसंदंशाश्चावमर्दितम् गुदास्थिपित्तशूकानि दश षड् जङ्गमाश्रयाः","text":"dṛṣṭiniśvāsadaṃṣṭrāśca nakhamūlamalāni ca śukraṃ lālā'ttavasparśasaṃdaṃśāścāvamarditam gudāsthipittaśūkāni daśa ṣaḍ jaṅgamāśrayāḥ"},{"type":"verse","number":"4","sanskrit":"अथ स्थावरविषाणां सामान्यकार्याणि उद्वेष्टनं मूलविषैर्मोहः प्रलपनं तथा","text":"atha sthāvaraviṣāṇāṃ sāmānyakāryāṇi udveṣṭanaṃ mūlaviṣairmohaḥ pralapanaṃ tathā"},{"type":"verse","number":"5","sanskrit":"जृम्भणं वेपनं श्वासो नृणां पत्रविषैर्भवेत्","text":"jṛmbhaṇaṃ vepanaṃ śvāso nṛṇāṃ patraviṣairbhavet"},{"type":"verse","number":"6","sanskrit":"मुष्कशोथः फलविषैर्दाहो द्वेषश्च भोजने","text":"muṣkaśothaḥ phalaviṣairdāho dveṣaśca bhojane"},{"type":"verse","number":"7","sanskrit":"भवेत्पुष्पविषैश्छर्दिराध्मानं मूर्च्छनं तथा","text":"bhavetpuṣpaviṣaiśchardirādhmānaṃ mūrcchanaṃ tathā"},{"type":"verse","number":"8","sanskrit":"त्वक्सारनिर्यासविषैरुपभुक्तैर्भवन्ति हि आस्यदौर्गन्ध्य पारुष्यशिरोरुक्कफसंस्रवाः","text":"tvaksāraniryāsaviṣairupabhuktairbhavanti hi āsyadaurgandhya pāruṣyaśirorukkaphasaṃsravāḥ"},{"type":"verse","number":"9","sanskrit":"फेनागमः क्षीरविषैर्विड्भेदो गुरुजिह्वता","text":"phenāgamaḥ kṣīraviṣairviḍbhedo gurujihvatā"},{"type":"verse","number":"10","sanskrit":"हृत्पीडनं धातुविषैर्मूर्च्छा दाहश्च तालुनि प्रायेण कालघातीनि विषाण्येतानि निर्दिशेत्","text":"hṛtpīḍanaṃ dhātuviṣairmūrcchā dāhaśca tāluni prāyeṇa kālaghātīni viṣāṇyetāni nirdiśet"},{"type":"verse","number":"11","sanskrit":"कन्दजान्युग्रवीर्याणि यान्युक्तानि त्रयोदश सर्वाण्येतानि कुशलैर्ज्ञेयानि दशभिर्गुणैः","text":"kandajānyugravīryāṇi yānyuktāni trayodaśa sarvāṇyetāni kuśalairjñeyāni daśabhirguṇaiḥ"},{"type":"verse","number":"12","sanskrit":"स्थावरं जङ्गमं वाऽपि कृत्रिमं चापि यद्विषम् सद्यो निहन्ति तत्सर्वं गुणैश्च दशभिर्युतम्","text":"sthāvaraṃ jaṅgamaṃ vā'pi kṛtrimaṃ cāpi yadviṣam sadyo nihanti tatsarvaṃ guṇaiśca daśabhiryutam"},{"type":"verse","number":"13","sanskrit":"रूक्षमुष्णं तथा तीक्ष्णं सूक्ष्ममाशु व्यवायि च विकाशि विशदञ्चैव लघुपाकि च ते दश","text":"rūkṣamuṣṇaṃ tathā tīkṣṇaṃ sūkṣmamāśu vyavāyi ca vikāśi viśadañcaiva laghupāki ca te daśa"},{"type":"verse","number":"14","sanskrit":"तद्रौ क्ष्यात्कोपयेद्वायुमौष्ण्यात् पित्तं सशोणितम् तैक्ष्ण्यान्मतिं मोहयति मर्मबन्धाञ्छिनत्ति हि शरीरावयवान्सौक्ष्म्यात्प्रविशेद्विकरोति च आशुत्वादाशु तत्प्रोक्तं व्यवायात्प्रकृतिं हरेत्","text":"tadrau kṣyātkopayedvāyumauṣṇyāt pittaṃ saśoṇitam taikṣṇyānmatiṃ mohayati marmabandhāñchinatti hi śarīrāvayavānsaukṣmyātpraviśedvikaroti ca āśutvādāśu tatproktaṃ vyavāyātprakṛtiṃ haret"},{"type":"verse","number":"15","sanskrit":"विकाशित्वात्क्षपयति दोषान्धातून्मलानपि अतिरिच्यते वैशद्याद् दुश्चिकित्स्यं च लाघवात् दुर्जरं चाविपाकित्वात्तस्मात्क्लेशयते चिरम्","text":"vikāśitvātkṣapayati doṣāndhātūnmalānapi atiricyate vaiśadyād duścikitsyaṃ ca lāghavāt durjaraṃ cāvipākitvāttasmātkleśayate ciram"},{"type":"verse","number":"16","sanskrit":"सद्यः क्षतं पच्यते यस्य जन्तोः स्रवेद्र क्तं पच्यते चाप्यभीक्ष्णम् कृष्णीभूतं क्लिन्नमत्यर्थपूति क्षतान्मांसं शीर्यते यस्य वाऽपि","text":"sadyaḥ kṣataṃ pacyate yasya jantoḥ sravedra ktaṃ pacyate cāpyabhīkṣṇam kṛṣṇībhūtaṃ klinnamatyarthapūti kṣatānmāṃsaṃ śīryate yasya vā'pi"},{"type":"verse","number":"17","sanskrit":"तृष्णातापौ दाहमूर्च्छे च यस्य दिग्धं विद्धं तं मनुष्यं व्यवस्येत् लिङ्गान्येतान्येव कुर्यादमित्रैर्दत्तः क्ष्वेडो वा व्रणे यस्य चापि","text":"tṛṣṇātāpau dāhamūrcche ca yasya digdhaṃ viddhaṃ taṃ manuṣyaṃ vyavasyet liṅgānyetānyeva kuryādamitrairdattaḥ kṣveḍo vā vraṇe yasya cāpi"},{"type":"verse","number":"18","sanskrit":"इङ्गितज्ञो मनुष्याणां वाक्चेष्टामुखवैकृतैः जानीयाद्विषदातारमेभिर्लिङ्गैश्च बुद्धिमान्","text":"iṅgitajño manuṣyāṇāṃ vākceṣṭāmukhavaikṛtaiḥ jānīyādviṣadātāramebhirliṅgaiśca buddhimān"},{"type":"verse","number":"19","sanskrit":"न ददात्युत्तरं पृष्टो विवक्षुर्मोहमेति च अपार्थं बहु सङ्कीर्णं भाषते चापि मूढवत्","text":"na dadātyuttaraṃ pṛṣṭo vivakṣurmohameti ca apārthaṃ bahu saṅkīrṇaṃ bhāṣate cāpi mūḍhavat"},{"type":"verse","number":"20","sanskrit":"अङ्गुलद्यः स्फोटयेदुर्वीं विलिखेत्प्रहसेदपि वेपथुश्चास्य भवति त्रस्तश्चैककमीक्षते","text":"aṅguladyaḥ sphoṭayedurvīṃ vilikhetprahasedapi vepathuścāsya bhavati trastaścaikakamīkṣate"},{"type":"verse","number":"21","sanskrit":"विवर्णवक्त्रो ध्यामश्च नखैः किञ्चिच्छिनत्ति च आलभेतासकृद्दीनः करेण च शिरोरुहान् निर्यियासुरपद्वारैर्वीक्षते च पुनः पुनः वर्त्तते विपरीतं च विषदाता विचेतनः","text":"vivarṇavaktro dhyāmaśca nakhaiḥ kiñcicchinatti ca ālabhetāsakṛddīnaḥ kareṇa ca śiroruhān niryiyāsurapadvārairvīkṣate ca punaḥ punaḥ varttate viparītaṃ ca viṣadātā vicetanaḥ"},{"type":"verse","number":"22","sanskrit":"निद्रां तन्द्रां क्लमं दाहं सम्पाकं लोमहर्षणम् शोथं चैवातिसारं च कुरुते जङ्गमं विषम्","text":"nidrāṃ tandrāṃ klamaṃ dāhaṃ sampākaṃ lomaharṣaṇam śothaṃ caivātisāraṃ ca kurute jaṅgamaṃ viṣam"},{"type":"verse","number":"23","sanskrit":"वातपित्तकफात्मानो भोगिमण्डलिराजिलाः यथाक्रमं समाख्याता द्व्यन्तराद्वन्द्वरूपिणः","text":"vātapittakaphātmāno bhogimaṇḍalirājilāḥ yathākramaṃ samākhyātā dvyantarādvandvarūpiṇaḥ"},{"type":"verse","number":"24","sanskrit":"फणिनो भोगिनो ज्ञेयाः संख्यातास्तेऽत्र विंशतिः मण्डलैर्विविधैश्चित्राः पृथवो मन्दगामिनः","text":"phaṇino bhogino jñeyāḥ saṃkhyātāste'tra viṃśatiḥ maṇḍalairvividhaiścitrāḥ pṛthavo mandagāminaḥ"},{"type":"verse","number":"25","sanskrit":"षट् ते मण्डलिनो ज्ञेया ज्वलनार्कविषाः स्मृताः","text":"ṣaṭ te maṇḍalino jñeyā jvalanārkaviṣāḥ smṛtāḥ"},{"type":"verse","number":"26","sanskrit":"स्निग्धा विविधवर्णाभिस्तिर्यगूर्ध्वञ्च राजिभिः विचित्रा इव ये भान्ति राजिलास्ते हि तेऽपि षट्","text":"snigdhā vividhavarṇābhistiryagūrdhvañca rājibhiḥ vicitrā iva ye bhānti rājilāste hi te'pi ṣaṭ"},{"type":"verse","number":"27","sanskrit":"दंशो भोगिकृतः कृष्णः सर्ववातविकारकृत् पीतो मण्डलिनः शोथो मृदुः पित्तविकारवान्","text":"daṃśo bhogikṛtaḥ kṛṣṇaḥ sarvavātavikārakṛt pīto maṇḍalinaḥ śotho mṛduḥ pittavikāravān"},{"type":"verse","number":"28","sanskrit":"राजिलोत्थो भवेद्दंशः स्थिरशोथश्च पिच्छिलः पाण्डुः स्निग्धोऽतिसान्द्रा सृक्सर्वश्लेष्मविकारवान्","text":"rājilottho bhaveddaṃśaḥ sthiraśothaśca picchilaḥ pāṇḍuḥ snigdho'tisāndrā sṛksarvaśleṣmavikāravān"},{"type":"verse","number":"29","sanskrit":"अश्वत्थदेवायतनश्मशानवल्मीकसन्ध्यासु चतुष्पथेषु याम्ये च पित्र्ये परिवर्जनीयाः ॠक्षे नरा मर्मसु ये च दष्टाः","text":"aśvatthadevāyatanaśmaśānavalmīkasandhyāsu catuṣpatheṣu yāmye ca pitrye parivarjanīyāḥ ṝkṣe narā marmasu ye ca daṣṭāḥ"},{"type":"verse","number":"30","sanskrit":"दर्वीकराणां विषमाशु हन्ति मेघानिलोष्णे द्विगुणीभवन्ति","text":"darvīkarāṇāṃ viṣamāśu hanti meghāniloṣṇe dviguṇībhavanti"},{"type":"verse","number":"31","sanskrit":"रथाङ्गलाङ्गलच्छत्रस्वस्ति काङ्कुशधारिणः ज्ञेया दर्वीकराः सर्पाः फणिनः शीघ्रगामिनः","text":"rathāṅgalāṅgalacchatrasvasti kāṅkuśadhāriṇaḥ jñeyā darvīkarāḥ sarpāḥ phaṇinaḥ śīghragāminaḥ"},{"type":"verse","number":"32","sanskrit":"अजीर्णपित्तातपपीडितेषु बालेषु वृद्धेषु बुभुक्षितेषु क्षीणे क्षते मेहिनि कुष्ठजुष्टे रूक्षेऽबले गर्भवतीषु चापि","text":"ajīrṇapittātapapīḍiteṣu bāleṣu vṛddheṣu bubhukṣiteṣu kṣīṇe kṣate mehini kuṣṭhajuṣṭe rūkṣe'bale garbhavatīṣu cāpi"},{"type":"verse","number":"33","sanskrit":"शस्त्रक्षते यस्य न रक्तमस्ति राज्यो लताभिश्च न सम्भवन्ति शीताभिरद्भिश्च न रोमहर्षो विषाभिभूतं परिवर्जयेत्तम् जिह्मं मुखं यस्य च केशशातो नासाऽवसादश्च सकण्ठभङ्गः कृष्णश्च रक्तः श्वयथुश्च दंशे हन्वोः स्थिरत्वञ्च विवर्जनीयः","text":"śastrakṣate yasya na raktamasti rājyo latābhiśca na sambhavanti śītābhiradbhiśca na romaharṣo viṣābhibhūtaṃ parivarjayettam jihmaṃ mukhaṃ yasya ca keśaśāto nāsā'vasādaśca sakaṇṭhabhaṅgaḥ kṛṣṇaśca raktaḥ śvayathuśca daṃśe hanvoḥ sthiratvañca vivarjanīyaḥ"},{"type":"verse","number":"34","sanskrit":"वान्तिर्घना यस्य निरेति वक्त्राद्र क्तं स्रवेदूर्ध्वमधश्च यस्य दंष्ट्रानिपातांश्चतुरश्च पश्येद्यस्यापि वैद्यैः परिवर्जनीयः","text":"vāntirghanā yasya nireti vaktrādra ktaṃ sravedūrdhvamadhaśca yasya daṃṣṭrānipātāṃścaturaśca paśyedyasyāpi vaidyaiḥ parivarjanīyaḥ"},{"type":"verse","number":"35","sanskrit":"उन्मत्तमत्यर्थमुपद्रुतं वा हीनस्वरं वाऽप्यथवा विवर्णम् सारिष्टमत्यर्थमवेगिनञ्च जह्यान्नरं तत्र न कर्म कुर्यात्","text":"unmattamatyarthamupadrutaṃ vā hīnasvaraṃ vā'pyathavā vivarṇam sāriṣṭamatyarthamaveginañca jahyānnaraṃ tatra na karma kuryāt"},{"type":"verse","number":"36","sanskrit":"जीर्णं विषघ्नौषधिभिर्हतं वा दावाग्निवातातपशोषितं वा स्वभावतो वा गुणविप्रहीनं विषं हि दूषीविषतामुपैति","text":"jīrṇaṃ viṣaghnauṣadhibhirhataṃ vā dāvāgnivātātapaśoṣitaṃ vā svabhāvato vā guṇaviprahīnaṃ viṣaṃ hi dūṣīviṣatāmupaiti"},{"type":"verse","number":"37","sanskrit":"वीर्याल्पभावान्न निपातयेत्तत्कफान्वितं वर्षगणानुबन्धि तेनार्दितो भिन्नपुरीषवर्णो विगन्धिवैरस्ययुतः पिपासी मूर्च्छा भ्रमं गद्गदवाग्वमिञ्च विचेष्टमानोऽरतिमाप्नुयाद्वा","text":"vīryālpabhāvānna nipātayettatkaphānvitaṃ varṣagaṇānubandhi tenārdito bhinnapurīṣavarṇo vigandhivairasyayutaḥ pipāsī mūrcchā bhramaṃ gadgadavāgvamiñca viceṣṭamāno'ratimāpnuyādvā"},{"type":"verse","number":"38","sanskrit":"आमाशयस्थे कफवातरोगी पक्वाशयस्थेऽनिलपित्तरोगी भवेत्समुद्धस्तशिरोऽङ्गरुट्को विलूनपक्षश्च यथा विहङ्गः","text":"āmāśayasthe kaphavātarogī pakvāśayasthe'nilapittarogī bhavetsamuddhastaśiro'ṅgaruṭko vilūnapakṣaśca yathā vihaṅgaḥ"},{"type":"verse","number":"39","sanskrit":"स्थितं रसादिष्वथ तद्यथोक्तान्करोति धातुप्रभवान्विकारान्","text":"sthitaṃ rasādiṣvatha tadyathoktānkaroti dhātuprabhavānvikārān"},{"type":"verse","number":"40","sanskrit":"कोपं पु शीतानिलदुर्दिनेषु यात्याशु पूर्वं शृणु तस्य रूपम्","text":"kopaṃ pu śītāniladurdineṣu yātyāśu pūrvaṃ śṛṇu tasya rūpam"},{"type":"verse","number":"41","sanskrit":"निद्रा गुरुत्वञ्च विजृम्भवच्च विश्लेषहर्षावथवाऽङ्गमर्दः","text":"nidrā gurutvañca vijṛmbhavacca viśleṣaharṣāvathavā'ṅgamardaḥ"},{"type":"verse","number":"42","sanskrit":"ततः करोत्यन्नमदाविपाकावरोचकं मण्डलकोठजन्म मासक्षयं पाणिपदे प्रशोथं मूर्च्छां तथा छर्दिमथातिसारम् दूषीविषं श्वासतृषाज्वरांश्च कुर्यात्प्रवृद्धिं जठरस्य चापि","text":"tataḥ karotyannamadāvipākāvarocakaṃ maṇḍalakoṭhajanma māsakṣayaṃ pāṇipade praśothaṃ mūrcchāṃ tathā chardimathātisāram dūṣīviṣaṃ śvāsatṛṣājvarāṃśca kuryātpravṛddhiṃ jaṭharasya cāpi"},{"type":"verse","number":"43","sanskrit":"उन्मादमन्यज्जनयेत्तथाऽन्यदानाहमन्यत्क्षपयेच्च शुक्रम् गाद्गद्यमन्मज्जनयेच्च कुष्ठं तांस्तान्विकारांश्च बहुप्रकारान्","text":"unmādamanyajjanayettathā'nyadānāhamanyatkṣapayecca śukram gādgadyamanmajjanayecca kuṣṭhaṃ tāṃstānvikārāṃśca bahuprakārān"},{"type":"verse","number":"44","sanskrit":"दूषितं देश कालान्नदिवास्वप्नैरभीक्ष्णशः यस्मात्सन्दूषयेद्धातूंस्तस्माद् दूषीविषं स्मृतम्","text":"dūṣitaṃ deśa kālānnadivāsvapnairabhīkṣṇaśaḥ yasmātsandūṣayeddhātūṃstasmād dūṣīviṣaṃ smṛtam"},{"type":"verse","number":"45","sanskrit":"साध्यमात्मवतः सद्यो याप्यं संवत्सरोत्थितम् दूषीविषमसाध्यं स्यात्क्षीणस्याहितसेविनः","text":"sādhyamātmavataḥ sadyo yāpyaṃ saṃvatsarotthitam dūṣīviṣamasādhyaṃ syātkṣīṇasyāhitasevinaḥ"},{"type":"verse","number":"46","sanskrit":"सौभाग्यार्थं स्त्रियः स्वेदं रजो नानाऽङ्गजान्मलान् शत्रुप्रयुक्तांश्च गरान्प्रयच्छन्त्यन्नमिश्रितान्","text":"saubhāgyārthaṃ striyaḥ svedaṃ rajo nānā'ṅgajānmalān śatruprayuktāṃśca garānprayacchantyannamiśritān"},{"type":"verse","number":"47","sanskrit":"तैः स्यात्पाण्डुः कृशोऽल्पाग्निर्गरैश्चास्योपजायते मर्मप्रधमनाध्मानं हस्तयोः शोथसम्भवः","text":"taiḥ syātpāṇḍuḥ kṛśo'lpāgnirgaraiścāsyopajāyate marmapradhamanādhmānaṃ hastayoḥ śothasambhavaḥ"},{"type":"verse","number":"48","sanskrit":"जठरं ग्रहणीदोषो यक्ष्मगुल्मक्षयज्वराः एवंविधस्य चान्यस्य व्याधेर्लिङ्गानि दर्शयेत्","text":"jaṭharaṃ grahaṇīdoṣo yakṣmagulmakṣayajvarāḥ evaṃvidhasya cānyasya vyādherliṅgāni darśayet"},{"type":"verse","number":"49","sanskrit":"यस्माल्लूनं तृणं प्राप्ता मुनेः प्रस्वेदबिन्दवः तेभ्यो जातास्तथा लूता इति ख्यातास्तु षोडश","text":"yasmāllūnaṃ tṛṇaṃ prāptā muneḥ prasvedabindavaḥ tebhyo jātāstathā lūtā iti khyātāstu ṣoḍaśa"},{"type":"verse","number":"50","sanskrit":"विश्वामित्रो नृपवरः कदाचिदृषिसत्तमम् वसिष्ठं कोपयामास गत्वाऽश्रमपदं किल","text":"viśvāmitro nṛpavaraḥ kadācidṛṣisattamam vasiṣṭhaṃ kopayāmāsa gatvā'śramapadaṃ kila"},{"type":"verse","number":"51","sanskrit":"कुपितस्य मुनेस्तस्य ललाटात्स्वेदबिन्दवः अपतन्दर्शनादेव ह्यधस्तात्तीव्रवर्चसः","text":"kupitasya munestasya lalāṭātsvedabindavaḥ apatandarśanādeva hyadhastāttīvravarcasaḥ"},{"type":"verse","number":"52","sanskrit":"लूने तृणे महर्षेस्तु धेन्वर्थे सम्भृतेऽपि च ततो जातास्त्विमे घोरा नानारूपा महाविषाः तासामष्टौ कष्टसाध्या वर्ज्यास्तावत्य एव हि","text":"lūne tṛṇe maharṣestu dhenvarthe sambhṛte'pi ca tato jātāstvime ghorā nānārūpā mahāviṣāḥ tāsāmaṣṭau kaṣṭasādhyā varjyāstāvatya eva hi"},{"type":"verse","number":"53","sanskrit":"ताभिर्दष्टे दंशकोथः प्रवृत्तिः क्षतजस्य च ज्वरो दाहोऽतिसारश्च गदाः स्युश्च त्रिदोषजाः","text":"tābhirdaṣṭe daṃśakothaḥ pravṛttiḥ kṣatajasya ca jvaro dāho'tisāraśca gadāḥ syuśca tridoṣajāḥ"},{"type":"verse","number":"54","sanskrit":"पिडका विविधाकारा मण्डलानि महान्ति च शोथा महान्तो मृदवो रक्ताः श्यावाश्चलास्तथा सामान्यं सर्वलूतानामेतद् दंशस्य लक्षणम्","text":"piḍakā vividhākārā maṇḍalāni mahānti ca śothā mahānto mṛdavo raktāḥ śyāvāścalāstathā sāmānyaṃ sarvalūtānāmetad daṃśasya lakṣaṇam"},{"type":"verse","number":"55","sanskrit":"दंशमध्ये तु यत्कृष्णं श्यावं वा जालकावृतम् दग्धाकृति भृशं पाकक्लेदशोथज्वरान्वितम् दूषीविषाभिर्लूताभिस्तद्दष्टमिति निर्दिशेत्","text":"daṃśamadhye tu yatkṛṣṇaṃ śyāvaṃ vā jālakāvṛtam dagdhākṛti bhṛśaṃ pākakledaśothajvarānvitam dūṣīviṣābhirlūtābhistaddaṣṭamiti nirdiśet"},{"type":"verse","number":"56","sanskrit":"शोथः श्वेताः सिता रक्ताः पीता वा पिडका ज्वरः प्राणान्तकाश्च जायन्ते दाहहिक्काशिरोग्रहाः","text":"śothaḥ śvetāḥ sitā raktāḥ pītā vā piḍakā jvaraḥ prāṇāntakāśca jāyante dāhahikkāśirograhāḥ"},{"type":"verse","number":"57","sanskrit":"आदंशाच्छोणितं पाण्डु मण्डलानि ज्वरोऽरुचिः लोमहर्षश्च दाहश्चाप्याखुदूषीविषार्दिते","text":"ādaṃśācchoṇitaṃ pāṇḍu maṇḍalāni jvaro'ruciḥ lomaharṣaśca dāhaścāpyākhudūṣīviṣārdite"},{"type":"verse","number":"58","sanskrit":"मूर्च्छाऽङ्गशोथवैवर्ण्यं क्लेदो मन्दश्रुतिर्ज्वरः शिरोगुरुत्वं लालाऽसृक्छर्दिश्चासाध्यमूषकात्","text":"mūrcchā'ṅgaśothavaivarṇyaṃ kledo mandaśrutirjvaraḥ śirogurutvaṃ lālā'sṛkchardiścāsādhyamūṣakāt"},{"type":"verse","number":"59","sanskrit":"शोथस्य कार्ष्ण्यमथवा नानावर्णत्वमेव च मोहोऽथ वर्चसो भेदो दष्टस्य कृकलासकैः","text":"śothasya kārṣṇyamathavā nānāvarṇatvameva ca moho'tha varcaso bhedo daṣṭasya kṛkalāsakaiḥ"},{"type":"verse","number":"60","sanskrit":"दहत्यग्निरिवादौ तु भिनत्तीवोर्द्ध्वमाशु च वृश्चिकस्य विषं याति पश्चाद् दंशेऽवतिष्ठते","text":"dahatyagnirivādau tu bhinattīvorddhvamāśu ca vṛścikasya viṣaṃ yāti paścād daṃśe'vatiṣṭhate"},{"type":"verse","number":"61","sanskrit":"दष्टोऽसाध्यैस्तु हृद्घ्राणरसनोपहतो नरः मांसैः पतद्भिरत्यर्थ वेदनाऽत्तो जहात्यसून्","text":"daṣṭo'sādhyaistu hṛdghrāṇarasanopahato naraḥ māṃsaiḥ patadbhiratyartha vedanā'tto jahātyasūn"},{"type":"verse","number":"62","sanskrit":"विसर्पः श्वयथुः शूलं ज्वरश्छर्दिरथापि वा लक्षणं कणभैर्दष्टे दंशश्चैव विशीर्यते","text":"visarpaḥ śvayathuḥ śūlaṃ jvaraśchardirathāpi vā lakṣaṇaṃ kaṇabhairdaṣṭe daṃśaścaiva viśīryate"},{"type":"verse","number":"63","sanskrit":"कृष्णलोमोच्चिटिङ्गेन स्तब्धलिङ्गो भृशार्त्तिमान् दष्टः शीतोदकेनेव सिक्तान्यङ्गानि मन्यते","text":"kṛṣṇalomocciṭiṅgena stabdhaliṅgo bhṛśārttimān daṣṭaḥ śītodakeneva siktānyaṅgāni manyate"},{"type":"verse","number":"64","sanskrit":"एकदंष्ट्राऽदितः शूनःसरुजः पीतकः सतृट् सनिद्र श्छर्दिमान्दष्टो मण्डूकैः सविषैर्भवेत्","text":"ekadaṃṣṭrā'ditaḥ śūnaḥsarujaḥ pītakaḥ satṛṭ sanidra śchardimāndaṣṭo maṇḍūkaiḥ saviṣairbhavet"},{"type":"verse","number":"65","sanskrit":"मत्स्यास्तु सविषाः कुर्युर्दाहं शोथं रुजं तथा","text":"matsyāstu saviṣāḥ kuryurdāhaṃ śothaṃ rujaṃ tathā"},{"type":"verse","number":"66","sanskrit":"कण्डूं शोथं ज्वरं मूर्च्छां सविषास्तु जलौकसः","text":"kaṇḍūṃ śothaṃ jvaraṃ mūrcchāṃ saviṣāstu jalaukasaḥ"},{"type":"verse","number":"67","sanskrit":"विदाहश्वयथुं तोदं प्रस्वेदं गृहगोधिकाः","text":"vidāhaśvayathuṃ todaṃ prasvedaṃ gṛhagodhikāḥ"},{"type":"verse","number":"68","sanskrit":"दंशे स्वेदं रुजं दाहं कुर्याच्छतपदीविषम्","text":"daṃśe svedaṃ rujaṃ dāhaṃ kuryācchatapadīviṣam"},{"type":"verse","number":"69","sanskrit":"कण्डूमान्मशकैरीषच्छोथः स्यान्मन्दवेदनः","text":"kaṇḍūmānmaśakairīṣacchothaḥ syānmandavedanaḥ"},{"type":"verse","number":"70","sanskrit":"असाध्यकीटसदृशमसाध्यं मशकक्षतम्","text":"asādhyakīṭasadṛśamasādhyaṃ maśakakṣatam"},{"type":"verse","number":"71","sanskrit":"सद्यः संस्राविणी श्यावा दाहमूर्च्छाज्वरान्विता पिडका मक्षिकादंशे तासान्तु स्थगिकाऽसुहृत्","text":"sadyaḥ saṃsrāviṇī śyāvā dāhamūrcchājvarānvitā piḍakā makṣikādaṃśe tāsāntu sthagikā'suhṛt"},{"type":"verse","number":"72","sanskrit":"चतुष्पाद्भिर्द्विपाद्भिर्वा नखैर्दन्तैश्च यत्कृतम् शूयते पच्यते तत्तु स्रवति ज्वरयत्यपि","text":"catuṣpādbhirdvipādbhirvā nakhairdantaiśca yatkṛtam śūyate pacyate tattu sravati jvarayatyapi"},{"type":"verse","number":"73","sanskrit":"प्रसन्नदोषं प्रकृतिस्थधातुमन्नाभिकामं सममूत्रविट्कम् प्रसन्नवर्णेन्द्रि यचित्तचेष्टं वैद्योऽवगच्छेदविषं मनुष्यम्","text":"prasannadoṣaṃ prakṛtisthadhātumannābhikāmaṃ samamūtraviṭkam prasannavarṇendri yacittaceṣṭaṃ vaidyo'vagacchedaviṣaṃ manuṣyam"},{"type":"verse","number":"74","sanskrit":"स्थावरेण विषेणार्त्तं नरं यत्नेन वामयेत् वमनेन समं नास्ति यतस्तस्य चिकित्सितम् विषमत्यर्थमुष्णञ्च तीक्ष्णं च कथितं यतः अतः सर्वविषेषूक्तः परिषेकस्तु शीतलः औष्ण्यात्तैक्ष्ण्याद्विशेषेण विषं पित्तं प्रकोपयेत् वमितं सेचयेत्तस्माच्छीतलेन जलेन च पाययेन्मधुसर्पिर्भ्यां विषघ्नं भेषजं द्रुतम् भोक्तुमम्लं रसं दद्याद्घर्षयेन्मरिचानि च","text":"sthāvareṇa viṣeṇārttaṃ naraṃ yatnena vāmayet vamanena samaṃ nāsti yatastasya cikitsitam viṣamatyarthamuṣṇañca tīkṣṇaṃ ca kathitaṃ yataḥ ataḥ sarvaviṣeṣūktaḥ pariṣekastu śītalaḥ auṣṇyāttaikṣṇyādviśeṣeṇa viṣaṃ pittaṃ prakopayet vamitaṃ secayettasmācchītalena jalena ca pāyayenmadhusarpirbhyāṃ viṣaghnaṃ bheṣajaṃ drutam bhoktumamlaṃ rasaṃ dadyādgharṣayenmaricāni ca"},{"type":"verse","number":"75","sanskrit":"यस्य यस्य च दोषस्य पश्येल्लिङ्गानि भूरिशः तस्य तस्यौषधैः कुर्याद्विपरीतगुणैः क्रियाम्","text":"yasya yasya ca doṣasya paśyelliṅgāni bhūriśaḥ tasya tasyauṣadhaiḥ kuryādviparītaguṇaiḥ kriyām"},{"type":"verse","number":"76","sanskrit":"शालयः षष्टिकाश्चैव कोरदूषाः प्रियङ्गवः भोजनार्थं विषार्त्तानामूर्ध्वञ्चाधश्च शोधनम्","text":"śālayaḥ ṣaṣṭikāścaiva koradūṣāḥ priyaṅgavaḥ bhojanārthaṃ viṣārttānāmūrdhvañcādhaśca śodhanam"},{"type":"verse","number":"77","sanskrit":"मूलत्वक्पत्रपुष्पाणि बीजं चेति शिरीषतः गवां मूत्रेण सम्पिष्टंलेपाद्विषहरं परम्","text":"mūlatvakpatrapuṣpāṇi bījaṃ ceti śirīṣataḥ gavāṃ mūtreṇa sampiṣṭaṃlepādviṣaharaṃ param"},{"type":"verse","number":"78","sanskrit":"दूषीविषार्त्तं सुस्निग्धमूर्ध्वञ्चाधश्च शोधनम् पाययेदगदं मुख्यमिदं दूषीविषापहम्","text":"dūṣīviṣārttaṃ susnigdhamūrdhvañcādhaśca śodhanam pāyayedagadaṃ mukhyamidaṃ dūṣīviṣāpaham"},{"type":"verse","number":"79","sanskrit":"पिप्पली ध्यामकं मांसी लोध्रमेला सुवर्चिका मरिचं बालकञ्चैला तथा कनकगैरिकम् क्षौद्र युक्तः कषायोऽय दूषीविषमपोहति","text":"pippalī dhyāmakaṃ māṃsī lodhramelā suvarcikā maricaṃ bālakañcailā tathā kanakagairikam kṣaudra yuktaḥ kaṣāyo'ya dūṣīviṣamapohati"},{"type":"verse","number":"80","sanskrit":"अभयां रोचनां कुष्ठमर्कपत्रं तथोत्पलम् नलवेतसमूलानि गरलं सुरसां तथा","text":"abhayāṃ rocanāṃ kuṣṭhamarkapatraṃ tathotpalam nalavetasamūlāni garalaṃ surasāṃ tathā"},{"type":"verse","number":"81","sanskrit":"सकलिङ्गां समञ्जिष्ठामनन्ताञ्च शतावरीम् शृङ्गाटकं समङ्गां च पद्मकेशरमित्यपि","text":"sakaliṅgāṃ samañjiṣṭhāmanantāñca śatāvarīm śṛṅgāṭakaṃ samaṅgāṃ ca padmakeśaramityapi"},{"type":"verse","number":"82","sanskrit":"कल्कीकृत्य पचेत्सर्पिः पयो दद्याच्चतुर्गुणम् सम्यक्पक्वेऽवतीर्णे च शीते तस्मिन्विनिक्षिपेत्","text":"kalkīkṛtya pacetsarpiḥ payo dadyāccaturguṇam samyakpakve'vatīrṇe ca śīte tasminvinikṣipet"},{"type":"verse","number":"83","sanskrit":"सर्पिस्तुल्यं भिषक्क्षौद्रं कृतरक्षं निधापयेत् विषाणि हन्ति दुर्गाणि गरदोषकृतानि च","text":"sarpistulyaṃ bhiṣakkṣaudraṃ kṛtarakṣaṃ nidhāpayet viṣāṇi hanti durgāṇi garadoṣakṛtāni ca"},{"type":"verse","number":"84","sanskrit":"स्पर्शाद्धन्ति विषं सर्वं गरैरुपहतां त्वचम् योगजं तमकं कण्डूं मांसपादं विसंज्ञताम्","text":"sparśāddhanti viṣaṃ sarvaṃ garairupahatāṃ tvacam yogajaṃ tamakaṃ kaṇḍūṃ māṃsapādaṃ visaṃjñatām"},{"type":"verse","number":"85","sanskrit":"नाशयत्यञ्जनाभ्यङ्गपानबस्तिषु योजितम् सर्पकीटाखुलूताऽदिदष्टानां विषहृत्परम्","text":"nāśayatyañjanābhyaṅgapānabastiṣu yojitam sarpakīṭākhulūtā'didaṣṭānāṃ viṣahṛtparam"},{"type":"verse","number":"86","sanskrit":"धत्तरूस्य शिफा पेया क्षीरेण परिपेषिता अङ्कोटवंशजा चापि श्वविषघ्नी प्रयत्नतः","text":"dhattarūsya śiphā peyā kṣīreṇa paripeṣitā aṅkoṭavaṃśajā cāpi śvaviṣaghnī prayatnataḥ"},{"type":"verse","number":"87","sanskrit":"रजनीयुग्मपत्तङ्ग मञ्जिष्ठानागकेशरैः शीताम्बुपिष्टैरालेपः सद्यो लूतां विनाशयेत्","text":"rajanīyugmapattaṅga mañjiṣṭhānāgakeśaraiḥ śītāmbupiṣṭairālepaḥ sadyo lūtāṃ vināśayet"},{"type":"verse","number":"88","sanskrit":"जीरकस्य कृतः कल्को घृतसैन्धवसंयुतः सुखोष्णो मधुना लेपो वृश्चिकस्य विषं हरेत्","text":"jīrakasya kṛtaḥ kalko ghṛtasaindhavasaṃyutaḥ sukhoṣṇo madhunā lepo vṛścikasya viṣaṃ haret"},{"type":"verse","number":"89","sanskrit":"गन्धमाघ्राय मृदितं सूर्यावर्त्तदलस्य तु वृश्चिकेन नरो विद्धः क्षणाद्भवति निर्विषः","text":"gandhamāghrāya mṛditaṃ sūryāvarttadalasya tu vṛścikena naro viddhaḥ kṣaṇādbhavati nirviṣaḥ"},{"type":"verse","number":"90","sanskrit":"इति सप्तषष्टितमो विषाधिकारः समाप्तः ६७","text":"iti saptaṣaṣṭitamo viṣādhikāraḥ samāptaḥ 67"}]},{"sthana":"Уттаракханда","number":67,"lang":"sa","content":[{"type":"heading","heading":"Стрирога — женские болезни"},{"type":"verse","number":"1","sanskrit":"विरुद्धमद्याध्यशनादजीर्णाद्गर्भप्रपातादतिमैथुनाच्च यानाध्वशोकादतिकर्षणाच्च भाराभिघाताच्छयनाद्दिवा च","text":"viruddhamadyādhyaśanādajīrṇādgarbhaprapātādatimaithunācca yānādhvaśokādatikarṣaṇācca bhārābhighātācchayanāddivā ca"},{"type":"verse","number":"2","sanskrit":"तं श्लेष्मपित्तानिलसन्निपातैश्चतुष्प्रकारं प्रदरं वदन्ति","text":"taṃ śleṣmapittānilasannipātaiścatuṣprakāraṃ pradaraṃ vadanti"},{"type":"verse","number":"3","sanskrit":"असृग्दरं भवेत्सर्वं साङ्गमर्दं सवेदनम्","text":"asṛgdaraṃ bhavetsarvaṃ sāṅgamardaṃ savedanam"},{"type":"verse","number":"4","sanskrit":"आमं सपिच्छाप्रतिमं सपाण्डुं पुलाकतोयप्रतिमं कफात्तु","text":"āmaṃ sapicchāpratimaṃ sapāṇḍuṃ pulākatoyapratimaṃ kaphāttu"},{"type":"verse","number":"5","sanskrit":"सपीतनीलासितरक्तमुष्णं पित्तार्त्तियुक्तं भृशवेगि पित्तात्","text":"sapītanīlāsitaraktamuṣṇaṃ pittārttiyuktaṃ bhṛśavegi pittāt"},{"type":"verse","number":"6","sanskrit":"रूक्षारुणं फेनिलमल्पमल्पं वातात्सतोदं पिशितोदकाभम्","text":"rūkṣāruṇaṃ phenilamalpamalpaṃ vātātsatodaṃ piśitodakābham"},{"type":"verse","number":"7","sanskrit":"सक्षौद्र सर्पिर्हरितालवर्णं मज्जप्रकाशं कुणपं त्रिदोषम् तच्चाप्यसाध्यं प्रवदन्ति तज्ज्ञा न तत्र कुर्वीत भिषक्चिकित्साम्","text":"sakṣaudra sarpirharitālavarṇaṃ majjaprakāśaṃ kuṇapaṃ tridoṣam taccāpyasādhyaṃ pravadanti tajjñā na tatra kurvīta bhiṣakcikitsām"},{"type":"verse","number":"8","sanskrit":"तस्यातिवृत्तौ दौर्बल्यं श्रमो मूर्च्छा मदस्तृषा दाहः प्रलापः पाण्डुत्वं तन्द्रा रोगाश्च वातजाः","text":"tasyātivṛttau daurbalyaṃ śramo mūrcchā madastṛṣā dāhaḥ pralāpaḥ pāṇḍutvaṃ tandrā rogāśca vātajāḥ"},{"type":"verse","number":"9","sanskrit":"शश्वत्स्त्रवन्तीमास्रावं तृष्णादाहज्वरान्विताम् दुर्बलां क्षीणरक्ताञ्च तामसाध्यां विवर्जयेत्","text":"śaśvatstravantīmāsrāvaṃ tṛṣṇādāhajvarānvitām durbalāṃ kṣīṇaraktāñca tāmasādhyāṃ vivarjayet"},{"type":"verse","number":"10","sanskrit":"मासान्निष्पिच्छदाहार्त्ति पञ्चरात्रानुबन्धि च नैवातिबहु नात्यल्पमार्त्तवं शुद्धमादिशेत्","text":"māsānniṣpicchadāhārtti pañcarātrānubandhi ca naivātibahu nātyalpamārttavaṃ śuddhamādiśet"},{"type":"verse","number":"11","sanskrit":"दध्ना सौवर्चलं जाजी मधुकं नीलमुत्पलम् पिबेत्क्षौद्र युतं नारी वातासृग्दरशान्तये","text":"dadhnā sauvarcalaṃ jājī madhukaṃ nīlamutpalam pibetkṣaudra yutaṃ nārī vātāsṛgdaraśāntaye"},{"type":"verse","number":"12","sanskrit":"मधुकं कर्षमेकं तु कर्षकाञ्च सितां तथा तण्डुलोदकसम्पिष्टां लोहित प्रदरे पिबेत् बलां कङ्कतिकाऽख्या या तस्या मूलं सुचूर्णितम् लोहितप्रदरे खादेच्छर्करामधुसंयुतम् शुचिस्थाने व्याघ्रनख्या मूलमुत्तरदिग्भवम् नीतमुत्तरफल्गुन्यां कटिबद्धं हरेदसृक्","text":"madhukaṃ karṣamekaṃ tu karṣakāñca sitāṃ tathā taṇḍulodakasampiṣṭāṃ lohita pradare pibet balāṃ kaṅkatikā'khyā yā tasyā mūlaṃ sucūrṇitam lohitapradare khādeccharkarāmadhusaṃyutam śucisthāne vyāghranakhyā mūlamuttaradigbhavam nītamuttaraphalgunyāṃ kaṭibaddhaṃ haredasṛk"},{"type":"verse","number":"13","sanskrit":"रसाञ्जनं तण्डुलकस्य मूलं क्षौद्रा न्वितं तण्डुलतोयपीतम् असृग्दरं सर्वभवं निहन्ति श्वासञ्च भार्गी सह नागरेण","text":"rasāñjanaṃ taṇḍulakasya mūlaṃ kṣaudrā nvitaṃ taṇḍulatoyapītam asṛgdaraṃ sarvabhavaṃ nihanti śvāsañca bhārgī saha nāgareṇa"},{"type":"verse","number":"14","sanskrit":"अशोकवल्कलक्वाथशृतं दुग्धं सुशीतलम् यथाबलं पिबेत्प्रातस्तीव्रासृग्दरनाशनम्","text":"aśokavalkalakvāthaśṛtaṃ dugdhaṃ suśītalam yathābalaṃ pibetprātastīvrāsṛgdaranāśanam"},{"type":"verse","number":"15","sanskrit":"कुशमूलं समुद्धृत्य पेषयेत्तडुलाम्बुना एतत्पीत्वा त्र्यहं नारी प्रदरात्परिमुच्यते","text":"kuśamūlaṃ samuddhṛtya peṣayettaḍulāmbunā etatpītvā tryahaṃ nārī pradarātparimucyate"},{"type":"verse","number":"16","sanskrit":"क्षौद्र युक्तं फलरसमौदुम्बरभवं पिबेत् असृग्दरविनाशाय सशर्करपयोऽन्नभुक्","text":"kṣaudra yuktaṃ phalarasamaudumbarabhavaṃ pibet asṛgdaravināśāya saśarkarapayo'nnabhuk"},{"type":"verse","number":"17","sanskrit":"अलाबुफलचूर्णस्य शर्करासहितस्य च मधुना मोदकं कृत्वा खादेत्प्रदरशान्तये","text":"alābuphalacūrṇasya śarkarāsahitasya ca madhunā modakaṃ kṛtvā khādetpradaraśāntaye"},{"type":"verse","number":"18","sanskrit":"दार्वीरसाञ्जनकिरातवृषाब्दबिल्वसक्षौद्र चन्दनदिनेशभवप्रसूनैः क्वाथः कृतो मधुयुतो विधिना निपीतो रक्तं सितञ्च सरुजं प्रदरं निहन्ति रक्तपित्ताधिकारोक्तं हितं कूष्माण्डखण्डकम्","text":"dārvīrasāñjanakirātavṛṣābdabilvasakṣaudra candanadineśabhavaprasūnaiḥ kvāthaḥ kṛto madhuyuto vidhinā nipīto raktaṃ sitañca sarujaṃ pradaraṃ nihanti raktapittādhikāroktaṃ hitaṃ kūṣmāṇḍakhaṇḍakam"},{"type":"verse","number":"19","sanskrit":"इत्यष्टषष्टितमः प्रदराधिकारः समाप्तः ६८","text":"ityaṣṭaṣaṣṭitamaḥ pradarādhikāraḥ samāptaḥ 68"}]},{"sthana":"Уттаракханда","number":68,"lang":"sa","content":[{"type":"heading","heading":"Сомарога — полиурия у женщин"},{"type":"verse","number":"1","sanskrit":"स्त्रीणामतिप्रसङ्गेन शोकाच्चापि श्रमादपि आभिचारिकयोगाद्वा गरयोगात्तथैव च","text":"strīṇāmatiprasaṅgena śokāccāpi śramādapi ābhicārikayogādvā garayogāttathaiva ca"},{"type":"verse","number":"2","sanskrit":"आपः सर्वशरीरस्थाः क्षुभ्यन्ति प्रस्रवन्ति च तस्यास्ताः प्रच्युताः स्थानान्मूत्रमार्ग व्रजन्ति हि","text":"āpaḥ sarvaśarīrasthāḥ kṣubhyanti prasravanti ca tasyāstāḥ pracyutāḥ sthānānmūtramārga vrajanti hi"},{"type":"verse","number":"3","sanskrit":"प्रसन्ना विमलाः शीता निर्गन्धा नीरुजाः सिताः स्रवन्ति चातिमात्रं ताः सा न शक्नोति दुर्बला","text":"prasannā vimalāḥ śītā nirgandhā nīrujāḥ sitāḥ sravanti cātimātraṃ tāḥ sā na śaknoti durbalā"},{"type":"verse","number":"4","sanskrit":"वेगं धारयितुं तासां न विन्दति सुखं क्वचित् शिरः शिथिलता तस्य मुखं तालु च शुष्यति","text":"vegaṃ dhārayituṃ tāsāṃ na vindati sukhaṃ kvacit śiraḥ śithilatā tasya mukhaṃ tālu ca śuṣyati"},{"type":"verse","number":"5","sanskrit":"मूर्च्छा जृम्भा प्रलापश्च त्वग्रूक्षा चातिमात्रतः भक्ष्यैर्भोज्यैश्च पेयैश्च न तृप्तिं लभते सदा","text":"mūrcchā jṛmbhā pralāpaśca tvagrūkṣā cātimātrataḥ bhakṣyairbhojyaiśca peyaiśca na tṛptiṃ labhate sadā"},{"type":"verse","number":"6","sanskrit":"सन्धारणाच्छरीरस्य ता आपः सोमसंज्ञिताः ततः सोमक्षयात्स्त्रीणां सोमरोग इति स्मृताः","text":"sandhāraṇāccharīrasya tā āpaḥ somasaṃjñitāḥ tataḥ somakṣayātstrīṇāṃ somaroga iti smṛtāḥ"},{"type":"verse","number":"7","sanskrit":"कदलीनां फलं पक्वं धात्रीफलरसं मधु शर्करासहितं खादेत् सोमधारणमुत्तमम्","text":"kadalīnāṃ phalaṃ pakvaṃ dhātrīphalarasaṃ madhu śarkarāsahitaṃ khādet somadhāraṇamuttamam"},{"type":"verse","number":"8","sanskrit":"माषचूर्णं समधुकं विदारीं मधुशर्कराम् पयसा पाययेत्प्रातः सोमधारणमुत्तमम्","text":"māṣacūrṇaṃ samadhukaṃ vidārīṃ madhuśarkarām payasā pāyayetprātaḥ somadhāraṇamuttamam"},{"type":"verse","number":"9","sanskrit":"स एव सरुजः सोमः स्रवेन्मूत्रेण चेन्मुहुः तत्रैलापत्रचूर्णेन पाययेद्वारुणीं सुराम्","text":"sa eva sarujaḥ somaḥ sravenmūtreṇa cenmuhuḥ tatrailāpatracūrṇena pāyayedvāruṇīṃ surām"},{"type":"verse","number":"10","sanskrit":"जलेनामलकी बीजकल्कं समधुशर्करम् पिबेद्दिनत्रयेणैव श्वेतप्रदरनाशनम्","text":"jalenāmalakī bījakalkaṃ samadhuśarkaram pibeddinatrayeṇaiva śvetapradaranāśanam"},{"type":"verse","number":"11","sanskrit":"तक्रौदनाहाररता सम्पिबेन्नागकेशरम् त्र्यहं तक्रेण सम्पिष्टं श्वेतप्रदरशान्तये","text":"takraudanāhāraratā sampibennāgakeśaram tryahaṃ takreṇa sampiṣṭaṃ śvetapradaraśāntaye"},{"type":"verse","number":"12","sanskrit":"सोमरोगे चिरं जाते यदा मूत्रमतिस्रवेत् मूत्रातिसारं तं प्राहुर्बलविध्वंसनं परम्","text":"somaroge ciraṃ jāte yadā mūtramatisravet mūtrātisāraṃ taṃ prāhurbalavidhvaṃsanaṃ param"},{"type":"verse","number":"13","sanskrit":"इत्यैकोनसप्ततितमः सोमरोगाधिकारः समाप्तः ६९","text":"ityaikonasaptatitamaḥ somarogādhikāraḥ samāptaḥ 69"}]},{"sthana":"Уттаракханда","number":69,"lang":"sa","content":[{"type":"heading","heading":"Йони — гинекология"},{"type":"verse","number":"1","sanskrit":"मिथ्याऽहारविहाराभ्यां दुष्टैर्दोषैः प्रदूषिताम् आर्त्तवाद्बीजतश्चापि दैवाद्वा स्युर्भगे गदाः","text":"mithyā'hāravihārābhyāṃ duṣṭairdoṣaiḥ pradūṣitām ārttavādbījataścāpi daivādvā syurbhage gadāḥ"},{"type":"verse","number":"2","sanskrit":"उदावर्त्ता तथा वन्ध्या विप्लुता च परिप्लुता वातला योनिजो रोगो वातदोषेण पञ्चधा","text":"udāvarttā tathā vandhyā viplutā ca pariplutā vātalā yonijo rogo vātadoṣeṇa pañcadhā"},{"type":"verse","number":"3","sanskrit":"पञ्चधा पित्तदोषेण तत्रादौ लोहितक्षरा प्रस्रंसिनी वामनी च पुत्रघ्नी पित्तला तथा","text":"pañcadhā pittadoṣeṇa tatrādau lohitakṣarā prasraṃsinī vāmanī ca putraghnī pittalā tathā"},{"type":"verse","number":"4","sanskrit":"अत्यानन्दा कर्णिनी च चरणानन्दपूर्विका अतिपूर्वाऽपि सा ज्ञेया श्लेष्मला च कफादिमाः","text":"atyānandā karṇinī ca caraṇānandapūrvikā atipūrvā'pi sā jñeyā śleṣmalā ca kaphādimāḥ"},{"type":"verse","number":"5","sanskrit":"षण्ढ्यण्डिनी च महती सूचीवक्त्रा त्रिदोषिणी पञ्चैता योनयः प्रोक्ताः सर्वदोषप्रकोपतः","text":"ṣaṇḍhyaṇḍinī ca mahatī sūcīvaktrā tridoṣiṇī pañcaitā yonayaḥ proktāḥ sarvadoṣaprakopataḥ"},{"type":"verse","number":"6","sanskrit":"सफेनिलमुदावर्त्ता रजः कृच्छ्रेण मुञ्चति बन्ध्या निरार्त्तवा ज्ञेया विप्लुता नित्यवेदना","text":"saphenilamudāvarttā rajaḥ kṛcchreṇa muñcati bandhyā nirārttavā jñeyā viplutā nityavedanā"},{"type":"verse","number":"7","sanskrit":"परिप्लुतायां भवति ग्राम्यधर्मरुजा भृशम् वातला कर्कशा स्तब्धा शूलनिस्तोदपीडिता चतसृष्वपि चाद्यासु भवन्त्यनिलवेदनाः","text":"pariplutāyāṃ bhavati grāmyadharmarujā bhṛśam vātalā karkaśā stabdhā śūlanistodapīḍitā catasṛṣvapi cādyāsu bhavantyanilavedanāḥ"},{"type":"verse","number":"8","sanskrit":"सदाहं क्षरते रक्तं यस्याः सा लोहितक्षरा प्रस्रंसिनी स्रंसते च क्षोभिता दुष्प्रजायिनी","text":"sadāhaṃ kṣarate raktaṃ yasyāḥ sā lohitakṣarā prasraṃsinī sraṃsate ca kṣobhitā duṣprajāyinī"},{"type":"verse","number":"9","sanskrit":"सवातमुद्गिरद्बीजं वामनी रजसा युतम् स्थितं हि पातयेद्गर्भं पुत्रघ्नी रक्तसंस्रवात्","text":"savātamudgiradbījaṃ vāmanī rajasā yutam sthitaṃ hi pātayedgarbhaṃ putraghnī raktasaṃsravāt"},{"type":"verse","number":"10","sanskrit":"अत्यर्थं पित्तला योनिर्दाहपाकज्वरान्विता चतसृष्वपि चाद्यासु पित्तलिङ्गोच्छ्रयो भवेत्","text":"atyarthaṃ pittalā yonirdāhapākajvarānvitā catasṛṣvapi cādyāsu pittaliṅgocchrayo bhavet"},{"type":"verse","number":"11","sanskrit":"अत्यानन्दा न सन्तोषं ग्राम्यधर्मेण विन्दति कर्णिन्यां कर्णिका योनौ श्लेष्मासृग्भ्यां प्रजायते","text":"atyānandā na santoṣaṃ grāmyadharmeṇa vindati karṇinyāṃ karṇikā yonau śleṣmāsṛgbhyāṃ prajāyate"},{"type":"verse","number":"12","sanskrit":"मैथुने चरणा पूर्वं पुरुषादतिरिच्यते बहुशश्चातिचरणा तयोर्बीजं न तिष्ठति","text":"maithune caraṇā pūrvaṃ puruṣādatiricyate bahuśaścāticaraṇā tayorbījaṃ na tiṣṭhati"},{"type":"verse","number":"13","sanskrit":"श्लेष्मला पिच्छिला योनिः कण्डूयुक्ताऽतिशीतला चतसृष्वपि चाद्यासु श्लेष्मलिङ्गोच्छ्रयो भवेत्","text":"śleṣmalā picchilā yoniḥ kaṇḍūyuktā'tiśītalā catasṛṣvapi cādyāsu śleṣmaliṅgocchrayo bhavet"},{"type":"verse","number":"14","sanskrit":"अनार्त्तवाऽस्तनी षण्ढी खरस्पर्शा च मैथुने महामेढ्रगृहीतायाबालायास्त्वण्डिनी भवेत्","text":"anārttavā'stanī ṣaṇḍhī kharasparśā ca maithune mahāmeḍhragṛhītāyābālāyāstvaṇḍinī bhavet"},{"type":"verse","number":"15","sanskrit":"विवृताऽतिमहायोनिः सूचीवक्त्राऽतिसंवृता","text":"vivṛtā'timahāyoniḥ sūcīvaktrā'tisaṃvṛtā"},{"type":"verse","number":"16","sanskrit":"सर्वलिङ्गसमुत्थाना सर्वदोषप्रकोपजा चतसृष्वपि चाद्यासु सर्वलिङ्गनिदर्शनम् ६६ पञ्चासाध्या भवन्तीह योनयः सर्वदोषजाः","text":"sarvaliṅgasamutthānā sarvadoṣaprakopajā catasṛṣvapi cādyāsu sarvaliṅganidarśanam 66 pañcāsādhyā bhavantīha yonayaḥ sarvadoṣajāḥ"},{"type":"verse","number":"17","sanskrit":"दिवास्वप्नादतिक्रोधाद् व्यायामादतिमैथुनात् क्षताच्च नखदन्ताद्यैर्वाताद्याः कुपिता यथा","text":"divāsvapnādatikrodhād vyāyāmādatimaithunāt kṣatācca nakhadantādyairvātādyāḥ kupitā yathā"},{"type":"verse","number":"18","sanskrit":"पूयशोणितसङ्काशं लकुचाकृतिसन्निभम् जनयन्ति यदा योनौ नाम्ना कन्दः स योनिजः","text":"pūyaśoṇitasaṅkāśaṃ lakucākṛtisannibham janayanti yadā yonau nāmnā kandaḥ sa yonijaḥ"},{"type":"verse","number":"19","sanskrit":"रूक्षं विवर्णं स्फुटितं वातिकं तं विनिर्दिशेत् दाहरागज्वरयुतं विद्यात्पित्तात्मकं तु तम्","text":"rūkṣaṃ vivarṇaṃ sphuṭitaṃ vātikaṃ taṃ vinirdiśet dāharāgajvarayutaṃ vidyātpittātmakaṃ tu tam"},{"type":"verse","number":"20","sanskrit":"तिलपुष्पप्रतीकाशं कण्डूमन्तं कफात्मकम् सर्वलिङ्गसमायुक्तं सन्निपातात्मकं वदेत्","text":"tilapuṣpapratīkāśaṃ kaṇḍūmantaṃ kaphātmakam sarvaliṅgasamāyuktaṃ sannipātātmakaṃ vadet"},{"type":"verse","number":"21","sanskrit":"आर्त्तवादर्शने नारी मत्स्यान्सेवेत नित्यशः काञ्जिकं च तिलान्माषानुदश्विच्च तथा दधि","text":"ārttavādarśane nārī matsyānseveta nityaśaḥ kāñjikaṃ ca tilānmāṣānudaśvicca tathā dadhi"},{"type":"verse","number":"22","sanskrit":"इक्ष्वाकुबीजदन्तीचपलागुडमदनकिण्वयवशूकैः सस्नुक्क्षीरैर्वर्त्तिर्योनिगता कुसुमसञ्जननी","text":"ikṣvākubījadantīcapalāguḍamadanakiṇvayavaśūkaiḥ sasnukkṣīrairvarttiryonigatā kusumasañjananī"},{"type":"verse","number":"23","sanskrit":"पीतं ज्योतिष्मतीपत्रं स्वर्जिकोग्रासनं त्र्यहम् शीतेन पयसा पिष्टं कुसुमं जनयेद् ध्रुवम्","text":"pītaṃ jyotiṣmatīpatraṃ svarjikogrāsanaṃ tryaham śītena payasā piṣṭaṃ kusumaṃ janayed dhruvam"},{"type":"verse","number":"24","sanskrit":"बला सिता सातिबला मधूकं वटस्य शुङ्गं गजकेशरं च एतन्मधुक्षीरघृतैर्निपीतं वन्ध्या सुपुत्रं नियतं प्रसूते","text":"balā sitā sātibalā madhūkaṃ vaṭasya śuṅgaṃ gajakeśaraṃ ca etanmadhukṣīraghṛtairnipītaṃ vandhyā suputraṃ niyataṃ prasūte"},{"type":"verse","number":"25","sanskrit":"अश्वगन्धाकषायेण सिद्धं दुग्धं घृतान्वितम् ॠतुस्नाताऽङ्गना प्रातः पीत्वा गर्भं दधाति हि","text":"aśvagandhākaṣāyeṇa siddhaṃ dugdhaṃ ghṛtānvitam ṝtusnātā'ṅganā prātaḥ pītvā garbhaṃ dadhāti hi"},{"type":"verse","number":"26","sanskrit":"पुष्योद्धृतं लक्ष्मणाया मूलं दुग्धेन कन्यया पिष्टं पीत्वा ॠतुस्नाता गर्भं धत्ते न संशयः","text":"puṣyoddhṛtaṃ lakṣmaṇāyā mūlaṃ dugdhena kanyayā piṣṭaṃ pītvā ṝtusnātā garbhaṃ dhatte na saṃśayaḥ"},{"type":"verse","number":"27","sanskrit":"कुरण्टमूलं धातक्याः कुसुमानि वटाङ्कुराः नीलोत्पलं पयोयुक्तमेतद् गर्भप्रदं ध्रुवम्","text":"kuraṇṭamūlaṃ dhātakyāḥ kusumāni vaṭāṅkurāḥ nīlotpalaṃ payoyuktametad garbhapradaṃ dhruvam"},{"type":"verse","number":"28","sanskrit":"याऽबला पिबति पार्श्वपिप्पलं जीरकेण सहितं हिताशिनी श्वेतया विशिखपुङ्खया युतं सा सुतं जनयतीह नान्यथा","text":"yā'balā pibati pārśvapippalaṃ jīrakeṇa sahitaṃ hitāśinī śvetayā viśikhapuṅkhayā yutaṃ sā sutaṃ janayatīha nānyathā"},{"type":"verse","number":"29","sanskrit":"पत्रमेकं पलाशस्य पिष्ट्वा दुग्धेन गर्भिणी पीत्वा पुत्रमवाप्नोति वीर्यवन्तं न संशयः","text":"patramekaṃ palāśasya piṣṭvā dugdhena garbhiṇī pītvā putramavāpnoti vīryavantaṃ na saṃśayaḥ"},{"type":"verse","number":"30","sanskrit":"शूकरशिम्बीमूलं मध्यं वा दधिफलस्य सपयस्कम् पीत्वाऽथो भवलिङ्गीबीजं कन्यां न सूते स्त्री","text":"śūkaraśimbīmūlaṃ madhyaṃ vā dadhiphalasya sapayaskam pītvā'tho bhavaliṅgībījaṃ kanyāṃ na sūte strī"},{"type":"verse","number":"31","sanskrit":"पुत्रकमञ्जरिमूलं विष्णुक्रान्तेशलिङ्गिनी सहिता एतद्गर्भेऽष्टदिनं पीत्वा कन्यां न सर्वथा सूते","text":"putrakamañjarimūlaṃ viṣṇukrānteśaliṅginī sahitā etadgarbhe'ṣṭadinaṃ pītvā kanyāṃ na sarvathā sūte"},{"type":"verse","number":"32","sanskrit":"पिप्पलिविडङ्गटङ्कणसमचूर्णं या पिबेत्पयसा ॠतुसमये न हि तस्या गर्भः सञ्जायते क्वापि","text":"pippaliviḍaṅgaṭaṅkaṇasamacūrṇaṃ yā pibetpayasā ṝtusamaye na hi tasyā garbhaḥ sañjāyate kvāpi"},{"type":"verse","number":"33","sanskrit":"आरनालपरिपेषितं त्र्यहं या जपाकुसुममत्ति पुष्पिणी सत्पुराणगुडमुष्टिसेविनी सन्दधाति न हि गर्भमङ्गना","text":"āranālaparipeṣitaṃ tryahaṃ yā japākusumamatti puṣpiṇī satpurāṇaguḍamuṣṭisevinī sandadhāti na hi garbhamaṅganā"},{"type":"verse","number":"34","sanskrit":"तासु योनिषु चाद्यासु स्नेहादिक्रम इष्यते वस्त्यभ्यङ्गपरीषेकप्रलेपपिचुधारणम्","text":"tāsu yoniṣu cādyāsu snehādikrama iṣyate vastyabhyaṅgaparīṣekapralepapicudhāraṇam"},{"type":"verse","number":"35","sanskrit":"नतवार्त्ताकिनी कुष्ठसैन्धवामरदारुभिः तिलतैलं पचेन्नारी पिचुमस्य विधारयेत् विप्लुतायां सदा योनौ व्यथा तेन प्रशाम्यति","text":"natavārttākinī kuṣṭhasaindhavāmaradārubhiḥ tilatailaṃ pacennārī picumasya vidhārayet viplutāyāṃ sadā yonau vyathā tena praśāmyati"},{"type":"verse","number":"36","sanskrit":"वातलां कर्कशां स्तब्धामल्पस्पर्शां तथैव च कुम्भीस्वेदैरुपचरेदन्तर्वेश्मनि संवृते धारयेद्वा पिचुं योनौ तिलतैलस्य सा सदा","text":"vātalāṃ karkaśāṃ stabdhāmalpasparśāṃ tathaiva ca kumbhīsvedairupacaredantarveśmani saṃvṛte dhārayedvā picuṃ yonau tilatailasya sā sadā"},{"type":"verse","number":"37","sanskrit":"पित्तलानां च योनीनां सेकाभ्यङ्गपिचुक्रियाः शीताः पित्तहराः कार्याःस्नेहनार्थं घृतानि च","text":"pittalānāṃ ca yonīnāṃ sekābhyaṅgapicukriyāḥ śītāḥ pittaharāḥ kāryāḥsnehanārthaṃ ghṛtāni ca"},{"type":"verse","number":"38","sanskrit":"प्रस्रसिनीं घृताभ्यक्तां क्षीरस्विन्नां प्रवेशयेत् पिधाय वेशवारेण ततो बन्धं समाचरेत्","text":"prasrasinīṃ ghṛtābhyaktāṃ kṣīrasvinnāṃ praveśayet pidhāya veśavāreṇa tato bandhaṃ samācaret"},{"type":"verse","number":"39","sanskrit":"शुण्ठीमरिचकृष्णा भिर्धान्यकाजाजिदाडिमैः पिप्पलीमूलसंयुक्तैर्वेशवारः स्मृतो बुधैः","text":"śuṇṭhīmaricakṛṣṇā bhirdhānyakājājidāḍimaiḥ pippalīmūlasaṃyuktairveśavāraḥ smṛto budhaiḥ"},{"type":"verse","number":"40","sanskrit":"धात्रीरसं सितायुक्तं योनिदाहे पिबेत्सदा सूर्यकान्ता भवं मूलं पिबेद्वा तण्डुलाम्बुना","text":"dhātrīrasaṃ sitāyuktaṃ yonidāhe pibetsadā sūryakāntā bhavaṃ mūlaṃ pibedvā taṇḍulāmbunā"},{"type":"verse","number":"41","sanskrit":"योन्यां तु पूयस्राविण्यां शोधनद्र व्यनिर्मितैः सगोमूत्रैः सलवणैः पिण्डैः सम्पूरणं हितम्","text":"yonyāṃ tu pūyasrāviṇyāṃ śodhanadra vyanirmitaiḥ sagomūtraiḥ salavaṇaiḥ piṇḍaiḥ sampūraṇaṃ hitam"},{"type":"verse","number":"42","sanskrit":"दुर्गन्धां पिच्छिलां वाऽपि चूर्णैः पञ्चकषायजैः पूरयेद्धारयेद्रा जवृक्षादिक्वथिताम्बुना","text":"durgandhāṃ picchilāṃ vā'pi cūrṇaiḥ pañcakaṣāyajaiḥ pūrayeddhārayedrā javṛkṣādikvathitāmbunā"},{"type":"verse","number":"43","sanskrit":"पिप्पल्या मरिचैर्माषैः शताह्वाकुष्ठसैन्धवैः वर्त्तिस्तुल्या प्रदेशिन्या योनौ श्लेष्मविशोधिनी","text":"pippalyā maricairmāṣaiḥ śatāhvākuṣṭhasaindhavaiḥ varttistulyā pradeśinyā yonau śleṣmaviśodhinī"},{"type":"verse","number":"44","sanskrit":"कर्णिन्यां वर्त्तयो देयाः शोधनद्र व्यनिर्मिताः","text":"karṇinyāṃ varttayo deyāḥ śodhanadra vyanirmitāḥ"},{"type":"verse","number":"45","sanskrit":"गुडूची त्रिफलादन्तीक्वथितोदकधारया योनिं प्रक्षालयेत्तेन तत्र कण्डूः प्रशाम्यति","text":"guḍūcī triphalādantīkvathitodakadhārayā yoniṃ prakṣālayettena tatra kaṇḍūḥ praśāmyati"},{"type":"verse","number":"46","sanskrit":"मुद्गयूषं सखदिरं पथ्यां जातीफलं तथा निम्बं पूगञ्च सञ्चूर्ण्य वस्त्रपूतं क्षिपेद्भगे","text":"mudgayūṣaṃ sakhadiraṃ pathyāṃ jātīphalaṃ tathā nimbaṃ pūgañca sañcūrṇya vastrapūtaṃ kṣipedbhage"},{"type":"verse","number":"47","sanskrit":"योनिर्भवति सङ्कीर्णा न स्रवेच्च जलं ततः कपिकच्छूभवं मूलं क्वाथयेद्विधिना भिषक् योनिः सङ्कीर्णतां याति क्वाथेनानेन धावने","text":"yonirbhavati saṅkīrṇā na sravecca jalaṃ tataḥ kapikacchūbhavaṃ mūlaṃ kvāthayedvidhinā bhiṣak yoniḥ saṅkīrṇatāṃ yāti kvāthenānena dhāvane"},{"type":"verse","number":"48","sanskrit":"जीरकद्वितयं कृष्णं सुषवी सुरभिर्वचा वासकः सैन्धवश्चापि यवक्षारो यवानिका","text":"jīrakadvitayaṃ kṛṣṇaṃ suṣavī surabhirvacā vāsakaḥ saindhavaścāpi yavakṣāro yavānikā"},{"type":"verse","number":"49","sanskrit":"एषां चूर्णं घृते किञ्चिद्भृष्ट्वा खण्डेन मोदकम् कृत्वा खादेद्यथावह्नि योनिरोगाद्विमुच्यते","text":"eṣāṃ cūrṇaṃ ghṛte kiñcidbhṛṣṭvā khaṇḍena modakam kṛtvā khādedyathāvahni yonirogādvimucyate"},{"type":"verse","number":"50","sanskrit":"मूषकक्वाथसंसिद्धतिलतैलकृतः पिचुः नाशयेद् योनिरोगांस्तान्धृतो योनौ न संशयः","text":"mūṣakakvāthasaṃsiddhatilatailakṛtaḥ picuḥ nāśayed yonirogāṃstāndhṛto yonau na saṃśayaḥ"},{"type":"verse","number":"51","sanskrit":"त्रिफलां द्वौ सहचरौ गुडूचीं सपुनर्नवाम् शुकनासां हरिद्रे द्वे रास्नां मेदां शतावरीम्","text":"triphalāṃ dvau sahacarau guḍūcīṃ sapunarnavām śukanāsāṃ haridre dve rāsnāṃ medāṃ śatāvarīm"},{"type":"verse","number":"52","sanskrit":"कल्कीकृत्य घृतप्रस्थं पचेत्क्षीरे चतुर्गुणे तत्सिद्धं पाययेन्नारी योनिरोगप्रशान्तये","text":"kalkīkṛtya ghṛtaprasthaṃ pacetkṣīre caturguṇe tatsiddhaṃ pāyayennārī yonirogapraśāntaye"},{"type":"verse","number":"53","sanskrit":"मञ्जिष्ठा मधुकं कुष्ठं त्रिफला शर्करा बला मेदे पयस्याकाकोल्यौ मूलं चैवाश्वगन्धजम्","text":"mañjiṣṭhā madhukaṃ kuṣṭhaṃ triphalā śarkarā balā mede payasyākākolyau mūlaṃ caivāśvagandhajam"},{"type":"verse","number":"54","sanskrit":"अजमोदा हरिद्रे द्वे प्रियङ्गुः कटुरोहिणी उत्पलं कुमुदं द्रा क्षा काकोल्यौ चन्दनद्वयम्","text":"ajamodā haridre dve priyaṅguḥ kaṭurohiṇī utpalaṃ kumudaṃ drā kṣā kākolyau candanadvayam"},{"type":"verse","number":"55","sanskrit":"एतेषां कार्षिकैर्भागैर्घृतप्रस्थं विपाचयेत् शतावरीरसं क्षीरं घृताद्देयं चतुर्गुणम्","text":"eteṣāṃ kārṣikairbhāgairghṛtaprasthaṃ vipācayet śatāvarīrasaṃ kṣīraṃ ghṛtāddeyaṃ caturguṇam"},{"type":"verse","number":"56","sanskrit":"सर्पि रेतन्नरः पीत्वा स्त्रीषु नित्यं वृषायते पुत्राञ्जनयते वीरान्मेधाऽढ्यान्प्रियदर्शनान्","text":"sarpi retannaraḥ pītvā strīṣu nityaṃ vṛṣāyate putrāñjanayate vīrānmedhā'ḍhyānpriyadarśanān"},{"type":"verse","number":"57","sanskrit":"या चैवास्थिरगर्भा स्यात्पुत्रं वा जनयेन्मृतम् अल्पायुषं वा जनयेद्या च कन्यां प्रसूयते","text":"yā caivāsthiragarbhā syātputraṃ vā janayenmṛtam alpāyuṣaṃ vā janayedyā ca kanyāṃ prasūyate"},{"type":"verse","number":"58","sanskrit":"योनिरोगे रजोदोषे परिस्रावे च शस्यते प्रजावर्धनमायुष्यं सर्वग्रहनिवारणम्","text":"yoniroge rajodoṣe parisrāve ca śasyate prajāvardhanamāyuṣyaṃ sarvagrahanivāraṇam"},{"type":"verse","number":"59","sanskrit":"नाम्ना फलघृतं ह्येतदश्विभ्यां परिकीर्त्तितम् अनुक्तं लक्ष्मणामूलं क्षिपन्त्यत्र चिकित्सकाः","text":"nāmnā phalaghṛtaṃ hyetadaśvibhyāṃ parikīrttitam anuktaṃ lakṣmaṇāmūlaṃ kṣipantyatra cikitsakāḥ"},{"type":"verse","number":"60","sanskrit":"जीवद्वत्सैकवर्णाया घृतं तत्र प्रयुज्यते आरण्यगोमयेनैव वह्निज्वाला च दीयते","text":"jīvadvatsaikavarṇāyā ghṛtaṃ tatra prayujyate āraṇyagomayenaiva vahnijvālā ca dīyate"},{"type":"verse","number":"61","sanskrit":"गैरिकाम्रास्थिजन्तुघ्नरजन्यञ्जनकट्फलाः पूरयेद्योनिमेतेषां चूर्णैः क्षौद्र्रसमन्वितैः","text":"gairikāmrāsthijantughnarajanyañjanakaṭphalāḥ pūrayedyonimeteṣāṃ cūrṇaiḥ kṣaudrrasamanvitaiḥ"},{"type":"verse","number":"62","sanskrit":"त्रिफलायाः कषायेण सक्षौद्रे ण च सेचयेत् प्रमदा योनिकन्देन व्याधिना परिमुच्यते","text":"triphalāyāḥ kaṣāyeṇa sakṣaudre ṇa ca secayet pramadā yonikandena vyādhinā parimucyate"},{"type":"verse","number":"63","sanskrit":"तत्र चलितगर्भस्थापने ह्रीवेरादिक्वाथः ह्रीवेरातिविषामुस्तमोचशक्रैश्शृतं जलम् दद्याद् गर्भे प्रचलिते प्रदरे कुक्षिरुज्यपि","text":"tatra calitagarbhasthāpane hrīverādikvāthaḥ hrīverātiviṣāmustamocaśakraiśśṛtaṃ jalam dadyād garbhe pracalite pradare kukṣirujyapi"},{"type":"verse","number":"64","sanskrit":"मधुकं चन्दनो शीरसारिवापद्मपत्रकैः शर्करामधुसंयुक्तैः कषायो गर्भिणीज्वरे","text":"madhukaṃ candano śīrasārivāpadmapatrakaiḥ śarkarāmadhusaṃyuktaiḥ kaṣāyo garbhiṇījvare"},{"type":"verse","number":"65","sanskrit":"चन्दनं सारिवालोध्रमृद्वीकाशर्कराऽन्वितम् क्वाथं कृत्वा प्रदद्याच्च गर्भिणीज्वरशान्तये पीतं विश्वमजाक्षीरैर्नाशयेद्विषमज्वरम्","text":"candanaṃ sārivālodhramṛdvīkāśarkarā'nvitam kvāthaṃ kṛtvā pradadyācca garbhiṇījvaraśāntaye pītaṃ viśvamajākṣīrairnāśayedviṣamajvaram"},{"type":"verse","number":"66","sanskrit":"आम्रजम्बूत्वचः क्वाथैर्लेहयेल्लाजशक्तुकम् अनेनालीढमात्रेण गर्भिणी ग्रहणीं जयेत्","text":"āmrajambūtvacaḥ kvāthairlehayellājaśaktukam anenālīḍhamātreṇa garbhiṇī grahaṇīṃ jayet"},{"type":"verse","number":"67","sanskrit":"ह्रीबेरारलुरक्तचन्दनबलाधान्याकवत्सादनी मुस्तोशीरयवासपर्पटविषाक्वाथं पिबेद् गर्भिणी नानाव्याधिरुजाऽतिसारगदके रक्तस्रुतौ वा ज्वरे योगोऽय मुनिभिः पुरा निगदितः सूत्यामयेऽप्युत्तमः","text":"hrīberāraluraktacandanabalādhānyākavatsādanī mustośīrayavāsaparpaṭaviṣākvāthaṃ pibed garbhiṇī nānāvyādhirujā'tisāragadake raktasrutau vā jvare yogo'ya munibhiḥ purā nigaditaḥ sūtyāmaye'pyuttamaḥ"},{"type":"verse","number":"68","sanskrit":"ग्राम्यधर्माध्व गमनयानायासप्रपीडनैः ज्वरोपवासोत्पतन प्रहाराजीर्णधावनैः","text":"grāmyadharmādhva gamanayānāyāsaprapīḍanaiḥ jvaropavāsotpatana prahārājīrṇadhāvanaiḥ"},{"type":"verse","number":"69","sanskrit":"वमनाच्च विरेकाच्च कुन्थनाद् गर्भपातनात् तीक्ष्णक्षारोष्णकटुकतिक्तरूक्षनिषेवणात्","text":"vamanācca virekācca kunthanād garbhapātanāt tīkṣṇakṣāroṣṇakaṭukatiktarūkṣaniṣevaṇāt"},{"type":"verse","number":"70","sanskrit":"वेगाभिघाताद्विषमादासनाच्छयनाद्भयात् गर्भे पतति रक्तस्य सशूलं दर्शनं भवेत्","text":"vegābhighātādviṣamādāsanācchayanādbhayāt garbhe patati raktasya saśūlaṃ darśanaṃ bhavet"},{"type":"verse","number":"71","sanskrit":"आ चतुर्थात्ततो मासात्प्रस्रवेद् गर्भविद्र वः ततः स्थिरशरीरस्य पातः पञ्चमषष्ठयोः","text":"ā caturthāttato māsātprasraved garbhavidra vaḥ tataḥ sthiraśarīrasya pātaḥ pañcamaṣaṣṭhayoḥ"},{"type":"verse","number":"72","sanskrit":"गर्भोऽभिघात विषमासनपीडनाद्यैः पक्वं द्रुमादिव फलं पतति क्षणेन","text":"garbho'bhighāta viṣamāsanapīḍanādyaiḥ pakvaṃ drumādiva phalaṃ patati kṣaṇena"},{"type":"verse","number":"73","sanskrit":"गुर्विण्या गर्भतो रक्तं स्रवेद्यदि मुहुर्मुहुः तन्निरोधाय सा दुग्धमुत्पलादिशृतं पिबेत्","text":"gurviṇyā garbhato raktaṃ sravedyadi muhurmuhuḥ tannirodhāya sā dugdhamutpalādiśṛtaṃ pibet"},{"type":"verse","number":"74","sanskrit":"उत्पलं नीलमारक्तं कह्लारं कुमुदं तथा श्वेताम्भोजञ्च मधुकमुत्पलादिरयं गणः","text":"utpalaṃ nīlamāraktaṃ kahlāraṃ kumudaṃ tathā śvetāmbhojañca madhukamutpalādirayaṃ gaṇaḥ"},{"type":"verse","number":"75","sanskrit":"संशीलितो हरत्येव दाहं तृष्णां हृदामयम् रक्तपित्तञ्च मूर्च्छां च तथा छर्दिमरोचकम्","text":"saṃśīlito haratyeva dāhaṃ tṛṣṇāṃ hṛdāmayam raktapittañca mūrcchāṃ ca tathā chardimarocakam"},{"type":"verse","number":"76","sanskrit":"प्रस्रंसमाने गर्भे स्याद्दाहः शूलञ्च पार्श्वयोः पृष्ठरुक्प्रदरानाहौ मूत्रसङ्गश्च जायते","text":"prasraṃsamāne garbhe syāddāhaḥ śūlañca pārśvayoḥ pṛṣṭharukpradarānāhau mūtrasaṅgaśca jāyate"},{"type":"verse","number":"77","sanskrit":"स्थानात्स्थानान्तरं तस्मिन्प्रयात्यपि च जायते आमपक्वाशयादौ तु क्षोभः पूर्वेऽप्युपद्र वाः","text":"sthānātsthānāntaraṃ tasminprayātyapi ca jāyate āmapakvāśayādau tu kṣobhaḥ pūrve'pyupadra vāḥ"},{"type":"verse","number":"78","sanskrit":"स्निग्धशीतक्रियास्तेषु दाहादिषु समाचरेत् कुशकाशोरुबूकाणां मूलैर्गोक्षुरकस्य च","text":"snigdhaśītakriyāsteṣu dāhādiṣu samācaret kuśakāśorubūkāṇāṃ mūlairgokṣurakasya ca"},{"type":"verse","number":"79","sanskrit":"शृतं दुग्धं सितायुक्तं गर्भिण्याः शूलहृत्परम् श्वदंष्ट्रामधुकक्षुद्रा ऽम्लानैः सिद्धं पयः पिबेत् शर्करामधुसंयुक्तं गर्भिणीवेदनापहम्","text":"śṛtaṃ dugdhaṃ sitāyuktaṃ garbhiṇyāḥ śūlahṛtparam śvadaṃṣṭrāmadhukakṣudrā 'mlānaiḥ siddhaṃ payaḥ pibet śarkarāmadhusaṃyuktaṃ garbhiṇīvedanāpaham"},{"type":"verse","number":"80","sanskrit":"मृत्कोष्ठागारिकागेहसम्भवा नवमल्लिका समङ्गा धातकीपुष्पं गैरिकं च रसाञ्जनम्","text":"mṛtkoṣṭhāgārikāgehasambhavā navamallikā samaṅgā dhātakīpuṣpaṃ gairikaṃ ca rasāñjanam"},{"type":"verse","number":"81","sanskrit":"तथा सर्जरसश्चैतान्यथालाभं विचूर्णयेत् तच्चूर्णं मधुना लिह्याद् गर्भपातप्रशान्तये","text":"tathā sarjarasaścaitānyathālābhaṃ vicūrṇayet taccūrṇaṃ madhunā lihyād garbhapātapraśāntaye"},{"type":"verse","number":"82","sanskrit":"कशेरूत्पलशृङ्गाटकल्कं वा पयसा पिबेत् पक्वं वचारसोनाभ्यां हिङ्गुसौवर्चलान्वितम् आनाहे तु पिबेद् दुग्धं गुर्विणी सुखिनी भवेत्","text":"kaśerūtpalaśṛṅgāṭakalkaṃ vā payasā pibet pakvaṃ vacārasonābhyāṃ hiṅgusauvarcalānvitam ānāhe tu pibed dugdhaṃ gurviṇī sukhinī bhavet"},{"type":"verse","number":"83","sanskrit":"तृणपञ्चकमूलानां कल्केन विपचेत्पयः तत्पयो गर्भिणी पीत्वा मूत्रसङ्गाद्विमुच्यते","text":"tṛṇapañcakamūlānāṃ kalkena vipacetpayaḥ tatpayo garbhiṇī pītvā mūtrasaṅgādvimucyate"},{"type":"verse","number":"84","sanskrit":"शालीक्षुकुशकाशैः स्याच्छरेण तृणपञ्चकम् एषां मूलं तृषादाहपित्तासृङ्मूत्रसङ्गहृत्","text":"śālīkṣukuśakāśaiḥ syācchareṇa tṛṇapañcakam eṣāṃ mūlaṃ tṛṣādāhapittāsṛṅmūtrasaṅgahṛt"},{"type":"verse","number":"85","sanskrit":"मधुकं शाकबीजं च पयस्या सुरदारु च अश्मन्तकस्तिलाः कृष्णस्ताम्रवल्ली शतावरी","text":"madhukaṃ śākabījaṃ ca payasyā suradāru ca aśmantakastilāḥ kṛṣṇastāmravallī śatāvarī"},{"type":"verse","number":"86","sanskrit":"वृक्षादनी पयस्या च प्रियङ्गूत्पलसारिवाः अनन्ता सारिवा रास्ना पद्मा मधुकमेव च","text":"vṛkṣādanī payasyā ca priyaṅgūtpalasārivāḥ anantā sārivā rāsnā padmā madhukameva ca"},{"type":"verse","number":"87","sanskrit":"बृहत्यौ काश्मरी चापि क्षीरिशुङ्गास्त्वचो घृतम् पृश्निपर्णी वचा शिग्रुः श्वदंष्ट्रा मधुपर्णिका","text":"bṛhatyau kāśmarī cāpi kṣīriśuṅgāstvaco ghṛtam pṛśniparṇī vacā śigruḥ śvadaṃṣṭrā madhuparṇikā"},{"type":"verse","number":"88","sanskrit":"शृङ्गाटकं विषं द्रा क्षा कशेरु मधुकं सिता वत्सैते सप्त योगाः स्युरर्द्धश्लोकसमापनाः","text":"śṛṅgāṭakaṃ viṣaṃ drā kṣā kaśeru madhukaṃ sitā vatsaite sapta yogāḥ syurarddhaślokasamāpanāḥ"},{"type":"verse","number":"89","sanskrit":"यथासंख्यं प्रयोक्तव्या गर्भस्रावे पयोयुता एवं गर्भो न पतति गर्भशूलञ्च शाम्यति","text":"yathāsaṃkhyaṃ prayoktavyā garbhasrāve payoyutā evaṃ garbho na patati garbhaśūlañca śāmyati"},{"type":"verse","number":"90","sanskrit":"कपित्थबृहतीबिल्वपटोलेक्षुनिदिग्धिकाः मूलानि क्षीरसिद्धानि दापयेद्भिषगष्टमे","text":"kapitthabṛhatībilvapaṭolekṣunidigdhikāḥ mūlāni kṣīrasiddhāni dāpayedbhiṣagaṣṭame"},{"type":"verse","number":"91","sanskrit":"नवमे मधुकानन्तापयस्यासारिवा पिबेत्","text":"navame madhukānantāpayasyāsārivā pibet"},{"type":"verse","number":"92","sanskrit":"क्षीरं शुण्ठीपयस्याभ्यां सिद्धं स्याद्दशमे हितम् सक्षीरं वा हिता शुण्ठी मधुकं सुरदारु च","text":"kṣīraṃ śuṇṭhīpayasyābhyāṃ siddhaṃ syāddaśame hitam sakṣīraṃ vā hitā śuṇṭhī madhukaṃ suradāru ca"},{"type":"verse","number":"93","sanskrit":"क्षीरिकामुत्पलं दुग्धं समङ्गामूलकं शिवाम् पिबेदेकादशे मासि गर्भिणीशूलशान्तये","text":"kṣīrikāmutpalaṃ dugdhaṃ samaṅgāmūlakaṃ śivām pibedekādaśe māsi garbhiṇīśūlaśāntaye"},{"type":"verse","number":"94","sanskrit":"सिता विदारी काकोली क्षीरी चैव मृणालिका गर्भिणी द्वादशे मासि पिबेच्छूलघ्नमौषधम्","text":"sitā vidārī kākolī kṣīrī caiva mṛṇālikā garbhiṇī dvādaśe māsi pibecchūlaghnamauṣadham"},{"type":"verse","number":"95","sanskrit":"एवमाप्यायते गर्भस्तीव्रा रूक् चोपशाम्यति","text":"evamāpyāyate garbhastīvrā rūk copaśāmyati"},{"type":"verse","number":"96","sanskrit":"गर्भो वातेन संशुष्को नोदरं पूरयेद्यदि सा बृंहणीयैः संसिद्धं दुग्धं मांसरसं पिबेत्","text":"garbho vātena saṃśuṣko nodaraṃ pūrayedyadi sā bṛṃhaṇīyaiḥ saṃsiddhaṃ dugdhaṃ māṃsarasaṃ pibet"},{"type":"verse","number":"97","sanskrit":"शुष्कार्त्तवमजाताङ्गं संशुष्कं मरुताऽदितम् त्यक्तं जीवेन तत्तस्मात्कठिनं चावतिष्ठते","text":"śuṣkārttavamajātāṅgaṃ saṃśuṣkaṃ marutā'ditam tyaktaṃ jīvena tattasmātkaṭhinaṃ cāvatiṣṭhate"},{"type":"verse","number":"98","sanskrit":"शुक्रार्त्तवार्दको वायुरुदराध्मानकृद् भवेत् कदाचिच्चेत्तदाऽध्मानं स्वयमेव प्रशाम्यति","text":"śukrārttavārdako vāyurudarādhmānakṛd bhavet kadāciccettadā'dhmānaṃ svayameva praśāmyati"},{"type":"verse","number":"99","sanskrit":"नैगमेयेन गर्भोऽय हृतो लोकध्वनिस्तदा स एवाल्पप्रवृत्त्या चेल्लघुर्भूत्वाऽवतिष्ठते","text":"naigameyena garbho'ya hṛto lokadhvanistadā sa evālpapravṛttyā cellaghurbhūtvā'vatiṣṭhate"},{"type":"verse","number":"100","sanskrit":"नवमे दशमे मासि नारी गर्भं प्रसूयते एकादशे द्वादशे वा ततोऽन्यत्र विकारतः","text":"navame daśame māsi nārī garbhaṃ prasūyate ekādaśe dvādaśe vā tato'nyatra vikārataḥ"},{"type":"verse","number":"101","sanskrit":"वातेन गर्भसङ्कोचात्प्रसूतिसमयेऽपि या गर्भं न जनयेन्नारी तस्याः शृणु चिकित्सितम्","text":"vātena garbhasaṅkocātprasūtisamaye'pi yā garbhaṃ na janayennārī tasyāḥ śṛṇu cikitsitam"},{"type":"verse","number":"102","sanskrit":"कुट्टयेन्मुशलेनैषा कृत्वा धान्यमुलूखले विषमं चासनं यानं सेवेत प्रसवार्थिनी","text":"kuṭṭayenmuśalenaiṣā kṛtvā dhānyamulūkhale viṣamaṃ cāsanaṃ yānaṃ seveta prasavārthinī"},{"type":"verse","number":"103","sanskrit":"प्रसवस्य विलम्बे तु धूपयेदभितो भगम् कृष्णसर्पस्य निर्मोकैस्तथा पिण्डीतकेन वा","text":"prasavasya vilambe tu dhūpayedabhito bhagam kṛṣṇasarpasya nirmokaistathā piṇḍītakena vā"},{"type":"verse","number":"104","sanskrit":"तन्तुना लाङ्गलीमूलं बध्नीयाद्धस्तपादयोः सुवर्चलां विशल्यां वा धारयेदाशु सूयते","text":"tantunā lāṅgalīmūlaṃ badhnīyāddhastapādayoḥ suvarcalāṃ viśalyāṃ vā dhārayedāśu sūyate"},{"type":"verse","number":"105","sanskrit":"करङ्कीभूतगोमूर्द्धा सूतिकाभवनोपरि स्थापितस्तत्क्षणान्नार्याः सुखं प्रसवकारकः","text":"karaṅkībhūtagomūrddhā sūtikābhavanopari sthāpitastatkṣaṇānnāryāḥ sukhaṃ prasavakārakaḥ"},{"type":"verse","number":"106","sanskrit":"पोतकामूलकल्केन तिलतैलयुतेन च योनेरभ्यन्तरं लिप्त्वा सुखं नारी प्रसूयते","text":"potakāmūlakalkena tilatailayutena ca yonerabhyantaraṃ liptvā sukhaṃ nārī prasūyate"},{"type":"verse","number":"107","sanskrit":"कृष्णा वचा चापि जलेन पिष्टा सैरण्डतैला खलु नाभिलेपात् सुखं प्रसूतिं कुरुतेऽङ्गनानां निपीडितानां बहुभिः प्रमादैः","text":"kṛṣṇā vacā cāpi jalena piṣṭā sairaṇḍatailā khalu nābhilepāt sukhaṃ prasūtiṃ kurute'ṅganānāṃ nipīḍitānāṃ bahubhiḥ pramādaiḥ"},{"type":"verse","number":"108","sanskrit":"मातुलुङ्गस्य मूलं तु मधुकेन युतं तथा घृतेन सहितं पीत्वा सुखं नारी प्रसूयते","text":"mātuluṅgasya mūlaṃ tu madhukena yutaṃ tathā ghṛtena sahitaṃ pītvā sukhaṃ nārī prasūyate"},{"type":"verse","number":"109","sanskrit":"इक्षोरुत्तरमूलं निजतनुमानेन तन्तुना बद्ध्वा कटिविषये गर्भवती सुखेन सूतेऽविलम्बेन","text":"ikṣoruttaramūlaṃ nijatanumānena tantunā baddhvā kaṭiviṣaye garbhavatī sukhena sūte'vilambena"},{"type":"verse","number":"110","sanskrit":"तालस्य चोत्तरं मूलं स्वप्रमाणेन तन्तुना बद्ध्वा कट्यान्तु नियतं सुखं नारी प्रसूयते","text":"tālasya cottaraṃ mūlaṃ svapramāṇena tantunā baddhvā kaṭyāntu niyataṃ sukhaṃ nārī prasūyate"},{"type":"verse","number":"111","sanskrit":"मूढः करोति पवनः खलु मूढगर्भशूलञ्च योनिजठरादिषु मूत्रसङ्गम् भुग्नोऽनिलेन विगुणेन ततः स गर्भः संख्यामतीत्य बहुधा समुपैति योनिम्","text":"mūḍhaḥ karoti pavanaḥ khalu mūḍhagarbhaśūlañca yonijaṭharādiṣu mūtrasaṅgam bhugno'nilena viguṇena tataḥ sa garbhaḥ saṃkhyāmatītya bahudhā samupaiti yonim"},{"type":"verse","number":"112","sanskrit":"संकीलकः प्रतिखुरः परिघोऽथ बीजस्तेषूर्ध्वबाहुचरणैः शिरसा च योनौ सङ्गी च यो भवति कीलकवत्स कीलो दृश्यैः खुरैः प्रतिखुरः स हि कायसङ्गी","text":"saṃkīlakaḥ pratikhuraḥ parigho'tha bījasteṣūrdhvabāhucaraṇaiḥ śirasā ca yonau saṅgī ca yo bhavati kīlakavatsa kīlo dṛśyaiḥ khuraiḥ pratikhuraḥ sa hi kāyasaṅgī"},{"type":"verse","number":"113","sanskrit":"द्वारं निरुद्ध्य् शिरसा जठरेण कश्चित् कश्चिच्छरीरपरिवर्त्तितकुब्जकायः एकेन कश्चिदपरस्तु भुजद्वयेन तिर्यग्गतो भवति कश्चिदवाङ्मुखोऽन्य पार्श्वापवृत्तगतिरेति तथैव कश्चिदित्यष्टधा भवति गर्भगतिः प्रसूतौ","text":"dvāraṃ niruddhy śirasā jaṭhareṇa kaścit kaściccharīraparivarttitakubjakāyaḥ ekena kaścidaparastu bhujadvayena tiryaggato bhavati kaścidavāṅmukho'nya pārśvāpavṛttagatireti tathaiva kaścidityaṣṭadhā bhavati garbhagatiḥ prasūtau"},{"type":"verse","number":"114","sanskrit":"अपविद्धशिरा या तु शीताङ्गी निरपत्रपा नीलोद्गतशिरा हन्ति सा गर्भं स च तां तथा","text":"apaviddhaśirā yā tu śītāṅgī nirapatrapā nīlodgataśirā hanti sā garbhaṃ sa ca tāṃ tathā"},{"type":"verse","number":"115","sanskrit":"गर्भास्पन्दनमावीनां प्रणाशः श्यावपाण्डुता भवेदुच्छ्वासपूतित्वं शूलं चान्तर्मृते शिशो","text":"garbhāspandanamāvīnāṃ praṇāśaḥ śyāvapāṇḍutā bhaveducchvāsapūtitvaṃ śūlaṃ cāntarmṛte śiśo"},{"type":"verse","number":"116","sanskrit":"मानसागन्तुभिर्मातुरुपतापैः प्रपीडितः गर्भो व्यापद्यते कुक्षौ व्याधिभिश्च प्रपीडितः","text":"mānasāgantubhirmāturupatāpaiḥ prapīḍitaḥ garbho vyāpadyate kukṣau vyādhibhiśca prapīḍitaḥ"},{"type":"verse","number":"117","sanskrit":"योनिसंवरणं सङ्गः कुक्षौ मक्कल्ल एव च हन्युः स्त्रियं मूढगर्भो यथोक्ताश्चाप्युपद्र वाः","text":"yonisaṃvaraṇaṃ saṅgaḥ kukṣau makkalla eva ca hanyuḥ striyaṃ mūḍhagarbho yathoktāścāpyupadra vāḥ"},{"type":"verse","number":"118","sanskrit":"याभिः सङ्कटकालेऽपि बह्व्यो नार्यः प्रसाविताः सम्यग्लब्धं यशस्तास्तु नार्यः कुर्युरिमां क्रियाम्","text":"yābhiḥ saṅkaṭakāle'pi bahvyo nāryaḥ prasāvitāḥ samyaglabdhaṃ yaśastāstu nāryaḥ kuryurimāṃ kriyām"},{"type":"verse","number":"119","sanskrit":"गर्भे जीवति मूढे तु गर्भं यत्नेन निर्हरेत् हस्तेन सर्पिषाऽक्तेन योनेरन्तर्गतेन सा","text":"garbhe jīvati mūḍhe tu garbhaṃ yatnena nirharet hastena sarpiṣā'ktena yonerantargatena sā"},{"type":"verse","number":"120","sanskrit":"मृते तु गर्भे गर्भिण्या योनौ शस्त्रं प्रवेशयेत् शस्त्रशास्त्रार्थविदुषी लघुहस्ता भयोज्झिता","text":"mṛte tu garbhe garbhiṇyā yonau śastraṃ praveśayet śastraśāstrārthaviduṣī laghuhastā bhayojjhitā"},{"type":"verse","number":"121","sanskrit":"सचेतनं तु शस्त्रेण न कथञ्चन दारयेत् स दीर्यमाणो जननीमात्मानं चापि मारयेत्","text":"sacetanaṃ tu śastreṇa na kathañcana dārayet sa dīryamāṇo jananīmātmānaṃ cāpi mārayet"},{"type":"verse","number":"122","sanskrit":"नोपेक्षेत मृतं गर्भं मुहूर्त्तमपि पण्डितः तदाशु जननीं हन्ति प्रभूतान्नं यथा पशुम्","text":"nopekṣeta mṛtaṃ garbhaṃ muhūrttamapi paṇḍitaḥ tadāśu jananīṃ hanti prabhūtānnaṃ yathā paśum"},{"type":"verse","number":"123","sanskrit":"यद्यदङ्गं हि गर्भस्य योनौ सक्तं तु तद्भिषक् सम्यग्विनिर्हरेच्छित्वा रक्षेन्नारीं प्रयत्नतः","text":"yadyadaṅgaṃ hi garbhasya yonau saktaṃ tu tadbhiṣak samyagvinirharecchitvā rakṣennārīṃ prayatnataḥ"},{"type":"verse","number":"124","sanskrit":"एवं निर्हृतशल्यां तां सिञ्चेदुष्णेन वारिणा ततोऽभ्यक्तशरीरायां योनौ स्नेहं विधारयेत्","text":"evaṃ nirhṛtaśalyāṃ tāṃ siñceduṣṇena vāriṇā tato'bhyaktaśarīrāyāṃ yonau snehaṃ vidhārayet"},{"type":"verse","number":"125","sanskrit":"एवं मृद्वी भवेद्योनिस्तच्छूलं चोपशाम्यति","text":"evaṃ mṛdvī bhavedyonistacchūlaṃ copaśāmyati"},{"type":"verse","number":"126","sanskrit":"तुम्बीपत्रं तथा लोध्रं समभागं सुपेषयेत् तेन लेपो भगे कार्यः शीघ्रंस्याद्योनिरक्षता","text":"tumbīpatraṃ tathā lodhraṃ samabhāgaṃ supeṣayet tena lepo bhage kāryaḥ śīghraṃsyādyonirakṣatā"},{"type":"verse","number":"127","sanskrit":"पलाशोदुम्बरफलं तिलतैलसमन्वितम् योनौ विलिप्तं मधुना गाढीकरणमुत्तमम्","text":"palāśodumbaraphalaṃ tilatailasamanvitam yonau viliptaṃ madhunā gāḍhīkaraṇamuttamam"},{"type":"verse","number":"128","sanskrit":"प्रसूता वनिता वृद्धकुक्षिह्रासाय सम्पिबेत् प्रातर्मथितसंमिश्रां त्रिसप्ताहात्कणाजटाम्","text":"prasūtā vanitā vṛddhakukṣihrāsāya sampibet prātarmathitasaṃmiśrāṃ trisaptāhātkaṇājaṭām"},{"type":"verse","number":"129","sanskrit":"प्रसूताया न पतिता जठरादपरा यदि तदा सा कुरुते शूलमाध्मानं वह्निमन्दताम्","text":"prasūtāyā na patitā jaṭharādaparā yadi tadā sā kurute śūlamādhmānaṃ vahnimandatām"},{"type":"verse","number":"130","sanskrit":"केशवेष्टितयाऽङ्गुल्या तस्याः कण्ठं प्रघर्षयेत् निर्मोककटुकाऽलाबू कृतबन्धनसर्षपः चूर्णितैः कटुतैलाक्तैर्धूपयेदभितो भगम्","text":"keśaveṣṭitayā'ṅgulyā tasyāḥ kaṇṭhaṃ pragharṣayet nirmokakaṭukā'lābū kṛtabandhanasarṣapaḥ cūrṇitaiḥ kaṭutailāktairdhūpayedabhito bhagam"},{"type":"verse","number":"131","sanskrit":"लाङ्गलीमूलकल्केन पाणिपादतलानि हि","text":"lāṅgalīmūlakalkena pāṇipādatalāni hi"},{"type":"verse","number":"132","sanskrit":"प्रलिम्पेत्सूतिका योषिदपरापातनाय वै हस्तं छिन्ननखं स्निग्धं सूतायोनौ शनैः क्षिपेत्","text":"pralimpetsūtikā yoṣidaparāpātanāya vai hastaṃ chinnanakhaṃ snigdhaṃ sūtāyonau śanaiḥ kṣipet"},{"type":"verse","number":"133","sanskrit":"अपरां तेन हस्तेन जनयित्री विनिर्हरेत् एवं निर्हृतशल्यां तां सिञ्चेदुष्णेन वारिणा ततोऽभ्यक्तशरीराया योनौ स्नेहं निधापयेत्","text":"aparāṃ tena hastena janayitrī vinirharet evaṃ nirhṛtaśalyāṃ tāṃ siñceduṣṇena vāriṇā tato'bhyaktaśarīrāyā yonau snehaṃ nidhāpayet"},{"type":"verse","number":"134","sanskrit":"वनितायाः प्रसूताया वातो रूक्षेण वर्द्धितः तीक्ष्णोष्णशोषितं रक्तं रुद्ध्वा ग्रन्थिं करोति हि","text":"vanitāyāḥ prasūtāyā vāto rūkṣeṇa varddhitaḥ tīkṣṇoṣṇaśoṣitaṃ raktaṃ ruddhvā granthiṃ karoti hi"},{"type":"verse","number":"135","sanskrit":"नाभ्यधः पार्श्वयोर्वस्तौ वस्तिमूर्द्धनि चापि वा ततश्च नाभौ वस्तौ च भवेच्छूलं तथोदरे","text":"nābhyadhaḥ pārśvayorvastau vastimūrddhani cāpi vā tataśca nābhau vastau ca bhavecchūlaṃ tathodare"},{"type":"verse","number":"136","sanskrit":"भवेत्पक्वाशयाध्मानं मूत्रसङ्गश्च जायते एतद्भिषग्भिरुदितं मक्कल्लामयलक्षणम्","text":"bhavetpakvāśayādhmānaṃ mūtrasaṅgaśca jāyate etadbhiṣagbhiruditaṃ makkallāmayalakṣaṇam"},{"type":"verse","number":"137","sanskrit":"सुचूर्णितं यवक्षारं पिबेत्कोष्णेन वारिणा सर्पिषा वा पिबेन्नारी मक्कल्लस्य निवृत्तये","text":"sucūrṇitaṃ yavakṣāraṃ pibetkoṣṇena vāriṇā sarpiṣā vā pibennārī makkallasya nivṛttaye"},{"type":"verse","number":"138","sanskrit":"पिप्पली पिप्पलीमूलं मरिचं गजपिप्पली नागरं चित्रकं चव्यं रेणुकैलाऽजमोदिकाः","text":"pippalī pippalīmūlaṃ maricaṃ gajapippalī nāgaraṃ citrakaṃ cavyaṃ reṇukailā'jamodikāḥ"},{"type":"verse","number":"139","sanskrit":"सर्षपो हिङ्गु भार्गी च पाठेन्द्र यवजीरकाः महानिम्बश्च मूर्वा च विषा तिक्ता विडङ्गकम्","text":"sarṣapo hiṅgu bhārgī ca pāṭhendra yavajīrakāḥ mahānimbaśca mūrvā ca viṣā tiktā viḍaṅgakam"},{"type":"verse","number":"140","sanskrit":"पिप्पल्यादिर्गणो ह्येष कफमारुतनाशनः क्वाथमेषां पिबेन्नारी लवणेन समन्वितम्","text":"pippalyādirgaṇo hyeṣa kaphamārutanāśanaḥ kvāthameṣāṃ pibennārī lavaṇena samanvitam"},{"type":"verse","number":"141","sanskrit":"गुल्मशूलज्वरहरं दीपनञ्चामपाचनम् मक्कल्लशूलगुल्मघ्नं कफानिलहरं परम्","text":"gulmaśūlajvaraharaṃ dīpanañcāmapācanam makkallaśūlagulmaghnaṃ kaphānilaharaṃ param"},{"type":"verse","number":"142","sanskrit":"त्रिकटुकचातुर्जातककुस्तुम्बुरुचूर्णसंयुक्तम् खादेद् गुडं पुराणं नित्यं मक्कल्लदलनाय","text":"trikaṭukacāturjātakakustumburucūrṇasaṃyuktam khāded guḍaṃ purāṇaṃ nityaṃ makkalladalanāya"},{"type":"verse","number":"143","sanskrit":"प्रसूता युक्तमाहारं विहारं च समाचरेत् व्यायामं मैथुनं क्रोधं शीतसेवाञ्च वर्जयेत्","text":"prasūtā yuktamāhāraṃ vihāraṃ ca samācaret vyāyāmaṃ maithunaṃ krodhaṃ śītasevāñca varjayet"},{"type":"verse","number":"144","sanskrit":"मिथ्याचारात्सूतिकाया यो व्याधिरुपजायते स कृच्छ्रसाध्योऽसाध्यो वा भवेत्तत्पथ्यमाचरेत्","text":"mithyācārātsūtikāyā yo vyādhirupajāyate sa kṛcchrasādhyo'sādhyo vā bhavettatpathyamācaret"},{"type":"verse","number":"145","sanskrit":"मिथ्योपचारात्संक्लेशाद्विषमाजीर्णभोजनात् सूतिकायास्तु ये रोगा जायन्ते दारुणाश्च ते","text":"mithyopacārātsaṃkleśādviṣamājīrṇabhojanāt sūtikāyāstu ye rogā jāyante dāruṇāśca te"},{"type":"verse","number":"146","sanskrit":"अङ्गमर्दो ज्वरः कासः पिपासा गुरुगात्रता शोथः शूलातिसारौ च सूतिकारोगलक्षणम्","text":"aṅgamardo jvaraḥ kāsaḥ pipāsā gurugātratā śothaḥ śūlātisārau ca sūtikārogalakṣaṇam"},{"type":"verse","number":"147","sanskrit":"ज्वरातीसारशोथाश्च शूलानाहबलक्षयाः तन्द्रा ऽरुचिप्रसेकाद्या वातश्लेष्मसमुद्भवाः १५९ कृच्छ्रसाध्या हि ते रोगाः क्षीणमांसबलाश्रिताः ते सर्वे सूतिकानाम्ना रोगास्ते चाप्युपद्र वाः","text":"jvarātīsāraśothāśca śūlānāhabalakṣayāḥ tandrā 'ruciprasekādyā vātaśleṣmasamudbhavāḥ 159 kṛcchrasādhyā hi te rogāḥ kṣīṇamāṃsabalāśritāḥ te sarve sūtikānāmnā rogāste cāpyupadra vāḥ"},{"type":"verse","number":"148","sanskrit":"सूतिकारोगशान्त्यर्थं कुर्याद्वातहरीं क्रियाम् दशमूलकृतं क्वाथं कोष्णं दद्याद् घृतान्वितम्","text":"sūtikārogaśāntyarthaṃ kuryādvātaharīṃ kriyām daśamūlakṛtaṃ kvāthaṃ koṣṇaṃ dadyād ghṛtānvitam"},{"type":"verse","number":"149","sanskrit":"अमृतानागरसहचरभद्रो त्कटपञ्चमूलकं जलदम् शृतशीतं मधुयुक्तं शमयत्यचिरेण सूतिकाऽतङ्कम्","text":"amṛtānāgarasahacarabhadro tkaṭapañcamūlakaṃ jaladam śṛtaśītaṃ madhuyuktaṃ śamayatyacireṇa sūtikā'taṅkam"},{"type":"verse","number":"150","sanskrit":"देवदारु वचा कुष्ठं पिप्पली विश्वभेषजम् भूनिम्बः कट्फलं मुस्तं तिक्ता धान्यहरीतकी","text":"devadāru vacā kuṣṭhaṃ pippalī viśvabheṣajam bhūnimbaḥ kaṭphalaṃ mustaṃ tiktā dhānyaharītakī"},{"type":"verse","number":"151","sanskrit":"गजकृष्णा सदुःस्पर्शा गोक्षुरुर्धन्वयासकः बृहत्यतिविषा छिन्ना कर्कटः कृष्णजीरकः","text":"gajakṛṣṇā saduḥsparśā gokṣururdhanvayāsakaḥ bṛhatyativiṣā chinnā karkaṭaḥ kṛṣṇajīrakaḥ"},{"type":"verse","number":"152","sanskrit":"समभागान्वितैरेतैः सिन्धुरामठसंयुतम् क्वाथमष्टावशेषं तु प्रसूतां पाययेत् स्त्रियम्","text":"samabhāgānvitairetaiḥ sindhurāmaṭhasaṃyutam kvāthamaṣṭāvaśeṣaṃ tu prasūtāṃ pāyayet striyam"},{"type":"verse","number":"153","sanskrit":"शूलकासज्वरश्वासमूर्च्छाकम्पशिरोऽत्तिभिः युक्तं प्रलापतृड्दाहतन्द्रा ऽतीसारवान्तिभिः","text":"śūlakāsajvaraśvāsamūrcchākampaśiro'ttibhiḥ yuktaṃ pralāpatṛḍdāhatandrā 'tīsāravāntibhiḥ"},{"type":"verse","number":"154","sanskrit":"निहन्ति सूतिकारोगं वातपित्तकफोद्भवम् कषायो देवदार्वादिः सूतायाः परमौषधम्","text":"nihanti sūtikārogaṃ vātapittakaphodbhavam kaṣāyo devadārvādiḥ sūtāyāḥ paramauṣadham"},{"type":"verse","number":"155","sanskrit":"जीरकं स्थूलजीरश्च शतपुष्पाद्वयं तथा यवानी चाजमोदा च धान्यकं मेथिकाऽपि च","text":"jīrakaṃ sthūlajīraśca śatapuṣpādvayaṃ tathā yavānī cājamodā ca dhānyakaṃ methikā'pi ca"},{"type":"verse","number":"156","sanskrit":"शुण्ठी कृष्णा कणामूलं चित्रकं हपुषाऽपि च बदरी गजचूर्णञ्च कुष्ठं कम्पिल्लकं तथा","text":"śuṇṭhī kṛṣṇā kaṇāmūlaṃ citrakaṃ hapuṣā'pi ca badarī gajacūrṇañca kuṣṭhaṃ kampillakaṃ tathā"},{"type":"verse","number":"157","sanskrit":"एतानि पलमात्राणि गुडं पलशतं मतम् क्षीरप्रस्थद्वयं दद्यात्सर्पिषः कुडवं तथा","text":"etāni palamātrāṇi guḍaṃ palaśataṃ matam kṣīraprasthadvayaṃ dadyātsarpiṣaḥ kuḍavaṃ tathā"},{"type":"verse","number":"158","sanskrit":"पञ्चजीरकपाकोऽय प्रसूतानां प्रशान्तये युज्यते सूतिकारोगे योनिरोगे ज्वरे क्षये","text":"pañcajīrakapāko'ya prasūtānāṃ praśāntaye yujyate sūtikāroge yoniroge jvare kṣaye"},{"type":"verse","number":"159","sanskrit":"कासे श्वासे पाण्डुरोगे कार्श्ये वातामयेषु च","text":"kāse śvāse pāṇḍuroge kārśye vātāmayeṣu ca"},{"type":"verse","number":"160","sanskrit":"आज्यं स्यात्पलयुग्ममत्र पयसः प्रस्थद्वयं खण्डतः पञ्चाशत्पलमत्र चूर्णितमथो प्रक्षिप्यते नागरम् प्रस्थार्धं गुडवद्विपाच्य विधिना मुष्टित्रयं धान्यका न्मिश्याः पञ्चपलं पलं कृमिरिपोः साजाजिजीरादपि","text":"ājyaṃ syātpalayugmamatra payasaḥ prasthadvayaṃ khaṇḍataḥ pañcāśatpalamatra cūrṇitamatho prakṣipyate nāgaram prasthārdhaṃ guḍavadvipācya vidhinā muṣṭitrayaṃ dhānyakā nmiśyāḥ pañcapalaṃ palaṃ kṛmiripoḥ sājājijīrādapi"},{"type":"verse","number":"161","sanskrit":"व्योषाम्भोददलोरगेन्द्र सुमनस्त्वग्द्रा विडीनां पलं पक्वं नागरखण्डसंज्ञकमिदं तत्सूतिकारोगहृत् तृटछर्दिज्वरदाहशोषशमनं सश्वासकासापहं प्लीहव्याधिविनाशनं कृमिहरं मन्दाग्निसन्दीपनम्","text":"vyoṣāmbhodadaloragendra sumanastvagdrā viḍīnāṃ palaṃ pakvaṃ nāgarakhaṇḍasaṃjñakamidaṃ tatsūtikārogahṛt tṛṭachardijvaradāhaśoṣaśamanaṃ saśvāsakāsāpahaṃ plīhavyādhivināśanaṃ kṛmiharaṃ mandāgnisandīpanam"},{"type":"verse","number":"162","sanskrit":"सर्वशः परिशुद्धा स्यात्स्निग्धपथ्याल्पभोजना स्वेदाभ्यङ्गपरा नित्यं भवेन्मासमतन्द्रि ता","text":"sarvaśaḥ pariśuddhā syātsnigdhapathyālpabhojanā svedābhyaṅgaparā nityaṃ bhavenmāsamatandri tā"},{"type":"verse","number":"163","sanskrit":"सक्षीरौ वाऽप्यदुग्धौ वा दोषः प्राप्य स्तनौ स्त्रियाः रक्तं मांसञ्च संदूष्य स्तनरोगाय कल्पते धमन्यः संवृतद्वाराः कन्यानां स्तनसंश्रिताः दोषाविसरणास्तासां न भवन्ति स्तनामयाः","text":"sakṣīrau vā'pyadugdhau vā doṣaḥ prāpya stanau striyāḥ raktaṃ māṃsañca saṃdūṣya stanarogāya kalpate dhamanyaḥ saṃvṛtadvārāḥ kanyānāṃ stanasaṃśritāḥ doṣāvisaraṇāstāsāṃ na bhavanti stanāmayāḥ"},{"type":"verse","number":"164","sanskrit":"तासामेव प्रसूतानां गर्भिणीनाञ्च ताः पुनः स्वभावादेव विवृता जायन्ते संस्रवन्त्यतः","text":"tāsāmeva prasūtānāṃ garbhiṇīnāñca tāḥ punaḥ svabhāvādeva vivṛtā jāyante saṃsravantyataḥ"},{"type":"verse","number":"165","sanskrit":"पञ्चानामपि तेषां तु हित्वा शोणितविद्र धिम् लक्षणानि समानानि ब्राह्यविद्र धिलक्षणैः","text":"pañcānāmapi teṣāṃ tu hitvā śoṇitavidra dhim lakṣaṇāni samānāni brāhyavidra dhilakṣaṇaiḥ"},{"type":"verse","number":"166","sanskrit":"शोथं स्तनोत्थितमवेक्ष्य भिषग्विदध्याद्यद्विद्र धावभिहितं बहुधा विधानम् आमे विदाहिनि तथैव च तस्य पाके यस्याः स्तनौ सततमेव च निग्रहात् तौ","text":"śothaṃ stanotthitamavekṣya bhiṣagvidadhyādyadvidra dhāvabhihitaṃ bahudhā vidhānam āme vidāhini tathaiva ca tasya pāke yasyāḥ stanau satatameva ca nigrahāt tau"},{"type":"verse","number":"167","sanskrit":"पित्तघ्नानि तु शीतानि द्र व्याण्यत्र प्रयोजयेत् जलौकोभिर्हरेद्र क्तं न स्तनावुपनाहयेत्","text":"pittaghnāni tu śītāni dra vyāṇyatra prayojayet jalaukobhirharedra ktaṃ na stanāvupanāhayet"},{"type":"verse","number":"168","sanskrit":"लेपो विशालामूलेन हन्ति पीडां स्तनोत्थिताम् निशाकनककल्काभ्यां लेपः प्रोक्तः स्तनार्त्तिहा","text":"lepo viśālāmūlena hanti pīḍāṃ stanotthitām niśākanakakalkābhyāṃ lepaḥ proktaḥ stanārttihā"},{"type":"verse","number":"169","sanskrit":"लेपो निहन्ति मूलं वन्ध्याकर्कोटिकाभवं शीघ्रम्","text":"lepo nihanti mūlaṃ vandhyākarkoṭikābhavaṃ śīghram"},{"type":"verse","number":"170","sanskrit":"इति सप्ततितमो योनिरोगाधिकारः समाप्तः ७० इति स्त्रीणां रोगाधिकाराः समाप्तः","text":"iti saptatitamo yonirogādhikāraḥ samāptaḥ 70 iti strīṇāṃ rogādhikārāḥ samāptaḥ"}]},{"sthana":"Уттаракханда","number":70,"lang":"sa","content":[{"type":"heading","heading":"Баларога — детские болезни"},{"type":"verse","number":"1","sanskrit":"बालग्रहा अनाचारात्पीडयन्ति शिशुं यतः तस्मात्तदुपसर्गेभ्यो रक्षेद्बालं प्रयत्नतः","text":"bālagrahā anācārātpīḍayanti śiśuṃ yataḥ tasmāttadupasargebhyo rakṣedbālaṃ prayatnataḥ"},{"type":"verse","number":"2","sanskrit":"स्कन्दग्रहस्तु प्रथमः स्कन्दापस्मार एव च शकुनी रेवती चैव पूतना चान्धपूतना","text":"skandagrahastu prathamaḥ skandāpasmāra eva ca śakunī revatī caiva pūtanā cāndhapūtanā"},{"type":"verse","number":"3","sanskrit":"पूतना शीतपूर्वा च तथैव मुखमण्डिका नवमो नैगमेयश्च प्रोक्ता बालग्रहा अमी","text":"pūtanā śītapūrvā ca tathaiva mukhamaṇḍikā navamo naigameyaśca proktā bālagrahā amī"},{"type":"verse","number":"4","sanskrit":"नव स्कन्दादयः प्रोक्ता बालानां ये ग्रहा अमी श्रीमन्तो दिव्यवपुषो नारीपुरुषविग्रहाः","text":"nava skandādayaḥ proktā bālānāṃ ye grahā amī śrīmanto divyavapuṣo nārīpuruṣavigrahāḥ"},{"type":"verse","number":"5","sanskrit":"एते स्कन्दस्य रक्षाऽथ कृत्तिकोमाऽग्निशूलिभिः सृष्टाः शरवणस्थस्य रक्षितस्य स्वतेजसा","text":"ete skandasya rakṣā'tha kṛttikomā'gniśūlibhiḥ sṛṣṭāḥ śaravaṇasthasya rakṣitasya svatejasā"},{"type":"verse","number":"6","sanskrit":"स्कन्दः सृष्टो भगवता देवेन त्रिपुरारिणा बिभर्ति चापरां संज्ञां कुमार इति स ग्रहः","text":"skandaḥ sṛṣṭo bhagavatā devena tripurāriṇā bibharti cāparāṃ saṃjñāṃ kumāra iti sa grahaḥ"},{"type":"verse","number":"7","sanskrit":"स्कन्दापस्मारसंज्ञो यः सोऽग्निना तत्समद्युतिः स च स्कन्दसखो नाम्ना विशाख इति चोच्यते","text":"skandāpasmārasaṃjño yaḥ so'gninā tatsamadyutiḥ sa ca skandasakho nāmnā viśākha iti cocyate"},{"type":"verse","number":"8","sanskrit":"ग्रहाः स्त्रीविग्रहा एते नानारूपाः प्रकीर्त्तिताः गङ्गोमाकृत्तिकानां ते भागा राजसतामसाः","text":"grahāḥ strīvigrahā ete nānārūpāḥ prakīrttitāḥ gaṅgomākṛttikānāṃ te bhāgā rājasatāmasāḥ"},{"type":"verse","number":"9","sanskrit":"नैगमेयस्तु पार्वत्या सृष्टो मेषाननो ग्रहः कुमारधारी देवस्य गुहस्यात्मसमोऽस्ति वै","text":"naigameyastu pārvatyā sṛṣṭo meṣānano grahaḥ kumāradhārī devasya guhasyātmasamo'sti vai"},{"type":"verse","number":"10","sanskrit":"ततो भगवता स्कन्दे सुरसेनापतौ कृते उपतस्थुर्ग्रहा एते दीप्तशक्तिधरं गुहम्","text":"tato bhagavatā skande surasenāpatau kṛte upatasthurgrahā ete dīptaśaktidharaṃ guham"},{"type":"verse","number":"11","sanskrit":"ऊचुः प्राञ्जलयश्चैनं वत्तिर्नो दीयतामिति तेषामर्थे ततः स्कन्दः शिवं देवमचोदयत्","text":"ūcuḥ prāñjalayaścainaṃ vattirno dīyatāmiti teṣāmarthe tataḥ skandaḥ śivaṃ devamacodayat"},{"type":"verse","number":"12","sanskrit":"ततो ग्रहांस्तानुवाच भगवान्भगनेत्रहृत् तैर्यग्योनिं मानुषं च दैवञ्च त्रितयं जगत्","text":"tato grahāṃstānuvāca bhagavānbhaganetrahṛt tairyagyoniṃ mānuṣaṃ ca daivañca tritayaṃ jagat"},{"type":"verse","number":"13","sanskrit":"परस्परोपकारेण वर्त्तते धार्यते तथा देवा नरान्प्रीणयन्ति तैर्यग्योनींस्तथैव च","text":"parasparopakāreṇa varttate dhāryate tathā devā narānprīṇayanti tairyagyonīṃstathaiva ca"},{"type":"verse","number":"14","sanskrit":"यथाकालं प्रवृत्तैस्तु ऊष्मवर्षहिमानिलैः इज्याऽञ्जलिनमस्कारैर्जपहोमैस्तथैव च","text":"yathākālaṃ pravṛttaistu ūṣmavarṣahimānilaiḥ ijyā'ñjalinamaskārairjapahomaistathaiva ca"},{"type":"verse","number":"15","sanskrit":"सम्यक्प्रयुक्तैश्च नराः प्रीणयन्त्यपि देवताः भागधेयविभक्तञ्च शेषं किञ्चिन्न विद्यते","text":"samyakprayuktaiśca narāḥ prīṇayantyapi devatāḥ bhāgadheyavibhaktañca śeṣaṃ kiñcinna vidyate"},{"type":"verse","number":"16","sanskrit":"तद्युष्माकं शुभा वृत्तिर्बालेष्वेव भविष्यति","text":"tadyuṣmākaṃ śubhā vṛttirbāleṣveva bhaviṣyati"},{"type":"verse","number":"17","sanskrit":"कुलेषु येषु नेज्यन्ते देवाः पितर एव च ब्राह्मणः साधवो वाऽपि गुरवोऽतिथयस्तथा","text":"kuleṣu yeṣu nejyante devāḥ pitara eva ca brāhmaṇaḥ sādhavo vā'pi guravo'tithayastathā"},{"type":"verse","number":"18","sanskrit":"निवृत्तशौचाचारेषु तथा कुत्सितवृत्तिषु निवृत्तभिक्षाबलिषु भग्नकांस्यगृहेषु वा","text":"nivṛttaśaucācāreṣu tathā kutsitavṛttiṣu nivṛttabhikṣābaliṣu bhagnakāṃsyagṛheṣu vā"},{"type":"verse","number":"19","sanskrit":"ते वै बालांश्च तांस्तान् हि ग्रहा हिंसन्त्यशङ्किताः तत्र वो विपुला वृत्तिः पूजा चैव भविष्यति","text":"te vai bālāṃśca tāṃstān hi grahā hiṃsantyaśaṅkitāḥ tatra vo vipulā vṛttiḥ pūjā caiva bhaviṣyati"},{"type":"verse","number":"20","sanskrit":"एवं ग्रहाः समुत्पन्ना बालान् हिंसन्ति चाप्यतः ग्रहोपसृष्टा बालाः स्युर्दुश्चिकित्स्यतमास्ततः","text":"evaṃ grahāḥ samutpannā bālān hiṃsanti cāpyataḥ grahopasṛṣṭā bālāḥ syurduścikitsyatamāstataḥ"},{"type":"verse","number":"21","sanskrit":"क्षणादुद्विजते बालः क्षणात् त्रस्यति रोदिति नखैर्दन्तैर्दारयति धात्रीमात्मानमेव च","text":"kṣaṇādudvijate bālaḥ kṣaṇāt trasyati roditi nakhairdantairdārayati dhātrīmātmānameva ca"},{"type":"verse","number":"22","sanskrit":"ऊर्ध्वं निरीक्षते दन्तान्खादेत्कूजति जृम्भते भ्रुवौ क्षिपति दष्टौष्ठः फेनं वमति चासकृत्","text":"ūrdhvaṃ nirīkṣate dantānkhādetkūjati jṛmbhate bhruvau kṣipati daṣṭauṣṭhaḥ phenaṃ vamati cāsakṛt"},{"type":"verse","number":"23","sanskrit":"क्षामोऽति निशि जागर्त्ति शूनाङ्गो भिन्नविट्स्वरः मत्स्यशोणितगन्धश्च न चाश्नाति यथा पुरा","text":"kṣāmo'ti niśi jāgartti śūnāṅgo bhinnaviṭsvaraḥ matsyaśoṇitagandhaśca na cāśnāti yathā purā"},{"type":"verse","number":"24","sanskrit":"दुर्बलो मलिनाङ्गश्च नष्टसंज्ञः प्रजायते सामान्यग्रहजुष्टस्य लक्षणं समुदाहृतम्","text":"durbalo malināṅgaśca naṣṭasaṃjñaḥ prajāyate sāmānyagrahajuṣṭasya lakṣaṇaṃ samudāhṛtam"},{"type":"verse","number":"25","sanskrit":"स्रस्ताङ्गः क्षतजसगन्धिकस्तनद्विड् वक्रास्यो हतचलितैकपक्ष्मनेत्रः उद्विग्नः ससलिलचक्षुरल्परोदी स्कन्दार्त्तो भवति च गाढमुष्टिवर्चाः","text":"srastāṅgaḥ kṣatajasagandhikastanadviḍ vakrāsyo hatacalitaikapakṣmanetraḥ udvignaḥ sasalilacakṣuralparodī skandārtto bhavati ca gāḍhamuṣṭivarcāḥ"},{"type":"verse","number":"26","sanskrit":"निःसंज्ञो भवति पुनर्लभेत संज्ञां संस्तब्धः करचरणैश्च नृत्यतीव विण्मूत्रे सृजति चिरेण जृम्भमाणः फेनं वा सृजति च तत्सखाभिजुष्टः","text":"niḥsaṃjño bhavati punarlabheta saṃjñāṃ saṃstabdhaḥ karacaraṇaiśca nṛtyatīva viṇmūtre sṛjati cireṇa jṛmbhamāṇaḥ phenaṃ vā sṛjati ca tatsakhābhijuṣṭaḥ"},{"type":"verse","number":"27","sanskrit":"स्रस्ताङ्गो भयचकितो विहङ्गगन्धिः सास्रवव्रणपरिपीडितः समन्तात् स्फोटैश्च प्रचिततनुः सदाहपाकैर्विज्ञेयो भवति शिशुः क्षतः शकुन्या","text":"srastāṅgo bhayacakito vihaṅgagandhiḥ sāsravavraṇaparipīḍitaḥ samantāt sphoṭaiśca pracitatanuḥ sadāhapākairvijñeyo bhavati śiśuḥ kṣataḥ śakunyā"},{"type":"verse","number":"28","sanskrit":"रक्तास्यो हरितमलोऽतिपाण्डुदेहः श्यावो वा मुखकरपाकवेदनाऽत्त गृह्णाति व्यथिततनुश्च कर्णनासं रेवत्या भृशमभिपीडितः कुमारः","text":"raktāsyo haritamalo'tipāṇḍudehaḥ śyāvo vā mukhakarapākavedanā'tta gṛhṇāti vyathitatanuśca karṇanāsaṃ revatyā bhṛśamabhipīḍitaḥ kumāraḥ"},{"type":"verse","number":"29","sanskrit":"विट्स्रावी स्वपिति न वासरे न रात्रौ विड्भिन्नं विसृजति काकतुल्यगन्धः छर्द्यार्त्तो हृषिततनूरुहः कुमारस्तृष्णालुर्भवति च पूतनागृहीतः","text":"viṭsrāvī svapiti na vāsare na rātrau viḍbhinnaṃ visṛjati kākatulyagandhaḥ chardyārtto hṛṣitatanūruhaḥ kumārastṛṣṇālurbhavati ca pūtanāgṛhītaḥ"},{"type":"verse","number":"30","sanskrit":"योद्वेष्टि स्तनमतिसारकासहिक्काछर्दीभिर्ज्वरसहिताभिरर्द्यमानः दुर्वर्णः सततमथापि योऽस्रगन्धिस्तं ब्रूयाद्भिषगथ चान्धपूतनाऽत्तम्","text":"yodveṣṭi stanamatisārakāsahikkāchardībhirjvarasahitābhirardyamānaḥ durvarṇaḥ satatamathāpi yo'sragandhistaṃ brūyādbhiṣagatha cāndhapūtanā'ttam"},{"type":"verse","number":"31","sanskrit":"आक्रन्दत्यभिचकितं सुवेपमानः संलीनो भवति व्यथाऽन्त्रकूजयुक्तः स्रस्ताङ्गो भृशमतिशीर्यते च शीतात् तं ब्रूयाद्भिषगथ शीतपूतनाऽत्तम्","text":"ākrandatyabhicakitaṃ suvepamānaḥ saṃlīno bhavati vyathā'ntrakūjayuktaḥ srastāṅgo bhṛśamatiśīryate ca śītāt taṃ brūyādbhiṣagatha śītapūtanā'ttam"},{"type":"verse","number":"32","sanskrit":"म्लानाङ्गः सरुधिरपाणिपादवक्त्रो बह्वाशी कलुषशिरावृतोदरो यः सोद्वेगो भवति च मूत्रतुल्यगन्धिः स ज्ञेयः शिशुरथ वक्त्रमण्डिकाऽत्त","text":"mlānāṅgaḥ sarudhirapāṇipādavaktro bahvāśī kaluṣaśirāvṛtodaro yaḥ sodvego bhavati ca mūtratulyagandhiḥ sa jñeyaḥ śiśuratha vaktramaṇḍikā'tta"},{"type":"verse","number":"33","sanskrit":"यः फेनं वमति विनम्यते च मध्ये सोद्वेगो विहसति चोर्ध्वमीक्षमाणः कूजेच्च प्रततमथो वसासगन्धिर्निःसंज्ञो भवति स नैगमेयजुष्टः","text":"yaḥ phenaṃ vamati vinamyate ca madhye sodvego vihasati cordhvamīkṣamāṇaḥ kūjecca pratatamatho vasāsagandhirniḥsaṃjño bhavati sa naigameyajuṣṭaḥ"},{"type":"verse","number":"34","sanskrit":"सहामुण्डितिकोदीच्यक्वाथस्नानं ग्रहापहम्","text":"sahāmuṇḍitikodīcyakvāthasnānaṃ grahāpaham"},{"type":"verse","number":"35","sanskrit":"सप्तच्छदामय निशाचन्दनैश्चानुलेपनम् सर्पत्वग्लशुनं मूर्वा सर्षपारिष्टपल्लवाः","text":"saptacchadāmaya niśācandanaiścānulepanam sarpatvaglaśunaṃ mūrvā sarṣapāriṣṭapallavāḥ"},{"type":"verse","number":"36","sanskrit":"विडालविडजालोम मेषशृङ्गी वचा मधु धूपः शिशोर्ज्वरघ्नोऽयमशेषग्रहनाशनः बालशान्तीष्टकर्माणि कार्याणि ग्रहशान्तये","text":"viḍālaviḍajāloma meṣaśṛṅgī vacā madhu dhūpaḥ śiśorjvaraghno'yamaśeṣagrahanāśanaḥ bālaśāntīṣṭakarmāṇi kāryāṇi grahaśāntaye"},{"type":"verse","number":"37","sanskrit":"वचा कुष्ठं तथा ब्राह्मी सिद्धार्थकमथापिच सारिवा सैन्धवं चैव पिप्पली घृतमष्टमम् सिद्धं घृतमिदं मेध्यं पिबेत्प्रातर्दिने दिने दृढस्मृतिः क्षिप्रमेधाः कुमारो बुद्धिमान्भवेत्","text":"vacā kuṣṭhaṃ tathā brāhmī siddhārthakamathāpica sārivā saindhavaṃ caiva pippalī ghṛtamaṣṭamam siddhaṃ ghṛtamidaṃ medhyaṃ pibetprātardine dine dṛḍhasmṛtiḥ kṣipramedhāḥ kumāro buddhimānbhavet"},{"type":"verse","number":"38","sanskrit":"न पिशाचा न रक्षांसि न भूता न च मातरः न भवन्ति कुमाराणां पिबतामष्टमङ्गलम्","text":"na piśācā na rakṣāṃsi na bhūtā na ca mātaraḥ na bhavanti kumārāṇāṃ pibatāmaṣṭamaṅgalam"},{"type":"verse","number":"39","sanskrit":"विशिष्टग्रहजुष्टबालकचिकित्सा स्कन्दग्रहोपसृष्टस्य कुमारस्य प्रशान्तये वातघ्नद्रुमपत्राणां क्वाथेन परिषेचनम्","text":"viśiṣṭagrahajuṣṭabālakacikitsā skandagrahopasṛṣṭasya kumārasya praśāntaye vātaghnadrumapatrāṇāṃ kvāthena pariṣecanam"},{"type":"verse","number":"40","sanskrit":"देवदारुणि रास्नायां मधुरेषु गणेषु च सिद्धं सर्पिश्च सक्षीरं पातुमस्मै प्रदापयेत्","text":"devadāruṇi rāsnāyāṃ madhureṣu gaṇeṣu ca siddhaṃ sarpiśca sakṣīraṃ pātumasmai pradāpayet"},{"type":"verse","number":"41","sanskrit":"सर्षपाः सर्पनिर्मोको वचा काकादनी घृतम् उष्ट्राजाविगवां चापि रोमाण्युद्धूपनं भवेत्","text":"sarṣapāḥ sarpanirmoko vacā kākādanī ghṛtam uṣṭrājāvigavāṃ cāpi romāṇyuddhūpanaṃ bhavet"},{"type":"verse","number":"42","sanskrit":"सोमवल्लीमिन्द्र वृक्षं वन्दाकं बिल्वजं शमीम् मृगादन्याश्च मूलानि ग्रथितानि विधारयेत्","text":"somavallīmindra vṛkṣaṃ vandākaṃ bilvajaṃ śamīm mṛgādanyāśca mūlāni grathitāni vidhārayet"},{"type":"verse","number":"43","sanskrit":"रक्तानि माल्यानि तथा पताका रक्ताश्च गन्धान् विविधांश्च भक्ष्यान् घण्टां च देवाय बलि निवेद्य सकुक्कुटं स्कन्दगृहे हिताय","text":"raktāni mālyāni tathā patākā raktāśca gandhān vividhāṃśca bhakṣyān ghaṇṭāṃ ca devāya bali nivedya sakukkuṭaṃ skandagṛhe hitāya"},{"type":"verse","number":"44","sanskrit":"स्नानं त्रिरात्रं निशि चत्वरेषु कुर्यात्परं शालियवैर्नवैस्तु अं गायत्रिपूताभिरथाद्भिरग्निं प्रज्वालयेदाहुतिभिश्च धीमान्","text":"snānaṃ trirātraṃ niśi catvareṣu kuryātparaṃ śāliyavairnavaistu aṃ gāyatripūtābhirathādbhiragniṃ prajvālayedāhutibhiśca dhīmān"},{"type":"verse","number":"45","sanskrit":"रक्षामतः प्रवक्ष्यामि बालानां पापनाशिनीम् अहन्यहनि कर्त्तव्या या भिषग्भिरतन्द्रि तैः","text":"rakṣāmataḥ pravakṣyāmi bālānāṃ pāpanāśinīm ahanyahani karttavyā yā bhiṣagbhiratandri taiḥ"},{"type":"verse","number":"46","sanskrit":"तपसां तेजसां चैव यशसां वपुषां तथा निधानं योऽव्ययो देवः स ते स्कन्दः प्रसीदतु","text":"tapasāṃ tejasāṃ caiva yaśasāṃ vapuṣāṃ tathā nidhānaṃ yo'vyayo devaḥ sa te skandaḥ prasīdatu"},{"type":"verse","number":"47","sanskrit":"ग्रहः सेनापतिर्देवो देवसेनापतिर्विभुः देवसेनारिपुहरः पातु त्वां भगवान्गुहः","text":"grahaḥ senāpatirdevo devasenāpatirvibhuḥ devasenāripuharaḥ pātu tvāṃ bhagavānguhaḥ"},{"type":"verse","number":"48","sanskrit":"देवदेवस्य महतः पावकस्य च यः सुतः गङ्गोमाकृत्तिकानां च स ते शर्म प्रयच्छतु","text":"devadevasya mahataḥ pāvakasya ca yaḥ sutaḥ gaṅgomākṛttikānāṃ ca sa te śarma prayacchatu"},{"type":"verse","number":"49","sanskrit":"रक्तमाल्याम्बरधरो रक्तचन्दनभूषितः रक्तदिव्यवपुर्देवः पातु त्वां क्रौञ्चसूदनः","text":"raktamālyāmbaradharo raktacandanabhūṣitaḥ raktadivyavapurdevaḥ pātu tvāṃ krauñcasūdanaḥ"},{"type":"verse","number":"50","sanskrit":"बिल्वः शिरीषो गोलोमी सुरसाऽदिश्च यो गणः परिषेके प्रयोक्तव्यः स्कन्दापस्मारशान्तये","text":"bilvaḥ śirīṣo golomī surasā'diśca yo gaṇaḥ pariṣeke prayoktavyaḥ skandāpasmāraśāntaye"},{"type":"verse","number":"51","sanskrit":"सुरसा श्वेतसुरसा पाठा फज्जी फणिज्जकः सौगन्धिकं भूस्तृणको राजिका श्वेतबर्बरी","text":"surasā śvetasurasā pāṭhā phajjī phaṇijjakaḥ saugandhikaṃ bhūstṛṇako rājikā śvetabarbarī"},{"type":"verse","number":"52","sanskrit":"कट्फलं खरपुष्पा च कासमर्दश्च शल्लकी विडङ्गमथ निर्गुण्डी कर्णिकार उदुम्बरः","text":"kaṭphalaṃ kharapuṣpā ca kāsamardaśca śallakī viḍaṅgamatha nirguṇḍī karṇikāra udumbaraḥ"},{"type":"verse","number":"53","sanskrit":"बला च काकमाची च तथा च विषमुष्टिका कफकृमिहरः ख्यातः सुरसाऽदिरयं गणः","text":"balā ca kākamācī ca tathā ca viṣamuṣṭikā kaphakṛmiharaḥ khyātaḥ surasā'dirayaṃ gaṇaḥ"},{"type":"verse","number":"54","sanskrit":"अष्टमूत्रविपक्वं च तैलमभ्यञ्जने हितम्","text":"aṣṭamūtravipakvaṃ ca tailamabhyañjane hitam"},{"type":"verse","number":"55","sanskrit":"गोऽजाविमहिषाश्वानां खरोष्ट्रकरिणां तथा मूत्राष्टकमिदं ख्यातं सर्वशास्त्रेषु सम्मतम्","text":"go'jāvimahiṣāśvānāṃ kharoṣṭrakariṇāṃ tathā mūtrāṣṭakamidaṃ khyātaṃ sarvaśāstreṣu sammatam"},{"type":"verse","number":"56","sanskrit":"क्षीरवृक्षकषायेण काकोल्यादिगणेन च विपक्तव्यं घृतं पश्चाद्दातव्यं पयसा सह","text":"kṣīravṛkṣakaṣāyeṇa kākolyādigaṇena ca vipaktavyaṃ ghṛtaṃ paścāddātavyaṃ payasā saha"},{"type":"verse","number":"57","sanskrit":"काकोली क्षीरकाकोली जीवकर्षभकौ तथा ॠद्धिर्वृद्धिस्तथा मेदा महामेदा गुडूचिका","text":"kākolī kṣīrakākolī jīvakarṣabhakau tathā ṝddhirvṛddhistathā medā mahāmedā guḍūcikā"},{"type":"verse","number":"58","sanskrit":"मुद्गपणी माषपर्णी पद्मकं वंशलोचना शृङ्गी प्रपौण्डरीकञ्च जीवन्ती मधुयष्टिका","text":"mudgapaṇī māṣaparṇī padmakaṃ vaṃśalocanā śṛṅgī prapauṇḍarīkañca jīvantī madhuyaṣṭikā"},{"type":"verse","number":"59","sanskrit":"द्रा क्षा चेति गणो नाम्ना काकोल्यादिरुदीरितः स्तन्यकृद् बृंहणो वृष्यः पित्तरक्तमलापहः","text":"drā kṣā ceti gaṇo nāmnā kākolyādirudīritaḥ stanyakṛd bṛṃhaṇo vṛṣyaḥ pittaraktamalāpahaḥ"},{"type":"verse","number":"60","sanskrit":"उत्सादनं वचा हिङ्गुयुक्तमत्र प्रकीर्त्तितम् गृध्रोलूकपुरीषाणि केशा हस्तिनखो घृतम्","text":"utsādanaṃ vacā hiṅguyuktamatra prakīrttitam gṛdhrolūkapurīṣāṇi keśā hastinakho ghṛtam"},{"type":"verse","number":"61","sanskrit":"वृषभस्य च रोमाणि योज्यान्युद्धूपने सदा अनन्तां कुक्कुटीं बिम्बीं मर्कटीञ्चापि धारयेत्","text":"vṛṣabhasya ca romāṇi yojyānyuddhūpane sadā anantāṃ kukkuṭīṃ bimbīṃ markaṭīñcāpi dhārayet"},{"type":"verse","number":"62","sanskrit":"पक्वापक्वानि मांसानि प्रसन्ना रुधिरं पयः मुद्गौदनं निवेद्याथ स्कन्दापस्मारिणे वटे","text":"pakvāpakvāni māṃsāni prasannā rudhiraṃ payaḥ mudgaudanaṃ nivedyātha skandāpasmāriṇe vaṭe"},{"type":"verse","number":"63","sanskrit":"चतुष्पथे कारयेच्च स्नानं तेन ततः पठेत्","text":"catuṣpathe kārayecca snānaṃ tena tataḥ paṭhet"},{"type":"verse","number":"64","sanskrit":"स्कन्दापस्मारसंज्ञो यः स्कन्दस्य दयितः सखा विशाखः स शिशोरस्य शिवायास्तु शुभाननः","text":"skandāpasmārasaṃjño yaḥ skandasya dayitaḥ sakhā viśākhaḥ sa śiśorasya śivāyāstu śubhānanaḥ"},{"type":"verse","number":"65","sanskrit":"शकुनिग्रहजुष्टस्य कार्यं वैद्येन जानता वेतसाम्रकपित्थानां क्वाथेन परिषेचनम्","text":"śakunigrahajuṣṭasya kāryaṃ vaidyena jānatā vetasāmrakapitthānāṃ kvāthena pariṣecanam"},{"type":"verse","number":"66","sanskrit":"ह्रीवेरमधुकोशीरसारिवोत्पलपद्मकैः लोध्रप्रियङ्गुमञ्जिष्ठागैरिकैः प्रदिहेच्छिशुम्","text":"hrīveramadhukośīrasārivotpalapadmakaiḥ lodhrapriyaṅgumañjiṣṭhāgairikaiḥ pradihecchiśum"},{"type":"verse","number":"67","sanskrit":"स्कन्दग्रहोक्ता धूपाश्च हिता अत्र भवन्ति हि स्कन्दापस्मारशमनं घृतमत्रापि पूजितम्","text":"skandagrahoktā dhūpāśca hitā atra bhavanti hi skandāpasmāraśamanaṃ ghṛtamatrāpi pūjitam"},{"type":"verse","number":"68","sanskrit":"शतावरीमृगैर्वारुनागदन्तीनिदिग्धिकाम् लक्ष्मणां सहदेवीं च बृहतीं चापि धारयेत्","text":"śatāvarīmṛgairvārunāgadantīnidigdhikām lakṣmaṇāṃ sahadevīṃ ca bṛhatīṃ cāpi dhārayet"},{"type":"verse","number":"69","sanskrit":"तिलतण्डुलकं माल्यं हरितालं मनः शिला बलिरेष करञ्जेतु निवेद्यो नियतात्मना","text":"tilataṇḍulakaṃ mālyaṃ haritālaṃ manaḥ śilā balireṣa karañjetu nivedyo niyatātmanā"},{"type":"verse","number":"70","sanskrit":"निकुञ्जे च प्रयोक्तव्यं स्नानमस्य यथाविधि श्वेताशिरीषगन्धाश्मधवगुग्गुलुसर्षपैः","text":"nikuñje ca prayoktavyaṃ snānamasya yathāvidhi śvetāśirīṣagandhāśmadhavaguggulusarṣapaiḥ"},{"type":"verse","number":"71","sanskrit":"सिद्धमभ्यञ्जने तैलं धारणं पूर्वमेव तु शुकुनिग्रहशान्त्यर्थं प्रदेहं कारयेद्धितम्","text":"siddhamabhyañjane tailaṃ dhāraṇaṃ pūrvameva tu śukunigrahaśāntyarthaṃ pradehaṃ kārayeddhitam"},{"type":"verse","number":"72","sanskrit":"कुर्याच्च विविधां पूजां शकुन्याः कुसुमैः शुभैः निकुम्भोक्तेन विधिना स्नापयेत्तं ततः पठेत्","text":"kuryācca vividhāṃ pūjāṃ śakunyāḥ kusumaiḥ śubhaiḥ nikumbhoktena vidhinā snāpayettaṃ tataḥ paṭhet"},{"type":"verse","number":"73","sanskrit":"अन्तरिक्षचरा देवी सर्वालङ्कारभूषिता अधोमुखी सूक्ष्मतुण्डा शकुनी ते प्रसीदतु","text":"antarikṣacarā devī sarvālaṅkārabhūṣitā adhomukhī sūkṣmatuṇḍā śakunī te prasīdatu"},{"type":"verse","number":"74","sanskrit":"दुर्दर्शना महामाया पिङ्गाङ्गी भैरवस्वरा लम्बोदरी शङ्कुकर्णी शकुनी ते प्रसीदतु","text":"durdarśanā mahāmāyā piṅgāṅgī bhairavasvarā lambodarī śaṅkukarṇī śakunī te prasīdatu"},{"type":"verse","number":"75","sanskrit":"अश्वगन्धाऽजशृङ्गी च सारिवाऽथ पुनर्नवा सहा विदारी ह्येतासां क्वाथेन परिषेचनम्","text":"aśvagandhā'jaśṛṅgī ca sārivā'tha punarnavā sahā vidārī hyetāsāṃ kvāthena pariṣecanam"},{"type":"verse","number":"76","sanskrit":"तैलमभ्यञ्जने कार्यं कुष्ठे सर्जरसे तथा पलङ्कषायां नलदे तथा गौरकदम्बके","text":"tailamabhyañjane kāryaṃ kuṣṭhe sarjarase tathā palaṅkaṣāyāṃ nalade tathā gaurakadambake"},{"type":"verse","number":"77","sanskrit":"धवाश्वकर्णककुभशल्लकीतिन्दुकेषु च काकोल्यादौ गणे चापि सिद्धं सर्पिः पिबेच्छिशुः","text":"dhavāśvakarṇakakubhaśallakītindukeṣu ca kākolyādau gaṇe cāpi siddhaṃ sarpiḥ pibecchiśuḥ"},{"type":"verse","number":"78","sanskrit":"कुलत्थं शङ्खचूर्णञ्च प्रदेहः साश्वगन्धिकः गृध्रोलूकपुरीषाणि यवान् यवफलो घृतम् सन्ध्ययोरुभयोः कार्यमेतदुद्धूपनं शिशोः","text":"kulatthaṃ śaṅkhacūrṇañca pradehaḥ sāśvagandhikaḥ gṛdhrolūkapurīṣāṇi yavān yavaphalo ghṛtam sandhyayorubhayoḥ kāryametaduddhūpanaṃ śiśoḥ"},{"type":"verse","number":"79","sanskrit":"शुक्लाः सुमनसो लाजाः पयः शाल्योदनं दधि बलिर्निवेद्यो गोतीर्थे रेवत्यै प्रयतात्मना","text":"śuklāḥ sumanaso lājāḥ payaḥ śālyodanaṃ dadhi balirnivedyo gotīrthe revatyai prayatātmanā"},{"type":"verse","number":"80","sanskrit":"स्नानं धात्रीकुमाराभ्यां सङ्गमे कारयेद्भिषक् नानाशस्त्रधरा देवी चित्रमाल्यानुलेपना","text":"snānaṃ dhātrīkumārābhyāṃ saṅgame kārayedbhiṣak nānāśastradharā devī citramālyānulepanā"},{"type":"verse","number":"81","sanskrit":"चॄलत्कुण्डलिनी श्यामा रेवती ते प्रसीदतु उपासते यां सततं देव्यो विविधभूषणाः","text":"cṝlatkuṇḍalinī śyāmā revatī te prasīdatu upāsate yāṃ satataṃ devyo vividhabhūṣaṇāḥ"},{"type":"verse","number":"82","sanskrit":"लम्बा कराला विनता तथैव बहुपुत्रिका रेवती शुष्कनासा च तुभ्यं देवी प्रसीदतु","text":"lambā karālā vinatā tathaiva bahuputrikā revatī śuṣkanāsā ca tubhyaṃ devī prasīdatu"},{"type":"verse","number":"83","sanskrit":"कपोतवङ्का श्योनाको वरुणः पारिभद्र कः आस्फोता चैव योज्याः स्युर्बालानां परिषेचने","text":"kapotavaṅkā śyonāko varuṇaḥ pāribhadra kaḥ āsphotā caiva yojyāḥ syurbālānāṃ pariṣecane"},{"type":"verse","number":"84","sanskrit":"नवा पयस्या गोलोमी हरितालं मनः शिला कुष्ठं सर्जरसश्चैव तैलार्थे कल्क इष्यते","text":"navā payasyā golomī haritālaṃ manaḥ śilā kuṣṭhaṃ sarjarasaścaiva tailārthe kalka iṣyate"},{"type":"verse","number":"85","sanskrit":"हितं घृतं तुगाक्षीर्या संसिद्धं मधुकेन च कुष्ठंतालीसखदिराः स्पन्दनोऽजुन एव च","text":"hitaṃ ghṛtaṃ tugākṣīryā saṃsiddhaṃ madhukena ca kuṣṭhaṃtālīsakhadirāḥ spandano'juna eva ca"},{"type":"verse","number":"86","sanskrit":"पनसः ककुभश्चापि मज्जानो बदरस्य च कुंक्कुटास्थि घृतं चापि धूपनं सह सर्षपैः","text":"panasaḥ kakubhaścāpi majjāno badarasya ca kuṃkkuṭāsthi ghṛtaṃ cāpi dhūpanaṃ saha sarṣapaiḥ"},{"type":"verse","number":"87","sanskrit":"काकादनीं चित्रफलां बिम्बीं गुञ्जाञ्च धारयेत्","text":"kākādanīṃ citraphalāṃ bimbīṃ guñjāñca dhārayet"},{"type":"verse","number":"88","sanskrit":"मत्स्यौदनं बलि दद्यात्कृशरां पललं तथा शरावसम्पुटे कृत्वा तस्य शून्ये गृहे भिषक्","text":"matsyaudanaṃ bali dadyātkṛśarāṃ palalaṃ tathā śarāvasampuṭe kṛtvā tasya śūnye gṛhe bhiṣak"},{"type":"verse","number":"89","sanskrit":"उत्सृष्टान्नाभिषिक्तस्य शिशोः स्नपनमिष्यते कुष्ठतालीसखदिरं चन्दनं स्पन्दनं तथा","text":"utsṛṣṭānnābhiṣiktasya śiśoḥ snapanamiṣyate kuṣṭhatālīsakhadiraṃ candanaṃ spandanaṃ tathā"},{"type":"verse","number":"90","sanskrit":"देवदारु वचा हिङ्गु कुष्ठं गिरिकदम्बकम् एला हरेणवश्चापि योज्या उद्धूपने सदा","text":"devadāru vacā hiṅgu kuṣṭhaṃ girikadambakam elā hareṇavaścāpi yojyā uddhūpane sadā"},{"type":"verse","number":"91","sanskrit":"मलिनाम्बरसंवीता मलिना रूक्षमूर्द्धजा शून्यागारस्थिता देवी दारकं पातु पूतना","text":"malināmbarasaṃvītā malinā rūkṣamūrddhajā śūnyāgārasthitā devī dārakaṃ pātu pūtanā"},{"type":"verse","number":"92","sanskrit":"तिक्तद्रुमाणां पत्रेषु क्वाथः कार्योऽभिषेचने","text":"tiktadrumāṇāṃ patreṣu kvāthaḥ kāryo'bhiṣecane"},{"type":"verse","number":"93","sanskrit":"निम्बः पटोलः क्षुद्रा च गुडूची वासकस्तथा विसर्पकुष्ठनुत्ख्यातो गणोऽय पञ्चतिक्तकः","text":"nimbaḥ paṭolaḥ kṣudrā ca guḍūcī vāsakastathā visarpakuṣṭhanutkhyāto gaṇo'ya pañcatiktakaḥ"},{"type":"verse","number":"94","sanskrit":"पिप्पली पिप्प्पलीमूलं चित्रको मधुको मधु शालिपर्णी बृहत्यौ च घृतार्थं च समाहरेत् सर्वगन्धः प्रदेहश्च गात्रे चाक्ष्णोश्च शीतलैः","text":"pippalī pipppalīmūlaṃ citrako madhuko madhu śāliparṇī bṛhatyau ca ghṛtārthaṃ ca samāharet sarvagandhaḥ pradehaśca gātre cākṣṇośca śītalaiḥ"},{"type":"verse","number":"95","sanskrit":"पुरीषं कौक्कुटं केशाश्चर्म सर्पभवं तथा जीर्णं चाभीक्ष्णशो वासो धूपनायोपकल्पयेत्","text":"purīṣaṃ kaukkuṭaṃ keśāścarma sarpabhavaṃ tathā jīrṇaṃ cābhīkṣṇaśo vāso dhūpanāyopakalpayet"},{"type":"verse","number":"96","sanskrit":"कुक्कुटीं मर्कटीं बिम्बीमनन्तां चापि धारयेत् मांसं सामं तथा पक्वं शोणितं च चतुष्पथे","text":"kukkuṭīṃ markaṭīṃ bimbīmanantāṃ cāpi dhārayet māṃsaṃ sāmaṃ tathā pakvaṃ śoṇitaṃ ca catuṣpathe"},{"type":"verse","number":"97","sanskrit":"निवेद्यमन्तश्च गृहे शिशो रक्षानिमित्ततः शिशोश्च स्नपनं कुर्यात्सर्वगन्धोदकैः शुभः कराला पिङ्गला मुण्डा कषायाम्बरसंवृता देवी बालमिमं प्रीता रक्ष त्वं गन्धपूतने","text":"nivedyamantaśca gṛhe śiśo rakṣānimittataḥ śiśośca snapanaṃ kuryātsarvagandhodakaiḥ śubhaḥ karālā piṅgalā muṇḍā kaṣāyāmbarasaṃvṛtā devī bālamimaṃ prītā rakṣa tvaṃ gandhapūtane"},{"type":"verse","number":"98","sanskrit":"गोमूत्रं चाश्वमूत्रञ्च मुस्तां चामरदारु च कुष्ठञ्च सर्वगन्धांश्च तैलार्थमवधारयेत्","text":"gomūtraṃ cāśvamūtrañca mustāṃ cāmaradāru ca kuṣṭhañca sarvagandhāṃśca tailārthamavadhārayet"},{"type":"verse","number":"99","sanskrit":"रोहिणीनिम्बखदिरपलाशककुभत्वचः निक्वाथ्य तस्मिन्निक्वाथे सक्षीरे विपचेद् घृतम्","text":"rohiṇīnimbakhadirapalāśakakubhatvacaḥ nikvāthya tasminnikvāthe sakṣīre vipaced ghṛtam"},{"type":"verse","number":"100","sanskrit":"गृध्रोलूकपुरीषाणि बस्तगन्धामहित्वचम् निम्बपत्राणि च तथा धूपनार्थं समाहरेत्","text":"gṛdhrolūkapurīṣāṇi bastagandhāmahitvacam nimbapatrāṇi ca tathā dhūpanārthaṃ samāharet"},{"type":"verse","number":"101","sanskrit":"धारयेदपि गुञ्जां च बलां काकादनीं तथा नद्यां मुद्गौदनैश्चापि तर्पयेच्छीतपूतनाम्","text":"dhārayedapi guñjāṃ ca balāṃ kākādanīṃ tathā nadyāṃ mudgaudanaiścāpi tarpayecchītapūtanām"},{"type":"verse","number":"102","sanskrit":"जलाशयान्ते बालस्य स्नपनं चोपदिश्यते","text":"jalāśayānte bālasya snapanaṃ copadiśyate"},{"type":"verse","number":"103","sanskrit":"देव्यै देयश्चोपहारो वारुणी रुधिरं तथा मुद्गौदनाशिनी देवी सुराशोणितपायिनी जलाशयरता नित्यं पातु त्वां शीतपूतना","text":"devyai deyaścopahāro vāruṇī rudhiraṃ tathā mudgaudanāśinī devī surāśoṇitapāyinī jalāśayaratā nityaṃ pātu tvāṃ śītapūtanā"},{"type":"verse","number":"104","sanskrit":"कपित्थं बिल्वतर्कारीवासा गन्धर्वहस्तकः कुबेराक्षी च योज्याः स्युर्बालानां परिषेचने","text":"kapitthaṃ bilvatarkārīvāsā gandharvahastakaḥ kuberākṣī ca yojyāḥ syurbālānāṃ pariṣecane"},{"type":"verse","number":"105","sanskrit":"स्वरसैर्भृङ्गवृक्षाणां तथैव हयगन्धया तैलं वसां च संयोज्य पचेदभ्यञ्जनं शिशोः","text":"svarasairbhṛṅgavṛkṣāṇāṃ tathaiva hayagandhayā tailaṃ vasāṃ ca saṃyojya pacedabhyañjanaṃ śiśoḥ"},{"type":"verse","number":"106","sanskrit":"बचा सर्जरसं कुष्ठं सर्पिश्चोद्धूपने हितम् वर्णकं चूर्णकं माल्यमञ्जनं पारदं तथा","text":"bacā sarjarasaṃ kuṣṭhaṃ sarpiścoddhūpane hitam varṇakaṃ cūrṇakaṃ mālyamañjanaṃ pāradaṃ tathā"},{"type":"verse","number":"107","sanskrit":"मनः शिलां चोपहरेद् गोष्ठमध्ये बलि ततः","text":"manaḥ śilāṃ copahared goṣṭhamadhye bali tataḥ"},{"type":"verse","number":"108","sanskrit":"पायसं सपुरोडाशं तद्वल्यर्थमुपाहरेत् मन्त्रपूताभिरद्भिश्च तत्रैव स्नपनं हितम्","text":"pāyasaṃ sapuroḍāśaṃ tadvalyarthamupāharet mantrapūtābhiradbhiśca tatraiva snapanaṃ hitam"},{"type":"verse","number":"109","sanskrit":"अलङ्कृता कामवती सुभगा कामरूपिणी गोष्ठमध्यालया या तु पातु त्वां मुखमण्डिका","text":"alaṅkṛtā kāmavatī subhagā kāmarūpiṇī goṣṭhamadhyālayā yā tu pātu tvāṃ mukhamaṇḍikā"},{"type":"verse","number":"110","sanskrit":"बिल्वाग्निमन्थपूतीकैः कार्यं स्यात्परिषेचितम्","text":"bilvāgnimanthapūtīkaiḥ kāryaṃ syātpariṣecitam"},{"type":"verse","number":"111","sanskrit":"प्रियङ्गुसरलानन्ताशतपुष्पाकुटन्नटैः पचेत्तैलं सगोमूत्रं दधिमस्त्वम्लकाञ्जिकैः","text":"priyaṅgusaralānantāśatapuṣpākuṭannaṭaiḥ pacettailaṃ sagomūtraṃ dadhimastvamlakāñjikaiḥ"},{"type":"verse","number":"112","sanskrit":"वचां वयस्यां जटिलां गोलोमीञ्चापि धारयेत्","text":"vacāṃ vayasyāṃ jaṭilāṃ golomīñcāpi dhārayet"},{"type":"verse","number":"113","sanskrit":"उत्सादनं हितञ्चात्र स्कन्दापस्मारनाशनम् मर्कटोलूकगृध्राणां पुरीषाणि प्रधूपनम् धूमः सुप्तजने कार्यो बालस्य हितमिच्छता तिलतण्डुलकं माल्यं भक्ष्यांश्च विविधानपि कौमारभृत्ये मेषाय प्लक्षमूले निवेदयेत्","text":"utsādanaṃ hitañcātra skandāpasmāranāśanam markaṭolūkagṛdhrāṇāṃ purīṣāṇi pradhūpanam dhūmaḥ suptajane kāryo bālasya hitamicchatā tilataṇḍulakaṃ mālyaṃ bhakṣyāṃśca vividhānapi kaumārabhṛtye meṣāya plakṣamūle nivedayet"},{"type":"verse","number":"114","sanskrit":"अधस्तात्क्षीरवृक्षस्य स्नपनञ्चोपदिश्यते","text":"adhastātkṣīravṛkṣasya snapanañcopadiśyate"},{"type":"verse","number":"115","sanskrit":"अजाननश्चलाक्षिभ्रूः कामरूपी महायशाः बालपालयिता देवो नैगमेयोऽभिरक्षतु","text":"ajānanaścalākṣibhrūḥ kāmarūpī mahāyaśāḥ bālapālayitā devo naigameyo'bhirakṣatu"},{"type":"verse","number":"116","sanskrit":"धात्र्यास्तु गुरुभिर्भोज्यैर्विषमैर्दोषलैस्तथा दोषा देहे प्रकुप्यन्ति ततः स्तन्यं प्रदुष्यति","text":"dhātryāstu gurubhirbhojyairviṣamairdoṣalaistathā doṣā dehe prakupyanti tataḥ stanyaṃ praduṣyati"},{"type":"verse","number":"117","sanskrit":"मिथ्याऽहारविहारिण्या दुष्टा वातादयस्त्रयः दूषयन्ति पयस्तेन जायन्ते व्याधयः शिशोः","text":"mithyā'hāravihāriṇyā duṣṭā vātādayastrayaḥ dūṣayanti payastena jāyante vyādhayaḥ śiśoḥ"},{"type":"verse","number":"118","sanskrit":"वातदुष्टं शिशुः स्तन्यं पिबन्वातगदातुरः क्षामस्वरः कृशाङ्गः स्याद् बद्धविण्मूत्रमारुतः","text":"vātaduṣṭaṃ śiśuḥ stanyaṃ pibanvātagadāturaḥ kṣāmasvaraḥ kṛśāṅgaḥ syād baddhaviṇmūtramārutaḥ"},{"type":"verse","number":"119","sanskrit":"स्विन्नो भिन्नमलो बालः कामलापित्तरोगवान् तृष्णालुरुष्णसर्वाङ्गः पित्तदुष्टं पयः पिबन्","text":"svinno bhinnamalo bālaḥ kāmalāpittarogavān tṛṣṇāluruṣṇasarvāṅgaḥ pittaduṣṭaṃ payaḥ piban"},{"type":"verse","number":"120","sanskrit":"श्लेष्मदुष्टं पिबन्क्षीरं लालालुः श्लेष्मरोगवान् निद्रा ऽदितो जडः शूनो रक्ताक्षश्छर्दनः शिशुः","text":"śleṣmaduṣṭaṃ pibankṣīraṃ lālāluḥ śleṣmarogavān nidrā 'dito jaḍaḥ śūno raktākṣaśchardanaḥ śiśuḥ"},{"type":"verse","number":"121","sanskrit":"द्वन्द्वजे द्वन्द्वजं रूपं सर्वजे सर्वलक्षणम्","text":"dvandvaje dvandvajaṃ rūpaṃ sarvaje sarvalakṣaṇam"},{"type":"verse","number":"122","sanskrit":"ज्वराद्या व्याधयः सर्वे महतां ये पुरेरिताः बालानामपि ते तद्वत् बोद्धव्या भिषगुत्तमैः","text":"jvarādyā vyādhayaḥ sarve mahatāṃ ye pureritāḥ bālānāmapi te tadvat boddhavyā bhiṣaguttamaiḥ"},{"type":"verse","number":"123","sanskrit":"बालानामेव ये रोगा भवन्ति महतां न च तालुकण्टकमुख्यांस्तानवधारय यत्नतः","text":"bālānāmeva ye rogā bhavanti mahatāṃ na ca tālukaṇṭakamukhyāṃstānavadhāraya yatnataḥ"},{"type":"verse","number":"124","sanskrit":"तालुमांसे कफः क्रुद्धः कुरुते तालुकण्टकम् तेन तालुप्रदेशस्य निम्नता मूर्ध्नि जायते","text":"tālumāṃse kaphaḥ kruddhaḥ kurute tālukaṇṭakam tena tālupradeśasya nimnatā mūrdhni jāyate"},{"type":"verse","number":"125","sanskrit":"तालुपातः स्तनद्वेषः कृच्छ्रात्पानं शकृद्द्र वम् तृडक्षिकण्ठास्यरुजा ग्रीवादुर्बलता वमिः","text":"tālupātaḥ stanadveṣaḥ kṛcchrātpānaṃ śakṛddra vam tṛḍakṣikaṇṭhāsyarujā grīvādurbalatā vamiḥ"},{"type":"verse","number":"126","sanskrit":"वीसर्पस्तु शिशोः प्राणनाशनः शीर्षवस्तिजः पद्मवर्णो महापद्मरोगो दोषत्रयोद्भवः शङ्खाभ्यां हृदयं याति हृदयाच्च गुदं व्रजेत्","text":"vīsarpastu śiśoḥ prāṇanāśanaḥ śīrṣavastijaḥ padmavarṇo mahāpadmarogo doṣatrayodbhavaḥ śaṅkhābhyāṃ hṛdayaṃ yāti hṛdayācca gudaṃ vrajet"},{"type":"verse","number":"127","sanskrit":"कुकूणकं क्षीरदोषाच्छिशूनामेव वर्त्मनि जायते सरुजं नेत्रं कण्डूरं प्रस्रवेद् बहु","text":"kukūṇakaṃ kṣīradoṣācchiśūnāmeva vartmani jāyate sarujaṃ netraṃ kaṇḍūraṃ prasraved bahu"},{"type":"verse","number":"128","sanskrit":"शिशुः कुर्याल्ललाटाक्षिकूटनासाप्रघर्षणम् शक्तो नार्कप्रभां द्र ष्टुं न चाक्ष्युन्मीलनक्षमः","text":"śiśuḥ kuryāllalāṭākṣikūṭanāsāpragharṣaṇam śakto nārkaprabhāṃ dra ṣṭuṃ na cākṣyunmīlanakṣamaḥ"},{"type":"verse","number":"129","sanskrit":"वातेनाध्मापिता नाभिः सरुजा तुण्डिरुच्यते बालस्य गुदपाकाख्यो ब्याधिः पित्तेन जायते","text":"vātenādhmāpitā nābhiḥ sarujā tuṇḍirucyate bālasya gudapākākhyo byādhiḥ pittena jāyate"},{"type":"verse","number":"130","sanskrit":"शकृन्मूत्रसमायुक्तेऽधौतेऽपाने शिशोर्भवेत् स्विन्ने वास्नाप्यमानस्य कण्डू रक्तकफोद्भवा","text":"śakṛnmūtrasamāyukte'dhaute'pāne śiśorbhavet svinne vāsnāpyamānasya kaṇḍū raktakaphodbhavā"},{"type":"verse","number":"131","sanskrit":"कण्डूयनात्ततः क्षिप्रं स्फोटाः स्रावश्च जायते एकीभूतं व्रणं घोरं तं विद्यादहिपूतनम्","text":"kaṇḍūyanāttataḥ kṣipraṃ sphoṭāḥ srāvaśca jāyate ekībhūtaṃ vraṇaṃ ghoraṃ taṃ vidyādahipūtanam"},{"type":"verse","number":"132","sanskrit":"स्निग्धा सवर्णा ग्रथिता नीरुजा मुद्गसन्निभा कफवातोत्थिता ज्ञेया बालानामजगल्लिका","text":"snigdhā savarṇā grathitā nīrujā mudgasannibhā kaphavātotthitā jñeyā bālānāmajagallikā"},{"type":"verse","number":"133","sanskrit":"मातुः कुमारो गर्भिण्याःस्तन्यं प्रायः पिबन्नपि कासाग्निसादवमथुतन्द्रा कार्श्यारुचिभ्रमैः","text":"mātuḥ kumāro garbhiṇyāḥstanyaṃ prāyaḥ pibannapi kāsāgnisādavamathutandrā kārśyārucibhramaiḥ"},{"type":"verse","number":"134","sanskrit":"युज्यते कोष्ठवृद्ध्या च तमाहुः पारिगर्भिकम् रोगं परिभवाख्यं च तत्र युञ्जीत दीपनम्","text":"yujyate koṣṭhavṛddhyā ca tamāhuḥ pārigarbhikam rogaṃ paribhavākhyaṃ ca tatra yuñjīta dīpanam"},{"type":"verse","number":"135","sanskrit":"दन्तोद्भेदः शिशोः सर्वरोगाणां कारणं स्मृतम् विशेषाज्वरविड्भेदकासच्छर्दिशिरोरुजाम्","text":"dantodbhedaḥ śiśoḥ sarvarogāṇāṃ kāraṇaṃ smṛtam viśeṣājvaraviḍbhedakāsacchardiśirorujām"},{"type":"verse","number":"136","sanskrit":"अभिष्यन्दस्य पोथक्या विसर्पस्य च जायते","text":"abhiṣyandasya pothakyā visarpasya ca jāyate"},{"type":"verse","number":"137","sanskrit":"भैषज्यं पूर्वमुद्दिष्टं महतां यज्ज्वरादिषु तदेव कार्यं बालानां किन्तु दाहादिकं विना","text":"bhaiṣajyaṃ pūrvamuddiṣṭaṃ mahatāṃ yajjvarādiṣu tadeva kāryaṃ bālānāṃ kintu dāhādikaṃ vinā"},{"type":"verse","number":"138","sanskrit":"त एव दोषा दूष्याश्च ज्वराद्या व्याधयश्च ते अतस्तदेव भैषज्यं मात्रा तत्र कनीयसी","text":"ta eva doṣā dūṣyāśca jvarādyā vyādhayaśca te atastadeva bhaiṣajyaṃ mātrā tatra kanīyasī"},{"type":"verse","number":"139","sanskrit":"बालस्य कनीयसी मात्रामाह विश्वामित्रः विडङ्गफलमात्रं तु जातमात्रस्य भेषजम् अनेनैव प्रमाणेन मासि मासि प्रवर्द्धयेत्","text":"bālasya kanīyasī mātrāmāha viśvāmitraḥ viḍaṅgaphalamātraṃ tu jātamātrasya bheṣajam anenaiva pramāṇena māsi māsi pravarddhayet"},{"type":"verse","number":"140","sanskrit":"प्रथमे मासि बालाय देया भैषज्यरक्तिका अवलेह्या तु कर्त्तव्या मधुक्षीरसिताघृतैः","text":"prathame māsi bālāya deyā bhaiṣajyaraktikā avalehyā tu karttavyā madhukṣīrasitāghṛtaiḥ"},{"type":"verse","number":"141","sanskrit":"एकैकां वर्द्धयेत्तावद्यावत्संवत्सरो भवेत् तदूर्ध्वं माषवृद्धिः स्याद्यावत्षोडश वत्सराः","text":"ekaikāṃ varddhayettāvadyāvatsaṃvatsaro bhavet tadūrdhvaṃ māṣavṛddhiḥ syādyāvatṣoḍaśa vatsarāḥ"},{"type":"verse","number":"142","sanskrit":"ततः स्थिरा भवेत्तावद्यावद्वर्षाणि सप्ततिः ततो बालकवन्मात्रा ह्रासनीया शनैः शनैः","text":"tataḥ sthirā bhavettāvadyāvadvarṣāṇi saptatiḥ tato bālakavanmātrā hrāsanīyā śanaiḥ śanaiḥ"},{"type":"verse","number":"143","sanskrit":"चूर्णकल्कावलेहानामियं मात्रा प्रकीर्त्तिता कषायस्य पुनः सैव विज्ञातव्या चतुर्गुणा","text":"cūrṇakalkāvalehānāmiyaṃ mātrā prakīrttitā kaṣāyasya punaḥ saiva vijñātavyā caturguṇā"},{"type":"verse","number":"144","sanskrit":"क्षीरपस्य शिशोर्देयमौषधं क्षीरसर्पिषा धात्र्यास्तु केवलं देयं न क्षीरेणापि सर्पिषा","text":"kṣīrapasya śiśordeyamauṣadhaṃ kṣīrasarpiṣā dhātryāstu kevalaṃ deyaṃ na kṣīreṇāpi sarpiṣā"},{"type":"verse","number":"145","sanskrit":"येषां गदानां ये योगाः प्रवक्ष्यन्तेऽगदङ्कराः तेषु तत्कल्पसंलिप्तौ पाययेत्तं शिशुं स्तनौ","text":"yeṣāṃ gadānāṃ ye yogāḥ pravakṣyante'gadaṅkarāḥ teṣu tatkalpasaṃliptau pāyayettaṃ śiśuṃ stanau"},{"type":"verse","number":"146","sanskrit":"अङ्गप्रत्यङ्गदेशे तु रुजा यत्रास्य जायते मुहुर्मुहुः स्पृशति तं स्पृश्यमानेन रोदिति","text":"aṅgapratyaṅgadeśe tu rujā yatrāsya jāyate muhurmuhuḥ spṛśati taṃ spṛśyamānena roditi"},{"type":"verse","number":"147","sanskrit":"निमीलिताक्षो मूर्द्धस्थे रोगे नो धारयेच्छिरः वस्तिस्थे मूत्रसङ्गार्त्तः क्षुधा तृडपि गच्छति","text":"nimīlitākṣo mūrddhasthe roge no dhārayecchiraḥ vastisthe mūtrasaṅgārttaḥ kṣudhā tṛḍapi gacchati"},{"type":"verse","number":"148","sanskrit":"विण्मूत्रसङ्गवैकल्याच्छर्द्याध्मानान्त्रकूजनैः कोष्ठे व्याधीन्विजानीयात्सर्वत्रस्थांश्च रोदनैः","text":"viṇmūtrasaṅgavaikalyācchardyādhmānāntrakūjanaiḥ koṣṭhe vyādhīnvijānīyātsarvatrasthāṃśca rodanaiḥ"},{"type":"verse","number":"149","sanskrit":"सर्वं निवार्यते बाले स्तन्यं नैव निवार्यते मात्रया लङ्घयेद्धात्रीं शिशोरेतद्धि लङ्घनम्","text":"sarvaṃ nivāryate bāle stanyaṃ naiva nivāryate mātrayā laṅghayeddhātrīṃ śiśoretaddhi laṅghanam"},{"type":"verse","number":"150","sanskrit":"भद्र मुस्ताऽभयानिम्बपटोलमधुकैः कृतः क्वाथः कोष्णः शिशोरेष निःशेषज्वरनाशनः","text":"bhadra mustā'bhayānimbapaṭolamadhukaiḥ kṛtaḥ kvāthaḥ koṣṇaḥ śiśoreṣa niḥśeṣajvaranāśanaḥ"},{"type":"verse","number":"151","sanskrit":"वनकृष्णाऽरुणाशृङ्गीचूर्णं क्षौद्रे ण संयुतम् शिशोर्ज्वरातिसारघ्नं कासं श्वासं वमिं हरेत्","text":"vanakṛṣṇā'ruṇāśṛṅgīcūrṇaṃ kṣaudre ṇa saṃyutam śiśorjvarātisāraghnaṃ kāsaṃ śvāsaṃ vamiṃ haret"},{"type":"verse","number":"152","sanskrit":"बिल्वं च पुष्पाणि च धातकीनां जलं सलोध्रं गजपिप्पलद्यं च क्वाथावलेहौ मधुना विमिश्रौ बालेषु योज्यावतिसारितेषु समङ्गाधातकीलोध्रसारिवाभिः शृतं जलम् दुर्धरेऽपि शिशोर्देयमतीसारे समाक्षिकम्","text":"bilvaṃ ca puṣpāṇi ca dhātakīnāṃ jalaṃ salodhraṃ gajapippaladyaṃ ca kvāthāvalehau madhunā vimiśrau bāleṣu yojyāvatisāriteṣu samaṅgādhātakīlodhrasārivābhiḥ śṛtaṃ jalam durdhare'pi śiśordeyamatīsāre samākṣikam"},{"type":"verse","number":"153","sanskrit":"विडङ्गान्यजमोदा च पिप्पलीतण्डुलानि च एषामालोड्य चूर्णानि सुखं तप्तेन वारिणा आमे प्रवृत्तेऽतीसारे कुमारं पाययेद्भिषक्","text":"viḍaṅgānyajamodā ca pippalītaṇḍulāni ca eṣāmāloḍya cūrṇāni sukhaṃ taptena vāriṇā āme pravṛtte'tīsāre kumāraṃ pāyayedbhiṣak"},{"type":"verse","number":"154","sanskrit":"मोचारसः समङ्गा च धातकी पद्मकेशरम् पिष्टैरेतैर्यवागूः स्याद्र क्तातीसारनाशिनी","text":"mocārasaḥ samaṅgā ca dhātakī padmakeśaram piṣṭairetairyavāgūḥ syādra ktātīsāranāśinī"},{"type":"verse","number":"155","sanskrit":"नागरातिविषामुस्तबालकेन्द्र यवैः शृतम् कुमारं पाययेत्प्रातः सर्वातीसारनाशनम्","text":"nāgarātiviṣāmustabālakendra yavaiḥ śṛtam kumāraṃ pāyayetprātaḥ sarvātīsāranāśanam"},{"type":"verse","number":"156","sanskrit":"लाजा सयष्टी मधुका शर्करा क्षौद्र मेव च तण्डुलोदकयोगेन क्षिप्रं हन्ति प्रवाहिकाम्","text":"lājā sayaṣṭī madhukā śarkarā kṣaudra meva ca taṇḍulodakayogena kṣipraṃ hanti pravāhikām"},{"type":"verse","number":"157","sanskrit":"रजनी सरलो दारु बृहती गजपिप्पली पृश्निपर्णी शताह्वा च लीढं माक्षिकसर्पिषा","text":"rajanī saralo dāru bṛhatī gajapippalī pṛśniparṇī śatāhvā ca līḍhaṃ mākṣikasarpiṣā"},{"type":"verse","number":"158","sanskrit":"दीपनं ग्रहणी हन्ति मारुतार्त्तिं सकामलाम् ज्वरातीसारपाण्डघ्नुं बालानां सर्वरोगनुत्","text":"dīpanaṃ grahaṇī hanti mārutārttiṃ sakāmalām jvarātīsārapāṇḍaghnuṃ bālānāṃ sarvaroganut"},{"type":"verse","number":"159","sanskrit":"मुस्तकातिविषावासाकणाशृङ्गीरसं लिहेत् मधुना मुच्यते बालः कासैः पञ्चभिरुत्थितैः","text":"mustakātiviṣāvāsākaṇāśṛṅgīrasaṃ lihet madhunā mucyate bālaḥ kāsaiḥ pañcabhirutthitaiḥ"},{"type":"verse","number":"160","sanskrit":"व्याघ्रीसुमनसं जातीकेशरैरवलेहिका मधुना चिरसञ्जाताञ्छिशोः कासान्व्यपोहति","text":"vyāghrīsumanasaṃ jātīkeśarairavalehikā madhunā cirasañjātāñchiśoḥ kāsānvyapohati"},{"type":"verse","number":"161","sanskrit":"धान्यं च शर्करायुक्तं तण्डुलोदकसंयुतम् पानमेतत्प्रदातव्यं कासश्वासापहं शिशोः","text":"dhānyaṃ ca śarkarāyuktaṃ taṇḍulodakasaṃyutam pānametatpradātavyaṃ kāsaśvāsāpahaṃ śiśoḥ"},{"type":"verse","number":"162","sanskrit":"द्रा क्षावासाऽभयाकृष्णाचूर्णं क्षौद्रे ण सर्पिषा लीढं श्वासं निहन्त्याशु कासञ्च तमकं तथा","text":"drā kṣāvāsā'bhayākṛṣṇācūrṇaṃ kṣaudre ṇa sarpiṣā līḍhaṃ śvāsaṃ nihantyāśu kāsañca tamakaṃ tathā"},{"type":"verse","number":"163","sanskrit":"चूर्णं कटुकरोहिण्या मधुनासह योजयेत् हिक्कां प्रशमयेत्क्षिप्रं छर्दिं चापि चिरोत्थिताम्","text":"cūrṇaṃ kaṭukarohiṇyā madhunāsaha yojayet hikkāṃ praśamayetkṣipraṃ chardiṃ cāpi cirotthitām"},{"type":"verse","number":"164","sanskrit":"आम्रास्थिलाजसिन्धूत्थं सक्षौद्रं छर्दिनुद्भवेत्","text":"āmrāsthilājasindhūtthaṃ sakṣaudraṃ chardinudbhavet"},{"type":"verse","number":"165","sanskrit":"छर्द्यां पीतं तु मेध्यन्तु स्तन्येन मधुसर्पिषा द्विवार्त्ताकीफलरसं पञ्चकोलञ्च लेहयेत्","text":"chardyāṃ pītaṃ tu medhyantu stanyena madhusarpiṣā dvivārttākīphalarasaṃ pañcakolañca lehayet"},{"type":"verse","number":"166","sanskrit":"पिप्पली पिप्पलीमूलं चव्यचित्रकनागरम्","text":"pippalī pippalīmūlaṃ cavyacitrakanāgaram"},{"type":"verse","number":"167","sanskrit":"घृतेन सिन्धुविश्वैलाहिङ्गुभार्गीरजो लिहन् आनाहं वातिकं शूलं हन्यात्तोयेन वा शिशुः","text":"ghṛtena sindhuviśvailāhiṅgubhārgīrajo lihan ānāhaṃ vātikaṃ śūlaṃ hanyāttoyena vā śiśuḥ"},{"type":"verse","number":"168","sanskrit":"कणोषणासिताक्षौद्र सूक्ष्मैलासैन्धवैः कृतः मूत्रग्रहे प्रयोक्तव्यः शिशूनां लेह उत्तमः","text":"kaṇoṣaṇāsitākṣaudra sūkṣmailāsaindhavaiḥ kṛtaḥ mūtragrahe prayoktavyaḥ śiśūnāṃ leha uttamaḥ"},{"type":"verse","number":"169","sanskrit":"यदा तु दुर्बलो बालः खादन्नपि च वह्निमान् विदारीकन्दगोधूमयवचूर्णं घृतप्लुतम् खादयेत्तदनु क्षीरं शृतं समधुशर्करम्","text":"yadā tu durbalo bālaḥ khādannapi ca vahnimān vidārīkandagodhūmayavacūrṇaṃ ghṛtaplutam khādayettadanu kṣīraṃ śṛtaṃ samadhuśarkaram"},{"type":"verse","number":"170","sanskrit":"मुस्तं कूष्माण्डबीजानि भद्र दारुकलिङ्गकान् पिष्ट्वा तोयेन संलिप्तं लेपोऽय शोथहृच्छिशोः","text":"mustaṃ kūṣmāṇḍabījāni bhadra dārukaliṅgakān piṣṭvā toyena saṃliptaṃ lepo'ya śothahṛcchiśoḥ"},{"type":"verse","number":"171","sanskrit":"पटोलत्रिफलाऽरिष्टहरिद्रा क्वथितं पिबेत् क्षतवीसर्पविस्फोटज्वराणां शान्तये शिशुः","text":"paṭolatriphalā'riṣṭaharidrā kvathitaṃ pibet kṣatavīsarpavisphoṭajvarāṇāṃ śāntaye śiśuḥ"},{"type":"verse","number":"172","sanskrit":"सारिवातिललोध्राणां कषायो मधुकस्य च संस्राविणि मुखे शस्तो धावनार्थं शिशोः सदा","text":"sārivātilalodhrāṇāṃ kaṣāyo madhukasya ca saṃsrāviṇi mukhe śasto dhāvanārthaṃ śiśoḥ sadā"},{"type":"verse","number":"173","sanskrit":"अश्वत्थत्वग्दलक्षौद्रै र्मुखपाके प्रलेपनम्","text":"aśvatthatvagdalakṣaudrai rmukhapāke pralepanam"},{"type":"verse","number":"174","sanskrit":"पिप्पलीत्रिफलाचूर्णं घृतक्षौद्र परिप्लुतम् बालो रोदिति यस्तस्मै लीढं दद्यात्सुखावहम्","text":"pippalītriphalācūrṇaṃ ghṛtakṣaudra pariplutam bālo roditi yastasmai līḍhaṃ dadyātsukhāvaham"},{"type":"verse","number":"175","sanskrit":"हरीतकी वचा कुष्ठं कल्कं माक्षिकसंयुतम् पीत्वा कुमारः स्तन्येन मुच्यते तालुकण्टकात्","text":"harītakī vacā kuṣṭhaṃ kalkaṃ mākṣikasaṃyutam pītvā kumāraḥ stanyena mucyate tālukaṇṭakāt"},{"type":"verse","number":"176","sanskrit":"फलत्रिकं लोध्रपुनर्नवे च सशृङ्गबेरं बृहतीद्वयं च आलेपनं श्लेष्महरं सुखोष्णं कुकूणके कार्यमुदाहरन्ति","text":"phalatrikaṃ lodhrapunarnave ca saśṛṅgaberaṃ bṛhatīdvayaṃ ca ālepanaṃ śleṣmaharaṃ sukhoṣṇaṃ kukūṇake kāryamudāharanti"},{"type":"verse","number":"177","sanskrit":"मृत्पिण्डेनाग्नितप्तेन क्षीरसिक्तेन सोष्मणा स्वेदयेदुत्थितां नाभिं शोथस्तेनोपशाम्यति","text":"mṛtpiṇḍenāgnitaptena kṣīrasiktena soṣmaṇā svedayedutthitāṃ nābhiṃ śothastenopaśāmyati"},{"type":"verse","number":"178","sanskrit":"नाभिपाके निशालोध्रप्रियंगुमधुकैः शृतम् तैलमभ्यञ्जने शस्तमेभिश्चाप्यवधूलनम्","text":"nābhipāke niśālodhrapriyaṃgumadhukaiḥ śṛtam tailamabhyañjane śastamebhiścāpyavadhūlanam"},{"type":"verse","number":"179","sanskrit":"दग्धेन छागशकृता नाभिपाकेऽवचूर्णनम् त्वक्चूर्णैः क्षीरिणा वाऽपि कुर्याच्चन्दनरेणुना","text":"dagdhena chāgaśakṛtā nābhipāke'vacūrṇanam tvakcūrṇaiḥ kṣīriṇā vā'pi kuryāccandanareṇunā"},{"type":"verse","number":"180","sanskrit":"गुदपाके तु बालानां पित्तघ्नीं कारयेत् क्रियाम् रसाञ्जनं विशेषेण पानालेपनयोर्हितम् शङ्खयष्ट्यञ्जनैश्चूर्णं शिशूनां गुदपाकनुत्","text":"gudapāke tu bālānāṃ pittaghnīṃ kārayet kriyām rasāñjanaṃ viśeṣeṇa pānālepanayorhitam śaṅkhayaṣṭyañjanaiścūrṇaṃ śiśūnāṃ gudapākanut"},{"type":"verse","number":"181","sanskrit":"शङ्खसौवीरयष्ट्याह्वैर्लेपो देयोऽहिपूतने","text":"śaṅkhasauvīrayaṣṭyāhvairlepo deyo'hipūtane"},{"type":"verse","number":"182","sanskrit":"पारिगर्भिकरोगे तु युज्यते वह्निदीपनम्","text":"pārigarbhikaroge tu yujyate vahnidīpanam"},{"type":"verse","number":"183","sanskrit":"दन्तपालद्यं तु मधुना चूर्णेन प्रतिसारयेत् धातकीपुष्पपिप्पल्योर्धात्रीफलरसेन वा","text":"dantapāladyaṃ tu madhunā cūrṇena pratisārayet dhātakīpuṣpapippalyordhātrīphalarasena vā"},{"type":"verse","number":"184","sanskrit":"दन्तोत्थानभवा रोगाः पीडयन्ति न बालकम् जाते दन्ते हि शाम्यन्ति यतस्तद्धेतुका गदाः","text":"dantotthānabhavā rogāḥ pīḍayanti na bālakam jāte dante hi śāmyanti yatastaddhetukā gadāḥ"},{"type":"verse","number":"185","sanskrit":"सौवर्णं सुकृतं चूर्णं कुष्ठं मधु घृतं वचा मत्स्याक्षकं शङ्खपुष्पी मधु सर्पिः सकाञ्चनम् अर्कपुष्पी मधु घृतं चूर्णितं कनकं वचा सहेमचूर्णं कैटर्यं श्वेता दूर्वा घृतं मधु","text":"sauvarṇaṃ sukṛtaṃ cūrṇaṃ kuṣṭhaṃ madhu ghṛtaṃ vacā matsyākṣakaṃ śaṅkhapuṣpī madhu sarpiḥ sakāñcanam arkapuṣpī madhu ghṛtaṃ cūrṇitaṃ kanakaṃ vacā sahemacūrṇaṃ kaiṭaryaṃ śvetā dūrvā ghṛtaṃ madhu"},{"type":"verse","number":"186","sanskrit":"चत्वारोऽभिहिताः प्राशा अर्द्धश्लोकसमापनाः कुमाराणां वपुर्मेधाबलपुष्टिकराः स्मृताः","text":"catvāro'bhihitāḥ prāśā arddhaślokasamāpanāḥ kumārāṇāṃ vapurmedhābalapuṣṭikarāḥ smṛtāḥ"},{"type":"verse","number":"187","sanskrit":"लाक्षारसे समे तैलं मस्तुन्यथ चतुर्गुणे रास्नाचन्दनकुष्टाह्वावाजिगन्धानिशायुतैः","text":"lākṣārase same tailaṃ mastunyatha caturguṇe rāsnācandanakuṣṭāhvāvājigandhāniśāyutaiḥ"},{"type":"verse","number":"188","sanskrit":"शताह्वादारुयष्ट्याह्व मूर्वातिक्ताहरेणुभिः संसिद्धं ज्वररक्षोघ्नं बलवर्णकरं शिशोः","text":"śatāhvādāruyaṣṭyāhva mūrvātiktāhareṇubhiḥ saṃsiddhaṃ jvararakṣoghnaṃ balavarṇakaraṃ śiśoḥ"},{"type":"verse","number":"189","sanskrit":"बालरोगाधिकारः समाप्तः समाप्तञ्चेदं मध्यखण्डम् पूर्व खण्डम्","text":"bālarogādhikāraḥ samāptaḥ samāptañcedaṃ madhyakhaṇḍam pūrva khaṇḍam"}]},{"sthana":"Уттаракханда","number":71,"lang":"sa","content":[{"type":"heading","heading":"Ваджикарана — репродуктивное здоровье"},{"type":"verse","number":"1","sanskrit":"यद् द्र व्यं पुरुषं कुर्याद्वाजीव सुरतक्षमम् तद्वाजीकरमाख्यातं मुनिभिर्भिषजां वरैः","text":"yad dra vyaṃ puruṣaṃ kuryādvājīva suratakṣamam tadvājīkaramākhyātaṃ munibhirbhiṣajāṃ varaiḥ"},{"type":"verse","number":"2","sanskrit":"क्लीबः स्यात्सुरताशक्तस्तद्भावः क्लैब्यमुच्यते तच्च सप्तविधं प्रोक्तं निदानं तस्य कथ्यते","text":"klībaḥ syātsuratāśaktastadbhāvaḥ klaibyamucyate tacca saptavidhaṃ proktaṃ nidānaṃ tasya kathyate"},{"type":"verse","number":"3","sanskrit":"तैस्तैर्भावैरहृद्यैस्तु रिरंसोर्मनसि क्षते ध्वजः पतत्यतो नॄणां क्लैब्यं समुपजायते द्वेष्यस्त्रीसम्प्रयोगाच्च क्लैब्यं तन्मानसं स्मृतम्","text":"taistairbhāvairahṛdyaistu riraṃsormanasi kṣate dhvajaḥ patatyato nṝṇāṃ klaibyaṃ samupajāyate dveṣyastrīsamprayogācca klaibyaṃ tanmānasaṃ smṛtam"},{"type":"verse","number":"4","sanskrit":"कटुकाम्लोष्णलवणैरतिमात्रोपसेवितैः पित्ताच्छुक्रक्षयो दृष्टः क्लैब्यं तस्मात्प्रजायते","text":"kaṭukāmloṣṇalavaṇairatimātropasevitaiḥ pittācchukrakṣayo dṛṣṭaḥ klaibyaṃ tasmātprajāyate"},{"type":"verse","number":"5","sanskrit":"अतिव्यवायशीलो यो न च वाजीक्रियारतः ध्वजभङ्गमवाप्नोति स शुक्रक्षयहेतुकम्","text":"ativyavāyaśīlo yo na ca vājīkriyārataḥ dhvajabhaṅgamavāpnoti sa śukrakṣayahetukam"},{"type":"verse","number":"6","sanskrit":"महता मेढ्ररोगेण चतुर्थी क्लीबता भवेत् वीर्यवाहिशिराच्छेदान्मेहनानुन्नतिर्भवेत्","text":"mahatā meḍhrarogeṇa caturthī klībatā bhavet vīryavāhiśirācchedānmehanānunnatirbhavet"},{"type":"verse","number":"7","sanskrit":"बलिनः क्षुब्धमनसो निरोधाद् ब्रह्मचर्यतः षष्ठं क्लैब्यं स्मृतं तत्तु शुक्रस्तम्भनिमित्तकम्","text":"balinaḥ kṣubdhamanaso nirodhād brahmacaryataḥ ṣaṣṭhaṃ klaibyaṃ smṛtaṃ tattu śukrastambhanimittakam"},{"type":"verse","number":"8","sanskrit":"जन्मप्रभृति यत्क्लैब्यं सहजं तद्धि सप्तमम्","text":"janmaprabhṛti yatklaibyaṃ sahajaṃ taddhi saptamam"},{"type":"verse","number":"9","sanskrit":"असाध्यं सहजं क्लैब्यं मर्मच्छेदाच्च यद्भवेत्","text":"asādhyaṃ sahajaṃ klaibyaṃ marmacchedācca yadbhavet"},{"type":"verse","number":"10","sanskrit":"क्लैब्यानामिह साध्यानां कार्यो हेतुविपर्ययः मुख्यं चिकित्सितं यस्मान्निदानपरिवर्जनम्","text":"klaibyānāmiha sādhyānāṃ kāryo hetuviparyayaḥ mukhyaṃ cikitsitaṃ yasmānnidānaparivarjanam"},{"type":"verse","number":"11","sanskrit":"नरो वाजीकरान्योगान्सम्यक्छुद्धो निरामयः सप्तत्यन्तं प्रकुर्वीत वर्षादूर्ध्वं तु षोडशात्","text":"naro vājīkarānyogānsamyakchuddho nirāmayaḥ saptatyantaṃ prakurvīta varṣādūrdhvaṃ tu ṣoḍaśāt"},{"type":"verse","number":"12","sanskrit":"न च वै षोडाशादर्वाक्सप्तत्याः परतो न च आयुष्कामो नरः स्त्रीभिः संयोगं कर्त्तुमर्हति","text":"na ca vai ṣoḍāśādarvāksaptatyāḥ parato na ca āyuṣkāmo naraḥ strībhiḥ saṃyogaṃ karttumarhati"},{"type":"verse","number":"13","sanskrit":"क्षयवृद्ध्युपदंशाद्या रोगाश्चातीव दुर्जयाः अकालमरणञ्च स्याद्भजतः स्त्रियमन्यथा","text":"kṣayavṛddhyupadaṃśādyā rogāścātīva durjayāḥ akālamaraṇañca syādbhajataḥ striyamanyathā"},{"type":"verse","number":"14","sanskrit":"विलासिनामर्थवतां रुपयौवनशालिनाम् नराणां बहुभार्याणां विधिर्वाजीकरो हितः","text":"vilāsināmarthavatāṃ rupayauvanaśālinām narāṇāṃ bahubhāryāṇāṃ vidhirvājīkaro hitaḥ"},{"type":"verse","number":"15","sanskrit":"स्थविराणां रिरंसूनां स्त्रीणां वाल्लभ्यमिच्छताम् योषित्प्रसङ्गात्क्षीणानां क्लीबानामल्परेतसाम्","text":"sthavirāṇāṃ riraṃsūnāṃ strīṇāṃ vāllabhyamicchatām yoṣitprasaṅgātkṣīṇānāṃ klībānāmalparetasām"},{"type":"verse","number":"16","sanskrit":"हिता वाजीकरा योगाः प्रीणयन्ति बलप्रदाः एतेऽपि पुष्टदेहानां सेव्याः कालाद्यपेक्षया","text":"hitā vājīkarā yogāḥ prīṇayanti balapradāḥ ete'pi puṣṭadehānāṃ sevyāḥ kālādyapekṣayā"},{"type":"verse","number":"17","sanskrit":"भोजनानि विचित्राणि पानानि विविधानि च गीतं श्रोत्राभिरामाश्च वाचः स्पर्शसुखस्तथा","text":"bhojanāni vicitrāṇi pānāni vividhāni ca gītaṃ śrotrābhirāmāśca vācaḥ sparśasukhastathā"},{"type":"verse","number":"18","sanskrit":"यामिनी चन्द्र तिलका कामिनी नवयौवना गीतं श्रोत्रमनोज्ञञ्च ताम्बूलं मदिरा स्रजः","text":"yāminī candra tilakā kāminī navayauvanā gītaṃ śrotramanojñañca tāmbūlaṃ madirā srajaḥ"},{"type":"verse","number":"19","sanskrit":"गन्धा मनोज्ञा रूपाणि चित्राण्युपवनानि च मनसश्चाप्रतीघातो वाजीकुर्वन्ति मानवम्","text":"gandhā manojñā rūpāṇi citrāṇyupavanāni ca manasaścāpratīghāto vājīkurvanti mānavam"},{"type":"verse","number":"20","sanskrit":"माक्षीकधातुमधुपारदलोहचूर्णपथ्याशिलाजतुविडङ्गघृतानि लिह्यात् एकाग्रविंशतिदिनानि गदार्दितोऽपि साशीतिकोऽपि रमयेत्प्रमदां युवेव","text":"mākṣīkadhātumadhupāradalohacūrṇapathyāśilājatuviḍaṅgaghṛtāni lihyāt ekāgraviṃśatidināni gadārdito'pi sāśītiko'pi ramayetpramadāṃ yuveva"},{"type":"verse","number":"21","sanskrit":"सत्वं गुडूच्या गगनं सलोध्रमेलासितामागधिकासमेतम् एतत्समेतं मधुनाऽवलीढं रामाशतं सेवयतीव षण्ढः","text":"satvaṃ guḍūcyā gaganaṃ salodhramelāsitāmāgadhikāsametam etatsametaṃ madhunā'valīḍhaṃ rāmāśataṃ sevayatīva ṣaṇḍhaḥ"},{"type":"verse","number":"22","sanskrit":"गवां विरूढवत्सानां सिद्धं पयसि पायसम् गोधूमचूर्णञ्च तथा सितामधुघृतान्वितम् भुक्त्वा हृष्यति जीर्णोऽपि दश दारान्व्रजत्यपि","text":"gavāṃ virūḍhavatsānāṃ siddhaṃ payasi pāyasam godhūmacūrṇañca tathā sitāmadhughṛtānvitam bhuktvā hṛṣyati jīrṇo'pi daśa dārānvrajatyapi"},{"type":"verse","number":"23","sanskrit":"दध्नोऽद्धाढकमीषदम्लमधुरं खण्डस्य चन्द्र द्युतेः प्रस्थं क्षौद्र पलं पलञ्च हविषः शुण्ठ्याश्च माषाष्टकम् तद्वन्माषचतुष्टयं मरिचतः कर्षं लवङ्गं तथा धृत्वा शुक्लपटे शनैः करतलेनोत्थाप्य विस्रावयेत्","text":"dadhno'ddhāḍhakamīṣadamlamadhuraṃ khaṇḍasya candra dyuteḥ prasthaṃ kṣaudra palaṃ palañca haviṣaḥ śuṇṭhyāśca māṣāṣṭakam tadvanmāṣacatuṣṭayaṃ maricataḥ karṣaṃ lavaṅgaṃ tathā dhṛtvā śuklapaṭe śanaiḥ karatalenotthāpya visrāvayet"},{"type":"verse","number":"24","sanskrit":"मृद्भाण्डे मृगनाभिचन्दनरसामृष्टेऽगुरूद्धूपिते कर्पू रेण सुगन्धितं तदखिलं संलोड्य संस्थापयेत् स्वस्यार्थं मकरेश्वरेण रचिता ह्येषा रसाला स्वयं भोक्तुर्मन्मथदीपनी सुखकरी कान्तेव नित्यं प्रिया","text":"mṛdbhāṇḍe mṛganābhicandanarasāmṛṣṭe'gurūddhūpite karpū reṇa sugandhitaṃ tadakhilaṃ saṃloḍya saṃsthāpayet svasyārthaṃ makareśvareṇa racitā hyeṣā rasālā svayaṃ bhokturmanmathadīpanī sukhakarī kānteva nityaṃ priyā"},{"type":"verse","number":"25","sanskrit":"रतिवर्द्धनयोगाः गोक्षुरेक्षुरबीजानि वाजिगन्धा शतावरी मुशली वानरीबीजं यष्टी नागबला बला","text":"rativarddhanayogāḥ gokṣurekṣurabījāni vājigandhā śatāvarī muśalī vānarībījaṃ yaṣṭī nāgabalā balā"},{"type":"verse","number":"26","sanskrit":"एषां चूर्णं दुग्धसिद्धं गव्येनाज्येन भर्जितम् सितया मोदकं कृत्वा भक्ष्यं वाजीकरं परम्","text":"eṣāṃ cūrṇaṃ dugdhasiddhaṃ gavyenājyena bharjitam sitayā modakaṃ kṛtvā bhakṣyaṃ vājīkaraṃ param"},{"type":"verse","number":"27","sanskrit":"चूर्णादष्टगुणं क्षीरं घृतं चूर्णसमं स्मृतम् सर्वतो द्विगुणं खण्डं खादेदग्निबलं यथा","text":"cūrṇādaṣṭaguṇaṃ kṣīraṃ ghṛtaṃ cūrṇasamaṃ smṛtam sarvato dviguṇaṃ khaṇḍaṃ khādedagnibalaṃ yathā"},{"type":"verse","number":"28","sanskrit":"वाजीकराणि भूरीणि संगृह्य रचितो यतः तस्माद्बहुषु योगेषु योगोऽय प्रवरो मतः","text":"vājīkarāṇi bhūrīṇi saṃgṛhya racito yataḥ tasmādbahuṣu yogeṣu yogo'ya pravaro mataḥ"},{"type":"verse","number":"29","sanskrit":"चत्वारो व्योमभागास्तदनु निगदितं भागयुग्मञ्च बङ्गं भागैकं शम्भुबीजं त्रितयमपि मृतं तत्समा सिद्धमूली चातुर्जातं सजातीफलमरिचकणा नागरं देवपुष्पं जातीपत्रञ्च भागद्वितयमपि पृथक्सर्वमेकत्र चूर्ण्यम्","text":"catvāro vyomabhāgāstadanu nigaditaṃ bhāgayugmañca baṅgaṃ bhāgaikaṃ śambhubījaṃ tritayamapi mṛtaṃ tatsamā siddhamūlī cāturjātaṃ sajātīphalamaricakaṇā nāgaraṃ devapuṣpaṃ jātīpatrañca bhāgadvitayamapi pṛthaksarvamekatra cūrṇyam"},{"type":"verse","number":"30","sanskrit":"सर्वद्व्यंशा सिता स्याद् घृतमधुसहितं मोदकीकृत्य चैतत् खादेदग्निं समीक्ष्य प्रसभमभिनवानन्दसम्वर्द्धनाय योगो वाजीकराख्योऽयमिह निगदितो भैरवानन्दनाम्ना निःशेषव्याधिहन्ता दलितबहुवधूद्दामकन्दर्पदर्पः","text":"sarvadvyaṃśā sitā syād ghṛtamadhusahitaṃ modakīkṛtya caitat khādedagniṃ samīkṣya prasabhamabhinavānandasamvarddhanāya yogo vājīkarākhyo'yamiha nigadito bhairavānandanāmnā niḥśeṣavyādhihantā dalitabahuvadhūddāmakandarpadarpaḥ"},{"type":"verse","number":"31","sanskrit":"पिप्पलीलवणोपेते बस्ताण्डे घृतसाधिते कच्छपस्याथवा खादेत्तत्तु वाजीकरं भृशम्","text":"pippalīlavaṇopete bastāṇḍe ghṛtasādhite kacchapasyāthavā khādettattu vājīkaraṃ bhṛśam"},{"type":"verse","number":"32","sanskrit":"पूगं दक्षिणदेशजं दशपलोन्मानं भृशं कर्त्तये त्तत्स्विन्नं जलयोगतो मृदुतरं सङ्कुट्य चूर्णीकृतम् तच्चूर्णं पटशोधितं वसुगुणे गोशुद्धदुग्धे पचेद् द्र व्याज्याञ्जलिसंयुतेऽतिनिबिडे दद्यात्तुलार्द्धां सिताम्","text":"pūgaṃ dakṣiṇadeśajaṃ daśapalonmānaṃ bhṛśaṃ karttaye ttatsvinnaṃ jalayogato mṛdutaraṃ saṅkuṭya cūrṇīkṛtam taccūrṇaṃ paṭaśodhitaṃ vasuguṇe gośuddhadugdhe paced dra vyājyāñjalisaṃyute'tinibiḍe dadyāttulārddhāṃ sitām"},{"type":"verse","number":"33","sanskrit":"पक्वं तज्ज्वलनात्क्षितिं प्रति नयेत्तस्मिन्पुनः प्रक्षिपेद् यद्यत्तत्तदुदाहरामि बहुला दृष्ट्वाऽदरात्संहिताः एला नागबला बला सचपला जातीफला लिङ्गका जातीपत्रसुपत्रपत्रकयुतं तच्च त्वचा संयुतम्","text":"pakvaṃ tajjvalanātkṣitiṃ prati nayettasminpunaḥ prakṣiped yadyattattadudāharāmi bahulā dṛṣṭvā'darātsaṃhitāḥ elā nāgabalā balā sacapalā jātīphalā liṅgakā jātīpatrasupatrapatrakayutaṃ tacca tvacā saṃyutam"},{"type":"verse","number":"34","sanskrit":"विश्वावीरणवारिवारिदवरा वांशी वरी वानरी द्रा क्षा सेक्षुरगोक्षुराऽथ महती खर्जूरिका क्षीरिका धान्याकं सकशेरुकं समधुकं शृङ्गाटकं जीरकं पृथ्वीकाऽथ यवानिका वरटिका मांसी मिसी मेथिका","text":"viśvāvīraṇavārivāridavarā vāṃśī varī vānarī drā kṣā sekṣuragokṣurā'tha mahatī kharjūrikā kṣīrikā dhānyākaṃ sakaśerukaṃ samadhukaṃ śṛṅgāṭakaṃ jīrakaṃ pṛthvīkā'tha yavānikā varaṭikā māṃsī misī methikā"},{"type":"verse","number":"35","sanskrit":"कन्देष्वत्र विदारिकाऽथ मुशली गन्धर्वगन्धा तथा कर्चूरं करिकेशरं समरिचं चारस्य बीजं नवम् बीजं शाल्मलिसम्भवं करिकणाबीजञ्च राजीवजं श्वेतं चन्दनमत्र रक्तमपि च श्रीसंज्ञपुष्पैः समम्","text":"kandeṣvatra vidārikā'tha muśalī gandharvagandhā tathā karcūraṃ karikeśaraṃ samaricaṃ cārasya bījaṃ navam bījaṃ śālmalisambhavaṃ karikaṇābījañca rājīvajaṃ śvetaṃ candanamatra raktamapi ca śrīsaṃjñapuṣpaiḥ samam"},{"type":"verse","number":"36","sanskrit":"सर्वञ्चेति पृथक्पृथक् पलमितं सञ्चूर्ण्य तत्र क्षिपेत् सूतं बङ्गभुजङ्गलोहगगनं सम्मारितं स्वेच्छया कस्तूरीघनसारचूर्णमपि च प्राप्तं यथा प्रक्षिपेत् पश्चादस्य तु मोदकान्विरचयेद् बिल्वप्रमाणानथ","text":"sarvañceti pṛthakpṛthak palamitaṃ sañcūrṇya tatra kṣipet sūtaṃ baṅgabhujaṅgalohagaganaṃ sammāritaṃ svecchayā kastūrīghanasāracūrṇamapi ca prāptaṃ yathā prakṣipet paścādasya tu modakānviracayed bilvapramāṇānatha"},{"type":"verse","number":"37","sanskrit":"तान्भुक्त्वाऽति सदा यथाऽनलबलं भुञ्जीत नाम्लं रसं पूर्वस्मिन्नशिते गते परिणतिं प्राग्भोजनाद्भक्षयेत् नित्यं स्त्रीरतिवल्लभाख्यकमिमं पूगस्य पाकं भजेत् स स्याद्वीर्यविवृद्धिवृद्धमदनो वाजीव शक्तो रतौ","text":"tānbhuktvā'ti sadā yathā'nalabalaṃ bhuñjīta nāmlaṃ rasaṃ pūrvasminnaśite gate pariṇatiṃ prāgbhojanādbhakṣayet nityaṃ strīrativallabhākhyakamimaṃ pūgasya pākaṃ bhajet sa syādvīryavivṛddhivṛddhamadano vājīva śakto ratau"},{"type":"verse","number":"38","sanskrit":"दीप्ताग्निर्बलवान्वलीविरहितो हृष्टः स पुष्टः सदा वृद्धो योऽपि युवेव सोऽपि रुचिरः पूर्णेन्दुवत्सुन्दरः","text":"dīptāgnirbalavānvalīvirahito hṛṣṭaḥ sa puṣṭaḥ sadā vṛddho yo'pi yuveva so'pi ruciraḥ pūrṇenduvatsundaraḥ"},{"type":"verse","number":"39","sanskrit":"एतस्मिन् रतिवल्लभे यदि पुनः सम्यक्खुराशाणिका धत्तूरस्य च बीजमर्ककरभः पोथोऽब्धिशोषस्तथा सन्माजूफलकं तथा खसफलत्वक्कार्षिकान् निक्षिपे च्चूर्णार्द्धा विजया तदा स हि भवेत्कामेश्वरो मोदकः","text":"etasmin rativallabhe yadi punaḥ samyakkhurāśāṇikā dhattūrasya ca bījamarkakarabhaḥ potho'bdhiśoṣastathā sanmājūphalakaṃ tathā khasaphalatvakkārṣikān nikṣipe ccūrṇārddhā vijayā tadā sa hi bhavetkāmeśvaro modakaḥ"},{"type":"verse","number":"40","sanskrit":"रक्तपित्ताधिकारोक्तः खण्डकूष्माण्डको महान् रक्तपित्तादिरोगघ्नो महावाजीकरः स्मृतः","text":"raktapittādhikāroktaḥ khaṇḍakūṣmāṇḍako mahān raktapittādirogaghno mahāvājīkaraḥ smṛtaḥ"},{"type":"verse","number":"41","sanskrit":"पक्वाम्रस्य रसद्रो णे सितामाढकसम्मिताम् घृतं प्रस्थमितं दद्यान्नागरस्य पलाष्टकम्","text":"pakvāmrasya rasadro ṇe sitāmāḍhakasammitām ghṛtaṃ prasthamitaṃ dadyānnāgarasya palāṣṭakam"},{"type":"verse","number":"42","sanskrit":"मरिचं कुडवोन्मानं पिप्पली द्विपलोन्मिता सलिलस्याढकं दत्वा सर्वमेकत्र कारयेत्","text":"maricaṃ kuḍavonmānaṃ pippalī dvipalonmitā salilasyāḍhakaṃ datvā sarvamekatra kārayet"},{"type":"verse","number":"43","sanskrit":"विपचेन्मृण्मये पात्रे दारुदर्व्या प्रचालयेत् चूर्णान्येषां क्षिपेत्तत्र घनीभूतेऽवतारिते","text":"vipacenmṛṇmaye pātre dārudarvyā pracālayet cūrṇānyeṣāṃ kṣipettatra ghanībhūte'vatārite"},{"type":"verse","number":"44","sanskrit":"धान्यकं जीरकं पथ्यां चित्रकं मुस्तकं त्वचम् बृहज्जीरकमप्यत्र ग्रन्थिकं नागकेशरम्","text":"dhānyakaṃ jīrakaṃ pathyāṃ citrakaṃ mustakaṃ tvacam bṛhajjīrakamapyatra granthikaṃ nāgakeśaram"},{"type":"verse","number":"45","sanskrit":"एलाबीजं लवङ्गञ्च पृथग्जाती पलम्पलम् सिद्धं शीते प्रदद्याच्च मधुनः कुडवद्वयम्","text":"elābījaṃ lavaṅgañca pṛthagjātī palampalam siddhaṃ śīte pradadyācca madhunaḥ kuḍavadvayam"},{"type":"verse","number":"46","sanskrit":"भक्षयेद्भोजनादर्वाक्पलमात्रमिदं नरः अथवा नियता नात्र मात्रां खादेद्यथाऽनलम्","text":"bhakṣayedbhojanādarvākpalamātramidaṃ naraḥ athavā niyatā nātra mātrāṃ khādedyathā'nalam"},{"type":"verse","number":"47","sanskrit":"मानवः सेवनादस्य वाजीव सुरते भवेत् समर्थो बलवान्पुष्टो नित्यं स स्यान्निरामयः","text":"mānavaḥ sevanādasya vājīva surate bhavet samartho balavānpuṣṭo nityaṃ sa syānnirāmayaḥ"},{"type":"verse","number":"48","sanskrit":"ग्रहणीं नाशयेदेष क्षयं श्वासमरोचकम् अम्लपित्तं महाश्वासं रक्तपित्तञ्च पाण्डुताम्","text":"grahaṇīṃ nāśayedeṣa kṣayaṃ śvāsamarocakam amlapittaṃ mahāśvāsaṃ raktapittañca pāṇḍutām"},{"type":"verse","number":"49","sanskrit":"शमयति गोक्षुर चूर्णं छाग क्षीरेण साधितं समधु भुक्तं क्षपयति षण्ढ्यं यज्जनितं कुप्रयोगेण","text":"śamayati gokṣura cūrṇaṃ chāga kṣīreṇa sādhitaṃ samadhu bhuktaṃ kṣapayati ṣaṇḍhyaṃ yajjanitaṃ kuprayogeṇa"},{"type":"verse","number":"50","sanskrit":"द्र व्याणि चन्दनादेस्तु चन्दनं रक्तचन्दनम् पत्तङ्गमथ कालीयागुरुकृष्णागुरूणि च","text":"dra vyāṇi candanādestu candanaṃ raktacandanam pattaṅgamatha kālīyāgurukṛṣṇāgurūṇi ca"},{"type":"verse","number":"51","sanskrit":"देवद्रुमः ससरलः पद्मकं तूणिकोऽपि च कर्पूरो मृगनाभिश्च लता कस्तूरिकाऽपि च","text":"devadrumaḥ sasaralaḥ padmakaṃ tūṇiko'pi ca karpūro mṛganābhiśca latā kastūrikā'pi ca"},{"type":"verse","number":"52","sanskrit":"सिह्लिकः कुङ्कमं नव्यं जातीफलकमेव च जातीपत्रं लवङ्गञ्च सूक्ष्मैला महती च सा","text":"sihlikaḥ kuṅkamaṃ navyaṃ jātīphalakameva ca jātīpatraṃ lavaṅgañca sūkṣmailā mahatī ca sā"},{"type":"verse","number":"53","sanskrit":"कङ्कोलफलकं त्वक्च पत्रकं नागकेशरम् बालकञ्च तथोशीरं मांसी दारुसिताऽपि वा","text":"kaṅkolaphalakaṃ tvakca patrakaṃ nāgakeśaram bālakañca tathośīraṃ māṃsī dārusitā'pi vā"},{"type":"verse","number":"54","sanskrit":"मुरा कर्पूरकश्चापि शैलेयं भद्र मुस्तकम् रेणुका च प्रियङ्गुश्च श्रीवासो गुग्गुलुस्तथा","text":"murā karpūrakaścāpi śaileyaṃ bhadra mustakam reṇukā ca priyaṅguśca śrīvāso guggulustathā"},{"type":"verse","number":"55","sanskrit":"लाक्षा नखश्च रालश्च धातकीकुसुमं तथा ग्रन्थिपर्णञ्च मञ्जिष्ठा तगरं सिक्थकं तथा","text":"lākṣā nakhaśca rālaśca dhātakīkusumaṃ tathā granthiparṇañca mañjiṣṭhā tagaraṃ sikthakaṃ tathā"},{"type":"verse","number":"56","sanskrit":"एतानि शाणमानानि कल्कीकृत्य शनैः पचेत् तैलं प्रस्थमितं सम्यगेतत्पात्रे शुभे क्षिपेत्","text":"etāni śāṇamānāni kalkīkṛtya śanaiḥ pacet tailaṃ prasthamitaṃ samyagetatpātre śubhe kṣipet"},{"type":"verse","number":"57","sanskrit":"अनेनाभ्यक्तगात्रस्तु वृद्धोऽशीतिसमोऽपि सः युवा भवति शुक्राढ्यः स्त्रीणामत्यन्तवल्लभः","text":"anenābhyaktagātrastu vṛddho'śītisamo'pi saḥ yuvā bhavati śukrāḍhyaḥ strīṇāmatyantavallabhaḥ"},{"type":"verse","number":"58","sanskrit":"वन्ध्याऽपि लभते गर्भं वृद्धोऽपि तरुणायते अपुत्रः पुत्रमाप्नोति जीवेच्च शरदां शतम्","text":"vandhyā'pi labhate garbhaṃ vṛddho'pi taruṇāyate aputraḥ putramāpnoti jīvecca śaradāṃ śatam"},{"type":"verse","number":"59","sanskrit":"चन्दनादि महातैलं रक्तपित्तं क्षयं ज्वरम् दाहं प्रस्वेददौर्गन्ध्यं कुष्ठं कण्डूं विनाशयेत्","text":"candanādi mahātailaṃ raktapittaṃ kṣayaṃ jvaram dāhaṃ prasvedadaurgandhyaṃ kuṣṭhaṃ kaṇḍūṃ vināśayet"},{"type":"verse","number":"60","sanskrit":"दशमूलं कणा वह्निः कपित्थञ्च विभीतकम् कट्फलं मरिचं विश्वमूलं पिप्पलिसैन्धवम्","text":"daśamūlaṃ kaṇā vahniḥ kapitthañca vibhītakam kaṭphalaṃ maricaṃ viśvamūlaṃ pippalisaindhavam"},{"type":"verse","number":"61","sanskrit":"रक्तरोहीतकं दन्ती द्रा क्षाजाजिनिशाद्बयम् धात्रीजन्तुघ्नशिखरि शृङ्गीदारुपुनर्नवाः","text":"raktarohītakaṃ dantī drā kṣājājiniśādbayam dhātrījantughnaśikhari śṛṅgīdārupunarnavāḥ"},{"type":"verse","number":"62","sanskrit":"धान्याकं देवकुसुमं राजवृक्षस्त्रिकण्टकम् वृद्धदारुकुबेराक्ष्यौ मूलं वीरणिकाभवम्","text":"dhānyākaṃ devakusumaṃ rājavṛkṣastrikaṇṭakam vṛddhadārukuberākṣyau mūlaṃ vīraṇikābhavam"},{"type":"verse","number":"63","sanskrit":"एतेषां पलयुग्मन्तु भेषजानां पृथक्पृथक् आढकञ्चापि पथ्यायास्तोये पञ्चाढके पचेत्","text":"eteṣāṃ palayugmantu bheṣajānāṃ pṛthakpṛthak āḍhakañcāpi pathyāyāstoye pañcāḍhake pacet"},{"type":"verse","number":"64","sanskrit":"स्विन्ना पथ्या भवेद्यावत्पश्चान्मधु विनिक्षिपेत् गुरूपदेशाद्विधिवत्त्रिदिनञ्च ततः परम्","text":"svinnā pathyā bhavedyāvatpaścānmadhu vinikṣipet gurūpadeśādvidhivattridinañca tataḥ param"},{"type":"verse","number":"65","sanskrit":"पुनः क्षिपेत्पञ्चदिनं तथा च दशवासरम् संसिद्धा चाभया पश्चाद् घृतभाण्डे निधापयेत्","text":"punaḥ kṣipetpañcadinaṃ tathā ca daśavāsaram saṃsiddhā cābhayā paścād ghṛtabhāṇḍe nidhāpayet"},{"type":"verse","number":"66","sanskrit":"विमले सुदृढे क्षौद्र परिपूर्णेप्रयत्नतः पश्चात्पूर्वोक्तकाण्डे तु क्षिपेद् बुद्धिपरायणः","text":"vimale sudṛḍhe kṣaudra paripūrṇeprayatnataḥ paścātpūrvoktakāṇḍe tu kṣiped buddhiparāyaṇaḥ"},{"type":"verse","number":"67","sanskrit":"एषा हरीतकी चैव धन्वन्तरि कृता शुभा भक्षयेद्यो नरो नित्यं रोगा नश्यन्ति सर्वशः","text":"eṣā harītakī caiva dhanvantari kṛtā śubhā bhakṣayedyo naro nityaṃ rogā naśyanti sarvaśaḥ"},{"type":"verse","number":"68","sanskrit":"श्वासं कासं क्षयं पाण्डु हिक्का छर्दिमदभ्रमान् मुखरोगं तथा तृष्णामरुचिं वह्निमन्दताम्","text":"śvāsaṃ kāsaṃ kṣayaṃ pāṇḍu hikkā chardimadabhramān mukharogaṃ tathā tṛṣṇāmaruciṃ vahnimandatām"},{"type":"verse","number":"69","sanskrit":"यकृत्प्लीहोदरञ्चैव वातरक्तं सुदारुणम् शिरोऽक्षिकर्णजां पीडां तथा बद्धगुदोदरम्","text":"yakṛtplīhodarañcaiva vātaraktaṃ sudāruṇam śiro'kṣikarṇajāṃ pīḍāṃ tathā baddhagudodaram"},{"type":"verse","number":"70","sanskrit":"ग्रहणीं दुर्विकाराञ्च शेषं दोषत्रयोद्भवम् मधुपक्वेति विख्याता हन्ति रोगाननेकशः","text":"grahaṇīṃ durvikārāñca śeṣaṃ doṣatrayodbhavam madhupakveti vikhyātā hanti rogānanekaśaḥ"},{"type":"verse","number":"71","sanskrit":"बीजानि तु कपिकच्छ्वाः कुडवमितानि च स्वेदयेच्छनकैः प्रस्थे गोभवदुग्धे तावद् यावद् भवेद् गाढम्","text":"bījāni tu kapikacchvāḥ kuḍavamitāni ca svedayecchanakaiḥ prasthe gobhavadugdhe tāvad yāvad bhaved gāḍham"},{"type":"verse","number":"72","sanskrit":"त्वग्रहितानि च कृत्वा सूक्ष्मं सम्पेषयेत्तानि पिष्टिकया लघुवटिकाः कृत्वा गव्ये पचेदाज्ये ६२ द्विगुणितशर्करया ता वटिकाः सम्पक्वया लेप्याः वटिका माक्षिकमध्ये मज्जनयोग्येऽखिलाः स्थाप्याः","text":"tvagrahitāni ca kṛtvā sūkṣmaṃ sampeṣayettāni piṣṭikayā laghuvaṭikāḥ kṛtvā gavye pacedājye 62 dviguṇitaśarkarayā tā vaṭikāḥ sampakvayā lepyāḥ vaṭikā mākṣikamadhye majjanayogye'khilāḥ sthāpyāḥ"},{"type":"verse","number":"73","sanskrit":"पञ्चटङ्कमितास्तास्तु प्रातः सायञ्च भक्षयेत् अनेन शीघ्रद्रा वी यो यश्च स्यात्पतितध्वजः","text":"pañcaṭaṅkamitāstāstu prātaḥ sāyañca bhakṣayet anena śīghradrā vī yo yaśca syātpatitadhvajaḥ"},{"type":"verse","number":"74","sanskrit":"सोऽपि प्रात्नोति सुरते सामर्थ्यमति वाजिवत् नानेन सदृशं किञ्चिद् द्र व्यं वाजीकरं परम्","text":"so'pi prātnoti surate sāmarthyamati vājivat nānena sadṛśaṃ kiñcid dra vyaṃ vājīkaraṃ param"},{"type":"verse","number":"75","sanskrit":"आकारकरभः शुण्ठी लवङ्गं कुङ्कुमं कणा जातीफलं जातिपुष्पं चन्दनं कार्षिकं पृथक्","text":"ākārakarabhaḥ śuṇṭhī lavaṅgaṃ kuṅkumaṃ kaṇā jātīphalaṃ jātipuṣpaṃ candanaṃ kārṣikaṃ pṛthak"},{"type":"verse","number":"76","sanskrit":"चूर्णयेदहिफेनन्तु तत्र दद्यात्पलोन्मितम् सर्वमेकीकृतं माषमात्रं क्षौद्रे ण भक्षयेत्","text":"cūrṇayedahiphenantu tatra dadyātpalonmitam sarvamekīkṛtaṃ māṣamātraṃ kṣaudre ṇa bhakṣayet"},{"type":"verse","number":"77","sanskrit":"शुक्रस्तम्भकरं पुंसामिदमानन्दकारकम् नारीणां प्रीतिजननं सेवेत निशि कामुकः","text":"śukrastambhakaraṃ puṃsāmidamānandakārakam nārīṇāṃ prītijananaṃ seveta niśi kāmukaḥ"},{"type":"verse","number":"78","sanskrit":"इति द्विसप्ततितमो वाजीकरणाधिकारः समाप्तः ७२","text":"iti dvisaptatitamo vājīkaraṇādhikāraḥ samāptaḥ 72"}]},{"sthana":"Уттаракханда","number":72,"lang":"sa","content":[{"type":"heading","heading":"Расаяна — омоложение"},{"type":"verse","number":"1","sanskrit":"यज्जराव्याधिविध्वंसि वयः स्तम्भकरं तथा चक्षुष्यं बृंहणं वृष्यं भेषजं तद्र सायनम्","text":"yajjarāvyādhividhvaṃsi vayaḥ stambhakaraṃ tathā cakṣuṣyaṃ bṛṃhaṇaṃ vṛṣyaṃ bheṣajaṃ tadra sāyanam"},{"type":"verse","number":"2","sanskrit":"दीर्घमायुः स्मृतिं मेधामारोग्यं तरुणं वयः देहेन्द्रि यबलं कान्तिं नरो विन्देद्र्रसायनात्","text":"dīrghamāyuḥ smṛtiṃ medhāmārogyaṃ taruṇaṃ vayaḥ dehendri yabalaṃ kāntiṃ naro vindedrrasāyanāt"},{"type":"verse","number":"3","sanskrit":"नाविशुद्धशरीरस्य युक्तो रासायनो विधिः न भाति वाससि म्लिष्टे रङ्गयोग इवार्पितः","text":"nāviśuddhaśarīrasya yukto rāsāyano vidhiḥ na bhāti vāsasi mliṣṭe raṅgayoga ivārpitaḥ"},{"type":"verse","number":"4","sanskrit":"शीतोदकं पयः क्षौद्रं घृतमेकैकशो हितम् त्रिशः समस्तमथवा प्राक्पीतं स्थापयेद्वयः","text":"śītodakaṃ payaḥ kṣaudraṃ ghṛtamekaikaśo hitam triśaḥ samastamathavā prākpītaṃ sthāpayedvayaḥ"},{"type":"verse","number":"5","sanskrit":"मण्डूकपर्ण्या स्वरसः प्रयोज्यः क्षीरेण यष्टीमधुकस्य चूर्णम् रसो गुडूच्यास्तु समूलपुष्पः कल्कः प्रयोज्यः खलु शङ्खपुष्प्याः","text":"maṇḍūkaparṇyā svarasaḥ prayojyaḥ kṣīreṇa yaṣṭīmadhukasya cūrṇam raso guḍūcyāstu samūlapuṣpaḥ kalkaḥ prayojyaḥ khalu śaṅkhapuṣpyāḥ"},{"type":"verse","number":"6","sanskrit":"आयुः प्रदान्यामयनाशनानि बलाग्निवर्णस्वरवर्द्धनानि मेध्यानि चैतानि रसायनानि मेध्या विशेषेण च शङ्खपुष्पी","text":"āyuḥ pradānyāmayanāśanāni balāgnivarṇasvaravarddhanāni medhyāni caitāni rasāyanāni medhyā viśeṣeṇa ca śaṅkhapuṣpī"},{"type":"verse","number":"7","sanskrit":"माक्षिकेण तुगाक्षीरी पिप्पल्या लवणेन च त्रिफला सितया वाऽपि युक्ता सिद्धं रसायनम्","text":"mākṣikeṇa tugākṣīrī pippalyā lavaṇena ca triphalā sitayā vā'pi yuktā siddhaṃ rasāyanam"},{"type":"verse","number":"8","sanskrit":"सिन्धूत्थशर्कराशुण्ठीकणामधुगुडैः क्रमात् वर्षाऽदिष्वभया प्राश्या रसायनगुणैषिणा","text":"sindhūtthaśarkarāśuṇṭhīkaṇāmadhuguḍaiḥ kramāt varṣā'diṣvabhayā prāśyā rasāyanaguṇaiṣiṇā"},{"type":"verse","number":"9","sanskrit":"पुनर्नवस्यार्द्धपलं नवस्य पिष्टं पिबेद्यः पयसाऽद्धमासम् मासत्रयं तत्त्रिगुणं समं वा जीर्णोऽपि भूयः स पुनर्नवः स्यात् ये मासमेकं स्वरसं पिबन्ति दिने दिने भृङ्गरजःसमुत्थम् क्षीराशिनस्ते बलवीर्ययुक्ताः समाः शतं जीवनमाप्नुवन्ति","text":"punarnavasyārddhapalaṃ navasya piṣṭaṃ pibedyaḥ payasā'ddhamāsam māsatrayaṃ tattriguṇaṃ samaṃ vā jīrṇo'pi bhūyaḥ sa punarnavaḥ syāt ye māsamekaṃ svarasaṃ pibanti dine dine bhṛṅgarajaḥsamuttham kṣīrāśinaste balavīryayuktāḥ samāḥ śataṃ jīvanamāpnuvanti"},{"type":"verse","number":"10","sanskrit":"शतावरी मुण्डितिका गुडूची सहस्तिकर्णा सहतालमूली एंतानि कृत्वा समभागयुक्तान्याज्येन किं वा मधुनाऽवलिह्यात्","text":"śatāvarī muṇḍitikā guḍūcī sahastikarṇā sahatālamūlī eṃtāni kṛtvā samabhāgayuktānyājyena kiṃ vā madhunā'valihyāt"},{"type":"verse","number":"11","sanskrit":"जरारुजामृत्युवियुक्तदेहो भवेन्नरो वीर्यबलादियुक्तः विभाति देवप्रतिमः स नित्यं प्रभामयो भूरिविवृद्धियुक्तः","text":"jarārujāmṛtyuviyuktadeho bhavennaro vīryabalādiyuktaḥ vibhāti devapratimaḥ sa nityaṃ prabhāmayo bhūrivivṛddhiyuktaḥ"},{"type":"verse","number":"12","sanskrit":"पीत्वाऽश्वगन्धां पयसाऽद्धमासं घृतेन तैलेन सुखाम्बुना वा वीर्यस्य पुष्टिं वपुषो विधत्ते बालस्य वृक्षस्य यथाऽम्बुवृष्टिः","text":"pītvā'śvagandhāṃ payasā'ddhamāsaṃ ghṛtena tailena sukhāmbunā vā vīryasya puṣṭiṃ vapuṣo vidhatte bālasya vṛkṣasya yathā'mbuvṛṣṭiḥ"},{"type":"verse","number":"13","sanskrit":"अयः पलं गुग्गुलुमत्र योज्यं पलत्रयं व्योषपलानि पञ्च पलानि चाष्टौ त्रिफलारजश्च कर्षं लिहन्यात्यमरत्वमेव","text":"ayaḥ palaṃ guggulumatra yojyaṃ palatrayaṃ vyoṣapalāni pañca palāni cāṣṭau triphalārajaśca karṣaṃ lihanyātyamaratvameva"},{"type":"verse","number":"14","sanskrit":"न केवलं दीर्घमिहायुरश्नुते रसायनं यो विधिवन्निषेवते गतिं स देवर्षिनिषेवितां शुभां प्रपद्यते ब्रह्म तथैव चाक्षरम्","text":"na kevalaṃ dīrghamihāyuraśnute rasāyanaṃ yo vidhivanniṣevate gatiṃ sa devarṣiniṣevitāṃ śubhāṃ prapadyate brahma tathaiva cākṣaram"},{"type":"verse","number":"15","sanskrit":"इति त्रिसप्ततितमो रसायनाधिकारः समाप्तः ७३ ग्रन्थकर्त्तृशुभाशीः शंसनम् यावद् व्योमनि बिम्बमम्बरमणेरिन्दोश्च विद्योतते यावत् सप्त पयोधयःसगिरयस्तिष्ठन्ति पृष्ठे भुवः यावच्चावनिमण्डलं फणिपतेरास्ते फणामण्डले तावत्सद्भिषजः पठन्तु परितो भावप्रकाशं शुभम्","text":"iti trisaptatitamo rasāyanādhikāraḥ samāptaḥ 73 granthakarttṛśubhāśīḥ śaṃsanam yāvad vyomani bimbamambaramaṇerindośca vidyotate yāvat sapta payodhayaḥsagirayastiṣṭhanti pṛṣṭhe bhuvaḥ yāvaccāvanimaṇḍalaṃ phaṇipaterāste phaṇāmaṇḍale tāvatsadbhiṣajaḥ paṭhantu parito bhāvaprakāśaṃ śubham"},{"type":"verse","number":"16","sanskrit":"ग्रन्थस्यास्याध्यापकनाञ्जनानां मध्ये नॄणामादरं कुर्वतां च श्रीसोमेशादित्यविप्रप्रसादादायुर्दीर्घं सौख्यमास्तां सदैव","text":"granthasyāsyādhyāpakanāñjanānāṃ madhye nṝṇāmādaraṃ kurvatāṃ ca śrīsomeśādityavipraprasādādāyurdīrghaṃ saukhyamāstāṃ sadaiva"},{"type":"verse","number":"17","sanskrit":"समाप्तमिदमुत्तरखण्डम् समाप्तश्चायं ग्रन्थः","text":"samāptamidamuttarakhaṇḍam samāptaścāyaṃ granthaḥ"}]}];
